<#
.SYNOPSIS
    PC-Tools für Windows 11 - Aufräumen, Optimieren, Updates (Windows, Treiber, Programme)
    mit grafischer Oberfläche und geplanter Aufgabe.
.DESCRIPTION
    GUI:        PCPflege.ps1              (fordert Adminrechte an)
    Automatik:  PCPflege.ps1 -Auto        (von der geplanten Aufgabe "PC-Tools" als SYSTEM)
    Hintergrund: PCPflege.ps1 -Run ...    (von der Oberfläche gestartet - läuft weiter, auch wenn das Fenster geschlossen wird)
    Daten:      C:\ProgramData\PCPflege   (config.json, lastrun.json, Logs\)
#>
[CmdletBinding()]
param([switch]$Auto, [switch]$Run, [string]$Parts = '', [switch]$Analyze, [switch]$CheckOnly, [string]$RunId = '', [string]$AppsFile = '', [string]$WingetFile = '', [string]$DirectFile = '', [string]$Monitor = '', [switch]$DeskArrange, [string]$Topology = '', [int]$Delay = 0, [switch]$Silent, [switch]$Install, [string]$JobFile = '', [switch]$Backup, [switch]$FleetPoll, [string]$FirstLogon = '', [switch]$NetDiag, [switch]$TbSync, [switch]$WinRepair, [switch]$NetDeep, [string]$DeepOpts = '', [switch]$FullBackup, [switch]$FullRepair, [switch]$NetDoc, [switch]$Sign, [string]$SignOpts = '', [string]$ChocoFile = '')

$AppVersion = '14.3.2'
$DefaultUpdateSource = 'github:rhedv42-sudo/pc-tools@stable'
# Portabel (USB-Stick): Datei portable.txt neben dem Skript -> Einstellungen/Protokolle im Ordner Daten auf dem Stick
$Script:IsPortable = [bool]($PSScriptRoot -and (Test-Path -LiteralPath (Join-Path $PSScriptRoot 'portable.txt')))
if ($Script:IsPortable) { $env:PCPFLEGE_DATA = Join-Path $PSScriptRoot 'Daten' }
$DataDir    = if ($env:PCPFLEGE_DATA) { $env:PCPFLEGE_DATA } else { Join-Path $env:ProgramData 'PCPflege' }
# Lite-Ansicht: Datei lite.txt neben dem Skript bzw. im Datenordner
$Script:IsLite = [bool](($PSScriptRoot -and (Test-Path -LiteralPath (Join-Path $PSScriptRoot 'lite.txt'))) -or (Test-Path -LiteralPath (Join-Path $DataDir 'lite.txt')))
$ConfigFile = Join-Path $DataDir 'config.json'
$TaskName   = 'PC-Pflege'
New-Item -Path $DataDir -ItemType Directory -Force -ErrorAction SilentlyContinue | Out-Null

# =====================================================================
#  ENGINE (läuft im Hintergrund-Runspace bzw. im Automatik-Modus)
# =====================================================================
$EngineText = @'
$ErrorActionPreference = 'Continue'
$Script:DataDir   = if ($env:PCPFLEGE_DATA) { $env:PCPFLEGE_DATA } else { Join-Path $env:ProgramData 'PCPflege' }
$Script:LogDir    = Join-Path $Script:DataDir 'Logs'
$Script:DryRun    = $false
$Script:CheckOnly = $false
$Script:Freed     = [int64]0
$Script:RebootNeeded     = $false
$Script:UpdatesInstalled = 0
$Script:Warnings  = 0
$Script:LogFile   = $null
$Script:StatusFile = $null
$Script:RunId = ''
$Script:ScriptDir = ''
$Script:NiniteApps = @()
$Script:WingetApps = @()
$Script:ChocoApps = @()
$Script:SysClass = $null
$Script:DirectApps = @()
$Script:IsAuto = $false
$Script:StepName = ''; $Script:StepStart = $null; $Script:StepNo = 0; $Script:StepCount = 0
$Script:Detail = ''; $Script:LastLine = ''; $Script:StatusText = ''
$Script:BeatSw = [Diagnostics.Stopwatch]::StartNew()
$Script:Captured = [System.Collections.Generic.List[string]]::new()
$Script:ExplorerMissingSince = $null
$Script:ExplorerCheck = [Diagnostics.Stopwatch]::StartNew()
$Script:CancelFile = $null
try { [Console]::OutputEncoding = [Text.Encoding]::UTF8 } catch { }

function Write-PLog {
    param([string]$Msg, [string]$Level = 'INFO')
    if ($Level -in 'WARN', 'FEHLER') { $Script:Warnings++ }
    $line = '{0:HH:mm:ss} [{1,-6}] {2}' -f (Get-Date), $Level, $Msg
    if ($Script:LogFile) { try { Add-Content -Path $Script:LogFile -Value $line -Encoding UTF8 } catch { } }
    if ($null -ne $sync) { $sync.Queue.Enqueue($line) } else { Write-Host $line }
    $t = $Msg.Trim(); if ($t -and $t -notmatch '^(=====|---)') { $Script:LastLine = $t }
    Update-PHeartbeat
}
$Script:Progress = 0
function Set-PStatus {
    param([string]$Text, [int]$Pct = -1, [bool]$Running = $true)
    if ($Pct -ge 0) { $Script:Progress = $Pct }
    $Script:StatusText = $Text
    if ($null -ne $sync) { $sync.Status = $Text; $sync.Progress = $Script:Progress }
    if ($Script:StatusFile) {
        try {
            @{
                Status = $Text; Progress = $Script:Progress; Running = $Running; Pid = $PID; RunId = $Script:RunId
                Step = $Script:StepName; StepNo = $Script:StepNo; StepCount = $Script:StepCount
                StepStart = $(if ($Script:StepStart) { $Script:StepStart.ToString('o') } else { '' })
                Detail = $Script:Detail; LastLine = $Script:LastLine; Beat = (Get-Date).ToString('o')
            } | ConvertTo-Json -Compress | Set-Content -Path $Script:StatusFile -Encoding UTF8
        } catch { }
    }
    $Script:BeatSw.Restart()
}
# Lebenszeichen für die Oberfläche (höchstens 1x pro Sekunde)
function Update-PHeartbeat {
    if ($Script:StatusFile -and $Script:BeatSw.Elapsed.TotalMilliseconds -ge 1000) { Set-PStatus $Script:StatusText }
}
function Test-PCancel {
    if ($null -ne $sync -and [bool]$sync.Cancel) { return $true }
    if ($Script:CancelFile -and [IO.File]::Exists($Script:CancelFile)) { return $true }
    return $false
}
function Format-Bytes {
    param([int64]$Bytes)
    if ($Bytes -ge 1GB) { return ('{0:N2} GB' -f ($Bytes / 1GB)) }
    if ($Bytes -ge 1MB) { return ('{0:N1} MB' -f ($Bytes / 1MB)) }
    return ('{0:N0} KB' -f ($Bytes / 1KB))
}
function Get-FreeBytes {
    try { return [int64](New-Object System.IO.DriveInfo $env:SystemDrive).AvailableFreeSpace } catch { return [int64]0 }
}
function Test-PendingReboot {
    return ((Test-Path 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Component Based Servicing\RebootPending') -or
            (Test-Path 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\WindowsUpdate\Auto Update\RebootRequired'))
}
function Get-ProfilePaths {
    @(Get-CimInstance Win32_UserProfile -ErrorAction SilentlyContinue |
      Where-Object { -not $_.Special -and $_.LocalPath -and (Test-Path -LiteralPath $_.LocalPath) } |
      ForEach-Object { $_.LocalPath })
}

# Löscht Dateien älter als X Tage; folgt keinen Verknüpfungen/Junctions; gesperrte Dateien werden übersprungen
function Remove-OldFiles {
    param([string]$Path, [int]$Days = 0, [string]$Filter = '*', [switch]$Recurse)
    $sum = [int64]0
    if (-not $Path -or -not [IO.Directory]::Exists($Path)) { return $sum }
    $limit = (Get-Date).AddDays(-$Days)
    $dirs  = [System.Collections.Generic.List[string]]::new()
    $stack = New-Object System.Collections.Stack
    $stack.Push($Path)
    while ($stack.Count -gt 0) {
        if (Test-PCancel) { break }
        $d  = [string]$stack.Pop()
        $di = New-Object System.IO.DirectoryInfo $d
        $files = @(); try { $files = $di.GetFiles($Filter) } catch { }
        foreach ($f in $files) {
            if ($f.Name -eq 'desktop.ini' -or $f.LastWriteTime -ge $limit) { continue }
            $len = $f.Length
            if ($Script:DryRun) { $sum += $len; continue }
            try { if ($f.IsReadOnly) { $f.IsReadOnly = $false }; $f.Delete(); $sum += $len } catch { }
        }
        if ($Recurse) {
            $subs = @(); try { $subs = $di.GetDirectories() } catch { }
            foreach ($s in $subs) {
                if ($s.Attributes -band [IO.FileAttributes]::ReparsePoint) { continue }
                $stack.Push($s.FullName); $dirs.Add($s.FullName)
            }
        }
    }
    if ($Recurse -and -not $Script:DryRun) {
        foreach ($x in ($dirs | Sort-Object Length -Descending)) {
            try {
                if ([IO.Directory]::GetLastWriteTime($x) -lt $limit -and
                    -not [IO.Directory]::EnumerateFileSystemEntries($x).GetEnumerator().MoveNext()) {
                    [IO.Directory]::Delete($x, $false)
                }
            } catch { }
        }
    }
    return $sum
}

function Invoke-CleanStep {
    param([string]$Name, [scriptblock]$Action)
    $r = $null
    try { $r = & $Action } catch { Write-PLog ('{0}: {1}' -f $Name, $_.Exception.Message) 'WARN'; return }
    $b = [int64](@($r) | Where-Object { $_ -is [ValueType] } | Measure-Object -Sum).Sum
    $Script:Freed += $b
    $verb = if ($Script:DryRun) { 'möglich' } else { 'freigegeben' }
    Write-PLog ('{0}: {1} {2}' -f $Name, (Format-Bytes $b), $verb) 'OK'
}

# ------------------------------------------------------------------ AUFRÄUMEN
function Clear-UserTemp {
    $d = [int]$Script:Cfg.Clean.UserTempDays
    foreach ($p in Get-ProfilePaths) { Remove-OldFiles -Path (Join-Path $p 'AppData\Local\Temp') -Days $d -Recurse }
}
function Clear-WinTemp { Remove-OldFiles -Path (Join-Path $env:SystemRoot 'Temp') -Days ([int]$Script:Cfg.Clean.WinTempDays) -Recurse }
function Clear-WUCache {
    $path = Join-Path $env:SystemRoot 'SoftwareDistribution\Download'
    if ($Script:DryRun) { return (Remove-OldFiles -Path $path -Recurse) }
    if (Test-PendingReboot) { Write-PLog 'Update-Cache: Neustart ausstehend - übersprungen'; return [int64]0 }
    $svc = 'wuauserv', 'bits'
    foreach ($s in $svc) { Stop-Service -Name $s -Force -ErrorAction SilentlyContinue }
    try { Remove-OldFiles -Path $path -Recurse }
    finally { foreach ($s in $svc) { Start-Service -Name $s -ErrorAction SilentlyContinue } }
}
function Clear-DeliveryOpt {
    $path = Join-Path $env:SystemRoot 'ServiceProfiles\NetworkService\AppData\Local\Microsoft\Windows\DeliveryOptimization\Cache'
    $size = [int64](Get-ChildItem -LiteralPath $path -Recurse -File -Force -ErrorAction SilentlyContinue | Measure-Object Length -Sum).Sum
    if ($Script:DryRun) { return $size }
    try { Delete-DeliveryOptimizationCache -Force -ErrorAction Stop | Out-Null }
    catch { Write-PLog ('Übermittlungsoptimierung: {0}' -f $_.Exception.Message) 'WARN'; return [int64]0 }
    return $size
}
function Clear-RecycleBins {
    $limit = (Get-Date).AddDays(-[int]$Script:Cfg.Clean.RecycleBinDays)
    foreach ($drv in (Get-CimInstance Win32_LogicalDisk -Filter 'DriveType=3' -ErrorAction SilentlyContinue)) {
        $rb = Join-Path ($drv.DeviceID + '\') '$Recycle.Bin'
        if (-not [IO.Directory]::Exists($rb)) { continue }
        $sidDirs = @(); try { $sidDirs = [IO.Directory]::GetDirectories($rb) } catch { }
        foreach ($sidDir in $sidDirs) {
            foreach ($i in (Get-ChildItem -LiteralPath $sidDir -Filter '$I*' -Force -File -ErrorAction SilentlyContinue)) {
                if ($i.LastWriteTime -ge $limit) { continue }
                $r = Join-Path $sidDir ('$R' + $i.Name.Substring(2))
                $size = [int64]0
                if ([IO.File]::Exists($r)) { $size = (New-Object IO.FileInfo $r).Length }
                elseif ([IO.Directory]::Exists($r)) { $size = [int64](Get-ChildItem -LiteralPath $r -Recurse -File -Force -ErrorAction SilentlyContinue | Measure-Object Length -Sum).Sum }
                if ($Script:DryRun) { $size; continue }
                try {
                    if ([IO.Directory]::Exists($r)) { & cmd.exe /c ('rd /s /q "{0}"' -f $r) 2>&1 | Out-Null }
                    elseif ([IO.File]::Exists($r)) { Remove-Item -LiteralPath $r -Force -ErrorAction Stop }
                    Remove-Item -LiteralPath $i.FullName -Force -ErrorAction Stop
                    $size
                } catch { }
            }
        }
    }
}
function Clear-ThumbCache {
    foreach ($p in Get-ProfilePaths) { Remove-OldFiles -Path (Join-Path $p 'AppData\Local\Microsoft\Windows\Explorer') -Filter 'thumbcache_*.db' }
}
function Clear-ErrorReports {
    $days  = [int]$Script:Cfg.Clean.WERDays
    $paths = @(
        (Join-Path $env:ProgramData 'Microsoft\Windows\WER\ReportArchive'),
        (Join-Path $env:ProgramData 'Microsoft\Windows\WER\ReportQueue'),
        (Join-Path $env:ProgramData 'Microsoft\Windows\WER\Temp'),
        (Join-Path $env:SystemRoot 'Minidump'),
        (Join-Path $env:SystemRoot 'LiveKernelReports')
    )
    foreach ($p in Get-ProfilePaths) {
        $paths += (Join-Path $p 'AppData\Local\CrashDumps')
        $paths += (Join-Path $p 'AppData\Local\Microsoft\Windows\WER')
    }
    foreach ($x in $paths) { Remove-OldFiles -Path $x -Days $days -Recurse }
    $mem = Join-Path $env:SystemRoot 'MEMORY.DMP'
    if ([IO.File]::Exists($mem)) {
        $fi = New-Object IO.FileInfo $mem
        if ($fi.LastWriteTime -lt (Get-Date).AddDays(-$days)) {
            if ($Script:DryRun) { $fi.Length } else { try { $l = $fi.Length; $fi.Delete(); $l } catch { } }
        }
    }
}
function Clear-OldLogs {
    $days = [int]$Script:Cfg.Clean.OldLogsDays
    $logs = Join-Path $env:SystemRoot 'Logs'
    Remove-OldFiles -Path (Join-Path $logs 'CBS') -Days $days -Filter '*.cab'
    Remove-OldFiles -Path (Join-Path $logs 'CBS') -Days $days -Filter '*.log'
    Remove-OldFiles -Path (Join-Path $logs 'DISM') -Days $days -Filter '*.log'
    Remove-OldFiles -Path (Join-Path $logs 'WindowsUpdate') -Days $days -Filter '*.etl'
    Remove-OldFiles -Path (Join-Path $logs 'NetSetup') -Days $days
    Remove-OldFiles -Path (Join-Path $logs 'SIH') -Days $days
}
function Clear-BrowserCaches {
    $running = @(Get-Process -Name chrome, msedge, firefox -ErrorAction SilentlyContinue | Select-Object -ExpandProperty ProcessName -Unique)
    if ($running.Count) { Write-PLog ('Browser läuft, Cache übersprungen: {0}' -f ($running -join ', ')) }
    $browsers = @(
        @{ N = 'chrome'; P = 'AppData\Local\Google\Chrome\User Data' },
        @{ N = 'msedge'; P = 'AppData\Local\Microsoft\Edge\User Data' }
    )
    foreach ($p in Get-ProfilePaths) {
        foreach ($b in $browsers) {
            if ($running -contains $b.N) { continue }
            $root = Join-Path $p $b.P
            if (-not [IO.Directory]::Exists($root)) { continue }
            foreach ($prof in [IO.Directory]::GetDirectories($root)) {
                $leaf = Split-Path $prof -Leaf
                if ($leaf -ne 'Default' -and $leaf -notlike 'Profile *') { continue }
                foreach ($sub in 'Cache\Cache_Data', 'Code Cache', 'GPUCache') { Remove-OldFiles -Path (Join-Path $prof $sub) -Recurse }
            }
        }
        if ($running -notcontains 'firefox') {
            $ff = Join-Path $p 'AppData\Local\Mozilla\Firefox\Profiles'
            if ([IO.Directory]::Exists($ff)) {
                foreach ($prof in [IO.Directory]::GetDirectories($ff)) { Remove-OldFiles -Path (Join-Path $prof 'cache2') -Recurse }
            }
        }
    }
}
function Clear-OwnLogs {
    $logDays = [math]::Max(1, [int]$Script:Cfg.Settings.LogDays)
    $repDays = [math]::Max(1, [int]$Script:Cfg.Settings.ReportDays)
    Remove-OldFiles -Path $Script:LogDir -Days $logDays -Filter 'PCPflege_*.log'
    Remove-OldFiles -Path (Join-Path $Script:DataDir 'Run') -Days 2
    Remove-OldFiles -Path (Join-Path $Script:DataDir 'Ninite') -Days $repDays
    Remove-OldFiles -Path (Join-Path $Script:DataDir 'OEM\HPIA_Report') -Days $repDays -Recurse
    Remove-OldFiles -Path (Join-Path $Script:DataDir 'OEM\HPIA_SoftPaqs') -Days 1 -Recurse
}
function Invoke-CleanMgr {
    $base   = 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Explorer\VolumeCaches'
    # bewusst NICHT: Temporary Setup Files, Setup Log Files, Windows Upgrade Log Files, Windows ESD installation files
    $wanted = @('Active Setup Temp Folders', 'BranchCache', 'Delivery Optimization Files', 'Device Driver Packages',
                'Diagnostic Data Viewer database files', 'Downloaded Program Files', 'Internet Cache Files',
                'Offline Pages Files', 'Old ChkDsk Files', 'RetailDemo Offline Content', 'System error memory dump files',
                'System error minidump files', 'Temporary Files', 'Update Cleanup', 'Upgrade Discarded Files',
                'Windows Defender', 'Windows Error Reporting Files')
    if ($Script:Cfg.Clean.WindowsOld) { $wanted += 'Previous Installations' }
    if ($Script:DryRun) { Write-PLog 'Datenträgerbereinigung: Menge wird erst bei der Ausführung ermittelt'; return [int64]0 }
    foreach ($k in (Get-ChildItem $base -ErrorAction SilentlyContinue)) {
        Remove-ItemProperty -Path $k.PSPath -Name 'StateFlags0777' -ErrorAction SilentlyContinue
        if ($wanted -contains $k.PSChildName) {
            New-ItemProperty -Path $k.PSPath -Name 'StateFlags0777' -Value 2 -PropertyType DWord -Force | Out-Null
        }
    }
    $before = Get-FreeBytes
    $p  = Start-Process -FilePath (Join-Path $env:SystemRoot 'System32\cleanmgr.exe') -ArgumentList '/sagerun:777' -PassThru -WindowStyle Hidden
    $sw = [Diagnostics.Stopwatch]::StartNew()
    while (-not $p.HasExited) {
        if ((Test-PCancel) -or $sw.Elapsed.TotalMinutes -gt [math]::Max(10, [int]$Script:Cfg.Settings.CleanMgrTimeout)) {
            try { $p.Kill() } catch { }
            Write-PLog 'Datenträgerbereinigung abgebrochen' 'WARN'; break
        }
        Start-Sleep -Seconds 2
    }
    $diff = (Get-FreeBytes) - $before
    if ($diff -lt 0) { $diff = 0 }
    return [int64]$diff
}
function Invoke-ComponentCleanup {
    if ($Script:DryRun) { Write-PLog 'Komponentenspeicher: Menge wird erst bei der Ausführung ermittelt'; return [int64]0 }
    $before = Get-FreeBytes
    $dismArgs = @('/Online', '/Cleanup-Image', '/StartComponentCleanup')
    if ($Script:Cfg.Clean.ResetBase) { $dismArgs += '/ResetBase' }
    $code = Invoke-External -Exe (Join-Path $env:SystemRoot 'System32\Dism.exe') -Arguments $dismArgs -TimeoutMin 120 -Quiet
    Write-PLog ('DISM StartComponentCleanup: Exitcode {0}' -f $code)
    $diff = (Get-FreeBytes) - $before
    if ($diff -lt 0) { $diff = 0 }
    return [int64]$diff
}
function Remove-OldDriverPackages {
    $drivers = @(Get-WindowsDriver -Online -ErrorAction Stop)
    $inUse = @{}; foreach ($d in @(Get-CimInstance Win32_PnPSignedDriver -ErrorAction SilentlyContinue)) { if ($d.InfName) { $inUse[([string]$d.InfName).ToLower()] = $true } }
    $vv = { param($x) try { [version]$x.Version } catch { [version]'0.0' } }
    $groups  = $drivers | Group-Object { '{0}|{1}|{2}' -f (Split-Path $_.OriginalFileName -Leaf), $_.ProviderName, $_.ClassName }
    foreach ($g in $groups) {
        if ($g.Count -lt 2) { continue }
        # Neueste Version zuerst (Version vor Datum). Nie löschen: benutzte Pakete, die neueste Version und alles, was neuer ist als ein benutztes Paket
        $sorted = @($g.Group | Sort-Object @{ e = { & $vv $_ }; Descending = $true }, @{ e = { $_.Date }; Descending = $true })
        $used = @($sorted | Where-Object { $inUse.ContainsKey(([string]$_.Driver).ToLower()) })
        $floor = if ($used.Count) { ($used | ForEach-Object { & $vv $_ } | Sort-Object -Descending | Select-Object -First 1) } else { & $vv $sorted[0] }
        foreach ($old in @($sorted | Select-Object -Skip 1 | Where-Object { -not $inUse.ContainsKey(([string]$_.Driver).ToLower()) -and (& $vv $_) -lt $floor })) {
            $dir  = Split-Path $old.OriginalFileName
            $size = [int64](Get-ChildItem -LiteralPath $dir -Recurse -File -Force -ErrorAction SilentlyContinue | Measure-Object Length -Sum).Sum
            $name = '{0} {1} ({2}, {3:dd.MM.yyyy})' -f $old.Driver, (Split-Path $old.OriginalFileName -Leaf), $old.Version, $old.Date
            if ($Script:DryRun) { Write-PLog ('   veraltet: {0}' -f $name); $size; continue }
            $null = & pnputil.exe /delete-driver $old.Driver 2>&1
            if ($LASTEXITCODE -eq 0) { Write-PLog ('   entfernt: {0}' -f $name); $size }
            else { Write-PLog ('   in Benutzung, behalten: {0}' -f $name) }
        }
    }
}

# ------------------------------------------------------------------ OPTIMIEREN
function New-PflegeRestorePoint {
    try {
        New-ItemProperty -Path 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\SystemRestore' -Name 'SystemRestorePointCreationFrequency' -Value 0 -PropertyType DWord -Force | Out-Null
        Checkpoint-Computer -Description ('PC-Tools {0:dd.MM.yyyy HH:mm}' -f (Get-Date)) -RestorePointType MODIFY_SETTINGS -ErrorAction Stop
        Write-PLog 'Wiederherstellungspunkt erstellt' 'OK'
    } catch {
        Write-PLog ('Wiederherstellungspunkt nicht möglich (Computerschutz für C: aktiv?): {0}' -f $_.Exception.Message) 'WARN'
    }
}
function Optimize-Drives {
    $vols = @(Get-Volume -ErrorAction SilentlyContinue | Where-Object { "$($_.DriveType)" -eq 'Fixed' -and $_.DriveLetter -and $_.FileSystem -in 'NTFS', 'ReFS' } | Sort-Object DriveLetter)
    $phys = @(Get-PhysicalDisk -ErrorAction SilentlyContinue)
    foreach ($v in $vols) {
        if (Test-PCancel) { break }
        $letter = [string]$v.DriveLetter
        $bus = ''; $media = ''
        try {
            $disk = Get-Partition -DriveLetter $v.DriveLetter -ErrorAction Stop | Get-Disk -ErrorAction Stop
            $bus = [string]$disk.BusType
            $pd = $phys | Where-Object { [string]$_.DeviceId -eq [string]$disk.Number } | Select-Object -First 1
            if ($pd) { $media = [string]$pd.MediaType }
        } catch { }
        if ($Script:Cfg.Optimize.SkipUsb -and $bus -eq 'USB') { Write-PLog ('Laufwerk {0}: USB - übersprungen' -f $letter); continue }
        $mode = switch ($media) { 'SSD' { 'TRIM' } 'HDD' { 'Defrag' } default { 'Auto' } }
        if ($mode -eq 'TRIM' -and -not $Script:Cfg.Optimize.Trim) { Write-PLog ('Laufwerk {0}: SSD - TRIM ist ausgeschaltet' -f $letter); continue }
        if ($mode -eq 'Defrag' -and -not $Script:Cfg.Optimize.Defrag) { Write-PLog ('Laufwerk {0}: Festplatte - Defragmentierung ist ausgeschaltet' -f $letter); continue }
        $label = switch ($mode) { 'TRIM' { 'SSD - TRIM (Retrim)' } 'Defrag' { 'Festplatte - Defragmentierung' } default { 'automatische Optimierung' } }
        $size = '{0:N0} GB' -f ($v.Size / 1GB)
        $Script:Detail = ('Laufwerk {0}: {1} ({2}, {3})' -f $letter, $label, $size, $(if ($bus) { $bus } else { '?' }))
        Set-PStatus ('Optimiere Laufwerk {0}: ({1})' -f $letter, $label)
        Write-PLog ('Laufwerk {0}: {1} ({2}, {3}) ...' -f $letter, $label, $size, $bus)
        $sw = [Diagnostics.Stopwatch]::StartNew()
        # defrag.exe: /L = Retrim (SSD), /D = Defragmentierung (HDD), /O = passend zum Medium; /U = Fortschritt, /V = ausführlich
        $a = switch ($mode) { 'TRIM' { @(('{0}:' -f $letter), '/L', '/U', '/V') } 'Defrag' { @(('{0}:' -f $letter), '/D', '/U', '/V') } default { @(('{0}:' -f $letter), '/O', '/U', '/V') } }
        $code = Invoke-External -Exe (Join-Path $env:SystemRoot 'System32\defrag.exe') -Arguments $a -TimeoutMin 240 -OemEncoding
        if ($code -eq 0) { Write-PLog ('Laufwerk {0}: fertig nach {1:mm\:ss} min' -f $letter, $sw.Elapsed) 'OK' }
        else { Write-PLog ('Laufwerk {0}: defrag beendet mit Code {1}' -f $letter, $code) 'WARN' }
    }
}
function Invoke-HealthCheck {
    Set-PStatus 'DISM RestoreHealth (kann lange dauern)'
    $c1 = Invoke-External -Exe (Join-Path $env:SystemRoot 'System32\Dism.exe') -Arguments @('/Online', '/Cleanup-Image', '/RestoreHealth') -TimeoutMin 120 -Quiet
    Write-PLog ('DISM RestoreHealth: Exitcode {0}' -f $c1) $(if ($c1 -eq 0) { 'OK' } else { 'WARN' })
    if (Test-PCancel) { return }
    Set-PStatus 'SFC /scannow (kann lange dauern)'
    $c2 = Invoke-External -Exe (Join-Path $env:SystemRoot 'System32\sfc.exe') -Arguments @('/scannow') -TimeoutMin 120 -Quiet
    Write-PLog ('SFC: Exitcode {0} (Details in C:\Windows\Logs\CBS\CBS.log)' -f $c2) $(if ($c2 -eq 0) { 'OK' } else { 'WARN' })
}
function Disable-FastStartup {
    Set-ItemProperty -Path 'HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Power' -Name 'HiberbootEnabled' -Value 0 -Type DWord
    Write-PLog 'Schnellstart deaktiviert' 'OK'
}
function Clear-Dns { Clear-DnsClientCache -ErrorAction SilentlyContinue; Write-PLog 'DNS-Cache geleert' 'OK' }

# ------------------------------------------------------------------ UPDATES
# Systempartition (EFI bzw. "System-reserviert") freiräumen - sonst scheitern Funktionsupdates mit
# "Die für das System reservierte Partition konnte nicht aktualisiert werden" (0xc1900104 / 0x800f0922).
# Vom Nutzer ausdrücklich als automatischer Schritt im Voll-Lauf gewünscht. Nur entbehrliche Dateien; alles wird vorher im Datenordner gesichert.
function Repair-EspSpace {
    $target = 30MB
    $part = $null
    try { $part = @(Get-Partition -ErrorAction Stop | Where-Object { $_.GptType -eq '{c12a7328-f81f-11d2-ba4b-00a0c93ec93b}' } | Sort-Object { -not $_.IsSystem }) | Select-Object -First 1 } catch { }
    if (-not $part) { try { $part = @(Get-Partition -ErrorAction Stop | Where-Object { $_.IsSystem }) | Select-Object -First 1 } catch { } }
    if (-not $part) { Write-PLog 'Systempartition nicht gefunden - übersprungen.'; return }
    $isEsp = ([string]$part.GptType -eq '{c12a7328-f81f-11d2-ba4b-00a0c93ec93b}')
    $used = @(Get-Volume -ErrorAction SilentlyContinue | Where-Object { $_.DriveLetter } | ForEach-Object { [string]$_.DriveLetter }) + @(Get-PSDrive -PSProvider FileSystem -ErrorAction SilentlyContinue | ForEach-Object { $_.Name })
    $L = @('S', 'T', 'U', 'V', 'W', 'R', 'Q', 'P', 'O') | Where-Object { $used -notcontains $_ } | Select-Object -First 1
    if (-not $L) { Write-PLog 'Kein freier Laufwerksbuchstabe für die Systempartition - übersprungen.' 'WARN'; return }
    $mounted = $false
    try {
        if ($isEsp) { & mountvol.exe ('{0}:' -f $L) /s 2>&1 | Out-Null } else { Add-PartitionAccessPath -DiskNumber $part.DiskNumber -PartitionNumber $part.PartitionNumber -AccessPath ('{0}:\' -f $L) -ErrorAction Stop }
        $mounted = $true
        Start-Sleep -Milliseconds 800
        $root = '{0}:\' -f $L
        if (-not (Test-Path -LiteralPath $root)) { Write-PLog 'Systempartition ließ sich nicht einbinden - übersprungen.' 'WARN'; return }
        $getFree = { try { [int64](New-Object IO.DriveInfo $root).AvailableFreeSpace } catch { [int64]-1 } }
        $free = & $getFree
        $size = [int64]$part.Size
        Write-PLog ('Systempartition ({0}, Datenträger {1} Partition {2}): {3:N0} MB groß, {4:N1} MB frei' -f $(if ($isEsp) { 'EFI' } else { 'System-reserviert' }), $part.DiskNumber, $part.PartitionNumber, ($size / 1MB), ($free / 1MB))
        if ($free -lt 0) { Write-PLog '   Freier Platz nicht lesbar - übersprungen.' 'WARN'; return }
        if ($free -ge $target) { Write-PLog '   Genug Platz für Windows-Funktionsupdates.' 'OK'; return }
        if ($Script:CheckOnly -or $Script:DryRun) { Write-PLog ('   Zu wenig Platz (unter {0:N0} MB) - Funktionsupdates können scheitern. Würde entbehrliche Dateien entfernen.' -f ($target / 1MB)) 'WARN'; return }
        $bak = Join-Path $Script:DataDir ('ESP-Sicherung\{0:yyyyMMdd_HHmmss}' -f (Get-Date))
        $mb = if ($isEsp) { Join-Path $root 'EFI\Microsoft\Boot' } else { Join-Path $root 'Boot' }
        $keepLang = @('de-DE', 'en-US', [Globalization.CultureInfo]::InstalledUICulture.Name, [Globalization.CultureInfo]::CurrentUICulture.Name) | Select-Object -Unique
        $steps = [System.Collections.Generic.List[object]]::new()
        $steps.Add(@{ Name = 'Schriftarten des Start-Managers (von Microsoft als entbehrlich dokumentiert)'; Items = @(Get-ChildItem -LiteralPath (Join-Path $mb 'Fonts') -File -Force -ErrorAction SilentlyContinue) })
        $steps.Add(@{ Name = 'Sprachdateien des Start-Managers für nicht genutzte Sprachen'; Items = @(Get-ChildItem -LiteralPath $mb -Directory -Force -ErrorAction SilentlyContinue | Where-Object { $_.Name -match '^[a-z]{2}-[A-Z]{2}$' -and $keepLang -notcontains $_.Name } | ForEach-Object { Get-ChildItem -LiteralPath $_.FullName -File -Recurse -Force -ErrorAction SilentlyContinue }) })
        $steps.Add(@{ Name = 'Protokoll- und Sicherungsreste'; Items = @(Get-ChildItem -LiteralPath $root -File -Recurse -Force -ErrorAction SilentlyContinue | Where-Object { $_.Extension -in '.log', '.old', '.tmp', '.dmp' }) })
        $steps.Add(@{ Name = 'HP: zwischengespeicherte Geräte-Firmware (DEVFW)'; Items = @(Get-ChildItem -LiteralPath (Join-Path $root 'EFI\HP\DEVFW') -File -Recurse -Force -ErrorAction SilentlyContinue) })
        $steps.Add(@{ Name = 'HP: Sicherung des vorherigen BIOS (BIOS\Previous)'; Items = @(Get-ChildItem -LiteralPath (Join-Path $root 'EFI\HP\BIOS\Previous') -File -Recurse -Force -ErrorAction SilentlyContinue) })
        foreach ($st in $steps) {
            if ($free -ge $target) { break }
            $items = @($st.Items | Where-Object { $_ })
            if (-not $items.Count) { continue }
            $sum = [int64]0; foreach ($it in $items) { $sum += $it.Length }
            Write-PLog ('   {0}: {1} Datei(en), {2:N1} MB' -f $st.Name, $items.Count, ($sum / 1MB))
            foreach ($it in $items) {
                try {
                    $rel = $it.FullName.Substring($root.Length)
                    $dst = Join-Path $bak $rel
                    New-Item -Path (Split-Path $dst) -ItemType Directory -Force | Out-Null
                    Copy-Item -LiteralPath $it.FullName -Destination $dst -Force -ErrorAction Stop
                    Remove-Item -LiteralPath $it.FullName -Force -ErrorAction Stop
                } catch { Write-PLog ('   {0}: {1}' -f $it.Name, $_.Exception.Message) 'WARN' }
            }
            $free = & $getFree
            Write-PLog ('   jetzt {0:N1} MB frei' -f ($free / 1MB))
        }
        if ($free -ge $target) { Write-PLog ('Systempartition bereinigt - {0:N1} MB frei, das Funktionsupdate sollte jetzt durchlaufen. Sicherung der entfernten Dateien: {1}' -f ($free / 1MB), $bak) 'OK' }
        else {
            $big = @(Get-ChildItem -LiteralPath $root -Directory -Force -Recurse -ErrorAction SilentlyContinue | ForEach-Object { $s0 = [int64]0; Get-ChildItem -LiteralPath $_.FullName -File -Force -ErrorAction SilentlyContinue | ForEach-Object { $s0 += $_.Length }; [pscustomobject]@{ P = $_.FullName.Substring($root.Length); S = $s0 } } | Sort-Object S -Descending | Select-Object -First 6)
            Write-PLog ('Die Systempartition hat nach der Bereinigung nur {0:N1} MB frei (Ziel {1:N0} MB). Sie ist mit {2:N0} MB zu klein oder voll mit Dateien anderer Hersteller. Größte Ordner: {3}. Lösung: Systempartition vergrößern (z.B. auf 300 MB) oder die Reparaturinstallation auf der Seite Windows-Reparatur.' -f ($free / 1MB), ($target / 1MB), ($size / 1MB), (($big | ForEach-Object { '{0} ({1:N1} MB)' -f $_.P, ($_.S / 1MB) }) -join ', ')) 'WARN'
        }
    } catch { Write-PLog ('Systempartition: {0}' -f $_.Exception.Message) 'WARN' }
    finally {
        if ($mounted) {
            if ($isEsp) { & mountvol.exe ('{0}:' -f $L) /d 2>&1 | Out-Null } else { try { Remove-PartitionAccessPath -DiskNumber $part.DiskNumber -PartitionNumber $part.PartitionNumber -AccessPath ('{0}:\' -f $L) -ErrorAction Stop } catch { } }
        }
    }
}
function Invoke-WindowsUpdate {
    $session = New-Object -ComObject Microsoft.Update.Session
    $session.ClientApplicationID = 'PC-Tools'
    $searcher = $session.CreateUpdateSearcher()
    $crit = 'IsInstalled=0 and IsHidden=0'
    if (-not $Script:Cfg.Update.WUDrivers) { $crit += " and Type='Software'" }
    $Script:Detail = 'Suche nach Updates bei Microsoft (kann einige Minuten dauern)'
    Set-PStatus 'Windows Update: Suche nach Updates'
    $result = $searcher.Search($crit)
    $list = [System.Collections.Generic.List[object]]::new()
    foreach ($u in $result.Updates) {
        $cats = @($u.Categories | ForEach-Object { $_.Name })
        $isUpgrade = ($cats -contains 'Upgrades') -or ($u.Title -match 'Insider Preview|Feature update|Funktionsupdate')
        if ($Script:Cfg.Update.WUExcludeUpgrades -and $isUpgrade) { Write-PLog ('   ausgeschlossen (Funktionsupdate): {0}' -f $u.Title); continue }
        $list.Add($u)
        Write-PLog ('   verfügbar: {0}{1}' -f $u.Title, $(if ($u.InstallationBehavior.CanRequestUserInput) { ' (wird still installiert)' } else { '' }))
    }
    Write-PLog ('Windows Update: {0} Update(s) verfügbar' -f $list.Count)
    if ($Script:CheckOnly -or $list.Count -eq 0) { return }
    if (@($list | Where-Object { $_.Type -eq 2 }).Count) { try { Invoke-DsBeforeDriverUpdate 'Windows Update (Treiber)' } catch { } }

    $coll = New-Object -ComObject Microsoft.Update.UpdateColl
    foreach ($u in $list) { if (-not $u.EulaAccepted) { $u.AcceptEula() }; [void]$coll.Add($u) }
    $Script:Detail = ('Download: {0}' -f (($list | ForEach-Object { $_.Title }) -join ' | '))
    Set-PStatus ('Windows Update: Download von {0} Update(s)' -f $list.Count)
    $dl = $session.CreateUpdateDownloader(); $dl.Updates = $coll
    $null = $dl.Download()
    $inst = New-Object -ComObject Microsoft.Update.UpdateColl
    foreach ($u in $list) { if ($u.IsDownloaded) { [void]$inst.Add($u) } }
    if ($inst.Count -eq 0) { Write-PLog 'Windows Update: Download fehlgeschlagen' 'WARN'; return }
    $Script:Detail = 'Installation läuft über den Windows-Modulinstaller (TiWorker) - kann dauern'
    Set-PStatus ('Windows Update: Installation von {0} Update(s)' -f $inst.Count)
    # Updates, die laut Microsoft "Eingaben anfordern koennen" (oft Intel-/Hersteller-Treiber), getrennt und
    # mit ForceQuiet installieren: so laufen sie still durch, statt uebersprungen zu werden - und falls eines
    # wirklich eine Eingabe braucht, schlaegt nur dieses fehl, statt dass die Installation haengt.
    $normal = New-Object -ComObject Microsoft.Update.UpdateColl; $quiet = New-Object -ComObject Microsoft.Update.UpdateColl
    for ($i = 0; $i -lt $inst.Count; $i++) { $u = $inst.Item($i); if ($u.InstallationBehavior.CanRequestUserInput) { [void]$quiet.Add($u) } else { [void]$normal.Add($u) } }
    $failQuiet = 0
    foreach ($batch in @(@{ C = $normal; Q = $false }, @{ C = $quiet; Q = $true })) {
        if ($batch.C.Count -eq 0) { continue }
        $installer = $session.CreateUpdateInstaller(); $installer.Updates = $batch.C
        if ($batch.Q) { try { $installer.ForceQuiet = $true } catch { }; Set-PStatus ('Windows Update: stille Installation von {0} Treiber-/Hersteller-Update(s)' -f $batch.C.Count) }
        try { $res = $installer.Install() }
        catch { Write-PLog ('   Installation fehlgeschlagen: {0}' -f $_.Exception.Message) 'WARN'; if ($batch.Q) { $failQuiet += $batch.C.Count }; continue }
        for ($i = 0; $i -lt $batch.C.Count; $i++) {
            $r = $res.GetUpdateResult($i)
            $ok = $r.ResultCode -in 2, 3
            if ($ok) { $Script:UpdatesInstalled++ } elseif ($batch.Q) { $failQuiet++ }
            Write-PLog ('   {0}: {1}{2}' -f $(if ($ok) { 'installiert' } else { 'FEHLER' }), $batch.C.Item($i).Title,
                        $(if (-not $ok) { ' (0x{0:X8})' -f $r.HResult } else { '' })) $(if ($ok) { 'OK' } else { 'WARN' })
        }
        if ($res.RebootRequired) { $Script:RebootNeeded = $true }
    }
    if ($failQuiet) { Write-PLog ('   {0} Update(s) liessen sich nicht still installieren - bitte einmal in Einstellungen > Windows Update auf "Installieren" klicken.' -f $failQuiet) 'WARN' }
}
function Get-WingetPath {
    $cmd = Get-Command winget.exe -ErrorAction SilentlyContinue
    if ($cmd) { return $cmd.Source }
    $cand = Get-ChildItem (Join-Path $env:ProgramFiles 'WindowsApps\Microsoft.DesktopAppInstaller_*_x64__8wekyb3d8bbwe\winget.exe') -ErrorAction SilentlyContinue |
            Sort-Object { try { [version](($_.Directory.Name -split '_')[1]) } catch { [version]'0.0' } } -Descending | Select-Object -First 1
    if ($cand) { return $cand.FullName }
    return $null
}
# Pakete, die NIE automatisch aktualisiert/installiert werden dürfen: Windows-Upgrade-Assistenten starten
# einen interaktiven OS-Upgrade-Dialog, der sich aufhängt (z.B. "Update-Assistant nur für Windows 10").
$Script:WingetBlocked = @('Microsoft.WindowsInstallationAssistant', 'Microsoft.Windows11InstallationAssistant', 'Microsoft.WindowsUpdateAssistant', 'Microsoft.UpdateAssistant', 'Microsoft.WindowsPCHealthCheck', 'Microsoft.MediaCreationTool', 'Microsoft.WindowsMediaCreationTool')
function Test-WingetBlocked([string]$Id) {
    $i = ([string]$Id).Trim()
    foreach ($b in @('Microsoft.WindowsInstallationAssistant', 'Microsoft.Windows11InstallationAssistant', 'Microsoft.WindowsUpdateAssistant', 'Microsoft.UpdateAssistant', 'Microsoft.WindowsPCHealthCheck', 'Microsoft.MediaCreationTool', 'Microsoft.WindowsMediaCreationTool')) { if ($i -ieq $b) { return $true } }
    return $false
}
function Get-WingetUpgradeIds {
    param([string]$Wg, [string[]]$Common)
    $null = Invoke-External -Exe $Wg -Arguments (@('upgrade') + $Common) -TimeoutMin 5 -Capture
    $ids = [System.Collections.Generic.List[string]]::new()
    $idStart = -1; $inTable = $false
    foreach ($raw in $Script:Captured) {
        $l = $raw.TrimEnd()
        $m = [regex]::Match($l, '(?<=\s)ID(?=\s+\S)')
        if (-not $inTable -and $m.Success -and $l -match 'Version') { $idStart = $m.Index; continue }
        if ($idStart -ge 0 -and -not $inTable -and $l -match '^-{10,}') { $inTable = $true; continue }
        if ($inTable) {
            if (-not $l.Trim() -or $l.Length -le $idStart -or $l -match '^\s*\d+\s+(Aktualisierung|Paket|upgrade|package|Update)' -or ($l -match '(verfügbar|available|angeheftet|pinned|explicit|explizit)[\.:]?\s*$' -and $l -notmatch '\S\s{2,}\S')) { $inTable = $false; $idStart = -1; continue }
            if ($idStart -gt 0 -and $l[$idStart - 1] -ne ' ') { continue }
            $tok = ($l.Substring($idStart).Trim() -split '\s+')[0]
            if ($tok -match '^[A-Za-z0-9][\w\.\-\+]*$' -and -not $ids.Contains($tok) -and -not (Test-WingetBlocked $tok)) { $ids.Add($tok) }
        }
    }
    return , $ids
}
function Invoke-Winget {
    $wg = Get-WingetPath
    if (-not $wg) { Write-PLog 'winget nicht gefunden (App-Installer aus dem Microsoft Store installieren)' 'WARN'; return }
    $common = @('--accept-source-agreements', '--disable-interactivity')
    # Windows-Upgrade-Assistenten dauerhaft anheften (sonst startet "upgrade --all" sie und sie hängen sich auf)
    foreach ($id in $Script:WingetBlocked) { $null = Invoke-External -Exe $wg -Arguments (@('pin', 'add', '--id', $id, '--exact') + $common) -TimeoutMin 2 -Quiet }
    $excl = @(([string]$Script:Cfg.Update.WingetExclude) -split '[,;\s]+' | Where-Object { $_ })
    foreach ($id in $excl) { $null = Invoke-External -Exe $wg -Arguments (@('pin', 'add', '--id', $id) + $common) -TimeoutMin 2 -Quiet }
    if ($excl.Count) { Write-PLog ('Ausgenommen (gepinnt): {0}' -f ($excl -join ', ')) }
    $timeout = [int]$Script:Cfg.Update.WingetTimeout; if ($timeout -lt 5) { $timeout = 5 }

    Set-PStatus 'winget: Suche nach Programm-Updates'
    if ($Script:CheckOnly) {
        $null = Invoke-External -Exe $wg -Arguments (@('upgrade') + $common) -TimeoutMin 5
        return
    }
    $ids = Get-WingetUpgradeIds -Wg $wg -Common $common
    Write-PLog ('winget: {0} Programm(e) mit Update' -f $ids.Count)
    $ok = 0; $fail = [System.Collections.Generic.List[string]]::new(); $noApp = [System.Collections.Generic.List[string]]::new()
    $n = 0
    foreach ($id in $ids) {
        if (Test-PCancel) { break }
        $n++
        $Script:Detail = ('Programm {1} von {2}: {0}' -f $id, $n, $ids.Count)
        Set-PStatus ('winget: {0} ({1}/{2})' -f $id, $n, $ids.Count)
        Write-PLog ('>> {0} ({1}/{2})' -f $id, $n, $ids.Count)
        $code = Invoke-External -Exe $wg -Arguments (@('upgrade', '--id', $id, '--exact', '--silent', '--accept-package-agreements') + $common) -TimeoutMin $timeout
        # Andere Installationsart (z.B. altes PowerToys pro Benutzer -> neues pro PC): alte Version entfernen und neu installieren
        if ($code -eq -1978335090) {
            Write-PLog '   Neue Version nutzt eine andere Installationsart - alte Version wird entfernt und neu installiert'
            $null = Invoke-External -Exe $wg -Arguments (@('uninstall', '--id', $id, '--exact', '--silent') + $common) -TimeoutMin $timeout
            $code = Invoke-External -Exe $wg -Arguments (@('install', '--id', $id, '--exact', '--silent', '--accept-package-agreements') + $common) -TimeoutMin $timeout
        }
        switch ($code) {
            0            { $ok++; Write-PLog ('   {0}: aktualisiert' -f $id) 'OK' }
            -1978335189  { $noApp.Add($id); Write-PLog ('   {0}: kein passendes Update (neuere Version passt nicht zu diesem System - kein Fehler)' -f $id) }
            -1978334967  { $ok++; Write-PLog ('   {0}: aktualisiert - Neustart nötig' -f $id) 'OK'; $Script:RebootNeeded = $true }
            default      {
                # Rückfall wie bei der Installation: toter winget-Link (z.B. HWiNFO 404) -> direkt beim Hersteller laden
                $done = $false
                $dk = @($Script:DirectSources.Keys | Where-Object { $Script:DirectSources[$_].WingetId -eq $id }) | Select-Object -First 1
                if ($dk) { Write-PLog ('   winget-Fehler 0x{0:X8} - lade direkt beim Hersteller' -f $code); $done = Install-DirectSource $dk -Update }
                elseif ($code -eq -1978335215) { Write-PLog '   Prüfsumme im winget-Katalog veraltet - installiere mit Signaturprüfung'; $done = Install-WingetBySignature $wg $id }
                if ($done) { $ok++; Write-PLog ('   {0}: aktualisiert (Rückfallweg)' -f $id) 'OK' }
                else { $fail.Add($id); Write-PLog ('   {0}: fehlgeschlagen (0x{1:X8} - {2})' -f $id, $code, (Get-WingetErrorText $code)) 'WARN' }
            }
        }
    }
    # Nachlauf: alles, was beim Einlesen nicht erkannt wurde (z.B. gekürzte IDs)
    if (-not (Test-PCancel)) {
        $rest = Get-WingetUpgradeIds -Wg $wg -Common $common
        # nur Programme, die beim ersten Durchgang gar nicht erkannt wurden - nicht erneut die fehlgeschlagenen oder unpassenden
        $left = @($rest | Where-Object { $ids -notcontains $_ -and $fail -notcontains $_ -and $noApp -notcontains $_ })
        if ($left.Count) {
            Write-PLog 'winget: Nachlauf für restliche Programme'
            $null = Invoke-External -Exe $wg -Arguments (@('upgrade', '--all', '--silent', '--accept-package-agreements') + $common) -TimeoutMin ($timeout * 2)
        }
    }
    if ($noApp.Count) { Write-PLog ('winget: ohne passendes Update (kein Fehler): {0}' -f ($noApp -join ', ')) }
    Write-PLog ('winget: {0} aktualisiert, {1} fehlgeschlagen{2}' -f $ok, $fail.Count, $(if ($fail.Count) { ' (' + ($fail -join ', ') + ')' } else { '' })) $(if ($fail.Count) { 'WARN' } else { 'OK' })
}
function Find-Ninite {
    $cands = @([string]$Script:Cfg.Update.NinitePath,
               (Join-Path $Script:DataDir 'NinitePro.exe'),
               $(if ($Script:ScriptDir) { Join-Path $Script:ScriptDir 'NinitePro.exe' }),
               'C:\Tools\PCPflege\NinitePro.exe', 'C:\Tools\NinitePro.exe')
    return ($cands | Where-Object { $_ -and (Test-Path -LiteralPath $_) } | Select-Object -First 1)
}
# ---- Chocolatey (kostenlose, skriptbare Alternative zu Ninite Pro) ----
function Get-ChocoPath {
    $c = Join-Path $env:ProgramData 'chocolatey\bin\choco.exe'
    if (Test-Path -LiteralPath $c) { return $c }
    $g = Get-Command choco.exe -ErrorAction SilentlyContinue
    if ($g) { return [string]$g.Source }
    return ''
}
function Install-Chocolatey {
    if (-not (Test-IsAdmin)) { Write-PLog 'Chocolatey-Einrichtung braucht Administratorrechte - übersprungen.' 'WARN'; return '' }
    Set-PStatus 'Chocolatey wird eingerichtet'
    Write-PLog 'Chocolatey nicht gefunden - wird eingerichtet (community.chocolatey.org).'
    $sp = [Net.ServicePointManager]::SecurityProtocol
    try {
        [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12
        $script = (New-Object Net.WebClient).DownloadString('https://community.chocolatey.org/install.ps1')
        & ([scriptblock]::Create($script)) *>&1 | ForEach-Object { if ([string]$_) { Write-PLog ('   ' + [string]$_) } }
    } catch { Write-PLog ('Chocolatey-Einrichtung fehlgeschlagen: ' + $_.Exception.Message) 'WARN'; return '' }
    finally { [Net.ServicePointManager]::SecurityProtocol = $sp }
    $p = Get-ChocoPath
    if ($p) { Write-PLog 'Chocolatey eingerichtet.' 'OK' }
    return $p
}
function Invoke-ChocoUpdate {
    $cho = Get-ChocoPath
    if (-not $cho -and $Script:Cfg.Update.ChocoAutoInstall) { $cho = Install-Chocolatey }
    if (-not $cho) { Write-PLog 'Chocolatey nicht gefunden (automatische Einrichtung aus oder fehlgeschlagen) - auf der Updates-Seite aktivieren.' 'WARN'; return }
    $timeout = [int]$Script:Cfg.Update.ChocoTimeout; if ($timeout -lt 5) { $timeout = 5 }
    $excl = @(([string]$Script:Cfg.Update.ChocoExclude) -split '[,;\s]+' | Where-Object { $_ })
    if ($Script:CheckOnly) {
        Set-PStatus 'Chocolatey: Suche nach Programm-Updates'
        $null = Invoke-External -Exe $cho -Arguments @('outdated', '--limit-output', '--no-color') -TimeoutMin 5
        return
    }
    Set-PStatus 'Chocolatey: Programme werden aktualisiert'
    $a = @('upgrade', 'all', '-y', '--no-progress', '--no-color', ('--execution-timeout=' + ([int]$timeout * 60)))
    if ($excl.Count) { $a += ('--except=' + ($excl -join ';')); Write-PLog ('Chocolatey ausgenommen: {0}' -f ($excl -join ', ')) }
    $code = Invoke-External -Exe $cho -Arguments $a -TimeoutMin ([math]::Max(10, [int]$timeout))
    switch ($code) {
        0 { Write-PLog 'Chocolatey: alle Programme aktuell bzw. aktualisiert.' 'OK' }
        1641 { Write-PLog 'Chocolatey: aktualisiert - Neustart nötig.' 'OK'; $Script:RebootNeeded = $true }
        3010 { Write-PLog 'Chocolatey: aktualisiert - Neustart nötig.' 'OK'; $Script:RebootNeeded = $true }
        default { Write-PLog ('Chocolatey meldet Code {0} - Details im Protokoll. Ein anderer Update-Dienst (winget) kann fehlende Programme übernehmen.' -f $code) 'WARN' }
    }
    $Script:UpdatesInstalled++
}
function Invoke-ChocoInstall {
    $ids = @($Script:ChocoApps | ForEach-Object { "$_".Trim() } | Where-Object { $_ })
    if (-not $ids.Count) { return }
    $cho = Get-ChocoPath
    if (-not $cho -and $Script:Cfg.Update.ChocoAutoInstall) { $cho = Install-Chocolatey }
    if (-not $cho) { Write-PLog 'Chocolatey nicht gefunden - auf der Updates-Seite aktivieren/einrichten.' 'WARN'; return }
    $timeout = [math]::Max(5, [int]$Script:Cfg.Update.ChocoTimeout)
    $ok = 0; $fail = [System.Collections.Generic.List[string]]::new(); $n = 0
    foreach ($id in $ids) {
        if (Test-PCancel) { break }
        $n++; $Script:Detail = ('Programm {1} von {2}: {0}' -f $id, $n, $ids.Count); Set-PStatus ('Chocolatey installiert {0} ({1}/{2})' -f $id, $n, $ids.Count); Write-PLog ('>> {0} ({1}/{2})' -f $id, $n, $ids.Count)
        $code = Invoke-External -Exe $cho -Arguments @('install', $id, '-y', '--no-progress', '--no-color', ('--execution-timeout=' + ([int]$timeout * 60))) -TimeoutMin ([math]::Max(10, $timeout))
        if ($code -in 0, 1641, 3010) { $ok++; if ($code -ne 0) { $Script:RebootNeeded = $true }; Write-PLog ('   {0} installiert.' -f $id) 'OK' } else { $fail.Add($id); Write-PLog ('   Chocolatey Code {0} für {1}' -f $code, $id) 'WARN' }
    }
    Write-PLog ('Chocolatey: {0} installiert{1}' -f $ok, $(if ($fail.Count) { ', ' + $fail.Count + ' fehlgeschlagen (' + ($fail -join ', ') + ')' } else { '' })) $(if ($fail.Count) { 'WARN' } else { 'OK' })
    $Script:UpdatesInstalled += $ok
}
# Live-Suche ueber winget UND Chocolatey - liefert Pakete zum Installieren (laeuft in Invoke-Bg)
function Search-AppCatalog([string]$Term, [string]$Src = 'beide') {
    $rows = [System.Collections.Generic.List[object]]::new()
    $t = ([string]$Term).Trim(); if (-not $t) { return , $rows.ToArray() }
    if ($Src -in 'beide', 'winget') {
        $wg = Get-WingetPath
        if ($wg) {
            try {
                $out = @(& $wg search $t --accept-source-agreements --disable-interactivity 2>$null)
                $hdr = -1; for ($i = 0; $i -lt $out.Count; $i++) { if ($out[$i] -match '^-{5,}') { $hdr = $i; break } }
                if ($hdr -ge 1) {
                    $head = $out[$hdr - 1]
                    $iId = $head.IndexOf('Id'); $iVer = $head.IndexOf('Version')
                    for ($i = $hdr + 1; $i -lt $out.Count; $i++) {
                        $ln = $out[$i]; if (-not $ln.Trim() -or $ln -match '^\d+\s') { continue }
                        if ($iId -gt 0 -and $ln.Length -ge $iId) {
                            $name = $ln.Substring(0, $iId).Trim()
                            $rest = $ln.Substring($iId)
                            $id = ($rest -split '\s{2,}')[0].Trim()
                            $ver = ''; if ($iVer -gt $iId -and $ln.Length -ge ($iVer - 0)) { try { $ver = ($ln.Substring([math]::Min($iVer, $ln.Length)) -split '\s{2,}')[0].Trim() } catch { } }
                            if ($name -and $id -and -not (Test-WingetBlocked $id)) { $rows.Add([pscustomobject]@{ Name = $name; Id = $id; Version = $ver; Source = 'winget' }) }
                        }
                    }
                }
            } catch { }
        }
    }
    if ($Src -in 'beide', 'choco') {
        $cho = Get-ChocoPath
        if ($cho) {
            try {
                foreach ($ln in @(& $cho search $t --limit-output --no-color 2>$null)) {
                    $p = ([string]$ln) -split '\|'
                    if ($p.Count -ge 1 -and $p[0].Trim()) { $rows.Add([pscustomobject]@{ Name = $p[0].Trim(); Id = $p[0].Trim(); Version = $(if ($p.Count -ge 2) { $p[1].Trim() } else { '' }); Source = 'Chocolatey' }) }
                }
            } catch { }
        }
    }
    return , $rows.ToArray()
}
function Invoke-NiniteUpdate {
    $exe = Find-Ninite
    if (-not $exe) { Write-PLog 'NinitePro.exe nicht gefunden - Programm-Updates laufen trotzdem ueber winget (kostenlos, in Windows enthalten). NinitePro Pro ist optional (mehr Programme): ninite.com/pro, Pfad dann unter Updates eintragen.' 'WARN'; return }
    $dir = Join-Path $Script:DataDir 'Ninite'
    New-Item $dir -ItemType Directory -Force | Out-Null
    $report = Join-Path $dir ('Ninite_{0:yyyyMMdd_HHmmss}.txt' -f (Get-Date))
    $timeout = [int]$Script:Cfg.Update.NiniteTimeout; if ($timeout -lt 10) { $timeout = 10 }
    if ($Script:CheckOnly) {
        $a = @('/audit', '/silent', ('"{0}"' -f $report))
        $Script:Detail = 'Ninite prüft die installierten Programme'
    } else {
        $a = @('/updateonly', '/silent', ('"{0}"' -f $report), '/disableshortcuts', '/nocache')
        if ($Script:Cfg.Update.NiniteKill -and ($Script:IsAuto -or -not $Script:Cfg.Settings.KillOnlyScheduled)) { $a += '/kill' }
        $Script:Detail = 'Ninite lädt und installiert Updates (Fortschritt siehe aktive Prozesse)'
    }
    $excl = @(([string]$Script:Cfg.Update.NiniteExclude) -split '[,;]+' | ForEach-Object { $_.Trim() } | Where-Object { $_ })
    if ($excl.Count) { $a += '/exclude'; $a += ($excl | ForEach-Object { if ($_ -match '\s') { '"{0}"' -f $_ } else { $_ } }) }
    Set-PStatus 'Ninite arbeitet'
    $code = Invoke-Tool $exe $a -TimeoutMin $timeout -Quiet
    Write-NiniteReport -Report $report -Code $code
}
function Write-NiniteReport {
    param([string]$Report, [int]$Code)
    if (-not (Test-Path -LiteralPath $Report)) { Write-PLog ('Ninite: kein Bericht erstellt (Code {0})' -f $Code) 'WARN'; return }
    $lines = @(Get-Content -LiteralPath $Report -ErrorAction SilentlyContinue | Where-Object { $_.Trim() })
    $ok = 0; $bad = 0; $upd = 0
    foreach ($l in $lines) {
        $t = $l.Trim()
        $lvl = 'INFO'
        if ($t -match '(?i)failed|fehler') { $lvl = 'WARN'; $bad++ }
        elseif ($t -match '(?i):\s*OK\b|^OK\b') { $lvl = 'OK'; $ok++ }
        elseif ($t -match '(?i)\bUpdate\s*-') { $upd++ }
        Write-PLog ('   {0}' -f $t) $lvl
    }
    if ($Script:CheckOnly) { Write-PLog ('Ninite: {0} Programm(e) mit Update' -f $upd) }
    else { Write-PLog ('Ninite: {0} erfolgreich, {1} fehlgeschlagen - Bericht: {2}' -f $ok, $bad, $Report) $(if ($bad) { 'WARN' } else { 'OK' }) }
}
function Invoke-NiniteInstall {
    $apps = @($Script:NiniteApps | ForEach-Object { "$_".Trim() } | Where-Object { $_ })
    if ($apps -contains 'Firefox') { $apps = @($apps | Where-Object { $_ -notlike 'Firefox ESR*' }) }
    if (-not $apps.Count) { Write-PLog 'Keine Programme zur Installation ausgewählt' 'WARN'; return }
    $exe = Find-Ninite
    if (-not $exe) { Write-PLog 'NinitePro.exe nicht gefunden - Programm-Updates laufen trotzdem ueber winget (kostenlos, in Windows enthalten). NinitePro Pro ist optional (mehr Programme): ninite.com/pro, Pfad dann unter Updates eintragen.' 'WARN'; return }
    $dir = Join-Path $Script:DataDir 'Ninite'
    New-Item $dir -ItemType Directory -Force | Out-Null
    $report = Join-Path $dir ('Ninite_Install_{0:yyyyMMdd_HHmmss}.txt' -f (Get-Date))
    $a = @('/select') + @($apps | ForEach-Object { '"{0}"' -f $_ }) + @('/silent', ('"{0}"' -f $report), '/nocache')
    if (-not $Script:Cfg.Install.Shortcuts) { $a += '/disableshortcuts' }
    if ($Script:Cfg.Install.AllUsers) { $a += '/allusers' }
    Write-PLog ('Installiere {0} Programm(e): {1}' -f $apps.Count, ($apps -join ', '))
    $Script:Detail = ('Ninite installiert: {0}' -f ($apps -join ', '))
    Set-PStatus 'Ninite installiert Programme'
    $timeout = [int]$Script:Cfg.Update.NiniteTimeout; if ($timeout -lt 10) { $timeout = 10 }
    $code = Invoke-Tool $exe $a -TimeoutMin ([math]::Max($timeout, 15 * $apps.Count)) -Quiet
    Write-NiniteReport -Report $report -Code $code
}
function Invoke-WingetInstall {
    $ids = @($Script:WingetApps | ForEach-Object { "$_".Trim() } | Where-Object { $_ })
    if (-not $ids.Count) { return }
    $wg = Get-WingetPath
    if (-not $wg) { Write-PLog 'winget nicht gefunden (App-Installer aus dem Microsoft Store installieren)' 'WARN'; return }
    $common = @('--accept-source-agreements', '--accept-package-agreements', '--disable-interactivity', '--silent')
    $timeout = [math]::Max(5, [int]$Script:Cfg.Update.WingetTimeout)
    $ok = 0; $fail = [System.Collections.Generic.List[string]]::new(); $n = 0
    foreach ($id in $ids) {
        if (Test-PCancel) { break }
        $n++
        if (Test-WingetBlocked $id) { Write-PLog ('   {0} übersprungen - Windows-Upgrade-Assistenten werden nicht installiert (würden sich aufhängen).' -f $id) 'WARN'; continue }
        $Script:Detail = ('Programm {1} von {2}: {0}' -f $id, $n, $ids.Count)
        Set-PStatus ('winget installiert {0} ({1}/{2})' -f $id, $n, $ids.Count)
        Write-PLog ('>> {0} ({1}/{2})' -f $id, $n, $ids.Count)
        if ($id -eq 'Microsoft.Office') { if (Install-OfficeDefault) { $ok++ } else { $fail.Add($id) }; continue }
        $code = Invoke-External -Exe $wg -Arguments (@('install', '--id', $id, '--exact') + $common) -TimeoutMin $timeout -Capture
        $outTxt = (@($Script:Captured) -join "`n")
        foreach ($l in @($Script:Captured)) { $x = ([string]$l).Trim(); if ($x -and $x -notmatch '^[\-\\\|/ ]+$|[\u2580-\u259F]|^\d+([\.,]\d+)?\s*(KB|MB|GB)\s*/') { Write-PLog ('   ' + $x) } }
        # Andere Installationsart (z.B. PowerToys: pro Benutzer -> pro PC): alte Version entfernen, neu installieren
        if ($code -eq -1978335090) {
            Write-PLog '   Neue Version nutzt eine andere Installationsart - alte Version wird entfernt und neu installiert'
            $null = Invoke-External -Exe $wg -Arguments @('uninstall', '--id', $id, '--exact', '--silent', '--disable-interactivity', '--accept-source-agreements') -TimeoutMin $timeout
            $code = Invoke-External -Exe $wg -Arguments (@('install', '--id', $id, '--exact') + $common) -TimeoutMin $timeout
        }
        # Version unbekannt (winget empfiehlt --include-unknown): gezielt aktualisieren
        if ($code -eq -1978335189 -and $outTxt -match 'include-unknown') {
            $c2 = Invoke-External -Exe $wg -Arguments (@('upgrade', '--id', $id, '--exact', '--include-unknown') + $common) -TimeoutMin $timeout
            if ($c2 -eq 0) { $code = 0 } elseif ($c2 -eq -1978334967) { $code = $c2 }
        }
        # Paket-ID umbenannt (z.B. Trimble.SketchUp -> Trimble.SketchUp.2026): neueste passende ID suchen
        if ($code -eq -1978335212) {
            $alt = Find-WingetSuccessor $wg $id
            if ($alt) { Write-PLog ('   Neue Paket-ID gefunden: {0}' -f $alt); $id2 = $alt; $code = Invoke-External -Exe $wg -Arguments (@('install', '--id', $alt, '--exact') + $common) -TimeoutMin $timeout }
        }
        switch ($code) {
            0           { $ok++; Write-PLog ('   {0}: installiert' -f $id) 'OK' }
            -1978335135 { $ok++; Write-PLog ('   {0}: bereits installiert' -f $id) 'OK' }
            -1978335189 { $ok++; Write-PLog ('   {0}: bereits aktuell' -f $id) 'OK' }
            -1978334967 { $ok++; $Script:RebootNeeded = $true; Write-PLog ('   {0}: installiert - Neustart nötig' -f $id) 'OK' }
            default     {
                # Rückfall: Hersteller-Download (z.B. HWiNFO, wenn der winget-Link tot ist) oder Installer mit gültiger Signatur, wenn der Hersteller die Datei ersetzt hat
                $done = $false
                $dk = @($Script:DirectSources.Keys | Where-Object { $Script:DirectSources[$_].WingetId -eq $id }) | Select-Object -First 1
                if ($dk) { Write-PLog ('   winget-Fehler 0x{0:X8} - lade direkt beim Hersteller' -f $code); $done = Install-DirectSource $dk -Update }
                elseif ($code -eq -1978335215) { Write-PLog '   Prüfsumme im winget-Katalog veraltet (Hersteller hat die Datei ersetzt) - installiere mit Signaturprüfung'; $done = Install-WingetBySignature $wg $(if ($id2) { $id2 } else { $id }) }
                if ($done) { $ok++; Write-PLog ('   {0}: installiert (Rückfallweg)' -f $id) 'OK' }
                else { $fail.Add($id); Write-PLog ('   {0}: fehlgeschlagen (0x{1:X8} - {2})' -f $id, $code, (Get-WingetErrorText $code)) 'WARN' }
            }
        }
        $id2 = $null
    }
    Write-PLog ('winget: {0} von {1} erfolgreich{2}' -f $ok, $ids.Count, $(if ($fail.Count) { ' - fehlgeschlagen: ' + ($fail -join ', ') } else { '' })) $(if ($fail.Count) { 'WARN' } else { 'OK' })
}
function Get-WingetErrorText([int]$Code) {
    switch ($Code) {
        -1978335215 { 'Prüfsumme passt nicht' } -1978335212 { 'Paket nicht gefunden' } -2145844844 { 'Download-Link beim Hersteller existiert nicht mehr (404)' }
        -1978335090 { 'andere Installationsart - alte Version zuerst deinstallieren' } -1978335226 { 'Installer meldet Fehler' } -1978335216 { 'kein passender Installer für dieses System' } -1978334975 { 'Programm läuft gerade' }
        default { 'siehe winget-Fehlercodes' }
    }
}
$Script:BrowserUA = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/140.0.0.0 Safari/537.36'
function Find-WingetSuccessor([string]$Wg, [string]$Id) {
    $null = Invoke-External -Exe $Wg -Arguments @('search', '--id', $Id, '--source', 'winget', '--accept-source-agreements', '--disable-interactivity') -TimeoutMin 3 -Capture
    $rx = '(?<![\w.])(' + [regex]::Escape($Id) + '(\.[\w\-]+)?)(?![\w.])'
    $ids = @($Script:Captured | ForEach-Object { foreach ($m in [regex]::Matches([string]$_, $rx, 'IgnoreCase')) { $m.Groups[1].Value } } | Where-Object { $_ -ne $Id } | Select-Object -Unique)
    if (-not $ids.Count) { return $null }
    # neueste Jahres-/Versionsnummer zuerst
    return ($ids | Sort-Object { if ($_ -match '(\d+)$') { [int]$Matches[1] } else { 0 } }, { $_ } -Descending | Select-Object -First 1)
}
function Install-WingetBySignature([string]$Wg, [string]$Id) {
    $null = Invoke-External -Exe $Wg -Arguments @('show', '--id', $Id, '--exact', '--accept-source-agreements', '--disable-interactivity') -TimeoutMin 3 -Capture
    $url = ''; $type = ''; $pub = ''
    foreach ($l in @($Script:Captured)) {
        if (-not $url -and $l -match '^\s*Installer[- ]?(Url|URL|Adresse)\s*:\s*(https?://\S+)') { $url = $Matches[2] }
        elseif (-not $type -and $l -match '^\s*Installer[- ]?(Type|typ|Typ)\s*:\s*(\w+)') { $type = $Matches[2].ToLower() }
        elseif (-not $pub -and $l -match '^\s*(Publisher|Herausgeber)\s*:\s*(.+)$') { $pub = $Matches[2].Trim() }
    }
    if (-not $url) { Write-PLog '   Installer-Adresse nicht ermittelbar.' 'WARN'; return $false }
    $args1 = switch -Regex ($type) { '^(nullsoft)$' { @('/S') } '^(inno)$' { @('/VERYSILENT', '/SUPPRESSMSGBOXES', '/NORESTART', '/SP-') } '^(msi|wix)$' { @('/qn', '/norestart') } '^(burn)$' { @('/quiet', '/norestart') } default { $null } }
    if ($null -eq $args1) { Write-PLog ('   Installer-Typ "{0}" lässt sich nicht still installieren - bitte von Hand: {1}' -f $type, $url) 'WARN'; return $false }
    $dl = Join-Path $Script:DataDir 'Downloads'; New-Item $dl -ItemType Directory -Force | Out-Null
    $ext = if ($type -in 'msi', 'wix') { '.msi' } else { '.exe' }
    $file = Join-Path $dl (($Id -replace '[^\w\.\-]', '_') + $ext)
    try { Invoke-WebRequest -Uri $url -OutFile $file -UseBasicParsing -TimeoutSec 1800 -UserAgent $Script:BrowserUA } catch { Write-PLog ('   Download fehlgeschlagen: {0}' -f $_.Exception.Message) 'WARN'; return $false }
    $sig = Get-AuthenticodeSignature -FilePath $file
    $subj = if ($sig.SignerCertificate) { [string]$sig.SignerCertificate.Subject } else { '' }
    $np = ($pub -replace '[^A-Za-z0-9]', '').ToLower(); $ns = ($subj -replace '[^A-Za-z0-9]', '').ToLower()
    $match = $np.Length -ge 4 -and $ns.Contains($np.Substring(0, [math]::Min(5, $np.Length)))
    if ($sig.Status -ne 'Valid' -or -not $match) {
        Write-PLog ('   Nicht installiert: Signatur {0}, Unterzeichner "{1}" passt nicht sicher zum Herausgeber "{2}".' -f $sig.Status, $subj, $pub) 'WARN'
        Remove-Item -LiteralPath $file -Force -ErrorAction SilentlyContinue; return $false
    }
    Write-PLog ('   Signatur gültig: {0}' -f $subj) 'OK'
    $code = if ($ext -eq '.msi') { Invoke-External -Exe (Join-Path $env:windir 'System32\msiexec.exe') -Arguments (@('/i', ('"{0}"' -f $file)) + $args1) -TimeoutMin 30 -Quiet } else { Invoke-External -Exe $file -Arguments $args1 -TimeoutMin 30 -Quiet }
    Remove-Item -LiteralPath $file -Force -ErrorAction SilentlyContinue
    if ($code -in 3010, 1641) { $Script:RebootNeeded = $true }
    return ($code -in 0, 3010, 1641)
}
function Install-OfficeDefault {
    $c2r = Get-ItemProperty 'HKLM:\SOFTWARE\Microsoft\Office\ClickToRun\Configuration' -ErrorAction SilentlyContinue
    if ($c2r -and $c2r.ProductReleaseIds) { Write-PLog ('   Office ist bereits installiert ({0}) - Updates macht Office selbst.' -f $c2r.ProductReleaseIds) 'OK'; return $true }
    Write-PLog '   Office über das Office Deployment Tool von Microsoft (winget-Paket hat eine veraltete Prüfsumme)'
    $keep = $Script:JobOpts
    try {
        $Script:JobOpts = [pscustomobject]@{ Mode = 'Install'; Product = 'O365ProPlusRetail'; Channel = 'Current'; Lang = 'de-de'; Exclude = @('Teams', 'Access', 'Publisher', 'Lync', 'Groove'); Extra = @(); Target = '' }
        Invoke-OfficeJob
        $c2r = Get-ItemProperty 'HKLM:\SOFTWARE\Microsoft\Office\ClickToRun\Configuration' -ErrorAction SilentlyContinue
        return [bool]($c2r -and $c2r.ProductReleaseIds)
    } catch { Write-PLog ('   Office: {0}' -f $_.Exception.Message) 'WARN'; return $false }
    finally { $Script:JobOpts = $keep }
}
