function Test-ArpInstalled([string]$Pattern) {
    $keys = 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*', 'HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*', 'HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*'
    $hit = Get-ItemProperty $keys -ErrorAction SilentlyContinue | Where-Object { $_.DisplayName -like "*$Pattern*" } | Select-Object -First 1
    return $hit
}
function Install-DirectSource([string]$Key, [switch]$Update) {
    $src = $Script:DirectSources[$Key]
    if (-not $src) { Write-PLog ('Unbekannte Quelle: {0}' -f $Key) 'WARN'; return $false }
    try { [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12 } catch { }
    $dl = Join-Path $Script:DataDir 'Downloads'
    New-Item $dl -ItemType Directory -Force | Out-Null
    $Script:Detail = ('{0}: Download-Link beim Hersteller ermitteln' -f $src.Name)
    Set-PStatus ('{0} wird installiert' -f $src.Name)
    $have = Test-ArpInstalled $src.ArpName
    if ($have -and -not $Update) { Write-PLog ('{0} ist bereits installiert (Version {1})' -f $src.Name, $have.DisplayVersion) 'OK'; return $true }
    $urls = [System.Collections.Generic.List[string]]::new()
    $ref = ''
    foreach ($page in $src.Pages) {
        try {
            $html = try { (Invoke-WebRequest -Uri $page -UseBasicParsing -TimeoutSec 30 -UserAgent $Script:BrowserUA -ErrorAction Stop).Content } catch { Write-PLog ('   {0}: {1} - versuche es wie ein Browser ...' -f $page, $_.Exception.Message); Get-WebHtml $page }
            foreach ($m in [regex]::Matches($html, $src.Pattern)) { if (-not $urls.Contains($m.Value)) { $urls.Add($m.Value); if (-not $ref) { $ref = $page } } }
        } catch { Write-PLog ('   {0} nicht erreichbar: {1}' -f $page, $_.Exception.Message) }
    }
    if (-not $urls.Count) { Write-PLog ('{0}: kein Download-Link gefunden - bitte manuell laden: {1}' -f $src.Name, $src.Manual) 'WARN'; return $false }
    # neueste Datei zuerst (Zeitstempel oder Versionsnummer im Dateinamen)
    $sorted = @($urls | Sort-Object { if ($_ -match '(\d{6,14})\.exe$') { [int64]$Matches[1] } elseif ($_ -match '_(\d+)x?\.exe$') { [int64]$Matches[1] } else { 0 } }, { $_ -notmatch 'sac\.sk' } -Descending)
    if ($have) {
        # nur aktualisieren, wenn der Hersteller wirklich eine neuere Version anbietet (z.B. hwi64_850.exe = 8.50 gegenüber installierter 7.10)
        $newN = if ($sorted[0] -match '_(\d{2,5})x?\.exe$') { $Matches[1] } else { '' }
        $haveN = ([string]$have.DisplayVersion -replace '[^\d]', '')
        if ($newN -and $haveN) { $len = [math]::Max($newN.Length, $haveN.Length); $a = [int64]($newN.PadRight($len, '0')); $b = [int64]($haveN.Substring(0, [math]::Min($haveN.Length, $len)).PadRight($len, '0'))
            if ($a -le $b) { Write-PLog ('{0} ist aktuell (Version {1})' -f $src.Name, $have.DisplayVersion) 'OK'; return $true }
            Write-PLog ('{0}: Version {1} installiert, beim Hersteller gibt es eine neuere - wird aktualisiert' -f $src.Name, $have.DisplayVersion) }
        else { Write-PLog ('{0} ist bereits installiert (Version {1})' -f $src.Name, $have.DisplayVersion) 'OK'; return $true }
    }
    foreach ($url in $sorted) {
        $file = Join-Path $dl ([IO.Path]::GetFileName(([uri]$url).AbsolutePath))
        Write-PLog ('{0}: lade {1}' -f $src.Name, $url)
        $Script:Detail = ('{0}: Download läuft' -f $src.Name); Update-PHeartbeat
        $okDl = $false
        foreach ($try in 1, 2) {
            try {
                $h = @{}
                if ($try -eq 1) { $h['Accept-Language'] = 'de-DE,de;q=0.9,en;q=0.8'; if ($ref) { $h['Referer'] = $ref } }
                Invoke-WebRequest -Uri $url -OutFile $file -UseBasicParsing -TimeoutSec 1800 -UserAgent $Script:BrowserUA -Headers $h
                $okDl = $true; break
            } catch { $err = $_.Exception.Message }
        }
        if (-not $okDl) {
            try { Start-BitsTransfer -Source $url -Destination $file -ErrorAction Stop; $okDl = $true } catch { }
        }
        if (-not $okDl) {
            # wie ein Browser laden (curl mit Browser-Kennung, Herkunftsseite und Sprache) - viele Hersteller-CDNs sperren sonst mit 403
            $curl = Join-Path $env:SystemRoot 'System32\curl.exe'
            if (Test-Path -LiteralPath $curl) {
                $ca = @('-s', '-L', '--max-time', '1800', '-A', $Script:BrowserUA, '-H', 'Accept: text/html,application/xhtml+xml,application/octet-stream,*/*;q=0.8', '-H', 'Accept-Language: de-DE,de;q=0.9,en;q=0.8', '-o', $file, '-w', '%{http_code}')
                if ($ref) { $ca += @('-e', $ref) } else { $ca += @('-e', ('{0}://{1}/' -f ([uri]$url).Scheme, ([uri]$url).Host)) }
                $hc = (& $curl @ca $url 2>$null) -join ''
                if ($hc -eq '200' -and (Test-Path -LiteralPath $file) -and (Get-Item -LiteralPath $file).Length -gt 100KB) { $okDl = $true; Write-PLog '   Download über curl (Browser-Kennung) erfolgreich.' } else { $err = 'HTTP ' + $hc; Remove-Item -LiteralPath $file -Force -ErrorAction SilentlyContinue }
            }
        }
        if (-not $okDl) { Write-PLog ('   Download fehlgeschlagen: {0}' -f $err) 'WARN'; continue }
        $sig = Get-AuthenticodeSignature -FilePath $file
        $signer = if ($sig.SignerCertificate) { $sig.SignerCertificate.Subject } else { '' }
        if ($sig.Status -ne 'Valid' -or $signer -notmatch $src.Signer) {
            Write-PLog ('{0}: Signatur ungültig oder unerwarteter Herausgeber ({1}, {2}) - Installation abgebrochen' -f $src.Name, $sig.Status, $signer) 'WARN'
            Remove-Item -LiteralPath $file -Force -ErrorAction SilentlyContinue
            return $false
        }
        Write-PLog ('   Signatur geprüft: {0}' -f $signer) 'OK'
        $Script:Detail = ('{0}: Installation läuft' -f $src.Name)
        $code = Invoke-External -Exe $file -Arguments @($src.Args -split ' ') -TimeoutMin 30 -Quiet
        Remove-Item -LiteralPath $file -Force -ErrorAction SilentlyContinue
        if ($code -eq 0 -or (Test-ArpInstalled $src.ArpName)) { Write-PLog ('{0}: installiert' -f $src.Name) 'OK'; return $true }
        Write-PLog ('{0}: Installation fehlgeschlagen (Code {1})' -f $src.Name, $code) 'WARN'; return $false
    }
    Write-PLog ('{0}: kein Download möglich - bitte manuell laden: {1}' -f $src.Name, $src.Manual) 'WARN'
    return $false
}
function Invoke-DirectInstall {
    $keys = @($Script:DirectApps | ForEach-Object { "$_".Trim() } | Where-Object { $_ })
    foreach ($k in $keys) { if (Test-PCancel) { break }; $null = Install-DirectSource $k }
}
function Invoke-StoreUpdate {
    try {
        Get-CimInstance -Namespace 'root\cimv2\mdm\dmmap' -ClassName 'MDM_EnterpriseModernAppManagement_AppManagement01' -ErrorAction Stop |
            Invoke-CimMethod -MethodName UpdateScanMethod -ErrorAction Stop | Out-Null
        Write-PLog 'Store-Update angestoßen (läuft im Hintergrund weiter)' 'OK'
    } catch { Write-PLog 'Store-Update nur als SYSTEM möglich (läuft automatisch über den Zeitplan)' }
}
function Invoke-DefenderUpdate {
    try {
        $st = Get-MpComputerStatus -ErrorAction Stop
        if (-not $st.AntivirusEnabled) { Write-PLog 'Defender ist nicht der aktive Virenscanner - übersprungen'; return }
        if ($Script:CheckOnly) { Write-PLog ('Defender-Signaturen vom {0:dd.MM.yyyy HH:mm}' -f $st.AntivirusSignatureLastUpdated); return }
        Update-MpSignature -ErrorAction Stop
        Write-PLog 'Defender-Signaturen aktualisiert' 'OK'
    } catch { Write-PLog ('Defender: {0}' -f $_.Exception.Message) 'WARN' }
}
# Explorer-Wächter: Manche Installer (z.B. Nextcloud, Treiber) beenden den Explorer.
# Fehlt er länger als 45 Sekunden, während ein Benutzer angemeldet ist, wird er in dessen Sitzung neu gestartet.
function Restore-Explorer {
    if ($Script:ExplorerCheck.Elapsed.TotalSeconds -lt 5) { return }
    $Script:ExplorerCheck.Restart()
    $user = $null
    try { $user = (Get-CimInstance Win32_ComputerSystem -ErrorAction Stop).UserName } catch { }
    if (-not $user) { $Script:ExplorerMissingSince = $null; return }
    $ex = @(Get-Process -Name explorer -ErrorAction SilentlyContinue | Where-Object { $_.SessionId -gt 0 })
    if ($ex.Count) { $Script:ExplorerMissingSince = $null; return }
    if (-not $Script:ExplorerMissingSince) { $Script:ExplorerMissingSince = Get-Date; return }
    if (((Get-Date) - $Script:ExplorerMissingSince).TotalSeconds -lt 45) { return }
    $Script:ExplorerMissingSince = $null
    Write-PLog 'Explorer wurde von einem Installer beendet - wird neu gestartet'
    try {
        $grp = (New-Object Security.Principal.SecurityIdentifier 'S-1-5-4').Translate([Security.Principal.NTAccount]).Value
        $tn  = 'PCPflege_ExplorerRestart'
        $act = New-ScheduledTaskAction -Execute (Join-Path $env:SystemRoot 'explorer.exe')
        $pr  = New-ScheduledTaskPrincipal -GroupId $grp -RunLevel Limited
        Register-ScheduledTask -TaskName $tn -Action $act -Principal $pr -Force | Out-Null
        Start-ScheduledTask -TaskName $tn
        Start-Sleep -Seconds 3
        Unregister-ScheduledTask -TaskName $tn -Confirm:$false -ErrorAction SilentlyContinue
        Write-PLog 'Explorer neu gestartet' 'OK'
    } catch { Write-PLog ('Explorer-Neustart fehlgeschlagen: {0}' -f $_.Exception.Message) 'WARN' }
}

# Startet ein externes Programm, streamt die Ausgabe ins Protokoll, unterstützt Abbrechen und Zeitlimit
function Invoke-External {
    param([string]$Exe, [string[]]$Arguments = @(), [int]$TimeoutMin = 120, [switch]$Quiet, [switch]$Capture, [switch]$OemEncoding)
    if ($Capture) { $Script:Captured.Clear() }
    $psi = New-Object System.Diagnostics.ProcessStartInfo
    $psi.FileName = $Exe
    $psi.Arguments = ($Arguments -join ' ')
    $psi.UseShellExecute = $false
    $psi.CreateNoWindow = $true
    $psi.RedirectStandardInput  = $true
    $psi.RedirectStandardOutput = $true
    $psi.RedirectStandardError  = $true
    if ($OemEncoding) {
        $enc = [Text.Encoding]::GetEncoding([Globalization.CultureInfo]::CurrentCulture.TextInfo.OEMCodePage)
        $psi.StandardOutputEncoding = $enc; $psi.StandardErrorEncoding = $enc
    } elseif (-not $Quiet -or $Capture) { $psi.StandardOutputEncoding = [Text.Encoding]::UTF8; $psi.StandardErrorEncoding = [Text.Encoding]::UTF8 }
    $p = New-Object System.Diagnostics.Process
    $p.StartInfo = $psi
    try { [void]$p.Start() } catch { Write-PLog ('{0} konnte nicht gestartet werden: {1}' -f (Split-Path $Exe -Leaf), $_.Exception.Message) 'WARN'; return -1 }
    try { $p.StandardInput.Close() } catch { }
    $outT = $p.StandardOutput.ReadLineAsync()
    $errT = $p.StandardError.ReadLineAsync()
    $sw = [Diagnostics.Stopwatch]::StartNew()
    $last = ''
    $killed = $false
    $exitSeen = $null
    while ($outT -or $errT) {
        $got = $false
        foreach ($which in 'out', 'err') {
            $t = if ($which -eq 'out') { $outT } else { $errT }
            if ($t -and $t.IsCompleted) {
                $got = $true
                $l = $null; try { $l = $t.Result } catch { }
                if ($null -eq $l) { if ($which -eq 'out') { $outT = $null } else { $errT = $null }; continue }
                if ($which -eq 'out') { $outT = $p.StandardOutput.ReadLineAsync() } else { $errT = $p.StandardError.ReadLineAsync() }
                if ($Capture) { $Script:Captured.Add($l); continue }
                if ($Quiet) { continue }
                $x = ($l -replace "`0", '').Trim()
                if (-not $x -or $x -eq $last) { continue }
                if ($x -match '\d{1,3}\s?%' -and $x.Length -lt 160) { $Script:LastLine = $x; Update-PHeartbeat; continue }
                if ($x -match '^[\s\-\\|/]+$' -or $x -match '[▀-▟]' -or $x -match '^[\d\.,]+\s*[KMG]?B\s*/\s*[\d\.,]+\s*[KMG]?B$' -or $x -match '^\d{1,3}\s*%$') { continue }
                $last = $x
                Write-PLog ('   {0}' -f $x)
            }
        }
        if ($got) { continue }
        if ((Test-PCancel) -or $sw.Elapsed.TotalMinutes -gt $TimeoutMin) {
            $why = if (Test-PCancel) { 'abgebrochen' } else { ('Zeitlimit {0} Min. überschritten' -f $TimeoutMin) }
            Write-PLog ('{0}: {1} - Prozess wird beendet' -f (Split-Path $Exe -Leaf), $why) 'WARN'
            & taskkill.exe /PID $p.Id /T /F 2>&1 | Out-Null
            $killed = $true
            break
        }
        Restore-Explorer
        Update-PHeartbeat
        if ($p.HasExited) {
            # Programm ist fertig - Kindprozesse können die Ausgabe noch offen halten, daher nur kurz nachlesen
            if (-not $exitSeen) { $exitSeen = [Diagnostics.Stopwatch]::StartNew() }
            elseif ($exitSeen.Elapsed.TotalSeconds -gt 3) { break }
        }
        Start-Sleep -Milliseconds 200
    }
    try { [void]$p.WaitForExit(10000) } catch { }
    $code = if ($killed) { -1 } else { try { $p.ExitCode } catch { -1 } }
    return $code
}
function Invoke-Tool {
    param([string]$Exe, [string[]]$Arguments, [int]$TimeoutMin = 180, [switch]$Quiet)
    Write-PLog ('Starte {0} {1}' -f (Split-Path $Exe -Leaf), ($Arguments -join ' '))
    $code = Invoke-External -Exe $Exe -Arguments $Arguments -TimeoutMin $TimeoutMin -Quiet:$Quiet
    Write-PLog ('{0} beendet mit Code {1}' -f (Split-Path $Exe -Leaf), $code)
    return $code
}
function Find-Tool { param([string[]]$Candidates) $Candidates | Where-Object { $_ -and (Test-Path -LiteralPath $_) } | Select-Object -First 1 }

function ConvertTo-ShortVersion([string]$v) {
    $parts = @(([string]$v) -split '[^\d]+' | Where-Object { $_ -ne '' } | Select-Object -First 4 | ForEach-Object { [int]$_ })
    if (-not $parts.Count) { return $null }
    while ($parts.Count -lt 4) { $parts += 0 }
    return [version]('{0}.{1}.{2}.{3}' -f $parts[0], $parts[1], $parts[2], $parts[3])
}

# Hersteller erkennen und passendes Update-Tool bestimmen
function Get-OemInfo {
    $cs  = Get-CimInstance Win32_ComputerSystem
    $man = [string]$cs.Manufacturer
    $pf86 = ${env:ProgramFiles(x86)}; $pf = $env:ProgramFiles
    $custom = [string]$Script:Cfg.Update.OEMToolPath
    $info = [ordered]@{ Vendor = $man; Model = [string]$cs.Model; Tool = $null; WingetId = $null; Exe = $null; Candidates = @() }
    if ($man -match 'Dell') {
        $classic = Join-Path $pf86 'Dell\CommandUpdate\dcu-cli.exe'
        $univ    = Join-Path $pf 'Dell\CommandUpdate\dcu-cli.exe'
        if (Test-Path -LiteralPath $classic) { $info.Tool = 'Dell Command | Update'; $info.WingetId = 'Dell.CommandUpdate'; $info.Exe = $classic }
        else { $info.Tool = 'Dell Command | Update (Universal)'; $info.WingetId = 'Dell.CommandUpdate.Universal'; $info.Exe = $univ }
        $info.Vendor = 'Dell'
    }
    elseif ($man -match 'HP|Hewlett') {
        $info.Vendor = 'HP'; $info.Tool = 'HP Image Assistant'; $info.WingetId = 'HP.ImageAssistant'
        $info.Exe = 'C:\SWSetup\HPImageAssistant\HPImageAssistant.exe'
        $info.Candidates = @((Join-Path $pf 'HP\HPIA\HPImageAssistant.exe'), (Join-Path $pf86 'HP\HPIA\HPImageAssistant.exe'), 'C:\HPIA\HPImageAssistant.exe')
    }
    elseif ($man -match 'Lenovo') {
        $info.Vendor = 'Lenovo'; $info.Tool = 'Lenovo Thin Installer'; $info.WingetId = 'Lenovo.ThinInstaller'
        $info.Exe = Join-Path $pf86 'Lenovo\ThinInstaller\ThinInstaller.exe'
        $info.Candidates = @((Join-Path $pf 'Lenovo\ThinInstaller\ThinInstaller.exe'))
    }
    if ($custom -and (Test-Path -LiteralPath $custom)) { $info.Exe = $custom }
    elseif ($info.Exe -and -not (Test-Path -LiteralPath $info.Exe)) {
        $alt = Find-Tool $info.Candidates
        if ($alt) { $info.Exe = $alt }
    }
    return [pscustomobject]$info
}

# Hersteller-Tool installieren bzw. auf die aktuelle Version bringen (über winget)
function Install-OemTool($Info) {
    $have = $null
    if ($Info.Exe -and (Test-Path -LiteralPath $Info.Exe)) {
        try { $vi = (Get-Item -LiteralPath $Info.Exe).VersionInfo; $have = ConvertTo-ShortVersion $(if ($vi.ProductVersion) { $vi.ProductVersion } else { $vi.FileVersion }) } catch { }
    }
    if (-not $Script:Cfg.Update.OEMAutoInstall) {
        if (-not $have) { Write-PLog ('{0} ist nicht installiert (automatische Installation ist ausgeschaltet)' -f $Info.Tool) 'WARN' }
        return
    }
    $wg = Get-WingetPath
    if (-not $wg) { Write-PLog 'winget fehlt - Hersteller-Tool kann nicht automatisch installiert werden' 'WARN'; return }
    $Script:Detail = ('{0}: Versionsprüfung' -f $Info.Tool); Update-PHeartbeat
    $null = Invoke-External -Exe $wg -Arguments @('show', '--id', $Info.WingetId, '--exact', '--accept-source-agreements', '--disable-interactivity') -TimeoutMin 3 -Capture
    $latestTxt = $null
    foreach ($l in $Script:Captured) { if ($l -match '^\s*Version\s*:\s*([\d][\d\.]*)') { $latestTxt = $Matches[1]; break } }
    $latest = ConvertTo-ShortVersion $latestTxt
    Write-PLog ('{0}: installiert {1}, aktuell verfügbar {2}' -f $Info.Tool, $(if ($have) { $have } else { '-' }), $(if ($latestTxt) { $latestTxt } else { 'unbekannt' }))
    $needs = (-not $have) -or ($latest -and $have -lt $latest)
    if (-not $needs) { Write-PLog ('{0} ist aktuell' -f $Info.Tool) 'OK'; return }
    if ($Script:CheckOnly) { Write-PLog ('{0} würde jetzt {1}' -f $Info.Tool, $(if ($have) { 'aktualisiert' } else { 'installiert' })); return }
    $Script:Detail = ('{0} wird {1}' -f $Info.Tool, $(if ($have) { 'aktualisiert' } else { 'installiert' }))
    Set-PStatus ('{0} wird eingerichtet' -f $Info.Tool)
    Write-PLog ('{0} wird {1} ...' -f $Info.Tool, $(if ($have) { 'aktualisiert' } else { 'installiert' }))
    $code = Invoke-External -Exe $wg -Arguments @('install', '--id', $Info.WingetId, '--exact', '--silent', '--force',
                                                 '--accept-package-agreements', '--accept-source-agreements', '--disable-interactivity') -TimeoutMin 20
    # Pfad neu ermitteln (z.B. Dell Universal vs. klassisch)
    $new = Get-OemInfo
    $Info.Exe = $new.Exe
    if ($Info.Exe -and (Test-Path -LiteralPath $Info.Exe)) { Write-PLog ('{0} bereit: {1}' -f $Info.Tool, $Info.Exe) 'OK' }
    else { Write-PLog ('{0}: Installation fehlgeschlagen (Code {1})' -f $Info.Tool, $code) 'WARN' }
}

function Invoke-OemUpdates {
    $info = Get-OemInfo
    Write-PLog ('Hersteller: {0} {1}' -f $info.Vendor, $info.Model)
    if (-not $info.Tool) {
        Write-PLog ('Für "{0}" gibt es kein unterstütztes Update-Tool - Treiber kommen über Windows Update' -f $info.Vendor)
        return
    }
    Install-OemTool $info
    if (-not ($info.Exe -and (Test-Path -LiteralPath $info.Exe))) { Write-PLog ('{0} nicht verfügbar - Schritt übersprungen' -f $info.Tool) 'WARN'; return }
    if (Test-PCancel) { return }

    $fw  = [bool]$Script:Cfg.Update.OEMFirmware
    if (-not $Script:CheckOnly) { try { Invoke-DsBeforeDriverUpdate ('Hersteller-Update ' + $info.Vendor) } catch { } }
    $exe = $info.Exe
    $rep = Join-Path $Script:DataDir 'OEM'
    New-Item $rep -ItemType Directory -Force | Out-Null

    switch ($info.Vendor) {
        'Dell' {
            $types = 'driver,application'; if ($fw) { $types += ',bios,firmware' }
            if ($Script:CheckOnly) { $a = @('/scan', '-silent', ('-updateType={0}' -f $types)) }
            else {
                $a = @('/applyUpdates', '-silent', '-reboot=disable', ('-updateType={0}' -f $types))
                if ($fw) { $a += '-autoSuspendBitLocker=enable' }
            }
            $Script:Detail = 'Dell Command | Update sucht und installiert Dell-Updates'
            Set-PStatus 'Dell Command | Update arbeitet'
            $code = Invoke-Tool $exe $a -TimeoutMin ([math]::Max(30, [int]$Script:Cfg.Settings.OemTimeout))
            switch ($code) {
                0   { Write-PLog 'Dell: erfolgreich' 'OK' }
                1   { $Script:RebootNeeded = $true; Write-PLog 'Dell: Neustart erforderlich' 'OK' }
                5   { $Script:RebootNeeded = $true; Write-PLog 'Dell: Neustart erforderlich' 'OK' }
                500 { Write-PLog 'Dell: keine Updates - alles aktuell' 'OK' }
                default { Write-PLog ('Dell: Code {0} (siehe C:\ProgramData\Dell\UpdateService\Log)' -f $code) 'WARN' }
            }
        }
        'HP' {
            $cat    = if ($fw) { 'Drivers,Firmware,BIOS' } else { 'Drivers' }
            $action = if ($Script:CheckOnly) { 'List' } else { 'Install' }
            $spDir  = Join-Path $rep 'HPIA_SoftPaqs'
            $a = @('/Operation:Analyze', ('/Action:{0}' -f $action), '/Selection:All', ('/Category:{0}' -f $cat), '/Silent',
                   ('/ReportFolder:"{0}"' -f (Join-Path $rep 'HPIA_Report')), ('/SoftpaqDownloadFolder:"{0}"' -f $spDir))
            $Script:Detail = 'HP Image Assistant: Analyse, Download und Installation der HP-Pakete (keine Zwischenmeldungen - siehe aktive Prozesse)'
            Set-PStatus 'HP Image Assistant arbeitet'
            $code = Invoke-Tool $exe $a -TimeoutMin ([math]::Max(30, [int]$Script:Cfg.Settings.OemTimeout)) -Quiet
            if ($code -eq 3010) { $Script:RebootNeeded = $true }
            if ($code -eq 256) { Write-PLog 'HP: keine Empfehlungen - Treiber aktuell' 'OK' }
            $json = Get-ChildItem (Join-Path $rep 'HPIA_Report') -Filter '*.json' -ErrorAction SilentlyContinue | Sort-Object LastWriteTime -Descending | Select-Object -First 1
            if ($json) {
                try {
                    $r = Get-Content $json.FullName -Raw -Encoding UTF8 | ConvertFrom-Json
                    foreach ($x in $r.HPIA.Recommendations) {
                        $okx = [string]$x.Remediation.Status -match 'COMPLETED'
                        Write-PLog ('   {0} {1}: {2}' -f $x.Name, $x.RecommendationValue, $x.Remediation.ReturnDescription) $(if ($okx) { 'OK' } elseif ($Script:CheckOnly) { 'INFO' } else { 'WARN' })
                        if ([string]$x.Remediation.ReturnDescription -match '(?<!NO)REBOOT=') { $Script:RebootNeeded = $true }
                    }
                } catch { }
            }
            if (-not $Script:CheckOnly) { $null = Remove-OldFiles -Path $spDir -Days 0 -Recurse }
        }
        'Lenovo' {
            $pt = if ($fw) { '1,2,3,4' } else { '1,2' }
            $rb = if ($fw) { '0,3,5' } else { '0,3' }
            $action = if ($Script:CheckOnly) { 'SCAN' } else { 'INSTALL' }
            $a = @('/CM', '-search', 'A', '-action', $action, '-packagetypes', $pt, '-includerebootpackages', $rb, '-noicon', '-noreboot', '-nolicense', '-exporttowmi')
            $Script:Detail = 'Lenovo Thin Installer sucht und installiert Lenovo-Updates'
            Set-PStatus 'Lenovo Thin Installer arbeitet'
            $t0 = Get-Date
            $code = Invoke-Tool $exe $a -TimeoutMin ([math]::Max(30, [int]$Script:Cfg.Settings.OemTimeout)) -Quiet
            $secs = ((Get-Date) - $t0).TotalSeconds
            if ($code -eq 0 -and $secs -lt 20 -and -not $Script:CheckOnly) {
                # Thin Installer hat sofort beendet: Protokoll auswerten statt blind "erfolgreich" zu melden
                $lgd = Join-Path (Split-Path $exe) 'logs'
                $lg = @(Get-ChildItem -LiteralPath $lgd -File -Recurse -ErrorAction SilentlyContinue | Where-Object { $_.LastWriteTime -ge $t0.AddSeconds(-5) } | Sort-Object LastWriteTime -Descending | Select-Object -First 1)
                if ($lg.Count) {
                    $hits = @(Get-Content -LiteralPath $lg[0].FullName -Tail 400 -ErrorAction SilentlyContinue | Where-Object { $_ -match '(?i)error|fail|exception|repository|no update|not applicable|install(ed|ing)|download' } | Select-Object -Last 8)
                    Write-PLog ('Lenovo Thin Installer war nach {0:N0} Sekunden fertig - Auszug aus {1}:' -f $secs, $lg[0].Name)
                    foreach ($h in $hits) { Write-PLog ('   ' + $h.Trim()) }
                } else { Write-PLog ('Lenovo Thin Installer war nach {0:N0} Sekunden ohne Protokoll fertig - vermutlich keine passenden Updates oder kein Zugriff auf das Lenovo-Repository. Alternative: Seite Treiber > Hersteller-Treiberpaket.' -f $secs) 'WARN' }
            }
            switch ($code) {
                0     { Write-PLog 'Lenovo: erfolgreich' 'OK' }
                3010  { $Script:RebootNeeded = $true; Write-PLog 'Lenovo: Neustart erforderlich' 'OK' }
                10000 { Write-PLog 'Lenovo: keine Updates - alles aktuell' 'OK' }
                10001 { Write-PLog 'Lenovo: Updates verfügbar' }
                default { Write-PLog ('Lenovo: Code {0} (Logs unter {1})' -f $code, (Join-Path (Split-Path $exe) 'logs')) 'WARN' }
            }
            $hist = Join-Path (Split-Path $exe) 'logs\update_history.txt'
            if (-not $Script:CheckOnly -and (Test-Path -LiteralPath $hist)) {
                Get-Content -LiteralPath $hist -Tail 15 -ErrorAction SilentlyContinue | Where-Object { $_.Trim() } | ForEach-Object { Write-PLog ('   {0}' -f $_.Trim()) }
            }
        }
    }
}

# ------------------------------------------------------------------ ABLAUF
function Invoke-PflegeRun {
    param($Config, [string[]]$Parts = @('Clean', 'Optimize', 'Update'), [switch]$Analyze, [switch]$CheckOnly, [string]$LogFile = '')
    $Script:Cfg = $Config
    $Script:DryRun = [bool]$Analyze
    $Script:CheckOnly = [bool]$CheckOnly
    $Script:Freed = [int64]0; $Script:RebootNeeded = $false; $Script:UpdatesInstalled = 0; $Script:Warnings = 0
    New-Item -Path $Script:LogDir -ItemType Directory -Force | Out-Null
    $Script:LogFile = if ($LogFile) { $LogFile } else { Join-Path $Script:LogDir ('PCPflege_{0:yyyyMMdd_HHmmss}.log' -f (Get-Date)) }
    if ($null -ne $sync) { $sync.Running = $true }
    $start = Get-Date
    try {
        $C = $Config
        $exec    = -not $Analyze -and -not $CheckOnly
        $doClean = ($Parts -contains 'Clean') -and -not $CheckOnly
        $doOpt   = ($Parts -contains 'Optimize') -and $exec
        $doUpd   = ($Parts -contains 'Update') -and -not $Analyze
        $doInst  = ($Parts -contains 'NiniteInstall') -and $exec
        $doWgIn  = ($Parts -contains 'WingetInstall') -and $exec
        $doChIn  = ($Parts -contains 'ChocoInstall') -and $exec
        $doDirIn = ($Parts -contains 'DirectInstall') -and $exec
        $doDiag  = ($Parts -contains 'Diag')
        $doDrv   = ($Parts -contains 'Drivers') -and -not $Analyze
        $doWuDrv = ($Parts -contains 'WUDrivers') -and -not $Analyze
        $doOemD  = ($Parts -contains 'OemDrivers') -and -not $Analyze
        $doGpu   = ($Parts -contains 'GpuDriver') -and -not $Analyze
        $doDrvBk = ($Parts -contains 'DriverBackup') -and $exec
        $doIntel = ($Parts -contains 'IntelAll') -and -not $Analyze
        $doIntW  = ($Parts -contains 'IntelWireless') -and -not $Analyze
        $doDsa   = ($Parts -contains 'IntelDsa') -and $exec
        $doAv    = ($Parts -contains 'AvInstall') -and $exec
        $doScan  = ($Parts -contains 'DefenderScan') -and $exec
        $doBloat = ($Parts -contains 'Debloat') -and $exec
        $doWinF  = ($Parts -contains 'WinFeatures') -and $exec
        $doIso   = ($Parts -contains 'WinIso') -and $exec
        $doOff   = ($Parts -contains 'Office') -and $exec
        $doUsb   = ($Parts -contains 'UsbBuild') -and $exec
        $doBak   = ($Parts -contains 'Backup') -and $exec
        $doImg   = ($Parts -contains 'Image') -and $exec
        $doRst   = ($Parts -contains 'Restore') -and $exec
        $doMigE  = ($Parts -contains 'MigrateExport') -and $exec
        $doMigI  = ($Parts -contains 'MigrateImport') -and $exec
        $doRep   = ($Parts -contains 'Repair') -and $exec
        $doWizB  = ($Parts -contains 'WizardBase') -and $exec
        $doWizC  = ($Parts -contains 'WizardCompany') -and $exec
        $doWizF  = ($Parts -contains 'WizardFinish') -and $exec
        $doOemP  = ($Parts -contains 'OemPack') -and -not $Analyze
        $doNetS  = ($Parts -contains 'NetSetup') -and $exec
        $doWinS  = ($Parts -contains 'WinSettingsImport') -and $exec
        $doBlS   = ($Parts -contains 'BitLockerSetup') -and $exec
        $doWuSel = ($Parts -contains 'WuSelected') -and $exec
        $doSurf  = ($Parts -contains 'SurfacePack') -and $exec
        $doSurfAll = ($Parts -contains 'SurfaceAll') -and $exec
        $doFb    = ($Parts -contains 'FullBackup') -and $exec
        $doFbV   = ($Parts -contains 'FullBackupVerify') -and $exec
        $doFbP   = ($Parts -contains 'FullBackupPrune') -and $exec
        $doFbK   = ($Parts -contains 'FullBackupPackage') -and $exec
        $doOk    = ($Parts -contains 'OneClick') -and $exec
        $doWr    = ($Parts -contains 'WinRepair') -and $exec
        $doWrIpu = ($Parts -contains 'WinRepairIpu') -and $exec
        $doTbL   = ($Parts -contains 'ToolboxLoad') -and $exec
        $doTbC   = ($Parts -contains 'ToolboxCopy') -and $exec
        $doRs    = ($Parts -contains 'RescueStick') -and $exec
        $doCcRun = ($Parts -contains 'CleanerRun') -and $exec
        $doCcWip = ($Parts -contains 'CleanerWipe') -and $exec
        $doPdrv  = ($Parts -contains 'ProblemDrivers') -and -not $Analyze
        $mode    = if ($Analyze) { 'Analyse (Probelauf, nichts wird gelöscht)' } elseif ($CheckOnly) { 'Update-Prüfung' } else { 'Ausführung' }
        Write-PLog ('===== PC-Tools {0} | {1} | {2} =====' -f $env:COMPUTERNAME, $mode, ($Parts -join ', '))
        Write-PLog ('Konto: {0}' -f [Security.Principal.WindowsIdentity]::GetCurrent().Name)

        $steps = [System.Collections.Generic.List[object]]::new()
        $add = { param($n, $a, $cl) $steps.Add([pscustomobject]@{ Name = $n; Action = $a; Clean = [bool]$cl }) }

        if ($exec -and ($doUpd -or $doOpt -or $doInst -or $doWgIn -or $doChIn -or $doDirIn -or $doDrv -or $doWuDrv -or $doOemD -or $doGpu -or $doOff -or $doMigI -or $doIntel -or $doIntW -or $doBloat -or $doWinF -or $doWizB -or $doWizC -or $doOemP -or $doWinS -or $doWuSel) -and $C.Optimize.RestorePoint) { & $add 'Wiederherstellungspunkt' { New-PflegeRestorePoint } $false }
        if ($exec -and ($doUpd -or $doDrv -or $doWuDrv -or $doOemD -or $doGpu -or $doInst -or $doWgIn -or $doChIn -or $doDirIn -or $doIntel -or $doIntW -or $doOemP)) { & $add 'Stand vorher festhalten' { Save-SystemSnapshot ('Vor: ' + ($Parts -join ', ')) } $false }
        if ($doWizB)  { & $add 'Grundeinstellungen (Assistent)' { Invoke-WizardBase } $false }
        if ($doWizC)  { & $add 'Unternehmens-Einstellungen' { Invoke-WizardCompany } $false }
        if ($doDrvBk) { & $add 'Treiber sichern' { Invoke-DriverBackup } $false }
        if ($doOemP)  { & $add 'Hersteller-Treiberpaket' { Invoke-OemDriverPack } $false }
        if ($doSurf)  { & $add 'Surface-Treiber- und Firmwarepaket' { Invoke-SurfacePackJob } $false }
        if ($doSurfAll) { & $add 'Surface: neueste Pakete aller Modelle' { Invoke-SurfaceAllJob } $false }
        if ($doFb)    { & $add 'Komplettsicherung (Systemabbild)' { Invoke-FbImageJob } $false }
        if ($doFbV)   { & $add 'Komplettsicherung prüfen' { Invoke-FbVerifyJob } $false }
        if ($doFbP)   { & $add 'Alte Komplettsicherungen entfernen' { Invoke-FbPruneJob } $false }
        if ($doFbK)   { & $add 'Wiederherstellungspaket schreiben' { Invoke-FbPackageJob } $false }
        if ($doCcRun) { & $add 'PC-Reiniger' { Invoke-CcCleanJob } $false }
        if ($doCcWip) { & $add 'Freien Speicher löschen' { Invoke-CcWipeJob } $false }
        if ($doOk)    { & $add 'Ein-Klick-Optimierung' { Invoke-OkJob } $false }
        if ($doWr)    { & $add 'Windows-Reparatur' { Invoke-WrRepairJob } $false }
        if ($doWrIpu) { & $add 'Reparaturinstallation (In-place Upgrade)' { Invoke-WrInPlaceJob } $false }
        if ($doTbL)   { & $add 'Toolbox: Werkzeuge laden' { Invoke-TbLoadJob } $false }
        if ($doTbC)   { & $add 'Toolbox auf USB-Stick kopieren' { Invoke-TbCopyJob } $false }
        if ($doRs)    { & $add 'Notfall-Stick' { Invoke-RsStickJob } $false }
        if ($doInst) { & $add 'Programme installieren (Ninite Pro)' { Invoke-NiniteInstall } $false }
        if ($doWgIn) { & $add 'Programme installieren (winget)' { Invoke-WingetInstall } $false }
        if ($doChIn) { & $add 'Programme installieren (Chocolatey)' { Invoke-ChocoInstall } $false }
        if ($doDirIn) { & $add 'Programme installieren (Hersteller-Download)' { Invoke-DirectInstall } $false }
        if ($doDiag)  { & $add 'Fehlerdaten sammeln' { Invoke-DiagCollect } $false }
        if ($doDrv)   { & $add 'Grafiktreiber' { Invoke-GpuDriverUpdate } $false; if ($C.Update.IntelDirect -ne $false) { & $add 'Intel WLAN und Bluetooth' { Invoke-IntelWirelessUpdate } $false }; & $add 'Treiber aus Windows Update' { Invoke-WUDrivers } $false; & $add 'Hersteller-Treiber und BIOS' { Invoke-OemUpdates } $false }
        if ($doIntel) { & $add 'Intel-Grafik' { Invoke-GpuDriverUpdate } $false; & $add 'Intel WLAN und Bluetooth' { Invoke-IntelWirelessUpdate } $false }
        if ($doIntW)  { & $add 'Intel WLAN und Bluetooth' { Invoke-IntelWirelessUpdate } $false }
        if ($doDsa)   { & $add 'Intel Driver & Support Assistant' { Invoke-IntelDsaInstall } $false }
        if ($doAv)    { & $add 'Virenschutz installieren' { Invoke-AvInstall } $false }
        if ($doScan)  { & $add 'Virenprüfung' { Invoke-DefenderScan } $false }
        if ($doBloat) { & $add 'Apps entfernen' { Invoke-Debloat } $false }
        if ($doWinF)  { & $add 'Windows-Funktionen installieren' { Invoke-WinFeatures } $false }
        if ($doPdrv)  { & $add 'Treiber für Geräte mit Problem' { Invoke-ProblemDriversStep $true } $false }
        if ($doWuDrv) { & $add 'Treiber aus Windows Update' { Invoke-WUDrivers -Ids @($Script:JobOpts.DriverIds) } $false }
        if ($doOemD)  { & $add 'Hersteller-Treiber und BIOS' { Invoke-OemUpdates } $false }
        if ($doGpu)   { & $add 'Grafiktreiber' { Invoke-GpuDriverUpdate } $false }
        if ($doIso)   { & $add 'Windows 11 ISO' { Invoke-WinIsoJob } $false }
        if ($doOff)   { & $add 'Office' { Invoke-OfficeJob } $false }
        if ($doUsb)   { & $add 'USB-Stick' { Invoke-UsbJob } $false }
        if ($doBak)   { & $add 'Datensicherung' { Invoke-BackupJob } $false }
        if ($doImg)   { & $add 'Systemabbild' { Invoke-ImageBackup ([string]$Script:Cfg.Backup.ImageTarget) } $false }
        if ($doRst)   { & $add 'Wiederherstellen' { Invoke-RestoreJob } $false }
        if ($doMigE)  { & $add 'Umzugspaket erstellen' { Invoke-MigrateExport } $false }
        if ($doMigI)  { & $add 'Daten und Einstellungen übernehmen' { Invoke-MigrateImport } $false }
        if ($doRep)   { & $add 'Fehlersuche und Reparatur' { Invoke-RepairJob } $false }
        if ($doWuSel) { & $add 'Ausgewählte Windows-Updates' { Invoke-WuSelected @($Script:JobOpts.UpdateIds) } $false }
        if ($doBlS)   { & $add 'BitLocker einschalten' { Invoke-BitLockerSetup ([string]$Script:JobOpts.KeyDir) } $false }
        if ($doNetS)  { & $add 'Netzlaufwerke und Drucker' { Invoke-NetSetupJob } $false }
        if ($doWinS)  { & $add 'Windows-Einstellungen übernehmen' { Invoke-WinSettingsImportJob } $false }
        if ($doUpd) {
            if ($C.Update.WindowsUpdate) { & $add 'Systempartition für Windows-Updates' { Repair-EspSpace } $false }
            if ($C.Update.WindowsUpdate) { & $add 'Windows Update' { Invoke-WindowsUpdate } $false }
            if ($C.Update.OEM)           { & $add 'Hersteller-Treiber' { Invoke-OemUpdates } $false }
            if ($C.Update.GpuDriver)     { & $add 'Grafiktreiber' { Invoke-GpuDriverUpdate } $false }
            if ($C.Update.Ninite)        { & $add 'Programme (Ninite Pro)' { Invoke-NiniteUpdate } $false }
            if ($C.Update.Winget)        { & $add 'Programme (winget)' { Invoke-Winget } $false }
            if ($C.Update.Choco)         { & $add 'Programme (Chocolatey)' { Invoke-ChocoUpdate } $false }
            if ($C.Update.StoreApps -and $exec) { & $add 'Store-Apps' { Invoke-StoreUpdate } $false }
            if ($C.Update.Defender)      { & $add 'Defender-Signaturen' { Invoke-DefenderUpdate } $false }
        }
        if ($doClean) {
            if ($C.Clean.UserTemp)         { & $add 'Temp-Dateien (Benutzer)' { Clear-UserTemp } $true }
            if ($C.Clean.WinTemp)          { & $add 'Temp-Dateien (Windows)' { Clear-WinTemp } $true }
            if ($C.Clean.WUCache)          { & $add 'Update-Downloadcache' { Clear-WUCache } $true }
            if ($C.Clean.DeliveryOpt)      { & $add 'Übermittlungsoptimierung' { Clear-DeliveryOpt } $true }
            if ($C.Clean.RecycleBin)       { & $add 'Papierkorb' { Clear-RecycleBins } $true }
            if ($C.Clean.ThumbCache)       { & $add 'Miniaturansichten-Cache' { Clear-ThumbCache } $true }
            if ($C.Clean.WER)              { & $add 'Fehlerberichte / Speicherabbilder' { Clear-ErrorReports } $true }
            if ($C.Clean.OldLogs)          { & $add 'Alte Protokolle' { Clear-OldLogs } $true }
            if ($C.Clean.BrowserCache)     { & $add 'Browser-Cache' { Clear-BrowserCaches } $true }
            if ($C.Cleaner -and $C.Cleaner.InSchedule) { & $add 'PC-Reiniger (eigene Auswahl)' { Invoke-CcCleanJob -AsStep } $true }
            if ($C.Clean.OldDrivers)       { & $add 'Veraltete Treiberpakete' { Remove-OldDriverPackages } $true }
            if ($C.Clean.CleanMgr)         { & $add 'Datenträgerbereinigung' { Invoke-CleanMgr } $true }
            if ($C.Clean.ComponentCleanup) { & $add 'Komponentenspeicher (WinSxS)' { Invoke-ComponentCleanup } $true }
            if ($C.Clean.OwnLogs)          { & $add 'Protokolle von PC-Tools' { Clear-OwnLogs } $true }
        }
        if ($doOpt) {
            if ($C.Optimize.DisableFastStartup) { & $add 'Schnellstart deaktivieren' { Disable-FastStartup } $false }
            if ($C.Optimize.DnsFlush)           { & $add 'DNS-Cache' { Clear-Dns } $false }
            if ($C.Optimize.HealthCheck)        { & $add 'Systemdateien prüfen' { Invoke-HealthCheck } $false }
            if ($C.Optimize.Volumes)            { & $add 'Laufwerke optimieren' { Optimize-Drives } $false }
        }
        if ($doWizF)  { & $add 'Einrichtung abschließen' { Invoke-WizardFinish } $false }
        if ($steps.Count -eq 0) { Write-PLog 'Keine Aufgaben ausgewählt.' 'WARN' }

        $i = 0
        foreach ($s in $steps) {
            if (Test-PCancel) { Write-PLog 'Abgebrochen durch Benutzer' 'WARN'; break }
            $i++
            $Script:StepName = $s.Name; $Script:StepStart = Get-Date; $Script:StepNo = $i; $Script:StepCount = $steps.Count
            $Script:Detail = ''; $Script:LastLine = ''
            Set-PStatus ('{0} ({1}/{2})' -f $s.Name, $i, $steps.Count) ([int](($i - 1) * 100 / $steps.Count))
            if ($s.Clean) { Invoke-CleanStep -Name $s.Name -Action $s.Action }
            else {
                Write-PLog ('--- {0} ---' -f $s.Name)
                try { & $s.Action | Out-Null } catch { Write-PLog ('{0}: {1}' -f $s.Name, $_.Exception.Message) 'FEHLER' }
            }
        }

        if ($Script:DsJobSet) { try { $null = Complete-DsAfterUpdate } catch { } }
        $dur = (Get-Date) - $start
        if ($doClean) { Write-PLog ('Speicherplatz {0}: {1}' -f $(if ($Analyze) { 'freigebbar' } else { 'freigegeben' }), (Format-Bytes $Script:Freed)) 'OK' }
        if ($doUpd -and -not $CheckOnly) { Write-PLog ('Installierte Windows-Updates: {0}' -f $Script:UpdatesInstalled) }
        if ($exec -and ((Test-PendingReboot) -or $Script:RebootNeeded)) {
            $why = if ($Script:RebootNeeded) { 'ein installiertes Update/Treiber verlangt ihn' } else { 'Windows meldet einen ausstehenden Neustart (aus einem früheren Update)' }
            $Script:RebootNeeded = $true
            Write-PLog ('Neustart erforderlich, um Updates abzuschließen - {0}' -f $why) 'WARN'
            $allowReboot = $C.Update.AutoReboot -and ($Script:IsAuto -or -not $C.Settings.RebootOnlyScheduled) -and -not ($doWr -or $doWrIpu)
            if ($allowReboot -and -not (Test-PCancel)) {
                $min = [math]::Max(1, [int]$C.Settings.RebootDelay)
                & shutdown.exe /r /t ($min * 60) /c ('PC-Tools: Neustart in {0} Minuten zum Abschluss der Updates (abbrechen: shutdown /a)' -f $min) | Out-Null
                Write-PLog ('Neustart in {0} Minuten geplant (abbrechen mit: shutdown /a)' -f $min)
            } elseif ($C.Update.AutoReboot) { Write-PLog 'Automatischer Neustart erfolgt nur beim Zeitplan - bitte selbst neu starten' }
        }
        Write-PLog ('===== Fertig nach {0:hh\:mm\:ss} - Warnungen: {1} =====' -f $dur, $Script:Warnings)
        if ($exec) {
            [pscustomobject]@{
                Zeit        = (Get-Date).ToString('dd.MM.yyyy HH:mm')
                Teile       = ($Parts -join ', ')
                Freigegeben = (Format-Bytes $Script:Freed)
                Updates     = $Script:UpdatesInstalled
                Neustart    = $Script:RebootNeeded
                Warnungen   = $Script:Warnings
                Dauer       = ('{0:hh\:mm\:ss}' -f $dur)
                Log         = $Script:LogFile
            } | ConvertTo-Json | Set-Content -Path (Join-Path $Script:DataDir 'lastrun.json') -Encoding UTF8
        }
    }
    catch { Write-PLog ('Unerwarteter Fehler: {0}' -f $_.Exception.Message) 'FEHLER' }
    finally {
        $Script:StepName = 'Fertig'; $Script:Detail = ''; $Script:StepStart = $null
        Set-PStatus 'Fertig' 100 $false
        if ($null -ne $sync) { $sync.Running = $false }
    }
}
'@

# =====================================================================
#  KONFIGURATION
# =====================================================================
$ConfigVersion = 4
function Get-DefaultConfig {
    [ordered]@{
        Clean = [ordered]@{
            UserTemp = $true;  UserTempDays = 1
            WinTemp  = $true;  WinTempDays  = 1
            WUCache  = $true;  DeliveryOpt  = $true
            RecycleBin = $true; RecycleBinDays = 1
            ThumbCache = $true
            WER = $true; WERDays = 1
            OldLogs = $true; OldLogsDays = 1
            BrowserCache = $true
            CleanMgr = $true; WindowsOld = $true
            ComponentCleanup = $true; ResetBase = $true
            OldDrivers = $true
            OwnLogs = $true
        }
        Optimize = [ordered]@{
            RestorePoint = $true; Volumes = $true; Trim = $true; Defrag = $true; SkipUsb = $true
            DnsFlush = $true; HealthCheck = $true; DisableFastStartup = $true
        }
        Update = [ordered]@{
            WindowsUpdate = $true; WUDrivers = $true; WUExcludeUpgrades = $false
            OEM = $true; OEMAutoInstall = $true; OEMFirmware = $true; OEMToolPath = ''
            Ninite = $true; NinitePath = ''; NiniteExclude = ''; NiniteKill = $true; NiniteTimeout = 90
            Winget = $true; WingetTimeout = 30; WingetExclude = ''
            Choco = $false; ChocoTimeout = 30; ChocoExclude = ''; ChocoAutoInstall = $true
            StoreApps = $true; Defender = $true; GpuDriver = $true; IntelDirect = $true; DriverBackup = $true
            AutoReboot = $true
        }
        Install = [ordered]@{ Shortcuts = $true; AllUsers = $true }
        Desk = [ordered]@{
            OldFolder = '_Alt'; OlderDays = 30
            MoveBroken = $true; MoveDuplicates = $true; MoveTemp = $true; MoveInstallers = $true
            MoveEmpty = $true; MoveOld = $true; SortRest = $true; IncludePublic = $true
            MoveOldVersions = $true; ArrangeGap = $true; ArrangeAfterClean = $true; FolderMin = 2; ArrangeLayout = 'Zeilen - oben entlang'
        }
        Monitor = [ordered]@{ AutoAtLogon = $false; AutoProfile = ''; AfterSwitch = 'Symbole nach Kategorien anordnen' }
        Backup = [ordered]@{
            Sources = ''; Target = ''; NasUser = ''; OnlyIfTarget = $true; Mode = 'Spiegeln'; Keep = 5
            ExcludeFiles = '*.tmp;~$*;Thumbs.db;desktop.ini;*.part;*.crdownload'; ExcludeDirs = '$RECYCLE.BIN;System Volume Information;node_modules;.cache;Temp'
            Threads = 16; Drivers = $true; Image = $false; ImageTarget = ''
            Enabled = $false; Frequency = 'Täglich'; Day = 'Freitag'; Time = '20:00'; WakeToRun = $true; Shutdown = $false
        }
        Diag = [ordered]@{
            Days = 14; SysInfo = $true; MsInfo = $true; DxDiag = $false; Events = $true; Reliability = $true; Dumps = $true; FullDump = $false
            UpdateLogs = $true; Drivers = $true; Network = $true; Software = $true; Disks = $true; Power = $true; PflegeLogs = $true; Target = ''
        }
        FullBackup = [ordered]@{
            Target = ''; NasUser = ''; Include = ''; Vss = 'Kopie (empfohlen - andere Sicherungsprogramme bleiben unberührt)'; NasVersions = $true; Keep = 3
            Verify = $true; DeepVerify = $false; Package = $true; PkgSource = 'WinRE dieses PCs'; StickRefresh = $false; SkipIfMissing = $true
            NotifyOk = $true; NotifyFail = $true; Shutdown = $false
            Enabled = $false; Frequency = 'Wöchentlich'; MonthWeek = 'ersten'; Day = 'Sonntag'; Time = '20:00'; WakeToRun = $true; OnlyAc = $true; CatchUp = $true; Retry = $true
        }
        Fleet = [ordered]@{ Enabled = $false; Dir = ''; Remote = $false; Heartbeat = $true; OnlineMin = 25; UploadLog = $true; Watch = $false; WatchOffline = $true; WatchOfflineH = 24; WatchScore = $true; WatchScoreDrop = 15; WatchBackup = $true; WatchBackupDays = 14; WatchJobs = $true; StrictAcl = $false }
        Cleaner = [ordered]@{ InSchedule = $false; Items = ''; KeepCookies = '' }
        OneClick = [ordered]@{ Updates = $true; Drivers = $true; Programs = $true; Repair = $true; AutoRepair = $false }
        DriverSafety = [ordered]@{ Enabled = $true; Keep = 5 }
        AutoFix = [ordered]@{ Enabled = $true; Below = 85 }
        Help = [ordered]@{ Mail = '' }
        Assistant = [ordered]@{ Provider = ''; Model = ''; CustomUrl = ''; AutoDiag = $true; AutoCloud = $false; Weekly = $true; Speak = $false; SaveChat = $true; Memory = $true; KeyScope = 'Nur mein Windows-Konto'; MonthlyLimit = 0; MaxTokens = 1024; CtxPage = $true; CtxSystem = $false; CtxHealth = $false; CtxLog = $false; CtxSelection = $true; ErrorButton = $true }
        Integrate = [ordered]@{ MqttEnabled = $false; MqttHost = ''; MqttPort = 1883; MqttUser = ''; MqttTopic = 'pcpflege'; HaEnabled = $false; HaUrl = ''; RmmEnabled = $false; RmmUrl = '' }
        Notify = [ordered]@{ Enabled = $false; Ntfy = ''; HaWebhook = ''; ChatWebhook = ''; OnRed = $true; OnWarn = $true; OnBackup = $true; OnBluescreen = $true; OnRecover = $true }
        Schedule = [ordered]@{
            Enabled = $true; Frequency = 'Wöchentlich'; Day = 'Sonntag'; Time = '03:00'
            Clean = $true; Optimize = $true; Update = $true; WakeToRun = $true; OneClick = $false
        }
        Settings = [ordered]@{
            CleanDays = 1
            LogDays = 30; ReportDays = 30
            RebootOnlyScheduled = $true; RebootDelay = 10
            KillOnlyScheduled = $true
            OemTimeout = 180; CleanMgrTimeout = 90
            Theme = 'Automatisch (wie Windows)'; UpdateSource = $DefaultUpdateSource; UpdateAuto = $true; UpdateInSchedule = $true; UpdateDelay = 'Sofort'
            ServerMode = $false
            ConfigVersion = $ConfigVersion
        }
    } | ConvertTo-Json -Depth 5 | ConvertFrom-Json
}
function Read-PflegeConfig {
    $def = Get-DefaultConfig
    if (Test-Path -LiteralPath $ConfigFile) {
        try {
            $u = $null
            try { $u = Get-Content -LiteralPath $ConfigFile -Raw -Encoding UTF8 | ConvertFrom-Json -ErrorAction Stop } catch { $u = $null }
            if (-not $u -or -not $u.PSObject.Properties.Count) {
                # beschädigte Konfiguration: aufheben und die letzte gute Sicherung nehmen statt still auf Standardwerte zu fallen
                try { Copy-Item -LiteralPath $ConfigFile -Destination ($ConfigFile + '.defekt-' + (Get-Date -Format 'yyyyMMdd_HHmmss')) -Force -ErrorAction SilentlyContinue } catch { }
                if (Test-Path -LiteralPath ($ConfigFile + '.bak')) { $u = Get-Content -LiteralPath ($ConfigFile + '.bak') -Raw -Encoding UTF8 | ConvertFrom-Json }
                try { Write-UpdLog 'config.json war beschädigt - Sicherung config.json.bak verwendet.' } catch { }
            }
            if (-not $u) { throw 'keine lesbare Konfiguration' }
            # Version < 3: alle neuen Standardwerte uebernehmen. Ab 4 nur gezielte Umstellungen (siehe unten).
            $oldCfg = -not ($u.Settings -and [int]$u.Settings.ConfigVersion -ge 3)
            foreach ($sec in $def.PSObject.Properties) {
                $us = $u.($sec.Name); if (-not $us) { continue }
                foreach ($p in $sec.Value.PSObject.Properties) {
                    if (-not $us.PSObject.Properties[$p.Name]) { continue }
                    if ($p.Name -eq 'ConfigVersion') { continue }
                    # Ältere Konfiguration: neue Standardwerte übernehmen, nur Texte (Pfade, Ausnahmen, Uhrzeit) behalten
                    if ($oldCfg -and -not ($p.Value -is [string])) { continue }
                    $p.Value = $us.($p.Name)
                }
            }
            # 13.3.2: Funktionsupdates und Insider-Builds werden jetzt standardmaessig mitinstalliert
            if (-not ($u.Settings -and [int]$u.Settings.ConfigVersion -ge 4)) { $def.Update.WUExcludeUpgrades = $false }
        } catch { }
    }
    if (-not [string]$def.Settings.UpdateSource) { $def.Settings.UpdateSource = $DefaultUpdateSource }
    # 13.7.1: Umzug auf das öffentliche Open-Source-Repository (Zweig stable, kein Token mehr nötig)
    if ([string]$def.Settings.UpdateSource -match '^github:\s*rhedv42-sudo/pc-pflege(@[\w\.\-/]+)?\s*$') { $def.Settings.UpdateSource = 'github:rhedv42-sudo/pc-tools@stable' }
    return $def
}
function Save-PflegeConfig($Cfg) {
    # ausfallsicher: erst in eine Temp-Datei schreiben und prüfen, dann die alte als .bak behalten und ersetzen
    $json = $Cfg | ConvertTo-Json -Depth 5
    $null = $json | ConvertFrom-Json
    $tmpC = $ConfigFile + '.neu'
    Set-Content -LiteralPath $tmpC -Value $json -Encoding UTF8
    if (Test-Path -LiteralPath $ConfigFile) {
        $okOld = $false; try { $null = Get-Content -LiteralPath $ConfigFile -Raw -Encoding UTF8 | ConvertFrom-Json -ErrorAction Stop; $okOld = $true } catch { }
        if ($okOld) { Copy-Item -LiteralPath $ConfigFile -Destination ($ConfigFile + '.bak') -Force -ErrorAction SilentlyContinue }
    }
    Move-Item -LiteralPath $tmpC -Destination $ConfigFile -Force
}

# =====================================================================
#  SELBST-UPDATE (Update-Quelle: Ordner/Netzwerkfreigabe oder https-Adresse mit version.json)
# =====================================================================
$UpdateFiles = 'PCPflege.ps1', 'PCPflege.ico', 'PCPflege.cmd'

# ---------------------------------------------------------------- Sprachen (Version 14)
# Deutsch ist die Ausgangssprache. Übersetzungen liegen als reine Daten (JSON) in lang\<code>.json - nie als Code.
# Übersetzt wird erst beim Anzeigen (Texte, Knöpfe, Tabellen, Meldungen); die Programmlogik arbeitet weiter mit den deutschen Texten.
$LangList = [ordered]@{ 'de-DE' = 'Deutsch'; 'en-US' = 'English'; 'zh-CN' = '简体中文'; 'ru-RU' = 'Русский'; 'es-ES' = 'Español'; 'pt-BR' = 'Português (Brasil)'; 'fr-FR' = 'Français'; 'ja-JP' = '日本語'; 'pl-PL' = 'Polski'; 'ko-KR' = '한국어'; 'tr-TR' = 'Türkçe'; 'it-IT' = 'Italiano' }
$LangAiName = @{ 'de-DE' = 'Deutsch'; 'en-US' = 'English'; 'zh-CN' = 'Simplified Chinese (简体中文)'; 'ru-RU' = 'Russian'; 'es-ES' = 'Spanish (Spain)'; 'pt-BR' = 'Brazilian Portuguese'; 'fr-FR' = 'French'; 'ja-JP' = 'Japanese'; 'pl-PL' = 'Polish'; 'ko-KR' = 'Korean'; 'tr-TR' = 'Turkish'; 'it-IT' = 'Italian' }
$script:I18nOn = $false; $script:UiLang = 'de-DE'; $script:LangMeta = $null
function T([string]$Text) { if ($script:I18nOn -or ('PcTools.I18n' -as [type])) { try { return [PcTools.I18n]::T($Text) } catch { } }; return $Text }
function Get-LangDirs { $d = @(); if ($PSScriptRoot) { $d += (Join-Path $PSScriptRoot 'lang') }; $d += (Join-Path $DataDir 'lang'); return $d }
function Get-LangFile([string]$Code) { foreach ($d in (Get-LangDirs)) { $f = Join-Path $d ($Code + '.json'); if (Test-Path -LiteralPath $f) { return $f } }; return '' }
function Get-UiLang {
    $f = Join-Path $DataDir 'sprache.txt'
    try { if (Test-Path -LiteralPath $f) { $c = ([string](Get-Content -LiteralPath $f -Raw -Encoding UTF8)).Trim(); if ($LangList.Contains($c)) { return $c } } } catch { }
    return 'de-DE'
}
function Set-UiLang([string]$Code) { if (-not $LangList.Contains($Code)) { return }; try { New-Item $DataDir -ItemType Directory -Force -ErrorAction SilentlyContinue | Out-Null; Set-Content -LiteralPath (Join-Path $DataDir 'sprache.txt') -Value $Code -Encoding ASCII } catch { } }
# Sprachdatei aus dem Update-Zweig laden (nur Daten, mit Prüfung, dass es gültiges JSON mit "strings" ist)
function Save-LangFile([string]$Code) {
    $src = $DefaultUpdateSource; try { $c = Read-PflegeConfig; if ([string]$c.Settings.UpdateSource) { $src = [string]$c.Settings.UpdateSource } } catch { }
    $gh = Get-GitHubSource $src; if (-not $gh) { $gh = Get-GitHubSource $DefaultUpdateSource }
    $dir = Join-Path $DataDir 'lang'; New-Item $dir -ItemType Directory -Force | Out-Null
    $tmp = Join-Path $dir ($Code + '.download'); $dst = Join-Path $dir ($Code + '.json')
    Invoke-GitHubRaw $gh ('lang/' + $Code + '.json') $tmp
    Add-Type -AssemblyName System.Web.Extensions
    $js = New-Object Web.Script.Serialization.JavaScriptSerializer; $js.MaxJsonLength = [int]::MaxValue
    $o = $js.DeserializeObject([IO.File]::ReadAllText($tmp, [Text.Encoding]::UTF8))
    if (-not $o -or -not $o.ContainsKey('strings')) { Remove-Item -LiteralPath $tmp -Force -ErrorAction SilentlyContinue; throw 'Sprachdatei ungültig.' }
    Move-Item -LiteralPath $tmp -Destination $dst -Force
    return $dst
}
$I18nCs = @'
using System;
using System.Collections.Generic;
using System.Globalization;
using System.Runtime.CompilerServices;
using System.Text;
using System.Text.RegularExpressions;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Data;
using System.Windows.Documents;
using System.Windows.Markup;
using System.ComponentModel;

namespace PcTools {
    public class TrConv : IValueConverter {
        public static readonly TrConv I = new TrConv();
        public object Convert(object v, Type t, object p, CultureInfo c) { var s = v as string; return s == null ? v : I18n.T(s); }
        public object ConvertBack(object v, Type t, object p, CultureInfo c) { return v; }
    }
    public static class I18n {
        public static string Lang = "de-DE";
        static Dictionary<string, string> exact = new Dictionary<string, string>(StringComparer.Ordinal);
        class Pat { public Regex Rx; public string Repl; public string Anchor; }
        static List<Pat> pats = new List<Pat>();
        static Dictionary<string, List<KeyValuePair<string, string>>> frag = new Dictionary<string, List<KeyValuePair<string, string>>>(StringComparer.Ordinal);
        static Dictionary<string, string> cache = new Dictionary<string, string>(StringComparer.Ordinal);
        static readonly object lk = new object();
        static bool installed;
        [ThreadStatic] static bool busy;
        static DataTemplate tpl;
        static ConditionalWeakTable<object, object> hooked = new ConditionalWeakTable<object, object>();
        static readonly Regex ph = new Regex(@"\{(\d+)(?:[,:][^}]*)?\}", RegexOptions.Compiled);
        const int FragMin = 8, FragKey = 6;

        public static bool Active { get { return !Lang.StartsWith("de", StringComparison.OrdinalIgnoreCase) && exact.Count > 0; } }
        public static int Count { get { return exact.Count; } }

        public static void Load(string lang, IDictionary<string, object> strings) {
            lock (lk) {
                Lang = lang; exact.Clear(); pats.Clear(); frag.Clear(); cache.Clear();
                if (strings == null) return;
                foreach (var kv in strings) {
                    var tr = kv.Value as string;
                    if (string.IsNullOrEmpty(kv.Key) || string.IsNullOrEmpty(tr) || tr == kv.Key) continue;
                    exact[kv.Key] = tr;
                    if (ph.IsMatch(kv.Key)) AddPattern(kv.Key, tr);
                    else if (kv.Key.Length >= FragMin) {
                        string k = kv.Key.Substring(0, FragKey); List<KeyValuePair<string, string>> l;
                        if (!frag.TryGetValue(k, out l)) { l = new List<KeyValuePair<string, string>>(); frag[k] = l; }
                        l.Add(new KeyValuePair<string, string>(kv.Key, tr));
                    }
                }
                foreach (var l in frag.Values) l.Sort((a, b) => b.Key.Length.CompareTo(a.Key.Length));
                pats.Sort((a, b) => b.Anchor.Length.CompareTo(a.Anchor.Length));
            }
        }
        static void AddPattern(string key, string tr) {
            var sb = new StringBuilder("^"); int last = 0; string anchor = ""; var seen = new HashSet<string>();
            foreach (Match m in ph.Matches(key)) {
                string lit = key.Substring(last, m.Index - last);
                if (lit.Trim().Length > anchor.Trim().Length) anchor = lit;
                sb.Append(Regex.Escape(lit));
                string g = "g" + m.Groups[1].Value;
                if (seen.Contains(g)) sb.Append(@"\k<" + g + ">"); else { sb.Append("(?<" + g + ">.*?)"); seen.Add(g); }
                last = m.Index + m.Length;
            }
            string tail = key.Substring(last); if (tail.Trim().Length > anchor.Trim().Length) anchor = tail;
            sb.Append(Regex.Escape(tail)).Append("$");
            if (anchor.Trim().Length < 3) return;
            try { pats.Add(new Pat { Rx = new Regex(sb.ToString(), RegexOptions.Singleline | RegexOptions.CultureInvariant), Repl = tr, Anchor = anchor }); } catch { }
        }

        public static string T(string s) {
            if (s == null || s.Length < 2 || !Active) return s;
            lock (lk) {
                string r;
                if (cache.TryGetValue(s, out r)) return r;
                r = Core(s, 0);
                if (cache.Count > 20000) cache.Clear();
                cache[s] = r;
                return r;
            }
        }
        static bool HasLetters(string s) { foreach (char c in s) if (char.IsLetter(c)) return true; return false; }
        static string Core(string s, int depth) {
            string r;
            if (exact.TryGetValue(s, out r)) return r;
            if (!HasLetters(s)) return s;
            string t = s.Trim();
            if (t.Length != s.Length && t.Length > 0) {
                if (exact.TryGetValue(t, out r)) { int a = s.IndexOf(t, StringComparison.Ordinal); return s.Substring(0, a) + r + s.Substring(a + t.Length); }
            }
            if (depth < 2 && (s.IndexOf('\n') >= 0)) {
                var parts = s.Split('\n'); bool ch = false;
                for (int i = 0; i < parts.Length; i++) { string cr = parts[i].EndsWith("\r") ? "\r" : ""; string p = cr.Length > 0 ? parts[i].Substring(0, parts[i].Length - 1) : parts[i]; string q = p.Length > 0 ? Core(p, depth + 1) : p; if (!ReferenceEquals(q, p) && q != p) { parts[i] = q + cr; ch = true; } }
                if (ch) return string.Join("\n", parts);
            }
            foreach (var p in pats) {
                if (p.Anchor.Length > 0 && s.IndexOf(p.Anchor, StringComparison.Ordinal) < 0) continue;
                var m = p.Rx.Match(s);
                if (!m.Success) continue;
                return ph.Replace(p.Repl, mm => { var g = m.Groups["g" + mm.Groups[1].Value]; if (!g.Success) return mm.Value; string v = g.Value; string tv; return exact.TryGetValue(v, out tv) ? tv : v; });
            }
            // "Bezeichnung: Wert"
            int ci = s.IndexOf(": ", StringComparison.Ordinal);
            if (ci > 1 && ci < 60) { string head = s.Substring(0, ci); if (exact.TryGetValue(head, out r)) return r + s.Substring(ci); if (exact.TryGetValue(head + ":", out r)) return r + s.Substring(ci + 1); }
            if (s.Length >= FragMin) {
                var sb = new StringBuilder(); int i = 0; bool any = false;
                while (i < s.Length) {
                    bool hit = false;
                    if (i + FragKey <= s.Length && (i == 0 || !char.IsLetter(s[i - 1]))) {
                        List<KeyValuePair<string, string>> l;
                        if (frag.TryGetValue(s.Substring(i, FragKey), out l)) {
                            foreach (var kv in l) {
                                if (i + kv.Key.Length <= s.Length && string.CompareOrdinal(s, i, kv.Key, 0, kv.Key.Length) == 0 && (i + kv.Key.Length == s.Length || !char.IsLetter(s[i + kv.Key.Length]) || !char.IsLetter(kv.Key[kv.Key.Length - 1]))) {
                                    sb.Append(kv.Value); i += kv.Key.Length; hit = true; any = true; break;
                                }
                            }
                        }
                    }
                    if (!hit) { sb.Append(s[i]); i++; }
                }
                if (any) return sb.ToString();
            }
            return s;
        }

        // ---------------------------------------------------------------- WPF
        public static void Install() {
            if (installed) return; installed = true;
            var f = new FrameworkElementFactory(typeof(TextBlock));
            f.SetBinding(TextBlock.TextProperty, new Binding(".") { Converter = TrConv.I });
            tpl = new DataTemplate { VisualTree = f }; tpl.Seal();
            // Loaded wird nur am Fenster zuverlässig gemeldet - dort den ganzen Baum übersetzen und später hinzukommende Elemente (gedrosselt) nachziehen
            EventManager.RegisterClassHandler(typeof(Window), FrameworkElement.LoadedEvent, new RoutedEventHandler(OnWinLoaded), true);
            EventManager.RegisterClassHandler(typeof(FrameworkElement), FrameworkElement.ToolTipOpeningEvent, new ToolTipEventHandler(OnTip), true);
        }
        static ConditionalWeakTable<object, object> done = new ConditionalWeakTable<object, object>();
        static ConditionalWeakTable<object, object> wins = new ConditionalWeakTable<object, object>();
        static void OnTip(object sender, ToolTipEventArgs e) {
            var fe = sender as FrameworkElement; if (fe == null || !Active) return;
            var s = fe.ToolTip as string; if (s != null) { var t = T(s); if (t != s) fe.ToolTip = t; }
        }
        static void OnWinLoaded(object sender, RoutedEventArgs e) {
            var w = sender as Window; if (w == null || !Active) return;
            object o; if (wins.TryGetValue(w, out o)) return;
            wins.Add(w, true);
            try { Walk(w); } catch { }
            var tm = new System.Windows.Threading.DispatcherTimer(System.Windows.Threading.DispatcherPriority.Background, w.Dispatcher) { Interval = TimeSpan.FromMilliseconds(350) };
            tm.Tick += (s2, e2) => { tm.Stop(); try { if (Active) Walk(w); } catch { } };
            w.LayoutUpdated += (s3, e3) => { if (!tm.IsEnabled) tm.Start(); };
            w.Closed += (s4, e4) => tm.Stop();
        }
        public static void Walk(DependencyObject root) {
            if (root == null || !Active) return;
            var st = new Stack<DependencyObject>(); st.Push(root);
            while (st.Count > 0) {
                var d = st.Pop();
                var fe = d as FrameworkElement;
                if (fe != null) {
                    if (fe.Uid == "notr") continue;
                    object o;
                    if (!done.TryGetValue(fe, out o)) { done.Add(fe, true); try { Apply(fe); } catch { } }
                }
                int n = 0;
                if (d is System.Windows.Media.Visual || d is System.Windows.Media.Media3D.Visual3D) { try { n = System.Windows.Media.VisualTreeHelper.GetChildrenCount(d); } catch { n = 0; } }
                for (int i = 0; i < n; i++) st.Push(System.Windows.Media.VisualTreeHelper.GetChild(d, i));
            }
        }
        public static void Apply(FrameworkElement fe) {
            if (fe == null || fe.Uid == "notr") return;
            var w = fe as Window;
            if (w != null) {
                if (!string.IsNullOrEmpty(w.Title)) w.Title = T(w.Title);
                try { w.Language = XmlLanguage.GetLanguage(Lang); } catch { }
                Hook(w, Window.TitleProperty, typeof(Window));
            }
            var tb = fe as TextBlock;
            if (tb != null) { DoTextBlock(tb); Hook(tb, TextBlock.TextProperty, typeof(TextBlock)); return; }
            var cb = fe as ComboBox;
            if (cb != null && !cb.IsEditable) {
                foreach (var it in cb.Items) { var ci = it as ComboBoxItem; if (ci != null && ci.Uid != "notr") DoContent(ci); }
                if (cb.ItemTemplate == null && cb.ItemsSource == null && cb.Items.Count > 0 && cb.Items[0] is string) cb.ItemTemplate = tpl;
            }
            var hc = fe as HeaderedContentControl;
            if (hc != null && hc.Header is string && hc.HeaderTemplate == null && hc.HeaderTemplateSelector == null) hc.HeaderTemplate = tpl;
            var hi = fe as HeaderedItemsControl;
            if (hi != null && hi.Header is string && hi.HeaderTemplate == null && hi.HeaderTemplateSelector == null) hi.HeaderTemplate = tpl;
            var cc = fe as ContentControl;
            if (cc != null && !(fe is Window)) DoContent(cc);
            var dg = fe as DataGrid;
            if (dg != null) DoGrid(dg);
            var gv = fe as ListView;
            if (gv != null) { var v = gv.View as GridView; if (v != null) foreach (var c in v.Columns) { if (c.Header is string) c.Header = T((string)c.Header); } }
        }
        static void DoContent(ContentControl cc) {
            if (cc.Content is string && cc.ContentTemplate == null && cc.ContentTemplateSelector == null && !BindingOperations.IsDataBound(cc, ContentControl.ContentProperty)) cc.ContentTemplate = tpl;
            var s = cc.ToolTip as string; if (s != null) { var t = T(s); if (t != s) cc.ToolTip = t; }
        }
        static void DoGrid(DataGrid dg) {
            foreach (var c in dg.Columns) {
                if (c.Header is string) { var t = T((string)c.Header); if (t != (string)c.Header) c.Header = t; }
                var tc = c as DataGridTextColumn;
                if (tc != null) {
                    var b = tc.Binding as Binding;
                    if (b != null && b.Converter == null) {
                        try { b.Converter = TrConv.I; }
                        catch { var nb = new Binding { Path = b.Path, Mode = b.Mode, StringFormat = b.StringFormat, Converter = TrConv.I, TargetNullValue = b.TargetNullValue, UpdateSourceTrigger = b.UpdateSourceTrigger }; tc.Binding = nb; }
                    }
                }
            }
        }
        static void DoTextBlock(TextBlock tb) {
            if (busy) return;
            if (BindingOperations.IsDataBound(tb, TextBlock.TextProperty)) return;
            busy = true;
            try {
                if (tb.Inlines.Count == 1 && tb.Inlines.FirstInline is Run) {
                    var run = (Run)tb.Inlines.FirstInline;
                    if (!BindingOperations.IsDataBound(run, Run.TextProperty)) { var t = T(run.Text); if (t != run.Text) run.Text = t; }
                } else DoInlines(tb.Inlines);
                var s = tb.ToolTip as string; if (s != null) { var t2 = T(s); if (t2 != s) tb.ToolTip = t2; }
            } finally { busy = false; }
        }
        static void CollectRuns(InlineCollection col, List<Run> runs) {
            foreach (var il in col) {
                var r = il as Run; if (r != null) { runs.Add(r); continue; }
                var sp = il as Span; if (sp != null) CollectRuns(sp.Inlines, runs);
            }
        }
        static void DoInlines(InlineCollection col) {
            var runs = new List<Run>(); CollectRuns(col, runs);
            foreach (var r in runs) { if (!BindingOperations.IsDataBound(r, Run.TextProperty) && !string.IsNullOrEmpty(r.Text)) { var t = T(r.Text); if (t != r.Text) r.Text = t; } }
        }
        static void Hook(DependencyObject d, DependencyProperty p, Type t) {
            object o;
            if (hooked.TryGetValue(d, out o)) return;
            hooked.Add(d, true);
            var dpd = DependencyPropertyDescriptor.FromProperty(p, t);
            if (dpd == null) return;
            dpd.AddValueChanged(d, (s, e) => {
                if (busy || !Active) return;
                try {
                    var tb = s as TextBlock; if (tb != null) { DoTextBlock(tb); return; }
                    var w = s as Window; if (w != null) { busy = true; try { var t2 = T(w.Title); if (t2 != w.Title) w.Title = t2; } finally { busy = false; } }
                } catch { }
            });
        }
        // HTML-Text (Berichte): nur Textknoten übersetzen
        static readonly Regex htmlText = new Regex(@">([^<>]*[A-Za-zÄÖÜäöüß][^<>]*)<", RegexOptions.Compiled);
        public static string Html(string html) {
            if (!Active || string.IsNullOrEmpty(html)) return html;
            return htmlText.Replace(html, m => {
                string raw = m.Groups[1].Value; string dec = System.Net.WebUtility.HtmlDecode(raw);
                string t = T(dec); if (t == dec) return m.Value;
                return ">" + System.Net.WebUtility.HtmlEncode(t) + "<";
            });
        }
    }
}

'@
function Initialize-I18n([string]$Code, [switch]$Download) {
    $script:UiLang = $(if ($LangList.Contains($Code)) { $Code } else { 'de-DE' })
    if ($script:UiLang -eq 'de-DE') {
        $script:I18nOn = $false
        if ('PcTools.I18n' -as [type]) { [PcTools.I18n]::Load('de-DE', $null) }
        return $true
    }
    $f = Get-LangFile $script:UiLang
    if (-not $f -and $Download) { try { $f = Save-LangFile $script:UiLang } catch { $f = '' } }
    if (-not $f) { $script:I18nOn = $false; return $false }
    if (-not ('PcTools.I18n' -as [type])) {
        Add-Type -TypeDefinition $I18nCs -ReferencedAssemblies PresentationFramework, PresentationCore, WindowsBase, System.Xaml, System -ErrorAction Stop
    }
    Add-Type -AssemblyName System.Web.Extensions
    $js = New-Object Web.Script.Serialization.JavaScriptSerializer; $js.MaxJsonLength = [int]::MaxValue
    $o = $js.DeserializeObject([IO.File]::ReadAllText($f, [Text.Encoding]::UTF8))
    $script:LangMeta = $o['meta']
    [PcTools.I18n]::Load($script:UiLang, $o['strings'])
    [PcTools.I18n]::Install()
    $script:I18nOn = $true
    return $true
}
# Sprachdatei nach einem PC-Tools-Update im Hintergrund auffrischen (gilt beim nächsten Start)
function Update-LangFileBg {
    if (-not $script:I18nOn) { return }
    $app = ''; try { $app = [string]$script:LangMeta['app'] } catch { }
    if ($app -eq $AppVersion) { return }
    try { Invoke-Bg -Script { param($c) Save-LangFile $c } -Arguments @($script:UiLang) -Functions @('Save-LangFile') -Done { param($r, $e) } } catch { }
}
function Get-LangStatusText {
    if ($script:UiLang -eq 'de-DE') { return 'Deutsch ist die Originalsprache von PC-Tools.' }
    $st = ''; $pc = ''; try { $st = [string]$script:LangMeta['status']; $pc = [string]$script:LangMeta['reviewed'] } catch { }
    $lab = switch ($st) { 'native' { 'von Muttersprachlern geprüft' } 'community' { 'von der Community geprüft' } default { 'maschinell übersetzt - Prüfung durch Muttersprachler erwünscht' } }
    return ('{0}: {1}. Siehst du einen Fehler? "Übersetzungsfehler melden" - danke!' -f $LangList[$script:UiLang], $lab)
}
function Open-LangReport([string]$Text = '') {
    $t = [uri]::EscapeDataString(('[{0}] Übersetzungsfehler' -f $script:UiLang))
    $u = 'https://github.com/rhedv42-sudo/pc-tools/issues/new?template=translation-error.yml&labels=translation&title={0}&lang={1}&version={2}' -f $t, [uri]::EscapeDataString($script:UiLang), [uri]::EscapeDataString($AppVersion)
    try { Start-Process $u } catch { }
}
$TokenFile = Join-Path $DataDir 'github.token'

# ---- Privates GitHub-Repository als Update-Quelle:  github:BENUTZER/REPO  oder  github:BENUTZER/REPO@branch
function Get-GitHubSource([string]$Source) {
    if ($Source -match '^github:\s*([\w\.\-]+/[\w\.\-]+?)(?:@([\w\.\-/]+))?\s*$') { return @{ Repo = $Matches[1]; Branch = $(if ($Matches[2]) { $Matches[2] } else { 'main' }) } }
    return $null
}
# Token verschlüsselt (DPAPI, an diesen PC gebunden) - lesbar für SYSTEM und Administratoren
function Save-GitHubToken([string]$Token) {
    Add-Type -AssemblyName System.Security
    $enc = [Security.Cryptography.ProtectedData]::Protect([Text.Encoding]::UTF8.GetBytes($Token.Trim()), $null, [Security.Cryptography.DataProtectionScope]::LocalMachine)
    New-Item $DataDir -ItemType Directory -Force | Out-Null
    [IO.File]::WriteAllBytes($TokenFile, $enc)
    & icacls.exe $TokenFile /inheritance:r /grant:r '*S-1-5-18:F' '*S-1-5-32-544:F' | Out-Null
}
function Get-GitHubToken {
    if (-not (Test-Path -LiteralPath $TokenFile)) {
        if ($Script:IsPortable) { $pt = Join-Path $PSScriptRoot 'pcpflege.token'; if (Test-Path -LiteralPath $pt) { try { return (Unprotect-PkgToken (Get-Content -LiteralPath $pt -Raw)) } catch { } } }
        return $null
    }
    try {
        Add-Type -AssemblyName System.Security
        return [Text.Encoding]::UTF8.GetString([Security.Cryptography.ProtectedData]::Unprotect([IO.File]::ReadAllBytes($TokenFile), $null, [Security.Cryptography.DataProtectionScope]::LocalMachine))
    } catch { return $null }
}
# Nur-Lesen-Token für andere PCs (auf dem eigenen PC verschlüsselt gemerkt, für Einrichtungspakete)
$ReadTokenFile = Join-Path $DataDir 'github.readtoken'
function Save-ReadToken([string]$Token) {
    Add-Type -AssemblyName System.Security
    [IO.File]::WriteAllBytes($ReadTokenFile, [Security.Cryptography.ProtectedData]::Protect([Text.Encoding]::UTF8.GetBytes($Token.Trim()), $null, [Security.Cryptography.DataProtectionScope]::LocalMachine))
    & icacls.exe $ReadTokenFile /inheritance:r /grant:r '*S-1-5-18:F' '*S-1-5-32-544:F' | Out-Null
}
function Get-ReadToken {
    if (-not (Test-Path -LiteralPath $ReadTokenFile)) { return $null }
    try { Add-Type -AssemblyName System.Security; [Text.Encoding]::UTF8.GetString([Security.Cryptography.ProtectedData]::Unprotect([IO.File]::ReadAllBytes($ReadTokenFile), $null, [Security.Cryptography.DataProtectionScope]::LocalMachine)) } catch { $null }
}
# Token im Einrichtungspaket (verschlüsselt, wird beim Einrichten übernommen und aus dem Programmordner gelöscht)
function Get-PkgKey { [Security.Cryptography.SHA256]::Create().ComputeHash([Text.Encoding]::UTF8.GetBytes('PC-Pflege|Einrichtungspaket|' + $DefaultUpdateSource)) }
function Protect-PkgToken([string]$Token) { ConvertTo-SecureString $Token -AsPlainText -Force | ConvertFrom-SecureString -Key (Get-PkgKey) }
function Unprotect-PkgToken([string]$Data) {
    $ss = ConvertTo-SecureString $Data.Trim() -Key (Get-PkgKey)
    $b = [Runtime.InteropServices.Marshal]::SecureStringToBSTR($ss)
    try { [Runtime.InteropServices.Marshal]::PtrToStringBSTR($b) } finally { [Runtime.InteropServices.Marshal]::ZeroFreeBSTR($b) }
}
function Test-GitHubToken([string]$Repo, [string]$Token) {
    try { [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12 } catch { }
    $h = @{ Authorization = ('Bearer {0}' -f $Token.Trim()); Accept = 'application/vnd.github+json'; 'X-GitHub-Api-Version' = '2022-11-28'; 'User-Agent' = 'PC-Tools' }
    $r = Invoke-RestMethod -Uri ('https://api.github.com/repos/{0}' -f $Repo) -Headers $h -TimeoutSec 20
    return [pscustomobject]@{ Name = $r.full_name; Private = [bool]$r.private; Push = (Test-GitHubWrite $Repo $Token) }
}
# Darf der Token schreiben? (permissions.push zeigt nur die Rechte des Kontos, nicht die des Tokens)
# Test: leeres Git-Objekt anlegen - harmlos, wird nirgends verwendet und von GitHub später aufgeräumt
function Test-GitHubWrite([string]$Repo, [string]$Token) {
    $h = @{ Authorization = ('Bearer {0}' -f $Token.Trim()); Accept = 'application/vnd.github+json'; 'X-GitHub-Api-Version' = '2022-11-28'; 'User-Agent' = 'PC-Tools' }
    try {
        Invoke-RestMethod -Method Post -Uri ('https://api.github.com/repos/{0}/git/blobs' -f $Repo) -Headers $h -Body '{"content":"","encoding":"utf-8"}' -ContentType 'application/json' -TimeoutSec 20 | Out-Null
        return $true
    } catch {
        $code = 0; try { $code = [int]$_.Exception.Response.StatusCode } catch { }
        if ($code -in 403, 404) { return $false }
        return $false
    }
}
# Token aus einem Einrichtungspaket übernehmen - einen funktionierenden vorhandenen Token nie überschreiben
function Import-PackageToken {
    $ok = $false
    if ($Script:IsPortable) { return $false }
    foreach ($d in (@($PSScriptRoot, $DataDir) | Where-Object { $_ } | Select-Object -Unique)) {
        $f = Join-Path $d 'pcpflege.token'
        if (-not (Test-Path -LiteralPath $f)) { continue }
        try {
            $t = Unprotect-PkgToken (Get-Content -LiteralPath $f -Raw)
            $keep = $false
            $cur = Get-GitHubToken
            if ($cur) { $gh = Get-GitHubSource $DefaultUpdateSource; try { $null = Test-GitHubToken $gh.Repo $cur; $keep = $true } catch { } }
            if ($t -and -not $keep) { Save-GitHubToken $t; $ok = $true }
        } catch { }
        if ($d -eq $DataDir) { Remove-Item -LiteralPath $f -Force -ErrorAction SilentlyContinue }
    }
    return $ok
}
function Get-GitHubHeaders([string]$Accept = 'application/vnd.github+json') {
    $t = Get-GitHubToken
    if (-not $t) { throw 'Kein GitHub-Token hinterlegt (Einstellungen > Updates von PC-Tools).' }
    return @{ Authorization = ('Bearer {0}' -f $t); Accept = $Accept; 'X-GitHub-Api-Version' = '2022-11-28'; 'User-Agent' = 'PC-Tools' }
}
function Invoke-GitHubRaw($Gh, [string]$Path, [string]$OutFile = '') {
    try { [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12 } catch { }
    $uri = 'https://api.github.com/repos/{0}/contents/{1}?ref={2}' -f $Gh.Repo, $Path, $Gh.Branch
    $h = Get-GitHubHeaders 'application/vnd.github.raw'
    if ($OutFile) { Invoke-WebRequest -Uri $uri -Headers $h -OutFile $OutFile -UseBasicParsing -TimeoutSec 300 | Out-Null; return }
    $r = Invoke-WebRequest -Uri $uri -Headers $h -UseBasicParsing -TimeoutSec 30
    $c = $r.Content
    if ($c -is [byte[]]) { $c = [Text.Encoding]::UTF8.GetString($c) }
    return ([string]$c).TrimStart([char]0xFEFF)
}
function Test-GitHubConnection([string]$Source) {
    $gh = Get-GitHubSource $Source
    if (-not $gh) { throw 'Keine GitHub-Quelle. Format: github:BENUTZER/REPO' }
    try { [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12 } catch { }
    try { $r = Invoke-RestMethod -Uri ('https://api.github.com/repos/{0}' -f $gh.Repo) -Headers (Get-GitHubHeaders) -TimeoutSec 20 }
    catch {
        if ($_.Exception.Response -and [int]$_.Exception.Response.StatusCode -eq 404) { throw ('Repository {0} nicht gefunden oder der Token hat keinen Zugriff (Token > Repository access > pc-pflege auswählen).' -f $gh.Repo) }
        throw (Get-GitHubError $_ '')
    }
    return [pscustomobject]@{ Name = $r.full_name; Private = [bool]$r.private; Push = (Test-GitHubWrite $gh.Repo (Get-GitHubToken)); Branch = $gh.Branch }
}
function Publish-GitHubFile($Gh, [string]$Name, [byte[]]$Bytes, [string]$Message) {
    $h = Get-GitHubHeaders
    $uri = 'https://api.github.com/repos/{0}/contents/{1}' -f $Gh.Repo, $Name
    $sha = $null
    try { $sha = (Invoke-RestMethod -Uri ('{0}?ref={1}' -f $uri, $Gh.Branch) -Headers $h -TimeoutSec 30).sha } catch { }
    $body = [ordered]@{ message = $Message; content = [Convert]::ToBase64String($Bytes); branch = $Gh.Branch }
    if ($sha) { $body.sha = $sha }
    # Windows PowerShell 5.1 schickt Text-Bodies als ISO-8859-1 -> Umlaute ergeben ungültiges JSON (400). Daher als UTF-8-Bytes senden.
    $bytesBody = [Text.Encoding]::UTF8.GetBytes(($body | ConvertTo-Json -Compress))
    try { Invoke-RestMethod -Method Put -Uri $uri -Headers $h -Body $bytesBody -ContentType 'application/json; charset=utf-8' -TimeoutSec 300 | Out-Null }
    catch { throw (Get-GitHubError $_ $Name) }
}
function Get-GitHubError($Err, [string]$What) {
    $msg = $Err.Exception.Message
    try { $d = $Err.ErrorDetails.Message | ConvertFrom-Json; if ($d.message) { $msg = '{0} - GitHub: {1}' -f $msg, $d.message } } catch { }
    if ($What) { $msg = '{0}: {1}' -f $What, $msg }
    return $msg
}
function Get-UpdateManifest([string]$Source) {
    if (-not $Source) { return $null }
    try {
        $gh = Get-GitHubSource $Source
        if ($gh) { return ((Invoke-GitHubRaw $gh 'version.json') | ConvertFrom-Json) }
        if ($Source -match '^https?://') {
            try { [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12 } catch { }
            $json = (Invoke-WebRequest -Uri ($Source.TrimEnd('/') + '/version.json') -UseBasicParsing -TimeoutSec 15).Content
        } else {
            $p = Join-Path $Source 'version.json'
            if (-not (Test-Path -LiteralPath $p)) { return $null }
            $json = Get-Content -LiteralPath $p -Raw -Encoding UTF8
        }
        return ($json | ConvertFrom-Json)
    } catch { return $null }
}
function Test-NewerVersion([string]$New, [string]$Old) { try { return ([version]$New -gt [version]$Old) } catch { return $false } }
# ---- Stabilität (9.3): Update-Verzögerung, zurückgenommene Versionen, Vorversion, Prüfung neuer Skripte, Ablauf-Sperre
function Write-UpdLog([string]$Text) { try { $d = Join-Path $DataDir 'Logs'; New-Item $d -ItemType Directory -Force | Out-Null; Add-Content -LiteralPath (Join-Path $d 'Update-Verlauf.log') -Value ('{0:yyyy-MM-dd HH:mm:ss}  {1}' -f (Get-Date), $Text) -Encoding UTF8 } catch { } }
function Get-UpdateSkip { $f = Join-Path $DataDir 'update-skip.txt'; if (Test-Path -LiteralPath $f) { @(Get-Content -LiteralPath $f -Encoding UTF8 | ForEach-Object { ([string]$_).Trim() } | Where-Object { $_ }) } else { @() } }
function Add-UpdateSkip([string]$Version) { try { $l = @(@(Get-UpdateSkip) + $Version | Select-Object -Unique); Set-Content -LiteralPath (Join-Path $DataDir 'update-skip.txt') -Value $l -Encoding UTF8 } catch { } }
function Get-UpdateDelayDays($Cfg) { $t = ''; try { $t = [string]$Cfg.Settings.UpdateDelay } catch { }; if ($t -match '(\d+)') { return [int]$Matches[1] }; return 0 }
function Get-UpdateDue($Manifest, $Cfg) {
    # $null = sofort installieren, sonst das Datum, ab dem installiert wird (Update-Verzögerung)
    $days = Get-UpdateDelayDays $Cfg
    if ($days -le 0 -or -not $Manifest) { return $null }
    $d = [datetime]::MinValue
    if (-not [datetime]::TryParseExact([string]$Manifest.Date, 'yyyy-MM-dd HH:mm', [Globalization.CultureInfo]::InvariantCulture, [Globalization.DateTimeStyles]::None, [ref]$d)) { return $null }
    $due = $d.AddDays($days)
    if ($due -le (Get-Date)) { return $null }
    return $due
}
function Test-UpdateWanted($Manifest, $Cfg, [switch]$IgnoreDelay) {
    if (-not $Manifest -or -not (Test-NewerVersion ([string]$Manifest.Version) $AppVersion)) { return $false }
    if (@(Get-UpdateSkip) -contains [string]$Manifest.Version) { return $false }
    if (-not $IgnoreDelay -and $null -ne (Get-UpdateDue $Manifest $Cfg)) { return $false }
    return $true
}
function Test-PflegeScript([string]$Path, [string]$ExpectVersion = '') {
    # Ein neues Skript wird nur installiert, wenn es fehlerfrei geparst werden kann und zur version.json passt
    $tok = $null; $errs = $null
    [void][System.Management.Automation.Language.Parser]::ParseFile($Path, [ref]$tok, [ref]$errs)
    if (@($errs).Count) { throw ('Das Update enthält {0} Syntaxfehler (zuerst Zeile {1}: {2}) - es wird NICHT installiert, die bisherige Version bleibt.' -f @($errs).Count, $errs[0].Extent.StartLineNumber, $errs[0].Message) }
    if ($ExpectVersion) {
        $head = (Get-Content -LiteralPath $Path -TotalCount 40 -Encoding UTF8) -join "`n"
        if ($head -notmatch ("\`$AppVersion = '" + [regex]::Escape($ExpectVersion) + "'")) { throw ('Die Programmdatei passt nicht zur angekündigten Version {0} - Update nicht installiert.' -f $ExpectVersion) }
    }
}
function Get-PflegeVorversion {
    $d = Join-Path $DataDir 'Vorversion'
    $f = Join-Path $d 'version.txt'
    if ((Test-Path -LiteralPath $f) -and (Test-Path -LiteralPath (Join-Path $d 'PCPflege.ps1'))) { return ([string](Get-Content -LiteralPath $f -Raw)).Trim() }
    return $null
}
function Save-PflegeVorversion {
    try {
        $srcDir = if (Test-Path -LiteralPath (Join-Path $DataDir 'PCPflege.ps1')) { $DataDir } elseif ($PSScriptRoot) { $PSScriptRoot } else { return }
        $cur = Join-Path $srcDir 'PCPflege.ps1'
        if (-not (Test-Path -LiteralPath $cur)) { return }
        $v = ''; $m = Select-String -LiteralPath $cur -Pattern "^\`$AppVersion = '([^']+)'" -List; if ($m) { $v = $m.Matches[0].Groups[1].Value }
        if (-not $v) { return }
        $dst = Join-Path $DataDir 'Vorversion'
        New-Item $dst -ItemType Directory -Force | Out-Null
        foreach ($n in $UpdateFiles) { $s = Join-Path $srcDir $n; if (Test-Path -LiteralPath $s) { Copy-Item -LiteralPath $s -Destination (Join-Path $dst $n) -Force -ErrorAction Stop } }
        Set-Content -LiteralPath (Join-Path $dst 'version.txt') -Value $v -Encoding ASCII
    } catch { Write-UpdLog ('Vorversion konnte nicht gesichert werden: ' + $_.Exception.Message) }
}
function Restore-PflegeVorversion([string]$Reason) {
    $src = Join-Path $DataDir 'Vorversion'
    $v = Get-PflegeVorversion
    if (-not $v) { throw 'Es gibt keine gesicherte Vorversion.' }
    Test-PflegeScript (Join-Path $src 'PCPflege.ps1')
    $targets = @($DataDir); if ($PSScriptRoot -and ($PSScriptRoot.TrimEnd('\') -ne $DataDir.TrimEnd('\'))) { $targets += $PSScriptRoot }
    foreach ($t in $targets) {
        foreach ($n in $UpdateFiles) {
            $s = Join-Path $src $n
            if (-not (Test-Path -LiteralPath $s)) { continue }
            try { Copy-Item -LiteralPath $s -Destination (Join-Path $t $n) -Force -ErrorAction Stop } catch { if ($t -eq $DataDir) { throw } }
        }
    }
    if ($AppVersion -ne $v) { Add-UpdateSkip $AppVersion }
    Write-UpdLog ('Zurück auf Vorversion {0} (von {1}): {2}' -f $v, $AppVersion, $Reason)
    return $v
}
function Enter-PflegeLock([int]$WaitMin = 90) {
    # verhindert, dass Zeitplan, Fernauftrag und Oberfläche gleichzeitig Aufgaben ausführen (winget, Windows Update ... vertragen das nicht)
    # Rückgabe: Mutex (gesperrt), $null (Sperre nicht verfügbar - trotzdem weiter) oder $false (Zeitlimit/Abbruch)
    $m = $null
    try {
        $sec = New-Object Security.AccessControl.MutexSecurity
        foreach ($sid in 'S-1-5-18', 'S-1-5-32-544') { $sec.AddAccessRule((New-Object Security.AccessControl.MutexAccessRule((New-Object Security.Principal.SecurityIdentifier($sid)), [Security.AccessControl.MutexRights]::FullControl, [Security.AccessControl.AccessControlType]::Allow))) }
        $created = $false
        $m = [Threading.Mutex]::new($false, 'Global\PCTools-Engine', [ref]$created, $sec)
    } catch { try { $m = [Threading.Mutex]::new($false, 'Global\PCTools-Engine') } catch { return $null } }
    $sw = [Diagnostics.Stopwatch]::StartNew(); $said = $false
    while ($true) {
        try { if ($m.WaitOne(5000)) { return $m } } catch [Threading.AbandonedMutexException] { return $m } catch { return $null }
        if (-not $said) { $said = $true; try { Write-PLog 'Eine andere PC-Tools-Aufgabe läuft gerade (z.B. die automatische Pflege) - es geht weiter, sobald sie fertig ist ...' 'WARN' } catch { } }
        try { $Script:Detail = 'wartet auf eine andere laufende PC-Tools-Aufgabe'; Set-PStatus 'Wartet auf andere Aufgabe ...' } catch { }
        $cx = $false; try { $cx = Test-PCancel } catch { }
        if ($cx -or $sw.Elapsed.TotalMinutes -ge $WaitMin) { try { $m.Dispose() } catch { }; return $false }
    }
}
function Exit-PflegeLock($Lock) { if ($Lock) { try { $Lock.ReleaseMutex() } catch { }; try { $Lock.Dispose() } catch { } } }
function Install-PflegeUpdate([string]$Source, $Manifest) {
    $tmp = Join-Path $DataDir 'Update'
    Remove-Item -LiteralPath $tmp -Recurse -Force -ErrorAction SilentlyContinue
    New-Item $tmp -ItemType Directory -Force | Out-Null
    foreach ($f in $Manifest.Files) {
        $name = [IO.Path]::GetFileName([string]$f.Name)
        if ($UpdateFiles -notcontains $name) { throw ('Unerwartete Datei im Update: {0}' -f $name) }
        $dst = Join-Path $tmp $name
        $gh = Get-GitHubSource $Source
        if ($gh) { Invoke-GitHubRaw $gh $name $dst }
        elseif ($Source -match '^https?://') { Invoke-WebRequest -Uri ($Source.TrimEnd('/') + '/' + $name) -OutFile $dst -UseBasicParsing -TimeoutSec 300 }
        else { Copy-Item -LiteralPath (Join-Path $Source $name) -Destination $dst -Force -ErrorAction Stop }
        $h = (Get-FileHash -LiteralPath $dst -Algorithm SHA256).Hash
        if ($h -ne ([string]$f.Sha256).ToUpper()) { throw ('Prüfsumme stimmt nicht: {0}' -f $name) }
    }
    Install-PflegeUpdateFiles $tmp $Manifest
}
function Install-PflegeUpdateFiles([string]$tmp, $Manifest) {
    $newPs = Join-Path $tmp 'PCPflege.ps1'
    if (Test-Path -LiteralPath $newPs) { try { Test-PflegeScript $newPs ([string]$Manifest.Version) } catch { Write-UpdLog ('Update {0} abgelehnt: {1}' -f $Manifest.Version, $_.Exception.Message); throw } }
    Save-PflegeVorversion
    Write-UpdLog ('Update {0} -> {1} wird installiert (Vorversion gesichert)' -f $AppVersion, $Manifest.Version)
    $targets = @($DataDir)
    if ($PSScriptRoot -and ($PSScriptRoot.TrimEnd('\') -ne $DataDir.TrimEnd('\'))) { $targets += $PSScriptRoot }
    foreach ($t in $targets) {
        foreach ($f in $Manifest.Files) {
            $name = [IO.Path]::GetFileName([string]$f.Name)
            try { Copy-Item -LiteralPath (Join-Path $tmp $name) -Destination (Join-Path $t $name) -Force -ErrorAction Stop } catch { if ($t -eq $DataDir) { throw } }
        }
    }
    Remove-Item -LiteralPath $tmp -Recurse -Force -ErrorAction SilentlyContinue
}
function Publish-PflegeUpdate([string]$Source, [string]$Notes) {
    $gh = Get-GitHubSource $Source
    if ($gh) {
        $files = @()
        foreach ($n in $UpdateFiles) {
            $src = Join-Path $PSScriptRoot $n
            if (-not (Test-Path -LiteralPath $src)) { continue }
            Publish-GitHubFile $gh $n ([IO.File]::ReadAllBytes($src)) ('PC-Tools {0}: {1}' -f $AppVersion, $n)
            $files += [ordered]@{ Name = $n; Sha256 = (Get-FileHash -LiteralPath $src -Algorithm SHA256).Hash }
        }
        $json = [ordered]@{ Version = $AppVersion; Date = (Get-Date).ToString('yyyy-MM-dd HH:mm'); Notes = $Notes; Files = $files } | ConvertTo-Json -Depth 4
        Publish-GitHubFile $gh 'version.json' ([Text.Encoding]::UTF8.GetBytes($json)) ('PC-Tools {0} veröffentlicht' -f $AppVersion)
        return
    }
    if ($Source -match '^https?://') { throw 'Veröffentlichen geht nur in einen Ordner bzw. eine Netzwerkfreigabe. Für eine Webadresse den Ordnerinhalt dorthin hochladen.' }
    New-Item -Path $Source -ItemType Directory -Force | Out-Null
    $files = @()
    foreach ($n in $UpdateFiles) {
        $src = Join-Path $PSScriptRoot $n
        if (-not (Test-Path -LiteralPath $src)) { continue }
        Copy-Item -LiteralPath $src -Destination (Join-Path $Source $n) -Force
        $files += [ordered]@{ Name = $n; Sha256 = (Get-FileHash -LiteralPath $src -Algorithm SHA256).Hash }
    }
    [ordered]@{ Version = $AppVersion; Date = (Get-Date).ToString('yyyy-MM-dd HH:mm'); Notes = $Notes; Files = $files } |
        ConvertTo-Json -Depth 4 | Set-Content -LiteralPath (Join-Path $Source 'version.json') -Encoding UTF8
}

# =====================================================================
#  AUTOMATIK-MODUS (geplante Aufgabe)
# =====================================================================

# =====================================================================
#  DESKTOP-SYMBOLE UND MONITORE (auch ohne Oberfläche: -DeskArrange, -Monitor, -Topology)
# =====================================================================
$NativeHelpers = @'
using System;
using System.Collections.Generic;
using System.ComponentModel;
using System.Runtime.InteropServices;
using System.Text;

namespace PCPflege {
    public class DisplaySnapshot { public byte[] Paths; public byte[] Modes; public int PathCount; public int ModeCount; }

    public static class Displays {
        public const int PATH = 72, MODE = 64;
        [DllImport("user32.dll")] static extern int GetDisplayConfigBufferSizes(uint flags, out uint np, out uint nm);
        [DllImport("user32.dll")] static extern int QueryDisplayConfig(uint flags, ref uint np, IntPtr paths, ref uint nm, IntPtr modes, IntPtr topo);
        [DllImport("user32.dll")] static extern int SetDisplayConfig(uint np, IntPtr paths, uint nm, IntPtr modes, uint flags);
        [DllImport("user32.dll")] static extern int DisplayConfigGetDeviceInfo(IntPtr packet);

        public static DisplaySnapshot Query(bool all) {
            uint flags = all ? 1u : 2u;   // QDC_ALL_PATHS / QDC_ONLY_ACTIVE_PATHS
            for (int attempt = 0; attempt < 5; attempt++) {
                uint np, nm;
                int r = GetDisplayConfigBufferSizes(flags, out np, out nm);
                if (r != 0) throw new Win32Exception(r);
                IntPtr pp = Marshal.AllocHGlobal((int)Math.Max(1, np) * PATH);
                IntPtr pm = Marshal.AllocHGlobal((int)Math.Max(1, nm) * MODE);
                try {
                    r = QueryDisplayConfig(flags, ref np, pp, ref nm, pm, IntPtr.Zero);
                    if (r == 122) continue;
                    if (r != 0) throw new Win32Exception(r);
                    DisplaySnapshot s = new DisplaySnapshot();
                    s.PathCount = (int)np; s.ModeCount = (int)nm;
                    s.Paths = new byte[np * PATH]; s.Modes = new byte[nm * MODE];
                    if (s.Paths.Length > 0) Marshal.Copy(pp, s.Paths, 0, s.Paths.Length);
                    if (s.Modes.Length > 0) Marshal.Copy(pm, s.Modes, 0, s.Modes.Length);
                    return s;
                } finally { Marshal.FreeHGlobal(pp); Marshal.FreeHGlobal(pm); }
            }
            throw new Exception("Die Monitor-Konfiguration ändert sich gerade - bitte erneut versuchen.");
        }

        public static int Apply(byte[] paths, int np, byte[] modes, int nm, bool validateOnly) {
            // SDC_USE_SUPPLIED_DISPLAY_CONFIG | SDC_ALLOW_CHANGES, dazu VALIDATE oder APPLY + SAVE_TO_DATABASE
            uint flags = 0x20u | 0x400u;
            flags |= validateOnly ? 0x40u : (0x80u | 0x200u);
            IntPtr pp = Marshal.AllocHGlobal(Math.Max(1, paths.Length));
            IntPtr pm = Marshal.AllocHGlobal(Math.Max(1, modes.Length));
            try {
                if (paths.Length > 0) Marshal.Copy(paths, 0, pp, paths.Length);
                if (modes.Length > 0) Marshal.Copy(modes, 0, pm, modes.Length);
                return SetDisplayConfig((uint)np, pp, (uint)nm, pm, flags);
            } finally { Marshal.FreeHGlobal(pp); Marshal.FreeHGlobal(pm); }
        }

        // 1 = nur Hauptbildschirm, 2 = duplizieren, 4 = erweitern, 8 = nur zweiter Bildschirm
        public static int SetTopology(uint topology) { return SetDisplayConfig(0, IntPtr.Zero, 0, IntPtr.Zero, topology | 0x80u); }

        static string DevInfo(int type, int size, uint low, int high, uint id, int strOffset) {
            IntPtr buf = Marshal.AllocHGlobal(size);
            try {
                Marshal.Copy(new byte[size], 0, buf, size);
                Marshal.WriteInt32(buf, 0, type); Marshal.WriteInt32(buf, 4, size);
                Marshal.WriteInt32(buf, 8, (int)low); Marshal.WriteInt32(buf, 12, high); Marshal.WriteInt32(buf, 16, (int)id);
                if (DisplayConfigGetDeviceInfo(buf) != 0) return "";
                string s = Marshal.PtrToStringUni(IntPtr.Add(buf, strOffset));
                return s == null ? "" : s;
            } finally { Marshal.FreeHGlobal(buf); }
        }
        public static string AdapterPath(uint low, int high) { return DevInfo(4, 276, low, high, 0, 20); }
        public static string MonitorName(uint low, int high, uint targetId) { return DevInfo(2, 420, low, high, targetId, 36); }
        public static string GdiName(uint low, int high, uint sourceId) { return DevInfo(1, 84, low, high, sourceId, 20); }

        // Name|Breite|Höhe|X|Y|Hz|\\.\DISPLAYn|TargetId|Drehung  (nur aktive Pfade)
        public static string[] Describe(DisplaySnapshot s) {
            List<string> list = new List<string>();
            for (int i = 0; i < s.PathCount; i++) {
                int o = i * PATH;
                if ((BitConverter.ToUInt32(s.Paths, o + 68) & 1u) == 0) continue;
                uint sLow = BitConverter.ToUInt32(s.Paths, o); int sHigh = BitConverter.ToInt32(s.Paths, o + 4);
                uint sId = BitConverter.ToUInt32(s.Paths, o + 8); uint sIdx = BitConverter.ToUInt32(s.Paths, o + 12);
                uint tLow = BitConverter.ToUInt32(s.Paths, o + 20); int tHigh = BitConverter.ToInt32(s.Paths, o + 24);
                uint tId = BitConverter.ToUInt32(s.Paths, o + 28); uint rot = BitConverter.ToUInt32(s.Paths, o + 40);
                uint rn = BitConverter.ToUInt32(s.Paths, o + 48); uint rd = BitConverter.ToUInt32(s.Paths, o + 52);
                int w = 0, h = 0, x = 0, y = 0;
                if (sIdx != 0xFFFFFFFFu && sIdx < (uint)s.ModeCount) {
                    int m = (int)sIdx * MODE;
                    if (BitConverter.ToInt32(s.Modes, m) == 1) {
                        w = BitConverter.ToInt32(s.Modes, m + 16); h = BitConverter.ToInt32(s.Modes, m + 20);
                        x = BitConverter.ToInt32(s.Modes, m + 28); y = BitConverter.ToInt32(s.Modes, m + 32);
                    }
                }
                string name = MonitorName(tLow, tHigh, tId);
                if (name.Length == 0) name = "Monitor " + tId;
                long hz = rd != 0 ? (long)Math.Round((double)rn / rd) : 0;
                list.Add(string.Join("|", new string[] { name, w.ToString(), h.ToString(), x.ToString(), y.ToString(), hz.ToString(), GdiName(sLow, sHigh, sId), tId.ToString(), rot.ToString() }));
            }
            return list.ToArray();
        }
    }

    public static class DesktopIcons {
        [DllImport("user32.dll", CharSet = CharSet.Unicode)] static extern IntPtr FindWindow(string cls, string title);
        [DllImport("user32.dll", CharSet = CharSet.Unicode)] static extern IntPtr FindWindowEx(IntPtr parent, IntPtr after, string cls, string title);
        [DllImport("user32.dll")] static extern IntPtr SendMessage(IntPtr h, uint msg, IntPtr w, IntPtr l);
        [DllImport("user32.dll")] static extern bool PostMessage(IntPtr h, uint msg, IntPtr w, IntPtr l);
        [DllImport("user32.dll")] static extern uint GetWindowThreadProcessId(IntPtr h, out uint pid);
        [DllImport("user32.dll")] static extern int GetWindowLong(IntPtr h, int idx);
        [DllImport("user32.dll")] static extern bool InvalidateRect(IntPtr h, IntPtr r, bool erase);
        [DllImport("user32.dll")] static extern bool ScreenToClient(IntPtr h, ref POINT p);
        [DllImport("user32.dll")] static extern IntPtr MonitorFromPoint(POINT pt, uint flags);
        [DllImport("user32.dll")] static extern bool GetMonitorInfo(IntPtr mon, ref MONITORINFO mi);
        [DllImport("user32.dll")] static extern IntPtr SetThreadDpiAwarenessContext(IntPtr ctx);
        [DllImport("kernel32.dll")] static extern IntPtr OpenProcess(uint access, bool inherit, uint pid);
        [DllImport("kernel32.dll")] static extern IntPtr VirtualAllocEx(IntPtr hp, IntPtr addr, UIntPtr size, uint type, uint protect);
        [DllImport("kernel32.dll")] static extern bool VirtualFreeEx(IntPtr hp, IntPtr addr, UIntPtr size, uint type);
        [DllImport("kernel32.dll")] static extern bool WriteProcessMemory(IntPtr hp, IntPtr addr, byte[] buf, UIntPtr size, out UIntPtr done);
        [DllImport("kernel32.dll")] static extern bool ReadProcessMemory(IntPtr hp, IntPtr addr, byte[] buf, UIntPtr size, out UIntPtr done);
        [DllImport("kernel32.dll")] static extern bool CloseHandle(IntPtr h);

        [StructLayout(LayoutKind.Sequential)] public struct POINT { public int X; public int Y; }
        [StructLayout(LayoutKind.Sequential)] public struct RECT { public int Left; public int Top; public int Right; public int Bottom; }
        [StructLayout(LayoutKind.Sequential)] public struct MONITORINFO { public int cbSize; public RECT rcMonitor; public RECT rcWork; public uint dwFlags; }

        const uint LVM_GETITEMCOUNT = 0x1004, LVM_SETITEMPOSITION = 0x100F, LVM_GETITEMPOSITION = 0x1010, LVM_GETITEMSPACING = 0x1033, LVM_GETITEMTEXTW = 0x1073;

        public static IntPtr DefView() {
            IntPtr progman = FindWindow("Progman", null);
            IntPtr dv = FindWindowEx(progman, IntPtr.Zero, "SHELLDLL_DefView", null);
            IntPtr w = IntPtr.Zero;
            while (dv == IntPtr.Zero) {
                w = FindWindowEx(IntPtr.Zero, w, "WorkerW", null);
                if (w == IntPtr.Zero) break;
                dv = FindWindowEx(w, IntPtr.Zero, "SHELLDLL_DefView", null);
            }
            return dv;
        }
        public static IntPtr ListView() {
            IntPtr dv = DefView();
            return dv == IntPtr.Zero ? IntPtr.Zero : FindWindowEx(dv, IntPtr.Zero, "SysListView32", null);
        }
        public static bool IsAutoArrange(IntPtr lv) { return (GetWindowLong(lv, -16) & 0x0100) != 0; }
        public static int Count(IntPtr lv) { return (int)SendMessage(lv, LVM_GETITEMCOUNT, IntPtr.Zero, IntPtr.Zero); }
        public static int[] Spacing(IntPtr lv) {
            long v = (long)SendMessage(lv, LVM_GETITEMSPACING, IntPtr.Zero, IntPtr.Zero);
            return new int[] { (int)(v & 0xFFFF), (int)((v >> 16) & 0xFFFF) };
        }
        // Arbeitsbereich des Hauptbildschirms in Koordinaten der Desktop-Liste (physische Pixel)
        public static int[] PrimaryWorkArea(IntPtr lv) {
            IntPtr old = IntPtr.Zero;
            try { old = SetThreadDpiAwarenessContext(new IntPtr(-4)); } catch (EntryPointNotFoundException) { }
            try {
                POINT z = new POINT();
                IntPtr mon = MonitorFromPoint(z, 1);
                MONITORINFO mi = new MONITORINFO(); mi.cbSize = Marshal.SizeOf(typeof(MONITORINFO));
                GetMonitorInfo(mon, ref mi);
                POINT a = new POINT(); a.X = mi.rcWork.Left; a.Y = mi.rcWork.Top;
                POINT b = new POINT(); b.X = mi.rcWork.Right; b.Y = mi.rcWork.Bottom;
                ScreenToClient(lv, ref a); ScreenToClient(lv, ref b);
                return new int[] { a.X, a.Y, b.X, b.Y };
            } finally { if (old != IntPtr.Zero) { try { SetThreadDpiAwarenessContext(old); } catch (EntryPointNotFoundException) { } } }
        }

        static IntPtr OpenShell(IntPtr lv, out IntPtr mem) {
            if (IntPtr.Size != 8) throw new Exception("Bitte die 64-Bit-PowerShell verwenden.");
            uint pid; GetWindowThreadProcessId(lv, out pid);
            IntPtr hp = OpenProcess(0x0008 | 0x0010 | 0x0020, false, pid);
            if (hp == IntPtr.Zero) throw new Win32Exception(Marshal.GetLastWin32Error());
            mem = VirtualAllocEx(hp, IntPtr.Zero, (UIntPtr)4096, 0x3000, 0x04);
            if (mem == IntPtr.Zero) { CloseHandle(hp); throw new Exception("Speicher im Explorer konnte nicht reserviert werden."); }
            return hp;
        }
        static void CloseShell(IntPtr hp, IntPtr mem) { VirtualFreeEx(hp, mem, UIntPtr.Zero, 0x8000); CloseHandle(hp); }

        public static string[] Names(IntPtr lv) {
            IntPtr mem; IntPtr hp = OpenShell(lv, out mem);
            try {
                int n = Count(lv); string[] res = new string[n];
                const int textOff = 512, cch = 520; UIntPtr done;
                for (int i = 0; i < n; i++) {
                    byte[] item = new byte[88];   // LVITEMW (64 Bit)
                    BitConverter.GetBytes(1).CopyTo(item, 0);                              // mask = LVIF_TEXT
                    BitConverter.GetBytes(i).CopyTo(item, 4);                              // iItem
                    BitConverter.GetBytes(new IntPtr(mem.ToInt64() + textOff).ToInt64()).CopyTo(item, 24);  // pszText
                    BitConverter.GetBytes(cch).CopyTo(item, 32);                           // cchTextMax
                    WriteProcessMemory(hp, mem, item, (UIntPtr)item.Length, out done);
                    int len = (int)SendMessage(lv, LVM_GETITEMTEXTW, new IntPtr(i), mem);
                    byte[] buf = new byte[cch * 2];
                    ReadProcessMemory(hp, new IntPtr(mem.ToInt64() + textOff), buf, (UIntPtr)buf.Length, out done);
                    res[i] = Encoding.Unicode.GetString(buf, 0, Math.Max(0, Math.Min(len, cch)) * 2);
                }
                return res;
            } finally { CloseShell(hp, mem); }
        }
        public static int[] Positions(IntPtr lv) {
            IntPtr mem; IntPtr hp = OpenShell(lv, out mem);
            try {
                int n = Count(lv); int[] res = new int[n * 2]; byte[] buf = new byte[8]; UIntPtr done;
                for (int i = 0; i < n; i++) {
                    SendMessage(lv, LVM_GETITEMPOSITION, new IntPtr(i), mem);
                    ReadProcessMemory(hp, mem, buf, (UIntPtr)8, out done);
                    res[i * 2] = BitConverter.ToInt32(buf, 0); res[i * 2 + 1] = BitConverter.ToInt32(buf, 4);
                }
                return res;
            } finally { CloseShell(hp, mem); }
        }
        public static void SetPosition(IntPtr lv, int index, int x, int y) {
            int lp = ((y & 0xFFFF) << 16) | (x & 0xFFFF);
            SendMessage(lv, LVM_SETITEMPOSITION, new IntPtr(index), new IntPtr(lp));
        }
        public static void Redraw(IntPtr lv) { InvalidateRect(lv, IntPtr.Zero, true); }
        public static void Refresh() { IntPtr dv = DefView(); if (dv != IntPtr.Zero) PostMessage(dv, 0x0111, new IntPtr(0x7103), IntPtr.Zero); }
    }

    public static class SysStats {
        [DllImport("kernel32.dll")] static extern bool GetSystemTimes(out long idle, out long kernel, out long user);
        [StructLayout(LayoutKind.Sequential)]
        public class MEMORYSTATUSEX {
            public uint dwLength = 64; public uint dwMemoryLoad; public ulong ullTotalPhys; public ulong ullAvailPhys;
            public ulong ullTotalPageFile; public ulong ullAvailPageFile; public ulong ullTotalVirtual; public ulong ullAvailVirtual; public ulong ullAvailExtendedVirtual;
        }
        [DllImport("kernel32.dll")] static extern bool GlobalMemoryStatusEx([In, Out] MEMORYSTATUSEX m);
        static long lastIdle, lastTotal;
        public static double Cpu() {
            long i, k, u;
            if (!GetSystemTimes(out i, out k, out u)) return 0;
            long total = k + u; long di = i - lastIdle, dt = total - lastTotal;
            lastIdle = i; lastTotal = total;
            if (dt <= 0) return 0;
            return Math.Max(0, Math.Min(100, 100.0 * (dt - di) / dt));
        }
        // Gesamt, frei, Auslastung %, Zusagegrenze, Zusage frei
        public static ulong[] Memory() {
            MEMORYSTATUSEX m = new MEMORYSTATUSEX();
            GlobalMemoryStatusEx(m);
            return new ulong[] { m.ullTotalPhys, m.ullAvailPhys, m.dwMemoryLoad, m.ullTotalPageFile, m.ullAvailPageFile };
        }
    }

    public class ProcRow : INotifyPropertyChanged {
        public event PropertyChangedEventHandler PropertyChanged;
        void N(string p) { PropertyChangedEventHandler h = PropertyChanged; if (h != null) h(this, new PropertyChangedEventArgs(p)); }
        public int Pid { get; set; }
        public string Name { get; set; }
        public string Description { get; set; }
        public string Path { get; set; }
        public string Title { get; set; }
        public long LastTicks { get; set; }
        public bool Seen { get; set; }
        double cpu, ram; int threads;
        public double Cpu { get { return cpu; } set { if (cpu != value) { cpu = value; N("Cpu"); N("CpuText"); } } }
        public string CpuText { get { return cpu < 0.05 ? "" : cpu.ToString("0.0") + " %"; } }
        public double RamMB { get { return ram; } set { if (ram != value) { ram = value; N("RamMB"); N("RamText"); } } }
        public string RamText { get { return ram.ToString("N1") + " MB"; } }
        public int Threads { get { return threads; } set { if (threads != value) { threads = value; N("Threads"); } } }
    }
}
'@
function Import-NativeHelpers {
    if (-not ('PCPflege.DesktopIcons' -as [type])) { Add-Type -TypeDefinition $NativeHelpers -Language CSharp }
}
function Test-IsAdmin { ([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator) }

function Restart-Explorer {
    Get-Process -Name explorer -ErrorAction SilentlyContinue | Where-Object { $_.SessionId -eq (Get-Process -Id $PID).SessionId } | Stop-Process -Force -ErrorAction SilentlyContinue
    Start-Sleep -Seconds 2
    if (-not (Get-Process -Name explorer -ErrorAction SilentlyContinue)) {
        if (Test-IsAdmin) {
            # Explorer nicht mit Admin-Rechten starten, sondern über eine Aufgabe für den angemeldeten Benutzer
            $grp = (New-Object Security.Principal.SecurityIdentifier 'S-1-5-4').Translate([Security.Principal.NTAccount]).Value
            $act = New-ScheduledTaskAction -Execute (Join-Path $env:SystemRoot 'explorer.exe')
            Register-ScheduledTask -TaskName 'PCPflege_ExplorerRestart' -Action $act -Principal (New-ScheduledTaskPrincipal -GroupId $grp -RunLevel Limited) -Force | Out-Null
            Start-ScheduledTask -TaskName 'PCPflege_ExplorerRestart'; Start-Sleep -Seconds 2
            Unregister-ScheduledTask -TaskName 'PCPflege_ExplorerRestart' -Confirm:$false -ErrorAction SilentlyContinue
        } else { Start-Process -FilePath (Join-Path $env:SystemRoot 'explorer.exe') }
    }
}

# ---- Programmkategorien für Desktop-Symbole: Reihenfolge = Reihenfolge auf dem Desktop (von links nach rechts)
