function Get-DeskGroup([string]$Name, $Info) {
    if ($Info) {
        if ($Info.IsFolder -or $Info.TargetIsFolder) { return 'Ordner' }
        if ($Info.Args -match '-Monitor|-DeskArrange|-Topology' -or $Info.Target -match 'PCPflege\.ps1|\\PCPflege\\') { return 'Windows' }
        if (-not $Info.IsShortcut) { return 'Dateien & Links' }
    }
    $n = $Name.ToLower()
    foreach ($k in $DeskGroupRules.Keys) { if ($n -match $DeskGroupRules[$k]) { return $k } }
    if ($Info -and $Info.Target) {
        $t = $Info.Target.ToLower()
        foreach ($k in $DeskGroupRules.Keys) { if ($k -ne 'Windows' -and $t -match $DeskGroupRules[$k]) { return $k } }
        if ($t -match '^(https?|ftp)://') { return 'Dateien & Links' }
    }
    if (-not $Info) { return 'Windows' }   # virtuelle Symbole (Papierkorb, Dieser PC ...)
    if ($Info.Ext -in '.url', '.website') { return 'Dateien & Links' }
    return 'Sonstige Programme'
}
# Dateien beider Desktops, erreichbar über den angezeigten Namen (mit und ohne Endung)
function Get-DeskIconInventory {
    $map = @{}
    $shell = New-Object -ComObject WScript.Shell
    foreach ($dir in @([Environment]::GetFolderPath('Desktop'), [Environment]::GetFolderPath('CommonDesktopDirectory'))) {
        if (-not $dir -or -not (Test-Path -LiteralPath $dir)) { continue }
        foreach ($it in @(Get-ChildItem -LiteralPath $dir -Force -ErrorAction SilentlyContinue | Where-Object { $_.Name -ne 'desktop.ini' })) {
            $info = [pscustomobject]@{ Name = $it.Name; Path = $it.FullName; IsFolder = [bool]$it.PSIsContainer; Ext = $it.Extension.ToLower()
                                       IsShortcut = $it.Extension -in '.lnk', '.url', '.website', '.appref-ms'; Target = ''; Args = ''; TargetIsFolder = $false }
            if ($info.Ext -eq '.lnk') {
                try { $sc = $shell.CreateShortcut($it.FullName); $info.Target = [string]$sc.TargetPath; $info.Args = [string]$sc.Arguments } catch { }
                if ($info.Target -and -not $info.Target.EndsWith('.exe') -and (Test-Path -LiteralPath $info.Target -PathType Container -ErrorAction SilentlyContinue)) { $info.TargetIsFolder = $true }
            } elseif ($info.Ext -eq '.url') {
                try { $u = (Get-Content -LiteralPath $it.FullName -ErrorAction Stop | Where-Object { $_ -like 'URL=*' } | Select-Object -First 1); if ($u) { $info.Target = $u.Substring(4) } } catch { }
            }
            foreach ($k in @($it.Name, $(if (-not $it.PSIsContainer) { $it.BaseName }))) { if ($k -and -not $map.ContainsKey($k.ToLower())) { $map[$k.ToLower()] = $info } }
        }
    }
    try { [void][Runtime.InteropServices.Marshal]::ReleaseComObject($shell) } catch { }
    return $map
}
function Get-DeskListView {
    Import-NativeHelpers
    for ($i = 0; $i -lt 30; $i++) {
        $lv = [PCPflege.DesktopIcons]::ListView()
        if ($lv -ne [IntPtr]::Zero -and [PCPflege.DesktopIcons]::Count($lv) -gt 0) { return $lv }
        Start-Sleep -Milliseconds 500
    }
    throw 'Die Desktop-Symbolliste wurde nicht gefunden (Explorer läuft nicht oder die Desktopsymbole sind ausgeblendet).'
}
# Automatisch anordnen abschalten (sonst setzt Windows jede Position sofort zurück) - braucht einen Explorer-Neustart
function Disable-DeskAutoArrange {
    $k = 'HKCU:\Software\Microsoft\Windows\Shell\Bags\1\Desktop'
    if (-not (Test-Path $k)) { New-Item $k -Force | Out-Null }
    $f = (Get-ItemProperty -Path $k -Name FFlags -ErrorAction SilentlyContinue).FFlags
    if ($null -eq $f) { $f = 0x40200224 } else { $f = [int]$f -band -2 }
    New-ItemProperty -Path $k -Name FFlags -Value ([int]$f) -PropertyType DWord -Force -ErrorAction SilentlyContinue | Out-Null
    Restart-Explorer
    Start-Sleep -Seconds 3
}
$DeskFolderNames = @{ 'Büro & Dokumente' = 'Büro'; 'System & Wartung' = 'System & Tools'; 'Sonstige Programme' = 'Weitere Programme'; 'Dateien & Links' = 'Internet-Links' }
function Get-DeskFolderName([string]$Group) { if ($DeskFolderNames.ContainsKey($Group)) { $DeskFolderNames[$Group] } else { $Group } }
# Sortierung innerhalb der Gruppen: Windows-Symbole und persönliche Ordner in sinnvoller Reihenfolge, Kategorie-Ordner wie die Kategorien
$DeskWinOrder = @('papierkorb', 'recycle bin', 'dieser pc', 'this pc', 'netzwerk', 'systemsteuerung', 'pc-pflege', 'desktop ordnen', 'monitor', 'neustart', 'herunterfahren')
$DeskUserFolderOrder = @('desktop', 'dokumente', 'documents', 'downloads', 'bilder', 'pictures', 'musik', 'music', 'videos')
function Get-DeskSortKey($Item) {
    $n = $Item.Name.ToLower()
    switch ($Item.Group) {
        'Windows' { $i = 50; for ($k = 0; $k -lt $DeskWinOrder.Count; $k++) { if ($n.StartsWith($DeskWinOrder[$k])) { $i = $k; break } }; return ('{0:D2}{1}' -f $i, $n) }
        'Kategorien' { return ('{0:D2}' -f [array]::IndexOf($DeskGroupOrder, $Item.Category)) }
        'Ordner' {
            if ($n -in 'ablage', '_alt') { return ('99' + $n) }
            $i = [array]::IndexOf($DeskUserFolderOrder, $n); if ($i -lt 0) { $i = 50 }
            return ('{0:D2}{1}' -f $i, $n)
        }
        default { return $n }
    }
}
function Get-DeskArrangePlan {
    $lv = Get-DeskListView
    $names = [PCPflege.DesktopIcons]::Names($lv)
    $inv = Get-DeskIconInventory
    $catFolders = @{}; foreach ($g in $DeskGroupOrder) { $catFolders[(Get-DeskFolderName $g).ToLower()] = $g }
    $items = for ($i = 0; $i -lt $names.Count; $i++) {
        $nm = [string]$names[$i]
        $info = $inv[$nm.ToLower()]
        $grp = Get-DeskGroup $nm $info; $cat = ''
        if ($grp -eq 'Ordner' -and $info -and $info.IsFolder -and $catFolders.ContainsKey($nm.ToLower())) { $grp = 'Kategorien'; $cat = $catFolders[$nm.ToLower()] }
        $o = [pscustomobject]@{ Index = $i; Name = $nm; Group = $grp; Category = $cat; Info = $info; Sort = '' }
        $o.Sort = Get-DeskSortKey $o
        $o
    }
    $groups = foreach ($g in $DeskGroupOrder) {
        $m = @($items | Where-Object Group -eq $g | Sort-Object Sort)
        if ($m.Count) { [pscustomobject]@{ Name = $(if ($g -eq 'Kategorien') { 'Kategorie-Ordner' } else { $g }); Items = $m } }
    }
    return [pscustomobject]@{ ListView = $lv; Groups = @($groups); Count = $names.Count }
}
function Invoke-DeskArrange([switch]$Gap, [switch]$AllowRestart, [string]$Layout = 'Zeilen') {
    Import-NativeHelpers
    $lv = Get-DeskListView
    if ([PCPflege.DesktopIcons]::IsAutoArrange($lv)) {
        if (-not $AllowRestart) { throw 'AUTOARRANGE' }
        Disable-DeskAutoArrange
    }
    [PCPflege.DesktopIcons]::Refresh(); Start-Sleep -Milliseconds 1500
    $plan = Get-DeskArrangePlan
    $lv = $plan.ListView
    if ([PCPflege.DesktopIcons]::IsAutoArrange($lv)) { throw 'Windows ordnet die Symbole weiterhin automatisch an. Bitte Rechtsklick auf den Desktop > Ansicht > "Symbole automatisch anordnen" ausschalten.' }
    $sp = [PCPflege.DesktopIcons]::Spacing($lv); $cx = [math]::Max(40, $sp[0]); $cy = [math]::Max(40, $sp[1])
    $wa = [PCPflege.DesktopIcons]::PrimaryWorkArea($lv)
    # Rasterursprung wie Windows: kleinster vorhandener Abstand zum Rand des Arbeitsbereichs
    $pos = [PCPflege.DesktopIcons]::Positions($lv)
    $ox = $wa[0] + 2; $oy = $wa[1] + 2
    $xs = @(for ($i = 0; $i -lt $pos.Count; $i += 2) { if ($pos[$i] -ge $wa[0] -and $pos[$i] -lt $wa[0] + $cx) { $pos[$i] } })
    $ys = @(for ($i = 1; $i -lt $pos.Count; $i += 2) { if ($pos[$i] -ge $wa[1] -and $pos[$i] -lt $wa[1] + $cy) { $pos[$i] } })
    if ($xs.Count) { $ox = ($xs | Measure-Object -Minimum).Minimum }
    if ($ys.Count) { $oy = ($ys | Measure-Object -Minimum).Minimum }
    $rows = [math]::Max(1, [math]::Floor(($wa[3] - $oy) / $cy))
    $maxCols = [math]::Max(1, [math]::Floor(($wa[2] - $ox) / $cx))
    if ($Layout -notlike 'Spalten*') {
        # Zeilen: oben entlang von links nach rechts, jede Gruppe beginnt in einer neuen Zeile
        $need = 0; foreach ($g in $plan.Groups) { $need += [math]::Ceiling($g.Items.Count / $maxCols) }
        $useGap = $Gap -and ($need + $plan.Groups.Count - 1) -le $rows
        $col = 0; $row = 0; $first = $true
        foreach ($g in $plan.Groups) {
            if (-not $first) { if ($col -ne 0) { $row++; $col = 0 }; if ($useGap) { $row++ } }
            $first = $false
            foreach ($it in $g.Items) {
                [PCPflege.DesktopIcons]::SetPosition($lv, $it.Index, [int]($ox + $col * $cx), [int]($oy + $row * $cy))
                $col++; if ($col -ge $maxCols) { $col = 0; $row++ }
            }
        }
        [PCPflege.DesktopIcons]::Redraw($lv)
        return [pscustomobject]@{ Count = $plan.Count; Groups = $plan.Groups; Rows = $row + [int]($col -gt 0); Gap = $useGap; OwnColumns = $true; Layout = 'Zeilen' }
    }
    $need = 0; foreach ($g in $plan.Groups) { $need += [math]::Ceiling($g.Items.Count / $rows) }
    $newCol = $need -le $maxCols                                           # jede Kategorie in eigener Spalte
    $useGap = $Gap -and $newCol -and ($need + $plan.Groups.Count - 1) -le $maxCols
    $col = 0; $row = 0; $first = $true
    foreach ($g in $plan.Groups) {
        if (-not $first) {
            if ($newCol -and $row -ne 0) { $col++; $row = 0 }
            if ($useGap) { $col++ }
        }
        $first = $false
        foreach ($it in $g.Items) {
            [PCPflege.DesktopIcons]::SetPosition($lv, $it.Index, [int]($ox + $col * $cx), [int]($oy + $row * $cy))
            $row++; if ($row -ge $rows) { $row = 0; $col++ }
        }
    }
    [PCPflege.DesktopIcons]::Redraw($lv)
    return [pscustomobject]@{ Count = $plan.Count; Groups = $plan.Groups; Columns = $col + [int]($row -gt 0); MaxColumns = $maxCols; Gap = $useGap; OwnColumns = $newCol }
}
$DeskLayoutFile = Join-Path (Join-Path $DataDir 'Desktop') ('layout_{0}.json' -f $env:USERNAME)
function Save-DeskLayout {
    $lv = Get-DeskListView
    $names = [PCPflege.DesktopIcons]::Names($lv); $pos = [PCPflege.DesktopIcons]::Positions($lv)
    $list = for ($i = 0; $i -lt $names.Count; $i++) { [pscustomobject]@{ Name = $names[$i]; X = $pos[$i * 2]; Y = $pos[$i * 2 + 1] } }
    New-Item (Split-Path $DeskLayoutFile) -ItemType Directory -Force | Out-Null
    $list | ConvertTo-Json -Depth 3 | Set-Content -LiteralPath $DeskLayoutFile -Encoding UTF8
    return $names.Count
}
function Restore-DeskLayout {
    if (-not (Test-Path -LiteralPath $DeskLayoutFile)) { throw 'Es wurde noch keine Anordnung gemerkt.' }
    $saved = @(Get-Content -LiteralPath $DeskLayoutFile -Raw -Encoding UTF8 | ConvertFrom-Json)
    $lv = Get-DeskListView
    if ([PCPflege.DesktopIcons]::IsAutoArrange($lv)) { throw 'AUTOARRANGE' }
    $names = [PCPflege.DesktopIcons]::Names($lv)
    $queue = @{}
    foreach ($s in $saved) { $k = [string]$s.Name; if (-not $queue.ContainsKey($k)) { $queue[$k] = New-Object System.Collections.Queue }; $queue[$k].Enqueue($s) }
    $ok = 0
    for ($i = 0; $i -lt $names.Count; $i++) {
        $q = $queue[[string]$names[$i]]
        if ($q -and $q.Count) { $s = $q.Dequeue(); [PCPflege.DesktopIcons]::SetPosition($lv, $i, [int]$s.X, [int]$s.Y); $ok++ }
    }
    [PCPflege.DesktopIcons]::Redraw($lv)
    return $ok
}

# ---- Monitor-Profile
$MonitorDir = Join-Path $DataDir 'Monitore'
function Get-MonitorLayout {
    Import-NativeHelpers
    $s = [PCPflege.Displays]::Query($false)
    return @([PCPflege.Displays]::Describe($s) | ForEach-Object {
        $f = $_ -split '\|'
        [pscustomobject]@{ Name = $f[0]; Width = [int]$f[1]; Height = [int]$f[2]; X = [int]$f[3]; Y = [int]$f[4]; Hz = [int]$f[5]
                           Display = ($f[6] -replace '^\\\\\.\\DISPLAY', ''); TargetId = $f[7]; Rotation = [int]$f[8]; Primary = ([int]$f[3] -eq 0 -and [int]$f[4] -eq 0) }
    } | Sort-Object X, Y)
}
function Get-MonitorText($m) {
    $res = if ($m.Rotation -in 2, 4) { '{0}x{1} hochkant' -f $m.Width, $m.Height } else { '{0}x{1}' -f $m.Width, $m.Height }
    '{0}: {1}  {2} @ {3} Hz{4}' -f $m.Display, $m.Name, $res, $m.Hz, $(if ($m.Primary) { '  (Hauptbildschirm)' } else { '' })
}
function Get-MonitorProfileFile([string]$Name) { Join-Path $MonitorDir (($Name -replace '[\\/:*?"<>|]', '_') + '.json') }
function Get-MonitorProfiles {
    @(Get-ChildItem -LiteralPath $MonitorDir -Filter '*.json' -ErrorAction SilentlyContinue | ForEach-Object {
        try { Get-Content -LiteralPath $_.FullName -Raw -Encoding UTF8 | ConvertFrom-Json } catch { }
    } | Where-Object { $_.Name } | Sort-Object Name)
}
function Save-MonitorProfile([string]$Name) {
    Import-NativeHelpers
    $s = [PCPflege.Displays]::Query($false)
    $adapters = @{}
    for ($i = 0; $i -lt $s.PathCount; $i++) {
        foreach ($o in ($i * 72), ($i * 72 + 20)) {
            $lo = [BitConverter]::ToUInt32($s.Paths, $o); $hi = [BitConverter]::ToInt32($s.Paths, $o + 4)
            $k = '{0}:{1}' -f $lo, $hi
            if (-not $adapters.ContainsKey($k)) { $adapters[$k] = [pscustomobject]@{ Low = $lo; High = $hi; Path = [PCPflege.Displays]::AdapterPath($lo, $hi) } }
        }
    }
    $p = [pscustomobject]@{
        Name = $Name; Created = (Get-Date).ToString('yyyy-MM-dd HH:mm'); Computer = $env:COMPUTERNAME
        PathCount = $s.PathCount; ModeCount = $s.ModeCount; Paths = [Convert]::ToBase64String($s.Paths); Modes = [Convert]::ToBase64String($s.Modes)
        Adapters = @($adapters.Values); Monitors = @(Get-MonitorLayout | ForEach-Object { Get-MonitorText $_ })
    }
    New-Item $MonitorDir -ItemType Directory -Force | Out-Null
    $p | ConvertTo-Json -Depth 4 | Set-Content -LiteralPath (Get-MonitorProfileFile $Name) -Encoding UTF8
    return $p
}
function Set-MonitorProfile([string]$Name) {
    Import-NativeHelpers
    $file = Get-MonitorProfileFile $Name
    if (-not (Test-Path -LiteralPath $file)) { throw ('Monitor-Profil "{0}" nicht gefunden.' -f $Name) }
    $p = Get-Content -LiteralPath $file -Raw -Encoding UTF8 | ConvertFrom-Json
    $paths = [Convert]::FromBase64String($p.Paths); $modes = [Convert]::FromBase64String($p.Modes)
    # Grafikkarten-Kennungen (LUID) ändern sich bei jedem Neustart -> über den Gerätepfad der Grafikkarte neu zuordnen
    $cur = [PCPflege.Displays]::Query($true)
    $byPath = @{}; $curAll = @{}
    for ($i = 0; $i -lt $cur.PathCount; $i++) {
        foreach ($o in ($i * 72), ($i * 72 + 20)) {
            $lo = [BitConverter]::ToUInt32($cur.Paths, $o); $hi = [BitConverter]::ToInt32($cur.Paths, $o + 4)
            $k = '{0}:{1}' -f $lo, $hi
            if ($curAll.ContainsKey($k)) { continue }
            $curAll[$k] = @($lo, $hi)
            $ap = [PCPflege.Displays]::AdapterPath($lo, $hi)
            if ($ap) { $byPath[$ap.ToLower()] = @($lo, $hi) }
        }
    }
    $map = @{}
    foreach ($a in @($p.Adapters)) {
        $k = '{0}:{1}' -f $a.Low, $a.High
        if ($a.Path -and $byPath.ContainsKey(([string]$a.Path).ToLower())) { $map[$k] = $byPath[([string]$a.Path).ToLower()] }
        elseif ($curAll.Count -eq 1) { $map[$k] = @($curAll.Values)[0] }
    }
    $patch = {
        param([byte[]]$Buf, [int]$Off)
        $k = '{0}:{1}' -f [BitConverter]::ToUInt32($Buf, $Off), [BitConverter]::ToInt32($Buf, $Off + 4)
        if ($map.ContainsKey($k)) {
            [Array]::Copy([BitConverter]::GetBytes([uint32]$map[$k][0]), 0, $Buf, $Off, 4)
            [Array]::Copy([BitConverter]::GetBytes([int32]$map[$k][1]), 0, $Buf, $Off + 4, 4)
        }
    }
    for ($i = 0; $i -lt [int]$p.PathCount; $i++) { & $patch $paths ($i * 72); & $patch $paths ($i * 72 + 20) }
    for ($i = 0; $i -lt [int]$p.ModeCount; $i++) { & $patch $modes ($i * 64 + 8) }
    $r = [PCPflege.Displays]::Apply($paths, [int]$p.PathCount, $modes, [int]$p.ModeCount, $true)
    if ($r -eq 0) { $r = [PCPflege.Displays]::Apply($paths, [int]$p.PathCount, $modes, [int]$p.ModeCount, $false) }
    if ($r -ne 0) {
        $why = switch ($r) { 87 { 'ungültige Einstellung' } 1610 { 'Anordnung passt nicht zu den angeschlossenen Monitoren' } 31 { 'Grafiktreiber hat abgelehnt' } 5 { 'Zugriff verweigert (Sperrbildschirm oder Remote-Sitzung?)' } default { 'Fehler ' + $r } }
        throw ('Profil "{0}" konnte nicht angewendet werden: {1}. Sind alle Monitore des Profils angeschlossen und eingeschaltet?' -f $Name, $why)
    }
}
function Invoke-AfterMonitorSwitch($Cfg) {
    $mode = [string]$Cfg.Monitor.AfterSwitch
    if ($mode -like 'Nichts*') { return }
    Start-Sleep -Seconds 4   # Explorer ordnet die Symbole nach der Umschaltung selbst um - danach unsere Anordnung
    if ($mode -like 'Gemerkte*' -and (Test-Path -LiteralPath $DeskLayoutFile)) { $null = Restore-DeskLayout }
    else { $null = Invoke-DeskArrange -Gap:([bool]$Cfg.Desk.ArrangeGap) -AllowRestart -Layout ([string]$Cfg.Desk.ArrangeLayout) }
}
function New-PflegeCommandShortcut([string]$File, [string]$Arguments, [string]$Icon, [string]$Description) {
    $sh = New-Object -ComObject WScript.Shell
    $sc = $sh.CreateShortcut($File)
    Set-HiddenShortcut $sc (Join-Path $DataDir 'PCPflege.ps1') $Arguments
    $sc.WorkingDirectory = $DataDir
    $sc.IconLocation = $Icon
    $sc.Description = $Description
    $sc.Save()
    [void][Runtime.InteropServices.Marshal]::ReleaseComObject($sh)
}


# =====================================================================
#  FEHLERDATEN (Problemliste für die Oberfläche, Sammelpaket für den Hintergrundlauf)
# =====================================================================
function Get-ProblemEvents([int]$Days = 7) {
    $since = (Get-Date).AddDays(-$Days)
    $defs = @(
        @{ Cat = 'Bluescreen';              Log = 'System';      Ids = @(1001);                         Prov = 'WER-SystemErrorReporting|BugCheck' }
        @{ Cat = 'Unerwartet ausgeschaltet'; Log = 'System';     Ids = @(41);                           Prov = 'Kernel-Power' }
        @{ Cat = 'Unerwartet ausgeschaltet'; Log = 'System';     Ids = @(6008);                         Prov = 'EventLog' }
        @{ Cat = 'Programmabsturz';         Log = 'Application'; Ids = @(1000, 1026);                   Prov = 'Application Error|\.NET Runtime' }
        @{ Cat = 'Programm reagiert nicht'; Log = 'Application'; Ids = @(1002);                         Prov = 'Application Hang' }
        @{ Cat = 'Hardwarefehler';          Log = 'System';      Ids = @(1, 17, 18, 19, 20, 46, 47);    Prov = 'WHEA' }
        @{ Cat = 'Datenträger';             Log = 'System';      Ids = @(7, 11, 51, 129, 153, 157);     Prov = 'disk|stor|nvme|iaStor|atapi|ahci' }
        @{ Cat = 'Dateisystem';             Log = 'System';      Ids = @(55, 98, 137, 140);             Prov = 'Ntfs' }
        @{ Cat = 'Dienst / Treiber';        Log = 'System';      Ids = @(7000, 7001, 7009, 7011, 7023, 7024, 7026, 7031, 7034); Prov = 'Service Control Manager' }
        @{ Cat = 'Windows Update';          Log = 'System';      Ids = @(20);                           Prov = 'WindowsUpdateClient' }
        @{ Cat = 'Treiber';                 Log = 'System';      Ids = @(219, 411);                     Prov = 'Kernel-PnP' }
        @{ Cat = 'Grafiktreiber';           Log = 'System';      Ids = @(4101);                         Prov = 'Display' }
    )
    $rows = foreach ($d in $defs) {
        $ev = @(Get-WinEvent -FilterHashtable @{ LogName = $d.Log; Id = $d.Ids; StartTime = $since } -MaxEvents 300 -ErrorAction SilentlyContinue |
                Where-Object { $_.ProviderName -match $d.Prov })
        foreach ($e in $ev) {
            $msg = [string]$e.Message
            if (-not $msg) { $msg = '(keine Beschreibung verfügbar)' }
            $first = (($msg -split "`r?`n") | Where-Object { $_.Trim() } | Select-Object -First 1)
            if ($d.Cat -eq 'Programmabsturz' -and $e.Properties.Count -gt 0) { $first = 'Absturz: {0}  ({1})' -f $e.Properties[0].Value, $first }
            if ($d.Cat -eq 'Programm reagiert nicht' -and $e.Properties.Count -gt 0) { $first = 'Reagiert nicht: {0}' -f $e.Properties[0].Value }
            [pscustomobject]@{
                Time = $e.TimeCreated; TimeText = $e.TimeCreated.ToString('dd.MM.yyyy HH:mm'); Cat = $d.Cat; Source = ($e.ProviderName -replace '^Microsoft-Windows-', '')
                Id = $e.Id; Text = $(if ($first.Length -gt 220) { $first.Substring(0, 220) + ' ...' } else { $first }); Message = $msg
                Level = $(if ($d.Cat -in 'Bluescreen', 'Hardwarefehler', 'Datenträger', 'Unerwartet ausgeschaltet') { 'Error' } else { 'Warn' })
            }
        }
    }
    return @($rows | Sort-Object Time -Descending)
}

function Save-DiagOutput([string]$File, [string]$Exe, [string[]]$Arguments, [int]$TimeoutMin = 5) {
    $null = Invoke-External -Exe $Exe -Arguments $Arguments -TimeoutMin $TimeoutMin -Capture -Quiet -OemEncoding
    try { $Script:Captured | Set-Content -LiteralPath $File -Encoding UTF8 } catch { }
}
function Save-DiagText([string]$File, [scriptblock]$Block) {
    try { & $Block 2>&1 | Out-String -Width 300 | Set-Content -LiteralPath $File -Encoding UTF8 }
    catch { ('Fehler: {0}' -f $_.Exception.Message) | Set-Content -LiteralPath $File -Encoding UTF8 }
}
function Invoke-DiagCollect {
    $D = $Script:Cfg.Diag
    $days = [math]::Max(1, [int]$D.Days)
    $since = (Get-Date).AddDays(-$days)
    $ms = [int64]$days * 86400000
    $stamp = Get-Date -Format 'yyyy-MM-dd_HHmm'
    $name = 'Fehlerdaten_{0}_{1}' -f $env:COMPUTERNAME, $stamp
    $target = if ([string]$D.Target) { [string]$D.Target } else { [Environment]::GetFolderPath('Desktop') }
    $work = Join-Path $env:TEMP $name
    New-Item $work -ItemType Directory -Force | Out-Null
    $dir = { param($n) $p = Join-Path $work $n; New-Item $p -ItemType Directory -Force | Out-Null; $p }
    $step = { param($t) if (Test-PCancel) { throw 'Abgebrochen durch Benutzer' }; $Script:Detail = $t; Write-PLog ('  ' + $t); Set-PStatus $Script:StatusText }
    Write-PLog ('Zeitraum: letzte {0} Tage, Ziel: {1}' -f $days, $target)

    # ---- Übersicht und Problemliste (immer)
    & $step 'Übersicht und Problemliste'
    $os = Get-CimInstance Win32_OperatingSystem; $cs = Get-CimInstance Win32_ComputerSystem; $bios = Get-CimInstance Win32_BIOS
    $reg = Get-ItemProperty 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion'
    $probs = @(Get-ProblemEvents $days)
    $sum = [System.Collections.Generic.List[string]]::new()
    $sum.Add(('Fehlerdaten {0} - erstellt {1:dd.MM.yyyy HH:mm} mit PC-Tools {2}' -f $env:COMPUTERNAME, (Get-Date), $AppVersion))
    $sum.Add(''); $sum.Add(('Windows:   {0} {1} (Build {2}.{3})' -f $os.Caption, $reg.DisplayVersion, $reg.CurrentBuild, $reg.UBR))
    $sum.Add(('Gerät:     {0} {1}, Seriennummer {2}, BIOS {3}' -f $cs.Manufacturer, $cs.Model, $bios.SerialNumber, $bios.SMBIOSBIOSVersion))
    $sum.Add(('Speicher:  {0:N1} GB, frei {1:N1} GB' -f ($cs.TotalPhysicalMemory / 1GB), ($os.FreePhysicalMemory * 1KB / 1GB)))
    $sum.Add(('Gestartet: {0:dd.MM.yyyy HH:mm}' -f $os.LastBootUpTime))
    foreach ($v in @(Get-Volume -ErrorAction SilentlyContinue | Where-Object DriveLetter)) { $sum.Add(('Laufwerk {0}: {1:N1} GB frei von {2:N1} GB ({3})' -f $v.DriveLetter, ($v.SizeRemaining / 1GB), ($v.Size / 1GB), $v.HealthStatus)) }
    $sum.Add(''); $sum.Add(('Probleme der letzten {0} Tage:' -f $days))
    foreach ($g in @($probs | Group-Object Cat | Sort-Object Count -Descending)) { $sum.Add(('  {0,-26} {1,4}x' -f $g.Name, $g.Count)) }
    if (-not $probs.Count) { $sum.Add('  keine') }
    $sum.Add('')
    foreach ($p in $probs) { $sum.Add(('{0}  {1,-24} {2,-28} {3,5}  {4}' -f $p.TimeText, $p.Cat, $p.Source, $p.Id, $p.Text)) }
    $sum | Set-Content -LiteralPath (Join-Path $work '00_Zusammenfassung.txt') -Encoding UTF8
    $probs | Select-Object TimeText, Cat, Source, Id, Message | Export-Csv -LiteralPath (Join-Path $work '01_Probleme.csv') -NoTypeInformation -Delimiter ';' -Encoding UTF8

    if ($D.SysInfo) {
        & $step 'Systeminformationen'
        $p = & $dir 'System'
        Save-DiagOutput (Join-Path $p 'systeminfo.txt') 'systeminfo.exe' @('/FO', 'LIST') 3
        Save-DiagText (Join-Path $p 'Hardware.txt') {
            Get-CimInstance Win32_ComputerSystem | Format-List Manufacturer, Model, SystemType, TotalPhysicalMemory, Domain, UserName
            Get-CimInstance Win32_BIOS | Format-List Manufacturer, SMBIOSBIOSVersion, ReleaseDate, SerialNumber
            Get-CimInstance Win32_BaseBoard | Format-List Manufacturer, Product, Version
            Get-CimInstance Win32_Processor | Format-List Name, NumberOfCores, NumberOfLogicalProcessors, MaxClockSpeed
            Get-CimInstance Win32_PhysicalMemory | Format-Table BankLabel, DeviceLocator, Capacity, Speed, Manufacturer, PartNumber -AutoSize
            Get-CimInstance Win32_VideoController | Format-List Name, DriverVersion, DriverDate, VideoModeDescription
        }
        if ($D.MsInfo) {
            & $step 'Systeminformationen (msinfo32, dauert 1-2 Minuten)'
            $null = Invoke-External -Exe (Join-Path $env:SystemRoot 'System32\msinfo32.exe') -Arguments @('/report', ('"{0}"' -f (Join-Path $p 'msinfo32.txt'))) -TimeoutMin 6 -Quiet
        }
        if ($D.DxDiag) {
            & $step 'DirectX-Diagnose (dxdiag)'
            $null = Invoke-External -Exe (Join-Path $env:SystemRoot 'System32\dxdiag.exe') -Arguments @('/t', ('"{0}"' -f (Join-Path $p 'dxdiag.txt'))) -TimeoutMin 3 -Quiet
            for ($i = 0; $i -lt 30 -and -not (Test-Path (Join-Path $p 'dxdiag.txt')); $i++) { Start-Sleep -Seconds 1 }
        }
    }
    if ($D.Events) {
        & $step 'Ereignisprotokolle'
        $p = & $dir 'Ereignisse'
        $q = ('*[System[TimeCreated[timediff(@SystemTime) <= {0}]]]' -f $ms)
        foreach ($l in @(@('System', 'System'), @('Application', 'Anwendung'), @('Setup', 'Setup'), @('Microsoft-Windows-WindowsUpdateClient/Operational', 'WindowsUpdate'),
                        @('Microsoft-Windows-Diagnostics-Performance/Operational', 'Startleistung'), @('Microsoft-Windows-Kernel-PnP/Configuration', 'Geraeteinstallation'))) {
            $null = Invoke-External -Exe 'wevtutil.exe' -Arguments @('epl', ('"{0}"' -f $l[0]), ('"{0}"' -f (Join-Path $p ($l[1] + '.evtx'))), ('/q:"{0}"' -f $q), '/ow:true') -TimeoutMin 5 -Quiet
        }
        foreach ($l in @(@('System', 'System'), @('Application', 'Anwendung'))) {
            Get-WinEvent -FilterHashtable @{ LogName = $l[0]; Level = 1, 2, 3; StartTime = $since } -MaxEvents 5000 -ErrorAction SilentlyContinue |
                Select-Object @{ n = 'Zeit'; e = { $_.TimeCreated.ToString('dd.MM.yyyy HH:mm:ss') } }, LevelDisplayName, ProviderName, Id, @{ n = 'Meldung'; e = { ([string]$_.Message -replace '\s+', ' ') } } |
                Export-Csv -LiteralPath (Join-Path $p ('{0}_Fehler_Warnungen.csv' -f $l[1])) -NoTypeInformation -Delimiter ';' -Encoding UTF8
        }
    }
    if ($D.Reliability) {
        & $step 'Zuverlässigkeitsverlauf'
        $p = & $dir 'System'
        try {
            Get-CimInstance Win32_ReliabilityRecords -ErrorAction Stop | Where-Object { $_.TimeGenerated -ge $since } |
                Select-Object @{ n = 'Zeit'; e = { $_.TimeGenerated.ToString('dd.MM.yyyy HH:mm') } }, SourceName, EventIdentifier, ProductName, @{ n = 'Meldung'; e = { ([string]$_.Message -replace '\s+', ' ') } } |
                Export-Csv -LiteralPath (Join-Path $p 'Zuverlaessigkeit.csv') -NoTypeInformation -Delimiter ';' -Encoding UTF8
        } catch { Write-PLog ('  Zuverlässigkeitsverlauf nicht verfügbar: {0}' -f $_.Exception.Message) }
    }
    if ($D.Dumps) {
        & $step 'Absturzabbilder und Fehlerberichte'
        $p = & $dir 'Abstuerze'
        foreach ($f in @(Get-ChildItem (Join-Path $env:SystemRoot 'Minidump') -Filter '*.dmp' -ErrorAction SilentlyContinue | Where-Object { $_.LastWriteTime -ge $since })) { Copy-Item -LiteralPath $f.FullName -Destination $p -ErrorAction SilentlyContinue }
        foreach ($f in @(Get-ChildItem (Join-Path $env:SystemRoot 'LiveKernelReports') -Filter '*.dmp' -Recurse -ErrorAction SilentlyContinue | Where-Object { $_.LastWriteTime -ge $since -and $_.Length -lt 100MB })) { Copy-Item -LiteralPath $f.FullName -Destination $p -ErrorAction SilentlyContinue }
        $mem = Join-Path $env:SystemRoot 'MEMORY.DMP'
        if ($D.FullDump -and (Test-Path $mem) -and (Get-Item $mem).LastWriteTime -ge $since) { & $step 'Vollständiges Speicherabbild (MEMORY.DMP, groß)'; Copy-Item -LiteralPath $mem -Destination $p -ErrorAction SilentlyContinue }
        $wer = Join-Path $p 'Fehlerberichte'; New-Item $wer -ItemType Directory -Force | Out-Null
        foreach ($root in @((Join-Path $env:ProgramData 'Microsoft\Windows\WER\ReportArchive'), (Join-Path $env:ProgramData 'Microsoft\Windows\WER\ReportQueue'))) {
            foreach ($f in @(Get-ChildItem $root -Filter 'Report.wer' -Recurse -ErrorAction SilentlyContinue | Where-Object { $_.LastWriteTime -ge $since } | Select-Object -First 200)) {
                Copy-Item -LiteralPath $f.FullName -Destination (Join-Path $wer ($f.Directory.Name + '.txt')) -ErrorAction SilentlyContinue
            }
        }
    }
    if ($D.UpdateLogs) {
        & $step 'Windows-Update- und Setup-Protokolle'
        $p = & $dir 'Updates'
        try { Get-WindowsUpdateLog -LogPath (Join-Path $p 'WindowsUpdate.log') -ErrorAction Stop *> $null } catch { Write-PLog '  WindowsUpdate.log konnte nicht erzeugt werden' }
        Save-DiagText (Join-Path $p 'Update-Verlauf.txt') {
            $s = New-Object -ComObject Microsoft.Update.Session; $srch = $s.CreateUpdateSearcher(); $n = $srch.GetTotalHistoryCount()
            $srch.QueryHistory(0, [math]::Min($n, 200)) | ForEach-Object {
                $r = switch ($_.ResultCode) { 1 { 'läuft' } 2 { 'OK' } 3 { 'OK mit Fehlern' } 4 { 'FEHLER' } 5 { 'abgebrochen' } default { $_.ResultCode } }
                '{0:dd.MM.yyyy HH:mm}  {1,-14} 0x{2:X8}  {3}' -f $_.Date, $r, $_.HResult, $_.Title
            }
        }
        Save-DiagText (Join-Path $p 'Hotfixes.txt') { Get-HotFix | Sort-Object InstalledOn -Descending | Format-Table HotFixID, Description, InstalledOn -AutoSize }
        foreach ($f in @((Join-Path $env:SystemRoot 'Logs\CBS\CBS.log'), (Join-Path $env:SystemRoot 'Logs\DISM\dism.log'), (Join-Path $env:SystemRoot 'Panther\setupact.log'), (Join-Path $env:SystemRoot 'Panther\setuperr.log'),
                         'C:\$WINDOWS.~BT\Sources\Panther\setupact.log', 'C:\$WINDOWS.~BT\Sources\Panther\setuperr.log', 'C:\$WINDOWS.~BT\Sources\Rollback\setupact.log',
                         (Join-Path $env:ProgramData 'ActiveSetupPreLogon\log.txt'))) {
            if (Test-Path -LiteralPath $f) {
                $n = ($f -replace '^[A-Za-z]:\\', '' -replace '[\\\$~]', '_').Trim('_')
                Copy-Item -LiteralPath $f -Destination (Join-Path $p $n) -ErrorAction SilentlyContinue
            }
        }
    }
    if ($D.Drivers) {
        & $step 'Treiber und Geräte'
        $p = & $dir 'Treiber'
        Save-DiagText (Join-Path $p 'Geraete_mit_Problemen.txt') { Get-PnpDevice -ErrorAction SilentlyContinue | Where-Object { $_.Status -notin 'OK', 'Unknown' } | Format-Table Status, Class, FriendlyName, InstanceId -AutoSize }
        Save-DiagOutput (Join-Path $p 'Treiberpakete.txt') 'pnputil.exe' @('/enum-drivers') 3
        Save-DiagText (Join-Path $p 'Treiber.csv') {
            Get-CimInstance Win32_PnPSignedDriver | Where-Object DeviceName | Sort-Object DeviceClass, DeviceName |
                Select-Object DeviceClass, DeviceName, Manufacturer, DriverVersion, @{ n = 'Datum'; e = { if ($_.DriverDate) { $_.DriverDate.ToString('yyyy-MM-dd') } } }, InfName | ConvertTo-Csv -NoTypeInformation -Delimiter ';'
        }
    }
    if ($D.Network) {
        & $step 'Netzwerk'
        $p = & $dir 'Netzwerk'
        Save-DiagOutput (Join-Path $p 'ipconfig.txt') 'ipconfig.exe' @('/all') 1
        Save-DiagOutput (Join-Path $p 'route.txt') 'route.exe' @('print') 1
        Save-DiagOutput (Join-Path $p 'netstat.txt') 'netstat.exe' @('-ano') 2
        Save-DiagOutput (Join-Path $p 'wlan.txt') 'netsh.exe' @('wlan', 'show', 'interfaces') 1
        Save-DiagOutput (Join-Path $p 'proxy.txt') 'netsh.exe' @('winhttp', 'show', 'proxy') 1
        Save-DiagText (Join-Path $p 'Adapter.txt') {
            Get-NetAdapter | Format-Table Name, InterfaceDescription, Status, LinkSpeed, MacAddress -AutoSize
            Get-NetIPConfiguration -Detailed -ErrorAction SilentlyContinue
            Get-DnsClientServerAddress -AddressFamily IPv4 | Format-Table InterfaceAlias, ServerAddresses -AutoSize
        }
        Save-DiagText (Join-Path $p 'Verbindungstest.txt') {
            foreach ($h in '8.8.8.8', 'www.microsoft.com') { Test-NetConnection $h -WarningAction SilentlyContinue | Format-List ComputerName, RemoteAddress, PingSucceeded, PingReplyDetails }
            Resolve-DnsName www.microsoft.com -ErrorAction SilentlyContinue | Format-Table -AutoSize
        }
    }
    if ($D.Software) {
        & $step 'Installierte Programme und Autostart'
        $p = & $dir 'Programme'
        Get-InstalledPrograms | Select-Object Name, Version, Publisher, InstallDate, SizeMB, Scope | Export-Csv -LiteralPath (Join-Path $p 'Programme.csv') -NoTypeInformation -Delimiter ';' -Encoding UTF8
        Get-CimInstance Win32_StartupCommand -ErrorAction SilentlyContinue | Select-Object Name, Command, Location, User | Export-Csv -LiteralPath (Join-Path $p 'Autostart.csv') -NoTypeInformation -Delimiter ';' -Encoding UTF8
        Get-CimInstance Win32_Service | Select-Object Name, DisplayName, State, StartMode, StartName, PathName | Export-Csv -LiteralPath (Join-Path $p 'Dienste.csv') -NoTypeInformation -Delimiter ';' -Encoding UTF8
        Get-ScheduledTask -ErrorAction SilentlyContinue | Where-Object { $_.TaskPath -notlike '\Microsoft\*' } | Select-Object TaskPath, TaskName, State, Author |
            Export-Csv -LiteralPath (Join-Path $p 'Aufgaben.csv') -NoTypeInformation -Delimiter ';' -Encoding UTF8
    }
    if ($D.Disks) {
        & $step 'Datenträger'
        $p = & $dir 'Datentraeger'
        Save-DiagText (Join-Path $p 'Datentraeger.txt') {
            Get-PhysicalDisk | Format-Table DeviceId, FriendlyName, MediaType, BusType, HealthStatus, OperationalStatus, @{ n = 'GB'; e = { [math]::Round($_.Size / 1GB) } } -AutoSize
            Get-PhysicalDisk | ForEach-Object { $_ | Get-StorageReliabilityCounter -ErrorAction SilentlyContinue | Format-List DeviceId, Temperature, TemperatureMax, Wear, PowerOnHours, ReadErrorsTotal, ReadErrorsUncorrected, WriteErrorsTotal, WriteErrorsUncorrected }
            Get-Volume | Format-Table DriveLetter, FileSystemLabel, FileSystem, HealthStatus, @{ n = 'Frei GB'; e = { [math]::Round($_.SizeRemaining / 1GB, 1) } }, @{ n = 'GB'; e = { [math]::Round($_.Size / 1GB, 1) } } -AutoSize
            Get-Partition | Format-Table DiskNumber, PartitionNumber, DriveLetter, Type, @{ n = 'GB'; e = { [math]::Round($_.Size / 1GB, 1) } } -AutoSize
        }
        Save-DiagOutput (Join-Path $p 'Dirty-Bit.txt') 'fsutil.exe' @('dirty', 'query', $env:SystemDrive) 1
    }
    if ($D.Power) {
        & $step 'Energie (Standby, Aufwachgründe, Akku)'
        $p = & $dir 'Energie'
        Save-DiagOutput (Join-Path $p 'Standby-Modi.txt') 'powercfg.exe' @('/a') 1
        Save-DiagOutput (Join-Path $p 'Letztes_Aufwachen.txt') 'powercfg.exe' @('/lastwake') 1
        Save-DiagOutput (Join-Path $p 'Wecker.txt') 'powercfg.exe' @('/waketimers') 1
        Save-DiagOutput (Join-Path $p 'Anforderungen.txt') 'powercfg.exe' @('/requests') 1
        if (Get-CimInstance Win32_Battery -ErrorAction SilentlyContinue) { $null = Invoke-External -Exe 'powercfg.exe' -Arguments @('/batteryreport', '/output', ('"{0}"' -f (Join-Path $p 'Akkubericht.html'))) -TimeoutMin 2 -Quiet }
    }
    if ($D.PflegeLogs) {
        & $step 'Protokolle von PC-Tools'
        $p = & $dir 'PC-Tools'
        Get-ChildItem (Join-Path $DataDir 'Logs') -File -ErrorAction SilentlyContinue | Sort-Object LastWriteTime -Descending | Select-Object -First 15 | Copy-Item -Destination $p -ErrorAction SilentlyContinue
        $cf = Join-Path $DataDir 'config.json'; if (Test-Path $cf) { Copy-Item $cf $p -ErrorAction SilentlyContinue }
    }

    & $step 'ZIP-Datei erstellen'
    New-Item $target -ItemType Directory -Force | Out-Null
    $zip = Join-Path $target ($name + '.zip')
    Add-Type -AssemblyName System.IO.Compression.FileSystem
    if (Test-Path -LiteralPath $zip) { Remove-Item -LiteralPath $zip -Force }
    [IO.Compression.ZipFile]::CreateFromDirectory($work, $zip, [IO.Compression.CompressionLevel]::Optimal, $false)
    Remove-Item -LiteralPath $work -Recurse -Force -ErrorAction SilentlyContinue
    Set-Content -LiteralPath (Join-Path $DataDir 'diag_last.txt') -Value $zip -Encoding UTF8
    Write-PLog ('Fehlerdaten gespeichert: {0} ({1})' -f $zip, (Format-Bytes (Get-Item -LiteralPath $zip).Length)) 'OK'
}

# Installierte Programme aus der Registry (64/32 Bit, Benutzer)
function Get-InstalledPrograms {
    $keys = @(@('HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall', 'Alle'), @('HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall', 'Alle (32 Bit)'),
              @('HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall', 'Benutzer'))
    $seen = @{}
    $list = foreach ($k in $keys) {
        foreach ($i in @(Get-ChildItem $k[0] -ErrorAction SilentlyContinue)) {
            $p = Get-ItemProperty $i.PSPath -ErrorAction SilentlyContinue
            if (-not $p.DisplayName -or $p.SystemComponent -eq 1 -or $p.ParentKeyName -or $p.ReleaseType -match 'Update|Hotfix') { continue }
            $key = ('{0}|{1}' -f $p.DisplayName, $p.DisplayVersion).ToLower()
            if ($seen.ContainsKey($key)) { continue }; $seen[$key] = $true
            $d = ''; if ([string]$p.InstallDate -match '^(\d{4})(\d{2})(\d{2})$') { $d = '{2}.{1}.{0}' -f $Matches[1], $Matches[2], $Matches[3] }
            [pscustomobject]@{
                Name = [string]$p.DisplayName; Version = [string]$p.DisplayVersion; Publisher = [string]$p.Publisher; InstallDate = $d
                SizeMB = $(if ($p.EstimatedSize) { [math]::Round([double]$p.EstimatedSize / 1024, 1) } else { $null })
                SizeText = $(if ($p.EstimatedSize) { '{0:N0} MB' -f ([double]$p.EstimatedSize / 1024) } else { '' })
                Scope = $k[1]; Uninstall = [string]$p.UninstallString; QuietUninstall = [string]$p.QuietUninstallString
                Location = [string]$p.InstallLocation; Key = $i.PSPath
            }
        }
    }
    return @($list | Sort-Object Name)
}


# =====================================================================
#  TREIBER, WINDOWS-ISO, OFFICE, USB-STICK (Hintergrundlauf; Optionen in $Script:JobOpts)
# =====================================================================
$Script:JobOpts = $null
function Save-Download([string]$Url, [string]$File, [string]$Label) {
    New-Item (Split-Path $File) -ItemType Directory -Force | Out-Null
    try { [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12 } catch { }
    $job = $null
    try { $job = Start-BitsTransfer -Source $Url -Destination $File -Asynchronous -DisplayName 'PC-Tools' -Priority Foreground -ErrorAction Stop } catch { $job = $null }
    if ($job) {
        $last = Get-Date
        while ($job.JobState -in 'Queued', 'Connecting', 'Transferring', 'TransientError') {
            if (Test-PCancel) { Remove-BitsTransfer $job -ErrorAction SilentlyContinue; throw 'Abgebrochen durch Benutzer' }
            Start-Sleep -Seconds 1
            if ($job.BytesTotal -gt 0 -and $job.BytesTotal -ne [uint64]::MaxValue) {
                $Script:Detail = '{0}: {1:N0} von {2:N0} MB ({3:N0} %)' -f $Label, ($job.BytesTransferred / 1MB), ($job.BytesTotal / 1MB), (100 * $job.BytesTransferred / $job.BytesTotal)
            } else { $Script:Detail = '{0}: {1:N0} MB geladen' -f $Label, ($job.BytesTransferred / 1MB) }
            if (((Get-Date) - $last).TotalSeconds -ge 30) { Write-PLog ('   ' + $Script:Detail); $last = Get-Date }
            Set-PStatus $Script:StatusText
        }
        if ($job.JobState -eq 'Transferred') { Complete-BitsTransfer $job; return }
        $err = $job.ErrorDescription; Remove-BitsTransfer $job -ErrorAction SilentlyContinue
        Write-PLog ('   BITS-Download fehlgeschlagen ({0}), lade direkt ...' -f $err) 'WARN'
    }
    $Script:Detail = $Label + ' (direkter Download, ohne Fortschrittsanzeige)'; Set-PStatus $Script:StatusText
    $ua = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/140.0.0.0 Safari/537.36 Edg/140.0.0.0'
    try { Invoke-WebRequest -Uri $Url -OutFile $File -UseBasicParsing -UserAgent $ua -ErrorAction Stop; return } catch { $e1 = $_.Exception.Message }
    $curl = Join-Path $env:SystemRoot 'System32\curl.exe'
    if (-not (Test-Path -LiteralPath $curl)) { throw $e1 }
    Write-PLog ('   Direkter Download fehlgeschlagen ({0}), versuche curl ...' -f $e1) 'WARN'
    $code = (& $curl -s -L --max-time 1800 -A $ua -o $File -w '%{http_code}' $Url 2>$null) -join ''
    if ($code -ne '200') { Remove-Item -LiteralPath $File -Force -ErrorAction SilentlyContinue; throw ('Download fehlgeschlagen (HTTP {0})' -f $code) }
}

# ---- Grafiktreiber
function Get-GpuList {
    @(Get-CimInstance Win32_VideoController | Where-Object { $_.Name -and $_.Name -notmatch 'Remote|Mirage|Parsec|Virtual|Basic Display|Standard-VGA|Microsoft Basic' } | ForEach-Object {
        $vendor = if ($_.Name -match 'NVIDIA|GeForce|Quadro|RTX') { 'NVIDIA' } elseif ($_.Name -match 'AMD|Radeon|FirePro') { 'AMD' } elseif ($_.Name -match 'Intel') { 'Intel' } else { 'Sonstige' }
        $nv = ''
        if ($vendor -eq 'NVIDIA' -and [string]$_.DriverVersion -match '\d') { $dig = ([string]$_.DriverVersion -replace '\.', ''); $t = $dig.Substring($dig.Length - 5); $nv = '{0}.{1}' -f [int]$t.Substring(0, 3), $t.Substring(3) }
        [pscustomobject]@{ Name = [string]$_.Name; Vendor = $vendor; DriverVersion = [string]$_.DriverVersion; NvVersion = $nv
                           DriverDate = $(if ($_.DriverDate) { $_.DriverDate.ToString('dd.MM.yyyy') } else { '' }) }
    })
}
function Get-NvidiaLatest([string]$GpuName) {
    try { [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12 } catch { }
    $name = ($GpuName -replace '^NVIDIA\s+', '' -replace '\s+', ' ').Trim()
    [xml]$x = (Invoke-WebRequest -Uri 'https://www.nvidia.com/Download/API/lookupValueSearch.aspx?TypeID=3' -UseBasicParsing -TimeoutSec 30).Content
    $all = @($x.LookupValueSearch.LookupValues.LookupValue)
    $hit = $all | Where-Object { $_.Name -eq $name } | Select-Object -First 1
    if (-not $hit) { $hit = $all | Where-Object { $_.Name -like "*$name*" -and $_.Name -notmatch 'Notebook|Laptop' } | Select-Object -First 1 }
    if (-not $hit) { $hit = $all | Where-Object { $name -like ('*' + $_.Name + '*') } | Sort-Object { $_.Name.Length } -Descending | Select-Object -First 1 }
    if (-not $hit) { throw ('Grafikkarte "{0}" ist in der NVIDIA-Liste nicht zu finden.' -f $name) }
    foreach ($os in 135, 57) {
        $u = 'https://gfwsl.geforce.com/services_toolkit/services/com/nvidia/services/AjaxDriverService.php?func=DriverManualLookup&psid={0}&pfid={1}&osID={2}&languageCode=1031&beta=0&isWHQL=1&dltype=-1&dch=1&upCRD=0&qnf=0&sort1=0&numberOfResults=1' -f $hit.ParentID, $hit.Value, $os
        try {
            $j = Invoke-RestMethod -Uri $u -TimeoutSec 30
            if ($j.IDS -and $j.IDS[0].downloadInfo.DownloadURL) {
                $d = $j.IDS[0].downloadInfo
                return [pscustomobject]@{ Version = [string]$d.Version; Url = [uri]::UnescapeDataString([string]$d.DownloadURL); Name = [uri]::UnescapeDataString([string]$d.Name); Date = [string]$d.ReleaseDateTime; Product = $hit.Name }
            }
        } catch { }
    }
    throw 'NVIDIA hat keinen passenden Treiber geliefert.'
}
function Invoke-GpuDriverUpdate {
    $gpus = @(Get-GpuList)
    if (-not $gpus.Count) { Write-PLog 'Keine Grafikkarte erkannt.'; return }
    foreach ($g in $gpus) {
        Write-PLog ('Grafikkarte: {0} (Treiber {1} vom {2})' -f $g.Name, $(if ($g.NvVersion) { $g.NvVersion } else { $g.DriverVersion }), $g.DriverDate)
        switch ($g.Vendor) {
            'NVIDIA' {
                try { $l = Get-NvidiaLatest $g.Name } catch { Write-PLog ('   NVIDIA-Abfrage fehlgeschlagen: {0}' -f $_.Exception.Message) 'WARN'; continue }
                Write-PLog ('   Neuester Treiber: {0} vom {1} ({2})' -f $l.Version, $l.Date, $l.Name)
                $have = $null; $want = $null; try { $have = [version]$g.NvVersion; $want = [version]$l.Version } catch { }
                if ($have -and $want -and $have -ge $want) { Write-PLog '   Grafiktreiber ist aktuell.' 'OK'; continue }
                if ($Script:CheckOnly) { Write-PLog ('   Update verfügbar: {0} -> {1}' -f $g.NvVersion, $l.Version) 'WARN'; continue }
                $file = Join-Path (Join-Path $DataDir 'Downloads') ([IO.Path]::GetFileName(([uri]$l.Url).AbsolutePath))
                Save-Download $l.Url $file ('NVIDIA-Treiber ' + $l.Version)
                $sig = Get-AuthenticodeSignature -FilePath $file
                if ($sig.Status -ne 'Valid' -or $sig.SignerCertificate.Subject -notmatch 'NVIDIA') { Write-PLog '   Signatur des Treibers ungültig - nicht installiert.' 'FEHLER'; continue }
                try { Invoke-DsBeforeDriverUpdate 'NVIDIA-Grafiktreiber' } catch { }
                $Script:Detail = 'NVIDIA-Treiber wird installiert - der Bildschirm kann kurz schwarz werden'; Set-PStatus $Script:StatusText
                $rc = Invoke-External -Exe $file -Arguments @('-s', '-noreboot', '-noeula') -TimeoutMin 40 -Quiet
                if ($rc -in 0, 1) { Write-PLog ('   NVIDIA-Treiber {0} installiert.' -f $l.Version) 'OK'; $Script:UpdatesInstalled++; if ($rc -eq 1) { $Script:RebootNeeded = $true } }
                else { Write-PLog ('   NVIDIA-Installation meldet Code {0}.' -f $rc) 'WARN' }
                Remove-Item -LiteralPath $file -Force -ErrorAction SilentlyContinue
            }
            'Intel' {
                $direct = $true; try { if ($null -ne $Script:Cfg.Update.IntelDirect) { $direct = [bool]$Script:Cfg.Update.IntelDirect } } catch { }
                if ($direct) { try { Invoke-IntelGfxUpdate $g; continue } catch { Write-PLog ('   Intel-Download-Center nicht nutzbar: {0} - weiter mit dem Intel-Assistenten' -f $_.Exception.Message) 'WARN' } }
                $dsa = Get-ChildItem "${env:ProgramFiles(x86)}\Intel\Driver and Support Assistant\DSATray.exe", "$env:ProgramFiles\Intel\Driver and Support Assistant\DSATray.exe" -ErrorAction SilentlyContinue | Select-Object -First 1
                if (-not $dsa -and -not $Script:CheckOnly) {
                    $wg = Get-WingetPath
                    if ($wg) { Write-PLog '   Installiere Intel Driver & Support Assistant (aktualisiert Intel-Grafik, WLAN, Bluetooth)'; $null = Invoke-External -Exe $wg -Arguments @('install', '--id', 'Intel.IntelDriverAndSupportAssistant', '-e', '--silent', '--accept-package-agreements', '--accept-source-agreements', '--disable-interactivity') -TimeoutMin 20 }
                } else { Write-PLog '   Intel-Treiber: Intel Driver & Support Assistant ist installiert und meldet Updates im Infobereich.' }
            }
            'AMD' { Write-PLog '   AMD-Grafik: Treiber über Windows Update bzw. AMD Software Adrenalin (amd.com/support). Automatischer Download ist bei AMD nicht möglich.' 'WARN' }
        }
    }
}
# ---- Treiber über Windows Update (auch optionale); $Ids = nur diese UpdateIDs
function Invoke-WUDrivers([string[]]$Ids = @()) {
    $session = New-Object -ComObject Microsoft.Update.Session
    $session.ClientApplicationID = 'PC-Tools'
    $searcher = $session.CreateUpdateSearcher()
    $Script:Detail = 'Suche nach Treibern bei Microsoft'; Set-PStatus 'Windows Update: Suche nach Treibern'
    $res = $searcher.Search("IsInstalled=0 and IsHidden=0 and Type='Driver'")
    $coll = New-Object -ComObject Microsoft.Update.UpdateColl
    foreach ($u in $res.Updates) {
        if ($Ids.Count -and $Ids -notcontains $u.Identity.UpdateID) { continue }
        Write-PLog ('   {0}{1}' -f $u.Title, $(if ($u.BrowseOnly) { '  (optional)' } else { '' }))
        if (-not $u.EulaAccepted) { $u.AcceptEula() }
        [void]$coll.Add($u)
    }
    Write-PLog ('Windows Update: {0} Treiber verfügbar' -f $coll.Count)
    if ($Script:CheckOnly -or $coll.Count -eq 0) { return }
    try { Invoke-DsBeforeDriverUpdate 'Treiber aus Windows Update' } catch { }
    Set-PStatus ('Windows Update: Download von {0} Treiber(n)' -f $coll.Count)
    $dl = $session.CreateUpdateDownloader(); $dl.Updates = $coll; $null = $dl.Download()
    $inst = New-Object -ComObject Microsoft.Update.UpdateColl
    foreach ($u in $coll) { if ($u.IsDownloaded) { [void]$inst.Add($u) } }
    if (-not $inst.Count) { Write-PLog 'Treiber-Download fehlgeschlagen' 'WARN'; return }
    Set-PStatus ('Windows Update: Installation von {0} Treiber(n)' -f $inst.Count)
    $installer = $session.CreateUpdateInstaller(); $installer.Updates = $inst
    $r = $installer.Install()
    for ($i = 0; $i -lt $inst.Count; $i++) {
        $x = $r.GetUpdateResult($i); $ok = $x.ResultCode -in 2, 3
        if ($ok) { $Script:UpdatesInstalled++ }
        Write-PLog ('   {0}: {1}{2}' -f $(if ($ok) { 'installiert' } else { 'FEHLER' }), $inst.Item($i).Title, $(if (-not $ok) { ' (0x{0:X8})' -f $x.HResult } else { '' })) $(if ($ok) { 'OK' } else { 'WARN' })
    }
    if ($r.RebootRequired) { $Script:RebootNeeded = $true }
}

# ---- Windows 11 als ISO (offiziell über Fido, Insider über UUP dump)
function Get-InsiderBuild([string]$Ring) {
    try { [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12 } catch { }
    $r = Invoke-RestMethod -Uri ('https://api.uupdump.net/fetchupd.php?arch=amd64&ring={0}&build=latest' -f $Ring) -TimeoutSec 60
    if (-not $r.response.updateId) { throw ('Kein Build für den Kanal {0} gefunden.' -f $Ring) }
    return [pscustomobject]@{ Id = [string]$r.response.updateId; Build = [string]$r.response.foundBuild; Title = [string]$r.response.updateTitle }
}
function Start-IsoUpgrade([string]$Iso) {
    $img = Mount-DiskImage -ImagePath $Iso -PassThru
    $letter = ($img | Get-Volume).DriveLetter
    $setup = '{0}:\setup.exe' -f $letter
    if (-not (Test-Path $setup)) { throw 'setup.exe im ISO nicht gefunden.' }
    Start-Process -FilePath $setup -ArgumentList '/auto upgrade /eula accept /dynamicupdate disable /compat ignorewarning /showoobe none'
    return $setup
}
function Invoke-WinIsoJob {
    $o = $Script:JobOpts
    $target = if ([string]$o.Target) { [string]$o.Target } else { Join-Path ([Environment]::GetFolderPath('Desktop')) 'Windows-ISO' }
    New-Item $target -ItemType Directory -Force | Out-Null
    $iso = $null
    if ($o.Ring -eq 'Retail') {
        Write-PLog 'Offizielle Windows-11-ISO: Download-Link bei Microsoft abfragen (Fido)'
        $fido = Join-Path (Join-Path $DataDir 'Tools') 'Fido.ps1'
        try { Save-Download 'https://raw.githubusercontent.com/pbatard/Fido/master/Fido.ps1' $fido 'Fido' } catch { Write-PLog ('Fido konnte nicht geladen werden: {0}' -f $_.Exception.Message) 'WARN' }
        $url = $null
        if (Test-Path $fido) {
            $null = Invoke-External -Exe 'powershell.exe' -Arguments @('-NoProfile', '-ExecutionPolicy', 'Bypass', '-File', ('"{0}"' -f $fido), '-Win', '"Windows 11"', '-Rel', 'Latest', '-Ed', ('"{0}"' -f $o.FidoEdition), '-Lang', ('"{0}"' -f $o.FidoLang), '-Arch', 'x64', '-GetUrl') -TimeoutMin 5 -Capture
            $url = $Script:Captured | Where-Object { $_ -match '^https://' } | Select-Object -Last 1
            if (-not $url) { Write-PLog ('Microsoft hat den direkten Link verweigert: {0}' -f (($Script:Captured | Select-Object -Last 3) -join ' ')) 'WARN' }
        }
        if ($url) {
            $name = [IO.Path]::GetFileName(([uri]$url).AbsolutePath); if (-not $name -or $name -notlike '*.iso') { $name = 'Windows11.iso' }
            $iso = Join-Path $target $name
            Save-Download $url $iso 'Windows 11 ISO'
        } else {
            Write-PLog 'Weiche auf UUP dump aus (offizieller Build, aus Microsoft-Dateien gebaut)'
            $o.Ring = 'Retail'
        }
    }
    if (-not $iso) {
        $b = Get-InsiderBuild $o.Ring
        Write-PLog ('Build: {0} ({1})' -f $b.Build, $b.Title)
        $work = Join-Path $target ('UUP_{0}_{1}' -f $b.Build, $o.Lang)
        New-Item $work -ItemType Directory -Force | Out-Null
        $zip = Join-Path $work 'paket.zip'
        $Script:Detail = 'Download-Paket von UUP dump holen'; Set-PStatus $Script:StatusText
        Invoke-WebRequest -Method Post -Uri ('https://uupdump.net/get.php?id={0}&pack={1}&edition={2}' -f $b.Id, $o.Lang, $o.UupEdition) -Body @{ autodl = '2'; updates = '1'; cleanup = '1' } -OutFile $zip -UseBasicParsing
        $head = [IO.File]::ReadAllBytes($zip) | Select-Object -First 2
        if (-not ($head[0] -eq 0x50 -and $head[1] -eq 0x4B)) { throw 'UUP dump hat kein Download-Paket geliefert (Seite geändert oder überlastet). Bitte später erneut versuchen oder uupdump.net im Browser nutzen.' }
        Expand-Archive -LiteralPath $zip -DestinationPath $work -Force
        Remove-Item $zip -Force
        foreach ($ini in @(Get-ChildItem $work -Filter 'ConvertConfig.ini' -Recurse)) { (Get-Content $ini.FullName) -replace '^\s*AutoExit\s*=.*', 'AutoExit =1' | Set-Content $ini.FullName -Encoding ASCII }
        $cmd = Get-ChildItem $work -Filter 'uup_download_windows.cmd' -Recurse | Select-Object -First 1
        if (-not $cmd) { throw 'uup_download_windows.cmd fehlt im Paket.' }
        Write-PLog 'ISO wird gebaut: Download der Microsoft-Dateien und Umwandlung laufen im sichtbaren Fenster (30-90 Minuten).'
        $p = Start-Process -FilePath 'cmd.exe' -ArgumentList @('/c', ('"{0}"' -f $cmd.FullName)) -WorkingDirectory $cmd.DirectoryName -PassThru
        $sw = [Diagnostics.Stopwatch]::StartNew()
        while (-not $p.HasExited) {
            if (Test-PCancel) { & taskkill.exe /PID $p.Id /T /F | Out-Null; throw 'Abgebrochen durch Benutzer' }
            if ($sw.Elapsed.TotalHours -gt 5) { & taskkill.exe /PID $p.Id /T /F | Out-Null; throw 'Zeitlimit überschritten' }
            $Script:Detail = 'ISO wird gebaut (Fenster "UUP"), läuft seit {0:hh\:mm\:ss}' -f $sw.Elapsed; Set-PStatus $Script:StatusText
            Start-Sleep -Seconds 5
        }
        $found = Get-ChildItem $work -Filter '*.iso' -Recurse -ErrorAction SilentlyContinue | Sort-Object LastWriteTime -Descending | Select-Object -First 1
        if (-not $found) { throw 'Es wurde keine ISO erstellt - Details im UUP-Fenster/Ordner.' }
        $iso = Join-Path $target $found.Name
        Move-Item -LiteralPath $found.FullName -Destination $iso -Force
        Remove-Item -LiteralPath $work -Recurse -Force -ErrorAction SilentlyContinue
    }
    Set-Content -LiteralPath (Join-Path $DataDir 'iso_last.txt') -Value $iso -Encoding UTF8
    Write-PLog ('ISO fertig: {0} ({1})' -f $iso, (Format-Bytes (Get-Item -LiteralPath $iso).Length)) 'OK'
    if ($o.Upgrade) { Write-PLog 'Starte Windows-Setup als Upgrade (Programme und Dateien bleiben erhalten) ...'; $null = Start-IsoUpgrade $iso }
}

# ---- Office über das Office Deployment Tool
function Get-OfficeXml($o, [string]$Source = '') {
    $vol = [string]$o.Product -match 'Volume$'
    $ch = if ($o.Product -eq 'ProPlus2024Volume') { 'PerpetualVL2024' } elseif ($o.Product -eq 'ProPlus2021Volume') { 'PerpetualVL2021' } elseif ($vol) { 'PerpetualVL2024' } else { [string]$o.Channel }
    $langs = @([string]$o.Lang -split ',' | Where-Object { $_ })
    $ex = (@($o.Exclude) | Where-Object { $_ } | ForEach-Object { '      <ExcludeApp ID="{0}"/>' -f $_ }) -join "`r`n"
    $lx = ($langs | ForEach-Object { '      <Language ID="{0}"/>' -f $_ }) -join "`r`n"
    $extra = ''
    foreach ($p in @($o.Extra | Where-Object { $_ })) { $extra += "    <Product ID=""$p"">`r`n$lx`r`n    </Product>`r`n" }
    $src = if ($Source) { ' SourcePath="{0}"' -f $Source } else { '' }
@"
<Configuration>
  <Add OfficeClientEdition="64" Channel="$ch"$src>
    <Product ID="$($o.Product)">
$lx
$ex
    </Product>
$extra  </Add>
  <Updates Enabled="TRUE" Channel="$ch"/>
  <Display Level="Full" AcceptEULA="TRUE"/>
  <Property Name="FORCEAPPSHUTDOWN" Value="FALSE"/>
  <RemoveMSI/>
</Configuration>
"@
}
function Invoke-OfficeJob {
    $o = $Script:JobOpts
    $odtDir = Join-Path (Join-Path $DataDir 'Tools') 'Office'
    New-Item $odtDir -ItemType Directory -Force | Out-Null
    $setup = Join-Path $odtDir 'setup.exe'
    if ($o.Mode -eq 'Channel') {
        $c2r = Join-Path $env:CommonProgramFiles 'microsoft shared\ClickToRun\OfficeC2RClient.exe'
        if (-not (Test-Path $c2r)) { throw 'Kein Klick-und-Los-Office (Microsoft 365) installiert.' }
        Write-PLog ('Office-Updatekanal wechseln auf {0}' -f $o.Channel)
        $null = Invoke-External -Exe $c2r -Arguments @('/changesetting', ('Channel={0}' -f $o.Channel)) -TimeoutMin 5 -Quiet
        $null = Invoke-External -Exe $c2r -Arguments @('/update', 'user', 'displaylevel=true', 'forceappshutdown=false') -TimeoutMin 5 -Quiet
        Write-PLog 'Kanal gesetzt - Office lädt die neue Version jetzt im Hintergrund (Fenster von Office).' 'OK'
        return
    }
    Save-Download 'https://officecdn.microsoft.com/pr/wsus/setup.exe' $setup 'Office Deployment Tool'
    $sig = Get-AuthenticodeSignature -FilePath $setup
    if ($sig.Status -ne 'Valid' -or $sig.SignerCertificate.Subject -notmatch 'Microsoft') { throw 'Das Office Deployment Tool ist nicht gültig signiert.' }
    if ($o.Mode -eq 'Install') {
        $xml = Join-Path $odtDir 'install.xml'
        Get-OfficeXml $o | Set-Content -LiteralPath $xml -Encoding UTF8
        Write-PLog ('Office wird installiert: {0}, Kanal {1}, Sprache {2}' -f $o.Product, $o.Channel, $o.Lang)
        $Script:Detail = 'Office-Installation läuft (Fortschritt im Office-Fenster)'; Set-PStatus $Script:StatusText
        $rc = Invoke-External -Exe $setup -Arguments @('/configure', ('"{0}"' -f $xml)) -TimeoutMin 120 -Quiet
        if ($rc -eq 0) { Write-PLog 'Office installiert.' 'OK' } else { Write-PLog ('Office-Setup meldet Code {0}.' -f $rc) 'WARN' }
        return
    }
    # Offline-Paket (z.B. für den USB-Stick)
    $target = if ([string]$o.Target) { [string]$o.Target } else { Join-Path ([Environment]::GetFolderPath('Desktop')) 'Office-Offline' }
    New-Item $target -ItemType Directory -Force | Out-Null
    Copy-Item $setup (Join-Path $target 'setup.exe') -Force
    $dlx = Join-Path $target 'download.xml'
    Get-OfficeXml $o $target | Set-Content -LiteralPath $dlx -Encoding UTF8
    Get-OfficeXml $o | Set-Content -LiteralPath (Join-Path $target 'install.xml') -Encoding UTF8
    Set-Content -LiteralPath (Join-Path $target 'Office installieren.cmd') -Encoding ASCII -Value @('@echo off', 'cd /d "%~dp0"', 'echo Office wird installiert ...', 'setup.exe /configure install.xml')
    Write-PLog ('Office-Offline-Paket wird geladen nach {0} (ca. 3-4 GB)' -f $target)
    $Script:Detail = 'Office-Dateien werden geladen (mehrere GB)'; Set-PStatus $Script:StatusText
    $rc = Invoke-External -Exe (Join-Path $target 'setup.exe') -Arguments @('/download', ('"{0}"' -f $dlx)) -TimeoutMin 240 -Quiet
    Remove-Item $dlx -Force -ErrorAction SilentlyContinue
    if ($rc -eq 0) { Write-PLog ('Office-Offline-Paket fertig: {0} - zum Installieren "Office installieren.cmd" starten.' -f $target) 'OK'; Set-Content (Join-Path $DataDir 'office_last.txt') $target -Encoding UTF8 }
    else { Write-PLog ('Download meldet Code {0}.' -f $rc) 'WARN' }
}

# ---- USB-Stick: bootfähiger Windows-Stick + Office + PC-Tools portabel
function Copy-PortablePflege([string]$Dest, [bool]$WithToken) {
    New-Item $Dest -ItemType Directory -Force | Out-Null
    foreach ($n in 'PCPflege.ps1', 'PCPflege.ico', 'NinitePro.exe') {
        $f = Join-Path $PSScriptRoot $n; if (-not (Test-Path -LiteralPath $f)) { $f = Join-Path $DataDir $n }
        if (Test-Path -LiteralPath $f) { Copy-Item -LiteralPath $f -Destination (Join-Path $Dest $n) -Force }
    }
    Set-Content -LiteralPath (Join-Path $Dest 'portable.txt') -Value 'Diese PC-Tools läuft portabel: Einstellungen und Protokolle liegen im Ordner "Daten" auf dem Stick, auf dem PC wird nichts eingerichtet.' -Encoding UTF8
    Remove-Item -LiteralPath (Join-Path $Dest 'PC-Pflege starten.cmd') -Force -ErrorAction SilentlyContinue
    Set-Content -LiteralPath (Join-Path $Dest 'PC-Tools starten.cmd') -Encoding ASCII -Value @('@echo off', 'start "" powershell.exe -NoProfile -ExecutionPolicy Bypass -WindowStyle Hidden -File "%~dp0PCPflege.ps1"')
    Set-Content -LiteralPath (Join-Path $Dest 'Netzwerk-Tiefenanalyse.cmd') -Encoding ASCII -Value @('@echo off', 'title PC-Tools Netzwerk-Tiefenanalyse', 'cd /d "%~dp0"', 'powershell.exe -NoProfile -ExecutionPolicy Bypass -File "%~dp0PCPflege.ps1" -NetDeep')
    Set-Content -LiteralPath (Join-Path $Dest 'Netzwerk-Notfall.cmd') -Encoding ASCII -Value @('@echo off', 'title PC-Tools Netzwerk-Notfall', 'cd /d "%~dp0"', 'powershell.exe -NoProfile -ExecutionPolicy Bypass -File "%~dp0PCPflege.ps1" -NetDiag')
    Set-Content -LiteralPath (Join-Path $Dest 'Windows-Reparatur.cmd') -Encoding ASCII -Value @('@echo off', 'title PC-Tools Windows-Reparatur', 'cd /d "%~dp0"', 'powershell.exe -NoProfile -ExecutionPolicy Bypass -File "%~dp0PCPflege.ps1" -WinRepair')
    Set-Content -LiteralPath (Join-Path $Dest 'Komplett-Reparatur.cmd') -Encoding ASCII -Value @('@echo off', 'title PC-Tools Komplett-Reparatur', 'cd /d "%~dp0"', 'powershell.exe -NoProfile -ExecutionPolicy Bypass -File "%~dp0PCPflege.ps1" -FullRepair')
    Set-Content -LiteralPath (Join-Path $Dest 'LIESMICH.txt') -Encoding UTF8 -Value @('PC-Tools portabel', '', '"PC-Tools starten.cmd"  - die normale Oberfläche (Einstellungen und Protokolle bleiben im Ordner "Daten" auf dem Stick).', '"Netzwerk-Notfall.cmd"   - Netzwerk-Diagnose im Textfenster: keine IPv4-Adresse (169.254), kein Internet, WLAN-Probleme.', '                          Funktioniert ohne Internet. Bericht landet im Ordner "Netzwerk-Diagnose" auf dem Stick.', '"Windows-Reparatur.cmd"  - Windows-Reparatur im Textfenster (DISM, SFC, Windows Update, Netzwerk-Tiefenreparatur, WinRE,', '                          abgesicherter Modus ...) - wenn die Oberfläche nicht mehr startet. Protokolle im Ordner "Daten".', '"Komplett-Reparatur.cmd" - tiefgreifende Komplett-Reparatur OHNE Rückfragen: Dienste auf Windows-Standard, DISM/SFC,', '                          Windows Update, Netzwerk, WMI, Store/Apps, Update-Blocker und alte angreifbare Treiber. Mit', '                          Super-Log und Fehlerdaten-Paket, am Ende Neustart. Für PCs, auf denen Dienste/Setup klemmen.', 'Ordner "Surface"         - Surface-Treiber-/Firmwarepakete (.msi), in PC-Tools > Microsoft Surface > "Paket vom Stick installieren".', '', 'Die .cmd-Dateien fragen nach Administratorrechten.')
    if ($WithToken) {
        $rt = Get-ReadToken
        if ($rt) { Set-Content -LiteralPath (Join-Path $Dest 'pcpflege.token') -Value (Protect-PkgToken $rt) -Encoding ASCII; Write-PLog '   Update-Zugang (nur Lesen) mitkopiert.' }
        else { Write-PLog '   Kein Nur-Lesen-Token hinterlegt - Stick ohne Update-Zugang.' 'WARN' }
    }
}
function Invoke-UsbJob {
    $o = $Script:JobOpts
    $disk = Get-Disk -Number ([int]$o.DiskNumber) -ErrorAction Stop
    if ($disk.IsBoot -or $disk.IsSystem -or [string]$disk.BusType -ne 'USB') { throw 'Das gewählte Laufwerk ist kein USB-Stick (oder ein Systemlaufwerk) - abgebrochen.' }
    $root = $null; $extra = $null
    $shw = Get-Service ShellHWDetection -ErrorAction SilentlyContinue; $shwRun = $shw -and $shw.Status -eq 'Running'
    try {
        if ($o.Format) {
            if ($shwRun) { Stop-Service ShellHWDetection -Force -ErrorAction SilentlyContinue }
            Write-PLog ('Stick {0} ({1:N0} GB) wird gelöscht und neu eingerichtet ...' -f $disk.FriendlyName, ($disk.Size / 1GB))
            if ($disk.PartitionStyle -ne 'RAW') { Clear-Disk -Number $disk.Number -RemoveData -RemoveOEM -Confirm:$false }
            Initialize-Disk -Number $disk.Number -PartitionStyle MBR -ErrorAction SilentlyContinue
            $big = $disk.Size -gt 34GB
            $p1 = if ($big) { New-Partition -DiskNumber $disk.Number -Size 32GB -IsActive -AssignDriveLetter } else { New-Partition -DiskNumber $disk.Number -UseMaximumSize -IsActive -AssignDriveLetter }
            $null = Format-Volume -Partition $p1 -FileSystem FAT32 -NewFileSystemLabel 'WIN11' -Force -Confirm:$false
            $root = ('{0}:\' -f (Get-Partition -DiskNumber $disk.Number -PartitionNumber $p1.PartitionNumber).DriveLetter)
            $extra = $root
            if ($big) {
                $p2 = New-Partition -DiskNumber $disk.Number -UseMaximumSize -AssignDriveLetter
                $null = Format-Volume -Partition $p2 -FileSystem exFAT -NewFileSystemLabel 'DATEN' -Force -Confirm:$false
                $extra = ('{0}:\' -f (Get-Partition -DiskNumber $disk.Number -PartitionNumber $p2.PartitionNumber).DriveLetter)
            }
            Write-PLog ('Stick eingerichtet: {0} (FAT32, bootfähig){1}' -f $root, $(if ($extra -ne $root) { ', ' + $extra + ' (Daten)' } else { '' })) 'OK'
        } else {
            $v = Get-Partition -DiskNumber $disk.Number | Where-Object { $_.DriveLetter -and [int][char]$_.DriveLetter -ne 0 } | Sort-Object Size -Descending | Select-Object -First 1
            if (-not $v) { throw 'Der Stick hat kein Laufwerk mit Buchstaben.' }
            $root = '{0}:\' -f $v.DriveLetter; $extra = $root
        }
        if ($o.Iso) {
            if (-not $o.Format) { Write-PLog 'Windows-Setup nur beim Neu-Einrichten des Sticks (FAT32, bootfähig).' 'WARN' }
            else {
                Write-PLog ('Windows-Setup von {0} auf den Stick kopieren ...' -f $o.Iso)
                $img = Mount-DiskImage -ImagePath $o.Iso -PassThru
                try {
                    $src = '{0}:\' -f ($img | Get-Volume).DriveLetter
                    $Script:Detail = 'Windows-Dateien werden kopiert'; Set-PStatus $Script:StatusText
                    $rc = Invoke-External -Exe 'robocopy.exe' -Arguments @(('"{0}"' -f $src.TrimEnd('\')), ('"{0}"' -f $root.TrimEnd('\')), '/E', '/XF', 'install.wim', '/R:1', '/W:1', '/NP', '/NJH', '/NJS', '/NDL', '/NFL') -TimeoutMin 90 -Quiet
                    if ($rc -ge 8) { throw ('Kopieren fehlgeschlagen (robocopy {0}).' -f $rc) }
                    $wim = Join-Path $src 'sources\install.wim'
                    if (Test-Path $wim) {
                        if ((Get-Item $wim).Length -gt 4GB - 1MB) {
                            Write-PLog '   install.wim ist größer als 4 GB - wird für FAT32 aufgeteilt (dism /Split-Image) ...'
                            $Script:Detail = 'install.wim wird aufgeteilt (dauert einige Minuten)'; Set-PStatus $Script:StatusText
                            $rc = Invoke-External -Exe 'dism.exe' -Arguments @('/Split-Image', ('/ImageFile:"{0}"' -f $wim), ('/SWMFile:"{0}sources\install.swm"' -f $root), '/FileSize:3800') -TimeoutMin 60 -Quiet
                            if ($rc -ne 0) { throw ('dism /Split-Image meldet {0}' -f $rc) }
                        } else { Copy-Item $wim (Join-Path $root 'sources\install.wim') -Force }
                    }
                    $bs = Join-Path $src 'boot\bootsect.exe'
                    if (Test-Path $bs) { $null = Invoke-External -Exe $bs -Arguments @('/nt60', $root.TrimEnd('\'), '/force', '/mbr') -TimeoutMin 2 -Quiet }
                    Write-PLog 'Windows-Setup auf dem Stick (UEFI und BIOS bootfähig).' 'OK'
                } finally { Dismount-DiskImage -ImagePath $o.Iso -ErrorAction SilentlyContinue | Out-Null }
            }
        }
        if ($o.OfficeDir -and (Test-Path -LiteralPath $o.OfficeDir)) {
            Write-PLog 'Office-Offline-Paket auf den Stick kopieren ...'
            $Script:Detail = 'Office wird kopiert'; Set-PStatus $Script:StatusText
            $rc = Invoke-External -Exe 'robocopy.exe' -Arguments @(('"{0}"' -f $o.OfficeDir.TrimEnd('\')), ('"{0}Office"' -f $extra), '/E', '/R:1', '/W:1', '/NP', '/NJH', '/NJS', '/NDL', '/NFL') -TimeoutMin 60 -Quiet
            if ($rc -ge 8) { Write-PLog ('Office kopieren fehlgeschlagen (robocopy {0})' -f $rc) 'WARN' } else { Write-PLog ('Office liegt auf {0}Office - dort "Office installieren.cmd" starten.' -f $extra) 'OK' }
        }
        if ($o.Pflege) {
            Copy-PortablePflege (Join-Path $extra 'PC-Tools') ([bool]$o.WithToken)
            Write-PLog ('PC-Tools portabel auf {0}PC-Tools - dort "PC-Tools starten.cmd".' -f $extra) 'OK'
        }
        Set-Content -LiteralPath (Join-Path $extra 'LIES MICH - Stick.txt') -Encoding UTF8 -Value @(
            'Dieser Stick wurde mit von PC-Tools erstellt.', '',
            'Windows installieren: vom Stick starten (Boot-Menü, meist F12/F9/F8/ESC) - oder unter Windows setup.exe auf dem Stick ausführen (Upgrade).',
            'Office installieren: Ordner Office > "Office installieren.cmd".', 'PC-Tools: Ordner PC-Tools > "PC-Tools starten.cmd" (läuft portabel, richtet nichts ein).')
    } finally { if ($shwRun) { Start-Service ShellHWDetection -ErrorAction SilentlyContinue } }
}



# =====================================================================
#  DATENSICHERUNG, SYSTEMABBILD, WIEDERHERSTELLUNG, PC-UMZUG
# =====================================================================
$BackupCredFile = Join-Path $DataDir 'backup.cred'
function Save-BackupCred([string]$User, [string]$Pwd) {
    Add-Type -AssemblyName System.Security
    $j = @{ User = $User; Pwd = $Pwd } | ConvertTo-Json -Compress
    [IO.File]::WriteAllBytes($BackupCredFile, [Security.Cryptography.ProtectedData]::Protect([Text.Encoding]::UTF8.GetBytes($j), $null, [Security.Cryptography.DataProtectionScope]::LocalMachine))
    & icacls.exe $BackupCredFile /inheritance:r /grant:r '*S-1-5-18:F' '*S-1-5-32-544:F' | Out-Null
}
function Get-BackupCred {
    if (-not (Test-Path -LiteralPath $BackupCredFile)) { return $null }
    try { Add-Type -AssemblyName System.Security; [Text.Encoding]::UTF8.GetString([Security.Cryptography.ProtectedData]::Unprotect([IO.File]::ReadAllBytes($BackupCredFile), $null, [Security.Cryptography.DataProtectionScope]::LocalMachine)) | ConvertFrom-Json } catch { $null }
}
# NAS-Freigabe mit gespeichertem Zugang verbinden (nötig, wenn die Sicherung als SYSTEM im Zeitplan läuft)
# ---- Stabilität (V14): Netzwerkfreigabe kurz anpingen statt Test-Path minutenlang hängen zu lassen; Dienste mit Zeitlimit steuern
function Test-UncReachable([string]$Path, [int]$Ms = 1500) {
    if ($Path -notmatch '^\\\\([^\\]+)\\') { return $true }
    $h = $Matches[1]; $c = New-Object Net.Sockets.TcpClient
    try { $t = $c.ConnectAsync($h, 445); return [bool]($t.Wait($Ms) -and $c.Connected) } catch { return $false } finally { try { $c.Close() } catch { } }
}
function Set-ServiceSafe([string]$Name, [string]$Action, [int]$Sec = 30) {
    try { Add-Type -AssemblyName System.ServiceProcess -ErrorAction SilentlyContinue } catch { }
    $s = New-Object System.ServiceProcess.ServiceController($Name)
    $s.Refresh(); $deps = @()
    if ($Action -in 'Stop', 'Restart' -and $s.Status -ne 'Stopped') {
        $deps = @($s.DependentServices | Where-Object { $_.Status -eq 'Running' })
        foreach ($d in $deps) { try { $d.Stop(); $d.WaitForStatus('Stopped', [TimeSpan]::FromSeconds($Sec)) } catch { } }
        if (-not $s.CanStop) { throw ('Dienst {0} lässt sich nicht beenden.' -f $Name) }
        $s.Stop()
        try { $s.WaitForStatus('Stopped', [TimeSpan]::FromSeconds($Sec)) } catch { throw ('Dienst {0} hat nicht innerhalb von {1} Sekunden angehalten.' -f $Name, $Sec) }
    }
    if ($Action -in 'Start', 'Restart') {
        $s.Refresh()
        if ($s.Status -ne 'Running') {
            if ($s.Status -ne 'StartPending') { $s.Start() }
            try { $s.WaitForStatus('Running', [TimeSpan]::FromSeconds($Sec)) } catch { throw ('Dienst {0} ist nicht innerhalb von {1} Sekunden gestartet.' -f $Name, $Sec) }
        }
        foreach ($d in $deps) { try { $d.Refresh(); if ($d.Status -ne 'Running') { $d.Start(); $d.WaitForStatus('Running', [TimeSpan]::FromSeconds(15)) } } catch { } }
    }
}
# V14: Start-/Stop-/Restart-Service im ganzen Programm mit Zeitlimit (die Windows-Befehle warten bei hängenden Diensten ewig).
# Gleiche Aufrufform wie die Original-Befehle; Fehler/Zeitüberschreitung als normaler Fehler (-ErrorAction wirkt wie gewohnt).
function Start-Service {
    [CmdletBinding()] param([Parameter(Mandatory = $true, Position = 0, ValueFromPipelineByPropertyName = $true)][Alias('ServiceName')][string[]]$Name, [switch]$PassThru, [int]$TimeoutSec = 45)
    process { foreach ($n in $Name) { try { Set-ServiceSafe $n 'Start' $TimeoutSec } catch { $PSCmdlet.WriteError((New-Object Management.Automation.ErrorRecord($_.Exception, 'PcToolsStartService', 'OperationTimeout', $n))) } } }
}
function Stop-Service {
    [CmdletBinding()] param([Parameter(Mandatory = $true, Position = 0, ValueFromPipelineByPropertyName = $true)][Alias('ServiceName')][string[]]$Name, [switch]$Force, [switch]$NoWait, [switch]$PassThru, [int]$TimeoutSec = 45)
    process {
        foreach ($n in $Name) {
            try { if ($NoWait) { $sc = New-Object System.ServiceProcess.ServiceController($n); if ($sc.Status -ne 'Stopped' -and $sc.CanStop) { $sc.Stop() } } else { Set-ServiceSafe $n 'Stop' $TimeoutSec } }
            catch { $PSCmdlet.WriteError((New-Object Management.Automation.ErrorRecord($_.Exception, 'PcToolsStopService', 'OperationTimeout', $n))) }
        }
    }
}
function Restart-Service {
    [CmdletBinding()] param([Parameter(Mandatory = $true, Position = 0, ValueFromPipelineByPropertyName = $true)][Alias('ServiceName')][string[]]$Name, [switch]$Force, [switch]$PassThru, [int]$TimeoutSec = 45)
    process { foreach ($n in $Name) { try { Set-ServiceSafe $n 'Restart' $TimeoutSec } catch { $PSCmdlet.WriteError((New-Object Management.Automation.ErrorRecord($_.Exception, 'PcToolsRestartService', 'OperationTimeout', $n))) } } }
}
# V14: Wiederherstellungspunkt dauert 15 s bis mehrere Minuten - im Fenster-Thread ohne Einfrieren, sonst wie gewohnt
function Checkpoint-Computer {
    [CmdletBinding()] param([Parameter(Position = 0)][string]$Description = 'PC-Tools', [string]$RestorePointType = 'MODIFY_SETTINGS')
    $onUi = $false; try { $onUi = [bool]($window -and [Windows.Threading.Dispatcher]::FromThread([Threading.Thread]::CurrentThread)) } catch { }
    if (-not $onUi) { Microsoft.PowerShell.Management\Checkpoint-Computer -Description $Description -RestorePointType $RestorePointType -ErrorAction Stop; return }
    $null = Invoke-UiWait { param($d, $t) Microsoft.PowerShell.Management\Checkpoint-Computer -Description $d -RestorePointType $t -ErrorAction Stop; 'ok' } @($Description, $RestorePointType) @() 900 'Wiederherstellungspunkt wird erstellt ... (kann einige Minuten dauern)'
}
# V14: Aufgabe in eigenem Thread ausführen und dabei das Fenster weiter zeichnen lassen (kein "Keine Rückmeldung");
# für kurze, aber blockierende Aufrufe (Wiederherstellungspunkt, Statusabfragen), wenn ein Umbau auf Invoke-Bg zu groß wäre.
function Invoke-UiDoEvents {
    try { $f = New-Object Windows.Threading.DispatcherFrame; [void][Windows.Threading.Dispatcher]::CurrentDispatcher.BeginInvoke([Windows.Threading.DispatcherPriority]::Background, [Windows.Threading.DispatcherOperationCallback] { param($x) $x.Continue = $false; $null }, $f); [Windows.Threading.Dispatcher]::PushFrame($f) } catch { }
}
function Invoke-UiWait([scriptblock]$Script, [object[]]$Arguments = @(), [string[]]$Functions = @(), [int]$TimeoutSec = 600, [string]$Text = '') {
    $ps = [powershell]::Create()
    try { $Functions = @(@($Functions) + @(Get-BgFnClosure $Functions) | Where-Object { $_ } | Select-Object -Unique) } catch { }
    try { Set-BgCommonVars $ps } catch { }
    $pre = ($Functions | ForEach-Object { "function $_ {`n" + (Get-Item "function:$_").ScriptBlock.ToString() + "`n}" }) -join "`n"
    if ($pre) { [void]$ps.AddScript($pre); [void]$ps.AddStatement() }
    [void]$ps.AddScript($Script.ToString()); foreach ($a in $Arguments) { [void]$ps.AddArgument($a) }
    $h = $ps.BeginInvoke()
    $ct = $null; $en = $true
    try { if ($Text -and $ui -and $ui.StatusText) { $ui.StatusText.Text = $Text } } catch { }
    try { if ($window) { $ct = $window.Content; if ($ct) { $en = $ct.IsEnabled; $ct.IsEnabled = $false }; $window.Cursor = 'Wait' } } catch { }
    $sw = [Diagnostics.Stopwatch]::StartNew()
    try {
        while (-not $h.IsCompleted) {
            Invoke-UiDoEvents; Start-Sleep -Milliseconds 40
            if ($sw.Elapsed.TotalSeconds -gt $TimeoutSec) { try { $ps.BeginStop($null, $null) | Out-Null } catch { }; throw ('Zeitlimit von {0} Sekunden überschritten.' -f $TimeoutSec) }
        }
        $r = $ps.EndInvoke($h)
        if ($ps.Streams.Error.Count -and -not $r.Count) { throw $ps.Streams.Error[0].Exception }
        return $r
    } finally {
        try { if ($ct) { $ct.IsEnabled = $en }; if ($window) { $window.Cursor = $null } } catch { }
        if ($h.IsCompleted) { $ps.Dispose() }
    }
}
function Connect-BackupTarget([string]$Path) {
    if ($Path -notmatch '^(\\\\[^\\]+\\[^\\]+)') { return }
    $share = $Matches[1]
    if (-not (Test-UncReachable $share)) { return }   # NAS aus/nicht erreichbar: nicht minutenlang warten
    if (Test-Path -LiteralPath $share -ErrorAction SilentlyContinue) { return }
    $c = Get-BackupCred
    if ($c -and $c.User -and $c.Pwd) { $null = Invoke-NdCmd (Join-Path $env:windir 'System32\net.exe') ('use "{0}" "{1}" /user:"{2}" /persistent:no' -f $share, $c.Pwd, $c.User) 20 }
}
function Get-RoboArgs($B, [string]$Mode) {
    $a = @(); if ($Mode -like 'Spiegeln*') { $a += '/MIR' } else { $a += '/E' }
    $a += @('/COPY:DAT', '/DCOPY:DAT', '/R:2', '/W:5', ('/MT:{0}' -f [math]::Max(1, [math]::Min(64, [int]$B.Threads))), '/XJ', '/FFT', '/NP', '/NDL', '/NFL', '/NJH')
    $xf = @(([string]$B.ExcludeFiles) -split '[;,]' | ForEach-Object { $_.Trim() } | Where-Object { $_ })
    $xd = @(([string]$B.ExcludeDirs) -split '[;,]' | ForEach-Object { $_.Trim() } | Where-Object { $_ })
    if ($xf.Count) { $a += '/XF'; $a += ($xf | ForEach-Object { '"{0}"' -f $_ }) }
    if ($xd.Count) { $a += '/XD'; $a += ($xd | ForEach-Object { '"{0}"' -f $_ }) }
    return , $a
}
function Invoke-BackupJob {
    $B = $Script:Cfg.Backup
    $start = Get-Date
    $target = ([string]$B.Target).Trim().TrimEnd('\')
    if (-not $target) { throw 'Kein Sicherungsziel eingetragen (Seite Sicherung).' }
    Connect-BackupTarget $target
    if (-not (Test-Path -LiteralPath $target)) {
        if ($B.OnlyIfTarget -and $Script:IsAuto) { Write-PLog ('Sicherungsziel {0} nicht erreichbar (Festplatte nicht angeschlossen?) - Sicherung übersprungen.' -f $target) 'WARN'; return }
        try { New-Item $target -ItemType Directory -Force -ErrorAction Stop | Out-Null } catch { throw ('Sicherungsziel {0} ist nicht erreichbar.' -f $target) }
    }
    $pcRoot = Join-Path $target $env:COMPUTERNAME
    $versions = [string]$B.Mode -like 'Versionen*'
    $set = if ($versions) { Join-Path $pcRoot (Get-Date -Format 'yyyy-MM-dd_HHmm') } else { Join-Path $pcRoot 'Aktuell' }
    New-Item $set -ItemType Directory -Force | Out-Null
    $sources = @(([string]$B.Sources) -split ';' | ForEach-Object { $_.Trim() } | Where-Object { $_ })
    if (-not $sources.Count) { throw 'Keine Ordner zum Sichern ausgewählt.' }
    Write-PLog ('Sicherung nach {0} ({1}, {2} Ordner)' -f $set, $B.Mode, $sources.Count)
    $used = @{}; $meta = [System.Collections.Generic.List[object]]::new(); $errors = 0
    $robo = Get-RoboArgs $B ([string]$B.Mode)
    foreach ($src in $sources) {
        if (Test-PCancel) { throw 'Abgebrochen durch Benutzer' }
        $name = Split-Path $src.TrimEnd('\') -Leaf; if (-not $name) { $name = ($src -replace '[:\\]', '_') }
        $n = $name; $i = 2; while ($used.ContainsKey($n.ToLower())) { $n = '{0} ({1})' -f $name, $i; $i++ }; $used[$n.ToLower()] = $true
        Connect-BackupTarget $src
        if (-not (Test-Path -LiteralPath $src)) { Write-PLog ('   {0}: Quelle nicht vorhanden - übersprungen' -f $src) 'WARN'; $errors++; continue }
        if ([string]$B.Mode -like 'Spiegeln*' -and -not (Get-ChildItem -LiteralPath $src -Force -ErrorAction SilentlyContinue | Select-Object -First 1)) {
            Write-PLog ('   {0}: Quelle ist leer - zur Sicherheit übersprungen (Spiegeln würde das Ziel leeren)' -f $src) 'WARN'; $errors++; continue
        }
        $dst = Join-Path $set $n
        $Script:Detail = 'Sichere {0}' -f $src; Set-PStatus $Script:StatusText
        Write-PLog ('   {0} -> {1}' -f $src, $dst)
        $rc = Invoke-External -Exe 'robocopy.exe' -Arguments (@(('"{0}"' -f $src.TrimEnd('\')), ('"{0}"' -f $dst)) + $robo) -TimeoutMin 720 -OemEncoding
        if ($rc -ge 8 -or $rc -lt 0) { Write-PLog ('   {0}: Fehler beim Kopieren (robocopy {1})' -f $name, $rc) 'WARN'; $errors++ } else { Write-PLog ('   {0}: OK' -f $name) 'OK' }
        $meta.Add([pscustomobject]@{ Name = $n; Source = $src })
    }
    [pscustomobject]@{ Computer = $env:COMPUTERNAME; User = $env:USERNAME; Date = (Get-Date).ToString('yyyy-MM-dd HH:mm'); Mode = [string]$B.Mode; Folders = @($meta) } |
        ConvertTo-Json -Depth 4 | Set-Content -LiteralPath (Join-Path $set 'sicherung.json') -Encoding UTF8
    if ($versions) {
        $keep = [math]::Max(1, [int]$B.Keep)
        $old = @(Get-ChildItem -LiteralPath $pcRoot -Directory -ErrorAction SilentlyContinue | Where-Object { $_.Name -match '^\d{4}-\d{2}-\d{2}_\d{4}$' } | Sort-Object Name -Descending | Select-Object -Skip $keep)
        foreach ($o in $old) { Write-PLog ('   Alte Version entfernt: {0}' -f $o.Name); Remove-Item -LiteralPath $o.FullName -Recurse -Force -ErrorAction SilentlyContinue }
    }
    if ($B.Drivers) {
        $Script:Detail = 'Treiber werden exportiert'; Set-PStatus $Script:StatusText
        $drv = Join-Path $pcRoot 'Treiber'
        Remove-Item -LiteralPath $drv -Recurse -Force -ErrorAction SilentlyContinue; New-Item $drv -ItemType Directory -Force | Out-Null
        $rc = Invoke-External -Exe 'dism.exe' -Arguments @('/online', '/export-driver', ('/destination:"{0}"' -f $drv)) -TimeoutMin 60 -Quiet
        Write-PLog ('Treiber exportiert nach {0} (Code {1})' -f $drv, $rc) $(if ($rc -eq 0) { 'OK' } else { 'WARN' })
    }
    if ($B.Image) { Invoke-ImageBackup ([string]$B.ImageTarget) }
    $res = [pscustomobject]@{ Date = (Get-Date).ToString('dd.MM.yyyy HH:mm'); Target = $set; Errors = $errors; Minutes = [math]::Round(((Get-Date) - $start).TotalMinutes, 1) }
    $res | ConvertTo-Json | Set-Content -LiteralPath (Join-Path $DataDir 'backup_last.json') -Encoding UTF8
    Write-PLog ('Sicherung fertig nach {0} Min., {1} Problem(e).' -f $res.Minutes, $errors) $(if ($errors) { 'WARN' } else { 'OK' })
    if ($B.Shutdown -and $Script:IsAuto) { Write-PLog 'PC wird in 2 Minuten heruntergefahren (Einstellung der Sicherung).'; & shutdown.exe /s /t 120 /c 'PC-Tools: Sicherung fertig - PC wird heruntergefahren' | Out-Null }
}
function Invoke-ImageBackup([string]$Target) {
    $t = $Target.Trim().TrimEnd('\')
    if (-not $t) { throw 'Kein Ziel für das Systemabbild eingetragen.' }
    if ($t -match '^[A-Za-z]$') { $t += ':' }
    if ($t -match '^[A-Za-z]:$' -and $t -eq $env:SystemDrive) { throw 'Das Systemabbild kann nicht auf das Systemlaufwerk selbst geschrieben werden.' }
    Connect-BackupTarget $t
    Write-PLog ('Systemabbild (komplettes Windows inkl. Programme) wird erstellt auf {0} - kann 30-120 Minuten dauern' -f $t)
    $Script:Detail = 'Systemabbild wird erstellt (Windows-Sicherung wbadmin)'; Set-PStatus $Script:StatusText
    $a = @('start', 'backup', ('-backupTarget:{0}' -f $t), ('-include:{0}' -f $env:SystemDrive), '-allCritical', '-quiet')
    if ($t -like '\\*') { $c = Get-BackupCred; if ($c -and $c.User) { $a += ('-user:{0}' -f $c.User); $a += ('-password:{0}' -f $c.Pwd) } }
    $rc = Invoke-External -Exe 'wbadmin.exe' -Arguments $a -TimeoutMin 720 -OemEncoding
    if ($rc -eq 0) { Write-PLog 'Systemabbild erfolgreich erstellt. Wiederherstellen: Neustart und BIOS > Erweiterte Startoptionen > Problembehandlung > Systemimage-Wiederherstellung.' 'OK' }
    else { Write-PLog ('Systemabbild meldet Code {0} - Ziel muss NTFS oder eine Netzwerkfreigabe sein und darf nicht auf der Systemplatte liegen.' -f $rc) 'WARN' }
}
function Invoke-RestoreJob {
    $o = $Script:JobOpts
    foreach ($it in @($o.Items)) {
        if (Test-PCancel) { throw 'Abgebrochen durch Benutzer' }
        $src = Join-Path $o.Set $it.Name
        if (-not (Test-Path -LiteralPath $src)) { Write-PLog ('   {0}: nicht in der Sicherung' -f $it.Name) 'WARN'; continue }
        $dst = [string]$it.Dest
        New-Item $dst -ItemType Directory -Force | Out-Null
        $a = @(('"{0}"' -f $src), ('"{0}"' -f $dst.TrimEnd('\')), '/E', '/COPY:DAT', '/R:2', '/W:5', '/MT:16', '/XJ', '/FFT', '/NP', '/NDL', '/NFL', '/NJH')
        if ($o.OnlyNewer) { $a += '/XO' }
        $Script:Detail = 'Stelle {0} wieder her' -f $it.Name; Set-PStatus $Script:StatusText
        $rc = Invoke-External -Exe 'robocopy.exe' -Arguments $a -TimeoutMin 720 -OemEncoding
        Write-PLog ('   {0} -> {1}: {2}' -f $it.Name, $dst, $(if ($rc -lt 8 -and $rc -ge 0) { 'OK' } else { "Fehler (robocopy $rc)" })) $(if ($rc -lt 8 -and $rc -ge 0) { 'OK' } else { 'WARN' })
    }
}

# ---- PC-Umzug
$MigSettingDefs = [ordered]@{
    Wlan = 'WLAN-Profile mit Kennwörtern'; Drives = 'Netzlaufwerke'; Printers = 'Netzwerkdrucker'
    Firefox = 'Firefox komplett (Lesezeichen, Kennwörter, Verlauf, Erweiterungen)'
    ChromeAll = 'Chrome komplett (Lesezeichen, Verlauf, Erweiterungen, Autofill)'; EdgeAll = 'Edge komplett (Lesezeichen, Verlauf, Erweiterungen, Autofill)'
    Brave = 'Brave komplett'; Vivaldi = 'Vivaldi komplett'; Opera = 'Opera komplett'
    Signatures = 'Outlook-Signaturen'; Templates = 'Office-Vorlagen'; Fonts = 'Eigene Schriftarten'
    Wallpaper = 'Hintergrundbild'; Explorer = 'Explorer-Einstellungen (Dateiendungen, Ansicht)'; Environment = 'Umgebungsvariablen'; Pflege = 'Einstellungen von PC-Tools'
}
# Ganze Browser-Profile werden 1:1 kopiert (kein Entschlüsseln von Kennwörtern). Firefox nimmt seine Passwörter mit;
# bei Chrome/Edge/Brave/Vivaldi/Opera sind die gespeicherten Passwörter mit dem Windows-Konto verschlüsselt (DPAPI) und
# lassen sich auf dem neuen PC nicht entschlüsseln - dafür ist die Browser-Anmeldung/Synchronisierung der Weg.
$BrowserDefs = [ordered]@{
    Firefox   = @{ Path = (Join-Path $env:APPDATA 'Mozilla\Firefox');                          Proc = 'firefox'; Kind = 'ff' }
    ChromeAll = @{ Path = (Join-Path $env:LOCALAPPDATA 'Google\Chrome\User Data');              Proc = 'chrome';  Kind = 'cr' }
    EdgeAll   = @{ Path = (Join-Path $env:LOCALAPPDATA 'Microsoft\Edge\User Data');             Proc = 'msedge';  Kind = 'cr' }
    Brave     = @{ Path = (Join-Path $env:LOCALAPPDATA 'BraveSoftware\Brave-Browser\User Data'); Proc = 'brave';   Kind = 'cr' }
    Vivaldi   = @{ Path = (Join-Path $env:LOCALAPPDATA 'Vivaldi\User Data');                    Proc = 'vivaldi'; Kind = 'cr' }
    Opera     = @{ Path = (Join-Path $env:APPDATA 'Opera Software\Opera Stable');               Proc = 'opera';   Kind = 'cr' }
}
function Copy-BrowserExport([string]$Key, [string]$Dest) {
    $bd = $BrowserDefs[$Key]
    if (-not (Test-Path -LiteralPath $bd.Path)) { return $false }
    if (Test-BrowserRunning $bd.Proc) { Write-PLog ('   {0} läuft - bitte schließen, sonst fehlen gesperrte Dateien.' -f $MigSettingDefs[$Key]) 'WARN' }
    $xd = if ($bd.Kind -eq 'ff') { @('cache2', 'startupCache', 'thumbnails', 'crashes', 'minidumps') }
          else { @('Cache', 'Code Cache', 'GPUCache', 'GrShaderCache', 'ShaderCache', 'Crashpad', 'component_crx_cache', 'Service Worker', 'optimization_guide_model_store', 'Subresource Filter') }
    $ra = @(('"{0}"' -f $bd.Path), ('"{0}"' -f $Dest), '/E', '/R:1', '/W:1', '/NP', '/NDL', '/NFL', '/NJH', '/XD') + $xd
    # Chromium: die Kennwort-Datenbank ist an dieses Windows-Konto gebunden und auf dem neuen PC nutzlos - sie reist als CSV (Export-Funktion des Browsers)
    if ($bd.Kind -eq 'cr') { $ra += @('/XF', '"Login Data"', '"Login Data-journal"', '"Login Data For Account"', '"Login Data For Account-journal"') }
    $null = Invoke-External -Exe 'robocopy.exe' -Arguments $ra -TimeoutMin 120 -Quiet
    if ($bd.Kind -eq 'cr') { Write-PLog '      Kennwörter: über "Kennwörter exportieren" (Seite PC-Umzug) als CSV-Datei ins Paket - lokal, ohne Cloud.' }
    return $true
}
function Copy-BrowserImport([string]$Key, [string]$Src) {
    $bd = $BrowserDefs[$Key]
    if (Test-BrowserRunning $bd.Proc) { Get-Process $bd.Proc -ErrorAction SilentlyContinue | Stop-Process -Force; Start-Sleep 2 }
    New-Item $bd.Path -ItemType Directory -Force | Out-Null
    $null = Invoke-External -Exe 'robocopy.exe' -Arguments @(('"{0}"' -f $Src), ('"{0}"' -f $bd.Path), '/E', '/R:1', '/W:1', '/NP', '/NDL', '/NFL', '/NJH') -TimeoutMin 120 -Quiet
}
# Kennwörter über die Export-/Import-Funktion der Browser (CSV, vom Benutzer mit Windows-Kennwort bestätigt - lokal, ohne Cloud)
$BrowserPwDefs = [ordered]@{
    Chrome  = @{ Name = 'Chrome';  Exe = 'chrome.exe';  Paths = @('Google\Chrome\Application\chrome.exe');                 Export = 'chrome://password-manager/settings'; Import = 'chrome://password-manager/settings' }
    Edge    = @{ Name = 'Edge';    Exe = 'msedge.exe';  Paths = @('Microsoft\Edge\Application\msedge.exe');                Export = 'edge://settings/passwords';           Import = 'edge://settings/importData' }
    Firefox = @{ Name = 'Firefox'; Exe = 'firefox.exe'; Paths = @('Mozilla Firefox\firefox.exe');                         Export = 'about:logins';                        Import = 'about:logins' }
    Brave   = @{ Name = 'Brave';   Exe = 'brave.exe';   Paths = @('BraveSoftware\Brave-Browser\Application\brave.exe');    Export = 'brave://password-manager/settings';   Import = 'brave://password-manager/settings' }
    Vivaldi = @{ Name = 'Vivaldi'; Exe = 'vivaldi.exe'; Paths = @('Vivaldi\Application\vivaldi.exe');                     Export = 'chrome://password-manager/settings';  Import = 'chrome://password-manager/settings' }
    Opera   = @{ Name = 'Opera';   Exe = 'opera.exe';   Paths = @('Programs\Opera\opera.exe', 'Programs\Opera\launcher.exe', 'Opera\launcher.exe'); Export = 'opera://settings/passwords'; Import = 'opera://settings/importData' }
}
function Get-BrowserExe([string]$Key) {
    $b = $BrowserPwDefs[$Key]
    foreach ($h in 'HKLM:', 'HKCU:', 'HKLM:\SOFTWARE\WOW6432Node') {
        $k = if ($h -like '*WOW*') { "$h\Microsoft\Windows\CurrentVersion\App Paths\$($b.Exe)" } else { "$h\SOFTWARE\Microsoft\Windows\CurrentVersion\App Paths\$($b.Exe)" }
        $v = (Get-ItemProperty -LiteralPath $k -ErrorAction SilentlyContinue).'(default)'
        if ($v) { $v = $v.Trim('"'); if (Test-Path -LiteralPath $v) { return $v } }
    }
    foreach ($root in @($env:ProgramFiles, ${env:ProgramFiles(x86)}, $env:LOCALAPPDATA)) {
        if (-not $root) { continue }
        foreach ($rel in $b.Paths) { $f = Join-Path $root $rel; if (Test-Path -LiteralPath $f) { return $f } }
    }
    return $null
}
function Get-PwFolder([string]$Target) { Join-Path $Target 'PC-Umzug-Kennwoerter' }
function Remove-FileSecure([string]$Path) {
    # Inhalt vor dem Löschen überschreiben (auf SSDs nicht garantiert - das Paket trotzdem sicher verwahren)
    try { $len = (Get-Item -LiteralPath $Path).Length; $fs = [IO.File]::Open($Path, 'Open', 'Write'); $buf = New-Object byte[] 65536; $n = [int64]0
          while ($n -lt $len) { $c = [int][math]::Min(65536, $len - $n); $fs.Write($buf, 0, $c); $n += $c }; $fs.Flush(); $fs.Close() } catch { }
    Remove-Item -LiteralPath $Path -Force -ErrorAction SilentlyContinue
}
function Get-KnownFolders {
    $l = [ordered]@{ Desktop = 'Desktop'; Dokumente = 'MyDocuments'; Bilder = 'MyPictures'; Musik = 'MyMusic'; Videos = 'MyVideos'; Favoriten = 'Favorites' }
    $r = foreach ($k in $l.Keys) { $p = [Environment]::GetFolderPath($l[$k]); if ($p -and (Test-Path -LiteralPath $p)) { [pscustomobject]@{ Name = $k; Path = $p } } }
    $dl = (Get-ItemProperty 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\User Shell Folders' -ErrorAction SilentlyContinue).'{374DE290-123F-4565-9164-39C4925E467B}'
    if ($dl) { $dl = [Environment]::ExpandEnvironmentVariables($dl) } else { $dl = Join-Path $env:USERPROFILE 'Downloads' }
    if (Test-Path -LiteralPath $dl) { $r = @($r) + [pscustomobject]@{ Name = 'Downloads'; Path = $dl } }
    return @($r)
}
function Test-BrowserRunning([string]$Name) { [bool](Get-Process -Name $Name -ErrorAction SilentlyContinue) }
function Invoke-MigrateExport {
    $o = $Script:JobOpts
    $root = Join-Path ([string]$o.Target) ('PC-Umzug_{0}_{1}' -f $env:COMPUTERNAME, (Get-Date -Format 'yyyy-MM-dd_HHmm'))
    Connect-BackupTarget ([string]$o.Target)
    New-Item $root -ItemType Directory -Force | Out-Null
    $man = [ordered]@{ Computer = $env:COMPUTERNAME; User = $env:USERNAME; Date = (Get-Date).ToString('dd.MM.yyyy HH:mm'); Windows = (Get-CimInstance Win32_OperatingSystem).Caption; Folders = @(); Settings = @(); AppData = @(); Programs = $false }
    Write-PLog ('Umzugspaket: {0}' -f $root)
    # Daten
    foreach ($f in @($o.Folders)) {
        if (Test-PCancel) { throw 'Abgebrochen durch Benutzer' }
        if (-not (Test-Path -LiteralPath $f.Path)) { continue }
        $Script:Detail = 'Kopiere {0}' -f $f.Name; Set-PStatus $Script:StatusText
        $rc = Invoke-External -Exe 'robocopy.exe' -Arguments @(('"{0}"' -f $f.Path.TrimEnd('\')), ('"{0}"' -f (Join-Path (Join-Path $root 'Daten') $f.Name)), '/E', '/COPY:DAT', '/R:1', '/W:2', '/MT:16', '/XJ', '/FFT', '/NP', '/NDL', '/NFL', '/NJH', '/XF', 'desktop.ini', 'Thumbs.db', '~$*') -TimeoutMin 720 -OemEncoding
        Write-PLog ('   Daten {0}: {1}' -f $f.Name, $(if ($rc -lt 8 -and $rc -ge 0) { 'OK' } else { "Fehler (robocopy $rc)" })) $(if ($rc -lt 8 -and $rc -ge 0) { 'OK' } else { 'WARN' })
        $man.Folders += [pscustomobject]@{ Name = $f.Name; Source = $f.Path }
    }
    # Programme
    if ($o.Programs) {
        $Script:Detail = 'Programmliste wird erstellt'; Set-PStatus $Script:StatusText
        $pdir = Join-Path $root 'Programme'; New-Item $pdir -ItemType Directory -Force | Out-Null
        $wgIds = @{}
        $wg = Get-WingetPath
        if ($wg) {
            $ex = Join-Path $pdir 'winget.json'
            $null = Invoke-External -Exe $wg -Arguments @('export', '-o', ('"{0}"' -f $ex), '--accept-source-agreements', '--disable-interactivity') -TimeoutMin 10 -Quiet
            if (Test-Path $ex) { try { foreach ($src in (Get-Content $ex -Raw | ConvertFrom-Json).Sources) { foreach ($p in $src.Packages) { $wgIds[[string]$p.PackageIdentifier] = [string]$src.SourceDetails.Name } } } catch { } }
            $null = Invoke-External -Exe $wg -Arguments @('list', '--accept-source-agreements', '--disable-interactivity') -TimeoutMin 5 -Capture
            $lines = @($Script:Captured)
        } else { $lines = @(); Write-PLog 'winget fehlt - Programme werden nur aufgelistet, nicht automatisch installierbar.' 'WARN' }
        $progs = [System.Collections.Generic.List[object]]::new(); $matched = @{}
        foreach ($id in $wgIds.Keys) {
            $row = $lines | Where-Object { $_.Contains(' ' + $id + ' ') -or $_.TrimEnd().EndsWith(' ' + $id) } | Select-Object -First 1
            $nm = if ($row) { $row.Substring(0, $row.IndexOf(' ' + $id)).Trim() } else { $id }
            if (-not $nm) { $nm = $id }
            $progs.Add([pscustomobject]@{ Name = $nm; Id = $id; Source = $wgIds[$id] }); $matched[$nm.ToLower()] = $true
        }
        foreach ($p in (Get-InstalledPrograms)) {
            $hit = $false; foreach ($k in $matched.Keys) { if ($p.Name.ToLower().StartsWith($k) -or $k.StartsWith($p.Name.ToLower())) { $hit = $true; break } }
            if (-not $hit) { $progs.Add([pscustomobject]@{ Name = $p.Name; Id = ''; Source = ''; Version = $p.Version; Publisher = $p.Publisher }) }
        }
        $progs | ConvertTo-Json -Depth 3 | Set-Content -LiteralPath (Join-Path $pdir 'Programme.json') -Encoding UTF8
        @($progs | Where-Object { -not $_.Id } | Sort-Object Name | ForEach-Object { '{0}  {1}  ({2})' -f $_.Name, $_.Version, $_.Publisher }) | Set-Content -LiteralPath (Join-Path $pdir 'Manuell installieren.txt') -Encoding UTF8
        Write-PLog ('   Programme: {0} automatisch installierbar (winget), {1} nur als Liste' -f @($progs | Where-Object Id).Count, @($progs | Where-Object { -not $_.Id }).Count) 'OK'
        $man.Programs = $true
    }
    # Einstellungen
    $sdir = Join-Path $root 'Einstellungen'; New-Item $sdir -ItemType Directory -Force | Out-Null
    foreach ($k in @($o.Settings)) {
        if (Test-PCancel) { throw 'Abgebrochen durch Benutzer' }
        $Script:Detail = 'Einstellungen: ' + $MigSettingDefs[$k]; Set-PStatus $Script:StatusText
        $d = Join-Path $sdir $k; New-Item $d -ItemType Directory -Force | Out-Null
        $ok = $true
        try {
            switch ($k) {
                { $BrowserDefs.Contains($_) } { $ok = Copy-BrowserExport $_ $d; break }
                'Wlan'        { $null = Invoke-External -Exe 'netsh.exe' -Arguments @('wlan', 'export', 'profile', 'key=clear', ('folder="{0}"' -f $d)) -TimeoutMin 2 -Quiet; $ok = [bool](Get-ChildItem $d -Filter *.xml) }
                'Drives'      { @(Get-ItemProperty 'HKCU:\Network\*' -ErrorAction SilentlyContinue | ForEach-Object { [pscustomobject]@{ Letter = $_.PSChildName; Path = $_.RemotePath } }) | ConvertTo-Json | Set-Content (Join-Path $d 'laufwerke.json') -Encoding UTF8 }
                'Printers'    { @(Get-Printer -ErrorAction SilentlyContinue | Where-Object { $_.Type -eq 'Connection' -or $_.Name -like '\\*' } | ForEach-Object { $_.Name }) | ConvertTo-Json | Set-Content (Join-Path $d 'drucker.json') -Encoding UTF8
                                @(Get-CimInstance Win32_Printer -Filter 'Default=True' -ErrorAction SilentlyContinue | ForEach-Object { $_.Name }) | Set-Content (Join-Path $d 'standard.txt') -Encoding UTF8 }
                'Signatures'  { $f = Join-Path $env:APPDATA 'Microsoft\Signatures'; if (Test-Path $f) { Copy-Item "$f\*" $d -Recurse -Force } else { $ok = $false } }
                'Templates'   { $f = Join-Path $env:APPDATA 'Microsoft\Templates'; if (Test-Path $f) { Copy-Item "$f\*" $d -Recurse -Force } else { $ok = $false } }
                'Fonts'       {
                    $fd = Join-Path $env:LOCALAPPDATA 'Microsoft\Windows\Fonts'
                    $map = @{}; $reg = Get-ItemProperty 'HKCU:\Software\Microsoft\Windows NT\CurrentVersion\Fonts' -ErrorAction SilentlyContinue
                    if ($reg) { foreach ($p in $reg.PSObject.Properties | Where-Object { $_.Name -notlike 'PS*' }) { $map[$p.Name] = [IO.Path]::GetFileName([string]$p.Value) } }
                    if (Test-Path $fd) { Copy-Item "$fd\*" $d -Force } else { $ok = $false }
                    $map | ConvertTo-Json | Set-Content (Join-Path $d 'fonts.json') -Encoding UTF8
                }
                'Wallpaper'   { $w = (Get-ItemProperty 'HKCU:\Control Panel\Desktop').WallPaper; $t = Join-Path $env:APPDATA 'Microsoft\Windows\Themes\TranscodedWallpaper'
                                if ($w -and (Test-Path -LiteralPath $w)) { Copy-Item -LiteralPath $w (Join-Path $d ('wallpaper' + [IO.Path]::GetExtension($w))) } elseif (Test-Path $t) { Copy-Item $t (Join-Path $d 'wallpaper.jpg') } else { $ok = $false } }
                'Explorer'    { $null = & reg.exe export 'HKCU\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced' (Join-Path $d 'explorer.reg') /y 2>&1 }
                'Environment' { $null = & reg.exe export 'HKCU\Environment' (Join-Path $d 'environment.reg') /y 2>&1 }
                'Pflege'      { foreach ($n in 'config.json') { $f = Join-Path $DataDir $n; if (Test-Path $f) { Copy-Item $f $d } } }
            }
        } catch { $ok = $false; Write-PLog ('   {0}: {1}' -f $MigSettingDefs[$k], $_.Exception.Message) 'WARN' }
        if ($ok) { $man.Settings += $k; Write-PLog ('   {0}: gesichert' -f $MigSettingDefs[$k]) 'OK' } else { Remove-Item $d -Recurse -Force -ErrorAction SilentlyContinue; Write-PLog ('   {0}: nicht vorhanden' -f $MigSettingDefs[$k]) }
    }
    # Programmeinstellungen (AppData)
    foreach ($n in @($o.AppData)) {
        $src = Join-Path $env:APPDATA $n
        if (-not (Test-Path -LiteralPath $src)) { continue }
        $Script:Detail = 'Programmeinstellungen: ' + $n; Set-PStatus $Script:StatusText
        $rc = Invoke-External -Exe 'robocopy.exe' -Arguments @(('"{0}"' -f $src), ('"{0}"' -f (Join-Path (Join-Path $root 'AppData') $n)), '/E', '/R:1', '/W:1', '/NP', '/NDL', '/NFL', '/NJH', '/XD', 'Cache', 'cache', 'Code Cache', 'GPUCache', 'CachedData', 'logs') -TimeoutMin 60 -Quiet
        if ($rc -lt 8 -and $rc -ge 0) { $man.AppData += $n }
    }
    # Browser-Kennwörter (CSV aus der Export-Funktion der Browser) ins Paket verschieben
    $pwSrc = Get-PwFolder ([string]$o.Target)
    $man.Passwords = @()
    $csv = @(Get-ChildItem -LiteralPath $pwSrc -Filter *.csv -File -ErrorAction SilentlyContinue)
    if ($csv.Count) {
        $pwDst = Join-Path $root 'Kennwoerter'; New-Item $pwDst -ItemType Directory -Force | Out-Null
        foreach ($f in $csv) { Move-Item -LiteralPath $f.FullName -Destination (Join-Path $pwDst $f.Name) -Force; $man.Passwords += $f.Name }
        Remove-Item -LiteralPath $pwSrc -Force -ErrorAction SilentlyContinue
        Write-PLog ('   Browser-Kennwörter: {0} CSV-Datei(en) ins Paket übernommen ({1})' -f $csv.Count, ($man.Passwords -join ', ')) 'OK'
    }
    [pscustomobject]$man | ConvertTo-Json -Depth 5 | Set-Content -LiteralPath (Join-Path $root 'umzug.json') -Encoding UTF8
    Set-Content -LiteralPath (Join-Path $root 'LIES MICH.txt') -Encoding UTF8 -Value @('PC-Umzugspaket von PC-Tools', ('Erstellt am {0} auf {1} (Benutzer {2})' -f $man.Date, $man.Computer, $man.User), '',
        'Auf dem neuen PC: PC-Tools > PC-Umzug > "Paket einlesen" > Ordner wählen > "Ausgewählte zurückspielen".', 'Enthält WLAN-Kennwörter und ggf. Browser-Kennwörter (Ordner Kennwoerter) im Klartext - sicher aufbewahren und nach dem Umzug löschen.', 'Browser-Kennwörter: nach dem Zurückspielen auf der Seite PC-Umzug "In ... importieren" wählen, danach "Kennwort-Dateien löschen".')
    Write-PLog ('Umzugspaket fertig: {0}' -f $root) 'OK'
}
function Invoke-MigrateImport {
    $o = $Script:JobOpts
    $root = [string]$o.Package
    Connect-BackupTarget $root
    $kf = @{}; foreach ($f in (Get-KnownFolders)) { $kf[$f.Name] = $f.Path }
    foreach ($n in @($o.Folders)) {
        if (Test-PCancel) { throw 'Abgebrochen durch Benutzer' }
        $src = Join-Path (Join-Path $root 'Daten') $n
        $dst = if ($kf.ContainsKey($n)) { $kf[$n] } else { Join-Path $env:USERPROFILE $n }
        $Script:Detail = 'Daten {0} -> {1}' -f $n, $dst; Set-PStatus $Script:StatusText
        $rc = Invoke-External -Exe 'robocopy.exe' -Arguments @(('"{0}"' -f $src), ('"{0}"' -f $dst.TrimEnd('\')), '/E', '/COPY:DAT', '/R:1', '/W:2', '/MT:16', '/XJ', '/FFT', '/NP', '/NDL', '/NFL', '/NJH', '/XO') -TimeoutMin 720 -OemEncoding
        Write-PLog ('   Daten {0} -> {1}: {2}' -f $n, $dst, $(if ($rc -lt 8 -and $rc -ge 0) { 'OK' } else { "Fehler (robocopy $rc)" })) $(if ($rc -lt 8 -and $rc -ge 0) { 'OK' } else { 'WARN' })
    }
    $sdir = Join-Path $root 'Einstellungen'
    foreach ($k in @($o.Settings)) {
        $d = Join-Path $sdir $k
        if (-not (Test-Path -LiteralPath $d)) { continue }
        $Script:Detail = 'Einstellungen: ' + $MigSettingDefs[$k]; Set-PStatus $Script:StatusText
        try {
            switch ($k) {
                { $BrowserDefs.Contains($_) } { Copy-BrowserImport $_ $d; break }
                'Wlan'        { foreach ($x in @(Get-ChildItem $d -Filter *.xml)) { $null = Invoke-External -Exe 'netsh.exe' -Arguments @('wlan', 'add', 'profile', ('filename="{0}"' -f $x.FullName), 'user=all') -TimeoutMin 1 -Quiet } }
                'Drives'      { foreach ($m in @(Get-Content (Join-Path $d 'laufwerke.json') -Raw | ConvertFrom-Json)) { if ($m.Letter -and $m.Path) { $null = & net.exe use ('{0}:' -f $m.Letter) $m.Path /persistent:yes 2>&1; Write-PLog ('   Netzlaufwerk {0}: {1}' -f $m.Letter, $m.Path) } } }
                'Printers'    {
                    foreach ($p in @(Get-Content (Join-Path $d 'drucker.json') -Raw | ConvertFrom-Json)) { try { Add-Printer -ConnectionName $p -ErrorAction Stop; Write-PLog ('   Drucker verbunden: {0}' -f $p) } catch { Write-PLog ('   Drucker {0}: {1}' -f $p, $_.Exception.Message) 'WARN' } }
                    $def = (Get-Content (Join-Path $d 'standard.txt') -ErrorAction SilentlyContinue | Select-Object -First 1)
                    if ($def) { $pr = Get-CimInstance Win32_Printer -Filter ("Name='{0}'" -f $def.Replace('\', '\\')) -ErrorAction SilentlyContinue; if ($pr) { $null = Invoke-CimMethod -InputObject $pr -MethodName SetDefaultPrinter } }
                }
                'Signatures'  { $t = Join-Path $env:APPDATA 'Microsoft\Signatures'; New-Item $t -ItemType Directory -Force | Out-Null; Copy-Item "$d\*" $t -Recurse -Force }
                'Templates'   { $t = Join-Path $env:APPDATA 'Microsoft\Templates'; New-Item $t -ItemType Directory -Force | Out-Null; Copy-Item "$d\*" $t -Recurse -Force }
                'Fonts'       {
                    $t = Join-Path $env:LOCALAPPDATA 'Microsoft\Windows\Fonts'; New-Item $t -ItemType Directory -Force | Out-Null
                    $map = Get-Content (Join-Path $d 'fonts.json') -Raw -ErrorAction SilentlyContinue | ConvertFrom-Json
                    $rk = 'HKCU:\Software\Microsoft\Windows NT\CurrentVersion\Fonts'; if (-not (Test-Path $rk)) { New-Item $rk -Force | Out-Null }
                    foreach ($f in @(Get-ChildItem $d -File | Where-Object { $_.Extension -match '\.(ttf|otf|ttc|fon)$' })) {
                        Copy-Item $f.FullName $t -Force
                        $name = $null; if ($map) { $name = ($map.PSObject.Properties | Where-Object { $_.Value -eq $f.Name } | Select-Object -First 1).Name }
                        if (-not $name) { $name = $f.BaseName + ' (TrueType)' }
                        New-ItemProperty -Path $rk -Name $name -Value (Join-Path $t $f.Name) -PropertyType String -Force | Out-Null
                    }
                }
                'Wallpaper'   {
                    $w = Get-ChildItem $d -Filter 'wallpaper*' | Select-Object -First 1
                    if ($w) {
                        $t = Join-Path $env:APPDATA ('Microsoft\Windows\Themes\PC-Umzug' + $w.Extension); Copy-Item $w.FullName $t -Force
                        Add-Type -Name Wp -Namespace PCPflege -MemberDefinition '[DllImport("user32.dll", CharSet = CharSet.Unicode)] public static extern int SystemParametersInfo(int a, int b, string c, int d);' -ErrorAction SilentlyContinue
                        [void][PCPflege.Wp]::SystemParametersInfo(20, 0, $t, 3)
                    }
                }
                'Explorer'    { $null = & reg.exe import (Join-Path $d 'explorer.reg') 2>&1 }
                'Environment' { $null = & reg.exe import (Join-Path $d 'environment.reg') 2>&1 }
                'Pflege'      { $f = Join-Path $d 'config.json'; if (Test-Path $f) { Copy-Item $f (Join-Path $DataDir 'config.json') -Force } }
            }
            Write-PLog ('   {0}: übernommen' -f $MigSettingDefs[$k]) 'OK'
        } catch { Write-PLog ('   {0}: {1}' -f $MigSettingDefs[$k], $_.Exception.Message) 'WARN' }
    }
    foreach ($n in @($o.AppData)) {
        $src = Join-Path (Join-Path $root 'AppData') $n
        if (-not (Test-Path -LiteralPath $src)) { continue }
        $rc = Invoke-External -Exe 'robocopy.exe' -Arguments @(('"{0}"' -f $src), ('"{0}"' -f (Join-Path $env:APPDATA $n)), '/E', '/R:1', '/W:1', '/NP', '/NDL', '/NFL', '/NJH') -TimeoutMin 60 -Quiet
        Write-PLog ('   Programmeinstellungen {0}: {1}' -f $n, $(if ($rc -lt 8 -and $rc -ge 0) { 'übernommen' } else { 'Fehler' }))
    }
    Write-PLog 'PC-Umzug abgeschlossen. Manche Einstellungen (Hintergrund, Explorer, Schriftarten) wirken nach dem Ab- und Anmelden.' 'OK'
}

# ---- Intel-Treiber direkt von Intel (Download-Center: Version, Link und SHA256 stehen auf der Seite)
function Get-IntelGfxPageId([string]$GpuName, [string]$Cpu = '') {
    if ($GpuName -match 'Arc' -or $Cpu -match 'Core\(TM\) Ultra|Core Ultra|Core\(TM\) [357] \d{3}') { return 785597 }
    $gen = 0
    if ($Cpu -match 'i[3579]-(\d{4,5})') { $m = $Matches[1]; $gen = if ($m.Length -eq 5) { [int]$m.Substring(0, 2) } else { [int]$m.Substring(0, 1) } }
    if ($gen -ge 11 -or $GpuName -match 'Iris\(R\) Xe|Iris Xe|UHD Graphics 7\d\d') { return 864990 }
    return 776137
}
# Webseite holen, die Bot-Schutz nutzt (z.B. Intel/Akamai): erst PowerShell mit Browser-Kopfzeilen, dann curl.exe, zuletzt Microsoft Edge unsichtbar
function Get-WebHtml([string]$Url) {
    $ua = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/140.0.0.0 Safari/537.36 Edg/140.0.0.0'
    $hdr = @{ 'Accept' = 'text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8'; 'Accept-Language' = 'de-DE,de;q=0.9,en-US;q=0.8,en;q=0.7'; 'Upgrade-Insecure-Requests' = '1'; 'Sec-Fetch-Dest' = 'document'; 'Sec-Fetch-Mode' = 'navigate'; 'Sec-Fetch-Site' = 'none'; 'Sec-Fetch-User' = '?1' }
    $errs = @()
    try { [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12 } catch { }
    try { return (Invoke-WebRequest -Uri $Url -UseBasicParsing -TimeoutSec 30 -UserAgent $ua -Headers $hdr -ErrorAction Stop).Content } catch { $errs += 'PowerShell: ' + $_.Exception.Message }
    $curl = Join-Path $env:SystemRoot 'System32\curl.exe'
    if (Test-Path -LiteralPath $curl) {
        $tmp = [IO.Path]::GetTempFileName()
        $a = @('-s', '-L', '--compressed', '--max-time', '40', '-o', $tmp, '-w', '%{http_code}', '-A', $ua, '-H', 'Accept: text/html,application/xhtml+xml,*/*;q=0.8', '-H', 'Accept-Language: de-DE,de;q=0.9,en;q=0.7', $Url)
        $code = (& $curl @a 2>$null) -join ''
        if ($code -eq '200') { $t = [IO.File]::ReadAllText($tmp); Remove-Item -LiteralPath $tmp -Force -ErrorAction SilentlyContinue; if ($t.Length -gt 5000) { return $t } } else { Remove-Item -LiteralPath $tmp -Force -ErrorAction SilentlyContinue; $errs += 'curl: HTTP ' + $code }
    }
    $edge = @((Join-Path ${env:ProgramFiles(x86)} 'Microsoft\Edge\Application\msedge.exe'), (Join-Path $env:ProgramFiles 'Microsoft\Edge\Application\msedge.exe')) | Where-Object { Test-Path -LiteralPath $_ } | Select-Object -First 1
    if ($edge) {
        $out = [IO.Path]::GetTempFileName(); $prof = Join-Path $env:TEMP 'PCPflege-Edge'
        $p = Start-Process -FilePath $edge -ArgumentList @('--headless=new', '--disable-gpu', '--no-first-run', '--no-default-browser-check', ('--user-data-dir="{0}"' -f $prof), '--virtual-time-budget=15000', '--dump-dom', ('"{0}"' -f $Url)) -RedirectStandardOutput $out -PassThru
        if (-not $p.WaitForExit(60000)) { try { $p.Kill() } catch { } }
        $t = ''; try { $t = [IO.File]::ReadAllText($out) } catch { }; Remove-Item -LiteralPath $out -Force -ErrorAction SilentlyContinue
        if ($t.Length -gt 5000 -and $t -notmatch 'Access Denied') { return $t }
        $errs += 'Edge: keine Seite erhalten'
    } else { $errs += 'Edge nicht gefunden' }
    throw ('Seite nicht abrufbar ({0})' -f ($errs -join '; '))
}
function Get-IntelDownloadInfo([int]$PageId, [string]$FilePattern = 'gfx_win_[\d\.]+\.exe') {
    try { [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12 } catch { }
    $slug = @{ 776137 = 'intel-7th-10th-gen-processor-graphics-windows'; 864990 = 'intel-11th-14th-gen-processor-graphics-windows'; 785597 = 'intel-arc-graphics-windows'
               19351 = 'intel-wireless-wi-fi-drivers-for-windows-10-and-windows-11'; 18649 = 'intel-wireless-bluetooth-drivers-for-windows-10-and-windows-11' }[$PageId]
    $page = 'https://www.intel.com/content/www/us/en/download/{0}/{1}.html' -f $PageId, $slug
    $html = Get-WebHtml $page
    $m = [regex]::Match($html, ('https://downloadmirror\.intel\.com/\d+/' + $FilePattern))
    if (-not $m.Success) { throw ('Intel-Seite {0}: kein Download-Link gefunden' -f $PageId) }
    $url = $m.Value
    $sha = ''; $h = [regex]::Match($html, 'SHA-?256[^A-Fa-f0-9]{0,300}([A-Fa-f0-9]{64})'); if ($h.Success) { $sha = $h.Groups[1].Value.ToUpper() }
    $ver = ''; $v = [regex]::Match([IO.Path]::GetFileName($url), '(\d+(\.\d+)+)'); if ($v.Success) { $ver = $v.Groups[1].Value.TrimEnd('.') }
    [pscustomobject]@{ Url = $url; Sha256 = $sha; Version = $ver; Page = $page; File = [IO.Path]::GetFileName($url) }
}
function Get-IntelGfxOffer($Gpu) {
    $cpu = [string](Get-CimInstance Win32_Processor | Select-Object -First 1).Name
    $info = Get-IntelDownloadInfo (Get-IntelGfxPageId $Gpu.Name $cpu)
    # gfx_win_101.2141.exe <-> Treiberversion 31.0.101.2141: verglichen wird der Teil nach "101."
    $have = 0; $want = 0
    if ([string]$Gpu.DriverVersion -match '\.(\d+)$') { $have = [int]$Matches[1] }
    if ($info.Version -match '(\d+)$') { $want = [int]$Matches[1] }
    $info | Add-Member -NotePropertyName Installed -NotePropertyValue $have -Force
    $info | Add-Member -NotePropertyName Newer -NotePropertyValue ($want -gt $have -and $have -gt 0) -Force
    $info | Add-Member -NotePropertyName Full -NotePropertyValue $(if ([string]$Gpu.DriverVersion -match '^(\d+\.\d+\.\d+)\.') { '{0}.{1}' -f $Matches[1], $want } else { [string]$want }) -Force
    return $info
}
function Invoke-IntelGfxUpdate($Gpu) {
    $o = Get-IntelGfxOffer $Gpu
    Write-PLog ('   Intel bietet {0} an ({1})' -f $o.Full, $o.Page)
    if (-not $o.Newer) { Write-PLog '   Intel-Grafiktreiber ist aktuell (oder neuer als bei Intel).' 'OK'; return }
    if ($Script:CheckOnly) { Write-PLog ('   Update verfügbar: {0} -> {1}' -f $Gpu.DriverVersion, $o.Full) 'WARN'; return }
    $file = Join-Path (Join-Path $DataDir 'Downloads') $o.File
    Save-Download $o.Url $file ('Intel-Grafiktreiber ' + $o.Full)
    if ($o.Sha256) {
        $got = (Get-FileHash -LiteralPath $file -Algorithm SHA256).Hash
        if ($got -ne $o.Sha256) { Write-PLog '   Prüfsumme stimmt nicht mit der Intel-Seite überein - nicht installiert.' 'FEHLER'; Remove-Item -LiteralPath $file -Force -ErrorAction SilentlyContinue; return }
        Write-PLog '   Prüfsumme (SHA256) wie auf der Intel-Seite.' 'OK'
    }
    $sig = Get-AuthenticodeSignature -FilePath $file
    if ($sig.Status -ne 'Valid' -or [string]$sig.SignerCertificate.Subject -notmatch 'Intel') { Write-PLog '   Signatur ungültig - nicht installiert.' 'FEHLER'; Remove-Item -LiteralPath $file -Force -ErrorAction SilentlyContinue; return }
    try { Invoke-DsBeforeDriverUpdate 'Intel-Grafiktreiber' } catch { }
    $Script:Detail = 'Intel-Grafiktreiber wird installiert - der Bildschirm kann kurz flackern'; Set-PStatus $Script:StatusText
    $rc = Invoke-External -Exe $file -Arguments @('-s') -TimeoutMin 45 -Quiet
    Remove-Item -LiteralPath $file -Force -ErrorAction SilentlyContinue
    $now = @(Get-GpuList | Where-Object { $_.Name -eq $Gpu.Name }) | Select-Object -First 1
    if ($rc -eq 0 -or ($now -and $now.DriverVersion -ne $Gpu.DriverVersion)) { Write-PLog ('   Intel-Grafiktreiber {0} installiert (Neustart empfohlen).' -f $o.Full) 'OK'; $Script:UpdatesInstalled++; $Script:RebootNeeded = $true }
    else { Write-PLog ('   Intel-Installer meldet Code {0}. Log: C:\ProgramData\Intel\IntelGFX.log' -f $rc) 'WARN' }
}
# Intel WLAN und Bluetooth: aktuelles Paket aus dem Intel-Download-Center, still installiert (-s)
$IntelWireless = @(
    @{ Kind = 'WLAN';      PageId = 19351; Pattern = 'WiFi-[\d\.]+-Driver64-Win10-Win11\.exe'; Device = { $_.PNPClass -eq 'Net' -and $_.Name -match 'Wi-?Fi|Wireless-AC|Wireless' }; Arp = 'Intel.*(PROSet|Wi-?Fi|Wireless) (Software|Driver|Drivers)' }
    @{ Kind = 'Bluetooth'; PageId = 18649; Pattern = 'BT-[\d\.]+-64UWD-Win10-Win11\.exe';      Device = { $_.PNPClass -eq 'Bluetooth' -and $_.Name -match 'Intel' };            Arp = 'Intel.*Wireless Bluetooth' }
)
function Get-IntelDsaPath {
    # Intel DSA liegt je nach Version in unterschiedlichen Ordnern bzw. heißt die Tray-/Dienstdatei anders
    foreach ($b in @(${env:ProgramFiles(x86)}, $env:ProgramFiles) | Where-Object { $_ }) {
        foreach ($d in 'Intel\Driver and Support Assistant', 'Intel\Intel Driver and Support Assistant', 'Intel Driver and Support Assistant') {
            foreach ($f in 'DSATray.exe', 'DSAService.exe', 'DSAServiceHelper.exe') { $x = Get-Item -LiteralPath (Join-Path (Join-Path $b $d) $f) -ErrorAction SilentlyContinue; if ($x) { return $x } }
        }
    }
    $svc = Get-CimInstance Win32_Service -Filter "Name LIKE 'DSAService%'" -ErrorAction SilentlyContinue | Select-Object -First 1
    if ($svc -and $svc.PathName) { $x = Get-Item -LiteralPath ($svc.PathName.Trim('"') -replace '"?\s+-.*$', '').Trim('"') -ErrorAction SilentlyContinue; if ($x) { return $x } }
    foreach ($k in 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*', 'HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*') {
        $u = Get-ItemProperty $k -ErrorAction SilentlyContinue | Where-Object { $_.DisplayName -match 'Intel.*Driver.*Support Assistant' } | Select-Object -First 1
        if ($u) { return [pscustomobject]@{ FullName = $null; Version = [string]$u.DisplayVersion; Dir = [string]$u.InstallLocation } }
    }
    return $null
}
function Invoke-IntelWirelessUpdate {
    $devs = @(Get-CimInstance Win32_PnPEntity -ErrorAction SilentlyContinue | Where-Object { $_.Manufacturer -match 'Intel' })
    $markFile = Join-Path $DataDir 'intel-pakete.json'
    $mark = @{}; try { $j = Get-Content -LiteralPath $markFile -Raw -ErrorAction Stop | ConvertFrom-Json; foreach ($p in $j.PSObject.Properties) { $mark[$p.Name] = [string]$p.Value } } catch { }
    foreach ($w in $IntelWireless) {
        if (Test-PCancel) { return }
        $d = @($devs | Where-Object $w.Device) | Select-Object -First 1
        if (-not $d) { Write-PLog ('   Intel {0}: kein Intel-Gerät vorhanden - übersprungen' -f $w.Kind); continue }
        Write-PLog ('   Intel {0}: {1}' -f $w.Kind, $d.Name)
        try { $i = Get-IntelDownloadInfo $w.PageId $w.Pattern } catch { Write-PLog ('   Intel-Download-Center: {0}' -f $_.Exception.Message) 'WARN'; continue }
        $arp = Get-ItemProperty 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*', 'HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*' -ErrorAction SilentlyContinue | Where-Object { $_.DisplayName -match $w.Arp } | Select-Object -First 1
        $have = if ($mark[$w.Kind]) { $mark[$w.Kind] } elseif ($arp) { [string]$arp.DisplayVersion } else { '' }
        $newer = $true; try { if ($have) { $newer = [version]$i.Version -gt [version](($have -split '\.')[0..2] -join '.') } } catch { }
        Write-PLog ('   Paket bei Intel: {0}{1}' -f $i.Version, $(if ($have) { ', installiert: ' + $have } else { '' }))
        if (-not $newer) { Write-PLog ('   Intel {0} ist aktuell.' -f $w.Kind) 'OK'; continue }
        if ($Script:CheckOnly) { Write-PLog ('   Update verfügbar: Intel {0} {1}' -f $w.Kind, $i.Version) 'WARN'; continue }
        $file = Join-Path (Join-Path $DataDir 'Downloads') $i.File
        try { Save-Download $i.Url $file ('Intel ' + $w.Kind + ' ' + $i.Version) } catch { Write-PLog ('   Download fehlgeschlagen: {0}' -f $_.Exception.Message) 'WARN'; continue }
        if ($i.Sha256 -and (Get-FileHash -LiteralPath $file -Algorithm SHA256).Hash -ne $i.Sha256) { Write-PLog '   Prüfsumme weicht von der Intel-Seite ab - nicht installiert.' 'FEHLER'; Remove-Item -LiteralPath $file -Force -ErrorAction SilentlyContinue; continue }
        $sig = Get-AuthenticodeSignature -FilePath $file
        if ($sig.Status -ne 'Valid' -or [string]$sig.SignerCertificate.Subject -notmatch 'Intel') { Write-PLog '   Signatur ungültig - nicht installiert.' 'FEHLER'; Remove-Item -LiteralPath $file -Force -ErrorAction SilentlyContinue; continue }
        $log = Join-Path (Join-Path $DataDir 'Logs') ('Intel_{0}_{1:yyyyMMdd_HHmm}.log' -f $w.Kind, (Get-Date))
        try { Invoke-DsBeforeDriverUpdate ('Intel ' + $w.Kind) } catch { }
        $Script:Detail = 'Intel {0} {1} wird installiert (Verbindung kann kurz abbrechen)' -f $w.Kind, $i.Version; Set-PStatus $Script:StatusText
        $rc = Invoke-External -Exe $file -Arguments @('-s', '-l', ('"{0}"' -f $log)) -TimeoutMin 30 -Quiet
        Remove-Item -LiteralPath $file -Force -ErrorAction SilentlyContinue
        switch ($rc) {
            { $_ -in 0, 3010, 350, 1641 } { Write-PLog ('   Intel {0} {1} installiert{2}.' -f $w.Kind, $i.Version, $(if ($rc) { ' - Neustart nötig' } else { '' })) 'OK'; $Script:UpdatesInstalled++; if ($rc) { $Script:RebootNeeded = $true }; $mark[$w.Kind] = $i.Version }
            default { Write-PLog ('   Intel {0}: Installer meldet Code {1} (1603 = allgemeiner Fehler, erst Windows-Updates und Neustart). Log: {2}' -f $w.Kind, $rc, $log) 'WARN' }
        }
    }
    try { [pscustomobject]$mark | ConvertTo-Json | Set-Content -LiteralPath $markFile -Encoding UTF8 } catch { }
}
function Invoke-IntelDsaInstall {
    if (Get-IntelDsaPath) { Write-PLog 'Intel Driver & Support Assistant ist bereits installiert.' 'OK'; return }
    $wg = Get-WingetPath
    if (-not $wg) { Write-PLog 'winget fehlt - Intel-Assistent bitte von intel.de laden.' 'WARN'; return }
    $rc = Invoke-External -Exe $wg -Arguments @('install', '--id', 'Intel.IntelDriverAndSupportAssistant', '-e', '--silent', '--accept-package-agreements', '--accept-source-agreements', '--disable-interactivity') -TimeoutMin 20 -Quiet
    if ((Get-IntelDsaPath) -or $rc -eq 0) { Write-PLog 'Intel Driver & Support Assistant: installiert' 'OK' }
    elseif ($rc -in -1978335189, -1978335135) { Write-PLog 'Intel Driver & Support Assistant: ist bereits installiert und aktuell (laut winget).' 'OK' }
    else { Write-PLog ('Intel Driver & Support Assistant: Installation meldet Code {0} - bitte von intel.de/dsa laden.' -f $rc) 'WARN' }
}

function Invoke-DriverBackup {
    $dir = Join-Path (Join-Path $DataDir 'Treiber-Sicherung') ('{0}_{1:yyyy-MM-dd_HHmm}' -f $env:COMPUTERNAME, (Get-Date))
    New-Item $dir -ItemType Directory -Force | Out-Null
    $Script:Detail = 'Alle installierten Treiber werden gesichert'; Set-PStatus $Script:StatusText
    $rc = Invoke-External -Exe (Join-Path $env:windir 'System32\pnputil.exe') -Arguments @('/export-driver', '*', ('"{0}"' -f $dir)) -TimeoutMin 30 -Quiet
    $n = @(Get-ChildItem -LiteralPath $dir -Filter *.inf -Recurse -ErrorAction SilentlyContinue).Count
    Write-PLog ('Treiber gesichert: {0} Pakete in {1}' -f $n, $dir) $(if ($rc -eq 0 -and $n) { 'OK' } else { 'WARN' })
    try { Write-DsManualManifest $dir } catch { }
    # nur die letzten 3 Sicherungen behalten
    Get-ChildItem -LiteralPath (Split-Path $dir) -Directory -ErrorAction SilentlyContinue | Where-Object { -not (Test-DsAutoSet $_.FullName) } | Sort-Object CreationTime -Descending | Select-Object -Skip 3 | Remove-Item -Recurse -Force -ErrorAction SilentlyContinue
}

# ---- Sicherheit: Virenschutz-Programme, Scans (laufen im Hintergrund über -Run)
