    @{ Key = 'Defender';    Name = 'Microsoft Defender';            Free = $true;  Ninite = '';            Winget = @();                           Url = 'windowsdefender://threat';                                    Desc = 'In Windows eingebaut, kostenlos, gute Testergebnisse. Mit den Einstellungen oben (Cloud-, PUA-, Netzwerk- und Ransomware-Schutz) für die meisten völlig ausreichend.' }
    @{ Key = 'BdFree';      Name = 'Bitdefender Antivirus Free';    Free = $true;  Ninite = '';            Winget = @('Bitdefender.Bitdefender');  Url = 'https://www.bitdefender.de/solutions/free.html';               Desc = 'Sehr hohe Erkennungsrate bei geringer Last, kaum Werbung.' }
    @{ Key = 'Avast';       Name = 'Avast Free Antivirus';          Free = $true;  Ninite = 'Avast';       Winget = @();                           Url = 'https://www.avast.com/de-de/free-antivirus-download';          Desc = 'Umfangreich, mit WLAN-Prüfung und Browser-Schutz; blendet Hinweise auf die Bezahlversion ein.' }
