    @{ Key = 'Panda';       Name = 'Panda Dome Free';               Free = $true;  Ninite = '';            Winget = @();                           Url = 'https://www.pandasecurity.com/de/homeusers/free-antivirus/';  Desc = 'Cloud-basierter Schutz, sehr leicht und schnell, gute Erkennung; mit USB-Schutz und Rettungs-Stick.'
       Pages = @('https://www.pandasecurity.com/de/homeusers/free-antivirus/', 'https://www.pandasecurity.com/en/homeusers/downloads/', 'https://www.pandasecurity.com/en/homeusers/free-antivirus/'); Pattern = 'https?://[^"''\s<>]*panda[^"''\s<>]*\.exe'; Signer = 'Panda|WatchGuard' }
    @{ Key = 'Sophos';      Name = 'Sophos Home Free';              Free = $true;  Ninite = '';            Winget = @('Sophos.SophosHome');        Url = 'https://home.sophos.com/de';                                   Desc = 'Firmen-Technik für zu Hause, Verwaltung über ein Online-Konto (bis 3 Geräte).' }
