    @{ Key = 'Eset';        Name = 'ESET HOME Security';            Free = $false; Ninite = '';            Winget = @();                           Url = 'https://www.eset.com/de/home/';                                Desc = 'Sehr ressourcenschonend, beliebt bei Technikern; Premium mit Passwort-Manager und Verschlüsselung.' }
    @{ Key = 'Gdata';       Name = 'G DATA Total Security';         Free = $false; Ninite = '';            Winget = @();                           Url = 'https://www.gdata.de/total-security';                          Desc = 'Made in Germany (Bochum), deutscher Support und Datenschutz, Backup und Passwort-Manager inklusive.' }
    @{ Key = 'Norton';      Name = 'Norton 360 Deluxe';             Free = $false; Ninite = '';            Winget = @();                           Url = 'https://de.norton.com/products/norton-360-deluxe';             Desc = 'Rundum-Paket mit VPN, Cloud-Backup, Passwort-Manager und Dark-Web-Überwachung.' }
