    @{ Key = 'MwbPremium';  Name = 'Malwarebytes Premium';          Free = $false; Ninite = '';            Winget = @('Malwarebytes.Malwarebytes'); Url = 'https://www.malwarebytes.com/de/premium';                  Desc = 'Echtzeitschutz und Exploit-Schutz, verträgt sich mit Defender.' }
