function Invoke-AvInstall {
    $p = $AvProducts | Where-Object { $_.Key -eq [string]$Script:JobOpts.Product } | Select-Object -First 1
    if (-not $p) { Write-PLog 'Unbekanntes Produkt' 'WARN'; return }
    Write-PLog ('Virenschutz: {0}' -f $p.Name)
    $other = @(Get-CimInstance -Namespace root/SecurityCenter2 -ClassName AntiVirusProduct -ErrorAction SilentlyContinue | Where-Object { $_.displayName -notmatch 'Defender' } | ForEach-Object { $_.displayName })
    if ($other.Count -and $p.Key -notin 'Mwb', 'MwbPremium') { Write-PLog ('   Achtung: bereits installiert: {0} - zwei Virenscanner gleichzeitig bremsen den PC und stören sich. Den alten vorher deinstallieren.' -f ($other -join ', ')) 'WARN' }
    if ($p.Ninite) {
        $Script:NiniteApps = @($p.Ninite); Invoke-NiniteInstall
        return
    }
    if ($p.Pages) {
        # Hersteller-Installer von der offiziellen Seite, Signatur prüfen, dann (mit Oberfläche des Herstellers) starten
        $ua = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/140.0.0.0 Safari/537.36'
        $url = $null
        foreach ($pg in $p.Pages) { try { $h = (Invoke-WebRequest -Uri $pg -UseBasicParsing -TimeoutSec 30 -UserAgent $ua).Content; $m = [regex]::Match($h, $p.Pattern, 'IgnoreCase'); if ($m.Success) { $url = $m.Value; break } } catch { } }
        if ($url) {
            $f = Join-Path (Join-Path $DataDir 'Downloads') ([IO.Path]::GetFileName(([uri]$url).AbsolutePath))
            try {
                Save-Download $url $f $p.Name
                $sig = Get-AuthenticodeSignature -FilePath $f
                if ($sig.Status -eq 'Valid' -and [string]$sig.SignerCertificate.Subject -match $p.Signer) {
                    Write-PLog ('   Installer geladen und Signatur geprüft ({0}) - die Installation von {1} öffnet sich jetzt, bitte dort durchklicken.' -f $sig.SignerCertificate.Subject, $p.Name) 'OK'
                    Start-Process -FilePath $f; return
                }
                Write-PLog ('   Signatur passt nicht ({0}) - nicht gestartet.' -f $sig.Status) 'WARN'; Remove-Item -LiteralPath $f -Force -ErrorAction SilentlyContinue
            } catch { Write-PLog ('   Download: {0}' -f $_.Exception.Message) 'WARN' }
        }
    }
    $wg = Get-WingetPath
    foreach ($id in @($p.Winget)) {
        if (-not $wg) { break }
        $null = Invoke-External -Exe $wg -Arguments @('show', '--id', $id, '--exact', '--accept-source-agreements', '--disable-interactivity') -TimeoutMin 3 -Capture
        if (-not ($Script:Captured | Where-Object { $_ -match [regex]::Escape($id) })) { continue }
        $code = Invoke-External -Exe $wg -Arguments @('install', '--id', $id, '--exact', '--accept-source-agreements', '--accept-package-agreements', '--disable-interactivity', '--silent') -TimeoutMin 30
        if ($code -in 0, -1978335189, -1978335135) { Write-PLog ('   {0} installiert. Einrichtung/Anmeldung im Programm abschließen.' -f $p.Name) 'OK'; return }
        Write-PLog ('   winget {0}: Code 0x{1:X8}' -f $id, $code) 'WARN'
    }
    Write-PLog ('   Kein stiller Installer verfügbar - die Hersteller-Seite wird geöffnet: {0}' -f $p.Url)
    try { Start-Process $p.Url } catch { }
}
function Invoke-DefenderScan {
    $t = [string]$Script:JobOpts.ScanType
    switch ($t) {
        'Offline' { Write-PLog 'Microsoft Defender Offline-Überprüfung: der PC startet jetzt neu und prüft vor dem Windows-Start (ca. 15 Minuten).' 'WARN'; Start-MpWDOScan; return }
        'Safety'  {
            $f = Join-Path (Join-Path $DataDir 'Downloads') 'msert.exe'
            Save-Download 'https://go.microsoft.com/fwlink/?LinkId=212732' $f 'Microsoft Safety Scanner'
            $sig = Get-AuthenticodeSignature -FilePath $f
            if ($sig.Status -ne 'Valid' -or [string]$sig.SignerCertificate.Subject -notmatch 'Microsoft') { Write-PLog 'Safety Scanner nicht gültig signiert - abgebrochen.' 'FEHLER'; return }
            $Script:Detail = 'Microsoft Safety Scanner prüft den ganzen PC (30-90 Minuten)'; Set-PStatus $Script:StatusText
            $rc = Invoke-External -Exe $f -Arguments @('/Q', '/F:Y') -TimeoutMin 240 -Quiet
            $log = Join-Path $env:windir 'debug\msert.log'
            $sum = if (Test-Path $log) { @(Get-Content $log -Tail 12) -join ' | ' } else { '' }
            Write-PLog ('Safety Scanner fertig (Code {0}). {1}' -f $rc, $sum) $(if ($rc -eq 0) { 'OK' } else { 'WARN' })
            Remove-Item -LiteralPath $f -Force -ErrorAction SilentlyContinue
            return
        }
        default {
            $type = if ($t -eq 'Full') { 'FullScan' } else { 'QuickScan' }
            try { Update-MpSignature -ErrorAction SilentlyContinue } catch { }
            $Script:Detail = 'Defender {0} läuft' -f $(if ($type -eq 'FullScan') { 'Vollprüfung (kann Stunden dauern)' } else { 'Schnellprüfung' }); Set-PStatus $Script:StatusText
            $before = @(Get-MpThreatDetection -ErrorAction SilentlyContinue).Count
            Start-MpScan -ScanType $type -ErrorAction Stop
            $new = @(Get-MpThreatDetection -ErrorAction SilentlyContinue).Count - $before
            if ($new -gt 0) { Write-PLog ('Defender hat {0} Bedrohung(en) gefunden und behandelt - Details: Seite Sicherheit > Bedrohungsverlauf.' -f $new) 'WARN' } else { Write-PLog 'Defender-Prüfung fertig - nichts gefunden.' 'OK' }
        }
    }
}

# ---- Zustand (Ampel), Meine PCs, Benachrichtigungen, Verlauf, Vorher/Nachher (Oberfläche und Hintergrund)
function Get-HealthItems($a) {
    $r = [System.Collections.Generic.List[object]]::new()
    function A([string]$L, [string]$T, [string]$D, [string]$Act, [string]$Btn) { $r.Add([pscustomobject]@{ Level = $L; Text = $T; Detail = $D; Action = $Act; Button = $Btn }) }
    $os = Get-CimInstance Win32_OperatingSystem
    $pend = (Test-Path 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Component Based Servicing\RebootPending') -or (Test-Path 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\WindowsUpdate\Auto Update\RebootRequired')
    $up = ((Get-Date) - $os.LastBootUpTime).TotalDays
    if ($pend) { A 'Yellow' 'Neustart ausstehend' 'Updates werden erst nach einem Neustart fertig installiert.' 'Restart' 'Neu starten' }
    elseif ($up -gt 14) { A 'Yellow' ('Seit {0} Tagen nicht neu gestartet' -f [int]$up) 'Ein Neustart macht Windows wieder frisch und schließt Updates ab.' 'Restart' 'Neu starten' }
    $d = New-Object IO.DriveInfo $env:SystemDrive; $pct = $d.AvailableFreeSpace * 100 / $d.TotalSize; $gb = $d.AvailableFreeSpace / 1GB
    if ($pct -lt 8 -or $gb -lt 10) { A 'Red' ('Laufwerk C: fast voll ({0:N1} GB frei)' -f $gb) 'Ohne freien Platz scheitern Updates und Windows wird langsam.' 'Space' 'Speicher prüfen' }
    elseif ($pct -lt 15) { A 'Yellow' ('Laufwerk C: wird knapp ({0:N0} GB frei)' -f $gb) 'Bald aufräumen oder große Dateien auslagern.' 'Space' 'Speicher prüfen' }
    foreach ($pd in @(Get-PhysicalDisk -ErrorAction SilentlyContinue | Where-Object { [string]$_.HealthStatus -ne 'Healthy' })) { A 'Red' ('Datenträger meldet Probleme: {0}' -f $pd.FriendlyName) 'Sofort eine Datensicherung machen und das Laufwerk tauschen.' 'Backup' 'Jetzt sichern' }
    $av = @(Get-CimInstance -Namespace root/SecurityCenter2 -ClassName AntiVirusProduct -ErrorAction SilentlyContinue | Where-Object { (([int]$_.productState -shr 12) -band 0xF) -in 1, 3 })
    $avOn = [bool]$av.Count; if (-not $avOn) { try { $avOn = (Get-MpComputerStatus -ErrorAction Stop).RealTimeProtectionEnabled } catch { } }
    if (-not $avOn) { A 'Red' 'Kein Virenschutz aktiv' 'Der PC ist ungeschützt gegen Schadsoftware.' 'Security' 'Sicherheit' }
    $fwOff = @(Get-NetFirewallProfile -ErrorAction SilentlyContinue | Where-Object { [string]$_.Enabled -ne 'True' })
    if ($fwOff.Count) { A 'Red' ('Firewall aus ({0})' -f (($fwOff | ForEach-Object { $_.Name }) -join ', ')) 'Andere Geräte im Netzwerk können direkt auf den PC zugreifen.' 'Security' 'Sicherheit' }
    try { $mp = Get-MpComputerStatus -ErrorAction Stop; if ($mp.AntivirusEnabled -and $mp.AntivirusSignatureAge -gt 7) { A 'Yellow' ('Virendefinitionen {0} Tage alt' -f $mp.AntivirusSignatureAge) 'Neue Schädlinge werden nicht erkannt.' 'Updates' 'Updates' } } catch { }
    $last = $null; try { $last = (Get-HotFix -ErrorAction Stop | Where-Object InstalledOn | Sort-Object InstalledOn -Descending | Select-Object -First 1).InstalledOn } catch { }
    if ($last) { $age = ((Get-Date) - $last).TotalDays; if ($age -gt 90) { A 'Red' ('Seit {0} Tagen keine Windows-Updates' -f [int]$age) 'Sicherheitslücken bleiben offen.' 'Updates' 'Updates' } elseif ($age -gt 45) { A 'Yellow' ('Letztes Windows-Update vor {0} Tagen' -f [int]$age) 'Updates installieren.' 'Updates' 'Updates' } }
    $bs = @(Get-WinEvent -FilterHashtable @{ LogName = 'System'; ProviderName = 'Microsoft-Windows-WER-SystemErrorReporting'; Id = 1001; StartTime = (Get-Date).AddDays(-7) } -ErrorAction SilentlyContinue).Count
    if ($bs) { A 'Red' ('{0} Bluescreen(s) in den letzten 7 Tagen' -f $bs) 'Die Fehlersuche findet Ursache und passende Reparatur.' 'Repair' 'Fehlersuche' }
    $dev = @(Get-CimInstance Win32_PnPEntity -ErrorAction SilentlyContinue | Where-Object { $_.ConfigManagerErrorCode -and $_.ConfigManagerErrorCode -ne 22 -and -not ($_.ConfigManagerErrorCode -eq 24 -and ([string]$_.DeviceID -match '^ACPI\\(PNP03|PNP0F|HPQ8001|MSF0001)' -or [string]$_.Name -match 'PS/2')) -and (@((Get-ItemProperty 'HKLM:\SOFTWARE\PCPflege' -Name DevIgnore -ErrorAction SilentlyContinue).DevIgnore) -notcontains [string]$_.DeviceID) }).Count
    if ($dev) { A 'Yellow' ('{0} Gerät(e) ohne funktionierenden Treiber' -f $dev) 'Auf der Seite Treiber aktualisieren.' 'Drivers' 'Treiber' }
    $lrD = $null; try { $lrD = [datetime]::ParseExact(([string]$a.LastRun -split ' ')[0], 'dd.MM.yyyy', $null) } catch { }
    if (-not $lrD) { A 'Yellow' 'Noch keine Pflege durchgeführt' 'Einmal "Alles jetzt ausführen" - danach übernimmt der Zeitplan.' 'RunAll' 'Jetzt pflegen' }
    elseif (((Get-Date) - $lrD).TotalDays -gt 30) { A 'Yellow' ('Letzte Pflege vor {0} Tagen' -f [int]((Get-Date) - $lrD).TotalDays) 'Aufräumen und Updates sind überfällig.' 'RunAll' 'Jetzt pflegen' }
    if (-not $a.Sched) { A 'Yellow' 'Automatische Pflege ist aus' 'Mit dem Zeitplan läuft alles von selbst - oder gleich den Sorgenfrei-Modus einschalten.' 'Sched' 'Zeitplan' }
    # Fehlende Datensicherung ist kein Ampel-Problem mehr (nur Empfehlung auf der Seite Datensicherung). Eine veraltete Sicherung bleibt ein Hinweis.
    if ($a.BackupTarget -and $a.BackupLast -and ((Get-Date) - [datetime]$a.BackupLast).TotalDays -gt 14) { A 'Yellow' ('Letzte Datensicherung vor {0} Tagen' -f [int]((Get-Date) - [datetime]$a.BackupLast).TotalDays) 'Die Sicherung ist nicht mehr aktuell.' 'Backup' 'Sichern' }
    if ($a.FbOn) {
        $fbD = $null; try { if ($a.FbLast) { $fbD = [datetime]$a.FbLast } } catch { }
        if (-not $fbD) { A 'Yellow' 'Noch keine Komplettsicherung' 'Ein Systemabbild bringt nach einem Festplattenschaden den ganzen PC in einer Stunde zurück.' 'FullBackup' 'Komplettsicherung' }
        elseif (((Get-Date) - $fbD).TotalDays -gt ([int]$a.FbDays + 2)) { A 'Yellow' ('Letzte Komplettsicherung vor {0} Tagen' -f [int]((Get-Date) - $fbD).TotalDays) ('Geplant ist alle {0} Tage - Sicherungsfestplatte angeschlossen bzw. NAS erreichbar?' -f [int]$a.FbDays) 'FullBackup' 'Komplettsicherung' }
        if ($a.FbFail) { A 'Yellow' 'Letzte Komplettsicherung fehlgeschlagen' ([string]$a.FbFailMsg) 'FullBackup' 'Details' }
    }
    try { $des = @(Get-CimInstance -Namespace root\wmi -ClassName BatteryStaticData -ErrorAction Stop)[0].DesignedCapacity; $full = @(Get-CimInstance -Namespace root\wmi -ClassName BatteryFullChargedCapacity -ErrorAction Stop)[0].FullChargedCapacity
          if ($des -and $full -and ($full * 100 / $des) -lt 60) { A 'Yellow' ('Akku nur noch {0:N0} % der Originalkapazität' -f ($full * 100 / $des)) 'Akkutausch einplanen.' 'Health' 'Gerätezustand' } } catch { }
    if ($a.Warranty) { try { $we = [datetime]$a.Warranty; $dd = ($we - (Get-Date)).TotalDays; if ($dd -gt 0 -and $dd -lt 60) { A 'Yellow' ('Garantie endet am {0:dd.MM.yyyy}' -f $we) 'Mängel jetzt noch kostenlos reparieren lassen (Akku, Tasten, Display, Lüfter).' 'Bios' 'Garantie' } } catch { } }
    # Funktionsupdate-Blocker (schnell: liest nur die letzte Setup-Scan-Datei des letzten Upgrade-Versuchs)
    try {
        $pan = ''
        foreach ($c in @((Join-Path $env:SystemDrive '$WINDOWS.~BT\Sources\Panther'), (Join-Path $env:SystemDrive '$WINDOWS.~WS\Sources\Panther'))) { if (Test-Path -LiteralPath $c) { $pan = $c; break } }
        if ($pan) {
            $sr = @(Get-ChildItem -LiteralPath $pan -Filter 'ScanResult.xml' -ErrorAction SilentlyContinue | Sort-Object LastWriteTime | Select-Object -Last 1)
            if ($sr.Count) {
                $raw = ''; try { $raw = Get-Content -LiteralPath $sr[0].FullName -Raw -ErrorAction Stop } catch { }
                $blk = @(); foreach ($m in [regex]::Matches($raw, '<Program\s+Name="([^"]+)"[^>]*>\s*<CompatibilityInfo\s+BlockingType="Hard"')) { $blk += $m.Groups[1].Value }
                $blk = @($blk | Select-Object -Unique)
                if ($blk.Count) { A 'Yellow' ('Funktionsupdate blockiert: {0}' -f ($blk -join ', ')) 'Diese Programme verhindern das nächste große Windows-Update. Der Windows-Update-Doktor nennt und löst den Blocker.' 'WinRepair' 'Windows-Reparatur' }
            }
        }
    } catch { }
    return , $r
}
function Get-HealthArgs {
    $cfg = $null; try { $cfg = Read-PflegeConfig } catch { }
    $lr = $null; $lrFile = Join-Path $DataDir 'lastrun.json'; if (Test-Path $lrFile) { try { $lr = Get-Content $lrFile -Raw -Encoding UTF8 | ConvertFrom-Json } catch { } }
    $bl = $null; foreach ($f in @(Get-ChildItem (Join-Path $DataDir 'Logs') -Filter 'PCPflege_*.log' -ErrorAction SilentlyContinue | Sort-Object LastWriteTime -Descending | Select-Object -First 40)) { if (Select-String -LiteralPath $f.FullName -Pattern 'Sicherung fertig|Datensicherung abgeschlossen' -Quiet -ErrorAction SilentlyContinue) { $bl = $f.LastWriteTime.ToString('o'); break } }
    $fbA = @{}; try { $fbA = Get-FbHealthArgs $cfg } catch { }
    $fbA + @{ BackupTarget = $(if ($cfg) { [string]$cfg.Backup.Target } else { '' }); BackupLast = $bl; LastRun = $(if ($lr) { [string]$lr.Zeit } else { '' }); Sched = [bool](Get-ScheduledTask -TaskName $TaskName -ErrorAction SilentlyContinue); Warranty = $(try { [string](Get-Content (Join-Path $DataDir 'garantie.json') -Raw -Encoding UTF8 | ConvertFrom-Json).End } catch { '' }) }
}
function Get-HealthState($Items) { if (@($Items | Where-Object Level -eq 'Red').Count) { 'Red' } elseif (@($Items | Where-Object Level -eq 'Yellow').Count) { 'Yellow' } else { 'Green' } }
function Write-FleetStatus($Items, [int]$SecScore = -1) {
    $cfg = Read-PflegeConfig
    if (-not $cfg.Fleet.Enabled -or -not $cfg.Fleet.Dir) { return }
    $dir = [string]$cfg.Fleet.Dir
    Connect-BackupTarget $dir
    New-Item $dir -ItemType Directory -Force -ErrorAction Stop | Out-Null
    $os = Get-CimInstance Win32_OperatingSystem; $cs = Get-CimInstance Win32_ComputerSystem
    $reg = Get-ItemProperty 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion'
    $d = New-Object IO.DriveInfo $env:SystemDrive
    $lr = $null; $lrFile = Join-Path $DataDir 'lastrun.json'; if (Test-Path $lrFile) { try { $lr = Get-Content $lrFile -Raw -Encoding UTF8 | ConvertFrom-Json } catch { } }
    $old = $null; $f = Join-Path $dir ('{0}.json' -f $env:COMPUTERNAME); if (Test-Path -LiteralPath $f) { try { $old = Get-Content -LiteralPath $f -Raw -Encoding UTF8 | ConvertFrom-Json } catch { } }
    $ip = @(Get-NetIPAddress -AddressFamily IPv4 -ErrorAction SilentlyContinue | Where-Object { $_.IPAddress -notlike '127.*' -and $_.IPAddress -notlike '169.254*' } | ForEach-Object { $_.IPAddress })
    [pscustomobject]@{
        Computer = $env:COMPUTERNAME; User = [string]$cs.UserName; Time = (Get-Date).ToString('o'); Version = $AppVersion
        Model = ('{0} {1}' -f $cs.Manufacturer, $cs.Model); Windows = ('{0} {1} (Build {2}.{3})' -f $os.Caption, $reg.DisplayVersion, $reg.CurrentBuild, $reg.UBR)
        State = (Get-HealthState $Items); Items = @($Items | Select-Object Level, Text, Detail)
        SecScore = $(if ($SecScore -ge 0) { $SecScore } elseif ($old) { [int]$old.SecScore } else { -1 })
        DiskFreeGB = [math]::Round($d.AvailableFreeSpace / 1GB, 1); DiskTotalGB = [math]::Round($d.TotalSize / 1GB, 0)
        LastRun = $(if ($lr) { [string]$lr.Zeit } else { '' }); Uptime = [math]::Round(((Get-Date) - $os.LastBootUpTime).TotalDays, 1)
        IP = ($ip -join ', '); Warranty = $(try { [string](Get-Content (Join-Path $DataDir 'garantie.json') -Raw -Encoding UTF8 | ConvertFrom-Json).End } catch { '' }); Remote = [bool]$cfg.Fleet.Remote
        Akte = $(try { Get-AkFleetInfo } catch { $null })
        FullBackup = $(try { Get-FbFleetInfo } catch { $null })
    } | ForEach-Object { Add-FdStatusFields $_ $old $dir $SecScore } | ConvertTo-Json -Depth 5 | Set-Content -LiteralPath ($f + '.tmp') -Encoding UTF8
    Move-Item -LiteralPath ($f + '.tmp') -Destination $f -Force
}
# ---- Hilfe anfordern (14.2): Bericht mit Score, Problemen, Fehlern und Protokoll an den Helfer
function New-HelpReport([string]$Msg = '', $Score = $null) {
    $os = Get-CimInstance Win32_OperatingSystem; $cs = Get-CimInstance Win32_ComputerSystem
    $reg = Get-ItemProperty 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion'
    $d = New-Object IO.DriveInfo $env:SystemDrive
    $items = @(); try { $items = @(Get-HealthItems (Get-HealthArgs) | ForEach-Object { $_ } | Where-Object { $_ -and [string]$_.Level -in 'Red', 'Yellow' } | ForEach-Object { [pscustomobject]@{ Level = [string]$_.Level; Text = [string]$_.Text; Detail = [string]$_.Detail } }) } catch { }
    $sv = -1; $grade = ''; $comps = @()
    if ($Score) {
        try { $sv = [int]$Score.Score } catch { }; $grade = [string]$Score.Grade
        $comps = @(@($Score.Components) | Where-Object { $_ -and [double]$_.Max -gt 0 -and [double]$_.Points -lt [double]$_.Max } | ForEach-Object { [pscustomobject]@{ Name = [string]$_.Name; Points = ('{0:N0}/{1:N0}' -f [double]$_.Points, [double]$_.Max); Reason = [string]$_.Reason } })
    }
    $ev = @(); try { $ev = @(Get-WinEvent -FilterHashtable @{ LogName = 'System'; Level = 1, 2; StartTime = (Get-Date).AddDays(-3) } -MaxEvents 15 -ErrorAction Stop | ForEach-Object { $m = (([string]$_.Message) -split "`r?`n")[0]; if ($m.Length -gt 180) { $m = $m.Substring(0, 180) + ' ...' }; '{0:dd.MM. HH:mm}  {1} ({2}): {3}' -f $_.TimeCreated, $_.ProviderName, $_.Id, $m }) } catch { }
    $log = @(); $logName = ''
    try { $lf = @(Get-ChildItem -LiteralPath (Join-Path $DataDir 'Logs') -Filter '*.log' -File -ErrorAction Stop | Where-Object { $_.Name -ne 'Update-Verlauf.log' } | Sort-Object LastWriteTime -Descending)[0]; if ($lf) { $logName = $lf.Name; $log = @(Get-Content -LiteralPath $lf.FullName -Tail 60 -Encoding UTF8 -ErrorAction Stop) } } catch { }
    [pscustomobject]@{
        Schema = 1; Computer = $env:COMPUTERNAME; User = [string]$cs.UserName; Time = (Get-Date).ToString('o'); Version = $AppVersion; Message = $Msg; Status = 'offen'
        Model = ('{0} {1}' -f $cs.Manufacturer, $cs.Model).Trim(); Windows = ('{0} {1} (Build {2}.{3})' -f $os.Caption, $reg.DisplayVersion, $reg.CurrentBuild, $reg.UBR)
        DiskFreeGB = [math]::Round($d.AvailableFreeSpace / 1GB, 1); UptimeDays = [math]::Round(((Get-Date) - $os.LastBootUpTime).TotalDays, 1)
        Score = $sv; Grade = $grade; Components = $comps; Items = $items; Events = $ev; LogName = $logName; Log = $log
    }
}
function Format-HelpReportText($R) {
    $sb = [System.Text.StringBuilder]::new()
    $t = try { ([datetime]$R.Time).ToString('dd.MM.yyyy HH:mm') } catch { [string]$R.Time }
    [void]$sb.AppendLine(('PC-Tools - Hilfe angefordert von {0} ({1})' -f $R.Computer, $R.User))
    [void]$sb.AppendLine(('Zeit: {0}  ·  PC-Tools {1}' -f $t, $R.Version))
    [void]$sb.AppendLine(('PC: {0}  ·  {1}' -f $R.Model, $R.Windows))
    [void]$sb.AppendLine(('C: frei: {0} GB  ·  läuft seit {1} Tagen' -f $R.DiskFreeGB, $R.UptimeDays))
    [void]$sb.AppendLine('')
    [void]$sb.AppendLine('Nachricht:'); [void]$sb.AppendLine($(if ([string]$R.Message) { [string]$R.Message } else { '(keine)' })); [void]$sb.AppendLine('')
    if ([int]$R.Score -ge 0) { [void]$sb.AppendLine(('Zustands-Score: {0} von 100 ({1})' -f $R.Score, $R.Grade)); foreach ($c in @($R.Components)) { if ($c) { [void]$sb.AppendLine(('  - {0}: {1} - {2}' -f $c.Name, $c.Points, $c.Reason)) } }; [void]$sb.AppendLine('') }
    [void]$sb.AppendLine('Probleme:'); $it = @(@($R.Items) | Where-Object { $_ }); if ($it.Count) { foreach ($i in $it) { [void]$sb.AppendLine(('  [{0}] {1} - {2}' -f $(if ($i.Level -eq 'Red') { 'dringend' } else { 'Hinweis' }), $i.Text, $i.Detail)) } } else { [void]$sb.AppendLine('  keine') }; [void]$sb.AppendLine('')
    [void]$sb.AppendLine('Fehler im System-Protokoll (3 Tage):'); $ev = @(@($R.Events) | Where-Object { $_ }); if ($ev.Count) { foreach ($e in $ev) { [void]$sb.AppendLine('  ' + $e) } } else { [void]$sb.AppendLine('  keine') }; [void]$sb.AppendLine('')
    if (@($R.Log).Count) { [void]$sb.AppendLine(('Letzte Zeilen aus {0}:' -f $R.LogName)); foreach ($l in @($R.Log)) { [void]$sb.AppendLine('  ' + [string]$l) } }
    $sb.ToString()
}
function Send-HelpRequest($R) {
    $res = [System.Collections.Generic.List[string]]::new()
    $stamp = (Get-Date).ToString('yyyyMMdd-HHmmss')
    $loc = Join-Path $DataDir 'Hilfe'; New-Item $loc -ItemType Directory -Force -ErrorAction SilentlyContinue | Out-Null
    $txt = Join-Path $loc ('Hilfe_{0}.txt' -f $stamp)
    Set-Content -LiteralPath $txt -Value (Format-HelpReportText $R) -Encoding UTF8
    $R | ConvertTo-Json -Depth 5 | Set-Content -LiteralPath ([IO.Path]::ChangeExtension($txt, '.json')) -Encoding UTF8
    $fleet = $false; $notified = $false
    $cfg = Read-PflegeConfig
    if ($cfg.Fleet.Enabled -and [string]$cfg.Fleet.Dir) {
        try {
            $dir = [string]$cfg.Fleet.Dir; Connect-BackupTarget $dir
            $hd = Join-Path $dir 'Hilfe'; New-Item $hd -ItemType Directory -Force -ErrorAction Stop | Out-Null
            $f = Join-Path $hd ('{0}_{1}.json' -f $env:COMPUTERNAME, $stamp)
            $R | ConvertTo-Json -Depth 5 | Set-Content -LiteralPath ($f + '.tmp') -Encoding UTF8; Move-Item -LiteralPath ($f + '.tmp') -Destination $f -Force
            $fleet = $true; $res.Add('Meine PCs: Hilferuf abgelegt')
            try { Write-FleetStatus @(Get-HealthItems (Get-HealthArgs) | ForEach-Object { $_ }) } catch { }
        } catch { $res.Add('Meine PCs: ' + $_.Exception.Message) }
    }
    try {
        $short = @(); if ([string]$R.Message) { $short += [string]$R.Message }
        if ([int]$R.Score -ge 0) { $short += ('Score {0}/100' -f $R.Score) }
        $short += @(@($R.Items) | Where-Object { $_ } | Select-Object -First 4 | ForEach-Object { '- ' + $_.Text })
        if ($fleet) { $short += 'Bericht unter Meine PCs > Hilferufe.' }
        $nr = @(Send-PflegeNotify 'Hilfe angefordert' ($short -join "`n") 'Red' -Force)
        $notified = [bool]@($nr | Where-Object { $_ -match ': OK$' }).Count
        foreach ($x in $nr) { $res.Add([string]$x) }
    } catch { }
    [pscustomobject]@{ TxtFile = $txt; Fleet = $fleet; Notified = $notified; Results = $res.ToArray(); Text = (Format-HelpReportText $R) }
}
function Read-FdHelpRequests([string]$Dir) {
    $out = @{}
    foreach ($fi in @(Get-ChildItem -LiteralPath (Join-Path $Dir 'Hilfe') -Filter '*.json' -File -ErrorAction SilentlyContinue | Sort-Object Name)) {
        try { $o = Get-Content -LiteralPath $fi.FullName -Raw -Encoding UTF8 -ErrorAction Stop | ConvertFrom-Json } catch { continue }
        if (-not $o -or -not [string]$o.Computer -or [string]$o.Status -eq 'erledigt') { continue }
        $o | Add-Member -NotePropertyName File -NotePropertyValue $fi.FullName -Force
        $out[([string]$o.Computer).ToUpper()] = $o
    }
    $out
}
function Send-PflegeNotify([string]$Title, [string]$Text, [string]$Level = 'Info', [switch]$Force) {
    $cfg = Read-PflegeConfig; $n = $cfg.Notify
    if (-not $Force -and -not $n.Enabled) { return @() }
    try { [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12 } catch { }
    $res = @(); $full = '{0} - {1}' -f $env:COMPUTERNAME, $Title
    $utf = [Text.Encoding]::UTF8
    if ($n.Ntfy) {
        try {
            $h = @{ Title = [Convert]::ToBase64String($utf.GetBytes($full)) -replace '^', '=?UTF-8?B?' -replace '$', '?='; Priority = $(switch ($Level) { 'Red' { '5' } 'Yellow' { '4' } default { '3' } }); Tags = $(switch ($Level) { 'Red' { 'rotating_light' } 'Yellow' { 'warning' } 'Green' { 'white_check_mark' } default { 'computer' } }) }
            Invoke-RestMethod -Uri ([string]$n.Ntfy) -Method Post -Body $utf.GetBytes($Text) -Headers $h -ContentType 'text/plain; charset=utf-8' -TimeoutSec 15 | Out-Null; $res += 'ntfy: OK'
        } catch { $res += 'ntfy: ' + $_.Exception.Message }
    }
    if ($n.HaWebhook) {
        try { $b = @{ title = $full; message = $Text; level = $Level; computer = $env:COMPUTERNAME } | ConvertTo-Json; Invoke-RestMethod -Uri ([string]$n.HaWebhook) -Method Post -Body $utf.GetBytes($b) -ContentType 'application/json; charset=utf-8' -TimeoutSec 15 | Out-Null; $res += 'Home Assistant: OK' } catch { $res += 'Home Assistant: ' + $_.Exception.Message }
    }
    if ($n.ChatWebhook) {
        try { $icon = switch ($Level) { 'Red' { ':red_circle:' } 'Yellow' { ':large_orange_circle:' } 'Green' { ':large_green_circle:' } default { ':computer:' } }
              $b = @{ text = ("{0} **{1}**`n{2}" -f $icon, $full, $Text); username = 'PC-Tools' } | ConvertTo-Json; Invoke-RestMethod -Uri ([string]$n.ChatWebhook) -Method Post -Body $utf.GetBytes($b) -ContentType 'application/json; charset=utf-8' -TimeoutSec 15 | Out-Null; $res += 'Chat: OK' } catch { $res += 'Chat: ' + $_.Exception.Message }
    }
    return $res
}
function Invoke-NotifyCheck($Items, $Run) {
    $cfg = Read-PflegeConfig; $n = $cfg.Notify
    if (-not $n.Enabled) { return }
    $stFile = Join-Path $DataDir 'benachrichtigung.json'
    $st = @{}; try { $j = Get-Content $stFile -Raw -ErrorAction Stop | ConvertFrom-Json; foreach ($p in $j.PSObject.Properties) { $st[$p.Name] = $p.Value } } catch { }
    $state = Get-HealthState $Items
    $key = (@($Items | Where-Object { $_.Level -eq 'Red' } | ForEach-Object { $_.Text }) -join '|')
    if ($n.OnRed -and $state -eq 'Red' -and $st.RedKey -ne $key) { $null = Send-PflegeNotify 'Dringend' ((@($Items | Where-Object Level -eq 'Red') | ForEach-Object { '- ' + $_.Text }) -join "`n") 'Red' }
    if ($n.OnRecover -and $state -ne 'Red' -and $st.LastState -eq 'Red') { $null = Send-PflegeNotify 'Wieder in Ordnung' 'Keine dringenden Probleme mehr.' 'Green' }
    if ($Run -and $n.OnWarn -and [int]$Run.Warnungen -gt 0) { $null = Send-PflegeNotify ('Pflege mit {0} Warnung(en)' -f $Run.Warnungen) ('Teile: {0}. Details im Protokoll: {1}' -f $Run.Teile, $Run.Log) 'Yellow' }
    if ($Run -and $n.OnBackup -and [string]$Run.Teile -match 'Backup' -and [int]$Run.Warnungen -gt 0) { $null = Send-PflegeNotify 'Datensicherung mit Fehlern' 'Die Sicherung hat nicht alles geschafft - Protokoll prüfen.' 'Red' }
    if ($n.OnBluescreen) {
        $bs = @(Get-WinEvent -FilterHashtable @{ LogName = 'System'; ProviderName = 'Microsoft-Windows-WER-SystemErrorReporting'; Id = 1001; StartTime = (Get-Date).AddDays(-2) } -MaxEvents 1 -ErrorAction SilentlyContinue)
        if ($bs.Count -and [string]$st.LastBsod -ne $bs[0].TimeCreated.ToString('o')) { $null = Send-PflegeNotify 'Bluescreen' ('Am {0:dd.MM.yyyy HH:mm}. Seite Fehler beheben zeigt die Ursache.' -f $bs[0].TimeCreated) 'Red'; $st.LastBsod = $bs[0].TimeCreated.ToString('o') }
    }
    $st.RedKey = $key; $st.LastState = $state
    [pscustomobject]$st | ConvertTo-Json | Set-Content $stFile -Encoding UTF8
}
function Add-HealthHistory {
    $f = Join-Path $DataDir 'Verlauf.csv'
    $today = (Get-Date).ToString('yyyy-MM-dd')
    $rows = @(); if (Test-Path $f) { $rows = @(Import-Csv -LiteralPath $f -Delimiter ';' -Encoding UTF8) }
    if (@($rows | Where-Object { $_.Datum -eq $today }).Count) { return }
    $bat = ''; $cyc = ''; $wear = ''; $temp = ''; $rerr = ''
    try { $des = @(Get-CimInstance -Namespace root\wmi -ClassName BatteryStaticData -ErrorAction Stop)[0].DesignedCapacity; $full = @(Get-CimInstance -Namespace root\wmi -ClassName BatteryFullChargedCapacity -ErrorAction Stop)[0].FullChargedCapacity; if ($des) { $bat = [math]::Round($full * 100 / $des, 1) }; $cyc = [string]@(Get-CimInstance -Namespace root\wmi -ClassName BatteryCycleCount -ErrorAction SilentlyContinue)[0].CycleCount } catch { }
    try { $sys = Get-Partition -DriveLetter ($env:SystemDrive.TrimEnd(':')) -ErrorAction Stop | Get-Disk -ErrorAction Stop; $pd = Get-PhysicalDisk -ErrorAction Stop | Where-Object { [string]$_.DeviceId -eq [string]$sys.Number } | Select-Object -First 1
          $rc = $pd | Get-StorageReliabilityCounter -ErrorAction Stop; $wear = [string]$rc.Wear; $temp = [string]$rc.Temperature; $rerr = [string]$rc.ReadErrorsUncorrected } catch { }
    $d = New-Object IO.DriveInfo $env:SystemDrive
    $boot = ''; try { $e = Get-WinEvent -FilterHashtable @{ LogName = 'Microsoft-Windows-Diagnostics-Performance/Operational'; Id = 100 } -MaxEvents 1 -ErrorAction Stop; $boot = [string][math]::Round([int]([xml]$e.ToXml()).Event.EventData.Data[1].'#text' / 1000, 1) } catch { }
    $rows += [pscustomobject]@{ Datum = $today; AkkuProzent = $bat; Ladezyklen = $cyc; SsdVerschleiss = $wear; SsdTemperatur = $temp; Lesefehler = $rerr; FreiGB = [math]::Round($d.AvailableFreeSpace / 1GB, 1); StartSek = $boot }
    $rows | Select-Object -Last 730 | Export-Csv -LiteralPath $f -Delimiter ';' -NoTypeInformation -Encoding UTF8
}
function Get-SystemSnapshot {
    $drv = @(Get-CimInstance Win32_PnPSignedDriver -ErrorAction SilentlyContinue | Where-Object { $_.DeviceName -and $_.DriverProviderName -notmatch '^Microsoft$' } | ForEach-Object { [pscustomobject]@{ Key = [string]$_.DeviceID; Name = [string]$_.DeviceName; Version = [string]$_.DriverVersion; Provider = [string]$_.DriverProviderName; Inf = [string]$_.InfName } })
    $prg = @(Get-ItemProperty 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*', 'HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*', 'HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*' -ErrorAction SilentlyContinue | Where-Object { $_.DisplayName -and -not $_.SystemComponent } | ForEach-Object { [pscustomobject]@{ Key = [string]$_.DisplayName; Name = [string]$_.DisplayName; Version = [string]$_.DisplayVersion; Provider = [string]$_.Publisher; Inf = [string]$_.PSChildName } } | Sort-Object Key -Unique)
    $kb = @(Get-HotFix -ErrorAction SilentlyContinue | ForEach-Object { [pscustomobject]@{ Key = [string]$_.HotFixID; Name = [string]$_.HotFixID; Version = [string]$_.Description; Provider = ''; Inf = $(if ($_.InstalledOn) { $_.InstalledOn.ToString('dd.MM.yyyy') } else { '' }) } })
    $reg = Get-ItemProperty 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion'
    [pscustomobject]@{ Time = (Get-Date).ToString('o'); Build = ('{0}.{1}' -f $reg.CurrentBuild, $reg.UBR); Drivers = $drv; Programs = $prg; Updates = $kb }
}
function Save-SystemSnapshot([string]$Reason) {
    $dir = Join-Path $DataDir 'Stände'; New-Item $dir -ItemType Directory -Force | Out-Null
    $s = Get-SystemSnapshot; $s | Add-Member -NotePropertyName Reason -NotePropertyValue $Reason
    $f = Join-Path $dir ('{0:yyyyMMdd_HHmmss}.json' -f (Get-Date))
    $s | ConvertTo-Json -Depth 4 -Compress | Set-Content -LiteralPath $f -Encoding UTF8
    Get-ChildItem $dir -Filter *.json | Sort-Object Name -Descending | Select-Object -Skip 40 | Remove-Item -Force -ErrorAction SilentlyContinue
    if (Get-Command Write-PLog -ErrorAction SilentlyContinue) { Write-PLog ('Stand vorher festgehalten: {0} Treiber, {1} Programme, {2} Updates' -f @($s.Drivers).Count, @($s.Programs).Count, @($s.Updates).Count) 'OK' }
}
function Compare-SystemSnapshot($A, $B) {
    $out = [System.Collections.Generic.List[object]]::new()
    foreach ($kind in @(@('Drivers', 'Treiber'), @('Programs', 'Programm'), @('Updates', 'Windows-Update'))) {
        $ha = @{}; foreach ($x in @($A.($kind[0]))) { $ha[[string]$x.Key] = $x }
        $hb = @{}; foreach ($x in @($B.($kind[0]))) { $hb[[string]$x.Key] = $x }
        foreach ($k in $hb.Keys) { $n = $hb[$k]; if (-not $ha.ContainsKey($k)) { $out.Add([pscustomobject]@{ Kind = $kind[1]; Name = $n.Name; Before = ''; After = $n.Version; Change = 'neu'; Key = $k; Inf = $n.Inf; Level = 'Warn' }) } elseif ([string]$ha[$k].Version -ne [string]$n.Version) { $out.Add([pscustomobject]@{ Kind = $kind[1]; Name = $n.Name; Before = $ha[$k].Version; After = $n.Version; Change = 'geändert'; Key = $k; Inf = $n.Inf; Level = 'Warn' }) } }
        foreach ($k in $ha.Keys) { if (-not $hb.ContainsKey($k)) { $o = $ha[$k]; $out.Add([pscustomobject]@{ Kind = $kind[1]; Name = $o.Name; Before = $o.Version; After = ''; Change = 'entfernt'; Key = $k; Inf = $o.Inf; Level = 'Off' }) } }
    }
    return , $out
}
function Invoke-AfterRun {
    # nach jedem Hintergrund- und Zeitplanlauf: Verlauf, Zustand, Meine PCs, Benachrichtigungen
    try { Add-HealthHistory } catch { }
    try { $null = Add-ScScoreHistory } catch { }
    $items = @(); try { $items = @(Get-HealthItems (Get-HealthArgs) | ForEach-Object { $_ }) } catch { }
    try { Write-FleetStatus $items } catch { }
    $run = $null; try { $run = Get-Content (Join-Path $DataDir 'lastrun.json') -Raw -Encoding UTF8 | ConvertFrom-Json } catch { }
    try { Invoke-NotifyCheck $items $run } catch { }
    try { Send-Integrations | Out-Null } catch { }
    if ($Script:IsAuto) { try { Invoke-AutoFix } catch { } }
}
function Get-BootTimes {
    $ev = @(Get-WinEvent -FilterHashtable @{ LogName = 'Microsoft-Windows-Diagnostics-Performance/Operational'; Id = 100 } -MaxEvents 20 -ErrorAction SilentlyContinue)
    $boots = foreach ($e in $ev) { $d = @{}; foreach ($n in ([xml]$e.ToXml()).Event.EventData.Data) { $d[$n.Name] = $n.'#text' }
        [pscustomobject]@{ Time = $e.TimeCreated; Total = [math]::Round([int]$d.BootTime / 1000, 1); Main = [math]::Round([int]$d.MainPathBootTime / 1000, 1); Post = [math]::Round([int]$d.BootPostBootTime / 1000, 1) } }
    $slow = foreach ($e in @(Get-WinEvent -FilterHashtable @{ LogName = 'Microsoft-Windows-Diagnostics-Performance/Operational'; Id = 101, 102, 103, 106, 109 } -MaxEvents 200 -ErrorAction SilentlyContinue)) {
        $d = @{}; foreach ($n in ([xml]$e.ToXml()).Event.EventData.Data) { $d[$n.Name] = $n.'#text' }
        $kind = switch ($e.Id) { 101 { 'Programm' } 102 { 'Treiber' } 103 { 'Dienst' } 106 { 'Hintergrund' } 109 { 'Gerät' } }
        $name = @($d.FriendlyName, $d.Name, $d.FileName, $d.ServiceName) | Where-Object { $_ } | Select-Object -First 1
        [pscustomobject]@{ Kind = $kind; Name = [string]$name; File = [string]$d.FileName; Delay = [math]::Round([int]$d.DegradationTime / 1000, 1); Time = $e.TimeCreated; Service = [string]$d.ServiceName }
    }
    $agg = @($slow | Where-Object { $_.Name } | Group-Object Kind, Name | ForEach-Object { $g = $_.Group; [pscustomobject]@{ Kind = $g[0].Kind; Name = $g[0].Name; File = $g[0].File; Service = $g[0].Service; Count = $g.Count; Avg = [math]::Round(($g | Measure-Object Delay -Average).Average, 1); Last = ($g | Sort-Object Time -Descending)[0].Time.ToString('dd.MM.yyyy') } } | Sort-Object Avg -Descending)
    [pscustomobject]@{ Boots = @($boots); Slow = $agg }
}

# ---- Apps entfernen (Bloatware), läuft im Hintergrund über -Run -Parts Debloat
# Level: 1 = vorsichtig (Werbung/Spiele), 2 = empfohlen (Microsoft-Extras), 3 = radikal (auch Xbox, Smartphone-Link ...), 0 = nur von Hand (nützlich)
$BloatCatalog = @(
    @('king.com.*', 'Candy Crush & Co. (King)', 'Spiele-Werbung', 1), @('*Disney*', 'Disney+', 'Werbe-App', 1), @('*TikTok*', 'TikTok', 'Werbe-App', 1), @('*Instagram*', 'Instagram', 'Werbe-App', 1),
    @('*Facebook*', 'Facebook', 'Werbe-App', 1), @('*Netflix*', 'Netflix', 'Werbe-App', 1), @('*AmazonVideo*', 'Prime Video', 'Werbe-App', 1), @('*LinkedIn*', 'LinkedIn', 'Werbe-App', 1),
