function Get-BloatList {
    $pk = @(Get-AppxPackage -AllUsers -ErrorAction SilentlyContinue | Where-Object { -not $_.IsFramework -and $_.SignatureKind -ne 'System' })
    $prov = @(Get-AppxProvisionedPackage -Online -ErrorAction SilentlyContinue)
    $out = [System.Collections.Generic.List[object]]::new()
    foreach ($c in $BloatCatalog) {
        $hit = @($pk | Where-Object { $_.Name -like $c[0] } | Sort-Object Name -Unique)
        foreach ($h in $hit) {
            $size = 0; try { if ($h.InstallLocation) { $size = (Get-ChildItem -LiteralPath $h.InstallLocation -Recurse -File -Force -ErrorAction SilentlyContinue | Measure-Object Length -Sum).Sum } } catch { }
            if (@($out | Where-Object { $_.Id -eq $h.Name }).Count) { continue }
            $out.Add([pscustomobject]@{ Kind = 'App'; Id = $h.Name; Name = $c[1]; Cat = $c[2]; Level = [int]$c[3]; Version = [string]$h.Version; Size = $size; SizeText = ('{0:N0} MB' -f ($size / 1MB)); Pfn = [string]$h.PackageFamilyName; Prov = [bool]@($prov | Where-Object { $_.DisplayName -eq $h.Name }).Count })
        }
    }
    foreach ($u in @(Get-ItemProperty 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*', 'HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*', 'HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*' -ErrorAction SilentlyContinue | Where-Object { $_.DisplayName -and $_.UninstallString })) {
        foreach ($w in $BloatWin32) { if ($u.DisplayName -like "*$w*") { $out.Add([pscustomobject]@{ Kind = 'Programm'; Id = [string]$u.PSChildName; Name = [string]$u.DisplayName; Cat = 'Hersteller-Beigabe / Probeversion'; Level = 1; Version = [string]$u.DisplayVersion; Size = [int64]$u.EstimatedSize * 1KB; SizeText = ('{0:N0} MB' -f ([int64]$u.EstimatedSize / 1KB)); Pfn = ''; Prov = $false }); break } }
    }
    return , $out
}
function Invoke-Debloat {
    $o = $Script:JobOpts
    $log = Join-Path $DataDir 'Apps-entfernt.json'
    $done = @(); try { $done = @(Get-Content $log -Raw -Encoding UTF8 | ConvertFrom-Json | ForEach-Object { $_ }) } catch { }
    foreach ($id in @($o.Apps)) {
        if (Test-PCancel) { break }
        $p = @(Get-AppxPackage -AllUsers -Name $id -ErrorAction SilentlyContinue)
        $Script:Detail = 'Entferne ' + $id; Set-PStatus $Script:StatusText
        $pfn = if ($p.Count) { [string]$p[0].PackageFamilyName } else { '' }
        foreach ($x in $p) { try { Remove-AppxPackage -Package $x.PackageFullName -AllUsers -ErrorAction Stop } catch { try { Remove-AppxPackage -Package $x.PackageFullName -ErrorAction Stop } catch { Write-PLog ('   {0}: {1}' -f $id, $_.Exception.Message) 'WARN' } } }
        if ($o.Provisioned) { foreach ($pp in @(Get-AppxProvisionedPackage -Online -ErrorAction SilentlyContinue | Where-Object { $_.DisplayName -eq $id })) { try { $null = Remove-AppxProvisionedPackage -Online -PackageName $pp.PackageName -ErrorAction Stop } catch { } } }
        $still = @(Get-AppxPackage -AllUsers -Name $id -ErrorAction SilentlyContinue).Count
        Write-PLog ('   {0}: {1}' -f $id, $(if ($still) { 'nicht vollständig entfernt' } else { 'entfernt' })) $(if ($still) { 'WARN' } else { 'OK' })
        if (-not $still) { $done += [pscustomobject]@{ Id = $id; Pfn = $pfn; Time = (Get-Date).ToString('dd.MM.yyyy HH:mm') } }
    }
    foreach ($key in @($o.Win32)) {
        $u = Get-ItemProperty ('HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\' + $key), ('HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\' + $key), ('HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\' + $key) -ErrorAction SilentlyContinue | Select-Object -First 1
        if (-not $u) { continue }
        $Script:Detail = 'Deinstalliere ' + $u.DisplayName; Set-PStatus $Script:StatusText
        if ($key -match '^\{[0-9A-F\-]+\}$') { $rc = Invoke-External -Exe (Join-Path $env:windir 'System32\msiexec.exe') -Arguments @('/x', $key, '/qn', '/norestart') -TimeoutMin 20 -Quiet }
        elseif ($u.QuietUninstallString) { $rc = Invoke-External -Exe 'cmd.exe' -Arguments @('/c', ('"{0}"' -f $u.QuietUninstallString)) -TimeoutMin 20 -Quiet }
        else { Write-PLog ('   {0}: Deinstallation öffnet sich - bitte dort bestätigen.' -f $u.DisplayName); $rc = Invoke-External -Exe 'cmd.exe' -Arguments @('/c', ('"{0}"' -f $u.UninstallString)) -TimeoutMin 20 -Quiet }
        Write-PLog ('   {0}: Code {1}' -f $u.DisplayName, $rc) $(if ($rc -in 0, 3010, 1605) { 'OK' } else { 'WARN' })
    }
    $done | ConvertTo-Json | Set-Content $log -Encoding UTF8
}
