$PrivacyCaps = [ordered]@{ webcam = 'Kamera'; microphone = 'Mikrofon'; location = 'Standort'; contacts = 'Kontakte'; appointments = 'Kalender'; graphicsCaptureProgrammatic = 'Bildschirmaufnahme'; phoneCall = 'Telefonate'; radios = 'Funk (Bluetooth/WLAN)'; documentsLibrary = 'Dokumente'; picturesLibrary = 'Bilder'; userNotificationListener = 'Benachrichtigungen lesen' }
function Get-PrivacyApps {
    $out = [System.Collections.Generic.List[object]]::new()
    foreach ($cap in $PrivacyCaps.Keys) {
        foreach ($root in 'HKCU:', 'HKLM:') {
            $base = "$root\Software\Microsoft\Windows\CurrentVersion\CapabilityAccessManager\ConsentStore\$cap"
            if (-not (Test-Path $base)) { continue }
            $keys = @(Get-ChildItem $base -ErrorAction SilentlyContinue | Where-Object { $_.PSChildName -ne 'NonPackaged' }) + @(Get-ChildItem "$base\NonPackaged" -ErrorAction SilentlyContinue)
            foreach ($k in $keys) {
                $p = Get-ItemProperty $k.PSPath -ErrorAction SilentlyContinue
                $nm = [string]$k.PSChildName
                $friendly = if ($nm -match '#') { [IO.Path]::GetFileName(($nm -replace '#', '\')) } else { (($nm -split '_')[0] -replace '^[^.]+\.', '') }
                $last = ''; $active = $false
                if ($p.LastUsedTimeStop) { try { $last = [DateTime]::FromFileTime([int64]$p.LastUsedTimeStop).ToString('dd.MM.yyyy HH:mm') } catch { } }
                if ($p.LastUsedTimeStart -and [int64]$p.LastUsedTimeStart -gt [int64]$p.LastUsedTimeStop) { $active = $true }
                if (@($out | Where-Object { $_.Cap -eq $cap -and $_.Key -eq $nm }).Count) { continue }
                $out.Add([pscustomobject]@{ Cap = $cap; CapDe = $PrivacyCaps[$cap]; Key = $nm; App = $friendly; Path = [string]$k.PSPath; Allowed = $(if ([string]$p.Value -eq 'Deny') { 'nein' } else { 'ja' }); Last = $(if ($active) { 'GERADE AKTIV' } else { $last }); Level = $(if ($active) { 'Warn' } elseif ([string]$p.Value -eq 'Deny') { 'Off' } else { '' }); Desktop = ($nm -match '#') })
            }
        }
    }
    return , $out
}
