$DnsProviders = [ordered]@{ 'Automatisch (vom Router)' = @(); 'Cloudflare (schnell)' = @('1.1.1.1', '1.0.0.1'); 'Cloudflare Familie (sperrt Schadseiten und Erwachsenen-Inhalte)' = @('1.1.1.3', '1.0.0.3'); 'Quad9 (sperrt Schadseiten, Schweiz)' = @('9.9.9.9', '149.112.112.112'); 'AdGuard (sperrt Werbung und Tracker)' = @('94.140.14.14', '94.140.15.15'); 'Google' = @('8.8.8.8', '8.8.4.4'); 'DNS4EU (EU)' = @('86.54.11.100', '86.54.11.200') }
function Get-NetOverview {
    $out = @()
    foreach ($a in @(Get-NetAdapter -ErrorAction SilentlyContinue | Where-Object { $_.Status -eq 'Up' })) {
        $ip = Get-NetIPConfiguration -InterfaceIndex $a.ifIndex -ErrorAction SilentlyContinue
        $dns = @(Get-DnsClientServerAddress -InterfaceIndex $a.ifIndex -AddressFamily IPv4 -ErrorAction SilentlyContinue).ServerAddresses
        $out += [pscustomobject]@{ Name = $a.Name; Desc = $a.InterfaceDescription; Speed = $a.LinkSpeed; Mac = $a.MacAddress; IP = (@($ip.IPv4Address.IPAddress) -join ', '); Gw = (@($ip.IPv4DefaultGateway.NextHop) -join ', '); Dns = ($dns -join ', '); Index = $a.ifIndex; Wifi = ($a.PhysicalMediaType -match '802.11' -or $a.InterfaceDescription -match 'Wi-?Fi|Wireless|WLAN') }
    }
    $w = (& netsh.exe wlan show interfaces 2>$null) -join "`n"
    $wifi = $null
    if ($w -match '(?m)^\s*SSID\s*:\s*(.+)$') {
        $g = { param($p) if ($w -match ('(?m)^\s*(?:' + $p + ')\s*:\s*(.+)$')) { $Matches[1].Trim() } else { '' } }
        $wifi = [pscustomobject]@{ Ssid = (& $g 'SSID'); Signal = (& $g 'Signal'); Channel = (& $g 'Kanal|Channel'); Band = (& $g 'Band'); Rx = (& $g 'Empfangsrate \(MBit/s\)|Receive rate \(Mbps\)'); Tx = (& $g 'Übertragungsrate \(MBit/s\)|Transmit rate \(Mbps\)'); Auth = (& $g 'Authentifizierung|Authentication'); Radio = (& $g 'Funktyp|Radio type') }
    }
    $pub = ''; try { $pub = (Invoke-RestMethod -Uri 'https://api.ipify.org' -TimeoutSec 5) } catch { }
    [pscustomobject]@{ Adapters = $out; Wifi = $wifi; Public = [string]$pub }
}
function Get-WifiNetworks {
    $raw = @(& netsh.exe wlan show networks mode=bssid 2>$null)
    $list = @(); $cur = $null
    foreach ($l in $raw) {
        if ($l -match '^SSID \d+ : (.*)$') { if ($cur) { $list += $cur }; $cur = [ordered]@{ Ssid = $Matches[1]; Signal = 0; Channel = ''; Band = ''; Auth = ''; Count = 0 } }
        elseif ($cur -and $l -match '^\s*(Authentifizierung|Authentication)\s*:\s*(.+)$') { $cur.Auth = $Matches[2].Trim() }
        elseif ($cur -and $l -match '^\s*BSSID \d+') { $cur.Count++ }
        elseif ($cur -and $l -match '^\s*Signal\s*:\s*(\d+)%') { $cur.Signal = [math]::Max($cur.Signal, [int]$Matches[1]) }
        elseif ($cur -and $l -match '^\s*(Kanal|Channel)\s*:\s*(\d+)') { if (-not $cur.Channel) { $cur.Channel = $Matches[2] } }
        elseif ($cur -and $l -match '^\s*Band\s*:\s*(.+)$') { if (-not $cur.Band) { $cur.Band = $Matches[1].Trim() } }
    }
    if ($cur) { $list += $cur }
    @($list | ForEach-Object { [pscustomobject]$_ } | Sort-Object Signal -Descending | ForEach-Object { $_ | Add-Member -NotePropertyName SignalText -NotePropertyValue ('{0} %' -f $_.Signal) -PassThru })
}
function Get-WifiPasswords {
    $names = @(& netsh.exe wlan show profiles 2>$null | ForEach-Object { if ($_ -match '(?:Profil für alle Benutzer|All User Profile|Benutzerprofil)\s*:\s*(.+)$') { $Matches[1].Trim() } })
    foreach ($n in $names) {
        $o = (& netsh.exe wlan show profile name="$n" key=clear 2>$null) -join "`n"
        $k = if ($o -match '(?m)^\s*(Schlüsselinhalt|Key Content)\s*:\s*(.+)$') { $Matches[2].Trim() } else { '(offen oder Unternehmens-WLAN)' }
        $au = if ($o -match '(?m)^\s*(Authentifizierung|Authentication)\s*:\s*(.+)$') { $Matches[2].Trim() } else { '' }
        [pscustomobject]@{ Ssid = $n; Key = $k; Auth = $au }
    }
}
function Get-NetConnectionsList {
    $procs = @{}; foreach ($p in @(Get-Process -ErrorAction SilentlyContinue)) { $procs[$p.Id] = $p }
    @(Get-NetTCPConnection -State Established -ErrorAction SilentlyContinue | Where-Object { $_.RemoteAddress -notmatch '^(127\.|::1|0\.0\.0\.0)' } | ForEach-Object {
        $pr = $procs[[int]$_.OwningProcess]
        [pscustomobject]@{ Program = $(if ($pr) { $pr.ProcessName } else { [string]$_.OwningProcess }); Path = $(if ($pr) { try { $pr.Path } catch { '' } } else { '' }); Remote = [string]$_.RemoteAddress; Port = [int]$_.RemotePort; Local = [int]$_.LocalPort; Host = '' }
    } | Sort-Object Program, Remote)
}
function Invoke-SpeedTest {
    $ua = 'PC-Tools'
    $ping = @(); $pn = New-Object Net.NetworkInformation.Ping
    for ($i = 0; $i -lt 5; $i++) { try { $r = $pn.Send('1.1.1.1', 1500); if ($r.Status -eq 'Success') { $ping += $r.RoundtripTime } } catch { } }
    $dl = 0; $ul = 0
    try { [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12 } catch { }
    try {
        $wc = New-Object Net.WebClient; $wc.Headers.Add('User-Agent', $ua)
        $sw = [Diagnostics.Stopwatch]::StartNew(); $data = $wc.DownloadData('https://speed.cloudflare.com/__down?bytes=50000000'); $sw.Stop()
        $dl = [math]::Round($data.Length * 8 / $sw.Elapsed.TotalSeconds / 1e6, 1)
    } catch { }
    try {
        $buf = New-Object byte[] 10000000; (New-Object Random).NextBytes($buf)
        $wc = New-Object Net.WebClient; $wc.Headers.Add('User-Agent', $ua); $wc.Headers.Add('Content-Type', 'application/octet-stream')
        $sw = [Diagnostics.Stopwatch]::StartNew(); $null = $wc.UploadData('https://speed.cloudflare.com/__up', 'POST', $buf); $sw.Stop()
        $ul = [math]::Round($buf.Length * 8 / $sw.Elapsed.TotalSeconds / 1e6, 1)
    } catch { }
    [pscustomobject]@{ Down = $dl; Up = $ul; Ping = $(if ($ping.Count) { [math]::Round(($ping | Measure-Object -Average).Average, 0) } else { -1 }); Jitter = $(if ($ping.Count -gt 1) { ($ping | Measure-Object -Maximum).Maximum - ($ping | Measure-Object -Minimum).Minimum } else { 0 }) }
}

# ---- Windows-Funktionen (RSAT, OpenSSH, Hyper-V ...) aus dem Profil "Windows-Server-Tools"
function Invoke-WinFeatures {
    foreach ($id in @($Script:JobOpts.WinFeatures)) {
        if (Test-PCancel) { break }
        $name = $id.Substring(2)
        $Script:Detail = $name + ' wird installiert (lädt ggf. von Windows Update)'; Set-PStatus $Script:StatusText
        try {
            if ($id.StartsWith('c:')) {
                $cap = Get-WindowsCapability -Online -Name $name -ErrorAction Stop
                if ($cap.State -eq 'Installed') { Write-PLog ('   {0}: bereits installiert' -f $name) 'OK'; continue }
                $r = Add-WindowsCapability -Online -Name $name -ErrorAction Stop
            } else {
                $f = Get-WindowsOptionalFeature -Online -FeatureName $name -ErrorAction Stop
                if ($f.State -eq 'Enabled') { Write-PLog ('   {0}: bereits eingeschaltet' -f $name) 'OK'; continue }
                $r = Enable-WindowsOptionalFeature -Online -FeatureName $name -All -NoRestart -ErrorAction Stop
            }
            if ($r.RestartNeeded) { $Script:RebootNeeded = $true }
            Write-PLog ('   {0}: installiert{1}' -f $name, $(if ($r.RestartNeeded) { ' - Neustart nötig' } else { '' })) 'OK'
        } catch { Write-PLog ('   {0}: {1} (Hyper-V und Sandbox gibt es nur in Windows Pro/Enterprise)' -f $name, $_.Exception.Message) 'WARN' }
    }
}

# ---- Lizenzen: auslesen, sichern, übertragen
$GenericWinKeys = @{ 'VK7JG-NPHTM-C97JM-9MPGT-3V66T' = 'Pro (generisch)'; 'YTMG3-N6DKC-DKB77-7M9GH-8HVX7' = 'Home (generisch)'; '2B87N-8KFHP-DKV6R-Y2C8J-PKCKT' = 'Pro N (generisch)'; 'YNMGQ-8RYV3-4PGQ3-C8XTP-7CFBY' = 'Education (generisch)'
                     'XGVPP-NMH47-7TTHJ-W3FW7-8HV2C' = 'Enterprise (generisch)'; 'DXG7C-N36C4-C4HTG-X4T3X-2YV77' = 'Pro for Workstations (generisch)'; 'BT79Q-G7N6G-PGBYW-4YWX6-6F4BT' = 'Home Single Language (generisch)'
                     'W269N-WFGWX-YVC9B-4J6C9-T83GX' = 'Pro KMS-Client'; 'NPPR9-FWDCX-D2C8J-H872K-2YT43' = 'Enterprise KMS-Client'; '3KHY7-WNT83-DGQKR-F7HPR-844BM' = 'Pro (Insider/generisch)' }
function ConvertFrom-DigitalProductId([byte[]]$Id) {
    if (-not $Id -or $Id.Length -lt 67) { return '' }
    $k = New-Object 'int[]' 15; for ($i = 0; $i -lt 15; $i++) { $k[$i] = $Id[52 + $i] }
    $isWin8 = [int]([math]::Floor($k[14] / 6)) -band 1
    $k[14] = ($k[14] -band 0xF7) -bor (($isWin8 -band 2) * 4)
    $chars = 'BCDFGHJKMPQRTVWXY2346789'; $out = ''; $last = 0
    for ($j = 24; $j -ge 0; $j--) {
        $cur = 0
        for ($y = 14; $y -ge 0; $y--) { $cur = $cur * 256 + $k[$y]; $k[$y] = [int][math]::Floor($cur / 24); $cur = $cur % 24 }
        $out = $chars[$cur] + $out; $last = $cur
    }
    if ($isWin8) { $s = $out.Substring(1); $out = $s.Substring(0, $last) + 'N' + $s.Substring($last) }
    return ($out.Substring(0, 5) + '-' + $out.Substring(5, 5) + '-' + $out.Substring(10, 5) + '-' + $out.Substring(15, 5) + '-' + $out.Substring(20, 5))
}
function Get-WindowsLicense {
    $reg = Get-ItemProperty 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion'
    $inst = ''; try { $inst = ConvertFrom-DigitalProductId ([byte[]]$reg.DigitalProductId) } catch { }
    $svc = Get-CimInstance SoftwareLicensingService -ErrorAction SilentlyContinue
    $prod = @(Get-CimInstance SoftwareLicensingProduct -Filter "ApplicationID='55c92734-d682-4d71-983e-d6ec3f16059f' AND PartialProductKey IS NOT NULL" -ErrorAction SilentlyContinue) | Select-Object -First 1
    $chan = [string]$prod.ProductKeyChannel; if (-not $chan -and $prod.Description -match 'channel$|(RETAIL|OEM|VOLUME\S*)') { $chan = $Matches[1] }
    $status = switch ([int]$prod.LicenseStatus) { 0 { 'nicht lizenziert' } 1 { 'aktiviert' } 2 { 'Kulanzzeit (OOB)' } 3 { 'Kulanzzeit (OOT)' } 4 { 'nicht echt' } 5 { 'Benachrichtigung - nicht aktiviert' } 6 { 'verlängerte Kulanzzeit' } default { 'unbekannt' } }
    $kind = if ($GenericWinKeys.ContainsKey($inst)) { 'Digitale Lizenz (an Hardware/Microsoft-Konto gebunden)' } elseif ($chan -match 'OEM') { 'OEM (an dieses Gerät gebunden)' } elseif ($chan -match 'Retail') { 'Einzelhandel/Retail (übertragbar)' } elseif ($chan -match 'Volume|KMS|MAK|GVLK') { 'Volumenlizenz (Firma)' } else { $chan }
    [pscustomobject]@{
        Edition = [string]$reg.EditionID; Name = ('{0} {1}' -f $reg.ProductName, $reg.DisplayVersion); Build = ('{0}.{1}' -f $reg.CurrentBuild, $reg.UBR)
        Status = $status; Channel = $chan; Kind = $kind; Partial = [string]$prod.PartialProductKey
        Installed = $inst; InstalledNote = $(if ($GenericWinKeys.ContainsKey($inst)) { $GenericWinKeys[$inst] } else { '' })
        Firmware = [string]$svc.OA3xOriginalProductKey; FirmwareDesc = [string]$svc.OA3xOriginalProductKeyDescription
        ProductId = [string]$reg.ProductId; Transferable = ($chan -match 'Retail' -and -not $GenericWinKeys.ContainsKey($inst))
    }
}
function Get-OfficeLicenses {
    $out = @()
    foreach ($p in @(Get-CimInstance SoftwareLicensingProduct -Filter "ApplicationID='0ff1ce15-a989-479d-af46-f275c6370663' AND PartialProductKey IS NOT NULL" -ErrorAction SilentlyContinue)) {
        $out += [pscustomobject]@{ Product = [string]$p.Name; Type = [string]$p.Description; Key = ('XXXXX-XXXXX-XXXXX-XXXXX-' + $p.PartialProductKey); Partial = [string]$p.PartialProductKey; Status = $(if ($p.LicenseStatus -eq 1) { 'aktiviert' } else { 'nicht aktiviert' }); Transfer = $(if ([string]$p.Description -match 'RETAIL') { 'Einzelhandel: auf altem PC entfernen, auf neuem mit dem Schlüssel aktivieren' } elseif ([string]$p.Description -match 'VOLUME') { 'Volumenlizenz der Firma' } else { 'Microsoft-Konto: account.microsoft.com/services' }) }
    }
    $c2r = Get-ItemProperty 'HKLM:\SOFTWARE\Microsoft\Office\ClickToRun\Configuration' -ErrorAction SilentlyContinue
    if ($c2r -and $c2r.ProductReleaseIds) {
        $mails = @(Get-ChildItem 'HKCU:\Software\Microsoft\Office\16.0\Common\Identity\Identities' -ErrorAction SilentlyContinue | ForEach-Object { (Get-ItemProperty $_.PSPath -ErrorAction SilentlyContinue).EmailAddress } | Where-Object { $_ } | Select-Object -Unique)
        foreach ($id in ([string]$c2r.ProductReleaseIds -split ',')) {
            if ($out | Where-Object { $_.Product -match [regex]::Escape($id) }) { continue }
            $out += [pscustomobject]@{ Product = $id; Type = $(if ($id -match '^O365') { 'Microsoft 365 (Abo)' } else { 'Klick-und-Los' }); Key = $(if ($mails) { 'Konto: ' + ($mails -join ', ') } else { '(über Microsoft-Konto)' }); Partial = ''; Status = 'installiert'; Transfer = 'Auf altem PC in Office abmelden bzw. unter account.microsoft.com/services die Installation deaktivieren, auf neuem PC anmelden' }
        }
    }
    return $out
}
