function Get-SoftwareLicenses {
    $prog = @(Get-ItemProperty 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*', 'HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*', 'HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*' -ErrorAction SilentlyContinue | Where-Object { $_.DisplayName -and -not $_.SystemComponent } | Sort-Object DisplayName -Unique)
    $out = @()
    foreach ($k in $LicenseKnowledge) {
        $hit = @($prog | Where-Object { $_.DisplayName -match $k[0] } | Select-Object -First 3)
        if (-not $hit.Count) { continue }
        $files = @($k[3] | ForEach-Object { [Environment]::ExpandEnvironmentVariables($_) } | Where-Object { Test-Path -LiteralPath $_ })
        foreach ($h in $hit) { $out += [pscustomobject]@{ Program = [string]$h.DisplayName; Version = [string]$h.DisplayVersion; Kind = $k[1]; Hint = $k[2]; File = ($files -join '; '); HasFile = [bool]$files.Count } }
    }
    return $out
}
# Lizenz-Tresor: lokal mit dem Windows-Konto verschlüsselt (DPAPI), Export mit eigenem Kennwort (AES-256)
$LicVaultFile = Join-Path $DataDir 'Lizenzen.dat'
function Read-LicVault {
    if (-not (Test-Path $LicVaultFile)) { return @() }
    Add-Type -AssemblyName System.Security
    try { $b = [Security.Cryptography.ProtectedData]::Unprotect([IO.File]::ReadAllBytes($LicVaultFile), $null, 'CurrentUser'); return @(([Text.Encoding]::UTF8.GetString($b) | ConvertFrom-Json) | ForEach-Object { $_ }) } catch { throw 'Der Lizenz-Tresor lässt sich nur mit dem Windows-Konto öffnen, das ihn angelegt hat.' }
}
function Save-LicVault($Items) {
    Add-Type -AssemblyName System.Security
    $j = ConvertTo-Json -InputObject @($Items) -Depth 4
    [IO.File]::WriteAllBytes($LicVaultFile, [Security.Cryptography.ProtectedData]::Protect([Text.Encoding]::UTF8.GetBytes($j), $null, 'CurrentUser'))
}
function Protect-WithPassword([byte[]]$Data, [string]$Pwd) {
    $salt = New-Object byte[] 16; $iv = New-Object byte[] 16; $rng = [Security.Cryptography.RandomNumberGenerator]::Create(); $rng.GetBytes($salt); $rng.GetBytes($iv)
    $kdf = New-Object Security.Cryptography.Rfc2898DeriveBytes($Pwd, $salt, 200000)
    $aes = [Security.Cryptography.Aes]::Create(); $aes.Key = $kdf.GetBytes(32); $aes.IV = $iv
    $hash = [Security.Cryptography.SHA256]::Create().ComputeHash($Data)
    $plain = $hash + $Data
    $enc = $aes.CreateEncryptor().TransformFinalBlock($plain, 0, $plain.Length)
    return ([Text.Encoding]::ASCII.GetBytes('PCPFLEGE-LIZENZ1') + $salt + $iv + $enc)
}
function Unprotect-WithPassword([byte[]]$Blob, [string]$Pwd) {
    if ([Text.Encoding]::ASCII.GetString($Blob, 0, 16) -ne 'PCPFLEGE-LIZENZ1') { throw 'Keine Lizenz-Exportdatei von PC-Tools.' }
    $salt = $Blob[16..31]; $iv = $Blob[32..47]; $enc = $Blob[48..($Blob.Length - 1)]
    $kdf = New-Object Security.Cryptography.Rfc2898DeriveBytes($Pwd, [byte[]]$salt, 200000)
    $aes = [Security.Cryptography.Aes]::Create(); $aes.Key = $kdf.GetBytes(32); $aes.IV = [byte[]]$iv
    try { $plain = $aes.CreateDecryptor().TransformFinalBlock([byte[]]$enc, 0, $enc.Length) } catch { throw 'Kennwort falsch.' }
    $data = [byte[]]$plain[32..($plain.Length - 1)]
    $chk = [Security.Cryptography.SHA256]::Create().ComputeHash($data)
    if ([Convert]::ToBase64String($chk) -ne [Convert]::ToBase64String([byte[]]$plain[0..31])) { throw 'Kennwort falsch oder Datei beschädigt.' }
    return $data
}

