function Get-SurfaceInfo {
    $cs = Get-CimInstance Win32_ComputerSystem -ErrorAction SilentlyContinue; $bi = Get-CimInstance Win32_BIOS -ErrorAction SilentlyContinue
    $cpu = @(Get-CimInstance Win32_Processor -ErrorAction SilentlyContinue)[0]
    $cpuK = if ($env:PROCESSOR_ARCHITECTURE -eq 'ARM64' -or [string]$cpu.Name -match 'Snapdragon|Qualcomm|SQ\d|Microsoft SQ') { 'Arm' } elseif ([string]$cpu.Manufacturer -match 'AMD') { 'AMD' } else { 'Intel' }
    $model = [string]$cs.Model; $sku = [string]$cs.SystemSKUNumber
    $isS = ([string]$cs.Manufacturer -match 'Microsoft') -and ($model -match 'Surface')
    $entry = $null
    if ($isS) { foreach ($e in $SurfaceModels) { if (('{0}|{1}' -f $model, $sku) -match $e.M -or $model -match $e.M) { if (-not $e.C -or $e.C -eq $cpuK) { $entry = $e; break } } } }
    $bd = ''; try { if ($bi.ReleaseDate) { $bd = ([datetime]$bi.ReleaseDate).ToString('dd.MM.yyyy') } } catch { }
    [pscustomobject]@{ IsSurface = $isS; Model = $model; Sku = $sku; Serial = [string]$bi.SerialNumber; Uefi = [string]$bi.SMBIOSBIOSVersion; UefiDate = $bd; Cpu = [string]$cpu.Name; CpuKind = $cpuK; Entry = $entry; Maker = [string]$cs.Manufacturer }
}
function Get-SurfaceMsiList([int]$Id, [int]$Win = 11, [int]$OsBuild = 0) {
    if ($Id -le 0) { throw 'Für dieses Modell gibt es kein MSI-Paket - Treiber und Firmware kommen nur über Windows Update.' }
    $html = Get-WebHtml ('https://www.microsoft.com/en-us/download/details.aspx?id={0}' -f $Id)
    $urls = @([regex]::Matches(($html -replace '\\u002F', '/' -replace '\\/', '/'), 'https?://download\.microsoft\.com/[^"''\s<>]+?\.(msi|zip)') | ForEach-Object { $_.Value } | Sort-Object -Unique)
    if (-not $urls.Count) { throw ('Auf der Microsoft-Seite (ID {0}) wurde kein Paket gefunden.' -f $Id) }
    $list = @($urls | ForEach-Object {
        $fn = [IO.Path]::GetFileName($_)
        $wv = if ($fn -match '(?i)Win11') { 11 } elseif ($fn -match '(?i)Win10') { 10 } else { 0 }
        $build = if ($fn -match '_(\d{5})_') { [int]$Matches[1] } else { 0 }
        $ver = if ($fn -match '_(\d+\.\d+\.\d+(\.\d+)?)\.(msi|zip)$') { $Matches[1] } else { '' }
        [pscustomobject]@{ File = $fn; Url = $_; Win = $wv; Build = $build; Version = $ver; Kind = [IO.Path]::GetExtension($fn).TrimStart('.').ToUpper() }
    } | Sort-Object @{ e = { $_.Kind -eq 'MSI' }; Descending = $true }, @{ e = { $_.Win -eq $Win }; Descending = $true }, @{ e = { $_.Win }; Descending = $true }, @{ e = { $OsBuild -eq 0 -or $_.Build -le $OsBuild }; Descending = $true }, @{ e = { $_.Build }; Descending = $true }, @{ e = { try { [version]$_.Version } catch { [version]'0.0' } }; Descending = $true })
    return $list
}
function Find-SurfaceLocalPack([string]$Hint) {
    $roots = @(); if ($PSScriptRoot) { $roots += (Join-Path $PSScriptRoot 'Surface'); $roots += $PSScriptRoot }
    $roots += (Join-Path $DataDir 'Surface')
    foreach ($dl in @(Get-CimInstance Win32_LogicalDisk -Filter 'DriveType=2 OR DriveType=3' -ErrorAction SilentlyContinue)) { $roots += (Join-Path ($dl.DeviceID + '\') 'Surface'); $roots += (Join-Path ($dl.DeviceID + '\') 'PCPflege\Surface') }
    $key = ($Hint -replace '[^A-Za-z0-9]', '')
    @(foreach ($r in ($roots | Select-Object -Unique)) { Get-ChildItem -LiteralPath $r -Filter *.msi -File -ErrorAction SilentlyContinue }) | Sort-Object @{ e = { $key -and (($_.Name -replace '[^A-Za-z0-9]', '') -like ('*' + $key + '*')) }; Descending = $true }, LastWriteTime -Descending
}
function Install-SurfaceMsi([string]$Msi, [string]$Mode = 'Full') {
    if ($Mode -eq 'Net') {
        $ex = Join-Path $env:SystemDrive 'PCPflege-Surface'; if (Test-Path $ex) { Remove-Item $ex -Recurse -Force -ErrorAction SilentlyContinue }; New-Item $ex -ItemType Directory -Force | Out-Null
        Write-PLog ('   Paket wird entpackt nach {0} ...' -f $ex)
        $rc = Invoke-External -Exe 'msiexec.exe' -Arguments @('/a', ('"{0}"' -f $Msi), '/qn', ('TARGETDIR="{0}"' -f $ex)) -TimeoutMin 30 -Quiet
        $infs = @(Get-ChildItem $ex -Recurse -Filter *.inf -ErrorAction SilentlyContinue | Where-Object { $_.DirectoryName -match '(?i)wifi|wlan|wireless|marvell|mrvl|avastar|netw|ethernet|realtek|rtux|rtk|lan|network|qcom.*wlan|qca|killer|intel.*wi' -or (Select-String -LiteralPath $_.FullName -Pattern '(?i)^\s*Class\s*=\s*Net\s*$' -Quiet -ErrorAction SilentlyContinue) })
        Write-PLog ('   Entpackt (Code {0}), {1} Netzwerktreiber gefunden.' -f $rc, $infs.Count)
        if (-not $infs.Count) { throw 'Im Paket wurden keine Netzwerktreiber gefunden.' }
        foreach ($i in $infs) {
            $r = Invoke-External -Exe (Join-Path $env:SystemRoot 'System32\pnputil.exe') -Arguments @('/add-driver', ('"{0}"' -f $i.FullName), '/install') -TimeoutMin 10 -Quiet
            Write-PLog ('   {0}: Code {1}' -f ($i.FullName.Substring($ex.Length + 1)), $r) $(if ($r -in 0, 259, 3010) { 'OK' } else { 'WARN' })
            if ($r -eq 3010) { $Script:RebootNeeded = $true }
        }
        Remove-Item $ex -Recurse -Force -ErrorAction SilentlyContinue
        return
    }
    $lg = Join-Path (Join-Path $DataDir 'Logs') ('Surface-MSI_{0:yyyyMMdd_HHmm}.log' -f (Get-Date))
    $Script:Detail = 'Surface-Treiber und -Firmware werden installiert (10-20 Minuten, Bildschirm kann flackern)'; Set-PStatus $Script:StatusText
    $rc = Invoke-External -Exe 'msiexec.exe' -Arguments @('/i', ('"{0}"' -f $Msi), '/qn', '/norestart', ('/l*v "{0}"' -f $lg)) -TimeoutMin 60 -Quiet
    switch ($rc) {
        0 { Write-PLog 'Surface-Paket installiert.' 'OK' }
        3010 { Write-PLog 'Surface-Paket installiert - Neustart nötig (Firmware wird beim Neustart eingespielt, Gerät NICHT ausschalten, Netzteil anschließen).' 'OK'; $Script:RebootNeeded = $true }
        1638 { Write-PLog 'Diese oder eine neuere Version des Pakets ist bereits installiert.' 'OK' }
        1603 { Write-PLog ('Installation fehlgeschlagen (1603) - Protokoll: {0}. Häufig: falsches Modell, Akku unter 40 % oder BitLocker. Tipp: "Nur Netzwerktreiber" oder anderes Paket.' -f $lg) 'WARN' }
        default { Write-PLog ('msiexec meldet Code {0} - Protokoll: {1}' -f $rc, $lg) 'WARN' }
    }
    $Script:UpdatesInstalled++
}
function Invoke-SurfacePackJob {
    $o = $Script:JobOpts
    $msi = [string]$o.SurfFile
    if (-not $msi -and [string]$o.SurfUrl) {
        $p = [pscustomobject]@{ File = [string]$o.SurfPkgFile; Url = [string]$o.SurfUrl; Version = '' }
        if (-not $p.File) { $p.File = [IO.Path]::GetFileName(([uri]$p.Url).AbsolutePath) }
        Write-PLog ('{0}: gewählte Variante {1}' -f $o.SurfName, $p.File)
        $dir = if ($o.SurfDest) { [string]$o.SurfDest } else { Join-Path $DataDir 'Surface' }
        $msi = Join-Path $dir $p.File
        if ((Test-Path -LiteralPath $msi) -and (Get-Item -LiteralPath $msi).Length -gt 50MB) { Write-PLog '   Paket liegt schon vor - Download übersprungen.' 'OK' }
        else { Save-Download $p.Url $msi $p.File }
        if ($o.SurfMode -eq 'Save') {
            Write-PLog ('   Gespeichert: {0} ({1:N0} MB)' -f $msi, ((Get-Item -LiteralPath $msi).Length / 1MB)) 'OK'
            Set-Content -LiteralPath (Join-Path $dir 'LIESMICH.txt') -Encoding UTF8 -Value @(('Surface-Treiberpaket für: {0}' -f $o.SurfName), ('Datei: {0}' -f $p.File), '', 'Auf dem Surface: PC-Tools vom Stick starten > Microsoft Surface > "Paket vom Stick installieren"', 'oder nur die Netzwerktreiber: "Nur Netzwerk-/WLAN-Treiber aus dem Paket".', 'Ohne PC-Tools: Doppelklick auf die .msi-Datei (ZIP: entpacken und Treiber per Geräte-Manager einspielen).')
            return
        }
    }
    if (-not $msi) {
        $Script:Detail = 'Surface-Paket wird gesucht'; Set-PStatus $Script:StatusText
        $l = @(Get-SurfaceMsiList ([int]$o.SurfId) $(if ($o.SurfWin) { [int]$o.SurfWin } else { 11 }) $(if ($o.SurfMode -ne 'Save') { [Environment]::OSVersion.Version.Build } else { 0 }) | Where-Object { $_.Kind -eq 'MSI' })
        if (-not $l.Count) { throw 'Für dieses Modell gibt es nur ein ZIP-Paket - bitte manuell von der Microsoft-Seite laden.' }
        $p = $l[0]
        Write-PLog ('{0}: {1} (Version {2})' -f $o.SurfName, $p.File, $p.Version)
        $dir = if ($o.SurfDest) { [string]$o.SurfDest } else { Join-Path $DataDir 'Surface' }
        $msi = Join-Path $dir $p.File
        if ((Test-Path -LiteralPath $msi) -and (Get-Item -LiteralPath $msi).Length -gt 50MB) { Write-PLog '   Paket liegt schon vor - Download übersprungen.' 'OK' }
        else { Save-Download $p.Url $msi $p.File }
        $sig = Get-AuthenticodeSignature -FilePath $msi
        if ($sig.Status -ne 'Valid' -or $sig.SignerCertificate.Subject -notmatch 'Microsoft') { Remove-Item -LiteralPath $msi -Force -ErrorAction SilentlyContinue; throw ('Signatur ungültig ({0}) - abgebrochen.' -f $sig.Status) }
        Write-PLog ('   Gespeichert: {0} ({1:N0} MB), signiert von Microsoft.' -f $msi, ((Get-Item -LiteralPath $msi).Length / 1MB)) 'OK'
        Set-Content -LiteralPath (Join-Path $dir 'LIESMICH.txt') -Encoding UTF8 -Value @(('Surface-Treiberpaket für: {0}' -f $o.SurfName), ('Datei: {0}' -f $p.File), '', 'Auf dem Surface: PC-Tools vom Stick starten > Microsoft Surface > "Paket vom Stick installieren"', 'oder nur die Netzwerktreiber: "Nur Netzwerk-/WLAN-Treiber aus dem Paket".', 'Ohne PC-Tools: Doppelklick auf die .msi-Datei.')
        if ($o.SurfMode -eq 'Save') { return }
    }
    if (-not (Test-Path -LiteralPath $msi)) { throw ('Datei nicht gefunden: ' + $msi) }
    $si = Get-SurfaceInfo
    Write-PLog ('Gerät: {0} (SKU {1}), Paket: {2}' -f $si.Model, $si.Sku, [IO.Path]::GetFileName($msi))
    try { Invoke-DsBeforeDriverUpdate 'Surface-Treiber- und Firmwarepaket' } catch { }
    Install-SurfaceMsi $msi $(if ($o.SurfMode -eq 'Net') { 'Net' } else { 'Full' })
}

# ================================================================ PC-Tools 9.0: Toolbox, Kiosk, Hardware-Test, Score, Notfall-Stick, Fernhilfe, Netzwerk-Werkzeuge, Geräte-Akte
# =====================================================================
#  TOOLBOX (Admin- und Diagnose-Werkzeuge) und SOFTWARE-KIOSK (Daten + Engine-Teile)
# =====================================================================
# Toolbox-Katalog. Kind:
#   Zip    = feste ZIP-Adresse(n) (Urls, erste erreichbare gewinnt)
#   Exe    = feste EXE-Adresse(n) (Einzeldatei)
#   GitHub = neuestes Release über die GitHub-API (Repo, Asset = Regex auf den Dateinamen)
#   Scrape = Herstellerseite(n) (Pages) nach Regex (Rx mit Gruppe v = Version) durchsuchen, Download-Adresse(n) aus UrlFmt ({0} = Version)
#   Winget = keine portable Version - Installation auf dem PC über winget (WingetId, Arp = Regex auf den Namen in "Programme und Features", Paths = mögliche Programmdateien)
# Exe = Liste von Regex auf den Dateinamen der Programmdatei (erste passende gewinnt, 64-Bit zuerst). Menu = Auswahlliste statt einer Programmdatei (Suite).
# Signer = erwarteter Unterzeichner (Regex) - wird nur geprüft, wenn die Datei signiert ist. VerRx = Version aus der (umgeleiteten) Download-Adresse.
$TbCategories = @('System', 'Hardware', 'Datenträger', 'Netzwerk', 'USB', 'Fernhilfe')
$TbCatalog = @(
    [ordered]@{ Key = 'SysSuite'; Name = 'Sysinternals Suite'; Cat = 'System'; Glyph = 0xE7EF; Color = '#2563EB'; Portable = $true; Kind = 'Zip'
        Urls = @('https://download.sysinternals.com/files/SysinternalsSuite.zip'); Exe = @(); Menu = $true; Args = '/accepteula'; Signer = 'Microsoft'; Eula = ''
        Desc = 'Alle rund 70 Sysinternals-Werkzeuge von Microsoft in einem Paket: Process Explorer, Autoruns, PsTools, Sigcheck, TCPView und viele mehr. "Starten" zeigt eine Auswahlliste.' }
    [ordered]@{ Key = 'Autoruns'; Name = 'Autoruns'; Cat = 'System'; Glyph = 0xE7E8; Color = '#16A34A'; Portable = $true; Kind = 'Zip'
        Urls = @('https://download.sysinternals.com/files/Autoruns.zip'); Exe = @('^Autoruns64\.exe$', '^Autoruns\.exe$'); Args = '/accepteula'; Signer = 'Microsoft'; Eula = 'AutoRuns'
        Desc = 'Zeigt alles, was mit Windows automatisch startet: Autostart, Dienste, Treiber, geplante Aufgaben, Explorer-Erweiterungen. Ideal gegen Bremsen und Schadsoftware.' }
    [ordered]@{ Key = 'ProcExp'; Name = 'Process Explorer'; Cat = 'System'; Glyph = 0xE9D9; Color = '#2D7FF9'; Portable = $true; Kind = 'Zip'
        Urls = @('https://download.sysinternals.com/files/ProcessExplorer.zip'); Exe = @('^procexp64\.exe$', '^procexp\.exe$'); Args = '/accepteula'; Signer = 'Microsoft'; Eula = 'Process Explorer'
