    [ordered]@{ Key = 'ProcMon'; Name = 'Process Monitor'; Cat = 'System'; Glyph = 0xE81C; Color = '#7C3AED'; Portable = $true; Kind = 'Zip'
        Urls = @('https://download.sysinternals.com/files/ProcessMonitor.zip'); Exe = @('^Procmon64\.exe$', '^Procmon\.exe$'); Args = '/accepteula'; Signer = 'Microsoft'; Eula = 'Process Monitor'
