# Engine-Teil "SurfaceAll": neuestes Treiber-/Firmwarepaket ALLER Surface-Modelle in einen Ordner laden (z.B. NAS)
function Invoke-SurfaceAllJob {
    $o = $Script:JobOpts
    $dest = [string]$o.SurfAllDest; if (-not $dest) { throw 'Kein Zielordner angegeben.' }
    if (-not (Test-Path -LiteralPath $dest)) { New-Item $dest -ItemType Directory -Force | Out-Null }
    $win = $(if ($o.SurfWin) { [int]$o.SurfWin } else { 11 })
    $models = @($SurfaceModels | Where-Object { $_.Id })
    $n = $models.Count; $i = 0; $ok = 0; $skip = 0; $fail = 0; $bytes = [int64]0
    Write-PLog ('Surface: neueste Pakete für {0} Modelle (Windows {1}) nach {2}' -f $n, $win, $dest)
    foreach ($m in $models) {
        if (Test-PCancel) { Write-PLog 'Abgebrochen durch Benutzer.' 'WARN'; break }
        $i++
        $Script:Detail = ('Surface {0}/{1}: {2}' -f $i, $n, $m.N); Set-PStatus $Script:Detail ([int](($i - 1) * 100 / [math]::Max(1, $n)))
        try {
            $l = @(Get-SurfaceMsiList ([int]$m.Id) $win 0 | Where-Object { $_.Kind -eq 'MSI' })
            if (-not $l.Count) { Write-PLog ('   {0}: kein MSI-Paket (nur ZIP oder Windows Update) - übersprungen' -f $m.N) 'WARN'; $skip++; continue }
            $p = $l[0]
            $md = Join-Path $dest (($m.N -replace '[\\/:*?"<>|]', '_').Trim())
            if (-not (Test-Path -LiteralPath $md)) { New-Item $md -ItemType Directory -Force | Out-Null }
            $msi = Join-Path $md $p.File
            if ((Test-Path -LiteralPath $msi) -and (Get-Item -LiteralPath $msi).Length -gt 50MB) { Write-PLog ('   {0}: {1} liegt schon vor - übersprungen' -f $m.N, $p.File) 'OK'; $skip++; continue }
            Write-PLog ('   {0}: lade {1} (Version {2})' -f $m.N, $p.File, $p.Version)
            Save-Download $p.Url $msi $p.File
            $sig = Get-AuthenticodeSignature -FilePath $msi
            if ($sig.Status -ne 'Valid' -or $sig.SignerCertificate.Subject -notmatch 'Microsoft') { Remove-Item -LiteralPath $msi -Force -ErrorAction SilentlyContinue; Write-PLog ('   {0}: Signatur ungültig ({1}) - verworfen' -f $m.N, $sig.Status) 'WARN'; $fail++; continue }
            $sz = (Get-Item -LiteralPath $msi).Length; $bytes += $sz
            Set-Content -LiteralPath (Join-Path $md 'LIESMICH.txt') -Encoding UTF8 -Value @(('Surface-Treiberpaket für: {0}' -f $m.N), ('Datei: {0}' -f $p.File), ('Version: {0}' -f $p.Version), '', 'Auf dem Surface: PC-Tools > Microsoft Surface > "Paket vom Stick installieren".')
            Write-PLog ('   {0}: gespeichert ({1:N0} MB), signiert von Microsoft.' -f $m.N, ($sz / 1MB)) 'OK'; $ok++
        } catch { Write-PLog ('   {0}: Fehler - {1}' -f $m.N, $_.Exception.Message) 'WARN'; $fail++ }
    }
    Write-PLog ('Fertig: {0} geladen, {1} übersprungen, {2} fehlgeschlagen - gesamt {3:N1} GB in {4}' -f $ok, $skip, $fail, ($bytes / 1GB), $dest) 'OK'
}
function Get-TbDir { Join-Path $DataDir 'Toolbox' }
function Get-TbTool([string]$Key) { $TbCatalog | Where-Object { $_.Key -eq $Key } | Select-Object -First 1 }
function Read-TbMeta([string]$Dir, [string]$Key) {
    $f = Join-Path (Join-Path $Dir $Key) 'toolbox.json'
    if (-not [IO.File]::Exists($f)) { return $null }
    try { return (Get-Content -LiteralPath $f -Raw -Encoding UTF8 | ConvertFrom-Json) } catch { return $null }
}
# Neueste Version beim Hersteller ermitteln (ohne Skript-Variablen - läuft auch in Invoke-Bg; braucht Get-WebHtml)
function Get-TbRemoteInfo($T) {
    try { [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12 } catch { }
    $ua = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/140.0.0.0 Safari/537.36 Edg/140.0.0.0'
    $info = [ordered]@{ Url = ''; Urls = @(); Version = ''; RemoteVer = ''; File = ''; ETag = ''; LastModified = ''; Length = [int64]0 }
    switch ([string]$T.Kind) {
        'GitHub' {
            $rel = Invoke-RestMethod -Uri ('https://api.github.com/repos/{0}/releases/latest' -f $T.Repo) -Headers @{ 'User-Agent' = 'PC-Tools'; 'Accept' = 'application/vnd.github+json' } -TimeoutSec 30 -ErrorAction Stop
            $asset = @($rel.assets | Where-Object { [string]$_.name -match $T.Asset }) | Select-Object -First 1
            if (-not $asset) { throw ('Im Release {0} gibt es keine passende Datei ({1}).' -f $rel.tag_name, $T.Asset) }
            $info.Url = [string]$asset.browser_download_url; $info.Urls = @($info.Url); $info.File = [string]$asset.name; $info.Length = [int64]$asset.size
            $info.RemoteVer = ([string]$rel.tag_name) -replace '^[vV]', ''; $info.Version = $info.RemoteVer
        }
        'Scrape' {
            $found = [System.Collections.Generic.List[string]]::new(); $errs = @()
            foreach ($pg in @($T.Pages)) {
                try {
                    $html = Get-WebHtml $pg
                    foreach ($m in [regex]::Matches($html, $T.Rx, 'IgnoreCase')) { $v = $m.Groups['v'].Value; if ($v -and -not $found.Contains($v)) { $found.Add($v) } }
                } catch { $errs += $_.Exception.Message }
                if ($found.Count) { break }
            }
            if (-not $found.Count) { throw ('Auf der Herstellerseite wurde kein Download gefunden{0}.' -f $(if ($errs.Count) { ' (' + ($errs -join '; ') + ')' } else { '' })) }
            $best = $found | Sort-Object { $p = @(([string]$_).Split('.') | ForEach-Object { [int]$_ }); while ($p.Count -lt 4) { $p += 0 }; '{0:D6}{1:D6}{2:D6}{3:D6}' -f $p[0], $p[1], $p[2], $p[3] } -Descending | Select-Object -First 1
            $info.RemoteVer = $best
            $info.Version = if ($T.VerStyle -eq 'Hwi' -and $best -match '^(\d)(\d+)$') { '{0}.{1}' -f $Matches[1], $Matches[2] } else { $best }
            $info.Urls = @($T.UrlFmt | ForEach-Object { $_ -f $best }); $info.Url = $info.Urls[0]
            $info.File = [IO.Path]::GetFileName(([uri]$info.Url).AbsolutePath)
        }
        default {
            $info.Urls = @($T.Urls); $info.Url = $info.Urls[0]
            foreach ($u in $info.Urls) {
                try {
                    $resp = Invoke-WebRequest -Uri $u -Method Head -UseBasicParsing -UserAgent $ua -TimeoutSec 30 -MaximumRedirection 5 -ErrorAction Stop
                    $info.Url = $u
                    foreach ($hk in @($resp.Headers.Keys)) {
                        $hv = (@($resp.Headers[$hk]) -join ',').Trim()
                        switch ([string]$hk) { 'ETag' { $info.ETag = $hv.Trim('"') } 'Last-Modified' { $info.LastModified = $hv } 'Content-Length' { try { $info.Length = [int64]$hv } catch { } } }
                    }
                    $final = ''; try { $final = [string]$resp.BaseResponse.ResponseUri.AbsoluteUri } catch { }
                    if (-not $final) { try { $final = [string]$resp.BaseResponse.RequestMessage.RequestUri.AbsoluteUri } catch { } }
                    if ($T.VerRx -and $final -match $T.VerRx) { $info.RemoteVer = $Matches['v']; $info.Version = $info.RemoteVer }
                    break
                } catch { }
            }
            # Erreichbare Adresse zuerst, die anderen als Ausweich
            $info.Urls = @(@($info.Url) + @($info.Urls | Where-Object { $_ -ne $info.Url }))
            $info.File = [IO.Path]::GetFileName(([uri]$info.Url).AbsolutePath)
        }
    }
    return [pscustomobject]$info
}
# Ist beim Hersteller etwas Neueres als das Geladene? (Version, sonst Datum/ETag/Größe der Datei)
function Test-TbNewer($Meta, $Remote) {
    if (-not $Remote) { return $false }
    if (-not $Meta) { return $true }
    if ($Remote.RemoteVer) { return ([string]$Remote.RemoteVer -ne [string]$Meta.RemoteVer) }
    if ($Remote.LastModified -and $Meta.LastModified) { return ([string]$Remote.LastModified -ne [string]$Meta.LastModified) }
    if ($Remote.ETag -and $Meta.ETag) { return ([string]$Remote.ETag -ne [string]$Meta.ETag) }
    if ([int64]$Remote.Length -gt 0 -and [int64]$Meta.Length -gt 0) { return ([int64]$Remote.Length -ne [int64]$Meta.Length) }
    return $false
}
function Find-TbExe([string]$Folder, [string[]]$Patterns) {
    $all = @(Get-ChildItem -LiteralPath $Folder -Recurse -File -ErrorAction SilentlyContinue | Where-Object { $_.Extension -eq '.exe' } | Sort-Object { $_.FullName.Length })
    foreach ($p in $Patterns) {
        $hit = $all | Where-Object { $_.Name -match $p } | Select-Object -First 1
        if ($hit) { return $hit.FullName.Substring($Folder.TrimEnd('\').Length + 1) }
    }
    return ''
}
function Get-TbFileVersion([string]$File) {
    try {
        $vi = (Get-Item -LiteralPath $File).VersionInfo
        foreach ($v in @($vi.ProductVersion, $vi.FileVersion)) {
            $m = [regex]::Match(([string]$v -replace ',\s*', '.'), '\d+(\.\d+)+')
            if ($m.Success) { $x = $m.Value; while ($x -match '^\d+\.\d+.*\.0$' -and ($x.Split('.').Count -gt 2)) { $x = $x -replace '\.0$', '' }; return $x }
        }
    } catch { }
    return ''
}
# Authenticode: signierte Dateien müssen gültig sein (und zum erwarteten Hersteller passen); unsignierte werden nur vermerkt
function Test-TbSignatures([string]$Folder, [string]$MainExe, [string]$Signer) {
    $res = [pscustomobject]@{ Ok = $true; Signed = 0; Unsigned = 0; Bad = [System.Collections.Generic.List[string]]::new(); MainSigner = ''; MainStatus = '' }
    $files = @(Get-ChildItem -LiteralPath $Folder -Recurse -File -ErrorAction SilentlyContinue | Where-Object { $_.Extension -in '.exe', '.msi' })
    foreach ($f in $files) {
        $sig = $null; try { $sig = Get-AuthenticodeSignature -FilePath $f.FullName -ErrorAction Stop } catch { }
        $st = if ($sig) { [string]$sig.Status } else { 'UnknownError' }
        $subj = if ($sig -and $sig.SignerCertificate) { [string]$sig.SignerCertificate.Subject } else { '' }
        $isMain = $MainExe -and ($f.FullName -eq $MainExe)
        if ($isMain) { $res.MainStatus = $st; $res.MainSigner = (([regex]::Match($subj, 'CN=("[^"]+"|[^,]+)').Groups[1].Value).Trim('"')) }
        switch ($st) {
            'Valid' {
                $res.Signed++
                if ($Signer -and $subj -notmatch $Signer -and ($isMain -or -not $MainExe)) { $res.Bad.Add(('{0}: unerwarteter Unterzeichner ({1})' -f $f.Name, $subj)) }
            }
            'NotSigned' { $res.Unsigned++ }
            'UnknownError' { $res.Unsigned++ }
            default { $res.Bad.Add(('{0}: Signatur {1}' -f $f.Name, $st)) }
        }
    }
    if ($res.Bad.Count) { $res.Ok = $false }
    return $res
}
# Ein Werkzeug laden, prüfen und (atomar) in den Toolbox-Ordner übernehmen. Rückgabe: 'neu' | 'aktuell'
function Save-TbTool($T, [string]$Dir, [bool]$Force) {
    $meta = Read-TbMeta $Dir $T.Key
    $dest = Join-Path $Dir $T.Key
    $Script:Detail = ('{0}: neueste Version beim Hersteller ermitteln' -f $T.Name); Set-PStatus $Script:StatusText
    $rem = Get-TbRemoteInfo $T
    Write-PLog ('   Quelle: {0}{1}' -f $rem.Url, $(if ($rem.Version) { '  (Version ' + $rem.Version + ')' } else { '' }))
    $haveExe = $meta -and ((-not $meta.Exe -and $T.Menu) -or ($meta.Exe -and (Test-Path -LiteralPath (Join-Path $dest $meta.Exe))))
    if ($haveExe -and -not $Force -and -not (Test-TbNewer $meta $rem)) { $sd = ''; try { $sd = ([datetime]$meta.Date).ToString('dd.MM.yyyy') } catch { }; Write-PLog ('   bereits aktuell ({0})' -f $(if ($meta.Version) { $meta.Version } else { 'geladen am ' + $sd })) 'OK'; return 'aktuell' }
    $tmp = Join-Path $Dir ('_neu_' + $T.Key)
    $old = Join-Path $Dir ('_alt_' + $T.Key)
    Remove-Item -LiteralPath $tmp -Recurse -Force -ErrorAction SilentlyContinue
    New-Item -Path $tmp -ItemType Directory -Force | Out-Null
    try {
        $name = if ($rem.File) { $rem.File } else { $T.Key + '.bin' }
        $file = Join-Path $tmp $name
        $got = ''; $err = ''
        foreach ($u in @($rem.Urls)) {
            try {
                Save-Download $u $file $T.Name
                if ((Test-Path -LiteralPath $file) -and (Get-Item -LiteralPath $file).Length -gt 20KB) { $got = $u; break }
                $err = 'Datei leer oder zu klein (Fehlerseite statt Download?)'
            } catch { $err = $_.Exception.Message; if ($err -match 'Abgebrochen') { throw }; Write-PLog ('   {0}: {1} - versuche nächste Quelle' -f $u, $err) 'WARN' }
        }
        if (-not $got) { throw ('Download fehlgeschlagen: {0}' -f $err) }
        $size = (Get-Item -LiteralPath $file).Length
        $content = Join-Path $tmp 'inhalt'
        New-Item -Path $content -ItemType Directory -Force | Out-Null
        if ($file -match '\.zip$') {
            $Script:Detail = ('{0}: entpacken' -f $T.Name); Set-PStatus $Script:StatusText
            try { Expand-Archive -LiteralPath $file -DestinationPath $content -Force -ErrorAction Stop }
            catch { Add-Type -AssemblyName System.IO.Compression.FileSystem; [IO.Compression.ZipFile]::ExtractToDirectory($file, $content) }
            Remove-Item -LiteralPath $file -Force -ErrorAction SilentlyContinue
        } else {
            $target = $name; if ($target -notmatch '\.exe$') { $target = $T.Key + '.exe' }
            Move-Item -LiteralPath $file -Destination (Join-Path $content $target) -Force
        }
        Get-ChildItem -LiteralPath $content -Recurse -File -ErrorAction SilentlyContinue | Unblock-File -ErrorAction SilentlyContinue
        $exeRel = ''
        if (@($T.Exe).Count) {
            $exeRel = Find-TbExe $content @($T.Exe)
            if (-not $exeRel) { throw 'Programmdatei im Paket nicht gefunden - der Hersteller hat den Aufbau geändert.' }
        }
        $Script:Detail = ('{0}: digitale Signatur prüfen' -f $T.Name); Set-PStatus $Script:StatusText
        $main = if ($exeRel) { Join-Path $content $exeRel } else { '' }
        $sig = Test-TbSignatures $content $main ([string]$T.Signer)
        if (-not $sig.Ok) { throw ('Signaturprüfung fehlgeschlagen - Dateien verworfen: {0}' -f (($sig.Bad | Select-Object -First 3) -join '; ')) }
        if ($main) {
            if ($sig.MainStatus -eq 'Valid') { Write-PLog ('   Signatur gültig: {0}' -f $sig.MainSigner) 'OK' }
            else { Write-PLog '   Programmdatei ist vom Hersteller nicht digital signiert (bei diesem Hersteller üblich) - Download nur von der offiziellen Adresse.' }
        } else { Write-PLog ('   Signaturen: {0} gültig signiert, {1} ohne Signatur, keine ungültige' -f $sig.Signed, $sig.Unsigned) 'OK' }
        $ver = if ($rem.Version) { $rem.Version } elseif ($main) { Get-TbFileVersion $main } else { '' }
        if (-not $ver -and $rem.LastModified) { try { $ver = 'Stand ' + ([datetime]::Parse($rem.LastModified)).ToString('dd.MM.yyyy') } catch { } }
        Set-Content -LiteralPath (Join-Path $content 'toolbox.json') -Encoding UTF8 -Value (([ordered]@{
            Key = $T.Key; Name = $T.Name; Version = $ver; RemoteVer = $rem.RemoteVer; Date = (Get-Date).ToString('s'); Source = $got; File = $name; Exe = $exeRel
            Size = $size; ETag = $rem.ETag; LastModified = $rem.LastModified; Length = $rem.Length; Signer = $sig.MainSigner; SigStatus = $sig.MainStatus; Kind = $T.Kind; Portable = $true
        }) | ConvertTo-Json)
        # Austausch: alten Ordner umbenennen (schlägt fehl, wenn das Programm läuft), neuen einsetzen, alten löschen
        Remove-Item -LiteralPath $old -Recurse -Force -ErrorAction SilentlyContinue
        if (Test-Path -LiteralPath $dest) {
            try { Rename-Item -LiteralPath $dest -NewName ('_alt_' + $T.Key) -ErrorAction Stop }
            catch { throw ('Die vorhandene Version lässt sich nicht ersetzen - läuft {0} gerade? Bitte schließen und erneut laden.' -f $T.Name) }
        }
        Move-Item -LiteralPath $content -Destination $dest -ErrorAction Stop
        Remove-Item -LiteralPath $old -Recurse -Force -ErrorAction SilentlyContinue
        Write-PLog ('   {0} {1} geladen ({2:N1} MB){3}' -f $T.Name, $ver, ($size / 1MB), $(if ($exeRel) { ' - Programm: ' + $exeRel } else { '' })) 'OK'
        return 'neu'
    } finally {
        Remove-Item -LiteralPath $tmp -Recurse -Force -ErrorAction SilentlyContinue
        if ((Test-Path -LiteralPath $old) -and -not (Test-Path -LiteralPath $dest)) { try { Rename-Item -LiteralPath $old -NewName $T.Key -ErrorAction Stop } catch { } }
    }
}
# Engine-Teil "ToolboxLoad": Optionen $Script:JobOpts.Tools (Schlüssel), .Force (auch aktuelle neu laden)
function Invoke-TbLoadJob {
    $o = $Script:JobOpts
    $dir = Get-TbDir
    New-Item -Path $dir -ItemType Directory -Force | Out-Null
    $want = @($o.Tools | ForEach-Object { [string]$_ } | Where-Object { $_ })
    $list = @($TbCatalog | Where-Object { $want -contains $_.Key })
    if (-not $list.Count) { Write-PLog 'Toolbox: keine Werkzeuge ausgewählt.' 'WARN'; return }
    $force = [bool]$o.Force
    Write-PLog ('Toolbox-Ordner: {0}{1}' -f $dir, $(if ($Script:IsPortable) { ' (auf dem USB-Stick)' } else { '' }))
    $readme = Join-Path $dir 'LIESMICH.txt'
    if (-not (Test-Path -LiteralPath $readme)) {
        Set-Content -LiteralPath $readme -Encoding UTF8 -Value @('PC-Tools - Toolbox', '', 'Jedes Werkzeug liegt in einem eigenen Unterordner, die Datei toolbox.json darin nennt Version, Quelle, Datum und Programmdatei.', 'Alle Programme sind portabel und laufen auch direkt per Doppelklick - am bequemsten über PC-Tools > Toolbox.', 'Ordner beginnend mit _neu_ oder _alt_ sind Reste eines abgebrochenen Downloads und können gelöscht werden.')
    }
    $ok = 0; $same = 0; $n = 0
    $fail = [System.Collections.Generic.List[string]]::new()
    $wg = [System.Collections.Generic.List[object]]::new()
    $pn = @($list | Where-Object { $_.Kind -ne 'Winget' }).Count
    foreach ($t in $list) {
        if (Test-PCancel) { Write-PLog 'Abgebrochen durch Benutzer' 'WARN'; break }
        if ($t.Kind -eq 'Winget') { $wg.Add($t); continue }
        $n++
        Set-PStatus ('Toolbox: {0} ({1}/{2})' -f $t.Name, $n, $pn) ([int](($n - 1) * 100 / [math]::Max(1, $pn)))
        Write-PLog ('>> {0} ({1}/{2})' -f $t.Name, $n, $pn)
        try { if ((Save-TbTool $t $dir $force) -eq 'aktuell') { $same++ } else { $ok++ } }
        catch { $fail.Add($t.Name); Write-PLog ('   {0}: {1}' -f $t.Name, $_.Exception.Message) 'WARN'; if ($_.Exception.Message -match 'Abgebrochen') { break } }
    }
    if ($wg.Count -and -not (Test-PCancel)) {
        Write-PLog ('>> Ohne portable Version, Installation auf diesem PC über winget: {0}' -f (($wg | ForEach-Object { $_.Name }) -join ', '))
        if ($Script:IsPortable) { Write-PLog '   Hinweis: diese Programme landen auf diesem PC, nicht auf dem Stick.' }
        $keep = $Script:WingetApps
        try { $Script:WingetApps = @($wg | ForEach-Object { $_.WingetId }); Invoke-WingetInstall }
        finally { $Script:WingetApps = $keep }
        foreach ($t in $wg) {
            $d = Join-Path $dir $t.Key; New-Item -Path $d -ItemType Directory -Force | Out-Null
            Set-Content -LiteralPath (Join-Path $d 'toolbox.json') -Encoding UTF8 -Value (([ordered]@{ Key = $t.Key; Name = $t.Name; Version = ''; RemoteVer = ''; Date = (Get-Date).ToString('s'); Source = 'winget:' + $t.WingetId; Exe = ''; Kind = 'Winget'; Portable = $false; Computer = $env:COMPUTERNAME }) | ConvertTo-Json)
        }
    }
    $sum = 'Toolbox: {0} neu geladen, {1} bereits aktuell{2}{3}' -f $ok, $same, $(if ($wg.Count) { (', {0} per winget' -f $wg.Count) } else { '' }), $(if ($fail.Count) { ' - fehlgeschlagen: ' + ($fail -join ', ') } else { '' })
    Write-PLog $sum $(if ($fail.Count) { 'WARN' } else { 'OK' })
}
# Engine-Teil "ToolboxCopy": Toolbox-Ordner neben die portable PC-Tools auf ein Laufwerk spiegeln (<Ziel>\PCPflege\Daten\Toolbox)
function Invoke-TbCopyJob {
    $o = $Script:JobOpts
    $src = Get-TbDir
    $target = [string]$o.Target
    if (-not $target) { throw 'Kein Ziel angegeben.' }
    if (-not (Test-Path -LiteralPath $src)) { throw 'Die Toolbox ist noch leer - bitte zuerst Werkzeuge laden.' }
    $root = if ((Split-Path $target -Leaf) -eq 'PCPflege') { $target } else { Join-Path $target 'PCPflege' }
    $dst = Join-Path (Join-Path $root 'Daten') 'Toolbox'
    if ([IO.Path]::GetFullPath($dst).TrimEnd('\') -eq [IO.Path]::GetFullPath($src).TrimEnd('\')) { Write-PLog 'Die Toolbox liegt bereits an diesem Ort - nichts zu kopieren.' 'OK'; return }
    $need = [int64]0; Get-ChildItem -LiteralPath $src -Recurse -File -ErrorAction SilentlyContinue | ForEach-Object { $need += $_.Length }
    try {
        $drv = New-Object IO.DriveInfo ([IO.Path]::GetPathRoot([IO.Path]::GetFullPath($root)))
        if ($drv.IsReady -and $drv.AvailableFreeSpace -lt ($need + 50MB)) { throw ('Auf {0} ist zu wenig Platz frei ({1:N0} MB frei, {2:N0} MB nötig).' -f $drv.Name, ($drv.AvailableFreeSpace / 1MB), ($need / 1MB)) }
    } catch [System.ArgumentException] { }
    if ($o.WithApp -and -not (Test-Path -LiteralPath (Join-Path $root 'PCPflege.ps1'))) {
        Set-PStatus 'Portable PC-Tools auf das Ziel kopieren'
        try { Copy-PortablePflege $root $false; Write-PLog ('Portable PC-Tools kopiert nach {0}' -f $root) 'OK' } catch { Write-PLog ('Portable PC-Tools: {0}' -f $_.Exception.Message) 'WARN' }
    }
    New-Item -Path $dst -ItemType Directory -Force | Out-Null
    $Script:Detail = ('{0:N0} MB nach {1}' -f ($need / 1MB), $dst); Set-PStatus 'Toolbox wird kopiert'
    Write-PLog ('Kopiere Toolbox ({0:N0} MB) nach {1} (Spiegelung - veraltete Dateien auf dem Ziel werden entfernt)' -f ($need / 1MB), $dst)
    $rc = Invoke-External -Exe (Join-Path $env:SystemRoot 'System32\robocopy.exe') -Arguments @(('"{0}"' -f $src), ('"{0}"' -f $dst), '/MIR', '/R:1', '/W:1', '/NP', '/NJH', '/NFL', '/NDL', '/XD', '_neu_*', '_alt_*') -TimeoutMin 120 -Quiet
    if ($rc -ge 0 -and $rc -lt 8) { Write-PLog ('Toolbox liegt jetzt auf {0} - am Ziel-PC "PC-Tools starten.cmd" öffnen, Seite Toolbox.' -f $dst) 'OK' }
    else { Write-PLog ('Kopieren meldet Fehler (robocopy-Code {0}) - ist das Ziel schreibgeschützt oder voll?' -f $rc) 'WARN' }
}

# ---------------------------------------------------------------- Toolbox: automatisch aktuell halten (eigener Hintergrundprozess -TbSync, blockiert keine andere Aufgabe)
function Get-TbPortableKeys { @($TbCatalog | Where-Object { $_.Kind -ne 'Winget' } | ForEach-Object { [string]$_.Key }) }
function Invoke-TbAutoSync($Cfg) {
    $dir = Get-TbDir
    New-Item -Path $dir -ItemType Directory -Force | Out-Null
    $lock = Join-Path $dir 'sync.lock'
    if ([IO.File]::Exists($lock)) {
        $old = 0; try { $old = [int](Get-Content -LiteralPath $lock -Raw).Trim() } catch { }
        if ($old -and $old -ne $PID -and (Get-Process -Id $old -ErrorAction SilentlyContinue)) { return }
    }
    Set-Content -LiteralPath $lock -Value $PID -Encoding ASCII
    $Script:LogFile = Join-Path $dir 'sync.log'
    $Script:StatusFile = Join-Path $dir 'sync.status.json'
    $Script:CancelFile = Join-Path $dir 'sync.cancel'   # Invoke-TbLoadJob löscht $Script:CancelFile - darf nicht $null sein
    Set-Content -LiteralPath $Script:LogFile -Value ('PC-Tools {0} - Toolbox automatisch aktualisieren ({1:dd.MM.yyyy HH:mm})' -f $AppVersion, (Get-Date)) -Encoding UTF8
    $ok = $true
    try {
        $rc = Join-Path $env:SystemRoot 'System32\robocopy.exe'
        $nas = $null
        try { if ($Cfg -and $Cfg.Fleet.Enabled -and $Cfg.Fleet.Dir) { $nas = Join-Path ([string]$Cfg.Fleet.Dir) 'Toolbox' } } catch { }
        if ($nas -and (Test-Path -LiteralPath $nas)) {
            Set-PStatus 'Toolbox: neuere Werkzeuge vom gemeinsamen Ordner holen' 2
            Write-PLog ('Gemeinsamer Ordner (Meine PCs): {0} - nur neuere Dateien werden übernommen' -f $nas)
            $null = Invoke-External -Exe $rc -Arguments @(('"{0}"' -f $nas), ('"{0}"' -f $dir), '/E', '/XO', '/R:1', '/W:1', '/NP', '/NJH', '/NFL', '/NDL', '/XD', '_neu_*', '_alt_*', '/XF', 'sync.*') -TimeoutMin 30 -Quiet
        }
        $Script:JobOpts = [pscustomobject]@{ Tools = @(Get-TbPortableKeys); Force = $false }
        Invoke-TbLoadJob
        if ($nas) {
            try {
                if (-not (Test-Path -LiteralPath $nas)) { New-Item -Path $nas -ItemType Directory -Force -ErrorAction Stop | Out-Null }
                Set-PStatus 'Toolbox: gemeinsamen Ordner aktualisieren' 98
                $null = Invoke-External -Exe $rc -Arguments @(('"{0}"' -f $dir), ('"{0}"' -f $nas), '/E', '/XO', '/R:1', '/W:1', '/NP', '/NJH', '/NFL', '/NDL', '/XD', '_neu_*', '_alt_*', '/XF', 'sync.*', 'updates.json') -TimeoutMin 30 -Quiet
                Write-PLog 'Gemeinsamer Ordner aktualisiert - die anderen PCs holen die Werkzeuge von dort.' 'OK'
            } catch { Write-PLog ('Gemeinsamer Ordner nicht beschreibbar: {0}' -f $_.Exception.Message) 'WARN' }
        }
    } catch { $ok = $false; Write-PLog ('Automatische Aktualisierung: {0}' -f $_.Exception.Message) 'FEHLER' }
    finally {
        try { @{ Last = (Get-Date).ToString('o'); Ok = $ok; Summary = [string]$Script:LastLine; Warnings = $Script:Warnings } | ConvertTo-Json | Set-Content -LiteralPath (Join-Path $dir 'sync.json') -Encoding UTF8 } catch { }
        Set-PStatus 'fertig' 100 $false
        Remove-Item -LiteralPath $lock -Force -ErrorAction SilentlyContinue
    }
}
