$NtOui = @{}
foreach ($ntLine in ($NtOuiData -split "`r?`n")) {
    $ntParts = $ntLine -split '\|', 2
    if ($ntParts.Count -lt 2) { continue }
    foreach ($ntPre in ($ntParts[1] -split '\s+')) { if ($ntPre.Length -eq 6) { $NtOui[$ntPre.ToUpper()] = $ntParts[0] } }
}

# MAC vereinheitlichen: AA:BB:CC:DD:EE:FF (leer, wenn ungültig)
function Format-NtMac([string]$Mac) {
    $h = ($Mac -replace '[^0-9A-Fa-f]', '').ToUpper()
    if ($h.Length -ne 12) { return '' }
    return (($h -split '(..)' | Where-Object { $_ }) -join ':')
}
# Hersteller zur MAC; zufällige (lokal verwaltete) MACs werden als solche erkannt
function Get-NtVendor([string]$Mac, $Table) {
    $h = ($Mac -replace '[^0-9A-Fa-f]', '').ToUpper()
    if ($h.Length -lt 6) { return '' }
    $pre = $h.Substring(0, 6)
    if ($Table -and $Table.ContainsKey($pre)) { return [string]$Table[$pre] }
    $b0 = [Convert]::ToInt32($h.Substring(0, 2), 16)
    if ($b0 -band 2) { return 'Zufällige MAC (Datenschutz-Funktion von Handy/PC)' }
    return ''
}

# ---- IPv4-Rechenhilfen (reine Berechnung, ohne Windows testbar)
function ConvertTo-NtNum([string]$Ip) {
    $b = ([Net.IPAddress]::Parse($Ip)).GetAddressBytes()
    return ([long]$b[0] * 16777216 + [long]$b[1] * 65536 + [long]$b[2] * 256 + [long]$b[3])
}
function ConvertFrom-NtNum([long]$Num) {
    '{0}.{1}.{2}.{3}' -f ([long][math]::Floor($Num / 16777216) % 256), ([long][math]::Floor($Num / 65536) % 256), ([long][math]::Floor($Num / 256) % 256), ($Num % 256)
}
function Get-NtBroadcast([string]$Ip, [int]$Prefix) {
    if ($Prefix -lt 1 -or $Prefix -gt 32) { $Prefix = 24 }
    $size = [long][math]::Pow(2, 32 - $Prefix); $n = ConvertTo-NtNum $Ip
    return (ConvertFrom-NtNum ($n - ($n % $size) + $size - 1))
}
# Zu prüfende Adressen: das eigene Netz, höchstens das /24 rund um die eigene Adresse (254 Adressen)
function Get-NtSubnetHosts([string]$Ip, [int]$Prefix) {
    if ($Prefix -lt 24 -or $Prefix -gt 30) { $Prefix = 24 }
    $size = [long][math]::Pow(2, 32 - $Prefix); $n = ConvertTo-NtNum $Ip
    $net = $n - ($n % $size)
    $out = [System.Collections.Generic.List[string]]::new()
    for ($k = $net + 1; $k -lt $net + $size - 1; $k++) { $out.Add((ConvertFrom-NtNum $k)) }
    return , $out
}
function Get-NtIpSort([string]$Ip) { try { return ('{0:D12}' -f (ConvertTo-NtNum $Ip)) } catch { return $Ip } }

# ---- Aktiver Adapter (Standardroute mit der niedrigsten Metrik)
function Get-NtActiveNet {
    $best = $null; $bestMetric = [int]::MaxValue
    foreach ($r in @(Get-NetRoute -DestinationPrefix '0.0.0.0/0' -ErrorAction SilentlyContinue | Where-Object { $_.NextHop -and $_.NextHop -ne '0.0.0.0' })) {
        $ad = Get-NetAdapter -InterfaceIndex $r.ifIndex -ErrorAction SilentlyContinue
        if (-not $ad -or $ad.Status -ne 'Up') { continue }
        $im = 0; try { $im = [int](Get-NetIPInterface -InterfaceIndex $r.ifIndex -AddressFamily IPv4 -ErrorAction Stop).InterfaceMetric } catch { }
        $m = [int]$r.RouteMetric + $im
        if ($m -lt $bestMetric) { $bestMetric = $m; $best = [pscustomobject]@{ Route = $r; Adapter = $ad } }
    }
    if (-not $best) {
        $ad = @(Get-NetAdapter -ErrorAction SilentlyContinue | Where-Object { $_.Status -eq 'Up' } | Sort-Object ifIndex)[0]
        if (-not $ad) { return $null }
        $best = [pscustomobject]@{ Route = $null; Adapter = $ad }
    }
    $ad = $best.Adapter
    $addr = @(Get-NetIPAddress -InterfaceIndex $ad.ifIndex -AddressFamily IPv4 -ErrorAction SilentlyContinue | Where-Object { $_.IPAddress -notlike '169.254*' -and $_.IPAddress -notlike '127.*' })[0]
    $dns = @(Get-DnsClientServerAddress -InterfaceIndex $ad.ifIndex -AddressFamily IPv4 -ErrorAction SilentlyContinue | ForEach-Object { $_.ServerAddresses } | Where-Object { $_ })
    $isWifi = ([string]$ad.PhysicalMediaType -match '802\.11') -or ([string]$ad.InterfaceDescription -match 'Wi-?Fi|Wireless|WLAN|802\.11')
    $ipTxt = if ($addr) { [string]$addr.IPAddress } else { '' }
    $pl = if ($addr) { [int]$addr.PrefixLength } else { 24 }
    [pscustomobject]@{
        Name = [string]$ad.Name; Desc = [string]$ad.InterfaceDescription; Index = [int]$ad.ifIndex; Mac = (Format-NtMac ([string]$ad.MacAddress)); Speed = [string]$ad.LinkSpeed
        Ip = $ipTxt; Prefix = $pl; Gateway = $(if ($best.Route) { [string]$best.Route.NextHop } else { '' }); Dns = $dns
        Wifi = $isWifi; Kind = $(if ($isWifi) { 'WLAN' } else { 'LAN' }); Broadcast = $(if ($ipTxt) { Get-NtBroadcast $ipTxt $pl } else { '255.255.255.255' })
    }
}

# ---- Geräte im Netz: Ping-Suche, ARP, Namen, optional Anschlüsse. $Sync (synchronisierte Hashtable) meldet den Fortschritt.
$NtQuickPorts = @(80, 443, 22, 445, 3389, 8080, 554, 9100, 1883, 8123)
function Invoke-NtSweep($Net, [bool]$CheckPorts, [int[]]$PortList, $Sync) {
    $say = { param($p, $t) if ($Sync) { $Sync.P = $p; $Sync.T = $t } }
    & $say 3 'Sende Ping an alle Adressen ...'
    $targets = @(Get-NtSubnetHosts $Net.Ip $Net.Prefix | ForEach-Object { $_ })
    $pings = [System.Collections.Generic.List[object]]::new()
    foreach ($t in $targets) {
        if ($t -eq $Net.Ip) { continue }
        $pg = New-Object Net.NetworkInformation.Ping
        try { $pings.Add([pscustomobject]@{ Ip = $t; P = $pg; T = $pg.SendPingAsync($t, 1000) }) } catch { }
    }
    try { [void][Threading.Tasks.Task]::WaitAll([Threading.Tasks.Task[]]@($pings | ForEach-Object { $_.T }), 4000) } catch { }
    $found = @{}
    foreach ($p in $pings) {
        if ($p.T.Status -eq 'RanToCompletion' -and $p.T.Result.Status -eq 'Success') { $found[$p.Ip] = [pscustomobject]@{ Ip = $p.Ip; Rtt = [int]$p.T.Result.RoundtripTime; Via = 'Ping'; Mac = ''; Host = ''; Ports = @() } }
        try { $p.P.Dispose() } catch { }
    }
    & $say 40 ('{0} Geräte antworten auf Ping - lese ARP-Tabelle ...' -f $found.Count)
    # Geräte, die Ping blockieren (z.B. Windows-PCs mit Firewall, Handys), stehen trotzdem in der ARP-Tabelle
    $inNet = @{}; foreach ($t in $targets) { $inNet[$t] = $true }
    foreach ($nb in @(Get-NetNeighbor -AddressFamily IPv4 -InterfaceIndex $Net.Index -ErrorAction SilentlyContinue)) {
        $nip = [string]$nb.IPAddress; $mac = Format-NtMac ([string]$nb.LinkLayerAddress)
        if (-not $inNet.ContainsKey($nip) -or -not $mac -or $mac -eq '00:00:00:00:00:00' -or $mac -like 'FF:FF:FF*' -or $mac -like '01:00:5E*') { continue }
        if ([string]$nb.State -notin @('Reachable', 'Stale', 'Delay', 'Probe', 'Permanent')) { continue }
        if ($found.ContainsKey($nip)) { $found[$nip].Mac = $mac }
        else { $found[$nip] = [pscustomobject]@{ Ip = $nip; Rtt = -1; Via = 'ARP'; Mac = $mac; Host = ''; Ports = @() } }
    }
    $found[$Net.Ip] = [pscustomobject]@{ Ip = $Net.Ip; Rtt = 0; Via = 'Dieser PC'; Mac = $Net.Mac; Host = $env:COMPUTERNAME; Ports = @() }
    & $say 55 'Löse Gerätenamen auf ...'
    $dn = @{}; foreach ($k in @($found.Keys)) { if ($k -ne $Net.Ip) { try { $dn[$k] = [Net.Dns]::GetHostEntryAsync($k) } catch { } } }
    try { [void][Threading.Tasks.Task]::WaitAll([Threading.Tasks.Task[]]@($dn.Values), 3500) } catch { }
    foreach ($k in @($dn.Keys)) { $tk = $dn[$k]; if ($tk.Status -eq 'RanToCompletion' -and $tk.Result.HostName -and $tk.Result.HostName -ne $k) { $found[$k].Host = [string]$tk.Result.HostName } }
    if ($CheckPorts -and $PortList.Count) {
        $list = @($found.Keys | Where-Object { $_ -ne $Net.Ip } | Sort-Object { Get-NtIpSort $_ })
        for ($b = 0; $b -lt $list.Count; $b += 24) {
            & $say ([int](65 + 33 * $b / [math]::Max(1, $list.Count))) ('Prüfe Anschlüsse ({0} von {1} Geräten) ...' -f $b, $list.Count)
            $batch = @($list[$b..([math]::Min($b + 23, $list.Count - 1))]); $tasks = [System.Collections.Generic.List[object]]::new()
            foreach ($h in $batch) { foreach ($pt in $PortList) { $c = New-Object Net.Sockets.TcpClient; try { $tasks.Add([pscustomobject]@{ Ip = $h; Port = $pt; C = $c; T = $c.ConnectAsync($h, $pt) }) } catch { } } }
            try { [void][Threading.Tasks.Task]::WaitAll([Threading.Tasks.Task[]]@($tasks | ForEach-Object { $_.T }), 1500) } catch { }
            foreach ($t in $tasks) { if ($t.T.Status -eq 'RanToCompletion' -and $t.C.Connected) { $found[$t.Ip].Ports = @($found[$t.Ip].Ports) + $t.Port }; try { $t.C.Close() } catch { } }
        }
    }
    & $say 100 'Fertig.'
    @($found.Values | Sort-Object { Get-NtIpSort $_.Ip })
}
# Ergebnis mit dem letzten Scan vergleichen und Anzeigezeilen bauen (reine Datenaufbereitung)
function ConvertTo-NtDeviceRows($Raw, $Store, $Net, $Table) {
    $last = @{}; foreach ($k in @($Store.LastScan)) { $last[[string]$k] = $true }
    $known = @{}; foreach ($d in @($Store.Devices)) { if ($d) { $known[[string]$d.Key] = $d } }
    $names = @{}; if ($Store.Names) { foreach ($p in $Store.Names.PSObject.Properties) { $names[$p.Name] = [string]$p.Value } }
    $first = -not @($Store.LastScan).Count
    $rows = foreach ($d in @($Raw)) {
        if (-not $d -or -not $d.Ip) { continue }
        $key = if ($d.Mac) { [string]$d.Mac } else { 'IP:' + $d.Ip }
        $vendor = Get-NtVendor $d.Mac $Table
        $isGw = ($Net -and $d.Ip -eq $Net.Gateway); $isMe = ($d.Via -eq 'Dieser PC')
        $nm = if ($names.ContainsKey($key)) { $names[$key] } elseif ($d.Host) { ([string]$d.Host -replace '\.(fritz\.box|local|lan|home|localdomain|speedport\.ip)$', '') } else { '' }
        if (-not $nm) { $nm = if ($isGw) { 'Router' } elseif ($vendor -and $vendor -notlike 'Zufällige*') { '(' + ($vendor -split ' ')[0] + '-Gerät)' } else { '(unbekannt)' } }
        if ($isGw) { $nm += '  [Router]' }; if ($isMe) { $nm += '  [dieser PC]' }
        $isNew = (-not $first) -and (-not $last.ContainsKey($key)) -and -not $isMe
        $since = if ($known.ContainsKey($key) -and $known[$key].FirstSeen) { try { ([datetime]$known[$key].FirstSeen).ToString('dd.MM.yyyy') } catch { '' } } else { '' }
        [pscustomobject]@{
            Key = $key; Name = $nm; Ip = [string]$d.Ip; IpSort = (Get-NtIpSort $d.Ip); Mac = [string]$d.Mac; Vendor = $vendor; Host = [string]$d.Host
            Rtt = [int]$d.Rtt; RttText = $(if ($isMe) { '-' } elseif ($d.Rtt -lt 0) { 'blockt Ping' } elseif ($d.Rtt -eq 0) { '< 1 ms' } else { '{0} ms' -f $d.Rtt })
            PortList = @($d.Ports); Ports = (@($d.Ports | Sort-Object) -join ', ')
            IsNew = $isNew; NewText = $(if ($isNew) { 'NEU' } elseif ($first) { 'erster Scan' } elseif ($since) { 'bekannt seit ' + $since } else { 'bekannt' })
            Level = $(if ($isNew) { 'Warn' } elseif ($isMe) { 'Good' } else { '' }); Gateway = $isGw; Self = $isMe
        }
    }
    return , @($rows)
}
function Read-NtDevStore([string]$File) {
    $s = $null; try { if (Test-Path -LiteralPath $File) { $s = Get-Content -LiteralPath $File -Raw -Encoding UTF8 | ConvertFrom-Json } } catch { }
    if (-not $s) { $s = [pscustomobject]@{ Time = ''; Net = ''; LastScan = @(); Devices = @(); Names = [pscustomobject]@{} } }
    foreach ($p in 'LastScan', 'Devices') { if (-not $s.PSObject.Properties[$p]) { $s | Add-Member -NotePropertyName $p -NotePropertyValue @() } }
    if (-not $s.PSObject.Properties['Names'] -or -not $s.Names) { $s | Add-Member -NotePropertyName Names -NotePropertyValue ([pscustomobject]@{}) -Force }
    return $s
}
function Save-NtDevStore([string]$File, $Store, $Rows, [string]$NetText) {
    $now = (Get-Date).ToString('o')
    $dev = @{}; foreach ($d in @($Store.Devices)) { if ($d -and $d.Key) { $dev[[string]$d.Key] = $d } }
    foreach ($r in @($Rows)) {
        if ($dev.ContainsKey($r.Key)) { $o = $dev[$r.Key]; $o.Ip = $r.Ip; $o.LastSeen = $now; if ($r.Host) { $o.Host = $r.Host }; if ($r.Vendor) { $o.Vendor = $r.Vendor } }
        else { $dev[$r.Key] = [pscustomobject]@{ Key = $r.Key; Ip = $r.Ip; Mac = $r.Mac; Host = $r.Host; Vendor = $r.Vendor; FirstSeen = $now; LastSeen = $now } }
    }
    $out = [pscustomobject]@{ Time = $now; Net = $NetText; LastScan = @($Rows | ForEach-Object { $_.Key }); Devices = @($dev.Values | Sort-Object { Get-NtIpSort $_.Ip } | Select-Object -Last 1000); Names = $Store.Names }
    $out | ConvertTo-Json -Depth 5 | Set-Content -LiteralPath $File -Encoding UTF8
    return $out
}

# ---- Wake-on-LAN
function ConvertTo-NtMacBytes([string]$Mac) {
    $h = ($Mac -replace '[^0-9A-Fa-f]', '')
    if ($h.Length -ne 12) { throw ('Ungültige MAC-Adresse: "{0}" (erwartet z.B. 3C:A6:2F:12:34:56)' -f $Mac) }
    $b = New-Object byte[] 6
    for ($i = 0; $i -lt 6; $i++) { $b[$i] = [Convert]::ToByte($h.Substring($i * 2, 2), 16) }
    return , $b
}
function New-NtMagicPacket([string]$Mac) {
    $m = ConvertTo-NtMacBytes $Mac
    $pk = New-Object byte[] 102
    for ($i = 0; $i -lt 6; $i++) { $pk[$i] = 255 }
    for ($r = 1; $r -le 16; $r++) { [Array]::Copy($m, 0, $pk, $r * 6, 6) }
    return , $pk
}
function Send-NtWol([string]$Mac, [string]$Broadcast) {
    $pk = New-NtMagicPacket $Mac
    $targets = [System.Collections.Generic.List[string]]::new()
    if ($Broadcast) { $targets.Add($Broadcast) }
    if (-not $targets.Contains('255.255.255.255')) { $targets.Add('255.255.255.255') }
    $sent = [System.Collections.Generic.List[string]]::new()
    $u = New-Object Net.Sockets.UdpClient
    try {
        $u.EnableBroadcast = $true
        foreach ($t in $targets) {
            $addr = $null; if (-not [Net.IPAddress]::TryParse($t, [ref]$addr)) { continue }
            foreach ($port in 9, 7) { try { [void]$u.Send($pk, $pk.Length, (New-Object Net.IPEndPoint($addr, $port))); $sent.Add(('{0}:{1}' -f $t, $port)) } catch { } }
        }
    } finally { $u.Close() }
    if (-not $sent.Count) { throw 'Das Paket konnte nicht gesendet werden (Netzwerk getrennt?).' }
    return ($sent -join ', ')
}
function Read-NtWolList([string]$File) {
    try { if (Test-Path -LiteralPath $File) { return @(Get-Content -LiteralPath $File -Raw -Encoding UTF8 | ConvertFrom-Json | ForEach-Object { $_ } | Where-Object { $_ -and $_.Mac }) } } catch { }
    return @()
}
function Save-NtWolList([string]$File, $List) { ConvertTo-Json -InputObject @($List | Select-Object Name, Mac, Broadcast, Ip, Last) -Depth 3 | Set-Content -LiteralPath $File -Encoding UTF8 }

# ---- Speedtest-Verlauf ($DataDir\speedtest.csv, Trennzeichen ;, Zahlen mit Punkt)
function Add-NtSpeedHistory($Result, $Net = $null) {
    if (-not $Result) { return }
    $f = Join-Path $DataDir 'speedtest.csv'
    if (-not $Net) { try { $Net = Get-NtActiveNet } catch { } }
    $inv = [Globalization.CultureInfo]::InvariantCulture
    $kind = if ($Net) { $Net.Kind } else { '' }
    $ad = if ($Net) { ('{0} ({1})' -f $Net.Name, $Net.Desc) -replace '[;"\r\n]', ' ' } else { '' }
    if (-not (Test-Path -LiteralPath $f)) { Set-Content -LiteralPath $f -Value 'Datum;Verbindung;Adapter;Download;Upload;Ping;Jitter' -Encoding UTF8 }
    $line = [string]::Format($inv, '{0};{1};{2};{3:0.0};{4:0.0};{5:0};{6:0}', (Get-Date).ToString('yyyy-MM-dd HH:mm:ss'), $kind, $ad, [double]$Result.Down, [double]$Result.Up, [double]$Result.Ping, [double]$Result.Jitter)
    Add-Content -LiteralPath $f -Value $line -Encoding UTF8
}
function Read-NtSpeedHistory([string]$File) {
    $inv = [Globalization.CultureInfo]::InvariantCulture
    $rows = @(); try { if (Test-Path -LiteralPath $File) { $rows = @(Import-Csv -LiteralPath $File -Delimiter ';' -Encoding UTF8) } } catch { }
    $out = foreach ($r in $rows) {
        $dt = [datetime]::MinValue; if (-not [datetime]::TryParseExact([string]$r.Datum, [string[]]@('yyyy-MM-dd HH:mm:ss', 'yyyy-MM-dd HH:mm'), $inv, [Globalization.DateTimeStyles]::None, [ref]$dt)) { continue }
        $num = { param($s) $v = 0.0; if ([double]::TryParse(([string]$s).Replace(',', '.'), [Globalization.NumberStyles]::Float, $inv, [ref]$v)) { $v } else { 0.0 } }
        $dn = & $num $r.Download; $upv = & $num $r.Upload; $pg = & $num $r.Ping; $jt = & $num $r.Jitter
        [pscustomobject]@{ Date = $dt; DateText = $dt.ToString('dd.MM.yyyy HH:mm'); Raw = [string]$r.Datum; Kind = [string]$r.Verbindung; Adapter = [string]$r.Adapter
            Down = $dn; Up = $upv; Ping = $pg; Jitter = $jt; DownText = ('{0:N1} Mbit/s' -f $dn); UpText = ('{0:N1} Mbit/s' -f $upv); PingText = $(if ($pg -ge 0) { '{0:N0} ms' -f $pg } else { '-' }); JitterText = ('{0:N0} ms' -f $jt)
            Level = $(if ($dn -le 0) { 'Error' } else { '' }) }
    }
    return , @($out | Sort-Object Date)
}
function Remove-NtSpeedEntry([string]$File, [string]$Raw) {
    $lines = @(Get-Content -LiteralPath $File -Encoding UTF8)
    $keep = @($lines | Where-Object { -not $_.StartsWith($Raw + ';') })
    Set-Content -LiteralPath $File -Value $keep -Encoding UTF8
}

# ---- DNS-Vergleich
$NtDnsDomains = @('google.de', 'youtube.com', 'amazon.de', 'wikipedia.org', 'microsoft.com', 'apple.com', 'web.de', 'spiegel.de', 'github.com', 'netflix.com')
$NtDnsPairs = @{ '1.1.1.1' = '1.0.0.1'; '8.8.8.8' = '8.8.4.4'; '9.9.9.9' = '149.112.112.112'; '94.140.14.14' = '94.140.15.15'; '208.67.222.222' = '208.67.220.220' }
$NtDnsServers = [ordered]@{ '1.1.1.1' = 'Cloudflare'; '8.8.8.8' = 'Google'; '9.9.9.9' = 'Quad9'; '94.140.14.14' = 'AdGuard'; '208.67.222.222' = 'OpenDNS (Cisco)' }
function Get-NtStats([double[]]$Values) {
    $v = @($Values | Sort-Object)
    if (-not $v.Count) { return [pscustomobject]@{ Avg = -1; Median = -1; Min = -1; Max = -1 } }
    $med = if ($v.Count % 2) { $v[[int][math]::Floor($v.Count / 2)] } else { ($v[$v.Count / 2 - 1] + $v[$v.Count / 2]) / 2 }
    [pscustomobject]@{ Avg = [math]::Round((($v | Measure-Object -Sum).Sum / $v.Count), 1); Median = [math]::Round($med, 1); Min = $v[0]; Max = $v[-1] }
}
# Servers: Liste von @{ Name; Ip }. Jede Domain wird zweimal gefragt (1. Mal ggf. ungecacht beim Anbieter, 2. Mal gecacht).
function Measure-NtDns($Servers, [string[]]$Domains, [int]$Rounds, $Sync) {
    $total = [math]::Max(1, @($Servers).Count * $Domains.Count * $Rounds); $done = 0
    foreach ($s in @($Servers)) {
        $samples = [System.Collections.Generic.List[double]]::new(); $fail = 0; $errs = @()
        for ($r = 0; $r -lt $Rounds; $r++) {
            foreach ($d in $Domains) {
                $sw = [Diagnostics.Stopwatch]::StartNew()
                try { $null = Resolve-DnsName -Name $d -Server $s.Ip -Type A -DnsOnly -QuickTimeout -NoHostsFile -ErrorAction Stop; $sw.Stop(); $samples.Add([math]::Round($sw.Elapsed.TotalMilliseconds, 1)) }
                catch { $sw.Stop(); $fail++; if ($errs.Count -lt 2) { $errs += $_.Exception.Message } }
                $done++; if ($Sync) { $Sync.P = [int](100 * $done / $total); $Sync.T = ('{0} ({1}): {2}' -f $s.Name, $s.Ip, $d) }
            }
        }
        $st = Get-NtStats $samples.ToArray()
        [pscustomobject]@{ Name = $s.Name; Server = $s.Ip; Avg = $st.Avg; Median = $st.Median; Min = $st.Min; Max = $st.Max; Fail = $fail; Count = $samples.Count + $fail; Router = [bool]$s.Router; Current = [bool]$s.Current; Error = ($errs -join ' | ') }
    }
}
# Bewertung/Empfehlung (Fehler zählen stark, dann Median, dann Mittelwert)
function Get-NtDnsRanking($Rows) {
    $ok = @($Rows | Where-Object { $_.Median -ge 0 })
    $ranked = @($ok | Sort-Object @{ e = { $_.Median + 1000.0 * $_.Fail / [math]::Max(1, $_.Count) } }, Avg)
    $best = $ranked | Select-Object -First 1
    $router = @($Rows | Where-Object Router)[0]
    $txt = if (-not $best) { 'Kein DNS-Server hat geantwortet - besteht eine Internetverbindung?' }
    elseif ($router -and $best.Server -eq $router.Server) { 'Dein Router ist am schnellsten ({0:N0} ms Median). Empfehlung: so lassen - der Router speichert Antworten zwischen und kennt die Namen der Geräte im Heimnetz (z.B. fritz.box, NAS).' -f $best.Median }
    elseif ($router -and $router.Median -ge 0 -and ($router.Median - $best.Median) -lt 5) { 'Am schnellsten: {0} ({1:N0} ms), aber der Router ({2:N0} ms) ist kaum langsamer. Der Unterschied ist nicht spürbar - Router-DNS behalten (lokale Namen funktionieren nur damit).' -f $best.Name, $best.Median, $router.Median }
    else { 'Empfehlung: {0} ({1}) mit {2:N0} ms Median{3}. Tipp: Besser im Router als "Upstream-DNS" eintragen - dann profitieren alle Geräte und lokale Namen funktionieren weiter.' -f $best.Name, $best.Server, $best.Median, $(if ($router -and $router.Median -ge 0) { ' - {0:N0} ms schneller als der Router' -f ($router.Median - $best.Median) } else { '' }) }
    [pscustomobject]@{ Best = $best; Text = $txt; Ranked = $ranked }
}

# ---- WLAN: netsh wlan show networks mode=bssid (deutsch und englisch) in einzelne Sender zerlegen
function ConvertFrom-NtWlanText([string[]]$Lines) {
    $out = [System.Collections.Generic.List[object]]::new(); $ssid = $null; $auth = ''; $enc = ''; $cur = $null
    $flush = { if ($cur) { $out.Add([pscustomobject]$cur) } }
    foreach ($l in $Lines) {
        if ($l -match '^\s*SSID\s+\d+\s*:\s?(.*)$') { & $flush; $cur = $null; $ssid = $Matches[1].Trim(); $auth = ''; $enc = ''; continue }
        if ($null -eq $ssid) { continue }
        if ($l -match '^\s*(Authentifizierung|Authentication)\s*:\s*(.+)$') { $auth = $Matches[2].Trim(); continue }
        if ($l -match '^\s*(Verschl\S*sselung|Encryption)\s*:\s*(.+)$') { $enc = $Matches[2].Trim(); continue }
        if ($l -match '^\s*BSSID\s+\d+\s*:\s*([0-9A-Fa-f:\-]{17})') {
            & $flush
            $cur = [ordered]@{ Ssid = $(if ($ssid) { $ssid } else { '(verborgenes Netz)' }); Bssid = (Format-NtMac $Matches[1]); Signal = 0; Channel = 0; Band = ''; Radio = ''; Auth = $auth; Enc = $enc; Util = -1; Stations = -1 }
            continue
        }
        if (-not $cur) { continue }
        if ($l -match '^\s*Signal\s*:\s*(\d+)\s*%') { $cur.Signal = [int]$Matches[1] }
        elseif ($l -match '^\s*(Funktyp|Radio type)\s*:\s*(.+)$') { $cur.Radio = $Matches[2].Trim() }
        elseif ($l -match '^\s*Band\s*:\s*(.+)$') { $cur.Band = $Matches[1].Trim() }
        elseif ($l -match '^\s*(Kanal|Channel)\s*:\s*(\d+)') { $cur.Channel = [int]$Matches[2] }
        elseif ($l -match '^\s*(Kanalauslastung|Kanalnutzung|Channel Utilization)\s*:\s*\d+\s*\((\d+)\s*%\)') { $cur.Util = [int]$Matches[2] }
        elseif ($l -match '^\s*(Verbundene Stationen|Connected Stations)\s*:\s*(\d+)') { $cur.Stations = [int]$Matches[2] }
    }
    & $flush
    foreach ($n in $out) {
        if (-not $n.Band) { $n.Band = if ($n.Channel -ge 1 -and $n.Channel -le 14) { '2,4 GHz' } elseif ($n.Channel -gt 14) { '5 GHz' } else { '' } }
        $n.Band = $n.Band -replace '2\.4', '2,4'
        $bk = if ($n.Band -match '^\s*6') { '6' } elseif ($n.Band -match '^\s*5') { '5' } elseif ($n.Band -match '^\s*2') { '2.4' } elseif ($n.Channel -ge 1 -and $n.Channel -le 14) { '2.4' } elseif ($n.Channel -gt 14) { '5' } else { '' }
        $n | Add-Member -NotePropertyName BandKey -NotePropertyValue $bk -Force
    }
    return , $out
}
function Get-NtWlanCurrent {
    $w = @(& netsh.exe wlan show interfaces 2>$null)
    $o = [ordered]@{ Ssid = ''; Bssid = ''; Channel = 0; Signal = ''; Radio = ''; Band = '' }
    foreach ($l in $w) {
        if ($l -match '^\s*SSID\s*:\s*(.+)$') { $o.Ssid = $Matches[1].Trim() }
        elseif ($l -match '^\s*(AP[ -])?BSSID\s*:\s*([0-9A-Fa-f:\-]{17})') { $o.Bssid = Format-NtMac $Matches[2] }
        elseif ($l -match '^\s*(Kanal|Channel)\s*:\s*(\d+)') { $o.Channel = [int]$Matches[2] }
        elseif ($l -match '^\s*Signal\s*:\s*(\d+\s*%)') { $o.Signal = $Matches[1] }
        elseif ($l -match '^\s*(Funktyp|Radio type)\s*:\s*(.+)$') { $o.Radio = $Matches[2].Trim() }
        elseif ($l -match '^\s*Band\s*:\s*(.+)$') { $o.Band = $Matches[1].Trim() }
    }
    return [pscustomobject]$o
}
function Get-NtWlanScan {
    $raw = @(& netsh.exe wlan show networks mode=bssid 2>&1 | ForEach-Object { [string]$_ })
    $txt = $raw -join "`n"
    $needLoc = ($txt -match '(?i)location permission|Standortberechtigung|Standort|ms-settings:privacy-location') -and -not ($txt -match '(?m)^\s*BSSID')
    [pscustomobject]@{ Nets = (ConvertFrom-NtWlanText $raw); Current = (Get-NtWlanCurrent); NeedLocation = $needLoc; Raw = $(if ($needLoc -or -not ($txt -match 'BSSID')) { ($raw | Select-Object -First 6) -join ' ' } else { '' }) }
}
# Kanalempfehlung: 2,4 GHz nur 1/6/11 (überlappungsfrei), 5 GHz: am wenigsten belegter 80-MHz-Block
function Get-NtChannelAdvice($Nets, [string]$OwnSsid) {
    $load24 = @{}; foreach ($k in 1..13) { $load24[$k] = 0.0 }
    $n24 = @($Nets | Where-Object { $_.BandKey -eq '2.4' -and $_.Channel -ge 1 -and $_.Channel -le 14 -and $_.Ssid -ne $OwnSsid })
    foreach ($n in $n24) { foreach ($k in 1..13) { $dd = [math]::Abs($n.Channel - $k); if ($dd -le 4) { $load24[$k] += ($n.Signal / 100.0) * (1 - $dd / 5.0) } } }
    $best24 = @(1, 6, 11 | Sort-Object @{ e = { $load24[$_] } }, @{ e = { $_ } })[0]
    $blocks = [ordered]@{ '36-48' = @(36, 40, 44, 48); '52-64 (DFS)' = @(52, 56, 60, 64); '100-112 (DFS)' = @(100, 104, 108, 112); '116-128 (DFS)' = @(116, 120, 124, 128); '132-140 (DFS)' = @(132, 136, 140, 144) }
    $load5 = [ordered]@{}; foreach ($b in $blocks.Keys) { $load5[$b] = 0.0 }
    $n5 = @($Nets | Where-Object { $_.BandKey -eq '5' -and $_.Ssid -ne $OwnSsid })
    foreach ($n in $n5) { foreach ($b in $blocks.Keys) { if ($blocks[$b] -contains $n.Channel) { $load5[$b] += [math]::Max(0.1, $n.Signal / 100.0) } } }
    $best5 = @($load5.Keys | Sort-Object @{ e = { $load5[$_] } }, @{ e = { if ($_ -like '36*') { 0 } else { 1 } } })[0]
    $best5ch = $blocks[$best5][0]
    [pscustomobject]@{ Best24 = $best24; Load24 = $load24; Best5Block = $best5; Best5 = $best5ch; Load5 = $load5; Count24 = $n24.Count; Count5 = $n5.Count }
}

# ---- Router-Check
$NtTlsCode = @'
using System;
using System.Net.Security;
using System.Net.Sockets;
using System.Security.Authentication;
using System.Security.Cryptography.X509Certificates;
namespace PCTools {
  public static class NtTls {
    public static string[] Probe(string host, int port, int timeoutMs) {
      try {
        using (TcpClient c = new TcpClient()) {
          IAsyncResult ar = c.BeginConnect(host, port, null, null);
          if (!ar.AsyncWaitHandle.WaitOne(timeoutMs)) { return new string[] { "timeout", "", "", "", "", "" }; }
          c.EndConnect(ar);
          string errs = "";
          using (SslStream s = new SslStream(c.GetStream(), false, delegate(object o, X509Certificate cert, X509Chain chain, SslPolicyErrors e) { errs = e.ToString(); return true; })) {
            s.ReadTimeout = timeoutMs; s.WriteTimeout = timeoutMs;
            s.AuthenticateAsClient(host, null, SslProtocols.Tls12 | SslProtocols.Tls11 | SslProtocols.Tls, false);
            X509Certificate2 x = new X509Certificate2(s.RemoteCertificate);
            return new string[] { "ok", x.Subject, x.Issuer, x.NotAfter.ToString("o"), errs, s.SslProtocol.ToString() };
          }
        }
      } catch (Exception ex) { return new string[] { "error", ex.Message, "", "", "", "" }; }
    }
  }
}
'@
function Get-NtHttpInfo([string]$Url) {
    $o = [pscustomobject]@{ Url = $Url; Code = 0; Title = ''; Server = ''; Error = '' }
    try {
        $w = Invoke-WebRequest -Uri $Url -UseBasicParsing -TimeoutSec 5 -MaximumRedirection 3 -ErrorAction Stop
        $o.Code = [int]$w.StatusCode; $o.Server = [string]$w.Headers['Server']
        if ($w.Content -match '(?is)<title[^>]*>\s*([^<]{1,120}?)\s*</title>') { $o.Title = [Net.WebUtility]::HtmlDecode($Matches[1]) }
    } catch {
        $resp = $null; try { $resp = $_.Exception.Response } catch { }
        if ($resp) { try { $o.Code = [int]$resp.StatusCode } catch { } }
        $o.Error = $_.Exception.Message
    }
    return $o
}
function ConvertFrom-NtBoxInfo([string]$Xml) {
    if (-not $Xml -or $Xml -notmatch 'BoxInfo') { return $null }
    $g = { param($n) if ($Xml -match ('<(?:\w+:)?' + $n + '>\s*([^<]*?)\s*</(?:\w+:)?' + $n + '>')) { $Matches[1] } else { '' } }
    $ver = & $g 'Version'; $os = ''
    if ($ver -match '^\d+\.(\d+)\.(\d+)') { $os = '{0}.{1}' -f [int]$Matches[1], $Matches[2] }
    [pscustomobject]@{ Name = (& $g 'Name'); HW = (& $g 'HW'); Version = $ver; Os = $os; Revision = (& $g 'Revision'); Serial = (& $g 'Serial'); Oem = (& $g 'OEM'); Lang = (& $g 'Lang'); Annex = (& $g 'Annex'); Lab = (& $g 'Lab'); Country = (& $g 'Country'); Flag = (& $g 'Flag'); UpdateConfig = (& $g 'UpdateConfig') }
}
function Get-NtFritzAdvice([string]$Os) {
    $v = $null; try { $v = [version]$Os } catch { }
    if (-not $v) { return [pscustomobject]@{ Level = 'Info'; Text = 'FRITZ!OS-Version nicht erkannt.' } }
    if ($v -lt [version]'7.29') { return [pscustomobject]@{ Level = 'Bad'; Text = ('FRITZ!OS {0} ist sehr alt. Sofort unter System > Update aktualisieren. Wird keine neuere Version angeboten, bekommt das Modell keine Sicherheitsupdates mehr - dann ersetzen.' -f $Os) } }
    if ($v -lt [version]'7.50') { return [pscustomobject]@{ Level = 'Warn'; Text = ('FRITZ!OS {0} ist veraltet. Unter System > Update nach neuer Version suchen (7.5x bzw. 8.x).' -f $Os) } }
    if ($v -lt [version]'8.0') { return [pscustomobject]@{ Level = 'Warn'; Text = ('FRITZ!OS {0}: Für viele Modelle gibt es FRITZ!OS 8. Unter System > Update prüfen - wird nichts angeboten, ist {0} der aktuelle Stand für dieses Modell.' -f $Os) } }
    return [pscustomobject]@{ Level = 'Good'; Text = ('FRITZ!OS {0} - aktuelle Generation. Automatische Updates unter System > Update > Auto-Update einschalten.' -f $Os) }
}
# Rohdaten sammeln (läuft in Invoke-Bg; Get-UpnpInfo, Get-NtHttpInfo, ConvertFrom-NtBoxInfo, Get-NtActiveNet, Format-NtMac, Get-NtBroadcast, ConvertTo-NtNum, ConvertFrom-NtNum mitgeben)
function Get-NtRouterData([string]$TlsCode, $Sync) {
    $say = { param($p, $t) if ($Sync) { $Sync.P = $p; $Sync.T = $t } }
    & $say 5 'Adapter und Router ermitteln ...'
    $net = Get-NtActiveNet
    $d = [ordered]@{ Net = $net; GwMac = ''; Dhcp = $null; Ipv6 = $null; Http = $null; Https = $null; Tls = $null; Box = $null; Upnp = $null; Ping = -1 }
    if (-not $net -or -not $net.Gateway) { return [pscustomobject]$d }
    $gw = $net.Gateway
    try { $pr = (New-Object Net.NetworkInformation.Ping).Send($gw, 1500); if ($pr.Status -eq 'Success') { $d.Ping = [int]$pr.RoundtripTime } } catch { }
    try { $d.GwMac = Format-NtMac ([string]@(Get-NetNeighbor -IPAddress $gw -ErrorAction Stop)[0].LinkLayerAddress) } catch { }
    & $say 15 'DHCP und IPv6 lesen ...'
    try {
        $cfg = @(Get-CimInstance Win32_NetworkAdapterConfiguration -Filter ('InterfaceIndex={0}' -f $net.Index) -ErrorAction Stop)[0]
        $d.Dhcp = [pscustomobject]@{ Enabled = [bool]$cfg.DHCPEnabled; Server = [string]$cfg.DHCPServer; Obtained = $cfg.DHCPLeaseObtained; Expires = $cfg.DHCPLeaseExpires; Domain = [string]$cfg.DNSDomain; Dns6 = @(Get-DnsClientServerAddress -InterfaceIndex $net.Index -AddressFamily IPv6 -ErrorAction SilentlyContinue | ForEach-Object { $_.ServerAddresses } | Where-Object { $_ -and $_ -notlike 'fec0*' }) }
    } catch { }
    try {
        $bind = Get-NetAdapterBinding -Name $net.Name -ComponentID ms_tcpip6 -ErrorAction SilentlyContinue
        $v6 = @(Get-NetIPAddress -InterfaceIndex $net.Index -AddressFamily IPv6 -ErrorAction SilentlyContinue | Where-Object { $_.IPAddress -match '^[23]' })
        $r6 = @(Get-NetRoute -InterfaceIndex $net.Index -DestinationPrefix '::/0' -ErrorAction SilentlyContinue)
        $d.Ipv6 = [pscustomobject]@{ Bound = $(if ($bind) { [bool]$bind.Enabled } else { $true }); Global = @($v6 | ForEach-Object { [string]$_.IPAddress } | Select-Object -Unique); Default = [bool]$r6.Count; Temp = @($v6 | Where-Object { [string]$_.SuffixOrigin -eq 'Random' }).Count }
    } catch { }
    & $say 35 'Weboberfläche prüfen (http/https) ...'
    try { [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12 -bor [Net.SecurityProtocolType]::Tls11 -bor [Net.SecurityProtocolType]::Tls } catch { }
    $d.Http = Get-NtHttpInfo ('http://{0}/' -f $gw)
    $d.Https = Get-NtHttpInfo ('https://{0}/' -f $gw)
    try { if (-not ('PCTools.NtTls' -as [type])) { Add-Type -TypeDefinition $TlsCode -ErrorAction Stop }; $t = [PCTools.NtTls]::Probe($gw, 443, 4000); $d.Tls = [pscustomobject]@{ State = $t[0]; Subject = $t[1]; Issuer = $t[2]; NotAfter = $t[3]; Errors = $t[4]; Proto = $t[5] } } catch { }
    & $say 55 'FRITZ!Box-Infos abfragen ...'
    foreach ($u in @(('http://{0}/jason_boxinfo.xml' -f $gw), 'http://fritz.box/jason_boxinfo.xml')) {
        try { $w = Invoke-WebRequest -Uri $u -UseBasicParsing -TimeoutSec 4 -ErrorAction Stop; $b = ConvertFrom-NtBoxInfo ([string]$w.Content); if ($b) { $b | Add-Member -NotePropertyName Url -NotePropertyValue $u; $d.Box = $b; break } } catch { }
    }
    & $say 70 'UPnP-Portfreigaben abfragen ...'
    try { $d.Upnp = Get-UpnpInfo } catch { }
    & $say 100 'Fertig.'
    return [pscustomobject]$d
}
# Checkliste aus den Rohdaten (reine Aufbereitung). Level: Good/Warn/Bad/Info
function Get-NtRouterChecklist($D, $Table) {
    $rows = [System.Collections.Generic.List[object]]::new()
    $add = { param($lv, $ti, $dt) $rows.Add([pscustomobject]@{ Level = $lv; Title = $ti; Detail = $dt }) }
    $net = $D.Net
    if (-not $net) { & $add 'Bad' 'Kein aktiver Netzwerkadapter' 'Der PC ist mit keinem Netzwerk verbunden.'; return , $rows }
    if (-not $net.Gateway) { & $add 'Bad' 'Kein Router (Standardgateway)' ('Adapter {0} hat kein Standardgateway - Internet nicht möglich. Seite Netzwerk-Diagnose hilft weiter.' -f $net.Name); return , $rows }
    $vend = Get-NtVendor $D.GwMac $Table
    & $add $(if ($D.Ping -ge 0) { 'Good' } else { 'Warn' }) ('Router {0}' -f $net.Gateway) ('MAC {0}{1} · über {2} ({3}) · {4}' -f $(if ($D.GwMac) { $D.GwMac } else { 'unbekannt' }), $(if ($vend) { ' · Hersteller: ' + $vend } else { '' }), $net.Name, $net.Kind, $(if ($D.Ping -ge 0) { 'antwortet in {0} ms' -f $D.Ping } else { 'antwortet nicht auf Ping (manche Router blocken das)' }))
    if ($D.Box) {
        $adv = Get-NtFritzAdvice $D.Box.Os
        & $add $adv.Level ('{0} - FRITZ!OS {1}{2}' -f $D.Box.Name, $D.Box.Os, $(if ($D.Box.Lab) { ' (Labor/Beta)' } else { '' })) ('{0} Firmware-Kennung {1}, Hardware {2}, Annex {3}.{4}' -f $adv.Text, $D.Box.Version, $D.Box.HW, $D.Box.Annex, $(if ($D.Box.Oem -and $D.Box.Oem -ne 'avm') { (' Provider-Branding "{0}": Updates kommen evtl. vom Anbieter.' -f $D.Box.Oem) } else { '' }))
        if ($D.Box.Flag -match 'mesh_master') { & $add 'Info' 'Mesh-Master' 'Diese FRITZ!Box steuert das Mesh - Updates und WLAN-Einstellungen werden an Repeater weitergegeben.' }
    } elseif ($vend -like 'AVM*') { & $add 'Info' 'FRITZ!Box erkannt, Modell nicht lesbar' 'Die Datei jason_boxinfo.xml war nicht abrufbar. Firmware im Menü unter System > Update prüfen.' }
    else { & $add 'Info' 'Firmware' 'Kein AVM-Router: Firmware-Stand bitte in der Router-Oberfläche prüfen (meist System/Verwaltung > Firmware-Update) und automatische Updates einschalten.' }
    $h = $D.Http; $s = $D.Https; $tls = $D.Tls
    $httpOk = $h -and ($h.Code -ge 200 -and $h.Code -lt 500); $httpsOk = ($s -and $s.Code -ge 200 -and $s.Code -lt 500) -or ($tls -and $tls.State -eq 'ok')
    if ($httpOk -or $httpsOk) {
        $txt = @()
        if ($h -and $h.Code) { $txt += ('http: Status {0}{1}' -f $h.Code, $(if ($h.Title) { ' "' + $h.Title + '"' } else { '' })) } elseif ($h) { $txt += 'http: nicht erreichbar' }
        if ($s -and $s.Code) { $txt += ('https: Status {0}{1}' -f $s.Code, $(if ($s.Title) { ' "' + $s.Title + '"' } else { '' })) }
        elseif ($tls -and $tls.State -eq 'ok') { $txt += ('https: erreichbar ({0}), Zertifikat {1}' -f $tls.Proto, $(if ($tls.Errors -and $tls.Errors -ne 'None') { 'nicht vertrauenswürdig/selbstsigniert (bei Routern normal)' } else { 'gültig' })) }
        else { $txt += 'https: nicht erreichbar' }
        & $add $(if ($httpsOk) { 'Good' } else { 'Warn' }) 'Router-Oberfläche erreichbar' (($txt -join ' · ') + $(if (-not $httpsOk) { '. Nur unverschlüsselt (http): Das Router-Kennwort geht im Klartext durchs Netz - wenn möglich https nutzen.' } else { '' }))
    } else { & $add 'Warn' 'Router-Oberfläche nicht erreichbar' ('Weder http noch https antworten auf {0}. Manche Router (z.B. Mesh-Systeme) werden nur per App verwaltet.' -f $net.Gateway) }
    if ($D.Dhcp) {
        if ($D.Dhcp.Enabled) {
            $lease = ''; $lv = 'Good'
            try { $span = ([datetime]$D.Dhcp.Expires) - ([datetime]$D.Dhcp.Obtained); $lease = if ($span.TotalDays -ge 1) { '{0:N0} Tag(e)' -f $span.TotalDays } else { '{0:N1} Stunde(n)' -f $span.TotalHours }; if ($span.TotalHours -lt 1) { $lv = 'Warn' } } catch { }
            & $add $lv ('DHCP-Server {0}' -f $D.Dhcp.Server) ('Adresse automatisch erhalten{0}{1}{2}.{3}' -f $(if ($D.Dhcp.Obtained) { (' am {0:dd.MM.yyyy HH:mm}' -f [datetime]$D.Dhcp.Obtained) } else { '' }), $(if ($D.Dhcp.Expires) { (', gültig bis {0:dd.MM.yyyy HH:mm}' -f [datetime]$D.Dhcp.Expires) } else { '' }), $(if ($lease) { ' (Lease-Dauer ' + $lease + ')' } else { '' }), $(if ($lv -eq 'Warn') { ' Sehr kurze Lease-Zeit - Geräte fragen ständig neu an; im Router auf 1 Tag oder mehr stellen.' } elseif ($D.Dhcp.Server -and $D.Dhcp.Server -ne $net.Gateway) { ' Hinweis: DHCP kommt nicht vom Router, sondern von einem anderen Gerät (z.B. Pi-hole/Server).' } else { '' }))
        } else { & $add 'Info' 'Feste IP-Adresse' ('Dieser PC hat die Adresse {0} fest eingetragen (kein DHCP). Sie sollte außerhalb des DHCP-Bereichs des Routers liegen.' -f $net.Ip) }
    }
    $dnsTxt = (@($net.Dns) -join ', ')
    if (@($net.Dns).Count) {
        $viaRouter = @($net.Dns) -contains $net.Gateway
        & $add $(if ($viaRouter) { 'Good' } else { 'Info' }) ('DNS-Server: {0}' -f $dnsTxt) $(if ($viaRouter) { 'Namen werden über den Router aufgelöst - lokale Namen (z.B. fritz.box, NAS) funktionieren. Den schnellsten Anbieter findet der DNS-Vergleich oben.' } else { 'Der PC fragt direkt einen externen bzw. anderen DNS-Server - lokale Gerätenamen gehen dann ggf. nicht. Absichtlich so eingestellt? (Seite Netzwerk > DNS-Server)' })
    } else { & $add 'Bad' 'Kein DNS-Server' 'Ohne DNS-Server können keine Namen aufgelöst werden. Seite Netzwerk-Diagnose prüft das.' }
    $v6 = $D.Ipv6
    if ($v6) {
        if (-not $v6.Bound) { & $add 'Warn' 'IPv6 am Adapter abgeschaltet' 'Microsoft rät davon ab, IPv6 abzuschalten - einige Windows-Funktionen setzen es voraus. In den Adaptereigenschaften "Internetprotokoll, Version 6" wieder anhaken.' }
        elseif ($v6.Global.Count -and $v6.Default) { & $add 'Good' 'IPv6 aktiv' ('Öffentliche IPv6-Adresse(n): {0}{1}. Datenschutz-Erweiterung (wechselnde Adresse): {2}.' -f (@($v6.Global | Select-Object -First 2) -join ', '), $(if ($v6.Global.Count -gt 2) { ' ...' } else { '' }), $(if ($v6.Temp) { 'aktiv' } else { 'nicht erkannt' })) }
        else { & $add 'Info' 'Nur IPv4' 'Kein IPv6 vom Router (oder vom Anschluss). Das funktioniert, IPv6 ist aber z.B. bei DS-Lite-Anschlüssen für eingehende Verbindungen nötig.' }
    }
    $u = $D.Upnp
    if ($u -and $u.On) {
        $maps = @($u.Maps)
        if ($maps.Count) { & $add 'Warn' ('UPnP: {0} automatische Portfreigabe(n)' -f $maps.Count) ('Programme/Geräte haben selbst Ports ins Internet geöffnet (Liste unten). Unbekannte Einträge prüfen; UPnP-Freigaben im Router nur für Geräte erlauben, die es brauchen (z.B. Spielkonsole).{0}' -f $(if ($u.Ext) { ' Externe IP laut Router: ' + $u.Ext } else { '' })) }
        else { & $add 'Info' 'UPnP an, keine Freigaben' ('{0} erlaubt automatische Portfreigaben, aktuell ist keine aktiv.' -f $(if ($u.Router) { $u.Router } else { 'Der Router' })) }
    } elseif ($u) { & $add 'Good' 'UPnP-Portfreigaben aus' 'Der Router beantwortet keine UPnP-Anfragen - kein Gerät kann sich selbst Ports ins Internet öffnen.' }
    return , $rows
}

# =====================================================================
#  Geräte-Akte ($DataDir\geraeteakte.json - ein Datensatz je PC)
# =====================================================================
$AkManualKeys = @('Kaufdatum', 'Preis', 'Haendler', 'Rechnungsnummer', 'Inventarnummer', 'Standort', 'Besitzer', 'Notizen')
$AkLogTypes = @('Wartung', 'Reparatur', 'Aufrüstung', 'Reinigung', 'Akkutausch', 'Garantiefall', 'Software / Neuinstallation', 'Prüfung', 'Sonstiges')
function Get-AkAutoData {
    $o = [ordered]@{}
    $cs = Get-CimInstance Win32_ComputerSystem -ErrorAction SilentlyContinue; $bios = Get-CimInstance Win32_BIOS -ErrorAction SilentlyContinue
    $prod = Get-CimInstance Win32_ComputerSystemProduct -ErrorAction SilentlyContinue; $os = Get-CimInstance Win32_OperatingSystem -ErrorAction SilentlyContinue
    $enc = @(Get-CimInstance Win32_SystemEnclosure -ErrorAction SilentlyContinue)[0]
    $reg = Get-ItemProperty 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion' -ErrorAction SilentlyContinue
    $o.Computer = $env:COMPUTERNAME
    $o.Hersteller = ([string]$cs.Manufacturer).Trim()
    $model = ([string]$cs.Model).Trim(); $mtm = ''
    if ($o.Hersteller -match 'Lenovo' -and $prod.Version -and [string]$prod.Version -notmatch '^\s*$') { $mtm = $model; $model = ([string]$prod.Version).Trim() }
    $o.Modell = $model; $o.Typnummer = $(if ($mtm) { $mtm } else { ([string]$cs.SystemSKUNumber).Trim() })
    $sn = ([string]$bios.SerialNumber).Trim(); if ($sn -match '^(To be filled|Default string|System Serial|0+$|None|Not Specified)') { $sn = ([string]$prod.IdentifyingNumber).Trim() }
    $o.Seriennummer = $sn
    $ct = @($enc.ChassisTypes | ForEach-Object { [int]$_ })
    $o.Bauform = if (@($ct | Where-Object { $_ -in 30, 32 }).Count) { 'Tablet' } elseif (@($ct | Where-Object { $_ -in 8, 9, 10, 11, 12, 14, 18, 21, 31 }).Count) { 'Notebook' } elseif (@($ct | Where-Object { $_ -in 3, 4, 5, 6, 7, 13, 15, 16, 24, 35, 36 }).Count) { 'Desktop' } else { 'PC' }
    $fw = ''; try { $fw = switch ([int](Get-ItemProperty 'HKLM:\SYSTEM\CurrentControlSet\Control' -Name PEFirmwareType -ErrorAction Stop).PEFirmwareType) { 1 { 'BIOS (Legacy)' } 2 { 'UEFI' } default { '' } } } catch { }
    $sb = ''; try { $sb = if ([int](Get-ItemProperty 'HKLM:\SYSTEM\CurrentControlSet\Control\SecureBoot\State' -Name UEFISecureBootEnabled -ErrorAction Stop).UEFISecureBootEnabled -eq 1) { 'Secure Boot an' } else { 'Secure Boot aus' } } catch { }
    $bd = ''; try { if ($bios.ReleaseDate) { $bd = ([datetime]$bios.ReleaseDate).ToString('dd.MM.yyyy') } } catch { }
    $o.Bios = ('{0} {1}{2}' -f ([string]$bios.Manufacturer).Trim(), ([string]$bios.SMBIOSBIOSVersion).Trim(), $(if ($bd) { ' vom ' + $bd } else { '' }))
    $o.BiosDatum = $(if ($bios.ReleaseDate) { try { ([datetime]$bios.ReleaseDate).ToString('yyyy-MM-dd') } catch { '' } } else { '' })
    $tpm = ''; try { $t = Get-CimInstance -Namespace root\cimv2\Security\MicrosoftTpm -ClassName Win32_Tpm -ErrorAction Stop; if ($t) { $tpm = 'TPM ' + (([string]$t.SpecVersion -split ',')[0]).Trim() } } catch { }
    $o.Firmware = (@($fw, $sb, $tpm) | Where-Object { $_ }) -join ' · '
    $cpu = @(Get-CimInstance Win32_Processor -ErrorAction SilentlyContinue)
    $o.Prozessor = if ($cpu.Count) { ('{0} ({1} Kerne / {2} Threads){3}' -f ([string]$cpu[0].Name -replace '\s+', ' ').Trim(), (($cpu | Measure-Object NumberOfCores -Sum).Sum), (($cpu | Measure-Object NumberOfLogicalProcessors -Sum).Sum), $(if ($cpu.Count -gt 1) { ' x' + $cpu.Count } else { '' })) } else { '' }
    $mods = @(Get-CimInstance Win32_PhysicalMemory -ErrorAction SilentlyContinue)
    $slots = 0; try { $slots = [int](@(Get-CimInstance Win32_PhysicalMemoryArray -ErrorAction Stop) | Measure-Object MemoryDevices -Sum).Sum } catch { }
    $mt = @{ 20 = 'DDR'; 21 = 'DDR2'; 24 = 'DDR3'; 26 = 'DDR4'; 29 = 'LPDDR3'; 30 = 'LPDDR4'; 34 = 'DDR5'; 35 = 'LPDDR5' }
    $totalGb = [math]::Round((($mods | Measure-Object Capacity -Sum).Sum) / 1GB, 0); if (-not $totalGb -and $cs.TotalPhysicalMemory) { $totalGb = [math]::Round($cs.TotalPhysicalMemory / 1GB, 0) }
    $typ = ''; if ($mods.Count) { $tv = [int]$mods[0].SMBIOSMemoryType; if ($mt.ContainsKey($tv)) { $typ = $mt[$tv] } }
    $spd = if ($mods.Count) { [int]@($mods | ForEach-Object { if ($_.ConfiguredClockSpeed) { $_.ConfiguredClockSpeed } else { $_.Speed } })[0] } else { 0 }
    $o.Arbeitsspeicher = ('{0} GB{1}{2} · {3} Modul(e){4}' -f $totalGb, $(if ($typ) { ' ' + $typ } else { '' }), $(if ($spd) { ' ' + $spd + ' MT/s' } else { '' }), $mods.Count, $(if ($slots -gt 0) { (' in {0} Steckplätzen' -f $slots) } else { '' }))
    $o.RamModule = @($mods | ForEach-Object { '{0}: {1} GB {2} {3}' -f $_.DeviceLocator, [math]::Round($_.Capacity / 1GB, 0), ([string]$_.Manufacturer).Trim(), ([string]$_.PartNumber).Trim() })
    $disks = @(); try { $disks = @(Get-PhysicalDisk -ErrorAction Stop | Sort-Object DeviceId | ForEach-Object { '{0} · {1:N0} GB · {2}/{3} · {4}' -f ([string]$_.FriendlyName).Trim(), ($_.Size / 1GB), $(if ([string]$_.MediaType -in 'SSD', 'HDD') { $_.MediaType } else { 'unbekannt' }), $_.BusType, $(switch ([string]$_.HealthStatus) { 'Healthy' { 'gesund' } 'Warning' { 'Warnung' } 'Unhealthy' { 'defekt' } default { [string]$_ } }) }) } catch { }
    if (-not $disks.Count) { $disks = @(Get-CimInstance Win32_DiskDrive -ErrorAction SilentlyContinue | ForEach-Object { '{0} · {1:N0} GB · {2}' -f $_.Model, ($_.Size / 1GB), $_.InterfaceType }) }
    $o.Datentraeger = $disks
    $o.Grafik = @(Get-CimInstance Win32_VideoController -ErrorAction SilentlyContinue | Where-Object { $_.Name -notmatch 'Remote|Mirage|Basic Display|Parsec|Virtual' } | ForEach-Object { '{0} (Treiber {1})' -f ([string]$_.Name).Trim(), $_.DriverVersion })
    $o.Windows = ('{0} {1} (Build {2}.{3}, {4})' -f ([string]$os.Caption -replace '^Microsoft\s+', ''), $reg.DisplayVersion, $reg.CurrentBuild, $reg.UBR, $os.OSArchitecture)
    $o.Installiert = $(try { ([datetime]$os.InstallDate).ToString('yyyy-MM-dd') } catch { '' })
    $act = ''
    try {
        $lp = @(Get-CimInstance SoftwareLicensingProduct -Filter "ApplicationID='55c92734-d682-4d71-983e-d6ec3f16059f' AND PartialProductKey IS NOT NULL" -ErrorAction Stop)[0]
        if ($lp) { $act = ('{0}{1}' -f $(switch ([int]$lp.LicenseStatus) { 1 { 'aktiviert' } 0 { 'nicht lizenziert' } 2 { 'Kulanzzeit (OOB)' } 3 { 'Kulanzzeit (OOT)' } 4 { 'nicht echt' } 5 { 'Benachrichtigung - nicht aktiviert' } 6 { 'erweiterte Kulanzzeit' } default { 'unbekannt' } }), $(if ($lp.ProductKeyChannel) { ' (' + $lp.ProductKeyChannel + ')' } else { '' })) }
    } catch { }
    $o.Aktivierung = $act
    $o.Netzwerk = @(Get-NetAdapter -Physical -ErrorAction SilentlyContinue | Sort-Object Name | ForEach-Object { '{0}: {1} ({2})' -f $_.Name, (([string]$_.MacAddress) -replace '-', ':'), ([string]$_.InterfaceDescription).Trim() })
    $bat = ''; $batPct = -1
    try {
        $des = @(Get-CimInstance -Namespace root\wmi -ClassName BatteryStaticData -ErrorAction Stop)[0].DesignedCapacity; $full = @(Get-CimInstance -Namespace root\wmi -ClassName BatteryFullChargedCapacity -ErrorAction Stop)[0].FullChargedCapacity
        $cyc = ''; try { $cyc = [string]@(Get-CimInstance -Namespace root\wmi -ClassName BatteryCycleCount -ErrorAction Stop)[0].CycleCount } catch { }
        if ($des -gt 0) { $batPct = [math]::Round($full * 100 / $des, 0); $bat = ('{0} % der Originalkapazität ({1:N0} von {2:N0} mWh){3}' -f $batPct, $full, $des, $(if ($cyc -and $cyc -ne '0') { ', ' + $cyc + ' Ladezyklen' } else { '' })) }
    } catch { }
    $o.Akku = $bat; $o.AkkuProzent = $batPct
    $o.Gelesen = (Get-Date).ToString('o')
    return [pscustomobject]$o
}
function New-AkRecord([string]$Computer, [string]$Serial) {
    $m = [ordered]@{}; foreach ($k in $AkManualKeys) { $m[$k] = '' }
    [pscustomobject]@{ Computer = $Computer; Serial = $Serial; Manual = [pscustomobject]$m; Log = @(); Files = @(); Auto = $null; Created = (Get-Date).ToString('o'); Updated = '' }
}
function Read-AkStore([string]$File) {
    $s = $null; try { if (Test-Path -LiteralPath $File) { $s = Get-Content -LiteralPath $File -Raw -Encoding UTF8 | ConvertFrom-Json } } catch { throw ('Geräte-Akte nicht lesbar ({0}): {1}' -f $File, $_.Exception.Message) }
    if (-not $s) { $s = [pscustomobject]@{ Format = 1; Records = @() } }
    if (-not $s.PSObject.Properties['Records']) { $s | Add-Member -NotePropertyName Records -NotePropertyValue @() }
    $recs = foreach ($r in @($s.Records)) { if ($r) { Repair-AkRecord $r } }
    $s.Records = @($recs)
    return $s
}
function Repair-AkRecord($R) {
    foreach ($p in 'Computer', 'Serial', 'Created', 'Updated') { if (-not $R.PSObject.Properties[$p]) { $R | Add-Member -NotePropertyName $p -NotePropertyValue '' } }
    foreach ($p in 'Log', 'Files') { if (-not $R.PSObject.Properties[$p]) { $R | Add-Member -NotePropertyName $p -NotePropertyValue @() } else { $R.$p = @($R.$p | Where-Object { $_ }) } }
    if (-not $R.PSObject.Properties['Auto']) { $R | Add-Member -NotePropertyName Auto -NotePropertyValue $null }
    if (-not $R.PSObject.Properties['Manual'] -or -not $R.Manual) { $R | Add-Member -NotePropertyName Manual -NotePropertyValue ([pscustomobject]@{}) -Force }
    foreach ($k in $AkManualKeys) { if (-not $R.Manual.PSObject.Properties[$k]) { $R.Manual | Add-Member -NotePropertyName $k -NotePropertyValue '' } }
    return $R
}
function Test-AkSerial([string]$Serial) { return [bool]($Serial -and $Serial -notmatch '^(To be filled|Default string|System Serial|0+$|None|Not Specified|123456789)') }
function Get-AkRecord($Store, [string]$Computer, [string]$Serial, [switch]$Create) {
    $r = $null
    if (Test-AkSerial $Serial) { $r = @($Store.Records | Where-Object { [string]$_.Serial -eq $Serial })[0] }
    if (-not $r) { $r = @($Store.Records | Where-Object { [string]$_.Computer -eq $Computer -and -not ((Test-AkSerial ([string]$_.Serial)) -and (Test-AkSerial $Serial) -and [string]$_.Serial -ne $Serial) })[0] }
    if (-not $r -and $Create) { $r = New-AkRecord $Computer $Serial; $Store.Records = @($Store.Records) + $r }
    if ($r) { if ($Computer) { $r.Computer = $Computer }; if ((Test-AkSerial $Serial) -and -not (Test-AkSerial ([string]$r.Serial))) { $r.Serial = $Serial } }
    return $r
}
function Save-AkStore([string]$File, $Store) {
    $Store.Records = @($Store.Records | Where-Object { $_ })
    foreach ($r in $Store.Records) { $r.Log = @($r.Log | Where-Object { $_ }); $r.Files = @($r.Files | Where-Object { $_ }) }
    $tmp = $File + '.tmp'
    $Store | ConvertTo-Json -Depth 8 | Set-Content -LiteralPath $tmp -Encoding UTF8
    Move-Item -LiteralPath $tmp -Destination $File -Force
}
function ConvertTo-AkDate([string]$Text) {
    $t = ([string]$Text).Trim(); if (-not $t) { return $null }
    $d = [datetime]::MinValue
    foreach ($f in 'dd.MM.yyyy', 'd.M.yyyy', 'yyyy-MM-dd', 'dd.MM.yy', 'MM/yyyy', 'MM.yyyy', 'yyyy') { if ([datetime]::TryParseExact($t, $f, [Globalization.CultureInfo]::InvariantCulture, 'None', [ref]$d)) { return $d } }
    if ([datetime]::TryParse($t, [Globalization.CultureInfo]::GetCultureInfo('de-DE'), 'None', [ref]$d)) { return $d }
    return $null
}
function ConvertTo-AkMoney([string]$Text) {
    $t = ([string]$Text) -replace '[^\d,\.\-]', ''; if (-not $t) { return $null }
    if ($t -match ',\d{1,2}$') { $t = $t.Replace('.', '').Replace(',', '.') } elseif ($t -match '\.\d{3}$' -and $t -notmatch '\.\d{1,2}$') { $t = $t.Replace('.', '') } else { $t = $t.Replace(',', '') }
    $v = 0.0; if ([double]::TryParse($t, [Globalization.NumberStyles]::Float, [Globalization.CultureInfo]::InvariantCulture, [ref]$v)) { return $v }
    return $null
}
function Format-AkMoney($Value) { if ($null -eq $Value) { return '' }; return ([double]$Value).ToString('N2', [Globalization.CultureInfo]::GetCultureInfo('de-DE')) + ' €' }
function Get-AkAge([datetime]$From, [datetime]$To = (Get-Date)) {
    $mon = ($To.Year - $From.Year) * 12 + $To.Month - $From.Month; if ($To.Day -lt $From.Day) { $mon-- }
    if ($mon -lt 0) { return '' }
    $y = [math]::Floor($mon / 12); $m = $mon % 12
    if ($y -eq 0) { return ('{0} Monat{1}' -f $m, $(if ($m -eq 1) { '' } else { 'e' })) }
    return ('{0} Jahr{1}{2}' -f $y, $(if ($y -eq 1) { '' } else { 'e' }), $(if ($m) { (', {0} Monat{1}' -f $m, $(if ($m -eq 1) { '' } else { 'e' })) } else { '' }))
}
function Get-AkLastRepair($Rec) {
    $x = @($Rec.Log | Where-Object { $_.Art -in 'Reparatur', 'Akkutausch', 'Garantiefall' } | Sort-Object { [string]$_.Datum } -Descending)[0]
    if (-not $x) { return '' }
    $dt = ConvertTo-AkDate $x.Datum
    return ('{0} {1}: {2}' -f $(if ($dt) { $dt.ToString('dd.MM.yyyy') } else { $x.Datum }), $x.Art, (([string]$x.Text) -replace '\s*\r?\n\s*', ' / '))
}
# Kernfelder für "Meine PCs" (Write-FleetStatus) - liest die Akte dieses PCs
function Get-AkFleetInfo {
    $f = Join-Path $DataDir 'geraeteakte.json'
    if (-not (Test-Path -LiteralPath $f)) { return $null }
    $sn = ''; try { $sn = ([string](Get-CimInstance Win32_BIOS -ErrorAction Stop).SerialNumber).Trim() } catch { }
    $r = Get-AkRecord (Read-AkStore $f) $env:COMPUTERNAME $sn
    if (-not $r) { return $null }
    $kd = ConvertTo-AkDate $r.Manual.Kaufdatum
    [pscustomobject]@{ Kaufdatum = $(if ($kd) { $kd.ToString('yyyy-MM-dd') } else { [string]$r.Manual.Kaufdatum }); Standort = [string]$r.Manual.Standort; Besitzer = [string]$r.Manual.Besitzer; Inventarnummer = [string]$r.Manual.Inventarnummer; LetzteReparatur = (Get-AkLastRepair $r) }
}
# SVG-Liniendiagramm für den PDF-Bericht (reine Aufbereitung)
function New-AkSvgChart([string]$Title, [double[]]$Values, [string[]]$Labels, [string]$Unit, [string]$Color) {
    $w = 330; $h = 130; $pl = 34; $pb = 18; $pt = 8
    $idx = @(for ($i = 0; $i -lt $Values.Count; $i++) { if (-not [double]::IsNaN($Values[$i])) { $i } })
    $sb = New-Object Text.StringBuilder
    [void]$sb.Append(('<div style="display:inline-block;width:48%;margin:0 1% 10px 0;vertical-align:top"><div style="font-weight:600;font-size:10pt">{0}</div><svg xmlns="http://www.w3.org/2000/svg" width="100%" viewBox="0 0 {1} {2}" style="background:#F8FAFD;border:1px solid #E2E7F0;border-radius:8px">' -f [Net.WebUtility]::HtmlEncode($Title), $w, $h))
    if ($idx.Count -ge 2) {
        $vals = @($idx | ForEach-Object { $Values[$_] })
        $min = ($vals | Measure-Object -Minimum).Minimum; $max = ($vals | Measure-Object -Maximum).Maximum
        if ($max - $min -lt 1) { $max += 1; $min -= 1 }
        $inv = [Globalization.CultureInfo]::InvariantCulture
        $n = [math]::Max(2, $Values.Count)
        $pts = @($idx | ForEach-Object { [string]::Format($inv, '{0:0.0},{1:0.0}', ($pl + ($w - $pl - 6) * $_ / ($n - 1)), ($pt + ($h - $pt - $pb) * (1 - ($Values[$_] - $min) / ($max - $min)))) })
        foreach ($g in 0..3) { $y = $pt + ($h - $pt - $pb) * $g / 3; $v = $max - ($max - $min) * $g / 3
            [void]$sb.Append([string]::Format($inv, '<line x1="{0}" y1="{1:0.0}" x2="{2}" y2="{1:0.0}" stroke="#E2E7F0" stroke-width="1"/><text x="2" y="{3:0.0}" font-size="8" fill="#6B7890">{4:0.#}</text>', $pl, $y, ($w - 4), ($y + 3), $v)) }
        [void]$sb.Append(('<polyline fill="none" stroke="{0}" stroke-width="2" stroke-linejoin="round" points="{1}"/>' -f $Color, ($pts -join ' ')))
        [void]$sb.Append(('<text x="{0}" y="{1}" font-size="8" fill="#6B7890">{2}</text><text x="{3}" y="{1}" font-size="8" fill="#6B7890" text-anchor="end">{4}</text>' -f $pl, ($h - 4), [Net.WebUtility]::HtmlEncode($Labels[$idx[0]]), ($w - 4), [Net.WebUtility]::HtmlEncode($Labels[$idx[-1]])))
        [void]$sb.Append('</svg>')
        [void]$sb.Append(('<div style="font-size:8.5pt;color:#6B7890">aktuell {0:N1} {1}, Spanne {2:N1} - {3:N1} {1}</div>' -f $Values[$idx[-1]], $Unit, ($vals | Measure-Object -Minimum).Minimum, ($vals | Measure-Object -Maximum).Maximum))
    } else {
        [void]$sb.Append(('<text x="{0}" y="{1}" font-size="10" fill="#6B7890" text-anchor="middle">noch zu wenige Messpunkte</text></svg>' -f ($w / 2), ($h / 2)))
    }
    [void]$sb.Append('</div>')
    return $sb.ToString()
}
# Kompletter HTML-Bericht der Akte (reine Aufbereitung). $H: Hashtable Rec, Auto, Warranty, Hist (Zeilen aus Verlauf.csv), Css, Version, Health (Items)
function ConvertTo-AkHtml($H) {
    $E = { param($s) [Net.WebUtility]::HtmlEncode([string]$s) }
    $r = $H.Rec; $a = $H.Auto; $m = $r.Manual
    $L = [System.Collections.Generic.List[string]]::new()
    $L.Add('<!DOCTYPE html><html lang="de"><head><meta charset="utf-8"><title>Geräte-Akte</title><style>' + $H.Css + ' td.k{width:32%;color:#475569} .grid2{width:100%} .sec{page-break-inside:avoid}</style></head><body>')
    $L.Add(('<div class="hero"><h1>Geräte-Akte: {0}</h1><div style="font-size:12pt;margin-top:4px">{1} {2}</div><small>Seriennummer {3} &middot; Computername {4} &middot; erstellt am {5:dd.MM.yyyy HH:mm} mit PC-Tools {6}</small></div>' -f (& $E $a.Modell), (& $E $a.Hersteller), $(if ($a.Typnummer) { '(' + (& $E $a.Typnummer) + ')' } else { '' }), (& $E $a.Seriennummer), (& $E $r.Computer), (Get-Date), (& $E $H.Version)))
    $row = { param($k, $v) if ([string]$v) { $L.Add(('<tr><td class="k">{0}</td><td>{1}</td></tr>' -f (& $E $k), $v)) } }
    $L.Add('<div class="sec"><h2>Kauf und Inventar</h2><table>')
    $kd = ConvertTo-AkDate $m.Kaufdatum
    & $row 'Kaufdatum' $(if ($kd) { $kd.ToString('dd.MM.yyyy') + ' (Alter: ' + (Get-AkAge $kd) + ')' } else { & $E $m.Kaufdatum })
    $pr = ConvertTo-AkMoney $m.Preis
    & $row 'Preis' $(if ($null -ne $pr) { & $E (Format-AkMoney $pr) } else { & $E $m.Preis })
    & $row 'Händler' (& $E $m.Haendler); & $row 'Rechnungsnummer' (& $E $m.Rechnungsnummer); & $row 'Inventarnummer' (& $E $m.Inventarnummer)
    & $row 'Standort' (& $E $m.Standort); & $row 'Besitzer / Nutzer' (& $E $m.Besitzer)
    if ($H.Warranty -and $H.Warranty.End) { $we = ConvertTo-AkDate ([string]$H.Warranty.End); if (-not $we) { try { $we = [datetime]$H.Warranty.End } catch { } }
        & $row 'Garantie bis' $(if ($we) { ('{0:dd.MM.yyyy} {1}' -f $we, $(if ($we -lt (Get-Date)) { '<span class="bad">(abgelaufen)</span>' } else { '<span class="ok">(läuft)</span>' })) } else { & $E $H.Warranty.End }) }
    & $row 'Notizen' ((& $E $m.Notizen) -replace "`r?`n", '<br>')
    $L.Add('</table></div>')
    $L.Add('<div class="sec"><h2>Hardware und Windows</h2><table>')
    & $row 'Hersteller / Modell' (& $E ('{0} {1}' -f $a.Hersteller, $a.Modell)); & $row 'Typnummer / SKU' (& $E $a.Typnummer); & $row 'Seriennummer' (& $E $a.Seriennummer); & $row 'Bauform' (& $E $a.Bauform)
    & $row 'BIOS / UEFI' (& $E $a.Bios); & $row 'Firmware' (& $E $a.Firmware); & $row 'Prozessor' (& $E $a.Prozessor); & $row 'Arbeitsspeicher' ((& $E $a.Arbeitsspeicher) + $(if (@($a.RamModule).Count) { '<br><span class="muted">' + ((@($a.RamModule) | ForEach-Object { & $E $_ }) -join '<br>') + '</span>' } else { '' }))
    & $row 'Datenträger' ((@($a.Datentraeger) | ForEach-Object { & $E $_ }) -join '<br>'); & $row 'Grafik' ((@($a.Grafik) | ForEach-Object { & $E $_ }) -join '<br>')
    & $row 'Windows' (& $E $a.Windows); & $row 'Installiert am' $(if ($a.Installiert) { try { ([datetime]$a.Installiert).ToString('dd.MM.yyyy') } catch { & $E $a.Installiert } } else { '' }); & $row 'Aktivierung' (& $E $a.Aktivierung)
    & $row 'Netzwerkadapter (MAC)' ((@($a.Netzwerk) | ForEach-Object { & $E $_ }) -join '<br>'); & $row 'Akku' (& $E $a.Akku)
    $L.Add('</table></div>')
    if (@($H.Health).Count) {
        $L.Add('<div class="sec"><h2>Zustand</h2><table>')
        foreach ($it in @($H.Health)) { $L.Add(('<tr><td style="width:18%"><span class="{0}">{1}</span></td><td>{2}<br><span class="muted">{3}</span></td></tr>' -f $(switch ($it.Level) { 'Red' { 'bad' } 'Yellow' { 'warn' } default { 'ok' } }), $(switch ($it.Level) { 'Red' { 'dringend' } 'Yellow' { 'bald' } default { 'OK' } }), (& $E $it.Text), (& $E $it.Detail))) }
        $L.Add('</table></div>')
    }
    $L.Add('<div class="sec"><h2>Wartung und Reparaturen</h2>')
    $logs = @($r.Log | Sort-Object { [string]$_.Datum } -Descending)
    if ($logs.Count) {
        $L.Add('<table><tr><th>Datum</th><th>Art</th><th>Beschreibung</th><th style="text-align:right">Kosten</th></tr>'); $sum = 0.0
        foreach ($x in $logs) { $c = ConvertTo-AkMoney $x.Kosten; if ($null -ne $c) { $sum += $c }; $dt = ConvertTo-AkDate $x.Datum
            $L.Add(('<tr><td>{0}</td><td>{1}</td><td>{2}</td><td style="text-align:right">{3}</td></tr>' -f $(if ($dt) { $dt.ToString('dd.MM.yyyy') } else { & $E $x.Datum }), (& $E $x.Art), ((& $E $x.Text) -replace "`r?`n", '<br>'), $(if ($null -ne $c) { & $E (Format-AkMoney $c) } else { & $E $x.Kosten }))) }
        $L.Add(('<tr><td colspan="3"><b>Summe</b></td><td style="text-align:right"><b>{0}</b></td></tr></table>' -f (& $E (Format-AkMoney $sum))))
    } else { $L.Add('<p class="muted">Noch keine Einträge.</p>') }
    $L.Add('</div>')
    if (@($r.Files).Count) {
        $L.Add('<div class="sec"><h2>Abgelegte Dateien</h2><table><tr><th>Datei</th><th>Art</th><th>hinzugefügt</th></tr>')
        foreach ($fx in @($r.Files)) { $L.Add(('<tr><td>{0}</td><td>{1}</td><td>{2}</td></tr>' -f (& $E $fx.Name), (& $E $fx.Art), $(try { ([datetime]$fx.Added).ToString('dd.MM.yyyy') } catch { '' }))) }
        $L.Add('</table><p class="muted">Die Dateien selbst liegen im PC-Tools-Datenordner unter Akte\Dateien.</p></div>')
    }
    $hist = @($H.Hist)
    if ($hist.Count) {
        $L.Add('<div class="sec"><h2>Verlauf des Gerätezustands</h2>')
        $lab = @($hist | ForEach-Object { try { ([datetime]$_.Datum).ToString('dd.MM.yy') } catch { [string]$_.Datum } })
        $num = { param($p) @($hist | ForEach-Object { $v = 0.0; if ([double]::TryParse(([string]$_.$p).Replace(',', '.'), [Globalization.NumberStyles]::Float, [Globalization.CultureInfo]::InvariantCulture, [ref]$v)) { $v } else { [double]::NaN } }) }
        $L.Add((New-AkSvgChart 'Akku-Kapazität' (& $num 'AkkuProzent') $lab '%' '#16A34A'))
        $L.Add((New-AkSvgChart 'SSD-Verschleiß' (& $num 'SsdVerschleiss') $lab '%' '#EA580C'))
        $L.Add((New-AkSvgChart 'Freier Speicher Systemlaufwerk' (& $num 'FreiGB') $lab 'GB' '#2D7FF9'))
        $L.Add((New-AkSvgChart 'Startzeit' (& $num 'StartSek') $lab 's' '#7C3AED'))
        $L.Add(('<p class="muted">{0} Messpunkte vom {1} bis {2} (ein Punkt pro Tag).</p></div>' -f $hist.Count, (& $E $hist[0].Datum), (& $E $hist[-1].Datum)))
    }
    $L.Add('</body></html>')
    return ($L -join "`n")
}

# =====================================================================
#  Windows-Reparatur (Version 9.1): Katalog aller Reparaturen, Prüf- und Reparaturfunktionen
#  Engine-Teile: "WinRepair" (Invoke-WrRepairJob, Optionen $Script:JobOpts.Keys/Source/Index/RestorePoint/SvcAll)
#                "WinRepairIpu" (Invoke-WrInPlaceJob, Optionen Source/DynUpdate/AutoReboot/RestorePoint)
#  Textmodus:    PCPflege.ps1 -WinRepair (Invoke-WrConsole) - vom Stick: Windows-Reparatur.cmd
#  Grundsatz:    nur Reparaturen - keine Kennwörter, Konten, Aktivierung/Lizenzen; nichts Sicherheitsrelevantes still abschalten
# =====================================================================
$WrCategories = @(
    @{ Key = 'Sys';  Glyph = '&#xE8F1;'; Color = '#2563EB'; Title = 'Systemdateien und Windows-Abbild'; Desc = 'Windows bringt ein eigenes Ersatzteillager mit (Komponentenspeicher, Ordner WinSxS). DISM prüft und repariert dieses Lager, SFC ersetzt danach beschädigte Systemdateien daraus. Reihenfolge immer: erst DISM, dann SFC.' }
    @{ Key = 'Wu';   Glyph = '&#xE895;'; Color = '#16A34A'; Title = 'Windows Update'; Desc = 'Wenn Updates hängen, mit Fehlercodes abbrechen oder immer wieder installiert werden: Update-Dienste, Zwischenspeicher und Berechtigungen zurücksetzen - von sanft bis gründlich.' }
    @{ Key = 'Net';  Glyph = '&#xE968;'; Color = '#DC2626'; Title = 'Netzwerk-Tiefenreparatur'; Desc = 'Ergänzt die Seite Netzwerk-Diagnose um alles, was tief im System steckt: Dienst- und Treiber-Vorgaben, fremde Netzwerkfilter (Virenschutz, VPN), IPv4-Registrierung, Winsock, Filterplattform und die komplette Neuinstallation aller Netzwerkkomponenten.' }
    @{ Key = 'Boot'; Glyph = '&#xE7E8;'; Color = '#7C3AED'; Title = 'Start und Wiederherstellung'; Desc = 'Startkonfiguration sichern und neu schreiben, Wiederherstellungsumgebung (WinRE) prüfen und einschalten, abgesicherter Modus, Startprotokoll und Datenträgerprüfung.' }
    @{ Key = 'Apps'; Glyph = '&#xE71D;'; Color = '#0891B2'; Title = 'Apps, Startmenü und Explorer'; Desc = 'Startmenü öffnet nicht, Suche findet nichts, Store oder Apps starten nicht, Symbole sind leer oder falsch: Apps neu registrieren, Zwischenspeicher neu aufbauen, Explorer neu starten.' }
    @{ Key = 'Comp'; Glyph = '&#xE713;'; Color = '#EA580C'; Title = 'Systemkomponenten'; Desc = 'WMI, Leistungsindikatoren, .NET, Visual-C++-Laufzeiten, Gruppenrichtlinien, Druck, Zeit, Windows-Sicherheit, hosts-Datei, Dienst-Starttypen, temporäre Dateien und eine Fehlerübersicht aus der Ereignisanzeige.' }
    @{ Key = 'Last'; Glyph = '&#xE777;'; Color = '#B91C1C'; Title = 'Letzter Ausweg'; Desc = 'Wenn alles andere nicht hilft: Windows über sich selbst neu installieren (Reparaturinstallation - Programme und Dateien bleiben), auf einen Wiederherstellungspunkt zurück oder den PC zurücksetzen.' }
)
# Risk: Safe = sicher, Reboot = Neustart nötig, Deep = tiefgreifend. Mode: Job = läuft im Hintergrund (Engine) bzw. im Textmodus, Ui = Knopf öffnet/erklärt etwas direkt
# Ord = Reihenfolge beim Ausführen (unabhängig von der Anzeige), Min = geschätzte Dauer in Minuten, Fn = ausführende Funktion
$WrCatalog = @(
    @{ Key = 'DismCheck'; Cat = 'Sys'; Ord = 110; Glyph = '&#xE9D9;'; Risk = 'Safe'; Reboot = $false; Mode = 'Job'; Min = 1; Fn = 'Invoke-WrSys'
       Title = 'Windows-Abbild schnell prüfen'; Desc = 'Liest in wenigen Sekunden, ob Windows im Komponentenspeicher schon eine Beschädigung vermerkt hat. Ändert nichts.'
       Cmd = 'DISM /Online /Cleanup-Image /CheckHealth' }
    @{ Key = 'DismScan'; Cat = 'Sys'; Ord = 120; Glyph = '&#xE721;'; Risk = 'Safe'; Reboot = $false; Mode = 'Job'; Min = 15; Fn = 'Invoke-WrSys'
       Title = 'Windows-Abbild gründlich prüfen'; Desc = 'Prüft jedes Bauteil des Komponentenspeichers gegen seine Prüfsumme. Dauert 5 bis 20 Minuten und ändert nichts.'
       Cmd = 'DISM /Online /Cleanup-Image /ScanHealth' }
    @{ Key = 'DismRestore'; Cat = 'Sys'; Ord = 130; Glyph = '&#xE90F;'; Risk = 'Safe'; Reboot = $false; Mode = 'Job'; Min = 20; Fn = 'Invoke-WrSys'
       Title = 'Windows-Abbild reparieren'; Desc = 'Ersetzt beschädigte Bauteile im Komponentenspeicher - aus Windows Update oder aus einer Windows-ISO (Reparaturquelle oben). Grundlage dafür, dass SFC danach reparieren kann.'
       Cmd = 'DISM /Online /Cleanup-Image /RestoreHealth   (mit Reparaturquelle: /Source:WIM:X:\sources\install.wim:<Index> /LimitAccess bzw. /Source:ESD:...)' }
    @{ Key = 'SfcScan'; Cat = 'Sys'; Ord = 140; Glyph = '&#xE8B7;'; Risk = 'Safe'; Reboot = $false; Mode = 'Job'; Min = 15; Fn = 'Invoke-WrSys'
       Title = 'Systemdateien prüfen und reparieren'; Desc = 'Vergleicht alle geschützten Windows-Dateien mit dem Komponentenspeicher und ersetzt veränderte oder beschädigte. Immer NACH der Abbild-Reparatur ausführen.'
       Cmd = 'sfc /scannow   (Auswertung danach aus %windir%\Logs\CBS\CBS.log)' }
    @{ Key = 'SfcVerify'; Cat = 'Sys'; Ord = 135; Glyph = '&#xE73E;'; Risk = 'Safe'; Reboot = $false; Mode = 'Job'; Min = 12; Fn = 'Invoke-WrSys'
       Title = 'Systemdateien nur prüfen'; Desc = 'Wie "prüfen und reparieren", ändert aber nichts - zeigt nur, ob geschützte Windows-Dateien beschädigt sind.'
       Cmd = 'sfc /verifyonly' }
    @{ Key = 'CbsReport'; Cat = 'Sys'; Ord = 145; Glyph = '&#xE8A5;'; Risk = 'Safe'; Reboot = $false; Mode = 'Job'; Min = 1; Fn = 'Invoke-WrSys'
       Title = 'SFC-Ergebnis auswerten'; Desc = 'Liest die Windows-Protokolldatei CBS.log und listet, welche Dateien SFC beim letzten Lauf reparieren konnte und welche nicht.'
       Cmd = 'Auswertung der [SR]-Zeilen in %windir%\Logs\CBS\CBS.log (Repairing/Repaired file, Cannot repair member file, Could not reproject)' }
    @{ Key = 'DismAnalyze'; Cat = 'Sys'; Ord = 150; Glyph = '&#xE9D9;'; Risk = 'Safe'; Reboot = $false; Mode = 'Job'; Min = 3; Fn = 'Invoke-WrSys'
       Title = 'Komponentenspeicher analysieren'; Desc = 'Zeigt, wie groß der Ordner WinSxS wirklich ist (vieles ist nur verlinkt), wie viele alte Pakete entfernbar sind und ob eine Bereinigung empfohlen wird.'
       Cmd = 'DISM /Online /Cleanup-Image /AnalyzeComponentStore' }
    @{ Key = 'DismCleanup'; Cat = 'Sys'; Ord = 155; Glyph = '&#xE74D;'; Risk = 'Safe'; Reboot = $false; Mode = 'Job'; Min = 10; Fn = 'Invoke-WrSys'
       Title = 'Komponentenspeicher bereinigen'; Desc = 'Entfernt ersetzte Versionen von Windows-Bauteilen, die nach Updates übrig bleiben. Installierte Updates bleiben deinstallierbar.'
       Cmd = 'DISM /Online /Cleanup-Image /StartComponentCleanup' }
    @{ Key = 'DismResetBase'; Cat = 'Sys'; Ord = 156; Glyph = '&#xE74D;'; Risk = 'Deep'; Reboot = $false; Mode = 'Job'; Min = 20; Fn = 'Invoke-WrSys'
       Title = 'Bereinigen mit ResetBase'; Desc = 'Löscht zusätzlich alle ersetzten Versionen endgültig. Spart am meisten Platz - aber bereits installierte Updates lassen sich danach NICHT mehr deinstallieren.'
       Cmd = 'DISM /Online /Cleanup-Image /StartComponentCleanup /ResetBase' }
    @{ Key = 'PendingRevert'; Cat = 'Sys'; Ord = 0; Glyph = '&#xE7A7;'; Risk = 'Deep'; Reboot = $true; Mode = 'Ui'; Min = 0; Fn = 'Invoke-WrDirect'
       Title = 'Hängende Update-Aktionen zurücknehmen'; Desc = 'Wenn Windows nach einem Update in der Schleife "Änderungen werden rückgängig gemacht" hängt: Ausstehende Aktionen lassen sich sicher nur aus der Wiederherstellungsumgebung zurücknehmen. Zeigt die Anleitung und startet auf Wunsch WinRE.'
       Cmd = 'In WinRE > Problembehandlung > Erweiterte Optionen > Eingabeaufforderung:  dism /Image:C:\ /Cleanup-Image /RevertPendingActions  (Laufwerksbuchstabe in WinRE vorher mit "dir C:\Windows" prüfen)' }

    @{ Key = 'WuReset'; Cat = 'Wu'; Ord = 210; Glyph = '&#xE895;'; Risk = 'Reboot'; Reboot = $true; Mode = 'Job'; Min = 3; Fn = 'Invoke-WrWu'
       Title = 'Windows Update komplett zurücksetzen'; Desc = 'Stoppt die Update-Dienste, legt SoftwareDistribution und catroot2 neu an (die alten bleiben als Sicherung), leert die BITS-Warteschlange und setzt die Berechtigungen von BITS und Windows Update auf Standard, falls sie verbogen sind. Der Update-Verlauf in den Einstellungen ist danach leer.'
       Cmd = 'net stop wuauserv, bits, cryptsvc, msiserver, usosvc, dosvc | ren %windir%\SoftwareDistribution und System32\catroot2 (*.bak_Zeitstempel) | del qmgr*.dat | sc sdshow/sdset bits und wuauserv (nur bei Abweichung, Standard-SDDL) | netsh winhttp reset proxy | net start  (das Neuregistrieren alter DLLs per regsvr32 ist seit Windows 10 wirkungslos und entfällt)' }
    @{ Key = 'WuPendingCheck'; Cat = 'Wu'; Ord = 205; Glyph = '&#xE823;'; Risk = 'Safe'; Reboot = $false; Mode = 'Job'; Min = 1; Fn = 'Invoke-WrWu'
       Title = 'Wartenden Update-Zustand prüfen'; Desc = 'Prüft, ob Windows auf einen Neustart wartet (Neustart-Markierungen, pending.xml, ausstehende Dateiumbenennungen) und nennt den sicheren Weg. Ändert nichts.'
       Cmd = 'Component Based Servicing\RebootPending, WindowsUpdate\Auto Update\RebootRequired, Session Manager\PendingFileRenameOperations, %windir%\WinSxS\pending.xml' }
    @{ Key = 'DoCache'; Cat = 'Wu'; Ord = 215; Glyph = '&#xE896;'; Risk = 'Safe'; Reboot = $false; Mode = 'Job'; Min = 1; Fn = 'Invoke-WrWu'
       Title = 'Übermittlungsoptimierung leeren'; Desc = 'Löscht den Zwischenspeicher, über den Windows Update-Teile mit anderen PCs austauscht. Hilft bei Downloads, die bei einem bestimmten Prozentwert hängen.'
       Cmd = 'Delete-DeliveryOptimizationCache -Force' }
    @{ Key = 'WuTroubleshoot'; Cat = 'Wu'; Ord = 220; Glyph = '&#xE9CE;'; Risk = 'Safe'; Reboot = $false; Mode = 'Job'; Min = 5; Fn = 'Invoke-WrWu'
       Title = 'Windows Update-Problembehandlung'; Desc = 'Startet die eingebaute Problembehandlung von Microsoft ohne Rückfragen. Wurde sie in neueren Windows-11-Versionen entfernt, steht das im Protokoll - dann über "Einstellungen > Problembehandlung" (Kachel daneben).'
       Cmd = 'Get-TroubleshootingPack %windir%\diagnostics\system\WindowsUpdate | Invoke-TroubleshootingPack -Unattended -Result <Datenordner>  (msdt.exe ist in Windows 11 abgekündigt)' }
    @{ Key = 'WuTroubleUi'; Cat = 'Wu'; Ord = 0; Glyph = '&#xE8A7;'; Risk = 'Safe'; Reboot = $false; Mode = 'Ui'; Min = 0; Fn = 'Invoke-WrDirect'
       Title = 'Problembehandlung in den Einstellungen'; Desc = 'Öffnet "Einstellungen > System > Problembehandlung" - dort startet Windows 11 die aktuellen Hilfe-Assistenten für Windows Update und Netzwerk.'
       Cmd = 'start ms-settings:troubleshoot' }
    @{ Key = 'WuScan'; Cat = 'Wu'; Ord = 290; Glyph = '&#xE72C;'; Risk = 'Safe'; Reboot = $false; Mode = 'Job'; Min = 1; Fn = 'Invoke-WrWu'
       Title = 'Update-Suche anstoßen'; Desc = 'Windows Update sucht sofort neu nach Updates - sinnvoll als letzter Schritt nach einem Zurücksetzen.'
       Cmd = 'UsoClient.exe StartScan' }
    @{ Key = 'WuFixUi'; Cat = 'Wu'; Ord = 0; Glyph = '&#xE777;'; Risk = 'Reboot'; Reboot = $true; Mode = 'Ui'; Min = 0; Fn = 'Invoke-WrDirect'
       Title = 'Mit Windows Update neu aufspielen'; Desc = 'Einstellungen > System > Wiederherstellung > "Probleme mithilfe von Windows Update beheben": lädt die installierte Windows-Version neu und installiert sie darüber. Programme, Dateien und Einstellungen bleiben. Braucht Internet und etwa eine Stunde.'
       Cmd = 'start ms-settings:recovery  > "Jetzt neu installieren"' }
    @{ Key = 'WuBlockAnalyze'; Cat = 'Wu'; Ord = 200; Glyph = '&#xE721;'; Risk = 'Safe'; Reboot = $false; Mode = 'Job'; Min = 1; Fn = 'Invoke-WrWu'
       Title = 'Funktionsupdate-Blocker finden'; Desc = 'Liest die Setup-Protokolle des letzten Funktionsupdate-Versuchs (ScanResult.xml, setuperr.log, setupact.log) und nennt den Grund beim Namen: hart blockierende Programme (z.B. altes VMware), unsignierte/blockierende Treiber, Fremd-Virenschutz (wsc:wica) und den Setup-Fehlercode im Klartext. Prüft zusätzlich installierte Upgrade-Blocker und aktiven Fremd-Virenschutz. Ändert nichts.'
       Cmd = 'ScanResult.xml (Program BlockingType=Hard, DriverPackage BlockMigration=True) | setuperr.log (0xC1900208/0xC1900101 ...) | setupact.log (wsc:wica reports HardBlock) | SecurityCenter2 AntiVirusProduct | Uninstall-Liste (VMware/VirtualBox)' }
    @{ Key = 'WuStuckSetup'; Cat = 'Wu'; Ord = 207; Glyph = '&#xE711;'; Risk = 'Deep'; Reboot = $true; Mode = 'Job'; Min = 1; Fn = 'Invoke-WrWu'
       Title = 'Hängendes Setup lösen ("andere Instanz läuft")'; Desc = 'Hilft, wenn Windows meldet "Windows Setup kann nicht gestartet werden, während bereits eine andere Instanz ausgeführt wird" oder ein Update bzw. eine Reparaturinstallation nicht startet. Beendet hängende Setup-Prozesse (SetupHost, setupprep, WindowsUpdateBox, Setup aus ~BT/~WS). Nur benutzen, wenn gerade KEIN gewolltes Funktionsupdate läuft.'
       Cmd = 'Stop-Process SetupHost, setupprep, WindowsUpdateBox, setup (nur aus Setup-Pfad) ; danach Neustart' }
    @{ Key = 'WuVulnDriver'; Cat = 'Wu'; Ord = 230; Glyph = '&#xE730;'; Risk = 'Deep'; Reboot = $false; Mode = 'Job'; Min = 2; Fn = 'Invoke-WrWu'
       Title = 'Angreifbare Alt-Treiber entfernen (Sperrliste)'; Desc = 'Entfernt bekannte alte, angreifbare Hilfstreiber, die Windows auf die Sperrliste gesetzt hat und die beim Start die Meldung "Ein Treiber kann auf diesem Gerät nicht geladen werden" auslösen (z.B. iqvw64e.sys, Intel-Ethernet-Diagnose). Entfernt Treiberpaket, Dienst und Datei - mit Sicherung. Geräte laufen mit den normalen Windows-Treibern weiter.'
       Cmd = 'pnputil /delete-driver oemXX.inf /uninstall ; sc delete <Treiber> ; Datei nach Sicherung löschen (iqvw64e.sys, NalDrv.sys)' }

    @{ Key = 'NetEvidence'; Cat = 'Net'; Ord = 301; Glyph = '&#xE8A5;'; Risk = 'Safe'; Reboot = $false; Mode = 'Job'; Min = 2; Fn = 'Invoke-WrNet'
       Title = 'Netzwerk-Beweissicherung'; Desc = 'Schreibt vor jeder Änderung den kompletten Ist-Zustand in eine Textdatei: Adressen, Bindungen, Filtertreiber, Winsock, Dienste, DHCP-Ereignisse und den Zustand der Filterplattform. Ändert nichts.'
       Cmd = 'ipconfig /all | netsh int ipv4 show config | route print -4 | Get-NetAdapterBinding -AllBindings | pnputil /enum-drivers /class NetService | netsh winsock show catalog | netsh wfp show state | Dhcp-Client-Ereignisse' }
    @{ Key = 'NetSvcDefaults'; Cat = 'Net'; Ord = 310; Glyph = '&#xE713;'; Risk = 'Reboot'; Reboot = $true; Mode = 'Job'; Min = 1; Fn = 'Invoke-WrNet'
       Title = 'Netzwerkdienste auf Windows-Standard'; Desc = 'Vergleicht Starttyp, Programmpfad und Abhängigkeiten von 20 Netzwerkdiensten und -treibern (DHCP-Client, DNS, NSI, TCP/IP, AFD, NDIS, Firewall, WLAN, Verbindungs-Manager, WinHTTP-Autoproxy ...) mit den Windows-11-Vorgaben und setzt nur abweichende Werte zurück. Vorher zeigt PC-Tools die Abweichungen.'
       Cmd = 'HKLM\SYSTEM\CurrentControlSet\Services\<Dienst>: Start, ImagePath, DependOnService (Sicherung per reg export vorher)' }
    @{ Key = 'NetIpv4Fix'; Cat = 'Net'; Ord = 320; Glyph = '&#xE839;'; Risk = 'Safe'; Reboot = $false; Mode = 'Job'; Min = 1; Fn = 'Invoke-WrNet'
       Title = 'IPv4 der Adapter auf automatisch (DHCP)'; Desc = 'Prüft je WLAN- und LAN-Adapter, ob IPv4 eingeschaltet ist, ob DHCP an ist und ob noch alte feste Adressen gespeichert sind - und stellt alles auf automatischen Bezug um, wo das nicht stimmt.'
       Cmd = 'Tcpip\Parameters\Interfaces\{GUID}: EnableDHCP, IPAddress | Enable-NetAdapterBinding ms_tcpip | Set-NetIPInterface -Dhcp Enabled | Set-DnsClientServerAddress -ResetServerAddresses' }
    @{ Key = 'NetIpv6Comp'; Cat = 'Net'; Ord = 325; Glyph = '&#xE774;'; Risk = 'Reboot'; Reboot = $true; Mode = 'Job'; Min = 1; Fn = 'Invoke-WrNet'
       Title = 'IPv6-Komponenten auf Standard'; Desc = 'Der Wert DisabledComponents schaltet Teile von IPv6 ab oder bevorzugt IPv4. Manche Tuning-Programme setzen ihn falsch - das stört dann auch IPv4. Setzt ihn auf 0 (Windows-Standard).'
       Cmd = 'HKLM\SYSTEM\CurrentControlSet\Services\Tcpip6\Parameters  DisabledComponents = 0' }
    @{ Key = 'NetBcastToggle'; Cat = 'Net'; Ord = 327; Glyph = '&#xE895;'; Risk = 'Safe'; Reboot = $false; Mode = 'Job'; Min = 1; Fn = 'Invoke-WrNet'
       Title = 'DHCP-Broadcast-Wechsel einschalten'; Desc = 'Kommt auf die Adress-Anfrage keine Antwort, fragt Windows automatisch noch einmal mit umgeschaltetem Broadcast-Bit. Hilft bei Routern und Access Points, die eine der beiden Varianten ignorieren.'
       Cmd = 'HKLM\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters  DhcpConnEnableBcastFlagToggle = 1 (DWORD)' }
    @{ Key = 'NetFilterOff'; Cat = 'Net'; Ord = 330; Glyph = '&#xE71C;'; Risk = 'Safe'; Reboot = $false; Mode = 'Job'; Min = 1; Fn = 'Invoke-WrNet'
       Title = 'Fremde Netzwerkfilter lösen'; Desc = 'Schaltet an allen echten Adaptern die Bindung von Filtern und Protokollen anderer Hersteller aus (Virenschutz wie Panda, VPN, Paketmitschnitt, Virtualisierung). Virenschutz-Filter sind eine der häufigsten Ursachen für "DHCP-Anfrage geht raus, aber keine Antwort kommt an". Rückgängig in der Filterliste unten.'
       Cmd = 'Get-NetAdapterBinding -AllBindings | ? ComponentID -notmatch "^(ms_|vms_)" | Disable-NetAdapterBinding (Liste als JSON im Datenordner)' }
    @{ Key = 'NetGhost'; Cat = 'Net'; Ord = 335; Glyph = '&#xE7BA;'; Risk = 'Safe'; Reboot = $false; Mode = 'Job'; Min = 1; Fn = 'Invoke-WrNet'
       Title = 'Versteckte Netzwerkadapter entfernen'; Desc = 'Entfernt Geräteeinträge von Netzwerkadaptern, die nicht mehr vorhanden sind (alte USB-Adapter, Hyper-V- und VPN-Reste). Solche Geister können Namen, Einstellungen und Bindungen blockieren.'
       Cmd = 'Get-PnpDevice -Class Net | ? Present -eq $false | % { pnputil /remove-device <InstanceId> }' }
    @{ Key = 'NetDrvReinstall'; Cat = 'Net'; Ord = 340; Glyph = '&#xE964;'; Risk = 'Safe'; Reboot = $false; Mode = 'Job'; Min = 2; Fn = 'Invoke-WrNet'
       Title = 'Adaptertreiber neu installieren'; Desc = 'Entfernt WLAN- und LAN-Adapter aus der Geräteverwaltung und lässt Windows sie sofort neu erkennen. Der Treiber wird frisch geladen, alle Adaptereinstellungen stehen wieder auf Standard. Die Verbindung ist kurz weg.'
       Cmd = 'pnputil /remove-device <InstanceId> ; pnputil /scan-devices  (wie Netzwerk-Diagnose > Treiber neu laden)' }
    @{ Key = 'NetWinhttp'; Cat = 'Net'; Ord = 345; Glyph = '&#xE909;'; Risk = 'Safe'; Reboot = $false; Mode = 'Job'; Min = 1; Fn = 'Invoke-WrNet'
       Title = 'Proxy zurücksetzen'; Desc = 'Setzt den Systemproxy (WinHTTP - benutzt von Windows Update und Diensten) und den Proxy des Benutzers zurück. Schadsoftware und alte Firmen-Einstellungen hinterlassen hier gern Reste.'
       Cmd = 'netsh winhttp reset proxy ; HKCU\...\Internet Settings ProxyEnable = 0' }
    @{ Key = 'NetFlush'; Cat = 'Net'; Ord = 350; Glyph = '&#xE72C;'; Risk = 'Safe'; Reboot = $false; Mode = 'Job'; Min = 1; Fn = 'Invoke-WrNet'
       Title = 'Zwischenspeicher leeren (DNS, ARP, NetBIOS)'; Desc = 'Vergisst gemerkte Namen und Hardwareadressen im Netz. Hilft, wenn Seiten oder Geräte an alten Adressen gesucht werden.'
       Cmd = 'ipconfig /flushdns ; netsh interface ip delete arpcache ; nbtstat -R' }
    @{ Key = 'NetRenew'; Cat = 'Net'; Ord = 390; Glyph = '&#xE895;'; Risk = 'Safe'; Reboot = $false; Mode = 'Job'; Min = 2; Fn = 'Invoke-WrNet'
       Title = 'Adressen neu anfordern'; Desc = 'Gibt alle IPv4-Adressen frei und fordert sie beim Router neu an. Die Verbindung ist dabei kurz unterbrochen.'
       Cmd = 'ipconfig /release ; ipconfig /renew' }
    @{ Key = 'NetIpReset'; Cat = 'Net'; Ord = 360; Glyph = '&#xE839;'; Risk = 'Reboot'; Reboot = $true; Mode = 'Job'; Min = 1; Fn = 'Invoke-WrNet'
       Title = 'TCP/IP (IPv4) zurücksetzen'; Desc = 'Schreibt die IPv4-Einstellungen in der Registrierung neu. Feste IP-Adressen gehen dabei verloren. Was geändert wurde, steht in einer Protokolldatei im Datenordner.'
       Cmd = 'netsh int ip reset "<Datenordner>\WinRepair\ipreset_<Zeit>.log"' }
    @{ Key = 'NetIpv6Reset'; Cat = 'Net'; Ord = 361; Glyph = '&#xE774;'; Risk = 'Reboot'; Reboot = $true; Mode = 'Job'; Min = 1; Fn = 'Invoke-WrNet'
       Title = 'IPv6 zurücksetzen'; Desc = 'Setzt die IPv6-Einstellungen, Routen und Präfixrichtlinien auf Standard zurück.'
       Cmd = 'netsh int ipv6 reset "<Datenordner>\WinRepair\ipv6reset_<Zeit>.log"' }
    @{ Key = 'NetWinsock'; Cat = 'Net'; Ord = 362; Glyph = '&#xE943;'; Risk = 'Reboot'; Reboot = $true; Mode = 'Job'; Min = 1; Fn = 'Invoke-WrNet'
       Title = 'Winsock zurücksetzen'; Desc = 'Setzt den Winsock-Katalog auf Standard und entfernt eingeklinkte Fremdmodule (LSPs) von Virenschutz, VPN oder Werbe-Software.'
       Cmd = 'netsh winsock reset' }
    @{ Key = 'NetWfp'; Cat = 'Net'; Ord = 365; Glyph = '&#xE72E;'; Risk = 'Safe'; Reboot = $false; Mode = 'Job'; Min = 2; Fn = 'Invoke-WrNet'
       Title = 'Filterplattform sichern und neu starten'; Desc = 'Über die Windows-Filterplattform (WFP) prüfen Firewall und Virenschutz jedes Paket. PC-Tools sichert ihren Zustand als Beweis und startet Basisfilterdienst und Firewall neu. Die Filter selbst lassen sich nur über "Firewall auf Standard" oder das Entfernen des Virenschutzes löschen.'
       Cmd = 'netsh wfp show state file=<...> ; netsh wfp show filters file=<...> ; Restart-Service BFE -Force ; Start-Service mpssvc (+ abhängige Dienste)' }
    @{ Key = 'NetFirewallReset'; Cat = 'Net'; Ord = 370; Glyph = '&#xE785;'; Risk = 'Deep'; Reboot = $false; Mode = 'Job'; Min = 1; Fn = 'Invoke-WrNet'
       Title = 'Windows-Firewall auf Standard'; Desc = 'Löscht alle eigenen und von Programmen angelegten Firewall-Regeln und stellt die Windows-Vorgabe her. Vorher wird eine Sicherung exportiert. Programme fragen danach neu nach Freigaben.'
       Cmd = 'netsh advfirewall export "<Datenordner>\WinRepair\Firewall_<Zeit>.wfw" ; netsh advfirewall reset  (zurück: netsh advfirewall import <Datei>)' }
    @{ Key = 'NetNetcfg'; Cat = 'Net'; Ord = 380; Glyph = '&#xE7EF;'; Risk = 'Deep'; Reboot = $true; Mode = 'Job'; Min = 2; Fn = 'Invoke-WrNet'
       Title = 'Netzwerk komplett neu installieren'; Desc = 'Wie "Einstellungen > Netzwerkzurücksetzung": Alle Netzwerkadapter und -komponenten werden entfernt und beim Neustart neu installiert, dazu TCP/IP, IPv6, Winsock und Proxy zurückgesetzt. VPN-Programme und virtuelle Switches müssen danach eventuell neu eingerichtet werden.'
       Cmd = 'netsh int ip reset ; netsh int ipv6 reset ; netsh winsock reset ; netsh winhttp reset proxy ; netcfg -d  (danach Neustart)' }
    @{ Key = 'NetHyperV'; Cat = 'Net'; Ord = 0; Glyph = '&#xE7F4;'; Risk = 'Safe'; Reboot = $false; Mode = 'Ui'; Min = 0; Fn = 'Invoke-WrDirect'
       Title = 'Hyper-V-Reste (Netzwerk-Diagnose)'; Desc = 'Verwaiste Switch-Bindungen, WinNAT, Internetverbindungsfreigabe und der Hypervisor werden auf der Seite Netzwerk-Diagnose geprüft und repariert - der Knopf führt direkt dorthin.'
       Cmd = 'Seite Netzwerk-Diagnose > Hyper-V (Get-VMSwitch, vms_pp-Bindung, winnat, hns, SharedAccess, bcdedit hypervisorlaunchtype)' }

    @{ Key = 'BcdExport'; Cat = 'Boot'; Ord = 410; Glyph = '&#xE8C8;'; Risk = 'Safe'; Reboot = $false; Mode = 'Job'; Min = 1; Fn = 'Invoke-WrBoot'
       Title = 'Startkonfiguration sichern'; Desc = 'Sichert die Startkonfiguration (BCD) in den Datenordner und schreibt alle Einträge lesbar in eine Textdatei.'
       Cmd = 'bcdedit /export "<Datenordner>\WinRepair\BCD-Sicherung_<Zeit>" ; bcdedit /enum all > BCD_<Zeit>.txt  (zurück: bcdedit /import <Datei>)' }
    @{ Key = 'BootFiles'; Cat = 'Boot'; Ord = 470; Glyph = '&#xE7E8;'; Risk = 'Deep'; Reboot = $true; Mode = 'Job'; Min = 1; Fn = 'Invoke-WrBoot'
       Title = 'Startdateien neu schreiben'; Desc = 'Bindet die versteckte EFI-Systempartition kurz ein und schreibt Start-Manager und Startkonfiguration mit bcdboot neu (vorher automatische Sicherung, BitLocker wird für einen Neustart angehalten). Hilft bei "Bootmanager fehlt" oder fehlendem Windows-Eintrag.'
       Cmd = 'bcdedit /export <Sicherung> ; mountvol S: /s ; bcdboot C:\Windows /s S: /f UEFI ; mountvol S: /d   (Legacy-BIOS: bcdboot C:\Windows)' }
    @{ Key = 'WinReInfo'; Cat = 'Boot'; Ord = 420; Glyph = '&#xE946;'; Risk = 'Safe'; Reboot = $false; Mode = 'Job'; Min = 1; Fn = 'Invoke-WrBoot'
       Title = 'Wiederherstellungsumgebung prüfen'; Desc = 'Zeigt, ob WinRE (Starthilfe, Zurücksetzen, Systemwiederherstellung beim Start) eingeschaltet ist und wo sie liegt.'
       Cmd = 'reagentc /info' }
    @{ Key = 'WinReEnable'; Cat = 'Boot'; Ord = 425; Glyph = '&#xE7EF;'; Risk = 'Safe'; Reboot = $false; Mode = 'Job'; Min = 3; Fn = 'Invoke-WrBoot'
       Title = 'Wiederherstellungsumgebung einschalten'; Desc = 'Schaltet WinRE ein. Fehlt die Datei Winre.wim, holt PC-Tools sie aus der Reparaturquelle (Windows-ISO oben) und meldet sie neu an.'
       Cmd = 'reagentc /enable ; bei fehlender Winre.wim: install.wim\Windows\System32\Recovery\Winre.wim > C:\Windows\System32\Recovery ; reagentc /setreimage /path C:\Windows\System32\Recovery ; reagentc /enable' }
    @{ Key = 'BootToRe'; Cat = 'Boot'; Ord = 0; Glyph = '&#xE777;'; Risk = 'Reboot'; Reboot = $true; Mode = 'Ui'; Min = 0; Fn = 'Invoke-WrDirect'
       Title = 'Jetzt in die Wiederherstellung starten'; Desc = 'Startet den PC sofort neu in die Windows-Wiederherstellungsumgebung (Problembehandlung, Starthilfe, Eingabeaufforderung, Systemwiederherstellung).'
       Cmd = 'reagentc /boottore ; shutdown /r /t 5   (Ersatz: shutdown /r /o /t 5)' }
    @{ Key = 'BootAdv'; Cat = 'Boot'; Ord = 0; Glyph = '&#xE7E8;'; Risk = 'Reboot'; Reboot = $true; Mode = 'Ui'; Min = 0; Fn = 'Invoke-WrDirect'
       Title = 'Erweiterte Startoptionen'; Desc = 'Neustart in das blaue Menü "Option auswählen" - wie Umschalt + Neu starten. Dort gibt es auch UEFI-Einstellungen und Starteinstellungen.'
       Cmd = 'shutdown /r /o /t 5' }
    @{ Key = 'SafeMode'; Cat = 'Boot'; Ord = 0; Glyph = '&#xE83D;'; Risk = 'Reboot'; Reboot = $true; Mode = 'Ui'; Min = 0; Fn = 'Invoke-WrDirect'
       Title = 'Abgesicherter Modus beim nächsten Start'; Desc = 'Startet Windows einmal nur mit Grundtreibern (wahlweise mit Netzwerk). Nach der Anmeldung im abgesicherten Modus schaltet PC-Tools ihn automatisch wieder aus, der übernächste Start ist wieder normal.'
       Cmd = 'bcdedit /set {current} safeboot minimal|network ; RunOnce "*PCToolsSafeModeOff" = bcdedit /deletevalue {current} safeboot' }
    @{ Key = 'SafeOff'; Cat = 'Boot'; Ord = 0; Glyph = '&#xE711;'; Risk = 'Safe'; Reboot = $false; Mode = 'Ui'; Min = 0; Fn = 'Invoke-WrDirect'
       Title = 'Abgesicherten Modus ausschalten'; Desc = 'Nimmt einen gesetzten abgesicherten Start sofort zurück - der nächste Start ist wieder normal.'
       Cmd = 'bcdedit /deletevalue {current} safeboot ; bcdedit /deletevalue {current} safebootalternateshell' }
    @{ Key = 'BootLogOn'; Cat = 'Boot'; Ord = 440; Glyph = '&#xE8A5;'; Risk = 'Reboot'; Reboot = $true; Mode = 'Job'; Min = 1; Fn = 'Invoke-WrBoot'
       Title = 'Startprotokoll einschalten'; Desc = 'Beim nächsten Start schreibt Windows jeden geladenen und nicht geladenen Treiber nach C:\Windows\ntbtlog.txt - ideal, um einen hängenden Treiber zu finden.'
       Cmd = 'bcdedit /set {current} bootlog yes' }
    @{ Key = 'BootLogOff'; Cat = 'Boot'; Ord = 441; Glyph = '&#xE8A5;'; Risk = 'Safe'; Reboot = $false; Mode = 'Job'; Min = 1; Fn = 'Invoke-WrBoot'
       Title = 'Startprotokoll ausschalten'; Desc = 'Schaltet das Startprotokoll wieder aus (die Datei ntbtlog.txt bleibt erhalten).'
       Cmd = 'bcdedit /set {current} bootlog no' }
    @{ Key = 'ChkScan'; Cat = 'Boot'; Ord = 450; Glyph = '&#xEDA2;'; Risk = 'Safe'; Reboot = $false; Mode = 'Job'; Min = 10; Fn = 'Invoke-WrBoot'
       Title = 'Laufwerk C: online prüfen'; Desc = 'Prüft das Dateisystem im laufenden Betrieb und repariert kleine Fehler sofort. Größere Fehler werden für den nächsten Start vorgemerkt.'
       Cmd = 'chkdsk C: /scan' }
    @{ Key = 'ChkBoot'; Cat = 'Boot'; Ord = 480; Glyph = '&#xEDA2;'; Risk = 'Reboot'; Reboot = $true; Mode = 'Job'; Min = 1; Fn = 'Invoke-WrBoot'
       Title = 'Laufwerk C: beim Neustart reparieren'; Desc = 'Merkt eine gründliche Prüfung mit Reparatur und Oberflächentest für den nächsten Start vor. Kann je nach Laufwerk 30 bis 120 Minuten dauern - nicht ausschalten!'
       Cmd = 'chkdsk C: /f /r (Rückfrage mit J/Y beantwortet) ; chkntfs C:' }
    @{ Key = 'DirtyQuery'; Cat = 'Boot'; Ord = 455; Glyph = '&#xE9D9;'; Risk = 'Safe'; Reboot = $false; Mode = 'Job'; Min = 1; Fn = 'Invoke-WrBoot'
       Title = 'Dateisystem-Zustand abfragen'; Desc = 'Zeigt, ob Laufwerk C: als fehlerhaft markiert ist und ob eine Prüfung beim Start geplant ist. Ändert nichts.'
       Cmd = 'fsutil dirty query C: ; chkntfs C:' }

    @{ Key = 'AppxUser'; Cat = 'Apps'; Ord = 520; Glyph = '&#xE71D;'; Risk = 'Safe'; Reboot = $false; Mode = 'Job'; Min = 5; Fn = 'Invoke-WrApps'
       Title = 'Apps neu registrieren (angemeldeter Benutzer)'; Desc = 'Meldet alle Apps des Benutzers neu bei Windows an (Einstellungen, Fotos, Rechner, Store ...). Hilft, wenn Apps sofort wieder zugehen oder gar nicht starten.'
       Cmd = 'Get-AppxPackage | % { Add-AppxPackage -Register "$($_.InstallLocation)\AppxManifest.xml" -DisableDevelopmentMode }' }
    @{ Key = 'AppxAll'; Cat = 'Apps'; Ord = 521; Glyph = '&#xE71D;'; Risk = 'Safe'; Reboot = $false; Mode = 'Job'; Min = 8; Fn = 'Invoke-WrApps'
       Title = 'Apps neu registrieren (alle Pakete)'; Desc = 'Wie oben, aber für alle auf dem PC bereitgestellten System- und Store-Apps (auch die anderer Benutzer werden für diesen Benutzer neu registriert). Dauert einige Minuten.'
       Cmd = 'Get-AppxPackage -AllUsers | ? SignatureKind -in System,Store | % { Add-AppxPackage -Register <Manifest> -DisableDevelopmentMode }' }
    @{ Key = 'StoreReset'; Cat = 'Apps'; Ord = 510; Glyph = '&#xE719;'; Risk = 'Safe'; Reboot = $false; Mode = 'Job'; Min = 2; Fn = 'Invoke-WrApps'
       Title = 'Microsoft Store zurücksetzen'; Desc = 'Leert den Store-Zwischenspeicher und setzt die Store-App im Hintergrund neu auf. Hilft bei hängenden Downloads und Anmeldefehlern im Store.'
       Cmd = 'wsreset.exe -i' }
    @{ Key = 'StartSearch'; Cat = 'Apps'; Ord = 530; Glyph = '&#xE721;'; Risk = 'Safe'; Reboot = $false; Mode = 'Job'; Min = 2; Fn = 'Invoke-WrApps'
       Title = 'Startmenü, Taskleiste und Suche reparieren'; Desc = 'Registriert die Windows-Oberfläche (Startmenü, Shell, Suche, Client-Kern) neu und startet sie neu.'
       Cmd = 'Add-AppxPackage -Register für Microsoft.Windows.StartMenuExperienceHost, ShellExperienceHost, Windows.Search, MicrosoftWindows.Client.CBS/Core ; Explorer neu starten' }
    @{ Key = 'SearchIndex'; Cat = 'Apps'; Ord = 535; Glyph = '&#xE721;'; Risk = 'Safe'; Reboot = $false; Mode = 'Job'; Min = 2; Fn = 'Invoke-WrApps'
       Title = 'Suchindex neu aufbauen'; Desc = 'Stoppt die Windows-Suche, löscht den Index (Windows.edb/Windows.db) und baut ihn neu auf. Die Suche ist danach eine Weile langsamer, bis alles neu erfasst ist.'
       Cmd = 'net stop WSearch ; del %ProgramData%\Microsoft\Search\Data\Applications\Windows\* ; SetupCompletedSuccessfully = 0 ; net start WSearch' }
    @{ Key = 'IconCache'; Cat = 'Apps'; Ord = 540; Glyph = '&#xE8B9;'; Risk = 'Safe'; Reboot = $false; Mode = 'Job'; Min = 1; Fn = 'Invoke-WrApps'
       Title = 'Symbol- und Miniaturansichten-Cache neu'; Desc = 'Bei leeren, falschen oder alten Symbolen und Vorschaubildern. Der Explorer startet dafür kurz neu.'
       Cmd = 'Explorer beenden ; del %LOCALAPPDATA%\IconCache.db, ...\Explorer\iconcache_*.db, thumbcache_*.db ; Explorer starten' }
    @{ Key = 'FontCache'; Cat = 'Apps'; Ord = 545; Glyph = '&#xE8D2;'; Risk = 'Reboot'; Reboot = $true; Mode = 'Job'; Min = 1; Fn = 'Invoke-WrApps'
       Title = 'Schriftarten-Cache neu aufbauen'; Desc = 'Bei falsch oder gar nicht dargestellten Schriften. Wirkt vollständig nach einem Neustart.'
       Cmd = 'net stop FontCache ; del %windir%\ServiceProfiles\LocalService\AppData\Local\FontCache\* und System32\FNTCACHE.DAT ; net start FontCache' }
    @{ Key = 'ExplorerRestart'; Cat = 'Apps'; Ord = 590; Glyph = '&#xE8B7;'; Risk = 'Safe'; Reboot = $false; Mode = 'Job'; Min = 1; Fn = 'Invoke-WrApps'
       Title = 'Explorer neu starten'; Desc = 'Beendet Taskleiste und Explorer und startet sie sauber mit normalen Benutzerrechten neu.'
       Cmd = 'taskkill /f /im explorer.exe ; explorer.exe (über eine Aufgabe als angemeldeter Benutzer)' }
    @{ Key = 'WingetReset'; Cat = 'Apps'; Ord = 550; Glyph = '&#xE896;'; Risk = 'Safe'; Reboot = $false; Mode = 'Job'; Min = 2; Fn = 'Invoke-WrApps'
       Title = 'winget-Quellen zurücksetzen'; Desc = 'Wenn winget keine Programme mehr findet oder mit Quellenfehlern abbricht.'
       Cmd = 'winget source reset --force ; winget source update' }

    @{ Key = 'WmiCheck'; Cat = 'Comp'; Ord = 610; Glyph = '&#xE9D9;'; Risk = 'Safe'; Reboot = $false; Mode = 'Job'; Min = 2; Fn = 'Invoke-WrComp'
       Title = 'WMI-Datenbank prüfen und reparieren'; Desc = 'WMI liefert Systeminformationen an Windows und viele Programme. Repariert wird nur, wenn die Prüfung Fehler findet - sonst bleibt alles, wie es ist.'
       Cmd = 'winmgmt /verifyrepository ; nur bei "inkonsistent": winmgmt /salvagerepository' }
    @{ Key = 'PerfCounters'; Cat = 'Comp'; Ord = 615; Glyph = '&#xE9D2;'; Risk = 'Safe'; Reboot = $false; Mode = 'Job'; Min = 2; Fn = 'Invoke-WrComp'
       Title = 'Leistungsindikatoren neu aufbauen'; Desc = 'Wenn Task-Manager, Leistungsüberwachung oder Monitoring-Programme leere Werte zeigen.'
       Cmd = 'lodctr /R ; %windir%\SysWOW64\lodctr /R ; winmgmt /resyncperf' }
    @{ Key = 'NetFx3'; Cat = 'Comp'; Ord = 620; Glyph = '&#xE943;'; Risk = 'Safe'; Reboot = $false; Mode = 'Job'; Min = 5; Fn = 'Invoke-WrComp'
       Title = '.NET Framework 3.5 reparieren'; Desc = 'Schaltet .NET Framework 3.5 (für ältere Programme) ein bzw. installiert es neu - aus Windows Update oder aus der Reparaturquelle (\sources\sxs der ISO). .NET 4.8 ist Teil von Windows und wird über Abbild-Reparatur und SFC repariert.'
       Cmd = 'DISM /Online /Enable-Feature /FeatureName:NetFx3 /All [/Source:X:\sources\sxs /LimitAccess]' }
    @{ Key = 'NetFxTool'; Cat = 'Comp'; Ord = 0; Glyph = '&#xE774;'; Risk = 'Safe'; Reboot = $false; Mode = 'Ui'; Min = 0; Fn = 'Invoke-WrDirect'
       Title = '.NET Framework Repair Tool'; Desc = 'Öffnet die Microsoft-Seite des offiziellen .NET Framework Repair Tools - für ältere Windows-Versionen und hartnäckige .NET-Installationsfehler.'
       Cmd = 'https://www.microsoft.com/download/details.aspx?id=30135' }
    @{ Key = 'VcRedist'; Cat = 'Comp'; Ord = 625; Glyph = '&#xE896;'; Risk = 'Safe'; Reboot = $false; Mode = 'Job'; Min = 5; Fn = 'Invoke-WrComp'
       Title = 'Visual-C++-Laufzeiten neu installieren'; Desc = 'Viele Programme brauchen die Microsoft-Visual-C++-Laufzeit 2015-2022. Fehlt sie oder ist sie beschädigt, starten sie mit "VCRUNTIME140.dll fehlt". Installiert x64 und x86 frisch.'
       Cmd = 'winget install --id Microsoft.VCRedist.2015+.x64 --exact --force (und .x86, auf ARM zusätzlich .arm64)' }
    @{ Key = 'GpReset'; Cat = 'Comp'; Ord = 630; Glyph = '&#xE7EF;'; Risk = 'Deep'; Reboot = $true; Mode = 'Job'; Min = 2; Fn = 'Invoke-WrComp'
       Title = 'Lokale Gruppenrichtlinien zurücksetzen'; Desc = 'Löscht die lokalen Richtliniendateien (vorher Sicherung) und wendet die Richtlinien neu an. Hilft bei "Einige Einstellungen werden von Ihrer Organisation verwaltet" nach Tuning-Programmen. NICHT an Firmen-PCs in einer Domäne - dort kommen Richtlinien vom Server.'
       Cmd = 'Sicherung ; del %windir%\System32\GroupPolicy\Machine\Registry.pol und User\Registry.pol ; gpupdate /force' }
    @{ Key = 'Spooler'; Cat = 'Comp'; Ord = 635; Glyph = '&#xE749;'; Risk = 'Safe'; Reboot = $false; Mode = 'Job'; Min = 1; Fn = 'Invoke-WrComp'
       Title = 'Druckwarteschlange zurücksetzen'; Desc = 'Löscht hängende Druckaufträge und startet den Druckdienst neu.'
       Cmd = 'net stop spooler ; del %windir%\System32\spool\PRINTERS\* ; net start spooler' }
    @{ Key = 'TimeSync'; Cat = 'Comp'; Ord = 640; Glyph = '&#xE823;'; Risk = 'Safe'; Reboot = $false; Mode = 'Job'; Min = 1; Fn = 'Invoke-WrComp'
       Title = 'Zeitdienst neu registrieren'; Desc = 'Meldet den Windows-Zeitdienst ab und neu an und gleicht die Uhr sofort ab. Eine falsche Uhrzeit stört Anmeldungen, Zertifikate und Windows Update.'
       Cmd = 'net stop w32time ; w32tm /unregister ; w32tm /register ; net start w32time ; w32tm /resync /force' }
    @{ Key = 'SecHealth'; Cat = 'Comp'; Ord = 645; Glyph = '&#xE72E;'; Risk = 'Safe'; Reboot = $false; Mode = 'Job'; Min = 3; Fn = 'Invoke-WrComp'
       Title = 'Windows-Sicherheit reparieren'; Desc = 'Setzt die App "Windows-Sicherheit" zurück, startet das Sicherheitscenter und holt frische Defender-Signaturen. Einstellungen des Virenschutzes werden NICHT verändert.'
       Cmd = 'Get-AppxPackage Microsoft.SecHealthUI -AllUsers | Reset-AppxPackage ; Start-Service wscsvc, SecurityHealthService ; Update-MpSignature' }
    @{ Key = 'HostsReset'; Cat = 'Comp'; Ord = 650; Glyph = '&#xE8A5;'; Risk = 'Deep'; Reboot = $false; Mode = 'Job'; Min = 1; Fn = 'Invoke-WrComp'
       Title = 'hosts-Datei auf Standard'; Desc = 'Ersetzt die hosts-Datei durch die leere Windows-Vorlage. Eigene Einträge (z.B. für Server im Heimnetz) werden daneben gesichert.'
       Cmd = 'copy hosts hosts.pcpflege-<Zeit>.bak ; hosts = Microsoft-Vorlage' }
    @{ Key = 'SvcCore'; Cat = 'Comp'; Ord = 655; Glyph = '&#xE713;'; Risk = 'Reboot'; Reboot = $true; Mode = 'Job'; Min = 1; Fn = 'Invoke-WrComp'
       Title = 'Wichtige Windows-Dienste auf Standard'; Desc = 'Vergleicht den Starttyp von rund 30 Kerndiensten (Windows Update, Installer, Ereignisprotokoll, WMI, Aufgabenplanung, Audio, Druck, Suche ...) mit der Windows-Vorgabe und setzt deaktivierte Dienste zurück. Die Abweichungen werden vorher angezeigt.'
       Cmd = 'HKLM\SYSTEM\CurrentControlSet\Services\<Dienst>\Start (Sicherung per reg export)' }
    @{ Key = 'TempClean'; Cat = 'Comp'; Ord = 660; Glyph = '&#xE74D;'; Risk = 'Safe'; Reboot = $false; Mode = 'Job'; Min = 2; Fn = 'Invoke-WrComp'
       Title = 'Temporäre Dateien löschen'; Desc = 'Löscht temporäre Dateien aller Benutzer und von Windows, die älter als einen Tag sind. Gesperrte Dateien bleiben liegen.'
       Cmd = 'del %TEMP%\* (je Benutzerprofil) und %windir%\Temp\* - älter als 1 Tag' }
    @{ Key = 'EventReport'; Cat = 'Comp'; Ord = 105; Glyph = '&#xE7BA;'; Risk = 'Safe'; Reboot = $false; Mode = 'Job'; Min = 1; Fn = 'Invoke-WrComp'
       Title = 'Fehlerübersicht der letzten 7 Tage'; Desc = 'Zählt kritische Ereignisse und Fehler im Systemprotokoll nach Quelle - zeigt schnell, ob Datenträger, Treiber, Dienste oder Updates Ärger machen. Ändert nichts.'
       Cmd = 'Get-WinEvent -FilterHashtable @{ LogName = "System"; Level = 1,2; StartTime = (Get-Date).AddDays(-7) } | Group-Object ProviderName' }

    @{ Key = 'RestorePoint'; Cat = 'Last'; Ord = 1; Glyph = '&#xE81C;'; Risk = 'Safe'; Reboot = $false; Mode = 'Job'; Min = 2; Fn = 'Invoke-WrLast'
       Title = 'Wiederherstellungspunkt erstellen'; Desc = 'Hält den aktuellen Stand von Windows, Treibern und Registrierung fest. Läuft vor jeder Reparatur automatisch, wenn der Haken oben gesetzt ist.'
       Cmd = 'Checkpoint-Computer -RestorePointType MODIFY_SETTINGS' }
    @{ Key = 'InPlace'; Cat = 'Last'; Ord = 0; Glyph = '&#xE777;'; Risk = 'Deep'; Reboot = $true; Mode = 'Ui'; Min = 0; Fn = 'Invoke-WrDirect'
       Title = 'Reparaturinstallation (In-place Upgrade)'; Desc = 'Installiert Windows aus einer ISO über sich selbst - Programme, Dateien und Einstellungen bleiben. Repariert fast alles, was DISM und SFC nicht schaffen. Führt zur Karte weiter unten.'
       Cmd = 'setup.exe /auto upgrade /eula accept /dynamicupdate enable /compat ignorewarning /showoobe none /quiet [/noreboot] /copylogs <Ordner>' }
    @{ Key = 'Rstrui'; Cat = 'Last'; Ord = 0; Glyph = '&#xE81C;'; Risk = 'Reboot'; Reboot = $true; Mode = 'Ui'; Min = 0; Fn = 'Invoke-WrDirect'
       Title = 'Systemwiederherstellung'; Desc = 'Setzt Windows, Treiber und Programme auf einen früheren Wiederherstellungspunkt zurück. Eigene Dateien bleiben unberührt.'
       Cmd = 'rstrui.exe' }
    @{ Key = 'ResetPc'; Cat = 'Last'; Ord = 0; Glyph = '&#xE72C;'; Risk = 'Deep'; Reboot = $true; Mode = 'Ui'; Min = 0; Fn = 'Invoke-WrDirect'
       Title = 'Diesen PC zurücksetzen'; Desc = 'Windows neu installieren - mit der Wahl "Eigene Dateien behalten" oder "Alles entfernen". Programme müssen danach neu installiert werden. Öffnet nur den Windows-Assistenten, der selbst noch einmal fragt.'
       Cmd = 'start ms-settings:recovery  (oder systemreset.exe -factoryreset)' }
    @{ Key = 'MediaPage'; Cat = 'Last'; Ord = 0; Glyph = '&#xE753;'; Risk = 'Safe'; Reboot = $false; Mode = 'Ui'; Min = 0; Fn = 'Invoke-WrDirect'
       Title = 'Windows-ISO besorgen'; Desc = 'Für Reparaturquelle und Reparaturinstallation wird eine Windows-ISO in derselben Version, Sprache und Edition gebraucht. Die Seite "Windows und Office" lädt sie direkt von Microsoft.'
       Cmd = 'Seite Windows und Office > Windows 11 ISO' }
)
$WrProfiles = @(
    @{ Key = 'Quick'; Glyph = '&#xE945;'; Title = 'Schnell & sicher'; Desc = 'In wenigen Minuten, ohne Risiko und ohne Neustart: Abbild-Schnellprüfung, SFC-Auswertung, Update-Zustand, Übermittlungsoptimierung, DNS/ARP/NetBIOS-Caches, WMI, Zeitdienst, Druckwarteschlange, temporäre Dateien und Fehlerübersicht.'
       Keys = @('EventReport', 'DismCheck', 'CbsReport', 'WuPendingCheck', 'DoCache', 'NetFlush', 'WinReInfo', 'DirtyQuery', 'WmiCheck', 'Spooler', 'TimeSync', 'TempClean'); Rp = $true; Reboot = $false }
    @{ Key = 'Check'; Glyph = '&#xE9D9;'; Title = 'Nur prüfen'; Desc = 'Ändert nichts: Abbild-Schnellprüfung, Systemdateien prüfen, SFC-Auswertung, Update-Zustand, WinRE, Dateisystem und Fehlerübersicht.'
       Keys = @('EventReport', 'DismCheck', 'SfcVerify', 'CbsReport', 'WuPendingCheck', 'WinReInfo', 'DirtyQuery'); Rp = $false; Reboot = $false }
    @{ Key = 'Sys'; Glyph = '&#xE8F1;'; Title = 'Systemdateien gründlich'; Desc = 'Die klassische Reihenfolge der Profis: Abbild prüfen und reparieren (mit ISO-Quelle, falls gewählt), danach SFC, Auswertung der CBS.log, Komponentenspeicher aufräumen, Laufwerk prüfen, WMI. Dauert 30 bis 60 Minuten.'
       Keys = @('DismCheck', 'DismScan', 'DismRestore', 'SfcScan', 'CbsReport', 'DismAnalyze', 'DismCleanup', 'ChkScan', 'DirtyQuery', 'WmiCheck'); Rp = $true; Reboot = $false }
    @{ Key = 'Wu'; Glyph = '&#xE895;'; Title = 'Windows Update reparieren'; Desc = 'Zustand prüfen, Update komplett zurücksetzen, Übermittlungsoptimierung leeren, Abbild und Systemdateien reparieren, Zeitdienst, Problembehandlung und neue Suche - mit Neustart am Ende.'
       Keys = @('WuPendingCheck', 'WuReset', 'DoCache', 'DismRestore', 'SfcScan', 'CbsReport', 'TimeSync', 'WuTroubleshoot', 'WuScan'); Rp = $true; Reboot = $true }
    @{ Key = 'Net'; Glyph = '&#xE968;'; Title = 'Netzwerk komplett zurücksetzen (Surface/DHCP)'; Desc = 'Für "keine IPv4-Adresse, DHCP-Anfrage ohne Antwort": Beweise sichern, Dienst-Vorgaben, IPv4/DHCP, IPv6-Komponenten, Broadcast-Wechsel, fremde Filter lösen, Geister-Adapter, Proxy, Caches, TCP/IP, IPv6, Winsock und Filterplattform - mit Wiederherstellungspunkt vorher und Neustart am Ende. Firewall und Netzwerkkomponenten bleiben unangetastet.'
       Keys = @('NetEvidence', 'NetSvcDefaults', 'NetIpv4Fix', 'NetIpv6Comp', 'NetBcastToggle', 'NetFilterOff', 'NetGhost', 'NetWinhttp', 'NetFlush', 'NetIpReset', 'NetIpv6Reset', 'NetWinsock', 'NetWfp'); Rp = $true; Reboot = $true }
    @{ Key = 'Apps'; Glyph = '&#xE71D;'; Title = 'Startmenü, Suche und Apps'; Desc = 'Store zurücksetzen, Oberfläche und Apps neu registrieren, Suchindex, Symbol-Cache und Explorer.'
       Keys = @('StoreReset', 'StartSearch', 'AppxUser', 'SearchIndex', 'IconCache', 'ExplorerRestart'); Rp = $true; Reboot = $false }
    @{ Key = 'Boot'; Glyph = '&#xE7E8;'; Title = 'Start absichern'; Desc = 'Startkonfiguration sichern, WinRE prüfen und einschalten, Dateisystem prüfen - damit der PC im Notfall startfähig bleibt.'
       Keys = @('BcdExport', 'WinReInfo', 'WinReEnable', 'DirtyQuery', 'ChkScan'); Rp = $false; Reboot = $false }
    @{ Key = 'Comp'; Glyph = '&#xE713;'; Title = 'Systemkomponenten'; Desc = 'WMI, Leistungsindikatoren, Windows-Sicherheit, Zeitdienst, deaktivierte Kerndienste, temporäre Dateien und Fehlerübersicht.'
       Keys = @('EventReport', 'WmiCheck', 'PerfCounters', 'SecHealth', 'TimeSync', 'SvcCore', 'TempClean'); Rp = $true; Reboot = $false }
    @{ Key = 'SxS'; Glyph = '&#xE74D;'; Title = 'WinSxS aufräumen'; Desc = 'Komponentenspeicher analysieren und alte Update-Reste entfernen (ohne ResetBase - Updates bleiben deinstallierbar).'
       Keys = @('DismAnalyze', 'DismCleanup'); Rp = $false; Reboot = $false }
    @{ Key = 'All'; Glyph = '&#xE7EF;'; Title = 'Alles außer Neuinstallation'; Desc = 'Jede Reparatur des Katalogs, die sicher ist oder nur einen Neustart braucht - in der richtigen Reihenfolge. Ausgenommen sind alle tiefgreifenden Eingriffe (Firewall, netcfg, ResetBase, Startdateien, Gruppenrichtlinien, hosts), die Prüfung beim Neustart und die Startprotokoll-Schalter. Dauert 1 bis 2 Stunden, Neustart am Ende.'
       Keys = @($WrCatalog | Where-Object { $_.Mode -eq 'Job' -and $_.Risk -ne 'Deep' -and $_.Key -notin 'ChkBoot', 'BootLogOn', 'BootLogOff', 'SfcVerify', 'RestorePoint' } | Sort-Object { [int]$_.Ord } | ForEach-Object { $_.Key }); Rp = $true; Reboot = $true }
)
# Windows-11-Vorgaben der Netzwerkdienste und -treiber (Start: 0 Boot, 1 System, 2 Automatisch, 3 Manuell, 4 Deaktiviert)
# Req = Abhängigkeiten, die vorhanden sein müssen; Allow = weitere Microsoft-Abhängigkeiten, die vorkommen dürfen; alles andere gilt als fremd
$WrNetSvcDefaults = @(
    @{ Name = 'Dhcp'; Label = 'DHCP-Client'; Start = 2; Img = '%SystemRoot%\system32\svchost.exe -k LocalServiceNetworkRestricted -p'; Req = @('Afd', 'NSI'); Allow = @('Tdx', 'Tcpip'); Note = 'Holt die IPv4-Adresse vom Router.' }
    @{ Name = 'Dnscache'; Label = 'DNS-Client'; Start = 2; Img = '%SystemRoot%\system32\svchost.exe -k NetworkService -p'; Req = @('nsi'); Allow = @('Afd', 'Tdx', 'Tcpip'); Note = 'Namensauflösung; WinHTTP-Autoproxy hängt davon ab.' }
    @{ Name = 'NlaSvc'; Label = 'Netzwerkstandort-Erkennung'; Start = 2; Loose = $true; Img = '%SystemRoot%\System32\svchost.exe -k netprofm -p'; Req = @('NSI', 'RpcSs'); Allow = @('TcpIp', 'Dhcp', 'Eventlog', 'Afd'); Note = 'Erkennt Netz und Internetzugang (Taskleistensymbol).' }
    @{ Name = 'nsi'; Label = 'Netzwerkspeicher-Schnittstelle'; Start = 2; Img = '%SystemRoot%\system32\svchost.exe -k LocalService -p'; Req = @('rpcss', 'nsiproxy'); Allow = @(); Note = 'Ohne NSI laufen DHCP, DNS und Firewall nicht.' }
    @{ Name = 'nsiproxy'; Label = 'NSI-Proxy-Treiber'; Start = 1; Img = 'system32\drivers\nsiproxy.sys'; Req = @(); Allow = @(); Note = '' }
    @{ Name = 'netprofm'; Label = 'Netzwerklistendienst'; Start = 3; Img = '%SystemRoot%\System32\svchost.exe -k LocalService -p'; Req = @('RpcSs'); Allow = @('NSI', 'nlasvc', 'Tcpip'); Note = '' }
    @{ Name = 'BFE'; Label = 'Basisfiltermodul'; Start = 2; Img = '%SystemRoot%\system32\svchost.exe -k LocalServiceNoNetworkFirewall -p'; Req = @('RpcSs'); Allow = @(); Note = 'Grundlage von Firewall und Filterplattform.' }
    @{ Name = 'mpssvc'; Label = 'Windows Defender Firewall'; Start = 2; Img = '%SystemRoot%\system32\svchost.exe -k LocalServiceNoNetworkFirewall -p'; Req = @('mpsdrv', 'bfe'); Allow = @('NSI'); Note = '' }
    @{ Name = 'mpsdrv'; Label = 'Firewall-Autorisierungstreiber'; Start = 3; Img = 'System32\drivers\mpsdrv.sys'; Req = @(); Allow = @(); Note = '' }
    @{ Name = 'Tcpip'; Label = 'TCP/IP-Protokolltreiber'; Start = 0; Img = 'System32\drivers\tcpip.sys'; Req = @(); Allow = @(); Note = 'Kern des Netzwerks.' }
    @{ Name = 'Tcpip6'; Label = 'IPv6-Protokolltreiber'; Start = 3; Img = 'System32\drivers\tcpip.sys'; Req = @(); Allow = @('Tcpip'); Note = '' }
    @{ Name = 'Afd'; Label = 'Winsock-Hilfstreiber (AFD)'; Start = 1; Img = '\SystemRoot\system32\drivers\afd.sys'; Req = @(); Allow = @(); Note = 'DHCP-Client und DNS hängen davon ab.' }
    @{ Name = 'NetBT'; Label = 'NetBIOS über TCP/IP'; Start = 1; Img = 'System32\DRIVERS\netbt.sys'; Req = @(); Allow = @('Tdx', 'tcpip'); Note = '' }
    @{ Name = 'Ndis'; Label = 'NDIS-Systemtreiber'; Start = 0; Img = 'system32\drivers\ndis.sys'; Req = @(); Allow = @(); Note = 'Ohne NDIS startet Windows nicht.' }
    @{ Name = 'WfpLwfs'; Label = 'WFP-Leichtgewichtsfilter'; Start = 0; Img = 'system32\drivers\wfplwfs.sys'; Req = @(); Allow = @('ndis'); Note = '' }
    @{ Name = 'iphlpsvc'; Label = 'IP-Hilfsdienst'; Start = 2; Img = '%SystemRoot%\System32\svchost.exe -k NetSvcs -p'; Req = @('RpcSs', 'NSI'); Allow = @('Tcpip', 'Tcpip6', 'WinHttpAutoProxySvc', 'winmgmt'); Note = '' }
    @{ Name = 'WlanSvc'; Label = 'WLAN-AutoKonfig'; Start = 2; Loose = $true; Img = '%SystemRoot%\system32\svchost.exe -k LocalSystemNetworkRestricted -p'; Req = @('RpcSs'); Allow = @('nativewifip', 'Ndisuio', 'wcmsvc'); Note = 'Ohne diesen Dienst kein WLAN.' }
    @{ Name = 'dot3svc'; Label = 'Automatische Konfiguration (verkabelt)'; Start = 3; Img = '%SystemRoot%\system32\svchost.exe -k LocalSystemNetworkRestricted -p'; Req = @('RpcSs'); Allow = @('Eaphost', 'Ndisuio'); Note = '802.1X am LAN.' }
    @{ Name = 'WcmSvc'; Label = 'Windows-Verbindungs-Manager'; Start = 2; Img = '%SystemRoot%\system32\svchost.exe -k LocalServiceNetworkRestricted -p'; Req = @('RpcSs', 'NSI'); Allow = @('WinHttpAutoProxySvc'); Note = 'Entscheidet, welche Verbindung genutzt wird.' }
    @{ Name = 'WinHttpAutoProxySvc'; Label = 'WinHTTP-Autoproxy-Erkennung'; Start = 3; Img = '%SystemRoot%\system32\svchost.exe -k LocalServiceNetworkRestricted -p'; Req = @(); Allow = @('Dhcp', 'Dnscache'); Note = 'Seit Windows 11 24H2 hängt der Verbindungs-Manager davon ab - deaktiviert heißt oft: keine IPv4-Adresse per DHCP.' }
)
