# Standard-Berechtigungen der Dienste BITS und wuauserv (Microsoft: "Windows Update-Komponenten manuell zurücksetzen")
$WrStdSddl = @{
    bits     = 'D:(A;CI;CCDCLCSWRPWPDTLOCRSDRCWDWO;;;SY)(A;;CCDCLCSWRPWPDTLOCRSDRCWDWO;;;BA)(A;;CCLCSWLOCRRC;;;IU)(A;;CCLCSWLOCRRC;;;SU)'
    wuauserv = 'D:(A;;CCLCSWRPLORC;;;AU)(A;;CCDCLCSWRPWPDTLOCRSDRCWDWO;;;BA)(A;;CCDCLCSWRPWPDTLOCRSDRCWDWO;;;SY)'
}

# ---- Nicht startende Dienste: Diagnose (warum?) und Reparatur (standalone, laufen in Invoke-Bg)
# ---- WLAN optimieren (standalone, laufen in Invoke-Bg; nutzen ConvertFrom-NtWlanText / Get-NtChannelAdvice / Format-NtMac)
function Get-WlanAdapter {
    $all = @(Get-NetAdapter -Physical -ErrorAction SilentlyContinue | Where-Object { [string]$_.NdisPhysicalMedium -eq '9' -or [string]$_.PhysicalMediaType -match '802\.11|Wireless' -or $_.InterfaceDescription -match 'Wi-?Fi|Wireless|WLAN|802\.11|AVASTAR|Centrino' })
    return ($all | Sort-Object @{ e = { [string]$_.Status -ne 'Up' } }, Name | Select-Object -First 1)
}
function Get-WlanIfInfo {
    $o = [ordered]@{ State = ''; Ssid = ''; Bssid = ''; Radio = ''; Auth = ''; Cipher = ''; Band = ''; Channel = 0; Rx = 0.0; Tx = 0.0; Signal = 0; Rssi = 0; Profile = ''; Raw = '' }
    $lines = @(& netsh.exe wlan show interfaces 2>&1 | ForEach-Object { [string]$_ })
    $o.Raw = ($lines | Select-Object -First 4) -join ' '
    foreach ($l in $lines) {
        if ($l -match '^\s*(Status|State|Zustand)\s*:\s*(.+)$') { $o.State = $Matches[2].Trim() }
        elseif ($l -match '^\s*SSID\s*:\s*(.+)$') { $o.Ssid = $Matches[1].Trim() }
        elseif ($l -match '^\s*(AP[ -])?BSSID\s*:\s*([0-9A-Fa-f:\-]{17})') { $o.Bssid = Format-NtMac $Matches[2] }
        elseif ($l -match '^\s*(Funktyp|Radio type)\s*:\s*(.+)$') { $o.Radio = $Matches[2].Trim() }
        elseif ($l -match '^\s*(Authentifizierung|Authentication)\s*:\s*(.+)$') { $o.Auth = $Matches[2].Trim() }
        elseif ($l -match '^\s*(Verschl\S*sselung|Cipher)\s*:\s*(.+)$') { $o.Cipher = $Matches[2].Trim() }
        elseif ($l -match '^\s*Band\s*:\s*(.+)$') { $o.Band = $Matches[1].Trim() -replace '2\.4', '2,4' }
        elseif ($l -match '^\s*(Kanal|Channel)\s*:\s*(\d+)') { $o.Channel = [int]$Matches[2] }
        elseif ($l -match '^\s*(Empfangsrate|Receive rate)[^:]*:\s*([\d\.,]+)') { $o.Rx = [double]($Matches[2] -replace ',', '.') }
        elseif ($l -match '^\s*(\S*bertragungsrate|Transmit rate|Senderate)[^:]*:\s*([\d\.,]+)') { $o.Tx = [double]($Matches[2] -replace ',', '.') }
        elseif ($l -match '^\s*Signal\s*:\s*(\d+)\s*%') { $o.Signal = [int]$Matches[1] }
        elseif ($l -match '^\s*Rssi\s*:\s*(-?\d+)') { $o.Rssi = [int]$Matches[1] }
        elseif ($l -match '^\s*(Profil|Profile)\s*:\s*(.+)$') { $o.Profile = $Matches[2].Trim() }
    }
    if (-not $o.Rssi -and $o.Signal) { $o.Rssi = [int]($o.Signal / 2 - 100) }
    if (-not $o.Band -and $o.Channel) { $o.Band = if ($o.Channel -le 14) { '2,4 GHz' } else { '5 GHz' } }
    return [pscustomobject]$o
}
function Get-WlanDriverCaps {
    $t = (& netsh.exe wlan show drivers 2>&1 | ForEach-Object { [string]$_ }) -join "`n"
    $radios = ''; if ($t -match '(?m)^\s*(Unterst\S*tzte Funktypen|Radio types supported)\s*:\s*(.+)$') { $radios = $Matches[2].Trim() }
    $bands = ''; if ($t -match '(?m)^\s*(Unterst\S*tzte B\S*nder|Supported bands?)\s*:\s*(.+)$') { $bands = $Matches[2].Trim() }
    [pscustomobject]@{ Radios = $radios; Bands = $bands; Ax = ($radios -match 'ax|be'); Ac = ($radios -match 'ac|ax|be'); Wpa3 = ($t -match 'WPA3'); Ghz6 = ($bands -match '\b6' -or $t -match '6\s*GHz') }
}
# Empfehlungen fuer die erweiterten Adapter-Eigenschaften (Intel, Realtek, Marvell, Qualcomm, MediaTek - deutsch/englisch)
function Get-WlanAdvPlan($Adapter, [bool]$Mesh, [bool]$Use6) {
    $plan = [System.Collections.Generic.List[object]]::new()
    $props = @(); try { $props = @(Get-NetAdapterAdvancedProperty -Name $Adapter.Name -AllProperties -ErrorAction Stop | Where-Object { $_.DisplayName -and $_.ValidDisplayValues }) } catch { }
    $rules = @(
        @{ N = '(?i)MIMO'; V = @('(?i)no ?SMPS|kein(e)? ?SMPS|keine|aus$|deaktiv|disable|max(imale|imum)? (leistung|performance)'); Why = 'MIMO-Energiesparen aus - volle Antennenleistung' }
        @{ N = '(?i)(preferred band|bevorzugtes band|band ?prefer|bandpr\S*ferenz|bandauswahl)'; V = $(if ($Use6) { @('(?i)6[\s-]*GHz', '(?i)5[\s-]*GHz|\b5G') } else { @('(?i)5[\s-]*GHz|\b5G') }); Why = 'schnelleres Band bevorzugen' }
        @{ N = '(?i)(transmit power|sendeleistung|tx ?power|übertragungsleistung|uebertragungsleistung)'; V = @('(?i)highest|h(ö|oe)chst|^max|100\s*%'); Why = 'volle Sendeleistung - stabilere Verbindung bei Abstand' }
        @{ N = '(?i)(roam\S* ?aggress|roaming-?aggress|roaming ?tendenz|roaming-?neigung)'; V = $(if ($Mesh) { @('(?i)^(4\.|mittel.?hoch|medium.?high)') } else { @() }); Why = 'Mesh/Repeater erkannt - schneller zum besseren Sender wechseln' }
        @{ N = '(?i)(2[\.,]4.*(channel width|kanalbreite|bandbreite)|(channel width|kanalbreite|bandbreite).*2[\.,]4)'; V = @('(?i)^20\s*MHz|nur 20|20 ?MHz only'); Why = '2,4 GHz nur 20 MHz breit - weniger Störungen mit Nachbarnetzen' }
        @{ N = '(?i)(5\s*GHz.*(channel width|kanalbreite|bandbreite)|(channel width|kanalbreite|bandbreite).*5\s*GHz)'; V = @('(?i)^auto|automatisch|160|80'); Why = '5 GHz volle Kanalbreite erlauben' }
        @{ N = '(?i)^(802\.11ax|802\.11ac|802\.11n|HE ?mode|VHT ?mode|HT ?mode|802\.11n/ac/ax).*'; V = @('(?i)^(aktiviert|enabled|ein|an|on|802\.11ax|.*ax.*)$'); Why = 'schnellsten Funkstandard erlauben' }
        @{ N = '(?i)(wireless mode|drahtlosmodus|wlan-?modus|funkmodus)'; V = @('(?i)ax|be', '(?i)ac'); Why = 'schnellsten Funkstandard erlauben' }
        @{ N = '(?i)(selective suspend|selektiv)'; V = @('(?i)^(disabled?|deaktiv|aus|off|nein)'); Why = 'Adapter nicht schlafen legen' }
        @{ N = '(?i)(power ?sav|energiespar|energie sparen|stromspar|leistungsspar|power ?mgmt|power management)'; V = @('(?i)^(disabled?|deaktiv|aus|off|max(imale|imum)? (leistung|performance)|h(ö|oe)chstleistung)'); Why = 'Energiesparen des Funkchips aus - keine Aussetzer' }
    )
    $used = @{}
    foreach ($r in $rules) {
        if (-not $r.V.Count) { continue }
        foreach ($p in $props) {
            $kw = [string]$p.RegistryKeyword; if ($used.ContainsKey($kw)) { continue }
            if ([string]$p.DisplayName -notmatch $r.N) { continue }
            $used[$kw] = 1
            $target = $null
            foreach ($rx in $r.V) { $target = @($p.ValidDisplayValues | Where-Object { $_ -match $rx }) | Select-Object -First 1; if ($target) { break } }
            $cur = [string]$p.DisplayValue
            $plan.Add([pscustomobject]@{ Name = [string]$p.DisplayName; Keyword = $kw; Current = $cur; CurrentReg = @($p.RegistryValue); Target = [string]$target; Change = ([bool]$target -and $target -ne $cur); Why = $r.Why })
        }
    }
    return $plan.ToArray()
}
function Get-WlanPowerIdx {
    $t = (& powercfg.exe /q SCHEME_CURRENT 19cbb8fa-5279-450e-9fac-8a3d5fedd0c1 12bbebe6-58d6-4636-95bb-3217ef867c1a 2>&1 | ForEach-Object { [string]$_ }) -join "`n"
    $v = @([regex]::Matches($t, '(?im)^\s*[^:\r\n]*(Wechselstrom|Gleichstrom|AC Power|DC Power)[^:\r\n]*:\s*0x([0-9a-f]+)') | ForEach-Object { [pscustomobject]@{ K = $(if ($_.Groups[1].Value -match 'Wechsel|AC') { 'AC' } else { 'DC' }); V = [Convert]::ToInt32($_.Groups[2].Value, 16) } })
    $ac = @($v | Where-Object { $_.K -eq 'AC' } | Select-Object -First 1); $dc = @($v | Where-Object { $_.K -eq 'DC' } | Select-Object -First 1)
    [pscustomobject]@{ AC = $(if ($ac.Count) { $ac[0].V } else { -1 }); DC = $(if ($dc.Count) { $dc[0].V } else { -1 }) }
}
function Get-WlanPowerText([int]$I) { switch ($I) { 0 { 'Höchstleistung' } 1 { 'geringes Energiesparen' } 2 { 'mittleres Energiesparen' } 3 { 'maximales Energiesparen' } default { 'unbekannt' } } }
function Get-WlanDevPower($Adapter) {
    try {
        $pnp = ([string]$Adapter.PnPDeviceID).ToUpper(); if (-not $pnp) { return $null }
        return (@(Get-CimInstance -Namespace root\wmi -ClassName MSPower_DeviceEnable -ErrorAction Stop | Where-Object { ([string]$_.InstanceName).ToUpper().StartsWith($pnp) }) | Select-Object -First 1)
    } catch { return $null }
}
function Test-WlanPing([string]$Target, [int]$Count = 20, [int]$Gap = 150) {
    $p = New-Object System.Net.NetworkInformation.Ping; $ms = [System.Collections.Generic.List[double]]::new(); $lost = 0
    for ($i = 0; $i -lt $Count; $i++) {
        try { $r = $p.Send($Target, 1000); if ($r.Status -eq 'Success') { $ms.Add([double]$r.RoundtripTime) } else { $lost++ } } catch { $lost++ }
        Start-Sleep -Milliseconds $Gap
    }
    $avg = if ($ms.Count) { ($ms | Measure-Object -Average).Average } else { 0 }
    $jit = 0.0; if ($ms.Count -gt 1) { $d = for ($i = 1; $i -lt $ms.Count; $i++) { [math]::Abs($ms[$i] - $ms[$i - 1]) }; $jit = ($d | Measure-Object -Average).Average }
    [pscustomobject]@{ Target = $Target; Sent = $Count; Lost = $lost; LossPct = [math]::Round(100.0 * $lost / [math]::Max(1, $Count), 1); Avg = [math]::Round($avg, 1); Max = $(if ($ms.Count) { ($ms | Measure-Object -Maximum).Maximum } else { 0 }); Jitter = [math]::Round($jit, 1) }
}
function Get-WlanReport {
    $o = [System.Collections.Generic.List[string]]::new(); $tips = [System.Collections.Generic.List[string]]::new()
    $add = { param($lvl, $txt) $tips.Add(('[{0}] {1}' -f $lvl, $txt)) }
    $a = Get-WlanAdapter
    if (-not $a) { return [pscustomobject]@{ Text = 'Kein WLAN-Adapter gefunden (oder er ist im Geräte-Manager deaktiviert).'; NeedLocation = $false } }
    $i = Get-WlanIfInfo; $caps = Get-WlanDriverCaps
    $raw = @(& netsh.exe wlan show networks mode=bssid 2>&1 | ForEach-Object { [string]$_ }); $rawT = $raw -join "`n"
    $needLoc = ($rawT -match '(?i)location permission|Standortberechtigung|Standort|ms-settings:privacy-location') -and -not ($rawT -match '(?m)^\s*BSSID')
    $nets = ConvertFrom-NtWlanText $raw
    $own = @($nets | Where-Object { $i.Ssid -and $_.Ssid -eq $i.Ssid })
    $mesh = (@($own | ForEach-Object { $_.Bssid } | Select-Object -Unique).Count -gt 2)
    $o.Add('== WLAN-Adapter =='); $o.Add(('  {0}  ({1})' -f $a.InterfaceDescription, $a.Status))
    $dd = $null; try { $dd = [datetime]$a.DriverDate } catch { }
    $o.Add(('  Treiber: {0}{1}{2}' -f $a.DriverVersionString, $(if ($dd) { ' vom ' + $dd.ToString('dd.MM.yyyy') } else { '' }), $(if ($a.DriverProvider) { ' (' + $a.DriverProvider + ')' } else { '' })))
    $o.Add(('  Kann: {0}{1}{2}' -f $(if ($caps.Radios) { $caps.Radios } else { '?' }), $(if ($caps.Wpa3) { ', WPA3' } else { '' }), $(if ($caps.Ghz6) { ', 6 GHz (WiFi 6E/7)' } else { '' })))
    $o.Add(''); $o.Add('== Verbindung ==')
    if (-not $i.Ssid -and -not $i.Bssid) {
        $o.Add('  nicht mit einem WLAN verbunden' + $(if ($a.Status -ne 'Up') { ' (Adapter: ' + $a.Status + ')' } else { '' }))
        if ($i.Raw -match '(?i)standort|location') { $needLoc = $true }
    } else {
        $q = if ($i.Rssi -ge -60) { 'sehr gut' } elseif ($i.Rssi -ge -67) { 'gut' } elseif ($i.Rssi -ge -75) { 'mittel' } elseif ($i.Rssi -ge -82) { 'schwach' } else { 'sehr schwach' }
        $o.Add(('  Netz: {0}   Sender (BSSID): {1}' -f $i.Ssid, $i.Bssid))
        $o.Add(('  Band/Kanal: {0}, Kanal {1}   Funkstandard: {2}' -f $i.Band, $i.Channel, $i.Radio))
        $o.Add(('  Signal: {0} % (ca. {1} dBm) - {2}' -f $i.Signal, $i.Rssi, $q))
        $o.Add(('  Verbindungstempo: empfangen {0} / senden {1} Mbit/s' -f $i.Rx, $i.Tx))
        $o.Add(('  Sicherheit: {0} / {1}' -f $i.Auth, $i.Cipher))
        if ($mesh) { $o.Add(('  Mesh/Repeater: {0} Sender mit diesem Netznamen in Reichweite' -f @($own | ForEach-Object { $_.Bssid } | Select-Object -Unique).Count)) }
        if ($i.Rssi -lt -75) { & $add 'PROBLEM' 'Signal schwach - näher an den Router/Repeater, Router höher und frei aufstellen oder einen Mesh-Repeater setzen.' }
        elseif ($i.Rssi -lt -67) { & $add 'TIPP' 'Signal nur mittel - für Videokonferenzen/Streaming besser näher an den Sender oder 5 GHz nutzen.' }
        else { & $add 'OK' 'Signalstärke gut.' }
        $is24 = ($i.Band -match '^2' -or ($i.Channel -ge 1 -and $i.Channel -le 14))
        $own5 = @($own | Where-Object { $_.BandKey -in '5', '6' } | Sort-Object Signal -Descending | Select-Object -First 1)
        if ($is24 -and $own5.Count -and $own5[0].Signal -ge 40) { & $add 'TIPP' ('Verbunden über 2,4 GHz, obwohl dein Netz auch auf {0} GHz mit {1} % empfangen wird. "Optimieren" stellt den Adapter auf 5 GHz bevorzugen.' -f $own5[0].BandKey, $own5[0].Signal) }
        elseif ($is24) { & $add 'TIPP' '2,4 GHz ist langsam und störanfällig. Wenn der Router 5 GHz kann: dort einschalten (gleicher Netzname reicht, Band-Steering).' }
        if ($i.Radio -match '802\.11(n|g|b|a)$' -and $caps.Ac) { & $add 'TIPP' ('Verbunden mit {0}, der Adapter kann aber mehr ({1}). Router-Einstellung "WLAN-Standard" prüfen (ac/ax einschalten) bzw. 5 GHz nutzen.' -f $i.Radio, $caps.Radios) }
        if ($i.Rx -gt 0 -and $i.Rx -lt 50 -and -not $is24) { & $add 'TIPP' ('Verbindungstempo nur {0} Mbit/s trotz 5 GHz - meist Abstand/Wände. Näher an den Sender oder Mesh-Repeater.' -f $i.Rx) }
        if ($i.Auth -match '(?i)offen|open' -or $i.Cipher -match '(?i)WEP|TKIP') { & $add 'PROBLEM' ('Unsichere Verschlüsselung ({0}/{1}) - im Router WPA2-AES oder WPA3 einstellen.' -f $i.Auth, $i.Cipher) }
        elseif ($i.Auth -notmatch 'WPA3' -and $caps.Wpa3) { & $add 'INFO' 'Dein Adapter kann WPA3. Kann der Router es auch, im Router "WPA2+WPA3" einschalten - sicherer.' }
        if ($nets.Count) {
            $adv = Get-NtChannelAdvice $nets $i.Ssid
            if ($is24) {
                $same = @($nets | Where-Object { $_.BandKey -eq '2.4' -and $_.Ssid -ne $i.Ssid -and [math]::Abs($_.Channel - $i.Channel) -lt 5 }).Count
                $o.Add(('  2,4 GHz: {0} fremde Netze, {1} davon überlappen mit Kanal {2}. Am freiesten: Kanal {3}.' -f $adv.Count24, $same, $i.Channel, $adv.Best24))
                if ($same -ge 3 -and $adv.Best24 -ne $i.Channel) { & $add 'TIPP' ('Kanal {0} ist voll ({1} überlappende Netze). Im Router auf Kanal {2} stellen (oder "automatisch").' -f $i.Channel, $same, $adv.Best24) }
            } else {
                $same = @($nets | Where-Object { $_.BandKey -in '5', '6' -and $_.Ssid -ne $i.Ssid -and $_.Channel -eq $i.Channel }).Count
                $o.Add(('  5 GHz: {0} fremde Sender, {1} auf deinem Kanal {2}. Am freiesten: Bereich {3}.' -f $adv.Count5, $same, $i.Channel, $adv.Best5Block))
                if ($same -ge 3) { & $add 'TIPP' ('Auf Kanal {0} funken {1} fremde Sender. Im Router den Bereich {2} wählen (oder "automatisch").' -f $i.Channel, $same, $adv.Best5Block) }
            }
        }
        $gw = ''; try { $gw = [string](@(Get-NetIPConfiguration -InterfaceIndex $a.ifIndex -ErrorAction Stop).IPv4DefaultGateway | Select-Object -First 1).NextHop } catch { }
        if ($gw) {
            $pg = Test-WlanPing $gw 20 100
            $o.Add(('  Router {0}: Ping {1} ms (max {2}), Schwankung {3} ms, Verlust {4} %' -f $gw, $pg.Avg, $pg.Max, $pg.Jitter, $pg.LossPct))
            if ($pg.LossPct -ge 5) { & $add 'PROBLEM' ('{0} % Paketverlust zum Router - Funkstörung oder zu weit weg.' -f $pg.LossPct) }
            elseif ($pg.Jitter -ge 15 -or $pg.Avg -ge 20) { & $add 'TIPP' 'Ping zum Router schwankt stark - typisch für Energiesparen des Adapters oder ein volles Band. "Optimieren" hilft oft.' }
            else { & $add 'OK' 'Verbindung zum Router stabil (kein Verlust, wenig Schwankung).' }
        }
    }
    if ($needLoc) { & $add 'INFO' 'Windows gibt die Liste der WLANs in Reichweite nur mit Standortberechtigung heraus - Knopf "Standortdienste" (für Desktop-Apps einschalten). Ohne sie fehlen Kanal-Empfehlungen.' }
    if ($dd -and $dd -lt (Get-Date).AddYears(-2)) { & $add 'TIPP' ('WLAN-Treiber ist von {0} - neuere Treiber beheben oft Abbrüche (Seite Treiber oder Hersteller).' -f $dd.ToString('MM/yyyy')) }
    # Energiesparen
    $o.Add(''); $o.Add('== Energiesparen ==')
    $pw = Get-WlanPowerIdx
    $o.Add(('  Energieplan WLAN: Netzbetrieb {0}, Akku {1}' -f (Get-WlanPowerText $pw.AC), (Get-WlanPowerText $pw.DC)))
    if ($pw.AC -gt 0) { & $add 'TIPP' 'Im Netzbetrieb spart der WLAN-Adapter Energie - kostet Tempo und erzeugt Aussetzer.' }
    $dp = Get-WlanDevPower $a
    if ($dp) { $o.Add(('  "Computer kann das Gerät ausschalten": {0}' -f $(if ($dp.Enable) { 'an' } else { 'aus' }))); if ($dp.Enable) { & $add 'TIPP' 'Windows darf den WLAN-Adapter abschalten - häufige Ursache für "WLAN weg nach Standby".' } }
    # Adapter-Einstellungen
    $plan = @(Get-WlanAdvPlan $a $mesh ([bool]($caps.Ghz6 -and @($own | Where-Object { $_.BandKey -eq '6' }).Count)))
    $o.Add(''); $o.Add('== Adapter-Einstellungen ==')
    if (-not $plan.Count) { $o.Add('  (keine bekannten Einstellungen beim Treiber gefunden)') }
    foreach ($p in $plan) { $o.Add(('  {0}: {1}{2}' -f $p.Name, $p.Current, $(if ($p.Change) { '   -> empfohlen: ' + $p.Target } else { '   (passt)' }))) }
    $chg = @($plan | Where-Object { $_.Change }).Count
    if ($chg) { & $add 'TIPP' ('{0} Adapter-Einstellung(en) sind nicht optimal (siehe oben).' -f $chg) }
    # Hotspots
    $hs = $null; try { $hs = (Get-ItemProperty -LiteralPath 'HKLM:\SOFTWARE\Microsoft\PolicyManager\default\WiFi\AllowAutoConnectToWiFiSenseHotspots' -ErrorAction Stop).value } catch { }
    if ($hs -ne 0) { & $add 'INFO' 'Windows darf sich automatisch mit vorgeschlagenen offenen Hotspots verbinden - "Optimieren" schaltet das aus.' }
    # Profile
    $prof = @(& netsh.exe wlan show profiles 2>$null | ForEach-Object { if ([string]$_ -match '(?:Profil für alle Benutzer|All User Profile|Benutzerprofil|Profil f\S*r alle Benutzer)\s*:\s*(.+)$') { $Matches[1].Trim() } })
    $o.Add(''); $o.Add(('== Gespeicherte WLANs: {0} ==' -f $prof.Count)); if ($prof.Count) { $o.Add('  ' + (($prof | Select-Object -First 25) -join ', ')) }
    if ($prof.Count -gt 15) { & $add 'INFO' 'Viele gespeicherte WLANs - alte Netze vergessen beschleunigt die Suche (Windows-Einstellungen > WLAN > Bekannte Netzwerke).' }
    $o.Insert(0, ''); 
    $sorted = @($tips | Sort-Object { switch -Regex ($_) { '^\[PROBLEM' { 0 } '^\[TIPP' { 1 } '^\[INFO' { 2 } default { 3 } } })
    for ($k = $sorted.Count - 1; $k -ge 0; $k--) { $o.Insert(0, '  ' + $sorted[$k]) }
    $o.Insert(0, '== Bewertung und Empfehlungen ==')
    $o.Add(''); $o.Add('"WLAN optimieren" stellt Energiesparen und Adapter-Einstellungen auf die Empfehlung (mit Sicherung, "Rückgängig" jederzeit). Kanal und Funkstandard stellt man im Router ein.')
    return [pscustomobject]@{ Text = ($o -join "`r`n"); NeedLocation = $needLoc }
}
function Invoke-WlanOptimize([string]$DataDir, [bool]$Battery) {
    $o = [System.Collections.Generic.List[string]]::new()
    $a = Get-WlanAdapter; if (-not $a) { return 'Kein WLAN-Adapter gefunden.' }
    $undoFile = Join-Path $DataDir 'wlan-rueckgaengig.json'
    $undo = [ordered]@{ Adapter = $a.Name; Created = (Get-Date).ToString('s'); Power = $null; DevPower = $null; Adv = @(); Hotspot = $null }
    if (Test-Path -LiteralPath $undoFile) { try { $old = Get-Content -LiteralPath $undoFile -Raw -Encoding UTF8 | ConvertFrom-Json; $o.Add('Hinweis: Es gibt schon eine Sicherung vom ' + $old.Created + ' - sie bleibt erhalten (Rückgängig stellt den Stand vor der ersten Optimierung her).'); $undo = $null } catch { } }
    # 1. Energieplan
    $pw = Get-WlanPowerIdx
    if ($undo) { $undo.Power = @{ AC = $pw.AC; DC = $pw.DC } }
    $null = & powercfg.exe /setacvalueindex SCHEME_CURRENT 19cbb8fa-5279-450e-9fac-8a3d5fedd0c1 12bbebe6-58d6-4636-95bb-3217ef867c1a 0 2>&1
    $dcT = if ($Battery) { 0 } else { [math]::Min([math]::Max($pw.DC, 0), 1) }
    $null = & powercfg.exe /setdcvalueindex SCHEME_CURRENT 19cbb8fa-5279-450e-9fac-8a3d5fedd0c1 12bbebe6-58d6-4636-95bb-3217ef867c1a $dcT 2>&1
    $null = & powercfg.exe /setactive SCHEME_CURRENT 2>&1
    $o.Add(('Energieplan WLAN: Netzbetrieb Höchstleistung, Akku {0}' -f (Get-WlanPowerText $dcT)))
    # 2. Geraet nicht abschalten
    $dp = Get-WlanDevPower $a
    if ($dp) {
        if ($undo) { $undo.DevPower = [bool]$dp.Enable }
        if ($dp.Enable) { try { Set-CimInstance -InputObject $dp -Property @{ Enable = $false } -ErrorAction Stop; $o.Add('"Computer kann das Gerät ausschalten": aus') } catch { $o.Add('"Computer kann das Gerät ausschalten" ließ sich nicht ändern: ' + $_.Exception.Message) } }
    }
    # 3. Adapter-Einstellungen
    $caps = Get-WlanDriverCaps; $i = Get-WlanIfInfo
    $nets = ConvertFrom-NtWlanText @(& netsh.exe wlan show networks mode=bssid 2>&1 | ForEach-Object { [string]$_ })
    $own = @($nets | Where-Object { $i.Ssid -and $_.Ssid -eq $i.Ssid })
    $mesh = (@($own | ForEach-Object { $_.Bssid } | Select-Object -Unique).Count -gt 2)
    $plan = @(Get-WlanAdvPlan $a $mesh ([bool]($caps.Ghz6 -and @($own | Where-Object { $_.BandKey -eq '6' }).Count)))
    $adv = [System.Collections.Generic.List[object]]::new(); $n = 0
    foreach ($p in @($plan | Where-Object { $_.Change })) {
        try {
            Set-NetAdapterAdvancedProperty -Name $a.Name -RegistryKeyword $p.Keyword -DisplayValue $p.Target -NoRestart -ErrorAction Stop
            $adv.Add([pscustomobject]@{ Keyword = $p.Keyword; Value = @($p.CurrentReg); Name = $p.Name; Display = $p.Current }); $n++
            $o.Add(('{0}: {1} -> {2}' -f $p.Name, $p.Current, $p.Target))
        } catch { $o.Add(('{0}: nicht geändert ({1})' -f $p.Name, ($_.Exception.Message -replace '\s+', ' '))) }
    }
    if ($undo) { $undo.Adv = $adv.ToArray() }
    # 4. Automatisch mit vorgeschlagenen Hotspots verbinden aus
    $hk = 'HKLM:\SOFTWARE\Microsoft\PolicyManager\default\WiFi\AllowAutoConnectToWiFiSenseHotspots'
    try {
        if (Test-Path -LiteralPath $hk) {
            $cur = (Get-ItemProperty -LiteralPath $hk -ErrorAction Stop).value
            if ($undo) { $undo.Hotspot = $cur }
            if ($cur -ne 0) { Set-ItemProperty -LiteralPath $hk -Name value -Value 0 -Type DWord -ErrorAction Stop; $o.Add('Automatisch mit vorgeschlagenen Hotspots verbinden: aus') }
        }
    } catch { }
    if ($undo) { try { $undo | ConvertTo-Json -Depth 5 | Set-Content -LiteralPath $undoFile -Encoding UTF8 } catch { $o.Add('Sicherung konnte nicht gespeichert werden: ' + $_.Exception.Message) } }
    if ($n) { $o.Add('WLAN-Adapter wird neu gestartet (Verbindung ist ca. 10 Sekunden weg) ...'); try { Restart-NetAdapter -Name $a.Name -Confirm:$false -ErrorAction Stop } catch { $o.Add('Neustart des Adapters fehlgeschlagen - bitte einmal WLAN aus/an.') } }
    if (-not $n) { $o.Add('Adapter-Einstellungen: nichts zu ändern.') }
    return ("== WLAN optimieren ==`r`n" + ($o -join "`r`n") + "`r`n`r`nDanach zum Vergleich erneut `"Analysieren`" oder `"Stabilität testen`".")
}
function Undo-WlanOptimize([string]$DataDir) {
    $f = Join-Path $DataDir 'wlan-rueckgaengig.json'
    if (-not (Test-Path -LiteralPath $f)) { return 'Keine Sicherung vorhanden - es wurde noch nichts optimiert.' }
    $u = Get-Content -LiteralPath $f -Raw -Encoding UTF8 | ConvertFrom-Json
    $o = [System.Collections.Generic.List[string]]::new()
    if ($u.Power -and $u.Power.AC -ge 0) {
        $null = & powercfg.exe /setacvalueindex SCHEME_CURRENT 19cbb8fa-5279-450e-9fac-8a3d5fedd0c1 12bbebe6-58d6-4636-95bb-3217ef867c1a ([int]$u.Power.AC) 2>&1
        if ($u.Power.DC -ge 0) { $null = & powercfg.exe /setdcvalueindex SCHEME_CURRENT 19cbb8fa-5279-450e-9fac-8a3d5fedd0c1 12bbebe6-58d6-4636-95bb-3217ef867c1a ([int]$u.Power.DC) 2>&1 }
        $null = & powercfg.exe /setactive SCHEME_CURRENT 2>&1; $o.Add('Energieplan WLAN zurückgesetzt')
    }
    $a = @(Get-NetAdapter -Name $u.Adapter -ErrorAction SilentlyContinue) | Select-Object -First 1
    if ($a) {
        if ($null -ne $u.DevPower) { $dp = Get-WlanDevPower $a; if ($dp) { try { Set-CimInstance -InputObject $dp -Property @{ Enable = [bool]$u.DevPower } -ErrorAction Stop; $o.Add('"Computer kann das Gerät ausschalten" zurückgesetzt') } catch { } } }
        $n = 0
        foreach ($p in @($u.Adv)) { if (-not $p) { continue }; try { Set-NetAdapterAdvancedProperty -Name $a.Name -RegistryKeyword $p.Keyword -RegistryValue @($p.Value | ForEach-Object { [string]$_ }) -NoRestart -ErrorAction Stop; $o.Add(('{0}: wieder {1}' -f $p.Name, $p.Display)); $n++ } catch { $o.Add(('{0}: nicht zurückgesetzt' -f $p.Name)) } }
        if ($n) { try { Restart-NetAdapter -Name $a.Name -Confirm:$false -ErrorAction Stop } catch { } }
    }
    if ($null -ne $u.Hotspot) { try { Set-ItemProperty -LiteralPath 'HKLM:\SOFTWARE\Microsoft\PolicyManager\default\WiFi\AllowAutoConnectToWiFiSenseHotspots' -Name value -Value ([int]$u.Hotspot) -Type DWord -ErrorAction Stop } catch { } }
    Remove-Item -LiteralPath $f -Force -ErrorAction SilentlyContinue
    return ("== Rückgängig ==`r`n" + ($o -join "`r`n"))
}
function Test-WlanStability([int]$Sec = 60) {
    $a = Get-WlanAdapter; if (-not $a) { return 'Kein WLAN-Adapter gefunden.' }
    $gw = ''; try { $gw = [string](@(Get-NetIPConfiguration -InterfaceIndex $a.ifIndex -ErrorAction Stop).IPv4DefaultGateway | Select-Object -First 1).NextHop } catch { }
    $ping = New-Object System.Net.NetworkInformation.Ping
    $sig = [System.Collections.Generic.List[int]]::new(); $rx = [System.Collections.Generic.List[double]]::new(); $gwMs = [System.Collections.Generic.List[double]]::new(); $netMs = [System.Collections.Generic.List[double]]::new()
    $lostGw = 0; $lostNet = 0; $roams = 0; $drops = 0; $last = ''; $n = 0
    $end = (Get-Date).AddSeconds($Sec)
    while ((Get-Date) -lt $end) {
        $n++; $i = Get-WlanIfInfo
        if ($i.Bssid) { $sig.Add($i.Signal); $rx.Add($i.Rx); if ($last -and $i.Bssid -ne $last) { $roams++ }; $last = $i.Bssid } else { $drops++ }
        if ($gw) { try { $r = $ping.Send($gw, 800); if ($r.Status -eq 'Success') { $gwMs.Add($r.RoundtripTime) } else { $lostGw++ } } catch { $lostGw++ } }
        try { $r = $ping.Send('1.1.1.1', 800); if ($r.Status -eq 'Success') { $netMs.Add($r.RoundtripTime) } else { $lostNet++ } } catch { $lostNet++ }
        Start-Sleep -Milliseconds 400
    }
    $st = { param($l) if (-not $l.Count) { return 'keine Werte' }; $m = $l | Measure-Object -Average -Minimum -Maximum; '{0:N0} / {1:N0} / {2:N0}' -f $m.Minimum, $m.Average, $m.Maximum }
    $jit = { param($l) if ($l.Count -lt 2) { return 0 }; $d = for ($k = 1; $k -lt $l.Count; $k++) { [math]::Abs($l[$k] - $l[$k - 1]) }; [math]::Round(($d | Measure-Object -Average).Average, 1) }
    $o = [System.Collections.Generic.List[string]]::new()
    $o.Add(('== Stabilitätstest ({0} Sekunden, {1} Messungen) ==' -f $Sec, $n))
    $o.Add(('Signal % (min / Schnitt / max): {0}' -f (& $st $sig)))
    $o.Add(('Verbindungstempo Mbit/s (min / Schnitt / max): {0}' -f (& $st $rx)))
    if ($gw) { $o.Add(('Router {0}: Ping ms (min / Schnitt / max) {1}, Schwankung {2} ms, verloren {3} von {4}' -f $gw, (& $st $gwMs), (& $jit $gwMs), $lostGw, $n)) }
    $o.Add(('Internet (1.1.1.1): Ping ms (min / Schnitt / max) {0}, Schwankung {1} ms, verloren {2} von {3}' -f (& $st $netMs), (& $jit $netMs), $lostNet, $n))
    $o.Add(('Senderwechsel (Roaming): {0}   Verbindung weg: {1}x' -f $roams, $drops))
    $o.Add('')
    $bad = $false
    if ($drops) { $o.Add('[PROBLEM] Die WLAN-Verbindung ist während des Tests abgerissen - Energiesparen/Treiber prüfen ("WLAN optimieren", Treiber aktualisieren).'); $bad = $true }
    if ($gw -and $lostGw -gt [math]::Max(1, $n * 0.03)) { $o.Add('[PROBLEM] Pakete zum Router gehen verloren - Funkstrecke gestört (Abstand, Kanal, Störquellen wie Mikrowelle/Babyfon).'); $bad = $true }
    elseif ($lostNet -gt [math]::Max(1, $n * 0.03)) { $o.Add('[PROBLEM] Zum Router ist alles gut, aber ins Internet gehen Pakete verloren - Ursache liegt beim Router/Anbieter, nicht am WLAN.'); $bad = $true }
    if ($gwMs.Count -gt 1 -and (& $jit $gwMs) -ge 15) { $o.Add('[TIPP] Ping zum Router schwankt stark - typisch für Energiesparen oder volles Band.'); $bad = $true }
    if ($roams -gt 2) { $o.Add('[INFO] Häufige Senderwechsel - bei Mesh normal beim Bewegen, im Stillstand ein Zeichen für gleich starke Sender (Mesh-Positionen prüfen).') }
    if (-not $bad) { $o.Add('[OK] Verbindung stabil.') }
    return ($o -join "`r`n")
}
function New-WlanWinReport {
    $null = Invoke-NdCmd (Get-SysExe 'netsh.exe') 'wlan show wlanreport' 120
    $f = Join-Path $env:ProgramData 'Microsoft\Windows\WlanReport\wlan-report-latest.html'
    if (Test-Path -LiteralPath $f) { return $f }; return ''
}
function Reset-WlanConnection {
    $a = Get-WlanAdapter; if (-not $a) { return 'Kein WLAN-Adapter gefunden.' }
    $i = Get-WlanIfInfo; $prof = $i.Profile
    try { Restart-NetAdapter -Name $a.Name -Confirm:$false -ErrorAction Stop } catch { return 'Adapter-Neustart fehlgeschlagen: ' + $_.Exception.Message }
    if ($prof) {
        for ($k = 0; $k -lt 15; $k++) { Start-Sleep -Seconds 1; if ((Get-WlanIfInfo).Bssid) { break } }
        if (-not (Get-WlanIfInfo).Bssid) { $null = & netsh.exe wlan connect name="$prof" 2>&1; Start-Sleep -Seconds 5 }
    }
    $j = Get-WlanIfInfo
    return ('WLAN-Adapter neu gestartet. ' + $(if ($j.Bssid) { 'Wieder verbunden mit {0} ({1} %, {2}).' -f $j.Ssid, $j.Signal, $j.Band } else { 'Noch nicht wieder verbunden - ggf. im Netzwerksymbol verbinden.' }))
}
# ---- Netzwerk dokumentieren: Erfassung (Invoke-Bg), Bewertung und PDF-Bericht
$NdocPorts = @(21, 22, 23, 25, 53, 80, 81, 88, 110, 135, 139, 143, 389, 443, 445, 515, 548, 554, 631, 873, 1433, 1880, 1883, 2001, 2010, 2049, 2375, 3000, 3306, 3389, 5000, 5001, 5432, 4433, 5900, 6053, 6379, 6638, 7000, 8000, 8043, 8008, 8009, 8080, 8081, 8082, 8123, 8181, 8291, 8443, 8883, 9000, 9100, 9200, 9443, 10000, 10443, 27017, 32400)
$NdocPortNames = @{ 21 = 'FTP'; 22 = 'SSH'; 23 = 'Telnet'; 25 = 'SMTP'; 53 = 'DNS'; 80 = 'Web (http)'; 81 = 'Web (http)'; 88 = 'Kerberos'; 110 = 'POP3'; 135 = 'Windows RPC'; 139 = 'NetBIOS'; 143 = 'IMAP'; 389 = 'LDAP'; 443 = 'Web (https)'; 445 = 'Dateifreigabe (SMB)'; 515 = 'Drucker (LPD)'; 548 = 'Apple-Freigabe (AFP)'; 554 = 'Kamera-Stream (RTSP)'; 631 = 'Drucker (IPP)'; 873 = 'rsync'; 1433 = 'SQL Server'; 1880 = 'Node-RED'; 1883 = 'MQTT'; 2001 = 'Homematic (BidCos)'; 2010 = 'Homematic IP'; 2049 = 'NFS'; 2375 = 'Docker-API (ungeschützt)'; 3000 = 'Web-App'; 3306 = 'MySQL/MariaDB'; 3389 = 'Remotedesktop'; 5000 = 'Synology/Web'; 5001 = 'Synology (https)'; 5432 = 'PostgreSQL'; 5900 = 'VNC-Fernsteuerung'; 6053 = 'ESPHome-API'; 6379 = 'Redis'; 6638 = 'Zigbee-Koordinator'; 7000 = 'AirPlay'; 8000 = 'Web-App'; 8008 = 'Chromecast'; 8009 = 'Chromecast'; 8080 = 'Web (alternativ)'; 8081 = 'Web (alternativ)/ioBroker'; 8082 = 'ioBroker'; 8123 = 'Home Assistant'; 8181 = 'Homematic (ReGa)'; 8291 = 'MikroTik Winbox'; 8043 = 'Omada-Controller'; 4433 = 'Firewall-Verwaltung'; 10443 = 'Firewall-Verwaltung'; 8443 = 'Web (https alt.)'; 8883 = 'MQTT (TLS)'; 9000 = 'Web-App/Portainer'; 9100 = 'Drucker (RAW)'; 9200 = 'Elasticsearch'; 9443 = 'Portainer (https)'; 10000 = 'Webmin'; 27017 = 'MongoDB'; 32400 = 'Plex' }
function Get-NdocPcInfo {
    $o = [ordered]@{}
    $cs = Get-CimInstance Win32_ComputerSystem -ErrorAction SilentlyContinue; $os = Get-CimInstance Win32_OperatingSystem -ErrorAction SilentlyContinue
    $o.Computer = $env:COMPUTERNAME; $o.User = $env:USERNAME
    $o.Domain = $(if ($cs.PartOfDomain) { 'Domäne ' + $cs.Domain } else { 'Arbeitsgruppe ' + $cs.Workgroup })
    $o.Os = ('{0} (Build {1})' -f $os.Caption, $os.BuildNumber); $o.Model = ('{0} {1}' -f $cs.Manufacturer, $cs.Model).Trim()
    $o.Adapters = @(Get-NetAdapter -ErrorAction SilentlyContinue | Sort-Object Status, Name | ForEach-Object {
        $a = $_; $ix = $a.ifIndex
        $v4 = @(Get-NetIPAddress -InterfaceIndex $ix -AddressFamily IPv4 -ErrorAction SilentlyContinue | ForEach-Object { '{0}/{1}' -f $_.IPAddress, $_.PrefixLength })
        $v6 = @(Get-NetIPAddress -InterfaceIndex $ix -AddressFamily IPv6 -ErrorAction SilentlyContinue | Where-Object { $_.IPAddress -notlike 'fe80*' } | ForEach-Object { $_.IPAddress })
        $gw = @(Get-NetRoute -InterfaceIndex $ix -DestinationPrefix '0.0.0.0/0' -ErrorAction SilentlyContinue | ForEach-Object { $_.NextHop })
        $dns = @(Get-DnsClientServerAddress -InterfaceIndex $ix -AddressFamily IPv4 -ErrorAction SilentlyContinue | ForEach-Object { $_.ServerAddresses })
        $dh = ''; try { $dh = [string](Get-NetIPInterface -InterfaceIndex $ix -AddressFamily IPv4 -ErrorAction Stop).Dhcp } catch { }
        [pscustomobject]@{ Name = [string]$a.Name; Desc = [string]$a.InterfaceDescription; Status = [string]$a.Status; Mac = (Format-NtMac ([string]$a.MacAddress)); Speed = [string]$a.LinkSpeed; Ipv4 = ($v4 -join ', '); Ipv6 = ($v6 -join ', '); Gateway = (@($gw | Select-Object -Unique) -join ', '); Dns = ($dns -join ', '); Dhcp = $(if ($dh -eq 'Enabled') { 'DHCP' } elseif ($dh) { 'fest' } else { '' }); Virtual = (-not $a.HardwareInterface) }
    })
    $o.Profiles = @(Get-NetConnectionProfile -ErrorAction SilentlyContinue | ForEach-Object { [pscustomobject]@{ Name = [string]$_.Name; Alias = [string]$_.InterfaceAlias; Index = [int]$_.InterfaceIndex; Category = [string]$_.NetworkCategory; V4 = [string]$_.IPv4Connectivity } })
    $o.Firewall = @(Get-NetFirewallProfile -ErrorAction SilentlyContinue | ForEach-Object { [pscustomobject]@{ Name = [string]$_.Name; Enabled = [bool]($_.Enabled -eq $true -or [string]$_.Enabled -eq 'True'); In = [string]$_.DefaultInboundAction } })
    $smb = $null; try { $smb = Get-SmbServerConfiguration -ErrorAction Stop } catch { }
    $o.Smb1 = $(if ($smb) { [bool]$smb.EnableSMB1Protocol } else { $null })
    $o.SmbSign = $(if ($smb) { [bool]$smb.RequireSecuritySignature } else { $null })
    $o.Shares = @(Get-SmbShare -ErrorAction SilentlyContinue | Where-Object { $_.Name -notmatch '^(ADMIN\$|IPC\$|print\$|[A-Z]\$)$' } | ForEach-Object {
        $s = $_; $acc = @(); try { $acc = @(Get-SmbShareAccess -Name $s.Name -ErrorAction Stop | ForEach-Object { '{0}: {1}' -f $_.AccountName, $_.AccessRight }) } catch { }
        [pscustomobject]@{ Name = [string]$s.Name; Path = [string]$s.Path; Access = ($acc -join '; '); Everyone = [bool]($acc -match '(?i)(Jeder|Everyone).*(Full|Change|Voll|Ändern)') } })
    $rdp = $null; try { $rdp = ([int](Get-ItemProperty 'HKLM:\SYSTEM\CurrentControlSet\Control\Terminal Server' -ErrorAction Stop).fDenyTSConnections -eq 0) } catch { }
    $nla = $null; try { $nla = ([int](Get-ItemProperty 'HKLM:\SYSTEM\CurrentControlSet\Control\Terminal Server\WinStations\RDP-Tcp' -ErrorAction Stop).UserAuthentication -eq 1) } catch { }
    $o.Rdp = $rdp; $o.RdpNla = $nla
    $guest = $null; try { $guest = [bool](Get-LocalUser -ErrorAction Stop | Where-Object { $_.SID -like '*-501' }).Enabled } catch { }
    $o.Guest = $guest
    $procs = @{}; foreach ($p in @(Get-Process -ErrorAction SilentlyContinue)) { $procs[[int]$p.Id] = $p.ProcessName }
    $o.Listen = @(Get-NetTCPConnection -State Listen -ErrorAction SilentlyContinue | Where-Object { $_.LocalAddress -in '0.0.0.0', '::' } | ForEach-Object { [pscustomobject]@{ Port = [int]$_.LocalPort; Proc = $(if ($procs.ContainsKey([int]$_.OwningProcess)) { $procs[[int]$_.OwningProcess] } else { 'PID ' + $_.OwningProcess }) } } | Sort-Object Port, Proc -Unique | Where-Object { $_.Port -lt 49152 })
    $px = ''; try { $px = ((& netsh.exe winhttp show proxy 2>$null) -join ' ') -replace '\s+', ' ' } catch { }
    $ie = $null; try { $ie = Get-ItemProperty 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Internet Settings' -ErrorAction Stop } catch { }
    $o.Proxy = $(if ($ie -and $ie.ProxyEnable -eq 1) { 'Benutzer-Proxy: ' + $ie.ProxyServer } elseif ($ie -and $ie.AutoConfigURL) { 'Proxy-Skript: ' + $ie.AutoConfigURL } elseif ($px -match '(?i)direct|direkt') { 'kein Proxy' } else { $px })
    $o.Hosts = @(Get-Content -LiteralPath (Join-Path $env:windir 'System32\drivers\etc\hosts') -ErrorAction SilentlyContinue | Where-Object { $_ -match '^\s*[0-9a-fA-F:\.]+\s+\S' -and $_ -notmatch '^\s*#' } | ForEach-Object { $_.Trim() })
    $o.Drives = @(Get-CimInstance Win32_MappedLogicalDisk -ErrorAction SilentlyContinue | ForEach-Object { '{0} -> {1}' -f $_.DeviceID, $_.ProviderName })
    $o.Printers = @(Get-Printer -ErrorAction SilentlyContinue | Where-Object { $_.Type -eq 'Connection' -or $_.PortName -match '^(IP_|WSD|\d+\.\d+\.\d+\.\d+|http)' } | ForEach-Object { '{0} ({1})' -f $_.Name, $_.PortName })
    $o.Llmnr = $null; try { $o.Llmnr = -not ([int](Get-ItemProperty 'HKLM:\SOFTWARE\Policies\Microsoft\Windows NT\DNSClient' -ErrorAction Stop).EnableMulticast -eq 0) } catch { $o.Llmnr = $true }
    return [pscustomobject]$o
}
function Get-NdocWebTitles($Devices) {
    $res = @{}
    foreach ($d in @($Devices)) {
        if (-not $d -or $d.Via -eq 'Dieser PC') { continue }
        $pp = @($d.Ports)
        $u = if ($pp -contains 443) { 'https://{0}/' -f $d.Ip } elseif ($pp -contains 80) { 'http://{0}/' -f $d.Ip } elseif ($pp -contains 8080) { 'http://{0}:8080/' -f $d.Ip } elseif ($pp -contains 5000) { 'http://{0}:5000/' -f $d.Ip } elseif ($pp -contains 8123) { 'http://{0}:8123/' -f $d.Ip } else { '' }
        if (-not $u) { continue }
        try {
            $w = Invoke-WebRequest -Uri $u -UseBasicParsing -TimeoutSec 3 -MaximumRedirection 2 -ErrorAction Stop
            $t = ''; if ($w.Content -match '(?is)<title[^>]*>\s*([^<]{1,100}?)\s*</title>') { $t = [Net.WebUtility]::HtmlDecode($Matches[1]).Trim() }
            $res[[string]$d.Ip] = [pscustomobject]@{ Url = $u; Title = $t; Server = [string]$w.Headers['Server'] }
        } catch {
            $sv = ''; try { $sv = [string]$_.Exception.Response.Headers['Server'] } catch { }
            $res[[string]$d.Ip] = [pscustomobject]@{ Url = $u; Title = ''; Server = $sv }
        }
    }
    return $res
}
function Get-NdocWlanInfo {
    $a = Get-WlanAdapter; if (-not $a) { return $null }
    $i = Get-WlanIfInfo; $caps = Get-WlanDriverCaps
    $raw = @(& netsh.exe wlan show networks mode=bssid 2>&1 | ForEach-Object { [string]$_ }); $t = $raw -join "`n"
    $nets = ConvertFrom-NtWlanText $raw
    $prof = @(& netsh.exe wlan show profiles 2>$null | ForEach-Object { if ([string]$_ -match '(?:Profil f\S*r alle Benutzer|All User Profile|Benutzerprofil)\s*:\s*(.+)$') { $Matches[1].Trim() } })
    $pinfo = foreach ($p in @($prof | Select-Object -First 60)) {
        $x = (& netsh.exe wlan show profile name="$p" 2>$null) -join "`n"; $au = ''; $mo = ''
        if ($x -match '(?m)^\s*(Authentifizierung|Authentication)\s*:\s*(.+)$') { $au = $Matches[2].Trim() }
        if ($x -match '(?m)^\s*(Verbindungsmodus|Connection mode)\s*:\s*(.+)$') { $mo = $Matches[2].Trim() }
        [pscustomobject]@{ Name = $p; Auth = $au; Mode = $mo }
    }
    [pscustomobject]@{ Adapter = [string]$a.InterfaceDescription; Driver = [string]$a.DriverVersionString; Conn = $i; Caps = $caps; Nets = @($nets); NeedLocation = (($t -match '(?i)Standort|location') -and -not ($t -match '(?m)^\s*BSSID')); Profiles = @($pinfo) }
}
function Invoke-NdocCollect([bool]$Ports, [bool]$Web, [bool]$Smart, [int[]]$PortList, [string]$TlsCode, $Sync, [hashtable]$Opt = @{}) {
    $say = { param($p, $t) if ($Sync) { $Sync.P = $p; $Sync.T = $t } }
    & $say 3 'Dieser PC: Adapter, Firewall, Freigaben ...'
    $pc = Get-NdocPcInfo
    $net = Get-NtActiveNet
    if (-not $net -or -not $net.Ip) { throw 'Kein aktiver Netzwerkadapter mit IPv4-Adresse gefunden.' }
    & $say 12 $(if ($Ports) { 'Suche Geräte und prüfe ihre Dienste (1-3 Minuten) ...' } else { 'Suche Geräte im Netz ...' })
    $dev = @(Invoke-NtSweep $net $Ports $PortList $null)
    $web = @{}; if ($Web) { & $say 60 ('Lese Weboberflächen von {0} Geräten ...' -f @($dev | Where-Object { @($_.Ports).Count }).Count); $web = Get-NdocWebTitles $dev }
    $sh = $null; if ($Smart) { & $say 64 'Smart Home und KNX erkennen (KNXnet/IP, mDNS, UPnP, Shelly, MQTT ...) ...'; try { $sh = Get-NdocSmartHome $net $dev $web } catch { } }
    & $say 68 'Netzwerk-Infrastruktur erkennen (SNMP, Weg ins Internet) ...'
    $inf = $null; try { $inf = Get-NdocInfra $dev $net } catch { }
    if ($sh) { foreach ($k in @($sh.Knx)) { if (-not @($dev | Where-Object { $_.Ip -eq $k.Ip }).Count) { $dev += [pscustomobject]@{ Ip = $k.Ip; Rtt = -1; Via = 'KNX'; Mac = $k.Mac; Host = ''; Ports = @() } } } }
    & $say 72 'Router prüfen (Firmware, UPnP, DHCP, IPv6) ...'
    $rt = $null; try { $rt = Get-NtRouterData $TlsCode $null } catch { }
    & $say 86 'WLAN-Umgebung lesen ...'
    $wl = $null; try { $wl = Get-NdocWlanInfo } catch { }
    & $say 94 'Öffentliche IP-Adresse ...'
    $pub = ''; try { $pub = [string](Invoke-WebRequest -Uri 'https://api.ipify.org' -UseBasicParsing -TimeoutSec 5 -ErrorAction Stop).Content } catch { }
    $pub = $pub.Trim()
    $fb = $null; $fbErr = ''
    if ($Opt.FbPass -and $net.Gateway) { & $say 96 'FRITZ!Box auslesen (Geräteliste, Freigaben, WLAN, Fernzugang) ...'; try { $fb = Get-FbData $net.Gateway ([string]$Opt.FbUser) $Opt.FbPass } catch { $fbErr = $_.Exception.Message } }
    $sho = $null; if ($Opt.Ext -and $pub) { & $say 97 'Erreichbarkeit von außen (Shodan InternetDB) ...'; try { $sho = Get-NdocShodan $pub } catch { } }
    $ha = $null; $haErr = ''
    if ($Opt.HaUrl -and $Opt.HaToken) { & $say 98 'Home Assistant abfragen ...'; try { $ha = Get-NdocHomeAssistant ([string]$Opt.HaUrl) ([string]$Opt.HaToken) } catch { $haErr = $_.Exception.Message } }
    & $say 100 'Fertig.'
    [pscustomobject]@{ Time = (Get-Date); Net = $net; Devices = $dev; Web = $web; Router = $rt; Wlan = $wl; Pc = $pc; PublicIp = $pub; Smart = $sh; Infra = $inf; Fritz = $fb; FritzErr = $fbErr; Shodan = $sho; Ha = $ha; HaErr = $haErr }
}
# ---- Smart Home und Gebäudeautomation erkennen (KNXnet/IP, mDNS, SSDP, Shelly, Tasmota, Hue, Node-RED, MQTT, Homematic)
function Read-NdocDnsName([byte[]]$B, [int]$Off) {
    $parts = [System.Collections.Generic.List[string]]::new(); $o = $Off; $end = -1; $guard = 0
    while ($o -lt $B.Length -and $guard -lt 64) {
        $guard++; $l = $B[$o]
        if ($l -eq 0) { $o++; break }
        if (($l -band 0xC0) -eq 0xC0) { if ($end -lt 0) { $end = $o + 2 }; $o = (($l -band 0x3F) * 256) + $B[$o + 1]; continue }
        $parts.Add([Text.Encoding]::UTF8.GetString($B, $o + 1, [math]::Min($l, $B.Length - $o - 1))); $o += $l + 1
    }
    if ($end -lt 0) { $end = $o }
    return [pscustomobject]@{ Name = ($parts -join '.'); Next = $end }
}
function ConvertFrom-NdocMdns([byte[]]$B) {
    $recs = [System.Collections.Generic.List[object]]::new()
    if ($B.Length -lt 12) { return $recs }
    $qd = $B[4] * 256 + $B[5]; $n = ($B[6] * 256 + $B[7]) + ($B[8] * 256 + $B[9]) + ($B[10] * 256 + $B[11]); $o = 12
    for ($i = 0; $i -lt $qd; $i++) { $r = Read-NdocDnsName $B $o; $o = $r.Next + 4 }
    for ($i = 0; $i -lt $n -and $o + 10 -le $B.Length; $i++) {
        $nm = Read-NdocDnsName $B $o; $o = $nm.Next
        $ty = $B[$o] * 256 + $B[$o + 1]; $len = $B[$o + 8] * 256 + $B[$o + 9]; $rd = $o + 10; $o = $rd + $len
        if ($o -gt $B.Length) { break }
        $val = $null
        switch ($ty) {
            12 { $val = (Read-NdocDnsName $B $rd).Name }
            33 { $val = [pscustomobject]@{ Port = $B[$rd + 4] * 256 + $B[$rd + 5]; Target = (Read-NdocDnsName $B ($rd + 6)).Name } }
            16 { $kv = @{}; $p = $rd; while ($p -lt $rd + $len) { $l = $B[$p]; if ($l -gt 0 -and $p + 1 + $l -le $B.Length) { $t = [Text.Encoding]::UTF8.GetString($B, $p + 1, $l); $k = ($t -split '=', 2); if ($k.Count -eq 2) { $kv[$k[0].ToLower()] = $k[1] } }; $p += $l + 1 }; $val = $kv }
            1 { if ($len -eq 4) { $val = '{0}.{1}.{2}.{3}' -f $B[$rd], $B[$rd + 1], $B[$rd + 2], $B[$rd + 3] } }
        }
        if ($null -ne $val) { $recs.Add([pscustomobject]@{ Name = $nm.Name; Type = $ty; Value = $val }) }
    }
    return $recs
}
function New-NdocUdp([string]$LocalIp) {
    $u = New-Object Net.Sockets.UdpClient (New-Object Net.IPEndPoint([Net.IPAddress]::Parse($LocalIp), 0))
    try { $u.Client.SetSocketOption([Net.Sockets.SocketOptionLevel]::IP, [Net.Sockets.SocketOptionName]::MulticastInterface, [Net.IPAddress]::Parse($LocalIp).GetAddressBytes()) } catch { }
    try { $u.Client.SetSocketOption([Net.Sockets.SocketOptionLevel]::IP, [Net.Sockets.SocketOptionName]::MulticastTimeToLive, 4) } catch { }
    $u.Client.ReceiveTimeout = 300
    return $u
}
function Invoke-NdocMdns([string]$LocalIp, [int]$Ms = 3000) {
    $types = @('_services._dns-sd._udp', '_hap._tcp', '_homekit._tcp', '_home-assistant._tcp', '_hue._tcp', '_shelly._tcp', '_esphomelib._tcp', '_matter._tcp', '_matterc._udp', '_meshcop._udp', '_googlecast._tcp', '_sonos._tcp', '_airplay._tcp', '_raop._tcp', '_spotify-connect._tcp', '_amzn-wplay._tcp', '_ipp._tcp', '_printer._tcp', '_pdl-datastream._tcp', '_scanner._tcp', '_smb._tcp', '_afpovertcp._tcp', '_workstation._tcp', '_device-info._tcp', '_mqtt._tcp', '_miio._udp', '_aqara._tcp', '_ewelink._tcp', '_wled._tcp', '_nanoleafapi._tcp', '_elg._tcp', '_ssh._tcp', '_http._tcp')
    $q = [System.Collections.Generic.List[byte]]::new(); $q.AddRange([byte[]](0, 0, 0, 0, 0, [byte]$types.Count, 0, 0, 0, 0, 0, 0))
    foreach ($t in $types) { foreach ($lab in (($t + '.local') -split '\.')) { $lb = [Text.Encoding]::ASCII.GetBytes($lab); $q.Add([byte]$lb.Length); $q.AddRange($lb) }; $q.AddRange([byte[]](0, 0, 12, 0x80, 1)) }
    $res = @{}
    $u = $null
    try {
        $u = New-NdocUdp $LocalIp; $pk = $q.ToArray()
        [void]$u.Send($pk, $pk.Length, '224.0.0.251', 5353)
        $end = (Get-Date).AddMilliseconds($Ms); $resent = $false
        while ((Get-Date) -lt $end) {
            if (-not $resent -and (Get-Date) -gt $end.AddMilliseconds(-$Ms / 2)) { try { [void]$u.Send($pk, $pk.Length, '224.0.0.251', 5353) } catch { }; $resent = $true }
            $ep = New-Object Net.IPEndPoint([Net.IPAddress]::Any, 0)
            try { $b = $u.Receive([ref]$ep) } catch { continue }
            $ip = [string]$ep.Address; if ($ip -eq $LocalIp) { continue }
            if (-not $res.ContainsKey($ip)) { $res[$ip] = [pscustomobject]@{ Ip = $ip; Services = [System.Collections.Generic.HashSet[string]]::new(); Names = [System.Collections.Generic.HashSet[string]]::new(); Txt = @{}; Host = '' } }
            $d = $res[$ip]
            foreach ($r in @(ConvertFrom-NdocMdns $b)) {
                if ($r.Type -eq 12 -and $r.Name -notlike '_services*') {
                    $svc = ($r.Name -replace '\.local$', ''); [void]$d.Services.Add($svc)
                    $inst = ([string]$r.Value -replace ([regex]::Escape('.' + $r.Name) + '$'), ''); if ($inst -and $inst -ne $r.Value) { [void]$d.Names.Add($inst) }
                } elseif ($r.Type -eq 16) { foreach ($k in $r.Value.Keys) { $d.Txt[$k] = $r.Value[$k] } }
                elseif ($r.Type -eq 33 -and $r.Value.Target) { $d.Host = ([string]$r.Value.Target -replace '\.local$', '') }
            }
        }
    } catch { } finally { if ($u) { $u.Close() } }
    return $res
}
function Invoke-NdocSsdp([string]$LocalIp, [int]$Ms = 3500) {
    $res = @{}; $u = $null
    try {
        $u = New-NdocUdp $LocalIp
        $req = [Text.Encoding]::ASCII.GetBytes("M-SEARCH * HTTP/1.1`r`nHOST: 239.255.255.250:1900`r`nMAN: `"ssdp:discover`"`r`nMX: 2`r`nST: ssdp:all`r`n`r`n")
        [void]$u.Send($req, $req.Length, '239.255.255.250', 1900)
        $end = (Get-Date).AddMilliseconds($Ms)
        while ((Get-Date) -lt $end) {
            $ep = New-Object Net.IPEndPoint([Net.IPAddress]::Any, 0)
            try { $t = [Text.Encoding]::UTF8.GetString($u.Receive([ref]$ep)) } catch { continue }
            $ip = [string]$ep.Address
            if (-not $res.ContainsKey($ip)) { $res[$ip] = [pscustomobject]@{ Ip = $ip; Server = ''; Types = [System.Collections.Generic.HashSet[string]]::new(); Location = ''; Friendly = ''; Maker = ''; Model = '' } }
            $d = $res[$ip]
            if ($t -match '(?im)^SERVER:\s*(.+)$') { $d.Server = $Matches[1].Trim() }
            if ($t -match '(?im)^ST:\s*(.+)$') { [void]$d.Types.Add($Matches[1].Trim()) }
            if (-not $d.Location -and $t -match '(?im)^LOCATION:\s*(\S+)') { $d.Location = $Matches[1].Trim() }
            if ($t -match '(?im)^hue-bridgeid:') { [void]$d.Types.Add('hue-bridge') }
        }
    } catch { } finally { if ($u) { $u.Close() } }
    foreach ($d in @($res.Values | Where-Object { $_.Location } | Select-Object -First 40)) {
        try {
            [xml]$x = (Invoke-WebRequest -Uri $d.Location -UseBasicParsing -TimeoutSec 2 -ErrorAction Stop).Content
            $dv = $x.root.device; $d.Friendly = [string]$dv.friendlyName; $d.Maker = [string]$dv.manufacturer; $d.Model = (('{0} {1}' -f $dv.modelName, $dv.modelNumber).Trim())
        } catch { }
    }
    return $res
}
function ConvertFrom-NdocKnxSearch([byte[]]$b, [string]$From) {
    if ($b.Length -lt 68 -or $b[0] -ne 0x06 -or $b[2] -ne 0x02 -or ($b[3] -ne 0x02 -and $b[3] -ne 0x0B)) { return $null }
    $ip = '{0}.{1}.{2}.{3}' -f $b[8], $b[9], $b[10], $b[11]; if ($ip -eq '0.0.0.0') { $ip = $From }
    $o = 14; $dl = $b[$o]
    $med = switch ($b[$o + 2]) { 0x02 { 'TP1 (Zweidraht)' } 0x04 { 'Powerline' } 0x10 { 'KNX RF (Funk)' } 0x20 { 'KNX IP' } default { 'unbekannt' } }
    $pa = '{0}.{1}.{2}' -f ($b[$o + 4] -shr 4), ($b[$o + 4] -band 15), $b[$o + 5]
    $mac = (($b[($o + 18)..($o + 23)] | ForEach-Object { '{0:X2}' -f $_ }) -join ':')
    $nm = ([Text.Encoding]::GetEncoding(28591).GetString($b, $o + 24, 30)).Trim([char]0, ' ')
    $fam = @{}; $p = $o + $dl
    while ($p + 2 -le $b.Length) {
        $l2 = $b[$p]; if ($l2 -lt 2) { break }
        if ($b[$p + 1] -eq 0x02) { for ($k = $p + 2; $k + 1 -lt $p + $l2; $k += 2) { $fam[[int]$b[$k]] = [int]$b[$k + 1] } }
        $p += $l2
    }
    [pscustomobject]@{ Ip = $ip; Name = $nm; Address = $pa; Medium = $med; Mac = $mac; Tunnel = $fam.ContainsKey(4); Routing = $fam.ContainsKey(5); Secure = $fam.ContainsKey(9); Mgmt = $fam.ContainsKey(3); Families = (($fam.Keys | Sort-Object | ForEach-Object { '0x{0:X2}v{1}' -f $_, $fam[$_] }) -join ' ') }
}
function Invoke-NdocKnx([string]$LocalIp, [int]$Ms = 3000) {
    $list = [System.Collections.Generic.List[object]]::new(); $u = $null; $seen = @{}
    try {
        $u = New-NdocUdp $LocalIp
        $port = [int]$u.Client.LocalEndPoint.Port; $ipb = [Net.IPAddress]::Parse($LocalIp).GetAddressBytes()
        $req = [byte[]](@(0x06, 0x10, 0x02, 0x01, 0x00, 0x0E, 0x08, 0x01) + @($ipb) + @((($port -shr 8) -band 255), ($port -band 255)))
        [void]$u.Send($req, $req.Length, '224.0.23.12', 3671)
        $end = (Get-Date).AddMilliseconds($Ms)
        while ((Get-Date) -lt $end) {
            $ep = New-Object Net.IPEndPoint([Net.IPAddress]::Any, 0)
            try { $b = $u.Receive([ref]$ep) } catch { continue }
            $k = ConvertFrom-NdocKnxSearch $b ([string]$ep.Address); if (-not $k) { continue }
            $key = $k.Ip + '|' + $k.Address; if ($seen.ContainsKey($key)) { continue }; $seen[$key] = 1
            $list.Add($k)
        }
    } catch { } finally { if ($u) { $u.Close() } }
    return $list.ToArray()
}
function Get-NdocHttp([string]$Url, [string]$Method = 'GET', [string]$Body = '') {
    try {
        $w = if ($Method -eq 'POST') { Invoke-WebRequest -Uri $Url -Method Post -Body $Body -ContentType 'text/xml' -UseBasicParsing -TimeoutSec 3 -ErrorAction Stop } else { Invoke-WebRequest -Uri $Url -UseBasicParsing -TimeoutSec 3 -MaximumRedirection 0 -ErrorAction Stop }
        $j = $null; try { $j = [string]$w.Content | ConvertFrom-Json -ErrorAction Stop } catch { }
        return [pscustomobject]@{ Code = [int]$w.StatusCode; Text = [string]$w.Content; Json = $j }
    } catch {
        $c = 0; try { $c = [int]$_.Exception.Response.StatusCode } catch { }
        return [pscustomobject]@{ Code = $c; Text = ''; Json = $null }
    }
}
function Test-NdocMqttAnon([string]$Ip, [int]$Port = 1883) {
    $c = New-Object Net.Sockets.TcpClient
    try {
        $t = $c.ConnectAsync($Ip, $Port); if (-not $t.Wait(1500) -or -not $c.Connected) { return $null }
        $s = $c.GetStream(); $s.ReadTimeout = 2500
        $cid = [Text.Encoding]::ASCII.GetBytes('pctools-pruefung')
        $vh = [byte[]](@(0, 4) + @([Text.Encoding]::ASCII.GetBytes('MQTT')) + @(4, 2, 0, 10))
        $pl = [byte[]](@(0, $cid.Length) + @($cid))
        $pk = [byte[]](@(0x10, ($vh.Length + $pl.Length)) + @($vh) + @($pl)); $s.Write($pk, 0, $pk.Length)
        $buf = New-Object byte[] 4; $n = 0; try { $n = $s.Read($buf, 0, 4) } catch { }
        try { $s.Write([byte[]](0xE0, 0), 0, 2) } catch { }
        if ($n -ge 4 -and $buf[0] -eq 0x20) { return [int]$buf[3] }
        return $null
    } catch { return $null } finally { $c.Close() }
}
function Get-NdocSmartHome($Net, $Devices, $Web) {
    $mdns = @{}; $ssdp = @{}; $knx = @()
    try { $mdns = Invoke-NdocMdns $Net.Ip } catch { }
    try { $ssdp = Invoke-NdocSsdp $Net.Ip } catch { }
    try { $knx = @(Invoke-NdocKnx $Net.Ip) } catch { }
    $items = [System.Collections.Generic.List[object]]::new()
    $add = { param($ip, $sys, $model, $fw, $auth, $risk, $detail) $items.Add([pscustomobject]@{ Ip = $ip; System = $sys; Model = $model; Firmware = $fw; Auth = $auth; Risk = $risk; Detail = $detail }) }
    foreach ($k in $knx) {
        $kf = (@($(if ($k.Tunnel) { 'Tunneling' }), $(if ($k.Routing) { 'Routing (Multicast)' }), $(if ($k.Mgmt) { 'Fernwartung' })) | Where-Object { $_ }) -join ', '
        $kd = '{0}; {1}{2}' -f $k.Medium, $kf, $(if ($k.Secure) { ', KNX IP Secure unterstützt' } else { '' })
        & $add $k.Ip 'KNX IP' ('{0} ({1})' -f $k.Name, $k.Address) '' $(if ($k.Secure) { 'KNX Secure' } else { 'ungesichert' }) $(if ($k.Secure) { 'Info' } else { 'Mittel' }) $kd
    }
    foreach ($d in @($Devices)) {
        if (-not $d -or $d.Via -eq 'Dieser PC') { continue }
        $ip = [string]$d.Ip; $p = @($d.Ports); $wi = $Web[$ip]; $title = if ($wi) { [string]$wi.Title + ' ' + [string]$wi.Server } else { '' }
        $md = $mdns[$ip]; $sd = $ssdp[$ip]; $svc = if ($md) { @($md.Services) -join ' ' } else { '' }
        # Shelly
        if ($p -contains 80 -and ($svc -match '_shelly' -or $title -match '(?i)shelly' -or ($md -and (@($md.Names) -join ' ') -match '(?i)shelly') -or [string]$d.Host -match '(?i)shelly' -or $p.Count -le 2)) {
            $r = Get-NdocHttp ('http://{0}/shelly' -f $ip)
            if ($r.Json) { $j = $r.Json; $gen = if ($j.gen) { [int]$j.gen } else { 1 }; $au = if ($gen -ge 2) { [bool]$j.auth_en } else { [bool]$j.auth }
                & $add $ip ('Shelly Gen{0}' -f $gen) $(if ($j.model) { [string]$j.model } elseif ($j.type) { [string]$j.type } else { [string]$j.app }) $(if ($j.ver) { [string]$j.ver } else { [string]$j.fw }) $(if ($au) { 'Passwort' } else { 'KEIN Passwort' }) $(if ($au) { 'OK' } else { 'Mittel' }) $(if ($j.name) { 'Name: ' + $j.name } else { '' }) }
        }
        # Tasmota
        if ($p -contains 80 -and $title -match '(?i)tasmota') {
            $r = Get-NdocHttp ('http://{0}/cm?cmnd=Status%202' -f $ip)
            $open = [bool]($r.Json -and $r.Json.StatusFWR)
            & $add $ip 'Tasmota' '' $(if ($open) { [string]$r.Json.StatusFWR.Version } else { '' }) $(if ($open) { 'KEIN Passwort' } elseif ($r.Code -eq 401) { 'Passwort' } else { '?' }) $(if ($open) { 'Mittel' } else { 'OK' }) 'Tasmota-Firmware (ESP)'
        }
        # Hue Bridge
        if (($sd -and (@($sd.Types) -contains 'hue-bridge' -or $sd.Server -match 'IpBridge')) -or $svc -match '_hue' -or $title -match '(?i)hue') {
            $r = Get-NdocHttp ('http://{0}/api/config' -f $ip)
            if ($r.Json -and $r.Json.bridgeid) { & $add $ip 'Philips Hue Bridge' ('{0} ({1})' -f $r.Json.name, $r.Json.modelid) ('{0} / API {1}' -f $r.Json.swversion, $r.Json.apiversion) 'Taste an der Bridge' 'OK' 'Zigbee-Lichtsteuerung; neue Apps brauchen den Knopfdruck an der Bridge.' }
        }
        # Node-RED
        if ($p -contains 1880) {
            $r = Get-NdocHttp ('http://{0}:1880/flows' -f $ip)
            & $add $ip 'Node-RED' '' '' $(if ($r.Code -eq 200) { 'KEINE Anmeldung' } elseif ($r.Code -eq 401) { 'Anmeldung' } else { '?' }) $(if ($r.Code -eq 200) { 'Hoch' } else { 'OK' }) 'Automatisierungs-Server - wer den Editor erreicht, kann beliebige Befehle auf dem Gerät ausführen.'
        }
        # MQTT
        if ($p -contains 1883) {
            $rc = Test-NdocMqttAnon $ip
            & $add $ip 'MQTT-Broker' '' '' $(if ($rc -eq 0) { 'anonym erlaubt' } elseif ($rc -in 4, 5) { 'Benutzer/Kennwort' } else { '?' }) $(if ($rc -eq 0) { 'Hoch' } elseif ($null -eq $rc) { 'Info' } else { 'OK' }) 'Nachrichten-Zentrale des Smart Homes (unverschlüsselt auf Port 1883).'
        }
        # Homematic
        if ($p -contains 2001 -or $p -contains 2010 -or $title -match '(?i)homematic|raspberrymatic|debmatic|piVCCU') {
            $open = $false
            foreach ($pp in @(2010, 2001)) { if ($p -contains $pp) { $r = Get-NdocHttp ('http://{0}:{1}/' -f $ip, $pp) 'POST' '<?xml version="1.0"?><methodCall><methodName>system.listMethods</methodName><params/></methodCall>'; if ($r.Code -eq 200 -and $r.Text -match 'methodResponse') { $open = $true; break } } }
            & $add $ip 'Homematic-Zentrale (CCU)' '' '' $(if ($open) { 'API ohne Anmeldung' } else { 'geschützt/unbekannt' }) $(if ($open) { 'Mittel' } else { 'Info' }) 'XML-RPC-Schnittstelle (2001 BidCos, 2010 HmIP).'
        }
        if ($p -contains 8123) { $r = Get-NdocHttp ('http://{0}:8123/manifest.json' -f $ip); & $add $ip 'Home Assistant' $(if ($r.Json) { [string]$r.Json.name } else { '' }) '' 'Anmeldung' $(if (@($p | Where-Object { $_ -in 443, 8443 }).Count) { 'OK' } else { 'Niedrig' }) $(if (@($p | Where-Object { $_ -in 443, 8443 }).Count) { 'Zentrale' } else { 'Zentrale - Zugriff nur über unverschlüsseltes http (8123).' }) }
        if ($p -contains 6053 -or $svc -match '_esphomelib') { & $add $ip 'ESPHome' $(if ($md) { @($md.Names)[0] } else { '' }) $(if ($md -and $md.Txt['version']) { $md.Txt['version'] } else { '' }) '?' 'Info' 'Native API (6053) - in der Gerätekonfiguration einen Verschlüsselungsschlüssel (api: encryption) setzen.' }
        if ($p -contains 6638) { & $add $ip 'Zigbee-Koordinator (Netzwerk)' '' '' 'keine' 'Niedrig' 'Zigbee-Funk über TCP (z.B. SLZB-06) - unverschlüsselt, nur im Smart-Home-Netz betreiben.' }
        if ($title -match '(?i)iobroker') { & $add $ip 'ioBroker' '' '' '?' 'Info' 'Smart-Home-Zentrale - in den Admin-Einstellungen Authentifizierung aktivieren.' }
        if ($title -match '(?i)openhab') { & $add $ip 'openHAB' '' '' '?' 'Info' 'Smart-Home-Zentrale.' }
        if ($title -match '(?i)loxone' -or [string]$d.Host -match '(?i)loxone') { & $add $ip 'Loxone Miniserver' '' '' 'Anmeldung' 'Info' 'Firmware in Loxone Config aktuell halten, Fernzugriff nur über Loxone Cloud/VPN.' }
        if ($title -match '(?i)phoscon|deconz') { & $add $ip 'deCONZ / Phoscon (Zigbee)' '' '' '?' 'Info' 'Zigbee-Gateway.' }
        if ($title -match '(?i)\bgira\b|homeserver') { & $add $ip 'Gira' '' '' '?' 'Info' 'KNX-Visualisierung/Server.' }
        if ($svc -match '_hap\.' -and -not @($items | Where-Object { $_.Ip -eq $ip }).Count) { & $add $ip 'HomeKit-Gerät' $(if ($md) { @($md.Names)[0] } else { '' }) '' 'HomeKit-Kopplung' 'Info' $(if ($md -and $md.Txt['sf'] -eq '1') { 'noch NICHT gekoppelt - kann von jedem im Netz mit dem Code übernommen werden' } else { 'gekoppelt' }) }
        if ($svc -match '_matter') { & $add $ip 'Matter-Gerät' $(if ($md) { @($md.Names)[0] } else { '' }) '' 'Matter' 'Info' 'Matter (lokale, verschlüsselte Steuerung).' }
        if ($svc -match '_meshcop') { & $add $ip 'Thread-Border-Router' $(if ($md) { @($md.Names)[0] } else { '' }) '' '' 'Info' 'Verbindet Thread-Funkgeräte (Matter) mit dem Netz.' }
    }
    return [pscustomobject]@{ Mdns = $mdns; Ssdp = $ssdp; Knx = @($knx); Items = $items.ToArray() }
}
function Get-UpnpInfo {
    $u = New-Object Net.Sockets.UdpClient; $u.Client.ReceiveTimeout = 1500; $u.EnableBroadcast = $true
    $req = [Text.Encoding]::ASCII.GetBytes("M-SEARCH * HTTP/1.1`r`nHOST: 239.255.255.250:1900`r`nMAN: `"ssdp:discover`"`r`nMX: 2`r`nST: urn:schemas-upnp-org:device:InternetGatewayDevice:1`r`n`r`n")
    $locs = @(); try { $null = $u.Send($req, $req.Length, '239.255.255.250', 1900); $end = (Get-Date).AddSeconds(3); while ((Get-Date) -lt $end) { $ep = New-Object Net.IPEndPoint([Net.IPAddress]::Any, 0); try { $r = [Text.Encoding]::ASCII.GetString($u.Receive([ref]$ep)); if ($r -match '(?im)^LOCATION:\s*(\S+)') { $locs += $Matches[1] } } catch { break } } } finally { $u.Close() }
    $locs = @($locs | Select-Object -Unique)
    if (-not $locs.Count) { return [pscustomobject]@{ On = $false; Router = ''; Maps = @(); Ext = '' } }
    $maps = @(); $name = ''; $ext = ''
    foreach ($loc in $locs) {
        try {
            [xml]$x = (Invoke-WebRequest -Uri $loc -UseBasicParsing -TimeoutSec 5).Content
            $name = '{0} {1}' -f $x.root.device.manufacturer, $x.root.device.modelName
            $svc = @($x.SelectNodes("//*[local-name()='service']") | Where-Object { $_.serviceType -match 'WAN(IP|PPP)Connection' })[0]
            if (-not $svc) { continue }
            $base = if ($x.root.URLBase) { [string]$x.root.URLBase } else { ([uri]$loc).GetLeftPart('Authority') }
            $cu = [string]$svc.controlURL; if ($cu -notmatch '^http') { $cu = $base.TrimEnd('/') + '/' + $cu.TrimStart('/') }
            $st = [string]$svc.serviceType
            $call = { param($act, $inner) $b = '<?xml version="1.0"?><s:Envelope xmlns:s="http://schemas.xmlsoap.org/soap/envelope/" s:encodingStyle="http://schemas.xmlsoap.org/soap/encoding/"><s:Body><u:{0} xmlns:u="{1}">{2}</u:{0}></s:Body></s:Envelope>' -f $act, $st, $inner
                [xml](Invoke-WebRequest -Uri $cu -Method Post -Body $b -ContentType 'text/xml; charset="utf-8"' -Headers @{ SOAPAction = ('"{0}#{1}"' -f $st, $act) } -UseBasicParsing -TimeoutSec 5).Content }
            try { $ext = [string](& $call 'GetExternalIPAddress' '').SelectSingleNode("//*[local-name()='NewExternalIPAddress']").InnerText } catch { }
            for ($i = 0; $i -lt 64; $i++) {
                try { $r = & $call 'GetGenericPortMappingEntry' ("<NewPortMappingIndex>$i</NewPortMappingIndex>") } catch { break }
                $g = { param($n) [string]$r.SelectSingleNode("//*[local-name()='$n']").InnerText }
                $maps += [pscustomobject]@{ Ext = (& $g 'NewExternalPort'); Proto = (& $g 'NewProtocol'); Int = ('{0}:{1}' -f (& $g 'NewInternalClient'), (& $g 'NewInternalPort')); Desc = (& $g 'NewPortMappingDescription'); On = $(if ((& $g 'NewEnabled') -eq '1') { 'ja' } else { 'nein' }) }
            }
            break
        } catch { }
    }
    [pscustomobject]@{ On = $true; Router = $name.Trim(); Maps = @($maps); Ext = $ext }
}
# ---- FRITZ!Box per TR-064 (Anmeldung nur für diesen Lauf, Zugangsdaten werden nie gespeichert)
function Get-FbServices([string]$Base) {
    [xml]$x = (Invoke-WebRequest -Uri ($Base + '/tr64desc.xml') -UseBasicParsing -TimeoutSec 6 -ErrorAction Stop).Content
    $m = @{}
    foreach ($s in @($x.SelectNodes("//*[local-name()='service']"))) { $t = [string]$s.SelectSingleNode("*[local-name()='serviceType']").InnerText; $c = [string]$s.SelectSingleNode("*[local-name()='controlURL']").InnerText; if ($t -and -not $m.ContainsKey($t)) { $m[$t] = $c } }
    return $m
}
function Invoke-FbSoap([string]$Base, [hashtable]$Svcs, [string]$Type, [string]$Action, [hashtable]$In = @{}, $Cred = $null) {
    if (-not $Svcs.ContainsKey($Type)) { throw ('Dienst fehlt: ' + $Type) }
    $inner = (@($In.Keys) | ForEach-Object { '<{0}>{1}</{0}>' -f $_, [Security.SecurityElement]::Escape([string]$In[$_]) }) -join ''
    $body = '<?xml version="1.0" encoding="utf-8"?><s:Envelope s:encodingStyle="http://schemas.xmlsoap.org/soap/encoding/" xmlns:s="http://schemas.xmlsoap.org/soap/envelope/"><s:Body><u:{0} xmlns:u="{1}">{2}</u:{0}></s:Body></s:Envelope>' -f $Action, $Type, $inner
    $req = [Net.HttpWebRequest]::Create($Base + $Svcs[$Type]); $req.Method = 'POST'; $req.ContentType = 'text/xml; charset="utf-8"'; $req.Timeout = 10000
    $req.Headers.Add('SOAPACTION', ('"{0}#{1}"' -f $Type, $Action))
    if ($Cred) { $req.Credentials = $Cred.GetNetworkCredential() }
    $by = [Text.Encoding]::UTF8.GetBytes($body); $req.ContentLength = $by.Length; $st = $req.GetRequestStream(); $st.Write($by, 0, $by.Length); $st.Close()
    try { $resp = $req.GetResponse() } catch [Net.WebException] {
        $r = $_.Exception.Response
        if ($r -and [int]$r.StatusCode -eq 401) { throw 'Anmeldung an der FRITZ!Box abgelehnt - Benutzername/Kennwort prüfen (FRITZ!Box: System > FRITZ!Box-Benutzer, Recht "FRITZ!Box Einstellungen").' }
        throw ('{0}: {1}' -f $Action, $_.Exception.Message)
    }
    try { $sr = New-Object IO.StreamReader($resp.GetResponseStream()); [xml]$x = $sr.ReadToEnd() } finally { $resp.Close() }
    $out = @{}; $node = $x.DocumentElement.SelectSingleNode("//*[local-name()='Body']").FirstChild
    foreach ($c in @($node.ChildNodes)) { $out[$c.LocalName] = [string]$c.InnerText }
    return $out
}
function Get-FbData([string]$Gw, [string]$User, $Pass) {
    $base = 'http://{0}:49000' -f $Gw
    $svcs = Get-FbServices $base
    $err = [System.Collections.Generic.List[string]]::new()
    if (-not $User) {
        try { $ul = (Invoke-FbSoap $base $svcs 'urn:dslforum-org:service:LANConfigSecurity:1' 'X_AVM-DE_GetUserList')['NewX_AVM-DE_UserList']; if ($ul -match '<Username[^>]*last_user="1"[^>]*>([^<]+)<') { $User = $Matches[1] } elseif ($ul -match '<Username[^>]*>([^<]+)<') { $User = $Matches[1] } } catch { }
    }
    $cred = New-Object Management.Automation.PSCredential ($(if ($User) { $User } else { 'admin' }), $Pass)
    $call = { param($t, $a, $in) try { Invoke-FbSoap $base $svcs $t $a $(if ($in) { $in } else { @{} }) $cred } catch { $err.Add(('{0}/{1}: {2}' -f ($t -replace '^urn:dslforum-org:service:', ''), $a, $_.Exception.Message)); $null } }
    $o = [ordered]@{ User = $User; Device = $null; Update = $null; Hosts = @(); Wlan = @(); Conn = $null; PortMaps = @(); Remote = $null; MyFritz = $null; Upnp = $null; Dsl = $null; Link = $null; Errors = $err }
    $o.Device = & $call 'urn:dslforum-org:service:DeviceInfo:1' 'GetInfo'
    if (-not $o.Device) { throw ('FRITZ!Box-Anmeldung fehlgeschlagen: ' + (@($err) -join '; ')) }
    $o.Update = & $call 'urn:dslforum-org:service:UserInterface:1' 'GetInfo'
    # Geräteliste (auch ausgeschaltete Geräte)
    $hl = & $call 'urn:dslforum-org:service:Hosts:1' 'X_AVM-DE_GetHostListPath'
    if ($hl -and $hl['NewX_AVM-DE_HostListPath']) {
        try {
            $p = [string]$hl['NewX_AVM-DE_HostListPath']; $u = if ($p -match '^https?:') { $p } else { $base + $p }
            [xml]$hx = (Invoke-WebRequest -Uri $u -UseBasicParsing -TimeoutSec 10 -ErrorAction Stop).Content
            $o.Hosts = @($hx.List.Item | ForEach-Object { [pscustomobject]@{ Ip = [string]$_.IPAddress; Mac = ([string]$_.MACAddress).ToUpper(); Name = [string]$_.HostName; Active = ([string]$_.Active -eq '1'); Iface = [string]$_.InterfaceType; Port = [string]$_.'X_AVM-DE_Port'; Speed = [string]$_.'X_AVM-DE_Speed'; Guest = ([string]$_.'X_AVM-DE_Guest' -eq '1'); Vpn = ([string]$_.'X_AVM-DE_VPN' -eq '1'); Blocked = ([string]$_.'X_AVM-DE_Disallow' -eq '1') } })
        } catch { $err.Add('Geräteliste: ' + $_.Exception.Message) }
    }
    # WLAN-Funknetze und WPS
    $wl = [System.Collections.Generic.List[object]]::new()
    for ($i = 1; $i -le 4; $i++) {
        $t = 'urn:dslforum-org:service:WLANConfiguration:{0}' -f $i; if (-not $svcs.ContainsKey($t)) { continue }
        $g = & $call $t 'GetInfo'; if (-not $g) { continue }
        $wps = & $call $t 'X_AVM-DE_GetWPSInfo'
        $wl.Add([pscustomobject]@{ Index = $i; Enabled = ($g['NewEnable'] -eq '1'); Ssid = $g['NewSSID']; Channel = $g['NewChannel']; Standard = $g['NewStandard']; Beacon = $g['NewBeaconType']; Status = $g['NewStatus']; Wps = $(if ($wps) { [string]$wps['NewX_AVM-DE_WPSMode'] } else { '' }); WpsStatus = $(if ($wps) { [string]$wps['NewX_AVM-DE_WPSStatus'] } else { '' }) })
    }
    if ($wl.Count -ge 3) { $wl[$wl.Count - 1] | Add-Member -NotePropertyName Guest -NotePropertyValue $true -Force }
    $o.Wlan = $wl.ToArray()
    # Internetverbindung und Portfreigaben
    foreach ($ct in 'urn:dslforum-org:service:WANPPPConnection:1', 'urn:dslforum-org:service:WANIPConnection:1') {
        if (-not $svcs.ContainsKey($ct)) { continue }
        $ci = & $call $ct 'GetInfo'; if (-not $ci) { continue }
        if (-not $o.Conn -or $ci['NewConnectionStatus'] -eq 'Connected') { $o.Conn = [pscustomobject]@{ Type = ($ct -replace '^.*service:', ''); Status = $ci['NewConnectionStatus']; ExtIp = $ci['NewExternalIPAddress']; Uptime = $ci['NewUptime']; Maps = [int]$ci['NewPortMappingNumberOfEntries'] } }
        $n = [int]$ci['NewPortMappingNumberOfEntries']
        $mp = for ($k = 0; $k -lt [math]::Min($n, 100); $k++) { $e = & $call $ct 'GetGenericPortMappingEntry' @{ NewPortMappingIndex = $k }; if ($e) { [pscustomobject]@{ Ext = $e['NewExternalPort']; Proto = $e['NewProtocol']; Ip = $e['NewInternalClient']; IntPort = $e['NewInternalPort']; Enabled = ($e['NewEnabled'] -eq '1'); Desc = $e['NewPortMappingDescription']; Remote = $e['NewRemoteHost']; Lease = $e['NewLeaseDuration'] } } }
        $o.PortMaps = @($o.PortMaps) + @($mp)
    }
    $o.Remote = & $call 'urn:dslforum-org:service:X_AVM-DE_RemoteAccess:1' 'GetInfo'
    $o.MyFritz = & $call 'urn:dslforum-org:service:X_AVM-DE_MyFritz:1' 'GetInfo'
    $o.Upnp = & $call 'urn:dslforum-org:service:X_AVM-DE_UPnP:1' 'GetInfo'
    if ($svcs.ContainsKey('urn:dslforum-org:service:WANDSLInterfaceConfig:1')) { $o.Dsl = & $call 'urn:dslforum-org:service:WANDSLInterfaceConfig:1' 'GetInfo' }
    $o.Link = & $call 'urn:dslforum-org:service:WANCommonInterfaceConfig:1' 'GetCommonLinkProperties'
    return [pscustomobject]$o
}
# ---- Erreichbarkeit von außen: öffentliche IP bei Shodan InternetDB nachschlagen (passiv, nur die eigene IP)
function Get-NdocShodan([string]$Ip) {
    if ($Ip -notmatch '^\d+\.\d+\.\d+\.\d+$') { return $null }
    try { [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12 } catch { }
    try { $j = Invoke-RestMethod -Uri ('https://internetdb.shodan.io/{0}' -f $Ip) -TimeoutSec 10 -ErrorAction Stop; return [pscustomobject]@{ Found = $true; Ports = @($j.ports); Vulns = @($j.vulns); Hostnames = @($j.hostnames); Cpes = @($j.cpes); Tags = @($j.tags) } }
    catch { $c = 0; try { $c = [int]$_.Exception.Response.StatusCode } catch { }; if ($c -eq 404) { return [pscustomobject]@{ Found = $false; Ports = @(); Vulns = @(); Hostnames = @(); Cpes = @(); Tags = @() } }; return $null }
}
function Test-NdocPrivateIp([string]$Ip) { return ($Ip -match '^(10\.|192\.168\.|172\.(1[6-9]|2\d|3[01])\.|100\.(6[4-9]|[7-9]\d|1[01]\d|12[0-7])\.|0\.0\.0\.0$)') }
$NdocExtRisk = @{ 23 = @(1, 'Telnet - unverschlüsselt, Hauptziel von Botnetzen'); 445 = @(1, 'Windows-Dateifreigabe - nie ins Internet (WannaCry)'); 139 = @(1, 'NetBIOS/Dateifreigabe'); 3389 = @(1, 'Remotedesktop - ständig Ziel von Passwort-Angriffen und Ransomware'); 5900 = @(1, 'VNC-Fernsteuerung'); 2375 = @(1, 'Docker-API - Übernahme des Servers'); 3671 = @(1, 'KNX - Haussteuerung aus dem Internet schaltbar'); 6379 = @(1, 'Redis-Datenbank'); 27017 = @(1, 'MongoDB'); 9200 = @(1, 'Elasticsearch'); 3306 = @(1, 'MySQL/MariaDB'); 5432 = @(1, 'PostgreSQL'); 1433 = @(1, 'SQL Server'); 1880 = @(1, 'Node-RED - Befehlsausführung'); 1883 = @(1, 'MQTT unverschlüsselt - Smart Home schaltbar'); 2001 = @(1, 'Homematic-API'); 2010 = @(1, 'Homematic-IP-API'); 21 = @(2, 'FTP - Kennwörter im Klartext'); 80 = @(2, 'unverschlüsselte Weboberfläche'); 8080 = @(2, 'unverschlüsselte Weboberfläche'); 8081 = @(2, 'unverschlüsselte Weboberfläche'); 8000 = @(2, 'unverschlüsselte Weboberfläche'); 10000 = @(2, 'Webmin (Root-Zugriff)'); 554 = @(2, 'Kamera-Stream'); 5000 = @(2, 'NAS-Oberfläche unverschlüsselt'); 8123 = @(2, 'Home Assistant'); 8883 = @(3, 'MQTT mit TLS'); 22 = @(3, 'SSH - nur mit Schlüssel und Fail2ban'); 443 = @(3, 'verschlüsselte Weboberfläche'); 8443 = @(3, 'verschlüsselte Weboberfläche'); 5001 = @(3, 'NAS-Oberfläche (https)'); 9443 = @(3, 'Portainer (https)'); 32400 = @(4, 'Plex Media Server'); 51820 = @(5, 'WireGuard-VPN (gut)'); 1194 = @(5, 'OpenVPN'); 500 = @(5, 'IPsec-VPN'); 4500 = @(5, 'IPsec-VPN') }
function Get-NdocExposure($X, $Rows) {
    $list = [System.Collections.Generic.List[object]]::new()
    $nm = { param($ip) $r = @($Rows | Where-Object { $_.Ip -eq $ip })[0]; if ($r) { '{0} ({1})' -f ([string]$r.Name -replace '\s+\[.*$', ''), $ip } else { $ip } }
    $sevT = @('', 'Kritisch', 'Hoch', 'Mittel', 'Niedrig', 'Info')
    $add = { param($way, $ext, $target, $svc, $sev, $hint) $list.Add([pscustomobject]@{ Way = $way; External = $ext; Target = $target; Service = $svc; SevNo = $sev; Sev = $sevT[$sev]; Hint = $hint }) }
    $seen = @{}
    $maps = @()
    if ($X.Fritz) { $maps += @($X.Fritz.PortMaps | Where-Object { $_ -and $_.Enabled } | ForEach-Object { [pscustomobject]@{ Src = $(if ($_.Lease -and $_.Lease -ne '0') { 'Portfreigabe (UPnP, automatisch)' } else { 'Portfreigabe (FRITZ!Box)' }); Ext = [string]$_.Ext; Proto = [string]$_.Proto; Ip = [string]$_.Ip; Port = [string]$_.IntPort; Desc = [string]$_.Desc } }) }
    if ($X.Router -and $X.Router.Upnp) { $maps += @($X.Router.Upnp.Maps | ForEach-Object { $ip, $pt = ([string]$_.Int -split ':', 2); [pscustomobject]@{ Src = 'Portfreigabe (UPnP, automatisch)'; Ext = [string]$_.Ext; Proto = [string]$_.Proto; Ip = $ip; Port = $pt; Desc = [string]$_.Desc } }) }
    foreach ($m in $maps) {
        $k = $m.Ext + '/' + $m.Proto; if ($seen.ContainsKey($k)) { continue }; $seen[$k] = 1
        $pi = 0; [void][int]::TryParse($m.Port, [ref]$pi); $r = $NdocExtRisk[$pi]; if (-not $r) { $r = @(3, 'Dienst unbekannt - prüfen, ob die Freigabe gebraucht wird') }
        $isKnx = $X.Smart -and @($X.Smart.Knx | Where-Object { $_.Ip -eq $m.Ip }).Count
        if ($isKnx) { $r = @(1, 'KNX-Schnittstelle aus dem Internet erreichbar') }
        & $add $m.Src ('{0}/{1}' -f $m.Ext, $m.Proto) (& $nm $m.Ip) ('Port {0}{1}' -f $m.Port, $(if ($m.Desc) { ' - ' + $m.Desc } else { '' })) $r[0] $r[1]
    }
    if ($X.Fritz) {
        $ra = $X.Fritz.Remote
        if ($ra -and $ra['NewEnabled'] -eq '1') { & $add 'Fernzugang zur FRITZ!Box' ('{0}/TCP (https)' -f $ra['NewPort']) 'FRITZ!Box-Oberfläche' 'Internetzugriff auf die FRITZ!Box' 3 'Nur mit starkem Kennwort und Zwei-Faktor-Anmeldung; wenn möglich stattdessen VPN (WireGuard) nutzen.' }
        $mf = $X.Fritz.MyFritz
        if ($mf -and $mf['NewEnabled'] -eq '1') { & $add 'MyFRITZ!' $(if ($mf['NewDynDNSName']) { $mf['NewDynDNSName'] } else { '-' }) 'FRITZ!Box' 'MyFRITZ!-Konto / Adresse' 5 'Ermöglicht Zugriff über myfritz.net - Freigaben und Fernzugang darüber prüfen.' }
    }
    $sh = $X.Shodan
    if ($sh -and $sh.Found) {
        foreach ($p in @($sh.Ports | Sort-Object)) {
            $known = @($list | Where-Object { ([string]$_.External -split '/')[0] -eq [string]$p })
            if ($known.Count) { foreach ($k in $known) { $k.Hint = [string]$k.Hint + ' Von Shodan bei einem Internet-Scan bestätigt.' }; continue }
            $r = $NdocExtRisk[[int]$p]; if (-not $r) { $r = @(3, 'offen sichtbar') }
            & $add 'Laut Shodan aus dem Internet sichtbar' ('{0}' -f $p) $X.PublicIp ('Port {0}' -f $p) $r[0] ($r[1] + ' - von Shodan bei einem Internet-Scan gesehen, keine Freigabe dazu bekannt (z.B. Dienst direkt auf dem Router oder Freigabe ohne FRITZ!Box-Anmeldung nicht lesbar).')
        }
        if (@($sh.Vulns).Count) { & $add 'Laut Shodan bekannte Schwachstellen' ('{0} CVE' -f @($sh.Vulns).Count) $X.PublicIp ((@($sh.Vulns) | Select-Object -First 12) -join ', ') 2 'Shodan ordnet der Software an dieser Adresse bekannte Sicherheitslücken zu - betroffenes Gerät aktualisieren.' }
    } elseif ($sh -and -not $sh.Found) { & $add 'Shodan InternetDB' '-' $X.PublicIp 'keine Einträge' 5 'Shodan kennt an dieser Adresse keine offenen Dienste (gut).' }
    $ext = if ($X.Fritz -and $X.Fritz.Conn) { [string]$X.Fritz.Conn.ExtIp } elseif ($X.Router -and $X.Router.Upnp) { [string]$X.Router.Upnp.Ext } else { '' }
    if ($X.PublicIp) {
        if ($ext -and (Test-NdocPrivateIp $ext)) { & $add 'Anschlussart' $ext 'Router' 'Carrier-NAT / Doppel-NAT' 5 ('Der Router hat nur eine interne Adresse ({0}), öffentlich ist {1}. Eingehende IPv4-Verbindungen sind dadurch kaum möglich - Portfreigaben wirken nur über IPv6.' -f $ext, $X.PublicIp) }
        elseif ($ext -and $ext -ne $X.PublicIp) { & $add 'Anschlussart' $ext 'Router' 'abweichende IP' 5 ('Router meldet {0}, nach außen sichtbar ist {1} (DS-Lite/Carrier-NAT oder zweiter Router).' -f $ext, $X.PublicIp) }
        else { & $add 'Anschlussart' $X.PublicIp 'Router' 'öffentliche IPv4-Adresse' 5 'Der Anschluss hat eine eigene öffentliche IPv4-Adresse - Portfreigaben sind direkt aus dem Internet erreichbar.' }
    }
    if ($X.Router -and $X.Router.Ipv6 -and @($X.Router.Ipv6.Global).Count) { & $add 'IPv6' 'öffentliche IPv6-Adressen' 'alle Geräte mit IPv6' 'IPv6-Freigaben' 5 'Mit IPv6 hat jedes Gerät eine weltweite Adresse. Die FRITZ!Box blockt eingehend standardmäßig - Freigaben unter Internet > Freigaben > Portfreigaben (IPv6) prüfen.' }
    return , @($list | Sort-Object SevNo)
}
# ---- Home Assistant per langlebigem Zugriffstoken (nur lesend)
function Get-NdocHomeAssistant([string]$Url, [string]$Token) {
    $Url = $Url.TrimEnd('/'); $h = @{ Authorization = 'Bearer ' + $Token }
    try { [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12 } catch { }
    $cfg = Invoke-RestMethod -Uri ($Url + '/api/config') -Headers $h -TimeoutSec 10 -ErrorAction Stop
    $st = @(Invoke-RestMethod -Uri ($Url + '/api/states') -Headers $h -TimeoutSec 20 -ErrorAction Stop)
    $st = @($st | ForEach-Object { $_ })
    $dom = @{}; foreach ($e in $st) { $d = ([string]$e.entity_id -split '\.')[0]; $dom[$d] = 1 + [int]$dom[$d] }
    $upd = @($st | Where-Object { $_.entity_id -like 'update.*' -and $_.state -eq 'on' } | ForEach-Object { [pscustomobject]@{ Name = $(if ($_.attributes.title) { [string]$_.attributes.title } else { [string]$_.attributes.friendly_name }); Installed = [string]$_.attributes.installed_version; Latest = [string]$_.attributes.latest_version; Core = ($_.entity_id -match 'home_assistant_(core|operating_system|supervisor)') } })
    $un = @($st | Where-Object { $_.state -in 'unavailable', 'unknown' -and $_.entity_id -notlike 'update.*' -and $_.entity_id -notlike 'button.*' -and $_.entity_id -notlike 'scene.*' })
    $bat = @($st | Where-Object { $_.attributes.device_class -eq 'battery' -and $_.attributes.unit_of_measurement -eq '%' } | ForEach-Object { $v = 0.0; if ([double]::TryParse([string]$_.state, [Globalization.NumberStyles]::Float, [Globalization.CultureInfo]::InvariantCulture, [ref]$v) -and $v -lt 20) { [pscustomobject]@{ Name = [string]$_.attributes.friendly_name; Value = $v } } })
    [pscustomobject]@{ Url = $Url; Version = [string]$cfg.version; Name = [string]$cfg.location_name; Components = @(@($cfg.components) | ForEach-Object { ($_ -split '\.')[0] } | Sort-Object -Unique); Entities = $st.Count; Domains = $dom; Updates = $upd; Unavailable = @($un | Select-Object -First 40 | ForEach-Object { if ($_.attributes.friendly_name) { [string]$_.attributes.friendly_name } else { [string]$_.entity_id } }); UnavailCount = $un.Count; LowBattery = $bat }
}
# ---- KNX-Busmonitor (passiv): lauscht am KNX-Routing-Multicast mit, sendet nichts
function Invoke-NdocKnxMonitor([string]$LocalIp, [int]$Sec = 60) {
    $u = New-Object Net.Sockets.UdpClient
    $u.Client.SetSocketOption([Net.Sockets.SocketOptionLevel]::Socket, [Net.Sockets.SocketOptionName]::ReuseAddress, $true)
    $u.Client.Bind((New-Object Net.IPEndPoint([Net.IPAddress]::Any, 3671)))
    $u.JoinMulticastGroup([Net.IPAddress]::Parse('224.0.23.12'), [Net.IPAddress]::Parse($LocalIp))
    $u.Client.ReceiveTimeout = 500
    $ga = @{}; $pa = @{}; $n = 0; $end = (Get-Date).AddSeconds($Sec)
    try {
        while ((Get-Date) -lt $end) {
            $ep = New-Object Net.IPEndPoint([Net.IPAddress]::Any, 0)
            try { $b = $u.Receive([ref]$ep) } catch { continue }
            if ($b.Length -lt 17 -or $b[0] -ne 6 -or $b[2] -ne 5 -or $b[3] -ne 0x30 -or $b[6] -ne 0x29) { continue }
            $p = 8 + $b[7]; if ($p + 8 -gt $b.Length) { continue }
            $c2 = $b[$p + 1]; $src = $b[$p + 2] * 256 + $b[$p + 3]; $dst = $b[$p + 4] * 256 + $b[$p + 5]; $len = $b[$p + 6]
            $n++
            $sp = '{0}.{1}.{2}' -f ($src -shr 12), (($src -shr 8) -band 15), ($src -band 255); $pa[$sp] = 1 + [int]$pa[$sp]
            if (($c2 -band 0x80) -eq 0 -or $len -lt 1 -or $p + 8 -ge $b.Length) { continue }
            $apci = ((($b[$p + 7] -band 3) * 256) + $b[$p + 8]) -band 0x3C0
            $cmd = switch ($apci) { 0x000 { 'Lesen' } 0x040 { 'Antwort' } 0x080 { 'Schreiben' } default { 'sonst' } }
            $val = if ($len -eq 1) { '{0:X2}' -f ($b[$p + 8] -band 0x3F) } else { (($b[($p + 9)..([math]::Min($b.Length - 1, $p + 7 + $len))] | ForEach-Object { '{0:X2}' -f $_ }) -join ' ') }
            $g = '{0}/{1}/{2}' -f ($dst -shr 11), (($dst -shr 8) -band 7), ($dst -band 255)
            if (-not $ga.ContainsKey($g)) { $ga[$g] = [pscustomobject]@{ Ga = $g; Count = 0; Write = 0; Read = 0; Resp = 0; Last = ''; Sources = [System.Collections.Generic.HashSet[string]]::new() } }
            $e = $ga[$g]; $e.Count++; if ($cmd -eq 'Schreiben') { $e.Write++ } elseif ($cmd -eq 'Lesen') { $e.Read++ } elseif ($cmd -eq 'Antwort') { $e.Resp++ }; if ($cmd -ne 'Lesen') { $e.Last = $val }; [void]$e.Sources.Add($sp)
        }
    } finally { try { $u.DropMulticastGroup([Net.IPAddress]::Parse('224.0.23.12')) } catch { }; $u.Close() }
    [pscustomobject]@{ Time = (Get-Date); Seconds = $Sec; Frames = $n; Groups = @($ga.Values | Sort-Object Count -Descending | ForEach-Object { [pscustomobject]@{ Ga = $_.Ga; Count = $_.Count; Write = $_.Write; Read = $_.Read; Resp = $_.Resp; Last = $_.Last; Sources = (@($_.Sources) -join ', ') } }); Devices = @($pa.Keys | Sort-Object { -[int]$pa[$_] } | ForEach-Object { [pscustomobject]@{ Pa = $_; Count = [int]$pa[$_] } }) }
}
# ---- Ablage: Einstellungen, Inventarfelder, Momentaufnahmen und Vergleich ($DataDir\Netzdoku)
function Get-NdocDir { $d = Join-Path $DataDir 'Netzdoku'; if (-not (Test-Path -LiteralPath $d)) { New-Item -Path $d -ItemType Directory -Force | Out-Null }; return $d }
function Read-NdocJson([string]$Name, $Default) { try { $f = Join-Path (Get-NdocDir) $Name; if (Test-Path -LiteralPath $f) { return (Get-Content -LiteralPath $f -Raw -Encoding UTF8 | ConvertFrom-Json) } } catch { }; return $Default }
function Save-NdocJson([string]$Name, $Obj) { $Obj | ConvertTo-Json -Depth 8 | Set-Content -LiteralPath (Join-Path (Get-NdocDir) $Name) -Encoding UTF8 }
function Get-NdocInventory { $i = Read-NdocJson 'inventar.json' $null; $h = @{}; if ($i) { foreach ($p in $i.PSObject.Properties) { $h[$p.Name] = $p.Value } }; return $h }
function Save-NdocSnapshot($Res) {
    $d = Join-Path (Get-NdocDir) 'Verlauf'; New-Item -Path $d -ItemType Directory -Force | Out-Null
    $o = [pscustomobject]@{ Time = $Res.Data.Time.ToString('o'); Net = ('{0}/{1}' -f $Res.Data.Net.Ip, $Res.Data.Net.Prefix); Devices = @($Res.Rows | Where-Object { -not $_.Offline } | ForEach-Object { [pscustomobject]@{ Key = $_.Key; Name = $_.Name; Ip = $_.Ip; Mac = $_.Mac; Vendor = $_.Vendor; Type = $_.Type; Ports = @($_.PortList) } }); Findings = @($Res.Find | ForEach-Object { [pscustomobject]@{ Key = ($_.Device + '|' + $_.Title); Sev = $_.Sev; SevNo = $_.SevNo; Title = $_.Title; Device = $_.Device } }) }
    $o | ConvertTo-Json -Depth 6 | Set-Content -LiteralPath (Join-Path $d ('{0:yyyy-MM-dd_HHmmss}.json' -f $Res.Data.Time)) -Encoding UTF8
    Get-ChildItem -LiteralPath $d -Filter '*.json' | Sort-Object Name -Descending | Select-Object -Skip 60 | Remove-Item -Force -ErrorAction SilentlyContinue
}
function Get-NdocLastSnapshot {
    $d = Join-Path (Get-NdocDir) 'Verlauf'; if (-not (Test-Path -LiteralPath $d)) { return $null }
    $f = Get-ChildItem -LiteralPath $d -Filter '*.json' | Sort-Object Name -Descending | Select-Object -First 1
    if (-not $f) { return $null }; try { return (Get-Content -LiteralPath $f.FullName -Raw -Encoding UTF8 | ConvertFrom-Json) } catch { return $null }
}
function Compare-NdocSnapshot($Prev, $Rows, $Find) {
    if (-not $Prev) { return $null }
    $pd = @{}; foreach ($d in @($Prev.Devices)) { if ($d) { $pd[[string]$d.Key] = $d } }
    $cur = @($Rows | Where-Object { -not $_.Offline }); $cd = @{}; foreach ($r in $cur) { $cd[[string]$r.Key] = $r }
    $new = @($cur | Where-Object { -not $pd.ContainsKey([string]$_.Key) })
    $gone = @($pd.Values | Where-Object { -not $cd.ContainsKey([string]$_.Key) })
    $ipc = [System.Collections.Generic.List[object]]::new(); $po = [System.Collections.Generic.List[object]]::new(); $pc = [System.Collections.Generic.List[object]]::new()
    foreach ($r in $cur) {
        if (-not $pd.ContainsKey([string]$r.Key)) { continue }; $o = $pd[[string]$r.Key]
        if ([string]$o.Ip -ne [string]$r.Ip) { $ipc.Add([pscustomobject]@{ Name = $r.Name; Old = $o.Ip; New = $r.Ip }) }
        $op = @($o.Ports | ForEach-Object { [int]$_ }); $np = @($r.PortList | ForEach-Object { [int]$_ })
        $a = @($np | Where-Object { $op -notcontains $_ }); $z = @($op | Where-Object { $np -notcontains $_ })
        if ($a.Count -and $op.Count + $np.Count) { $po.Add([pscustomobject]@{ Name = $r.Name; Ip = $r.Ip; Ports = ($a -join ', ') }) }
        if ($z.Count) { $pc.Add([pscustomobject]@{ Name = $r.Name; Ip = $r.Ip; Ports = ($z -join ', ') }) }
    }
    $pf = @{}; foreach ($x in @($Prev.Findings)) { if ($x) { $pf[[string]$x.Key] = $x } }
    $cf = @{}; foreach ($x in @($Find)) { $cf[($x.Device + '|' + $x.Title)] = $x }
    [pscustomobject]@{ PrevTime = [string]$Prev.Time; NewDev = $new; GoneDev = $gone; IpChanged = $ipc.ToArray(); PortsOpened = $po.ToArray(); PortsClosed = $pc.ToArray()
        NewFind = @($Find | Where-Object { $_.SevNo -le 4 -and -not $pf.ContainsKey($_.Device + '|' + $_.Title) }); FixedFind = @($pf.Values | Where-Object { [int]$_.SevNo -le 4 -and -not $cf.ContainsKey([string]$_.Key) }) }
}
# ---- FRITZ!Box-Geräteliste mit dem Scan zusammenführen (Namen, Anschluss, ausgeschaltete Geräte)
function Merge-NdocFritzHosts($Rows, $Fb, $Table) {
    $out = [System.Collections.Generic.List[object]]::new(); foreach ($r in @($Rows)) { $out.Add($r) }
    if (-not $Fb -or -not @($Fb.Hosts).Count) { return , $out.ToArray() }
    $byMac = @{}; foreach ($h in @($Fb.Hosts)) { if ($h.Mac) { $byMac[(Format-NtMac $h.Mac)] = $h } }
    foreach ($r in $out) {
        $h = $byMac[[string]$r.Mac]; if (-not $h) { continue }
        $conn = if ($h.Iface -match '802') { 'WLAN' + $(if ($h.Speed) { ' ' + $h.Speed + ' Mbit/s' } else { '' }) } elseif ($h.Iface) { 'LAN' + $(if ($h.Port) { ' Port ' + $h.Port } else { '' }) + $(if ($h.Speed -and $h.Speed -ne '0') { ' ' + $h.Speed + ' Mbit/s' } else { '' }) } else { '' }
        if ($h.Guest) { $conn += ' (Gastnetz)' }
        $r | Add-Member -NotePropertyName Conn -NotePropertyValue $conn.Trim() -Force
        if ($h.Name -and ([string]$r.Name -match '^\(' -or [string]$r.Name -match '^\d+\.\d+\.\d+\.\d+$')) { $r.Name = $h.Name + $(if ($r.Gateway) { '  [Router]' } else { '' }) }
        if ($h.Blocked) { $r | Add-Member -NotePropertyName Blocked -NotePropertyValue $true -Force }
    }
    $have = @{}; foreach ($r in $out) { if ($r.Mac) { $have[[string]$r.Mac] = 1 } }
    foreach ($h in @($Fb.Hosts)) {
        $m = Format-NtMac $h.Mac; if (-not $m -or $have.ContainsKey($m)) { continue }
        $vend = Get-NtVendor $m $Table
        $out.Add([pscustomobject]@{ Key = $m; Name = $(if ($h.Name) { $h.Name } else { '(unbekannt)' }); Ip = $h.Ip; IpSort = (Get-NtIpSort $(if ($h.Ip) { $h.Ip } else { '255.255.255.255' })); Mac = $m; Vendor = $vend; Host = $h.Name; Rtt = -1; RttText = '-'; PortList = @(); Ports = ''; IsNew = $false; NewText = $(if ($h.Active) { 'aktiv laut FRITZ!Box' } else { 'ausgeschaltet/offline' }); Level = ''; Gateway = $false; Self = $false; Offline = (-not $h.Active); Conn = $(if ($h.Iface -match '802') { 'WLAN' } elseif ($h.Iface) { 'LAN' } else { '' }) + $(if ($h.Guest) { ' (Gastnetz)' } else { '' }); System = ''; Type = 'Unbekannt'; Blocked = $h.Blocked })
    }
    return , $out.ToArray()
}
# ---- WLAN-Rundgang: Empfang je Raum messen und speichern
function Measure-WlanRoom([string]$Room, [int]$Sec = 10) {
    $a = Get-WlanAdapter; if (-not $a) { throw 'Kein WLAN-Adapter gefunden.' }
    $gw = ''; try { $gw = [string](@(Get-NetIPConfiguration -InterfaceIndex $a.ifIndex -ErrorAction Stop).IPv4DefaultGateway | Select-Object -First 1).NextHop } catch { }
    $sig = [System.Collections.Generic.List[int]]::new(); $rx = [System.Collections.Generic.List[double]]::new(); $ms = [System.Collections.Generic.List[double]]::new(); $lost = 0; $n = 0; $last = $null
    $ping = New-Object System.Net.NetworkInformation.Ping; $end = (Get-Date).AddSeconds($Sec)
    while ((Get-Date) -lt $end) {
        $i = Get-WlanIfInfo; if ($i.Bssid) { $sig.Add($i.Signal); $rx.Add($i.Rx); $last = $i }
        if ($gw) { $n++; try { $r = $ping.Send($gw, 800); if ($r.Status -eq 'Success') { $ms.Add($r.RoundtripTime) } else { $lost++ } } catch { $lost++ } }
        Start-Sleep -Milliseconds 300
    }
    if (-not $last) { throw 'Keine WLAN-Verbindung während der Messung.' }
    $s = [math]::Round(($sig | Measure-Object -Average).Average); $dbm = [int]($s / 2 - 100)
    [pscustomobject]@{ Room = $Room; Time = (Get-Date).ToString('dd.MM.yyyy HH:mm'); Signal = $s; Dbm = $dbm; Band = $last.Band; Channel = $last.Channel; Bssid = $last.Bssid; Ssid = $last.Ssid; Rx = [math]::Round(($rx | Measure-Object -Average).Average); Ping = $(if ($ms.Count) { [math]::Round(($ms | Measure-Object -Average).Average) } else { -1 }); Loss = $(if ($n) { [math]::Round(100.0 * $lost / $n) } else { 0 }); Rating = $(if ($dbm -ge -60) { 'sehr gut' } elseif ($dbm -ge -67) { 'gut' } elseif ($dbm -ge -75) { 'mittel' } else { 'schwach' }) }
}
# ---- Ergebnis aufbereiten (Oberfläche und automatische Erfassung)
function Complete-NdocResult($X, [string]$DevFile) {
    $store = Read-NtDevStore $DevFile
    $rows = @(ConvertTo-NtDeviceRows $X.Devices $store $X.Net $NtOui | ForEach-Object { $_ })
    $null = Save-NtDevStore $DevFile $store $rows ('{0}/{1} über {2}' -f $X.Net.Ip, $X.Net.Prefix, $X.Net.Name)
    foreach ($rw in $rows) {
        $sys = Get-NdocSystemText $rw $X.Smart
        $rw | Add-Member -NotePropertyName System -NotePropertyValue $sys -Force
        $rw | Add-Member -NotePropertyName Type -NotePropertyValue (Get-NdocDevType $rw $X.Web[[string]$rw.Ip] $X.Smart) -Force
        if ($sys -and ([string]$rw.Name -match '^\(')) { $rw.Name = (($sys -split ' · ')[0] -replace '\s*\[.*$', '') + $(if ($rw.Gateway) { '  [Router]' } else { '' }) }
        $rw | Add-Member -NotePropertyName Offline -NotePropertyValue $false -Force
        $rw | Add-Member -NotePropertyName Conn -NotePropertyValue '' -Force
    }
    $rows = @(Merge-NdocFritzHosts $rows $X.Fritz $NtOui | ForEach-Object { $_ })
    $wnets = if ($X.Wlan) { @($X.Wlan.Nets) } else { @() }
    foreach ($rw in $rows) {
        $sn = if ($X.Infra -and $X.Infra.Snmp) { $X.Infra.Snmp[[string]$rw.Ip] } else { $null }
        $ir = Get-NdocInfraRole $rw $X.Web[[string]$rw.Ip] $sn $X.Smart $wnets
        $rw | Add-Member -NotePropertyName Infra -NotePropertyValue $ir -Force
        if ($ir.Role -and -not $rw.Gateway -and -not $rw.Self -and [string]$rw.Type -notin 'Drucker', 'Kamera/NVR', 'KNX / Gebäudetechnik', 'Smart Home', 'TV/Medien', 'NAS/Server') { $rw.Type = $(if ($ir.Role -eq 'Router') { 'Router (weiterer)' } else { $ir.Role }) }
        if ($ir.SysName -and ([string]$rw.Name -match '^\(')) { $rw.Name = $ir.SysName }
        if ($ir.Model -and -not $rw.System) { $rw.System = $ir.Model }
    }
    $inv = Get-NdocInventory
    foreach ($rw in $rows) { $f = $inv[[string]$rw.Key]; foreach ($k in 'Room', 'Purpose', 'Owner', 'Note') { $rw | Add-Member -NotePropertyName $k -NotePropertyValue $(if ($f -and $f.$k) { [string]$f.$k } else { '' }) -Force } }
    $chk = @(); if ($X.Router) { $chk = @(Get-NtRouterChecklist $X.Router $NtOui | ForEach-Object { $_ }) }
    $exp = @(Get-NdocExposure $X $rows | ForEach-Object { $_ })
    $find = Get-NdocFindings $X $rows $chk $exp
    $diff = Compare-NdocSnapshot (Get-NdocLastSnapshot) $rows $find
    $rooms = @(Read-NdocJson 'wlan-raeume.json' @() | ForEach-Object { $_ } | Where-Object { $_ })
    $res = [pscustomobject]@{ Data = $X; Rows = $rows; Checks = $chk; Find = $find; Exposure = $exp; Diff = $diff; Rooms = $rooms }
    try { Save-NdocSnapshot $res } catch { }
    return $res
}
function Get-NdocMeta([string]$Title = '', [string]$Site = '', [string]$Author = '') {
    $set = Read-NdocJson 'einstellungen.json' $null
    if (-not $Title -and $set) { $Title = [string]$set.Title }; if (-not $Site -and $set) { $Site = [string]$set.Site }; if (-not $Author -and $set) { $Author = [string]$set.Author }
    $logo = ''
    if ($set -and $set.LogoPath -and (Test-Path -LiteralPath ([string]$set.LogoPath))) {
        try { $fi = Get-Item -LiteralPath ([string]$set.LogoPath); if ($fi.Length -lt 3MB) { $mime = switch -Regex ($fi.Extension) { '(?i)\.png$' { 'image/png' } '(?i)\.jpe?g$' { 'image/jpeg' } '(?i)\.gif$' { 'image/gif' } '(?i)\.svg$' { 'image/svg+xml' } default { 'image/png' } }; $logo = 'data:{0};base64,{1}' -f $mime, [Convert]::ToBase64String([IO.File]::ReadAllBytes($fi.FullName)) } } catch { }
    }
    $speed = @(); try { $speed = @(Read-NtSpeedHistory (Join-Path $DataDir 'speedtest.csv') | ForEach-Object { $_ } | Select-Object -Last 5) } catch { }
    [pscustomobject]@{ Title = $Title; Site = $Site; Author = $Author; AppVersion = $AppVersion; Speed = $speed; Ports = $NdocPorts; LogoData = $logo }
}
function New-NdocPdf($Res, $Meta, [string]$OutDir, $KnxMon = $null) {
    $html = ConvertTo-NdocHtml $Res.Data $Res.Rows $Res.Find $Res.Checks $Meta $NdocPortNames $Res.Exposure $Res.Diff $Res.Rooms $KnxMon
    New-Item -Path $OutDir -ItemType Directory -Force | Out-Null
    $out = Join-Path $OutDir ('Netzwerk-Dokumentation_{0}_{1:yyyy-MM-dd_HHmm}.pdf' -f (($(if ($Meta.Site) { $Meta.Site } else { $env:COMPUTERNAME })) -replace '[\\/:*?"<>|\s]+', '-'), $Res.Data.Time)
    return [pscustomobject]@{ Html = $html; Out = $out }
}
# ---- Automatische Erfassung (geplante Aufgabe "PC-Tools Netzwerk-Dokumentation", als SYSTEM, wöchentlich)
function Invoke-NdocAuto {
    $log = Join-Path (Join-Path $DataDir 'Logs') 'Netzwerk-Dokumentation.log'; New-Item (Split-Path $log) -ItemType Directory -Force | Out-Null
    $w = { param($t) Add-Content -LiteralPath $log -Value ('{0:yyyy-MM-dd HH:mm} {1}' -f (Get-Date), $t) -Encoding UTF8 }
    try {
        & $w 'Erfassung gestartet'
        $x = Invoke-NdocCollect $true $true $true $NdocPorts $NtTlsCode $null @{ Ext = $true }
        $res = Complete-NdocResult $x (Join-Path $DataDir 'netzgeraete.json')
        $pdf = New-NdocPdf $res (Get-NdocMeta) (Join-Path (Get-NdocDir) 'Berichte')
        $f = Convert-HtmlToPdf $pdf.Html $pdf.Out
        $sc = Get-NdocScore $res.Find
        & $w ('fertig: {0} Geräte, Note {1} ({2}), Bericht {3}' -f @($res.Rows).Count, $sc.Grade, $sc.Score, $f)
        $d = $res.Diff
        if ($d) {
            $msg = [System.Collections.Generic.List[string]]::new()
            if (@($d.NewDev).Count) { $msg.Add(('Neue Geräte: ' + ((@($d.NewDev) | ForEach-Object { '{0} ({1}, {2})' -f $_.Name, $_.Ip, $(if ($_.Vendor) { $_.Vendor } else { $_.Mac }) }) -join '; '))) }
            $nf = @($d.NewFind | Where-Object { $_.SevNo -le 3 }); if ($nf.Count) { $msg.Add(('Neue Schwachstellen: ' + ((@($nf) | ForEach-Object { '[{0}] {1} - {2}' -f $_.Sev, $_.Device, $_.Title }) -join '; '))) }
            if (@($d.PortsOpened).Count) { $msg.Add(('Neue offene Dienste: ' + ((@($d.PortsOpened) | ForEach-Object { '{0} ({1}): {2}' -f $_.Name, $_.Ip, $_.Ports }) -join '; '))) }
            if ($msg.Count) { $msg.Add(('Bewertung: {0} ({1}/100). Bericht: {2}' -f $sc.Grade, $sc.Score, $f)); try { $null = Send-PflegeNotify 'Netzwerk: Änderungen gefunden' ($msg -join "`n") $(if ($nf.Count) { 'Red' } else { 'Yellow' }) } catch { & $w ('Benachrichtigung fehlgeschlagen: ' + $_.Exception.Message) } }
        }
    } catch { & $w ('FEHLER: ' + $_.Exception.Message) }
}
function Register-NdocTask([bool]$On) {
    $tn = 'PC-Tools Netzwerk-Dokumentation'
    if (-not $On) { Unregister-ScheduledTask -TaskName $tn -Confirm:$false -ErrorAction SilentlyContinue; return 'Automatische Erfassung aus.' }
    $act = New-ScheduledTaskAction -Execute (Join-Path $env:SystemRoot 'System32\WindowsPowerShell\v1.0\powershell.exe') -Argument ('-NoProfile -ExecutionPolicy Bypass -WindowStyle Hidden -File "{0}" -NetDoc' -f (Join-Path $DataDir 'PCPflege.ps1'))
    $trg = New-ScheduledTaskTrigger -Weekly -DaysOfWeek Monday -At '12:17'
    $pr = New-ScheduledTaskPrincipal -UserId 'NT AUTHORITY\SYSTEM' -LogonType ServiceAccount -RunLevel Highest
    $set = New-ScheduledTaskSettingsSet -StartWhenAvailable -AllowStartIfOnBatteries -DontStopIfGoingOnBatteries -ExecutionTimeLimit (New-TimeSpan -Hours 1) -MultipleInstances IgnoreNew
    Register-ScheduledTask -TaskName $tn -Action $act -Trigger $trg -Principal $pr -Settings $set -Description 'PC-Tools: Netzwerk wöchentlich dokumentieren und bei neuen Geräten/Schwachstellen melden' -Force | Out-Null
    return 'Automatische Erfassung aktiv: jeden Montag (oder sobald der PC danach läuft).'
}
# ---- Netzwerk-Infrastruktur erkennen: Router, Firewalls, Switches, Access Points, WLAN-Controller, Repeater
# SNMP v2c (nur lesend, Standard-Community "public") - BER-Kodierung ohne Fremdbibliothek
function New-NdocSnmpGet([int]$ReqId, [string]$Community = 'public') {
    $tlv = { param([byte]$t, [byte[]]$v) $l = $v.Length; if ($l -lt 128) { [byte[]](@($t, $l) + @($v)) } else { [byte[]](@($t, 0x81, $l) + @($v)) } }
    $vbs = [System.Collections.Generic.List[byte]]::new()
    foreach ($x in 1, 2, 3, 4, 5, 6) { $oid = [byte[]](0x2B, 6, 1, 2, 1, 1, $x, 0); $vb = & $tlv 0x30 ([byte[]](@(& $tlv 0x06 $oid) + @(0x05, 0x00))); $vbs.AddRange([byte[]]$vb) }
    $rid = [BitConverter]::GetBytes([int]$ReqId); [Array]::Reverse($rid)
    $pdu = & $tlv 0xA0 ([byte[]](@(& $tlv 0x02 $rid) + @(0x02, 1, 0) + @(0x02, 1, 0) + @(& $tlv 0x30 $vbs.ToArray())))
    return (& $tlv 0x30 ([byte[]](@(0x02, 1, 1) + @(& $tlv 0x04 ([Text.Encoding]::ASCII.GetBytes($Community))) + @($pdu))))
}
function ConvertFrom-NdocSnmp([byte[]]$B) {
    $out = @{}
    $read = $null
    $read = {
        param([int]$o, [int]$end, [int]$depth)
        $vals = [System.Collections.Generic.List[object]]::new()
        while ($o -lt $end -and $o + 1 -lt $B.Length) {
            $t = $B[$o]; $l = [int]$B[$o + 1]; $h = 2
            if ($l -band 0x80) { $n = $l -band 0x7F; $l = 0; for ($i = 0; $i -lt $n; $i++) { $l = $l * 256 + $B[$o + 2 + $i] }; $h = 2 + $n }
            $s = $o + $h; $e = [math]::Min($s + $l, $B.Length)
            if ($t -eq 0x30 -or ($t -band 0xE0) -eq 0xA0) { $vals.Add([pscustomobject]@{ T = $t; C = (& $read $s $e ($depth + 1)) }) }
            else { $vals.Add([pscustomobject]@{ T = $t; S = $s; L = ($e - $s) }) }
            $o = $e
        }
        return , $vals
    }
    $top = & $read 0 $B.Length 0
    $walk = $null
    $walk = { param($nodes) foreach ($n in $nodes) { if ($n.C) { if ($n.T -eq 0x30 -and $n.C.Count -eq 2 -and $n.C[0].T -eq 0x06) { $v = $n.C[1]; $oid = (($B[$n.C[0].S..($n.C[0].S + $n.C[0].L - 1)]) -join '.'); $val = switch ($v.T) { 0x04 { [Text.Encoding]::UTF8.GetString($B, $v.S, $v.L) } 0x06 { $a = $B[$v.S..($v.S + $v.L - 1)]; $parts = @([int]($a[0] / 40), [int]($a[0] % 40)); $acc = 0; for ($i = 1; $i -lt $a.Count; $i++) { $acc = $acc * 128 + ($a[$i] -band 0x7F); if (-not ($a[$i] -band 0x80)) { $parts += $acc; $acc = 0 } }; $parts -join '.' } 0x43 { $acc = [long]0; for ($i = 0; $i -lt $v.L; $i++) { $acc = $acc * 256 + $B[$v.S + $i] }; $acc } default { $null } }; $out[$oid] = $val } else { & $walk $n.C } } } }
    & $walk $top
    $g = { param($x) $out[('43.6.1.2.1.1.{0}.0' -f $x)] }
    if (-not $out.Count) { return $null }
    [pscustomobject]@{ Descr = ([string](& $g 1)).Trim(); ObjectId = [string](& $g 2); Uptime = (& $g 3); Contact = [string](& $g 4); Name = [string](& $g 5); Location = [string](& $g 6) }
}
function Invoke-NdocSnmpScan([string[]]$Ips, [int]$Ms = 2500) {
    $res = @{}; $u = $null
    try {
        $u = New-Object Net.Sockets.UdpClient; $u.Client.ReceiveTimeout = 300
        $k = 0; foreach ($ip in $Ips) { $k++; $pk = New-NdocSnmpGet (4000 + $k); try { [void]$u.Send($pk, $pk.Length, $ip, 161) } catch { } }
        $end = (Get-Date).AddMilliseconds($Ms)
        while ((Get-Date) -lt $end) {
            $ep = New-Object Net.IPEndPoint([Net.IPAddress]::Any, 0)
            try { $b = $u.Receive([ref]$ep) } catch { continue }
            try { $p = ConvertFrom-NdocSnmp $b; if ($p) { $res[[string]$ep.Address] = $p } } catch { }
        }
    } catch { } finally { if ($u) { $u.Close() } }
    return $res
}
# Weg ins Internet (erste Hops) - erkennt zweite Router und Doppel-NAT
function Get-NdocTraceHops([string]$Target = '8.8.8.8', [int]$Max = 4) {
    $p = New-Object System.Net.NetworkInformation.Ping; $hops = [System.Collections.Generic.List[object]]::new()
    for ($t = 1; $t -le $Max; $t++) {
        $o = New-Object System.Net.NetworkInformation.PingOptions($t, $true); $ip = ''; $ms = -1
        try { $r = $p.Send($Target, 1500, (New-Object byte[] 32), $o); if ($r.Address) { $ip = [string]$r.Address; $ms = [int]$r.RoundtripTime } } catch { }
        $hops.Add([pscustomobject]@{ Hop = $t; Ip = $ip; Ms = $ms; Private = [bool]($ip -match '^(10\.|192\.168\.|172\.(1[6-9]|2\d|3[01])\.|100\.(6[4-9]|[7-9]\d|1[01]\d|12[0-7])\.)') })
        if ($ip -eq $Target) { break }
    }
    return $hops.ToArray()
}
function Get-NdocInfra($Devices, $Net) {
    $ips = @($Devices | Where-Object { $_ -and $_.Via -ne 'Dieser PC' } | ForEach-Object { [string]$_.Ip })
    $snmp = @{}; try { $snmp = Invoke-NdocSnmpScan $ips } catch { }
    $hops = @(); try { $hops = @(Get-NdocTraceHops) } catch { }
    [pscustomobject]@{ Snmp = $snmp; Hops = $hops }
}
# Einordnung (UI-Thread): Infrastruktur-Rolle, Hersteller/Modell, Verwaltungszugang, Funknetze
$NdocEnterprise = @{ '9' = 'Cisco'; '11' = 'HP'; '25506' = 'H3C/HPE'; '14988' = 'MikroTik'; '41112' = 'Ubiquiti'; '4526' = 'Netgear'; '11863' = 'TP-Link'; '890' = 'Zyxel'; '2356' = 'LANCOM'; '12356' = 'Fortinet'; '14823' = 'Aruba'; '25053' = 'Ruckus'; '29671' = 'Cisco Meraki'; '8072' = 'Linux (net-snmp)'; '311' = 'Microsoft'; '6574' = 'Synology'; '24681' = 'QNAP'; '2011' = 'Huawei'; '4413' = 'Broadcom'; '171' = 'D-Link'; '674' = 'Dell'; '2636' = 'Juniper'; '21067' = 'Sophos'; '12325' = 'pfSense/FreeBSD'; '17713' = 'Cambium'; '10002' = 'Ubiquiti (Frogfoot)'; '1916' = 'Extreme'; '1991' = 'Brocade'; '3955' = 'Linksys'; '4458' = 'Grandstream'; '26928' = 'Allied Telesis'; '207' = 'Allied Telesis'; '6486' = 'Nokia/Alcatel'; '5624' = 'Enterasys'; '30065' = 'Arista'; '8691' = 'Moxa'; '1588' = 'Brocade'; '11898' = 'Peplink'; '12148' = 'Eltek'; '43356' = 'Teltonika'; '48690' = 'Teltonika'; '3224' = 'Juniper NetScreen'; '8741' = 'SonicWall'; '3097' = 'WatchGuard'; '37720' = 'Securepoint' }
$NdocInfraRules = @(
    @{ Role = 'Firewall'; Rx = '(?i)pfsense|opnsense|sophos|fortigate|fortinet|sonicwall|watchguard|securepoint|zywall|usg ?flex|zyxel usg|checkpoint|check point|palo ?alto|untangle|ipfire|endian|stormshield|barracuda|gateprotect|lancom.*(unified|r&s)|r&s.*unified' }
    @{ Role = 'WLAN-Controller'; Rx = '(?i)unifi (network|controller|os)|omada (controller|software)|wireless lan controller|wlc\b|aruba (mobility|central)|ruckus (smartzone|zonedirector|virtual)|meraki dashboard|lancom.*(wlc|wlan controller)|cloud key' }
    @{ Role = 'Access Point'; Rx = '(?i)access ?point|\buap\b|uap-|\bu6[- ]|\bu7[- ]|unifi ap|\beap ?\d|omada eap|aruba instant|\biap-?\d|\bap-?\d{3}|ruckus r\d|cambium.*e\d|grandstream gwn|lancom (l|ln|lw|ow)-\d|zyxel (nwa|wax|wac)|netgear wac|wax\d|engenius|mikrotik (cap|wap)|\bcap ac|\bwap ac|fritz!repeater|fritzrepeater|tp-link (eap|re\d)|devolo|powerline|repeater|deco\b|eero|orbi|velop|aimesh|mesh node' }
    @{ Role = 'Switch'; Rx = '(?i)\bswitch\b|procurve|aruba ?\d{4}|catalyst|nexus|gs1\d\d|gs3\d\d|gs7\d\d|gs\d{3,4}(tp|p|e)?\b|sg\d{3}|sg ?300|tl-sg|tl-sx|netgear gs|xs\d{3}|usw-|unifi switch|us-\d+|cbs\d{3}|sx\d{3}|crs\d{3}|css\d{3}|dgs-|dxs-|powerconnect|edgeswitch|zyxel (gs|xgs|xs)|lancom gs|omada.*(sg|tl-sg)|hpe officeconnect|1920s|1820|1810|ex\d{4}' }
    @{ Role = 'Router'; Rx = '(?i)routeros|mikrotik|routerboard|openwrt|luci|dd-wrt|tomato|asuswrt|merlin|edgerouter|edgeos|vyos|draytek|vigor|speedport|vodafone station|easybox|connect ?box|o2 ?homespot|o2 box|huawei.*(hg|b\d{3}|e\d{4})|zte|sagemcom|technicolor|fritz!box|fritzbox|router|gateway|teltonika|rut\d{3}|peplink|lancom (1\d{3}|17\d\d|19\d\d|7\d{3})|cisco (isr|rv\d)|bintec|be\.ip|digitalisierungsbox|dream machine|\budm\b|usg\b|unifi gateway|ucg|er-x|omada (er|router)|tl-er|zyxel (vmg|lte|nr)|starlink|5g router|lte router|cudy|glinet|gl\.inet' }
)
function Get-NdocInfraRole($Row, $WebInfo, $Snmp, $Smart, $WlanNets) {
    $p = @($Row.PortList); $v = [string]$Row.Vendor
    $txt = @([string]$Row.Host, [string]$Row.Name, $(if ($WebInfo) { $WebInfo.Title + ' ' + $WebInfo.Server }), $(if ($Snmp) { $Snmp.Descr + ' ' + $Snmp.Name }), $(if ($Smart -and $Smart.Ssdp[[string]$Row.Ip]) { $sd = $Smart.Ssdp[[string]$Row.Ip]; $sd.Server + ' ' + $sd.Friendly + ' ' + $sd.Maker + ' ' + $sd.Model + ' ' + (@($sd.Types) -join ' ') })) -join ' '
    $role = ''; $why = ''
    foreach ($r in $NdocInfraRules) { if ($txt -match $r.Rx) { $role = $r.Role; $why = $Matches[0]; break } }
    if (-not $role -and $Smart -and $Smart.Ssdp[[string]$Row.Ip]) { $ty = @($Smart.Ssdp[[string]$Row.Ip].Types) -join ' '; if ($ty -match 'InternetGatewayDevice') { $role = 'Router'; $why = 'UPnP-Internet-Gateway' } elseif ($ty -match 'WFADevice|WLANAccessPoint') { $role = 'Access Point'; $why = 'UPnP-WLAN-Gerät' } }
    if (-not $role -and ($p -contains 8291 -or $p -contains 8728)) { $role = 'Router'; $why = 'MikroTik Winbox/API' }
    if (-not $role -and ($p -contains 8043)) { $role = 'WLAN-Controller'; $why = 'Omada (8043)' }
    if (-not $role -and ($p -contains 4433 -or $p -contains 10443)) { $role = 'Firewall'; $why = 'Firewall-Verwaltung' }
    # BSSID nahe an der eigenen MAC = dieses Gerät funkt das WLAN aus
    $ssids = @()
    if ($Row.Mac -and @($WlanNets).Count) {
        $m = ([string]$Row.Mac -replace ':', ''); if ($m.Length -eq 12) {
            $base = [Convert]::ToInt64($m.Substring(6), 16); $pre = $m.Substring(0, 6)
            foreach ($n in @($WlanNets)) { $bm = ([string]$n.Bssid -replace ':', ''); if ($bm.Length -ne 12) { continue }
                $bp = $bm.Substring(0, 6); $bb = [Convert]::ToInt64($bm.Substring(6), 16)
                $pre2 = ([Convert]::ToInt32($bp.Substring(0, 2), 16) -band 0xFD).ToString('X2') + $bp.Substring(2)   # lokal verwaltete Variante (Bit 1) gleichsetzen
                $preM = ([Convert]::ToInt32($pre.Substring(0, 2), 16) -band 0xFD).ToString('X2') + $pre.Substring(2)
                if (($bp -eq $pre -or $pre2 -eq $preM) -and [math]::Abs($bb - $base) -le 24) { $ssids += ('{0} ({1}, Kanal {2})' -f $n.Ssid, $n.Band, $n.Channel) } }
        }
    }
    if ($ssids.Count -and $role -notin 'Router', 'Firewall') { $role = 'Access Point'; if (-not $why) { $why = 'sendet WLAN (BSSID passt zur MAC)' } }
    if (-not $role -and $Snmp -and $Snmp.ObjectId -match '^1\.3\.6\.1\.4\.1\.(\d+)') { $en = $Matches[1]; if ($en -in '9', '11', '25506', '4526', '11863', '890', '2356', '14823', '171', '674', '2636', '1916', '30065', '26928', '207', '1991') { $role = 'Switch'; $why = 'SNMP-Netzwerkgerät' } }
    if (-not $role -and $v -match '(?i)ubiquiti|mikrotik|routerboard|lancom|ruckus|aruba|meraki|cambium|engenius|juniper|fortinet|sophos|watchguard|sonicwall|peplink|teltonika|draytek') { $role = 'Netzwerkgerät'; $why = 'Hersteller' }
    $model = ''
    if ($Snmp -and $Snmp.Descr) { $model = ($Snmp.Descr -split "`r?`n")[0] }
    elseif ($Smart -and $Smart.Ssdp[[string]$Row.Ip] -and $Smart.Ssdp[[string]$Row.Ip].Model) { $model = ('{0} {1}' -f $Smart.Ssdp[[string]$Row.Ip].Maker, $Smart.Ssdp[[string]$Row.Ip].Model).Trim() }
    elseif ($WebInfo -and $WebInfo.Title) { $model = $WebInfo.Title }
    $mg = @(); foreach ($x in @(@(443, 'https'), @(8443, 'https:8443'), @(80, 'http'), @(22, 'SSH'), @(23, 'Telnet'), @(8291, 'Winbox'), @(8043, 'Omada'), @(4433, 'https:4433'), @(10443, 'https:10443'))) { if ($p -contains $x[0]) { $mg += $x[1] } }
    if ($Snmp) { $mg += 'SNMP (public)' }
    $vendorTxt = if ($Snmp -and $Snmp.ObjectId -match '^1\.3\.6\.1\.4\.1\.(\d+)' -and $NdocEnterprise[$Matches[1]]) { $NdocEnterprise[$Matches[1]] } else { $v }
    [pscustomobject]@{ Role = $role; Why = $why; Model = $model; Vendor = $vendorTxt; Mgmt = ($mg -join ', '); Ssids = (@($ssids | Select-Object -Unique) -join '; '); Location = $(if ($Snmp) { $Snmp.Location } else { '' }); Contact = $(if ($Snmp) { $Snmp.Contact } else { '' }); SysName = $(if ($Snmp) { $Snmp.Name } else { '' }); Uptime = $(if ($Snmp -and $Snmp.Uptime) { '{0:N0} Tage' -f ([double]$Snmp.Uptime / 8640000) } else { '' }) }
}
# ---- Aufbereitung (UI-Thread, reine Datenverarbeitung)
function Get-NdocSystemText($Row, $Sm) {
    if (-not $Sm) { return '' }
    $t = [System.Collections.Generic.List[string]]::new()
    foreach ($it in @($Sm.Items | Where-Object { $_.Ip -eq $Row.Ip })) { $t.Add(([string]$it.System + $(if ($it.Model) { ' ' + $it.Model } else { '' })).Trim()) }
    $sd = $Sm.Ssdp[[string]$Row.Ip]; if ($sd -and ($sd.Friendly -or $sd.Model)) { $t.Add((@($sd.Friendly, $(if ($sd.Maker -or $sd.Model) { '(' + (($sd.Maker + ' ' + $sd.Model).Trim()) + ')' })) | Where-Object { $_ }) -join ' ') }
    $md = $Sm.Mdns[[string]$Row.Ip]
    if ($md -and @($md.Services).Count) {
        $map = [ordered]@{ '_hap' = 'HomeKit'; '_matter' = 'Matter'; '_meshcop' = 'Thread'; '_hue' = 'Hue'; '_shelly' = 'Shelly'; '_esphomelib' = 'ESPHome'; '_googlecast' = 'Chromecast'; '_airplay' = 'AirPlay'; '_sonos' = 'Sonos'; '_spotify' = 'Spotify Connect'; '_ipp' = 'Drucker (IPP)'; '_scanner' = 'Scanner'; '_smb' = 'Dateifreigabe'; '_home-assistant' = 'Home Assistant'; '_mqtt' = 'MQTT'; '_miio' = 'Xiaomi'; '_wled' = 'WLED'; '_amzn' = 'Amazon'; '_ssh' = 'SSH' }
        $sv = @($md.Services) -join ' '; $hit = @($map.Keys | Where-Object { $sv -match [regex]::Escape($_) } | ForEach-Object { $map[$_] })
        $nm = @($md.Names | Select-Object -First 1)
        if ($hit.Count -or $nm.Count) { $t.Add(((@($nm) + @('[' + ($hit -join ', ') + ']')) | Where-Object { $_ -and $_ -ne '[]' }) -join ' ') }
    }
    return ((@($t) | Select-Object -Unique) -join ' · ')
}
function Get-NdocDevType($Row, $WebInfo, $Sm = $null) {
    $p = @($Row.PortList); $v = [string]$Row.Vendor; $h = ([string]$Row.Host + ' ' + [string]$Row.Name + ' ' + $(if ($WebInfo) { $WebInfo.Title + ' ' + $WebInfo.Server } else { '' }))
    if ($Row.Gateway) { return 'Router' }
    if ($Row.Self) { return 'PC (dieser)' }
    if ($Sm) {
        if (@($Sm.Knx | Where-Object { $_.Ip -eq $Row.Ip }).Count) { return 'KNX / Gebäudetechnik' }
        $its = @($Sm.Items | Where-Object { $_.Ip -eq $Row.Ip -and $_.System -notin 'MQTT-Broker' })
        if ($its.Count) { return 'Smart Home' }
        $md = $Sm.Mdns[[string]$Row.Ip]; $sv = if ($md) { @($md.Services) -join ' ' } else { '' }
        $sd = $Sm.Ssdp[[string]$Row.Ip]; $ss = if ($sd) { ($sd.Server + ' ' + (@($sd.Types) -join ' ') + ' ' + $sd.Maker + ' ' + $sd.Model) } else { '' }
        if ($sv -match '_ipp|_printer|_pdl|_scanner' -or $ss -match '(?i)printer|Print') { return 'Drucker' }
        if ($sv -match '_hap|_homekit|_matter|_hue|_shelly|_esphome|_miio|_aqara|_ewelink|_wled|_nanoleaf|_elg|_meshcop') { return 'Smart Home' }
        if ($sv -match '_googlecast|_airplay|_raop|_sonos|_spotify|_amzn' -or $ss -match '(?i)MediaRenderer|sonos|webos|tizen|roku|dial-multiscreen') { return 'TV/Medien' }
    }
    if ($h -match '(?i)fritz.*repeater|repeater|mesh|access ?point|unifi|deco|eero|orbi') { return 'Repeater/Access Point' }
    if ($p -contains 9100 -or $p -contains 631 -or $p -contains 515 -or $v -match '(?i)brother|epson|canon|kyocera|lexmark|ricoh|xerox|konica|oki ' -or $h -match '(?i)printer|drucker|laserjet|officejet') { return 'Drucker' }
    if ($p -contains 5000 -or $p -contains 5001 -or $p -contains 548 -or $p -contains 2049 -or $v -match '(?i)synology|qnap|western digital|buffalo|asustor' -or $h -match '(?i)\bnas\b|diskstation|unraid|truenas|openmediavault') { return 'NAS/Server' }
    if ($p -contains 554 -or $v -match '(?i)hikvision|dahua|reolink|axis|foscam|ubiquiti.*cam|amcrest|annke' -or $h -match '(?i)camera|kamera|ipcam|nvr') { return 'Kamera/NVR' }
    if ($p -contains 8123 -or $p -contains 1883 -or $p -contains 1880 -or $p -contains 6053 -or $p -contains 2001 -or $p -contains 2010 -or $v -match '(?i)shelly|espressif|tuya|sonoff|tasmota|philips lighting|signify|homematic|eq-3|tado|ecobee|nest' -or $h -match '(?i)home ?assistant|shelly|tasmota|hue|zigbee') { return 'Smart Home' }
    if ($p -contains 8008 -or $p -contains 8009 -or $p -contains 7000 -or $p -contains 32400 -or $v -match '(?i)samsung electronics|lg electronics|sony|roku|amazon|google|apple tv|sonos|panasonic|philips|tcl|hisense|nvidia' -or $h -match '(?i)tv|chromecast|fire|sonos|appletv|plex|kodi') { return 'TV/Medien' }
    if ($p -contains 2375 -or $p -contains 9443 -or $p -contains 10000 -or $p -contains 3306 -or $p -contains 5432 -or $p -contains 27017) { return 'Server' }
    if ($p -contains 3389 -or $p -contains 135 -or ($p -contains 445 -and $p -contains 139)) { return 'Windows-PC' }
    if ($p -contains 22) { return 'Linux/Server' }
    if ($v -match '(?i)^Zufällige' -or $v -match '(?i)apple|samsung|xiaomi|huawei|oneplus|oppo|motorola|google') { return 'Smartphone/Tablet' }
    if ($v -match '(?i)intel|realtek|dell|lenovo|hewlett|hp inc|asus|micro-star|gigabyte|microsoft|liteon|azurewave') { return 'PC/Notebook' }
    if ($v -match '(?i)avm|tp-link|netgear|zyxel|d-link|cisco|juniper|mikrotik|ubiquiti|lancom') { return 'Netzwerkgerät' }
    return 'Unbekannt'
}
function Get-NdocFindings($Data, $Rows, $RouterChecks, $Exposure = @()) {
    $f = [System.Collections.Generic.List[object]]::new()
    $add = { param($sev, $dev, $title, $detail, $fix) $f.Add([pscustomobject]@{ SevNo = $sev; Sev = @('', 'Kritisch', 'Hoch', 'Mittel', 'Niedrig', 'Info')[$sev]; Device = $dev; Title = $title; Detail = $detail; Fix = $fix }) }
    foreach ($r in @($Rows)) {
        $dn = '{0} ({1})' -f $r.Name, $r.Ip; $p = @($r.PortList); if ($r.Self -or $r.Offline) { continue }
        if ($p -contains 2375) { & $add 1 $dn 'Docker-API ohne Schutz erreichbar (Port 2375)' 'Wer diesen Port erreicht, kann auf dem Gerät beliebige Container starten und es komplett übernehmen.' 'Port 2375 schließen (nur lokal/Socket nutzen) oder TLS mit Zertifikaten (2376) einrichten.' }
        if ($p -contains 23) { & $add 2 $dn 'Telnet offen (Port 23)' 'Telnet überträgt Anmeldedaten unverschlüsselt und ist ein bevorzugtes Ziel für Angriffe (z.B. Mirai-Botnetz).' 'Telnet im Gerät abschalten, stattdessen SSH oder die Weboberfläche nutzen; Firmware aktualisieren.' }
        if ($p -contains 5900) { & $add 2 $dn 'VNC-Fernsteuerung offen (Port 5900)' 'VNC ist oft nur mit einem kurzen Kennwort oder gar nicht geschützt und überträgt unverschlüsselt.' 'VNC abschalten, wenn nicht genutzt; sonst starkes Kennwort und nur über VPN.' }
        foreach ($db in @(@(6379, 'Redis'), @(27017, 'MongoDB'), @(9200, 'Elasticsearch'), @(3306, 'MySQL/MariaDB'), @(5432, 'PostgreSQL'), @(1433, 'SQL Server'))) { if ($p -contains $db[0]) { & $add 3 $dn ('Datenbank {0} im Netz erreichbar (Port {1})' -f $db[1], $db[0]) 'Datenbanken sollten nur für die Programme erreichbar sein, die sie brauchen. Redis/MongoDB/Elasticsearch sind ohne Konfiguration oft ganz ohne Kennwort.' 'An localhost binden oder per Firewall auf die nötigen Rechner beschränken; Kennwort/Benutzerverwaltung aktivieren.' } }
        if ($p -contains 21) { & $add 3 $dn 'FTP offen (Port 21)' 'FTP überträgt Kennwörter und Daten unverschlüsselt.' 'FTP abschalten und SFTP/SMB/https nutzen.' }
        if ($p -contains 3389) { & $add 4 $dn 'Remotedesktop offen (Port 3389)' 'Im eigenen Netz in Ordnung, wenn gewollt. Darf nie direkt ins Internet freigegeben sein.' 'Prüfen, ob gewollt; Netzwerkebenen-Authentifizierung (NLA) und starke Kennwörter; Zugriff von außen nur per VPN.' }
        if ($p -contains 10000) { & $add 3 $dn 'Webmin-Verwaltung erreichbar (Port 10000)' 'Webmin hat volle Root-Rechte über das Gerät und hatte mehrfach kritische Lücken.' 'Aktuell halten, nur aus dem Verwaltungsnetz erreichbar machen, 2FA einschalten.' }
        if ($p -contains 554) { & $add 4 $dn 'Kamera-Stream im Netz (RTSP, Port 554)' 'Viele Kameras liefern den Stream mit Standard-Zugangsdaten oder ohne Anmeldung.' 'Eigenes starkes Kennwort setzen, Firmware aktualisieren, Kamera nicht per Portfreigabe ins Internet stellen (UPnP prüfen).' }
        if ($p -contains 1883) { & $add 4 $dn 'MQTT unverschlüsselt (Port 1883)' 'Smart-Home-Nachrichten und ggf. Zugangsdaten gehen im Klartext durchs Netz.' 'Benutzer/Kennwort am Broker erzwingen, wenn möglich MQTT über TLS (8883).' }
        if ((@($p | Where-Object { $_ -in 80, 81, 8080 }).Count) -and -not (@($p | Where-Object { $_ -in 443, 8443, 5001, 9443 }).Count) -and ($r.Type -in 'Router', 'Router (weiterer)', 'Firewall', 'Switch', 'Access Point', 'WLAN-Controller', 'NAS/Server', 'Kamera/NVR', 'Drucker', 'Netzwerkgerät', 'Repeater/Access Point', 'Server')) { & $add 4 $dn 'Verwaltung nur über unverschlüsseltes http' 'Das Kennwort der Weboberfläche geht im Klartext durchs Netz.' 'In den Geräteeinstellungen https einschalten bzw. erzwingen.' }
        if ($r.IsNew) { & $add 3 $dn 'Neues Gerät seit der letzten Erfassung' ('Hersteller: {0}' -f $(if ($r.Vendor) { $r.Vendor } else { 'unbekannt' })) 'Prüfen, ob das Gerät bekannt ist. Unbekannte Geräte im Router sperren und das WLAN-Kennwort ändern.' }
        elseif ($r.Type -eq 'Unbekannt' -and -not $r.Host) { & $add 5 $dn 'Gerät nicht zuzuordnen' ('MAC {0}, Hersteller {1}' -f $r.Mac, $(if ($r.Vendor) { $r.Vendor } else { 'unbekannt' })) 'In den Netzwerk-Werkzeugen einen Namen vergeben, damit es in späteren Berichten erkennbar ist.' }
    }
    foreach ($c in @($RouterChecks)) {
        if ([string]$c.Title -like 'UPnP:*' -and $Data.Router -and $Data.Router.Upnp -and @($Data.Router.Upnp.Maps).Count) { continue }
        if ($c.Level -eq 'Bad') { & $add 2 'Router' $c.Title $c.Detail 'Wie im Befund beschrieben in der Router-Oberfläche beheben.' }
        elseif ($c.Level -eq 'Warn') { & $add 3 'Router' $c.Title $c.Detail 'Wie im Befund beschrieben in der Router-Oberfläche prüfen.' }
    }
    foreach ($x in @($Exposure | Where-Object { $_.SevNo -le 4 -and $_.Way -notin 'Anschlussart', 'IPv6', 'Shodan InternetDB' })) {
        $fx = if ($x.Way -like 'Portfreigabe*') { 'Freigabe in der FRITZ!Box unter Internet > Freigaben entfernen bzw. für dieses Gerät "Selbstständige Portfreigaben erlauben" ausschalten; Fernzugriff besser per VPN (WireGuard).' } elseif ($x.Way -like 'Laut Shodan*') { 'Herausfinden, welches Gerät dahinter steckt (Portfreigaben), Freigabe schließen oder das Gerät aktualisieren.' } else { $x.Hint }
        & $add $x.SevNo ('Internet -> ' + $x.Target) ('Von außen erreichbar: ' + $x.Service) ('{0}, extern {1}. {2}' -f $x.Way, $x.External, $x.Hint) $fx
    }
    $snmpOpen = @($Rows | Where-Object { $_.Infra -and $_.Infra.Mgmt -match 'SNMP' })
    if ($snmpOpen.Count) { & $add 3 'Netzwerk-Infrastruktur' ('{0} Gerät(e) mit SNMP-Standardzugang "public"' -f $snmpOpen.Count) (((@($snmpOpen) | ForEach-Object { '{0} ({1})' -f ($_.Name -replace '\s+\[.*$', ''), $_.Ip }) -join ', ') + '. SNMP v1/v2c ist unverschlüsselt; mit der Standard-Community kann jeder im Netz Konfiguration, Schnittstellen und oft auch ARP-/MAC-Tabellen auslesen.') 'Community auf ein langes, geheimes Wort ändern oder SNMP abschalten; besser SNMPv3 mit Benutzer und Verschlüsselung, Zugriff per ACL auf den Monitoring-Server beschränken.' }
    foreach ($r in @($Rows | Where-Object { $_.Type -eq 'Router (weiterer)' })) { & $add 4 ('{0} ({1})' -f ($r.Name -replace '\s+\[.*$', ''), $r.Ip) 'Weiterer Router im Netz' ('Erkannt als Router ({0}). Ein zweiter Router kann ein eigenes Netz mit eigenem DHCP aufspannen (Doppel-NAT, Geräte nicht erreichbar) oder ungewollt ein Hintertürchen sein.' -f $r.Infra.Why) 'Prüfen, ob gewollt; als Access Point/Bridge betreiben (DHCP aus) oder dokumentieren, welche Geräte dahinter hängen.' }
    if ($Data.Infra -and @($Data.Infra.Hops).Count -ge 2) { $hp = @($Data.Infra.Hops); if ($hp[0].Private -and $hp[1].Ip -and $hp[1].Private -and $hp[1].Ip -notmatch '^100\.') { & $add 4 'Weg ins Internet' ('Doppel-NAT: zweiter Router {0} hinter {1}' -f $hp[1].Ip, $hp[0].Ip) 'Der Datenverkehr läuft durch zwei Router mit Adressumsetzung. Portfreigaben, VPN und Telefonie (SIP) funktionieren dann oft nicht oder nur eingeschränkt.' 'Den inneren Router als "IP-Client"/Bridge betreiben oder den äußeren Router in den Modem-/Bridge-Modus stellen; sonst Freigaben in beiden Routern pflegen.' } }
    $fb = $Data.Fritz
    if ($fb) {
        if ($fb.Update -and $fb.Update['NewUpgradeAvailable'] -eq '1') { & $add 2 'FRITZ!Box' ('FRITZ!OS-Update verfügbar ({0})' -f $fb.Update['NewX_AVM-DE_Version']) 'Neue FRITZ!OS-Versionen schließen Sicherheitslücken.' 'System > Update > "Neues FRITZ!OS suchen" und installieren; unter "Auto-Update" automatische Updates einschalten.' }
        foreach ($wn in @($fb.Wlan | Where-Object { $_.Enabled })) {
            if ($wn.Wps -and $wn.Wps -notin 'off', 'stop', '') { & $add 3 ('WLAN ' + $wn.Ssid) ('WPS-Schnellverbindung eingeschaltet ({0})' -f $wn.Wps) 'Besonders WPS-PIN ist angreifbar.' 'WLAN > Sicherheit > WPS-Schnellverbindung ausschalten (bei Bedarf kurz per Taste nutzen).' }
            if ($wn.Beacon -in 'None', 'Basic') { if ($wn.Guest) { & $add 4 ('WLAN ' + $wn.Ssid) 'Gast-WLAN ohne Verschlüsselung (Hotspot)' 'Gäste-Datenverkehr ist mitlesbar.' 'Gastzugang mit WPA2/WPA3 und Kennwort betreiben.' } else { & $add 1 ('WLAN ' + $wn.Ssid) 'Funknetz ohne Verschlüsselung' 'Jeder in Reichweite kann ins Heimnetz.' 'WLAN > Sicherheit: WPA2 + WPA3 einstellen.' } }
            elseif ($wn.Beacon -eq 'WPAand11i' -or $wn.Beacon -eq 'WPA') { & $add 4 ('WLAN ' + $wn.Ssid) 'Altes WPA (TKIP) noch erlaubt' 'WPA1/TKIP ist veraltet und bremst.' 'WLAN > Sicherheit: "WPA2 + WPA3" wählen.' }
        }
        if (-not @($fb.Wlan | Where-Object { $_.Guest -and $_.Enabled }).Count -and $Data.Smart -and (@($Data.Smart.Items).Count + @($Data.Smart.Knx).Count) -ge 3) { & $add 5 'FRITZ!Box' 'Kein Gast-/IoT-WLAN aktiv' 'Smart-Home-Geräte und Gäste teilen sich das Netz mit PCs und NAS.' 'WLAN > Gastzugang einschalten und Smart-Home-Geräte dorthin umziehen (sofern sie keine lokale Zentrale im Heimnetz brauchen).' }
        if ($fb.Upnp -and $fb.Upnp['NewEnable'] -eq '1') { & $add 5 'FRITZ!Box' 'UPnP-Statusinformationen aktiv' 'Geräte können per UPnP Infos lesen; Portfreigaben per UPnP sind zusätzlich je Gerät einstellbar.' 'Internet > Freigaben: "Selbstständige Portfreigaben" nur für Geräte erlauben, die es brauchen (z.B. Spielkonsole).' }
        $blk = @($fb.Hosts | Where-Object { $_.Blocked }); if ($blk.Count) { & $add 5 'FRITZ!Box' ('{0} Gerät(e) gesperrt' -f $blk.Count) ((@($blk) | ForEach-Object { $_.Name }) -join ', ') 'Zur Information.' }
    }
    if ($Data.FritzErr) { & $add 5 'FRITZ!Box' 'FRITZ!Box-Anmeldung fehlgeschlagen' $Data.FritzErr 'Benutzer/Kennwort prüfen; in der FRITZ!Box muss "Zugriff für Anwendungen zulassen" (Heimnetz > Netzwerk > Netzwerkeinstellungen) an sein.' }
    $ha = $Data.Ha
    if ($ha) {
        $core = @($ha.Updates | Where-Object { $_.Core }); if ($core.Count) { & $add 3 ('Home Assistant ' + $ha.Version) 'Home-Assistant-Update verfügbar' ((@($core) | ForEach-Object { '{0}: {1} -> {2}' -f $_.Name, $_.Installed, $_.Latest }) -join '; ') 'Einstellungen > System > Updates (vorher Sicherung erstellen).' }
        $oth = @($ha.Updates | Where-Object { -not $_.Core }); if ($oth.Count) { & $add 4 'Home Assistant' ('{0} weitere Updates (Add-ons, Integrationen, Geräte-Firmware)' -f $oth.Count) ((@($oth) | Select-Object -First 12 | ForEach-Object { $_.Name }) -join ', ') 'In Home Assistant unter Einstellungen > Updates installieren.' }
        if ($ha.UnavailCount -ge 10) { & $add 5 'Home Assistant' ('{0} Entitäten nicht verfügbar' -f $ha.UnavailCount) ((@($ha.Unavailable) | Select-Object -First 12) -join ', ') 'Ausgefallene Geräte/Integrationen prüfen oder entfernen.' }
        if (@($ha.LowBattery).Count) { & $add 5 'Home Assistant' ('{0} Geräte mit schwacher Batterie' -f @($ha.LowBattery).Count) ((@($ha.LowBattery) | ForEach-Object { '{0} ({1:N0} %)' -f $_.Name, $_.Value }) -join ', ') 'Batterien tauschen.' }
    }
    if ($Data.HaErr) { & $add 5 'Home Assistant' 'Home Assistant nicht abrufbar' $Data.HaErr 'Adresse und Token prüfen (Profil > Sicherheit > Langlebige Zugriffstoken).' }
    $sm = $Data.Smart
    if ($sm) {
        foreach ($k in @($sm.Knx)) {
            $kd = 'KNX {0} ({1})' -f $k.Name, $k.Ip
            if (-not $k.Secure) { & $add 3 $kd 'KNX-IP-Schnittstelle ohne KNX Secure' ('Physikalische Adresse {0}, {1}. Die KNX-Telegramme gehen unverschlüsselt und ohne Anmeldung durchs Netz: Jedes Gerät in diesem Netz (auch ein gehacktes Smart-TV oder Gäste im WLAN) kann Licht, Jalousien, Heizung oder Türöffner schalten und alles mitlesen.{2}' -f $k.Address, $k.Medium, $(if ($k.Routing) { ' Die Schnittstelle arbeitet zusätzlich als Router (Multicast) - jedes Gerät im Netz kann Telegramme direkt auf den Bus senden.' } else { '' })) 'KNX IP Secure (Secure Tunneling/Routing) in der ETS einschalten oder gegen ein Secure-fähiges Gerät tauschen; KNX-IP in ein eigenes Netz/VLAN ohne Gäste und IoT; Port 3671 nie ins Internet freigeben, Fernzugriff nur per VPN; ETS-Projektpasswort und BCU-Schlüssel setzen.' }
            else { & $add 5 $kd 'KNX IP Secure unterstützt' ('Physikalische Adresse {0}, {1}.' -f $k.Address, $k.Medium) 'In der ETS prüfen, ob Secure Tunneling auch wirklich aktiviert ist - unterstützt heißt nicht eingeschaltet.' }
        }
        $its = @($sm.Items)
        foreach ($grp in @($its | Where-Object { $_.Auth -match '^KEIN' -and $_.System -match 'Shelly|Tasmota' } | Group-Object { ($_.System -split ' ')[0] })) { & $add 3 ('{0} Geräte' -f $grp.Name) ('{0} {1}-Gerät(e) ohne Passwort' -f $grp.Count, $grp.Name) (($grp.Group | ForEach-Object { '{0}{1}' -f $_.Ip, $(if ($_.Model) { ' (' + $_.Model + ')' } else { '' }) }) -join ', ') 'In der Weboberfläche jedes Geräts unter Einstellungen > Zugriff/Authentifizierung ein Passwort setzen - sonst kann jeder im Netz schalten und die Firmware tauschen. Firmware aktuell halten.' }
        foreach ($it in @($its | Where-Object { $_.System -eq 'Node-RED' -and $_.Risk -eq 'Hoch' })) { & $add 2 ('Node-RED ({0})' -f $it.Ip) 'Node-RED-Editor ohne Anmeldung' 'Wer den Editor erreicht, kann Abläufe ändern und beliebige Befehle auf dem Gerät ausführen.' 'In settings.js "adminAuth" mit Benutzer und Kennwort einrichten, Node-RED nur im Smart-Home-Netz erreichbar machen.' }
        foreach ($it in @($its | Where-Object { $_.System -eq 'MQTT-Broker' -and $_.Risk -eq 'Hoch' })) { & $add 2 ('MQTT ({0})' -f $it.Ip) 'MQTT-Broker erlaubt anonymen Zugriff' 'Jeder im Netz kann alle Smart-Home-Nachrichten mitlesen und Geräte schalten (z.B. Shelly, Tasmota, Zigbee2MQTT).' 'Im Broker (z.B. Mosquitto: allow_anonymous false) Benutzer und Kennwörter erzwingen, wenn möglich TLS (8883).' }
        foreach ($it in @($its | Where-Object { $_.System -like 'Homematic*' -and $_.Risk -eq 'Mittel' })) { & $add 3 ('Homematic ({0})' -f $it.Ip) 'Homematic-API ohne Anmeldung' 'Über die XML-RPC-Schnittstelle kann jedes Gerät im Netz Aktoren schalten und Programme ändern.' 'CCU/RaspberryMatic: Einstellungen > Systemsteuerung > Sicherheit > "Authentifizierung" einschalten und Firewall auf "eingeschränkt" stellen.' }
        foreach ($it in @($its | Where-Object { $_.System -eq 'HomeKit-Gerät' -and $_.Detail -match 'NICHT gekoppelt' })) { & $add 4 ('HomeKit ({0})' -f $it.Ip) 'HomeKit-Gerät nicht gekoppelt' $it.Detail 'Gerät in der Home-App koppeln oder zurücksetzen/entfernen.' }
        foreach ($it in @($its | Where-Object { $_.System -eq 'Zigbee-Koordinator (Netzwerk)' })) { & $add 4 ('Zigbee ({0})' -f $it.Ip) 'Zigbee-Koordinator per Netzwerk erreichbar' $it.Detail 'Nur im Smart-Home-Netz betreiben, Firmware aktuell halten.' }
        $esp = @($its | Where-Object { $_.System -eq 'ESPHome' }); if ($esp.Count) { & $add 5 'ESPHome-Geräte' ('{0} ESPHome-Gerät(e) mit Netzwerk-API' -f $esp.Count) (($esp | ForEach-Object { $_.Ip }) -join ', ') 'In jeder Konfiguration "api: encryption: key" und ein OTA-Passwort setzen.' }
        $nSmart = @($its | Where-Object { $_.System -notin 'MQTT-Broker', 'KNX IP' }).Count + @($sm.Knx).Count
        if ($nSmart -ge 3) { & $add 4 'Netzaufteilung' ('{0} Smart-Home-/Gebäudetechnik-Geräte im selben Netz wie PCs und NAS' -f $nSmart) 'Smart-Home-Geräte haben oft schwache Sicherheit und selten Updates. Wird eines übernommen, ist von dort das ganze Netz erreichbar.' 'Eigenes IoT-Netz einrichten (FRITZ!Box: Gastnetz für Smart-Home-Geräte bzw. VLAN am Switch/Router); Zentralen (Home Assistant, KNX, Homematic) nur von dort und vom Admin-PC erreichbar machen.' }
    }
    $w = $Data.Wlan
    if ($w -and $w.Conn -and $w.Conn.Ssid) {
        $c = $w.Conn
        if ($c.Auth -match '(?i)offen|open') { & $add 1 ('WLAN ' + $c.Ssid) 'WLAN ohne Verschlüsselung' 'Jeder in Reichweite kann mitlesen und das Netz benutzen.' 'Im Router WPA2-AES oder WPA3 mit langem Kennwort einschalten.' }
        elseif ($c.Cipher -match '(?i)WEP') { & $add 1 ('WLAN ' + $c.Ssid) 'WEP-Verschlüsselung' 'WEP ist in Minuten zu knacken.' 'Auf WPA2-AES oder WPA3 umstellen.' }
        elseif ($c.Cipher -match '(?i)TKIP') { & $add 2 ('WLAN ' + $c.Ssid) 'Veraltete TKIP-Verschlüsselung' 'TKIP gilt als unsicher und bremst das WLAN auf 54 Mbit/s.' 'Im Router "WPA2 (CCMP/AES)" bzw. "WPA2+WPA3" einstellen.' }
        elseif ($c.Auth -notmatch 'WPA3' -and $w.Caps.Wpa3) { & $add 5 ('WLAN ' + $c.Ssid) 'WPA3 möglich' 'Verbunden mit WPA2. Der Adapter dieses PCs kann WPA3.' 'Kann der Router WPA3: "WPA2 + WPA3" einschalten.' }
        if ($c.Rssi -and $c.Rssi -lt -75) { & $add 5 ('WLAN ' + $c.Ssid) 'Schwaches WLAN-Signal an diesem PC' ('ca. {0} dBm' -f $c.Rssi) 'Seite "WLAN optimieren".' }
    }
    if ($w) {
        $open = @($w.Profiles | Where-Object { $_.Auth -match '(?i)offen|open' })
        if ($open.Count) { & $add 4 'Dieser PC' ('{0} offene WLANs gespeichert' -f $open.Count) (($open | ForEach-Object { $_.Name }) -join ', ') 'Offene Hotspots vergessen oder auf "manuell verbinden" stellen - sonst verbindet sich der PC unbemerkt mit gleichnamigen Fake-Hotspots.' }
        $weak = @($w.Nets | Where-Object { $_.Auth -match '(?i)offen|open' -or $_.Enc -match '(?i)WEP' } | Select-Object -ExpandProperty Ssid -Unique)
        if ($weak.Count) { & $add 5 'Umgebung' ('{0} offene/unsichere WLANs in Reichweite' -f $weak.Count) (($weak | Select-Object -First 10) -join ', ') 'Nur zur Information - nicht mit diesen Netzen verbinden.' }
    }
    $pc = $Data.Pc
    foreach ($fw in @($pc.Firewall)) { if (-not $fw.Enabled) { & $add 2 'Dieser PC' ('Windows-Firewall aus (Profil {0})' -f $fw.Name) 'Ohne Firewall sind alle Dienste des PCs im Netz erreichbar.' 'Seite Sicherheit bzw. Netzwerk-Sicherheit: Firewall einschalten.' } }
    if ($pc.Smb1 -eq $true) { & $add 2 'Dieser PC' 'SMB1 (altes Dateifreigabe-Protokoll) aktiv' 'SMB1 war das Einfallstor von WannaCry und wird nicht mehr gebraucht.' 'SMB1 abschalten (Windows-Features > "Unterstützung für SMB 1.0/CIFS-Dateifreigabe").' }
    if ($pc.Rdp -eq $true -and $pc.RdpNla -eq $false) { & $add 2 'Dieser PC' 'Remotedesktop ohne Netzwerkebenen-Authentifizierung' 'Ohne NLA ist der Anmeldebildschirm ohne Kennwort erreichbar - Angriffsfläche für RDP-Lücken.' 'Systemeigenschaften > Remote: "Nur Verbindungen mit Authentifizierung auf Netzwerkebene zulassen".' }
    elseif ($pc.Rdp -eq $true) { & $add 5 'Dieser PC' 'Remotedesktop eingeschaltet' 'Mit NLA geschützt.' 'Nur einschalten, wenn gebraucht; nie direkt ins Internet freigeben.' }
    if ($pc.Guest -eq $true) { & $add 3 'Dieser PC' 'Gastkonto aktiv' 'Das Gastkonto erlaubt Anmeldungen ohne Kennwort.' 'Gastkonto deaktivieren.' }
    foreach ($s in @($pc.Shares | Where-Object { $_.Everyone })) { & $add 3 'Dieser PC' ('Freigabe "{0}" für Jeder beschreibbar' -f $s.Name) ('{0} - {1}' -f $s.Path, $s.Access) 'Rechte auf bestimmte Benutzer beschränken.' }
    foreach ($pf in @($pc.Profiles | Where-Object { $_.Category -eq 'Public' })) { & $add 5 'Dieser PC' ('Netz "{0}" als öffentlich eingestuft' -f $pf.Name) 'Sicher für fremde Netze; im eigenen Netz sind dann Dateifreigabe und Gerätesuche aus.' 'Im eigenen Heim-/Firmennetz bei Bedarf auf "Privat" stellen.' }
    if ($pc.Proxy -and $pc.Proxy -notmatch '(?i)kein Proxy|direct|direkt') { & $add 5 'Dieser PC' 'Proxy eingestellt' $pc.Proxy 'Prüfen, ob gewollt - Schadsoftware setzt gern einen Proxy, um mitzulesen.' }
    if (@($pc.Hosts).Count) { & $add 5 'Dieser PC' ('{0} Einträge in der hosts-Datei' -f @($pc.Hosts).Count) ((@($pc.Hosts) | Select-Object -First 8) -join '; ') 'Prüfen, ob gewollt - Schadsoftware leitet hierüber Seiten um.' }
    if ($pc.Llmnr) { & $add 5 'Dieser PC' 'LLMNR-Namensauflösung aktiv' 'Windows-Standard. In Firmennetzen ein bekannter Angriffsweg (Abgreifen von Anmeldedaten).' 'In Firmennetzen per Gruppenrichtlinie "Multicastnamensauflösung deaktivieren".' }
    return , @($f | Sort-Object SevNo, Device)
}
function Get-NdocScore($Findings) {
    $s = 100; foreach ($x in @($Findings)) { $s -= @(0, 25, 12, 6, 2, 0)[$x.SevNo] }
    $s = [math]::Max(0, $s)
    $g = if ($s -ge 90) { 'A' } elseif ($s -ge 75) { 'B' } elseif ($s -ge 60) { 'C' } elseif ($s -ge 40) { 'D' } else { 'E' }
    [pscustomobject]@{ Score = $s; Grade = $g; Text = @{ A = 'sehr gut'; B = 'gut'; C = 'befriedigend'; D = 'mangelhaft'; E = 'kritisch' }[$g] }
}
function ConvertTo-NdocHtml($Data, $Rows, $Findings, $RouterChecks, $Meta, $PortNames, $Exposure = @(), $Diff = $null, $Rooms = @(), $KnxMon = $null) {
    $e = { param($s) [Net.WebUtility]::HtmlEncode([string]$s) }
    $sc = Get-NdocScore $Findings
    $cnt = @{}; foreach ($k in 1..5) { $cnt[$k] = @($Findings | Where-Object { $_.SevNo -eq $k }).Count }
    $net = $Data.Net; $rt = $Data.Router; $w = $Data.Wlan; $pc = $Data.Pc
    $box = if ($rt -and $rt.Box) { '{0} (FRITZ!OS {1})' -f $rt.Box.Name, $rt.Box.Os } else { '' }
    $sevCol = @{ 1 = '#B91C1C'; 2 = '#EA580C'; 3 = '#D97706'; 4 = '#2563EB'; 5 = '#64748B' }
    $gradeCol = @{ A = '#16A34A'; B = '#65A30D'; C = '#D97706'; D = '#EA580C'; E = '#B91C1C' }[$sc.Grade]
    $h = [System.Text.StringBuilder]::new()
    $null = $h.Append(@"
<!DOCTYPE html><html lang="de"><head><meta charset="utf-8"><title>Netzwerk-Dokumentation</title><style>
@page { size: A4; margin: 14mm 13mm 16mm 13mm; }
* { box-sizing: border-box; -webkit-print-color-adjust: exact; print-color-adjust: exact; }
body { font-family: 'Segoe UI', Arial, sans-serif; color: #1F2A44; font-size: 10pt; line-height: 1.45; margin: 0; }
h1 { font-size: 26pt; margin: 0 0 4px; letter-spacing: -0.5px; } h2 { font-size: 15pt; margin: 0 0 10px; padding-bottom: 6px; border-bottom: 2px solid #2D7FF9; color: #13213D; }
h3 { font-size: 11.5pt; margin: 16px 0 6px; color: #13213D; }
.page { break-before: page; } .avoid { break-inside: avoid; }
.cover { height: 265mm; display: flex; flex-direction: column; }
.band { background: linear-gradient(135deg, #1E3A8A 0%, #2D7FF9 60%, #06B6D4 100%); color: white; border-radius: 14px; padding: 34px 32px 30px; }
.band .sub { font-size: 12pt; opacity: .9; } .band .meta { margin-top: 22px; font-size: 10pt; opacity: .95; display: grid; grid-template-columns: 140px 1fr; row-gap: 3px; }
.kpis { display: grid; grid-template-columns: repeat(4, 1fr); gap: 10px; margin: 18px 0; }
.kpi { border: 1px solid #E2E7F0; border-radius: 12px; padding: 12px 14px; background: #F8FAFD; } .kpi .v { font-size: 20pt; font-weight: 700; } .kpi .l { color: #6B7890; font-size: 9pt; }
.grade { display: flex; align-items: center; gap: 18px; border: 1px solid #E2E7F0; border-radius: 14px; padding: 16px 20px; }
.grade .g { width: 74px; height: 74px; border-radius: 37px; color: white; font-size: 34pt; font-weight: 700; display: flex; align-items: center; justify-content: center; }
.sev { display: inline-block; border-radius: 10px; padding: 1px 9px; color: white; font-size: 8.5pt; font-weight: 600; white-space: nowrap; }
table { width: 100%; border-collapse: collapse; margin: 6px 0 12px; font-size: 8.8pt; } th { background: #EEF3FB; color: #13213D; text-align: left; padding: 6px 7px; font-weight: 600; border-bottom: 1px solid #C7D0DE; }
td { padding: 5px 7px; border-bottom: 1px solid #E8ECF3; vertical-align: top; } tr { break-inside: avoid; } tr:nth-child(even) td { background: #FAFBFD; }
.mono { font-family: Consolas, monospace; font-size: 8.4pt; } .muted { color: #6B7890; } .small { font-size: 8.5pt; }
.kv { display: grid; grid-template-columns: 190px 1fr; row-gap: 4px; column-gap: 12px; margin-bottom: 10px; } .kv div:nth-child(odd) { color: #6B7890; }
.box { border: 1px solid #E2E7F0; border-left: 4px solid #2D7FF9; border-radius: 8px; padding: 10px 14px; margin: 8px 0; background: #F8FAFD; }
.toc li { margin: 4px 0; } .chk { display: inline-block; width: 11px; height: 11px; border: 1.4px solid #52627A; border-radius: 2px; margin-right: 6px; vertical-align: -1px; }
.foot { margin-top: auto; color: #6B7890; font-size: 8.5pt; border-top: 1px solid #E2E7F0; padding-top: 8px; }
</style></head><body>
"@)
    # ---------- Deckblatt
    $null = $h.Append('<div class="cover"><div class="band">' + $(if ($Meta.LogoData) { '<img src="' + $Meta.LogoData + '" style="float:right;max-height:70px;max-width:210px;background:#fff;border-radius:10px;padding:8px;margin-left:16px">' } else { '' }) + '<div class="sub">PC-Tools · Netzwerk-Dokumentation</div><h1>' + (& $e $(if ($Meta.Title) { $Meta.Title } else { 'Netzwerk ' + $net.Ip + '/' + $net.Prefix })) + '</h1><div class="sub">Bestandsaufnahme, Geräteinventar und Sicherheitsbewertung</div><div class="meta">')
    foreach ($kv in @(@('Standort / Kunde', $Meta.Site), @('Erstellt von', $Meta.Author), @('Erfasst am', ($Data.Time.ToString('dd.MM.yyyy, HH:mm') + ' Uhr')), @('Erfasst von PC', ($pc.Computer + ' (' + $pc.Model + ')')), @('Netz', ('{0}/{1} · Router {2}' -f $net.Ip, $net.Prefix, $net.Gateway)))) { if ($kv[1]) { $null = $h.Append('<div>' + (& $e $kv[0]) + '</div><div><b>' + (& $e $kv[1]) + '</b></div>') } }
    $null = $h.Append('</div></div>')
    $null = $h.Append('<div class="kpis"><div class="kpi"><div class="v">' + @($Rows | Where-Object { -not $_.Offline }).Count + '</div><div class="l">Geräte im Netz</div></div><div class="kpi"><div class="v" style="color:#B91C1C">' + ($cnt[1] + $cnt[2]) + '</div><div class="l">kritische/hohe Befunde</div></div><div class="kpi"><div class="v" style="color:#D97706">' + ($cnt[3] + $cnt[4]) + '</div><div class="l">mittlere/niedrige Befunde</div></div><div class="kpi"><div class="v">' + @($Rows | Where-Object { @($_.PortList).Count }).Count + '</div><div class="l">Geräte mit offenen Diensten</div></div></div>')
    $null = $h.Append(('<div class="grade avoid"><div class="g" style="background:{0}">{1}</div><div><div style="font-size:14pt;font-weight:600">Sicherheitsbewertung: {2} ({3} von 100 Punkten)</div><div class="muted">Kritisch {4} · Hoch {5} · Mittel {6} · Niedrig {7} · Hinweise {8}. Die Bewertung zieht je Befund Punkte ab (kritisch 25, hoch 12, mittel 6, niedrig 2).</div></div></div>' -f $gradeCol, $sc.Grade, $sc.Text, $sc.Score, $cnt[1], $cnt[2], $cnt[3], $cnt[4], $cnt[5]))
    # Topologie (SVG)
    $tOrd = @{ 'Firewall' = 0; 'Router (weiterer)' = 1; 'WLAN-Controller' = 2; 'Switch' = 3; 'Access Point' = 4; 'Repeater/Access Point' = 5 }
    $groups = @($Rows | Where-Object { -not $_.Gateway -and -not $_.Offline } | Group-Object Type | Sort-Object @{ e = { if ($tOrd.ContainsKey($_.Name)) { $tOrd[$_.Name] } else { 10 } } }, @{ e = { $_.Count }; Descending = $true } | Select-Object -First 10)
    $svgW = 700; $svg = [System.Text.StringBuilder]::new()
    $null = $svg.Append(('<svg viewBox="0 0 {0} 270" width="100%" xmlns="http://www.w3.org/2000/svg" style="margin-top:18px">' -f $svgW))
    $null = $svg.Append('<rect x="290" y="6" width="120" height="40" rx="20" fill="#E0ECFF" stroke="#2D7FF9"/><text x="350" y="31" text-anchor="middle" font-size="13" fill="#1E3A8A" font-weight="600">Internet</text>')
    $null = $svg.Append('<line x1="350" y1="46" x2="350" y2="84" stroke="#2D7FF9" stroke-width="2"/>')
    $null = $svg.Append(('<rect x="255" y="84" width="190" height="50" rx="10" fill="#1E3A8A"/><text x="350" y="106" text-anchor="middle" font-size="13" fill="white" font-weight="600">Router</text><text x="350" y="123" text-anchor="middle" font-size="10" fill="#C7D7FF">{0}</text>' -f (& $e $(if ($box) { $box } else { $net.Gateway }))))
    $svgL = [System.Text.StringBuilder]::new(); $svgB = [System.Text.StringBuilder]::new()
    $n = [math]::Max(1, $groups.Count); $bw = [math]::Min(130, ($svgW - 20) / [math]::Min($n, 5) - 10)
    for ($k = 0; $k -lt $groups.Count; $k++) {
        $row = [math]::Floor($k / 5); $col = $k % 5; $inRow = [math]::Min(5, $groups.Count - $row * 5)
        $x = ($svgW - ($inRow * ($bw + 10) - 10)) / 2 + $col * ($bw + 10); $y = 170 + $row * 52
        $null = $svgL.Append(('<path d="M350 134 L350 152 L{0} 152 L{0} {1}" fill="none" stroke="#9FB4D6" stroke-width="1.4"/>' -f ($x + $bw / 2), $y))
        $null = $svgB.Append(('<rect x="{0}" y="{1}" width="{2}" height="40" rx="8" fill="#F1F5FB" stroke="#9FB4D6"/><text x="{3}" y="{4}" text-anchor="middle" font-size="10.5" fill="#13213D" font-weight="600">{5}</text><text x="{3}" y="{6}" text-anchor="middle" font-size="9.5" fill="#52627A">{7} Gerät(e)</text>' -f $x, $y, $bw, ($x + $bw / 2), ($y + 17), (& $e $groups[$k].Name), ($y + 31), $groups[$k].Count))
    }
    $null = $svg.Append($svgL.ToString()); $null = $svg.Append($svgB.ToString())
    $null = $svg.Append('</svg>')
    $null = $h.Append('<h3>Aufbau des Netzes</h3>' + $svg.ToString())
    $null = $h.Append('<div class="foot">Erstellt mit PC-Tools ' + (& $e $Meta.AppVersion) + ' · Momentaufnahme: Geräte, die ausgeschaltet waren oder Ping und ARP nicht beantworten, fehlen. Die Prüfung erfolgte nur von innen und nur im eigenen Netz.</div></div>')
    # ---------- Inhalt + Zusammenfassung
    $null = $h.Append('<div class="page"><h2>Inhalt</h2><ol class="toc"><li>Zusammenfassung und wichtigste Maßnahmen</li><li>Änderungen seit der letzten Erfassung</li><li>Netz und Internetanschluss</li><li>Erreichbarkeit aus dem Internet</li><li>Router</li><li>Netzwerk-Infrastruktur (Router, Firewalls, Switches, Access Points)</li><li>WLAN</li><li>Geräteinventar</li><li>Offene Dienste je Gerät</li><li>Smart Home und Gebäudeautomation (KNX)</li><li>Dieser PC</li><li>Schwachstellen im Detail</li><li>Maßnahmenplan zum Abhaken</li><li>Anhang: Methodik und Legende</li></ol>')
    $null = $h.Append('<h2 style="margin-top:22px">1. Zusammenfassung</h2>')
    $top = @($Findings | Where-Object { $_.SevNo -le 3 } | Select-Object -First 8)
    $null = $h.Append(('<div class="box">Im Netz <b>{0}/{1}</b> wurden <b>{2} Geräte</b> gefunden{3}. Die Sicherheitsbewertung lautet <b>{4}</b> ({5}/100). {6}</div>' -f $net.Ip, $net.Prefix, @($Rows).Count, $(if (@($Rows | Where-Object { $_.IsNew }).Count) { ', davon <b>' + @($Rows | Where-Object { $_.IsNew }).Count + ' neu</b> seit der letzten Erfassung' } else { '' }), $sc.Text, $sc.Score, $(if ($top.Count) { 'Die folgenden Punkte sollten zuerst angegangen werden:' } else { 'Es gibt keine kritischen, hohen oder mittleren Befunde.' })))
    if ($top.Count) { $null = $h.Append('<table><tr><th style="width:80px">Stufe</th><th style="width:160px">Gerät</th><th>Befund</th><th style="width:230px">Maßnahme</th></tr>'); foreach ($x in $top) { $null = $h.Append(('<tr><td><span class="sev" style="background:{0}">{1}</span></td><td>{2}</td><td><b>{3}</b></td><td>{4}</td></tr>' -f $sevCol[$x.SevNo], $x.Sev, (& $e $x.Device), (& $e $x.Title), (& $e $x.Fix))) }; $null = $h.Append('</table>') }
    $null = $h.Append('<h3>Geräte nach Art</h3><table><tr><th>Art</th><th style="width:70px">Anzahl</th><th>Beispiele</th></tr>')
    foreach ($g in @($Rows | Group-Object Type | Sort-Object Count -Descending)) { $null = $h.Append(('<tr><td>{0}</td><td>{1}</td><td class="small">{2}</td></tr>' -f (& $e $g.Name), $g.Count, (& $e ((@($g.Group | Select-Object -First 4 | ForEach-Object { $_.Name -replace '\s+\[.*$', '' }) -join ', '))))) }
    $null = $h.Append('</table></div>')
    # ---------- 2. Änderungen
    $null = $h.Append('<div class="page"><h2>2. Änderungen seit der letzten Erfassung</h2>')
    if (-not $Diff) { $null = $h.Append('<p class="muted">Dies ist die erste Erfassung - beim nächsten Bericht werden hier neue und verschwundene Geräte, neue offene Dienste sowie neue und behobene Befunde aufgeführt.</p>') }
    else {
        $pt = ''; try { $pt = ([datetime]$Diff.PrevTime).ToString('dd.MM.yyyy HH:mm') } catch { $pt = [string]$Diff.PrevTime }
        $null = $h.Append(('<div class="box">Verglichen mit der Erfassung vom <b>{0}</b>: {1} neue Geräte, {2} nicht mehr gefunden, {3} mit neuen offenen Diensten, {4} neue und {5} behobene Befunde.</div>' -f $pt, @($Diff.NewDev).Count, @($Diff.GoneDev).Count, @($Diff.PortsOpened).Count, @($Diff.NewFind).Count, @($Diff.FixedFind).Count))
        $tbl = { param($title, $items, $cols, $sb) if (@($items).Count) { $null = $h.Append('<h3>' + $title + '</h3><table><tr>' + (($cols | ForEach-Object { '<th>' + $_ + '</th>' }) -join '') + '</tr>'); foreach ($i in @($items)) { $null = $h.Append('<tr>' + ((& $sb $i | ForEach-Object { '<td>' + (& $e $_) + '</td>' }) -join '') + '</tr>') }; $null = $h.Append('</table>') } }
        & $tbl 'Neue Geräte' $Diff.NewDev @('Name', 'IP', 'MAC', 'Hersteller') { param($i) $i.Name, $i.Ip, $i.Mac, $i.Vendor }
        & $tbl 'Nicht mehr gefunden (ausgeschaltet oder entfernt)' $Diff.GoneDev @('Name', 'IP', 'MAC', 'Art') { param($i) $i.Name, $i.Ip, $i.Mac, $i.Type }
        & $tbl 'Neue offene Dienste' $Diff.PortsOpened @('Gerät', 'IP', 'Neue Ports') { param($i) $i.Name, $i.Ip, $i.Ports }
        & $tbl 'Geschlossene Dienste' $Diff.PortsClosed @('Gerät', 'IP', 'Ports') { param($i) $i.Name, $i.Ip, $i.Ports }
        & $tbl 'Geänderte IP-Adressen' $Diff.IpChanged @('Gerät', 'vorher', 'jetzt') { param($i) $i.Name, $i.Old, $i.New }
        & $tbl 'Neue Befunde' $Diff.NewFind @('Stufe', 'Gerät', 'Befund') { param($i) $i.Sev, $i.Device, $i.Title }
        & $tbl 'Behobene Befunde' $Diff.FixedFind @('Stufe', 'Gerät', 'Befund') { param($i) $i.Sev, $i.Device, $i.Title }
    }
    $null = $h.Append('</div>')
    # ---------- 3. Netz
    $null = $h.Append('<div class="page"><h2>3. Netz und Internetanschluss</h2><div class="kv">')
    $dh = if ($rt -and $rt.Dhcp) { if ($rt.Dhcp.Enabled) { 'DHCP vom Server ' + $rt.Dhcp.Server } else { 'feste Adresse' } } else { '' }
    $v6 = if ($rt -and $rt.Ipv6) { if ($rt.Ipv6.Global.Count) { 'aktiv (' + (@($rt.Ipv6.Global | Select-Object -First 2) -join ', ') + ')' } elseif (-not $rt.Ipv6.Bound) { 'am Adapter abgeschaltet' } else { 'nur IPv4' } } else { '' }
    foreach ($kv in @(@('Netzbereich', ('{0}/{1}' -f $net.Ip, $net.Prefix)), @('Standardgateway (Router)', $net.Gateway), @('DNS-Server', (@($net.Dns) -join ', ')), @('Adresse dieses PCs', $dh), @('IPv6', $v6), @('Verbunden über', ('{0} - {1} ({2}, {3})' -f $net.Name, $net.Desc, $net.Kind, $net.Speed)), @('Öffentliche IPv4-Adresse', $Data.PublicIp), @('Externe IP laut Router (UPnP)', $(if ($rt -and $rt.Upnp) { $rt.Upnp.Ext } else { '' })))) { if ($kv[1]) { $null = $h.Append('<div>' + (& $e $kv[0]) + '</div><div>' + (& $e $kv[1]) + '</div>') } }
    $null = $h.Append('</div>')
    if ($Meta.Speed -and @($Meta.Speed).Count) {
        $null = $h.Append('<h3>Letzte Geschwindigkeitsmessungen</h3><table><tr><th>Datum</th><th>Verbindung</th><th>Download</th><th>Upload</th><th>Ping</th><th>Schwankung</th></tr>')
        foreach ($s in @($Meta.Speed)) { $null = $h.Append(('<tr><td>{0}</td><td>{1}</td><td>{2}</td><td>{3}</td><td>{4}</td><td>{5}</td></tr>' -f $s.DateText, (& $e $s.Kind), $s.DownText, $s.UpText, $s.PingText, $s.JitterText)) }
        $null = $h.Append('</table>')
    }
    # ---------- 4. Erreichbarkeit
    $null = $h.Append('<h2 style="margin-top:20px">4. Erreichbarkeit aus dem Internet</h2>')
    $expL = @($Exposure)
    $crit = @($expL | Where-Object { $_.SevNo -le 2 -and $_.Way -ne 'Anschlussart' })
    $null = $h.Append(('<div class="box">{0} Wege von außen ins Netz gefunden{1}. Geprüft wurden Portfreigaben (FRITZ!Box und automatisch per UPnP), der Fernzugang zur FRITZ!Box/MyFRITZ!, die Anschlussart (Carrier-NAT/DS-Lite), IPv6 und - falls eingeschaltet - was Shodan bei Internet-Scans an der öffentlichen Adresse {2} gesehen hat.</div>' -f @($expL | Where-Object { $_.Way -notin 'Anschlussart', 'IPv6', 'Shodan InternetDB' }).Count, $(if ($crit.Count) { ', davon <b style="color:#B91C1C">' + $crit.Count + ' kritisch/hoch</b>' } else { '' }), (& $e $Data.PublicIp)))
    if ($expL.Count) {
        $null = $h.Append('<table><tr><th style="width:72px">Stufe</th><th style="width:150px">Weg</th><th style="width:90px">Von außen</th><th style="width:140px">Ziel im Netz</th><th>Dienst und Bewertung</th></tr>')
        foreach ($x in $expL) { $null = $h.Append(('<tr><td><span class="sev" style="background:{0}">{1}</span></td><td class="small">{2}</td><td class="mono">{3}</td><td class="small">{4}</td><td class="small"><b>{5}</b><br>{6}</td></tr>' -f $sevCol[$x.SevNo], $x.Sev, (& $e $x.Way), (& $e $x.External), (& $e $x.Target), (& $e $x.Service), (& $e $x.Hint))) }
        $null = $h.Append('</table>')
    } else { $null = $h.Append('<p class="muted">Keine Daten zur Erreichbarkeit (ohne FRITZ!Box-Anmeldung und ohne Shodan-Abfrage nur über UPnP prüfbar).</p>') }
    if ($Data.Shodan -and $Data.Shodan.Found -and (@($Data.Shodan.Hostnames).Count -or @($Data.Shodan.Cpes).Count)) { $null = $h.Append(('<p class="small muted">Shodan: Namen {0}; erkannte Software {1}</p>' -f (& $e (@($Data.Shodan.Hostnames) -join ', ')), (& $e (@($Data.Shodan.Cpes) -join ', ')))) }
    # ---------- 5. Router
    $null = $h.Append('<h2 style="margin-top:20px">5. Router</h2>')
    if ($rt -and $rt.Box) { $null = $h.Append('<div class="kv">'); foreach ($kv in @(@('Modell', $rt.Box.Name), @('FRITZ!OS', ($rt.Box.Os + ' (' + $rt.Box.Version + ')')), @('Hardware', $rt.Box.HW), @('Branding', $rt.Box.Oem), @('MAC', $rt.GwMac))) { if ($kv[1]) { $null = $h.Append('<div>' + (& $e $kv[0]) + '</div><div>' + (& $e $kv[1]) + '</div>') } }; $null = $h.Append('</div>') }
    if (@($RouterChecks).Count) {
        $lvT = @{ Good = @('#16A34A', 'gut'); Warn = @('#D97706', 'prüfen'); Bad = @('#B91C1C', 'Problem'); Info = @('#64748B', 'Info') }
        $null = $h.Append('<table><tr><th style="width:70px">Status</th><th style="width:200px">Prüfung</th><th>Ergebnis</th></tr>')
        foreach ($c in @($RouterChecks)) { $m = $lvT[[string]$c.Level]; if (-not $m) { $m = $lvT.Info }; $null = $h.Append(('<tr><td><span class="sev" style="background:{0}">{1}</span></td><td><b>{2}</b></td><td class="small">{3}</td></tr>' -f $m[0], $m[1], (& $e $c.Title), (& $e $c.Detail))) }
        $null = $h.Append('</table>')
    }
    if ($rt -and $rt.Upnp -and @($rt.Upnp.Maps).Count) { $null = $h.Append('<h3>Automatische Portfreigaben (UPnP)</h3><table><tr><th>Extern</th><th>Protokoll</th><th>Ziel im Netz</th><th>Beschreibung</th></tr>'); foreach ($m in @($rt.Upnp.Maps)) { $null = $h.Append(('<tr><td>{0}</td><td>{1}</td><td class="mono">{2}</td><td>{3}</td></tr>' -f (& $e $m.Ext), (& $e $m.Proto), (& $e $m.Int), (& $e $m.Desc))) }; $null = $h.Append('</table>') }
    $fb = $Data.Fritz
    if ($fb) {
        $dv = $fb.Device; $upd = $fb.Update
