            foreach ($k in $kn) { $null = $h.Append(('<tr><td><b>{0}</b><br><span class="mono muted">{1}</span></td><td class="mono">{2}</td><td>{3}</td><td>{4}</td><td class="small">{5}</td><td>{6}</td></tr>' -f (& $e $k.Name), $k.Mac, $k.Ip, $k.Address, (& $e $k.Medium), (& $e ((@($(if ($k.Tunnel) { 'Tunneling' }), $(if ($k.Routing) { 'Routing' }), $(if ($k.Mgmt) { 'Fernwartung' })) | Where-Object { $_ }) -join ', ')), $(if ($k.Secure) { '<span class="sev" style="background:#16A34A">unterstützt</span>' } else { '<span class="sev" style="background:#D97706">nein</span>' }))) }
