        $ha = $Data.Ha
        if ($ha) {
            $null = $h.Append(('<h3>Home Assistant "{0}" (Version {1})</h3><div class="kv"><div>Adresse</div><div>{2}</div><div>Entitäten</div><div>{3} ({4})</div><div>Integrationen</div><div class="small">{5}</div><div>Nicht verfügbar</div><div>{6}</div><div>Schwache Batterien</div><div>{7}</div></div>' -f (& $e $ha.Name), (& $e $ha.Version), (& $e $ha.Url), $ha.Entities, (& $e ((@($ha.Domains.Keys | Sort-Object { -[int]$ha.Domains[$_] } | Select-Object -First 12 | ForEach-Object { '{0} {1}' -f $ha.Domains[$_], $_ })) -join ', ')), (& $e ((@($ha.Components) | Where-Object { $_ -notin 'api', 'auth', 'config', 'frontend', 'http', 'websocket_api', 'onboarding', 'person', 'system_log', 'logger', 'default_config', 'homeassistant', 'persistent_notification', 'repairs', 'search', 'sun', 'zone', 'tag', 'trace', 'webhook', 'device_automation', 'diagnostics', 'file_upload', 'image_upload', 'lovelace', 'network', 'analytics', 'application_credentials', 'blueprint', 'counter', 'input_boolean', 'input_button', 'input_datetime', 'input_number', 'input_select', 'input_text', 'timer', 'schedule', 'script', 'automation', 'scene', 'group' }) -join ', ')), $ha.UnavailCount, @($ha.LowBattery).Count))
            if (@($ha.Updates).Count) { $null = $h.Append('<table><tr><th>Ausstehendes Update</th><th style="width:120px">installiert</th><th style="width:120px">verfügbar</th></tr>'); foreach ($u in @($ha.Updates)) { $null = $h.Append(('<tr><td>{0}</td><td>{1}</td><td><b>{2}</b></td></tr>' -f (& $e $u.Name), (& $e $u.Installed), (& $e $u.Latest))) }; $null = $h.Append('</table>') }
            if (@($ha.LowBattery).Count) { $null = $h.Append('<p class="small"><b>Batterie unter 20 %:</b> ' + (& $e ((@($ha.LowBattery) | ForEach-Object { '{0} ({1:N0} %)' -f $_.Name, $_.Value }) -join ', ')) + '</p>') }
        } elseif ($Data.HaErr) { $null = $h.Append('<p class="small muted">Home Assistant nicht abrufbar: ' + (& $e $Data.HaErr) + '</p>') }
        if ($KnxMon) {
            $null = $h.Append(('<h3>KNX-Busmonitor ({0} Sekunden, {1} Telegramme)</h3>' -f $KnxMon.Seconds, $KnxMon.Frames))
            if (-not $KnxMon.Frames) { $null = $h.Append('<p class="small muted">Keine Telegramme empfangen. Der passive Mitschnitt funktioniert nur mit einem KNX-IP-Router (Routing/Multicast); reine Tunneling-Schnittstellen geben nichts ins Netz.</p>') }
            else {
                $null = $h.Append('<table><tr><th style="width:80px">Gruppenadr.</th><th style="width:60px">Telegr.</th><th style="width:130px">Schreiben/Lesen/Antw.</th><th style="width:110px">letzter Wert</th><th>Absender (phys. Adr.)</th></tr>')
                foreach ($g in @($KnxMon.Groups | Select-Object -First 60)) { $null = $h.Append(('<tr><td class="mono">{0}</td><td>{1}</td><td>{2} / {3} / {4}</td><td class="mono">{5}</td><td class="small">{6}</td></tr>' -f $g.Ga, $g.Count, $g.Write, $g.Read, $g.Resp, (& $e $g.Last), (& $e $g.Sources))) }
                $null = $h.Append('</table><p class="small muted">Sendende Geräte: ' + (& $e ((@($KnxMon.Devices) | Select-Object -First 40 | ForEach-Object { '{0} ({1})' -f $_.Pa, $_.Count }) -join ', ')) + '. Jedes Gerät im Netz kann diese Telegramme ohne KNX Secure genauso mitlesen.</p>')
            }
        }
        $null = $h.Append('<h3>Empfehlungen für Smart Home und KNX</h3><ul><li><b>Eigenes Netz für Smart Home</b> (Gastnetz/VLAN): Lampen, Steckdosen, Kameras und Sprachassistenten getrennt von PCs und NAS.</li><li><b>KNX:</b> KNX IP Secure nutzen, KNX-IP-Schnittstellen in ein eigenes Netz, nie Port 3671 freigeben, Fernzugriff nur per VPN; ETS-Projekt mit Passwort und Sicherung aufbewahren.</li><li><b>Jedes Gerät mit eigenem Passwort</b> (Shelly, Tasmota, Node-RED, MQTT, Homematic) - Standard- oder leere Zugänge sind der häufigste Angriffsweg.</li><li><b>Updates</b> für Zentralen und Geräte regelmäßig einspielen; Geräte ohne Updates mittelfristig ersetzen.</li><li><b>Lokal statt Cloud</b> bevorzugen (Matter, Zigbee, KNX) - weniger Abhängigkeit und weniger Daten beim Hersteller.</li></ul>')
    }
    $null = $h.Append('</div>')
    # ---------- 8. Dieser PC
    $null = $h.Append('<div class="page"><h2>11. Dieser PC</h2><div class="kv">')
    foreach ($kv in @(@('Computername', $pc.Computer), @('Modell', $pc.Model), @('Betriebssystem', $pc.Os), @('Zugehörigkeit', $pc.Domain), @('Proxy', $pc.Proxy), @('SMB1', $(if ($null -eq $pc.Smb1) { '' } elseif ($pc.Smb1) { 'AN (unsicher)' } else { 'aus' })), @('Remotedesktop', $(if ($null -eq $pc.Rdp) { '' } elseif ($pc.Rdp) { 'an' + $(if ($pc.RdpNla) { ' (mit NLA)' } else { ' (OHNE NLA)' }) } else { 'aus' })), @('Gastkonto', $(if ($null -eq $pc.Guest) { '' } elseif ($pc.Guest) { 'aktiv' } else { 'deaktiviert' })), @('Firewall', ((@($pc.Firewall) | ForEach-Object { '{0}: {1}' -f $_.Name, $(if ($_.Enabled) { 'an' } else { 'AUS' }) }) -join ', ')), @('Netzprofile', ((@($pc.Profiles) | ForEach-Object { '{0} ({1}): {2}' -f $_.Name, $_.Alias, $(if ($_.Category -eq 'Private') { 'privat' } elseif ($_.Category -eq 'Public') { 'öffentlich' } else { $_.Category }) }) -join '; ')))) { if ($kv[1]) { $null = $h.Append('<div>' + (& $e $kv[0]) + '</div><div>' + (& $e $kv[1]) + '</div>') } }
    $null = $h.Append('</div><h3>Netzwerkadapter</h3><table><tr><th>Adapter</th><th style="width:60px">Status</th><th style="width:100px">MAC</th><th>IPv4 / Gateway / DNS</th></tr>')
    foreach ($a in @($pc.Adapters)) { $null = $h.Append(('<tr><td><b>{0}</b><br><span class="small muted">{1}{2}</span></td><td>{3}</td><td class="mono">{4}</td><td class="small">{5}</td></tr>' -f (& $e $a.Name), (& $e $a.Desc), $(if ($a.Speed -and $a.Status -eq 'Up') { ' · ' + $a.Speed } else { '' }), (& $e $a.Status), $a.Mac, (& $e ((@($a.Ipv4, $(if ($a.Dhcp) { '(' + $a.Dhcp + ')' }), $(if ($a.Gateway) { 'GW ' + $a.Gateway }), $(if ($a.Dns) { 'DNS ' + $a.Dns }), $(if ($a.Ipv6) { 'IPv6 ' + $a.Ipv6 }) | Where-Object { $_ }) -join ' · '))))) }
    $null = $h.Append('</table>')
    if (@($pc.Shares).Count) { $null = $h.Append('<h3>Freigaben</h3><table><tr><th>Name</th><th>Pfad</th><th>Rechte</th></tr>'); foreach ($s in @($pc.Shares)) { $null = $h.Append(('<tr><td>{0}</td><td class="mono">{1}</td><td class="small">{2}</td></tr>' -f (& $e $s.Name), (& $e $s.Path), (& $e $s.Access))) }; $null = $h.Append('</table>') }
    if (@($pc.Listen).Count) { $null = $h.Append('<h3>Dienste, die auf diesem PC von außen erreichbar lauschen</h3><table><tr><th style="width:70px">Port</th><th style="width:170px">Bedeutung</th><th>Programm</th></tr>'); foreach ($l in @($pc.Listen)) { $null = $h.Append(('<tr><td>{0}</td><td>{1}</td><td>{2}</td></tr>' -f $l.Port, (& $e $(if ($PortNames.ContainsKey([int]$l.Port)) { $PortNames[[int]$l.Port] } else { '' })), (& $e $l.Proc))) }; $null = $h.Append('</table><p class="small muted">Ob diese Dienste wirklich von anderen Geräten erreichbar sind, entscheidet zusätzlich die Windows-Firewall.</p>') }
    if (@($pc.Drives).Count -or @($pc.Printers).Count) { $null = $h.Append('<h3>Netzlaufwerke und Netzwerkdrucker</h3><ul>'); foreach ($x in @($pc.Drives) + @($pc.Printers)) { $null = $h.Append('<li>' + (& $e $x) + '</li>') }; $null = $h.Append('</ul>') }
    $null = $h.Append('</div>')
    # ---------- 8. Schwachstellen
    $null = $h.Append(('<div class="page"><h2>12. Schwachstellen im Detail ({0})</h2>' -f @($Findings).Count))
    if (-not @($Findings).Count) { $null = $h.Append('<p>Keine Befunde.</p>') }
    $no = 0
    foreach ($x in @($Findings)) { $no++; $null = $h.Append(('<div class="avoid" style="border:1px solid #E2E7F0;border-left:5px solid {0};border-radius:8px;padding:8px 12px;margin:7px 0"><div><span class="sev" style="background:{0}">{1}</span> <b>{2}. {3}</b> <span class="muted">· {4}</span></div><div class="small" style="margin-top:3px">{5}</div><div class="small" style="margin-top:3px"><b>Maßnahme:</b> {6}</div></div>' -f $sevCol[$x.SevNo], $x.Sev, $no, (& $e $x.Title), (& $e $x.Device), (& $e $x.Detail), (& $e $x.Fix))) }
    $null = $h.Append('</div>')
    # ---------- 9. Maßnahmenplan
    $null = $h.Append('<div class="page"><h2>13. Maßnahmenplan zum Abhaken</h2><table><tr><th style="width:24px"></th><th style="width:72px">Stufe</th><th>Maßnahme</th><th style="width:150px">Gerät</th><th style="width:80px">Erledigt am</th></tr>')
    foreach ($x in @($Findings | Where-Object { $_.SevNo -le 4 })) { $null = $h.Append(('<tr><td><span class="chk"></span></td><td><span class="sev" style="background:{0}">{1}</span></td><td><b>{2}</b><br><span class="small">{3}</span></td><td class="small">{4}</td><td></td></tr>' -f $sevCol[$x.SevNo], $x.Sev, (& $e $x.Title), (& $e $x.Fix), (& $e $x.Device))) }
    $null = $h.Append('</table><h3>Allgemeine Empfehlungen</h3><ul><li>Router, NAS, Kameras und Smart-Home-Geräte regelmäßig aktualisieren (automatische Updates einschalten).</li><li>Für Gäste und Smart-Home-Geräte ein eigenes Gast-/IoT-WLAN verwenden - so kommen sie nicht an PCs und NAS.</li><li>Standard-Kennwörter aller Geräte ändern, für Router und NAS Zwei-Faktor-Anmeldung nutzen, wo möglich.</li><li>Portfreigaben und UPnP nur für Geräte, die es wirklich brauchen; Fernzugriff besser per VPN.</li><li>Diesen Bericht regelmäßig (z.B. vierteljährlich) neu erstellen - neue Geräte werden markiert.</li></ul>')
    $null = $h.Append('<h3 style="margin-top:26px">Freigabe</h3><table class="avoid"><tr><th style="width:120px"></th><th>Name</th><th style="width:110px">Datum</th><th style="width:200px">Unterschrift</th></tr>' + ((@('Erstellt', 'Geprüft', 'Freigegeben') | ForEach-Object { '<tr><td><b>' + $_ + '</b></td><td style="height:38px">' + $(if ($_ -eq 'Erstellt' -and $Meta.Author) { & $e $Meta.Author } else { '' }) + '</td><td>' + $(if ($_ -eq 'Erstellt') { $Data.Time.ToString('dd.MM.yyyy') } else { '' }) + '</td><td></td></tr>' }) -join '') + '</table></div>')
    # ---------- Anhang
    $null = $h.Append('<div class="page"><h2>14. Anhang: Methodik und Legende</h2><p>Die Erfassung lief vom PC <b>' + (& $e $pc.Computer) + '</b> aus. Geräte werden per Ping an alle Adressen des eigenen Netzes (höchstens /24) und über die ARP-Tabelle gefunden; Namen über DNS/Router. Die Dienst-Prüfung baut zu ' + @($Meta.Ports).Count + ' üblichen TCP-Ports eine kurze Verbindung auf (kein Eindringen, keine Anmeldeversuche). Router-Daten stammen aus der Weboberfläche (nur öffentliche Infos), FRITZ!Box-Infodatei und UPnP. WLAN-Daten liefert Windows (netsh).</p>')
    $null = $h.Append('<h3>Stufen</h3><table><tr><th style="width:90px">Stufe</th><th>Bedeutung</th></tr>')
    foreach ($k in 1..5) { $null = $h.Append(('<tr><td><span class="sev" style="background:{0}">{1}</span></td><td>{2}</td></tr>' -f $sevCol[$k], @('', 'Kritisch', 'Hoch', 'Mittel', 'Niedrig', 'Info')[$k], @('', 'Sofort handeln - das Netz oder ein Gerät kann direkt übernommen werden.', 'Zeitnah beheben - bekannte, häufig ausgenutzte Schwachstelle.', 'Beheben, wenn möglich - erhöht das Risiko oder ist unnötig offen.', 'Gute Praxis - kleine Verbesserung.', 'Hinweis zur Einordnung, keine Schwachstelle.')[$k])) }
    $null = $h.Append('</table><h3>Geprüfte Dienste</h3><table><tr><th style="width:60px">Port</th><th>Dienst</th><th style="width:60px">Port</th><th>Dienst</th></tr>')
    $pl = @($Meta.Ports | Sort-Object); for ($k = 0; $k -lt $pl.Count; $k += 2) { $a1 = $pl[$k]; $a2 = if ($k + 1 -lt $pl.Count) { $pl[$k + 1] } else { $null }; $null = $h.Append(('<tr><td>{0}</td><td>{1}</td><td>{2}</td><td>{3}</td></tr>' -f $a1, (& $e $PortNames[[int]$a1]), $a2, $(if ($null -ne $a2) { & $e $PortNames[[int]$a2] } else { '' }))) }
    $null = $h.Append('</table><p class="small muted">Grenzen: Ausgeschaltete Geräte, Geräte in anderen Netzen/VLANs und Geräte, die weder Ping noch ARP beantworten, fehlen. Eine fehlende Warnung ist keine Garantie für Sicherheit. Diese Dokumentation enthält keine Kennwörter.</p></div>')
    $null = $h.Append('</body></html>')
    return $h.ToString()
}
# ---- Geraete mit Problemen (Geraete-Manager) (standalone, laufen in Invoke-Bg)
# Verwaiste Software-Geraete (ROOT\..., Treiber geloescht, z.B. alter TAP-Adapter) werden entfernt.
# Bluetooth-Dienste ohne Treiber (BTHENUM\{Dienst}..., "Andere Geraete") kommen nach dem Entfernen sofort wieder,
# solange das Geraet gekoppelt ist - dauerhaft hilft nur, den Dienst fuer dieses Geraet auszuschalten.
function Get-DevBtSvcName([string]$Guid) {
    $g = $Guid.ToLower()
    if ($g -notmatch '^0000([0-9a-f]{4})-0000-1000-8000-00805f9b34fb$') { return 'herstellereigener Dienst' }
    switch ($Matches[1]) {
        '1101' { 'Serieller Anschluss' } '1103' { 'DFU-Netzwerk' } '1105' { 'Objektuebertragung (OBEX)' } '1106' { 'Dateiuebertragung (OBEX)' }
        '1108' { 'Headset' } '110a' { 'Audioquelle' } '110b' { 'Audiowiedergabe (A2DP)' } '110c' { 'Fernbedienung (AVRCP)' } '110e' { 'Fernbedienung (AVRCP)' }
        '1112' { 'Headset-Gateway' } '1115' { 'Netzwerk (PANU)' } '1116' { 'Netzwerkzugang (NAP)' } '111e' { 'Freisprechen' } '111f' { 'Freisprech-Gateway' }
        '1124' { 'Eingabegeraet (HID)' } '112d' { 'SIM-Zugriff' } '112f' { 'Telefonbuchzugriff' } '1132' { 'Nachrichtenzugriff' } '1200' { 'Geraeteinformation (PnP)' }
        default { 'Dienst 0x' + $Matches[1] }
    }
}
function Get-DevProblemText([int]$Code) {
    switch ($Code) {
        1 { 'nicht richtig eingerichtet (Code 1)' } 3 { 'Treiber beschaedigt oder zu wenig Speicher (Code 3)' } 10 { 'Geraet kann nicht gestartet werden (Code 10)' }
        12 { 'zu wenig freie Ressourcen (Code 12)' } 14 { 'Neustart noetig (Code 14)' } 18 { 'Treiber neu installieren (Code 18)' } 19 { 'Registrierung beschaedigt (Code 19)' }
        21 { 'wird gerade entfernt (Code 21)' } 22 { 'deaktiviert (Code 22)' } 24 { 'nicht vorhanden oder unvollstaendig installiert (Code 24)' }
        28 { 'kein Treiber installiert (Code 28)' } 29 { 'von der Firmware deaktiviert (Code 29)' } 31 { 'Treiber laesst sich nicht laden (Code 31)' }
        32 { 'Treiberdienst deaktiviert (Code 32)' } 37 { 'Treiber meldet Fehler beim Start (Code 37)' } 38 { 'alter Treiber noch im Speicher - Neustart (Code 38)' }
        39 { 'Treiber beschaedigt oder fehlt (Code 39)' } 43 { 'Geraet hat einen Fehler gemeldet (Code 43)' } 45 { 'nicht angeschlossen (Code 45)' }
        48 { 'Treiber von Windows blockiert (Code 48)' } 52 { 'Treibersignatur ungueltig (Code 52)' } 0 { 'Status unbekannt' }
        default { 'Problem-Code ' + $Code }
    }
}
function Get-DevIssues {
    $res = [System.Collections.Generic.List[object]]::new()
    $all = @(); try { $all = @(Get-PnpDevice -PresentOnly -ErrorAction Stop) } catch { }
    $btDev = @{}
    foreach ($b in $all) { if ([string]$b.InstanceId -match '^BTHENUM\\DEV_([0-9A-F]{12})') { $btDev[$Matches[1].ToUpper()] = [string]$b.FriendlyName } }
    if (-not $btDev.Count) {
        foreach ($b in @($all | Where-Object { [string]$_.Class -eq 'Bluetooth' })) { if ([string]$b.InstanceId -match '^BTH(LE)?ENUM\\.*?([0-9A-F]{12})' -and -not $btDev.ContainsKey($Matches[2].ToUpper())) { $btDev[$Matches[2].ToUpper()] = [string]$b.FriendlyName } }
    }
    foreach ($d in @($all | Where-Object { [string]$_.Status -ne 'OK' })) {
        $id = [string]$d.InstanceId; $cls = [string]$d.Class; $code = 0; try { $code = [int]$d.ConfigManagerErrorCode } catch { }
        $name = [string]$d.FriendlyName; if (-not $name) { $name = 'Unbekanntes Geraet' }
        $hw = @($d.HardwareID | Where-Object { $_ }); $hw1 = if ($hw.Count) { [string]$hw[0] } else { '' }
        $o = [pscustomobject]@{ Kind = ''; Name = $name; InstanceId = $id; HardwareId = $hw1; Code = $code; Detail = (Get-DevProblemText $code); Fix = 'None'; Mac = ''; SvcGuid = ''; BtName = '' }
        if ($id -match '^BTHENUM\\\{([0-9A-Fa-f-]{36})\}' -and -not $cls) {
            $o.SvcGuid = $Matches[1].ToLower()
            if ($id -match '([0-9A-F]{12})_C[0-9A-F]+$') { $o.Mac = $Matches[1].ToUpper() }
            $o.BtName = if ($o.Mac -and $btDev.ContainsKey($o.Mac)) { $btDev[$o.Mac] } else { 'Bluetooth-Geraet ' + $o.Mac }
            $o.Kind = 'BtDienst'; $o.Name = ('{0} - {1}' -f $o.BtName, (Get-DevBtSvcName $o.SvcGuid))
            $o.Detail = 'Bluetooth-Dienst des gekoppelten Geraets, fuer den es keinen Windows-Treiber gibt - harmlos, kommt aber nach dem Loeschen sofort wieder'
            $o.Fix = $(if ($o.Mac) { 'BtOff' } else { 'None' })
        }
        elseif ($id -like 'ROOT\*' -and $code -in 28, 1, 18, 24, 31, 39) {
            $o.Kind = 'Verwaist'; $o.Detail = 'verwaister Software-Eintrag (Treiber wurde entfernt, z.B. von altem VPN/Virtualisierungsprogramm) - ' + $o.Detail; $o.Fix = 'Remove'
        }
        elseif ($code -eq 22) { $o.Kind = 'Deaktiviert' }
        elseif ($code -eq 28) { $o.Kind = 'OhneTreiber' }
        else { $o.Kind = 'Fehler' }
        $res.Add($o)
    }
    return $res.ToArray()
}
function Get-DevIssueText {
    $list = @(Get-DevIssues)
    $o = [System.Collections.Generic.List[string]]::new()
    $real = @($list | Where-Object { $_.Kind -notin 'Deaktiviert', 'BtDienst' }); $bt = @($list | Where-Object { $_.Kind -eq 'BtDienst' })
    if (-not $list.Count) { $o.Add('Keine Geraete mit Problemen - der Geraete-Manager ist sauber.') }
    else { $o.Add(('{0} Geraet(e) mit Problemen, davon {1} harmlose Bluetooth-Dienste.' -f ($real.Count + $bt.Count), $bt.Count)) }
    $o.Add('')
    foreach ($i in @($list | Sort-Object { switch ($_.Kind) { 'Verwaist' { 0 } 'OhneTreiber' { 1 } 'Fehler' { 2 } 'BtDienst' { 3 } default { 4 } } }, Name)) {
        $tag = switch ($i.Kind) { 'Verwaist' { '[VERWAIST]' } 'OhneTreiber' { '[KEIN TREIBER]' } 'Fehler' { '[FEHLER]' } 'BtDienst' { '[BT-DIENST]' } default { '[deaktiviert]' } }
        $o.Add(('{0}  {1}' -f $tag, $i.Name)); $o.Add('        ' + $i.Detail)
        if ($i.Kind -ne 'BtDienst') { $o.Add('        ' + $i.InstanceId); if ($i.HardwareId -and $i.HardwareId -ne $i.InstanceId) { $o.Add('        Hardware-ID: ' + $i.HardwareId) } }
        switch ($i.Kind) {
            'Verwaist' { $o.Add('        -> "Reparieren" entfernt den Eintrag.') }
            'BtDienst' { $o.Add('        -> "Reparieren" schaltet diesen Dienst fuer das Geraet aus, dann ist der Eintrag dauerhaft weg.') }
            'OhneTreiber' { $o.Add('        -> Treiber fehlt: Einstellungen > Windows Update > Erweiterte Optionen > Optionale Updates, sonst mit der Hardware-ID beim Hersteller suchen.') }
            'Fehler' { $o.Add('        -> Geraete-Manager: Treiber aktualisieren oder Geraet deinstallieren und neu starten.') }
        }
    }
    if (@($list | Where-Object { $_.Fix -ne 'None' }).Count) { $o.Add(''); $o.Add('"Reparieren": verwaiste Eintraege werden entfernt, Bluetooth-Dienste ohne Treiber werden fuer ihr Geraet ausgeschaltet (Koppelung, Musik und Telefonie bleiben, soweit Windows sie unterstuetzt).') }
    return ($o -join "`r`n")
}
function Disable-DevBtService([string]$Mac, [string]$Guid) {
    if (-not ('PcToolsBt' -as [type])) {
        Add-Type -TypeDefinition @'
using System; using System.Runtime.InteropServices;
public static class PcToolsBt {
    [StructLayout(LayoutKind.Sequential)] public struct SYSTEMTIME { public ushort a, b, c, d, e, f, g, h; }
    [StructLayout(LayoutKind.Sequential, CharSet = CharSet.Unicode)] public struct DEVINFO {
        public uint dwSize; public ulong Address; public uint ulClassofDevice; public int fConnected; public int fRemembered; public int fAuthenticated;
        public SYSTEMTIME stLastSeen; public SYSTEMTIME stLastUsed; [MarshalAs(UnmanagedType.ByValTStr, SizeConst = 248)] public string szName; }
    [StructLayout(LayoutKind.Sequential)] public struct RADIOPARAMS { public uint dwSize; }
    [DllImport("bthprops.cpl", SetLastError = true)] static extern IntPtr BluetoothFindFirstRadio(ref RADIOPARAMS p, out IntPtr hRadio);
    [DllImport("bthprops.cpl", SetLastError = true)] static extern bool BluetoothFindRadioClose(IntPtr hFind);
    [DllImport("bthprops.cpl", SetLastError = true)] static extern uint BluetoothGetDeviceInfo(IntPtr hRadio, ref DEVINFO info);
    [DllImport("bthprops.cpl", SetLastError = true)] static extern uint BluetoothSetServiceState(IntPtr hRadio, ref DEVINFO info, ref Guid svc, uint flags);
    [DllImport("kernel32.dll")] static extern bool CloseHandle(IntPtr h);
    public static uint Disable(ulong addr, Guid svc) {
        RADIOPARAMS p = new RADIOPARAMS(); p.dwSize = (uint)Marshal.SizeOf(typeof(RADIOPARAMS));
        IntPtr hRadio; IntPtr hFind = BluetoothFindFirstRadio(ref p, out hRadio);
        if (hFind == IntPtr.Zero) return 0xFFFFFFFF;
        try {
            DEVINFO i = new DEVINFO(); i.dwSize = (uint)Marshal.SizeOf(typeof(DEVINFO)); i.Address = addr; i.szName = "";
            uint r = BluetoothGetDeviceInfo(hRadio, ref i); if (r != 0) return r;
            return BluetoothSetServiceState(hRadio, ref i, ref svc, 0);
        } finally { CloseHandle(hRadio); BluetoothFindRadioClose(hFind); }
    }
}
'@ -ErrorAction Stop
    }
    return [PcToolsBt]::Disable([Convert]::ToUInt64($Mac, 16), [guid]$Guid)
}
function Remove-DevNode([string]$Id) {
    $r = Invoke-NdCmd (Get-SysExe 'pnputil.exe') ('/remove-device "{0}"' -f $Id) 60
    Start-Sleep -Milliseconds 300
    $still = $null; try { $still = Get-PnpDevice -InstanceId $Id -PresentOnly -ErrorAction Stop } catch { }
    if (-not $still) { return '' }
    return (($r -split "`r`n" | Where-Object { $_.Trim() } | Select-Object -Last 1) -join ' ')
}
function Repair-DevIssues {
    $o = [System.Collections.Generic.List[string]]::new(); $cpl = $false
    $list = @(Get-DevIssues)
    foreach ($i in @($list | Where-Object { $_.Fix -eq 'Remove' })) {
        $e = Remove-DevNode $i.InstanceId
        $o.Add(('  {0}: {1}' -f $i.Name, $(if (-not $e) { 'verwaisten Eintrag entfernt' } else { 'nicht entfernt - ' + $e })))
    }
    $done = @{}
    foreach ($i in @($list | Where-Object { $_.Fix -eq 'BtOff' })) {
        $k = $i.Mac + '|' + $i.SvcGuid; if ($done.ContainsKey($k)) { continue }; $done[$k] = 1
        $rc = $null; $err = ''
        try { $rc = Disable-DevBtService $i.Mac $i.SvcGuid } catch { $err = $_.Exception.Message -replace '\s+', ' ' }
        if ($null -ne $rc -and [uint32]$rc -eq 0) {
            Start-Sleep -Milliseconds 500
            $null = Remove-DevNode $i.InstanceId
            $o.Add(('  {0}: Dienst fuer dieses Geraet ausgeschaltet' -f $i.Name))
        }
        else {
            $cpl = $true
            $why = if ($err) { $err } elseif ($null -ne $rc -and [uint32]$rc -eq [uint32]::MaxValue) { 'kein Bluetooth-Adapter gefunden/eingeschaltet' } else { 'Windows-Fehler ' + $rc }
            $o.Add(('  {0}: nicht ausgeschaltet ({1})' -f $i.Name, $why))
        }
    }
    if ($cpl) {
        $o.Add(''); $o.Add('Von Hand: In der geoeffneten Systemsteuerung "Geraete und Drucker" das Bluetooth-Geraet rechts anklicken > Eigenschaften > Registerkarte "Dienste" > die Haken bei den Diensten ohne Treiber entfernen > OK.')
    }
    if (-not $o.Count) { $o.Add('  Nichts automatisch zu reparieren.') }
    else { $o.Add(''); $o.Add('Zum Kontrollieren erneut "Geraete pruefen" klicken.') }
    return [pscustomobject]@{ Text = ("== Geraete reparieren ==`r`n" + ($o -join "`r`n")); OpenCpl = $cpl }
}
# ---- Store-Apps, die nicht starten (standalone, laufen in Invoke-Bg)
# Typischer Fall nach grossen Windows-Updates: App ist als installiert eingetragen, ihr Programmordner fehlt
# (InstallLocation leer) -> startet nicht, Zuruecksetzen hilft nicht, nur entfernen + neu installieren.
function Get-AppxIssues {
    $res = [System.Collections.Generic.List[object]]::new()
    $mine = @(); try { $mine = @(Get-AppxPackage -ErrorAction Stop) } catch { }
    foreach ($p in $mine) {
        if ($p.IsFramework -or $p.IsResourcePackage -or $p.IsBundle) { continue }
        $loc = [string]$p.InstallLocation
        $noDir = (-not $loc) -or -not (Test-Path -LiteralPath $loc)
        $badSt = ([string]$p.Status -ne 'Ok')
        if (-not ($noDir -or $badSt)) { continue }
        $store = ([string]$p.SignatureKind -eq 'Store')
        $det = if ($noDir) { 'Programmordner fehlt - die App ist eingetragen, startet aber nicht' } else { 'Paketstatus: ' + [string]$p.Status }
        $res.Add([pscustomobject]@{ Kind = 'App'; Name = [string]$p.Name; Version = [string]$p.Version; FullName = [string]$p.PackageFullName; Family = [string]$p.PackageFamilyName; Detail = $det; Fix = $(if ($store) { 'Reinstall' } else { 'None' }); WingetId = '' })
    }
    # Laufzeiten/Frameworks (alle Benutzer): defekte alte Version ist harmlos, wenn eine neuere derselben Reihe in Ordnung ist
    $all = @(); try { $all = @(Get-AppxPackage -AllUsers -ErrorAction Stop | Where-Object { $_.IsFramework }) } catch { }
    foreach ($p in @($all | Where-Object { [string]$_.Status -ne 'Ok' })) {
        $okNewer = @($all | Where-Object { $_.Name -eq $p.Name -and [string]$_.Architecture -eq [string]$p.Architecture -and [string]$_.Status -eq 'Ok' -and [version]$_.Version -gt [version]$p.Version })
        $wid = if ($p.Name -match '^Microsoft\.WindowsAppRuntime\.\d+(\.\d+)?$') { [string]$p.Name } else { '' }
        if ($okNewer.Count) { $res.Add([pscustomobject]@{ Kind = 'Altlast'; Name = [string]$p.Name; Version = [string]$p.Version; FullName = [string]$p.PackageFullName; Family = ''; Detail = ('alte Version beschaedigt ({0}), neuere {1} ist in Ordnung - stoert nicht' -f [string]$p.Status, [string]($okNewer | Sort-Object { [version]$_.Version } | Select-Object -Last 1).Version); Fix = 'None'; WingetId = '' }) }
        else { $res.Add([pscustomobject]@{ Kind = 'Laufzeit'; Name = [string]$p.Name; Version = [string]$p.Version; FullName = [string]$p.PackageFullName; Family = ''; Detail = ('Laufzeit beschaedigt ({0}) - Apps, die sie brauchen, starten nicht' -f [string]$p.Status); Fix = $(if ($wid) { 'Winget' } else { 'None' }); WingetId = $wid }) }
    }
    # WebView2 (Grundlage u.a. fuer das neue Outlook, Teams, Widgets)
    $wv = ''
    foreach ($k in 'HKLM:\SOFTWARE\WOW6432Node\Microsoft\EdgeUpdate\Clients\{F3017226-FE2A-4295-8BDF-00C3A9A7E4C5}', 'HKLM:\SOFTWARE\Microsoft\EdgeUpdate\Clients\{F3017226-FE2A-4295-8BDF-00C3A9A7E4C5}', 'HKCU:\SOFTWARE\Microsoft\EdgeUpdate\Clients\{F3017226-FE2A-4295-8BDF-00C3A9A7E4C5}') {
        try { $v = [string](Get-ItemProperty -LiteralPath $k -ErrorAction Stop).pv; if ($v -and $v -ne '0.0.0.0') { $wv = $v; break } } catch { }
    }
    if (-not $wv) { $res.Add([pscustomobject]@{ Kind = 'WebView2'; Name = 'Microsoft Edge WebView2'; Version = ''; FullName = ''; Family = ''; Detail = 'fehlt - das neue Outlook, Teams u.a. starten ohne WebView2 nicht'; Fix = 'Winget'; WingetId = 'Microsoft.EdgeWebView2Runtime' }) }
    return $res.ToArray()
}
function Get-AppxIssueText {
    $list = @(Get-AppxIssues)
    $o = [System.Collections.Generic.List[string]]::new()
    $real = @($list | Where-Object { $_.Kind -ne 'Altlast' })
    if (-not $real.Count) { $o.Add('Alle Store-Apps und ihre Laufzeiten sind in Ordnung.') }
    else { $o.Add(('{0} Problem(e) gefunden:' -f $real.Count)) }
    $o.Add('')
    foreach ($i in $list) {
        $tag = switch ($i.Kind) { 'App' { '[APP DEFEKT]' } 'Laufzeit' { '[LAUFZEIT DEFEKT]' } 'WebView2' { '[FEHLT]' } default { '[harmlos]' } }
        $o.Add(('{0}  {1} {2}' -f $tag, $i.Name, $i.Version)); $o.Add('        ' + $i.Detail)
        if ($i.Kind -eq 'App' -and $i.Fix -eq 'None') { $o.Add('        Windows-eigene App - hier hilft nur DISM/SFC bzw. eine Reparaturinstallation.') }
    }
    if ($real.Count) { $o.Add(''); $o.Add('"Reparieren": defekte Store-Apps werden entfernt und ihre Store-Seite zum Neuinstallieren geoeffnet, defekte Laufzeiten und WebView2 werden neu installiert.') }
    else { $o.Add(''); $o.Add('Startet eine App trotzdem nicht: Einstellungen > Apps > die App > Erweiterte Optionen > "Zuruecksetzen".') }
    return ($o -join "`r`n")
}
function Repair-AppxIssues {
    $o = [System.Collections.Generic.List[string]]::new(); $open = [System.Collections.Generic.List[string]]::new()
    $list = @(Get-AppxIssues)
    $wg = $null; try { $wg = (Get-Command winget.exe -ErrorAction Stop).Source } catch { }
    foreach ($i in @($list | Where-Object { $_.Fix -eq 'Winget' })) {
        if (-not $wg) { $o.Add(('  {0}: winget fehlt - bitte ueber den Microsoft Store "App-Installer" installieren.' -f $i.Name)); continue }
        $r = Invoke-NdCmd $wg ('install --id {0} --exact --force --accept-package-agreements --accept-source-agreements --disable-interactivity' -f $i.WingetId) 600
        $ok = $r -match '(?i)Erfolgreich installiert|Successfully installed'
        $o.Add(('  {0}: {1}' -f $i.Name, $(if ($ok) { 'neu installiert' } else { 'Installation nicht bestaetigt - Ausgabe: ' + (($r -split "`r`n" | Where-Object { $_.Trim() } | Select-Object -Last 2) -join ' / ') })))
    }
    foreach ($i in @($list | Where-Object { $_.Fix -eq 'Reinstall' })) {
        try {
            Remove-AppxPackage -Package $i.FullName -ErrorAction Stop
            $o.Add(('  {0}: defekte Registrierung entfernt - Store-Seite zum Neuinstallieren wird geoeffnet.' -f $i.Name)); if ($i.Family) { $open.Add($i.Family) }
        } catch { $o.Add(('  {0}: konnte nicht entfernt werden: {1}' -f $i.Name, ($_.Exception.Message -replace '\s+', ' '))) }
    }
    if (-not $o.Count) { $o.Add('  Nichts zu reparieren.') }
    return [pscustomobject]@{ Text = ("== Store-Apps reparieren ==`r`n" + ($o -join "`r`n")); Open = $open.ToArray() }
}
function Get-SvcTriggerMap {
    $t = @{}
    try { foreach ($k in Get-ChildItem 'HKLM:\SYSTEM\CurrentControlSet\Services' -ErrorAction Stop) { if (Test-Path -LiteralPath (Join-Path $k.PSPath 'TriggerInfo')) { $t[$k.PSChildName] = $true } } } catch { }
    return $t
}
function Get-StuckSvcText {
    # Nur Diagnose - startet KEINE Dienste (laeuft daher in wenigen Sekunden durch)
    $trig = Get-SvcTriggerMap
    $hostMap = Get-SvcHostGroupMap
    $svc = @(); try { $svc = @(Get-CimInstance Win32_Service -ErrorAction Stop) } catch { return 'Dienste nicht lesbar: ' + $_.Exception.Message }
    $auto = @($svc | Where-Object { $_.StartMode -eq 'Auto' -and $_.State -ne 'Running' } | Sort-Object DisplayName)
    if (-not $auto.Count) { return 'Alle automatischen Dienste laufen - keine Probleme gefunden.' }
    $echt = @($auto | Where-Object { -not $trig.ContainsKey($_.Name) })
    $o = [System.Collections.Generic.List[string]]::new()
    if ($echt.Count) { $o.Add(('{0} Automatik-Dienst(e) laufen gerade nicht ({1} weitere starten nur bei Bedarf):' -f $echt.Count, ($auto.Count - $echt.Count))) }
    else { $o.Add('Alle nicht laufenden Automatik-Dienste starten nur bei Bedarf - das ist normal.') }
    $o.Add('')
    foreach ($s in $auto) {
        $name = $s.Name
        $isTrig = $trig.ContainsKey($name)
        $gs = $null; try { $gs = Get-Service -Name $name -ErrorAction Stop } catch { }
        $depBad = @(); if ($gs) { try { $depBad = @($gs.ServicesDependedOn | Where-Object { $_.Status -ne 'Running' } | ForEach-Object { '{0} ({1})' -f $_.Name, $_.Status }) } catch { } }
        $binOk = $true; $bin = ''
        if ($s.PathName) { $bin = ($s.PathName -replace '^"([^"]+)".*$', '$1'); if ($bin -notmatch '^[A-Za-z]:') { $bin = ($s.PathName -split '\s+')[0] }; if ($bin -match '\.exe$' -and -not (Test-Path -LiteralPath $bin)) { $binOk = $false } }
        $reason = ''
        $hg = @(Get-SvcHostGroupsFor $hostMap $name)
        $grpFix = Get-SvcHostGroupFix ([string]$s.PathName) $hg
        $grpNone = ($hostMap.Count -gt 0) -and -not $hg.Count -and ([string]$s.PathName -match '(?i)svchost\.exe"?\s+-k\s+\S+')
        if ($grpFix) { $reason = ("FALSCHE DIENSTGRUPPE: Startpfad nennt '{0}', Windows fuehrt den Dienst in '{1}'. Der Prozess startet, findet den Dienst aber nie - darum haengt er. ""Reparieren"" korrigiert das (danach Neustart)." -f (Get-SvcHostGroupOf ([string]$s.PathName)), $hg[0]) }
        elseif ($grpNone) { $reason = ("DIENST IN KEINER DIENSTGRUPPE: Startpfad nennt '{0}', dort ist der Dienst nicht eingetragen - er haengt deshalb beim Start. Reparaturinstallation empfohlen." -f (Get-SvcHostGroupOf ([string]$s.PathName))) }
        elseif ($isTrig) { $reason = 'startet nur bei Bedarf (Trigger) - leerer Status ist normal' }
        elseif (-not $binOk) { $reason = 'PROGRAMMDATEI FEHLT: ' + $bin }
        elseif ($depBad.Count) { $reason = 'wartet auf Dienst(e), der/die nicht laufen: ' + ($depBad -join ', ') }
        elseif ($s.StartMode -eq 'Auto' -and $s.DelayedAutoStart) { $reason = 'verzögerter Start (startet kurz nach dem Hochfahren)' }
        else { $reason = 'sollte laufen, tut es aber nicht - mit "Reparieren" starten' }
        $tag = if ($grpFix -or $grpNone) { '[FALSCH EINGERICHTET]' } elseif ($s.State -eq 'Start Pending') { '[HAENGT BEIM START]' } elseif ($isTrig) { '[bei Bedarf]' } else { '[LAEUFT NICHT]' }
        $o.Add(('{0}  {1}  ({2})' -f $tag, $s.DisplayName, $name))
        if ($reason) { $o.Add('        Ursache: ' + $reason) }
        if (-not $isTrig -and $s.StartName -and $s.StartName -notmatch '^(LocalSystem|NT AUTHORITY|NT SERVICE|LocalService|NetworkService)') { $o.Add('        Anmeldekonto: ' + $s.StartName) }
        if (-not $isTrig -and $null -ne $s.ExitCode -and $s.ExitCode -ne 0 -and $s.ExitCode -ne 1077) { $o.Add('        Letzter Windows-Exitcode: ' + $s.ExitCode) }
    }
    $o.Add('')
    if ($echt.Count) { $o.Add('Mit "Nicht startende Dienste reparieren" werden Kerndienste auf die Windows-Vorgabe gesetzt und (ohne zu blockieren) gestartet.') }
    return ($o -join "`r`n")
}
function Start-SvcNonBlocking([string]$Name) {
    # Startkommando senden und sofort zurueckkehren (ServiceController.Start() wartet nicht)
    try {
        $sc = Get-Service -Name $Name -ErrorAction Stop
        if ($sc.Status -eq 'Running') { return 'running' }
        if ($sc.Status -eq 'Stopped' -or $sc.Status -eq 'Paused') { $sc.Start(); return 'started' }
        return 'pending'
    } catch { return 'err:' + (($_.Exception.Message -replace '\s+', ' ').Trim()) }
}
function Repair-StuckSvcText([object[]]$Core) {
    $trig = Get-SvcTriggerMap
    $o = [System.Collections.Generic.List[string]]::new()
    $o.Add('== Starttyp der Kerndienste auf die Windows-Vorgabe setzen =='); $chg = 0
    foreach ($d in $Core) {
        $s = $null; try { $s = Get-CimInstance Win32_Service -Filter ("Name='{0}'" -f $d.Name) -ErrorAction Stop } catch { }
        if (-not $s) { continue }
        $want = switch ([int]$d.Start) { 2 { 'Automatic' } 3 { 'Manual' } 4 { 'Disabled' } default { 'Manual' } }
        $curN = switch ([string]$s.StartMode) { 'Auto' { 'Automatic' } 'Manual' { 'Manual' } 'Disabled' { 'Disabled' } default { [string]$s.StartMode } }
        if ($curN -ne $want) { try { Set-Service -Name $d.Name -StartupType $want -ErrorAction Stop; $o.Add(('  {0}: {1} -> {2}' -f $d.Label, $curN, $want)); $chg++ } catch { $o.Add(('  {0}: Starttyp aendern fehlgeschlagen: {1}' -f $d.Label, ($_.Exception.Message -replace '\s+', ' '))) } }
    }
    if (-not $chg) { $o.Add('  (alle Kerndienste haben bereits den richtigen Starttyp)') }

    # Falsche svchost-Dienstgruppe (Prozess startet, Dienst wird nie uebergeben -> haengt ewig)
    $o.Add(''); $o.Add('== Dienstgruppen pruefen (svchost) ==')
    $hostMap = Get-SvcHostGroupMap; $grpFixed = 0
    if (-not $hostMap.Count) { $o.Add('  (Gruppenliste nicht lesbar - uebersprungen)') }
    else {
        $bakDir = Join-Path $env:PUBLIC ('Documents\PC-Tools-Dienstsicherung\' + (Get-Date -Format 'yyyyMMdd_HHmmss'))
        foreach ($s in @(Get-CimInstance Win32_Service -ErrorAction SilentlyContinue | Where-Object { $_.State -ne 'Running' -and $_.StartMode -ne 'Disabled' })) {
            $k = 'HKLM:\SYSTEM\CurrentControlSet\Services\' + $s.Name
            $raw = [string](Get-ItemProperty -LiteralPath $k -ErrorAction SilentlyContinue).ImagePath
            $hg = @(Get-SvcHostGroupsFor $hostMap ([string]$s.Name))
            $new = Get-SvcHostGroupFix $raw $hg
            if (-not $new) { continue }
            try {
                New-Item $bakDir -ItemType Directory -Force | Out-Null
                & reg.exe export ('HKLM\SYSTEM\CurrentControlSet\Services\' + $s.Name) (Join-Path $bakDir ($s.Name + '.reg')) /y | Out-Null
                Set-ItemProperty -LiteralPath $k -Name ImagePath -Value $new -Type ExpandString -ErrorAction Stop
                $o.Add(('  {0}: Dienstgruppe korrigiert ({1} -> {2})' -f $s.DisplayName, (Get-SvcHostGroupOf $raw), $hg[0])); $grpFixed++
            } catch { $o.Add(('  {0}: Dienstgruppe konnte nicht korrigiert werden: {1}' -f $s.DisplayName, ($_.Exception.Message -replace '\s+', ' '))) }
        }
        if ($grpFixed) { $o.Add(('  Sicherung: {0}' -f $bakDir)); $o.Add('  WICHTIG: Danach den PC NEU STARTEN - ein schon haengender Dienst kommt erst nach dem Neustart frei.') }
        else { $o.Add('  (alle Dienstgruppen stimmen)') }
    }

    $o.Add(''); $o.Add('== Dienste starten (ohne Blockieren, mit Zeitbegrenzung) ==')
    $started = [System.Collections.Generic.List[string]]::new(); $failed = @{}; $names = @{}
    $deadline = (Get-Date).AddSeconds(50)
    for ($pass = 1; $pass -le 5 -and (Get-Date) -lt $deadline; $pass++) {
        $auto = @(); try { $auto = @(Get-CimInstance Win32_Service -ErrorAction Stop | Where-Object { $_.StartMode -eq 'Auto' -and $_.State -eq 'Stopped' -and -not $trig.ContainsKey($_.Name) }) } catch { }
        if (-not $auto.Count) { break }
        $fired = $false
        foreach ($s in $auto) {
            $names[$s.Name] = $s.DisplayName
            # Abhaengigkeiten nicht blockierend anstossen
            try { $gs = Get-Service -Name $s.Name -ErrorAction Stop; foreach ($dep in @($gs.ServicesDependedOn | Where-Object { $_.Status -ne 'Running' })) { try { if ((Get-Service -Name $dep.Name -ErrorAction Stop).StartType -eq 'Disabled') { Set-Service -Name $dep.Name -StartupType Manual -ErrorAction SilentlyContinue }; [void](Start-SvcNonBlocking $dep.Name) } catch { } } } catch { }
            $res = Start-SvcNonBlocking $s.Name
            if ($res -eq 'started') { $fired = $true }
            elseif ($res -like 'err:*') { $failed[$s.Name] = @{ D = $s.DisplayName; E = $res.Substring(4) } }
        }
        Start-Sleep -Milliseconds 2000  # kurz warten bis die Dienste hochkommen (gesamt begrenzt)
        if (-not $fired) { break }
    }
    # Endstand erheben
    foreach ($n in $names.Keys) {
        $run = $false; try { $run = ((Get-Service -Name $n -ErrorAction Stop).Status -eq 'Running') } catch { }
        if ($run) { [void]$started.Add($names[$n]); $failed.Remove($n) }
        elseif (-not $failed.ContainsKey($n)) { $failed[$n] = @{ D = $names[$n]; E = 'startet nicht (bleibt gestoppt)' } }
    }
    if ($started.Count) { foreach ($x in ($started | Select-Object -Unique)) { $o.Add('  gestartet: ' + $x) } } else { $o.Add('  (keine zusaetzlichen Dienste gestartet)') }
    if ($failed.Count) {
        $o.Add(''); $o.Add('== Starten weiterhin nicht =='); foreach ($k in $failed.Keys) { $o.Add(('  {0} ({1}): {2}' -f $failed[$k].D, $k, $failed[$k].E)) }
        $o.Add(''); $o.Add('Bleiben Dienste rot, fehlt oft die Programmdatei/ein Treiber oder die Registrierung ist beschaedigt - dann hilft DISM/SFC oder eine Reparaturinstallation (Seite Windows-Reparatur). Bei Surface zusaetzlich das Surface-Treiber-/Firmwarepaket einspielen.')
    } else { $o.Add(''); $o.Add('Alle reparierbaren Dienste laufen jetzt.') }
    return ($o -join "`r`n")
}
# ---- Windows-Reparatur: Auswertungen (ohne Windows testbar, laufen auch in Invoke-Bg)
function ConvertFrom-WrBytes([byte[]]$Bytes) {
    # sfc.exe schreibt umgeleitet UTF-16LE, andere Programme die OEM-Codepage - hier automatisch erkennen
    if (-not $Bytes -or $Bytes.Length -eq 0) { return '' }
    $max = [math]::Min($Bytes.Length, 4000); $zero = 0; $pairs = 0
    for ($i = 1; $i -lt $max; $i += 2) { $pairs++; if ($Bytes[$i] -eq 0) { $zero++ } }
    $uni = (($Bytes.Length -ge 2) -and ($Bytes[0] -eq 0xFF) -and ($Bytes[1] -eq 0xFE)) -or ($pairs -gt 0 -and ($zero / $pairs) -gt 0.3)
    if ($uni) { $t = [Text.Encoding]::Unicode.GetString($Bytes) }
    else {
        $enc = $null
        try { $enc = [Text.Encoding]::GetEncoding([Globalization.CultureInfo]::CurrentCulture.TextInfo.OEMCodePage) } catch { $enc = [Text.Encoding]::UTF8 }
        $t = $enc.GetString($Bytes)
    }
    return (($t -replace "`0", '') -replace ([string][char]0xFEFF), '')
}
function Get-WrDismVerdict([string]$Text) {
    $t = ([string]$Text) -replace "`0", ''
    $code = ''; $m = [regex]::Match($t, '(?im)^\s*(Fehler|Error)\s*:\s*(0x[0-9a-f]{8}|-?\d+)\b')
    if ($m.Success) { $code = $m.Groups[2].Value }
    $state = 'Unknown'
    if ($t -match '(?i)kann nicht repariert werden|cannot be repaired|nicht reparierbar') { $state = 'NotRepairable' }
    elseif ($t -match '(?i)Wiederherstellungsvorgang wurde erfolgreich|restore operation completed successfully') { $state = 'Repaired' }
    elseif ($t -match '(?i)kann repariert werden|is repairable|\breparierbar') { $state = 'Repairable' }
    elseif ($t -match '(?i)keine Komponentenspeicherbesch|No component store corruption') { $state = 'Healthy' }
    elseif ($code) { $state = 'Error' }
    elseif ($t -match '(?i)Vorgang wurde erfolgreich|operation completed successfully') { $state = 'Ok' }
    $src = $code -match '(?i)^0x800f(081f|0906|0907|0950)$'
    $txt = switch ($state) {
        'Healthy'       { 'Keine Beschädigung im Komponentenspeicher.' }
        'Repairable'    { 'Der Komponentenspeicher ist beschädigt, aber reparierbar - "Windows-Abbild reparieren" ausführen.' }
        'NotRepairable' { 'Der Komponentenspeicher ist nicht mehr reparierbar - Reparaturinstallation (In-place Upgrade) nötig.' }
        'Repaired'      { 'Die Reparatur wurde erfolgreich abgeschlossen.' }
        'Ok'            { 'Vorgang erfolgreich beendet.' }
        'Error'         {
            if ($src) { 'Quelldateien nicht gefunden ({0}) - eine Windows-ISO in derselben Version, Edition und Sprache als Reparaturquelle angeben.' -f $code }
            elseif ($code -match '(?i)^(0x80070005|5)$') { 'Zugriff verweigert ({0}) - als Administrator ausführen, Virenschutz prüfen.' -f $code }
            elseif ($code -match '(?i)^0x800f082f$') { 'Komponentenspeicher-Konfiguration fehlerhaft ({0}) - Reparaturinstallation empfohlen.' -f $code }
            elseif ($code -match '(?i)^0x800f0922$') { 'Verarbeitung fehlgeschlagen ({0}) - meist fehlende Internetverbindung oder zu kleine Systempartition.' -f $code }
            elseif ($code -match '(?i)^0x800f0831$') { 'Ein Basispaket fehlt ({0}) - ISO der exakt installierten Version als Quelle angeben.' -f $code }
            elseif ($code -match '(?i)^(0x800700b7|0x80070020)$') { 'Datei ist gesperrt ({0}) - PC neu starten und erneut versuchen.' -f $code }
            else { 'DISM meldet Fehler {0} - Details in C:\Windows\Logs\DISM\dism.log.' -f $code }
        }
        default         { 'Ergebnis nicht erkannt - Ausgabe im Protokoll prüfen.' }
    }
    return [pscustomobject]@{ State = $state; Code = $code; SourceMissing = [bool]$src; Text = $txt }
}
function Get-WrDismAnalyze([string]$Text) {
    $r = [ordered]@{ Actual = ''; Shared = ''; Backups = ''; Cache = ''; LastCleanup = ''; Reclaimable = -1; Recommended = $null }
    foreach ($l in (([string]$Text) -replace "`0", '' -split "`r?`n")) {
        $m = [regex]::Match($l, '^\s*(.+?)\s*:\s*(.+?)\s*$'); if (-not $m.Success) { continue }
        $k = $m.Groups[1].Value; $v = $m.Groups[2].Value
        if ($k -match '(?i)Tats.chliche Gr.+e|Actual Size') { $r.Actual = $v }
        elseif ($k -match '(?i)geteilt|Shared with Windows') { $r.Shared = $v }
        elseif ($k -match '(?i)Sicherungen|Backups and Disabled') { $r.Backups = $v }
        elseif ($k -match '(?i)Cache und|Cache and Temporary') { $r.Cache = $v }
        elseif ($k -match '(?i)letzten Bereinigung|Last Cleanup') { $r.LastCleanup = $v }
        elseif ($k -match '(?i)freigebbar|zurückgewinnbar|Reclaimable') { $n = [regex]::Match($v, '\d+'); if ($n.Success) { $r.Reclaimable = [int]$n.Value } }
        elseif ($k -match '(?i)empfohlen|Recommended') { $r.Recommended = ($v -match '(?i)^(Ja|Yes)') }
    }
    return [pscustomobject]$r
}
function Get-WrSfcVerdict([string]$Text) {
    $t = ([string]$Text) -replace "`0", ''
    $state = 'Unknown'
    if ($t -match '(?i)keine Integrit\S{0,3}tsverletzungen|did not find any integrity violations') { $state = 'Clean' }
    elseif ($t -match '(?i)einige davon nicht|konnte jedoch einige|unable to fix some|could not repair some') { $state = 'Partial' }
    elseif ($t -match '(?i)erfolgreich repariert|successfully repaired') { $state = 'Repaired' }
    elseif ($t -match '(?i)Systemreparatur.{0,40}aus|system repair pending') { $state = 'Pending' }
    elseif ($t -match '(?i)Reparaturdienst nicht starten|could not start the repair service') { $state = 'ServiceFail' }
    elseif ($t -match '(?i)angeforderten Vorgang nicht|could not perform the requested operation') { $state = 'Failed' }
    elseif ($t -match '(?i)Integrit\S{0,3}tsverletzungen gefunden|found integrity violations|besch\S{0,3}digte Dateien gefunden|found corrupt files') { $state = 'Found' }
    $txt = switch ($state) {
        'Clean'       { 'Keine beschädigten Systemdateien gefunden.' }
        'Repaired'    { 'Beschädigte Systemdateien gefunden und repariert.' }
        'Partial'     { 'Beschädigte Dateien gefunden, einige konnten NICHT repariert werden - zuerst "Windows-Abbild reparieren" (DISM), dann SFC erneut; hilft das nicht: Reparaturinstallation.' }
        'Found'       { 'Beschädigte Systemdateien gefunden (nur geprüft) - "Systemdateien prüfen und reparieren" ausführen.' }
        'Pending'     { 'Eine Systemreparatur wartet auf einen Neustart - neu starten und SFC erneut ausführen.' }
        'ServiceFail' { 'Der Reparaturdienst (Windows Modules Installer) startet nicht - Kerndienste auf Standard setzen und neu starten.' }
        'Failed'      { 'SFC konnte nicht arbeiten - im abgesicherten Modus oder aus WinRE erneut versuchen, vorher DISM.' }
        default       { 'Ergebnis nicht erkannt - Auswertung der CBS.log beachten.' }
    }
    return [pscustomobject]@{ State = $state; Text = $txt }
}
function ConvertFrom-WrCbsLines([string[]]$Lines) {
    # CBS.log ist auch auf deutschem Windows englisch; SFC-Zeilen tragen [SR], die Hash-Meldungen des Prüflaufs nicht
    $list = [System.Collections.Generic.List[object]]::new(); $hash = [System.Collections.Generic.List[object]]::new()
    $ci = [Globalization.CultureInfo]::InvariantCulture
    foreach ($l in $Lines) {
        $sr = $l -match '\[SR\]'
        if (-not $sr -and $l -notmatch 'Hashes for file member') { continue }
        $m = [regex]::Match($l, '^(\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2})')
        if (-not $m.Success) { continue }
        $o = [pscustomobject]@{ T = [datetime]::ParseExact($m.Groups[1].Value, 'yyyy-MM-dd HH:mm:ss', $ci); L = $l }
        if ($sr) { $list.Add($o) } else { $hash.Add($o) }
    }
    if (-not $list.Count) { return [pscustomobject]@{ Found = $false; Start = $null; End = $null; Verified = 0; Repaired = @(); Failed = @(); Corrupt = @(); Mode = ''; Complete = $false; Verdict = 'Kein SFC-Lauf in der CBS.log gefunden.' } }
    $e = $list.Count - 1; $s = $e
    while ($s -gt 0 -and ($list[$s].T - $list[$s - 1].T).TotalMinutes -le 15) { $s-- }
    $ver = 0; $rep = [System.Collections.Generic.List[string]]::new(); $bad = [System.Collections.Generic.List[string]]::new(); $cor = [System.Collections.Generic.List[string]]::new()
    $repairMode = $false; $complete = $false
    for ($i = $s; $i -le $e; $i++) {
        $l = $list[$i].L
        $m = [regex]::Match($l, 'Verifying (\d+) component'); if ($m.Success) { $ver += [int]$m.Groups[1].Value }
        if ($l -match 'Verify and Repair|Repairing \d+ component|Repair complete') { $repairMode = $true }
        if ($l -match 'Verify complete|Repair complete|Transaction completed') { $complete = $true }
        $m = [regex]::Match($l, '(?:Repairing corrupted file|Repaired file) \[[^\]]*\]"([^"]+)"\\\[[^\]]*\]"([^"]+)"')
        if ($m.Success) { $p = ($m.Groups[1].Value -replace '^\\\?\?\\', '') + '\' + $m.Groups[2].Value; if (-not $rep.Contains($p)) { $rep.Add($p) }; continue }
        $m = [regex]::Match($l, 'Cannot repair member file \[[^\]]*\]"([^"]+)"(?: of ([^,]+))?')
        if ($m.Success) { $p = $m.Groups[1].Value + $(if ($m.Groups[2].Success) { ' (' + $m.Groups[2].Value.Trim() + ')' } else { '' }); if (-not $bad.Contains($p)) { $bad.Add($p) }; continue }
        $m = [regex]::Match($l, 'Could not reproject corrupted file \[[^\]]*\]"([^"]+)"\\\[[^\]]*\]"([^"]+)"')
        if ($m.Success) { $p = ($m.Groups[1].Value -replace '^\\\?\?\\', '') + '\' + $m.Groups[2].Value; if (-not $bad.Contains($p)) { $bad.Add($p) }; continue }
    }
    $t0 = $list[$s].T.AddSeconds(-5); $t1 = $list[$e].T.AddSeconds(5)
    foreach ($h in $hash) {
        if ($h.T -lt $t0 -or $h.T -gt $t1) { continue }
        $m = [regex]::Match($h.L, 'Hashes for file member (?:\[[^\]]*\])?"?([^"]+?)"? do not match')
        if ($m.Success) { $f = ($m.Groups[1].Value -replace '^\\\?\?\\', '').Trim(); if (-not $cor.Contains($f) -and -not $rep.Contains($f)) { $cor.Add($f) } }
    }
    $mode = if ($repairMode) { 'Prüfen und reparieren' } else { 'Nur prüfen' }
    $verdict = if ($bad.Count) { '{0} Datei(en) konnten NICHT repariert werden.' -f $bad.Count }
               elseif ($rep.Count) { '{0} Datei(en) repariert, keine offenen Fehler.' -f $rep.Count }
               elseif ($cor.Count) { '{0} beschädigte Datei(en) gefunden (nur geprüft).' -f $cor.Count }
               else { 'Keine beschädigten Dateien.' }
    return [pscustomobject]@{ Found = $true; Start = $list[$s].T; End = $list[$e].T; Verified = $ver; Repaired = @($rep); Failed = @($bad); Corrupt = @($cor); Mode = $mode; Complete = $complete; Verdict = $verdict }
}
function Get-WrCbsSummary([string]$Path = '') {
    if (-not $Path) { $Path = Join-Path $env:windir 'Logs\CBS\CBS.log' }
    if (-not [IO.File]::Exists($Path)) { return (ConvertFrom-WrCbsLines @()) }
    $fs = New-Object IO.FileStream($Path, [IO.FileMode]::Open, [IO.FileAccess]::Read, [IO.FileShare]'ReadWrite, Delete')
    try {
        $len = [int64]$fs.Length; $max = [int64]24MB
        if ($len -gt $max) { [void]$fs.Seek($len - $max, [IO.SeekOrigin]::Begin) }
        $sr = New-Object IO.StreamReader($fs, [Text.Encoding]::UTF8)
        $txt = $sr.ReadToEnd()
    } finally { $fs.Dispose() }
    return (ConvertFrom-WrCbsLines ($txt -split "`r?`n"))
}
function ConvertFrom-WrReagentc([string]$Text) {
    $st = [regex]::Match([string]$Text, '(?im)Windows RE[- ]?(?:Status|state)\s*:\s*(\S+)')
    $lo = [regex]::Match([string]$Text, '(?im)Windows RE[- ]?(?:Speicherort|location|Ort)\s*:\s*(.*?)\s*$')
    $v = if ($st.Success) { $st.Groups[1].Value } else { '' }
    return [pscustomobject]@{ Enabled = ($v -match '(?i)^(Enabled|Aktiviert)'); Status = $v; Location = $(if ($lo.Success) { $lo.Groups[1].Value } else { '' }) }
}
function Get-WrBcdInfo([string]$Text) {
    $g = { param($n) $m = [regex]::Match([string]$Text, ('(?im)^' + $n + '\s+(.+?)\s*$')); if ($m.Success) { $m.Groups[1].Value } else { '' } }
    $path = & $g 'path'
    return [pscustomobject]@{ SafeBoot = (& $g 'safeboot'); BootLog = ((& $g 'bootlog') -match '(?i)^(Yes|Ja)$'); Path = $path; Uefi = ($path -match '(?i)winload\.efi'); Hypervisor = (& $g 'hypervisorlaunchtype') }
}
function Get-WrNormPath([string]$p) {
    $x = ([string]$p).Trim().Trim('"').ToLower() -replace '"', ''
    $x = $x -replace '^%systemroot%\\', '' -replace '^\\systemroot\\', '' -replace '^\\\?\?\\c:\\windows\\', '' -replace '^c:\\windows\\', '' -replace '^%windir%\\', ''
    return (($x -replace '\s+', ' ').Trim())
}
function Get-SvcHostGroupMap {
    # Dienstname (klein) -> svchost-Gruppen, die ihn laut diesem Windows beherbergen
    # (HKLM\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Svchost). Die Gruppe eines Dienstes
    # wechselt zwischen Windows-Versionen - daher nie aus einer festen Tabelle nehmen.
    # Steht ein Dienst in mehreren Gruppen, kommt die kleinste zuerst (eine eigene Gruppe nur fuer ihn
    # ist die von Windows vorgesehene, z.B. LocalServiceHttp fuer WinHttpAutoProxySvc).
    $raw = @{}; $size = @{}
    try {
        $p = Get-ItemProperty -LiteralPath 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Svchost' -ErrorAction Stop
        foreach ($prop in $p.PSObject.Properties) {
            if ($prop.Name -in 'PSPath', 'PSParentPath', 'PSChildName', 'PSDrive', 'PSProvider') { continue }
            if ($prop.Value -isnot [array]) { continue }
            $members = @(@($prop.Value) | ForEach-Object { ([string]$_).Trim().ToLower() } | Where-Object { $_ })
            $size[[string]$prop.Name] = $members.Count
            foreach ($k in $members) {
                if (-not $raw.ContainsKey($k)) { $raw[$k] = @() }
                $raw[$k] += [string]$prop.Name
            }
        }
    } catch { }
    $map = @{}
    foreach ($k in $raw.Keys) { $map[$k] = @($raw[$k] | Sort-Object { $size[$_] }, { $_ }) }
    return $map
}
function Get-SvcHostGroupsFor([hashtable]$Map, [string]$Name) {
    # Pro-Benutzer-Dienste (z.B. CDPUserSvc_b270d) stehen nie selbst in einer Gruppenliste,
    # sondern unter dem Namen ihrer Vorlage - dann ueber den Grundnamen nachschlagen
    $n = ([string]$Name).ToLower()
    $g = @($Map[$n] | Where-Object { $_ })
    if (-not $g.Count -and $n -match '^(.+)_[0-9a-f]{4,8}$') { $g = @($Map[$Matches[1]] | Where-Object { $_ }) }
    return , $g
}
function Get-SvcHostGroupOf([string]$ImagePath) {
    $m = [regex]::Match([string]$ImagePath, '(?i)svchost\.exe"?\s+-k\s+(\S+)')
    if ($m.Success) { return $m.Groups[1].Value } else { return '' }
}
function Get-SvcHostGroupFix([string]$ImagePath, [string[]]$HostGroups) {
    # Liefert den korrigierten Startpfad, wenn der Dienst in einer Gruppe gestartet wird, die ihn
    # nicht kennt (Prozess startet, Dienst wird nie uebergeben -> haengt ewig in "Wird gestartet").
    # Leer = alles in Ordnung bzw. nicht entscheidbar.
    $hg = @($HostGroups | Where-Object { $_ })
    if (-not $hg.Count) { return '' }
    $cg = Get-SvcHostGroupOf $ImagePath
    if (-not $cg) { return '' }
    if (@($hg | ForEach-Object { $_.ToLower() }) -contains $cg.ToLower()) { return '' }
    return [regex]::Replace([string]$ImagePath, '(?i)(-k\s+)\S+', ('${1}' + $hg[0]))
}
function Test-WrImagePath([string]$Def, [string]$Cur) {
    $c = Get-WrNormPath $Cur
    if ($Def -match '(?i)svchost\.exe\s+-k\s+(\S+)') { return ($c -match ('^system32\\svchost\.exe\s+-k\s+' + [regex]::Escape($Matches[1].ToLower()) + '(\s|$)')) }
    if (-not $c) { return $true }   # Treiber ohne ImagePath: Windows nimmt den Standardpfad
    return ($c -eq (Get-WrNormPath $Def))
}
function Compare-WrSvcEntry($Def, $Cur, [string]$Group = 'Netzwerk') {
    $msSvc = @('rpcss', 'rpceptmapper', 'dcomlaunch', 'nsi', 'nsiproxy', 'afd', 'tdx', 'tcpip', 'tcpip6', 'dhcp', 'dnscache', 'eventlog', 'winhttpautoproxysvc', 'bfe', 'mpsdrv', 'mpssvc', 'nlasvc', 'netprofm', 'ndisuio', 'nativewifip', 'wcmsvc', 'eaphost', 'ndis', 'winmgmt', 'samss', 'lanmanworkstation', 'http', 'keyiso', 'netbt', 'wfplwfs', 'profsvc', 'cryptsvc')
    $rows = [System.Collections.Generic.List[object]]::new()
    $label = if ($Def.Label) { [string]$Def.Label } else { [string]$Def.Name }
    $mk = { param($f, $ist, $soll, $lvl, $fix, $txt) $rows.Add([pscustomobject]@{ Gruppe = $Group; Dienst = [string]$Def.Name; Name = $label; Feld = $f; Ist = [string]$ist; Soll = [string]$soll; Stufe = $lvl; Hinweis = [string]$txt; Fix = $fix }) }
    $sn = { param($v) if ($null -eq $v -or [string]$v -eq '') { '(fehlt)' } else { switch ([int]$v) { 0 { 'Boot' } 1 { 'System' } 2 { 'Automatisch' } 3 { 'Manuell' } 4 { 'Deaktiviert' } default { [string]$v } } } }
    if (-not $Cur -or -not $Cur.Exists) { & $mk 'Dienst' 'fehlt' 'vorhanden' 'Problem' $null 'Der Registrierungsschlüssel fehlt - Windows-Abbild und Systemdateien reparieren, sonst Reparaturinstallation.'; return $rows.ToArray() }
    if ($null -ne $Def.Start) {
        $cs = $Cur.Start
        if ($null -eq $cs -or [string]$cs -eq '' -or [int]$cs -ne [int]$Def.Start) {
            $prob = ($null -eq $cs -or [string]$cs -eq '') -or ([int]$cs -eq 4 -and [int]$Def.Start -ne 4) -or ([int]$Def.Start -le 1 -and [int]$cs -gt [int]$Def.Start)
            $txt = if ($Def.Optional -and $prob) { 'Ist ausgeschaltet - wird oft absichtlich abgeschaltet (z.B. Druckdienst zur Absicherung). Nur zur Information, wird nicht automatisch geändert.' } elseif ($prob) { if ($Def.Note) { 'Startet nicht wie vorgesehen. ' + $Def.Note } else { 'Startet nicht wie vorgesehen.' } } elseif ($Def.Optional) { 'Wird oft absichtlich abgeschaltet (z.B. Druckdienst zur Absicherung) - nur zur Information, wird nicht automatisch geändert.' } elseif ($Def.Loose) { 'Die Vorgabe unterscheidet sich je nach Windows-Version - nur zur Information, wird nicht geändert.' } else { 'Weicht von der Vorgabe ab, stört aber meist nicht.' }
            $sfix = if (($Def.Loose -and -not $prob) -or $Def.Optional) { $null } else { @{ Name = [string]$Def.Name; Field = 'Start'; Value = [int]$Def.Start } }
            & $mk 'Starttyp' (& $sn $cs) (& $sn $Def.Start) $(if ($prob) { 'Problem' } else { 'Hinweis' }) $sfix $txt
        }
    }
    if ($Def.Img) {
        $curImg = [string]$Cur.ImagePath
        $hg = @($Cur.HostGroups | Where-Object { $_ })
        if (([string]$Def.Img) -match '(?i)svchost\.exe\s+-k\s+\S+') {
            # svchost-Dienst: die Gruppe NICHT aus der Tabelle erzwingen (sie wechselt je nach Windows-Version),
            # sondern pruefen, ob die Gruppe im Startpfad den Dienst in diesem Windows auch wirklich kennt.
            $isHost = (Get-WrNormPath $curImg) -match '^system32\\svchost\.exe\s+-k\s+\S+'
            if ($isHost -and -not $hg.Count -and $Cur.HostMapOk) {
                & $mk 'Dienstgruppe' $curImg '(in einer svchost-Gruppe eingetragen)' 'Problem' $null ("Der Dienst steht in keiner svchost-Gruppe dieses Windows - der Prozess startet dann, findet den Dienst aber nicht (haengt in 'Wird gestartet'). Gruppe '{0}' pruefen bzw. Reparaturinstallation." -f (Get-SvcHostGroupOf $curImg))
            } elseif ($isHost) {
                $want = Get-SvcHostGroupFix $curImg $hg
                if ($want) {
                    & $mk 'Dienstgruppe' $curImg $want 'Problem' @{ Name = [string]$Def.Name; Field = 'ImagePath'; Value = $want } ("Falsche Dienstgruppe: Der Startpfad nennt '{0}', dieses Windows fuehrt den Dienst aber in '{1}'. Der Dienst haengt dann dauerhaft in 'Wird gestartet' (oft nach Tuning-Programmen oder veralteten Reparatur-Tabellen)." -f (Get-SvcHostGroupOf $curImg), $hg[0])
                }
            } else {
                $grp = if ($hg.Count) { $hg[0] } else { Get-SvcHostGroupOf ([string]$Def.Img) }
                $want = '%SystemRoot%\system32\svchost.exe -k ' + $grp + ' -p'
                & $mk 'Programmpfad' $curImg $want 'Problem' @{ Name = [string]$Def.Name; Field = 'ImagePath'; Value = $want } 'Zeigt nicht auf die Windows-Datei - von Schadsoftware, Tuning- oder Sicherheitsprogrammen verändert.'
            }
        } elseif (-not (Test-WrImagePath ([string]$Def.Img) $curImg)) {
            & $mk 'Programmpfad' $curImg ([string]$Def.Img) 'Problem' @{ Name = [string]$Def.Name; Field = 'ImagePath'; Value = [string]$Def.Img } 'Zeigt nicht auf die Windows-Datei - von Schadsoftware, Tuning- oder Sicherheitsprogrammen verändert.'
        }
    }
    $isDrv = ([string]$Def.Img) -match '\.sys$'
    if (-not $isDrv -and ($null -ne $Def.Req -or $null -ne $Def.Allow)) {
        $cur = @(@($Cur.Depend) | Where-Object { $_ } | ForEach-Object { [string]$_ })
        $low = @($cur | ForEach-Object { $_.ToLower() })
        $missing = @(@($Def.Req) | Where-Object { $_ -and ($low -notcontains ([string]$_).ToLower()) })
        $known = @(@($Def.Req) + @($Def.Allow) | Where-Object { $_ } | ForEach-Object { ([string]$_).ToLower() }) + $msSvc
        $foreign = @($cur | Where-Object { $known -notcontains $_.ToLower() })
        if ($missing.Count -or $foreign.Count) {
            $new = @($cur | Where-Object { $known -contains $_.ToLower() }) + $missing
            $t = @(); if ($missing.Count) { $t += ('fehlt: ' + ($missing -join ', ')) }; if ($foreign.Count) { $t += ('fremd: ' + ($foreign -join ', ') + ' - ein fremder Dienst als Voraussetzung kann den Start blockieren') }
            & $mk 'Abhängigkeiten' ($cur -join ', ') ($new -join ', ') 'Problem' @{ Name = [string]$Def.Name; Field = 'DependOnService'; Value = [string[]]$new } ($t -join '; ')
        }
    }
    return $rows.ToArray()
}
function Get-WrSvcDiff([object[]]$Defs, [string]$Group = 'Netzwerk') {
    $all = [System.Collections.Generic.List[object]]::new()
    $hostMap = Get-SvcHostGroupMap
    foreach ($d in $Defs) {
        $k = 'HKLM:\SYSTEM\CurrentControlSet\Services\' + $d.Name
        $cur = @{ Exists = $false; Start = $null; ImagePath = ''; Depend = @(); HostGroups = @(Get-SvcHostGroupsFor $hostMap ([string]$d.Name)); HostMapOk = ($hostMap.Count -gt 0) }
        if (Test-Path -LiteralPath $k) {
            $p = Get-ItemProperty -LiteralPath $k -ErrorAction SilentlyContinue
            $cur.Exists = $true; $cur.Start = $p.Start; $cur.ImagePath = [string]$p.ImagePath; $cur.Depend = @($p.DependOnService)
        }
        foreach ($r in @(Compare-WrSvcEntry $d $cur $Group)) { if ($r) { $all.Add($r) } }
    }
    return $all.ToArray()
}
function Get-WrSddlAces([string]$Sddl) {
    $d = [string]$Sddl; $i = $d.IndexOf('D:'); if ($i -lt 0) { return @() }
    $d = $d.Substring($i + 2); $j = $d.IndexOf('S:'); if ($j -ge 0) { $d = $d.Substring(0, $j) }
    $res = foreach ($m in [regex]::Matches($d, '\(([^)]*)\)')) {
        $f = $m.Groups[1].Value -split ';'
        if ($f.Count -lt 6) { continue }
        $tok = if ($f[2] -match '^0x') { @('HEX:' + $f[2]) } else { @([regex]::Matches($f[2], '..') | ForEach-Object { $_.Value.ToUpper() }) }
        [pscustomobject]@{ Type = $f[0].ToUpper(); Rights = $tok; Sid = $f[5].ToUpper() }
    }
    return @($res)
}
function Test-WrSddl([string]$Sddl) {
    # Standard-Rechte vorhanden? SYSTEM und Administratoren dürfen starten/stoppen/abfragen, angemeldete Benutzer dürfen abfragen, kein Verweigern
    $aces = @(Get-WrSddlAces $Sddl)
    if (-not $aces.Count) { return $false }
    if (@($aces | Where-Object { $_.Type -eq 'D' -and $_.Sid -in 'SY', 'BA', 'AU', 'IU', 'BU', 'WD' }).Count) { return $false }
    $has = { param($sids, [string[]]$need) foreach ($a in $aces) { if ($a.Type -ne 'A' -or $sids -notcontains $a.Sid) { continue }; if ($a.Rights -contains 'GA') { return $true }; $ok = $true; foreach ($n in $need) { if ($a.Rights -notcontains $n) { $ok = $false } }; if ($ok) { return $true } }; return $false }
    return ((& $has @('SY') @('CC', 'LC', 'RP', 'WP')) -and (& $has @('BA') @('CC', 'LC', 'RP', 'WP')) -and (& $has @('AU', 'IU', 'BU', 'WD') @('LC')))
}
function Get-WrDisabledComponentsText([int64]$Value) {
    if ($Value -eq 0) { return 'Wert 0 - Windows-Standard: IPv6 ist vollständig aktiv.' }
    $v = [int]($Value -band 0xFF)
    if ($v -eq 0xFF) { return 'Wert 0xFF - IPv6 ist komplett abgeschaltet (nur Loopback). Microsoft rät davon ab; Windows-Teile wie Heimnetzgruppe, DirectAccess und manche Dienste erwarten IPv6.' }
    $p = @()
    if ($v -band 0x01) { $p += 'IPv6 auf Tunnel-Schnittstellen aus' }
    if ($v -band 0x02) { $p += '6to4 aus' }
    if ($v -band 0x04) { $p += 'ISATAP aus' }
    if ($v -band 0x08) { $p += 'Teredo aus' }
    if ($v -band 0x10) { $p += 'IPv6 auf allen normalen Schnittstellen aus' }
    if ($v -band 0x20) { $p += 'IPv4 wird IPv6 vorgezogen' }
    if (-not $p.Count) { $p += 'unbekannte Bits' }
    return ('Wert 0x{0:X2} - {1}.' -f $v, ($p -join ', '))
}
function Get-WrFilterVerdict([string]$Name, [string]$Id) {
    $n = '{0} {1}' -f $Name, $Id
    $ms = ([string]$Id) -match '^(ms_|vms_)'
    $vendors = @(
        @('(?i)panda|nnsnah|psinaflt|psinprot|pskmad|nnsprv|watchguard', 'Panda / WatchGuard', 'AV'),
        @('(?i)bitdefender|bdfndis|bdfwfpf|gzflt', 'Bitdefender', 'AV'),
        @('(?i)kaspersky|kl_?ndis|klim\d|klwfp', 'Kaspersky', 'AV'),
        @('(?i)\beset\b|epfw|ekbdflt|eamonm', 'ESET', 'AV'),
        @('(?i)avast|\bavg\b|aswndis|aswmonflt|aswnetsec', 'Avast / AVG', 'AV'),
        @('(?i)norton|symantec|symnets|symtdi|symefa|gen digital', 'Norton / Symantec', 'AV'),
        @('(?i)mcafee|mfendis|mfewfp|mfefire', 'McAfee', 'AV'),
        @('(?i)sophos|sntp|hmpalert', 'Sophos', 'AV'),
        @('(?i)trend ?micro|tmwfp|tmlwf|tmeevw', 'Trend Micro', 'AV'),
        @('(?i)f-?secure|fsni\b|fses\b|withsecure', 'F-Secure / WithSecure', 'AV'),
        @('(?i)g ?data|gdwfp|gdkbfilter', 'G DATA', 'AV'),
        @('(?i)avira|avnetflt|avipbb', 'Avira', 'AV'),
        @('(?i)malwarebytes|mbam|mwac', 'Malwarebytes', 'AV'),
        @('(?i)webroot|wrkrn', 'Webroot', 'AV'),
        @('(?i)zonealarm|check ?point|vsdatant', 'Check Point / ZoneAlarm', 'AV'),
        @('(?i)comodo|cmdguard', 'Comodo', 'AV'),
        @('(?i)npcap|winpcap|\bnpf\b|netmon|\bnm3\b|wireshark', 'Paketmitschnitt (Npcap/WinPcap/Netmon)', 'Capture'),
        @('(?i)virtualbox|vboxnet|oracle_vbox', 'VirtualBox', 'Virt'),
        @('(?i)vmware|vmnetbridge|vmnetuserif', 'VMware', 'Virt'),
        @('(?i)openvpn|tap-?windows|tap0901|wintun|wireguard', 'OpenVPN / WireGuard', 'VPN'),
        @('(?i)cisco|anyconnect|secure client|vpnva|acsock', 'Cisco AnyConnect / Secure Client', 'VPN'),
        @('(?i)fortinet|forticlient|ftsvnic', 'FortiClient', 'VPN'),
        @('(?i)globalprotect|pangp|palo ?alto', 'Palo Alto GlobalProtect', 'VPN'),
        @('(?i)nordvpn|nordlynx|expressvpn|surfshark|protonvpn|cyberghost|hotspot shield|windscribe|zscaler', 'VPN-Dienst', 'VPN'),
        @('(?i)netlimiter|glasswire|killer|rivet|cfos|smartbyte', 'Traffic-Steuerung (Killer/cFos/SmartByte ...)', 'Tool')
    )
    $vendor = ''; $kind = ''
    foreach ($v in $vendors) { if ($n -match $v[0]) { $vendor = $v[1]; $kind = $v[2]; break } }
    if ($ms -and -not $vendor) { return [pscustomobject]@{ ThirdParty = $false; Vendor = 'Microsoft'; Kind = 'MS'; IsAv = $false; Text = 'Windows-Bestandteil' } }
    if (-not $vendor) { $vendor = 'Drittanbieter'; $kind = 'Other' }
    $txt = switch ($kind) {
        'AV'      { 'Virenschutz-Netzwerkfilter - häufigste Ursache für "DHCP-Anfrage geht raus, keine Antwort kommt an". Testweise lösen; hilft das, den Virenschutz vollständig deinstallieren (Hersteller-Entfernungstool).' }
        'VPN'     { 'VPN-Filter/-Adapter - kann Routen und DHCP umleiten. Testweise lösen oder VPN-Programm deinstallieren.' }
        'Capture' { 'Mitschnitt-Treiber - meist harmlos, alte Versionen stören aber gelegentlich. Testweise lösen.' }
        'Virt'    { 'Virtualisierungs-Brücke - kann den Adapter übernehmen. Testweise lösen.' }
        'Tool'    { 'Traffic-Steuerung - bekannt für Verbindungsprobleme. Testweise lösen oder deinstallieren.' }
        default   { 'Filter/Protokoll eines Drittanbieters - bei Netzwerkproblemen testweise lösen.' }
    }
    return [pscustomobject]@{ ThirdParty = $true; Vendor = $vendor; Kind = $kind; IsAv = ($kind -eq 'AV'); Text = $txt }
}
function ConvertFrom-WrPnpDrivers([string]$Text) {
    $res = [System.Collections.Generic.List[object]]::new(); $cur = $null
    foreach ($l in (([string]$Text) -split "`r?`n")) {
        $m = [regex]::Match($l, '^\s*([^:]+?)\s*:\s*(.*?)\s*$'); if (-not $m.Success) { continue }
        $k = $m.Groups[1].Value; $v = $m.Groups[2].Value
        if ($k -match '(?i)^(Ver.{1,2}ffentlichter Name|Published Name)$') { $cur = [ordered]@{ Inf = $v; Original = ''; Provider = ''; Class = ''; Version = ''; Signer = '' }; $res.Add($cur); continue }
        if (-not $cur) { continue }
        if ($k -match '(?i)^(Urspr.{1,2}nglicher Name|Original Name)$') { $cur.Original = $v }
        elseif ($k -match '(?i)^(Anbietername|Provider Name)$') { $cur.Provider = $v }
        elseif ($k -match '(?i)^(Klassenname|Class Name)$') { $cur.Class = $v }
        elseif ($k -match '(?i)^(Treiberversion|Driver Version)$') { $cur.Version = $v }
        elseif ($k -match '(?i)^(Signaturgebername|Signer Name)$') { $cur.Signer = $v }
    }
    return @($res | ForEach-Object { [pscustomobject]$_ })
}
function Get-WrEventHint([string]$Source) {
    switch -Regex ($Source) {
        '(?i)^(disk|Ntfs|stornvme|storahci|iaStor|volsnap|Microsoft-Windows-Ntfs)' { return 'Datenträger/Dateisystem - Laufwerk prüfen, Daten sichern.' }
        '(?i)Service Control Manager' { return 'Dienst startet nicht oder stürzt ab - Dienste-Vergleich ansehen.' }
        '(?i)Kernel-Power' { return 'Unerwartet ausgeschaltet oder neu gestartet (Strom, Akku, Absturz).' }
        '(?i)WHEA' { return 'Hardwarefehler (Prozessor, Arbeitsspeicher, PCIe) - Hardware-Test, BIOS aktualisieren.' }
        '(?i)WindowsUpdateClient' { return 'Update-Installation fehlgeschlagen - Profil "Windows Update reparieren".' }
        '(?i)Dhcp' { return 'DHCP-Client: keine Adresse erhalten - Netzwerk-Profil ausführen.' }
        '(?i)Tcpip|NDIS|NetBT|Netwtw|mrvl|Marvell|athw|rt640|e1d|e1i|Wlan' { return 'Netzwerk-/WLAN-Treiber - Adaptertreiber neu installieren, Hersteller-Treiber.' }
        '(?i)DistributedCOM' { return 'Meist harmlos (Berechtigungsmeldungen von Windows selbst).' }
        '(?i)BugCheck|WER-SystemErrorReporting|volmgr' { return 'Bluescreen - Seite Fehlerdaten zeigt die Ursache.' }
        '(?i)Display|nvlddmkm|amdkmdag|igfx|dxgkrnl' { return 'Grafiktreiber - aktualisieren.' }
        '(?i)Kernel-PnP' { return 'Gerät/Treiber konnte nicht geladen werden - Seite Treiber.' }
        '(?i)Time-Service' { return 'Zeitdienst - "Zeitdienst neu registrieren".' }
        '(?i)EventLog' { return 'Unerwartetes Herunterfahren protokolliert.' }
        '(?i)Kernel-Boot|Kernel-General' { return 'Start-/Kernelmeldung - bei Häufung Startprotokoll einschalten.' }
        '(?i)Winlogon|User Profile' { return 'Anmeldung/Profil - bei Häufung neues Benutzerprofil testen.' }
        default { return '' }
    }
}
function Get-WrEventGroups([object[]]$Events) {
    $rows = foreach ($g in @($Events | Where-Object { $_ } | Group-Object ProviderName)) {
        $s = @($g.Group | Sort-Object TimeCreated -Descending)
        $msg = ''; try { $msg = (([string]$s[0].Message) -split "`r?`n" | Where-Object { $_.Trim() } | Select-Object -First 1) } catch { }
        if ($msg.Length -gt 220) { $msg = $msg.Substring(0, 220) + ' ...' }
        [pscustomobject]@{
            Quelle = [string]$g.Name; Anzahl = [int]$g.Count; Kritisch = @($g.Group | Where-Object { [int]$_.Level -eq 1 }).Count
            Letztes = ([datetime]$s[0].TimeCreated).ToString('dd.MM. HH:mm'); Ids = ((@($g.Group | Group-Object Id | Sort-Object Count -Descending | Select-Object -First 4) | ForEach-Object { $_.Name }) -join ', ')
            Beispiel = $msg; Hinweis = (Get-WrEventHint ([string]$g.Name))
        }
    }
    return @($rows | Sort-Object @{ e = { $_.Kritisch }; Descending = $true }, @{ e = { $_.Anzahl }; Descending = $true })
}
function Get-WrSetupCodeText([int64]$Code) {
    $u = [uint32]($Code -band 0xFFFFFFFFL)
    $h = '0x{0:X8}' -f $u
    $t = switch ($h) {
        '0x00000000' { 'Setup ist fertig - der Neustart schließt die Reparaturinstallation ab.' }
        '0x00000BC2' { 'Setup ist fertig und wartet auf den Neustart.' }
        '0xC1900210' { 'Keine Kompatibilitätsprobleme gefunden.' }
        '0xC1900101' { 'Treiberfehler während der Installation - Treiber aktualisieren, Zubehör abziehen, Virenschutz (z.B. Panda) vorher deinstallieren.' }
        '0xC1900107' { 'Eine frühere Installation wartet noch auf Bereinigung - neu starten und erneut versuchen.' }
        '0xC1900200' { 'Der PC erfüllt die Mindestanforderungen nicht.' }
        '0xC1900202' { 'Der PC erfüllt die Mindestanforderungen nicht.' }
        '0xC1900204' { 'Die gewählte Übernahme ist nicht möglich - ISO passt nicht zu Edition, Sprache, Architektur oder ist älter als das installierte Windows.' }
        '0xC1900208' { 'Eine inkompatible App blockiert die Installation (häufig Virenschutz) - Details in den kopierten Setup-Protokollen (compat*.xml).' }
        '0xC1900209' { 'Inkompatible Software blockiert die Installation - Details in compat*.xml.' }
        '0xC190020E' { 'Zu wenig freier Speicherplatz (mindestens 20 GB auf C: frei machen).' }
        '0xC1900223' { 'Dynamische Updates konnten nicht geladen werden - ohne "Updates während der Installation" erneut versuchen.' }
        '0xC1800118' { 'Update-Metadaten beschädigt (WSUS) - Windows Update zurücksetzen.' }
        '0x80070070' { 'Zu wenig freier Speicherplatz.' }
        '0x800F0922' { 'Systemreservierte Partition zu klein oder keine Verbindung zu Update-Servern.' }
        '0x8007042B' { 'Setup wurde unerwartet beendet - Protokolle prüfen, Virenschutz deinstallieren, erneut versuchen.' }
        '0x80070005' { 'Zugriff verweigert - als Administrator starten, Virenschutz prüfen.' }
        '0xFFFFFFFF' { 'Setup wurde abgebrochen oder konnte nicht gestartet werden.' }
        default { 'Unbekannter Setup-Code - Details in C:\$WINDOWS.~BT\Sources\Panther\setupact.log bzw. den kopierten Protokollen.' }
    }
    return ('{0}: {1}' -f $h, $t)
}
function Get-WrArchName($a) {
    switch ([string]$a) { '0' { 'x86' } '5' { 'arm' } '9' { 'x64' } '12' { 'arm64' } 'AMD64' { 'x64' } 'ARM64' { 'arm64' } 'x86' { 'x86' } default { ([string]$a).ToLower() } }
}
function Test-WrIpuCompat($Inst, $Img) {
    # Prüft, ob eine Reparaturinstallation mit "Apps und Dateien behalten" möglich ist
    $why = [System.Collections.Generic.List[string]]::new(); $st = @{ L = 'ok' }
    $bad = { param($t) $why.Add($t); $st.L = 'bad' }
    $warn = { param($t) $why.Add($t); if ($st.L -ne 'bad') { $st.L = 'warn' } }
    if ([string]$Img.Arch -and [string]$Inst.Arch -and ([string]$Img.Arch).ToLower() -ne ([string]$Inst.Arch).ToLower()) { & $bad ('Architektur {0} statt {1}' -f $Img.Arch, $Inst.Arch) }
    $langs = @(@($Img.Langs) | ForEach-Object { ([regex]::Match([string]$_, '^[a-zA-Z]{2,3}-[a-zA-Z]{2,4}')).Value.ToLower() } | Where-Object { $_ })
    if ($Inst.Lang -and $langs.Count -and $langs -notcontains ([string]$Inst.Lang).ToLower()) { & $bad ('Sprache {0} statt {1}' -f ($langs -join '/'), $Inst.Lang) }
    $iv = [regex]::Match([string]$Img.Build, '(\d+)\.(\d+)\.(\d+)(?:\.(\d+))?')
    $ib = 0; $iu = 0; if ($iv.Success) { $ib = [int]$iv.Groups[3].Value; if ($iv.Groups[4].Success) { $iu = [int]$iv.Groups[4].Value } }
    if ($ib -and [int]$Inst.Build) {
        if ($ib -lt [int]$Inst.Build) {
            if ($Inst.Insider) { & $bad ('Build {0} ist älter als die installierte Insider-Build {1} - dafür wird eine passende Insider-ISO gebraucht (gleiche oder neuere Build)' -f $ib, $Inst.Build) }
            else { & $bad ('Build {0} ist älter als das installierte Windows ({1}) - Apps und Dateien könnten nicht behalten werden' -f $ib, $Inst.Build) }
        }
        elseif ($ib -eq [int]$Inst.Build -and $iu -and [int]$Inst.Ubr -and $iu -lt [int]$Inst.Ubr) { & $warn ('gleiche Build, aber älterer Update-Stand ({0}.{1} statt {2}.{3}) - mit "Updates während der Installation" wird nachgezogen' -f $ib, $iu, $Inst.Build, $Inst.Ubr) }
        elseif ($ib -gt [int]$Inst.Build) { & $warn ('neuere Build {0} - die Reparatur ist zugleich ein Upgrade' -f $ib) }
    }
    if ($Img.EditionId -and $Inst.EditionId -and [string]$Img.EditionId -ne [string]$Inst.EditionId) { & $warn ('andere Edition ({0} statt {1}) - Setup wählt bei Mehrfach-ISOs automatisch die passende' -f $Img.EditionId, $Inst.EditionId) }
    if (-not $why.Count) { $why.Add('passt: gleiche Edition, Sprache und Architektur, Build gleich') }
    return [pscustomobject]@{ Level = $st.L; Text = ($why -join '; ') }
}
function Get-WrIpHint($Row) {
    $h = @(); $lvl = 'ok'
    if (-not $Row.Bound) { $h += 'IPv4 ist am Adapter ausgeschaltet'; $lvl = 'bad' }
    $stat = @(@($Row.RegIp) | Where-Object { $_ -and $_ -ne '0.0.0.0' })
    if ([int]$Row.EnableDhcp -eq 0) {
        if (-not $stat.Count) { $h += 'DHCP aus, aber keine feste Adresse - so kann der Adapter keine Adresse bekommen'; $lvl = 'bad' }
        else { $h += ('feste Adresse {0} eingetragen (gewollt?)' -f ($stat -join ', ')); if ($lvl -eq 'ok') { $lvl = 'warn' } }
    } elseif ($stat.Count) { $h += ('DHCP an, aber alte feste Adresse {0} gespeichert (Rest)' -f ($stat -join ', ')); if ($lvl -eq 'ok') { $lvl = 'warn' } }
    if ($Row.Up -and -not $Row.Ip) { $h += 'verbunden, aber keine gültige IPv4-Adresse (leer oder 169.254)'; $lvl = 'bad' }
    if ($null -ne $Row.ForceBcast -and [string]$Row.ForceBcast -ne '') { $h += ('Broadcast-Flag fest auf {0}' -f $Row.ForceBcast) }
    if (-not $h.Count) { $h += 'in Ordnung' }
    return [pscustomobject]@{ Level = $lvl; Text = ($h -join '; ') }
}

# ---- Windows-Reparatur: Zustand lesen (nur lesend, laufen in Invoke-Bg - alle Pfade per Argument)
function Get-WrInstalledInfo {
    $cv = Get-ItemProperty 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion' -ErrorAction SilentlyContinue
    $os = $null; try { $os = Get-CimInstance Win32_OperatingSystem -ErrorAction Stop } catch { }
    $lang = ''
    try { $il = (Get-ItemProperty 'HKLM:\SYSTEM\CurrentControlSet\Control\Nls\Language' -ErrorAction Stop).InstallLanguage; $lang = [Globalization.CultureInfo]::GetCultureInfo([Convert]::ToInt32([string]$il, 16)).Name } catch { }
    $pa = if ($env:PROCESSOR_ARCHITEW6432) { $env:PROCESSOR_ARCHITEW6432 } else { $env:PROCESSOR_ARCHITECTURE }
    $ap = Get-ItemProperty 'HKLM:\SOFTWARE\Microsoft\WindowsSelfHost\Applicability' -ErrorAction SilentlyContinue
    $branch = if ($ap) { [string]$ap.BranchName } else { '' }
    $ins = [bool]($ap -and (([string]$ap.EnablePreviewBuilds -match '^[1-9]') -or ($branch -match '(?i)dev|canary|beta|releasepreview|rs_prerelease|external')))
    return [pscustomobject]@{
        Caption = $(if ($os) { [string]$os.Caption } else { [string]$cv.ProductName }); EditionId = [string]$cv.EditionID; Build = [int]$cv.CurrentBuild; Ubr = [int]$cv.UBR
        Display = [string]$cv.DisplayVersion; Arch = (Get-WrArchName $pa); Lang = $lang; Insider = $ins; Branch = $branch
        InstallDate = $(if ($os) { $os.InstallDate } else { $null }); InstallType = [string]$cv.InstallationType
    }
}
function Get-WrImageList([string]$Path) {
    # Listet die Windows-Abbilder einer ISO/WIM/ESD (ISO wird dafür kurz eingebunden)
    $res = [ordered]@{ Ok = $false; Error = ''; Wim = ''; Kind = ''; Root = ''; Setup = ''; Images = @() }
    $mounted = $false
    try {
        if (-not (Test-Path -LiteralPath $Path)) { throw 'Datei nicht gefunden.' }
        $w = $Path
        if ($Path -match '(?i)\.iso$') {
            $di = Get-DiskImage -ImagePath $Path -ErrorAction Stop
            if (-not $di.Attached) { $null = Mount-DiskImage -ImagePath $Path -StorageType ISO -ErrorAction Stop; $mounted = $true; Start-Sleep -Seconds 2 }
            $letter = (Get-DiskImage -ImagePath $Path | Get-Volume).DriveLetter
            if (-not $letter) { throw 'Die ISO wurde eingebunden, hat aber keinen Laufwerksbuchstaben.' }
            $res.Root = '{0}:\' -f $letter
            $w = @('sources\install.wim', 'sources\install.esd') | ForEach-Object { Join-Path $res.Root $_ } | Where-Object { Test-Path -LiteralPath $_ } | Select-Object -First 1
            if (-not $w) { if (Test-Path -LiteralPath (Join-Path $res.Root 'sources\install.swm')) { throw 'Die ISO enthält eine geteilte install.swm - bitte eine Microsoft-ISO (Media Creation Tool) verwenden.' }; throw 'In der ISO fehlt sources\install.wim bzw. install.esd.' }
            $st = Join-Path $res.Root 'setup.exe'; if (Test-Path -LiteralPath $st) { $res.Setup = $st }
        } else { $res.Root = Split-Path (Split-Path $Path) }
        $res.Wim = $w; $res.Kind = $(if ($w -match '(?i)\.esd$') { 'ESD' } else { 'WIM' })
        $list = [System.Collections.Generic.List[object]]::new()
        foreach ($i in @(Get-WindowsImage -ImagePath $w -ErrorAction Stop)) {
            $d = $null; try { $d = Get-WindowsImage -ImagePath $w -Index $i.ImageIndex -ErrorAction Stop } catch { }
            $list.Add([pscustomobject]@{
                Index = [int]$i.ImageIndex; Name = [string]$i.ImageName
                EditionId = $(if ($d) { [string]$d.EditionId } else { '' }); Build = $(if ($d) { [string]$d.Version } else { '' })
                Arch = $(if ($d) { Get-WrArchName $d.Architecture } else { '' }); Langs = $(if ($d) { @($d.Languages) } else { @() })
            })
        }
        $res.Images = $list.ToArray(); $res.Ok = $true
    } catch { $res.Error = $_.Exception.Message }
    finally { if ($mounted) { try { Dismount-DiskImage -ImagePath $Path -ErrorAction SilentlyContinue | Out-Null } catch { } } }
    return [pscustomobject]$res
}
function Get-WrPendingInfo {
    $r = [System.Collections.Generic.List[string]]::new()
    $cbs = 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Component Based Servicing'
    if (Test-Path -LiteralPath (Join-Path $cbs 'RebootPending')) { $r.Add('Windows-Komponenten warten auf einen Neustart') }
    if (Test-Path -LiteralPath (Join-Path $cbs 'PackagesPending')) { $r.Add('Update-Pakete warten auf die Installation') }
    if (Test-Path -LiteralPath 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\WindowsUpdate\Auto Update\RebootRequired') { $r.Add('Windows Update verlangt einen Neustart') }
    $pf = @((Get-ItemProperty 'HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager' -Name PendingFileRenameOperations -ErrorAction SilentlyContinue).PendingFileRenameOperations | Where-Object { $_ })
    if ($pf.Count) { $r.Add(('{0} Datei(en) werden beim Neustart ersetzt' -f [math]::Max(1, [int]($pf.Count / 2)))) }
    if (Test-Path -LiteralPath (Join-Path $env:windir 'WinSxS\pending.xml')) { $r.Add('pending.xml vorhanden (Update-Aktionen stehen aus)') }
    $a = (Get-ItemProperty 'HKLM:\SYSTEM\CurrentControlSet\Control\ComputerName\ActiveComputerName' -ErrorAction SilentlyContinue).ComputerName
    $n = (Get-ItemProperty 'HKLM:\SYSTEM\CurrentControlSet\Control\ComputerName\ComputerName' -ErrorAction SilentlyContinue).ComputerName
    if ($a -and $n -and $a -ne $n) { $r.Add(('Computername wird zu {0} geändert' -f $n)) }
    $uv = (Get-ItemProperty 'HKLM:\SOFTWARE\Microsoft\Updates' -Name UpdateExeVolatile -ErrorAction SilentlyContinue).UpdateExeVolatile
    if ($uv -and [int]$uv -ne 0) { $r.Add('Ein Installationsprogramm wartet auf den Neustart') }
    return @($r)
}
function Get-WrPendingRevertText {
    return @(
        'Ausstehende Update-Aktionen zurücknehmen (nur in der Wiederherstellungsumgebung sicher):',
        '',
        '1. "Jetzt in die Wiederherstellung starten" (oder Umschalt + Neu starten).',
        '2. Problembehandlung > Erweiterte Optionen > Eingabeaufforderung.',
        '3. Laufwerk von Windows finden: "dir C:\Windows" - in WinRE hat Windows manchmal D: oder E:.',
        '   Ist das Laufwerk mit BitLocker verschlüsselt, fragt WinRE vorher nach dem eigenen Wiederherstellungsschlüssel (Microsoft-Konto: aka.ms/myrecoverykey).',
        '4. dism /Image:C:\ /Cleanup-Image /RevertPendingActions',
        '5. Schlägt das fehl: ren C:\Windows\WinSxS\pending.xml pending.xml.alt  (nur hier in WinRE, nie im laufenden Windows)',
        '6. exit und "Weiter zu Windows".',
        '',
        'Danach: Profil "Windows Update reparieren" und das Update neu installieren lassen.',
        'Tipp: Auf dem Notfall-Stick von PC-Tools macht das Reparatur-Menü (Punkt 5) diese Schritte automatisch.'
    ) -join "`r`n"
}
function Get-WrStatus([string]$DataDir) {
    $sys = Join-Path $env:windir 'System32'
    $r = [ordered]@{}
    try {
        $i = Get-WrInstalledInfo; $r.Inst = $i
        $r.WinVal = (($i.Caption -replace '^Microsoft\s+', '') -replace '\s+', ' ').Trim()
        $r.WinSub = ('{0} · Build {1}.{2} · {3} · {4}' -f $i.Display, $i.Build, $i.Ubr, $i.Arch, $i.Lang)
        if ($i.InstallDate) { $r.WinSub += (' · installiert ' + ([datetime]$i.InstallDate).ToString('dd.MM.yyyy')) }
        if ($i.Insider) { $r.WinSub += (' · Insider ' + $i.Branch) }
        $r.WinLvl = $(if ($i.Insider) { 'info' } else { 'ok' })
    } catch { $r.WinVal = 'Windows'; $r.WinSub = $_.Exception.Message; $r.WinLvl = 'warn' }
    $p = @(Get-WrPendingInfo)
    $r.RebootVal = $(if ($p.Count) { 'Ja' } else { 'Nein' }); $r.RebootSub = $(if ($p.Count) { $p -join ' · ' } else { 'Nichts wartet auf einen Neustart.' }); $r.RebootLvl = $(if ($p.Count) { 'warn' } else { 'ok' })
    $state = $null; $sf = Join-Path $DataDir 'WinRepair\state.json'
    if (Test-Path -LiteralPath $sf) { try { $state = Get-Content -LiteralPath $sf -Raw -Encoding UTF8 | ConvertFrom-Json } catch { } }
    $v = Get-WrDismVerdict (Invoke-NdCmd (Join-Path $sys 'Dism.exe') '/Online /Cleanup-Image /CheckHealth' 120)
    $r.StoreVal = switch ($v.State) { 'Healthy' { 'Gesund' } 'Ok' { 'Gesund' } 'Repaired' { 'Gesund' } 'Repairable' { 'Beschädigt' } 'NotRepairable' { 'Defekt' } default { 'unklar' } }
    $r.StoreLvl = switch ($v.State) { 'Healthy' { 'ok' } 'Ok' { 'ok' } 'Repaired' { 'ok' } 'Repairable' { 'warn' } 'NotRepairable' { 'bad' } default { 'info' } }
    $r.StoreSub = $v.Text
    if ($state -and $state.Dism) { $r.StoreSub += (' Letzte Prüfung mit PC-Tools: {0} ({1}) am {2}' -f $state.Dism.Op, $state.Dism.Text, $state.Dism.Time) }
    try { $c = Get-WrCbsSummary (Join-Path $env:windir 'Logs\CBS\CBS.log') } catch { $c = ConvertFrom-WrCbsLines @() }
    $r.Cbs = $c
    if (-not $c.Found) { $r.SfcVal = 'kein Lauf'; $r.SfcSub = 'In der aktuellen CBS.log steht kein SFC-Lauf - "Systemdateien prüfen" ausführen.'; $r.SfcLvl = 'info' }
    else {
        $r.SfcVal = if (@($c.Failed).Count) { '{0} offen' -f @($c.Failed).Count } elseif (@($c.Repaired).Count) { '{0} repariert' -f @($c.Repaired).Count } elseif (@($c.Corrupt).Count) { '{0} beschädigt' -f @($c.Corrupt).Count } else { 'sauber' }
        $r.SfcLvl = if (@($c.Failed).Count) { 'bad' } elseif (@($c.Corrupt).Count) { 'warn' } else { 'ok' }
        $r.SfcSub = ('Letzter Lauf {0} · {1} · {2} Komponenten geprüft{3}' -f ([datetime]$c.End).ToString('dd.MM.yyyy HH:mm'), $c.Mode, $c.Verified, $(if (-not $c.Complete) { ' · unvollständig' } else { '' }))
    }
    $re = ConvertFrom-WrReagentc (Invoke-NdCmd (Join-Path $sys 'reagentc.exe') '/info' 60)
    $r.ReVal = $(if ($re.Enabled) { 'Aktiv' } elseif ($re.Status) { 'Aus' } else { 'unklar' }); $r.ReLvl = $(if ($re.Enabled) { 'ok' } elseif ($re.Status) { 'bad' } else { 'info' })
    $pm = [regex]::Match($re.Location, '(?i)harddisk(\d+)\\partition(\d+)')
    $r.ReSub = $(if ($re.Enabled -and $pm.Success) { 'Datenträger {0}, Partition {1} - Starthilfe und Zurücksetzen möglich.' -f $pm.Groups[1].Value, $pm.Groups[2].Value } elseif ($re.Enabled) { 'Starthilfe und Zurücksetzen möglich.' } else { 'Ohne WinRE keine Starthilfe - "Wiederherstellungsumgebung einschalten".' })
    try {
        $d = New-Object IO.DriveInfo $env:SystemDrive; $free = [math]::Round($d.AvailableFreeSpace / 1GB, 1); $tot = [math]::Round($d.TotalSize / 1GB); $pct = [math]::Round($d.AvailableFreeSpace * 100 / [math]::Max(1, $d.TotalSize))
        $r.DiskVal = ('{0} GB' -f $free); $r.DiskSub = ('frei von {0} GB ({1} %). Reparaturen und Updates brauchen mindestens 10-20 GB.' -f $tot, $pct)
        $r.DiskLvl = $(if ($free -lt 10 -or $pct -lt 8) { 'bad' } elseif ($free -lt 20) { 'warn' } else { 'ok' })
    } catch { $r.DiskVal = '?'; $r.DiskSub = $_.Exception.Message; $r.DiskLvl = 'info' }
    $rp = @(); try { $rp = @(Get-ComputerRestorePoint -ErrorAction Stop | Sort-Object SequenceNumber) } catch { }
    if ($rp.Count) {
        $lt = [Management.ManagementDateTimeConverter]::ToDateTime($rp[-1].CreationTime)
        $r.RpVal = $lt.ToString('dd.MM.yyyy'); $r.RpSub = ('{0} Punkt(e), letzter: {1} ({2:HH:mm})' -f $rp.Count, $rp[-1].Description, $lt); $r.RpLvl = $(if (((Get-Date) - $lt).TotalDays -gt 30) { 'warn' } else { 'ok' })
    } else { $r.RpVal = 'keiner'; $r.RpSub = 'Kein Wiederherstellungspunkt - vor Reparaturen einen erstellen (Computerschutz für C: muss an sein).'; $r.RpLvl = 'warn' }
    $b = Get-WrBcdInfo (Invoke-NdCmd (Join-Path $sys 'bcdedit.exe') '/enum {current}' 30)
    $sb = ''; try { $sb = $(if (Confirm-SecureBootUEFI -ErrorAction Stop) { 'Secure Boot an' } else { 'Secure Boot aus' }) } catch { }
    $r.Bcd = $b
    $r.BootVal = $(if ($b.SafeBoot) { 'Abgesichert' } else { 'Normal' })
    $r.BootLvl = $(if ($b.SafeBoot) { 'warn' } else { 'ok' })
    $bp = @(); $bp += $(if ($b.Uefi -or $env:firmware_type -eq 'UEFI') { 'UEFI' } else { 'Legacy-BIOS' }); if ($sb) { $bp += $sb }
    if ($b.SafeBoot) { $bp += ('nächster Start abgesichert ({0})' -f $b.SafeBoot) }
    if ($b.BootLog) { $bp += 'Startprotokoll an' }
    if ($b.Hypervisor) { $bp += ('Hypervisor: {0}' -f $b.Hypervisor) }
    $r.BootSub = $bp -join ' · '
    $r.Time = (Get-Date).ToString('HH:mm')
    return [pscustomobject]$r
}
function Get-WrNetScan {
    $r = [ordered]@{ Filters = @(); Ip = @(); Dc = [int64]0; DcText = ''; Toggle = $null; Uninstall = @(); Drivers = @() }
    $inf = @{}
    foreach ($cls in '{4D36E974-E325-11CE-BFC1-08002BE10318}', '{4D36E975-E325-11CE-BFC1-08002BE10318}', '{4D36E973-E325-11CE-BFC1-08002BE10318}') {
        foreach ($k in @(Get-ChildItem ('HKLM:\SYSTEM\CurrentControlSet\Control\Network\' + $cls) -ErrorAction SilentlyContinue)) {
            $p = Get-ItemProperty -LiteralPath $k.PSPath -ErrorAction SilentlyContinue
            if ($p -and $p.ComponentId) { $inf[([string]$p.ComponentId).ToLower()] = [string]$p.InfPath }
        }
    }
    $drv = @(ConvertFrom-WrPnpDrivers (Invoke-NdCmd 'pnputil.exe' '/enum-drivers /class NetService' 60)); $r.Drivers = $drv
    $byInf = @{}; foreach ($d in $drv) { if ($d.Inf) { $byInf[([string]$d.Inf).ToLower()] = $d } }
    $ads = @(Get-NetAdapter -Physical -ErrorAction SilentlyContinue | Where-Object { $_.InterfaceDescription -notmatch 'Bluetooth' } | Sort-Object Name)
    $rows = [System.Collections.Generic.List[object]]::new()
    foreach ($a in $ads) {
        foreach ($b in @(Get-NetAdapterBinding -Name $a.Name -AllBindings -ErrorAction SilentlyContinue)) {
            $v = Get-WrFilterVerdict ([string]$b.DisplayName) ([string]$b.ComponentID)
            if (-not $v.ThirdParty -and [string]$b.ComponentID -notin 'ms_tcpip', 'ms_tcpip6', 'vms_pp') { continue }
            $ip = [string]$inf[([string]$b.ComponentID).ToLower()]; $pk = $null; if ($ip) { $pk = $byInf[$ip.ToLower()] }
            $e = if ($v.ThirdParty) { $v.Text } elseif ([string]$b.ComponentID -eq 'ms_tcpip' -and -not $b.Enabled) { 'IPv4 ist AUS - ohne IPv4-Bindung keine IPv4-Adresse. Wieder einschalten!' } elseif ([string]$b.ComponentID -eq 'vms_pp' -and $b.Enabled) { 'Adapter hängt an einem Hyper-V-Switch - Seite Netzwerk-Diagnose prüfen.' } else { 'Windows-Bestandteil' }
            $lvl = if ($v.IsAv -and $b.Enabled) { 'bad' } elseif ($v.ThirdParty -and $b.Enabled) { 'warn' } elseif ([string]$b.ComponentID -eq 'ms_tcpip' -and -not $b.Enabled) { 'bad' } elseif ([string]$b.ComponentID -eq 'vms_pp' -and $b.Enabled) { 'warn' } else { 'ok' }
            $rows.Add([pscustomobject]@{ Adapter = [string]$a.Name; If = [int]$a.ifIndex; Komponente = [string]$b.DisplayName; Id = [string]$b.ComponentID; Aktiv = $(if ($b.Enabled) { 'Ja' } else { 'Nein' }); Enabled = [bool]$b.Enabled
                Hersteller = $(if ($pk -and $pk.Provider) { [string]$pk.Provider } else { $v.Vendor }); Paket = $ip; Original = $(if ($pk) { [string]$pk.Original } else { '' }); Einschaetzung = $e; Third = [bool]$v.ThirdParty; IsAv = [bool]$v.IsAv; Level = $lvl })
        }
    }
    $r.Filters = @($rows | Sort-Object @{ e = { -not $_.Third } }, Adapter, Komponente)
    $base = 'HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters'
    $iprows = foreach ($a in $ads) {
        $p = Get-ItemProperty -LiteralPath (Join-Path $base ('Interfaces\' + $a.InterfaceGuid)) -ErrorAction SilentlyContinue
        $b = Get-NetAdapterBinding -Name $a.Name -ComponentID ms_tcpip -ErrorAction SilentlyContinue
        $v4 = @(Get-NetIPAddress -InterfaceIndex $a.ifIndex -AddressFamily IPv4 -ErrorAction SilentlyContinue | Where-Object { $_.IPAddress -notlike '169.254.*' } | ForEach-Object { $_.IPAddress })
        $row = [pscustomobject]@{ Adapter = [string]$a.Name; Beschreibung = [string]$a.InterfaceDescription; Status = [string]$a.Status; Up = ([string]$a.Status -eq 'Up'); Bound = [bool]($b -and $b.Enabled)
            EnableDhcp = $(if ($p -and $null -ne $p.EnableDHCP) { [int]$p.EnableDHCP } else { 1 }); RegIp = @($(if ($p) { $p.IPAddress } else { $null }) | Where-Object { $_ }); Ip = ($v4 -join ', ')
            DhcpServer = $(if ($p) { [string]$p.DhcpServer } else { '' }); ForceBcast = $(if ($p) { $p.DhcpConnForceBroadcastFlag } else { $null }); Mac = [string]$a.MacAddress; Guid = [string]$a.InterfaceGuid; If = [int]$a.ifIndex }
        $h = Get-WrIpHint $row
        $row | Add-Member -NotePropertyName Dhcp -NotePropertyValue $(if ($row.EnableDhcp) { 'an' } else { 'aus' }) -PassThru |
               Add-Member -NotePropertyName Gespeichert -NotePropertyValue ((@($row.RegIp) | Where-Object { $_ -ne '0.0.0.0' }) -join ', ') -PassThru |
               Add-Member -NotePropertyName Hinweis -NotePropertyValue $h.Text -PassThru | Add-Member -NotePropertyName Level -NotePropertyValue $h.Level -PassThru
    }
    $r.Ip = @($iprows)
    $p6 = Get-ItemProperty 'HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip6\Parameters' -Name DisabledComponents -ErrorAction SilentlyContinue
    $r.Dc = $(if ($p6) { [int64]$p6.DisabledComponents } else { [int64]0 }); $r.DcText = Get-WrDisabledComponentsText $r.Dc
    $r.Toggle = (Get-ItemProperty $base -Name DhcpConnEnableBcastFlagToggle -ErrorAction SilentlyContinue).DhcpConnEnableBcastFlagToggle
    $un = foreach ($root in 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall', 'HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall') {
        foreach ($k in @(Get-ChildItem $root -ErrorAction SilentlyContinue)) {
            $p = Get-ItemProperty -LiteralPath $k.PSPath -ErrorAction SilentlyContinue
            if (-not $p -or -not $p.DisplayName -or $p.SystemComponent -eq 1 -or -not $p.UninstallString) { continue }
            $v = Get-WrFilterVerdict ([string]$p.DisplayName + ' ' + [string]$p.Publisher) 'x'
            if ($v.Kind -in 'AV', 'VPN') { [pscustomobject]@{ Name = [string]$p.DisplayName; Publisher = [string]$p.Publisher; Version = [string]$p.DisplayVersion; Uninstall = [string]$p.UninstallString; Kind = $v.Kind } }
        }
    }
    $r.Uninstall = @($un | Sort-Object Name -Unique)
    return [pscustomobject]$r
}
function Get-WrEventOverview([int]$Days = 7) {
    $ev = @(Get-WinEvent -FilterHashtable @{ LogName = 'System'; Level = 1, 2; StartTime = (Get-Date).AddDays(-$Days) } -MaxEvents 3000 -ErrorAction SilentlyContinue)
    return [pscustomobject]@{ Total = $ev.Count; Critical = @($ev | Where-Object { [int]$_.Level -eq 1 }).Count; Groups = @(Get-WrEventGroups $ev); Days = $Days }
}
# Direkte Aktionen (Knöpfe mit Mode = Ui): öffnen etwas oder stellen den nächsten Start um. Rückfragen stellt der Aufrufer (Oberfläche/Textmodus).
function Invoke-WrDirect([string]$Key, [string]$Arg = '') {
    $sys = Join-Path $env:windir 'System32'
    $bcd = Join-Path $sys 'bcdedit.exe'; $sd = Join-Path $sys 'shutdown.exe'
    $ro = 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\RunOnce'
    switch ($Key) {
        'BootToRe' {
            $o = Invoke-NdCmd (Join-Path $sys 'reagentc.exe') '/boottore' 30
            if ($o -match '(?i)erfolgreich|successful') { $null = Invoke-NdCmd $sd '/r /t 5 /c "PC-Tools: Neustart in die Windows-Wiederherstellung"' 10; return 'Neustart in die Windows-Wiederherstellungsumgebung in 5 Sekunden.' }
            $null = Invoke-NdCmd $sd '/r /o /t 5' 10
            return ('WinRE ließ sich nicht direkt ansteuern ({0}) - Neustart in die erweiterten Startoptionen in 5 Sekunden.' -f (($o -replace '\s+', ' ').Trim()))
        }
        'BootAdv' { $null = Invoke-NdCmd $sd '/r /o /t 5' 10; return 'Neustart in die erweiterten Startoptionen in 5 Sekunden.' }
        'Reboot' { $null = Invoke-NdCmd $sd '/r /t 5 /c "PC-Tools: Neustart"' 10; return 'Neustart in 5 Sekunden.' }
        'SafeMode' {
            $mode = if ($Arg -eq 'network') { 'network' } else { 'minimal' }
            $o = Invoke-NdCmd $bcd ('/set {current} safeboot ' + $mode) 20
            if ($o -notmatch '(?i)erfolgreich|successfully') { throw ('bcdedit: ' + (($o -replace '\s+', ' ').Trim())) }
            if (-not (Test-Path -LiteralPath $ro)) { $null = New-Item -Path $ro -Force }
            $null = New-ItemProperty -LiteralPath $ro -Name '*PCToolsSafeModeOff' -Value ('"{0}" /deletevalue {{current}} safeboot' -f $bcd) -PropertyType String -Force
            return ('Der nächste Start erfolgt im abgesicherten Modus{0}. Nach der Anmeldung (mit einem Administratorkonto) schaltet sich der abgesicherte Modus automatisch wieder aus - der übernächste Start ist normal.' -f $(if ($mode -eq 'network') { ' mit Netzwerk' } else { '' }))
        }
        'SafeOff' {
            $o = Invoke-NdCmd $bcd '/deletevalue {current} safeboot' 20; $null = Invoke-NdCmd $bcd '/deletevalue {current} safebootalternateshell' 20
            Remove-ItemProperty -LiteralPath $ro -Name '*PCToolsSafeModeOff' -ErrorAction SilentlyContinue
            return ('Abgesicherter Modus ist aus - der nächste Start ist normal. ({0})' -f (($o -replace '\s+', ' ').Trim()))
        }
        'WuFixUi' { Start-Process 'ms-settings:recovery'; return 'Einstellungen > Wiederherstellung geöffnet: "Probleme mithilfe von Windows Update beheben" > "Jetzt neu installieren".' }
        'WuTroubleUi' { Start-Process 'ms-settings:troubleshoot'; return 'Einstellungen > Problembehandlung geöffnet.' }
        'Rstrui' { Start-Process (Join-Path $sys 'rstrui.exe'); return 'Systemwiederherstellung geöffnet.' }
        'ResetPc' {
            $x = Join-Path $sys 'systemreset.exe'
            if ($Arg -eq 'direct' -and (Test-Path -LiteralPath $x)) { Start-Process -FilePath $x -ArgumentList '-factoryreset'; return 'Assistent "Diesen PC zurücksetzen" geöffnet - er fragt selbst noch einmal nach.' }
            Start-Process 'ms-settings:recovery'; return 'Einstellungen > Wiederherstellung geöffnet: "Diesen PC zurücksetzen".'
        }
        'NetFxTool' { Start-Process 'https://www.microsoft.com/download/details.aspx?id=30135'; return 'Microsoft-Seite zum .NET Framework Repair Tool geöffnet.' }
        'AppsFeatures' { Start-Process 'ms-settings:appsfeatures'; return 'Einstellungen > Installierte Apps geöffnet.' }
        'PendingRevert' { return (Get-WrPendingRevertText) }
        default { throw ('Unbekannte Aktion: ' + $Key) }
    }
}

# ---- Windows-Reparatur: Ausführung (Engine-Teil "WinRepair" und Textmodus - braucht Write-PLog, Set-PStatus, Test-PCancel aus $EngineText)
function Get-WrDir {
    $b = if ($Script:DataDir) { $Script:DataDir } else { $DataDir }
    $d = Join-Path $b 'WinRepair'
    New-Item $d -ItemType Directory -Force -ErrorAction SilentlyContinue | Out-Null
    return $d
}
function Get-WrStamp { Get-Date -Format 'yyyyMMdd_HHmmss' }
function Write-WrResult([string]$Text, [string]$Level = 'INFO') { $Script:WrMsg = $Text; Write-PLog ('   ' + $Text) $Level }
function Save-WrState([string]$Name, $Value) {
    $f = Join-Path (Get-WrDir) 'state.json'; $o = [ordered]@{}
    if (Test-Path -LiteralPath $f) { try { $j = Get-Content -LiteralPath $f -Raw -Encoding UTF8 | ConvertFrom-Json; foreach ($p in $j.PSObject.Properties) { $o[$p.Name] = $p.Value } } catch { } }
    $o[$Name] = $Value
    try { [pscustomobject]$o | ConvertTo-Json -Depth 5 | Set-Content -LiteralPath $f -Encoding UTF8 } catch { }
}
# Externes Programm mit Live-Ausgabe im Protokoll UND Mitschnitt für die Auswertung (DISM-Fortschritt wird zur Statuszeile).
# -Enc Auto: Ausgabe roh lesen und UTF-16/OEM selbst erkennen (sfc.exe)
function Invoke-WrExe {
    param([string]$Exe, [string]$ArgLine = '', [int]$TimeoutMin = 60, [string]$Enc = 'Oem', [switch]$Silent, [string]$Label = '')
    $name = Split-Path $Exe -Leaf; if (-not $Label) { $Label = $name }
    Write-PLog ('   > {0} {1}' -f $name, $ArgLine)
    $psi = New-Object Diagnostics.ProcessStartInfo
    $psi.FileName = $Exe; $psi.Arguments = $ArgLine; $psi.UseShellExecute = $false; $psi.CreateNoWindow = $true
    $psi.RedirectStandardOutput = $true; $psi.RedirectStandardError = $true; $psi.RedirectStandardInput = $true
    if ($Enc -eq 'Oem') { try { $e = [Text.Encoding]::GetEncoding([Globalization.CultureInfo]::CurrentCulture.TextInfo.OEMCodePage); $psi.StandardOutputEncoding = $e; $psi.StandardErrorEncoding = $e } catch { } }
    $p = New-Object Diagnostics.Process; $p.StartInfo = $psi
    try { [void]$p.Start() } catch { Write-PLog ('   {0} konnte nicht gestartet werden: {1}' -f $name, $_.Exception.Message) 'WARN'; return [pscustomobject]@{ Code = -1; Text = ''; Killed = $false } }
    try { $p.StandardInput.Close() } catch { }
    $sb = New-Object Text.StringBuilder; $sw = [Diagnostics.Stopwatch]::StartNew(); $killed = $false
    $stop = { if ((Test-PCancel) -or $sw.Elapsed.TotalMinutes -gt $TimeoutMin) { Write-PLog ('   {0}: {1} - wird beendet' -f $name, $(if (Test-PCancel) { 'abgebrochen' } else { 'Zeitlimit {0} Min. überschritten' -f $TimeoutMin })) 'WARN'; & taskkill.exe /PID $p.Id /T /F 2>&1 | Out-Null; return $true }; return $false }
    if ($Enc -eq 'Auto') {
        $ms1 = New-Object IO.MemoryStream; $ms2 = New-Object IO.MemoryStream
        $t1 = $p.StandardOutput.BaseStream.CopyToAsync($ms1); $t2 = $p.StandardError.BaseStream.CopyToAsync($ms2)
        while (-not $p.HasExited) {
            if (& $stop) { $killed = $true; break }
            $Script:Detail = ('{0} arbeitet seit {1} Min. {2:00} s' -f $Label, [int][math]::Floor($sw.Elapsed.TotalMinutes), $sw.Elapsed.Seconds); Update-PHeartbeat
            Start-Sleep -Milliseconds 500
        }
        try { [void]$t1.Wait(8000) } catch { }; try { [void]$t2.Wait(3000) } catch { }
        $txt = (ConvertFrom-WrBytes $ms1.ToArray()) + "`r`n" + (ConvertFrom-WrBytes $ms2.ToArray())
        $last = ''
        foreach ($l in ($txt -split "`r`n|`n|`r")) {
            $x = $l.Trim(); if (-not $x -or $x -eq $last -or $x -match '\d{1,3}\s?%') { continue }
            [void]$sb.AppendLine($x); $last = $x
            if (-not $Silent) { Write-PLog ('   ' + $x) }
        }
    } else {
        $outT = $p.StandardOutput.ReadLineAsync(); $errT = $p.StandardError.ReadLineAsync(); $exitSeen = $null; $last = ''
        while ($outT -or $errT) {
            $got = $false
            foreach ($which in 'out', 'err') {
                $t = if ($which -eq 'out') { $outT } else { $errT }
                if (-not ($t -and $t.IsCompleted)) { continue }
                $got = $true; $l = $null; try { $l = $t.Result } catch { }
                if ($null -eq $l) { if ($which -eq 'out') { $outT = $null } else { $errT = $null }; continue }
                if ($which -eq 'out') { $outT = $p.StandardOutput.ReadLineAsync() } else { $errT = $p.StandardError.ReadLineAsync() }
                $x = ($l -replace "`0", '').Trim()
                if (-not $x) { continue }
                $pm = [regex]::Match($x, '^\[?[=\s\-]*(\d{1,3}(?:[\.,]\d)?)\s?%')
                if ($pm.Success -or ($x -match '^\[[=\s]*\d{1,3}(?:[\.,]\d)?%[=\s]*\]$')) { if (-not $pm.Success) { $pm = [regex]::Match($x, '(\d{1,3}(?:[\.,]\d)?)%') }; $Script:Detail = ('{0}: {1} %' -f $Label, $pm.Groups[1].Value); $Script:LastLine = $Script:Detail; Update-PHeartbeat; continue }
                [void]$sb.AppendLine($x)
                if (-not $Silent -and $x -ne $last) { Write-PLog ('   ' + $x) }
                $last = $x
            }
            if ($got) { continue }
            if (& $stop) { $killed = $true; break }
            Update-PHeartbeat
            if ($p.HasExited) { if (-not $exitSeen) { $exitSeen = [Diagnostics.Stopwatch]::StartNew() } elseif ($exitSeen.Elapsed.TotalSeconds -gt 3) { break } }
            Start-Sleep -Milliseconds 200
        }
    }
    try { [void]$p.WaitForExit(10000) } catch { }
    $code = if ($killed) { -1 } else { try { $p.ExitCode } catch { -1 } }
    return [pscustomobject]@{ Code = $code; Text = $sb.ToString(); Killed = $killed }
}
# Reparaturquelle (ISO/WIM/ESD): einmal pro Lauf einbinden, Index passend zur installierten Edition
function Get-WrSource {
    if ($Script:WrSrcInfo) { return $Script:WrSrcInfo }
    $src = [string]$Script:JobOpts.Source
    if (-not $src -or $Script:WrSrcTried) { return $null }
    $Script:WrSrcTried = $true
    try {
        if (-not (Test-Path -LiteralPath $src)) { throw ('nicht gefunden: ' + $src) }
        $root = ''; $wim = $src
        if ($src -match '(?i)\.iso$') {
            $di = Get-DiskImage -ImagePath $src -ErrorAction Stop
            if (-not $di.Attached) { $null = Mount-DiskImage -ImagePath $src -StorageType ISO -ErrorAction Stop; $Script:WrMountedIso = $src; Start-Sleep -Seconds 2 }
            $root = '{0}:\' -f (Get-DiskImage -ImagePath $src | Get-Volume).DriveLetter
            $wim = @('sources\install.wim', 'sources\install.esd') | ForEach-Object { Join-Path $root $_ } | Where-Object { Test-Path -LiteralPath $_ } | Select-Object -First 1
            if (-not $wim) { throw 'keine sources\install.wim bzw. install.esd in der ISO' }
        } else { $root = Split-Path (Split-Path $src) }
        $kind = if ($wim -match '(?i)\.esd$') { 'ESD' } else { 'WIM' }
        $idx = [int]$Script:JobOpts.Index
        if ($idx -le 0) {
            $ed = [string](Get-ItemProperty 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion').EditionID
            foreach ($i in @(Get-WindowsImage -ImagePath $wim -ErrorAction Stop)) { $d = Get-WindowsImage -ImagePath $wim -Index $i.ImageIndex -ErrorAction SilentlyContinue; if ($d -and [string]$d.EditionId -eq $ed) { $idx = [int]$i.ImageIndex; break } }
            if ($idx -le 0) { $idx = 1; Write-PLog ('   Reparaturquelle: keine Edition "{0}" im Abbild - Index 1 wird benutzt.' -f $ed) 'WARN' }
        }
        $sxs = Join-Path $root 'sources\sxs'
        $Script:WrSrcInfo = [pscustomobject]@{ Wim = $wim; Kind = $kind; Index = $idx; Root = $root; Sxs = $(if ($root -and (Test-Path -LiteralPath $sxs)) { $sxs } else { '' }) }
        Write-PLog ('   Reparaturquelle: {0} (Index {1})' -f $wim, $idx)
        return $Script:WrSrcInfo
    } catch { Write-PLog ('   Reparaturquelle nicht nutzbar: {0} - Windows Update wird benutzt.' -f $_.Exception.Message) 'WARN'; return $null }
}
function Get-WrSourceArg {
    $s = Get-WrSource; if (-not $s) { return '' }
    $p = [string]$s.Wim; if ($p -match '\s') { $p = '"' + $p + '"' }
    return (' /Source:{0}:{1}:{2} /LimitAccess' -f $s.Kind, $p, $s.Index)
}
function Dismount-WrSource {
    if ($Script:WrMountedIso) { try { Dismount-DiskImage -ImagePath $Script:WrMountedIso -ErrorAction SilentlyContinue | Out-Null } catch { } }
    $Script:WrMountedIso = $null; $Script:WrSrcInfo = $null; $Script:WrSrcTried = $false
}
function Write-WrCbsDetails($c) {
    if (-not $c -or -not $c.Found) { Write-PLog '   CBS.log: kein SFC-Lauf gefunden.'; return }
    Write-PLog ('   CBS.log: Lauf {0:dd.MM.yyyy HH:mm}-{1:HH:mm}, {2}, {3} Komponenten geprüft - {4}' -f $c.Start, $c.End, $c.Mode, $c.Verified, $c.Verdict)
    foreach ($f in @($c.Repaired | Select-Object -First 25)) { Write-PLog ('      repariert: ' + $f) }
    foreach ($f in @($c.Failed | Select-Object -First 25)) { Write-PLog ('      NICHT reparierbar: ' + $f) 'WARN' }
    foreach ($f in @($c.Corrupt | Select-Object -First 25)) { Write-PLog ('      beschädigt: ' + $f) }
}
function Invoke-WrSys([string]$Key) {
    $dism = Get-SysExe 'Dism.exe'
    switch ($Key) {
        { $_ -in 'DismCheck', 'DismScan', 'DismRestore' } {
            $op = @{ DismCheck = 'CheckHealth'; DismScan = 'ScanHealth'; DismRestore = 'RestoreHealth' }[$Key]
            $a = '/Online /Cleanup-Image /' + $op; if ($Key -eq 'DismRestore') { $a += (Get-WrSourceArg) }
            $r = Invoke-WrExe $dism $a $(if ($Key -eq 'DismCheck') { 15 } else { 240 }) -Label ('DISM ' + $op)
            $v = Get-WrDismVerdict $r.Text
            $ok = ($v.State -in 'Healthy', 'Ok', 'Repaired') -or ($v.State -eq 'Unknown' -and $r.Code -eq 0)
            Write-WrResult $v.Text $(if ($ok) { 'OK' } else { 'WARN' })
            Save-WrState 'Dism' ([ordered]@{ Op = $op; State = $v.State; Text = $v.Text; Code = $v.Code; Time = (Get-Date).ToString('dd.MM.yyyy HH:mm') })
            if ($Key -eq 'DismRestore' -and $v.SourceMissing -and -not [string]$Script:JobOpts.Source) { Write-PLog '   Tipp: oben bei "Reparaturquelle" eine Windows-ISO derselben Version wählen (Seite Windows und Office lädt sie) und erneut ausführen.' }
            if ($Key -ne 'DismRestore' -and $v.State -eq 'Repairable') { Write-PLog '   Empfehlung: "Windows-Abbild reparieren", danach "Systemdateien prüfen und reparieren".' }
            if ($v.State -eq 'NotRepairable') { Write-PLog '   Empfehlung: Reparaturinstallation (In-place Upgrade) mit einer passenden Windows-ISO.' }
        }
        'DismAnalyze' {
            $r = Invoke-WrExe $dism '/Online /Cleanup-Image /AnalyzeComponentStore' 45 -Label 'DISM Analyse'
            $a = Get-WrDismAnalyze $r.Text
            Write-WrResult ('WinSxS tatsächlich {0}{1}, {2} entfernbare Pakete, Bereinigung {3}.' -f $(if ($a.Actual) { $a.Actual } else { '?' }), $(if ($a.Shared) { ' (davon mit Windows geteilt ' + $a.Shared + ')' } else { '' }), $(if ($a.Reclaimable -ge 0) { $a.Reclaimable } else { '?' }), $(if ($a.Recommended) { 'empfohlen' } elseif ($null -eq $a.Recommended) { 'unklar' } else { 'nicht nötig' })) 'OK'
        }
        { $_ -in 'DismCleanup', 'DismResetBase' } {
            $before = Get-FreeBytes
            $a = '/Online /Cleanup-Image /StartComponentCleanup'; if ($Key -eq 'DismResetBase') { $a += ' /ResetBase' }
            $r = Invoke-WrExe $dism $a 240 -Label 'DISM Bereinigung'
            $diff = [math]::Max([int64]0, (Get-FreeBytes) - $before)
            $v = Get-WrDismVerdict $r.Text
            Write-WrResult ('Komponentenspeicher bereinigt, {0} frei geworden.{1}' -f (Format-Bytes $diff), $(if ($r.Code -ne 0) { ' ' + $v.Text } else { '' })) $(if ($r.Code -eq 0) { 'OK' } else { 'WARN' })
        }
        { $_ -in 'SfcScan', 'SfcVerify' } {
            $ti = Get-Service TrustedInstaller -ErrorAction SilentlyContinue
            if ($ti -and [string]$ti.StartType -eq 'Disabled') { Set-Service TrustedInstaller -StartupType Manual -ErrorAction SilentlyContinue; Write-PLog '   Der Dienst Windows Modules Installer war deaktiviert - auf "Manuell" gesetzt, sonst kann SFC nicht arbeiten.' 'WARN' }
            $r = Invoke-WrExe (Get-SysExe 'sfc.exe') $(if ($Key -eq 'SfcScan') { '/scannow' } else { '/verifyonly' }) 180 -Enc Auto -Label 'SFC'
            $v = Get-WrSfcVerdict $r.Text
            Start-Sleep -Seconds 2
            $c = $null; try { $c = Get-WrCbsSummary } catch { }
            Write-WrResult ('{0}{1}' -f $v.Text, $(if ($c -and $c.Found) { ' CBS.log: ' + $c.Verdict } else { '' })) $(if ($v.State -in 'Clean', 'Repaired') { 'OK' } else { 'WARN' })
            Write-WrCbsDetails $c
            Save-WrState 'Sfc' ([ordered]@{ State = $v.State; Text = $v.Text; Time = (Get-Date).ToString('dd.MM.yyyy HH:mm') })
            if ($v.State -eq 'Pending') { $Script:RebootNeeded = $true }
        }
        'CbsReport' {
            $c = Get-WrCbsSummary
            Write-WrCbsDetails $c
            $f = Join-Path (Get-WrDir) ('SFC-Auswertung_{0}.txt' -f (Get-WrStamp))
            $L = @('SFC-Auswertung aus ' + (Join-Path $env:windir 'Logs\CBS\CBS.log'), ('Erstellt: {0:dd.MM.yyyy HH:mm}' -f (Get-Date)), '')
            if ($c.Found) {
                $L += ('Lauf: {0:dd.MM.yyyy HH:mm:ss} bis {1:HH:mm:ss} ({2}), {3} Komponenten geprüft' -f $c.Start, $c.End, $c.Mode, $c.Verified), ('Ergebnis: ' + $c.Verdict), ''
                $L += 'Repariert:'; $L += @($c.Repaired | ForEach-Object { '  ' + $_ }); $L += '', 'NICHT reparierbar:'; $L += @($c.Failed | ForEach-Object { '  ' + $_ }); $L += '', 'Beschädigt (nur geprüft):'; $L += @($c.Corrupt | ForEach-Object { '  ' + $_ })
            } else { $L += 'Kein SFC-Lauf in der aktuellen CBS.log.' }
            Set-Content -LiteralPath $f -Value $L -Encoding UTF8
            Write-WrResult ('{0} Bericht: {1}' -f $(if ($c.Found) { $c.Verdict } else { 'Kein SFC-Lauf in der CBS.log.' }), $f) $(if ($c.Found -and @($c.Failed).Count) { 'WARN' } else { 'OK' })
        }
    }
}
# ---- Windows-Update-Doktor: Funktionsupdate-Blocker finden (Erkenntnisse aus Praxisfällen) - lesend, laufen im -Run-Kind und im Textmodus
$WuVulnDrivers = @(
    @{ File = 'iqvw64e.sys'; Name = 'Intel Ethernet Diagnose-Treiber (NAL)'; Why = 'alter, angreifbarer Diagnosetreiber - das Netzwerk läuft ohne ihn' }
    @{ File = 'NalDrv.sys'; Name = 'Intel NAL-Treiber'; Why = 'alter Intel-Diagnosetreiber' }
)
function Get-WuPantherDir {
    foreach ($c in @((Join-Path $env:SystemDrive '$WINDOWS.~BT\Sources\Panther'), (Join-Path $env:SystemDrive '$WINDOWS.~WS\Sources\Panther'), (Join-Path $env:windir 'Panther'))) {
        if (Test-Path -LiteralPath $c) { return $c }
    }
    return ''
}
function Get-WuErrorText([string]$Code) {
    $c = ([string]$Code).ToUpperInvariant()
    $map = [ordered]@{
        '0XC1900208' = 'Kompatibilitätsblock: ein Programm oder Treiber verhindert das Funktionsupdate (oft altes VMware/VirtualBox oder ein Fremd-Virenschutz).'
        '0XC1900101' = 'Treiber-Rollback: Setup bricht in der Installation ab und rollt zurück - fast immer ein Treiber. Treiber aktualisieren oder entfernen.'
        '0XC1900204' = 'Migrationsdaten passen nicht - meist hilft die Reparaturinstallation von der ISO.'
        '0X80246010' = 'Update-Dateien fehlen (Download neu anfordern) - oft nach manuellem Löschen von ~BT/Download. Neu suchen lassen.'
        '0X8024200D' = 'Update-Dateien unvollständig - Windows Update zurücksetzen und neu laden.'
        '0X8007042B' = 'Ein Prozess wurde unerwartet beendet (häufig ein Fremdtreiber oder Virenschutz während der Installation).'
        '0XC1800118' = 'WinRE/SafeOS-Image defekt - WinRE aus- und wieder einschalten (reagentc).'
        '0X800F0922' = 'Systemreservierte Partition zu voll/zu klein, oder keine Verbindung zum Update-Server.'
        '0XC1900200' = 'Systemvoraussetzungen nicht erfüllt (z.B. TPM/CPU).'
    }
    foreach ($k in $map.Keys) { if ($c -eq $k) { return $map[$k] } }
    return ''
}
function Get-WuThirdPartyAv {
    $r = @()
    try { foreach ($a in @(Get-CimInstance -Namespace 'root/SecurityCenter2' -ClassName AntiVirusProduct -ErrorAction Stop)) { $n = [string]$a.displayName; if ($n -and $n -notmatch 'Defender') { $r += $n } } } catch { }
    @($r | Select-Object -Unique)
}
function Get-WuKnownBlockApps {
    $r = @()
    $roots = @('HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*', 'HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*')
    try {
        foreach ($p in @(Get-ItemProperty $roots -ErrorAction SilentlyContinue)) {
            $n = [string]$p.DisplayName
            if ($n -and $n -match 'VMware (Workstation|Player)|VirtualBox|Virtual PC') { $r += ('{0} {1}' -f $n, [string]$p.DisplayVersion).Trim() }
        }
    } catch { }
    @($r | Select-Object -Unique)
}
function Get-WuDriverDetails([string[]]$Infs) {
    $out = @{}
    if (-not $Infs -or -not $Infs.Count) { return $out }
    $txt = ''
    try { $txt = (@(Invoke-NdCmd (Get-SysExe 'pnputil.exe') '/enum-drivers' 90) -join "`n") } catch { }
    $recs = @($txt -split "(?:`r?`n){2,}")
    foreach ($inf in $Infs) {
        $hit = ''
        foreach ($rc in $recs) { if ($rc -match [regex]::Escape($inf)) { $hit = ((@($rc -split "`r?`n") | ForEach-Object { $_.Trim() } | Where-Object { $_ -and $_ -notmatch '^-{3,}$' }) -join ' | '); break } }
        $out[$inf] = $(if ($hit) { $hit } else { '(kein registriertes Treiberpaket mehr - evtl. Altlast)' })
    }
    $out
}
function Get-WuBlockReport {
    $p = Get-WuPantherDir
    $res = [pscustomobject]@{ Panther = $p; Programs = @(); Drivers = @(); DriverInfo = @{}; Providers = @(); LastError = ''; ErrorTime = ''; Av = @(); KnownApps = @() }
    if ($p) {
        $scan = @(Get-ChildItem -LiteralPath $p -Filter 'ScanResult.xml' -ErrorAction SilentlyContinue | Sort-Object LastWriteTime | Select-Object -Last 1)
        if (-not $scan.Count) { $scan = @(Get-ChildItem -LiteralPath $p -Filter 'CompatData_*.xml' -ErrorAction SilentlyContinue | Sort-Object LastWriteTime | Select-Object -Last 1) }
        if ($scan.Count) {
            $raw = ''
            try { $raw = Get-Content -LiteralPath $scan[0].FullName -Raw -ErrorAction Stop } catch { }
            foreach ($m in [regex]::Matches($raw, '<Program\s+Name="([^"]+)"[^>]*>\s*<CompatibilityInfo\s+BlockingType="Hard"')) { $res.Programs += $m.Groups[1].Value }
            foreach ($m in [regex]::Matches($raw, '<DriverPackage\s+Inf="([^"]+)"\s+BlockMigration="True"')) { $res.Drivers += $m.Groups[1].Value }
            $res.Programs = @($res.Programs | Select-Object -Unique); $res.Drivers = @($res.Drivers | Select-Object -Unique)
            if ($res.Drivers.Count) { $res.DriverInfo = Get-WuDriverDetails $res.Drivers }
        }
        $errlog = Join-Path $p 'setuperr.log'
        if (Test-Path -LiteralPath $errlog) {
            $lines = @(Get-Content -LiteralPath $errlog -Tail 120 -ErrorAction SilentlyContinue)
            for ($i = $lines.Count - 1; $i -ge 0; $i--) {
                $mm = [regex]::Match($lines[$i], '(0x[0-9A-Fa-f]{8})')
                if ($mm.Success) { $res.LastError = $mm.Groups[1].Value.ToUpperInvariant(); $tm = [regex]::Match($lines[$i], '^\d{4}-\d{2}-\d{2}\s[\d:]+'); if ($tm.Success) { $res.ErrorTime = $tm.Value }; break }
            }
        }
        $actlog = Join-Path $p 'setupact.log'
        if (Test-Path -LiteralPath $actlog) {
            try { foreach ($h in @(Select-String -LiteralPath $actlog -Pattern 'Provider\s+(wsc:\w+):\s+reports\s+HardBlock' -ErrorAction SilentlyContinue)) { $res.Providers += $h.Matches[0].Groups[1].Value } } catch { }
            $res.Providers = @($res.Providers | Select-Object -Unique)
        }
    }
    $res.Av = @(Get-WuThirdPartyAv)
    $res.KnownApps = @(Get-WuKnownBlockApps)
    $res
}
function Invoke-WrWu([string]$Key) {
    switch ($Key) {
        'WuBlockAnalyze' {
            $b = Get-WuBlockReport
            $found = $false
            if ($b.Panther) { Write-PLog ('   Setup-Protokolle: {0}' -f $b.Panther) } else { Write-PLog '   Keine Setup-Protokolle gefunden (seit dem letzten Aufräumen noch kein Funktionsupdate-Versuch).' }
            if ($b.LastError) { $t = Get-WuErrorText $b.LastError; Write-PLog ('   Letzter Setup-Fehler: {0}{1}{2}' -f $b.LastError, $(if ($b.ErrorTime) { ' (' + $b.ErrorTime + ')' } else { '' }), $(if ($t) { ' - ' + $t } else { '' })) $(if ($t) { 'WARN' } else { 'INFO' }) }
            if ($b.Programs.Count) { $found = $true; foreach ($x in $b.Programs) { Write-PLog ('   HART BLOCKIERENDES PROGRAMM: {0} - vor dem Update deinstallieren (danach wieder installierbar).' -f $x) 'WARN' } }
            if ($b.Providers -contains 'wsc:wica') { $found = $true; Write-PLog '   Fremd-Virenschutz blockiert das Update (wsc:wica HardBlock).' 'WARN' }
            if ($b.Av.Count) { $found = $true; foreach ($x in $b.Av) { Write-PLog ('   Fremd-Virenschutz aktiv: {0} - kann Funktionsupdates blockieren; notfalls deinstallieren (nur Defender lassen).' -f $x) 'WARN' } }
            if ($b.Drivers.Count) { $found = $true; foreach ($x in $b.Drivers) { Write-PLog ('   BLOCKIERENDER/UNSIGNIERTER TREIBER: {0} -> {1}' -f $x, [string]$b.DriverInfo[$x]) 'WARN' } }
            if ($b.KnownApps.Count) { $found = $true; foreach ($x in $b.KnownApps) { Write-PLog ('   Bekannter Upgrade-Blocker installiert: {0} - alte Version vor dem Update entfernen oder aktualisieren.' -f $x) 'WARN' } }
            if ($found) { Write-WrResult ('Blocker gefunden: {0} Programm(e), {1} Treiber, {2} Fremd-Virenschutz. Details oben - diese entfernen/aktualisieren, dann Windows Update erneut.' -f $b.Programs.Count, $b.Drivers.Count, $b.Av.Count) 'WARN' }
            else { Write-WrResult 'Keine bekannten Funktionsupdate-Blocker gefunden (weder Fremd-Virenschutz noch blockierende Programme oder unsignierte Treiber).' 'OK' }
        }
        'WuStuckSetup' {
            $procs = @()
            foreach ($n in 'SetupHost', 'setupprep', 'WindowsUpdateBox', 'SetupPlatform') { $procs += @(Get-Process -Name $n -ErrorAction SilentlyContinue) }
            foreach ($pp in @(Get-Process -Name 'setup' -ErrorAction SilentlyContinue)) { $pth = ''; try { $pth = [string]$pp.Path } catch { }; if ($pth -match '\$WINDOWS\.~(BT|WS)|Windows10Upgrade|\\Sources\\') { $procs += $pp } }
            $procs = @($procs | Sort-Object Id -Unique)
            if (-not $procs.Count) {
                $pend = @(Get-WrPendingInfo)
                if ($pend.Count) { $Script:RebootNeeded = $true; Write-WrResult ('Keine laufende Setup-Instanz, aber {0} wartende Update-Aktion(en) - die lösen die Meldung "andere Instanz von Setup" aus. Bitte neu starten.' -f $pend.Count) 'OK' }
                else { Write-WrResult 'Keine hängende Setup-Instanz und kein wartender Update-Zustand.' 'OK' }
                return
            }
            foreach ($x in $procs) { $age = ''; try { $age = ' (seit {0:HH:mm})' -f $x.StartTime } catch { }; Write-PLog ('   läuft: {0} PID {1}{2}' -f $x.ProcessName, $x.Id, $age) }
            $killed = 0
            foreach ($x in $procs) { try { Stop-Process -Id $x.Id -Force -ErrorAction Stop; $killed++; Write-PLog ('   beendet: {0} PID {1}' -f $x.ProcessName, $x.Id) 'OK' } catch { Write-PLog ('   {0} ließ sich nicht beenden: {1}' -f $x.ProcessName, $_.Exception.Message) 'WARN' } }
            $Script:RebootNeeded = $true
            Write-WrResult ('{0} hängende Setup-Prozess(e) beendet. Nach einem Neustart lässt sich Windows Update oder eine Reparaturinstallation wieder starten.' -f $killed) 'OK'
        }
        'WuVulnDriver' {
            $dir = Get-WrDir; $stamp = Get-WrStamp; $bak = Join-Path $dir ('Treiber-Sicherung_{0}' -f $stamp)
            $pnp = Get-SysExe 'pnputil.exe'; $sc = Get-SysExe 'sc.exe'
            $drvEnum = ''; try { $drvEnum = (@(Invoke-NdCmd $pnp '/enum-drivers' 90) -join "`n") } catch { }
            $hits = 0; $removed = 0
            foreach ($d in $WuVulnDrivers) {
                $f = Join-Path (Join-Path $env:windir 'System32\drivers') $d.File
                if (-not (Test-Path -LiteralPath $f)) { continue }
                $hits++
                Write-PLog ('   gefunden: {0} ({1}) - {2}' -f $d.File, $d.Name, $d.Why) 'WARN'
                $base = [IO.Path]::GetFileNameWithoutExtension($d.File); $oem = ''
                foreach ($rc in @($drvEnum -split "(?:`r?`n){2,}")) { if ($rc -match [regex]::Escape($d.File) -or $rc -match ('(?i)' + [regex]::Escape($base) + '\.inf')) { $mo = [regex]::Match($rc, '(?im)\b(oem\d+\.inf)\b'); if ($mo.Success) { $oem = $mo.Groups[1].Value; break } } }
                if ($oem) { $o = Invoke-NdCmd $pnp ('/delete-driver {0} /uninstall' -f $oem) 60; Write-PLog ('   Treiberpaket {0} entfernt: {1}' -f $oem, (($o -replace '\s+', ' ').Trim())) }
                $null = Invoke-NdCmd $sc ('stop {0}' -f $base) 15; $null = Invoke-NdCmd $sc ('delete {0}' -f $base) 15
                if (Test-Path -LiteralPath $f) {
                    if (-not (Test-Path -LiteralPath $bak)) { New-Item $bak -ItemType Directory -Force | Out-Null }
                    try { Copy-Item -LiteralPath $f -Destination $bak -Force -ErrorAction SilentlyContinue } catch { }
                    try { Remove-Item -LiteralPath $f -Force -ErrorAction Stop; $removed++; Write-PLog ('   {0} gelöscht (Sicherung in {1})' -f $d.File, $bak) 'OK' }
                    catch { Write-PLog ('   {0} ließ sich nicht löschen ({1}) - nach einem Neustart erneut versuchen.' -f $d.File, $_.Exception.Message) 'WARN'; $Script:RebootNeeded = $true }
                }
            }
            if (-not $hits) { Write-WrResult 'Keine bekannten angreifbaren Alt-Treiber (z.B. iqvw64e.sys) gefunden.' 'OK' }
            else { Write-WrResult ('{0} angreifbare(n) Alt-Treiber gefunden, {1} entfernt{2}. Geräte laufen mit den normalen Windows-Treibern weiter.' -f $hits, $removed, $(if (Test-Path -LiteralPath $bak) { ' (Sicherung: ' + $bak + ')' } else { '' })) $(if ($removed -eq $hits) { 'OK' } else { 'WARN' }) }
        }
        'WuReset' {
            $dir = Get-WrDir; $stamp = Get-WrStamp
            $svc = 'wuauserv', 'bits', 'cryptsvc', 'msiserver', 'usosvc', 'dosvc'
            foreach ($s in $svc) {
                $o = Get-Service $s -ErrorAction SilentlyContinue; if (-not $o -or [string]$o.Status -eq 'Stopped') { continue }
                try { Stop-Service $s -Force -ErrorAction Stop; $o.WaitForStatus('Stopped', [TimeSpan]::FromSeconds(30)); Write-PLog ('   Dienst {0} gestoppt' -f $s) } catch { Write-PLog ('   Dienst {0} ließ sich nicht stoppen ({1}) - weiter' -f $s, $_.Exception.Message) }
            }
            foreach ($f in @((Join-Path $env:windir 'SoftwareDistribution'), (Join-Path $env:windir 'System32\catroot2'))) {
                if (-not (Test-Path -LiteralPath $f)) { continue }
                $ok = $false
                for ($t = 0; $t -lt 4 -and -not $ok; $t++) {
                    try { Rename-Item -LiteralPath $f -NewName ((Split-Path $f -Leaf) + '.bak_' + $stamp) -ErrorAction Stop; $ok = $true }
                    catch { Stop-Service cryptsvc, wuauserv, bits -Force -ErrorAction SilentlyContinue; Start-Sleep -Seconds 3 }
                }
                if ($ok) { Write-PLog ('   {0} neu angelegt (alt: {1}.bak_{2})' -f $f, (Split-Path $f -Leaf), $stamp) 'OK' } else { Write-PLog ('   {0} ist gesperrt und konnte nicht umbenannt werden - nach einem Neustart erneut versuchen.' -f $f) 'WARN' }
            }
            $q = @(Get-ChildItem (Join-Path $env:ALLUSERSPROFILE 'Microsoft\Network\Downloader') -Filter 'qmgr*.dat' -Force -ErrorAction SilentlyContinue)
            foreach ($x in $q) { Remove-Item -LiteralPath $x.FullName -Force -ErrorAction SilentlyContinue }
            Write-PLog ('   BITS-Warteschlange: {0} qmgr*.dat gelöscht' -f $q.Count)
            $sc = Get-SysExe 'sc.exe'
            foreach ($s in 'bits', 'wuauserv') {
                $cur = [string](@((Invoke-NdCmd $sc ('sdshow ' + $s) 15) -split "`r?`n" | Where-Object { $_ -match '^\s*D:' }) | Select-Object -First 1)
                $cur = $cur.Trim()
                if (-not $cur) { Write-PLog ('   Berechtigungen von {0} nicht lesbar - übersprungen' -f $s); continue }
                Add-Content -LiteralPath (Join-Path $dir ('Dienstrechte_{0}.txt' -f $stamp)) -Value ('{0}  {1}' -f $s, $cur) -Encoding UTF8
                if (Test-WrSddl $cur) { Write-PLog ('   Berechtigungen von {0}: in Ordnung' -f $s); continue }
                $sacl = ''; $si = $cur.IndexOf('S:'); if ($si -ge 0) { $sacl = $cur.Substring($si) }
                $o = Invoke-NdCmd $sc ('sdset {0} "{1}{2}"' -f $s, $WrStdSddl[$s], $sacl) 15
                Write-PLog ('   Berechtigungen von {0} auf Standard gesetzt (alt gesichert in Dienstrechte_{1}.txt): {2}' -f $s, $stamp, (($o -replace '\s+', ' ').Trim())) $(if ($o -match '(?i)SUCCESS|ERFOLG') { 'OK' } else { 'WARN' })
            }
            Write-PLog '   DLL-Neuregistrierung (regsvr32) übersprungen - seit Windows 10 wirkungslos, Microsoft empfiehlt sie nicht mehr.'
            $null = Invoke-NdCmd (Get-SysExe 'netsh.exe') 'winhttp reset proxy' 20
            foreach ($x in @(@('wuauserv', 'Manual'), @('bits', 'Manual'), @('cryptsvc', 'Automatic'))) {
                $o = Get-Service $x[0] -ErrorAction SilentlyContinue
                if ($o -and [string]$o.StartType -eq 'Disabled') { try { Set-Service $x[0] -StartupType $x[1] -ErrorAction Stop; Write-PLog ('   {0} war deaktiviert - Starttyp {1}' -f $x[0], $x[1]) 'OK' } catch { Write-PLog ('   {0}: {1}' -f $x[0], $_.Exception.Message) 'WARN' } }
            }
            foreach ($s in 'cryptsvc', 'bits', 'wuauserv', 'usosvc') { try { Start-Service $s -ErrorAction Stop } catch { } }
            try { $bj = @(Get-BitsTransfer -AllUsers -ErrorAction Stop); if ($bj.Count) { $bj | Remove-BitsTransfer -ErrorAction SilentlyContinue; Write-PLog ('   {0} hängende BITS-Übertragung(en) entfernt' -f $bj.Count) } } catch { }
            foreach ($pat in @(@($env:windir, 'SoftwareDistribution.bak_*'), @((Join-Path $env:windir 'System32'), 'catroot2.bak_*'))) {
                Get-ChildItem $pat[0] -Directory -Filter $pat[1] -ErrorAction SilentlyContinue | Where-Object { $_.CreationTime -lt (Get-Date).AddDays(-14) } | ForEach-Object { Remove-Item -LiteralPath $_.FullName -Recurse -Force -ErrorAction SilentlyContinue }
            }
            $Script:RebootNeeded = $true
            Write-WrResult 'Windows Update zurückgesetzt - nach dem Neustart sucht und lädt Windows alle Updates neu.' 'OK'
        }
        'WuPendingCheck' {
            $p = @(Get-WrPendingInfo)
            foreach ($x in $p) { Write-PLog ('   ' + $x) }
            if ($p.Count) { $Script:RebootNeeded = $true; Write-WrResult ('Windows wartet auf einen Neustart ({0} Hinweis(e)). Sicherer Weg: neu starten und danach erneut prüfen. Bleibt es über mehrere Neustarts: "Hängende Update-Aktionen zurücknehmen" (WinRE).' -f $p.Count) 'OK' }
            else { Write-WrResult 'Nichts wartet auf einen Neustart.' 'OK' }
        }
        'DoCache' {
            $n = [int64](@(Clear-DeliveryOpt) | Where-Object { $_ -is [ValueType] } | Measure-Object -Sum).Sum
            Write-WrResult ('Zwischenspeicher der Übermittlungsoptimierung geleert ({0}).' -f (Format-Bytes $n)) 'OK'
        }
        'WuTroubleshoot' {
            $pack = Join-Path $env:windir 'diagnostics\system\WindowsUpdate'
            if ((Test-Path -LiteralPath $pack) -and (Get-Command Get-TroubleshootingPack -ErrorAction SilentlyContinue)) {
                $out = Join-Path (Get-WrDir) ('Problembehandlung_{0}' -f (Get-WrStamp)); New-Item $out -ItemType Directory -Force | Out-Null
                try {
                    $tp = Get-TroubleshootingPack -Path $pack -ErrorAction Stop
                    Invoke-TroubleshootingPack -Pack $tp -Unattended -Result $out -ErrorAction Stop | Out-Null
                    $rc = @(); $xf = Get-ChildItem $out -Filter 'ResultReport.xml' -Recurse -ErrorAction SilentlyContinue | Select-Object -First 1
                    if ($xf) { try { $rc = @(([xml](Get-Content -LiteralPath $xf.FullName -Raw)).SelectNodes('//RootCause') | ForEach-Object { '{0}: {1}' -f $_.Name, $_.Status }) } catch { } }
                    foreach ($x in $rc) { Write-PLog ('   ' + $x) }
                    Write-WrResult ('Problembehandlung ausgeführt - Bericht in {0}' -f $out) 'OK'
                } catch { Write-WrResult ('Problembehandlung: {0}' -f $_.Exception.Message) 'WARN' }
            } else { Write-WrResult 'Die klassische Windows Update-Problembehandlung ist in dieser Windows-Version nicht mehr enthalten - Kachel "Problembehandlung in den Einstellungen" benutzen.' 'OK' }
        }
        'WuScan' { Invoke-RepairAction 'WuScan' }
    }
}
function Repair-WrServices([object[]]$Defs, [string]$Group, [bool]$All) {
    $rows = @(Get-WrSvcDiff $Defs $Group)
    if (-not $rows.Count) { Write-WrResult ('Alle {0} Dienste entsprechen der Windows-Vorgabe.' -f @($Defs).Count) 'OK'; return }
    foreach ($r in $rows) { Write-PLog ('   [{0}] {1} ({2}) {3}: ist "{4}", Vorgabe "{5}" - {6}' -f $r.Stufe, $r.Dienst, $r.Name, $r.Feld, $r.Ist, $r.Soll, $r.Hinweis) }
    $fix = @($rows | Where-Object { $_.Fix -and ($All -or $_.Stufe -eq 'Problem') })
    if (-not $fix.Count) { Write-WrResult ('{0} Abweichung(en), aber keine Probleme - nichts geändert (alle Abweichungen anpassen: in der Oberfläche "Alle Abweichungen").' -f $rows.Count) 'OK'; return }
    $bak = Join-Path (Get-WrDir) ('Dienste-Sicherung_{0}' -f (Get-WrStamp)); New-Item $bak -ItemType Directory -Force | Out-Null
    foreach ($n in @($fix | ForEach-Object { $_.Fix.Name } | Select-Object -Unique)) { $null = Invoke-NdCmd (Get-SysExe 'reg.exe') ('export "HKLM\SYSTEM\CurrentControlSet\Services\{0}" "{1}" /y' -f $n, (Join-Path $bak ($n + '.reg'))) 20 }
    $ok = 0; $bad = 0
    foreach ($f in $fix) {
        $x = $f.Fix; $k = 'HKLM:\SYSTEM\CurrentControlSet\Services\' + $x.Name
        try {
            switch ($x.Field) {
                'Start' { Set-ItemProperty -LiteralPath $k -Name Start -Value ([int]$x.Value) -Type DWord -ErrorAction Stop }
                'ImagePath' { Set-ItemProperty -LiteralPath $k -Name ImagePath -Value ([string]$x.Value) -Type ExpandString -ErrorAction Stop }
                'DependOnService' { $v = @(@($x.Value) | Where-Object { $_ }); if ($v.Count) { Set-ItemProperty -LiteralPath $k -Name DependOnService -Value ([string[]]$v) -Type MultiString -ErrorAction Stop } else { Remove-ItemProperty -LiteralPath $k -Name DependOnService -ErrorAction Stop } }
            }
            $ok++; Write-PLog ('   {0} {1} -> {2}' -f $x.Name, $f.Feld, $f.Soll) 'OK'
        } catch {
            $done = $false
            if ($x.Field -eq 'Start') {
                $sn = @('boot', 'system', 'auto', 'demand', 'disabled')[[int]$x.Value]
                $o = Invoke-NdCmd (Get-SysExe 'sc.exe') ('config {0} start= {1}' -f $x.Name, $sn) 20
                if ($o -match '(?i)SUCCESS|ERFOLG') { $done = $true; $ok++; Write-PLog ('   {0} Starttyp -> {1} (sc config)' -f $x.Name, $f.Soll) 'OK' }
            }
            if (-not $done) { $bad++; Write-PLog ('   {0} {1}: {2} - geschützter Dienst, bleibt nur Abbild-/SFC-Reparatur oder Reparaturinstallation.' -f $x.Name, $f.Feld, $_.Exception.Message) 'WARN' }
        }
    }
    $Script:RebootNeeded = $true
    Write-WrResult ('{0} Wert(e) auf Windows-Standard gesetzt{1}. Sicherung (reg-Dateien): {2}' -f $ok, $(if ($bad) { ', {0} nicht änderbar' -f $bad } else { '' }), $bak) $(if ($bad) { 'WARN' } else { 'OK' })
}
function Get-WrHwAdapters { @(Get-NetAdapter -Physical -ErrorAction SilentlyContinue | Where-Object { $_.InterfaceDescription -notmatch 'Bluetooth' }) }
function Invoke-WrNet([string]$Key) {
    $netsh = Get-SysExe 'netsh.exe'
    switch ($Key) {
        'NetEvidence' {
            $dir = Get-WrDir; $stamp = Get-WrStamp; $f = Join-Path $dir ('Netzwerk-Beweis_{0}.txt' -f $stamp)
            $L = [System.Collections.Generic.List[string]]::new()
            $add = { param($t, $x) $L.Add(''); $L.Add(('===== {0} =====' -f $t)); $L.Add(([string]$x).TrimEnd()) }
            $L.Add(('PC-Tools Netzwerk-Beweissicherung {0} - {1:dd.MM.yyyy HH:mm:ss}' -f $env:COMPUTERNAME, (Get-Date)))
            & $add 'ipconfig /all' (Invoke-NdCmd 'ipconfig.exe' '/all' 30)
            & $add 'netsh interface ipv4 show interfaces' (Invoke-NdCmd $netsh 'interface ipv4 show interfaces' 30)
            & $add 'netsh interface ipv4 show config' (Invoke-NdCmd $netsh 'interface ipv4 show config' 30)
            & $add 'route print -4' (Invoke-NdCmd 'route.exe' 'print -4' 30)
            & $add 'Adapter und Treiber' (Get-NetAdapter -IncludeHidden -ErrorAction SilentlyContinue | Sort-Object Name | Format-Table Name, InterfaceDescription, Status, MacAddress, DriverProvider, DriverVersion, DriverDate -AutoSize | Out-String -Width 260)
            & $add 'Bindungen (alle)' (Get-NetAdapterBinding -AllBindings -ErrorAction SilentlyContinue | Sort-Object Name, ComponentID | Format-Table Name, DisplayName, ComponentID, Enabled -AutoSize | Out-String -Width 260)
            & $add 'pnputil /enum-drivers /class NetService' (Invoke-NdCmd 'pnputil.exe' '/enum-drivers /class NetService' 60)
            & $add 'netsh winsock show catalog' (Invoke-NdCmd $netsh 'winsock show catalog' 30)
            & $add 'Netzwerkdienste (Zustand)' (Get-Service -Name @($WrNetSvcDefaults | Where-Object { $_.Img -notmatch '\.sys$' } | ForEach-Object { $_.Name }) -ErrorAction SilentlyContinue | Format-Table Name, Status, StartType, DisplayName -AutoSize | Out-String -Width 200)
            & $add 'Netzwerkdienste (Abweichungen von der Vorgabe)' (@(Get-WrSvcDiff $WrNetSvcDefaults) | Format-Table Dienst, Feld, Ist, Soll, Stufe -AutoSize | Out-String -Width 260)
            $dc = (Get-ItemProperty 'HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip6\Parameters' -Name DisabledComponents -ErrorAction SilentlyContinue).DisabledComponents
            & $add 'IPv6 DisabledComponents / DHCP-Broadcast-Wechsel' ((Get-WrDisabledComponentsText ([int64]$(if ($dc) { $dc } else { 0 }))) + "`r`nDhcpConnEnableBcastFlagToggle = " + [string](Get-ItemProperty 'HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters' -Name DhcpConnEnableBcastFlagToggle -ErrorAction SilentlyContinue).DhcpConnEnableBcastFlagToggle)
            & $add 'DHCP-Client-Ereignisse (Admin, letzte 40)' (Get-WinEvent -LogName 'Microsoft-Windows-Dhcp-Client/Admin' -MaxEvents 40 -ErrorAction SilentlyContinue | Format-Table TimeCreated, Id, LevelDisplayName, Message -Wrap -AutoSize | Out-String -Width 260)
            $wf = Join-Path $dir ('WFP-Zustand_{0}.xml' -f $stamp)
            $null = Invoke-NdCmd $netsh ('wfp show state file="{0}"' -f $wf) 180
            & $add 'netsh wfp show state' $(if (Test-Path -LiteralPath $wf) { 'gespeichert in ' + $wf } else { 'nicht erstellt' })
            Set-Content -LiteralPath $f -Value $L -Encoding UTF8
            try { $null = Invoke-NetDiagFix 'DhcpLog'; Write-PLog '   DHCP-Detailprotokoll (Microsoft-Windows-Dhcp-Client/Operational) eingeschaltet - nach dem Neustart zeigt es jede Anfrage und Antwort.' } catch { }
            Write-WrResult ('Ist-Zustand gesichert: {0}' -f $f) 'OK'
        }
        'NetSvcDefaults' { Repair-WrServices $WrNetSvcDefaults 'Netzwerk' ([bool]$Script:JobOpts.SvcAll) }
        'NetIpv4Fix' {
            $n = 0; $dir = Get-WrDir
            foreach ($a in (Get-WrHwAdapters | Where-Object { [string]$_.Status -ne 'Disabled' })) {
                $b = Get-NetAdapterBinding -Name $a.Name -ComponentID ms_tcpip -ErrorAction SilentlyContinue
                if ($b -and -not $b.Enabled) { Write-PLog ('   {0}: {1}' -f $a.Name, (Invoke-NetDiagFix 'Bind' $a.ifIndex 'ms_tcpip')) 'OK'; $n++ }
                $k = 'HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters\Interfaces\' + $a.InterfaceGuid
                $p = Get-ItemProperty -LiteralPath $k -ErrorAction SilentlyContinue
                $i = Get-NetIPInterface -InterfaceIndex $a.ifIndex -AddressFamily IPv4 -ErrorAction SilentlyContinue
                $man = @(Get-NetIPAddress -InterfaceIndex $a.ifIndex -AddressFamily IPv4 -ErrorAction SilentlyContinue | Where-Object { [string]$_.PrefixOrigin -eq 'Manual' })
                if (($i -and [string]$i.Dhcp -ne 'Enabled') -or $man.Count) { Write-PLog ('   {0}: {1}' -f $a.Name, (Invoke-NetDiagFix 'SetDhcp' $a.ifIndex)) 'OK'; $n++; continue }
                if ($p -and [int]$p.EnableDHCP -eq 1) {
                    $stale = @(@($p.IPAddress) | Where-Object { $_ -and $_ -ne '0.0.0.0' })
                    if ($stale.Count) {
                        $null = Invoke-NdCmd (Get-SysExe 'reg.exe') ('export "HKLM\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters\Interfaces\{0}" "{1}" /y' -f $a.InterfaceGuid, (Join-Path $dir ('Tcpip-Interface_{0}_{1}.reg' -f $a.ifIndex, (Get-WrStamp)))) 20
                        Set-ItemProperty -LiteralPath $k -Name IPAddress -Value ([string[]]@('0.0.0.0')) -Type MultiString -ErrorAction SilentlyContinue
                        Set-ItemProperty -LiteralPath $k -Name SubnetMask -Value ([string[]]@('0.0.0.0')) -Type MultiString -ErrorAction SilentlyContinue
                        Remove-ItemProperty -LiteralPath $k -Name DefaultGateway, DefaultGatewayMetric -ErrorAction SilentlyContinue
                        Write-PLog ('   {0}: alte feste Adresse {1} aus der Registrierung entfernt (DHCP bleibt an, Sicherung als .reg)' -f $a.Name, ($stale -join ', ')) 'OK'; $n++
                    }
                }
            }
            Write-WrResult $(if ($n) { '{0} IPv4-Einstellung(en) auf automatischen Bezug korrigiert.' -f $n } else { 'IPv4 und DHCP sind an allen Adaptern richtig eingestellt.' }) 'OK'
        }
        'NetIpv6Comp' {
            $k = 'HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip6\Parameters'
            $v = (Get-ItemProperty $k -Name DisabledComponents -ErrorAction SilentlyContinue).DisabledComponents
            if ($null -eq $v -or [int64]$v -eq 0) { Write-WrResult 'DisabledComponents steht auf Windows-Standard (0).' 'OK'; return }
            Write-PLog ('   bisher: ' + (Get-WrDisabledComponentsText ([int64]$v)))
            Set-PReg $k 'DisabledComponents' 0
            $Script:RebootNeeded = $true
            Write-WrResult ('DisabledComponents von 0x{0:X} auf 0 gesetzt - wirkt nach dem Neustart.' -f [int64]$v) 'OK'
        }
        'NetBcastToggle' {
            Set-PReg 'HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters' 'DhcpConnEnableBcastFlagToggle' 1
            Write-WrResult 'DHCP-Broadcast-Wechsel eingeschaltet (wirkt ab dem nächsten Adapter- oder PC-Neustart).' 'OK'
        }
        'NetFilterOff' {
            $done = [System.Collections.Generic.List[object]]::new(); $ads = @{}
            foreach ($a in (Get-WrHwAdapters)) {
                foreach ($b in @(Get-NetAdapterBinding -Name $a.Name -AllBindings -ErrorAction SilentlyContinue | Where-Object { $_.Enabled -and [string]$_.ComponentID -notmatch '^(ms_|vms_)' })) {
                    try { Disable-NetAdapterBinding -Name $a.Name -ComponentID $b.ComponentID -ErrorAction Stop; $done.Add([pscustomobject]@{ Adapter = $a.Name; ComponentID = [string]$b.ComponentID; DisplayName = [string]$b.DisplayName }); $ads[$a.Name] = $true; Write-PLog ('   {0}: "{1}" ({2}) gelöst' -f $a.Name, $b.DisplayName, $b.ComponentID) 'OK' }
                    catch { Write-PLog ('   {0}: "{1}" ließ sich nicht lösen: {2}' -f $a.Name, $b.DisplayName, $_.Exception.Message) 'WARN' }
                }
            }
            if (-not $done.Count) { Write-WrResult 'Keine aktiven Filter oder Protokolle von Drittanbietern gefunden.' 'OK'; return }
            $jf = Join-Path (Get-WrDir) ('Filter-Bindungen_{0}.json' -f (Get-WrStamp)); $done | ConvertTo-Json -Depth 3 | Set-Content -LiteralPath $jf -Encoding UTF8
            foreach ($n in $ads.Keys) { try { Restart-NetAdapter -Name $n -Confirm:$false -ErrorAction Stop } catch { } }
            Write-WrResult ('{0} fremde Bindung(en) gelöst (Liste: {1}). Wieder einschalten über die Filterliste auf der Seite.' -f $done.Count, $jf) 'OK'
        }
        'NetGhost' {
            $g = @(Get-PnpDevice -Class Net -ErrorAction SilentlyContinue | Where-Object { -not $_.Present })
            foreach ($d in $g) { $o = Invoke-NdCmd 'pnputil.exe' ('/remove-device "{0}"' -f $d.InstanceId) 30; Write-PLog ('   entfernt: {0} - {1}' -f $d.FriendlyName, (($o -split "`r?`n" | Where-Object { $_.Trim() } | Select-Object -Last 1) -join '')) }
            Write-WrResult $(if ($g.Count) { '{0} nicht mehr vorhandene Netzwerkadapter entfernt.' -f $g.Count } else { 'Keine versteckten Netzwerkadapter gefunden.' }) 'OK'
        }
        'NetDrvReinstall' {
            $ads = @(Get-WrHwAdapters | Where-Object { $_.InterfaceDescription -notmatch 'Hyper-V|Virtual|VPN|TAP' })
            foreach ($a in $ads) { try { Write-PLog ('   {0}: {1}' -f $a.Name, (Invoke-NetDiagFix 'DrvRe' $a.ifIndex)) 'OK' } catch { Write-PLog ('   {0}: {1}' -f $a.Name, $_.Exception.Message) 'WARN' } }
            Write-WrResult ('{0} Adapter entfernt und neu erkannt.' -f $ads.Count) 'OK'
        }
        'NetWinhttp' { Write-WrResult (Invoke-NetDiagFix 'ProxyOff') 'OK' }
        'NetFlush' {
            $t = Invoke-NetDiagFix 'Flush'
            $o = Invoke-NdCmd (Get-SysExe 'nbtstat.exe') '-R' 20
            Write-WrResult ('{0} NetBIOS-Namenscache neu geladen.' -f $t) 'OK'
            if ($o -match '\S') { Write-PLog ('   ' + (($o -replace '\s+', ' ').Trim())) }
        }
        'NetRenew' {
            $null = Invoke-NdCmd 'ipconfig.exe' '/release' 40; Start-Sleep -Seconds 2
            $o = Invoke-NdCmd 'ipconfig.exe' '/renew' 90
            $ips = @(foreach ($a in (Get-WrHwAdapters | Where-Object { [string]$_.Status -eq 'Up' })) { '{0}: {1}' -f $a.Name, $(if ($x = Get-NdIpv4 $a.ifIndex) { $x } else { 'keine Adresse' }) })
            $bad = ($o -match '(?i)Fehler|error|Zeitüberschreitung|timeout|konnte nicht|unable')
            Write-WrResult ('Adressen neu angefordert: {0}' -f $(if ($ips.Count) { $ips -join ', ' } else { 'kein verbundener Adapter' })) $(if ($bad) { 'WARN' } else { 'OK' })
        }
        { $_ -in 'NetIpReset', 'NetIpv6Reset' } {
            $v6 = $Key -eq 'NetIpv6Reset'
            $lf = Join-Path (Get-WrDir) ('{0}_{1}.log' -f $(if ($v6) { 'ipv6reset' } else { 'ipreset' }), (Get-WrStamp))
            $o = Invoke-NdCmd $netsh ('int {0} reset "{1}"' -f $(if ($v6) { 'ipv6' } else { 'ip' }), $lf) 90
            foreach ($x in @($o -split "`r?`n" | Where-Object { $_.Trim() } | Select-Object -First 30)) { Write-PLog ('   ' + $x.Trim()) }
            $Script:RebootNeeded = $true
            Write-WrResult ('{0} zurückgesetzt - Neustart nötig. Protokoll: {1}' -f $(if ($v6) { 'IPv6' } else { 'TCP/IP (IPv4)' }), $lf) $(if ($o -match '(?i)Zugriff verweigert|Access is denied|fehlgeschlagen|failed') { 'WARN' } else { 'OK' })
        }
        'NetWinsock' { $Script:RebootNeeded = $true; Write-WrResult (Invoke-NetDiagFix 'Winsock') 'OK' }
        'NetWfp' {
            $dir = Get-WrDir; $stamp = Get-WrStamp
            $f1 = Join-Path $dir ('WFP-Zustand_{0}.xml' -f $stamp); $f2 = Join-Path $dir ('WFP-Filter_{0}.xml' -f $stamp)
            $null = Invoke-NdCmd $netsh ('wfp show state file="{0}"' -f $f1) 180
            $null = Invoke-NdCmd $netsh ('wfp show filters file="{0}"' -f $f2) 180
            $cnt = 0; try { $cnt = ([regex]::Matches([IO.File]::ReadAllText($f2), '<filterKey>')).Count } catch { }
            $run = @((Get-Service BFE -ErrorAction SilentlyContinue).DependentServices | Where-Object { [string]$_.Status -eq 'Running' } | ForEach-Object { $_.Name })
            try { Restart-Service BFE -Force -ErrorAction Stop; Write-PLog '   Basisfiltermodul (BFE) neu gestartet' 'OK' } catch { Write-PLog ('   BFE: {0}' -f $_.Exception.Message) 'WARN' }
            foreach ($s in @(@('mpssvc') + $run | Select-Object -Unique)) { try { Start-Service $s -ErrorAction Stop } catch { } }
            $fw = Get-Service mpssvc -ErrorAction SilentlyContinue
            Write-WrResult ('Filterplattform gesichert ({0} Filter, Dateien WFP-*_{1}.xml im Datenordner), BFE neu gestartet, Firewall {2}.' -f $cnt, $stamp, $(if ($fw -and [string]$fw.Status -eq 'Running') { 'läuft' } else { 'läuft NICHT' })) $(if ($fw -and [string]$fw.Status -eq 'Running') { 'OK' } else { 'WARN' })
        }
        'NetFirewallReset' {
            $wf = Join-Path (Get-WrDir) ('Firewall_{0}.wfw' -f (Get-WrStamp))
            $o1 = Invoke-NdCmd $netsh ('advfirewall export "{0}"' -f $wf) 60
            if (-not (Test-Path -LiteralPath $wf)) { Write-WrResult ('Sicherung der Firewall-Regeln fehlgeschlagen ({0}) - Firewall bleibt unverändert.' -f (($o1 -replace '\s+', ' ').Trim())) 'WARN'; return }
            $o2 = Invoke-NdCmd $netsh 'advfirewall reset' 60
            try { $null = Invoke-NetDiagFix 'DhcpFw' } catch { }
            Write-WrResult ('Windows-Firewall auf Standard gesetzt. Sicherung: {0} (zurück mit: netsh advfirewall import "{0}")' -f $wf) $(if ($o2 -match '(?i)OK|erfolgreich') { 'OK' } else { 'WARN' })
        }
        'NetNetcfg' { $Script:RebootNeeded = $true; Write-WrResult (Invoke-NetDiagFix 'Deep' 0 'netcfg') 'OK' }
    }
}
function Invoke-WrBoot([string]$Key) {
    $bcd = Get-SysExe 'bcdedit.exe'; $rc = Get-SysExe 'reagentc.exe'
    switch ($Key) {
        'BcdExport' {
            $f = Join-Path (Get-WrDir) ('BCD-Sicherung_{0}' -f (Get-WrStamp))
            $o = Invoke-NdCmd $bcd ('/export "{0}"' -f $f) 30
            Set-Content -LiteralPath ($f + '.txt') -Value (Invoke-NdCmd $bcd '/enum all' 30) -Encoding UTF8
            Write-WrResult ('Startkonfiguration gesichert: {0} (lesbar: {0}.txt, zurück mit bcdedit /import)' -f $f) $(if (Test-Path -LiteralPath $f) { 'OK' } else { 'WARN' })
            if (-not (Test-Path -LiteralPath $f)) { Write-PLog ('   ' + (($o -replace '\s+', ' ').Trim())) }
        }
        'BootFiles' {
            Invoke-WrBoot 'BcdExport'
            try { $bl = Get-BitLockerVolume -MountPoint $env:SystemDrive -ErrorAction Stop; if ([string]$bl.ProtectionStatus -eq 'On') { $null = Suspend-BitLocker -MountPoint $env:SystemDrive -RebootCount 1 -ErrorAction Stop; Write-PLog '   BitLocker für EINEN Neustart angehalten (schaltet sich danach selbst wieder ein) - sonst würde der geänderte Start-Manager den Wiederherstellungsschlüssel verlangen.' 'OK' } } catch { }
            $bb = Get-SysExe 'bcdboot.exe'; $win = $env:SystemRoot
            $info = Get-WrBcdInfo (Invoke-NdCmd $bcd '/enum {current}' 30)
            if ($env:firmware_type -eq 'UEFI' -or $info.Uefi) {
                $letter = @('S', 'T', 'U', 'V', 'W', 'X', 'Y', 'Z', 'R', 'Q', 'P') | Where-Object { -not (Test-Path ($_ + ':\')) } | Select-Object -First 1
                $mv = Get-SysExe 'mountvol.exe'
                $null = Invoke-NdCmd $mv ('{0}: /s' -f $letter) 20
                if (-not (Test-Path ($letter + ':\EFI'))) { $null = Invoke-NdCmd $mv ('{0}: /d' -f $letter) 20; Write-WrResult 'Die EFI-Systempartition ließ sich nicht einbinden - nichts geändert. In diesem Fall hilft der Notfall-Stick (Reparatur-Menü Punkt 1).' 'WARN'; return }
                try { $r = Invoke-WrExe $bb ('"{0}" /s {1}: /f UEFI' -f $win, $letter) 5 -Label 'bcdboot' } finally { $null = Invoke-NdCmd $mv ('{0}: /d' -f $letter) 20 }
            } else { $r = Invoke-WrExe $bb ('"{0}"' -f $win) 5 -Label 'bcdboot' }
            $Script:RebootNeeded = $true
            Write-WrResult $(if ($r.Code -eq 0) { 'Startdateien und Startkonfiguration neu geschrieben.' } else { 'bcdboot meldet Code {0} - Sicherung der Startkonfiguration liegt im Datenordner.' -f $r.Code }) $(if ($r.Code -eq 0) { 'OK' } else { 'WARN' })
        }
        'WinReInfo' {
            $o = Invoke-NdCmd $rc '/info' 60
            foreach ($x in @($o -split "`r?`n" | Where-Object { $_.Trim() })) { Write-PLog ('   ' + $x.Trim()) }
            $i = ConvertFrom-WrReagentc $o
            Write-WrResult $(if ($i.Enabled) { 'WinRE ist eingeschaltet ({0}).' -f $i.Location } else { 'WinRE ist AUS - "Wiederherstellungsumgebung einschalten" ausführen.' }) $(if ($i.Enabled) { 'OK' } else { 'WARN' })
        }
        'WinReEnable' {
            if ((ConvertFrom-WrReagentc (Invoke-NdCmd $rc '/info' 60)).Enabled) { Write-WrResult 'WinRE ist bereits eingeschaltet.' 'OK'; return }
            $o = Invoke-NdCmd $rc '/enable' 120; Write-PLog ('   reagentc /enable: ' + (($o -replace '\s+', ' ').Trim()))
            if ((ConvertFrom-WrReagentc (Invoke-NdCmd $rc '/info' 60)).Enabled) { Write-WrResult 'WinRE eingeschaltet.' 'OK'; return }
            $re = Join-Path $env:windir 'System32\Recovery\Winre.wim'
            if (Test-Path -LiteralPath $re) { Write-WrResult 'Winre.wim ist vorhanden, aber reagentc /enable schlägt fehl - meist ist die Wiederherstellungspartition zu klein oder C:\Windows\System32\Recovery\ReAgent.xml beschädigt (Microsoft-Anleitung KB5028997 "WinRE-Partition vergrößern").' 'WARN'; return }
            $s = Get-WrSource
            if (-not $s) { Write-WrResult 'Die Datei Winre.wim fehlt. Oben eine Windows-ISO als Reparaturquelle wählen und erneut ausführen - PC-Tools holt die Datei dann daraus.' 'WARN'; return }
            $dism = Get-SysExe 'Dism.exe'
            $tmp = Join-Path $env:SystemDrive ('PCTools-WinRE-' + (Get-WrStamp)); $mnt = Join-Path $tmp 'mnt'; New-Item $mnt -ItemType Directory -Force | Out-Null
            try {
                $img = $s.Wim; $ix = $s.Index
                if ($s.Kind -eq 'ESD') {
                    if ((Get-FreeBytes) -lt 12GB) { throw 'Für das Auspacken aus der install.esd werden mindestens 12 GB frei auf C: gebraucht.' }
                    $w2 = Join-Path $tmp 'install.wim'
                    $r = Invoke-WrExe $dism ('/Export-Image /SourceImageFile:"{0}" /SourceIndex:{1} /DestinationImageFile:"{2}" /Compress:max /CheckIntegrity' -f $img, $ix, $w2) 90 -Label 'DISM Export'
                    if ($r.Code -ne 0) { throw ('Export aus der install.esd fehlgeschlagen (Code {0})' -f $r.Code) }
                    $img = $w2; $ix = 1
                }
                $r = Invoke-WrExe $dism ('/Mount-Image /ImageFile:"{0}" /Index:{1} /MountDir:"{2}" /ReadOnly' -f $img, $ix, $mnt) 30 -Label 'DISM Einbinden'
                if ($r.Code -ne 0) { throw ('Abbild ließ sich nicht einbinden (Code {0})' -f $r.Code) }
                try {
                    $src = Join-Path $mnt 'Windows\System32\Recovery\Winre.wim'
                    if (-not (Test-Path -LiteralPath $src)) { throw 'Winre.wim fehlt auch im Abbild der ISO.' }
                    New-Item (Split-Path $re) -ItemType Directory -Force | Out-Null
                    Copy-Item -LiteralPath $src -Destination $re -Force
                    Write-PLog '   Winre.wim aus der ISO kopiert' 'OK'
                } finally { $null = Invoke-WrExe $dism ('/Unmount-Image /MountDir:"{0}" /Discard' -f $mnt) 20 -Label 'DISM Aushängen' -Silent }
                $null = Invoke-NdCmd $rc ('/setreimage /path "{0}"' -f (Split-Path $re)) 60
                $o = Invoke-NdCmd $rc '/enable' 120
                $ok = (ConvertFrom-WrReagentc (Invoke-NdCmd $rc '/info' 60)).Enabled
                Write-WrResult $(if ($ok) { 'Winre.wim wiederhergestellt und WinRE eingeschaltet.' } else { 'Winre.wim wiederhergestellt, reagentc /enable meldet aber: ' + (($o -replace '\s+', ' ').Trim()) }) $(if ($ok) { 'OK' } else { 'WARN' })
            } catch { Write-WrResult ('WinRE: {0}' -f $_.Exception.Message) 'WARN' }
            finally { Remove-Item -LiteralPath $tmp -Recurse -Force -ErrorAction SilentlyContinue }
        }
        { $_ -in 'BootLogOn', 'BootLogOff' } {
            $on = $Key -eq 'BootLogOn'
            $o = Invoke-NdCmd $bcd ('/set {{current}} bootlog {0}' -f $(if ($on) { 'yes' } else { 'no' })) 20
            $ok = $o -match '(?i)erfolgreich|successfully'
            if ($on -and $ok) { $Script:RebootNeeded = $true }
            Write-WrResult $(if (-not $ok) { 'bcdedit: ' + (($o -replace '\s+', ' ').Trim()) } elseif ($on) { 'Startprotokoll ein - nach dem Neustart steht es in C:\Windows\ntbtlog.txt.' } else { 'Startprotokoll aus.' }) $(if ($ok) { 'OK' } else { 'WARN' })
        }
        'ChkScan' {
            $r = Invoke-WrExe (Get-SysExe 'chkdsk.exe') ('{0} /scan' -f $env:SystemDrive) 180 -Label 'chkdsk' -Silent
            foreach ($x in @($r.Text -split "`r?`n" | Where-Object { $_ -match '(?i)fehler|error|problem|korrigiert|fixed|gefunden|found|keine|no ' } | Select-Object -Last 8)) { Write-PLog ('   ' + $x.Trim()) }
            $t = switch ($r.Code) { 0 { 'Keine Fehler im Dateisystem gefunden.' } 1 { 'Fehler gefunden und korrigiert.' } 2 { 'Bereinigung durchgeführt - für die vollständige Reparatur "beim Neustart reparieren" ausführen.' } 3 { 'Fehler gefunden, die nur beim Neustart repariert werden können - "Laufwerk C: beim Neustart reparieren".' } default { 'chkdsk meldet Code {0}.' -f $r.Code } }
            Write-WrResult $t $(if ($r.Code -in 0, 1) { 'OK' } else { 'WARN' })
        }
        'ChkBoot' {
            Invoke-RepairAction 'ChkBoot'
            $o = Invoke-NdCmd (Get-SysExe 'chkntfs.exe') $env:SystemDrive 20
            Write-WrResult ('Prüfung beim nächsten Start vorgemerkt. chkntfs: {0}' -f (($o -replace '\s+', ' ').Trim())) 'OK'
        }
        'DirtyQuery' {
            $o1 = Invoke-NdCmd (Get-SysExe 'fsutil.exe') ('dirty query {0}' -f $env:SystemDrive) 20
            $o2 = Invoke-NdCmd (Get-SysExe 'chkntfs.exe') $env:SystemDrive 20
            Write-PLog ('   fsutil: ' + (($o1 -replace '\s+', ' ').Trim())); Write-PLog ('   chkntfs: ' + (($o2 -replace '\s+', ' ').Trim()))
            $dirty = ($o1 -notmatch '(?i)NICHT|NOT') -and ($o1 -match '(?i)fehlerhaft|dirty')
            Write-WrResult $(if ($dirty) { 'Laufwerk {0} ist als fehlerhaft markiert - "beim Neustart reparieren" ausführen.' -f $env:SystemDrive } else { 'Laufwerk {0} ist nicht als fehlerhaft markiert.' -f $env:SystemDrive }) $(if ($dirty) { 'WARN' } else { 'OK' })
        }
    }
}
function Invoke-WrApps([string]$Key) {
    switch ($Key) {
        'AppxUser' {
            $ok = 0; $bad = 0; $pk = @(Get-AppxPackage -ErrorAction SilentlyContinue | Where-Object { $_.InstallLocation -and -not $_.IsFramework })
            $i = 0
            foreach ($p in $pk) {
                if (Test-PCancel) { break }
                $i++; $m = Join-Path $p.InstallLocation 'AppxManifest.xml'; if (-not (Test-Path -LiteralPath $m)) { continue }
                $Script:Detail = ('{0}/{1}: {2}' -f $i, $pk.Count, $p.Name); Update-PHeartbeat
                try { Add-AppxPackage -DisableDevelopmentMode -Register $m -ErrorAction Stop; $ok++ } catch { $bad++ }
            }
            Write-WrResult ('{0} Apps neu registriert, {1} übersprungen (laufen gerade oder sind schon aktuell).' -f $ok, $bad) 'OK'
        }
        'AppxAll' { Invoke-RepairAction 'AppsReregister' }
        'StoreReset' { Invoke-RepairAction 'StoreReset' }
        'StartSearch' { Invoke-RepairAction 'StartMenuFix' }
        'SearchIndex' { Invoke-RepairAction 'SearchReset' }
        'IconCache' {
            Get-Process explorer -ErrorAction SilentlyContinue | Where-Object { $_.SessionId -eq (Get-Process -Id $PID).SessionId } | Stop-Process -Force -ErrorAction SilentlyContinue
            Start-Sleep -Seconds 2
            $n = 0; $ex = Join-Path $env:LOCALAPPDATA 'Microsoft\Windows\Explorer'
            foreach ($f in @(@(Get-Item -LiteralPath (Join-Path $env:LOCALAPPDATA 'IconCache.db') -Force -ErrorAction SilentlyContinue) + @(Get-ChildItem -LiteralPath $ex -Filter '*cache_*.db' -Force -ErrorAction SilentlyContinue))) { try { Remove-Item -LiteralPath $f.FullName -Force -ErrorAction Stop; $n++ } catch { } }
            Restart-Explorer
            Write-WrResult ('{0} Cache-Datei(en) gelöscht, Explorer neu gestartet - Symbole und Vorschaubilder werden neu aufgebaut.' -f $n) 'OK'
        }
        'FontCache' { Invoke-RepairAction 'FontCache'; $Script:RebootNeeded = $true }
        'ExplorerRestart' { Restart-Explorer; Write-WrResult 'Explorer und Taskleiste neu gestartet.' 'OK' }
        'WingetReset' { Invoke-RepairAction 'WingetReset' }
    }
}
function Invoke-WrComp([string]$Key) {
    switch ($Key) {
        'WmiCheck' { Invoke-RepairAction 'Wmi' }
        'PerfCounters' { Invoke-RepairAction 'PerfCounters' }
        'NetFx3' {
            $st = ''; try { $st = [string](Get-WindowsOptionalFeature -Online -FeatureName NetFx3 -ErrorAction Stop).State } catch { }
            Write-PLog ('   .NET Framework 3.5 bisher: {0}' -f $(if ($st) { $st } else { 'unbekannt' }))
            $a = '/Online /Enable-Feature /FeatureName:NetFx3 /All /NoRestart'
            $s = Get-WrSource; if ($s -and $s.Sxs) { $a += (' /Source:"{0}" /LimitAccess' -f $s.Sxs) }
            $r = Invoke-WrExe (Get-SysExe 'Dism.exe') $a 60 -Label 'DISM NetFx3'
            if ($r.Code -eq 3010) { $Script:RebootNeeded = $true }
            $v = Get-WrDismVerdict $r.Text
            Write-WrResult $(if ($r.Code -in 0, 3010) { '.NET Framework 3.5 ist eingeschaltet.' } else { $v.Text }) $(if ($r.Code -in 0, 3010) { 'OK' } else { 'WARN' })
        }
        'VcRedist' {
            $wg = Get-WingetPath
            if (-not $wg) { Write-WrResult 'winget nicht gefunden - "Store und App-Installer" reparieren oder die Laufzeiten von aka.ms/vs/17/release/vc_redist.x64.exe laden.' 'WARN'; return }
            $ids = @('Microsoft.VCRedist.2015+.x64', 'Microsoft.VCRedist.2015+.x86')
            if ((Get-WrArchName $(if ($env:PROCESSOR_ARCHITEW6432) { $env:PROCESSOR_ARCHITEW6432 } else { $env:PROCESSOR_ARCHITECTURE })) -eq 'arm64') { $ids += 'Microsoft.VCRedist.2015+.arm64' }
            $okc = 0
            foreach ($id in $ids) {
                $Script:Detail = $id; Set-PStatus ('Visual C++: {0}' -f $id)
                $c = Invoke-External -Exe $wg -Arguments @('install', '--id', $id, '--exact', '--silent', '--force', '--accept-package-agreements', '--accept-source-agreements', '--disable-interactivity') -TimeoutMin 15
                if ($c -eq 3010) { $Script:RebootNeeded = $true }
                if ($c -in 0, 3010, -1978335189, -1978335135) { $okc++; Write-PLog ('   {0}: installiert' -f $id) 'OK' } else { Write-PLog ('   {0}: winget-Code {1}' -f $id, $c) 'WARN' }
            }
            Write-WrResult ('{0} von {1} Visual-C++-Laufzeiten neu installiert.' -f $okc, $ids.Count) $(if ($okc -eq $ids.Count) { 'OK' } else { 'WARN' })
        }
        'GpReset' {
            try { $cs = Get-CimInstance Win32_ComputerSystem -ErrorAction Stop; if ($cs.PartOfDomain) { Write-PLog ('   Achtung: Mitglied der Domäne {0} - Domänenrichtlinien kommen beim nächsten Abgleich wieder vom Server.' -f $cs.Domain) } } catch { }
            $gp = Join-Path $env:windir 'System32\GroupPolicy'; $bak = Join-Path (Get-WrDir) ('GPO-Sicherung_{0}' -f (Get-WrStamp))
            if (Test-Path -LiteralPath $gp) { try { Copy-Item -LiteralPath $gp -Destination $bak -Recurse -Force -ErrorAction Stop; Write-PLog ('   Sicherung: {0}' -f $bak) } catch { Write-WrResult ('Sicherung fehlgeschlagen ({0}) - nichts gelöscht.' -f $_.Exception.Message) 'WARN'; return } }
            $n = 0
            foreach ($f in 'Machine\Registry.pol', 'User\Registry.pol') { $p = Join-Path $gp $f; if (Test-Path -LiteralPath $p) { Remove-Item -LiteralPath $p -Force -ErrorAction SilentlyContinue; if (-not (Test-Path -LiteralPath $p)) { $n++; Write-PLog ('   gelöscht: ' + $p) } } }
            $c = Invoke-External -Exe (Get-SysExe 'gpupdate.exe') -Arguments @('/force') -TimeoutMin 10 -OemEncoding
            $Script:RebootNeeded = $true
            Write-WrResult ('{0} Richtliniendatei(en) zurückgesetzt, gpupdate Code {1}. Sicherung: {2} (zurück: Dateien nach %windir%\System32\GroupPolicy kopieren).' -f $n, $c, $bak) $(if ($c -eq 0) { 'OK' } else { 'WARN' })
        }
        'Spooler' { Invoke-RepairAction 'Spooler' }
        'TimeSync' {
            $w = Get-SysExe 'w32tm.exe'
            Stop-Service W32Time -Force -ErrorAction SilentlyContinue; Start-Sleep -Seconds 2
            $o1 = Invoke-NdCmd $w '/unregister' 30; Start-Sleep -Seconds 2
            $o2 = Invoke-NdCmd $w '/register' 30
            Write-PLog ('   w32tm /unregister: {0} | /register: {1}' -f (($o1 -replace '\s+', ' ').Trim()), (($o2 -replace '\s+', ' ').Trim()))
            try { Start-Service W32Time -ErrorAction Stop } catch { Write-PLog ('   W32Time: {0}' -f $_.Exception.Message) 'WARN' }
            $null = Invoke-NdCmd $w '/config /update' 20
            $o3 = Invoke-NdCmd $w '/resync /force' 60
            $ok = $o3 -match '(?i)erfolgreich|successfully'
            Write-WrResult ('Zeitdienst neu registriert. Abgleich: {0} Uhrzeit jetzt {1:HH:mm:ss}.' -f (($o3 -replace '\s+', ' ').Trim()), (Get-Date)) $(if ($ok) { 'OK' } else { 'WARN' })
        }
        'SecHealth' {
            foreach ($x in @(@('wscsvc', 'Automatic'), @('SecurityHealthService', 'Manual'))) {
                $s = Get-Service $x[0] -ErrorAction SilentlyContinue
                if ($s -and [string]$s.StartType -eq 'Disabled') { try { Set-Service $x[0] -StartupType $x[1] -ErrorAction Stop; Write-PLog ('   {0} war deaktiviert - Starttyp {1}' -f $x[0], $x[1]) 'OK' } catch { Write-PLog ('   {0}: geschützter Dienst ({1})' -f $x[0], $_.Exception.Message) 'WARN' } }
                try { Start-Service $x[0] -ErrorAction Stop } catch { }
            }
            $pk = @(Get-AppxPackage -AllUsers -Name 'Microsoft.SecHealthUI' -ErrorAction SilentlyContinue)
            foreach ($p in $pk) {
                try {
                    if (Get-Command Reset-AppxPackage -ErrorAction SilentlyContinue) { $p | Reset-AppxPackage -ErrorAction Stop; Write-PLog '   App "Windows-Sicherheit" zurückgesetzt' 'OK' }
                    else { Add-AppxPackage -DisableDevelopmentMode -Register (Join-Path $p.InstallLocation 'AppxManifest.xml') -ErrorAction Stop; Write-PLog '   App "Windows-Sicherheit" neu registriert' 'OK' }
                } catch { Write-PLog ('   Windows-Sicherheit: {0}' -f $_.Exception.Message) 'WARN' }
            }
            if (-not $pk.Count) { Write-PLog '   App "Windows-Sicherheit" (Microsoft.SecHealthUI) nicht gefunden - Abbild-Reparatur und SFC ausführen.' 'WARN' }
            $sig = ''
            try { $st = Get-MpComputerStatus -ErrorAction Stop; if ($st.AntivirusEnabled) { Update-MpSignature -ErrorAction Stop; $sig = 'Defender-Signaturen aktualisiert.' } else { $sig = 'Defender ist passiv (anderer Virenschutz aktiv) - Signaturen übersprungen.' } } catch { $sig = 'Defender-Status nicht lesbar: ' + $_.Exception.Message }
            Write-WrResult ('Sicherheitscenter geprüft. {0}' -f $sig) 'OK'
        }
        'HostsReset' { Invoke-RepairAction 'HostsReset' }
        'SvcCore' { Repair-WrServices $WrCoreSvcDefaults 'System' ([bool]$Script:JobOpts.SvcAll) }
        'TempClean' {
            $sum = [int64]0
            foreach ($p in @(Get-ProfilePaths)) { $sum += [int64](@(Remove-OldFiles -Path (Join-Path $p 'AppData\Local\Temp') -Days 1 -Recurse) | Where-Object { $_ -is [ValueType] } | Measure-Object -Sum).Sum }
            $sum += [int64](@(Remove-OldFiles -Path (Join-Path $env:SystemRoot 'Temp') -Days 1 -Recurse) | Where-Object { $_ -is [ValueType] } | Measure-Object -Sum).Sum
            Write-WrResult ('Temporäre Dateien gelöscht: {0}.' -f (Format-Bytes $sum)) 'OK'
        }
        'EventReport' {
            $e = Get-WrEventOverview 7
            foreach ($g in @($e.Groups | Select-Object -First 12)) { Write-PLog ('   {0,4}x {1}{2} (zuletzt {3}, IDs {4}){5}' -f $g.Anzahl, $g.Quelle, $(if ($g.Kritisch) { ' [' + $g.Kritisch + ' kritisch]' } else { '' }), $g.Letztes, $g.Ids, $(if ($g.Hinweis) { ' - ' + $g.Hinweis } else { '' })) }
            $f = Join-Path (Get-WrDir) ('Fehleruebersicht_{0}.csv' -f (Get-WrStamp))
            try { @($e.Groups) | Export-Csv -LiteralPath $f -Delimiter ';' -NoTypeInformation -Encoding UTF8 } catch { }
            Write-WrResult ('{0} Fehler und {1} kritische Ereignisse in 7 Tagen aus {2} Quellen. Liste: {3}' -f ($e.Total - $e.Critical), $e.Critical, @($e.Groups).Count, $f) 'OK'
        }
    }
}
function Invoke-WrLast([string]$Key) {
    switch ($Key) { 'RestorePoint' { New-PflegeRestorePoint } }
}
function Save-WrHistory($Sum) {
    $dir = Get-WrDir
    try { $Sum | ConvertTo-Json -Depth 5 | Set-Content -LiteralPath (Join-Path $dir 'last.json') -Encoding UTF8 } catch { }
    $res = if ($Sum.Abgebrochen) { 'abgebrochen' } elseif ($Sum.Warnungen) { 'mit Warnungen' } else { 'OK' }
    $row = [pscustomobject]@{ Zeit = $Sum.Zeit; Art = $Sum.Art; Titel = $Sum.Titel; Schritte = (@($Sum.Schritte) | ForEach-Object { $_.Key }) -join ','; Anzahl = @($Sum.Schritte).Count; Ergebnis = $res; Warnungen = $Sum.Warnungen; Neustart = $(if ($Sum.Neustart) { 'Ja' } else { 'Nein' }); Dauer = $Sum.Dauer; Log = $Sum.Log }
    try { $row | Export-Csv -LiteralPath (Join-Path $dir 'history.csv') -Append -Delimiter ';' -NoTypeInformation -Encoding UTF8 } catch { }
}
# Führt Katalog-Schritte der Reihe nach aus (Engine und Textmodus), schreibt last.json und history.csv
function Invoke-WrRun([string[]]$Keys, [string]$Title = '', [string]$Kind = 'Oberfläche', [bool]$ForceReboot = $false) {
    $start = Get-Date; $res = [System.Collections.Generic.List[object]]::new()
    $ents = @(foreach ($k in $Keys) { $e = $WrCatalog | Where-Object { $_.Key -eq $k } | Select-Object -First 1; if ($e) { $e } else { Write-PLog ('Unbekannter Reparaturschritt: ' + $k) 'WARN' } })
    $cnt = $ents.Count; $no = 0; $cancel = $false
    try {
        foreach ($e in $ents) {
            if (Test-PCancel) { $cancel = $true; Write-PLog 'Abgebrochen durch Benutzer' 'WARN'; break }
            $no++
            $Script:Detail = $e.Title; $Script:WrMsg = ''; $Script:LastLine = ''
            Set-PStatus ('Windows-Reparatur {0}/{1}: {2}' -f $no, $cnt, $e.Title) ([int](($no - 1) * 100 / [math]::Max(1, $cnt)))
            Write-PLog ('--- {0}/{1}: {2} ---' -f $no, $cnt, $e.Title)
            Write-PLog ('   Befehl: ' + $e.Cmd)
            if ($e.Mode -ne 'Job') { Write-PLog '   Das ist ein Knopf der Oberfläche - hier übersprungen.'; continue }
            $w0 = $Script:Warnings; $t0 = Get-Date; $err = ''
            try { & $e.Fn $e.Key | Out-Null } catch { $err = $_.Exception.Message; Write-PLog ('   Fehler: {0}' -f $err) 'FEHLER' }
            $state = if ($err) { 'Fehler' } elseif ($Script:Warnings -gt $w0) { 'Warnung' } else { 'OK' }
            $msg = if ($err) { $err } elseif ($Script:WrMsg) { $Script:WrMsg } else { $Script:LastLine }
            $res.Add([pscustomobject]@{ Key = $e.Key; Schritt = $e.Title; Ergebnis = $state; Dauer = ('{0:mm\:ss}' -f ((Get-Date) - $t0)); Meldung = [string]$msg })
        }
    } finally { Dismount-WrSource }
    if ($ForceReboot -and -not $cancel -and -not $Script:RebootNeeded) { $Script:RebootNeeded = $true; Write-PLog 'Dieses Profil endet mit einem Neustart, damit alle Netzwerk- und Update-Komponenten frisch starten.' }
    $sum = [pscustomobject]@{
        Zeit = $start.ToString('dd.MM.yyyy HH:mm'); Art = $Kind; Titel = $Title; Schritte = $res.ToArray()
        Ok = @($res | Where-Object { $_.Ergebnis -eq 'OK' }).Count; Warnungen = @($res | Where-Object { $_.Ergebnis -ne 'OK' }).Count
        Neustart = [bool]$Script:RebootNeeded; Dauer = ('{0:hh\:mm\:ss}' -f ((Get-Date) - $start)); Log = [string]$Script:LogFile; Abgebrochen = $cancel
    }
    Save-WrHistory $sum
    return $sum
}
# Engine-Teil "WinRepair"
function Invoke-WrRepairJob {
    $o = $Script:JobOpts
    $keys = @(@($o.Keys) | ForEach-Object { [string]$_ } | Where-Object { $_ })
    if (-not $keys.Count) { Write-PLog 'Windows-Reparatur: keine Schritte übergeben.' 'WARN'; return }
    if ($o.RestorePoint -and $keys -notcontains 'RestorePoint') { $keys = @('RestorePoint') + $keys }
    $title = [string]$o.Title
    Write-PLog ('Windows-Reparatur: {0} Schritt(e){1}{2}' -f $keys.Count, $(if ($title) { ' - ' + $title } else { '' }), $(if ([string]$o.Source) { ' - Reparaturquelle ' + [string]$o.Source } else { '' }))
    $sum = Invoke-WrRun $keys $title 'Oberfläche' ([bool]$o.ForceReboot)
    Set-PStatus 'Windows-Reparatur abgeschlossen' 100
    Write-PLog ('Windows-Reparatur fertig: {0} ohne Befund, {1} mit Warnung/Fehler, Dauer {2}.{3}' -f $sum.Ok, $sum.Warnungen, $sum.Dauer, $(if ($sum.Neustart) { ' Ein Neustart ist nötig, damit alle Reparaturen wirksam werden.' } else { '' })) 'OK'
}
# Engine-Teil "WinRepairIpu": Reparaturinstallation (In-place Upgrade) mit setup.exe aus einer Windows-ISO
function Invoke-WrInPlaceJob {
    $o = $Script:JobOpts; $iso = [string]$o.Source; $t0 = Get-Date; $state = 'Fehler'; $msg = ''
    try {
        if ($o.RestorePoint) { Set-PStatus 'Reparaturinstallation: Wiederherstellungspunkt' 1; New-PflegeRestorePoint }
        if (-not $iso -or -not (Test-Path -LiteralPath $iso)) { throw 'Keine Windows-ISO angegeben oder Datei nicht gefunden.' }
        Set-PStatus 'Reparaturinstallation: ISO einbinden und prüfen' 2
        $di = Get-DiskImage -ImagePath $iso -ErrorAction Stop
        if (-not $di.Attached) { $null = Mount-DiskImage -ImagePath $iso -StorageType ISO -ErrorAction Stop; Start-Sleep -Seconds 3 }
        $root = '{0}:\' -f (Get-DiskImage -ImagePath $iso | Get-Volume).DriveLetter
        $setup = Join-Path $root 'setup.exe'
        if (-not (Test-Path -LiteralPath $setup)) { throw ('setup.exe fehlt in der ISO ({0}).' -f $root) }
        $inst = Get-WrInstalledInfo
        Write-PLog ('Installiert: {0} {1}, Build {2}.{3}, {4}, {5}{6}' -f $inst.Caption, $inst.Display, $inst.Build, $inst.Ubr, $inst.Lang, $inst.Arch, $(if ($inst.Insider) { ', Insider ' + $inst.Branch } else { '' }))
        $il = Get-WrImageList $iso
        if (-not $il.Ok) { throw ('Abbilder der ISO nicht lesbar: ' + $il.Error) }
        $fit = $null
        foreach ($img in @($il.Images)) {
            $c = Test-WrIpuCompat $inst $img
            Write-PLog ('   Index {0}: {1} ({2}, {3}, {4}) - {5}' -f $img.Index, $img.Name, $img.EditionId, $img.Build, ((@($img.Langs)) -join '/'), $c.Text) $(if ($c.Level -eq 'bad') { 'INFO' } else { 'OK' })
            if (-not $fit -and $c.Level -ne 'bad' -and [string]$img.EditionId -eq [string]$inst.EditionId) { $fit = $img }
        }
        if (-not $fit) { $fit = @($il.Images | Where-Object { (Test-WrIpuCompat $inst $_).Level -ne 'bad' }) | Select-Object -First 1 }
        if (-not $fit) { throw 'Kein Abbild der ISO passt zu diesem Windows (Sprache, Architektur oder Build) - Apps und Dateien könnten nicht behalten werden. Passende ISO besorgen (Seite Windows und Office; bei Insider-Builds eine Insider-ISO).' }
        $free = Get-FreeBytes
        if ($free -lt 20GB) { Write-PLog ('Nur {0} frei auf {1} - Setup braucht etwa 20 GB. Vorher aufräumen, sonst bricht Setup ab.' -f (Format-Bytes $free), $env:SystemDrive) 'WARN' }
        $logs = Join-Path (Get-WrDir) ('Setup-Protokolle_{0}' -f (Get-WrStamp)); New-Item $logs -ItemType Directory -Force | Out-Null
        $sa = @('/auto', 'upgrade', '/eula', 'accept', '/dynamicupdate', $(if ($o.DynUpdate -eq $false) { 'disable' } else { 'enable' }), '/compat', 'ignorewarning', '/showoobe', 'none', '/quiet', '/copylogs', ('"{0}"' -f $logs))
        if (-not $o.AutoReboot) { $sa += '/noreboot' }
        Write-PLog ('Starte Windows-Setup: {0} {1}' -f $setup, ($sa -join ' '))
        Write-PLog 'Setup prüft zuerst die Kompatibilität, lädt ggf. Updates und bereitet alles vor - das dauert 30 bis 90 Minuten. Windows wird erst beim Neustart ersetzt; Apps, Dateien und Einstellungen bleiben.'
        $p = Start-Process -FilePath $setup -ArgumentList ($sa -join ' ') -PassThru -WindowStyle Hidden
        $null = $p.Handle   # Handle sofort holen, sonst liefert ExitCode später $null
        $sw = [Diagnostics.Stopwatch]::StartNew(); $lastPct = -1; $cancel = $false
        while ($true) {
            $alive = (-not $p.HasExited) -or @(Get-Process -Name 'SetupHost', 'SetupPrep' -ErrorAction SilentlyContinue).Count
            if (-not $alive) { break }
            if (Test-PCancel) {
                $cancel = $true; Write-PLog 'Abbruch: Setup wird beendet - bis zum Neustart wurde an Windows nichts verändert.' 'WARN'
                Get-Process -Name 'SetupHost', 'SetupPrep' -ErrorAction SilentlyContinue | Stop-Process -Force -ErrorAction SilentlyContinue
                Get-Process -Name 'setup' -ErrorAction SilentlyContinue | Where-Object { try { $_.Path -like ($root + '*') } catch { $false } } | Stop-Process -Force -ErrorAction SilentlyContinue
                break
            }
            if ($sw.Elapsed.TotalMinutes -gt 300) { Write-PLog 'Setup läuft seit über 5 Stunden - PC-Tools wartet nicht länger (Setup läuft weiter).' 'WARN'; break }
            $pct = (Get-ItemProperty 'HKLM:\SYSTEM\Setup\MoSetup\Volatile' -Name SetupProgress -ErrorAction SilentlyContinue).SetupProgress
            if ($null -ne $pct -and [int]$pct -ne $lastPct) {
                $lastPct = [int]$pct; $Script:Detail = ('Windows-Setup: {0} %' -f $lastPct)
                Set-PStatus ('Reparaturinstallation läuft ({0} %)' -f $lastPct) ([int](5 + $lastPct * 0.9))
                if ($lastPct % 10 -eq 0) { Write-PLog ('   Setup: {0} %' -f $lastPct) }
            } else { $Script:Detail = ('Windows-Setup arbeitet seit {0} Min.{1}' -f [int]$sw.Elapsed.TotalMinutes, $(if ($lastPct -ge 0) { ' (' + $lastPct + ' %)' } else { '' })); Update-PHeartbeat }
            Start-Sleep -Seconds 3
        }
        $code = -1; if (-not $cancel) { try { [void]$p.WaitForExit(5000); if ($p.HasExited -and $null -ne $p.ExitCode) { $code = [int64]$p.ExitCode } } catch { } }
        $msg = Get-WrSetupCodeText $code
        $u = [uint32]($code -band 0xFFFFFFFFL)
        if (-not $cancel -and ($u -eq 0 -or $u -eq 0xBC2)) { $state = 'OK'; $Script:RebootNeeded = $true; Write-PLog ('Windows-Setup: {0}' -f $msg) 'OK' }
        else {
            Write-PLog ('Windows-Setup: {0}' -f $msg) 'WARN'
            $pe = Join-Path $env:SystemDrive '$WINDOWS.~BT\Sources\Panther\setuperr.log'
            if (Test-Path -LiteralPath $pe) { foreach ($x in @(Get-Content -LiteralPath $pe -Tail 12 -ErrorAction SilentlyContinue)) { Write-PLog ('   ' + $x) } }
            Write-PLog ('Setup-Protokolle: {0}' -f $logs)
            try { Dismount-DiskImage -ImagePath $iso -ErrorAction SilentlyContinue | Out-Null } catch { }
            if ($cancel) { $state = 'Abgebrochen' }
        }
    } catch { $msg = $_.Exception.Message; Write-PLog ('Reparaturinstallation: {0}' -f $msg) 'FEHLER' }
    $row = [pscustomobject]@{ Key = 'InPlace'; Schritt = 'Reparaturinstallation (In-place Upgrade)'; Ergebnis = $(if ($state -eq 'OK') { 'OK' } elseif ($state -eq 'Abgebrochen') { 'Warnung' } else { 'Fehler' }); Dauer = ('{0:hh\:mm\:ss}' -f ((Get-Date) - $t0)); Meldung = $msg }
    Save-WrHistory ([pscustomobject]@{ Zeit = $t0.ToString('dd.MM.yyyy HH:mm'); Art = 'Reparaturinstallation'; Titel = $iso; Schritte = @($row); Ok = $(if ($state -eq 'OK') { 1 } else { 0 }); Warnungen = $(if ($state -eq 'OK') { 0 } else { 1 }); Neustart = [bool]$Script:RebootNeeded; Dauer = $row.Dauer; Log = [string]$Script:LogFile; Abgebrochen = ($state -eq 'Abgebrochen') })
    if ($state -eq 'OK') { Write-PLog $(if ($o.AutoReboot) { 'Setup startet den PC gleich selbst neu - danach läuft die Installation mit mehreren Neustarts weiter (nicht ausschalten!).' } else { 'Jetzt neu starten: Windows installiert sich dann über sich selbst (mehrere Neustarts, 20-60 Minuten, nicht ausschalten!).' }) }
}
function Start-WrUninstall([string]$Cmd) {
    if (-not $Cmd) { Start-Process 'ms-settings:appsfeatures'; return }
    Start-Process -FilePath (Join-Path $env:windir 'System32\cmd.exe') -ArgumentList ('/c "{0}"' -f $Cmd)
}

# ---- Komplett-Reparatur ohne Rückfragen (PCPflege.ps1 -FullRepair, im Ordner: "Komplett-Reparatur.cmd") - für PCs, auf denen Dienste/Setup nicht mehr starten (z.B. Surface)
#      Läuft alle sicheren und Neustart-Reparaturen des Katalogs in richtiger Reihenfolge, setzt ALLE Dienste auf Windows-Standard,
#      schreibt ein vollständiges Transcript und sammelt am Ende automatisch ein Fehlerdaten-Paket (ZIP), falls doch etwas offen bleibt.
function Invoke-WrFullRepair {
    if (-not (Get-Command Write-PLog -ErrorAction SilentlyContinue)) { . ([scriptblock]::Create($EngineText)) }
    if (-not $Script:Cfg) { try { $Script:Cfg = Read-PflegeConfig } catch { } }
    try { $Host.UI.RawUI.WindowTitle = 'PC-Tools Komplett-Reparatur' } catch { }
    $dd = if ($Script:DataDir) { $Script:DataDir } else { $DataDir }
    $logs = Join-Path $dd 'Logs'; New-Item $logs -ItemType Directory -Force -ErrorAction SilentlyContinue | Out-Null
    $Script:LogFile = Join-Path $logs ('Komplett-Reparatur_{0:yyyyMMdd_HHmmss}.log' -f (Get-Date))
    $trans = Join-Path $logs ('Komplett-Reparatur-Mitschnitt_{0:yyyyMMdd_HHmmss}.txt' -f (Get-Date))
    $transOn = $false
    try { Start-Transcript -LiteralPath $trans -Force -ErrorAction Stop | Out-Null; $transOn = $true } catch { }
    Clear-Host
    Write-Host ''; Write-Host '  PC-TOOLS  KOMPLETT-REPARATUR' -ForegroundColor White -BackgroundColor DarkRed
    Write-Host ('  {0} - repariert Windows tiefgreifend und ohne Rückfragen.' -f $env:COMPUTERNAME) -ForegroundColor Gray
    Write-Host '  Enthalten: Wiederherstellungspunkt, hängendes Setup & Update-Blocker, Dienste auf Windows-Standard,'
    Write-Host '  Abbild (DISM) & Systemdateien (SFC), Windows Update komplett, Netzwerk, WMI, Store/Apps, Datenträger.'
    Write-Host '  Alte, angreifbare Treiber werden entfernt. Am Ende ein Fehlerdaten-Paket und ein Neustart. Dauer: 30-90 Minuten.' -ForegroundColor Gray
    Write-Host ''
    Write-Host '  Start in 8 Sekunden - zum Abbrechen dieses Fenster schliessen (Strg+C).' -ForegroundColor Yellow
    for ($s = 8; $s -ge 1; $s--) { Write-Host ('   ... {0} ' -f $s) -NoNewline -ForegroundColor DarkGray; Start-Sleep -Seconds 1 }
    Write-Host ''
    $jobKeys = @($WrCatalog | Where-Object { $_.Mode -eq 'Job' -and $_.Risk -ne 'Deep' -and $_.Key -notin 'ChkBoot', 'BootLogOn', 'BootLogOff', 'SfcVerify', 'RestorePoint', 'WuBlockAnalyze' } | Sort-Object { [int]$_.Ord } | ForEach-Object { $_.Key })
    $keys = @('WuStuckSetup', 'WuBlockAnalyze') + $jobKeys + @('WuVulnDriver')
    $Script:JobOpts = [pscustomobject]@{ Keys = $keys; Source = ''; Index = 0; RestorePoint = $true; SvcAll = $true; Title = 'Komplett-Reparatur' }
    $Script:RebootNeeded = $false; $Script:Warnings = 0
    $k2 = @('RestorePoint') + @($keys)
    $sum = Invoke-WrRun $k2 'Komplett-Reparatur' 'Komplett-Reparatur' $true
    Write-Host ''; Write-Host '  ERGEBNIS' -ForegroundColor White -BackgroundColor DarkRed; Write-Host ''
    foreach ($r in @($sum.Schritte)) { Write-Host ('  {0,-8} {1}' -f $r.Ergebnis, $r.Schritt) -ForegroundColor $(switch ($r.Ergebnis) { 'OK' { 'Green' } 'Warnung' { 'Yellow' } default { 'Red' } }); if ($r.Meldung) { Write-Host ('           ' + $r.Meldung) -ForegroundColor DarkGray } }
    Write-Host ''; Write-Host ('  {0} ohne Befund, {1} mit Warnung/Fehler. Protokoll: {2}' -f $sum.Ok, $sum.Warnungen, $Script:LogFile) -ForegroundColor Cyan
    # Fehlerdaten-Paket sammeln, damit bei verbleibenden Problemen alles zur Auswertung bereitliegt
    Write-Host ''; Write-Host '  Sammle Fehlerdaten (Super-Log) ...' -ForegroundColor Gray
    $zip = ''
    try {
        if (-not $Script:Cfg) { $Script:Cfg = Read-PflegeConfig }
        try { $Script:Cfg.Diag.Target = $logs } catch { }
        Invoke-DiagCollect
        $lf = Join-Path $dd 'diag_last.txt'; if (Test-Path -LiteralPath $lf) { $zip = (Get-Content -LiteralPath $lf -Raw -ErrorAction SilentlyContinue).Trim() }
    } catch { Write-Host ('  Fehlerdaten-Paket: ' + $_.Exception.Message) -ForegroundColor Yellow }
    if ($zip) { Write-Host ('  Fehlerdaten-Paket: {0}' -f $zip) -ForegroundColor Cyan }
    if ($transOn) { try { Stop-Transcript | Out-Null } catch { } }
    Write-Host ''
    Write-Host '  Der PC startet in 60 Sekunden neu, damit alle Reparaturen wirksam werden.' -ForegroundColor Yellow
    Write-Host '  Sofort neu starten: Taste N. Neustart verschieben: Taste V.' -ForegroundColor Yellow
    $doReboot = $true
    for ($s = 60; $s -ge 1; $s--) {
        try { if ([Console]::KeyAvailable) { $kk = [Console]::ReadKey($true); if ($kk.Key -eq 'V') { $doReboot = $false; break }; if ($kk.Key -eq 'N') { break } } } catch { }
        Start-Sleep -Seconds 1
        if ($s % 10 -eq 0) { Write-Host ('   Neustart in {0}s ...' -f $s) -ForegroundColor DarkGray }
    }
    if ($doReboot) { Write-Host '  Neustart ...' -ForegroundColor Green; try { Restart-Computer -Force } catch { } }
    else { Write-Host '  Neustart verschoben - bitte später manuell neu starten, damit alle Reparaturen abgeschlossen werden.' -ForegroundColor Yellow; Read-Host '  Enter zum Beenden' }
}

# ---- Code-Signierung des eigenen Skripts mit dem EIGENEN Zertifikat (PCPflege.ps1 -Sign). Ändert NICHTS am Zertifikatsvertrauen des PCs.
#      Zertifikat wählen: -SignOpts "pfx=C:\pfad\cert.pfx;pw=geheim"  ODER automatisch das erste Codesignatur-Zertifikat aus dem eigenen Speicher.
function Invoke-PflegeSign([string]$Opts = '') {
    try { $Host.UI.RawUI.WindowTitle = 'PC-Tools Signieren' } catch { }
    Write-Host ''; Write-Host '  PC-TOOLS  SKRIPT SIGNIEREN' -ForegroundColor White -BackgroundColor DarkBlue; Write-Host ''
    $pfx = ''; $pw = ''
    foreach ($kv in @($Opts -split ';')) { if ($kv -match '^\s*pfx\s*=\s*(.+)$') { $pfx = $Matches[1].Trim().Trim('"') }; if ($kv -match '^\s*pw\s*=\s*(.+)$') { $pw = $Matches[1].Trim() } }
    $cert = $null
    try {
        if ($pfx) {
            if (-not (Test-Path -LiteralPath $pfx)) { Write-Host ('  PFX nicht gefunden: ' + $pfx) -ForegroundColor Red; Read-Host '  Enter'; return }
            $sec = if ($pw) { ConvertTo-SecureString $pw -AsPlainText -Force } else { Read-Host '  PFX-Kennwort' -AsSecureString }
            $cert = Get-PfxCertificate -FilePath $pfx -Password $sec -ErrorAction Stop
        } else {
            $cert = @(Get-ChildItem Cert:\CurrentUser\My, Cert:\LocalMachine\My -CodeSigningCert -ErrorAction SilentlyContinue | Where-Object { $_.NotAfter -gt (Get-Date) } | Sort-Object NotAfter -Descending | Select-Object -First 1)
            if ($cert.Count) { $cert = $cert[0] }
        }
    } catch { Write-Host ('  Zertifikat konnte nicht geladen werden: ' + $_.Exception.Message) -ForegroundColor Red; Read-Host '  Enter'; return }
    if (-not $cert) { Write-Host '  Kein Codesignatur-Zertifikat gefunden. Entweder mit -SignOpts "pfx=...;pw=..." angeben oder vorher eines im eigenen Speicher anlegen.' -ForegroundColor Yellow; Write-Host '  Ein eigenes Testzertifikat erstellst du mit: New-SelfSignedCertificate -Type CodeSigningCert -Subject "CN=PC-Tools (eigene Signatur)" -CertStoreLocation Cert:\CurrentUser\My' -ForegroundColor Gray; Read-Host '  Enter'; return }
    Write-Host ('  Zertifikat: {0}  (gültig bis {1:dd.MM.yyyy})' -f $cert.Subject, $cert.NotAfter) -ForegroundColor Gray
    $tsa = 'http://timestamp.digicert.com'
    $ok = 0; $fail = 0
    foreach ($f in @($PSCommandPath)) {
        if (-not (Test-Path -LiteralPath $f)) { continue }
        try {
            $r = Set-AuthenticodeSignature -FilePath $f -Certificate $cert -HashAlgorithm SHA256 -TimestampServer $tsa -ErrorAction Stop
            if ([string]$r.Status -eq 'Valid') { $ok++; Write-Host ('  signiert: {0}' -f $f) -ForegroundColor Green } else { $fail++; Write-Host ('  {0}: {1} - {2}' -f $f, $r.Status, $r.StatusMessage) -ForegroundColor Yellow }
        } catch { $fail++; Write-Host ('  {0}: {1}' -f $f, $_.Exception.Message) -ForegroundColor Red }
    }
    Write-Host ''
    Write-Host ('  Fertig: {0} signiert, {1} fehlgeschlagen.' -f $ok, $fail) -ForegroundColor $(if ($fail) { 'Yellow' } else { 'Green' })
    Write-Host '  Hinweis: Das Zertifikatsvertrauen des PCs wird dabei absichtlich NICHT verändert.' -ForegroundColor DarkGray
    Write-Host '  Damit signierte Skripte ohne Warnung laufen, muss das Zertifikat EINMALIG und bewusst in "Vertrauenswürdige Herausgeber" -' -ForegroundColor DarkGray
    Write-Host '  im Firmennetz am besten per Gruppenrichtlinie/Intune. PC-Tools selbst startet ohnehin mit -ExecutionPolicy Bypass.' -ForegroundColor DarkGray
    Read-Host '  Enter zum Beenden'
}

# ---- Windows-Reparatur im Textfenster (PCPflege.ps1 -WinRepair, vom Stick: Windows-Reparatur.cmd) - wenn die Oberfläche nicht startet
function Invoke-WrConsole {
    if (-not (Get-Command Write-PLog -ErrorAction SilentlyContinue)) { . ([scriptblock]::Create($EngineText)) }
    try { $Host.UI.RawUI.WindowTitle = 'PC-Tools Windows-Reparatur' } catch { }
    $dd = if ($Script:DataDir) { $Script:DataDir } else { $DataDir }
    New-Item (Join-Path $dd 'Logs') -ItemType Directory -Force -ErrorAction SilentlyContinue | Out-Null
    $Script:LogFile = Join-Path (Join-Path $dd 'Logs') ('Windows-Reparatur_{0:yyyyMMdd_HHmmss}.log' -f (Get-Date))
    $Script:JobOpts = [pscustomobject]@{ Keys = @(); Source = ''; Index = 0; RestorePoint = $true; SvcAll = $false; Title = '' }
    $rcol = @{ Safe = 'Green'; Reboot = 'Yellow'; Deep = 'Red' }; $rtxt = @{ Safe = 'sicher'; Reboot = 'Neustart'; Deep = 'TIEFGREIFEND' }
    $lcol = @{ ok = 'Green'; warn = 'Yellow'; bad = 'Red'; info = 'Cyan' }
    $pause = { Read-Host '  Weiter mit Enter' | Out-Null }
    $yes = { param($q) ((Read-Host ('  ' + $q + ' (j/N)')) -match '^[jJyY]') }
    $head = { param($t) Write-Host ''; Write-Host ('  ' + $t) -ForegroundColor White -BackgroundColor DarkRed; Write-Host '' }
    $runKeys = {
        param([string[]]$keys, [string]$title, [bool]$force = $false)
        $ents = @(foreach ($k in $keys) { $WrCatalog | Where-Object { $_.Key -eq $k -and $_.Mode -eq 'Job' } | Select-Object -First 1 })
        if (-not $ents.Count) { Write-Host '  Nichts auszuführen.' -ForegroundColor Yellow; & $pause; return }
        & $head ('AUSFÜHREN: ' + $title)
        foreach ($e in $ents) { Write-Host ('   - {0,-50} [{1}]' -f $e.Title, $rtxt[$e.Risk]) -ForegroundColor $rcol[$e.Risk] }
        $deep = @($ents | Where-Object { $_.Risk -eq 'Deep' })
        if ($deep.Count) { Write-Host ''; Write-Host '  ACHTUNG - tiefgreifend:' -ForegroundColor Red; foreach ($e in $deep) { Write-Host ('   {0}: {1}' -f $e.Title, $e.Desc) -ForegroundColor Red } }
        Write-Host ''
        Write-Host ('  Wiederherstellungspunkt vorher: {0}   Reparaturquelle: {1}' -f $(if ($Script:JobOpts.RestorePoint) { 'ja' } else { 'nein' }), $(if ($Script:JobOpts.Source) { $Script:JobOpts.Source } else { 'Windows Update' })) -ForegroundColor Gray
        if (-not (& $yes 'Jetzt ausführen?')) { return }
        $Script:RebootNeeded = $false; $Script:Warnings = 0
        $k2 = @($ents | ForEach-Object { $_.Key }); if ($Script:JobOpts.RestorePoint -and $k2 -notcontains 'RestorePoint') { $k2 = @('RestorePoint') + $k2 }
        $sum = Invoke-WrRun $k2 $title 'Textmodus' $force
        & $head 'ERGEBNIS'
        foreach ($r in @($sum.Schritte)) { Write-Host ('  {0,-8} {1}' -f $r.Ergebnis, $r.Schritt) -ForegroundColor $(switch ($r.Ergebnis) { 'OK' { 'Green' } 'Warnung' { 'Yellow' } default { 'Red' } }); if ($r.Meldung) { Write-Host ('           ' + $r.Meldung) -ForegroundColor DarkGray } }
        Write-Host ''; Write-Host ('  Protokoll: {0}' -f $Script:LogFile) -ForegroundColor Cyan
        if ($sum.Neustart -or (Test-PendingReboot)) { if (& $yes 'Ein Neustart ist nötig. Jetzt neu starten?') { Restart-Computer -Force } }
        & $pause
    }
    $st = $null
    while ($true) {
        Clear-Host
        Write-Host ''; Write-Host '  PC-TOOLS  WINDOWS-REPARATUR' -ForegroundColor White -BackgroundColor DarkRed; Write-Host ('  {0} - Textmodus, falls die Oberfläche nicht startet. Alles wird protokolliert.' -f $env:COMPUTERNAME) -ForegroundColor Gray
        if (-not $st) { Write-Host '  Prüfe den Zustand (ca. 10-30 Sekunden) ...' -ForegroundColor Gray; try { $st = Get-WrStatus $dd } catch { Write-Host ('  Zustand: ' + $_.Exception.Message) -ForegroundColor Red } }
        if ($st) {
            Write-Host ''
            foreach ($t in @(@('Windows', 'Win'), @('Neustart ausstehend', 'Reboot'), @('Komponentenspeicher', 'Store'), @('Systemdateien (SFC)', 'Sfc'), @('Wiederherstellung', 'Re'), @('Frei auf C:', 'Disk'), @('Wiederherstellungspunkt', 'Rp'), @('Startmodus', 'Boot'))) {
                $val = [string]$st.($t[1] + 'Val'); $sub = [string]$st.($t[1] + 'Sub'); $lv = [string]$st.($t[1] + 'Lvl'); if (-not $lcol.ContainsKey($lv)) { $lv = 'info' }
                Write-Host ('  {0,-24} ' -f $t[0]) -NoNewline -ForegroundColor Gray; Write-Host ('{0,-18} ' -f $val) -NoNewline -ForegroundColor $lcol[$lv]; Write-Host $(if ($sub.Length -gt 90) { $sub.Substring(0, 90) + '...' } else { $sub }) -ForegroundColor DarkGray
            }
        }
        Write-Host ''; Write-Host '  PROFILE' -ForegroundColor White
        $i = 0; foreach ($p in $WrProfiles) { $i++; Write-Host ('  [{0}] {1}' -f $i, $p.Title) -ForegroundColor $(if ($p.Key -eq 'Net') { 'Cyan' } else { 'Gray' }) }
        Write-Host ''
        Write-Host '  [K] Einzelne Reparaturen aus dem Katalog wählen' -ForegroundColor White
        Write-Host ('  [Q] Reparaturquelle (Windows-ISO/WIM) festlegen - aktuell: {0}' -f $(if ($Script:JobOpts.Source) { '{0} (Index {1})' -f $Script:JobOpts.Source, $(if ($Script:JobOpts.Index) { $Script:JobOpts.Index } else { 'automatisch' }) } else { 'Windows Update' }))
        Write-Host ('  [P] Wiederherstellungspunkt vor Reparaturen: {0}' -f $(if ($Script:JobOpts.RestorePoint) { 'AN' } else { 'aus' }))
        Write-Host '  [D] Dienste-Vergleich (Netzwerk und Kerndienste)   [F] Netzwerkfilter, IPv4 und Virenschutz'
        Write-Host '  [C] SFC-Ergebnis aus der CBS.log                   [E] Fehler der letzten 7 Tage'
        Write-Host '  [W] Neustart in die Wiederherstellung (WinRE)      [A] Abgesicherter Modus an/aus'
        Write-Host '  [U] Hängende Update-Aktionen (Anleitung)           [S] Zustand neu prüfen'
        Write-Host '  [G] PC-Tools-Oberfläche starten   [R] Neustart jetzt   [0] Beenden'
        $c = (Read-Host '  Auswahl').Trim()
        try {
            if ($c -match '^\d+$' -and [int]$c -ge 1 -and [int]$c -le $WrProfiles.Count) {
                $p = $WrProfiles[[int]$c - 1]
                Write-Host ''; Write-Host ('  ' + $p.Desc) -ForegroundColor Gray
                $keepRp = $Script:JobOpts.RestorePoint; if (-not $p.Rp) { $Script:JobOpts.RestorePoint = $false }
                & $runKeys @($p.Keys) $p.Title ([bool]$p.Reboot)
                $Script:JobOpts.RestorePoint = $keepRp; $st = $null; continue
            }
            switch -Regex ($c) {
                '^0$' { return }
                '^[kK]$' {
                    & $head 'KATALOG'
                    $j = 0; foreach ($cat in $WrCategories) { $j++; Write-Host ('  [{0}] {1}' -f $j, $cat.Title) }
                    $cc = Read-Host '  Bereich (Nummer, Enter = zurück)'
                    if ($cc -notmatch '^\d+$' -or [int]$cc -lt 1 -or [int]$cc -gt $WrCategories.Count) { break }
                    $cat = $WrCategories[[int]$cc - 1]
                    $list = @($WrCatalog | Where-Object { $_.Cat -eq $cat.Key })
                    & $head $cat.Title.ToUpper()
                    $j = 0
                    foreach ($e in $list) { $j++; Write-Host ('  [{0,2}] {1,-52} [{2}]{3}' -f $j, $e.Title, $rtxt[$e.Risk], $(if ($e.Mode -ne 'Job') { ' (Knopf)' } else { '' })) -ForegroundColor $rcol[$e.Risk]; Write-Host ('       ' + $e.Desc) -ForegroundColor DarkGray; Write-Host ('       > ' + $e.Cmd) -ForegroundColor DarkCyan }
                    $sel = Read-Host '  Nummern (z.B. 1,3,5), a = alle ausführbaren, Enter = zurück'
                    if (-not $sel) { break }
                    $pick = if ($sel -match '^[aA]$') { @($list | Where-Object { $_.Mode -eq 'Job' }) } else { @($sel -split '[,; ]+' | Where-Object { $_ -match '^\d+$' -and [int]$_ -ge 1 -and [int]$_ -le $list.Count } | ForEach-Object { $list[[int]$_ - 1] }) }
                    $ui1 = @($pick | Where-Object { $_.Mode -ne 'Job' })
                    foreach ($e in $ui1) {
                        if ($e.Key -in 'InPlace', 'NetHyperV', 'MediaPage') { Write-Host ('  "{0}" gibt es nur in der Oberfläche (bzw. Netzwerk-Notfall.cmd für Hyper-V).' -f $e.Title) -ForegroundColor Yellow; continue }
                        if ($e.Key -eq 'SafeMode') { $m = Read-Host '  [1] minimal  [2] mit Netzwerk'; if (& $yes 'Abgesicherten Modus für den nächsten Start setzen?') { Write-Host ('  ' + (Invoke-WrDirect 'SafeMode' $(if ($m -eq '2') { 'network' } else { 'minimal' }))) -ForegroundColor Green }; continue }
                        if ($e.Risk -ne 'Safe' -and -not (& $yes ('{0} - wirklich?' -f $e.Title))) { continue }
                        Write-Host ('  ' + (Invoke-WrDirect $e.Key)) -ForegroundColor Green
                    }
                    $jobs = @($pick | Where-Object { $_.Mode -eq 'Job' } | Sort-Object { [int]$_.Ord })
                    if ($jobs.Count) { & $runKeys @($jobs | ForEach-Object { $_.Key }) ('Auswahl: ' + $cat.Title) } else { & $pause }
                    $st = $null
                }
                '^[qQ]$' {
                    $f = (Read-Host '  Pfad zur Windows-ISO, install.wim oder install.esd (Enter = entfernen)').Trim().Trim('"')
                    if (-not $f) { $Script:JobOpts.Source = ''; $Script:JobOpts.Index = 0; break }
                    Write-Host '  Lese Abbilder ...' -ForegroundColor Gray
                    $il = Get-WrImageList $f
                    if (-not $il.Ok) { Write-Host ('  ' + $il.Error) -ForegroundColor Red; & $pause; break }
                    $inst = Get-WrInstalledInfo
                    Write-Host ('  Installiert: {0}, Build {1}.{2}, {3}, {4}' -f $inst.EditionId, $inst.Build, $inst.Ubr, $inst.Lang, $inst.Arch) -ForegroundColor Gray
                    foreach ($img in @($il.Images)) { $cp = Test-WrIpuCompat $inst $img; Write-Host ('  [{0}] {1} - {2}, {3}, {4}: {5}' -f $img.Index, $img.Name, $img.EditionId, $img.Build, (@($img.Langs) -join '/'), $cp.Text) -ForegroundColor $(switch ($cp.Level) { 'ok' { 'Green' } 'warn' { 'Yellow' } default { 'Red' } }) }
                    $ix = Read-Host '  Index (Enter = automatisch passend zur Edition)'
                    $Script:JobOpts.Source = $f; $Script:JobOpts.Index = $(if ($ix -match '^\d+$') { [int]$ix } else { 0 })
                }
                '^[pP]$' { $Script:JobOpts.RestorePoint = -not $Script:JobOpts.RestorePoint }
                '^[dD]$' {
                    & $head 'DIENSTE-VERGLEICH'
                    $rows = @(Get-WrSvcDiff $WrNetSvcDefaults 'Netzwerk') + @(Get-WrSvcDiff $WrCoreSvcDefaults 'System')
                    if (-not $rows.Count) { Write-Host '  Alle Dienste entsprechen der Windows-Vorgabe.' -ForegroundColor Green; & $pause; break }
                    foreach ($r in $rows) { Write-Host ('  [{0,-7}] {1,-22} {2,-15} ist: {3}  ->  Vorgabe: {4}' -f $r.Stufe, $r.Dienst, $r.Feld, $r.Ist, $r.Soll) -ForegroundColor $(if ($r.Stufe -eq 'Problem') { 'Red' } else { 'Yellow' }); if ($r.Hinweis) { Write-Host ('            ' + $r.Hinweis) -ForegroundColor DarkGray } }
                    if (@($rows | Where-Object { $_.Fix }).Count) {
                        $Script:JobOpts.SvcAll = & $yes 'Auch die Hinweise (nicht nur Probleme) auf Standard setzen?'
                        $ks = @(); if (@($rows | Where-Object { $_.Gruppe -eq 'Netzwerk' }).Count) { $ks += 'NetSvcDefaults' }; if (@($rows | Where-Object { $_.Gruppe -eq 'System' }).Count) { $ks += 'SvcCore' }
                        & $runKeys $ks 'Dienste auf Windows-Standard'
                        $Script:JobOpts.SvcAll = $false
                    } else { & $pause }
                }
                '^[fF]$' {
                    & $head 'NETZWERKFILTER, IPv4 UND VIRENSCHUTZ'
                    $n = Get-WrNetScan
                    foreach ($r in @($n.Filters)) { Write-Host ('  {0,-14} {1,-5} {2,-45} {3}' -f $r.Adapter, $r.Aktiv, ('{0} ({1})' -f $r.Komponente, $r.Id), $r.Hersteller) -ForegroundColor $(switch ($r.Level) { 'bad' { 'Red' } 'warn' { 'Yellow' } default { 'Gray' } }); if ($r.Third) { Write-Host ('                 ' + $r.Einschaetzung) -ForegroundColor DarkGray } }
                    Write-Host ''
                    foreach ($r in @($n.Ip)) { Write-Host ('  {0,-14} {1,-12} DHCP {2,-4} IPv4 {3,-16} {4}' -f $r.Adapter, $r.Status, $r.Dhcp, $(if ($r.Ip) { $r.Ip } else { '-' }), $r.Hinweis) -ForegroundColor $(switch ($r.Level) { 'bad' { 'Red' } 'warn' { 'Yellow' } default { 'Green' } }) }
                    Write-Host ''; Write-Host ('  IPv6 DisabledComponents: ' + $n.DcText) -ForegroundColor Gray; Write-Host ('  DHCP-Broadcast-Wechsel: {0}' -f $(if ([string]$n.Toggle -eq '1') { 'an' } else { 'aus (Standard)' })) -ForegroundColor Gray
                    $un = @($n.Uninstall)
                    if ($un.Count) { Write-Host ''; Write-Host '  Installierte Virenschutz-/VPN-Programme:' -ForegroundColor Yellow; $j = 0; foreach ($u in $un) { $j++; Write-Host ('  [{0}] {1} {2} ({3})' -f $j, $u.Name, $u.Version, $u.Publisher) -ForegroundColor Yellow } }
                    Write-Host ''
                    $a = Read-Host '  [L] fremde Filter lösen   [1..n] Programm deinstallieren   Enter = zurück'
                    if ($a -match '^[lL]$') { & $runKeys @('NetFilterOff') 'Fremde Netzwerkfilter lösen' }
                    elseif ($a -match '^\d+$' -and [int]$a -ge 1 -and [int]$a -le $un.Count) { $u = $un[[int]$a - 1]; if (& $yes ('"{0}" deinstallieren (Deinstallationsprogramm des Herstellers)?' -f $u.Name)) { Start-WrUninstall $u.Uninstall; Write-Host '  Deinstallation gestartet - danach neu starten. Bei Panda hilft notfalls der "Panda Generic Uninstaller" des Herstellers.' -ForegroundColor Green; & $pause } }
                }
                '^[cC]$' {
                    & $head 'SFC-ERGEBNIS (CBS.log)'
                    $cb = Get-WrCbsSummary
                    if (-not $cb.Found) { Write-Host '  Kein SFC-Lauf in der aktuellen CBS.log.' -ForegroundColor Yellow }
                    else {
                        Write-Host ('  Lauf {0:dd.MM.yyyy HH:mm} - {1:HH:mm}, {2}, {3} Komponenten: {4}' -f $cb.Start, $cb.End, $cb.Mode, $cb.Verified, $cb.Verdict) -ForegroundColor $(if (@($cb.Failed).Count) { 'Red' } else { 'Green' })
                        foreach ($x in @($cb.Repaired)) { Write-Host ('   repariert:          ' + $x) -ForegroundColor Green }
                        foreach ($x in @($cb.Failed)) { Write-Host ('   NICHT reparierbar:  ' + $x) -ForegroundColor Red }
                        foreach ($x in @($cb.Corrupt)) { Write-Host ('   beschädigt:         ' + $x) -ForegroundColor Yellow }
                    }
                    & $pause
                }
                '^[eE]$' {
                    & $head 'FEHLER DER LETZTEN 7 TAGE (Systemprotokoll)'
                    $ev = Get-WrEventOverview 7
                    Write-Host ('  {0} Ereignisse, davon {1} kritisch' -f $ev.Total, $ev.Critical) -ForegroundColor Gray
                    foreach ($g in @($ev.Groups | Select-Object -First 15)) { Write-Host ('  {0,4}x {1,-40} zuletzt {2}  IDs {3}' -f $g.Anzahl, $g.Quelle, $g.Letztes, $g.Ids) -ForegroundColor $(if ($g.Kritisch) { 'Red' } else { 'Yellow' }); if ($g.Hinweis) { Write-Host ('        ' + $g.Hinweis) -ForegroundColor DarkGray } }
                    & $pause
                }
                '^[wW]$' { if (& $yes 'Jetzt in die Windows-Wiederherstellungsumgebung neu starten?') { Write-Host ('  ' + (Invoke-WrDirect 'BootToRe')) -ForegroundColor Green; & $pause } }
                '^[aA]$' {
                    $b = Get-WrBcdInfo (Invoke-NdCmd (Get-SysExe 'bcdedit.exe') '/enum {current}' 30)
                    if ($b.SafeBoot) { if (& $yes ('Der nächste Start ist abgesichert ({0}). Ausschalten?' -f $b.SafeBoot)) { Write-Host ('  ' + (Invoke-WrDirect 'SafeOff')) -ForegroundColor Green } }
                    else {
                        $m = Read-Host '  Abgesicherter Modus beim nächsten Start: [1] minimal  [2] mit Netzwerk  Enter = abbrechen'
                        if ($m -in '1', '2') { Write-Host ('  ' + (Invoke-WrDirect 'SafeMode' $(if ($m -eq '2') { 'network' } else { 'minimal' }))) -ForegroundColor Green; if (& $yes 'Jetzt neu starten?') { Restart-Computer -Force } }
                    }
                    & $pause
                }
                '^[uU]$' { Write-Host ''; Write-Host (Get-WrPendingRevertText) -ForegroundColor Gray; Write-Host ''; if (& $yes 'Jetzt in die Wiederherstellungsumgebung neu starten?') { Write-Host ('  ' + (Invoke-WrDirect 'BootToRe')) -ForegroundColor Green }; & $pause }
                '^[sS]$' { $st = $null }
                '^[gG]$' { Start-Process powershell.exe -ArgumentList ('-NoProfile -ExecutionPolicy Bypass -WindowStyle Hidden -File "{0}"' -f $PSCommandPath) }
                '^[rR]$' { if (& $yes 'PC jetzt neu starten?') { Restart-Computer -Force } }
            }
        } catch { Write-Host ('  Fehler: ' + $_.Exception.Message) -ForegroundColor Red; & $pause }
    }
}







# ================================================================ PC-Tools 10.0
# =====================================================================
#  KOMPLETTSICHERUNG (Fb): Systemabbild des ganzen PCs (wbadmin), Prüfung, Versionen, Zeitplan,
#  Wiederherstellungspaket am Ziel und Notfall-Stick
#  Engine-Teile: FullBackup (Invoke-FbImageJob), FullBackupPrune (Invoke-FbPruneJob),
#                FullBackupPackage (Invoke-FbPackageJob), FullBackupVerify (Invoke-FbVerifyJob)
#  Zeitplan: Aufgabe "PC-Tools Komplettsicherung" -> PCPflege.ps1 -FullBackup (als SYSTEM)
# =====================================================================
$FbTaskName  = 'PC-Tools Komplettsicherung'
$FbPkgFolder = 'PC-Tools-Wiederherstellung'
$FbNasFolder = 'PC-Tools-Komplettsicherung'
$FbDayNames  = [ordered]@{ 'Montag' = 'Monday'; 'Dienstag' = 'Tuesday'; 'Mittwoch' = 'Wednesday'; 'Donnerstag' = 'Thursday'; 'Freitag' = 'Friday'; 'Samstag' = 'Saturday'; 'Sonntag' = 'Sunday' }
# Bekannte Fehler der Windows-Sicherung mit deutscher Erklärung (Code oder Textmuster, deutsch und englisch)
$FbErrorCatalog = @(
    [pscustomobject]@{ Code = '0x807800C5'; Pattern = 'Vorbereiten des Sicherungsabbilds|preparing the backup image'; Title = 'Sicherungsabbild konnte nicht vorbereitet werden'
        Fix = 'Meist ist am Ziel etwas im Weg: eine alte/beschädigte Sicherung, zu wenig Platz, ein schreibgeschütztes Laufwerk oder ein NAS, das keine großen VHDX-Dateien anlegen kann. 1. Freien Platz prüfen. 2. Den Ordner WindowsImageBackup\<PC-Name> am Ziel umbenennen (nicht löschen) und neu sichern. 3. NAS: SMB2/SMB3 einschalten, Schreibrechte des Benutzers prüfen. 4. Ist der Sicherungskatalog beschädigt: Eingabeaufforderung als Administrator "wbadmin delete catalog" (löscht keine Sicherungen, nur das Verzeichnis).' }
    [pscustomobject]@{ Code = '0x80780119'; Pattern = 'nicht genügend Speicherplatz.*Schattenkopie|not enough disk space to create the volume shadow copy'; Title = 'Zu wenig Platz für die Schattenkopie (Wiederherstellungspartition zu klein)'
        Fix = 'Auf einer kleinen Partition - meist "Wiederherstellung" oder "System-reserviert" - ist zu wenig frei für die Schattenkopie. Windows braucht dort bei Partitionen unter 500 MB mindestens 50 MB frei, darüber etwa 320 MB. Lösung: die Wiederherstellungspartition auf etwa 1 GB vergrößern (Seite Windows-Reparatur > Wiederherstellungsumgebung, oder reagentc /disable - Partition vergrößern - reagentc /enable) bzw. unnötige Dateien auf der System-reserviert-Partition entfernen (Seite Updates: Systempartition aufräumen).' }
    [pscustomobject]@{ Code = '0x81000019'; Pattern = 'Schattenkopie konnte nicht erstellt|shadow copy could not be created'; Title = 'Schattenkopie konnte nicht erstellt werden'
        Fix = 'Häufig dieselbe Ursache wie 0x80780119 (kleine Partition zu voll) oder ein gestörter VSS-Writer. Prüfen: Eingabeaufforderung als Administrator "vssadmin list writers" - alle sollten "Stabil" und "Kein Fehler" melden. Dienst "Volumeschattenkopie" neu starten, PC neu starten, andere Sicherungsprogramme (Acronis, Macrium, Veeam) prüfen.' }
    [pscustomobject]@{ Code = '0x80042302'; Pattern = 'Volumeschattenkopie-Dienst|Volume Shadow Copy Service component encountered'; Title = 'Volumeschattenkopie-Dienst gestört'
        Fix = 'Die Dienste "Volumeschattenkopie" (VSS) und "Microsoft Software Shadow Copy Provider" auf "Manuell" stellen und starten, danach neu sichern. Hilft das nicht: Seite Windows-Reparatur > Systemdateien prüfen (SFC/DISM).' }
    [pscustomobject]@{ Code = '0x8004231F'; Pattern = 'Insufficient storage|nicht genügend Speicher für Schattenkopien'; Title = 'Zu wenig Speicher für Schattenkopien'
        Fix = 'Auf einem der gesicherten Laufwerke ist zu wenig Platz für die Schattenkopie. Seite Aufräumen ausführen oder den Schattenkopie-Speicher vergrößern: "vssadmin resize shadowstorage /for=C: /on=C: /maxsize=10%".' }
    [pscustomobject]@{ Code = '0x80042306'; Pattern = 'provider vetoed|Anbieter hat .* abgelehnt'; Title = 'Ein Schattenkopie-Anbieter hat abgelehnt'
        Fix = 'Ein anderes Sicherungs- oder Virenschutzprogramm hat einen eigenen VSS-Anbieter installiert, der stört. "vssadmin list providers" zeigt ihn. Programm aktualisieren oder deinstallieren, PC neu starten.' }
    [pscustomobject]@{ Code = '0x8004230F'; Pattern = 'unexpected provider error|unerwarteter Anbieterfehler'; Title = 'Unerwarteter Fehler des Schattenkopie-Anbieters'
        Fix = 'PC neu starten und erneut sichern. Bleibt der Fehler: Ereignisanzeige > Windows-Protokolle > Anwendung (Quelle VSS) prüfen, Drittanbieter-Sicherungsprogramme entfernen.' }
    [pscustomobject]@{ Code = '0x80042313'; Pattern = 'flush.*timeout|Zeitüberschreitung.*Leeren'; Title = 'Zeitüberschreitung beim Anhalten der Schreibvorgänge'
        Fix = 'Windows konnte die Laufwerke nicht rechtzeitig "einfrieren". Zu einer ruhigeren Zeit sichern (Zeitplan nachts), Programme mit viel Schreiblast schließen (VMs, Datenbanken, Spiele-Downloads) und erneut versuchen.' }
    [pscustomobject]@{ Code = '0x80042314'; Pattern = 'hold.*writes.*timeout'; Title = 'Zeitüberschreitung beim Halten der Schreibvorgänge'
        Fix = 'Wie 0x80042313: zu viel Schreiblast während der Schattenkopie. Später erneut versuchen, große Programme schließen.' }
    [pscustomobject]@{ Code = '0x80070005'; Pattern = 'Zugriff verweigert|Access is denied'; Title = 'Zugriff verweigert'
        Fix = 'NAS: Benutzer und Kennwort speichern (Karte Sicherungsziel) und prüfen, ob dieser Benutzer auf der Freigabe schreiben darf. Lokal: Der "Überwachte Ordnerzugriff" von Defender oder ein Virenschutz blockiert die Windows-Sicherung - wbadmin.exe/wbengine.exe dort zulassen.' }
    [pscustomobject]@{ Code = '0x80070070'; Pattern = 'nicht genügend Speicherplatz auf dem Datenträger|not enough space on the disk'; Title = 'Ziel ist voll'
        Fix = 'Auf dem Ziel ist kein Platz mehr. Ältere Versionen löschen (Karte Versionen), ein größeres Laufwerk nehmen oder die zusätzlichen Datenlaufwerke aus der Sicherung nehmen.' }
    [pscustomobject]@{ Code = '0x80070057'; Pattern = 'Parameter ist falsch|parameter is incorrect'; Title = 'Falscher Parameter'
        Fix = 'Meist ein Ziellaufwerk mit ungeeignetem Dateisystem (FAT32/exFAT) oder ein Laufwerk mit großen 4K-Sektoren über einen alten USB-Adapter. Ziel mit NTFS formatieren bzw. anderen USB-Adapter/Port verwenden.' }
    [pscustomobject]@{ Code = '0x8007045D'; Pattern = 'E/A-Gerätefehler|I/O device error'; Title = 'Gerätefehler beim Lesen oder Schreiben'
        Fix = 'Die Zielfestplatte, das Kabel oder der USB-Anschluss macht Probleme (auch Energiesparen am USB-Port). Anderes Kabel und einen USB-Anschluss direkt am PC nehmen; Festplatte auf der Seite Hardware-Test prüfen. Tritt der Fehler beim Lesen von C: auf: Datenträger prüfen (chkdsk).' }
    [pscustomobject]@{ Code = '0x80070020'; Pattern = 'von einem anderen Prozess verwendet|being used by another process'; Title = 'Datei wird von einem anderen Programm benutzt'
        Fix = 'Ein anderes Programm (Virenschutz, zweite Sicherung, Indexdienst) hält eine Datei am Ziel offen. Erneut versuchen; ggf. den Ordner WindowsImageBackup vom Virenschutz ausnehmen.' }
    [pscustomobject]@{ Code = '0x8078002A'; Pattern = 'Gerätefehler|device error'; Title = 'Gerätefehler an Quelle oder Ziel'
        Fix = 'Ein Datenträger hat einen Fehler gemeldet. Ziel und Kabel prüfen, "chkdsk X: /f" für das Ziel und Seite Hardware-Test für C:. Bei sehr großen USB-Festplatten mit 4K-Sektoren hilft oft ein anderer USB-Adapter.' }
    [pscustomobject]@{ Code = '0x80042403'; Pattern = 'kein Datenträger.*Wiederherstell|No disk that can be used for recovering'; Title = 'Kein passender Datenträger für die Wiederherstellung'
        Fix = 'Beim Zurückspielen: Die neue Festplatte ist kleiner als die alte, wird ohne Treiber nicht erkannt (Intel RST/VMD - im Reparatur-Menü Punkt D) oder ist die Sicherungsplatte selbst. Gleich große oder größere Festplatte einbauen.' }
    [pscustomobject]@{ Code = ''; Pattern = 'NTFS|FAT32|exFAT|nicht unterstützt.*Dateisystem|file system.*not supported'; Title = 'Ungeeignetes Dateisystem am Ziel'
        Fix = 'Die Windows-Sicherung schreibt nur auf NTFS-Laufwerke oder Netzwerkfreigaben - nicht auf FAT32/exFAT. Ein anderes Laufwerk wählen oder das Laufwerk mit NTFS formatieren (Rechtsklick > Formatieren - LÖSCHT ALLES darauf).' }
    [pscustomobject]@{ Code = ''; Pattern = 'nicht gefunden oder unzulässig|not found or (is )?not valid|Sicherungsdatenträger wurde nicht gefunden|storage location .*not found|could not be found'; Title = 'Sicherungsziel nicht gefunden'
        Fix = 'Das Ziel war nicht erreichbar: Festplatte nicht angeschlossen, anderer Laufwerksbuchstabe oder NAS ausgeschaltet/Freigabe umbenannt. Ziel prüfen und den Laufwerksbuchstaben in der Datenträgerverwaltung fest vergeben.' }
    [pscustomobject]@{ Code = ''; Pattern = 'bereits ausgeführt|wird bereits|another .* (operation|backup) .*in progress|already running'; Title = 'Es läuft bereits eine Sicherung'
        Fix = 'Eine andere Windows-Sicherung oder Wiederherstellung läuft gerade. Warten oder sie mit "wbadmin stop job" (Eingabeaufforderung als Administrator) beenden.' }
    [pscustomobject]@{ Code = ''; Pattern = 'Anmeldeinformationen|Kennwort|password|credentials|logon failure|Anmeldung fehlgeschlagen'; Title = 'Anmeldung am NAS fehlgeschlagen'
        Fix = 'Benutzer und Kennwort für die Freigabe neu speichern (Karte Sicherungsziel > Zugang speichern). Der Benutzer muss auf der Freigabe schreiben dürfen; beim NAS am besten einen eigenen Sicherungsbenutzer anlegen.' }
    [pscustomobject]@{ Code = ''; Pattern = 'kein zu sicherndes Volume|no volume(s)? (was|were) (specified|included)'; Title = 'Kein Laufwerk zum Sichern'
        Fix = 'Das Ziel liegt auf einem Laufwerk, das selbst gesichert werden soll, oder die Liste der Laufwerke ist leer. Ein anderes Ziel wählen bzw. das Ziel aus den zusätzlichen Laufwerken nehmen.' }
)

function Format-FbBytes([double]$Bytes) {
    if ($Bytes -ge 1TB) { return ('{0:N2} TB' -f ($Bytes / 1TB)) }
    if ($Bytes -ge 1GB) { return ('{0:N1} GB' -f ($Bytes / 1GB)) }
    if ($Bytes -ge 1MB) { return ('{0:N0} MB' -f ($Bytes / 1MB)) }
    if ($Bytes -gt 0) { return ('{0:N0} KB' -f ($Bytes / 1KB)) }
    return '0 KB'
}
# Ziel normalisieren: 'e' / 'E:\' / 'E:\Ordner' -> 'E:'; UNC ohne abschließenden Backslash
function ConvertTo-FbTarget([string]$Text) {
    $t = ([string]$Text).Trim().Trim('"').TrimEnd('\')
    $r = [ordered]@{ Path = ''; IsNas = $false; Letter = ''; Sub = ''; Valid = $false }
    if (-not $t) { return [pscustomobject]$r }
    if ($t -match '^\\\\[^\\]+\\[^\\]+') { $r.Path = $t; $r.IsNas = $true; $r.Valid = $true; return [pscustomobject]$r }
    $m = [regex]::Match($t, '^([A-Za-z])(:(\\(.*))?)?$')
    if ($m.Success) {
        $r.Letter = $m.Groups[1].Value.ToUpper(); $r.Path = $r.Letter + ':'; $r.Sub = [string]$m.Groups[4].Value; $r.Valid = $true
    }
    return [pscustomobject]$r
}
function Get-FbIntervalDays([string]$Frequency) {
    switch ($Frequency) { 'Alle 2 Wochen' { return 14 } 'Monatlich' { return 31 } default { return 7 } }
}
# ---- Zugangsdaten für das NAS (verschlüsselt, an diesen PC gebunden - lesbar für SYSTEM und Administratoren)
function Save-FbCred([string]$File, [string]$User, [string]$Pwd) {
    Add-Type -AssemblyName System.Security
    $j = @{ User = $User; Pwd = $Pwd } | ConvertTo-Json -Compress
    [IO.File]::WriteAllBytes($File, [Security.Cryptography.ProtectedData]::Protect([Text.Encoding]::UTF8.GetBytes($j), $null, [Security.Cryptography.DataProtectionScope]::LocalMachine))
    & icacls.exe $File /inheritance:r /grant:r '*S-1-5-18:F' '*S-1-5-32-544:F' | Out-Null
}
function Get-FbCred([string]$File, [string]$AltFile = '') {
    foreach ($f in @($File, $AltFile)) {
        if (-not $f -or -not (Test-Path -LiteralPath $f)) { continue }
        try { Add-Type -AssemblyName System.Security; $c = [Text.Encoding]::UTF8.GetString([Security.Cryptography.ProtectedData]::Unprotect([IO.File]::ReadAllBytes($f), $null, [Security.Cryptography.DataProtectionScope]::LocalMachine)) | ConvertFrom-Json; if ($c -and $c.User) { return $c } } catch { }
    }
    return $null
}
function Connect-FbTarget([string]$Path, [string]$CredFile, [string]$AltCredFile = '') {
    if ($Path -notmatch '^(\\\\[^\\]+\\[^\\]+)') { return $true }
    $share = $Matches[1]
    if (Test-Path -LiteralPath $share -ErrorAction SilentlyContinue) { return $true }
    $c = Get-FbCred $CredFile $AltCredFile
    if ($c -and $c.User) { try { $null = & net.exe use $share $c.Pwd ('/user:{0}' -f $c.User) /persistent:no 2>&1 } catch { } }
    return [bool](Test-Path -LiteralPath $share -ErrorAction SilentlyContinue)
}
# Programm mit Ausgabe in der OEM-Codepage (wbadmin, vssadmin) - auch in Invoke-Bg nutzbar
function Invoke-FbCmd([string]$Exe, [string]$ArgLine, [int]$Sec = 120) {
    $psi = New-Object Diagnostics.ProcessStartInfo
    $psi.FileName = $Exe; $psi.Arguments = $ArgLine; $psi.UseShellExecute = $false; $psi.CreateNoWindow = $true
    $psi.RedirectStandardOutput = $true; $psi.RedirectStandardError = $true; $psi.RedirectStandardInput = $true
    try { $enc = [Text.Encoding]::GetEncoding([Globalization.CultureInfo]::CurrentCulture.TextInfo.OEMCodePage); $psi.StandardOutputEncoding = $enc; $psi.StandardErrorEncoding = $enc } catch { }
    $p = [Diagnostics.Process]::Start($psi)
    try { $p.StandardInput.Close() } catch { }
    $so = $p.StandardOutput.ReadToEndAsync(); $se = $p.StandardError.ReadToEndAsync()
    if (-not $p.WaitForExit($Sec * 1000)) { try { $p.Kill() } catch { }; return [pscustomobject]@{ Code = -1; Text = 'Zeitüberschreitung' } }
    $p.WaitForExit()
    return [pscustomobject]@{ Code = [int]$p.ExitCode; Text = (([string]$so.Result) + ([string]$se.Result)) }
}
function Get-FbWbadminExe { $s = Join-Path $env:windir 'Sysnative\wbadmin.exe'; if (Test-Path -LiteralPath $s) { return $s }; return (Join-Path $env:windir 'System32\wbadmin.exe') }

# ---- wbadmin-Ausgabe verstehen (deutsch und englisch)
function ConvertFrom-FbWbadminLine([string]$Line) {
    $x = ([string]$Line -replace "`0", '').Trim()
    $r = [ordered]@{ Kind = 'Info'; Text = $x; Volume = ''; Pct = -1; Code = '' }
    if (-not $x) { $r.Kind = 'Empty'; return [pscustomobject]$r }
    $cm = [regex]::Match($x, '0x[0-9A-Fa-f]{8}'); if ($cm.Success) { $r.Code = '0x' + $cm.Value.Substring(2).ToUpper() }
    $vm = [regex]::Match($x, '\(([A-Za-z]):\)')
    if ($vm.Success) { $r.Volume = $vm.Groups[1].Value.ToUpper() + ':' }
    elseif ($x -match '(?i)EFI[- ]?System[- ]?part') { $r.Volume = 'EFI' }
    elseif ($x -match '(?i)(System[- ]?reserv|System Reserved)') { $r.Volume = 'Reserviert' }
    elseif ($x -match '(?i)(Wiederherstellung|Recovery)\s*\(') { $r.Volume = 'Wiederherstellung' }
    else { $qm = [regex]::Match($x, "(?i)volume\s+'([^']+)'"); if ($qm.Success) { $r.Volume = $qm.Groups[1].Value } }
    $pms = [regex]::Matches($x, '(\d{1,3})(?:[\.,]\d+)?\s?%')
    if ($pms.Count) { $pv = [int]$pms[$pms.Count - 1].Groups[1].Value; if ($pv -ge 0 -and $pv -le 100) { $r.Pct = $pv } }
    if ($x -match '(?i)(backup operation (successfully completed|completed successfully)|Sicherungsvorgang wurde erfolgreich (abgeschlossen|beendet)|Sicherungsvorgang erfolgreich abgeschlossen)') { $r.Kind = 'Success' }
    elseif ($x -match '(?i)(did not (successfully )?complete|could not (be )?complete|konnte nicht|nicht abgeschlossen|fehlgeschlagen|failed|^ERROR|^FEHLER|Fehler:|error:|stopped before|abgebrochen)' -or $r.Code) { $r.Kind = 'Error' }
    elseif ($x -match '(?i)(successfully completed|completed successfully|erfolgreich abgeschlossen)') { $r.Kind = 'VolumeDone' }
    elseif ($r.Pct -ge 0 -and $x -match '(?i)(kopiert|copied|erstellt|creating|sicherung|backup)') { $r.Kind = 'Progress' }
    elseif ($x -match '(?i)(Schattenkopie|shadow copy)') { $r.Kind = 'Shadow' }
    elseif ($x -match '(?i)\.log$' -and $x -match '^[A-Za-z]:\\') { $r.Kind = 'LogFile' }
    elseif ($x -match '(?i)(is starting|wird gestartet)') { $r.Kind = 'Start' }
    return [pscustomobject]$r
}
# Gesamtfortschritt aus dem Fortschritt je Laufwerk (gewichtet nach belegtem Platz). $State: Hashtable (wird verändert)
function Update-FbProgress($State, $P) {
    if (-not $State.ContainsKey('Weights')) { $State.Weights = @{} }
    if (-not $State.ContainsKey('Done')) { $State.Done = @{} }
    if (-not $State.ContainsKey('Cur')) { $State.Cur = ''; $State.CurPct = 0 }
    $known = [double]0; foreach ($k in @($State.Weights.Keys)) { $known += [double]$State.Weights[$k] }
    $small = [math]::Max([double]200MB, $known * 0.005)
    if ($P -and $P.Volume -and -not $State.Weights.ContainsKey($P.Volume)) { $State.Weights[$P.Volume] = $small }
    if ($P -and $P.Kind -eq 'Progress') {
        $v = $(if ($P.Volume) { $P.Volume } else { $State.Cur })
        if ($v) { if ($State.Cur -and $State.Cur -ne $v) { $State.Done[$State.Cur] = $true }; $State.Cur = $v; $State.CurPct = [int]$P.Pct; if ([int]$P.Pct -ge 100) { $State.Done[$v] = $true } }
    }
    if ($P -and $P.Kind -eq 'VolumeDone' -and $P.Volume) { $State.Done[$P.Volume] = $true; if ($State.Cur -eq $P.Volume) { $State.CurPct = 100 } }
    $tot = [double]0; $got = [double]0
    foreach ($k in @($State.Weights.Keys)) {
        $w = [double]$State.Weights[$k]; $tot += $w
        if ($State.Done.ContainsKey($k)) { $got += $w } elseif ($k -eq $State.Cur) { $got += $w * [double]$State.CurPct / 100 }
    }
    if ($P -and $P.Kind -eq 'Success') { $State.Success = $true }
    if ($State.ContainsKey('Success') -and $State.Success) { return 100 }
    if ($tot -le 0) { return [int][math]::Min([double]99, [double]$State.CurPct) }
    return [int][math]::Min([double]99, [math]::Floor($got * 100 / $tot))
}
function Get-FbErrorHelp([string]$Text, $Catalog) {
    $out = [System.Collections.Generic.List[object]]::new()
    $codes = @([regex]::Matches([string]$Text, '0x[0-9A-Fa-f]{8}') | ForEach-Object { '0x' + $_.Value.Substring(2).ToUpper() } | Select-Object -Unique)
    foreach ($e in @($Catalog)) {
        $hit = $false
        if ($e.Code -and ($codes -contains $e.Code.ToUpper().Replace('0X', '0x'))) { $hit = $true }
        elseif ($e.Pattern -and -not $e.Code -and [string]$Text -match ('(?i)' + $e.Pattern)) { $hit = $true }
        elseif ($e.Pattern -and $e.Code -and -not $codes.Count -and [string]$Text -match ('(?i)' + $e.Pattern)) { $hit = $true }
        if ($hit -and -not @($out | Where-Object { $_.Title -eq $e.Title }).Count) { $out.Add($e) }
    }
    foreach ($c in $codes) { if (-not @($Catalog | Where-Object { $_.Code -eq $c }).Count) { $out.Add([pscustomobject]@{ Code = $c; Pattern = ''; Title = ('Fehlercode {0}' -f $c); Fix = ('Unbekannter Code - im Protokoll der Windows-Sicherung (Ereignisanzeige > Anwendungs- und Dienstprotokolle > Microsoft > Windows > Backup) steht die genaue Ursache. Suche im Internet nach "wbadmin {0}".' -f $c) }) } }
    return , $out
}
# "wbadmin get versions" in Objekte umwandeln (Zeitstempel der Version ist UTC: MM/dd/yyyy-HH:mm)
function ConvertFrom-FbVersions([string]$Text) {
    $list = [System.Collections.Generic.List[object]]::new()
    $cur = $null
    $flush = { if ($cur -and $cur.Version) { $list.Add([pscustomobject]$cur) } }
    foreach ($ln in @(([string]$Text) -split "`r?`n")) {
        $l = $ln.Trim()
        if (-not $l) { & $flush; $cur = $null; continue }
        $m = [regex]::Match($l, '^([^:]{2,60}?)\s*:\s*(.*)$')
        if (-not $m.Success) { continue }
        $k = $m.Groups[1].Value.Trim(); $v = $m.Groups[2].Value.Trim()
        if (-not $cur) { $cur = [ordered]@{ Time = ''; Target = ''; Version = ''; CanRecover = ''; SnapshotId = ''; Utc = $null; Local = $null; Bmr = $false } }
        if ($v -match '^\d{2}/\d{2}/\d{4}-\d{2}:\d{2}$') {
            if ($cur.Version) { & $flush; $cur = [ordered]@{ Time = ''; Target = ''; Version = ''; CanRecover = ''; SnapshotId = ''; Utc = $null; Local = $null; Bmr = $false } }
            $cur.Version = $v
            try { $u = [datetime]::ParseExact($v, 'MM/dd/yyyy-HH:mm', [Globalization.CultureInfo]::InvariantCulture, ([Globalization.DateTimeStyles]::AssumeUniversal -bor [Globalization.DateTimeStyles]::AdjustToUniversal)); $cur.Utc = $u; $cur.Local = $u.ToLocalTime() } catch { }
        }
        elseif ($k -match '(?i)snapshot' -or $v -match '^\{[0-9A-Fa-f\-]{36}\}$') { $cur.SnapshotId = $v }
        elseif ($k -match '(?i)(recover|wiederherstell)') { $cur.CanRecover = $v; $cur.Bmr = [bool]($v -match '(?i)(bare.?metal|systemstatus|system state)') }
        elseif ($k -match '(?i)(time|zeit)') { if ($cur.Time -and $cur.Version) { & $flush; $cur = [ordered]@{ Time = ''; Target = ''; Version = ''; CanRecover = ''; SnapshotId = ''; Utc = $null; Local = $null; Bmr = $false } }; $cur.Time = $v }
        elseif ($k -match '(?i)(target|ziel)') { $cur.Target = $v }
    }
    & $flush
    return , $list
}
# Welche Versionen löschen, damit $Keep übrig bleiben? (immer die ältesten, nie die neueste)
function Get-FbRetentionPlan($Versions, [int]$Keep) {
    $k = [math]::Max(1, $Keep)
    $all = @(@($Versions) | Where-Object { $_ } | Sort-Object { $(if ($_.Utc) { [datetime]$_.Utc } else { [datetime]::MinValue }) })
    $out = [System.Collections.Generic.List[object]]::new()
    if ($all.Count -le $k) { return , $out }
    foreach ($v in @($all | Select-Object -First ($all.Count - $k))) { $out.Add($v) }
    return , $out
}
# Ordner WindowsImageBackup\<PC>\Backup yyyy-MM-dd HHmmss (Zeit im Ordnernamen ist UTC) - auch in Datumsordnern (NAS mit Versionen)
function Get-FbImageFolders([string]$Base, [string]$Machine = '', [string]$NasFolder = 'PC-Tools-Komplettsicherung') {
    $list = [System.Collections.Generic.List[object]]::new()
    if (-not $Base -or -not (Test-Path -LiteralPath $Base)) { return , $list }
    $roots = [System.Collections.Generic.List[string]]::new(); $roots.Add($Base)
    $vb = Join-Path $Base $NasFolder
    if (Test-Path -LiteralPath $vb) {
        foreach ($md in @(Get-ChildItem -LiteralPath $vb -Directory -ErrorAction SilentlyContinue)) {
            if ($Machine -and $md.Name -ne $Machine) { continue }
            foreach ($dd in @(Get-ChildItem -LiteralPath $md.FullName -Directory -ErrorAction SilentlyContinue | Where-Object { $_.Name -match '^\d{4}-\d{2}-\d{2}_\d{4}$' })) { $roots.Add($dd.FullName) }
        }
    }
    foreach ($root in $roots) {
        $wib = Join-Path $root 'WindowsImageBackup'
        if (-not (Test-Path -LiteralPath $wib)) { continue }
        foreach ($pc in @(Get-ChildItem -LiteralPath $wib -Directory -ErrorAction SilentlyContinue)) {
            if ($Machine -and $pc.Name -ne $Machine) { continue }
            foreach ($bk in @(Get-ChildItem -LiteralPath $pc.FullName -Directory -ErrorAction SilentlyContinue | Where-Object { $_.Name -like 'Backup *' })) {
                $tm = $null; $mm = [regex]::Match($bk.Name, '^Backup (\d{4}-\d{2}-\d{2}) (\d{6})$')
                if ($mm.Success) { try { $tm = [datetime]::ParseExact(($mm.Groups[1].Value + ' ' + $mm.Groups[2].Value), 'yyyy-MM-dd HHmmss', [Globalization.CultureInfo]::InvariantCulture, ([Globalization.DateTimeStyles]::AssumeUniversal -bor [Globalization.DateTimeStyles]::AdjustToUniversal)).ToLocalTime() } catch { } }
                if (-not $tm) { $tm = $bk.LastWriteTime }
                $vh = @(Get-ChildItem -LiteralPath $bk.FullName -File -ErrorAction SilentlyContinue | Where-Object { $_.Extension -in '.vhdx', '.vhd' } | Sort-Object Length -Descending | ForEach-Object { [pscustomobject]@{ Path = $_.FullName; Name = $_.Name; Bytes = [int64]$_.Length } })
                $sum = [int64]0; foreach ($v in $vh) { $sum += [int64]$v.Bytes }
                $list.Add([pscustomobject]@{ Machine = $pc.Name; Root = $root; Folder = $bk.FullName; Name = $bk.Name; Time = $tm; Bytes = $sum; Vhdx = @($vh); Specs = [bool](Test-Path -LiteralPath (Join-Path $bk.FullName 'BackupSpecs.xml')); Dated = ($root -ne $Base) })
            }
        }
    }
    $sorted = [System.Collections.Generic.List[object]]::new()
    foreach ($x in @($list | Sort-Object Time -Descending)) { $sorted.Add($x) }
    return , $sorted
}
# wbadmin-Versionen und gefundene Ordner zu einer Liste zusammenführen (für die Versionsliste der Oberfläche)
function Merge-FbVersionRows($Wb, $Folders) {
    $rows = [System.Collections.Generic.List[object]]::new()
    $used = @{}
    foreach ($v in @($Wb)) {
        if (-not $v) { continue }
        $t = $(if ($v.Local) { [datetime]$v.Local } else { $null })
        $f = $null
        if ($t) { foreach ($fo in @($Folders)) { if ($fo -and -not $used.ContainsKey($fo.Folder) -and [math]::Abs(([datetime]$fo.Time - $t).TotalMinutes) -le 30) { $f = $fo; break } } }
        if ($f) { $used[$f.Folder] = $true }
        $rows.Add([pscustomobject]@{ Time = $t; DateText = $(if ($t) { $t.ToString('dd.MM.yyyy HH:mm') } else { [string]$v.Time }); Version = [string]$v.Version
            Content = $(if ($v.Bmr) { 'Systemabbild (ganzer PC)' } elseif ($v.CanRecover) { [string]$v.CanRecover } else { 'Systemabbild' })
            Bytes = $(if ($f) { [int64]$f.Bytes } else { [int64]0 }); SizeText = $(if ($f) { Format-FbBytes $f.Bytes } else { 'in Schattenkopie' })
            Place = $(if ($f) { $f.Folder } else { 'ältere Version (Schattenkopie am Ziel)' }); Snapshot = [string]$v.SnapshotId; Folder = $(if ($f) { $f.Folder } else { '' }); Kind = 'wb' })
    }
    foreach ($fo in @($Folders)) {
        if (-not $fo -or $used.ContainsKey($fo.Folder)) { continue }
        $rows.Add([pscustomobject]@{ Time = $fo.Time; DateText = ([datetime]$fo.Time).ToString('dd.MM.yyyy HH:mm'); Version = '-'; Content = $(if ($fo.Machine) { 'Systemabbild von ' + $fo.Machine } else { 'Systemabbild' })
            Bytes = [int64]$fo.Bytes; SizeText = (Format-FbBytes $fo.Bytes); Place = $fo.Folder; Snapshot = ''; Folder = $fo.Folder; Kind = 'folder' })
    }
    $out = [System.Collections.Generic.List[object]]::new()
    foreach ($x in @($rows | Sort-Object { $(if ($_.Time) { [datetime]$_.Time } else { [datetime]::MinValue }) } -Descending)) { $out.Add($x) }
    return , $out
}
# Versionen am Ziel (wbadmin + Ordner) - Ziel ist der eingestellte Pfad (Laufwerk oder Freigabe)
function Get-FbVersions([string]$Target, [string]$Machine, [string]$CredFile = '', [string]$AltCredFile = '', [string]$NasFolder = 'PC-Tools-Komplettsicherung') {
    $t = ConvertTo-FbTarget $Target
    $res = [ordered]@{ Ok = $false; Rows = @(); Wb = @(); Folders = @(); Text = ''; Error = '' }
    if (-not $t.Valid) { $res.Error = 'Kein Ziel eingestellt.'; return [pscustomobject]$res }
    if ($t.IsNas) { $null = Connect-FbTarget $t.Path $CredFile $AltCredFile }
    $base = $(if ($t.IsNas) { $t.Path } else { $t.Path + '\' })
    if (-not (Test-Path -LiteralPath $base)) { $res.Error = ('Ziel {0} ist nicht erreichbar.' -f $t.Path); return [pscustomobject]$res }
    $wb = @()
    if (Test-Path -LiteralPath (Join-Path $base 'WindowsImageBackup')) {
        $a = '-backupTarget:{0}' -f $(if ($t.IsNas) { '"' + $t.Path + '"' } else { $t.Path })
        if ($Machine) { $a += ' -machine:' + $Machine }
        $c = Invoke-FbCmd (Get-FbWbadminExe) ('get versions ' + $a) 120
        $res.Text = $c.Text
        $wb = @(ConvertFrom-FbVersions $c.Text | ForEach-Object { $_ })
    }
    $fo = @(Get-FbImageFolders $base $Machine $NasFolder | ForEach-Object { $_ })
    $res.Wb = $wb; $res.Folders = $fo
    $res.Rows = @(Merge-FbVersionRows $wb $fo | ForEach-Object { $_ })
    $res.Ok = $true
    return [pscustomobject]$res
}

# ---- Laufwerke: kritische Volumes (EFI, Windows, Wiederherstellung) und Datenlaufwerke mit belegtem Platz
function Get-FbVolumeUsage {
    $rows = [System.Collections.Generic.List[object]]::new()
    $sysL = ([string]$env:SystemDrive).TrimEnd(':').ToUpper()
    $sysDisk = -1; try { $sysDisk = [int](Get-Partition -DriveLetter $sysL -ErrorAction Stop | Select-Object -First 1).DiskNumber } catch { }
    $disks = @{}; try { foreach ($d in @(Get-Disk -ErrorAction Stop)) { $disks[[int]$d.Number] = $d } } catch { }
    foreach ($p in @(Get-Partition -ErrorAction SilentlyContinue)) {
        $letter = ''; if ($p.DriveLetter -and [int][char]$p.DriveLetter -ne 0) { $letter = ([string]$p.DriveLetter).ToUpper() }
        $gpt = ([string]$p.GptType).ToLower(); $kind = ''
        if ($gpt -eq '{c12a7328-f81f-11d2-ba4b-00a0c93ec93b}' -or [string]$p.Type -eq 'System') { $kind = 'EFI' }
        elseif ($gpt -eq '{de94bba4-06d1-4d40-a16a-bfd50179d6ac}' -or [string]$p.Type -eq 'Recovery') { $kind = 'Wiederherstellung' }
        elseif ($letter -and $letter -eq $sysL) { $kind = 'System' }
        elseif (-not $letter -and $p.IsActive -and [int]$p.DiskNumber -eq $sysDisk) { $kind = 'Reserviert' }
        elseif ($letter) { $kind = 'Daten' }
        else { continue }
        $v = $null; try { $v = $p | Get-Volume -ErrorAction Stop } catch { }
        $size = [int64]$p.Size; $free = [int64]0; $fs = ''; $label = ''; $dt = ''
        if ($v) { if ([int64]$v.Size -gt 0) { $size = [int64]$v.Size }; $free = [int64]$v.SizeRemaining; $fs = [string]$v.FileSystem; $label = [string]$v.FileSystemLabel; $dt = [string]$v.DriveType }
        $used = [int64]($size - $free); if (-not $v) { $used = $size }
        $skip = [int64]0
        if ($kind -eq 'System') { foreach ($sf in 'pagefile.sys', 'hiberfil.sys', 'swapfile.sys') { try { $fi = Get-Item -LiteralPath ('{0}:\{1}' -f $letter, $sf) -Force -ErrorAction Stop; $skip += [int64]$fi.Length } catch { } } }
        $dk = $null; if ($disks.ContainsKey([int]$p.DiskNumber)) { $dk = $disks[[int]$p.DiskNumber] }
        $crit = ($kind -in 'System', 'EFI', 'Reserviert') -or ($kind -eq 'Wiederherstellung' -and [int]$p.DiskNumber -eq $sysDisk)
        $rows.Add([pscustomobject]@{ Letter = $(if ($letter) { $letter + ':' } else { '' }); Kind = $kind; Label = $label; Fs = $fs; Size = $size; Free = $free; Used = $used
            Est = [int64][math]::Max([double]0, [double]($used - $skip)); DiskNumber = [int]$p.DiskNumber; PartitionNumber = [int]$p.PartitionNumber
            BusType = $(if ($dk) { [string]$dk.BusType } else { '' }); DiskName = $(if ($dk) { [string]$dk.FriendlyName } else { '' }); DriveType = $dt
            OnSystemDisk = ([int]$p.DiskNumber -eq $sysDisk); Critical = [bool]$crit })
    }
    return , $rows
}
# Geschätzte Abbildgröße: kritische Volumes + gewählte Datenlaufwerke (belegter Platz ohne Auslagerungs-/Ruhezustandsdatei)
function Measure-FbEstimate($Rows, [string[]]$Include = @()) {
    $inc = @($Include | Where-Object { $_ } | ForEach-Object { ([string]$_).Trim().TrimEnd('\').ToUpper() })
    $sum = [int64]0; $names = [System.Collections.Generic.List[string]]::new()
    foreach ($r in @($Rows)) {
        if (-not $r) { continue }
        if ($r.Critical -or ($r.Letter -and $inc -contains ([string]$r.Letter).ToUpper())) {
            $sum += [int64]$r.Est
            $names.Add($(if ($r.Letter) { '{0} {1}' -f $r.Letter, $(if ($r.Kind -eq 'System') { 'Windows' } else { $r.Label }) } else { switch ($r.Kind) { 'EFI' { 'EFI-Systempartition' } 'Wiederherstellung' { 'Wiederherstellungspartition' } default { 'System-reserviert' } } }).Trim())
        }
    }
    return [pscustomobject]@{ Bytes = $sum; Names = @($names) }
}
# Zustand eines Ziels (Laufwerk oder Freigabe)
function Get-FbTargetInfo([string]$Target, [string]$CredFile = '', [string]$AltCredFile = '') {
    $t = ConvertTo-FbTarget $Target
    $i = [ordered]@{ Target = $t.Path; Valid = [bool]$t.Valid; IsNas = [bool]$t.IsNas; Letter = $t.Letter; Sub = $t.Sub; Exists = $false; Fs = ''; Label = ''; Free = [int64]-1; Size = [int64]-1
        DiskNumber = -1; OnSystemDisk = $false; IsSystemDrive = $false; BusType = ''; DiskName = ''; HasImages = $false; Error = '' }
    if (-not $t.Valid) { return [pscustomobject]$i }
    try {
        if ($t.IsNas) {
            $null = Connect-FbTarget $t.Path $CredFile $AltCredFile
            $i.Exists = [bool](Test-Path -LiteralPath $t.Path -ErrorAction SilentlyContinue)
            if ($i.Exists) {
                try {
                    if (-not ('PCPflegeFb.Disk' -as [type])) { Add-Type -Namespace PCPflegeFb -Name Disk -MemberDefinition '[DllImport("kernel32.dll", CharSet = CharSet.Unicode, SetLastError = true)] public static extern bool GetDiskFreeSpaceEx(string d, out ulong a, out ulong t, out ulong f);' }
                    $fa = [uint64]0; $tt = [uint64]0; $tf = [uint64]0
                    if ([PCPflegeFb.Disk]::GetDiskFreeSpaceEx(($t.Path.TrimEnd('\') + '\'), [ref]$fa, [ref]$tt, [ref]$tf)) { $i.Free = [int64]$fa; $i.Size = [int64]$tt }
                } catch { }
                $i.HasImages = [bool](Test-Path -LiteralPath (Join-Path $t.Path 'WindowsImageBackup')) -or [bool](Test-Path -LiteralPath (Join-Path $t.Path 'PC-Tools-Komplettsicherung'))
            }
        } else {
            $i.IsSystemDrive = (($t.Letter + ':') -eq ([string]$env:SystemDrive).ToUpper())
            $v = $null; try { $v = Get-Volume -DriveLetter $t.Letter -ErrorAction Stop } catch { }
            if ($v) {
                $i.Exists = $true; $i.Fs = [string]$v.FileSystem; $i.Label = [string]$v.FileSystemLabel; $i.Free = [int64]$v.SizeRemaining; $i.Size = [int64]$v.Size
                $sysDisk = -1; try { $sysDisk = [int](Get-Partition -DriveLetter (([string]$env:SystemDrive).TrimEnd(':')) -ErrorAction Stop | Select-Object -First 1).DiskNumber } catch { }
                try { $pp = Get-Partition -DriveLetter $t.Letter -ErrorAction Stop | Select-Object -First 1; $i.DiskNumber = [int]$pp.DiskNumber; $i.OnSystemDisk = ($sysDisk -ge 0 -and [int]$pp.DiskNumber -eq $sysDisk); $dk = Get-Disk -Number $pp.DiskNumber -ErrorAction Stop; $i.BusType = [string]$dk.BusType; $i.DiskName = [string]$dk.FriendlyName } catch { }
                $i.HasImages = [bool](Test-Path -LiteralPath ('{0}:\WindowsImageBackup' -f $t.Letter))
            }
        }
    } catch { $i.Error = $_.Exception.Message }
    return [pscustomobject]$i
}
# Bewertung des Ziels: Zeilen mit Level ok / info / warn / bad
function Get-FbTargetVerdict($Info, [int64]$Estimate, [bool]$NasVersions = $true, [int]$Keep = 3, [string[]]$Include = @()) {
    $rows = [System.Collections.Generic.List[object]]::new()
    $add = { param($lv, $tx) $rows.Add([pscustomobject]@{ Level = $lv; Text = $tx }) }
    if (-not $Info -or -not $Info.Valid) { & $add 'bad' 'Noch kein Sicherungsziel gewählt - eine externe Festplatte (Laufwerksbuchstabe) oder eine NAS-Freigabe (\\Server\Freigabe).'; return , $rows }
    $est = [double]$Estimate
    if ($Info.IsNas) {
        if (-not $Info.Exists) { & $add 'bad' ('Die Freigabe {0} ist nicht erreichbar - NAS eingeschaltet? Benutzer und Kennwort gespeichert?' -f $Info.Target); return , $rows }
        & $add 'ok' ('Netzwerkfreigabe {0} ist erreichbar.' -f $Info.Target)
        if ($NasVersions) { & $add 'info' ('Jede Sicherung kommt in einen eigenen Datumsordner ({0}\<PC>\<Datum>). Behalten werden {1} Version(en) - jede braucht die volle Größe.' -f 'PC-Tools-Komplettsicherung', [math]::Max(1, $Keep)) }
        else { & $add 'warn' 'Auf einer Netzwerkfreigabe hebt Windows nur EINE Version auf - jede Sicherung ersetzt die vorige. Bricht eine Sicherung ab, kann auch die alte unbrauchbar sein. Empfehlung: "Mehrere Versionen auf dem NAS behalten" einschalten.' }
        if ($Info.Free -ge 0 -and $est -gt 0) {
            $need = $est * 1.1
            if ([double]$Info.Free -lt $need) { & $add 'bad' ('Zu wenig Platz auf der Freigabe: {0} frei, gebraucht werden etwa {1}.' -f (Format-FbBytes $Info.Free), (Format-FbBytes $need)) }
            else { & $add 'ok' ('{0} frei - genug für ein Abbild von etwa {1}.' -f (Format-FbBytes $Info.Free), (Format-FbBytes $est)) }
        }
        & $add 'info' 'Zum Zurückspielen braucht das Reparatursystem Netzwerk: Freigabe als \\IP-Adresse\Freigabe eingeben, NAS-Benutzer bereithalten. Mit WLAN geht das meist nicht - LAN-Kabel verwenden.'
        return , $rows
    }
    if ($Info.Sub) { & $add 'warn' ('Unterordner ("{0}") sind bei lokalen Laufwerken nicht möglich - Windows legt den Ordner WindowsImageBackup immer direkt auf {1}\ an.' -f $Info.Sub, $Info.Target) }
    if (-not $Info.Exists) { & $add 'bad' ('Laufwerk {0} ist nicht angeschlossen bzw. nicht vorhanden.' -f $Info.Target); return , $rows }
    if ($Info.IsSystemDrive) { & $add 'bad' 'Das ist das Windows-Laufwerk selbst - das Abbild kann nicht auf sich selbst geschrieben werden.'; return , $rows }
    if (@($Include | ForEach-Object { ([string]$_).TrimEnd('\').ToUpper() }) -contains ([string]$Info.Target).ToUpper()) { & $add 'bad' ('{0} ist auch als zusätzliches Laufwerk zum Sichern angekreuzt - ein Laufwerk kann nicht Quelle und Ziel zugleich sein.' -f $Info.Target) }
    switch -Regex ([string]$Info.Fs) {
        '^NTFS$'  { & $add 'ok' ('{0} "{1}" ist mit NTFS formatiert.' -f $Info.Target, $Info.Label) }
        '^ReFS$'  { & $add 'warn' ('{0} ist mit ReFS formatiert - die Windows-Sicherung von Windows 11 schreibt darauf in der Regel, offiziell empfohlen ist NTFS.' -f $Info.Target) }
        '^(FAT32|FAT|exFAT)$' { & $add 'bad' ('{0} ist mit {1} formatiert - die Windows-Sicherung braucht NTFS. Ein anderes Laufwerk wählen oder mit NTFS formatieren (Rechtsklick > Formatieren - LÖSCHT ALLES darauf).' -f $Info.Target, $Info.Fs) }
        default   { & $add 'bad' ('{0} hat kein unterstütztes Dateisystem ({1}).' -f $Info.Target, $(if ($Info.Fs) { $Info.Fs } else { 'unformatiert' })) }
    }
    if ($Info.OnSystemDisk) { & $add 'bad' ('{0} liegt auf derselben Festplatte wie Windows. Fällt die Festplatte aus, ist die Sicherung mit weg - bitte eine externe oder zweite Festplatte nehmen.' -f $Info.Target) }
    elseif ([string]$Info.BusType -eq 'USB') { & $add 'ok' ('Externe USB-Festplatte ({0}).' -f $Info.DiskName) }
    elseif ($Info.BusType) { & $add 'info' ('Interne zweite Festplatte ({0}, {1}) - schützt vor Windows- und SSD-Fehlern, nicht vor Diebstahl, Brand oder Überspannung. Zusätzlich gelegentlich extern sichern.' -f $Info.DiskName, $Info.BusType) }
    if ($Info.Size -gt 0 -and $est -gt 0 -and [double]$Info.Size -lt $est) { & $add 'bad' ('Das Laufwerk ist zu klein ({0}) für ein Abbild von etwa {1}.' -f (Format-FbBytes $Info.Size), (Format-FbBytes $est)) }
    elseif ($Info.Free -ge 0 -and $est -gt 0) {
        if (-not $Info.HasImages -and [double]$Info.Free -lt $est * 1.15) { & $add 'bad' ('Zu wenig Platz für die erste Sicherung: {0} frei, gebraucht werden etwa {1}.' -f (Format-FbBytes $Info.Free), (Format-FbBytes ($est * 1.15))) }
        elseif ($Info.HasImages -and [double]$Info.Free -lt $est * 0.2) { & $add 'warn' ('Nur noch {0} frei. Weitere Sicherungen speichern nur Änderungen; wird der Platz knapp, löscht Windows selbst die ältesten Versionen.' -f (Format-FbBytes $Info.Free)) }
        else { & $add 'ok' ('{0} frei von {1} - genug für ein Abbild von etwa {2}.' -f (Format-FbBytes $Info.Free), (Format-FbBytes $Info.Size), (Format-FbBytes $est)) }
    }
    & $add 'info' ('Auf lokalen Laufwerken bewahrt Windows ältere Versionen als Schattenkopien auf (nur die Änderungen) und löscht die ältesten selbst, wenn der Platz knapp wird. PC-Tools behält zusätzlich höchstens {0} Version(en).' -f [math]::Max(1, $Keep))
    return , $rows
}

# ---- Zeitplan: Aufgaben-XML (Wochen-/Monatsplan, Wecken, nur am Netzteil, Wiederholung, verpasste Läufe nachholen)
function Get-FbTaskXml([hashtable]$O) {
    $days = @{ 'Montag' = 'Monday'; 'Dienstag' = 'Tuesday'; 'Mittwoch' = 'Wednesday'; 'Donnerstag' = 'Thursday'; 'Freitag' = 'Friday'; 'Samstag' = 'Saturday'; 'Sonntag' = 'Sunday' }
    $day = $days[[string]$O.Day]; if (-not $day) { $day = 'Sunday' }
    $tm = [datetime]::MinValue
    if (-not [datetime]::TryParseExact(([string]$O.Time).Trim(), 'HH:mm', [Globalization.CultureInfo]::InvariantCulture, 'None', [ref]$tm)) { throw 'Uhrzeit bitte im Format HH:mm angeben, z.B. 20:00' }
    $base = $(if ($O.StartDate) { ([datetime]$O.StartDate).Date } else { (Get-Date).Date })
    $start = '{0:yyyy-MM-dd}T{1:HH:mm}:00' -f $base, $tm
    $sched = switch ([string]$O.Frequency) {
        'Monatlich' {
            $wk = switch ([string]$O.MonthWeek) { 'zweiten' { '2' } 'dritten' { '3' } 'vierten' { '4' } 'letzten' { 'Last' } default { '1' } }
            $months = (@('January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December') | ForEach-Object { '<{0}/>' -f $_ }) -join ''
            '<ScheduleByMonthDayOfWeek><Weeks><Week>{0}</Week></Weeks><DaysOfWeek><{1}/></DaysOfWeek><Months>{2}</Months></ScheduleByMonthDayOfWeek>' -f $wk, $day, $months
        }
        'Alle 2 Wochen' { '<ScheduleByWeek><DaysOfWeek><{0}/></DaysOfWeek><WeeksInterval>2</WeeksInterval></ScheduleByWeek>' -f $day }
        default         { '<ScheduleByWeek><DaysOfWeek><{0}/></DaysOfWeek><WeeksInterval>1</WeeksInterval></ScheduleByWeek>' -f $day }
    }
    $b = { param($v) $(if ($v) { 'true' } else { 'false' }) }
    $retry = $(if ($O.Retry) { '<RestartOnFailure><Interval>PT30M</Interval><Count>3</Count></RestartOnFailure>' } else { '' })
    $esc = { param($s) [Security.SecurityElement]::Escape([string]$s) }
    $x = @"
<?xml version="1.0" encoding="UTF-16"?>
<Task version="1.2" xmlns="http://schemas.microsoft.com/windows/2004/02/mit/task">
  <RegistrationInfo><Author>PC-Tools</Author><Description>PC-Tools: Komplettsicherung (Systemabbild) des ganzen PCs mit der Windows-Sicherung</Description></RegistrationInfo>
  <Triggers><CalendarTrigger><StartBoundary>$start</StartBoundary><Enabled>true</Enabled>$sched</CalendarTrigger></Triggers>
  <Principals><Principal id="Author"><UserId>S-1-5-18</UserId><RunLevel>HighestAvailable</RunLevel></Principal></Principals>
  <Settings>
    <MultipleInstancesPolicy>IgnoreNew</MultipleInstancesPolicy>
    <DisallowStartIfOnBatteries>$(& $b $O.OnlyAc)</DisallowStartIfOnBatteries>
    <StopIfGoingOnBatteries>$(& $b $O.OnlyAc)</StopIfGoingOnBatteries>
    <AllowHardTerminate>true</AllowHardTerminate>
    <StartWhenAvailable>$(& $b ($null -eq $O.CatchUp -or [bool]$O.CatchUp))</StartWhenAvailable>
    <RunOnlyIfNetworkAvailable>$(& $b $O.Network)</RunOnlyIfNetworkAvailable>
    <IdleSettings><StopOnIdleEnd>false</StopOnIdleEnd><RestartOnIdle>false</RestartOnIdle></IdleSettings>
    <AllowStartOnDemand>true</AllowStartOnDemand>
    <Enabled>true</Enabled>
    <Hidden>false</Hidden>
    <RunOnlyIfIdle>false</RunOnlyIfIdle>
    <WakeToRun>$(& $b $O.WakeToRun)</WakeToRun>
    <ExecutionTimeLimit>PT12H</ExecutionTimeLimit>
    <Priority>7</Priority>
    $retry
  </Settings>
  <Actions Context="Author"><Exec><Command>$(& $esc $O.Command)</Command><Arguments>$(& $esc $O.Arguments)</Arguments></Exec></Actions>
</Task>
"@
    return $x
}
function Get-FbScheduleText($F) {
    if (-not $F -or -not $F.Enabled) { return 'kein Zeitplan' }
    $d = [string]$F.Day
    switch ([string]$F.Frequency) {
        'Monatlich' { return ('jeden {0} {1} im Monat um {2} Uhr' -f [string]$F.MonthWeek, $d, [string]$F.Time) }
        'Alle 2 Wochen' { return ('alle 2 Wochen {0} um {1} Uhr' -f $d, [string]$F.Time) }
        default { return ('jeden {0} um {1} Uhr' -f $d, [string]$F.Time) }
    }
}

# ---- Verlauf ($DataDir\Komplettsicherung\history.json)
function Get-FbHistory([string]$Dir) {
    $f = Join-Path $Dir 'history.json'
    $list = [System.Collections.Generic.List[object]]::new()
    if (-not (Test-Path -LiteralPath $f)) { return , $list }
    try { $j = Get-Content -LiteralPath $f -Raw -Encoding UTF8 | ConvertFrom-Json; foreach ($e in @($j)) { if ($e) { $list.Add($e) } } } catch { }
    return , $list
}
function Add-FbHistory([string]$Dir, $Entry, [int]$Max = 80) {
    New-Item -Path $Dir -ItemType Directory -Force -ErrorAction SilentlyContinue | Out-Null
    $all = [System.Collections.Generic.List[object]]::new()
    foreach ($e in (Get-FbHistory $Dir)) { $all.Add($e) }
    $all.Add([pscustomobject]$Entry)
    $keep = @($all | Select-Object -Last $Max)
    $tmp = Join-Path $Dir 'history.json.neu'
    Set-Content -LiteralPath $tmp -Value (ConvertTo-Json -InputObject @($keep) -Depth 5) -Encoding UTF8
    Move-Item -LiteralPath $tmp -Destination (Join-Path $Dir 'history.json') -Force
}
function ConvertTo-FbDate($Value) {
    if ($null -eq $Value -or $Value -eq '') { return $null }
    if ($Value -is [datetime]) { return [datetime]$Value }
    $d = [datetime]::MinValue
    if ([datetime]::TryParse([string]$Value, [Globalization.CultureInfo]::InvariantCulture, [Globalization.DateTimeStyles]::RoundtripKind, [ref]$d)) { return $d.ToLocalTime() }
    if ([datetime]::TryParse([string]$Value, [ref]$d)) { return $d }
    return $null
}
# Zusammenfassung für Statuskarte, Übersicht und Meine PCs
function Get-FbSummary($History, [int]$IntervalDays = 7, [datetime]$Now = (Get-Date)) {
    $h = @(@($History) | Where-Object { $_ })
    $last = $null; $lastOk = $null
    if ($h.Count) { $last = $h[$h.Count - 1] }
    foreach ($e in $h) { if ([string]$e.Result -in 'OK', 'Warnung') { $lastOk = $e } }
    $age = $null
    if ($lastOk) { $le = ConvertTo-FbDate $lastOk.End; if ($le) { $age = ($Now - $le).TotalDays } }
    $state = 'never'
    if ($null -ne $age) { $state = $(if ($age -le $IntervalDays + 2) { 'ok' } elseif ($age -le 2 * $IntervalDays + 2) { 'due' } else { 'overdue' }) }
    $failed = $false
    if ($last -and [string]$last.Result -eq 'Fehler') { $failed = $true }
    return [pscustomobject]@{ Last = $last; LastOk = $lastOk; AgeDays = $age; State = $state; Failed = $failed; Count = $h.Count; Interval = $IntervalDays }
}
function Get-FbHealthArgs($Cfg) {
    $r = @{ FbOn = $false; FbLast = ''; FbDays = 7; FbFail = $false; FbFailMsg = '' }
    if (-not $Cfg -or -not $Cfg.FullBackup -or -not [string]$Cfg.FullBackup.Target) { return $r }
    $hist = Get-FbHistory (Join-Path $DataDir 'Komplettsicherung')
    if (-not $Cfg.FullBackup.Enabled -and -not $hist.Count) { return $r }
    $s = Get-FbSummary $hist (Get-FbIntervalDays ([string]$Cfg.FullBackup.Frequency))
    $r.FbOn = $true; $r.FbDays = [int]$s.Interval
    if ($s.LastOk) { $le = ConvertTo-FbDate $s.LastOk.End; if ($le) { $r.FbLast = $le.ToString('o') } }
    if ($s.Failed) { $r.FbFail = $true; $r.FbFailMsg = [string]$s.Last.Message }
    return $r
}
function Get-FbFleetInfo {
    $cfg = Read-PflegeConfig
    if (-not $cfg.FullBackup -or -not [string]$cfg.FullBackup.Target) { return $null }
    $hist = Get-FbHistory (Join-Path $DataDir 'Komplettsicherung')
    $s = Get-FbSummary $hist (Get-FbIntervalDays ([string]$cfg.FullBackup.Frequency))
    $next = ''; try { $ti = Get-ScheduledTaskInfo -TaskName $FbTaskName -ErrorAction Stop; if ($ti.NextRunTime -and $ti.NextRunTime.Year -gt 2000) { $next = $ti.NextRunTime.ToString('o') } } catch { }
    [pscustomobject]@{
        Last = $(if ($s.LastOk -and (ConvertTo-FbDate $s.LastOk.End)) { (ConvertTo-FbDate $s.LastOk.End).ToString('o') } else { '' }); LastResult = $(if ($s.Last) { [string]$s.Last.Result } else { '' }); State = $s.State
        SizeGB = $(if ($s.LastOk) { [math]::Round([double]$s.LastOk.Bytes / 1GB, 1) } else { 0 }); Target = [string]$cfg.FullBackup.Target
        Schedule = (Get-FbScheduleText $cfg.FullBackup); Next = $next; Message = $(if ($s.Failed) { [string]$s.Last.Message } else { '' })
    }
}

# ---- Notfall-Stick: Stempel prüfen und eingesteckte PCT-NOTFALL-Sticks finden
# Ist der Stick älter als das installierte Windows? (Build des Reparatursystems - nur bei WinRE dieses PCs, eine ISO hat
# naturgemäß oft einen kleineren Build - oder erstellt vor dem letzten Funktionsupdate). $MaxAgeDays = 0: Alter egal.
function Test-FbStickOutdated($Stamp, [int]$CurBuild, [datetime]$OsInstall, [datetime]$Now = (Get-Date), [int]$MaxAgeDays = 180) {
    if (-not $Stamp) { return [pscustomobject]@{ Outdated = $true; Reason = 'Kein Stempel (PC-Tools-Stick.json) auf dem Stick' } }
    $cr = $null; try { $cr = [datetime]::ParseExact([string]$Stamp.Created, 'dd.MM.yyyy HH:mm', [Globalization.CultureInfo]::InvariantCulture) } catch { }
    $m = [regex]::Match([string]$Stamp.WinReVersion, '(\d+)\.(\d+)\.(\d+)\.(\d+)')
    $fromIso = [string]$Stamp.Source -match '(?i)ISO'
    if (-not $fromIso -and $m.Success -and $CurBuild -gt 0 -and [int]$m.Groups[3].Value -lt $CurBuild) { return [pscustomobject]@{ Outdated = $true; Reason = ('Reparatursystem ist Build {0}, Windows ist Build {1}' -f $m.Groups[3].Value, $CurBuild) } }
    if ($cr -and $OsInstall -gt [datetime]'2000-01-01' -and $cr -lt $OsInstall) { return [pscustomobject]@{ Outdated = $true; Reason = ('Stick vom {0:dd.MM.yyyy}, Windows-Funktionsupdate am {1:dd.MM.yyyy}' -f $cr, $OsInstall) } }
    if (-not $cr) { return [pscustomobject]@{ Outdated = $true; Reason = 'Erstellungsdatum unbekannt' } }
    if ($MaxAgeDays -gt 0 -and ($Now - $cr).TotalDays -gt $MaxAgeDays) { return [pscustomobject]@{ Outdated = $true; Reason = ('Stick ist älter als ein halbes Jahr ({0:dd.MM.yyyy})' -f $cr) } }
    return [pscustomobject]@{ Outdated = $false; Reason = ('aktuell (vom {0:dd.MM.yyyy})' -f $cr) }
}
function Get-FbOsBuild {
    $reg = Get-ItemProperty 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion' -ErrorAction SilentlyContinue
    $inst = [datetime]'2000-01-01'; try { if ($reg.InstallDate) { $inst = ([datetime]'1970-01-01').AddSeconds([double]$reg.InstallDate).ToLocalTime() } } catch { }
    [pscustomobject]@{ Build = [int]$reg.CurrentBuild; Ubr = [int]$reg.UBR; Text = ('{0}.{1}' -f $reg.CurrentBuild, $reg.UBR); Display = [string]$reg.DisplayVersion; Install = $inst }
}
function Find-FbRescueSticks {
    $out = [System.Collections.Generic.List[object]]::new()
    foreach ($v in @(Get-Volume -ErrorAction SilentlyContinue | Where-Object { [string]$_.FileSystemLabel -eq 'PCT-NOTFALL' -and $_.DriveLetter })) {
        try {
            $p = Get-Partition -DriveLetter $v.DriveLetter -ErrorAction Stop | Select-Object -First 1
            $d = Get-Disk -Number $p.DiskNumber -ErrorAction Stop
            if ([string]$d.BusType -ne 'USB' -or $d.IsBoot -or $d.IsSystem) { continue }
            $root = '{0}:\' -f $v.DriveLetter; $st = $null
            $sf = Join-Path $root 'PC-Tools-Stick.json'; if (Test-Path -LiteralPath $sf) { try { $st = Get-Content -LiteralPath $sf -Raw -Encoding UTF8 | ConvertFrom-Json } catch { } }
            $out.Add([pscustomobject]@{ DiskNumber = [int]$d.Number; Root = $root; Name = [string]$d.FriendlyName; Size = [int64]$d.Size; Stamp = $st })
        } catch { }
    }
    return , $out
}
function Get-FbStickState {
    $os = Get-FbOsBuild
    $rows = [System.Collections.Generic.List[object]]::new()
    foreach ($s in (Find-FbRescueSticks)) {
        $t = Test-FbStickOutdated $s.Stamp $os.Build $os.Install
        $rows.Add([pscustomobject]@{ DiskNumber = $s.DiskNumber; Root = $s.Root; Name = $s.Name; Outdated = $t.Outdated; Reason = $t.Reason; Created = $(if ($s.Stamp) { [string]$s.Stamp.Created } else { '' }); Parts = $(if ($s.Stamp) { @($s.Stamp.Parts) } else { @() }) })
    }
    return , $rows
}

# ---- Wiederherstellungspaket am Ziel: \PC-Tools-Wiederherstellung\<PC>
function Get-FbPackageRoot([string]$Target, [string]$Machine, [string]$PkgFolder = 'PC-Tools-Wiederherstellung') {
    $t = ConvertTo-FbTarget $Target
    if (-not $t.Valid) { return '' }
    $base = $(if ($t.IsNas) { $t.Path } else { $t.Path + '\' })
    return (Join-Path (Join-Path $base $PkgFolder) $Machine)
}
function Get-FbPackageState([string]$PkgRoot, [string]$CurBuild = '') {
    $r = [ordered]@{ Exists = $false; Ok = $false; Created = ''; Build = ''; Source = ''; WimBytes = [int64]0; Text = 'Noch kein Wiederherstellungspaket am Ziel.' }
    if (-not $PkgRoot -or -not (Test-Path -LiteralPath $PkgRoot)) { return [pscustomobject]$r }
    $r.Exists = $true
    $j = $null; try { $j = Get-Content -LiteralPath (Join-Path $PkgRoot 'Wiederherstellung.json') -Raw -Encoding UTF8 | ConvertFrom-Json } catch { }
    $w = Get-Item -LiteralPath (Join-Path $PkgRoot 'Stick\sources\boot.wim') -Force -ErrorAction SilentlyContinue
    if ($w) { $r.WimBytes = [int64]$w.Length }
    if ($j) { $r.Created = [string]$j.Created; $r.Build = [string]$j.Build; $r.Source = [string]$j.Source }
    $r.Ok = [bool]($w -and $w.Length -gt 100MB -and (Test-Path -LiteralPath (Join-Path $PkgRoot 'Stick\EFI\Microsoft\Boot\BCD')))
    $r.Text = $(if ($r.Ok) { 'Vorhanden vom {0} (Windows {1}, {2}), Reparatursystem {3}.{4}' -f $r.Created, $r.Build, $r.Source, (Format-FbBytes $r.WimBytes), $(if ($CurBuild -and $r.Build -and $r.Build -ne $CurBuild) { ' Windows wurde seitdem aktualisiert - wird bei der nächsten Sicherung erneuert.' } else { '' }) } else { 'Unvollständig - bitte "Paket jetzt schreiben".' })
    return [pscustomobject]$r
}
function Get-FbReadme($I) {
    $l = [System.Collections.Generic.List[string]]::new()
    $a = { param([string]$x) $l.Add($x) }
    & $a 'PC-TOOLS KOMPLETTSICHERUNG - WIEDERHERSTELLUNGSPAKET'
    & $a '==================================================='
    & $a ('PC: {0}   Modell: {1}' -f $I.Computer, $I.Model)
    & $a ('Windows: {0}   Paket erstellt: {1} mit PC-Tools {2}' -f $I.Windows, $I.Created, $I.AppVersion)
    & $a ('Systemabbild liegt in: {0}' -f $I.ImagePath)
    & $a ''
    & $a 'WAS IST DAS?'
    & $a 'Die Komplettsicherung ist ein Abbild des ganzen PCs (Windows, Programme, Einstellungen, Dateien auf C: und den'
    & $a 'gewählten Laufwerken). Damit lässt sich der PC nach einem Festplattenschaden, einer Schadsoftware oder einem'
    & $a 'kaputten Windows auf den Stand der Sicherung zurücksetzen - auch auf eine neue, leere Festplatte.'
    & $a 'Dieses Paket enthält alles, um auf IRGENDEINEM PC einen Start-Stick für die Wiederherstellung zu bauen.'
    & $a ''
    & $a 'INHALT'
    & $a '  Stick\                    Reparatursystem (Windows-Wiederherstellungsumgebung) mit Startdateien und Reparatur-Menü'
    & $a '  Stick-erstellen.cmd       kopiert den Ordner Stick auf einen FAT32-USB-Stick - danach ist der Stick startfähig'
    & $a '  PC-Tools\                 PC-Tools portabel (läuft unter jedem Windows, nicht im Reparatursystem)'
    & $a '  Datentraeger.txt          Aufbau der Festplatten dieses PCs zum Zeitpunkt der Sicherung (Größen!)'
    & $a '  Wiederherstellung.json    technische Angaben'
    & $a ''
    & $a 'TEIL A: START-STICK BAUEN (nur wenn kein Notfall-Stick da ist)'
    & $a '  1. Einen USB-Stick ab 4 GB im Explorer mit FAT32 formatieren (Rechtsklick > Formatieren). Sticks über 32 GB:'
    & $a '     mit PC-Tools (Seite Notfall-Stick) oder Rufus einrichten.'
    & $a '  2. "Stick-erstellen.cmd" doppelklicken und den Laufwerksbuchstaben des Sticks eingeben.'
    & $a '     Oder von Hand: den INHALT des Ordners "Stick" auf den Stick kopieren.'
    & $a '  3. Der Stick startet im UEFI-Modus, auch mit Secure Boot.'
    & $a ''
    & $a 'TEIL B: DEN GANZEN PC ZURÜCKSPIELEN'
    & $a '  1. Die Sicherungsfestplatte anschließen (bei NAS: LAN-Kabel einstecken).'
    & $a '  2. Vom Stick starten: PC einschalten und sofort die Boot-Menü-Taste drücken (HP F9, Lenovo F12, Dell F12,'
    & $a '     Surface: Leiser-Taste halten + Ein/Aus) und den USB-Stick wählen. Startet Windows noch: Umschalt-Taste halten'
    & $a '     und "Neu starten" - dann "Problembehandlung".'
    & $a '  3. Tastaturlayout "Deutsch" wählen.'
    & $a '  4. Problembehandlung > Erweiterte Optionen > "Weitere Wiederherstellungsoptionen anzeigen" >'
    & $a '     "Systemimage-Wiederherstellung" (englisch: System Image Recovery).'
    & $a '  5. "Neuestes verfügbares Systemabbild verwenden" - oder "Systemabbild auswählen" für eine ältere Version.'
    & $a '     Liegt das Abbild auf dem NAS: "Systemabbild auswählen" > "Erweitert" > "Im Netzwerk nach einem Systemabbild'
    & $a ('     suchen" und \\IP-Adresse\Freigabe eingeben (Pfad: {0}).' -f $I.NasHint)
    & $a '  6. Neue/leere Festplatte: "Datenträger formatieren und neu partitionieren" ankreuzen. ACHTUNG: Die Sicherungs-'
    & $a '     festplatte über "Datenträger ausschließen" schützen!'
    & $a '  7. "Fertig stellen" - die Wiederherstellung dauert etwa so lange wie die Sicherung. Danach startet der PC neu.'
    & $a '  Alternative: Im Reparatursystem "Eingabeaufforderung" > Stick:\Reparatur\Reparatur.cmd > Punkt S.'
    & $a ''
    & $a 'WICHTIG'
    & $a '  - Die neue Festplatte muss mindestens so groß sein wie die alte (siehe Datentraeger.txt).'
    & $a '  - BitLocker: Nach dem Zurückspielen kann Windows den 48-stelligen Wiederherstellungsschlüssel verlangen'
    & $a ('    (https://aka.ms/myrecoverykey). {0}' -f $I.BitLocker)
    & $a '  - Alles, was nach der Sicherung auf C: gespeichert wurde, ist danach weg - vorher Dateien retten'
    & $a '    (Reparatur-Menü Punkt 6 sichert persönliche Dateien auf den Stick).'
    & $a '  - "Kein Systemabbild gefunden": Der Ordner WindowsImageBackup muss direkt im Hauptverzeichnis der'
    & $a '    Festplatte liegen; Festplatte vor dem Start anschließen.'
    & $a '  - "Kein Datenträger für die Wiederherstellung" (0x80042403): SSD ohne Treiber nicht sichtbar (Intel RST/VMD -'
    & $a '    Reparatur-Menü Punkt D) oder neue Festplatte zu klein.'
    & $a ''
    & $a 'EINZELNE DATEIEN HOLEN (ohne den PC zurückzusetzen)'
    & $a '  PC-Tools > Komplettsicherung > "Einzelne Dateien aus dem Abbild holen". Ohne PC-Tools: Datenträgerverwaltung >'
    & $a '  Aktion > "Virtuelle Festplatte anfügen" > die größte .vhdx-Datei aus WindowsImageBackup\<PC>\Backup ... wählen,'
    & $a '  "Schreibgeschützt" ankreuzen. Danach wieder "Virtuelle Festplatte trennen".'
    return , $l
}
function Get-FbStickCmd {
    $t = @'
@echo off
setlocal EnableExtensions
title PC-Tools - Start-Stick aus dem Wiederherstellungspaket
cd /d "%~dp0"
echo.
echo  ==============================================================
echo    PC-Tools - Start-Stick aus dem Wiederherstellungspaket
echo  ==============================================================
echo.
echo  Kopiert das Reparatursystem aus diesem Paket auf einen USB-Stick.
echo  Der Stick muss vorher mit FAT32 formatiert sein:
echo  Explorer - Rechtsklick auf den Stick - Formatieren - Dateisystem FAT32.
echo  Sticks ueber 32 GB: mit PC-Tools - Seite Notfall-Stick - oder mit Rufus einrichten.
echo.
if not exist "%~dp0Stick\sources\boot.wim" goto nopkg
set "DST="
set /p "DST=  Laufwerksbuchstabe des Sticks, z.B. F: "
if not defined DST goto ende
set "DST=%DST:~0,1%:"
if /i "%DST%"=="%SystemDrive%" goto bad
if not exist "%DST%\" goto bad
echo.
echo  Dateien gleichen Namens auf %DST% werden ersetzt, andere Dateien bleiben.
set "YN="
set /p "YN=  Jetzt kopieren? J/N: "
if /i not "%YN%"=="J" goto ende
robocopy "%~dp0Stick" "%DST%\." /E /R:1 /W:1 /NP /NJH
if errorlevel 8 goto fail
if exist "%~dp0PC-Tools\PCPflege.ps1" robocopy "%~dp0PC-Tools" "%DST%\PC-Tools" /E /R:1 /W:1 /NP /NJH /NFL /NDL
echo.
echo  Fertig. Vom Stick starten: Boot-Menue-Taste F12, F9, F8 oder Esc beim Einschalten,
echo  oder in Windows Umschalt-Taste halten und Neu starten - Ein Geraet verwenden.
goto ende
:nopkg
echo  Im Paket fehlt Stick\sources\boot.wim - das Paket ist unvollstaendig.
goto ende
:bad
echo  Laufwerk %DST% nicht gefunden oder es ist das Windows-Laufwerk.
goto ende
:fail
echo  Kopieren fehlgeschlagen - Stick voll oder nicht FAT32? Dateien ueber 4 GB passen nicht auf FAT32.
:ende
echo.
pause
endlocal
'@
    return @($t -split "`r?`n")
}
function Get-FbDiskLayout {
    $l = [System.Collections.Generic.List[string]]::new()
    $l.Add(('Datenträger von {0} am {1:dd.MM.yyyy HH:mm}' -f $env:COMPUTERNAME, (Get-Date))); $l.Add('')
    foreach ($d in @(Get-Disk -ErrorAction SilentlyContinue | Sort-Object Number)) {
        $l.Add(('Datenträger {0}: {1}  {2}  {3}  ({4}){5}' -f $d.Number, $d.FriendlyName, (Format-FbBytes $d.Size), [string]$d.PartitionStyle, [string]$d.BusType, $(if ($d.IsBoot) { '  <- Windows' } else { '' })))
        foreach ($p in @(Get-Partition -DiskNumber $d.Number -ErrorAction SilentlyContinue | Sort-Object PartitionNumber)) {
            $v = $null; try { $v = $p | Get-Volume -ErrorAction Stop } catch { }
            $l.Add(('   Partition {0}: {1,-10} {2,10}  {3} {4} {5}' -f $p.PartitionNumber, [string]$p.Type, (Format-FbBytes $p.Size), $(if ($p.DriveLetter -and [int][char]$p.DriveLetter -ne 0) { [string]$p.DriveLetter + ':' } else { '  ' }), $(if ($v) { [string]$v.FileSystem } else { '' }), $(if ($v) { [string]$v.FileSystemLabel } else { '' })))
        }
        $l.Add('')
    }
    return , $l
}
# Paket schreiben. Startteil (boot.wim, Startdateien, BCD) nur neu, wenn nötig: kein Paket, anderer Windows-Build, älter als 60 Tage oder -Force
function Write-FbPackage([string]$PkgRoot, [string]$Source = 'WinRE', [string]$ImagePath = '', [switch]$Force) {
    $os = Get-FbOsBuild
    New-Item -Path $PkgRoot -ItemType Directory -Force | Out-Null
    $stick = Join-Path $PkgRoot 'Stick'
    $old = Get-FbPackageState $PkgRoot $os.Text
    $oldDate = $null; try { $oldDate = [datetime]::ParseExact($old.Created, 'dd.MM.yyyy HH:mm', [Globalization.CultureInfo]::InvariantCulture) } catch { }
    $rebuild = $Force -or -not $old.Ok -or ($old.Build -ne $os.Text) -or (-not $oldDate) -or (((Get-Date) - $oldDate).TotalDays -gt 60)
    $cs = Get-CimInstance Win32_ComputerSystem -ErrorAction SilentlyContinue
    $info = [ordered]@{ Created = (Get-Date).ToString('dd.MM.yyyy HH:mm'); Computer = $env:COMPUTERNAME; Model = $(if ($cs) { ('{0} {1}' -f $cs.Manufacturer, $cs.Model).Trim() } else { '' })
        Windows = ('{0} (Build {1})' -f $os.Display, $os.Text); Build = $os.Text; AppVersion = $AppVersion; Source = $old.Source; WinReVersion = ''; ImagePath = $ImagePath; BitLocker = ''; NasHint = '' }
    if ($ImagePath -match '^\\\\') { $info.NasHint = $ImagePath } else { $info.NasHint = 'nur bei NAS-Sicherungen' }
    try { $bl = Get-BitLockerVolume -MountPoint $env:SystemDrive -ErrorAction Stop; if ([string]$bl.ProtectionStatus -eq 'On') { $kp = @($bl.KeyProtector | Where-Object { [string]$_.KeyProtectorType -eq 'RecoveryPassword' } | Select-Object -First 1); $info.BitLocker = 'Laufwerk C: ist mit BitLocker verschlüsselt' + $(if ($kp.Count) { ' - Schlüssel-ID ' + $kp[0].KeyProtectorId + ' (beginnt mit diesen Zeichen).' } else { '.' }) } else { $info.BitLocker = 'BitLocker ist auf C: nicht aktiv.' } } catch { $info.BitLocker = 'BitLocker-Status unbekannt.' }
    if ($rebuild) {
        Write-PLog ('Wiederherstellungspaket: Reparatursystem wird neu geschrieben ({0})' -f $(if ($Force) { 'auf Wunsch' } elseif (-not $old.Ok) { 'noch keins vorhanden' } elseif ($old.Build -ne $os.Text) { 'Windows wurde aktualisiert' } else { 'älter als 60 Tage' }))
        foreach ($sub in 'sources', 'boot', 'EFI\Boot', 'EFI\Microsoft\Boot', 'Reparatur') { New-Item -Path (Join-Path $stick $sub) -ItemType Directory -Force | Out-Null }
        $efiName = Get-RsEfiName
        $bootDir = Join-Path $env:windir 'Boot'
        $efiSrc = Join-Path $bootDir 'EFI\bootmgfw.efi'
        $sdiSrc = Join-Path $bootDir 'DVD\EFI\boot.sdi'; if (-not (Test-Path -LiteralPath $sdiSrc)) { $sdiSrc = Join-Path $bootDir 'DVD\PCAT\boot.sdi' }
        $wimTmp = Join-Path $stick 'sources\boot.wim.neu'
        $isoPath = ''; $mounted = $false
        try {
            if ($Source -eq 'ISO') {
                $isoPath = Get-RsLatestIso
                $img = Mount-DiskImage -ImagePath $isoPath -PassThru -ErrorAction Stop; $mounted = $true
                $src = '{0}:\' -f ($img | Get-Volume).DriveLetter
                $Script:Detail = 'Paket: boot.wim aus der Windows-ISO'; Set-PStatus $Script:StatusText
                Copy-Item -LiteralPath (Join-Path $src 'sources\boot.wim') -Destination $wimTmp -Force -ErrorAction Stop
                $ie = Join-Path $src ('efi\boot\' + $efiName); if (Test-Path -LiteralPath $ie) { $efiSrc = $ie }
                $is = Join-Path $src 'boot\boot.sdi'; if (Test-Path -LiteralPath $is) { $sdiSrc = $is }
                $info.Source = 'Windows-ISO ' + [IO.Path]::GetFileName($isoPath)
            } else {
                $Script:Detail = 'Paket: Wiederherstellungsumgebung (WinRE) wird kopiert'; Set-PStatus $Script:StatusText
                $null = Copy-RsWinRe $wimTmp
                $info.Source = 'WinRE von ' + $env:COMPUTERNAME
            }
            try { (Get-Item -LiteralPath $wimTmp -Force).Attributes = 'Archive' } catch { }
            Move-Item -LiteralPath $wimTmp -Destination (Join-Path $stick 'sources\boot.wim') -Force -ErrorAction Stop
        } finally {
            if ($mounted) { Dismount-DiskImage -ImagePath $isoPath -ErrorAction SilentlyContinue | Out-Null }
            if (Test-Path -LiteralPath $wimTmp) { Remove-Item -LiteralPath $wimTmp -Force -ErrorAction SilentlyContinue }
        }
        try { $wi = Get-WindowsImage -ImagePath (Join-Path $stick 'sources\boot.wim') -Index 1 -ErrorAction Stop; $info.WinReVersion = '{0} {1}' -f $wi.ImageName, $wi.Version } catch { }
        Copy-Item -LiteralPath $sdiSrc -Destination (Join-Path $stick 'boot\boot.sdi') -Force -ErrorAction Stop
        Copy-Item -LiteralPath $efiSrc -Destination (Join-Path $stick ('EFI\Boot\' + $efiName)) -Force -ErrorAction Stop
        try { $fnt = Join-Path $bootDir 'Fonts'; if (Test-Path -LiteralPath $fnt) { $fd = New-Item (Join-Path $stick 'EFI\Microsoft\Boot\Fonts') -ItemType Directory -Force; Copy-Item -Path (Join-Path $fnt '*') -Destination $fd.FullName -Force -ErrorAction SilentlyContinue } } catch { }
        # Startkonfiguration lokal bauen (bcdedit kann nicht auf Netzwerkpfade schreiben) und dann kopieren
        $tmpRoot = Join-Path $env:TEMP ('pct-fbbcd-{0}' -f (Get-Random))
        try {
            $null = New-RsBcdStore $tmpRoot
            Copy-Item -LiteralPath (Join-Path $tmpRoot 'EFI\Microsoft\Boot\BCD') -Destination (Join-Path $stick 'EFI\Microsoft\Boot\BCD') -Force -ErrorAction Stop
        } finally { Remove-Item -LiteralPath $tmpRoot -Recurse -Force -ErrorAction SilentlyContinue }
        $stamp = [ordered]@{ Created = $info.Created; Computer = $env:COMPUTERNAME; AppVersion = $AppVersion; Source = $info.Source; WinReVersion = $info.WinReVersion; BootSigner = ''; Arch = $(if ($efiName -eq 'bootaa64.efi') { 'ARM64' } else { 'x64' }); Parts = @('Reparatursystem') }
        [pscustomobject]$stamp | ConvertTo-Json -Depth 3 | Set-Content -LiteralPath (Join-Path $stick 'PC-Tools-Stick.json') -Encoding UTF8
        Write-PLog ('   Reparatursystem im Paket: {0}' -f (Format-FbBytes (Get-Item -LiteralPath (Join-Path $stick 'sources\boot.wim') -Force).Length)) 'OK'
    } else {
        $info.Created = $old.Created; $info.Source = $old.Source
        try { $oj = Get-Content -LiteralPath (Join-Path $PkgRoot 'Wiederherstellung.json') -Raw -Encoding UTF8 | ConvertFrom-Json; $info.WinReVersion = [string]$oj.WinReVersion } catch { }
        Write-PLog ('Wiederherstellungspaket: Reparatursystem ist aktuell (vom {0}) - nur Anleitung und Menü werden erneuert.' -f $old.Created)
    }
    New-Item -Path (Join-Path $stick 'Reparatur') -ItemType Directory -Force | Out-Null
    [IO.File]::WriteAllText((Join-Path $stick 'Reparatur\Reparatur.cmd'), (((Get-RsRepairCmd) -join "`r`n") + "`r`n"), [Text.Encoding]::ASCII)
    [IO.File]::WriteAllText((Join-Path $PkgRoot 'Stick-erstellen.cmd'), (((Get-FbStickCmd) -join "`r`n") + "`r`n"), [Text.Encoding]::ASCII)
    $rm = Get-FbReadme ([pscustomobject]$info)
    Set-Content -LiteralPath (Join-Path $PkgRoot 'LIESMICH.txt') -Value $rm -Encoding UTF8
    Set-Content -LiteralPath (Join-Path $stick 'LIESMICH.txt') -Value $rm -Encoding UTF8
    try { Set-Content -LiteralPath (Join-Path $PkgRoot 'Datentraeger.txt') -Value (Get-FbDiskLayout) -Encoding UTF8 } catch { }
    try { $Script:Detail = 'Paket: PC-Tools portabel'; Set-PStatus $Script:StatusText; Copy-PortablePflege (Join-Path $PkgRoot 'PC-Tools') $false } catch { Write-PLog ('   PC-Tools portabel: {0}' -f $_.Exception.Message) 'WARN' }
    [pscustomobject]$info | ConvertTo-Json -Depth 3 | Set-Content -LiteralPath (Join-Path $PkgRoot 'Wiederherstellung.json') -Encoding UTF8
    Write-PLog ('Wiederherstellungspaket aktuell: {0}' -f $PkgRoot) 'OK'
    return [pscustomobject]$info
}

# ---- VHDX schreibgeschützt einbinden (Prüfung und einzelne Dateien)
function Mount-FbVhd([string]$Path, [string]$MountDir = '') {
    $res = [ordered]@{ Path = $Path; DiskNumber = -1; Roots = @(); AccessPaths = @(); Error = '' }
    $null = Mount-DiskImage -ImagePath $Path -Access ReadOnly -ErrorAction Stop
    $dk = $null
    for ($i = 0; $i -lt 20 -and -not $dk; $i++) { try { $dk = Get-DiskImage -ImagePath $Path -ErrorAction Stop | Get-Disk -ErrorAction Stop } catch { Start-Sleep -Milliseconds 500 } }
    if (-not $dk) { $res.Error = 'Der eingebundene Datenträger wurde nicht gefunden.'; return [pscustomobject]$res }
    $res.DiskNumber = [int]$dk.Number
    if ($dk.IsOffline) {
        $why = [string]$dk.OfflineReason
        $res.Error = $(if ($why -match 'Collision|Signatur') { 'Windows hält das Abbild offline, weil es dieselbe Datenträgerkennung wie die eingebaute Festplatte hat (Signaturkonflikt). Schreibgeschützt lässt sich das nicht lösen - das Abbild auf einem anderen PC öffnen oder im Reparatursystem zurückspielen.' } else { 'Das Abbild ist offline (' + $why + ').' })
        return [pscustomobject]$res
    }
    $roots = [System.Collections.Generic.List[string]]::new(); $aps = [System.Collections.Generic.List[string]]::new()
    for ($i = 0; $i -lt 10; $i++) {
        $parts = @(Get-Partition -DiskNumber $dk.Number -ErrorAction SilentlyContinue | Where-Object { [string]$_.Type -notin 'Reserved', 'Unknown' -and $_.Size -gt 50MB })
        if ($parts.Count) { break }
        Start-Sleep -Milliseconds 500
    }
    foreach ($p in $parts) {
        if ($p.DriveLetter -and [int][char]$p.DriveLetter -ne 0) { $roots.Add(('{0}:\' -f $p.DriveLetter)); continue }
        $ok = $false
        try { $p | Add-PartitionAccessPath -AssignDriveLetter -ErrorAction Stop; $p2 = Get-Partition -DiskNumber $p.DiskNumber -PartitionNumber $p.PartitionNumber; if ($p2.DriveLetter -and [int][char]$p2.DriveLetter -ne 0) { $roots.Add(('{0}:\' -f $p2.DriveLetter)); $ok = $true } } catch { }
        if (-not $ok -and $MountDir) {
            try { $md = Join-Path $MountDir ('Abbild-{0}-{1}' -f $dk.Number, $p.PartitionNumber); New-Item -Path $md -ItemType Directory -Force | Out-Null; Add-PartitionAccessPath -DiskNumber $p.DiskNumber -PartitionNumber $p.PartitionNumber -AccessPath ($md + '\') -ErrorAction Stop; $roots.Add($md + '\'); $aps.Add($md) } catch { }
        }
    }
    $res.Roots = @($roots); $res.AccessPaths = @($aps)
    if (-not $roots.Count) { $res.Error = 'Das Abbild ist eingebunden, aber Windows hat ihm keinen Laufwerksbuchstaben gegeben.' }
    return [pscustomobject]$res
}
function Dismount-FbVhd([string]$Path, [string[]]$AccessPaths = @()) {
    try { $dk = Get-DiskImage -ImagePath $Path -ErrorAction Stop | Get-Disk -ErrorAction Stop; foreach ($ap in @($AccessPaths)) { try { foreach ($p in @(Get-Partition -DiskNumber $dk.Number -ErrorAction SilentlyContinue)) { Remove-PartitionAccessPath -DiskNumber $dk.Number -PartitionNumber $p.PartitionNumber -AccessPath ($ap + '\') -ErrorAction SilentlyContinue } } catch { } } } catch { }
    Dismount-DiskImage -ImagePath $Path -ErrorAction Stop | Out-Null
    foreach ($ap in @($AccessPaths)) { if ($ap -and (Test-Path -LiteralPath $ap)) { Remove-Item -LiteralPath $ap -Force -Recurse -ErrorAction SilentlyContinue } }
    return $true
}
# Sicherung prüfen: wbadmin kennt die Version, Ordner und VHDX-Dateien vorhanden und plausibel, optional Abbild einbinden und Windows darin finden
function Test-FbBackup([string]$Target, [string]$Machine, [datetime]$Since = [datetime]::MinValue, [int64]$Estimate = 0, [switch]$Deep, [string]$MountDir = '') {
    $rows = [System.Collections.Generic.List[object]]::new()
    $add = { param($lv, $it, $dt) $rows.Add([pscustomobject]@{ Level = $lv; Item = $it; Detail = $dt }) }
    $t = ConvertTo-FbTarget $Target
    $base = $(if ($t.IsNas) { $t.Path } else { $t.Path + '\' })
    $ver = ''
    if (Test-Path -LiteralPath (Join-Path $base 'WindowsImageBackup')) {
        $c = Invoke-FbCmd (Get-FbWbadminExe) ('get versions -backupTarget:{0} -machine:{1}' -f $(if ($t.IsNas) { '"' + $t.Path + '"' } else { $t.Path }), $Machine) 120
        $vv = @(ConvertFrom-FbVersions $c.Text | ForEach-Object { $_ })
        $newest = @($vv | Where-Object { $_.Local } | Sort-Object Local -Descending | Select-Object -First 1)
        if ($newest.Count -and ($Since -eq [datetime]::MinValue -or [datetime]$newest[0].Local -ge $Since.AddMinutes(-5))) { $ver = [string]$newest[0].Version; & $add 'ok' 'Windows-Sicherung kennt die Version' ('{0} ({1:dd.MM.yyyy HH:mm}), {2} Version(en) am Ziel{3}' -f $ver, [datetime]$newest[0].Local, $vv.Count, $(if ($newest[0].Bmr) { ', vollständige Wiederherstellung möglich' } else { '' })) }
        elseif ($newest.Count) { & $add 'warn' 'Windows-Sicherung kennt die Version' ('Neueste Version ist vom {0:dd.MM.yyyy HH:mm} - älter als diese Sicherung.' -f [datetime]$newest[0].Local) }
        else { & $add 'bad' 'Windows-Sicherung kennt die Version' ('"wbadmin get versions" findet keine Version. {0}' -f ((([string]$c.Text) -split "`r?`n" | Where-Object { $_.Trim() } | Select-Object -Last 2) -join ' ')) }
    } else { & $add 'bad' 'Ordner WindowsImageBackup' ('fehlt unter {0}' -f $base) }
    $fo = @(Get-FbImageFolders $base $Machine | ForEach-Object { $_ })
    $nf = @($fo | Select-Object -First 1)
    $bytes = [int64]0; $vhdx = ''
    if ($nf.Count) {
        $f = $nf[0]; $bytes = [int64]$f.Bytes
        & $add $(if ($Since -eq [datetime]::MinValue -or [datetime]$f.Time -ge $Since.AddMinutes(-5)) { 'ok' } else { 'warn' }) 'Sicherungsordner' ('{0} ({1:dd.MM.yyyy HH:mm})' -f $f.Folder, [datetime]$f.Time)
        if (@($f.Vhdx).Count) {
            $vhdx = [string]$f.Vhdx[0].Path
            $tiny = @($f.Vhdx | Where-Object { [int64]$_.Bytes -lt 1MB }).Count
            & $add $(if ($tiny) { 'warn' } else { 'ok' }) 'Abbild-Dateien (VHDX)' ('{0} Datei(en), zusammen {1}, größte {2}{3}' -f @($f.Vhdx).Count, (Format-FbBytes $bytes), (Format-FbBytes $f.Vhdx[0].Bytes), $(if ($tiny) { (' - {0} auffällig kleine Datei(en)' -f $tiny) } else { '' }))
            if ($Estimate -gt 0) {
                $ratio = [double]$bytes / [double]$Estimate
                if ($ratio -lt 0.3) { & $add 'warn' 'Größe plausibel?' ('Das Abbild ({0}) ist viel kleiner als der belegte Platz ({1}) - bitte gründlich prüfen.' -f (Format-FbBytes $bytes), (Format-FbBytes $Estimate)) }
                else { & $add 'ok' 'Größe plausibel' ('{0:N0} % des belegten Platzes (Auslagerungsdatei, Ruhezustand und Schattenkopien werden nicht gesichert)' -f ($ratio * 100)) }
            }
        } else { & $add 'bad' 'Abbild-Dateien (VHDX)' 'Im Sicherungsordner liegt keine .vhdx-Datei.' }
        if (-not $f.Specs) { & $add 'warn' 'BackupSpecs.xml' 'fehlt - die Sicherung ist vermutlich unvollständig.' }
    } else { & $add 'bad' 'Sicherungsordner' ('Kein Ordner "Backup ..." unter {0}\WindowsImageBackup\{1}' -f $base.TrimEnd('\'), $Machine) }
    if ($Deep -and $vhdx) {
        $m = $null
        try {
            $m = Mount-FbVhd $vhdx $MountDir
            if ($m.Error) { & $add 'warn' 'Gründliche Prüfung (Abbild einbinden)' $m.Error }
            else {
                $found = ''
                foreach ($r in @($m.Roots)) { if ([IO.File]::Exists((Join-Path $r 'Windows\System32\config\SYSTEM'))) { $found = $r } }
                if ($found) {
                    $cnt = 0; try { $cnt = @(Get-ChildItem -LiteralPath (Join-Path $found 'Windows\System32') -File -ErrorAction Stop | Select-Object -First 500).Count } catch { }
                    & $add 'ok' 'Gründliche Prüfung (Abbild einbinden)' ('Abbild schreibgeschützt eingebunden, Windows gefunden ({0}Windows\System32\config\SYSTEM, {1}+ Systemdateien lesbar).' -f $found, $cnt)
                } else { & $add 'warn' 'Gründliche Prüfung (Abbild einbinden)' ('Eingebunden ({0}), aber in der größten Abbild-Datei wurde kein Windows gefunden.' -f (@($m.Roots) -join ', ')) }
            }
        } catch { & $add 'warn' 'Gründliche Prüfung (Abbild einbinden)' ('nicht möglich: {0}' -f $_.Exception.Message) }
        finally { try { $null = Dismount-FbVhd $vhdx $(if ($m) { @($m.AccessPaths) } else { @() }) } catch { } }
    }
    $bad = @($rows | Where-Object { $_.Level -eq 'bad' }).Count; $warn = @($rows | Where-Object { $_.Level -eq 'warn' }).Count
    return [pscustomobject]@{ Ok = ($bad -eq 0); Warn = $warn; Rows = @($rows); Version = $ver; Bytes = $bytes; Vhdx = $vhdx; Text = $(if ($bad) { 'Prüfung fehlgeschlagen' } elseif ($warn) { 'geprüft mit Hinweisen' } elseif ($Deep) { 'gründlich geprüft' } else { 'geprüft' }) }
}

# ---- wbadmin ausführen: Zeilen live auswerten, Fortschritt anzeigen, Abbruch über "wbadmin stop job"
function Invoke-FbWbadmin([string[]]$Arguments, [hashtable]$State, [int]$TimeoutMin = 720, [string]$Mask = '') {
    $exe = Get-FbWbadminExe
    $shown = ($Arguments -join ' '); if ($Mask) { $shown = $shown.Replace($Mask, '********') }
    Write-PLog ('   wbadmin {0}' -f $shown)
    $psi = New-Object Diagnostics.ProcessStartInfo
    $psi.FileName = $exe; $psi.Arguments = ($Arguments -join ' '); $psi.UseShellExecute = $false; $psi.CreateNoWindow = $true
    $psi.RedirectStandardInput = $true; $psi.RedirectStandardOutput = $true; $psi.RedirectStandardError = $true
    try { $enc = [Text.Encoding]::GetEncoding([Globalization.CultureInfo]::CurrentCulture.TextInfo.OEMCodePage); $psi.StandardOutputEncoding = $enc; $psi.StandardErrorEncoding = $enc } catch { }
    $p = New-Object Diagnostics.Process; $p.StartInfo = $psi
    $lines = [System.Collections.Generic.List[string]]::new(); $errs = [System.Collections.Generic.List[string]]::new(); $logs = [System.Collections.Generic.List[string]]::new()
    $res = [ordered]@{ ExitCode = -1; Success = $false; Lines = $lines; Errors = $errs; LogFiles = $logs; Cancelled = $false; TimedOut = $false }
    try { [void]$p.Start() } catch { $errs.Add('wbadmin konnte nicht gestartet werden: ' + $_.Exception.Message); return [pscustomobject]$res }
    try { $p.StandardInput.Close() } catch { }
    $outT = $p.StandardOutput.ReadLineAsync(); $errT = $p.StandardError.ReadLineAsync()
    $sw = [Diagnostics.Stopwatch]::StartNew(); $exitSeen = $null; $lastLogged = @{}
    $span = 100.0; $base0 = 0.0; if ($Script:StepCount -gt 0) { $span = 100.0 / $Script:StepCount; $base0 = ($Script:StepNo - 1) * $span }
    while ($outT -or $errT) {
        $got = $false
        foreach ($which in 'out', 'err') {
            $tk = $(if ($which -eq 'out') { $outT } else { $errT })
            if (-not $tk -or -not $tk.IsCompleted) { continue }
            $got = $true
            $l = $null; try { $l = $tk.Result } catch { }
            if ($null -eq $l) { if ($which -eq 'out') { $outT = $null } else { $errT = $null }; continue }
            if ($which -eq 'out') { $outT = $p.StandardOutput.ReadLineAsync() } else { $errT = $p.StandardError.ReadLineAsync() }
            $pl = ConvertFrom-FbWbadminLine $l
            if ($pl.Kind -eq 'Empty') { continue }
            $lines.Add($pl.Text)
            $ov = Update-FbProgress $State $pl
            switch ($pl.Kind) {
                'Progress' {
                    $Script:Detail = 'Abbild: {0} {1} % (gesamt etwa {2} %)' -f $(if ($pl.Volume) { $pl.Volume } else { 'Laufwerk' }), $pl.Pct, $ov
                    $Script:LastLine = $pl.Text
                    Set-PStatus $Script:StatusText ([int]($base0 + $span * $ov / 100))
                    $key = [string]$pl.Volume; $bucket = [int][math]::Floor([double]$pl.Pct / 25)
                    if (-not $lastLogged.ContainsKey($key) -or $lastLogged[$key] -ne $bucket) { $lastLogged[$key] = $bucket; Write-PLog ('   {0}' -f $pl.Text) }
                }
                'Error'   { $errs.Add($pl.Text); Write-PLog ('   {0}' -f $pl.Text) 'WARN' }
                'Success' { $res.Success = $true; Write-PLog ('   {0}' -f $pl.Text) 'OK' }
                'LogFile' { $logs.Add($pl.Text); Write-PLog ('   Protokoll der Windows-Sicherung: {0}' -f $pl.Text) }
                'Shadow'  { $Script:Detail = 'Schattenkopie der Laufwerke wird erstellt'; Set-PStatus $Script:StatusText; if (-not $lastLogged.ContainsKey('#shadow')) { $lastLogged['#shadow'] = 1; Write-PLog ('   {0}' -f $pl.Text) } }
                default   { if ($pl.Text -notmatch '^(wbadmin \d|\(C\) Copyright|-{3,})') { Write-PLog ('   {0}' -f $pl.Text) } }
            }
        }
        if ($got) { continue }
        $cx = Test-PCancel
        if ($cx -or $sw.Elapsed.TotalMinutes -gt $TimeoutMin) {
            if ($cx) { $res.Cancelled = $true } else { $res.TimedOut = $true }
            Write-PLog ('Komplettsicherung wird {0} - die Windows-Sicherung wird angehalten (wbadmin stop job) ...' -f $(if ($cx) { 'abgebrochen' } else { ('nach {0} Minuten abgebrochen (Zeitlimit)' -f $TimeoutMin) })) 'WARN'
            try { $null = Invoke-FbCmd $exe 'stop job -quiet' 120 } catch { }
            try { & taskkill.exe /PID $p.Id /T /F 2>&1 | Out-Null } catch { }
            break
        }
        Update-PHeartbeat
        if ($p.HasExited) { if (-not $exitSeen) { $exitSeen = [Diagnostics.Stopwatch]::StartNew() } elseif ($exitSeen.Elapsed.TotalSeconds -gt 3) { break } }
        Start-Sleep -Milliseconds 250
    }
    try { [void]$p.WaitForExit(10000) } catch { }
    try { $res.ExitCode = [int]$p.ExitCode } catch { }
    return [pscustomobject]$res
}

# ---- Alte Versionen entfernen
function Invoke-FbPrune([string]$Target, [int]$Keep, [string]$Machine, [string]$NasFolder = 'PC-Tools-Komplettsicherung') {
    $t = ConvertTo-FbTarget $Target
    $k = [math]::Max(1, $Keep)
    $removed = 0
    if ($t.IsNas) {
        $vb = Join-Path (Join-Path $t.Path $NasFolder) $Machine
        if (-not (Test-Path -LiteralPath $vb)) { Write-PLog 'NAS: einzelne Version - es gibt nichts zu entfernen (Windows ersetzt die Sicherung jedes Mal).'; return 0 }
        $dirs = @(Get-ChildItem -LiteralPath $vb -Directory -ErrorAction SilentlyContinue | Where-Object { $_.Name -match '^\d{4}-\d{2}-\d{2}_\d{4}$' } | Sort-Object Name -Descending)
        $good = @($dirs | Where-Object { Test-Path -LiteralPath (Join-Path $_.FullName ('WindowsImageBackup\{0}' -f $Machine)) })
        if (-not $good.Count) { Write-PLog 'NAS: keine vollständige Version gefunden - es wird nichts gelöscht.' 'WARN'; return 0 }
        $keepSet = @($good | Select-Object -First $k | ForEach-Object { $_.FullName })
        $newestGood = $good[0].Name
        foreach ($d in $dirs) {
            if ($keepSet -contains $d.FullName) { continue }
            if ($d.Name -gt $newestGood) { continue }
            Write-PLog ('   Alte Version entfernt: {0}' -f $d.FullName)
            try { Remove-Item -LiteralPath $d.FullName -Recurse -Force -ErrorAction Stop; $removed++ } catch { Write-PLog ('   {0}: {1}' -f $d.Name, $_.Exception.Message) 'WARN' }
        }
        Write-PLog ('Aufbewahrung: {0} Version(en) behalten, {1} entfernt.' -f [math]::Min($k, $good.Count), $removed) 'OK'
        return $removed
    }
    $exe = Get-FbWbadminExe
    $list = { @(ConvertFrom-FbVersions (Invoke-FbCmd $exe ('get versions -backupTarget:{0} -machine:{1}' -f $t.Path, $Machine) 120).Text | ForEach-Object { $_ }) }
    $vers = @(& $list)
    if ($vers.Count -le $k) { Write-PLog ('Aufbewahrung: {0} Version(en) am Ziel, behalten werden bis zu {1} - nichts zu löschen.' -f $vers.Count, $k); return 0 }
    Write-PLog ('Aufbewahrung: {0} Versionen am Ziel, {1} sollen bleiben.' -f $vers.Count, $k)
    $c = Invoke-FbCmd $exe ('delete backup -backupTarget:{0} -machine:{1} -keepVersions:{2} -quiet' -f $t.Path, $Machine, $k) 1800
    $after = @(& $list)
    if ($c.Code -eq 0 -and $after.Count -le $k) { Write-PLog ('   wbadmin delete backup: {0} Version(en) entfernt.' -f ($vers.Count - $after.Count)) 'OK'; return ($vers.Count - $after.Count) }
    Write-PLog ('   "wbadmin delete backup" steht auf diesem Windows nicht zur Verfügung bzw. hat nichts gelöscht ({0}) - ältere Versionen werden über ihre Schattenkopien entfernt.' -f ((([string]$c.Text) -split "`r?`n" | Where-Object { $_.Trim() } | Select-Object -Last 1) -join ''))
    $plan = @(Get-FbRetentionPlan $after $k | ForEach-Object { $_ })
    $sc = @(); try { $sc = @(Get-CimInstance Win32_ShadowCopy -ErrorAction Stop) } catch { Write-PLog ('   Schattenkopien nicht lesbar: {0}' -f $_.Exception.Message) 'WARN'; return 0 }
    foreach ($v in $plan) {
        if (-not $v.SnapshotId) { Write-PLog ('   Version {0}: keine Snapshot-ID - übersprungen.' -f $v.Version) 'WARN'; continue }
        $hit = @($sc | Where-Object { ([string]$_.ID).ToLower() -eq ([string]$v.SnapshotId).ToLower() })
        if (-not $hit.Count) { Write-PLog ('   Version {0}: Schattenkopie {1} nicht gefunden.' -f $v.Version, $v.SnapshotId) 'WARN'; continue }
        try { $hit | Remove-CimInstance -ErrorAction Stop; $removed++; Write-PLog ('   Version {0} ({1:dd.MM.yyyy HH:mm}) entfernt.' -f $v.Version, [datetime]$v.Local) } catch { Write-PLog ('   Version {0}: {1}' -f $v.Version, $_.Exception.Message) 'WARN' }
    }
    Write-PLog ('Aufbewahrung: {0} ältere Version(en) entfernt.' -f $removed) $(if ($removed -eq $plan.Count) { 'OK' } else { 'WARN' })
    return $removed
}
# Notfall-Stick auffrischen (nur aktualisieren, nie formatieren) - nach erfolgreicher Sicherung, wenn eingeschaltet
function Invoke-FbStickRefresh {
    $os = Get-FbOsBuild
    $sticks = @(Find-FbRescueSticks | ForEach-Object { $_ })
    if (-not $sticks.Count) { Write-PLog 'Notfall-Stick: kein Stick "PCT-NOTFALL" eingesteckt - nichts zu tun.'; return 'kein Stick' }
    $out = @()
    foreach ($s in $sticks) {
        $t = Test-FbStickOutdated $s.Stamp $os.Build $os.Install (Get-Date) 0
        if (-not $t.Outdated) { Write-PLog ('Notfall-Stick {0} ist {1}.' -f $s.Root, $t.Reason) 'OK'; $out += 'aktuell'; continue }
        Write-PLog ('Notfall-Stick {0} wird aufgefrischt: {1} (nur Aktualisieren, nichts wird gelöscht)' -f $s.Root, $t.Reason)
        $keep = $Script:JobOpts
        try {
            $hadPf = (-not $s.Stamp) -or (@($s.Stamp.Parts) -contains 'PC-Tools portabel')
            # gleiche Quelle wie beim Erstellen: ISO-Stick bleibt ISO-Stick (startet überall), sonst WinRE dieses PCs
            $src = $(if ($s.Stamp -and [string]$s.Stamp.Source -match '(?i)ISO') { 'Latest' } else { 'WinRe' })
            $Script:JobOpts = [pscustomobject]@{ DiskNumber = [int]$s.DiskNumber; Format = $false; Repair = $true; Source = $src; Iso = ''; Pflege = [bool]$hadPf; WithToken = $false; Toolbox = $false; Drivers = $false }
            Invoke-RsStickJob
            $out += 'aufgefrischt'
        } catch { Write-PLog ('Notfall-Stick auffrischen: {0}' -f $_.Exception.Message) 'WARN'; $out += 'Fehler' }
        finally { $Script:JobOpts = $keep }
    }
    return ($out -join ', ')
}

# ---- Engine-Teil "FullBackup"
function Invoke-FbImageJob {
    $F = $Script:Cfg.FullBackup
    $o = $Script:JobOpts
    $dir = Join-Path $DataDir 'Komplettsicherung'
    New-Item -Path $dir -ItemType Directory -Force -ErrorAction SilentlyContinue | Out-Null
    $credFile = Join-Path $DataDir 'fullbackup.cred'; $altCred = Join-Path $DataDir 'backup.cred'
    $opt = @{ Deep = [bool]$F.DeepVerify; Verify = [bool]$F.Verify; Package = [bool]$F.Package; Stick = [bool]$F.StickRefresh; Keep = [int]$F.Keep }
    if ($o) { foreach ($k in 'Deep', 'Verify', 'Package', 'Stick', 'Keep') { if ($o.PSObject.Properties[$k] -and $null -ne $o.$k) { $opt[$k] = $o.$k } } }
    $start = Get-Date
    $h = [ordered]@{ Id = $start.ToString('yyyyMMdd_HHmmss'); Start = $start.ToString('o'); End = ''; Result = 'Fehler'; Target = [string]$F.Target; Kind = ''; Volumes = ''; Bytes = [int64]0; Estimate = [int64]0
        Minutes = 0; Version = ''; Verify = ''; Message = ''; Codes = @(); Scheduled = [bool]$Script:IsAuto; Log = [string]$Script:LogFile; Package = ''; Stick = ''; Pruned = 0 }
    $Script:FbLastResult = 'Fehler'
    try {
        if (-not (Test-IsAdmin)) { throw 'Die Komplettsicherung braucht Administratorrechte.' }
        $t = ConvertTo-FbTarget ([string]$F.Target)
        if (-not $t.Valid) { throw 'Kein Ziel für die Komplettsicherung eingestellt (Seite Komplettsicherung > Sicherungsziel).' }
        $h.Target = $t.Path; $h.Kind = $(if ($t.IsNas) { 'NAS' } else { 'Festplatte' })
        if (-not (Test-Path -LiteralPath (Get-FbWbadminExe))) { throw 'Die Windows-Sicherung (wbadmin.exe) fehlt auf diesem PC.' }
        $reach = $(if ($t.IsNas) { Connect-FbTarget $t.Path $credFile $altCred } else { [bool](Test-Path -LiteralPath ($t.Path + '\')) })
        if (-not $reach) {
            if ($Script:IsAuto -and $F.SkipIfMissing) {
                $h.Result = 'Übersprungen'; $h.Message = ('Ziel {0} nicht erreichbar (Festplatte nicht angeschlossen / NAS aus).' -f $t.Path)
                Write-PLog ('Komplettsicherung übersprungen: {0}' -f $h.Message) 'WARN'
                return
            }
            throw ('Das Ziel {0} ist nicht erreichbar - Festplatte angeschlossen bzw. NAS eingeschaltet und Zugang gespeichert?' -f $t.Path)
        }
        # Laufwerke und Größe
        $usage = @(Get-FbVolumeUsage | ForEach-Object { $_ })
        $inc = @(([string]$F.Include) -split '[;, ]' | ForEach-Object { $_.Trim().TrimEnd('\').ToUpper() } | Where-Object { $_ -match '^[A-Z]:$' } | Select-Object -Unique)
        $incOk = [System.Collections.Generic.List[string]]::new()
        foreach ($x in $inc) {
            $r = @($usage | Where-Object { $_.Letter -eq $x } | Select-Object -First 1)
            if (-not $r.Count) { Write-PLog ('   Zusätzliches Laufwerk {0} ist nicht vorhanden - übersprungen.' -f $x) 'WARN'; continue }
            if ($x -eq $t.Path) { Write-PLog ('   {0} ist das Ziel und wird nicht mitgesichert.' -f $x) 'WARN'; continue }
            if ([string]$r[0].Fs -notin 'NTFS', 'ReFS') { Write-PLog ('   {0} ({1}) kann die Windows-Sicherung nicht sichern - übersprungen.' -f $x, $r[0].Fs) 'WARN'; continue }
            if ($x -ne ([string]$env:SystemDrive).ToUpper()) { $incOk.Add($x) }
        }
        $est = Measure-FbEstimate $usage @($incOk)
        $h.Estimate = [int64]$est.Bytes; $h.Volumes = (@($est.Names) -join ', ')
        Write-PLog ('Komplettsicherung: {0} -> {1} (geschätzt {2})' -f $h.Volumes, $t.Path, (Format-FbBytes $est.Bytes))
        $info = Get-FbTargetInfo $t.Path $credFile $altCred
        $verdict = @(Get-FbTargetVerdict $info $est.Bytes ([bool]$F.NasVersions) ([int]$F.Keep) @($incOk) | ForEach-Object { $_ })
        foreach ($vr in $verdict) { if ($vr.Level -in 'warn', 'bad') { Write-PLog ('   Ziel: {0}' -f $vr.Text) 'WARN' } }
        $hard = @($verdict | Where-Object { $_.Level -eq 'bad' })
        if ($hard.Count) { throw ('Das Ziel ist nicht geeignet: {0}' -f $hard[0].Text) }
        # wirksames Ziel (NAS mit Versionen: eigener Datumsordner)
        $eff = $t.Path
        if ($t.IsNas -and $F.NasVersions) {
            $eff = Join-Path (Join-Path (Join-Path $t.Path $FbNasFolder) $env:COMPUTERNAME) ($start.ToString('yyyy-MM-dd_HHmm'))
            New-Item -Path $eff -ItemType Directory -Force -ErrorAction Stop | Out-Null
            Write-PLog ('   NAS mit Versionen: Ziel dieser Sicherung {0}' -f $eff)
        }
        $vol = @(([string]$env:SystemDrive).ToUpper()) + @($incOk)
        $a = @('start', 'backup', ('-backupTarget:{0}' -f $(if ($t.IsNas) { '"' + $eff + '"' } else { $eff })), ('-include:{0}' -f ($vol -join ',')), '-allCritical', $(if ([string]$F.Vss -like 'Vollst*') { '-vssFull' } else { '-vssCopy' }), '-quiet')
        $mask = ''
        if ($t.IsNas) { $c = Get-FbCred $credFile $altCred; if ($c -and $c.User) { $a += ('-user:"{0}"' -f $c.User); $a += ('-password:"{0}"' -f $c.Pwd); $mask = [string]$c.Pwd } }
        $state = @{ Weights = @{} }
        foreach ($u in $usage) { if ($u.Critical -or ($u.Letter -and $incOk -contains $u.Letter)) { $nm = $(if ($u.Letter) { $u.Letter } else { switch ($u.Kind) { 'EFI' { 'EFI' } 'Wiederherstellung' { 'Wiederherstellung' } default { 'Reserviert' } } }); $state.Weights[$nm] = [double][math]::Max([double]50MB, [double]$u.Est) } }
        $Script:Detail = 'Windows-Sicherung startet'; Set-PStatus $Script:StatusText
        $r = Invoke-FbWbadmin $a $state 720 $mask
        $h.Codes = @([regex]::Matches(($r.Lines -join "`n"), '0x[0-9A-Fa-f]{8}') | ForEach-Object { '0x' + $_.Value.Substring(2).ToUpper() } | Select-Object -Unique)
        if ($r.Cancelled) { $h.Result = 'Abgebrochen'; $h.Message = 'Vom Benutzer abgebrochen.'; return }
        $ok = ($r.ExitCode -eq 0) -or ($r.Success -and -not $r.Errors.Count)
        if (-not $ok) {
            $h.Message = $(if ($r.TimedOut) { 'Zeitlimit von 12 Stunden überschritten.' } elseif ($r.Errors.Count) { [string]$r.Errors[$r.Errors.Count - 1] } else { 'wbadmin meldet Code {0}.' -f $r.ExitCode })
            Write-PLog ('Komplettsicherung fehlgeschlagen (Code {0}): {1}' -f $r.ExitCode, $h.Message) 'FEHLER'
            if ($eff -ne $t.Path -and -not @(Get-FbImageFolders $eff $env:COMPUTERNAME | ForEach-Object { $_ } | Where-Object { [int64]$_.Bytes -gt 0 }).Count) { try { Remove-Item -LiteralPath $eff -Recurse -Force -ErrorAction Stop; Write-PLog ('   Unvollständiger Versionsordner entfernt: {0}' -f $eff) } catch { } }
            foreach ($e in (Get-FbErrorHelp ($r.Lines -join "`n") $FbErrorCatalog)) { Write-PLog ('   Hilfe - {0}{1}: {2}' -f $e.Title, $(if ($e.Code) { ' (' + $e.Code + ')' } else { '' }), $e.Fix) 'WARN' }
            try { foreach ($ev in @(Get-WinEvent -FilterHashtable @{ LogName = 'Microsoft-Windows-Backup'; StartTime = $start.AddMinutes(-1); Level = 1, 2, 3 } -MaxEvents 5 -ErrorAction Stop)) { Write-PLog ('   Ereignis {0}: {1}' -f $ev.Id, (([string]$ev.Message) -replace '\s+', ' ')) } } catch { }
            return
        }
        $h.Result = 'OK'
        Write-PLog ('Systemabbild erstellt nach {0:N0} Minuten.' -f ((Get-Date) - $start).TotalMinutes) 'OK'
        if ($r.Errors.Count) {
            # Sicherung fertig, aber mit Meldungen (z.B. einzelne Dateien nicht lesbar - "Log of files for which backup failed")
            $h.Result = 'Warnung'; $h.Message = [string]$r.Errors[$r.Errors.Count - 1]
            Write-PLog ('Die Windows-Sicherung meldet {0} Hinweis(e) - Abbild ist da, bitte das Protokoll der Windows-Sicherung ansehen: {1}' -f $r.Errors.Count, (@($r.LogFiles) -join ', ')) 'WARN'
        }
        # Prüfung
        if ($opt.Verify -or $opt.Deep) {
            $Script:Detail = $(if ($opt.Deep) { 'Sicherung wird gründlich geprüft (Abbild einbinden)' } else { 'Sicherung wird geprüft' }); Set-PStatus $Script:StatusText
            $chk = Test-FbBackup $eff $env:COMPUTERNAME $start $est.Bytes -Deep:([bool]$opt.Deep) -MountDir $dir
            foreach ($cr in @($chk.Rows)) { Write-PLog ('   Prüfung - {0}: {1}' -f $cr.Item, $cr.Detail) $(switch ($cr.Level) { 'ok' { 'OK' } 'bad' { 'WARN' } 'warn' { 'WARN' } default { 'INFO' } }) }
            $h.Verify = $chk.Text; $h.Version = $chk.Version; $h.Bytes = [int64]$chk.Bytes
            if (-not $chk.Ok) { $h.Result = 'Warnung'; $h.Message = 'Die Prüfung nach der Sicherung hat Fehler gefunden.' }
        } else {
            $fo = @(Get-FbImageFolders $(if ($t.IsNas) { $eff } else { $eff + '\' }) $env:COMPUTERNAME | ForEach-Object { $_ } | Select-Object -First 1)
            if ($fo.Count) { $h.Bytes = [int64]$fo[0].Bytes }
            $h.Verify = 'nicht geprüft'
        }
        # Aufbewahrung
        if (([int]$opt.Keep -gt 0) -and ([string]$h.Result -in @('OK', 'Warnung')) -and ($h.Verify -ne 'Prüfung fehlgeschlagen')) {
            $Script:Detail = 'Alte Versionen aufräumen'; Set-PStatus $Script:StatusText
            try { $h.Pruned = [int](Invoke-FbPrune $t.Path ([int]$opt.Keep) $env:COMPUTERNAME $FbNasFolder) } catch { Write-PLog ('Aufbewahrung: {0}' -f $_.Exception.Message) 'WARN' }
        }
        # Wiederherstellungspaket
        if ($opt.Package) {
            $Script:Detail = 'Wiederherstellungspaket am Ziel'; Set-PStatus $Script:StatusText
            try {
                $pr = Get-FbPackageRoot $t.Path $env:COMPUTERNAME $FbPkgFolder
                $null = Write-FbPackage $pr $(if ([string]$F.PkgSource -like '*ISO*') { 'ISO' } else { 'WinRE' }) $(if ($t.IsNas) { $eff } else { $t.Path + '\WindowsImageBackup\' + $env:COMPUTERNAME })
                $h.Package = 'aktuell'
            } catch { $h.Package = 'Fehler'; Write-PLog ('Wiederherstellungspaket: {0}' -f $_.Exception.Message) 'WARN' }
        }
        # Notfall-Stick nur nach der geplanten Sicherung (oder auf ausdrücklichen Wunsch) und nur aktualisieren, nie formatieren
        if ($opt.Stick -and ($Script:IsAuto -or ($o -and $o.PSObject.Properties['Stick'] -and $o.Stick))) { try { $h.Stick = Invoke-FbStickRefresh } catch { $h.Stick = 'Fehler'; Write-PLog ('Notfall-Stick: {0}' -f $_.Exception.Message) 'WARN' } }
    } catch {
        $h.Result = 'Fehler'; $h.Message = $_.Exception.Message
        Write-PLog ('Komplettsicherung: {0}' -f $_.Exception.Message) 'FEHLER'
    } finally {
        $end = Get-Date
        $h.End = $end.ToString('o'); $h.Minutes = [math]::Round(($end - $start).TotalMinutes, 1)
        $Script:FbLastResult = [string]$h.Result
        try { Add-FbHistory $dir $h } catch { Write-PLog ('Verlauf der Komplettsicherung: {0}' -f $_.Exception.Message) 'WARN' }
        try {
            $sz = $(if ([int64]$h.Bytes -gt 0) { Format-FbBytes $h.Bytes } else { '-' })
            switch ([string]$h.Result) {
                'OK'           { if ($F.NotifyOk) { $null = Send-PflegeNotify 'Komplettsicherung erfolgreich' ('{0}, {1} Min., Ziel {2}, {3}.' -f $sz, $h.Minutes, $h.Target, $h.Verify) 'Green' } }
                'Warnung'      { if ($F.NotifyFail) { $null = Send-PflegeNotify 'Komplettsicherung mit Warnung' ('{0} - {1}' -f $h.Message, $h.Target) 'Yellow' } }
                'Übersprungen' { if ($F.NotifyFail) { $null = Send-PflegeNotify 'Komplettsicherung übersprungen' $h.Message 'Yellow' } }
                'Abgebrochen'  { }
                default        { if ($F.NotifyFail) { $null = Send-PflegeNotify 'Komplettsicherung fehlgeschlagen' ('{0} Details: PC-Tools > Komplettsicherung > Verlauf.' -f $h.Message) 'Red' } }
            }
        } catch { }
        if ($F.Shutdown -and $Script:IsAuto -and [string]$h.Result -in 'OK', 'Warnung') { Write-PLog 'PC wird in 3 Minuten heruntergefahren (Einstellung der Komplettsicherung).'; & shutdown.exe /s /t 180 /c 'PC-Tools: Komplettsicherung fertig - PC wird heruntergefahren (abbrechen: shutdown /a)' | Out-Null }
    }
}
# Engine-Teil "FullBackupPrune" (Optionen: Keep)
function Invoke-FbPruneJob {
    $F = $Script:Cfg.FullBackup; $o = $Script:JobOpts
    $k = [int]$F.Keep; if ($o -and $o.PSObject.Properties['Keep'] -and [int]$o.Keep -gt 0) { $k = [int]$o.Keep }
    $t = ConvertTo-FbTarget ([string]$F.Target)
    if (-not $t.Valid) { throw 'Kein Ziel eingestellt.' }
    if ($t.IsNas) { $null = Connect-FbTarget $t.Path (Join-Path $DataDir 'fullbackup.cred') (Join-Path $DataDir 'backup.cred') }
    $null = Invoke-FbPrune $t.Path $k $env:COMPUTERNAME $FbNasFolder
}
# Engine-Teil "FullBackupPackage" (Optionen: Force, Source = WinRE|ISO)
function Invoke-FbPackageJob {
    $F = $Script:Cfg.FullBackup; $o = $Script:JobOpts
    $t = ConvertTo-FbTarget ([string]$F.Target)
    if (-not $t.Valid) { throw 'Kein Ziel eingestellt.' }
    if ($t.IsNas) { if (-not (Connect-FbTarget $t.Path (Join-Path $DataDir 'fullbackup.cred') (Join-Path $DataDir 'backup.cred'))) { throw ('{0} ist nicht erreichbar.' -f $t.Path) } }
    elseif (-not (Test-Path -LiteralPath ($t.Path + '\'))) { throw ('{0} ist nicht angeschlossen.' -f $t.Path) }
    $src = $(if ($o -and $o.Source) { [string]$o.Source } elseif ([string]$F.PkgSource -like '*ISO*') { 'ISO' } else { 'WinRE' })
    $img = $(if ($t.IsNas) { $(if ($F.NasVersions) { Join-Path (Join-Path $t.Path $FbNasFolder) $env:COMPUTERNAME } else { $t.Path }) } else { $t.Path + '\WindowsImageBackup\' + $env:COMPUTERNAME })
    $null = Write-FbPackage (Get-FbPackageRoot $t.Path $env:COMPUTERNAME $FbPkgFolder) $src $img -Force:([bool]($o -and $o.Force))
}
# Engine-Teil "FullBackupVerify" (Optionen: Deep)
function Invoke-FbVerifyJob {
    $F = $Script:Cfg.FullBackup; $o = $Script:JobOpts
    $t = ConvertTo-FbTarget ([string]$F.Target)
    if (-not $t.Valid) { throw 'Kein Ziel eingestellt.' }
    $dir = Join-Path $DataDir 'Komplettsicherung'
    if ($t.IsNas) { $null = Connect-FbTarget $t.Path (Join-Path $DataDir 'fullbackup.cred') (Join-Path $DataDir 'backup.cred') }
    $eff = $t.Path
    if ($t.IsNas -and $F.NasVersions) { $fo = @(Get-FbImageFolders $t.Path $env:COMPUTERNAME $FbNasFolder | ForEach-Object { $_ } | Select-Object -First 1); if ($fo.Count) { $eff = $fo[0].Root } }
    $usage = @(Get-FbVolumeUsage | ForEach-Object { $_ }); $est = Measure-FbEstimate $usage @(([string]$F.Include) -split '[;, ]')
    $Script:Detail = 'Neueste Sicherung wird geprüft'; Set-PStatus $Script:StatusText
    $chk = Test-FbBackup $eff $env:COMPUTERNAME ([datetime]::MinValue) $est.Bytes -Deep:([bool]($o -and $o.Deep)) -MountDir $dir
    foreach ($cr in @($chk.Rows)) { Write-PLog ('   {0}: {1}' -f $cr.Item, $cr.Detail) $(switch ($cr.Level) { 'ok' { 'OK' } 'bad' { 'WARN' } 'warn' { 'WARN' } default { 'INFO' } }) }
    Write-PLog ('Prüfung der Komplettsicherung: {0}' -f $chk.Text) $(if ($chk.Ok -and -not $chk.Warn) { 'OK' } else { 'WARN' })
    try { $chk | Select-Object Ok, Warn, Text, Version, Bytes, Vhdx, @{ n = 'Time'; e = { (Get-Date).ToString('o') } }, @{ n = 'Deep'; e = { [bool]($o -and $o.Deep) } }, Rows | ConvertTo-Json -Depth 4 | Set-Content -LiteralPath (Join-Path $dir 'verify_last.json') -Encoding UTF8 } catch { }
}

# ---- Alles für die Statuskarte der Oberfläche in einem Rutsch (läuft in Invoke-Bg - Funktionen siehe $FbBgFunctions)
function Get-FbStatusData([hashtable]$P) {
    $r = [ordered]@{ Target = $null; Usage = @(); Estimate = $null; Verdict = @(); Versions = $null; Package = $null; Sticks = @(); History = @(); Summary = $null; Task = $null; Os = $null; Errors = @() }
    $errs = [System.Collections.Generic.List[string]]::new()
    try { $r.Os = Get-FbOsBuild } catch { $errs.Add('Windows-Version: ' + $_.Exception.Message) }
    try { $r.Usage = @(Get-FbVolumeUsage | ForEach-Object { $_ }) } catch { $errs.Add('Laufwerke: ' + $_.Exception.Message) }
    $inc = @(([string]$P.Include) -split '[;, ]' | Where-Object { $_ })
    try { $r.Estimate = Measure-FbEstimate $r.Usage $inc } catch { }
    try { $r.Target = Get-FbTargetInfo ([string]$P.Target) ([string]$P.CredFile) ([string]$P.AltCredFile) } catch { $errs.Add('Ziel: ' + $_.Exception.Message) }
    try { $r.Verdict = @(Get-FbTargetVerdict $r.Target $(if ($r.Estimate) { [int64]$r.Estimate.Bytes } else { [int64]0 }) ([bool]$P.NasVersions) ([int]$P.Keep) $inc | ForEach-Object { $_ }) } catch { }
    if ($P.WithVersions -and $r.Target -and $r.Target.Exists) {
        try { $r.Versions = Get-FbVersions ([string]$P.Target) ([string]$P.Machine) ([string]$P.CredFile) ([string]$P.AltCredFile) ([string]$P.NasFolder) } catch { $errs.Add('Versionen: ' + $_.Exception.Message) }
    }
    if ($r.Target -and $r.Target.Exists) {
        try { $r.Package = Get-FbPackageState (Get-FbPackageRoot ([string]$P.Target) ([string]$P.Machine) ([string]$P.PkgFolder)) $(if ($r.Os) { [string]$r.Os.Text } else { '' }) } catch { }
    }
    try { $r.Sticks = @(Get-FbStickState | ForEach-Object { $_ }) } catch { }
    try { $r.History = @(Get-FbHistory ([string]$P.HistDir) | ForEach-Object { $_ }); $r.Summary = Get-FbSummary $r.History ([int]$P.IntervalDays) } catch { $errs.Add('Verlauf: ' + $_.Exception.Message) }
    try {
        $tk = Get-ScheduledTask -TaskName ([string]$P.TaskName) -ErrorAction Stop
        $ti = Get-ScheduledTaskInfo -TaskName ([string]$P.TaskName) -ErrorAction Stop
        $r.Task = [pscustomobject]@{ State = [string]$tk.State; Next = $(if ($ti.NextRunTime -and $ti.NextRunTime.Year -gt 2000) { [datetime]$ti.NextRunTime } else { $null }); Last = $(if ($ti.LastRunTime -and $ti.LastRunTime.Year -gt 2000) { [datetime]$ti.LastRunTime } else { $null }); LastResult = [int64]$ti.LastTaskResult }
    } catch { }
    $r.Errors = @($errs)
    return [pscustomobject]$r
}
# Funktionen, die Get-FbStatusData (und die Prüfung/Einbindung aus der Oberfläche) im Hintergrund-Runspace brauchen
$FbBgFunctions = @('Get-FbStatusData', 'Get-FbOsBuild', 'Get-FbVolumeUsage', 'Measure-FbEstimate', 'Get-FbTargetInfo', 'Get-FbTargetVerdict', 'ConvertTo-FbTarget', 'Connect-FbTarget', 'Get-FbCred',
    'Format-FbBytes', 'Get-FbVersions', 'Invoke-FbCmd', 'Get-FbWbadminExe', 'ConvertFrom-FbVersions', 'Get-FbImageFolders', 'Merge-FbVersionRows', 'Get-FbPackageRoot', 'Get-FbPackageState',
    'Get-FbStickState', 'Find-FbRescueSticks', 'Test-FbStickOutdated', 'Get-FbHistory', 'Get-FbSummary', 'ConvertTo-FbDate', 'Mount-FbVhd', 'Dismount-FbVhd', 'Test-FbBackup')
# =====================================================================
#  PC-REINIGER (Cc): Benutzerdefinierte Reinigung (Windows, Browser, Anwendungen, Windows-Extras),
#  Registry-Reinigung (nur verwaiste Einträge, immer mit .reg-Sicherung), Programme deinstallieren
#  (mit Restesuche), Browser-Erweiterungen und Startseiten-Prüfung, Kontextmenü-Manager,
#  geplante Aufgaben anderer Hersteller, freien Speicher sicher löschen (cipher /w).
#  Engine-Teile: CleanerRun (Invoke-CcCleanJob), CleanerWipe (Invoke-CcWipeJob)
#  Alle Hilfsfunktionen laufen ohne Skript-Variablen und sind deshalb auch in Invoke-Bg nutzbar
#  (Liste: $CcBgFunctions). Gespeicherte Kennwörter werden NIE gelesen oder gelöscht.
# =====================================================================
$CcStateFile     = Join-Path $DataDir 'pc-reiniger.json'
$CcRegBackupRoot = Join-Path $DataDir 'Registry-Sicherung'
$CcTaskBackupDir = Join-Path $DataDir 'Aufgaben-Sicherung'

# ---- Browser (Chromium-Familie und Firefox); Pfad-Kürzel: L = AppData\Local, R = AppData\Roaming, LL = AppData\LocalLow, P = Benutzerordner
function Get-CcBrowserDefs {
    @(
        @{ Key = 'Edge';    Name = 'Microsoft Edge';  Kind = 'Chromium'; Root = 'L:\Microsoft\Edge\User Data';              CacheRoot = '';                                Proc = @('msedge');  Policy = 'Microsoft\Edge';         DefSearch = 'Bing' }
        @{ Key = 'Chrome';  Name = 'Google Chrome';   Kind = 'Chromium'; Root = 'L:\Google\Chrome\User Data';               CacheRoot = '';                                Proc = @('chrome');  Policy = 'Google\Chrome';          DefSearch = 'Google' }
        @{ Key = 'Brave';   Name = 'Brave';           Kind = 'Chromium'; Root = 'L:\BraveSoftware\Brave-Browser\User Data'; CacheRoot = '';                                Proc = @('brave');   Policy = 'BraveSoftware\Brave';    DefSearch = 'Brave Search' }
        @{ Key = 'Vivaldi'; Name = 'Vivaldi';         Kind = 'Chromium'; Root = 'L:\Vivaldi\User Data';                     CacheRoot = '';                                Proc = @('vivaldi'); Policy = '';                       DefSearch = 'Standard' }
        @{ Key = 'Opera';   Name = 'Opera';           Kind = 'Chromium'; Root = 'R:\Opera Software\Opera Stable';           CacheRoot = 'L:\Opera Software\Opera Stable';    Proc = @('opera');   Policy = '';                       DefSearch = 'Google' }
        @{ Key = 'OperaGX'; Name = 'Opera GX';        Kind = 'Chromium'; Root = 'R:\Opera Software\Opera GX Stable';        CacheRoot = 'L:\Opera Software\Opera GX Stable'; Proc = @('opera');   Policy = '';                       DefSearch = 'Google' }
        @{ Key = 'Firefox'; Name = 'Mozilla Firefox'; Kind = 'Firefox';  Root = 'R:\Mozilla\Firefox\Profiles';              CacheRoot = 'L:\Mozilla\Firefox\Profiles';       Proc = @('firefox'); Policy = 'Mozilla\Firefox';        DefSearch = 'Google' }
    )
}

# ---- Katalog aller Reinigungs-Elemente
#  Def = in "Sicher" (Standard) an, Deep = zusätzlich in "Gründlich", Priv = Datenschutz-relevant (nur im Profil "Datenschutz")
#  Paths: 'Pfad|Filter|Rekursiv(1/0)', Kürzel L: R: LL: P: (je Benutzer), W: (Windows), PD: (ProgramData), STEAM: (Steam-Ordner), ALLDRIVES: (alle festen Laufwerke)
#  Days: Mindestalter in Tagen oder 'Cfg:<Schlüssel>' (aus den Aufräumen-Einstellungen)
#  Fn: vorhandene Aufräumen-Funktion, die in der Engine genutzt wird (Pfade dienen dann nur der Analyse)
function Get-CcCatalog {
    $c = [System.Collections.Generic.List[object]]::new()
    $add = { param($h) $c.Add($h) }
    # ---------------------------------------------------------------- Windows (wie die Seite Aufräumen)
    & $add @{ Id = 'Win.UserTemp'; Group = 'Windows'; Sub = 'Windows'; Def = $true; Title = 'Temporäre Dateien der Benutzer'
              Desc = 'AppData\Local\Temp aller Benutzerkonten. Es werden nur Dateien entfernt, die älter sind als auf der Seite Aufräumen eingestellt; gerade benutzte Dateien überspringt PC-Tools automatisch.'
              Paths = @('L:\Temp'); Days = 'Cfg:UserTempDays'; Fn = 'Clear-UserTemp' }
    & $add @{ Id = 'Win.WinTemp'; Group = 'Windows'; Sub = 'Windows'; Def = $true; Title = 'Temporäre Dateien von Windows'
              Desc = 'C:\Windows\Temp - Reste von Installationen und Windows-Diensten.'
              Paths = @('W:\Temp'); Days = 'Cfg:WinTempDays'; Fn = 'Clear-WinTemp' }
    & $add @{ Id = 'Win.Recycle'; Group = 'Windows'; Sub = 'Windows'; Def = $true; Title = 'Papierkorb (alle Laufwerke und Benutzer)'
              Desc = 'Nur Elemente, die schon länger im Papierkorb liegen (Einstellung auf der Seite Aufräumen). Danach sind diese Dateien endgültig weg.'
              Paths = @('ALLDRIVES:\$Recycle.Bin'); Days = 'Cfg:RecycleBinDays'; Fn = 'Clear-RecycleBins' }
    & $add @{ Id = 'Win.Thumbs'; Group = 'Windows'; Sub = 'Windows'; Def = $true; Title = 'Miniaturansichten-Cache'
              Desc = 'Vorschaubilder im Explorer (thumbcache_*.db). Windows erstellt sie beim nächsten Öffnen eines Ordners neu.'
              Paths = @('L:\Microsoft\Windows\Explorer|thumbcache_*.db|0'); Fn = 'Clear-ThumbCache' }
    & $add @{ Id = 'Win.WER'; Group = 'Windows'; Sub = 'Windows'; Def = $true; Title = 'Windows-Fehlerberichte'
              Desc = 'Gesammelte Absturzberichte, die an Microsoft gesendet wurden oder warten. Für die eigene Fehlersuche gibt es die Seite Fehlerdaten.'
              Paths = @('PD:\Microsoft\Windows\WER\ReportArchive', 'PD:\Microsoft\Windows\WER\ReportQueue', 'PD:\Microsoft\Windows\WER\Temp', 'L:\Microsoft\Windows\WER'); Days = 'Cfg:WERDays'; Fn = 'Clear-ErrorReports' }
    & $add @{ Id = 'Win.WUCache'; Group = 'Windows'; Sub = 'Windows'; Def = $true; Title = 'Windows-Update-Downloadcache'
              Desc = 'Bereits installierte Update-Pakete (SoftwareDistribution\Download). Wird übersprungen, solange ein Neustart aussteht.'
              Paths = @('W:\SoftwareDistribution\Download'); Fn = 'Clear-WUCache' }
    & $add @{ Id = 'Win.DeliveryOpt'; Group = 'Windows'; Sub = 'Windows'; Def = $true; Title = 'Übermittlungsoptimierung'
              Desc = 'Zwischenspeicher, mit dem Windows Updates an andere PCs im Netz weitergibt.'
              Paths = @('W:\ServiceProfiles\NetworkService\AppData\Local\Microsoft\Windows\DeliveryOptimization\Cache'); Fn = 'Clear-DeliveryOpt' }

    # ---------------------------------------------------------------- Browser (alle Profile aller Benutzer)
    $what = @(
        @{ W = 'Cache';     Def = $true;  Priv = $false; Title = 'Cache (zwischengespeicherte Webseiten)'; Desc = 'Bilder, Skripte und Seiten, die der Browser zwischenspeichert. Wird beim Surfen neu geladen - Webseiten öffnen danach beim ersten Mal etwas langsamer.' }
        @{ W = 'Code';      Def = $true;  Priv = $false; Title = 'Code-, GPU-, Shader- und Service-Worker-Cache'; Desc = 'Vorübersetzte Skripte, Grafik-Shader und Offline-Speicher von Web-Apps (Service Worker). Wird automatisch neu aufgebaut.' }
        @{ W = 'Downloads'; Def = $true;  Priv = $false; Title = 'Download-Verlauf'; Desc = 'Nur die Liste der Downloads im Browser - die heruntergeladenen Dateien selbst bleiben im Ordner Downloads.' }
        @{ W = 'History';   Def = $false; Priv = $true;  Title = 'Browserverlauf (besuchte Seiten)'; Desc = 'Besuchte Seiten, häufig besuchte Seiten und Vorschläge in der Adresszeile. Lesezeichen/Favoriten bleiben erhalten.' }
        @{ W = 'Cookies';   Def = $false; Priv = $true;  Title = 'Cookies (Anmeldungen) - außer Ausnahmeliste'; Desc = 'Danach sind Sie auf Webseiten abgemeldet. Domains in der Ausnahmeliste (oben) bleiben angemeldet. Gespeicherte Kennwörter bleiben immer erhalten.' }
        @{ W = 'Session';   Def = $false; Priv = $true;  Title = 'Letzte Sitzung (offene Tabs)'; Desc = 'Die Liste der zuletzt geöffneten Tabs und Fenster. Ist "Beim Start dort weitermachen, wo ich aufgehört habe" eingestellt, startet der Browser danach mit einer leeren Seite.' }
        @{ W = 'Autofill';  Def = $false; Priv = $true;  Title = 'Formulardaten (Autofill-Einträge)'; Desc = 'Gemerkte Eingaben in Formularfeldern (Namen, Suchbegriffe, Adressfelder). Gespeicherte Kennwörter, Adressen-Profile und Zahlungsdaten werden NICHT angefasst.' }
    )
    foreach ($b in (Get-CcBrowserDefs)) {
        foreach ($w in $what) {
            & $add @{ Id = ('Brw.{0}.{1}' -f $b.Key, $w.W); Group = 'Browser'; Sub = $b.Name; Def = $w.Def; Priv = $w.Priv; Title = $w.Title; Desc = $w.Desc
                      Kind = 'Browser'; Browser = $b.Key; What = $w.W; Proc = $b.Proc }
        }
    }

    # ---------------------------------------------------------------- Anwendungen
    & $add @{ Id = 'App.OfficeCache'; Group = 'Anwendungen'; Sub = 'Microsoft Office'; Def = $true; Title = 'Office: Add-in- und Webdienst-Cache, Telemetrie'
              Desc = 'Zwischenspeicher der Office-Add-ins (Wef), Webdienst-Cache und Telemetrie-Daten. Der Upload-Cache für OneDrive/SharePoint wird bewusst NICHT angefasst (dort können noch nicht hochgeladene Dokumente liegen).'
              Paths = @('L:\Microsoft\Office\16.0\Wef', 'L:\Microsoft\Office\16.0\WebServiceCache', 'L:\Microsoft\Office\OTele'); Proc = @('winword', 'excel', 'powerpnt', 'outlook', 'onenote', 'msaccess', 'mspub', 'visio') }
    & $add @{ Id = 'App.OfficeMru'; Group = 'Anwendungen'; Sub = 'Microsoft Office'; Priv = $true; Title = 'Office: zuletzt verwendete Dateien'
              Desc = 'Die Listen "Zuletzt verwendet" in Word, Excel, PowerPoint & Co. (Registry und Verknüpfungen). Angeheftete Dateien verschwinden ebenfalls aus der Liste - die Dokumente selbst bleiben.'
              Paths = @('R:\Microsoft\Office\Recent|*.lnk|0'); RegKeys = @('Software\Microsoft\Office\*\*\File MRU', 'Software\Microsoft\Office\*\*\Place MRU', 'Software\Microsoft\Office\*\*\User MRU\*\File MRU', 'Software\Microsoft\Office\*\*\User MRU\*\Place MRU')
              Proc = @('winword', 'excel', 'powerpnt', 'msaccess', 'mspub', 'visio') }
    & $add @{ Id = 'App.TeamsClassic'; Group = 'Anwendungen'; Sub = 'Microsoft Teams'; Def = $true; Title = 'Teams (klassisch): Cache'
              Desc = 'Cache, GPU-Cache, Blob-Speicher und Temp-Dateien des klassischen Teams. Chats und Anmeldung bleiben erhalten (liegen auf dem Server bzw. in anderen Ordnern).'
              Paths = @('R:\Microsoft\Teams\Cache', 'R:\Microsoft\Teams\Code Cache', 'R:\Microsoft\Teams\GPUCache', 'R:\Microsoft\Teams\blob_storage', 'R:\Microsoft\Teams\tmp', 'R:\Microsoft\Teams\Service Worker\CacheStorage'); Proc = @('teams') }
    & $add @{ Id = 'App.TeamsNew'; Group = 'Anwendungen'; Sub = 'Microsoft Teams'; Def = $true; Title = 'Teams (neu): Cache und Protokolle'
              Desc = 'Web-Cache (WebView2) und Protokolle des neuen Teams. Hilft auch bei hängenden Chats oder fehlenden Bildern.'
              Paths = @('L:\Packages\MSTeams_8wekyb3d8bbwe\LocalCache\Microsoft\MSTeams\EBWebView\*\Cache', 'L:\Packages\MSTeams_8wekyb3d8bbwe\LocalCache\Microsoft\MSTeams\EBWebView\*\Code Cache', 'L:\Packages\MSTeams_8wekyb3d8bbwe\LocalCache\Microsoft\MSTeams\EBWebView\*\GPUCache', 'L:\Packages\MSTeams_8wekyb3d8bbwe\LocalCache\Microsoft\MSTeams\Logs'); Proc = @('ms-teams') }
    & $add @{ Id = 'App.Discord'; Group = 'Anwendungen'; Sub = 'Discord'; Def = $true; Title = 'Discord: Cache'
              Desc = 'Bilder, Videos und Skripte, die Discord zwischenspeichert - kann mehrere GB groß werden. Nachrichten bleiben auf dem Server.'
              Paths = @('R:\discord\Cache', 'R:\discord\Code Cache', 'R:\discord\GPUCache', 'R:\discord\DawnCache'); Proc = @('discord') }
