              Paths = @('L:\Spotify\Data', 'L:\Spotify\Browser\Cache', 'L:\Spotify\Browser\GPUCache', 'L:\Packages\SpotifyAB.SpotifyMusic_zpdnekdrzrea0\LocalCache\Spotify\Data'); Proc = @('spotify') }
