              Desc = 'Cache des Steam-Shops und der Bibliothek, Protokolle und Dumps. Spiele und Spielstände bleiben unberührt.'
              Paths = @('STEAM:\appcache\httpcache', 'L:\Steam\htmlcache', 'STEAM:\logs', 'STEAM:\dumps'); Proc = @('steam', 'steamwebhelper') }
