              Desc = 'Nur der Zwischenspeicher der Oberfläche - Chats, Fotos und empfangene Medien bleiben erhalten.'
              Paths = @('L:\Packages\5319275A.WhatsAppDesktop_cv1g1gvanyjgm\LocalCache\Roaming\WhatsApp\Cache', 'L:\Packages\5319275A.WhatsAppDesktop_cv1g1gvanyjgm\LocalCache\Roaming\WhatsApp\Code Cache', 'L:\Packages\5319275A.WhatsAppDesktop_cv1g1gvanyjgm\LocalCache\Roaming\WhatsApp\GPUCache', 'L:\Packages\5319275A.WhatsAppDesktop_cv1g1gvanyjgm\LocalState\EBWebView\*\Cache', 'L:\Packages\5319275A.WhatsAppDesktop_cv1g1gvanyjgm\LocalState\EBWebView\*\Code Cache', 'L:\Packages\5319275A.WhatsAppDesktop_cv1g1gvanyjgm\LocalState\EBWebView\*\GPUCache', 'R:\WhatsApp\Cache', 'R:\WhatsApp\Code Cache', 'R:\WhatsApp\GPUCache'); Proc = @('whatsapp', 'whatsapp.root') }
    & $add @{ Id = 'App.OneDriveLogs'; Group = 'Anwendungen'; Sub = 'Kommunikation'; Def = $true; Title = 'OneDrive: Protokolle'
