              Paths = @('L:\Microsoft\OneDrive\logs', 'L:\Microsoft\OneDrive\setup\logs') }

    # ---------------------------------------------------------------- Windows-Extras
    & $add @{ Id = 'Ext.Recent'; Group = 'Windows-Extras'; Sub = 'Datenschutz'; Priv = $true; Title = 'Zuletzt verwendete Dokumente und Sprunglisten'
              Desc = 'Die Liste "Zuletzt verwendet" im Explorer und Startmenü sowie die Sprunglisten der Taskleiste (Rechtsklick auf ein Programm). Angeheftete Einträge in Sprunglisten verschwinden dabei ebenfalls.'
              Paths = @('R:\Microsoft\Windows\Recent|*.lnk|0', 'R:\Microsoft\Windows\Recent\AutomaticDestinations', 'R:\Microsoft\Windows\Recent\CustomDestinations') }
    & $add @{ Id = 'Ext.ExplorerMru'; Group = 'Windows-Extras'; Sub = 'Datenschutz'; Priv = $true; Title = 'Explorer-Verlauf (Pfade, Ausführen, Suche, Öffnen/Speichern)'
              Desc = 'Eingetippte Pfade in der Adresszeile, Verlauf von Win+R (Ausführen), Suchbegriffe im Explorer und die Listen der Öffnen-/Speichern-Dialoge. Wird für angemeldete Benutzer in deren Registry gelöscht.'
              RegKeys = @('Software\Microsoft\Windows\CurrentVersion\Explorer\RecentDocs', 'Software\Microsoft\Windows\CurrentVersion\Explorer\RunMRU', 'Software\Microsoft\Windows\CurrentVersion\Explorer\TypedPaths', 'Software\Microsoft\Windows\CurrentVersion\Explorer\WordWheelQuery', 'Software\Microsoft\Windows\CurrentVersion\Explorer\ComDlg32\OpenSavePidlMRU', 'Software\Microsoft\Windows\CurrentVersion\Explorer\ComDlg32\LastVisitedPidlMRU') }
    & $add @{ Id = 'Ext.Clipboard'; Group = 'Windows-Extras'; Sub = 'Datenschutz'; Priv = $true; Kind = 'Special'; Title = 'Zwischenablage-Verlauf (Win+V)'
              Desc = 'Der Verlauf der Zwischenablage. Angeheftete Einträge bleiben erhalten. Funktioniert nur in der Sitzung des angemeldeten Benutzers (nicht bei der nächtlichen Pflege als SYSTEM).' }
    & $add @{ Id = 'Ext.Dns'; Group = 'Windows-Extras'; Sub = 'System'; Def = $true; Kind = 'Special'; Title = 'DNS-Cache'
              Desc = 'Zwischengespeicherte Namensauflösungen (ipconfig /flushdns). Hilft, wenn eine Webseite nach einem Umzug nicht erreichbar ist. Wird sofort automatisch neu gefüllt.' }
    & $add @{ Id = 'Ext.FontCache'; Group = 'Windows-Extras'; Sub = 'System'; Kind = 'Special'; Title = 'Schriftarten-Cache'
              Desc = 'Nur bei Problemen nötig (falsch dargestellte oder fehlende Schriften). Der Dienst "Windows-Schriftartencache" wird kurz angehalten; vollständig wirksam nach einem Neustart.' }
    & $add @{ Id = 'Ext.Dumps'; Group = 'Windows-Extras'; Sub = 'System'; Deep = $true; Title = 'Speicherabbilder (alle, auch neue)'
              Desc = 'MEMORY.DMP, Minidumps, Live-Kernel-Berichte und Absturzabbilder der Programme - oft mehrere GB. Werden zur Analyse von Bluescreens gebraucht (Seite Fehlerdaten): erst löschen, wenn das Problem gelöst ist.'
              Paths = @('W:\|MEMORY.DMP|0', 'W:\Minidump', 'W:\LiveKernelReports|*.dmp|1', 'L:\CrashDumps') }
    & $add @{ Id = 'Ext.WinLogs'; Group = 'Windows-Extras'; Sub = 'System'; Def = $true; Title = 'Alte Windows-Protokolle'
              Desc = 'Alte CBS-, DISM- und Windows-Update-Protokolle (Alter wie auf der Seite Aufräumen). Setup- und Upgrade-Protokolle bleiben für Fehleranalysen erhalten.'
              Paths = @('W:\Logs\CBS|*.log|0', 'W:\Logs\CBS|*.cab|0', 'W:\Logs\DISM|*.log|0', 'W:\Logs\WindowsUpdate|*.etl|0', 'W:\Logs\NetSetup|*|0', 'W:\Logs\SIH|*|0'); Days = 'Cfg:OldLogsDays'; Fn = 'Clear-OldLogs' }
    & $add @{ Id = 'Ext.Prefetch'; Group = 'Windows-Extras'; Sub = 'System'; Title = 'Prefetch-Daten (nicht empfohlen)'
              Desc = 'Windows merkt sich hier, welche Dateien ein Programm beim Start braucht, und lädt sie beim nächsten Mal vorab - das beschleunigt Programmstarts. Windows begrenzt den Ordner selbst. Löschen macht die nächsten Starts LANGSAMER und ist nur aus Datenschutzgründen (Prefetch verrät, welche Programme liefen) oder zur Fehlersuche sinnvoll.'
              Paths = @('W:\Prefetch|*.pf|0') }
    & $add @{ Id = 'Ext.IconCache'; Group = 'Windows-Extras'; Sub = 'System'; Title = 'Symbol-Cache (IconCache)'
              Desc = 'Nur bei falschen oder leeren Programmsymbolen. Der Explorer hält einen Teil der Dateien offen - für einen vollständigen Neuaufbau besser Seite Windows-Reparatur, "Symbol- und Miniaturansichten-Cache neu" (startet den Explorer neu).'
              Paths = @('L:|IconCache.db|0', 'L:\Microsoft\Windows\Explorer|iconcache_*.db|0') }

    foreach ($x in $c) {
        foreach ($k in 'Def', 'Deep', 'Priv') { if (-not $x.ContainsKey($k)) { $x[$k] = $false } }
        if (-not $x.ContainsKey('Kind')) { $x['Kind'] = 'Files' }
        if (-not $x.ContainsKey('Proc')) { $x['Proc'] = @() }
    }
    return , $c
}
function Get-CcGroupInfo {
    [ordered]@{
        'Windows'        = @{ Glyph = '&#xE7F8;'; Color = '#2D7FF9'; Text = 'Windows-Grundreinigung - dieselben Bereiche wie auf der Seite Aufräumen, mit deren Alters-Einstellungen.' }
        'Browser'        = @{ Glyph = '&#xE774;'; Color = '#0891B2'; Text = 'Alle Profile aller Benutzer. Gespeicherte Kennwörter werden nie angefasst. Läuft ein Browser, wird er übersprungen oder (nach Rückfrage) geschlossen.' }
        'Anwendungen'    = @{ Glyph = '&#xE71D;'; Color = '#7C3AED'; Text = 'Caches und Protokolle bekannter Programme - nur, was das Programm selbst wieder erzeugt.' }
        'Windows-Extras' = @{ Glyph = '&#xE713;'; Color = '#EA580C'; Text = 'Spuren und Spezial-Caches von Windows. Datenschutz-Einträge sind standardmäßig aus.' }
    }
}
function Get-CcProfileIds([string]$Mode, $Catalog) {
    $all = @($Catalog | ForEach-Object { $_ })
    switch ($Mode) {
        'Gründlich'   { return @($all | Where-Object { $_.Def -or $_.Deep } | ForEach-Object { $_.Id }) }
        'Datenschutz' { return @($all | Where-Object { $_.Def -or $_.Priv } | ForEach-Object { $_.Id }) }
        default       { return @($all | Where-Object { $_.Def } | ForEach-Object { $_.Id }) }
    }
}
function ConvertTo-CcIdList($Value) {
    $o = [System.Collections.Generic.List[string]]::new()
    foreach ($v in @($Value)) { foreach ($p in ([string]$v -split '[,;\s]+')) { if ($p -and -not $o.Contains($p)) { $o.Add($p) } } }
    return , $o
}

# ---- kleine Helfer
function Format-CcSize([double]$Bytes) {
    if ($Bytes -ge 1TB) { return ('{0:N2} TB' -f ($Bytes / 1TB)) }
    if ($Bytes -ge 1GB) { return ('{0:N2} GB' -f ($Bytes / 1GB)) }
    if ($Bytes -ge 1MB) { return ('{0:N1} MB' -f ($Bytes / 1MB)) }
    if ($Bytes -gt 0) { return ('{0:N0} KB' -f [math]::Max([double]1, [math]::Ceiling($Bytes / 1KB))) }
    return '0 KB'
}
function Get-CcProfiles {
    $list = [System.Collections.Generic.List[object]]::new()
    foreach ($p in @(Get-CimInstance Win32_UserProfile -ErrorAction SilentlyContinue)) {
        if ($p.Special -or -not $p.LocalPath) { continue }
        $lp = [string]$p.LocalPath
        if (-not [IO.Directory]::Exists($lp)) { continue }
        $list.Add([pscustomobject]@{ Root = $lp; Sid = [string]$p.SID; Loaded = [bool]$p.Loaded; User = [IO.Path]::GetFileName($lp) })
    }
    if (-not $list.Count -and $env:USERPROFILE) {
        $list.Add([pscustomobject]@{ Root = $env:USERPROFILE; Sid = [Security.Principal.WindowsIdentity]::GetCurrent().User.Value; Loaded = $true; User = $env:USERNAME })
    }
    return , $list
}
function Get-CcRunningSet {
    $h = @{}
    foreach ($p in @(Get-Process -ErrorAction SilentlyContinue)) { $h[([string]$p.ProcessName).ToLower()] = $true }
    return $h
}
function Get-CcSteamPath {
    foreach ($k in @(@('CurrentUser', 'Software\Valve\Steam', 'SteamPath'), @('LocalMachine', 'SOFTWARE\WOW6432Node\Valve\Steam', 'InstallPath'), @('LocalMachine', 'SOFTWARE\Valve\Steam', 'InstallPath'))) {
        try {
            $b = [Microsoft.Win32.RegistryKey]::OpenBaseKey($k[0], 'Registry64')
            $s = $b.OpenSubKey($k[1])
            if ($s) { $v = [string]$s.GetValue($k[2]); $s.Close(); if ($v) { $v = $v.Replace('/', '\'); if ([IO.Directory]::Exists($v)) { return $v } } }
        } catch { }
    }
    return ''
}
function New-CcContext($Opt) {
    $days = @{}
    if ($Opt -and $Opt.Days) { foreach ($k in @($Opt.Days.Keys)) { $days[$k] = [int]$Opt.Days[$k] } }
    $drv = [System.Collections.Generic.List[string]]::new()
    foreach ($d in [IO.DriveInfo]::GetDrives()) { try { if ([string]$d.DriveType -eq 'Fixed' -and $d.IsReady) { $drv.Add($d.RootDirectory.FullName) } } catch { } }
    $keep = ''; if ($Opt -and $Opt.Keep) { $keep = [string]$Opt.Keep }
    return [pscustomobject]@{ Days = $days; Keep = $keep; Steam = (Get-CcSteamPath); Drives = $drv; Running = (Get-CcRunningSet) }
}
function Expand-CcToken([string]$P, $Prof, $Ctx) {
    if ($P -match '^(LL|L|R|P|W|PD|STEAM):(.*)$') {
        $t = $Matches[1]; $rest = $Matches[2].TrimStart('\')
        $base = ''
        switch ($t) {
            'L'     { if ($Prof) { $base = [IO.Path]::Combine($Prof.Root, 'AppData\Local') } }
            'R'     { if ($Prof) { $base = [IO.Path]::Combine($Prof.Root, 'AppData\Roaming') } }
            'LL'    { if ($Prof) { $base = [IO.Path]::Combine($Prof.Root, 'AppData\LocalLow') } }
            'P'     { if ($Prof) { $base = $Prof.Root } }
            'W'     { $base = $env:SystemRoot }
            'PD'    { $base = $env:ProgramData }
            'STEAM' { if ($Ctx -and $Ctx.Steam) { $base = $Ctx.Steam } }
        }
        if (-not $base) { return '' }
        if ($rest) { return [IO.Path]::Combine($base, $rest) }
        return $base
    }
    return $P
}
# Ordnerpfad mit * oder ? in einzelnen Abschnitten auflösen (nur vorhandene Ordner)
function Expand-CcWild([string]$Path) {
    $out = [System.Collections.Generic.List[string]]::new()
    if (-not $Path) { return , $out }
    if ($Path -notmatch '[\*\?]') { if ([IO.Directory]::Exists($Path)) { $out.Add($Path.TrimEnd('\')) }; return , $out }
    $parts = $Path.TrimEnd('\') -split '\\'
    $cur = @($parts[0] + '\')
    for ($i = 1; $i -lt $parts.Count; $i++) {
        $seg = $parts[$i]; $next = @()
        foreach ($cd in $cur) {
            if ($seg -match '[\*\?]') { try { $next += @([IO.Directory]::GetDirectories($cd, $seg)) } catch { } }
            else { $d = [IO.Path]::Combine($cd, $seg); if ([IO.Directory]::Exists($d)) { $next += $d } }
        }
        $cur = $next
        if (-not $cur.Count) { break }
    }
    foreach ($cd in $cur) { $out.Add(([string]$cd).TrimEnd('\')) }
    return , $out
}
function New-CcRes([string]$Id) { [pscustomobject]@{ Id = $Id; Bytes = [int64]0; Files = 0; Entries = [int64]0; Failed = 0; Running = $false; Skipped = $false; Note = '' } }
function Add-CcRes($R, $X) { if ($X) { $R.Bytes += [int64]$X.Bytes; $R.Files += [int]$X.Files; $R.Failed += [int]$X.Failed } }
# Dateien messen oder löschen; folgt keinen Verknüpfungen/Junctions; gesperrte Dateien werden übersprungen; der Startordner bleibt bestehen
function Invoke-CcFiles([string]$Dir, [string]$Filter = '*', [bool]$Recurse = $true, [int]$Days = 0, [bool]$Delete = $false) {
    $r = [pscustomobject]@{ Bytes = [int64]0; Files = 0; Failed = 0 }
    if (-not $Dir -or -not [IO.Directory]::Exists($Dir)) { return $r }
    $limit = (Get-Date).AddDays(-$Days)
    $canCancel = [bool](Get-Command Test-PCancel -CommandType Function -ErrorAction SilentlyContinue)
    $dirs = [System.Collections.Generic.List[string]]::new()
    $stack = New-Object System.Collections.Stack
    $stack.Push($Dir)
    while ($stack.Count -gt 0) {
        if ($Delete -and $canCancel -and (Test-PCancel)) { break }
        $d = [string]$stack.Pop()
        $di = New-Object IO.DirectoryInfo $d
        $files = @(); try { $files = $di.GetFiles($Filter) } catch { }
        foreach ($f in $files) {
            if ($f.Name -eq 'desktop.ini') { continue }
            if ($Days -gt 0 -and $f.LastWriteTime -ge $limit) { continue }
            $len = [int64]$f.Length
            if (-not $Delete) { $r.Bytes += $len; $r.Files++; continue }
            try { if ($f.IsReadOnly) { $f.IsReadOnly = $false }; $f.Delete(); $r.Bytes += $len; $r.Files++ } catch { $r.Failed++ }
        }
        if ($Recurse) {
            $subs = @(); try { $subs = $di.GetDirectories() } catch { }
            foreach ($s in $subs) {
                if ($s.Attributes -band [IO.FileAttributes]::ReparsePoint) { continue }
                $stack.Push($s.FullName); $dirs.Add($s.FullName)
            }
        }
    }
    if ($Recurse -and $Delete) {
        foreach ($x in ($dirs | Sort-Object Length -Descending)) {
            try { if (-not [IO.Directory]::EnumerateFileSystemEntries($x).GetEnumerator().MoveNext()) { [IO.Directory]::Delete($x, $false) } } catch { }
        }
    }
    return $r
}
# einzelne benannte Dateien in einem Ordner
function Invoke-CcNamedFiles([string]$Dir, [string[]]$Names, [bool]$Delete, $R) {
    foreach ($n in $Names) {
        $f = [IO.Path]::Combine($Dir, $n)
        if (-not [IO.File]::Exists($f)) { continue }
        $len = [int64]0; try { $len = (New-Object IO.FileInfo $f).Length } catch { }
        if (-not $Delete) { $R.Bytes += $len; $R.Files++; continue }
        try { [IO.File]::Delete($f); $R.Bytes += $len; $R.Files++ } catch { $R.Failed++ }
    }
}
function Get-CcItemDays($It, $Ctx) {
    $d = $It.Days
    if ($d -is [string] -and $d -like 'Cfg:*') { $k = $d.Substring(4); if ($Ctx.Days -and $Ctx.Days.ContainsKey($k)) { return [int]$Ctx.Days[$k] }; return 1 }
    if ($d) { return [int]$d }
    return 0
}
function Invoke-CcSpecs($It, $Profiles, $Ctx, [bool]$Delete, $R) {
    $days = Get-CcItemDays $It $Ctx
    $seen = @{}
    foreach ($spec in @($It.Paths)) {
        $f = ([string]$spec) -split '\|'
        $p = $f[0]
        $flt = if ($f.Count -gt 1 -and $f[1]) { $f[1] } else { '*' }
        $rec = -not ($f.Count -gt 2 -and $f[2] -eq '0')
        $bases = [System.Collections.Generic.List[string]]::new()
        if ($p -match '^(LL|L|R|P):') { foreach ($pr in $Profiles) { $x = Expand-CcToken $p $pr $Ctx; if ($x) { $bases.Add($x) } } }
        elseif ($p -like 'ALLDRIVES:*') { foreach ($dr in $Ctx.Drives) { $bases.Add([IO.Path]::Combine($dr, $p.Substring(10).TrimStart('\'))) } }
        else { $x = Expand-CcToken $p $null $Ctx; if ($x) { $bases.Add($x) } }
        foreach ($bx in $bases) {
            foreach ($d in @(Expand-CcWild $bx | ForEach-Object { $_ })) {
                $key = ($d + '|' + $flt).ToLower()
                if ($seen.ContainsKey($key)) { continue }
                $seen[$key] = $true
                Add-CcRes $R (Invoke-CcFiles $d $flt $rec $days $Delete)
            }
        }
    }
}

# ---- Registry (Werte zählen bzw. löschen, Schlüssel bleiben bestehen)
function Expand-CcRegWild($Base, [string]$Path) {
    $out = [System.Collections.Generic.List[string]]::new()
    $cur = @('')
    foreach ($seg in ($Path -split '\\')) {
        $next = @()
        foreach ($c in $cur) {
            if ($seg -match '[\*\?]') {
                $k = $null; try { $k = if ($c) { $Base.OpenSubKey($c) } else { $Base } } catch { }
                if (-not $k) { continue }
                try { foreach ($n in $k.GetSubKeyNames()) { if ($n -like $seg) { $next += $(if ($c) { $c + '\' + $n } else { $n }) } } } catch { }
                if ($c) { $k.Close() }
            } else {
                $np = if ($c) { $c + '\' + $seg } else { $seg }
                $k = $null; try { $k = $Base.OpenSubKey($np) } catch { }
                if ($k) { $k.Close(); $next += $np }
            }
        }
        $cur = $next
        if (-not $cur.Count) { break }
    }
    foreach ($c in $cur) { if ($c) { $out.Add($c) } }
    return , $out
}
function Clear-CcRegValues($Base, [string]$Path, [bool]$Delete) {
    $n = 0; $k = $null
    try { $k = $Base.OpenSubKey($Path, $Delete) } catch { }
    if (-not $k) { return 0 }
    try {
        foreach ($v in $k.GetValueNames()) { if ($v -eq '') { continue }; $n++; if ($Delete) { try { $k.DeleteValue($v, $false) } catch { } } }
        foreach ($s in $k.GetSubKeyNames()) { $n += (Clear-CcRegValues $Base ($Path + '\' + $s) $Delete) }
    } finally { $k.Close() }
    return $n
}
function Invoke-CcRegItem($It, $Profiles, [bool]$Delete, $R) {
    foreach ($pr in $Profiles) {
        if (-not $pr.Sid) { continue }
        $hk = $null; try { $hk = [Microsoft.Win32.Registry]::Users.OpenSubKey($pr.Sid) } catch { }
        if (-not $hk) { continue }   # Benutzer nicht angemeldet - Registry nicht geladen
        try {
            foreach ($spec in @($It.RegKeys)) {
                foreach ($kp in @(Expand-CcRegWild $hk $spec | ForEach-Object { $_ })) { $R.Entries += (Clear-CcRegValues $hk $kp $Delete) }
            }
        } finally { $hk.Close() }
    }
}

# ---- SQLite (winsqlite3.dll ist Teil von Windows 10/11), Firefox-mozlz4 und indirekte Texte (@dll,-123)
function Initialize-CcNative {
    if ('PCPflege.CcNative' -as [type]) { return }
    $cs = @'
using System;
using System.IO;
using System.Text;
using System.Runtime.InteropServices;
namespace PCPflege {
public static class CcNative {
    const string Lib = "winsqlite3.dll";
    [DllImport(Lib, CallingConvention = CallingConvention.StdCall)] static extern int sqlite3_open_v2(byte[] filename, out IntPtr db, int flags, IntPtr vfs);
    [DllImport(Lib, CallingConvention = CallingConvention.StdCall)] static extern int sqlite3_close_v2(IntPtr db);
    [DllImport(Lib, CallingConvention = CallingConvention.StdCall)] static extern int sqlite3_busy_timeout(IntPtr db, int ms);
    [DllImport(Lib, CallingConvention = CallingConvention.StdCall)] static extern int sqlite3_prepare_v2(IntPtr db, byte[] sql, int nByte, out IntPtr stmt, IntPtr tail);
    [DllImport(Lib, CallingConvention = CallingConvention.StdCall)] static extern int sqlite3_step(IntPtr stmt);
    [DllImport(Lib, CallingConvention = CallingConvention.StdCall)] static extern long sqlite3_column_int64(IntPtr stmt, int col);
    [DllImport(Lib, CallingConvention = CallingConvention.StdCall)] static extern int sqlite3_finalize(IntPtr stmt);
    [DllImport(Lib, CallingConvention = CallingConvention.StdCall)] static extern int sqlite3_changes(IntPtr db);
    [DllImport(Lib, CallingConvention = CallingConvention.StdCall)] static extern IntPtr sqlite3_errmsg(IntPtr db);
    [DllImport("shlwapi.dll", CharSet = CharSet.Unicode)] static extern int SHLoadIndirectString(string src, StringBuilder buf, int size, IntPtr reserved);
    [ThreadStatic] public static string LastError;
    static byte[] U8(string s) { return Encoding.UTF8.GetBytes(s + "\0"); }
    static string Msg(IntPtr db) {
        if (db == IntPtr.Zero) return "";
        IntPtr p = sqlite3_errmsg(db); if (p == IntPtr.Zero) return "";
        int n = 0; while (Marshal.ReadByte(p, n) != 0) n++;
        byte[] b = new byte[n]; Marshal.Copy(p, b, 0, n); return Encoding.UTF8.GetString(b);
    }
    static IntPtr Open(string path, bool write) {
        IntPtr db; int rc;
        if (write) rc = sqlite3_open_v2(U8(path), out db, 0x2, IntPtr.Zero);
        else rc = sqlite3_open_v2(U8(new Uri(path).AbsoluteUri + "?immutable=1"), out db, 0x1 | 0x40, IntPtr.Zero);
        if (rc != 0) { LastError = Msg(db); if (db != IntPtr.Zero) sqlite3_close_v2(db); return IntPtr.Zero; }
        sqlite3_busy_timeout(db, 3000);
        return db;
    }
    static long CountOn(IntPtr db, string sql) {
        IntPtr st; byte[] q = U8(sql);
        if (sqlite3_prepare_v2(db, q, q.Length, out st, IntPtr.Zero) != 0) { LastError = Msg(db); return -1; }
        try { int rc = sqlite3_step(st); if (rc == 100) return sqlite3_column_int64(st, 0); LastError = Msg(db); return -1; }
        finally { sqlite3_finalize(st); }
    }
    public static long Count(string path, string sql) {
        LastError = "";
        long n = -1;
        IntPtr db = Open(path, false);
        if (db != IntPtr.Zero) { try { n = CountOn(db, sql); } finally { sqlite3_close_v2(db); } }
        if (n >= 0) return n;
        string tmp = Path.Combine(Path.GetTempPath(), "pct_" + Guid.NewGuid().ToString("N") + ".db");
        try {
            using (FileStream src = new FileStream(path, FileMode.Open, FileAccess.Read, FileShare.ReadWrite | FileShare.Delete))
            using (FileStream dst = File.Create(tmp)) { src.CopyTo(dst); }
            db = Open(tmp, false); if (db == IntPtr.Zero) return -1;
            try { return CountOn(db, sql); } finally { sqlite3_close_v2(db); }
        } catch (Exception e) { LastError = e.Message; return -1; }
        finally { try { File.Delete(tmp); } catch { } }
    }
    public static long Exec(string path, string[] sqls) {
        LastError = "";
        IntPtr db = Open(path, true); if (db == IntPtr.Zero) return -1;
        long total = 0;
        try {
            foreach (string s in sqls) {
                IntPtr st; byte[] q = U8(s);
                if (sqlite3_prepare_v2(db, q, q.Length, out st, IntPtr.Zero) != 0) { LastError = Msg(db); continue; }
                try { int rc = sqlite3_step(st); if (rc == 101 || rc == 100) total += sqlite3_changes(db); else { LastError = Msg(db); if (rc == 5 || rc == 6) return -1; } }
                finally { sqlite3_finalize(st); }
            }
        } finally { sqlite3_close_v2(db); }
        return total;
    }
    public static string MozLz4(string path) {
        byte[] b;
        using (FileStream fs = new FileStream(path, FileMode.Open, FileAccess.Read, FileShare.ReadWrite | FileShare.Delete)) { b = new byte[fs.Length]; int r = 0; while (r < b.Length) { int x = fs.Read(b, r, b.Length - r); if (x <= 0) break; r += x; } }
        return MozLz4Bytes(b);
    }
    public static string MozLz4Bytes(byte[] b) {
        if (b == null || b.Length < 12 || Encoding.ASCII.GetString(b, 0, 7) != "mozLz40") return null;
        int size = BitConverter.ToInt32(b, 8); if (size <= 0 || size > 512 * 1024 * 1024) return null;
        byte[] o = new byte[size]; int ip = 12, op = 0;
        while (ip < b.Length) {
            int token = b[ip++]; int lit = token >> 4;
            if (lit == 15) { int x; do { if (ip >= b.Length) return null; x = b[ip++]; lit += x; } while (x == 255); }
            if (ip + lit > b.Length || op + lit > o.Length) return null;
            Buffer.BlockCopy(b, ip, o, op, lit); ip += lit; op += lit;
            if (ip >= b.Length) break;
            if (ip + 2 > b.Length) return null;
            int off = b[ip] | (b[ip + 1] << 8); ip += 2;
            if (off == 0 || off > op) return null;
            int ml = token & 15;
            if (ml == 15) { int x; do { if (ip >= b.Length) return null; x = b[ip++]; ml += x; } while (x == 255); }
            ml += 4;
            if (op + ml > o.Length) return null;
            int mp = op - off; for (int i = 0; i < ml; i++) o[op++] = o[mp + i];
        }
        return Encoding.UTF8.GetString(o, 0, op);
    }
    public static string Indirect(string s) {
        if (string.IsNullOrEmpty(s) || s[0] != '@') return s;
        try { StringBuilder sb = new StringBuilder(1024); return SHLoadIndirectString(s, sb, sb.Capacity, IntPtr.Zero) == 0 ? sb.ToString() : s; } catch { return s; }
    }
}
}
'@
    try { Add-Type -TypeDefinition $cs -ErrorAction Stop } catch { if (-not ('PCPflege.CcNative' -as [type])) { throw } }
}
function Invoke-CcDb([string]$Db, [string]$CountSql, [string[]]$Exec, [bool]$Delete, $R) {
    if (-not [IO.File]::Exists($Db)) { return }
    Initialize-CcNative
    $n = [int64]0
    if ($CountSql) { $n = [PCPflege.CcNative]::Count($Db, $CountSql); if ($n -lt 0) { $n = 0; if ($R -and -not $R.Note) { $R.Note = 'Datenbank nicht lesbar: ' + [PCPflege.CcNative]::LastError } } }
    if ($Delete -and $Exec) {
        $ch = [PCPflege.CcNative]::Exec($Db, [string[]]$Exec)
        if ($ch -lt 0) { $R.Failed++; $R.Note = 'Datenbank gesperrt (Browser geöffnet?): ' + [PCPflege.CcNative]::LastError; return }
    }
    $R.Entries += $n
}
function Get-CcCookieWhere([string]$Col, [string]$Keep) {
    $d = @(($Keep -split '[;,\s]+') | ForEach-Object { $_.Trim().Trim('.').ToLower() -replace '^https?://', '' -replace '/.*$', '' -replace '^www\.', '' } | Where-Object { $_ -match '^[a-z0-9][a-z0-9\.\-]*$' } | Select-Object -Unique)
    if (-not $d.Count) { return '' }
    $c = foreach ($x in $d) { "($Col = '$x' OR $Col = '.$x' OR $Col LIKE '%.$x')" }
    return (' WHERE NOT (' + ($c -join ' OR ') + ')')
}
function Get-CcChromiumProfiles([string]$Root) {
    $o = [System.Collections.Generic.List[string]]::new()
    if (-not [IO.Directory]::Exists($Root)) { return , $o }
    if ([IO.File]::Exists([IO.Path]::Combine($Root, 'Preferences'))) { $o.Add($Root) }
    $subs = @(); try { $subs = [IO.Directory]::GetDirectories($Root) } catch { }
    foreach ($d in $subs) {
        $leaf = [IO.Path]::GetFileName($d)
        if (($leaf -eq 'Default' -or $leaf -like 'Profile *' -or $leaf -eq 'Guest Profile') -and [IO.File]::Exists([IO.Path]::Combine($d, 'Preferences'))) { $o.Add($d) }
    }
    return , $o
}
function Get-CcBrowserProfileDirs($B, $Prof, $Ctx) {
    # liefert je Browser-Profil: Profilordner (Pr) und Cache-Ordner (Cb) - bei Opera/Firefox liegt der Cache unter AppData\Local
    $out = [System.Collections.Generic.List[object]]::new()
    $root = Expand-CcToken $B.Root $Prof $Ctx
    if (-not $root -or -not [IO.Directory]::Exists($root)) { return , $out }
    $croot = if ($B.CacheRoot) { Expand-CcToken $B.CacheRoot $Prof $Ctx } else { $root }
    $dirs = @()
    if ($B.Kind -eq 'Firefox') { try { $dirs = @([IO.Directory]::GetDirectories($root)) } catch { } }
    else { $dirs = @(Get-CcChromiumProfiles $root | ForEach-Object { $_ }) }
    foreach ($d in $dirs) {
        $rel = $d.Substring($root.Length).TrimStart('\')
        $cb = if ($rel) { [IO.Path]::Combine($croot, $rel) } else { $croot }
        $out.Add([pscustomobject]@{ Pr = $d; Cb = $cb; Root = $root; CRoot = $croot; Name = $(if ($rel) { $rel } else { 'Standard' }) })
    }
    return , $out
}
function Invoke-CcBrowser($It, $Profiles, $Ctx, [bool]$Delete, $R) {
    $b = @(Get-CcBrowserDefs | Where-Object { $_.Key -eq $It.Browser }) | Select-Object -First 1
    if (-not $b) { return }
    $seen = @{}
    $dirDo = { param($d) if (-not $d) { return }; $k = $d.ToLower(); if ($seen.ContainsKey($k)) { return }; $seen[$k] = $true; Add-CcRes $R (Invoke-CcFiles $d '*' $true 0 $Delete) }
    foreach ($pr in $Profiles) {
        $bps = @(Get-CcBrowserProfileDirs $b $pr $Ctx | ForEach-Object { $_ })
        foreach ($bp in $bps) {
            if ($b.Kind -eq 'Chromium') {
                switch ($It.What) {
                    'Cache' { foreach ($s in 'Cache', 'Media Cache', 'Application Cache') { foreach ($bd in @($bp.Cb, $bp.Pr)) { & $dirDo ([IO.Path]::Combine($bd, $s)) } } }
                    'Code' {
                        foreach ($s in 'Code Cache', 'GPUCache', 'DawnCache', 'DawnGraphiteCache', 'DawnWebGPUCache', 'Service Worker\CacheStorage', 'Service Worker\ScriptCache') { foreach ($bd in @($bp.Cb, $bp.Pr)) { & $dirDo ([IO.Path]::Combine($bd, $s)) } }
                        foreach ($s in 'GrShaderCache', 'ShaderCache', 'GraphiteDawnCache') { foreach ($bd in @($bp.CRoot, $bp.Root)) { & $dirDo ([IO.Path]::Combine($bd, $s)) } }
                    }
                    'Downloads' { Invoke-CcDb ([IO.Path]::Combine($bp.Pr, 'History')) 'SELECT COUNT(*) FROM downloads' @('DELETE FROM downloads_url_chains', 'DELETE FROM downloads_slices', 'DELETE FROM downloads') $Delete $R }
                    'History' {
                        Invoke-CcDb ([IO.Path]::Combine($bp.Pr, 'History')) 'SELECT COUNT(*) FROM urls' @() $false $R
                        Invoke-CcNamedFiles $bp.Pr @('History', 'History-journal', 'Visited Links', 'Top Sites', 'Top Sites-journal', 'Network Action Predictor', 'Network Action Predictor-journal', 'Shortcuts', 'Shortcuts-journal') $Delete $R
                    }
                    'Cookies' {
                        $db = [IO.Path]::Combine($bp.Pr, 'Network\Cookies'); if (-not [IO.File]::Exists($db)) { $db = [IO.Path]::Combine($bp.Pr, 'Cookies') }
                        $w = Get-CcCookieWhere 'host_key' $Ctx.Keep
                        Invoke-CcDb $db ('SELECT COUNT(*) FROM cookies' + $w) @('DELETE FROM cookies' + $w) $Delete $R
                    }
                    'Session' { & $dirDo ([IO.Path]::Combine($bp.Pr, 'Sessions')); Invoke-CcNamedFiles $bp.Pr @('Current Session', 'Current Tabs', 'Last Session', 'Last Tabs') $Delete $R }
                    'Autofill' { Invoke-CcDb ([IO.Path]::Combine($bp.Pr, 'Web Data')) 'SELECT COUNT(*) FROM autofill' @('DELETE FROM autofill') $Delete $R }
                }
            } else {
                $pl = [IO.Path]::Combine($bp.Pr, 'places.sqlite')
                switch ($It.What) {
                    'Cache' { foreach ($s in 'cache2', 'jumpListCache', 'thumbnails') { & $dirDo ([IO.Path]::Combine($bp.Cb, $s)) } }
                    'Code' {
                        & $dirDo ([IO.Path]::Combine($bp.Pr, 'shader-cache')); & $dirDo ([IO.Path]::Combine($bp.Cb, 'startupCache'))
                        foreach ($d in @(Expand-CcWild ([IO.Path]::Combine($bp.Pr, 'storage\default\*\cache')) | ForEach-Object { $_ })) { & $dirDo $d }
                    }
                    'Downloads' {
                        $q = "FROM moz_annos WHERE anno_attribute_id IN (SELECT id FROM moz_anno_attributes WHERE name LIKE 'downloads/%')"
                        Invoke-CcDb $pl ('SELECT COUNT(*) ' + $q) @('DELETE ' + $q) $Delete $R
                    }
                    'History' {
                        Invoke-CcDb $pl 'SELECT COUNT(*) FROM moz_historyvisits' @(
                            'DELETE FROM moz_historyvisits', 'DELETE FROM moz_inputhistory', 'DELETE FROM moz_places_metadata',
                            'UPDATE moz_places SET visit_count = 0, last_visit_date = NULL',
                            'DELETE FROM moz_places WHERE id NOT IN (SELECT fk FROM moz_bookmarks WHERE fk IS NOT NULL) AND id NOT IN (SELECT place_id FROM moz_annos) AND id NOT IN (SELECT place_id FROM moz_keywords WHERE place_id IS NOT NULL)') $Delete $R
                    }
                    'Cookies' {
                        $w = Get-CcCookieWhere 'host' $Ctx.Keep
                        Invoke-CcDb ([IO.Path]::Combine($bp.Pr, 'cookies.sqlite')) ('SELECT COUNT(*) FROM moz_cookies' + $w) @('DELETE FROM moz_cookies' + $w) $Delete $R
                    }
                    'Session' { Invoke-CcNamedFiles $bp.Pr @('sessionstore.jsonlz4', 'sessionstore.js') $Delete $R; & $dirDo ([IO.Path]::Combine($bp.Pr, 'sessionstore-backups')) }
                    'Autofill' { Invoke-CcDb ([IO.Path]::Combine($bp.Pr, 'formhistory.sqlite')) 'SELECT COUNT(*) FROM moz_formhistory' @('DELETE FROM moz_formhistory') $Delete $R }
                }
            }
        }
    }
}
function Invoke-CcSpecial($It, $Ctx, [bool]$Delete, $R) {
    switch ($It.Id) {
        'Ext.Clipboard' {
            try {
                $null = [Windows.ApplicationModel.DataTransfer.Clipboard, Windows.ApplicationModel.DataTransfer, ContentType = WindowsRuntime]
                if (-not [Windows.ApplicationModel.DataTransfer.Clipboard]::IsHistoryEnabled()) { $R.Note = 'Verlauf ist ausgeschaltet - nichts zu tun' }
                elseif ($Delete) { if ([Windows.ApplicationModel.DataTransfer.Clipboard]::ClearHistory()) { $R.Note = 'Verlauf geleert (angeheftete Einträge bleiben)'; $R.Entries = 1 } else { $R.Note = 'Verlauf konnte nicht geleert werden' } }
                else { $R.Note = 'Verlauf ist eingeschaltet'; $R.Entries = 1 }
            } catch { $R.Note = 'nur in der Sitzung des angemeldeten Benutzers möglich' }
        }
        'Ext.Dns' {
            try { $R.Entries = [int64]@(Get-DnsClientCache -ErrorAction Stop).Count } catch { $R.Note = 'DNS-Cache nicht lesbar' }
            if ($Delete) { try { Clear-DnsClientCache -ErrorAction Stop } catch { try { $null = & ipconfig.exe /flushdns 2>&1 } catch { } } }
        }
        'Ext.FontCache' {
            $fc = [IO.Path]::Combine($env:SystemRoot, 'ServiceProfiles\LocalService\AppData\Local\FontCache')
            if ($Delete) { try { Stop-Service -Name FontCache -Force -ErrorAction Stop } catch { $R.Note = 'Dienst ließ sich nicht anhalten - gesperrte Dateien bleiben' } }
            try {
                Add-CcRes $R (Invoke-CcFiles $fc '*' $false 0 $Delete)
                Add-CcRes $R (Invoke-CcFiles ([IO.Path]::Combine($env:SystemRoot, 'System32')) 'FNTCACHE.DAT' $false 0 $Delete)
            } finally { if ($Delete) { try { Start-Service -Name FontCache -ErrorAction Stop } catch { } } }
            if ($Delete -and -not $R.Note) { $R.Note = 'wirkt vollständig nach einem Neustart' }
        }
    }
}
# Ein Element messen ($Delete = $false) oder reinigen
function Invoke-CcItem($It, $Profiles, $Ctx, [bool]$Delete) {
    $r = New-CcRes $It.Id
    $run = @(@($It.Proc) | Where-Object { $_ -and $Ctx.Running.ContainsKey(([string]$_).ToLower()) })
    if ($run.Count) {
        $r.Running = $true; $r.Note = 'läuft gerade: ' + ($run -join ', ')
        if ($Delete) { $r.Skipped = $true; $r.Note = 'übersprungen - {0} läuft' -f ($run -join ', '); return $r }
    }
    try {
        if ($It.Kind -eq 'Browser') { Invoke-CcBrowser $It $Profiles $Ctx $Delete $r }
        elseif ($It.Kind -eq 'Special') { Invoke-CcSpecial $It $Ctx $Delete $r }
        else {
            if ($It.Paths) { Invoke-CcSpecs $It $Profiles $Ctx $Delete $r }
            if ($It.RegKeys) { Invoke-CcRegItem $It $Profiles $Delete $r }
        }
    } catch { $r.Note = 'Fehler: ' + $_.Exception.Message }
    if ($Delete -and $r.Failed -gt 0 -and -not $r.Note) { $r.Note = '{0} Datei(en) gesperrt - übersprungen' -f $r.Failed }
    return $r
}
# Analyse für die Oberfläche (läuft in Invoke-Bg). $Prog: synchronisierte Hashtable für die Fortschrittsanzeige
function Invoke-CcAnalyze($Items, $Opt, $Prog) {
    $profiles = @(Get-CcProfiles | ForEach-Object { $_ })
    $ctx = New-CcContext $Opt
    $i = 0; $n = @($Items).Count
    foreach ($it in @($Items)) {
        $i++
        if ($Prog) { $Prog.Text = $(if ($it.Sub -and $it.Group -eq 'Browser') { $it.Sub + ': ' + $it.Title } else { $it.Title }); $Prog.Pct = [int]($i * 100 / [math]::Max(1, $n)) }
        Invoke-CcItem $it $profiles $ctx $false
    }
}
# Welche Elemente gibt es auf diesem PC? (Browser installiert, Programm-Ordner vorhanden)
function Get-CcPresence($Items) {
    $profiles = @(Get-CcProfiles | ForEach-Object { $_ })
    $ctx = New-CcContext $null
    $h = @{}
    $bdefs = @(Get-CcBrowserDefs)
    foreach ($it in @($Items)) {
        $ok = $false
        if ($it.Kind -eq 'Browser') {
            $b = @($bdefs | Where-Object { $_.Key -eq $it.Browser }) | Select-Object -First 1
            foreach ($pr in $profiles) { $x = Expand-CcToken $b.Root $pr $ctx; if ($x -and [IO.Directory]::Exists($x)) { $ok = $true; break } }
        } elseif ($it.Kind -eq 'Special' -or $it.RegKeys -or $it.Group -eq 'Windows' -or $it.Group -eq 'Windows-Extras') { $ok = $true }
        else {
            foreach ($spec in @($it.Paths)) {
                $p = (([string]$spec) -split '\|')[0]
                $bases = @()
                if ($p -match '^(LL|L|R|P):') { foreach ($pr in $profiles) { $bases += (Expand-CcToken $p $pr $ctx) } } else { $bases += (Expand-CcToken $p $null $ctx) }
                foreach ($bx in $bases) { if ($bx -and @(Expand-CcWild $bx | ForEach-Object { $_ }).Count) { $ok = $true; break } }
                if ($ok) { break }
            }
        }
        $h[$it.Id] = $ok
    }
    return $h
}
function Get-CcState([string]$File) {
    try { if ([IO.File]::Exists($File)) { $j = [IO.File]::ReadAllText($File) | ConvertFrom-Json; if ($j) { return $j } } } catch { }
    return [pscustomobject]@{}
}
function Set-CcState([string]$File, [string]$Name, $Value) {
    $s = Get-CcState $File
    $s | Add-Member -NotePropertyName $Name -NotePropertyValue $Value -Force
    try { $s | ConvertTo-Json -Depth 6 | Set-Content -LiteralPath $File -Encoding UTF8 } catch { }
}

# =====================================================================
#  Registry-Reinigung (konservativ: nur verwaiste Einträge, deren Ziel sicher fehlt)
# =====================================================================
function Get-CcRegCatNames {
    [ordered]@{
        SharedDll = 'Fehlende gemeinsame DLLs'
        AppPaths  = 'Verwaiste Programmpfade (App Paths)'
        Uninstall = 'Verwaiste Deinstallations-Einträge'
        FileTypes = 'Dateitypen und "Öffnen mit" ohne Programm'
        Run       = 'Autostart-Einträge mit fehlender Datei'
        Help      = 'Fehlende Hilfedateien'
        Installer = 'Veraltete Installer-Verweise'
        Fonts     = 'Ungültige Schriftart-Einträge'
        Sounds    = 'Systemklänge mit fehlender Datei'
    }
}
function Open-CcRegKey([string]$Hive, [string]$Path, [bool]$Write = $false) {
    try {
        $base = switch ($Hive) { 'HKLM' { [Microsoft.Win32.RegistryKey]::OpenBaseKey('LocalMachine', 'Registry64') } 'HKCU' { [Microsoft.Win32.RegistryKey]::OpenBaseKey('CurrentUser', 'Registry64') } 'HKU' { [Microsoft.Win32.RegistryKey]::OpenBaseKey('Users', 'Registry64') } default { $null } }
        if (-not $base) { return $null }
        if (-not $Path) { return $base }
        return $base.OpenSubKey($Path, $Write)
    } catch { return $null }
}
# Dateipfad aus einem Befehl/Wert - '' wenn nicht sicher bestimmbar (dann wird nichts gemeldet)
function Get-CcRefPath([string]$Raw) {
    if (-not $Raw) { return '' }
    $s = [Environment]::ExpandEnvironmentVariables($Raw.Trim())
    if ($s -match '%' -or $s.StartsWith('@')) { return '' }
    $p = ''
    if ($s -match '^"([^"]+)"') { $p = $Matches[1] }
    elseif ($s -match '^([A-Za-z]:\\[^"]*?\.(exe|dll|com|cmd|bat|cpl|ocx|scr|msc|vbs|ps1|wav|ttf|otf|fon|ttc|chm|hlp|sys|lnk|ico))(\s|,|$)') { $p = $Matches[1] }
    elseif ($s -match '^[A-Za-z]:\\[^,"]*$' -and $s -notmatch '\s/') { $p = $s.Trim() }
    if (-not $p -or $p -notmatch '^[A-Za-z]:\\') { return '' }
    $leaf = ($p -split '\\')[-1].ToLower()
    # Hilfsprogramme: das eigentliche Ziel steht in den Argumenten - nicht sicher bestimmbar
    if ($leaf -in 'rundll32.exe', 'msiexec.exe', 'cmd.exe', 'wscript.exe', 'cscript.exe', 'powershell.exe', 'pwsh.exe', 'explorer.exe', 'conhost.exe', 'mshta.exe', 'regsvr32.exe', 'dllhost.exe', 'svchost.exe') { return '' }
    return $p
}
# $true nur, wenn das Ziel sicher fehlt: festes, bereites Laufwerk und weder Datei noch Ordner vorhanden (auch nicht 32/64-Bit-Gegenstück)
function Test-CcPathMissing([string]$Path) {
    if (-not $Path -or $Path -notmatch '^[A-Za-z]:\\') { return $false }
    try { $d = New-Object IO.DriveInfo ([IO.Path]::GetPathRoot($Path)); if (-not $d.IsReady -or [string]$d.DriveType -ne 'Fixed') { return $false } } catch { return $false }
    if ([IO.File]::Exists($Path) -or [IO.Directory]::Exists($Path)) { return $false }
    $alts = [System.Collections.Generic.List[string]]::new()
    $sys32 = [IO.Path]::Combine($env:SystemRoot, 'System32'); $wow = [IO.Path]::Combine($env:SystemRoot, 'SysWOW64'); $nat = [IO.Path]::Combine($env:SystemRoot, 'Sysnative')
    if ($Path.StartsWith($sys32 + '\', 'OrdinalIgnoreCase')) { $alts.Add($wow + $Path.Substring($sys32.Length)); $alts.Add($nat + $Path.Substring($sys32.Length)) }
    if ($Path.StartsWith($wow + '\', 'OrdinalIgnoreCase')) { $alts.Add($sys32 + $Path.Substring($wow.Length)) }
    if ($Path -match '\\Program Files \(x86\)\\') { $alts.Add(($Path -replace '\\Program Files \(x86\)\\', '\Program Files\')) }
    elseif ($Path -match '\\Program Files\\') { $alts.Add(($Path -replace '\\Program Files\\', '\Program Files (x86)\')) }
    foreach ($a in $alts) { if ([IO.File]::Exists($a) -or [IO.Directory]::Exists($a)) { return $false } }
    return $true
}
function ConvertTo-CcPackedGuid([string]$Guid) {
    $h = ($Guid -replace '[\{\}\-]', '').ToUpper()
    if ($h -notmatch '^[0-9A-F]{32}$') { return '' }
    $rev = { param($s) $a = $s.ToCharArray(); [Array]::Reverse($a); -join $a }
    $o = (& $rev $h.Substring(0, 8)) + (& $rev $h.Substring(8, 4)) + (& $rev $h.Substring(12, 4))
    for ($i = 16; $i -lt 32; $i += 2) { $o += [string]$h[$i + 1] + [string]$h[$i] }
    return $o
}
function Test-CcMsiRegistered([string]$Guid) {
    $pk = ConvertTo-CcPackedGuid $Guid
    if (-not $pk) { return $true }
    foreach ($x in @(@('HKLM', 'SOFTWARE\Classes\Installer\Products\' + $pk), @('HKCU', 'Software\Microsoft\Installer\Products\' + $pk), @('HKLM', 'SOFTWARE\Microsoft\Windows\CurrentVersion\Installer\UserData\S-1-5-18\Products\' + $pk))) {
        $k = Open-CcRegKey $x[0] $x[1]; if ($k) { $k.Close(); return $true }
    }
    return $false
}
function Get-CcRegFindings([string[]]$Cats, $Prog) {
    $names = Get-CcRegCatNames
    $out = [System.Collections.Generic.List[object]]::new()
    $add = { param($cat, $hive, $path, $val, $act, $data, $prob)
        $out.Add([pscustomobject]@{ CatKey = $cat; Cat = $names[$cat]; Hive = $hive; Path = $path; Value = $val; Action = $act; Data = [string]$data; Problem = $prob
            Key = ('{0}\{1}' -f $hive, $path) + $(if ($val) { '  [' + $val + ']' } elseif ($act -eq 'ClearDefault') { '  [(Standard)]' } else { '' }) }) }
    $step = { param($t) if ($Prog) { $Prog.Text = $t } }
    $up = 'SOFTWARE\Microsoft\Windows\CurrentVersion'
    if ($Cats -contains 'SharedDll') {
        & $step $names['SharedDll']
        foreach ($p in @("$up\SharedDLLs", 'SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\SharedDLLs')) {
            $k = Open-CcRegKey 'HKLM' $p; if (-not $k) { continue }
            try { foreach ($v in $k.GetValueNames()) { $f = [Environment]::ExpandEnvironmentVariables($v); if (Test-CcPathMissing $f) { & $add 'SharedDll' 'HKLM' $p $v 'DeleteValue' $f 'Datei fehlt - Zählereintrag ohne Datei' } } } finally { $k.Close() }
        }
    }
    if ($Cats -contains 'AppPaths') {
        & $step $names['AppPaths']
        foreach ($x in @(@('HKLM', "$up\App Paths"), @('HKLM', 'SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\App Paths'), @('HKCU', "Software\Microsoft\Windows\CurrentVersion\App Paths"))) {
            $k = Open-CcRegKey $x[0] $x[1]; if (-not $k) { continue }
            try {
                foreach ($s in $k.GetSubKeyNames()) {
                    $sk = $null; try { $sk = $k.OpenSubKey($s) } catch { }; if (-not $sk) { continue }
                    try { $ref = Get-CcRefPath ([string]$sk.GetValue('')); if ($ref -and (Test-CcPathMissing $ref)) { & $add 'AppPaths' $x[0] ($x[1] + '\' + $s) '' 'DeleteKey' $ref ('"{0}" zeigt auf ein fehlendes Programm' -f $s) } } finally { $sk.Close() }
                }
            } finally { $k.Close() }
        }
    }
    if ($Cats -contains 'Uninstall') {
        & $step $names['Uninstall']
        foreach ($x in @(@('HKLM', "$up\Uninstall"), @('HKLM', 'SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall'), @('HKCU', 'Software\Microsoft\Windows\CurrentVersion\Uninstall'))) {
            $k = Open-CcRegKey $x[0] $x[1]; if (-not $k) { continue }
            try {
                foreach ($s in $k.GetSubKeyNames()) {
                    $sk = $null; try { $sk = $k.OpenSubKey($s) } catch { }; if (-not $sk) { continue }
                    try {
                        $dn = [string]$sk.GetValue('DisplayName'); if (-not $dn) { continue }
                        $un = [string]$sk.GetValue('UninstallString'); $loc = ([string]$sk.GetValue('InstallLocation')).Trim().Trim('"')
                        $locGone = (-not $loc) -or (Test-CcPathMissing $loc)
                        $isMsi = ($un -match '(?i)msiexec') -or ([string]$sk.GetValue('WindowsInstaller') -eq '1')
                        if ($isMsi) {
                            $g = ''; if ($s -match '^\{[0-9A-Fa-f\-]{36}\}$') { $g = $s } elseif ($un -match '\{[0-9A-Fa-f\-]{36}\}') { $g = $Matches[0] }
                            if ($g -and -not (Test-CcMsiRegistered $g) -and $locGone) { & $add 'Uninstall' $x[0] ($x[1] + '\' + $s) '' 'DeleteKey' $g ('"{0}": Windows Installer kennt das Produkt nicht mehr' -f $dn) }
                        } else {
                            $ref = Get-CcRefPath $un
                            if ($ref -and (Test-CcPathMissing $ref) -and $locGone) { & $add 'Uninstall' $x[0] ($x[1] + '\' + $s) '' 'DeleteKey' $ref ('"{0}": Deinstallationsprogramm und Programmordner fehlen' -f $dn) }
                        }
                    } finally { $sk.Close() }
                }
            } finally { $k.Close() }
        }
    }
    if ($Cats -contains 'FileTypes') {
        & $step $names['FileTypes']
        $skip = @('*', 'CLSID', 'Interface', 'TypeLib', 'Installer', 'AppID', 'WOW6432Node', 'Local Settings', 'Directory', 'Drive', 'Folder', 'AllFilesystemObjects', 'DesktopBackground', 'Unknown', 'exefile', 'batfile', 'cmdfile', 'comfile', 'lnkfile', 'regfile', 'Msi.Package', 'Msi.Patch', 'SystemFileAssociations', 'MIME', 'Extensions', 'PackagedCom', 'ActivatableClasses')
        foreach ($x in @(@('HKLM', 'SOFTWARE\Classes'), @('HKCU', 'Software\Classes'))) {
            $k = Open-CcRegKey $x[0] $x[1]; if (-not $k) { continue }
            try {
                $progIds = @($k.GetSubKeyNames() | Where-Object { $_ -notlike '.*' -and $skip -notcontains $_ -and $_ -notlike 'AppX*' -and $_ -notlike 'Microsoft.*' -and $_ -notlike 'Windows.*' })
                $apps = @(); $ak = $k.OpenSubKey('Applications'); if ($ak) { $apps = @($ak.GetSubKeyNames() | ForEach-Object { 'Applications\' + $_ }); $ak.Close() }
                foreach ($pid2 in @($progIds | Where-Object { $_ -ne 'Applications' }) + $apps) {
                    $sh = $null; try { $sh = $k.OpenSubKey($pid2 + '\shell') } catch { }; if (-not $sh) { continue }
                    try {
                        foreach ($verb in $sh.GetSubKeyNames()) {
                            $ck = $null; try { $ck = $sh.OpenSubKey($verb + '\command') } catch { }; if (-not $ck) { continue }
                            try {
                                if ($null -ne $ck.GetValue('DelegateExecute')) { continue }
                                $ref = Get-CcRefPath ([string]$ck.GetValue(''))
                                if ($ref -and (Test-CcPathMissing $ref)) {
                                    if ($pid2 -like 'Applications\*') { & $add 'FileTypes' $x[0] ($x[1] + '\' + $pid2) '' 'DeleteKey' $ref ('"Öffnen mit"-Eintrag {0}: Programm fehlt' -f $pid2.Substring(13)) }
                                    else { & $add 'FileTypes' $x[0] ($x[1] + '\' + $pid2 + '\shell\' + $verb) '' 'DeleteKey' $ref ('Befehl "{0}" von {1}: Programm fehlt' -f $verb, $pid2) }
                                }
                            } finally { $ck.Close() }
                        }
                    } finally { $sh.Close() }
                }
            } finally { $k.Close() }
        }
    }
    if ($Cats -contains 'Run') {
        & $step $names['Run']
        foreach ($x in @(@('HKLM', "$up\Run"), @('HKLM', "$up\RunOnce"), @('HKLM', 'SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Run'), @('HKLM', 'SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\RunOnce'), @('HKCU', 'Software\Microsoft\Windows\CurrentVersion\Run'), @('HKCU', 'Software\Microsoft\Windows\CurrentVersion\RunOnce'))) {
            $k = Open-CcRegKey $x[0] $x[1]; if (-not $k) { continue }
            try { foreach ($v in $k.GetValueNames()) { if (-not $v) { continue }; $ref = Get-CcRefPath ([string]$k.GetValue($v)); if ($ref -and (Test-CcPathMissing $ref)) { & $add 'Run' $x[0] $x[1] $v 'DeleteValue' $ref ('Autostart "{0}": Datei fehlt' -f $v) } } } finally { $k.Close() }
        }
    }
    if ($Cats -contains 'Help') {
        & $step $names['Help']
        foreach ($p in @('SOFTWARE\Microsoft\Windows\Help', 'SOFTWARE\Microsoft\Windows\HTML Help', 'SOFTWARE\WOW6432Node\Microsoft\Windows\Help', 'SOFTWARE\WOW6432Node\Microsoft\Windows\HTML Help')) {
            $k = Open-CcRegKey 'HKLM' $p; if (-not $k) { continue }
            try {
                foreach ($v in $k.GetValueNames()) {
                    if (-not $v) { continue }
                    $dir = [Environment]::ExpandEnvironmentVariables([string]$k.GetValue($v)).Trim().Trim('"')
                    if (-not $dir -or $dir -notmatch '^[A-Za-z]:\\') { continue }
                    $f = [IO.Path]::Combine($dir, $v)
                    if (Test-CcPathMissing $f) { & $add 'Help' 'HKLM' $p $v 'DeleteValue' $f ('Hilfedatei {0} fehlt' -f $v) }
                }
            } finally { $k.Close() }
        }
    }
    if ($Cats -contains 'Installer') {
        & $step $names['Installer']
        $p = "$up\Installer\Folders"
        $k = Open-CcRegKey 'HKLM' $p
        if ($k) { try { foreach ($v in $k.GetValueNames()) { if ($v -and (Test-CcPathMissing $v.TrimEnd('\'))) { & $add 'Installer' 'HKLM' $p $v 'DeleteValue' $v 'Ordner aus einer früheren Installation existiert nicht mehr' } } } finally { $k.Close() } }
    }
    if ($Cats -contains 'Fonts') {
        & $step $names['Fonts']
        $fd = [IO.Path]::Combine($env:SystemRoot, 'Fonts')
        foreach ($h in 'HKLM', 'HKCU') {
            $p = 'SOFTWARE\Microsoft\Windows NT\CurrentVersion\Fonts'
            $k = Open-CcRegKey $h $p; if (-not $k) { continue }
            try {
                foreach ($v in $k.GetValueNames()) {
                    if (-not $v) { continue }
                    $d = [Environment]::ExpandEnvironmentVariables([string]$k.GetValue($v)).Trim()
                    if (-not $d) { continue }
                    $f = if ($d -match '^[A-Za-z]:\\') { $d } elseif ($d -notmatch '\\') { [IO.Path]::Combine($fd, $d) } else { '' }
                    if ($f -and (Test-CcPathMissing $f)) { & $add 'Fonts' $h $p $v 'DeleteValue' $f ('Schriftart "{0}": Datei fehlt' -f $v) }
                }
            } finally { $k.Close() }
        }
    }
    if ($Cats -contains 'Sounds') {
        & $step $names['Sounds']
        $media = [IO.Path]::Combine($env:SystemRoot, 'Media')
        $k = Open-CcRegKey 'HKCU' 'AppEvents\Schemes\Apps'
        if ($k) {
            try {
                foreach ($app in $k.GetSubKeyNames()) {
                    $ak = $k.OpenSubKey($app); if (-not $ak) { continue }
                    try {
                        foreach ($ev in $ak.GetSubKeyNames()) {
                            $ck = $ak.OpenSubKey($ev + '\.Current'); if (-not $ck) { continue }
                            try {
                                $d = [Environment]::ExpandEnvironmentVariables([string]$ck.GetValue('')).Trim().Trim('"')
                                if (-not $d) { continue }
                                $f = if ($d -match '^[A-Za-z]:\\') { $d } elseif ($d -notmatch '\\') { [IO.Path]::Combine($media, $d) } else { '' }
                                if ($f -and (Test-CcPathMissing $f)) { & $add 'Sounds' 'HKCU' ('AppEvents\Schemes\Apps\{0}\{1}\.Current' -f $app, $ev) '' 'ClearDefault' $f ('Klang "{0}" ({1}): Datei fehlt - wird auf "kein Klang" gesetzt' -f $ev, $app) }
                            } finally { $ck.Close() }
                        }
                    } finally { $ak.Close() }
                }
            } finally { $k.Close() }
        }
    }
    return , $out
}
# Sicherung (reg.exe export) und Änderung; ohne erfolgreiche Sicherung wird NICHTS geändert
function Invoke-CcRegFix($Rows, [string]$Dir, [string]$Title = 'Registry-Reinigung') {
    $res = [System.Collections.Generic.List[object]]::new()
    $null = New-Item -Path $Dir -ItemType Directory -Force -ErrorAction SilentlyContinue
    $exported = @{}; $idx = [System.Collections.Generic.List[object]]::new(); $n = 0
    $reg = [IO.Path]::Combine($env:SystemRoot, 'System32\reg.exe')
    foreach ($r in @($Rows)) {
        $k = '{0}\{1}' -f $r.Hive, $r.Path
        if (-not $exported.ContainsKey($k)) {
            $n++
            $leaf = (($r.Path -split '\\')[-1] -replace '[^A-Za-z0-9_\-\.]', '_'); if ($leaf.Length -gt 60) { $leaf = $leaf.Substring(0, 60) }
            $file = [IO.Path]::Combine($Dir, ('{0:D3}_{1}.reg' -f $n, $leaf))
            $null = & $reg export $k $file /y /reg:64 2>&1
            if ($LASTEXITCODE -eq 0 -and [IO.File]::Exists($file)) { $exported[$k] = $file; $idx.Add([pscustomobject]@{ File = [IO.Path]::GetFileName($file); Key = $k }) } else { $exported[$k] = '' }
        }
        $ok = $false; $msg = ''
        if (-not $exported[$k]) { $msg = 'Sicherung nicht möglich - nicht geändert' }
        else {
            try {
                switch ($r.Action) {
                    'DeleteValue' { $kk = Open-CcRegKey $r.Hive $r.Path $true; if (-not $kk) { throw 'Schlüssel nicht beschreibbar' }; try { $kk.DeleteValue([string]$r.Value, $false) } finally { $kk.Close() } }
                    'ClearDefault' { $kk = Open-CcRegKey $r.Hive $r.Path $true; if (-not $kk) { throw 'Schlüssel nicht beschreibbar' }; try { $kk.SetValue('', '') } finally { $kk.Close() } }
                    'DeleteKey' {
                        $i = $r.Path.LastIndexOf('\'); if ($i -lt 1) { throw 'Pfad zu kurz' }
                        $pk = Open-CcRegKey $r.Hive $r.Path.Substring(0, $i) $true; if (-not $pk) { throw 'Schlüssel nicht beschreibbar' }
                        try { $pk.DeleteSubKeyTree($r.Path.Substring($i + 1), $false) } finally { $pk.Close() }
                    }
                }
                $ok = $true; $msg = 'erledigt'
            } catch { $msg = 'Fehler: ' + $_.Exception.Message }
        }
        $res.Add([pscustomobject]@{ Key = $r.Key; Ok = $ok; Msg = $msg; Problem = $r.Problem })
    }
    try {
        $okRows = @($res | Where-Object { $_.Ok })
        [pscustomobject]@{ Time = (Get-Date).ToString('dd.MM.yyyy HH:mm:ss'); Title = $Title; Count = $okRows.Count; Files = @($idx); Changes = @($res | ForEach-Object { '{0} - {1} ({2})' -f $_.Key, $_.Problem, $_.Msg }) } | ConvertTo-Json -Depth 4 | Set-Content -LiteralPath ([IO.Path]::Combine($Dir, 'index.json')) -Encoding UTF8
        $cmd = @('@echo off', 'rem PC-Tools: Registry-Sicherung zurückspielen (als Administrator ausführen)', 'cd /d "%~dp0"') + @($idx | ForEach-Object { 'reg import "{0}" /reg:64' -f $_.File }) + @('echo Fertig.', 'pause')
        Set-Content -LiteralPath ([IO.Path]::Combine($Dir, 'Wiederherstellen.cmd')) -Value $cmd -Encoding Default
        $lst = @(('{0} - {1}' -f $Title, (Get-Date).ToString('dd.MM.yyyy HH:mm:ss')), '') + @($res | ForEach-Object { '{0}  {1}{2}    {3}' -f $(if ($_.Ok) { '[OK]  ' } else { '[--]  ' }), $_.Key, [Environment]::NewLine, $_.Problem })
        Set-Content -LiteralPath ([IO.Path]::Combine($Dir, 'Liste.txt')) -Value $lst -Encoding UTF8
    } catch { }
    return , $res
}
function Get-CcRegBackups([string]$Root) {
    $o = [System.Collections.Generic.List[object]]::new()
    if (-not [IO.Directory]::Exists($Root)) { return , $o }
    foreach ($d in @([IO.Directory]::GetDirectories($Root) | Sort-Object -Descending)) {
        $j = $null; try { $j = [IO.File]::ReadAllText([IO.Path]::Combine($d, 'index.json')) | ConvertFrom-Json } catch { }
        $files = @([IO.Directory]::GetFiles($d, '*.reg'))
        $o.Add([pscustomobject]@{ Time = $(if ($j) { [string]$j.Time } else { [IO.Path]::GetFileName($d) }); Title = $(if ($j -and $j.Title) { [string]$j.Title } else { 'Registry-Sicherung' }); Count = $(if ($j) { [int]$j.Count } else { $files.Count }); Files = $files.Count; Dir = $d; Folder = [IO.Path]::GetFileName($d) })
    }
    return , $o
}
function Restore-CcRegBackup([string]$Dir) {
    $ok = 0; $bad = 0
    $reg = [IO.Path]::Combine($env:SystemRoot, 'System32\reg.exe')
    foreach ($f in @([IO.Directory]::GetFiles($Dir, '*.reg') | Sort-Object)) {
        $null = & $reg import $f /reg:64 2>&1
        if ($LASTEXITCODE -eq 0) { $ok++ } else { $bad++ }
    }
    return [pscustomobject]@{ Ok = $ok; Bad = $bad }
}

# =====================================================================
#  Programme (Win32 aus HKLM/HKCU/WOW6432Node und Store-Apps)
# =====================================================================
function Split-CcCommand([string]$Cmd) {
    $c = [Environment]::ExpandEnvironmentVariables(([string]$Cmd).Trim())
    if ($c -match '^"([^"]+)"\s*(.*)$') { return @($Matches[1], $Matches[2].Trim()) }
    if ($c -match '^(.+?\.(exe|cmd|bat|com))(\s+(.*))?$') { return @($Matches[1], ([string]$Matches[4]).Trim()) }
    return @($c, '')
}
function Get-CcPrograms([bool]$Store = $true) {
    $list = [System.Collections.Generic.List[object]]::new()
    $srcs = @(@('HKLM', 'SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall', 'Alle Benutzer'), @('HKLM', 'SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall', 'Alle Benutzer (32 Bit)'), @('HKCU', 'Software\Microsoft\Windows\CurrentVersion\Uninstall', 'Nur dieser Benutzer'))
    foreach ($src in $srcs) {
        $k = Open-CcRegKey $src[0] $src[1]; if (-not $k) { continue }
        try {
            foreach ($s in $k.GetSubKeyNames()) {
                $sk = $null; try { $sk = $k.OpenSubKey($s) } catch { }; if (-not $sk) { continue }
                try {
                    $dn = [string]$sk.GetValue('DisplayName'); if (-not $dn) { continue }
                    if ([string]$sk.GetValue('SystemComponent') -eq '1' -or [string]$sk.GetValue('ParentKeyName') -or ([string]$sk.GetValue('ReleaseType')) -match 'Update|Hotfix') { continue }
                    $un = [string]$sk.GetValue('UninstallString'); $q = [string]$sk.GetValue('QuietUninstallString'); $mod = [string]$sk.GetValue('ModifyPath')
                    $isMsi = ([string]$sk.GetValue('WindowsInstaller') -eq '1') -or ($un -match '(?i)msiexec')
                    $g = ''; if ($s -match '^\{[0-9A-Fa-f\-]{36}\}$') { $g = $s } elseif ($isMsi -and $un -match '\{[0-9A-Fa-f\-]{36}\}') { $g = $Matches[0] }
                    $orphan = $false
                    if ($isMsi -and $g) { $orphan = -not (Test-CcMsiRegistered $g) }
                    elseif (-not $un) { $orphan = $true }
                    else { $ref = Get-CcRefPath $un; $orphan = [bool]($ref -and (Test-CcPathMissing $ref)) }
                    $est = [int64]0; try { $est = [int64]$sk.GetValue('EstimatedSize', 0) * 1KB } catch { }
                    $dt = $null; $idt = [string]$sk.GetValue('InstallDate')
                    if ($idt -match '^(\d{4})(\d{2})(\d{2})$') { try { $dt = Get-Date -Year ([int]$Matches[1]) -Month ([int]$Matches[2]) -Day ([int]$Matches[3]) -Hour 0 -Minute 0 -Second 0 } catch { } }
                    $loc = ([string]$sk.GetValue('InstallLocation')).Trim().Trim('"')
                    $list.Add([pscustomobject]@{
                        Kind = 'Programm'; Name = $dn; Publisher = [string]$sk.GetValue('Publisher'); Version = [string]$sk.GetValue('DisplayVersion')
                        Size = $est; SizeText = $(if ($est -gt 0) { Format-CcSize $est } else { '' }); Date = $dt; DateText = $(if ($dt) { $dt.ToString('dd.MM.yyyy') } else { '' })
                        Scope = $src[2]; Hive = $src[0]; Path = ($src[1] + '\' + $s); KeyName = $s; Uninstall = $un; Quiet = $q; Modify = $mod
                        CanModify = [bool]($mod -and [string]$sk.GetValue('NoModify') -ne '1'); CanRepair = [bool]($isMsi -and $g -and [string]$sk.GetValue('NoRepair') -ne '1')
                        Msi = $isMsi; Guid = $g; Location = $loc; Orphan = $orphan; Pkg = ''; Pfn = ''
                        KindText = $(if ($orphan) { 'Eintrag verwaist' } elseif ($isMsi) { 'Desktop (MSI)' } else { 'Desktop' })
                        Level = $(if ($orphan) { 'Warn' } else { '' })
                    })
                } finally { $sk.Close() }
            }
        } finally { $k.Close() }
    }
    if ($Store) {
        try {
            $names = @{}
            try { foreach ($a in @(Get-StartApps -ErrorAction Stop)) { $id = [string]$a.AppID; if ($id -match '^([^!]+)!') { if (-not $names.ContainsKey($Matches[1])) { $names[$Matches[1]] = [string]$a.Name } } } } catch { }
            foreach ($p in @(Get-AppxPackage -ErrorAction Stop | Where-Object { -not $_.IsFramework -and [string]$_.SignatureKind -ne 'System' -and $_.NonRemovable -ne $true -and -not $_.IsResourcePackage })) {
                $pfn = [string]$p.PackageFamilyName
                $nm = if ($names.ContainsKey($pfn)) { $names[$pfn] } else { ([string]$p.Name -replace '^[^.]+\.', '') }
                $dt = $null; try { if ($p.InstallLocation) { $dt = [IO.Directory]::GetCreationTime([string]$p.InstallLocation) } } catch { }
                $pub = ([string]$p.Publisher -replace '^CN=([^,]+).*$', '$1')
                $list.Add([pscustomobject]@{
                    Kind = 'Store-App'; Name = $nm; Publisher = $pub; Version = [string]$p.Version; Size = [int64]0; SizeText = ''
                    Date = $dt; DateText = $(if ($dt) { $dt.ToString('dd.MM.yyyy') } else { '' }); Scope = 'Dieser Benutzer'; Hive = ''; Path = ''; KeyName = [string]$p.Name
                    Uninstall = ''; Quiet = ''; Modify = ''; CanModify = $false; CanRepair = $false; Msi = $false; Guid = ''; Location = [string]$p.InstallLocation; Orphan = $false
                    Pkg = [string]$p.PackageFullName; Pfn = $pfn; KindText = 'Store-App'; Level = ''
                })
            }
        } catch { }
    }
    return , $list
}
function Test-CcProgramPresent($P) {
    if ($P.Kind -eq 'Store-App') { return [bool](@(Get-AppxPackage -Name $P.KeyName -ErrorAction SilentlyContinue).Count) }
    $k = Open-CcRegKey $P.Hive $P.Path
    if ($k) { $k.Close(); return $true }
    return $false
}
# Deinstallation; wartet auch auf Deinstallationsprogramme, die eine Kopie starten und sich sofort beenden
function Invoke-CcUninstall($P, [bool]$Quiet) {
    if ($P.Kind -eq 'Store-App') {
        Remove-AppxPackage -Package $P.Pkg -ErrorAction Stop
        return [pscustomobject]@{ Code = 0; Removed = -not (Test-CcProgramPresent $P); Cmd = 'Remove-AppxPackage ' + $P.Pkg }
    }
    $exe = ''; $arg = ''
    if ($P.Msi -and $P.Guid) { $exe = [IO.Path]::Combine($env:SystemRoot, 'System32\msiexec.exe'); $arg = '/x {0}' -f $P.Guid; if ($Quiet) { $arg += ' /qn /norestart' } }
    else {
        $cmd = if ($Quiet -and $P.Quiet) { $P.Quiet } else { $P.Uninstall }
        if (-not $cmd) { throw 'Für dieses Programm ist kein Deinstallationsbefehl eingetragen.' }
        $sp = Split-CcCommand $cmd; $exe = $sp[0]; $arg = $sp[1]
        if (-not [IO.File]::Exists($exe)) { throw ('Das Deinstallationsprogramm fehlt: {0} - der Eintrag ist verwaist ("Verwaisten Eintrag entfernen").' -f $exe) }
    }
    $t0 = Get-Date
    $pr = if ($arg) { Start-Process -FilePath $exe -ArgumentList $arg -PassThru -ErrorAction Stop } else { Start-Process -FilePath $exe -PassThru -ErrorAction Stop }
    $pr.WaitForExit()
    $code = $pr.ExitCode
    $rx = '^(un_?|unins|uninst|au_|_iu14d2n|_un|setup|msiexec|.*uninstall.*|.*deinst.*)'
    $sw = [Diagnostics.Stopwatch]::StartNew(); $idle = 0
    while ($sw.Elapsed.TotalMinutes -lt 15) {
        if (-not (Test-CcProgramPresent $P)) { break }
        $busy = @(Get-Process -ErrorAction SilentlyContinue | Where-Object { $_.Name -match $rx -and $(try { $_.StartTime -ge $t0 } catch { $false }) }).Count
        if ($busy) { $idle = 0 } else { $idle++ }
        if ($idle -ge 3) { break }
        Start-Sleep -Seconds 2
    }
    return [pscustomobject]@{ Code = $code; Removed = -not (Test-CcProgramPresent $P); Cmd = ('"{0}" {1}' -f $exe, $arg).Trim() }
}
function Get-CcCleanName([string]$Name) {
    $n = $Name -replace '\(.*?\)', '' -replace '\b(x64|x86|64-bit|32-bit|64 bit|32 bit|version|v)\b', '' -replace '\s\d+(\.\d+)+.*$', '' -replace '\s+\d+$', ''
    $n = $n -replace ',?\s+(Inc|Ltd|GmbH|AG|LLC|Corporation|Corp|Co|SE|S\.A|B\.V|Limited|Software)\.?$', ''
    return ($n -replace '\s{2,}', ' ').Trim(' ', '-', '.', ',')
}
# mögliche Reste nach der Deinstallation (Ordner und Registry) - nur exakte Namenstreffer, nie ganze Hersteller-Ordner bekannter Firmen
function Find-CcLeftovers($P) {
    $out = [System.Collections.Generic.List[object]]::new()
    $deny = @('microsoft', 'windows', 'common files', 'intel', 'nvidia', 'amd', 'google', 'mozilla', 'packages', 'temp', 'programs', 'microsoft corporation', 'windowsapps', 'installer', 'package cache', 'apple', 'adobe', 'oracle', 'java', 'dell', 'hp', 'lenovo', 'realtek', 'program files', 'users', 'public', 'system32', 'drivers', 'cache', 'data', 'logs', 'app', 'apps', 'tools', 'update', 'updater', 'software')
    $prod = Get-CcCleanName $P.Name
    $pub = Get-CcCleanName $P.Publisher
    $names = [System.Collections.Generic.List[string]]::new()
    foreach ($x in @($prod, ($prod -replace '\s', ''), $(if ($P.Location) { [IO.Path]::GetFileName($P.Location.TrimEnd('\')) } else { '' }))) { if ($x -and $x.Length -ge 4 -and $x -notmatch '[\\/:*?"<>|]' -and $deny -notcontains $x.ToLower() -and -not $names.Contains($x)) { $names.Add($x) } }
    # Namen und Ordner, die noch zu ANDEREN installierten Programmen gehören, nie vorschlagen (z.B. mehrere Python-Versionen)
    $others = @(Get-CcPrograms $false | ForEach-Object { $_ } | Where-Object { $_.Path -ne $P.Path -and -not $_.Orphan })
    $otherNames = @{}; foreach ($o in $others) { $cn = (Get-CcCleanName $o.Name).ToLower(); if ($cn) { $otherNames[$cn] = $true; $otherNames[($cn -replace '\s', '')] = $true } }
    $otherLocs = @($others | Where-Object { $_.Location -match '^[A-Za-z]:\\' } | ForEach-Object { $_.Location.TrimEnd('\').ToLower() })
    foreach ($x in @($names)) { if ($otherNames.ContainsKey($x.ToLower())) { [void]$names.Remove($x) } }
    if (-not $names.Count) { return , $out }
    $pubOk = [bool]($pub -and $pub.Length -ge 3 -and $pub -notmatch '[\\/:*?"<>|]' -and $deny -notcontains $pub.ToLower())
    $seen = @{}
    $addDir = { param($d, $why)
        if (-not $d -or -not [IO.Directory]::Exists($d)) { return }
        $k = $d.TrimEnd('\').ToLower(); if ($seen.ContainsKey($k)) { return }; $seen[$k] = $true
        foreach ($ol in $otherLocs) { if ($ol -eq $k -or $ol.StartsWith($k + '\')) { return } }
        $m = Invoke-CcFiles $d '*' $true 0 $false
        $out.Add([pscustomobject]@{ Sel = $true; Cat = 'Ordner'; Key = $d; Size = (Format-CcSize $m.Bytes); Problem = ('{0} ({1} Dateien)' -f $why, $m.Files); Kind = 'Dir'; Hive = ''; Path = $d })
    }
    $bases = [System.Collections.Generic.List[string]]::new()
    foreach ($b in @($env:ProgramFiles, ${env:ProgramFiles(x86)}, $env:ProgramData)) { if ($b -and -not $bases.Contains($b)) { $bases.Add($b) } }
    foreach ($pr in @(Get-CcProfiles | ForEach-Object { $_ })) { foreach ($s in 'AppData\Local', 'AppData\Roaming', 'AppData\LocalLow', 'AppData\Local\Programs') { $bases.Add([IO.Path]::Combine($pr.Root, $s)) } }
    if ($P.Location -and $P.Location -match '^[A-Za-z]:\\.+\\.+' -and [IO.Directory]::Exists($P.Location)) { & $addDir $P.Location.TrimEnd('\') 'Installationsordner ist noch vorhanden' }
    foreach ($b in $bases) {
        foreach ($nm in $names) {
            & $addDir ([IO.Path]::Combine($b, $nm)) 'Programmordner'
            if ($pubOk) {
                $pd = [IO.Path]::Combine($b, $pub)
                & $addDir ([IO.Path]::Combine($pd, $nm)) 'Programmordner beim Hersteller'
            }
        }
    }
    $regs = [System.Collections.Generic.List[object]]::new()
    foreach ($nm in $names) {
        foreach ($h in @(@('HKCU', 'Software'), @('HKLM', 'SOFTWARE'), @('HKLM', 'SOFTWARE\WOW6432Node'))) {
            $regs.Add(@($h[0], ('{0}\{1}' -f $h[1], $nm)))
            if ($pubOk) { $regs.Add(@($h[0], ('{0}\{1}\{2}' -f $h[1], $pub, $nm))) }
        }
    }
    foreach ($x in $regs) {
        $k = Open-CcRegKey $x[0] $x[1]; if (-not $k) { continue }
        $cnt = 0; try { $cnt = $k.ValueCount + $k.SubKeyCount } catch { }; $k.Close()
        $key = '{0}\{1}' -f $x[0], $x[1]
        if ($seen.ContainsKey($key.ToLower())) { continue }; $seen[$key.ToLower()] = $true
        $out.Add([pscustomobject]@{ Sel = $true; Cat = 'Registry'; Key = $key; Size = ''; Problem = ('Einstellungen des Programms ({0} Einträge)' -f $cnt); Kind = 'Reg'; Hive = $x[0]; Path = $x[1] })
    }
    return , $out
}
function Remove-CcLeftovers($Rows, [string]$BackupDir) {
    $msgs = [System.Collections.Generic.List[string]]::new()
    $dirs = @($Rows | Where-Object { $_.Kind -eq 'Dir' })
    if ($dirs.Count) {
        Add-Type -AssemblyName Microsoft.VisualBasic
        foreach ($d in $dirs) {
            try { [Microsoft.VisualBasic.FileIO.FileSystem]::DeleteDirectory([string]$d.Path, 'OnlyErrorDialogs', 'SendToRecycleBin'); $msgs.Add('Papierkorb: ' + $d.Path) }
            catch { $msgs.Add('nicht möglich (in Benutzung?): ' + $d.Path + ' - ' + $_.Exception.Message) }
        }
    }
    $regs = @($Rows | Where-Object { $_.Kind -eq 'Reg' } | ForEach-Object { [pscustomobject]@{ Hive = $_.Hive; Path = $_.Path; Value = ''; Action = 'DeleteKey'; Key = $_.Key; Problem = 'Rest nach Deinstallation' } })
    if ($regs.Count) { foreach ($r in @(Invoke-CcRegFix $regs $BackupDir 'Reste nach Deinstallation' | ForEach-Object { $_ })) { $msgs.Add($(if ($r.Ok) { 'Registry (gesichert und entfernt): ' } else { 'Registry nicht entfernt: ' }) + $r.Key + $(if (-not $r.Ok) { ' - ' + $r.Msg } else { '' })) } }
    return , $msgs
}

# ---- Nicht genutzte Programme finden (Liste) und nach EINER Bestätigung still samt Resten entfernen
# Nutzung aus drei Windows-Spuren: Prefetch (Programmstarts), BAM (alle Benutzer) und UserAssist (dieser Benutzer)
function Get-ProgUsageMap {
    $byExe = @{}; $byPath = @{}
    $upd = { param($k, $d, $h) if ($k -and $d -and $d.Year -gt 2000 -and (-not $h.ContainsKey($k) -or $h[$k] -lt $d)) { $h[$k] = $d } }
    try { foreach ($f in [IO.Directory]::GetFiles((Join-Path $env:windir 'Prefetch'), '*.pf')) { $n = [IO.Path]::GetFileName($f); if ($n -match '^(.+)-[0-9A-F]{8}\.pf$') { & $upd ($Matches[1].ToLower()) ([IO.File]::GetLastWriteTime($f)) $byExe } } } catch { }
    foreach ($root in 'HKLM:\SYSTEM\CurrentControlSet\Services\bam\State\UserSettings', 'HKLM:\SYSTEM\CurrentControlSet\Services\bam\UserSettings') {
        try {
            foreach ($sid in @(Get-ChildItem -LiteralPath $root -ErrorAction Stop)) {
                $k = Get-Item -LiteralPath $sid.PSPath -ErrorAction SilentlyContinue; if (-not $k) { continue }
                foreach ($vn in $k.GetValueNames()) { $v = $k.GetValue($vn); if ($v -is [byte[]] -and $v.Length -ge 8) { try { $d = [DateTime]::FromFileTime([BitConverter]::ToInt64($v, 0)); $p = ($vn -replace '^\\Device\\HarddiskVolume\d+', '').ToLower(); & $upd $p $d $byPath; & $upd ([IO.Path]::GetFileName($p)) $d $byExe } catch { } } }
            }
        } catch { }
    }
    try {
        $kf = @{ '{6D809377-6AF0-444B-8957-A3773F02200E}' = $env:ProgramFiles; '{7C5A40EF-A0FB-4BFC-874A-C0F2E0B9FA8E}' = ${env:ProgramFiles(x86)}; '{F38BF404-1D43-42F2-9305-67DE0B28FC23}' = $env:windir; '{1AC14E77-02E7-4E5D-B744-2EB1AE5198B7}' = (Join-Path $env:windir 'System32') }
        $k = Get-Item -LiteralPath 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\UserAssist\{CEBFF5CD-ACE2-4F4F-9178-9926F41749EA}\Count' -ErrorAction Stop
        foreach ($vn in $k.GetValueNames()) {
            $v = $k.GetValue($vn); if (-not ($v -is [byte[]]) -or $v.Length -lt 68) { continue }
            $ft = [BitConverter]::ToInt64($v, 60); if ($ft -le 0) { continue }
            $d = [DateTime]::FromFileTime($ft)
            $nm = -join ($vn.ToCharArray() | ForEach-Object { $c = [int]$_; if ($c -ge 65 -and $c -le 90) { [char](65 + ($c - 65 + 13) % 26) } elseif ($c -ge 97 -and $c -le 122) { [char](97 + ($c - 97 + 13) % 26) } else { $_ } })
            foreach ($g in @($kf.Keys)) { if ($nm.StartsWith($g, [StringComparison]::OrdinalIgnoreCase)) { $nm = $kf[$g] + $nm.Substring($g.Length) } }
            if ($nm -notmatch '\.exe$') { continue }
            $p = ($nm -replace '^[A-Za-z]:', '').ToLower(); & $upd $p $d $byPath; & $upd ([IO.Path]::GetFileName($p)) $d $byExe
        }
    } catch { }
    return @{ Exe = $byExe; Path = $byPath }
}
# nie vorgeschlagen: Laufzeiten, Treiber/Hersteller-Werkzeuge, Sicherheit, Sicherung, VPN/Fernwartung, Office, Drucker
$UnusedProtect = '(?i)visual c\+\+|redistributable|\.net (framework|runtime|desktop|core)|asp\.net|windows (sdk|software development|driver kit|app cert|desktop runtime|pc health|subsystem)|microsoft (edge|update health|visual studio|office|365|onedrive|teams|webview|policy platform|gameinput|search|support|odbc|access database|sql|silverlight|xna)|webview2|directx|physx|vulkan|openal|\bjava\b|\bjre\b|\bjdk\b|python launcher|driver|treiber|chipset|\bintel\b|realtek|nvidia|\bamd\b|radeon|synaptics|\belan\b|\balps\b|dolby|waves|conexant|bluetooth|wacom|thunderbolt|firmware|\bbios\b|hp (support|smart|hotkey|audio|wolf|sure|connection|documentation|system|programmable)|dell (command|update|optimizer|power|digital)|lenovo (vantage|system|hotkey|power|commercial)|surface|logitech|corsair|razer|steelseries|antivir|security|defender|endpoint|bitdefender|kaspersky|\beset\b|avast|\bavg\b|avira|norton|mcafee|sophos|malwarebytes|g data|f-secure|trend micro|panda|webroot|veeam|acronis|backup|sicherung|\bvpn\b|wireguard|openvpn|forticlient|anyconnect|globalprotect|citrix|vmware|virtualbox|hyper-v|pc-tools|pcpflege|bonjour|apple (mobile device|application support|software update)|google update|windows update|rsat|sql server|crystal reports|adobe (acrobat|reader|genuine|creative cloud)|teamviewer|anydesk|remote|printer|drucker|scanner|canon|epson|brother|kyocera|ricoh|xerox|lexmark|konica'
function Get-ProgExeNames([string]$Loc) {
    $l = [System.Collections.Generic.List[string]]::new()
    if (-not $Loc -or -not [IO.Directory]::Exists($Loc)) { return , $l }
    try { $n = 0; foreach ($f in [IO.Directory]::EnumerateFiles($Loc, '*.exe', [IO.SearchOption]::AllDirectories)) { $n++; if ($n -gt 400) { break }; $l.Add($f) } } catch { }
    return , $l
}
# stiller Deinstallationsweg: MSI, Herstellerangabe, Inno Setup, NSIS, Squirrel - sonst $null (dann nur von Hand)
function Get-SilentUninstallCmd($P) {
    if ($P.Msi -and $P.Guid) { return [pscustomobject]@{ Exe = [IO.Path]::Combine($env:SystemRoot, 'System32\msiexec.exe'); Args = ('/x {0} /qn /norestart REBOOT=ReallySuppress' -f $P.Guid); How = 'MSI' } }
    if ($P.Quiet) { try { $sp = Split-CcCommand $P.Quiet; if ([IO.File]::Exists($sp[0])) { return [pscustomobject]@{ Exe = $sp[0]; Args = [string]$sp[1]; How = 'Hersteller (still)' } } } catch { } }
    if (-not $P.Uninstall) { return $null }
    # von winget installierte portable Programme: "winget uninstall --product-code ..."
    if ([string]$P.Uninstall -match '^\s*"?winget(\.exe)?"?\s+(uninstall\s.+)$') {
        $wg = ''; try { $wg = (Get-Command winget.exe -ErrorAction Stop).Source } catch { }
        if ($wg) { return [pscustomobject]@{ Exe = $wg; Args = ($Matches[2] + ' --silent --force --accept-source-agreements --disable-interactivity'); How = 'winget' } }
    }
    $sp = $null; try { $sp = Split-CcCommand $P.Uninstall } catch { return $null }
    $exe = [string]$sp[0]; $a = [string]$sp[1]; if (-not [IO.File]::Exists($exe)) { return $null }
    $fn = [IO.Path]::GetFileName($exe).ToLower()
    if ($fn -eq 'msiexec.exe' -and $a -match '\{[0-9A-Fa-f\-]{36}\}') { return [pscustomobject]@{ Exe = $exe; Args = ('/x {0} /qn /norestart REBOOT=ReallySuppress' -f $Matches[0]); How = 'MSI' } }
    $vi = $null; try { $vi = [Diagnostics.FileVersionInfo]::GetVersionInfo($exe) } catch { }
    $desc = if ($vi) { '{0} {1} {2} {3}' -f $vi.FileDescription, $vi.Comments, $vi.ProductName, $vi.LegalCopyright } else { '' }
    if ($fn -match '^unins\d{3}\.exe$' -or $desc -match '(?i)inno setup') { return [pscustomobject]@{ Exe = $exe; Args = ($a + ' /VERYSILENT /SUPPRESSMSGBOXES /NORESTART').Trim(); How = 'Inno Setup' } }
    if ($fn -eq 'update.exe' -and $a -match '(?i)--uninstall') { return [pscustomobject]@{ Exe = $exe; Args = ($a + ' -s').Trim(); How = 'Squirrel' } }
    # WiX-Burn-Pakete (Package Cache ... /uninstall)
    if ($a -match '(?i)(^|\s)/uninstall(\s|$)' -and $exe -match '(?i)\\Package Cache\\') { return [pscustomobject]@{ Exe = $exe; Args = ($a + ' /quiet /norestart').Trim(); How = 'WiX/Burn' } }
    $isNsis = $false
    try { $fs = [IO.File]::OpenRead($exe); try { $buf = New-Object byte[] ([Math]::Min([int64]4194304, $fs.Length)); [void]$fs.Read($buf, 0, $buf.Length) } finally { $fs.Close() }; $isNsis = ([Text.Encoding]::ASCII.GetString($buf) -match 'Nullsoft|NSIS Error|nsis\.sf\.net') } catch { }
    # electron-builder (NSIS): "Uninstall <Name>.exe"
    if (-not $isNsis -and $fn -match '^uninstall .+\.exe$') { $isNsis = $true }
    if ($isNsis) { return [pscustomobject]@{ Exe = $exe; Args = (($a -replace '(?i)(^|\s)/S(\s|$)', ' ') + ' /S').Trim(); How = 'NSIS' } }
    return $null
}
function Get-UnusedPrograms([int]$Days = 180) {
    $use = Get-ProgUsageMap
    $cut = (Get-Date).AddDays(-$Days)
    $svcPaths = @(); try { $svcPaths = @(Get-CimInstance Win32_Service -ErrorAction Stop | Where-Object { [string]$_.StartMode -match '^Auto' -and $_.PathName } | ForEach-Object { ([string]$_.PathName).Trim().Trim('"').ToLower() }) } catch { }
    $procPaths = @(Get-Process -ErrorAction SilentlyContinue | ForEach-Object { try { ([string]$_.Path).ToLower() } catch { '' } } | Where-Object { $_ })
    $helper = '(?i)^(unins|uninst|uninstall|setup|install|update|updater|autoupdate|helper|crash|crashpad|crashreporter|elevat|notification|maintenance|vc_redist|repair|report|bugreport|squirrel|createdump|dxsetup|dotnetfx)|(updat|uninst|crash|helper|elevat|setup)[^\\]*\.exe$'
    $out = [System.Collections.Generic.List[object]]::new()
    foreach ($p in @(Get-CcPrograms $false | ForEach-Object { $_ })) {
        if (-not $p -or $p.Kind -ne 'Programm' -or $p.Orphan) { continue }
        if (('{0} {1}' -f $p.Name, $p.Publisher) -match $UnusedProtect) { continue }
        $loc = [string]$p.Location
        if (-not $loc -or -not [IO.Directory]::Exists($loc)) {
            $ref = ''; try { $ref = [IO.Path]::GetDirectoryName((Split-CcCommand $p.Uninstall)[0]) } catch { }
            $loc = if ($ref -and [IO.Directory]::Exists($ref) -and $ref -notmatch '(?i)\\(windows|system32|syswow64|installer|package cache|temp)(\\|$)' -and $ref -match '^[A-Za-z]:\\.+\\.+') { $ref } else { '' }
        }
        $inst = $p.Date; if (-not $inst -and $loc) { try { $inst = [IO.Directory]::GetCreationTime($loc) } catch { } }
        if ($inst -and $inst -gt $cut) { continue }
        $locLow = if ($loc) { $loc.TrimEnd('\').ToLower() + '\' } else { '' }
        if ($locLow -and (@($svcPaths | Where-Object { $_.StartsWith($locLow) }).Count -or @($procPaths | Where-Object { $_.StartsWith($locLow) }).Count)) { continue }
        $exes = @(Get-ProgExeNames $loc | ForEach-Object { $_ } | Where-Object { [IO.Path]::GetFileName($_) -notmatch $helper })
        $last = $null
        foreach ($e in $exes) {
            $fn = [IO.Path]::GetFileName($e).ToLower(); $pf = if ($fn.Length -gt 29) { $fn.Substring(0, 29) } else { $fn }
            foreach ($d in @($use.Exe[$fn], $use.Exe[$pf])) { if ($d -and (-not $last -or $d -gt $last)) { $last = $d } }
        }
        if ($locLow) { $lk = ($locLow -replace '^[a-z]:', ''); foreach ($k in @($use.Path.Keys)) { if ($k.StartsWith($lk) -and [IO.Path]::GetFileName($k) -notmatch $helper) { $d = $use.Path[$k]; if (-not $last -or $d -gt $last) { $last = $d } } } }
        if ($last -and $last -gt $cut) { continue }
        $sil = Get-SilentUninstallCmd $p
        $known = [bool]$exes.Count
        $status = if (-not $known) { 'Nutzung nicht feststellbar' } elseif ($last) { 'zuletzt benutzt vor {0} Tagen' -f [int]((Get-Date) - $last).TotalDays } else { 'seit der Installation nie gestartet' }
        if (-not $sil) { $status += ' - wird über winget oder das Deinstallationsprogramm des Herstellers entfernt' }
        $out.Add([pscustomobject]@{ Sel = [bool]$known; Name = $p.Name; Publisher = $p.Publisher; Version = $p.Version; LastUsed = $last; LastText = $(if ($last) { $last.ToString('dd.MM.yyyy') } elseif ($known) { 'nie' } else { '?' }); DateText = $(if ($inst) { $inst.ToString('dd.MM.yyyy') } else { '' }); Size = $p.Size; SizeText = $p.SizeText; Status = $status; Silent = [bool]$sil; Location = $loc; Prog = $p })
    }
    return , @($out | Sort-Object @{ e = { -not $_.Sel } }, @{ e = { $_.Size }; Descending = $true })
}
# Verknüpfungen im Startmenü/auf dem Desktop, deren Ziel im entfernten Programmordner lag und jetzt fehlt
function Remove-ProgShortcuts([string]$Loc) {
    $n = 0; if (-not $Loc) { return 0 }
    $locL = $Loc.TrimEnd('\').ToLower() + '\'
    $dirs = [System.Collections.Generic.List[string]]::new()
    $dirs.Add((Join-Path $env:ProgramData 'Microsoft\Windows\Start Menu\Programs')); $dirs.Add((Join-Path $env:PUBLIC 'Desktop'))
    foreach ($pr in @(Get-CcProfiles | ForEach-Object { $_ })) { foreach ($s in 'AppData\Roaming\Microsoft\Windows\Start Menu\Programs', 'Desktop', 'OneDrive\Desktop') { $dirs.Add([IO.Path]::Combine($pr.Root, $s)) } }
    $sh = $null; try { $sh = New-Object -ComObject WScript.Shell } catch { return 0 }
    foreach ($d in $dirs) {
        if (-not [IO.Directory]::Exists($d)) { continue }
        $files = @(); try { $files = [IO.Directory]::GetFiles($d, '*.lnk', [IO.SearchOption]::AllDirectories) } catch { }
        foreach ($f in $files) { try { $t = [string]$sh.CreateShortcut($f).TargetPath; if ($t -and $t.ToLower().StartsWith($locL) -and -not [IO.File]::Exists($t)) { [IO.File]::Delete($f); $n++ } } catch { } }
        if ($d -like '*Start Menu\Programs') { $sub = @(); try { $sub = @([IO.Directory]::GetDirectories($d, '*', [IO.SearchOption]::AllDirectories) | Sort-Object Length -Descending) } catch { }; foreach ($sd in $sub) { try { if (-not @([IO.Directory]::GetFileSystemEntries($sd)).Count) { [IO.Directory]::Delete($sd) } } catch { } } }
    }
    return $n
}
function Invoke-UnusedUninstall($Items, [string]$BackupDir) {
    $log = [System.Collections.Generic.List[string]]::new()
    try { New-ItemProperty -Path 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\SystemRestore' -Name 'SystemRestorePointCreationFrequency' -Value 0 -PropertyType DWord -Force | Out-Null; Checkpoint-Computer -Description 'PC-Tools: ungenutzte Programme entfernen' -RestorePointType APPLICATION_UNINSTALL -ErrorAction Stop; $log.Add('Wiederherstellungspunkt erstellt.') } catch { $log.Add('Hinweis: Wiederherstellungspunkt nicht möglich (' + $_.Exception.Message + ').') }
    $ok = 0; $fail = 0
    foreach ($it in @($Items)) {
        $p = $it.Prog; $log.Add(''); $log.Add('== ' + $p.Name + ' ==')
        # Wege der Reihe nach: 1. still (Hersteller/MSI/Inno/NSIS/...)  2. winget  3. Deinstallationsprogramm sichtbar  4. portables Programm ohne Deinstaller: Ordner + Eintrag entfernen
        $steps = [System.Collections.Generic.List[object]]::new()
        $c0 = Get-SilentUninstallCmd $p; if ($c0) { $steps.Add([pscustomobject]@{ Exe = $c0.Exe; Args = $c0.Args; How = $c0.How; Visible = $false }) }
        $wg = ''; try { $wg = (Get-Command winget.exe -ErrorAction Stop).Source } catch { }
        if ($wg -and -not ($c0 -and $c0.How -eq 'winget')) { $steps.Add([pscustomobject]@{ Exe = $wg; Args = ('uninstall --name "{0}" --exact --silent --force --accept-source-agreements --disable-interactivity' -f ([string]$p.Name -replace '"', '')); How = 'winget'; Visible = $false }) }
        if ($p.Uninstall -and -not ($c0 -and $c0.How -eq 'winget')) { try { $spv = Split-CcCommand $p.Uninstall; if ([IO.File]::Exists([string]$spv[0])) { $steps.Add([pscustomobject]@{ Exe = [string]$spv[0]; Args = [string]$spv[1]; How = 'Deinstallationsprogramm des Herstellers'; Visible = $true }) } } catch { } }
        $c = $null; $pr = $null
        foreach ($st in $steps) {
            if ($st.Visible) { $log.Add('  Stiller Weg nicht möglich - das Deinstallationsprogramm des Herstellers wurde geöffnet, bitte dort bestätigen.') }
            $t0 = Get-Date; $pr = $null
            try {
                $ws = $(if ($st.Visible) { 'Normal' } else { 'Hidden' })
                $pr = if ($st.Args) { Start-Process -FilePath $st.Exe -ArgumentList $st.Args -PassThru -WindowStyle $ws -ErrorAction Stop } else { Start-Process -FilePath $st.Exe -PassThru -WindowStyle $ws -ErrorAction Stop }
                if (-not $pr.WaitForExit(900000)) { try { $pr.Kill() } catch { }; $log.Add('  abgebrochen: lief länger als 15 Minuten.') }
                $rx = '^(un_?|unins|uninst|au_|_iu14d2n|_un|setup|msiexec|winget|.*uninstall.*|.*deinst.*)'
                $sw = [Diagnostics.Stopwatch]::StartNew(); $idle = 0
                while ($sw.Elapsed.TotalMinutes -lt $(if ($st.Visible) { 15 } else { 10 })) {
                    if (-not (Test-CcProgramPresent $p)) { break }
                    $busy = @(Get-Process -ErrorAction SilentlyContinue | Where-Object { $_.Name -match $rx -and $(try { $_.StartTime -ge $t0 } catch { $false }) }).Count
                    if ($busy) { $idle = 0 } else { $idle++ }; if ($idle -ge 4) { break }
                    Start-Sleep -Seconds 2
                }
            } catch { $log.Add(('  {0}: Start nicht möglich ({1})' -f $st.How, $_.Exception.Message)); continue }
            if (-not (Test-CcProgramPresent $p)) { $c = $st; break }
            $log.Add(('  {0}: nicht entfernt (Rückgabewert {1}) - nächster Weg ...' -f $st.How, $(try { $pr.ExitCode } catch { '?' })))
        }
        if (-not $c -and -not $p.Uninstall -and (Test-CcProgramPresent $p)) {
            # Programm ohne Deinstallationsprogramm (portabel): Ordner in den Papierkorb, Eintrag gesichert entfernen
            try {
                $rows = [System.Collections.Generic.List[object]]::new()
                if ($p.Location -and $p.Location -match '^[A-Za-z]:\\.+\\.+' -and [IO.Directory]::Exists($p.Location)) { $rows.Add([pscustomobject]@{ Kind = 'Dir'; Path = $p.Location.TrimEnd('\'); Hive = ''; Key = $p.Location }) }
                $rows.Add([pscustomobject]@{ Kind = 'Reg'; Hive = $p.Hive; Path = $p.Path; Key = ('{0}\{1}' -f $p.Hive, $p.Path) })
                foreach ($m in @(Remove-CcLeftovers $rows.ToArray() $BackupDir | ForEach-Object { $_ })) { $log.Add('  ' + $m) }
                if (-not (Test-CcProgramPresent $p)) { $c = [pscustomobject]@{ How = 'ohne Deinstallationsprogramm: Ordner und Eintrag entfernt' } }
            } catch { $log.Add('  Entfernen nicht möglich: ' + $_.Exception.Message) }
        }
        if (-not $c) { $log.Add('  NICHT entfernt - alle Wege versucht. Bitte über Einstellungen > Apps deinstallieren.'); $fail++; continue }
        $ok++; $log.Add(('  deinstalliert ({0})' -f $c.How))
        try {
            $rows = @(Find-CcLeftovers $p | ForEach-Object { $_ })
            if ($rows.Count) { foreach ($m in @(Remove-CcLeftovers $rows $BackupDir | ForEach-Object { $_ })) { $log.Add('  Rest: ' + $m) } } else { $log.Add('  keine Reste gefunden') }
        } catch { $log.Add('  Reste-Suche: ' + $_.Exception.Message) }
        try { $sc = Remove-ProgShortcuts $it.Location; if ($sc) { $log.Add(('  {0} verwaiste Verknüpfung(en) entfernt' -f $sc)) } } catch { }
    }
    $log.Insert(0, ('{0} Programm(e) entfernt, {1} nicht. Ordner-Reste liegen im Papierkorb, Registry-Reste sind gesichert.' -f $ok, $fail))
    return ($log -join "`r`n")
}
# =====================================================================
#  Browser-Erweiterungen und Startseite/Suchmaschine
# =====================================================================
function Read-CcJsonFile([string]$File) {
    try {
        if (-not [IO.File]::Exists($File)) { return $null }
        $fs = New-Object IO.FileStream($File, [IO.FileMode]::Open, [IO.FileAccess]::Read, [IO.FileShare]'ReadWrite, Delete')
        try { $sr = New-Object IO.StreamReader($fs, [Text.Encoding]::UTF8, $true); $t = $sr.ReadToEnd() } finally { $fs.Dispose() }
        if (-not $t) { return $null }
        return ($t | ConvertFrom-Json)
    } catch { return $null }
}
function Resolve-CcExtMsg([string]$Text, [string]$Dir, [string]$Def) {
    if ($Text -notmatch '^__MSG_(.+)__$') { return $Text }
    $key = $Matches[1]
    foreach ($loc in @('de', 'de_DE', $Def, 'en', 'en_US', 'en_GB') | Where-Object { $_ } | Select-Object -Unique) {
        $j = Read-CcJsonFile ([IO.Path]::Combine($Dir, '_locales', $loc, 'messages.json'))
        if (-not $j) { continue }
        foreach ($p in $j.PSObject.Properties) { if ($p.Name -ieq $key -and $p.Value.message) { return [string]$p.Value.message } }
    }
    return $Text
}
function Get-CcProp($Obj, [string[]]$Path) {
    $o = $Obj
    foreach ($p in $Path) { if ($null -eq $o) { return $null }; $pp = $o.PSObject.Properties[$p]; if (-not $pp) { return $null }; $o = $pp.Value }
    return $o
}
function Get-CcExtensions {
    $out = [System.Collections.Generic.List[object]]::new()
    $profiles = @(Get-CcProfiles | ForEach-Object { $_ }); $multi = $profiles.Count -gt 1
    $ctx = New-CcContext $null
    foreach ($b in (Get-CcBrowserDefs)) {
        foreach ($pr in $profiles) {
            foreach ($bp in @(Get-CcBrowserProfileDirs $b $pr $ctx | ForEach-Object { $_ })) {
                $pname = $bp.Name
                if ($b.Kind -eq 'Chromium') {
                    $prefs = Read-CcJsonFile ([IO.Path]::Combine($bp.Pr, 'Preferences'))
                    $sprefs = Read-CcJsonFile ([IO.Path]::Combine($bp.Pr, 'Secure Preferences'))
                    $pn = [string](Get-CcProp $prefs @('profile', 'name')); if ($pn) { $pname = $pn }
                    $settings = @{}
                    foreach ($src in @($prefs, $sprefs)) { $st = Get-CcProp $src @('extensions', 'settings'); if ($st) { foreach ($q in $st.PSObject.Properties) { $settings[$q.Name] = $q.Value } } }
                    $ed = [IO.Path]::Combine($bp.Pr, 'Extensions')
                    if (-not [IO.Directory]::Exists($ed)) { continue }
                    foreach ($idDir in @([IO.Directory]::GetDirectories($ed))) {
                        $id = [IO.Path]::GetFileName($idDir)
                        if ($id -notmatch '^[a-p]{32}$') { continue }
                        $vd = @([IO.Directory]::GetDirectories($idDir) | Sort-Object { [IO.Directory]::GetLastWriteTime($_) } -Descending) | Select-Object -First 1
                        if (-not $vd) { continue }
                        $m = Read-CcJsonFile ([IO.Path]::Combine($vd, 'manifest.json'))
                        if (-not $m) { continue }
                        $nm = Resolve-CcExtMsg ([string]$m.name) $vd ([string]$m.default_locale)
                        $ds = Resolve-CcExtMsg ([string]$m.description) $vd ([string]$m.default_locale)
                        $s = $settings[$id]
                        $state = Get-CcProp $s @('state'); $dr = Get-CcProp $s @('disable_reasons'); $locn = Get-CcProp $s @('location')
                        if ($null -ne $locn -and [int]$locn -in 5, 10) { continue }   # Komponenten des Browsers
                        $en = $true
                        if ($null -ne $state) { $en = ([int]$state -eq 1) }
                        if ($null -ne $dr -and @($dr).Count -and [string](@($dr)[0]) -ne '0') { $en = $false }
                        $srcTxt = switch ([string]$locn) { '1' { 'Web Store' } '4' { 'entpackt (Entwickler)' } '2' { 'extern (Programm)' } '3' { 'extern (Registry)' } '6' { 'extern (Programm)' } '7' { 'extern (Richtlinie)' } '8' { 'extern (Befehlszeile)' } '9' { 'extern (Richtlinie)' } default { $(if (Get-CcProp $s @('from_webstore')) { 'Web Store' } else { '' }) } }
                        $perm = @(@($m.permissions) + @($m.host_permissions) | Where-Object { $_ -is [string] }) -join ', '
                        $out.Add([pscustomobject]@{
                            Browser = $b.Name; BrowserKey = $b.Key; Profile = $(if ($multi) { '{0} / {1}' -f $pr.User, $pname } else { $pname }); Name = $nm; Version = [string]$m.version; Id = $id
                            Enabled = $en; StatusText = $(if ($en) { 'aktiv' } else { 'deaktiviert' }); Source = $srcTxt; Perms = $perm; Desc = $ds; Path = $idDir; Kind = 'Chromium'; Proc = $b.Proc
                            Level = $(if (-not $en) { 'Off' } elseif ($srcTxt -like 'extern*' -or $srcTxt -like 'entpackt*') { 'Warn' } else { '' })
                        })
                    }
                } else {
                    $j = Read-CcJsonFile ([IO.Path]::Combine($bp.Pr, 'extensions.json'))
                    foreach ($a in @($j.addons)) {
                        if (-not $a -or [string]$a.type -ne 'extension') { continue }
                        if ([string]$a.location -in 'app-builtin', 'app-system-defaults', 'app-system-addons', 'app-system-share', 'app-system-local', 'app-global') { continue }
                        $nm = [string](Get-CcProp $a @('defaultLocale', 'name')); if (-not $nm) { $nm = [string]$a.id }
                        $en = [bool]$a.active
                        $srcU = [string]$a.sourceURI; $srcTxt = if ($srcU -match 'addons\.mozilla\.org|addons\.cdn\.mozilla\.net') { 'addons.mozilla.org' } elseif ($srcU) { ([uri]$srcU).Host } else { [string]$a.location }
                        $out.Add([pscustomobject]@{
                            Browser = $b.Name; BrowserKey = $b.Key; Profile = $(if ($multi) { '{0} / {1}' -f $pr.User, $pname } else { $pname }); Name = $nm; Version = [string]$a.version; Id = [string]$a.id
                            Enabled = $en; StatusText = $(if ($en) { 'aktiv' } elseif ($a.userDisabled) { 'deaktiviert' } else { 'inaktiv' }); Source = $srcTxt; Perms = (@(Get-CcProp $a @('userPermissions', 'permissions')) + @(Get-CcProp $a @('userPermissions', 'origins')) | Where-Object { $_ }) -join ', '
                            Desc = [string](Get-CcProp $a @('defaultLocale', 'description')); Path = [string]$a.path; Kind = 'Firefox'; Proc = $b.Proc
                            Level = $(if (-not $en) { 'Off' } elseif ($srcTxt -ne 'addons.mozilla.org' -and $srcTxt -notlike 'app-*') { 'Warn' } else { '' })
                        })
                    }
                }
            }
        }
    }
    return , $out
}
function Test-CcKnownHost([string]$Url) {
    if (-not $Url) { return $true }
    if ($Url -match '^(chrome|edge|brave|vivaldi|opera|about):') { return $true }
    $h = ''; try { $h = ([uri]($Url -replace '\{[^\}]*\}', 'x')).Host.ToLower() } catch { return $false }
    return [bool]($h -match '(^|\.)(google\.[a-z\.]+|bing\.com|msn\.com|microsoft\.com|duckduckgo\.com|ecosia\.org|startpage\.com|qwant\.com|yahoo\.com|search\.brave\.com|brave\.com|yandex\.[a-z]+|baidu\.com|ixquick\.com|metager\.de|t-online\.de|web\.de|gmx\.(net|de)|vivaldi\.com|opera\.com|mozilla\.org|firefox\.com|wikipedia\.org|you\.com|perplexity\.ai|kagi\.com|mojeek\.com|swisscows\.ch|presearch\.com)$')
}
function Get-CcPolicyValues([string]$Vendor) {
    $o = [ordered]@{}
    if (-not $Vendor) { return $o }
    foreach ($h in 'HKLM', 'HKCU') {
        $k = Open-CcRegKey $h ('SOFTWARE\Policies\' + $Vendor); if (-not $k) { continue }
        try {
            foreach ($v in 'DefaultSearchProviderSearchURL', 'DefaultSearchProviderName', 'HomepageLocation', 'NewTabPageLocation', 'RestoreOnStartup') { $x = $k.GetValue($v); if ($null -ne $x) { $o[$v] = [string]$x } }
            foreach ($sub in 'RestoreOnStartupURLs', 'ExtensionInstallForcelist') { $sk = $k.OpenSubKey($sub); if ($sk) { try { $o[$sub] = (@($sk.GetValueNames() | ForEach-Object { [string]$sk.GetValue($_) }) -join ' | ') } finally { $sk.Close() } } }
        } finally { $k.Close() }
    }
    return $o
}
function Get-CcBrowserHome {
    $out = [System.Collections.Generic.List[object]]::new()
    $profiles = @(Get-CcProfiles | ForEach-Object { $_ }); $multi = $profiles.Count -gt 1
    $ctx = New-CcContext $null
    foreach ($b in (Get-CcBrowserDefs)) {
        $pol = Get-CcPolicyValues $b.Policy
        $polTxt = (@($pol.Keys | ForEach-Object { '{0}: {1}' -f $_, $pol[$_] }) -join '; ')
        foreach ($pr in $profiles) {
            foreach ($bp in @(Get-CcBrowserProfileDirs $b $pr $ctx | ForEach-Object { $_ })) {
                $search = ''; $surl = ''; $start = ''; $warn = [System.Collections.Generic.List[string]]::new(); $pname = $bp.Name
                if ($b.Kind -eq 'Chromium') {
                    $p = Read-CcJsonFile ([IO.Path]::Combine($bp.Pr, 'Preferences'))
                    $pn = [string](Get-CcProp $p @('profile', 'name')); if ($pn) { $pname = $pn }
                    $t = Get-CcProp $p @('default_search_provider_data', 'template_url_data')
                    if ($t) { $search = [string]$t.short_name; $surl = [string]$t.url }
                    if (-not $search) { $surl = [string](Get-CcProp $p @('default_search_provider', 'search_url')); $search = [string](Get-CcProp $p @('default_search_provider', 'name')) }
                    if (-not $search) { $search = $b.DefSearch + ' (Standard)' }
                    $ros = Get-CcProp $p @('session', 'restore_on_startup')
                    $urls = @(Get-CcProp $p @('session', 'startup_urls') | Where-Object { $_ })
                    $hp = [string](Get-CcProp $p @('homepage'))
                    $start = switch ([string]$ros) { '1' { 'Letzte Sitzung fortsetzen' } '4' { 'Bestimmte Seiten: ' + ($urls -join ', ') } '5' { 'Neuer Tab' } default { 'Neuer Tab (Standard)' } }
                    if ([string]$ros -eq '4') { foreach ($u in $urls) { if (-not (Test-CcKnownHost $u)) { $warn.Add('unbekannte Startseite ' + $u) } } }
                    if ($hp -and -not (Get-CcProp $p @('homepage_is_newtabpage'))) { $start += ' | Startseite-Schaltfläche: ' + $hp; if (-not (Test-CcKnownHost $hp)) { $warn.Add('unbekannte Startseite ' + $hp) } }
                } else {
                    $pf = [IO.Path]::Combine($bp.Pr, 'prefs.js'); $hp = ''; $pg = ''
                    if ([IO.File]::Exists($pf)) {
                        foreach ($l in [IO.File]::ReadAllLines($pf)) {
                            if ($l -match '^user_pref\("browser\.startup\.homepage",\s*"(.*)"\);') { $hp = $Matches[1] }
                            elseif ($l -match '^user_pref\("browser\.startup\.page",\s*(\d+)\);') { $pg = $Matches[1] }
                        }
                    }
                    $start = switch ($pg) { '3' { 'Letzte Sitzung fortsetzen' } '0' { 'Leere Seite' } default { $(if ($hp) { 'Startseite: ' + $hp } else { 'Firefox-Startseite (Standard)' }) } }
                    if ($hp) { foreach ($u in ($hp -split '\|')) { if ($u -notlike 'about:*' -and -not (Test-CcKnownHost $u)) { $warn.Add('unbekannte Startseite ' + $u) } } }
                    $sj = [IO.Path]::Combine($bp.Pr, 'search.json.mozlz4')
                    if ([IO.File]::Exists($sj)) {
                        try {
                            Initialize-CcNative
                            $js = [PCPflege.CcNative]::MozLz4($sj) | ConvertFrom-Json
                            $defId = [string](Get-CcProp $js @('metaData', 'defaultEngineId')); $cur = [string](Get-CcProp $js @('metaData', 'current'))
                            $eng = @($js.engines | Where-Object { ($defId -and [string]$_.id -eq $defId) -or ($cur -and [string]$_._name -eq $cur) }) | Select-Object -First 1
                            if ($eng) {
                                $search = [string]$eng._name
                                $tu = @($eng._urls | Where-Object { -not $_.type -or $_.type -eq 'text/html' }) | Select-Object -First 1
                                if ($tu) { $surl = [string]$tu.template }
                                if ([string]$eng._loadPath -and [string]$eng._loadPath -notmatch '^\[(app|addon)\]' -and -not $eng._isAppProvided -and $surl -and -not (Test-CcKnownHost $surl)) { $warn.Add('Suchmaschine von außen hinzugefügt') }
                            }
                        } catch { }
                    }
                    if (-not $search) { $search = 'Standard' }
                }
                if ($surl -and -not (Test-CcKnownHost $surl)) { $warn.Add('unbekannte Suchmaschine ' + $surl) }
                if ($polTxt) { $warn.Add('durch Richtlinie festgelegt') }
                $out.Add([pscustomobject]@{
                    Browser = $b.Name; Profile = $(if ($multi) { '{0} / {1}' -f $pr.User, $pname } else { $pname }); Search = $(if ($surl) { '{0}  ({1})' -f $search, $surl } else { $search }); Start = $start; Policy = $polTxt
                    Rating = $(if ($warn.Count) { 'Prüfen: ' + (($warn | Select-Object -Unique) -join '; ') } else { 'unauffällig' }); Level = $(if ($warn.Count) { 'Warn' } else { 'Good' })
                })
            }
        }
    }
    return , $out
}
# Chromium-Erweiterung entfernen: Ordner in den Papierkorb (nur bei geschlossenem Browser)
function Remove-CcExtension($Row) {
    if ($Row.Kind -ne 'Chromium') { throw 'Firefox-Erweiterungen bitte in Firefox unter about:addons entfernen.' }
    $run = @(Get-Process -Name $Row.Proc -ErrorAction SilentlyContinue)
    if ($run.Count) { throw ('{0} läuft noch - bitte zuerst schließen.' -f $Row.Browser) }
    if (-not [IO.Directory]::Exists($Row.Path) -or $Row.Path -notmatch '\\Extensions\\[a-p]{32}$') { throw 'Erweiterungsordner nicht gefunden.' }
    Add-Type -AssemblyName Microsoft.VisualBasic
    [Microsoft.VisualBasic.FileIO.FileSystem]::DeleteDirectory($Row.Path, 'OnlyErrorDialogs', 'SendToRecycleBin')
    return $true
}

# =====================================================================
#  Kontextmenü (Shell-Erweiterungen über die Blocked-Liste, Befehle über LegacyDisable - beides umkehrbar)
# =====================================================================
function Get-CcFileCompany([string]$File) {
    try { $f = [Environment]::ExpandEnvironmentVariables($File.Trim().Trim('"')); if ([IO.File]::Exists($f)) { return [string][Diagnostics.FileVersionInfo]::GetVersionInfo($f).CompanyName } } catch { }
    return ''
}
function Get-CcContextItems([bool]$IncludeMs) {
    $out = [System.Collections.Generic.List[object]]::new()
    try { Initialize-CcNative } catch { }
    $places = [ordered]@{ '*' = 'Alle Dateien'; 'AllFilesystemObjects' = 'Dateien und Ordner'; 'Directory' = 'Ordner'; 'Directory\Background' = 'Ordner-Hintergrund'; 'Folder' = 'Ordner (auch Bibliotheken)'; 'Drive' = 'Laufwerke' }
    $blocked = @{}
    foreach ($h in 'HKLM', 'HKCU') { $k = Open-CcRegKey $h 'SOFTWARE\Microsoft\Windows\CurrentVersion\Shell Extensions\Blocked'; if ($k) { try { foreach ($v in $k.GetValueNames()) { $blocked[$v.ToUpper()] = $true } } finally { $k.Close() } } }
    $clsName = { param($c)
        $n = ''; $dll = ''
        foreach ($root in @(@('HKLM', 'SOFTWARE\Classes\CLSID\' + $c), @('HKCU', 'Software\Classes\CLSID\' + $c), @('HKLM', 'SOFTWARE\Classes\WOW6432Node\CLSID\' + $c))) {
            $ck = Open-CcRegKey $root[0] $root[1]; if (-not $ck) { continue }
            try { if (-not $n) { $n = [string]$ck.GetValue('') }; $ik = $ck.OpenSubKey('InprocServer32'); if ($ik) { try { if (-not $dll) { $dll = [string]$ik.GetValue('') } } finally { $ik.Close() } } } finally { $ck.Close() }
        }
        @($n, $dll)
    }
    $seen = @{}
    foreach ($pl in $places.Keys) {
        foreach ($h in @(@('HKLM', 'SOFTWARE\Classes'), @('HKCU', 'Software\Classes'))) {
            # Shell-Erweiterungen
            $kp = '{0}\{1}\shellex\ContextMenuHandlers' -f $h[1], $pl
            $k = Open-CcRegKey $h[0] $kp
            if ($k) {
                try {
                    foreach ($s in $k.GetSubKeyNames()) {
                        $sk = $k.OpenSubKey($s); if (-not $sk) { continue }
                        $def = ''; try { $def = [string]$sk.GetValue('') } finally { $sk.Close() }
                        $clsid = if ($def -match '^\{[0-9A-Fa-f\-]{36}\}$') { $def } elseif ($s -match '^\{[0-9A-Fa-f\-]{36}\}$') { $s } else { '' }
                        if (-not $clsid) { continue }
                        $sid = ('{0}|{1}|{2}' -f $pl, $clsid, $h[0]).ToUpper(); if ($seen.ContainsKey($sid)) { continue }; $seen[$sid] = $true
                        $ci = & $clsName $clsid
                        $co = Get-CcFileCompany $ci[1]
                        $ms = ($co -match 'Microsoft') -or ($ci[1] -match '(?i)\\Windows\\System32\\|\\SystemApps\\')
                        if ($ms -and -not $IncludeMs) { continue }
                        $nm = if ($s -notmatch '^\{') { $s } elseif ($ci[0]) { $ci[0] } else { $clsid }
                        $en = -not $blocked.ContainsKey($clsid.ToUpper())
                        $out.Add([pscustomobject]@{ Name = $nm; Where = $places[$pl]; Kind = 'Shell-Erweiterung'; Enabled = $en; StatusText = $(if ($en) { 'sichtbar' } else { 'ausgeblendet' }); Company = $co; Target = $(if ($ci[1]) { $ci[1] } else { $clsid })
                            Clsid = $clsid; Hive = $h[0]; KeyPath = ($kp + '\' + $s); Ms = $ms; Level = $(if (-not $en) { 'Off' } else { '' }) })
                    }
                } finally { $k.Close() }
            }
            # Befehle (Verben)
            $kp2 = '{0}\{1}\shell' -f $h[1], $pl
            $k2 = Open-CcRegKey $h[0] $kp2
            if ($k2) {
                try {
                    foreach ($verb in $k2.GetSubKeyNames()) {
                        $vk = $k2.OpenSubKey($verb); if (-not $vk) { continue }
                        try {
                            if ($null -ne $vk.GetValue('ProgrammaticAccessOnly')) { continue }
                            $disp = [string]$vk.GetValue('MUIVerb'); if (-not $disp) { $disp = [string]$vk.GetValue('') }
                            if ($disp -like '@*') { try { $disp = [PCPflege.CcNative]::Indirect($disp) } catch { } }
                            if (-not $disp -or $disp -like '@*') { $disp = $verb }
                            $disp = $disp.Replace('&', '')
                            $cmd = ''; $ck = $vk.OpenSubKey('command'); if ($ck) { try { $cmd = [string]$ck.GetValue('') } finally { $ck.Close() } }
                            $exe = Get-CcRefPath $cmd; $co = if ($exe) { Get-CcFileCompany $exe } else { '' }
                            $ms = ($co -match 'Microsoft') -or ($cmd -match '(?i)%SystemRoot%|\\Windows\\') -or ($verb -in 'open', 'find', 'explore', 'opennewwindow', 'pintohome', 'cmd', 'Powershell', 'runas', 'print', 'edit', 'opennewprocess', 'opennewtab', 'UpdateEncryptionSettings', 'UpdateEncryptionSettingsWork')
                            if ($ms -and -not $IncludeMs) { continue }
                            $en = ($null -eq $vk.GetValue('LegacyDisable'))
                            $ext = ($null -ne $vk.GetValue('Extended'))
                            $out.Add([pscustomobject]@{ Name = $disp + $(if ($ext) { '  (nur mit Umschalt)' } else { '' }); Where = $places[$pl]; Kind = 'Befehl'; Enabled = $en; StatusText = $(if ($en) { 'sichtbar' } else { 'ausgeblendet' }); Company = $co; Target = $cmd
                                Clsid = ''; Hive = $h[0]; KeyPath = ($kp2 + '\' + $verb); Ms = $ms; Level = $(if (-not $en) { 'Off' } else { '' }) })
                        } finally { $vk.Close() }
                    }
                } finally { $k2.Close() }
            }
        }
    }
    return , $out
}
function Set-CcContextItem($Row, [bool]$Enable) {
    if ($Row.Kind -eq 'Shell-Erweiterung') {
        $bp = 'SOFTWARE\Microsoft\Windows\CurrentVersion\Shell Extensions\Blocked'
        if ($Enable) {
            foreach ($h in 'HKLM', 'HKCU') { $k = Open-CcRegKey $h $bp $true; if ($k) { try { foreach ($v in @($k.GetValueNames() | Where-Object { $_ -ieq $Row.Clsid })) { $k.DeleteValue($v, $false) } } finally { $k.Close() } } }
        } else {
            $base = Open-CcRegKey 'HKLM' ''
            $k = $base.CreateSubKey($bp)
            try { $k.SetValue($Row.Clsid, ('PC-Tools: ' + $Row.Name)) } finally { $k.Close() }
        }
    } else {
        $k = Open-CcRegKey $Row.Hive $Row.KeyPath $true
        if (-not $k) { throw 'Eintrag nicht beschreibbar.' }
        try { if ($Enable) { $k.DeleteValue('LegacyDisable', $false) } else { $k.SetValue('LegacyDisable', '') } } finally { $k.Close() }
    }
}

# =====================================================================
#  Geplante Aufgaben anderer Hersteller
# =====================================================================
function ConvertTo-CcDuration([string]$Iso) {
    if (-not $Iso) { return '' }
    try {
        $t = [Xml.XmlConvert]::ToTimeSpan($Iso)
        if ($t.TotalDays -ge 1 -and $t.TotalDays -eq [math]::Floor($t.TotalDays)) { return $(if ($t.TotalDays -eq 1) { 'täglich' } else { '{0} Tage' -f $t.TotalDays }) }
        if ($t.TotalHours -ge 1 -and $t.TotalHours -eq [math]::Floor($t.TotalHours)) { return $(if ($t.TotalHours -eq 1) { '1 Stunde' } else { '{0} Stunden' -f $t.TotalHours }) }
        return ('{0} Minuten' -f [math]::Round($t.TotalMinutes))
    } catch { return $Iso }
}
function ConvertTo-CcTriggerText($Tr) {
    $cls = [string]$Tr.CimClass.CimClassName
    $tm = ''; try { if ($Tr.StartBoundary) { $tm = ([datetime]$Tr.StartBoundary).ToString('HH:mm') } } catch { }
    $t = switch ($cls) {
        'MSFT_TaskLogonTrigger'   { 'bei Anmeldung' + $(if ($Tr.UserId) { ' (' + $Tr.UserId + ')' } else { ' (jeder Benutzer)' }) }
        'MSFT_TaskBootTrigger'    { 'beim Systemstart' }
        'MSFT_TaskDailyTrigger'   { $(if ([int]$Tr.DaysInterval -gt 1) { 'alle {0} Tage {1}' -f $Tr.DaysInterval, $tm } else { 'täglich ' + $tm }) }
        'MSFT_TaskWeeklyTrigger'  {
            $dn = @(); $m = [int]$Tr.DaysOfWeek; $map = @(@(2, 'Mo'), @(4, 'Di'), @(8, 'Mi'), @(16, 'Do'), @(32, 'Fr'), @(64, 'Sa'), @(1, 'So'))
            foreach ($x in $map) { if ($m -band $x[0]) { $dn += $x[1] } }
            'wöchentlich ' + ($dn -join ', ') + ' ' + $tm
        }
        'MSFT_TaskTimeTrigger'    { $(try { 'einmalig ' + ([datetime]$Tr.StartBoundary).ToString('dd.MM.yyyy HH:mm') } catch { 'einmalig' }) }
        'MSFT_TaskIdleTrigger'    { 'im Leerlauf' }
        'MSFT_TaskEventTrigger'   { 'bei einem Ereignis' }
        'MSFT_TaskSessionStateChangeTrigger' { 'bei Sitzungswechsel (Sperren/Entsperren/Verbinden)' }
        'MSFT_TaskRegistrationTrigger' { 'beim Erstellen/Ändern der Aufgabe' }
        default { ($cls -replace '^MSFT_Task|Trigger$', '') }
    }
    try { if ($Tr.Repetition -and $Tr.Repetition.Interval) { $t += ', wiederholt alle ' + (ConvertTo-CcDuration ([string]$Tr.Repetition.Interval)) } } catch { }
    try { if ($Tr.Enabled -eq $false) { $t += ' (aus)' } } catch { }
    return $t.Trim()
}
function Get-CcTasks {
    $out = [System.Collections.Generic.List[object]]::new()
    $res = @{ '0' = 'Erfolgreich'; '1' = 'Fehler (1)'; '267009' = 'Läuft gerade'; '267011' = 'Noch nie ausgeführt'; '267014' = 'Vom Benutzer beendet'; '2147750687' = 'Läuft bereits'; '2147942402' = 'Datei nicht gefunden'; '2147942405' = 'Zugriff verweigert'; '2147946720' = 'Abgebrochen (Zeit überschritten)' }
    $stt = @{ Ready = 'Bereit'; Running = 'Läuft'; Disabled = 'Deaktiviert'; Queued = 'Wartet' }
    foreach ($t in @(Get-ScheduledTask -ErrorAction SilentlyContinue | Where-Object { $_.TaskPath -notlike '\Microsoft\*' })) {
        $i = $null; try { $i = Get-ScheduledTaskInfo -InputObject $t -ErrorAction Stop } catch { }
        $last = if ($i -and $i.LastRunTime -and $i.LastRunTime.Year -gt 2000) { $i.LastRunTime } else { $null }
        $next = if ($i -and $i.NextRunTime -and $i.NextRunTime.Year -gt 2000) { $i.NextRunTime } else { $null }
        $code = if ($i) { [uint32]$i.LastTaskResult } else { 0 }
        $acts = @($t.Actions | Where-Object { $_.Execute })
        $act = ($acts | ForEach-Object { ('{0} {1}' -f $_.Execute, $_.Arguments).Trim() }) -join ' | '
        $exe = ''; $missing = $false; $co = ''
        if ($acts.Count) {
            $exe = [Environment]::ExpandEnvironmentVariables(([string]$acts[0].Execute).Trim('"'))
            if ($exe -match '^[A-Za-z]:\\') { $missing = Test-CcPathMissing $exe; if (-not $missing) { $co = Get-CcFileCompany $exe } }
        }
        $author = [string]$t.Author
        if ($author -like '$(@*') { try { Initialize-CcNative; $author = [PCPflege.CcNative]::Indirect($author.Substring(2).TrimEnd(')')) } catch { } }
        $own = ($t.TaskName -like 'PC-Pflege*' -or $t.TaskName -like 'PC-Tools*')
        $trg = @($t.Triggers | ForEach-Object { ConvertTo-CcTriggerText $_ }) -join '; '
        $out.Add([pscustomobject]@{
            Name = $t.TaskName; Path = $t.TaskPath; Author = $(if ($co) { $co } elseif ($author) { $author } else { '' }); Trigger = $(if ($trg) { $trg } else { 'nur manuell' })
            State = [string]$t.State; StateText = $(if ($own) { 'PC-Tools' } elseif ($stt[[string]$t.State]) { $stt[[string]$t.State] } else { [string]$t.State })
            Last = $last; LastText = $(if ($last) { $last.ToString('dd.MM.yyyy HH:mm') } else { '' }); Next = $next; NextText = $(if ($next) { $next.ToString('dd.MM.yyyy HH:mm') } else { '' })
            ResultText = $(if (-not $last) { '' } elseif ($res.ContainsKey([string]$code)) { $res[[string]$code] } else { '0x{0:X8}' -f $code })
            Action = $act; Missing = $missing; Own = $own; Account = [string]$t.Principal.UserId; Desc = [string]$t.Description
            Level = $(if ($missing) { 'Error' } elseif ($t.State -eq 'Disabled') { 'Off' } elseif ($last -and $code -ne 0 -and $code -ne 267009 -and $code -ne 267011) { 'Warn' } else { '' })
        })
    }
    return , $out
}

# =====================================================================
#  Laufwerke (freien Speicher löschen / TRIM)
# =====================================================================
function Get-CcDrives {
    $out = [System.Collections.Generic.List[object]]::new()
    $phys = @(Get-PhysicalDisk -ErrorAction SilentlyContinue)
    foreach ($v in @(Get-Volume -ErrorAction SilentlyContinue | Where-Object { "$($_.DriveType)" -eq 'Fixed' -and $_.DriveLetter } | Sort-Object DriveLetter)) {
        $media = ''; $bus = ''
        try {
            $disk = Get-Partition -DriveLetter $v.DriveLetter -ErrorAction Stop | Get-Disk -ErrorAction Stop
            $bus = [string]$disk.BusType
            $pd = $phys | Where-Object { [string]$_.DeviceId -eq [string]$disk.Number } | Select-Object -First 1
            if ($pd) { $media = [string]$pd.MediaType }
        } catch { }
        $free = [int64]$v.SizeRemaining; $size = [int64]$v.Size
        $isSsd = ($media -eq 'SSD' -or $bus -eq 'NVMe')
        $hours = [math]::Round(($free * 3.0) / (120MB) / 3600, 1)
        $fsOk = ([string]$v.FileSystem -in 'NTFS', 'ReFS')
        $adv = if (-not $fsOk) { 'Dateisystem {0}: cipher /w nur für NTFS/ReFS' -f $v.FileSystem }
               elseif ($isSsd) { 'SSD: TRIM empfohlen - Überschreiben wirkt auf SSDs nur eingeschränkt und kostet Lebensdauer' }
               else { 'Festplatte: Überschreiben möglich, ca. {0} Std. (3 Durchgänge)' -f $(if ($hours -lt 0.1) { '0,1' } else { $hours }) }
        $out.Add([pscustomobject]@{
            Letter = [string]$v.DriveLetter; Label = [string]$v.FileSystemLabel; FileSystem = [string]$v.FileSystem; Size = $size; Free = $free
            SizeText = (Format-CcSize $size); FreeText = (Format-CcSize $free); Media = $(if ($isSsd) { 'SSD' } elseif ($media -eq 'HDD') { 'Festplatte (HDD)' } elseif ($media) { $media } else { 'unbekannt' }); Bus = $bus
            IsSsd = $isSsd; FsOk = $fsOk; Advice = $adv; Level = $(if (-not $fsOk) { 'Off' } elseif ($isSsd) { 'Good' } else { '' })
        })
    }
    return , $out
}
# Zahlen für die Kacheln (schnell)
function Get-CcQuickCounts {
    $prg = 0
    foreach ($src in @(@('HKLM', 'SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall'), @('HKLM', 'SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall'), @('HKCU', 'Software\Microsoft\Windows\CurrentVersion\Uninstall'))) {
        $k = Open-CcRegKey $src[0] $src[1]; if (-not $k) { continue }
        try { foreach ($s in $k.GetSubKeyNames()) { $sk = $k.OpenSubKey($s); if (-not $sk) { continue }; try { if ($sk.GetValue('DisplayName') -and [string]$sk.GetValue('SystemComponent') -ne '1' -and -not $sk.GetValue('ParentKeyName')) { $prg++ } } finally { $sk.Close() } } } finally { $k.Close() }
    }
    $apps = 0; try { $apps = @(Get-AppxPackage -ErrorAction Stop | Where-Object { -not $_.IsFramework -and [string]$_.SignatureKind -ne 'System' -and $_.NonRemovable -ne $true -and -not $_.IsResourcePackage }).Count } catch { }
    $auto = 0
    foreach ($src in @(@('HKLM', 'SOFTWARE\Microsoft\Windows\CurrentVersion\Run'), @('HKLM', 'SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Run'), @('HKCU', 'Software\Microsoft\Windows\CurrentVersion\Run'))) {
        $k = Open-CcRegKey $src[0] $src[1]; if ($k) { try { $auto += @($k.GetValueNames() | Where-Object { $_ }).Count } finally { $k.Close() } }
    }
    foreach ($f in @([Environment]::GetFolderPath('Startup'), [Environment]::GetFolderPath('CommonStartup'))) { if ($f -and [IO.Directory]::Exists($f)) { $auto += @([IO.Directory]::GetFiles($f) | Where-Object { [IO.Path]::GetFileName($_) -ne 'desktop.ini' }).Count } }
    $ext = 0
    $ctx = New-CcContext $null
    foreach ($pr in @(Get-CcProfiles | ForEach-Object { $_ })) {
        foreach ($b in (Get-CcBrowserDefs)) {
            foreach ($bp in @(Get-CcBrowserProfileDirs $b $pr $ctx | ForEach-Object { $_ })) {
                if ($b.Kind -eq 'Chromium') { $ed = [IO.Path]::Combine($bp.Pr, 'Extensions'); if ([IO.Directory]::Exists($ed)) { $ext += @([IO.Directory]::GetDirectories($ed) | Where-Object { [IO.Path]::GetFileName($_) -match '^[a-p]{32}$' }).Count } }
                else { $j = Read-CcJsonFile ([IO.Path]::Combine($bp.Pr, 'extensions.json')); $ext += @($j.addons | Where-Object { $_ -and [string]$_.type -eq 'extension' -and [string]$_.location -notlike 'app-*' }).Count }
            }
        }
    }
    return [pscustomobject]@{ Programs = $prg; Apps = $apps; Startup = $auto; Extensions = $ext }
}
