    'Initialize-CcNative', 'Invoke-CcDb', 'Get-CcCookieWhere', 'Get-CcChromiumProfiles', 'Get-CcBrowserProfileDirs', 'Invoke-CcBrowser', 'Invoke-CcSpecial', 'Invoke-CcItem', 'Invoke-CcAnalyze', 'Get-CcPresence',
    'Get-CcState', 'Set-CcState', 'Get-CcRegCatNames', 'Open-CcRegKey', 'Get-CcRefPath', 'Test-CcPathMissing', 'ConvertTo-CcPackedGuid', 'Test-CcMsiRegistered', 'Get-CcRegFindings', 'Invoke-CcRegFix',
    'Get-CcRegBackups', 'Restore-CcRegBackup', 'Split-CcCommand', 'Get-CcPrograms', 'Test-CcProgramPresent', 'Invoke-CcUninstall', 'Get-CcCleanName', 'Find-CcLeftovers', 'Remove-CcLeftovers',
    'Read-CcJsonFile', 'Resolve-CcExtMsg', 'Get-CcProp', 'Get-CcExtensions', 'Test-CcKnownHost', 'Get-CcPolicyValues', 'Get-CcBrowserHome', 'Remove-CcExtension', 'Get-CcFileCompany', 'Get-CcContextItems',
