# =====================================================================
#  Engine-Teile (laufen im Hintergrundprozess bzw. im Zeitplan; brauchen Write-PLog, Set-PStatus, Test-PCancel)
# =====================================================================
# CleanerRun: Elemente aus $Script:JobOpts.Items, sonst aus der Einstellung Cleaner.Items, sonst Profil "Sicher".
# -AsStep: Aufruf als Schritt der normalen Aufräumen-Pflege (Rückgabe = Bytes, Summe macht Invoke-CleanStep)
function Invoke-CcCleanJob {
    param([switch]$AsStep)
    $o = $Script:JobOpts
    $cc = $null; if ($Script:Cfg -and $Script:Cfg.PSObject.Properties['Cleaner']) { $cc = $Script:Cfg.Cleaner }
    $cat = @(Get-CcCatalog | ForEach-Object { $_ })
    $ids = @()
    if (-not $AsStep -and $o -and $o.PSObject.Properties['Items'] -and @($o.Items).Count) { $ids = @(ConvertTo-CcIdList $o.Items | ForEach-Object { $_ }) }
    elseif ($cc -and [string]$cc.Items) { $ids = @(ConvertTo-CcIdList ([string]$cc.Items) | ForEach-Object { $_ }) }
    if (-not $ids.Count) { $ids = @(Get-CcProfileIds 'Sicher' $cat) }
    $keep = ''
    if (-not $AsStep -and $o -and $o.PSObject.Properties['KeepCookies']) { $keep = [string]$o.KeepCookies } elseif ($cc) { $keep = [string]$cc.KeepCookies }
    $days = @{}
    if ($Script:Cfg -and $Script:Cfg.Clean) { foreach ($k in 'UserTempDays', 'WinTempDays', 'RecycleBinDays', 'WERDays', 'OldLogsDays') { try { $days[$k] = [int]$Script:Cfg.Clean.$k } catch { } } }
    $profiles = @(Get-CcProfiles | ForEach-Object { $_ })
    $ctx = New-CcContext @{ Days = $days; Keep = $keep }
    $items = @($cat | Where-Object { $ids -contains $_.Id })
    $verb = if ($Script:DryRun) { 'möglich' } else { 'entfernt' }
    if (-not $AsStep) { Write-PLog ('PC-Reiniger: {0} Bereiche ausgewählt{1}' -f $items.Count, $(if ($keep) { ' - Cookie-Ausnahmen: ' + $keep } else { '' })) }
    $total = [int64]0; $entries = [int64]0; $i = 0; $skipped = 0
    foreach ($it in $items) {
        if (Test-PCancel) { Write-PLog 'PC-Reiniger abgebrochen' 'WARN'; break }
        $i++
        $label = if ($it.Group -eq 'Browser') { '{0}: {1}' -f $it.Sub, $it.Title } else { $it.Title }
        $Script:Detail = ('{0} ({1}/{2})' -f $label, $i, $items.Count)
        Set-PStatus $Script:StatusText
        $b = [int64]0; $note = ''; $ent = [int64]0
        if ($it.Fn -and (Get-Command $it.Fn -CommandType Function -ErrorAction SilentlyContinue)) {
            try { $b = [int64](@(& $it.Fn) | Where-Object { $_ -is [ValueType] } | Measure-Object -Sum).Sum } catch { $note = $_.Exception.Message }
        } else {
            $r = Invoke-CcItem $it $profiles $ctx (-not $Script:DryRun)
            $b = [int64]$r.Bytes; $ent = [int64]$r.Entries; $note = [string]$r.Note
            if ($r.Skipped) { $skipped++ }
        }
        $total += $b; $entries += $ent
        $line = '   {0}: {1} {2}{3}{4}' -f $label, (Format-CcSize $b), $verb, $(if ($ent -gt 0) { (', {0:N0} Einträge' -f $ent) } else { '' }), $(if ($note) { ' - ' + $note } else { '' })
        Write-PLog $line $(if ($note -like 'übersprungen*' -or $note -like 'Fehler*' -or $note -like 'Datenbank gesperrt*') { 'WARN' } else { 'OK' })
    }
    if (-not $Script:DryRun) {
        Set-CcState $CcStateFile 'LastClean' ([pscustomobject]@{ Time = (Get-Date).ToString('dd.MM.yyyy HH:mm'); Bytes = $total; Entries = $entries; Items = $items.Count; Skipped = $skipped; Auto = [bool]$AsStep })
    }
    if ($AsStep) { return [int64]$total }
    $Script:Freed += $total
    Write-PLog ('PC-Reiniger: {0} {1}{2}{3}' -f (Format-CcSize $total), $(if ($Script:DryRun) { 'freigebbar' } else { 'freigegeben' }), $(if ($entries -gt 0) { (', {0:N0} Einträge (Verlauf, Cookies, Listen)' -f $entries) } else { '' }), $(if ($skipped) { (' - {0} Bereich(e) übersprungen, weil das Programm lief' -f $skipped) } else { '' })) 'OK'
}
# CleanerWipe: freien Speicher eines Laufwerks mit cipher /w überschreiben (3 Durchgänge: 0x00, 0xFF, Zufall)
function Invoke-CcWipeJob {
    $o = $Script:JobOpts
    $drv = ([string]$(if ($o) { $o.Drive } else { '' })).Trim().TrimEnd('\').TrimEnd(':')
    if ($drv -notmatch '^[A-Za-z]$') { Write-PLog 'Freien Speicher löschen: kein gültiges Laufwerk angegeben.' 'FEHLER'; return }
    $root = $drv.ToUpper() + ':\'
    $di = $null; try { $di = New-Object IO.DriveInfo $root } catch { }
    if (-not $di -or -not $di.IsReady) { Write-PLog ('Laufwerk {0} ist nicht bereit.' -f $root) 'FEHLER'; return }
    if ([string]$di.DriveType -ne 'Fixed') { Write-PLog ('Laufwerk {0} ist kein festes Laufwerk - abgebrochen.' -f $root) 'FEHLER'; return }
    if ([string]$di.DriveFormat -notin 'NTFS', 'ReFS') { Write-PLog ('Laufwerk {0} hat das Dateisystem {1} - cipher /w wird nur für NTFS/ReFS unterstützt.' -f $root, $di.DriveFormat) 'FEHLER'; return }
    $free0 = [double]$di.AvailableFreeSpace
    Write-PLog ('Freien Speicher löschen auf {0} ({1} frei) - 3 Durchgänge: Nullen, Einsen, Zufallszahlen. Vorhandene Dateien bleiben unberührt.' -f $root, (Format-CcSize $free0))
    Write-PLog 'Während des Laufs ist das Laufwerk vorübergehend fast voll (Ordner EFSTMPWP) - das ist normal; der Platz wird am Ende wieder freigegeben.'
    $out = [IO.Path]::Combine($env:TEMP, ('PCPflege_cipher_{0:yyyyMMdd_HHmmss}.txt' -f (Get-Date)))
    $cipher = [IO.Path]::Combine($env:SystemRoot, 'System32\cipher.exe')
    $t0 = Get-Date
    $p = Start-Process -FilePath ([IO.Path]::Combine($env:SystemRoot, 'System32\cmd.exe')) -ArgumentList ('/c ""{0}" /w:{1} > "{2}" 2>&1"' -f $cipher, $root, $out) -WindowStyle Hidden -PassThru
    $sw = [Diagnostics.Stopwatch]::StartNew(); $lastPass = 0; $cancel = $false; $fsPass = 1; $lastFill = [double]0
    while (-not $p.HasExited) {
        if (Test-PCancel) {
            $cancel = $true
            foreach ($c in @(Get-Process -Name cipher -ErrorAction SilentlyContinue)) { try { if ($c.StartTime -ge $t0.AddSeconds(-5)) { $c.Kill() } } catch { } }
            try { $p.Kill() } catch { }
            break
        }
        $txt = ''
        try { $fs = New-Object IO.FileStream($out, [IO.FileMode]::Open, [IO.FileAccess]::Read, [IO.FileShare]'ReadWrite, Delete'); try { $txt = (New-Object IO.StreamReader($fs, [Text.Encoding]::Default)).ReadToEnd() } finally { $fs.Dispose() } } catch { }
        $pass = 1
        if ($txt -match '(?i)random|zufall|zufäll') { $pass = 3 } elseif ($txt -match '0xFF') { $pass = 2 }
        $cur = [double]0; try { $cur = [double](New-Object IO.DriveInfo $root).AvailableFreeSpace } catch { }
        $fill = if ($free0 -gt 0) { [math]::Min([double]1, [math]::Max([double]0, 1 - ($cur / $free0))) } else { [double]0 }
        # cipher puffert seine Ausgabe teilweise - Durchgangswechsel zusätzlich am wieder freigegebenen Platz erkennen
        if ($lastFill -gt 0.85 -and $fill -lt 0.3) { $fsPass = [math]::Min(3, $fsPass + 1) }
        $lastFill = $fill
        $pass = [math]::Max($pass, $fsPass)
        if ($pass -ne $lastPass) { Write-PLog ('   Durchgang {0} von 3 ({1})' -f $pass, $(switch ($pass) { 1 { 'Nullen' } 2 { 'Einsen (0xFF)' } default { 'Zufallszahlen' } })); $lastPass = $pass }
        $pct = [int]((($pass - 1) + $fill) / 3 * 100)
        $Script:Detail = ('Laufwerk {0}: Durchgang {1}/3, {2:N0} % dieses Durchgangs, gesamt ca. {3} % - läuft seit {4:hh\:mm\:ss}' -f $root, $pass, ($fill * 100), $pct, $sw.Elapsed)
        Set-PStatus ('Freien Speicher löschen ({0})' -f $root) ([math]::Min(99, $pct))
        Start-Sleep -Seconds 3
    }
    $tmpDir = [IO.Path]::Combine($root, 'EFSTMPWP')
    if ([IO.Directory]::Exists($tmpDir)) { try { [IO.Directory]::Delete($tmpDir, $true) } catch { Write-PLog ('Hilfsordner {0} bitte von Hand löschen.' -f $tmpDir) 'WARN' } }
    try { Remove-Item -LiteralPath $out -Force -ErrorAction SilentlyContinue } catch { }
    if ($cancel) { Write-PLog ('Freien Speicher löschen auf {0} abgebrochen - der Hilfsordner wurde entfernt, der Platz ist wieder frei.' -f $root) 'WARN'; return }
    $code = $p.ExitCode
    if ($code -eq 0) { Write-PLog ('Freier Speicher auf {0} überschrieben (Dauer {1:hh\:mm\:ss}). Früher gelöschte Dateien lassen sich nicht mehr wiederherstellen.' -f $root, $sw.Elapsed) 'OK' }
    else { Write-PLog ('cipher beendet mit Code {0} (Dauer {1:hh\:mm\:ss}).' -f $code, $sw.Elapsed) 'WARN' }
}
# =====================================================================
#  PC-Tools 10 (Team D): Treiber- und BIOS-Sicherung vor Updates (Ds) und Ein-Klick-Optimierung (Ok)
#  Läuft im Engine-Modus (-Run, -Auto, Fernaufträge). Die reinen Hilfsfunktionen (ohne Write-PLog)
#  werden auch von der Oberfläche und in Invoke-Bg-Runspaces benutzt.
# =====================================================================
$Script:DsJobSet = $null          # Ordner der Treiber-Sicherung dieses Laufs ('-' = ausgeschaltet) -> nur einmal pro Lauf sichern
$Script:DsJobReasons = @()        # Anlässe (welche Update-Schritte die Sicherung genutzt haben)
$Script:DsLastChanges = @()       # Änderungen nach dem Lauf (für den Ein-Klick-Bericht)

# ---------------------------------------------------------------- Ds: reine Logik (ohne Windows testbar)
function ConvertTo-DsSafeName([string]$Text) {
    $t = [string]$Text
    foreach ($p in @(@('ä', 'ae'), @('ö', 'oe'), @('ü', 'ue'), @('ß', 'ss'))) { $t = $t -replace $p[0], $p[1] }
    $t = ($t -replace '[^A-Za-z0-9]+', '-').Trim('-')
    if ($t.Length -gt 40) { $t = $t.Substring(0, 40).Trim('-') }
    if (-not $t) { $t = 'Update' }
    return $t
}
function Compare-DsVersion([string]$A, [string]$B) {
    # Treiberversionen haben oft 4 und mehr Teile (z.B. 31.0.101.5186) - Teil für Teil numerisch vergleichen, Text-Teile als Zeichenkette
    $pa = @(([string]$A).Trim() -split '[\.\-_ ,]' | Where-Object { $_ -ne '' })
    $pb = @(([string]$B).Trim() -split '[\.\-_ ,]' | Where-Object { $_ -ne '' })
    $n = [math]::Max($pa.Count, $pb.Count)
    for ($i = 0; $i -lt $n; $i++) {
        $x = if ($i -lt $pa.Count) { [string]$pa[$i] } else { '0' }
        $y = if ($i -lt $pb.Count) { [string]$pb[$i] } else { '0' }
        $xi = [int64]0; $yi = [int64]0
        if ([int64]::TryParse($x, [ref]$xi) -and [int64]::TryParse($y, [ref]$yi)) {
            if ($xi -lt $yi) { return -1 }
            if ($xi -gt $yi) { return 1 }
        } else {
            $c = [string]::Compare($x, $y, [StringComparison]::OrdinalIgnoreCase)
            if ($c -lt 0) { return -1 }
            if ($c -gt 0) { return 1 }
        }
    }
    return 0
}
function ConvertTo-DsDriverRow($D) {
    # aus Win32_PnPSignedDriver (oder einem gleich aufgebauten Testobjekt)
    $dt = ''
    try { if ($D.DriverDate) { $dt = ([datetime]$D.DriverDate).ToString('yyyy-MM-dd') } } catch { $dt = [string]$D.DriverDate }
    $cls = [string]$D.DeviceClass
    [pscustomobject]@{
        Device = [string]$D.DeviceName; DeviceId = [string]$D.DeviceID; Class = $cls; Provider = [string]$D.DriverProviderName
        Version = [string]$D.DriverVersion; Date = $dt; Inf = ([string]$D.InfName).ToLower(); HardwareId = [string]$D.HardWareID
        Firmware = [bool]($cls -eq 'FIRMWARE' -or [string]$D.DeviceName -match '(?i)firmware|UEFI|System BIOS')
    }
}
function Get-DsOrigInf([string]$StoreFolder) {
    # 'netwtw10.inf_amd64_0123abcd' -> 'netwtw10.inf'
    if (-not $StoreFolder) { return '' }
    $i = $StoreFolder.ToLower().IndexOf('.inf_')
    if ($i -gt 0) { return $StoreFolder.Substring(0, $i + 4) }
    return ''
}
function Resolve-DsExportPath([string]$StoreFolder, [string[]]$Files) {
    # $Files: relative Pfade aller .inf im Sicherungsordner. pnputil/Export-WindowsDriver legen je Paket einen Ordner wie im
    # Treiberspeicher an (netwtw10.inf_amd64_0123abcd\netwtw10.inf); ältere Windows-Versionen nur den Originalnamen.
    if (-not $StoreFolder) { return '' }
    $orig = Get-DsOrigInf $StoreFolder
    $hitDir = ''
    foreach ($f in @($Files)) {
        $p = @(([string]$f) -split '[\\/]')
        if ($p.Count -lt 2) { continue }
        if ($p[$p.Count - 2] -ieq $StoreFolder) {
            if ($p[$p.Count - 1] -ieq $orig) { return [string]$f }
            if (-not $hitDir) { $hitDir = [string]$f }
        }
    }
    if ($hitDir) { return $hitDir }
    if ($orig) {
        $cand = @($Files | Where-Object { (@(([string]$_) -split '[\\/]'))[-1] -ieq $orig })
        if ($cand.Count -eq 1) { return [string]$cand[0] }
    }
    return ''
}
function New-DsManifest {
    param([object[]]$Drivers = @(), $Bios = $null, [string]$Reason = '', [string]$Kind = 'Auto', [hashtable]$StoreMap = @{}, [string[]]$Files = @(),
          [bool]$ExportOk = $true, [string]$Computer = $env:COMPUTERNAME, $Created = $null)
    if (-not $Created) { $Created = Get-Date }
    $list = [System.Collections.Generic.List[object]]::new()
    foreach ($d in @($Drivers | Where-Object { $_ } | Sort-Object Class, Device)) {
        $inf = ([string]$d.Inf).ToLower()
        $sf = ''; if ($StoreMap -and $StoreMap.ContainsKey($inf)) { $sf = [string]$StoreMap[$inf] }
        $rel = ''; if ($ExportOk) { $rel = Resolve-DsExportPath $sf $Files }
        $list.Add([pscustomobject]@{
            Device = [string]$d.Device; DeviceId = [string]$d.DeviceId; Class = [string]$d.Class; Provider = [string]$d.Provider
            Version = [string]$d.Version; Date = [string]$d.Date; Inf = $inf; OrigInf = (Get-DsOrigInf $sf); StoreFolder = $sf
            Path = $rel; Firmware = [bool]$d.Firmware; HardwareId = [string]$d.HardwareId })
    }
    $pk = @($list | Where-Object { $_.Path } | ForEach-Object { $_.Path } | Sort-Object -Unique).Count
    [pscustomobject]@{
        Format = 1; Kind = $Kind; Created = ([datetime]$Created).ToString('yyyy-MM-ddTHH:mm:ss.fff'); Computer = $Computer; Reason = $Reason; Reasons = @($Reason)
        Bios = $Bios; ExportOk = [bool]$ExportOk; Count = $list.Count; Packages = $pk; Drivers = $list.ToArray()
    }
}
function Compare-DsManifest($Manifest, [object[]]$Rows = @(), $Bios = $null) {
    # Unterschiede gesicherter Stand -> aktueller Stand (je Gerät), dazu das BIOS. Gibt die Änderungen einzeln aus.
    $old = @{}; foreach ($d in @($Manifest.Drivers)) { if ($d -and $d.DeviceId) { $old[([string]$d.DeviceId).ToUpper()] = $d } }
    $new = @{}; foreach ($d in @($Rows)) { if ($d -and $d.DeviceId) { $new[([string]$d.DeviceId).ToUpper()] = $d } }
    $out = [System.Collections.Generic.List[object]]::new()
    foreach ($k in @($new.Keys | Sort-Object)) {
        $n = $new[$k]
        if ($old.ContainsKey($k)) {
            $o = $old[$k]
            $cmp = Compare-DsVersion ([string]$n.Version) ([string]$o.Version)
            $chg = ''
            if ($cmp -gt 0) { $chg = 'aktualisiert' } elseif ($cmp -lt 0) { $chg = 'zurückgestuft' } elseif ([string]$n.Inf -ne [string]$o.Inf -and [string]$o.Inf) { $chg = 'anderes Paket' }
            if (-not $chg) { continue }
            $out.Add([pscustomobject]@{ Kind = $(if ($o.Firmware -or $n.Firmware) { 'Firmware' } else { 'Treiber' }); Device = [string]$n.Device; Class = [string]$n.Class; DeviceId = [string]$n.DeviceId
                Before = [string]$o.Version; After = [string]$n.Version; BeforeDate = [string]$o.Date; AfterDate = [string]$n.Date; Change = $chg
                SavedInf = [string]$o.Inf; NowInf = [string]$n.Inf; Path = [string]$o.Path; CanRestore = [bool]($o.Path -and -not ($o.Firmware -or $n.Firmware)) })
        } else {
            $out.Add([pscustomobject]@{ Kind = $(if ($n.Firmware) { 'Firmware' } else { 'Treiber' }); Device = [string]$n.Device; Class = [string]$n.Class; DeviceId = [string]$n.DeviceId
                Before = ''; After = [string]$n.Version; BeforeDate = ''; AfterDate = [string]$n.Date; Change = 'neu'
                SavedInf = ''; NowInf = [string]$n.Inf; Path = ''; CanRestore = $false })
        }
    }
    foreach ($k in @($old.Keys | Sort-Object)) {
        if ($new.ContainsKey($k)) { continue }
        $o = $old[$k]
        $out.Add([pscustomobject]@{ Kind = $(if ($o.Firmware) { 'Firmware' } else { 'Treiber' }); Device = [string]$o.Device; Class = [string]$o.Class; DeviceId = [string]$o.DeviceId
            Before = [string]$o.Version; After = ''; BeforeDate = [string]$o.Date; AfterDate = ''; Change = 'entfernt / nicht verbunden'
            SavedInf = [string]$o.Inf; NowInf = ''; Path = [string]$o.Path; CanRestore = [bool]($o.Path -and -not $o.Firmware) })
    }
    if ($Manifest.Bios -and $Bios -and [string]$Manifest.Bios.Version -and [string]$Bios.Version -and ([string]$Manifest.Bios.Version).Trim() -ne ([string]$Bios.Version).Trim()) {
        $cb = Compare-DsVersion ([string]$Bios.Version) ([string]$Manifest.Bios.Version)
        $out.Add([pscustomobject]@{ Kind = 'BIOS'; Device = ('BIOS/UEFI {0} {1}' -f $Bios.Vendor, $Bios.Model).Trim(); Class = 'BIOS'; DeviceId = 'BIOS'
            Before = [string]$Manifest.Bios.Version; After = [string]$Bios.Version; BeforeDate = [string]$Manifest.Bios.Release; AfterDate = [string]$Bios.Release
            Change = $(if ($cb -lt 0) { 'zurückgestuft' } else { 'aktualisiert' }); SavedInf = ''; NowInf = ''; Path = ''; CanRestore = $false })
    }
    $out.ToArray()
}
function Test-DsSameState($Manifest, [object[]]$Rows = @(), $Bios = $null) { @(Compare-DsManifest $Manifest $Rows $Bios).Count -eq 0 }
function Select-DsPrune([object[]]$Sets = @(), [int]$Keep = 5, [string]$Protect = '') {
    # Nur automatische Sätze (Kind 'Auto') werden ausgedünnt - die neuesten $Keep bleiben; von Hand angelegte Sicherungen nie; $Protect (Satz dieses Laufs) nie
    if ($Keep -lt 1) { $Keep = 1 }
    @($Sets | Where-Object { $_ -and [string]$_.Kind -eq 'Auto' } | Sort-Object { [string]$_.Created } -Descending | Select-Object -Skip $Keep | Where-Object { [string]$_.Path -ne $Protect })
}
function Get-DsRoot([string]$Base = '') { if (-not $Base) { $Base = $DataDir }; Join-Path $Base 'Treiber-Sicherung' }
function Read-DsManifest([string]$Dir) {
    $f = Join-Path $Dir 'Sicherung.json'
    if (-not (Test-Path -LiteralPath $f)) { return $null }
    try { return (Get-Content -LiteralPath $f -Raw -Encoding UTF8 | ConvertFrom-Json) } catch { return $null }
}
function Test-DsAutoSet([string]$Dir) { $m = Read-DsManifest $Dir; return [bool]($m -and [string]$m.Kind -eq 'Auto') }
function Get-DsSets([string]$Root) {
    foreach ($d in @(Get-ChildItem -LiteralPath $Root -Directory -ErrorAction SilentlyContinue)) {
        $m = Read-DsManifest $d.FullName
        if (-not $m) { continue }
        $after = $null; $cf = Join-Path $d.FullName 'Aenderungen.json'
        if (Test-Path -LiteralPath $cf) { try { $after = Get-Content -LiteralPath $cf -Raw -Encoding UTF8 | ConvertFrom-Json } catch { } }
        $cr = $m.Created; if ($cr -is [datetime]) { $cr = $cr.ToString('yyyy-MM-ddTHH:mm:ss.fff') }   # PowerShell 7 wandelt ISO-Datumstexte beim Einlesen in DateTime um
        [pscustomobject]@{ Path = $d.FullName; Name = $d.Name; Kind = [string]$m.Kind; Created = [string]$cr; Reason = (@($m.Reasons | Where-Object { $_ }) -join ' · '); Manifest = $m; After = $after }
    }
}
function Get-DsBiosHint([string]$Vendor) {
    # Rückweg für BIOS/UEFI-Firmware: PC-Tools flasht nie selbst - nur Anleitung je Hersteller
    switch -Regex ([string]$Vendor) {
        'HP|Hewlett' { return 'HP: Ältere BIOS-Version (SoftPaq) von support.hp.com für genau dieses Modell laden und starten bzw. mit HP Image Assistant/HP BIOS Configuration Utility einspielen. Im BIOS-Setup (F10) unter Sicherheit > BIOS-Update-Einstellungen muss "BIOS-Rollback-Richtlinie: Rollback auf ältere BIOS-Versionen zulassen" aktiv sein; bei vielen Business-Geräten hilft auch "HP Sure Start" mit der gesicherten Kopie (Win+B+V beim Einschalten halten = BIOS-Wiederherstellung). BitLocker vorher anhalten.' }
        'Lenovo' { return 'Lenovo: Ältere BIOS-Version von pcsupport.lenovo.com (Modell/Typnummer) laden und unter Windows starten. Rückstufen geht nur, wenn im BIOS-Setup (F1) unter Security > "Secure Rollback Prevention" auf Disabled steht - manche Versionen sperren ein Zurück dauerhaft (siehe Hinweise in der README des BIOS-Pakets). BitLocker vorher anhalten.' }
        'Dell' { return 'Dell: Ältere BIOS-Version von dell.com/support (Service-Tag) laden und als Administrator starten; im BIOS-Setup (F2) unter Update/Recovery "BIOS Downgrade" erlauben. Alternativ beim Start F12 > "BIOS Flash Update" mit der Datei auf einem USB-Stick. Dell BIOS-Recovery: Strg+Esc beim Einschalten. BitLocker vorher anhalten.' }
        'Microsoft' { return 'Surface: Firmware wird über Windows Update bzw. das Surface-Treiberpaket (MSI) geliefert - ein Zurückstufen sieht Microsoft nicht vor (UEFI-Sperre gegen ältere Versionen). Bei Problemen: Surface-UEFI zurücksetzen (Lauter-Taste + Ein/Aus) und den Microsoft-Support kontaktieren.' }
        'ASUS|ASUSTeK' { return 'ASUS: Ältere BIOS-Version von asus.com/support laden und per EZ Flash im BIOS-Setup (F2/Entf) einspielen; bei Mainboards mit "USB BIOS FlashBack" auch ohne Start möglich. Manche Versionen (Sicherheits-Updates von Intel/AMD) lassen kein Zurück zu.' }
        'Acer' { return 'Acer: Ältere BIOS-Version von acer.com/support laden und unter Windows starten; Acer erlaubt Rückstufen nicht bei allen Modellen. BitLocker vorher anhalten.' }
        default { return 'BIOS/UEFI: Ältere Version nur von der Support-Seite des Herstellers für genau dieses Modell laden und nach dessen Anleitung einspielen (oft muss "BIOS-Downgrade/Rollback" im BIOS-Setup erlaubt werden). Vorher BitLocker anhalten, Netzteil anschließen und nichts abbrechen. PC-Tools spielt BIOS-Versionen nie selbst ein.' }
    }
}

# ---------------------------------------------------------------- Ds: Windows-Teil (Engine und Oberfläche)
function Get-DsDriverRows {
    # alle aktiven Treiber aus zusätzlichen Paketen (oemNN.inf = nicht von Windows mitgeliefert) - genau die exportiert pnputil
    foreach ($d in @(Get-CimInstance Win32_PnPSignedDriver -ErrorAction Stop)) {
        if (-not $d.DeviceID -or -not ([string]$d.InfName -match '^(?i)oem\d+\.inf$')) { continue }
        ConvertTo-DsDriverRow $d
    }
}
function Get-DsBiosInfo {
    $b = $null; $cs = $null
    try { $b = Get-CimInstance Win32_BIOS -ErrorAction Stop } catch { }
    try { $cs = Get-CimInstance Win32_ComputerSystem -ErrorAction Stop } catch { }
    $rd = ''; try { if ($b.ReleaseDate) { $rd = ([datetime]$b.ReleaseDate).ToString('yyyy-MM-dd') } } catch { }
    [pscustomobject]@{ Vendor = [string]$cs.Manufacturer; Model = [string]$cs.Model; BiosVendor = [string]$b.Manufacturer; Version = [string]$b.SMBIOSBIOSVersion; Release = $rd
        Ec = $(if ($b -and $null -ne $b.EmbeddedControllerMajorVersion -and [int]$b.EmbeddedControllerMajorVersion -lt 255) { '{0}.{1}' -f $b.EmbeddedControllerMajorVersion, $b.EmbeddedControllerMinorVersion } else { '' }) }
}
function Get-DsStoreMap {
    # oemNN.inf -> Ordner im Treiberspeicher (HKLM\SYSTEM\DriverDatabase\DriverInfFiles\oemNN.inf: "Active" bzw. erster Eintrag)
    $m = @{}
    foreach ($k in @(Get-ChildItem 'HKLM:\SYSTEM\DriverDatabase\DriverInfFiles' -ErrorAction SilentlyContinue | Where-Object { $_.PSChildName -match '^(?i)oem\d+\.inf$' })) {
        $act = ''
        try { $act = [string]$k.GetValue('Active') } catch { }
        if (-not $act) { try { $act = [string](@($k.GetValue(''))[0]) } catch { } }
        if ($act) { $m[$k.PSChildName.ToLower()] = $act }
    }
    if (-not $m.Count) {
        # Ersatzweg (langsamer): DISM liefert je oemNN.inf den Pfad im Treiberspeicher
        try { foreach ($w in @(Get-WindowsDriver -Online -ErrorAction Stop)) { if ([string]$w.Driver -match '^(?i)oem\d+\.inf$' -and $w.OriginalFileName) { $m[([string]$w.Driver).ToLower()] = Split-Path (Split-Path ([string]$w.OriginalFileName) -Parent) -Leaf } } } catch { }
    }
    return $m
}
function Get-DsExportEstimate([hashtable]$StoreMap) {
    $sum = [int64]0
    $repo = Join-Path $env:SystemRoot 'System32\DriverStore\FileRepository'
    foreach ($f in @($StoreMap.Values | Sort-Object -Unique)) {
        $sum += [int64](@(Get-ChildItem -LiteralPath (Join-Path $repo $f) -Recurse -File -Force -ErrorAction SilentlyContinue) | Measure-Object Length -Sum).Sum
    }
    return $sum
}
function Write-DsManifestFile($Manifest, [string]$Dir) {
    $Manifest | ConvertTo-Json -Depth 6 | Set-Content -LiteralPath (Join-Path $Dir 'Sicherung.json') -Encoding UTF8
    $b = $Manifest.Bios
    Set-Content -LiteralPath (Join-Path $Dir 'LIESMICH.txt') -Encoding UTF8 -Value @(
        ('Treiber- und BIOS-Sicherung von {0} vom {1:dd.MM.yyyy HH:mm}' -f $Manifest.Computer, [datetime]$Manifest.Created),
        ('Anlass: {0}' -f $Manifest.Reason),
        ('BIOS/UEFI: {0} vom {1} ({2} {3})' -f $b.Version, $b.Release, $b.Vendor, $b.Model), '',
        ('{0} Geräte mit zusätzlichen Treibern, {1} Treiberpakete gesichert. Liste: Sicherung.json' -f $Manifest.Count, $Manifest.Packages), '',
        'Zurückspielen: PC-Tools > Treiber > Treiber-Sicherungen vor Updates (je Gerät oder alle).',
        'Ohne PC-Tools (Eingabeaufforderung als Administrator): pnputil /add-driver "<dieser Ordner>\*.inf" /subdirs /install',
        'Ein BIOS wird nie automatisch zurückgespielt - Anleitung des Herstellers beachten.')
}
function Invoke-DsRetention([string]$Root, [int]$Keep, [string]$Protect = '') {
    $del = @(Select-DsPrune @(Get-DsSets $Root) $Keep $Protect)
    $n = 0
    foreach ($s in $del) {
        try { Remove-Item -LiteralPath $s.Path -Recurse -Force -ErrorAction Stop; $n++; if (Get-Command Write-PLog -ErrorAction SilentlyContinue) { Write-PLog ('   Alte Treiber-Sicherung entfernt: {0}' -f $s.Name) } } catch { }
    }
    return $n
}
function Get-DsConfig {
    $c = $null
    try { $c = $Script:Cfg.DriverSafety } catch { }
    if (-not $c) { try { $c = (Read-PflegeConfig).DriverSafety } catch { } }
    $en = $true; $keep = 5
    if ($c) { if ($null -ne $c.Enabled) { $en = [bool]$c.Enabled }; if ([int]$c.Keep -gt 0) { $keep = [int]$c.Keep } }
    [pscustomobject]@{ Enabled = $en; Keep = $keep }
}
function Invoke-DsRestorePoint([int]$FreshMinutes = 120) {
    # Windows legt ohne Ausnahme höchstens einen Punkt je 24 Stunden an (SystemRestorePointCreationFrequency) - New-PflegeRestorePoint setzt die Ausnahme.
    # Ein frischer Punkt (jünger als $FreshMinutes, z.B. vom Schritt "Wiederherstellungspunkt" dieses Laufs) wird genutzt statt einen weiteren anzulegen.
    if ($Script:DryRun -or $Script:CheckOnly) { return }
    $last = $null; try { $last = @(Get-ComputerRestorePoint -ErrorAction Stop | Sort-Object SequenceNumber -Descending)[0] } catch { }
    if ($last) {
        $t = $null; try { $t = [Management.ManagementDateTimeConverter]::ToDateTime([string]$last.CreationTime) } catch { }
        if ($t -and ((Get-Date) - $t).TotalMinutes -lt $FreshMinutes) { Write-PLog ('Wiederherstellungspunkt von {0:HH:mm} Uhr ist aktuell genug: "{1}"' -f $t, $last.Description) 'OK'; return }
    }
    New-PflegeRestorePoint
}
function Write-DsManualManifest([string]$Dir) {
    # von Invoke-DriverBackup (Teil "DriverBackup") aufgerufen: macht die Sicherung vergleich- und je Gerät zurückspielbar
    $files = @(Get-ChildItem -LiteralPath $Dir -Filter *.inf -Recurse -File -ErrorAction SilentlyContinue | ForEach-Object { $_.FullName.Substring($Dir.TrimEnd('\').Length + 1) })
    $man = New-DsManifest -Drivers @(Get-DsDriverRows) -Bios (Get-DsBiosInfo) -Reason 'Treibersicherung (von Hand)' -Kind 'Manuell' -StoreMap (Get-DsStoreMap) -Files $files -ExportOk ([bool]$files.Count)
    Write-DsManifestFile $man $Dir
    if (-not $Script:DsJobSet) { $Script:DsJobSet = $Dir; $Script:DsJobReasons = @('Treibersicherung (von Hand)') }
}
function Invoke-DsBeforeDriverUpdate([string]$Reason = 'Treiber-Update') {
    # Aufruf direkt vor jedem Treiber-/BIOS-/Firmware-Update. Pro Lauf nur einmal; unveränderter Stand -> letzte Sicherung wiederverwenden.
    if ($Script:DryRun -or $Script:CheckOnly) { return }
    if ($Script:DsJobSet) { if ($Script:DsJobSet -ne '-' -and @($Script:DsJobReasons) -notcontains $Reason) { $Script:DsJobReasons = @($Script:DsJobReasons) + $Reason }; return }
    $cfg = Get-DsConfig
    if (-not $cfg.Enabled) { $Script:DsJobSet = '-'; Write-PLog 'Treiber-Sicherung vor Updates ist ausgeschaltet (Seite Treiber).'; return }
    $saveDetail = $Script:Detail; $saveStatus = $Script:StatusText
    try {
        $Script:Detail = ('Treiber- und BIOS-Stand wird vor dem Update gesichert ({0})' -f $Reason); Set-PStatus $saveStatus
        Write-PLog ('Treiber-Sicherung vor dem Update ({0}) ...' -f $Reason)
        $rows = @(Get-DsDriverRows); $bios = Get-DsBiosInfo
        $root = Get-DsRoot; New-Item $root -ItemType Directory -Force | Out-Null
        $last = @(Get-DsSets $root | Where-Object { $_.Manifest.ExportOk } | Sort-Object Created -Descending) | Select-Object -First 1
        $age = 999; if ($last) { try { $age = ((Get-Date) - [datetime]$last.Created).TotalDays } catch { } }
        if ($last -and $age -lt 60 -and (Test-DsSameState $last.Manifest $rows $bios)) {
            $Script:DsJobSet = $last.Path; $Script:DsJobReasons = @($Reason)
            try { $m = $last.Manifest; $m.Reasons = @(@($m.Reasons) + ('{0:dd.MM.yyyy HH:mm} {1}' -f (Get-Date), $Reason) | Select-Object -Last 12); Write-DsManifestFile $m $last.Path } catch { }
            Write-PLog ('   Treiber und BIOS ({0}) unverändert seit der Sicherung vom {1:dd.MM.yyyy HH:mm} - wird wiederverwendet: {2}' -f $bios.Version, [datetime]$last.Created, $last.Path) 'OK'
        } else {
            $dir = Join-Path $root ('{0:yyyy-MM-dd_HHmmss}_{1}' -f (Get-Date), (ConvertTo-DsSafeName $Reason))
            New-Item $dir -ItemType Directory -Force | Out-Null
            $map = Get-DsStoreMap
            $est = [int64]0; try { $est = Get-DsExportEstimate $map } catch { }
            $free = [int64]-1; try { $free = (New-Object IO.DriveInfo ([IO.Path]::GetPathRoot($dir))).AvailableFreeSpace } catch { }
            $exportOk = $false
            if ($free -ge 0 -and $free -lt ($est + 5GB)) {
                Write-PLog ('   Zu wenig Platz für die Treiber ({0:N1} GB nötig, {1:N1} GB frei) - nur Liste und BIOS-Stand werden gesichert.' -f (($est + 5GB) / 1GB), ($free / 1GB)) 'WARN'
            } else {
                $Script:Detail = ('Treiberpakete werden exportiert (ca. {0:N1} GB)' -f ($est / 1GB)); Set-PStatus $saveStatus
                $rc = Invoke-External -Exe (Join-Path $env:SystemRoot 'System32\pnputil.exe') -Arguments @('/export-driver', '*', ('"{0}"' -f $dir)) -TimeoutMin 30 -Quiet
                $n = @(Get-ChildItem -LiteralPath $dir -Filter *.inf -Recurse -File -ErrorAction SilentlyContinue).Count
                if (-not $n -and -not (Test-PCancel)) {
                    Write-PLog ('   pnputil meldet Code {0} ohne Treiber - zweiter Versuch mit Export-WindowsDriver' -f $rc) 'WARN'
                    try { $null = Export-WindowsDriver -Online -Destination $dir -ErrorAction Stop } catch { Write-PLog ('   Export-WindowsDriver: {0}' -f $_.Exception.Message) 'WARN' }
                    $n = @(Get-ChildItem -LiteralPath $dir -Filter *.inf -Recurse -File -ErrorAction SilentlyContinue).Count
                }
                $exportOk = [bool]$n
            }
            $files = @(Get-ChildItem -LiteralPath $dir -Filter *.inf -Recurse -File -ErrorAction SilentlyContinue | ForEach-Object { $_.FullName.Substring($dir.TrimEnd('\').Length + 1) })
            $man = New-DsManifest -Drivers $rows -Bios $bios -Reason $Reason -Kind 'Auto' -StoreMap $map -Files $files -ExportOk $exportOk
            Write-DsManifestFile $man $dir
            $Script:DsJobSet = $dir; $Script:DsJobReasons = @($Reason)
            $noPath = @($man.Drivers | Where-Object { -not $_.Path -and -not $_.Firmware }).Count
            Write-PLog ('   Treiber-Sicherung: {0} Geräte, {1} Pakete, BIOS {2} vom {3} - {4}{5}' -f $man.Count, $man.Packages, $bios.Version, $bios.Release, $dir, $(if ($exportOk -and $noPath) { (' ({0} Geräte ohne zuordenbares Paket)' -f $noPath) } else { '' })) $(if ($exportOk) { 'OK' } else { 'WARN' })
            $null = Invoke-DsRetention $root $cfg.Keep $dir
        }
    } catch {
        Write-PLog ('Treiber-Sicherung fehlgeschlagen: {0} - das Update läuft trotzdem weiter (Wiederherstellungspunkt als Rückweg).' -f $_.Exception.Message) 'WARN'
        if (-not $Script:DsJobSet) { $Script:DsJobSet = '-' }
    }
    try { $null = Invoke-DsRestorePoint } catch { }
    $Script:Detail = $saveDetail; Set-PStatus $saveStatus
}
function Complete-DsAfterUpdate {
    # am Ende des Laufs: gesicherten Stand mit dem jetzigen vergleichen, Änderungen ins Protokoll und nach Aenderungen.json
    $set = [string]$Script:DsJobSet; $reasons = @($Script:DsJobReasons)
    $Script:DsJobSet = $null; $Script:DsJobReasons = @(); $Script:DsLastChanges = @()
    if (-not $set -or $set -eq '-') { return }
    $man = Read-DsManifest $set
    if (-not $man) { return }
    $bios = Get-DsBiosInfo
    $chg = @(Compare-DsManifest $man @(Get-DsDriverRows) $bios)
    $pend = $false; try { $pend = [bool](Test-PendingReboot) } catch { }
    try { [pscustomobject]@{ Time = (Get-Date).ToString('s'); Reasons = $reasons; RebootPending = $pend; Changes = @($chg) } | ConvertTo-Json -Depth 5 | Set-Content -LiteralPath (Join-Path $set 'Aenderungen.json') -Encoding UTF8 } catch { }
    $Script:DsLastChanges = $chg
    if ($chg.Count) {
        Write-PLog ('Treiber-Sicherung: {0} Änderung(en) gegenüber dem gesicherten Stand:' -f $chg.Count)
        foreach ($c in @($chg | Select-Object -First 40)) { Write-PLog ('   {0} - {1}: {2} -> {3} ({4})' -f $c.Kind, $c.Device, $(if ($c.Before) { $c.Before } else { '-' }), $(if ($c.After) { $c.After } else { '-' }), $c.Change) }
        Write-PLog '   Zurückspielen: Seite Treiber > Treiber-Sicherungen vor Updates.'
    } else { Write-PLog 'Treiber-Sicherung: keine Treiber geändert.' 'OK' }
    if ($pend) { Write-PLog '   BIOS- und Firmware-Updates werden oft erst beim Neustart eingespielt - die Seite Treiber vergleicht danach erneut.' }
}

# ---------------------------------------------------------------- Ok: reine Logik (ohne Windows testbar)
function Get-OkPhaseDefs {
    # Schlüssel, Titel, Gewicht für den Fortschritt, Glyph
    @(
        @('ScoreBefore', 'Zustand vorher', 4, 0xE9D9), @('Restore', 'Wiederherstellungspunkt', 3, 0xE777), @('Clean', 'Aufräumen', 16, 0xE74D),
        @('Windows', 'Windows-Updates', 26, 0xE895), @('Drivers', 'Treiber und Firmware', 16, 0xE964), @('Programs', 'Programme und Virenschutz', 14, 0xE71D),
        @('Repair', 'Optimieren und Systemprüfung', 10, 0xE90F), @('AutoRepair', 'Fehler automatisch beheben', 10, 0xE90F), @('Security', 'Sicherheit', 3, 0xE72E), @('Backup', 'Datensicherung', 2, 0xE8F7),
        @('ScoreAfter', 'Zustand nachher', 4, 0xE9D9), @('Report', 'Bericht', 2, 0xE8A5)
    )
}
function Format-OkBytes([double]$Bytes) {
    if ($Bytes -ge 1GB) { return ('{0:N2} GB' -f ($Bytes / 1GB)) }
    if ($Bytes -ge 1MB) { return ('{0:N0} MB' -f ($Bytes / 1MB)) }
    if ($Bytes -gt 0) { return ('{0:N0} KB' -f ($Bytes / 1KB)) }
    return '0 MB'
}
function Get-OkItemKey([string]$Text) { (([string]$Text) -replace '\d+([\.,]\d+)?', '#').Trim().ToLower() }
function Get-OkFixed([object[]]$Before = @(), [object[]]$After = @()) {
    # Probleme der Ampel, die vorher da waren und nachher nicht mehr (Zahlen im Text zählen nicht - "noch 12 GB frei" bleibt dasselbe Problem)
    $ak = @{}; foreach ($a in @($After)) { if ($a) { $ak[(Get-OkItemKey $a.Text)] = $true } }
    foreach ($b in @($Before)) { if ($b -and $b.Text -and -not $ak.ContainsKey((Get-OkItemKey $b.Text))) { [string]$b.Text } }
}
function Get-OkRecommendations([object[]]$After = @(), $Score = $null) {
    # Restliche Empfehlungen: alles aus der Ampel (außer "Pflege überfällig" - die ist gerade gelaufen) + schwache Score-Bestandteile
    $out = [System.Collections.Generic.List[object]]::new(); $seen = @{}
    foreach ($a in @($After)) {
        if (-not $a -or [string]$a.Action -eq 'RunAll') { continue }
        $out.Add([pscustomobject]@{ Level = $(if ([string]$a.Level -eq 'Red') { 'Red' } else { 'Yellow' }); Text = [string]$a.Text; Detail = [string]$a.Detail; Action = [string]$a.Action; Button = $(if ($a.Button) { [string]$a.Button } else { 'Öffnen' }) })
        $seen[[string]$a.Action] = $true
    }
    $map = @{ Security = @('Security', 'Sicherheit'); Updates = @('Updates', 'Updates'); Space = @('Space', 'Speicher prüfen'); Disk = @('Health', 'Gerätezustand'); Battery = @('Health', 'Gerätezustand'); Stability = @('Repair', 'Fehlersuche'); Boot = @('Custom', 'Autostart'); Devices = @('Drivers', 'Treiber'); Temp = @('Health', 'Gerätezustand') }
    if ($Score) {
        foreach ($c in @($Score.Components | Where-Object { $_ -and [string]$_.Level -in 'Bad', 'Warn' } | Sort-Object { [double]$_.Points - [double]$_.Max })) {
            $m = $map[[string]$c.Key]; if (-not $m -or $seen.ContainsKey($m[0])) { continue }
            $seen[$m[0]] = $true
            $out.Add([pscustomobject]@{ Level = $(if ([string]$c.Level -eq 'Bad') { 'Red' } else { 'Yellow' }); Text = ('{0}: {1:0.#} von {2:0} Punkten' -f $c.Name, [double]$c.Points, [double]$c.Max); Detail = [string]$c.Reason; Action = $m[0]; Button = $m[1] })
        }
    }
    @($out | Sort-Object @{ Expression = { if ($_.Level -eq 'Red') { 0 } else { 1 } } })
}
function New-OkReportHtml($R, [string]$Css = '') {
    if (-not $Css) { try { $Css = $ReportCss } catch { } }
    $h = { param($s) [Net.WebUtility]::HtmlEncode([string]$s) }
    $sb = [Text.StringBuilder]::new()
    $b = [int]$R.ScoreBefore.Score; $a = [int]$R.ScoreAfter.Score; $d = $a - $b
    $col = { param($v) if ($v -ge 85) { '#16A34A' } elseif ($v -ge 65) { '#D97706' } else { '#DC2626' } }
    [void]$sb.Append('<!DOCTYPE html><html lang="de"><head><meta charset="utf-8"><title>Ein-Klick-Optimierung</title><style>' + $Css)
    [void]$sb.Append(' .grid{display:flex;gap:10px;margin:12px 0} .tile{flex:1;border:1px solid #E2E7F0;border-radius:10px;padding:10px 12px} .tile b{display:block;font-size:17pt} .sc{display:flex;align-items:center;gap:18px;margin-top:8px} .big{font-size:34pt;font-weight:700} .arrow{font-size:20pt;opacity:.85}')
    [void]$sb.Append('</style></head><body>')
    [void]$sb.Append(('<div class="hero"><small>PC-Tools · Ein-Klick-Optimierung · {0}</small><h1>{1}</h1><small>{2} · {3} bis {4} · Dauer {5}{6}</small><div class="sc"><div><small>vorher</small><div class="big">{7}</div></div><div class="arrow">&#8594;</div><div><small>nachher</small><div class="big">{8}</div></div><div><small>Veränderung</small><div class="big">{9}</div></div></div></div>' -f
        (& $h $R.Model), (& $h $R.Computer), (& $h $R.Mode), (& $h $R.StartText), (& $h $R.EndText), (& $h $R.Duration), $(if ($R.Cancelled) { ' · abgebrochen' } else { '' }), $b, $a, $(if ($d -gt 0) { '+' + $d } else { [string]$d })))
    [void]$sb.Append(('<div class="grid"><div class="tile"><b>{0}</b>Speicher frei geworden</div><div class="tile"><b>{1}</b>Updates installiert</div><div class="tile"><b>{2}</b>Probleme behoben</div><div class="tile"><b>{3}</b>Empfehlungen offen</div></div>' -f (& $h $R.FreedText), [int]$R.Updates, @($R.Fixed).Count, @($R.Remaining).Count))
    if ($R.RebootNeeded) { [void]$sb.Append('<p class="warn">Ein Neustart ist nötig, damit alle Updates fertig installiert werden. Danach steigt der Zustands-Score meist noch weiter.</p>') }
    [void]$sb.Append('<h2>Was wurde gemacht</h2><table><tr><th>Schritt</th><th>Ergebnis</th><th>Zeit</th></tr>')
    foreach ($p in @($R.Phases)) {
        $cls = switch ([string]$p.State) { 'ok' { 'ok' } 'warn' { 'warn' } 'skip' { 'muted' } default { 'muted' } }
        $st = switch ([string]$p.State) { 'ok' { 'erledigt' } 'warn' { 'mit Hinweis' } 'skip' { 'übersprungen' } 'cancel' { 'abgebrochen' } 'run' { 'abgebrochen' } default { 'nicht ausgeführt' } }
        [void]$sb.Append(('<tr><td>{0}</td><td><span class="{1}">{2}</span> {3}</td><td class="muted">{4}</td></tr>' -f (& $h $p.Title), $cls, $st, (& $h $p.Info), $(if ([double]$p.Seconds -ge 1) { '{0:N0} s' -f [double]$p.Seconds } else { '' })))
    }
    [void]$sb.Append('</table><h2>Zustands-Score im Detail</h2><table><tr><th>Bestandteil</th><th>vorher</th><th>nachher</th><th>Begründung (nachher)</th></tr>')
    $bc = @{}; foreach ($c in @($R.ScoreBefore.Components)) { if ($c) { $bc[[string]$c.Key] = $c } }
    foreach ($c in @($R.ScoreAfter.Components)) {
        if (-not $c -or [double]$c.Max -le 0) { continue }
        $o = $bc[[string]$c.Key]; $ov = if ($o) { '{0:0.#}' -f [double]$o.Points } else { '-' }
        $cls = if ($o -and [double]$c.Points -gt [double]$o.Points) { 'ok' } elseif ($o -and [double]$c.Points -lt [double]$o.Points) { 'bad' } else { '' }
        [void]$sb.Append(('<tr><td>{0}</td><td>{1} / {2:0}</td><td class="{3}">{4:0.#} / {2:0}</td><td class="muted">{5}</td></tr>' -f (& $h $c.Name), $ov, [double]$c.Max, $cls, [double]$c.Points, (& $h $c.Reason)))
    }
    [void]$sb.Append('</table>')
    if (@($R.Fixed).Count) { [void]$sb.Append('<h2>Behoben</h2><ul>'); foreach ($f in @($R.Fixed)) { [void]$sb.Append(('<li class="ok">{0}</li>' -f (& $h $f))) }; [void]$sb.Append('</ul>') }
    if (@($R.DriverChanges).Count) {
        [void]$sb.Append('<h2>Geänderte Treiber und Firmware</h2><table><tr><th>Gerät</th><th>vorher</th><th>nachher</th><th>Änderung</th></tr>')
        foreach ($c in @($R.DriverChanges)) { [void]$sb.Append(('<tr><td>{0}</td><td>{1}</td><td>{2}</td><td>{3}</td></tr>' -f (& $h $c.Device), (& $h $c.Before), (& $h $c.After), (& $h $c.Change))) }
        [void]$sb.Append(('</table><p class="muted">Der vorherige Stand ist gesichert ({0}) und lässt sich je Gerät zurückspielen: PC-Tools &gt; Treiber &gt; Treiber-Sicherungen vor Updates.</p>' -f (& $h $R.DriverSet)))
    }
    if (@($R.Security).Count) {
        [void]$sb.Append('<h2>Sicherheit und Datensicherung</h2><table><tr><th>Prüfung</th><th>Ergebnis</th></tr>')
        foreach ($s in @(@($R.Security) + @($R.Backup))) { if ($s) { [void]$sb.Append(('<tr><td>{0}</td><td class="{1}">{2}</td></tr>' -f (& $h $s.Name), $(switch ([string]$s.State) { 'ok' { 'ok' } 'bad' { 'bad' } default { 'warn' } }), (& $h $s.Text))) } }
        [void]$sb.Append('</table>')
    }
    [void]$sb.Append('<h2>Noch zu tun</h2>')
    if (@($R.Remaining).Count) {
        [void]$sb.Append('<table><tr><th></th><th>Empfehlung</th><th>Warum</th></tr>')
        foreach ($x in @($R.Remaining)) { [void]$sb.Append(('<tr><td><span class="pill" style="background:{0};color:#fff">{1}</span></td><td>{2}</td><td class="muted">{3}</td></tr>' -f $(if ($x.Level -eq 'Red') { '#DC2626' } else { '#D97706' }), $(if ($x.Level -eq 'Red') { 'wichtig' } else { 'Hinweis' }), (& $h $x.Text), (& $h $x.Detail))) }
        [void]$sb.Append('</table>')
    } else { [void]$sb.Append('<p class="ok">Nichts - dieser PC ist rundum gepflegt.</p>') }
    [void]$sb.Append(('<p class="muted" style="margin-top:18px">Protokoll: {0}</p></body></html>' -f (& $h $R.Log)))
    $sb.ToString()
}

# ---------------------------------------------------------------- Ok: Windows-Teil (Engine)
function Get-OkDir { $d = Join-Path $DataDir 'EinKlick'; New-Item $d -ItemType Directory -Force -ErrorAction SilentlyContinue | Out-Null; return $d }
function Get-OkOpt([string]$Key) {
    $v = $null
    try { if ($Script:JobOpts -and $null -ne $Script:JobOpts.$Key) { $v = $Script:JobOpts.$Key } } catch { }
    if ($null -eq $v) { try { $v = $Script:Cfg.OneClick.$Key } catch { } }
    if ($null -eq $v) { return $true }
    return [bool]$v
}
function Save-OkPhases {
    try { @($Script:OkPhases) | ConvertTo-Json -Depth 3 | Set-Content -LiteralPath (Join-Path (Get-OkDir) 'phasen.json') -Encoding UTF8 } catch { }
}
function Set-OkPhase([string]$Key, [string]$State, [string]$Info = $null) {
    $p = @($Script:OkPhases | Where-Object { $_.Key -eq $Key })[0]
    if (-not $p) { return }
    if ($State -eq 'run') { $p.Started = (Get-Date).ToString('o') }
    elseif ($p.Started -and $State -in 'ok', 'warn', 'skip', 'cancel') { try { $p.Seconds = [math]::Round(((Get-Date) - [datetime]$p.Started).TotalSeconds, 0) } catch { } }
    $p.State = $State
    if ($null -ne $Info) { $p.Info = $Info }
    if ($State -eq 'run') {
        # Fortschritt nach Gewicht der geplanten Schritte (abgewählte zählen nicht)
        $done = 0.0; $tot = 0.0; $before = $true
        foreach ($x in $Script:OkPhases) {
            if ($x.Key -eq $Key) { $before = $false }
            if ([string]$x.Info -eq 'abgewählt') { continue }
            $tot += [double]$x.Weight; if ($before) { $done += [double]$x.Weight }
        }
        $Script:StepName = 'Ein-Klick: ' + $p.Title; $Script:Detail = ''
        Set-PStatus ('Ein-Klick-Optimierung: {0}' -f $p.Title) ([int]([math]::Min(99.0, $done * 100.0 / [math]::Max(1.0, [double]$tot))))
    }
    Save-OkPhases
}
function Get-OkSecurityItems {
    $l = [System.Collections.Generic.List[object]]::new()
    $add = { param($n, $s, $t) $l.Add([pscustomobject]@{ Name = $n; State = $s; Text = $t }) }
    $avOn = $false; $avName = ''
    try { foreach ($av in @(Get-CimInstance -Namespace root/SecurityCenter2 -ClassName AntiVirusProduct -ErrorAction Stop)) { if (((([int]$av.productState) -shr 12) -band 0xF) -in 1, 3) { $avOn = $true; $avName = [string]$av.displayName } } } catch { }
    $mp = $null; try { $mp = Get-MpComputerStatus -ErrorAction Stop } catch { }
    if (-not $avOn -and $mp -and $mp.RealTimeProtectionEnabled) { $avOn = $true; $avName = 'Microsoft Defender' }
    & $add 'Virenschutz' $(if ($avOn) { 'ok' } else { 'bad' }) $(if ($avOn) { $avName + ' aktiv' } else { 'kein Virenschutz aktiv' })
    if ($mp -and $mp.AntivirusEnabled) { $ag = [int]$mp.AntivirusSignatureAge; & $add 'Virendefinitionen' $(if ($ag -le 3) { 'ok' } elseif ($ag -le 7) { 'warn' } else { 'bad' }) ('{0} Tag(e) alt (Stand {1:dd.MM.yyyy})' -f $ag, $mp.AntivirusSignatureLastUpdated) }
    $fw = @(); try { $fw = @(Get-NetFirewallProfile -ErrorAction Stop) } catch { }
    $off = @($fw | Where-Object { [string]$_.Enabled -ne 'True' })
    if ($fw.Count) { & $add 'Firewall' $(if ($off.Count) { 'bad' } else { 'ok' }) $(if ($off.Count) { 'aus für: ' + (($off | ForEach-Object { $_.Name }) -join ', ') } else { 'für alle Netzwerke an' }) }
    $bl = $null; try { $bl = ([string](Get-BitLockerVolume -MountPoint $env:SystemDrive -ErrorAction Stop).ProtectionStatus -eq 'On') } catch { }
    & $add 'Verschlüsselung (BitLocker)' $(if ($bl -eq $true) { 'ok' } else { 'warn' }) $(if ($bl -eq $true) { 'Laufwerk C: ist verschlüsselt' } elseif ($bl -eq $false) { 'Laufwerk C: ist nicht verschlüsselt' } else { 'Status unbekannt' })
    $sbt = $null; try { $sbt = [bool](Confirm-SecureBootUEFI -ErrorAction Stop) } catch { }
    & $add 'Secure Boot' $(if ($sbt) { 'ok' } else { 'warn' }) $(if ($sbt) { 'an' } elseif ($sbt -eq $false) { 'aus' } else { 'nicht feststellbar (älteres BIOS oder Legacy-Start)' })
    $uac = Get-ItemProperty 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\System' -ErrorAction SilentlyContinue
    & $add 'Benutzerkontensteuerung' $(if ($uac -and $uac.EnableLUA -eq 1 -and $uac.ConsentPromptBehaviorAdmin -ne 0) { 'ok' } else { 'warn' }) $(if ($uac -and $uac.EnableLUA -eq 1 -and $uac.ConsentPromptBehaviorAdmin -ne 0) { 'aktiv' } else { 'aus - kein kritisches Problem, aber empfohlen: einschalten (Seite Sicherheit)' })
    $l.ToArray()
}
function Get-OkBackupItems($HealthArgs) {
    $l = [System.Collections.Generic.List[object]]::new()
    if (-not $HealthArgs.BackupTarget) { $l.Add([pscustomobject]@{ Name = 'Datensicherung'; State = 'warn'; Text = 'Empfehlung: einrichten - sonst sind Fotos und Dokumente bei einem Defekt verloren (NAS oder USB wählen)' }) }
    else {
        $age = $null; try { if ($HealthArgs.BackupLast) { $age = [int]((Get-Date) - [datetime]$HealthArgs.BackupLast).TotalDays } } catch { }
        $l.Add([pscustomobject]@{ Name = 'Datensicherung'; State = $(if ($null -eq $age) { 'warn' } elseif ($age -le 7) { 'ok' } elseif ($age -le 14) { 'warn' } else { 'bad' }); Text = $(if ($null -eq $age) { 'Ziel ' + $HealthArgs.BackupTarget + ' - noch keine erfolgreiche Sicherung gefunden' } else { 'letzte Sicherung vor {0} Tag(en) nach {1}' -f $age, $HealthArgs.BackupTarget }) })
    }
    $rp = $null; try { $rp = @(Get-ComputerRestorePoint -ErrorAction Stop | Sort-Object SequenceNumber -Descending)[0] } catch { }
    if ($rp) { $t = $null; try { $t = [Management.ManagementDateTimeConverter]::ToDateTime([string]$rp.CreationTime) } catch { }; $l.Add([pscustomobject]@{ Name = 'Wiederherstellungspunkt'; State = 'ok'; Text = ('{0:dd.MM.yyyy HH:mm}: {1}' -f $t, $rp.Description) }) }
    else { $l.Add([pscustomobject]@{ Name = 'Wiederherstellungspunkt'; State = 'warn'; Text = 'keiner vorhanden - Computerschutz für C: einschalten (Seite Optimieren)' }) }
    $ds = @(Get-DsSets (Get-DsRoot) | Sort-Object Created -Descending) | Select-Object -First 1
    $l.Add([pscustomobject]@{ Name = 'Treiber-Sicherung'; State = $(if ($ds) { 'ok' } else { 'warn' }); Text = $(if ($ds) { 'letzter Stand vom {0:dd.MM.yyyy HH:mm} ({1})' -f [datetime]$ds.Created, $ds.Reason } else { 'noch keine - entsteht automatisch vor dem ersten Treiber-Update' }) })
    $l.ToArray()
}
function Invoke-OkCheckHealth {
    # DISM /CheckHealth dauert Sekunden. Nur wenn der Komponentenspeicher als beschädigt markiert ist, folgen RestoreHealth und SFC (dauern lange).
    # SFC /verifyonly allein würde 5-15 Minuten kosten und findet selten mehr - deshalb nur bei Befund.
    $Script:Detail = 'DISM prüft den Komponentenspeicher (CheckHealth)'; Set-PStatus $Script:StatusText
    $rc = Invoke-External -Exe (Join-Path $env:SystemRoot 'System32\Dism.exe') -Arguments @('/Online', '/Cleanup-Image', '/CheckHealth', '/English') -TimeoutMin 10 -Capture -OemEncoding
    $txt = ($Script:Captured -join ' ')
    $state = if ($txt -match '(?i)not repairable') { 'kaputt' } elseif ($txt -match '(?i)is repairable|kann repariert werden') { 'reparierbar' } elseif ($txt -match '(?i)No component store corruption|keine Komponentenspeicherbesch') { 'ok' } elseif ($rc -eq 0) { 'ok' } else { 'unklar' }
    return [pscustomobject]@{ Code = $rc; State = $state }
}
function Invoke-OkJob {
    $C = $Script:Cfg
    $t0 = Get-Date
    $Script:OkPhases = [System.Collections.Generic.List[object]]::new()
    $autoRep = $false; try { $autoRep = [bool]$Script:JobOpts.AutoRepair } catch { }
    $plan = @{ ScoreBefore = $true; Restore = [bool]$C.Optimize.RestorePoint; Clean = $true; Windows = ((Get-OkOpt 'Updates') -and [bool]$C.Update.WindowsUpdate); Drivers = (Get-OkOpt 'Drivers'); Programs = (Get-OkOpt 'Programs'); Repair = (Get-OkOpt 'Repair'); AutoRepair = $autoRep; Security = $true; Backup = $true; ScoreAfter = $true; Report = $true }
    foreach ($d in (Get-OkPhaseDefs)) { $Script:OkPhases.Add([pscustomobject]@{ Key = $d[0]; Title = $d[1]; Weight = $d[2]; Glyph = $d[3]; State = $(if ($plan[$d[0]]) { 'wait' } else { 'skip' }); Info = $(if ($plan[$d[0]]) { '' } else { 'abgewählt' }); Started = ''; Seconds = 0 }) }
    Save-OkPhases
    Write-PLog ('Ein-Klick-Optimierung: {0}' -f (($Script:OkPhases | Where-Object { $_.State -eq 'wait' } | ForEach-Object { $_.Title }) -join ' > '))
    $freed0 = [int64]$Script:Freed; $upd0 = [int]$Script:UpdatesInstalled
    $fixedExtra = [System.Collections.Generic.List[string]]::new()
    $cancelled = $false
    $script:OkScB = $null; $script:OkHa0 = $null; $script:OkHb = @(); $script:OkSec = @(); $script:OkBak = @()
    # Jeder Schritt gibt als LETZTE Ausgabe Zustand und Text aus (@('ok', 'Text')) - Ausgaben der aufgerufenen Pflege-Funktionen davor werden ignoriert
    $run = {
        param($key, $block)
        if ($cancelled -or (Test-PCancel)) { return }
        Set-OkPhase $key 'run'
        try {
            $out = @(& $block)
            $st = 'ok'; $tx = ''
            if ($out.Count -ge 2 -and [string]$out[$out.Count - 2] -in 'ok', 'warn', 'skip', 'cancel') { $st = [string]$out[$out.Count - 2]; $tx = [string]$out[$out.Count - 1] }
            if (Test-PCancel) { $st = 'cancel'; $tx = ('abgebrochen. ' + $tx).Trim() }
            Set-OkPhase $key $st $tx
        } catch { Write-PLog ('Ein-Klick ({0}): {1}' -f $key, $_.Exception.Message) 'WARN'; Set-OkPhase $key 'warn' $_.Exception.Message }
    }

    # 1. Zustand vorher
    & $run 'ScoreBefore' {
        $script:OkScB = Get-ScHealthScore
        $script:OkHa0 = Get-HealthArgs
        $script:OkHb = @(Get-HealthItems $script:OkHa0 | ForEach-Object { $_ })
        Write-PLog ('Zustands-Score vorher: {0} ({1})' -f $script:OkScB.Score, $script:OkScB.Grade)
        try { Save-SystemSnapshot 'Vor: Ein-Klick-Optimierung' } catch { }
        @('ok', ('{0} von 100 ({1})' -f $script:OkScB.Score, $script:OkScB.Grade))
    }
    # 2. Wiederherstellungspunkt
    if ($plan.Restore) { & $run 'Restore' { $null = Invoke-DsRestorePoint; @('ok', 'gesetzt bzw. aktuell') } }
    # 3. Aufräumen (wie Teil "Clean", nach den Einstellungen der Seite Aufräumen)
    & $run 'Clean' {
        $cl = @(
            @('UserTemp', 'Temp-Dateien (Benutzer)', { Clear-UserTemp }), @('WinTemp', 'Temp-Dateien (Windows)', { Clear-WinTemp }), @('WUCache', 'Update-Downloadcache', { Clear-WUCache }),
            @('DeliveryOpt', 'Übermittlungsoptimierung', { Clear-DeliveryOpt }), @('RecycleBin', 'Papierkorb', { Clear-RecycleBins }), @('ThumbCache', 'Miniaturansichten-Cache', { Clear-ThumbCache }),
            @('WER', 'Fehlerberichte / Speicherabbilder', { Clear-ErrorReports }), @('OldLogs', 'Alte Protokolle', { Clear-OldLogs }), @('BrowserCache', 'Browser-Cache', { Clear-BrowserCaches }),
            @('OldDrivers', 'Veraltete Treiberpakete', { Remove-OldDriverPackages }), @('CleanMgr', 'Datenträgerbereinigung', { Invoke-CleanMgr }), @('ComponentCleanup', 'Komponentenspeicher (WinSxS)', { Invoke-ComponentCleanup }),
            @('OwnLogs', 'Protokolle von PC-Tools', { Clear-OwnLogs }))
        $f0 = [int64]$Script:Freed; $n = 0
        foreach ($x in $cl) {
            if (Test-PCancel) { break }
            if (-not $C.Clean.($x[0])) { continue }
            $n++; $Script:Detail = $x[1]; Set-PStatus $Script:StatusText
            Invoke-CleanStep -Name $x[1] -Action $x[2]
        }
        # PC-Reiniger (eigene Auswahl) wie im Teil "Clean" - sonst entfällt er, wenn der Zeitplan die Ein-Klick-Optimierung ausführt
        if ((-not (Test-PCancel)) -and $C.Cleaner -and $C.Cleaner.InSchedule) { $n++; $Script:Detail = 'PC-Reiniger (eigene Auswahl)'; Set-PStatus $Script:StatusText; Invoke-CleanStep -Name 'PC-Reiniger (eigene Auswahl)' -Action { Invoke-CcCleanJob -AsStep } }
        @('ok', ('{0} freigegeben ({1} Bereiche)' -f (Format-OkBytes ([double]([int64]$Script:Freed - $f0))), $n))
    }
    # 4. Windows-Updates (inkl. Treiber aus Windows Update, wenn eingestellt)
    if ($plan.Windows) {
        & $run 'Windows' {
            $u0 = [int]$Script:UpdatesInstalled; $w0 = [int]$Script:Warnings
            try { $null = Repair-EspSpace } catch { Write-PLog ('Systempartition: {0}' -f $_.Exception.Message) 'WARN' }
            $null = Invoke-WindowsUpdate
            $nu = [int]$Script:UpdatesInstalled - $u0
            @($(if ([int]$Script:Warnings -gt $w0) { 'warn' } else { 'ok' }), $(if ($nu) { '{0} Update(s) installiert' -f $nu } else { 'alles aktuell' }))
        }
    }
    # 5. Treiber und Firmware (Hersteller-Tool, Grafik, Intel WLAN/Bluetooth) - davor greift automatisch die Treiber-Sicherung
    if ($plan.Drivers) {
        & $run 'Drivers' {
            $u0 = [int]$Script:UpdatesInstalled; $w0 = [int]$Script:Warnings; $parts = @()
            if ($C.Update.OEM) { $parts += 'Hersteller'; try { $null = Invoke-OemUpdates } catch { Write-PLog ('Hersteller-Treiber: {0}' -f $_.Exception.Message) 'WARN' } }
            if ((-not (Test-PCancel)) -and $C.Update.GpuDriver) { $parts += 'Grafik'; try { $null = Invoke-GpuDriverUpdate } catch { Write-PLog ('Grafiktreiber: {0}' -f $_.Exception.Message) 'WARN' } }
            if ((-not (Test-PCancel)) -and $C.Update.IntelDirect -ne $false) { $parts += 'Intel WLAN/Bluetooth'; try { $null = Invoke-IntelWirelessUpdate } catch { Write-PLog ('Intel WLAN/Bluetooth: {0}' -f $_.Exception.Message) 'WARN' } }
            $nu = [int]$Script:UpdatesInstalled - $u0
            if (-not $parts.Count) { return @('skip', 'in den Update-Einstellungen ausgeschaltet') }
            @($(if ([int]$Script:Warnings -gt $w0) { 'warn' } else { 'ok' }), ('{0}: {1}' -f ($parts -join ', '), $(if ($nu) { '{0} Treiber/Firmware installiert' -f $nu } else { 'aktuell' })))
        }
    }
    # 6. Programme und Virenschutz
    if ($plan.Programs) {
        & $run 'Programs' {
            $w0 = [int]$Script:Warnings; $parts = @()
            if ($C.Update.Ninite -and (Find-Ninite)) { $parts += 'Ninite'; try { $null = Invoke-NiniteUpdate } catch { Write-PLog ('Ninite: {0}' -f $_.Exception.Message) 'WARN' } }
            if ((-not (Test-PCancel)) -and $C.Update.Winget) { $parts += 'winget'; try { $null = Invoke-Winget } catch { Write-PLog ('winget: {0}' -f $_.Exception.Message) 'WARN' } }
            if ((-not (Test-PCancel)) -and $C.Update.Choco) { $parts += 'Chocolatey'; try { $null = Invoke-ChocoUpdate } catch { Write-PLog ('Chocolatey: {0}' -f $_.Exception.Message) 'WARN' } }
            if ((-not (Test-PCancel)) -and $C.Update.StoreApps) { $parts += 'Store'; try { $null = Invoke-StoreUpdate } catch { } }
            if ((-not (Test-PCancel)) -and $C.Update.Defender) { $parts += 'Virendefinitionen'; try { $null = Invoke-DefenderUpdate } catch { } }
            if (-not $parts.Count) { return @('skip', 'in den Update-Einstellungen ausgeschaltet') }
            @($(if ([int]$Script:Warnings -gt $w0) { 'warn' } else { 'ok' }), ($parts -join ', ') + ' aktualisiert')
        }
    }
    # 7. Optimieren und schnelle Systemprüfung
    if ($plan.Repair) {
        & $run 'Repair' {
            $info = @(); $st = 'ok'
            if ($C.Optimize.DnsFlush) { try { $null = Clear-Dns; $info += 'DNS-Cache geleert' } catch { } }
            if ($C.Optimize.Volumes -and -not (Test-PCancel)) { try { $null = Optimize-Drives; $info += 'Laufwerke optimiert' } catch { Write-PLog ('Laufwerke: {0}' -f $_.Exception.Message) 'WARN' } }
            if (-not (Test-PCancel)) {
                $ch = Invoke-OkCheckHealth
                switch ($ch.State) {
                    'ok' { Write-PLog 'DISM CheckHealth: Komponentenspeicher in Ordnung.' 'OK'; $info += 'Systemdateien in Ordnung' }
                    'reparierbar' {
                        Write-PLog 'DISM CheckHealth: Komponentenspeicher beschädigt - wird repariert (RestoreHealth + SFC).' 'WARN'
                        $null = Invoke-HealthCheck
                        $ch2 = Invoke-OkCheckHealth
                        if ($ch2.State -eq 'ok') { $fixedExtra.Add('Beschädigte Windows-Systemdateien repariert (DISM/SFC)'); $info += 'Systemdateien repariert' } else { $st = 'warn'; $info += 'Systemdateien: Reparatur unvollständig - Seite Windows-Reparatur' }
                    }
                    'kaputt' { $st = 'warn'; Write-PLog 'DISM CheckHealth: Komponentenspeicher nicht reparierbar - Seite Windows-Reparatur (Reparaturinstallation) nutzen.' 'WARN'; $info += 'Systemdateien nicht reparierbar' }
                    default { $info += ('DISM-Prüfung ohne klares Ergebnis (Code {0})' -f $ch.Code) }
                }
            }
            @($st, ($info -join ', '))
        }
    }
    # 7b. Fehler automatisch beheben (nur erkannte Probleme, nur sichere Reparaturen)
    if ($plan.AutoRepair) {
        & $run 'AutoRepair' {
            $found = @(Get-AutoRepairKeys)
            if (-not $found.Count) { return @('ok', 'keine Probleme gefunden - alles läuft') }
            $reasons = (@($found | ForEach-Object { $_.Reason } | Select-Object -Unique) -join ', ')
            Write-PLog ('Automatische Reparatur: {0} Punkt(e) erkannt ({1})' -f $found.Count, $reasons) 'WARN'
            $done = [System.Collections.Generic.List[string]]::new(); $w0 = [int]$Script:Warnings
            foreach ($f in $found) {
                if (Test-PCancel) { break }
                $def = @($RepairDefs | Where-Object { $_.Key -eq $f.Key })[0]
                $title = if ($def) { $def.Title } else { $f.Key }
                $Script:Detail = $title; Set-PStatus $Script:StatusText
                Write-PLog ('--- Auto-Reparatur: {0} ({1}) ---' -f $title, $f.Reason)
                try { Invoke-RepairAction $f.Key; $done.Add($title); $fixedExtra.Add(('Automatisch repariert: {0}' -f $title)) }
                catch { Write-PLog ('Auto-Reparatur {0}: {1}' -f $f.Key, $_.Exception.Message) 'WARN' }
            }
            if (-not $done.Count) { return @('warn', 'erkannte Probleme konnten nicht behoben werden') }
            @($(if ([int]$Script:Warnings -gt $w0) { 'warn' } else { 'ok' }), ('{0} Problem(e) behoben: {1}' -f $done.Count, ($done -join ', ')))
        }
    }
    # 8. Sicherheit
    & $run 'Security' {
        $script:OkSec = @(Get-OkSecurityItems)
        $bad = @($script:OkSec | Where-Object { $_.State -ne 'ok' })
        foreach ($s in $script:OkSec) { Write-PLog ('Sicherheit - {0}: {1}' -f $s.Name, $s.Text) $(if ($s.State -eq 'ok') { 'OK' } else { 'INFO' }) }
        @($(if (@($bad | Where-Object { $_.State -eq 'bad' }).Count) { 'warn' } else { 'ok' }), $(if ($bad.Count) { '{0} von {1} Prüfungen mit Hinweis' -f $bad.Count, $script:OkSec.Count } else { 'alle {0} Prüfungen in Ordnung' -f $script:OkSec.Count }))
    }
    # 9. Datensicherung
    & $run 'Backup' {
        $script:OkBak = @(Get-OkBackupItems (Get-HealthArgs))
        foreach ($s in $script:OkBak) { Write-PLog ('Sicherung - {0}: {1}' -f $s.Name, $s.Text) $(if ($s.State -eq 'ok') { 'OK' } else { 'INFO' }) }
        $b0 = $script:OkBak[0]
        @($(if ($b0.State -eq 'ok') { 'ok' } else { 'warn' }), $b0.Text)
    }
    # Treiber-Änderungen dieses Laufs festhalten (sonst erledigt das Invoke-PflegeRun am Ende)
    $chg = @(); $dsSet = [string]$Script:DsJobSet
    if ($Script:DsJobSet) { try { $null = Complete-DsAfterUpdate } catch { }; $chg = @($Script:DsLastChanges) }
    if (Test-PCancel) { $cancelled = $true }
    # 10. Zustand nachher - auch nach Abbruch, damit der Bericht stimmt
    Set-OkPhase 'ScoreAfter' 'run'
    $scA = $null; $haItems = @()
    try {
        $scA = Get-ScHealthScore
        $haItems = @(Get-HealthItems (Get-HealthArgs) | ForEach-Object { $_ })
        try { $null = Add-ScScoreHistory -Result $scA -NoNotify } catch { }
        Write-PLog ('Zustands-Score nachher: {0} ({1}), vorher {2}' -f $scA.Score, $scA.Grade, $script:OkScB.Score) 'OK'
        Set-OkPhase 'ScoreAfter' 'ok' ('{0} von 100 ({1})' -f $scA.Score, $scA.Grade)
    } catch { Set-OkPhase 'ScoreAfter' 'warn' $_.Exception.Message }
    if (-not $script:OkScB) { $script:OkScB = $scA }
    foreach ($p in $Script:OkPhases) { if ($p.State -in 'wait', 'run') { $p.State = $(if ($cancelled) { 'cancel' } else { 'skip' }) } }
    # 11. Bericht
    Set-OkPhase 'Report' 'run'
    $t1 = Get-Date
    $pend = $false; try { $pend = [bool](Test-PendingReboot) } catch { }
    $cs = $null; try { $cs = Get-CimInstance Win32_ComputerSystem -ErrorAction Stop } catch { }
    $fixed = @(@(Get-OkFixed @($script:OkHb) @($haItems)) + @($fixedExtra) | Where-Object { $_ })
    $res = [pscustomobject]@{
        Format = 1; Computer = $env:COMPUTERNAME; Model = $(if ($cs) { '{0} {1}' -f $cs.Manufacturer, $cs.Model } else { '' })
        Start = $t0.ToString('s'); End = $t1.ToString('s'); StartText = $t0.ToString('dd.MM.yyyy HH:mm'); EndText = $t1.ToString('HH:mm'); Duration = ('{0:hh\:mm\:ss}' -f ($t1 - $t0))
        Mode = $(if ($Script:IsAuto) { 'automatisch (Zeitplan)' } else { 'von Hand gestartet' }); Auto = [bool]$Script:IsAuto; Cancelled = $cancelled
        ScoreBefore = $script:OkScB; ScoreAfter = $scA
        Freed = [int64]$Script:Freed - $freed0; FreedText = (Format-OkBytes ([double]([int64]$Script:Freed - $freed0))); Updates = [int]$Script:UpdatesInstalled - $upd0
        RebootNeeded = [bool]($pend -or $Script:RebootNeeded); Warnings = [int]$Script:Warnings
        Phases = @($Script:OkPhases | Select-Object Key, Title, State, Info, Seconds, Glyph)
        Fixed = @($fixed); Remaining = @(Get-OkRecommendations @($haItems) $scA)
        Security = @($script:OkSec); Backup = @($script:OkBak); DriverChanges = @($chg); DriverSet = $(if ($dsSet -and $dsSet -ne '-') { $dsSet } else { '' })
        Log = [string]$Script:LogFile; Html = ''; Pdf = ''
    }
    $dir = Get-OkDir; $stamp = $t0.ToString('yyyyMMdd_HHmmss')
    try {
        $html = New-OkReportHtml $res
        $hf = Join-Path $dir ('Bericht_{0}.html' -f $stamp)
        [IO.File]::WriteAllText($hf, $html, (New-Object Text.UTF8Encoding $true))
        $res.Html = $hf
        if (-not $Script:IsAuto) {
            # PDF nur bei Start aus der Oberfläche (Edge im Hintergrund) - beim Zeitplan als SYSTEM gibt es oft kein Edge-Profil; dort entsteht das PDF beim Öffnen
            $Script:Detail = 'PDF-Bericht wird erstellt'; Set-PStatus $Script:StatusText
            $pdf = Convert-HtmlToPdf $html (Join-Path $dir ('Bericht_{0}.pdf' -f $stamp))
            if ($pdf -like '*.pdf') { $res.Pdf = $pdf }
        }
    } catch { Write-PLog ('Bericht: {0}' -f $_.Exception.Message) 'WARN' }
    try {
        $json = $res | ConvertTo-Json -Depth 6
        Set-Content -LiteralPath (Join-Path $dir ('Bericht_{0}.json' -f $stamp)) -Value $json -Encoding UTF8
        Set-Content -LiteralPath (Join-Path $dir 'letzter.json') -Value $json -Encoding UTF8
        Get-ChildItem -LiteralPath $dir -File -Filter 'Bericht_*' -ErrorAction SilentlyContinue | Sort-Object Name -Descending | Select-Object -Skip 60 | Remove-Item -Force -ErrorAction SilentlyContinue
    } catch { Write-PLog ('Bericht speichern: {0}' -f $_.Exception.Message) 'WARN' }
    Set-OkPhase 'Report' 'ok' $(if ($res.Pdf) { 'PDF erstellt' } else { 'gespeichert' })
    Write-PLog ('Ein-Klick-Optimierung fertig: Score {0} -> {1}, {2} frei, {3} Update(s), {4} Problem(e) behoben, {5} Empfehlung(en) offen{6}' -f $res.ScoreBefore.Score, $res.ScoreAfter.Score, $res.FreedText, $res.Updates, @($res.Fixed).Count, @($res.Remaining).Count, $(if ($res.RebootNeeded) { ', Neustart nötig' } else { '' })) 'OK'
    if ($Script:IsAuto) {
        try { $null = Send-PflegeNotify 'Ein-Klick-Optimierung fertig' ('Zustands-Score {0} -> {1}, {2} frei, {3} Update(s){4}. Offen: {5}' -f $res.ScoreBefore.Score, $res.ScoreAfter.Score, $res.FreedText, $res.Updates, $(if ($res.RebootNeeded) { ', Neustart nötig' } else { '' }), $(if (@($res.Remaining).Count) { (@($res.Remaining | Select-Object -First 3 | ForEach-Object { $_.Text }) -join '; ') } else { 'nichts' })) $(if (@($res.Remaining | Where-Object { $_.Level -eq 'Red' }).Count) { 'Yellow' } else { 'Info' }) } catch { }
    }
}
