function Format-EnDur([double]$Minutes) {
    if ([double]::IsNaN($Minutes) -or $Minutes -lt 0) { return '-' }
    $m = [int][math]::Round($Minutes)
    if ($m -lt 60) { return ('{0} Min.' -f $m) }
    $h = [math]::Floor($m / 60); $r = $m - $h * 60
    if ($h -ge 48) { return ('{0:N1} Tage' -f ($m / 1440)) }
    if ($r -eq 0) { return ('{0} Std.' -f $h) }
    return ('{0} Std. {1} Min.' -f $h, $r)
}
# ISO-8601-Dauer (PT5H12M, P1DT2H) oder Millisekunden/Sekunden-Zahl -> Minuten (NaN wenn unbekannt)
function ConvertTo-EnMinutes([string]$Text, [string]$NumUnit = 'ms') {
    $t = ([string]$Text).Trim()
    if (-not $t) { return [double]::NaN }
    if ($t -match '^-?P') { try { return [System.Xml.XmlConvert]::ToTimeSpan($t).TotalMinutes } catch { return [double]::NaN } }
    if ($t -match '^\d+:\d\d(:\d\d)?$') { try { return [TimeSpan]::Parse($t).TotalMinutes } catch { return [double]::NaN } }
    $n = 0.0
    if ([double]::TryParse($t, [Globalization.NumberStyles]::Float, [Globalization.CultureInfo]::InvariantCulture, [ref]$n)) {
        switch ($NumUnit) { 's' { return $n / 60 } 'min' { return $n } default { return $n / 60000 } }
    }
    return [double]::NaN
}
function ConvertTo-EnDate([string]$Text) {
    $t = ([string]$Text).Trim()
    if (-not $t) { return $null }
    $inv = [Globalization.CultureInfo]::InvariantCulture
    $fmts = @('yyyy-MM-ddTHH:mm:ss', 'yyyy-MM-ddTHH:mm:ss.fff', 'yyyy-MM-ddTHH:mm:ssZ', 'yyyy-MM-ddTHH:mm:ss.fffZ', 'yyyy-MM-dd HH:mm:ss', 'yyyy-MM-dd HH:mm', 'yyyy-MM-dd', 'dd.MM.yyyy HH:mm:ss', 'dd.MM.yyyy HH:mm', 'dd.MM.yyyy', 'M/d/yyyy h:mm:ss tt', 'M/d/yyyy H:mm:ss', 'M/d/yyyy h:mm tt', 'M/d/yyyy')
    $d = [datetime]::MinValue
    $t2 = $t -replace '(:\d\d\.\d{3})\d+', '$1'
    if ([datetime]::TryParseExact($t2, [string[]]$fmts, $inv, [Globalization.DateTimeStyles]::AssumeLocal, [ref]$d)) { return $d }
    if ([datetime]::TryParse($t, [Globalization.CultureInfo]::CurrentCulture, [Globalization.DateTimeStyles]::None, [ref]$d)) { return $d }
    if ([datetime]::TryParse($t, $inv, [Globalization.DateTimeStyles]::None, [ref]$d)) { return $d }
    return $null
}
function ConvertTo-EnNum([string]$Text) {
    $t = ([string]$Text).Trim() -replace '[^\d\.,\-eE]', ''
    if (-not $t) { return [double]::NaN }
    if ($t -match '^-?\d{1,3}(\.\d{3})+(,\d+)?$') { $t = ($t -replace '\.', '') -replace ',', '.' }
    elseif ($t -match '^-?\d+,\d+$') { $t = $t -replace ',', '.' }
    elseif ($t -match '^-?\d{1,3}(,\d{3})+(\.\d+)?$') { $t = $t -replace ',', '' }
    $n = 0.0
    if ([double]::TryParse($t, [Globalization.NumberStyles]::Float, [Globalization.CultureInfo]::InvariantCulture, [ref]$n)) { return $n }
    return [double]::NaN
}
# Wert als Attribut ODER als Kindelement (Namespaces egal)
function Get-EnXVal($Node, [string]$Name) {
    if (-not $Node) { return '' }
    try { if ($Node.Attributes) { foreach ($a in $Node.Attributes) { if ($a.LocalName -ieq $Name) { return [string]$a.Value } } } } catch { }
    try { foreach ($c in $Node.ChildNodes) { if ($c.NodeType -eq 'Element' -and $c.LocalName -ieq $Name) { return [string]$c.InnerText } } } catch { }
    return ''
}
function Get-EnXFirst($Node, [string]$Pattern) {
    if (-not $Node) { return '' }
    try { if ($Node.Attributes) { foreach ($a in $Node.Attributes) { if ($a.LocalName -match $Pattern) { return [string]$a.Value } } } } catch { }
    try {
        foreach ($c in $Node.ChildNodes) {
            if ($c.NodeType -ne 'Element' -or $c.LocalName -notmatch $Pattern) { continue }
            if (@($c.ChildNodes | Where-Object { $_.NodeType -eq 'Element' }).Count -eq 0) { return [string]$c.InnerText }
        }
    } catch { }
    return ''
}
function Get-EnChemName([string]$Code) {
    $c = ([string]$Code).Trim()
    switch -Regex ($c) {
        '^(?i)(LION|Li-?ion|LIon|6)$' { return 'Lithium-Ionen (Li-Ion)' }
        '^(?i)(LIP|LiP|LiPo|Li-?Poly.*|8)$' { return 'Lithium-Polymer (Li-Po)' }
        '^(?i)(PBAC|Pb|Lead.*|3)$' { return 'Blei-Säure (typisch für USV)' }
        '^(?i)(NIMH|NiMH|5)$' { return 'Nickel-Metallhydrid (NiMH)' }
        '^(?i)(NICD|NiCd|4)$' { return 'Nickel-Cadmium (NiCd)' }
        '^(?i)(LIFE|LFP|LiFePO4)$' { return 'Lithium-Eisenphosphat (LiFePO4)' }
        '^$' { return 'unbekannt' }
        default { return $c }
    }
}

# ---------------------------------------------------------------- powercfg /batteryreport /xml
function ConvertFrom-EnBatteryReportXml([string]$XmlText) {
    $x = New-Object System.Xml.XmlDocument
    $x.XmlResolver = $null
    $x.LoadXml(($XmlText -replace '^﻿', ''))
    $root = $x.DocumentElement
    $sys = @($root.ChildNodes | Where-Object { $_.LocalName -eq 'SystemInformation' })[0]
    $bats = [System.Collections.Generic.List[object]]::new()
    foreach ($b in @($root.SelectNodes("//*[local-name()='Batteries']/*[local-name()='Battery']"))) {
        $des = ConvertTo-EnNum (Get-EnXVal $b 'DesignCapacity'); $full = ConvertTo-EnNum (Get-EnXVal $b 'FullChargeCapacity'); $cyc = ConvertTo-EnNum (Get-EnXVal $b 'CycleCount')
        $bats.Add([pscustomobject]@{ Id = (Get-EnXVal $b 'Id').Trim(); Manufacturer = (Get-EnXVal $b 'Manufacturer').Trim(); Serial = (Get-EnXVal $b 'SerialNumber').Trim(); Chemistry = (Get-EnXVal $b 'Chemistry').Trim()
            ManufactureDate = (Get-EnXVal $b 'ManufactureDate').Trim(); Design = $des; Full = $full; Cycles = $cyc
            Health = $(if ($des -gt 0 -and $full -gt 0) { [math]::Round($full * 100 / $des, 1) } else { [double]::NaN }) })
    }
    $hist = [System.Collections.Generic.List[object]]::new()
    foreach ($h in @($root.SelectNodes("//*[local-name()='History']/*[local-name()='HistoryEntry']"))) {
        $ds = Get-EnXVal $h 'LocalStartDate'; if (-not $ds) { $ds = Get-EnXVal $h 'StartDate' }
        $de = Get-EnXVal $h 'LocalEndDate'; if (-not $de) { $de = Get-EnXVal $h 'EndDate' }
        $d0 = ConvertTo-EnDate $ds; $d1 = ConvertTo-EnDate $de
        $full = ConvertTo-EnNum (Get-EnXVal $h 'FullChargeCapacity'); $des = ConvertTo-EnNum (Get-EnXVal $h 'DesignCapacity')
        if (-not $d0 -or -not ($full -gt 0) -or -not ($des -gt 0)) { continue }
        $hist.Add([pscustomobject]@{ Start = $d0; End = $(if ($d1) { $d1 } else { $d0 }); Full = $full; Design = $des; Pct = [math]::Round($full * 100 / $des, 1)
            Cycles = (ConvertTo-EnNum (Get-EnXVal $h 'CycleCount'))
            ActiveDcMin = (ConvertTo-EnMinutes (Get-EnXVal $h 'ActiveDcTime')); ActiveAcMin = (ConvertTo-EnMinutes (Get-EnXVal $h 'ActiveAcTime')); ActiveDcEnergy = (ConvertTo-EnNum (Get-EnXVal $h 'ActiveDcEnergy')) })
    }
    $rt = @($root.SelectNodes("//*[local-name()='RuntimeEstimates']"))[0]
    $rtFull = [double]::NaN; $rtDes = [double]::NaN; $rtFullCs = [double]::NaN
    if ($rt) {
        foreach ($c in @($rt.ChildNodes)) {
            if ($c.NodeType -ne 'Element') { continue }
            $act = ConvertTo-EnMinutes (Get-EnXVal $c 'ActiveRuntime'); $cs = ConvertTo-EnMinutes (Get-EnXVal $c 'ConnectedStandbyRuntime')
            if ($c.LocalName -match '(?i)FullCharge') { $rtFull = $act; $rtFullCs = $cs } elseif ($c.LocalName -match '(?i)Design') { $rtDes = $act }
        }
    }
    $usage = [System.Collections.Generic.List[object]]::new()
    foreach ($u in @($root.SelectNodes("//*[local-name()='RecentUsage']/*[local-name()='UsageEntry']"))) {
        $ts = Get-EnXVal $u 'LocalTimestamp'; if (-not $ts) { $ts = Get-EnXVal $u 'Timestamp' }
        $d = ConvertTo-EnDate $ts; if (-not $d) { continue }
        $usage.Add([pscustomobject]@{ Time = $d; Ac = ((Get-EnXVal $u 'Ac') -eq '1'); Type = (Get-EnXVal $u 'EntryType'); Charge = (ConvertTo-EnNum (Get-EnXVal $u 'ChargeCapacity')); Full = (ConvertTo-EnNum (Get-EnXVal $u 'FullChargeCapacity')) })
    }
    $scan = ConvertTo-EnDate (Get-EnXVal (@($root.ChildNodes | Where-Object { $_.LocalName -eq 'ReportInformation' })[0]) 'LocalScanTime')
    [pscustomobject]@{
        Batteries = $bats.ToArray(); History = @($hist | Sort-Object Start); Usage = @($usage | Sort-Object Time)
        RuntimeFullMin = $rtFull; RuntimeDesignMin = $rtDes; RuntimeFullStandbyMin = $rtFullCs
        Manufacturer = (Get-EnXVal $sys 'SystemManufacturer').Trim(); Product = (Get-EnXVal $sys 'SystemProductName').Trim()
        ConnectedStandby = ((Get-EnXVal $sys 'ConnectedStandby').Trim() -eq '1'); ScanTime = $scan
    }
}
# Verschleiß-Trend aus Messpunkten (Datum, Prozent): Prozentpunkte pro Monat (negativ = Abnahme) und Prognose
function Get-EnWearTrend([object[]]$Points) {
    $p = @($Points | Where-Object { $_ -and $_.Date -and -not [double]::IsNaN([double]$_.Pct) -and [double]$_.Pct -gt 0 } | Sort-Object Date)
    if ($p.Count -lt 3) { return [pscustomobject]@{ Ok = $false; PerMonth = [double]::NaN; Text = 'Noch zu wenige Messpunkte für einen Trend.'; MonthsTo70 = [double]::NaN; MonthsTo60 = [double]::NaN } }
    $span = ($p[$p.Count - 1].Date - $p[0].Date).TotalDays
    if ($span -lt 14) { return [pscustomobject]@{ Ok = $false; PerMonth = [double]::NaN; Text = 'Messpunkte umfassen erst {0:N0} Tage - der Trend wird nach zwei Wochen berechnet.' -f $span; MonthsTo70 = [double]::NaN; MonthsTo60 = [double]::NaN } }
    $xs = @($p | ForEach-Object { $_.Date.ToOADate() }); $ys = @($p | ForEach-Object { [double]$_.Pct })
    $mx = ($xs | Measure-Object -Average).Average; $my = ($ys | Measure-Object -Average).Average
    $num = 0.0; $den = 0.0
    for ($i = 0; $i -lt $xs.Count; $i++) { $num += ($xs[$i] - $mx) * ($ys[$i] - $my); $den += ($xs[$i] - $mx) * ($xs[$i] - $mx) }
    if ($den -le 0) { return [pscustomobject]@{ Ok = $false; PerMonth = [double]::NaN; Text = 'Kein Trend berechenbar.'; MonthsTo70 = [double]::NaN; MonthsTo60 = [double]::NaN } }
    $slope = $num / $den * 30.4375
    # aktueller Wert = Regressionswert am letzten Tag (glättet Ausreißer)
    $cur = $my + ($num / $den) * ($xs[$xs.Count - 1] - $mx)
    $m70 = [double]::NaN; $m60 = [double]::NaN
    if ($slope -lt -0.02) { if ($cur -gt 70) { $m70 = ($cur - 70) / -$slope }; if ($cur -gt 60) { $m60 = ($cur - 60) / -$slope } }
    $txt = if ($slope -lt -0.02) {
        '{0:N1} Prozentpunkte pro Monat{1}' -f (-$slope), $(if (-not [double]::IsNaN($m70)) { ' - 70 % voraussichtlich in {0}' -f (Format-EnMonths $m70) } elseif (-not [double]::IsNaN($m60)) { ' - 60 % voraussichtlich in {0}' -f (Format-EnMonths $m60) } else { '' })
    } elseif ($slope -gt 0.3) { 'Kapazität steigt (meist nach Kalibrierung oder Firmware-Update) - kein Verschleiß erkennbar' } else { 'Stabil - kaum messbarer Verschleiß' }
    [pscustomobject]@{ Ok = $true; PerMonth = $slope; Text = $txt; MonthsTo70 = $m70; MonthsTo60 = $m60 }
}
function Format-EnMonths([double]$M) {
    if ($M -lt 1.5) { return 'ca. 1 Monat' }
    if ($M -lt 24) { return ('ca. {0:N0} Monaten' -f $M) }
    return ('ca. {0:N1} Jahren' -f ($M / 12))
}

# ---------------------------------------------------------------- powercfg /srumutil /csv (Energieverbrauch je App)
function Get-EnAppName([string]$AppId) {
    $a = ([string]$AppId).Trim().Trim('"')
    if (-not $a) { return '(unbekannt)' }
    if ($a -match '^!!([^!]+)!') { $a = $Matches[1] }
    if ($a -match '^\{?[0-9a-fA-F\-]{36}\}?$') { return 'Windows-Komponente ' + $a.Substring(0, 8) }
    if ($a -match '^S-1-5-') { return 'Systemkonto' }
    $svc = ''; if ($a -match '\[([^\]]+)\]\s*$') { $svc = $Matches[1]; $a = ($a -replace '\s*\[[^\]]+\]\s*$', '') }
    $n = $a
    if ($a -match '[\\/]') { $n = ($a -split '[\\/]')[-1] }
    elseif ($a -match '^([A-Za-z0-9\.\-]+)_[a-z0-9]{13}(!.*)?$') { $n = $Matches[1] }
    elseif ($a -match '^([A-Za-z0-9\.\-]+)_[\d\.]+_[a-z0-9]+__[a-z0-9]{13}') { $n = $Matches[1] }
    $map = @{ 'chrome.exe' = 'Google Chrome'; 'msedge.exe' = 'Microsoft Edge'; 'firefox.exe' = 'Mozilla Firefox'; 'ms-teams.exe' = 'Microsoft Teams'; 'teams.exe' = 'Microsoft Teams'
              'outlook.exe' = 'Outlook'; 'olk.exe' = 'Outlook (neu)'; 'winword.exe' = 'Word'; 'excel.exe' = 'Excel'; 'powerpnt.exe' = 'PowerPoint'; 'onedrive.exe' = 'OneDrive'; 'explorer.exe' = 'Explorer (Desktop, Taskleiste)'
              'dwm.exe' = 'Desktopfenster-Manager (Grafik)'; 'svchost.exe' = 'Windows-Dienste (svchost)'; 'system' = 'Windows-Kern (System)'; 'msmpeng.exe' = 'Microsoft Defender'; 'searchindexer.exe' = 'Windows-Suche (Indizierung)'
              'zoom.exe' = 'Zoom'; 'spotify.exe' = 'Spotify'; 'discord.exe' = 'Discord'; 'slack.exe' = 'Slack'; 'code.exe' = 'Visual Studio Code'; 'steam.exe' = 'Steam'; 'vlc.exe' = 'VLC'; 'powershell.exe' = 'PowerShell'; 'pwsh.exe' = 'PowerShell 7'
              'tiworker.exe' = 'Windows Update (Installation)'; 'mousocoreworker.exe' = 'Windows Update'; 'audiodg.exe' = 'Windows-Audio'; 'csrss.exe' = 'Windows-Sitzung (csrss)'; 'lsass.exe' = 'Windows-Anmeldung (lsass)' }
    $k = $n.ToLower()
    $nice = if ($map.ContainsKey($k)) { $map[$k] } else { $n }
    if ($svc) { $nice = '{0} [{1}]' -f $nice, $svc }
    return $nice
}
function ConvertFrom-EnSrumCsv([string]$CsvText, [int]$Days = 7, [datetime]$Now = (Get-Date)) {
    $lines = @(($CsvText -replace '^﻿', '') -split "`r?`n" | Where-Object { $_.Trim() })
    if ($lines.Count -lt 2) { return [pscustomobject]@{ Apps = @(); Total = 0.0; Rows = 0; From = $null; To = $null; Columns = @(); Note = 'Die SRUM-Datei enthält keine Daten.' } }
    $delim = ','
    if (($lines[0].Split(';').Count) -gt ($lines[0].Split(',').Count)) { $delim = ';' }
    $hdr = @($lines[0].Split($delim) | ForEach-Object { $_.Trim().Trim('"').Trim() })
    $rows = @($lines[1..($lines.Count - 1)] | ConvertFrom-Csv -Delimiter $delim -Header $hdr)
    $appCol = @($hdr | Where-Object { $_ -match '^(?i)(AppId|App ?Name|Application|AppName|App)$' })[0]
    if (-not $appCol) { $appCol = @($hdr | Where-Object { $_ -match '(?i)app' })[0] }
    if (-not $appCol) { $appCol = $hdr[0] }
    $timeCol = @($hdr | Where-Object { $_ -match '^(?i)(TimeStamp|Time ?Stamp|Timestamp|Time|Zeitstempel)$' })[0]
    if (-not $timeCol) { $timeCol = @($hdr | Where-Object { $_ -match '(?i)time|zeit' })[0] }
    $energy = @($hdr | Where-Object { $_ -match '(?i)Energy' -and $_ -notmatch '(?i)OnBehalf|Attributed|Loss|Delta' })
    $totalCol = @($energy | Where-Object { $_ -match '^(?i)TotalEnergy' })[0]
    $parts = [ordered]@{ Cpu = @($energy | Where-Object { $_ -match '(?i)^(CPU|Soc)' }); Display = @($energy | Where-Object { $_ -match '(?i)^Display' }); Disk = @($energy | Where-Object { $_ -match '(?i)^Disk' })
                         Net = @($energy | Where-Object { $_ -match '(?i)^(Network|MBB|Wlan|Wifi)' }); Other = @($energy | Where-Object { $_ -match '(?i)^(Other|Emi|Gpu|Audio)' }) }
    $from = $null; if ($Days -gt 0) { $from = $Now.AddDays(-$Days) }
    $acc = @{}; $minD = $null; $maxD = $null; $used = 0
    foreach ($r in $rows) {
        if ($timeCol -and $from) {
            $d = ConvertTo-EnDate ([string]$r.$timeCol)
            if ($d) { if ($d -lt $from -or $d -gt $Now.AddDays(1)) { continue }; if (-not $minD -or $d -lt $minD) { $minD = $d }; if (-not $maxD -or $d -gt $maxD) { $maxD = $d } }
        }
        $id = [string]$r.$appCol; if (-not $id.Trim()) { continue }
        $name = Get-EnAppName $id
        if (-not $acc.ContainsKey($name)) { $acc[$name] = [ordered]@{ Total = 0.0; Cpu = 0.0; Display = 0.0; Disk = 0.0; Net = 0.0; Other = 0.0; Id = $id } }
        $e = $acc[$name]; $sumParts = 0.0
        foreach ($k in @($parts.Keys)) { foreach ($c in $parts[$k]) { $v = ConvertTo-EnNum ([string]$r.$c); if (-not [double]::IsNaN($v) -and $v -gt 0) { $e[$k] += $v; $sumParts += $v } } }
        $t = if ($totalCol) { ConvertTo-EnNum ([string]$r.$totalCol) } else { [double]::NaN }
        if ([double]::IsNaN($t) -or $t -le 0) { $t = $sumParts }
        $e.Total += $t; $used++
    }
    $total = 0.0; foreach ($v in $acc.Values) { $total += $v.Total }
    $apps = foreach ($k in $acc.Keys) {
        $v = $acc[$k]; if ($v.Total -le 0) { continue }
        $sp = $v.Cpu + $v.Display + $v.Disk + $v.Net + $v.Other
        $f = { param($x) if ($sp -gt 0) { [math]::Round($x * 100 / $sp) } else { 0 } }
        [pscustomobject]@{ Name = $k; Id = $v.Id; Energy = $v.Total; Share = $(if ($total -gt 0) { [math]::Round($v.Total * 100 / $total, 1) } else { 0 })
            CpuPct = (& $f $v.Cpu); DisplayPct = (& $f $v.Display); DiskPct = (& $f $v.Disk); NetPct = (& $f $v.Net); OtherPct = (& $f $v.Other)
            ShareText = ''; Mix = '' }
    }
    $apps = @($apps | Sort-Object Energy -Descending)
    foreach ($a in $apps) {
        $a.ShareText = '{0:N1} %' -f $a.Share
        $mx = @(); foreach ($q in @(@('Prozessor', $a.CpuPct), @('Bildschirm', $a.DisplayPct), @('Netzwerk', $a.NetPct), @('Datenträger', $a.DiskPct), @('Sonstiges', $a.OtherPct))) { if ($q[1] -ge 5) { $mx += ('{0} {1} %' -f $q[0], $q[1]) } }
        $a.Mix = $mx -join ' · '
    }
    [pscustomobject]@{ Apps = $apps; Total = $total; Rows = $used; From = $minD; To = $maxD; Columns = $energy; Note = $(if (-not $energy.Count) { 'In der Datei wurden keine Energiespalten gefunden.' } else { '' }) }
}

# ---------------------------------------------------------------- powercfg /energy (HTML-Bericht auswerten)
function Get-EnEnergyCatalog {
    @(
        @{ R = '(?i)Platform Timer Resolution|Plattformzeitgeber|Zeitgeberauflösung'; T = 'Zeitgeber-Auflösung erhöht'; E = 'Ein Programm hat den Windows-Takt beschleunigt (z.B. von 15,6 ms auf 1 ms). Der Prozessor wacht dadurch bis zu 1000-mal pro Sekunde auf und kommt nicht in tiefe Schlafzustände - das kostet spürbar Akku.'; Tip = 'Unter "Details" steht, welches Programm es ist (häufig Browser mit Video, Chat-, Musik- oder Spiele-Programme). Programm schließen, wenn es nicht gebraucht wird.' }
        @{ R = '(?i)USB Suspend|USB.*(Standby|Energiespar|Suspend|Ruhezustand)|USB-Energie'; T = 'USB-Gerät schläft nicht ein'; E = 'Ein USB-Gerät oder USB-Controller geht nicht in den Energiesparmodus. USB-Geräte, die ständig aktiv bleiben, verhindern, dass der Prozessor tief schläft.'; Tip = 'Gerät abziehen, wenn nicht gebraucht (z.B. Webcam, Dongle, Kartenleser). Treiber aktualisieren. Im Energiesparplan "Selektives USB-Energiesparen" aktiviert lassen.' }
        @{ R = '(?i)CPU Utilization|Processor utilization|Prozessorauslastung|CPU-Auslastung'; T = 'Hohe Prozessorlast während der Messung'; E = 'Während der 60 Sekunden war der Prozessor deutlich beschäftigt. Dauerlast ist der größte Akkufresser überhaupt.'; Tip = 'Im Task-Manager nach dem Verursacher sehen (Spalte "Energieverbrauch"). Die Messung möglichst ohne offene Programme wiederholen.' }
        @{ R = '(?i)Display timeout|Display.*(abschalt|Zeitlimit|aus)|Bildschirm.*(Zeitlimit|abschalt|ausschalt|aus nach)'; T = 'Bildschirm schaltet spät oder nie ab'; E = 'Der Bildschirm ist einer der größten Verbraucher eines Laptops. Ist er nach langer Zeit (oder nie) aus, läuft der Akku auch bei Pausen leer.'; Tip = 'Seite Individualisieren > Energie: "Bildschirm ausschalten nach" im Akkubetrieb auf 3-5 Minuten.' }
        @{ R = '(?i)Display dim|Dim.*display|abblend|gedimmt'; T = 'Bildschirm wird spät gedimmt'; E = 'Das Abdunkeln vor dem Abschalten spart Strom, ohne zu stören.'; Tip = 'In den erweiterten Energieoptionen "Bildschirm abdunkeln nach" kürzer stellen.' }
        @{ R = '(?i)Sleep timeout|Sleep.*disabled|Standby.*(deaktiviert|nie)|Energie sparen.*(nie|deaktiviert)|Leerlauf.*Standby'; T = 'Standby nach Leerlauf ist aus'; E = 'Der PC geht bei Nichtbenutzung nicht von selbst in den Energiesparmodus.'; Tip = 'Seite Individualisieren > Energie: "Energie sparen nach" im Akkubetrieb auf 10-15 Minuten setzen.' }
        @{ R = '(?i)802\.11|Wireless|Drahtlos|WLAN|WiFi'; T = 'WLAN-Energiesparen ist aus oder schwach'; E = 'Der WLAN-Adapter läuft im Akkubetrieb mit voller Leistung statt im Sparmodus.'; Tip = 'Im Plan "PC-Tools Akku-Langläufer" ist WLAN-Energiesparen auf "Maximal" gestellt. Bei Verbindungsabbrüchen wieder auf "Mittel".' }
        @{ R = '(?i)ASPM|Active.?State Power|PCI Express.*(Energie|Power)|Verbindungszustand'; T = 'PCI-Express-Energiesparen (ASPM) aus'; E = 'Die Energiesparfunktion der PCI-Express-Verbindungen (Grafik, SSD, WLAN) ist abgeschaltet - entweder im Energiesparplan oder weil Firmware/Hardware sie nicht unterstützen.'; Tip = 'Im Energiesparplan "Verbindungszustand-Energieverwaltung" auf "Maximale Energieeinsparung" (Akku). Steht dort "vom BIOS deaktiviert", hilft nur ein BIOS-Update oder die BIOS-Einstellung "ASPM".' }
        @{ R = '(?i)Minimum processor|Mindest.*Prozessor|Minimaler Leistungszustand|Minimum.*performance state'; T = 'Mindest-Prozessorleistung hoch eingestellt'; E = 'Der Prozessor darf im Leerlauf nicht herunter takten.'; Tip = 'Im Energiesparplan "Minimaler Leistungszustand des Prozessors" auf 5 % stellen (Standard).' }
        @{ R = '(?i)Power Plan Personality|High Performance|Höchstleistung|Ultimative'; T = 'Leistungs-Energieplan aktiv'; E = 'Ein Energieplan für Höchstleistung ist aktiv. Im Akkubetrieb verkürzt das die Laufzeit deutlich.'; Tip = 'Unten unter "Energiesparpläne" auf "Ausbalanciert" oder "PC-Tools Ausgewogen leise" wechseln.' }
        @{ R = '(?i)Power Capabilities Not Supported|Sleep state.*(not supported|nicht unterst)|Standbymodus.*nicht|Energieverwaltungsfunktionen|Power Management Capabilities'; T = 'Energiesparfunktionen der Plattform'; E = 'Firmware oder Treiber melden eingeschränkte Energiesparfunktionen (z.B. ein Standby-Modus fehlt). Bei Desktop-PCs ist das normal, bei Laptops deutet es auf fehlende Chipsatz-/Grafiktreiber oder ein veraltetes BIOS hin.'; Tip = 'Chipsatz- und Grafiktreiber des Herstellers und das neueste BIOS installieren (Seite Treiber).' }
        @{ R = '(?i)System Availability|Systemverfügbarkeit|Request.*(Display|System)|Anforderung'; T = 'Programm oder Treiber hält den PC wach'; E = 'Ein Programm, Dienst oder Treiber hat Windows gebeten, nicht in den Standby zu gehen oder den Bildschirm anzulassen (z.B. Videowiedergabe, Download, Präsentation).'; Tip = 'Unter "Standby und Aufwachen" zeigt "Was verhindert gerade den Standby?" den aktuellen Stand.' }
        @{ R = '(?i)Device not entering|Gerät.*(nicht|kein).*(Energie|Standby|D3)|not entering suspend|D3'; T = 'Gerät geht nicht in den Sparzustand'; E = 'Ein Gerät bleibt im vollen Betriebszustand, obwohl es nicht benutzt wird.'; Tip = 'Treiber des genannten Geräts aktualisieren; bei USB-Geräten abziehen.' }
        @{ R = '(?i)Disk.*(idle|timeout)|Datenträger.*(Leerlauf|ausschalten)|Festplatte'; T = 'Datenträger schaltet nicht ab'; E = 'Eine Festplatte darf im Leerlauf nicht anhalten. Bei SSDs ist der Effekt gering, bei Festplatten groß.'; Tip = 'Im Energiesparplan "Festplatte ausschalten nach" im Akkubetrieb auf 10 Minuten.' }
        @{ R = '(?i)Video.*(quality|Qualität)|Video playback|Videowiedergabe'; T = 'Videowiedergabe auf Qualität statt Akku'; E = 'Videos werden im Akkubetrieb in voller Qualität dekodiert.'; Tip = 'Einstellungen > Apps > Videowiedergabe > "Für Akkulaufzeit optimieren".' }
        @{ R = '(?i)Battery:|Akku:|Battery Information|Akkuinformationen|Battery Capacity|Akkukapazität'; T = 'Akku-Informationen'; E = 'Daten des Akkus aus der Messung (Hersteller, Kapazität bei Auslieferung und heute). Weicht "letzte vollständige Ladung" stark von der "Auslegungskapazität" ab, ist der Akku verschlissen.'; Tip = 'Oben auf dieser Seite stehen die gleichen Werte mit Verlauf.' }
        @{ R = '(?i)Processor Power Management|Prozessorenergieverwaltung|Processor Performance|Leistungsverwaltung'; T = 'Prozessor-Energieverwaltung'; E = 'Information über die Energiesparzustände (C-States) und Taktstufen (P-States) des Prozessors.'; Tip = 'Nur zur Information.' }
        @{ R = '(?i)Hibernate|Ruhezustand'; T = 'Ruhezustand'; E = 'Hinweis zum Ruhezustand (Hibernate).'; Tip = 'Unten unter "Standby und Aufwachen" ein- oder ausschalten.' }
        @{ R = '(?i)Smart Battery|Akkuverwaltung'; T = 'Akkuverwaltung'; E = 'Hinweis zur Akkuverwaltung der Firmware.'; Tip = 'BIOS und Akku-/Chipsatztreiber des Herstellers aktuell halten.' }
    )
}
function ConvertTo-EnPlain([string]$Html) {
    $t = [regex]::Replace($Html, '(?is)<(script|style)[^>]*>.*?</\1>', ' ')
    $t = [regex]::Replace($t, '(?i)<br\s*/?>', ' ')
    $t = [regex]::Replace($t, '<[^>]+>', ' ')
    $t = [System.Net.WebUtility]::HtmlDecode($t)
    return ([regex]::Replace($t, '\s+', ' ')).Trim()
}
function ConvertFrom-EnEnergyHtml([string]$Html) {
    $cat = Get-EnEnergyCatalog
    $names = @([regex]::Matches($Html, '(?is)<(span|td|div|th)[^>]*class="[^"]*log-entry-name[^"]*"[^>]*>(.*?)</\1>'))
    $heads = @([regex]::Matches($Html, '(?is)<h[1-6][^>]*>(.*?)</h[1-6]>'))
    $res = [System.Collections.Generic.List[object]]::new()
    for ($i = 0; $i -lt $names.Count; $i++) {
        $m = $names[$i]
        $endIdx = if ($i + 1 -lt $names.Count) { $names[$i + 1].Index } else { $Html.Length }
        $chunk = $Html.Substring($m.Index, $endIdx - $m.Index)
        $title = ConvertTo-EnPlain $m.Groups[2].Value
        if (-not $title) { continue }
        # Schweregrad: letzte class mit error/warning/info vor dem Eintrag, sonst Überschrift
        $sev = ''
        $back = $Html.Substring([math]::Max(0, $m.Index - 1500), [math]::Min(1500, $m.Index))
        $cls = @([regex]::Matches($back, '(?i)class="([^"]*(error|warn|info)[^"]*)"'))
        if ($cls.Count) { $c = $cls[$cls.Count - 1].Groups[1].Value; $sev = $(if ($c -match '(?i)error') { 'Fehler' } elseif ($c -match '(?i)warn') { 'Warnung' } else { 'Info' }) }
        if (-not $sev) {
            $hd = @($heads | Where-Object { $_.Index -lt $m.Index }); if ($hd.Count) { $ht = ConvertTo-EnPlain $hd[$hd.Count - 1].Groups[1].Value
                $sev = $(if ($ht -match '(?i)error|fehler') { 'Fehler' } elseif ($ht -match '(?i)warn') { 'Warnung' } elseif ($ht -match '(?i)info') { 'Info' } else { '' }) }
        }
        if (-not $sev) { $sev = 'Info' }
        $desc = ''; $dm = [regex]::Match($chunk, '(?is)<(span|td|div)[^>]*class="[^"]*log-entry-description[^"]*"[^>]*>(.*?)</\1>'); if ($dm.Success) { $desc = ConvertTo-EnPlain $dm.Groups[2].Value }
        $det = [System.Collections.Generic.List[string]]::new()
        foreach ($tr in [regex]::Matches($chunk, '(?is)<tr[^>]*>\s*<td[^>]*>(.*?)</td>\s*<td[^>]*>(.*?)</td>\s*</tr>')) {
            $k = ConvertTo-EnPlain $tr.Groups[1].Value; $v = ConvertTo-EnPlain $tr.Groups[2].Value
            if ($k -and $k -ne $title -and $k -ne $desc -and $det.Count -lt 40) { $det.Add(('{0}: {1}' -f $k, $v)) }
        }
        $hit = $null; foreach ($c in $cat) { if ($title -match $c.R) { $hit = $c; break } }
        $cat2, $sub = $title -split ':', 2
        $de = if ($hit) { $hit.T } else { $title }
        $res.Add([pscustomobject]@{ Severity = $sev; Title = $title; Category = $(if ($sub) { $cat2.Trim() } else { '' }); Desc = $desc; German = $de
            Explain = $(if ($hit) { $hit.E } else { '' }); Tip = $(if ($hit) { $hit.Tip } else { '' }); Details = @($det); Known = [bool]$hit })
    }
    $order = @{ 'Fehler' = 0; 'Warnung' = 1; 'Info' = 2 }
    @($res | Sort-Object @{ Expression = { $order[$_.Severity] } }, @{ Expression = { $_.Title } })
}
function Invoke-EnEnergyTrace([string]$OutFile, [int]$Seconds = 60) {
    $dir = Split-Path $OutFile -Parent; if ($dir) { $null = New-Item $dir -ItemType Directory -Force -ErrorAction SilentlyContinue }
    Remove-Item -LiteralPath $OutFile -Force -ErrorAction SilentlyContinue
    $out = Invoke-NdCmd 'powercfg.exe' ('/energy /output "{0}" /duration {1}' -f $OutFile, $Seconds) ($Seconds + 90)
    $items = @(); $ok = Test-Path -LiteralPath $OutFile
    if ($ok) { $html = [IO.File]::ReadAllText($OutFile); $items = @(ConvertFrom-EnEnergyHtml $html) }
    [pscustomobject]@{ Ok = $ok; File = $OutFile; Output = $out; Items = $items }
}

# ---------------------------------------------------------------- powercfg /a (verfügbare Standby-Arten)
function ConvertFrom-EnPowerCfgA([string]$Text) {
    $avail = [System.Collections.Generic.List[object]]::new(); $not = [System.Collections.Generic.List[object]]::new()
    $mode = ''; $last = $null
    foreach ($ln in ($Text -split "`r?`n")) {
        if (-not $ln.Trim()) { continue }
        if ($ln -notmatch '^\s') {
            if ($ln -match '(?i)not available|nicht verfügbar|nicht verf.gbar|non disponibil|no disponible') { $mode = 'N' } elseif ($ln -match '(?i)available|verfügbar|verf.gbar|disponibil') { $mode = 'A' } else { $mode = '' }
            $last = $null; continue
        }
        if (-not $mode) { continue }
        $ind = $ln.Length - $ln.TrimStart().Length
        if ($ind -le 5) {
            $last = [pscustomobject]@{ Name = $ln.Trim(); Id = (Get-EnSleepStateId $ln.Trim()); Reasons = [System.Collections.Generic.List[string]]::new() }
            if ($mode -eq 'A') { $avail.Add($last) } else { $not.Add($last) }
        } elseif ($last -and $mode -eq 'N') { $last.Reasons.Add($ln.Trim()) }
    }
    $has = { param($id) [bool](@($avail | Where-Object { $_.Id -eq $id }).Count) }
    [pscustomobject]@{ Available = $avail.ToArray(); NotAvailable = $not.ToArray()
        ModernStandby = (& $has 'S0'); S3 = (& $has 'S3'); S1 = (& $has 'S1'); S2 = (& $has 'S2'); Hibernate = (& $has 'Hibernate'); Hybrid = (& $has 'Hybrid'); FastStartup = (& $has 'FastStartup')
        S0Network = [bool](@($avail | Where-Object { $_.Id -eq 'S0' -and $_.Name -match '(?i)connected|verbunden' }).Count) }
}
function Get-EnSleepStateId([string]$Name) {
    if ($Name -match '(?i)S0|Low Power Idle|Niedrigenergie|Leerlauf') { return 'S0' }
    if ($Name -match '(?i)\(S1\)') { return 'S1' }; if ($Name -match '(?i)\(S2\)') { return 'S2' }; if ($Name -match '(?i)\(S3\)') { return 'S3' }
    if ($Name -match '(?i)Hybrid') { return 'Hybrid' }
    if ($Name -match '(?i)Fast Startup|Schnellstart') { return 'FastStartup' }
    if ($Name -match '(?i)Hibernat|Ruhezustand') { return 'Hibernate' }
    return 'Other'
}

# ---------------------------------------------------------------- powercfg /requests (was verhindert den Standby)
function ConvertFrom-EnRequests([string]$Text) {
    $catDe = @{ DISPLAY = 'Bildschirm bleibt an'; SYSTEM = 'Standby wird verhindert'; AWAYMODE = 'Abwesenheitsmodus'; EXECUTION = 'Programm läuft weiter'; PERFBOOST = 'Leistungsschub'; ACTIVELOCKSCREEN = 'Sperrbildschirm aktiv' }
    $typeDe = @{ DRIVER = 'Treiber'; PROCESS = 'Programm'; SERVICE = 'Dienst'; KERNEL = 'Windows-Kern' }
    $cur = ''; $item = $null
    $list = [System.Collections.Generic.List[object]]::new()
    foreach ($ln in ($Text -split "`r?`n")) {
        $t = $ln.Trim()
        if (-not $t) { $item = $null; continue }
        if ($t -match '^([A-Z]{3,})\s*:\s*$') { $cur = $Matches[1]; $item = $null; continue }
        if (-not $cur) { continue }
        if ($t -match '^(?i)(None|Keine|Kein|Aucun|Ninguno|Nessuna)\.?$') { continue }
        if ($t -match '^\[([A-Z]+)\]\s*(.*)$') {
            $ty = $Matches[1]; $src = $Matches[2].Trim()
            $item = [pscustomobject]@{ Category = $cur; CategoryText = $(if ($catDe.ContainsKey($cur)) { $catDe[$cur] } else { $cur }); Type = $ty; TypeText = $(if ($typeDe.ContainsKey($ty)) { $typeDe[$ty] } else { $ty })
                Source = $src; Name = (Get-EnRequestName $ty $src); Reason = '' }
            $list.Add($item); continue
        }
        if ($item) { $item.Reason = (($item.Reason + ' ' + $t).Trim()) }
    }
    $list.ToArray()
}
function Get-EnRequestName([string]$Type, [string]$Src) {
    if ($Type -eq 'PROCESS' -and $Src -match '[\\/]') { return (Get-EnAppName $Src) }
    if ($Type -eq 'DRIVER') { return ($Src -replace '\s*\([^\)]*\\[^\)]*\)\s*$', '').Trim() }
    return $Src
}
# ---------------------------------------------------------------- powercfg /waketimers
function ConvertFrom-EnWakeTimers([string]$Text) {
    $list = [System.Collections.Generic.List[object]]::new(); $cur = $null
    foreach ($ln in ($Text -split "`r?`n")) {
        $t = $ln.Trim(); if (-not $t) { continue }
        $m = [regex]::Match($t, '\[(SERVICE|PROCESS|DRIVER|KERNEL)\]\s*(.+?)(?:\s+(?:expires|festgelegter|gesetzter|l\S*uft|abl\S*uft)\b.*)?$')
        if ($m.Success) {
            $ty = $m.Groups[1].Value; $src = $m.Groups[2].Value.Trim(); $when = ''
            $tm = [regex]::Match($t, '(\d{1,2}:\d\d(?::\d\d)?)\s*(AM|PM)?\D+?(\d{1,2}[\./]\d{1,2}[\./]\d{2,4}|\d{4}-\d\d-\d\d)')
            if ($tm.Success) { $when = ('{0} {1}{2}' -f $tm.Groups[3].Value, $tm.Groups[1].Value, $(if ($tm.Groups[2].Value) { ' ' + $tm.Groups[2].Value } else { '' })) }
            $cur = [pscustomobject]@{ Type = $ty; Source = $src; Name = (Get-EnRequestName $ty $src); When = $when; Reason = ''; Task = '' }
            $list.Add($cur); continue
        }
        if (-not $cur) { continue }
        $r = [regex]::Match($t, '^(?i)(Reason|Grund|Ursache)\s*:\s*(.*)$')
        $txt = $(if ($r.Success) { $r.Groups[2].Value.Trim() } else { $t })
        $cur.Reason = (($cur.Reason + ' ' + $txt).Trim())
        if (-not $cur.Task) { $q = [regex]::Match($cur.Reason, "'([^']+)'"); if ($q.Success) { $cur.Task = $q.Groups[1].Value } }
    }
    $list.ToArray()
}
# ---------------------------------------------------------------- powercfg /lastwake
function ConvertFrom-EnLastWake([string]$Text) {
    $srcs = [System.Collections.Generic.List[object]]::new(); $cur = $null
    $keyMap = @{ 'type' = 'Type'; 'typ' = 'Type'; 'friendly name' = 'Name'; 'anzeigename' = 'Name'; 'description' = 'Desc'; 'beschreibung' = 'Desc'; 'instance path' = 'Path'; 'instanzpfad' = 'Path'; 'manufacturer' = 'Maker'; 'hersteller' = 'Maker' }
    foreach ($ln in ($Text -split "`r?`n")) {
        $t = $ln.Trim(); if (-not $t) { continue }
        if ($t -match '(?i)(Wake Source|Reaktivierungsquelle)\s*\[\d+\]') { $cur = [ordered]@{ Type = ''; Name = ''; Desc = ''; Path = ''; Maker = '' }; $srcs.Add($cur); continue }
        if ($cur -and $t -match '^([^:]{2,40}?)\s*:\s*(.*)$') { $k = $Matches[1].Trim().ToLower(); if ($keyMap.ContainsKey($k)) { $cur[$keyMap[$k]] = $Matches[2].Trim() } }
    }
    foreach ($s in $srcs) {
        $n = if ($s.Name) { $s.Name } elseif ($s.Desc) { $s.Desc } else { $s.Type }
        [pscustomobject]@{ Type = $s.Type; Name = $n; Desc = $s.Desc; Path = $s.Path; Text = $(if ($s.Type -and $n -ne $s.Type) { '{0} ({1})' -f $n, $s.Type } else { $n }) }
    }
}
# ---------------------------------------------------------------- powercfg /devicequery
function ConvertFrom-EnDeviceList([string]$Text) {
    @(($Text -split "`r?`n") | ForEach-Object { $_.Trim() } | Where-Object { $_ -and $_ -notmatch '^(?i)(NONE|KEINE?|AUCUN|NINGUNO|NESSUNO)\.?$' -and $_ -notmatch '^\(' })
}
# ---------------------------------------------------------------- powercfg /list
function ConvertFrom-EnPlanList([string]$Text) {
    $b = Get-EnBuiltinPlans
    foreach ($ln in ($Text -split "`r?`n")) {
        if ($ln -match '([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12})\s+\((.+)\)\s*(\*)?\s*$') {
            $g = $Matches[1].ToLower(); $n = $Matches[2]; $act = [bool]$Matches[3]
            [pscustomobject]@{ Guid = $g; Name = $n; Active = $act; ActiveText = $(if ($act) { 'aktiv' } else { '' }); Builtin = $b.ContainsKey($g); Own = ($n -like 'PC-Tools*')
                Kind = $(if ($b.ContainsKey($g)) { 'Windows' } elseif ($n -like 'PC-Tools*') { 'PC-Tools' } else { 'Eigener/Hersteller' }) }
        }
    }
}
# ---------------------------------------------------------------- powercfg /sleepstudy /xml (Modern Standby)
function ConvertFrom-EnSleepStudyXml([string]$XmlText) {
    $x = New-Object System.Xml.XmlDocument; $x.XmlResolver = $null
    $x.LoadXml(($XmlText -replace '^﻿', ''))
    $nodes = @($x.SelectNodes("//*[local-name()='ScenarioInstance' or local-name()='Session' or local-name()='SleepSession' or local-name()='StandbySession']"))
    $list = [System.Collections.Generic.List[object]]::new()
    foreach ($n in $nodes) {
        $st = ConvertTo-EnDate (Get-EnXFirst $n '^(?i)(LocalStartTime|LocalStart|StartTime|Start|EntryTime)$')
        $en = ConvertTo-EnDate (Get-EnXFirst $n '^(?i)(LocalEndTime|LocalEnd|EndTime|End|ExitTime)$')
        $durRaw = Get-EnXFirst $n '^(?i)(Duration|DurationMs|TotalDuration)$'
        $dur = [double]::NaN
        if ($st -and $en -and $en -gt $st) { $dur = ($en - $st).TotalMinutes }
        elseif ($durRaw -match '^\d+(\.\d+)?$') { $dur = ConvertTo-EnMinutes $durRaw $(if ((Get-EnXFirst $n '^(?i)DurationMs$') -or [double]$durRaw -ge 1000000) { 'ms' } else { 's' }) }
        else { $dur = ConvertTo-EnMinutes $durRaw }
        $typ = Get-EnXFirst $n '^(?i)(Type|ScenarioType|SessionType|Kind|State)$'
        $tt = switch -Regex ($typ) { '(?i)screen ?off|standby|sleep|drips|^2$|cs' { 'Standby (Bildschirm aus)' } '(?i)active|screen ?on|^1$' { 'Aktiv' } '(?i)hibern' { 'Ruhezustand' } default { $(if ($typ) { $typ } else { 'Standby' }) } }
        $drRaw = Get-EnXFirst $n '^(?i)(SwDripsPercent|SwDrips|DripsPercent|DripsPercentage|HwDripsPercent|HwDrips|Drips|LowPowerStatePercentage)$'
        $drips = ConvertTo-EnNum $drRaw; if (-not [double]::IsNaN($drips) -and $drips -le 1 -and $drRaw -match '\.') { $drips = $drips * 100 }
        $enRaw = Get-EnXFirst $n '^(?i)(EnergyDrain|EnergyChange|Discharge|DischargeMwh|EnergyDrainMwh|ChargeChange|CapacityChange|EnergyConsumed)$'
        $energy = [math]::Abs((ConvertTo-EnNum $enRaw))
        $pctRaw = Get-EnXFirst $n '^(?i)(PercentDrain|DrainPercent|BatteryDrainPercent|PercentageDrained|ChargeDrainPercent)$'
        $pct = [math]::Abs((ConvertTo-EnNum $pctRaw))
        $offs = [System.Collections.Generic.List[string]]::new()
        foreach ($o in @($n.SelectNodes('.//*'))) {
            if ($o.LocalName -notmatch '(?i)blocker|offender|activator|culprit') { continue }
            $nm = Get-EnXFirst $o '^(?i)(Name|FriendlyName|Id|ComponentName|Component)$'
            if (-not $nm -and -not $o.HasAttributes -and $o.ChildNodes.Count -eq 1 -and $o.FirstChild.NodeType -eq 'Text') { $nm = $o.InnerText }
            if (-not $nm) { continue }
            $sh = Get-EnXFirst $o '^(?i)(ActivePercent|Percent|Percentage|ActiveTimePercent|Contribution)$'
            $nm = Get-EnAppName $nm
            $s = if ($sh) { '{0} ({1} %)' -f $nm, ([math]::Round((ConvertTo-EnNum $sh))) } else { $nm }
            if (-not $offs.Contains($s) -and $offs.Count -lt 5) { $offs.Add($s) }
        }
        $rate = [double]::NaN; if ($energy -gt 0 -and $dur -gt 0) { $rate = $energy / ($dur / 60) }
        $list.Add([pscustomobject]@{ Start = $st; End = $en; DurMin = $dur; Type = $tt; Drips = $drips; Energy = $energy; Percent = $pct; RateMw = $rate; Offenders = $offs.ToArray()
            StartText = $(if ($st) { $st.ToString('dd.MM. HH:mm') } else { '' }); DurText = (Format-EnDur $dur)
            DripsText = $(if ([double]::IsNaN($drips)) { '-' } else { '{0:N0} %' -f $drips })
            DrainText = $(if ($pct -gt 0) { '{0:N1} %' -f $pct } elseif ($energy -gt 0) { '{0:N0} mWh' -f $energy } else { '-' })
            RateText = $(if ([double]::IsNaN($rate)) { '-' } else { '{0:N0} mW' -f $rate })
            OffText = ($offs -join ', ') })
    }
    $sb = @($list | Where-Object { $_.Type -like 'Standby*' })
    $bad = @($sb | Where-Object { (-not [double]::IsNaN($_.Drips) -and $_.Drips -lt 80 -and $_.DurMin -ge 15) -or ($_.Percent -gt 0 -and $_.DurMin -gt 0 -and ($_.Percent / ($_.DurMin / 60)) -gt 1.5) })
    [pscustomobject]@{ Sessions = @($list | Sort-Object Start -Descending); StandbyCount = $sb.Count; BadCount = $bad.Count
        AvgDrips = $(if (@($sb | Where-Object { -not [double]::IsNaN($_.Drips) }).Count) { [math]::Round((@($sb | Where-Object { -not [double]::IsNaN($_.Drips) }) | Measure-Object Drips -Average).Average) } else { [double]::NaN }) }
}

# ---------------------------------------------------------------- Akku- und USV-Daten (WMI)
function Get-EnSysPower {
    try {
        Add-Type -ErrorAction Stop -TypeDefinition @'
using System; using System.Runtime.InteropServices;
namespace PCPflegeEn {
public static class Pwr {
  [StructLayout(LayoutKind.Sequential)] public struct SPS { public byte AC; public byte Flag; public byte Pct; public byte Saver; public int Life; public int Full; }
  [DllImport("kernel32.dll")] static extern bool GetSystemPowerStatus(out SPS s);
  [DllImport("powrprof.dll")] static extern uint PowerGetActualOverlayScheme(out Guid g);
  [DllImport("powrprof.dll")] static extern uint PowerSetActiveOverlayScheme(Guid g);
  public static int[] Get() { SPS s; if (!GetSystemPowerStatus(out s)) return null; return new int[] { s.AC, s.Flag, s.Pct, s.Saver, s.Life, s.Full }; }
  public static string Overlay() { Guid g; try { if (PowerGetActualOverlayScheme(out g) == 0) return g.ToString(); } catch { } return ""; }
  public static uint SetOverlay(string id) { try { return PowerSetActiveOverlayScheme(new Guid(id)); } catch { return 9999; } }
}}
'@
    } catch { }
    try { $a = [PCPflegeEn.Pwr]::Get(); if ($a) { return [pscustomobject]@{ Ac = $a[0]; Flag = $a[1]; Pct = $a[2]; Saver = ($a[3] -eq 1); LifeSec = $a[4]; FullSec = $a[5]; NoBattery = (($a[1] -band 128) -ne 0) } } } catch { }
    return $null
}
function Get-EnBatteryInfo {
    $o = [ordered]@{ Present = $false; Batteries = @(); Ups = @(); Design = 0.0; Full = 0.0; Remaining = 0.0; Rate = 0.0; ChargeRate = 0.0; Voltage = 0.0; Online = $true; Charging = $false
                     Percent = -1; Cycles = -1; Health = [double]::NaN; EstMin = [double]::NaN; FullMin = [double]::NaN; ToFullMin = [double]::NaN; Saver = $false; Chemistry = ''; Maker = ''; Name = ''; Serial = ''
                     IsLaptop = $false; Model = ''; Manufacturer = ''; Product = ''; Error = '' }
    try { $cs = Get-CimInstance Win32_ComputerSystem -ErrorAction Stop; $o.IsLaptop = ([int]$cs.PCSystemType -eq 2 -or [int]$cs.PCSystemTypeEx -in 2, 8); $o.Manufacturer = [string]$cs.Manufacturer; $o.Model = [string]$cs.Model } catch { }
    try { $o.Product = [string](Get-CimInstance Win32_ComputerSystemProduct -ErrorAction Stop).Version } catch { }
    $sp = Get-EnSysPower
    if ($sp) { $o.Saver = $sp.Saver; if ($sp.Ac -eq 0) { $o.Online = $false } }
    $wb = @(Get-CimInstance Win32_Battery -ErrorAction SilentlyContinue)
    $pnp = @(Get-PnpDevice -Class Battery -PresentOnly -ErrorAction SilentlyContinue)
    $hidUps = @($pnp | Where-Object { [string]$_.InstanceId -like 'HID\*' -or [string]$_.FriendlyName -match '(?i)\bUPS\b|USV|HID.*(Battery|Akku)' })
    $upsRx = '(?i)\bUPS\b|USV|Back-?UPS|Smart-?UPS|Eaton|CyberPower|PowerWalker|BlueWalker|Riello|Online USV|Easy UPS|APC'
    $ups = @($wb | Where-Object { [string]$_.Name -match $upsRx -or [string]$_.DeviceID -match $upsRx -or ([int]$_.Chemistry -eq 3) })
    if (-not $ups.Count -and $hidUps.Count -and -not $o.IsLaptop) { $ups = @($wb) }
    $o.Ups = @($ups | ForEach-Object {
        [pscustomobject]@{ Name = ([string]$_.Name).Trim(); Device = [string]$_.DeviceID; Percent = [int]$_.EstimatedChargeRemaining
            RunMin = $(if ([uint32]$_.EstimatedRunTime -gt 0 -and [uint32]$_.EstimatedRunTime -lt 71582788) { [double]$_.EstimatedRunTime } else { [double]::NaN })
            Status = $(switch ([int]$_.BatteryStatus) { 1 { 'Batteriebetrieb (Netz ausgefallen!)' } 2 { 'Netzbetrieb' } 3 { 'voll geladen' } 4 { 'schwach' } 5 { 'kritisch' } 6 { 'lädt' } 7 { 'lädt (hoch)' } 8 { 'lädt (niedrig)' } 9 { 'lädt (kritisch)' } 11 { 'teilweise geladen' } default { 'Status {0}' -f $_.BatteryStatus } })
            OnBattery = ([int]$_.BatteryStatus -eq 1 -or [int]$_.BatteryStatus -in 4, 5); Chemistry = (Get-EnChemName ([string]$_.Chemistry)) } })
    $upsIds = @($ups | ForEach-Object { [string]$_.DeviceID })
    $static = @(); $fullC = @(); $stat = @(); $cyc = @()
    try { $static = @(Get-CimInstance -Namespace root\wmi -ClassName BatteryStaticData -ErrorAction Stop) } catch { }
    try { $fullC = @(Get-CimInstance -Namespace root\wmi -ClassName BatteryFullChargedCapacity -ErrorAction Stop) } catch { }
    try { $stat = @(Get-CimInstance -Namespace root\wmi -ClassName BatteryStatus -ErrorAction Stop -OperationTimeoutSec 5) } catch { }
    try { $cyc = @(Get-CimInstance -Namespace root\wmi -ClassName BatteryCycleCount -ErrorAction Stop) } catch { }
    $list = [System.Collections.Generic.List[object]]::new()
    # Desktop-PC mit USB-USV: die "Akkus" in root\wmi sind die USV
    $skipAll = (-not $o.IsLaptop -and $hidUps.Count -gt 0 -and $ups.Count -gt 0)
    foreach ($s in $static) {
        if ($skipAll) { break }
        $inst = [string]$s.InstanceName
        $f = @($fullC | Where-Object { [string]$_.InstanceName -eq $inst })[0]; $st = @($stat | Where-Object { [string]$_.InstanceName -eq $inst })[0]; $cc = @($cyc | Where-Object { [string]$_.InstanceName -eq $inst })[0]
        $name = ([string]$s.DeviceName).Trim()
        if ($upsIds.Count -and ($name -match $upsRx)) { continue }
        $chemCode = ''
        try { $bytes = [BitConverter]::GetBytes([uint32]$s.Chemistry); $chemCode = ([Text.Encoding]::ASCII.GetString($bytes) -replace '[^\x20-\x7E]', '').Trim() } catch { }
        $des = [double]$s.DesignedCapacity; $fc = $(if ($f) { [double]$f.FullChargedCapacity } else { 0.0 })
        $md = ''; try { if ($s.ManufactureDate) { $md = ([datetime]$s.ManufactureDate).ToString('dd.MM.yyyy') } } catch { }
        $list.Add([pscustomobject]@{ Instance = $inst; Name = $name; Maker = ([string]$s.ManufactureName).Trim(); Serial = ([string]$s.SerialNumber).Trim(); Chemistry = (Get-EnChemName $chemCode); ManufactureDate = $md
            Design = $des; Full = $fc; Health = $(if ($des -gt 0 -and $fc -gt 0) { [math]::Round([math]::Min(100.0, $fc * 100 / $des), 1) } else { [double]::NaN })
            Cycles = $(if ($cc -and [int]$cc.CycleCount -gt 0) { [int]$cc.CycleCount } else { -1 })
            Remaining = $(if ($st) { [double]$st.RemainingCapacity } else { 0.0 }); Rate = $(if ($st -and [int]$st.DischargeRate -gt 0 -and [int]$st.DischargeRate -lt 500000) { [double]$st.DischargeRate } else { 0.0 })
            ChargeRate = $(if ($st -and [int]$st.ChargeRate -gt 0 -and [int]$st.ChargeRate -lt 500000) { [double]$st.ChargeRate } else { 0.0 })
            Voltage = $(if ($st) { [double]$st.Voltage } else { 0.0 }); Online = $(if ($st) { [bool]$st.PowerOnline } else { $true }); Charging = $(if ($st) { [bool]$st.Charging } else { $false }) })
    }
    if (-not $list.Count -and -not $skipAll -and $wb.Count -gt $ups.Count) {
        # Fallback: nur Win32_Battery
        foreach ($b in @($wb | Where-Object { $upsIds -notcontains [string]$_.DeviceID })) {
            $list.Add([pscustomobject]@{ Instance = [string]$b.DeviceID; Name = ([string]$b.Name).Trim(); Maker = ''; Serial = ''; Chemistry = (Get-EnChemName ([string]$b.Chemistry)); ManufactureDate = ''
                Design = [double]$b.DesignCapacity; Full = [double]$b.FullChargeCapacity; Health = [double]::NaN; Cycles = -1; Remaining = 0.0; Rate = 0.0; ChargeRate = 0.0; Voltage = 0.0; Online = ([int]$b.BatteryStatus -ne 1); Charging = ([int]$b.BatteryStatus -in 6, 7, 8, 9) })
        }
    }
    $o.Batteries = $list.ToArray()
    if ($list.Count) {
        $o.Present = $true
        foreach ($b in $list) { $o.Design += $b.Design; $o.Full += $b.Full; $o.Remaining += $b.Remaining; $o.Rate += $b.Rate; $o.ChargeRate += $b.ChargeRate }
        $o.Voltage = [double]$list[0].Voltage; $o.Online = [bool](@($list | Where-Object { $_.Online }).Count); $o.Charging = [bool](@($list | Where-Object { $_.Charging }).Count)
        if ($sp -and $sp.Ac -eq 0) { $o.Online = $false }
        $o.Chemistry = $list[0].Chemistry; $o.Maker = $list[0].Maker; $o.Name = $list[0].Name; $o.Serial = $list[0].Serial
        $cy = @($list | Where-Object { $_.Cycles -ge 0 }); if ($cy.Count) { $o.Cycles = [int](($cy | Measure-Object Cycles -Maximum).Maximum) }
        if ($o.Design -gt 0 -and $o.Full -gt 0) { $o.Health = [math]::Round([math]::Min(100.0, $o.Full * 100 / $o.Design), 1) }
        $wbl = @($wb | Where-Object { $upsIds -notcontains [string]$_.DeviceID })
        if ($o.Full -gt 0 -and $o.Remaining -gt 0) { $o.Percent = [int][math]::Min(100, [math]::Round($o.Remaining * 100 / $o.Full)) } elseif ($wbl.Count) { $o.Percent = [int]$wbl[0].EstimatedChargeRemaining } elseif ($sp -and $sp.Pct -le 100) { $o.Percent = [int]$sp.Pct }
        if (-not $o.Online -and $o.Rate -gt 0) { $o.EstMin = $o.Remaining / $o.Rate * 60; $o.FullMin = $o.Full / $o.Rate * 60 }
        elseif (-not $o.Online -and $sp -and $sp.LifeSec -gt 0) { $o.EstMin = $sp.LifeSec / 60 }
        elseif (-not $o.Online -and $wbl.Count -and [uint32]$wbl[0].EstimatedRunTime -lt 71582788) { $o.EstMin = [double]$wbl[0].EstimatedRunTime }
        if ($o.Charging -and $o.ChargeRate -gt 0 -and $o.Full -gt $o.Remaining) { $o.ToFullMin = ($o.Full - $o.Remaining) / $o.ChargeRate * 60 }
    }
    [pscustomobject]$o
}
# Eigener Verlauf (Verlauf.csv von Gerätezustand) als Punkte
function Get-EnOwnHistory([string]$Dir) {
    $f = Join-Path $Dir 'Verlauf.csv'
    if (-not (Test-Path -LiteralPath $f)) { return }
    foreach ($r in @(Import-Csv -LiteralPath $f -Delimiter ';' -Encoding UTF8)) {
        $v = ConvertTo-EnNum ([string]$r.AkkuProzent); if ([double]::IsNaN($v) -or $v -le 0) { continue }
        $d = $null; try { $d = [datetime]::ParseExact([string]$r.Datum, 'yyyy-MM-dd', [Globalization.CultureInfo]::InvariantCulture) } catch { continue }
        [pscustomobject]@{ Date = $d; Pct = $v; Cycles = (ConvertTo-EnNum ([string]$r.Ladezyklen)) }
    }
}
function Get-EnBatteryReport([string]$Dir) {
    $null = New-Item $Dir -ItemType Directory -Force -ErrorAction SilentlyContinue
    $f = Join-Path $Dir 'Akkubericht.xml'
    Remove-Item -LiteralPath $f -Force -ErrorAction SilentlyContinue
    $out = Invoke-NdCmd 'powercfg.exe' ('/batteryreport /xml /output "{0}"' -f $f) 90
    if (-not (Test-Path -LiteralPath $f)) { throw ('Akkubericht nicht erstellt: ' + $out) }
    ConvertFrom-EnBatteryReportXml ([IO.File]::ReadAllText($f))
}
function Get-EnSrum([string]$Dir, [int]$Days) {
    $null = New-Item $Dir -ItemType Directory -Force -ErrorAction SilentlyContinue
    $f = Join-Path $Dir 'srumutil.csv'
    Remove-Item -LiteralPath $f -Force -ErrorAction SilentlyContinue
    $out = Invoke-NdCmd 'powercfg.exe' ('/srumutil /output "{0}" /csv' -f $f) 180
    if (-not (Test-Path -LiteralPath $f)) { throw ('Die Energiedaten (SRUM) konnten nicht gelesen werden: ' + $out) }
    ConvertFrom-EnSrumCsv ([IO.File]::ReadAllText($f)) $Days (Get-Date)
}
function Get-EnSleepStudy([string]$Dir, [int]$Days = 3) {
    $null = New-Item $Dir -ItemType Directory -Force -ErrorAction SilentlyContinue
    $f = Join-Path $Dir 'Standbystudie.xml'; $h = Join-Path $Dir 'Standbystudie.html'
    Remove-Item -LiteralPath $f, $h -Force -ErrorAction SilentlyContinue
    $out = Invoke-NdCmd 'powercfg.exe' ('/sleepstudy /xml /output "{0}" /duration {1}' -f $f, $Days) 120
    $null = Invoke-NdCmd 'powercfg.exe' ('/sleepstudy /output "{0}" /duration {1}' -f $h, $Days) 120
    $r = $null
    if (Test-Path -LiteralPath $f) { try { $r = ConvertFrom-EnSleepStudyXml ([IO.File]::ReadAllText($f)) } catch { $out += ' ' + $_.Exception.Message } }
    [pscustomobject]@{ Ok = [bool]$r; Data = $r; Html = $(if (Test-Path -LiteralPath $h) { $h } else { '' }); Output = $out }
}
function Get-EnSleepInfo {
    $a = ConvertFrom-EnPowerCfgA (Invoke-NdCmd 'powercfg.exe' '/a' 30)
    $req = @(ConvertFrom-EnRequests (Invoke-NdCmd 'powercfg.exe' '/requests' 30))
    $tim = @(ConvertFrom-EnWakeTimers (Invoke-NdCmd 'powercfg.exe' '/waketimers' 30))
    $lw = @(ConvertFrom-EnLastWake (Invoke-NdCmd 'powercfg.exe' '/lastwake' 30))
    $armed = @(ConvertFrom-EnDeviceList (Invoke-NdCmd 'powercfg.exe' '/devicequery wake_armed' 30))
    $prog = @(ConvertFrom-EnDeviceList (Invoke-NdCmd 'powercfg.exe' '/devicequery wake_programmable' 30))
    $devs = foreach ($d in @(@($armed) + @($prog) | Select-Object -Unique)) {
        $kind = switch -Regex ($d) { '(?i)ethernet|network|netzwerk|wi-?fi|wlan|wireless|lan|realtek pcie|intel.*(I2\d\d|connection)' { 'Netzwerk' } '(?i)keyboard|tastatur|hid keyboard' { 'Tastatur' } '(?i)mouse|maus|pointing|touchpad|trackpoint' { 'Maus/Touchpad' } '(?i)usb.*(hub|root|controller|xhci)|xhci|host controller' { 'USB-Controller' } '(?i)bluetooth' { 'Bluetooth' } default { 'Gerät' } }
        [pscustomobject]@{ Name = $d; Armed = ($armed -contains $d); ArmedText = $(if ($armed -contains $d) { 'Ja' } else { 'Nein' }); Kind = $kind }
    }
    $hist = [System.Collections.Generic.List[object]]::new()
    try {
        foreach ($e in @(Get-WinEvent -FilterHashtable @{ LogName = 'System'; ProviderName = 'Microsoft-Windows-Power-Troubleshooter'; Id = 1 } -MaxEvents 25 -ErrorAction Stop)) {
            $msg = [string]$e.Message; $src = ''
            $m = [regex]::Match($msg, '(?im)^\s*(Wake Source|Reaktivierungsquelle|Quelle der Reaktivierung)\s*:\s*(.+)$'); if ($m.Success) { $src = $m.Groups[2].Value.Trim() }
            $sl = ''; $ms = [regex]::Match($msg, '(?im)^\s*(Sleep Time|Standbyzeit|Energiesparzeit|Zeit des Standbymodus)\s*:\s*(.+)$'); if ($ms.Success) { $sl = $ms.Groups[2].Value.Trim() }
            if (-not $src) { try { $px = [xml]$e.ToXml(); $src = [string](@($px.Event.EventData.Data | Where-Object { $_.Name -match 'WakeSourceText' })[0].'#text') } catch { } }
            $hist.Add([pscustomobject]@{ Time = $e.TimeCreated; TimeText = $e.TimeCreated.ToString('dd.MM.yyyy HH:mm'); Source = $(if ($src) { $src } else { 'unbekannt' }); Slept = $sl })
        }
    } catch { }
    $hibOn = $false; $hibType = ''; $hibPct = -1; $hibSize = -1.0; $fast = $false
    try { $pr = Get-ItemProperty 'HKLM:\SYSTEM\CurrentControlSet\Control\Power' -ErrorAction Stop; $hibOn = [int]$pr.HibernateEnabled -eq 1; if ($null -ne $pr.HiberFileType) { $hibType = $(if ([int]$pr.HiberFileType -eq 1) { 'reduziert' } elseif ([int]$pr.HiberFileType -eq 2) { 'vollständig' } else { '' }) }; if ($null -ne $pr.HiberFileSizePercent) { $hibPct = [int]$pr.HiberFileSizePercent } } catch { }
    try { $hf = Get-Item -LiteralPath (Join-Path $env:SystemDrive 'hiberfil.sys') -Force -ErrorAction Stop; $hibSize = [double]$hf.Length } catch { }
    try { $fast = [int](Get-ItemProperty 'HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Power' -Name HiberbootEnabled -ErrorAction Stop).HiberbootEnabled -eq 1 } catch { }
    [pscustomobject]@{ States = $a; Requests = $req; Timers = $tim; LastWake = $lw; Devices = @($devs | Sort-Object @{ Expression = { -not $_.Armed } }, Name); History = $hist.ToArray()
        HibOn = $hibOn; HibType = $hibType; HibPct = $hibPct; HibSize = $hibSize; FastStartup = $fast }
}
function Get-EnPlans { @(ConvertFrom-EnPlanList (Invoke-NdCmd 'powercfg.exe' '/list' 20)) }
function Get-EnOverlay {
    $ac = ''; $dc = ''; $now = ''
    try { $k = Get-ItemProperty 'HKLM:\SYSTEM\CurrentControlSet\Control\Power\User\PowerSchemes' -ErrorAction Stop; $ac = [string]$k.ActiveOverlayAcPowerScheme; $dc = [string]$k.ActiveOverlayDcPowerScheme } catch { }
    $o = Invoke-NdCmd 'powercfg.exe' '/getactiveoverlayscheme' 10
    if ($o -match '([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12})') { $now = $Matches[1].ToLower() }
    if (-not $now) { try { $null = Get-EnSysPower; $now = [PCPflegeEn.Pwr]::Overlay() } catch { } }
    $act = ''; $p = Invoke-NdCmd 'powercfg.exe' '/getactivescheme' 10
    if ($p -match '([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12})') { $act = $Matches[1].ToLower() }
    [pscustomobject]@{ Ac = $(if ($ac) { $ac.ToLower() } else { '00000000-0000-0000-0000-000000000000' }); Dc = $(if ($dc) { $dc.ToLower() } else { '00000000-0000-0000-0000-000000000000' }); Now = $now; ActivePlan = $act; Supported = [bool]($o -match '[0-9a-fA-F]{8}-' -or $ac -or $dc -or $now) }
}
function Set-EnOverlay([string]$Ac, [string]$Dc, [bool]$OnAc) {
    $k = 'HKLM:\SYSTEM\CurrentControlSet\Control\Power\User\PowerSchemes'
    if ($Ac) { Set-ItemProperty -Path $k -Name ActiveOverlayAcPowerScheme -Value $Ac -Type String -ErrorAction Stop }
    if ($Dc) { Set-ItemProperty -Path $k -Name ActiveOverlayDcPowerScheme -Value $Dc -Type String -ErrorAction Stop }
    $now = $(if ($OnAc) { $Ac } else { $Dc })
    if (-not $now) { return 'gespeichert' }
    $o = Invoke-NdCmd 'powercfg.exe' ('/overlaysetactive {0}' -f $now) 15
    if ($o -match '(?i)invalid|ungültig|unbekannt|not recognized|nicht erkannt|Fehler|error') {
        try { $null = Get-EnSysPower; $r = [PCPflegeEn.Pwr]::SetOverlay($now); if ($r -eq 0) { return 'sofort aktiv' } } catch { }
        return ('gespeichert (wirkt nach dem nächsten Netzteilwechsel oder Neustart): ' + $o)
    }
    return 'sofort aktiv'
}
function New-EnPowerPlan([string]$Key, [bool]$Activate = $true) {
    $pre = @(Get-EnPlanPresets | Where-Object { $_.Key -eq $Key })[0]
    if (-not $pre) { throw ('Unbekannte Vorlage: ' + $Key) }
    $log = [System.Collections.Generic.List[string]]::new()
    $o = Invoke-NdCmd 'powercfg.exe' ('/duplicatescheme {0}' -f '381b4222-f694-41f0-9685-ff5bb260df2e') 20
    $m = [regex]::Match($o, '([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12})')
    if (-not $m.Success) { throw ('Plan konnte nicht angelegt werden: ' + $o) }
    $g = $m.Value.ToLower()
    $desc = ($pre.Desc -replace '"', "'"); if ($desc.Length -gt 250) { $desc = $desc.Substring(0, 247) + '...' }
    $null = Invoke-NdCmd 'powercfg.exe' ('/changename {0} "{1}" "{2}"' -f $g, $pre.Name, $desc) 15
    foreach ($v in $pre.Values) {
        if ([int]$v[2] -ge 0) { $r = Invoke-NdCmd 'powercfg.exe' ('/setacvalueindex {0} {1} {2} {3}' -f $g, $v[0], $v[1], $v[2]) 15; if ($r) { $log.Add(('{0}/{1} Netz: {2}' -f $v[0].Substring(0, 8), $v[1].Substring(0, 8), $r)) } }
        if ([int]$v[3] -ge 0) { $r = Invoke-NdCmd 'powercfg.exe' ('/setdcvalueindex {0} {1} {2} {3}' -f $g, $v[0], $v[1], $v[3]) 15; if ($r) { $log.Add(('{0}/{1} Akku: {2}' -f $v[0].Substring(0, 8), $v[1].Substring(0, 8), $r)) } }
    }
    if ($Activate) { $null = Invoke-NdCmd 'powercfg.exe' ('/setactive {0}' -f $g) 15 }
    [pscustomobject]@{ Guid = $g; Name = $pre.Name; Notes = $log.ToArray() }
}

# ---------------------------------------------------------------- Ladegrenze (Hersteller-Schnittstellen)
# Bekannte Werte -> Klartext. Unbekannte Werte werden unverändert angezeigt.
function Get-EnChargeValueText([string]$Name, [string]$Value) {
    $v = [string]$Value
    $map = @{
        'Let HP manage my battery charging' = 'HP entscheidet automatisch (Standard)'; 'Maximize my battery health' = 'Akku schonen (lädt nur bis ca. 80 %)'; 'Maximize my battery duration' = 'Volle Laufzeit (immer bis 100 %)'
        'Standard' = 'Standard (normales Laden bis 100 %)'; 'Express' = 'Schnellladen (ExpressCharge)'; 'ExpressCharge' = 'Schnellladen (ExpressCharge)'; 'PrimAcUse' = 'Überwiegend am Netzteil (lädt nur bis ca. 50-60 %)'
        'Adaptive' = 'Adaptiv (Dell lernt das Nutzungsverhalten)'; 'Custom' = 'Benutzerdefiniert (Start/Stopp unten)'; 'Enable' = 'Ein'; 'Disable' = 'Aus'; 'Enabled' = 'Ein'; 'Disabled' = 'Aus'
    }
    if ($map.ContainsKey($v)) { return $map[$v] }
    return $v
}
function Get-EnChargeLimit {
    $cs = Get-CimInstance Win32_ComputerSystem -ErrorAction SilentlyContinue
    $mk = [string]$cs.Manufacturer; $model = [string]$cs.Model; $ver = ''
    try { $ver = [string](Get-CimInstance Win32_ComputerSystemProduct -ErrorAction Stop).Version } catch { }
    $vendor = if ($mk -match 'Lenovo') { 'Lenovo' } elseif ($mk -match 'HP|Hewlett') { 'HP' } elseif ($mk -match 'Dell') { 'Dell' } elseif ($mk -match 'Microsoft' -and $model -match 'Surface') { 'Surface' } elseif ($mk -match 'ASUS') { 'ASUS' } elseif ($mk -match 'Acer') { 'Acer' } elseif ($mk -match 'Micro-Star|MSI') { 'MSI' } elseif ($mk -match 'Samsung') { 'Samsung' } elseif ($mk -match 'Framework') { 'Framework' } elseif ($mk -match 'HUAWEI|HONOR') { 'Huawei' } else { $mk }
    $o = [ordered]@{ Vendor = $vendor; Model = $(if ($vendor -eq 'Lenovo' -and $ver) { '{0} ({1})' -f $ver, $model } else { $model }); Method = ''; State = ''; Settings = @(); Settable = $false; Hint = ''; App = ''; Extra = @() }
    $rx = '(?i)batt.*(charg|health|care|cfg|mode|conserv|limit|thresh|life|manage)|charg.*(start|stop|thresh|limit|cfg|mode|custom|level)|adaptive.?batt|custom.?charge|conservation|battery.?health|batt.?care'
    if ($vendor -in 'HP', 'Dell', 'Lenovo') {
        try {
            $all = Get-BiosFull
            $hit = @($all | ForEach-Object { $_ } | Where-Object { $_.Name -match $rx -and $_.Name -notmatch '(?i)alarm|warn|password|usb|alwayson|always.?on|wake|dock|boot|express.?card|peak|audio|beep|in.?battery|on.?battery|remaining|port' })
            $o.Settings = @($hit | ForEach-Object { [pscustomobject]@{ Vendor = $_.Vendor; Name = $_.Name; Label = $_.Label; Current = $_.Current; CurrentText = (Get-EnChargeValueText $_.Name $_.Current); Options = @($_.Options); Type = $_.Type; ReadOnly = $_.ReadOnly } })
            if ($o.Settings.Count) { $o.Method = '{0} BIOS-WMI (dieselbe Schnittstelle wie auf der Seite BIOS-Einstellungen)' -f $vendor; $o.Settable = [bool](@($o.Settings | Where-Object { -not $_.ReadOnly }).Count) }
        } catch { if ($vendor -ne 'Lenovo') { $o.Extra += ('BIOS-Schnittstelle nicht lesbar: ' + $_.Exception.Message) } }
    }
    switch ($vendor) {
        'Lenovo' {
            $tp = ($ver -match '(?i)ThinkPad|ThinkBook' -or $model -match '^(20|21)')
            $vant = [bool](Get-AppxPackage -AllUsers -Name 'E046963F.LenovoCompanion' -ErrorAction SilentlyContinue) -or [bool](Get-AppxPackage -AllUsers -Name 'E046963F.LenovoSettingsforEnterprise' -ErrorAction SilentlyContinue)
            $o.App = $(if ($vant) { 'Lenovo Vantage ist installiert' } else { 'Lenovo Vantage nicht gefunden (Microsoft Store: "Lenovo Vantage", Firmen: "Commercial Vantage")' })
            foreach ($rk in 'HKLM:\SOFTWARE\WOW6432Node\Lenovo\PWRMGRV\ConfKeys\Data', 'HKLM:\SOFTWARE\Lenovo\PWRMGRV\ConfKeys\Data') {
                try { $pk = Get-ItemProperty -Path $rk -ErrorAction Stop
                      if ($null -ne $pk.ChargeStopPercentage -or $null -ne $pk.ChargeStartPercentage) { $o.State = 'Laut Lenovo-Energieverwaltung: Laden startet bei {0} %, stoppt bei {1} %' -f $(if ($pk.ChargeStartPercentage) { $pk.ChargeStartPercentage } else { '?' }), $(if ($pk.ChargeStopPercentage) { $pk.ChargeStopPercentage } else { '?' }); break } } catch { }
            }
            if (-not $o.Settings.Count) { $o.Method = $(if ($tp) { 'ThinkPad: Ladeschwellen über den Lenovo-Energieverwaltungstreiber (Lenovo Vantage > Gerät > Stromversorgung > Akku-Ladeschwellenwert)' } else { 'IdeaPad/Legion/Yoga: "Schutzmodus" (Conservation Mode, lädt nur bis ca. 60-80 %) in Lenovo Vantage > Gerät > Stromversorgung' }) }
            $o.Hint = $(if ($tp) { 'ThinkPad: "Benutzerdefinierter Akku-Ladeschwellenwert" z.B. Start 75 %, Stopp 80 % - ideal für Geräte, die meist am Netzteil hängen. Die Werte speichert der Akku selbst; sie gelten danach auch ohne Vantage. Lenovo bietet dafür keine öffentlich dokumentierte WMI-Schnittstelle - PC-Tools öffnet daher Vantage.' } else { 'IdeaPad/Yoga/Legion: Der Schutzmodus begrenzt die Ladung auf ca. 60 % (neuere Modelle 80 %). Lenovo bietet dafür keine öffentlich dokumentierte WMI-Schnittstelle - PC-Tools öffnet daher Vantage.' })
        }
        'HP' { if (-not $o.Settings.Count) { $o.Method = 'Keine Ladegrenzen-Einstellung im BIOS gefunden'; $o.Hint = 'Ältere HP-Modelle haben nur "Battery Care Function" im BIOS-Menü (F10) oder gar keine Ladegrenze. HP Power Manager / HP Support Assistant zeigen ggf. weitere Optionen.' } else { $o.Hint = 'HP "Battery Health Manager": "Akku schonen" begrenzt die Ladung auf ca. 80 % - empfohlen für Laptops, die meist am Netzteil oder in der Dockingstation stehen.' } }
        'Dell' { if (-not $o.Settings.Count) { $o.Method = 'Keine Ladegrenzen-Einstellung im BIOS-WMI gefunden'; $o.Hint = 'Ältere Dell-Modelle ohne BIOS-WMI: Dell Power Manager / Dell Optimizer oder Dell Command | Configure ("Primary Battery Charge Configuration").' } else { $o.Hint = 'Dell "Primary Battery Charge Configuration": "Überwiegend am Netzteil" oder "Benutzerdefiniert" (z.B. Start 50 %, Stopp 80 %) schont den Akku. Bei "Benutzerdefiniert" zuerst Start/Stopp setzen, dann den Modus.' } }
        'Surface' { $o.Method = 'Surface UEFI: "Akkubegrenzungsmodus" (Battery Limit, lädt nur bis 50 %); neuere Modelle zusätzlich "Intelligentes Laden" (Smart Charging, 80 %) in der Surface-App'; $o.Hint = 'Battery Limit stellt man im Surface UEFI ein: Seite "Neustart und BIOS" > "UEFI/BIOS öffnen", dort Boot configuration > Advanced options > "Enable Battery Limit Mode". Firmen mit SEMM können es zentral setzen.'; $o.App = 'Surface-App' }
        'ASUS' { $o.Method = 'MyASUS > Gerät > Akku-Pflege (Battery Health Charging: 60 / 80 / 100 %)'; $o.Hint = 'Die Einstellung wird über den ASUS-System-Control-Treiber gesetzt und bleibt erhalten.' }
        'Acer' { $o.Method = 'Acer Care Center / AcerSense > Akku-Ladegrenze (80 %)'; $o.Hint = '' }
        'MSI' { $o.Method = 'MSI Center > Akku-Ladeoption (Best for Mobility / Balanced / Best for Battery)'; $o.Hint = '' }
        'Samsung' { $o.Method = 'Samsung Settings > Akku-Lebensdauer verlängern (85 %)'; $o.Hint = '' }
        'Framework' { $o.Method = 'BIOS-Setup > Advanced > "Battery Charge Limit" (z.B. 80 %)'; $o.Hint = '' }
        'Huawei' { $o.Method = 'PC Manager > Smart Charge'; $o.Hint = '' }
        default { if (-not $o.Method) { $o.Method = 'Keine bekannte Herstellerschnittstelle - die Hersteller-App oder das BIOS-Setup prüfen.' } }
    }
    # Windows 11: Intelligentes Laden (nur bestimmte Geräte, z.B. Copilot+-PCs mit Firmware-Unterstützung)
    try { $b = [int](Get-ItemProperty 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion' -ErrorAction Stop).CurrentBuild; if ($b -ge 26100) { $o.Extra += 'Windows 11: Unter Einstellungen > System > Energie und Akku gibt es auf unterstützten Geräten "Intelligentes Laden" (Smart Charging) - lädt bis 80 %, wenn der Laptop meist am Netzteil ist.' } } catch { }
    [pscustomobject]$o
}
