#  FERNWARTUNGS-DASHBOARD (Fd) - PC-Tools 10, Seite "Meine PCs"
#  Gemeinsamer Ordner (Fleet.Dir):
#    <PC>.json                   Zustand (Write-FleetStatus, erweitert um Add-FdStatusFields)
#    Heartbeat\<PC>.json         Lebenszeichen, alle 10 Minuten (Aufgabe "PC-Pflege Fernaufträge")
#    Protokolle\<PC>.txt         Auszug der letzten Protokolle (Fleet.UploadLog)
#    Auftraege\<PC>\<Id>.json    Auftrag (+ <Id>.result.json Ergebnis, online.txt)
#    Meldungen\<Schlüssel>.json  Sperrdatei: jede Problem-Meldung wird nur von EINEM PC verschickt
#  Sicherheit: nur Aktionen aus $FleetActions, Aufträge höchstens 3 Tage alt, nur für diesen PC,
#  optional HMAC-Signatur (Auftragsschlüssel) und strenge Ordnerrechte-Prüfung (Fleet.StrictAcl).
# =====================================================================
$FleetActions['Neustart'] = 'Neu starten (mit Hinweis an den Benutzer, Wartezeit wählbar)'
$FleetActions['Aus'] = 'Herunterfahren (mit Hinweis an den Benutzer, Wartezeit wählbar)'
$FleetActions['Selbsttest'] = 'Selbsttest von PC-Tools ausführen'
$FleetActions['NotfallStick'] = 'Notfall-Stick-Status prüfen'
$FleetActions['Komplettsicherung'] = 'Komplettsicherung starten (Systemabbild)'
$FdKeyFile = Join-Path $DataDir 'fernauftrag.key'

# ---- Zeit und Anzeige (reine Aufbereitung, überall nutzbar)
function Get-FdTime($Value) {
    if ($null -eq $Value) { return $null }
    if ($Value -is [datetime]) { return [datetime]$Value }
    $s = ([string]$Value).Trim()
    if (-not $s) { return $null }
    $dt = [datetime]::MinValue
    foreach ($fmt in 'dd.MM.yyyy HH:mm', 'dd.MM.yyyy HH:mm:ss', 'dd.MM.yyyy', 'yyyy-MM-dd') {
        if ([datetime]::TryParseExact($s, $fmt, [Globalization.CultureInfo]::InvariantCulture, [Globalization.DateTimeStyles]::None, [ref]$dt)) { return $dt }
    }
    if ([datetime]::TryParse($s, [Globalization.CultureInfo]::InvariantCulture, [Globalization.DateTimeStyles]::RoundtripKind, [ref]$dt)) {
        if ($dt.Kind -eq [DateTimeKind]::Utc) { return $dt.ToLocalTime() }
        return $dt
    }
    return $null
}
function Get-FdAgeText([double]$Min) {
    if ($Min -ge [double]::MaxValue / 2) { return 'nie' }
    if ($Min -lt 1) { return 'gerade eben' }
    if ($Min -lt 60) { return ('vor {0:N0} Min.' -f [math]::Floor($Min)) }
    if ($Min -lt 2880) { return ('vor {0:N0} Std.' -f [math]::Floor($Min / 60)) }
    return ('vor {0:N0} Tagen' -f [math]::Floor($Min / 1440))
}
function ConvertTo-FdSafeName([string]$Text) { (($Text -replace '[^A-Za-z0-9_\-\.]', '_') -replace '_{2,}', '_').Trim('_') }

# ---- Online-Logik: zuletzt gesehen = jüngste Meldung aus Status, Heartbeat und online.txt
function Get-FdLastSeen([object[]]$Times) {
    $best = $null
    foreach ($t in $Times) { $x = Get-FdTime $t; if ($x -and (-not $best -or $x -gt $best)) { $best = $x } }
    return $best
}
function Get-FdOnlineState($LastSeen, [datetime]$Now, [int]$OnlineMin = 25, [bool]$HasBeat = $true, [int]$LongH = 72) {
    if ($OnlineMin -lt 5) { $OnlineMin = 25 }
    $t = Get-FdTime $LastSeen
    if (-not $t) { return [pscustomobject]@{ State = 'nie'; AgeMin = [double]::MaxValue; Text = 'nie gemeldet'; Online = $false; Sort = 4 } }
    $age = ($Now - $t).TotalMinutes
    if ($age -lt 0) { $age = 0 }
    $st = if ($age -le $OnlineMin) { 'online' } elseif (-not $HasBeat) { 'unbekannt' } elseif ($age -le ($LongH * 60)) { 'offline' } else { 'lange' }
    $tx = switch ($st) { 'online' { 'online' } 'offline' { 'offline' } 'lange' { 'lange offline' } default { 'ohne Heartbeat' } }
    $so = switch ($st) { 'online' { 0 } 'offline' { 1 } 'lange' { 2 } default { 3 } }
    [pscustomobject]@{ State = $st; AgeMin = [math]::Round($age, 1); Text = $tx; Online = ($st -eq 'online'); Sort = $so }
}

# ---- Datensicherung: Zustand aus backup_last.json (Invoke-BackupJob)
function Get-FdBackupState($Info, [string]$Target, [datetime]$Now, [int]$MaxDays = 14) {
    if (-not $Target) { return [pscustomobject]@{ State = 'aus'; Last = ''; Text = 'nicht eingerichtet'; AgeDays = -1 } }
    if (-not $Info) { return [pscustomobject]@{ State = 'nie'; Last = ''; Text = 'noch nie gesichert'; AgeDays = -1 } }
    $t = Get-FdTime $Info.Date
    $age = if ($t) { [math]::Round(($Now - $t).TotalDays, 1) } else { -1 }
    $err = 0; try { $err = [int]$Info.Errors } catch { }
    $st = if ($err -gt 0) { 'Fehler' } elseif ($t -and $MaxDays -gt 0 -and $age -gt $MaxDays) { 'alt' } else { 'ok' }
    $tx = switch ($st) { 'Fehler' { '{0} Problem(e) am {1:dd.MM.}' -f $err, $t } 'alt' { 'vor {0:N0} Tagen' -f $age } default { if ($t) { '{0:dd.MM.yyyy HH:mm}' -f $t } else { 'ok' } } }
    [pscustomobject]@{ State = $st; Last = $(if ($t) { $t.ToString('o') } else { '' }); Text = $tx; AgeDays = $age }
}

# ---- Neustart-Pending (Registry, schnell)
function Test-FdRebootPending {
    $p = @('HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Component Based Servicing\RebootPending', 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\WindowsUpdate\Auto Update\RebootRequired')
    foreach ($x in $p) { if (Test-Path -LiteralPath $x) { return $true } }
    try {
        $a = (Get-ItemProperty 'HKLM:\SYSTEM\CurrentControlSet\Control\ComputerName\ActiveComputerName' -ErrorAction Stop).ComputerName
        $b = (Get-ItemProperty 'HKLM:\SYSTEM\CurrentControlSet\Control\ComputerName\ComputerName' -ErrorAction Stop).ComputerName
        if ($a -and $b -and $a -ne $b) { return $true }
    } catch { }
    return $false
}

# ---- Zwischenspeicher für teure Werte (Ereignisse, Windows-Update-Zähler)
function Get-FdCache {
    $h = @{}
    try { $j = Get-Content -LiteralPath (Join-Path $DataDir 'fd-cache.json') -Raw -Encoding UTF8 -ErrorAction Stop | ConvertFrom-Json; foreach ($p in $j.PSObject.Properties) { $h[$p.Name] = $p.Value } } catch { }
    return $h
}
function Save-FdCache([hashtable]$H) { try { [pscustomobject]$H | ConvertTo-Json -Depth 3 | Set-Content -LiteralPath (Join-Path $DataDir 'fd-cache.json') -Encoding UTF8 } catch { } }
function Test-FdCacheFresh([hashtable]$H, [string]$Name, [double]$MaxMin) {
    $t = Get-FdTime $H[$Name + 'At']
    return [bool]($t -and ((Get-Date) - $t).TotalMinutes -lt $MaxMin -and $null -ne $H[$Name])
}
function Get-FdWuPendingCount {
    # Offline-Suche gegen die zwischengespeicherten Update-Daten von Windows (schnell, kein Download)
    $s = New-Object -ComObject Microsoft.Update.Session
    $se = $s.CreateUpdateSearcher(); $se.Online = $false
    $r = $se.Search("IsInstalled=0 and IsHidden=0 and Type='Software'")
    return [int]$r.Updates.Count
}

# ---- Zustands-Score-Verlauf kompakt für den Status
function Get-FdScoreSeries($Rows, [int]$Last = 30) {
    @(@($Rows) | Where-Object { $_ -and [string]$_.Datum -match '^\d{4}-\d\d-\d\d$' -and [string]$_.Score -match '^\d+$' } | Sort-Object Datum | Select-Object -Last $Last | ForEach-Object { [pscustomobject]@{ D = [string]$_.Datum; S = [int]$_.Score } })
}
function Get-FdScoreDrop($Hist, [datetime]$Now) {
    $h = @(@($Hist) | Where-Object { $_ -and [string]$_.D -match '^\d{4}-\d\d-\d\d$' } | Sort-Object D)
    if ($h.Count -lt 3) { return $null }
    $lastRow = $h[$h.Count - 1]
    $ld = [datetime]::ParseExact([string]$lastRow.D, 'yyyy-MM-dd', [Globalization.CultureInfo]::InvariantCulture)
    if (($Now.Date - $ld).TotalDays -gt 2) { return $null }
    $from = $ld.AddDays(-7).ToString('yyyy-MM-dd')
    $prev = @($h | Where-Object { [string]$_.D -lt [string]$lastRow.D -and [string]$_.D -ge $from })
    if ($prev.Count -lt 2) { return $null }
    $avg = [double](($prev | ForEach-Object { [double]$_.S } | Measure-Object -Average).Average)
    [pscustomobject]@{ Date = [string]$lastRow.D; Score = [int]$lastRow.S; Avg = [math]::Round($avg, 1); Drop = [math]::Round($avg - [double]$lastRow.S, 1) }
}

# ---- Zusatzfelder für den Status: reine Zusammenführung (testbar) + Erhebung (Windows)
function Merge-FdStatus($Obj, $Facts) {
    if (-not $Obj -or -not $Facts) { return $Obj }
    foreach ($k in @($Facts.Keys)) {
        if ($Obj.PSObject.Properties[[string]$k]) {
            # Felder anderer Teile (z.B. FullBackup aus Get-FbFleetInfo) nicht überschreiben, wenn schon gefüllt
            if ($k -eq 'FullBackup' -and $null -ne $Obj.$k) { continue }
            $Obj.$k = $Facts[$k]
        } else { $Obj | Add-Member -NotePropertyName ([string]$k) -NotePropertyValue $Facts[$k] }
    }
    return $Obj
}
function Get-FdStatusFacts([string]$Dir, $Old) {
    $cfg = $null; try { $cfg = Read-PflegeConfig } catch { }
    $now = Get-Date
    $f = [ordered]@{ Schema = 2; Heartbeat = $now.ToString('o') }
    $c = Get-FdCache; $dirty = $false
    try { $reg = Get-ItemProperty 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion' -ErrorAction Stop; $f.WinBuild = ('{0}.{1}' -f $reg.CurrentBuild, $reg.UBR); $f.WinDisplay = [string]$reg.DisplayVersion } catch { $f.WinBuild = ''; $f.WinDisplay = '' }
    $f.Edition = $(if ($Script:IsLite) { 'Lite' } else { 'Voll' })
    $f.Portable = [bool]$Script:IsPortable
    try { $os = Get-CimInstance Win32_OperatingSystem -ErrorAction Stop; $f.UptimeH = [math]::Round(((Get-Date) - $os.LastBootUpTime).TotalHours, 1) } catch { $f.UptimeH = -1 }
    try { $dv = New-Object IO.DriveInfo $env:SystemDrive; $f.DiskFreePct = [math]::Round([double]$dv.AvailableFreeSpace * 100 / [double]$dv.TotalSize, 0) } catch { $f.DiskFreePct = -1 }
    $f.RebootPending = $(try { [bool](Test-FdRebootPending) } catch { $false })
    # Zustands-Score
    $hist = @(); try { $hist = @(Get-ScScoreHistory $DataDir 45) } catch { }
    $f.ScoreHist = @(Get-FdScoreSeries $hist 30)
    $f.Score = $(if (@($f.ScoreHist).Count) { [int]@($f.ScoreHist)[@($f.ScoreHist).Count - 1].S } else { -1 })
    $f.ScoreDate = $(if (@($f.ScoreHist).Count) { [string]@($f.ScoreHist)[@($f.ScoreHist).Count - 1].D } else { '' })
    # Datensicherung
    $bl = $null; try { $bl = Get-Content -LiteralPath (Join-Path $DataDir 'backup_last.json') -Raw -Encoding UTF8 -ErrorAction Stop | ConvertFrom-Json } catch { }
    $bs = Get-FdBackupState $bl $(if ($cfg) { [string]$cfg.Backup.Target } else { '' }) $now 14
    $f.BackupState = $bs.State; $f.BackupLast = $bs.Last; $f.BackupText = $bs.Text
    # letzter Lauf
    $lr = $null; try { $lr = Get-Content -LiteralPath (Join-Path $DataDir 'lastrun.json') -Raw -Encoding UTF8 -ErrorAction Stop | ConvertFrom-Json } catch { }
    $f.RunWarnings = $(if ($lr) { [int]$lr.Warnungen } else { -1 })
    $f.RunParts = $(if ($lr) { [string]$lr.Teile } else { '' })
    # Fehler im System-Ereignisprotokoll (24 Std.) - höchstens alle 30 Minuten neu zählen
    if (-not (Test-FdCacheFresh $c 'Errors24h' 30)) {
        $n = -1; try { $n = @(Get-WinEvent -FilterHashtable @{ LogName = 'System'; Level = 1, 2; StartTime = (Get-Date).AddDays(-1) } -MaxEvents 999 -ErrorAction Stop).Count } catch { if ($_.Exception.Message -match 'No events|Es wurden keine Ereignisse') { $n = 0 } }
        $c.Errors24h = $n; $c.Errors24hAt = $now.ToString('o'); $dirty = $true
    }
    $f.Errors24h = [int]$c.Errors24h
    # offene Windows-Updates: nur im Hintergrund (Fernaufträge-Aufgabe), höchstens alle 6 Stunden
    if ($Script:FdInPoll -and -not (Test-FdCacheFresh $c 'WuPending' 360)) {
        $w = -1; try { $w = Get-FdWuPendingCount } catch { }
        $c.WuPending = $w; $c.WuPendingAt = $now.ToString('o'); $dirty = $true
    }
    $f.WuPending = $(if ($null -ne $c.WuPending) { [int]$c.WuPending } else { -1 })
    $f.WuPendingAt = [string]$c.WuPendingAt
    if ($dirty) { Save-FdCache $c }
    # Komplettsicherung (Teil "FullBackup" eines anderen Teams) - Haken: Get-FbFleetInfo
    $f.FullBackup = $null
    if (Get-Command Get-FbFleetInfo -ErrorAction SilentlyContinue) { try { $f.FullBackup = Get-FbFleetInfo } catch { } }
    # Notfall-Stick (letzte Prüfung per Fernauftrag oder auf der Seite)
    $f.RescueStick = $null; try { $f.RescueStick = Get-Content -LiteralPath (Join-Path $DataDir 'fd-notfallstick.json') -Raw -Encoding UTF8 -ErrorAction Stop | ConvertFrom-Json } catch { }
    # Fernwartung dieses PCs
    $f.HeartbeatOn = [bool]($cfg -and $cfg.Fleet.Heartbeat)
    $f.Watcher = [bool]($cfg -and $cfg.Fleet.Watch)
    $f.StrictAcl = [bool]($cfg -and $cfg.Fleet.StrictAcl)
    $f.KeyFp = $(try { [string](Get-FdKeyFingerprint) } catch { 'Fehler' })
    $f.NotifyOn = [bool]($cfg -and $cfg.Notify.Enabled)
    $f.LogFile = $(if ($cfg -and $cfg.Fleet.UploadLog) { 'Protokolle\{0}.txt' -f $env:COMPUTERNAME } else { '' })
    return $f
}
# Aufruf aus Write-FleetStatus (Pipeline) - gibt NUR das Statusobjekt zurück
function Add-FdStatusFields($Obj, $Old, [string]$Dir, [int]$SecScore = -1) {
    $facts = $null
    try { $facts = Get-FdStatusFacts $Dir $Old } catch { }
    if ($facts) { $null = Merge-FdStatus $Obj $facts }
    try { $null = Save-FdLogExcerpt $Dir } catch { }
    return $Obj
}

# ---- Lebenszeichen (alle 10 Minuten aus der Fernaufträge-Aufgabe)
function New-FdHeartbeat([string]$Computer, [datetime]$Now, $Facts) {
    [pscustomobject]@{
        Computer = $Computer; Time = $Now.ToString('o'); Version = [string]$Facts.Version; Edition = [string]$Facts.Edition
        User = [string]$Facts.User; UptimeH = $Facts.UptimeH; RebootPending = [bool]$Facts.RebootPending; Remote = [bool]$Facts.Remote; Watcher = [bool]$Facts.Watcher
    }
}
function Write-FdHeartbeat([string]$Dir, $Cfg) {
    $bd = Join-Path $Dir 'Heartbeat'
    New-Item -ItemType Directory -Path $bd -Force -ErrorAction Stop | Out-Null
    $u = ''; $up = -1
    try { $u = [string](Get-CimInstance Win32_ComputerSystem -ErrorAction Stop).UserName } catch { }
    try { $up = [math]::Round(((Get-Date) - (Get-CimInstance Win32_OperatingSystem -ErrorAction Stop).LastBootUpTime).TotalHours, 1) } catch { }
    $facts = @{ Version = $AppVersion; Edition = $(if ($Script:IsLite) { 'Lite' } else { 'Voll' }); User = $u; UptimeH = $up; RebootPending = $(try { Test-FdRebootPending } catch { $false }); Remote = [bool]$Cfg.Fleet.Remote; Watcher = [bool]$Cfg.Fleet.Watch }
    $hb = New-FdHeartbeat $env:COMPUTERNAME (Get-Date) $facts
    $f = Join-Path $bd ('{0}.json' -f $env:COMPUTERNAME); $tmp = $f + '.tmp'
    $hb | ConvertTo-Json -Compress | Set-Content -LiteralPath $tmp -Encoding UTF8 -ErrorAction Stop
    Move-Item -LiteralPath $tmp -Destination $f -Force -ErrorAction Stop
}

# ---- Protokoll-Auszug für das Dashboard
function Get-FdLogExcerpt([string]$LogDir, [int]$MainLines = 70, [int]$JobLines = 25, [int]$MaxChars = 60000) {
    $sb = New-Object Text.StringBuilder
    $pick = [System.Collections.Generic.List[object]]::new()
    foreach ($spec in @(@('PCPflege_*.log', $MainLines, 1), @('Fernauftrag_*.log', $JobLines, 1), @('Fernauftraege.log', 10, 1), @('Oberflaeche-Fehler.log', 10, 1))) {
        foreach ($fi in @(Get-ChildItem -LiteralPath $LogDir -Filter $spec[0] -File -ErrorAction SilentlyContinue | Sort-Object LastWriteTime -Descending | Select-Object -First $spec[2])) { $pick.Add([pscustomobject]@{ File = $fi; Lines = [int]$spec[1] }) }
    }
    foreach ($p in $pick) {
        $lines = @(); try { $lines = @(Get-Content -LiteralPath $p.File.FullName -Tail $p.Lines -Encoding UTF8 -ErrorAction Stop) } catch { continue }
        $null = $sb.AppendLine(('===== {0}  ({1:dd.MM.yyyy HH:mm}) =====' -f $p.File.Name, $p.File.LastWriteTime))
        foreach ($l in $lines) { $null = $sb.AppendLine([string]$l) }
        $null = $sb.AppendLine()
    }
    $t = $sb.ToString()
    if ($t.Length -gt $MaxChars) { $t = $t.Substring($t.Length - $MaxChars) }
    return $t
}
function Save-FdLogExcerpt([string]$Dir) {
    $cfg = Read-PflegeConfig
    if (-not $cfg.Fleet.UploadLog -or -not $Dir) { return }
    $ld = Join-Path $Dir 'Protokolle'
    New-Item -ItemType Directory -Path $ld -Force -ErrorAction Stop | Out-Null
    $txt = Get-FdLogExcerpt (Join-Path $DataDir 'Logs')
    $head = 'PC-Tools {0} auf {1} - Auszug vom {2:dd.MM.yyyy HH:mm}' -f $AppVersion, $env:COMPUTERNAME, (Get-Date)
    Set-Content -LiteralPath (Join-Path $ld ('{0}.txt' -f $env:COMPUTERNAME)) -Value ($head + "`r`n`r`n" + $txt) -Encoding UTF8 -ErrorAction Stop
}

# ---- Auftragsschlüssel (HMAC-SHA256). Gespeichert: abgeleiteter Schlüssel, DPAPI (Computer), nur SYSTEM/Administratoren
function ConvertTo-FdKeyBytes([string]$Pass) {
    $sha = [Security.Cryptography.SHA256]::Create()
    try { return , $sha.ComputeHash([Text.Encoding]::UTF8.GetBytes('PC-Tools Fernauftrag v1|' + $Pass)) } finally { $sha.Dispose() }
}
function Get-FdKeyFingerprintOf([byte[]]$Key) {
    if (-not $Key -or $Key.Length -eq 0) { return '' }
    $sha = [Security.Cryptography.SHA256]::Create()
    try { $h = $sha.ComputeHash([byte[]]($Key + [Text.Encoding]::ASCII.GetBytes('fp'))) } finally { $sha.Dispose() }
    $x = -join ($h[0..3] | ForEach-Object { $_.ToString('X2') })
    return ('{0}-{1}' -f $x.Substring(0, 4), $x.Substring(4, 4))
}
function Get-FdKey {
    # $null = kein Schlüssel eingerichtet; Ausnahme = Schlüsseldatei vorhanden, aber unlesbar (dann werden Aufträge abgelehnt)
    if (-not (Test-Path -LiteralPath $FdKeyFile)) { return $null }
    Add-Type -AssemblyName System.Security
    $b = [IO.File]::ReadAllBytes($FdKeyFile)
    $k = [Security.Cryptography.ProtectedData]::Unprotect($b, $null, [Security.Cryptography.DataProtectionScope]::LocalMachine)
    if (-not $k -or $k.Length -ne 32) { throw 'Auftragsschlüssel ist beschädigt.' }
    return , $k
}
function Get-FdKeySafe { try { $k = Get-FdKey; if ($k -and $k.Length -eq 32) { return , $k } } catch { }; return $null }
function Get-FdKeyFingerprint { $k = Get-FdKey; if ($k) { return (Get-FdKeyFingerprintOf $k) }; return '' }
function Set-FdKey([string]$Pass) {
    if ([string]::IsNullOrEmpty($Pass) -or $Pass.Length -lt 12) { throw 'Der Auftragsschlüssel muss mindestens 12 Zeichen lang sein.' }
    Add-Type -AssemblyName System.Security
    $k = ConvertTo-FdKeyBytes $Pass
    $b = [Security.Cryptography.ProtectedData]::Protect($k, $null, [Security.Cryptography.DataProtectionScope]::LocalMachine)
    [IO.File]::WriteAllBytes($FdKeyFile, $b)
    $null = & icacls.exe $FdKeyFile /inheritance:r /grant:r '*S-1-5-18:F' '*S-1-5-32-544:F' 2>&1
    return (Get-FdKeyFingerprintOf $k)
}
function Remove-FdKey { Remove-Item -LiteralPath $FdKeyFile -Force -ErrorAction SilentlyContinue }
function Get-FdJobCanon($Job) {
    $t = Get-FdTime $Job.Time
    $ts = if ($t) { $t.ToUniversalTime().ToString('yyyyMMddHHmmss') } else { '' }
    $dl = ''; $ms = ''
    if ($Job.Params) { if ($null -ne $Job.Params.Delay) { $dl = [string][int]$Job.Params.Delay }; if ($null -ne $Job.Params.Message) { $ms = [string]$Job.Params.Message } }
    return ('v2|{0}|{1}|{2}|{3}|{4}|{5}|{6}' -f [string]$Job.Id, [string]$Job.Action, ([string]$Job.Pc).ToUpper(), $ts, $dl, $ms, [string]$Job.Batch)
}
function Get-FdSig([byte[]]$Key, [string]$Canon) {
    $h = New-Object Security.Cryptography.HMACSHA256 -ArgumentList (, $Key)
    try { return [Convert]::ToBase64String($h.ComputeHash([Text.Encoding]::UTF8.GetBytes($Canon))) } finally { $h.Dispose() }
}

# ---- Aufträge senden (gleiches Format wie Send-FleetJob, plus Pc, Params, Batch, Sig)
function New-FdJob([string]$Pc, [string]$Action, [hashtable]$Params, [byte[]]$Key, [string]$Batch = '', [datetime]$Now = (Get-Date)) {
    $id = '{0:yyyyMMdd_HHmmss}_{1}' -f $Now, (Get-Random -Minimum 1000 -Maximum 99999)
    $p = [ordered]@{}
    if ($Params) { if ($Params.ContainsKey('Delay')) { $p.Delay = [int]$Params.Delay }; if ($Params.ContainsKey('Message')) { $p.Message = [string]$Params.Message } }
    $j = [pscustomobject]@{ Id = $id; Action = $Action; Pc = $Pc.ToUpper(); From = $env:COMPUTERNAME; User = $env:USERNAME; Time = $Now.ToString('o'); Params = [pscustomobject]$p; Batch = $Batch; V = 2; Sig = '' }
    if ($Key -and $Key.Length) { $j.Sig = Get-FdSig $Key (Get-FdJobCanon $j) }
    return $j
}
function Send-FdJob([string]$Dir, [string]$Pc, [string]$Action, [hashtable]$Params = @{}, [byte[]]$Key = $null, [string]$Batch = '') {
    if (-not $FleetActions.Contains($Action)) { throw ('Unbekannte Aktion: {0}' -f $Action) }
    if ($Pc -notmatch '^[A-Za-z0-9_\-\.]{1,63}$') { throw ('Ungültiger PC-Name: {0}' -f $Pc) }
    $Pc = $Pc.ToUpper()
    $d = Get-FleetJobDir $Dir $Pc
    New-Item $d -ItemType Directory -Force -ErrorAction Stop | Out-Null
    $j = New-FdJob $Pc $Action $Params $Key $Batch
    $f = Join-Path $d ($j.Id + '.json'); $tmp = Join-Path $d ($j.Id + '.tmp')
    $j | ConvertTo-Json -Depth 4 | Set-Content -LiteralPath $tmp -Encoding UTF8 -ErrorAction Stop
    Move-Item -LiteralPath $tmp -Destination $f -Force -ErrorAction Stop
    return $j.Id
}

# ---- Ordnerrechte: wer darf Aufträge ablegen? (reine Bewertung + Auslesen)
function Get-FdAclRisk($Rules) {
    $bad = [System.Collections.Generic.List[string]]::new()
    foreach ($r in @($Rules)) {
        if (-not $r -or [string]$r.Type -ne 'Allow') { continue }
        if ([string]$r.Rights -notmatch 'FullControl|Modify|Write|CreateFiles|AppendData|WriteData') { continue }
        $sid = [string]$r.Sid; $id = [string]$r.Identity
        $risky = ($sid -in 'S-1-1-0', 'S-1-5-11', 'S-1-5-32-545', 'S-1-5-32-546', 'S-1-5-7', 'S-1-5-4', 'S-1-5-2') -or ($sid -match '^S-1-5-21-.+-(513|514)$') -or
                 ((-not $sid) -and ($id -match '(?i)\\?(Everyone|Jeder|Users|Benutzer|Authenticated Users|Authentifizierte Benutzer|Domain Users|Domänen-Benutzer|Guests|Gäste|ANONYMOUS LOGON|INTERAKTIV|INTERACTIVE|NETWORK|NETZWERK)$'))
        if ($risky -and -not $bad.Contains($id)) { $bad.Add($id) }
    }
    return $bad.ToArray()
}
function Get-FdShareAclRisk([string]$Path) {
    $acl = Get-Acl -LiteralPath $Path -ErrorAction Stop
    $rules = foreach ($r in $acl.Access) {
        $sid = ''; try { $sid = $r.IdentityReference.Translate([Security.Principal.SecurityIdentifier]).Value } catch { }
        [pscustomobject]@{ Identity = [string]$r.IdentityReference; Sid = $sid; Rights = [string]$r.FileSystemRights; Type = [string]$r.AccessControlType }
    }
    Get-FdAclRisk $rules
}

# ---- Annahme-Prüfung eines Auftrags (zusätzlich zur Whitelist $FleetActions und der 3-Tage-Grenze)
function Test-FdJobAllowed($Job, [string]$Pc, [byte[]]$Key, [string]$KeyError = '', [string[]]$AclRisk = @(), [bool]$Strict = $false, [bool]$FbAvailable = $true, [datetime]$Now = (Get-Date)) {
    if (-not $FleetActions.Contains([string]$Job.Action)) { return 'unbekannte Aktion' }
    if ($Job.PSObject.Properties['Pc'] -and [string]$Job.Pc -and ([string]$Job.Pc).ToUpper() -ne $Pc.ToUpper()) { return ('Auftrag ist für {0} bestimmt, nicht für {1}' -f $Job.Pc, $Pc) }
    $t = Get-FdTime $Job.Time
    if (-not $t) { return 'Auftrag ohne gültige Zeit' }
    if (($t - $Now).TotalMinutes -gt 60) { return 'Auftragszeit liegt in der Zukunft (Uhr des sendenden PCs prüfen)' }
    if ($KeyError) { return ('Auftragsschlüssel auf diesem PC nicht lesbar ({0}) - aus Sicherheitsgründen wird nichts ausgeführt' -f $KeyError) }
    if ($Key -and $Key.Length) {
        $sig = [string]$Job.Sig
        if (-not $sig) { return 'Auftrag ohne Signatur - dieser PC nimmt nur signierte Aufträge an (Auftragsschlüssel)' }
        $exp = Get-FdSig $Key (Get-FdJobCanon $Job)
        if ($sig -ne $exp) { return 'Signatur ungültig - Auftragsschlüssel auf dem sendenden PC passt nicht oder der Auftrag wurde verändert' }
    }
    if ($Strict -and @($AclRisk).Count) { return ('Ordnerrechte zu offen ({0} dürfen schreiben) - "Nur bei sicheren Ordnerrechten" ist eingeschaltet' -f (@($AclRisk) -join ', ')) }
    if ([string]$Job.Action -eq 'Komplettsicherung' -and -not $FbAvailable) { return 'Komplettsicherung ist in dieser PC-Tools-Version nicht verfügbar - zuerst "PC-Tools aktualisieren" senden' }
    if ([string]$Job.Action -in 'Neustart', 'Aus' -and $Job.Params -and $null -ne $Job.Params.Delay) {
        $dl = 0; if (-not [int]::TryParse([string]$Job.Params.Delay, [ref]$dl) -or $dl -lt 1 -or $dl -gt 240) { return 'Wartezeit für Neustart/Herunterfahren muss 1 bis 240 Minuten sein' }
    }
    return ''
}

# ---- Neustart / Herunterfahren mit Wartezeit und Nachricht (msg.exe + shutdown.exe)
function Get-FdShutdownPlan($Params, [string]$From, [string]$Kind = 'r') {
    $min = 5
    if ($Params -and $null -ne $Params.Delay -and [string]$Params.Delay -ne '') { $x = 0; if ([int]::TryParse([string]$Params.Delay, [ref]$x)) { $min = $x } }
    if ($min -lt 1) { $min = 1 }; if ($min -gt 240) { $min = 240 }
    $txt = ''; if ($Params -and $Params.Message) { $txt = [string]$Params.Message }
    $txt = (($txt -replace '[\x00-\x1F"%^&|<>]', ' ') -replace '\s{2,}', ' ').Trim()
    if ($txt.Length -gt 200) { $txt = $txt.Substring(0, 200) }
    if (-not $txt) { $txt = 'Bitte speichere deine Arbeit.' }
    $from2 = ($From -replace '[^A-Za-z0-9_\-\. ]', '').Trim(); if (-not $from2) { $from2 = 'Meine PCs' }
    $what = if ($Kind -eq 's') { 'heruntergefahren' } else { 'neu gestartet' }
    $msg = 'PC-Tools: Dieser PC wird in {0} {1} {2} (angefordert von {3}). {4}' -f $min, $(if ($min -eq 1) { 'Minute' } else { 'Minuten' }), $what, $from2, $txt
    $cmt = $msg + ' Abbrechen: shutdown /a'
    if ($cmt.Length -gt 500) { $cmt = $cmt.Substring(0, 500) }
    [pscustomobject]@{ Minutes = $min; Seconds = $min * 60; Switch = $(if ($Kind -eq 's') { 's' } else { 'r' }); Message = $msg; Comment = $cmt; What = $what }
}
function Invoke-FdShutdown($Job, [string]$Kind) {
    $plan = Get-FdShutdownPlan $Job.Params ([string]$Job.From) $Kind
    $sys = if (Test-Path (Join-Path $env:windir 'Sysnative')) { Join-Path $env:windir 'Sysnative' } else { Join-Path $env:windir 'System32' }
    $msgInfo = 'Nachricht über die Windows-Meldung von shutdown.exe'
    $msgExe = Join-Path $sys 'msg.exe'
    if (Test-Path -LiteralPath $msgExe) {
        try { $null = & $msgExe '*' ('/TIME:{0}' -f $plan.Seconds) $plan.Message 2>&1; if ($LASTEXITCODE -eq 0) { $msgInfo = 'Nachricht per msg.exe an alle angemeldeten Benutzer' } } catch { }
    }
    $null = & (Join-Path $sys 'shutdown.exe') ('/' + $plan.Switch) '/t' ([string]$plan.Seconds) '/c' $plan.Comment '/d' 'p:0:0' 2>&1
    if ($LASTEXITCODE -eq 1190) { throw 'Es ist bereits ein Neustart/Herunterfahren geplant - zuerst "Neustart abbrechen" senden.' }
    if ($LASTEXITCODE -ne 0) { throw ('shutdown.exe meldet Fehler {0}' -f $LASTEXITCODE) }
    return ('Wird in {0} Min. {1} - {2}' -f $plan.Minutes, $plan.What, $msgInfo)
}

# ---- Selbsttest ohne Oberfläche (gleiche Prüfungen wie Einstellungen > Selbsttest, plus Fernwartung)
function Get-FdSelfTestRows([hashtable]$A) {
    $rows = [System.Collections.Generic.List[object]]::new()
    $R = { param([string]$Area, [string]$Level, [string]$State, [string]$Detail) $rows.Add([pscustomobject]@{ Area = $Area; State = $State; Detail = $Detail; Level = $Level }) }
    $psv = $PSVersionTable.PSVersion
    & $R 'PowerShell' $(if ($psv.Major -eq 5 -and $psv.Minor -ge 1) { 'Good' } else { 'Warn' }) ('{0}' -f $psv) $(if ($psv.Major -eq 5) { 'Windows PowerShell 5.1 - passt.' } else { 'PC-Tools ist für Windows PowerShell 5.1 gebaut.' })
    $rel = 0; try { $rel = [int](Get-ItemProperty 'HKLM:\SOFTWARE\Microsoft\NET Framework Setup\NDP\v4\Full' -ErrorAction Stop).Release } catch { }
    & $R '.NET Framework' $(if ($rel -ge 461808) { 'Good' } else { 'Warn' }) $(if ($rel -ge 528040) { '4.8' } elseif ($rel -ge 461808) { '4.7.2' } else { 'alt' }) 'Wird für Oberfläche und Downloads gebraucht (ab 4.7.2).'
    $adm = $false; try { $adm = ([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator) } catch { }
    & $R 'Administratorrechte' $(if ($adm) { 'Good' } else { 'Error' }) $(if ($adm) { 'ja' } else { 'nein' }) ('Konto: {0}' -f $(try { [Security.Principal.WindowsIdentity]::GetCurrent().Name } catch { $env:USERNAME }))
    $wr = $false; try { $tf = Join-Path $A.DataDir ('selftest-{0}.tmp' -f $PID); Set-Content -LiteralPath $tf -Value 'x' -ErrorAction Stop; Remove-Item -LiteralPath $tf -Force; $wr = $true } catch { }
    & $R 'Datenordner' $(if ($wr) { 'Good' } else { 'Error' }) $(if ($wr) { 'beschreibbar' } else { 'NICHT beschreibbar' }) $A.DataDir
    try { $dr = New-Object IO.DriveInfo ([IO.Path]::GetPathRoot($A.DataDir)); $gb = $dr.AvailableFreeSpace / 1GB; & $R 'Freier Speicher' $(if ($gb -ge 10) { 'Good' } elseif ($gb -ge 3) { 'Warn' } else { 'Error' }) ('{0:N1} GB frei auf {1}' -f $gb, $dr.Name) 'Unter 3 GB scheitern Updates und Downloads.' } catch { }
    $cfgOk = $false; $cfgMsg = 'fehlt (Standardwerte)'
    if (Test-Path -LiteralPath $A.ConfigFile) { try { $null = Get-Content -LiteralPath $A.ConfigFile -Raw -Encoding UTF8 | ConvertFrom-Json -ErrorAction Stop; $cfgOk = $true; $cfgMsg = 'gültig' } catch { $cfgMsg = 'BESCHÄDIGT' } }
    & $R 'Einstellungen (config.json)' $(if ($cfgOk) { 'Good' } elseif ($cfgMsg -like 'fehlt*') { 'Warn' } else { 'Error' }) $cfgMsg $(if (Test-Path -LiteralPath ($A.ConfigFile + '.bak')) { 'Sicherungskopie config.json.bak vorhanden.' } else { 'Noch keine Sicherungskopie (entsteht beim nächsten Speichern).' })
    $scr = Join-Path $A.DataDir 'PCPflege.ps1'; if (-not (Test-Path -LiteralPath $scr)) { $scr = $A.Script }
    try { $t0 = $null; $e0 = $null; [void][System.Management.Automation.Language.Parser]::ParseFile($scr, [ref]$t0, [ref]$e0); & $R 'Programmdatei' $(if (@($e0).Count) { 'Error' } else { 'Good' }) $(if (@($e0).Count) { '{0} Fehler' -f @($e0).Count } else { 'fehlerfrei' }) $scr } catch { & $R 'Programmdatei' 'Warn' 'nicht prüfbar' $_.Exception.Message }
    if ($A.Portable) { & $R 'Zeitplan' 'Good' 'portabel' 'Vom Stick gibt es keinen Zeitplan.' } else {
        $tk = $null; try { $tk = Get-ScheduledTask -TaskName $A.Task -ErrorAction Stop } catch { }
        if (-not $tk) { & $R 'Zeitplan' 'Warn' 'nicht eingerichtet' 'Automatische Pflege ist aus oder die Aufgabe fehlt (Einstellungen speichern richtet sie ein).' }
        else {
            $argx = [string]$tk.Actions[0].Arguments; $tp = ''; if ($argx -match '-File "([^"]+)"') { $tp = $Matches[1] }
            $info = $null; try { $info = Get-ScheduledTaskInfo -TaskName $A.Task -ErrorAction Stop } catch { }
            $res = if ($info) { [int64]$info.LastTaskResult } else { -1 }
            $okRes = $res -in 0, 267011, 267009
            & $R 'Zeitplan' $(if ($tp -and -not (Test-Path -LiteralPath $tp)) { 'Error' } elseif ($okRes) { 'Good' } else { 'Warn' }) $(if ($info -and $info.LastRunTime -and $info.LastRunTime.Year -gt 2000) { 'zuletzt {0:dd.MM.yyyy HH:mm}' -f $info.LastRunTime } else { 'noch nicht gelaufen' }) $(if ($tp -and -not (Test-Path -LiteralPath $tp)) { 'Die Aufgabe zeigt auf eine fehlende Datei - Einstellungen einmal speichern.' } elseif (-not $okRes) { 'Letztes Ergebnis 0x{0:X} - Protokoll ansehen.' -f $res } else { 'Nächster Lauf: ' + $(if ($info -and $info.NextRunTime) { $info.NextRunTime.ToString('dd.MM.yyyy HH:mm') } else { '-' }) })
        }
    }
    & $R 'Update-Quelle' $(if (-not $A.SrcVer) { 'Warn' } else { 'Good' }) $(if ($A.SrcVer) { 'erreichbar, Version ' + $A.SrcVer } else { 'nicht erreichbar/nicht geprüft' }) ('Installiert: {0}' -f $A.Ver)
    & $R 'Vorversion (Rückfall)' $(if ($A.Vor) { 'Good' } else { 'Warn' }) $(if ($A.Vor) { $A.Vor } else { 'keine' }) 'Wird bei jedem Update automatisch gesichert. Startet eine neue Version zweimal nicht, geht PC-Tools selbst zurück.'
    $wg = $null; try { $wg = Get-Command winget.exe -ErrorAction Stop } catch { }
    if (-not $wg) { $wg = Get-ChildItem -Path (Join-Path $env:ProgramFiles 'WindowsApps') -Filter 'winget.exe' -Recurse -ErrorAction SilentlyContinue | Select-Object -First 1 }
    & $R 'winget' $(if ($wg) { 'Good' } else { 'Warn' }) $(if ($wg) { 'vorhanden' } else { 'fehlt (als SYSTEM oft nicht sichtbar)' }) 'Für Programm-Updates und den Software-Kiosk (App-Installer aus dem Store).'
    try { $ls = [int64]0; Get-ChildItem -LiteralPath (Join-Path $A.DataDir 'Logs') -File -Recurse -ErrorAction SilentlyContinue | ForEach-Object { $ls += $_.Length }; & $R 'Protokolle' $(if ($ls -gt 500MB) { 'Warn' } else { 'Good' }) ('{0:N0} MB' -f ($ls / 1MB)) 'Alte Protokolle räumt die Pflege automatisch auf.' } catch { }
    $el = Join-Path (Join-Path $A.DataDir 'Logs') 'Oberflaeche-Fehler.log'; $ec = 0
    if (Test-Path -LiteralPath $el) { $lim = (Get-Date).AddDays(-7).ToString('yyyy-MM-dd'); $ec = @(Get-Content -LiteralPath $el -Encoding UTF8 | Where-Object { $_ -match '^(\d{4}-\d{2}-\d{2})' -and $Matches[1] -ge $lim }).Count }
    & $R 'Abgefangene Fehler (7 Tage)' $(if ($ec -eq 0) { 'Good' } elseif ($ec -lt 5) { 'Warn' } else { 'Error' }) ([string]$ec) $(if ($ec) { 'Fehlerprotokoll ansehen und an den Entwickler schicken.' } else { 'keine' })
    & $R 'Ansicht' 'Good' $(if ($A.Lite) { 'Lite' } else { 'Voll' }) 'Umschaltbar unter Einstellungen > Stabilität.'
    # Fernwartung
    $pt = $null; try { $pt = Get-ScheduledTask -TaskName 'PC-Pflege Fernaufträge' -ErrorAction Stop } catch { }
    & $R 'Fernaufträge-Aufgabe' $(if ($pt) { 'Good' } else { 'Warn' }) $(if ($pt) { 'eingerichtet' } else { 'fehlt' }) 'Prüft alle 10 Minuten auf Aufträge und schreibt das Lebenszeichen.'
    & $R 'Auftragsschlüssel' $(if ($A.KeyError) { 'Error' } elseif ($A.KeyFp) { 'Good' } else { 'Warn' }) $(if ($A.KeyError) { 'unlesbar' } elseif ($A.KeyFp) { 'aktiv (' + $A.KeyFp + ')' } else { 'keiner' }) $(if ($A.KeyFp) { 'Nur signierte Aufträge werden angenommen.' } else { 'Ohne Schlüssel nimmt der PC jeden Auftrag aus dem Ordner an - Schlüssel auf der Seite Meine PCs festlegen.' })
    if ($A.AclRisk) { & $R 'Ordnerrechte Aufträge' 'Warn' 'zu offen' ('Schreiben dürfen: ' + $A.AclRisk) } elseif ($A.AclChecked) { & $R 'Ordnerrechte Aufträge' 'Good' 'nur berechtigte Konten' 'Keine allgemeinen Gruppen (Jeder, Benutzer ...) mit Schreibrecht gefunden.' }
    return , $rows
}
function Invoke-FdSelfTestJob($Cfg) {
    $src = ''; try { $m = Get-UpdateManifest ([string]$Cfg.Settings.UpdateSource); if ($m) { $src = [string]$m.Version } } catch { }
    $fp = ''; $ke = ''; try { $fp = [string](Get-FdKeyFingerprint) } catch { $ke = $_.Exception.Message }
    $risk = ''; $chk = $false
    try { $jd = Get-FleetJobDir ([string]$Cfg.Fleet.Dir) $env:COMPUTERNAME; if (Test-Path -LiteralPath $jd) { $risk = (@(Get-FdShareAclRisk $jd) -join ', '); $chk = $true } } catch { }
    $a = @{ DataDir = $DataDir; ConfigFile = $ConfigFile; Task = $TaskName; Ver = $AppVersion; SrcVer = $src; Script = $PSCommandPath; Vor = [string](Get-PflegeVorversion); Lite = [bool]$Script:IsLite; Portable = [bool]$Script:IsPortable; KeyFp = $fp; KeyError = $ke; AclRisk = $risk; AclChecked = $chk }
    $rows = @(Get-FdSelfTestRows $a | ForEach-Object { $_ })
    $bad = @($rows | Where-Object { $_.Level -eq 'Error' }).Count; $warn = @($rows | Where-Object { $_.Level -eq 'Warn' }).Count
    $msg = if ($bad) { '{0} Problem(e), {1} Hinweis(e): {2}' -f $bad, $warn, ((@($rows | Where-Object { $_.Level -eq 'Error' }) | ForEach-Object { $_.Area }) -join ', ') } elseif ($warn) { 'Alles läuft - {0} Hinweis(e): {1}' -f $warn, ((@($rows | Where-Object { $_.Level -eq 'Warn' }) | ForEach-Object { $_.Area }) -join ', ') } else { 'Alles in Ordnung ({0} Prüfungen)' -f $rows.Count }
    [pscustomobject]@{ Message = $msg; Data = @($rows | ForEach-Object { [pscustomobject]@{ Area = [string]$_.Area; State = [string]$_.State; Detail = [string]$_.Detail; Level = [string]$_.Level } }) }
}

# ---- Notfall-Stick-Status (eingesteckte Sticks + letzte Erstellung laut Protokoll)
function Get-FdStickVerdict($Stamp, [bool]$Bootable, [datetime]$Now) {
    $cr = Get-FdTime $(if ($Stamp) { $Stamp.Created } else { $null })
    if (-not $Bootable) { return [pscustomobject]@{ State = 'nicht bootfähig'; Level = 'Error' } }
    if (-not $cr) { return [pscustomobject]@{ State = 'Alter unbekannt'; Level = 'Warn' } }
    if (($Now - $cr).TotalDays -gt 180) { return [pscustomobject]@{ State = ('veraltet (vom {0:dd.MM.yyyy})' -f $cr); Level = 'Warn' } }
    return [pscustomobject]@{ State = ('aktuell (vom {0:dd.MM.yyyy})' -f $cr); Level = 'Good' }
}
function Get-FdRescueStickStatus {
    $rows = [System.Collections.Generic.List[object]]::new()
    $now = Get-Date
    if (Get-Command Get-FbStickState -ErrorAction SilentlyContinue) {
        foreach ($s in @(Get-FbStickState | ForEach-Object { $_ })) {
            $rows.Add([pscustomobject]@{ Area = ('Stick {0} ({1})' -f $s.Root, $s.Name); State = $(if ($s.Outdated) { 'veraltet' } else { 'aktuell' }); Detail = [string]$s.Reason; Level = $(if ($s.Outdated) { 'Warn' } else { 'Good' }) })
        }
    } else {
        $disks = @(); try { $disks = @(Get-Disk -ErrorAction Stop | Where-Object { [string]$_.BusType -eq 'USB' -and -not $_.IsBoot -and -not $_.IsSystem }) } catch { }
        foreach ($dk in $disks) {
            $roots = @(Get-Partition -DiskNumber $dk.Number -ErrorAction SilentlyContinue | Where-Object { $_.DriveLetter -and [int][char]$_.DriveLetter -ne 0 } | Sort-Object PartitionNumber | ForEach-Object { '{0}:\' -f $_.DriveLetter })
            $stamp = $null; foreach ($r in $roots) { $sf = Join-Path $r 'PC-Tools-Stick.json'; if (Test-Path -LiteralPath $sf) { try { $stamp = Get-Content -LiteralPath $sf -Raw -Encoding UTF8 | ConvertFrom-Json } catch { } } }
            if (-not $stamp) { continue }
            $rep = @(); try { $rep = @(Get-RsStickReport $roots | ForEach-Object { $_ }) } catch { }
            $bi = @($rep | Where-Object { $_.Item -match 'boot\.wim|boot\.sdi|Start-Manager|Startkonfiguration' })
            $boot = ($bi.Count -ge 4) -and -not @($bi | Where-Object { $_.Level -eq 'bad' }).Count
            $v = Get-FdStickVerdict $stamp $boot $now
            $rows.Add([pscustomobject]@{ Area = ('Stick {0} ({1})' -f ($roots -join ' '), $dk.FriendlyName); State = $v.State; Detail = ('erstellt auf {0} mit PC-Tools {1}; {2} Bestandteile vorhanden, {3} fehlen' -f $stamp.Computer, $stamp.AppVersion, @($rep | Where-Object Level -eq 'ok').Count, @($rep | Where-Object Level -eq 'bad').Count); Level = $v.Level })
        }
    }
    $last = $null
    foreach ($fi in @(Get-ChildItem (Join-Path $DataDir 'Logs') -Filter '*.log' -File -ErrorAction SilentlyContinue | Sort-Object LastWriteTime -Descending | Select-Object -First 200)) {
        if (Select-String -LiteralPath $fi.FullName -Pattern 'Notfall-Stick fertig' -Quiet -ErrorAction SilentlyContinue) { $last = $fi.LastWriteTime; break }
    }
    $rows.Add([pscustomobject]@{ Area = 'Zuletzt auf diesem PC erstellt'; State = $(if ($last) { $last.ToString('dd.MM.yyyy') } else { 'nicht im Protokoll' }); Detail = 'laut Protokollen von PC-Tools'; Level = $(if ($last -and ($now - $last).TotalDays -le 180) { 'Good' } else { 'Warn' }) })
    $sticks = @($rows | Where-Object { $_.Area -like 'Stick *' })
    $msg = if ($sticks.Count) { '{0} Notfall-Stick(s) eingesteckt: {1}' -f $sticks.Count, ((@($sticks) | ForEach-Object { '{0} {1}' -f $_.Area, $_.State }) -join '; ') } else { 'Kein Notfall-Stick eingesteckt. Zuletzt erstellt: {0}' -f $(if ($last) { $last.ToString('dd.MM.yyyy') } else { 'unbekannt' }) }
    $info = [pscustomobject]@{ Time = $now.ToString('o'); Count = $sticks.Count; Ok = [bool]($sticks.Count -and -not @($sticks | Where-Object { $_.Level -ne 'Good' }).Count); LastCreated = $(if ($last) { $last.ToString('o') } else { '' }); Text = $msg }
    try { $info | ConvertTo-Json | Set-Content -LiteralPath (Join-Path $DataDir 'fd-notfallstick.json') -Encoding UTF8 } catch { }
    [pscustomobject]@{ Message = $msg; Data = @($rows) }
}

# ---- Daten aus dem gemeinsamen Ordner lesen (eigenständig: läuft auch in Invoke-Bg)
function Read-FdFleetData([string]$Dir, [int]$MaxJobs = 40) {
    if (-not $Dir -or -not (Test-Path -LiteralPath $Dir)) { throw ('Der gemeinsame Ordner ist nicht erreichbar: {0}' -f $Dir) }
    $rd = { param($p) try { Get-Content -LiteralPath $p -Raw -Encoding UTF8 -ErrorAction Stop | ConvertFrom-Json } catch { $null } }
    $status = [System.Collections.Generic.List[object]]::new()
    foreach ($fi in @(Get-ChildItem -LiteralPath $Dir -Filter '*.json' -File -ErrorAction SilentlyContinue)) {
        $o = & $rd $fi.FullName
        if ($o -and $o.PSObject.Properties['Computer'] -and [string]$o.Computer) { $status.Add($o) }
    }
    $beats = @{}
    foreach ($fi in @(Get-ChildItem -LiteralPath (Join-Path $Dir 'Heartbeat') -Filter '*.json' -File -ErrorAction SilentlyContinue)) {
        $o = & $rd $fi.FullName
        if ($o -and [string]$o.Computer) { $beats[([string]$o.Computer).ToUpper()] = $o }
    }
    $seen = @{}; $jobs = [System.Collections.Generic.List[object]]::new()
    foreach ($pd in @(Get-ChildItem -LiteralPath (Join-Path $Dir 'Auftraege') -Directory -ErrorAction SilentlyContinue)) {
        $pcName = [string]$pd.Name
        $sf = Join-Path $pd.FullName 'online.txt'
        if (Test-Path -LiteralPath $sf) { try { $seen[$pcName.ToUpper()] = ([string](Get-Content -LiteralPath $sf -Raw -ErrorAction Stop)).Trim() } catch { } }
        $files = @(Get-ChildItem -LiteralPath $pd.FullName -Filter '*.json' -File -ErrorAction SilentlyContinue | Where-Object { $_.Name -notlike '*.result.json' } | Sort-Object Name -Descending | Select-Object -First $MaxJobs)
        foreach ($fi in $files) {
            $j = & $rd $fi.FullName
            if (-not $j -or -not [string]$j.Id) { continue }
            $r = $null; $rf = Join-Path $pd.FullName ([string]$j.Id + '.result.json'); if (Test-Path -LiteralPath $rf) { $r = & $rd $rf }
            $jobs.Add([pscustomobject]@{
                    Pc = $pcName.ToUpper(); Id = [string]$j.Id; Action = [string]$j.Action; From = [string]$j.From; User = [string]$j.User; Time = $j.Time
                    Params = $(if ($j.PSObject.Properties['Params']) { $j.Params } else { $null }); Batch = $(if ($j.PSObject.Properties['Batch']) { [string]$j.Batch } else { '' }); Signed = [bool]($j.PSObject.Properties['Sig'] -and [string]$j.Sig); File = $fi.FullName
                    State = $(if ($r) { [string]$r.State } else { '' }); Start = $(if ($r) { $r.Start } else { $null }); End = $(if ($r) { $r.End } else { $null }); Message = $(if ($r) { [string]$r.Message } else { '' })
                    Data = $(if ($r -and $r.PSObject.Properties['Data']) { $r.Data } else { $null }) })
        }
    }
    $help = @{}; try { $help = Read-FdHelpRequests $Dir } catch { }
    [pscustomobject]@{ Status = $status.ToArray(); Beats = $beats; Seen = $seen; Jobs = $jobs.ToArray(); Help = $help; Time = (Get-Date) }
}

# ---- Aufbereitung für Tabellen und Kacheln (rein, testbar)
function Get-FdJobState($Job, [datetime]$Now) {
    $s = [string]$Job.State
    $age = 0; $t = Get-FdTime $Job.Time; if ($t) { $age = ($Now - $t).TotalHours }
    if (-not $s) {
        if ($age -gt 72) { return [pscustomobject]@{ Key = 'failed'; Text = 'nicht abgeholt'; Level = 'Off'; Sort = 4; Open = $false } }
        return [pscustomobject]@{ Key = 'queued'; Text = 'wartet'; Level = ''; Sort = 1; Open = $true }
    }
    if ($s -eq 'läuft') {
        $st = Get-FdTime $Job.Start; $run = if ($st) { ($Now - $st).TotalHours } else { 0 }
        if ($run -gt 9) { return [pscustomobject]@{ Key = 'failed'; Text = 'hängt (abgebrochen?)'; Level = 'Error'; Sort = 3; Open = $false } }
        return [pscustomobject]@{ Key = 'running'; Text = 'läuft'; Level = 'Warn'; Sort = 0; Open = $true }
    }
    if ($s -eq 'fertig') { return [pscustomobject]@{ Key = 'done'; Text = 'fertig'; Level = 'Good'; Sort = 5; Open = $false } }
    if ($s -eq 'abgelaufen') { return [pscustomobject]@{ Key = 'failed'; Text = 'abgelaufen'; Level = 'Off'; Sort = 4; Open = $false } }
    if ($s -eq 'abgelehnt') { return [pscustomobject]@{ Key = 'failed'; Text = 'abgelehnt'; Level = 'Error'; Sort = 2; Open = $false } }
    return [pscustomobject]@{ Key = 'failed'; Text = $(if ($s -eq 'Fehler') { 'Fehler' } else { $s }); Level = 'Error'; Sort = 2; Open = $false }
}
function Get-FdShortAction([string]$Action) {
    $m = @{ Pflege = 'Pflege'; Updates = 'Updates'; Aufraeumen = 'Aufräumen'; Sicherung = 'Sicherung'; Virenscan = 'Virenscan'; Selbstupdate = 'Selbstupdate'; Neustart = 'Neustart'; Aus = 'Herunterfahren'; Abbruch = 'Abbruch'; Status = 'Zustand'; Selbsttest = 'Selbsttest'; NotfallStick = 'Notfall-Stick'; Komplettsicherung = 'Komplettsicherung' }
    if ($m.ContainsKey($Action)) { return $m[$Action] }
    return $Action
}
function ConvertTo-FdJobRow($Job, [datetime]$Now) {
    $st = Get-FdJobState $Job $Now
    $t = Get-FdTime $Job.Time; $e = Get-FdTime $Job.End; $b = Get-FdTime $Job.Start
    $lab = if ($FleetActions.Contains([string]$Job.Action)) { [string]$FleetActions[[string]$Job.Action] } else { [string]$Job.Action }
    if ([string]$Job.Action -in 'Neustart', 'Aus' -and $Job.Params -and $null -ne $Job.Params.Delay) { $lab = '{0} - {1} Min.' -f $(if ($Job.Action -eq 'Aus') { 'Herunterfahren' } else { 'Neustart' }), [int]$Job.Params.Delay }
    $dur = ''; if ($b -and $e) { $m = ($e - $b).TotalMinutes; $dur = if ($m -lt 1) { '< 1 Min.' } elseif ($m -lt 120) { '{0:N0} Min.' -f $m } else { '{0:N1} Std.' -f ($m / 60) } }
    [pscustomobject]@{
        Pc = [string]$Job.Pc; Id = [string]$Job.Id; Action = [string]$Job.Action; ActionText = $lab; From = [string]$Job.From
        TimeText = $(if ($t) { $t.ToString('dd.MM. HH:mm') } else { '' }); TimeSort = $(if ($t) { $t.ToString('yyyyMMddHHmmss') } else { '' })
        EndText = $(if ($e) { $e.ToString('dd.MM. HH:mm') } else { '' }); EndSort = $(if ($e) { $e.ToString('yyyyMMddHHmmss') } else { '' })
        StateKey = $st.Key; StateText = $st.Text; StateSort = $st.Sort; Open = $st.Open; Level = $st.Level; DurText = $dur
        Message = [string]$Job.Message; HasData = [bool]($null -ne $Job.Data); Data = $Job.Data; File = [string]$Job.File; Signed = [bool]$Job.Signed; Params = $Job.Params; EndTime = $e
    }
}
function ConvertTo-FdPcRow($S, $Beat, [string]$SeenTxt, $JobRows, [datetime]$Now, [int]$OnlineMin = 25, [string]$LocalFp = '') {
    $pc = if ($S) { [string]$S.Computer } elseif ($Beat) { [string]$Beat.Computer } else { '' }
    $hasBeat = [bool]($Beat -or $SeenTxt)
    $last = Get-FdLastSeen @($(if ($S) { $S.Time } else { $null }), $(if ($Beat) { $Beat.Time } else { $null }), $SeenTxt)
    $on = Get-FdOnlineState $last $Now $OnlineMin $hasBeat
    $p = { param($n) if ($S -and $S.PSObject.Properties[$n]) { $S.$n } else { $null } }
    $sh = & $p 'ScoreHist'; $shArr = @(); if ($null -ne $sh) { $shArr = @(@($sh) | Where-Object { $null -ne $_ }) }
    $state = [string](& $p 'State')
    $score = & $p 'Score'; $scoreN = -1; if ($null -ne $score) { try { $scoreN = [int]$score } catch { } }
    $wu = & $p 'WuPending'; $wuN = -1; if ($null -ne $wu) { try { $wuN = [int]$wu } catch { } }
    $err = & $p 'Errors24h'; $errN = -1; if ($null -ne $err) { try { $errN = [int]$err } catch { } }
    $upH = & $p 'UptimeH'; if ($Beat -and $null -ne $Beat.UptimeH) { $upH = $Beat.UptimeH }
    $upN = -1.0; if ($null -ne $upH) { try { $upN = [double]$upH } catch { } } elseif ($null -ne (& $p 'Uptime')) { try { $upN = [double](& $p 'Uptime') * 24 } catch { } }
    $reboot = [bool](& $p 'RebootPending'); if ($Beat -and $null -ne $Beat.RebootPending) { $reboot = [bool]$Beat.RebootPending }
    $ver = [string](& $p 'Version'); if ($Beat -and [string]$Beat.Version) { $ver = [string]$Beat.Version }
    $ed = [string](& $p 'Edition'); if ($Beat -and [string]$Beat.Edition) { $ed = [string]$Beat.Edition }
    $free = & $p 'DiskFreeGB'; $freeN = -1.0; if ($null -ne $free) { try { $freeN = [double]$free } catch { } }
    $pct = & $p 'DiskFreePct'
    $bst = [string](& $p 'BackupState')
    $fb = & $p 'FullBackup'
    $ak = & $p 'Akte'
    $jr = @(@($JobRows) | Where-Object { $_ })
    $jq = @($jr | Where-Object { $_.StateKey -eq 'queued' }).Count; $jrun = @($jr | Where-Object { $_.StateKey -eq 'running' }).Count
    $jf = @($jr | Where-Object { $_.StateKey -eq 'failed' -and $_.Level -eq 'Error' -and $_.EndTime -and ($Now - $_.EndTime).TotalHours -le 24 }).Count
    $jtxt = @(); if ($jrun) { $jtxt += ('{0} läuft' -f $jrun) }; if ($jq) { $jtxt += ('{0} wartet' -f $jq) }; if ($jf) { $jtxt += ('{0} Fehler' -f $jf) }
    if (-not $jtxt.Count -and $jr.Count) { $l = @($jr | Sort-Object TimeSort -Descending)[0]; $jtxt += ('zuletzt: {0} {1}' -f (Get-FdShortAction $l.Action), $l.StateText) }
    $kfp = [string](& $p 'KeyFp')
    $keyText = if (-not $kfp) { 'ohne' } elseif ($kfp -eq 'Fehler') { 'Fehler' } elseif ($LocalFp -and $kfp -eq $LocalFp) { 'passt' } elseif ($LocalFp) { 'anderer Schlüssel' } else { 'aktiv' }
    $bad = ($state -in 'Red', 'Yellow') -or (-not $on.Online) -or $reboot -or ($bst -eq 'Fehler') -or ($jf -gt 0) -or ($fb -and [string]$fb.LastResult -eq 'Fehler')
    $lvl = if ($on.State -in 'lange', 'nie') { 'Off' } elseif ($state -eq 'Red') { 'Error' } elseif ($state -eq 'Yellow') { 'Warn' } elseif (-not $on.Online) { 'Off' } else { '' }
    [pscustomobject]@{
        Computer = $pc; OnlineState = $on.State; Online = $on.Online; OnlineText = $on.Text; OnlineSort = $on.Sort; LastSeen = $last; AgeMin = $on.AgeMin; HasBeat = $hasBeat
        SeenText = $(Get-FdAgeText $on.AgeMin); SeenSort = $on.AgeMin
        State = $state; StateText = $(switch ($state) { 'Red' { 'rot' } 'Yellow' { 'gelb' } 'Green' { 'grün' } default { '-' } }); StateSort = $(switch ($state) { 'Red' { 0 } 'Yellow' { 1 } 'Green' { 2 } default { 3 } })
        ScoreText = $(if ($scoreN -ge 0) { [string]$scoreN } else { '-' }); ScoreSort = $scoreN; ScoreHist = $shArr
        Build = $(if ([string](& $p 'WinBuild')) { '{0} ({1})' -f (& $p 'WinBuild'), (& $p 'WinDisplay') } else { [string](& $p 'Windows') -replace '^.*\(Build ([\d\.]+)\).*$', '$1' })
        VerText = $(if ($ver) { ('{0} {1}' -f $ver, $ed).Trim() } else { '-' }); Version = $ver; Edition = $ed
        RebootPending = $reboot; RebootText = $(if ($reboot) { 'nötig' } else { '' })
        WuText = $(if ($wuN -gt 0) { [string]$wuN } elseif ($wuN -eq 0) { 'keine' } else { '-' }); WuSort = $wuN
        FreeText = $(if ($freeN -ge 0) { '{0:N0} GB{1}' -f $freeN, $(if ($null -ne $pct -and [int]$pct -ge 0) { ' ({0} %)' -f [int]$pct } else { '' }) } else { '-' }); FreeSort = $freeN
        UptimeText = $(if ($upN -lt 0) { '-' } elseif ($upN -lt 48) { '{0:N0} Std.' -f $upN } else { '{0:N0} Tage' -f ($upN / 24) }); UptimeSort = $upN
        ErrText = $(if ($errN -ge 0) { [string]$errN } else { '-' }); ErrSort = $errN
        BackupState = $bst; BackupText = $(switch ($bst) { 'Fehler' { 'Fehler' } 'alt' { 'veraltet' } 'ok' { 'ok' } 'nie' { 'noch nie' } 'aus' { 'aus' } default { '-' } }) + $(if ([string](& $p 'BackupText') -and $bst -in 'ok', 'alt', 'Fehler') { ' · ' + [string](& $p 'BackupText') } else { '' })
        BackupSort = $(switch ($bst) { 'Fehler' { 0 } 'alt' { 1 } 'nie' { 2 } 'ok' { 4 } default { 3 } })
        FullBackup = $fb; FullText = $(if ($fb) { $x = switch ([string]$fb.State) { 'ok' { 'ok' } 'due' { 'fällig' } 'overdue' { 'überfällig' } 'never' { 'noch nie' } default { [string]$fb.State } }; if ([string]$fb.LastResult -eq 'Fehler') { 'Fehler' } else { $x } } else { '-' })
        JobText = ($jtxt -join ' · '); JobsOpen = ($jq + $jrun); JobsFailed = $jf
        KeyText = $keyText; KeyFp = $kfp
        AkStandort = $(if ($ak) { [string]$ak.Standort } else { '' }); AkBesitzer = $(if ($ak) { [string]$ak.Besitzer } else { '' })
        User = $(if ($Beat -and $Beat.User) { [string]$Beat.User } else { [string](& $p 'User') }); Model = [string](& $p 'Model'); IP = [string](& $p 'IP')
        Problem = [bool]$bad; Level = $lvl; Raw = $S; Beat = $Beat
    }
}
function Get-FdRows($Data, [datetime]$Now, [int]$OnlineMin = 25, [string]$LocalFp = '') {
    $byPc = @{}
    foreach ($j in @($Data.Jobs)) { if (-not $j) { continue }; $k = ([string]$j.Pc).ToUpper(); if (-not $byPc.ContainsKey($k)) { $byPc[$k] = [System.Collections.Generic.List[object]]::new() }; $byPc[$k].Add((ConvertTo-FdJobRow $j $Now)) }
    $done = @{}
    foreach ($s in @($Data.Status)) {
        if (-not $s) { continue }
        $k = ([string]$s.Computer).ToUpper(); if ($done.ContainsKey($k)) { continue }; $done[$k] = $true
        $b = $null; if ($Data.Beats -and $Data.Beats.ContainsKey($k)) { $b = $Data.Beats[$k] }
        $sn = ''; if ($Data.Seen -and $Data.Seen.ContainsKey($k)) { $sn = [string]$Data.Seen[$k] }
        ConvertTo-FdPcRow $s $b $sn $(if ($byPc.ContainsKey($k)) { $byPc[$k].ToArray() } else { @() }) $Now $OnlineMin $LocalFp
    }
    if ($Data.Beats) {
        foreach ($k in @($Data.Beats.Keys)) {
            if ($done.ContainsKey($k)) { continue }; $done[$k] = $true
            $sn = ''; if ($Data.Seen -and $Data.Seen.ContainsKey($k)) { $sn = [string]$Data.Seen[$k] }
            ConvertTo-FdPcRow $null $Data.Beats[$k] $sn $(if ($byPc.ContainsKey($k)) { $byPc[$k].ToArray() } else { @() }) $Now $OnlineMin $LocalFp
        }
    }
}
function Get-FdTileCounts($Rows) {
    $r = @(@($Rows) | Where-Object { $_ })
    [pscustomobject]@{
        Total = $r.Count; Online = @($r | Where-Object { $_.Online }).Count; Offline = @($r | Where-Object { -not $_.Online }).Count
        NoBeat = @($r | Where-Object { $_.OnlineState -eq 'unbekannt' }).Count
        Red = @($r | Where-Object { $_.State -eq 'Red' }).Count; Yellow = @($r | Where-Object { $_.State -eq 'Yellow' }).Count; Green = @($r | Where-Object { $_.State -eq 'Green' }).Count
        JobsOpen = [int](($r | ForEach-Object { [int]$_.JobsOpen } | Measure-Object -Sum).Sum); JobsFailed = [int](($r | ForEach-Object { [int]$_.JobsFailed } | Measure-Object -Sum).Sum)
        Reboot = @($r | Where-Object { $_.RebootPending }).Count
    }
}
function Test-FdRowShow($Row, [string]$Text, [int]$Mode) {
    switch ($Mode) { 1 { if (-not $Row.Problem) { return $false } } 2 { if (-not $Row.Online) { return $false } } 3 { if ($Row.Online) { return $false } } }
    if (-not $Text) { return $true }
    foreach ($pn in 'Computer', 'Model', 'User', 'AkStandort', 'AkBesitzer', 'Build', 'VerText', 'IP', 'JobText') { if ([string]$Row.$pn -like ('*' + $Text + '*')) { return $true } }
    return $false
}
function Get-FdChartPoints($Hist, [double]$Width, [double]$Height, [double]$Pad = 6) {
    $h = @(@($Hist) | Where-Object { $_ -and $null -ne $_.S })
    if ($h.Count -lt 1) { return @() }
    $n = $h.Count
    for ($i = 0; $i -lt $n; $i++) {
        $x = if ($n -eq 1) { $Width / 2 } else { $Pad + ($Width - 2 * $Pad) * $i / ($n - 1) }
        $v = [math]::Max([double]0, [math]::Min([double]100, [double]$h[$i].S))
        [pscustomobject]@{ X = [math]::Round($x, 1); Y = [math]::Round($Pad + ($Height - 2 * $Pad) * (100 - $v) / 100, 1); S = [int]$h[$i].S; D = [string]$h[$i].D }
    }
}

# ---- "Benachrichtigung bei Problem": Regeln (rein) + Sperrdatei gegen doppelte Meldungen
function Get-FdRules($Cfg) {
    $f = if ($Cfg) { $Cfg.Fleet } else { $null }
    $g = { param($n, $d) if ($f -and $f.PSObject.Properties[$n] -and $null -ne $f.$n) { $f.$n } else { $d } }
    [pscustomobject]@{
        Offline = [bool](& $g 'WatchOffline' $true); OfflineH = [int](& $g 'WatchOfflineH' 24)
        Score = [bool](& $g 'WatchScore' $true); ScoreDrop = [int](& $g 'WatchScoreDrop' 15)
        Backup = [bool](& $g 'WatchBackup' $true); BackupDays = [int](& $g 'WatchBackupDays' 14)
        Jobs = [bool](& $g 'WatchJobs' $true)
    }
}
function Get-FdIncidents($Rows, $JobRows, $Rules, [datetime]$Now) {
    foreach ($r in @(@($Rows) | Where-Object { $_ })) {
        $pc = [string]$r.Computer
        if ($Rules.Offline -and $Rules.OfflineH -gt 0 -and $r.HasBeat -and $r.LastSeen -and -not $r.Online -and ($r.AgeMin / 60) -ge $Rules.OfflineH) {
            [pscustomobject]@{ Kind = 'offline'; Pc = $pc; Key = ('offline_{0}_{1:yyyyMMddHHmm}' -f $pc, $r.LastSeen); Level = 'Yellow'; Title = ('{0} ist offline' -f $pc); Text = ('{0} meldet sich seit {1:N0} Stunden nicht mehr (zuletzt {2:dd.MM.yyyy HH:mm}). Strom, Netzwerk oder Aufgabe "PC-Pflege Fernaufträge" prüfen.' -f $pc, ($r.AgeMin / 60), $r.LastSeen) }
        }
        if ($Rules.Score -and $Rules.ScoreDrop -gt 0) {
            $sd = Get-FdScoreDrop $r.ScoreHist $Now
            if ($sd -and $sd.Drop -ge $Rules.ScoreDrop) {
                [pscustomobject]@{ Kind = 'score'; Pc = $pc; Key = ('score_{0}_{1}' -f $pc, $sd.Date); Level = 'Yellow'; Title = ('Zustands-Score von {0} eingebrochen' -f $pc); Text = ('Score {0} statt durchschnittlich {1:N0} in den Tagen davor (minus {2:N0} Punkte). Details: PC-Tools > Übersicht > Zustands-Score.' -f $sd.Score, $sd.Avg, $sd.Drop) }
            }
        }
        if ($Rules.Backup) {
            $raw = $r.Raw
            if ($r.BackupState -eq 'Fehler') {
                $bt0 = if ($raw -and $raw.BackupLast) { Get-FdTime $raw.BackupLast } else { $null }
                $bk = if ($bt0) { $bt0.ToString('yyyyMMddHHmm') } else { $Now.ToString('yyyyMMdd') }
                [pscustomobject]@{ Kind = 'backup'; Pc = $pc; Key = ('backup_{0}_{1}' -f $pc, $bk); Level = 'Red'; Title = ('Datensicherung auf {0} fehlgeschlagen' -f $pc); Text = ('Die letzte Datensicherung hatte Probleme ({0}). Protokoll im Dashboard ansehen.' -f [string]$raw.BackupText) }
            } elseif ($r.BackupState -eq 'alt' -and $Rules.BackupDays -gt 0 -and $raw -and $raw.BackupLast) {
                $bt = Get-FdTime $raw.BackupLast
                if ($bt -and ($Now - $bt).TotalDays -gt $Rules.BackupDays) { [pscustomobject]@{ Kind = 'backupalt'; Pc = $pc; Key = ('backupalt_{0}_{1:yyyyMMdd}' -f $pc, $bt); Level = 'Yellow'; Title = ('Datensicherung auf {0} veraltet' -f $pc); Text = ('Letzte Datensicherung vor {0:N0} Tagen ({1:dd.MM.yyyy}).' -f ($Now - $bt).TotalDays, $bt) } }
            }
            $fb = $r.FullBackup
            if ($fb -and [string]$fb.LastResult -eq 'Fehler') {
                [pscustomobject]@{ Kind = 'fullbackup'; Pc = $pc; Key = ('full_{0}_{1:yyyyMMdd}' -f $pc, $Now); Level = 'Red'; Title = ('Komplettsicherung auf {0} fehlgeschlagen' -f $pc); Text = $(if ([string]$fb.Message) { [string]$fb.Message } else { 'Die letzte Komplettsicherung ist fehlgeschlagen.' }) }
            } elseif ($fb -and [string]$fb.State -eq 'overdue') {
                $fl = Get-FdTime $fb.Last
                [pscustomobject]@{ Kind = 'fullbackupalt'; Pc = $pc; Key = ('fullalt_{0}_{1}' -f $pc, $(if ($fl) { $fl.ToString('yyyyMMdd') } else { 'nie' })); Level = 'Yellow'; Title = ('Komplettsicherung auf {0} überfällig' -f $pc); Text = $(if ($fl) { 'Letzte erfolgreiche Komplettsicherung am {0:dd.MM.yyyy}.' -f $fl } else { 'Noch keine erfolgreiche Komplettsicherung.' }) }
            }
        }
    }
    if ($Rules.Jobs) {
        foreach ($j in @(@($JobRows) | Where-Object { $_ -and $_.StateKey -eq 'failed' -and $_.Level -eq 'Error' -and $_.EndTime -and ($Now - $_.EndTime).TotalHours -le 24 })) {
            [pscustomobject]@{ Kind = 'job'; Pc = [string]$j.Pc; Key = ('job_{0}_{1}' -f $j.Pc, $j.Id); Level = 'Red'; Title = ('Fernauftrag auf {0} fehlgeschlagen' -f $j.Pc); Text = ('{0}: {1} ({2})' -f $j.ActionText, $j.StateText, $j.Message) }
        }
    }
}
function Lock-FdIncident([string]$Dir, [string]$Key, [string]$Who = $env:COMPUTERNAME) {
    $md = Join-Path $Dir 'Meldungen'
    New-Item -ItemType Directory -Path $md -Force -ErrorAction Stop | Out-Null
    $f = Join-Path $md ((ConvertTo-FdSafeName $Key) + '.json')
    $fs = $null
    try { $fs = [IO.File]::Open($f, [IO.FileMode]::CreateNew, [IO.FileAccess]::Write, [IO.FileShare]::None) } catch { return $false }
    try { $b = [Text.Encoding]::UTF8.GetBytes(([pscustomobject]@{ Key = $Key; By = $Who; Time = (Get-Date).ToString('o') } | ConvertTo-Json -Compress)); $fs.Write($b, 0, $b.Length) } finally { $fs.Dispose() }
    return $true
}
function Unlock-FdIncident([string]$Dir, [string]$Key) { Remove-Item -LiteralPath (Join-Path (Join-Path $Dir 'Meldungen') ((ConvertTo-FdSafeName $Key) + '.json')) -Force -ErrorAction SilentlyContinue }
function Invoke-FdWatch([string]$Dir, $Cfg, [int]$Max = 5) {
    $data = Read-FdFleetData $Dir 20
    $now = Get-Date
    $om = 25; try { if ([int]$Cfg.Fleet.OnlineMin -ge 5) { $om = [int]$Cfg.Fleet.OnlineMin } } catch { }
    $rows = @(Get-FdRows $data $now $om '')
    $jrows = @(@($data.Jobs) | Where-Object { $_ } | ForEach-Object { ConvertTo-FdJobRow $_ $now })
    $inc = @(Get-FdIncidents $rows $jrows (Get-FdRules $Cfg) $now)
    $sent = 0
    foreach ($i in $inc) {
        if ($sent -ge $Max) { break }
        if ($i.Kind -eq 'offline' -and $i.Pc -eq $env:COMPUTERNAME) { continue }
        if (-not (Lock-FdIncident $Dir $i.Key)) { continue }
        $res = @(); try { $res = @(Send-PflegeNotify $i.Title ([string]$i.Text + "`n(gemeldet von " + $env:COMPUTERNAME + ')') $i.Level) } catch { }
        if (@($res | Where-Object { [string]$_ -like '*: OK' }).Count) { $sent++ } else { Unlock-FdIncident $Dir $i.Key }
    }
    # alte Sperrdateien (30 Tage) aufräumen
    Get-ChildItem -LiteralPath (Join-Path $Dir 'Meldungen') -Filter '*.json' -File -ErrorAction SilentlyContinue | Where-Object { $_.LastWriteTime -lt (Get-Date).AddDays(-30) } | Remove-Item -Force -ErrorAction SilentlyContinue
    return $sent
}

# ---- Zusätze bei jedem Lauf der Fernaufträge-Aufgabe (alle 10 Minuten, als SYSTEM)
function Invoke-FdPollExtras($Cfg, [string]$Dir) {
    $Script:FdInPoll = $true
    $lg = Join-Path (Join-Path $DataDir 'Logs') 'Fernauftraege.log'
    if ($Cfg.Fleet.Heartbeat -or $Cfg.Fleet.Remote) { try { Write-FdHeartbeat $Dir $Cfg } catch { try { Add-Content -LiteralPath $lg -Value ('{0:yyyy-MM-dd HH:mm} Heartbeat: {1}' -f (Get-Date), $_.Exception.Message) -Encoding UTF8 } catch { } } }
    # ausführlicher Zustand höchstens stündlich (sonst nur nach Pflege/Öffnen der Oberfläche)
    try {
        $sf = Join-Path $Dir ('{0}.json' -f $env:COMPUTERNAME)
        $age = if (Test-Path -LiteralPath $sf) { ((Get-Date) - (Get-Item -LiteralPath $sf).LastWriteTime).TotalMinutes } else { 9999 }
        if ($age -ge 55) { $items = @(); try { $items = @(Get-HealthItems (Get-HealthArgs) | ForEach-Object { $_ }) } catch { }; Write-FleetStatus $items }
    } catch { try { Add-Content -LiteralPath $lg -Value ('{0:yyyy-MM-dd HH:mm} Status: {1}' -f (Get-Date), $_.Exception.Message) -Encoding UTF8 } catch { } }
    if ($Cfg.Fleet.Watch) { try { $null = Invoke-FdWatch $Dir $Cfg } catch { try { Add-Content -LiteralPath $lg -Value ('{0:yyyy-MM-dd HH:mm} Überwachung: {1}' -f (Get-Date), $_.Exception.Message) -Encoding UTF8 } catch { } } }
}
