# ---------------------------------------------------------------- JSON (eigener, verlässlicher Serialisierer für PS 5.1 und 7)
function ConvertTo-AiJsonString([string]$Text) {
    if ($null -eq $Text) { return '""' }
    $esc = [regex]::Replace($Text, '[\\"\x00-\x1F  ]', {
            param($m)
            switch ([int][char]$m.Value) {
                34 { '\"' } 92 { '\\' } 8 { '\b' } 9 { '\t' } 10 { '\n' } 12 { '\f' } 13 { '\r' }
                default { '\u{0:x4}' -f [int][char]$m.Value }
            }
        })
    return '"' + $esc + '"'
}
function ConvertTo-AiJson($Value) {
    if ($null -eq $Value) { return 'null' }
    if ($Value -is [string] -or $Value -is [char]) { return (ConvertTo-AiJsonString ([string]$Value)) }
    if ($Value -is [bool]) { if ($Value) { return 'true' } else { return 'false' } }
    if ($Value -is [int] -or $Value -is [long] -or $Value -is [int16] -or $Value -is [byte] -or $Value -is [uint32] -or $Value -is [uint64]) { return ([string]$Value) }
    if ($Value -is [double] -or $Value -is [single] -or $Value -is [decimal]) { return ([Convert]::ToString($Value, [Globalization.CultureInfo]::InvariantCulture)) }
    if ($Value -is [System.Collections.IDictionary]) {
        $aiParts = [System.Collections.Generic.List[string]]::new()
        foreach ($k in $Value.Keys) { $aiParts.Add((ConvertTo-AiJsonString ([string]$k)) + ':' + (ConvertTo-AiJson $Value[$k])) }
        return '{' + ($aiParts -join ',') + '}'
    }
    if ($Value -is [System.Management.Automation.PSCustomObject]) {
        $aiParts = [System.Collections.Generic.List[string]]::new()
        foreach ($p in $Value.PSObject.Properties) { $aiParts.Add((ConvertTo-AiJsonString ([string]$p.Name)) + ':' + (ConvertTo-AiJson $p.Value)) }
        return '{' + ($aiParts -join ',') + '}'
    }
    if ($Value -is [System.Collections.IEnumerable]) {
        $aiParts = [System.Collections.Generic.List[string]]::new()
        foreach ($x in $Value) { $aiParts.Add((ConvertTo-AiJson $x)) }
        return '[' + ($aiParts -join ',') + ']'
    }
    return (ConvertTo-AiJsonString ([string]$Value))
}

# ---------------------------------------------------------------- Werkzeuge (tools) für die API
function Get-AiToolDefs([string[]]$Pages, [object[]]$Profiles) {
    $aiTools = [System.Collections.Generic.List[object]]::new()
    $profKeys = @($Profiles | ForEach-Object { [string]$_.Key } | Where-Object { $_ })
    $profDesc = 'Reparatur-Profil: ' + ((@($Profiles | Where-Object { $_.Key }) | ForEach-Object { '{0} = {1}' -f $_.Key, $_.Title }) -join '; ')
    foreach ($d in $AiActionDefs) {
        if ($d.Name -eq 'seite_oeffnen' -and -not @($Pages).Count) { continue }
        if ($d.Name -eq 'windows_reparatur_vorbereiten' -and -not $profKeys.Count) { continue }
        $props = [ordered]@{}
        foreach ($pn in $d.Params.Keys) {
            $src = $d.Params[$pn]; $p = [ordered]@{ type = $src.type }
            $desc = [string]$src.description; if ($desc -eq '__PROFILES_DESC__') { $desc = $profDesc }
            $p.description = $desc
            if ($src.Contains('enum')) {
                if ($src.enum -eq '__PAGES__') { $p.enum = @($Pages) }
                elseif ($src.enum -eq '__PROFILES__') { $p.enum = @($profKeys) }
                else { $p.enum = @($src.enum) }
            }
            $props[$pn] = $p
        }
        $schema = [ordered]@{ type = 'object'; properties = $props }
        if (@($d.Required).Count) { $schema.required = @($d.Required) }
        $kindTxt = switch ($d.Kind) { 'Read' { ' (gibt Daten an dich zurück)' } 'Open' { ' (öffnet nur eine Seite)' } default { ' (startet eine Aufgabe in PC-Tools)' } }
        $aiTools.Add([ordered]@{ name = $d.Name; description = ($d.Desc + $kindTxt + ' Der Nutzer muss jede Aktion bestätigen.'); input_schema = $schema })
    }
    return , $aiTools
}
function Get-AiActionDef([string]$Name) { foreach ($d in $AiActionDefs) { if ($d.Name -eq $Name) { return $d } }; return $null }

# ---------------------------------------------------------------- Anfrage bauen
function New-AiRequestBody([string]$Model, [string]$System, [object[]]$Messages, [object[]]$Tools = @(), [int]$MaxTokens = 1024) {
    if ($MaxTokens -lt 64) { $MaxTokens = 64 }
    $req = [ordered]@{ model = $Model; max_tokens = $MaxTokens; system = $System; messages = @($Messages) }
    if (@($Tools).Count) { $req.tools = @($Tools) }
    return (ConvertTo-AiJson $req)
}
function Get-AiRequestBytes([string]$Json) { return , ([Text.Encoding]::UTF8.GetBytes($Json)) }

# ---------------------------------------------------------------- Antwort auswerten
function ConvertFrom-AiResponse([string]$Json) {
    $o = $Json | ConvertFrom-Json
    if ($o.PSObject.Properties['choices']) { $o = ConvertFrom-AiOpenAiResponse $o }
    $texts = [System.Collections.Generic.List[string]]::new()
    $tools = [System.Collections.Generic.List[object]]::new()
    $hist = [System.Collections.Generic.List[object]]::new()
    foreach ($b in @($o.content)) {
        if (-not $b) { continue }
        switch ([string]$b.type) {
            'text' {
                $texts.Add([string]$b.text)
                $hist.Add([ordered]@{ type = 'text'; text = [string]$b.text })
            }
            'tool_use' {
                $inp = $b.input; if ($null -eq $inp) { $inp = [ordered]@{} }
                $tools.Add([pscustomobject]@{ Id = [string]$b.id; Name = [string]$b.name; Input = $inp })
                $hist.Add([ordered]@{ type = 'tool_use'; id = [string]$b.id; name = [string]$b.name; input = $inp })
            }
        }
    }
    if (-not $hist.Count) { $hist.Add([ordered]@{ type = 'text'; text = '(keine Antwort)' }) }
    $in = [long]0; $out = [long]0
    if ($o.usage) {
        foreach ($k in 'input_tokens', 'cache_creation_input_tokens', 'cache_read_input_tokens') { try { if ($null -ne $o.usage.$k) { $in += [long]$o.usage.$k } } catch { } }
        try { $out = [long]$o.usage.output_tokens } catch { }
    }
    [pscustomobject]@{
        Text = (($texts | Where-Object { $_ }) -join "`n`n").Trim()
        ToolUses = $tools.ToArray()
        Content = $hist.ToArray()
        StopReason = [string]$o.stop_reason
        Model = [string]$o.model
        InTokens = $in; OutTokens = $out
    }
}
function New-AiToolResult([string]$Id, [string]$Text, [bool]$IsError = $false) {
    $r = [ordered]@{ type = 'tool_result'; tool_use_id = $Id; content = $Text }
    if ($IsError) { $r.is_error = $true }
    return $r
}

# ---------------------------------------------------------------- Verständliche Fehlermeldungen
function Get-AiErrorText([int]$Status, [string]$Body, [string]$Message, [string]$Name = 'Anthropic') {
    $apiMsg = ''; $apiType = ''
    if ($Body) { try { $e = $Body | ConvertFrom-Json; $apiMsg = [string]$e.error.message; $apiType = [string]$e.error.type } catch { } }
    $det = $(if ($apiMsg) { ' (' + $Name + ': ' + $apiMsg + ')' } else { '' })
    switch ($Status) {
        0 {
            $m = [string]$Message
            if ($m -match '(?i)407|proxy') { return 'Der Proxy-Server lässt die Verbindung nicht zu (Proxy-Anmeldung nötig?). Bitte die Proxy-Einstellungen von Windows prüfen oder die Netzwerk-Diagnose starten. Details: ' + $m }
            if ($m -match '(?i)NameResolution|resolve|auflös|Remotename|No such host|nicht bekannt') { return 'Keine Verbindung: Der Name des KI-Servers lässt sich nicht auflösen. Ist der PC mit dem Internet verbunden? Tipp: Netzwerk-Diagnose starten. Details: ' + $m }
            if ($m -match '(?i)Timeout|Zeitlimit|timed out|überschritten') { return 'Zeitüberschreitung: ' + $Name + ' hat nicht rechtzeitig geantwortet. Bitte gleich noch einmal versuchen oder ein schnelleres Modell wählen.' }
            if ($m -match '(?i)SSL|TLS|Vertrauensstellung|trust|certificate|Zertifikat') { return 'Die sichere Verbindung (TLS) wurde abgelehnt - oft durch eine Firewall oder einen Virenschutz mit HTTPS-Prüfung. Details: ' + $m }
            return 'Keine Verbindung zu ' + $Name + ': ' + $m + ' - Internet, Firewall oder Proxy prüfen (Netzwerk-Diagnose hilft).'
        }
        400 {
            if ($apiMsg -match '(?i)credit|balance|billing|guthaben') { return 'Das Guthaben beim KI-Anbieter (' + $Name + ') ist aufgebraucht. Bitte dort aufladen - oder oben einen kostenlosen Anbieter wählen.' + $det }
            return 'Die Anfrage wurde abgelehnt (ungültig).' + $det + ' Tipp: "Neues Gespräch" starten.'
        }
        401 { return 'Der API-Schlüssel ist ungültig oder wurde widerrufen. Bitte beim Anbieter einen neuen Schlüssel erzeugen und hier unter "API-Schlüssel" einfügen.' }
        403 { return 'Der API-Schlüssel hat keine Berechtigung für diese Anfrage (z.B. Modell nicht freigeschaltet oder Organisation gesperrt).' + $det }
        404 { return 'Das gewählte Modell ist nicht verfügbar. Bitte rechts unter "Modell" ein anderes wählen.' + $det }
        413 { return 'Die Anfrage ist zu groß. Bitte weniger Kontext mitsenden oder ein neues Gespräch beginnen.' }
        429 {
            if ($apiMsg -match '(?i)credit|balance|billing|spend|limit.*month|monthly') { return 'Das Ausgaben- bzw. Gratis-Limit bei ' + $Name + ' ist erreicht - später erneut versuchen oder oben einen anderen Anbieter wählen.' + $det }
            return 'Zu viele Anfragen in kurzer Zeit (Rate-Limit von ' + $Name + '). Bitte eine Minute warten und dann erneut fragen.'
        }
        500 { return 'Fehler bei ' + $Name + ' (500). Bitte später noch einmal versuchen.' }
        502 { return '' + $Name + ' ist gerade nicht erreichbar (502). Bitte später noch einmal versuchen.' }
        503 { return '' + $Name + ' ist gerade nicht erreichbar (503). Bitte später noch einmal versuchen.' }
        529 { return 'Claude ist gerade überlastet (529). Bitte in ein paar Minuten noch einmal fragen - oder vorübergehend ein anderes Modell wählen.' }
    }
    return ('Unerwartete Antwort von {2} (HTTP {0}).{1}' -f $Status, $det, $Name)
}

# ---------------------------------------------------------------- HTTP (läuft in Invoke-Bg; UTF-8-Bytes, TLS 1.2, Windows-Proxy)
function Invoke-AiHttp([string]$Method, [string]$Url, [hashtable]$Headers, [byte[]]$Body, [int]$TimeoutSec = 120, [switch]$NoProxy) {
    try { [Net.ServicePointManager]::SecurityProtocol = [Net.ServicePointManager]::SecurityProtocol -bor [Net.SecurityProtocolType]::Tls12 } catch { }
    $status = 0; $text = ''; $errMsg = ''
    try {
        $req = [Net.HttpWebRequest][Net.WebRequest]::Create($Url)
        $req.Method = $Method
        $req.Timeout = $TimeoutSec * 1000; $req.ReadWriteTimeout = $TimeoutSec * 1000
        $req.UserAgent = 'PC-Tools'; $req.Accept = 'application/json'
        if ($NoProxy) { $req.Proxy = $null } else { try { $px = [Net.WebRequest]::GetSystemWebProxy(); $px.Credentials = [Net.CredentialCache]::DefaultNetworkCredentials; $req.Proxy = $px } catch { } }
        foreach ($hk in @($Headers.Keys)) {
            if ([string]$hk -eq 'content-type') { $req.ContentType = [string]$Headers[$hk] } else { $req.Headers[[string]$hk] = [string]$Headers[$hk] }
        }
        if ($null -ne $Body -and $Body.Length) {
            $req.ContentLength = $Body.Length
            $rs = $req.GetRequestStream(); try { $rs.Write($Body, 0, $Body.Length) } finally { $rs.Close() }
        }
        $resp = $req.GetResponse()
        try {
            $status = [int]$resp.StatusCode
            $sr = New-Object IO.StreamReader($resp.GetResponseStream(), [Text.Encoding]::UTF8)
            try { $text = $sr.ReadToEnd() } finally { $sr.Close() }
        } finally { $resp.Close() }
    } catch {
        $ex = $_.Exception
        while ($ex -and -not ($ex -is [Net.WebException]) -and $ex.InnerException) { $ex = $ex.InnerException }
        if ($ex -is [Net.WebException] -and $ex.Response) {
            $r = $ex.Response
            try { $status = [int]$r.StatusCode } catch { $status = 0 }
            try { $sr = New-Object IO.StreamReader($r.GetResponseStream(), [Text.Encoding]::UTF8); $text = $sr.ReadToEnd(); $sr.Close() } catch { }
            try { $r.Close() } catch { }
            if ($status -eq 407) { $status = 0; $errMsg = 'Proxy-Anmeldung erforderlich (407)' }
        } else {
            $errMsg = [string]$ex.Message
            if ($ex -is [Net.WebException]) { $errMsg = ('{0}: {1}' -f $ex.Status, $ex.Message) }
        }
    }
    [pscustomobject]@{ Status = $status; Body = $text; Error = $errMsg }
}
# Eine Messages-Anfrage mit einer Wiederholung bei Überlastung (läuft im Hintergrund)
function Invoke-AiMessages([string]$Key, [byte[]]$Body, [string]$Url, [string]$Version, [string]$Kind = 'anthropic', [int]$TimeoutSec = 150) {
    $local = ([string]$Url -match '^https?://(localhost|127\.0\.0\.1|\[::1\])(:|/)')
    if ($Kind -eq 'anthropic') { $h = @{ 'x-api-key' = $Key; 'anthropic-version' = $Version; 'content-type' = 'application/json' } }
    else {
        $h = @{ 'content-type' = 'application/json'; 'X-Title' = 'PC-Tools'; 'HTTP-Referer' = 'https://github.com/rhedv42-sudo/pc-tools' }
        if ($Key) { $h['Authorization'] = 'Bearer ' + $Key }
    }
    $res = $null
    for ($try = 1; $try -le 2; $try++) {
        $res = Invoke-AiHttp 'POST' $Url $h $Body $TimeoutSec -NoProxy:$local
        if ($local -and [int]$res.Status -eq 0 -and $try -lt 2 -and $Url -match ':11434/') { if (Start-OllamaServer) { continue } }
        if ($res.Status -in 500, 502, 503, 529 -and $try -lt 2) { Start-Sleep -Seconds 4; continue }
        break
    }
    return $res
}

# ---------------------------------------------------------------- Ollama (kostenlose lokale KI) - alles im Hintergrund
function Get-OllamaExe {
    foreach ($c in @((Join-Path $env:LOCALAPPDATA 'Programs\Ollama\ollama.exe'), (Join-Path $env:ProgramFiles 'Ollama\ollama.exe'))) { if ($c -and (Test-Path -LiteralPath $c)) { return $c } }
    try { $g = Get-Command ollama.exe -ErrorAction Stop; return $g.Source } catch { }
    return ''
}
function Get-OllamaState([string]$BaseUrl = 'http://localhost:11434') {
    $o = [pscustomobject]@{ Installed = [bool](Get-OllamaExe); Running = $false; Models = @(); Version = '' }
    $r = Invoke-AiHttp 'GET' ($BaseUrl.TrimEnd('/') + '/api/tags') @{} $null 4 -NoProxy
    if ([int]$r.Status -eq 200) {
        $o.Running = $true; $o.Installed = $true
        try { $o.Models = @(($r.Body | ConvertFrom-Json).models | ForEach-Object { [string]$_.name }) } catch { }
    }
    return $o
}
function Start-OllamaServer {
    $st = Get-OllamaState
    if ($st.Running) { return $true }
    $exe = Get-OllamaExe; if (-not $exe) { return $false }
    $app = Join-Path (Split-Path -Parent $exe) 'ollama app.exe'
    try { if (Test-Path -LiteralPath $app) { Start-Process -FilePath $app -WindowStyle Hidden } else { Start-Process -FilePath $exe -ArgumentList 'serve' -WindowStyle Hidden } } catch { return $false }
    for ($i = 0; $i -lt 20; $i++) { Start-Sleep -Milliseconds 750; if ((Get-OllamaState).Running) { return $true } }
    return $false
}
# Installiert Ollama (winget, still) falls nötig, startet es und lädt das Modell. Gibt Textzeilen zurück.
function Install-OllamaModel([string]$Model, [switch]$InstallApp) {
    $log = [System.Collections.Generic.List[string]]::new()
    if (-not (Get-OllamaExe) -and $InstallApp) {
        $wg = ''; try { $wg = (Get-Command winget.exe -ErrorAction Stop).Source } catch { }
        if (-not $wg) { $log.Add('winget fehlt - bitte Ollama von https://ollama.com/download installieren.'); return $log.ToArray() }
        $log.Add('Installiere Ollama (winget, ca. 1 GB) ...')
        $r = Invoke-NdCmd $wg 'install -e --id Ollama.Ollama --silent --accept-package-agreements --accept-source-agreements --disable-interactivity' 900
        if (-not (Get-OllamaExe)) { $log.Add('Installation nicht abgeschlossen: ' + ([string]$r).Trim()); return $log.ToArray() }
        $log.Add('Ollama installiert.')
    }
    if (-not (Start-OllamaServer)) { $log.Add('Ollama läuft nicht und ließ sich nicht starten. Bitte Ollama einmal über das Startmenü öffnen.'); return $log.ToArray() }
    if ($Model) {
        if (@((Get-OllamaState).Models) -contains $Model -or @((Get-OllamaState).Models) -contains ($Model + ':latest')) { $log.Add(('Modell {0} ist bereits geladen.' -f $Model)); return $log.ToArray() }
        $log.Add(('Lade Modell {0} herunter (einige GB, kann je nach Leitung 5-30 Minuten dauern) ...' -f $Model))
        $body = [Text.Encoding]::UTF8.GetBytes((ConvertTo-AiJson ([ordered]@{ model = $Model; stream = $false })))
        $r = Invoke-AiHttp 'POST' 'http://localhost:11434/api/pull' @{ 'content-type' = 'application/json' } $body 7200 -NoProxy
        if ([int]$r.Status -eq 200) { $log.Add(('OK: Modell {0} ist bereit.' -f $Model)) } else { $log.Add(('Laden fehlgeschlagen (HTTP {0}): {1} {2}' -f $r.Status, $r.Body, $r.Error)) }
    }
    return $log.ToArray()
}
# Modellvorschlag nach Arbeitsspeicher
function Get-OllamaSuggestedModel {
    $gb = 8; try { $gb = [math]::Round((Get-CimInstance Win32_ComputerSystem -OperationTimeoutSec 3 -ErrorAction Stop).TotalPhysicalMemory / 1GB) } catch { }
    if ($gb -ge 24) { return 'qwen3:8b' }
    return 'qwen3:4b'
}

# ---------------------------------------------------------------- KI 13.9: Daten für die Lese-Werkzeuge (alles nur lesen)
$AiBugChecks = @{
    0x0A = 'IRQL_NOT_LESS_OR_EQUAL (meist fehlerhafter Treiber)'; 0x1A = 'MEMORY_MANAGEMENT (Arbeitsspeicher oder Treiber)'; 0x1E = 'KMODE_EXCEPTION_NOT_HANDLED (Treiber)'
    0x3B = 'SYSTEM_SERVICE_EXCEPTION (Treiber oder Systemdatei)'; 0x50 = 'PAGE_FAULT_IN_NONPAGED_AREA (Treiber, RAM oder Virenschutz)'; 0x7E = 'SYSTEM_THREAD_EXCEPTION_NOT_HANDLED (Treiber)'
    0x7F = 'UNEXPECTED_KERNEL_MODE_TRAP (Hardware/Übertaktung)'; 0x9F = 'DRIVER_POWER_STATE_FAILURE (Treiber beim Energiesparen/Standby)'
    0xC2 = 'BAD_POOL_CALLER (Treiber)'; 0xC5 = 'DRIVER_CORRUPTED_EXPOOL (Treiber)'; 0xD1 = 'DRIVER_IRQL_NOT_LESS_OR_EQUAL (Treiber, oft Netzwerk/WLAN)'
    0xEF = 'CRITICAL_PROCESS_DIED (Systemprozess beendet - Systemdateien/Datenträger)'; 0xF4 = 'CRITICAL_OBJECT_TERMINATION (Datenträger/Systemprozess)'; 0x101 = 'CLOCK_WATCHDOG_TIMEOUT (Prozessor/BIOS/Übertaktung)'
    0x116 = 'VIDEO_TDR_FAILURE (Grafiktreiber)'; 0x117 = 'VIDEO_TDR_TIMEOUT_DETECTED (Grafiktreiber)'; 0x124 = 'WHEA_UNCORRECTABLE_ERROR (Hardwarefehler: CPU, RAM, Überhitzung, Netzteil)'
    0x133 = 'DPC_WATCHDOG_VIOLATION (Treiber, oft Speicher-Controller/SSD)'; 0x139 = 'KERNEL_SECURITY_CHECK_FAILURE (Treiber oder beschädigte Daten)'; 0x13A = 'KERNEL_MODE_HEAP_CORRUPTION (Treiber)'
    0x154 = 'UNEXPECTED_STORE_EXCEPTION (Datenträger/SSD)'; 0x1E0 = 'BUGCODE_ID_DRIVER'; 0x7A = 'KERNEL_DATA_INPAGE_ERROR (Datenträger/SSD oder Kabel)'
    0x77 = 'KERNEL_STACK_INPAGE_ERROR (Datenträger)'; 0xBE = 'ATTEMPTED_WRITE_TO_READONLY_MEMORY (Treiber)'; 0xFC = 'ATTEMPTED_EXECUTE_OF_NOEXECUTE_MEMORY (Treiber)'
    0x18B = 'SECURE_KERNEL_ERROR'; 0x1CA = 'SYNTHETIC_WATCHDOG_TIMEOUT'; 0x9C = 'MACHINE_CHECK_EXCEPTION (Hardware)'
}
function Get-AiBugCheckName([long]$Code) { if ($Code -eq 0xC000021AL) { return 'Windows-Anmeldeprozess abgestürzt (Systemdateien)' }; $n = $null; if ($Code -ge 0 -and $Code -le [int]::MaxValue) { $n = $AiBugChecks[[int]$Code] }; if ($n) { return $n }; return 'unbekannter Stoppcode' }
# Liest Stoppcode und Parameter aus dem Kopf einer Minidump-Datei (PAGEDU64 / PAGEDUMP)
function Read-MinidumpBugCheck([string]$Path) {
    try {
        $fs = [IO.File]::Open($Path, 'Open', 'Read', 'ReadWrite')
        try { $buf = New-Object byte[] 0x60; $n = $fs.Read($buf, 0, $buf.Length) } finally { $fs.Close() }
        if ($n -lt 0x60) { return $null }
        $sig = [Text.Encoding]::ASCII.GetString($buf, 0, 8)
        if ($sig -eq 'PAGEDU64') { $code = [BitConverter]::ToUInt32($buf, 0x38); $p = @(0x40, 0x48, 0x50, 0x58 | ForEach-Object { '0x{0:X}' -f [BitConverter]::ToUInt64($buf, $_) }) }
        elseif ($sig -eq 'PAGEDUMP') { $code = [BitConverter]::ToUInt32($buf, 0x20); $p = @(0x24, 0x28, 0x2C, 0x30 | ForEach-Object { '0x{0:X}' -f [BitConverter]::ToUInt32($buf, $_) }) }
        else { return $null }
        return [pscustomobject]@{ Code = [long]$code; Params = $p }
    } catch { return $null }
}
function Get-AiCrashText([int]$Days = 90) {
    $o = [System.Collections.Generic.List[string]]::new()
    $since = (Get-Date).AddDays(-$Days)
    $dumps = @()
    foreach ($d in @((Join-Path $env:SystemRoot 'Minidump'), (Join-Path $env:SystemRoot 'LiveKernelReports'))) {
        try { $dumps += @(Get-ChildItem -LiteralPath $d -Filter '*.dmp' -File -Recurse -ErrorAction Stop | Where-Object { $_.LastWriteTime -gt $since }) } catch { }
    }
    $o.Add(('Bluescreens/Absturzabbilder der letzten {0} Tage: {1}' -f $Days, $dumps.Count))
    foreach ($f in @($dumps | Sort-Object LastWriteTime -Descending | Select-Object -First 10)) {
        $bc = Read-MinidumpBugCheck $f.FullName
        $o.Add(('- {0:dd.MM.yyyy HH:mm}  {1}{2}' -f $f.LastWriteTime, $f.Name, $(if ($bc) { '  Stoppcode 0x{0:X} = {1}, Parameter {2}' -f $bc.Code, (Get-AiBugCheckName $bc.Code), ($bc.Params -join ' ') } else { '' })))
    }
    try { if (Test-Path -LiteralPath (Join-Path $env:SystemRoot 'MEMORY.DMP')) { $m = Get-Item -LiteralPath (Join-Path $env:SystemRoot 'MEMORY.DMP'); $o.Add(('Vollständiges Speicherabbild MEMORY.DMP vom {0:dd.MM.yyyy} ({1:N1} GB)' -f $m.LastWriteTime, ($m.Length / 1GB))) } } catch { }
    $ev = @()
    try { $ev = @(Get-WinEvent -FilterHashtable @{ LogName = 'System'; Id = 41, 1001, 6008; StartTime = $since } -MaxEvents 60 -ErrorAction Stop) } catch { }
    $bug = @($ev | Where-Object { $_.Id -eq 1001 -and $_.ProviderName -match 'WER-SystemErrorReporting|BugCheck' })
    $kp = @($ev | Where-Object { $_.Id -eq 41 }); $us = @($ev | Where-Object { $_.Id -eq 6008 })
    $o.Add(('Ereignisse: {0} Bluescreen-Meldungen (1001), {1} unerwartete Neustarts/Stromverlust (Kernel-Power 41), {2} unerwartete Herunterfahren (6008)' -f $bug.Count, $kp.Count, $us.Count))
    foreach ($e in @($bug | Select-Object -First 6)) { $o.Add(('- {0:dd.MM.yyyy HH:mm} {1}' -f $e.TimeCreated, (([string]$e.Message) -replace '\s+', ' ').Substring(0, [math]::Min(260, ([string]$e.Message -replace '\s+', ' ').Length)))) }
    foreach ($e in @($kp | Select-Object -First 6)) {
        $code = 0; try { $code = [long]$e.Properties[0].Value } catch { }
        $o.Add(('- {0:dd.MM.yyyy HH:mm} Kernel-Power 41{1}' -f $e.TimeCreated, $(if ($code) { ' mit Stoppcode 0x{0:X} = {1}' -f $code, (Get-AiBugCheckName $code) } else { ' ohne Stoppcode (Strom weg, Ausschalter gedrückt, Netzteil oder Überhitzung)' })))
    }
    if (-not $dumps.Count -and -not $ev.Count) { $o.Add('Keine Bluescreens und keine unerwarteten Neustarts gefunden.') }
    return ($o -join "`n")
}
function Get-AiEventText([int]$Days = 7, [int]$Top = 25) {
    $since = (Get-Date).AddDays(-$Days)
    $all = [System.Collections.Generic.List[object]]::new()
    foreach ($log in 'System', 'Application') {
        try { foreach ($e in @(Get-WinEvent -FilterHashtable @{ LogName = $log; Level = 1, 2; StartTime = $since } -MaxEvents 500 -ErrorAction Stop)) { $all.Add($e) } } catch { }
    }
    if (-not $all.Count) { return ('Keine Fehler oder kritischen Ereignisse in den letzten {0} Tagen (System und Anwendung).' -f $Days) }
    $o = [System.Collections.Generic.List[string]]::new()
    $o.Add(('{0} Fehler/kritische Ereignisse in den letzten {1} Tagen, gruppiert (Anzahl, Quelle, ID, zuletzt, Meldung):' -f $all.Count, $Days))
    foreach ($g in @($all | Group-Object { '{0}|{1}' -f $_.ProviderName, $_.Id } | Sort-Object Count -Descending | Select-Object -First $Top)) {
        $e = @($g.Group | Sort-Object TimeCreated -Descending)[0]
        $msg = ''; try { $msg = ([string]$e.Message -replace '\s+', ' ').Trim() } catch { }
        if ($msg.Length -gt 220) { $msg = $msg.Substring(0, 220) + ' ...' }
        $o.Add(('- {0}x  {1} (ID {2}, {3})  zuletzt {4:dd.MM. HH:mm}: {5}' -f $g.Count, $e.ProviderName, $e.Id, $e.LogName, $e.TimeCreated, $msg))
    }
    return ($o -join "`n")
}
function Get-AiUpdateText {
    $o = [System.Collections.Generic.List[string]]::new()
    try {
        $h = @(Get-WuHistory | ForEach-Object { $_ } | Select-Object -First 25)
        $o.Add('Zuletzt installierte bzw. versuchte Windows-Updates:')
        foreach ($x in $h) { $o.Add(('- {0}  {1}  {2}' -f $x.Date, $x.Result, $x.Title)) }
    } catch { $o.Add('Update-Verlauf nicht lesbar: ' + $_.Exception.Message) }
    try {
        $p = @(Get-WuUpdatesList | ForEach-Object { $_ } | Where-Object { $_ -and -not $_.Hidden })
        $o.Add(''); $o.Add(('Ausstehende Windows-Updates: {0}' -f $p.Count)); foreach ($x in @($p | Select-Object -First 15)) { $o.Add('- ' + $x.Title) }
    } catch { }
    try { $rb = (Test-Path 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\WindowsUpdate\Auto Update\RebootRequired') -or (Test-Path 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Component Based Servicing\RebootPending'); $o.Add(('Neustart ausstehend: {0}' -f $(if ($rb) { 'ja' } else { 'nein' }))) } catch { }
    return ($o -join "`n")
}
function Get-AiDriverText {
    $o = [System.Collections.Generic.List[string]]::new()
    try { $o.Add((Get-DevIssueText)) } catch { $o.Add('Geräte-Manager nicht lesbar: ' + $_.Exception.Message) }
    try {
        $old = @(Get-CimInstance Win32_PnPSignedDriver -OperationTimeoutSec 20 -ErrorAction Stop | Where-Object { $_.DriverDate -and $_.DeviceName -and $_.DriverProviderName -notmatch '^Microsoft' } | Sort-Object DriverDate | Select-Object -First 15)
        $o.Add(''); $o.Add('Älteste Treiber von Drittherstellern (Gerät, Hersteller, Version, Datum):')
        foreach ($d in $old) { $o.Add(('- {0} | {1} | {2} | {3:dd.MM.yyyy}' -f $d.DeviceName, $d.DriverProviderName, $d.DriverVersion, $d.DriverDate)) }
    } catch { }
    return ($o -join "`n")
}
# Wochen-Daten (Hintergrund): Läufe, Ereignisse, Abstürze, Updates
function Get-AiWeekData([string]$LogDir) {
    $o = [System.Collections.Generic.List[string]]::new()
    $since = (Get-Date).AddDays(-7)
    try {
        $logs = @(Get-ChildItem -LiteralPath $LogDir -Filter 'PCPflege_*.log' -File -ErrorAction Stop | Where-Object { $_.LastWriteTime -gt $since })
        $w = 0; $e = 0; foreach ($l in $logs) { foreach ($z in [IO.File]::ReadAllLines($l.FullName)) { if ($z -match '\bWARN') { $w++ } elseif ($z -match '\bFEHLER|\bERROR') { $e++ } } }
        $o.Add(('PC-Tools-Läufe diese Woche: {0} (Warnungen {1}, Fehler {2})' -f $logs.Count, $w, $e))
    } catch { $o.Add('PC-Tools-Läufe diese Woche: keine') }
    try { $up = (Get-Date) - (Get-CimInstance Win32_OperatingSystem -OperationTimeoutSec 5).LastBootUpTime; $o.Add(('Letzter Neustart vor {0:N1} Tagen' -f $up.TotalDays)) } catch { }
    try { $dv = New-Object IO.DriveInfo $env:SystemDrive; $o.Add(('Laufwerk C: {0:N1} GB frei von {1:N0} GB' -f ($dv.AvailableFreeSpace / 1GB), ($dv.TotalSize / 1GB))) } catch { }
    $o.Add(''); $o.Add((Get-AiCrashText 7))
    $o.Add(''); $o.Add((Get-AiEventText 7 15))
    try {
        $h = @(Get-WuHistory | ForEach-Object { $_ } | Where-Object { try { [datetime]::ParseExact([string]$_.Date, 'dd.MM.yyyy HH:mm', $null) -gt $since } catch { $false } })
        $o.Add(''); $o.Add(('Windows-Updates diese Woche: {0}' -f $h.Count)); foreach ($x in @($h | Select-Object -First 12)) { $o.Add(('- {0} {1}' -f $x.Result, $x.Title)) }
    } catch { }
    return ($o -join "`n")
}
# Gedächtnis je PC (kurze Notizen zu früheren Problemen)
function Get-AiMemoryFile([string]$Dir) { $pc = ($env:COMPUTERNAME -replace '[^\w\-]', '_'); Join-Path (Join-Path $Dir 'Assistant') ('gedaechtnis-{0}.txt' -f $pc) }
function Get-AiChatFile([string]$Dir) { $pc = ($env:COMPUTERNAME -replace '[^\w\-]', '_'); Join-Path (Join-Path $Dir 'Assistant') ('gespraech-{0}.json' -f $pc) }
function Add-AiMemory([string]$Dir, [string]$Text) {
    $f = Get-AiMemoryFile $Dir; $d = Split-Path -Parent $f; if (-not (Test-Path -LiteralPath $d)) { New-Item $d -ItemType Directory -Force | Out-Null }
    $lines = @(); if (Test-Path -LiteralPath $f) { $lines = @([IO.File]::ReadAllLines($f, [Text.Encoding]::UTF8) | Where-Object { $_.Trim() }) }
    foreach ($l in @(([string]$Text -split "`r?`n") | ForEach-Object { $_.Trim().TrimStart('-', '*', ' ') } | Where-Object { $_ -and $_.Length -gt 5 } | Select-Object -First 4)) { $lines += ('{0:dd.MM.yyyy}: {1}' -f (Get-Date), $l) }
    $lines = @($lines | Select-Object -Last 30)
    [IO.File]::WriteAllLines($f, [string[]]$lines, (New-Object Text.UTF8Encoding $false))
}
function Get-AiMemoryText([string]$Dir) {
    $f = Get-AiMemoryFile $Dir
    if (-not (Test-Path -LiteralPath $f)) { return '' }
    try { return (([IO.File]::ReadAllLines($f, [Text.Encoding]::UTF8) | Where-Object { $_.Trim() }) -join "`n") } catch { return '' }
}
# Text fürs Vorlesen (Markdown entfernen)
function ConvertTo-AiSpeechText([string]$Text) {
    $t = [string]$Text
    $t = [regex]::Replace($t, '```[\s\S]*?```', ' (Befehl, siehe Bildschirm) ')
    $t = [regex]::Replace($t, '\[([^\]]+)\]\([^)]+\)', '$1')
    $t = $t -replace '[`*_#>|]', '' -replace '(?m)^\s*[-+]\s+', '' -replace '(?m)^\s*(\d+)\.\s+', '$1: '
    return ($t -replace '\s+', ' ').Trim()
}

# ---------------------------------------------------------------- Verlauf kürzen (Werkzeug-Paare bleiben gültig)
function Test-AiPlainUser($Msg) {
    if (-not $Msg -or [string]$Msg.role -ne 'user') { return $false }
    if ($Msg.content -is [string]) { return $true }
    foreach ($b in @($Msg.content)) { if ($b -and [string]$b.type -eq 'tool_result') { return $false } }
    return $true
}
function Get-AiMsgSize($Msg) { return (ConvertTo-AiJson $Msg).Length }
function Limit-AiHistory([object[]]$Messages, [int]$MaxChars = 48000) {
    # gibt eine List[object] zurück (Aufrufer: NICHT mit @() umschließen)
    $aiList = [System.Collections.Generic.List[object]]::new()
    foreach ($m in @($Messages)) { if ($m) { $aiList.Add($m) } }
    $sizes = [System.Collections.Generic.List[int]]::new(); foreach ($m in $aiList) { $sizes.Add((Get-AiMsgSize $m)) }
    $total = 0; foreach ($s in $sizes) { $total += $s }
    while ($total -gt $MaxChars -and $aiList.Count -gt 1) {
        # nächste "echte" Nutzerfrage nach dem Anfang suchen - alles davor fällt weg
        $cut = -1
        for ($i = 1; $i -lt $aiList.Count; $i++) { if (Test-AiPlainUser $aiList[$i]) { $cut = $i; break } }
        if ($cut -lt 1) { break }
        for ($i = 0; $i -lt $cut; $i++) { $total -= $sizes[0]; $aiList.RemoveAt(0); $sizes.RemoveAt(0) }
    }
    # Anfang muss eine normale Nutzerfrage sein
    while ($aiList.Count -gt 1 -and -not (Test-AiPlainUser $aiList[0])) { $aiList.RemoveAt(0) }
    return , $aiList
}

# ---------------------------------------------------------------- Verbrauch je Monat (Token aus dem usage-Feld)
function Get-AiUsageFile([string]$Dir) { Join-Path (Join-Path $Dir 'Assistant') 'usage.json' }
function Get-AiUsage([string]$File, [string]$Month = '') {
    if (-not $Month) { $Month = (Get-Date).ToString('yyyy-MM') }
    $r = [pscustomobject]@{ Month = $Month; In = [long]0; Out = [long]0; Calls = 0 }
    if ($File -and (Test-Path -LiteralPath $File)) {
        try {
            $j = Get-Content -LiteralPath $File -Raw -Encoding UTF8 | ConvertFrom-Json
            $m = $j.$Month
            if ($m) { $r.In = [long]$m.In; $r.Out = [long]$m.Out; $r.Calls = [int]$m.Calls }
        } catch { }
    }
    return $r
}
function Add-AiUsage([string]$File, [long]$In, [long]$Out, [string]$Month = '') {
    if (-not $Month) { $Month = (Get-Date).ToString('yyyy-MM') }
    $all = [ordered]@{}
    if (Test-Path -LiteralPath $File) {
        try { $j = Get-Content -LiteralPath $File -Raw -Encoding UTF8 | ConvertFrom-Json; foreach ($p in $j.PSObject.Properties) { $all[$p.Name] = [ordered]@{ In = [long]$p.Value.In; Out = [long]$p.Value.Out; Calls = [int]$p.Value.Calls } } } catch { }
    }
    if (-not $all.Contains($Month)) { $all[$Month] = [ordered]@{ In = [long]0; Out = [long]0; Calls = 0 } }
    $all[$Month].In = [long]$all[$Month].In + $In
    $all[$Month].Out = [long]$all[$Month].Out + $Out
    $all[$Month].Calls = [int]$all[$Month].Calls + 1
    # nur die letzten 24 Monate behalten
    $keep = [ordered]@{}; foreach ($k in @($all.Keys | Sort-Object | Select-Object -Last 24)) { $keep[$k] = $all[$k] }
    $d = Split-Path -Parent $File; if ($d) { New-Item $d -ItemType Directory -Force -ErrorAction SilentlyContinue | Out-Null }
    [IO.File]::WriteAllText($File, (ConvertTo-AiJson $keep), (New-Object Text.UTF8Encoding $false))
    return (Get-AiUsage $File $Month)
}
function Test-AiLimitReached($Usage, [long]$Limit) {
    if ($Limit -le 0 -or -not $Usage) { return $false }
    return (([double]$Usage.In + [double]$Usage.Out) -ge [double]$Limit)
}

# ---------------------------------------------------------------- API-Schlüssel (DPAPI, je PC eigene Datei - auch portabel auf dem Stick)
function Get-AiKeyFile([string]$Dir, [string]$Provider = 'anthropic') {
    $pc = $env:COMPUTERNAME; if (-not $pc) { $pc = [Environment]::MachineName }
    $pre = $(if (-not $Provider -or $Provider -eq 'anthropic') { 'claude' } else { $Provider -replace '[^\w\-]', '_' })
    Join-Path (Join-Path $Dir 'Assistant') ('{0}-{1}.key' -f $pre, ($pc -replace '[^\w\-]', '_'))
}
function Save-AiKey([string]$Key, [string]$Dir, [string]$Scope = 'CurrentUser', [string]$Provider = 'anthropic') {
    $k = ([string]$Key).Trim().Trim('"', "'").Trim()
    if (-not $k) { throw 'Kein Schlüssel eingegeben.' }
    if ($k -match '\s') { throw 'Der Schlüssel enthält Leerzeichen - bitte nur den Schlüssel selbst einfügen (ohne Leerzeichen).' }
    Add-Type -AssemblyName System.Security -ErrorAction SilentlyContinue
    $sc = $(if ($Scope -eq 'LocalMachine') { [Security.Cryptography.DataProtectionScope]::LocalMachine } else { [Security.Cryptography.DataProtectionScope]::CurrentUser })
    $entropy = [Text.Encoding]::UTF8.GetBytes('PC-Tools|KI-Assistent')
    $blob = [Security.Cryptography.ProtectedData]::Protect([Text.Encoding]::UTF8.GetBytes($k), $entropy, $sc)
    $f = Get-AiKeyFile $Dir $Provider
    New-Item (Split-Path -Parent $f) -ItemType Directory -Force | Out-Null
    $hdr = [byte[]]@($(if ($Scope -eq 'LocalMachine') { 2 } else { 1 }))
    [IO.File]::WriteAllBytes($f, [byte[]]($hdr + $blob))
    # nur mit Administratorrechten auf SYSTEM/Administratoren beschränken - sonst sperrte sich ein Standardkonto selbst aus
    if ($Scope -eq 'LocalMachine' -and (Get-Command Test-IsAdmin -ErrorAction SilentlyContinue) -and (Test-IsAdmin)) { try { $null = & icacls.exe $f /inheritance:r /grant:r '*S-1-5-18:F' '*S-1-5-32-544:F' 2>&1 } catch { } }
    return $f
}
function Get-AiKey([string]$Dir, [string]$Provider = 'anthropic') {
    $f = Get-AiKeyFile $Dir $Provider
    if (-not (Test-Path -LiteralPath $f)) { return $null }
    try {
        Add-Type -AssemblyName System.Security -ErrorAction SilentlyContinue
        $all = [IO.File]::ReadAllBytes($f)
        if ($all.Length -lt 2) { return $null }
        $sc = $(if ($all[0] -eq 2) { [Security.Cryptography.DataProtectionScope]::LocalMachine } else { [Security.Cryptography.DataProtectionScope]::CurrentUser })
        $blob = New-Object byte[] ($all.Length - 1); [Array]::Copy($all, 1, $blob, 0, $blob.Length)
        $entropy = [Text.Encoding]::UTF8.GetBytes('PC-Tools|KI-Assistent')
        return [Text.Encoding]::UTF8.GetString([Security.Cryptography.ProtectedData]::Unprotect($blob, $entropy, $sc))
    } catch { return $null }
}
function Get-AiKeyState([string]$Dir, [string]$Provider = 'anthropic') {
    $f = Get-AiKeyFile $Dir $Provider
    if (-not (Test-Path -LiteralPath $f)) { return [pscustomobject]@{ Present = $false; Readable = $false; Scope = ''; Date = $null } }
    $sc = ''; try { $b = [IO.File]::ReadAllBytes($f); $sc = $(if ($b[0] -eq 2) { 'LocalMachine' } else { 'CurrentUser' }) } catch { }
    [pscustomobject]@{ Present = $true; Readable = [bool](Get-AiKey $Dir $Provider); Scope = $sc; Date = (Get-Item -LiteralPath $f).LastWriteTime }
}
function Remove-AiKey([string]$Dir, [string]$Provider = 'anthropic') {
    $f = Get-AiKeyFile $Dir $Provider
    if (Test-Path -LiteralPath $f) {
        # vor dem Löschen überschreiben
        try { $len = (Get-Item -LiteralPath $f).Length; [IO.File]::WriteAllBytes($f, (New-Object byte[] $len)) } catch { }
        Remove-Item -LiteralPath $f -Force
    }
}

# ---------------------------------------------------------------- Datenschutz: offensichtliche Geheimnisse vor dem Senden unkenntlich machen
function Protect-AiText([string]$Text) {
    if (-not $Text) { return '' }
    $t = $Text
    $t = [regex]::Replace($t, 'sk-ant-[A-Za-z0-9_\-]{6,}', 'sk-ant-***')
    $t = [regex]::Replace($t, '\b(ghp_|gho_|github_pat_)[A-Za-z0-9_]{10,}', '$1***')
    $t = [regex]::Replace($t, '(?i)\b(kennwort|passwort|password|passwd|pwd|token|api[_\-]?key|secret|geheimnis|pin)\b(\s*[:=]\s*)("[^"]*"|''[^'']*''|\S+)', '$1$2***')
    $t = [regex]::Replace($t, '\b[A-Z0-9]{5}(-[A-Z0-9]{5}){4}\b', 'XXXXX-XXXXX-XXXXX-XXXXX-XXXXX')
    $t = [regex]::Replace($t, '(?i)\b([A-Z]:\\Users\\)(?!Public\\|Default\\|All Users\\)[^\\\r\n"]+', '$1<Benutzer>')
    return $t
}
function Limit-AiText([string]$Text, [int]$Max = 6000) {
    if (-not $Text) { return '' }
    if ($Text.Length -le $Max) { return $Text }
    $half = [int][math]::Floor([double]$Max / 2)
    return $Text.Substring(0, $half) + "`n[... gekürzt ...]`n" + $Text.Substring($Text.Length - $half)
}

# ---------------------------------------------------------------- Protokoll-Zusammenfassung (letzter Lauf)
function Get-AiLogSummary([string]$LogDir, [int]$TailLines = 12, [int]$MaxIssues = 15) {
    if (-not $LogDir -or -not (Test-Path -LiteralPath $LogDir)) { return '' }
    $f = @(Get-ChildItem -LiteralPath $LogDir -Filter 'PCPflege_*.log' -File -ErrorAction SilentlyContinue | Sort-Object LastWriteTime -Descending | Select-Object -First 1)
    if (-not $f.Count) { return '' }
    $lines = @(Get-Content -LiteralPath $f[0].FullName -Encoding UTF8 -ErrorAction SilentlyContinue | Where-Object { $_ -ne $null })
    $ok = @($lines | Where-Object { $_ -match '\[OK\s*\]' }).Count
    $warnL = @($lines | Where-Object { $_ -match '\[WARN\s*\]' })
    $errL = @($lines | Where-Object { $_ -match '\[FEHLER\s*\]' })
    $sb = New-Object Text.StringBuilder
    [void]$sb.AppendLine(('Letzter Lauf: {0} (geändert {1:dd.MM.yyyy HH:mm}), {2} Zeilen: {3}x OK, {4}x WARN, {5}x FEHLER' -f $f[0].Name, $f[0].LastWriteTime, $lines.Count, $ok, $warnL.Count, $errL.Count))
    $iss = @(@($errL) + @($warnL) | Select-Object -First $MaxIssues)
    if ($iss.Count) { [void]$sb.AppendLine('Warnungen und Fehler:'); foreach ($l in $iss) { [void]$sb.AppendLine('  ' + ([string]$l).Trim()) } }
    [void]$sb.AppendLine('Letzte Zeilen:')
    foreach ($l in @($lines | Select-Object -Last $TailLines)) { [void]$sb.AppendLine('  ' + ([string]$l).TrimEnd()) }
    return (Protect-AiText $sb.ToString().TrimEnd())
}

# ---------------------------------------------------------------- System-Prompt
function Get-AiFeatureText([string[]]$Pages, [object[]]$Chapters) {
    $sb = New-Object Text.StringBuilder
    if (@($Pages).Count) { [void]$sb.AppendLine('Seiten in der Navigation: ' + (@($Pages) -join ', ') + '.') }
    $titles = @($Chapters | ForEach-Object { [string]$_.Title } | Where-Object { $_ } | Select-Object -Unique)
    if ($titles.Count) { [void]$sb.AppendLine('Funktionen laut Handbuch: ' + ($titles -join '; ') + '.') }
    return $sb.ToString().TrimEnd()
}
function Get-AiPageHelp([string]$TabName, [object[]]$Chapters, [int]$Max = 1800) {
    if (-not $TabName) { return '' }
    $sb = New-Object Text.StringBuilder
    foreach ($c in @($Chapters | Where-Object { [string]$_.Tab -eq $TabName })) {
        [void]$sb.AppendLine(('Handbuch "{0}": {1}' -f $c.Title, $c.Intro))
        foreach ($it in @($c.Items)) { $p = ([string]$it) -split '\|', 2; if ($p.Count -eq 2) { [void]$sb.AppendLine(('  - {0}: {1}' -f $p[0], $p[1])) } }
    }
    return (Limit-AiText $sb.ToString().TrimEnd() $Max)
}
function Get-AiSystemPrompt([string]$Version, [string]$FeatureText, [string]$ContextText) {
    $p = Get-AiSystemPromptDe $Version $FeatureText $ContextText
    if ($script:UiLang -and $script:UiLang -ne 'de-DE') { $p += "`n`nIMPORTANT: The user interface language is " + $LangAiName[$script:UiLang] + ". Always answer in " + $LangAiName[$script:UiLang] + ", even though these instructions and the PC-Tools data are in German. Name PC-Tools pages and buttons as the user sees them in " + $LangAiName[$script:UiLang] + "." }
    return $p
}
function Get-AiSystemPromptDe([string]$Version, [string]$FeatureText, [string]$ContextText) {
    $p = @"
Du bist der KI-Assistent in PC-Tools (Version $Version), einem Windows-11-Werkzeugkasten für Pflege, Updates, Sicherheit, Reparatur und Fehlersuche. Du hilfst bei genau diesem PC.

So antwortest du:
- Immer auf Deutsch, freundlich und einfach - für Menschen ohne IT-Wissen. Kurze Sätze, keine unnötigen Fachwörter; Fachbegriffe kurz erklären.
- Zuerst die Antwort in 2-5 Sätzen oder einer kurzen Schrittliste. Profi-Details (Befehle, Ereignis-IDs, Registry-Pfade, Hintergründe) nur, wenn danach gefragt wird oder sie wirklich nötig sind.
- Formatierung: **fett** für Wichtiges, Listen mit "- " oder "1. ", Befehle in Codeblöcken mit drei Backticks. Keine Tabellen, keine Überschriften über "##".
- Verweise bevorzugt auf passende Seiten und Funktionen von PC-Tools statt auf fremde Programme.
- Wenn dir Informationen fehlen, frag kurz nach oder nutze ein Lese-Werkzeug (der Nutzer muss es bestätigen).
- Sei ehrlich: Wenn du etwas nicht sicher weißt, sag es. Erfinde keine Messwerte.

Aktionen:
- Du kannst Aktionen NUR über die bereitgestellten Werkzeuge vorschlagen. Jede Aktion zeigt PC-Tools dem Nutzer zur Bestätigung an; erst nach "Ja" wird sie ausgeführt.
- Schlage Aktionen nur vor, wenn sie zur Frage passen, und erkläre vorher in einem Satz, was passiert. Höchstens eine Aufgabe auf einmal starten.
- PC-Tools führt niemals Befehle aus deinen Texten aus. Zeigst du Befehle (PowerShell/cmd), dann nur zum Nachlesen; weise auf Risiken hin.
- Niemals: Kennwörter, Anmeldedaten, Product Keys oder Wiederherstellungsschlüssel auslesen oder umgehen; Sicherheitsfunktionen (Virenschutz, Firewall, Updates, UAC, BitLocker) abschalten lassen.
- Bei Datenverlust-Risiko (Löschen, Zurücksetzen, Neuinstallation) zuerst zu einer Datensicherung bzw. einem Wiederherstellungspunkt raten.

Über PC-Tools:
$FeatureText
Wichtige Abläufe: Aufräumen/Optimieren/Updates laufen im Hintergrund, Fortschritt auf der Seite Protokoll. Die Suche (Strg+K) findet jede Funktion. Die Windows-Reparatur bietet Profile (z.B. Schnell & sicher, Windows Update reparieren, Netzwerk zurücksetzen).
Heute ist der $((Get-Date).ToString('dd.MM.yyyy')).
"@
    if ($ContextText) { $p += "`n`n# Kontext (vom Nutzer zum Senden freigegeben)`n" + $ContextText }
    return $p
}
function New-AiContextText([hashtable]$Parts) {
    # Parts: Seite, Seitenhilfe, System, Zustand, Protokoll - nur gefüllte Teile werden gesendet
    $sb = New-Object Text.StringBuilder
    foreach ($k in @('Seite', 'Seitenhilfe', 'System', 'Zustand', 'Protokoll')) {
        if ($Parts.ContainsKey($k) -and $Parts[$k]) {
            $label = switch ($k) { 'Seite' { 'Aktuell geöffnete Seite' } 'Seitenhilfe' { 'Hilfe zu dieser Seite' } 'System' { 'Systemübersicht' } 'Zustand' { 'Zustand und Score' } 'Protokoll' { 'Letzter PC-Tools-Lauf' } }
            [void]$sb.AppendLine('## ' + $label)
            [void]$sb.AppendLine((Protect-AiText ([string]$Parts[$k])).Trim())
            [void]$sb.AppendLine()
        }
    }
    return $sb.ToString().Trim()
}
function New-AiUserText([string]$Question, [object[]]$Attachments) {
    $sb = New-Object Text.StringBuilder
    foreach ($a in @($Attachments)) {
        if (-not $a -or -not $a.Text) { continue }
        [void]$sb.AppendLine(('<anhang name="{0}">' -f $a.Label))
        [void]$sb.AppendLine((Limit-AiText (Protect-AiText ([string]$a.Text)) 8000).Trim())
        [void]$sb.AppendLine('</anhang>')
        [void]$sb.AppendLine()
    }
    [void]$sb.Append($Question.Trim())
    return $sb.ToString()
}
# Text für "In Claude.ai fragen" (ohne API-Schlüssel: Zwischenablage + Browser)
function New-AiClaudeAiText([string]$Question, [string]$ContextText, [object[]]$Attachments, [string]$Version) {
    $sb = New-Object Text.StringBuilder
    [void]$sb.AppendLine(('Ich nutze das Windows-Wartungsprogramm "PC-Tools" (Version {0}) auf meinem PC. Bitte antworte auf Deutsch, einfach verständlich und Schritt für Schritt; Profi-Details nur, wenn nötig.' -f $Version))
    [void]$sb.AppendLine()
    [void]$sb.AppendLine('Meine Frage:')
    [void]$sb.AppendLine($Question.Trim())
    foreach ($a in @($Attachments)) { if ($a -and $a.Text) { [void]$sb.AppendLine(); [void]$sb.AppendLine(('{0}:' -f $a.Label)); [void]$sb.AppendLine((Limit-AiText (Protect-AiText ([string]$a.Text)) 8000).Trim()) } }
    if ($ContextText) { [void]$sb.AppendLine(); [void]$sb.AppendLine('Infos zu meinem PC:'); [void]$sb.AppendLine($ContextText) }
    return $sb.ToString().TrimEnd()
}

# ---------------------------------------------------------------- Markdown-light (fett, kursiv, Inline-Code, Listen, Codeblöcke, Überschriften)
function ConvertFrom-AiInline([string]$Text) {
    $runs = [System.Collections.Generic.List[object]]::new()
    if (-not $Text) { return , $runs }
    $t = [regex]::Replace($Text, '\[([^\]\r\n]+)\]\((https?://[^)\s]+)\)', '$1 ($2)')
    $rx = [regex]'(\*\*(?<b>[^\r\n]+?)\*\*|__(?<b2>[^\r\n]+?)__|`(?<c>[^`\r\n]+)`|(?<![\*\w])\*(?<i>[^\*\s][^\*\r\n]*?)\*(?![\*\w]))'
    $pos = 0
    foreach ($m in $rx.Matches($t)) {
        if ($m.Index -gt $pos) { $runs.Add([pscustomobject]@{ Text = $t.Substring($pos, $m.Index - $pos); Bold = $false; Italic = $false; Code = $false }) }
        if ($m.Groups['b'].Success) { $runs.Add([pscustomobject]@{ Text = $m.Groups['b'].Value; Bold = $true; Italic = $false; Code = $false }) }
        elseif ($m.Groups['b2'].Success) { $runs.Add([pscustomobject]@{ Text = $m.Groups['b2'].Value; Bold = $true; Italic = $false; Code = $false }) }
        elseif ($m.Groups['c'].Success) { $runs.Add([pscustomobject]@{ Text = $m.Groups['c'].Value; Bold = $false; Italic = $false; Code = $true }) }
        else { $runs.Add([pscustomobject]@{ Text = $m.Groups['i'].Value; Bold = $false; Italic = $true; Code = $false }) }
        $pos = $m.Index + $m.Length
    }
    if ($pos -lt $t.Length) { $runs.Add([pscustomobject]@{ Text = $t.Substring($pos); Bold = $false; Italic = $false; Code = $false }) }
    return , $runs
}
function ConvertFrom-AiMarkdown([string]$Text) {
    # gibt eine List[object] mit Blöcken zurück: Para, Heading, List, Code, Quote, Rule
    $blocks = [System.Collections.Generic.List[object]]::new()
    if (-not $Text) { return , $blocks }
    $lines = $Text -split '\r?\n'
    $para = [System.Collections.Generic.List[string]]::new()
    $list = $null; $code = $null
    $flushPara = { if ($para.Count) { $blocks.Add([pscustomobject]@{ Type = 'Para'; Text = ($para -join "`n"); Runs = (ConvertFrom-AiInline ($para -join "`n")) }); $para.Clear() } }
    for ($i = 0; $i -lt $lines.Count; $i++) {
        $ln = $lines[$i]
        if ($code) {
            if ($ln -match '^\s*```\s*$') { $blocks.Add([pscustomobject]@{ Type = 'Code'; Lang = $code.Lang; Text = ($code.Lines -join "`n") }); $code = $null }
            else { $code.Lines.Add($ln) }
            continue
        }
        if ($ln -match '^\s*```\s*([\w\+\-\.#]*)\s*$') {
            & $flushPara; if ($list) { $blocks.Add($list); $list = $null }
            $code = @{ Lang = $Matches[1]; Lines = [System.Collections.Generic.List[string]]::new() }
            continue
        }
        if ($ln -match '^\s*$') { & $flushPara; if ($list) { $blocks.Add($list); $list = $null }; continue }
        if ($ln -match '^\s{0,3}(#{1,6})\s+(.+?)\s*#*\s*$') {
            & $flushPara; if ($list) { $blocks.Add($list); $list = $null }
            $blocks.Add([pscustomobject]@{ Type = 'Heading'; Level = $Matches[1].Length; Text = $Matches[2]; Runs = (ConvertFrom-AiInline $Matches[2]) }); continue
        }
        if ($ln -match '^\s{0,3}([-*_])(\s*\1){2,}\s*$') { & $flushPara; if ($list) { $blocks.Add($list); $list = $null }; $blocks.Add([pscustomobject]@{ Type = 'Rule' }); continue }
        $mb = [regex]::Match($ln, '^(?<ind>\s*)(?<mk>[-*+•]|\d{1,3}[.)])\s+(?<t>.*)$')
        if ($mb.Success) {
            & $flushPara
            $ordered = $mb.Groups['mk'].Value -match '^\d'
            $lvl = [int][math]::Floor([double]($mb.Groups['ind'].Value.Replace("`t", '    ').Length) / 2); if ($lvl -gt 3) { $lvl = 3 }
            if ($list -and $lvl -eq 0 -and [bool]$list.Ordered -ne [bool]$ordered) { $blocks.Add($list); $list = $null }
            if (-not $list) { $list = [pscustomobject]@{ Type = 'List'; Ordered = $ordered; Items = [System.Collections.Generic.List[object]]::new() } }
            $num = $(if ($ordered) { $mb.Groups['mk'].Value.TrimEnd('.', ')') } else { '' })
            $list.Items.Add([pscustomobject]@{ Level = $lvl; Ordered = $ordered; Number = $num; Text = $mb.Groups['t'].Value; Runs = (ConvertFrom-AiInline $mb.Groups['t'].Value) })
            continue
        }
        if ($list -and $ln -match '^\s{2,}\S') {
            # Fortsetzungszeile eines Listenpunkts
            $last = $list.Items[$list.Items.Count - 1]; $last.Text = $last.Text + ' ' + $ln.Trim(); $last.Runs = (ConvertFrom-AiInline $last.Text); continue
        }
        if ($ln -match '^\s*>\s?(.*)$') {
            & $flushPara; if ($list) { $blocks.Add($list); $list = $null }
            $q = $Matches[1]
            if ($blocks.Count -and $blocks[$blocks.Count - 1].Type -eq 'Quote') { $qb = $blocks[$blocks.Count - 1]; $qb.Text = $qb.Text + "`n" + $q; $qb.Runs = (ConvertFrom-AiInline $qb.Text) }
            else { $blocks.Add([pscustomobject]@{ Type = 'Quote'; Text = $q; Runs = (ConvertFrom-AiInline $q) }) }
            continue
        }
        if ($list) { $blocks.Add($list); $list = $null }
        $para.Add($ln.TrimEnd())
    }
    if ($code) { $blocks.Add([pscustomobject]@{ Type = 'Code'; Lang = $code.Lang; Text = ($code.Lines -join "`n") }) }
    & $flushPara
    if ($list) { $blocks.Add($list) }
    return , $blocks
}
# Chat als Text (für Export)
function ConvertTo-AiTranscript([object[]]$Entries, [string]$Version) {
    $sb = New-Object Text.StringBuilder
    [void]$sb.AppendLine(('PC-Tools {0} - KI-Assistent - Gespräch vom {1:dd.MM.yyyy HH:mm} ({2})' -f $Version, (Get-Date), $env:COMPUTERNAME))
    [void]$sb.AppendLine(('=' * 70))
    foreach ($e in @($Entries)) {
        if (-not $e) { continue }
        $who = switch ([string]$e.Role) { 'user' { 'Du' } 'assistant' { 'Claude' } 'action' { 'Aktion' } default { 'Hinweis' } }
        [void]$sb.AppendLine()
        [void]$sb.AppendLine(('[{0:HH:mm}] {1}:' -f $e.Time, $who))
        [void]$sb.AppendLine(([string]$e.Text).TrimEnd())
    }
    return $sb.ToString()
}

if ($Install) {
    Add-Type -AssemblyName PresentationFramework
    if (-not (Test-IsAdmin)) {
        # erst lokal zwischenlagern (Netzlaufwerke sind mit Admin-Rechten oft nicht erreichbar), dann mit Admin-Rechten weiter
        $tmp = Join-Path $env:TEMP 'PCPflege-Einrichtung'
        New-Item $tmp -ItemType Directory -Force | Out-Null
        foreach ($n in @($UpdateFiles) + 'pcpflege.token') { $f = Join-Path $PSScriptRoot $n; if (Test-Path -LiteralPath $f) { Copy-Item -LiteralPath $f -Destination $tmp -Force } }
        Get-ChildItem $tmp -File | Unblock-File -ErrorAction SilentlyContinue
        try { $null = Start-HiddenPS (Join-Path $tmp 'PCPflege.ps1') @('-Install') -Elevate }
        catch { [Windows.MessageBox]::Show((T ('Die Einrichtung braucht Administratorrechte.')), (T ('PC-Tools')), 'OK', 'Warning') | Out-Null }
        return
    }
    try {
        New-Item $DataDir -ItemType Directory -Force | Out-Null
        $targets = @($DataDir); if (Test-Path 'C:\Tools\PCPflege') { $targets += 'C:\Tools\PCPflege' }
        foreach ($t in $targets) {
            foreach ($n in @($UpdateFiles)) {
                $f = Join-Path $PSScriptRoot $n
                if ((Test-Path -LiteralPath $f) -and ($PSScriptRoot.TrimEnd('\') -ne $t.TrimEnd('\'))) { Copy-Item -LiteralPath $f -Destination (Join-Path $t $n) -Force; Unblock-File -LiteralPath (Join-Path $t $n) -ErrorAction SilentlyContinue }
            }
        }
        $tf = Join-Path $PSScriptRoot 'pcpflege.token'
        if (Test-Path -LiteralPath $tf) { Copy-Item -LiteralPath $tf -Destination (Join-Path $DataDir 'pcpflege.token') -Force }
        $null = Import-PackageToken
        $cfg = Read-PflegeConfig
        if (-not [string]$cfg.Settings.UpdateSource) { $cfg.Settings.UpdateSource = $DefaultUpdateSource }
        Save-PflegeConfig $cfg
        try { Add-MpPreference -ExclusionPath $DataDir -ErrorAction Stop } catch { }
        if ($PSScriptRoot -like (Join-Path $env:TEMP '*')) { Remove-Item -LiteralPath (Join-Path $PSScriptRoot 'pcpflege.token') -Force -ErrorAction SilentlyContinue }
        $null = Start-HiddenPS (Join-Path $DataDir 'PCPflege.ps1')
    } catch { [Windows.MessageBox]::Show((T ('Einrichtung fehlgeschlagen: ' + $_.Exception.Message)), (T ('PC-Tools')), 'OK', 'Error') | Out-Null }
    return
}

# ---- Aufruf über Verknüpfung oder Anmelde-Aufgabe (ohne Oberfläche, ohne Admin-Rechte)
if ($Monitor -or $DeskArrange -or $Topology) {
    $cliLog = Join-Path $env:TEMP 'PCPflege_Monitor.log'
    try {
        if ($Delay -gt 0) { Start-Sleep -Seconds $Delay }
        $cfg = Read-PflegeConfig
        if ($Monitor) { Set-MonitorProfile $Monitor; Invoke-AfterMonitorSwitch $cfg }
        elseif ($Topology) {
            Import-NativeHelpers
            $t = switch ($Topology) { 'Intern' { 1 } 'Duplizieren' { 2 } 'Erweitern' { 4 } 'Extern' { 8 } default { 4 } }
            $r = [PCPflege.Displays]::SetTopology([uint32]$t)
            if ($r -ne 0) { throw ('Umschalten fehlgeschlagen (Fehler {0}).' -f $r) }
            Invoke-AfterMonitorSwitch $cfg
        }
        else { $null = Invoke-DeskArrange -Gap:([bool]$cfg.Desk.ArrangeGap) -AllowRestart -Layout ([string]$cfg.Desk.ArrangeLayout) }
        Add-Content -LiteralPath $cliLog -Value ('{0:yyyy-MM-dd HH:mm:ss} OK {1}{2}{3}' -f (Get-Date), $Monitor, $Topology, $(if ($DeskArrange) { 'Desktop ordnen' })) -Encoding UTF8 -ErrorAction SilentlyContinue
    } catch {
        Add-Content -LiteralPath $cliLog -Value ('{0:yyyy-MM-dd HH:mm:ss} FEHLER {1}' -f (Get-Date), $_.Exception.Message) -Encoding UTF8 -ErrorAction SilentlyContinue
        if (-not $Silent) {
            Add-Type -AssemblyName PresentationFramework
            [Windows.MessageBox]::Show((T ($_.Exception.Message)), (T ('PC-Tools')), 'OK', 'Warning') | Out-Null
        }
    }
    return
}


# ---- Geplante Komplettsicherung (Aufgabe "PC-Tools Komplettsicherung", PCPflege.ps1 -FullBackup)
if ($FullBackup) {
    $cfg = Read-PflegeConfig
    . ([scriptblock]::Create($EngineText))
    $Script:ScriptDir = $PSScriptRoot
    $Script:IsAuto = $true
    $Script:FbLastResult = ''
    $fbLog = Join-Path (Join-Path $DataDir 'Logs') ('Komplettsicherung_{0:yyyyMMdd_HHmmss}.log' -f (Get-Date))
    New-Item (Split-Path $fbLog) -ItemType Directory -Force -ErrorAction SilentlyContinue | Out-Null
    $lk = Enter-PflegeLock 180
    if ($lk -eq $false) {
        $fbNow = (Get-Date).ToString('o')
        try { Add-Content -LiteralPath $fbLog -Value ('{0:HH:mm:ss} [WARN  ] Eine andere PC-Tools-Aufgabe lief zu lange - die Komplettsicherung wurde nicht gestartet.' -f (Get-Date)) -Encoding UTF8 } catch { }
        try { Add-FbHistory (Join-Path $DataDir 'Komplettsicherung') ([ordered]@{ Id = (Get-Date).ToString('yyyyMMdd_HHmmss'); Start = $fbNow; End = $fbNow; Result = 'Übersprungen'; Target = [string]$cfg.FullBackup.Target; Bytes = [int64]0; Minutes = 0; Verify = ''; Message = 'Eine andere PC-Tools-Aufgabe lief zu lange - nicht gestartet.'; Codes = @(); Scheduled = $true; Log = $fbLog }) } catch { }
        try { if ($cfg.FullBackup.NotifyFail) { $null = Send-PflegeNotify 'Komplettsicherung nicht gestartet' 'Eine andere PC-Tools-Aufgabe lief zu lange.' 'Yellow' } } catch { }
        exit 1
    }
    try { Invoke-PflegeRun -Config $cfg -Parts @('FullBackup') -LogFile $fbLog } finally { Exit-PflegeLock $lk }
    try { Write-FleetStatus @(Get-HealthItems (Get-HealthArgs) | ForEach-Object { $_ }) } catch { }
    # Exitcode 1 bei Fehler: dann greift "bei einem Fehler neu versuchen" der geplanten Aufgabe
    if ([string]$Script:FbLastResult -eq 'Fehler') { exit 1 }
    exit 0
}
# ---- Geplante Datensicherung (Aufgabe "PC-Tools Sicherung")
if ($Backup) {
    $cfg = Read-PflegeConfig
    . ([scriptblock]::Create($EngineText))
    $Script:ScriptDir = $PSScriptRoot
    $Script:IsAuto = $true
    Invoke-PflegeRun -Config $cfg -Parts @('Backup') -LogFile (Join-Path (Join-Path $DataDir 'Logs') ('Sicherung_{0:yyyyMMdd_HHmmss}.log' -f (Get-Date)))
    return
}
if ($Auto) {
    try { $null = Import-PackageToken } catch { }
    $cfg = Read-PflegeConfig
    if ($cfg.Settings.UpdateInSchedule -and $cfg.Settings.UpdateSource) {
        $upLog = Join-Path (Join-Path $DataDir 'Logs') ('Update_{0:yyyyMMdd_HHmmss}.log' -f (Get-Date))
        New-Item (Split-Path $upLog) -ItemType Directory -Force | Out-Null
        $man = Get-UpdateManifest $cfg.Settings.UpdateSource
        if ($man -and (Test-NewerVersion $man.Version $AppVersion) -and -not (Test-UpdateWanted $man $cfg)) {
            $due = Get-UpdateDue $man $cfg
            Add-Content -LiteralPath $upLog -Value $(if ($due) { 'Version {0} verfügbar - wird wegen der Update-Verzögerung ab {1:dd.MM.yyyy HH:mm} installiert.' -f $man.Version, $due } else { 'Version {0} wurde zurückgenommen und wird übersprungen.' -f $man.Version }) -Encoding UTF8
        }
        if (Test-UpdateWanted $man $cfg) {
            try {
                Install-PflegeUpdate $cfg.Settings.UpdateSource $man
                Add-Content -LiteralPath $upLog -Value ('Update {0} -> {1} installiert, starte neue Version' -f $AppVersion, $man.Version) -Encoding UTF8
                Start-Process -FilePath (Join-Path $env:SystemRoot 'System32\WindowsPowerShell\v1.0\powershell.exe') -ArgumentList @('-NoProfile', '-ExecutionPolicy', 'Bypass', '-WindowStyle', 'Hidden', '-File', ('"{0}"' -f (Join-Path $DataDir 'PCPflege.ps1')), '-Auto') -WindowStyle Hidden
                return
            } catch { Add-Content -LiteralPath $upLog -Value ('Update fehlgeschlagen: {0}' -f $_.Exception.Message) -Encoding UTF8 }
        }
    }
    . ([scriptblock]::Create($EngineText))
    $Script:ScriptDir = $PSScriptRoot
    $Script:IsAuto = $true
    $parts = @()
    if ($cfg.Schedule.Update)   { $parts += 'Update' }
    if ($cfg.Schedule.Clean)    { $parts += 'Clean' }
    if ($cfg.Schedule.Optimize) { $parts += 'Optimize' }
    if ($cfg.Schedule.OneClick) { $parts = @('OneClick') }
    $lk = Enter-PflegeLock 180
    if ($lk -eq $false) { return }
    try { Invoke-PflegeRun -Config $cfg -Parts $parts } finally { Exit-PflegeLock $lk }
    try { Invoke-AfterRun } catch { }
    return
}
if ($Run) {
    # Parameter sichern, bevor die Engine gleichnamige Variablen setzt
    $runParts = @($Parts -split ',' | Where-Object { $_ }); $runAnalyze = [bool]$Analyze; $runCheck = [bool]$CheckOnly; $runIdent = $RunId
    $runApps = @(); if ($AppsFile -and (Test-Path -LiteralPath $AppsFile)) { $runApps = @(Get-Content -LiteralPath $AppsFile -Encoding UTF8 | Where-Object { $_.Trim() }) }
    $runWg = @(); if ($WingetFile -and (Test-Path -LiteralPath $WingetFile)) { $runWg = @(Get-Content -LiteralPath $WingetFile -Encoding UTF8 | Where-Object { $_.Trim() }) }
    $runJobFile = $JobFile
    $runDir2 = @(); if ($DirectFile -and (Test-Path -LiteralPath $DirectFile)) { $runDir2 = @(Get-Content -LiteralPath $DirectFile -Encoding UTF8 | Where-Object { $_.Trim() }) }
    $runCho = @(); if ($ChocoFile -and (Test-Path -LiteralPath $ChocoFile)) { $runCho = @(Get-Content -LiteralPath $ChocoFile -Encoding UTF8 | Where-Object { $_.Trim() }) }
    $cfg = Read-PflegeConfig
    . ([scriptblock]::Create($EngineText))
    $Script:ScriptDir = $PSScriptRoot
    $runDir = Join-Path $DataDir 'Run'
    New-Item $runDir -ItemType Directory -Force | Out-Null
    $Script:RunId = $runIdent
    $Script:NiniteApps = $runApps
    $Script:WingetApps = $runWg
    $Script:DirectApps = $runDir2
    $Script:ChocoApps = $runCho
    if ($runJobFile -and (Test-Path -LiteralPath $runJobFile)) { $Script:JobOpts = Get-Content -LiteralPath $runJobFile -Raw -Encoding UTF8 | ConvertFrom-Json }
    $Script:StatusFile = Join-Path $runDir ('{0}.status.json' -f $runIdent)
    $Script:CancelFile = Join-Path $runDir ('{0}.cancel' -f $runIdent)
    $log = Join-Path (Join-Path $DataDir 'Logs') ('PCPflege_{0}.log' -f $runIdent)
    $lk = Enter-PflegeLock 90
    if ($lk -eq $false) {
        try { New-Item (Split-Path $log) -ItemType Directory -Force | Out-Null; Add-Content -LiteralPath $log -Value ('{0:HH:mm:ss} [WARN  ] Eine andere PC-Tools-Aufgabe lief zu lange bzw. abgebrochen - diese Aufgabe wurde nicht gestartet.' -f (Get-Date)) -Encoding UTF8 } catch { }
        try { Set-PStatus 'Nicht gestartet - andere Aufgabe lief' 100 $false } catch { }
        return
    }
    try { Invoke-PflegeRun -Config $cfg -Parts $runParts -Analyze:$runAnalyze -CheckOnly:$runCheck -LogFile $log } finally { Exit-PflegeLock $lk }
    if (-not $runAnalyze -and -not $runCheck) { try { Invoke-AfterRun } catch { } }
    Remove-Item $Script:CancelFile -Force -ErrorAction SilentlyContinue
    return
}
# ---- Toolbox automatisch aktuell halten (von der Oberfläche als eigener Hintergrundprozess gestartet)
if ($TbSync) {
    $cfg = $null; try { $cfg = Read-PflegeConfig } catch { }
    . ([scriptblock]::Create($EngineText))
    $Script:ScriptDir = $PSScriptRoot
    try { Invoke-TbAutoSync $cfg } catch { }
    return
}
# ---- Netzwerk-Dokumentation automatisch (Aufgabe als SYSTEM, wöchentlich)
if ($NetDoc) {
    try { Invoke-NdocAuto } catch { }
    return
}
# ---- Fernaufträge von "Meine PCs" (Aufgabe als SYSTEM alle 10 Minuten)
if ($FleetPoll) {
    try { Invoke-FleetPoll } catch { try { Add-Content (Join-Path (Join-Path $DataDir 'Logs') 'Fernauftraege.log') ('{0:yyyy-MM-dd HH:mm} {1}' -f (Get-Date), $_.Exception.Message) -Encoding UTF8 } catch { } }
    try { Send-Integrations | Out-Null } catch { }
    return
}
# ---- Netzwerk-Notfall im Textfenster (vom USB-Stick: Netzwerk-Notfall.cmd)
if ($NetDiag) {
    if (-not (Test-IsAdmin)) { try { Start-Process powershell.exe -Verb RunAs -ArgumentList ('-NoProfile -ExecutionPolicy Bypass -File "{0}" -NetDiag' -f $PSCommandPath) } catch { Write-Host 'Bitte als Administrator starten (Rechtsklick > Als Administrator ausführen).' -ForegroundColor Red; Read-Host 'Enter' }; return }
    try { Invoke-NetDiagConsole } catch { Write-Host ('Fehler: ' + $_.Exception.Message) -ForegroundColor Red; Read-Host 'Enter zum Beenden' }
    return
}
# ---- Windows-Reparatur im Textfenster (vom USB-Stick: Windows-Reparatur.cmd, oder PCPflege.ps1 -WinRepair)
if ($WinRepair) {
    if (-not (Test-IsAdmin)) { try { Start-Process powershell.exe -Verb RunAs -ArgumentList ('-NoProfile -ExecutionPolicy Bypass -File "{0}" -WinRepair' -f $PSCommandPath) } catch { Write-Host 'Bitte als Administrator starten (Rechtsklick > Als Administrator ausführen).' -ForegroundColor Red; Read-Host 'Enter' }; return }
    try { Invoke-WrConsole } catch { Write-Host ('Fehler: ' + $_.Exception.Message) -ForegroundColor Red; Read-Host 'Enter zum Beenden' }
    return
}
# ---- Komplett-Reparatur (Komplett-Reparatur.cmd): tiefgreifend, ohne Rückfragen, mit Super-Log und Neustart - z.B. Surface, auf dem Dienste/Setup nicht mehr starten
if ($FullRepair) {
    if (-not (Test-IsAdmin)) { try { Start-Process powershell.exe -Verb RunAs -ArgumentList ('-NoProfile -ExecutionPolicy Bypass -File "{0}" -FullRepair' -f $PSCommandPath) } catch { Write-Host 'Bitte als Administrator starten (Rechtsklick > Als Administrator ausführen).' -ForegroundColor Red; Read-Host 'Enter' }; return }
    try { Invoke-WrFullRepair } catch { Write-Host ('Fehler: ' + $_.Exception.Message) -ForegroundColor Red; Read-Host 'Enter zum Beenden' }
    return
}
# ---- Skript mit eigenem Zertifikat signieren (PCPflege.ps1 -Sign) - verändert NICHT das Vertrauen des PCs
if ($Sign) {
    try { Invoke-PflegeSign $SignOpts } catch { Write-Host ('Fehler: ' + $_.Exception.Message) -ForegroundColor Red; Read-Host 'Enter zum Beenden' }
    return
}
# ---- Netzwerk-Tiefenanalyse (Netzwerk-Tiefenanalyse.cmd): alle Daten in eine ZIP-Datei
if ($NetDeep) {
    if (-not (Test-IsAdmin)) { try { Start-Process powershell.exe -Verb RunAs -ArgumentList ('-NoProfile -ExecutionPolicy Bypass -File "{0}" -NetDeep{1}' -f $PSCommandPath, $(if ($DeepOpts) { ' -DeepOpts "' + $DeepOpts + '"' } else { '' })) } catch { Write-Host 'Bitte als Administrator starten.' -ForegroundColor Red; Read-Host 'Enter' }; return }
    try { Invoke-NetDeepConsole $DeepOpts } catch { Write-Host ('Fehler: ' + $_.Exception.Message) -ForegroundColor Red; Read-Host 'Enter zum Beenden' }
    return
}
# ---- Erster Start nach vollautomatischer Windows-Installation (vom USB-Stick)
if ($FirstLogon) {
    if (-not (Test-IsAdmin)) { try { $null = Start-HiddenPS $PSCommandPath @('-FirstLogon', ('"{0}"' -f $FirstLogon)) -Elevate } catch { }; return }
    try { Invoke-FirstLogon $FirstLogon } catch { try { Add-Content (Join-Path $env:TEMP 'PCPflege-Erststart.log') $_.Exception.Message } catch { } }
    return
}

# =====================================================================
#  GUI
# =====================================================================
$isAdmin = ([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)
if (-not $isAdmin) {
    try { $null = Start-HiddenPS $PSCommandPath -Elevate } catch { }
    return
}
# ---- Startschutz (9.3): startet eine neue Version zweimal hintereinander nicht, automatisch zurück auf die Vorversion
$StartFile = Join-Path $DataDir 'start.json'
$stPrev = $null; try { $stPrev = Get-Content -LiteralPath $StartFile -Raw -Encoding UTF8 | ConvertFrom-Json } catch { }
$startFails = 0; if ($stPrev -and [string]$stPrev.Version -eq $AppVersion -and -not $stPrev.Ok) { $startFails = [int]$stPrev.Fails + 1 }
if ($startFails -ge 2) {
    $pv = Get-PflegeVorversion
    if ($pv -and $pv -ne $AppVersion) {
        try {
            $null = Restore-PflegeVorversion ('Oberfläche von Version {0} ist {1}x hintereinander nicht gestartet' -f $AppVersion, $startFails)
            Remove-Item -LiteralPath $StartFile -Force -ErrorAction SilentlyContinue
            Set-Content -LiteralPath (Join-Path $DataDir 'rollback-info.txt') -Value ('Version {0} ist mehrmals nicht richtig gestartet. PC-Tools hat deshalb automatisch die Vorversion {1} wiederhergestellt. Version {0} wird nicht erneut automatisch installiert - erst die nächste neuere Version.' -f $AppVersion, $pv) -Encoding UTF8
            $null = Start-HiddenPS $PSCommandPath
            return
        } catch { Write-UpdLog ('Automatische Rücknahme fehlgeschlagen: ' + $_.Exception.Message) }
    }
}
try { [ordered]@{ Version = $AppVersion; Fails = $startFails; Ok = $false; Time = (Get-Date).ToString('o') } | ConvertTo-Json | Set-Content -LiteralPath $StartFile -Encoding UTF8 } catch { }
# Lite-Kennzeichen vom Installationsordner in den Datenordner übernehmen (damit die installierte Kopie ebenfalls Lite ist)
if (-not $Script:IsPortable -and $PSScriptRoot -and (Test-Path -LiteralPath (Join-Path $PSScriptRoot 'lite.txt')) -and -not (Test-Path -LiteralPath (Join-Path $DataDir 'lite.txt'))) { try { Copy-Item -LiteralPath (Join-Path $PSScriptRoot 'lite.txt') -Destination (Join-Path $DataDir 'lite.txt') -Force } catch { } }

try {
    Add-Type -Name ConWin -Namespace PCPflege -MemberDefinition '[DllImport("kernel32.dll")] public static extern System.IntPtr GetConsoleWindow(); [DllImport("user32.dll")] public static extern bool ShowWindow(System.IntPtr h, int n);'
    [PCPflege.ConWin]::ShowWindow([PCPflege.ConWin]::GetConsoleWindow(), 0) | Out-Null
} catch { }

Add-Type -AssemblyName PresentationFramework, PresentationCore, WindowsBase
# Eigene App-Kennung: Windows zeigt dann in der Taskleiste das PC-Tools-Logo statt des PowerShell-Symbols
try {
    Add-Type -Name AppId -Namespace PCPflege -MemberDefinition '[DllImport("shell32.dll", CharSet = CharSet.Unicode)] public static extern int SetCurrentProcessExplicitAppUserModelID(string id);'
    [void][PCPflege.AppId]::SetCurrentProcessExplicitAppUserModelID('RHEDV.PCPflege')
} catch { }

function Esc([string]$s) { [Security.SecurityElement]::Escape($s) }

# ---------------------------------------------------------------- Hell / Dunkel (wie Windows oder fest eingestellt)
function Get-ThemeDark {
    $pref = ''; try { $pref = [string](Read-PflegeConfig).Settings.Theme } catch { }
    if ($pref -like 'Hell*') { return $false }
    if ($pref -like 'Dunkel*') { return $true }
    $v = (Get-ItemProperty 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Themes\Personalize' -Name AppsUseLightTheme -ErrorAction SilentlyContinue).AppsUseLightTheme
    return ($v -eq 0)
}
$Script:Dark = Get-ThemeDark
# ---------------------------------------------------------------- Ladeanzeige (Splash) auf eigenem Thread, zeigt beim Start den Fortschritt
$Script:Splash = $null
function Show-PflegeSplash {
    try {
        $sync = [hashtable]::Synchronized(@{ Status = 'Wird geladen ...'; Ver = [string]$AppVersion; Close = $false; Dark = [bool]$Script:Dark })
        $rs = [runspacefactory]::CreateRunspace(); $rs.ApartmentState = 'STA'; $rs.ThreadOptions = 'ReuseThread'; $rs.Open()
        $rs.SessionStateProxy.SetVariable('sync', $sync)
        $ps = [powershell]::Create(); $ps.Runspace = $rs
        [void]$ps.AddScript({
            try {
                Add-Type -AssemblyName PresentationFramework, PresentationCore, WindowsBase
                $bg = if ($sync.Dark) { '#15181E' } else { '#FFFFFF' }
                $fg = if ($sync.Dark) { '#E8ECF4' } else { '#1F2A44' }
                $sub = if ($sync.Dark) { '#98A2B6' } else { '#6B7890' }
                $track = if ($sync.Dark) { '#2A303A' } else { '#E3E8F2' }
                $xaml = @"
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" WindowStartupLocation="CenterScreen" WindowStyle="None" AllowsTransparency="True" Background="Transparent" ResizeMode="NoResize" ShowInTaskbar="True" Topmost="True" Width="440" Height="210" Title="PC-Tools">
  <Border Background="$bg" CornerRadius="16" BorderBrush="#2D7FF9" BorderThickness="1">
    <Grid Margin="34,28">
      <Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="*"/><RowDefinition Height="Auto"/></Grid.RowDefinitions>
      <StackPanel Orientation="Horizontal">
        <TextBlock FontFamily="Segoe MDL2 Assets" Text="&#xE950;" FontSize="30" Foreground="#2D7FF9" VerticalAlignment="Center"/>
        <StackPanel Margin="14,0,0,0" VerticalAlignment="Center">
          <TextBlock Text="PC-Tools" FontSize="26" FontWeight="SemiBold" Foreground="$fg"/>
          <TextBlock Text="Version $($sync.Ver)  ·  by RH" FontSize="12" Foreground="$sub"/>
        </StackPanel>
      </StackPanel>
      <ProgressBar Grid.Row="2" Height="7" IsIndeterminate="True" Foreground="#2D7FF9" Background="$track" BorderThickness="0" VerticalAlignment="Bottom" Margin="0,0,0,12"/>
      <TextBlock x:Name="S" Grid.Row="3" Text="Wird geladen ..." FontSize="13" Foreground="$sub" TextTrimming="CharacterEllipsis"/>
    </Grid>
  </Border>
</Window>
"@
                $w = [Windows.Markup.XamlReader]::Parse($xaml)
                $s = $w.FindName('S')
                $t = New-Object Windows.Threading.DispatcherTimer
                $t.Interval = [TimeSpan]::FromMilliseconds(120)
                $t.Add_Tick({ try { $s.Text = [string]$sync.Status; if ($sync.Close) { $t.Stop(); $w.Close() } } catch { } })
                $w.Add_SourceInitialized({ $t.Start() })
                [void]$w.ShowDialog()
            } catch { }
        })
        $h = $ps.BeginInvoke()
        $Script:Splash = @{ Sync = $sync; PS = $ps; RS = $rs; Handle = $h }
    } catch { $Script:Splash = $null }
}
function Set-SplashStatus([string]$Text) { try { if ($Script:Splash) { $Script:Splash.Sync.Status = $Text } } catch { } }
function Close-PflegeSplash {
    if (-not $Script:Splash) { return }
    try { $Script:Splash.Sync.Close = $true; Start-Sleep -Milliseconds 120 } catch { }
    try { if ($Script:Splash.Handle.AsyncWaitHandle.WaitOne(3000)) { $Script:Splash.PS.EndInvoke($Script:Splash.Handle) } else { $Script:Splash.PS.Stop() } } catch { }
    try { $Script:Splash.PS.Dispose() } catch { }
    try { $Script:Splash.RS.Close() } catch { }
    $Script:Splash = $null
}
Show-PflegeSplash
