function Convert-ThemeXaml([string]$X) {
    if (-not $Script:Dark) { return $X }
    $X = $X.Replace('Background="#1F2A44"', 'Background="#10131A"')
    $X = [regex]::Replace($X, '(Background|RowBackground)="White"', '$1="#1D2129"')
    $X = [regex]::Replace($X, 'Property="(Background|RowBackground)" Value="White"', 'Property="$1" Value="#1D2129"')
    # Statusfarben als Schrift: auf dunklem Grund hellere Töne, damit sie lesbar bleiben
    foreach ($p in @(@('#C81E1E', '#F87171'), @('#B45309', '#FBBF24'), @('#D97706', '#FBBF24'), @('#15803D', '#4ADE80'), @('#9AA5B8', '#8A94A6'),
                     @('#9A3412', '#FDBA74'), @('#92400E', '#FDBA74'), @('#7F1D1D', '#F87171'), @('#991B1B', '#F87171'), @('#B91C1C', '#F87171'),
                     @('#166534', '#4ADE80'), @('#1E40AF', '#93C5FD'), @('#1D4ED8', '#93C5FD'), @('#2563EB', '#93C5FD'), @('#0E7490', '#67E8F9'), @('#155E75', '#67E8F9'))) {
        $X = $X.Replace(('Foreground="{0}"' -f $p[0]), ('Foreground="{0}"' -f $p[1])).Replace(('Property="Foreground" Value="{0}"' -f $p[0]), ('Property="Foreground" Value="{0}"' -f $p[1]))
    }
    foreach ($k in $ThemeMap.Keys) { if ($k -like '#*') { $X = [regex]::Replace($X, [regex]::Escape($k), $ThemeMap[$k], 'IgnoreCase') } }
    $dark = '<Style TargetType="TextBox"><Setter Property="Background" Value="#232833"/><Setter Property="Foreground" Value="#E4E8EF"/><Setter Property="BorderBrush" Value="#3A4150"/><Setter Property="CaretBrush" Value="#E4E8EF"/></Style>' +
            '<Style TargetType="PasswordBox"><Setter Property="Background" Value="#232833"/><Setter Property="Foreground" Value="#E4E8EF"/><Setter Property="BorderBrush" Value="#3A4150"/><Setter Property="CaretBrush" Value="#E4E8EF"/></Style>' +
            '<Style TargetType="ToolTip"><Setter Property="Background" Value="#232833"/><Setter Property="Foreground" Value="#E4E8EF"/><Setter Property="BorderBrush" Value="#3A4150"/></Style>' + $DarkComboXaml
    $i = $X.IndexOf('</Window.Resources>'); if ($i -gt 0) { $X = $X.Insert($i, $dark) }
    return $X
}
