function New-CheckRow([string]$Name, [string]$Title, [string]$Desc, [string]$NumName = '', [string]$Pre = 'älter als', [string]$Post = 'Tage') {
    $num = ''
    if ($NumName) {
        $num = @"
<StackPanel Grid.Column="1" Orientation="Horizontal" VerticalAlignment="Top" Margin="12,0,0,0">
  <TextBlock Text="$(Esc $Pre)" Foreground="#6B7890" VerticalAlignment="Center" Margin="0,0,6,0"/>
  <TextBox x:Name="$NumName" Width="48" TextAlignment="Center" Padding="2,3"/>
  <TextBlock Text="$(Esc $Post)" Foreground="#6B7890" VerticalAlignment="Center" Margin="6,0,0,0"/>
</StackPanel>
"@
    }
    $descXaml = ''
    if ($Desc) { $descXaml = '<TextBlock Text="{0}" Foreground="#6B7890" FontSize="12" Margin="21,2,0,0" TextWrapping="Wrap"/>' -f (Esc $Desc) }
@"
<Grid Margin="0,5">
  <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
  <StackPanel>
    <CheckBox x:Name="$Name" Content="$(Esc $Title)" FontWeight="SemiBold" Foreground="#1F2A44"/>
    $descXaml
  </StackPanel>
  $num
</Grid>
"@
}
function New-NumRow([string]$Title, [string]$Desc, [string]$NumName, [string]$Pre = '', [string]$Post = '') {
    $descXaml = ''
    if ($Desc) { $descXaml = '<TextBlock Text="{0}" Foreground="#6B7890" FontSize="12" Margin="0,2,0,0" TextWrapping="Wrap"/>' -f (Esc $Desc) }
@"
<Grid Margin="0,5">
  <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
  <StackPanel>
    <TextBlock Text="$(Esc $Title)" FontWeight="SemiBold" Foreground="#1F2A44"/>
    $descXaml
  </StackPanel>
  <StackPanel Grid.Column="1" Orientation="Horizontal" VerticalAlignment="Top" Margin="12,0,0,0">
    <TextBlock Text="$(Esc $Pre)" Foreground="#6B7890" VerticalAlignment="Center" Margin="0,0,6,0"/>
    <TextBox x:Name="$NumName" Width="56" TextAlignment="Center" Padding="2,3"/>
    <TextBlock Text="$(Esc $Post)" Foreground="#6B7890" VerticalAlignment="Center" Margin="6,0,0,0"/>
  </StackPanel>
</Grid>
"@
}
function New-TextRow([string]$Name, [string]$Title, [string]$Desc, [string]$ButtonName = '') {
    $btn = ''
    if ($ButtonName) { $btn = '<Button x:Name="{0}" Grid.Column="1" Content="Durchsuchen..." Style="{{StaticResource Sec}}" Margin="8,0,0,0" Padding="12,4"/>' -f $ButtonName }
@"
<StackPanel Margin="0,6">
  <TextBlock Text="$(Esc $Title)" FontWeight="SemiBold" Foreground="#1F2A44"/>
  <TextBlock Text="$(Esc $Desc)" Foreground="#6B7890" FontSize="12" Margin="0,2,0,4" TextWrapping="Wrap"/>
  <Grid>
    <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
    <TextBox x:Name="$Name" Padding="4,3"/>
    $btn
  </Grid>
</StackPanel>
"@
}
function New-Card([string]$Title, [string[]]$Rows) {
@"
<Border Background="White" CornerRadius="12" Padding="20,16" Margin="0,0,4,16" BorderBrush="#E2E7F0" BorderThickness="1">
  <Border.Effect><DropShadowEffect BlurRadius="18" ShadowDepth="2" Direction="270" Opacity="0.07" Color="Black"/></Border.Effect>
  <StackPanel>
    <StackPanel Orientation="Horizontal" Margin="0,0,0,8"><Border Width="4" Height="16" CornerRadius="2" Margin="0,0,10,0" VerticalAlignment="Center" Background="{StaticResource AccentGrad}"/><TextBlock Text="$(Esc $Title)" FontSize="16" FontWeight="SemiBold" Foreground="#1F2A44" VerticalAlignment="Center"/></StackPanel>
    $($Rows -join "`n")
  </StackPanel>
</Border>
"@
}
