function New-Page([string]$Title, [string]$Sub, [string]$Body) {
    $g = if ($PageGlyphs.ContainsKey($Title)) { $PageGlyphs[$Title] } else { @('&#xE8A5;', '#2D7FF9') }
@"
<ScrollViewer VerticalScrollBarVisibility="Auto" Padding="0,0,8,0">
  <StackPanel>
    <Grid Margin="0,0,0,18">
      <Grid.ColumnDefinitions><ColumnDefinition Width="Auto"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>
      <Border Width="58" Height="58" CornerRadius="16" Background="$($g[1])" Margin="0,2,18,0" VerticalAlignment="Top">
        <Border.Effect><DropShadowEffect BlurRadius="18" ShadowDepth="4" Direction="270" Opacity="0.28" Color="$($g[1])"/></Border.Effect>
        <TextBlock Text="$($g[0])" FontFamily="Segoe MDL2 Assets" FontSize="27" Foreground="#FFFFFF" HorizontalAlignment="Center" VerticalAlignment="Center"/>
      </Border>
      <StackPanel Grid.Column="1">
        <TextBlock Text="$(Esc $Title)" FontSize="28" FontWeight="SemiBold" Foreground="#1F2A44"/>
        <Border Width="64" Height="4" CornerRadius="2" HorizontalAlignment="Left" Margin="0,6,0,0" Background="{StaticResource AccentGrad}"/>
        <TextBlock Text="$(Esc $Sub)" FontSize="13.5" Foreground="#6B7890" Margin="0,10,0,0" TextWrapping="Wrap" MaxWidth="1100" HorizontalAlignment="Left"/>
      </StackPanel>
    </Grid>
    $Body
  </StackPanel>
</ScrollViewer>
"@
}
function New-TabHeader([string]$Glyph, [string]$Text) {
@"
<TabItem.Header>
  <StackPanel Orientation="Horizontal">
    <TextBlock FontFamily="Segoe MDL2 Assets" Text="$Glyph" FontSize="16" Margin="0,0,12,0" VerticalAlignment="Center"/>
    <TextBlock Text="$(Esc $Text)" VerticalAlignment="Center"/>
  </StackPanel>
</TabItem.Header>
"@
}

