# ---------------------------------------------------------------- Seiten

# ---------------------------------------------------------------- Tabellen (DataGrid) - Spalten: 'Überschrift|Bindung|Breite[|Sortierfeld]'
function New-DataGrid([string]$Name, [string[]]$Cols, [string]$Extra = '') {
    $c = foreach ($col in $Cols) {
        $f = $col -split '\|'
        $w = if ($f.Count -gt 2 -and $f[2]) { $f[2] } else { '*' }
        $sort = if ($f.Count -gt 3 -and $f[3]) { ' SortMemberPath="{0}"' -f $f[3] } else { '' }
        '<DataGridTextColumn Header="{0}" Binding="{{Binding {1}}}" Width="{2}"{3}/>' -f (Esc $f[0]), $f[1], $w, $sort
    }
    '<DataGrid x:Name="{0}" {1}><DataGrid.Columns>{2}</DataGrid.Columns></DataGrid>' -f $Name, $Extra, ($c -join '')
}
function New-Bar([string[]]$Buttons, [string]$Left = '') {
    # Buttons: 'Name|Text' (Sekundär) oder 'Name|Text|P' (Primär)
    $b = foreach ($x in $Buttons) {
        $f = $x -split '\|'
        $st = if ($f.Count -gt 2 -and $f[2] -eq 'P') { '' } else { ' Style="{StaticResource Sec}"' }
        '<Button x:Name="{0}" Content="{1}"{2} Padding="12,6" Margin="0,0,8,8"/>' -f $f[0], (Esc $f[1]), $st
    }
    '<WrapPanel Margin="0,0,0,4">{0}{1}</WrapPanel>' -f $Left, ($b -join '')
}
function New-Filter([string]$Name, [int]$Width = 220) {
    '<Grid Width="{1}" Margin="0,0,10,8"><TextBox x:Name="{0}" Padding="24,5,4,5" VerticalContentAlignment="Center"/><TextBlock Text="&#xE721;" FontFamily="Segoe MDL2 Assets" Foreground="#9AA5B8" Margin="7,0,0,0" VerticalAlignment="Center" IsHitTestVisible="False"/></Grid>' -f $Name, $Width
}
function New-Combo([string]$Name, [string[]]$Items, [int]$Width = 170) {
    '<ComboBox x:Name="{0}" Width="{1}" Margin="0,0,10,8" VerticalContentAlignment="Center" SelectedIndex="0">{2}</ComboBox>' -f $Name, $Width, (($Items | ForEach-Object { '<ComboBoxItem Content="{0}"/>' -f (Esc $_) }) -join '')
}
function New-White([string]$Inner, [string]$Extra = '') {
    '<Border Background="White" CornerRadius="10" BorderBrush="#E2E7F0" BorderThickness="1" Padding="4" {0}>{1}</Border>' -f $Extra, $Inner
}

