# ---------------------------------------------------------------- Task-Manager
function New-Tile([string]$Key, [string]$Title, [string]$Color) {
@"
<Border Background="White" CornerRadius="10" BorderBrush="#E2E7F0" BorderThickness="1" Padding="14,10" Margin="0,0,12,12" Width="250">
  <StackPanel>
    <TextBlock Text="$(Esc $Title)" Foreground="#6B7890" FontSize="12"/>
    <TextBlock x:Name="Tm${Key}Val" Text="-" FontSize="22" FontWeight="SemiBold" Foreground="#1F2A44"/>
    <TextBlock x:Name="Tm${Key}Sub" Text="" FontSize="12" Foreground="#6B7890" TextTrimming="CharacterEllipsis"/>
    <Border Height="42" Margin="0,6,0,0" Background="#F7F9FC" CornerRadius="4" ClipToBounds="True">
      <Canvas x:Name="Tm${Key}Canvas"><Polyline x:Name="Tm${Key}Line" Stroke="$Color" StrokeThickness="1.6"/></Canvas>
    </Border>
  </StackPanel>
</Border>
"@
}
$tmBar = (New-Bar @('TmKill|Beenden|P', 'TmKillTree|Prozessbaum beenden', 'TmOpen|Speicherort öffnen', 'TmPause|Anhalten', 'TmResmon|Ressourcenmonitor', 'TmTaskmgr|Windows Task-Manager') ((New-Filter 'TmFilter') + '<CheckBox x:Name="TmApps" Content="Nur Programme mit Fenster" Margin="0,0,14,8" VerticalAlignment="Center"/>')) -replace '^<WrapPanel', '<WrapPanel Grid.Row="2"'
$pageTm = @"
<Grid>
  <Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="*"/></Grid.RowDefinitions>
  <StackPanel>
    <TextBlock Text="Task-Manager" FontSize="24" FontWeight="SemiBold" Foreground="#1F2A44"/>
    <TextBlock Text="Live-Auslastung und laufende Prozesse (aktualisiert alle 2 Sekunden, solange diese Seite offen ist). Spaltenkopf anklicken zum Sortieren." FontSize="13" Foreground="#6B7890" Margin="0,4,0,14" TextWrapping="Wrap"/>
  </StackPanel>
  <WrapPanel Grid.Row="1">$(New-Tile 'Cpu' 'Prozessor' '#2D7FF9')$(New-Tile 'Ram' 'Arbeitsspeicher' '#8B5CF6')$(New-Tile 'Net' 'Netzwerk' '#10B981')$(New-Tile 'Sys' 'System' '#F59E0B')</WrapPanel>
  $tmBar
  <Border Grid.Row="3" Background="White" CornerRadius="10" BorderBrush="#E2E7F0" BorderThickness="1" Padding="4">
    $(New-DataGrid 'TmGrid' @('Name|Name|180', 'PID|Pid|70', 'CPU|CpuText|80|Cpu', 'Arbeitsspeicher|RamText|120|RamMB', 'Threads|Threads|70', 'Beschreibung|Description|240', 'Fenster|Title|*', 'Pfad|Path|*'))
  </Border>
</Grid>
"@

# ---------------------------------------------------------------- Fehlerdaten
$pageDiag = New-Page 'Fehlerdaten' 'Zeigt, was auf diesem PC zuletzt schiefging (Bluescreens, Abstürze, Hardware- und Datenträgerfehler), und sammelt auf Knopfdruck alle wichtigen Protokolle in einer ZIP-Datei - zum Auswerten oder Weitergeben.' ((New-Card 'Letzte Probleme' @(
        ('<WrapPanel>{0}<Button x:Name="BtnProbRefresh" Content="Neu einlesen" Style="{{StaticResource Sec}}" Padding="12,6" Margin="0,0,8,8"/><Button x:Name="BtnProbReliab" Content="Zuverlässigkeitsverlauf" Style="{{StaticResource Sec}}" Padding="12,6" Margin="0,0,8,8"/></WrapPanel>' -f (New-Combo 'ProbDays' @('Letzte 7 Tage', 'Letzte 30 Tage', 'Letzte 90 Tage') 160)),
        '<WrapPanel x:Name="ProbTiles" Margin="0,4,0,6"/>',
        '<TextBlock x:Name="ProbInfo" Text="" Foreground="#6B7890" Margin="0,0,0,6" TextWrapping="Wrap"/>',
        (New-White (New-DataGrid 'ProbGrid' @('Zeit|TimeText|130|Time', 'Art|Cat|170', 'Quelle|Source|190', 'ID|Id|55', 'Beschreibung|Text|*') 'Height="300"')),
        '<TextBox x:Name="ProbDetail" Height="130" Margin="0,8,0,0" IsReadOnly="True" TextWrapping="Wrap" VerticalScrollBarVisibility="Auto" FontFamily="Consolas" FontSize="12" Padding="6"/>')) +
    (New-Card 'Fehlerdaten sammeln' @(
        '<TextBlock Text="Alles landet in einer ZIP-Datei (Standard: auf dem Desktop). Persönliche Dateien werden nicht eingesammelt. Der Vorgang läuft im Hintergrund, den Fortschritt zeigt das Protokoll." Foreground="#6B7890" FontSize="12" TextWrapping="Wrap" Margin="0,0,0,6"/>',
        (New-NumRow 'Zeitraum' 'Wie weit Ereignisse, Abstürze und Berichte zurückreichen.' 'Diag_Days' 'letzte' 'Tage'),
        '<Grid Margin="0,6,0,0"><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions><StackPanel>' +
            (New-CheckRow 'Diag_SysInfo' 'Systeminformationen' 'systeminfo, Hardware, Speicher, Grafik') +
            (New-CheckRow 'Diag_MsInfo' 'Ausführlicher Systembericht (msinfo32)' 'Sehr vollständig, dauert 1-2 Minuten') +
            (New-CheckRow 'Diag_DxDiag' 'DirectX-Diagnose (dxdiag)' 'Bei Grafik- und Tonproblemen') +
            (New-CheckRow 'Diag_Events' 'Ereignisprotokolle' 'System, Anwendung, Setup, Windows Update, Startleistung, Geräteinstallation') +
            (New-CheckRow 'Diag_Reliability' 'Zuverlässigkeitsverlauf' 'Abstürze, Installationen, Fehler als Liste') +
            (New-CheckRow 'Diag_Dumps' 'Absturzabbilder und Fehlerberichte' 'Minidumps, LiveKernelReports, Windows-Fehlerberichte') +
            (New-CheckRow 'Diag_FullDump' 'Auch vollständiges Speicherabbild (MEMORY.DMP)' 'Kann mehrere GB groß sein') +
        '</StackPanel><StackPanel Grid.Column="1" Margin="16,0,0,0">' +
            (New-CheckRow 'Diag_UpdateLogs' 'Windows-Update- und Setup-Protokolle' 'WindowsUpdate.log, Verlauf, CBS, DISM, Panther/Upgrade-Logs') +
            (New-CheckRow 'Diag_Drivers' 'Treiber und Geräte' 'Alle Treiber mit Version, Geräte mit Problemen') +
            (New-CheckRow 'Diag_Network' 'Netzwerk' 'ipconfig, Routen, Verbindungen, WLAN, Proxy, Verbindungstest') +
            (New-CheckRow 'Diag_Software' 'Programme, Dienste, Autostart, Aufgaben' 'Listen als CSV') +
            (New-CheckRow 'Diag_Disks' 'Datenträger' 'Zustand, SMART-Zähler, Partitionen') +
            (New-CheckRow 'Diag_Power' 'Energie' 'Standby, Aufwachgründe, Akkubericht') +
            (New-CheckRow 'Diag_PflegeLogs' 'Protokolle von PC-Tools' 'Letzte Läufe und Einstellungen') +
        '</StackPanel></Grid>',
        (New-TextRow 'Diag_Target' 'Speicherort der ZIP-Datei' 'Leer lassen = Desktop' 'BtnDiagBrowse'),
        '<WrapPanel Margin="0,8,0,0"><Button x:Name="BtnDiagRun" Content="Fehlerdaten jetzt sammeln"/><Button x:Name="BtnDiagOpen" Content="Letzte ZIP-Datei zeigen" Style="{StaticResource Sec}"/></WrapPanel>')))

# ---------------------------------------------------------------- Computerverwaltung
$subTabStyle = @'
<TabControl.Resources>
  <Style TargetType="TabItem">
    <Setter Property="Foreground" Value="#1F2A44"/>
    <Setter Property="FontSize" Value="13"/>
    <Setter Property="Template">
      <Setter.Value>
        <ControlTemplate TargetType="TabItem">
          <Border x:Name="Bd" Background="#E3E8F2" Padding="14,7" Margin="0,0,6,10" CornerRadius="16" Cursor="Hand">
            <ContentPresenter ContentSource="Header" VerticalAlignment="Center"/>
          </Border>
          <ControlTemplate.Triggers>
            <Trigger Property="IsMouseOver" Value="True"><Setter TargetName="Bd" Property="Background" Value="#D3DBEA"/></Trigger>
            <Trigger Property="IsSelected" Value="True"><Setter TargetName="Bd" Property="Background" Value="#2D7FF9"/><Setter Property="Foreground" Value="White"/></Trigger>
          </ControlTemplate.Triggers>
        </ControlTemplate>
      </Setter.Value>
    </Setter>
  </Style>
</TabControl.Resources>
<TabControl.Template>
  <ControlTemplate TargetType="TabControl">
    <DockPanel><WrapPanel DockPanel.Dock="Top" IsItemsHost="True"/><ContentPresenter ContentSource="SelectedContent"/></DockPanel>
  </ControlTemplate>
</TabControl.Template>
'@
function New-SubTab([string]$Header, [string]$Name, [string]$Body) { '<TabItem Header="{0}" x:Name="{1}">{2}</TabItem>' -f (Esc $Header), $Name, $Body }
# Standard-Aufbau: Leiste oben, Tabelle, Detailtext unten
function New-ListPage([string]$Bar, [string]$Grid, [string]$Detail, [string]$Hint = '') {
    $h = if ($Hint) { '<TextBlock Text="{0}" Foreground="#6B7890" FontSize="12" TextWrapping="Wrap" Margin="0,0,0,8"/>' -f (Esc $Hint) } else { '' }
@"
<Grid>
  <Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="*"/><RowDefinition Height="Auto"/></Grid.RowDefinitions>
  <StackPanel>$h$Bar</StackPanel>
  <Border Grid.Row="1" Background="White" CornerRadius="10" BorderBrush="#E2E7F0" BorderThickness="1" Padding="4">$Grid</Border>
  <TextBox x:Name="$Detail" Grid.Row="2" Height="96" Margin="0,8,0,0" IsReadOnly="True" TextWrapping="Wrap" VerticalScrollBarVisibility="Auto" Padding="6" Background="White" BorderBrush="#E2E7F0"/>
</Grid>
"@
}

$dkFs = (New-Combo 'DkFs' @('NTFS', 'exFAT', 'FAT32', 'ReFS') 150) -replace '^<ComboBox', '<ComboBox Grid.Column="1" HorizontalAlignment="Left"'
$tabDisks = @"
<ScrollViewer VerticalScrollBarVisibility="Auto" Padding="0,0,8,0"><StackPanel>
  $(New-Bar @('BtnDkRefresh|Aktualisieren', 'BtnDkMgmt|Windows-Datenträgerverwaltung') '<TextBlock Text="System- und Bootlaufwerke sind gesperrt. Datenträger auswählen - darunter Partitionen und Zustand (SMART)." Foreground="#6B7890" VerticalAlignment="Center" Margin="0,0,16,8"/>')
  $(New-White (New-DataGrid 'DkGrid' @('Nr|Number|40', 'Modell|Model|*', 'Seriennummer|Serial|150', 'Bus|Bus|70', 'Typ|Media|60', 'Größe|SizeText|90|Size', 'Stil|Style|60', 'Status|Status|120', 'Zustand|HealthText|80', 'Hinweis|Hint|200') 'Height="170"'))
  <Grid Margin="0,10,0,0">
    <Grid.ColumnDefinitions><ColumnDefinition Width="4*"/><ColumnDefinition Width="4*"/><ColumnDefinition Width="6*"/></Grid.ColumnDefinitions>
    <StackPanel><TextBlock Text="Partitionen" FontWeight="SemiBold" Margin="2,0,0,4"/>$(New-White (New-DataGrid 'DkParts' @('Nr|Number|35', 'LW|Letter|40', 'Typ|Type|*', 'Größe|SizeText|80', 'Dateisystem|FileSystem|80', 'Bezeichnung|Label|*') 'Height="210"'))</StackPanel>
    <StackPanel Grid.Column="1" Margin="10,0,0,0"><TextBlock Text="Zustand" FontWeight="SemiBold" Margin="2,0,0,4"/>$(New-White (New-DataGrid 'DkHealth' @('Eigenschaft|Name|*', 'Wert|Value|*') 'Height="210"'))</StackPanel>
    <StackPanel Grid.Column="2" Margin="10,0,0,0"><TextBlock x:Name="DkSmartTitle" Text="SMART-Attribute" FontWeight="SemiBold" Margin="2,0,0,4"/>$(New-White (New-DataGrid 'DkSmart' @('ID|Id|70', 'Attribut|Name|*', 'Akt.|Cur|45', 'Min.|Worst|45', 'Schw.|Thr|45', 'Rohwert|Raw|90', 'Bewertung|State|110') 'Height="210"'))</StackPanel>
  </Grid>
  <Border Background="White" CornerRadius="10" BorderBrush="#E2E7F0" BorderThickness="1" Padding="16,12" Margin="0,12,0,0">
    <StackPanel>
      <TextBlock Text="Datenträger bereinigen, initialisieren und formatieren" FontSize="15" FontWeight="SemiBold" Foreground="#1F2A44"/>
      <Grid Margin="0,8,0,0">
        <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="*"/><ColumnDefinition Width="1.4*"/></Grid.ColumnDefinitions>
        <StackPanel Margin="0,0,16,0">
          <TextBlock Text="1. Bereinigung" FontWeight="SemiBold" Margin="0,0,0,4"/>
          <RadioButton x:Name="DkQuick" GroupName="DkClean" IsChecked="True" Content="Schnell - alle Partitionen entfernen (Sekunden)" Margin="0,2"/>
          <RadioButton x:Name="DkSecure" GroupName="DkClean" Content="Sicher - komplett mit Nullen überschreiben (Stunden)" Margin="0,2"/>
          <TextBlock Text="Bei SSDs ist Überschreiben wegen Wear-Leveling nicht zuverlässig und belastet den Speicher - dort reicht Schnell." Foreground="#6B7890" FontSize="11" TextWrapping="Wrap" Margin="0,4,0,0"/>
          <TextBlock Text="2. Partitionsstil" FontWeight="SemiBold" Margin="0,12,0,4"/>
          $(New-Combo 'DkStyle' @('GPT - empfohlen (UEFI, auch über 2 TB)', 'MBR - ältere Systeme / BIOS (max. 2 TB)', 'Keiner - RAW lassen (z.B. für Linux)') 300)
        </StackPanel>
        <StackPanel Grid.Column="1" Margin="0,0,16,0">
          <TextBlock Text="3. Partition und Formatierung" FontWeight="SemiBold" Margin="0,0,0,4"/>
          <CheckBox x:Name="DkCreate" Content="Neue Partition anlegen und formatieren" IsChecked="True" Margin="0,2,0,6"/>
          <Grid>
            <Grid.ColumnDefinitions><ColumnDefinition Width="100"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>
            <Grid.RowDefinitions><RowDefinition/><RowDefinition/><RowDefinition/><RowDefinition/><RowDefinition/><RowDefinition/></Grid.RowDefinitions>
            <TextBlock Text="Dateisystem" VerticalAlignment="Center"/>$dkFs
            <TextBlock Grid.Row="1" Text="Clustergröße" VerticalAlignment="Center"/>$((New-Combo 'DkCluster' @('Standard', '4 KB', '8 KB', '16 KB', '32 KB', '64 KB') 150) -replace '^<ComboBox', '<ComboBox Grid.Row="1" Grid.Column="1" HorizontalAlignment="Left"')
            <TextBlock Grid.Row="2" Text="Bezeichnung" VerticalAlignment="Center"/><TextBox x:Name="DkLabel" Grid.Row="2" Grid.Column="1" Width="150" HorizontalAlignment="Left" Margin="0,0,0,8" Padding="4,3"/>
            <TextBlock Grid.Row="3" Text="Laufwerk" VerticalAlignment="Center"/><ComboBox x:Name="DkLetter" Grid.Row="3" Grid.Column="1" Width="150" HorizontalAlignment="Left" Margin="0,0,0,8"/>
            <TextBlock Grid.Row="4" Text="Größe" VerticalAlignment="Center"/>
            <StackPanel Grid.Row="4" Grid.Column="1" Orientation="Horizontal" Margin="0,0,0,8"><CheckBox x:Name="DkMax" Content="Maximal" IsChecked="True" VerticalAlignment="Center"/><TextBox x:Name="DkSize" Width="70" Margin="10,0,6,0" Padding="4,3" IsEnabled="False"/><TextBlock Text="GB" VerticalAlignment="Center"/></StackPanel>
            <StackPanel Grid.Row="5" Grid.ColumnSpan="2" Orientation="Horizontal"><RadioButton x:Name="DkFQuick" GroupName="DkFmt" Content="Schnellformatierung" IsChecked="True" Margin="0,0,14,0"/><RadioButton x:Name="DkFFull" GroupName="DkFmt" Content="Vollständig (prüft alle Sektoren)"/></StackPanel>
          </Grid>
        </StackPanel>
        <StackPanel Grid.Column="2">
          <WrapPanel><Button x:Name="DkRun" Content="Ausführen ..." IsEnabled="False"/><Button x:Name="DkCancel" Content="Überschreiben abbrechen" Style="{StaticResource Sec}" IsEnabled="False"/></WrapPanel>
          <ProgressBar x:Name="DkProgress" Height="6" Margin="0,4,0,4" Foreground="#2D7FF9" Background="#EEF2F8" BorderThickness="0"/>
          <TextBlock x:Name="DkStatus" Text="Bereit." Foreground="#1F2A44" FontWeight="SemiBold" Margin="0,0,0,4"/>
          <TextBox x:Name="DkLog" Height="150" IsReadOnly="True" FontFamily="Consolas" FontSize="12" VerticalScrollBarVisibility="Auto" TextWrapping="Wrap" Padding="6"/>
        </StackPanel>
      </Grid>
    </StackPanel>
  </Border>
</StackPanel></ScrollViewer>
"@
