$tabEv = New-ListPage (New-Bar @('EvRefresh|Anzeigen|P', 'EvMmc|Ereignisanzeige') ((New-Combo 'EvLog' @('System', 'Anwendung', 'Setup', 'Sicherheit', 'Windows Update', 'Anmeldungen/Profile', 'PowerShell') 170) + (New-Combo 'EvLevel' @('Kritisch und Fehler', 'Mit Warnungen', 'Alle Ebenen') 160) + (New-Combo 'EvDays' @('Letzte 24 Stunden', 'Letzte 7 Tage', 'Letzte 30 Tage') 150) + (New-Filter 'EvFilter' 180))) `
    (New-DataGrid 'EvGrid' @('Zeit|TimeText|130|Time', 'Ebene|LevelText|80', 'Quelle|Source|200', 'ID|Id|60', 'Meldung|Text|*')) 'EvDetail'
$tabUsers = @"
<Grid>
