  $(New-Bar @('UsrNew|Neuer Benutzer|P', 'UsrPwd|Kennwort setzen', 'UsrEnable|Aktivieren', 'UsrDisable|Deaktivieren', 'UsrAdmin|Administrator ja/nein', 'UsrDelete|Löschen', 'UsrRefresh|Aktualisieren', 'UsrMmc|Benutzerverwaltung'))
  <Border Grid.Row="1" Background="White" CornerRadius="10" BorderBrush="#E2E7F0" BorderThickness="1" Padding="4">$(New-DataGrid 'UsrGrid' @('Benutzer|Name|160', 'Vollständiger Name|FullName|*', 'Aktiv|EnabledText|60', 'Administrator|AdminText|100', 'Letzte Anmeldung|LastText|140|Last', 'Kennwort geändert|PwdText|140', 'Beschreibung|Description|*'))</Border>
