  <Border Grid.Row="3" Background="White" CornerRadius="10" BorderBrush="#E2E7F0" BorderThickness="1" Padding="4">$(New-DataGrid 'SesGrid' @('Computer|Client|160', 'Benutzer|User|160', 'Datei/Sitzung|Item|*', 'Seit|Since|120') 'Height="160"')</Border>
