# ---------------------------------------------------------------- Treiber
$pageDrv = New-Page 'Treiber' 'Zeigt alle Treiber dieses PCs mit Version, Datum und Zustand und bringt sie auf den neuesten Stand - Grafik direkt bei NVIDIA und Intel, alles andere über Windows Update (inkl. optionaler Treiber) und das Hersteller-Tool (HP, Dell, Lenovo).' ((New-Card 'Alles auf einmal' @(
        '<TextBlock Text="Reihenfolge: Treiber sichern, Wiederherstellungspunkt, Grafik (NVIDIA/Intel direkt), alle Treiber aus Windows Update, Treiber und BIOS über das Hersteller-Tool." Foreground="#6B7890" FontSize="12" TextWrapping="Wrap" Margin="0,0,0,8"/>',
        '<WrapPanel><Button x:Name="BtnDrvAll" Content="Alle Treiber jetzt aktualisieren"/><Button x:Name="BtnDrvCheck" Content="Nur prüfen" Style="{StaticResource Sec}"/><Button x:Name="BtnDrvDevMgr" Content="Geräte mit Problemen anzeigen" Style="{StaticResource Sec}"/></WrapPanel>',
        (New-CheckRow 'Update_DriverBackup' 'Vorher alle Treiber sichern' 'pnputil exportiert alle installierten Treiberpakete (die letzten 3 Sicherungen bleiben). Damit lässt sich jeder Treiber zurückspielen.'),
        (New-CheckRow 'Update_IntelDirect' 'Intel-Grafiktreiber direkt von Intel' 'Neuester Treiber aus dem Intel-Download-Center (Prüfsumme und Signatur werden geprüft) - meist deutlich neuer als beim Laptop-Hersteller.'),
        (New-CheckRow 'Update_GpuDriver' 'Grafiktreiber auch bei der automatischen Pflege aktualisieren' 'Die normale Update-Pflege (Zeitplan und "Updates") prüft dann zusätzlich NVIDIA und Intel.'))) +
    (New-Card 'Grafikkarten' @(
        '<StackPanel x:Name="GpuPanel"><TextBlock Text="Wird beim Öffnen der Seite geprüft ..." Foreground="#6B7890"/></StackPanel>',
        '<WrapPanel Margin="0,8,0,0"><Button x:Name="BtnGpuCheck" Content="Neu prüfen" Style="{StaticResource Sec}"/><Button x:Name="BtnGpuUpdate" Content="Grafiktreiber aktualisieren"/></WrapPanel>')) +
    (New-Card 'Intel-Geräte' @(
        '<TextBlock Text="Alle Intel-Komponenten dieses PCs mit installiertem Treiber. Grafik, WLAN und Bluetooth holt PC-Tools direkt aus dem Intel-Download-Center (Prüfsumme und Signatur werden geprüft) und installiert sie still - genau die Updates, die auch der Intel Driver &amp; Support Assistant anzeigt." Foreground="#6B7890" FontSize="12" TextWrapping="Wrap" Margin="0,0,0,8"/>',
        '<TextBlock x:Name="IntelDsaInfo" Text="" FontSize="12" Foreground="#475569" TextWrapping="Wrap" Margin="0,0,0,6"/>',
        '<StackPanel x:Name="IntelPanel"><TextBlock Text="Wird mit der Treiberliste eingelesen ..." Foreground="#6B7890"/></StackPanel>',
        '<WrapPanel Margin="0,8,0,0"><Button x:Name="BtnIntelGfx" Content="Alle Intel-Treiber aktualisieren"/><Button x:Name="BtnIntelWifi" Content="Nur WLAN und Bluetooth" Style="{StaticResource Sec}"/><Button x:Name="BtnIntelCheck" Content="Nur prüfen" Style="{StaticResource Sec}"/><Button x:Name="BtnIntelDsa" Content="Intel-Assistent öffnen" Style="{StaticResource Sec}"/></WrapPanel>')) +
    (New-Card 'Treiber aus Windows Update' @(
        '<TextBlock Text="Auch optionale Treiber, die Windows sonst nicht von selbst installiert (z.B. Chipsatz, Kartenleser, Firmware)." Foreground="#6B7890" FontSize="12" TextWrapping="Wrap" Margin="0,0,0,6"/>',
        '<StackPanel x:Name="WuDrvPanel"/>',
        '<TextBlock x:Name="WuDrvInfo" Text="Noch nicht gesucht." Foreground="#1F2A44" FontWeight="SemiBold" Margin="0,6,0,6"/>',
        '<WrapPanel><Button x:Name="BtnWuDrvScan" Content="Suchen" Style="{StaticResource Sec}"/><Button x:Name="BtnWuDrvInstall" Content="Ausgewählte installieren" IsEnabled="False"/></WrapPanel>')) +
