# ---------------------------------------------------------------- Fehlersuche und Reparatur
$pageRepair = New-Page 'Fehlersuche und Reparatur' 'Erst suchen, dann gezielt reparieren: Die Fehlersuche prüft Windows, Datenträger, Updates, Netzwerk, Dienste, Geräte und Sicherheit und schlägt die passenden Reparaturen vor. Alles läuft im Hintergrund und steht im Protokoll.' ((New-Card '1. Fehlersuche' @(
        '<TextBlock Text="Dauert etwa eine Minute und ändert nichts am PC." Foreground="#6B7890" FontSize="12" Margin="0,0,0,8"/>',
        '<WrapPanel><Button x:Name="BtnRepScan" Content="Fehlersuche starten"/><Button x:Name="BtnRepPick" Content="Empfohlene Reparaturen auswählen" Style="{StaticResource Sec}" IsEnabled="False"/></WrapPanel>',
        '<TextBlock x:Name="RepScanInfo" Text="" FontWeight="SemiBold" Foreground="#1F2A44" Margin="0,2,0,6" TextWrapping="Wrap"/>',
        (New-White (New-DataGrid 'RepFindings' @('Bereich|Area|190', 'Ergebnis|State|110', 'Befund|Detail|*', 'Empfehlung|FixText|340') 'Height="330"')))) +
    (New-Card 'Dienste, die nicht starten' @(
        '<TextBlock Text="Findet Dienste mit Starttyp Automatisch, die nicht laufen, und sagt WARUM (Abhängigkeit, Starttyp, Konto, deaktiviert, Fehlercode). &quot;Reparieren&quot; setzt Kerndienste auf die Windows-Vorgabe, startet Abhängigkeiten in der richtigen Reihenfolge und startet die Dienste. Dienste, die nur bei Bedarf starten (Trigger), werden als normal erkannt." Foreground="#6B7890" FontSize="12.5" TextWrapping="Wrap" Margin="0,0,0,8"/>',
        '<WrapPanel><Button x:Name="BtnSvcCheck" Content="Dienste prüfen (warum starten sie nicht?)"/><Button x:Name="BtnSvcFix" Content="Nicht startende Dienste reparieren" Style="{StaticResource Sec}"/></WrapPanel>',
        '<TextBlock x:Name="SvcFixState" Text="" Foreground="#1F2A44" FontWeight="SemiBold" Margin="0,6,0,4" TextWrapping="Wrap"/>',
        '<Border Background="#EDF1F7" BorderBrush="#C7D0DE" BorderThickness="1" CornerRadius="6" Padding="2" Margin="0,0,0,8"><TextBox x:Name="SvcFixOut" IsReadOnly="True" FontFamily="Consolas" FontSize="13" Height="280" VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Auto" TextWrapping="NoWrap" Background="#EDF1F7" Foreground="#17202E" BorderThickness="0" Padding="8,6"/></Border>',
        '<Button x:Name="BtnSvcCopy" Content="Protokoll kopieren" Style="{StaticResource Sec}" HorizontalAlignment="Left"/>')) +
    (New-Card 'Store-Apps, die nicht starten' @(
        '<TextBlock Text="Findet Store-Apps (z.B. das neue Outlook), die eingetragen sind, deren Programmordner aber fehlt - typisch nach großen Windows-Updates. Prüft außerdem beschädigte App-Laufzeiten und WebView2. &quot;Reparieren&quot; entfernt defekte Store-Apps und öffnet ihre Store-Seite zum Neuinstallieren; defekte Laufzeiten und WebView2 werden neu installiert." Foreground="#6B7890" FontSize="12.5" TextWrapping="Wrap" Margin="0,0,0,8"/>',
        '<WrapPanel><Button x:Name="BtnAppxCheck" Content="Store-Apps prüfen"/><Button x:Name="BtnAppxFix" Content="Defekte Store-Apps reparieren" Style="{StaticResource Sec}"/></WrapPanel>',
        '<TextBlock x:Name="AppxFixState" Text="" Foreground="#1F2A44" FontWeight="SemiBold" Margin="0,6,0,4" TextWrapping="Wrap"/>',
        '<Border Background="#EDF1F7" BorderBrush="#C7D0DE" BorderThickness="1" CornerRadius="6" Padding="2" Margin="0,0,0,8"><TextBox x:Name="AppxFixOut" IsReadOnly="True" FontFamily="Consolas" FontSize="13" Height="220" VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Auto" TextWrapping="NoWrap" Background="#EDF1F7" Foreground="#17202E" BorderThickness="0" Padding="8,6"/></Border>',
        '<Button x:Name="BtnAppxCopy" Content="Protokoll kopieren" Style="{StaticResource Sec}" HorizontalAlignment="Left"/>')) +
    (New-Card 'Geräte mit Problemen (Geräte-Manager)' @(
        '<TextBlock Text="Findet Geräte mit Ausrufezeichen im Geräte-Manager und sagt, was los ist. &quot;Reparieren&quot; entfernt verwaiste Einträge (z.B. ein alter TAP-/VPN-Adapter, dessen Treiber gelöscht wurde) und schaltet Bluetooth-Dienste ohne Treiber (z.B. bei gekoppelten Handys/Tablets unter &quot;Andere Geräte&quot;) für ihr Gerät aus - dann kommen sie nicht wieder." Foreground="#6B7890" FontSize="12.5" TextWrapping="Wrap" Margin="0,0,0,8"/>',
        '<WrapPanel><Button x:Name="BtnDevCheck" Content="Geräte prüfen"/><Button x:Name="BtnDevFix" Content="Geräte-Probleme reparieren" Style="{StaticResource Sec}"/><Button x:Name="BtnDevDrivers" Content="Treiber für Problemgeräte suchen" Style="{StaticResource Sec}" ToolTip="Gezielt über Windows Update, sonst über das Treiberpaket des Herstellers (HP, Lenovo, Dell)"/></WrapPanel>',
        '<TextBlock x:Name="DevFixState" Text="" Foreground="#1F2A44" FontWeight="SemiBold" Margin="0,6,0,4" TextWrapping="Wrap"/>',
        '<Border Background="#EDF1F7" BorderBrush="#C7D0DE" BorderThickness="1" CornerRadius="6" Padding="2" Margin="0,0,0,8"><TextBox x:Name="DevFixOut" IsReadOnly="True" FontFamily="Consolas" FontSize="13" Height="220" VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Auto" TextWrapping="NoWrap" Background="#EDF1F7" Foreground="#17202E" BorderThickness="0" Padding="8,6"/></Border>',
        '<Button x:Name="BtnDevCopy" Content="Protokoll kopieren" Style="{StaticResource Sec}" HorizontalAlignment="Left"/>')) +
    (New-Card '2. Reparieren' @(
        '<TextBlock Text="Schnellwahl" FontWeight="SemiBold" Margin="0,0,0,4"/>',
        '<WrapPanel><Button x:Name="BtnRepStd" Content="Standard-Reparatur" Style="{StaticResource Sec}" Padding="12,6"/><Button x:Name="BtnRepWu" Content="Windows Update" Style="{StaticResource Sec}" Padding="12,6"/><Button x:Name="BtnRepNet" Content="Internet / Netzwerk" Style="{StaticResource Sec}" Padding="12,6"/><Button x:Name="BtnRepApps" Content="Startmenü, Store und Apps" Style="{StaticResource Sec}" Padding="12,6"/><Button x:Name="BtnRepDisk" Content="Datenträger" Style="{StaticResource Sec}" Padding="12,6"/><Button x:Name="BtnRepNone" Content="Auswahl leeren" Style="{StaticResource Sec}" Padding="12,6"/></WrapPanel>',
        '<StackPanel x:Name="RepGroups" Margin="0,6,0,0"/>',
        (New-TextRow 'RepSource' 'Reparaturquelle (optional)' 'Windows-ISO oder install.wim - wenn DISM über Windows Update nicht reparieren kann. Leer = Windows Update.' 'BtnRepSource'),
        '<TextBlock x:Name="RepSelInfo" Text="" Foreground="#475569" FontSize="12" Margin="0,6,0,6" TextWrapping="Wrap"/>',
        '<WrapPanel><Button x:Name="BtnRepRun" Content="Ausgewählte Reparaturen starten"/></WrapPanel>')) +
    (New-Card '3. Wiederherstellungspunkte' @(
        '<TextBlock Text="Stand von Windows, Treibern und Programmen zu einem früheren Zeitpunkt - eigene Dateien bleiben unberührt." Foreground="#6B7890" FontSize="12" Margin="0,0,0,8" TextWrapping="Wrap"/>',
        (New-White (New-DataGrid 'RepPoints' @('Erstellt|Date|170', 'Beschreibung|Desc|*', 'Art|Kind|200', 'Nr.|Seq|60') 'Height="180"')),
        '<WrapPanel Margin="0,8,0,0"><Button x:Name="BtnRpCreate" Content="Jetzt Punkt erstellen" Style="{StaticResource Sec}"/><Button x:Name="BtnRpRestore" Content="Auf ausgewählten Punkt zurücksetzen ..." Style="{StaticResource Sec}"/><Button x:Name="BtnRpRstrui" Content="Systemwiederherstellung öffnen" Style="{StaticResource Sec}"/><Button x:Name="BtnRpRefresh" Content="Neu einlesen" Style="{StaticResource Sec}"/></WrapPanel>')) +
    (New-Card '4. Weitere Hilfen von Windows' @(
        '<TextBlock Text="Wenn nichts mehr hilft: Windows über Windows Update neu aufspielen oder mit einer ISO reparieren - Programme und Dateien bleiben erhalten." Foreground="#6B7890" FontSize="12" Margin="0,0,0,8" TextWrapping="Wrap"/>',
        '<WrapPanel x:Name="RepTools"/>')))

# ---------------------------------------------------------------- Individualisieren
function New-TagCombo([string]$Name, [string[]]$Items, [int]$Width = 200, [string]$Extra = '') {
    '<ComboBox x:Name="{0}" Width="{1}" Margin="0,0,10,6" VerticalContentAlignment="Center" {3}>{2}</ComboBox>' -f $Name, $Width, (($Items | ForEach-Object { $p = $_ -split '\|', 2; '<ComboBoxItem Content="{0}" Tag="{1}"/>' -f (Esc $p[0]), (Esc $p[1]) }) -join ''), $Extra
}
function New-CuRow([string]$Label, [string]$Inner, [string]$Hint = '') {
    $h = if ($Hint) { '<TextBlock Text="{0}" Foreground="#6B7890" FontSize="12" TextWrapping="Wrap" Margin="0,0,0,2"/>' -f (Esc $Hint) } else { '' }
    '<Grid Margin="0,3"><Grid.ColumnDefinitions><ColumnDefinition Width="260"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions><StackPanel VerticalAlignment="Center" Margin="0,0,10,0"><TextBlock Text="{0}" Foreground="#1F2A44" TextWrapping="Wrap"/>{2}</StackPanel><WrapPanel Grid.Column="1" VerticalAlignment="Center">{1}</WrapPanel></Grid>' -f (Esc $Label), $Inner, $h
}
$cuAct = @('Nichts tun|0', 'Energie sparen|1', 'Ruhezustand|2', 'Herunterfahren|3', 'Bildschirm aus|4')
$cuMin = @('Nie|0', '1 Minute|1', '2 Minuten|2', '3 Minuten|3', '5 Minuten|5', '10 Minuten|10', '15 Minuten|15', '20 Minuten|20', '30 Minuten|30', '45 Minuten|45', '1 Stunde|60', '2 Stunden|120', '3 Stunden|180', '5 Stunden|300')
$pageCustom = New-Page 'Laptop / PC individualisieren' 'Alles, was man an einem Gerät gern dauerhaft nach seinem Geschmack einstellt: Tastaturbeleuchtung, Energie und Deckel, Akku, Bildschirm, Touchpad, Maus, Tastatur, Aussehen, Computername und die Hersteller-Einstellungen im BIOS. Beim Öffnen werden die aktuellen Werte eingelesen.' ((New-Card 'Tastaturbeleuchtung' @(
        (New-InfoRow 'Gerät' 'CuKbdDevice'),
        (New-InfoRow 'Steuerung' 'CuKbdMethod'),
        (New-InfoRow 'Aktuell' 'CuKbdNow'),
        (New-CuRow 'Helligkeit' ((New-TagCombo 'CuKbdLevel' @('Aus|0', 'Gedimmt (Stufe 1)|1', 'Hell (Stufe 2)|2') 220 'SelectedIndex="2"') + '<Button x:Name="BtnKbdSet" Content="Jetzt setzen" Style="{StaticResource Sec}" Padding="12,5" Margin="0,0,8,6"/>')),
        '<CheckBox x:Name="CuKbdKeep" Content="Immer so halten - nach Neustart, Anmeldung, Aufwachen aus dem Energiesparmodus und Netzteilwechsel automatisch wieder setzen" Margin="0,6,0,2"/>',
        '<CheckBox x:Name="CuKbdMinute" Content="Zusätzlich jede Minute nachprüfen (falls der Laptop das Licht bei Bildschirm-Aus abschaltet)" Margin="21,2,0,6"/>',
        '<StackPanel x:Name="CuKbdBios" Margin="0,4,0,0"/>',
        '<TextBlock x:Name="CuKbdTask" Text="" Foreground="#475569" FontSize="12" TextWrapping="Wrap" Margin="0,4,0,6"/>',
        '<WrapPanel><Button x:Name="BtnKbdApply" Content="Übernehmen"/><Button x:Name="BtnKbdRemove" Content="Automatik entfernen" Style="{StaticResource Sec}"/><Button x:Name="BtnKbdLighting" Content="Dynamische Beleuchtung (RGB)" Style="{StaticResource Sec}"/></WrapPanel>')) +
    (New-Card 'Energie, Deckel und Netzschalter' @(
        (New-CuRow 'Energiesparplan' ((New-TagCombo 'CuPlan' @() 300) + '<Button x:Name="BtnPlanUltimate" Content="Höchstleistung hinzufügen" Style="{StaticResource Sec}" Padding="12,5" Margin="0,0,8,6"/>')),
        '<Grid Margin="0,6,0,2"><Grid.ColumnDefinitions><ColumnDefinition Width="260"/><ColumnDefinition Width="210"/><ColumnDefinition Width="210"/></Grid.ColumnDefinitions><TextBlock Grid.Column="1" Text="Am Netzteil" FontWeight="SemiBold"/><TextBlock Grid.Column="2" Text="Im Akkubetrieb" FontWeight="SemiBold"/></Grid>',
        (New-CuRow 'Deckel zuklappen' ((New-TagCombo 'CuLidAc' $cuAct 200) + (New-TagCombo 'CuLidDc' $cuAct 200))),
        (New-CuRow 'Netzschalter drücken' ((New-TagCombo 'CuBtnAc' $cuAct 200) + (New-TagCombo 'CuBtnDc' $cuAct 200))),
        (New-CuRow 'Bildschirm ausschalten nach' ((New-TagCombo 'CuMonAc' $cuMin 200) + (New-TagCombo 'CuMonDc' $cuMin 200))),
        (New-CuRow 'Energie sparen nach' ((New-TagCombo 'CuSlpAc' $cuMin 200) + (New-TagCombo 'CuSlpDc' $cuMin 200))),
        (New-CuRow 'Ruhezustand nach' ((New-TagCombo 'CuHibAc' $cuMin 200) + (New-TagCombo 'CuHibDc' $cuMin 200))),
        (New-CuRow 'Energiesparmodus automatisch ab' (New-TagCombo 'CuSaver' @('Nie|0', '10 % Akku|10', '20 % Akku|20', '30 % Akku|30', '40 % Akku|40', '50 % Akku|50', 'Immer|100') 200)),
        '<WrapPanel Margin="0,6,0,6"><CheckBox x:Name="CuHibernate" Content="Ruhezustand verfügbar" Margin="0,0,20,4"/><CheckBox x:Name="CuUsbSuspend" Content="USB-Geräte dürfen Strom sparen" Margin="0,0,20,4"/><CheckBox x:Name="CuAdaptBright" Content="Helligkeit automatisch anpassen" Margin="0,0,20,4"/><CheckBox x:Name="CuWakeTimers" Content="Weckzeitgeber erlauben (Updates nachts)" Margin="0,0,20,4"/></WrapPanel>',
        '<WrapPanel><Button x:Name="BtnPwrApplyCu" Content="Energie-Einstellungen übernehmen"/><Button x:Name="BtnPwrReset" Content="Plan auf Standard" Style="{StaticResource Sec}"/></WrapPanel>')) +
    (New-Card 'Akku' @(
        (New-InfoRow 'Zustand' 'CuBatHealth'),
        (New-InfoRow 'Ladezyklen' 'CuBatCycles'),
        (New-InfoRow 'Ladestand' 'CuBatNow'),
        '<TextBlock Text="Ladegrenze (z.B. nur bis 80 % laden, schont den Akku) stellt man bei HP und Dell unten unter BIOS-Einstellungen ein, bei Lenovo in Lenovo Vantage (Akku > Ladeschwelle)." Foreground="#6B7890" FontSize="12" TextWrapping="Wrap" Margin="0,6,0,6"/>',
        '<WrapPanel><Button x:Name="BtnBatReport" Content="Ausführlichen Akku-Bericht öffnen" Style="{StaticResource Sec}"/><Button x:Name="BtnBatVantage" Content="Lenovo Vantage / Hersteller-App" Style="{StaticResource Sec}"/></WrapPanel>')) +
    (New-Card 'Bildschirm' @(
        (New-CuRow 'Helligkeit (Laptop-Bildschirm)' ('<Slider x:Name="CuBright" Minimum="0" Maximum="100" Width="300" TickFrequency="5" IsSnapToTickEnabled="True" VerticalAlignment="Center" Margin="0,0,10,6"/><TextBlock x:Name="CuBrightVal" Text="" VerticalAlignment="Center" Width="50" Margin="0,0,0,6"/>')),
        '<WrapPanel Margin="0,6,0,0"><Button x:Name="BtnCuNight" Content="Nachtlicht" Style="{StaticResource Sec}"/><Button x:Name="BtnCuDisplay" Content="Auflösung und Skalierung" Style="{StaticResource Sec}"/><Button x:Name="BtnCuHdr" Content="HDR und Bildwiederholrate" Style="{StaticResource Sec}"/><Button x:Name="BtnCuGfx" Content="Grafik pro Programm" Style="{StaticResource Sec}"/></WrapPanel>')) +
    (New-Card 'Touchpad und Maus' @(
        '<TextBlock Text="Touchpad" FontWeight="SemiBold" Margin="0,0,0,4"/>',
        '<WrapPanel><CheckBox x:Name="CuTapClick" Content="Tippen = Klicken" Margin="0,0,20,4"/><CheckBox x:Name="CuTwoFinger" Content="Mit zwei Fingern tippen = Rechtsklick" Margin="0,0,20,4"/><CheckBox x:Name="CuNatural" Content="Natürliches Scrollen (wie am Handy)" Margin="0,0,20,4"/><CheckBox x:Name="CuTouchWithMouse" Content="Touchpad bleibt an, wenn eine Maus steckt" Margin="0,0,20,4"/></WrapPanel>',
        (New-CuRow 'Touchpad-Empfindlichkeit' (New-TagCombo 'CuTouchSens' @('Höchste|0', 'Hoch|1', 'Mittel|2', 'Niedrig|3') 200)),
        '<TextBlock Text="Maus" FontWeight="SemiBold" Margin="0,8,0,4"/>',
        (New-CuRow 'Zeigergeschwindigkeit' ('<Slider x:Name="CuMouseSpeed" Minimum="1" Maximum="20" Width="300" TickFrequency="1" IsSnapToTickEnabled="True" VerticalAlignment="Center" Margin="0,0,10,6"/><TextBlock x:Name="CuMouseSpeedVal" Text="" VerticalAlignment="Center" Margin="0,0,0,6"/>')),
        (New-CuRow 'Zeilen pro Mausrad-Schritt' (New-TagCombo 'CuWheel' @('1|1', '2|2', '3 (Standard)|3', '5|5', '7|7', '10|10', 'Ganze Seite|-1') 200)),
        '<WrapPanel><CheckBox x:Name="CuMouseAccel" Content="Zeigerbeschleunigung (für Spiele/CAD ausschalten)" Margin="0,0,20,4"/><CheckBox x:Name="CuSwapBtn" Content="Linke und rechte Maustaste tauschen" Margin="0,0,20,4"/></WrapPanel>',
        '<WrapPanel Margin="0,6,0,0"><Button x:Name="BtnCuMouseApply" Content="Touchpad und Maus übernehmen"/><Button x:Name="BtnCuPointer" Content="Mauszeiger-Größe und -Farbe" Style="{StaticResource Sec}"/></WrapPanel>',
        '<TextBlock Text="Touchpad-Änderungen wirken nach dem Ab- und Anmelden, Maus-Änderungen sofort." Foreground="#6B7890" FontSize="12" Margin="0,4,0,0"/>')) +
    (New-Card 'Tastatur' @(
        (New-CuRow 'Verzögerung bis zur Wiederholung' ('<Slider x:Name="CuKeyDelay" Minimum="0" Maximum="3" Width="300" TickFrequency="1" IsSnapToTickEnabled="True" VerticalAlignment="Center" Margin="0,0,10,6"/><TextBlock x:Name="CuKeyDelayVal" Text="" VerticalAlignment="Center" Margin="0,0,0,6"/>')),
        (New-CuRow 'Wiederholrate' ('<Slider x:Name="CuKeyRate" Minimum="0" Maximum="31" Width="300" TickFrequency="1" IsSnapToTickEnabled="True" VerticalAlignment="Center" Margin="0,0,10,6"/><TextBlock x:Name="CuKeyRateVal" Text="" VerticalAlignment="Center" Margin="0,0,0,6"/>')),
        '<WrapPanel Margin="0,4,0,0"><CheckBox x:Name="CuStickyOff" Content="Keine Einrasttasten-Abfrage bei 5x Umschalt (auch Filter-/Umschalttasten)" Margin="0,0,20,4"/><CheckBox x:Name="CuLangHotkeyOff" Content="Sprachumschaltung mit Alt+Umschalt aus" Margin="0,0,20,4"/><CheckBox x:Name="CuNumLockOn" Content="NumLock beim Start an" Margin="0,0,20,4"/></WrapPanel>',
        '<TextBlock Text="Fn-Taste (F1-F12 als Standard oder Sonderfunktionen) lässt sich unten in den BIOS-Einstellungen umstellen; bei vielen Laptops auch sofort mit Fn+Esc." Foreground="#6B7890" FontSize="12" TextWrapping="Wrap" Margin="0,4,0,6"/>',
        '<WrapPanel><Button x:Name="BtnCuKeyApply" Content="Tastatur übernehmen"/></WrapPanel>')) +
    (New-Card 'Aussehen und Klang' @(
        (New-CuRow 'Farbmodus Apps' (New-TagCombo 'CuThemeApps' @('Hell|1', 'Dunkel|0') 200)),
        (New-CuRow 'Farbmodus Windows (Taskleiste, Start)' (New-TagCombo 'CuThemeSys' @('Hell|1', 'Dunkel|0') 200)),
        '<WrapPanel Margin="0,4,0,0"><CheckBox x:Name="CuTransp" Content="Transparenzeffekte" Margin="0,0,20,4"/><CheckBox x:Name="CuAccentTitle" Content="Akzentfarbe auf Titelleisten" Margin="0,0,20,4"/><CheckBox x:Name="CuAccentAuto" Content="Akzentfarbe aus dem Hintergrund" Margin="0,0,20,4"/><CheckBox x:Name="CuStartSound" Content="Startsound beim Hochfahren" Margin="0,0,20,4"/><CheckBox x:Name="CuLockTips" Content="Tipps und Werbung auf dem Sperrbildschirm" Margin="0,0,20,4"/></WrapPanel>',
        '<WrapPanel Margin="0,6,0,0"><Button x:Name="BtnCuLookApply" Content="Aussehen übernehmen"/><Button x:Name="BtnCuWall" Content="Hintergrund" Style="{StaticResource Sec}"/><Button x:Name="BtnCuColors" Content="Farben" Style="{StaticResource Sec}"/><Button x:Name="BtnCuLock" Content="Sperrbildschirm" Style="{StaticResource Sec}"/><Button x:Name="BtnCuThemes" Content="Designs" Style="{StaticResource Sec}"/><Button x:Name="BtnCuSounds" Content="Sounds" Style="{StaticResource Sec}"/><Button x:Name="BtnCuFonts" Content="Schriftarten" Style="{StaticResource Sec}"/></WrapPanel>')) +
    (New-Card 'Computername' @(
        (New-CuRow 'Name des PCs' '<TextBox x:Name="CuPcName" Width="260" Padding="4,3" Margin="0,0,10,6"/>' 'Nur Buchstaben, Ziffern und Bindestrich, max. 15 Zeichen. Wirkt nach Neustart.'),
        (New-CuRow 'Beschreibung' '<TextBox x:Name="CuPcDesc" Width="420" Padding="4,3" Margin="0,0,10,6"/>' 'Wird im Netzwerk neben dem Namen angezeigt.'),
        '<WrapPanel Margin="0,4,0,0"><Button x:Name="BtnCuRename" Content="Übernehmen"/></WrapPanel>')) +
    (New-Card 'Hersteller-Einstellungen im BIOS (Lenovo, HP, Dell)' @(
        '<TextBlock Text="Direkt aus Windows änderbar, ohne ins BIOS zu gehen: Tastaturbeleuchtung und Zeitlimit, Fn-Taste, Akku-Ladegrenze, Laden über USB bei ausgeschaltetem PC, Wake-on-LAN, Einschalten beim Deckel öffnen, Lüfter und vieles mehr. Wirkt nach dem nächsten Neustart. Ist ein BIOS-Kennwort gesetzt, hier eintragen." Foreground="#6B7890" FontSize="12" TextWrapping="Wrap" Margin="0,0,0,6"/>',
        '<WrapPanel><Button x:Name="BtnBiosRead" Content="Einlesen" Style="{StaticResource Sec}"/><CheckBox x:Name="CuBiosAll" Content="Alle Einstellungen zeigen (nicht nur die für den Alltag)" VerticalAlignment="Center" Margin="0,0,20,8"/><TextBlock Text="BIOS-Kennwort:" VerticalAlignment="Center" Margin="0,0,6,8"/><PasswordBox x:Name="CuBiosPwd" Width="160" Padding="4,3" Margin="0,0,10,8"/></WrapPanel>',
        '<TextBlock x:Name="CuBiosInfo" Text="Noch nicht eingelesen." FontWeight="SemiBold" Foreground="#1F2A44" Margin="0,2,0,6" TextWrapping="Wrap"/>',
        '<StackPanel x:Name="CuBiosList"/>',
        '<WrapPanel Margin="0,8,0,0"><Button x:Name="BtnBiosApply" Content="Geänderte Einstellungen übernehmen" IsEnabled="False"/></WrapPanel>')))

# ---------------------------------------------------------------- Sicherheit
$pageSecurity = New-Page 'Sicherheit' 'Alle Schutzfunktionen dieses PCs auf einen Blick - prüfen, einzeln ein- und ausschalten und bei Bedarf einen anderen Virenschutz installieren.' ((New-Card 'Sicherheitsstatus' @(
        '<Grid Margin="0,0,0,8"><Grid.ColumnDefinitions><ColumnDefinition Width="Auto"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>',
        '<Border x:Name="SecScoreRing" Width="96" Height="96" CornerRadius="48" BorderThickness="7" BorderBrush="#2D7FF9" Margin="0,0,18,0"><StackPanel VerticalAlignment="Center"><TextBlock x:Name="SecScore" Text="-" FontSize="30" FontWeight="Bold" HorizontalAlignment="Center" Foreground="#1F2A44"/><TextBlock Text="von 100" FontSize="11" HorizontalAlignment="Center" Foreground="#6B7890"/></StackPanel></Border>',
        '<StackPanel Grid.Column="1" VerticalAlignment="Center"><TextBlock x:Name="SecScoreText" Text="Wird geprüft ..." FontSize="16" FontWeight="SemiBold" Foreground="#1F2A44" TextWrapping="Wrap"/><TextBlock x:Name="SecAvInfo" Text="" Foreground="#475569" Margin="0,4,0,0" TextWrapping="Wrap"/><WrapPanel Margin="0,8,0,0"><Button x:Name="BtnSecCheck" Content="Neu prüfen" Style="{StaticResource Sec}" Padding="12,5"/><Button x:Name="BtnSecWinSec" Content="Windows-Sicherheit öffnen" Style="{StaticResource Sec}" Padding="12,5"/></WrapPanel></StackPanel></Grid>',
        (New-White (New-DataGrid 'SecGrid' @('Bereich|Area|220', 'Zustand|State|170', 'Details|Detail|*', 'Empfehlung|Fix|320') 'Height="360"')))) +
    (New-Card 'Microsoft Defender' @(
        '<TextBlock x:Name="SecDefInfo" Text="" Foreground="#475569" FontSize="12" TextWrapping="Wrap" Margin="0,0,0,6"/>',
        '<WrapPanel>',
        '<CheckBox x:Name="DefRealtime" Content="Echtzeitschutz" Width="330" Margin="0,3"/><CheckBox x:Name="DefCloud" Content="Cloudbasierter Schutz" Width="330" Margin="0,3"/><CheckBox x:Name="DefSamples" Content="Automatische Übermittlung von Beispielen" Width="330" Margin="0,3"/>',
        '<CheckBox x:Name="DefPua" Content="Schutz vor unerwünschten Apps (PUA)" Width="330" Margin="0,3"/><CheckBox x:Name="DefNetwork" Content="Netzwerkschutz (gefährliche Webseiten)" Width="330" Margin="0,3"/><CheckBox x:Name="DefCfa" Content="Ransomware-Schutz (überwachter Ordnerzugriff)" Width="330" Margin="0,3"/>',
        '<CheckBox x:Name="DefBehavior" Content="Verhaltensüberwachung" Width="330" Margin="0,3"/><CheckBox x:Name="DefScript" Content="Skripte prüfen" Width="330" Margin="0,3"/><CheckBox x:Name="DefRemovable" Content="USB-Sticks beim Vollscan prüfen" Width="330" Margin="0,3"/>',
        '</WrapPanel>',
        '<TextBlock Text="Ist der Manipulationsschutz an, lässt Windows manche Änderungen nur in der Windows-Sicherheit selbst zu. Der Ransomware-Schutz kann Programme blockieren, die in Dokumente schreiben - dann dort Apps zulassen." Foreground="#6B7890" FontSize="12" TextWrapping="Wrap" Margin="0,6,0,6"/>',
        '<WrapPanel><Button x:Name="BtnDefApply" Content="Defender-Einstellungen übernehmen"/><Button x:Name="BtnDefQuick" Content="Schnellprüfung" Style="{StaticResource Sec}"/><Button x:Name="BtnDefFull" Content="Vollprüfung" Style="{StaticResource Sec}"/><Button x:Name="BtnDefOffline" Content="Offline-Prüfung (Neustart)" Style="{StaticResource Sec}"/><Button x:Name="BtnDefSafety" Content="Zweitmeinung: Microsoft Safety Scanner" Style="{StaticResource Sec}"/><Button x:Name="BtnDefSig" Content="Signaturen aktualisieren" Style="{StaticResource Sec}"/></WrapPanel>',
        '<TextBlock Text="Bedrohungsverlauf" FontWeight="SemiBold" Margin="0,8,0,4"/>',
        (New-White (New-DataGrid 'DefThreats' @('Zeit|Time|140', 'Bedrohung|Name|*', 'Schwere|Severity|90', 'Aktion|Action|140', 'Datei|Path|*') 'Height="150"')))) +
    (New-Card 'Firewall' @(
        '<WrapPanel><CheckBox x:Name="FwDomain" Content="Domänennetzwerk" Width="220" Margin="0,3"/><CheckBox x:Name="FwPrivate" Content="Privates Netzwerk (Zuhause)" Width="240" Margin="0,3"/><CheckBox x:Name="FwPublic" Content="Öffentliches Netzwerk (Hotel, Café)" Width="260" Margin="0,3"/></WrapPanel>',
        '<CheckBox x:Name="FwBlockPublic" Content="Im öffentlichen Netzwerk alle eingehenden Verbindungen blockieren (auch erlaubte Apps)" Margin="0,6,0,2"/>',
        '<CheckBox x:Name="FwNotify" Content="Benachrichtigen, wenn eine App blockiert wird" Margin="0,2,0,6"/>',
        '<TextBlock x:Name="FwInfo" Text="" Foreground="#475569" FontSize="12" TextWrapping="Wrap" Margin="0,0,0,6"/>',
        '<WrapPanel><Button x:Name="BtnFwApply" Content="Firewall übernehmen"/><Button x:Name="BtnFwAdv" Content="Erweiterte Regeln (wf.msc)" Style="{StaticResource Sec}"/><Button x:Name="BtnFwReset" Content="Auf Standard zurücksetzen" Style="{StaticResource Sec}"/><Button x:Name="BtnFwNet" Content="Netzwerkprofil (Privat/Öffentlich)" Style="{StaticResource Sec}"/></WrapPanel>')) +
    (New-Card 'BitLocker-Laufwerksverschlüsselung' @(
        '<TextBlock x:Name="BlInfo" Text="Schützt die Daten, wenn der Laptop gestohlen wird. Den Wiederherstellungsschlüssel unbedingt außerhalb des PCs aufbewahren (USB-Stick, Ausdruck, Microsoft-Konto)." Foreground="#6B7890" FontSize="12" TextWrapping="Wrap" Margin="0,0,0,6"/>',
        (New-White (New-DataGrid 'BlGrid' @('Laufwerk|Drive|80', 'Zustand|State|170', 'Verschlüsselt|Pct|100', 'Methode|Method|130', 'Entsperren über|Protectors|*') 'Height="140"')),
        '<WrapPanel Margin="0,8,0,0"><Button x:Name="BtnBlWizard" Content="BitLocker-Assistent ..." ToolTip="Schritt für Schritt: prüfen, verschlüsseln und den Schlüssel an mehreren sicheren Orten ablegen"/><Button x:Name="BtnBlOneClick" Content="C: mit einem Klick verschlüsseln" Style="{StaticResource Sec}" ToolTip="Verschlüsselt das Windows-Laufwerk und legt den Wiederherstellungsschlüssel automatisch im PC-Tools-Ordner ab."/><Button x:Name="BtnBlKeyFolder" Content="Schlüssel-Ordner öffnen" Style="{StaticResource Sec}"/><Button x:Name="BtnBlOn" Content="Anderes Laufwerk verschlüsseln ..." Style="{StaticResource Sec}"/><Button x:Name="BtnBlKey" Content="Schlüssel auf USB-Stick sichern ..." Style="{StaticResource Sec}"/><Button x:Name="BtnBlSuspend" Content="Für 1 Neustart aussetzen (BIOS-Update)" Style="{StaticResource Sec}"/><Button x:Name="BtnBlResume" Content="Fortsetzen" Style="{StaticResource Sec}"/><Button x:Name="BtnBlOff" Content="Entschlüsseln" Style="{StaticResource Sec}"/><Button x:Name="BtnBlMsSave" Content="Im Microsoft-Konto sichern"/><Button x:Name="BtnBlOnline" Content="Schlüssel im Microsoft-Konto ansehen" Style="{StaticResource Sec}"/></WrapPanel>')) +
    (New-Card 'Passwort-Check' @(
        '<TextBlock Text="Prüft, ob Passwörter in bekannten Datenlecks auftauchen (Have I Been Pwned). Das Passwort verlässt den PC nie: nur die ersten 5 Zeichen seines SHA-1-Fingerabdrucks werden abgefragt, der Vergleich passiert hier auf dem PC." Foreground="#6B7890" FontSize="12" TextWrapping="Wrap" Margin="0,0,0,8"/>',
        '<WrapPanel><TextBlock Text="Ein Passwort prüfen:" VerticalAlignment="Center" Margin="0,0,8,8" Foreground="#1F2A44"/><PasswordBox x:Name="PwOne" Width="260" Padding="4,5" Margin="0,0,8,8" VerticalAlignment="Center"/><Button x:Name="BtnPwOne" Content="Prüfen"/><TextBlock x:Name="PwOneInfo" Text="" VerticalAlignment="Center" FontWeight="SemiBold" Margin="4,0,0,8" TextWrapping="Wrap" MaxWidth="520"/></WrapPanel>',
        '<TextBlock Text="Alle gespeicherten Passwörter prüfen: im Browser exportieren (Edge: Einstellungen &gt; Kennwörter &gt; ... &gt; Kennwörter exportieren · Chrome: Passwortmanager &gt; Einstellungen &gt; Passwörter exportieren · Firefox: Passwörter &gt; ... &gt; Zugangsdaten exportieren), dann die Datei hier wählen. PC-Tools löscht die Export-Datei danach auf Wunsch sicher." Foreground="#475569" FontSize="12" TextWrapping="Wrap" Margin="0,6,0,6"/>',
        '<WrapPanel><Button x:Name="BtnPwCsv" Content="Export-Datei prüfen ..."/><Button x:Name="BtnPwEdge" Content="Edge-Kennwörter öffnen" Style="{StaticResource Sec}"/><Button x:Name="BtnPwChrome" Content="Chrome-Passwortmanager öffnen" Style="{StaticResource Sec}"/><Button x:Name="BtnPwDelCsv" Content="Export-Datei sicher löschen" Style="{StaticResource Sec}" IsEnabled="False"/></WrapPanel>',
        '<TextBlock x:Name="PwInfo" Text="" Foreground="#1F2A44" FontWeight="SemiBold" TextWrapping="Wrap" Margin="0,4,0,6"/>',
        (New-White (New-DataGrid 'PwGrid' @('Seite|Site|220', 'Benutzer|User|170', 'Ergebnis|Result|*|Sort') 'Height="220"'))
    )) +
    (New-Card 'Windows-Schutzfunktionen' @(
        (New-CuRow 'Benutzerkontensteuerung (UAC)' (New-TagCombo 'SecUac' @('Immer benachrichtigen (sicherste)|2', 'Standard - nur bei Programmänderungen|5', 'Ohne Bildschirmabdunkelung|5d', 'Nie benachrichtigen (nicht empfohlen)|0') 360) 'Fragt nach, bevor Programme Änderungen am System vornehmen.'),
        '<WrapPanel Margin="0,6,0,0">',
        '<CheckBox x:Name="SecSmartScreen" Content="SmartScreen für Apps und Dateien" Width="360" Margin="0,3"/><CheckBox x:Name="SecHvci" Content="Speicherintegrität (Kernisolierung)" Width="360" Margin="0,3"/>',
        '<CheckBox x:Name="SecLsa" Content="LSA-Schutz (Anmeldedaten schützen)" Width="360" Margin="0,3"/><CheckBox x:Name="SecSmb1Off" Content="SMBv1 abgeschaltet (veraltet, unsicher)" Width="360" Margin="0,3"/>',
        '<CheckBox x:Name="SecAutorunOff" Content="Autostart von USB-Sticks/CDs aus" Width="360" Margin="0,3"/><CheckBox x:Name="SecGuestOff" Content="Gastkonto deaktiviert" Width="360" Margin="0,3"/>',
        '<CheckBox x:Name="SecRdp" Content="Remotedesktop erlaubt (Zugriff aus dem Netz)" Width="360" Margin="0,3"/><CheckBox x:Name="SecPs2Off" Content="Alte PowerShell 2.0 entfernt" Width="360" Margin="0,3"/>',
        '<CheckBox x:Name="SecRemoteAssist" Content="Remoteunterstützung erlaubt" Width="360" Margin="0,3"/><CheckBox x:Name="SecExtShow" Content="Dateiendungen anzeigen (erkennt getarnte .exe)" Width="360" Margin="0,3"/>',
        '</WrapPanel>',
        '<TextBlock Text="Speicherintegrität, LSA-Schutz und UAC wirken nach einem Neustart. Speicherintegrität kann sehr alte Treiber blockieren - Windows meldet das dann." Foreground="#6B7890" FontSize="12" TextWrapping="Wrap" Margin="0,6,0,6"/>',
        '<WrapPanel><Button x:Name="BtnSecApply" Content="Schutzfunktionen übernehmen"/><Button x:Name="BtnSecRecommended" Content="Empfohlene Werte setzen" Style="{StaticResource Sec}"/></WrapPanel>')) +
    (New-Card 'Virenschutz installieren' @(
        '<TextBlock Text="Microsoft Defender reicht für die meisten völlig aus. Wer mehr will: Nie zwei Virenscanner gleichzeitig mit Echtzeitschutz betreiben - Windows schaltet Defender beim Installieren eines anderen automatisch in den Ruhemodus. Malwarebytes ist als Zweitscanner verträglich. Kaspersky fehlt bewusst: Das BSI rät seit 2022 davon ab." Foreground="#6B7890" FontSize="12" TextWrapping="Wrap" Margin="0,0,0,8"/>',
        '<TextBlock Text="Kostenlos" FontWeight="SemiBold" FontSize="14" Margin="0,0,0,4"/>',
        '<WrapPanel x:Name="AvFree"/>',
        '<TextBlock Text="Kostenpflichtig (Testversion oder Kauf beim Hersteller)" FontWeight="SemiBold" FontSize="14" Margin="0,10,0,4"/>',
        '<WrapPanel x:Name="AvPaid"/>')))

# ---------------------------------------------------------------- Handbuch (wird mit jeder Version gepflegt)
$ManualNews = @(
    'Version 14.3.2: Port-Scanner und Sicherheits-Scan prüfen nur noch Adressen im eigenen Netz (z.B. 192.168.x.x, 10.x.x.x) - fremde Adressen im Internet werden nie gescannt. Das Setup zeigt vor der Installation die Datenschutz-Hinweise.',
    'Version 14.3.1: Alle neuen Funktionen seit 14.0 (KI-Assistent, Punkte beheben, Startzeit-Analyse, Hilfe holen, Einfach-Modus, Passwort-Check, BitLocker-Assistent) sind jetzt in allen 12 Sprachen übersetzt.',
    'Version 14.3: Neu auf der Seite Sicherheit - Passwort-Check: prüft einzelne Passwörter oder alle aus dem Browser exportierten gegen bekannte Datenlecks (Have I Been Pwned). Das Passwort verlässt den PC nie, nur 5 Zeichen seines Fingerabdrucks. Zeigt auch mehrfach verwendete und zu einfache Passwörter und löscht die Export-Datei danach sicher. Neu: BitLocker-Assistent - prüft TPM, Edition, Secure Boot und Netzteil, verschlüsselt und legt den Wiederherstellungsschlüssel an mehreren Orten ab (USB-Stick, Ordner/NAS, Microsoft- oder Firmenkonto, Ausdruck, Lizenz-Tresor) und kontrolliert jede Kopie.',
    'Version 14.2: Neu "Hilfe holen" - beim Zustands-Score und im Einfach-Modus. Ein Klick schickt dem Helfer einen Bericht (Zustand, Probleme, Fehler der letzten 3 Tage, Protokoll): in "Meine PCs" erscheint ein roter Hilferuf mit Bericht, aufs Handy kommt eine Nachricht (wenn eingerichtet), auf Wunsch wird eine E-Mail vorbereitet - sonst liegt der Bericht auf dem Desktop. Neu: Einfach-Modus für Eltern, Großeltern und Einsteiger - nur eine große Ampel und zwei Knöpfe "Alles reparieren" und "Hilfe holen" (Einstellungen > Stabilität oder beim ersten Start).',
    'Version 14.1: Treiber für Geräte mit Problem (z.B. Code 48/28) sucht PC-Tools jetzt gezielt - erst über Windows Update, dann über das offizielle Treiberpaket von HP, Lenovo oder Dell (Seite Geräte und "Punkte beheben"). Neu auf der Seite Autostart: Startzeit-Analyse zeigt, welche Programme, Dienste und Treiber den Start wie viele Sekunden bremsen, und entschärft sie mit einem Klick. Beim Zustands-Score: "Automatisch beheben, wenn der Score unter ... fällt" - nach jedem geplanten Lauf wird erledigt, was sicher automatisch geht, der Rest kommt als Hinweis.',
    'Version 14.0.1: Neuer Knopf "Punkte beheben" beim Zustands-Score - behebt mit einem Klick alles, was automatisch geht (Updates und Treiber nachinstallieren, Aufräumen, Autostart aufräumen, Geräte-Probleme, Virendefinitionen, Firewall) und sagt ehrlich, was nur von Hand geht (z.B. Secure Boot im BIOS). Fehlgeschlagene Updates zählen im Score nur noch, wenn sie seitdem nicht doch erfolgreich installiert wurden.',
    'Version 14.0: PC-Tools spricht jetzt 12 Sprachen - Deutsch, English, Español, Français, Italiano, Português (Brasil), Polski, Türkçe, Русский, 简体中文, 日本語 und 한국어. Die Sprache wählst du beim ersten Start oder jederzeit unter Einstellungen > Stabilität > Sprache; auch der KI-Assistent antwortet in deiner Sprache. Die Übersetzungen sind maschinell (KI) erstellt - Fehler bitte über "Übersetzungsfehler melden" mitteilen. Dazu: PC-Tools.exe, Installationsprogramm und die Linux-Ausgabe.',
    'Version 13.9.2: Das Symbol in der Taskleiste ist repariert (eigenes PC-Tools-Symbol in allen Größen, auch beim Anheften). Neu: PC-Tools.exe als Starter und ein Installationsprogramm (PC-Tools-Setup.exe) - und die ersten Sprachen: English, Español, Русский und 简体中文 (Einstellungen > Stabilität > Sprache). Weitere Sprachen folgen mit Version 14.',
    'Version 13.9.1: "Nicht genutzte Programme" entfernt jetzt auch Programme ohne stillen Deinstallationsweg: erst still (MSI, Inno, NSIS, electron-builder, WiX, Squirrel), dann über winget, dann über das Deinstallationsprogramm des Herstellers, bei portablen Programmen ohne Deinstaller werden Ordner (Papierkorb) und Eintrag (gesichert) entfernt. Vorbereitung für die Mehrsprachigkeit von Version 14.',
    'Version 13.9: Der KI-Assistent arbeitet jetzt selbstständig: Kostenlose KI mit einem Klick (oder automatisch beim ersten Senden), automatische Diagnose nach jedem Pflegelauf in einfachen Worten, wöchentliche Zusammenfassung "Was ist diese Woche auf deinem PC passiert?", Bluescreens (Minidumps mit Stoppcode) und Ereignisprotokoll erklären, Netzwerk-Bericht per KI zusammenfassen mit Maßnahmenliste nach Wichtigkeit, neue Lese-Werkzeuge (Autostart, Treiber, Updates - immer erst nach Bestätigung), Spracheingabe und Vorlesen, Gespräch je PC speichern und Gedächtnis für frühere Probleme.',
    'Version 13.8: Der KI-Assistent hat jetzt eine Anbieter-Auswahl (Dropdown): komplett kostenlos und ohne Konto mit Ollama (KI läuft lokal auf dem PC, "Ollama einrichten" installiert alles mit einem Klick), kostenlos mit Gratis-Konto über Groq, OpenRouter oder Mistral (EU), bezahlt mit Claude, ChatGPT oder Gemini - oder jede andere OpenAI-kompatible KI. Schlüssel und Modell je Anbieter getrennt. "Nicht genutzte Programme" lässt sich jetzt ab 5 Tagen einstellen. Dazu Stabilität: Dienste-Aktionen, Netzlaufwerke, Update-Prüfung und Statusmeldungen können PC-Tools nicht mehr endlos blockieren.',
    'Version 13.7.1: PC-Tools ist jetzt Open Source (Apache 2.0) - https://github.com/rhedv42-sudo/pc-tools. Updates kommen ab jetzt aus dem öffentlichen Repository (Zweig stable, Downloads unter Releases), ein GitHub-Token ist nicht mehr nötig. Bestehende Installationen werden automatisch umgestellt.',
    'Version 13.7: Neu "Nicht genutzte Programme" (Übersicht und PC-Reiniger > Programme): findet Programme, die seit 90 Tagen bis 2 Jahren nicht gestartet wurden (Windows-Spuren Prefetch, BAM und UserAssist), schützt Laufzeiten, Treiber, Sicherheits-, Sicherungs-, VPN-, Fernwartungs-, Office- und Druckerprogramme und entfernt die angehakten nach EINER Bestätigung still nacheinander - mit Wiederherstellungspunkt, Resten (Ordner in den Papierkorb, Registry mit Sicherung) und verwaisten Verknüpfungen. Ninite Pro ist nicht mehr Teil des Downloads - wer eine Lizenz hat, kopiert NinitePro.exe nach C:\ProgramData\PCPflege (Anleitung: Ninite-Pro-einbinden.txt).',
    'Version 13.6: Netzwerk dokumentieren erkennt jetzt die gesamte Netzwerk-Infrastruktur - Router (auch weitere Router und Doppel-NAT), Firewalls (Sophos, Fortinet, pfSense/OPNsense, Securepoint, Zyxel, LANCOM ...), Switches, Access Points (UniFi, Omada, Aruba, LANCOM, MikroTik, FRITZ!Repeater, Mesh ...) und WLAN-Controller. Quellen: Hersteller, Weboberfläche, UPnP, SNMP (Modell, Firmware, Standort, Kontakt, Laufzeit), Verwaltungsports und die WLAN-Sender, die zur Geräte-MAC passen. Neues Berichtskapitel "Netzwerk-Infrastruktur" mit WLAN-Abdeckung je Access Point und dem Weg ins Internet; neue Befunde: SNMP mit Standard-Community, weiterer Router, Doppel-NAT.',
    'Version 13.5: Zwei neue Seiten. "WLAN optimieren": Analyse von Verbindung, Signal (dBm), Band, Kanal, Funkstandard, Sicherheit, Nachbarnetzen, Energiesparen und den versteckten Treiber-Einstellungen mit Bewertung; "WLAN optimieren" stellt Energiesparen, 5/6-GHz-Bevorzugung, Sendeleistung, MIMO, Kanalbreite, Funkstandard und Roaming mit Sicherung ein (Rückgängig); Stabilitätstest, WLAN neu verbinden, WLAN-Bericht von Windows und der WLAN-Rundgang (Empfang je Raum messen). "Netzwerk dokumentieren": erfasst alle Geräte (Art, IP, MAC, Hersteller, 59 Dienste, Weboberfläche, Anschluss), Smart Home und Gebäudeautomation (KNX IP mit Secure-Prüfung und passivem Busmonitor, Bonjour/mDNS, UPnP, Shelly, Tasmota, Hue, Node-RED, MQTT, Homematic, ESPHome, Matter/Thread, Home Assistant per Token), Router und - mit Anmeldung - die FRITZ!Box (alle Geräte auch offline, Portfreigaben, WPS, Gastnetz, Fernzugang, FRITZ!OS-Update, DSL-Werte), die Erreichbarkeit aus dem Internet (Portfreigaben, UPnP, Fernzugang, Carrier-NAT, IPv6, Shodan InternetDB mit CVEs), WLAN und diesen PC. Bewertet Schwachstellen (kritisch bis Info, Note A-E), vergleicht mit der letzten Erfassung, speichert Raum/Zweck/Notiz je Gerät, exportiert als Excel-Liste und erstellt einen PDF-Bericht mit Logo, Netzplan, Inventar, Schwachstellen, Maßnahmenplan und Freigabe-/Unterschriftenfeld. Auf Wunsch jeden Montag automatisch mit Meldung bei neuen Geräten oder Schwachstellen.',
    'Version 13.4: Zwei neue Ein-Klick-Knöpfe auf der Übersicht. "Alle Optimierungen" schaltet alle Einstellungen der Seite Tuning ein (Leistung, Datenschutz, Explorer und Taskleiste, System) - mit Wiederherstellungspunkt, Liste vorher und Protokoll. "Autostart: nur das Nötige" reduziert den Autostart auf Sicherheit, Treiber-Helfer, PC-Tools und angepinnte Programme (Rückgängig im Autostart-Manager).',
    'Version 13.3.2: Funktionsupdates (neue Windows-Versionen) und - wenn der PC im Insider-Programm ist - die jeweils neuesten Insider-Builds werden jetzt standardmaessig ueber Windows Update mitinstalliert, auch in der Ein-Klick-Pflege. Bestehende Installationen werden einmalig umgestellt. Wer das nicht will: Einstellungen > "Funktionsupdates und Insider-Builds ausschliessen" einschalten.',
    'Version 13.3.1: Windows Update installiert jetzt auch Updates, die Microsoft als "kann Eingaben anfordern" kennzeichnet (typisch: Intel-Grafik-, System- und Extension-Treiber). Sie wurden bisher mit "uebersprungen (braucht Eingabe)" ausgelassen. Jetzt werden sie getrennt und still installiert; nur falls eines wirklich eine Eingabe braucht, schlaegt dieses eine fehl und das Protokoll sagt, was zu tun ist.',
    'Version 13.3: Neu auf der Seite Fehler beheben: "Geraete mit Problemen (Geraete-Manager)". Zeigt alle Geraete mit Ausrufezeichen und den Grund (kein Treiber, Fehlercode, deaktiviert). "Reparieren" entfernt verwaiste Software-Eintraege, deren Treiber geloescht wurde (z.B. ein alter TAP-/VPN-Adapter als "Unbekanntes Geraet"), und schaltet Bluetooth-Dienste ohne Treiber fuer ihr gekoppeltes Geraet aus (z.B. Samsung-Handy/-Tablet unter "Andere Geraete") - einfach loeschen hilft dort nicht, die Eintraege kommen sofort wieder. Klappt das Ausschalten nicht, oeffnet sich "Geraete und Drucker" mit Anleitung.',
    'Version 13.2: Neu auf der Seite Fehler beheben: "Store-Apps, die nicht starten". Findet Apps wie das neue Outlook, die nach einem grossen Windows-Update zwar eingetragen sind, deren Programmordner aber fehlt (dann startet die App nicht und Zuruecksetzen hilft nicht). Prueft ausserdem beschaedigte App-Laufzeiten (Windows App Runtime) und WebView2 - alte beschaedigte Versionen, neben denen eine intakte neuere liegt, werden als harmlos erkannt. "Reparieren" entfernt defekte Store-Apps und oeffnet ihre Store-Seite zum Neuinstallieren und installiert defekte Laufzeiten bzw. WebView2 per winget neu.',
    'Version 13.1.4: Die neue Dienstgruppen-Pruefung meldete die Kopien, die Windows pro Benutzer von manchen Diensten anlegt (Name endet z.B. auf _b270d), faelschlich als "in keiner Dienstgruppe". Diese werden jetzt ueber den Namen ihrer Vorlage geprueft. Die Netzwerkdienst-Pruefung erkennt dadurch auch einen verstellten Netzwerklistendienst (netprofm) zuverlaessig.',
    'Version 13.1.3: Wichtige Korrektur - die Pruefung "Netzwerkdienste auf Windows-Standard" hat bei Diensten wie der WinHTTP-Autoproxy-Erkennung eine fest hinterlegte, veraltete Dienstgruppe erzwungen. Auf neueren Windows-Versionen startet der Dienst dann nie (haengt dauerhaft in "Wird gestartet"), ohne ihn laufen Verbindungs-Manager und WLAN nicht. Jetzt wird die richtige Gruppe aus dem jeweiligen Windows selbst gelesen. Neu: "Dienste, die nicht starten" erkennt falsche oder fehlende Dienstgruppen (FALSCH EINGERICHTET), und "Reparieren" korrigiert sie mit Sicherung. Bereits verstellte PCs werden dabei wieder richtig gestellt.',
    'Version 13.1.2: "Dienste, die nicht starten" - die Ausgabe ist jetzt hell und gut lesbar (vorher sehr dunkel), und unter dem Feld gibt es den Knopf "Protokoll kopieren", der den gesamten Inhalt in die Zwischenablage legt.',
    'Version 13.1.1: Fehler behoben - "Dienste, die nicht starten" zeigte beim Prüfen und Reparieren nichts an und der Vorgang schien minutenlang zu hängen. Ursache: beide Funktionen versuchten jeden Dienst mit einem blockierenden Startbefehl zu starten (bis zu 30 Sekunden je Dienst), die Anzeige wurde erst ganz am Ende aktualisiert. Jetzt: "Prüfen" diagnostiziert nur (startet keine Dienste) und ist in Sekunden fertig; "Reparieren" startet die Dienste ohne zu blockieren und mit fester Zeitbegrenzung (i.d.R. unter einer Minute).',
    'Version 13.1: Neue Hilfe "Dienste, die nicht starten" (Seite Fehler beheben): findet alle Dienste mit Starttyp Automatisch, die nicht laufen, und nennt die URSACHE (wartet auf anderen Dienst, Programmdatei fehlt, deaktiviert, falsches Konto, Fehlercode). "Reparieren" setzt die Kerndienste auf die Windows-Vorgabe, startet Abhängigkeiten in der richtigen Reihenfolge und startet die Dienste. Dienste, die nur bei Bedarf (Trigger) starten, werden als normal erkannt. Gut für PCs/Surfaces, auf denen Dienste klemmen.',
    'Version 13.0.1: Fehler behoben - der Windows-Installations-/Update-Assistent (Microsoft.WindowsInstallationAssistant u.a.) wurde bei "Programme aktualisieren" über winget mitaktualisiert und startete einen OS-Upgrade-Dialog, der sich aufhängte. Diese Upgrade-Assistenten werden jetzt dauerhaft übersprungen (angeheftet) und erscheinen nicht mehr im Installer.',
    'Version 13.0: Neuer Bereich Server-Tools (erscheint automatisch auf Windows Server, auf normalen PCs unter Einstellungen > Server-Modus einschaltbar - dann auf Wunsch mit PowerShell-Remoting): Server- und Rollenübersicht, Active-Directory-Gesundheit (dcdiag, Replikation, FSMO, Zeit, DNS), AD-Konten und -Gruppen (gesperrte/inaktive Konten, ablaufende Kennwörter, privilegierte Gruppen, GPO, Konto entsperren), Azure/Entra (Hybrid-Join, Entra-Connect-Sync, Azure-Erreichbarkeit) sowie Wartung und Härtung (Zertifikate, SMBv1/LDAP/NTLM-Prüfung, Windows Server Backup).',
    'Version 13.0: Netzwerk-Werkzeuge mit Port-Scanner und Sicherheits-Scan - scannt einen Rechner oder ein ganzes Netz (einzelne IP, Bereich, Subnetz, mehrere mit Komma) nach offenen Ports (von den wichtigsten bis zu allen 65535) und prüft gefundene Geräte auf riskante Dienste (SMBv1, Telnet, FTP, RDP, VNC, offene Datenbanken, SNMP ...) mit Einstufung und Empfehlung. Nur für eigene Netze.',
    'Version 12.5: Großes Update. Neu: "Alles automatisch" auf der Startseite - erkennt selbst Probleme (Dienste, Windows Update, Netzwerk, WMI, Dateisystem), behebt sie und optimiert den PC komplett, ganz ohne Rückfragen (für Einsteiger gedacht). Neuer Knopf "Mega-Leistung" (Ultimative Leistung, Effekte/Animationen aus, Energiesparen und unnötige Autostarts aus). Windows 11 26H2 als Ziel, dazu "Windows 11 auch ohne TPM/Secure Boot erlauben" und die "nicht unterstützt"-Hinweise/Wasserzeichen dauerhaft aus (Update-Steuerung). Erkennt jetzt Geräteart und System genau (Client/Server, Desktop/Notebook/Tablet/Server/VM, Marke) und läuft auf Windows 10 und Windows Server 2012-2025. Schnellerer Start mit Ladeanzeige. Open-Source-Infobereich mit Quelltext, Prüfsumme, Datenschutz-Hinweis und "Fehler melden".',
    'Version 12.5: Treiber für alle Geräte (Kamera, Drucker, USB, Sound ...) kommen über Windows Update - klappt der Hersteller-Katalog mal nicht (z.B. HP), wird automatisch auf Windows Update ausgewichen. Hersteller-Katalog robuster entpackt. Benutzerkontensteuerung-aus und fehlende Datensicherung gelten nicht mehr als Sicherheits-PROBLEM, sondern als Empfehlung. Komplettsicherung erkennt installierte Backup-Programme und empfiehlt kostenlose. Dunkelmodus: schlecht lesbare Stellen (helle Kästen) behoben.',
    'Version 12.1: BitLocker mit einem Klick - auf der Seite Sicherheit verschlüsselt "C: mit einem Klick verschlüsseln" das Windows-Laufwerk und legt den Wiederherstellungsschlüssel automatisch in einem eigenen Ordner ("BitLocker-Schluessel") im PC-Tools-Datenordner ab - mit Hinweis-Datei, dass der Schlüssel unbedingt zusätzlich außerhalb des PCs gesichert werden muss. PC-Tools öffnet den Ordner direkt; "Schlüssel-Ordner öffnen" führt jederzeit dorthin.',
    'Version 12.0: Neuer durchsuchbarer Installer - auf der Seite Installieren gibt es jetzt die Online-Suche über winget und Chocolatey (zehntausende Programme). Quelle oben wählen, Begriff eintippen, Enter drücken, markieren und installieren. Alle Quellen (Ninite wenn vorhanden, winget, Chocolatey) ergänzen sich automatisch: fehlt ein Programm in einer Quelle, übernimmt die andere. Alles kostenlos.',
    'Version 11.5: Programm-Updates aus mehreren kostenlosen Quellen - Chocolatey (10.000+ Pakete) läuft parallel zu winget und Ninite, die Quellen ergänzen sich als Rückfall; neue Knöpfe für UniGetUI und Patch My PC Home',
    'Version 11.0: Windows-Update-Doktor und Komplett-Reparatur - findet und löst Blockaden von Funktions-Updates (unverträgliche Programme/Treiber wie VMware, alte Netzwerkfilter), dazu die tiefgreifende Komplett-Reparatur per Batch-Datei mit ausführlichem Super-Protokoll',
    'PC-Tools ist Open Source und kostenlos - der Quelltext liegt offen auf GitHub (Lizenz Apache 2.0). Jeder darf das Programm prüfen, nutzen und weitergeben.',
    'Version 10.0.1: Microsoft Surface - alle Varianten des Treiber- und Firmwarepakets als Liste (Windows-Version, Build, Version, Größe, passt/empfohlen), gewählte Variante wird geladen bzw. installiert',
    'Version 10.0: Große neue Version - Auswahl Lite oder Vollversion beim ersten Start, PC-Reiniger (wie CCleaner), Komplettsicherung mit Wiederherstellungspaket, KI-Assistent (Claude), Ein-Klick-Optimierung mit Vorher/Nachher-Bericht, Treiber- und BIOS-Sicherung vor Updates, Akku und Energie, Fernwartungs-Dashboard in Meine PCs',
    'Version 10.0: Neue Seite Komplettsicherung - regelmäßiges Systemabbild des ganzen PCs (Windows-Sicherung) auf externe Festplatte oder NAS mit Live-Fortschritt, deutschen Erklärungen zu Fehlercodes, Prüfung jeder Sicherung (auf Wunsch mit eingebundenem Abbild), Versionen und Aufbewahrung, eigenem Zeitplan (wöchentlich/monatlich, wecken, nur am Netzteil, nachholen), Handy-Benachrichtigung, Wiederherstellungspaket am Ziel, automatischem Auffrischen des Notfall-Sticks, einzelnen Dateien aus dem Abbild und Menüpunkt S (Systemabbild wiederherstellen) im Reparatur-Menü',
    'Version 10.0: Neue Seite PC-Reiniger (Bereich Pflege) - Reinigung auf CCleaner-Professional-Niveau: Edge, Chrome, Brave, Vivaldi, Opera und Firefox in allen Profilen (Cache, Code-/GPU-/Shader-Cache, Download-Verlauf, auf Wunsch Verlauf, Cookies mit Ausnahmeliste, Sitzung und Formulardaten - nie Kennwörter), über 20 Programme (Office, Teams, Discord, Spotify, Steam, Epic, Battle.net, Shader-Caches, Adobe, VS Code, JetBrains, Zoom, WhatsApp ...), Windows-Spuren; Analyse mit Diagramm, Profile Sicher/Gründlich/Datenschutz/Eigene, auf Wunsch in der automatischen Pflege. Dazu vorsichtige Registry-Reinigung mit .reg-Sicherung, Programme deinstallieren mit Restesuche, Browser-Erweiterungen und Startseiten-Prüfung, Kontextmenü-Manager, fremde geplante Aufgaben und freien Speicher sicher löschen (cipher /w, TRIM für SSDs)',
    'Version 10.0: Ein-Klick-Optimierung auf der Übersicht - ein runder Knopf misst den Zustands-Score, setzt einen Wiederherstellungspunkt, räumt auf, installiert Windows-, Treiber- und Programm-Updates, optimiert, prüft Systemdateien, Sicherheit und Datensicherung und zeigt danach einen Vorher/Nachher-Bericht (auch als PDF) mit Sprung zu jeder offenen Empfehlung; Fortschritt direkt auf der Karte, auf Wunsch als automatische Pflege',
    'Version 10.0: Treiber- und BIOS-Sicherung vor Updates - vor jedem Treiber-, BIOS- oder Firmware-Update (Windows Update, NVIDIA, Intel, HP, Lenovo, Dell, Surface, Treiberpakete) werden alle Treiber mit Geräteliste und BIOS-Version gesichert; danach zeigt die Treiber-Seite, was sich geändert hat, und spielt einzelne Geräte oder den ganzen Stand zurück',
    'Version 10.0: Neue Seite Akku und Energie - Akku-Gesundheit mit Kapazitätsverlauf und Verschleiß-Prognose, "Was zieht den Akku leer?" (Energieverbrauch je Programm), Energie-Analyse auf Deutsch, Standby-Diagnose (was hält den PC wach, wer weckt ihn nachts, Standby-Analyse), Energiesparpläne und Windows-11-Energiemodus, Ladegrenze für HP/Dell direkt und Lenovo/Surface mit Anleitung, USV-Erkennung und Stromspartipps für Desktop-PCs',
    'Version 10.0: Meine PCs wird zum Fernwartungs-Dashboard - Live-Übersicht mit Online-Erkennung (Lebenszeichen alle 10 Minuten), sortierbare Liste aller PCs mit Zustands-Score, Neustart-Bedarf, offenen Updates, Sicherung und Komplettsicherung, Aufträge an mehrere PCs gleichzeitig (neu: Selbsttest, Notfall-Stick-Status, Komplettsicherung, Neustart mit Nachricht und Wartezeit), Auftragsverlauf, Detailansicht mit Score-Verlauf und Protokoll, Benachrichtigung bei Problemen ohne doppelte Meldungen und Auftragsschlüssel zum Absichern der Fernaufträge',
    'Version 10.0: KI-Assistent - Claude beantwortet Fragen zu deinem PC und zu PC-Tools in einfachen Worten, erklärt Protokolle und Fehlermeldungen und schlägt passende Aktionen vor (nur nach deiner Bestätigung). Mit eigenem Anthropic-API-Schlüssel direkt im Programm (verschlüsselt gespeichert, Verbrauchszähler und Monatslimit) oder ohne Schlüssel über "In Claude.ai fragen". Du bestimmst, welche PC-Infos mitgesendet werden. Knopf "Assistent" unten in der Statusleiste und Strg+Umschalt+A auf jeder Seite.',
    'Version 9.3: Stabiler - neue Versionen werden vor der Installation geprüft, die Vorversion gesichert und bei Startproblemen automatisch wiederhergestellt; Einstellungen ausfallsicher gespeichert; Zeitplan und Oberfläche starten Aufgaben nie mehr gleichzeitig; Fehler in der Oberfläche werden abgefangen und protokolliert. Neu: Selbsttest, "Auf Vorversion zurück", Update-Verzögerung (Test-PC zuerst) und Lite-Ansicht (Einstellungen > Stabilität)',
    'Version 9.2.1: Automatischer Voll-Lauf räumt vor Windows Update die Systempartition (EFI/System-reserviert) frei, wenn dort weniger als 30 MB frei sind - behebt "Die für das System reservierte Partition konnte nicht aktualisiert werden"; entfernte Dateien werden im Datenordner unter ESP-Sicherung gesichert',
    'Version 9.2: Notfall-Stick lädt automatisch die neueste offizielle Windows-11-ISO von Microsoft (startet auf jedem PC, auch mit Secure Boot) und legt ISO und Reparaturquelle (install.esd mit Editionsliste) auf die exFAT-Datenpartition - das Reparatur-Menü findet die Quelle für DISM selbst; Datenpartition wird jetzt mit format.com eingerichtet und bei Problemen automatisch nachgeholt',
    'Version 9.1: Toolbox fest eingebaut - die Werkzeuge werden beim Start automatisch im Hintergrund geladen und aktuell gehalten (ohne andere Aufgaben zu blockieren, mit gemeinsamem Ordner aus Meine PCs auch für alle PCs); Zustands-Score: Speicherplatz bei großen Laufwerken, Sicherheitswert, USB-Laufwerke und Absturz-Zählung korrigiert',
    'Version 9.1: Neue Seite Windows-Reparatur - über 70 Reparaturen an einem Ort (DISM mit ISO-Quelle, SFC mit CBS.log-Auswertung, Windows Update komplett zurücksetzen, Netzwerk-Tiefenreparatur mit Dienst-Vergleich gegen Windows 11, NDIS-Filter von Virenschutz/VPN wie Panda erkennen und lösen, IPv4-/IPv6-Registrierung, WinRE, Startdateien, abgesicherter Modus, Apps, WMI, .NET, Visual C++, Gruppenrichtlinien), Reparatur-Assistent mit Profilen, Lauf im Hintergrund mit Verlauf, Reparaturinstallation (In-place Upgrade) mit ISO-Prüfung und Textmodus Windows-Reparatur.cmd für den Stick',
    'Version 9.0: Neuer Bereich WERKZEUGE mit sieben neuen Seiten - Toolbox, Hardware-Test, Netzwerk-Werkzeuge, Notfall-Stick, Fernhilfe, Geräte-Akte und Software-Kiosk - dazu der Zustands-Score auf der Übersicht und eine überarbeitete Oberfläche',
    'Version 9.0: Toolbox - 25 bewährte Admin- und Diagnose-Werkzeuge (Sysinternals, CPU-Z, HWiNFO, CrystalDiskInfo, Rufus, Ventoy, PuTTY, RustDesk ...) auf Knopfdruck, immer in der neuesten Version direkt vom Hersteller, mit Signaturprüfung und auf Wunsch auf dem USB-Stick; Software-Kiosk - Programme wie im App-Store nach Rolle installieren (Büro, Rezeption, Kasse, Entwicklung, Grafik, Familie, Gaming, Admin), eigene Rollen speichern, exportieren und importieren, dazu winget-Suche',
    'Version 9.0: Neue Seite Hardware-Test - Arbeitsspeicher, Datenträger (Lesetest mit Geschwindigkeitskurve), Prozessor-Belastung mit Takt/Temperatur-Diagramm und Drosselungserkennung, Akku mit echter Laufzeitmessung, Bildschirm-Pixeltest mit Pixel-Wiederbeleber, Tastatur- und Touch/Stift-Test - und am Ende ein Prüfprotokoll als PDF mit Unterschriftszeilen',
    'Version 9.0: Zustands-Score auf der Übersicht - ein Wert von 0 bis 100 aus Sicherheit, Updates, Speicherplatz, Datenträgern, Akku, Stabilität, Startzeit, Geräten und Temperatur, mit Trend, 90-Tage-Verlauf und Handy-Benachrichtigung bei einem Einbruch',
    'Version 9.0: neue Seite Notfall-Stick (bootfähiger Reparatur-Stick mit der Wiederherstellungsumgebung des PCs, Reparatur-Menü, Dateirettung, Treiber-Sicherung), neue Seite Fernhilfe (Hilfe-Paket mit Handy-Benachrichtigung, Schnellhilfe, RustDesk, TeamViewer, AnyDesk mit Signaturprüfung)',
    'Version 9.0: Neue Seite Netzwerk-Werkzeuge - alle Geräte im Netz mit Hersteller und "neu"-Markierung, Wake-on-LAN, Speedtest-Verlauf mit Diagramm (LAN/WLAN), DNS-Vergleich mit Empfehlung, WLAN-Kanal-Planer (2,4 und 5 GHz) und Router-Check mit FRITZ!OS-Version und UPnP-Freigaben',
    'Version 9.0: Neue Seite Geräte-Akte - Hardware, Seriennummer, Garantie, Akku und Zustandsverlauf automatisch, dazu Kaufdaten, Inventarnummer, Standort, Wartungsbuch, Rechnungen/Fotos und Akte als PDF; Standort und Besitzer erscheinen in "Meine PCs"',
    'Version 8.1: Updates werden beim Start automatisch installiert - mit Fortschrittsanzeige (Datei, Größe, Geschwindigkeit, Prüfsumme) und Neustart von PC-Tools; braucht eine Pflege, ein Treiber oder eine Reparatur einen Neustart, bietet PC-Tools ihn direkt an (jetzt, in 10 Minuten oder später mit Erinnerung)',
    'Version 8.0: Aus PC-Pflege wird PC-Tools - neuer Name, neues Logo (Monitor mit Chip und Schraubenschlüssel). Einstellungen, Zeitpläne, Update-Weg und alles andere bleiben unverändert; Verknüpfungen werden automatisch umbenannt',
    'Version 7.9: "Mit neuer MAC testen" (zeigt, ob der Router nur diesem Gerät die Adresse verweigert), "Original-MAC zurück", doppelte Netzwerkprofile (Netz 2, 3, 4 ...) erkennen und bereinigen, genauere Aussagen im DHCP-Live-Test',
    'Version 7.8: DHCP-Live-Test (30 s) mit Paketmitschnitt - zeigt, ob der PC fragt, ob ein DHCP-Server antwortet und ob andere Geräte ebenfalls keine Adresse bekommen, erkennt Netz und Router und setzt auf Wunsch eine freie feste IP; Tiefenanalyse wertet den Mitschnitt jetzt richtig aus (auch deutsche pktmon-Ausgabe)',
    'Version 7.7: Netzwerk-Tiefenanalyse - sammelt alle Netzwerkdaten, einen Live-Test mit DHCP-Paketmitschnitt (pktmon), eine eigene DHCP-Probe beim Router, WFP-Filter und verworfene Pakete, Registrierung und Ereignisse in eine ZIP-Datei mit automatischer Auswertung (Netzwerk-Diagnose, Textmodus Taste T, Netzwerk-Tiefenanalyse.cmd auf dem Stick)',
    'Version 7.6: Treiber-Seite "Problem beheben" (USB Code 10: Energiesparen aus, Hub und Gerät neu starten, neu erkennen, Hersteller aus VID/PID; Geistergeräte entfernen), PS/2-Anschluss ohne Gerät (Code 24) gilt als harmlos, eigene Geräte als harmlos ausblenden; Treiberaufräumen löscht keine neueren Treiberpakete mehr',
    'Version 7.5: Netzwerk-Diagnose erkennt Hyper-V-Probleme (verwaiste Switch-Bindung, Switch ohne Freigabe für den PC, vEthernet ohne IPv4, belegter DHCP-Port 68, reservierte Ports durch WinNAT, ICS) und behebt sie: Adapter vom Switch lösen, Switch löschen, WinNAT neu starten, Hypervisor-Test, Hyper-V-Netz zurücksetzen - auch im Netzwerk-Notfall-Textmodus (Taste H)',
    'Version 7.4.1: Programm-Updates mit denselben Rückfallwegen wie die Installation (HWiNFO direkt beim Hersteller, PowerToys neu installieren bei anderer Installationsart), kein unnötiger Nachlauf, kein falscher Neustart-Hinweis nach HP-Treibern',
    'Version 7.4: Korrekturen aus dem Protokoll - winget liest keine Fußzeilen mehr als Programm ("ierungen"), HWiNFO und andere Hersteller-Downloads laden wie ein Browser (umgeht 403-Sperren, neue Download-Quellen), Lenovo Thin Installer meldet kein falsches "erfolgreich" mehr',
    'Version 7.3: neue Seite Netzwerk-Diagnose (keine IPv4-Adresse/169.254, kein Internet: Ursache finden und mit einem Klick reparieren, auch offline), neue Seite Microsoft Surface (Modell, Firmware, Treiberpaket auch für den USB-Stick, UEFI, Akku, Type Cover, bekannte Probleme), portable Version mit Netzwerk-Notfall.cmd',
    'Version 7.2: Treiber-Update-Center (NVIDIA, Intel, Windows Update in einer Liste), Treiber-Werkzeuge, Treiberspeicher, Verlauf und Sicherungen; Update-Seite mit Stand, Programm- und Windows-Updates zum Auswählen; Drucker: Warteschlange bereinigen und neu starten mit einem Knopf',
    'Version 7.1: Einrichtungs-Assistent mit Unternehmens-Schritt (Domäne, Richtlinien, WLAN, VPN, Proxy, Zertifikate, Inventar), Begrüßung mit dem Namen des angemeldeten Benutzers, winget-Korrekturen (PowerToys, unbekannte Versionen, HWiNFO-Update)',
    'Version 7.0: Einrichtungs-Assistent (alles in einem Durchgang, mit Update-Runden über Neustarts), Neugerät-Check mit Prüfbericht, automatische Windows-Installation per USB-Stick, eigene Programm-Profile',
    'Neu: Drucker und Scanner (vollständige Herstellertreiber, Fehlerbehebung), Netzwerk-Sicherheit (Schwachstellen finden und schließen), Sicherheitslücken in Programmen, Update-Steuerung, Konten und Netzwerk, Einstellungen übertragen',
    'Neu: Hersteller-Treiberpaket (Lenovo/HP/Dell), Garantie-Anzeige, Fernaufträge an andere PCs, Anbindung an Home Assistant (MQTT/REST) und RMM, neues Design mit Seitensymbolen und sanften Übergängen',
    'Version 6.1: neue Seite BIOS-Einstellungen für Lenovo, HP und Dell - alle Einstellungen lesen, ändern, sichern; Schnellschalter nach Thema; Neustart direkt ins BIOS',
    'Version 6.0: Sorgenfrei-Modus, Suche mit Strg+K und PC-Bericht als PDF auf der Übersicht',
    'Neue Seiten: Meine PCs mit Handy-Benachrichtigung, Änderungen (Vorher/Nachher), Gerätezustand mit Startzeit, Speicherplatz, Datenschutz, Apps entfernen, Netzwerk und Lizenzen',
    'Neues Gerät: Extra-Profile Virenschutz (Panda Dome, Bitdefender ...) und Windows-Server-Tools (RSAT, OpenSSH, Hyper-V, Sandbox ...)',
    'Lizenzen: Windows-, Office- und Programmlizenzen auslesen, verschlüsselt sichern und mit Kennwort auf den neuen PC übertragen'
)
$ManualChapters = @(
    @{ Tab = 'TabOverview'; Glyph = '&#xE80F;'; Color = '#2D7FF9'; Title = 'Übersicht'; Intro = 'Die Startseite zeigt den Zustand des PCs auf einen Blick.'
       Items = @('Live-Anzeigen|Prozessor, Arbeitsspeicher, Laufwerk C: und Sicherheitswert werden laufend aktualisiert. Gelb heißt: knapp.', 'Schnellaktionen|Die wichtigsten Aufgaben mit einem Klick - alles läuft im Hintergrund, der Fortschritt steht unten und im Protokoll.', 'System- und Hardware-Infos|Windows-Version, Modell, Seriennummer, Datenträger, Akku, Netzwerk. "Alle Infos kopieren" legt alles in die Zwischenablage (z.B. für den Support).')
       Tip = 'Alles, was PC-Tools tut, läuft auch weiter, wenn du das Fenster schließt.' }
    @{ Tab = 'TabOverview'; Glyph = '&#xE8FB;'; Color = '#059669'; Title = 'Sorgenfrei-Modus, Suche und PDF-Bericht'; Intro = 'Drei Abkürzungen auf der Übersicht, die viel Arbeit sparen.'
       Items = @('Sorgenfrei-Modus|Ein Klick stellt alles auf "automatisch": wöchentliche Pflege mit Updates, Selbst-Aktualisierung, Wiederherstellungspunkte, tägliche Datensicherung (wenn ein Ziel eingetragen ist), Defender- und Firewall-Empfehlungen, überflüssige Autostarts aus und Handy-Benachrichtigung. Jeder Punkt lässt sich vorher abwählen.', 'Suche (Strg+K)|Strg+K oder "Suchen ..." oben links öffnet die Schnellsuche. Einfach lostippen, z.B. "wlan kennwort", "akku", "bitlocker" oder "product key" - Pfeiltasten wählen, Enter öffnet die Seite oder startet die Aktion direkt.', 'PC-Bericht als PDF|Zustand (Ampel), Hardware, Laufwerke mit Belegung und SSD-Verschleiß, Akku, Sicherheit, Windows-Lizenz, Stabilität der letzten 30 Tage und Verlauf - fertig als PDF, z.B. für den Verkauf oder die Werkstatt. Braucht Microsoft Edge; ohne Edge entsteht eine Webseite.')
       Tip = 'Der Sorgenfrei-Modus ist ideal für PCs von Familie und Freunden: einmal einrichten, dann meldet sich der PC nur noch, wenn wirklich etwas ist.' }
    @{ Tab = 'TabOverview'; Glyph = '&#xE945;'; Color = '#6D4AE8'; Title = 'Ein-Klick-Optimierung'; Intro = 'Neu in 10.0: der große runde Knopf auf der Übersicht erledigt die komplette Pflege in einem Durchgang - und zeigt danach schwarz auf weiß, was sie gebracht hat.'
       Items = @('Ablauf|1. Zustands-Score und Ampel vorher messen (und den Stand für die Seite Änderungen festhalten), 2. Wiederherstellungspunkt (ein Punkt jünger als 2 Stunden wird genutzt), 3. Aufräumen nach der Seite Aufräumen, 4. Windows-Updates (mit Systempartition-Prüfung), 5. Treiber und Firmware (Hersteller-Tool, Grafik, Intel WLAN/Bluetooth - vorher automatische Treiber- und BIOS-Sicherung), 6. Programme (Ninite, winget, Store) und Virendefinitionen, 7. DNS-Cache, Laufwerke optimieren und Systemdateien prüfen, 8. Sicherheit, 9. Datensicherung, 10. Zustand nachher, 11. Bericht.', 'Systemprüfung|DISM /CheckHealth dauert nur Sekunden. Nur wenn der Komponentenspeicher als beschädigt markiert ist, folgen DISM /RestoreHealth und SFC /scannow (lang) und danach eine zweite Prüfung - eine gelungene Reparatur steht unter "Behoben". Ein reines SFC /verifyonly kostet 5-15 Minuten und findet selten mehr, deshalb läuft es nicht bei jedem Klick.', 'Fortschritt|Direkt auf der Karte: jeder Schritt als Chip (grau = wartet, blau = läuft, grün = erledigt, orange = mit Hinweis, durchgestrichen = abgewählt), Fortschrittsbalken und aktuelle Tätigkeit. Der Lauf arbeitet im Hintergrund weiter, auch wenn PC-Tools geschlossen wird; Abbrechen beendet den laufenden Schritt und erstellt trotzdem einen Bericht.', 'Vorher/Nachher-Bericht|Score vorher und nachher als Ringe, frei gewordener Speicher, installierte Updates, behobene Probleme, jede Phase mit Ergebnis und Dauer, jeder Score-Bestandteil vorher/nachher, geänderte Treiber, Sicherheit und Datensicherung - und "Noch zu tun" mit einem Knopf, der direkt zur passenden Seite springt. Speichern als PDF (Edge) oder im Browser öffnen; alle Berichte liegen im Datenordner unter EinKlick.', 'Einstellungen|Unter der Karte: Windows-Updates, Treiber und Firmware, Programme und Virenschutz, Optimieren und Systemprüfung an- oder abwählen. Was genau aufgeräumt und aktualisiert wird, bestimmen wie immer die Seiten Aufräumen, Updates und Optimieren.', 'Automatisch|"Als automatische Pflege planen" lässt den Zeitplan (Seite Zeitplan: Tag und Uhrzeit) die komplette Ein-Klick-Optimierung ausführen - mit Bericht und Handy-Benachrichtigung, wenn eingerichtet. Auch im Sorgenfrei-Modus wählbar.', 'Score sinkt?|Direkt nach Updates meldet Windows oft "Neustart ausstehend" - das kostet Punkte in Updates. Nach dem Neustart steigt der Wert wieder; der Bericht weist darauf hin.')
       Tip = 'Einmal im Monat von Hand oder jede Woche automatisch - und nach jedem Lauf zeigt der Bericht, was noch zu tun ist.' }
    @{ Tab = 'TabAssistant'; Glyph = '&#xE99A;'; Color = '#D97757'; Title = 'KI-Assistent: Fragen an Claude'; Intro = 'Neu in 10.0: Claude (von Anthropic) erklärt dir deinen PC und PC-Tools in einfachen Worten - mit Profi-Details, wenn du sie willst.'
       Items = @('Fragen|Unten ins Feld tippen und Enter drücken (Umschalt+Enter = neue Zeile). Die Vorschläge im leeren Chat ("Warum ist mein PC langsam?", "Erkläre das letzte Protokoll", "Ist mein PC sicher?" ...) senden sofort. Antworten sind formatiert: fett, Listen, Befehle als Codeblock mit Knopf "Kopieren". Jede Antwort lässt sich kopieren, das ganze Gespräch über "Exportieren" als Textdatei speichern; "Neues Gespräch" beginnt von vorn.', 'Von jeder Seite|Der Knopf "Assistent" unten in der Statusleiste oder Strg+Umschalt+A öffnet den Assistenten mit der gerade offenen Seite als Kontext - Claude weiß dann, worum es geht, und kennt den Handbuch-Text dieser Seite.', 'Protokoll und Fehler erklären|Auf der Seite Protokoll erklärt "Protokoll erklären (KI)" den markierten Ausschnitt (sonst die letzten Zeilen) - auch per Rechtsklick > "Mit KI-Assistent erklären". Fehlerfenster von PC-Tools haben den Knopf "Assistent fragen". Beides hängt den Text nur an - gesendet wird erst mit "Senden".', 'Aktionen nur mit deinem Ja|Claude kann nur Aktionen aus einer festen Liste vorschlagen: Seite öffnen, Aufräumen (analysieren/starten), Optimieren, Updates suchen/installieren, Netzwerk-Diagnose, Sicherheit prüfen, Zustand neu berechnen, Selbsttest, Wiederherstellungspunkt, Windows-Reparatur mit vorgewähltem Profil sowie letztes Protokoll bzw. Zustand lesen. Jeder Vorschlag erscheint als Karte "Ausführen? Ja/Nein". Befehle aus Claudes Text führt PC-Tools nie aus.', 'Ohne Schlüssel: In Claude.ai fragen|Kopiert Frage, Anhänge und die freigegebenen PC-Infos in die Zwischenablage und öffnet claude.ai im Browser - dort einfügen (Strg+V) und absenden. Funktioniert mit jedem kostenlosen oder bezahlten Claude-Konto.')
       Tip = 'Je genauer die Frage, desto besser die Antwort: "Seit dem letzten Update startet Outlook nicht mehr" hilft mehr als "Outlook geht nicht".' }
    @{ Tab = 'TabAssistant'; Glyph = '&#xE8D7;'; Color = '#D97757'; Title = 'KI-Assistent: Schlüssel, Kosten und Datenschutz'; Intro = 'Was du für Antworten direkt im Programm brauchst, was es kostet und welche Daten das Haus verlassen.'
       Items = @('KI-Anbieter|Rechts unter "Verbindung zur KI" wählst du per Dropdown, welche KI antwortet. Komplett kostenlos und ohne Konto: Ollama - die KI läuft dann auf deinem PC ("Ollama einrichten" installiert sie und lädt das Modell; ab ca. 8 GB Arbeitsspeicher, mit Grafikkarte schneller), deine Fragen verlassen den PC nicht. Kostenlos mit Gratis-Konto: Groq und OpenRouter (Tageslimits), Mistral (EU-Server, Gratis-Testtarif). Bezahlt: Claude (Anthropic), ChatGPT (OpenAI), Gemini (Google). "Andere KI / eigener Server" passt zu jeder OpenAI-kompatiblen Schnittstelle (z.B. LM Studio, DeepSeek, Azure).', 'API-Schlüssel|Für Anbieter mit Konto den Schlüssel beim Anbieter erzeugen (Link unter dem Feld), einfügen und speichern. Er wird je Anbieter getrennt mit dem Windows-Datenschutz (DPAPI) verschlüsselt im Datenordner abgelegt - wahlweise nur für dein Windows-Konto oder für alle Konten dieses PCs -, nie wieder angezeigt und nie protokolliert. "Verbindung testen" prüft Schlüssel und Modell.', 'Automatik|Nach jedem Pflegelauf erklärt die KI das Ergebnis kurz, einmal pro Woche gibt es eine Zusammenfassung. Mit der lokalen KI (Ollama) läuft das ohne Nachfrage; mit einer Online-KI nur, wenn "Automatik auch mit Online-KI" angehakt ist. Die Ergebnisse erscheinen im Assistenten, Rückfragen sind direkt möglich.', 'Sprache|"Sprechen" öffnet die Spracheingabe von Windows (wie Windows-Taste + H) - einfach sprechen, dann Enter. "Vorlesen" unter jeder Antwort liest sie mit der Windows-Sprachausgabe vor; erneut klicken stoppt.', 'Gedächtnis|Das Gespräch wird je PC gespeichert und beim nächsten Öffnen fortgesetzt. Bei "Neues Gespräch" merkt sich der Assistent in 1-3 Zeilen, worum es ging, und berücksichtigt das später. "Gedächtnis ansehen/löschen" unter Datenschutz.', 'Was die KI lesen darf|Nur nach deiner Bestätigung je Aktion: letztes Protokoll, Zustand, Windows-Ereignisprotokoll, Bluescreens und Abstürze, Autostart, Treiber und Geräte, Windows-Updates, Netzwerk-Bericht. Ändern kann sie nichts selbst - Aufgaben startet sie nur über die bestätigten Knöpfe von PC-Tools.', 'Modell|Je Anbieter gibt es eine Vorschlagsliste; ein anderer Modellname lässt sich eintippen. PC-Tools merkt sich das Modell je Anbieter. Bei Claude: Haiku schnell und günstig, Sonnet gründlicher, Opus am stärksten.', 'Verbrauch und Limit|PC-Tools zählt je Monat die Token, die der KI-Anbieter in jeder Antwort meldet (Eingabe + Ausgabe). Mit einem Monatslimit hört der Assistent auf, sobald es erreicht ist. "Max. Länge einer Antwort" begrenzt jede einzelne Antwort. Lange Gespräche werden automatisch vorne gekürzt.', 'Datenschutz|Gesendet wird nur nach deiner ausdrücklichen Frage - und nur, was du rechts anhakst: aktuelle Seite, Systemübersicht (ohne Seriennummer und Computername), Zustand und Score, letzter Lauf, Anhänge. Kennwörter, Token, Product Keys und Benutzernamen in Pfaden werden vorher unkenntlich gemacht. "Vorschau: was würde gesendet?" zeigt alles vorab. Der Gesprächsverlauf bleibt nur im Arbeitsspeicher.', 'Fehlermeldungen|401 = Schlüssel ungültig, 429 = zu viele Anfragen (kurz warten), 529 = Claude überlastet (später erneut, wird einmal automatisch wiederholt), Netzwerk/Proxy = Internetverbindung oder Proxy prüfen (Netzwerk-Diagnose). Bei Fehlern gibt es "Nochmal versuchen".')
       Tip = 'Für Firmen-PCs: Mit "Monatslimit" und dem günstigen Standardmodell bleiben die Kosten planbar - typische Fragen kosten nur Bruchteile eines Cents.' }
    @{ Tab = 'TabFleet'; Glyph = '&#xE977;'; Color = '#4F46E5'; Title = 'Meine PCs und Handy-Benachrichtigungen'; Intro = 'Alle eigenen PCs auf einer Seite - und eine Nachricht aufs Handy, wenn einer Hilfe braucht.'
       Items = @('Gemeinsamer Ordner|Ein Ordner auf dem NAS oder in OneDrive, den alle PCs erreichen. Jeder PC legt dort nach jeder Pflege und jeder Ampel-Prüfung eine kleine Statusdatei ab (Zustand, freier Platz, Updates, Sicherung, Version).', 'Kacheln|Jeder PC als Kachel mit Ampelfarbe und Alter der Meldung. Anklicken zeigt Details; von dort per Remotedesktop verbinden.', 'ntfy|Kostenlose App (ntfy.sh) - ein eigenes, schwer zu erratendes Thema ausdenken, in der App abonnieren und hier eintragen.', 'Home Assistant|Webhook-Adresse einer Automation eintragen - die Meldung kommt als JSON (Titel, Text, Stufe, PC).', 'Chat|Webhook für Discord, Slack oder Teams.', 'Wann?|Wählbar: Ampel wird rot, Warnungen, Sicherung fehlgeschlagen, Bluescreen, und wenn wieder alles gut ist. Jede Meldung kommt nur einmal, nicht bei jeder Prüfung erneut.')
       Tip = 'Mit "Testnachricht senden" prüfen, ob alles ankommt.' }
    @{ Tab = 'TabFleet'; Glyph = '&#xE977;'; Color = '#4F46E5'; Title = 'Fernwartungs-Dashboard'; Intro = 'Neu in 10.0: alle eigenen PCs live auf einer Seite - mit Aufträgen an viele PCs gleichzeitig und Meldung aufs Handy, wenn irgendwo etwas schiefgeht.'
       Items = @('Lebenszeichen|Jeder PC mit eingeschaltetem "Lebenszeichen senden" schreibt alle 10 Minuten eine kleine Datei in den Ordner Heartbeat (Aufgabe "PC-Pflege Fernaufträge", läuft als SYSTEM). Online heißt: das letzte Lebenszeichen ist höchstens 25 Minuten alt (einstellbar). PCs ohne diese Aufgabe erscheinen als "ohne Lebenszeichen" - dort einmal PC-Tools öffnen und Einstellungen speichern.', 'Kacheln|Online, offline, Ampel rot/gelb/grün und offene Aufträge auf einen Blick. Die Seite aktualisiert sich alle 30 Sekunden, solange sie offen ist.', 'Liste|Alle PCs mit Online-Zustand, Ampel, Zustands-Score, Windows-Build, PC-Tools-Version und -Ansicht (Voll/Lite), Neustart nötig, offene Windows-Updates (alle 6 Stunden aus dem Windows-Update-Zwischenspeicher gezählt), freiem Platz, Laufzeit, Fehlern im Systemprotokoll der letzten 24 Stunden, Datensicherung, Komplettsicherung, Aufträgen, Standort und Auftragsschutz. Spaltenkopf anklicken sortiert, die Sortierung bleibt beim Aktualisieren erhalten.', 'Aufträge an mehrere PCs|PCs mit Strg/Umschalt oder "Alle wählen" markieren, dann Pflege, Updates, Aufräumen, Sicherung, Virenscan, Selbstupdate, Komplettsicherung, Selbsttest, Notfall-Stick-Status, Zustand melden, Neustart oder Herunterfahren. Neustart und Herunterfahren immer mit Wartezeit (1 bis 120 Minuten) und einer Nachricht, die der angemeldete Benutzer sofort sieht (msg.exe, zusätzlich die Windows-Meldung von shutdown.exe).', 'Aufträge und Verlauf|wartet = noch nicht abgeholt, läuft, fertig, Fehler, abgelehnt (Sicherheitsprüfung), abgelaufen (älter als 3 Tage). Doppelklick zeigt das ganze Ergebnis - beim Selbsttest die komplette Prüfliste des fernen PCs. Wartende Aufträge lassen sich zurückziehen, alte erneut senden.', 'Details|Klick auf einen PC zeigt alle Werte, die Ampel-Punkte, die Geräte-Akte, den Score-Verlauf der letzten 30 Einträge als Diagramm und den Protokoll-Auszug, den der PC nach jeder Meldung hochlädt (Ordner Protokolle).', 'Benachrichtigung bei Problem|Ein oder mehrere PCs, die meist laufen, überwachen alle anderen: PC länger als N Stunden offline, Zustands-Score bricht um N Punkte ein, Datensicherung/Komplettsicherung fehlgeschlagen oder veraltet, Fernauftrag fehlgeschlagen. Vor dem Senden legt der meldende PC eine Sperrdatei im Ordner Meldungen an - so kommt jede Meldung nur einmal, egal wie viele PCs überwachen. Klappt das Senden nicht, wird die Sperre wieder freigegeben.', 'Auftragsschutz|Aufträge laufen als SYSTEM. Mit einem Auftragsschlüssel (gleiches Kennwort auf allen PCs) werden Aufträge mit HMAC-SHA256 signiert; PCs mit Schlüssel lehnen unsignierte oder veränderte Aufträge ab. Zusätzlich lässt sich festlegen, dass Aufträge nur angenommen werden, wenn keine allgemeinen Gruppen (Jeder, Benutzer, Gäste) in den Auftragsordner schreiben dürfen. Immer gilt: nur die festen Aktionen, nur Aufträge für den eigenen PC, höchstens 3 Tage alt.')
       Tip = 'Am besten auf dem NAS die Freigabe so einrichten, dass nur dein eigenes Konto schreiben darf, und zusätzlich einen Auftragsschlüssel festlegen. Die Spalte "Schutz" zeigt, ob alle PCs denselben Schlüssel haben.' }
    @{ Tab = 'TabTm'; Glyph = '&#xE9D9;'; Color = '#0891B2'; Title = 'Task-Manager'; Intro = 'Laufende Programme, Auslastung und Autostart.'
       Items = @('Diagramme|CPU, Arbeitsspeicher, Datenträger und Netzwerk der letzten Minute.', 'Prozesse|Sortieren, filtern und hängende Programme beenden.')
       Tip = 'Ein Programm frisst dauerhaft CPU? Rechtsklick > beenden, danach unter Fehler beheben die Fehlersuche starten.' }
    @{ Tab = 'TabClean'; Glyph = '&#xE74D;'; Color = '#16A34A'; Title = 'Aufräumen'; Intro = 'Entfernt, was Windows und Programme liegen lassen - persönliche Dateien werden nie angefasst.'
       Items = @('Temporäre Dateien|Aller Benutzer und von Windows, nur ältere als eingestellt.', 'Windows-Rückstände|Update-Cache, alte Treiberpakete, Fehlerberichte, Komponentenspeicher (WinSxS).', 'Probelauf|"Analysieren" in der Übersicht zeigt vorher, wie viel frei wird.')
       Tip = 'Einmal im Monat reicht - der Zeitplan erledigt es automatisch.' }
    @{ Tab = 'TabCleaner'; Glyph = '&#xE75C;'; Color = '#0D9488'; Title = 'PC-Reiniger'; Intro = 'Neu in 10.0: gründliche Reinigung wie bei CCleaner Professional - mit Analyse vorher, Sicherung bei allem, was sich nicht neu erzeugt, und ohne Kennwörter anzufassen.'
       Items = @('Kacheln oben|Freigebbarer Platz der letzten Analyse, Registry-Funde der letzten Suche, Autostart-Einträge (Klick öffnet den Autostart auf der Seite Tuning), installierte Programme und Browser-Erweiterungen. Jede Kachel springt in den passenden Bereich.', 'Reinigung|Vier Gruppen: Windows (dieselben Bereiche wie die Seite Aufräumen, mit deren Alters-Einstellungen), Browser (Edge, Chrome, Brave, Vivaldi, Opera, Opera GX, Firefox - alle Profile aller Benutzer), Anwendungen (Office, Teams klassisch und neu, Discord, Spotify, Steam, Epic, Battle.net, Shader-Caches von NVIDIA, AMD, Intel und DirectX, Adobe, VS Code, JetBrains, Java, Zoom, WhatsApp, OneDrive-Protokolle) und Windows-Extras (zuletzt verwendete Dokumente und Sprunglisten, Explorer-Verlauf, Zwischenablage-Verlauf, DNS-Cache, Schriftarten-Cache, Speicherabbilder, alte Windows-Protokolle, Prefetch, Symbol-Cache). Angezeigt werden nur Programme, die es auf dem PC gibt.', 'Profile|Sicher (Standard): nur Caches, Temp-Dateien und Protokolle, die automatisch neu entstehen. Gründlich: dazu Shader-Caches, Speicherabbilder, Adobe- und Entwickler-Caches. Datenschutz: dazu Browserverlauf, Cookies, Sitzungen, Formulardaten und die Verlaufslisten von Windows. "Aktuelle Auswahl als Eigene speichern" merkt sich die Häkchen - diese Auswahl nutzt auch die automatische Pflege, wenn "Bei der automatischen Pflege mitreinigen" an ist.', 'Analysieren und Reinigen|"Analysieren" misst im Hintergrund jeden Posten (Größe, Anzahl Dateien, bei Verlauf und Cookies die Anzahl Einträge) und zeigt die zehn größten als Balkendiagramm - gelöscht wird dabei nichts. "Reinigen" läuft als Hintergrundaufgabe weiter, auch wenn das Fenster zu ist; jeder Posten steht im Protokoll. Läuft ein Browser oder Programm, fragt PC-Tools: schließen (Ja), diesen Bereich überspringen (Nein) oder abbrechen.', 'Cookies mit Ausnahmeliste|Cookies werden direkt in der Datenbank des Browsers gelöscht (Windows-eigenes SQLite), Domains der Ausnahmeliste samt Unterdomains bleiben erhalten - dort bleiben Sie angemeldet. Gespeicherte Kennwörter (Login Data, logins.json), Lesezeichen, Adressen- und Zahlungsdaten werden nie angefasst. Firefox-Verlauf: Besuche werden gelöscht, Lesezeichen bleiben.', 'Registry|Sucht nur verwaiste Einträge, deren Ziel auf einem festen Laufwerk sicher fehlt: gemeinsame DLLs, App Paths, Deinstallations-Einträge (Programm und Ordner weg bzw. Windows Installer kennt das Produkt nicht mehr), Dateitypen und "Öffnen mit" ohne Programm, Autostart mit fehlender Datei, Hilfedateien, Installer-Ordner, Schriftarten und Systemklänge. Vor jeder Änderung sichert reg.exe den Schlüssel als .reg (ohne Sicherung keine Änderung); "Ausgewählte Sicherung zurückspielen" macht alles rückgängig. Registry-Reinigung beschleunigt den PC nicht spürbar - sie beseitigt Fehlermeldungen und tote Einträge.', 'Programme|Alle Desktop-Programme (64/32 Bit, alle Benutzer und nur dieser Benutzer) und Store-Apps mit Herausgeber, Version, Größe und Datum; Filter für verwaiste, große und neue Programme. Deinstallieren mit dem Programm des Herstellers oder still (QuietUninstallString, MSI: msiexec /x /qn). PC-Tools wartet, bis auch nachgestartete Deinstallationsprogramme fertig sind, und bietet dann die Restesuche an: Ordner in Programme, ProgramData und AppData sowie Software\Hersteller\Produkt in der Registry - nur exakte Namenstreffer, nie ganze Ordner bekannter Hersteller. Ordner gehen in den Papierkorb, Registry-Schlüssel werden gesichert. Ändern und Reparieren (MSI: msiexec /fomus), verwaiste Einträge gesichert entfernen.', 'Browser-Erweiterungen|Alle Erweiterungen aller Chromium-Browser (Namen aus manifest.json, auch übersetzte __MSG_-Namen) und von Firefox (extensions.json) mit Status, Quelle und Berechtigungen. Orange = nicht aus dem offiziellen Store. Chromium-Erweiterungen lassen sich bei geschlossenem Browser entfernen (Ordner in den Papierkorb; mit Synchronisierung kann sie zurückkommen), Firefox über about:addons. Die Tabelle "Startseite und Suchmaschine" zeigt je Profil Suchmaschine, Startverhalten und erzwungene Richtlinien - auffällige Werte (Browser-Hijacker) sind orange.', 'Kontextmenü|Shell-Erweiterungen und Befehle von Drittherstellern für Dateien, Ordner, Ordner-Hintergrund und Laufwerke. Ausblenden ist umkehrbar: Erweiterungen kommen auf die Windows-Sperrliste (Shell Extensions\Blocked), Befehle bekommen LegacyDisable. Wirkt nach "Explorer neu starten". Der Schalter für das klassische Windows-11-Menü liegt auf der Seite Tuning.', 'Geplante Aufgaben|Alle Aufgaben außerhalb von \Microsoft\ mit Hersteller, Auslöser in Klartext (z.B. "täglich 10:30, wiederholt alle 1 Stunde"), nächster und letzter Ausführung und Aktion. Rot = das gestartete Programm fehlt. Deaktivieren, Aktivieren, Jetzt ausführen, Löschen nach Rückfrage mit XML-Sicherung (Datenordner\Aufgaben-Sicherung). Aufgaben von PC-Tools sind geschützt.', 'Laufwerk säubern|Überschreibt nur den freien Platz eines NTFS/ReFS-Laufwerks dreimal (cipher /w) - danach lassen sich früher gelöschte Dateien nicht mehr wiederherstellen; vorhandene Dateien bleiben. Läuft als Hintergrundaufgabe mit Fortschritt und lässt sich abbrechen. Auf SSDs empfiehlt PC-Tools stattdessen TRIM (Optimize-Volume -ReTrim). Ganze Laufwerke werden hier bewusst nie gelöscht.')
       Tip = 'Vor dem Verkauf eines PCs: Seite PC-Reiniger mit Profil Datenschutz reinigen, Programme samt Resten entfernen und zum Schluss bei Festplatten den freien Speicher überschreiben bzw. bei SSDs TRIM ausführen.' }
    @{ Tab = 'TabOpt'; Glyph = '&#xE945;'; Color = '#7C3AED'; Title = 'Optimieren'; Intro = 'Hält Windows schnell und stabil.'
       Items = @('Laufwerke|SSD trimmen, Festplatten defragmentieren - USB-Laufwerke auf Wunsch auslassen.', 'Systemdateien prüfen|DISM und SFC reparieren beschädigte Windows-Dateien.', 'Wiederherstellungspunkt|Wird vor jeder größeren Änderung gesetzt.') }
    @{ Tab = 'TabUpd'; Glyph = '&#xE895;'; Color = '#16A34A'; Title = 'Updates'; Intro = 'Ein Knopf für alle Updates.'
       Items = @('Windows Update|Qualitäts- und Sicherheitsupdates, optional Treiber.', 'Programme|Ninite Pro und winget aktualisieren installierte Programme still.', 'Hersteller|HP Image Assistant, Dell Command Update, Lenovo Thin Installer (Treiber und BIOS).', 'Store und Defender|Store-Apps und Virendefinitionen.')
       Tip = 'Neustarts nach Updates gibt es nur, wenn du es erlaubst - beim Zeitplan auf Wunsch automatisch mit Vorwarnung.' }
    @{ Tab = 'TabUpd'; Glyph = '&#xE895;'; Color = '#16A34A'; Title = 'Updates: Übersicht und Auswahl'; Intro = 'Neu in 7.2: sehen, was es Neues gibt, und gezielt installieren.'
       Items = @('Stand|Windows-Version, letzte Suche und Installation, Office mit Kanal und Version, Virendefinitionen, App-Installer und PC-Tools - mit Knöpfen für Office-, Defender-, Store- und PC-Tools-Updates.', 'Programm-Updates|Alle Programme mit neuer Version (auch unbekannte Versionen); sicherheitsrelevante zuerst. Markierte oder alle aktualisieren, einzelne dauerhaft ausnehmen und wieder aufnehmen, Details anzeigen.', 'Windows-Updates|Verfügbare Updates mit Art (Sicherheit, .NET, Treiber, Funktionsupdate), Größe und ob ein Neustart nötig ist - markierte installieren oder ausblenden.', 'Zuletzt aktualisiert|Was PC-Tools wann aktualisiert hat - Programme, Windows-Updates und Treiber.') }
    @{ Tab = 'TabUpdCtl'; Glyph = '&#xE777;'; Color = '#0891B2'; Title = 'Update-Steuerung'; Intro = 'Selbst bestimmen, wann welche Windows-Updates kommen.'
       Items = @('Pausieren|1, 2 oder 5 Wochen - z.B. vor wichtigen Terminen oder wenn ein neues Update Probleme macht.', 'Version festhalten|Windows bleibt auf der gewählten Version (z.B. 24H2) und bekommt trotzdem Sicherheitsupdates.', 'Zurückstellen|Funktionsupdates bis 365 Tage, Sicherheitsupdates bis 30 Tage später.', 'Weitere Regeln|Keine Treiber über Windows Update, kein automatischer Neustart solange jemand angemeldet ist, Nutzungszeit, Store-Apps automatisch ja/nein, neue Funktionen sofort.', 'Einzelne Updates|Verfügbare Updates anzeigen, problematische ausblenden und wieder einblenden.', 'Verlauf|Alle installierten Updates mit Ergebnis und Fehlercode; fehlerhafte Updates deinstallieren, Windows Update reparieren.')
       Tip = 'Macht ein Update Ärger: im Verlauf deinstallieren und oben ausblenden - dann kommt es nicht sofort wieder.' }
    @{ Tab = 'TabSpace'; Glyph = '&#xEDA2;'; Color = '#0891B2'; Title = 'Speicherplatz'; Intro = 'Zeigt in Sekunden, was die Festplatte füllt.'
       Items = @('Kachelkarte|Je größer die Fläche, desto mehr Platz belegt der Ordner. Klick öffnet den Ordner, Rechtsklick zeigt ihn im Explorer, "Eine Ebene höher" geht zurück.', 'Größte Dateien|Die 200 größten Dateien, alte Downloads, Videos und Installationsdateien - löschen geht immer nur in den Papierkorb.', 'Doppelte Dateien|Findet identische Dateien (erst Größe, dann Prüfsumme). Das älteste Exemplar bleibt als Original (grün) stehen, "Kopien auswählen" markiert nur die Duplikate.')
       Tip = 'Große, lange nicht benutzte Dateien lieber auf die Sicherungsplatte oder das NAS verschieben als löschen.' }
    @{ Tab = 'TabDrv'; Glyph = '&#xE964;'; Color = '#7C3AED'; Title = 'Treiber'; Intro = 'Alle Treiber sehen, prüfen und aktualisieren.'
       Items = @('Alle Treiber jetzt aktualisieren|Sichert vorher alle Treiber, setzt einen Wiederherstellungspunkt und holt dann Grafik (NVIDIA/Intel direkt), Intel WLAN/Bluetooth, Windows-Update-Treiber und Hersteller-Treiber.', 'Treiberliste|Jeder Treiber mit Hersteller, Version, Datum und Zustand. Filter für Probleme, alte Treiber, Intel, Grafik usw. "Treiber im Web suchen" hilft bei unbekannten Geräten.', 'Intel-Geräte|Grafik, WLAN und Bluetooth kommen direkt aus dem Intel-Download-Center (Prüfsumme und Signatur geprüft) - das sind dieselben Updates, die der Intel-Assistent anzeigt.', 'Treiber sichern und zurückspielen|"Alle Treiber sichern" exportiert alle Pakete, "Treiber aus Ordner installieren" spielt sie wieder ein - auch nach einer Neuinstallation.')
       Tip = 'Macht ein neuer Treiber Ärger: Fehler beheben > Wiederherstellungspunkte, oder den gesicherten Treiber aus dem Ordner installieren.' }
    @{ Tab = 'TabDrv'; Glyph = '&#xE964;'; Color = '#7C3AED'; Title = 'Treiber: Update-Center und Werkzeuge'; Intro = 'Neu in 7.2: alle Treiber-Updates in einer Liste und Werkzeuge für jedes Gerät.'
       Items = @('Kennzahlen|Anzahl Treiber, Geräte mit Problem, alte Hersteller-Treiber, verfügbare Updates und letzte Sicherung auf einen Blick.', 'Update-Center|Ein Klick sucht bei NVIDIA, Intel (Grafik, WLAN, Bluetooth) und Windows Update (auch optionale Treiber) und zeigt installierte und neue Version. Markieren, installieren - auf Wunsch mit Treibersicherung vorher.', 'Ausgewählter Treiber|Alle Details samt Fehlercode-Erklärung; Gerät neu starten, deaktivieren/aktivieren, deinstallieren und neu erkennen, Treiberpaket löschen, im Microsoft-Update-Katalog suchen.', 'Treiberspeicher|Alle zusätzlichen Treiberpakete mit Größe; ältere Versionen werden erkannt und lassen sich gefahrlos entfernen.', 'Verlauf|Welche Treiber Windows in den letzten 90 Tagen installiert hat - mit Ergebnis.', 'Sicherungen|Alle Treibersicherungen mit Größe; zurückspielen, auf Stick/NAS kopieren, löschen.')
       Tip = 'Nach einem Treiber-Update spinnt ein Gerät? "Gerät neu starten" oder den Treiber über die Sicherung zurückspielen.' }
    @{ Tab = 'TabDrv'; Glyph = '&#xE964;'; Color = '#0F766E'; Title = 'Treiber: Sicherung vor Updates und Zurückspielen'; Intro = 'Neu in 10.0: vor jedem Treiber-, BIOS- oder Firmware-Update sichert PC-Tools automatisch den bisherigen Stand - ein misslungenes Update lässt sich so gezielt je Gerät rückgängig machen.'
       Items = @('Wann?|Direkt vor der Installation bei Windows Update (nur wenn Treiber dabei sind), Treibern aus Windows Update, NVIDIA- und Intel-Grafik, Intel WLAN/Bluetooth, HP Image Assistant, Lenovo Thin Installer, Dell Command | Update (jeweils inklusive BIOS/Firmware, wenn eingestellt), Hersteller-Treiberpaketen und dem Surface-Paket - in der automatischen Pflege, der Ein-Klick-Optimierung und auf den Seiten Treiber/Updates. Pro Lauf nur einmal.', 'Was wird gesichert?|Alle zusätzlichen Treiberpakete (pnputil /export-driver, wie "Treiber sichern") nach Treiber-Sicherung\<Datum>_<Anlass> im Datenordner, dazu Sicherung.json mit jedem Gerät (Name, Geräte-ID, Klasse, Anbieter, Version, Datum, Paket) und der BIOS-Version. Ist seit der letzten Sicherung nichts geändert, wird sie wiederverwendet - das spart Minuten und Gigabytes. Reicht der Platz nicht, wird nur die Liste gesichert. Außerdem wird ein Wiederherstellungspunkt gesetzt (oder ein frischer genutzt).', 'Vergleich|Nach dem Lauf steht im Protokoll, welche Treiber sich geändert haben (vorher -> nachher). Die Karte "Treiber-Sicherungen vor Updates" vergleicht jede Sicherung live mit dem jetzigen Stand - auch nach dem Neustart, wenn BIOS und Firmware erst dann aktiv werden.', 'Gerät zurückspielen|Gerät wählen, "Diesen Stand zurückspielen": das gesicherte Paket wird mit pnputil installiert. Hält Windows am neueren Treiber fest (bessere Einstufung), bietet PC-Tools an, das neuere Paket zu entfernen (pnputil /delete-driver /uninstall, mit Warnung, wie viele Geräte es nutzen) - oder öffnet die Geräte-Eigenschaften mit "Vorheriger Treiber". Speicher- und Systemtreiber werden extra gewarnt.', 'Ganzer Satz|"Ganzen Satz zurückspielen" installiert alle Pakete der Sicherung - gut nach einer Neuinstallation. Neuere Treiber bleiben dabei aktiv.', 'BIOS und Firmware|Werden nie automatisch zurückgespielt - ein falscher oder abgebrochener Flash kann den PC unbrauchbar machen. "BIOS: Rückweg" zeigt gesicherte und jetzige Version und den Weg des Herstellers (HP Rollback-Richtlinie und Sure Start, Lenovo Secure Rollback Prevention, Dell BIOS Downgrade, Surface ohne Rückweg) samt Support-Seite.', 'Aufbewahrung|Die letzten 5 automatischen Sicherungen bleiben (einstellbar); von Hand angelegte werden nie automatisch gelöscht. Ausschalten ist möglich, aber nicht empfohlen.')
       Tip = 'Spinnt nach einem Update das WLAN, der Ton oder die Grafik: hier die Sicherung wählen, das Gerät anklicken und den alten Stand zurückspielen - meist ohne Neustart.' }
    @{ Tab = 'TabSched'; Glyph = '&#xE787;'; Color = '#0F766E'; Title = 'Zeitplan'; Intro = 'Die automatische Pflege.'
       Items = @('Wann|Täglich oder wöchentlich zur gewünschten Uhrzeit, als geplante Aufgabe (läuft auch ohne Anmeldung).', 'Verpasst?|War der PC aus, wird der Lauf beim nächsten Start nachgeholt.', 'Was|Updates, Aufräumen und Optimieren - jeweils nach den Einstellungen der Seiten.') }
    @{ Tab = 'TabSecurity'; Glyph = '&#xE72E;'; Color = '#0F766E'; Title = 'Sicherheit'; Intro = 'Alle Schutzfunktionen prüfen und einstellen.'
       Items = @('Sicherheitswert|0-100 aus rund 20 Prüfungen (Virenschutz, Firewall, BitLocker, Secure Boot, TPM, Updates ...). Die Tabelle nennt zu jedem Punkt die Empfehlung.', 'Defender|Echtzeit-, Cloud-, PUA-, Netzwerk- und Ransomware-Schutz einzeln schalten; Schnell-, Voll- und Offline-Prüfung, Zweitmeinung mit dem Microsoft Safety Scanner, Bedrohungsverlauf.', 'Firewall|Pro Netzwerktyp an/aus, im öffentlichen WLAN alles Eingehende blockieren.', 'BitLocker mit einem Klick|"C: mit einem Klick verschlüsseln" schaltet BitLocker für das Windows-Laufwerk ein (XTS-AES 256, Entsperrung über den TPM-Chip - beim Start musst du nichts eingeben). Der Wiederherstellungsschlüssel wird automatisch im Ordner "BitLocker-Schluessel" im PC-Tools-Datenordner gespeichert, zusammen mit der Datei "WICHTIG - unbedingt sichern.txt". PC-Tools öffnet den Ordner danach gleich. Mit "Schlüssel-Ordner öffnen" kommst du jederzeit dorthin, mit "Schlüssel auf USB-Stick sichern ..." kopierst du ihn woandershin. Weitere Laufwerke über "Anderes Laufwerk verschlüsseln ...". Für ein BIOS-Update "Für 1 Neustart aussetzen".', 'Schutzfunktionen|Benutzerkontensteuerung, SmartScreen, Speicherintegrität, LSA-Schutz, SMBv1, Remotedesktop usw. - "Empfohlene Werte setzen" stellt alles sinnvoll ein.', 'Virenschutz installieren|Kostenlose (Defender, Bitdefender, Panda Dome, Avast, AVG, Avira, Sophos, Malwarebytes) und kostenpflichtige Programme.')
       Tip = 'Den BitLocker-Wiederherstellungsschlüssel IMMER außerhalb des PCs aufbewahren - ohne ihn sind die Daten nach einem Hardwaretausch verloren.' }
    @{ Tab = 'TabVuln'; Glyph = '&#xE7BA;'; Color = '#DC2626'; Title = 'Sicherheitslücken'; Intro = 'Unsichere und veraltete Programme finden und mit einem Klick beheben.'
       Items = @('Kritisch (rot)|Programme mit bekannter, ausgenutzter Lücke unter der sicheren Mindestversion - z.B. 7-Zip, WinRAR, Notepad++, PuTTY, KeePass, VLC.', 'Veraltet (orange)|Versionen ohne Sicherheitsupdates: alte Java-, Python-, .NET- und Office-Versionen, Flash, Silverlight, QuickTime.', 'Sicherheitsupdate (orange)|Browser, PDF, Fernwartung, Messenger & Co. mit neuer Version - diese Updates schließen fast immer Lücken.', 'Beheben|"Alle kritischen und Sicherheitsupdates installieren" per winget; nicht mehr gepflegte Programme deinstallieren.')
       Tip = 'Einmal im Monat prüfen - oder einfach die automatische Pflege laufen lassen, die aktualisiert Programme ebenfalls.' }
    @{ Tab = 'TabNetSec'; Glyph = '&#xE785;'; Color = '#B91C1C'; Title = 'Netzwerk-Sicherheit'; Intro = 'Schwachstellen im eigenen Netz finden und schließen.'
       Items = @('Dieser PC|Firewall, Netzwerkprofil (Privat/Öffentlich), SMBv1, SMB-Signierung, LLMNR und NetBIOS (Kennwort-Abgriff im Netz), WPAD, Remotedesktop ohne NLA, Remote-Registrierung, Gastkonto, Freigaben für "Jeden", offene Anschlüsse, Defender-Netzwerkschutz.', 'Geräte im Netz|Alle Geräte werden gefunden und auf riskante Dienste geprüft: Telnet, FTP, VNC, offene Datenbanken, unverschlüsseltes MQTT, Weboberflächen ohne HTTPS, Kameras (RTSP) - mit Erklärung und Link zur Geräteoberfläche.', 'Router|UPnP-Portfreigaben (was aus dem Internet erreichbar ist), Fernwartung TR-069, Router-Oberfläche ohne HTTPS, Firmware-Hinweis.', 'WLAN|Verschlüsselung des verbundenen Netzes (offen/WEP/WPA2/WPA3) und offene WLANs, mit denen sich der PC automatisch verbindet.', 'Beheben|Alles, was am PC einstellbar ist, mit einem Klick; Router- und Gerätebefunde mit Anleitung. Bericht als PDF.')
       Tip = 'Es wird nur das eigene Netz geprüft und nichts angegriffen. Anschluss-Scans nur im eigenen Netz bzw. mit Erlaubnis des Netzbetreibers durchführen.' }
    @{ Tab = 'TabPrivacy'; Glyph = '&#xE72E;'; Color = '#0F766E'; Title = 'Datenschutz'; Intro = 'Was Windows über dich sammelt und welche App was darf.'
       Items = @('Schalter|Telemetrie auf das Minimum, Werbe-ID, personalisierte Werbung, Aktivitätsverlauf, Tipps und Vorschläge, Bing in der Suche, Copilot, Recall und mehr - jeweils einzeln, "Alles datensparsam einstellen" setzt alles auf einmal.', 'App-Berechtigungen|Welche App darf Kamera, Mikrofon, Standort, Kontakte, Kalender ...? Filter nach Berechtigung, einzelne Apps erlauben oder sperren, oder eine Berechtigung für alle Apps abschalten.')
       Tip = 'Mikrofon und Kamera für alle Apps sperren und nur für Teams/Zoom erlauben - so hört keine App heimlich mit.' }
    @{ Tab = 'TabRepair'; Glyph = '&#xE90F;'; Color = '#EA580C'; Title = 'Fehler beheben'; Intro = 'Erst suchen, dann gezielt reparieren.'
       Items = @('Fehlersuche|Prüft Neustart, Speicher, Datenträger, Windows-Abbild, Updates, Abstürze, Dienste, Geräte, Netzwerk, Virenschutz und mehr - ändert nichts.', 'Empfohlene Reparaturen|Ein Klick hakt genau die passenden Reparaturen an.', 'Über 40 Reparaturen|DISM/SFC, chkdsk, Windows Update zurücksetzen, Netzwerk, Store und Startmenü, Symbol-/Schriftarten-Cache, Suche, Drucker, WMI, WinRE, Startdateien.', 'Wiederherstellungspunkte|Anzeigen, erstellen und zurückspielen.', 'Wenn nichts hilft|Windows über Windows Update neu aufspielen oder Reparaturinstallation mit ISO - Programme und Dateien bleiben.')
       Tip = 'Die Standard-Reparatur (Schnellwahl) behebt die meisten "Windows spinnt"-Probleme.' }
    @{ Tab = 'TabWinRepair'; Glyph = '&#xEC7A;'; Color = '#B91C1C'; Title = 'Windows-Reparatur: Überblick und Reparatur-Assistent'; Intro = 'Neu in 9.1: Alle Reparaturen, die Windows selbst anbietet, auf einer Seite - von der harmlosen Prüfung bis zur Reparaturinstallation. Die Seite "Fehler beheben" sucht Fehler und schlägt schnelle Reparaturen vor; die Windows-Reparatur geht tiefer und erklärt jeden Schritt.'
       Items = @('Zustand|Acht Kacheln oben zeigen beim Öffnen: Windows-Version mit Build, Sprache und Installationsdatum, ob ein Neustart aussteht, den Zustand des Komponentenspeichers (DISM-Schnellprüfung), das Ergebnis des letzten SFC-Laufs aus der CBS.log, ob die Wiederherstellungsumgebung (WinRE) aktiv ist, den freien Platz auf C:, den letzten Wiederherstellungspunkt und den Startmodus (UEFI, Secure Boot, abgesicherter Start, Startprotokoll, Hypervisor). Grün = gut, orange = Hinweis, rot = Problem.', 'Reparatur-Assistent|Profile wie "Schnell & sicher", "Systemdateien gründlich", "Windows Update reparieren", "Netzwerk komplett zurücksetzen (Surface/DHCP)" oder "Alles außer Neuinstallation" haken die passenden Reparaturen in der richtigen Reihenfolge an. Die Auswahl lässt sich in den Kacheln ergänzen oder verkleinern, dann "Auswahl jetzt reparieren".', 'Kacheln|Jede Reparatur hat eine Kachel mit Erklärung, geschätzter Dauer und einem Kennzeichen: "sicher" (ändert nichts Riskantes), "Neustart nötig" oder "tiefgreifend" (z.B. Firewall auf Standard, Netzwerk komplett neu installieren). "Profi-Details" und der Tooltip zeigen den genauen Befehl. "Ausführen" startet nur diese eine Reparatur.', 'Reparaturquelle|DISM holt Ersatzteile normalerweise aus Windows Update. Mit einer Windows-ISO (oder install.wim/esd) geht es offline und auch dann, wenn Windows Update selbst kaputt ist. PC-Tools liest die Abbilder der ISO und wählt automatisch den Index der installierten Edition. Version, Edition und Sprache müssen passen, sonst meldet DISM 0x800f081f.', 'Sicherheit|Vor jedem Lauf kann ein Wiederherstellungspunkt entstehen (Haken im Assistenten). Tiefgreifende Schritte fragen doppelt nach. Alles, was geändert wird, sichert PC-Tools vorher: Dienst-Werte als .reg, Startkonfiguration (bcdedit /export), Firewall-Regeln (.wfw), Gruppenrichtlinien, hosts-Datei, alte SoftwareDistribution/catroot2.', 'Lauf und Verlauf|Läufe arbeiten als Hintergrundaufgabe und laufen weiter, wenn das Fenster zugeht. Die Karte "Reparatur-Lauf" zeigt Fortschritt, aktuellen Schritt und das Live-Protokoll; "Abbrechen" stoppt nach dem aktuellen Schritt. Unter "Ergebnisse und Verlauf" steht jeder Schritt mit Ergebnis; alles liegt im Datenordner unter WinRepair (last.json, history.csv, Berichte, Sicherungen).', 'Textmodus|Startet die Oberfläche nicht mehr: "Windows-Reparatur.cmd" auf dem portablen Stick bzw. PCPflege.ps1 -WinRepair bietet dieselben Profile und den ganzen Katalog im Textfenster - inklusive Dienste-Vergleich, Netzwerkfilter, SFC-Auswertung, Neustart in WinRE und abgesichertem Modus.')
       Tip = 'Reihenfolge der Profis: erst "Nur prüfen" oder "Schnell & sicher", dann "Systemdateien gründlich", erst danach die tiefgreifenden Schritte - und als allerletztes die Reparaturinstallation.' }
    @{ Tab = 'TabWinRepair'; Glyph = '&#xE8F1;'; Color = '#2563EB'; Title = 'Windows-Reparatur: Systemdateien, Updates, Start und Apps'; Intro = 'Was die einzelnen Bereiche machen und wann welche Reparatur hilft.'
       Items = @('DISM und SFC|Windows hat ein eigenes Ersatzteillager (Komponentenspeicher, WinSxS). DISM /CheckHealth und /ScanHealth prüfen es, /RestoreHealth repariert es. Erst danach kann sfc /scannow beschädigte Systemdateien daraus ersetzen - deshalb immer erst DISM, dann SFC. "SFC-Ergebnis auswerten" liest die CBS.log (deutsches und englisches Windows) und listet jede reparierte und jede NICHT reparierbare Datei.', 'Komponentenspeicher aufräumen|/AnalyzeComponentStore zeigt die echte Größe von WinSxS, /StartComponentCleanup entfernt alte Update-Reste. /ResetBase spart am meisten, danach lassen sich installierte Updates aber nicht mehr deinstallieren.', 'Windows Update|"Komplett zurücksetzen" stoppt die Dienste, legt SoftwareDistribution und catroot2 neu an (die alten bleiben als Sicherung), leert die BITS-Warteschlange und setzt verbogene Dienst-Berechtigungen von BITS und wuauserv auf den Standard. Die veraltete DLL-Neuregistrierung aus alten Anleitungen entfällt. Hängt Windows nach einem Update in einer Schleife: "Hängende Update-Aktionen zurücknehmen" (aus WinRE).', 'Start und Wiederherstellung|Startkonfiguration sichern, Startdateien mit bcdboot neu schreiben (EFI-Partition wird dafür kurz eingebunden, BitLocker für einen Neustart angehalten), WinRE einschalten - fehlt die Datei Winre.wim, holt PC-Tools sie aus der ISO. Dazu: sofort in WinRE oder die erweiterten Startoptionen starten, abgesicherter Modus für den nächsten Start (schaltet sich nach der Anmeldung selbst wieder aus), Startprotokoll (ntbtlog.txt), chkdsk online oder beim Neustart.', 'Apps und Oberfläche|Apps neu registrieren (für den Benutzer oder alle Pakete), Store zurücksetzen, Startmenü/Taskleiste/Suche reparieren, Suchindex neu aufbauen, Symbol-, Miniaturansichten- und Schriftarten-Cache, Explorer neu starten, winget-Quellen.', 'Systemkomponenten|WMI (repariert nur bei Fehlern), Leistungsindikatoren, .NET Framework 3.5 (auch offline aus der ISO), Visual-C++-Laufzeiten per winget, lokale Gruppenrichtlinien, Druckwarteschlange, Zeitdienst, Windows-Sicherheit, hosts-Datei, Starttypen von rund 30 Kerndiensten (erst Vergleich, dann Rückfrage) und eine Fehlerübersicht der letzten 7 Tage.', 'Letzter Ausweg|Die Reparaturinstallation installiert Windows aus einer ISO über sich selbst - Programme, Dateien und Einstellungen bleiben. PC-Tools prüft vorher Edition, Sprache, Architektur und Build (Insider-Builds brauchen eine Insider-ISO), startet Setup im Hintergrund, zeigt den Fortschritt und übersetzt Fehlercodes wie 0xC1900101. Alternativen: Systemwiederherstellung, "Mit Windows Update neu aufspielen" und - ganz zuletzt - "Diesen PC zurücksetzen".')
       Tip = 'Meldet SFC "einige Dateien konnten nicht repariert werden": DISM /RestoreHealth mit einer passenden ISO als Reparaturquelle, danach SFC noch einmal. Bleiben Fehler, ist die Reparaturinstallation der sichere Weg.' }
    @{ Tab = 'TabWinRepair'; Glyph = '&#xE968;'; Color = '#DC2626'; Title = 'Windows-Reparatur: keine IPv4-Adresse per DHCP (Netzwerk-Tiefenreparatur)'; Intro = 'Für den hartnäckigsten Netzwerkfall: Der PC schickt DHCP-Anfragen, bekommt aber nie eine Antwort - IPv6 funktioniert, IPv4 bleibt leer oder bei 169.254. Andere Geräte am selben Router haben kein Problem.'
       Items = @('Erst prüfen|"Netzwerk tief prüfen" zeigt alle Filter und Protokolle an den echten Adaptern mit Hersteller und Treiberpaket (Get-NetAdapterBinding -AllBindings, pnputil /enum-drivers /class NetService), die IPv4-Einstellungen in der Registrierung (DHCP an/aus, alte feste Adressen), IPv6 DisabledComponents, den DHCP-Broadcast-Wechsel und die Abweichungen von rund 50 Netzwerk- und Kerndiensten von der Windows-11-Vorgabe.', 'Virenschutz-Filter|Häufigste Ursache: Ein NDIS-Filtertreiber eines Virenschutzes (z.B. Panda NNSNAHSL) verwirft die DHCP-Antwort des Routers. "Ausgewählten lösen" schaltet die Bindung testweise aus (rückgängig mit "Wieder einschalten"). Hilft das, den Virenschutz mit dem Programm des Herstellers deinstallieren (bei Panda notfalls "Panda Generic Uninstaller"); bleibt der Filter übrig, "Treiberpaket entfernen" (netcfg -u, pnputil /delete-driver).', 'Dienste und Treiber|Starttyp, Programmpfad und Abhängigkeiten von DHCP-Client, DNS-Client, NSI, TCP/IP, AFD, NetBT, NDIS, WFP, Firewall, WLAN-AutoKonfig, Verbindungs-Manager und WinHTTP-Autoproxy werden mit Windows 11 verglichen. Ab Windows 11 24H2 hängt der Verbindungs-Manager vom WinHTTP-Autoproxy-Dienst ab - wer diesen "zum Tunen" deaktiviert hat, bekommt keine IPv4-Adresse mehr. Nur abweichende Werte werden nach Rückfrage zurückgesetzt, vorher als .reg gesichert.', 'IPv4 und IPv6|"IPv4 der Adapter auf automatisch" schaltet IPv4 und DHCP ein und entfernt alte feste Adressen. DisabledComponents sollte 0 sein; die einzige empfohlene Abweichung ist 0x20 (IPv4 bevorzugen). IPv6 ganz abzuschalten hilft bei DHCP-Problemen nicht.', 'Profil Netzwerk komplett zurücksetzen|Sichert erst den Ist-Zustand als Beweis (ipconfig, Bindungen, Winsock-Katalog, WFP-Zustand, DHCP-Ereignisse) und schaltet das DHCP-Detailprotokoll ein, dann: Dienst-Vorgaben, IPv4/DHCP, IPv6-Komponenten, Broadcast-Wechsel, fremde Filter lösen, Geister-Adapter entfernen, Proxy, Caches, netsh int ip reset (mit Protokolldatei), int ipv6 reset, winsock reset, Filterplattform. Vorher Wiederherstellungspunkt, am Ende Neustart. Firewall und netcfg -d bleiben bewusst außen vor.', 'Wenn es danach noch klemmt|"Netzwerk komplett neu installieren" (netcfg -d, wie Einstellungen > Netzwerkzurücksetzung) und "Windows-Firewall auf Standard" sind die nächsten Stufen. Hyper-V-Reste (verwaiste Switch-Bindung, WinNAT, ICS) prüft und repariert die Seite Netzwerk-Diagnose; dort gibt es auch den DHCP-Live-Test.')
       Tip = 'Nach dem Neustart zeigt die Ereignisanzeige unter Microsoft-Windows-Dhcp-Client/Operational jede Anfrage und Antwort - kommt dort nie ein Offer an, obwohl die Filter gelöst sind, liegt das Problem im WLAN-/LAN-Treiber oder beim Access Point.' }
    @{ Tab = 'TabChanges'; Glyph = '&#xE81C;'; Color = '#7C3AED'; Title = 'Änderungen (Vorher/Nachher)'; Intro = 'Was hat sich am PC geändert - und wie drehe ich es zurück?'
       Items = @('Stände|Vor jedem Update-, Treiber- oder Installationslauf hält PC-Tools automatisch fest, welche Programme, Treiber, Dienste, Autostarts und Windows-Updates vorhanden sind. Auf Knopfdruck geht das auch von Hand.', 'Vergleich|Zwei Stände auswählen: neu, entfernt und geändert (mit alter und neuer Version) - filterbar nach Art.', 'Zurückdrehen|Für ein neues Programm startet die Deinstallation, für einen Treiber der Geräte-Manager, sonst geht es zu den Wiederherstellungspunkten.')
       Tip = 'Seit einem Update spinnt etwas? Den Stand von vorher mit jetzt vergleichen - meist steht der Schuldige ganz oben.' }
    @{ Tab = 'TabHealth'; Glyph = '&#xE9D2;'; Color = '#16A34A'; Title = 'Gerätezustand und Startzeit'; Intro = 'Wie geht es Akku, SSD und Windows auf lange Sicht?'
       Items = @('Verlauf|Einmal täglich werden Akku-Kapazität, Ladezyklen, SSD-Verschleiß und -Temperatur, Lesefehler, freier Platz und Startzeit gespeichert und als Kurven gezeigt.', 'Prognose|Aus dem Verlauf schätzt PC-Tools, wann der Akku unter 70 % fällt.', 'Startzeit|Die letzten Starts als Balken (grün unter 45 s), Aufteilung bis zum Desktop und danach.', 'Bremsen|Programme, Dienste und Treiber, die Windows als Startbremse meldet - Dienste lassen sich direkt verzögert starten.')
       Tip = 'Werte ändern sich langsam - nach ein paar Wochen sieht man echte Trends.' }
    @{ Tab = 'TabDiag'; Glyph = '&#xEBE8;'; Color = '#DC2626'; Title = 'Fehlerdaten'; Intro = 'Bluescreens, Abstürze und Protokolle einsammeln.'
       Items = @('Problemliste|Alle Bluescreens, Abstürze und Hardwarefehler mit Ursache.', 'ZIP-Paket|Alles für den Support in einer Datei.') }
    @{ Tab = 'TabBackup'; Glyph = '&#xE8F7;'; Color = '#DB2777'; Title = 'Datensicherung'; Intro = 'Eigene Dateien und den ganzen PC sichern.'
       Items = @('Was und wohin|Benutzerordner und eigene Ordner auf externe Festplatte oder NAS.', 'Modus|Spiegeln, Ergänzen oder mit Versionen; Ausnahmen für Dateitypen und Ordner.', 'Systemabbild|Der komplette PC als Abbild - Wiederherstellung über die erweiterten Startoptionen.', 'Zeitplan|Automatisch, auch nachgeholt; ist die Festplatte nicht da, wird still übersprungen.')
       Tip = '3-2-1-Regel: 3 Kopien, 2 verschiedene Datenträger, 1 außer Haus.' }
    @{ Tab = 'TabFullBackup'; Glyph = '&#xE78C;'; Color = '#4338CA'; Title = 'Komplettsicherung'; Intro = 'Ein Abbild des ganzen PCs - damit ist nach einem Festplattenschaden, Schadsoftware oder einem kaputten Windows in einer Stunde alles wieder wie vorher.'
       Items = @('Was ist der Unterschied zur Datensicherung?|Die Datensicherung kopiert ausgewählte Ordner (Dateien einzeln zurückholen). Die Komplettsicherung ist ein Abbild aller Laufwerke, die Windows zum Starten braucht (EFI, C:, Wiederherstellungspartition) - mit Windows, Programmen, Einstellungen und allen Dateien. Ideal: beides.', 'Ziel|Eine externe NTFS-Festplatte (nicht die Windows-Festplatte!) oder eine NAS-Freigabe. FAT32/exFAT geht nicht. Auf Festplatten speichert Windows weitere Sicherungen nur als Änderungen; auf einem NAS hebt Windows nur EINE Version auf - PC-Tools legt deshalb auf Wunsch je Sicherung einen Datumsordner an.', 'Prüfung|Nach jeder Sicherung: kennt die Windows-Sicherung die Version, sind Ordner und VHDX-Dateien da, passt die Größe? Gründlich: das Abbild wird schreibgeschützt eingebunden und Windows darin gesucht.', 'Versionen|"Versionen behalten" entfernt ältere Stände nach einer erfolgreichen Sicherung - nie die neueste.', 'Zeitplan|Eigene Aufgabe "PC-Tools Komplettsicherung" (als SYSTEM): wöchentlich, alle 2 Wochen oder monatlich, mit Wecken, nur am Netzteil, Nachholen und Wiederholen bei Fehlern. Erfolg und Fehler kommen aufs Handy; die Übersicht meldet, wenn die letzte erfolgreiche Sicherung zu alt ist.', 'Wiederherstellungsmedium|Das Wiederherstellungspaket am Ziel enthält Reparatursystem, Startdateien, Reparatur-Menü, PC-Tools portabel und eine Anleitung - "Stick-erstellen.cmd" macht daraus auf jedem PC einen Start-Stick. Ein eingesteckter Notfall-Stick kann nach der geplanten Sicherung automatisch aufgefrischt werden (nie formatiert).', 'Wiederherstellen|"Neustart in die Wiederherstellung" oder vom Stick starten, dann Problembehandlung > Erweiterte Optionen > Systemimage-Wiederherstellung (oder Reparatur-Menü Punkt S). Einzelne Dateien: Version markieren, "Einzelne Dateien aus dem Abbild holen".')
       Tip = 'Einmal im Jahr testen: eine Datei aus dem Abbild holen und mit dem Notfall-Stick bis zur Systemimage-Wiederherstellung durchklicken (dort abbrechen). Dann klappt es auch im Ernstfall.' }
    @{ Tab = 'TabMigrate'; Glyph = '&#xE8AB;'; Color = '#DB2777'; Title = 'PC-Umzug'; Intro = 'Vom alten auf den neuen PC.'
       Items = @('Umzugspaket|Daten, Einstellungen (WLAN, Drucker, Netzlaufwerke, Signaturen, Schriften ...), alle Browser komplett und die Programmliste.', 'Browser-Kennwörter|Über die Export-Funktion der Browser als CSV - lokal, ohne Cloud. Auf dem neuen PC "In ... importieren", danach die CSV löschen.', 'Neuer PC|Paket einlesen - Programme werden automatisch installiert, dann Daten und Einstellungen übernommen.') }
    @{ Tab = 'TabWinSet'; Glyph = '&#xE8C8;'; Color = '#DB2777'; Title = 'Einstellungen übertragen'; Intro = 'Windows auf dem neuen PC so einrichten wie auf dem alten.'
       Items = @('Bereiche|Explorer, Taskleiste mit angehefteten Programmen, Startmenü, Design und Hintergrund, Maus/Tastatur/Sprachen, Region und Zeitzone, Energieplan, WLAN-Profile, Drucker, Netzlaufwerke, Schriftarten, Outlook-Signaturen, Standard-Apps, Umgebungsvariablen, Hosts-Datei.', 'Ablauf|Alter PC: "Jetzt sichern" in einen Ordner (Stick/NAS). Neuer PC: Ordner wählen, "Jetzt übernehmen" - oder im Einrichtungs-Assistenten Schritt 8.', 'Standard-Apps|Windows erlaubt das Setzen nur von Hand - PC-Tools zeigt die Liste und öffnet die passende Einstellung.')
       Tip = 'Der Sicherungsordner enthält WLAN-Kennwörter im Klartext - danach löschen.' }
    @{ Tab = 'TabWizard'; Glyph = '&#xE768;'; Color = '#2563EB'; Title = 'Einrichtungs-Assistent'; Intro = 'Einen neuen PC in einem Durchgang komplett einrichten.'
       Items = @('10 Schritte|Gerät und Region, Energie und Deckel, Datenschutz/Explorer/Taskleiste, Apps entfernen, Programme (Profile), Treiber und Updates, Benutzer/Netzlaufwerke/Drucker, Einstellungen vom alten PC, Unternehmen, Sicherheit und Abschluss - jeder Schritt einzeln an- und abwählbar.', 'Unternehmen|Firma/Besitzer, Namensschema ({SERIAL}, {NR}, {TYP}), Inventarnummer und zentrale Inventarliste (CSV auf dem NAS), Support-Angaben, Active-Directory-Beitritt mit OU, OneDrive-Ordnersicherung für Microsoft 365, Entra-ID-Verbindung, Bildschirmsperre, Kennwortrichtlinie, USB-Speicher sperren oder nur lesen, Defender-Angriffsflächen-Regeln, Administratorkonto aus, Anmeldehinweis, Firmenbild für Sperrbildschirm und Desktop, Firmen-WLAN, VPN (IKEv2/SSTP/L2TP), Proxy, Zeitserver und Firmen-Zertifikate.', 'Update-Runden|Nach Neustarts geht es nach der Anmeldung automatisch weiter, bis alle Updates drin sind (bis zu 5 Runden).', 'Vorlagen|Einstellungen als Vorlage speichern und auf weiteren PCs laden - oder direkt auf den USB-Stick für die automatische Installation.', 'Abschluss|BitLocker mit gesichertem Schlüssel, Sorgenfrei-Modus und Einrichtungsprotokoll als PDF.')
       Tip = 'Kennwörter aus Schritt 7 werden verschlüsselt an den PC gebunden gespeichert.' }
    @{ Tab = 'TabSetup'; Glyph = '&#xE7F8;'; Color = '#EA580C'; Title = 'Neues Gerät'; Intro = 'Einen frischen PC in Minuten einrichten.'
       Items = @('Profile|Büro, Heim, Gaming, Entwicklung, KI, 3D-Druck, IT-Admin ... - kombinierbar, einzelne Programme an- oder abwählen.', 'Installation|Still über Ninite Pro, winget oder direkt beim Hersteller (mit Signaturprüfung).') }
    @{ Tab = 'TabSetup'; Glyph = '&#xE77B;'; Color = '#0F766E'; Title = 'Eigene Programm-Profile'; Intro = 'Deine eigene Programmauswahl als Profil speichern und überall verwenden.'
       Items = @('Speichern|Profile wählen, Programme anhaken, "Auswahl als eigenes Profil speichern" - es erscheint als eigene Karte.', 'Aus diesem PC|"Profil aus diesem PC erzeugen" übernimmt alle Programme, die sich per winget installieren lassen.', 'Teilen|Profile exportieren und auf anderen PCs importieren; im Einrichtungs-Assistenten auswählbar.') }
    @{ Tab = 'TabCheck'; Glyph = '&#xE73E;'; Color = '#16A34A'; Title = 'Neugerät-Check'; Intro = 'Neue Geräte prüfen, solange Rückgabe und Umtausch einfach sind.'
       Items = @('Von Hand|Bildschirm (Farbflächen gegen Pixelfehler), Tastatur (jede Taste wird grün), Kamera, Mikrofon (Aufnahme mit Pegel), Lautsprecher (links/rechts), USB-Anschlüsse (Stick nacheinander einstecken), Arbeitsspeicher (Windows-Speicherdiagnose).', 'Automatisch|WLAN und Bluetooth, Akku gegenüber Neuzustand, SSD-Zustand/Betriebsstunden/Tempo, 60-Sekunden-Belastungstest mit Takt und Temperatur, Geräte ohne Treiber, Windows-Lizenz.', 'Bericht|Prüfbericht als PDF - bei Mängeln dem Händler schicken.')
       Tip = 'Viele Betriebsstunden auf der SSD eines "neuen" Geräts deuten auf Rückläufer oder Vorführgerät hin.' }
    @{ Tab = 'TabUnattend'; Glyph = '&#xE88E;'; Color = '#52627A'; Title = 'Automatische Installation'; Intro = 'Windows-USB-Stick, der ohne Fragen installiert.'
       Items = @('Antwortdatei|Sprache, Tastatur, Edition, Computername, Zeitzone, lokales Administratorkonto - ohne Microsoft-Konto-Zwang, ohne Werbe-Apps, Datenschutz-Fragen übersprungen.', 'Optional|Automatische Geräteverschlüsselung aus, WLAN-Auswahl zeigen, Windows-11-Prüfung für ältere PCs umgehen.', 'Danach|PC-Tools liegt mit auf dem Stick, richtet sich beim ersten Anmelden selbst ein und führt den Einrichtungs-Assistenten mit deinen Einstellungen aus.', 'Sicherheit|Welche Festplatte gelöscht wird, fragt das Setup weiterhin - so wird nie versehentlich die falsche Platte überschrieben.')
       Tip = 'Stick gut beschriften: Er installiert auf jedem PC, der davon startet, ohne weitere Rückfrage.' }
    @{ Tab = 'TabSetup'; Glyph = '&#xE72E;'; Color = '#B91C1C'; Title = 'Neues Gerät: Virenschutz und Server-Tools (Extras)'; Intro = 'Zwei zusätzliche Profile - bewusst nichts vorausgewählt.'
       Items = @('Virenschutz (Extra)|Panda Dome, Bitdefender, Avast, AVG, Avira, Sophos Home und Malwarebytes. Nur EINEN Virenschutz wählen - zwei gleichzeitig bremsen und stören sich. Ohne Auswahl bleibt Microsoft Defender aktiv.', 'Windows-Server-Tools (Extra)|RSAT (Active Directory, DNS, DHCP, Gruppenrichtlinien, Hyper-V-Verwaltung ...), OpenSSH, SNMP, Hyper-V, Windows-Sandbox, Telnet/TFTP-Client, .NET 3.5, Windows Admin Center, Sysinternals, PowerShell 7 und Terminal.', 'Windows-Funktionen|RSAT und Co. kommen direkt von Windows Update; Hyper-V und Sandbox gibt es nur in Pro/Enterprise und brauchen einen Neustart.') }
    @{ Tab = 'TabDebloat'; Glyph = '&#xE74D;'; Color = '#EA580C'; Title = 'Apps entfernen'; Intro = 'Vorinstallierte Werbe- und Test-Apps loswerden.'
       Items = @('Schnellwahl|Vorsichtig: Werbung und Spiele. Empfohlen: zusätzlich entbehrliche Microsoft-Extras. Radikal: auch Xbox, Smartphone-Link, neues Outlook ... Systemwichtiges wird nie angeboten.', 'Herstellersoftware|Auch Testversionen von Virenschutz, Office-Angeboten und Hersteller-Beigaben.', 'Auch für neue Benutzer|Auf Wunsch wird die App auch aus dem Windows-Abbild entfernt, damit sie bei neuen Konten nicht wiederkommt.', 'Zurückholen|Alles Entfernte steht in der Liste unten - ein Klick öffnet es im Store.')
       Tip = 'Vorher wird automatisch ein Wiederherstellungspunkt gesetzt.' }
    @{ Tab = 'TabInstall'; Glyph = '&#xE896;'; Color = '#16A34A'; Title = 'Installieren'; Intro = 'Programme auswählen und still installieren - immer die aktuelle Version, ohne Toolbars oder Werbung.'
       Items = @('Zwei Wege|Oben bei "Quelle" wählst du: "Geprüfter Katalog" zeigt die bewährten Programme nach Kategorien als Karten zum Anhaken (nutzt Ninite Pro, wenn es vorhanden ist). "Online: winget", "Online: Chocolatey" oder "Online: alle Quellen" durchsuchen zehntausende Programme live.', 'Online-Suche|Begriff eintippen (z.B. "firefox", "7zip", "vlc") und Enter drücken. Die Treffer erscheinen als Liste mit Programmname, Paket-ID, Version und Quelle. Mit Strg oder Umschalt mehrere markieren und "Markierte installieren" klicken.', 'Quellen ergänzen sich|Bei "alle Quellen" sucht PC-Tools gleichzeitig in winget und Chocolatey - und zeigt zusätzlich passende Ninite-Programme, wenn Ninite Pro vorhanden ist. Fehlt ein Programm in einer Quelle, übernimmt die andere automatisch.', 'Kostenlos|winget ist in Windows enthalten, Chocolatey wird bei Bedarf kostenlos eingerichtet. Ninite Pro ist optional. Es entstehen keine Kosten.', 'Sicher|Prüfsummen bzw. Signaturen werden geprüft; bei veralteten Katalogeinträgen gibt es Rückfallwege.') }
    @{ Tab = 'TabAccounts'; Glyph = '&#xE716;'; Color = '#0891B2'; Title = 'Konten und Netzwerk'; Intro = 'Benutzer, Netzlaufwerke und BitLocker.'
       Items = @('Benutzer|Anlegen (Standard oder Administrator), aktivieren/deaktivieren, Kennwort setzen, löschen, Windows Hello und automatische Anmeldung.', 'Netzlaufwerke|Buchstabe, Pfad, Benutzer und Kennwort - dauerhaft gespeichert; optional auch für Programme mit Administratorrechten sichtbar.', 'BitLocker|Einschalten mit TPM und Wiederherstellungsschlüssel im PC-Tools-Ordner, auf dem NAS/Stick und im Lizenz-Tresor.') }
    @{ Tab = 'TabCustom'; Glyph = '&#xE790;'; Color = '#7C3AED'; Title = 'Individualisieren'; Intro = 'Das Gerät dauerhaft nach deinem Geschmack.'
       Items = @('Tastaturbeleuchtung|Stufe wählen und "Immer so halten": nach Neustart, Anmeldung, Aufwachen und Netzteilwechsel wird sie automatisch wieder gesetzt (ThinkPad direkt, HP/Dell über das BIOS).', 'Energie und Deckel|Was beim Zuklappen oder Netzschalter passiert, Bildschirm-/Energiespar-Zeiten, Energiesparplan, Energiesparmodus.', 'Akku|Zustand in % der Originalkapazität, Ladezyklen, ausführlicher Akku-Bericht.', 'Touchpad, Maus, Tastatur|Tippen zum Klicken, natürliches Scrollen, Zeigergeschwindigkeit ohne Beschleunigung, Wiederholrate, Einrasttasten-Abfrage aus.', 'Aussehen|Hell/Dunkel, Transparenz, Akzentfarbe, Startsound.', 'BIOS-Einstellungen|Bei Lenovo, HP und Dell direkt aus Windows: Fn-Taste, Ladegrenze, USB-Laden, Wake-on-LAN, Lüfter ...')
       Tip = 'BIOS-Änderungen wirken erst nach einem Neustart. Ist ein BIOS-Kennwort gesetzt, muss es eingetragen werden.' }
    @{ Tab = 'TabTune'; Glyph = '&#xE771;'; Color = '#0891B2'; Title = 'Tuning'; Intro = 'Windows-Optimierungen für Leistung, Datenschutz und Bedienung - und der Autostart.'
       Items = @('Vorgaben|Empfohlen, Maximale Leistung, Datenschutz oder alles auf Windows-Standard.', 'Autostart|"Nur das Nötige" lässt mit einem Klick nur Sicherheit, Treiber-Helfer und PC-Tools an. Dazu Empfehlung, Alle an, Alle aus, Rückgängig und die Stecknadel für Programme, die immer bleiben sollen.') }
    @{ Tab = 'TabDesk'; Glyph = '&#xE8B7;'; Color = '#475569'; Title = 'Desktop aufräumen'; Intro = 'Ordnung auf dem Desktop.'
       Items = @('Kategorien|Verknüpfungen in Ordner wie Büro, KI, 3D-Druck einsortieren.', 'Anordnung|Symbole in Zeilen oder Spalten nach Kategorien - wird beim Anmelden wiederhergestellt.') }
    @{ Tab = 'TabMon'; Glyph = '&#xE7F4;'; Color = '#475569'; Title = 'Monitore'; Intro = 'Monitor-Anordnungen speichern und per Verknüpfung umschalten.'
       Items = @('Profile|Z.B. "Büro mit 3 Monitoren" und "unterwegs" - je eine Desktop-Verknüpfung.') }

    @{ Tab = 'TabNet'; Glyph = '&#xE701;'; Color = '#2D7FF9'; Title = 'Netzwerk'; Intro = 'Alles rund um Internet, WLAN und Verbindungen.'
       Items = @('Übersicht|Adapter, IP, Router, DNS, WLAN-Signal, Kanal und Frequenz, öffentliche IP.', 'Speedtest|Download, Upload, Ping und Schwankung (über Cloudflare).', 'DNS|Mit einem Klick Cloudflare, Google, Quad9, AdGuard (Werbefilter) oder eigene Server.', 'WLAN-Scan|Alle WLANs in der Nähe mit Kanal - und welcher 2,4-GHz-Kanal am freiesten ist.', 'WLAN-Kennwörter|Gespeicherte Kennwörter anzeigen, kopieren oder Netze vergessen.', 'Verbindungen|Welches Programm redet mit welchem Server - Namen auflösen und Programme per Firewall sperren.', 'Werkzeuge|Ping, Traceroute, DNS-Abfrage und Port-Test.')
       Tip = 'Langsames WLAN? Erst Speedtest per Kabel, dann per WLAN - ist nur WLAN langsam, den Kanal im Router wechseln.' }
    @{ Tab = 'TabNetDiag'; Glyph = '&#xE774;'; Color = '#DC2626'; Title = 'Netzwerk-Diagnose'; Intro = 'Neu in 7.3: wenn der PC keine IPv4-Adresse bekommt (169.254.x.x) oder kein Internet hat.'
       Items = @('Prüfung|Rund 40 Prüfungen ohne Internet: Netzwerkdienste (DHCP-Client ...), Gerätefehler, deaktivierte Adapter, IPv4-Bindung, DHCP an/aus, APIPA-Adresse, IPv6 als Gegenprobe, Nachbarn im Netz, zufällige MAC, Energiesparen, fremde Filter (VPN/Virenschutz), DHCP-Broadcast-Flag, Firewall-Regel für DHCP, Winsock-LSPs, Proxy, Hosts, Schnellstart, DHCP-Ereignisse, Router/Internet/DNS-Test.', 'Automatisch reparieren|Geht die sicheren Schritte der Reihe nach durch und hört auf, sobald eine gültige Adresse da ist.', 'Einzeln|Adresse neu anfordern, Adapter neu starten, DHCP an, feste IP zum Testen, Energiesparen aus, Broadcast-Flag aus, zufällige MAC aus, Treiber neu installieren, WLAN-Profil neu anlegen - und alle erweiterten Treibereinstellungen ändern.', 'Tiefe Reparatur|TCP/IP, IPv6, Winsock und Proxy zurücksetzen, auf Wunsch alle Adapter neu installieren (netcfg -d), dann Neustart.', 'Bericht|Textdatei mit allen Rohdaten (ipconfig, netsh, Bindungen, Treiber, Ereignisse) plus WLAN-Bericht von Windows - portabel direkt auf dem Stick.', 'Notfall-Stick|"Netzwerk-Notfall.cmd" auf dem Stick startet die Diagnose im Textfenster - auch wenn die Oberfläche nicht geht.')
       Tip = 'Mit fester IP klappt Internet, mit DHCP nicht? Dann liegt es am DHCP (Router oder Broadcast-Flag) - nicht am WLAN-Treiber.' }
    @{ Tab = 'TabPrinter'; Glyph = '&#xE749;'; Color = '#0F766E'; Title = 'Drucker und Scanner'; Intro = 'Drucker und Multifunktionsgeräte einrichten, verwalten und reparieren.'
       Items = @('Finden|Netzwerk-Suche mit Hersteller und Modell (SNMP/Weboberfläche), USB-Geräte, Windows-Assistent.', 'Vollständiger Herstellertreiber|Treiberseite des Herstellers für genau dieses Modell (HP, Brother, Canon, Epson, Kyocera, Lexmark, Xerox, Ricoh, Konica Minolta, OKI, Sharp, Samsung, Dell), Hersteller-Apps per winget, heruntergeladene Pakete (exe/msi/zip/inf) mit Signaturprüfung installieren - Scanner, Fax und Tintenstand inklusive.', 'Ohne Download|Microsoft IPP/PCL6/PS-Klassentreiber oder Treiber über Windows Update. Beim Einrichten: SNMP-Statusabfrage aus (kein falsches Offline), Standarddrucker, Testseite.', 'Verwalten|Standard, Testseite, Druckeinstellungen, Warteschlange, Weboberfläche, umbenennen, freigeben, entfernen, unbenutzte Treiber aufräumen.', 'Fehlerbehebung|Druckwarteschlange, hängende Aufträge, "offline verwenden", Erreichbarkeit und neue IP-Adresse (Drucker wird automatisch umgestellt), SNMP, WSD-Anschlüsse, fehlende Treiber, Fehlerprotokoll, 0x0000011b, Scanner-Dienst, Netzwerkerkennung - mit Ein-Klick-Lösung und komplettem Zurücksetzen.')
       Tip = 'Drucker bekommt ständig eine neue IP? Im Router eine feste Adresse für den Drucker einstellen.' }
    @{ Tab = 'TabLic'; Glyph = '&#xE8D7;'; Color = '#D97706'; Title = 'Lizenzen'; Intro = 'Alle Lizenzen auslesen, sicher aufbewahren und auf einen neuen PC übertragen.'
       Items = @('Windows|Edition, Aktivierung, Lizenzart (digital, OEM, Retail, Volumen), installierter Schlüssel, Schlüssel im BIOS und eine Anleitung, wie genau diese Lizenz umzieht.', 'Lösen und aktivieren|Retail-Lizenz auf dem alten PC lösen (slmgr /upk), auf dem neuen Schlüssel eingeben und aktivieren - mit Sicherheitsabfrage.', 'Office|Klassische Schlüssel-Lizenzen (entfernen mit OSPP) und Microsoft-365-Konten.', 'Programme|Über 20 bekannte Programme (WinRAR, Total Commander, Adobe, Autodesk, JetBrains, Virenschutz, Sicherungs-Software ...) mit Hinweis, wie die Lizenz umzieht; Lizenzdateien direkt in den Tresor.', 'Tresor|Eigene Schlüssel und Lizenzdateien, verschlüsselt mit deinem Windows-Konto. Schlüssel sind verdeckt, bis du "anzeigen" klickst.', 'Umzug|"Für Umzug exportieren" erzeugt eine .pclic-Datei mit eigenem Kennwort (AES-256). Auf dem neuen PC: Import, gleiches Kennwort - fertig.', 'Übersicht|Alles als Textdatei - wahlweise mit gekürzten Schlüsseln.')
       Tip = 'Digitale Windows-Lizenz? Dann gibt es keinen Schlüssel zum Abschreiben - wichtig ist nur, dass das Microsoft-Konto verknüpft ist.' }
    @{ Tab = 'TabMedia'; Glyph = '&#xE753;'; Color = '#2D7FF9'; Title = 'Windows und Office'; Intro = 'Windows-ISO, Office und bootfähiger USB-Stick.'
       Items = @('Windows 11 ISO|Offiziell oder Insider (Release Preview bis Canary), auf Wunsch direkt als Upgrade installieren.', 'Office|Installieren, Offline-Paket laden, Updatekanal wechseln.', 'USB-Stick|Bootfähig mit Windows, Office und portablen PC-Tools.') }
    @{ Tab = 'TabAdmin'; Glyph = '&#xE7EF;'; Color = '#475569'; Title = 'Computerverwaltung'; Intro = 'Die Admin-Werkzeuge an einem Ort.'
       Items = @('Bereiche|Datenträger (inkl. Bereinigen und SMART), Dienste, Geräte, Aufgaben, Ereignisse, Benutzer, Freigaben, Programme und Werkzeuge.') }
    @{ Tab = 'TabEnergy'; Glyph = '&#xE83F;'; Color = '#059669'; Title = 'Akku und Energie: Akku, Verbrauch, Ladegrenze'; Intro = 'Neu in 10.0: Zustand und Verschleiß des Akkus mit Verlauf, wer den Akku leert, und wie man ihn schont.'
       Items = @('Akku jetzt|Zwei Ringe zeigen Ladestand und Gesundheit (heutige volle Kapazität geteilt durch die Kapazität im Neuzustand). Darunter: geschätzte Restlaufzeit, Laufzeit bei voller Ladung, aktuelle Leistungsaufnahme in Watt (misst der Akku nur im Akkubetrieb) und Ladezyklen. Die Werte werden alle 10 Sekunden aktualisiert, solange die Seite offen ist.', 'Akku im Detail|Hersteller, Zellchemie, Seriennummer, Kapazität neu und heute, Verschleiß, Spannung und eine Einschätzung in Klartext. Über 80 % ist gut, 60-80 % gebraucht, unter 60 % ist ein Tausch sinnvoll.', 'Kapazitätsverlauf|Diagramm aus zwei Quellen: dem wöchentlichen Verlauf von Windows (powercfg /batteryreport, reicht oft Jahre zurück) und dem täglichen Messpunkt von PC-Tools (Seite Gerätezustand). Daraus berechnet PC-Tools den Verschleiß pro Monat und wann der Akku voraussichtlich unter 70 % fällt.', 'Was zieht den Akku leer?|Wertet den Systemressourcen-Monitor von Windows aus (powercfg /srumutil): Energieverbrauch jedes Programms der letzten 1-30 Tage als Rangliste mit farbigen Balken, aufgeteilt nach Prozessor, Bildschirm, Netzwerk und Datenträger. Funktioniert auch am Netzteil.', 'Energie-Analyse|60 Sekunden Messung mit powercfg /energy. Fehler und Warnungen werden auf Deutsch erklärt, mit Tipp zur Abhilfe (z.B. Programme, die den Windows-Takt beschleunigen, USB-Geräte, die nicht einschlafen, zu lange Bildschirmzeiten, abgeschaltetes PCI-Express-Energiesparen).', 'Ladegrenze|Bei HP (Battery Health Manager) und Dell (Primary Battery Charge Configuration, auch Start/Stopp in Prozent) direkt einstellbar - über dieselbe BIOS-Schnittstelle wie die Seite BIOS-Einstellungen, auf Wunsch mit BIOS-Kennwort. Lenovo (ThinkPad-Ladeschwellen, IdeaPad-Schutzmodus) über Lenovo Vantage, Surface über den Akkubegrenzungsmodus im UEFI; dazu Hinweise für ASUS, Acer, MSI, Samsung und Framework.')
       Tip = 'Laptops, die fast immer am Netzteil oder in der Dockingstation hängen, mit Ladegrenze 60-80 % betreiben - das kann die Lebensdauer des Akkus verdoppeln. Vor einer Reise kurz auf 100 % stellen.' }
    @{ Tab = 'TabEnergy'; Glyph = '&#xE708;'; Color = '#4F46E5'; Title = 'Akku und Energie: Standby, Pläne, Desktop und USV'; Intro = 'Warum der PC nicht schläft oder nachts aufwacht - und die richtigen Energieeinstellungen.'
       Items = @('Standby und Aufwachen|Zeigt, ob das Gerät Modern Standby (S0, schläft wie ein Handy) oder klassischen Standby (S3) nutzt, ob Ruhezustand und Schnellstart an sind und wie groß die Ruhezustandsdatei ist. Beides lässt sich mit Rückfrage umschalten.', 'Was verhindert den Standby?|Programme, Dienste und Treiber, die Windows gerade wach halten (powercfg /requests), mit Grund - z.B. Videowiedergabe, Audio-Treiber oder Updates.', 'Weckzeitgeber und Weckgeräte|Welche geplanten Aufgaben den PC wecken dürfen und welche Geräte (Maus, Tastatur, Netzwerkkarte). Einem Gerät das Wecken verbieten oder wieder erlauben: auswählen und Knopf drücken (mit Rückfrage). Dazu der Aufwach-Verlauf aus dem Ereignisprotokoll.', 'Standby-Analyse|Bei Modern Standby: jede Standby-Phase der letzten 3 Tage mit Dauer, Tiefschlaf-Anteil, Akkuverbrauch und Hauptverursacher (powercfg /sleepstudy). Bei S3: System-Standby-Diagnose als Bericht.', 'Energiesparpläne|Alle Pläne mit Herkunft; aktivieren, löschen (nicht die von Windows) und drei fertige PC-Tools-Pläne anlegen: "Ausgewogen leise" (kühl und leise), "Akku-Langläufer" (maximale Laufzeit) und "Volle Leistung (Netzteil)".', 'Energiemodus|Der Windows-11-Schieberegler (Beste Energieeffizienz, Ausbalanciert, Beste Leistung) getrennt für Netzteil und Akku. Wirkt nur mit dem Plan "Ausbalanciert".', 'Desktop-PC und USV|Ohne Akku zeigt die Seite Stromspartipps und einen Stromkosten-Rechner. Eine über USB angeschlossene USV wird erkannt: Ladung, Überbrückungszeit und ab welcher Restladung Windows bei Stromausfall herunterfährt (einstellbar).')
       Tip = 'Wacht der PC nachts auf: zuerst "Aufwach-Verlauf" ansehen. Steht dort die Netzwerkkarte, ihr das Wecken verbieten; steht dort ein Weckzeitgeber (meist Windows Update), unter Individualisieren "Weckzeitgeber erlauben" abschalten.' }
    @{ Tab = 'TabPower'; Glyph = '&#xE7E8;'; Color = '#475569'; Title = 'Neustart und BIOS'; Intro = 'Alle Start- und Ausschaltvarianten.'
       Items = @('Kacheln|Neustart, vollständig herunterfahren, UEFI/BIOS, erweiterte Startoptionen, abgesicherter Modus, Speicher- und Datenträgerprüfung.', 'Einmalig starten von|USB-Stick, Netzwerk oder anderem System - nur beim nächsten Start.') }
    @{ Tab = 'TabBios'; Glyph = '&#xE950;'; Color = '#334155'; Title = 'BIOS-Einstellungen'; Intro = 'BIOS/UEFI direkt aus Windows einstellen - ohne beim Start Tasten zu drücken.'
       Items = @('Unterstützt|Lenovo (ThinkPad, ThinkCentre, ThinkStation), HP (EliteBook, ProBook, ZBook, Z-Workstation ...) und Dell (Latitude, OptiPlex, Precision ...) über die offiziellen WMI-Schnittstellen. Andere Marken: Firmware-Infos, BIOS-Taste und Neustart direkt ins BIOS.', 'Firmware-Infos|BIOS-Version, UEFI oder Legacy, Secure Boot, TPM und welche BIOS-Kennwörter gesetzt sind.', 'Schnellschalter|Nach Themen: Warnungen beim Start (z.B. Netzteil zu schwach), Einschalten und Aufwachen (Wake on LAN, Einschalten bei Netzanschluss), Akku, Leistung und Lüfter, Tastatur (Fn/Strg tauschen, F1-F12, Beleuchtung), Virtualisierung, Sicherheit, Startreihenfolge, Kamera/Mikrofon/Funk, Anschlüsse. Angezeigt wird nur, was das Modell wirklich hat.', 'Alle Einstellungen|Komplette Liste mit Suche und Themenfilter. Zeile wählen, neuen Wert wählen oder eintippen, "Vormerken". Erst "Änderungen übernehmen" schreibt ins BIOS - mit BIOS-Kennwort, falls eines gesetzt ist.', 'Sichern und zurückspielen|Alle Einstellungen als Datei sichern und später (oder auf einem baugleichen PC) wieder vormerken. Liste als CSV. Lenovo: Werkseinstellungen laden.', 'Netzteil-Warnung|"The connected AC adapter has a lower wattage ...": Dell kann solche Warnungen abschalten bzw. ohne Pause fortfahren. Bei vielen ThinkPads gibt es dafür keinen Schalter - dann hilft nur ein Netzteil mit genug Leistung (USB-C, mind. 65 W).')
       Tip = 'Vor Änderungen an Secure Boot oder TPM den BitLocker-Wiederherstellungsschlüssel bereitlegen (Seite Sicherheit).' }
    @{ Tab = 'TabSurface'; Glyph = '&#xE70A;'; Color = '#2563EB'; Title = 'Microsoft Surface'; Intro = 'Neu in 7.3: alles für Surface Pro, Laptop, Book, Go und Studio.'
       Items = @('Gerät|Modell, SKU, Seriennummer, UEFI-Version, Secure Boot/TPM/BitLocker, WLAN-Chip mit Treiber, Bildschirm, Akku, Zubehör.', 'Treiberpaket|Das komplette MSI-Paket von Microsoft (alle Treiber und Firmware) für fast 50 Modelle: suchen, laden und installieren - oder auf einen USB-Stick laden, wenn das Surface kein Internet hat. "Nur Netzwerktreiber" entpackt das Paket und spielt nur WLAN/LAN ein.', 'Treiber und Firmware|Alle Surface-, Firmware- und Netzwerktreiber mit Version und Status; Gerät neu starten, Treiber neu installieren.', 'UEFI und Start|Neustart ins Surface UEFI, Tastenkombinationen für UEFI, USB-Start und erzwungenen Neustart passend zum Modell, BitLocker für Firmware aussetzen, Wiederherstellung.', 'Akku|Zustand in %, Kapazität, Ladezyklen, Akkubericht, Hinweis auf Akkubegrenzung (50 %).', 'Zubehör|Type Cover, Stift, Touch, Kamera, Dock - neu starten, kalibrieren, koppeln.', 'Bekannte Probleme|Marvell-WLAN ohne IP, Akku lädt nicht, schwarzer Bildschirm, Type Cover, Flackern, Firmware-Update, Stift, Dock - jeweils mit Lösung.')
       Tip = 'Surface ohne Internet: auf einem anderen PC Modell wählen, "Auf USB-Stick laden" (die portablen PC-Tools kommt gleich mit), am Surface "Paket vom Stick installieren".' }
    @{ Tab = 'TabToolbox'; Glyph = '&#xE90F;'; Color = '#0891B2'; Title = 'Toolbox: Werkzeuge auf Knopfdruck'; Intro = 'Neu in 9.0: 25 bewährte, kostenlose Admin- und Diagnose-Werkzeuge - immer aktuell, geprüft und auch vom USB-Stick nutzbar.'
       Items = @('Kacheln|Jedes Werkzeug hat eine Kachel mit Symbol, Kategorie (System, Hardware, Datenträger, Netzwerk, USB, Fernhilfe), kurzer Beschreibung und Stand: "Version ... - geladen am ...", "nicht geladen", "Update verfügbar" (orange) oder "installiert via winget". Kategorie-Auswahl und Suchfeld filtern die Kacheln; der Tooltip nennt Quelle und ob das Werkzeug portabel ist.', 'Starten|Startet das geladene Programm mit Administratorrechten. Sysinternals-Werkzeuge starten mit akzeptierter Lizenz (/accepteula), damit keine Nachfrage erscheint. Bei der Sysinternals Suite öffnet "Starten" eine Auswahlliste aller Programme mit Fenster, dazu "Eingabeaufforderung hier" für die Kommandozeilen-Werkzeuge (PsExec, Sigcheck, Handle, PsInfo ...).', 'Laden / Aktualisieren|Holt die neueste Version direkt beim Hersteller: Sysinternals und NirSoft über die festen Download-Adressen, Rufus, Ventoy und RustDesk über das neueste GitHub-Release, CPU-Z, HWiNFO (mit Ausweich-Server) und Everything über die Herstellerseite. ZIP-Dateien werden entpackt, die Programmdatei (64-Bit bevorzugt) wird automatisch gefunden. Ist die Version schon aktuell, wird nichts geladen.', 'Sicher|Alle Programmdateien werden auf ihre digitale Signatur geprüft: signierte Dateien müssen gültig sein und vom erwarteten Hersteller stammen (z.B. Microsoft bei Sysinternals, CPUID bei CPU-Z), sonst wird der Download verworfen. Das Ersetzen einer vorhandenen Version geschieht erst, wenn der neue Download vollständig und geprüft ist - läuft das Programm gerade, bleibt die alte Version erhalten.', 'Ohne portable Version|GPU-Z, CrystalDiskInfo, CrystalDiskMark, WinDirStat, TreeSize Free und Wireshark gibt es nicht (sinnvoll) als portable Datei - sie werden auf diesem PC über winget installiert und dann direkt aus der Kachel gestartet.', 'Nach Updates suchen|Fragt im Hintergrund bei allen Herstellern nach: GitHub-Version, Versionsnummer auf der Herstellerseite oder Datum/Größe der Download-Datei. Werkzeuge mit neuer Version werden orange markiert; "Alle laden/aktualisieren" holt dann nur die neuen.', 'Speicherort|Ordner "Toolbox" im Datenordner von PC-Tools (normalerweise C:\ProgramData\PCPflege\Toolbox). Jedes Werkzeug liegt in einem eigenen Unterordner mit einer kleinen Datei toolbox.json (Version, Quelle, Datum, Signatur). "Toolbox-Ordner öffnen" zeigt ihn im Explorer; die Statuskacheln oben zeigen, wie viele Werkzeuge geladen sind, wie viele Updates es gibt und wie viel Platz die Toolbox belegt.')
       Tip = 'Einmal "Alle laden/aktualisieren" (ca. 250 MB) - danach reicht ab und zu "Nach Updates suchen".' }
    @{ Tab = 'TabToolbox'; Glyph = '&#xE88E;'; Color = '#0891B2'; Title = 'Toolbox auf dem USB-Stick'; Intro = 'Die komplette Werkzeugsammlung für unterwegs - läuft an jedem PC ohne Installation.'
       Items = @('Auf USB-Stick kopieren|Wählt einen Wechseldatenträger (oder einen beliebigen Ordner) und spiegelt die Toolbox nach <Stick>\PCPflege\Daten\Toolbox - also genau dorthin, wo die portablen PC-Tools ihre Daten ablegen. Fehlen die portablen PC-Tools auf dem Stick, werden sie auf Wunsch gleich mitkopiert. Vorher wird geprüft, ob genug Platz frei ist.', 'Am fremden PC|Auf dem Stick "PC-Tools starten.cmd" öffnen, Seite Toolbox: alle Werkzeuge sind sofort da und starten direkt vom Stick. Läuft PC-Tools portabel, landen neue Downloads automatisch auf dem Stick.', 'Aktualisieren|Einfach erneut "Auf USB-Stick kopieren" - nur geänderte Dateien werden übertragen, veraltete Versionen auf dem Stick entfernt.', 'Hinweis|Die winget-Programme (GPU-Z, CrystalDiskInfo usw.) werden immer auf dem jeweiligen PC installiert, nicht auf dem Stick.')
       Tip = 'Zusammen mit dem Netzwerk-Notfall und dem Surface-Treiberpaket wird der Stick zum kompletten Werkzeugkoffer.' }
    @{ Tab = 'TabKiosk'; Glyph = '&#xE719;'; Color = '#7C3AED'; Title = 'Software-Kiosk'; Intro = 'Neu in 9.0: Programme wie im App-Store installieren - nach Rolle oder einzeln, still im Hintergrund über winget.'
       Items = @('Rollen|Acht fertige Rollen: Büro, Rezeption/Empfang, Kasse/Theke, Entwicklung, Grafik & Foto, Familie/Zuhause, Gaming und Admin/IT. Jede Kachel zeigt Beschreibung, Anzahl der Programme, wie viele davon schon installiert sind, und die ersten Programme als Vorschau.', 'Programmliste|Ein Klick auf eine Rolle zeigt ihre Programme mit Häkchen und Status ("installiert", "fehlt"). Fehlende Programme sind vorausgewählt. "Ausgewählte installieren" installiert die angehakten, "Alle der Rolle installieren" alle (bereits installierte werden dabei aktualisiert), "Nur fehlende anhaken" setzt die Auswahl zurück.', 'Installation|Läuft als Hintergrundaufgabe mit Fortschritt und Protokoll (Seite Protokoll) - auch wenn das Fenster geschlossen wird. Downloads kommen über winget direkt vom Hersteller, mit Prüfsumme. Microsoft 365 Apps (Office) wird über das Office Deployment Tool installiert (Deutsch, aktueller Kanal, ohne Teams/Access/Publisher). Danach wird der Installationsstatus automatisch neu eingelesen.', 'Erkennung|"Installiert" ermittelt PC-Tools über winget (exakte Paket-ID) und zusätzlich über "Programme und Features" - so werden auch Programme erkannt, die von Hand installiert wurden. "Installationsstatus aktualisieren" liest neu ein.', 'Einzelne Programme|Der ganze Katalog (über 50 Programme in 11 Kategorien) als Kacheln mit Suche und Kategorie-Filter. "Installieren" startet sofort, "+ Rolle" nimmt das Programm in die gewählte eigene Rolle auf. "In winget suchen ..." findet jedes weitere winget-Paket (Katalog-Treffer sofort, winget nach einigen Sekunden) - oder die Paket-ID direkt eintippen.')
       Tip = 'PC-Tools läuft vom Stick? Die Programme werden trotzdem auf dem PC installiert, an dem der Stick steckt - ideal zum Einrichten neuer Geräte.' }
    @{ Tab = 'TabKiosk'; Glyph = '&#xE8B5;'; Color = '#DB2777'; Title = 'Eigene Kiosk-Rollen'; Intro = 'Die Programmliste genau so, wie sie im Hotel, in der Firma oder zu Hause gebraucht wird.'
       Items = @('Als eigene Rolle speichern|Speichert die angehakten Programme der gewählten Rolle als neue, frei bearbeitbare Rolle - mit eigenem Namen, Beschreibung und Farbe.', 'Neue eigene Rolle|Legt eine leere Rolle an; Programme kommen über "Programm hinzufügen ..." (Katalog und winget-Suche) oder "+ Rolle" im Katalog dazu. Das X neben einem Programm nimmt es wieder heraus.', 'Exportieren und importieren|"Rolle exportieren ..." speichert eine Rolle (auch eine eingebaute) als JSON-Datei, "Rolle importieren ..." liest sie auf einem anderen PC wieder ein - z.B. für alle Rezeptions-PCs die gleiche Ausstattung. Gleichnamige Rollen bekommen den Zusatz "(importiert)".', 'Speicherort|Eigene Rollen stehen in kiosk.json im Datenordner von PC-Tools (bei der portablen Version auf dem Stick).', 'Löschen|"Rolle löschen" entfernt nur die Rolle, installierte Programme bleiben unberührt. Eingebaute Rollen lassen sich nicht löschen oder ändern - dafür gibt es "Als eigene Rolle speichern".')
       Tip = 'Einmal eine Rolle "Rezeption Waldhotel" bauen, exportieren und auf den Stick legen - jeder neue Empfangs-PC ist dann mit zwei Klicks fertig.' }
    @{ Tab = 'TabOverview'; Glyph = '&#xE9D2;'; Color = '#16A34A'; Title = 'Zustands-Score'; Intro = 'Ein einziger Wert von 0 bis 100, der zeigt, wie gut es dem PC insgesamt geht - mit Trend, Verlauf und Warnung bei einem Einbruch.'
       Items = @('Bestandteile und Gewichtung|Sicherheit 25 Punkte, Updates 15, Speicherplatz 10, Datenträger 15, Stabilität 15, Akku 5, Startzeit 5, Geräte 5, Temperatur 5. Was ein PC nicht hat oder was Windows nicht liefert (z.B. Akku am Desktop-PC, Temperatur, Startzeit), zählt nicht mit - der Score wird dann auf die übrigen Bestandteile umgerechnet, damit ein Desktop-PC nicht schlechter dasteht als ein Laptop.', 'Sicherheit|Hat die Seite Sicherheit schon geprüft, wird ihr ausführlicher Wert übernommen (z.B. 88 von 100 = 22 von 25 Punkten). Sonst prüft der Score schnell selbst: Virenschutz aktiv und aktuell, Firewall in allen Netzwerken an, Laufwerk C: verschlüsselt (BitLocker oder Geräteverschlüsselung), Secure Boot, Benutzerkontensteuerung.', 'Updates|Wann zuletzt ein Windows-Update installiert wurde (bis 35 Tage volle Punkte, ab 90 Tagen keine), ob ein Neustart aussteht, damit Updates fertig werden, und ob Installationen in den letzten 30 Tagen fehlgeschlagen sind.', 'Speicherplatz|Freier Platz auf Laufwerk C: - volle Punkte ab 20 % und mindestens 30 GB frei. Unter 10 GB frei gibt es höchstens 2 Punkte, weil dann Updates scheitern.', 'Datenträger|Zustand, Verschleiß (Wear) und nicht korrigierbare Lesefehler aller Laufwerke, wie sie die Laufwerke selbst melden (S.M.A.R.T.). Meldet ein Laufwerk "Warnung" oder "defekt", gibt es 0 Punkte - dann sofort sichern.', 'Stabilität|Bluescreens (minus 5 je Stück), unerwartetes Ausschalten oder Neustarten, z.B. Stromausfall oder Absturz (minus 2 je Stück), und Programmabstürze der letzten 30 Tage.', 'Akku, Startzeit, Geräte, Temperatur|Akku: Kapazität im Vergleich zum Neuzustand (ab 80 % volle Punkte). Startzeit: Durchschnitt der letzten 5 Starts (bis 30 Sekunden volle Punkte). Geräte: Geräte ohne funktionierenden Treiber (ausgeblendete Geräte zählen nicht). Temperatur: Gehäuse-/Prozessorsensor und Laufwerkstemperaturen, soweit Windows sie liefert.', 'Anzeige|Der Ring zeigt den Wert in Farbe (grün ab 85, orange ab 65, sonst rot), daneben der Trend gegenüber dem Durchschnitt der letzten 7 Tage und eine Kurve der letzten 90 Tage. Rechts jeder Bestandteil mit Balken, Punkten und Begründung - so sieht man sofort, wo Punkte fehlen.', 'Verlauf|"Verlauf" öffnet das große Diagramm für 30, 90 oder 365 Tage mit dem 7-Tage-Durchschnitt, roten Marken bei Einbrüchen und einer Tabelle aller Tage. Gespeichert wird ein Wert pro Tag in Score.csv im Datenordner (2 Jahre lang), beim Start von PC-Tools und nach jeder Pflege.', 'Benachrichtigung|Fällt der Score um 10 Punkte oder mehr unter den Durchschnitt der letzten 7 Tage, kommt eine Nachricht über die eingerichteten Kanäle (ntfy, Home Assistant, Chat) - höchstens einmal am Tag, mit den drei schwächsten Bestandteilen.')
       Tip = 'Ein plötzlicher Einbruch hat fast immer eine konkrete Ursache: Bluescreen, volles Laufwerk, ausgeschalteter Virenschutz oder ein Laufwerk mit Lesefehlern. Die Begründungen in der Karte zeigen, welche.' }
    @{ Tab = 'TabHwTest'; Glyph = '&#xE9D9;'; Color = '#0E7490'; Title = 'Hardware-Test: die Tests'; Intro = 'Das Testzentrum prüft die wichtigsten Bauteile gründlich - ideal beim Kauf oder Verkauf eines gebrauchten Geräts, bei der Übergabe an Kollegen oder wenn der PC spinnt. Alle Tests sind nur lesend.'
       Items = @('Arbeitsspeicher|Belegt 25, 50 oder 75 % des freien Arbeitsspeichers (mindestens 1 GB bzw. 10 % bleiben für Windows frei) und prüft jedes 64-Bit-Wort mit sechs Mustern: alle Bits 0, alle Bits 1, 0x55/0xAA (Nachbarbits abwechselnd), wandernde Einsen und ein Zufallsmuster. Jedes Muster wird erst komplett geschrieben und dann komplett gelesen - so fallen auch Zellen auf, die ihren Inhalt verlieren. Angezeigt werden Fortschritt, Geschwindigkeit und die ersten Fehler mit Adresse und abweichenden Bits.', 'Windows-Speicherdiagnose|Prüft den gesamten Speicher außerhalb von Windows (auch den Teil, den Windows selbst belegt). "Windows-Speicherdiagnose beim Neustart" plant sie für den nächsten Start ein (dauert 10-60 Minuten), "Ergebnis der Speicherdiagnose" liest das Ergebnis aus dem Ereignisprotokoll (MemoryDiagnostics-Results, Ereignis 1101/1201) und übernimmt es ins Protokoll.', 'Datenträger-Lesetest|Liest den gewählten Datenträger direkt Block für Block (1, 2 oder 4 MB, ohne Windows-Zwischenspeicher) und misst jeden Block. Der Schnelltest verteilt in etwa 2 Minuten immer dichtere Stichproben über den ganzen Datenträger, der vollständige Test liest jeden Block (je nach Größe und Laufwerk Minuten bis Stunden). Die Kurve zeigt die Geschwindigkeit über die Position - bei Festplatten fällt sie nach innen normal ab, Einbrüche und orange/rote Marken zeigen langsame Blöcke (über 200/500 ms) und Lesefehler. Es wird nichts geschrieben.', 'Zuverlässigkeitswerte|Die Tabelle zeigt für jedes Laufwerk, was es selbst meldet: Zustand, Temperatur, Verschleiß in %, nicht korrigierbare Lesefehler und Betriebsstunden. Viele Betriebsstunden bei einem "neuen" Gerät verraten Vorführ- oder Gebrauchtware.', 'Prozessor-Belastungstest|Lastet alle, die Hälfte oder einen Kern 1, 5 oder 10 Minuten voll aus. Jede Sekunde werden Takt, Auslastung und - wenn Windows sie liefert - die Temperatur gemessen und als Diagramm gezeigt. Fällt der Takt unter Last um mehr als 25 % unter die Spitze, meldet der Test Drosselung und sagt, ob Hitze (Kühler reinigen, Wärmeleitpaste) oder eine Leistungsgrenze die Ursache ist. Ab 90 °C gibt es eine Warnung, ab 95 °C einen Fehler. Stürzt der PC während des Tests ab, ist das der wichtigste Befund überhaupt.', 'Akku-Test|Vergleicht die heutige volle Kapazität mit der im Neuzustand (ab 80 % gut, unter 60 % verschlissen) und zeigt die Ladezyklen. Die 3-Minuten-Messung läuft ohne Netzteil und misst den echten Verbrauch - daraus berechnet PC-Tools, wie lange eine volle Ladung bei dieser Nutzung reicht. "Akkubericht" erstellt den ausführlichen Windows-Bericht (powercfg /batteryreport) mit Kapazitätsverlauf. Die Anleitung erklärt, wie man die Prozentanzeige neu kalibriert.', 'Bildschirm-Pixeltest|Elf Vollbild-Testbilder: Schwarz, Weiß, Rot, Grün, Blau, Grau, Grauverlauf, 16 Graustufen, Farbverläufe, Raster und feines Schachbrett. Weiter mit Klick, Leertaste oder Pfeiltasten, zurück mit Rechtsklick oder Pfeil links, H blendet den Hinweis dauerhaft ein, Esc beendet. Danach bewertest du, was du gesehen hast.', 'Pixel-Wiederbeleber|Ein kleines, sehr schnell die Farbe wechselndes Quadrat, das du mit der Maus auf einen hängenden Pixel ziehst (Mausrad = Größe, Rechtsklick = Ende). 10-30 Minuten laufen lassen - hilft manchmal bei farbigen oder hellen "hängenden" Pixeln, nicht bei toten schwarzen. Achtung bei Lichtempfindlichkeit (Flackern).', 'Tastatur-Test|Deutsche Tastatur mit Funktionstasten, Pfeil- und Navigationsblock und Ziffernblock. Gedrückte Tasten werden grün, gerade gehaltene blau - bleibt eine Taste blau, klemmt sie. Links/rechts (Umschalt, Strg, Alt/AltGr) und Enter/Ziffernblock-Enter werden unterschieden; der Ziffernblock wird auch ohne Num-Lock richtig erkannt. Unten stehen die letzten Tasten und Tasten, die nicht im Bild sind (z.B. Lautstärke).', 'Touch/Stift-Test|Vollbild mit 160 Feldern: mit Finger, Stift oder Maus überall hinmalen - jedes berührte Feld wird grün, die Abdeckung steht oben. Beim Stift wird der Andruck angezeigt und gezählt, wie viele Druckstufen ankommen; außerdem die höchste Zahl gleichzeitiger Finger. Felder, die trotz Berührung dunkel bleiben, sind tote Zonen im Touchscreen.')
       Tip = 'Tests mit großer Last (Arbeitsspeicher, Prozessor, vollständiger Datenträgertest) nicht gleichzeitig laufen lassen - dann sind die Ergebnisse (Geschwindigkeit, Takt) nicht vergleichbar. Laptops für den Prozessor-Test ans Netzteil, für die Akku-Messung vom Netzteil.' }
    @{ Tab = 'TabHwTest'; Glyph = '&#xE749;'; Color = '#0E7490'; Title = 'Hardware-Test: Ergebnisse und Prüfprotokoll'; Intro = 'Jedes Ergebnis wird gespeichert und landet auf Knopfdruck in einem Prüfprotokoll als PDF.'
       Items = @('Kacheln oben|Anzahl bestandener Tests, Warnungen und Fehler sowie das Datum der letzten Prüfung. Jede Testkarte zeigt rechts oben ihr Ergebnis: Bestanden (grün), Warnung (orange), Fehler (rot) oder Nicht geprüft.', 'Dieses Gerät|Hersteller, Modell, Seriennummer, BIOS, Prozessor, Arbeitsspeicher mit allen Riegeln und belegten Steckplätzen, Datenträger, Grafik und Windows-Version - genau diese Daten stehen auch im Protokoll.', 'Prüfprotokoll als PDF|Fragt nach Prüfer, Übernehmer/Käufer, Ort und Bemerkungen (z.B. Zubehör, Kratzer) und erstellt ein PDF mit Gesamturteil, Gerätedaten, Datenträgern mit Zuverlässigkeitswerten, jedem Testergebnis mit Befund, Details und Datum sowie Unterschriftszeilen. Braucht Microsoft Edge; ohne Edge entsteht eine Webseite zum Drucken.', 'Gespeichert|Alle Ergebnisse stehen in Hardwaretest.json im Datenordner und bleiben auch nach dem Schließen erhalten - man kann also heute den Speicher und morgen den Akku testen. "Ergebnisse löschen" beginnt von vorn.', 'Bewertung|Bestanden = ohne Befund. Warnung = funktioniert, aber auffällig (z.B. Drosselung, Akku unter 80 %, einzelner Pixelfehler, langsame Blöcke). Fehler = Defekt (Speicherfehler, Lesefehler, Überhitzung, tote Tasten oder Touch-Zonen, Akku unter 60 %).')
       Tip = 'Beim Verkauf: Protokoll ausdrucken, beide Seiten unterschreiben, eine Kopie behalten. Beim Kauf: Tests vor Ort durchführen - vor allem Datenträger-Schnelltest, Arbeitsspeicher und Akku.' }
    @{ Tab = 'TabRescue'; Glyph = '&#xE88E;'; Color = '#BE123C'; Title = 'Notfall-Stick'; Intro = 'Neu in 9.0: ein bootfähiger Reparatur-Stick für die eigenen PCs - für den Tag, an dem Windows nicht mehr startet.'
       Items = @('Wofür?|Schwarzer Bildschirm, "Automatische Reparatur" in der Endlosschleife, "Bootmanager fehlt" (0xc000000f), Bluescreen beim Start oder Hänger nach einem Update: Vom Stick startet die Windows-Wiederherstellungsumgebung (WinRE) - das offizielle Reparatursystem von Microsoft - unabhängig von der kaputten Festplatte. Einmal erstellen, in die Schublade legen.', 'Reparatursystem|PC-Tools liest mit "reagentc /info" (deutsch und englisch), wo die Winre.wim dieses PCs liegt. Liegt sie auf der versteckten Wiederherstellungspartition, wird diese nur für das Kopieren kurz eingebunden und danach wieder ausgeblendet. Ist WinRE ausgeschaltet, kommt die Datei aus C:\Windows\System32\Recovery. Alternative Quelle: boot.wim aus einer Windows-ISO (Windows-Setup mit "Computerreparaturoptionen").', 'Aufbau des Sticks|FAT32-Partition (UEFI startet nur von FAT32) mit \sources\boot.wim, \boot\boot.sdi, \EFI\Boot\bootx64.efi (Start-Manager dieses PCs, von Microsoft signiert - Secure Boot kann an bleiben) und einer eigenen Startkonfiguration (BCD) mit dem Eintrag "PC-Tools Reparatursystem". Sticks über 34 GB bekommen zusätzlich eine exFAT-Partition für Sicherungen und große Dateien.', 'Reparatur-Menü|Im Reparatursystem: Problembehandlung > Erweiterte Optionen > Eingabeaufforderung > Reparatur\Reparatur.cmd. Das Menü findet das installierte Windows selbst und bietet: 1 Startdateien neu schreiben (bcdboot), 2 Systemdateien prüfen (sfc offline), 3 Komponentenspeicher reparieren (DISM offline, optional mit install.wim), 4 Datenträger prüfen (chkdsk), 5 ausstehende Updates zurücknehmen, 6 persönliche Dateien auf den Stick sichern, 7 Systemwiederherstellung, 8 Notepad als Dateimanager, 9 Treiber einspielen, B BitLocker entsperren, D Speichertreiber laden. Alles wird in "Reparatur-Protokoll.txt" auf dem Stick mitgeschrieben.', 'Weitere Inhalte|Portable PC-Tools (mit Netzwerk-Notfall und Netzwerk-Tiefenanalyse - läuft unter jedem Windows, nicht im Reparatursystem), die Toolbox und eine Treiber-Sicherung dieses PCs (\Treiber\<PC-Name>: für Neuinstallationen und für SSDs, die ohne Intel-RST/VMD-Treiber nicht sichtbar sind). Surface-Treiberpakete kommen über die Seite Microsoft Surface auf den Stick.', 'Stick prüfen|Zeigt als Checkliste, was auf einem eingesteckten Stick liegt: Reparatursystem, Startdateien, Signatur des Start-Managers, Startkonfiguration, Reparatur-Menü, PC-Tools-Version, Toolbox, Treiber, Surface-Pakete, gerettete Dateien - und ob der Stick bootfähig ist.', 'Vom Stick starten|Boot-Menü-Taste beim Einschalten (HP F9, Lenovo/Dell F12, Surface: Leiser-Taste halten + Ein/Aus) oder "Neustart: vom Stick starten" (erweiterter Start > Ein Gerät verwenden). Die Tabelle auf der Seite nennt die Tasten aller gängigen Hersteller.', 'Aktualisieren ohne Löschen|Ohne den Haken "Stick neu einrichten" werden die Dateien auf einem vorhandenen Notfall-Stick ersetzt bzw. ergänzt - z.B. nach einem großen Windows-Update, damit das Reparatursystem zur Windows-Version passt.')
       Tip = 'BitLocker-Wiederherstellungsschlüssel bereithalten (aka.ms/myrecoverykey): Im Reparatursystem ist das Windows-Laufwerk gesperrt, bis es mit Menüpunkt B entsperrt ist. Den Stick nach großen Windows-Updates einmal neu erstellen.' }
    @{ Tab = 'TabRemote'; Glyph = '&#xE8AF;'; Color = '#0891B2'; Title = 'Fernhilfe'; Intro = 'Neu in 9.0: Hilfe holen und Hilfe geben - für Familie, Kollegen und für dich als Helfer.'
       Items = @('Hilfe anfordern|Problem wählen (Internet, Drucker, langsam, Fehlermeldung, E-Mail, Programm, Betrugsverdacht, Passwort ...) und kurz beschreiben. Ein Klick schnürt ein Hilfe-Paket als ZIP: Zusammenfassung (PC, Benutzer, Modell, Seriennummer, Windows-Version, IP, freier Speicher), Zustand aus der Ampel, Netzwerk-Diagnose, Fehler-Ereignisse der letzten 48 Stunden und auf Wunsch ein Bildschirmfoto (PC-Tools blendet sich dafür kurz aus).', 'Benachrichtigung|Eine Kurzfassung geht sofort als Handy-Nachricht an den Helfer - über die Kanäle aus Meine PCs (ntfy, Home Assistant, Chat-Webhook), auch wenn die automatischen Meldungen dort aus sind. Das Paket bleibt auf dem PC; ist in Meine PCs ein gemeinsamer Ordner (NAS) eingetragen, liegt eine Kopie in dessen Unterordner "Hilfe". Ohne Kanal: "Per E-Mail an Helfer" öffnet eine fertige E-Mail und zeigt die ZIP-Datei zum Anhängen.', 'Vorlesen|PC-Name, Benutzer, IP-Adressen, Windows-Version, Gerät mit Seriennummer und vorhandene RustDesk-/TeamViewer-IDs groß zum Vorlesen oder Kopieren.', 'Fernwartung|Windows-Schnellhilfe (eingebaut; fehlt sie, geht es zum Microsoft Store), RustDesk (neueste Version von GitHub, sonst winget), TeamViewer QuickSupport und AnyDesk. Die Programme werden in den Datenordner geladen, vor jedem Start auf eine gültige digitale Signatur des Herstellers geprüft (RustDesk zusätzlich per SHA-256 gegen die GitHub-Veröffentlichung) und nur dann gestartet. Nichts wird installiert.', 'Ich helfe jemandem|Schnellhilfe unter "Hilfe leisten" oder RustDesk öffnen und eine verständliche Schritt-für-Schritt-Anleitung für den Hilfesuchenden kopieren (Schnellhilfe, RustDesk, TeamViewer, AnyDesk) - mit Telefonnummer und Warnung vor Betrugsanrufen.', 'Einstellungen|Name, Telefon und E-Mail des Helfers sowie das bevorzugte Programm. Sie stehen oben auf der Seite und in den Anleitungen. Tipp: Auf dem PC der Eltern einmal eintragen - dann reicht dort ein Klick auf "Hilfe anfordern".')
       Tip = 'Niemand von Microsoft, Bank oder Polizei ruft unaufgefordert an und will auf den PC. Codes, IDs und Passwörter nur an Menschen geben, die man selbst angerufen hat.' }
    @{ Tab = 'TabNetTools'; Glyph = '&#xE968;'; Color = '#0891B2'; Title = 'Netzwerk-Werkzeuge: Geräte im Netz und Wake-on-LAN'; Intro = 'Neu in 9.0: wer ist in meinem Netz - und PCs aus der Ferne einschalten. Nur im eigenen Netz bzw. mit Erlaubnis verwenden.'
       Items = @('Netz durchsuchen|PC-Tools schickt gleichzeitig einen Ping an alle Adressen des eigenen Netzes (das /24 des aktiven Adapters, bis 254 Adressen, ca. 10 Sekunden) und liest danach die ARP-Tabelle von Windows. So werden auch Geräte gefunden, die auf Ping nicht antworten (z.B. Windows-PCs mit Firewall, Handys im Standby) - sie stehen mit "blockt Ping" in der Liste.', 'Name, Hersteller, Antwortzeit|Der Name kommt aus dem DNS des Routers (bei der FRITZ!Box der Gerätename aus dem Heimnetz), der Hersteller aus den ersten sechs Stellen der MAC-Adresse (z.B. AVM, Apple, Raspberry Pi, Espressif für Shelly/Tasmota, Sonos, Synology). "Zufällige MAC" bedeutet: Das Gerät (meist Handy oder Tablet) verschleiert seine echte Adresse - eine Datenschutz-Funktion, kein Fehler.', 'Anschlüsse|Auf Wunsch wird bei jedem Gerät kurz geprüft, ob Web (80/443/8080), SSH (22), Windows-Freigaben (445), Remotedesktop (3389), Kamera-Stream (554), Drucker (9100), MQTT (1883) oder Home Assistant (8123) offen sind. Doppelklick öffnet die passende Weboberfläche.', 'Neu seit letztem Scan|Jeder Scan wird gespeichert. Geräte, die beim letzten Mal nicht da waren, erscheinen orange mit NEU - so fällt ein unbekanntes Gerät im WLAN sofort auf. "nur neue Geräte" filtert darauf. Eigene Namen ("Drucker Büro") werden an der MAC-Adresse gemerkt.', 'Wake-on-LAN|Geräte in die Liste übernehmen (aus dem Scan oder von Hand mit MAC-Adresse), dann "Aufwecken": PC-Tools sendet das Magic Packet als Broadcast an UDP-Port 9 und 7. Ist eine IP-Adresse hinterlegt, prüft PC-Tools anschließend bis zu 2 Minuten, ob der PC antwortet.', 'Voraussetzungen für Wake-on-LAN|Im BIOS/UEFI "Wake on LAN" einschalten, im Geräte-Manager beim Netzwerkadapter "Gerät kann den Computer aktivieren" und "Wake on Magic Packet" aktivieren, Windows-Schnellstart ausschalten. Funktioniert praktisch nur per Netzwerkkabel. Aus dem Internet geht es über den Router (FRITZ!Box: Heimnetz > Netzwerk > Gerät bearbeiten > "Computer starten").')
       Tip = 'Einmal scannen, wenn alle eigenen Geräte an sind, und die wichtigsten benennen - danach fällt jedes fremde Gerät sofort als NEU auf.' }
    @{ Tab = 'TabNetTools'; Glyph = '&#xEC4A;'; Color = '#0891B2'; Title = 'Netzwerk-Werkzeuge: Speedtest-Verlauf, DNS und WLAN-Kanäle'; Intro = 'Messen statt raten: Wie schnell ist das Internet wirklich, welcher DNS ist am schnellsten, welcher WLAN-Kanal ist frei?'
       Items = @('Speedtest-Verlauf|Jede Messung (hier mit "Jetzt messen" und auf der Seite Netzwerk) wird mit Datum, Verbindungsart (LAN oder WLAN) und Adapter gespeichert. Das Diagramm zeigt Download und Upload über die Zeit, darunter alle Messungen. Filter nach LAN/WLAN und Zeitraum; die Zusammenfassung vergleicht LAN mit WLAN.', 'Was die Werte bedeuten|Download/Upload in Mbit/s (100 Mbit/s = ca. 12 MB pro Sekunde), Ping = Reaktionszeit in Millisekunden (unter 20 ms sehr gut), Schwankung (Jitter) = wie gleichmäßig der Ping ist (wichtig für Videokonferenzen und Spiele). Fehlgeschlagene Messungen stehen rot in der Liste - so lassen sich Ausfälle belegen.', 'DNS-Vergleich|Der DNS-Server übersetzt Namen wie google.de in Adressen. PC-Tools fragt zehn bekannte Adressen je zweimal beim aktuellen DNS (meist der Router), beim Router selbst und bei Cloudflare, Google, Quad9, AdGuard und OpenDNS. Gewertet wird der Median (typischer Wert), Ausfälle zählen stark negativ. Der schnellste wird grün empfohlen.', 'DNS übernehmen|"Übernehmen" stellt den gewählten (oder schnellsten) DNS für den aktiven Adapter dieses PCs ein, die Zeile "Router" stellt wieder auf automatisch. Achtung: Mit einem externen DNS am PC funktionieren Namen aus dem Heimnetz (fritz.box, NAS) nicht mehr - besser den Anbieter im Router als Upstream-DNS eintragen, dann profitieren alle Geräte.', 'WLAN-Kanal-Planer|Alle WLAN-Sender in Reichweite (netsh wlan, jeder Access Point einzeln). 2,4 GHz: Jedes Netz ist ein Hügel über etwa 4 Kanälen, die Höhe ist die Signalstärke - überlappende Hügel stören sich. Nur die Kanäle 1, 6 und 11 überschneiden sich nicht; empfohlen wird der am wenigsten belegte davon. 5 GHz: Balken = Anzahl Sender je Kanal, * = DFS-Kanal (Radar-Erkennung).', 'Standortberechtigung|Ab Windows 11 24H2 gibt Windows die WLAN-Liste nur mit eingeschalteter Standortberechtigung heraus. PC-Tools erkennt das und bietet "Standortdienste öffnen" an.')
       Tip = 'WLAN langsamer als LAN? Erst den Kanal prüfen, dann 5 GHz nutzen - und den Router möglichst frei und zentral aufstellen.' }
    @{ Tab = 'TabNetTools'; Glyph = '&#xE839;'; Color = '#DC2626'; Title = 'Netzwerk-Werkzeuge: Router-Check'; Intro = 'Der Router ist das Tor zum Internet - ein Blick auf die wichtigsten Einstellungen, ohne Anmeldung am Router.'
       Items = @('Router und Hersteller|Adresse, Antwortzeit, MAC-Adresse und Hersteller des Routers (Standardgateway des aktiven Adapters).', 'FRITZ!Box|Modell und FRITZ!OS-Version werden ohne Kennwort aus jason_boxinfo.xml gelesen. Ab FRITZ!OS 8 grün; 7.5x orange mit Hinweis, unter System > Update nach FRITZ!OS 8 zu suchen; ältere Versionen rot. Wird für ein Modell nichts Neueres angeboten, bekommt es ggf. keine Updates mehr.', 'Weboberfläche|Ob die Router-Oberfläche per http und https erreichbar ist (Statuscode und Seitentitel). Nur http heißt: Das Router-Kennwort geht unverschlüsselt durchs Netz. Selbstsignierte Zertifikate sind bei Routern normal.', 'DHCP und DNS|Welcher DHCP-Server die Adresse vergeben hat, wann und wie lange sie gilt (Lease). Kommt DHCP nicht vom Router, gibt es einen zweiten DHCP-Server (z.B. Pi-hole). Dazu die eingestellten DNS-Server.', 'IPv6|Ob der Anschluss IPv6 liefert, mit Datenschutz-Erweiterung (wechselnde Adresse). Abgeschaltetes IPv6 am Adapter wird bemängelt.', 'UPnP-Portfreigaben|Programme und Geräte können sich per UPnP selbst Ports ins Internet öffnen. PC-Tools listet alle aktiven Freigaben - unbekannte Einträge im Router löschen und UPnP nur für Geräte erlauben, die es wirklich brauchen.')
       Tip = 'Automatische Updates im Router einschalten - das ist der wichtigste Schutz fürs ganze Heimnetz.' }
    @{ Tab = 'TabDevFile'; Glyph = '&#xE7C3;'; Color = '#9333EA'; Title = 'Geräte-Akte'; Intro = 'Neu in 9.0: alles über diesen PC an einem Ort - für Versicherung, Verkauf, Werkstatt und Inventur.'
       Items = @('Automatisch erkannt|Hersteller, Modell (bei Lenovo mit Klarnamen und Typnummer), Seriennummer, BIOS/UEFI mit Datum, Firmware (UEFI, Secure Boot, TPM), Prozessor, Arbeitsspeicher mit Modulen und Steckplätzen, Datenträger mit Typ und Zustand, Grafik, Windows-Version, Installationsdatum, Aktivierung, MAC-Adressen, Akku-Kapazität, Garantie (von der Seite BIOS-Einstellungen) und der Zustand (Ampel).', 'Kauf und Inventar|Kaufdatum, Preis, Händler, Rechnungsnummer, Inventarnummer, Standort, Besitzer/Nutzer und Notizen einmal eintragen und speichern. Aus dem Kaufdatum berechnet PC-Tools das Alter und bis wann die gesetzliche Gewährleistung (2 Jahre) läuft. Kaufdatum, Standort, Besitzer, Inventarnummer und letzte Reparatur erscheinen auch auf der Seite "Meine PCs".', 'Wartung und Reparaturen|Ein Logbuch mit Datum, Art (Wartung, Reparatur, Aufrüstung, Reinigung, Akkutausch, Garantiefall ...), Beschreibung und Kosten - mit Summe. Doppelklick bearbeitet einen Eintrag.', 'Dateien|Rechnungen, Garantiebelege und Fotos werden in den PC-Tools-Datenordner kopiert (Akte\Dateien) und lassen sich direkt öffnen. Die Originale bleiben, wo sie sind.', 'Verlauf|Akku-Kapazität, SSD-Verschleiß und -Temperatur, freier Speicher und Startzeit aus dem täglichen Verlauf als Diagramm.', 'PDF, Export und Import|"Akte als PDF" erstellt einen Bericht mit allen Daten, dem Wartungsbuch und Verlaufskurven (braucht Microsoft Edge). "Exportieren" speichert die Akte als ZIP mit allen Dateien (oder nur als JSON), "Importieren" holt sie zurück - z.B. nach einer Neuinstallation. Wartungseinträge und Dateien werden dabei ergänzt, nicht überschrieben.')
       Tip = 'Die Rechnung gleich nach dem Kauf als PDF oder Foto hinzufügen - bei einem Garantiefall oder Diebstahl ist dann alles sofort zur Hand.' }
    @{ Tab = 'TabSettings'; Glyph = '&#xE713;'; Color = '#475569'; Title = 'Einstellungen'; Intro = 'Update-Quelle, Verknüpfungen, Design und Virenschutz-Ausnahmen.'
       Items = @('Selbst-Update|Neue Versionen von PC-Tools kommen automatisch aus dem privaten GitHub-Repository (mit Prüfsummen).', 'Design|Hell, dunkel oder wie Windows.', 'Weitere PCs|Einrichtungspaket erstellen - Doppelklick auf Einrichten.cmd, fertig.') }
)
function New-ManualXaml {
    $toc = ($ManualChapters | ForEach-Object { $i = [array]::IndexOf($ManualChapters, $_)
        '<Button Style="{{StaticResource Sec}}" Tag="ManCh{0}" Padding="10,5" Margin="0,0,8,8"><StackPanel Orientation="Horizontal"><TextBlock Text="{1}" FontFamily="Segoe MDL2 Assets" Foreground="{2}" Margin="0,0,7,0" VerticalAlignment="Center"/><TextBlock Text="{3}" VerticalAlignment="Center"/></StackPanel></Button>' -f $i, $_.Glyph, $_.Color, (Esc $_.Title) }) -join ''
    $news = ($ManualNews | ForEach-Object { '<TextBlock TextWrapping="Wrap" Margin="0,2" Foreground="#FFFFFF"><Run Text="✓  " FontWeight="Bold"/><Run Text="{0}"/></TextBlock>' -f (Esc $_) }) -join ''
    $head = @"
<Border CornerRadius="18" Margin="0,0,4,18" Padding="28,22" Background="{StaticResource HeroGrad}">
  <Border.Effect><DropShadowEffect BlurRadius="26" ShadowDepth="5" Direction="270" Opacity="0.28" Color="#2A2F8F"/></Border.Effect>
  <StackPanel>
    <TextBlock Text="Neu in Version $AppVersion" Foreground="#FFFFFF" FontSize="18" FontWeight="Bold" Margin="0,0,0,6"/>
    $news
  </StackPanel>
</Border>
"@
    $tocCard = New-Card 'Inhalt' @('<TextBlock Text="Auf ein Kapitel klicken, um dorthin zu springen. &quot;Zur Seite&quot; in jedem Kapitel öffnet die Funktion direkt." Foreground="#6B7890" FontSize="12" Margin="0,0,0,8" TextWrapping="Wrap"/>', ('<WrapPanel x:Name="ManToc">{0}</WrapPanel>' -f $toc))
    $basics = New-Card 'So funktioniert PC-Tools' @(
        '<WrapPanel>',
        ((('&#xE768;|#2D7FF9|Im Hintergrund|Jede Aufgabe läuft als eigener Prozess weiter - auch wenn das Fenster zu ist. Fortschritt unten und auf der Seite Protokoll.',
          '&#xE72E;|#16A34A|Sicher|Vor Änderungen wird ein Wiederherstellungspunkt gesetzt; Downloads werden per Prüfsumme und digitaler Signatur geprüft.',
          '&#xE895;|#7C3AED|Immer aktuell|PC-Tools aktualisiert sich selbst. Neue Funktionen stehen dann oben unter "Neu in Version".',
          '&#xE8A5;|#EA580C|Nachvollziehbar|Jeder Lauf wird protokolliert (C:\ProgramData\PCPflege\Logs).') | ForEach-Object { $f = $_ -split '\|'
            '<Border Width="300" Margin="0,0,12,12" Padding="14,12" CornerRadius="10" Background="#F8FAFD" BorderBrush="#E2E7F0" BorderThickness="1"><StackPanel><StackPanel Orientation="Horizontal"><Border Width="32" Height="32" CornerRadius="8" Background="{1}" Margin="0,0,10,0"><TextBlock Text="{0}" FontFamily="Segoe MDL2 Assets" Foreground="#FFFFFF" FontSize="15" HorizontalAlignment="Center" VerticalAlignment="Center"/></Border><TextBlock Text="{2}" FontWeight="SemiBold" FontSize="14" VerticalAlignment="Center" Foreground="#1F2A44"/></StackPanel><TextBlock Text="{3}" TextWrapping="Wrap" FontSize="12.5" Foreground="#475569" Margin="0,8,0,0"/></StackPanel></Border>' -f $f[0], $f[1], (Esc $f[2]), (Esc $f[3]) }) -join ''),
        '</WrapPanel>')
    $chap = for ($i = 0; $i -lt $ManualChapters.Count; $i++) {
        $c = $ManualChapters[$i]
        $items = ($c.Items | ForEach-Object { $f = $_ -split '\|', 2
            '<Grid Margin="0,5"><Grid.ColumnDefinitions><ColumnDefinition Width="22"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions><Ellipse Width="7" Height="7" Fill="{0}" VerticalAlignment="Top" Margin="0,7,0,0" HorizontalAlignment="Left"/><TextBlock Grid.Column="1" TextWrapping="Wrap" Foreground="#1F2A44" FontSize="13"><Run Text="{1}: " FontWeight="SemiBold"/><Run Text="{2}"/></TextBlock></Grid>' -f $c.Color, (Esc $f[0]), (Esc $f[1]) }) -join ''
        $tip = if ($c.Tip) { '<Border Background="#F5F9FF" BorderBrush="#AFC4EA" BorderThickness="1" CornerRadius="8" Padding="12,8" Margin="0,8,0,0"><TextBlock TextWrapping="Wrap" Foreground="#1F2A44" FontSize="12.5"><Run Text="&#xE82F;  " FontFamily="Segoe MDL2 Assets" Foreground="#2D7FF9"/><Run Text="Tipp: " FontWeight="SemiBold"/><Run Text="{0}"/></TextBlock></Border>' -f (Esc $c.Tip) } else { '' }
@"
<Border x:Name="ManCh$i" Background="White" CornerRadius="12" Padding="20,16" Margin="0,0,4,16" BorderBrush="#E2E7F0" BorderThickness="1">
  <Border.Effect><DropShadowEffect BlurRadius="18" ShadowDepth="2" Direction="270" Opacity="0.07" Color="Black"/></Border.Effect>
  <Grid><Grid.ColumnDefinitions><ColumnDefinition Width="Auto"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>
    <Border Width="52" Height="52" CornerRadius="14" Background="$($c.Color)" VerticalAlignment="Top" Margin="0,0,18,0"><TextBlock Text="$($c.Glyph)" FontFamily="Segoe MDL2 Assets" FontSize="24" Foreground="#FFFFFF" HorizontalAlignment="Center" VerticalAlignment="Center"/></Border>
    <StackPanel Grid.Column="1">
      <Grid><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
        <StackPanel><TextBlock Text="$(Esc $c.Title)" FontSize="19" FontWeight="SemiBold" Foreground="#1F2A44"/><TextBlock Text="$(Esc $c.Intro)" Foreground="#6B7890" FontSize="13" TextWrapping="Wrap" Margin="0,2,0,6"/></StackPanel>
        <Button Grid.Column="1" Content="Zur Seite  &#x2192;" Tag="$($c.Tab)" Style="{StaticResource Sec}" Padding="12,5" Margin="10,0,0,0" VerticalAlignment="Top"/>
      </Grid>
      $items
      $tip
    </StackPanel>
  </Grid>
</Border>
"@
    }
    return $head + $tocCard + $basics + ($chap -join '')
}
$pageManual = New-Page 'Handbuch' ('Alle Funktionen von PC-Tools {0} verständlich erklärt - mit Tipps aus der Praxis. Das Handbuch wird mit jeder neuen Version ergänzt.' -f $AppVersion) ('<StackPanel x:Name="ManRoot">' + (New-ManualXaml) + '</StackPanel>')

# ---------------------------------------------------------------- Meine PCs, Änderungen, Gerätezustand
$pageFleet = New-Page 'Meine PCs' 'Alle PCs mit PC-Tools auf einen Blick: Jeder PC legt nach jeder Pflege (und beim Öffnen von PC-Tools) seinen Zustand in einem gemeinsamen Ordner ab - z.B. auf dem NAS. Dazu Benachrichtigungen aufs Handy, wenn etwas rot wird.' ((New-Card 'Übersicht aller PCs' @(
        '<TextBlock x:Name="FleetInfo" Text="" FontWeight="SemiBold" Foreground="#1F2A44" Margin="0,0,0,8" TextWrapping="Wrap"/>',
        '<WrapPanel x:Name="FleetTiles"/>',
        (New-White (New-DataGrid 'FleetGrid' @('PC|Computer|130', 'Zustand|StateText|75', 'Modell|Model|*', 'Standort|AkStandort|150', 'Besitzer / Nutzer|AkBesitzer|140', 'Inventar-Nr.|AkInv|105', 'Kaufdatum|AkKauf|95|AkKaufSort', 'Letzte Reparatur|AkRep|*', 'Stand|AgeText|105') 'Height="210"') 'Margin="0,4,0,10"'),
        '<WrapPanel Margin="0,4,0,0"><Button x:Name="BtnFleetRefresh" Content="Aktualisieren" Style="{StaticResource Sec}"/><Button x:Name="BtnFleetRdp" Content="Remotedesktop zum gewählten PC" Style="{StaticResource Sec}"/><Button x:Name="BtnFleetOpen" Content="Ordner öffnen" Style="{StaticResource Sec}"/><Button x:Name="BtnFleetRemove" Content="Gewählten PC aus der Liste entfernen" Style="{StaticResource Sec}"/></WrapPanel>',
        '<TextBlock x:Name="FleetDetail" Text="Einen PC anklicken für Details." Foreground="#475569" FontSize="12.5" Margin="0,8,0,0" TextWrapping="Wrap"/>')) +
    (New-Card 'Gemeinsamer Statusordner' @(
        (New-CheckRow 'Fleet_Enabled' 'Zustand dieses PCs im gemeinsamen Ordner ablegen' 'Auf jedem PC mit demselben Ordner einschalten. Für NAS-Ordner wird der NAS-Zugang aus der Datensicherung benutzt (auch bei der automatischen Pflege als SYSTEM).'),
        (New-TextRow 'Fleet_Dir' 'Ordner' 'z.B. \\NAS\PC-Tools\Status - nach dem Ändern unten "Einstellungen speichern".' 'BtnFleetDir'))) +
    (New-Card 'Benachrichtigungen aufs Handy' @(
        (New-CheckRow 'Notify_Enabled' 'Benachrichtigungen senden' 'Nach jeder Pflege und bei der automatischen Pflege. Jede Meldung kommt nur einmal, bis sich der Zustand ändert.'),
        (New-TextRow 'Notify_Ntfy' 'ntfy (App ntfy.sh, kostenlos)' 'Adresse des Themas, z.B. https://ntfy.sh/pcpflege-rene-8x3k (eigener Name = eigener Kanal, in der ntfy-App abonnieren). Eigener ntfy-Server geht auch.'),
        (New-TextRow 'Notify_HaWebhook' 'Home Assistant Webhook' 'z.B. https://ha.example.de/api/webhook/pcpflege - in HA eine Automation mit Auslöser Webhook anlegen (Felder title, message, level, computer).'),
        (New-TextRow 'Notify_ChatWebhook' 'Mattermost / Slack / Discord (Incoming Webhook)' 'Adresse des eingehenden Webhooks aus dem Chat.'),
        '<TextBlock Text="Melden bei" FontWeight="SemiBold" Margin="0,8,0,4"/>',
        '<WrapPanel><CheckBox x:Name="Notify_OnRed" Content="Ampel rot" Margin="0,0,20,6"/><CheckBox x:Name="Notify_OnRecover" Content="wieder grün" Margin="0,0,20,6"/><CheckBox x:Name="Notify_OnWarn" Content="Pflege mit Warnungen" Margin="0,0,20,6"/><CheckBox x:Name="Notify_OnBackup" Content="Datensicherung fehlgeschlagen" Margin="0,0,20,6"/><CheckBox x:Name="Notify_OnBluescreen" Content="Bluescreen" Margin="0,0,20,6"/></WrapPanel>',
        '<WrapPanel Margin="0,6,0,0"><Button x:Name="BtnNotifyTest" Content="Testnachricht senden" Style="{StaticResource Sec}"/></WrapPanel>',
        '<TextBlock x:Name="NotifyInfo" Text="" Foreground="#475569" FontSize="12" TextWrapping="Wrap"/>')))

$pageChanges = New-Page 'Was hat sich geändert?' 'Vor jedem Update-, Treiber- und Installationslauf hält PC-Tools den Stand fest (Treiber, Programme, Windows-Updates). Macht danach etwas Ärger, zeigt diese Seite genau, was sich geändert hat - und wie man es zurückdreht.' ((New-Card 'Vergleich' @(
        '<WrapPanel><TextBlock Text="Vorher:" VerticalAlignment="Center" Margin="0,0,8,8"/><ComboBox x:Name="ChgFrom" Width="360" Margin="0,0,14,8"/><TextBlock Text="Nachher:" VerticalAlignment="Center" Margin="0,0,8,8"/><ComboBox x:Name="ChgTo" Width="300" Margin="0,0,14,8"/><Button x:Name="BtnChgCompare" Content="Vergleichen" Padding="14,6"/><Button x:Name="BtnChgSnap" Content="Stand jetzt festhalten" Style="{StaticResource Sec}" Padding="14,6"/></WrapPanel>',
        '<TextBlock x:Name="ChgInfo" Text="" FontWeight="SemiBold" Foreground="#1F2A44" Margin="0,4,0,6" TextWrapping="Wrap"/>',
        ('<WrapPanel>{0}</WrapPanel>' -f (New-Combo 'ChgFilter' @('Alle Änderungen', 'Nur Treiber', 'Nur Programme', 'Nur Windows-Updates') 240)),
        (New-White (New-DataGrid 'ChgGrid' @('Art|Kind|130', 'Name|Name|*', 'Vorher|Before|170', 'Nachher|After|170', 'Änderung|Change|110') 'Height="420"')),
        '<WrapPanel Margin="0,8,0,0"><Button x:Name="BtnChgRollback" Content="Zurückdrehen ..." /><Button x:Name="BtnChgDevMgr" Content="Geräte-Manager" Style="{StaticResource Sec}"/><Button x:Name="BtnChgRestore" Content="Wiederherstellungspunkte" Style="{StaticResource Sec}"/></WrapPanel>',
        '<TextBlock Text="Zurückdrehen: Treiber öffnet die Geräte-Eigenschaften (dort &quot;Vorheriger Treiber&quot;) bzw. installiert den Treiber aus der letzten Treiber-Sicherung; Programme öffnen die Deinstallation; Windows-Updates werden deinstalliert." Foreground="#6B7890" FontSize="12" TextWrapping="Wrap" Margin="0,6,0,0"/>')))

$pageHealth = New-Page 'Gerätezustand und Startzeit' 'Wie sich Akku, SSD, Speicherplatz und Startzeit über die Wochen entwickeln - so kündigt sich ein Defekt lange vorher an. Einmal täglich wird ein Messpunkt gespeichert.' ((New-Card 'Verlauf' @(
        '<TextBlock x:Name="HistInfo" Text="" Foreground="#475569" FontSize="12.5" TextWrapping="Wrap" Margin="0,0,0,8"/>',
        '<WrapPanel x:Name="HistCharts"/>')) +
    (New-Card 'Startzeit von Windows' @(
        '<TextBlock x:Name="BootInfo" Text="Wird geladen ..." FontWeight="SemiBold" Foreground="#1F2A44" TextWrapping="Wrap" Margin="0,0,0,8"/>',
        '<Border Height="150" Background="#F8FAFD" CornerRadius="8" BorderBrush="#E2E7F0" BorderThickness="1" Padding="8"><Canvas x:Name="BootChart" ClipToBounds="True"/></Border>',
        '<TextBlock Text="Was den Start bremst (laut Windows-Leistungsdiagnose)" FontWeight="SemiBold" Margin="0,12,0,4"/>',
        (New-White (New-DataGrid 'BootSlow' @('Art|Kind|110', 'Name|Name|*', 'Bremst im Schnitt|AvgText|150|Avg', 'Wie oft|Count|80', 'Zuletzt|Last|100') 'Height="230"')),
        '<WrapPanel Margin="0,8,0,0"><Button x:Name="BtnBootDelay" Content="Gewählten Dienst verzögert starten" Style="{StaticResource Sec}"/><Button x:Name="BtnBootAutostart" Content="Autostart aufräumen" Style="{StaticResource Sec}"/><Button x:Name="BtnBootFast" Content="Schnellstart-Einstellung" Style="{StaticResource Sec}"/><Button x:Name="BtnBootTimeRefresh" Content="Neu einlesen" Style="{StaticResource Sec}"/></WrapPanel>')))

# ---------------------------------------------------------------- Apps entfernen, Datenschutz, Netzwerk, Speicherplatz
$pageDebloat = New-Page 'Apps entfernen' 'Vorinstallierte Werbe-Apps, Spiele, Probeversionen und Microsoft-Extras mit einem Klick loswerden. Neue Benutzerkonten bekommen sie auf Wunsch auch nicht mehr. Nützliche Hersteller-Apps (Vantage, Support Assistant) sind nie vorausgewählt.' ((New-Card 'Schnellwahl' @(
        '<WrapPanel><Button x:Name="BtnBloat1" Content="Vorsichtig: Werbung und Spiele" Style="{StaticResource Sec}"/><Button x:Name="BtnBloat2" Content="Empfohlen: + Microsoft-Extras"/><Button x:Name="BtnBloat3" Content="Radikal: + Xbox, Smartphone-Link, Outlook neu ..." Style="{StaticResource Sec}"/><Button x:Name="BtnBloatNone" Content="Auswahl leeren" Style="{StaticResource Sec}"/></WrapPanel>',
        '<CheckBox x:Name="BloatProv" Content="Auch für neue Benutzerkonten entfernen (vorinstallierte Pakete)" IsChecked="True" Margin="0,4,0,4"/>',
        '<TextBlock x:Name="BloatInfo" Text="Wird eingelesen ..." FontWeight="SemiBold" Foreground="#1F2A44" Margin="0,4,0,6" TextWrapping="Wrap"/>',
        '<StackPanel x:Name="BloatList"/>',
        '<WrapPanel Margin="0,8,0,0"><Button x:Name="BtnBloatRun" Content="Ausgewählte entfernen"/><Button x:Name="BtnBloatRefresh" Content="Neu einlesen" Style="{StaticResource Sec}"/></WrapPanel>')) +
    (New-Card 'Bereits entfernt - zurückholen' @(
        '<TextBlock Text="Versehentlich entfernt? Die App wird im Microsoft Store geöffnet und lässt sich dort mit einem Klick wieder installieren." Foreground="#6B7890" FontSize="12" TextWrapping="Wrap" Margin="0,0,0,6"/>',
        (New-White (New-DataGrid 'BloatDone' @('App|Id|*', 'Entfernt am|Time|160') 'Height="160"')),
        '<WrapPanel Margin="0,8,0,0"><Button x:Name="BtnBloatRestore" Content="Im Store wiederherstellen" Style="{StaticResource Sec}"/></WrapPanel>')))

$pagePrivacy = New-Page 'Datenschutz' 'Was Windows über dich sammelt und welche Programme Kamera, Mikrofon, Standort und mehr benutzen dürfen - mit Datenschutzwert, einzeln schaltbar und "zuletzt benutzt" pro App.' ((New-Card 'Datenschutzwert' @(
        '<Grid><Grid.ColumnDefinitions><ColumnDefinition Width="Auto"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>',
        '<Border x:Name="PrivRing" Width="96" Height="96" CornerRadius="48" BorderThickness="7" BorderBrush="#2D7FF9" Margin="0,0,18,0"><StackPanel VerticalAlignment="Center"><TextBlock x:Name="PrivScore" Text="-" FontSize="30" FontWeight="Bold" HorizontalAlignment="Center" Foreground="#1F2A44"/><TextBlock Text="von 100" FontSize="11" HorizontalAlignment="Center" Foreground="#6B7890"/></StackPanel></Border>',
        '<StackPanel Grid.Column="1" VerticalAlignment="Center"><TextBlock x:Name="PrivScoreText" Text="" FontSize="16" FontWeight="SemiBold" Foreground="#1F2A44" TextWrapping="Wrap"/><WrapPanel Margin="0,8,0,0"><Button x:Name="BtnPrivAll" Content="Alles datensparsam einstellen"/><Button x:Name="BtnPrivApply" Content="Auswahl übernehmen" Style="{StaticResource Sec}"/><Button x:Name="BtnPrivSettings" Content="Windows-Datenschutz öffnen" Style="{StaticResource Sec}"/></WrapPanel></StackPanel></Grid>')) +
    (New-Card 'Einstellungen' @('<WrapPanel x:Name="PrivList"/>')) +
    (New-Card 'App-Berechtigungen' @(
        '<TextBlock Text="Welche App darf was - und wann wurde es zuletzt benutzt. &quot;GERADE AKTIV&quot; heißt: Die App greift in diesem Moment zu (z.B. Mikrofon in einer Videokonferenz)." Foreground="#6B7890" FontSize="12" TextWrapping="Wrap" Margin="0,0,0,6"/>',
        ('<WrapPanel>{0}{1}</WrapPanel>' -f (New-Combo 'PrivCap' @('Alle Berechtigungen', 'Kamera', 'Mikrofon', 'Standort', 'Kontakte', 'Kalender', 'Bildschirmaufnahme', 'Telefonate', 'Funk (Bluetooth/WLAN)', 'Dokumente', 'Bilder', 'Benachrichtigungen lesen') 260), (New-Filter 'PrivSearch' 260)),
        (New-White (New-DataGrid 'PrivGrid' @('Berechtigung|CapDe|170', 'App|App|*', 'Erlaubt|Allowed|80', 'Zuletzt benutzt|Last|170') 'Height="360"')),
        '<WrapPanel Margin="0,8,0,0"><Button x:Name="BtnPrivAllow" Content="Erlauben" Style="{StaticResource Sec}"/><Button x:Name="BtnPrivDeny" Content="Verbieten" Style="{StaticResource Sec}"/><Button x:Name="BtnPrivCapOff" Content="Gewählte Berechtigung für alle Apps aus" Style="{StaticResource Sec}"/><Button x:Name="BtnPrivCapOn" Content="... für alle Apps an" Style="{StaticResource Sec}"/><Button x:Name="BtnPrivRefresh" Content="Neu einlesen" Style="{StaticResource Sec}"/></WrapPanel>')))

$pageNet = New-Page 'Netzwerk' 'Verbindung prüfen und verbessern: Geschwindigkeit, WLAN-Empfang und Kanäle, DNS-Server wechseln, sehen welche Programme ins Internet gehen, gespeicherte WLAN-Kennwörter und Diagnose-Werkzeuge.' ((New-Card 'Verbindung' @(
        '<TextBlock x:Name="NetInfo" Text="Wird geladen ..." Foreground="#1F2A44" TextWrapping="Wrap"/>',
        '<WrapPanel Margin="0,8,0,0"><Button x:Name="BtnNetRefresh" Content="Neu einlesen" Style="{StaticResource Sec}"/><Button x:Name="BtnNetSettings" Content="Netzwerkeinstellungen" Style="{StaticResource Sec}"/><Button x:Name="BtnNetRepair" Content="Internet reparieren ..." Style="{StaticResource Sec}"/></WrapPanel>')) +
    (New-Card 'Geschwindigkeitstest' @(
        '<Grid><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="*"/><ColumnDefinition Width="*"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>',
        '<StackPanel><TextBlock Text="Download" Foreground="#6B7890"/><TextBlock x:Name="SpDown" Text="-" FontSize="30" FontWeight="Bold" Foreground="#2D7FF9"/><TextBlock Text="MBit/s" Foreground="#6B7890"/></StackPanel>',
        '<StackPanel Grid.Column="1"><TextBlock Text="Upload" Foreground="#6B7890"/><TextBlock x:Name="SpUp" Text="-" FontSize="30" FontWeight="Bold" Foreground="#7C3AED"/><TextBlock Text="MBit/s" Foreground="#6B7890"/></StackPanel>',
        '<StackPanel Grid.Column="2"><TextBlock Text="Ping" Foreground="#6B7890"/><TextBlock x:Name="SpPing" Text="-" FontSize="30" FontWeight="Bold" Foreground="#16A34A"/><TextBlock Text="ms" Foreground="#6B7890"/></StackPanel>',
        '<StackPanel Grid.Column="3"><TextBlock Text="Schwankung" Foreground="#6B7890"/><TextBlock x:Name="SpJitter" Text="-" FontSize="30" FontWeight="Bold" Foreground="#EA580C"/><TextBlock Text="ms" Foreground="#6B7890"/></StackPanel></Grid>',
        '<TextBlock x:Name="SpInfo" Text="Misst über Cloudflare (50 MB Download, 10 MB Upload)." Foreground="#6B7890" FontSize="12" Margin="0,8,0,6" TextWrapping="Wrap"/>',
        '<WrapPanel><Button x:Name="BtnSpeed" Content="Test starten"/></WrapPanel>')) +
    (New-Card 'DNS-Server' @(
        '<TextBlock Text="Der DNS-Server übersetzt Namen wie google.de in Adressen. Ein schneller oder filternder DNS macht das Surfen flotter und sperrt auf Wunsch Schadseiten oder Werbung - für alle Programme." Foreground="#6B7890" FontSize="12" TextWrapping="Wrap" Margin="0,0,0,6"/>',
        ('<WrapPanel>{0}<TextBox x:Name="DnsCustom" Width="260" Padding="4,3" Margin="0,0,10,8" ToolTip="Eigene DNS-Server, mit Komma getrennt"/><Button x:Name="BtnDnsApply" Content="Übernehmen" Padding="14,6"/></WrapPanel>' -f (New-Combo 'DnsChoice' @($DnsProviders.Keys + @('Eigene (rechts eintragen)')) 420)))) +
    (New-Card 'WLAN in der Umgebung' @(
        '<TextBlock x:Name="WifiAdvice" Text="" Foreground="#1F2A44" FontWeight="SemiBold" TextWrapping="Wrap" Margin="0,0,0,6"/>',
        (New-White (New-DataGrid 'WifiGrid' @('Netz|Ssid|*', 'Signal|SignalText|80|Signal', 'Kanal|Channel|70', 'Band|Band|100', 'Sicherheit|Auth|170', 'Sender|Count|70') 'Height="220"')),
        '<WrapPanel Margin="0,8,0,0"><Button x:Name="BtnWifiScan" Content="Suchen" Style="{StaticResource Sec}"/></WrapPanel>')) +
    (New-Card 'Welche Programme gehen ins Internet?' @(
        (New-White (New-DataGrid 'ConnGrid' @('Programm|Program|200', 'Gegenstelle|Remote|*', 'Name|Host|260', 'Port|Port|70') 'Height="260"')),
        '<WrapPanel Margin="0,8,0,0"><Button x:Name="BtnConnRefresh" Content="Aktualisieren" Style="{StaticResource Sec}"/><Button x:Name="BtnConnResolve" Content="Namen auflösen" Style="{StaticResource Sec}"/><Button x:Name="BtnConnBlock" Content="Gewähltes Programm in der Firewall sperren" Style="{StaticResource Sec}"/></WrapPanel>')) +
    (New-Card 'Gespeicherte WLAN-Kennwörter' @(
        (New-White (New-DataGrid 'WpwGrid' @('WLAN|Ssid|*', 'Kennwort|Show|260', 'Sicherheit|Auth|200') 'Height="200"')),
        '<WrapPanel Margin="0,8,0,0"><Button x:Name="BtnWpwLoad" Content="Anzeigen" Style="{StaticResource Sec}"/><Button x:Name="BtnWpwCopy" Content="Kennwort kopieren" Style="{StaticResource Sec}"/><Button x:Name="BtnWpwForget" Content="Netz vergessen" Style="{StaticResource Sec}"/></WrapPanel>')) +
    (New-Card 'Diagnose' @(
        '<WrapPanel><TextBox x:Name="NetHost" Width="260" Text="google.de" Padding="4,3" Margin="0,0,10,8"/><Button x:Name="BtnNetPing" Content="Ping" Style="{StaticResource Sec}"/><Button x:Name="BtnNetTrace" Content="Route verfolgen" Style="{StaticResource Sec}"/><Button x:Name="BtnNetNs" Content="DNS-Abfrage" Style="{StaticResource Sec}"/><Button x:Name="BtnNetPort" Content="Port 443 prüfen" Style="{StaticResource Sec}"/></WrapPanel>',
        '<TextBox x:Name="NetOut" Height="180" IsReadOnly="True" FontFamily="Consolas" FontSize="12" VerticalScrollBarVisibility="Auto" Padding="6" TextWrapping="NoWrap" HorizontalScrollBarVisibility="Auto"/>')))

$pageSpace = New-Page 'Speicherplatz' 'Was belegt die Festplatte? Kachelansicht aller Ordner (je größer, desto mehr Platz), größte Dateien, alte Downloads und doppelte Dateien - mit Löschen in den Papierkorb.' ((New-Card 'Analyse' @(
        '<WrapPanel><TextBlock Text="Ordner:" VerticalAlignment="Center" Margin="0,0,8,8"/><TextBox x:Name="SpcRoot" Width="360" Padding="4,3" Margin="0,0,8,8"/><Button x:Name="BtnSpcBrowse" Content="..." Style="{StaticResource Sec}" Padding="12,5"/><Button x:Name="BtnSpcScan" Content="Analysieren" Padding="14,6"/><Button x:Name="BtnSpcUp" Content="Eine Ebene höher" Style="{StaticResource Sec}" Padding="12,5"/></WrapPanel>',
        '<TextBlock x:Name="SpcInfo" Text="Laufwerk oder Ordner wählen und analysieren - bei großen Laufwerken dauert das 1-3 Minuten." FontWeight="SemiBold" Foreground="#1F2A44" Margin="0,2,0,8" TextWrapping="Wrap"/>',
        '<Border Height="430" CornerRadius="8" BorderBrush="#E2E7F0" BorderThickness="1" Background="#F8FAFD" ClipToBounds="True"><Canvas x:Name="SpcMap"/></Border>',
        '<TextBlock Text="Klick auf eine Kachel öffnet den Ordner in der Ansicht, Rechtsklick zeigt ihn im Explorer." Foreground="#6B7890" FontSize="12" Margin="0,6,0,0"/>')) +
    (New-Card 'Größte Dateien' @(
        ('<WrapPanel>{0}</WrapPanel>' -f (New-Combo 'SpcFilesMode' @('Größte Dateien', 'Alte große Downloads (über 90 Tage, ab 50 MB)', 'Videos', 'Installationsdateien und Archive (.exe .msi .iso .zip)') 380)),
        (New-White (New-DataGrid 'SpcFiles' @('Datei|Name|*', 'Größe|SizeText|100|Size', 'Geändert|Date|110|DateSort', 'Ordner|Dir|*') 'Height="300" SelectionMode="Extended"')),
        '<WrapPanel Margin="0,8,0,0"><Button x:Name="BtnSpcDelete" Content="Ausgewählte in den Papierkorb" Style="{StaticResource Sec}"/><Button x:Name="BtnSpcShow" Content="Im Explorer zeigen" Style="{StaticResource Sec}"/></WrapPanel>')) +
    (New-Card 'Doppelte Dateien' @(
        '<TextBlock Text="Sucht Dateien ab 1 MB mit genau gleichem Inhalt (Prüfsumme). Von jeder Gruppe bleibt die älteste stehen, die anderen sind zum Löschen vorausgewählt." Foreground="#6B7890" FontSize="12" TextWrapping="Wrap" Margin="0,0,0,6"/>',
        '<TextBlock x:Name="DupInfo" Text="" FontWeight="SemiBold" Foreground="#1F2A44" Margin="0,0,0,6"/>',
        (New-White (New-DataGrid 'DupGrid' @('Gruppe|Group|70', 'Datei|Name|*', 'Größe|SizeText|100', 'Geändert|Date|110', 'Ordner|Dir|*') 'Height="300" SelectionMode="Extended"')),
        '<WrapPanel Margin="0,8,0,0"><Button x:Name="BtnDupScan" Content="Im gewählten Ordner suchen"/><Button x:Name="BtnDupSelect" Content="Kopien auswählen (Original bleibt)" Style="{StaticResource Sec}"/><Button x:Name="BtnDupDelete" Content="Ausgewählte in den Papierkorb" Style="{StaticResource Sec}"/></WrapPanel>')))

$pageBios = New-Page 'BIOS / UEFI' 'Firmware-Einstellungen direkt aus Windows lesen und ändern - für Lenovo (ThinkPad, ThinkCentre, ThinkStation), HP (EliteBook, ProBook, Z-Workstation ...) und Dell (Latitude, OptiPlex, Precision ...). Andere Marken: Infos, Neustart ins BIOS und Tastenkürzel.' ((New-Card 'Firmware dieses PCs' @(
        (New-InfoRow 'Gerät' 'BiosDevice'), (New-InfoRow 'BIOS-Version' 'BiosVer'), (New-InfoRow 'Firmware-Modus' 'BiosMode'), (New-InfoRow 'Secure Boot / TPM' 'BiosSec'),
        (New-InfoRow 'Schnittstelle in Windows' 'BiosIface'), (New-InfoRow 'BIOS-Kennwörter' 'BiosPwState'),
        '<Border Background="#F5F9FF" BorderBrush="#AFC4EA" BorderThickness="1" CornerRadius="8" Padding="12,8" Margin="0,8,0,8"><TextBlock x:Name="BiosHint" TextWrapping="Wrap" Foreground="#1F2A44" FontSize="12.5" Text=""/></Border>',
        '<WrapPanel><Button x:Name="BtnBiosReboot" Content="Jetzt neu starten ins BIOS/UEFI"/><Button x:Name="BtnBiosUpdate" Content="BIOS aktualisieren (Treiber-Seite)" Style="{StaticResource Sec}"/><Button x:Name="BtnBiosSupport" Content="Support-Seite des Herstellers" Style="{StaticResource Sec}"/><Button x:Name="BtnBiosSerial" Content="Seriennummer kopieren" Style="{StaticResource Sec}"/><Button x:Name="BtnBiosReload" Content="Neu einlesen" Style="{StaticResource Sec}"/></WrapPanel>')) +
    (New-Card 'Schnellschalter nach Thema' @(
        '<TextBlock Text="Die wichtigsten Einstellungen, sortiert nach Thema. Angezeigt wird nur, was dein Modell wirklich im BIOS hat. Ändern, dann unten &quot;Änderungen übernehmen&quot; - wirkt nach dem nächsten Neustart." Foreground="#6B7890" FontSize="12" TextWrapping="Wrap" Margin="0,0,0,8"/>',
        '<StackPanel x:Name="BiosQuick"/>')) +
    (New-Card 'Alle BIOS-Einstellungen' @(
        '<Grid Margin="0,0,0,8"><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="230"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions><TextBox x:Name="BiosSearch" Padding="4,4" Margin="0,0,8,0" ToolTip="Suchen, z.B. wake, usb, boot, adapter"/><ComboBox x:Name="BiosCat" Grid.Column="1" SelectedIndex="0" Margin="0,0,8,0"/><CheckBox x:Name="BiosChangedOnly" Grid.Column="2" Content="Nur vorgemerkte" VerticalAlignment="Center"/></Grid>',
        (New-White (New-DataGrid 'BiosGrid' @('Thema|Cat|130', 'Einstellung|Label|260', 'Aktuell|Current|170', 'Neu|Pending|140', 'Mögliche Werte|OptText|*') 'Height="330"')),
        '<Grid Margin="0,10,0,0"><Grid.ColumnDefinitions><ColumnDefinition Width="Auto"/><ColumnDefinition Width="300"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions><TextBlock x:Name="BiosSelName" Text="Einstellung wählen:" VerticalAlignment="Center" Margin="0,0,10,0" FontWeight="SemiBold" MaxWidth="320" TextTrimming="CharacterEllipsis"/><ComboBox x:Name="BiosSelValue" Grid.Column="1" IsEditable="True" Margin="0,0,10,0"/><WrapPanel Grid.Column="2"><Button x:Name="BtnBiosMark" Content="Vormerken" Style="{StaticResource Sec}" Margin="0,0,8,0"/><Button x:Name="BtnBiosUnmark" Content="Vormerkung entfernen" Style="{StaticResource Sec}" Margin="0,0,8,0"/><Button x:Name="BtnBiosUnmarkAll" Content="Alle Vormerkungen verwerfen" Style="{StaticResource Sec}" Margin="0"/></WrapPanel></Grid>',
        '<TextBlock x:Name="BiosSelInfo" Text="" Foreground="#6B7890" FontSize="12" TextWrapping="Wrap" Margin="0,6,0,0"/>')) +
    (New-Card 'Übernehmen, sichern, zurücksetzen' @(
        '<TextBlock x:Name="BiosPendingInfo" Text="Keine Änderungen vorgemerkt." FontWeight="SemiBold" Foreground="#1F2A44" Margin="0,0,0,8" TextWrapping="Wrap"/>',
        '<WrapPanel><TextBlock Text="BIOS-Administrator-Kennwort (falls gesetzt):" VerticalAlignment="Center" Margin="0,0,8,8"/><PasswordBox x:Name="BiosPwd" Width="200" Padding="4,3" Margin="0,0,10,8"/><Button x:Name="BtnBiosApplyAll" Content="Änderungen übernehmen"/><CheckBox x:Name="BiosRebootAfter" Content="danach ins BIOS neu starten (zum Kontrollieren)" VerticalAlignment="Center" Margin="0,0,0,8"/></WrapPanel>',
        '<WrapPanel Margin="0,4,0,0"><Button x:Name="BtnBiosBackup" Content="Alle Einstellungen sichern (Datei) ..." Style="{StaticResource Sec}"/><Button x:Name="BtnBiosRestore" Content="Aus Sicherung vormerken ..." Style="{StaticResource Sec}"/><Button x:Name="BtnBiosCsv" Content="Liste als CSV" Style="{StaticResource Sec}"/><Button x:Name="BtnBiosDefaults" Content="Werkseinstellungen laden (Lenovo) ..." Style="{StaticResource Sec}"/></WrapPanel>',
        '<TextBlock Text="Hinweise: Änderungen werden erst beim nächsten Neustart aktiv. Sicherheitsrelevante Einstellungen (Secure Boot, TPM, Virtualisierung) fragt das BIOS beim Start teils noch einmal ab - dann am Bildschirm bestätigen (meist F10 oder Enter). Ohne Administrator-Kennwort lassen sich manche Einstellungen nicht ändern. BitLocker: vor Änderungen an Secure Boot/TPM den Wiederherstellungsschlüssel bereithalten (Seite Sicherheit)." Foreground="#6B7890" FontSize="12" TextWrapping="Wrap" Margin="0,8,0,0"/>')))
$pageLic = New-Page 'Lizenzen' 'Alle Lizenzen dieses PCs an einem Ort: Windows-Schlüssel (auch aus dem BIOS), Office, bekannte Programme mit Hinweis, wie die Lizenz umzieht - und ein verschlüsselter Lizenz-Tresor, der sich mit Kennwort auf den neuen PC übertragen lässt.' ((New-Card 'Windows' @(
        (New-InfoRow 'Windows' 'LicWinName'), (New-InfoRow 'Aktivierung' 'LicWinStatus'), (New-InfoRow 'Lizenzart' 'LicWinKind'),
        (New-InfoRow 'Installierter Schlüssel' 'LicWinKey'), (New-InfoRow 'Schlüssel im BIOS/UEFI' 'LicWinFw'), (New-InfoRow 'Produkt-ID' 'LicWinPid'),
        '<Border Background="#F5F9FF" BorderBrush="#AFC4EA" BorderThickness="1" CornerRadius="8" Padding="12,8" Margin="0,8,0,8"><TextBlock x:Name="LicWinAdvice" TextWrapping="Wrap" Foreground="#1F2A44" FontSize="12.5" Text=""/></Border>',
        '<WrapPanel><Button x:Name="BtnLicCopyKey" Content="Schlüssel kopieren" Style="{StaticResource Sec}"/><Button x:Name="BtnLicToVault" Content="In den Tresor übernehmen" Style="{StaticResource Sec}"/><Button x:Name="BtnLicActivation" Content="Aktivierung / Problembehandlung" Style="{StaticResource Sec}"/><Button x:Name="BtnLicAccount" Content="Mit Microsoft-Konto verknüpfen" Style="{StaticResource Sec}"/></WrapPanel>',
        '<Expander Header="Übertragen: Lizenz hier lösen oder neuen Schlüssel eingeben" Margin="0,6,0,0"><StackPanel Margin="0,6,0,0">',
        '<TextBlock Text="Nur für Einzelhandels-Lizenzen (Retail): erst auf dem alten PC lösen, dann auf dem neuen eingeben. Ein OEM-Schlüssel (vorinstalliert) gehört zum Gerät und darf nicht übertragen werden." Foreground="#6B7890" FontSize="12" TextWrapping="Wrap" Margin="0,0,0,6"/>',
        '<WrapPanel><Button x:Name="BtnLicRelease" Content="Lizenz von diesem PC lösen ..." Style="{StaticResource Sec}"/><TextBox x:Name="LicNewKey" Width="300" Padding="4,3" Margin="0,0,10,8" ToolTip="XXXXX-XXXXX-XXXXX-XXXXX-XXXXX"/><Button x:Name="BtnLicActivate" Content="Schlüssel eingeben und aktivieren" Style="{StaticResource Sec}"/></WrapPanel>',
        '<TextBlock x:Name="LicSlmgrOut" Text="" FontFamily="Consolas" FontSize="12" Foreground="#475569" TextWrapping="Wrap"/>',
        '</StackPanel></Expander>')) +
    (New-Card 'Office' @(
        (New-White (New-DataGrid 'LicOffGrid' @('Produkt|Product|260', 'Art|Type|200', 'Schlüssel / Konto|Key|240', 'Status|Status|110', 'Umzug|Transfer|*') 'Height="140"')),
        '<WrapPanel Margin="0,8,0,0"><Button x:Name="BtnLicOffRemove" Content="Gewählte Office-Lizenz hier entfernen ..." Style="{StaticResource Sec}"/><Button x:Name="BtnLicOffAccount" Content="Microsoft-Konto: Installationen verwalten" Style="{StaticResource Sec}"/></WrapPanel>')) +
    (New-Card 'Weitere Programme' @(
        '<TextBlock Text="Erkannte Programme mit Lizenz - und wie sie auf den neuen PC kommen. Lizenzdateien lassen sich direkt in den Tresor übernehmen." Foreground="#6B7890" FontSize="12" TextWrapping="Wrap" Margin="0,0,0,6"/>',
        (New-White (New-DataGrid 'LicSwGrid' @('Programm|Program|240', 'Version|Version|100', 'Lizenz über|Kind|90', 'So zieht sie um|Hint|*', 'Lizenzdatei|File|*') 'Height="220"')),
        '<WrapPanel Margin="0,8,0,0"><Button x:Name="BtnLicSwFile" Content="Lizenzdatei in den Tresor" Style="{StaticResource Sec}"/><Button x:Name="BtnLicSwAdd" Content="Schlüssel dazu im Tresor notieren" Style="{StaticResource Sec}"/></WrapPanel>')) +
    (New-Card 'Lizenz-Tresor' @(
        '<TextBlock Text="Alle Schlüssel, Lizenzdateien und Notizen sicher an einem Ort - verschlüsselt mit deinem Windows-Konto. Für den Umzug mit eigenem Kennwort exportieren (AES-256) und auf dem neuen PC importieren." Foreground="#6B7890" FontSize="12" TextWrapping="Wrap" Margin="0,0,0,6"/>',
        (New-White (New-DataGrid 'LicVaultGrid' @('Name|Name|220', 'Schlüssel|KeyShow|300', 'Datei|FileName|180', 'Notiz|Note|*', 'Hinzugefügt|Added|110') 'Height="220"')),
        '<Grid Margin="0,8,0,0"><Grid.ColumnDefinitions><ColumnDefinition Width="220"/><ColumnDefinition Width="300"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions><TextBox x:Name="LicVName" Padding="4,3" Margin="0,0,8,0" ToolTip="Name, z.B. Windows 11 Pro"/><TextBox x:Name="LicVKey" Grid.Column="1" Padding="4,3" Margin="0,0,8,0" ToolTip="Schlüssel / Lizenzcode"/><TextBox x:Name="LicVNote" Grid.Column="2" Padding="4,3" ToolTip="Notiz, z.B. gekauft 2024, Rechnung bei Amazon"/></Grid>',
        '<WrapPanel Margin="0,8,0,0"><Button x:Name="BtnLicVAdd" Content="Hinzufügen"/><Button x:Name="BtnLicVShow" Content="Schlüssel anzeigen" Style="{StaticResource Sec}"/><Button x:Name="BtnLicVCopy" Content="Kopieren" Style="{StaticResource Sec}"/><Button x:Name="BtnLicVSaveFile" Content="Datei speichern unter ..." Style="{StaticResource Sec}"/><Button x:Name="BtnLicVDel" Content="Entfernen" Style="{StaticResource Sec}"/></WrapPanel>',
        '<WrapPanel Margin="0,4,0,0"><TextBlock Text="Kennwort für Export/Import:" VerticalAlignment="Center" Margin="0,0,8,8"/><PasswordBox x:Name="LicVPwd" Width="200" Padding="4,3" Margin="0,0,10,8"/><Button x:Name="BtnLicVExport" Content="Für Umzug exportieren ..." Style="{StaticResource Sec}"/><Button x:Name="BtnLicVImport" Content="Import ..." Style="{StaticResource Sec}"/><Button x:Name="BtnLicReport" Content="Lizenzübersicht als Textdatei" Style="{StaticResource Sec}"/></WrapPanel>')))

# ---------------------------------------------------------------- Datensicherung
$pageBackup = New-Page 'Datensicherung' 'Eigene Dateien regelmäßig auf eine externe Festplatte oder ein NAS sichern, ein komplettes Systemabbild des PCs erstellen und alles wieder zurückholen. Die Sicherung läuft im Hintergrund, auch automatisch nach Zeitplan.' ((New-Card 'Was wird gesichert' @(
        '<TextBlock Text="Ordner, die gesichert werden. Liegen Ordner schon auf dem NAS (umgeleitete Benutzerordner), sichert man sie besser auf eine externe Festplatte." Foreground="#6B7890" FontSize="12" TextWrapping="Wrap" Margin="0,0,0,6"/>',
        '<Border BorderBrush="#E2E7F0" BorderThickness="1" CornerRadius="6"><ListBox x:Name="BkSourceList" Height="150" BorderThickness="0" Background="Transparent"/></Border>',
        '<TextBox x:Name="Backup_Sources" Visibility="Collapsed"/>',
        '<WrapPanel Margin="0,8,0,0"><Button x:Name="BtnBkAddUser" Content="Benutzerordner hinzufügen" Style="{StaticResource Sec}"/><Button x:Name="BtnBkAddFolder" Content="Ordner hinzufügen ..." Style="{StaticResource Sec}"/><Button x:Name="BtnBkRemove" Content="Markierten entfernen" Style="{StaticResource Sec}"/></WrapPanel>')) +
    (New-Card 'Wohin' @(
        (New-TextRow 'Backup_Target' 'Sicherungsziel' 'Externe Festplatte (z.B. E:\Sicherung) oder NAS-Freigabe (z.B. \\NAS\Sicherung). Darin entsteht ein Ordner pro PC.' 'BtnBkTarget'),
        '<TextBlock x:Name="BkTargetInfo" Text="" Foreground="#6B7890" FontSize="12" Margin="0,0,0,6" TextWrapping="Wrap"/>',
        '<Grid Margin="0,4"><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions><StackPanel Margin="0,0,8,0"><TextBlock Text="NAS-Benutzer (nur für Netzwerkziele)" FontSize="12" Foreground="#6B7890"/><TextBox x:Name="Backup_NasUser" Padding="4,3"/></StackPanel><StackPanel Grid.Column="1" Margin="0,0,8,0"><TextBlock Text="NAS-Kennwort" FontSize="12" Foreground="#6B7890"/><PasswordBox x:Name="BkNasPwd" Padding="4,3"/></StackPanel><StackPanel Grid.Column="2" Orientation="Horizontal" VerticalAlignment="Bottom"><Button x:Name="BtnBkNasSave" Content="Zugang speichern" Style="{StaticResource Sec}" Padding="12,5" Margin="0,0,8,0"/><Button x:Name="BtnBkTest" Content="Ziel testen" Style="{StaticResource Sec}" Padding="12,5" Margin="0"/></StackPanel></Grid>',
        '<TextBlock x:Name="BkNasInfo" Text="" FontSize="12" Foreground="#6B7890" Margin="0,2,0,4" TextWrapping="Wrap"/>',
        (New-CheckRow 'Backup_OnlyIfTarget' 'Ziel nicht da? Automatische Sicherung still überspringen' 'Praktisch für externe Festplatten, die nicht immer angeschlossen sind - sonst erscheint eine Warnung im Protokoll.'))) +
    (New-Card 'Wie' @(
        '<Grid Margin="0,4"><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions><StackPanel><TextBlock Text="Art der Sicherung" FontWeight="SemiBold"/><TextBlock Text="Spiegeln: Ziel ist immer ein genaues Abbild (gelöschte Dateien verschwinden auch im Ziel). Ergänzen: im Ziel wird nie etwas gelöscht. Versionen: jede Sicherung in einem eigenen Datumsordner - man kann ältere Stände zurückholen, braucht aber mehr Platz." Foreground="#6B7890" FontSize="12" TextWrapping="Wrap" Margin="0,2,12,0"/></StackPanel><ComboBox x:Name="Backup_Mode" Grid.Column="1" Width="230" VerticalAlignment="Top"><ComboBoxItem Content="Spiegeln"/><ComboBoxItem Content="Ergänzen"/><ComboBoxItem Content="Versionen"/></ComboBox></Grid>',
        (New-NumRow 'Versionen behalten' 'Nur bei "Versionen": so viele Stände bleiben, ältere werden gelöscht.' 'Backup_Keep' '' 'Stände'),
        (New-TextRow 'Backup_ExcludeFiles' 'Dateien auslassen' 'Muster mit ; getrennt, z.B. *.tmp;~$*;Thumbs.db' ''),
        (New-TextRow 'Backup_ExcludeDirs' 'Ordner auslassen' 'Ordnernamen mit ; getrennt, z.B. node_modules;.cache;Temp' ''),
        (New-NumRow 'Gleichzeitige Kopiervorgänge' 'Mehr = schneller bei vielen kleinen Dateien; bei USB-Festplatten 8, bei SSD/NAS 16-32.' 'Backup_Threads' '' 'Threads'),
        (New-CheckRow 'Backup_Drivers' 'Treiber mitsichern' 'Alle installierten Treiber werden exportiert - nach einer Neuinstallation sofort wieder da.'),
        (New-CheckRow 'Backup_Image' 'Zusätzlich komplettes Systemabbild' 'Windows, Programme und Einstellungen von Laufwerk C: als Abbild (Windows-Sicherung). Wiederherstellung über die erweiterten Startoptionen.'),
        (New-TextRow 'Backup_ImageTarget' 'Ziel für das Systemabbild' 'Laufwerksbuchstabe einer NTFS-Festplatte (z.B. E:) oder NAS-Freigabe. Auf einem Netzlaufwerk bleibt nur das letzte Abbild erhalten.' ''))) +
    (New-Card 'Zeitplan' @(
        (New-CheckRow 'Backup_Enabled' 'Automatisch sichern' 'Verpasste Sicherungen werden beim nächsten Einschalten nachgeholt.'),
        '<WrapPanel Margin="21,4,0,4"><TextBlock Text="Wann" VerticalAlignment="Center" Margin="0,0,8,8"/><ComboBox x:Name="Backup_Frequency" Width="140" Margin="0,0,10,8"><ComboBoxItem Content="Täglich"/><ComboBoxItem Content="Werktags"/><ComboBoxItem Content="Wöchentlich"/></ComboBox><ComboBox x:Name="Backup_Day" Width="130" Margin="0,0,10,8"><ComboBoxItem Content="Montag"/><ComboBoxItem Content="Dienstag"/><ComboBoxItem Content="Mittwoch"/><ComboBoxItem Content="Donnerstag"/><ComboBoxItem Content="Freitag"/><ComboBoxItem Content="Samstag"/><ComboBoxItem Content="Sonntag"/></ComboBox><TextBlock Text="um" VerticalAlignment="Center" Margin="0,0,6,8"/><TextBox x:Name="Backup_Time" Width="60" TextAlignment="Center" Padding="2,3" Margin="0,0,0,8"/><TextBlock Text="Uhr" VerticalAlignment="Center" Margin="6,0,0,8"/></WrapPanel>',
        (New-CheckRow 'Backup_WakeToRun' 'PC dafür aus dem Energiesparmodus wecken' ''),
        (New-CheckRow 'Backup_Shutdown' 'Nach der automatischen Sicherung herunterfahren' 'Z.B. für eine Sicherung am Abend.'),
        '<TextBlock x:Name="BkTaskInfo" Text="" FontWeight="SemiBold" Margin="0,6,0,0"/>')) +
    (New-Card 'Jetzt sichern' @(
        (New-InfoRow 'Letzte Sicherung' 'BkLast'),
        '<WrapPanel Margin="0,8,0,0"><Button x:Name="BtnBkRun" Content="Jetzt sichern"/><Button x:Name="BtnBkImage" Content="Nur Systemabbild erstellen" Style="{StaticResource Sec}"/><Button x:Name="BtnBkOpen" Content="Sicherung öffnen" Style="{StaticResource Sec}"/><Button x:Name="BtnBkImageList" Content="Vorhandene Systemabbilder" Style="{StaticResource Sec}"/><Button x:Name="BtnBkRecovery" Content="Wiederherstellungslaufwerk (USB) erstellen" Style="{StaticResource Sec}"/></WrapPanel>')) +
    (New-Card 'Wiederherstellen' @(
        '<TextBlock Text="Einzelne Ordner aus einer Sicherung zurückholen. Den ganzen PC stellt man aus dem Systemabbild wieder her: Seite Neustart und BIOS > Erweiterte Startoptionen > Problembehandlung > Erweiterte Optionen > Systemimage-Wiederherstellung." Foreground="#6B7890" FontSize="12" TextWrapping="Wrap" Margin="0,0,0,6"/>',
        (New-TextRow 'BkRestoreSet' 'Sicherung' 'Ordner einer Sicherung (…\PC-Name\Aktuell oder ein Datumsordner)' 'BtnBkRestoreBrowse'),
        '<WrapPanel Margin="0,4,0,4"><Button x:Name="BtnBkRestoreRead" Content="Einlesen" Style="{StaticResource Sec}"/><ComboBox x:Name="BkRestoreMode" Width="300" Margin="0,0,10,8" SelectedIndex="0"><ComboBoxItem Content="Alles zurückschreiben (überschreibt)"/><ComboBoxItem Content="Nur fehlende und ältere Dateien ersetzen"/></ComboBox></WrapPanel>',
        '<StackPanel x:Name="BkRestoreList"/>',
        '<StackPanel Orientation="Horizontal" Margin="0,6,0,0"><CheckBox x:Name="BkRestoreOther" Content="In anderen Ordner wiederherstellen:" VerticalAlignment="Center" Margin="0,0,8,0"/><TextBox x:Name="BkRestoreTarget" Width="360" Padding="4,3"/><Button x:Name="BtnBkRestoreTarget" Content="..." Style="{StaticResource Sec}" Padding="10,3" Margin="6,0,0,0"/></StackPanel>',
        '<WrapPanel Margin="0,8,0,0"><Button x:Name="BtnBkRestore" Content="Ausgewählte wiederherstellen" IsEnabled="False"/></WrapPanel>')))

# ---------------------------------------------------------------- PC-Umzug
$migSettingsXaml = ($MigSettingDefs.Keys | ForEach-Object { '<CheckBox Content="{0}" Tag="{1}" IsChecked="True" Width="330" Margin="0,3"/>' -f (Esc $MigSettingDefs[$_]), $_ }) -join ''
$pageMigrate = New-Page 'PC-Umzug' 'Vom alten auf den neuen PC: Daten, Einstellungen und die Liste der installierten Programme in ein Umzugspaket packen (externe Festplatte, USB-Stick oder NAS) und auf dem neuen PC mit einem Klick zurückspielen - die Programme werden dabei automatisch neu installiert.' ((New-Card '1. Alter PC: Umzugspaket erstellen' @(
        (New-TextRow 'MigTarget' 'Speicherort des Pakets' 'Externe Festplatte, USB-Stick oder NAS-Ordner' 'BtnMigTarget'),
        '<TextBlock Text="Daten" FontWeight="SemiBold" Margin="0,8,0,4"/>',
        '<WrapPanel x:Name="MigFolders"/>',
        '<CheckBox x:Name="MigPrograms" Content="Liste der installierten Programme (auf dem neuen PC automatisch installieren)" IsChecked="True" FontWeight="SemiBold" Margin="0,10,0,4"/>',
        '<TextBlock Text="Einstellungen" FontWeight="SemiBold" Margin="0,8,0,4"/>',
        ('<WrapPanel x:Name="MigSettings">{0}</WrapPanel>' -f $migSettingsXaml),
        '<TextBlock Text="Programmeinstellungen (AppData)" FontWeight="SemiBold" Margin="0,10,0,2"/>',
        '<TextBlock Text="Einstellungen einzelner Programme (z.B. FileZilla-Server, Notepad++, VS Code). Erst einlesen, dann anhaken." Foreground="#6B7890" FontSize="12" Margin="0,0,0,4"/>',
        '<WrapPanel x:Name="MigAppData"/>',
        '<WrapPanel Margin="0,4,0,0"><Button x:Name="BtnMigAppData" Content="Programmeinstellungen einlesen" Style="{StaticResource Sec}"/></WrapPanel>',
        '<Border Background="#F5F9FF" BorderBrush="#AFC4EA" BorderThickness="1" CornerRadius="8" Padding="14,10" Margin="0,12,0,4"><StackPanel>',
        '<TextBlock Text="Browser-Kennwörter lokal mitnehmen (ohne Cloud)" FontWeight="SemiBold" Foreground="#1F2A44"/>',
        '<TextBlock Foreground="#475569" FontSize="12" TextWrapping="Wrap" Margin="0,4,0,8" Text="Chrome, Edge, Brave, Vivaldi und Opera verschlüsseln gespeicherte Kennwörter mit dem Windows-Konto dieses PCs - kopiert sind sie auf dem neuen PC nicht lesbar. Deshalb nutzt PC-Tools die Export-Funktion des Browsers: Knopf drücken, im Browser &quot;Kennwörter exportieren&quot; wählen, mit Windows-Kennwort oder PIN bestätigen und beim Speichern den Ordner einfügen (Strg+V - er steht schon in der Zwischenablage). Beim Erstellen wandern die CSV-Dateien ins Umzugspaket. Firefox nimmt seine Kennwörter mit dem Profil ohnehin mit."/>',
        '<WrapPanel x:Name="MigPwExport"/>',
        '<TextBlock x:Name="MigPwInfo" Text="" FontSize="12" Foreground="#475569" TextWrapping="Wrap" Margin="0,2,0,0"/>',
        '</StackPanel></Border>',
        '<TextBlock Text="Vorher alle Browser schließen. Das Paket enthält WLAN- und Browser-Kennwörter im Klartext - sicher aufbewahren und nach dem Umzug löschen." Foreground="#D97706" FontSize="12" Margin="0,8,0,6" TextWrapping="Wrap"/>',
        '<WrapPanel><Button x:Name="BtnMigExport" Content="Umzugspaket erstellen"/></WrapPanel>')) +
    (New-Card '2. Neuer PC: Paket zurückspielen' @(
        (New-TextRow 'MigPackage' 'Umzugspaket' 'Ordner PC-Umzug_... auswählen' 'BtnMigPackage'),
        '<WrapPanel Margin="0,4,0,0"><Button x:Name="BtnMigRead" Content="Paket einlesen" Style="{StaticResource Sec}"/></WrapPanel>',
        '<TextBlock x:Name="MigInfo" Text="" FontWeight="SemiBold" Margin="0,4,0,6" TextWrapping="Wrap"/>',
        '<StackPanel x:Name="MigImport" Visibility="Collapsed">',
        '<TextBlock Text="Daten" FontWeight="SemiBold" Margin="0,4,0,4"/><WrapPanel x:Name="MigImpFolders"/>',
        '<Grid Margin="0,10,0,4"><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions><TextBlock x:Name="MigImpProgTitle" Text="Programme" FontWeight="SemiBold" VerticalAlignment="Center"/><StackPanel Grid.Column="1" Orientation="Horizontal"><Button x:Name="BtnMigProgAll" Content="Alle" Style="{StaticResource Sec}" Padding="10,3" Margin="0,0,6,0"/><Button x:Name="BtnMigProgNone" Content="Keine" Style="{StaticResource Sec}" Padding="10,3" Margin="0"/></StackPanel></Grid>',
        '<Border BorderBrush="#E2E7F0" BorderThickness="1" CornerRadius="6" Padding="6"><ScrollViewer MaxHeight="260" VerticalScrollBarVisibility="Auto"><WrapPanel x:Name="MigImpPrograms"/></ScrollViewer></Border>',
        '<Expander Header="Programme, die von Hand installiert werden müssen" Margin="0,6,0,0"><TextBox x:Name="MigImpManual" Height="120" IsReadOnly="True" TextWrapping="Wrap" VerticalScrollBarVisibility="Auto" Padding="6"/></Expander>',
        '<TextBlock Text="Einstellungen" FontWeight="SemiBold" Margin="0,10,0,4"/><WrapPanel x:Name="MigImpSettings"/>',
        '<TextBlock Text="Programmeinstellungen (AppData)" FontWeight="SemiBold" Margin="0,10,0,4"/><WrapPanel x:Name="MigImpAppData"/>',
        '<TextBlock Text="Reihenfolge: erst werden die Programme installiert, dann Daten und Einstellungen übernommen. Vorhandene neuere Dateien werden nicht überschrieben." Foreground="#6B7890" FontSize="12" Margin="0,8,0,6" TextWrapping="Wrap"/>',
        '<WrapPanel><Button x:Name="BtnMigImport" Content="Ausgewählte zurückspielen"/></WrapPanel>',
        '<Border x:Name="MigPwImpBox" Visibility="Collapsed" Background="#F5F9FF" BorderBrush="#AFC4EA" BorderThickness="1" CornerRadius="8" Padding="14,10" Margin="0,12,0,0"><StackPanel>',
        '<TextBlock Text="Browser-Kennwörter importieren" FontWeight="SemiBold" Foreground="#1F2A44"/>',
        '<TextBlock x:Name="MigPwImpInfo" Foreground="#475569" FontSize="12" TextWrapping="Wrap" Margin="0,4,0,8" Text=""/>',
        '<WrapPanel x:Name="MigPwImport"/>',
        '<WrapPanel Margin="0,4,0,0"><Button x:Name="BtnMigPwOpen" Content="Ordner öffnen" Style="{StaticResource Sec}"/><Button x:Name="BtnMigPwWipe" Content="Kennwort-Dateien jetzt löschen" Style="{StaticResource Sec}"/></WrapPanel>',
        '</StackPanel></Border>',
        '</StackPanel>')))

function New-Gauge([string]$Name, [string]$Label) {
@"
<StackPanel Margin="8,0" Width="108">
  <Grid Width="92" Height="92">
    <Ellipse Stroke="#FFFFFF" StrokeThickness="8" Opacity="0.22"/>
    <Ellipse x:Name="${Name}Arc" Stroke="#FFFFFF" StrokeThickness="8" StrokeDashArray="0 100" StrokeDashCap="Round" RenderTransformOrigin="0.5,0.5"><Ellipse.RenderTransform><RotateTransform Angle="-90"/></Ellipse.RenderTransform></Ellipse>
    <TextBlock x:Name="${Name}Val" Text="-" Foreground="#FFFFFF" FontSize="19" FontWeight="Bold" HorizontalAlignment="Center" VerticalAlignment="Center"/>
  </Grid>
  <TextBlock Text="$(Esc $Label)" Foreground="#FFFFFF" Opacity="0.95" HorizontalAlignment="Center" Margin="0,6,0,0" FontSize="12.5" FontWeight="SemiBold"/>
  <TextBlock x:Name="${Name}Sub" Text="" Foreground="#FFFFFF" Opacity="0.75" HorizontalAlignment="Center" FontSize="11" TextTrimming="CharacterEllipsis"/>
</StackPanel>
"@
}
function New-ActionTile([string]$Name, [string]$Glyph, [string]$Color, [string]$Title, [string]$Desc) {
@"
<Button x:Name="$Name" Style="{StaticResource Sec}" Width="270" MinHeight="78" Padding="14,10" Margin="0,0,12,12" HorizontalContentAlignment="Stretch">
  <Grid><Grid.ColumnDefinitions><ColumnDefinition Width="Auto"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>
    <Border Width="42" Height="42" CornerRadius="11" Background="$Color" Margin="0,0,12,0" VerticalAlignment="Center"><TextBlock Text="$Glyph" FontFamily="Segoe MDL2 Assets" FontSize="19" Foreground="#FFFFFF" HorizontalAlignment="Center" VerticalAlignment="Center"/></Border>
    <StackPanel Grid.Column="1" VerticalAlignment="Center"><TextBlock Text="$(Esc $Title)" FontWeight="SemiBold" FontSize="14" TextWrapping="Wrap"/><TextBlock Text="$(Esc $Desc)" FontWeight="Normal" FontSize="12" Foreground="#475569" TextWrapping="Wrap" Margin="0,2,0,0"/></StackPanel>
  </Grid>
</Button>
"@
}
$pageOverviewHero = @"
<Border CornerRadius="18" Margin="0,0,4,18" Padding="28,24" Background="{StaticResource HeroGrad}">
  <Border.Effect><DropShadowEffect BlurRadius="26" ShadowDepth="5" Direction="270" Opacity="0.28" Color="#2A2F8F"/></Border.Effect>
  <Grid>
    <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
    <StackPanel VerticalAlignment="Center" Margin="0,0,20,0">
      <TextBlock x:Name="HeroHello" Text="Hallo" Foreground="#FFFFFF" Opacity="0.85" FontSize="15"/>
      <TextBlock x:Name="HeroPc" Text="$env:COMPUTERNAME" Foreground="#FFFFFF" FontSize="34" FontWeight="Bold" Margin="0,2,0,0"/>
      <TextBlock x:Name="HeroSub" Text="" Foreground="#FFFFFF" Opacity="0.85" FontSize="13.5" TextWrapping="Wrap" Margin="0,2,0,12"/>
      <WrapPanel x:Name="HeroChips"/>
    </StackPanel>
    <WrapPanel Grid.Column="1" VerticalAlignment="Center">$(New-Gauge 'GaCpu' 'Prozessor')$(New-Gauge 'GaRam' 'Arbeitsspeicher')$(New-Gauge 'GaDisk' 'Laufwerk C:')$(New-Gauge 'GaSec' 'Sicherheit')</WrapPanel>
  </Grid>
</Border>
"@
