            (New-ActionTile 'BtnQuickSearch' '&#xE721;' '#334155' 'Suchen (Strg+K)' 'Jede Funktion und Einstellung schnell finden'),
            (New-ActionTile 'BtnQuickManual' '&#xE82D;' '#475569' 'Handbuch' 'Alle Funktionen verständlich erklärt'),
            (New-ActionTile 'BtnQuickDiag' '&#xEBE8;' '#DC2626' 'Fehlerdaten (Super-Log)' 'Alle Protokolle als ZIP sammeln - zum Auswerten oder Senden'),
            (New-ActionTile 'BtnQuickTweakAll' '&#xE713;' '#2563EB' 'Alle Optimierungen' 'Ein Klick: alle Leistungs-, Datenschutz-, Explorer- und System-Einstellungen an'),
            (New-ActionTile 'BtnQuickAutoMin' '&#xE7E8;' '#9333EA' 'Autostart: nur das Nötige' 'Ein Klick: nur Sicherheit, Treiber-Helfer und angepinnte Programme starten mit'),
            (New-ActionTile 'BtnQuickUnused' '&#xE74D;' '#DC2626' 'Nicht genutzte Programme' 'Lange nicht gestartete Programme finden und samt Resten entfernen')),
        '<TextBlock x:Name="CarefreeState" Foreground="#6B7890" FontSize="12" Text="Sorgenfrei-Modus noch nicht eingerichtet."/>')) +
    (New-Card 'System' @(
        (New-InfoRow 'Windows' 'InfoOS'),
        (New-InfoRow 'Gerät' 'InfoModel'),
        (New-InfoRow 'Hersteller-Tool' 'InfoOem'),
        (New-InfoRow 'Virenschutz' 'InfoAv'),
        (New-InfoRow 'PC-Tools' 'InfoAppVer'),
        (New-InfoRow 'Laufwerk C:' 'InfoDisk'),
        (New-InfoRow 'Läuft seit' 'InfoUptime'),
        (New-InfoRow 'Neustart ausstehend' 'InfoReboot'))) + $pageOverviewHw +
    (New-Card 'Pflege' @(
        (New-InfoRow 'Letzte Pflege' 'InfoLastRun'),
        (New-InfoRow 'Automatische Pflege' 'InfoTask'))))


$pageClean = New-Page 'Aufräumen' 'Was regelmäßig entfernt werden soll. Persönliche Ordner (Desktop, Dokumente, Downloads) werden nie angefasst.' ((New-Card 'Temporäre Dateien' @(
        (New-CheckRow 'Clean_UserTemp' 'Temporäre Dateien aller Benutzer' 'AppData\Local\Temp aller Profile. Gerade benutzte Dateien werden automatisch übersprungen.' 'Clean_UserTempDays'),
        (New-CheckRow 'Clean_WinTemp' 'Temporäre Dateien von Windows' 'C:\Windows\Temp' 'Clean_WinTempDays'),
        (New-CheckRow 'Clean_ThumbCache' 'Miniaturansichten-Cache' 'Wird von Windows bei Bedarf automatisch neu erstellt.'),
        (New-CheckRow 'Clean_BrowserCache' 'Browser-Cache (Chrome, Edge, Firefox)' 'Nur Cache - keine Passwörter, Cookies oder Verlauf. Wird übersprungen, solange der Browser läuft.'))) +
    (New-Card 'Windows-Rückstände' @(
        (New-CheckRow 'Clean_WUCache' 'Windows-Update-Downloadcache' 'SoftwareDistribution\Download - wird übersprungen, solange ein Neustart aussteht.'),
        (New-CheckRow 'Clean_DeliveryOpt' 'Übermittlungsoptimierung' 'Cache für die Update-Verteilung zwischen PCs.'),
        (New-CheckRow 'Clean_WER' 'Fehlerberichte und Speicherabbilder' 'Windows-Fehlerberichte, Minidumps, MEMORY.DMP, CrashDumps der Programme.' 'Clean_WERDays'),
        (New-CheckRow 'Clean_OldLogs' 'Alte Protokolldateien' 'CBS-, DISM- und Windows-Update-Logs. Setup- und Upgrade-Logs (Panther) bleiben für Fehleranalysen erhalten.' 'Clean_OldLogsDays'),
        (New-CheckRow 'Clean_RecycleBin' 'Papierkorb (alle Benutzer und Laufwerke)' 'Nur Elemente, die schon länger im Papierkorb liegen.' 'Clean_RecycleBinDays' 'gelöscht vor mehr als'))) +
    (New-Card 'Tiefenreinigung' @(
        (New-CheckRow 'Clean_CleanMgr' 'Windows-Datenträgerbereinigung' 'Update-Rückstände, alte Treiberpakete, Defender-Reste u.v.m. Setup-Dateien laufender Upgrades bleiben erhalten.'),
        (New-CheckRow 'Clean_ComponentCleanup' 'Komponentenspeicher bereinigen (WinSxS)' 'DISM StartComponentCleanup - entfernt ersetzte Update-Versionen.'),
        (New-CheckRow 'Clean_ResetBase' 'zusätzlich /ResetBase' 'Spart mehr Platz - installierte Updates lassen sich danach nicht mehr deinstallieren.'),
        (New-CheckRow 'Clean_OldDrivers' 'Veraltete Treiberpakete entfernen' 'Ältere Versionen desselben Treibers im Treiberspeicher. Verwendete Treiber werden nie gelöscht.'),
        (New-CheckRow 'Clean_WindowsOld' 'Vorherige Windows-Installation (Windows.old) entfernen' 'Achtung: Danach ist kein Zurückkehren zur vorherigen Windows-Version mehr möglich.'))) +
    (New-Card 'PC-Tools selbst' @(
        (New-CheckRow 'Clean_OwnLogs' 'Protokolle und Berichte von PC-Tools bereinigen' 'Alte Protokolle, Ninite- und HP-Berichte sowie heruntergeladene Treiberpakete. Aufbewahrungsdauer unter Einstellungen.'))) +
    '<WrapPanel><Button x:Name="BtnRunClean" Content="Nur Aufräumen ausführen"/></WrapPanel>')

$pageOpt = New-Page 'Optimieren' 'Wartung für Laufwerke und Systemdateien.' ((New-Card 'Sicherheit' @(
        (New-CheckRow 'Optimize_RestorePoint' 'Wiederherstellungspunkt vor Updates und Optimierung' 'Computerschutz muss für Laufwerk C: aktiviert sein.'))) +
    (New-Card 'Leistung' @(
        (New-CheckRow 'Optimize_Volumes' 'Laufwerke optimieren' 'Alle internen Laufwerke - Art (SSD/Festplatte) wird automatisch erkannt. Fortschritt live im Protokoll.'),
        (New-CheckRow 'Optimize_Trim' 'SSDs: TRIM ausführen' 'Teilt der SSD mit, welche Blöcke frei sind - hält Schreibgeschwindigkeit und Lebensdauer hoch. Dauert Sekunden.'),
        (New-CheckRow 'Optimize_Defrag' 'Festplatten (HDD): defragmentieren' 'Ordnet zerstückelte Dateien neu an. Kann bei großen Platten länger dauern. SSDs werden nie defragmentiert.'),
        (New-CheckRow 'Optimize_SkipUsb' 'USB-Laufwerke dabei auslassen' ''),
        (New-CheckRow 'Optimize_DnsFlush' 'DNS-Cache leeren' ''),
        (New-CheckRow 'Optimize_DisableFastStartup' 'Schnellstart deaktivieren' 'Empfohlen: sorgt für echte Neustarts und saubere Update-Installationen.'))) +
    (New-Card 'Reparatur' @(
        (New-CheckRow 'Optimize_HealthCheck' 'Systemdateien prüfen und reparieren' 'DISM RestoreHealth und SFC /scannow - dauert 15 bis 60 Minuten.'))) +
    '<WrapPanel><Button x:Name="BtnRunOpt" Content="Nur Optimierung ausführen"/></WrapPanel>')

$pageUpd = New-Page 'Updates' 'Windows, Treiber, Programme und Store-Apps aktuell halten.' ((New-Card 'Windows' @(
        (New-CheckRow 'Update_WindowsUpdate' 'Windows Update' 'Sicherheits- und Qualitätsupdates, .NET, Office (falls über Microsoft Update) usw.'),
        (New-CheckRow 'Update_WUDrivers' 'Treiber über Windows Update' ''),
        (New-CheckRow 'Update_WUExcludeUpgrades' 'Funktionsupdates und Insider-Builds ausschließen' 'Standard: aus - neue Windows-Versionen und (wenn der PC im Insider-Programm ist) die neuesten Insider-Builds werden automatisch mitinstalliert. Dauert 1-2 Stunden und braucht Neustarts.'),
        (New-CheckRow 'Update_Defender' 'Defender-Signaturen' 'Nur, wenn Microsoft Defender der aktive Virenscanner ist.'))) +
    (New-Card 'Treiber vom Hersteller' @(
        (New-CheckRow 'Update_OEM' 'Hersteller-Treiber (Dell / HP / Lenovo)' 'Hersteller wird automatisch erkannt: Dell Command | Update, HP Image Assistant oder Lenovo Thin Installer.'),
        (New-CheckRow 'Update_OEMAutoInstall' 'Hersteller-Tool automatisch installieren und aktuell halten' 'Fehlt das Tool oder ist es veraltet, wird es vor der Benutzung über winget in der neuesten Version installiert.'),
        (New-CheckRow 'Update_OEMFirmware' 'Auch BIOS und Firmware installieren' 'Nur wenn gewünscht - BIOS-Updates brauchen einen Neustart und stabile Stromversorgung.'),
        '<TextBlock Text="Ein abweichender Pfad zum Hersteller-Tool lässt sich unter Einstellungen festlegen." Foreground="#6B7890" FontSize="12" Margin="0,4,0,0"/>')) +
    (New-Card 'Programme - Ninite Pro' @(
        (New-CheckRow 'Update_Ninite' 'Programme mit Ninite Pro aktualisieren' 'Aktualisiert alle installierten Programme, die Ninite kennt (Chrome, Firefox, 7-Zip, VLC, Zoom, Java ...). Installiert nichts Neues. Läuft vor winget.' 'Update_NiniteTimeout' 'max.' 'Min.'),
        (New-CheckRow 'Update_NiniteKill' 'Laufende Programme dafür schließen (/kill)' 'Standard: nur beim nächtlichen Zeitplan (siehe Einstellungen) - bei manuellen Läufen werden offene Programme übersprungen.'),
        (New-TextRow 'Update_NiniteExclude' 'Von Ninite ausgenommen' 'Ninite-Namen, durch Komma getrennt, z.B. Firefox, Zoom'))) +
    (New-Card 'Programme - winget' @(
        (New-CheckRow 'Update_Winget' 'Programme aktualisieren (winget)' 'Alle Programme, die winget kennt: Browser, 7-Zip, Notepad++, Adobe Reader, VLC ... Jedes Programm wird einzeln installiert - hängt ein Installer, wird nur er nach dem Zeitlimit beendet.' 'Update_WingetTimeout' 'max.' 'Min./Programm'),
        (New-TextRow 'Update_WingetExclude' 'Ausgenommene Programme' 'winget-Paket-IDs, durch Komma getrennt, z.B. Mozilla.Firefox, VMware.WorkstationPro'),
        (New-CheckRow 'Update_Choco' 'Programme mit Chocolatey aktualisieren (kostenlos, 10.000+ Programme)' 'Freier Paketmanager - die kostenlose Alternative zu Ninite Pro. Läuft nach winget und fängt Programme ab, die winget nicht kennt. So ergänzen sich die Quellen: scheitert eine an einem Programm, kann die andere es aktualisieren.' 'Update_ChocoTimeout' 'max.' 'Min.'),
        (New-CheckRow 'Update_ChocoAutoInstall' 'Chocolatey bei Bedarf automatisch einrichten' 'Installiert Chocolatey still über das offizielle Skript (community.chocolatey.org), falls es fehlt. Braucht Administratorrechte.'),
        (New-TextRow 'Update_ChocoExclude' 'Von Chocolatey ausgenommen' 'Chocolatey-Paketnamen, durch Komma getrennt, z.B. googlechrome, firefox'),
        '<Border Background="#EFF6FF" BorderBrush="#BFDBFE" BorderThickness="1" CornerRadius="10" Padding="14,12" Margin="0,8,0,2"><Grid><Grid.ColumnDefinitions><ColumnDefinition Width="Auto"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions><Border Width="38" Height="38" CornerRadius="10" Background="#2563EB" VerticalAlignment="Top" Margin="0,0,12,0"><TextBlock Text="&#xE71D;" FontFamily="Segoe MDL2 Assets" FontSize="18" Foreground="White" HorizontalAlignment="Center" VerticalAlignment="Center"/></Border><StackPanel Grid.Column="1"><TextBlock Text="Weitere kostenlose Update-Werkzeuge (grafisch, manuell)" FontWeight="SemiBold" Foreground="#1E3A8A"/><TextBlock Text="UniGetUI: eine schöne Oberfläche über winget, Chocolatey und Scoop - alles an einem Ort aktualisieren. Patch My PC Home Updater: eine portable EXE, die ~300 gängige Programme still aktualisiert (für privat kostenlos, Ninite-ähnlich)." Foreground="#1D4ED8" FontSize="12" TextWrapping="Wrap" Margin="0,2,0,10"/><WrapPanel><Button x:Name="BtnGetUniGet" Content="UniGetUI holen" Style="{StaticResource Sec}"/><Button x:Name="BtnGetPatchMyPc" Content="Patch My PC Home holen" Style="{StaticResource Sec}"/></WrapPanel></StackPanel></Grid></Border>',
        (New-CheckRow 'Update_StoreApps' 'Microsoft-Store-Apps' 'Store-Aktualisierung anstoßen (zuverlässig über den Zeitplan).'))) +
    (New-Card 'Neustart' @(
        (New-CheckRow 'Update_AutoReboot' 'Bei Bedarf automatisch neu starten' 'Mit Vorwarnung, abbrechbar mit: shutdown /a. Standard: nur beim Zeitplan - Wartezeit unter Einstellungen.'))) +
    '<WrapPanel><Button x:Name="BtnCheckUpd2" Content="Nach Updates suchen" Style="{StaticResource Sec}"/><Button x:Name="BtnRunUpd" Content="Updates installieren"/></WrapPanel>')

$pageInstall = @"
<Grid>
  <Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="*"/><RowDefinition Height="Auto"/></Grid.RowDefinitions>
  <StackPanel>
    <TextBlock Text="Programme installieren" FontSize="24" FontWeight="SemiBold" Foreground="#1F2A44"/>
    <TextBlock Text="Still installieren - ohne Toolbars oder Werbung, immer die aktuelle Version. Quelle wählen: der geprüfte Katalog (empfohlen) oder die Online-Suche über winget und Chocolatey mit zehntausenden Programmen. Ninite Pro wird zusätzlich genutzt, wenn es vorhanden ist." FontSize="13" Foreground="#6B7890" Margin="0,4,0,14" TextWrapping="Wrap"/>
  </StackPanel>
  <Grid Grid.Row="1" Margin="0,0,0,12">
    <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="190"/><ColumnDefinition Width="190"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
    <Grid>
      <TextBox x:Name="NinSearch" Padding="30,6,6,6" FontSize="13"/>
      <TextBlock FontFamily="Segoe MDL2 Assets" Text="&#xE721;" Foreground="#9AA5B8" VerticalAlignment="Center" Margin="10,0,0,0" IsHitTestVisible="False"/>
      <TextBlock x:Name="NinSearchHint" Text="Suchen ..." Foreground="#9AA5B8" VerticalAlignment="Center" Margin="30,0,0,0" IsHitTestVisible="False"/>
    </Grid>
    <ComboBox x:Name="NinSource" Grid.Column="1" Margin="10,0,0,0" VerticalContentAlignment="Center"/>
    <ComboBox x:Name="NinCategory" Grid.Column="2" Margin="10,0,0,0" VerticalContentAlignment="Center"/>
    <StackPanel x:Name="NinCatOpts" Grid.Column="3" Orientation="Horizontal" Margin="10,0,0,0">
      <CheckBox x:Name="NinOnlySel" Content="nur Auswahl" VerticalAlignment="Center" Margin="0,0,10,0"/>
      <CheckBox x:Name="NinHideInst" Content="Installierte ausblenden" VerticalAlignment="Center"/>
    </StackPanel>
    <Button x:Name="BtnNinOnline" Grid.Column="3" Content="Online suchen" Style="{StaticResource Sec}" Margin="10,0,0,0" Visibility="Collapsed"/>
  </Grid>
  <Border Grid.Row="2" Background="White" CornerRadius="10" BorderBrush="#E2E7F0" BorderThickness="1">
    <Grid>
      <ScrollViewer x:Name="NinCatView" VerticalScrollBarVisibility="Auto" Padding="16,10,8,10">
        <StackPanel x:Name="NinPanel"/>
      </ScrollViewer>
      <Grid x:Name="NinOnlineView" Visibility="Collapsed">
        <DataGrid x:Name="NinOnlineGrid" Margin="2" AutoGenerateColumns="False" IsReadOnly="True" HeadersVisibility="Column"
                  SelectionMode="Extended" GridLinesVisibility="Horizontal" BorderThickness="0" Background="White"
                  CanUserResizeRows="False" RowHeaderWidth="0">
          <DataGrid.Columns>
            <DataGridTextColumn Header="Programm" Binding="{Binding Name}" Width="*"/>
            <DataGridTextColumn Header="Paket-ID" Binding="{Binding Id}" Width="2*"/>
            <DataGridTextColumn Header="Version" Binding="{Binding Version}" Width="120"/>
            <DataGridTextColumn Header="Quelle" Binding="{Binding Source}" Width="110"/>
          </DataGrid.Columns>
        </DataGrid>
        <TextBlock x:Name="NinOnlineEmpty" Text="Suchbegriff oben eingeben und Enter drücken (oder &quot;Online suchen&quot;)." Foreground="#9AA5B8" HorizontalAlignment="Center" VerticalAlignment="Center" FontSize="14" TextWrapping="Wrap" TextAlignment="Center" Margin="40"/>
      </Grid>
    </Grid>
  </Border>
  <Grid Grid.Row="3" Margin="0,12,0,0">
    <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
    <StackPanel>
      <TextBlock x:Name="NinInfo" Text="0 ausgewählt" FontWeight="SemiBold" Foreground="#1F2A44" TextWrapping="Wrap"/>
      <StackPanel Orientation="Horizontal" Margin="0,6,0,0">
        <CheckBox x:Name="Install_Shortcuts" Content="Desktop-Verknüpfungen anlegen" Margin="0,0,16,0"/>
        <CheckBox x:Name="Install_AllUsers" Content="Für alle Benutzer installieren (wo möglich)"/>
      </StackPanel>
    </StackPanel>
    <WrapPanel Grid.Column="1" VerticalAlignment="Center">
      <Button x:Name="BtnNinAudit" Content="Installierte erkennen" Style="{StaticResource Sec}" Margin="0,0,10,0"/>
      <Button x:Name="BtnNinClear" Content="Auswahl leeren" Style="{StaticResource Sec}" Margin="0,0,10,0"/>
      <Button x:Name="BtnNinInstall" Content="Ausgewählte installieren" Margin="0"/>
    </WrapPanel>
  </Grid>
</Grid>
"@

$pageSetup = @"
<Grid>
  <Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="*"/></Grid.RowDefinitions>
  <StackPanel>
    <TextBlock Text="Neues Gerät einrichten" FontSize="24" FontWeight="SemiBold" Foreground="#1F2A44"/>
    <TextBlock Text="Karten anklicken - mehrere Profile lassen sich kombinieren (z.B. Büro-PC + Business-PC). Programme darunter bei Bedarf anpassen und installieren. Nicht vorausgewählte Programme sind optional (z.B. lizenzpflichtig)." FontSize="13" Foreground="#6B7890" Margin="0,4,0,8" TextWrapping="Wrap"/>
    <WrapPanel Margin="0,0,0,10"><Button x:Name="BtnProfSave" Content="Auswahl als eigenes Profil speichern ..." Style="{StaticResource Sec}"/><Button x:Name="BtnProfFromPc" Content="Profil aus diesem PC erzeugen" Style="{StaticResource Sec}"/><Button x:Name="BtnProfImport" Content="Profil importieren ..." Style="{StaticResource Sec}"/><Button x:Name="BtnProfExport" Content="Profil exportieren ..." Style="{StaticResource Sec}"/><Button x:Name="BtnProfDelete" Content="Eigenes Profil löschen ..." Style="{StaticResource Sec}"/><Button x:Name="BtnProfWizard" Content="Einrichtungs-Assistent" Style="{StaticResource Sec}"/></WrapPanel>
  </StackPanel>
  <ScrollViewer Grid.Row="1" MaxHeight="400" VerticalScrollBarVisibility="Auto" Margin="0,0,0,12">
    <WrapPanel x:Name="ProfPanel"/>
  </ScrollViewer>
  <Border Grid.Row="2" Background="White" CornerRadius="10" BorderBrush="#E2E7F0" BorderThickness="1" Padding="18,14">
    <Grid>
      <Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="*"/><RowDefinition Height="Auto"/></Grid.RowDefinitions>
      <StackPanel>
        <TextBlock x:Name="ProfTitle" Text="Bitte ein oder mehrere Profile wählen" FontSize="17" FontWeight="SemiBold" Foreground="#1F2A44"/>
        <TextBlock x:Name="ProfDesc" Text="" Foreground="#6B7890" Margin="0,2,0,8" TextWrapping="Wrap"/>
      </StackPanel>
      <ScrollViewer Grid.Row="1" VerticalScrollBarVisibility="Auto">
        <WrapPanel x:Name="ProfApps"/>
      </ScrollViewer>
      <Grid Grid.Row="2" Margin="0,10,0,0">
        <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
        <TextBlock x:Name="ProfInfo" Text="" VerticalAlignment="Center" Foreground="#1F2A44" FontWeight="SemiBold" TextWrapping="Wrap"/>
        <WrapPanel Grid.Column="1">
          <Button x:Name="BtnProfAll" Content="Alle" Style="{StaticResource Sec}" Margin="0,0,8,0" Padding="14,8"/>
          <Button x:Name="BtnProfNone" Content="Keine" Style="{StaticResource Sec}" Margin="0,0,8,0" Padding="14,8"/>
          <Button x:Name="BtnProfInstall" Content="Profil installieren" Margin="0"/>
        </WrapPanel>
      </Grid>
    </Grid>
  </Border>
</Grid>
"@

$pageDesk = @"
<Grid>
  <Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="*"/><RowDefinition Height="Auto"/></Grid.RowDefinitions>
  <StackPanel>
    <TextBlock Text="Desktop aufräumen" FontSize="24" FontWeight="SemiBold" Foreground="#1F2A44"/>
    <TextBlock Text="Nichts wird gelöscht: Unnötiges wandert in einen Alt-Ordner auf dem Desktop (zum Prüfen und späteren Löschen), der Rest wird ordentlich einsortiert. Jede Aktion lässt sich rückgängig machen." FontSize="13" Foreground="#6B7890" Margin="0,4,0,14" TextWrapping="Wrap"/>
  </StackPanel>
  <Border Grid.Row="1" Background="White" CornerRadius="10" BorderBrush="#E2E7F0" BorderThickness="1" Padding="16,12" Margin="0,0,0,12">
    <Grid>
      <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
      <StackPanel>
        <CheckBox x:Name="Desk_MoveBroken" Content="Verknüpfungen ins Leere" Margin="0,2"/>
        <CheckBox x:Name="Desk_MoveDuplicates" Content="Doppelte Verknüpfungen" Margin="0,2"/>
        <CheckBox x:Name="Desk_MoveTemp" Content="Temporäre Dateien (~`$, .tmp, .part ...)" Margin="0,2"/>
        <CheckBox x:Name="Desk_MoveInstallers" Content="Installationsdateien (.exe, .msi)" Margin="0,2"/>
        <CheckBox x:Name="Desk_MoveOldVersions" Content="Ältere Versionen desselben Programms" Margin="0,2" ToolTip="Z.B. Blender 4.2, 4.5 und 5.1 - nur die neueste Verknüpfung bleibt auf dem Desktop"/>
      </StackPanel>
      <StackPanel Grid.Column="1">
        <CheckBox x:Name="Desk_MoveEmpty" Content="Leere Ordner" Margin="0,2"/>
        <StackPanel Orientation="Horizontal" Margin="0,2">
          <CheckBox x:Name="Desk_MoveOld" Content="Dateien unverändert seit" VerticalAlignment="Center"/>
          <TextBox x:Name="Desk_OlderDays" Width="44" TextAlignment="Center" Margin="6,0" Padding="2,1"/>
          <TextBlock Text="Tagen" VerticalAlignment="Center" Foreground="#6B7890"/>
        </StackPanel>
        <CheckBox x:Name="Desk_SortRest" Content="Übrige Dateien in Ablage-Ordner einsortieren" Margin="0,2"/>
        <CheckBox x:Name="Desk_IncludePublic" Content="Öffentlichen Desktop mit prüfen (nur Verknüpfungen)" Margin="0,2"/>
      </StackPanel>
      <StackPanel Grid.Column="2" Margin="12,0,0,0">
        <TextBlock Text="Name des Alt-Ordners" Foreground="#6B7890" FontSize="12"/>
        <TextBox x:Name="Desk_OldFolder" Width="170" Padding="4,3" Margin="0,3,0,0"/>
      </StackPanel>
    </Grid>
  </Border>
  <Border Grid.Row="2" Background="White" CornerRadius="10" BorderBrush="#E2E7F0" BorderThickness="1" Padding="16,12" Margin="0,0,0,12">
    <Grid>
      <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
      <StackPanel>
        <TextBlock Text="Nach Programmkategorien ordnen" FontSize="15" FontWeight="SemiBold" Foreground="#1F2A44"/>
        <TextBlock Text="Ordnet alle Symbole auf dem Hauptbildschirm in Gruppen - wahlweise in Zeilen oben entlang oder in Spalten links herunter: Windows (Papierkorb, PC-Tools, Neustart ...), Kategorie-Ordner, persönliche Ordner, dann Programme nach Kategorie (Büro, Internet, Netzwerk, Entwicklung, KI, 3D-Druck &amp; CAD, Grafik, Multimedia, Kameras, System) und Dateien. Jede Gruppe beginnt in einer neuen Zeile bzw. Spalte. Oder: Verknüpfungen gleich in Ordner je Kategorie einsortieren (Büro, KI, 3D-Druck ...) - Windows-Symbole, PC-Tools, Ordner und Dateien bleiben liegen." Foreground="#6B7890" FontSize="12" TextWrapping="Wrap" Margin="0,2,0,6"/>
        <WrapPanel>
          <TextBlock Text="Anordnung" VerticalAlignment="Center" Foreground="#6B7890" Margin="0,2,6,2"/>
          <ComboBox x:Name="Desk_ArrangeLayout" Width="190" Margin="0,2,18,2"><ComboBoxItem Content="Zeilen - oben entlang"/><ComboBoxItem Content="Spalten - links herunter"/></ComboBox>
          <CheckBox x:Name="Desk_ArrangeGap" Content="Abstand zwischen den Gruppen (wenn Platz ist)" Margin="0,2,18,2"/>
          <CheckBox x:Name="Desk_ArrangeAfterClean" Content="Nach dem Aufräumen automatisch anordnen" Margin="0,2,18,2"/>
        </WrapPanel>
        <StackPanel Orientation="Horizontal" Margin="0,4,0,0"><TextBlock Text="In Ordner einsortieren: Ordner erst ab" VerticalAlignment="Center" Foreground="#6B7890"/><TextBox x:Name="Desk_FolderMin" Width="36" TextAlignment="Center" Margin="6,0" Padding="2,1"/><TextBlock Text="Verknüpfungen einer Kategorie anlegen" VerticalAlignment="Center" Foreground="#6B7890"/></StackPanel>
        <TextBlock x:Name="DeskArrInfo" Text="" Foreground="#1F2A44" FontWeight="SemiBold" TextWrapping="Wrap" Margin="0,6,0,0"/>
      </StackPanel>
      <WrapPanel Grid.Column="1" VerticalAlignment="Center" MaxWidth="330" Margin="12,0,0,0">
        <Button x:Name="BtnDeskArrPreview" Content="Vorschau" Style="{StaticResource Sec}" Margin="0,0,8,8"/>
        <Button x:Name="BtnDeskArrange" Content="Jetzt anordnen" Margin="0,0,8,8"/>
        <Button x:Name="BtnDeskFolders" Content="In Ordner einsortieren" Margin="0,0,8,8" ToolTip="Verknüpfungen in Ordner wie Büro, 3D-Druck &amp; CAD, KI, Multimedia ... auf dem Desktop verschieben"/>
        <Button x:Name="BtnDeskLayoutSave" Content="Anordnung merken" Style="{StaticResource Sec}" Margin="0,0,8,8" ToolTip="Speichert die aktuellen Positionen aller Symbole - z.B. nach eigenem Feinschliff"/>
        <Button x:Name="BtnDeskLayoutLoad" Content="Gemerkte wiederherstellen" Style="{StaticResource Sec}" Margin="0,0,8,8"/>
        <Button x:Name="BtnDeskArrLnk" Content="Verknüpfung 'Desktop ordnen'" Style="{StaticResource Sec}" Margin="0,0,8,8"/>
      </WrapPanel>
    </Grid>
  </Border>
  <Border Grid.Row="3" Background="White" CornerRadius="10" BorderBrush="#E2E7F0" BorderThickness="1">
    <Grid>
      <Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="*"/></Grid.RowDefinitions>
      <Grid Margin="14,10,22,6">
        <Grid.ColumnDefinitions><ColumnDefinition Width="30"/><ColumnDefinition Width="*"/><ColumnDefinition Width="210"/><ColumnDefinition Width="200"/><ColumnDefinition Width="90"/><ColumnDefinition Width="70"/></Grid.ColumnDefinitions>
        <CheckBox x:Name="DeskAll" IsChecked="True" VerticalAlignment="Center"/>
        <TextBlock Grid.Column="1" Text="Element" FontWeight="SemiBold" Foreground="#6B7890"/>
        <TextBlock Grid.Column="2" Text="Grund" FontWeight="SemiBold" Foreground="#6B7890"/>
        <TextBlock Grid.Column="3" Text="Ziel" FontWeight="SemiBold" Foreground="#6B7890"/>
        <TextBlock Grid.Column="4" Text="Geändert" FontWeight="SemiBold" Foreground="#6B7890"/>
        <TextBlock Grid.Column="5" Text="Größe" FontWeight="SemiBold" Foreground="#6B7890" TextAlignment="Right"/>
      </Grid>
      <ScrollViewer Grid.Row="1" VerticalScrollBarVisibility="Auto" Padding="14,0,8,8">
        <StackPanel x:Name="DeskList"/>
      </ScrollViewer>
    </Grid>
  </Border>
  <Grid Grid.Row="4" Margin="0,12,0,0">
    <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
    <TextBlock x:Name="DeskInfo" Text="Noch nicht analysiert - auf 'Desktop analysieren' klicken." VerticalAlignment="Center" FontWeight="SemiBold" Foreground="#1F2A44" TextWrapping="Wrap"/>
    <WrapPanel Grid.Column="1">
      <Button x:Name="BtnDeskScan" Content="Desktop analysieren" Style="{StaticResource Sec}" Margin="0,0,8,0"/>
      <Button x:Name="BtnDeskOpen" Content="Alt-Ordner öffnen" Style="{StaticResource Sec}" Margin="0,0,8,0"/>
      <Button x:Name="BtnDeskUndo" Content="Rückgängig" Style="{StaticResource Sec}" Margin="0,0,8,0"/>
      <Button x:Name="BtnDeskRun" Content="Ausgewählte aufräumen" Margin="0"/>
    </WrapPanel>
  </Grid>
</Grid>
"@


$pageMon = New-Page 'Monitore' 'Monitor-Anordnung merken und per Klick oder Desktop-Verknüpfung umschalten. Ein Profil speichert Positionen, Auflösung, Bildwiederholrate, Drehung und Hauptbildschirm - praktisch, wenn Windows die Anordnung nach Updates, Treiberwechseln oder Standby vergisst.' ((New-Card 'Aktuelle Anordnung' @(
        '<Border Background="#F4F6FA" CornerRadius="8" Padding="8" Margin="0,4,0,8"><Canvas x:Name="MonCanvas" Height="170" ClipToBounds="True"/></Border>',
        '<StackPanel x:Name="MonCurrent"/>',
        '<Grid Margin="0,12,0,0"><Grid.ColumnDefinitions><ColumnDefinition Width="Auto"/><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions><TextBlock Text="Profilname" VerticalAlignment="Center" Foreground="#6B7890" Margin="0,0,10,0"/><TextBox x:Name="MonName" Grid.Column="1" Padding="4,3" VerticalAlignment="Center"/><StackPanel Grid.Column="2" Orientation="Horizontal"><Button x:Name="BtnMonRefresh" Content="Neu einlesen" Style="{StaticResource Sec}" Margin="8,0,0,0" Padding="12,5"/><Button x:Name="BtnMonSave" Content="Als Profil speichern" Margin="8,0,0,0" Padding="12,5"/><Button x:Name="BtnMonSettings" Content="Windows-Anzeigeeinstellungen" Style="{StaticResource Sec}" Margin="8,0,0,0" Padding="12,5"/></StackPanel></Grid>')) +
    (New-Card 'Gespeicherte Profile' @(
        '<TextBlock Text="Anwenden schaltet sofort um. Eine Verknüpfung auf dem Desktop schaltet ohne Rückfrage und ohne Admin-Abfrage um - danach werden die Desktop-Symbole wie unten eingestellt neu sortiert." Foreground="#6B7890" FontSize="12" TextWrapping="Wrap" Margin="0,0,0,6"/>',
        '<StackPanel x:Name="MonList"/>')) +
    (New-Card 'Schnell umschalten (wie Windows-Taste + P)' @(
        '<WrapPanel Margin="0,4,0,0"><Button x:Name="BtnTopoExtend" Content="Erweitern" Style="{StaticResource Sec}"/><Button x:Name="BtnTopoClone" Content="Duplizieren" Style="{StaticResource Sec}"/><Button x:Name="BtnTopoInternal" Content="Nur Hauptbildschirm" Style="{StaticResource Sec}"/><Button x:Name="BtnTopoExternal" Content="Nur zweiter Bildschirm" Style="{StaticResource Sec}"/></WrapPanel>')) +
    (New-Card 'Automatik' @(
        (New-CheckRow 'Monitor_AutoAtLogon' 'Beim Anmelden ein Profil wiederherstellen' 'Stellt nach jeder Anmeldung die gewählte Anordnung wieder her (ohne Admin-Abfrage). Wird mit "Einstellungen speichern" eingerichtet.'),
        '<Grid Margin="21,2,0,8"><Grid.ColumnDefinitions><ColumnDefinition Width="Auto"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions><TextBlock Text="Profil" VerticalAlignment="Center" Foreground="#6B7890" Margin="0,0,10,0"/><ComboBox x:Name="Monitor_AutoProfile" Grid.Column="1" Width="280" HorizontalAlignment="Left"/></Grid>',
        '<Grid Margin="0,6,0,0"><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions><StackPanel><TextBlock Text="Desktop-Symbole nach dem Umschalten" FontWeight="SemiBold" Foreground="#1F2A44"/><TextBlock Text="Windows schiebt die Symbole beim Umschalten durcheinander - danach automatisch wieder ordnen." Foreground="#6B7890" FontSize="12" TextWrapping="Wrap" Margin="0,2,0,0"/></StackPanel><ComboBox x:Name="Monitor_AfterSwitch" Grid.Column="1" Width="300" VerticalAlignment="Top"><ComboBoxItem Content="Symbole nach Kategorien anordnen"/><ComboBoxItem Content="Gemerkte Symbol-Anordnung wiederherstellen"/><ComboBoxItem Content="Nichts tun"/></ComboBox></Grid>')))

$pageTune = @"
<Grid>
  <Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="*"/><RowDefinition Height="Auto"/></Grid.RowDefinitions>
  <StackPanel>
    <TextBlock Text="Tuning" FontSize="24" FontWeight="SemiBold" Foreground="#1F2A44"/>
    <TextBlock Text="Sinnvolle Windows-Optimierungen für Leistung, Datenschutz und Bedienung. Jede Option zeigt ihren aktuellen Zustand, lässt sich einzeln zurücknehmen, und vor jeder Änderung wird ein Wiederherstellungspunkt erstellt." FontSize="13" Foreground="#6B7890" Margin="0,4,0,12" TextWrapping="Wrap"/>
  </StackPanel>
  <WrapPanel Grid.Row="1" Margin="0,0,0,12">
    <TextBlock Text="Vorgaben:" VerticalAlignment="Center" Foreground="#6B7890" Margin="0,0,10,8"/>
    <Button x:Name="BtnTwRec" Content="Empfohlen"/>
    <Button x:Name="BtnTwPerf" Content="Maximale Leistung" Style="{StaticResource Sec}"/>
    <Button x:Name="BtnTwPriv" Content="Datenschutz" Style="{StaticResource Sec}"/>
    <Button x:Name="BtnTwStd" Content="Alles auf Windows-Standard" Style="{StaticResource Sec}"/>
    <Button x:Name="BtnTwCur" Content="Auswahl verwerfen" Style="{StaticResource Sec}"/>
  </WrapPanel>
  <ScrollViewer Grid.Row="2" VerticalScrollBarVisibility="Auto" Padding="0,0,8,0">
    <StackPanel>
      <StackPanel x:Name="TweakPanel"/>
      <Border Background="White" CornerRadius="10" Padding="18,12" Margin="0,0,0,14" BorderBrush="#E2E7F0" BorderThickness="1">
        <StackPanel>
          <Grid Margin="0,0,0,6">
            <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
            <StackPanel>
              <TextBlock Text="Autostart-Programme" FontSize="15" FontWeight="SemiBold" Foreground="#1F2A44"/>
              <TextBlock Text="Häkchen entfernen = Programm startet nicht mehr mit Windows (wie im Task-Manager, jederzeit umkehrbar). Wirkt sofort. Mit der Stecknadel markierte Einträge bleiben bei &quot;Nur das Nötige&quot; und &quot;Alle aus&quot; immer an." FontSize="12" Foreground="#6B7890" TextWrapping="Wrap" Margin="0,2,0,0"/>
            </StackPanel>
            <Button x:Name="BtnAutoRefresh" Grid.Column="1" Content="Neu laden" Style="{StaticResource Sec}" Margin="10,0,0,0" Padding="12,5" VerticalAlignment="Top"/>
          </Grid>
          <WrapPanel Margin="0,6,0,2">
            <Button x:Name="BtnAutoMinimal" Content="Nur das Nötige (1 Klick)" Padding="14,7" Margin="0,0,8,8"/>
            <Button x:Name="BtnAutoRecommended" Content="Empfehlung: Überflüssiges aus" Style="{StaticResource Sec}" Padding="14,7" Margin="0,0,8,8"/>
            <Button x:Name="BtnAutoAllOn" Content="Alle an" Style="{StaticResource Sec}" Padding="14,7" Margin="0,0,8,8"/>
            <Button x:Name="BtnAutoAllOff" Content="Alle aus" Style="{StaticResource Sec}" Padding="14,7" Margin="0,0,8,8"/>
            <Button x:Name="BtnAutoUndo" Content="Rückgängig" Style="{StaticResource Sec}" Padding="14,7" Margin="0,0,8,8" IsEnabled="False"/>
            <Button x:Name="BtnAutoBroken" Content="Kaputte Einträge entfernen" Style="{StaticResource Sec}" Padding="14,7" Margin="0,0,8,8"/>
            <Button x:Name="BtnAutoFolder" Content="Autostart-Ordner" Style="{StaticResource Sec}" Padding="14,7" Margin="0,0,8,8"/>
            <Button x:Name="BtnAutoTaskMgr" Content="Task-Manager" Style="{StaticResource Sec}" Padding="14,7" Margin="0,0,8,8"/>
          </WrapPanel>
          <WrapPanel Margin="0,0,0,6">
            <TextBlock Text="Anzeigen:" VerticalAlignment="Center" Margin="0,0,8,8"/>
            <ComboBox x:Name="AutoFilter" Width="220" Margin="0,0,14,8" SelectedIndex="0"><ComboBoxItem Content="Alle"/><ComboBoxItem Content="Nur aktive"/><ComboBoxItem Content="Nur deaktivierte"/><ComboBoxItem Content="Überflüssige"/><ComboBoxItem Content="Notwendige"/><ComboBoxItem Content="Kaputte (Datei fehlt)"/></ComboBox>
            <CheckBox x:Name="AutoShowTasks" Content="Aufgaben bei der Anmeldung zeigen" IsChecked="True" Margin="0,0,14,8" VerticalAlignment="Center"/>
            <TextBlock x:Name="AutoSummary" Text="" FontWeight="SemiBold" Foreground="#1F2A44" VerticalAlignment="Center" Margin="0,0,0,8"/>
          </WrapPanel>
          <StackPanel x:Name="AutoList"/>
        </StackPanel>
      </Border>
      <Border Background="White" CornerRadius="10" Padding="18,12" Margin="0,0,0,14" BorderBrush="#E2E7F0" BorderThickness="1">
        <StackPanel>
          <TextBlock Text="Startzeit-Analyse" FontSize="15" FontWeight="SemiBold" Foreground="#1F2A44"/>
          <TextBlock Text="Windows misst bei jedem Start, welche Programme, Dienste und Treiber ihn bremsen. Hier stehen die größten Bremsen der letzten 60 Tage - Programme lassen sich aus dem Autostart nehmen, Dienste von Drittanbietern verzögert starten." Foreground="#6B7890" FontSize="12" TextWrapping="Wrap" Margin="0,2,0,8"/>
          <WrapPanel Margin="0,0,0,6"><Button x:Name="BtnBootAnalyze" Content="Startzeit analysieren" Padding="14,7" Margin="0,0,8,8"/><Button x:Name="BtnBootFix" Content="Ausgewählte entschärfen" Style="{StaticResource Sec}" Padding="14,7" Margin="0,0,8,8" IsEnabled="False" ToolTip="Ohne Auswahl: alle Bremsen ab 1 Sekunde, die PC-Tools ändern kann"/></WrapPanel>
          <TextBlock x:Name="BootSummary" Text="" FontWeight="SemiBold" Foreground="#1F2A44" TextWrapping="Wrap" Margin="0,0,0,6"/>
          $(New-DataGrid 'BootTimeGrid' @('Art|Typ|95', 'Name|Display|*', 'Ø Verzögerung|AvgText|105|AvgSec', 'Anzahl|Count|65', 'Zuletzt|LastText|90', 'Möglich|Action|210') 'Height="240" IsReadOnly="True" AutoGenerateColumns="False" SelectionMode="Extended"')
        </StackPanel>
      </Border>
    </StackPanel>
  </ScrollViewer>
  <Grid Grid.Row="3" Margin="0,12,0,0">
    <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
    <TextBlock x:Name="TweakInfo" Text="" VerticalAlignment="Center" FontWeight="SemiBold" Foreground="#1F2A44"/>
    <WrapPanel Grid.Column="1">
      <Button x:Name="BtnTwExplorer" Content="Explorer neu starten" Style="{StaticResource Sec}" Margin="0,0,8,0"/>
      <Button x:Name="BtnTweakApply" Content="Übernehmen" Margin="0"/>
    </WrapPanel>
  </Grid>
</Grid>
"@

$pageSettings = New-Page 'Einstellungen' 'Verhalten, Aufbewahrung, Zeitlimits, Pfade und Verwaltung von PC-Tools.' ((New-Card 'Darstellung' @(
        '<Grid Margin="0,4"><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions><StackPanel><TextBlock Text="Farbschema" FontWeight="SemiBold" Foreground="#1F2A44"/><TextBlock Text="Automatisch folgt der Windows-Einstellung (Einstellungen > Personalisierung > Farben). Wirkt nach dem nächsten Start von PC-Tools." Foreground="#6B7890" FontSize="12" TextWrapping="Wrap" Margin="0,2,0,0"/></StackPanel><ComboBox x:Name="Settings_Theme" Grid.Column="1" Width="220" VerticalAlignment="Top"><ComboBoxItem Content="Automatisch (wie Windows)"/><ComboBoxItem Content="Hell"/><ComboBoxItem Content="Dunkel"/></ComboBox></Grid>')) +
    (New-Card 'Bereinigung' @(
        '<Grid Margin="0,4"><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions><StackPanel><TextBlock Text="Standard-Alter für alle Bereinigungen" FontWeight="SemiBold" Foreground="#1F2A44"/><TextBlock Text="Dateien, die älter sind, werden gelöscht. Mit dem Button auf alle Punkte der Seite Aufräumen übertragen." Foreground="#6B7890" FontSize="12" TextWrapping="Wrap" Margin="0,2,0,0"/></StackPanel><StackPanel Grid.Column="1" Orientation="Horizontal" VerticalAlignment="Top"><TextBox x:Name="Settings_CleanDays" Width="48" TextAlignment="Center" Padding="2,3"/><TextBlock Text="Tage" Foreground="#6B7890" VerticalAlignment="Center" Margin="6,0,10,0"/><Button x:Name="BtnApplyDays" Content="Auf alle anwenden" Style="{StaticResource Sec}" Margin="0" Padding="12,5"/></StackPanel></Grid>')) +
    (New-Card 'Neustart und laufende Programme' @(
        (New-CheckRow 'Settings_RebootOnlyScheduled' 'Automatischer Neustart nur beim Zeitplan' 'Bei manuellen Läufen startet der PC nie von selbst neu - es erscheint nur ein Hinweis.'),
        (New-CheckRow 'Settings_KillOnlyScheduled' 'Programme nur beim Zeitplan schließen (Ninite /kill)' 'Verhindert, dass geöffnete Programme während der Arbeit geschlossen werden.'),
        (New-NumRow 'Vorwarnzeit vor dem Neustart' 'Zeit zwischen Hinweis und Neustart.' 'Settings_RebootDelay' '' 'Minuten'))) +
    (New-Card 'Protokolle und Berichte' @(
        (New-NumRow 'Protokolle von PC-Tools aufbewahren' 'Ältere Protokolle werden beim Aufräumen gelöscht.' 'Settings_LogDays' '' 'Tage'),
        (New-NumRow 'Ninite- und Hersteller-Berichte aufbewahren' '' 'Settings_ReportDays' '' 'Tage'),
        '<WrapPanel Margin="0,8,0,0"><Button x:Name="BtnOpenLogs2" Content="Protokollordner öffnen" Style="{StaticResource Sec}"/><Button x:Name="BtnOpenData" Content="Datenordner öffnen" Style="{StaticResource Sec}"/></WrapPanel>')) +
    (New-Card 'Zeitlimits' @(
        (New-NumRow 'Hersteller-Tool (Dell/HP/Lenovo)' 'Danach wird das Tool beendet und die Pflege läuft weiter.' 'Settings_OemTimeout' 'max.' 'Min.'),
        (New-NumRow 'Windows-Datenträgerbereinigung' '' 'Settings_CleanMgrTimeout' 'max.' 'Min.'),
        '<TextBlock Text="Zeitlimits für winget (pro Programm) und Ninite stehen auf der Seite Updates." Foreground="#6B7890" FontSize="12" Margin="0,4,0,0"/>')) +
    (New-Card 'Pfade' @(
        (New-TextRow 'Update_NinitePath' 'NinitePro.exe (optional)' 'Ohne NinitePro laufen Programm-Updates über winget (kostenlos, in Windows). NinitePro Pro (mehr Programme): ninite.com/pro. Leer = automatisch neben PCPflege.ps1 bzw. in C:\ProgramData\PCPflege.' 'BtnBrowseNinite'),
        '<Border Background="#ECFDF5" BorderBrush="#A7F3D0" BorderThickness="1" CornerRadius="10" Padding="14,12" Margin="0,2,0,10"><Grid><Grid.ColumnDefinitions><ColumnDefinition Width="Auto"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions><Border Width="38" Height="38" CornerRadius="10" Background="#059669" VerticalAlignment="Top" Margin="0,0,12,0"><TextBlock Text="&#xE896;" FontFamily="Segoe MDL2 Assets" FontSize="18" Foreground="White" HorizontalAlignment="Center" VerticalAlignment="Center"/></Border><StackPanel Grid.Column="1"><TextBlock Text="Programm-Updates auch ohne NinitePro" FontWeight="SemiBold" Foreground="#065F46"/><TextBlock Text="PC-Tools aktualisiert Programme kostenlos über winget (in Windows enthalten). NinitePro ist optional - für mehr Programme und einen Zwischenspeicher. Vorhandenes NinitePro wird nie gelöscht." Foreground="#047857" FontSize="12" TextWrapping="Wrap" Margin="0,2,0,10"/><WrapPanel><Button x:Name="BtnNiniteFree" Content="Kostenlose Ninite-Seite öffnen" Style="{StaticResource Sec}"/><Button x:Name="BtnNinitePro" Content="NinitePro kaufen (ninite.com/pro)" Style="{StaticResource Sec}"/></WrapPanel></StackPanel></Grid></Border>',
        (New-TextRow 'Update_OEMToolPath' 'Hersteller-Tool' 'Leer = automatisch (wird bei Bedarf installiert). Nur für abweichende Speicherorte.' 'BtnBrowse'))) +
    (New-Card 'Verknüpfungen' @(
        '<Grid Margin="0,0,0,8"><Grid.ColumnDefinitions><ColumnDefinition Width="Auto"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions><Image x:Name="ShortcutLogo" Width="48" Height="48" Margin="0,0,14,0" VerticalAlignment="Top"/><StackPanel Grid.Column="1"><TextBlock Text="PC-Tools mit einem Doppelklick starten" FontWeight="SemiBold" Foreground="#1F2A44"/><TextBlock Text="Die Verknüpfung startet die Kopie unter C:\ProgramData\PCPflege - sie wird bei jedem Start aus dem Programmordner aktuell gehalten. Beim ersten Start werden Desktop und Startmenü automatisch eingerichtet." Foreground="#6B7890" FontSize="12" TextWrapping="Wrap" Margin="0,2,0,4"/><TextBlock x:Name="ShortcutStatus" Text="..." Foreground="#16A34A" FontWeight="SemiBold" FontSize="12"/></StackPanel></Grid>',
        '<WrapPanel><Button x:Name="BtnLnkDesktop" Content="Auf meinem Desktop"/><Button x:Name="BtnLnkPublic" Content="Desktop aller Benutzer" Style="{StaticResource Sec}"/><Button x:Name="BtnLnkStart" Content="Im Startmenü" Style="{StaticResource Sec}"/><Button x:Name="BtnLnkRemove" Content="Verknüpfungen entfernen" Style="{StaticResource Sec}"/></WrapPanel>')) +
    (New-Card 'Updates von PC-Tools' @(
        '<TextBlock x:Name="UpdStatus" Text="..." FontWeight="SemiBold" Foreground="#1F2A44" TextWrapping="Wrap" Margin="0,0,0,6"/>',
        (New-TextRow 'Settings_UpdateSource' 'Update-Quelle' 'Privates GitHub-Repository als github:BENUTZER/REPO (optional @branch, Standard main) - oder ein Ordner / eine Netzwerkfreigabe bzw. https-Adresse mit version.json. Von hier wird Code auf alle Geräte verteilt: nur du darfst dort schreiben.' 'BtnUpdBrowse'),
        '<StackPanel Margin="0,6"><TextBlock Text="GitHub-Token" FontWeight="SemiBold" Foreground="#1F2A44"/><TextBlock Text="Fine-grained Token, nur für dieses Repository. Auf deinem PC mit Contents: Lesen und Schreiben (zum Veröffentlichen), auf allen anderen Geräten nur Lesen. Wird verschlüsselt und an dieses Gerät gebunden gespeichert." Foreground="#6B7890" FontSize="12" TextWrapping="Wrap" Margin="0,2,0,4"/><Grid><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions><PasswordBox x:Name="GhToken" Padding="4,3"/><Button x:Name="BtnGhSave" Grid.Column="1" Content="Token speichern" Style="{StaticResource Sec}" Margin="8,0,0,0" Padding="12,4"/><Button x:Name="BtnGhTest" Grid.Column="2" Content="Verbindung testen" Style="{StaticResource Sec}" Margin="8,0,0,0" Padding="12,4"/></Grid><TextBlock x:Name="GhStatus" Text="" FontSize="12" Margin="0,4,0,0" TextWrapping="Wrap"/></StackPanel>',
        (New-CheckRow 'Settings_UpdateAuto' 'Beim Start nach neuer Version suchen' ''),
        (New-CheckRow 'Settings_UpdateInSchedule' 'Beim Zeitplan automatisch aktualisieren' 'Die automatische Pflege installiert neue Versionen selbst und läuft dann mit der neuen Version weiter. Für Netzwerkfreigaben muss das Computerkonto lesen dürfen (oder https nutzen).'),
        '<WrapPanel Margin="0,6,0,0"><Button x:Name="BtnUpdCheck" Content="Jetzt prüfen" Style="{StaticResource Sec}"/><Button x:Name="BtnUpdInstall" Content="Update installieren" IsEnabled="False"/><Button x:Name="BtnUpdPublish" Content="Diese Version veröffentlichen" Style="{StaticResource Sec}"/></WrapPanel>',
        '<Border Background="#F4F6FA" CornerRadius="8" Padding="12,10" Margin="0,10,0,0"><StackPanel><TextBlock Text="Weitere PCs einrichten" FontWeight="SemiBold" Foreground="#1F2A44"/><TextBlock Text="Einmal einen Nur-Lesen-Token hier hinterlegen und ein Einrichtungspaket erstellen (z.B. auf dem NAS oder einem USB-Stick). Auf jedem anderen PC reicht dann ein Doppelklick auf Einrichten.cmd: PC-Tools wird installiert oder aktualisiert, Update-Quelle und Token werden automatisch übernommen." Foreground="#6B7890" FontSize="12" TextWrapping="Wrap" Margin="0,2,0,6"/><Grid><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions><PasswordBox x:Name="GhReadToken" Padding="4,3" VerticalContentAlignment="Center"/><Button x:Name="BtnGhReadSave" Grid.Column="1" Content="Nur-Lesen-Token speichern" Style="{StaticResource Sec}" Margin="8,0,0,0" Padding="12,5"/><Button x:Name="BtnPkgCreate" Grid.Column="2" Content="Einrichtungspaket erstellen" Margin="8,0,0,0" Padding="12,5"/></Grid><TextBlock x:Name="GhReadStatus" Text="" FontSize="12" Margin="0,4,0,0" TextWrapping="Wrap"/></StackPanel></Border>')) +
    (New-Card 'Stabilität, Selbsttest und Ansicht' @(
        '<TextBlock x:Name="StabInfo" Text="" FontWeight="SemiBold" Foreground="#1F2A44" TextWrapping="Wrap" Margin="0,0,0,8"/>',
        '<Grid Margin="0,3"><Grid.ColumnDefinitions><ColumnDefinition Width="230"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions><TextBlock Text="Update-Verzögerung" Foreground="#475569" VerticalAlignment="Center"/><StackPanel Grid.Column="1" Orientation="Horizontal">' + (New-Combo 'Settings_UpdateDelay' @('Sofort', '1 Tag warten', '2 Tage warten', '3 Tage warten', '7 Tage warten') 200) + '</StackPanel></Grid>',
        '<TextBlock Text="Auf deinem Test-PC &quot;Sofort&quot;, auf allen anderen z.B. &quot;2 Tage warten&quot;: Neue Versionen landen dann erst auf dem Test-PC - fällt dort ein Fehler auf, ist die Korrektur da, bevor die anderen PCs aktualisieren. Von Hand (Update installieren) geht es immer sofort." Foreground="#6B7890" FontSize="12" TextWrapping="Wrap" Margin="0,0,0,8"/>',
        '<TextBlock Text="Schutz bei Updates: Jede neue Version wird vor der Installation auf Fehler geprüft, die bisherige als Vorversion gesichert. Startet die neue Version zweimal hintereinander nicht, stellt PC-Tools die Vorversion selbst wieder her und überspringt die fehlerhafte Version." Foreground="#6B7890" FontSize="12" TextWrapping="Wrap" Margin="0,0,0,8"/>',
        '<WrapPanel><Button x:Name="BtnSelfTest" Content="Selbsttest starten"/><Button x:Name="BtnRollback" Content="Auf Vorversion zurück ..." Style="{StaticResource Sec}" IsEnabled="False"/><Button x:Name="BtnErrLog" Content="Fehlerprotokoll" Style="{StaticResource Sec}"/></WrapPanel>',
        '<TextBlock x:Name="SelfTestInfo" Text="Der Selbsttest prüft PowerShell, .NET, Rechte, Datenordner, Einstellungen, Programmdatei, Zeitplan, Update-Quelle, Vorversion, winget und abgefangene Fehler." Foreground="#475569" FontSize="12" TextWrapping="Wrap" Margin="0,2,0,6"/>',
        (New-White (New-DataGrid 'SelfTestGrid' @('Bereich|Area|210', 'Ergebnis|State|200', 'Details|Detail|*') 'Height="290"')),
        ('<Border Background="#F4F6FA" CornerRadius="10" Padding="14,12" Margin="0,12,0,0"><StackPanel><TextBlock Text="Sprache" FontWeight="SemiBold" Foreground="#1F2A44"/><TextBlock x:Name="StabLangInfo" Text="" Foreground="#6B7890" FontSize="12" TextWrapping="Wrap" Margin="0,2,0,8"/><WrapPanel><ComboBox x:Name="LangBox" Uid="notr" Width="230" Margin="0,0,8,6">{0}</ComboBox><Button x:Name="BtnLangApply" Content="Sprache übernehmen (Neustart)" Style="{{StaticResource Sec}}" Margin="0,0,8,6"/><Button x:Name="BtnLangReport" Content="Übersetzungsfehler melden" Style="{{StaticResource Sec}}" Margin="0,0,8,6"/></WrapPanel></StackPanel></Border>' -f ((@($LangList.Keys | ForEach-Object { '<ComboBoxItem Uid="notr" Content="{0}" Tag="{1}"/>' -f $LangList[$_], $_ })) -join '')),
        '<Border Background="#F4F6FA" CornerRadius="10" Padding="14,12" Margin="0,12,0,0"><StackPanel><TextBlock Text="Lite-Ansicht" FontWeight="SemiBold" Foreground="#1F2A44"/><TextBlock x:Name="StabLite" Text="" Foreground="#6B7890" FontSize="12" TextWrapping="Wrap" Margin="0,2,0,8"/><WrapPanel><Button x:Name="BtnLiteToggle" Content="Lite-Ansicht einschalten" Style="{StaticResource Sec}"/><Button x:Name="BtnEdAsk" Content="Beim nächsten Start Lite/Voll fragen" Style="{StaticResource Sec}"/></WrapPanel></StackPanel></Border>' +
        '<Border Background="#F4F6FA" CornerRadius="10" Padding="14,12" Margin="0,12,0,0"><StackPanel><TextBlock Text="Einfach-Modus und Hilfe holen" FontWeight="SemiBold" Foreground="#1F2A44"/><TextBlock Text="Der Einfach-Modus zeigt nur eine Ampel und zwei große Knöpfe: Alles reparieren und Hilfe holen - ideal für Eltern, Großeltern und Einsteiger. Hilfe holen schickt einen Bericht an den Helfer: in Meine PCs (wenn eingerichtet), als Handy-Nachricht (wenn eingerichtet) und auf Wunsch per E-Mail." Foreground="#6B7890" FontSize="12" TextWrapping="Wrap" Margin="0,2,0,8"/><WrapPanel><Button x:Name="BtnSimpleOn" Content="Einfach-Modus einschalten" Style="{StaticResource Sec}"/><TextBlock Text="E-Mail des Helfers:" VerticalAlignment="Center" Margin="6,0,8,8" Foreground="#1F2A44"/><TextBox x:Name="Help_Mail" Width="240" Padding="4,4" Margin="0,0,8,8" VerticalAlignment="Center"/><Button x:Name="BtnHelpTry" Content="Hilfe holen ausprobieren" Style="{StaticResource Sec}"/></WrapPanel></StackPanel></Border>' +
        '<Border Background="#F4F6FA" CornerRadius="10" Padding="14,12" Margin="0,12,0,0"><StackPanel><TextBlock Text="Server-Modus (AD / Windows Server)" FontWeight="SemiBold" Foreground="#1F2A44"/><TextBlock x:Name="SrvModeState" Text="" Foreground="#6B7890" FontSize="12" TextWrapping="Wrap" Margin="0,2,0,8"/><CheckBox x:Name="Settings_ServerMode" Content="Server-Werkzeuge anzeigen (AD, Azure/Entra, Server-Wartung)"/><TextBlock Text="Auf Windows Server sind die Server-Werkzeuge automatisch an. Auf einem normalen PC (z.B. Admin-Arbeitsplatz mit RSAT) lassen sie sich hier einschalten. Beim Einschalten bietet PC-Tools an, PowerShell-Remoting zu aktivieren (für Fern-Verwaltung)." Foreground="#6B7890" FontSize="12" TextWrapping="Wrap" Margin="0,8,0,0"/></StackPanel></Border>')) +
    (New-Card 'Virenschutz' @(
        '<TextBlock x:Name="AvStatus" Text="..." FontWeight="SemiBold" Foreground="#1F2A44" TextWrapping="Wrap"/>',
        '<TextBlock x:Name="AvHint" Text="" Foreground="#6B7890" FontSize="12" TextWrapping="Wrap" Margin="0,4,0,8"/>',
        '<TextBlock Text="Diese Ordner als Ausnahme eintragen:" Foreground="#1F2A44" FontSize="12"/>',
        '<TextBox x:Name="AvPaths" IsReadOnly="True" FontFamily="Consolas" FontSize="12" Padding="6,4" Margin="0,4,0,8" TextWrapping="Wrap" BorderBrush="#E2E7F0"/>',
        '<WrapPanel><Button x:Name="BtnAvCopy" Content="Pfade kopieren" Style="{StaticResource Sec}"/><Button x:Name="BtnAvDefender" Content="Defender-Ausnahmen eintragen" Style="{StaticResource Sec}"/><Button x:Name="BtnAvOpen" Content="Virenscanner öffnen" Style="{StaticResource Sec}"/></WrapPanel>')) +
    (New-Card 'Konfiguration' @(
        '<TextBlock Text="Einstellungen sichern, auf andere PCs übertragen oder auf die empfohlenen Standardwerte zurücksetzen." Foreground="#6B7890" FontSize="12" TextWrapping="Wrap" Margin="0,0,0,10"/>',
        '<WrapPanel><Button x:Name="BtnCfgExport" Content="Exportieren ..." Style="{StaticResource Sec}"/><Button x:Name="BtnCfgImport" Content="Importieren ..." Style="{StaticResource Sec}"/><Button x:Name="BtnCfgReset" Content="Standardwerte" Style="{StaticResource Sec}"/><Button x:Name="BtnTaskRemove" Content="Zeitplan-Aufgabe entfernen" Style="{StaticResource Sec}"/></WrapPanel>')) +
    (New-Card 'Info' @(
        (New-InfoRow 'Version' 'InfoVersion'),
        (New-InfoRow 'Programmdatei' 'InfoScript'),
        (New-InfoRow 'Datenordner' 'InfoData'),
        (New-InfoRow 'Computer' 'InfoComputer'))) +
    (New-Card 'Über PC-Tools' @(
        '<TextBlock TextWrapping="Wrap" Foreground="#1F2A44" FontSize="13"><Run Text="PC-Tools ist kostenlos und quelloffen (Open Source, Lizenz Apache 2.0)." FontWeight="SemiBold"/><LineBreak/><Run Text="Entwickelt von René Hütt (by RH). Jeder darf das Programm prüfen, nutzen und weitergeben."/></TextBlock>',
        '<TextBlock TextWrapping="Wrap" Foreground="#166534" FontSize="12.5" Margin="0,8,0,0"><Run Text="Datenschutz: " FontWeight="SemiBold"/><Run Text="PC-Tools sendet nichts nach Hause - keine Telemetrie, keine Nutzerdaten. Nur der KI-Assistent kontaktiert das Internet, und nur, wenn du ausdrücklich eine Frage sendest."/></TextBlock>',
        '<TextBlock x:Name="InfoChecksum" TextWrapping="Wrap" Foreground="#6B7890" FontSize="11.5" Margin="0,8,0,0"/>',
        '<WrapPanel Margin="0,10,0,0"><Button x:Name="BtnAboutGitHub" Content="Quelltext auf GitHub ansehen"/><Button x:Name="BtnAboutIssue" Content="Fehler melden / Verbesserung vorschlagen" Style="{StaticResource Sec}"/><Button x:Name="BtnAboutLicense" Content="Lizenz (Apache 2.0)" Style="{StaticResource Sec}"/><Button x:Name="BtnAboutWhatsNew" Content="Was ist neu in dieser Version" Style="{StaticResource Sec}"/></WrapPanel>')))

$scheduleBody = @"
<Grid Margin="0,6">
  <Grid.ColumnDefinitions><ColumnDefinition Width="190"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>
  <Grid.RowDefinitions><RowDefinition/><RowDefinition/><RowDefinition/></Grid.RowDefinitions>
  <TextBlock Text="Häufigkeit" Foreground="#6B7890" VerticalAlignment="Center" Margin="0,4"/>
  <ComboBox x:Name="Schedule_Frequency" Grid.Column="1" Width="200" HorizontalAlignment="Left" Margin="0,4">
    <ComboBoxItem Content="Täglich"/><ComboBoxItem Content="Wöchentlich"/><ComboBoxItem Content="Alle 2 Wochen"/><ComboBoxItem Content="Alle 4 Wochen"/>
  </ComboBox>
  <TextBlock Grid.Row="1" Text="Wochentag" Foreground="#6B7890" VerticalAlignment="Center" Margin="0,4"/>
  <ComboBox x:Name="Schedule_Day" Grid.Row="1" Grid.Column="1" Width="200" HorizontalAlignment="Left" Margin="0,4">
    <ComboBoxItem Content="Montag"/><ComboBoxItem Content="Dienstag"/><ComboBoxItem Content="Mittwoch"/><ComboBoxItem Content="Donnerstag"/><ComboBoxItem Content="Freitag"/><ComboBoxItem Content="Samstag"/><ComboBoxItem Content="Sonntag"/>
  </ComboBox>
  <TextBlock Grid.Row="2" Text="Uhrzeit (HH:mm)" Foreground="#6B7890" VerticalAlignment="Center" Margin="0,4"/>
  <TextBox x:Name="Schedule_Time" Grid.Row="2" Grid.Column="1" Width="80" HorizontalAlignment="Left" Margin="0,4" Padding="4,3"/>
</Grid>
"@
$pageSched = New-Page 'Zeitplan' 'Automatische Pflege als geplante Aufgabe (läuft als SYSTEM, auch ohne Anmeldung).' ((New-Card 'Automatik' @(
        (New-CheckRow 'Schedule_Enabled' 'Automatische Pflege aktivieren' 'Verpasste Termine (PC aus) werden beim nächsten Start nachgeholt.'),
        $scheduleBody,
        (New-CheckRow 'Schedule_WakeToRun' 'PC zum Ausführen aus dem Energiesparmodus wecken' ''))) +
    (New-Card 'Was soll automatisch laufen?' @(
        (New-CheckRow 'Schedule_Update' 'Updates' 'Gemäß Seite Updates'),
        (New-CheckRow 'Schedule_Clean' 'Aufräumen' 'Gemäß Seite Aufräumen'),
        (New-CheckRow 'Schedule_Optimize' 'Optimieren' 'Gemäß Seite Optimieren'),
        '<TextBlock Text="Ist auf der Übersicht bei der Ein-Klick-Optimierung „Als automatische Pflege planen“ angehakt, läuft zum geplanten Termin stattdessen die komplette Ein-Klick-Optimierung (mit Treibern, Systemprüfung und Vorher/Nachher-Bericht) - die drei Haken hier gelten dann nicht." Foreground="#6B7890" FontSize="12" TextWrapping="Wrap" Margin="0,4,0,6"/>')) +
    (New-Card 'Status' @('<TextBlock x:Name="ScheduleStatus" Text="..." Foreground="#1F2A44" FontWeight="SemiBold" TextWrapping="Wrap"/>')) +
    '<WrapPanel><Button x:Name="BtnSchedule" Content="Zeitplan übernehmen"/></WrapPanel>')


# ---------------------------------------------------------------- Version 7: neue Seiten
function Add-PageCards([string]$Page, [string]$Cards) { $i = $Page.LastIndexOf('</StackPanel>'); return $Page.Insert($i, $Cards) }
function New-StepHead([string]$No, [string]$Title, [string]$Name, [string]$Color = '#2D7FF9', [bool]$On = $true) {
    '<Grid Margin="0,0,0,10"><Grid.ColumnDefinitions><ColumnDefinition Width="Auto"/><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>' +
    ('<Border Width="34" Height="34" CornerRadius="17" Background="{0}" Margin="0,0,12,0"><TextBlock Text="{1}" Foreground="#FFFFFF" FontWeight="Bold" FontSize="15" HorizontalAlignment="Center" VerticalAlignment="Center"/></Border>' -f $Color, $No) +
    ('<TextBlock Grid.Column="1" Text="{0}" FontSize="16" FontWeight="SemiBold" Foreground="#1F2A44" VerticalAlignment="Center"/>' -f (Esc $Title)) +
    ('<CheckBox x:Name="{0}" Grid.Column="2" Content="ausführen" IsChecked="{1}" VerticalAlignment="Center" Margin="0"/></Grid>' -f $Name, $(if ($On) { 'True' } else { 'False' }))
}
function New-StepCard([string]$Head, [string[]]$Rows) {
@"
<Border Background="White" CornerRadius="12" Padding="20,16" Margin="0,0,4,14" BorderBrush="#E2E7F0" BorderThickness="1">
  <Border.Effect><DropShadowEffect BlurRadius="18" ShadowDepth="2" Direction="270" Opacity="0.07" Color="Black"/></Border.Effect>
  <StackPanel>$Head
    $($Rows -join "`n")
  </StackPanel>
</Border>
"@
}
function New-FieldRow([string]$Label, [string]$Control) { '<Grid Margin="0,3"><Grid.ColumnDefinitions><ColumnDefinition Width="230"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions><TextBlock Text="{0}" Foreground="#475569" VerticalAlignment="Center" TextWrapping="Wrap"/><ContentControl Grid.Column="1">{1}</ContentControl></Grid>' -f (Esc $Label), $Control }
function New-Hint([string]$Text) { '<TextBlock Text="{0}" Foreground="#6B7890" FontSize="12" TextWrapping="Wrap" Margin="0,4,0,6"/>' -f (Esc $Text) }
function New-StatTile([string]$Name, [string]$Label, [string]$Color) { '<Border Width="200" Margin="0,0,12,12" Padding="16,12" CornerRadius="12" Background="{2}"><StackPanel><TextBlock x:Name="{0}" Text="-" FontSize="30" FontWeight="Bold" Foreground="#FFFFFF"/><TextBlock Text="{1}" Foreground="#FFFFFF" Opacity="0.92" TextWrapping="Wrap"/></StackPanel></Border>' -f $Name, (Esc $Label), $Color }
$comboMin = { param($n, $vals, $sel) '<ComboBox x:Name="{0}" Width="140" HorizontalAlignment="Left" SelectedIndex="{2}">{1}</ComboBox>' -f $n, (($vals | ForEach-Object { '<ComboBoxItem Content="{0}"/>' -f (Esc $_) }) -join ''), $sel }

# ---- Einrichtungs-Assistent
$pageWizard = New-Page 'Einrichtungs-Assistent' 'Einen neuen oder frisch installierten PC in einem Durchgang komplett einrichten: Name, Region, Energie, Datenschutz, Apps entfernen, Programme, Treiber, Updates (mit automatischen Neustarts), Konten, Netzlaufwerke, Drucker, Einstellungen vom alten PC, BitLocker und Sorgenfrei-Modus. Jeden Schritt einzeln an- oder abwählen - am Ende gibt es ein Einrichtungsprotokoll als PDF.' (
    ('<Border CornerRadius="16" Padding="22,16" Margin="0,0,4,16" Background="{StaticResource HeroGrad}"><StackPanel><TextBlock Text="So funktioniert es" Foreground="#FFFFFF" FontSize="17" FontWeight="SemiBold"/>' +
     '<TextBlock Foreground="#FFFFFF" Opacity="0.93" TextWrapping="Wrap" Margin="0,6,0,10" Text="1. Schritte unten prüfen und anpassen   2. &quot;Alles einrichten&quot; klicken   3. Weiterarbeiten oder zusehen - nach Neustarts geht es nach der Anmeldung automatisch weiter, bis alle Updates drin sind."/>' +
     '<WrapPanel x:Name="WizSteps"/></StackPanel></Border>') +
    (New-StepCard (New-StepHead '1' 'Gerät und Region' 'WizOnBase') @(
        (New-FieldRow 'Computername' '<StackPanel Orientation="Horizontal"><TextBox x:Name="WizName" Width="220" Padding="4,3"/><TextBlock x:Name="WizNameNow" Foreground="#6B7890" VerticalAlignment="Center" Margin="10,0,0,0"/></StackPanel>'),
        (New-FieldRow 'Zeitzone' '<ComboBox x:Name="WizTz" Width="420" HorizontalAlignment="Left"/>'),
        (New-FieldRow 'Design' (& $comboMin 'WizTheme' @('unverändert', 'Hell', 'Dunkel') 0)),
        '<CheckBox x:Name="WizRegion" Content="Region Deutschland, deutsche Datums- und Zahlenformate, Uhrzeit synchronisieren" IsChecked="True" Margin="0,6,0,0"/>')) +
    (New-StepCard (New-StepHead '2' 'Energie und Deckel' 'WizOnPower' '#0891B2') @(
        (New-FieldRow 'Energieplan' (& $comboMin 'WizPower' @('unverändert', 'Ausbalanciert', 'Höchstleistung', 'Energiesparmodus') 1)),
        (New-FieldRow 'Bildschirm aus nach (Minuten)' '<StackPanel Orientation="Horizontal"><TextBlock Text="Netz" Margin="0,0,6,0" VerticalAlignment="Center"/><TextBox x:Name="WizScrAc" Width="50" Text="15"/><TextBlock Text="Akku" Margin="14,0,6,0" VerticalAlignment="Center"/><TextBox x:Name="WizScrDc" Width="50" Text="5"/></StackPanel>'),
        (New-FieldRow 'Energie sparen nach (Minuten, 0 = nie)' '<StackPanel Orientation="Horizontal"><TextBlock Text="Netz" Margin="0,0,6,0" VerticalAlignment="Center"/><TextBox x:Name="WizSlpAc" Width="50" Text="0"/><TextBlock Text="Akku" Margin="14,0,6,0" VerticalAlignment="Center"/><TextBox x:Name="WizSlpDc" Width="50" Text="15"/></StackPanel>'),
        (New-FieldRow 'Deckel zuklappen (Laptop)' (& $comboMin 'WizLid' @('unverändert', 'Nichts tun', 'Energie sparen', 'Ruhezustand', 'Herunterfahren') 0)))) +
    (New-StepCard (New-StepHead '3' 'Datenschutz, Explorer, Taskleiste' 'WizOnUx' '#0F766E') @(
        '<WrapPanel>',
        '<CheckBox x:Name="WizPrivacy" Content="Datenschutz: alles datensparsam" IsChecked="True" Width="330" Margin="0,0,0,6"/>',
        '<CheckBox x:Name="WizExplorer" Content="Dateiendungen zeigen, Explorer öffnet &quot;Dieser PC&quot;" IsChecked="True" Width="330" Margin="0,0,0,6"/>',
        '<CheckBox x:Name="WizHidden" Content="Versteckte Dateien anzeigen" Width="330" Margin="0,0,0,6"/>',
        '<CheckBox x:Name="WizClassic" Content="Klassisches Rechtsklick-Menü (Windows 11)" Width="330" Margin="0,0,0,6"/>',
        '<CheckBox x:Name="WizTaskbar" Content="Taskleiste aufräumen (ohne Widgets, Chat, Taskansicht)" IsChecked="True" Width="330" Margin="0,0,0,6"/>',
        '<CheckBox x:Name="WizTaskLeft" Content="Startknopf links (wie Windows 10)" Width="330" Margin="0,0,0,6"/>',
        '<CheckBox x:Name="WizRdp" Content="Remotedesktop einschalten (Windows Pro)" Width="330" Margin="0,0,0,6"/>',
        '</WrapPanel>')) +
    (New-StepCard (New-StepHead '4' 'Vorinstallierte Apps entfernen' 'WizOnBloat' '#EA580C') @(
        (New-FieldRow 'Umfang' (& $comboMin 'WizBloat' @('Vorsichtig: Werbung und Spiele', 'Empfohlen: + Microsoft-Extras', 'Radikal: + Xbox, Smartphone-Link, Outlook neu') 1).Replace('Width="140"', 'Width="360"')),
        (New-Hint 'Systemwichtiges und nützliche Hersteller-Apps (Vantage, SupportAssist, MyASUS) bleiben. Entfernte Apps lassen sich im Store zurückholen.'))) +
    (New-StepCard (New-StepHead '5' 'Programme installieren' 'WizOnApps' '#2D7FF9') @(
        (New-Hint 'Profile wählen - installiert werden die vorausgewählten Programme der Profile. Eigene Profile (Seite Neues Gerät) stehen ebenfalls zur Wahl.'),
        '<WrapPanel x:Name="WizProfiles"/>',
        '<CheckBox x:Name="WizUseSetup" Content="Stattdessen genau die Auswahl der Seite &quot;Neues Gerät&quot; verwenden" Margin="0,6,0,0"/>')) +
    (New-StepCard (New-StepHead '6' 'Treiber und Updates' 'WizOnUpd' '#7C3AED') @(
        '<WrapPanel>',
        '<CheckBox x:Name="WizOemPack" Content="Komplettes Treiberpaket des Herstellers (Lenovo, HP, Dell)" IsChecked="True" Width="420" Margin="0,0,0,6"/>',
        '<CheckBox x:Name="WizDrivers" Content="Grafik-, Intel- und Windows-Update-Treiber" IsChecked="True" Width="420" Margin="0,0,0,6"/>',
        '<CheckBox x:Name="WizUpdates" Content="Windows-, Programm-, Store- und Defender-Updates" IsChecked="True" Width="420" Margin="0,0,0,6"/>',
        '<CheckBox x:Name="WizReboot" Content="Zwischendurch automatisch neu starten" IsChecked="True" Width="420" Margin="0,0,0,6"/>',
        '</WrapPanel>',
        (New-FieldRow 'Update-Runden (mit Neustart)' (& $comboMin 'WizRounds' @('1', '2', '3', '4', '5') 2)),
        (New-Hint 'Frische Windows-Installationen brauchen meist 2-3 Runden, bis wirklich alle Updates installiert sind. Nach jedem Neustart einfach anmelden - PC-Tools macht nach einer Minute allein weiter.'))) +
    (New-StepCard (New-StepHead '7' 'Benutzer, Netzlaufwerke und Drucker' 'WizOnNet' '#DB2777' $false) @(
        (New-Hint 'Eine Zeile pro Eintrag, Felder mit | trennen. Kennwörter werden verschlüsselt an diesen PC gebunden gespeichert.'),
        '<TextBlock Text="Benutzer:  Name | Kennwort | admin (optional)" FontWeight="SemiBold" Foreground="#1F2A44" Margin="0,4,0,2"/><TextBox x:Name="WizUsers" Height="54" AcceptsReturn="True" TextWrapping="NoWrap" VerticalScrollBarVisibility="Auto" FontFamily="Consolas" Padding="4"/>',
        '<TextBlock Text="Netzlaufwerke:  Buchstabe | \\Server\Freigabe | Benutzer | Kennwort" FontWeight="SemiBold" Foreground="#1F2A44" Margin="0,8,0,2"/><TextBox x:Name="WizDrives" Height="54" AcceptsReturn="True" TextWrapping="NoWrap" VerticalScrollBarVisibility="Auto" FontFamily="Consolas" Padding="4"/>',
        '<TextBlock Text="Drucker:  Name | IP-Adresse | Treiber (leer = automatisch)" FontWeight="SemiBold" Foreground="#1F2A44" Margin="0,8,0,2"/><TextBox x:Name="WizPrinters" Height="54" AcceptsReturn="True" TextWrapping="NoWrap" VerticalScrollBarVisibility="Auto" FontFamily="Consolas" Padding="4"/>')) +
    (New-StepCard (New-StepHead '8' 'Einstellungen vom alten PC' 'WizOnSet' '#52627A' $false) @(
        (New-Hint 'Ordner mit gesicherten Windows-Einstellungen (Seite "Einstellungen übertragen" auf dem alten PC).'),
        '<Grid><Grid.ColumnDefinitions><ColumnDefinition/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions><TextBox x:Name="WizSetDir" Padding="4,3"/><Button x:Name="BtnWizSetDir" Grid.Column="1" Content="..." Style="{StaticResource Sec}" Margin="8,0,0,0"/></Grid>',
        '<WrapPanel x:Name="WizSetItems" Margin="0,8,0,0"/>')) +
    (New-StepCard (New-StepHead '9' 'Unternehmen' 'WizOnCorp' '#0F766E' $false) @(
        (New-Hint 'Für Firmen-PCs: Domäne, Firmenangaben, Sicherheitsrichtlinien, Firmen-WLAN, VPN, Proxy, Zertifikate, Inventar. Leere Felder werden übersprungen.'),
        '<TextBlock Text="Firma und Inventar" FontWeight="SemiBold" Foreground="#1F2A44" Margin="0,4,0,4"/>',
        (New-FieldRow 'Firma / Besitzer' '<StackPanel Orientation="Horizontal"><TextBox x:Name="WizCoOrg" Width="220" Padding="4,3" ToolTip="Firmenname (Windows-Info)"/><TextBox x:Name="WizCoOwner" Width="200" Padding="4,3" Margin="8,0,0,0" ToolTip="Besitzer / Abteilung"/></StackPanel>'),
        (New-FieldRow 'Namensschema für PCs' '<StackPanel Orientation="Horizontal"><TextBox x:Name="WizCoNaming" Width="220" Padding="4,3" ToolTip="z.B. RR-{SERIAL} oder BUERO-{NR}"/><TextBlock Text="{}{SERIAL} = Seriennummer, {NR} = Inventarnummer, {TYP} = NB/PC" Foreground="#6B7890" FontSize="11.5" VerticalAlignment="Center" Margin="10,0,0,0"/></StackPanel>'),
        (New-FieldRow 'Inventarnummer' '<TextBox x:Name="WizCoAsset" Width="220" HorizontalAlignment="Left" Padding="4,3"/>'),
        (New-FieldRow 'Inventarliste (Ordner, z.B. NAS)' '<Grid><Grid.ColumnDefinitions><ColumnDefinition/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions><TextBox x:Name="WizCoInvDir" Padding="4,3" ToolTip="Jeder eingerichtete PC wird als Zeile in Inventar.csv eingetragen"/><Button x:Name="BtnWizCoInvDir" Grid.Column="1" Content="..." Style="{StaticResource Sec}" Margin="8,0,0,0"/></Grid>'),
        (New-FieldRow 'Support-Angaben (Einstellungen > System > Info)' '<StackPanel Orientation="Horizontal"><TextBox x:Name="WizCoSupName" Width="150" Padding="4,3" ToolTip="Name der IT / Firma"/><TextBox x:Name="WizCoSupPhone" Width="140" Padding="4,3" Margin="8,0,0,0" ToolTip="Telefon"/><TextBox x:Name="WizCoSupUrl" Width="200" Padding="4,3" Margin="8,0,0,0" ToolTip="Webseite oder Ticket-Portal"/></StackPanel>'),
        '<TextBlock Text="Domäne und Microsoft 365" FontWeight="SemiBold" Foreground="#1F2A44" Margin="0,10,0,4"/>',
        (New-FieldRow 'Active-Directory-Domäne' '<StackPanel Orientation="Horizontal"><TextBox x:Name="WizCoDomain" Width="200" Padding="4,3" ToolTip="z.B. firma.local"/><TextBox x:Name="WizCoOu" Width="240" Padding="4,3" Margin="8,0,0,0" ToolTip="OU (optional), z.B. OU=Clients,DC=firma,DC=local"/></StackPanel>'),
        (New-FieldRow 'Beitritts-Konto' '<StackPanel Orientation="Horizontal"><TextBox x:Name="WizCoDomUser" Width="200" Padding="4,3" ToolTip="FIRMA\admin oder admin@firma.local"/><PasswordBox x:Name="WizCoDomPwd" Width="160" Padding="4,3" Margin="8,0,0,0"/></StackPanel>'),
        (New-FieldRow 'Microsoft-365-Mandanten-ID' '<TextBox x:Name="WizCoTenant" Width="320" HorizontalAlignment="Left" Padding="4,3" ToolTip="Für OneDrive: Desktop/Dokumente/Bilder automatisch in OneDrive sichern (Mandanten-ID aus dem Entra-Admin-Center)"/>'),
        '<CheckBox x:Name="WizCoEntra" Content="Am Ende &quot;Arbeits- oder Schulkonto verbinden&quot; öffnen (Microsoft Entra ID / Intune)" Margin="0,4,0,0"/>',
        '<TextBlock Text="Sicherheitsrichtlinien" FontWeight="SemiBold" Foreground="#1F2A44" Margin="0,10,0,4"/>',
        (New-FieldRow 'Bildschirm sperren nach (Minuten)' '<TextBox x:Name="WizCoLock" Width="60" HorizontalAlignment="Left" Padding="4,3" Text="10"/>'),
        (New-FieldRow 'Kennwörter lokaler Konten' '<StackPanel Orientation="Horizontal"><TextBlock Text="min. Länge" VerticalAlignment="Center" Margin="0,0,6,0"/><TextBox x:Name="WizCoPwLen" Width="40" Text="12"/><TextBlock Text="Sperre nach Fehlversuchen" VerticalAlignment="Center" Margin="14,0,6,0"/><TextBox x:Name="WizCoPwLock" Width="40" Text="10"/></StackPanel>'),
        (New-FieldRow 'USB-Speicher (Sticks, Platten)' (& $comboMin 'WizCoUsb' @('erlaubt', 'nur lesen', 'gesperrt') 0)),
        (New-FieldRow 'Angriffsflächen-Regeln (Defender)' (& $comboMin 'WizCoAsr' @('nicht ändern', 'nur protokollieren', 'blockieren') 0).Replace('Width="140"', 'Width="180"')),
        '<WrapPanel Margin="0,4,0,0"><CheckBox x:Name="WizCoAdminOff" Content="Integriertes Administratorkonto deaktivieren" IsChecked="True" Width="360" Margin="0,0,0,6"/><CheckBox x:Name="WizCoNoConsumer" Content="Keine Werbe-/Verbraucherfunktionen (Store-Vorschläge, Tipps)" IsChecked="True" Width="400" Margin="0,0,0,6"/></WrapPanel>',
        (New-FieldRow 'Anmeldehinweis (Titel | Text)' '<TextBox x:Name="WizCoLegal" Padding="4,3" ToolTip="z.B. Firmeneigentum | Nutzung nur für dienstliche Zwecke. Aktivitäten können protokolliert werden."/>'),
        (New-FieldRow 'Firmenbild Sperrbildschirm / Desktop' '<Grid><Grid.ColumnDefinitions><ColumnDefinition/><ColumnDefinition Width="Auto"/><ColumnDefinition/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions><TextBox x:Name="WizCoLockImg" Padding="4,3" ToolTip="Bild für den Sperrbildschirm"/><Button x:Name="BtnWizCoLockImg" Grid.Column="1" Content="..." Style="{StaticResource Sec}" Margin="6,0,10,0"/><TextBox x:Name="WizCoDeskImg" Grid.Column="2" Padding="4,3" ToolTip="Bild für den Desktop-Hintergrund"/><Button x:Name="BtnWizCoDeskImg" Grid.Column="3" Content="..." Style="{StaticResource Sec}" Margin="6,0,0,0"/></Grid>'),
        '<TextBlock Text="Netzwerk" FontWeight="SemiBold" Foreground="#1F2A44" Margin="0,10,0,4"/>',
        (New-FieldRow 'Firmen-WLAN (SSID / Kennwort)' '<StackPanel Orientation="Horizontal"><TextBox x:Name="WizCoWifi" Width="200" Padding="4,3"/><PasswordBox x:Name="WizCoWifiPwd" Width="160" Padding="4,3" Margin="8,0,0,0"/></StackPanel>'),
        (New-FieldRow 'VPN (Name / Server / Art / Schlüssel)' '<StackPanel Orientation="Horizontal"><TextBox x:Name="WizCoVpnName" Width="130" Padding="4,3" ToolTip="Anzeigename"/><TextBox x:Name="WizCoVpnSrv" Width="170" Padding="4,3" Margin="6,0,0,0" ToolTip="vpn.firma.de"/><ComboBox x:Name="WizCoVpnType" Width="110" Margin="6,0,0,0" SelectedIndex="0"><ComboBoxItem Content="IKEv2"/><ComboBoxItem Content="SSTP"/><ComboBoxItem Content="L2TP"/></ComboBox><PasswordBox x:Name="WizCoVpnPsk" Width="120" Padding="4,3" Margin="6,0,0,0" ToolTip="Vorinstallierter Schlüssel (nur L2TP)"/></StackPanel>'),
        (New-FieldRow 'Proxy (Server:Port / Ausnahmen)' '<StackPanel Orientation="Horizontal"><TextBox x:Name="WizCoProxy" Width="200" Padding="4,3" ToolTip="proxy.firma.local:8080"/><TextBox x:Name="WizCoProxyEx" Width="240" Padding="4,3" Margin="8,0,0,0" ToolTip="*.firma.local;&lt;local&gt;"/></StackPanel>'),
        (New-FieldRow 'Zeitserver' '<TextBox x:Name="WizCoNtp" Width="220" HorizontalAlignment="Left" Padding="4,3" ToolTip="z.B. dc01.firma.local oder ptbtime1.ptb.de"/>'),
        (New-FieldRow 'Zertifikate (Ordner mit .cer/.crt)' '<Grid><Grid.ColumnDefinitions><ColumnDefinition/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions><TextBox x:Name="WizCoCertDir" Padding="4,3" ToolTip="Stammzertifikate der Firma (z.B. für Proxy, WLAN, interne Webseiten)"/><Button x:Name="BtnWizCoCertDir" Grid.Column="1" Content="..." Style="{StaticResource Sec}" Margin="8,0,0,0"/></Grid>'))) +
    (New-StepCard (New-StepHead '10' 'Sicherheit und Abschluss' 'WizOnFinish' '#16A34A') @(
        '<CheckBox x:Name="WizBitLocker" Content="BitLocker für Laufwerk C: einschalten (TPM nötig) und Wiederherstellungsschlüssel sichern" Margin="0,0,0,4"/>',
        (New-FieldRow 'Schlüssel zusätzlich speichern in' '<Grid><Grid.ColumnDefinitions><ColumnDefinition/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions><TextBox x:Name="WizKeyDir" Padding="4,3" ToolTip="z.B. \\NAS\Sicherung\BitLocker oder ein USB-Stick"/><Button x:Name="BtnWizKeyDir" Grid.Column="1" Content="..." Style="{StaticResource Sec}" Margin="8,0,0,0"/></Grid>'),
        '<CheckBox x:Name="WizCarefree" Content="Sorgenfrei-Modus: wöchentliche Pflege, Selbst-Update, Wiederherstellungspunkte, Firewall" IsChecked="True" Margin="0,8,0,4"/>',
        '<CheckBox x:Name="WizReport" Content="Einrichtungsprotokoll als PDF (Programme, Einstellungen, Zustand)" IsChecked="True"/>')) +
    (New-Card 'Los geht''s' @(
        '<TextBlock x:Name="WizSummary" TextWrapping="Wrap" Foreground="#1F2A44" Margin="0,0,0,10"/>',
        '<WrapPanel><Button x:Name="BtnWizStart" Content="Alles einrichten"/><Button x:Name="BtnWizSave" Content="Als Vorlage speichern ..." Style="{StaticResource Sec}"/><Button x:Name="BtnWizLoad" Content="Vorlage laden ..." Style="{StaticResource Sec}"/><Button x:Name="BtnWizStick" Content="Für automatische Windows-Installation verwenden" Style="{StaticResource Sec}"/><Button x:Name="BtnWizCheck" Content="Danach: Neugerät-Check" Style="{StaticResource Sec}"/></WrapPanel>')))

# ---- Neugerät-Check
$pageCheck = New-Page 'Neugerät-Check' 'Neuen (oder gebrauchten) PC in den ersten Tagen gründlich prüfen - solange Rückgabe und Umtausch noch einfach sind: Bildschirm, Tastatur, Kamera, Mikrofon, Lautsprecher, Anschlüsse, WLAN und Bluetooth, Akku, SSD, Arbeitsspeicher und ein Belastungstest mit Temperaturen. Am Ende gibt es einen Prüfbericht.' (
    ('<Border CornerRadius="16" Padding="22,16" Margin="0,0,4,16" Background="{StaticResource HeroGrad}"><Grid><Grid.ColumnDefinitions><ColumnDefinition/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>' +
     '<StackPanel><TextBlock x:Name="ChkTitle" Text="Noch nichts geprüft" Foreground="#FFFFFF" FontSize="22" FontWeight="SemiBold"/><TextBlock x:Name="ChkSub" Text="Tests der Reihe nach anklicken - jeder dauert nur wenige Sekunden bis Minuten." Foreground="#FFFFFF" Opacity="0.92" TextWrapping="Wrap" Margin="0,4,0,0"/></StackPanel>' +
     '<StackPanel Grid.Column="1" Orientation="Horizontal" VerticalAlignment="Center"><Border Background="#33FFFFFF" CornerRadius="10" Padding="14,8" Margin="0,0,8,0"><StackPanel><TextBlock x:Name="ChkOk" Text="0" Foreground="#FFFFFF" FontSize="22" FontWeight="Bold" HorizontalAlignment="Center"/><TextBlock Text="in Ordnung" Foreground="#FFFFFF" FontSize="11"/></StackPanel></Border>' +
     '<Border Background="#33FFFFFF" CornerRadius="10" Padding="14,8" Margin="0,0,8,0"><StackPanel><TextBlock x:Name="ChkBad" Text="0" Foreground="#FFFFFF" FontSize="22" FontWeight="Bold" HorizontalAlignment="Center"/><TextBlock Text="Fehler" Foreground="#FFFFFF" FontSize="11"/></StackPanel></Border>' +
     '<Border Background="#33FFFFFF" CornerRadius="10" Padding="14,8"><StackPanel><TextBlock x:Name="ChkOpen" Text="0" Foreground="#FFFFFF" FontSize="22" FontWeight="Bold" HorizontalAlignment="Center"/><TextBlock Text="offen" Foreground="#FFFFFF" FontSize="11"/></StackPanel></Border></StackPanel></Grid></Border>') +
    (New-Card 'Tests' @('<WrapPanel x:Name="ChkTiles"/>')) +
    (New-Card 'Messwerte und Protokoll' @(
        '<TextBox x:Name="ChkLog" Height="220" IsReadOnly="True" TextWrapping="Wrap" VerticalScrollBarVisibility="Auto" FontFamily="Consolas" FontSize="12" Padding="8"/>',
        '<WrapPanel Margin="0,10,0,0"><Button x:Name="BtnChkReport" Content="Prüfbericht als PDF ..."/><Button x:Name="BtnChkAuto" Content="Alle automatischen Tests starten" Style="{StaticResource Sec}"/><Button x:Name="BtnChkReset" Content="Neu beginnen" Style="{StaticResource Sec}"/><Button x:Name="BtnChkWarranty" Content="Garantie prüfen" Style="{StaticResource Sec}"/></WrapPanel>')))

# ---- Automatische Windows-Installation (Antwortdatei)
$pageUnattend = New-Page 'Automatische Installation' 'Einen Windows-USB-Stick so vorbereiten, dass die Installation ohne Fragen durchläuft: deutsche Sprache und Tastatur, lokales Konto ohne Zwang zum Microsoft-Konto, keine Werbe-Apps, Datenschutz-Fragen übersprungen. Nach der ersten Anmeldung richtet sich PC-Tools selbst ein und führt den Einrichtungs-Assistenten mit deinen Einstellungen aus.' (
    (New-Card '1. Windows-Installation' @(
        (New-FieldRow 'Sprache und Tastatur' (& $comboMin 'UaLang' @('de-DE', 'de-AT', 'de-CH', 'en-US') 0)),
        (New-FieldRow 'Edition' (& $comboMin 'UaEdition' @('Pro', 'Home', 'Pro for Workstations', 'Education', 'beim Setup fragen') 0).Replace('Width="140"', 'Width="220"')),
        (New-FieldRow 'Computername (leer = zufällig)' '<TextBox x:Name="UaName" Width="220" HorizontalAlignment="Left" Padding="4,3"/>'),
        (New-FieldRow 'Zeitzone' '<ComboBox x:Name="UaTz" Width="420" HorizontalAlignment="Left"/>'),
        (New-FieldRow 'Benutzername (Administrator)' '<TextBox x:Name="UaUser" Width="220" HorizontalAlignment="Left" Padding="4,3"/>'),
        (New-FieldRow 'Kennwort (leer = ohne)' '<PasswordBox x:Name="UaPwd" Width="220" HorizontalAlignment="Left" Padding="4,3"/>'),
        '<WrapPanel Margin="0,8,0,0">',
        '<CheckBox x:Name="UaNoConsumer" Content="Keine Werbe-Apps und Vorschläge" IsChecked="True" Width="360" Margin="0,0,0,6"/>',
        '<CheckBox x:Name="UaNoBitLocker" Content="Keine automatische Geräteverschlüsselung" Width="360" Margin="0,0,0,6"/>',
        '<CheckBox x:Name="UaWifi" Content="WLAN-Auswahl während der Installation zeigen" IsChecked="True" Width="360" Margin="0,0,0,6"/>',
        '<CheckBox x:Name="UaBypass" Content="Windows-11-Prüfung (TPM, CPU, Secure Boot) umgehen" Width="360" Margin="0,0,0,6"/>',
        '</WrapPanel>',
        (New-Hint 'Das Setup fragt weiterhin, auf welche Festplatte/Partition installiert wird - so wird nie versehentlich eine falsche Platte gelöscht. Kennwort ohne Anführungszeichen. Windows-11-Prüfung umgehen nur für ältere PCs, die offiziell nicht unterstützt sind.'))) +
    (New-Card '2. Nach der Installation' @(
        '<CheckBox x:Name="UaRunPflege" Content="PC-Tools auf den Stick kopieren und beim ersten Anmelden den Einrichtungs-Assistenten ausführen" IsChecked="True"/>',
        '<CheckBox x:Name="UaToken" Content="Zugang für Updates von PC-Tools mitkopieren (nur auf eigene Sticks)" IsChecked="True" Margin="0,6,0,0"/>',
        '<TextBlock x:Name="UaSpecInfo" Foreground="#1F2A44" TextWrapping="Wrap" Margin="0,8,0,0"/>',
        '<WrapPanel Margin="0,6,0,0"><Button x:Name="BtnUaWizard" Content="Assistent-Einstellungen bearbeiten" Style="{StaticResource Sec}"/></WrapPanel>')) +
    (New-Card '3. Auf den USB-Stick schreiben' @(
        (New-Hint 'Der Stick muss bereits ein Windows-Installationsstick sein (Seite "Windows und Office" > USB-Stick, oder Media Creation Tool). Die Antwortdatei kommt ins Hauptverzeichnis, PC-Tools in den Ordner PCPflege.'),
        '<WrapPanel><ComboBox x:Name="UaDrive" Width="360" Margin="0,0,10,8"/><Button x:Name="BtnUaRefresh" Content="Laufwerke neu suchen" Style="{StaticResource Sec}"/><Button x:Name="BtnUaWrite" Content="Auf Stick schreiben"/><Button x:Name="BtnUaSave" Content="Nur autounattend.xml speichern ..." Style="{StaticResource Sec}"/><Button x:Name="BtnUaMedia" Content="Windows-Stick erstellen" Style="{StaticResource Sec}"/></WrapPanel>',
        '<TextBlock x:Name="UaInfo" TextWrapping="Wrap" Foreground="#1F2A44" Margin="0,6,0,0"/>')))

# ---- Einstellungen übertragen
$pageWinSet = New-Page 'Einstellungen übertragen' 'Windows so einrichten wie auf dem alten PC: Taskleiste, Startmenü, Explorer, Design und Hintergrund, Maus und Tastatur, Region, Energieplan, WLAN-Profile, Drucker, Netzlaufwerke, Schriftarten, Outlook-Signaturen, Standard-Apps und mehr. Ergänzt den PC-Umzug (der die Dateien und Programme übernimmt).' (
    (New-Card 'Was soll übertragen werden?' @('<WrapPanel x:Name="WsItems"/>', '<WrapPanel Margin="0,6,0,0"><Button x:Name="BtnWsAll" Content="Alle" Style="{StaticResource Sec}"/><Button x:Name="BtnWsNone" Content="Keine" Style="{StaticResource Sec}"/></WrapPanel>')) +
    (New-Card 'Alter PC: Einstellungen sichern' @(
        '<Grid><Grid.ColumnDefinitions><ColumnDefinition/><ColumnDefinition Width="Auto"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions><TextBox x:Name="WsExpDir" Padding="4,3"/><Button x:Name="BtnWsExpDir" Grid.Column="1" Content="..." Style="{StaticResource Sec}" Margin="8,0,0,0"/><Button x:Name="BtnWsExport" Grid.Column="2" Content="Jetzt sichern" Margin="8,0,0,0"/></Grid>',
        (New-Hint 'Z.B. ein USB-Stick, eine externe Festplatte oder das NAS. Achtung: Der Ordner enthält WLAN-Kennwörter im Klartext - danach sicher aufbewahren oder löschen.'))) +
    (New-Card 'Neuer PC: Einstellungen übernehmen' @(
        '<Grid><Grid.ColumnDefinitions><ColumnDefinition/><ColumnDefinition Width="Auto"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions><TextBox x:Name="WsImpDir" Padding="4,3"/><Button x:Name="BtnWsImpDir" Grid.Column="1" Content="..." Style="{StaticResource Sec}" Margin="8,0,0,0"/><Button x:Name="BtnWsImport" Grid.Column="2" Content="Jetzt übernehmen" Margin="8,0,0,0"/></Grid>',
        '<TextBlock x:Name="WsImpInfo" TextWrapping="Wrap" Foreground="#1F2A44" Margin="0,6,0,0"/>',
        (New-Hint 'Der Explorer startet danach kurz neu. Standard-Apps kann Windows nur von Hand festlegen - PC-Tools zeigt die Liste und öffnet die passende Einstellung.'))) +
    (New-Card 'Ergebnis' @('<TextBox x:Name="WsLog" Height="160" IsReadOnly="True" TextWrapping="Wrap" VerticalScrollBarVisibility="Auto" FontFamily="Consolas" FontSize="12" Padding="8"/>')))

# ---- Konten, Laufwerke, Drucker
$pageAccounts = New-Page 'Konten und Netzwerk' 'Benutzerkonten verwalten, Netzlaufwerke (z.B. vom NAS) verbinden, BitLocker einschalten und den Schlüssel sicher ablegen.' (
    (New-Card 'Benutzerkonten' @(
        (New-White (New-DataGrid 'AccGrid' @('Name|Name|150', 'Voller Name|Full|170', 'Art|Kind|130', 'Aktiv|Enabled|70', 'Kennwort|PwdInfo|170', 'Letzte Anmeldung|Last|*') 'Height="170"')),
        '<WrapPanel Margin="0,8,0,0"><Button x:Name="BtnAccRefresh" Content="Neu einlesen" Style="{StaticResource Sec}"/><Button x:Name="BtnAccToggle" Content="Aktivieren / Deaktivieren" Style="{StaticResource Sec}"/><Button x:Name="BtnAccAdmin" Content="Administrator ja/nein" Style="{StaticResource Sec}"/><Button x:Name="BtnAccPwd" Content="Kennwort setzen ..." Style="{StaticResource Sec}"/><Button x:Name="BtnAccDel" Content="Löschen ..." Style="{StaticResource Sec}"/><Button x:Name="BtnAccHello" Content="Windows Hello / PIN" Style="{StaticResource Sec}"/><Button x:Name="BtnAccNetplwiz" Content="Automatisch anmelden (netplwiz)" Style="{StaticResource Sec}"/></WrapPanel>',
        '<Grid Margin="0,6,0,0"><Grid.ColumnDefinitions><ColumnDefinition Width="160"/><ColumnDefinition Width="180"/><ColumnDefinition Width="170"/><ColumnDefinition Width="Auto"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions><TextBox x:Name="AccName" Padding="4,3" Margin="0,0,8,0" ToolTip="Benutzername"/><TextBox x:Name="AccFull" Grid.Column="1" Padding="4,3" Margin="0,0,8,0" ToolTip="Voller Name (optional)"/><PasswordBox x:Name="AccPwdBox" Grid.Column="2" Padding="4,3" Margin="0,0,8,0" ToolTip="Kennwort (leer = ohne)"/><CheckBox x:Name="AccIsAdmin" Grid.Column="3" Content="Administrator" VerticalAlignment="Center" Margin="0,0,10,0"/><Button x:Name="BtnAccAdd" Grid.Column="4" Content="Konto anlegen" Margin="0"/></Grid>')) +
    (New-Card 'Netzlaufwerke' @(
        (New-White (New-DataGrid 'NdGrid' @('Laufwerk|Letter|80', 'Pfad|Path|*', 'Benutzer|User|160', 'Zustand|State|120') 'Height="140"')),
        '<Grid Margin="0,8,0,0"><Grid.ColumnDefinitions><ColumnDefinition Width="70"/><ColumnDefinition Width="*"/><ColumnDefinition Width="150"/><ColumnDefinition Width="150"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions><ComboBox x:Name="NdLetter" Margin="0,0,8,0"/><TextBox x:Name="NdPath" Grid.Column="1" Padding="4,3" Margin="0,0,8,0" ToolTip="\\NAS\Freigabe"/><TextBox x:Name="NdUser" Grid.Column="2" Padding="4,3" Margin="0,0,8,0" ToolTip="Benutzer (optional)"/><PasswordBox x:Name="NdPwd" Grid.Column="3" Padding="4,3" Margin="0,0,8,0" ToolTip="Kennwort"/><Button x:Name="BtnNdAdd" Grid.Column="4" Content="Verbinden" Margin="0"/></Grid>',
        '<WrapPanel Margin="0,8,0,0"><Button x:Name="BtnNdRefresh" Content="Neu einlesen" Style="{StaticResource Sec}"/><Button x:Name="BtnNdOpen" Content="Öffnen" Style="{StaticResource Sec}"/><Button x:Name="BtnNdDel" Content="Trennen" Style="{StaticResource Sec}"/><Button x:Name="BtnNdLinked" Content="Laufwerke auch in Admin-Programmen zeigen" Style="{StaticResource Sec}"/></WrapPanel>',
        (New-Hint 'Die Laufwerke werden dauerhaft für dein Konto gespeichert; der Zugang landet in der Windows-Anmeldeinformationsverwaltung. Im Explorer erscheinen sie sofort oder nach dem nächsten Anmelden.'))) +
    (New-Card 'Drucker' @('<WrapPanel><Button x:Name="BtnAccPrinters" Content="Drucker und Scanner einrichten und reparieren"/></WrapPanel>')) +
    (New-Card 'BitLocker und Anmeldung' @(
        '<TextBlock x:Name="AccBlState" TextWrapping="Wrap" Foreground="#1F2A44" FontWeight="SemiBold"/>',
        (New-FieldRow 'Schlüssel zusätzlich speichern in' '<Grid><Grid.ColumnDefinitions><ColumnDefinition/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions><TextBox x:Name="AccKeyDir" Padding="4,3"/><Button x:Name="BtnAccKeyDir" Grid.Column="1" Content="..." Style="{StaticResource Sec}" Margin="8,0,0,0"/></Grid>'),
        '<WrapPanel Margin="0,8,0,0"><Button x:Name="BtnAccBlOn" Content="BitLocker einschalten und Schlüssel sichern"/><Button x:Name="BtnAccBlVault" Content="Schlüssel in den Lizenz-Tresor" Style="{StaticResource Sec}"/><Button x:Name="BtnAccBlPage" Content="Alle Laufwerke (Seite Sicherheit)" Style="{StaticResource Sec}"/></WrapPanel>')))

# ---- Update-Steuerung
$pageUpdCtl = New-Page 'Update-Steuerung' 'Selbst bestimmen, wann und welche Windows-Updates kommen: pausieren, Funktionsupdates zurückstellen oder auf einer Windows-Version bleiben, Treiber aus Windows Update ausschließen, Nutzungszeit festlegen, einzelne Updates ausblenden und fehlerhafte Updates wieder entfernen.' (
    (New-Card 'Stand' @((New-InfoRow 'Windows' 'UcBuild'), (New-InfoRow 'Insider-Programm' 'UcInsider'), (New-InfoRow 'Pause' 'UcPause'), (New-InfoRow 'Regeln' 'UcRules'))) +
    (New-Card 'Updates pausieren' @(
        '<WrapPanel><Button x:Name="BtnUcPause7" Content="1 Woche" Style="{StaticResource Sec}"/><Button x:Name="BtnUcPause14" Content="2 Wochen" Style="{StaticResource Sec}"/><Button x:Name="BtnUcPause35" Content="5 Wochen (Maximum)" Style="{StaticResource Sec}"/><Button x:Name="BtnUcResume" Content="Pause aufheben"/></WrapPanel>',
        (New-Hint 'Praktisch vor wichtigen Terminen, auf Reisen oder wenn ein neues Update Probleme macht. Sicherheitsupdates danach bald nachholen.'))) +
    (New-Card 'Regeln' @(
        '<CheckBox x:Name="UcPin" Content="Auf dieser Windows-Version bleiben (kein Funktionsupdate auf eine neue Version):" Margin="0,0,0,4"/>',
        (New-FieldRow 'Version festhalten auf' '<ComboBox x:Name="UcPinVer" Width="140" HorizontalAlignment="Left" IsEditable="True"><ComboBoxItem Content="23H2"/><ComboBoxItem Content="24H2"/><ComboBoxItem Content="25H2"/><ComboBoxItem Content="26H2"/></ComboBox>'),
        (New-FieldRow 'Funktionsupdates später (Tage)' (& $comboMin 'UcDeferF' @('0', '7', '14', '30', '60', '90', '180', '365') 0)),
        (New-FieldRow 'Sicherheitsupdates später (Tage)' (& $comboMin 'UcDeferQ' @('0', '1', '3', '7', '14', '30') 0)),
        (New-FieldRow 'Nutzungszeit (kein Neustart)' '<StackPanel Orientation="Horizontal"><ComboBox x:Name="UcActS" Width="70"/><TextBlock Text="bis" Margin="8,0" VerticalAlignment="Center"/><ComboBox x:Name="UcActE" Width="70"/><TextBlock Text="Uhr" Margin="8,0" VerticalAlignment="Center"/></StackPanel>'),
        (New-FieldRow 'Store-Apps automatisch' (& $comboMin 'UcStore' @('Standard', 'an', 'aus') 0)),
        '<CheckBox x:Name="UcNoDrivers" Content="Keine Treiber über Windows Update (Treiber kommen dann nur noch über die Treiber-Seite)" Margin="0,6,0,0"/>',
        '<CheckBox x:Name="UcNoReboot" Content="Nie automatisch neu starten, solange jemand angemeldet ist" Margin="0,6,0,0"/>',
        '<CheckBox x:Name="UcPreview" Content="Neue Funktionen sofort erhalten (&quot;Erhalte die neuesten Updates, sobald sie verfügbar sind&quot;)" Margin="0,6,0,0"/>',
        '<WrapPanel Margin="0,10,0,0"><Button x:Name="BtnUcApply" Content="Regeln übernehmen"/><Button x:Name="BtnUcDefault" Content="Alles auf Windows-Standard" Style="{StaticResource Sec}"/><Button x:Name="BtnUcInsider" Content="Windows-Insider-Einstellungen" Style="{StaticResource Sec}"/></WrapPanel>')) +
    (New-Card 'Windows 11 auf nicht unterstützter Hardware (ohne TPM / Secure Boot)' @(
        '<TextBlock x:Name="UcHwState" Text="" Foreground="#6B7890" FontSize="12.5" TextWrapping="Wrap" Margin="0,0,0,8"/>',
        (New-Hint 'Für ältere, aber gesunde PCs: erlaubt das Upgrade auf Windows 11 (inkl. 26H2) trotz fehlendem TPM 2.0, Secure Boot oder nicht gelisteter CPU - und unterdrückt das "Systemanforderungen nicht erfüllt"-Wasserzeichen und die dauernden Hinweise. Setzt die bekannten Microsoft-Registry-Schalter (AllowUpgradesWithUnsupportedTPMOrCPU, LabConfig-Bypässe). Die Reparaturinstallation von der Seite Windows-Reparatur nutzt das dann automatisch mit.'),
        '<WrapPanel Margin="0,8,0,0"><Button x:Name="BtnUcBypassOn" Content="Erlauben + Hinweise aus"/><Button x:Name="BtnUcNagOff" Content="Nur Hinweise/Wasserzeichen aus" Style="{StaticResource Sec}"/><Button x:Name="BtnUcBypassOff" Content="Wieder auf Windows-Standard" Style="{StaticResource Sec}"/></WrapPanel>')) +
    (New-Card 'Verfügbare und ausgeblendete Updates' @(
        '<WrapPanel><Button x:Name="BtnUcSearch" Content="Nach Updates suchen"/><Button x:Name="BtnUcHide" Content="Ausblenden" Style="{StaticResource Sec}"/><Button x:Name="BtnUcShow" Content="Wieder einblenden" Style="{StaticResource Sec}"/><Button x:Name="BtnUcInstall" Content="Alle installieren (Seite Updates)" Style="{StaticResource Sec}"/></WrapPanel>',
        '<TextBlock x:Name="UcSearchInfo" Foreground="#6B7890" Margin="0,0,0,6"/>',
        (New-White (New-DataGrid 'UcGrid' @('Update|Title|*', 'KB|KB|110', 'Art|Kind|120', 'Größe|Size|80', 'Zustand|HiddenText|110') 'Height="200" SelectionMode="Extended"')))) +
    (New-Card 'Verlauf und Deinstallation' @(
        '<WrapPanel><Button x:Name="BtnUcHist" Content="Verlauf laden" Style="{StaticResource Sec}"/><Button x:Name="BtnUcUninst" Content="Gewähltes Update deinstallieren ..." Style="{StaticResource Sec}"/><Button x:Name="BtnUcRepair" Content="Windows Update reparieren" Style="{StaticResource Sec}"/></WrapPanel>',
        (New-White (New-DataGrid 'UcHistGrid' @('Datum|Date|130', 'Update|Title|*', 'KB|KB|100', 'Vorgang|Op|110', 'Ergebnis|Result|110', 'Fehlercode|Code|100') 'Height="240"')))))

# ---- Sicherheitslücken
$vulnGrid = '<DataGrid x:Name="VulnGrid" Height="420" SelectionMode="Extended"><DataGrid.RowStyle><Style TargetType="DataGridRow" BasedOn="{StaticResource {x:Type DataGridRow}}"><Style.Triggers>' +
    '<DataTrigger Binding="{Binding Level}" Value="0"><Setter Property="Foreground" Value="#C81E1E"/><Setter Property="FontWeight" Value="SemiBold"/></DataTrigger>' +
    '<DataTrigger Binding="{Binding Level}" Value="1"><Setter Property="Foreground" Value="#B45309"/></DataTrigger></Style.Triggers></Style></DataGrid.RowStyle><DataGrid.Columns>' +
    '<DataGridTextColumn Header="Zustand" Binding="{Binding Status}" Width="190"/><DataGridTextColumn Header="Programm" Binding="{Binding Name}" Width="260"/><DataGridTextColumn Header="Installiert" Binding="{Binding Version}" Width="110"/>' +
    '<DataGridTextColumn Header="Neu" Binding="{Binding Available}" Width="100"/><DataGridTextColumn Header="Warum" Binding="{Binding Why}" Width="*"/><DataGridTextColumn Header="Hersteller" Binding="{Binding Publisher}" Width="150"/></DataGrid.Columns></DataGrid>'
$pageVuln = New-Page 'Sicherheitslücken' 'Findet Programme mit bekannten Sicherheitslücken, Versionen ohne Updates (z.B. alte Java-, Python-, .NET- und Office-Versionen) und alles, wofür es eine neuere Version gibt - und aktualisiert oder entfernt sie mit einem Klick.' (
    ('<WrapPanel Margin="0,0,0,6">' + (New-StatTile 'VulnS0' 'kritisch (bekannte Lücke)' '#DC2626') + (New-StatTile 'VulnS1' 'veraltet oder Sicherheitsupdate' '#EA580C') + (New-StatTile 'VulnS2' 'normales Update verfügbar' '#2D7FF9') + (New-StatTile 'VulnS3' 'aktuell' '#16A34A') + '</WrapPanel>') +
    (New-Card 'Installierte Programme' @(
        '<Grid Margin="0,0,0,8"><Grid.ColumnDefinitions><ColumnDefinition Width="260"/><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions><ComboBox x:Name="VulnFilter" SelectedIndex="0" Margin="0,0,8,0"><ComboBoxItem Content="Nur mit Handlungsbedarf"/><ComboBoxItem Content="Alle Programme"/></ComboBox><TextBox x:Name="VulnSearch" Grid.Column="1" Padding="4,4" ToolTip="Suchen"/><Button x:Name="BtnVulnScan" Grid.Column="2" Content="Jetzt prüfen" Margin="8,0,0,0"/></Grid>',
        '<TextBlock x:Name="VulnInfo" Foreground="#6B7890" Margin="0,0,0,6" TextWrapping="Wrap" Text="Noch nicht geprüft."/>',
        (New-White $vulnGrid),
        '<WrapPanel Margin="0,10,0,0"><Button x:Name="BtnVulnFixAll" Content="Alle kritischen und Sicherheitsupdates installieren"/><Button x:Name="BtnVulnUpdate" Content="Gewählte aktualisieren" Style="{StaticResource Sec}"/><Button x:Name="BtnVulnRemove" Content="Gewählte deinstallieren ..." Style="{StaticResource Sec}"/><Button x:Name="BtnVulnWeb" Content="Lücken im Web nachschlagen" Style="{StaticResource Sec}"/></WrapPanel>',
        (New-Hint 'Die Liste bekannter Lücken wird mit jeder Version von PC-Tools erweitert. "Sicherheitsupdate" heißt: Programm mit Internetkontakt (Browser, PDF, Fernwartung, Messenger ...), für das eine neue Version bereitsteht - solche Updates schließen fast immer Lücken.'))))

# ---- Meine PCs: Fernaufträge und Anbindung
$fleetExtra = (New-Card 'Fernaufträge an andere PCs' @(
        '<CheckBox x:Name="Fleet_Remote" Content="Dieser PC nimmt Aufträge aus dem gemeinsamen Ordner an (prüft alle 10 Minuten)"/>',
        (New-Hint 'Einmal auf jedem PC einschalten. Danach kannst du von jedem PC aus z.B. die Pflege, Updates, eine Sicherung oder einen Neustart auf einem anderen PC anstoßen - ohne Fernwartungsprogramm. Es gibt nur diese festen Aktionen, keine beliebigen Befehle. Wer Schreibrechte auf den Ordner hat, kann Aufträge senden.'),
        '<Grid Margin="0,6,0,0"><Grid.ColumnDefinitions><ColumnDefinition Width="200"/><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions><ComboBox x:Name="RemPc" Margin="0,0,8,0"/><ComboBox x:Name="RemAction" Grid.Column="1" Margin="0,0,8,0"/><Button x:Name="BtnRemSend" Grid.Column="2" Content="Auftrag senden" Margin="0,0,8,0"/><Button x:Name="BtnRemRefresh" Grid.Column="3" Content="Aktualisieren" Style="{StaticResource Sec}" Margin="0"/></Grid>',
        '<TextBlock x:Name="RemSeen" Foreground="#6B7890" Margin="0,6,0,6"/>',
        (New-White (New-DataGrid 'RemGrid' @('Gesendet|Time|110', 'Auftrag|Action|*', 'Von|From|120', 'Zustand|State|100', 'Fertig|Done|110', 'Ergebnis|Msg|*') 'Height="170"')))) +
    (New-Card 'Anbindung an Home Assistant, RMM und eigene Systeme' @(
        (New-Hint 'Jeder PC meldet nach jeder Pflege, beim Öffnen von PC-Tools und (mit Fernaufträgen) alle 10 Minuten seinen Zustand. Kennwörter und Tokens werden verschlüsselt an diesen PC gebunden gespeichert.'),
        '<CheckBox x:Name="Integrate_MqttEnabled" Content="MQTT mit Home-Assistant-Autoerkennung (jeder PC erscheint als Gerät mit Sensoren)" FontWeight="SemiBold"/>',
        '<Grid Margin="24,6,0,8"><Grid.ColumnDefinitions><ColumnDefinition Width="230"/><ColumnDefinition Width="90"/><ColumnDefinition Width="160"/><ColumnDefinition Width="160"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions><TextBox x:Name="Integrate_MqttHost" Padding="4,3" Margin="0,0,8,0" ToolTip="Broker, z.B. 192.168.1.10 oder homeassistant.local"/><TextBox x:Name="Integrate_MqttPort" Grid.Column="1" Padding="4,3" Margin="0,0,8,0" ToolTip="Port (1883)"/><TextBox x:Name="Integrate_MqttUser" Grid.Column="2" Padding="4,3" Margin="0,0,8,0" ToolTip="Benutzer"/><PasswordBox x:Name="IntMqttPwd" Grid.Column="3" Padding="4,3" Margin="0,0,8,0" ToolTip="Kennwort (leer lassen = unverändert)"/><TextBox x:Name="Integrate_MqttTopic" Grid.Column="4" Padding="4,3" ToolTip="Basis-Topic (pcpflege)"/></Grid>',
        '<CheckBox x:Name="Integrate_HaEnabled" Content="Home Assistant direkt (REST-API mit langlebigem Zugangstoken)" FontWeight="SemiBold"/>',
        '<Grid Margin="24,6,0,8"><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="260"/></Grid.ColumnDefinitions><TextBox x:Name="Integrate_HaUrl" Padding="4,3" Margin="0,0,8,0" ToolTip="z.B. http://homeassistant.local:8123"/><PasswordBox x:Name="IntHaToken" Grid.Column="1" Padding="4,3" ToolTip="Token (leer lassen = unverändert)"/></Grid>',
        '<CheckBox x:Name="Integrate_RmmEnabled" Content="RMM / eigener Webhook (JSON per POST, optional mit Bearer-Token)" FontWeight="SemiBold"/>',
        '<Grid Margin="24,6,0,8"><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="260"/></Grid.ColumnDefinitions><TextBox x:Name="Integrate_RmmUrl" Padding="4,3" Margin="0,0,8,0" ToolTip="https://rmm.example/api/pcpflege"/><PasswordBox x:Name="IntRmmToken" Grid.Column="1" Padding="4,3" ToolTip="Token (leer lassen = unverändert)"/></Grid>',
        '<WrapPanel><Button x:Name="BtnIntSave" Content="Speichern"/><Button x:Name="BtnIntTest" Content="Jetzt senden (Test)" Style="{StaticResource Sec}"/><Button x:Name="BtnIntExample" Content="Beispiel für Home Assistant" Style="{StaticResource Sec}"/></WrapPanel>',
        '<TextBlock x:Name="IntInfo" TextWrapping="Wrap" Foreground="#1F2A44" Margin="0,6,0,0"/>'))
$pageFleet = Add-PageCards $pageFleet $fleetExtra

# ---- BIOS-Seite: Garantie
$pageBios = Add-PageCards $pageBios (New-Card 'Garantie' @(
        (New-InfoRow 'Garantie bis' 'WarEnd'), (New-InfoRow 'Details' 'WarDetails'),
        '<WrapPanel Margin="0,8,0,0"><Button x:Name="BtnWarCheck" Content="Online prüfen (Lenovo)"/><Button x:Name="BtnWarOpen" Content="Garantieseite des Herstellers" Style="{StaticResource Sec}"/><TextBlock Text="Selbst eintragen:" VerticalAlignment="Center" Margin="8,0,6,8"/><DatePicker x:Name="WarDate" Width="140" Margin="0,0,8,8"/><Button x:Name="BtnWarSave" Content="Speichern" Style="{StaticResource Sec}"/></WrapPanel>',
        (New-Hint 'Lenovo lässt sich direkt abfragen. Bei HP, Dell und anderen öffnet sich die Garantieseite (Seriennummer ist schon kopiert) - das Enddatum dann hier eintragen. Die Ampel warnt 60 Tage vor Ablauf, und "Meine PCs" zeigt das Datum für alle PCs.')))

# ---- Treiber-Seite: Hersteller-Treiberpaket
$pageDrv = Add-PageCards $pageDrv (New-Card 'Komplettes Treiberpaket des Herstellers' @(
        (New-Hint 'Ideal direkt nach einer frischen Windows-Installation: Lenovo (SCCM-Paket), HP (Driver Pack) und Dell (Driver Pack) bieten für jedes Firmenmodell ein komplettes Treiberpaket. PC-Tools sucht das passende Paket im offiziellen Katalog, prüft Prüfsumme und Signatur und installiert alle Treiber in einem Schritt - nur passende und neuere werden wirklich übernommen.'),
        '<TextBlock x:Name="OemPackInfo" TextWrapping="Wrap" Foreground="#1F2A44" FontWeight="SemiBold" Text="Noch nicht gesucht."/>',
        '<WrapPanel Margin="0,8,0,0"><Button x:Name="BtnOemPackFind" Content="Passendes Paket suchen" Style="{StaticResource Sec}"/><Button x:Name="BtnOemPackInstall" Content="Treiberpaket installieren"/></WrapPanel>'))


# ---- Drucker und Scanner
$prnGridX = '<DataGrid x:Name="PrnGrid" Height="190"><DataGrid.RowStyle><Style TargetType="DataGridRow" BasedOn="{StaticResource {x:Type DataGridRow}}"><Style.Triggers><DataTrigger Binding="{Binding Bad}" Value="True"><Setter Property="Foreground" Value="#C81E1E"/></DataTrigger></Style.Triggers></Style></DataGrid.RowStyle><DataGrid.Columns>' +
    '<DataGridTextColumn Header="Name" Binding="{Binding Name}" Width="220"/><DataGridTextColumn Header="Zustand" Binding="{Binding State}" Width="130"/><DataGridTextColumn Header="Standard" Binding="{Binding Default}" Width="70"/><DataGridTextColumn Header="Aufträge" Binding="{Binding Jobs}" Width="70"/>' +
    '<DataGridTextColumn Header="Treiber" Binding="{Binding Driver}" Width="220"/><DataGridTextColumn Header="Anschluss / Adresse" Binding="{Binding Port}" Width="*"/></DataGrid.Columns></DataGrid>'
$pagePrinter = New-Page 'Drucker und Scanner' 'Drucker und Multifunktionsgeräte (Drucken, Scannen, Kopieren, Fax) finden, mit dem vollständigen Treiber des Herstellers einrichten, verwalten und Druckprobleme automatisch finden und beheben: hängende Aufträge, "Offline", falsche IP-Adresse, Treiberfehler, Druckwarteschlange, Freigaben und Scanner.' (
    (New-Card 'Installierte Drucker' @(
        (New-White $prnGridX),
        '<WrapPanel Margin="0,8,0,0"><Button x:Name="BtnPrnRefresh" Content="Neu einlesen" Style="{StaticResource Sec}"/><Button x:Name="BtnPrnDefault" Content="Als Standard" Style="{StaticResource Sec}"/><Button x:Name="BtnPrnTest" Content="Testseite" Style="{StaticResource Sec}"/><Button x:Name="BtnPrnPrefs" Content="Druckeinstellungen" Style="{StaticResource Sec}"/><Button x:Name="BtnPrnQueueOpen" Content="Warteschlange anzeigen" Style="{StaticResource Sec}"/><Button x:Name="BtnPrnQueue" Content="Aufträge löschen" Style="{StaticResource Sec}"/><Button x:Name="BtnPrnSpoolReset" Content="Warteschlange bereinigen und neu starten"/><Button x:Name="BtnPrnWeb" Content="Weboberfläche des Geräts" Style="{StaticResource Sec}"/><Button x:Name="BtnPrnRename" Content="Umbenennen ..." Style="{StaticResource Sec}"/><Button x:Name="BtnPrnShare" Content="Freigeben / nicht freigeben" Style="{StaticResource Sec}"/><Button x:Name="BtnPrnDel" Content="Entfernen" Style="{StaticResource Sec}"/><Button x:Name="BtnPrnSettings" Content="Windows-Druckereinstellungen" Style="{StaticResource Sec}"/></WrapPanel>',
        '<TextBlock x:Name="PrnSelInfo" TextWrapping="Wrap" Foreground="#6B7890" Margin="0,4,0,0"/>')) +
    (New-Card 'Drucker und Multifunktionsgeräte finden' @(
        (New-Hint 'Sucht im eigenen Netz nach Druckern und Multifunktionsgeräten (Anschlüsse 9100, 631, 515) und fragt Hersteller und Modell ab (SNMP und Weboberfläche). Per USB angeschlossene Geräte stehen darunter.'),
        '<WrapPanel><Button x:Name="BtnPrnScan" Content="Im Netz suchen"/><Button x:Name="BtnPrnUsb" Content="USB-Geräte anzeigen" Style="{StaticResource Sec}"/><Button x:Name="BtnPrnWinAdd" Content="Windows-Assistent &quot;Drucker hinzufügen&quot;" Style="{StaticResource Sec}"/></WrapPanel>',
        (New-White (New-DataGrid 'PrnFound' @('Adresse|Ip|120', 'Hersteller|Vendor|110', 'Modell|Model|240', 'Anschlüsse|Ports|100', 'Name im Netz|Host|*', 'Schon eingerichtet|Known|110') 'Height="150"') 'Margin="0,8,0,0"'))) +
    (New-Card 'Einrichten - mit dem richtigen Treiber' @(
        '<Grid><Grid.ColumnDefinitions><ColumnDefinition Width="230"/><ColumnDefinition Width="160"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions><TextBox x:Name="PrnName" Padding="4,3" Margin="0,0,8,0" ToolTip="Name, z.B. Büro-Drucker"/><TextBox x:Name="PrnIp" Grid.Column="1" Padding="4,3" Margin="0,0,8,0" ToolTip="IP-Adresse oder Name"/><TextBlock x:Name="PrnModelInfo" Grid.Column="2" VerticalAlignment="Center" Foreground="#1F2A44" FontWeight="SemiBold" TextTrimming="CharacterEllipsis"/></Grid>',
        '<TextBlock Text="Weg 1 - Vollständiges Hersteller-Paket (empfohlen für Multifunktionsgeräte: Drucken, Scannen, Fax, Tintenstand, Wartung)" FontWeight="SemiBold" Foreground="#1F2A44" Margin="0,12,0,4"/>',
        '<WrapPanel><Button x:Name="BtnPrnVendorPage" Content="Treiberseite des Herstellers für dieses Modell"/><Button x:Name="BtnPrnVendorApp" Content="Hersteller-App (winget/Store) suchen" Style="{StaticResource Sec}"/><Button x:Name="BtnPrnPackage" Content="Heruntergeladenes Paket installieren ..." Style="{StaticResource Sec}"/></WrapPanel>',
        '<ListBox x:Name="PrnVendorApps" Height="80" Margin="0,4,0,0"/>',
        '<TextBlock Text="Weg 2 - Treiber aus Windows (ohne Download)" FontWeight="SemiBold" Foreground="#1F2A44" Margin="0,12,0,4"/>',
        '<Grid><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions><ComboBox x:Name="PrnDriver" IsEditable="True" Margin="0,0,8,0"/><Button x:Name="BtnPrnWuDrv" Grid.Column="1" Content="Treiber über Windows Update nachladen" Style="{StaticResource Sec}" Margin="0,0,8,0"/><Button x:Name="BtnPrnAdd" Grid.Column="2" Content="Drucker einrichten" Margin="0"/></Grid>',
        '<WrapPanel Margin="0,8,0,0"><CheckBox x:Name="PrnSetDefault" Content="Als Standarddrucker" Margin="0,0,20,0"/><CheckBox x:Name="PrnNoSnmp" Content="SNMP-Statusabfrage aus (verhindert falsches &quot;Offline&quot;)" IsChecked="True" Margin="0,0,20,0"/><CheckBox x:Name="PrnTestAfter" Content="Danach Testseite drucken" IsChecked="True"/></WrapPanel>',
        (New-Hint '"Microsoft IPP Class Driver" funktioniert ohne Herstellertreiber mit fast allen modernen Druckern (Mopria/AirPrint). Für Scannen, Fax, Tintenstand und alle Druckoptionen das Herstellerpaket installieren - danach steht dessen Treiber oben in der Liste.'))) +
