# ---- Netzwerk-Sicherheit
$nsGrid = '<DataGrid x:Name="NsGrid" Height="330" SelectionMode="Extended"><DataGrid.RowStyle><Style TargetType="DataGridRow" BasedOn="{StaticResource {x:Type DataGridRow}}"><Style.Triggers>' +
    '<DataTrigger Binding="{Binding Rank}" Value="0"><Setter Property="Foreground" Value="#C81E1E"/><Setter Property="FontWeight" Value="SemiBold"/></DataTrigger><DataTrigger Binding="{Binding Rank}" Value="1"><Setter Property="Foreground" Value="#B45309"/></DataTrigger><DataTrigger Binding="{Binding Rank}" Value="3"><Setter Property="Foreground" Value="#15803D"/></DataTrigger>' +
    '</Style.Triggers></Style></DataGrid.RowStyle><DataGrid.Columns><DataGridTextColumn Header="Risiko" Binding="{Binding LevelText}" Width="80"/><DataGridTextColumn Header="Bereich" Binding="{Binding Area}" Width="130"/><DataGridTextColumn Header="Befund" Binding="{Binding Title}" Width="280"/>' +
    '<DataGridTextColumn Header="Details" Binding="{Binding Detail}" Width="*"/><DataGridTextColumn Header="Lösung" Binding="{Binding FixText}" Width="200"/></DataGrid.Columns></DataGrid>'
$pageNetSec = New-Page 'Netzwerk-Sicherheit' 'Findet Schwachstellen in deinem Heim- oder Firmennetz und hilft, sie zu schließen: offene und riskante Dienste auf allen Geräten (Telnet, FTP, VNC, Datenbanken, unverschlüsselte Weboberflächen), Portfreigaben im Router per UPnP, veraltete Protokolle (SMBv1, LLMNR, NetBIOS), Firewall, Netzwerkprofil, Freigaben, WLAN-Verschlüsselung, offene Anschlüsse dieses PCs und mehr. Geprüft wird nur das eigene Netz, es wird nichts angegriffen.' (
    ('<WrapPanel Margin="0,0,0,6">' + (New-StatTile 'NsS0' 'hohes Risiko' '#DC2626') + (New-StatTile 'NsS1' 'mittleres Risiko' '#EA580C') + (New-StatTile 'NsS2' 'Hinweise' '#2D7FF9') + (New-StatTile 'NsS3' 'in Ordnung' '#16A34A') + (New-StatTile 'NsDev' 'Geräte im Netz' '#6D4AE8') + '</WrapPanel>') +
    (New-Card 'Prüfung' @(
        '<WrapPanel><CheckBox x:Name="NsLocal" Content="Dieser PC (Firewall, Protokolle, Freigaben, offene Anschlüsse)" IsChecked="True" Margin="0,0,20,6"/><CheckBox x:Name="NsLan" Content="Alle Geräte im Netz (Anschluss-Scan)" IsChecked="True" Margin="0,0,20,6"/><CheckBox x:Name="NsRouter" Content="Router (UPnP-Portfreigaben, Fernwartung, Weboberfläche)" IsChecked="True" Margin="0,0,20,6"/><CheckBox x:Name="NsWifi" Content="WLAN (Verschlüsselung, offene Netze)" IsChecked="True" Margin="0,0,0,6"/></WrapPanel>',
        '<WrapPanel><Button x:Name="BtnNsScan" Content="Netzwerk jetzt prüfen"/><Button x:Name="BtnNsFix" Content="Gewählte beheben" Style="{StaticResource Sec}"/><Button x:Name="BtnNsFixAll" Content="Alle automatisch lösbaren beheben" Style="{StaticResource Sec}"/><Button x:Name="BtnNsReport" Content="Bericht als PDF ..." Style="{StaticResource Sec}"/><Button x:Name="BtnNsRouterWeb" Content="Router-Oberfläche öffnen" Style="{StaticResource Sec}"/></WrapPanel>',
        '<TextBlock x:Name="NsInfo" Foreground="#6B7890" Margin="0,4,0,6" TextWrapping="Wrap" Text="Noch nicht geprüft. Die Prüfung dauert je nach Netzgröße 20 Sekunden bis 2 Minuten."/>',
        '<ProgressBar x:Name="NsProgress" Height="6" IsIndeterminate="False" Visibility="Collapsed" Margin="0,0,0,8" Foreground="{StaticResource AccentGrad}" Background="#E3E8F2" BorderThickness="0"/>',
        '<Grid Margin="0,0,0,8"><Grid.ColumnDefinitions><ColumnDefinition Width="260"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions><ComboBox x:Name="NsFilter" SelectedIndex="0" Margin="0,0,8,0"><ComboBoxItem Content="Nur Handlungsbedarf"/><ComboBoxItem Content="Alles (auch in Ordnung)"/></ComboBox><TextBox x:Name="NsSearch" Grid.Column="1" Padding="4,4" ToolTip="Suchen"/></Grid>',
        (New-White $nsGrid))) +
    (New-Card 'Geräte im Netz' @(
        (New-White (New-DataGrid 'NsDevGrid' @('Adresse|Ip|120', 'Name|Host|200', 'MAC|Mac|140', 'Gerät|Kind|180', 'Offene Anschlüsse|Ports|*', 'Risiko|Risk|90') 'Height="240"')),
        '<WrapPanel Margin="0,8,0,0"><Button x:Name="BtnNsDevWeb" Content="Weboberfläche des Geräts" Style="{StaticResource Sec}"/><Button x:Name="BtnNsDevCopy" Content="Liste kopieren" Style="{StaticResource Sec}"/></WrapPanel>')) +
    (New-Card 'Portfreigaben im Router (UPnP)' @(
        '<TextBlock x:Name="NsUpnpInfo" TextWrapping="Wrap" Foreground="#1F2A44" Text="-"/>',
        (New-White (New-DataGrid 'NsUpnpGrid' @('Von außen|Ext|90', 'Protokoll|Proto|80', 'An Gerät|Int|200', 'Beschreibung|Desc|*', 'Aktiv|On|60') 'Height="140"') 'Margin="0,8,0,0"'),
        (New-Hint 'Diese Anschlüsse sind aus dem Internet erreichbar, weil ein Gerät oder Programm sie über UPnP selbst im Router geöffnet hat. Unbekannte Einträge im Router löschen und UPnP dort am besten ausschalten.'))))


# ---- Treiber- und Update-Seite: Erweiterungen (7.2)
function Add-PageTop([string]$Page, [string]$Xaml) { $i = $Page.IndexOf("    </Grid>`n"); if ($i -lt 0) { $i = $Page.IndexOf("    </Grid>`r`n") }; $j = $Page.IndexOf("`n", $i) + 1; return $Page.Insert($j, $Xaml + "`n") }
$ucGrid = { param($n, $h) '<DataGrid x:Name="{0}" Height="{1}" SelectionMode="Extended"><DataGrid.RowStyle><Style TargetType="DataGridRow" BasedOn="{{StaticResource {{x:Type DataGridRow}}}}"><Style.Triggers><DataTrigger Binding="{{Binding Hot}}" Value="True"><Setter Property="Foreground" Value="#B45309"/><Setter Property="FontWeight" Value="SemiBold"/></DataTrigger></Style.Triggers></Style></DataGrid.RowStyle><DataGrid.Columns>' -f $n, $h }
$drvTop = ('<WrapPanel Margin="0,0,0,6">' + (New-StatTile 'DrvS0' 'Treiber installiert' '#2D7FF9') + (New-StatTile 'DrvS1' 'Geräte mit Problem' '#DC2626') + (New-StatTile 'DrvS2' 'Hersteller-Treiber älter als 3 Jahre' '#EA580C') + (New-StatTile 'DrvS3' 'Updates verfügbar' '#7C3AED') + (New-StatTile 'DrvS4' 'letzte Treibersicherung' '#0F766E') + '</WrapPanel>') +
    (New-Card 'Update-Center: alle verfügbaren Treiber-Updates' @(
        (New-Hint 'Sammelt in einem Durchgang alles, was es für diesen PC an neueren Treibern gibt: Grafik direkt bei NVIDIA und Intel, Intel WLAN und Bluetooth direkt bei Intel und alle (auch optionalen) Treiber aus Windows Update - mit installierter und neuer Version. Markieren und installieren.'),
        '<WrapPanel><Button x:Name="BtnUcDrvScan" Content="Nach Treiber-Updates suchen"/><Button x:Name="BtnUcDrvInstall" Content="Markierte installieren" Style="{StaticResource Sec}"/><Button x:Name="BtnUcDrvAll" Content="Alle installieren" Style="{StaticResource Sec}"/><CheckBox x:Name="UcDrvBackup" Content="Vorher alle Treiber sichern" IsChecked="True" VerticalAlignment="Center" Margin="8,0,0,8"/></WrapPanel>',
        '<TextBlock x:Name="UcDrvInfo" Text="Noch nicht gesucht." Foreground="#6B7890" Margin="0,0,0,6" TextWrapping="Wrap"/>',
        '<ProgressBar x:Name="UcDrvProg" Height="5" IsIndeterminate="True" Visibility="Collapsed" Margin="0,0,0,6" Foreground="{StaticResource AccentGrad}" Background="#E3E8F2" BorderThickness="0"/>',
        (New-White ((& $ucGrid 'UcDrvGrid' 260) + '<DataGridTextColumn Header="Quelle" Binding="{Binding Source}" Width="130"/><DataGridTextColumn Header="Gerät / Treiber" Binding="{Binding Name}" Width="*"/><DataGridTextColumn Header="Installiert" Binding="{Binding Have}" Width="140"/><DataGridTextColumn Header="Neu" Binding="{Binding New}" Width="140"/><DataGridTextColumn Header="Datum" Binding="{Binding Date}" Width="95"/><DataGridTextColumn Header="Größe" Binding="{Binding Size}" Width="80"/><DataGridTextColumn Header="Hinweis" Binding="{Binding Note}" Width="170"/></DataGrid.Columns></DataGrid>'))))
$drvBottom = (New-Card 'Ausgewählter Treiber' @(
        (New-InfoRow 'Gerät' 'DrvDName'), (New-InfoRow 'Treiber' 'DrvDVer'), (New-InfoRow 'Paket' 'DrvDInf'), (New-InfoRow 'Hardware-ID' 'DrvDHw'), (New-InfoRow 'Geräte-Instanz' 'DrvDDev'), (New-InfoRow 'Zustand' 'DrvDState'),
        '<WrapPanel Margin="0,8,0,0"><Button x:Name="BtnDrvFixDev" Content="Problem beheben"/><Button x:Name="BtnDrvHarm" Content="Als harmlos ausblenden / wieder zeigen" Style="{StaticResource Sec}"/><Button x:Name="BtnDrvRestartDev" Content="Gerät neu starten" Style="{StaticResource Sec}"/><Button x:Name="BtnDrvToggleDev" Content="Deaktivieren / Aktivieren" Style="{StaticResource Sec}"/><Button x:Name="BtnDrvUninstDev" Content="Gerät deinstallieren und neu erkennen ..." Style="{StaticResource Sec}"/><Button x:Name="BtnDrvDelPkg" Content="Treiberpaket löschen ..." Style="{StaticResource Sec}"/><Button x:Name="BtnDrvWuDev" Content="Bei Microsoft suchen (Katalog)" Style="{StaticResource Sec}"/><Button x:Name="BtnDrvDevMgr2" Content="Geräte-Manager" Style="{StaticResource Sec}"/></WrapPanel>',
        (New-Hint 'Zuerst oben in der Treiberliste ein Gerät anklicken. "Gerät neu starten" hilft oft bei WLAN, Bluetooth, Kamera oder Sound, ohne den PC neu zu starten. "Deinstallieren und neu erkennen" lädt den Treiber frisch.'))) +
    (New-Card 'Treiberspeicher (installierte Treiberpakete)' @(
        '<WrapPanel><Button x:Name="BtnDsLoad" Content="Einlesen" Style="{StaticResource Sec}"/><Button x:Name="BtnDsOld" Content="Alle älteren Versionen entfernen ..." Style="{StaticResource Sec}"/><Button x:Name="BtnDsDel" Content="Markierte entfernen ..." Style="{StaticResource Sec}"/><Button x:Name="BtnDsOpen" Content="Ordner öffnen" Style="{StaticResource Sec}"/></WrapPanel>',
