        '<WrapPanel><Button x:Name="BtnDbNew" Content="Jetzt alle Treiber sichern" Style="{StaticResource Sec}"/><Button x:Name="BtnDbRestore" Content="Gewählte Sicherung zurückspielen ..." Style="{StaticResource Sec}"/><Button x:Name="BtnDbOpen" Content="Ordner öffnen" Style="{StaticResource Sec}"/><Button x:Name="BtnDbCopy" Content="Auf Stick/NAS kopieren ..." Style="{StaticResource Sec}"/><Button x:Name="BtnDbDel" Content="Löschen" Style="{StaticResource Sec}"/></WrapPanel>',
