        (New-Hint 'Eine Treibersicherung enthält alle Treiber dieses PCs - ideal vor einer Windows-Neuinstallation: danach einfach zurückspielen, und alle Geräte laufen sofort.')))
$pageDrv = Add-PageCards (Add-PageTop $pageDrv $drvTop) $drvBottom

$updTop = ('<WrapPanel Margin="0,0,0,6">' + (New-StatTile 'UpS0' 'Windows-Updates offen' '#2D7FF9') + (New-StatTile 'UpS1' 'Programm-Updates' '#7C3AED') + (New-StatTile 'UpS2' 'Tage seit letztem Windows-Update' '#0F766E') + (New-StatTile 'UpS3' 'Neustart nötig' '#EA580C') + '</WrapPanel>') +
    (New-Card 'Stand' @((New-InfoRow 'Windows' 'UpWin'), (New-InfoRow 'Windows Update' 'UpWu'), (New-InfoRow 'Microsoft Office' 'UpOffice'), (New-InfoRow 'Virendefinitionen' 'UpDef'), (New-InfoRow 'winget / App-Installer' 'UpWinget'), (New-InfoRow 'PC-Tools' 'UpPflege'),
        '<WrapPanel Margin="0,8,0,0"><Button x:Name="BtnUpAll" Content="Alles aktualisieren (Windows, Programme, Store, Defender)"/><Button x:Name="BtnUpRefresh" Content="Stand neu einlesen" Style="{StaticResource Sec}"/><Button x:Name="BtnUpOffice" Content="Office jetzt aktualisieren" Style="{StaticResource Sec}"/><Button x:Name="BtnUpDef" Content="Virendefinitionen" Style="{StaticResource Sec}"/><Button x:Name="BtnUpStore" Content="Store-Updates" Style="{StaticResource Sec}"/><Button x:Name="BtnUpSelf" Content="PC-Tools aktualisieren" Style="{StaticResource Sec}"/><Button x:Name="BtnUpCtl" Content="Update-Steuerung" Style="{StaticResource Sec}"/></WrapPanel>')) +
    (New-Card 'Programm-Updates' @(
        '<Grid Margin="0,0,0,8"><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions><TextBox x:Name="UpAppSearch" Padding="4,4" ToolTip="Suchen"/><CheckBox x:Name="UpAppUnknown" Grid.Column="1" Content="auch Programme mit unbekannter Version" IsChecked="True" VerticalAlignment="Center" Margin="10,0,0,0"/></Grid>',
        '<WrapPanel><Button x:Name="BtnUpAppScan" Content="Nach Programm-Updates suchen"/><Button x:Name="BtnUpAppSel" Content="Markierte aktualisieren" Style="{StaticResource Sec}"/><Button x:Name="BtnUpAppAll" Content="Alle aktualisieren" Style="{StaticResource Sec}"/><Button x:Name="BtnUpAppExcl" Content="Nicht mehr aktualisieren" Style="{StaticResource Sec}"/><Button x:Name="BtnUpAppIncl" Content="Wieder aktualisieren" Style="{StaticResource Sec}"/><Button x:Name="BtnUpAppShow" Content="Details" Style="{StaticResource Sec}"/></WrapPanel>',
        '<TextBlock x:Name="UpAppInfo" Text="Noch nicht gesucht." Foreground="#6B7890" Margin="0,0,0,6" TextWrapping="Wrap"/>',
        (New-White ((& $ucGrid 'UpAppGrid' 300) + '<DataGridTextColumn Header="Programm" Binding="{Binding Name}" Width="*"/><DataGridTextColumn Header="Paket-ID" Binding="{Binding Id}" Width="230"/><DataGridTextColumn Header="Installiert" Binding="{Binding Version}" Width="120"/><DataGridTextColumn Header="Neu" Binding="{Binding Available}" Width="120"/><DataGridTextColumn Header="Hinweis" Binding="{Binding Note}" Width="190"/></DataGrid.Columns></DataGrid>')))) +
    (New-Card 'Windows-Updates' @(
        '<WrapPanel><Button x:Name="BtnUpWuScan" Content="Bei Microsoft suchen"/><Button x:Name="BtnUpWuSel" Content="Markierte installieren" Style="{StaticResource Sec}"/><Button x:Name="BtnUpWuAll" Content="Alle installieren" Style="{StaticResource Sec}"/><Button x:Name="BtnUpWuHide" Content="Ausblenden" Style="{StaticResource Sec}"/></WrapPanel>',
        '<TextBlock x:Name="UpWuInfo" Text="Noch nicht gesucht." Foreground="#6B7890" Margin="0,0,0,6" TextWrapping="Wrap"/>',
        (New-White ((& $ucGrid 'UpWuGrid' 220) + '<DataGridTextColumn Header="Update" Binding="{Binding Title}" Width="*"/><DataGridTextColumn Header="KB" Binding="{Binding KB}" Width="100"/><DataGridTextColumn Header="Art" Binding="{Binding Kind}" Width="130"/><DataGridTextColumn Header="Größe" Binding="{Binding Size}" Width="90"/><DataGridTextColumn Header="Neustart" Binding="{Binding Reboot}" Width="80"/></DataGrid.Columns></DataGrid>')))) +
    (New-Card 'Zuletzt aktualisiert' @(
        '<WrapPanel><Button x:Name="BtnUpHist" Content="Aus den Protokollen lesen" Style="{StaticResource Sec}"/></WrapPanel>',
