# ---- Netzwerk-Diagnose
$ndGridX = '<DataGrid x:Name="NdFindGrid" Height="330"><DataGrid.RowStyle><Style TargetType="DataGridRow" BasedOn="{StaticResource {x:Type DataGridRow}}"><Style.Triggers>' +
    '<DataTrigger Binding="{Binding Rank}" Value="0"><Setter Property="Foreground" Value="#C81E1E"/><Setter Property="FontWeight" Value="SemiBold"/></DataTrigger><DataTrigger Binding="{Binding Rank}" Value="1"><Setter Property="Foreground" Value="#B45309"/></DataTrigger><DataTrigger Binding="{Binding Rank}" Value="3"><Setter Property="Foreground" Value="#15803D"/></DataTrigger>' +
    '</Style.Triggers></Style></DataGrid.RowStyle><DataGrid.Columns><DataGridTextColumn Header="Ergebnis" Binding="{Binding StateText}" Width="90"/><DataGridTextColumn Header="Bereich" Binding="{Binding Area}" Width="170"/><DataGridTextColumn Header="Befund" Binding="{Binding Title}" Width="300"/>' +
    '<DataGridTextColumn Header="Details" Binding="{Binding Detail}" Width="*"/><DataGridTextColumn Header="Lösung (Doppelklick)" Binding="{Binding FixText}" Width="190"/></DataGrid.Columns></DataGrid>'
$ndAdX = '<DataGrid x:Name="NdAdGrid" Height="170"><DataGrid.RowStyle><Style TargetType="DataGridRow" BasedOn="{StaticResource {x:Type DataGridRow}}"><Style.Triggers><DataTrigger Binding="{Binding Bad}" Value="True"><Setter Property="Foreground" Value="#C81E1E"/><Setter Property="FontWeight" Value="SemiBold"/></DataTrigger></Style.Triggers></Style></DataGrid.RowStyle><DataGrid.Columns>' +
    '<DataGridTextColumn Header="Adapter" Binding="{Binding Name}" Width="140"/><DataGridTextColumn Header="Art" Binding="{Binding Kind}" Width="60"/><DataGridTextColumn Header="Status" Binding="{Binding Status}" Width="85"/><DataGridTextColumn Header="IPv4" Binding="{Binding Ip}" Width="150"/><DataGridTextColumn Header="Herkunft" Binding="{Binding Origin}" Width="170"/>' +
    '<DataGridTextColumn Header="Router" Binding="{Binding Gw}" Width="110"/><DataGridTextColumn Header="DNS" Binding="{Binding Dns}" Width="130"/><DataGridTextColumn Header="MAC" Binding="{Binding Mac}" Width="130"/><DataGridTextColumn Header="Gerät / Treiber" Binding="{Binding Desc}" Width="*"/></DataGrid.Columns></DataGrid>'
$pageNetDiag = New-Page 'Netzwerk-Diagnose' 'Tiefe Fehlersuche, wenn ein PC keine IPv4-Adresse bekommt (169.254.x.x, "Keine gültige IP-Konfiguration"), kein Internet hat oder das WLAN ständig abbricht. Alles funktioniert ohne Internet - ideal portabel vom USB-Stick. Jede Prüfung zeigt die Ursache und eine Lösung mit einem Klick.' (
    ('<WrapPanel Margin="0,0,0,6">' + (New-StatTile 'NdS0' 'Probleme' '#DC2626') + (New-StatTile 'NdS1' 'Hinweise' '#EA580C') + (New-StatTile 'NdS2' 'Adapter mit gültiger IPv4' '#2D7FF9') + (New-StatTile 'NdS3' 'Internet' '#16A34A') + '</WrapPanel>') +
    (New-Card 'Prüfen und reparieren' @(
        '<Border x:Name="NdBanner" Background="#FEF2F2" BorderBrush="#FCA5A5" BorderThickness="1" CornerRadius="8" Padding="12,8" Margin="0,0,0,10" Visibility="Collapsed"><TextBlock x:Name="NdBannerText" TextWrapping="Wrap" Foreground="#991B1B" FontWeight="SemiBold"/></Border>',
        '<WrapPanel><Button x:Name="BtnNdScan" Content="Jetzt prüfen"/><Button x:Name="BtnNdAuto" Content="Automatisch reparieren"/><Button x:Name="BtnNdLive" Content="DHCP-Live-Test (30 s)"/><Button x:Name="BtnNdLiveStatic" Content="Feste IP aus dem Test übernehmen" Style="{StaticResource Sec}"/><Button x:Name="BtnNdFix" Content="Gewählte Lösung anwenden" Style="{StaticResource Sec}"/><Button x:Name="BtnNdReport" Content="Bericht speichern" Style="{StaticResource Sec}"/><Button x:Name="BtnNdOpenDir" Content="Berichtsordner" Style="{StaticResource Sec}"/><Button x:Name="BtnNdDeep" Content="Tiefe Reparatur (Neustart) ..." Style="{StaticResource Sec}"/></WrapPanel>',
        '<TextBlock x:Name="NdInfo" Foreground="#6B7890" Margin="0,4,0,6" TextWrapping="Wrap" Text="Noch nicht geprüft."/>',
        '<ProgressBar x:Name="NdProgress" Height="6" IsIndeterminate="True" Visibility="Collapsed" Margin="0,0,0,8" Foreground="{StaticResource AccentGrad}" Background="#E3E8F2" BorderThickness="0"/>',
        (New-White $ndGridX),
        (New-Hint '"Automatisch reparieren" geht diese Schritte durch und hört auf, sobald eine gültige Adresse da ist: Dienste starten, Adapter und IPv4 einschalten, DHCP-Firewallregel, DHCP an, Energiesparen aus, Caches leeren, Adresse neu anfordern, Adapter neu starten, DHCP-Broadcast-Flag aus, zufällige MAC aus, fremde Filter aus, WLAN-Profil neu anlegen, Treiber neu laden. Ein Bericht mit allen Rohdaten wird automatisch gespeichert.'))) +
    (New-Card 'Netzwerkadapter' @(
        (New-White $ndAdX),
        '<WrapPanel Margin="0,8,0,0"><Button x:Name="BtnNdRenew" Content="Adresse neu anfordern" Style="{StaticResource Sec}"/><Button x:Name="BtnNdRestart" Content="Adapter neu starten" Style="{StaticResource Sec}"/><Button x:Name="BtnNdDhcp" Content="Auf automatisch (DHCP)" Style="{StaticResource Sec}"/><Button x:Name="BtnNdStatic" Content="Feste IP vorübergehend ..." Style="{StaticResource Sec}"/><Button x:Name="BtnNdPower" Content="Energiesparen aus" Style="{StaticResource Sec}"/><Button x:Name="BtnNdBcast" Content="DHCP-Broadcast-Flag aus" Style="{StaticResource Sec}"/><Button x:Name="BtnNdRand" Content="Zufällige MAC aus" Style="{StaticResource Sec}"/><Button x:Name="BtnNdMacTest" Content="Mit neuer MAC testen"/><Button x:Name="BtnNdMacBack" Content="Original-MAC zurück" Style="{StaticResource Sec}"/><Button x:Name="BtnNdNla" Content="Netzwerkprofile bereinigen" Style="{StaticResource Sec}"/><Button x:Name="BtnNdDrv" Content="Treiber neu installieren" Style="{StaticResource Sec}"/><Button x:Name="BtnNdOnOff" Content="Aktivieren / Deaktivieren" Style="{StaticResource Sec}"/><Button x:Name="BtnNdNcpa" Content="Netzwerkverbindungen (Windows)" Style="{StaticResource Sec}"/><Button x:Name="BtnNdDevMgr" Content="Geräte-Manager" Style="{StaticResource Sec}"/></WrapPanel>',
        '<TextBlock x:Name="NdAdInfo" TextWrapping="Wrap" Foreground="#6B7890" Margin="0,4,0,0"/>')) +
    (New-Card 'Hyper-V, WSL und Docker (virtuelle Netzwerke)' @(
        (New-Hint 'Hyper-V hängt die echten Adapter an virtuelle Switches: Dann spricht der Adapter selbst kein IPv4 mehr, die Adresse liegt auf "vEthernet (...)". Ist der Switch kaputt oder verwaist, gibt es kein IPv4 - IPv6 oft schon. Außerdem können WinNAT/ICS die DHCP-Anschlüsse (UDP 67/68) belegen.'),
        '<TextBlock x:Name="HvInfo" TextWrapping="Wrap" Foreground="#1F2A44" Margin="0,0,0,8" Text="-"/>',
        (New-White (New-DataGrid 'HvGrid' @('Switch|Name|170', 'Art|Type|90', 'Echter Adapter|Nic|*', 'Virtueller Adapter|VEth|170', 'IPv4|Ip|150', 'Zustand|State|200') 'Height="150"')),
        '<WrapPanel Margin="0,8,0,0"><Button x:Name="BtnHvUnbind" Content="Adapter vom Switch lösen"/><Button x:Name="BtnHvDel" Content="Switch löschen" Style="{StaticResource Sec}"/><Button x:Name="BtnHvWinNat" Content="WinNAT/HNS neu starten" Style="{StaticResource Sec}"/><Button x:Name="BtnHvIcsOff" Content="ICS testweise aus" Style="{StaticResource Sec}"/><Button x:Name="BtnHvIcsOn" Content="ICS wieder an" Style="{StaticResource Sec}"/></WrapPanel>',
        '<WrapPanel Margin="0,0,0,0"><Button x:Name="BtnHvBootOff" Content="Test: Hypervisor beim Start aus" Style="{StaticResource Sec}"/><Button x:Name="BtnHvBootOn" Content="Hypervisor wieder an" Style="{StaticResource Sec}"/><Button x:Name="BtnHvReset" Content="Hyper-V-Netzwerk zurücksetzen ..." Style="{StaticResource Sec}"/><Button x:Name="BtnHvRemove" Content="Hyper-V deinstallieren ..." Style="{StaticResource Sec}"/><Button x:Name="BtnHvMgr" Content="Hyper-V-Manager" Style="{StaticResource Sec}"/></WrapPanel>')) +
    (New-Card 'Erweiterte Treibereinstellungen des gewählten Adapters' @(
        (New-Hint 'Die Einstellungen aus Geräte-Manager > Adapter > Erweitert. Bei WLAN-Problemen helfen oft: "Roaming Aggressiveness" niedriger, "Wireless Mode"/"802.11n/ac" fest einstellen, "Preferred Band" wählen, "MIMO Power Save" bzw. Energiesparen aus. Änderungen starten den Adapter kurz neu.'),
        (New-White (New-DataGrid 'NdPropGrid' @('Eigenschaft|Name|240', 'Wert|Value|170', 'Mögliche Werte|Valid|*', 'Schlüssel|Key|170') 'Height="200"')),
        '<Grid Margin="0,8,0,0"><Grid.ColumnDefinitions><ColumnDefinition Width="260"/><ColumnDefinition Width="Auto"/><ColumnDefinition Width="Auto"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions><ComboBox x:Name="NdPropVal" IsEditable="True" Margin="0,0,8,0"/><Button x:Name="BtnNdPropSet" Grid.Column="1" Content="Wert übernehmen" Margin="0,0,8,0"/><Button x:Name="BtnNdPropReset" Grid.Column="2" Content="Alle auf Standard ..." Style="{StaticResource Sec}"/></Grid>')) +
    (New-Card 'WLAN' @(
        '<Grid><Grid.ColumnDefinitions><ColumnDefinition Width="260"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions><ComboBox x:Name="NdWlanProf" Margin="0,0,8,0" ToolTip="Gespeicherte WLAN-Profile"/><WrapPanel Grid.Column="1"><Button x:Name="BtnNdWlanReNew" Content="Profil neu anlegen (Kennwort bleibt)" Style="{StaticResource Sec}"/><Button x:Name="BtnNdWlanForget" Content="Profil vergessen ..." Style="{StaticResource Sec}"/><Button x:Name="BtnNdWlanList" Content="WLAN-Liste" Style="{StaticResource Sec}"/><Button x:Name="BtnNdWlanReport" Content="WLAN-Bericht von Windows" Style="{StaticResource Sec}"/></WrapPanel></Grid>',
        '<TextBox x:Name="NdWlanText" Height="170" Margin="0,8,0,0" IsReadOnly="True" FontFamily="Consolas" FontSize="12" VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Auto" TextWrapping="NoWrap"/>')) +
    (New-Card 'Tiefenanalyse: alles in eine Datei für die Fehlersuche' @(
        (New-Hint 'Sammelt in 2-6 Minuten ALLE Netzwerkdaten dieses PCs in eine ZIP-Datei (portabel direkt auf den Stick): System, Updates, Sicherheitsprogramme, Adapter, Treiber und Treiberpakete, alle Bindungen und Filter, erweiterte Treibereinstellungen, IP/DHCP/Routen/DNS, reservierte Ports, UDP-Belegung mit Prozess, WLAN komplett mit WLAN-Bericht, Hyper-V/NAT/HNS, Firewall- und WFP-Filter, Registrierung (TCP/IP, DHCP, Winsock, Netzwerkklassen) und Ereignisprotokolle. Die Datei 01_Zusammenfassung.txt wertet alles aus.'),
        '<WrapPanel Margin="0,4,0,6"><CheckBox x:Name="NdDeepLive" Content="Live-Test: Adressen neu anfordern und DHCP-Pakete mitschneiden (pktmon)" IsChecked="True" Margin="0,0,20,6"/><CheckBox x:Name="NdDeepProbe" Content="Eigene DHCP-Probe (DHCP-Client 15 s angehalten, fragt selbst beim Router)" IsChecked="True" Margin="0,0,20,6"/><CheckBox x:Name="NdDeepWfp" Content="Windows-Filterplattform: Filter und verworfene Pakete" IsChecked="True" Margin="0,0,20,6"/><CheckBox x:Name="NdDeepTrace" Content="Zusätzlich netsh trace (bis 300 MB, +2 Minuten)" Margin="0,0,0,6"/></WrapPanel>',
        '<WrapPanel><Button x:Name="BtnNdDeep2" Content="Tiefenanalyse starten"/><Button x:Name="BtnNdDeepDir" Content="Ordner mit Analysen öffnen" Style="{StaticResource Sec}"/></WrapPanel>',
        (New-Hint 'Die Analyse läuft in einem eigenen Fenster mit Fortschritt. Während des Live-Tests ist das Netzwerk kurz weg. Die ZIP enthält Netz- und Gerätenamen, IP-/MAC-Adressen und WLAN-Profile - WLAN-Kennwörter werden nicht im Klartext gespeichert.'))) +
    (New-Card 'Reparatur-Protokoll' @(
        '<TextBox x:Name="NdLog" Height="170" IsReadOnly="True" FontFamily="Consolas" FontSize="12" VerticalScrollBarVisibility="Auto" TextWrapping="Wrap"/>')) +
    (New-Card 'Notfall-Stick' @(
        (New-Hint 'Kopiert PC-Tools portabel auf einen USB-Stick oder in einen Ordner - mit "Netzwerk-Notfall.cmd": auf dem kaputten PC doppelklicken, dann läuft die Diagnose im Textfenster (auch wenn die Oberfläche nicht startet) und der Bericht landet auf dem Stick. Für ein Surface kann gleich das passende Treiberpaket mit auf den Stick (Seite Microsoft Surface).'),
        '<WrapPanel><Button x:Name="BtnNdStick" Content="Portable PC-Tools auf Stick / in Ordner ..."/><Button x:Name="BtnNdConsole" Content="Textmodus hier starten" Style="{StaticResource Sec}"/><Button x:Name="BtnNdSurface" Content="Zur Seite Microsoft Surface" Style="{StaticResource Sec}"/><Button x:Name="BtnNdRescue" Content="Bootfähiger Notfall-Stick ..." Style="{StaticResource Sec}"/></WrapPanel>')))

# ---- Microsoft Surface
$sfKnown = '<DataGrid x:Name="SfKnownGrid" Height="250" HeadersVisibility="Column"><DataGrid.Columns><DataGridTextColumn Header="Problem" Binding="{Binding P}" Width="230"><DataGridTextColumn.ElementStyle><Style TargetType="TextBlock"><Setter Property="TextWrapping" Value="Wrap"/><Setter Property="FontWeight" Value="SemiBold"/></Style></DataGridTextColumn.ElementStyle></DataGridTextColumn>' +
    '<DataGridTextColumn Header="Betrifft" Binding="{Binding M}" Width="170"><DataGridTextColumn.ElementStyle><Style TargetType="TextBlock"><Setter Property="TextWrapping" Value="Wrap"/></Style></DataGridTextColumn.ElementStyle></DataGridTextColumn>' +
    '<DataGridTextColumn Header="Lösung" Binding="{Binding L}" Width="*"><DataGridTextColumn.ElementStyle><Style TargetType="TextBlock"><Setter Property="TextWrapping" Value="Wrap"/></Style></DataGridTextColumn.ElementStyle></DataGridTextColumn></DataGrid.Columns></DataGrid>'
$pageSurface = New-Page 'Microsoft Surface' 'Alles für Surface Pro, Laptop, Book, Go und Studio: Modell, Firmware und alle Surface-Treiber, das komplette Treiber- und Firmwarepaket von Microsoft (auch zum Mitnehmen auf dem USB-Stick für ein Surface ohne Internet), UEFI, Tastenkombinationen, Akku, Type Cover, Stift, Touch und die bekannten Surface-Probleme mit Lösung.' (
    ('<WrapPanel Margin="0,0,0,6">' + (New-StatTile 'SfS0' 'Akku-Zustand' '#16A34A') + (New-StatTile 'SfS1' 'Surface-Treiber und Firmware' '#2D7FF9') + (New-StatTile 'SfS2' 'Geräte mit Fehler' '#DC2626') + (New-StatTile 'SfS3' 'Netzwerk (IPv4)' '#6D4AE8') + '</WrapPanel>') +
    '<Border x:Name="SfBanner" Background="#FEF2F2" BorderBrush="#FCA5A5" BorderThickness="1" CornerRadius="8" Padding="12,8" Margin="0,0,0,12" Visibility="Collapsed"><Grid><Grid.ColumnDefinitions><ColumnDefinition/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions><TextBlock x:Name="SfBannerText" TextWrapping="Wrap" Foreground="#991B1B" FontWeight="SemiBold" VerticalAlignment="Center"/><Button x:Name="BtnSfBannerGo" Grid.Column="1" Content="Netzwerk-Diagnose" Margin="10,0,0,0"/></Grid></Border>' +
    (New-Card 'Dieses Gerät' @(
        '<TextBlock x:Name="SfNoSurface" TextWrapping="Wrap" Foreground="#B45309" FontWeight="SemiBold" Margin="0,0,0,8" Visibility="Collapsed" Text="Dieser PC ist kein Surface. Du kannst trotzdem unten das Treiberpaket für ein beliebiges Surface-Modell auf einen USB-Stick laden."/>',
        (New-InfoRow 'Modell' 'SfModel'), (New-InfoRow 'SKU / Seriennummer' 'SfSku'), (New-InfoRow 'UEFI (Firmware)' 'SfUefi'), (New-InfoRow 'Prozessor' 'SfCpu'), (New-InfoRow 'Windows' 'SfOs'),
        (New-InfoRow 'Sicherheit' 'SfSec'), (New-InfoRow 'WLAN' 'SfWlan'), (New-InfoRow 'Bildschirm' 'SfDisp'), (New-InfoRow 'Akku' 'SfBat'), (New-InfoRow 'Zubehör' 'SfAcc'),
        '<WrapPanel Margin="0,8,0,0"><Button x:Name="BtnSfRefresh" Content="Neu einlesen" Style="{StaticResource Sec}"/><Button x:Name="BtnSfCopy" Content="Angaben kopieren" Style="{StaticResource Sec}"/><Button x:Name="BtnSfWarranty" Content="Garantie prüfen" Style="{StaticResource Sec}"/><Button x:Name="BtnSfSupport" Content="Surface-Support von Microsoft" Style="{StaticResource Sec}"/></WrapPanel>')) +
    (New-Card 'Treiber- und Firmwarepaket von Microsoft (MSI)' @(
        (New-Hint 'Das Paket enthält ALLE Treiber und die Firmware (UEFI, WLAN, Touch, Akku-Controller, Kamera ...) für genau ein Modell. Hat das Surface kein Internet: auf einem anderen PC das Modell wählen, "Auf USB-Stick laden", Stick ans Surface, PC-Tools vom Stick starten und "Paket vom Stick installieren" - oder nur die Netzwerktreiber.'),
        '<Grid><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="140"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions><ComboBox x:Name="SfModelCombo" Margin="0,0,8,0"/><ComboBox x:Name="SfWin" Grid.Column="1" SelectedIndex="0" Margin="0,0,8,0"><ComboBoxItem Content="Windows 11"/><ComboBoxItem Content="Windows 10"/></ComboBox><Button x:Name="BtnSfFind" Grid.Column="2" Content="Neueste Version suchen" Style="{StaticResource Sec}" Margin="0"/></Grid>',
        '<TextBlock x:Name="SfPackInfo" TextWrapping="Wrap" Foreground="#1F2A44" FontWeight="SemiBold" Margin="0,8,0,0" Text="-"/>',
        '<Border x:Name="SfPackBox" Visibility="Collapsed" Background="White" BorderBrush="#E2E7F0" BorderThickness="1" CornerRadius="10" Margin="0,8,0,0" Padding="2">' + (New-DataGrid 'SfPackGrid' @('Paket|File|*', 'Windows|WinText|80', 'Build|Build|70', 'Version|Version|120', 'Art|Kind|55', 'Größe|SizeText|80|Size', 'Passt?|Fit|230') 'Height="200"') + '</Border>',
        '<TextBlock x:Name="SfPackHint" Visibility="Collapsed" TextWrapping="Wrap" Foreground="#6B7890" FontSize="12" Margin="0,4,0,0" Text="Alle Varianten, die Microsoft für dieses Modell anbietet. Die markierte Zeile wird für &quot;Herunterladen und installieren&quot; und &quot;Auf USB-Stick laden&quot; verwendet - vorausgewählt ist die empfohlene (passend zu Windows-Version und Build). ZIP-Pakete enthalten die Treiber ohne Installer (nur zum manuellen Einspielen)."/>',
        '<WrapPanel Margin="0,8,0,0"><Button x:Name="BtnSfOneClick" Content="Ein Klick: neueste Treiber &amp; Firmware laden und installieren" Background="#059669" Foreground="White" BorderThickness="0" FontWeight="SemiBold"/></WrapPanel>',
        '<WrapPanel Margin="0,8,0,0"><Button x:Name="BtnSfInstall" Content="Herunterladen und installieren"/><Button x:Name="BtnSfSave" Content="Auf USB-Stick / in Ordner laden ..."/><Button x:Name="BtnSfAllModels" Content="Neueste für ALLE Modelle in Ordner laden ..." Style="{StaticResource Sec}"/><Button x:Name="BtnSfLocal" Content="Paket vom Stick installieren" Style="{StaticResource Sec}"/><Button x:Name="BtnSfNet" Content="Nur Netzwerk-/WLAN-Treiber aus dem Paket" Style="{StaticResource Sec}"/><Button x:Name="BtnSfMsPage" Content="Microsoft-Downloadseite" Style="{StaticResource Sec}"/></WrapPanel>',
        '<TextBlock x:Name="SfLocalInfo" TextWrapping="Wrap" Foreground="#6B7890" Margin="0,4,0,0"/>')) +
    (New-Card 'Installierte Surface-Treiber und Firmware' @(
        '<WrapPanel><ComboBox x:Name="SfDrvFilter" Width="260" SelectedIndex="0" Margin="0,0,8,8"><ComboBoxItem Content="Surface, Firmware und Netzwerk"/><ComboBoxItem Content="Nur Geräte mit Fehler"/><ComboBoxItem Content="Alle Treiber"/></ComboBox>' + (New-Filter 'SfDrvSearch' 220) + '</WrapPanel>',
        (New-White (New-DataGrid 'SfDrvGrid' @('Gerät|Name|280', 'Klasse|Class|100', 'Version|Version|130', 'Datum|Date|90', 'Anbieter|Provider|150', 'Status|State|*') 'Height="260"')),
        '<WrapPanel Margin="0,8,0,0"><Button x:Name="BtnSfDevRestart" Content="Gerät neu starten" Style="{StaticResource Sec}"/><Button x:Name="BtnSfDevReinst" Content="Treiber neu installieren" Style="{StaticResource Sec}"/><Button x:Name="BtnSfWu" Content="Surface-Updates über Windows Update" Style="{StaticResource Sec}"/><Button x:Name="BtnSfDevMgr" Content="Geräte-Manager" Style="{StaticResource Sec}"/></WrapPanel>')) +
    (New-Card 'UEFI, Starten und Wiederherstellen' @(
        '<TextBlock x:Name="SfKeys" TextWrapping="Wrap" Foreground="#1F2A44" LineHeight="20"/>',
        '<WrapPanel Margin="0,8,0,0"><Button x:Name="BtnSfUefi" Content="Neustart ins Surface UEFI"/><Button x:Name="BtnSfAdv" Content="Erweiterter Start (USB-Stick, Reparatur)" Style="{StaticResource Sec}"/><Button x:Name="BtnSfBitlocker" Content="BitLocker für Firmware-Update aussetzen" Style="{StaticResource Sec}"/><Button x:Name="BtnSfRecDrive" Content="Wiederherstellungslaufwerk erstellen" Style="{StaticResource Sec}"/><Button x:Name="BtnSfRecImg" Content="Surface-Wiederherstellungsabbild" Style="{StaticResource Sec}"/></WrapPanel>')) +
    (New-Card 'Akku und Stromversorgung' @(
        '<TextBlock x:Name="SfBatText" TextWrapping="Wrap" Foreground="#1F2A44" LineHeight="20" Text="-"/>',
        '<WrapPanel Margin="0,8,0,0"><Button x:Name="BtnSfBatReport" Content="Ausführlicher Akkubericht" Style="{StaticResource Sec}"/><Button x:Name="BtnSfBatDrv" Content="Akkutreiber neu laden" Style="{StaticResource Sec}"/><Button x:Name="BtnSfPower" Content="Energie und Akku (Windows)" Style="{StaticResource Sec}"/></WrapPanel>',
        (New-Hint 'Surface lädt nur bis 50 %? Dann ist im UEFI der "Akkubegrenzungsmodus" (Battery Limit) an - gut für Geräte, die dauernd am Netzteil hängen. In der Surface-App gibt es außerdem "Intelligentes Laden".'))) +
    (New-Card 'Type Cover, Stift, Touch und Kamera' @(
        (New-White (New-DataGrid 'SfInGrid' @('Gerät|Name|300', 'Art|Class|110', 'Status|State|110', 'Geräte-ID|Id|*') 'Height="170"')),
        '<WrapPanel Margin="0,8,0,0"><Button x:Name="BtnSfInRestart" Content="Gerät neu starten" Style="{StaticResource Sec}"/><Button x:Name="BtnSfTouchCal" Content="Touch/Stift kalibrieren" Style="{StaticResource Sec}"/><Button x:Name="BtnSfPen" Content="Stift und Windows Ink" Style="{StaticResource Sec}"/><Button x:Name="BtnSfBt" Content="Bluetooth (Stift koppeln)" Style="{StaticResource Sec}"/><Button x:Name="BtnSfCam" Content="Kamera-Datenschutz" Style="{StaticResource Sec}"/><Button x:Name="BtnSfDisplay" Content="Anzeige / Helligkeit" Style="{StaticResource Sec}"/></WrapPanel>')) +
    (New-Card 'Surface-Apps von Microsoft' @(
        '<WrapPanel><Button x:Name="BtnSfApp" Content="Surface-App" Style="{StaticResource Sec}"/><Button x:Name="BtnSfSdt" Content="Surface Diagnostic Toolkit" Style="{StaticResource Sec}"/><Button x:Name="BtnSfDock" Content="Surface Dock Firmware-Update" Style="{StaticResource Sec}"/><Button x:Name="BtnSfDocs" Content="Surface-Dokumentation für IT" Style="{StaticResource Sec}"/></WrapPanel>',
        (New-Hint 'Surface-App: Akku, Stift-Druck, Tastenbelegung, Garantie und Updates. Surface Diagnostic Toolkit: offizieller Hardwaretest von Microsoft (Akku, Display, Touch, WLAN, Tasten ...).'))) +
    (New-Card 'Bekannte Surface-Probleme und Lösungen' @((New-White $sfKnown))))

# ---------------------------------------------------------------- Toolbox und Software-Kiosk (Seiten-XAML)
$pageToolbox = New-Page 'Toolbox' 'Bewährte kostenlose Admin- und Diagnose-Werkzeuge - fest eingebaut: PC-Tools lädt sie beim Start automatisch im Hintergrund und hält sie aktuell, direkt vom Hersteller und mit Prüfung der digitalen Signatur. Auf Wunsch auch auf dem USB-Stick für jeden PC dabei.' ((@(
    ('<WrapPanel Margin="0,0,0,4">{0}{1}{2}{3}</WrapPanel>' -f (New-StatTile 'TbStatLoaded' 'Werkzeuge geladen' '#2D7FF9'), (New-StatTile 'TbStatUpd' 'Updates verfügbar' '#EA580C'), (New-StatTile 'TbStatSize' 'Speicherplatz der Toolbox' '#0891B2'), (New-StatTile 'TbStatWg' 'Programme per winget installiert' '#7C3AED')),
    (New-Card 'Werkzeugkasten' @(
        '<Border Background="#ECFEFF" BorderBrush="#A5F3FC" BorderThickness="1" CornerRadius="12" Padding="14,12" Margin="0,0,0,12"><Grid><Grid.ColumnDefinitions><ColumnDefinition Width="Auto"/><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions><Border Width="38" Height="38" CornerRadius="10" Background="#0891B2" VerticalAlignment="Top" Margin="0,0,12,0"><TextBlock Text="&#xE895;" FontFamily="Segoe MDL2 Assets" FontSize="18" Foreground="White" HorizontalAlignment="Center" VerticalAlignment="Center"/></Border><StackPanel Grid.Column="1"><TextBlock x:Name="TbAutoText" Text="" FontWeight="SemiBold" Foreground="#164E63" TextWrapping="Wrap"/><TextBlock x:Name="TbAutoSub" Text="" Foreground="#155E75" FontSize="12" TextWrapping="Wrap" Margin="0,2,0,0"/><ProgressBar x:Name="TbAutoBar" Height="6" Maximum="100" Margin="0,8,0,0" Visibility="Collapsed" Foreground="#0891B2" Background="#CFFAFE" BorderThickness="0"/><CheckBox x:Name="TbAutoOn" Content="Beim Start von PC-Tools automatisch laden und aktuell halten (mit Signaturprüfung; mit gemeinsamem Ordner aus Meine PCs auch für alle PCs)" Margin="0,8,0,0" IsChecked="True"/></StackPanel><StackPanel Grid.Column="2" Margin="12,0,0,0"><Button x:Name="BtnTbAutoNow" Content="Jetzt aktualisieren" Style="{StaticResource Sec}" Padding="12,5" Margin="0,0,0,6"/><Button x:Name="BtnTbAutoLog" Content="Protokoll" Style="{StaticResource Sec}" Padding="12,5" Margin="0"/></StackPanel></Grid></Border>',
        '<TextBlock x:Name="TbPath" Text="" Foreground="#6B7890" FontSize="12" TextWrapping="Wrap" Margin="0,0,0,10"/>',
        (New-Bar @('BtnTbLoadAll|Alle sofort laden (als Aufgabe)', 'BtnTbCheck|Nach Updates suchen', 'BtnTbUsb|Auf USB-Stick kopieren ...', 'BtnTbOpen|Toolbox-Ordner öffnen') ((New-Combo 'TbCat' (@('Alle Kategorien') + $TbCategories) 180) + (New-Filter 'TbSearch' 240))),
        '<TextBlock x:Name="TbInfo" Text="" Foreground="#1F2A44" FontSize="12.5" TextWrapping="Wrap" Margin="0,2,0,0"/>'
    )),
    '<StackPanel x:Name="TbPanel" Margin="0,0,0,8"/>',
    (New-Card 'Gut zu wissen' @(
        (New-Hint 'Portabel: Die Werkzeuge werden nicht installiert, sondern in den Ordner "Toolbox" im Datenordner von PC-Tools geladen. Läuft PC-Tools vom USB-Stick, liegt die Toolbox automatisch auf dem Stick und ist an jedem PC sofort da.'),
        (New-Hint 'Immer aktuell: "Nach Updates suchen" fragt beim Hersteller nach (GitHub-Releases, Herstellerseite oder Datum/Größe der Download-Datei) und markiert neuere Versionen. "Laden/Aktualisieren" ersetzt ein Werkzeug erst, wenn der neue Download vollständig und geprüft ist.'),
        (New-Hint 'Sicherheit: Signierte Dateien müssen eine gültige digitale Signatur des erwarteten Herstellers haben (z.B. Microsoft bei Sysinternals), sonst wird der Download verworfen. NirSoft- und Ventoy-Dateien sind vom Hersteller nicht signiert und kommen ausschließlich von der offiziellen Adresse.'),
        (New-Hint 'Ohne portable Version (GPU-Z, CrystalDiskInfo, CrystalDiskMark, WinDirStat, TreeSize, Wireshark) installiert PC-Tools das Programm auf diesem PC über winget. Sysinternals-Werkzeuge starten mit akzeptierter Lizenz (/accepteula). Fernwartungs-Programme sind nur für die private Nutzung kostenlos.')
    ))
)) -join "`n")

$ksHero = @'
<Border CornerRadius="18" Margin="0,0,4,18" Padding="28,22" Background="{StaticResource HeroGrad}">
  <Border.Effect><DropShadowEffect BlurRadius="26" ShadowDepth="5" Direction="270" Opacity="0.28" Color="#2A2F8F"/></Border.Effect>
  <Grid>
    <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
    <StackPanel>
      <TextBlock Text="Programme wie im App-Store" Foreground="#FFFFFF" FontSize="22" FontWeight="Bold"/>
      <TextBlock Text="Rolle wählen, Häkchen prüfen, installieren - PC-Tools lädt alles still über winget direkt von den Herstellern. Bereits installierte Programme werden erkannt und auf Wunsch aktualisiert. Eigene Rollen lassen sich speichern, exportieren und auf anderen PCs importieren." Foreground="#FFFFFF" Opacity="0.92" FontSize="13.5" TextWrapping="Wrap" Margin="0,8,0,14" MaxWidth="820" HorizontalAlignment="Left"/>
      <WrapPanel>
        <Border CornerRadius="14" Padding="12,5" Margin="0,0,8,0" Background="#33FFFFFF"><TextBlock x:Name="KsHeroRoles" Text="-" Foreground="#FFFFFF" FontWeight="SemiBold"/></Border>
        <Border CornerRadius="14" Padding="12,5" Margin="0,0,8,0" Background="#33FFFFFF"><TextBlock x:Name="KsHeroApps" Text="-" Foreground="#FFFFFF" FontWeight="SemiBold"/></Border>
        <Border CornerRadius="14" Padding="12,5" Margin="0,0,8,0" Background="#33FFFFFF"><TextBlock x:Name="KsHeroInst" Text="Installationsstatus wird ermittelt ..." Foreground="#FFFFFF" FontWeight="SemiBold"/></Border>
      </WrapPanel>
    </StackPanel>
    <Border Grid.Column="1" Width="96" Height="96" CornerRadius="24" Background="#26FFFFFF" Margin="24,0,0,0" VerticalAlignment="Center">
      <TextBlock Text="&#xE719;" FontFamily="Segoe MDL2 Assets" FontSize="46" Foreground="#FFFFFF" HorizontalAlignment="Center" VerticalAlignment="Center"/>
    </Border>
  </Grid>
</Border>
'@
$ksRoleHead = @'
<Grid Margin="0,0,0,8">
  <Grid.ColumnDefinitions><ColumnDefinition Width="Auto"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>
  <Border x:Name="KsRoleBadge" Width="46" Height="46" CornerRadius="12" Background="#52627A" Margin="0,0,14,0" VerticalAlignment="Top">
    <TextBlock x:Name="KsRoleGlyph" Text="&#xE719;" FontFamily="Segoe MDL2 Assets" FontSize="21" Foreground="#FFFFFF" HorizontalAlignment="Center" VerticalAlignment="Center"/>
  </Border>
  <StackPanel Grid.Column="1">
    <TextBlock x:Name="KsRoleTitle" Text="Bitte oben eine Rolle wählen" FontSize="18" FontWeight="SemiBold" Foreground="#1F2A44"/>
    <TextBlock x:Name="KsRoleDesc" Text="Ein Klick auf eine Rollen-Kachel zeigt ihre Programme. Fehlende Programme sind vorausgewählt." Foreground="#6B7890" TextWrapping="Wrap" Margin="0,2,0,0"/>
    <TextBlock x:Name="KsRoleInfo" Text="" Foreground="#2D7FF9" FontWeight="SemiBold" FontSize="12" Margin="0,6,0,0"/>
  </StackPanel>
</Grid>
'@
$pageKiosk = New-Page 'Software-Kiosk' 'Geräte nach Rolle einrichten: Büro, Rezeption, Kasse, Entwicklung, Grafik, Familie, Gaming oder Admin - oder einzelne Programme aus dem Katalog. Die Installation läuft im Hintergrund mit Fortschritt und Protokoll.' ((@(
    $ksHero,
    (New-Card 'Rollen' @(
        (New-Hint 'Eine Rolle ist eine Programmliste für einen Einsatzzweck. Eingebaute Rollen lassen sich als eigene Rolle speichern und dann frei anpassen (Programme hinzufügen/entfernen, exportieren, auf anderen PCs importieren).'),
        '<WrapPanel x:Name="KsRolePanel" Margin="0,6,0,0"/>',
        (New-Bar @('BtnKsNewRole|Neue eigene Rolle ...', 'BtnKsImport|Rolle importieren ...'))
    )),
    (New-Card 'Programme der Rolle' @(
        $ksRoleHead,
        '<WrapPanel x:Name="KsAppPanel" Margin="0,4,0,8"/>',
        (New-Bar @('BtnKsInstallSel|Ausgewählte installieren|P', 'BtnKsInstallAll|Alle der Rolle installieren', 'BtnKsSelMissing|Nur fehlende anhaken', 'BtnKsAddApp|Programm hinzufügen ...', 'BtnKsSaveAs|Als eigene Rolle speichern ...', 'BtnKsExport|Rolle exportieren ...', 'BtnKsDelete|Rolle löschen'))
    )),
    (New-Card 'Einzelne Programme' @(
        (New-Hint 'Der ganze Katalog zum Stöbern. "Installieren" startet sofort (bereits installierte Programme werden dabei aktualisiert); "+ Rolle" nimmt das Programm in die gewählte eigene Rolle auf. Nicht dabei? "In winget suchen" durchsucht die Tausenden Pakete von winget.'),
        (New-Bar @('BtnKsWgSearch|In winget suchen ...', 'BtnKsRefresh|Installationsstatus aktualisieren') ((New-Combo 'KsCat' (@('Alle Kategorien') + $KsCategories) 190) + (New-Filter 'KsSearch' 240))),
        '<TextBlock x:Name="KsStatus" Text="" Foreground="#6B7890" FontSize="12" TextWrapping="Wrap" Margin="0,0,0,8"/>',
        '<WrapPanel x:Name="KsCatPanel"/>'
    ))
)) -join "`n")
# ---------------------------------------------------------------- Übersicht: Karte "Zustands-Score" (mit Ring, Trend, Verlauf und Bestandteilen)
$pageScoreCard = @'
<Border Background="White" CornerRadius="12" Padding="20,16" Margin="0,0,4,16" BorderBrush="#E2E7F0" BorderThickness="1">
  <Border.Effect><DropShadowEffect BlurRadius="18" ShadowDepth="2" Direction="270" Opacity="0.07" Color="Black"/></Border.Effect>
  <StackPanel>
    <Grid Margin="0,0,0,10">
      <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
      <StackPanel Orientation="Horizontal" VerticalAlignment="Center"><Border Width="4" Height="16" CornerRadius="2" Margin="0,0,10,0" VerticalAlignment="Center" Background="{StaticResource AccentGrad}"/><TextBlock Text="Zustands-Score" FontSize="16" FontWeight="SemiBold" Foreground="#1F2A44" VerticalAlignment="Center"/><TextBlock x:Name="ScInfo" Text="" FontSize="12" Foreground="#6B7890" Margin="12,0,0,0" VerticalAlignment="Center"/></StackPanel>
      <StackPanel Grid.Column="1" Orientation="Horizontal"><Button x:Name="BtnScFix" Content="Punkte beheben" Padding="12,5" Margin="0,0,8,0" VerticalAlignment="Center" ToolTip="Behebt mit einem Klick alles, was sich automatisch beheben lässt (vorher kommt eine Übersicht)"/><Button x:Name="BtnScHelp" Content="Hilfe holen" Style="{StaticResource Sec}" Padding="12,5" Margin="0,0,8,0" VerticalAlignment="Center" ToolTip="Schickt deinem Helfer einen Bericht über diesen PC (Zustand, Probleme, Protokoll)"/><Button x:Name="BtnScHistory" Content="Verlauf" Style="{StaticResource Sec}" Padding="12,5" Margin="0,0,8,0" VerticalAlignment="Center"/><Button x:Name="BtnScRefresh" Content="Neu berechnen" Style="{StaticResource Sec}" Padding="12,5" Margin="0" VerticalAlignment="Center"/></StackPanel>
    </Grid>
    <WrapPanel Margin="0,0,0,10"><CheckBox x:Name="AutoFix_Enabled" Content="Automatisch beheben, wenn der Score unter" VerticalAlignment="Center" Margin="0,0,6,0" ToolTip="Nach jedem geplanten Pflegelauf: Virendefinitionen, Geräte-Probleme und Treiber für Problemgeräte werden selbst behoben. Alles andere meldet PC-Tools als Hinweis."/><TextBox x:Name="AutoFix_Below" Width="40" TextAlignment="Center" Padding="2,2" VerticalAlignment="Center"/><TextBlock Text="fällt (nach jedem geplanten Lauf)" VerticalAlignment="Center" Foreground="#6B7890" Margin="6,0,0,0"/></WrapPanel>
    <Grid>
      <Grid.ColumnDefinitions><ColumnDefinition Width="Auto"/><ColumnDefinition Width="260"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>
      <Grid Width="170" Height="170" Margin="0,0,24,0" VerticalAlignment="Top">
        <Canvas x:Name="ScRing" Width="170" Height="170"/>
        <StackPanel VerticalAlignment="Center" HorizontalAlignment="Center">
          <TextBlock x:Name="ScValue" Text="-" FontSize="46" FontWeight="Bold" Foreground="#1F2A44" HorizontalAlignment="Center"/>
          <TextBlock Text="von 100" FontSize="11" Foreground="#6B7890" HorizontalAlignment="Center" Margin="0,-4,0,0"/>
          <TextBlock x:Name="ScGrade" Text="wird berechnet ..." FontSize="13" FontWeight="SemiBold" Foreground="#6B7890" HorizontalAlignment="Center" Margin="0,4,0,0"/>
        </StackPanel>
      </Grid>
      <StackPanel Grid.Column="1" Margin="0,0,24,0">
        <TextBlock Text="TREND" FontSize="11" FontWeight="Bold" Foreground="#6B7890"/>
        <StackPanel Orientation="Horizontal" Margin="0,2,0,0"><TextBlock x:Name="ScTrendArrow" Text="" FontFamily="Segoe MDL2 Assets" FontSize="18" Foreground="#6B7890" VerticalAlignment="Center" Margin="0,0,8,0"/><TextBlock x:Name="ScTrend" Text="-" FontSize="17" FontWeight="SemiBold" Foreground="#1F2A44" VerticalAlignment="Center" TextWrapping="Wrap"/></StackPanel>
        <TextBlock x:Name="ScTrendSub" Text="" FontSize="12" Foreground="#6B7890" TextWrapping="Wrap" Margin="0,2,0,12"/>
        <TextBlock Text="LETZTE 90 TAGE" FontSize="11" FontWeight="Bold" Foreground="#6B7890"/>
        <Border Background="#F8FAFD" CornerRadius="8" BorderBrush="#E2E7F0" BorderThickness="1" Margin="0,4,0,0" Padding="6"><Canvas x:Name="ScSpark" Height="64" ClipToBounds="True"/></Border>
        <TextBlock x:Name="ScSparkInfo" Text="" FontSize="11" Foreground="#6B7890" Margin="0,4,0,0" TextWrapping="Wrap"/>
      </StackPanel>
      <StackPanel Grid.Column="2">
        <TextBlock Text="BESTANDTEILE" FontSize="11" FontWeight="Bold" Foreground="#6B7890" Margin="0,0,0,4"/>
        <StackPanel x:Name="ScComps"/>
      </StackPanel>
    </Grid>
  </StackPanel>
</Border>
'@
# Karte automatisch unter der Ampel einfügen (die Übersicht wird weiter oben gebaut; $pageAmpel steckt unverändert darin)
if ($pageOverview -and $pageAmpel -and $pageOverview -notmatch 'x:Name="ScRing"') { $pageOverview = $pageOverview.Replace($pageAmpel, $pageAmpel + $pageScoreCard) }

# ---------------------------------------------------------------- Hardware-Test (Testzentrum mit Prüfprotokoll)
function New-HwCard([string]$Key, [string]$Glyph, [string]$Color, [string]$Title, [string]$Desc, [string]$Buttons, [string]$Extra = '', [int]$Width = 0, [switch]$NoProgress) {
    $wAttr = if ($Width -gt 0) { ' Width="{0}"' -f $Width } else { '' }
    $prog = if ($NoProgress) { '' } else { '<Grid Margin="0,8,0,0"><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions><ProgressBar x:Name="Hw{0}Prog" Height="8" Minimum="0" Maximum="100" Value="0" Foreground="{{StaticResource AccentGrad}}" Background="#E3E8F2" BorderThickness="0" VerticalAlignment="Center"/><TextBlock x:Name="Hw{0}Pct" Grid.Column="1" Text="" Width="44" TextAlignment="Right" Foreground="#6B7890" FontSize="12" VerticalAlignment="Center"/></Grid>' -f $Key }
@"
<Border Background="White" CornerRadius="14" Padding="20,16" Margin="0,0,14,16" BorderBrush="#E2E7F0" BorderThickness="1"$wAttr>
  <Border.Effect><DropShadowEffect BlurRadius="18" ShadowDepth="2" Direction="270" Opacity="0.07" Color="Black"/></Border.Effect>
  <StackPanel>
    <Grid>
      <Grid.ColumnDefinitions><ColumnDefinition Width="Auto"/><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
      <Border Width="46" Height="46" CornerRadius="13" Background="$Color" Margin="0,0,14,0" VerticalAlignment="Top">
        <Border.Effect><DropShadowEffect BlurRadius="12" ShadowDepth="2" Direction="270" Opacity="0.25" Color="$Color"/></Border.Effect>
        <TextBlock Text="$Glyph" FontFamily="Segoe MDL2 Assets" FontSize="21" Foreground="#FFFFFF" HorizontalAlignment="Center" VerticalAlignment="Center"/>
      </Border>
      <StackPanel Grid.Column="1" VerticalAlignment="Center">
        <TextBlock Text="$(Esc $Title)" FontSize="16" FontWeight="SemiBold" Foreground="#1F2A44" TextWrapping="Wrap"/>
        <TextBlock Text="$(Esc $Desc)" FontSize="12" Foreground="#6B7890" TextWrapping="Wrap" Margin="0,3,0,0"/>
      </StackPanel>
      <Border x:Name="Hw${Key}Badge" Grid.Column="2" CornerRadius="10" Padding="10,3" Background="#EEF2F8" VerticalAlignment="Top" Margin="10,0,0,0"><TextBlock x:Name="Hw${Key}BadgeText" Text="Nicht geprüft" FontSize="11.5" FontWeight="SemiBold" Foreground="#475569"/></Border>
    </Grid>
    <WrapPanel Margin="0,12,0,0">$Buttons</WrapPanel>
    $prog
    <TextBlock x:Name="Hw${Key}Status" Text="" Foreground="#1F2A44" FontSize="12.5" TextWrapping="Wrap" Margin="0,6,0,0"/>
    $Extra
    <TextBlock x:Name="Hw${Key}Detail" Text="" Foreground="#6B7890" FontSize="12" TextWrapping="Wrap" Margin="0,6,0,0"/>
  </StackPanel>
</Border>
"@
}
function New-HwChartBox([string]$Name, [int]$Height) {
    '<Border Background="#F8FAFD" CornerRadius="10" BorderBrush="#E2E7F0" BorderThickness="1" Margin="0,10,0,0" Padding="4"><Canvas x:Name="{0}" Height="{1}" ClipToBounds="True"/></Border>' -f $Name, $Height
}
$hwLogBox = '<TextBox x:Name="{0}" Height="96" Margin="0,8,0,0" IsReadOnly="True" FontFamily="Consolas" FontSize="11.5" TextWrapping="NoWrap" VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Auto" Padding="6,4"/>'
$hwBatGuide = @(
    '1. Akku vollständig auf 100 % laden und danach noch 1-2 Stunden am Netzteil lassen (die Ladeelektronik gleicht die Zellen aus).',
    '2. Energiesparmodus so einstellen, dass der Laptop bei niedrigem Akku NICHT in den Ruhezustand geht (Systemsteuerung > Energieoptionen > Energiesparplaneinstellungen ändern > Erweiterte Einstellungen > Akku > Aktion bei kritischer Akkukapazität: "Nichts unternehmen" bzw. Ruhezustand erst bei 3 %).',
    '3. Netzteil abziehen und den Laptop normal benutzen oder einfach eingeschaltet lassen (Bildschirm an), bis er sich von selbst ausschaltet.',
    '4. Mindestens 3-5 Stunden ausgeschaltet ruhen lassen.',
    '5. Ohne Unterbrechung wieder auf 100 % laden (am besten ausgeschaltet).',
    '6. Energieeinstellungen aus Schritt 2 wieder zurückstellen und hier "Akkubericht" bzw. den Akku-Test erneut starten.',
    'Hinweis: Kalibrieren repariert keinen verschlissenen Akku - es sorgt nur dafür, dass Prozentanzeige und Restlaufzeit wieder stimmen. Lithium-Akkus mögen keine Tiefentladung: höchstens alle 2-3 Monate kalibrieren. Viele Hersteller (Lenovo Vantage, Dell Power Manager, HP, Surface) haben eigene Kalibrier- oder Ladegrenzen-Funktionen - diese haben Vorrang.'
)
$hwStatTiles = '<WrapPanel Margin="0,0,0,4">{0}{1}{2}{3}</WrapPanel>' -f (New-StatTile 'HwStatOk' 'Tests bestanden' '#16A34A'), (New-StatTile 'HwStatWarn' 'Warnungen' '#EA580C'), (New-StatTile 'HwStatBad' 'Fehler' '#DC2626'), (New-StatTile 'HwStatLast' 'zuletzt geprüft' '#2D7FF9')

$pageHwTest = New-Page 'Hardware-Test' 'Das Testzentrum prüft Arbeitsspeicher, Datenträger, Prozessor, Akku, Bildschirm, Tastatur und Touch/Stift gründlich und erstellt daraus ein Prüfprotokoll als PDF - ideal beim Kauf oder Verkauf eines gebrauchten Geräts, bei der Übergabe an Kollegen oder zur Fehlersuche. Alle Tests sind nur lesend: es werden keine Daten verändert.' (
    $hwStatTiles +
    (New-Card 'Dieses Gerät' @(
        (New-InfoRow 'Hersteller' 'HwInfoMaker'),
        (New-InfoRow 'Modell' 'HwInfoModel'),
        (New-InfoRow 'Seriennummer' 'HwInfoSerial'),
        (New-InfoRow 'Prozessor' 'HwInfoCpu'),
        (New-InfoRow 'Arbeitsspeicher' 'HwInfoRam'),
        (New-InfoRow 'Datenträger' 'HwInfoDisks'),
        (New-InfoRow 'Grafik' 'HwInfoGpu'),
        (New-InfoRow 'Windows / BIOS' 'HwInfoOs'),
        '<Border Height="1" Background="#E2E7F0" Margin="0,10,0,10"/>',
        (New-Bar @('BtnHwReport|Prüfprotokoll als PDF|P', 'BtnHwRefresh|Gerätedaten neu lesen', 'BtnHwReset|Ergebnisse löschen')),
        (New-Hint 'Das Prüfprotokoll enthält die Gerätedaten, jedes Testergebnis mit Datum und Details sowie Unterschriftszeilen für Prüfer und Übernehmer. Die Ergebnisse bleiben gespeichert (Datei Hardwaretest.json im Datenordner), auch wenn PC-Tools geschlossen wird.'))) +

    (New-HwCard 'Ram' '&#xE964;' '#7C3AED' 'Arbeitsspeicher' 'Belegt einen Teil des freien Arbeitsspeichers und prüft ihn mit sechs Bitmustern (0x00, 0xFF, 0x55/0xAA, wandernde Einsen, Zufall): jedes Wort wird geschrieben und wieder gelesen. Findet defekte Speicherzellen und instabile Riegel. Den Speicher, den Windows selbst belegt, prüft nur die Windows-Speicherdiagnose beim Neustart.' (
        (New-Combo 'HwRamAmount' @('25 % des freien Speichers', '50 % des freien Speichers', '75 % des freien Speichers') 220).Replace('SelectedIndex="0"', 'SelectedIndex="1"') +
        (New-Combo 'HwRamPasses' @('1 Durchlauf', '2 Durchläufe', '3 Durchläufe', '5 Durchläufe') 140) +
        '<Button x:Name="BtnHwRamStart" Content="Test starten" Padding="14,6" Margin="0,0,8,8"/><Button x:Name="BtnHwRamStop" Content="Abbrechen" Style="{StaticResource Sec}" Padding="12,6" Margin="0,0,8,8" IsEnabled="False"/>' +
        '<Button x:Name="BtnHwRamDiag" Content="Windows-Speicherdiagnose beim Neustart" Style="{StaticResource Sec}" Padding="12,6" Margin="0,0,8,8"/><Button x:Name="BtnHwRamDiagResult" Content="Ergebnis der Speicherdiagnose" Style="{StaticResource Sec}" Padding="12,6" Margin="0,0,8,8"/>'
    ) ('<TextBlock x:Name="HwRamInfo" Text="" Foreground="#475569" FontSize="12" TextWrapping="Wrap" Margin="0,6,0,0"/>' + ($hwLogBox -f 'HwRamLog'))) +

    (New-HwCard 'Disk' '&#xEDA2;' '#0F766E' 'Datenträger-Lesetest' 'Liest den ganzen Datenträger direkt Block für Block (ohne Windows-Zwischenspeicher) und misst für jeden Block die Zeit. Langsame Blöcke (über 200 ms bzw. 500 ms) und Lesefehler deuten auf schwache oder defekte Bereiche hin. Es wird nur gelesen - nichts verändert. Dazu die Zuverlässigkeitswerte, die das Laufwerk selbst meldet (S.M.A.R.T.).' (
        '<ComboBox x:Name="HwDiskSel" Width="360" Margin="0,0,10,8" VerticalContentAlignment="Center"/>' +
        (New-Combo 'HwDiskMode' @('Schnelltest (verteilte Stichproben, ca. 2 Minuten)', 'Vollständig (jeder Block, kann Stunden dauern)') 330) +
        (New-Combo 'HwDiskBlock' @('Blockgröße 1 MB', 'Blockgröße 2 MB', 'Blockgröße 4 MB') 140).Replace('SelectedIndex="0"', 'SelectedIndex="2"') +
        '<Button x:Name="BtnHwDiskStart" Content="Test starten" Padding="14,6" Margin="0,0,8,8"/><Button x:Name="BtnHwDiskStop" Content="Abbrechen" Style="{StaticResource Sec}" Padding="12,6" Margin="0,0,8,8" IsEnabled="False"/>'
    ) ('<TextBlock x:Name="HwDiskLive" Text="" Foreground="#475569" FontSize="12" TextWrapping="Wrap" Margin="0,4,0,0"/>' + (New-HwChartBox 'HwDiskChart' 190) +
       '<TextBlock Text="ZUVERLÄSSIGKEITSWERTE DER LAUFWERKE" FontSize="11" FontWeight="Bold" Foreground="#6B7890" Margin="0,12,0,4"/>' +
       (New-White (New-DataGrid 'HwDiskRelGrid' @('Nr.|Number|45', 'Datenträger|Name|*', 'Art|Media|70', 'Bus|Bus|65', 'Größe|SizeText|80', 'Zustand|Health|85', 'Temperatur|Temp|85', 'Verschleiß|Wear|80', 'Lesefehler (nicht korr.)|ReadErr|140', 'Betriebsstunden|Hours|115') 'Height="140"')) +
       ($hwLogBox -f 'HwDiskLog'))) +

    (New-HwCard 'Cpu' '&#xE945;' '#DC2626' 'Prozessor-Belastungstest' 'Lastet alle (oder ausgewählte) Prozessorkerne mit Rechenarbeit voll aus und misst jede Sekunde Takt, Auslastung und - falls Windows sie liefert - die Temperatur. Erkennt Drosselung (Takt fällt unter Last um mehr als 25 %), Überhitzung und Abstürze. Der Lüfter wird laut, das ist normal. Laptops dabei ans Netzteil anschließen.' (
        (New-Combo 'HwCpuDur' @('1 Minute', '5 Minuten', '10 Minuten') 130) +
        (New-Combo 'HwCpuThreads' @('Alle logischen Prozessoren', 'Hälfte der Prozessoren', 'Ein einzelner Kern') 220) +
        '<Button x:Name="BtnHwCpuStart" Content="Test starten" Padding="14,6" Margin="0,0,8,8"/><Button x:Name="BtnHwCpuStop" Content="Abbrechen" Style="{StaticResource Sec}" Padding="12,6" Margin="0,0,8,8" IsEnabled="False"/>'
    ) ('<TextBlock x:Name="HwCpuLive" Text="" Foreground="#475569" FontSize="12" TextWrapping="Wrap" Margin="0,4,0,0"/>' + (New-HwChartBox 'HwCpuChart' 230))) +

    (New-HwCard 'Bat' '&#xE83F;' '#16A34A' 'Akku-Test' 'Vergleicht die heutige volle Kapazität mit der Kapazität im Neuzustand, zeigt die Ladezyklen und misst 3 Minuten lang ohne Netzteil den tatsächlichen Verbrauch - daraus ergibt sich die realistische Laufzeit.' (
        '<Button x:Name="BtnHwBatStart" Content="3-Minuten-Messung starten" Padding="14,6" Margin="0,0,8,8"/><Button x:Name="BtnHwBatStop" Content="Abbrechen" Style="{StaticResource Sec}" Padding="12,6" Margin="0,0,8,8" IsEnabled="False"/>' +
        '<Button x:Name="BtnHwBatReport" Content="Akkubericht (powercfg /batteryreport)" Style="{StaticResource Sec}" Padding="12,6" Margin="0,0,8,8"/><Button x:Name="BtnHwBatPower" Content="Energieoptionen" Style="{StaticResource Sec}" Padding="12,6" Margin="0,0,8,8"/>'
    ) ((New-InfoRow 'Kapazität neu' 'HwBatDesign') + (New-InfoRow 'Kapazität heute' 'HwBatFull') + (New-InfoRow 'Zustand' 'HwBatHealth') + (New-InfoRow 'Ladezyklen' 'HwBatCycles') + (New-InfoRow 'Aktuell' 'HwBatNow') +
       (New-HwChartBox 'HwBatChart' 130) +
       '<Expander Header="Anleitung: Akku kalibrieren (Prozentanzeige wieder genau machen)" Margin="0,10,0,0" Foreground="#1F2A44"><StackPanel Margin="4,8,0,0">' +
       (($hwBatGuide | ForEach-Object { '<TextBlock Text="{0}" TextWrapping="Wrap" Foreground="#1F2A44" FontSize="12.5" Margin="0,0,0,6"/>' -f (Esc $_) }) -join '') +
       '</StackPanel></Expander>')) +

    '<WrapPanel>' +
    (New-HwCard 'Disp' '&#xE7F4;' '#2D7FF9' 'Bildschirm-Pixeltest' 'Vollbild in Schwarz, Weiß, Rot, Grün, Blau, Graustufen, Farbverläufen und Raster. Weiter mit Klick, Leertaste oder Pfeiltasten, Esc beendet. Achte auf helle oder dunkle Punkte, Flecken, Streifen und ungleichmäßige Ausleuchtung.' (
        '<Button x:Name="BtnHwDispStart" Content="Pixeltest starten" Padding="14,6" Margin="0,0,8,8"/><Button x:Name="BtnHwDispRevive" Content="Pixel-Wiederbeleber" Style="{StaticResource Sec}" Padding="12,6" Margin="0,0,8,8"/>'
    ) '' 380 -NoProgress) +
    (New-HwCard 'Kbd' '&#xE765;' '#7C3AED' 'Tastatur-Test' 'Zeigt eine deutsche Tastatur (QWERTZ) mit Funktionstasten, Pfeil- und Navigationsblock und Ziffernblock. Jede gedrückte Taste wird grün - so fallen tote oder hängende Tasten sofort auf.' (
        '<Button x:Name="BtnHwKbdStart" Content="Tastatur-Test starten" Padding="14,6" Margin="0,0,8,8"/>'
    ) '' 380 -NoProgress) +
    (New-HwCard 'Touch' '&#xE70F;' '#DB2777' 'Touch/Stift-Test' 'Vollbild-Zeichenfläche mit Raster: einfach mit Finger, Stift oder Maus über den ganzen Bildschirm malen. Jedes berührte Feld wird grün - Stellen, die nicht reagieren, bleiben dunkel. Beim Stift wird der Andruck angezeigt.' (
        '<Button x:Name="BtnHwTouchStart" Content="Touch/Stift-Test starten" Padding="14,6" Margin="0,0,8,8"/>'
    ) '' 380 -NoProgress) +
    '</WrapPanel>' +
    (New-Hint 'Tipp für den Gebrauchtkauf: erst den Schnelltest des Datenträgers und den Arbeitsspeicher prüfen (je 2-5 Minuten), dann 5 Minuten Prozessor-Belastung, Akku, Bildschirm, Tastatur und Touch. Am Ende "Prüfprotokoll als PDF" - fertig ist der Nachweis für beide Seiten.'))

# ---- Notfall-Stick
function New-RsStepBadge([string]$No, [string]$Title, [string]$Text) {
    '<Border Background="#26FFFFFF" CornerRadius="12" Padding="14,10" Margin="0,0,12,0" Width="300"><Grid><Grid.ColumnDefinitions><ColumnDefinition Width="Auto"/><ColumnDefinition/></Grid.ColumnDefinitions><Border Width="34" Height="34" CornerRadius="17" Background="#FFFFFF" VerticalAlignment="Top" Margin="0,0,12,0"><TextBlock Text="{0}" FontSize="16" FontWeight="Bold" Foreground="#6D4AE8" HorizontalAlignment="Center" VerticalAlignment="Center"/></Border><StackPanel Grid.Column="1"><TextBlock Text="{1}" Foreground="#FFFFFF" FontWeight="SemiBold" FontSize="14"/><TextBlock Text="{2}" Foreground="#FFFFFF" Opacity="0.9" TextWrapping="Wrap" FontSize="12" Margin="0,2,0,0"/></StackPanel></Grid></Border>' -f (Esc $No), (Esc $Title), (Esc $Text)
}
function New-RsMenuTile([string]$No, [string]$Title, [string]$Text, [string]$Color) {
    '<Border Width="262" Margin="0,0,10,10" Padding="12,10" CornerRadius="12" Background="#F7F9FC" BorderBrush="#E2E7F0" BorderThickness="1"><Grid><Grid.ColumnDefinitions><ColumnDefinition Width="Auto"/><ColumnDefinition/></Grid.ColumnDefinitions><Border Width="30" Height="30" CornerRadius="9" Background="{3}" VerticalAlignment="Top" Margin="0,0,10,0"><TextBlock Text="{0}" Foreground="#FFFFFF" FontWeight="Bold" HorizontalAlignment="Center" VerticalAlignment="Center"/></Border><StackPanel Grid.Column="1"><TextBlock Text="{1}" FontWeight="SemiBold" Foreground="#1F2A44" TextWrapping="Wrap"/><TextBlock Text="{2}" Foreground="#6B7890" FontSize="12" TextWrapping="Wrap" Margin="0,2,0,0"/></StackPanel></Grid></Border>' -f (Esc $No), (Esc $Title), (Esc $Text), $Color
}
$rsMenuTiles = @(
    (New-RsMenuTile '1' 'Startdateien neu schreiben' 'bcdboot: bei "Bootmanager fehlt", 0xc000000f, Windows fehlt im Startmenü' '#2D7FF9'),
    (New-RsMenuTile '2' 'Systemdateien prüfen' 'sfc /scannow offline: beschädigte Windows-Dateien ersetzen' '#16A34A'),
    (New-RsMenuTile '3' 'Komponentenspeicher reparieren' 'DISM /RestoreHealth offline, auf Wunsch mit install.wim als Quelle' '#16A34A'),
    (New-RsMenuTile '4' 'Datenträger prüfen' 'chkdsk /f (Dateisystem) oder /r (defekte Sektoren)' '#0891B2'),
    (New-RsMenuTile '5' 'Updates zurücknehmen' 'DISM /RevertPendingActions: wenn Windows nach einem Update hängt' '#EA580C'),
    (New-RsMenuTile '6' 'Dateien auf den Stick sichern' 'Desktop, Dokumente, Bilder, Videos, Downloads, OneDrive (lokal) aller Benutzer' '#DB2777'),
    (New-RsMenuTile '7' 'Systemwiederherstellung' 'rstrui /offline: auf einen Wiederherstellungspunkt zurück' '#6D4AE8'),
    (New-RsMenuTile '8' 'Notepad als Dateimanager' 'Datei > Öffnen: Dateien ansehen, kopieren, umbenennen' '#52627A'),
    (New-RsMenuTile '9' 'Treiber einspielen' 'Treiber-Sicherung vom Stick offline in Windows einspielen' '#52627A'),
    (New-RsMenuTile 'B' 'BitLocker entsperren' 'manage-bde mit dem 48-stelligen Wiederherstellungsschlüssel' '#B91C1C'),
    (New-RsMenuTile 'D' 'Speichertreiber laden' 'drvload für Intel RST/VMD/NVMe, wenn die SSD fehlt' '#B91C1C'),
    (New-RsMenuTile '0' 'Neustart' 'wpeutil reboot - vorher den Stick abziehen' '#52627A')
) -join ''
$rsCheckX = '<DataGrid x:Name="RsCheckGrid" Height="300"><DataGrid.RowStyle><Style TargetType="DataGridRow" BasedOn="{StaticResource {x:Type DataGridRow}}"><Style.Triggers>' +
    '<DataTrigger Binding="{Binding Rank}" Value="0"><Setter Property="Foreground" Value="#C81E1E"/><Setter Property="FontWeight" Value="SemiBold"/></DataTrigger><DataTrigger Binding="{Binding Rank}" Value="1"><Setter Property="Foreground" Value="#B45309"/></DataTrigger><DataTrigger Binding="{Binding Rank}" Value="3"><Setter Property="Foreground" Value="#15803D"/></DataTrigger>' +
    '</Style.Triggers></Style></DataGrid.RowStyle><DataGrid.Columns><DataGridTextColumn Header="Status" Binding="{Binding State}" Width="95"/><DataGridTextColumn Header="Bestandteil" Binding="{Binding Item}" Width="330"/><DataGridTextColumn Header="Details" Binding="{Binding Detail}" Width="*"/></DataGrid.Columns></DataGrid>'
$rsWrap = '<DataGridTextColumn.ElementStyle><Style TargetType="TextBlock"><Setter Property="TextWrapping" Value="Wrap"/></Style></DataGridTextColumn.ElementStyle>'
$rsKeysX = ('<DataGrid x:Name="RsKeyGrid" Height="330" HeadersVisibility="Column"><DataGrid.Columns><DataGridTextColumn Header="Hersteller" Binding="{{Binding Maker}}" Width="210">{0}</DataGridTextColumn><DataGridTextColumn Header="Boot-Menü (Stick wählen)" Binding="{{Binding Menu}}" Width="*">{0}</DataGridTextColumn><DataGridTextColumn Header="BIOS / UEFI" Binding="{{Binding Setup}}" Width="170">{0}</DataGridTextColumn><DataGridTextColumn Header="Hinweis" Binding="{{Binding Note}}" Width="260">{0}</DataGridTextColumn></DataGrid.Columns></DataGrid>' -f $rsWrap)
$pageRescue = New-Page 'Notfall-Stick' 'Ein bootfähiger Reparatur-Stick für deine eigenen PCs: Startet Windows nicht mehr, startest du vom Stick die Windows-Wiederherstellungsumgebung dieses PCs mit einem Reparatur-Menü (Startdateien, Systemdateien, Datenträger, hängende Updates, Systemwiederherstellung, BitLocker) - und kannst vorher persönliche Dateien auf den Stick retten. Dazu kommen die portablen PC-Tools, deine Toolbox und eine Treiber-Sicherung.' (
    ('<Border CornerRadius="16" Padding="22,18" Margin="0,0,4,16" Background="{StaticResource HeroGrad}"><StackPanel>' +
     '<TextBlock Text="Der Rettungsanker, wenn Windows nicht mehr startet" Foreground="#FFFFFF" FontSize="19" FontWeight="SemiBold"/>' +
     '<TextBlock Foreground="#FFFFFF" Opacity="0.93" TextWrapping="Wrap" Margin="0,6,0,14" Text="' + (Esc 'Schwarzer Bildschirm, "Automatische Reparatur" in der Endlosschleife, "Bootmanager fehlt", Bluescreen beim Start oder Hänger nach einem Update: Mit diesem Stick startest du das offizielle Reparatursystem von Microsoft (WinRE) - unabhängig von der kaputten Festplatte. Einmal erstellen, in die Schublade legen, im Notfall einstecken. Dauer: 3-10 Minuten.') + '"/>' +
     '<WrapPanel>' + (New-RsStepBadge '1' 'Stick erstellen' 'USB-Stick ab 4 GB wählen, Inhalt ankreuzen, "Stick erstellen" - fertig.') + (New-RsStepBadge '2' 'Vom Stick starten' 'Boot-Menü-Taste (F9, F12, Surface: Leiser-Taste) oder Umschalt + Neu starten > Gerät verwenden.') + (New-RsStepBadge '3' 'Reparieren' 'Problembehandlung > Eingabeaufforderung > Reparatur.cmd - geführtes Menü.') + '</WrapPanel>' +
     '</StackPanel></Border>') +
    ('<WrapPanel Margin="0,0,0,6">' + (New-StatTile 'RsS0' 'Wiederherstellungsumgebung (WinRE) dieses PCs' '#16A34A') + (New-StatTile 'RsS1' 'Größe des Reparatursystems' '#2D7FF9') + (New-StatTile 'RsS2' 'USB-Sticks eingesteckt' '#6D4AE8') + (New-StatTile 'RsS3' 'Start-Modus dieses PCs' '#0891B2') + '</WrapPanel>') +
    '<Border x:Name="RsBanner" Background="#FFF7ED" BorderBrush="#FDBA74" BorderThickness="1" CornerRadius="8" Padding="12,8" Margin="0,0,0,12" Visibility="Collapsed"><TextBlock x:Name="RsBannerText" TextWrapping="Wrap" Foreground="#9A3412" FontWeight="SemiBold"/></Border>' +
    (New-Card '1. USB-Stick wählen' @(
        '<Grid><Grid.ColumnDefinitions><ColumnDefinition Width="140"/><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions><TextBlock Text="USB-Stick" VerticalAlignment="Center"/><ComboBox x:Name="RsDisk" Grid.Column="1" Margin="0,0,8,0"/><Button x:Name="BtnRsRefresh" Grid.Column="2" Content="Aktualisieren" Style="{StaticResource Sec}" Margin="0" Padding="12,5"/></Grid>',
        '<TextBlock x:Name="RsDiskInfo" Foreground="#6B7890" TextWrapping="Wrap" Margin="0,8,0,0" Text="-"/>',
        (New-Hint 'Es werden nur USB-Datenträger angezeigt - nie die interne Festplatte/SSD und nie das Laufwerk, von dem Windows läuft. Empfehlung: ein eigener Stick mit 8-64 GB, USB 3, der nur für den Notfall da ist.'))) +
    (New-Card '2. Was soll auf den Stick?' @(
        '<CheckBox x:Name="RsRepair" IsChecked="True" Margin="0,2,0,2"><TextBlock Text="Reparatursystem (bootfähig)" FontWeight="SemiBold"/></CheckBox>',
        '<StackPanel x:Name="RsSrcPanel" Margin="26,0,0,10">',
        (New-Hint 'Die Windows-Wiederherstellungsumgebung (WinRE) mit Starthilfe, Systemwiederherstellung, Updates deinstallieren, UEFI-Einstellungen und Eingabeaufforderung - plus das Reparatur-Menü von PC-Tools (\Reparatur\Reparatur.cmd). Startet im UEFI-Modus, auch mit Secure Boot.'),
        '<RadioButton x:Name="RsSrcLatest" GroupName="RsSrc" IsChecked="True" Margin="0,2,0,4"><TextBlock TextWrapping="Wrap"><Run FontWeight="SemiBold" Text="Neueste offizielle Windows-11-ISO von Microsoft (empfohlen)"/><Run Text=" - wird automatisch geladen (ca. 7 GB, danach zwischengespeichert und nur bei neuer Version erneut geladen). Startet auf jedem PC, auch mit Secure Boot. Die ISO und die Reparaturquelle für DISM kommen zusätzlich auf die exFAT-Datenpartition."/></TextBlock></RadioButton>',
        '<RadioButton x:Name="RsSrcWinRe" GroupName="RsSrc" Margin="0,2,0,4" Content="Wiederherstellungsumgebung dieses PCs (schnell, ca. 500-900 MB - bei Insider-PCs startet sie mit Secure Boot nicht auf anderen Geräten)"/>',
        '<RadioButton x:Name="RsSrcIso" GroupName="RsSrc" Margin="0,2,0,4" Content="boot.wim aus einer Windows-ISO (Windows-Setup mit &quot;Computerreparaturoptionen&quot;)"/>',
        '<Grid Margin="22,2,0,0"><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions><TextBox x:Name="RsIso" Margin="0,0,8,0" Padding="4,3" IsEnabled="False"/><Button x:Name="BtnRsIsoBrowse" Grid.Column="1" Content="ISO wählen ..." Style="{StaticResource Sec}" Margin="0" Padding="12,5" IsEnabled="False"/></Grid>',
        '</StackPanel>',
        '<CheckBox x:Name="RsPflege" IsChecked="True" Margin="0,2,0,2"><TextBlock Text="Portable PC-Tools (mit Netzwerk-Notfall und Netzwerk-Tiefenanalyse)" FontWeight="SemiBold"/></CheckBox>',
        '<StackPanel Margin="26,0,0,10"><TextBlock Foreground="#6B7890" FontSize="12" TextWrapping="Wrap" Text="Läuft auf jedem PC mit Windows direkt vom Stick, ohne Installation. Im Reparatursystem selbst gibt es kein PowerShell - dort hilft das Reparatur-Menü."/><CheckBox x:Name="RsToken" Margin="0,4,0,0" Content="Update-Zugang (nur Lesen) mitkopieren - damit sich die Stick-Kopie selbst aktualisieren kann"/></StackPanel>',
        '<CheckBox x:Name="RsToolbox" Margin="0,2,0,2"><TextBlock Text="Toolbox-Ordner mitkopieren" FontWeight="SemiBold"/></CheckBox>',
        '<TextBlock x:Name="RsToolboxInfo" Foreground="#6B7890" FontSize="12" TextWrapping="Wrap" Margin="26,0,0,10" Text="-"/>',
        '<CheckBox x:Name="RsDrivers" Margin="0,2,0,2"><TextBlock Text="Treiber-Sicherung dieses PCs" FontWeight="SemiBold"/></CheckBox>',
        '<TextBlock x:Name="RsDriversInfo" Foreground="#6B7890" FontSize="12" TextWrapping="Wrap" Margin="26,0,0,10" Text="Alle installierten Drittanbieter-Treiber (Export-WindowsDriver) nach \Treiber\&lt;PC-Name&gt; - für eine Neuinstallation oder wenn die SSD im Reparatursystem ohne Treiber nicht sichtbar ist (Intel RST/VMD). Dauert 1-5 Minuten, meist 0,5-3 GB."/>',
        '<Border Background="#EFF6FF" BorderBrush="#BFDBFE" BorderThickness="1" CornerRadius="10" Padding="12,10" Margin="0,4,0,0"><Grid><Grid.ColumnDefinitions><ColumnDefinition Width="Auto"/><ColumnDefinition/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions><TextBlock Text="&#xE70A;" FontFamily="Segoe MDL2 Assets" FontSize="20" Foreground="#2563EB" VerticalAlignment="Center" Margin="0,0,12,0"/><TextBlock Grid.Column="1" TextWrapping="Wrap" Foreground="#1E3A8A" VerticalAlignment="Center" Text="Surface im Haus? Das komplette Surface-Treiber- und Firmwarepaket (MSI) passt mit auf den Stick: Seite Microsoft Surface > Modell wählen > &quot;Auf USB-Stick / in Ordner laden&quot; und dort den Stick (Ordner \Surface) wählen."/><Button x:Name="BtnRsSurface" Grid.Column="2" Content="Zur Seite Microsoft Surface" Style="{StaticResource Sec}" Margin="12,0,0,0"/></Grid></Border>')) +
    (New-Card '3. Stick erstellen' @(
        '<CheckBox x:Name="RsFormat" IsChecked="True" Margin="0,2,0,2"><TextBlock Text="Stick neu einrichten - LÖSCHT ALLE DATEN auf dem Stick (beim ersten Mal nötig)" FontWeight="SemiBold" Foreground="#B91C1C"/></CheckBox>',
        (New-Hint 'Neu einrichten: bis 32 GB eine FAT32-Partition "PCT-NOTFALL" (UEFI startet nur von FAT32). Größere Sticks bekommen zusätzlich eine exFAT-Partition "PCT-DATEN" für Sicherungen, Treiber und große Dateien (keine 4-GB-Grenze). Ohne Haken wird ein vorhandener Notfall-Stick nur aktualisiert bzw. ergänzt - dafür muss er schon eine FAT32-Partition haben.'),
        '<WrapPanel Margin="0,6,0,0"><Button x:Name="BtnRsBuild" Content="Stick erstellen" Padding="18,7" FontWeight="SemiBold"/><Button x:Name="BtnRsCheck" Content="Stick prüfen" Style="{StaticResource Sec}"/><Button x:Name="BtnRsOpen" Content="Stick im Explorer öffnen" Style="{StaticResource Sec}"/><Button x:Name="BtnRsReadme" Content="Anleitung anzeigen" Style="{StaticResource Sec}"/><Button x:Name="BtnRsBootNow" Content="Neustart: vom Stick starten ..." Style="{StaticResource Sec}"/></WrapPanel>',
        (New-Hint 'Das Erstellen läuft im Hintergrund weiter, auch wenn du das Fenster schließt - Fortschritt unten und im Protokoll. Testen: "Neustart: vom Stick starten" öffnet den erweiterten Start von Windows; dort "Ein Gerät verwenden" und den Stick wählen.'))) +
    (New-Card 'Was ist auf dem Stick?' @(
        '<TextBlock x:Name="RsCheckInfo" Foreground="#6B7890" TextWrapping="Wrap" Margin="0,0,0,6" Text="Stick einstecken, oben wählen und &quot;Stick prüfen&quot; klicken."/>',
        '<ProgressBar x:Name="RsProgress" Height="6" IsIndeterminate="True" Visibility="Collapsed" Margin="0,0,0,8" Foreground="{StaticResource AccentGrad}" Background="#E3E8F2" BorderThickness="0"/>',
        (New-White $rsCheckX))) +
    (New-Card 'Das Reparatur-Menü auf dem Stick' @(
        (New-Hint 'Im Reparatursystem: Tastaturlayout "Deutsch" > Problembehandlung > Erweiterte Optionen > Eingabeaufforderung. Dann diese Zeile tippen (findet den Stick unabhängig vom Laufwerksbuchstaben):'),
        '<TextBox IsReadOnly="True" FontFamily="Consolas" FontSize="13" Padding="8,6" Margin="0,0,0,10" Text="for %i in (C D E F G H I J K L M N O P) do @if exist %i:\Reparatur\Reparatur.cmd %i:\Reparatur\Reparatur.cmd"/>',
        ('<WrapPanel>' + $rsMenuTiles + '</WrapPanel>'),
        (New-Hint 'Das Menü findet das installierte Windows selbst (sucht \Windows\System32\config\SYSTEM auf C: bis Z:), fragt vor jedem Schritt nach und schreibt alles in "Reparatur-Protokoll.txt" auf dem Stick. Empfohlene Reihenfolge, wenn Windows nicht startet: erst Dateien sichern (6), dann 1 > 4 > 3 > 2; nach einem missglückten Update 5 und danach 7.'))) +
    (New-Card 'Boot-Tasten, Secure Boot und BitLocker' @(
        (New-White $rsKeysX),
        (New-Hint 'Secure Boot darf an bleiben: Der Stick nutzt den von Microsoft signierten Start-Manager dieses PCs. Meldet ein anderer PC "Secure Boot violation", hat er eine andere Zertifikatsgeneration (Windows UEFI CA 2023 statt PCA 2011) - dann den Stick auf einem aktuellen PC neu erstellen. BitLocker: Im Reparatursystem ist das Windows-Laufwerk gesperrt - den 48-stelligen Wiederherstellungsschlüssel bereithalten (aka.ms/myrecoverykey oder die Schlüssel-Datei von PC-Tools), Menüpunkt B.'))))

# ---- Fernhilfe
$FhCategories = @('Internet / WLAN geht nicht', 'Drucker / Scanner', 'PC ist langsam oder hängt', 'Fehlermeldung / Absturz / Bluescreen', 'E-Mail / Outlook', 'Programm installieren oder Update', 'Verdacht auf Virus oder Betrug (Anruf, Pop-up)', 'Passwort / Anmeldung', 'Sonstiges')
function New-FhTile([string]$Key, [string]$Glyph, [string]$Color, [string]$Title, [string]$Text, [string]$Btn) {
    '<Border Width="265" Margin="0,0,12,12" Padding="14,12" CornerRadius="14" Background="#FFFFFF" BorderBrush="#E2E7F0" BorderThickness="1"><StackPanel><Grid><Grid.ColumnDefinitions><ColumnDefinition Width="Auto"/><ColumnDefinition/></Grid.ColumnDefinitions><Border Width="42" Height="42" CornerRadius="12" Background="{2}" Margin="0,0,12,0"><TextBlock Text="{1}" FontFamily="Segoe MDL2 Assets" FontSize="20" Foreground="#FFFFFF" HorizontalAlignment="Center" VerticalAlignment="Center"/></Border><TextBlock Grid.Column="1" Text="{3}" FontSize="15" FontWeight="SemiBold" Foreground="#1F2A44" VerticalAlignment="Center" TextWrapping="Wrap"/></Grid><TextBlock Text="{4}" Foreground="#6B7890" FontSize="12" TextWrapping="Wrap" Margin="0,8,0,6" MinHeight="48"/><TextBlock x:Name="FhSt{0}" Text="-" Foreground="#1F2A44" FontSize="12" TextWrapping="Wrap" Margin="0,0,0,8"/><Button x:Name="BtnFh{0}" Content="{5}" HorizontalAlignment="Left" Margin="0"/></StackPanel></Border>' -f $Key, $Glyph, $Color, (Esc $Title), (Esc $Text), (Esc $Btn)
}
function New-FhBig([string]$Name, [string]$Label, [int]$Size = 15) {
    '<StackPanel Margin="0,0,28,10" MinWidth="200"><TextBlock Text="{1}" Foreground="#6B7890" FontSize="12"/><TextBox x:Name="{0}" Text="-" FontSize="{2}" FontWeight="SemiBold" Foreground="#1F2A44" IsReadOnly="True" BorderThickness="0" Background="Transparent" Padding="0" TextWrapping="Wrap"/></StackPanel>' -f $Name, (Esc $Label), $Size
}
$pageRemote = New-Page 'Fernhilfe' 'Hilfe holen und Hilfe geben: Mit einem Klick ein Hilfe-Paket (Zustand, Netzwerk, Fehler, Bildschirmfoto) schnüren und deinen Helfer per Handy-Nachricht benachrichtigen, dann per Windows-Schnellhilfe, RustDesk, TeamViewer QuickSupport oder AnyDesk verbinden - die Programme werden geladen und vor dem Start auf eine gültige Signatur geprüft. Für Helfer: Schnellhilfe/RustDesk öffnen und eine Anleitung für den Hilfesuchenden kopieren.' (
    ('<Border CornerRadius="16" Padding="22,18" Margin="0,0,4,16" Background="{StaticResource HeroGrad}"><Grid><Grid.ColumnDefinitions><ColumnDefinition Width="Auto"/><ColumnDefinition/></Grid.ColumnDefinitions>' +
     '<Border Width="64" Height="64" CornerRadius="32" Background="#33FFFFFF" Margin="0,0,18,0" VerticalAlignment="Top"><TextBlock Text="&#xE897;" FontFamily="Segoe MDL2 Assets" FontSize="30" Foreground="#FFFFFF" HorizontalAlignment="Center" VerticalAlignment="Center"/></Border>' +
     '<StackPanel Grid.Column="1"><TextBlock Text="Brauchst du Hilfe am PC?" Foreground="#FFFFFF" FontSize="20" FontWeight="SemiBold"/>' +
     '<TextBlock Foreground="#FFFFFF" Opacity="0.93" TextWrapping="Wrap" Margin="0,6,0,8" Text="' + (Esc 'Beschreibe kurz, was nicht klappt, und klicke auf "Hilfe anfordern". PC-Tools sammelt alles, was dein Helfer wissen muss, und schickt ihm eine Nachricht. Dann meldet er sich - oder du rufst an und startest unten die Fernwartung.') + '"/>' +
     '<TextBlock x:Name="FhHelperShow" Foreground="#FFFFFF" FontWeight="SemiBold" FontSize="14" TextWrapping="Wrap" Text="-"/></StackPanel></Grid></Border>') +
    ('<Border Background="White" CornerRadius="14" Padding="0" Margin="0,0,4,16" BorderBrush="#E2E7F0" BorderThickness="1"><Border.Effect><DropShadowEffect BlurRadius="18" ShadowDepth="2" Direction="270" Opacity="0.09" Color="Black"/></Border.Effect><Grid><Grid.ColumnDefinitions><ColumnDefinition Width="8"/><ColumnDefinition/></Grid.ColumnDefinitions><Border CornerRadius="14,0,0,14" Background="{StaticResource AccentGrad}"/><StackPanel Grid.Column="1" Margin="22,18,22,18">' +
     '<TextBlock Text="Hilfe anfordern" FontSize="20" FontWeight="SemiBold" Foreground="#1F2A44" Margin="0,0,0,10"/>' +
     (New-FieldRow 'Worum geht es?' ('<ComboBox x:Name="FhCat" Width="380" HorizontalAlignment="Left" SelectedIndex="0">{0}</ComboBox>' -f (($FhCategories | ForEach-Object { '<ComboBoxItem Content="{0}"/>' -f (Esc $_) }) -join ''))) +
     (New-FieldRow 'Was ist passiert? (in eigenen Worten)' '<TextBox x:Name="FhDesc" Height="96" TextWrapping="Wrap" AcceptsReturn="True" VerticalScrollBarVisibility="Auto" Padding="6,4"/>') +
     '<WrapPanel Margin="0,8,0,4"><CheckBox x:Name="FhShot" IsChecked="True" Margin="0,0,22,6" Content="Bildschirmfoto mitschicken (PC-Tools wird dafür kurz ausgeblendet)"/><CheckBox x:Name="FhNet" IsChecked="True" Margin="0,0,22,6" Content="Netzwerk prüfen (ca. 20-40 Sekunden)"/><CheckBox x:Name="FhEvents" IsChecked="True" Margin="0,0,0,6" Content="Fehlermeldungen der letzten 48 Stunden"/></WrapPanel>' +
     '<StackPanel Orientation="Horizontal" Margin="0,6,0,0"><Button x:Name="BtnFhSend" Padding="26,10" FontSize="16" FontWeight="SemiBold" Margin="0,0,12,0"><StackPanel Orientation="Horizontal"><TextBlock Text="&#xE724;" FontFamily="Segoe MDL2 Assets" Margin="0,0,10,0" VerticalAlignment="Center"/><TextBlock Text="Hilfe anfordern" VerticalAlignment="Center"/></StackPanel></Button><TextBlock x:Name="FhSendInfo" VerticalAlignment="Center" Foreground="#6B7890" TextWrapping="Wrap" MaxWidth="560" Text="Nichts wird ohne diesen Klick verschickt. Das Paket bleibt auf diesem PC; die Nachricht enthält nur eine Kurzfassung."/></StackPanel>' +
     '<ProgressBar x:Name="FhProgress" Height="6" IsIndeterminate="True" Visibility="Collapsed" Margin="0,12,0,0" Foreground="{StaticResource AccentGrad}" Background="#E3E8F2" BorderThickness="0"/>' +
     '<Border x:Name="FhResult" Visibility="Collapsed" Background="#F0FDF4" BorderBrush="#86EFAC" BorderThickness="1" CornerRadius="10" Padding="14,12" Margin="0,14,0,0"><StackPanel><StackPanel Orientation="Horizontal"><TextBlock x:Name="FhResultGlyph" Text="&#xE73E;" FontFamily="Segoe MDL2 Assets" FontSize="18" Foreground="#15803D" Margin="0,0,10,0" VerticalAlignment="Center"/><TextBlock x:Name="FhResultTitle" FontSize="15" FontWeight="SemiBold" Foreground="#166534" VerticalAlignment="Center" TextWrapping="Wrap"/></StackPanel>' +
     '<TextBox x:Name="FhResultText" Margin="0,8,0,8" IsReadOnly="True" FontFamily="Consolas" FontSize="12" MaxHeight="220" VerticalScrollBarVisibility="Auto" TextWrapping="Wrap" Background="#FFFFFF"/>' +
     '<WrapPanel><Button x:Name="BtnFhOpenZip" Content="Paket im Ordner zeigen" Style="{StaticResource Sec}"/><Button x:Name="BtnFhMail" Content="Per E-Mail an Helfer ..." Style="{StaticResource Sec}"/><Button x:Name="BtnFhCopySum" Content="Zusammenfassung kopieren" Style="{StaticResource Sec}"/></WrapPanel></StackPanel></Border>' +
     '</StackPanel></Grid></Border>') +
    (New-Card 'Das liest du deinem Helfer vor' @(
        '<WrapPanel>' + (New-FhBig 'FhPc' 'PC-Name' 24) + (New-FhBig 'FhUser' 'Benutzer' 18) + (New-FhBig 'FhIp' 'IP-Adresse(n)' 18) + '</WrapPanel>',
        '<WrapPanel>' + (New-FhBig 'FhWin' 'Windows' 14) + (New-FhBig 'FhModel' 'Gerät / Seriennummer' 14) + (New-FhBig 'FhIds' 'Fernwartungs-IDs' 14) + '</WrapPanel>',
        '<WrapPanel Margin="0,4,0,0"><Button x:Name="BtnFhCopyInfo" Content="Angaben kopieren" Style="{StaticResource Sec}"/><Button x:Name="BtnFhRefreshInfo" Content="Neu einlesen" Style="{StaticResource Sec}"/></WrapPanel>')) +
    (New-Card 'Fernwartung starten (dein Helfer sieht deinen Bildschirm)' @(
        (New-Hint 'Welches Programm? Das, das dein Helfer sagt. Schnellhilfe ist in Windows eingebaut; die anderen werden beim ersten Klick von der Hersteller-Seite geladen (5-30 MB), auf eine gültige digitale Signatur des Herstellers geprüft und erst dann gestartet. Nichts wird installiert.'),
        ('<WrapPanel Margin="0,4,0,0">' +
         (New-FhTile 'Qa' '&#xE897;' '#2D7FF9' 'Windows-Schnellhilfe' 'In Windows eingebaut. Der Helfer nennt dir einen 6-stelligen Code, du trägst ihn unter "Hilfe erhalten" ein.' 'Schnellhilfe öffnen') +
         (New-FhTile 'Rd' '&#xE8AF;' '#EA580C' 'RustDesk' 'Kostenlos, quelloffen. Du nennst dem Helfer ID und Einmal-Passwort aus dem Fenster.' 'RustDesk starten') +
         (New-FhTile 'Tv' '&#xE7F4;' '#0891B2' 'TeamViewer QuickSupport' 'Das kleine Kunden-Modul von TeamViewer. Du nennst dem Helfer ID und Passwort.' 'QuickSupport starten') +
         (New-FhTile 'Ad' '&#xE703;' '#DC2626' 'AnyDesk' 'Du nennst dem Helfer die Nummer unter "Dieser Arbeitsplatz" und klickst auf "Annehmen".' 'AnyDesk starten') + '</WrapPanel>'),
        '<ProgressBar x:Name="FhDlProgress" Height="6" IsIndeterminate="True" Visibility="Collapsed" Margin="0,0,0,8" Foreground="{StaticResource AccentGrad}" Background="#E3E8F2" BorderThickness="0"/>',
        '<TextBlock x:Name="FhDlInfo" Foreground="#6B7890" TextWrapping="Wrap" Text=""/>',
        '<Border Background="#FEF2F2" BorderBrush="#FCA5A5" BorderThickness="1" CornerRadius="10" Padding="12,10" Margin="0,10,0,0"><StackPanel Orientation="Horizontal"><TextBlock Text="&#xE7BA;" FontFamily="Segoe MDL2 Assets" FontSize="18" Foreground="#B91C1C" Margin="0,0,10,0" VerticalAlignment="Top"/><TextBlock TextWrapping="Wrap" MaxWidth="1000" Foreground="#991B1B" Text="Vorsicht vor Betrügern: Microsoft, deine Bank, die Polizei oder ein &quot;Techniker&quot; rufen NIE unaufgefordert an und wollen auf deinen PC. Gib Codes, IDs und Passwörter nur Menschen, die du selbst angerufen hast und kennst."/></StackPanel></Border>')) +
    (New-Card 'Ich helfe jemandem' @(
        (New-Hint 'Für dich als Helfer: Schnellhilfe unter "Hilfe leisten" öffnen (Anmeldung mit Microsoft-Konto nötig) und dem anderen den Code sagen - oder RustDesk öffnen und dort ID und Passwort des anderen eintragen. Die Anleitung unten kannst du kopieren und per Messenger oder E-Mail schicken.'),
        '<WrapPanel Margin="0,0,0,8"><Button x:Name="BtnFhHelpQa" Content="Schnellhilfe öffnen (Hilfe leisten)"/><Button x:Name="BtnFhHelpRd" Content="RustDesk öffnen" Style="{StaticResource Sec}"/></WrapPanel>',
        '<Grid><Grid.ColumnDefinitions><ColumnDefinition Width="Auto"/><ColumnDefinition Width="Auto"/><ColumnDefinition/></Grid.ColumnDefinitions><TextBlock Text="Anleitung für" VerticalAlignment="Center" Margin="0,0,10,8"/>' + (New-Combo 'FhGuideTool' @('Schnellhilfe', 'RustDesk', 'TeamViewer', 'AnyDesk') 200).Replace('<ComboBox ', '<ComboBox Grid.Column="1" ') + '<Button x:Name="BtnFhCopyGuide" Grid.Column="2" Content="Anleitung kopieren" HorizontalAlignment="Left" Margin="0,0,0,8"/></Grid>',
        '<TextBox x:Name="FhGuideText" Height="190" IsReadOnly="True" TextWrapping="Wrap" VerticalScrollBarVisibility="Auto" Padding="6,4" FontSize="13"/>')) +
    (New-Card 'Einstellungen: dein Helfer' @(
        (New-FieldRow 'Name des Helfers' '<TextBox x:Name="FhName" Width="320" HorizontalAlignment="Left" Padding="4,3"/>'),
        (New-FieldRow 'Telefon' '<TextBox x:Name="FhPhone" Width="320" HorizontalAlignment="Left" Padding="4,3"/>'),
        (New-FieldRow 'E-Mail' '<TextBox x:Name="FhMail" Width="320" HorizontalAlignment="Left" Padding="4,3"/>'),
        (New-FieldRow 'Bevorzugtes Programm' (New-Combo 'FhTool' @('Schnellhilfe', 'RustDesk', 'TeamViewer', 'AnyDesk') 200)),
        '<WrapPanel Margin="0,8,0,0"><Button x:Name="BtnFhSave" Content="Speichern"/><Button x:Name="BtnFhNotify" Content="Handy-Benachrichtigung einrichten" Style="{StaticResource Sec}"/><Button x:Name="BtnFhDir" Content="Ordner mit Hilfe-Paketen" Style="{StaticResource Sec}"/></WrapPanel>',
        (New-Hint 'Die Nachricht bei "Hilfe anfordern" geht über die Kanäle aus Meine PCs > Handy-Benachrichtigungen (ntfy, Home Assistant, Chat-Webhook) - auch wenn die automatischen Benachrichtigungen dort ausgeschaltet sind. Ist in Meine PCs ein gemeinsamer Ordner (NAS) eingetragen, landet das Hilfe-Paket zusätzlich dort im Unterordner "Hilfe". Gespeichert in fernhilfe.json im Datenordner.'))))
# ---------------------------------------------------------------- Netzwerk-Werkzeuge und Geräte-Akte (Seiten)
function New-NtProgress([string]$Bar, [string]$Label) {
    '<StackPanel Margin="0,2,0,8"><ProgressBar x:Name="{0}" Height="6" Minimum="0" Maximum="100" Visibility="Collapsed" Foreground="{{StaticResource AccentGrad}}" Background="#E3E8F2" BorderThickness="0"/><TextBlock x:Name="{1}" Text="" Foreground="#6B7890" FontSize="12" Margin="0,4,0,0" TextWrapping="Wrap"/></StackPanel>' -f $Bar, $Label
}
function New-NtChartBox([string]$Canvas, [int]$Height) {
    '<Border Background="#F8FAFD" CornerRadius="10" BorderBrush="#E2E7F0" BorderThickness="1" Padding="10,8" Margin="0,4,0,8"><Canvas x:Name="{0}" Height="{1}" ClipToBounds="True"/></Border>' -f $Canvas, $Height
}
function New-NtLegend([string[]]$Items) {
    $x = foreach ($i in $Items) { $f = $i -split '\|'; '<StackPanel Orientation="Horizontal" Margin="0,0,18,4"><Border Width="14" Height="4" CornerRadius="2" Background="{0}" VerticalAlignment="Center" Margin="0,0,6,0"/><TextBlock Text="{1}" Foreground="#6B7890" FontSize="12"/></StackPanel>' -f $f[0], (Esc $f[1]) }
    '<WrapPanel Margin="2,0,0,2">{0}</WrapPanel>' -f ($x -join '')
}
function New-NtSection([string]$Name, [string]$Glyph, [string]$Color, [string]$Title, [string]$Intro, [string[]]$Rows) {
    $head = '<Grid Margin="0,0,0,10"><Grid.ColumnDefinitions><ColumnDefinition Width="Auto"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions><Border Width="38" Height="38" CornerRadius="10" Background="{0}" Margin="0,0,12,0" VerticalAlignment="Top"><TextBlock Text="{1}" FontFamily="Segoe MDL2 Assets" FontSize="18" Foreground="#FFFFFF" HorizontalAlignment="Center" VerticalAlignment="Center"/></Border><StackPanel Grid.Column="1"><TextBlock Text="{2}" FontSize="17" FontWeight="SemiBold" Foreground="#1F2A44"/><TextBlock Text="{3}" Foreground="#6B7890" FontSize="12.5" TextWrapping="Wrap" Margin="0,2,0,0"/></StackPanel></Grid>' -f $Color, $Glyph, (Esc $Title), (Esc $Intro)
@"
<Border x:Name="$Name" Background="White" CornerRadius="14" Padding="20,16" Margin="0,0,4,16" BorderBrush="#E2E7F0" BorderThickness="1">
  <Border.Effect><DropShadowEffect BlurRadius="18" ShadowDepth="2" Direction="270" Opacity="0.07" Color="Black"/></Border.Effect>
  <StackPanel>
    $head
    $($Rows -join "`n")
  </StackPanel>
</Border>
"@
}
$ntJump = '<WrapPanel Margin="0,0,0,12">' + ((@('NtJDev|&#xE968;|Geräte im Netz', 'NtJWol|&#xE7E8;|Wake-on-LAN', 'NtJSpeed|&#xEC4A;|Speedtest-Verlauf', 'NtJDns|&#xE774;|DNS-Vergleich', 'NtJWlan|&#xE701;|WLAN-Kanäle', 'NtJRouter|&#xE839;|Router-Check') | ForEach-Object {
            $f = $_ -split '\|'; '<Button x:Name="{0}" Style="{{StaticResource Sec}}" Padding="12,6" Margin="0,0,8,8"><StackPanel Orientation="Horizontal"><TextBlock Text="{1}" FontFamily="Segoe MDL2 Assets" Margin="0,0,8,0" VerticalAlignment="Center"/><TextBlock Text="{2}" VerticalAlignment="Center"/></StackPanel></Button>' -f $f[0], $f[1], (Esc $f[2]) }) -join '') + '</WrapPanel>'
$ntTiles = '<WrapPanel Margin="0,0,0,4">' + (New-StatTile 'NtT0' 'Geräte im Netz (letzter Scan)' '#2D7FF9') + (New-StatTile 'NtT1' 'neu seit dem Scan davor' '#EA580C') + (New-StatTile 'NtT2' 'Download zuletzt (Mbit/s)' '#16A34A') + (New-StatTile 'NtT3' 'schnellster DNS (ms)' '#6D4AE8') + '</WrapPanel>'

$pageNetTools = New-Page 'Netzwerk-Werkzeuge' 'Werkzeuge für das eigene Heim- oder Firmennetz: alle Geräte im Netz finden (mit Hersteller und "neu"-Markierung), PCs per Wake-on-LAN aufwecken, Internet-Geschwindigkeit über die Zeit verfolgen, den schnellsten DNS-Server finden, den besten WLAN-Kanal wählen und den Router prüfen. Bitte nur in Netzen verwenden, die dir gehören oder die du prüfen darfst.' (
    $ntTiles + $ntJump +
    (New-NtSection 'NtSecDev' '&#xE968;' '#2D7FF9' 'Geräte im Netz' 'Schickt einen Ping an alle Adressen des eigenen Netzes (bis 254 Stück, parallel - dauert ca. 10 Sekunden), liest die ARP-Tabelle (findet auch Geräte, die Ping blockieren), löst Namen auf und erkennt den Hersteller an der MAC-Adresse. Geräte, die beim letzten Scan noch nicht da waren, sind orange mit NEU markiert. Doppelklick öffnet die Weboberfläche des Geräts.' @(
        '<TextBlock x:Name="NtDevNet" Text="Noch nicht gesucht." Foreground="#1F2A44" FontWeight="SemiBold" TextWrapping="Wrap" Margin="0,0,0,8"/>',
        ('<WrapPanel>{0}<CheckBox x:Name="NtDevPorts" Content="Wichtige Anschlüsse prüfen (Web, SSH, Freigaben, Remotedesktop, Drucker, Kamera, MQTT, Home Assistant)" IsChecked="True" Margin="0,4,16,8" VerticalAlignment="Center"/><CheckBox x:Name="NtDevOnlyNew" Content="nur neue Geräte" Margin="0,4,0,8" VerticalAlignment="Center"/></WrapPanel>' -f (New-Filter 'NtDevFilter' 240)),
        (New-Bar @('BtnNtDevScan|Netz durchsuchen|P', 'BtnNtDevWeb|Weboberfläche öffnen', 'BtnNtDevName|Eigenen Namen vergeben ...', 'BtnNtDevWol|Zu Wake-on-LAN hinzufügen', 'BtnNtDevCopy|Liste kopieren')),
        (New-NtProgress 'NtDevProg' 'NtDevState'),
        (New-White (New-DataGrid 'NtDevGrid' @('Name|Name|*', 'IP-Adresse|Ip|125|IpSort', 'MAC-Adresse|Mac|140', 'Hersteller|Vendor|220', 'Antwort|RttText|95|Rtt', 'Offene Anschlüsse|Ports|150', 'Status|NewText|150') 'Height="340"')),
        (New-Hint 'Tipp: Zufällige MAC-Adressen (Handys, Tablets, Windows mit "Zufällige Hardwareadressen") zeigen keinen Hersteller - das ist eine Datenschutz-Funktion. Eigene Namen werden an der MAC-Adresse gespeichert und bei jedem Scan wieder angezeigt.'))) +
    (New-NtSection 'NtSecScan' '&#xE7BA;' '#B91C1C' 'Port-Scanner und Sicherheits-Scan' 'Scannt einen Rechner oder ein ganzes Netz detailliert nach offenen Anschlüssen (Ports) - von den wichtigsten bis zu allen 65535 - und prüft auf riskante oder veraltete Dienste. Nur in eigenen Netzen verwenden.' @(
        '<Grid Margin="0,0,0,8"><Grid.ColumnDefinitions><ColumnDefinition Width="Auto"/><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/><ColumnDefinition Width="220"/></Grid.ColumnDefinitions>' +
        '<TextBlock Text="Ziel:" VerticalAlignment="Center" Margin="0,0,8,0" Foreground="#475569"/>' +
        '<TextBox x:Name="ScanTarget" Grid.Column="1" VerticalContentAlignment="Center" ToolTip="Ein Rechner: 192.168.1.10 oder name.local  ·  Bereich: 192.168.1.10-50  ·  Subnetz: 192.168.1.0/24  ·  leer = lokales Subnetz. Mehrere mit Komma."/>' +
        '<TextBlock Text="Ports:" VerticalAlignment="Center" Margin="14,0,8,0" Foreground="#475569"/>' +
        '<ComboBox x:Name="ScanPorts" Grid.Column="3" VerticalContentAlignment="Center" IsEditable="True" ToolTip="Vorgabe wählen oder eigene Ports: 80,443,3389 oder 1-1024"><ComboBoxItem Content="Wichtige Ports" IsSelected="True"/><ComboBoxItem Content="Top 100"/><ComboBoxItem Content="Dienste (1-1024)"/><ComboBoxItem Content="ALLE (1-65535)"/></ComboBox></Grid>',
        (New-Bar @('BtnScanPort|Port-Scanner|P', 'BtnScanSec|Sicherheits-Scan (ganzes Netz)', 'BtnScanStop|Stopp', 'BtnScanCopy|Ausgabe kopieren')),
        (New-NtProgress 'ScanProg' 'ScanState'),
        '<TextBox x:Name="ScanOut" IsReadOnly="True" FontFamily="Consolas" FontSize="12" Height="300" VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Auto" TextWrapping="NoWrap" Background="#0F131A" Foreground="#D6DEEA" BorderBrush="#3A4150" Margin="0,6,0,0"/>',
        (New-Hint 'Der Sicherheits-Scan findet zuerst alle Geräte und prüft sie dann auf riskante offene Dienste: SMBv1/Dateifreigaben (445/139), Telnet (23), FTP (21), RDP (3389), VNC (5900), offene Datenbanken (MySQL 3306, MSSQL 1433, PostgreSQL 5432, MongoDB 27017, Redis 6379), LDAP (389), SNMP (161), ungesicherte Weboberflächen u.a. - mit Einstufung und Empfehlung. Ein Voll-Scan (alle Ports) über ein /24-Netz kann einige Minuten dauern.'))) +
    (New-NtSection 'NtSecWol' '&#xE7E8;' '#16A34A' 'Wake-on-LAN (PCs aus der Ferne einschalten)' 'Schickt ein "Magic Packet" als Broadcast (UDP-Port 9 und 7) ins Netz - ein ausgeschalteter PC mit aktiviertem Wake-on-LAN startet dann. Die Liste wird gespeichert; Geräte lassen sich direkt aus dem Scan übernehmen.' @(
        (New-White (New-DataGrid 'NtWolGrid' @('Name|Name|*', 'MAC-Adresse|Mac|150', 'Broadcast-Adresse|Broadcast|150', 'Letzte IP|Ip|130', 'Zuletzt geweckt|LastText|150') 'Height="170"')),
        (New-Bar @('BtnNtWolSend|Aufwecken|P', 'BtnNtWolAdd|Hinzufügen ...', 'BtnNtWolScan|Aus Scan übernehmen ...', 'BtnNtWolEdit|Bearbeiten ...', 'BtnNtWolDel|Entfernen')),
        '<TextBlock x:Name="NtWolInfo" Text="" Foreground="#1F2A44" TextWrapping="Wrap" Margin="0,2,0,6"/>',
        (New-Hint 'Damit es klappt: 1) im BIOS/UEFI "Wake on LAN" bzw. "Power On by PCI-E" einschalten, 2) im Geräte-Manager beim Netzwerkadapter unter Energieverwaltung "Gerät kann den Computer aus dem Ruhezustand aktivieren" und "Nur Magic Packet" anhaken, unter Erweitert "Wake on Magic Packet" aktivieren, 3) Windows-Schnellstart ausschalten (sonst wacht der PC aus dem "Herunterfahren" oft nicht auf). Über WLAN funktioniert Wake-on-LAN meist nicht, nur per Kabel. Aus dem Internet: im Router (z.B. FRITZ!Box: Heimnetz > Netzwerk > Gerät > "Computer starten") auslösen.'))) +
    (New-NtSection 'NtSecSpeed' '&#xEC4A;' '#0891B2' 'Speedtest-Verlauf' 'Jede Messung (hier und auf der Seite Netzwerk) wird mit Datum und Verbindungsart (LAN/WLAN) gespeichert. So sieht man, ob der Anschluss abends einbricht, ob das WLAN bremst und ob der Anbieter die gebuchte Geschwindigkeit liefert.' @(
        ('<WrapPanel>{0}{1}</WrapPanel>' -f (New-Combo 'NtSpKind' @('LAN und WLAN', 'nur LAN (Kabel)', 'nur WLAN') 170), (New-Combo 'NtSpRange' @('letzte 30 Tage', 'letzte 90 Tage', 'letztes Jahr', 'alles') 150)),
        '<TextBlock x:Name="NtSpInfo" Text="" Foreground="#1F2A44" FontWeight="SemiBold" TextWrapping="Wrap" Margin="0,0,0,4"/>',
        (New-NtLegend @('#2D7FF9|Download (Mbit/s)', '#7C3AED|Upload (Mbit/s)')),
        (New-NtChartBox 'NtSpCanvas' 250),
        (New-Bar @('BtnNtSpRun|Jetzt messen|P', 'BtnNtSpDel|Gewählte Messung löschen', 'BtnNtSpOpen|Als Tabelle öffnen (CSV)')),
        (New-NtProgress 'NtSpProg' 'NtSpState'),
        (New-White (New-DataGrid 'NtSpGrid' @('Datum|DateText|140|Raw', 'Verbindung|Kind|90', 'Download|DownText|120|Down', 'Upload|UpText|120|Up', 'Ping|PingText|80|Ping', 'Schwankung|JitterText|100|Jitter', 'Adapter|Adapter|*') 'Height="200"')),
        (New-Hint 'Gemessen wird über Cloudflare (50 MB Download, 10 MB Upload). Für aussagekräftige Werte per Kabel messen und andere Downloads/Streams pausieren. Liegt WLAN deutlich unter LAN, lohnt ein besserer WLAN-Kanal (unten), 5 GHz oder ein Mesh-Repeater.'))) +
    (New-NtSection 'NtSecDns' '&#xE774;' '#6D4AE8' 'DNS-Vergleich' 'Misst, wie schnell verschiedene DNS-Server (der aktuelle bzw. der Router, Cloudflare, Google, Quad9, AdGuard, OpenDNS) Namen wie google.de beantworten - zehn bekannte Adressen, je zweimal. Entscheidend ist der Median (typischer Wert), Ausfälle zählen stark negativ.' @(
        (New-Bar @('BtnNtDnsRun|Vergleich starten|P', 'BtnNtDnsApply|Gewählten bzw. schnellsten übernehmen ...')),
        (New-NtProgress 'NtDnsProg' 'NtDnsState'),
        '<TextBlock x:Name="NtDnsAdvice" Text="" Foreground="#1F2A44" FontWeight="SemiBold" TextWrapping="Wrap" Margin="0,0,0,6"/>',
        (New-NtLegend @('#16A34A|schnellster', '#2D7FF9|Router / aktuell eingestellt', '#8B5CF6|weitere Anbieter', '#1F2A44|Strich = Mittelwert')),
        (New-NtChartBox 'NtDnsCanvas' 60),
        (New-White (New-DataGrid 'NtDnsGrid' @('Rang|RankText|55|Rank', 'Anbieter|Name|*', 'Server|Server|130', 'Median|MedText|90|Median', 'Mittelwert|AvgText|100|Avg', 'Schnellste|MinText|95|Min', 'Langsamste|MaxText|100|Max', 'Ausfälle|FailText|80|Fail') 'Height="210"')),
        (New-Hint 'Wichtig: Der Router-DNS kennt die Namen deiner Geräte (z.B. fritz.box, NAS, Drucker). Wer am PC einen externen DNS einträgt, verliert diese Namen. Besser: den schnellen Anbieter im Router als Upstream-DNS eintragen (FRITZ!Box: Internet > Zugangsdaten > DNS-Server). "Übernehmen" stellt den DNS nur für den aktiven Adapter dieses PCs um; die Zeile "Router" stellt ihn wieder auf automatisch.'))) +
    (New-NtSection 'NtSecWlan' '&#xE701;' '#EA580C' 'WLAN-Kanal-Planer' 'Zeigt alle WLAN-Sender in Reichweite. Im 2,4-GHz-Band überlappen sich Nachbarkanäle (jedes Netz belegt etwa 4 Kanäle) - deshalb sind nur 1, 6 und 11 überschneidungsfrei. Im 5-GHz-Band gibt es viel mehr Platz. Dein eigenes Netz ist blau hervorgehoben.' @(
        '<WrapPanel><Button x:Name="BtnNtWlanScan" Content="WLAN-Umgebung scannen" Padding="12,6" Margin="0,0,8,8"/><Button x:Name="BtnNtWlanLoc" Content="Standortdienste öffnen" Style="{StaticResource Sec}" Padding="12,6" Margin="0,0,8,8" Visibility="Collapsed"/></WrapPanel>',
        (New-NtProgress 'NtWlanProg' 'NtWlanState'),
        '<Border x:Name="NtWlanAdviceBox" Background="#F5F9FF" BorderBrush="#AFC4EA" BorderThickness="1" CornerRadius="10" Padding="14,10" Margin="0,0,0,10" Visibility="Collapsed"><TextBlock x:Name="NtWlanAdvice" TextWrapping="Wrap" Foreground="#1F2A44"/></Border>',
        '<TextBlock Text="2,4 GHz - Kanäle 1 bis 13 (Höhe = Signalstärke, Breite = belegte Kanäle)" FontWeight="SemiBold" Foreground="#1F2A44" Margin="0,4,0,0"/>',
        (New-NtChartBox 'NtWlan24' 240),
        '<TextBlock Text="5 GHz - Anzahl Sender je Kanal (* = DFS-Kanal mit Radar-Erkennung)" FontWeight="SemiBold" Foreground="#1F2A44" Margin="0,4,0,0"/>',
        (New-NtChartBox 'NtWlan5' 200),
        (New-White (New-DataGrid 'NtWlanGrid' @('Netz (SSID)|Ssid|*', 'Sender (BSSID)|Bssid|140', 'Signal|SignalText|70|Signal', 'Kanal|Channel|65|Channel', 'Band|Band|80', 'Standard|RadioText|120', 'Sicherheit|Auth|150', 'Auslastung|UtilText|90|Util') 'Height="230"')),
        (New-Hint 'Windows aktualisiert die WLAN-Liste etwa jede Minute - direkt nach dem Einschalten des WLANs fehlen evtl. Netze. Ab Windows 11 24H2 braucht die Abfrage die Standortberechtigung (Einstellungen > Datenschutz > Position). Kanal in der FRITZ!Box ändern: WLAN > Funkkanal > "Funkkanal-Einstellungen anpassen".'))) +
    (New-NtSection 'NtSecRouter' '&#xE839;' '#DC2626' 'Router-Check' 'Prüft den Router, über den dieser PC ins Internet geht: Adresse und Hersteller, DHCP und Lease-Zeit, DNS, IPv6, ob die Oberfläche per http/https erreichbar ist, automatische UPnP-Portfreigaben und - bei einer FRITZ!Box - Modell und FRITZ!OS-Version (ohne Anmeldung).' @(
        (New-Bar @('BtnNtRtRun|Router prüfen|P', 'BtnNtRtWeb|Router-Oberfläche öffnen')),
        (New-NtProgress 'NtRtProg' 'NtRtState'),
        '<TextBlock x:Name="NtRtTitle" Text="" FontSize="15" FontWeight="SemiBold" Foreground="#1F2A44" TextWrapping="Wrap" Margin="0,0,0,8"/>',
        '<StackPanel x:Name="NtRtList"/>',
        '<TextBlock Text="UPnP-Portfreigaben (vom Router gemeldet)" FontWeight="SemiBold" Foreground="#1F2A44" Margin="0,8,0,4"/>',
        (New-White (New-DataGrid 'NtRtUpnpGrid' @('Extern|Ext|70', 'Protokoll|Proto|80', 'Ziel im Heimnetz|Int|180', 'Beschreibung|Desc|*', 'Aktiv|On|60') 'Height="150"')))))

# ---- Geräte-Akte
function New-AkField([string]$Label, [string]$Control) {
    '<Grid Margin="0,4"><Grid.ColumnDefinitions><ColumnDefinition Width="150"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions><TextBlock Text="{0}" Foreground="#475569" VerticalAlignment="Center"/><ContentControl Grid.Column="1">{1}</ContentControl></Grid>' -f (Esc $Label), $Control
}
function New-AkTwoCol([string]$Left, [string]$Right) {
    '<Grid><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="24"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions><StackPanel>{0}</StackPanel><StackPanel Grid.Column="2">{1}</StackPanel></Grid>' -f $Left, $Right
}
$akHero = @'
<Border CornerRadius="18" Margin="0,0,4,18" Padding="26,22" Background="{StaticResource HeroGrad}">
  <Border.Effect><DropShadowEffect BlurRadius="26" ShadowDepth="5" Direction="270" Opacity="0.28" Color="#2A2F8F"/></Border.Effect>
  <Grid>
    <Grid.ColumnDefinitions><ColumnDefinition Width="Auto"/><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
    <Border Width="96" Height="96" CornerRadius="24" Background="#33FFFFFF" BorderBrush="#55FFFFFF" BorderThickness="1" Margin="0,0,22,0" VerticalAlignment="Top">
      <TextBlock x:Name="AkGlyph" Text="&#xE977;" FontFamily="Segoe MDL2 Assets" FontSize="48" Foreground="#FFFFFF" HorizontalAlignment="Center" VerticalAlignment="Center"/>
    </Border>
    <StackPanel Grid.Column="1" VerticalAlignment="Center">
      <TextBlock x:Name="AkHeroVendor" Text="Geräte-Akte" Foreground="#FFFFFF" Opacity="0.85" FontSize="13"/>
      <TextBlock x:Name="AkHeroModel" Text="Wird eingelesen ..." Foreground="#FFFFFF" FontSize="27" FontWeight="Bold" TextWrapping="Wrap"/>
      <TextBlock x:Name="AkHeroSerial" Text="" Foreground="#FFFFFF" Opacity="0.92" Margin="0,4,0,0" TextWrapping="Wrap"/>
      <WrapPanel x:Name="AkBadges" Margin="0,12,0,0"/>
    </StackPanel>
    <StackPanel Grid.Column="2" VerticalAlignment="Top" Margin="16,0,0,0">
      <Button x:Name="BtnAkPdf" Content="Akte als PDF" Margin="0,0,0,8" Padding="16,8"/>
      <Button x:Name="BtnAkRefresh" Content="Neu einlesen" Style="{StaticResource Sec}" Margin="0,0,0,8" Padding="16,6"/>
      <Button x:Name="BtnAkExport" Content="Exportieren ..." Style="{StaticResource Sec}" Margin="0,0,0,8" Padding="16,6"/>
      <Button x:Name="BtnAkImport" Content="Importieren ..." Style="{StaticResource Sec}" Margin="0,0,0,0" Padding="16,6"/>
    </StackPanel>
  </Grid>
</Border>
'@
$akHwL = ((New-InfoRow 'Hersteller' 'AkHwMaker') + (New-InfoRow 'Modell' 'AkHwModel') + (New-InfoRow 'Typnummer / SKU' 'AkHwSku') + (New-InfoRow 'Seriennummer' 'AkHwSerial') + (New-InfoRow 'Bauform' 'AkHwForm') + (New-InfoRow 'BIOS / UEFI' 'AkHwBios') + (New-InfoRow 'Firmware und Sicherheit' 'AkHwFw') + (New-InfoRow 'Prozessor' 'AkHwCpu') + (New-InfoRow 'Arbeitsspeicher' 'AkHwRam'))
$akHwR = ((New-InfoRow 'Datenträger' 'AkHwDisk') + (New-InfoRow 'Grafik' 'AkHwGpu') + (New-InfoRow 'Windows' 'AkHwWin') + (New-InfoRow 'Installiert am' 'AkHwInst') + (New-InfoRow 'Aktivierung' 'AkHwAct') + (New-InfoRow 'Netzwerk (MAC)' 'AkHwMac') + (New-InfoRow 'Garantie' 'AkHwWar') + (New-InfoRow 'Akku' 'AkHwBat'))
$akHw = New-Card 'Hardware und Windows (automatisch erkannt)' @(
    '<ProgressBar x:Name="AkProg" Height="5" IsIndeterminate="True" Visibility="Collapsed" Margin="0,0,0,8" Foreground="{StaticResource AccentGrad}" Background="#E3E8F2" BorderThickness="0"/>',
    (New-AkTwoCol $akHwL $akHwR),
    (New-Bar @('BtnAkCopy|Alles kopieren', 'BtnAkLic|Lizenzen dieses PCs ...', 'BtnAkWarranty|Garantie prüfen ...', 'BtnAkHealth|Gerätezustand ...')))
$akBuyL = ((New-AkField 'Kaufdatum' '<DatePicker x:Name="AkBuyDate" SelectedDateFormat="Short"/>') + (New-AkField 'Preis (brutto)' '<TextBox x:Name="AkPrice" Padding="4,3" ToolTip="z.B. 1.299,00"/>') + (New-AkField 'Händler' '<TextBox x:Name="AkShop" Padding="4,3"/>') + (New-AkField 'Rechnungsnummer' '<TextBox x:Name="AkInvoice" Padding="4,3"/>'))
$akBuyR = ((New-AkField 'Inventarnummer' '<TextBox x:Name="AkInvNo" Padding="4,3"/>') + (New-AkField 'Standort' '<TextBox x:Name="AkLocation" Padding="4,3" ToolTip="z.B. Büro EG, Rezeption, Zuhause Arbeitszimmer"/>') + (New-AkField 'Besitzer / Nutzer' '<TextBox x:Name="AkOwner" Padding="4,3"/>') + '<TextBlock x:Name="AkAgeText" Text="" Foreground="#6B7890" FontSize="12" Margin="150,6,0,0" TextWrapping="Wrap"/>')
$akBuy = New-Card 'Kauf und Inventar' @(
    (New-Hint 'Diese Angaben kennt Windows nicht - einmal eintragen, dann stehen sie in der PDF-Akte und (Kaufdatum, Standort, Besitzer, Inventarnummer, letzte Reparatur) auch auf der Seite "Meine PCs".'),
    (New-AkTwoCol $akBuyL $akBuyR),
    (New-AkField 'Notizen' '<TextBox x:Name="AkNotes" Padding="4,3" Height="70" AcceptsReturn="True" TextWrapping="Wrap" VerticalScrollBarVisibility="Auto"/>'),
    '<WrapPanel Margin="0,8,0,0"><Button x:Name="BtnAkSave" Content="Speichern" Padding="16,7"/><TextBlock x:Name="AkSaveInfo" Text="" Foreground="#6B7890" VerticalAlignment="Center" Margin="4,0,0,8"/></WrapPanel>')
$akLog = New-Card 'Wartung und Reparaturen' @(
    '<TextBlock x:Name="AkLogSum" Text="" Foreground="#1F2A44" FontWeight="SemiBold" TextWrapping="Wrap" Margin="0,0,0,6"/>',
    (New-White (New-DataGrid 'AkLogGrid' @('Datum|DateText|100|SortDate', 'Art|Art|160', 'Beschreibung|Text|*', 'Kosten|CostText|110|CostNum') 'Height="200"')),
    (New-Bar @('BtnAkLogAdd|Eintrag hinzufügen ...|P', 'BtnAkLogEdit|Bearbeiten ...', 'BtnAkLogDel|Löschen')),
    (New-Hint 'Z.B. Akkutausch, Lüfter gereinigt, SSD aufgerüstet, Displayreparatur (Garantie), Windows neu installiert. Doppelklick bearbeitet einen Eintrag.'))
$akFiles = New-Card 'Dateien (Rechnungen, Fotos, Belege)' @(
    (New-White (New-DataGrid 'AkFileGrid' @('Datei|Name|*', 'Art|Art|140', 'Größe|SizeText|90|Size', 'Hinzugefügt|AddedText|110|Added') 'Height="170"')),
    (New-Bar @('BtnAkFileAdd|Dateien hinzufügen ...|P', 'BtnAkFileOpen|Öffnen', 'BtnAkFileDel|Entfernen', 'BtnAkFileDir|Ordner öffnen')),
    '<TextBlock x:Name="AkFileInfo" Text="" Foreground="#6B7890" FontSize="12" TextWrapping="Wrap"/>')
$akHist = New-Card 'Verlauf des Gerätezustands' @(
    ('<WrapPanel>{0}<TextBlock x:Name="AkHistInfo" Text="" Foreground="#6B7890" FontSize="12" VerticalAlignment="Center" Margin="4,0,0,8" TextWrapping="Wrap"/></WrapPanel>' -f (New-Combo 'AkHistSel' @('Akku-Kapazität (%)', 'SSD-Verschleiß (%)', 'SSD-Temperatur (°C)', 'Freier Speicher Systemlaufwerk (GB)', 'Startzeit (Sekunden)') 260)),
    (New-NtChartBox 'AkHistCanvas' 220))
$pageDevFile = New-Page 'Geräte-Akte' 'Alles über diesen PC an einem Ort: Hardware, Seriennummer, Windows und Aktivierung, Garantie, Akku und Zustandsverlauf - automatisch ausgelesen. Dazu Kaufdaten, Inventarnummer, Standort und Besitzer, ein Wartungs- und Reparaturbuch sowie Rechnungen und Fotos. Als PDF z.B. für die Versicherung, den Verkauf, die Werkstatt oder die Inventur.' ($akHero + $akHw + $akBuy + $akLog + $akFiles + $akHist)

# ---------------------------------------------------------------- Windows-Reparatur (Seite, Version 9.1) - braucht $WrCategories, $WrCatalog, $WrProfiles aus dem Hauptteil
function New-WrStat([string]$Key, [string]$Glyph, [string]$Label) {
    '<Border Width="266" MinHeight="116" Margin="0,0,12,12" Padding="14,12" CornerRadius="14" Background="White" BorderBrush="#E2E7F0" BorderThickness="1"><Grid><Grid.ColumnDefinitions><ColumnDefinition Width="Auto"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>' +
    ('<Border x:Name="WrSt{0}Dot" Width="40" Height="40" CornerRadius="11" Background="#94A3B8" VerticalAlignment="Top" Margin="0,2,12,0"><TextBlock Text="{1}" FontFamily="Segoe MDL2 Assets" FontSize="18" Foreground="#FFFFFF" HorizontalAlignment="Center" VerticalAlignment="Center"/></Border>' -f $Key, $Glyph) +
    ('<StackPanel Grid.Column="1"><TextBlock Text="{1}" Foreground="#6B7890" FontSize="12"/><TextBlock x:Name="WrSt{0}" Text="..." FontSize="19" FontWeight="SemiBold" Foreground="#1F2A44" TextTrimming="CharacterEllipsis"/><TextBlock x:Name="WrSt{0}Sub" Text="" Foreground="#6B7890" FontSize="11.5" TextWrapping="Wrap" Margin="0,2,0,0"/></StackPanel></Grid></Border>' -f $Key, (Esc $Label))
}
function ConvertTo-WrAttr([string]$s) { $x = Esc $s; if ($x.StartsWith('{')) { $x = '{}' + $x }; return $x }
function New-WrTile($E) {
    $risk = @{ Safe = @('sicher', '#DCFCE7', '#15803D'); Reboot = @('Neustart nötig', '#FFEDD5', '#C2410C'); Deep = @('tiefgreifend', '#FEE2E2', '#B91C1C') }[[string]$E.Risk]
    $col = [string](@($WrCategories | Where-Object { $_.Key -eq $E.Cat })[0].Color)
    $btn = switch ([string]$E.Key) { 'BootToRe' { 'Neu starten ...' } 'BootAdv' { 'Neu starten ...' } 'SafeMode' { 'Einstellen ...' } 'SafeOff' { 'Ausschalten' } 'InPlace' { 'Zur Karte' } 'PendingRevert' { 'Anleitung' } 'NetHyperV' { 'Zur Diagnose' } 'MediaPage' { 'Zur Seite' } 'ResetPc' { 'Öffnen ...' } default { if ($E.Mode -eq 'Job') { 'Ausführen' } else { 'Öffnen' } } }
    $left = if ($E.Mode -eq 'Job') { '<CheckBox x:Name="WrChk_{0}" Tag="{0}" VerticalAlignment="Center"><TextBlock Text="In Lauf aufnehmen" FontSize="12" Foreground="#475569"/></CheckBox>' -f $E.Key } else { '<TextBlock Text="Direkt-Knopf" FontSize="12" Foreground="#6B7890" VerticalAlignment="Center"/>' }
    $dur = if ($E.Mode -eq 'Job' -and [int]$E.Min -gt 0) { 'ca. {0} Min.' -f $E.Min } else { '' }
    $tip = ConvertTo-WrAttr ('Befehl: ' + [string]$E.Cmd)
    '<Border Width="372" Margin="0,0,12,12" Padding="14,12" CornerRadius="14" Background="White" BorderBrush="#E2E7F0" BorderThickness="1" ToolTip="{0}"><StackPanel>' -f $tip +
    '<Grid><Grid.ColumnDefinitions><ColumnDefinition Width="Auto"/><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>' +
    ('<Border Width="40" Height="40" CornerRadius="11" Background="{0}" Margin="0,0,12,0" VerticalAlignment="Top"><TextBlock Text="{1}" FontFamily="Segoe MDL2 Assets" FontSize="18" Foreground="#FFFFFF" HorizontalAlignment="Center" VerticalAlignment="Center"/></Border>' -f $col, $E.Glyph) +
    ('<TextBlock Grid.Column="1" Text="{0}" FontSize="14" FontWeight="SemiBold" Foreground="#1F2A44" TextWrapping="Wrap" VerticalAlignment="Center"/>' -f (ConvertTo-WrAttr $E.Title)) +
    ('<Border Grid.Column="2" CornerRadius="9" Padding="8,2" Background="{0}" VerticalAlignment="Top" Margin="8,2,0,0"><TextBlock Text="{1}" FontSize="11" FontWeight="SemiBold" Foreground="{2}"/></Border></Grid>' -f $risk[1], (Esc $risk[0]), $risk[2]) +
    ('<TextBlock Text="{0}" FontSize="12" Foreground="#6B7890" TextWrapping="Wrap" Margin="0,8,0,4" MinHeight="48"/>' -f (ConvertTo-WrAttr $E.Desc)) +
    ('<Expander Header="Profi-Details: genauer Befehl" Margin="0,0,0,8" FontSize="11.5" Foreground="#475569"><TextBox Text="{0}" IsReadOnly="True" TextWrapping="Wrap" FontFamily="Consolas" FontSize="11.5" Margin="0,4,0,0" BorderThickness="0" Background="#F4F6FA" Padding="6"/></Expander>' -f (ConvertTo-WrAttr $E.Cmd)) +
    '<Grid><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>' + $left +
    ('<TextBlock Grid.Column="1" Text="{0}" FontSize="11.5" Foreground="#6B7890" VerticalAlignment="Center" Margin="0,0,10,0"/>' -f (Esc $dur)) +
    ('<Button x:Name="BtnWrGo_{0}" Grid.Column="2" Tag="{0}" Content="{1}" Style="{{StaticResource Sec}}" Padding="14,5" Margin="0"/></Grid>' -f $E.Key, (Esc $btn)) +
    '</StackPanel></Border>'
}
function New-WrCatCard($C) {
    $tiles = (@($WrCatalog | Where-Object { $_.Cat -eq $C.Key }) | ForEach-Object { New-WrTile $_ }) -join ''
    $extra = ''
    if ($C.Key -eq 'Net') { $extra = '<Border Background="#FFEDD5" CornerRadius="10" Padding="12,8" Margin="0,0,0,12"><TextBlock TextWrapping="Wrap" Foreground="#1F2A44" FontSize="12.5" Text="Keine IPv4-Adresse, obwohl die DHCP-Anfrage rausgeht und keine Antwort ankommt (IPv6 geht)? Häufigste Ursachen in dieser Reihenfolge: Netzwerkfilter eines Virenschutzes (z.B. Panda NNSNAHSL), ein deaktivierter oder verbogener Netzwerkdienst (ab Windows 11 24H2 auch WinHTTP-Autoproxy), Hyper-V-Reste und kaputte TCP/IP-Einträge. Das Profil &quot;Netzwerk komplett zurücksetzen (Surface/DHCP-Problem)&quot; oben geht alles davon in der richtigen Reihenfolge durch - die Tiefenprüfung unten zeigt vorher, was auffällt."/></Border>' }
    if ($C.Key -eq 'Last') { $extra = '<Border Background="#FEE2E2" CornerRadius="10" Padding="12,8" Margin="0,0,0,12"><TextBlock TextWrapping="Wrap" Foreground="#7F1D1D" FontSize="12.5" Text="Reihenfolge, wenn nichts anderes hilft: 1. Systemwiederherstellung auf einen Punkt vor dem Problem, 2. Reparaturinstallation (behält Programme und Dateien), 3. Diesen PC zurücksetzen (Programme müssen neu installiert werden). Vorher Daten sichern (Seite Datensicherung)."/></Border>' }
    '<Border Background="White" CornerRadius="16" Padding="20,16" Margin="0,0,4,16" BorderBrush="#E2E7F0" BorderThickness="1"><Border.Effect><DropShadowEffect BlurRadius="18" ShadowDepth="2" Direction="270" Opacity="0.07" Color="Black"/></Border.Effect><StackPanel>' +
    '<Grid Margin="0,0,0,12"><Grid.ColumnDefinitions><ColumnDefinition Width="Auto"/><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>' +
    ('<Border Width="48" Height="48" CornerRadius="14" Background="{0}" Margin="0,0,14,0" VerticalAlignment="Top"><Border.Effect><DropShadowEffect BlurRadius="14" ShadowDepth="3" Direction="270" Opacity="0.25" Color="{0}"/></Border.Effect><TextBlock Text="{1}" FontFamily="Segoe MDL2 Assets" FontSize="22" Foreground="#FFFFFF" HorizontalAlignment="Center" VerticalAlignment="Center"/></Border>' -f $C.Color, $C.Glyph) +
    ('<StackPanel Grid.Column="1" VerticalAlignment="Center"><TextBlock Text="{0}" FontSize="17" FontWeight="SemiBold" Foreground="#1F2A44"/><TextBlock Text="{1}" FontSize="12.5" Foreground="#6B7890" TextWrapping="Wrap" Margin="0,3,12,0"/></StackPanel>' -f (Esc $C.Title), (ConvertTo-WrAttr $C.Desc)) +
    ('<StackPanel Grid.Column="2" Orientation="Horizontal" VerticalAlignment="Top"><Button x:Name="BtnWrCatAll_{0}" Tag="{0}" Content="Sichere anhaken" Style="{{StaticResource Sec}}" Padding="10,4" Margin="0,0,6,0"/><Button x:Name="BtnWrCatNone_{0}" Tag="{0}" Content="Keine" Style="{{StaticResource Sec}}" Padding="10,4" Margin="0"/></StackPanel></Grid>' -f $C.Key) +
    $extra + '<WrapPanel>' + $tiles + '</WrapPanel></StackPanel></Border>'
}
function New-WrProfileBtn($P) {
    '<Button x:Name="BtnWrProf_{0}" Tag="{0}" Background="#26FFFFFF" Foreground="#FFFFFF" Padding="12,8" Margin="0,0,10,10" HorizontalContentAlignment="Left" MaxWidth="330" ToolTip="{3}"><StackPanel Orientation="Horizontal"><TextBlock Text="{1}" FontFamily="Segoe MDL2 Assets" FontSize="16" Foreground="#FFFFFF" VerticalAlignment="Center" Margin="0,0,10,0"/><TextBlock Text="{2}" Foreground="#FFFFFF" FontWeight="SemiBold" TextWrapping="Wrap" VerticalAlignment="Center"/></StackPanel></Button>' -f $P.Key, $P.Glyph, (Esc $P.Title), (ConvertTo-WrAttr $P.Desc)
}
function New-WrSection([string]$Name, [string]$Glyph, [string]$Color, [string]$Title, [string]$Intro, [string[]]$Rows) {
    $nm = if ($Name) { ' x:Name="{0}"' -f $Name } else { '' }
    ('<Border{0} Background="White" CornerRadius="16" Padding="20,16" Margin="0,0,4,16" BorderBrush="#E2E7F0" BorderThickness="1"><Border.Effect><DropShadowEffect BlurRadius="18" ShadowDepth="2" Direction="270" Opacity="0.07" Color="Black"/></Border.Effect><StackPanel>' -f $nm) +
    '<Grid Margin="0,0,0,10"><Grid.ColumnDefinitions><ColumnDefinition Width="Auto"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>' +
    ('<Border Width="44" Height="44" CornerRadius="13" Background="{0}" Margin="0,0,14,0" VerticalAlignment="Top"><TextBlock Text="{1}" FontFamily="Segoe MDL2 Assets" FontSize="20" Foreground="#FFFFFF" HorizontalAlignment="Center" VerticalAlignment="Center"/></Border>' -f $Color, $Glyph) +
    ('<StackPanel Grid.Column="1" VerticalAlignment="Center"><TextBlock Text="{0}" FontSize="17" FontWeight="SemiBold" Foreground="#1F2A44"/><TextBlock Text="{1}" FontSize="12.5" Foreground="#6B7890" TextWrapping="Wrap" Margin="0,3,0,0"/></StackPanel></Grid>' -f (Esc $Title), (ConvertTo-WrAttr $Intro)) +
    ($Rows -join '') + '</StackPanel></Border>'
}
function New-WrSub([string]$Text) { '<TextBlock Text="{0}" FontSize="13.5" FontWeight="SemiBold" Foreground="#1F2A44" Margin="0,12,0,6"/>' -f (Esc $Text) }

$wrStatusXaml = New-WrSection '' '&#xE9D9;' '#0F766E' 'Zustand von Windows' 'Wird beim Öffnen der Seite geprüft (DISM-Schnellprüfung, CBS.log, Wiederherstellungsumgebung, Startkonfiguration) - ändert nichts. Grün = in Ordnung, orange = Hinweis, rot = Problem.' @(
    ('<WrapPanel>' + (New-WrStat 'Win' '&#xE7F8;' 'Windows') + (New-WrStat 'Reboot' '&#xE7E8;' 'Neustart ausstehend') + (New-WrStat 'Store' '&#xE8F1;' 'Komponentenspeicher (DISM)') + (New-WrStat 'Sfc' '&#xE8B7;' 'Systemdateien (letzter SFC-Lauf)') +
     (New-WrStat 'Re' '&#xE777;' 'Wiederherstellungsumgebung') + (New-WrStat 'Disk' '&#xEDA2;' 'Frei auf Laufwerk C:') + (New-WrStat 'Rp' '&#xE81C;' 'Letzter Wiederherstellungspunkt') + (New-WrStat 'Boot' '&#xE7EF;' 'Startmodus') + '</WrapPanel>'),
    '<WrapPanel><Button x:Name="BtnWrStatus" Content="Neu prüfen" Style="{StaticResource Sec}" Padding="12,5"/><TextBlock x:Name="WrStInfo" Text="" Foreground="#6B7890" FontSize="12" VerticalAlignment="Center" Margin="4,0,0,8"/></WrapPanel>'
)
$wrHeroXaml = @'
<Border CornerRadius="18" Margin="0,0,4,16" Padding="26,22" Background="{StaticResource HeroGrad}">
  <Border.Effect><DropShadowEffect BlurRadius="26" ShadowDepth="5" Direction="270" Opacity="0.28" Color="#2A2F8F"/></Border.Effect>
  <StackPanel>
    <Grid>
      <Grid.ColumnDefinitions><ColumnDefinition Width="Auto"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>
      <Border Width="56" Height="56" CornerRadius="16" Background="#33FFFFFF" Margin="0,0,16,0" VerticalAlignment="Top">
        <TextBlock Text="&#xE90F;" FontFamily="Segoe MDL2 Assets" FontSize="26" Foreground="#FFFFFF" HorizontalAlignment="Center" VerticalAlignment="Center"/>
      </Border>
      <StackPanel Grid.Column="1">
        <TextBlock Text="Reparatur-Assistent" Foreground="#FFFFFF" FontSize="22" FontWeight="Bold"/>
        <TextBlock Text="Profil wählen - PC-Tools hakt die passenden Reparaturen in der richtigen Reihenfolge an. Prüfen, bei Bedarf ergänzen, dann starten. Alles läuft im Hintergrund weiter, auch wenn das Fenster geschlossen wird, und steht im Protokoll." Foreground="#FFFFFF" Opacity="0.92" TextWrapping="Wrap" Margin="0,4,0,0"/>
      </StackPanel>
    </Grid>
    <WrapPanel Margin="0,16,0,0">__PROFILES__</WrapPanel>
    <TextBlock x:Name="WrProfInfo" Text="Noch kein Profil gewählt." Foreground="#FFFFFF" Opacity="0.95" TextWrapping="Wrap" Margin="0,2,0,0"/>
    <Border Background="#26FFFFFF" CornerRadius="12" Padding="14,10" Margin="0,12,0,0">
      <StackPanel>
        <WrapPanel>
          <CheckBox x:Name="WrChkRp" IsChecked="True" Margin="0,0,24,6"><TextBlock Text="Vorher Wiederherstellungspunkt erstellen" Foreground="#FFFFFF"/></CheckBox>
          <CheckBox x:Name="WrChkSvcAll" IsChecked="False" Margin="0,0,24,6"><TextBlock Text="Dienste: auch Hinweise (nicht nur Probleme) angleichen" Foreground="#FFFFFF"/></CheckBox>
        </WrapPanel>
        <Grid Margin="0,4,0,0">
          <Grid.ColumnDefinitions><ColumnDefinition Width="Auto"/><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
          <TextBlock Text="Reparaturquelle:" Foreground="#FFFFFF" FontWeight="SemiBold" VerticalAlignment="Center" Margin="0,0,10,8"/>
          <TextBox x:Name="WrSource" Grid.Column="1" IsReadOnly="True" Text="" Padding="6,4" Margin="0,0,10,8" ToolTip="Windows-ISO, install.wim oder install.esd - für DISM, .NET 3.5 und eine fehlende Winre.wim. Leer = Windows Update."/>
          <Button x:Name="BtnWrSource" Grid.Column="2" Content="ISO/WIM wählen ..." Background="#FFFFFF" Foreground="#1E3A8A" Padding="12,5"/>
          <Button x:Name="BtnWrSourceClear" Grid.Column="3" Content="Entfernen" Background="#33FFFFFF" Foreground="#FFFFFF" Padding="12,5" Margin="0,0,0,8"/>
        </Grid>
        <WrapPanel>
          <ComboBox x:Name="WrIndex" Width="440" Margin="0,0,10,4" VerticalContentAlignment="Center"/>
          <TextBlock x:Name="WrSourceInfo" Text="Ohne Quelle holt DISM Ersatzteile aus Windows Update (braucht Internet). Mit einer ISO geht es auch offline - Version, Edition und Sprache müssen passen." Foreground="#FFFFFF" Opacity="0.9" FontSize="12" TextWrapping="Wrap" MaxWidth="560" VerticalAlignment="Center"/>
        </WrapPanel>
      </StackPanel>
    </Border>
    <Grid Margin="0,14,0,0">
      <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
      <TextBlock x:Name="WrSelInfo" Text="" Foreground="#FFFFFF" FontWeight="SemiBold" TextWrapping="Wrap" VerticalAlignment="Center" Margin="0,0,12,8"/>
      <StackPanel Grid.Column="1" Orientation="Horizontal">
        <Button x:Name="BtnWrFullRepair" Content="Komplett-Reparatur (ohne Rückfragen)" Background="#059669" Foreground="#FFFFFF" Padding="16,9" Margin="0,0,10,8" FontWeight="SemiBold" ToolTip="Tiefgreifende Reparatur ohne Nachfragen: Dienste, DISM/SFC, Windows Update, Netzwerk, WMI, Update-Blocker und alte angreifbare Treiber - mit Super-Log und Neustart. Für PCs, auf denen Dienste/Setup klemmen."/>
        <Button x:Name="BtnWrSelNone" Content="Auswahl leeren" Background="#33FFFFFF" Foreground="#FFFFFF" Padding="14,8"/>
        <Button x:Name="BtnWrRunSel" Content="Auswahl jetzt reparieren" Background="#FFFFFF" Foreground="#1E3A8A" Padding="20,9" Margin="0,0,0,8" IsEnabled="False"/>
      </StackPanel>
    </Grid>
  </StackPanel>
</Border>
'@
$wrHeroXaml = $wrHeroXaml.Replace('__PROFILES__', (($WrProfiles | ForEach-Object { New-WrProfileBtn $_ }) -join ''))
$wrRunXaml = New-WrSection 'WrRunCard' '&#xE768;' '#2D7FF9' 'Reparatur-Lauf' 'Fortschritt und Protokoll des laufenden bzw. letzten Laufs. Abbrechen stoppt nach dem aktuellen Schritt; einzelne Programme wie DISM werden sauber beendet.' @(
    '<Grid><Grid.ColumnDefinitions><ColumnDefinition Width="Auto"/><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>',
    '<Border x:Name="WrRunBadge" Width="42" Height="42" CornerRadius="21" Background="#94A3B8" Margin="0,0,14,0" VerticalAlignment="Center"><TextBlock x:Name="WrRunGlyph" Text="&#xE768;" FontFamily="Segoe MDL2 Assets" FontSize="18" Foreground="#FFFFFF" HorizontalAlignment="Center" VerticalAlignment="Center"/></Border>',
    '<StackPanel Grid.Column="1" VerticalAlignment="Center"><TextBlock x:Name="WrRunTitle" Text="Kein Lauf aktiv" FontSize="16" FontWeight="SemiBold" Foreground="#1F2A44"/><TextBlock x:Name="WrRunStep" Text="Profil wählen oder in den Kacheln &quot;In Lauf aufnehmen&quot; anhaken." Foreground="#6B7890" TextWrapping="Wrap"/></StackPanel>',
    '<StackPanel Grid.Column="2" Orientation="Horizontal" VerticalAlignment="Center"><Button x:Name="BtnWrCancel" Content="Abbrechen" Style="{StaticResource Sec}" Padding="12,5" IsEnabled="False"/><Button x:Name="BtnWrOpenData" Content="Ordner WinRepair" Style="{StaticResource Sec}" Padding="12,5"/><Button x:Name="BtnWrToLog" Content="Gesamtprotokoll" Style="{StaticResource Sec}" Padding="12,5" Margin="0,0,0,8"/></StackPanel></Grid>',
    '<ProgressBar x:Name="WrRunBar" Height="10" Minimum="0" Maximum="100" Value="0" Margin="0,12,0,6"/>',
    '<TextBlock x:Name="WrRunDetail" Text="" Foreground="#475569" FontSize="12" TextWrapping="Wrap" Margin="0,0,0,8"/>',
    '<TextBox x:Name="WrRunLog" Height="240" IsReadOnly="True" FontFamily="Consolas" FontSize="11.5" TextWrapping="NoWrap" VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Auto" Background="#F8FAFD" BorderBrush="#E2E7F0" Padding="8"/>'
)
$wrNetXaml = New-WrSection '' '&#xE968;' '#DC2626' 'Netzwerk-Tiefenprüfung (nur lesen)' 'Zeigt, was an den echten Adaptern hängt (Filter und Protokolle mit Hersteller und Treiberpaket), wie IPv4 in der Registrierung eingestellt ist, ob IPv6-Komponenten verbogen sind und welche Netzwerk- und Kerndienste von der Windows-11-Vorgabe abweichen. Erst prüfen, dann gezielt reparieren.' @(
    '<WrapPanel><Button x:Name="BtnWrNetScan" Content="Netzwerk tief prüfen"/><Button x:Name="BtnWrSvcScan" Content="Nur Dienste vergleichen" Style="{StaticResource Sec}"/><Button x:Name="BtnWrToNetDiag" Content="Zur Netzwerk-Diagnose (DHCP-Live-Test, Hyper-V)" Style="{StaticResource Sec}"/></WrapPanel>',
    '<TextBlock x:Name="WrNetInfo" Text="Noch nicht geprüft." Foreground="#1F2A44" FontWeight="SemiBold" TextWrapping="Wrap" Margin="0,2,0,4"/>',
    (New-WrSub 'Filter und Protokolle an den Adaptern'),
    (New-White (New-DataGrid 'WrFilterGrid' @('Adapter|Adapter|120', 'Aktiv|Aktiv|50', 'Komponente|Komponente|220', 'ID|Id|130', 'Hersteller|Hersteller|140', 'Paket|Paket|80', 'Einschätzung|Einschaetzung|*') 'Height="220"')),
    '<WrapPanel Margin="0,8,0,0"><Button x:Name="BtnWrFilterOff" Content="Ausgewählten lösen" Style="{StaticResource Sec}" Padding="12,5"/><Button x:Name="BtnWrFilterOn" Content="Wieder einschalten" Style="{StaticResource Sec}" Padding="12,5"/><Button x:Name="BtnWrFilterAllOff" Content="Alle fremden lösen ..." Style="{StaticResource Sec}" Padding="12,5"/><Button x:Name="BtnWrFilterRemove" Content="Treiberpaket entfernen ..." Style="{StaticResource Sec}" Padding="12,5"/></WrapPanel>',
    (New-Hint 'Virenschutz-Filter (z.B. Panda NNSNAHSL) lassen sich lösen, kommen aber beim nächsten Update des Virenschutzes oft zurück. Dauerhaft hilft nur die Deinstallation mit dem Programm des Herstellers - danach übernimmt Microsoft Defender automatisch. "Treiberpaket entfernen" ist der letzte Ausweg, wenn der Hersteller-Deinstaller den Filter zurücklässt.'),
    '<WrapPanel><ComboBox x:Name="WrAvCombo" Width="420" Margin="0,0,10,8" VerticalContentAlignment="Center"/><Button x:Name="BtnWrAvUninst" Content="Deinstallieren ..." Style="{StaticResource Sec}" Padding="12,5"/><Button x:Name="BtnWrAppsFeatures" Content="Installierte Apps öffnen" Style="{StaticResource Sec}" Padding="12,5"/></WrapPanel>',
    (New-WrSub 'IPv4 der Adapter (Registrierung und Ist-Zustand)'),
    (New-White (New-DataGrid 'WrIpGrid' @('Adapter|Adapter|120', 'Status|Status|90', 'DHCP|Dhcp|50', 'IPv4|Ip|120', 'Gespeichert|Gespeichert|120', 'DHCP-Server|DhcpServer|110', 'Hinweis|Hinweis|*') 'Height="140"')),
    '<TextBlock x:Name="WrIpv6Info" Text="" Foreground="#475569" FontSize="12" TextWrapping="Wrap" Margin="0,6,0,0"/>',
    '<WrapPanel Margin="0,6,0,0"><Button x:Name="BtnWrDc0" Content="IPv6 auf Standard (0)" Style="{StaticResource Sec}" Padding="12,5" ToolTip="DisabledComponents = 0: IPv6 voll aktiv, Windows wählt selbst - Microsoft-Empfehlung."/><Button x:Name="BtnWrDc20" Content="IPv4 bevorzugen (0x20)" Style="{StaticResource Sec}" Padding="12,5" ToolTip="DisabledComponents = 0x20: IPv6 bleibt an, aber IPv4-Adressen werden bevorzugt - die einzige von Microsoft empfohlene Abweichung."/><Button x:Name="BtnWrBcastOn" Content="DHCP-Broadcast-Wechsel einschalten" Style="{StaticResource Sec}" Padding="12,5"/></WrapPanel>',
    (New-WrSub 'Dienste und Treiber im Vergleich mit Windows 11'),
    (New-White (New-DataGrid 'WrSvcGrid' @('Gruppe|Gruppe|75', 'Dienst|Dienst|140', 'Name|Name|190', 'Feld|Feld|105', 'Ist|Ist|160', 'Vorgabe|Soll|160', 'Stufe|Stufe|70', 'Hinweis|Hinweis|*') 'Height="220"')),
    '<TextBlock x:Name="WrSvcInfo" Text="" Foreground="#475569" FontSize="12" TextWrapping="Wrap" Margin="0,6,0,4"/>',
    '<WrapPanel><Button x:Name="BtnWrSvcFix" Content="Probleme beheben ..." Style="{StaticResource Sec}" Padding="12,5" IsEnabled="False"/><Button x:Name="BtnWrSvcFixAll" Content="Alle Abweichungen angleichen ..." Style="{StaticResource Sec}" Padding="12,5" IsEnabled="False"/></WrapPanel>'
)
$wrCbsXaml = New-WrSection '' '&#xE8B7;' '#2563EB' 'Ergebnis der Systemdatei-Prüfung (CBS.log)' 'SFC schreibt jedes Ergebnis in die Protokolldatei C:\Windows\Logs\CBS\CBS.log. PC-Tools sucht darin den letzten Lauf und listet, welche Dateien repariert wurden und welche nicht - die nicht reparierbaren braucht man, um gezielt weiterzumachen (DISM mit ISO, Reparaturinstallation).' @(
    '<WrapPanel><Button x:Name="BtnWrCbs" Content="CBS.log auswerten" Style="{StaticResource Sec}" Padding="12,5"/><Button x:Name="BtnWrCbsOpen" Content="CBS.log öffnen" Style="{StaticResource Sec}" Padding="12,5"/></WrapPanel>',
    '<TextBlock x:Name="WrCbsInfo" Text="" Foreground="#1F2A44" FontWeight="SemiBold" TextWrapping="Wrap" Margin="0,2,0,6"/>',
    (New-White (New-DataGrid 'WrCbsGrid' @('Ergebnis|Art|160', 'Datei|Datei|*') 'Height="170"'))
)
$wrEvtXaml = New-WrSection '' '&#xE7BA;' '#EA580C' 'Fehler der letzten 7 Tage' 'Kritische Ereignisse und Fehler aus dem Systemprotokoll, zusammengefasst nach Quelle - mit Einschätzung, was dahintersteckt. Einzelne DistributedCOM-Meldungen sind normal; Häufungen bei Datenträger, Dienststeuerung, DHCP oder WHEA sind es nicht.' @(
    '<WrapPanel><Button x:Name="BtnWrEvents" Content="Fehler zusammenfassen" Style="{StaticResource Sec}" Padding="12,5"/><Button x:Name="BtnWrEventvwr" Content="Ereignisanzeige öffnen" Style="{StaticResource Sec}" Padding="12,5"/></WrapPanel>',
    '<TextBlock x:Name="WrEvtInfo" Text="" Foreground="#1F2A44" FontWeight="SemiBold" TextWrapping="Wrap" Margin="0,2,0,6"/>',
    (New-White (New-DataGrid 'WrEvtGrid' @('Quelle|Quelle|210', 'Anzahl|Anzahl|60', 'Kritisch|Kritisch|60', 'Zuletzt|Letztes|90', 'IDs|Ids|100', 'Einschätzung|Hinweis|260', 'Beispiel|Beispiel|*') 'Height="220"'))
)
$wrIpuXaml = New-WrSection 'WrIpuCard' '&#xE777;' '#B91C1C' 'Reparaturinstallation (In-place Upgrade)' 'Windows-Setup installiert Windows aus einer ISO über das vorhandene Windows. Programme, eigene Dateien und die meisten Einstellungen bleiben erhalten - ersetzt werden alle Systemdateien, der Komponentenspeicher, die Netzwerk-Grundkonfiguration und die Windows-Apps. Das ist die gründlichste Reparatur vor dem Zurücksetzen.' @(
    '<Border Background="#FEE2E2" CornerRadius="10" Padding="12,8" Margin="0,0,0,10"><TextBlock TextWrapping="Wrap" Foreground="#7F1D1D" FontSize="12.5" Text="Voraussetzungen: ISO mit derselben Sprache und Architektur, gleicher oder neuerer Build (Insider-Builds brauchen eine Insider-ISO), mindestens 20 GB frei auf C:, Netzteil angeschlossen. Virenschutz von Drittanbietern (z.B. Panda) vorher deinstallieren - er ist die häufigste Ursache für abgebrochene Setups. BitLocker hält Setup selbst an. Dauer: 30-90 Minuten Vorbereitung im Hintergrund, danach 20-60 Minuten mit mehreren Neustarts - nicht ausschalten."/></Border>',
    '<Grid><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions><TextBox x:Name="WrIpuIso" IsReadOnly="True" Padding="6,4" Margin="0,0,10,8"/><Button x:Name="BtnWrIpuPick" Grid.Column="1" Content="ISO wählen ..." Style="{StaticResource Sec}" Padding="12,5"/><Button x:Name="BtnWrIpuMedia" Grid.Column="2" Content="ISO herunterladen (Windows und Office)" Style="{StaticResource Sec}" Padding="12,5" Margin="0,0,0,8"/></Grid>',
    '<WrapPanel><Button x:Name="BtnWrIpuCheck" Content="Passt die ISO? Prüfen" Style="{StaticResource Sec}" Padding="12,5"/></WrapPanel>',
    (New-White (New-DataGrid 'WrIpuGrid' @('Index|Index|50', 'Abbild|Name|210', 'Edition|EditionId|130', 'Build|Build|120', 'Sprache|Sprachen|80', 'Arch.|Arch|55', 'Ergebnis|Text|*') 'Height="170"')),
    '<TextBlock x:Name="WrIpuVerdict" Text="Noch keine ISO geprüft." Foreground="#1F2A44" FontWeight="SemiBold" TextWrapping="Wrap" Margin="0,8,0,8"/>',
    '<WrapPanel><CheckBox x:Name="WrIpuDyn" IsChecked="True" Margin="0,0,24,8"><TextBlock Text="Updates während der Installation laden (empfohlen, braucht Internet)" Foreground="#1F2A44"/></CheckBox><CheckBox x:Name="WrIpuRp" IsChecked="True" Margin="0,0,24,8"><TextBlock Text="Vorher Wiederherstellungspunkt" Foreground="#1F2A44"/></CheckBox><CheckBox x:Name="WrIpuReboot" IsChecked="False" Margin="0,0,24,8"><TextBlock Text="Automatisch neu starten, sobald Setup bereit ist" Foreground="#1F2A44"/></CheckBox></WrapPanel>',
    '<WrapPanel><Button x:Name="BtnWrIpuStart" Content="Reparaturinstallation starten ..." Padding="18,8" IsEnabled="False"/></WrapPanel>'
)
$wrHistXaml = New-WrSection '' '&#xE81C;' '#7C3AED' 'Ergebnisse und Verlauf' 'Das letzte Ergebnis Schritt für Schritt und alle bisherigen Läufe (auch aus dem Textmodus). Doppelklick auf einen Lauf öffnet sein Protokoll. Gespeichert im Datenordner unter WinRepair (last.json, history.csv, Sicherungen und Berichte).' @(
    '<TextBlock x:Name="WrLastInfo" Text="Noch kein Lauf." Foreground="#1F2A44" FontWeight="SemiBold" TextWrapping="Wrap" Margin="0,0,0,6"/>',
    (New-White (New-DataGrid 'WrLastGrid' @('Schritt|Schritt|250', 'Ergebnis|Ergebnis|80', 'Dauer|Dauer|60', 'Meldung|Meldung|*') 'Height="200"')),
    (New-WrSub 'Alle Läufe'),
    (New-White (New-DataGrid 'WrHistGrid' @('Zeit|Zeit|115', 'Art|Art|120', 'Profil / Titel|Titel|230', 'Schritte|Anzahl|60', 'Ergebnis|Ergebnis|100', 'Neustart|Neustart|65', 'Dauer|Dauer|65', 'Protokoll|Log|*') 'Height="180"')),
    '<WrapPanel Margin="0,8,0,0"><Button x:Name="BtnWrHistRefresh" Content="Aktualisieren" Style="{StaticResource Sec}" Padding="12,5"/><Button x:Name="BtnWrConsole" Content="Textmodus starten (-WinRepair)" Style="{StaticResource Sec}" Padding="12,5"/></WrapPanel>'
)
$pageWinRepair = New-Page 'Windows-Reparatur' 'Alle Reparaturen, die Windows selbst anbietet, an einem Ort: Systemdateien und Abbild, Windows Update, das Netzwerk bis tief in die Registrierung, Start und Wiederherstellung, Apps, Systemkomponenten und als letzter Ausweg die Reparaturinstallation. Jede Kachel erklärt, was passiert, zeigt den genauen Befehl und sagt, ob sie sicher ist, einen Neustart braucht oder tief eingreift. Läufe arbeiten im Hintergrund weiter, auch wenn das Fenster geschlossen wird.' (
    $wrStatusXaml + $wrHeroXaml + $wrRunXaml + (($WrCategories | ForEach-Object { New-WrCatCard $_ }) -join '') + $wrNetXaml + $wrCbsXaml + $wrEvtXaml + $wrIpuXaml + $wrHistXaml)







# ---------------------------------------------------------------- Komplettsicherung (Seite)
# kleine Bausteine nur für diese Seite
function New-FbKpi([string]$Name, [string]$Label, [string]$Glyph, [string]$Color) {
    '<Border Background="#F6F8FC" BorderBrush="#E2E7F0" BorderThickness="1" CornerRadius="12" Padding="12,10" Margin="0,0,10,10"><Grid><Grid.ColumnDefinitions><ColumnDefinition Width="Auto"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>' +
    ('<Border Width="34" Height="34" CornerRadius="10" Background="{0}" Margin="0,0,10,0" VerticalAlignment="Top"><TextBlock Text="{1}" FontFamily="Segoe MDL2 Assets" FontSize="16" Foreground="#FFFFFF" HorizontalAlignment="Center" VerticalAlignment="Center"/></Border>' -f $Color, $Glyph) +
    ('<StackPanel Grid.Column="1"><TextBlock Text="{0}" FontSize="11.5" Foreground="#6B7890"/><TextBlock x:Name="{1}" Text="-" FontSize="14.5" FontWeight="SemiBold" Foreground="#1F2A44" TextWrapping="Wrap" Margin="0,1,0,0"/></StackPanel></Grid></Border>' -f (Esc $Label), $Name)
}
function New-FbStep([string]$No, [string]$Title, [string]$Text, [string]$Color) {
    '<Border Background="#F6F8FC" BorderBrush="#E2E7F0" BorderThickness="1" CornerRadius="12" Padding="14,12" Margin="0,0,10,10"><StackPanel>' +
    ('<StackPanel Orientation="Horizontal" Margin="0,0,0,6"><Border Width="28" Height="28" CornerRadius="14" Background="{0}" Margin="0,0,10,0"><TextBlock Text="{1}" FontWeight="Bold" Foreground="#FFFFFF" HorizontalAlignment="Center" VerticalAlignment="Center"/></Border><TextBlock Text="{2}" FontWeight="SemiBold" Foreground="#1F2A44" VerticalAlignment="Center" TextWrapping="Wrap" MaxWidth="200"/></StackPanel>' -f $Color, $No, (Esc $Title)) +
    ('<TextBlock Text="{0}" FontSize="12" Foreground="#475569" TextWrapping="Wrap"/></StackPanel></Border>' -f (Esc $Text))
}
function New-FbTile([string]$Glyph, [string]$Color, [string]$Title, [string[]]$Rows) {
    '<Border Background="#F6F8FC" BorderBrush="#E2E7F0" BorderThickness="1" CornerRadius="12" Padding="16,14" Margin="0,0,10,10"><StackPanel>' +
    ('<StackPanel Orientation="Horizontal" Margin="0,0,0,8"><Border Width="34" Height="34" CornerRadius="10" Background="{0}" Margin="0,0,10,0"><TextBlock Text="{1}" FontFamily="Segoe MDL2 Assets" FontSize="16" Foreground="#FFFFFF" HorizontalAlignment="Center" VerticalAlignment="Center"/></Border><TextBlock Text="{2}" FontSize="15" FontWeight="SemiBold" Foreground="#1F2A44" VerticalAlignment="Center"/></StackPanel>' -f $Color, $Glyph, (Esc $Title)) +
    ($Rows -join '') + '</StackPanel></Border>'
}
$fbDayCombo = '<ComboBox x:Name="FullBackup_Day" Width="130" Margin="0,0,10,8">' + (($FbDayNames.Keys | ForEach-Object { '<ComboBoxItem Content="{0}"/>' -f $_ }) -join '') + '</ComboBox>'

$fbHero = '<Border CornerRadius="18" Margin="0,0,4,16" Padding="26,20" Background="{StaticResource HeroGrad}"><Grid><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>' +
    '<StackPanel>' +
    '<TextBlock Text="SYSTEMABBILD DES GANZEN PCS" Foreground="#FFFFFF" Opacity="0.75" FontSize="11.5" FontWeight="SemiBold"/>' +
    '<StackPanel Orientation="Horizontal" Margin="0,8,0,0"><Border Width="44" Height="44" CornerRadius="22" Background="#33FFFFFF" Margin="0,0,14,0"><TextBlock x:Name="FbHeroGlyph" Text="&#xE78C;" FontFamily="Segoe MDL2 Assets" FontSize="21" Foreground="#FFFFFF" HorizontalAlignment="Center" VerticalAlignment="Center"/></Border>' +
    '<TextBlock x:Name="FbHeroTitle" Text="Komplettsicherung wird gelesen ..." FontSize="23" FontWeight="SemiBold" Foreground="#FFFFFF" VerticalAlignment="Center" TextWrapping="Wrap" MaxWidth="760"/></StackPanel>' +
    '<TextBlock x:Name="FbHeroSub" Text="" Foreground="#FFFFFF" Opacity="0.92" FontSize="13" TextWrapping="Wrap" Margin="0,8,0,0" MaxWidth="900" HorizontalAlignment="Left"/>' +
    '<WrapPanel x:Name="FbHeroChips" Margin="0,12,0,0"/>' +
    '<WrapPanel Margin="0,8,0,0"><Button x:Name="BtnFbRun" Content="Jetzt komplett sichern" Padding="18,7" FontWeight="SemiBold" Margin="0,0,8,6"/><Button x:Name="BtnFbVerify" Content="Neueste Sicherung prüfen" Style="{StaticResource Sec}" Margin="0,0,8,6"/><Button x:Name="BtnFbVerifyDeep" Content="Gründlich prüfen (Abbild einbinden)" Style="{StaticResource Sec}" Margin="0,0,8,6"/><Button x:Name="BtnFbRefresh" Content="Aktualisieren" Style="{StaticResource Sec}" Margin="0,0,8,6"/></WrapPanel>' +
    '</StackPanel>' +
    '<Border Grid.Column="1" Width="150" Height="150" CornerRadius="75" Background="#26FFFFFF" BorderBrush="#66FFFFFF" BorderThickness="3" Margin="20,0,0,0" VerticalAlignment="Center"><StackPanel VerticalAlignment="Center"><TextBlock x:Name="FbHeroAge" Text="-" FontSize="40" FontWeight="Bold" Foreground="#FFFFFF" HorizontalAlignment="Center"/><TextBlock x:Name="FbHeroAgeUnit" Text="" FontSize="12.5" Foreground="#FFFFFF" Opacity="0.9" HorizontalAlignment="Center" TextAlignment="Center" TextWrapping="Wrap" MaxWidth="120"/></StackPanel></Border>' +
    '</Grid></Border>'

$fbGlance = New-Card 'Auf einen Blick' @(
    ('<UniformGrid Columns="4">' +
        (New-FbKpi 'FbKLast' 'Letzte Sicherung' '&#xE823;' '#2D7FF9') + (New-FbKpi 'FbKResult' 'Ergebnis' '&#xE73E;' '#16A34A') +
        (New-FbKpi 'FbKSize' 'Größe des Abbilds' '&#xEDA2;' '#7C3AED') + (New-FbKpi 'FbKDuration' 'Dauer' '&#xE916;' '#0891B2') +
        (New-FbKpi 'FbKNext' 'Nächster Lauf' '&#xE787;' '#2563EB') + (New-FbKpi 'FbKFree' 'Frei am Ziel' '&#xE8B7;' '#EA580C') +
        (New-FbKpi 'FbKVersions' 'Versionen am Ziel' '&#xE81C;' '#DB2777') + (New-FbKpi 'FbKMedia' 'Wiederherstellung' '&#xE88E;' '#BE123C') +
        '</UniformGrid>'),
    '<Grid Margin="0,6,0,4"><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions><TextBlock Text="Die letzten 12 Sicherungen" FontWeight="SemiBold" Foreground="#1F2A44"/>' +
        '<StackPanel Grid.Column="1" Orientation="Horizontal">' +
        (('#16A34A|erfolgreich', '#EA580C|mit Warnung', '#DC2626|fehlgeschlagen', '#94A3B8|übersprungen/abgebrochen' | ForEach-Object { $q = $_ -split '\|'; '<Ellipse Width="9" Height="9" Fill="{0}" Margin="12,0,5,0" VerticalAlignment="Center"/><TextBlock Text="{1}" FontSize="11.5" Foreground="#6B7890" VerticalAlignment="Center"/>' -f $q[0], (Esc $q[1]) }) -join '') +
        '</StackPanel></Grid>',
    '<Border Background="#F6F8FC" BorderBrush="#E2E7F0" BorderThickness="1" CornerRadius="12" Padding="10,8"><Canvas x:Name="FbTimeline" Height="150" ClipToBounds="True" Background="Transparent"/></Border>',
    '<TextBlock x:Name="FbTimelineInfo" Text="" FontSize="12" Foreground="#6B7890" Margin="0,6,0,0" TextWrapping="Wrap"/>')

$fbTargetCard = New-Card 'Sicherungsziel' @(
    (New-TextRow 'FullBackup_Target' 'Wohin wird gesichert?' 'Externe NTFS-Festplatte (Laufwerksbuchstabe, z.B. E:) oder NAS-Freigabe (z.B. \\NAS\Sicherung). Die Windows-Sicherung legt dort den Ordner WindowsImageBackup an - auf einer Festplatte immer direkt im Hauptverzeichnis.' 'BtnFbTargetBrowse'),
    ('<WrapPanel Margin="0,2,0,4"><TextBlock Text="Angeschlossene Laufwerke:" Foreground="#475569" VerticalAlignment="Center" Margin="0,0,8,8"/><ComboBox x:Name="FbDriveCombo" Width="440" Margin="0,0,8,8" VerticalContentAlignment="Center"/><Button x:Name="BtnFbDriveUse" Content="Als Ziel nehmen" Style="{StaticResource Sec}" Padding="12,5" Margin="0,0,8,8"/><Button x:Name="BtnFbTargetTest" Content="Ziel prüfen" Style="{StaticResource Sec}" Padding="12,5" Margin="0,0,8,8"/></WrapPanel>'),
    ('<Grid Margin="0,4"><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>' +
        '<StackPanel Margin="0,0,8,0"><TextBlock Text="NAS-Benutzer (nur für Netzwerkziele)" FontSize="12" Foreground="#6B7890"/><TextBox x:Name="FullBackup_NasUser" Padding="4,3"/></StackPanel>' +
        '<StackPanel Grid.Column="1" Margin="0,0,8,0"><TextBlock Text="NAS-Kennwort" FontSize="12" Foreground="#6B7890"/><PasswordBox x:Name="FbNasPwd" Padding="4,3"/></StackPanel>' +
        '<StackPanel Grid.Column="2" Orientation="Horizontal" VerticalAlignment="Bottom"><Button x:Name="BtnFbNasSave" Content="Zugang speichern" Style="{StaticResource Sec}" Padding="12,5" Margin="0"/></StackPanel></Grid>'),
    '<TextBlock x:Name="FbNasInfo" Text="" FontSize="12" Foreground="#6B7890" Margin="0,2,0,6" TextWrapping="Wrap"/>',
    '<Border Background="#F6F8FC" BorderBrush="#E2E7F0" BorderThickness="1" CornerRadius="10" Padding="12,8" Margin="0,4,0,0"><StackPanel><TextBlock Text="Bewertung des Ziels" FontWeight="SemiBold" Foreground="#1F2A44" Margin="0,0,0,4"/><StackPanel x:Name="FbVerdict"/><TextBlock x:Name="FbEstimate" Text="" FontSize="12" Foreground="#475569" Margin="0,6,0,0" TextWrapping="Wrap"/></StackPanel></Border>')

$fbWhatCard = New-Card 'Was gesichert wird' @(
    (New-Hint 'Immer dabei sind alle Teile, die Windows zum Starten braucht ("kritische Volumes"): EFI-Systempartition, Laufwerk C: mit Windows, Programmen, Einstellungen und allen Benutzerdateien sowie die Wiederherstellungspartition. Nicht gesichert werden Auslagerungs- und Ruhezustandsdatei, Papierkorb-Inhalte älterer Schattenkopien und Dateien, die Programme ausdrücklich von Sicherungen ausnehmen.'),
    '<StackPanel x:Name="FbCritList" Margin="0,2,0,8"/>',
    '<TextBlock Text="Zusätzliche Laufwerke mitsichern" FontWeight="SemiBold" Foreground="#1F2A44"/>',
    (New-Hint 'Interne Datenlaufwerke (NTFS) können mit ins Abbild. Das Ziellaufwerk selbst und USB-Sticks lassen sich nicht auswählen.'),
    '<WrapPanel x:Name="FbIncludePanel" Margin="0,0,0,6"/>',
    '<TextBox x:Name="FullBackup_Include" Visibility="Collapsed"/>',
    (New-FieldRow 'Schattenkopie-Art' ('<ComboBox x:Name="FullBackup_Vss" Width="520" HorizontalAlignment="Left"><ComboBoxItem Content="{0}"/><ComboBoxItem Content="{1}"/></ComboBox>' -f (Esc 'Kopie (empfohlen - andere Sicherungsprogramme bleiben unberührt)'), (Esc 'Vollständig (setzt Anwendungsprotokolle zurück - nur ohne andere Sicherung)'))),
    (New-Hint 'Kopie (-vssCopy) ist für Arbeitsplätze richtig. Vollständig (-vssFull) kürzt z.B. Exchange- oder SQL-Protokolle - nur wählen, wenn PC-Tools die einzige Sicherung dieser Programme ist.'),
    (New-CheckRow 'FullBackup_NasVersions' 'NAS: mehrere Versionen behalten (je Sicherung ein Datumsordner)' 'Auf Netzwerkfreigaben hebt Windows selbst nur EINE Version auf und überschreibt sie bei jeder Sicherung. Mit dieser Einstellung schreibt PC-Tools jede Sicherung in einen eigenen Ordner (PC-Tools-Komplettsicherung\<PC>\<Datum>) und behält so viele, wie unten eingestellt - jede braucht die volle Größe.'))

$fbKeepCard = New-Card 'Prüfung und Versionen' @(
    (New-CheckRow 'FullBackup_Verify' 'Nach jeder Sicherung prüfen' 'Prüft, ob die Windows-Sicherung die neue Version kennt ("wbadmin get versions"), ob Ordner WindowsImageBackup, BackupSpecs.xml und die Abbild-Dateien (.vhdx) da sind und ob die Größe zum belegten Platz passt.'),
    (New-CheckRow 'FullBackup_DeepVerify' 'Gründlich prüfen: Abbild schreibgeschützt einbinden' 'Bindet die größte VHDX-Datei schreibgeschützt ein, sucht darin Windows\System32\config\SYSTEM und liest Systemdateien - so ist sicher, dass das Abbild lesbar ist. Dauert 1-3 Minuten länger.'),
    (New-NumRow 'Versionen behalten' 'Ältere Versionen werden nach einer erfolgreichen Sicherung entfernt, die neueste nie. 0 = Windows entscheidet selbst.' 'FullBackup_Keep' '' 'Versionen'),
    (New-Hint 'Wichtig zu wissen: Auf einer lokalen Festplatte speichert Windows ältere Versionen nur als Änderungen (Schattenkopien) und löscht die ältesten selbst, wenn der Platz knapp wird. "wbadmin delete backup -keepVersions" gibt es nur auf Windows Server - auf Windows 11 entfernt PC-Tools überzählige Versionen über ihre Schattenkopien. Auf dem NAS (Datumsordner) werden ganze Ordner gelöscht.'),
    (New-White (New-DataGrid 'FbVerGrid' @('Datum|DateText|140', 'Inhalt|Content|210', 'Größe|SizeText|110', 'Ort|Place|*') 'Height="210" IsReadOnly="True" AutoGenerateColumns="False" SelectionMode="Single"') 'Margin="0,4,0,6"'),
    '<TextBlock x:Name="FbVerInfo" Text="" FontSize="12" Foreground="#6B7890" TextWrapping="Wrap" Margin="0,0,0,6"/>',
    '<WrapPanel><Button x:Name="BtnFbVerRead" Content="Versionen lesen" Style="{StaticResource Sec}" Margin="0,0,8,8"/><Button x:Name="BtnFbVerOpen" Content="Ordner der Version öffnen" Style="{StaticResource Sec}" Margin="0,0,8,8"/><Button x:Name="BtnFbPrune" Content="Alte Versionen jetzt entfernen" Style="{StaticResource Sec}" Margin="0,0,8,8"/></WrapPanel>')

$fbSchedCard = New-Card 'Zeitplan' @(
