        '<StackPanel x:Name="FbMonthPanel" Orientation="Horizontal"><TextBlock Text="am" VerticalAlignment="Center" Margin="0,0,8,8"/><ComboBox x:Name="FullBackup_MonthWeek" Width="100" Margin="0,0,10,8"><ComboBoxItem Content="ersten"/><ComboBoxItem Content="zweiten"/><ComboBoxItem Content="dritten"/><ComboBoxItem Content="vierten"/><ComboBoxItem Content="letzten"/></ComboBox></StackPanel>' +
