$fbMediaCard = New-Card 'Wiederherstellungsmedium' @(
    (New-Hint 'Ein Abbild nützt nur, wenn man den PC auch ohne funktionierendes Windows davon starten kann. Dafür gibt es zwei Wege - am besten beide.'),
    ('<UniformGrid Columns="2">' +
        (New-FbTile '&#xE8B7;' '#7C3AED' 'Wiederherstellungspaket am Ziel' @(
