$fbHistCard = New-Card 'Verlauf' @(
    (New-White (New-DataGrid 'FbHistGrid' @('Datum|StartText|130', 'Ergebnis|Result|100', 'Dauer|DurText|80', 'Größe|SizeText|90', 'Ziel|Target|150', 'Prüfung|Verify|150', 'Meldung|Message|*') 'Height="210" IsReadOnly="True" AutoGenerateColumns="False" SelectionMode="Single"') 'Margin="0,0,0,8"'),
