    '<WrapPanel><Button x:Name="BtnFbHistLog" Content="Protokoll des Laufs öffnen" Style="{StaticResource Sec}" Margin="0,0,8,8"/><Button x:Name="BtnFbHistDir" Content="Datenordner öffnen" Style="{StaticResource Sec}" Margin="0,0,8,8"/></WrapPanel>')

$fbToolsCard = New-Card 'Backup-Programme auf diesem PC' @(
