    '<WrapPanel Margin="0,8,0,0"><Button x:Name="BtnFbToolsScan" Content="Backup-Programme erkennen" Style="{StaticResource Sec}"/><Button x:Name="BtnFbGetAomei" Content="AOMEI Backupper (gratis)" Style="{StaticResource Sec}"/><Button x:Name="BtnFbGetVeeam" Content="Veeam Agent (gratis)" Style="{StaticResource Sec}"/><Button x:Name="BtnFbGetHasleo" Content="Hasleo (gratis)" Style="{StaticResource Sec}"/><Button x:Name="BtnFbGetDuplicati" Content="Duplicati (Open Source)" Style="{StaticResource Sec}"/></WrapPanel>')
$pageFullBackup = New-Page 'Komplettsicherung' 'Ein vollständiges Abbild des ganzen PCs - Windows, Programme, Einstellungen und Dateien - regelmäßig auf eine externe Festplatte oder ein NAS. Nach einem Festplattenschaden, Schadsoftware oder einem kaputten Windows ist der PC damit in einer Stunde wieder genau so wie vorher. Dazu: Prüfung jeder Sicherung, Versionen, Zeitplan und ein Wiederherstellungsmedium.' ($fbHero + $fbGlance + $fbTargetCard + $fbWhatCard + $fbKeepCard + $fbSchedCard + $fbMediaCard + $fbRestoreCard + $fbToolsCard + $fbHistCard)
# ---------------------------------------------------------------- PC-Reiniger (Seiten-XAML)
function New-CcTile([string]$Name, [string]$Label, [string]$Color, [string]$Glyph, [string]$Tip) {
@"
<Button x:Name="$Name" Cursor="Hand" Margin="0,0,12,12" Padding="0" ToolTip="$(Esc $Tip)">
  <Button.Template><ControlTemplate TargetType="Button"><Border x:Name="Bd" Width="214" CornerRadius="14" Padding="16,12,14,12" Background="$Color"><Border.Effect><DropShadowEffect BlurRadius="14" ShadowDepth="3" Direction="270" Opacity="0.22" Color="$Color"/></Border.Effect><ContentPresenter/></Border>
    <ControlTemplate.Triggers><Trigger Property="IsMouseOver" Value="True"><Setter TargetName="Bd" Property="Opacity" Value="0.9"/></Trigger><Trigger Property="IsPressed" Value="True"><Setter TargetName="Bd" Property="Opacity" Value="0.8"/></Trigger></ControlTemplate.Triggers></ControlTemplate></Button.Template>
  <StackPanel>
    <DockPanel>
      <TextBlock DockPanel.Dock="Right" Text="$Glyph" FontFamily="Segoe MDL2 Assets" FontSize="20" Foreground="#FFFFFF" Opacity="0.85" VerticalAlignment="Top"/>
      <TextBlock x:Name="${Name}Val" Text="-" FontSize="28" FontWeight="Bold" Foreground="#FFFFFF"/>
    </DockPanel>
    <TextBlock Text="$(Esc $Label)" Foreground="#FFFFFF" FontWeight="SemiBold" TextWrapping="Wrap"/>
    <TextBlock x:Name="${Name}Sub" Text="" Foreground="#FFFFFF" Opacity="0.85" FontSize="11.5" TextWrapping="Wrap" Margin="0,2,0,0"/>
  </StackPanel>
</Button>
"@
}
function New-CcSeg([string]$Name, [string]$Glyph, [string]$Text, [bool]$Checked = $false) {
    '<RadioButton x:Name="{0}" GroupName="CcNav" Style="{{StaticResource CcSeg}}" IsChecked="{3}"><StackPanel Orientation="Horizontal"><TextBlock Text="{1}" FontFamily="Segoe MDL2 Assets" FontSize="14" VerticalAlignment="Center" Margin="0,0,8,0"/><TextBlock Text="{2}" VerticalAlignment="Center"/></StackPanel></RadioButton>' -f $Name, $Glyph, (Esc $Text), $(if ($Checked) { 'True' } else { 'False' })
}
# Tabelle mit Ankreuz-Spalte (Bindung an die Eigenschaft Sel)
function New-CcCheckGrid([string]$Name, [string[]]$Cols, [string]$Extra = '') {
    $c = foreach ($col in $Cols) {
        $f = $col -split '\|'
        $w = if ($f.Count -gt 2 -and $f[2]) { $f[2] } else { '*' }
        $sort = if ($f.Count -gt 3 -and $f[3]) { ' SortMemberPath="{0}"' -f $f[3] } else { '' }
        '<DataGridTextColumn Header="{0}" Binding="{{Binding {1}}}" Width="{2}"{3}/>' -f (Esc $f[0]), $f[1], $w, $sort
    }
    $chk = '<DataGridTemplateColumn Header="" Width="54" CanUserSort="False"><DataGridTemplateColumn.CellTemplate><DataTemplate><CheckBox IsChecked="{Binding Sel, Mode=TwoWay, UpdateSourceTrigger=PropertyChanged}" HorizontalAlignment="Center" Focusable="False"/></DataTemplate></DataGridTemplateColumn.CellTemplate></DataGridTemplateColumn>'
    '<DataGrid x:Name="{0}" {1}><DataGrid.Columns>{2}{3}</DataGrid.Columns></DataGrid>' -f $Name, $Extra, $chk, ($c -join '')
}
# farbiger Erklär-Kopf je Bereich
function New-CcBanner([string]$Glyph, [string]$Color, [string]$Title, [string]$Text, [string]$Extra = '') {
@"
<Border Background="White" CornerRadius="14" Padding="20,16" Margin="0,0,4,16" BorderBrush="#E2E7F0" BorderThickness="1">
  <Border.Effect><DropShadowEffect BlurRadius="18" ShadowDepth="2" Direction="270" Opacity="0.07" Color="Black"/></Border.Effect>
  <Grid>
    <Grid.ColumnDefinitions><ColumnDefinition Width="Auto"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>
    <Border Width="46" Height="46" CornerRadius="12" Background="$Color" Margin="0,2,16,0" VerticalAlignment="Top">
      <TextBlock Text="$Glyph" FontFamily="Segoe MDL2 Assets" FontSize="21" Foreground="#FFFFFF" HorizontalAlignment="Center" VerticalAlignment="Center"/>
    </Border>
    <StackPanel Grid.Column="1">
      <TextBlock Text="$(Esc $Title)" FontSize="17" FontWeight="SemiBold" Foreground="#1F2A44"/>
      <TextBlock Text="$(Esc $Text)" Foreground="#6B7890" FontSize="12.5" TextWrapping="Wrap" Margin="0,5,0,0"/>
      $Extra
    </StackPanel>
  </Grid>
</Border>
"@
}
function New-CcRegCat([string]$Key, [string]$Text, [string]$Tip) {
    '<CheckBox x:Name="CcRegCat_{0}" Content="{1}" IsChecked="True" Margin="0,4,22,6" ToolTip="{2}"/>' -f $Key, (Esc $Text), (Esc $Tip)
}

$ccResources = @'
<StackPanel.Resources>
  <Style x:Key="CcSeg" TargetType="RadioButton">
    <Setter Property="Foreground" Value="#1F2A44"/><Setter Property="Cursor" Value="Hand"/><Setter Property="Margin" Value="0,0,3,0"/><Setter Property="FontWeight" Value="SemiBold"/><Setter Property="FocusVisualStyle" Value="{x:Null}"/>
    <Setter Property="Template"><Setter.Value><ControlTemplate TargetType="RadioButton">
      <Border x:Name="Bd" Background="Transparent" CornerRadius="9" Padding="14,8"><ContentPresenter VerticalAlignment="Center"/></Border>
