"@

Set-SplashStatus 'Oberfläche wird aufgebaut ...'
try { $null = Initialize-I18n (Get-UiLang) -Download } catch { $script:I18nOn = $false }
try {
    $window = [Windows.Markup.XamlReader]::Parse((Convert-ThemeXaml $xaml))
    if ($Script:Dark) { $window.Add_SourceInitialized({ try { $h = (New-Object Windows.Interop.WindowInteropHelper $window).Handle; $one = 1; [void][PCPflege.Dwm]::DwmSetWindowAttribute($h, 20, [ref]$one, 4) } catch { } }) }
    $window.Add_ContentRendered({ try { Close-PflegeSplash } catch { }; try { $window.Dispatcher.BeginInvoke([Action] { try { Show-FirstRunOrNews } catch { } }, [Windows.Threading.DispatcherPriority]::Background) | Out-Null } catch { } })
    if ($Script:IsPortable) { $window.Title = 'PC-Tools (portabel vom Stick)' }
} catch {
    $xErr = $_.Exception.Message
    # Notfall: Oberfläche defekt -> zuerst die gesicherte Vorversion, sonst eine reparierte Version aus der Update-Quelle
    $fixed = $false
    try {
        $pv = Get-PflegeVorversion
        if ($pv -and $pv -ne $AppVersion) {
            $null = Restore-PflegeVorversion ('Oberfläche ließ sich nicht laden: ' + $xErr)
            Remove-Item -LiteralPath (Join-Path $DataDir 'start.json') -Force -ErrorAction SilentlyContinue
            [Windows.MessageBox]::Show((T (('Die Oberfläche von Version {0} konnte nicht geladen werden. PC-Tools hat automatisch die Vorversion {1} wiederhergestellt und startet sie jetzt.' -f $AppVersion, $pv))), (T ('PC-Tools')), 'OK', 'Information') | Out-Null
            $null = Start-HiddenPS $PSCommandPath
            return
        }
    } catch { }
    try {
        $c = Read-PflegeConfig
        $man = Get-UpdateManifest $c.Settings.UpdateSource
        if ($man -and [string]$man.Version -ne $AppVersion) {
            Install-PflegeUpdate $c.Settings.UpdateSource $man
            $fixed = $true
            [Windows.MessageBox]::Show((T (('Die Oberfläche dieser Version konnte nicht geladen werden. Version {0} wurde deshalb aus der Update-Quelle installiert - bitte PC-Tools neu starten.' -f $man.Version))), (T ('PC-Tools')), 'OK', 'Information') | Out-Null
        }
    } catch { }
    if (-not $fixed) { [Windows.MessageBox]::Show((T ("Oberfläche konnte nicht geladen werden:`n$xErr")), (T ('PC-Tools')), 'OK', 'Error') | Out-Null }
    return
}

# ---- Fehler in der Oberfläche abfangen statt abstürzen (9.3)
$script:GuiErrLog = Join-Path (Join-Path $DataDir 'Logs') 'Oberflaeche-Fehler.log'
try { New-Item (Split-Path $script:GuiErrLog) -ItemType Directory -Force | Out-Null } catch { }
$window.Dispatcher.Add_UnhandledException({
    param($s, $e)
    try { Add-Content -LiteralPath $script:GuiErrLog -Value ('{0:yyyy-MM-dd HH:mm:ss}  v{1}  {2}' -f (Get-Date), $AppVersion, $e.Exception.ToString()) -Encoding UTF8 } catch { }
    $e.Handled = $true
    try { $ui.StatusText.Text = 'Ein Fehler wurde abgefangen - PC-Tools läuft weiter. Details: Einstellungen > Stabilität > Fehlerprotokoll.' } catch { }
})
$window.Add_ContentRendered({
    # Start erfolgreich -> Startschutz zurücksetzen
    try { [ordered]@{ Version = $AppVersion; Fails = 0; Ok = $true; Time = (Get-Date).ToString('o') } | ConvertTo-Json | Set-Content -LiteralPath (Join-Path $DataDir 'start.json') -Encoding UTF8 } catch { }
    $ri = Join-Path $DataDir 'rollback-info.txt'
    if (Test-Path -LiteralPath $ri) { try { $t = Get-Content -LiteralPath $ri -Raw -Encoding UTF8; Remove-Item -LiteralPath $ri -Force; [Windows.MessageBox]::Show((T ($t)), (T ('PC-Tools - automatisch zurückgesetzt')), 'OK', 'Information') | Out-Null } catch { } }
})
$ui = @{}
foreach ($n in 'Tabs', 'LogBox', 'Progress', 'StatusText', 'InfoOS', 'InfoModel', 'InfoOem', 'InfoDisk', 'InfoUptime', 'InfoReboot', 'InfoLastRun', 'InfoTask', 'ScheduleStatus',
               'BtnAnalyze', 'BtnCheckUpd', 'BtnCheckUpd2', 'BtnRunAll', 'BtnRunClean', 'BtnRunOpt', 'BtnRunUpd', 'BtnSchedule', 'BtnSave', 'BtnCancel',
               'BtnOpenLogs', 'BtnClearLog', 'BtnBrowse', 'BtnBrowseNinite', 'Update_NinitePath', 'Update_OEMToolPath', 'ActDot', 'ActStep', 'ActState', 'ActDetail', 'ActLast', 'ActProc', 'Pulse',
               'TabLog', 'ProfPanel', 'ProfTitle', 'ProfDesc', 'ProfApps', 'ProfInfo', 'BtnProfAll', 'BtnProfNone', 'BtnProfInstall',
               'Settings_CleanDays', 'BtnApplyDays', 'BtnOpenLogs2', 'BtnOpenData', 'BtnCfgExport', 'BtnCfgImport', 'BtnCfgReset', 'BtnTaskRemove',
               'InfoVersion', 'InfoScript', 'InfoData', 'InfoComputer', 'ShortcutLogo', 'ShortcutStatus', 'Settings_UpdateAuto', 'UpdStatus', 'GhToken', 'BtnGhSave', 'BtnGhTest', 'GhStatus', 'Settings_UpdateSource', 'BtnUpdBrowse', 'BtnUpdCheck', 'BtnUpdInstall', 'BtnUpdPublish', 'InfoAppVer', 'AvStatus', 'AvHint', 'AvPaths', 'BtnAvCopy', 'BtnAvDefender', 'BtnAvOpen', 'InfoAv', 'BtnLnkDesktop', 'BtnLnkPublic', 'BtnLnkStart', 'BtnLnkRemove', 'TweakPanel', 'TweakInfo', 'AutoList', 'BtnTwRec', 'BtnTwPerf', 'BtnTwPriv', 'BtnTwStd', 'BtnTwCur', 'BtnTwExplorer', 'BtnTweakApply', 'BtnAutoRefresh', 'DeskList', 'DeskInfo', 'DeskAll', 'BtnDeskScan', 'BtnDeskOpen', 'BtnDeskUndo', 'BtnDeskRun', 'DeskArrInfo', 'BtnDeskArrPreview', 'BtnDeskArrange', 'BtnDeskLayoutSave', 'BtnDeskLayoutLoad', 'BtnDeskArrLnk', 'MonCanvas', 'MonCurrent', 'MonName', 'BtnMonRefresh', 'BtnMonSave', 'BtnMonSettings', 'MonList', 'BtnTopoExtend', 'BtnTopoClone', 'BtnTopoInternal', 'BtnTopoExternal', 'Monitor_AutoProfile', 'Monitor_AfterSwitch', 'Monitor_AutoAtLogon', 'NinSearch', 'NinSearchHint', 'NinSource', 'NinCategory', 'NinCatOpts', 'NinOnlySel', 'NinHideInst', 'NinPanel', 'NinCatView', 'NinOnlineView', 'NinOnlineGrid', 'NinOnlineEmpty', 'BtnNinOnline', 'NinInfo', 'BtnNinAudit', 'BtnNinClear', 'BtnNinInstall') {
    $ui[$n] = $window.FindName($n)
}
foreach ($m in [regex]::Matches($xaml, 'x:Name="([^"]+)"')) { $n = $m.Groups[1].Value; if (-not $ui.ContainsKey($n)) { $c = $window.FindName($n); if ($c) { $ui[$n] = $c } } }
$RunButtons = 'BtnAnalyze', 'BtnCheckUpd', 'BtnCheckUpd2', 'BtnRunAll', 'BtnRunClean', 'BtnRunOpt', 'BtnRunUpd', 'BtnSchedule', 'BtnSave', 'BtnNinInstall', 'BtnNinAudit', 'BtnProfInstall', 'BtnTbLoadAll', 'BtnTbUsb', 'BtnKsInstallSel', 'BtnKsInstallAll', 'BtnRsBuild'

function Set-UiFromConfig($Cfg) {
    foreach ($sec in $Cfg.PSObject.Properties) {
        foreach ($p in $sec.Value.PSObject.Properties) {
            $c = $window.FindName(('{0}_{1}' -f $sec.Name, $p.Name))
            if (-not $c) { continue }
            switch ($c.GetType().Name) {
                'CheckBox' { $c.IsChecked = [bool]$p.Value }
                'TextBox'  { $c.Text = [string]$p.Value }
                'ComboBox' { foreach ($it in $c.Items) { if ([string]$it.Content -eq [string]$p.Value) { $c.SelectedItem = $it } } }
            }
        }
    }
}
function Get-ConfigFromUi {
    $cfg = Get-DefaultConfig
    foreach ($sec in $cfg.PSObject.Properties) {
        foreach ($p in $sec.Value.PSObject.Properties) {
            $c = $window.FindName(('{0}_{1}' -f $sec.Name, $p.Name))
            if (-not $c) { continue }
            switch ($c.GetType().Name) {
                'CheckBox' { $p.Value = [bool]$c.IsChecked }
                'TextBox'  {
                    if ($p.Value -is [int] -or $p.Value -is [long]) {
                        $n = 0; if ([int]::TryParse($c.Text.Trim(), [ref]$n) -and $n -ge 0) { $p.Value = $n }
                    } else { $p.Value = $c.Text.Trim() }
                }
                'ComboBox' { if ($c.SelectedItem) { $p.Value = [string]$c.SelectedItem.Content } }
            }
        }
    }
    return $cfg
}

function Get-TaskText {
    $t = Get-ScheduledTask -TaskName $TaskName -ErrorAction SilentlyContinue
    if (-not $t) { return 'Nicht eingerichtet' }
    $ti = Get-ScheduledTaskInfo -TaskName $TaskName -ErrorAction SilentlyContinue
    $state = if ($t.State -eq 'Disabled') { 'Deaktiviert' } else { 'Aktiv' }
    $next = if ($ti -and $ti.NextRunTime) { $ti.NextRunTime.ToString('dd.MM.yyyy HH:mm') } else { '-' }
    $last = if ($ti -and $ti.LastRunTime -and $ti.LastRunTime.Year -gt 2000) { $ti.LastRunTime.ToString('dd.MM.yyyy HH:mm') } else { 'noch nie' }
    return ('{0} - nächster Lauf: {1} - letzter Lauf: {2}' -f $state, $next, $last)
}

# Vorname des angemeldeten Benutzers (auch bei Microsoft-/Firmenkonto und wenn PC-Tools mit einem anderen Admin-Konto läuft)
function Get-GreetingName {
    if ($script:GreetName) { return $script:GreetName }
    $name = ''
    try {
        $sid = ''; $ex = @(Get-CimInstance Win32_Process -Filter "Name='explorer.exe'" -ErrorAction Stop)[0]
        if ($ex) { $o = Invoke-CimMethod -InputObject $ex -MethodName GetOwnerSid -ErrorAction Stop; $sid = [string]$o.Sid }
        foreach ($k in @(Get-ChildItem 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Authentication\LogonUI\SessionData' -ErrorAction SilentlyContinue)) {
            $p = Get-ItemProperty $k.PSPath -ErrorAction SilentlyContinue
            if ($p.LoggedOnDisplayName -and (-not $sid -or [string]$p.LoggedOnUserSID -eq $sid)) { $name = [string]$p.LoggedOnDisplayName; break }
        }
        if (-not $name -and $sid) { try { Add-Type -AssemblyName System.DirectoryServices.AccountManagement; $ctx = New-Object DirectoryServices.AccountManagement.PrincipalContext('Machine'); $u = [DirectoryServices.AccountManagement.UserPrincipal]::FindByIdentity($ctx, 'Sid', $sid); if ($u) { $name = $(if ($u.DisplayName) { $u.DisplayName } else { $u.SamAccountName }) } } catch { } }
    } catch { }
    if (-not $name) { try { Add-Type -AssemblyName System.DirectoryServices.AccountManagement; $name = [string][DirectoryServices.AccountManagement.UserPrincipal]::Current.DisplayName } catch { } }
    if (-not $name) { try { $name = [string](Get-LocalUser -Name $env:USERNAME -ErrorAction Stop).FullName } catch { } }
    if (-not $name) { $name = $env:USERNAME }
    if ($name -match '@') { $name = ($name -split '@')[0] -replace '[\._]', ' ' }
    $first = (($name.Trim() -split '\s+')[0])
    if ($first -cmatch '^[a-zäöü]') { $first = $first.Substring(0, 1).ToUpper() + $first.Substring(1) }
    $script:GreetName = $first
    return $first
}
function Update-Overview {
    try {
        $os  = Get-CimInstance Win32_OperatingSystem
        $reg = Get-ItemProperty 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion'
        $cs  = Get-CimInstance Win32_ComputerSystem
        $sc = Get-SysClassCached
        $osKind = if ($sc.IsServer) { 'Server' } else { 'Client' }
        $ui.InfoOS.Text    = '{0}  (Version {1}, Build {2}.{3}) - {4}' -f $os.Caption, $reg.DisplayVersion, $reg.CurrentBuild, $reg.UBR, $osKind
        $devType = $sc.Chassis; if ($sc.IsVM -and $sc.VmHost) { $devType = 'Virtuelle Maschine (' + $sc.VmHost + ')' }
        $ui.InfoModel.Text = '{0} {1} - {2}' -f $cs.Manufacturer, $cs.Model, $devType
        $m = [string]$cs.Manufacturer; $pf86 = ${env:ProgramFiles(x86)}
        $oem = $null
        if ($m -match 'Dell') { $oem = @('Dell Command | Update', (Join-Path $pf86 'Dell\CommandUpdate\dcu-cli.exe'), (Join-Path $env:ProgramFiles 'Dell\CommandUpdate\dcu-cli.exe')) }
        elseif ($m -match 'HP|Hewlett') { $oem = @('HP Image Assistant', $ui.Update_OEMToolPath.Text, 'C:\SWSetup\HPImageAssistant\HPImageAssistant.exe') }
        elseif ($m -match 'Lenovo') { $oem = @('Lenovo Thin Installer', (Join-Path $pf86 'Lenovo\ThinInstaller\ThinInstaller.exe')) }
        if ($oem) {
            $p = $oem[1..($oem.Count - 1)] | Where-Object { $_ -and (Test-Path -LiteralPath $_) } | Select-Object -First 1
            if ($p) { $ui.InfoOem.Text = '{0} - Version {1}' -f $oem[0], (Get-Item -LiteralPath $p).VersionInfo.ProductVersion }
            else { $ui.InfoOem.Text = '{0} - noch nicht installiert (wird beim nächsten Update-Lauf automatisch eingerichtet)' -f $oem[0] }
        } elseif ($m -match 'Microsoft' -and $cs.Model -match 'Surface') { $ui.InfoOem.Text = 'Microsoft Surface - Treiber und Firmware über Windows Update und die Seite Microsoft Surface (Treiberpaket)' }
        elseif ($m -match 'Fujitsu|Acer|ASUS|ASUSTeK|MSI|Micro-Star|Gigabyte|Medion|Samsung|Toshiba|Dynabook|LG|Huawei|Razer|Shuttle|Zotac|Intel|Supermicro|Gateway|Packard') {
            $brand = @('Fujitsu', 'Acer', 'ASUS', 'MSI', 'Gigabyte', 'Medion', 'Samsung', 'Toshiba', 'Dynabook', 'LG', 'Huawei', 'Razer', 'Shuttle', 'Zotac', 'Intel', 'Supermicro') | Where-Object { $m -match $_ } | Select-Object -First 1
            if (-not $brand) { $brand = ($m -split '\s+')[0] }
            $ui.InfoOem.Text = ('{0}: Treiber und BIOS/Firmware kommen über Windows Update und das Update-Center der Treiber-Seite - zusätzlich bietet der Hersteller ({0}) eigene Treiber zum jeweiligen Modell an.' -f $brand)
        } else { $ui.InfoOem.Text = 'kein spezielles Hersteller-Tool nötig - Treiber kommen über Windows Update und die Treiber-Seite (Update-Center)' }
        if ($sc -and $sc.IsServer) { $ui.InfoOem.Text = ('Windows Server erkannt ({0}) - Treiber über Windows Update und Hersteller; Client-only-Funktionen (Store-Apps, BitLocker-Oberfläche) sind je nach Server-Rolle evtl. nicht verfügbar.' -f $sc.OsFamily) }
        $drv = New-Object System.IO.DriveInfo $env:SystemDrive
        $ui.InfoDisk.Text  = '{0:N1} GB frei von {1:N0} GB' -f ($drv.AvailableFreeSpace / 1GB), ($drv.TotalSize / 1GB)
        $usedPct = 100 - $drv.AvailableFreeSpace * 100 / $drv.TotalSize
        Set-Gauge 'GaDisk' $usedPct ('{0:N0} %' -f $usedPct) ('{0:N0} GB frei' -f ($drv.AvailableFreeSpace / 1GB)) $(if ($usedPct -ge 90) { '#FDE68A' } else { '#FFFFFF' })
        $h = (Get-Date).Hour
        $ui.HeroHello.Text = '{0}, {1}' -f $(if ($h -lt 5) { 'Gute Nacht' } elseif ($h -lt 11) { 'Guten Morgen' } elseif ($h -lt 18) { 'Guten Tag' } else { 'Guten Abend' }), (Get-GreetingName)
        $ui.HeroSub.Text = '{0} {1}  ·  {2}' -f $cs.Manufacturer, $(try { (Get-CimInstance Win32_ComputerSystemProduct).Version } catch { $cs.Model }), ($os.Caption -replace '^Microsoft ', '')
        $up = (Get-Date) - $os.LastBootUpTime
        $ui.InfoUptime.Text = '{0} Tage, {1} Std. (seit {2:dd.MM.yyyy HH:mm})' -f $up.Days, $up.Hours, $os.LastBootUpTime
        $pend = (Test-Path 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Component Based Servicing\RebootPending') -or
                (Test-Path 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\WindowsUpdate\Auto Update\RebootRequired')
        $ui.InfoReboot.Text = if ($pend) { 'Ja - bitte neu starten' } else { 'Nein' }
        $lrFile = Join-Path $DataDir 'lastrun.json'
        if (Test-Path $lrFile) {
            $lr = Get-Content $lrFile -Raw -Encoding UTF8 | ConvertFrom-Json
            $ui.InfoLastRun.Text = '{0} ({1}) - {2} freigegeben, {3} Updates, {4} Warnungen' -f $lr.Zeit, $lr.Teile, $lr.Freigegeben, $lr.Updates, $lr.Warnungen
        } else { $ui.InfoLastRun.Text = 'noch nie' }
        $tt = Get-TaskText
        $ui.InfoTask.Text = $tt
        $chips = @()
        $chips += 'Letzte Pflege: ' + $(if (Test-Path $lrFile) { ($lr.Zeit -split ' ')[0] } else { 'noch nie' })
        $chips += 'Läuft seit {0} Tagen' -f $up.Days
        $chips += $(if ($pend) { 'Neustart nötig' } else { 'Kein Neustart nötig' })
        $chips += $(if ($tt -match 'aktiv|täglich|wöchentlich|Uhr') { 'Automatik an' } else { 'Automatik aus' })
        $ui.HeroChips.Children.Clear()
        foreach ($c in $chips) {
            $b = New-Object Windows.Controls.Border; $b.CornerRadius = '12'; $b.Padding = '11,4'; $b.Margin = '0,0,8,6'
            $b.Background = (New-Object Windows.Media.BrushConverter).ConvertFromString('#33FFFFFF')
            $t = New-Object Windows.Controls.TextBlock; $t.Text = $c; $t.FontSize = 12; $t.Foreground = [Windows.Media.Brushes]::White
            $b.Child = $t; [void]$ui.HeroChips.Children.Add($b)
        }
        $ui.ScheduleStatus.Text = $tt
    } catch { }
}

# Programmdateien nach C:\ProgramData\PCPflege kopieren (Zeitplan und Verknüpfungen nutzen diese Kopie)
function Sync-PflegeFiles {
    if ($Script:IsPortable) { return }
    if (-not $PSScriptRoot -or ($PSScriptRoot.TrimEnd('\') -eq $DataDir.TrimEnd('\'))) { return }
    foreach ($n in 'PCPflege.ps1', 'NinitePro.exe', 'PCPflege.ico') {
        $src = Join-Path $PSScriptRoot $n
        $dst = Join-Path $DataDir $n
        if (-not (Test-Path -LiteralPath $src)) { continue }
        try {
            if (-not (Test-Path -LiteralPath $dst) -or (Get-Item -LiteralPath $src).LastWriteTime -gt (Get-Item -LiteralPath $dst).LastWriteTime -or
                (Get-Item -LiteralPath $src).Length -ne (Get-Item -LiteralPath $dst).Length) {
                Copy-Item -LiteralPath $src -Destination $dst -Force
            }
        } catch { }
    }
}
function Get-ShortcutPath([string]$Where) {
    switch ($Where) {
        'Desktop'   { Join-Path ([Environment]::GetFolderPath('Desktop')) 'PC-Tools.lnk' }
        'Public'    { Join-Path ([Environment]::GetFolderPath('CommonDesktopDirectory')) 'PC-Tools.lnk' }
        'StartMenu' { Join-Path ([Environment]::GetFolderPath('CommonPrograms')) 'PC-Tools.lnk' }
    }
}
function Move-OldShortcuts {
    # Umbenennung PC-Pflege -> PC-Tools (Version 8): alte Verknüpfungen durch neue ersetzen
    foreach ($w in 'Desktop', 'Public', 'StartMenu') {
        $new = Get-ShortcutPath $w; $old = Join-Path (Split-Path $new) 'PC-Pflege.lnk'
        if (Test-Path -LiteralPath $old) { try { if (-not (Test-Path -LiteralPath $new)) { New-PflegeShortcut $w }; Remove-Item -LiteralPath $old -Force -ErrorAction SilentlyContinue } catch { } }
    }
}
function New-PflegeShortcut([string]$Where) {
    Sync-PflegeFiles
    $lnk = Get-ShortcutPath $Where
    $sh = New-Object -ComObject WScript.Shell
    $sc = $sh.CreateShortcut($lnk)
    Set-HiddenShortcut $sc (Join-Path $DataDir 'PCPflege.ps1')
    $sc.WorkingDirectory = $DataDir
    $sc.Description = 'PC-Tools - Aufräumen, Optimieren, Updates und Programme installieren'
    $ico = Join-Path $DataDir 'PCPflege.ico'
    if (Test-Path -LiteralPath $ico) { $sc.IconLocation = '{0},0' -f $ico }
    $sc.Save()
    [void][Runtime.InteropServices.Marshal]::ReleaseComObject($sh)
    Set-LnkRunAsAdmin $lnk
    return $lnk
}
function Update-ShortcutStatus {
    $names = @{ Desktop = 'mein Desktop'; Public = 'Desktop aller Benutzer'; StartMenu = 'Startmenü' }
    $have = @(foreach ($w in 'Desktop', 'Public', 'StartMenu') { if (Test-Path -LiteralPath (Get-ShortcutPath $w)) { $names[$w] } })
    $ui.ShortcutStatus.Text = if ($have.Count) { 'Vorhanden: ' + ($have -join ', ') } else { 'Noch keine Verknüpfung angelegt' }
}

function Register-PflegeTask($Cfg) {
    if ($Script:IsPortable) { return 'Portabel vom Stick - kein Zeitplan auf diesem PC.' }
    if (-not $Cfg.Schedule.Enabled) {
        Unregister-ScheduledTask -TaskName $TaskName -Confirm:$false -ErrorAction SilentlyContinue
        return 'Automatische Pflege ist deaktiviert.'
    }
    $time = [datetime]::MinValue
    if (-not [datetime]::TryParseExact([string]$Cfg.Schedule.Time, 'HH:mm', [Globalization.CultureInfo]::InvariantCulture, 'None', [ref]$time)) {
        throw 'Uhrzeit bitte im Format HH:mm angeben, z.B. 03:00'
    }
    $days = @{ 'Montag' = 'Monday'; 'Dienstag' = 'Tuesday'; 'Mittwoch' = 'Wednesday'; 'Donnerstag' = 'Thursday'; 'Freitag' = 'Friday'; 'Samstag' = 'Saturday'; 'Sonntag' = 'Sunday' }
    $dow = $days[[string]$Cfg.Schedule.Day]; if (-not $dow) { $dow = 'Sunday' }
    switch ([string]$Cfg.Schedule.Frequency) {
        'Täglich'       { $trg = New-ScheduledTaskTrigger -Daily -At $time }
        'Wöchentlich'   { $trg = New-ScheduledTaskTrigger -Weekly -DaysOfWeek $dow -At $time }
        'Alle 2 Wochen' { $trg = New-ScheduledTaskTrigger -Weekly -DaysOfWeek $dow -WeeksInterval 2 -At $time }
        default         { $trg = New-ScheduledTaskTrigger -Weekly -DaysOfWeek $dow -WeeksInterval 4 -At $time }
    }
    $target = Join-Path $DataDir 'PCPflege.ps1'
    Sync-PflegeFiles
    $act = New-ScheduledTaskAction -Execute (Join-Path $env:SystemRoot 'System32\WindowsPowerShell\v1.0\powershell.exe') `
                                   -Argument ('-NoProfile -ExecutionPolicy Bypass -WindowStyle Hidden -File "{0}" -Auto' -f $target)
    $pr  = New-ScheduledTaskPrincipal -UserId 'NT AUTHORITY\SYSTEM' -LogonType ServiceAccount -RunLevel Highest
    $set = New-ScheduledTaskSettingsSet -StartWhenAvailable -AllowStartIfOnBatteries -DontStopIfGoingOnBatteries `
                                        -ExecutionTimeLimit (New-TimeSpan -Hours 8) -MultipleInstances IgnoreNew
    $set.WakeToRun = [bool]$Cfg.Schedule.WakeToRun
    Register-ScheduledTask -TaskName $TaskName -Action $act -Trigger $trg -Principal $pr -Settings $set `
        -Description 'PC-Tools: Aufräumen, Optimieren, Updates' -Force | Out-Null
    # Skript läuft als SYSTEM -> nur Admins/SYSTEM dürfen es ändern
    & icacls.exe $DataDir /inheritance:r /grant:r '*S-1-5-18:(OI)(CI)F' '*S-1-5-32-544:(OI)(CI)F' '*S-1-5-32-545:(OI)(CI)RX' | Out-Null
    return 'Zeitplan gespeichert.'
}

function Save-All([switch]$Quiet) {
    $cfg = Get-ConfigFromUi
    Save-PflegeConfig $cfg
    try {
        $msg = Register-PflegeTask $cfg
        try { $msg += Update-MonitorLogonTask $cfg } catch { $msg += ' Monitor-Aufgabe: ' + $_.Exception.Message }
        try { $msg += Register-BackupTask $cfg } catch { $msg += ' Sicherung: ' + $_.Exception.Message }
        try { $msg += Register-FbTask $cfg } catch { $msg += ' Komplettsicherung: ' + $_.Exception.Message }
        try { $msg += ' ' + (Register-FleetPollTask ([bool]($cfg.Fleet.Enabled -and $cfg.Fleet.Dir -and ($cfg.Fleet.Remote -or $cfg.Fleet.Heartbeat -or $cfg.Fleet.Watch)))) } catch { $msg += ' Fernaufträge: ' + $_.Exception.Message }
        $ui.StatusText.Text = 'Einstellungen gespeichert. ' + $msg
    } catch {
        $ui.StatusText.Text = 'Einstellungen gespeichert, Zeitplan-Fehler: ' + $_.Exception.Message
        if (-not $Quiet) { [Windows.MessageBox]::Show((T ($_.Exception.Message)), (T ('PC-Tools')), 'OK', 'Warning') | Out-Null }
    }
    Update-Overview
    return $cfg
}

# ---------------------------------------------------------------- Hintergrund-Lauf (eigener Prozess)
# Die Pflege läuft in einem eigenen, unsichtbaren PowerShell-Prozess. Schließt ein Installer
# (z.B. per Windows Restart Manager) dieses Fenster oder den Explorer, läuft die Pflege weiter.
$script:Job = $null

function Set-Busy([bool]$Busy) {
    foreach ($b in $RunButtons) { if ($ui[$b]) { $ui[$b].IsEnabled = -not $Busy } }
    $ui.BtnCancel.IsEnabled = $Busy
    if ($ui.Pulse) {
        $ui.Pulse.IsIndeterminate = $Busy
        $ui.Pulse.Visibility = if ($Busy) { 'Visible' } else { 'Collapsed' }
    }
    if ($Busy -and $script:Act) { $script:Act.LastSample = $null; $script:Act.LastActive = Get-Date; $script:Act.Info = 'startet' }
    if (-not $Busy -and $ui.ActDot) {
        $ui.ActDot.Fill = $Brush.Gray
        $ui.ActStep.Text = 'Fertig - keine Aufgabe aktiv'
        $ui.ActState.Text = ''; $ui.ActDetail.Text = ''; $ui.ActProc.Text = ''
    }
}

function Start-Run([string[]]$Parts, [switch]$Analyze, [switch]$CheckOnly, [string[]]$Apps = @(), [string[]]$WingetApps = @(), [string[]]$ChocoApps = @(), [string[]]$DirectApps = @(), [hashtable]$Job = $null) {
    if ($script:Job) { return }
    $cfg = Get-ConfigFromUi
    Save-PflegeConfig $cfg
    $runId  = Get-Date -Format 'yyyyMMdd_HHmmss'
    $runDir = Join-Path $DataDir 'Run'
    $logDir = Join-Path $DataDir 'Logs'
    New-Item $runDir, $logDir -ItemType Directory -Force | Out-Null
    Get-ChildItem $runDir -File -ErrorAction SilentlyContinue | Where-Object { $_.LastWriteTime -lt (Get-Date).AddDays(-2) } | Remove-Item -Force -ErrorAction SilentlyContinue
    $argList = @('-NoProfile', '-ExecutionPolicy', 'Bypass', '-WindowStyle', 'Hidden', '-File', ('"{0}"' -f $PSCommandPath),
                 '-Run', '-RunId', $runId, '-Parts', ($Parts -join ','))
    if ($Apps.Count) {
        $appsFile = Join-Path $runDir ('{0}.apps.txt' -f $runId)
        $Apps | Set-Content -LiteralPath $appsFile -Encoding UTF8
        $argList += @('-AppsFile', ('"{0}"' -f $appsFile))
    }
    if ($WingetApps.Count) {
        $wgFile = Join-Path $runDir ('{0}.winget.txt' -f $runId)
        $WingetApps | Set-Content -LiteralPath $wgFile -Encoding UTF8
        $argList += @('-WingetFile', ('"{0}"' -f $wgFile))
    }
    if ($ChocoApps.Count) {
        $chFile = Join-Path $runDir ('{0}.choco.txt' -f $runId)
        $ChocoApps | Set-Content -LiteralPath $chFile -Encoding UTF8
        $argList += @('-ChocoFile', ('"{0}"' -f $chFile))
    }
    if ($DirectApps.Count) {
        $dFile = Join-Path $runDir ('{0}.direct.txt' -f $runId)
        $DirectApps | Set-Content -LiteralPath $dFile -Encoding UTF8
        $argList += @('-DirectFile', ('"{0}"' -f $dFile))
    }
    if ($Job) {
        $jf = Join-Path $runDir ('{0}.job.json' -f $runId)
        $Job | ConvertTo-Json -Depth 5 | Set-Content -LiteralPath $jf -Encoding UTF8
        $argList += @('-JobFile', ('"{0}"' -f $jf))
    }
    if ($Analyze)   { $argList += '-Analyze' }
    if ($CheckOnly) { $argList += '-CheckOnly' }
    $proc = Start-HiddenPS $PSCommandPath @($argList | Select-Object -Skip 7)
    $script:Job = @{
        Proc   = $proc
        Log    = Join-Path $logDir ('PCPflege_{0}.log' -f $runId)
        Status = Join-Path $runDir ('{0}.status.json' -f $runId)
        Cancel = Join-Path $runDir ('{0}.cancel' -f $runId)
        Offset = [int64]0
        Rest   = ''
        Parts  = $Parts
    }
    $ui.Progress.Value = 0
    $ui.StatusText.Text = 'Starte ...'
    Set-Busy $true
    $ui.Tabs.SelectedItem = $ui.TabLog
}

function Read-JobLog {
    $j = $script:Job
    if (-not $j -or -not [IO.File]::Exists($j.Log)) { return }
    try {
        $fs = New-Object IO.FileStream($j.Log, [IO.FileMode]::Open, [IO.FileAccess]::Read, [IO.FileShare]'ReadWrite, Delete')
        try {
            if ($fs.Length -le $j.Offset) { return }
            [void]$fs.Seek($j.Offset, [IO.SeekOrigin]::Begin)
            $buf = New-Object byte[] ($fs.Length - $j.Offset)
            $n = $fs.Read($buf, 0, $buf.Length)
            $j.Offset += $n
        } finally { $fs.Dispose() }
        $text = $j.Rest + [Text.Encoding]::UTF8.GetString($buf, 0, $n).Replace([string][char]0xFEFF, '')
        $cut = $text.LastIndexOf("`n")
        if ($cut -lt 0) { $j.Rest = $text; return }
        $j.Rest = $text.Substring($cut + 1)
        $chunk = $text.Substring(0, $cut + 1).Replace("`r", '')
        if ($script:I18nOn) { $chunk = (@($chunk -split "`n") | ForEach-Object { T $_ }) -join "`n" }
        $ui.LogBox.AppendText($chunk)
        $ui.LogBox.ScrollToEnd()
    } catch { }
}

# ---------------------------------------------------------------- Neues Gerät: Profile
$script:ProfItems = [System.Collections.Generic.List[object]]::new()
$script:ProfCurrent = $null
function Get-ProfileItems($Prof) {
    foreach ($e in $Prof.Apps) {
        $pre = -not $e.StartsWith('-')
        $x = $e.TrimStart('-')
        if ($x.StartsWith('n:')) { [pscustomobject]@{ Src = 'Ninite'; Id = $x.Substring(2); Label = $x.Substring(2); Pre = $pre } }
        elseif ($x.StartsWith('u:')) { $p = $x.Substring(2).Split('|'); [pscustomobject]@{ Src = 'Hersteller'; Id = $p[0]; Label = $p[1]; Pre = $pre } }
        elseif ($x.StartsWith('c:')) { $p = $x.Substring(2).Split('|'); [pscustomobject]@{ Src = 'Windows'; Id = 'c:' + $p[0]; Label = $p[1]; Pre = $pre } }
        elseif ($x.StartsWith('f:')) { $p = $x.Substring(2).Split('|'); [pscustomobject]@{ Src = 'Windows'; Id = 'f:' + $p[0]; Label = $p[1]; Pre = $pre } }
        else { $p = $x.Substring(2).Split('|'); [pscustomobject]@{ Src = 'winget'; Id = $p[0]; Label = $(if ($p.Count -gt 1) { $p[1] } else { $p[0] }); Pre = $pre } }
    }
}
$script:ProfSel = [System.Collections.Generic.List[string]]::new()
function Build-Profiles {
    foreach ($prof in $DeviceProfiles) {
        $items = @(Get-ProfileItems $prof)
        $card = New-Object Windows.Controls.Border
        $card.Width = 280; $card.Height = 118; $card.Margin = '0,0,12,12'; $card.Padding = '14,12'; $card.CornerRadius = '10'
        $card.Background = (New-UiBrush 'White'); $card.BorderBrush = (New-UiBrush '#E2E7F0'); $card.BorderThickness = '1'; $card.Cursor = 'Hand'
        $card.ToolTip = '{0}: {1}' -f $prof.Name, $prof.Desc
        $g = New-Object Windows.Controls.Grid
        foreach ($w in 'Auto', '*', 'Auto') { $cd = New-Object Windows.Controls.ColumnDefinition; $cd.Width = $w; [void]$g.ColumnDefinitions.Add($cd) }
        $ic = New-Object Windows.Controls.Border
        $ic.Width = 42; $ic.Height = 42; $ic.CornerRadius = '10'; $ic.Background = (New-UiBrush $prof.Color); $ic.VerticalAlignment = 'Top'; $ic.Margin = '0,0,12,0'
        $gl = New-Object Windows.Controls.TextBlock
        $gl.FontFamily = 'Segoe MDL2 Assets'; $gl.Text = [string][char]$prof.Glyph; $gl.FontSize = 19; $gl.Foreground = (New-UiBrush '#FFFFFF')
        $gl.HorizontalAlignment = 'Center'; $gl.VerticalAlignment = 'Center'
        $ic.Child = $gl
        $sp = New-Object Windows.Controls.StackPanel
        [Windows.Controls.Grid]::SetColumn($sp, 1)
        $t = New-Object Windows.Controls.TextBlock; $t.Text = $prof.Name; $t.FontSize = 15; $t.FontWeight = 'SemiBold'; $t.Foreground = (New-UiBrush '#1F2A44')
        $d = New-Object Windows.Controls.TextBlock; $d.Text = $prof.Desc; $d.FontSize = 12; $d.Foreground = (New-UiBrush '#6B7890'); $d.TextWrapping = 'Wrap'; $d.TextTrimming = 'WordEllipsis'
        $d.Margin = '0,3,0,0'; $d.Height = 34
        $n = New-Object Windows.Controls.TextBlock
        $n.Text = ('{0} Programme, {1} vorausgewählt' -f $items.Count, @($items | Where-Object Pre).Count); $n.FontSize = 11; $n.Foreground = (New-UiBrush $prof.Color); $n.FontWeight = 'SemiBold'; $n.Margin = '0,8,0,0'
        [void]$sp.Children.Add($t); [void]$sp.Children.Add($d); [void]$sp.Children.Add($n)
        # Auswahl-Kreis oben rechts
        $ck = New-Object Windows.Controls.Border
        $ck.Width = 22; $ck.Height = 22; $ck.CornerRadius = '11'; $ck.BorderThickness = '1.5'; $ck.BorderBrush = (New-UiBrush '#C5CEDD'); $ck.Background = (New-UiBrush 'White')
        $ck.VerticalAlignment = 'Top'; $ck.Margin = '8,0,0,0'
        $cm = New-Object Windows.Controls.TextBlock; $cm.FontFamily = 'Segoe MDL2 Assets'; $cm.Text = [string][char]0xE73E; $cm.FontSize = 11; $cm.Foreground = (New-UiBrush '#FFFFFF')
        $cm.HorizontalAlignment = 'Center'; $cm.VerticalAlignment = 'Center'; $cm.Visibility = 'Hidden'
        $ck.Child = $cm
        [Windows.Controls.Grid]::SetColumn($ck, 2)
        [void]$g.Children.Add($ic); [void]$g.Children.Add($sp); [void]$g.Children.Add($ck)
        $card.Child = $g
        $card.Tag = $prof.Key
        $card.Add_MouseLeftButtonUp({ param($sender, $e) Switch-Profile ([string]$sender.Tag) })
        $card.Add_MouseEnter({ param($sender, $e) if (-not $script:ProfSel.Contains([string]$sender.Tag)) { $sender.BorderBrush = New-UiBrush '#AFC4EA' } })
        $card.Add_MouseLeave({ param($sender, $e) if (-not $script:ProfSel.Contains([string]$sender.Tag)) { $sender.BorderBrush = New-UiBrush '#E2E7F0' } })
        $prof.Card = $card; $prof.Check = $ck; $prof.CheckMark = $cm
        [void]$ui.ProfPanel.Children.Add($card)
    }
}
# Mehrere Profile kombinierbar (z.B. Büro + Business): Klick auf eine Karte wählt sie zusätzlich aus bzw. wieder ab
function Switch-Profile([string]$Key) {
    if ($script:ProfSel.Contains($Key)) { [void]$script:ProfSel.Remove($Key) } else { $script:ProfSel.Add($Key) }
    Show-ProfileApps
}
function Select-Profile([string]$Key) { $script:ProfSel.Clear(); $script:ProfSel.Add($Key); Show-ProfileApps }
function Show-ProfileApps {
    foreach ($p in $DeviceProfiles) {
        $on = $script:ProfSel.Contains($p.Key)
        $p.Card.BorderBrush = if ($on) { New-UiBrush $p.Color } else { New-UiBrush '#E2E7F0' }
        $p.Card.BorderThickness = if ($on) { '2' } else { '1' }
        $p.Card.Background = if ($on) { New-UiBrush '#F5F9FF' } else { New-UiBrush 'White' }
        $p.Check.Background = if ($on) { New-UiBrush $p.Color } else { New-UiBrush 'White' }
        $p.Check.BorderBrush = if ($on) { New-UiBrush $p.Color } else { New-UiBrush '#C5CEDD' }
        $p.CheckMark.Visibility = if ($on) { 'Visible' } else { 'Hidden' }
    }
    $old = @{}; foreach ($pi in $script:ProfItems) { $old[$pi.Key] = [bool]$pi.Check.IsChecked }
    $profs = @(foreach ($k in $script:ProfSel) { $DeviceProfiles | Where-Object { $_.Key -eq $k } | Select-Object -First 1 })
    $script:ProfCurrent = if ($profs.Count) { [pscustomobject]@{ Name = (($profs | ForEach-Object { $_.Name }) -join ' + ') } } else { $null }
    $ui.ProfTitle.Text = if ($profs.Count) { $script:ProfCurrent.Name } else { 'Bitte ein oder mehrere Profile wählen' }
    $ui.ProfDesc.Text = if ($profs.Count -eq 1) { $profs[0].Desc } elseif ($profs.Count -gt 1) { 'Kombination aus {0} Profilen - Programme, die in mehreren Profilen vorkommen, werden nur einmal installiert.' -f $profs.Count } else { 'Karten oben anklicken - ein Klick wählt ein Profil aus, ein zweiter wieder ab. Mehrere Profile lassen sich kombinieren.' }
    $ui.ProfApps.Children.Clear()
    $script:ProfItems.Clear()
    $merged = [ordered]@{}
    foreach ($prof in $profs) {
        foreach ($it in (Get-ProfileItems $prof)) {
            $key = ('{0}|{1}' -f $it.Src, $it.Id).ToLower()
            if ($merged.Contains($key)) { if ($it.Pre) { $merged[$key].Pre = $true }; $merged[$key].From += $prof.Name; continue }
            $merged[$key] = [pscustomobject]@{ Item = $it; Pre = [bool]$it.Pre; From = @($prof.Name) }
        }
    }
    foreach ($key in $merged.Keys) {
        $m = $merged[$key]; $it = $m.Item
        $cb = New-Object Windows.Controls.CheckBox
        $cb.IsChecked = if ($old.ContainsKey($key)) { $old[$key] } else { $m.Pre }
        $cb.Margin = '0,0,18,8'; $cb.Width = $(if ($it.Src -eq 'Windows') { 330 } else { 230 })
        if ($profs.Count -gt 1) { $cb.ToolTip = 'Aus: ' + ($m.From -join ', ') }
        $sp = New-Object Windows.Controls.StackPanel; $sp.Orientation = 'Horizontal'
        $l = New-Object Windows.Controls.TextBlock; $l.Text = $it.Label; $l.Foreground = (New-UiBrush '#1F2A44'); $l.FontWeight = 'SemiBold'
        $bd = New-Object Windows.Controls.Border; $bd.CornerRadius = '4'; $bd.Padding = '5,0'; $bd.Margin = '6,0,0,0'; $bd.VerticalAlignment = 'Center'
        $bd.Background = switch ($it.Src) { 'Ninite' { New-UiBrush '#E6F0FF' } 'winget' { New-UiBrush '#EDE9FE' } 'Windows' { New-UiBrush '#DCFCE7' } default { New-UiBrush '#FFEDD5' } }
        $bt = New-Object Windows.Controls.TextBlock; $bt.Text = $it.Src; $bt.FontSize = 10; $bt.Foreground = (New-UiBrush '#475569')
        $bd.Child = $bt
        [void]$sp.Children.Add($l); [void]$sp.Children.Add($bd)
        $cb.Content = $sp
        $cb.Add_Click({ Update-ProfInfo })
        [void]$ui.ProfApps.Children.Add($cb)
        $script:ProfItems.Add([pscustomobject]@{ Item = $it; Check = $cb; Key = $key })
    }
    Update-ProfInfo
}
function Update-ProfInfo {
    $sel = @($script:ProfItems | Where-Object { $_.Check.IsChecked })
    $ui.ProfInfo.Text = if ($script:ProfCurrent) { '{0} von {1} Programmen ausgewählt' -f $sel.Count, $script:ProfItems.Count } else { '' }
    $ui.BtnProfInstall.Content = if ($sel.Count) { 'Profil installieren ({0})' -f $sel.Count } else { 'Profil installieren' }
}
function Install-SelectedProfile {
    if (-not $script:ProfCurrent) { return }
    if ($script:Job) { [Windows.MessageBox]::Show((T ('Es läuft bereits eine Aufgabe.')), (T ('PC-Tools')), 'OK', 'Information') | Out-Null; return }
    $sel = @($script:ProfItems | Where-Object { $_.Check.IsChecked } | ForEach-Object { $_.Item })
    if (-not $sel.Count) { [Windows.MessageBox]::Show((T ('Bitte mindestens ein Programm auswählen.')), (T ('PC-Tools')), 'OK', 'Information') | Out-Null; return }
    $nin = @($sel | Where-Object { $_.Src -eq 'Ninite' } | ForEach-Object { $_.Id })
    $wg  = @($sel | Where-Object { $_.Src -eq 'winget' } | ForEach-Object { $_.Id })
    $dir = @($sel | Where-Object { $_.Src -eq 'Hersteller' } | ForEach-Object { $_.Id })
    $win = @($sel | Where-Object { $_.Src -eq 'Windows' } | ForEach-Object { $_.Id })
    if ($nin.Count -and -not (Get-NinitePathGui)) {
        $r = [Windows.MessageBox]::Show((T ('NinitePro.exe wurde nicht gefunden - die Ninite-Programme werden übersprungen. Trotzdem fortfahren?')), (T ('PC-Tools')), 'YesNo', 'Warning')
        if ($r -ne 'Yes') { return }
        $nin = @()
    }
    $msg = "Profil '{0}' installieren ({2} Programme)?`n`n{1}" -f $script:ProfCurrent.Name, (($sel | ForEach-Object { '- ' + $_.Label }) -join "`n"), $sel.Count
    if ([Windows.MessageBox]::Show((T ($msg)), (T ('PC-Tools - Neues Gerät')), 'YesNo', 'Question') -ne 'Yes') { return }
    $parts = @(); if ($nin.Count) { $parts += 'NiniteInstall' }; if ($wg.Count) { $parts += 'WingetInstall' }; if ($dir.Count) { $parts += 'DirectInstall' }; if ($win.Count) { $parts += 'WinFeatures' }
    Start-Run -Parts $parts -Apps $nin -WingetApps $wg -DirectApps $dir -Job $(if ($win.Count) { @{ WinFeatures = $win } } else { $null })
}

# ---------------------------------------------------------------- Virenschutz
function Get-AvProducts {
    @(Get-CimInstance -Namespace 'root/SecurityCenter2' -ClassName AntiVirusProduct -ErrorAction SilentlyContinue | ForEach-Object {
        $st = [int]$_.productState
        [pscustomobject]@{
            Name   = [string]$_.displayName
            Active = (($st -shr 12) -band 0xF) -in 1, 3
            Exe    = [string]$_.pathToSignedProductExe
            IsMs   = [string]$_.displayName -match 'Defender|Microsoft'
        }
    })
}
function Get-AvExclusionPaths {
    $p = @($DataDir)
    if ($PSScriptRoot -and ($PSScriptRoot.TrimEnd('\') -ne $DataDir.TrimEnd('\'))) { $p += $PSScriptRoot }
    return $p
}
function Update-AvStatus {
    $av = @(Get-AvProducts)
    # Security Center meldet nichts (kommt bei Insider-Builds vor): Defender direkt fragen
    if (-not $av.Count) { try { $mp = Get-MpComputerStatus -ErrorAction Stop; if ($mp.AntivirusEnabled) { $av = @([pscustomobject]@{ Name = 'Microsoft Defender Antivirus'; Active = [bool]$mp.RealTimeProtectionEnabled; Exe = ''; IsMs = $true }) } } catch { } }
    $third = @($av | Where-Object { -not $_.IsMs })
    $active = @($av | Where-Object Active)
    $ui.AvPaths.Text = (Get-AvExclusionPaths) -join [Environment]::NewLine
    if (-not $av.Count) { $ui.AvStatus.Text = 'Kein Virenscanner gemeldet'; $ui.InfoAv.Text = 'unbekannt'; return }
    $ui.AvStatus.Text = 'Erkannt: ' + (($av | ForEach-Object { '{0} ({1})' -f $_.Name, $(if ($_.Active) { 'aktiv' } else { 'passiv' }) }) -join ', ')
    if ($third.Count) {
        $n = ($third | Select-Object -First 1).Name
        $ui.AvHint.Text = ('{0} kann Programme wie diese Pflege (PowerShell, Installer, Treiber-Tools) fälschlich blockieren oder Dateien löschen. Bitte in {0} die beiden Ordner unten als Ausnahme (Dateien und Ordner ausschließen) eintragen - danach laufen Updates und Installationen störungsfrei. Bei Panda: Panda öffnen > Einstellungen > Antivirus > Ausschlüsse > Dateien/Ordner hinzufügen. Gelöschte Dateien lassen sich unter Quarantäne wiederherstellen.' -f $n)
        $ui.InfoAv.Text = ('{0} - bitte Ausnahmen eintragen (Einstellungen > Virenschutz)' -f (($active | Select-Object -First 1).Name))
        $ui.InfoAv.Foreground = $Brush.Orange
    } else {
        $ui.AvHint.Text = 'Microsoft Defender ist aktiv - die Ausnahmen lassen sich mit einem Klick eintragen.'
        $ui.InfoAv.Text = ($active | Select-Object -First 1).Name
    }
}

# ---------------------------------------------------------------- Desktop aufräumen
$script:DeskRows = [System.Collections.Generic.List[object]]::new()
$DeskCats = [ordered]@{
    'Dokumente'  = 'pdf|docx?|xlsx?|pptx?|odt|ods|odp|rtf|txt|csv|md|xps|epub'
    'Bilder'     = 'jpe?g|png|gif|bmp|tiff?|webp|heic|svg|ico|raw|cr2|nef|psd|xcf'
    'Videos'     = 'mp4|mkv|avi|mov|wmv|webm|m4v|mpe?g|flv'
    'Musik'      = 'mp3|wav|flac|m4a|aac|ogg|wma|opus'
    'Archive'    = 'zip|rar|7z|tar|gz|bz2|xz|iso|img|cab'
    'Installer'  = 'exe|msi|msix|msixbundle|appx|appxbundle'
    '3D-Druck'   = 'stl|3mf|obj|gcode|step|stp|f3d|scad|amf|ply'
    'Skripte'    = 'ps1|bat|cmd|vbs|py|js|sh|reg|json|xml|ini|cfg|yaml|yml|log'
}
function Get-DeskCategory($item) {
    if ($item.PSIsContainer) { return 'Ordner' }
    $ext = $item.Extension.TrimStart('.').ToLower()
    if ($ext -in 'lnk', 'url', 'website') { return 'Verknüpfungen' }
    foreach ($k in $DeskCats.Keys) { if ($ext -match ('^(' + $DeskCats[$k] + ')$')) { return $k } }
    return 'Sonstiges'
}
function Get-DeskPlan($Cfg) {
    $d = $Cfg.Desk
    $desk = [Environment]::GetFolderPath('Desktop')
    $pub  = [Environment]::GetFolderPath('CommonDesktopDirectory')
    $oldName = if ([string]$d.OldFolder) { [string]$d.OldFolder } else { '_Alt' }
    $oldRoot = Join-Path $desk $oldName
    $ablage  = Join-Path $desk 'Ablage'
    $oldDay  = Join-Path $oldRoot (Get-Date -Format 'yyyy-MM-dd')
    $limit   = (Get-Date).AddDays(-[math]::Max(1, [int]$d.OlderDays))
    $shell   = New-Object -ComObject WScript.Shell
    $seen    = @{}
    $plan    = [System.Collections.Generic.List[object]]::new()
    $sources = @(@{ Path = $desk; Public = $false })
    if ($d.IncludePublic -and $pub -and (Test-Path -LiteralPath $pub)) { $sources += @{ Path = $pub; Public = $true } }
    # Mehrere Versionen desselben Programms (z.B. Blender 4.2, 4.5, 5.1): nur die neueste bleibt auf dem Desktop
    $verLosers = @{}
    if ($d.MoveOldVersions) {
        $cands = foreach ($src in $sources) {
            foreach ($f in @(Get-ChildItem -LiteralPath $src.Path -Filter '*.lnk' -Force -ErrorAction SilentlyContinue)) {
                $tp = ''; try { $tp = [string]$shell.CreateShortcut($f.FullName).TargetPath } catch { }
                if (-not $tp -or -not (Test-Path -LiteralPath $tp -PathType Leaf -ErrorAction SilentlyContinue)) { continue }
                $base = ($f.BaseName -replace '[\s_\-]*\(?v?\d+(\.\d+)+\)?(\s*(lts|beta|x64|64-?bit))?\s*$', '').Trim().ToLower()
                $ver = $null
                if ($f.BaseName -match '(\d+(?:\.\d+)+)') { $ver = $Matches[1] }
                elseif ((Split-Path $tp -Parent) -match '(\d+(?:\.\d+)+)[^\\]*$') { $ver = $Matches[1] }
                else { try { $pv = (Get-Item -LiteralPath $tp).VersionInfo.ProductVersion; if ($pv -match '^(\d+(?:\.\d+)+)') { $ver = $Matches[1] } } catch { } }
                $v = $null; if ($ver) { try { $v = [version]$ver } catch { } }
                if ($v -and $base) { [pscustomobject]@{ Path = $f.FullName; Base = $base; Ver = $v; Name = $f.BaseName } }
            }
        }
        foreach ($grp in @($cands | Group-Object Base | Where-Object Count -gt 1)) {
            $best = $grp.Group | Sort-Object Ver -Descending | Select-Object -First 1
            foreach ($c in $grp.Group) { if ($c.Ver -lt $best.Ver) { $verLosers[$c.Path] = $best.Name } }
        }
    }
    foreach ($src in $sources) {
        $items = @(Get-ChildItem -LiteralPath $src.Path -Force -ErrorAction SilentlyContinue | Where-Object {
            $_.Name -ne 'desktop.ini' -and $_.Name -ne 'PC-Tools.lnk' -and $_.Name -ne 'PC-Pflege.lnk' -and $_.FullName -ne $oldRoot -and $_.FullName -ne $ablage -and
            -not ($_.Attributes -band [IO.FileAttributes]::System) -and -not ($_.Attributes -band [IO.FileAttributes]::Hidden -and $_.Name -notlike '~$*')
        } | Sort-Object Name)
        foreach ($it in $items) {
            $cat = Get-DeskCategory $it
            $reason = $null; $target = $null; $pre = $true
            if ($cat -eq 'Verknüpfungen' -and $it.Extension -eq '.lnk') {
                $tp = ''; $ar = ''
                try { $sc = $shell.CreateShortcut($it.FullName); $tp = [string]$sc.TargetPath; $ar = [string]$sc.Arguments } catch { }
                $key = ($tp + '|' + $ar).ToLower()
                if ($tp -and $d.MoveBroken -and -not $tp.StartsWith('\\') -and $tp -notmatch '^[a-z]+:(?!\\)' -and -not (Test-Path -LiteralPath $tp)) { $reason = 'Verknüpfung ins Leere' }
                elseif ($tp -and $d.MoveDuplicates -and $seen.ContainsKey($key)) { $reason = ('Doppelt (wie {0})' -f $seen[$key]) }
                elseif ($verLosers.ContainsKey($it.FullName)) { $reason = ('Ältere Version (neueste: {0})' -f $verLosers[$it.FullName]) }
                if ($tp -and -not $seen.ContainsKey($key)) { $seen[$key] = $it.BaseName }
            }
            elseif ($src.Public) { continue }
            elseif ($d.MoveTemp -and ($it.Name -like '~$*' -or $it.Extension -match '^\.(tmp|temp|bak|old|part|crdownload|download|partial)$')) { $reason = 'Temporäre Datei' }
            elseif ($d.MoveInstallers -and $cat -eq 'Installer') { $reason = 'Installationsdatei' }
            elseif ($d.MoveEmpty -and $it.PSIsContainer -and -not (Get-ChildItem -LiteralPath $it.FullName -Force -ErrorAction SilentlyContinue | Select-Object -First 1)) { $reason = 'Leerer Ordner' }
            elseif ($d.MoveOld -and $cat -ne 'Verknüpfungen' -and $it.LastWriteTime -lt $limit) { $reason = ('Seit {0} Tagen unverändert' -f [int]((Get-Date) - $it.LastWriteTime).TotalDays) }
            if ($reason) { $target = Join-Path $oldDay $cat }
            elseif ($d.SortRest -and -not $src.Public -and $cat -notin 'Verknüpfungen', 'Ordner') { $reason = 'Einsortieren'; $target = Join-Path $ablage $cat }
            if (-not $target) { continue }
            $size = if ($it.PSIsContainer) { $null } else { $it.Length }
            $plan.Add([pscustomobject]@{ Item = $it; Name = $(if ($src.Public) { $it.Name + '  (öffentlich)' } else { $it.Name }); Cat = $cat; Reason = $reason; Target = $target; Pre = $pre; Size = $size })
        }
    }
    [void][Runtime.InteropServices.Marshal]::ReleaseComObject($shell)
    return , $plan
}
function Show-DeskPlan($Plan) {
    $ui.DeskList.Children.Clear()
    $script:DeskRows.Clear()
    $desk = [Environment]::GetFolderPath('Desktop')
    foreach ($p in $Plan) {
        $g = New-Object Windows.Controls.Grid
        $g.Margin = '0,3'
        foreach ($w in 30, -1, 210, 200, 90, 70) {
            $c = New-Object Windows.Controls.ColumnDefinition
            if ($w -gt 0) { $c.Width = $w }
            [void]$g.ColumnDefinitions.Add($c)
        }
        $cb = New-Object Windows.Controls.CheckBox; $cb.IsChecked = $p.Pre; $cb.VerticalAlignment = 'Center'
        $cb.Add_Click({ Update-DeskInfo })
        $nm = New-Object Windows.Controls.TextBlock; $nm.Text = $p.Name; $nm.Foreground = (New-UiBrush '#1F2A44'); $nm.TextTrimming = 'CharacterEllipsis'; $nm.ToolTip = $p.Item.FullName
        $rs = New-Object Windows.Controls.TextBlock; $rs.Text = $p.Reason; $rs.TextTrimming = 'CharacterEllipsis'
        $rs.Foreground = if ($p.Reason -eq 'Einsortieren') { $Brush.Gray } else { $Brush.Orange }
        $tg = New-Object Windows.Controls.TextBlock; $tg.Text = $p.Target.Replace($desk, 'Desktop'); $tg.Foreground = (New-UiBrush '#6B7890'); $tg.TextTrimming = 'CharacterEllipsis'; $tg.ToolTip = $p.Target
        $dt = New-Object Windows.Controls.TextBlock; $dt.Text = $p.Item.LastWriteTime.ToString('dd.MM.yyyy'); $dt.Foreground = (New-UiBrush '#6B7890')
        $sz = New-Object Windows.Controls.TextBlock; $sz.TextAlignment = 'Right'; $sz.Foreground = (New-UiBrush '#6B7890')
        $sz.Text = if ($null -eq $p.Size) { '' } elseif ($p.Size -ge 1MB) { '{0:N1} MB' -f ($p.Size / 1MB) } else { '{0:N0} KB' -f [math]::Ceiling($p.Size / 1KB) }
        $i = 0
        foreach ($el in $cb, $nm, $rs, $tg, $dt, $sz) { [Windows.Controls.Grid]::SetColumn($el, $i); [void]$g.Children.Add($el); $i++ }
        [void]$ui.DeskList.Children.Add($g)
        $script:DeskRows.Add([pscustomobject]@{ Plan = $p; Check = $cb })
    }
    Update-DeskInfo
}
function Update-DeskInfo {
    $all = $script:DeskRows.Count
    if (-not $all) { $ui.DeskInfo.Text = 'Der Desktop ist aufgeräumt - nichts zu tun.'; $ui.BtnDeskRun.IsEnabled = $false; return }
    $sel = @($script:DeskRows | Where-Object { $_.Check.IsChecked })
    $old = @($sel | Where-Object { $_.Plan.Reason -ne 'Einsortieren' }).Count
    $ui.DeskInfo.Text = ('{0} von {1} ausgewählt: {2} in den Alt-Ordner, {3} einsortieren' -f $sel.Count, $all, $old, ($sel.Count - $old))
    $ui.BtnDeskRun.IsEnabled = [bool]$sel.Count
}
function Get-FreeTargetPath([string]$Dir, [string]$Name) {
    $p = Join-Path $Dir $Name
    if (-not (Test-Path -LiteralPath $p)) { return $p }
    $base = [IO.Path]::GetFileNameWithoutExtension($Name); $ext = [IO.Path]::GetExtension($Name)
    for ($n = 2; $n -lt 1000; $n++) { $p = Join-Path $Dir ('{0} ({1}){2}' -f $base, $n, $ext); if (-not (Test-Path -LiteralPath $p)) { return $p } }
    return $null
}
function Invoke-DeskCleanup {
    $sel = @($script:DeskRows | Where-Object { $_.Check.IsChecked } | ForEach-Object { $_.Plan })
    if (-not $sel.Count) { return }
    if ([Windows.MessageBox]::Show((T (('{0} Element(e) verschieben? Es wird nichts gelöscht, alles lässt sich rückgängig machen.' -f $sel.Count))), (T ('PC-Tools - Desktop aufräumen')), 'YesNo', 'Question') -ne 'Yes') { return }
    $moves = [System.Collections.Generic.List[object]]::new()
    $errors = 0
    $window.Cursor = 'Wait'
    foreach ($p in $sel) {
        try {
            New-Item -Path $p.Target -ItemType Directory -Force | Out-Null
            $dst = Get-FreeTargetPath $p.Target $p.Item.Name
            Move-Item -LiteralPath $p.Item.FullName -Destination $dst -Force -ErrorAction Stop
            $moves.Add([pscustomobject]@{ From = $p.Item.FullName; To = $dst })
        } catch { $errors++ }
    }
    $window.Cursor = $null
    # Hinweisdatei im Alt-Ordner
    $d = (Get-ConfigFromUi).Desk
    $oldRoot = Join-Path ([Environment]::GetFolderPath('Desktop')) $(if ([string]$d.OldFolder) { [string]$d.OldFolder } else { '_Alt' })
    if (Test-Path -LiteralPath $oldRoot) {
        $readme = Join-Path $oldRoot 'LIES MICH.txt'
        if (-not (Test-Path -LiteralPath $readme)) {
            "Hier legt PC-Tools Dinge ab, die vom Desktop entfernt wurden (sortiert nach Datum und Art).`r`nBitte in Ruhe prüfen und nicht mehr Benötigtes löschen.`r`nRückgängig machen: PC-Tools > Desktop aufräumen > Rückgängig." | Set-Content -LiteralPath $readme -Encoding UTF8
        }
    }
    $undoDir = Join-Path $DataDir 'Desktop'
    New-Item $undoDir -ItemType Directory -Force | Out-Null
    if ($moves.Count) { $moves | ConvertTo-Json -Depth 3 | Set-Content -LiteralPath (Join-Path $undoDir ('undo_{0:yyyyMMdd_HHmmss}.json' -f (Get-Date))) -Encoding UTF8 }
    $ui.StatusText.Text = ('Desktop aufgeräumt: {0} verschoben{1}' -f $moves.Count, $(if ($errors) { ", $errors nicht möglich (Datei geöffnet?)" } else { '' }))
    Show-DeskPlan (Get-DeskPlan (Get-ConfigFromUi))
    if ($d.ArrangeAfterClean) { Start-Sleep -Seconds 2; Invoke-DeskArrangeGui }
}
function Undo-DeskCleanup {
    $undoDir = Join-Path $DataDir 'Desktop'
    $last = Get-ChildItem $undoDir -Filter 'undo_*.json' -ErrorAction SilentlyContinue | Sort-Object Name -Descending | Select-Object -First 1
    if (-not $last) { [Windows.MessageBox]::Show((T ('Es gibt nichts rückgängig zu machen.')), (T ('PC-Tools'))) | Out-Null; return }
    $moves = @(Get-Content -LiteralPath $last.FullName -Raw -Encoding UTF8 | ConvertFrom-Json)
    if ([Windows.MessageBox]::Show((T (('Letzte Aufräumaktion vom {0:dd.MM.yyyy HH:mm} rückgängig machen ({1} Elemente)?' -f $last.LastWriteTime, $moves.Count))), (T ('PC-Tools')), 'YesNo', 'Question') -ne 'Yes') { return }
    $ok = 0
    foreach ($m in $moves) {
        if ((Test-Path -LiteralPath $m.To) -and -not (Test-Path -LiteralPath $m.From)) {
            try { Move-Item -LiteralPath $m.To -Destination $m.From -ErrorAction Stop; $ok++ } catch { }
        }
    }
    Remove-Item -LiteralPath $last.FullName -Force
    foreach ($dir in @($moves | ForEach-Object { Split-Path $_.To -Parent } | Select-Object -Unique)) {
        if ((Test-Path -LiteralPath $dir) -and -not (Get-ChildItem -LiteralPath $dir -Force -ErrorAction SilentlyContinue | Where-Object { $_.Name -ne 'desktop.ini' } | Select-Object -First 1)) { Remove-Item -LiteralPath $dir -Recurse -Force -ErrorAction SilentlyContinue }
    }
    $ui.StatusText.Text = ('{0} von {1} Elementen zurück auf den Desktop verschoben.' -f $ok, $moves.Count)
    Show-DeskPlan (Get-DeskPlan (Get-ConfigFromUi))
}


# ---------------------------------------------------------------- Desktop-Symbole anordnen (Oberfläche)
function Get-DeskGroupText($Groups) { ($Groups | ForEach-Object { '{0} ({1}): {2}' -f $_.Name, $_.Items.Count, (($_.Items | ForEach-Object Name) -join ', ') }) -join "`n`n" }
function Get-DeskGroupShort($Groups) { ($Groups | ForEach-Object { '{0} {1}' -f $_.Name, $_.Items.Count }) -join '  ·  ' }
function Invoke-GuiAutoArrangeCheck([scriptblock]$Action) {
    try { return (& $Action $false) }
    catch {
        if ($_.Exception.Message -ne 'AUTOARRANGE') { throw }
        $window.Cursor = $null
        $q = "Auf dem Desktop ist 'Symbole automatisch anordnen' eingeschaltet - damit würde Windows jede Anordnung sofort wieder zurücksetzen.`n`nAusschalten und den Explorer kurz neu starten? (Offene Explorer-Fenster werden geschlossen.)"
        if ([Windows.MessageBox]::Show((T ($q)), (T ('PC-Tools')), 'YesNo', 'Question') -ne 'Yes') { return $null }
        $window.Cursor = 'Wait'
        return (& $Action $true)
    }
}
function Invoke-DeskArrangeGui {
    $cfg = Get-ConfigFromUi
    $window.Cursor = 'Wait'
    try {
        $gap = [bool]$cfg.Desk.ArrangeGap
        $lay = [string]$cfg.Desk.ArrangeLayout
        $r = Invoke-GuiAutoArrangeCheck { param($allow) Invoke-DeskArrange -Gap:$gap -AllowRestart:$allow -Layout $lay }
        if (-not $r) { return }
        $note = if ($r.Layout -eq 'Zeilen') { $(if ($r.Gap) { ', in Zeilen oben entlang mit Abstand zwischen den Gruppen' } else { ', in Zeilen oben entlang' }) } elseif (-not $r.OwnColumns) { ' - zu viele Symbole für eine eigene Spalte je Kategorie, daher fortlaufend sortiert' } elseif ($r.Gap) { ', mit Abstand zwischen den Kategorien' } else { ', jede Kategorie in eigener Spalte' }
        $ui.DeskArrInfo.Text = ('Angeordnet: {0} Symbole in {1} Kategorien{2}.' -f $r.Count, $r.Groups.Count, $note)
        $ui.DeskArrInfo.ToolTip = Get-DeskGroupText $r.Groups
        $ui.StatusText.Text = 'Desktop-Symbole nach Kategorien angeordnet.'
    } catch { [Windows.MessageBox]::Show((T ('Anordnen fehlgeschlagen: ' + $_.Exception.Message)), (T ('PC-Tools')), 'OK', 'Warning') | Out-Null }
    finally { $window.Cursor = $null }
}
function Show-DeskArrangePreview {
    $window.Cursor = 'Wait'
    try {
        $plan = Get-DeskArrangePlan
        $ui.DeskArrInfo.Text = 'Vorschau: ' + (Get-DeskGroupShort $plan.Groups)
        $ui.DeskArrInfo.ToolTip = Get-DeskGroupText $plan.Groups
        $window.Cursor = $null
        [Windows.MessageBox]::Show((T (("So werden die {0} Symbole von links nach rechts angeordnet:`n`n{1}" -f $plan.Count, (Get-DeskGroupText $plan.Groups)))), (T ('PC-Tools - Vorschau')), 'OK', 'Information') | Out-Null
    } catch { [Windows.MessageBox]::Show((T ('Vorschau fehlgeschlagen: ' + $_.Exception.Message)), (T ('PC-Tools')), 'OK', 'Warning') | Out-Null }
    finally { $window.Cursor = $null }
}

# ---------------------------------------------------------------- Verknüpfungen in Kategorie-Ordner einsortieren
function Get-DeskFolderPlan($Cfg) {
    $d = $Cfg.Desk
    $desk = [Environment]::GetFolderPath('Desktop'); $pub = [Environment]::GetFolderPath('CommonDesktopDirectory')
    $min = [math]::Max(1, [int]$d.FolderMin)
    $sources = @($desk); if ($d.IncludePublic -and $pub -and (Test-Path -LiteralPath $pub)) { $sources += $pub }
    $shell = New-Object -ComObject WScript.Shell
    $items = foreach ($src in $sources) {
        foreach ($it in @(Get-ChildItem -LiteralPath $src -File -Force -ErrorAction SilentlyContinue | Where-Object { $_.Extension -in '.lnk', '.url', '.website', '.appref-ms' -and -not ($_.Attributes -band [IO.FileAttributes]::Hidden) })) {
            $info = [pscustomobject]@{ Name = $it.Name; Path = $it.FullName; IsFolder = $false; Ext = $it.Extension.ToLower(); IsShortcut = $true; Target = ''; Args = ''; TargetIsFolder = $false }
            if ($info.Ext -eq '.lnk') {
                try { $sc = $shell.CreateShortcut($it.FullName); $info.Target = [string]$sc.TargetPath; $info.Args = [string]$sc.Arguments } catch { }
                if ($info.Target -and -not $info.Target.EndsWith('.exe') -and (Test-Path -LiteralPath $info.Target -PathType Container -ErrorAction SilentlyContinue)) { $info.TargetIsFolder = $true }
            } elseif ($info.Ext -eq '.url') {
                try { $u = (Get-Content -LiteralPath $it.FullName -ErrorAction Stop | Where-Object { $_ -like 'URL=*' } | Select-Object -First 1); if ($u) { $info.Target = $u.Substring(4) } } catch { }
            }
            $g = Get-DeskGroup $it.BaseName $info
            if ($g -in 'Windows', 'Ordner') { continue }
            [pscustomobject]@{ Item = $it; Group = $g }
        }
    }
    try { [void][Runtime.InteropServices.Marshal]::ReleaseComObject($shell) } catch { }
    $plan = foreach ($grp in @($items | Group-Object Group)) {
        $target = Join-Path $desk (Get-DeskFolderName $grp.Name)
        if ($grp.Count -lt $min -and -not (Test-Path -LiteralPath $target)) { continue }
        foreach ($x in $grp.Group) { [pscustomobject]@{ Item = $x.Item; Group = $grp.Name; Target = $target } }
    }
    return @($plan | Sort-Object { [array]::IndexOf($DeskGroupOrder, $_.Group) }, { $_.Item.Name })
}
function Invoke-DeskFolders {
    $cfg = Get-ConfigFromUi; Save-PflegeConfig $cfg
    $window.Cursor = 'Wait'
    try { $plan = @(Get-DeskFolderPlan $cfg) } finally { $window.Cursor = $null }
    if (-not $plan.Count) { [Windows.MessageBox]::Show((T ('Keine Verknüpfungen zum Einsortieren gefunden.')), (T ('PC-Tools'))) | Out-Null; return }
    $groups = @($plan | Group-Object Group)
    $txt = ($groups | ForEach-Object { '{0} ({1}): {2}' -f (Get-DeskFolderName $_.Name), $_.Count, (($_.Group | ForEach-Object { $_.Item.BaseName }) -join ', ') }) -join "`n`n"
    if (-not (Confirm-Ui ("{0} Verknüpfungen werden in {1} Ordner auf dem Desktop einsortiert:`n`n{2}`n`nWindows-Symbole, PC-Tools, Ordner und Dateien bleiben auf dem Desktop. Mit 'Rückgängig' lässt sich alles zurückholen.`n`nJetzt einsortieren?" -f $plan.Count, $groups.Count, $txt))) { return }
    $moves = [System.Collections.Generic.List[object]]::new(); $errors = 0
    $window.Cursor = 'Wait'
    foreach ($p in $plan) {
        try {
            New-Item -Path $p.Target -ItemType Directory -Force | Out-Null
            $dst = Get-FreeTargetPath $p.Target $p.Item.Name
            Move-Item -LiteralPath $p.Item.FullName -Destination $dst -Force -ErrorAction Stop
            $moves.Add([pscustomobject]@{ From = $p.Item.FullName; To = $dst })
        } catch { $errors++ }
    }
    $window.Cursor = $null
    $undoDir = Join-Path $DataDir 'Desktop'; New-Item $undoDir -ItemType Directory -Force | Out-Null
    if ($moves.Count) { $moves | ConvertTo-Json -Depth 3 | Set-Content -LiteralPath (Join-Path $undoDir ('undo_{0:yyyyMMdd_HHmmss}.json' -f (Get-Date))) -Encoding UTF8 }
    $ui.StatusText.Text = ('{0} Verknüpfungen in {1} Ordner einsortiert{2}' -f $moves.Count, $groups.Count, $(if ($errors) { ", $errors nicht möglich" } else { '' }))
    $ui.DeskArrInfo.Text = $ui.StatusText.Text
    if ($cfg.Desk.ArrangeAfterClean) { Start-Sleep -Seconds 2; Invoke-DeskArrangeGui }
}

# ---------------------------------------------------------------- Monitore
$script:MonCur = @()
function Show-MonitorCanvas {
    $c = $ui.MonCanvas
    $c.Children.Clear()
    $mons = @($script:MonCur)
    if (-not $mons.Count) { return }
    $w = $c.ActualWidth; if ($w -lt 60) { $w = 640 }
    $h = 170
    $minX = ($mons | ForEach-Object { $_.X } | Measure-Object -Minimum).Minimum
    $minY = ($mons | ForEach-Object { $_.Y } | Measure-Object -Minimum).Minimum
    $maxX = ($mons | ForEach-Object { $_.X + $_.Width } | Measure-Object -Maximum).Maximum
    $maxY = ($mons | ForEach-Object { $_.Y + $_.Height } | Measure-Object -Maximum).Maximum
    $sc = [math]::Min(($w - 10) / [math]::Max(1, $maxX - $minX), ($h - 10) / [math]::Max(1, $maxY - $minY))
    $offX = ($w - ($maxX - $minX) * $sc) / 2; $offY = ($h - ($maxY - $minY) * $sc) / 2
    foreach ($m in $mons) {
        $b = New-Object Windows.Controls.Border
        $b.Width = [math]::Max(20, $m.Width * $sc - 4); $b.Height = [math]::Max(16, $m.Height * $sc - 4)
        $b.CornerRadius = '6'
        $b.Background = if ($m.Primary) { New-UiBrush '#2D7FF9' } else { New-UiBrush '#5B6B8C' }
        $t = New-Object Windows.Controls.TextBlock
        $t.Text = "{0}{1}`n{2}`n{3}x{4}" -f $m.Display, $(if ($m.Primary) { '  ★' } else { '' }), $m.Name, $m.Width, $m.Height
        $t.Foreground = New-UiBrush '#FFFFFF'; $t.FontSize = 11; $t.TextAlignment = 'Center'; $t.TextWrapping = 'Wrap'
        $t.VerticalAlignment = 'Center'; $t.HorizontalAlignment = 'Center'; $t.Margin = '4'
        $b.Child = $t
        $b.ToolTip = Get-MonitorText $m
        [Windows.Controls.Canvas]::SetLeft($b, $offX + ($m.X - $minX) * $sc + 2)
        [Windows.Controls.Canvas]::SetTop($b, $offY + ($m.Y - $minY) * $sc + 2)
        [void]$c.Children.Add($b)
    }
}
function Build-MonitorPage {
    try { $script:MonCur = @(Get-MonitorLayout) } catch { $script:MonCur = @(); $ui.StatusText.Text = 'Monitore konnten nicht gelesen werden: ' + $_.Exception.Message }
    $ui.MonCurrent.Children.Clear()
    foreach ($m in $script:MonCur) {
        $t = New-Object Windows.Controls.TextBlock
        $t.Text = Get-MonitorText $m
        $t.Foreground = New-UiBrush '#1F2A44'; $t.Margin = '0,2'
        if ($m.Primary) { $t.FontWeight = 'SemiBold' }
        [void]$ui.MonCurrent.Children.Add($t)
    }
    Show-MonitorCanvas
    # gespeicherte Profile
    $keep = if ($ui.Monitor_AutoProfile.SelectedItem) { [string]$ui.Monitor_AutoProfile.SelectedItem.Content } else { '' }
    $ui.Monitor_AutoProfile.Items.Clear()
    $ui.MonList.Children.Clear()
    $profiles = @(Get-MonitorProfiles)
    if (-not $profiles.Count) {
        $t = New-Object Windows.Controls.TextBlock
        $t.Text = 'Noch keine Profile. Monitore wie gewünscht anordnen (Windows-Einstellungen > System > Bildschirm), dann oben einen Namen eingeben und speichern.'
        $t.Foreground = New-UiBrush '#6B7890'; $t.TextWrapping = 'Wrap'
        [void]$ui.MonList.Children.Add($t)
    }
    foreach ($p in $profiles) {
        $ci = New-Object Windows.Controls.ComboBoxItem; $ci.Content = [string]$p.Name
        [void]$ui.Monitor_AutoProfile.Items.Add($ci)
        if ([string]$p.Name -eq $keep) { $ui.Monitor_AutoProfile.SelectedItem = $ci }
        $g = New-Object Windows.Controls.Grid; $g.Margin = '0,6'
        foreach ($wd in -1, 0) { $cd = New-Object Windows.Controls.ColumnDefinition; if ($wd -eq 0) { $cd.Width = 'Auto' }; [void]$g.ColumnDefinitions.Add($cd) }
        $sp = New-Object Windows.Controls.StackPanel
        $n = New-Object Windows.Controls.TextBlock; $n.Text = [string]$p.Name; $n.FontWeight = 'SemiBold'; $n.FontSize = 14; $n.Foreground = New-UiBrush '#1F2A44'
        $d = New-Object Windows.Controls.TextBlock; $d.Text = ((@($p.Monitors) -join "`n") + "`nGespeichert: " + $p.Created); $d.Foreground = New-UiBrush '#6B7890'; $d.FontSize = 12; $d.TextWrapping = 'Wrap'
        [void]$sp.Children.Add($n); [void]$sp.Children.Add($d)
        $bp = New-Object Windows.Controls.StackPanel; $bp.Orientation = 'Horizontal'; $bp.VerticalAlignment = 'Top'
        [Windows.Controls.Grid]::SetColumn($bp, 1)
        foreach ($def in @(@('Anwenden', 'Apply', $false), @('Verknüpfung auf Desktop', 'Link', $true), @('Löschen', 'Del', $true))) {
            $b = New-Object Windows.Controls.Button
            $b.Content = $def[0]; $b.Tag = ('{0}|{1}' -f $def[1], $p.Name); $b.Margin = '8,0,0,0'; $b.Padding = '12,5'
            if ($def[2]) { $b.Style = $window.FindResource('Sec') }
            $b.Add_Click({ param($s, $e) Invoke-MonitorAction ([string]$s.Tag) })
            [void]$bp.Children.Add($b)
        }
        [void]$g.Children.Add($sp); [void]$g.Children.Add($bp)
        $sep = New-Object Windows.Controls.Border; $sep.BorderBrush = New-UiBrush '#E2E7F0'; $sep.BorderThickness = '0,0,0,1'; $sep.Margin = '0,4,0,0'; $sep.Child = $g
        [void]$ui.MonList.Children.Add($sep)
    }
}
function Invoke-MonitorAction([string]$Tag) {
    $act, $name = $Tag -split '\|', 2
    switch ($act) {
        'Apply' {
            $window.Cursor = 'Wait'
            try {
                Set-MonitorProfile $name
                $ui.StatusText.Text = ('Monitor-Profil "{0}" angewendet.' -f $name)
                try { Invoke-AfterMonitorSwitch (Get-ConfigFromUi) } catch { $ui.StatusText.Text += ' Desktop-Symbole: ' + $_.Exception.Message }
            } catch { [Windows.MessageBox]::Show((T ($_.Exception.Message)), (T ('PC-Tools')), 'OK', 'Warning') | Out-Null }
            finally { $window.Cursor = $null; Build-MonitorPage }
        }
        'Link' {
            try {
                Sync-PflegeFiles
                $f = Join-Path ([Environment]::GetFolderPath('Desktop')) (('Monitor - {0}.lnk' -f $name) -replace '[\\/:*?"<>|]', '_')
                New-PflegeCommandShortcut $f ('-Monitor "{0}"' -f $name) ((Join-Path $env:SystemRoot 'System32\DisplaySwitch.exe') + ',0') ('Monitor-Anordnung "{0}" einschalten (PC-Tools)' -f $name)
                $ui.StatusText.Text = 'Verknüpfung erstellt: ' + $f
            } catch { [Windows.MessageBox]::Show((T ('Verknüpfung konnte nicht erstellt werden: ' + $_.Exception.Message)), (T ('PC-Tools')), 'OK', 'Warning') | Out-Null }
        }
        'Del' {
            if ([Windows.MessageBox]::Show((T (('Profil "{0}" löschen? Eine Desktop-Verknüpfung dafür funktioniert danach nicht mehr.' -f $name))), (T ('PC-Tools')), 'YesNo', 'Question') -ne 'Yes') { return }
            Remove-Item -LiteralPath (Get-MonitorProfileFile $name) -Force -ErrorAction SilentlyContinue
            $lnk = Join-Path ([Environment]::GetFolderPath('Desktop')) (('Monitor - {0}.lnk' -f $name) -replace '[\\/:*?"<>|]', '_')
            Remove-Item -LiteralPath $lnk -Force -ErrorAction SilentlyContinue
            Build-MonitorPage
        }
    }
}
function Save-MonitorProfileGui {
    $name = ($ui.MonName.Text -replace '["\\/:*?<>|]', '').Trim()
    if (-not $name) { [Windows.MessageBox]::Show((T ('Bitte einen Namen für das Profil eingeben, z.B. "Arbeit" oder "Nur Hauptmonitor".')), (T ('PC-Tools'))) | Out-Null; return }
    if ((Test-Path -LiteralPath (Get-MonitorProfileFile $name)) -and [Windows.MessageBox]::Show((T (('Profil "{0}" gibt es schon. Mit der aktuellen Anordnung überschreiben?' -f $name))), (T ('PC-Tools')), 'YesNo', 'Question') -ne 'Yes') { return }
    try {
        $p = Save-MonitorProfile $name
        $ui.MonName.Text = ''
        Build-MonitorPage
        $ui.StatusText.Text = ('Monitor-Profil "{0}" gespeichert ({1} Monitor(e)).' -f $name, @($p.Monitors).Count)
        if ([Windows.MessageBox]::Show((T (('Profil "{0}" gespeichert. Gleich eine Verknüpfung auf dem Desktop anlegen?' -f $name))), (T ('PC-Tools')), 'YesNo', 'Question') -eq 'Yes') { Invoke-MonitorAction ('Link|' + $name) }
    } catch { [Windows.MessageBox]::Show((T ('Speichern fehlgeschlagen: ' + $_.Exception.Message)), (T ('PC-Tools')), 'OK', 'Warning') | Out-Null }
}
function Set-TopologyGui([string]$Topo) {
    Import-NativeHelpers
    $t = switch ($Topo) { 'Intern' { 1 } 'Duplizieren' { 2 } 'Erweitern' { 4 } 'Extern' { 8 } }
    $r = [PCPflege.Displays]::SetTopology([uint32]$t)
    if ($r -ne 0) { [Windows.MessageBox]::Show((T (('Umschalten nicht möglich (Fehler {0}) - ist ein zweiter Bildschirm angeschlossen?' -f $r))), (T ('PC-Tools')), 'OK', 'Warning') | Out-Null; return }
    Start-Sleep -Seconds 2
    Build-MonitorPage
}
function Update-MonitorLogonTask($Cfg) {
    if ($Script:IsPortable) { return '' }
    $tn = 'PC-Pflege Monitore'
    $prof = [string]$Cfg.Monitor.AutoProfile
    if ($Cfg.Monitor.AutoAtLogon -and $prof) {
        $user = [Security.Principal.WindowsIdentity]::GetCurrent().Name
        $act = New-ScheduledTaskAction -Execute (Join-Path $env:SystemRoot 'System32\WindowsPowerShell\v1.0\powershell.exe') `
               -Argument ('-NoProfile -ExecutionPolicy Bypass -WindowStyle Hidden -File "{0}" -Monitor "{1}" -Delay 8 -Silent' -f (Join-Path $DataDir 'PCPflege.ps1'), $prof)
        $trg = New-ScheduledTaskTrigger -AtLogOn -User $user
        $pr  = New-ScheduledTaskPrincipal -UserId $user -LogonType Interactive -RunLevel Limited
        $set = New-ScheduledTaskSettingsSet -AllowStartIfOnBatteries -DontStopIfGoingOnBatteries -ExecutionTimeLimit (New-TimeSpan -Minutes 5)
        Register-ScheduledTask -TaskName $tn -Action $act -Trigger $trg -Principal $pr -Settings $set -Force | Out-Null
        return (' Monitor-Profil "{0}" wird beim Anmelden wiederhergestellt.' -f $prof)
    }
    if (Get-ScheduledTask -TaskName $tn -ErrorAction SilentlyContinue) { Unregister-ScheduledTask -TaskName $tn -Confirm:$false -ErrorAction SilentlyContinue }
    return ''
}

Import-NativeHelpers

# =====================================================================
#  Hintergrundaufgaben für die Oberfläche (Oberfläche bleibt bedienbar)
# =====================================================================
$script:BgJobs = New-Object System.Collections.ArrayList
# V14: Hintergrund-Aufgaben bekommen automatisch alle Hilfsfunktionen mit, die die genannten Funktionen aufrufen
# (vorher fehlte leicht eine in der Liste -> Abbruch im Hintergrund)
$script:BgFnDeps = @{}; $script:BgFnAll = $null
function Get-BgFnClosure([string[]]$Roots) {
    if (-not $script:BgFnAll) { $script:BgFnAll = @{}; foreach ($f in @(Get-ChildItem function:)) { try { if ($f.ScriptBlock.File -and $f.ScriptBlock.File -eq $PSCommandPath) { $script:BgFnAll[$f.Name] = $f } } catch { } } }
    $seen = [System.Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase); $q = [System.Collections.Generic.Queue[string]]::new()
    foreach ($r in @($Roots)) { if ($r) { $q.Enqueue([string]$r) } }
    while ($q.Count) {
        $n = $q.Dequeue(); if (-not $seen.Add($n)) { continue }; if (-not $script:BgFnAll.ContainsKey($n)) { continue }
        if (-not $script:BgFnDeps.ContainsKey($n)) { $script:BgFnDeps[$n] = @([regex]::Matches($script:BgFnAll[$n].ScriptBlock.ToString(), '(?<![\w$\-])[A-Z][A-Za-z0-9]*-[A-Za-z0-9]+') | ForEach-Object { $_.Value } | Where-Object { $script:BgFnAll.ContainsKey($_) } | Select-Object -Unique) }
        foreach ($d in $script:BgFnDeps[$n]) { if (-not $seen.Contains($d)) { $q.Enqueue($d) } }
    }
    return @($seen | Where-Object { $script:BgFnAll.ContainsKey($_) })
}
# V14: Grundeinstellungen, die viele Funktionen voraussetzen, auch im Hintergrund-Thread bereitstellen
function Set-BgCommonVars($Ps) {
    foreach ($n in 'DataDir', 'ConfigFile', 'ConfigVersion', 'DefaultUpdateSource', 'AppVersion', 'CcRegBackupRoot', 'NtOui', 'NdocPorts', 'NdocPortNames', 'NdocExtRisk', 'NdocEnterprise', 'NdocInfraRules', 'UnusedProtect', 'NtTlsCode', 'AiBugChecks', 'AiProviders', 'AutoSources') {
        try { $v = Get-Variable -Name $n -Scope Script -ErrorAction Stop; $Ps.Runspace.SessionStateProxy.SetVariable($n, $v.Value) } catch { }
    }
}
function Invoke-Bg([scriptblock]$Script, [object[]]$Arguments = @(), [scriptblock]$Done, [string[]]$Functions = @()) {
    $ps = [powershell]::Create()
    try { $Functions = @(@($Functions) + @(Get-BgFnClosure $Functions) | Where-Object { $_ } | Select-Object -Unique) } catch { }
    Set-BgCommonVars $ps
    $pre = ($Functions | ForEach-Object { "function $_ {`n" + (Get-Item "function:$_").ScriptBlock.ToString() + "`n}" }) -join "`n"
    if ($pre) { [void]$ps.AddScript($pre); [void]$ps.AddStatement() }
    [void]$ps.AddScript($Script.ToString())
    foreach ($a in $Arguments) { [void]$ps.AddArgument($a) }
    [void]$script:BgJobs.Add(@{ PS = $ps; Handle = $ps.BeginInvoke(); Done = $Done })
}
$bgTimer = New-Object System.Windows.Threading.DispatcherTimer
$bgTimer.Interval = [TimeSpan]::FromMilliseconds(250)
$bgTimer.Add_Tick({
    foreach ($j in @($script:BgJobs)) {
        if (-not $j.Handle.IsCompleted) { continue }
        [void]$script:BgJobs.Remove($j)
        $res = $null; $err = $null
        try { $res = @($j.PS.EndInvoke($j.Handle)) } catch { $err = $_.Exception.InnerException; if (-not $err) { $err = $_.Exception } }
        if (-not $err -and $j.PS.Streams.Error.Count -and -not $res) { $err = $j.PS.Streams.Error[0].Exception }
        $j.PS.Dispose()
        try { & $j.Done $res $err } catch { $ui.StatusText.Text = 'Fehler: ' + $_.Exception.Message }
    }
})
function Set-GridItems($Grid, $Items) {
    $Grid.ItemsSource = $null
    $Grid.ItemsSource = [System.Collections.ArrayList]@($Items)
}
function Set-GridFilter($Grid, [scriptblock]$Test) {
    if (-not $Grid.ItemsSource) { return }
    $v = [Windows.Data.CollectionViewSource]::GetDefaultView($Grid.ItemsSource)
    if ($Test) { $v.Filter = [Predicate[object]]$Test } else { $v.Filter = $null }
}
function Test-Match($Obj, [string]$Text, [string[]]$Props) {
    if (-not $Text) { return $true }
    foreach ($p in $Props) { if ([string]$Obj.$p -like ('*' + $Text + '*')) { return $true } }
    return $false
}
function Confirm-Ui([string]$Text, [string]$Icon = 'Question') { [Windows.MessageBox]::Show((T ($Text)), (T ('PC-Tools')), 'YesNo', $Icon) -eq 'Yes' }
function Show-UiError([string]$Text) {
    # 10.0: Fehlerfenster mit "Assistent fragen" (abschaltbar: KI-Assistent > Datenschutz); fällt bei jedem Problem auf das normale Fenster zurück
    try { if ((Get-Command Show-AiErrorDialog -ErrorAction SilentlyContinue) -and (Show-AiErrorDialog $Text)) { return } } catch { }
    [Windows.MessageBox]::Show((T ($Text)), (T ('PC-Tools')), 'OK', 'Warning') | Out-Null
}
function Start-Tool([string]$Cmd) {
    $exe, $arg = $Cmd -split ' ', 2
    try { if ($arg) { Start-Process -FilePath $exe -ArgumentList $arg } else { Start-Process -FilePath $exe } }
    catch { Show-UiError ('{0} konnte nicht gestartet werden: {1}' -f $Cmd, $_.Exception.Message) }
}

# Einfacher Eingabedialog. Felder: @{ Key; Label; Type = Text|Password|Check|Combo|Folder; Items; Value }
function Show-InputDialog([string]$Title, [string]$Intro, [object[]]$Fields) {
    $rows = foreach ($f in $Fields) {
        switch ($f.Type) {
            'Password' { '<TextBlock Text="{0}" Margin="0,8,0,3"/><PasswordBox x:Name="F_{1}" Padding="4,4"/>' -f (Esc $f.Label), $f.Key }
            'Check'    { '<CheckBox x:Name="F_{1}" Content="{0}" Margin="0,10,0,0" IsChecked="{2}"/>' -f (Esc $f.Label), $f.Key, $(if ($f.Value) { 'True' } else { 'False' }) }
            'Combo'    { '<TextBlock Text="{0}" Margin="0,8,0,3"/><ComboBox x:Name="F_{1}" SelectedIndex="0">{2}</ComboBox>' -f (Esc $f.Label), $f.Key, (($f.Items | ForEach-Object { '<ComboBoxItem Content="{0}"/>' -f (Esc $_) }) -join '') }
            'Folder'   { '<TextBlock Text="{0}" Margin="0,8,0,3"/><Grid><Grid.ColumnDefinitions><ColumnDefinition/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions><TextBox x:Name="F_{1}" Padding="4,4" Text="{2}"/><Button x:Name="B_{1}" Grid.Column="1" Content="..." Margin="6,0,0,0" Padding="10,2"/></Grid>' -f (Esc $f.Label), $f.Key, (Esc ([string]$f.Value)) }
            default    { '<TextBlock Text="{0}" Margin="0,8,0,3"/><TextBox x:Name="F_{1}" Padding="4,4" Text="{2}"/>' -f (Esc $f.Label), $f.Key, (Esc ([string]$f.Value)) }
        }
    }
    $x = @"
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Title="$(Esc $Title)" Width="440" SizeToContent="Height" WindowStartupLocation="CenterOwner" ResizeMode="NoResize" FontFamily="Segoe UI" FontSize="13" Background="#F4F6FA">
  <StackPanel Margin="20">
    <TextBlock Text="$(Esc $Intro)" TextWrapping="Wrap" Foreground="#1F2A44"/>
    $($rows -join "`n")
    <StackPanel Orientation="Horizontal" HorizontalAlignment="Right" Margin="0,18,0,0">
      <Button x:Name="Ok" Content="OK" Width="100" Padding="0,7" Margin="0,0,8,0" IsDefault="True"/>
      <Button x:Name="No" Content="Abbrechen" Width="100" Padding="0,7" IsCancel="True"/>
    </StackPanel>
  </StackPanel>
</Window>
"@
    $w = [Windows.Markup.XamlReader]::Parse($x)
    $w.Owner = $window
    $w.FindName('Ok').Add_Click({ $w.DialogResult = $true })
    foreach ($f in $Fields) {
        if ($f.Type -eq 'Folder') {
            $tb = $w.FindName('F_' + $f.Key)
            $w.FindName('B_' + $f.Key).Add_Click({
                Add-Type -AssemblyName System.Windows.Forms
                $d = New-Object System.Windows.Forms.FolderBrowserDialog
                if ($d.ShowDialog() -eq 'OK') { $tb.Text = $d.SelectedPath }
            }.GetNewClosure())
        }
    }
    if (-not $w.ShowDialog()) { return $null }
    $r = @{}
    foreach ($f in $Fields) {
        $c = $w.FindName('F_' + $f.Key)
        $r[$f.Key] = switch ($f.Type) { 'Password' { $c.Password } 'Check' { [bool]$c.IsChecked } 'Combo' { [string]$c.SelectedItem.Content } default { $c.Text.Trim() } }
    }
    return $r
}

# =====================================================================
#  Übersicht: Hardware- und Netzwerkinfos (im Hintergrund)
# =====================================================================
$SysInfoScript = {
    $o = [ordered]@{}
    try {
        $cs = Get-CimInstance Win32_ComputerSystem; $os = Get-CimInstance Win32_OperatingSystem
        $cpu = @(Get-CimInstance Win32_Processor)
        $o.InfoCpu = (($cpu | ForEach-Object { '{0} - {1} Kerne / {2} Threads, {3:N1} GHz' -f ($_.Name -replace '\s+', ' ').Trim(), $_.NumberOfCores, $_.NumberOfLogicalProcessors, ($_.MaxClockSpeed / 1000) }) -join "`n")
        $mem = @(Get-CimInstance Win32_PhysicalMemory)
        $slots = (Get-CimInstance Win32_PhysicalMemoryArray | Measure-Object MemoryDevices -Sum).Sum
        $types = @{ 20 = 'DDR'; 21 = 'DDR2'; 24 = 'DDR3'; 26 = 'DDR4'; 34 = 'DDR5'; 35 = 'LPDDR5' }
        $t = ($mem | ForEach-Object { $types[[int]$_.SMBIOSMemoryType] } | Where-Object { $_ } | Select-Object -First 1)
        $grp = ($mem | Group-Object { [math]::Round($_.Capacity / 1GB) } | ForEach-Object { '{0}x {1} GB' -f $_.Count, $_.Name }) -join ' + '
        $spd = ($mem | Measure-Object ConfiguredClockSpeed -Maximum).Maximum
        $o.InfoRam = '{0:N0} GB ({1}{2}{3}), {4} von {5} Steckplätzen belegt' -f ($cs.TotalPhysicalMemory / 1GB), $grp, $(if ($t) { ' ' + $t } else { '' }), $(if ($spd) { " $spd MT/s" } else { '' }), $mem.Count, $(if ($slots) { $slots } else { '?' })
        $o.InfoGpu = ((Get-CimInstance Win32_VideoController | Where-Object { $_.Name -notmatch 'Remote|Mirage|Parsec|Virtual' } | ForEach-Object { '{0} (Treiber {1})' -f $_.Name, $_.DriverVersion }) -join "`n")
        $bb = Get-CimInstance Win32_BaseBoard; $bios = Get-CimInstance Win32_BIOS
        $uefi = if (Test-Path 'HKLM:\SYSTEM\CurrentControlSet\Control\SecureBoot\State') { 'UEFI' } else { 'Legacy-BIOS' }
        $o.InfoBoard = '{0} {1} - BIOS {2} vom {3:dd.MM.yyyy} ({4})' -f $bb.Manufacturer, $bb.Product, $bios.SMBIOSBIOSVersion, $bios.ReleaseDate, $uefi
        $o.InfoSerial = [string]$bios.SerialNumber
        $pd = @(Get-PhysicalDisk -ErrorAction SilentlyContinue | Sort-Object DeviceId)
        $hl = @{ Healthy = 'Gut'; Warning = 'Warnung'; Unhealthy = 'Kritisch' }
        $o.InfoDisks = (($pd | ForEach-Object { '{0}: {1} - {2:N0} GB, {3}, {4}, Zustand {5}' -f $_.DeviceId, $_.FriendlyName, ($_.Size / 1GB), $_.BusType, $(if ([string]$_.MediaType -ne 'Unspecified') { $_.MediaType } else { '?' }), $(if ($hl[[string]$_.HealthStatus]) { $hl[[string]$_.HealthStatus] } else { $_.HealthStatus }) }) -join "`n")
        $o.InfoVolumes = ((Get-Volume -ErrorAction SilentlyContinue | Where-Object { $_.DriveLetter -and $_.Size } | Sort-Object DriveLetter | ForEach-Object { '{0}: {1:N0} GB frei von {2:N0} GB ({3}{4})' -f $_.DriveLetter, ($_.SizeRemaining / 1GB), ($_.Size / 1GB), $_.FileSystem, $(if ($_.FileSystemLabel) { ', ' + $_.FileSystemLabel } else { '' }) }) -join "`n")
        $bat = @(Get-CimInstance Win32_Battery -ErrorAction SilentlyContinue)
        $o.InfoBattery = if ($bat.Count) { ($bat | ForEach-Object { '{0} % geladen ({1})' -f $_.EstimatedChargeRemaining, $(if ($_.BatteryStatus -eq 2) { 'am Netz' } else { 'Akkubetrieb' }) }) -join ', ' } else { 'kein Akku (Desktop-PC)' }
        $dom = if ($cs.PartOfDomain) { 'Domäne ' + $cs.Domain } else { 'Arbeitsgruppe ' + $cs.Workgroup }
        $o.InfoComputerName = '{0} - {1}, angemeldet: {2}' -f $env:COMPUTERNAME, $dom, $cs.UserName
        $net = foreach ($a in @(Get-NetAdapter -Physical -ErrorAction SilentlyContinue | Where-Object Status -eq 'Up')) {
            $ip = (Get-NetIPAddress -InterfaceIndex $a.ifIndex -AddressFamily IPv4 -ErrorAction SilentlyContinue | Select-Object -First 1).IPAddress
            $gw = (Get-NetRoute -InterfaceIndex $a.ifIndex -DestinationPrefix '0.0.0.0/0' -ErrorAction SilentlyContinue | Select-Object -First 1).NextHop
            '{0}: {1}, {2}, IP {3}{4}, MAC {5}' -f $a.Name, $a.InterfaceDescription, $a.LinkSpeed, $ip, $(if ($gw) { ", Gateway $gw" } else { '' }), $a.MacAddress
        }
        $o.InfoNet = if ($net) { $net -join "`n" } else { 'keine aktive Verbindung' }
        $sec = [System.Collections.Generic.List[string]]::new()
        try { $tpm = Get-CimInstance -Namespace root\cimv2\Security\MicrosoftTpm -ClassName Win32_Tpm -ErrorAction Stop; $sec.Add(('TPM {0} {1}' -f (([string]$tpm.SpecVersion -split ',')[0]), $(if ($tpm.IsEnabled_InitialValue) { 'aktiv' } else { 'aus' }))) } catch { $sec.Add('kein TPM') }
        try { $sb = Confirm-SecureBootUEFI -ErrorAction Stop; $sec.Add($(if ($sb) { 'Secure Boot an' } else { 'Secure Boot aus' })) } catch { $sec.Add('Secure Boot nicht verfügbar') }
        try { $bl = Get-BitLockerVolume -MountPoint $env:SystemDrive -ErrorAction Stop; $sec.Add($(if ([string]$bl.ProtectionStatus -eq 'On') { 'BitLocker an' } else { 'BitLocker aus' })) } catch { }
        try { $fw = @(Get-NetFirewallProfile -ErrorAction Stop | Where-Object { -not $_.Enabled }); $sec.Add($(if ($fw.Count) { 'Firewall AUS für: ' + (($fw | ForEach-Object Name) -join ', ') } else { 'Firewall an' })) } catch { }
        $o.InfoSec = $sec -join ', '
        $o.InfoInstalled = '{0:dd.MM.yyyy HH:mm}' -f $os.InstallDate
        $lic = Get-CimInstance SoftwareLicensingProduct -Filter "ApplicationID='55c92734-d682-4d71-983e-d6ec3f16059f' AND PartialProductKey IS NOT NULL" -ErrorAction SilentlyContinue | Select-Object -First 1
        $ls = @{ 0 = 'nicht lizenziert'; 1 = 'aktiviert'; 2 = 'Kulanzzeit'; 3 = 'Kulanzzeit'; 4 = 'nicht echt'; 5 = 'Benachrichtigung'; 6 = 'erweiterte Kulanzzeit' }
        $o.InfoLicense = if ($lic) { '{0} ({1}, Schlüssel ...{2})' -f $ls[[int]$lic.LicenseStatus], ($lic.Description -replace '^.*?,\s*', ''), $lic.PartialProductKey } else { 'unbekannt' }
    } catch { $o.InfoCpu = 'Fehler beim Einlesen: ' + $_.Exception.Message }
    [pscustomobject]$o
}
function Update-SysInfo {
    foreach ($n in 'InfoCpu', 'InfoRam', 'InfoGpu', 'InfoBoard', 'InfoSerial', 'InfoDisks', 'InfoVolumes', 'InfoBattery', 'InfoComputerName', 'InfoNet', 'InfoSec', 'InfoInstalled', 'InfoLicense') { $ui[$n].Text = 'wird eingelesen ...' }
    try { $ui.InfoMon.Text = (@(Get-MonitorLayout) | ForEach-Object { Get-MonitorText $_ }) -join "`n" } catch { $ui.InfoMon.Text = '-' }
    Invoke-Bg -Script $SysInfoScript -Done {
        param($r, $err)
        if ($err -or -not $r) { $ui.InfoCpu.Text = 'Fehler: ' + $(if ($err) { $err.Message } else { 'keine Daten' }); return }
        foreach ($p in $r[0].PSObject.Properties) { if ($ui[$p.Name]) { $ui[$p.Name].Text = $(if ([string]$p.Value) { [string]$p.Value } else { '-' }) } }
    }
}
function Copy-SysInfo {
    $lines = foreach ($pair in @(@('Windows', 'InfoOS'), @('Gerät', 'InfoModel'), @('Seriennummer', 'InfoSerial'), @('Prozessor', 'InfoCpu'), @('Arbeitsspeicher', 'InfoRam'), @('Grafik', 'InfoGpu'),
                              @('Monitore', 'InfoMon'), @('Mainboard / BIOS', 'InfoBoard'), @('Datenträger', 'InfoDisks'), @('Laufwerke', 'InfoVolumes'), @('Akku', 'InfoBattery'), @('Computer', 'InfoComputerName'),
                              @('Netzwerk', 'InfoNet'), @('Sicherheit', 'InfoSec'), @('Lizenz', 'InfoLicense'), @('Installiert am', 'InfoInstalled'), @('Virenschutz', 'InfoAv'), @('Läuft seit', 'InfoUptime'))) {
        '{0,-18} {1}' -f ($pair[0] + ':'), ($ui[$pair[1]].Text -replace "`n", ("`n" + (' ' * 19)))
    }
    [Windows.Clipboard]::SetText((('PC-Tools - {0} ({1:dd.MM.yyyy HH:mm})' -f $env:COMPUTERNAME, (Get-Date)), '') + $lines -join "`r`n")
    $ui.StatusText.Text = 'Systeminfos in die Zwischenablage kopiert.'
}

# =====================================================================
#  Live-Auslastung und Task-Manager
# =====================================================================
$script:TmRows = @{}
$script:TmList = New-Object 'System.Collections.ObjectModel.ObservableCollection[PCPflege.ProcRow]'
$script:TmLast = [DateTime]::MinValue
$script:TmDesc = @{}
$script:TmHist = @{ Cpu = [System.Collections.Generic.List[double]]::new(); Ram = [System.Collections.Generic.List[double]]::new(); Net = [System.Collections.Generic.List[double]]::new(); Sys = [System.Collections.Generic.List[double]]::new() }
$script:NetLast = $null; $script:NetLastTime = $null
$script:TmPaused = $false
function Get-NetBytes {
    $sum = [int64]0
    foreach ($n in [System.Net.NetworkInformation.NetworkInterface]::GetAllNetworkInterfaces()) {
        if ($n.OperationalStatus -ne 'Up' -or $n.NetworkInterfaceType -eq 'Loopback') { continue }
        try { $s = $n.GetIPStatistics(); $sum += $s.BytesReceived + $s.BytesSent } catch { }
    }
    return $sum
}
function Get-LoadSample {
    Import-NativeHelpers
    $cpu = [PCPflege.SysStats]::Cpu()
    $m = [PCPflege.SysStats]::Memory()
    $now = Get-Date; $nb = Get-NetBytes; $rate = 0
    if ($script:NetLast -and $script:NetLastTime) { $sec = ($now - $script:NetLastTime).TotalSeconds; if ($sec -gt 0) { $rate = [math]::Max(0, ($nb - $script:NetLast) / $sec) } }
    $script:NetLast = $nb; $script:NetLastTime = $now
    [pscustomobject]@{ Cpu = $cpu; RamTotal = [double]$m[0]; RamFree = [double]$m[1]; RamPct = [double]$m[2]; CommitTotal = [double]$m[3]; CommitFree = [double]$m[4]; Net = $rate }
}
function Add-Spark([string]$Key, [double]$Val, [double]$Max) {
    $h = $script:TmHist[$Key]; $h.Add($Val); while ($h.Count -gt 60) { $h.RemoveAt(0) }
    $line = $ui['Tm' + $Key + 'Line']; $cv = $ui['Tm' + $Key + 'Canvas']
    $w = [math]::Max(50, $cv.ActualWidth); $ht = 40
    if ($Max -le 0) { $Max = [math]::Max(1, ($h | Measure-Object -Maximum).Maximum) }
    $pts = New-Object Windows.Media.PointCollection
    for ($i = 0; $i -lt $h.Count; $i++) { $pts.Add((New-Object Windows.Point (($w * ($i + 60 - $h.Count) / 59), ($ht - [math]::Min($ht, $ht * $h[$i] / $Max) + 1)))) }
    $line.Points = $pts
}
function Set-Gauge([string]$Name, [double]$Pct, [string]$Val, [string]$Sub = '', [string]$Color = '#FFFFFF') {
    $e = $ui[$Name + 'Arc']; if (-not $e) { return }
    $len = [math]::Max(0, [math]::Min(100, $Pct)) / 100 * ([math]::PI * 84 / 8)
    $dc = New-Object Windows.Media.DoubleCollection; $dc.Add([math]::Max(0.001, $len)); $dc.Add(100); $e.StrokeDashArray = $dc
    $e.Stroke = (New-Object Windows.Media.BrushConverter).ConvertFromString($Color)
    $ui[$Name + 'Val'].Text = $Val; $ui[$Name + 'Sub'].Text = $Sub
}
function Update-Load([switch]$Tiles) {
    $s = Get-LoadSample
    $used = $s.RamTotal - $s.RamFree
    try { Set-Gauge 'GaCpu' $s.Cpu ('{0:N0} %' -f $s.Cpu) 'Auslastung' $(if ($s.Cpu -ge 85) { '#FDE68A' } else { '#FFFFFF' }); Set-Gauge 'GaRam' $s.RamPct ('{0:N0} %' -f $s.RamPct) ('{0:N1} von {1:N0} GB' -f ($used / 1GB), ($s.RamTotal / 1GB)) $(if ($s.RamPct -ge 85) { '#FDE68A' } else { '#FFFFFF' }) } catch { }
    $ui.InfoLoad.Text = 'CPU {0:N0} %   ·   Arbeitsspeicher {1:N1} von {2:N1} GB ({3:N0} %)   ·   Netzwerk {4}' -f $s.Cpu, ($used / 1GB), ($s.RamTotal / 1GB), $s.RamPct, (Format-Rate $s.Net)
    if (-not $Tiles) { return }
    $ui.TmCpuVal.Text = '{0:N0} %' -f $s.Cpu
    $ui.TmCpuSub.Text = '{0} logische Prozessoren' -f [Environment]::ProcessorCount
    Add-Spark 'Cpu' $s.Cpu 100
    $ui.TmRamVal.Text = '{0:N1} / {1:N0} GB' -f ($used / 1GB), ($s.RamTotal / 1GB)
    $ui.TmRamSub.Text = '{0:N0} % belegt, Zusage {1:N1} / {2:N1} GB' -f $s.RamPct, (($s.CommitTotal - $s.CommitFree) / 1GB), ($s.CommitTotal / 1GB)
    Add-Spark 'Ram' $s.RamPct 100
    $ui.TmNetVal.Text = Format-Rate $s.Net
    $ui.TmNetSub.Text = 'Senden + Empfangen, alle Adapter'
    Add-Spark 'Net' $s.Net 0
}
function Update-TaskManager {
    if ($script:TmPaused) { return }
    Update-Load -Tiles
    $now = [DateTime]::UtcNow
    $wall = ($now - $script:TmLast).TotalSeconds * [Environment]::ProcessorCount
    $first = $script:TmLast -eq [DateTime]::MinValue
    $script:TmLast = $now
    $threads = 0
    foreach ($r in $script:TmList) { $r.Seen = $false }
    foreach ($p in [Diagnostics.Process]::GetProcesses()) {
        if ($p.Id -eq 0) { continue }
        $row = $script:TmRows[$p.Id]
        if (-not $row) {
            $row = New-Object PCPflege.ProcRow
            $row.Pid = $p.Id; $row.Name = $p.ProcessName
            $path = ''; try { $path = $p.MainModule.FileName } catch { }
            $row.Path = $path
            if ($path) {
                if (-not $script:TmDesc.ContainsKey($path)) { try { $script:TmDesc[$path] = [Diagnostics.FileVersionInfo]::GetVersionInfo($path).FileDescription } catch { $script:TmDesc[$path] = '' } }
                $row.Description = $script:TmDesc[$path]
            }
            $script:TmRows[$p.Id] = $row
            $script:TmList.Add($row)
        }
        $ticks = [int64]0; try { $ticks = $p.TotalProcessorTime.Ticks } catch { }
        if (-not $first -and $row.LastTicks -gt 0 -and $wall -gt 0) { $row.Cpu = [math]::Round([math]::Max(0, ($ticks - $row.LastTicks) / 1e7 / $wall * 100), 1) }
        $row.LastTicks = $ticks
        $row.RamMB = [math]::Round($p.WorkingSet64 / 1MB, 1)
        $row.Threads = $p.Threads.Count; $threads += $row.Threads
        $t = ''; try { $t = $p.MainWindowTitle } catch { }
        if ($row.Title -ne $t) { $row.Title = $t }
        $row.Seen = $true
        $p.Dispose()
    }
    foreach ($r in @($script:TmList | Where-Object { -not $_.Seen })) { [void]$script:TmList.Remove($r); $script:TmRows.Remove($r.Pid) }
    $ui.TmSysVal.Text = '{0} Prozesse' -f $script:TmList.Count
    if (-not $script:BootTime) { $script:BootTime = (Get-CimInstance Win32_OperatingSystem).LastBootUpTime }
    $up = (Get-Date) - $script:BootTime
    $ui.TmSysSub.Text = '{0:N0} Threads, läuft seit {1} T {2} Std' -f $threads, $up.Days, $up.Hours
    Add-Spark 'Sys' $script:TmList.Count 0
}
function Update-TmFilter {
    $txt = $ui.TmFilter.Text.Trim(); $apps = [bool]$ui.TmApps.IsChecked
    if (-not $txt -and -not $apps) { Set-GridFilter $ui.TmGrid $null; return }
    $script:FTm = @{ T = $txt; A = $apps }
    Set-GridFilter $ui.TmGrid { param($o) $f = $script:FTm; ((-not $f.A -or $o.Title) -and (Test-Match $o $f.T @('Name', 'Description', 'Title', 'Path'))) -or ($f.T -and [string]$o.Pid -eq $f.T) }
}
function Stop-SelectedProcess([switch]$Tree) {
    $r = $ui.TmGrid.SelectedItem
    if (-not $r) { return }
    if (-not (Confirm-Ui ('{0} (PID {1}){2} wirklich beenden? Nicht gespeicherte Daten gehen verloren.' -f $r.Name, $r.Pid, $(if ($Tree) { ' samt aller Unterprozesse' } else { '' })) 'Warning')) { return }
    try {
        if ($Tree) { $null = & taskkill.exe /PID $r.Pid /T /F 2>&1 } else { Stop-Process -Id $r.Pid -Force -ErrorAction Stop }
        $ui.StatusText.Text = ('{0} beendet.' -f $r.Name)
    } catch { Show-UiError ('Beenden nicht möglich: ' + $_.Exception.Message) }
}

# =====================================================================
#  Fehlerdaten
# =====================================================================
$ProbColors = @{ 'Bluescreen' = '#DC2626'; 'Unerwartet ausgeschaltet' = '#EA580C'; 'Hardwarefehler' = '#DC2626'; 'Datenträger' = '#DC2626'; 'Dateisystem' = '#EA580C'
                 'Programmabsturz' = '#D97706'; 'Programm reagiert nicht' = '#D97706'; 'Dienst / Treiber' = '#6B7890'; 'Windows Update' = '#2563EB'; 'Treiber' = '#6B7890'; 'Grafiktreiber' = '#7C3AED' }
function Update-Problems {
    $days = switch ($ui.ProbDays.SelectedIndex) { 1 { 30 } 2 { 90 } default { 7 } }
    $ui.ProbInfo.Text = 'Wird eingelesen ...'
    Invoke-Bg -Script { param($d) Get-ProblemEvents $d } -Arguments @($days) -Functions @('Get-ProblemEvents') -Done {
        param($r, $err)
        if ($err) { $ui.ProbInfo.Text = 'Fehler: ' + $err.Message; return }
        $rows = @($r | Where-Object { $_ })
        Set-GridItems $ui.ProbGrid $rows
        $ui.ProbTiles.Children.Clear()
        foreach ($g in @($rows | Group-Object Cat | Sort-Object Count -Descending)) {
            $b = New-Object Windows.Controls.Border
            $b.CornerRadius = '8'; $b.Padding = '12,6'; $b.Margin = '0,0,8,8'
            $b.Background = New-UiBrush $(if ($ProbColors[$g.Name]) { $ProbColors[$g.Name] } else { '#6B7890' })
            $t = New-Object Windows.Controls.TextBlock; $t.Foreground = New-UiBrush '#FFFFFF'; $t.FontWeight = 'SemiBold'
            $t.Text = '{0}  {1}' -f $g.Count, $g.Name
            $b.Child = $t; [void]$ui.ProbTiles.Children.Add($b)
        }
        $ui.ProbInfo.Text = if ($rows.Count) { '{0} Einträge. Eintrag anklicken für die vollständige Meldung.' -f $rows.Count } else { 'Keine Probleme gefunden - sehr gut.' }
    }
}

# =====================================================================
#  Computerverwaltung
# =====================================================================
$script:AdmLoaded = @{}
function Invoke-AdmLoad([string]$Name, [switch]$Force) {
    if ($script:AdmLoaded[$Name] -and -not $Force) { return }
    $script:AdmLoaded[$Name] = $true
    switch ($Name) {
        'AdmDisks'  { Update-DiskList }
        'AdmSvc'    { Update-Services }
        'AdmDev'    { Update-Devices }
        'AdmTask'   { Update-Tasks }
        'AdmEv'     { Update-Events }
        'AdmUsers'  { Update-Users }
        'AdmShares' { Update-Shares }
        'AdmPrg'    { Update-Programs }
    }
}

# ---- Dienste
function Update-Services {
    $window.Cursor = 'Wait'
    try {
        $st = @{ Running = 'Läuft'; Stopped = 'Beendet'; Paused = 'Angehalten'; 'Start Pending' = 'Startet ...'; 'Stop Pending' = 'Stoppt ...' }
        $rows = foreach ($s in @(Get-CimInstance Win32_Service)) {
            $start = switch ($s.StartMode) { 'Auto' { if ($s.DelayedAutoStart) { 'Automatisch (verzögert)' } else { 'Automatisch' } } 'Manual' { 'Manuell' } 'Disabled' { 'Deaktiviert' } 'Boot' { 'Boot' } 'System' { 'System' } default { $s.StartMode } }
            $ms = ([string]$s.PathName -match '\\Windows\\|svchost') -and ([string]$s.PathName -notmatch 'Program Files')
            [pscustomobject]@{
                DisplayName = [string]$s.DisplayName; Name = [string]$s.Name; State = [string]$s.State; StateText = $(if ($st[[string]$s.State]) { $st[[string]$s.State] } else { $s.State })
                StartMode = [string]$s.StartMode; StartText = $start; Account = ([string]$s.StartName -replace '^NT AUTHORITY\\|^NT-AUTORITÄT\\', ''); Pid = $(if ($s.ProcessId) { $s.ProcessId } else { $null })
                Description = [string]$s.Description; Path = [string]$s.PathName; IsMs = $ms
                Level = $(if ($s.StartMode -eq 'Auto' -and $s.State -ne 'Running' -and -not $s.DelayedAutoStart) { 'Warn' } elseif ($s.State -ne 'Running') { 'Off' } else { '' })
            }
        }
        Set-GridItems $ui.SvcGrid @($rows | Sort-Object DisplayName)
        Update-SvcFilter
    } catch { Show-UiError ('Dienste konnten nicht gelesen werden: ' + $_.Exception.Message) }
    finally { $window.Cursor = $null }
}
function Update-SvcFilter {
    $script:FSvc = @{ T = $ui.SvcFilter.Text.Trim(); M = $ui.SvcState.SelectedIndex }
    Set-GridFilter $ui.SvcGrid {
        param($o)
        $txt = $script:FSvc.T
        $ok = switch ($script:FSvc.M) { 1 { $o.State -eq 'Running' } 2 { $o.State -ne 'Running' } 3 { $o.StartMode -eq 'Auto' -and $o.State -ne 'Running' } 4 { -not $o.IsMs } default { $true } }
        $ok -and (Test-Match $o $txt @('DisplayName', 'Name', 'Description'))
    }
}
function Invoke-SvcAction([string]$Act) {
    $s = $ui.SvcGrid.SelectedItem
    if (-not $s) { return }
    $window.Cursor = 'Wait'
    try {
        switch ($Act) {
            'Start'   { Set-ServiceSafe $s.Name 'Start' 30 }
            'Stop'    { if (-not (Confirm-Ui ('Dienst "{0}" beenden?' -f $s.DisplayName))) { return }; Set-ServiceSafe $s.Name 'Stop' 30 }
            'Restart' { Set-ServiceSafe $s.Name 'Restart' 30 }
            default   {
                if ($Act -eq 'Disabled' -and $s.IsMs -and -not (Confirm-Ui ('"{0}" ist ein Windows-Dienst. Deaktivieren kann Funktionen von Windows stören. Trotzdem deaktivieren?' -f $s.DisplayName) 'Warning')) { return }
                $mode = @{ Automatic = 'auto'; Manual = 'demand'; Disabled = 'disabled' }[$Act]
                $out = & sc.exe config $s.Name start= $mode 2>&1
                if ($LASTEXITCODE -ne 0) { throw ($out -join ' ') }
            }
        }
        $ui.StatusText.Text = ('Dienst {0}: erledigt.' -f $s.DisplayName)
    } catch { Show-UiError ('Aktion fehlgeschlagen: ' + $_.Exception.Message) }
    finally { $window.Cursor = $null }
    Update-Services
}

# ---- Geräte
function Update-Devices {
    $ui.DevInfo.Text = 'Geräte werden eingelesen ...'
    Invoke-Bg -Script {
        $drv = @{}
        foreach ($d in @(Get-CimInstance Win32_PnPSignedDriver -ErrorAction SilentlyContinue)) { if ($d.DeviceID) { $drv[$d.DeviceID] = $d } }
        $codes = @{ 1 = 'nicht richtig konfiguriert'; 3 = 'Treiber beschädigt'; 10 = 'kann nicht gestartet werden'; 12 = 'Ressourcenkonflikt'; 14 = 'Neustart nötig'; 18 = 'Treiber neu installieren'
                    19 = 'Registrierung fehlerhaft'; 21 = 'wird entfernt'; 22 = 'deaktiviert'; 24 = 'nicht vorhanden'; 28 = 'kein Treiber installiert'; 29 = 'von Firmware deaktiviert'; 31 = 'Treiber lädt nicht'
                    32 = 'Dienst deaktiviert'; 37 = 'Treiber-Fehler'; 39 = 'Treiber fehlt/beschädigt'; 41 = 'Gerät nicht gefunden'; 43 = 'Gerät meldet Fehler'; 45 = 'nicht angeschlossen'; 52 = 'Signatur ungültig' }
        foreach ($p in @(Get-PnpDevice -ErrorAction SilentlyContinue)) {
            $d = $drv[$p.InstanceId]
            $code = [int]$p.ConfigManagerErrorCode
            $present = [bool]$p.Present
            $stText = if (-not $present) { 'nicht angeschlossen' } elseif ($p.Status -eq 'OK') { 'OK' } elseif ($codes[$code]) { $codes[$code] } else { '{0} (Code {1})' -f $p.Status, $code }
            [pscustomobject]@{
                Class = [string]$(if ($p.Class) { $p.Class } else { 'Sonstige' }); Name = [string]$(if ($p.FriendlyName) { $p.FriendlyName } else { $p.InstanceId }); Status = [string]$p.Status; StatusText = $stText
                Present = $present; Problem = ($present -and $p.Status -ne 'OK' -and $code -ne 22); Disabled = ($code -eq 22)
                Manufacturer = [string]$p.Manufacturer; DriverVersion = [string]$d.DriverVersion; DriverDate = $(if ($d.DriverDate) { $d.DriverDate.ToString('dd.MM.yyyy') } else { '' })
                Inf = [string]$d.InfName; InstanceId = [string]$p.InstanceId
                Level = $(if (-not $present) { 'Off' } elseif ($code -eq 22) { 'Off' } elseif ($p.Status -ne 'OK') { 'Error' } else { '' })
            }
        }
    } -Done {
        param($r, $err)
        if ($err) { $ui.DevInfo.Text = 'Fehler: ' + $err.Message; return }
        $rows = @($r | Where-Object { $_ } | Sort-Object @{ e = { -not $_.Problem } }, Class, Name)
        Set-GridItems $ui.DevGrid $rows
        Update-DevFilter
        $pr = @($rows | Where-Object Problem).Count
        $ui.DevInfo.Text = if ($pr) { '{0} Gerät(e) mit Problemen - stehen oben in Rot.' -f $pr } else { 'Alle angeschlossenen Geräte funktionieren.' }
    }
}
function Update-DevFilter {
    $script:FDev = @{ T = $ui.DevFilter.Text.Trim(); P = [bool]$ui.DevProblems.IsChecked; H = [bool]$ui.DevHidden.IsChecked }
    Set-GridFilter $ui.DevGrid { param($o) $f = $script:FDev; ($f.H -or $o.Present) -and (-not $f.P -or $o.Problem) -and (Test-Match $o $f.T @('Class', 'Name', 'Manufacturer', 'InstanceId')) }
}
function Invoke-DevAction([string]$Act) {
    $d = $ui.DevGrid.SelectedItem
    if (-not $d) { return }
    try {
        if ($Act -eq 'Disable') {
            if (-not (Confirm-Ui ('"{0}" deaktivieren? Tastatur, Maus, Grafik- oder Netzwerkkarte besser nicht deaktivieren.' -f $d.Name) 'Warning')) { return }
            Disable-PnpDevice -InstanceId $d.InstanceId -Confirm:$false -ErrorAction Stop
        } else { Enable-PnpDevice -InstanceId $d.InstanceId -Confirm:$false -ErrorAction Stop }
        $ui.StatusText.Text = 'Gerät geändert: ' + $d.Name
    } catch { Show-UiError ('Nicht möglich: ' + $_.Exception.Message) }
    Update-Devices
}

# ---- Aufgabenplanung
function Update-Tasks {
    $ui.TskInfo.Text = 'Aufgaben werden eingelesen ...'
    Invoke-Bg -Script {
        param($ms)
        $res = @{ 0 = 'Erfolgreich'; 1 = 'Fehler (1)'; 267009 = 'Läuft gerade'; 267011 = 'Noch nie ausgeführt'; 267014 = 'Vom Benutzer beendet'; 2147750687 = 'Läuft bereits'; 2147942402 = 'Datei nicht gefunden'; 2147942405 = 'Zugriff verweigert' }
        $stt = @{ Ready = 'Bereit'; Running = 'Läuft'; Disabled = 'Deaktiviert'; Queued = 'Wartet' }
        foreach ($t in @(Get-ScheduledTask -ErrorAction SilentlyContinue | Where-Object { $ms -or $_.TaskPath -notlike '\Microsoft\*' })) {
            $i = $null; try { $i = Get-ScheduledTaskInfo -InputObject $t -ErrorAction Stop } catch { }
            $last = if ($i -and $i.LastRunTime -and $i.LastRunTime.Year -gt 2000) { $i.LastRunTime } else { $null }
            $next = if ($i -and $i.NextRunTime -and $i.NextRunTime.Year -gt 2000) { $i.NextRunTime } else { $null }
            $code = if ($i) { [uint32]$i.LastTaskResult } else { 0 }
            $act = ($t.Actions | ForEach-Object { ('{0} {1}' -f $_.Execute, $_.Arguments).Trim() }) -join ' | '
            $trg = ($t.Triggers | ForEach-Object { ($_.CimClass.CimClassName -replace '^MSFT_Task|Trigger$', '') + $(if ($_.StartBoundary) { ' ab ' + $_.StartBoundary } else { '' }) }) -join ', '
            [pscustomobject]@{
                Name = $t.TaskName; Path = $t.TaskPath; State = [string]$t.State; StateText = $(if ($stt[[string]$t.State]) { $stt[[string]$t.State] } else { [string]$t.State })
                Last = $last; LastText = $(if ($last) { $last.ToString('dd.MM.yyyy HH:mm') } else { '' }); Next = $next; NextText = $(if ($next) { $next.ToString('dd.MM.yyyy HH:mm') } else { '' })
                ResultText = $(if (-not $last) { '' } elseif ($res.ContainsKey([int64]$code)) { $res[[int64]$code] } else { '0x{0:X8}' -f $code })
                Info = ('Aktion: {0}{1}Auslöser: {2}{1}Konto: {3}{1}{4}' -f $act, [Environment]::NewLine, $trg, $t.Principal.UserId, $t.Description)
                Level = $(if ($t.State -eq 'Disabled') { 'Off' } elseif ($last -and $code -ne 0 -and $code -ne 267009 -and $code -ne 267011) { 'Warn' } else { '' })
            }
        }
    } -Arguments @([bool]$ui.TskMs.IsChecked) -Done {
        param($r, $err)
        if ($err) { $ui.TskInfo.Text = 'Fehler: ' + $err.Message; return }
        Set-GridItems $ui.TskGrid @($r | Where-Object { $_ } | Sort-Object Path, Name)
        Update-TskFilter
        $ui.TskInfo.Text = 'Aufgabe auswählen für Details.'
    }
}
function Update-TskFilter { $script:FTsk = $ui.TskFilter.Text.Trim(); Set-GridFilter $ui.TskGrid { param($o) Test-Match $o $script:FTsk @('Name', 'Path', 'Info') } }
function Invoke-TskAction([string]$Act) {
    $t = $ui.TskGrid.SelectedItem
    if (-not $t) { return }
    try {
        switch ($Act) {
            'Run'     { Start-ScheduledTask -TaskName $t.Name -TaskPath $t.Path -ErrorAction Stop }
            'Enable'  { Enable-ScheduledTask -TaskName $t.Name -TaskPath $t.Path -ErrorAction Stop | Out-Null }
            'Disable' { Disable-ScheduledTask -TaskName $t.Name -TaskPath $t.Path -ErrorAction Stop | Out-Null }
            'Delete'  { if (-not (Confirm-Ui ('Aufgabe "{0}" endgültig löschen?' -f $t.Name) 'Warning')) { return }; Unregister-ScheduledTask -TaskName $t.Name -TaskPath $t.Path -Confirm:$false -ErrorAction Stop }
        }
        $ui.StatusText.Text = 'Aufgabe geändert: ' + $t.Name
    } catch { Show-UiError ('Nicht möglich: ' + $_.Exception.Message) }
    Update-Tasks
}

# ---- Ereignisse
function Update-Events {
    $log = switch ($ui.EvLog.SelectedIndex) { 1 { 'Application' } 2 { 'Setup' } 3 { 'Security' } 4 { 'Microsoft-Windows-WindowsUpdateClient/Operational' } 5 { 'Microsoft-Windows-User Profile Service/Operational' } 6 { 'Microsoft-Windows-PowerShell/Operational' } default { 'System' } }
    $lv = switch ($ui.EvLevel.SelectedIndex) { 1 { @(1, 2, 3) } 2 { @(0, 1, 2, 3, 4) } default { @(1, 2) } }
    $days = switch ($ui.EvDays.SelectedIndex) { 0 { 1 } 2 { 30 } default { 7 } }
    $ui.EvDetail.Text = 'Ereignisse werden eingelesen ...'
    Invoke-Bg -Script {
        param($log, $lv, $days)
        $f = @{ LogName = $log; StartTime = (Get-Date).AddDays(-$days) }
        if ($lv.Count -lt 5) { $f.Level = $lv }
        $lt = @{ 0 = 'Info'; 1 = 'Kritisch'; 2 = 'Fehler'; 3 = 'Warnung'; 4 = 'Info'; 5 = 'Ausführlich' }
        foreach ($e in @(Get-WinEvent -FilterHashtable $f -MaxEvents 2000 -ErrorAction SilentlyContinue)) {
            $m = [string]$e.Message; if (-not $m) { $m = '(keine Beschreibung verfügbar)' }
            $first = ($m -split "`r?`n" | Where-Object { $_.Trim() } | Select-Object -First 1)
            [pscustomobject]@{ Time = $e.TimeCreated; TimeText = $e.TimeCreated.ToString('dd.MM.yyyy HH:mm:ss'); LevelText = $lt[[int]$e.Level]; Source = ($e.ProviderName -replace '^Microsoft-Windows-', '')
                               Id = $e.Id; Text = $first; Message = $m; Level = $(if ($e.Level -le 2 -and $e.Level -ge 1) { 'Error' } elseif ($e.Level -eq 3) { 'Warn' } else { '' }) }
        }
    } -Arguments @($log, $lv, $days) -Done {
        param($r, $err)
        if ($err) { $ui.EvDetail.Text = 'Fehler: ' + $err.Message; return }
        $rows = @($r | Where-Object { $_ })
        Set-GridItems $ui.EvGrid $rows
        Update-EvFilter
        $ui.EvDetail.Text = if ($rows.Count) { '{0} Ereignisse (höchstens 2000). Eintrag anklicken für Details.' -f $rows.Count } else { 'Keine Ereignisse im gewählten Zeitraum.' }
    }
}
function Update-EvFilter { $script:FEv = $ui.EvFilter.Text.Trim(); Set-GridFilter $ui.EvGrid { param($o) (Test-Match $o $script:FEv @('Source', 'Message')) -or ($script:FEv -and [string]$o.Id -eq $script:FEv) } }

# ---- Benutzer und Gruppen
function Update-Users {
    try {
        $admins = @(Get-LocalGroupMember -SID 'S-1-5-32-544' -ErrorAction SilentlyContinue | ForEach-Object { [string]$_.SID })
        $rows = foreach ($u in @(Get-LocalUser)) {
            [pscustomobject]@{
                Name = $u.Name; FullName = $u.FullName; Enabled = $u.Enabled; EnabledText = $(if ($u.Enabled) { 'ja' } else { 'nein' }); IsAdmin = ($admins -contains [string]$u.SID)
                AdminText = $(if ($admins -contains [string]$u.SID) { 'ja' } else { '' }); Last = $u.LastLogon; LastText = $(if ($u.LastLogon) { $u.LastLogon.ToString('dd.MM.yyyy HH:mm') } else { 'nie' })
                PwdText = $(if ($u.PasswordLastSet) { $u.PasswordLastSet.ToString('dd.MM.yyyy') } else { '' }); Description = $u.Description; Sid = [string]$u.SID
                Level = $(if (-not $u.Enabled) { 'Off' } else { '' })
            }
        }
        Set-GridItems $ui.UsrGrid @($rows)
        Set-GridItems $ui.GrpGrid @(Get-LocalGroup | Sort-Object Name | ForEach-Object { [pscustomobject]@{ Name = $_.Name; Description = $_.Description; Sid = [string]$_.SID } })
    } catch { Show-UiError ('Benutzer konnten nicht gelesen werden (auf Windows Home eingeschränkt): ' + $_.Exception.Message) }
}
function Invoke-UserAction([string]$Act) {
    $u = $ui.UsrGrid.SelectedItem
    if ($Act -ne 'New' -and -not $u) { return }
    try {
        switch ($Act) {
            'New' {
                $r = Show-InputDialog 'Neuer Benutzer' 'Lokales Benutzerkonto auf diesem PC anlegen.' @(
                    @{ Key = 'Name'; Label = 'Benutzername'; Type = 'Text' }, @{ Key = 'Full'; Label = 'Vollständiger Name (optional)'; Type = 'Text' },
                    @{ Key = 'Pwd'; Label = 'Kennwort'; Type = 'Password' }, @{ Key = 'Pwd2'; Label = 'Kennwort wiederholen'; Type = 'Password' },
                    @{ Key = 'Admin'; Label = 'Administrator'; Type = 'Check' }, @{ Key = 'NoExp'; Label = 'Kennwort läuft nie ab'; Type = 'Check'; Value = $true })
                if (-not $r) { return }
                if (-not $r.Name) { throw 'Kein Benutzername angegeben.' }
                if ($r.Pwd -ne $r.Pwd2) { throw 'Die Kennwörter stimmen nicht überein.' }
                $p = @{ Name = $r.Name; FullName = $r.Full; PasswordNeverExpires = $r.NoExp }
                if ($r.Pwd) { $p.Password = (ConvertTo-SecureString $r.Pwd -AsPlainText -Force) } else { $p.NoPassword = $true }
                New-LocalUser @p -ErrorAction Stop | Out-Null
                Add-LocalGroupMember -SID $(if ($r.Admin) { 'S-1-5-32-544' } else { 'S-1-5-32-545' }) -Member $r.Name -ErrorAction Stop
            }
            'Pwd' {
                $r = Show-InputDialog 'Kennwort setzen' ('Neues Kennwort für {0}. Achtung: Mit EFS verschlüsselte Dateien und gespeicherte Kennwörter des Kontos gehen dabei verloren.' -f $u.Name) @(
                    @{ Key = 'Pwd'; Label = 'Neues Kennwort (leer = kein Kennwort)'; Type = 'Password' }, @{ Key = 'Pwd2'; Label = 'Wiederholen'; Type = 'Password' })
                if (-not $r) { return }
                if ($r.Pwd -ne $r.Pwd2) { throw 'Die Kennwörter stimmen nicht überein.' }
                if ($r.Pwd) { Set-LocalUser -Name $u.Name -Password (ConvertTo-SecureString $r.Pwd -AsPlainText -Force) -ErrorAction Stop }
                else { & net.exe user $u.Name '""' | Out-Null }
            }
            'Enable'  { Enable-LocalUser -Name $u.Name -ErrorAction Stop }
            'Disable' { if ($u.Name -eq $env:USERNAME) { throw 'Das eigene Konto kann hier nicht deaktiviert werden.' }; Disable-LocalUser -Name $u.Name -ErrorAction Stop }
            'Admin'   {
                if ($u.IsAdmin) {
                    if ($u.Name -eq $env:USERNAME) { throw 'Dem eigenen Konto werden die Administratorrechte hier nicht entzogen.' }
                    if (-not (Confirm-Ui ('{0} die Administratorrechte entziehen?' -f $u.Name))) { return }
                    Remove-LocalGroupMember -SID 'S-1-5-32-544' -Member $u.Name -ErrorAction Stop
                    Add-LocalGroupMember -SID 'S-1-5-32-545' -Member $u.Name -ErrorAction SilentlyContinue
                } else { if (-not (Confirm-Ui ('{0} zum Administrator machen?' -f $u.Name))) { return }; Add-LocalGroupMember -SID 'S-1-5-32-544' -Member $u.Name -ErrorAction Stop }
            }
            'Delete'  {
                if ($u.Name -eq $env:USERNAME) { throw 'Das eigene Konto kann nicht gelöscht werden.' }
                if (-not (Confirm-Ui ('Benutzer {0} löschen? Das Profil (Dateien) bleibt unter C:\Users erhalten.' -f $u.Name) 'Warning')) { return }
                Remove-LocalUser -Name $u.Name -ErrorAction Stop
            }
        }
        $ui.StatusText.Text = 'Benutzerverwaltung: erledigt.'
    } catch { Show-UiError $_.Exception.Message }
    Update-Users
}

# ---- Freigaben
function Update-Shares {
    try {
        $ses = @(Get-SmbSession -ErrorAction SilentlyContinue)
        $rows = foreach ($s in @(Get-SmbShare -ErrorAction Stop)) {
            $acc = ''; try { $acc = (Get-SmbShareAccess -Name $s.Name -ErrorAction Stop | ForEach-Object { '{0}: {1} {2}' -f $_.AccountName, $_.AccessControlType, $_.AccessRight }) -join ', ' } catch { }
            [pscustomobject]@{ Name = $s.Name; Path = $s.Path; Description = $s.Description; Access = $acc; Users = $s.CurrentUsers; Special = [bool]$s.Special
                               Level = $(if ($s.Special) { 'Off' } else { '' }) }
        }
        Set-GridItems $ui.ShrGrid @($rows | Sort-Object Special, Name)
        $conn = @()
        $conn += $ses | ForEach-Object { [pscustomobject]@{ Client = $_.ClientComputerName; User = $_.ClientUserName; Item = ('Sitzung, {0} Dateien offen' -f $_.NumOpens); Since = $(if ($_.SecondsExists) { '{0:N0} min' -f ($_.SecondsExists / 60) } else { '' }) } }
        $conn += @(Get-SmbOpenFile -ErrorAction SilentlyContinue) | ForEach-Object { [pscustomobject]@{ Client = $_.ClientComputerName; User = $_.ClientUserName; Item = $_.Path; Since = '' } }
        Set-GridItems $ui.SesGrid $conn
    } catch { Show-UiError ('Freigaben konnten nicht gelesen werden: ' + $_.Exception.Message) }
}
function Invoke-ShareAction([string]$Act) {
    try {
        switch ($Act) {
            'New' {
                $r = Show-InputDialog 'Ordner freigeben' 'Ordner im Netzwerk freigeben (Zugriff nur für Benutzer mit Konto auf diesem PC).' @(
                    @{ Key = 'Path'; Label = 'Ordner'; Type = 'Folder' }, @{ Key = 'Name'; Label = 'Freigabename (leer = Ordnername)'; Type = 'Text' },
                    @{ Key = 'Right'; Label = 'Rechte für "Jeder"'; Type = 'Combo'; Items = @('Lesen', 'Ändern', 'Vollzugriff') })
                if (-not $r -or -not $r.Path) { return }
                if (-not (Test-Path -LiteralPath $r.Path -PathType Container)) { throw 'Der Ordner existiert nicht.' }
                $n = if ($r.Name) { $r.Name } else { Split-Path $r.Path -Leaf }
                $sid = (New-Object Security.Principal.SecurityIdentifier 'S-1-1-0').Translate([Security.Principal.NTAccount]).Value
                $p = @{ Name = $n; Path = $r.Path }
                switch ($r.Right) { 'Lesen' { $p.ReadAccess = $sid } 'Ändern' { $p.ChangeAccess = $sid } default { $p.FullAccess = $sid } }
                New-SmbShare @p -ErrorAction Stop | Out-Null
            }
            'Remove' {
                $s = $ui.ShrGrid.SelectedItem; if (-not $s) { return }
                if ($s.Special) { throw 'Administrative Freigaben (mit $) verwaltet Windows selbst.' }
                if (-not (Confirm-Ui ('Freigabe "{0}" entfernen? Der Ordner selbst bleibt erhalten.' -f $s.Name))) { return }
                Remove-SmbShare -Name $s.Name -Force -ErrorAction Stop
            }
            'Open' { $s = $ui.ShrGrid.SelectedItem; if ($s -and $s.Path -and (Test-Path -LiteralPath $s.Path)) { Start-Process explorer.exe $s.Path } }
        }
    } catch { Show-UiError $_.Exception.Message }
    if ($Act -ne 'Open') { Update-Shares }
}

# ---- Programme
function Update-Programs {
    $window.Cursor = 'Wait'
    try { Set-GridItems $ui.PrgGrid (Get-InstalledPrograms); Update-PrgFilter; $ui.PrgInfo.Text = '{0} Programme. Programm auswählen für Details.' -f $ui.PrgGrid.Items.Count }
    catch { Show-UiError $_.Exception.Message }
    finally { $window.Cursor = $null }
}
function Update-PrgFilter { $script:FPrg = $ui.PrgFilter.Text.Trim(); Set-GridFilter $ui.PrgGrid { param($o) Test-Match $o $script:FPrg @('Name', 'Publisher', 'Version') } }
function Invoke-PrgUninstall {
    $p = $ui.PrgGrid.SelectedItem
    if (-not $p) { return }
    $cmd = if ($p.Uninstall) { $p.Uninstall } else { $p.QuietUninstall }
    if (-not $cmd) { Show-UiError 'Für dieses Programm ist keine Deinstallation hinterlegt.'; return }
    if (-not (Confirm-Ui ('{0} deinstallieren? Das Deinstallationsprogramm des Herstellers wird gestartet.' -f $p.Name))) { return }
    try {
        if ($cmd -match '(?i)msiexec(\.exe)?\s+/[IX]\s*(\{[0-9A-F\-]+\})') { Start-Process msiexec.exe -ArgumentList ('/x {0}' -f $Matches[2]) }
        elseif ($cmd -match '^\s*"([^"]+)"\s*(.*)$') { if ($Matches[2]) { Start-Process -FilePath $Matches[1] -ArgumentList $Matches[2] } else { Start-Process -FilePath $Matches[1] } }
        else { Start-Process cmd.exe -ArgumentList ('/c "{0}"' -f $cmd) -WindowStyle Hidden }
        $ui.StatusText.Text = 'Deinstallation gestartet: ' + $p.Name + ' - danach "Aktualisieren" klicken.'
    } catch { Show-UiError ('Start fehlgeschlagen: ' + $_.Exception.Message) }
}


# ---- Datenträger bereinigen, initialisieren, formatieren (aus DiskCleaner übernommen)
$dkSync = [hashtable]::Synchronized(@{ Log = New-Object 'System.Collections.Concurrent.ConcurrentQueue[string]'; Process = $null; Cancel = $false; Success = $false })
$script:DkJob = $null
$DkLabelMax = @{ NTFS = 32; ReFS = 32; exFAT = 15; FAT32 = 11 }
$DkClusterValues = @(0, 4096, 8192, 16384, 32768, 65536)
$DkStyleValues = @('GPT', 'MBR', 'RAW')
$DkWorker = {
    param($sync, $opt)
    function Write-Log([string]$Message) { $sync.Log.Enqueue(('[{0:HH:mm:ss}] {1}' -f (Get-Date), $Message)) }
    $n = [int]$opt.DiskNumber
    $shellHw = Get-Service -Name ShellHWDetection -ErrorAction SilentlyContinue
    $shellHwWasRunning = ($shellHw -and $shellHw.Status -eq 'Running')
    try {
        Import-Module Storage -ErrorAction Stop
        $disk = Get-Disk -Number $n -ErrorAction Stop
        if ($disk.IsBoot -or $disk.IsSystem) { throw "Datenträger $n ist ein System-/Bootlaufwerk - Vorgang gesperrt." }
        Write-Log "=== Start: Datenträger $n - $($disk.FriendlyName) ==="
        if ($shellHwWasRunning) { Stop-Service -Name ShellHWDetection -Force -ErrorAction SilentlyContinue }
        if ($disk.IsOffline)  { Write-Log 'Setze Datenträger online ...'; Set-Disk -Number $n -IsOffline $false }
        if ($disk.IsReadOnly) { Write-Log 'Entferne Schreibschutz-Attribut ...'; Set-Disk -Number $n -IsReadOnly $false }
        if ($opt.SecureWipe) {
            if ($sync.Cancel) { throw 'Vom Benutzer abgebrochen.' }
            Write-Log 'Sicheres Überschreiben gestartet (diskpart clean all) - das kann mehrere Stunden dauern ...'
            $scriptFile = Join-Path $env:TEMP ('diskclean_{0}.txt' -f [guid]::NewGuid())
            Set-Content -Path $scriptFile -Value @("select disk $n", 'clean all') -Encoding Ascii
            $psi = New-Object System.Diagnostics.ProcessStartInfo
            $psi.FileName = 'diskpart.exe'; $psi.Arguments = "/s `"$scriptFile`""
            $psi.UseShellExecute = $false; $psi.CreateNoWindow = $true; $psi.RedirectStandardOutput = $true
            $psi.StandardOutputEncoding = [Text.Encoding]::GetEncoding([Globalization.CultureInfo]::CurrentCulture.TextInfo.OEMCodePage)
            $proc = [System.Diagnostics.Process]::Start($psi)
            $sync.Process = $proc
            $output = $proc.StandardOutput.ReadToEnd()
            $proc.WaitForExit()
            $sync.Process = $null
            Remove-Item -Path $scriptFile -ErrorAction SilentlyContinue
            if ($sync.Cancel) { throw 'Überschreiben abgebrochen. Die Platte ist nur teilweise überschrieben und hat keine Partitionstabelle mehr.' }
            $output -split "`r?`n" | Where-Object { $_.Trim() } | Select-Object -Last 3 | ForEach-Object { Write-Log "  diskpart: $($_.Trim())" }
            if ($proc.ExitCode -ne 0) { throw "diskpart meldete einen Fehler (Exitcode $($proc.ExitCode))." }
            Write-Log 'Sicheres Überschreiben abgeschlossen.'
        } elseif ($disk.PartitionStyle -ne 'RAW') {
            Write-Log 'Entferne alle Partitionen inkl. EFI/OEM (Clear-Disk) ...'
            Clear-Disk -Number $n -RemoveData -RemoveOEM -Confirm:$false
            Write-Log 'Partitionstabelle gelöscht.'
        } else { Write-Log 'Datenträger ist bereits leer (RAW).' }
        Update-HostStorageCache
        $disk = Get-Disk -Number $n
        if ($opt.PartitionStyle -eq 'RAW') { Write-Log 'Keine Initialisierung - Datenträger bleibt RAW.' }
        else {
            Write-Log "Initialisiere als $($opt.PartitionStyle) ..."
            if ($disk.PartitionStyle -eq 'RAW') { Initialize-Disk -Number $n -PartitionStyle $opt.PartitionStyle } else { Set-Disk -Number $n -PartitionStyle $opt.PartitionStyle }
            Write-Log 'Initialisierung abgeschlossen.'
        }
        if ($opt.CreatePartition) {
            $np = @{ DiskNumber = $n }
            if ([uint64]$opt.SizeBytes -gt 0) { $np.Size = [uint64]$opt.SizeBytes } else { $np.UseMaximumSize = $true }
            if ($opt.DriveLetter -eq 'AUTO') { $np.AssignDriveLetter = $true } elseif ($opt.DriveLetter) { $np.DriveLetter = [char]$opt.DriveLetter }
            Write-Log 'Lege Partition an ...'
            $part = New-Partition @np
            Write-Log ('Partition {0} angelegt ({1:N2} GB).' -f $part.PartitionNumber, ($part.Size / 1GB))
            $fv = @{ Partition = $part; FileSystem = $opt.FileSystem; Force = $true; Confirm = $false }
            if ($opt.Label) { $fv.NewFileSystemLabel = $opt.Label }
            if ([int]$opt.AllocationUnitSize -gt 0) { $fv.AllocationUnitSize = [uint32]$opt.AllocationUnitSize }
            if ($opt.FullFormat) { $fv.Full = $true; Write-Log "Vollständige Formatierung mit $($opt.FileSystem) - das dauert je nach Größe lange ..." }
            else { Write-Log "Schnellformatierung mit $($opt.FileSystem) ..." }
            $vol = Format-Volume @fv
            Write-Log 'Formatierung abgeschlossen.'
            $part = Get-Partition -DiskNumber $n -PartitionNumber $part.PartitionNumber
            $hasLetter = ($part.DriveLetter -and [int][char]$part.DriveLetter -ne 0)
            if (-not $opt.DriveLetter -and $hasLetter) {
                Remove-PartitionAccessPath -DiskNumber $n -PartitionNumber $part.PartitionNumber -AccessPath "$($part.DriveLetter):\"
                $hasLetter = $false
            }
            $letterInfo = if ($hasLetter) { "Laufwerk $($part.DriveLetter):" } else { 'ohne Laufwerksbuchstaben' }
            Write-Log ("Volume bereit: {0}, {1:N2} GB, Bezeichnung '{2}', {3}" -f $vol.FileSystem, ($vol.Size / 1GB), $vol.FileSystemLabel, $letterInfo)
        }
        $sync.Success = $true
        Write-Log '=== Alle Schritte erfolgreich abgeschlossen ==='
    } catch {
        $sync.Success = $false
        Write-Log "FEHLER: $($_.Exception.Message)"
    } finally {
        $sync.Process = $null
        if ($shellHwWasRunning) { Start-Service -Name ShellHWDetection -ErrorAction SilentlyContinue }
    }
}
$SmartNames = @{
    1 = 'Lesefehlerrate'; 2 = 'Durchsatzleistung'; 3 = 'Anlaufzeit'; 4 = 'Start/Stopp-Zähler'; 5 = 'Neu zugewiesene Sektoren'; 7 = 'Suchfehlerrate'; 8 = 'Suchzeit-Leistung'; 9 = 'Betriebsstunden'
    10 = 'Spin-Retry-Zähler'; 11 = 'Kalibrierungs-Wiederholungen'; 12 = 'Einschaltvorgänge'; 13 = 'Soft-Lesefehlerrate'; 160 = 'Nicht korrigierbare Sektoren'; 161 = 'Gültige Reserveblöcke'
    163 = 'Anfängliche defekte Blöcke'; 164 = 'Gesamt-Löschzähler'; 165 = 'Max. Löschzähler'; 166 = 'Min. Löschzähler'; 167 = 'Durchschn. Löschzähler'; 168 = 'SATA-PHY-Fehler'
    169 = 'Verbleibende Lebensdauer'; 170 = 'Reserveblöcke verfügbar'; 171 = 'Programmierfehler'; 172 = 'Löschfehler'; 173 = 'Wear-Leveling-Zähler'; 174 = 'Unerwartete Stromausfälle'
    175 = 'Programmierfehler (Worst Die)'; 176 = 'Löschfehler'; 177 = 'Wear-Leveling-Zähler'; 178 = 'Reserveblöcke genutzt (Chip)'; 179 = 'Reserveblöcke genutzt (gesamt)'; 180 = 'Freie Reserveblöcke'
    181 = 'Programmierfehler'; 182 = 'Löschfehler'; 183 = 'Runtime Bad Blocks'; 184 = 'End-to-End-Fehler'; 187 = 'Nicht korrigierbare Fehler'; 188 = 'Befehls-Timeouts'; 189 = 'High Fly Writes'
    190 = 'Luftstromtemperatur'; 191 = 'Erschütterungsfehler'; 192 = 'Notabschaltungen'; 193 = 'Lade-/Entladezyklen'; 194 = 'Temperatur'; 195 = 'ECC-Korrekturen'
    196 = 'Neuzuweisungs-Ereignisse'; 197 = 'Schwebende Sektoren'; 198 = 'Nicht korrigierbare Sektoren (offline)'; 199 = 'UltraDMA-CRC-Fehler (Kabel)'; 200 = 'Schreibfehlerrate'; 202 = 'Verbrauchte Lebensdauer'
    206 = 'Flughöhe'; 220 = 'Plattenverschiebung'; 222 = 'Geladene Stunden'; 223 = 'Lade-Wiederholungen'; 224 = 'Lade-Reibung'; 225 = 'Lade-/Entladezyklen'; 226 = 'Ladezeit'; 230 = 'GMR-Kopf-Amplitude'
    231 = 'Verbleibende Lebensdauer (SSD)'; 232 = 'Reserve verfügbar'; 233 = 'Media Wearout Indicator'; 234 = 'Durchschn./Max. Löschzähler'; 235 = 'Gute Blöcke / Systemblöcke'; 240 = 'Kopf-Flugstunden'
    241 = 'Geschriebene Daten (LBAs)'; 242 = 'Gelesene Daten (LBAs)'; 244 = 'Durchschn. Löschzähler'; 249 = 'NAND-Schreibvorgänge'; 250 = 'Lese-Wiederholungen'; 254 = 'Freifall-Schutz'
}
$SmartCritical = @(5, 10, 184, 187, 188, 196, 197, 198)
function Format-Size([double]$Bytes) { if ($Bytes -ge 1TB) { '{0:N2} TB' -f ($Bytes / 1TB) } elseif ($Bytes -ge 1GB) { '{0:N2} GB' -f ($Bytes / 1GB) } else { '{0:N0} MB' -f ($Bytes / 1MB) } }
function Write-DkLog([string]$Message) { $dkSync.Log.Enqueue(('[{0:HH:mm:ss}] {1}' -f (Get-Date), $Message)) }
function Get-DiskHealth($Disk) {
    $summary = [System.Collections.Generic.List[object]]::new()
    $attrs = [System.Collections.Generic.List[object]]::new()
    $note = ''
    $v = { param($x, $suffix = '') if ($null -eq $x -or "$x" -eq '') { '-' } else { "$x$suffix" } }
    $add = { param($n, $val, $lvl) $summary.Add([pscustomobject]@{ Name = $n; Value = $val; Level = $(switch ($lvl) { 'Unhealthy' { 'Error' } 'Warning' { 'Warn' } 'Healthy' { 'Good' } default { '' } }) }) }
    $pd = $null; try { $pd = Get-PhysicalDisk -ErrorAction Stop | Where-Object { [string]$_.DeviceId -eq [string]$Disk.Number } | Select-Object -First 1 } catch { }
    $rc = $null; if ($pd) { try { $rc = Get-StorageReliabilityCounter -PhysicalDisk $pd -ErrorAction Stop } catch { } }
    $predict = $null; $smartData = $null; $smartThresh = $null
    try {
        $dd = Get-CimInstance -ClassName Win32_DiskDrive -Filter "Index=$($Disk.Number)" -ErrorAction Stop
        if ($dd) {
            $pnp = [string]$dd.PNPDeviceID
            $match = { param($o) ([string]$o.InstanceName).StartsWith($pnp, [StringComparison]::OrdinalIgnoreCase) }
            $predict = Get-CimInstance -Namespace root\wmi -ClassName MSStorageDriver_FailurePredictStatus -ErrorAction SilentlyContinue | Where-Object { & $match $_ } | Select-Object -First 1
            $smartData = Get-CimInstance -Namespace root\wmi -ClassName MSStorageDriver_ATAPISmartData -ErrorAction SilentlyContinue | Where-Object { & $match $_ } | Select-Object -First 1
            $smartThresh = Get-CimInstance -Namespace root\wmi -ClassName MSStorageDriver_FailurePredictThresholds -ErrorAction SilentlyContinue | Where-Object { & $match $_ } | Select-Object -First 1
        }
    } catch { }
    $health = if ($pd) { [string]$pd.HealthStatus } else { [string]$Disk.HealthStatus }
    $healthDe = switch ($health) { 'Healthy' { 'Gut' } 'Warning' { 'Warnung' } 'Unhealthy' { 'Kritisch' } default { & $v $health } }
    & $add 'Gesamtzustand (Windows)' $healthDe $health
    $predText = if ($predict) { if ($predict.PredictFailure) { 'JA - Ausfall droht!' } else { 'Nein' } } else { 'nicht verfügbar' }
    & $add 'SMART-Ausfallvorhersage' $predText $(if ($predict -and $predict.PredictFailure) { 'Unhealthy' } else { '' })
    & $add 'Betriebsstatus' (& $v (($pd.OperationalStatus) -join ', ')) ''
    & $add 'Medientyp / Bus' ('{0} / {1}' -f (& $v $pd.MediaType), (& $v $Disk.BusType)) ''
    & $add 'Firmware' (& $v $pd.FirmwareVersion) ''
    if ($rc) {
        & $add 'Temperatur' $(if ($rc.Temperature) { "$($rc.Temperature) °C" + $(if ($rc.TemperatureMax) { " (max. $($rc.TemperatureMax) °C)" } else { '' }) } else { '-' }) ''
        & $add 'Betriebsstunden' $(if ($rc.PowerOnHours) { '{0:N0} h (~{1:N1} Jahre)' -f $rc.PowerOnHours, ($rc.PowerOnHours / 8760) } else { '-' }) ''
        & $add 'Verschleiß (SSD)' (& $v $rc.Wear ' %') $(if ($rc.Wear -ge 90) { 'Unhealthy' } elseif ($rc.Wear -ge 70) { 'Warning' } else { '' })
        & $add 'Lesefehler gesamt / unkorr.' ('{0} / {1}' -f (& $v $rc.ReadErrorsTotal), (& $v $rc.ReadErrorsUncorrected)) $(if ([uint64]$rc.ReadErrorsUncorrected -gt 0) { 'Warning' } else { '' })
        & $add 'Schreibfehler gesamt / unkorr.' ('{0} / {1}' -f (& $v $rc.WriteErrorsTotal), (& $v $rc.WriteErrorsUncorrected)) $(if ([uint64]$rc.WriteErrorsUncorrected -gt 0) { 'Warning' } else { '' })
        & $add 'Start/Stopp-Zyklen' (& $v $rc.StartStopCycleCount) ''
        & $add 'Lade-/Entladezyklen' (& $v $rc.LoadUnloadCycleCount) ''
    } else { & $add 'Zuverlässigkeitszähler' 'nicht verfügbar (z.B. USB-Gehäuse)' '' }
    if ($smartData -and $smartData.VendorSpecific) {
        $b = [byte[]]$smartData.VendorSpecific
        $th = @{}
        if ($smartThresh -and $smartThresh.VendorSpecific) {
            $t = [byte[]]$smartThresh.VendorSpecific
            for ($i = 0; $i -lt 30; $i++) { $o = 2 + $i * 12; if ($o + 1 -lt $t.Length -and $t[$o] -ne 0) { $th[[int]$t[$o]] = [int]$t[$o + 1] } }
        }
        for ($i = 0; $i -lt 30; $i++) {
            $o = 2 + $i * 12
            if ($o + 11 -ge $b.Length) { break }
            $id = [int]$b[$o]; if ($id -eq 0) { continue }
            $cur = [int]$b[$o + 3]; $worst = [int]$b[$o + 4]
            [uint64]$raw = 0; for ($k = 5; $k -ge 0; $k--) { $raw = $raw * 256 + $b[$o + 5 + $k] }
            $rawText = switch ($id) { { $_ -in 190, 194 } { '{0} °C' -f $b[$o + 5] } 9 { '{0:N0} h' -f ($raw -band 0xFFFFFFFF) } default { '{0:N0}' -f $raw } }
            $thr = if ($th.ContainsKey($id)) { $th[$id] } else { 0 }
            $level = ''; $state = 'OK'
            if ($thr -gt 0 -and $cur -le $thr) { $level = 'Error'; $state = 'FEHLER (Schwelle)' }
            elseif ($SmartCritical -contains $id -and $raw -gt 0) { $level = 'Warn'; $state = 'Warnung' }
            elseif ($id -eq 199 -and $raw -gt 0) { $level = 'Warn'; $state = 'Kabel prüfen' }
            $attrs.Add([pscustomobject]@{ Id = ('{0} (0x{0:X2})' -f $id); Name = $(if ($SmartNames.ContainsKey($id)) { $SmartNames[$id] } else { 'Herstellerspezifisch' }); Cur = $cur; Worst = $worst
                                          Thr = $(if ($thr) { $thr } else { '-' }); Raw = $rawText; State = $state; Level = $level })
        }
    } else { $note = 'Keine SMART-Rohdaten über Windows verfügbar (typisch bei NVMe und vielen USB-Gehäusen) - links stehen die Windows-Zuverlässigkeitszähler.' }
    return [pscustomobject]@{ Summary = $summary; Attributes = $attrs; Note = $note }
}
function Update-DiskList([int]$Select = -1) {
    $window.Cursor = 'Wait'
    try {
        try { Update-HostStorageCache -ErrorAction SilentlyContinue } catch { }
        $physical = @{}; Get-PhysicalDisk -ErrorAction SilentlyContinue | ForEach-Object { $physical[[string]$_.DeviceId] = $_ }
        $rows = foreach ($d in @(Get-Disk | Sort-Object Number)) {
            $pd = $physical[[string]$d.Number]
            $locked = ($d.IsBoot -or $d.IsSystem)
            $status = [string]$d.OperationalStatus; if ($d.IsReadOnly) { $status += ', schreibgeschützt' }
            $health = if ($pd) { [string]$pd.HealthStatus } else { [string]$d.HealthStatus }
            [pscustomobject]@{
                Number = $d.Number; Model = [string]$d.FriendlyName; Serial = ([string]$d.SerialNumber).Trim(); Bus = [string]$d.BusType
                Media = $(if ($pd -and [string]$pd.MediaType -ne 'Unspecified') { [string]$pd.MediaType } else { '-' }); Size = [double]$d.Size; SizeText = (Format-Size $d.Size)
                Style = [string]$d.PartitionStyle; Status = $status; HealthText = $(switch ($health) { 'Healthy' { 'Gut' } 'Warning' { 'Warnung' } 'Unhealthy' { 'Kritisch' } default { '-' } })
                Hint = $(if ($locked) { 'Windows-Systemlaufwerk - gesperrt' } else { '' }); Locked = $locked; Disk = $d
                Level = $(switch ($health) { 'Unhealthy' { 'Error' } 'Warning' { 'Warn' } default { if ($locked) { 'Off' } else { '' } } })
            }
        }
        Set-GridItems $ui.DkGrid @($rows)
        if ($Select -ge 0) { $ui.DkGrid.SelectedItem = @($rows | Where-Object Number -eq $Select)[0] }
        Update-DkLetters
        Update-DkState
    } finally { $window.Cursor = $null }
}
function Get-DkFreeLetters {
    $used = @(); $used += Get-Volume -ErrorAction SilentlyContinue | Where-Object DriveLetter | ForEach-Object { [string]$_.DriveLetter }
    $used += Get-PSDrive -PSProvider FileSystem | ForEach-Object { [string]$_.Name }
    foreach ($c in 68..90) { $l = [string][char]$c; if ($used -notcontains $l) { $l } }
}
function Update-DkLetters {
    $cur = [string]$ui.DkLetter.SelectedItem
    $ui.DkLetter.Items.Clear()
    foreach ($x in @('Automatisch', 'Keiner') + @(Get-DkFreeLetters | ForEach-Object { "${_}:" })) { [void]$ui.DkLetter.Items.Add($x) }
    $i = $ui.DkLetter.Items.IndexOf($cur); $ui.DkLetter.SelectedIndex = $(if ($i -ge 0) { $i } else { 0 })
}
function Update-DkDetails {
    $sel = $ui.DkGrid.SelectedItem
    Set-GridItems $ui.DkParts @(); Set-GridItems $ui.DkHealth @(); Set-GridItems $ui.DkSmart @()
    if (-not $sel) { Update-DkState; return }
    $window.Cursor = 'Wait'
    try {
        $parts = foreach ($p in @(Get-Partition -DiskNumber $sel.Number -ErrorAction SilentlyContinue)) {
            $vol = $null; try { $vol = Get-Volume -Partition $p -ErrorAction Stop } catch { }
            [pscustomobject]@{ Number = $p.PartitionNumber; Letter = $(if ($p.DriveLetter -and [int][char]$p.DriveLetter -ne 0) { "$($p.DriveLetter):" } else { '' }); Type = [string]$p.Type
                               SizeText = (Format-Size $p.Size); FileSystem = $(if ($vol) { [string]$vol.FileSystem } else { '' }); Label = $(if ($vol) { [string]$vol.FileSystemLabel } else { '' }) }
        }
        if (-not $parts) { $parts = @([pscustomobject]@{ Number = '-'; Letter = ''; Type = '(keine Partitionen)'; SizeText = ''; FileSystem = ''; Label = '' }) }
        Set-GridItems $ui.DkParts @($parts)
        $h = Get-DiskHealth $sel.Disk
        Set-GridItems $ui.DkHealth @($h.Summary)
        Set-GridItems $ui.DkSmart @($h.Attributes)
        $ui.DkSmartTitle.Text = if ($h.Note) { 'SMART-Attribute - ' + $h.Note } else { 'SMART-Attribute' }
        $max = [math]::Max(1, [math]::Floor($sel.Size / 1GB)); $ui.DkSize.Text = [string]$max
    } catch { Show-UiError $_.Exception.Message }
    finally { $window.Cursor = $null }
    Update-DkState
}
function Update-DkState {
    $busy = [bool]$script:DkJob
    $sel = $ui.DkGrid.SelectedItem
    $raw = ($ui.DkStyle.SelectedIndex -eq 2)
    $ui.DkGrid.IsEnabled = -not $busy
    $ui.BtnDkRefresh.IsEnabled = -not $busy
    $ui.DkCreate.IsEnabled = -not $raw -and -not $busy
    $fmt = (-not $raw) -and [bool]$ui.DkCreate.IsChecked -and -not $busy
    foreach ($c in 'DkFs', 'DkCluster', 'DkLabel', 'DkLetter', 'DkMax', 'DkFQuick', 'DkFFull') { $ui[$c].IsEnabled = $fmt }
    $ui.DkSize.IsEnabled = $fmt -and -not [bool]$ui.DkMax.IsChecked
    foreach ($c in 'DkQuick', 'DkSecure', 'DkStyle') { $ui[$c].IsEnabled = -not $busy }
    $ui.DkRun.IsEnabled = (-not $busy) -and $sel -and -not $sel.Locked
    $ui.DkCancel.IsEnabled = $busy -and $script:DkJob.Secure
}
function Show-DangerConfirm([string]$Summary, [int]$DiskNumber) {
    $x = @"
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Title="Bestätigung erforderlich" Width="500" SizeToContent="Height" WindowStartupLocation="CenterOwner" ResizeMode="NoResize" FontFamily="Segoe UI" FontSize="13">
  <StackPanel Margin="20">
    <TextBlock Text="$(Esc $Summary)" TextWrapping="Wrap"/>
    <TextBlock Text="ALLE DATEN AUF DIESEM DATENTRÄGER WERDEN UNWIDERRUFLICH GELÖSCHT!" Foreground="#C81E1E" FontWeight="Bold" TextWrapping="Wrap" Margin="0,14,0,10"/>
    <CheckBox x:Name="Chk" Content="Ja, Datenträger $DiskNumber wirklich löschen"/>
    <StackPanel Orientation="Horizontal" HorizontalAlignment="Right" Margin="0,18,0,0">
      <Button x:Name="Ok" Content="Löschen starten" Width="140" Padding="0,7" Margin="0,0,8,0" IsEnabled="False"/>
      <Button x:Name="No" Content="Abbrechen" Width="110" Padding="0,7" IsCancel="True" IsDefault="True"/>
    </StackPanel>
  </StackPanel>
</Window>
"@
    $w = [Windows.Markup.XamlReader]::Parse($x); $w.Owner = $window
    $chk = $w.FindName('Chk'); $ok = $w.FindName('Ok')
    $chk.Add_Click({ $ok.IsEnabled = [bool]$chk.IsChecked }.GetNewClosure())
    $ok.Add_Click({ $w.DialogResult = $true }.GetNewClosure())
    return ([bool]$w.ShowDialog() -and [bool]$chk.IsChecked)
}
function Start-DiskJob {
    $sel = $ui.DkGrid.SelectedItem
    if (-not $sel) { return }
    $d = Get-Disk -Number $sel.Number
    if ($d.IsBoot -or $d.IsSystem) { Show-UiError 'Das ist ein Windows-System-/Bootlaufwerk und kann hier nicht bearbeitet werden.'; return }
    $style = $DkStyleValues[$ui.DkStyle.SelectedIndex]
    $create = ([bool]$ui.DkCreate.IsChecked -and $style -ne 'RAW')
    $fs = [string]$ui.DkFs.SelectedItem.Content
    $label = $ui.DkLabel.Text.Trim()
    $sizeBytes = [uint64]0; $letter = ''
    $cluster = $DkClusterValues[[math]::Max(0, $ui.DkCluster.SelectedIndex)]
    $max = [bool]$ui.DkMax.IsChecked
    $gb = 0; [void][int]::TryParse($ui.DkSize.Text.Trim(), [ref]$gb)
    if ($create) {
        if (-not $max -and $gb -lt 1) { Show-UiError 'Bitte eine gültige Größe in GB angeben.'; return }
        $partBytes = if ($max) { [double]$d.Size } else { [double]$gb * 1GB }
        if (-not $max) { $sizeBytes = [uint64]([double]$gb * 1GB) }
        if ($label.Length -gt $DkLabelMax[$fs]) { Show-UiError ("Die Bezeichnung darf bei $fs höchstens $($DkLabelMax[$fs]) Zeichen lang sein."); return }
        if ($fs -eq 'FAT32' -and $partBytes -gt 32GB) { Show-UiError "Windows kann FAT32 nur bis 32 GB formatieren. Bitte exFAT wählen oder eine kleinere Größe angeben."; return }
        if ($style -eq 'MBR' -and $partBytes -gt 2TB) { Show-UiError "MBR unterstützt Partitionen nur bis 2 TB. Bitte GPT wählen oder eine kleinere Größe angeben."; return }
        $letter = switch ($ui.DkLetter.SelectedIndex) { 0 { 'AUTO' } 1 { '' } default { ([string]$ui.DkLetter.SelectedItem).TrimEnd(':') } }
    } elseif ($style -eq 'MBR' -and $d.Size -gt 2TB) {
        if (-not (Confirm-Ui "Die Platte ist größer als 2 TB. Mit MBR sind nur 2 TB nutzbar. Trotzdem fortfahren?" 'Warning')) { return }
    }
    $nl = [Environment]::NewLine
    $summary = "Datenträger $($d.Number): $($d.FriendlyName) ($(Format-Size $d.Size))$nl$nl"
    $summary += '1. Bereinigen: ' + $(if ($ui.DkSecure.IsChecked) { 'sicher überschreiben (dauert Stunden)' } else { 'schnell' }) + $nl
    $summary += "2. Partitionsstil: $style$nl"
    if ($create) {
        $sizeText = if ($max) { 'maximal' } else { "$gb GB" }
        $letterText = switch ($letter) { 'AUTO' { 'automatisch' } '' { 'keiner' } default { "${letter}:" } }
        $summary += "3. Partition: $sizeText, $fs, Laufwerk $letterText, " + $(if ($ui.DkFFull.IsChecked) { 'vollständig' } else { 'schnell' })
    }
    if (-not (Show-DangerConfirm $summary $d.Number)) { Write-DkLog 'Abgebrochen - nichts wurde verändert.'; return }
    $opt = @{ DiskNumber = [int]$d.Number; SecureWipe = [bool]$ui.DkSecure.IsChecked; PartitionStyle = $style; CreatePartition = $create; FileSystem = $fs; Label = $label
              DriveLetter = $letter; SizeBytes = $sizeBytes; AllocationUnitSize = $cluster; FullFormat = [bool]$ui.DkFFull.IsChecked }
    $dkSync.Cancel = $false; $dkSync.Success = $false; $dkSync.Process = $null
    $rs = [runspacefactory]::CreateRunspace(); $rs.Open()
    $ps = [powershell]::Create(); $ps.Runspace = $rs
    [void]$ps.AddScript($DkWorker.ToString()).AddArgument($dkSync).AddArgument($opt)
    $script:DkJob = [pscustomobject]@{ PS = $ps; Runspace = $rs; Handle = $ps.BeginInvoke(); Start = Get-Date; Secure = $opt.SecureWipe; DiskNumber = $opt.DiskNumber }
    $ui.DkProgress.IsIndeterminate = $true
    Update-DkState
}
$dkTimer = New-Object System.Windows.Threading.DispatcherTimer
$dkTimer.Interval = [TimeSpan]::FromMilliseconds(300)
$dkTimer.Add_Tick({
    $line = $null
    while ($dkSync.Log.TryDequeue([ref]$line)) { $ui.DkLog.AppendText($line + [Environment]::NewLine); $ui.DkLog.ScrollToEnd() }
    if (-not $script:DkJob) { return }
    $el = (Get-Date) - $script:DkJob.Start
    $ui.DkStatus.Text = 'Läuft ... ' + $el.ToString('hh\:mm\:ss') + '  (PC-Tools nicht schließen)'
    if ($script:DkJob.Handle.IsCompleted) {
        try { [void]$script:DkJob.PS.EndInvoke($script:DkJob.Handle) } catch { Write-DkLog ('FEHLER: ' + $_.Exception.Message); $dkSync.Success = $false }
        $script:DkJob.PS.Dispose(); $script:DkJob.Runspace.Dispose()
        $no = $script:DkJob.DiskNumber; $script:DkJob = $null
        $ui.DkProgress.IsIndeterminate = $false
        $dur = $el.ToString('hh\:mm\:ss')
        Update-DiskList -Select $no
        if ($dkSync.Success) { $ui.DkStatus.Text = "Fertig nach $dur."; [Windows.MessageBox]::Show((T ("Vorgang erfolgreich abgeschlossen ($dur).")), (T ('PC-Tools')), 'OK', 'Information') | Out-Null }
        else { $ui.DkStatus.Text = 'Mit Fehler beendet - siehe Protokoll.'; Show-UiError 'Der Vorgang wurde mit einem Fehler beendet. Details stehen im Protokoll darunter.' }
    }
})


# ---------------------------------------------------------------- Treiber (Oberfläche)
$script:DrvLoaded = $false
function Update-GpuPanel {
    $ui.GpuPanel.Children.Clear()
    $t = New-Object Windows.Controls.TextBlock; $t.Text = 'Grafikkarten werden geprüft ...'; $t.Foreground = New-UiBrush '#6B7890'
    [void]$ui.GpuPanel.Children.Add($t)
    Invoke-Bg -Script {
        foreach ($g in (Get-GpuList)) {
            $latest = $null; $err = ''
            if ($g.Vendor -eq 'NVIDIA') { try { $latest = Get-NvidiaLatest $g.Name } catch { $err = $_.Exception.Message } }
            elseif ($g.Vendor -eq 'Intel') { try { $latest = Get-IntelGfxOffer $g } catch { $err = $_.Exception.Message } }
            [pscustomobject]@{ Gpu = $g; Latest = $latest; Error = $err }
        }
    } -Functions @('Get-GpuList', 'Get-NvidiaLatest', 'Get-IntelGfxPageId', 'Get-WebHtml', 'Get-IntelDownloadInfo', 'Get-IntelGfxOffer') -Done {
        param($r, $err)
        $ui.GpuPanel.Children.Clear()
        if ($err) { $t = New-Object Windows.Controls.TextBlock; $t.Text = 'Fehler: ' + $err.Message; [void]$ui.GpuPanel.Children.Add($t); return }
        foreach ($x in @($r | Where-Object { $_ })) {
            $g = $x.Gpu
            $sp = New-Object Windows.Controls.StackPanel; $sp.Margin = '0,0,0,10'
            $n = New-Object Windows.Controls.TextBlock; $n.Text = $g.Name; $n.FontWeight = 'SemiBold'; $n.FontSize = 14; $n.Foreground = New-UiBrush '#1F2A44'
            $v = New-Object Windows.Controls.TextBlock; $v.Foreground = New-UiBrush '#6B7890'
            $v.Text = 'Installiert: {0} vom {1}' -f $(if ($g.NvVersion) { '{0} ({1})' -f $g.NvVersion, $g.DriverVersion } else { $g.DriverVersion }), $g.DriverDate
            $s = New-Object Windows.Controls.TextBlock; $s.FontWeight = 'SemiBold'; $s.Margin = '0,2,0,0'; $s.TextWrapping = 'Wrap'
            switch ($g.Vendor) {
                'NVIDIA' {
                    if ($x.Latest) {
                        $newer = $false; try { $newer = [version]$x.Latest.Version -gt [version]$g.NvVersion } catch { }
                        $s.Text = if ($newer) { 'Neuer Treiber verfügbar: {0} vom {1}' -f $x.Latest.Version, $x.Latest.Date } else { 'Aktuell (neuester Treiber {0})' -f $x.Latest.Version }
                        $s.Foreground = if ($newer) { $Brush.Orange } else { $Brush.Green }
                    } else { $s.Text = 'NVIDIA-Abfrage nicht möglich: ' + $x.Error; $s.Foreground = $Brush.Gray }
                }
                'Intel' {
                    if ($x.Latest) {
                        $s.Text = if ($x.Latest.Newer) { 'Neuer Treiber bei Intel: {0} ({1})' -f $x.Latest.Full, $x.Latest.File } else { 'Aktuell - Intel bietet {0} an' -f $x.Latest.Full }
                        $s.Foreground = if ($x.Latest.Newer) { $Brush.Orange } else { $Brush.Green }
                    } else { $s.Text = 'Intel-Download-Center nicht erreichbar (' + $x.Error + ') - Aktualisierung dann über Windows Update und den Intel-Assistenten.'; $s.Foreground = $Brush.Gray }
                }
                'AMD' { $s.Text = 'AMD-Grafik: Aktualisierung über Windows Update oder AMD Software Adrenalin (amd.com/support).'; $s.Foreground = $Brush.Gray }
                default { $s.Text = 'Aktualisierung über Windows Update.'; $s.Foreground = $Brush.Gray }
            }
            [void]$sp.Children.Add($n); [void]$sp.Children.Add($v); [void]$sp.Children.Add($s)
            [void]$ui.GpuPanel.Children.Add($sp)
        }
        if (-not $ui.GpuPanel.Children.Count) { $t = New-Object Windows.Controls.TextBlock; $t.Text = 'Keine Grafikkarte erkannt.'; [void]$ui.GpuPanel.Children.Add($t) }
    }
}
$script:WuDrvRows = [System.Collections.Generic.List[object]]::new()
function Update-WuDrivers {
    $ui.WuDrvPanel.Children.Clear(); $script:WuDrvRows.Clear()
    $ui.WuDrvInfo.Text = 'Suche bei Microsoft läuft (kann 1-3 Minuten dauern) ...'
    $ui.BtnWuDrvInstall.IsEnabled = $false
    Invoke-Bg -Script {
        $s = New-Object -ComObject Microsoft.Update.Session
        $r = $s.CreateUpdateSearcher().Search("IsInstalled=0 and IsHidden=0 and Type='Driver'")
        foreach ($u in $r.Updates) {
            [pscustomobject]@{ Id = $u.Identity.UpdateID; Title = $u.Title; Optional = [bool]$u.BrowseOnly; Class = [string]$u.DriverClass; Provider = [string]$u.DriverProvider
                               Date = $(try { ([datetime]$u.DriverVerDate).ToString('dd.MM.yyyy') } catch { '' }); SizeMB = [math]::Round($u.MaxDownloadSize / 1MB, 1) }
        }
    } -Done {
        param($r, $err)
        if ($err) { $ui.WuDrvInfo.Text = 'Suche fehlgeschlagen: ' + $err.Message; return }
        foreach ($d in @($r | Where-Object { $_ })) {
            $cb = New-Object Windows.Controls.CheckBox; $cb.IsChecked = $true; $cb.Margin = '0,3'
            $cb.Content = '{0}   ({1}{2}, {3}, {4:N1} MB)' -f $d.Title, $(if ($d.Class) { $d.Class + ', ' } else { '' }), $d.Provider, $d.Date, $d.SizeMB
            if ($d.Optional) { $cb.Content = [string]$cb.Content + '  - optional' }
            $cb.Add_Click({ $ui.BtnWuDrvInstall.IsEnabled = [bool](@($script:WuDrvRows | Where-Object { $_.Check.IsChecked }).Count) })
            [void]$ui.WuDrvPanel.Children.Add($cb)
            $script:WuDrvRows.Add([pscustomobject]@{ Id = $d.Id; Check = $cb })
        }
        $ui.WuDrvInfo.Text = if ($script:WuDrvRows.Count) { '{0} Treiber verfügbar.' -f $script:WuDrvRows.Count } else { 'Windows Update hat keine neuen Treiber - alles aktuell.' }
        $ui.BtnWuDrvInstall.IsEnabled = [bool]$script:WuDrvRows.Count
    }
}
function Update-DrvOemInfo { $ui.DrvOemInfo.Text = $ui.InfoOem.Text }

# ---------------------------------------------------------------- Treiberliste und Intel-Geräte (Oberfläche)
$DrvClassDe = @{ DISPLAY = 'Grafik'; NET = 'Netzwerk'; BLUETOOTH = 'Bluetooth'; MEDIA = 'Audio/Video'; AUDIOENDPOINT = 'Audio-Endpunkt'; SYSTEM = 'System/Chipsatz'; USB = 'USB'
                 HDC = 'Speicher-Controller'; SCSIADAPTER = 'Speicher-Controller'; DISKDRIVE = 'Laufwerk'; CDROM = 'DVD'; VOLUME = 'Volume'; MONITOR = 'Monitor'; KEYBOARD = 'Tastatur'
                 MOUSE = 'Maus/Touchpad'; HIDCLASS = 'Eingabegerät'; BIOMETRIC = 'Fingerabdruck'; CAMERA = 'Kamera'; IMAGE = 'Kamera/Scanner'; PRINTER = 'Drucker'; PRINTQUEUE = 'Drucker'
                 FIRMWARE = 'Firmware'; BATTERY = 'Akku'; SOFTWARECOMPONENT = 'Softwarekomponente'; EXTENSION = 'Erweiterung'; PROCESSOR = 'Prozessor'; SECURITYDEVICES = 'Sicherheit (TPM)'
                 SENSOR = 'Sensor'; SDHOST = 'Kartenleser'; SMARTCARDREADER = 'Smartcard'; PORTS = 'Anschlüsse'; COMPUTER = 'Computer'; NETSERVICE = 'Netzwerkdienst'; NETTRANS = 'Netzwerkprotokoll'
                 WPD = 'Mobilgerät'; UCM = 'USB-C'; USBDEVICE = 'USB-Gerät'; SOFTWAREDEVICE = 'Softwaregerät'; SYSTEMDEVICES = 'System/Chipsatz' }
$script:DrvAll = @()
function Update-DrvInventory {
    $ui.DrvSummary.Text = 'Treiber werden eingelesen (einige Sekunden) ...'
    Invoke-Bg -Script {
        param($map)
        $ign = @((Get-ItemProperty 'HKLM:\SOFTWARE\PCPflege' -Name DevIgnore -ErrorAction SilentlyContinue).DevIgnore)
        $ents = @{}; foreach ($e in @(Get-CimInstance Win32_PnPEntity -ErrorAction SilentlyContinue)) { $ents[[string]$e.DeviceID] = $e }
        foreach ($d in @(Get-CimInstance Win32_PnPSignedDriver -ErrorAction SilentlyContinue | Where-Object { $_.DeviceName })) {
            $e = $ents[[string]$d.DeviceID]; $code = if ($e) { [int]$e.ConfigManagerErrorCode } else { 0 }
            $harm = ''; if ($code -eq 24 -and ([string]$d.DeviceID -match '^ACPI\\(PNP03|PNP0F|HPQ8001|MSF0001)' -or [string]$d.DeviceName -match 'PS/2')) { $harm = 'kein PS/2-Gerät eingesteckt (harmlos)' } elseif ($code -and $ign -contains [string]$d.DeviceID) { $harm = 'ausgeblendet (Code {0})' -f $code }
            $dt = $null; try { $dt = [datetime]$d.DriverDate } catch { }
            $age = if ($dt -and $dt.Year -gt 1990) { [math]::Round(((Get-Date) - $dt).TotalDays / 365.25, 1) } else { -1 }
            $cls = ([string]$d.DeviceClass).ToUpper(); $prov = [string]$d.DriverProviderName
            $inbox = $prov -match '^Microsoft' -or ($dt -and $dt.Year -le 2006)
            $lvl = if ($harm) { 'Off' } elseif ($code -and $code -ne 22) { 'Error' } elseif ($age -ge 4 -and -not $inbox) { 'Warn' } elseif ($inbox) { 'Off' } else { '' }
            [pscustomobject]@{
                Name = [string]$d.DeviceName; Class = $cls; ClassDe = $(if ($map.ContainsKey($cls)) { $map[$cls] } elseif ($cls) { $cls.Substring(0, 1) + $cls.Substring(1).ToLower() } else { 'Sonstige' })
                Maker = [string]$d.Manufacturer; Provider = $prov; Version = [string]$d.DriverVersion
                Date = $(if ($dt -and $dt.Year -gt 1990) { $dt.ToString('dd.MM.yyyy') } else { '' }); DateSort = $(if ($dt) { $dt.ToString('yyyyMMdd') } else { '' })
                Age = $age; AgeText = $(if ($age -ge 0) { '{0:N1} J.' -f $age } else { '' }); Inf = [string]$d.InfName; HwId = [string]$d.HardWareID; DevId = [string]$d.DeviceID
                Status = $(if ($harm) { $harm } elseif ($code -eq 22) { 'deaktiviert' } elseif ($code) { 'Problem (Code {0})' -f $code } else { 'OK' }); Code = $code; Harmless = [bool]$harm; Inbox = $inbox; Level = $lvl; Signed = [bool]$d.IsSigned
            }
        }
    } -Arguments @(, $DrvClassDe) -Done {
        param($r, $err)
        if ($err) { $ui.DrvSummary.Text = 'Treiberliste nicht lesbar: ' + $err.Message; return }
        $script:DrvAll = @($r | Where-Object { $_ } | Sort-Object @{ e = { if ($_.Level -eq 'Error') { 0 } elseif ($_.Level -eq 'Warn') { 1 } elseif ($_.Level -eq 'Off') { 3 } else { 2 } } }, ClassDe, Name)
        Update-DrvFilter
        $p = @($script:DrvAll | Where-Object { $_.Code -and $_.Code -ne 22 -and -not $_.Harmless }).Count; $o = @($script:DrvAll | Where-Object { $_.Age -ge 3 -and -not $_.Inbox }).Count
        $i = @($script:DrvAll | Where-Object { $_.Maker -match 'Intel' -or $_.Provider -match 'Intel' }).Count
        $ui.DrvSummary.Text = '{0} Treiber  ·  {1} mit Problem  ·  {2} Hersteller-Treiber älter als 3 Jahre  ·  {3} von Intel  ·  {4} Windows-Standardtreiber' -f $script:DrvAll.Count, $p, $o, $i, @($script:DrvAll | Where-Object Inbox).Count
        Update-IntelPanel
        try { Update-DrvStats } catch { }
    }
}
function Update-DrvFilter {
    $t = $ui.DrvSearch.Text.Trim(); $f = [math]::Max(0, $ui.DrvFilter.SelectedIndex)
    $rows = @($script:DrvAll | Where-Object {
        $x = $_
        $ok = switch ($f) {
            1 { $x.Code -and $x.Code -ne 22 } 2 { $x.Age -ge 3 } 3 { -not $x.Inbox } 4 { $x.Maker -match 'Intel' -or $x.Provider -match 'Intel' } 5 { $x.Class -eq 'DISPLAY' }
            6 { $x.Class -in 'NET', 'BLUETOOTH' } 7 { $x.Class -in 'MEDIA', 'AUDIOENDPOINT' } 8 { $x.Class -in 'SYSTEM', 'PROCESSOR', 'FIRMWARE', 'SECURITYDEVICES', 'USB', 'UCM' } 9 { $x.Class -in 'HDC', 'SCSIADAPTER', 'DISKDRIVE', 'SDHOST', 'CDROM' }
            10 { $x.Class -in 'KEYBOARD', 'MOUSE', 'HIDCLASS' } 11 { $x.Class -in 'CAMERA', 'IMAGE', 'BIOMETRIC', 'SENSOR' } default { $true }
        }
        $ok -and (Test-Match $x $t @('Name', 'Maker', 'Provider', 'Version', 'ClassDe', 'Inf', 'HwId'))
    })
    Set-GridItems $ui.DrvGrid $rows
}
function Update-IntelPanel {
    $ui.IntelPanel.Children.Clear()
    $intel = @($script:DrvAll | Where-Object { ($_.Maker -match 'Intel' -or $_.Provider -match 'Intel') -and $_.Class -notin 'SOFTWARECOMPONENT', 'EXTENSION', 'VOLUME' })
    if (-not $intel.Count) { $t = New-Object Windows.Controls.TextBlock; $t.Text = 'Keine Intel-Komponenten gefunden.'; $t.Foreground = New-UiBrush '#6B7890'; [void]$ui.IntelPanel.Children.Add($t); return }
    $groups = [ordered]@{
        'Grafik' = { $_.Class -eq 'DISPLAY' }; 'WLAN' = { $_.Class -eq 'NET' -and $_.Name -match 'Wi-?Fi|Wireless|WLAN' }; 'Bluetooth' = { $_.Class -eq 'BLUETOOTH' -and $_.Name -match 'Intel|Wireless Bluetooth' }
        'LAN' = { $_.Class -eq 'NET' -and $_.Name -notmatch 'Wi-?Fi|Wireless|WLAN|Virtual|Miniport' }; 'Audio' = { $_.Class -in 'MEDIA', 'AUDIOENDPOINT' }
        'Management Engine, Chipsatz, Serial IO' = { $_.Class -in 'SYSTEM', 'SECURITYDEVICES', 'FIRMWARE' }; 'Speicher (RST/VMD)' = { $_.Class -in 'HDC', 'SCSIADAPTER' }; 'USB/Thunderbolt' = { $_.Class -in 'USB', 'UCM' -or $_.Name -match 'Thunderbolt' }
    }
    $used = @{}
    foreach ($g in $groups.Keys) {
        $items = @($intel | Where-Object $groups[$g] | Where-Object { -not $used.ContainsKey($_.DevId) })
        if (-not $items.Count) { continue }
        foreach ($x in $items) { $used[$x.DevId] = $true }
        $h = New-Object Windows.Controls.TextBlock; $h.Text = $g; $h.FontWeight = 'SemiBold'; $h.Margin = '0,6,0,2'; $h.Foreground = New-UiBrush '#1F2A44'
        [void]$ui.IntelPanel.Children.Add($h)
        foreach ($x in ($items | Sort-Object Name | Select-Object -First 8)) {
            $t = New-Object Windows.Controls.TextBlock; $t.TextWrapping = 'Wrap'; $t.Margin = '12,1,0,1'; $t.FontSize = 12
            $t.Text = '{0}  ·  Treiber {1} vom {2}{3}' -f $x.Name, $x.Version, $x.Date, $(if ($x.Status -ne 'OK') { '  ·  ' + $x.Status } else { '' })
            $t.Foreground = New-UiBrush $(if ($x.Level -eq 'Error') { '#C81E1E' } elseif ($x.Level -eq 'Warn') { '#B45309' } else { '#475569' })
            [void]$ui.IntelPanel.Children.Add($t)
        }
    }
    $script:IntelHas = @{ Gfx = [bool]@($intel | Where-Object { $_.Class -eq 'DISPLAY' }).Count; Wifi = [bool]@($intel | Where-Object { $_.Class -eq 'NET' -and $_.Name -match 'Wi-?Fi|Wireless' }).Count; Bt = [bool]@($intel | Where-Object { $_.Class -eq 'BLUETOOTH' }).Count }
    $ui.BtnIntelGfx.IsEnabled = $script:IntelHas.Gfx -or $script:IntelHas.Wifi -or $script:IntelHas.Bt; $ui.BtnIntelWifi.IsEnabled = $script:IntelHas.Wifi -or $script:IntelHas.Bt
    $dsa = Get-IntelDsaPath
    $ui.BtnIntelDsa.Content = if ($dsa) { 'Intel-Assistent öffnen' } else { 'Intel-Assistent installieren' }
    $ui.IntelDsaInfo.Text = if ($dsa) { 'Intel Driver & Support Assistant ist installiert ({0}) - zeigt zusätzlich alle Intel-Updates im Browser.' -f $(if ($dsa.FullName) { [Diagnostics.FileVersionInfo]::GetVersionInfo($dsa.FullName).ProductVersion } else { $dsa.Version }) } else { 'Intel Driver & Support Assistant ist nicht installiert - wird für die Anzeige im Browser nicht gebraucht, kann aber mit einem Klick dazu.' }
}

# ---------------------------------------------------------------- Windows und Office (Oberfläche)
$IsoRings = @('Retail', 'ReleasePreview', 'Beta', 'Dev', 'Canary')
$IsoLangs = @(@('de-de', 'German'), @('en-us', 'English'), @('en-gb', 'English International'))
function Get-IsoJob([switch]$Upgrade) {
    $l = $IsoLangs[[math]::Max(0, $ui.IsoLang.SelectedIndex)]
    $ed = switch ($ui.IsoEdition.SelectedIndex) { 1 { @('professional', 'Pro') } 2 { @('core', 'Home') } default { @('professional;core', 'Pro') } }
    @{ Ring = $IsoRings[[math]::Max(0, $ui.IsoRing.SelectedIndex)]; Lang = $l[0]; FidoLang = $l[1]; UupEdition = $ed[0]; FidoEdition = $ed[1]; Target = $ui.IsoTarget.Text.Trim(); Upgrade = [bool]$ui.IsoUpgrade.IsChecked }
}
function Update-IsoBuild {
    $ring = $IsoRings[[math]::Max(0, $ui.IsoRing.SelectedIndex)]
    if ($ring -eq 'Retail') { $ui.IsoBuildInfo.Text = 'Offizielle ISO direkt von Microsoft (aktuelle Version, z.B. 25H2). Falls Microsoft den Direkt-Download blockiert, wird sie automatisch aus den Microsoft-Dateien gebaut.'; return }
    $ui.IsoBuildInfo.Text = 'Build wird ermittelt ...'
    Invoke-Bg -Script { param($r) Get-InsiderBuild $r } -Arguments @($ring) -Functions @('Get-InsiderBuild') -Done {
        param($r, $err)
        if ($err -or -not $r) { $ui.IsoBuildInfo.Text = 'Build konnte nicht ermittelt werden: ' + $(if ($err) { $err.Message } else { 'keine Antwort' }); return }
        $cur = (Get-ItemProperty 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion')
        $ui.IsoBuildInfo.Text = 'Neuester Build: {0}  ({1})  -  auf diesem PC: {2}.{3}' -f $r[0].Build, $r[0].Title, $cur.CurrentBuild, $cur.UBR
    }
}
function Get-OfficeJob([string]$Mode) {
    $prod = @('O365BusinessRetail', 'O365ProPlusRetail', 'Home2024Retail', 'HomeBusiness2024Retail', 'ProPlus2024Volume', 'ProPlus2021Volume')[[math]::Max(0, $ui.OffProduct.SelectedIndex)]
    $ch = @('Current', 'MonthlyEnterprise', 'SemiAnnual', 'BetaChannel', 'CurrentPreview')[[math]::Max(0, $ui.OffChannel.SelectedIndex)]
    $lang = @('de-de', 'de-de,en-us', 'en-us')[[math]::Max(0, $ui.OffLang.SelectedIndex)]
    $ex = @($ui.OffApps.Children | Where-Object { -not $_.IsChecked } | ForEach-Object { [string]$_.Tag })
    $extra = @()
    $vol = $prod -match 'Volume$'
    if ($ui.OffVisio.IsChecked) { $extra += $(if ($prod -eq 'ProPlus2021Volume') { 'VisioPro2021Volume' } elseif ($vol) { 'VisioPro2024Volume' } else { 'VisioProRetail' }) }
    if ($ui.OffProject.IsChecked) { $extra += $(if ($prod -eq 'ProPlus2021Volume') { 'ProjectPro2021Volume' } elseif ($vol) { 'ProjectPro2024Volume' } else { 'ProjectProRetail' }) }
    if ($prod -notmatch '^O365' -and $ch -in 'BetaChannel', 'CurrentPreview', 'MonthlyEnterprise', 'SemiAnnual') { $ch = 'Current' }
    @{ Mode = $Mode; Product = $prod; Channel = $ch; Lang = $lang; Exclude = $ex; Extra = $extra; Target = $ui.OffTarget.Text.Trim() }
}
function Update-UsbList {
    $ui.UsbDisk.Items.Clear()
    foreach ($d in @(Get-Disk | Where-Object { [string]$_.BusType -eq 'USB' -and -not $_.IsBoot -and -not $_.IsSystem } | Sort-Object Number)) {
        $letters = (@(Get-Partition -DiskNumber $d.Number -ErrorAction SilentlyContinue | Where-Object { $_.DriveLetter -and [int][char]$_.DriveLetter -ne 0 } | ForEach-Object { "$($_.DriveLetter):" }) -join ' ')
        $ci = New-Object Windows.Controls.ComboBoxItem
        $ci.Content = 'Datenträger {0}: {1}  ({2:N1} GB){3}' -f $d.Number, $d.FriendlyName, ($d.Size / 1GB), $(if ($letters) { '  - ' + $letters } else { '' })
        $ci.Tag = $d.Number
        [void]$ui.UsbDisk.Items.Add($ci)
    }
    if ($ui.UsbDisk.Items.Count) { $ui.UsbDisk.SelectedIndex = 0 }
    else { $ci = New-Object Windows.Controls.ComboBoxItem; $ci.Content = 'Kein USB-Stick gefunden - einstecken und "Aktualisieren"'; $ci.IsEnabled = $false; [void]$ui.UsbDisk.Items.Add($ci) }
    $last = Join-Path $DataDir 'iso_last.txt'
    if (-not $ui.UsbIso.Text -and (Test-Path $last)) { $x = (Get-Content $last -Raw).Trim(); if (Test-Path -LiteralPath $x) { $ui.UsbIso.Text = $x } }
    $lo = Join-Path $DataDir 'office_last.txt'
    if (-not $ui.UsbOffice.Text -and (Test-Path $lo)) { $x = (Get-Content $lo -Raw).Trim(); if (Test-Path -LiteralPath $x) { $ui.UsbOffice.Text = $x } }
}
function Start-UsbJob([switch]$Format) {
    $ci = $ui.UsbDisk.SelectedItem
    if (-not $ci -or $null -eq $ci.Tag) { Show-UiError 'Bitte einen USB-Stick auswählen.'; return }
    $iso = $ui.UsbIso.Text.Trim(); $off = $ui.UsbOffice.Text.Trim()
    if ($iso -and -not (Test-Path -LiteralPath $iso)) { Show-UiError 'Die ISO-Datei gibt es nicht.'; return }
    if ($off -and -not (Test-Path -LiteralPath $off)) { Show-UiError 'Den Office-Ordner gibt es nicht.'; return }
    if ($Format) {
        $txt = "{0}`n`nALLE DATEN AUF DIESEM STICK WERDEN GELÖSCHT.`n`nInhalt danach: {1}{2}{3}`n`nFortfahren?" -f $ci.Content, $(if ($iso) { 'Windows-Setup (bootfähig)' } else { 'leerer Stick' }), $(if ($off) { ', Office' } else { '' }), $(if ($ui.UsbPflege.IsChecked) { ', PC-Tools portabel' } else { '' })
        if (-not (Confirm-Ui $txt 'Warning')) { return }
    }
    Start-Run -Parts @('UsbBuild') -Job @{ DiskNumber = [int]$ci.Tag; Format = [bool]$Format; Iso = $(if ($Format) { $iso } else { '' }); OfficeDir = $off; Pflege = [bool]($ui.UsbPflege.IsChecked -or -not $Format); WithToken = [bool]$ui.UsbToken.IsChecked }
}
function Select-FolderInto($TextBox) {
    Add-Type -AssemblyName System.Windows.Forms
    $d = New-Object System.Windows.Forms.FolderBrowserDialog
    if ($TextBox.Text -and (Test-Path -LiteralPath $TextBox.Text)) { $d.SelectedPath = $TextBox.Text }
    if ($d.ShowDialog() -eq 'OK') { $TextBox.Text = $d.SelectedPath }
}
function Select-IsoFile([string]$Title) {
    Add-Type -AssemblyName System.Windows.Forms
    $d = New-Object System.Windows.Forms.OpenFileDialog
    $d.Filter = 'ISO-Dateien (*.iso)|*.iso'; $d.Title = $Title
    if ($d.ShowDialog() -eq 'OK') { return $d.FileName }
    return $null
}


# ---------------------------------------------------------------- Neustart und BIOS (Oberfläche)
