    @{ Key = 'Shutdown';  Glyph = 0xE7E8; Color = '#334155'; Title = 'Herunterfahren';           Desc = 'Mit Schnellstart (falls aktiv)' }
    @{ Key = 'Full';      Glyph = 0xE7E8; Color = '#475569'; Title = 'Vollständig herunterfahren'; Desc = 'Ohne Schnellstart - frischer Kaltstart' }
    @{ Key = 'Uefi';      Glyph = 0xE950; Color = '#7C3AED'; Title = 'Neustart ins UEFI/BIOS';   Desc = 'Direkt in die Firmware-Einstellungen' }
    @{ Key = 'Advanced';  Glyph = 0xE90F; Color = '#0F766E'; Title = 'Erweiterte Startoptionen'; Desc = 'Wiederherstellung, Reparatur, Systemwiederherstellung, Eingabeaufforderung' }
    @{ Key = 'Safe';      Glyph = 0xE83D; Color = '#D97706'; Title = 'Abgesicherter Modus';       Desc = 'Nur Grundtreiber - danach automatisch wieder normal' }
    @{ Key = 'SafeNet';   Glyph = 0xE83D; Color = '#D97706'; Title = 'Abgesichert mit Netzwerk';  Desc = 'Wie oben, mit Internet/Netzwerk' }
    @{ Key = 'SafeCmd';   Glyph = 0xE756; Color = '#D97706'; Title = 'Abgesichert mit Eingabeaufforderung'; Desc = 'Ohne Explorer, nur Kommandozeile' }
    @{ Key = 'Sleep';     Glyph = 0xE708; Color = '#0891B2'; Title = 'Energie sparen';            Desc = 'Standby' }
    @{ Key = 'Hibernate'; Glyph = 0xE823; Color = '#0891B2'; Title = 'Ruhezustand';               Desc = 'Arbeitsstand auf die Festplatte, PC aus' }
    @{ Key = 'Logoff';    Glyph = 0xF3B1; Color = '#64748B'; Title = 'Abmelden';                  Desc = 'Benutzer abmelden' }
    @{ Key = 'Lock';      Glyph = 0xE72E; Color = '#64748B'; Title = 'Sperren';                   Desc = 'Bildschirm sperren' }
    @{ Key = 'MemTest';   Glyph = 0xE964; Color = '#BE123C'; Title = 'Speicherdiagnose';          Desc = 'Arbeitsspeicher beim Neustart testen' }
    @{ Key = 'ChkDsk';    Glyph = 0xEDA2; Color = '#BE123C'; Title = 'Datenträgerprüfung';        Desc = 'Laufwerk C: beim nächsten Start prüfen und reparieren' }
)
Add-Type -Name Power -Namespace PCPflege -MemberDefinition '[DllImport("powrprof.dll")] public static extern bool SetSuspendState(bool hibernate, bool force, bool wakeupEventsDisabled);' -ErrorAction SilentlyContinue
$BcdExe = if (Test-Path (Join-Path $env:windir 'Sysnative\bcdedit.exe')) { Join-Path $env:windir 'Sysnative\bcdedit.exe' } else { Join-Path $env:windir 'System32\bcdedit.exe' }
function Test-Uefi { Test-Path 'HKLM:\SYSTEM\CurrentControlSet\Control\SecureBoot\State' }
function Update-PowerInfo {
    $sb = try { if (Confirm-SecureBootUEFI -ErrorAction Stop) { 'Secure Boot an' } else { 'Secure Boot aus' } } catch { 'Secure Boot nicht verfügbar' }
    $ui.PwrMode.Text = if (Test-Uefi) { 'UEFI, ' + $sb } else { 'Legacy-BIOS (Neustart ins UEFI nicht möglich)' }
    $hb = (Get-ItemProperty 'HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Power' -Name HiberbootEnabled -ErrorAction SilentlyContinue).HiberbootEnabled
    $ui.PwrFast.Text = if ($hb -eq 1) { 'an - "Herunterfahren" ist dann kein echter Kaltstart' } else { 'aus' }
    $os = Get-CimInstance Win32_OperatingSystem
    $up = (Get-Date) - $os.LastBootUpTime
    $ui.PwrBoot.Text = '{0:dd.MM.yyyy HH:mm} (vor {1} Tagen, {2} Std.)' -f $os.LastBootUpTime, $up.Days, $up.Hours
    $p = @()
    if ((Test-Path 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Component Based Servicing\RebootPending') -or (Test-Path 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\WindowsUpdate\Auto Update\RebootRequired')) { $p += 'Neustart für Updates nötig' }
    $bcd = (& $BcdExe /enum '{current}' 2>$null) -join "`n"
    if ($bcd -match '(?m)^safeboot\s+(\w+)') { $p += ('Abgesicherter Modus ist für den nächsten Start eingestellt ({0})' -f $Matches[1]) }
    $ui.PwrPending.Text = if ($p) { $p -join ', ' } else { 'nichts' }
}
function Build-PowerTiles {
    $ui.PwrTiles.Children.Clear()
    foreach ($a in $PowerActions) {
        $b = New-Object Windows.Controls.Button
        $b.Style = $window.FindResource('Sec'); $b.Width = 290; $b.MinHeight = 78; $b.Padding = '12,9'; $b.Margin = '0,0,10,10'; $b.HorizontalContentAlignment = 'Stretch'
        $g = New-Object Windows.Controls.Grid
        $c1 = New-Object Windows.Controls.ColumnDefinition; $c1.Width = 'Auto'; [void]$g.ColumnDefinitions.Add($c1); [void]$g.ColumnDefinitions.Add((New-Object Windows.Controls.ColumnDefinition))
        $ic = New-Object Windows.Controls.Border; $ic.Width = 38; $ic.Height = 38; $ic.CornerRadius = '9'; $ic.Background = New-UiBrush $a.Color; $ic.Margin = '0,0,10,0'; $ic.VerticalAlignment = 'Center'
        $gl = New-Object Windows.Controls.TextBlock; $gl.FontFamily = 'Segoe MDL2 Assets'; $gl.Text = [string][char]$a.Glyph; $gl.FontSize = 17; $gl.Foreground = New-UiBrush '#FFFFFF'; $gl.HorizontalAlignment = 'Center'; $gl.VerticalAlignment = 'Center'
        $ic.Child = $gl
        $sp = New-Object Windows.Controls.StackPanel; $sp.VerticalAlignment = 'Center'; [Windows.Controls.Grid]::SetColumn($sp, 1)
        $t = New-Object Windows.Controls.TextBlock; $t.Text = $a.Title; $t.FontWeight = 'SemiBold'; $t.TextWrapping = 'Wrap'
        $d = New-Object Windows.Controls.TextBlock; $d.Text = $a.Desc; $d.FontSize = 12; $d.FontWeight = 'Normal'; $d.Foreground = New-UiBrush '#475569'; $d.TextWrapping = 'Wrap'; $d.Margin = '0,2,0,0'
        [void]$sp.Children.Add($t); [void]$sp.Children.Add($d)
        [void]$g.Children.Add($ic); [void]$g.Children.Add($sp)
        $b.Content = $g; $b.Tag = $a.Key; $b.ToolTip = $a.Desc
        if ($a.Key -eq 'Uefi' -and -not (Test-Uefi)) { $b.IsEnabled = $false }
        $b.Add_Click({ param($s, $e) Invoke-PowerAction ([string]$s.Tag) })
        [void]$ui.PwrTiles.Children.Add($b)
    }
}
function Get-PwrArgs {
    $d = 0; [void][int]::TryParse($ui.PwrDelay.Text.Trim(), [ref]$d); $d = [math]::Max(0, [math]::Min(315360000, $d))
    $a = @('/t', [string]$d); if ($ui.PwrForce.IsChecked) { $a += '/f' }
    return , $a
}
function Invoke-Shutdown([string[]]$Args1, [string]$What) {
    $a = $Args1 + (Get-PwrArgs) + @('/c', ('"PC-Tools: {0}"' -f $What), '/d', 'p:0:0')
    $out = & shutdown.exe @a 2>&1
    if ($LASTEXITCODE -ne 0) { Show-UiError ('{0} nicht möglich: {1}' -f $What, ($out -join ' ')) } else { $ui.StatusText.Text = $What + ' eingeleitet.' }
}
function Set-SafeBoot([string]$Mode, [bool]$Shell) {
    $o = & $BcdExe /set '{current}' safeboot $Mode 2>&1
    if ($LASTEXITCODE -ne 0) { throw ('bcdedit: ' + ($o -join ' ')) }
    if ($Shell) { $null = & $BcdExe /set '{current}' safebootalternateshell yes 2>&1 }
    # Einmalig: beim Anmelden im abgesicherten Modus wird er für den nächsten Start wieder ausgeschaltet
    $cmd = 'cmd.exe /c bcdedit /deletevalue {current} safeboot & bcdedit /deletevalue {current} safebootalternateshell'
    New-ItemProperty -Path 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\RunOnce' -Name '*PCPflegeSafeModeOff' -Value $cmd -PropertyType String -Force | Out-Null
}
function Invoke-PowerAction([string]$Key) {
    $a = $PowerActions | Where-Object { $_.Key -eq $Key } | Select-Object -First 1
    $q = switch ($Key) {
        'Uefi'     { 'Der PC startet neu und öffnet direkt die UEFI/BIOS-Einstellungen. Offene Programme speichern!' }
        'Advanced' { 'Der PC startet neu in die erweiterten Startoptionen (Problembehandlung, Starthilfe, Systemwiederherstellung, Eingabeaufforderung, UEFI-Einstellungen).' }
        'Safe'     { 'Der PC startet im abgesicherten Modus. Beim Anmelden dort wird er für den nächsten Neustart automatisch wieder ausgeschaltet.' }
        'SafeNet'  { 'Der PC startet im abgesicherten Modus mit Netzwerk. Beim Anmelden dort wird er für den nächsten Neustart automatisch wieder ausgeschaltet.' }
        'SafeCmd'  { 'Der PC startet im abgesicherten Modus nur mit Eingabeaufforderung (kein Explorer). Zurück: Befehl "shutdown /r /t 0" eingeben - der Modus ist dann schon wieder ausgeschaltet.' }
        'ChkDsk'   { 'Laufwerk C: wird beim nächsten Start geprüft und repariert (kann je nach Größe 5-60 Minuten dauern). Jetzt vormerken? Neu gestartet wird nicht automatisch.' }
        'MemTest'  { 'Die Windows-Speicherdiagnose wird geöffnet - dort "Jetzt neu starten und nach Problemen suchen" wählen.' }
        'Lock'     { $null }
        default    { '{0}?' -f $a.Title }
    }
    if ($q -and -not (Confirm-Ui $q)) { return }
    try {
        switch ($Key) {
            'Restart'   { Invoke-Shutdown @('/r') 'Neustart' }
            'Shutdown'  { Invoke-Shutdown @('/s') 'Herunterfahren' }
            'Full'      { Invoke-Shutdown @('/s', '/full') 'Vollständiges Herunterfahren' }
            'Uefi'      { Invoke-Shutdown @('/r', '/fw') 'Neustart ins UEFI/BIOS' }
            'Advanced'  { Invoke-Shutdown @('/r', '/o') 'Neustart in die erweiterten Startoptionen' }
            'Safe'      { Set-SafeBoot 'minimal' $false; Invoke-Shutdown @('/r') 'Neustart im abgesicherten Modus' }
            'SafeNet'   { Set-SafeBoot 'network' $false; Invoke-Shutdown @('/r') 'Neustart im abgesicherten Modus mit Netzwerk' }
            'SafeCmd'   { Set-SafeBoot 'minimal' $true; Invoke-Shutdown @('/r') 'Neustart im abgesicherten Modus mit Eingabeaufforderung' }
            'Sleep'     { [void][PCPflege.Power]::SetSuspendState($false, $false, $false) }
            'Hibernate' {
                $o = & shutdown.exe /h 2>&1
                if ($LASTEXITCODE -ne 0) { if (Confirm-Ui 'Der Ruhezustand ist ausgeschaltet. Einschalten (powercfg /h on) und in den Ruhezustand gehen?') { & powercfg.exe /h on | Out-Null; & shutdown.exe /h | Out-Null } }
            }
            'Logoff'    { & shutdown.exe /l | Out-Null }
            'Lock'      { & rundll32.exe user32.dll,LockWorkStation }
            'MemTest'   { Start-Process mdsched.exe }
            'ChkDsk'    { $o = & fsutil.exe dirty set $env:SystemDrive 2>&1; $ui.StatusText.Text = 'Datenträgerprüfung für ' + $env:SystemDrive + ' beim nächsten Start vorgemerkt.'; Update-PowerInfo }
        }
    } catch { Show-UiError $_.Exception.Message }
}
function Update-BootEntries {
    $rows = [System.Collections.Generic.List[object]]::new()
    $msg = ''
    foreach ($fw in $false, $true) {
        $argsB = if ($fw) { @('/enum', 'firmware', '/v') } else { @('/enum', '/v') }
        $out = @(& $BcdExe @argsB 2>&1 | ForEach-Object { [string]$_ })
        if ($LASTEXITCODE -ne 0) { if (-not $msg) { $msg = ($out | Where-Object { $_.Trim() } | Select-Object -First 1) }; continue }
        # Blöcke: Überschrift, Strichlinie, Eigenschaften (sprachunabhängig: Kennung ist die erste {GUID}-Zeile)
        $blocks = [System.Collections.Generic.List[object]]::new(); $cur = $null
        for ($i = 0; $i -lt $out.Count; $i++) {
            if ($i + 1 -lt $out.Count -and $out[$i + 1] -match '^-{5,}\s*$' -and $out[$i].Trim()) { $cur = @{ Head = $out[$i].Trim(); Lines = [System.Collections.Generic.List[string]]::new() }; $blocks.Add($cur); $i++; continue }
            if ($cur -and $out[$i].Trim()) { $cur.Lines.Add($out[$i]) }
        }
        foreach ($blk in $blocks) {
            $id = ''; $desc = ''
            foreach ($l in $blk.Lines) {
                if (-not $id -and $l -match '^\S+\s+(\{[0-9a-fA-F\-]{36}\}|\{\w+\})\s*$') { $id = $Matches[1] }
                elseif (-not $desc -and $l -match '^(description|Beschreibung)\s+(.+)$') { $desc = $Matches[2].Trim() }
            }
            if (-not $id) { continue }
            if ($blk.Head -match 'Firmware.?(Start|Boot).?Manager') { continue }
            if (-not $fw -and $blk.Head -match '(Start|Boot).?Manager') { continue }
            if (-not $desc) { $desc = $blk.Head }
            if ($rows | Where-Object { $_.Id -eq $id }) { continue }
            $rows.Add([pscustomobject]@{ Name = $desc; Kind = $(if ($fw) { 'Firmware (UEFI)' } else { 'Windows-Starteintrag' }); Id = $id; Fw = $fw })
        }
    }
    if (-not $rows.Count) { $rows.Add([pscustomobject]@{ Name = $(if ($msg) { 'Keine Einträge lesbar: ' + $msg } else { 'Keine Einträge gefunden' }); Kind = ''; Id = ''; Fw = $false }) }
    Set-GridItems $ui.BootGrid @($rows)
}
function Invoke-BootOnce {
    $r = $ui.BootGrid.SelectedItem
    if (-not $r -or -not $r.Id) { Show-UiError 'Bitte einen Eintrag auswählen.'; return }
    if (-not (Confirm-Ui ('Der PC startet jetzt neu - einmalig von "{0}". Offene Programme speichern!' -f $r.Name))) { return }
    $o = if ($r.Fw) { & $BcdExe /set '{fwbootmgr}' bootsequence $r.Id 2>&1 } else { & $BcdExe /bootsequence $r.Id 2>&1 }
    if ($LASTEXITCODE -ne 0) { Show-UiError ('Nicht möglich: ' + ($o -join ' ')); return }
    Invoke-Shutdown @('/r') ('Einmaliger Start von ' + $r.Name)
}


# ---------------------------------------------------------------- Fehlersuche und Reparatur (Oberfläche)
$RepPresets = @{
    Std  = @('RestorePoint', 'DismRestore', 'Sfc', 'ChkScan', 'DiskHealth', 'Wmi', 'TimeSync')
    Wu   = @('RestorePoint', 'WuReset', 'DismRestore', 'Sfc', 'TimeSync', 'WuScan')
    Net  = @('DnsFlush', 'IpRenew', 'AdapterRestart', 'ProxyReset', 'Winsock')
    Apps = @('RestorePoint', 'StoreReset', 'StoreReregister', 'StartMenuFix', 'WingetReset', 'IconCache')
    Disk = @('ChkScan', 'DiskHealth', 'Trim')
}
$script:RepChecks = @{}
function Build-RepGroups {
    $ui.RepGroups.Children.Clear(); $script:RepChecks = @{}
    foreach ($grp in @($RepairDefs | ForEach-Object { $_.Group } | Select-Object -Unique)) {
        $h = New-Object Windows.Controls.TextBlock; $h.Text = $grp; $h.FontWeight = 'SemiBold'; $h.FontSize = 14; $h.Margin = '0,10,0,4'; $h.Foreground = New-UiBrush '#1F2A44'
        [void]$ui.RepGroups.Children.Add($h)
        $wp = New-Object Windows.Controls.WrapPanel
        foreach ($d in @($RepairDefs | Where-Object { $_.Group -eq $grp })) {
            $cb = New-Object Windows.Controls.CheckBox; $cb.Width = 440; $cb.Margin = '0,3,10,5'; $cb.Tag = $d.Key; $cb.VerticalContentAlignment = 'Top'
            $sp = New-Object Windows.Controls.StackPanel
            $t = New-Object Windows.Controls.TextBlock; $t.Text = $d.Title + $(if ($d.Reboot) { '  (Neustart)' } else { '' }); $t.FontWeight = 'SemiBold'; $t.TextWrapping = 'Wrap'; $t.Foreground = New-UiBrush '#1F2A44'
            $ds = New-Object Windows.Controls.TextBlock; $ds.Text = $d.Desc; $ds.FontSize = 12; $ds.TextWrapping = 'Wrap'; $ds.Foreground = New-UiBrush '#475569'
            [void]$sp.Children.Add($t); [void]$sp.Children.Add($ds); $cb.Content = $sp
            $cb.Add_Click({ Update-RepSelInfo })
            $script:RepChecks[$d.Key] = $cb
            [void]$wp.Children.Add($cb)
        }
        [void]$ui.RepGroups.Children.Add($wp)
    }
    Update-RepSelInfo
}
function Set-RepSelection([string[]]$Keys, [switch]$Add) {
    foreach ($k in $script:RepChecks.Keys) { if (-not $Add) { $script:RepChecks[$k].IsChecked = $false } }
    foreach ($k in $Keys) { if ($script:RepChecks.ContainsKey($k)) { $script:RepChecks[$k].IsChecked = $true } }
    Update-RepSelInfo
}
function Get-RepSelection { @($RepairDefs | Where-Object { $script:RepChecks[$_.Key].IsChecked } | ForEach-Object { $_.Key }) }
function Update-RepSelInfo {
    $sel = Get-RepSelection
    $rb = @($RepairDefs | Where-Object { $_.Reboot -and $sel -contains $_.Key }).Count
    $ui.RepSelInfo.Text = if ($sel.Count) { '{0} Reparaturen ausgewählt{1}. Reihenfolge wird automatisch richtig gesetzt (Wiederherstellungspunkt zuerst, DISM vor SFC).' -f $sel.Count, $(if ($rb) { ', davon {0} mit Neustart' -f $rb } else { '' }) } else { 'Nichts ausgewählt - Schnellwahl oben nutzen oder einzelne Punkte anhaken.' }
}
function Start-Repair {
    $sel = Get-RepSelection
    if (-not $sel.Count) { Show-UiError 'Bitte mindestens eine Reparatur auswählen.'; return }
    $warn = @($RepairDefs | Where-Object { $sel -contains $_.Key -and $_.Key -in 'FirewallReset', 'NetReset', 'WuLastRemove', 'BootRepair', 'HostsReset' } | ForEach-Object { '  - ' + $_.Title })
    $q = "{0} Reparaturen jetzt im Hintergrund ausführen?" -f $sel.Count
    if ($warn) { $q += "`n`nAchtung, tiefgreifend:`n" + ($warn -join "`n") }
    if (@($RepairDefs | Where-Object { $_.Reboot -and $sel -contains $_.Key }).Count) { $q += "`n`nDanach ist ein Neustart nötig (startet nicht automatisch)." }
    if (-not (Confirm-Ui $q $(if ($warn) { 'Warning' } else { 'Question' }))) { return }
    Start-Run -Parts @('Repair') -Job @{ Actions = $sel; Source = $ui.RepSource.Text.Trim() }
}
function Start-RepScan {
    $ui.BtnRepScan.IsEnabled = $false; $ui.RepScanInfo.Text = 'Fehlersuche läuft ...'
    Set-GridItems $ui.RepFindings @()
    Invoke-Bg -Script {
        $r = [System.Collections.Generic.List[object]]::new()
        function F([string]$Area, [string]$Level, [string]$Detail, [string]$FixText = '', [string[]]$Fix = @()) {
            $st = switch ($Level) { 'Good' { 'in Ordnung' } 'Warn' { 'Hinweis' } 'Error' { 'Problem' } default { 'Info' } }
            $r.Add([pscustomobject]@{ Area = $Area; State = $st; Detail = $Detail; FixText = $FixText; Fix = ($Fix -join ','); Level = $Level })
        }
        $sys = Join-Path $env:windir 'System32'
        # Neustart
        $pend = (Test-Path 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Component Based Servicing\RebootPending') -or (Test-Path 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\WindowsUpdate\Auto Update\RebootRequired')
        $os = Get-CimInstance Win32_OperatingSystem; $up = (Get-Date) - $os.LastBootUpTime
        if ($pend) { F 'Neustart' 'Warn' 'Ein Neustart steht aus (Updates/Installationen).' 'Zuerst neu starten - viele Fehler erledigen sich damit.' }
        elseif ($up.TotalDays -gt 14) { F 'Neustart' 'Warn' ('PC läuft seit {0} Tagen ohne Neustart.' -f [int]$up.TotalDays) 'Neu starten.' }
        else { F 'Neustart' 'Good' ('Letzter Start vor {0} Tagen, nichts ausstehend.' -f [int]$up.TotalDays) }
        # Speicherplatz
        foreach ($v in @(Get-Volume -ErrorAction SilentlyContinue | Where-Object { $_.DriveLetter -and "$($_.DriveType)" -eq 'Fixed' -and $_.Size -gt 5GB })) {
            $pct = [math]::Round($v.SizeRemaining * 100 / $v.Size); $gb = [math]::Round($v.SizeRemaining / 1GB, 1)
            if ($pct -lt 8 -or $gb -lt 10) { F ('Speicher {0}:' -f $v.DriveLetter) 'Error' ('Nur {0} GB frei ({1} %).' -f $gb, $pct) 'Seite Aufräumen ausführen; ohne Platz scheitern Updates.' @('ComponentClean') }
            elseif ($pct -lt 15) { F ('Speicher {0}:' -f $v.DriveLetter) 'Warn' ('{0} GB frei ({1} %).' -f $gb, $pct) 'Bald aufräumen.' }
            else { F ('Speicher {0}:' -f $v.DriveLetter) 'Good' ('{0} GB frei ({1} %).' -f $gb, $pct) }
        }
        # Datenträger-Zustand
        foreach ($d in @(Get-PhysicalDisk -ErrorAction SilentlyContinue)) {
            $rc = $null; try { $rc = $d | Get-StorageReliabilityCounter -ErrorAction Stop } catch { }
            $x = '{0}: {1}' -f $d.FriendlyName, $d.HealthStatus
            if ($rc -and $rc.Wear -ne $null) { $x += (', Verschleiß {0} %' -f $rc.Wear) }
            if ($rc -and $rc.Temperature) { $x += (', {0} °C' -f $rc.Temperature) }
            if ([string]$d.HealthStatus -ne 'Healthy') { F 'Datenträger' 'Error' $x 'Daten SOFORT sichern (Seite Datensicherung) und Laufwerk tauschen.' @('DiskHealth') }
            elseif ($rc -and $rc.Wear -ge 80) { F 'Datenträger' 'Warn' $x 'SSD ist stark abgenutzt - Austausch planen.' @('DiskHealth') }
            else { F 'Datenträger' 'Good' $x }
        }
        $dirty = (& (Join-Path $sys 'fsutil.exe') dirty query $env:SystemDrive 2>&1) -join ' '
        if ($dirty -match '(NICHT|NOT)') { } elseif ($dirty -match '(fehlerhaft|dirty)') { F 'Dateisystem' 'Error' 'Laufwerk C: ist als fehlerhaft markiert.' 'Laufwerk beim Neustart reparieren.' @('ChkBoot') }
        $de = @(Get-WinEvent -FilterHashtable @{ LogName = 'System'; ProviderName = 'disk', 'Ntfs', 'stornvme', 'storahci', 'iaStorAC'; Level = 1, 2, 3; StartTime = (Get-Date).AddDays(-30) } -MaxEvents 200 -ErrorAction SilentlyContinue | Where-Object { $_.Id -in 7, 11, 51, 55, 98, 129, 153, 157 })
        if ($de.Count) { F 'Datenträger-Ereignisse' $(if ($de.Count -gt 10) { 'Error' } else { 'Warn' }) ('{0} Lese-/Schreib- oder Dateisystemfehler in 30 Tagen (zuletzt {1:dd.MM. HH:mm}).' -f $de.Count, $de[0].TimeCreated) 'Datenträger prüfen, Kabel/Anschluss kontrollieren, Daten sichern.' @('ChkScan', 'DiskHealth') }
        else { F 'Datenträger-Ereignisse' 'Good' 'Keine Datenträgerfehler in 30 Tagen.' }
        # Windows-Abbild
        $o = & (Join-Path $sys 'Dism.exe') /Online /Cleanup-Image /CheckHealth 2>&1; $txt = $o -join ' '
        if (($LASTEXITCODE -ne 0) -or (($txt -match '(reparierbar|repairable|beschädigt|corrupt)') -and ($txt -notmatch '(Keine Komponentenspeicherbeschädigung|No component store corruption)'))) { F 'Windows-Abbild' 'Error' 'Der Komponentenspeicher ist beschädigt.' 'Windows-Abbild reparieren, danach Systemdateien prüfen.' @('RestorePoint', 'DismRestore', 'Sfc') }
        else { F 'Windows-Abbild' 'Good' 'Keine Beschädigung gemeldet.' }
        # Windows Update
        $wuErr = @(Get-WinEvent -FilterHashtable @{ LogName = 'System'; ProviderName = 'Microsoft-Windows-WindowsUpdateClient'; Id = 20; StartTime = (Get-Date).AddDays(-14) } -MaxEvents 50 -ErrorAction SilentlyContinue)
        $last = $null; try { $last = (Get-HotFix -ErrorAction Stop | Where-Object InstalledOn | Sort-Object InstalledOn -Descending | Select-Object -First 1).InstalledOn } catch { }
        $wuSvc = Get-CimInstance Win32_Service -Filter "Name='wuauserv'" -ErrorAction SilentlyContinue
        if ($wuSvc -and $wuSvc.StartMode -eq 'Disabled') { F 'Windows Update' 'Error' 'Der Update-Dienst ist deaktiviert.' 'Windows Update zurücksetzen.' @('WuReset') }
        elseif ($wuErr.Count -ge 2) { F 'Windows Update' 'Error' ('{0} fehlgeschlagene Installationen in 14 Tagen (zuletzt: {1}).' -f $wuErr.Count, (($wuErr[0].Message -split "`n")[0])) 'Windows Update zurücksetzen und Abbild reparieren.' @('RestorePoint', 'WuReset', 'DismRestore', 'Sfc', 'WuScan') }
        elseif ($last -and ((Get-Date) - $last).TotalDays -gt 45) { F 'Windows Update' 'Warn' ('Letztes Update am {0:dd.MM.yyyy}.' -f $last) 'Update-Suche anstoßen; hängt sie, zurücksetzen.' @('WuScan') }
        else { F 'Windows Update' 'Good' $(if ($last) { 'Letztes Update am {0:dd.MM.yyyy}, keine Fehler.' -f $last } else { 'Keine Fehler in 14 Tagen.' }) }
        # Abstürze
        $bs = @(Get-WinEvent -FilterHashtable @{ LogName = 'System'; ProviderName = 'Microsoft-Windows-WER-SystemErrorReporting'; Id = 1001; StartTime = (Get-Date).AddDays(-30) } -ErrorAction SilentlyContinue)
        $kp = @(Get-WinEvent -FilterHashtable @{ LogName = 'System'; ProviderName = 'Microsoft-Windows-Kernel-Power'; Id = 41; StartTime = (Get-Date).AddDays(-30) } -ErrorAction SilentlyContinue)
        $wh = @(Get-WinEvent -FilterHashtable @{ LogName = 'System'; ProviderName = 'Microsoft-Windows-WHEA-Logger'; Level = 1, 2, 3; StartTime = (Get-Date).AddDays(-30) } -ErrorAction SilentlyContinue)
        if ($bs.Count) { F 'Bluescreens' 'Error' ('{0} Bluescreen(s) in 30 Tagen.' -f $bs.Count) 'Seite Fehlerdaten zeigt die Ursache; Treiber aktualisieren, Speicher testen.' @('DismRestore', 'Sfc') } else { F 'Bluescreens' 'Good' 'Keine in 30 Tagen.' }
        if ($kp.Count) { F 'Unerwartet aus' 'Warn' ('{0}x unerwartet ausgeschaltet/neu gestartet in 30 Tagen.' -f $kp.Count) 'Stromversorgung, Überhitzung, Netzteil prüfen.' } else { F 'Unerwartet aus' 'Good' 'Keine in 30 Tagen.' }
        if ($wh.Count) { F 'Hardwarefehler' 'Error' ('{0} Hardwarefehler (WHEA) in 30 Tagen - CPU, RAM oder PCIe.' -f $wh.Count) 'Speicherdiagnose (Seite Neustart und BIOS), BIOS aktualisieren.' } else { F 'Hardwarefehler' 'Good' 'Keine in 30 Tagen.' }
        $ac = @(Get-WinEvent -FilterHashtable @{ LogName = 'Application'; Id = 1000; StartTime = (Get-Date).AddDays(-7) } -MaxEvents 300 -ErrorAction SilentlyContinue)
        if ($ac.Count) { $top = $ac | ForEach-Object { if ($_.Properties.Count) { [string]$_.Properties[0].Value } } | Group-Object | Sort-Object Count -Descending | Select-Object -First 3
            $lv = if ($ac.Count -gt 20) { 'Warn' } else { 'Info' }
            $fx = @(); $ft = 'Betroffene Programme aktualisieren oder neu installieren.'
            if (($top | ForEach-Object { $_.Name }) -match '(explorer|StartMenuExperienceHost|ShellExperienceHost|SearchHost)') { $fx = @('StartMenuFix', 'Sfc'); $ft = 'Windows-Oberfläche stürzt ab: Startmenü reparieren, Systemdateien prüfen.'; $lv = 'Warn' }
            F 'Programmabstürze' $lv ('{0} in 7 Tagen, am häufigsten: {1}' -f $ac.Count, (($top | ForEach-Object { '{0} ({1}x)' -f $_.Name, $_.Count }) -join ', ')) $ft $fx }
        else { F 'Programmabstürze' 'Good' 'Keine in 7 Tagen.' }
        # Dienste
        $need = 'Winmgmt', 'EventLog', 'Dhcp', 'Dnscache', 'LanmanWorkstation', 'Spooler', 'Audiosrv', 'AudioEndpointBuilder', 'WSearch', 'mpssvc', 'CryptSvc', 'Schedule', 'Themes', 'ProfSvc', 'BFE', 'nsi', 'Power', 'RpcSs', 'SENS', 'UserManager', 'Wcmsvc', 'WlanSvc', 'FontCache'
        $bad = @(Get-CimInstance Win32_Service -ErrorAction SilentlyContinue | Where-Object { $need -contains $_.Name -and $_.StartMode -eq 'Auto' -and $_.State -ne 'Running' })
        $off = @(Get-CimInstance Win32_Service -ErrorAction SilentlyContinue | Where-Object { $_.Name -in 'Winmgmt', 'EventLog', 'Dhcp', 'Dnscache', 'CryptSvc', 'BFE', 'mpssvc', 'Audiosrv' -and $_.StartMode -eq 'Disabled' })
        if ($bad.Count -or $off.Count) {
            $fx = @(); foreach ($x in $bad + $off) { switch -Regex ($x.Name) { 'Spooler' { $fx += 'Spooler' } 'Audio' { $fx += 'Audio' } 'WSearch' { $fx += 'SearchReset' } 'Winmgmt' { $fx += 'Wmi' } 'FontCache' { $fx += 'FontCache' } 'Dhcp|Dnscache|nsi|Wcmsvc|WlanSvc' { $fx += 'Winsock' } } }
            F 'Wichtige Dienste' 'Error' ('Laufen nicht: {0}' -f ((@($bad + $off) | ForEach-Object { '{0} ({1})' -f $_.DisplayName, $_.StartMode }) -join ', ')) 'Passende Reparatur ausführen oder Dienst in der Computerverwaltung starten.' @($fx | Select-Object -Unique)
        } else { F 'Wichtige Dienste' 'Good' 'Alle wichtigen Windows-Dienste laufen.' }
        # Geräte
        $dev = @(Get-CimInstance Win32_PnPEntity -ErrorAction SilentlyContinue | Where-Object { $_.ConfigManagerErrorCode -and $_.ConfigManagerErrorCode -ne 22 -and -not ($_.ConfigManagerErrorCode -eq 24 -and ([string]$_.DeviceID -match '^ACPI\\(PNP03|PNP0F|HPQ8001|MSF0001)' -or [string]$_.Name -match 'PS/2')) -and (@((Get-ItemProperty 'HKLM:\SOFTWARE\PCPflege' -Name DevIgnore -ErrorAction SilentlyContinue).DevIgnore) -notcontains [string]$_.DeviceID) })
        if ($dev.Count) { F 'Geräte' 'Warn' ('{0} Gerät(e) mit Problem: {1}' -f $dev.Count, (($dev | Select-Object -First 4 | ForEach-Object { '{0} (Code {1})' -f $_.Name, $_.ConfigManagerErrorCode }) -join ', ')) 'Seite Treiber: Treiber prüfen und aktualisieren.' }
        else { F 'Geräte' 'Good' 'Alle Geräte arbeiten ohne Fehler.' }
        # Netzwerk
        $gw = @(Get-NetRoute -DestinationPrefix '0.0.0.0/0' -ErrorAction SilentlyContinue | Sort-Object RouteMetric | Select-Object -First 1)
        $png = New-Object Net.NetworkInformation.Ping
        $gwOk = $false; if ($gw) { try { $gwOk = $png.Send([string]$gw[0].NextHop, 1500).Status -eq 'Success' } catch { } }
        $dnsOk = $false; try { $dnsOk = [bool][Net.Dns]::GetHostAddresses('www.microsoft.com') } catch { }
        $webOk = $false; try { $wr = [Net.WebRequest]::Create('http://www.msftconnecttest.com/connecttest.txt'); $wr.Timeout = 5000; $resp = $wr.GetResponse(); $webOk = $true; $resp.Close() } catch { }
        $px = Get-ItemProperty 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Internet Settings' -ErrorAction SilentlyContinue
        if (-not $gw) { F 'Netzwerk' 'Error' 'Kein Router/Gateway - keine Netzwerkverbindung.' 'Kabel/WLAN prüfen, Adapter neu starten, IP neu holen.' @('AdapterRestart', 'IpRenew', 'Winsock') }
        elseif (-not $gwOk -and -not $webOk) { F 'Netzwerk' 'Error' ('Router {0} antwortet nicht.' -f $gw[0].NextHop) 'Adapter neu starten und IP neu holen.' @('AdapterRestart', 'IpRenew', 'DnsFlush') }
        elseif (-not $dnsOk) { F 'Netzwerk' 'Error' 'Namensauflösung (DNS) funktioniert nicht.' 'DNS-Cache leeren, TCP/IP zurücksetzen.' @('DnsFlush', 'Winsock') }
        elseif (-not $webOk) { F 'Netzwerk' 'Warn' 'Router erreichbar, Internet-Test fehlgeschlagen (Proxy/Firewall?).' 'Proxy zurücksetzen, Winsock zurücksetzen.' @('ProxyReset', 'DnsFlush', 'Winsock') }
        else { F 'Netzwerk' 'Good' ('Router {0}, DNS und Internet in Ordnung.' -f $gw[0].NextHop) }
        if ($px.ProxyEnable -eq 1) { F 'Proxy' 'Warn' ('Proxy eingestellt: {0}' -f $px.ProxyServer) 'Falls nicht gewollt (Schadsoftware setzt gern Proxys): zurücksetzen.' @('ProxyReset') }
        $hosts = @(Get-Content (Join-Path $sys 'drivers\etc\hosts') -ErrorAction SilentlyContinue | Where-Object { $_.Trim() -and $_.Trim() -notlike '#*' })
        if ($hosts.Count) { F 'hosts-Datei' 'Info' ('{0} eigene Einträge, z.B. {1}' -f $hosts.Count, ($hosts[0] -replace '\s+', ' ')) 'Nur zurücksetzen, wenn Seiten falsch umgeleitet werden.' @('HostsReset') }
        # Zeit
        $ts = Get-CimInstance Win32_Service -Filter "Name='W32Time'" -ErrorAction SilentlyContinue
        if ($ts -and $ts.StartMode -eq 'Disabled') { F 'Uhrzeit' 'Warn' 'Zeitdienst ist deaktiviert - falsche Uhrzeit stört Anmeldungen und Zertifikate.' 'Uhrzeit synchronisieren.' @('TimeSync') } else { F 'Uhrzeit' 'Good' 'Zeitdienst aktiv.' }
        # Sicherheit
        try { $mp = Get-MpComputerStatus -ErrorAction Stop
            if (-not $mp.RealTimeProtectionEnabled) { F 'Virenschutz' 'Warn' 'Defender-Echtzeitschutz ist aus (anderer Virenschutz aktiv?).' 'Windows-Sicherheit prüfen.' }
            elseif ($mp.AntivirusSignatureAge -gt 3) { F 'Virenschutz' 'Warn' ('Signaturen {0} Tage alt.' -f $mp.AntivirusSignatureAge) 'Defender-Signaturen neu laden.' @('Defender') }
            else { F 'Virenschutz' 'Good' ('Defender aktiv, Signaturen {0} Tag(e) alt.' -f $mp.AntivirusSignatureAge) }
        } catch { F 'Virenschutz' 'Info' 'Defender-Status nicht lesbar (anderer Virenschutz installiert?).' }
        # WMI
        $null = & (Join-Path $sys 'wbem\winmgmt.exe') /verifyrepository 2>&1
        if ($LASTEXITCODE -ne 0) { F 'WMI' 'Error' 'WMI-Datenbank ist inkonsistent.' 'WMI reparieren.' @('Wmi') } else { F 'WMI' 'Good' 'WMI-Datenbank konsistent.' }
        # Wiederherstellung
        $re = (& (Join-Path $sys 'reagentc.exe') /info 2>&1) -join ' '
        if ($re -match '(Enabled|Aktiviert)') { F 'Wiederherstellung (WinRE)' 'Good' 'Aktiv - Starthilfe und Zurücksetzen möglich.' } else { F 'Wiederherstellung (WinRE)' 'Warn' 'WinRE ist aus - im Notfall keine Starthilfe.' 'WinRE einschalten.' @('ReAgent') }
        $rp = @(); try { $rp = @(Get-ComputerRestorePoint -ErrorAction Stop) } catch { }
        if (-not $rp.Count) { F 'Wiederherstellungspunkte' 'Warn' 'Keine Wiederherstellungspunkte vorhanden.' 'Computerschutz einschalten und Punkt erstellen.' @('SysProtect', 'RestorePoint') }
        else { F 'Wiederherstellungspunkte' 'Good' ('{0} vorhanden, letzter: {1}' -f $rp.Count, ([Management.ManagementDateTimeConverter]::ToDateTime($rp[-1].CreationTime)).ToString('dd.MM.yyyy HH:mm')) }
        # Autostart und Speicher
        $as = 0; foreach ($k in 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Run', 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Run', 'HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Run') { $p = Get-ItemProperty $k -ErrorAction SilentlyContinue; if ($p) { $as += @($p.PSObject.Properties | Where-Object { $_.Name -notlike 'PS*' }).Count } }
        if ($as -gt 12) { F 'Autostart' 'Warn' ('{0} Programme starten mit Windows.' -f $as) 'Seite Tuning > Autostart: "Nur das Nötige".' } else { F 'Autostart' 'Good' ('{0} Programme im Autostart.' -f $as) }
        $memPct = [math]::Round(100 - $os.FreePhysicalMemory * 100 / $os.TotalVisibleMemorySize)
        if ($memPct -gt 90) { F 'Arbeitsspeicher' 'Warn' ('{0} % belegt.' -f $memPct) 'Programme schließen (Task-Manager), Autostart reduzieren.' } else { F 'Arbeitsspeicher' 'Good' ('{0} % belegt.' -f $memPct) }
        return , $r
    } -Done {
        param($res, $err)
        $ui.BtnRepScan.IsEnabled = $true
        if ($err) { $ui.RepScanInfo.Text = 'Fehlersuche fehlgeschlagen: ' + $err.Message; return }
        $all = @($res | ForEach-Object { $_ } | Where-Object { $_ })
        $ord = @{ Error = 0; Warn = 1; Info = 2; Good = 3 }
        $script:RepFound = @($all | Sort-Object @{ e = { $ord[$_.Level] } }, Area)
        Set-GridItems $ui.RepFindings $script:RepFound
        $e = @($all | Where-Object Level -eq 'Error').Count; $w = @($all | Where-Object Level -eq 'Warn').Count
        $ui.RepScanInfo.Text = if ($e + $w) { '{0} Probleme und {1} Hinweise gefunden. "Empfohlene Reparaturen auswählen" hakt unten die passenden Reparaturen an.' -f $e, $w } else { 'Alles in Ordnung - keine Probleme gefunden.' }
        $ui.BtnRepPick.IsEnabled = [bool]@($all | Where-Object { $_.Fix -and $_.Level -in 'Error', 'Warn' }).Count
    }
}
function Select-RepRecommended {
    $keys = @($script:RepFound | Where-Object { $_.Fix -and $_.Level -in 'Error', 'Warn' } | ForEach-Object { $_.Fix -split ',' } | Where-Object { $_ } | Select-Object -Unique)
    if (-not $keys.Count) { return }
    if ($keys | Where-Object { $_ -notin 'DiskHealth', 'DnsFlush', 'WuScan', 'TimeSync' }) { $keys = @('RestorePoint') + $keys }
    Set-RepSelection $keys
    $ui.RepGroups.BringIntoView()
    $ui.StatusText.Text = '{0} empfohlene Reparaturen ausgewählt - prüfen und "Ausgewählte Reparaturen starten".' -f $keys.Count
}
function Update-RestorePoints {
    $rows = @()
    try {
        $rows = @(Get-ComputerRestorePoint -ErrorAction Stop | Sort-Object SequenceNumber -Descending | ForEach-Object {
            $k = switch ([int]$_.RestorePointType) { 0 { 'Programm installiert' } 1 { 'Programm entfernt' } 10 { 'Treiber installiert' } 12 { 'Einstellungen geändert' } 13 { 'Wiederherstellung abgebrochen' } default { 'Sonstiges' } }
            [pscustomobject]@{ Date = ([Management.ManagementDateTimeConverter]::ToDateTime($_.CreationTime)).ToString('dd.MM.yyyy HH:mm'); Desc = $_.Description; Kind = $k; Seq = [int]$_.SequenceNumber } })
    } catch { }
    Set-GridItems $ui.RepPoints $rows
}
function Build-RepTools {
    $ui.RepTools.Children.Clear()
    $tools = @(
        @('Mit Windows Update neu aufspielen', 'ms-settings:recovery', 'Einstellungen > System > Wiederherstellung: "Probleme mithilfe von Windows Update beheben" installiert die aktuelle Windows-Version neu - Programme und Dateien bleiben.')
        @('Reparaturinstallation mit ISO ...', '::iso', 'Windows-Setup aus einer ISO als Upgrade - repariert Windows komplett, Programme und Dateien bleiben.')
        @('Zur vorherigen Windows-Version', 'ms-settings:recovery', 'Nach einem Funktionsupdate 10 Tage lang möglich.')
        @('Erweiterte Startoptionen', '::advanced', 'Starthilfe, abgesicherter Modus, Eingabeaufforderung, Systemabbild.')
        @('Problembehandlungen von Windows', 'ms-settings:troubleshoot', 'Die eingebauten Problemlöser für Audio, Drucker, Netzwerk usw.')
        @('Zuverlässigkeitsverlauf', 'perfmon.exe /rel', 'Zeitleiste aller Abstürze und Installationen.')
        @('Ereignisanzeige', 'eventvwr.msc', '')
        @('Ressourcenmonitor', 'resmon.exe', '')
        @('Systeminformationen', 'msinfo32.exe', '')
        @('Speicherdiagnose', 'mdsched.exe', 'Arbeitsspeicher beim Neustart testen.')
        @('CBS-Protokoll (SFC)', '::cbs', '')
        @('DISM-Protokoll', '::dism', '')
        @('Netzwerk zurücksetzen (Einstellungen)', 'ms-settings:network-advancedsettings', '')
        @('Fehlerdaten sammeln', '::diag', 'Bluescreens und Abstürze auswerten.')
    )
    foreach ($t in $tools) {
        $b = New-Object Windows.Controls.Button; $b.Style = $window.FindResource('Sec'); $b.Content = $t[0]; $b.Tag = $t[1]; $b.Padding = '12,6'; $b.Margin = '0,0,8,8'
        if ($t[2]) { $b.ToolTip = $t[2] }
        $b.Add_Click({ param($s, $e)
            $c = [string]$s.Tag
            switch ($c) {
                '::iso'      { $f = Select-IsoFile 'Windows-ISO für die Reparaturinstallation wählen'; if ($f -and (Confirm-Ui ("Windows-Setup mit`n{0}`nals Reparaturinstallation starten? Programme und Dateien bleiben erhalten, der PC startet mehrmals neu." -f $f))) { try { $x = Start-IsoUpgrade $f; $ui.StatusText.Text = 'Windows-Setup gestartet: ' + $x } catch { Show-UiError $_.Exception.Message } } }
                '::advanced' { Invoke-PowerAction 'Advanced' }
                '::cbs'      { Start-Process notepad.exe (Join-Path $env:windir 'Logs\CBS\CBS.log') }
                '::dism'     { Start-Process notepad.exe (Join-Path $env:windir 'Logs\DISM\dism.log') }
                '::diag'     { $ui.Tabs.SelectedItem = $ui.TabDiag }
                default      { if ($c -like 'ms-settings:*') { Start-Process $c } else { Start-Tool $c } }
            } })
        [void]$ui.RepTools.Children.Add($b)
    }
}

# ---------------------------------------------------------------- Individualisieren (Oberfläche)
# ThinkPad-Tastaturbeleuchtung über den Lenovo-Energieverwaltungstreiber (\\.\IBMPmDrv) - wie Fn+Leertaste
$KbdCs = @"
using System; using System.Runtime.InteropServices;
namespace PCPflegeKbd {
public static class TpKbd {
  [DllImport("kernel32.dll", SetLastError=true, CharSet=CharSet.Unicode)] static extern IntPtr CreateFile(string n, uint a, uint s, IntPtr sa, uint c, uint f, IntPtr t);
  [DllImport("kernel32.dll", SetLastError=true)] static extern bool DeviceIoControl(IntPtr h, uint code, ref uint inBuf, uint inSize, out uint outBuf, uint outSize, out uint ret, IntPtr ov);
  [DllImport("kernel32.dll")] static extern bool CloseHandle(IntPtr h);
  static IntPtr Open() { return CreateFile("\\\\.\\IBMPmDrv", 0x80000000, 1, IntPtr.Zero, 3, 0x80, IntPtr.Zero); }
  public static int Get() { IntPtr h = Open(); if (h == new IntPtr(-1)) return -1; uint snt = 0, rcv = 0, r = 0; bool ok = DeviceIoControl(h, 0x222000, ref snt, 4, out rcv, 4, out r, IntPtr.Zero); CloseHandle(h); if (!ok || r == 0 || (rcv & 0x50000) == 0) return -2; return (int)(rcv & 0xF); }
  public static int Set(int level) { IntPtr h = Open(); if (h == new IntPtr(-1)) return -1; uint snt = 0, rcv = 0, r = 0; bool ok = DeviceIoControl(h, 0x222000, ref snt, 4, out rcv, 4, out r, IntPtr.Zero); if (!ok || r == 0 || (rcv & 0x50000) == 0) { CloseHandle(h); return -2; } snt = ((rcv & 0x200000) != 0 ? 0x100u : 0u) | (rcv & 0xF0) | (uint)level; rcv = 0; ok = DeviceIoControl(h, 0x222004, ref snt, 4, out rcv, 4, out r, IntPtr.Zero); CloseHandle(h); return ok ? 0 : -3; }
}}
"@
$KbdTaskName = 'PC-Pflege Tastaturbeleuchtung'
$KbdVantageBase = 'C:\ProgramData\Lenovo\Vantage\Addins\ThinkKeyboardAddin'
function Set-KbdLevelNow([int]$Level) {
    Add-Type -TypeDefinition $KbdCs -ErrorAction SilentlyContinue
    $r = [PCPflegeKbd.TpKbd]::Set($Level)
    if ($r -ne 0) {
        $dir = Get-ChildItem $KbdVantageBase -Directory -ErrorAction SilentlyContinue | Sort-Object Name -Descending | Select-Object -First 1
        if ($dir) { Add-Type -Path (Join-Path $dir.FullName 'Keyboard_Core.dll'); $c = New-Object Keyboard_Core.KeyboardControl; $d = $null; $null = $c.SetKeyboardBackLightStatus($Level, [ref]$d); $r = 0 }
    }
    return $r
}
function Register-KbdTask([int]$Level, [bool]$EveryMinute) {
    $dir = Join-Path $DataDir 'Tastatur'; New-Item $dir -ItemType Directory -Force | Out-Null
    $helper = Join-Path $dir 'Tastaturlicht.ps1'
    $body = @(
        'param([int]$Level = 2)',
        '# PC-Tools: setzt die ThinkPad-Tastaturbeleuchtung (angelegt von der Seite Individualisieren)',
        ('$cs = @"' + "`r`n" + $KbdCs.Trim() + "`r`n" + '"@'),
        'Add-Type -TypeDefinition $cs -ErrorAction SilentlyContinue',
        'Start-Sleep -Seconds 2',
        '$r = [PCPflegeKbd.TpKbd]::Set($Level)',
        ('if ($r -ne 0) { $d = Get-ChildItem ''VANTAGEBASE'' -Directory -ErrorAction SilentlyContinue | Sort-Object Name -Descending | Select-Object -First 1; if ($d) { try { Add-Type -Path (Join-Path $d.FullName ''Keyboard_Core.dll''); $c = New-Object Keyboard_Core.KeyboardControl; $x = $null; $null = $c.SetKeyboardBackLightStatus($Level, [ref]$x); $r = 0 } catch { $r = -9 } } }').Replace('VANTAGEBASE', $KbdVantageBase),
        '"{0:dd.MM.yyyy HH:mm:ss}  Stufe {1}  Ergebnis {2}" -f (Get-Date), $Level, $r | Set-Content -LiteralPath (Join-Path $PSScriptRoot ''letzter-lauf.txt'') -Encoding UTF8'
    ) -join "`r`n"
    Set-Content -LiteralPath $helper -Value $body -Encoding UTF8
    $ps = Join-Path $env:windir 'System32\WindowsPowerShell\v1.0\powershell.exe'
    $ev = { param($prov, $id) '<EventTrigger><Enabled>true</Enabled><Delay>PT3S</Delay><Subscription>&lt;QueryList&gt;&lt;Query Id="0" Path="System"&gt;&lt;Select Path="System"&gt;*[System[Provider[@Name=''{0}''] and EventID={1}]]&lt;/Select&gt;&lt;/Query&gt;&lt;/QueryList&gt;</Subscription></EventTrigger>' -f $prov, $id }
    $trig = '<BootTrigger><Enabled>true</Enabled><Delay>PT20S</Delay></BootTrigger><LogonTrigger><Enabled>true</Enabled><Delay>PT5S</Delay></LogonTrigger>' +
            (& $ev 'Microsoft-Windows-Power-Troubleshooter' 1) + (& $ev 'Microsoft-Windows-Kernel-Power' 507) + (& $ev 'Microsoft-Windows-Kernel-Power' 105)
    if ($EveryMinute) { $trig += '<TimeTrigger><Enabled>true</Enabled><StartBoundary>2024-01-01T00:00:00</StartBoundary><Repetition><Interval>PT1M</Interval><StopAtDurationEnd>false</StopAtDurationEnd></Repetition></TimeTrigger>' }
    $xml = @"
<?xml version="1.0" encoding="UTF-16"?>
<Task version="1.4" xmlns="http://schemas.microsoft.com/windows/2004/02/mit/task">
  <RegistrationInfo><Description>PC-Tools: Tastaturbeleuchtung immer auf Stufe $Level halten</Description></RegistrationInfo>
  <Triggers>$trig</Triggers>
  <Principals><Principal id="Author"><UserId>S-1-5-18</UserId><RunLevel>HighestAvailable</RunLevel></Principal></Principals>
  <Settings><MultipleInstancesPolicy>IgnoreNew</MultipleInstancesPolicy><DisallowStartIfOnBatteries>false</DisallowStartIfOnBatteries><StopIfGoingOnBatteries>false</StopIfGoingOnBatteries><StartWhenAvailable>true</StartWhenAvailable><ExecutionTimeLimit>PT2M</ExecutionTimeLimit><Hidden>true</Hidden><Priority>7</Priority></Settings>
  <Actions Context="Author"><Exec><Command>$ps</Command><Arguments>-NoProfile -NonInteractive -WindowStyle Hidden -ExecutionPolicy Bypass -File "$helper" -Level $Level</Arguments></Exec></Actions>
</Task>
"@
    Register-ScheduledTask -TaskName $KbdTaskName -Xml $xml -Force | Out-Null
}
# ---- BIOS / UEFI: alle Einstellungen (Lenovo, HP, Dell) und Firmware-Infos
function Get-BiosFull {
    $mk = [string](Get-CimInstance Win32_ComputerSystem).Manufacturer
    $list = [System.Collections.Generic.List[object]]::new()
    function Add-B($V, $N, $L, $C, $O, $T, $RO, $P) { $list.Add([pscustomobject]@{ Vendor = $V; Name = [string]$N; Label = [string]$L; Current = [string]$C; Options = @($O | Where-Object { $_ -ne $null -and [string]$_ -ne '' } | ForEach-Object { [string]$_ }); Type = $T; ReadOnly = [bool]$RO; Path = [string]$P }) }
    if ($mk -match 'Lenovo') {
        $sel = $null; try { $sel = Get-WmiObject -Namespace root\wmi -Class Lenovo_GetBiosSelections -ErrorAction Stop } catch { }
        foreach ($s in @(Get-CimInstance -Namespace root\wmi -ClassName Lenovo_BiosSetting -ErrorAction Stop)) {
            $c = [string]$s.CurrentSetting; if (-not $c) { continue }
            $main, $opt = $c -split ';', 2; $n, $v = $main -split ',', 2
            $opts = @(); if ($opt -match '\[Optional:([^\]]*)\]') { $opts = $Matches[1] -split ',' } elseif ($sel) { try { $opts = ([string]$sel.GetBiosSelections($n).Selections) -split ',' } catch { } }
            $opts = @($opts | Where-Object { $_ })
            Add-B 'Lenovo' $n $n $v $opts $(if ($n -match 'BootOrder$|BootOrder[^L]') { 'Order' } elseif ($opts.Count) { 'Enum' } else { 'String' }) $false ''
        }
    } elseif ($mk -match 'HP|Hewlett') {
        $ns = 'root\HP\InstrumentedBIOS'
        foreach ($s in @(Get-CimInstance -Namespace $ns -ClassName HP_BIOSEnumeration -ErrorAction Stop)) { Add-B 'HP' $s.Name $s.Name $s.CurrentValue $s.PossibleValues 'Enum' ($s.IsReadOnly -eq 1) $s.Path }
        foreach ($s in @(Get-CimInstance -Namespace $ns -ClassName HP_BIOSInteger -ErrorAction SilentlyContinue)) { Add-B 'HP' $s.Name $s.Name $s.IntegerValue @() ('Integer {0}-{1}' -f $s.LowerBound, $s.UpperBound) ($s.IsReadOnly -eq 1) $s.Path }
        foreach ($s in @(Get-CimInstance -Namespace $ns -ClassName HP_BIOSString -ErrorAction SilentlyContinue)) { if ($s.Name -match 'Password') { continue }; Add-B 'HP' $s.Name $s.Name $s.Value @() 'String' ($s.IsReadOnly -eq 1) $s.Path }
        foreach ($s in @(Get-CimInstance -Namespace $ns -ClassName HP_BIOSOrderedList -ErrorAction SilentlyContinue)) { Add-B 'HP' $s.Name $s.Name $s.Value @() 'Order' ($s.IsReadOnly -eq 1) $s.Path }
    } elseif ($mk -match 'Dell') {
        $ns = 'root\dcim\sysman\biosattributes'
        foreach ($s in @(Get-CimInstance -Namespace $ns -ClassName EnumerationAttribute -ErrorAction Stop)) { Add-B 'Dell' $s.AttributeName $(if ($s.DisplayName) { '{0} ({1})' -f $s.DisplayName, $s.AttributeName } else { $s.AttributeName }) (@($s.CurrentValue)[0]) $s.PossibleValue 'Enum' ($s.IsReadonly -eq 1) '' }
        foreach ($s in @(Get-CimInstance -Namespace $ns -ClassName IntegerAttribute -ErrorAction SilentlyContinue)) { Add-B 'Dell' $s.AttributeName $(if ($s.DisplayName) { '{0} ({1})' -f $s.DisplayName, $s.AttributeName } else { $s.AttributeName }) (@($s.CurrentValue)[0]) @() ('Integer {0}-{1}' -f $s.LowerBound, $s.UpperBound) ($s.IsReadonly -eq 1) '' }
        foreach ($s in @(Get-CimInstance -Namespace $ns -ClassName StringAttribute -ErrorAction SilentlyContinue)) { Add-B 'Dell' $s.AttributeName $(if ($s.DisplayName) { '{0} ({1})' -f $s.DisplayName, $s.AttributeName } else { $s.AttributeName }) (@($s.CurrentValue)[0]) @() 'String' ($s.IsReadonly -eq 1) '' }
    } else { return , $list }
    return , $list
}
function Get-BiosInfo {
    $cs = Get-CimInstance Win32_ComputerSystem; $csp = Get-CimInstance Win32_ComputerSystemProduct; $b = Get-CimInstance Win32_BIOS
    $mk = [string]$cs.Manufacturer
    $vendor = if ($mk -match 'Lenovo') { 'Lenovo' } elseif ($mk -match 'HP|Hewlett') { 'HP' } elseif ($mk -match 'Dell') { 'Dell' } elseif ($mk -match 'Microsoft') { 'Microsoft' } elseif ($mk -match 'ASUS') { 'ASUS' } elseif ($mk -match 'Acer') { 'Acer' } elseif ($mk -match 'Micro-Star|MSI') { 'MSI' } elseif ($mk -match 'Gigabyte') { 'Gigabyte' } elseif ($mk -match 'Fujitsu') { 'Fujitsu' } elseif ($mk -match 'Medion') { 'Medion' } else { $mk }
    $model = if ($vendor -eq 'Lenovo' -and $csp.Version) { '{0} ({1})' -f $csp.Version, $cs.Model } else { [string]$cs.Model }
    $fw = 'unbekannt'; try { $t = (Get-ItemProperty 'HKLM:\SYSTEM\CurrentControlSet\Control' -Name PEFirmwareType -ErrorAction Stop).PEFirmwareType; $fw = @{ 1 = 'Legacy-BIOS (CSM)'; 2 = 'UEFI' }[[int]$t] } catch { }
    $sb = 'nicht unterstützt'; try { $sb = if (Confirm-SecureBootUEFI -ErrorAction Stop) { 'an' } else { 'aus' } } catch { }
    $tpm = 'nicht gefunden'; try { $tp = Get-CimInstance -Namespace root\cimv2\security\microsofttpm -ClassName Win32_Tpm -ErrorAction Stop; if ($tp) { $tpm = 'TPM {0}{1}' -f (([string]$tp.SpecVersion -split ',')[0]), $(if ($tp.IsEnabled_InitialValue) { ', aktiv' } else { ', inaktiv' }) } } catch { }
    $iface = 'keine'; $pw = 'nicht auslesbar'
    switch ($vendor) {
        'Lenovo' { try { $null = Get-CimInstance -Namespace root\wmi -ClassName Lenovo_BiosSetting -ErrorAction Stop | Select-Object -First 1; $iface = 'Lenovo BIOS-WMI (lesen und ändern)'
                   $ps = [int](Get-CimInstance -Namespace root\wmi -ClassName Lenovo_BiosPasswordSettings -ErrorAction Stop).PasswordState
                   $n = @(); if ($ps -band 1) { $n += 'Einschalt-Kennwort' }; if ($ps -band 2) { $n += 'Supervisor-/Admin-Kennwort' }; if ($ps -band 4) { $n += 'Festplatten-Kennwort' }; if ($ps -band 64) { $n += 'Systemverwaltungs-Kennwort' }
                   $pw = if ($n.Count) { ($n -join ', ') + ' gesetzt' } else { 'keine gesetzt' } } catch { } }
        'HP' { try { $pws = @(Get-CimInstance -Namespace root\HP\InstrumentedBIOS -ClassName HP_BIOSPassword -ErrorAction Stop); $iface = 'HP BIOS-WMI (lesen und ändern)'
                   $n = @($pws | Where-Object { $_.IsSet -eq 1 } | ForEach-Object { $_.Name }); $pw = if ($n.Count) { ($n -join ', ') + ' gesetzt' } else { 'keine gesetzt' } } catch { } }
        'Dell' { try { $null = Get-CimInstance -Namespace root\dcim\sysman\biosattributes -ClassName EnumerationAttribute -ErrorAction Stop | Select-Object -First 1; $iface = 'Dell BIOS-WMI (lesen und ändern)'
                   $pws = @(Get-CimInstance -Namespace root\dcim\sysman\wmisecurity -ClassName PasswordObject -ErrorAction Stop); $n = @($pws | Where-Object { $_.IsPasswordSet -eq 1 } | ForEach-Object { @{ Admin = 'Admin-Kennwort'; System = 'System-Kennwort' }[[string]$_.NameId] })
                   $pw = if ($n.Count) { ($n -join ', ') + ' gesetzt' } else { 'keine gesetzt' } } catch { $iface = 'Dell: WMI nicht verfügbar (ältere Modelle: Dell Command | Configure)' } }
    }
    [pscustomobject]@{ Vendor = $vendor; Manufacturer = $mk; Model = $model; Serial = [string]$b.SerialNumber; BiosVer = [string]$b.SMBIOSBIOSVersion; BiosDate = $b.ReleaseDate
        Ec = $(if ($b.EmbeddedControllerMajorVersion -ne $null -and $b.EmbeddedControllerMajorVersion -lt 255) { '{0}.{1}' -f $b.EmbeddedControllerMajorVersion, $b.EmbeddedControllerMinorVersion } else { '' }); Firmware = $fw; SecureBoot = $sb; Tpm = $tpm; Iface = $iface; Pw = $pw }
}
function Get-OemBiosSettings {
    $cs = Get-CimInstance Win32_ComputerSystem
    $mk = [string]$cs.Manufacturer
    $list = [System.Collections.Generic.List[object]]::new()
    if ($mk -match 'Lenovo') {
        $sel = $null; try { $sel = Get-WmiObject -Namespace root\wmi -Class Lenovo_GetBiosSelections -ErrorAction Stop } catch { }
        foreach ($s in @(Get-CimInstance -Namespace root\wmi -ClassName Lenovo_BiosSetting -ErrorAction Stop)) {
            $c = [string]$s.CurrentSetting; if (-not $c) { continue }
            $main, $opt = $c -split ';', 2; $n, $v = $main -split ',', 2
            $opts = @(); if ($opt -match '\[Optional:([^\]]*)\]') { $opts = $Matches[1] -split ',' } elseif ($sel) { try { $opts = ([string]$sel.GetBiosSelections($n).Selections) -split ',' } catch { } }
            $list.Add([pscustomobject]@{ Vendor = 'Lenovo'; Name = $n; Label = $n; Current = $v; Options = @($opts | Where-Object { $_ }) })
        }
    } elseif ($mk -match 'HP|Hewlett') {
        foreach ($s in @(Get-CimInstance -Namespace root\HP\InstrumentedBIOS -ClassName HP_BIOSEnumeration -ErrorAction Stop)) {
            if ($s.IsReadOnly -eq 1) { continue }
            $list.Add([pscustomobject]@{ Vendor = 'HP'; Name = [string]$s.Name; Label = [string]$s.Name; Current = [string]$s.CurrentValue; Options = @($s.PossibleValues | Where-Object { $_ }) })
        }
    } elseif ($mk -match 'Dell') {
        foreach ($s in @(Get-CimInstance -Namespace root\dcim\sysman\biosattributes -ClassName EnumerationAttribute -ErrorAction Stop)) {
            $list.Add([pscustomobject]@{ Vendor = 'Dell'; Name = [string]$s.AttributeName; Label = $(if ($s.DisplayName) { '{0} ({1})' -f $s.DisplayName, $s.AttributeName } else { [string]$s.AttributeName }); Current = [string](@($s.CurrentValue)[0]); Options = @($s.PossibleValue | Where-Object { $_ }) })
        }
    } else { throw ('Für "{0}" gibt es keine BIOS-Schnittstelle in Windows (unterstützt: Lenovo, HP, Dell).' -f $mk) }
    return , $list
}
function Set-OemBiosSettings($Changes, [string]$Pwd) {
    $out = @()
    foreach ($c in $Changes) {
        $ok = $false; $msg = ''
        try {
            switch ($c.Vendor) {
                'Lenovo' { $arg = if ($Pwd) { '{0},{1},{2},ascii,us' -f $c.Name, $c.Value, $Pwd } else { '{0},{1}' -f $c.Name, $c.Value }; $msg = [string](Get-WmiObject -Namespace root\wmi -Class Lenovo_SetBiosSetting).SetBiosSetting($arg).return; $ok = $msg -eq 'Success' }
                'HP'     { $r = (Get-WmiObject -Namespace root\HP\InstrumentedBIOS -Class HP_BIOSSettingInterface).SetBIOSSetting($c.Name, $c.Value, $(if ($Pwd) { '<utf-16/>' + $Pwd } else { '' })); $msg = [string]$r.Return; $ok = $r.Return -eq 0 }
                'Dell'   {
                    $bai = Get-CimInstance -Namespace root\dcim\sysman\biosattributes -ClassName BIOSAttributeInterface
                    $a = @{ AttributeName = $c.Name; AttributeValue = $c.Value; SecType = [uint32]0; SecHndCount = [uint32]0; SecHandle = [byte[]]@() }
                    if ($Pwd) { $b = [Text.Encoding]::ASCII.GetBytes($Pwd); $a.SecType = [uint32]1; $a.SecHndCount = [uint32]$b.Length; $a.SecHandle = $b }
                    $r = Invoke-CimMethod -InputObject $bai -MethodName SetAttribute -Arguments $a; $msg = [string]$r.Status; $ok = $r.Status -eq 0
                }
            }
        } catch { $msg = $_.Exception.Message }
        $out += [pscustomobject]@{ Name = $c.Name; Value = $c.Value; Ok = $ok; Msg = $msg }
    }
    if (@($Changes | Where-Object { $_.Vendor -eq 'Lenovo' }).Count -and @($out | Where-Object Ok).Count) {
        $sv = Get-WmiObject -Namespace root\wmi -Class Lenovo_SaveBiosSettings
        $r = if ($Pwd) { $sv.SaveBiosSettings(('{0},ascii,us' -f $Pwd)).return } else { $sv.SaveBiosSettings().return }
        if ($r -ne 'Success') { $out += [pscustomobject]@{ Name = 'Speichern'; Value = ''; Ok = $false; Msg = [string]$r } }
    }
    return $out
}
$CuBiosDaily = '(?i)keyboard|kbd|backlit|backlight|illumin|fn|f1|hotkey|action.?key|battery|batt|charg|akku|usb.*(power|charg)|always.?on|wake|wol|lan|lid|power.?on|after.?power|ac.?(recovery|power)|fan|thermal|performance|numlock|touchpad|trackpoint|camera|microphone|audio|speaker|boot.?(logo|beep|up)|post|splash|tpm|virtual|vt-?x|hyper|secure.?boot|flip|intelligent|express.?charge|adaptive|light'
function Set-ComboByTag($Combo, [string]$Tag) {
    foreach ($i in $Combo.Items) { if ([string]$i.Tag -eq $Tag) { $Combo.SelectedItem = $i; return } }
    # Wert steht nicht in der Liste: als eigenen Eintrag übernehmen, damit beim Speichern nichts verstellt wird
    if ($Tag -match '^\d+$') { $ci = New-Object Windows.Controls.ComboBoxItem; $ci.Content = '{0} (aktueller Wert)' -f $Tag; $ci.Tag = $Tag; [void]$Combo.Items.Add($ci); $Combo.SelectedItem = $ci } else { $Combo.SelectedIndex = -1 }
}
function Get-ComboTag($Combo) { if ($Combo.SelectedItem) { [string]$Combo.SelectedItem.Tag } else { '' } }
function Get-ComboInt($Combo, [int]$Factor = 1) { $t = Get-ComboTag $Combo; if ($t -match '^-?\d+$') { [int]$t * $Factor } else { -1 } }
function Get-PwrValue([string]$Sub, [string]$Set) {
    $o = @(& powercfg.exe /q SCHEME_CURRENT $Sub $Set 2>$null)
    $hex = @($o | Where-Object { $_ -match ':\s*0x[0-9a-fA-F]+\s*$' } | Select-Object -Last 2 | ForEach-Object { [Convert]::ToInt32(($_ -replace '^.*0x', ''), 16) })
    if ($hex.Count -ge 2) { return @($hex[0], $hex[1]) } else { return @(-1, -1) }
}
function Set-PwrValue([string]$Sub, [string]$Set, [int]$Ac, [int]$Dc) {
    if ($Ac -ge 0) { $null = & powercfg.exe /setacvalueindex SCHEME_CURRENT $Sub $Set $Ac 2>&1 }
    if ($Dc -ge 0) { $null = & powercfg.exe /setdcvalueindex SCHEME_CURRENT $Sub $Set $Dc 2>&1 }
}
$TouchKey = 'HKCU:\Software\Microsoft\Windows\CurrentVersion\PrecisionTouchPad'
Add-Type -Name Spi -Namespace PCPflege -MemberDefinition @'
[DllImport("user32.dll", SetLastError=true)] public static extern bool SystemParametersInfo(uint a, uint u, IntPtr p, uint f);
[DllImport("user32.dll", SetLastError=true)] public static extern bool SystemParametersInfo(uint a, uint u, int[] p, uint f);
[DllImport("user32.dll", SetLastError=true)] public static extern bool SystemParametersInfo(uint a, uint u, ref uint p, uint f);
[DllImport("user32.dll")] public static extern bool SwapMouseButton(bool s);
'@ -ErrorAction SilentlyContinue
function Load-Custom {
    # Gerät und Tastaturbeleuchtung
    $cs = Get-CimInstance Win32_ComputerSystem; $pr = Get-CimInstance Win32_ComputerSystemProduct
    $ui.CuKbdDevice.Text = '{0} {1} ({2})' -f $cs.Manufacturer, $pr.Version, $cs.Model
    $script:KbdTp = -1
    try { Add-Type -TypeDefinition $KbdCs -ErrorAction Stop; $script:KbdTp = [PCPflegeKbd.TpKbd]::Get() } catch { try { $script:KbdTp = [PCPflegeKbd.TpKbd]::Get() } catch { } }
    $vant = [bool](Get-ChildItem $KbdVantageBase -Directory -ErrorAction SilentlyContinue)
    if ($script:KbdTp -ge 0) {
        $ui.CuKbdMethod.Text = 'Lenovo-Energieverwaltungstreiber (wie Fn+Leertaste) - wird direkt gesetzt'
        $ui.CuKbdNow.Text = @('aus', 'gedimmt', 'hell')[[math]::Min(2, $script:KbdTp)]
        Set-ComboByTag $ui.CuKbdLevel ([string][math]::Min(2, $script:KbdTp))
    } elseif ($vant) { $ui.CuKbdMethod.Text = 'Lenovo Vantage (Tastatur-Modul)'; $ui.CuKbdNow.Text = 'unbekannt' }
    elseif ([string]$cs.Manufacturer -match 'HP|Hewlett|Dell') { $ui.CuKbdMethod.Text = 'Über die BIOS-Einstellungen des Herstellers (Zeitlimit "Nie" bzw. Helligkeit) - siehe unten, wird dauerhaft gespeichert.'; $ui.CuKbdNow.Text = 'siehe BIOS-Einstellungen'; $ui.CuKbdLevel.IsEnabled = $false; $ui.BtnKbdSet.IsEnabled = $false; $ui.CuKbdKeep.IsEnabled = $false; $ui.CuKbdMinute.IsEnabled = $false }
    else { $ui.CuKbdMethod.Text = 'Keine Steuerung aus Windows gefunden. ThinkPad: Lenovo "Power Management Driver" installieren (Seite Treiber > Hersteller-Tool). RGB-Tastaturen: Dynamische Beleuchtung.'; $ui.CuKbdNow.Text = '-'; $ui.CuKbdLevel.IsEnabled = $false; $ui.BtnKbdSet.IsEnabled = $false }
    $t = Get-ScheduledTask -TaskName $KbdTaskName -ErrorAction SilentlyContinue
    $ui.CuKbdKeep.IsChecked = [bool]$t
    $ui.CuKbdMinute.IsChecked = [bool]($t -and ($t.Triggers | Where-Object { $_.Repetition.Interval -eq 'PT1M' }))
    $last = Join-Path $DataDir 'Tastatur\letzter-lauf.txt'
    $ui.CuKbdTask.Text = if ($t) { 'Automatik aktiv (Aufgabe "{0}"). Letzter Lauf: {1}' -f $KbdTaskName, $(if (Test-Path $last) { (Get-Content $last -Raw).Trim() } else { 'noch keiner' }) } else { 'Automatik nicht eingerichtet - nach Neustart oder Energiesparen schaltet der Laptop das Licht selbst.' }
    # Energie
    $ui.CuPlan.Items.Clear()
    foreach ($l in @(& powercfg.exe /list 2>$null)) { if ($l -match '([0-9a-fA-F\-]{36})\s+\((.+?)\)(\s*\*)?') { $ci = New-Object Windows.Controls.ComboBoxItem; $ci.Content = $Matches[2]; $ci.Tag = $Matches[1]; [void]$ui.CuPlan.Items.Add($ci); if ($Matches[3]) { $ui.CuPlan.SelectedItem = $ci } } }
    $v = Get-PwrValue 'SUB_BUTTONS' 'LIDACTION'; Set-ComboByTag $ui.CuLidAc ([string]$v[0]); Set-ComboByTag $ui.CuLidDc ([string]$v[1])
    $v = Get-PwrValue 'SUB_BUTTONS' 'PBUTTONACTION'; Set-ComboByTag $ui.CuBtnAc ([string]$v[0]); Set-ComboByTag $ui.CuBtnDc ([string]$v[1])
    foreach ($p in @(@('SUB_VIDEO', 'VIDEOIDLE', 'CuMonAc', 'CuMonDc'), @('SUB_SLEEP', 'STANDBYIDLE', 'CuSlpAc', 'CuSlpDc'), @('SUB_SLEEP', 'HIBERNATEIDLE', 'CuHibAc', 'CuHibDc'))) {
        $v = Get-PwrValue $p[0] $p[1]
        Set-ComboByTag $ui[$p[2]] ([string]$(if ($v[0] -ge 0) { [int][math]::Round($v[0] / 60) } else { -1 })); Set-ComboByTag $ui[$p[3]] ([string]$(if ($v[1] -ge 0) { [int][math]::Round($v[1] / 60) } else { -1 }))
    }
    $v = Get-PwrValue 'SUB_ENERGYSAVER' 'ESBATTTHRESHOLD'; Set-ComboByTag $ui.CuSaver ([string]$v[1])
    $ui.CuHibernate.IsChecked = [bool]((Get-ItemProperty 'HKLM:\SYSTEM\CurrentControlSet\Control\Power' -Name HibernateEnabled -ErrorAction SilentlyContinue).HibernateEnabled)
    $ui.CuUsbSuspend.IsChecked = (Get-PwrValue '2a737441-1930-4402-8d77-b2bebba308a3' '48e6b7a6-50f5-4782-a5d4-53bb8f07e226')[0] -eq 1
    $ui.CuAdaptBright.IsChecked = (Get-PwrValue 'SUB_VIDEO' 'ADAPTBRIGHT')[1] -eq 1
    $ui.CuWakeTimers.IsChecked = (Get-PwrValue 'SUB_SLEEP' 'RTCWAKE')[0] -ge 1
    # Akku
    try {
        $des = @(Get-CimInstance -Namespace root\wmi -ClassName BatteryStaticData -ErrorAction Stop)[0].DesignedCapacity
        $full = @(Get-CimInstance -Namespace root\wmi -ClassName BatteryFullChargedCapacity -ErrorAction Stop)[0].FullChargedCapacity
        $cyc = @(Get-CimInstance -Namespace root\wmi -ClassName BatteryCycleCount -ErrorAction SilentlyContinue)[0].CycleCount
        $pct = [math]::Round($full * 100 / $des)
        $ui.CuBatHealth.Text = '{0} % der ursprünglichen Kapazität ({1:N0} von {2:N0} mWh) - {3}' -f $pct, $full, $des, $(if ($pct -ge 80) { 'gut' } elseif ($pct -ge 60) { 'gebraucht' } else { 'verschlissen, Austausch empfohlen' })
        $ui.CuBatCycles.Text = if ($cyc) { [string]$cyc } else { 'nicht gemeldet' }
        $b = Get-CimInstance Win32_Battery | Select-Object -First 1
        $ui.CuBatNow.Text = '{0} % - {1}' -f $b.EstimatedChargeRemaining, $(switch ([int]$b.BatteryStatus) { 1 { 'entlädt' } 2 { 'am Netzteil' } 3 { 'voll' } 6 { 'lädt' } 7 { 'lädt (hoch)' } 8 { 'lädt (niedrig)' } default { 'am Netzteil' } })
    } catch { $ui.CuBatHealth.Text = 'Kein Akku (Desktop-PC) oder keine Akkudaten verfügbar'; $ui.CuBatCycles.Text = '-'; $ui.CuBatNow.Text = '-' }
    # Bildschirm
    try { $ui.CuBright.Value = @(Get-CimInstance -Namespace root\wmi -ClassName WmiMonitorBrightness -ErrorAction Stop)[0].CurrentBrightness; $ui.CuBright.IsEnabled = $true } catch { $ui.CuBright.IsEnabled = $false; $ui.CuBrightVal.Text = 'nicht regelbar' }
    # Touchpad
    $tp = Get-ItemProperty $TouchKey -ErrorAction SilentlyContinue
    $ui.CuTapClick.IsChecked = $tp.TapsEnabled -ne 0; $ui.CuTwoFinger.IsChecked = $tp.TwoFingerTapEnabled -ne 0; $ui.CuNatural.IsChecked = ($null -ne $tp.ScrollDirection -and $tp.ScrollDirection -ne 0); $ui.CuTouchWithMouse.IsChecked = $tp.LeaveOnWithMouse -ne 0
    Set-ComboByTag $ui.CuTouchSens ([string]$(if ($null -ne $tp.AAPThreshold) { $tp.AAPThreshold } else { 2 }))
    # Maus
    $m = Get-ItemProperty 'HKCU:\Control Panel\Mouse' -ErrorAction SilentlyContinue
    $ui.CuMouseSpeed.Value = [int]$m.MouseSensitivity; $ui.CuMouseAccel.IsChecked = [string]$m.MouseSpeed -ne '0'; $ui.CuSwapBtn.IsChecked = [string]$m.SwapMouseButtons -eq '1'
    Set-ComboByTag $ui.CuWheel ([string](Get-ItemProperty 'HKCU:\Control Panel\Desktop' -ErrorAction SilentlyContinue).WheelScrollLines)
    # Tastatur
    $k = Get-ItemProperty 'HKCU:\Control Panel\Keyboard' -ErrorAction SilentlyContinue
    $ui.CuKeyDelay.Value = [int]$k.KeyboardDelay; $ui.CuKeyRate.Value = [int]$k.KeyboardSpeed
    $ui.CuStickyOff.IsChecked = [string](Get-ItemProperty 'HKCU:\Control Panel\Accessibility\StickyKeys' -ErrorAction SilentlyContinue).Flags -eq '506'
    $ui.CuLangHotkeyOff.IsChecked = [string](Get-ItemProperty 'HKCU:\Keyboard Layout\Toggle' -ErrorAction SilentlyContinue).Hotkey -eq '3'
    $ui.CuNumLockOn.IsChecked = [string](Get-ItemProperty 'Registry::HKEY_USERS\.DEFAULT\Control Panel\Keyboard' -ErrorAction SilentlyContinue).InitialKeyboardIndicators -match '^2'
    # Aussehen
    $pz = Get-ItemProperty 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Themes\Personalize' -ErrorAction SilentlyContinue
    Set-ComboByTag $ui.CuThemeApps ([string]$(if ($null -ne $pz.AppsUseLightTheme) { $pz.AppsUseLightTheme } else { 1 })); Set-ComboByTag $ui.CuThemeSys ([string]$(if ($null -ne $pz.SystemUsesLightTheme) { $pz.SystemUsesLightTheme } else { 1 }))
    $ui.CuTransp.IsChecked = $pz.EnableTransparency -ne 0
    $ui.CuAccentTitle.IsChecked = (Get-ItemProperty 'HKCU:\Software\Microsoft\Windows\DWM' -ErrorAction SilentlyContinue).ColorPrevalence -eq 1
    $ui.CuAccentAuto.IsChecked = (Get-ItemProperty 'HKCU:\Control Panel\Desktop' -ErrorAction SilentlyContinue).AutoColorization -eq '1'
    $ui.CuStartSound.IsChecked = (Get-ItemProperty 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Authentication\LogonUI\BootAnimation' -ErrorAction SilentlyContinue).DisableStartupSound -eq 0
    $ui.CuLockTips.IsChecked = (Get-ItemProperty 'HKCU:\Software\Microsoft\Windows\CurrentVersion\ContentDeliveryManager' -ErrorAction SilentlyContinue).RotatingLockScreenOverlayEnabled -ne 0
    # Name
    $ui.CuPcName.Text = $env:COMPUTERNAME; $ui.CuPcDesc.Text = [string](Get-CimInstance Win32_OperatingSystem).Description
}
function Save-KbdSettings {
    $lvl = [int](Get-ComboTag $ui.CuKbdLevel)
    $msgs = @()
    if ($ui.CuKbdLevel.IsEnabled) { $r = Set-KbdLevelNow $lvl; $msgs += $(if ($r -eq 0) { 'Beleuchtung gesetzt.' } else { 'Beleuchtung konnte nicht gesetzt werden (Code {0}).' -f $r }) }
    if ($ui.CuKbdKeep.IsChecked -and $ui.CuKbdKeep.IsEnabled) { Register-KbdTask $lvl ([bool]$ui.CuKbdMinute.IsChecked); $msgs += 'Automatik eingerichtet - bleibt auch nach Neustart und Energiesparen so.' }
    elseif (Get-ScheduledTask -TaskName $KbdTaskName -ErrorAction SilentlyContinue) { Unregister-ScheduledTask -TaskName $KbdTaskName -Confirm:$false; $msgs += 'Automatik entfernt.' }
    $ui.StatusText.Text = 'Tastatur: ' + ($msgs -join ' ')
    Load-Custom
}
function Save-PowerSettings {
    $plan = Get-ComboTag $ui.CuPlan; if ($plan) { $null = & powercfg.exe /setactive $plan 2>&1 }
    Set-PwrValue 'SUB_BUTTONS' 'LIDACTION' (Get-ComboInt $ui.CuLidAc) (Get-ComboInt $ui.CuLidDc)
    Set-PwrValue 'SUB_BUTTONS' 'PBUTTONACTION' (Get-ComboInt $ui.CuBtnAc) (Get-ComboInt $ui.CuBtnDc)
    foreach ($p in @(@('SUB_VIDEO', 'VIDEOIDLE', 'CuMonAc', 'CuMonDc'), @('SUB_SLEEP', 'STANDBYIDLE', 'CuSlpAc', 'CuSlpDc'), @('SUB_SLEEP', 'HIBERNATEIDLE', 'CuHibAc', 'CuHibDc'))) {
        Set-PwrValue $p[0] $p[1] (Get-ComboInt $ui[$p[2]] 60) (Get-ComboInt $ui[$p[3]] 60)
    }
    Set-PwrValue 'SUB_ENERGYSAVER' 'ESBATTTHRESHOLD' -1 (Get-ComboInt $ui.CuSaver)
    $u = if ($ui.CuUsbSuspend.IsChecked) { 1 } else { 0 }; Set-PwrValue '2a737441-1930-4402-8d77-b2bebba308a3' '48e6b7a6-50f5-4782-a5d4-53bb8f07e226' $u $u
    $a = if ($ui.CuAdaptBright.IsChecked) { 1 } else { 0 }; Set-PwrValue 'SUB_VIDEO' 'ADAPTBRIGHT' $a $a
    $w = if ($ui.CuWakeTimers.IsChecked) { 1 } else { 0 }; Set-PwrValue 'SUB_SLEEP' 'RTCWAKE' $w $w
    $null = & powercfg.exe /h $(if ($ui.CuHibernate.IsChecked) { 'on' } else { 'off' }) 2>&1
    $null = & powercfg.exe /setactive SCHEME_CURRENT 2>&1
    $ui.StatusText.Text = 'Energie-Einstellungen übernommen.'
}
function Save-MouseSettings {
    $on = -1   # 0xFFFFFFFF = an
    New-Item $TouchKey -Force -ErrorAction SilentlyContinue | Out-Null
    Set-ItemProperty $TouchKey -Name TapsEnabled -Value $(if ($ui.CuTapClick.IsChecked) { $on } else { 0 }) -Type DWord
    Set-ItemProperty $TouchKey -Name TwoFingerTapEnabled -Value $(if ($ui.CuTwoFinger.IsChecked) { $on } else { 0 }) -Type DWord
    Set-ItemProperty $TouchKey -Name ScrollDirection -Value $(if ($ui.CuNatural.IsChecked) { $on } else { 0 }) -Type DWord
    Set-ItemProperty $TouchKey -Name LeaveOnWithMouse -Value $(if ($ui.CuTouchWithMouse.IsChecked) { $on } else { 0 }) -Type DWord
    Set-ItemProperty $TouchKey -Name AAPThreshold -Value ([int](Get-ComboTag $ui.CuTouchSens)) -Type DWord
    $sp = [int]$ui.CuMouseSpeed.Value; $acc = [bool]$ui.CuMouseAccel.IsChecked
    Set-ItemProperty 'HKCU:\Control Panel\Mouse' -Name MouseSensitivity -Value ([string]$sp)
    Set-ItemProperty 'HKCU:\Control Panel\Mouse' -Name MouseSpeed -Value $(if ($acc) { '1' } else { '0' })
    Set-ItemProperty 'HKCU:\Control Panel\Mouse' -Name MouseThreshold1 -Value $(if ($acc) { '6' } else { '0' })
    Set-ItemProperty 'HKCU:\Control Panel\Mouse' -Name MouseThreshold2 -Value $(if ($acc) { '10' } else { '0' })
    Set-ItemProperty 'HKCU:\Control Panel\Mouse' -Name SwapMouseButtons -Value $(if ($ui.CuSwapBtn.IsChecked) { '1' } else { '0' })
    $wl = [int](Get-ComboTag $ui.CuWheel); Set-ItemProperty 'HKCU:\Control Panel\Desktop' -Name WheelScrollLines -Value ([string]$wl)
    [void][PCPflege.Spi]::SystemParametersInfo(0x71, 0, [IntPtr]$sp, 3)
    [void][PCPflege.Spi]::SystemParametersInfo(0x04, 0, [int[]]$(if ($acc) { @(6, 10, 1) } else { @(0, 0, 0) }), 3)
    [void][PCPflege.Spi]::SystemParametersInfo(0x69, [uint32]$(if ($wl -lt 0) { [uint32]::MaxValue } else { $wl }), [IntPtr]::Zero, 3)
    [void][PCPflege.Spi]::SwapMouseButton([bool]$ui.CuSwapBtn.IsChecked)
    $ui.StatusText.Text = 'Maus übernommen (sofort), Touchpad nach Ab- und Anmelden.'
}
function Save-KeySettings {
    $d = [int]$ui.CuKeyDelay.Value; $r = [int]$ui.CuKeyRate.Value
    Set-ItemProperty 'HKCU:\Control Panel\Keyboard' -Name KeyboardDelay -Value ([string]$d); Set-ItemProperty 'HKCU:\Control Panel\Keyboard' -Name KeyboardSpeed -Value ([string]$r)
    [void][PCPflege.Spi]::SystemParametersInfo(0x17, [uint32]$d, [IntPtr]::Zero, 3); [void][PCPflege.Spi]::SystemParametersInfo(0x0B, [uint32]$r, [IntPtr]::Zero, 3)
    $off = [bool]$ui.CuStickyOff.IsChecked
    Set-ItemProperty 'HKCU:\Control Panel\Accessibility\StickyKeys' -Name Flags -Value $(if ($off) { '506' } else { '510' })
    Set-ItemProperty 'HKCU:\Control Panel\Accessibility\Keyboard Response' -Name Flags -Value $(if ($off) { '122' } else { '126' })
    Set-ItemProperty 'HKCU:\Control Panel\Accessibility\ToggleKeys' -Name Flags -Value $(if ($off) { '58' } else { '62' })
    $tg = 'HKCU:\Keyboard Layout\Toggle'; New-Item $tg -Force -ErrorAction SilentlyContinue | Out-Null
    if ($ui.CuLangHotkeyOff.IsChecked) { foreach ($n in 'Hotkey', 'Language Hotkey', 'Layout Hotkey') { Set-ItemProperty $tg -Name $n -Value '3' } } else { Set-ItemProperty $tg -Name 'Hotkey' -Value '1'; Set-ItemProperty $tg -Name 'Language Hotkey' -Value '1'; Set-ItemProperty $tg -Name 'Layout Hotkey' -Value '2' }
    $nl = if ($ui.CuNumLockOn.IsChecked) { '2' } else { '0' }
    Set-ItemProperty 'Registry::HKEY_USERS\.DEFAULT\Control Panel\Keyboard' -Name InitialKeyboardIndicators -Value $nl -ErrorAction SilentlyContinue
    Set-ItemProperty 'HKCU:\Control Panel\Keyboard' -Name InitialKeyboardIndicators -Value $nl -ErrorAction SilentlyContinue
    $ui.StatusText.Text = 'Tastatur-Einstellungen übernommen.'
}
function Save-LookSettings {
    $pzk = 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Themes\Personalize'
    Set-ItemProperty $pzk -Name AppsUseLightTheme -Value ([int](Get-ComboTag $ui.CuThemeApps)) -Type DWord
    Set-ItemProperty $pzk -Name SystemUsesLightTheme -Value ([int](Get-ComboTag $ui.CuThemeSys)) -Type DWord
    Set-ItemProperty $pzk -Name EnableTransparency -Value $(if ($ui.CuTransp.IsChecked) { 1 } else { 0 }) -Type DWord
    Set-ItemProperty 'HKCU:\Software\Microsoft\Windows\DWM' -Name ColorPrevalence -Value $(if ($ui.CuAccentTitle.IsChecked) { 1 } else { 0 }) -Type DWord
    Set-ItemProperty 'HKCU:\Control Panel\Desktop' -Name AutoColorization -Value $(if ($ui.CuAccentAuto.IsChecked) { '1' } else { '0' })
    $ba = 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Authentication\LogonUI\BootAnimation'; New-Item $ba -Force -ErrorAction SilentlyContinue | Out-Null
    Set-ItemProperty $ba -Name DisableStartupSound -Value $(if ($ui.CuStartSound.IsChecked) { 0 } else { 1 }) -Type DWord
    $cdm = 'HKCU:\Software\Microsoft\Windows\CurrentVersion\ContentDeliveryManager'
    foreach ($n in 'RotatingLockScreenOverlayEnabled', 'SubscribedContent-338387Enabled') { Set-ItemProperty $cdm -Name $n -Value $(if ($ui.CuLockTips.IsChecked) { 1 } else { 0 }) -Type DWord -ErrorAction SilentlyContinue }
    # Windows über die Änderung informieren (Taskleiste/Explorer übernehmen den Farbmodus sofort)
    Add-Type -Name Bc -Namespace PCPflege -MemberDefinition '[DllImport("user32.dll", CharSet=CharSet.Unicode)] public static extern IntPtr SendMessageTimeout(IntPtr h, uint m, UIntPtr w, string l, uint f, uint t, out UIntPtr r);' -ErrorAction SilentlyContinue
    $res = [UIntPtr]::Zero; [void][PCPflege.Bc]::SendMessageTimeout([IntPtr]0xffff, 0x1A, [UIntPtr]::Zero, 'ImmersiveColorSet', 2, 3000, [ref]$res)
    $ui.StatusText.Text = 'Aussehen übernommen. PC-Tools selbst wechselt beim nächsten Start das Design.'
}
function Update-CuBios {
    $ui.CuBiosInfo.Text = 'BIOS-Einstellungen werden gelesen ...'; $ui.CuBiosList.Children.Clear(); $ui.BtnBiosApply.IsEnabled = $false
    Invoke-Bg -Script { Get-OemBiosSettings } -Functions @('Get-OemBiosSettings') -Done {
        param($r, $err)
        if ($err) { $ui.CuBiosInfo.Text = $err.Message; return }
        $script:CuBios = @($r | ForEach-Object { $_ } | Where-Object { $_ -and $_.Name })
        Show-CuBios
    }
}
function Show-CuBios {
    $ui.CuBiosList.Children.Clear(); $ui.CuKbdBios.Children.Clear()
    $all = @($script:CuBios); $show = if ($ui.CuBiosAll.IsChecked) { $all } else { @($all | Where-Object { $_.Name -match $CuBiosDaily -or $_.Label -match $CuBiosDaily }) }
    $ui.CuBiosInfo.Text = '{0} BIOS-Einstellungen ({1}), davon {2} angezeigt. Nur geänderte werden übernommen.' -f $all.Count, $(if ($all.Count) { $all[0].Vendor } else { '-' }), $show.Count
    foreach ($s in ($show | Sort-Object Label)) {
        foreach ($target in @($ui.CuBiosList) + $(if ($s.Name -match '(?i)backlit|backlight|kbd.*(light|illum|timeout)|keyboard.*(light|illum)') { @($ui.CuKbdBios) } else { @() })) {
            $g = New-Object Windows.Controls.Grid; $g.Margin = '0,2'
            foreach ($w in 360, -1) { $c = New-Object Windows.Controls.ColumnDefinition; if ($w -gt 0) { $c.Width = $w }; [void]$g.ColumnDefinitions.Add($c) }
            $t = New-Object Windows.Controls.TextBlock; $t.Text = $s.Label; $t.TextWrapping = 'Wrap'; $t.VerticalAlignment = 'Center'; $t.Foreground = New-UiBrush '#1F2A44'
            $cb = New-Object Windows.Controls.ComboBox; $cb.Width = 260; $cb.HorizontalAlignment = 'Left'; $cb.Tag = $s
            foreach ($o in @($s.Options)) { [void]$cb.Items.Add([string]$o) }
            if (-not $cb.Items.Contains($s.Current)) { [void]$cb.Items.Insert(0, $s.Current) }
            $cb.SelectedItem = $s.Current
            $cb.Add_SelectionChanged({ param($sn, $ev) $ev.Handled = $true; $ui.BtnBiosApply.IsEnabled = $true; foreach ($o in @(@($ui.CuBiosList.Children) + @($ui.CuKbdBios.Children) | Where-Object { $_ -is [Windows.Controls.Grid] })) { $c2 = $o.Children[1]; if ($c2 -ne $sn -and $c2.Tag -eq $sn.Tag -and $c2.SelectedItem -ne $sn.SelectedItem) { $c2.SelectedItem = $sn.SelectedItem } } })
            [Windows.Controls.Grid]::SetColumn($cb, 1)
            [void]$g.Children.Add($t); [void]$g.Children.Add($cb)
            [void]$target.Children.Add($g)
        }
    }
    if ($ui.CuKbdBios.Children.Count) { $h = New-Object Windows.Controls.TextBlock; $h.Text = 'Tastaturbeleuchtung im BIOS (dauerhaft, wirkt nach Neustart - unten bei "Geänderte Einstellungen übernehmen" speichern):'; $h.FontWeight = 'SemiBold'; $h.TextWrapping = 'Wrap'; $h.Margin = '0,4,0,4'; $ui.CuKbdBios.Children.Insert(0, $h) }
}
function Save-CuBios {
    $chg = @(); foreach ($o in $ui.CuBiosList.Children) { $cb = $o.Children[1]; if ([string]$cb.SelectedItem -ne [string]$cb.Tag.Current) { $chg += [pscustomobject]@{ Vendor = $cb.Tag.Vendor; Name = $cb.Tag.Name; Value = [string]$cb.SelectedItem } } }
    if (-not $chg.Count) { $ui.StatusText.Text = 'Keine BIOS-Einstellung geändert.'; return }
    if (-not (Confirm-Ui ("Diese BIOS-Einstellungen ändern?`n`n{0}`n`nWirkt nach dem nächsten Neustart." -f (($chg | ForEach-Object { '  {0} = {1}' -f $_.Name, $_.Value }) -join "`n")) 'Warning')) { return }
    $res = Set-OemBiosSettings $chg $ui.CuBiosPwd.Password
    $bad = @($res | Where-Object { -not $_.Ok })
    if ($bad.Count) { Show-UiError ("Nicht übernommen:`n" + (($bad | ForEach-Object { '  {0}: {1}' -f $_.Name, $_.Msg }) -join "`n") + "`n`nIst ein BIOS-Kennwort gesetzt? Dann oben eintragen.") }
    else { $ui.StatusText.Text = '{0} BIOS-Einstellung(en) gespeichert - wirken nach dem Neustart.' -f $chg.Count }
    Update-CuBios
}

# ---------------------------------------------------------------- Sicherheit (Oberfläche)
function Update-Security {
    $ui.SecScoreText.Text = 'Sicherheit wird geprüft ...'; $ui.BtnSecCheck.IsEnabled = $false
    Invoke-Bg -Script {
        $o = @{}; $rows = [System.Collections.Generic.List[object]]::new(); $pts = 0; $max = 0
        function R([string]$Area, [bool]$Ok, [string]$State, [string]$Detail, [string]$Fix, [int]$W, [string]$Lvl = '') {
            $script:max += $W; if ($Ok) { $script:pts += $W }
            $rows.Add([pscustomobject]@{ Area = $Area; State = $State; Detail = $Detail; Fix = $(if ($Ok) { '' } else { $Fix }); Level = $(if ($Lvl) { $Lvl } elseif ($Ok) { 'Good' } else { 'Warn' }); W = $W; Ok = $Ok })
        }
        $script:pts = 0; $script:max = 0
        # Virenschutz
        $avs = @(Get-CimInstance -Namespace root/SecurityCenter2 -ClassName AntiVirusProduct -ErrorAction SilentlyContinue | ForEach-Object {
            $st = [int]$_.productState; [pscustomobject]@{ Name = [string]$_.displayName; On = ((($st -shr 12) -band 0xF) -in 1, 3); Current = ((($st -shr 4) -band 0xF) -eq 0) } })
        if (-not $avs.Count) { try { $m0 = Get-MpComputerStatus -ErrorAction Stop; if ($m0.AntivirusEnabled) { $avs = @([pscustomobject]@{ Name = 'Microsoft Defender Antivirus'; On = [bool]$m0.RealTimeProtectionEnabled; Current = ($m0.AntivirusSignatureAge -le 3) }) } } catch { } }
        $o.Avs = $avs
        $act = @($avs | Where-Object On)
        R 'Virenschutz' ([bool]$act.Count) $(if ($act.Count) { 'aktiv' } else { 'KEINER AKTIV' }) (($avs | ForEach-Object { '{0} ({1}{2})' -f $_.Name, $(if ($_.On) { 'an' } else { 'aus' }), $(if ($_.Current) { ', aktuell' } else { ', veraltet' }) }) -join '; ') 'Virenschutz einschalten (Defender unten) oder installieren.' 20 $(if (-not $act.Count) { 'Error' } else { '' })
        $mp = $null; $pref = $null; try { $mp = Get-MpComputerStatus -ErrorAction Stop; $pref = Get-MpPreference -ErrorAction Stop } catch { }
        $o.Mp = $mp; $o.Pref = $pref
        if ($mp -and $mp.AMRunningMode -notmatch 'Passive|EDR|Not running') {
            R 'Defender-Echtzeitschutz' ([bool]$mp.RealTimeProtectionEnabled) $(if ($mp.RealTimeProtectionEnabled) { 'an' } else { 'AUS' }) ('Modus: {0}' -f $mp.AMRunningMode) 'Echtzeitschutz unten einschalten.' 10 $(if (-not $mp.RealTimeProtectionEnabled) { 'Error' } else { '' })
            R 'Virendefinitionen' ($mp.AntivirusSignatureAge -le 3) ('{0} Tag(e) alt' -f $mp.AntivirusSignatureAge) ('Version {0}' -f $mp.AntivirusSignatureVersion) 'Signaturen aktualisieren.' 5
            R 'Manipulationsschutz' ([bool]$mp.IsTamperProtected) $(if ($mp.IsTamperProtected) { 'an' } else { 'aus' }) 'Verhindert, dass Schadsoftware den Schutz abschaltet.' 'In der Windows-Sicherheit > Viren- & Bedrohungsschutz einschalten.' 3
            R 'Schutz vor unerwünschten Apps' ($pref.PUAProtection -eq 1) $(if ($pref.PUAProtection -eq 1) { 'an' } else { 'aus' }) 'Blockiert Adware, Toolbars, Krypto-Miner.' 'Unten einschalten.' 3
            R 'Ransomware-Schutz' ($pref.EnableControlledFolderAccess -eq 1) $(if ($pref.EnableControlledFolderAccess -eq 1) { 'an' } else { 'aus' }) 'Überwachter Ordnerzugriff auf Dokumente, Bilder usw.' 'Optional unten einschalten (kann Programme blockieren).' 2 'Info'
        } else { $rows.Add([pscustomobject]@{ Area = 'Microsoft Defender'; State = 'passiv'; Detail = 'Ein anderer Virenschutz ist zuständig.'; Fix = ''; Level = 'Off' }) }
        # Firewall
        $fw = @(Get-NetFirewallProfile -ErrorAction SilentlyContinue); $o.Fw = $fw
        $off = @($fw | Where-Object { -not $_.Enabled -or [string]$_.Enabled -eq 'False' })
        R 'Firewall' (-not $off.Count -and $fw.Count) $(if ($off.Count) { 'teilweise AUS' } else { 'an' }) (($fw | ForEach-Object { '{0}: {1}' -f $_.Name, $(if ([string]$_.Enabled -eq 'True') { 'an' } else { 'aus' }) }) -join ', ') 'Firewall für alle Netzwerke einschalten.' 15 $(if ($off.Count) { 'Error' } else { '' })
        # BitLocker
        $bl = @(); try { $bl = @(Get-BitLockerVolume -ErrorAction Stop) } catch { }
        $o.Bl = @($bl | ForEach-Object { [pscustomobject]@{ Drive = $_.MountPoint; State = $(switch ([string]$_.VolumeStatus) { 'FullyEncrypted' { if ([string]$_.ProtectionStatus -eq 'On') { 'verschlüsselt, geschützt' } else { 'verschlüsselt, AUSGESETZT' } } 'FullyDecrypted' { 'nicht verschlüsselt' } 'EncryptionInProgress' { 'wird verschlüsselt' } 'DecryptionInProgress' { 'wird entschlüsselt' } default { [string]$_.VolumeStatus } }); Pct = ('{0} %' -f $_.EncryptionPercentage); Method = [string]$_.EncryptionMethod; Protectors = (@($_.KeyProtector | ForEach-Object { switch ([string]$_.KeyProtectorType) { 'Tpm' { 'TPM' } 'RecoveryPassword' { 'Wiederherstellungsschlüssel' } 'TpmPin' { 'TPM+PIN' } 'ExternalKey' { 'USB-Schlüssel' } 'Password' { 'Kennwort' } default { [string]$_ } } }) -join ', '); On = ([string]$_.ProtectionStatus -eq 'On'); VolumeType = [string]$_.VolumeType } })
        $os = $bl | Where-Object { [string]$_.VolumeType -eq 'OperatingSystem' } | Select-Object -First 1
        if ($bl.Count) { R 'BitLocker (Laufwerk C:)' ($os -and [string]$os.ProtectionStatus -eq 'On') $(if ($os -and [string]$os.ProtectionStatus -eq 'On') { 'verschlüsselt' } else { 'nicht geschützt' }) 'Schützt die Daten bei Diebstahl.' 'Bei Laptops unbedingt verschlüsseln (unten).' 10 }
        else { $dev = (Get-ItemProperty 'HKLM:\SYSTEM\CurrentControlSet\Control\BitLocker' -ErrorAction SilentlyContinue); $rows.Add([pscustomobject]@{ Area = 'BitLocker'; State = 'nicht verfügbar'; Detail = 'Windows Home hat nur die Geräteverschlüsselung (Einstellungen > Datenschutz und Sicherheit).'; Fix = 'Geräteverschlüsselung einschalten oder auf Windows Pro wechseln.'; Level = 'Info' }) }
        # Secure Boot, TPM
        $sb = $false; try { $sb = Confirm-SecureBootUEFI -ErrorAction Stop } catch { }
        R 'Secure Boot' $sb $(if ($sb) { 'an' } else { 'aus' }) 'Verhindert Schadsoftware im Startvorgang.' 'Im UEFI/BIOS einschalten (Seite Neustart und BIOS).' 6
        $tpm = $null; try { $tpm = Get-Tpm -ErrorAction Stop } catch { }
        $tv = try { [string](Get-CimInstance -Namespace root/cimv2/security/microsofttpm -ClassName Win32_Tpm -ErrorAction Stop).SpecVersion -replace ',.*$', '' } catch { '' }
        R 'TPM-Sicherheitschip' ($tpm -and $tpm.TpmReady) $(if ($tpm -and $tpm.TpmReady) { 'bereit' } elseif ($tpm -and $tpm.TpmPresent) { 'vorhanden, nicht bereit' } else { 'fehlt/aus' }) ('Version {0}' -f $tv) 'Im BIOS aktivieren (Intel PTT / AMD fTPM).' 4
        # UAC, SmartScreen, Kernisolierung, LSA
        $sys = Get-ItemProperty 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\System' -ErrorAction SilentlyContinue
        $o.Uac = @{ Lua = [int]$sys.EnableLUA; Cp = [int]$sys.ConsentPromptBehaviorAdmin; Sd = [int]$sys.PromptOnSecureDesktop }
        R 'Benutzerkontensteuerung' ($sys.EnableLUA -eq 1 -and $sys.ConsentPromptBehaviorAdmin -ne 0) $(if ($sys.EnableLUA -ne 1) { 'AUS' } elseif ($sys.ConsentPromptBehaviorAdmin -eq 0) { 'nie benachrichtigen' } elseif ($sys.ConsentPromptBehaviorAdmin -eq 2) { 'immer benachrichtigen' } else { 'Standard' }) 'Fragt vor Systemänderungen nach.' 'Mindestens auf Standard stellen.' 8
        $ssPol = (Get-ItemProperty 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\System' -ErrorAction SilentlyContinue).EnableSmartScreen
        $ss = [string](Get-ItemProperty 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Explorer' -ErrorAction SilentlyContinue).SmartScreenEnabled
        $ssOn = if ($null -ne $ssPol) { $ssPol -eq 1 } else { $ss -ne 'Off' }
        $o.SmartScreen = $ssOn
        R 'SmartScreen' $ssOn $(if ($ssOn) { 'an' } else { 'aus' }) 'Warnt vor unbekannten Programmen aus dem Internet.' 'Einschalten.' 5
        $hv = (Get-ItemProperty 'HKLM:\SYSTEM\CurrentControlSet\Control\DeviceGuard\Scenarios\HypervisorEnforcedCodeIntegrity' -ErrorAction SilentlyContinue).Enabled
        $hvRun = $false; try { $hvRun = @((Get-CimInstance -Namespace root\Microsoft\Windows\DeviceGuard -ClassName Win32_DeviceGuard -ErrorAction Stop).SecurityServicesRunning) -contains 2 } catch { }
        $o.Hvci = ($hv -eq 1)
        R 'Speicherintegrität' ($hv -eq 1) $(if ($hvRun) { 'aktiv' } elseif ($hv -eq 1) { 'an (nach Neustart aktiv)' } else { 'aus' }) 'Kernisolierung: schützt den Windows-Kern vor Schadcode.' 'Einschalten (Neustart).' 5
        $lsa = (Get-ItemProperty 'HKLM:\SYSTEM\CurrentControlSet\Control\Lsa' -ErrorAction SilentlyContinue).RunAsPPL
        $o.Lsa = ($lsa -in 1, 2)
        R 'LSA-Schutz' ($lsa -in 1, 2) $(if ($lsa -in 1, 2) { 'an' } else { 'aus' }) 'Schützt gespeicherte Anmeldedaten vor Auslesen.' 'Einschalten (Neustart).' 4
        # SMBv1, PowerShell 2
        $smb1 = $false; try { $smb1 = (Get-WindowsOptionalFeature -Online -FeatureName SMB1Protocol -ErrorAction Stop).State -eq 'Enabled' } catch { }
        $o.Smb1 = $smb1
        R 'SMBv1' (-not $smb1) $(if ($smb1) { 'INSTALLIERT' } else { 'entfernt' }) 'Uraltes Freigabeprotokoll (WannaCry).' 'Abschalten - nur sehr alte NAS brauchen es.' 4
        $ps2 = $false; try { $ps2 = (Get-WindowsOptionalFeature -Online -FeatureName MicrosoftWindowsPowerShellV2Root -ErrorAction Stop).State -eq 'Enabled' } catch { }
        $o.Ps2 = $ps2
        R 'PowerShell 2.0' (-not $ps2) $(if ($ps2) { 'vorhanden' } else { 'entfernt' }) 'Wird von Angreifern genutzt, um Schutzfunktionen zu umgehen.' 'Entfernen.' 2
        # Konten, Fernzugriff
        $guest = Get-LocalUser -ErrorAction SilentlyContinue | Where-Object { [string]$_.SID -like '*-501' } | Select-Object -First 1
        $o.Guest = [bool]($guest -and $guest.Enabled)
        R 'Gastkonto' (-not $o.Guest) $(if ($o.Guest) { 'AKTIV' } else { 'deaktiviert' }) '' 'Deaktivieren.' 2
        $rdp = (Get-ItemProperty 'HKLM:\SYSTEM\CurrentControlSet\Control\Terminal Server' -ErrorAction SilentlyContinue).fDenyTSConnections -eq 0
        $nla = (Get-ItemProperty 'HKLM:\SYSTEM\CurrentControlSet\Control\Terminal Server\WinStations\RDP-Tcp' -ErrorAction SilentlyContinue).UserAuthentication -eq 1
        $o.Rdp = $rdp
        R 'Remotedesktop' (-not $rdp -or $nla) $(if ($rdp) { 'erlaubt' + $(if ($nla) { ' (mit NLA)' } else { ' OHNE NLA' }) } else { 'aus' }) 'Fernzugriff auf diesen PC.' 'Nur einschalten, wenn gebraucht - dann mit Netzwerkauthentifizierung.' 2
        $o.RemoteAssist = (Get-ItemProperty 'HKLM:\SYSTEM\CurrentControlSet\Control\Remote Assistance' -ErrorAction SilentlyContinue).fAllowToGetHelp -eq 1
        $ar = (Get-ItemProperty 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\Explorer' -ErrorAction SilentlyContinue).NoDriveTypeAutoRun
        $o.AutorunOff = ($ar -eq 255)
        R 'Autostart von Datenträgern' ($ar -eq 255) $(if ($ar -eq 255) { 'aus' } else { 'an' }) 'USB-Sticks starten keine Programme selbst.' 'Abschalten.' 2
        $o.ExtShow = (Get-ItemProperty 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced' -ErrorAction SilentlyContinue).HideFileExt -eq 0
        R 'Dateiendungen sichtbar' $o.ExtShow $(if ($o.ExtShow) { 'ja' } else { 'nein' }) 'Rechnung.pdf.exe fällt sofort auf.' 'Einschalten.' 2
        # Updates
        $last = $null; try { $last = (Get-HotFix -ErrorAction Stop | Where-Object InstalledOn | Sort-Object InstalledOn -Descending | Select-Object -First 1).InstalledOn } catch { }
        $okU = $last -and ((Get-Date) - $last).TotalDays -le 45
        R 'Windows-Updates' ([bool]$okU) $(if ($last) { 'zuletzt {0:dd.MM.yyyy}' -f $last } else { 'unbekannt' }) 'Sicherheitslücken werden nur durch Updates geschlossen.' 'Seite Updates ausführen.' 8
        # Bedrohungen
        $thr = @(); try { $names = @{}; foreach ($t in @(Get-MpThreat -ErrorAction Stop)) { $names[[string]$t.ThreatID] = $t }
            $thr = @(Get-MpThreatDetection -ErrorAction Stop | Sort-Object InitialDetectionTime -Descending | Select-Object -First 50 | ForEach-Object { $n = $names[[string]$_.ThreatID]
                [pscustomobject]@{ Time = $_.InitialDetectionTime.ToString('dd.MM.yyyy HH:mm'); Name = $(if ($n) { $n.ThreatName } else { [string]$_.ThreatID }); Severity = $(if ($n) { @{ 1 = 'niedrig'; 2 = 'mittel'; 4 = 'hoch'; 5 = 'schwer' }[[int]$n.SeverityID] } else { '' }); Action = $(if ($_.ActionSuccess) { 'entfernt/blockiert' } else { 'offen!' }); Path = (@($_.Resources) -join ', ') } }) } catch { }
        $o.Threats = $thr
        if (@($thr | Where-Object { $_.Action -eq 'offen!' }).Count) { $rows.Add([pscustomobject]@{ Area = 'Gefundene Bedrohungen'; State = 'OFFEN'; Detail = 'Nicht alle Funde wurden entfernt.'; Fix = 'Vollprüfung oder Offline-Prüfung starten.'; Level = 'Error' }) }
        $o.Rows = $rows; $wMax = 0.0; $wPts = 0.0; foreach ($rw in $rows) { if ($null -ne $rw.W) { $wMax += [double]$rw.W; if ($rw.Ok) { $wPts += [double]$rw.W } } }; $o.Score = [int][math]::Round($wPts * 100.0 / [math]::Max(1.0, $wMax))
        [pscustomobject]$o
    } -Done {
        param($r, $err)
        $ui.BtnSecCheck.IsEnabled = $true
        if ($err) { $ui.SecScoreText.Text = 'Prüfung fehlgeschlagen: ' + $err.Message; return }
        $x = @($r | Where-Object { $_ })[0]; $script:SecState = $x
        $ord = @{ Error = 0; Warn = 1; Info = 2; Off = 3; Good = 4 }
        Set-GridItems $ui.SecGrid @($x.Rows | Sort-Object @{ e = { $ord[$_.Level] } }, Area)
        $ui.SecScore.Text = [string]$x.Score
        try { Set-Gauge 'GaSec' $x.Score ([string]$x.Score) $(if ($x.Score -ge 85) { 'sehr gut' } elseif ($x.Score -ge 65) { 'ordentlich' } else { 'Handlungsbedarf' }) $(if ($x.Score -ge 85) { '#FFFFFF' } elseif ($x.Score -ge 65) { '#FDE68A' } else { '#FCA5A5' }) } catch { }
        $col = if ($x.Score -ge 85) { '#16A34A' } elseif ($x.Score -ge 65) { '#D97706' } else { '#DC2626' }
        $ui.SecScoreRing.BorderBrush = New-UiBrush $col
        $bad = @($x.Rows | Where-Object { $_.Level -in 'Error', 'Warn' }).Count
        $ui.SecScoreText.Text = if ($x.Score -ge 85) { 'Sehr gut geschützt' + $(if ($bad) { (' - noch {0} Verbesserung(en) möglich' -f $bad) } else { '' }) } elseif ($x.Score -ge 65) { 'Ordentlich - {0} Punkt(e) sollten verbessert werden' -f $bad } else { 'Handlungsbedarf - {0} Punkt(e) unsicher' -f $bad }
        if (-not $script:ScBusy -and $script:ScLast) { try { Update-ScScoreUi } catch { } }
        $ui.SecAvInfo.Text = 'Virenschutz: ' + $(if (@($x.Avs).Count) { (@($x.Avs) | ForEach-Object { '{0} ({1})' -f $_.Name, $(if ($_.On) { 'aktiv' } else { 'aus' }) }) -join ', ' } else { 'keiner gemeldet' })
        # Defender
        $p = $x.Pref; $m = $x.Mp
        $defOn = [bool]($m -and $m.AMRunningMode -notmatch 'Passive|Not running')
        foreach ($n in 'DefRealtime', 'DefCloud', 'DefSamples', 'DefPua', 'DefNetwork', 'DefCfa', 'DefBehavior', 'DefScript', 'DefRemovable', 'BtnDefApply', 'BtnDefQuick', 'BtnDefFull') { $ui[$n].IsEnabled = $defOn }
        if ($p) {
            $ui.DefRealtime.IsChecked = -not $p.DisableRealtimeMonitoring; $ui.DefCloud.IsChecked = $p.MAPSReporting -ne 0; $ui.DefSamples.IsChecked = $p.SubmitSamplesConsent -in 1, 3
            $ui.DefPua.IsChecked = $p.PUAProtection -eq 1; $ui.DefNetwork.IsChecked = $p.EnableNetworkProtection -eq 1; $ui.DefCfa.IsChecked = $p.EnableControlledFolderAccess -eq 1
            $ui.DefBehavior.IsChecked = -not $p.DisableBehaviorMonitoring; $ui.DefScript.IsChecked = -not $p.DisableScriptScanning; $ui.DefRemovable.IsChecked = -not $p.DisableRemovableDriveScanning
        }
        $ui.SecDefInfo.Text = if ($m) { 'Modus: {0}  ·  Engine {1}  ·  Definitionen {2} ({3} Tag(e))  ·  Manipulationsschutz: {4}  ·  Letzte Schnellprüfung: {5}  ·  Letzte Vollprüfung: {6}' -f $m.AMRunningMode, $m.AMEngineVersion, $m.AntivirusSignatureVersion, $m.AntivirusSignatureAge, $(if ($m.IsTamperProtected) { 'an' } else { 'aus' }), $(if ($m.QuickScanEndTime) { $m.QuickScanEndTime.ToString('dd.MM.yyyy HH:mm') } else { 'nie' }), $(if ($m.FullScanEndTime) { $m.FullScanEndTime.ToString('dd.MM.yyyy HH:mm') } else { 'nie' }) } else { 'Microsoft Defender ist nicht verfügbar.' }
        Set-GridItems $ui.DefThreats @($x.Threats)
        # Firewall
        foreach ($f in @($x.Fw)) { $on = [string]$f.Enabled -eq 'True'; switch ([string]$f.Name) { 'Domain' { $ui.FwDomain.IsChecked = $on } 'Private' { $ui.FwPrivate.IsChecked = $on } 'Public' { $ui.FwPublic.IsChecked = $on; $ui.FwBlockPublic.IsChecked = [string]$f.AllowInboundRules -eq 'False' } } }
        $ui.FwNotify.IsChecked = [bool](@($x.Fw | Where-Object { [string]$_.NotifyOnListen -eq 'True' }).Count)
        $prof = try { (@(Get-NetConnectionProfile -ErrorAction Stop) | ForEach-Object { '{0} = {1}' -f $_.Name, $(switch ([string]$_.NetworkCategory) { 'Private' { 'Privat' } 'Public' { 'Öffentlich' } 'DomainAuthenticated' { 'Domäne' } default { [string]$_.NetworkCategory } }) }) -join ', ' } catch { '' }
        $ui.FwInfo.Text = 'Aktuelle Netzwerke: ' + $(if ($prof) { $prof } else { 'keins' })
        # BitLocker
        Set-GridItems $ui.BlGrid @($x.Bl)
        foreach ($n in 'BtnBlOn', 'BtnBlKey', 'BtnBlSuspend', 'BtnBlResume', 'BtnBlOff') { $ui[$n].IsEnabled = [bool]@($x.Bl).Count }
        if (-not @($x.Bl).Count) { $ui.BlInfo.Text = 'BitLocker ist in dieser Windows-Edition nicht verfügbar (Home). Die einfachere Geräteverschlüsselung findet sich unter Einstellungen > Datenschutz und Sicherheit > Geräteverschlüsselung.' }
        # Schutzfunktionen
        $u = $x.Uac
        Set-ComboByTag $ui.SecUac $(if ($u.Cp -eq 2) { '2' } elseif ($u.Cp -eq 0 -or $u.Lua -eq 0) { '0' } elseif ($u.Sd -eq 0) { '5d' } else { '5' })
        $ui.SecSmartScreen.IsChecked = $x.SmartScreen; $ui.SecHvci.IsChecked = $x.Hvci; $ui.SecLsa.IsChecked = $x.Lsa; $ui.SecSmb1Off.IsChecked = -not $x.Smb1
        $ui.SecAutorunOff.IsChecked = $x.AutorunOff; $ui.SecGuestOff.IsChecked = -not $x.Guest; $ui.SecRdp.IsChecked = $x.Rdp; $ui.SecPs2Off.IsChecked = -not $x.Ps2
        $ui.SecRemoteAssist.IsChecked = $x.RemoteAssist; $ui.SecExtShow.IsChecked = $x.ExtShow
        Build-AvTiles
    }
}
function Build-AvTiles {
    $ui.AvFree.Children.Clear(); $ui.AvPaid.Children.Clear()
    $inst = @($script:SecState.Avs | ForEach-Object { $_.Name })
    foreach ($p in $AvProducts) {
        $b = New-Object Windows.Controls.Border; $b.Width = 330; $b.Margin = '0,0,12,12'; $b.Padding = '14,12'; $b.CornerRadius = '10'; $b.BorderThickness = '1'
        $b.BorderBrush = New-UiBrush '#E2E7F0'; $b.Background = New-UiBrush '#F8FAFD'
        $sp = New-Object Windows.Controls.StackPanel
        $h = New-Object Windows.Controls.StackPanel; $h.Orientation = 'Horizontal'
        $t = New-Object Windows.Controls.TextBlock; $t.Text = $p.Name; $t.FontWeight = 'SemiBold'; $t.FontSize = 14; $t.Foreground = New-UiBrush '#1F2A44'
        [void]$h.Children.Add($t)
        $word = ($p.Name -split ' ')[0]
        if ($inst | Where-Object { $_ -match [regex]::Escape($word) }) { [void]$h.Children.Add((New-AutoBadge 'installiert' '#DCFCE7' '#15803D')) }
        [void]$sp.Children.Add($h)
        $d = New-Object Windows.Controls.TextBlock; $d.Text = $p.Desc; $d.TextWrapping = 'Wrap'; $d.FontSize = 12; $d.Margin = '0,4,0,8'; $d.Foreground = New-UiBrush '#475569'; $d.MinHeight = 48
        [void]$sp.Children.Add($d)
        $wp = New-Object Windows.Controls.WrapPanel
        if ($p.Key -eq 'Defender') { $x1 = New-BrowserButton $p.Key 'Windows-Sicherheit öffnen' $false; $x1.Add_Click({ Start-Process 'windowsdefender:' }); [void]$wp.Children.Add($x1) }
        else {
            if ($p.Free -and ($p.Ninite -or @($p.Winget).Count -or $p.Pages)) { $x1 = New-BrowserButton $p.Key 'Installieren' $true; $x1.Add_Click({ param($s, $e) $pp = $AvProducts | Where-Object { $_.Key -eq [string]$s.Tag } | Select-Object -First 1; if (Confirm-Ui ('{0} installieren? Einen anderen Virenschutz mit Echtzeitschutz vorher deinstallieren.' -f $pp.Name)) { Start-Run -Parts @('AvInstall') -Job @{ Product = $pp.Key } } }); [void]$wp.Children.Add($x1) }
            $x2 = New-BrowserButton $p.Key $(if ($p.Free) { 'Website' } else { 'Testen / Kaufen' }) (-not $p.Free); $x2.Add_Click({ param($s, $e) Start-Process (($AvProducts | Where-Object { $_.Key -eq [string]$s.Tag } | Select-Object -First 1).Url) }); [void]$wp.Children.Add($x2)
        }
        [void]$sp.Children.Add($wp); $b.Child = $sp
        if ($p.Free) { [void]$ui.AvFree.Children.Add($b) } else { [void]$ui.AvPaid.Children.Add($b) }
    }
}
function Save-Defender {
    $err = @()
    $set = [ordered]@{ DisableRealtimeMonitoring = -not $ui.DefRealtime.IsChecked; MAPSReporting = $(if ($ui.DefCloud.IsChecked) { 2 } else { 0 }); SubmitSamplesConsent = $(if ($ui.DefSamples.IsChecked) { 1 } else { 2 })
                       PUAProtection = $(if ($ui.DefPua.IsChecked) { 1 } else { 0 }); EnableNetworkProtection = $(if ($ui.DefNetwork.IsChecked) { 1 } else { 0 }); EnableControlledFolderAccess = $(if ($ui.DefCfa.IsChecked) { 1 } else { 0 })
                       DisableBehaviorMonitoring = -not $ui.DefBehavior.IsChecked; DisableScriptScanning = -not $ui.DefScript.IsChecked; DisableRemovableDriveScanning = -not $ui.DefRemovable.IsChecked }
    foreach ($k in $set.Keys) { try { $a = @{ $k = $set[$k]; ErrorAction = 'Stop' }; Set-MpPreference @a } catch { $err += ('{0}: {1}' -f $k, $_.Exception.Message) } }
    if ($err) { Show-UiError ("Nicht alles ließ sich ändern (Manipulationsschutz oder Gruppenrichtlinie?):`n" + ($err -join "`n")) } else { $ui.StatusText.Text = 'Defender-Einstellungen übernommen.' }
    Update-Security
}
function Save-Firewall {
    try {
        Set-NetFirewallProfile -Profile Domain -Enabled $(if ($ui.FwDomain.IsChecked) { 'True' } else { 'False' }) -ErrorAction Stop
        Set-NetFirewallProfile -Profile Private -Enabled $(if ($ui.FwPrivate.IsChecked) { 'True' } else { 'False' }) -ErrorAction Stop
        Set-NetFirewallProfile -Profile Public -Enabled $(if ($ui.FwPublic.IsChecked) { 'True' } else { 'False' }) -AllowInboundRules $(if ($ui.FwBlockPublic.IsChecked) { 'False' } else { 'True' }) -ErrorAction Stop
        Set-NetFirewallProfile -Profile Domain, Private, Public -NotifyOnListen $(if ($ui.FwNotify.IsChecked) { 'True' } else { 'False' }) -ErrorAction Stop
        $ui.StatusText.Text = 'Firewall übernommen.'
    } catch { Show-UiError $_.Exception.Message }
    Update-Security
}
function Save-Protection {
    $v = @{ Uac = Get-ComboTag $ui.SecUac; Ss = [bool]$ui.SecSmartScreen.IsChecked; Hvci = [bool]$ui.SecHvci.IsChecked; Lsa = [bool]$ui.SecLsa.IsChecked; Smb1Off = [bool]$ui.SecSmb1Off.IsChecked
            AutorunOff = [bool]$ui.SecAutorunOff.IsChecked; GuestOff = [bool]$ui.SecGuestOff.IsChecked; Rdp = [bool]$ui.SecRdp.IsChecked; Ps2Off = [bool]$ui.SecPs2Off.IsChecked; Ra = [bool]$ui.SecRemoteAssist.IsChecked; Ext = [bool]$ui.SecExtShow.IsChecked; Old = $script:SecState }
    if ($v.Uac -eq '0' -and -not (Confirm-Ui 'Benutzerkontensteuerung auf "Nie benachrichtigen" stellen? Dann können Programme ohne Rückfrage Systemänderungen vornehmen.' 'Warning')) { return }
    $ui.StatusText.Text = 'Schutzfunktionen werden gesetzt (Windows-Features können eine Minute dauern) ...'; $ui.BtnSecApply.IsEnabled = $false
    Invoke-Bg -Script {
        param($v)
        $msg = @()
        $k = 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\System'
        switch ($v.Uac) { '2' { $cp = 2; $sd = 1 } '5' { $cp = 5; $sd = 1 } '5d' { $cp = 5; $sd = 0 } '0' { $cp = 0; $sd = 0 } default { $cp = $null } }
        if ($null -ne $cp) { Set-ItemProperty $k -Name EnableLUA -Value 1 -Type DWord; Set-ItemProperty $k -Name ConsentPromptBehaviorAdmin -Value $cp -Type DWord; Set-ItemProperty $k -Name PromptOnSecureDesktop -Value $sd -Type DWord }
        Set-ItemProperty 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Explorer' -Name SmartScreenEnabled -Value $(if ($v.Ss) { 'Warn' } else { 'Off' })
        if ($null -ne (Get-ItemProperty 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\System' -Name EnableSmartScreen -ErrorAction SilentlyContinue)) { Set-ItemProperty 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\System' -Name EnableSmartScreen -Value $(if ($v.Ss) { 1 } else { 0 }) -Type DWord }
        $hk = 'HKLM:\SYSTEM\CurrentControlSet\Control\DeviceGuard\Scenarios\HypervisorEnforcedCodeIntegrity'; New-Item $hk -Force -ErrorAction SilentlyContinue | Out-Null
        if ($v.Hvci -ne $v.Old.Hvci) { Set-ItemProperty $hk -Name Enabled -Value $(if ($v.Hvci) { 1 } else { 0 }) -Type DWord; $msg += 'Speicherintegrität ändert sich nach dem Neustart' }
        if ($v.Lsa -ne $v.Old.Lsa) { Set-ItemProperty 'HKLM:\SYSTEM\CurrentControlSet\Control\Lsa' -Name RunAsPPL -Value $(if ($v.Lsa) { 1 } else { 0 }) -Type DWord; $msg += 'LSA-Schutz nach Neustart' }
        if ($v.Smb1Off -ne (-not $v.Old.Smb1)) {
            if ($v.Smb1Off) { try { Set-SmbServerConfiguration -EnableSMB1Protocol $false -Force -ErrorAction SilentlyContinue; $null = Disable-WindowsOptionalFeature -Online -FeatureName SMB1Protocol -NoRestart -ErrorAction Stop; $msg += 'SMBv1 entfernt' } catch { $msg += 'SMBv1: ' + $_.Exception.Message } }
            else { try { $null = Enable-WindowsOptionalFeature -Online -FeatureName SMB1Protocol -All -NoRestart -ErrorAction Stop; $msg += 'SMBv1 installiert (nach Neustart)' } catch { $msg += 'SMBv1: ' + $_.Exception.Message } }
        }
        if ($v.Ps2Off -ne (-not $v.Old.Ps2)) {
            try { if ($v.Ps2Off) { $null = Disable-WindowsOptionalFeature -Online -FeatureName MicrosoftWindowsPowerShellV2Root -NoRestart -ErrorAction Stop; $msg += 'PowerShell 2.0 entfernt' } else { $null = Enable-WindowsOptionalFeature -Online -FeatureName MicrosoftWindowsPowerShellV2Root -All -NoRestart -ErrorAction Stop } } catch { $msg += 'PowerShell 2.0: ' + $_.Exception.Message }
        }
        $ek = 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\Explorer'; New-Item $ek -Force -ErrorAction SilentlyContinue | Out-Null
        if ($v.AutorunOff) { Set-ItemProperty $ek -Name NoDriveTypeAutoRun -Value 255 -Type DWord } else { Remove-ItemProperty $ek -Name NoDriveTypeAutoRun -ErrorAction SilentlyContinue }
        $g = Get-LocalUser -ErrorAction SilentlyContinue | Where-Object { [string]$_.SID -like '*-501' } | Select-Object -First 1
        if ($g) { if ($v.GuestOff) { Disable-LocalUser -SID $g.SID -ErrorAction SilentlyContinue } else { Enable-LocalUser -SID $g.SID -ErrorAction SilentlyContinue } }
        Set-ItemProperty 'HKLM:\SYSTEM\CurrentControlSet\Control\Terminal Server' -Name fDenyTSConnections -Value $(if ($v.Rdp) { 0 } else { 1 }) -Type DWord
        if ($v.Rdp) { Set-ItemProperty 'HKLM:\SYSTEM\CurrentControlSet\Control\Terminal Server\WinStations\RDP-Tcp' -Name UserAuthentication -Value 1 -Type DWord; Enable-NetFirewallRule -Group '@FirewallAPI.dll,-28752' -ErrorAction SilentlyContinue } else { Disable-NetFirewallRule -Group '@FirewallAPI.dll,-28752' -ErrorAction SilentlyContinue }
        Set-ItemProperty 'HKLM:\SYSTEM\CurrentControlSet\Control\Remote Assistance' -Name fAllowToGetHelp -Value $(if ($v.Ra) { 1 } else { 0 }) -Type DWord
        Set-ItemProperty 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced' -Name HideFileExt -Value $(if ($v.Ext) { 0 } else { 1 }) -Type DWord
        $msg
    } -Arguments @($v) -Done {
        param($r, $err)
        $ui.BtnSecApply.IsEnabled = $true
        if ($err) { Show-UiError $err.Message } else { $ui.StatusText.Text = 'Schutzfunktionen übernommen. ' + (@($r | Where-Object { $_ }) -join ' · ') }
        Update-Security
    }
}
function Get-BlSelected { $r = $ui.BlGrid.SelectedItem; if (-not $r) { $r = @($ui.BlGrid.ItemsSource | Where-Object { $_.VolumeType -eq 'OperatingSystem' })[0] }; return $r }
function Save-BlKey($Drive) {
    Add-Type -AssemblyName System.Windows.Forms
    $d = New-Object System.Windows.Forms.SaveFileDialog; $d.Filter = 'Textdatei (*.txt)|*.txt'; $d.FileName = ('BitLocker-Schluessel_{0}_{1}.txt' -f $env:COMPUTERNAME, ($Drive -replace '[:\\]', ''))
    $d.Title = 'Wiederherstellungsschlüssel speichern - am besten auf einem USB-Stick, NICHT auf diesem Laufwerk'
    if ($d.ShowDialog() -ne 'OK') { return $false }
    if ($d.FileName.Substring(0, 2) -ieq $Drive.Substring(0, 2)) { Show-UiError 'Bitte nicht auf dem verschlüsselten Laufwerk selbst speichern - sonst ist der Schlüssel im Notfall nicht erreichbar.'; return $false }
    $v = Get-BitLockerVolume -MountPoint $Drive
    $keys = @($v.KeyProtector | Where-Object { [string]$_.KeyProtectorType -eq 'RecoveryPassword' })
    if (-not $keys.Count) { Show-UiError 'Kein Wiederherstellungsschlüssel vorhanden.'; return $false }
    $txt = @('BitLocker-Wiederherstellungsschlüssel', ('PC: {0}   Laufwerk: {1}   erstellt: {2:dd.MM.yyyy HH:mm}' -f $env:COMPUTERNAME, $Drive, (Get-Date)), '')
    foreach ($k in $keys) { $txt += ('Kennung: {0}' -f $k.KeyProtectorId); $txt += ('Schlüssel: {0}' -f $k.RecoveryPassword); $txt += '' }
    $txt += 'Sicher aufbewahren (Ausdruck, USB-Stick im Schrank). Wer diesen Schlüssel hat, kann die Daten lesen.'
    Set-Content -LiteralPath $d.FileName -Value $txt -Encoding UTF8
    $ui.StatusText.Text = 'Wiederherstellungsschlüssel gespeichert: ' + $d.FileName
    return $true
}
function Enable-BlDrive {
    $r = Get-BlSelected; if (-not $r) { return }
    if ($r.State -notmatch 'nicht verschlüsselt') { Show-UiError ('{0} ist bereits verschlüsselt oder in Bearbeitung.' -f $r.Drive); return }
    $isOs = $r.VolumeType -eq 'OperatingSystem'
    if (-not (Confirm-Ui ("Laufwerk {0} mit BitLocker (XTS-AES 256) verschlüsseln?`n`n- Zuerst wird ein Wiederherstellungsschlüssel erzeugt, den du gleich speicherst (USB-Stick oder Ausdruck).`n- Die Verschlüsselung läuft im Hintergrund, der PC bleibt nutzbar.`n{1}" -f $r.Drive, $(if ($isOs) { '- Entsperrt wird automatisch über den TPM-Chip.' } else { '- Wird automatisch entsperrt, wenn C: verschlüsselt ist.' })) 'Warning')) { return }
    try {
        $null = Add-BitLockerKeyProtector -MountPoint $r.Drive -RecoveryPasswordProtector -ErrorAction Stop
        if (-not (Save-BlKey $r.Drive)) { if (-not (Confirm-Ui 'Der Schlüssel wurde nicht gespeichert. Trotzdem verschlüsseln? (Später über "Wiederherstellungsschlüssel sichern" nachholen!)' 'Warning')) { $v = Get-BitLockerVolume -MountPoint $r.Drive; foreach ($k in @($v.KeyProtector | Where-Object { [string]$_.KeyProtectorType -eq 'RecoveryPassword' })) { $null = Remove-BitLockerKeyProtector -MountPoint $r.Drive -KeyProtectorId $k.KeyProtectorId }; return } }
        if ($isOs) { $null = Enable-BitLocker -MountPoint $r.Drive -EncryptionMethod XtsAes256 -UsedSpaceOnly -TpmProtector -SkipHardwareTest -ErrorAction Stop }
        else { $null = Enable-BitLocker -MountPoint $r.Drive -EncryptionMethod XtsAes256 -UsedSpaceOnly -RecoveryPasswordProtector -ErrorAction Stop; try { Enable-BitLockerAutoUnlock -MountPoint $r.Drive -ErrorAction Stop } catch { } }
        $ui.StatusText.Text = 'BitLocker verschlüsselt {0} im Hintergrund.' -f $r.Drive
    } catch { Show-UiError ('BitLocker: ' + $_.Exception.Message) }
    Update-Security
}
function Save-BlKeyToTools([string]$Drive) {
    $folder = Get-BlKeyFolder
    $v = Get-BitLockerVolume -MountPoint $Drive -ErrorAction SilentlyContinue
    $keys = @($v.KeyProtector | Where-Object { [string]$_.KeyProtectorType -eq 'RecoveryPassword' })
    if (-not $keys.Count) { return '' }
    $txt = @('BitLocker-Wiederherstellungsschlüssel', ('PC: {0}   Laufwerk: {1}   erstellt: {2:dd.MM.yyyy HH:mm}' -f $env:COMPUTERNAME, $Drive, (Get-Date)), '')
    foreach ($k in $keys) { $txt += ('Kennung: {0}' -f $k.KeyProtectorId); $txt += ('Schlüssel: {0}' -f $k.RecoveryPassword); $txt += '' }
    $txt += 'Diesen Schlüssel UNBEDINGT zusätzlich außerhalb des PCs sichern (USB-Stick, Ausdruck, Microsoft-Konto).'
    $f = Join-Path $folder ('BitLocker-Schluessel_{0}_{1}.txt' -f $env:COMPUTERNAME, ($Drive -replace '[:\\]', ''))
    try { Set-Content -LiteralPath $f -Value $txt -Encoding UTF8 -ErrorAction Stop } catch { return '' }
    Write-BlKeyInfo $folder
    return $folder
}
function Invoke-BlOneClick {
    $mp = $env:SystemDrive
    $v = $null; try { $v = Get-BitLockerVolume -MountPoint $mp -ErrorAction Stop } catch { Show-UiError ('BitLocker-Status nicht lesbar: ' + $_.Exception.Message); return }
    if ([string]$v.ProtectionStatus -eq 'On') {
        $folder = Save-BlKeyToTools $mp
        [Windows.MessageBox]::Show((T (("Laufwerk {0} ist bereits mit BitLocker verschlüsselt.`n`nEine Kopie des Wiederherstellungsschlüssels liegt jetzt im Ordner:`n{1}`n`nBitte diesen Schlüssel zusätzlich außerhalb des PCs sichern (USB-Stick, Ausdruck)." -f $mp, $folder))), (T ('PC-Tools - BitLocker')), 'OK', 'Information') | Out-Null
        if ($folder) { try { Start-Process explorer.exe $folder } catch { } }
        return
    }
    if ($v.VolumeStatus -notlike '*Decrypted*' -and [string]$v.ProtectionStatus -ne 'Off') { Show-UiError ('{0} wird gerade ver- oder entschlüsselt - bitte warten.' -f $mp); return }
    $tpm = $null; try { $tpm = Get-Tpm -ErrorAction Stop } catch { }
    if (-not $tpm -or -not $tpm.TpmReady) {
        [Windows.MessageBox]::Show((T ("Für die automatische Entsperrung über den TPM-Chip ist kein betriebsbereites TPM vorhanden.`n`nBitte im BIOS/UEFI das TPM (bei manchen Geräten `"Security Chip`" / `"PTT`" / `"fTPM`") einschalten - siehe Seite BIOS-Einstellungen > Sicherheit.")), (T ('PC-Tools - BitLocker')), 'OK', 'Warning') | Out-Null
        return
    }
    if (-not (Confirm-Ui ("Laufwerk {0} jetzt mit BitLocker (XTS-AES 256) verschlüsseln?`n`n- Der Wiederherstellungsschlüssel wird automatisch im PC-Tools-Ordner gespeichert.`n- Entsperrt wird automatisch über den TPM-Chip - du musst beim Start nichts eingeben.`n- Die Verschlüsselung läuft im Hintergrund, der PC bleibt nutzbar." -f $mp) 'Warning')) { return }
    try {
        if (-not @($v.KeyProtector | Where-Object { [string]$_.KeyProtectorType -eq 'RecoveryPassword' }).Count) { $null = Add-BitLockerKeyProtector -MountPoint $mp -RecoveryPasswordProtector -ErrorAction Stop -WarningAction SilentlyContinue }
        $null = Enable-BitLocker -MountPoint $mp -EncryptionMethod XtsAes256 -UsedSpaceOnly -TpmProtector -SkipHardwareTest -ErrorAction Stop -WarningAction SilentlyContinue
    } catch { Show-UiError ('BitLocker: ' + $_.Exception.Message); return }
    $folder = Save-BlKeyToTools $mp
    try { foreach ($k in @((Get-BitLockerVolume -MountPoint $mp).KeyProtector | Where-Object { [string]$_.KeyProtectorType -eq 'RecoveryPassword' })) { Backup-BitLockerKeyProtector -MountPoint $mp -KeyProtectorId $k.KeyProtectorId -ErrorAction Stop | Out-Null } } catch { }
    $ui.StatusText.Text = 'BitLocker verschlüsselt {0} im Hintergrund - Schlüssel gespeichert.' -f $mp
    [Windows.MessageBox]::Show((T (("BitLocker ist eingeschaltet - {0} wird im Hintergrund verschlüsselt (der PC bleibt nutzbar).`n`nDer Wiederherstellungsschlüssel liegt im Ordner:`n{1}`n`nSEHR WICHTIG: Diesen Schlüssel zusätzlich außerhalb des PCs sichern (USB-Stick, Ausdruck oder Microsoft-Konto). Ohne ihn sind die Daten nach einem Hardwaretausch verloren. Die Datei `"WICHTIG - unbedingt sichern.txt`" im Ordner erklärt alles." -f $mp, $folder))), (T ('PC-Tools - BitLocker')), 'OK', 'Information') | Out-Null
    if ($folder) { try { Start-Process explorer.exe $folder } catch { } }
    Update-Security
}

function Update-Ampel {
    $ui.AmpTitle.Text = 'Zustand wird geprüft ...'; $ui.AmpSub.Text = ''
    $args1 = @(, (Get-HealthArgs))
    Invoke-Bg -Script { param($a) Get-HealthItems $a } -Functions @('Get-HealthItems') -Arguments $args1 -Done {
        param($res, $err)
        if ($err) { $ui.AmpTitle.Text = 'Prüfung nicht möglich: ' + $err.Message; return }
        $items = @($res | ForEach-Object { $_ } | Where-Object { $_ -and $_.Text })
        $red = @($items | Where-Object Level -eq 'Red'); $yel = @($items | Where-Object Level -eq 'Yellow')
        $state = if ($red.Count) { 'Red' } elseif ($yel.Count) { 'Yellow' } else { 'Green' }
        $lit = @{ Red = '#EF4444'; Yellow = '#F59E0B'; Green = '#22C55E' }; $dim = @{ Red = '#4A2A2E'; Yellow = '#4A3F24'; Green = '#1F3A2A' }
        foreach ($k in 'Red', 'Yellow', 'Green') {
            $e = $ui['Amp' + $k]; $on = $k -eq $state
            $e.Fill = (New-Object Windows.Media.BrushConverter).ConvertFromString($(if ($on) { $lit[$k] } else { $dim[$k] }))
            if ($on) { $fx = New-Object Windows.Media.Effects.DropShadowEffect; $fx.Color = [Windows.Media.ColorConverter]::ConvertFromString($lit[$k]); $fx.BlurRadius = 24; $fx.ShadowDepth = 0; $fx.Opacity = 0.9; $e.Effect = $fx } else { $e.Effect = $null }
        }
        $ui.AmpTitle.Text = switch ($state) { 'Red' { 'Dringend: {0} Punkt(e) sofort erledigen' -f $red.Count } 'Yellow' { 'Gut - {0} Punkt(e) bald erledigen' -f $yel.Count } default { 'Alles in Ordnung - dem PC geht es gut' } }
        $ui.AmpSub.Text = switch ($state) { 'Red' { 'Rot heißt: Sicherheit oder Daten sind in Gefahr.' } 'Yellow' { 'Gelb heißt: nichts Kritisches, aber bitte zeitnah.' } default { 'Keine Probleme gefunden. Weiter so - der Zeitplan hält alles aktuell.' } }
        $script:AmpItems = $items
        # V14: Status an "Meine PCs" (NAS) und Verlauf im Hintergrund - ein ausgeschaltetes NAS ließ das Fenster sonst hängen
        Invoke-Bg -Script { param($it, $sc) try { Write-FleetStatus $it $sc } catch { }; try { Add-HealthHistory } catch { } } -Arguments @(@($items), $(if ($script:SecState) { [int]$script:SecState.Score } else { -1 })) -Functions @('Write-FleetStatus', 'Add-HealthHistory') -Done { param($r, $e) }
        $ui.AmpList.Children.Clear()
        foreach ($it in ($items | Sort-Object @{ e = { if ($_.Level -eq 'Red') { 0 } else { 1 } } })) {
            $g = New-Object Windows.Controls.Grid; $g.Margin = '0,4'
            foreach ($w in 22, -1, 150) { $c = New-Object Windows.Controls.ColumnDefinition; if ($w -gt 0) { $c.Width = $w }; [void]$g.ColumnDefinitions.Add($c) }
            $dot = New-Object Windows.Shapes.Ellipse; $dot.Width = 11; $dot.Height = 11; $dot.VerticalAlignment = 'Top'; $dot.Margin = '0,5,0,0'
            $dot.Fill = (New-Object Windows.Media.BrushConverter).ConvertFromString($(if ($it.Level -eq 'Red') { '#EF4444' } else { '#F59E0B' }))
            $sp = New-Object Windows.Controls.StackPanel; [Windows.Controls.Grid]::SetColumn($sp, 1)
            $t1 = New-Object Windows.Controls.TextBlock; $t1.Text = $it.Text; $t1.FontWeight = 'SemiBold'; $t1.Foreground = New-UiBrush '#1F2A44'; $t1.TextWrapping = 'Wrap'
            $t2 = New-Object Windows.Controls.TextBlock; $t2.Text = $it.Detail; $t2.FontSize = 12; $t2.Foreground = New-UiBrush '#475569'; $t2.TextWrapping = 'Wrap'
            [void]$sp.Children.Add($t1); [void]$sp.Children.Add($t2)
            $b = New-Object Windows.Controls.Button; $b.Content = $it.Button; $b.Tag = $it.Action; $b.Padding = '12,5'; $b.Margin = '8,0,0,0'; $b.VerticalAlignment = 'Center'; $b.HorizontalAlignment = 'Right'
            if ($it.Level -ne 'Red') { $b.Style = $window.FindResource('Sec') }
            $b.Add_Click({ param($s, $e) Invoke-AmpAction ([string]$s.Tag) })
            [Windows.Controls.Grid]::SetColumn($b, 2)
            [void]$g.Children.Add($dot); [void]$g.Children.Add($sp); [void]$g.Children.Add($b)
            [void]$ui.AmpList.Children.Add($g)
        }
    }
}
function Invoke-AmpAction([string]$A) {
    switch ($A) {
        'Restart'  { Invoke-PowerAction 'Restart' }
        'Clean'    { $ui.Tabs.SelectedItem = $ui.TabClean }
        'Security' { $ui.Tabs.SelectedItem = $ui.TabSecurity }
        'Updates'  { $ui.Tabs.SelectedItem = $ui.TabUpd }
        'RunAll'   { Start-Run -Parts 'Update', 'Clean', 'Optimize' }
        'Backup'   { $ui.Tabs.SelectedItem = $ui.TabBackup }
        'FullBackup' { $ui.Tabs.SelectedItem = $ui.TabFullBackup }
        'Repair'   { $ui.Tabs.SelectedItem = $ui.TabRepair; Start-RepScan }
        'Drivers'  { $ui.Tabs.SelectedItem = $ui.TabDrv }
        'Sched'    { $ui.Tabs.SelectedItem = $ui.TabSched }
        'Custom'   { $ui.Tabs.SelectedItem = $ui.TabCustom }
        'Space'    { $ui.Tabs.SelectedItem = $ui.TabSpace }
        'Health'   { $ui.Tabs.SelectedItem = $ui.TabHealth }
        'Bios'     { $ui.Tabs.SelectedItem = $ui.TabBios }
        'WinRepair' { $ui.Tabs.SelectedItem = $ui.TabWinRepair }
    }
}

# ---------------------------------------------------------------- Meine PCs (Oberfläche)
function Update-Fleet {
    $ui.FleetTiles.Children.Clear()
    $dir = $ui.Fleet_Dir.Text.Trim()
    if (-not $dir) { $ui.FleetInfo.Text = 'Noch kein gemeinsamer Ordner eingestellt (unten).'; return }
    $ui.FleetInfo.Text = 'Wird gelesen ...'
    Invoke-Bg -Script {
        param($d)
        @(Get-ChildItem -LiteralPath $d -Filter *.json -ErrorAction Stop | ForEach-Object { try { Get-Content -LiteralPath $_.FullName -Raw -Encoding UTF8 | ConvertFrom-Json } catch { } })
    } -Arguments @($dir) -Done {
        param($r, $err)
        if ($err) { $ui.FleetInfo.Text = 'Ordner nicht erreichbar: ' + $err.Message; return }
        $pcs = @($r | Where-Object { $_ -and $_.Computer } | Sort-Object @{ e = { switch ($_.State) { 'Red' { 0 } 'Yellow' { 1 } default { 2 } } } }, Computer)
        $script:FleetPcs = $pcs
        try { Set-GridItems $ui.FleetGrid @($pcs | ForEach-Object { $ak = $_.Akte; $ageH = ((Get-Date) - [datetime]$_.Time).TotalHours
                [pscustomobject]@{ Computer = $_.Computer; StateText = $(switch ($_.State) { 'Red' { 'rot' } 'Yellow' { 'gelb' } default { 'grün' } }); Model = $_.Model
                    AkStandort = $(if ($ak) { [string]$ak.Standort } else { '' }); AkBesitzer = $(if ($ak) { [string]$ak.Besitzer } else { '' }); AkInv = $(if ($ak) { [string]$ak.Inventarnummer } else { '' }); AkKaufSort = $(if ($ak) { [string]$ak.Kaufdatum } else { '' })
                    AkKauf = $(if ($ak -and $ak.Kaufdatum) { try { ([datetime]$ak.Kaufdatum).ToString('dd.MM.yyyy') } catch { [string]$ak.Kaufdatum } } else { '' }); AkRep = $(if ($ak) { [string]$ak.LetzteReparatur } else { '' })
                    AgeText = $(if ($ageH -lt 48) { 'vor {0:N0} Std.' -f $ageH } else { ([datetime]$_.Time).ToString('dd.MM.yyyy') }); Level = $(if ($ageH -gt 72) { 'Off' } elseif ($_.State -eq 'Red') { 'Error' } elseif ($_.State -eq 'Yellow') { 'Warn' } else { '' }) } }) } catch { }
        $cnt = @{ Red = @($pcs | Where-Object State -eq 'Red').Count; Yellow = @($pcs | Where-Object State -eq 'Yellow').Count; Green = @($pcs | Where-Object State -eq 'Green').Count }
        $ui.FleetInfo.Text = '{0} PC(s): {1} rot, {2} gelb, {3} grün' -f $pcs.Count, $cnt.Red, $cnt.Yellow, $cnt.Green
        foreach ($p in $pcs) {
            $age = ((Get-Date) - [datetime]$p.Time)
            $stale = $age.TotalDays -gt 3
            $col = if ($stale) { '#9AA5B8' } else { switch ($p.State) { 'Red' { '#EF4444' } 'Yellow' { '#F59E0B' } default { '#22C55E' } } }
            $b = New-Object Windows.Controls.Border; $b.Width = 320; $b.Margin = '0,0,12,12'; $b.CornerRadius = '12'; $b.BorderThickness = '1'; $b.BorderBrush = New-UiBrush '#E2E7F0'; $b.Background = New-UiBrush '#F8FAFD'; $b.Cursor = 'Hand'; $b.Tag = $p
            $g = New-Object Windows.Controls.Grid; $c1 = New-Object Windows.Controls.ColumnDefinition; $c1.Width = '6'; [void]$g.ColumnDefinitions.Add($c1); [void]$g.ColumnDefinitions.Add((New-Object Windows.Controls.ColumnDefinition))
            $bar = New-Object Windows.Controls.Border; $bar.CornerRadius = '12,0,0,12'; $bar.Background = (New-Object Windows.Media.BrushConverter).ConvertFromString($col)
            $sp = New-Object Windows.Controls.StackPanel; $sp.Margin = '14,10,12,10'; [Windows.Controls.Grid]::SetColumn($sp, 1)
            $h = New-Object Windows.Controls.StackPanel; $h.Orientation = 'Horizontal'
            $dot = New-Object Windows.Shapes.Ellipse; $dot.Width = 12; $dot.Height = 12; $dot.Margin = '0,0,8,0'; $dot.VerticalAlignment = 'Center'; $dot.Fill = (New-Object Windows.Media.BrushConverter).ConvertFromString($col)
            $n = New-Object Windows.Controls.TextBlock; $n.Text = $p.Computer; $n.FontSize = 17; $n.FontWeight = 'SemiBold'; $n.Foreground = New-UiBrush '#1F2A44'
            [void]$h.Children.Add($dot); [void]$h.Children.Add($n)
            if ($p.Computer -eq $env:COMPUTERNAME) { [void]$h.Children.Add((New-AutoBadge 'dieser PC' '#E6F0FF' '#2D7FF9')) }
            [void]$sp.Children.Add($h)
            $l1 = New-Object Windows.Controls.TextBlock; $l1.Text = [string]$p.Model; $l1.FontSize = 12; $l1.Foreground = New-UiBrush '#475569'; $l1.TextTrimming = 'CharacterEllipsis'
            $l2 = New-Object Windows.Controls.TextBlock; $l2.FontSize = 12; $l2.Foreground = New-UiBrush '#475569'; $l2.TextWrapping = 'Wrap'; $l2.Margin = '0,4,0,0'
            $l2.Text = 'Sicherheit {0}  ·  C: {1} GB frei  ·  Pflege {2}' -f $(if ([int]$p.SecScore -ge 0) { [int]$p.SecScore } else { '-' }), $p.DiskFreeGB, $(if ($p.LastRun) { ($p.LastRun -split ' ')[0] } else { 'nie' })
            if ($p.Warranty) { try { $l2.Text += '  ·  Garantie bis {0:dd.MM.yyyy}' -f [datetime]$p.Warranty } catch { } }; if ($p.Remote) { $l2.Text += '  ·  Fernaufträge an' }
            if ($p.Akte) { $akx = @(@($(if ($p.Akte.Standort) { 'Standort: ' + $p.Akte.Standort }), $(if ($p.Akte.Besitzer) { 'Nutzer: ' + $p.Akte.Besitzer }), $(if ($p.Akte.Inventarnummer) { 'Inv.-Nr. ' + $p.Akte.Inventarnummer })) | Where-Object { $_ }); if ($akx.Count) { $l2.Text += "`n" + ($akx -join '  ·  ') } }
            $l3 = New-Object Windows.Controls.TextBlock; $l3.FontSize = 12; $l3.Margin = '0,4,0,0'; $l3.TextWrapping = 'Wrap'
            $bad = @($p.Items | Where-Object { $_.Level -in 'Red', 'Yellow' })
            $l3.Text = if ($stale) { 'Keine Meldung seit {0:N0} Tagen' -f $age.TotalDays } elseif ($bad.Count) { (($bad | Select-Object -First 2 | ForEach-Object { $_.Text }) -join ' · ') + $(if ($bad.Count -gt 2) { (' (+{0})' -f ($bad.Count - 2)) } else { '' }) } else { 'Alles in Ordnung' }
            $l3.Foreground = New-UiBrush $(if ($stale) { '#6B7890' } elseif ($p.State -eq 'Red') { '#C81E1E' } elseif ($p.State -eq 'Yellow') { '#B45309' } else { '#15803D' })
            $l4 = New-Object Windows.Controls.TextBlock; $l4.FontSize = 11; $l4.Foreground = New-UiBrush '#6B7890'; $l4.Margin = '0,4,0,0'
            $l4.Text = 'Stand: {0}  ·  PC-Tools {1}' -f $(if ($age.TotalMinutes -lt 60) { 'vor {0:N0} Min.' -f $age.TotalMinutes } elseif ($age.TotalHours -lt 48) { 'vor {0:N0} Std.' -f $age.TotalHours } else { ([datetime]$p.Time).ToString('dd.MM.yyyy HH:mm') }), $p.Version
            foreach ($x in $l1, $l2, $l3, $l4) { [void]$sp.Children.Add($x) }
            [void]$g.Children.Add($bar); [void]$g.Children.Add($sp); $b.Child = $g
            $b.Add_MouseLeftButtonUp({ param($s, $e)
                foreach ($t in $ui.FleetTiles.Children) { $t.BorderBrush = New-UiBrush '#E2E7F0'; $t.BorderThickness = '1' }
                $s.BorderBrush = New-UiBrush '#2D7FF9'; $s.BorderThickness = '2'; $script:FleetSel = $s.Tag; $q = $s.Tag
                $ui.FleetDetail.Text = "{0}  ·  {1}  ·  {2}`nBenutzer: {3}  ·  IP: {4}  ·  läuft seit {5} Tagen`n{6}" -f $q.Computer, $q.Model, $q.Windows, $q.User, $q.IP, $q.Uptime, ((@($q.Items) | ForEach-Object { '{0} {1} - {2}' -f $(if ($_.Level -eq 'Red') { '●' } else { '○' }), $_.Text, $_.Detail }) -join "`n")
                if ($q.Akte) { $ui.FleetDetail.Text += ("`nGeräte-Akte: Kaufdatum {0}  ·  Standort {1}  ·  Besitzer {2}  ·  Inventarnummer {3}  ·  letzte Reparatur {4}" -f $(if ($q.Akte.Kaufdatum) { try { ([datetime]$q.Akte.Kaufdatum).ToString('dd.MM.yyyy') } catch { $q.Akte.Kaufdatum } } else { '-' }), $(if ($q.Akte.Standort) { $q.Akte.Standort } else { '-' }), $(if ($q.Akte.Besitzer) { $q.Akte.Besitzer } else { '-' }), $(if ($q.Akte.Inventarnummer) { $q.Akte.Inventarnummer } else { '-' }), $(if ($q.Akte.LetzteReparatur) { $q.Akte.LetzteReparatur } else { 'keine' })) } })
            [void]$ui.FleetTiles.Children.Add($b)
        }
    }
}
# ---------------------------------------------------------------- Änderungen (Oberfläche)
function Update-ChgLists {
    $ui.ChgFrom.Items.Clear(); $ui.ChgTo.Items.Clear()
    $now = New-Object Windows.Controls.ComboBoxItem; $now.Content = 'Jetzt (aktueller Stand)'; $now.Tag = ''; [void]$ui.ChgTo.Items.Add($now)
    foreach ($f in @(Get-ChildItem (Join-Path $DataDir 'Stände') -Filter *.json -ErrorAction SilentlyContinue | Sort-Object Name -Descending)) {
        $reason = ''; try { $reason = [string]((Get-Content $f.FullName -Raw -Encoding UTF8 | ConvertFrom-Json).Reason) } catch { }
        $txt = '{0}  -  {1}' -f $f.LastWriteTime.ToString('dd.MM.yyyy HH:mm'), $reason
        foreach ($cb in $ui.ChgFrom, $ui.ChgTo) { $ci = New-Object Windows.Controls.ComboBoxItem; $ci.Content = $txt; $ci.Tag = $f.FullName; [void]$cb.Items.Add($ci) }
    }
    if ($ui.ChgFrom.Items.Count) { $ui.ChgFrom.SelectedIndex = 0; $ui.ChgInfo.Text = '{0} festgehaltene Stände. Standard: letzter Stand vor einem Update gegen jetzt.' -f $ui.ChgFrom.Items.Count } else { $ui.ChgInfo.Text = 'Noch kein Stand festgehalten - passiert automatisch vor jedem Update, oder jetzt mit "Stand jetzt festhalten".' }
    $ui.ChgTo.SelectedIndex = 0
}
function Start-ChgCompare {
    $a = Get-ComboTag $ui.ChgFrom; $b = Get-ComboTag $ui.ChgTo
    if (-not $a) { Show-UiError 'Bitte einen früheren Stand wählen.'; return }
    $ui.ChgInfo.Text = 'Vergleiche ... (der aktuelle Stand wird einige Sekunden eingelesen)'; $ui.BtnChgCompare.IsEnabled = $false
    Invoke-Bg -Script {
        param($fa, $fb)
        $A = Get-Content -LiteralPath $fa -Raw -Encoding UTF8 | ConvertFrom-Json
        $B = if ($fb) { Get-Content -LiteralPath $fb -Raw -Encoding UTF8 | ConvertFrom-Json } else { Get-SystemSnapshot }
        [pscustomobject]@{ Diff = (Compare-SystemSnapshot $A $B); BuildA = $A.Build; BuildB = $B.Build }
    } -Arguments @($a, $b) -Functions @('Get-SystemSnapshot', 'Compare-SystemSnapshot') -Done {
        param($r, $err)
        $ui.BtnChgCompare.IsEnabled = $true
        if ($err) { $ui.ChgInfo.Text = 'Vergleich fehlgeschlagen: ' + $err.Message; return }
        $x = @($r | Where-Object { $_ })[0]
        $script:ChgAll = @($x.Diff | ForEach-Object { $_ } | Where-Object { $_ } | Sort-Object Kind, Name)
        $ui.ChgInfo.Text = '{0} Änderungen: {1} Treiber, {2} Programme, {3} Windows-Updates{4}' -f $script:ChgAll.Count, @($script:ChgAll | Where-Object Kind -eq 'Treiber').Count, @($script:ChgAll | Where-Object Kind -eq 'Programm').Count, @($script:ChgAll | Where-Object Kind -eq 'Windows-Update').Count, $(if ($x.BuildA -ne $x.BuildB) { '  ·  Windows-Build {0} -> {1}' -f $x.BuildA, $x.BuildB } else { '' })
        Update-ChgFilter
    }
}
function Update-ChgFilter {
    $f = [math]::Max(0, $ui.ChgFilter.SelectedIndex); $k = @('', 'Treiber', 'Programm', 'Windows-Update')[$f]
    Set-GridItems $ui.ChgGrid @($script:ChgAll | Where-Object { -not $k -or $_.Kind -eq $k })
}
function Invoke-ChgRollback {
    $r = $ui.ChgGrid.SelectedItem; if (-not $r) { Show-UiError 'Bitte eine Änderung auswählen.'; return }
    switch ($r.Kind) {
        'Treiber' {
            if (Confirm-Ui ("Treiber für`n{0}`nzurückdrehen?`n`nEs öffnen sich die Geräte-Eigenschaften - dort auf der Registerkarte Treiber ""Vorheriger Treiber"" wählen. Ist der Knopf grau, den Treiber aus der Treiber-Sicherung installieren (Seite Treiber > Treiber aus Ordner installieren)." -f $r.Name)) {
                Start-Process rundll32.exe -ArgumentList ('devmgr.dll,DeviceProperties_RunDLL /DeviceID "{0}"' -f $r.Key)
            }
        }
        'Programm' {
            $u = Get-ItemProperty ('HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\' + $r.Inf), ('HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\' + $r.Inf), ('HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\' + $r.Inf) -ErrorAction SilentlyContinue | Select-Object -First 1
            if ($r.Change -eq 'entfernt') { Show-UiError ('"{0}" wurde entfernt - zum Zurückholen neu installieren (Seite Installieren).' -f $r.Name); return }
            if ($u -and $u.UninstallString -and (Confirm-Ui ('"{0}" deinstallieren? {1}' -f $r.Name, $(if ($r.Change -eq 'geändert') { 'Danach die alte Version {0} beim Hersteller laden.' -f $r.Before } else { '' })))) {
                $cmd = [string]$u.UninstallString
                if ($cmd -match 'msiexec') { Start-Process msiexec.exe -ArgumentList (($cmd -replace '(?i)^.*msiexec(\.exe)?"?\s*', '') -replace '/I', '/X') } else { Start-Process cmd.exe -ArgumentList ('/c "{0}"' -f $cmd) -WindowStyle Hidden }
            } elseif (-not $u) { Start-Process 'ms-settings:appsfeatures' }
        }
        'Windows-Update' {
            if ($r.Change -ne 'neu') { return }
            $kb = $r.Name -replace '\D', ''
            if (Confirm-Ui ('Update {0} deinstallieren? Danach ist ein Neustart nötig. Kumulative Updates lassen sich oft nur über Fehler beheben > "Letztes kumulatives Update entfernen" zurücknehmen.' -f $r.Name) 'Warning') { Start-Process wusa.exe -ArgumentList ('/uninstall /kb:{0} /norestart' -f $kb) }
        }
    }
}
# ---------------------------------------------------------------- Gerätezustand (Oberfläche)
function New-LineChart([string]$Title, [double[]]$Vals, [string[]]$Labels, [string]$Unit, [string]$Color, [string]$Note = '') {
    $w = 360; $h = 120
    $b = New-Object Windows.Controls.Border; $b.Width = $w + 28; $b.Margin = '0,0,12,12'; $b.Padding = '14,10'; $b.CornerRadius = '10'; $b.BorderThickness = '1'; $b.BorderBrush = New-UiBrush '#E2E7F0'; $b.Background = New-UiBrush '#F8FAFD'
    $sp = New-Object Windows.Controls.StackPanel
    $t = New-Object Windows.Controls.TextBlock; $t.Text = $Title; $t.FontWeight = 'SemiBold'; $t.Foreground = New-UiBrush '#1F2A44'; [void]$sp.Children.Add($t)
    $valid = @(for ($i = 0; $i -lt $Vals.Count; $i++) { if (-not [double]::IsNaN($Vals[$i])) { [pscustomobject]@{ I = $i; V = $Vals[$i] } } })
    $v = New-Object Windows.Controls.TextBlock; $v.FontSize = 22; $v.FontWeight = 'Bold'; $v.Foreground = (New-Object Windows.Media.BrushConverter).ConvertFromString($Color)
    $v.Text = if ($valid.Count) { '{0:N1} {1}' -f $valid[-1].V, $Unit } else { 'keine Daten' }
    [void]$sp.Children.Add($v)
    $cv = New-Object Windows.Controls.Canvas; $cv.Width = $w; $cv.Height = $h; $cv.Margin = '0,6,0,0'; $cv.ClipToBounds = $true
    if ($valid.Count -ge 2) {
        $min = ($valid | Measure-Object V -Minimum).Minimum; $max = ($valid | Measure-Object V -Maximum).Maximum
        if ($max - $min -lt 1) { $max += 1; $min -= 1 }
        $n = [math]::Max(2, $Vals.Count)
        $pts = New-Object Windows.Media.PointCollection
        foreach ($p in $valid) { $pts.Add((New-Object Windows.Point ($w * $p.I / ($n - 1)), ($h - 8 - ($h - 16) * ($p.V - $min) / ($max - $min)))) }
        $fill = New-Object Windows.Shapes.Polygon; $fp = New-Object Windows.Media.PointCollection; $fp.Add((New-Object Windows.Point ($pts[0].X, $h))); foreach ($q in $pts) { $fp.Add($q) }; $fp.Add((New-Object Windows.Point ($pts[$pts.Count - 1].X, $h))); $fill.Points = $fp
        $fill.Fill = (New-Object Windows.Media.BrushConverter).ConvertFromString($Color); $fill.Opacity = 0.12
        $pl = New-Object Windows.Shapes.Polyline; $pl.Points = $pts; $pl.StrokeThickness = 2.5; $pl.Stroke = (New-Object Windows.Media.BrushConverter).ConvertFromString($Color); $pl.StrokeLineJoin = 'Round'
        [void]$cv.Children.Add($fill); [void]$cv.Children.Add($pl)
        foreach ($yv in $min, $max) { $l = New-Object Windows.Controls.TextBlock; $l.Text = '{0:N0}' -f $yv; $l.FontSize = 10; $l.Foreground = New-UiBrush '#6B7890'; [Windows.Controls.Canvas]::SetLeft($l, 2); [Windows.Controls.Canvas]::SetTop($l, $(if ($yv -eq $max) { 0 } else { $h - 16 })); [void]$cv.Children.Add($l) }
    }
    [void]$sp.Children.Add($cv)
    $ft = New-Object Windows.Controls.TextBlock; $ft.FontSize = 11; $ft.Foreground = New-UiBrush '#6B7890'; $ft.TextWrapping = 'Wrap'
    $ft.Text = $(if ($Labels.Count) { '{0} bis {1}' -f $Labels[0], $Labels[-1] } else { '' }) + $(if ($Note) { "`n" + $Note } else { '' })
    [void]$sp.Children.Add($ft)
    $b.Child = $sp
    return $b
}
function Update-HealthPage {
    try { Add-HealthHistory } catch { }
    $ui.HistCharts.Children.Clear()
    $f = Join-Path $DataDir 'Verlauf.csv'
    $rows = @(); if (Test-Path $f) { $rows = @(Import-Csv -LiteralPath $f -Delimiter ';' -Encoding UTF8) }
    $ui.HistInfo.Text = if ($rows.Count -lt 3) { 'Es gibt erst {0} Messpunkt(e). Die Kurven werden mit jedem Tag aussagekräftiger (ein Punkt pro Tag, beim Öffnen von PC-Tools und nach jeder Pflege).' -f $rows.Count } else { '{0} Messpunkte vom {1} bis {2}.' -f $rows.Count, $rows[0].Datum, $rows[-1].Datum }
    $lab = @($rows | ForEach-Object { ([datetime]$_.Datum).ToString('dd.MM.yy') })
    function V($col) { , [double[]]@($rows | ForEach-Object { $x = [string]$_.$col; if ($x -match '^[\d\.,]+$') { [double]($x -replace ',', '.') } else { [double]::NaN } }) }
    # Akku-Prognose: lineare Abnahme pro Monat
    $bv = V 'AkkuProzent'; $note = ''
    $bp = @(for ($i = 0; $i -lt $rows.Count; $i++) { if (-not [double]::IsNaN($bv[$i])) { [pscustomobject]@{ X = ([datetime]$rows[$i].Datum).ToOADate(); Y = $bv[$i] } } })
    if ($bp.Count -ge 5 -and ($bp[-1].X - $bp[0].X) -ge 14) {
        $mx = ($bp | Measure-Object X -Average).Average; $my = ($bp | Measure-Object Y -Average).Average
        $num = 0.0; $den = 0.0; foreach ($p in $bp) { $num += ($p.X - $mx) * ($p.Y - $my); $den += ($p.X - $mx) * ($p.X - $mx) }
        if ($den -gt 0) { $slope = $num / $den * 30; $note = if ($slope -lt -0.05) { 'Verliert ca. {0:N1} % pro Monat{1}' -f (-$slope), $(if ($bp[-1].Y -gt 60) { ' - 60 % in ca. {0:N0} Monaten' -f (($bp[-1].Y - 60) / -$slope) } else { '' }) } else { 'Stabil' } }
    }
    if (@($bv | Where-Object { -not [double]::IsNaN($_) }).Count) { [void]$ui.HistCharts.Children.Add((New-LineChart 'Akku-Kapazität' $bv $lab '%' '#22C55E' $note)) }
    [void]$ui.HistCharts.Children.Add((New-LineChart 'SSD-Verschleiß' (V 'SsdVerschleiss') $lab '%' '#7C3AED' '0 % = neu, 100 % = Lebensdauer erreicht'))
    [void]$ui.HistCharts.Children.Add((New-LineChart 'SSD-Temperatur' (V 'SsdTemperatur') $lab '°C' '#EA580C' 'Über 70 °C dauerhaft ist zu warm'))
    [void]$ui.HistCharts.Children.Add((New-LineChart 'Freier Speicher C:' (V 'FreiGB') $lab 'GB' '#2D7FF9' ''))
    [void]$ui.HistCharts.Children.Add((New-LineChart 'Startzeit' (V 'StartSek') $lab 's' '#0891B2' 'Letzter gemessener Windows-Start'))
    Update-BootPage
}
function Update-BootPage {
    $ui.BootInfo.Text = 'Startzeiten werden gelesen ...'
    Invoke-Bg -Script { Get-BootTimes } -Functions @('Get-BootTimes') -Done {
        param($r, $err)
        if ($err) { $ui.BootInfo.Text = 'Nicht lesbar: ' + $err.Message; return }
        $x = @($r | Where-Object { $_ })[0]
        $boots = @($x.Boots | Where-Object { $_ } | Sort-Object Time)
        if (-not $boots.Count) { $ui.BootInfo.Text = 'Windows hat noch keine Startzeiten aufgezeichnet.' }
        else {
            $avg = ($boots | Measure-Object Total -Average).Average
            $ui.BootInfo.Text = 'Letzter Start: {0:N1} s (davon {1:N1} s bis zum Desktop, {2:N1} s danach)  ·  Durchschnitt der letzten {3}: {4:N1} s  -  {5}' -f $boots[-1].Total, $boots[-1].Main, $boots[-1].Post, $boots.Count, $avg, $(if ($avg -lt 30) { 'sehr schnell' } elseif ($avg -lt 60) { 'gut' } elseif ($avg -lt 120) { 'mittel - Autostart aufräumen hilft' } else { 'langsam - Startbremsen unten ansehen' })
        }
        $cv = $ui.BootChart; $cv.Children.Clear()
        $W = [math]::Max(600, $cv.ActualWidth); $H = 130
        if ($boots.Count) {
            $mx = [math]::Max(10, ($boots | Measure-Object Total -Maximum).Maximum); $bw = [math]::Min(46, ($W - 20) / $boots.Count - 8)
            for ($i = 0; $i -lt $boots.Count; $i++) {
                $bt = $boots[$i]; $hh = ($H - 24) * $bt.Total / $mx
                $rc = New-Object Windows.Shapes.Rectangle; $rc.Width = $bw; $rc.Height = [math]::Max(2, $hh); $rc.RadiusX = 4; $rc.RadiusY = 4
                $rc.Fill = (New-Object Windows.Media.BrushConverter).ConvertFromString($(if ($bt.Total -lt 45) { '#22C55E' } elseif ($bt.Total -lt 90) { '#F59E0B' } else { '#EF4444' }))
                $rc.ToolTip = '{0:dd.MM.yyyy HH:mm}: {1:N1} s' -f $bt.Time, $bt.Total
                [Windows.Controls.Canvas]::SetLeft($rc, 10 + $i * ($bw + 8)); [Windows.Controls.Canvas]::SetTop($rc, $H - 16 - $hh); [void]$cv.Children.Add($rc)
                $l = New-Object Windows.Controls.TextBlock; $l.Text = '{0:N0}' -f $bt.Total; $l.FontSize = 10; $l.Foreground = New-UiBrush '#475569'
                [Windows.Controls.Canvas]::SetLeft($l, 10 + $i * ($bw + 8) + 2); [Windows.Controls.Canvas]::SetTop($l, $H - 30 - $hh); [void]$cv.Children.Add($l)
            }
        }
        Set-GridItems $ui.BootSlow @($x.Slow | Where-Object { $_ } | ForEach-Object { $_ | Add-Member -NotePropertyName AvgText -NotePropertyValue ('{0:N1} s' -f $_.Avg) -Force -PassThru })
    }
}

# ---------------------------------------------------------------- Apps entfernen (Oberfläche)
function Update-Bloat {
    $ui.BloatInfo.Text = 'Installierte Apps werden eingelesen ...'; $ui.BloatList.Children.Clear()
    Invoke-Bg -Script { param($h) $BloatCatalog = $h.C; $BloatWin32 = $h.W; Get-BloatList } -Arguments @(@{ C = $BloatCatalog; W = $BloatWin32 }) -Functions @('Get-BloatList') -Done {
        param($r, $err)
        if ($err) { $ui.BloatInfo.Text = 'Nicht lesbar: ' + $err.Message; return }
        $script:BloatRows = @($r | ForEach-Object { $_ } | Where-Object { $_ -and $_.Id } | Sort-Object @{ e = { if ($_.Level -eq 0) { 9 } else { $_.Level } } }, Cat, Name)
        $ui.BloatList.Children.Clear()
        foreach ($x in $script:BloatRows) {
            $g = New-Object Windows.Controls.Grid; $g.Margin = '0,2'
            foreach ($w in -1, 150, 90) { $cd = New-Object Windows.Controls.ColumnDefinition; if ($w -gt 0) { $cd.Width = $w }; [void]$g.ColumnDefinitions.Add($cd) }
            $cb = New-Object Windows.Controls.CheckBox; $cb.Tag = $x
            $sp = New-Object Windows.Controls.StackPanel; $sp.Orientation = 'Horizontal'
            $t = New-Object Windows.Controls.TextBlock; $t.Text = $x.Name; $t.FontWeight = 'SemiBold'; [void]$sp.Children.Add($t)
            $lvl = switch ($x.Level) { 0 { New-AutoBadge 'nützlich - nur von Hand' '#DCFCE7' '#15803D' } 1 { New-AutoBadge 'Werbung/Spiele' '#FFEDD5' '#C2410C' } 2 { New-AutoBadge 'Microsoft-Extra' '#E6F0FF' '#2D7FF9' } default { New-AutoBadge 'radikal' '#EDE9FE' '#7C3AED' } }
            [void]$sp.Children.Add($lvl); $cb.Content = $sp
            $c2 = New-Object Windows.Controls.TextBlock; $c2.Text = $x.Cat; $c2.Foreground = New-UiBrush '#475569'; $c2.FontSize = 12; $c2.VerticalAlignment = 'Center'; [Windows.Controls.Grid]::SetColumn($c2, 1)
            $c3 = New-Object Windows.Controls.TextBlock; $c3.Text = $x.SizeText; $c3.Foreground = New-UiBrush '#475569'; $c3.FontSize = 12; $c3.HorizontalAlignment = 'Right'; $c3.VerticalAlignment = 'Center'; [Windows.Controls.Grid]::SetColumn($c3, 2)
            [void]$g.Children.Add($cb); [void]$g.Children.Add($c2); [void]$g.Children.Add($c3)
            [void]$ui.BloatList.Children.Add($g)
        }
        $ui.BloatInfo.Text = if ($script:BloatRows.Count) { '{0} entfernbare Apps gefunden ({1:N0} MB). Schnellwahl oben oder einzeln anhaken.' -f $script:BloatRows.Count, (($script:BloatRows | Measure-Object Size -Sum).Sum / 1MB) } else { 'Keine bekannten überflüssigen Apps gefunden - sauber!' }
        Update-BloatDone
    }
}
function Update-BloatDone { $f = Join-Path $DataDir 'Apps-entfernt.json'; $d = @(); try { $d = @(Get-Content $f -Raw -Encoding UTF8 | ConvertFrom-Json | ForEach-Object { $_ }) } catch { }; Set-GridItems $ui.BloatDone $d }
function Set-BloatPreset([int]$Max) { foreach ($g in $ui.BloatList.Children) { $cb = $g.Children[0]; $cb.IsChecked = ($cb.Tag.Level -ge 1 -and $cb.Tag.Level -le $Max) } }
# ---------------------------------------------------------------- Datenschutz (Oberfläche)
function Get-PrivState($d) {
    $v = (Get-ItemProperty -LiteralPath $d.Path -Name $d.Name -ErrorAction SilentlyContinue).($d.Name)
    return ([string]$v -eq [string]$d.On)
}
function Update-Privacy {
    $ui.PrivList.Children.Clear(); $on = 0
    foreach ($d in $PrivacyDefs) {
        $cb = New-Object Windows.Controls.CheckBox; $cb.Width = 470; $cb.Margin = '0,4,12,6'; $cb.Tag = $d; $cb.VerticalContentAlignment = 'Top'
        $sp = New-Object Windows.Controls.StackPanel
        $t = New-Object Windows.Controls.TextBlock; $t.Text = $d.Title; $t.FontWeight = 'SemiBold'; $t.TextWrapping = 'Wrap'
        $ds = New-Object Windows.Controls.TextBlock; $ds.Text = $d.Desc; $ds.FontSize = 12; $ds.Foreground = New-UiBrush '#475569'; $ds.TextWrapping = 'Wrap'
        [void]$sp.Children.Add($t); [void]$sp.Children.Add($ds); $cb.Content = $sp
        $cb.IsChecked = Get-PrivState $d; if ($cb.IsChecked) { $on++ }
        [void]$ui.PrivList.Children.Add($cb)
    }
    $score = [int][math]::Round($on * 100 / $PrivacyDefs.Count)
    $ui.PrivScore.Text = [string]$score
    $ui.PrivRing.BorderBrush = New-UiBrush $(if ($score -ge 80) { '#16A34A' } elseif ($score -ge 50) { '#D97706' } else { '#DC2626' })
    $ui.PrivScoreText.Text = '{0} von {1} Datenschutz-Einstellungen sind datensparsam. {2}' -f $on, $PrivacyDefs.Count, $(if ($score -ge 80) { 'Sehr gut.' } elseif ($score -ge 50) { 'Da geht noch was.' } else { 'Windows sammelt hier noch viel.' })
    Update-PrivApps
}
function Save-Privacy {
    $err = @()
    foreach ($cb in $ui.PrivList.Children) {
        $d = $cb.Tag; $want = [bool]$cb.IsChecked
        if ($want -eq (Get-PrivState $d)) { continue }
        try {
            New-Item -Path $d.Path -Force -ErrorAction SilentlyContinue | Out-Null
            foreach ($n in @($d.Name) + @($d.Extra | Where-Object { $_ })) {
                $val = if ($want) { $d.On } else { $d.Off }
                if ($null -eq $val) { Remove-ItemProperty -LiteralPath $d.Path -Name $n -ErrorAction SilentlyContinue }
                elseif ($val -is [string]) { Set-ItemProperty -LiteralPath $d.Path -Name $n -Value $val -Type String -ErrorAction Stop }
                else { Set-ItemProperty -LiteralPath $d.Path -Name $n -Value ([int]$val) -Type DWord -ErrorAction Stop }
            }
        } catch { $err += ('{0}: {1}' -f $d.Title, $_.Exception.Message) }
    }
    if ($err) { Show-UiError ($err -join "`n") } else { $ui.StatusText.Text = 'Datenschutz-Einstellungen übernommen (manches wirkt nach dem Ab- und Anmelden).' }
    Update-Privacy
}
function Update-PrivApps {
    $script:PrivApps = @(Get-PrivacyApps | ForEach-Object { $_ })
    Update-PrivFilter
}
function Update-PrivFilter {
    $i = [math]::Max(0, $ui.PrivCap.SelectedIndex); $cap = if ($i -gt 0) { @($PrivacyCaps.Keys)[$i - 1] } else { '' }
    $t = $ui.PrivSearch.Text.Trim()
    Set-GridItems $ui.PrivGrid @($script:PrivApps | Where-Object { (-not $cap -or $_.Cap -eq $cap) -and (Test-Match $_ $t @('App', 'Key', 'CapDe')) } | Sort-Object @{ e = { if ($_.Last -eq 'GERADE AKTIV') { 0 } else { 1 } } }, CapDe, App)
}
# ---------------------------------------------------------------- Netzwerk (Oberfläche)
function Update-NetPage {
    $ui.NetInfo.Text = 'Wird geladen ...'
    Invoke-Bg -Script { Get-NetOverview } -Functions @('Get-NetOverview') -Done {
        param($r, $err)
        if ($err) { $ui.NetInfo.Text = $err.Message; return }
        $x = @($r | Where-Object { $_ })[0]
        $lines = @()
        foreach ($a in @($x.Adapters)) { $lines += '{0} ({1}, {2}): IP {3}  ·  Router {4}  ·  DNS {5}' -f $a.Name, $a.Desc, $a.Speed, $a.IP, $a.Gw, $a.Dns }
        if ($x.Wifi) { $lines += 'WLAN "{0}": Signal {1}, Kanal {2} ({3}), {4}, {5}/{6} MBit/s, {7}' -f $x.Wifi.Ssid, $x.Wifi.Signal, $x.Wifi.Channel, $x.Wifi.Band, $x.Wifi.Radio, $x.Wifi.Rx, $x.Wifi.Tx, $x.Wifi.Auth }
        $lines += 'Öffentliche IP: ' + $(if ($x.Public) { $x.Public } else { 'nicht ermittelbar' })
        $ui.NetInfo.Text = $lines -join "`n"
        $script:NetAdapters = @($x.Adapters); $script:NetWifi = $x.Wifi
        $cur = (@($x.Adapters) | Select-Object -First 1).Dns
        $ui.DnsChoice.SelectedIndex = 0
        $i = 0; foreach ($k in $DnsProviders.Keys) { $v = $DnsProviders[$k]; if ($v.Count -and $cur -like ($v[0] + '*')) { $ui.DnsChoice.SelectedIndex = $i }; $i++ }
    }
}
function Set-NetDns {
    $i = [math]::Max(0, $ui.DnsChoice.SelectedIndex); $keys = @($DnsProviders.Keys)
    $srv = if ($i -lt $keys.Count) { @($DnsProviders[$keys[$i]]) } else { @($ui.DnsCustom.Text -split '[,; ]+' | Where-Object { $_ -match '^[\d\.:a-fA-F]+$' }) }
    if ($i -ge $keys.Count -and -not $srv.Count) { Show-UiError 'Bitte eigene DNS-Server eintragen (z.B. 192.168.1.2, 1.1.1.1).'; return }
    $n = 0
    foreach ($a in @(Get-NetAdapter -Physical -ErrorAction SilentlyContinue | Where-Object { $_.Status -eq 'Up' })) {
        try { if ($srv.Count) { Set-DnsClientServerAddress -InterfaceIndex $a.ifIndex -ServerAddresses $srv -ErrorAction Stop } else { Set-DnsClientServerAddress -InterfaceIndex $a.ifIndex -ResetServerAddresses -ErrorAction Stop }; $n++ } catch { }
    }
    Clear-DnsClientCache -ErrorAction SilentlyContinue
    $ui.StatusText.Text = 'DNS für {0} Adapter gesetzt: {1}' -f $n, $(if ($srv.Count) { $srv -join ', ' } else { 'automatisch' })
    Update-NetPage
}
function Update-WifiScan {
    $ui.WifiAdvice.Text = 'Suche WLANs ...'
    Invoke-Bg -Script { Get-WifiNetworks } -Functions @('Get-WifiNetworks') -Done {
        param($r, $err)
        if ($err) { $ui.WifiAdvice.Text = $err.Message; return }
        $nets = @($r | Where-Object { $_ -and $_.Ssid -ne $null })
        Set-GridItems $ui.WifiGrid $nets
        $ch24 = @{ 1 = 0; 6 = 0; 11 = 0 }
        foreach ($n in $nets) { $c = [int]$n.Channel; if ($c -ge 1 -and $c -le 13) { foreach ($k in 1, 6, 11) { if ([math]::Abs($c - $k) -le 2) { $ch24[$k] += [math]::Max(1, $n.Signal / 25) } } } }
        $best = ($ch24.GetEnumerator() | Sort-Object Value | Select-Object -First 1).Key
        $mine = if ($script:NetWifi) { [int]$script:NetWifi.Channel } else { 0 }
        $ui.WifiAdvice.Text = if (-not $nets.Count) { 'Keine WLANs gefunden (WLAN aus oder kein WLAN-Adapter).' } else { '{0} WLANs in Reichweite. 2,4 GHz: Kanal {1} ist am freiesten{2}. Wenn möglich 5 GHz nutzen - dort gibt es viel mehr freie Kanäle.' -f $nets.Count, $best, $(if ($mine -ge 1 -and $mine -le 13 -and [math]::Abs($mine - $best) -gt 2) { (' - dein Router funkt auf Kanal {0}, im Router auf {1} umstellen bringt mehr Tempo' -f $mine, $best) } elseif ($mine -gt 13) { (' - du bist mit 5 GHz verbunden (Kanal {0}), sehr gut' -f $mine) } else { '' }) }
    }
}
function Start-NetTool([string]$Tool) {
    $h = $ui.NetHost.Text.Trim(); if (-not $h) { return }
    $ui.NetOut.Text = 'Läuft ...'
    Invoke-Bg -Script {
        param($t, $h)
        switch ($t) {
            'ping'  { (& ping.exe -n 4 $h 2>&1) -join "`r`n" }
            'trace' { (& tracert.exe -d -h 20 -w 800 $h 2>&1) -join "`r`n" }
            'ns'    { (& nslookup.exe $h 2>&1) -join "`r`n" }
            'port'  { $r = Test-NetConnection -ComputerName $h -Port 443 -WarningAction SilentlyContinue; 'Ziel {0} ({1}), Port 443: {2}, Ping: {3}' -f $h, $r.RemoteAddress, $(if ($r.TcpTestSucceeded) { 'offen' } else { 'ZU / nicht erreichbar' }), $(if ($r.PingSucceeded) { 'ja' } else { 'nein' }) }
        }
    } -Arguments @($Tool, $h) -Done { param($r, $err) $ui.NetOut.Text = if ($err) { $err.Message } else { (@($r) -join "`r`n") } }
}
# ---------------------------------------------------------------- Speicherplatz (Oberfläche)
$SpcCs = @"
using System; using System.IO; using System.Collections.Generic; using System.Security.Cryptography;
namespace PCPflegeSpc {
public class Item { public string Name; public string Path; public long Size; public long Files; public bool IsDir; public DateTime Date; }
public static class Scan {
  static long DirSize(DirectoryInfo d, List<Item> big, long minBig, ref long files) {
    long s = 0;
    try { foreach (FileInfo f in d.EnumerateFiles()) { try { s += f.Length; files++; if (f.Length >= minBig) big.Add(new Item { Name = f.Name, Path = f.FullName, Size = f.Length, Date = f.LastWriteTime }); } catch { } } } catch { }
    try { foreach (DirectoryInfo sd in d.EnumerateDirectories()) { if ((sd.Attributes & FileAttributes.ReparsePoint) != 0) continue; s += DirSize(sd, big, minBig, ref files); } } catch { }
    return s;
  }
  public static List<Item> Children(string root, List<Item> big, long minBig) {
    List<Item> r = new List<Item>(); DirectoryInfo d = new DirectoryInfo(root);
    long loose = 0, lf = 0;
    try { foreach (FileInfo f in d.EnumerateFiles()) { try { loose += f.Length; lf++; if (f.Length >= minBig) big.Add(new Item { Name = f.Name, Path = f.FullName, Size = f.Length, Date = f.LastWriteTime }); } catch { } } } catch { }
    try { foreach (DirectoryInfo sd in d.EnumerateDirectories()) { if ((sd.Attributes & FileAttributes.ReparsePoint) != 0) continue; long files = 0; long s = DirSize(sd, big, minBig, ref files); r.Add(new Item { Name = sd.Name, Path = sd.FullName, Size = s, Files = files, IsDir = true }); } } catch { }
    if (loose > 0) r.Add(new Item { Name = "(Dateien in diesem Ordner)", Path = root, Size = loose, Files = lf, IsDir = false });
    return r;
  }
  static void AllFiles(DirectoryInfo d, List<FileInfo> acc, long min) {
    try { foreach (FileInfo f in d.EnumerateFiles()) { try { if (f.Length >= min) acc.Add(f); } catch { } } } catch { }
    try { foreach (DirectoryInfo sd in d.EnumerateDirectories()) { if ((sd.Attributes & FileAttributes.ReparsePoint) != 0) continue; AllFiles(sd, acc, min); } } catch { }
  }
  static string Hash(string p, long max) {
    try { using (FileStream fs = new FileStream(p, FileMode.Open, FileAccess.Read, FileShare.ReadWrite)) using (MD5 m = MD5.Create()) {
      if (max <= 0) return BitConverter.ToString(m.ComputeHash(fs));
      byte[] b = new byte[max]; int n = fs.Read(b, 0, b.Length); return BitConverter.ToString(m.ComputeHash(b, 0, n)); } } catch { return null; }
  }
  public static List<List<Item>> Dupes(string root, long min) {
    List<FileInfo> all = new List<FileInfo>(); AllFiles(new DirectoryInfo(root), all, min);
    Dictionary<long, List<FileInfo>> bySize = new Dictionary<long, List<FileInfo>>();
    foreach (FileInfo f in all) { List<FileInfo> l; if (!bySize.TryGetValue(f.Length, out l)) { l = new List<FileInfo>(); bySize[f.Length] = l; } l.Add(f); }
    List<List<Item>> res = new List<List<Item>>();
    foreach (List<FileInfo> grp in bySize.Values) {
      if (grp.Count < 2) continue;
      Dictionary<string, List<FileInfo>> q = new Dictionary<string, List<FileInfo>>();
      foreach (FileInfo f in grp) { string h = Hash(f.FullName, 65536); if (h == null) continue; List<FileInfo> l; if (!q.TryGetValue(h, out l)) { l = new List<FileInfo>(); q[h] = l; } l.Add(f); }
      foreach (List<FileInfo> g2 in q.Values) {
        if (g2.Count < 2) continue;
        Dictionary<string, List<Item>> full = new Dictionary<string, List<Item>>();
        foreach (FileInfo f in g2) { string h = Hash(f.FullName, 0); if (h == null) continue; List<Item> l; if (!full.TryGetValue(h, out l)) { l = new List<Item>(); full[h] = l; } l.Add(new Item { Name = f.Name, Path = f.FullName, Size = f.Length, Date = f.LastWriteTime }); }
        foreach (List<Item> g3 in full.Values) if (g3.Count > 1) res.Add(g3);
      }
    }
    return res;
  }
}}
"@
function Format-Size([double]$b) { if ($b -ge 1TB) { '{0:N2} TB' -f ($b / 1TB) } elseif ($b -ge 1GB) { '{0:N1} GB' -f ($b / 1GB) } elseif ($b -ge 1MB) { '{0:N0} MB' -f ($b / 1MB) } else { '{0:N0} KB' -f ($b / 1KB) } }
function Start-SpaceScan {
    $root = $ui.SpcRoot.Text.Trim(); if (-not $root) { $root = $env:SystemDrive + '\'; $ui.SpcRoot.Text = $root }
    if (-not (Test-Path -LiteralPath $root)) { Show-UiError 'Ordner nicht gefunden.'; return }
    $ui.SpcInfo.Text = 'Analysiere {0} ...' -f $root; $ui.BtnSpcScan.IsEnabled = $false; $ui.SpcMap.Children.Clear()
    Invoke-Bg -Script {
        param($root, $cs)
        Add-Type -TypeDefinition $cs -ErrorAction SilentlyContinue
        $big = New-Object 'System.Collections.Generic.List[PCPflegeSpc.Item]'
        $kids = [PCPflegeSpc.Scan]::Children($root, $big, 10MB)
        [pscustomobject]@{ Kids = @($kids | Sort-Object Size -Descending); Big = @($big | Sort-Object Size -Descending | Select-Object -First 1000) }
    } -Arguments @($root, $SpcCs) -Done {
        param($r, $err)
        $ui.BtnSpcScan.IsEnabled = $true
        if ($err) { $ui.SpcInfo.Text = 'Fehler: ' + $err.Message; return }
        $x = @($r | Where-Object { $_ })[0]
        $script:SpcKids = @($x.Kids | Where-Object { $_.Size -gt 0 }); $script:SpcBig = @($x.Big)
        $tot = ($script:SpcKids | Measure-Object Size -Sum).Sum
        $drv = $null; try { $drv = New-Object IO.DriveInfo ($ui.SpcRoot.Text.Substring(0, 1)) } catch { }
        $ui.SpcInfo.Text = '{0}: {1} belegt in {2} Ordnern{3}' -f $ui.SpcRoot.Text, (Format-Size $tot), @($script:SpcKids | Where-Object IsDir).Count, $(if ($drv) { '  ·  Laufwerk: {0} frei von {1}' -f (Format-Size $drv.AvailableFreeSpace), (Format-Size $drv.TotalSize) } else { '' })
        Show-Treemap; Update-SpcFiles
    }
}
function Show-Treemap {
    $cv = $ui.SpcMap; $cv.Children.Clear()
    $W = [math]::Max(400, $cv.ActualWidth); $H = [math]::Max(300, $cv.ActualHeight); if ($W -lt 50) { $W = 1100 }; if ($H -lt 50) { $H = 428 }
    $items = @($script:SpcKids | Select-Object -First 40)
    $tot = ($items | Measure-Object Size -Sum).Sum; if (-not $tot) { return }
    $areas = @($items | ForEach-Object { $_.Size / $tot * $W * $H })
    $pal = @('#2D7FF9', '#7C3AED', '#0891B2', '#16A34A', '#EA580C', '#DB2777', '#0F766E', '#D97706', '#4F46E5', '#65A30D', '#BE123C', '#475569')
    $rects = New-Object System.Collections.ArrayList
    $x = 0.0; $y = 0.0; $w = [double]$W; $h = [double]$H; $i = 0
    $worst = { param($row, $side) $s = ($row | Measure-Object -Sum).Sum; $mx = ($row | Measure-Object -Maximum).Maximum; $mn = ($row | Measure-Object -Minimum).Minimum; [math]::Max($side * $side * $mx / ($s * $s), $s * $s / ($side * $side * $mn)) }
    $row = @(); $rowIdx = @()
    $flush = {
        $s = ($row | Measure-Object -Sum).Sum
        if ($w -ge $h) { $cw = $s / $h; $yy = $y; for ($k = 0; $k -lt $row.Count; $k++) { $rh = $row[$k] / $cw; [void]$rects.Add(@($rowIdx[$k], $x, $yy, $cw, $rh)); $yy += $rh }; $script:tmX = $x + $cw; $script:tmW = $w - $cw; $script:tmY = $y; $script:tmH = $h }
        else { $rh = $s / $w; $xx = $x; for ($k = 0; $k -lt $row.Count; $k++) { $cw = $row[$k] / $rh; [void]$rects.Add(@($rowIdx[$k], $xx, $y, $cw, $rh)); $xx += $cw }; $script:tmX = $x; $script:tmW = $w; $script:tmY = $y + $rh; $script:tmH = $h - $rh }
    }
    while ($i -lt $areas.Count) {
        $side = [math]::Min($w, $h); $a = $areas[$i]
        if (-not $row.Count -or (& $worst ($row + $a) $side) -le (& $worst $row $side)) { $row += $a; $rowIdx += $i; $i++ }
        else { & $flush; $x = $script:tmX; $w = $script:tmW; $y = $script:tmY; $h = $script:tmH; $row = @(); $rowIdx = @() }
    }
    if ($row.Count) { & $flush }
    foreach ($rc in $rects) {
        $it = $items[$rc[0]]
        $bd = New-Object Windows.Controls.Border; $bd.Width = [math]::Max(1, $rc[3] - 2); $bd.Height = [math]::Max(1, $rc[4] - 2); $bd.CornerRadius = '4'; $bd.Cursor = 'Hand'; $bd.Tag = $it
        $bd.Background = (New-Object Windows.Media.BrushConverter).ConvertFromString($pal[$rc[0] % $pal.Count]); $bd.Opacity = $(if ($it.IsDir) { 0.92 } else { 0.55 })
        $bd.ToolTip = "{0}`n{1}  ·  {2:N0} Dateien" -f $it.Path, (Format-Size $it.Size), $it.Files
        if ($rc[3] -gt 60 -and $rc[4] -gt 30) {
            $sp = New-Object Windows.Controls.StackPanel; $sp.Margin = '6,4'
            $t1 = New-Object Windows.Controls.TextBlock; $t1.Text = $it.Name; $t1.Foreground = [Windows.Media.Brushes]::White; $t1.FontWeight = 'SemiBold'; $t1.TextTrimming = 'CharacterEllipsis'; $t1.FontSize = $(if ($rc[3] -gt 200 -and $rc[4] -gt 80) { 15 } else { 12 })
            $t2 = New-Object Windows.Controls.TextBlock; $t2.Text = Format-Size $it.Size; $t2.Foreground = [Windows.Media.Brushes]::White; $t2.Opacity = 0.9; $t2.FontSize = 11
            [void]$sp.Children.Add($t1); [void]$sp.Children.Add($t2); $bd.Child = $sp
        }
        $bd.Add_MouseLeftButtonUp({ param($s, $e) if ($s.Tag.IsDir) { $ui.SpcRoot.Text = $s.Tag.Path; Start-SpaceScan } })
        $bd.Add_MouseRightButtonUp({ param($s, $e) Start-Process explorer.exe ('"{0}"' -f $s.Tag.Path) })
        [Windows.Controls.Canvas]::SetLeft($bd, $rc[1] + 1); [Windows.Controls.Canvas]::SetTop($bd, $rc[2] + 1)
        [void]$cv.Children.Add($bd)
    }
}
function Update-SpcFiles {
    $m = [math]::Max(0, $ui.SpcFilesMode.SelectedIndex)
    $dl = Join-Path $env:USERPROFILE 'Downloads'
    $rows = @($script:SpcBig | Where-Object {
        switch ($m) { 1 { $_.Path -like "$dl*" -and $_.Size -ge 50MB -and $_.Date -lt (Get-Date).AddDays(-90) } 2 { $_.Name -match '\.(mp4|mkv|avi|mov|wmv|m4v|mts|webm)$' } 3 { $_.Name -match '\.(exe|msi|iso|zip|7z|rar|cab|img)$' } default { $true } }
    } | Select-Object -First 300 | ForEach-Object { [pscustomobject]@{ Name = $_.Name; Path = $_.Path; Dir = [IO.Path]::GetDirectoryName($_.Path); Size = $_.Size; SizeText = (Format-Size $_.Size); Date = $_.Date.ToString('dd.MM.yyyy'); DateSort = $_.Date.ToString('yyyyMMdd') } })
    Set-GridItems $ui.SpcFiles $rows
}
function Remove-ToRecycle($Paths) {
    Add-Type -AssemblyName Microsoft.VisualBasic
    $n = 0; foreach ($p in $Paths) { try { [Microsoft.VisualBasic.FileIO.FileSystem]::DeleteFile($p, 'OnlyErrorDialogs', 'SendToRecycleBin'); $n++ } catch { } }
    return $n
}
function Start-DupScan {
    $root = $ui.SpcRoot.Text.Trim(); if (-not $root -or $root.Length -le 3) { if (-not (Confirm-Ui 'Doppelte Dateien auf dem ganzen Laufwerk suchen? Das kann bei großen Platten lange dauern. Besser einen Ordner wählen (z.B. Bilder oder Downloads).')) { return } }
    if (-not $root) { $root = $env:SystemDrive + '\' }
    $ui.DupInfo.Text = 'Suche doppelte Dateien in {0} ... (Dateien ab 1 MB, Inhalt wird verglichen)' -f $root; $ui.BtnDupScan.IsEnabled = $false
    Invoke-Bg -Script { param($root, $cs) Add-Type -TypeDefinition $cs -ErrorAction SilentlyContinue; , ([PCPflegeSpc.Scan]::Dupes($root, 1MB)) } -Arguments @($root, $SpcCs) -Done {
        param($r, $err)
        $ui.BtnDupScan.IsEnabled = $true
        if ($err) { $ui.DupInfo.Text = 'Fehler: ' + $err.Message; return }
        $rows = New-Object System.Collections.ArrayList; $g = 0; $waste = 0
        foreach ($grp in @($r | ForEach-Object { $_ } | Where-Object { $_ } | Sort-Object { $_[0].Size * ($_.Count - 1) } -Descending)) {
            $g++; $items = @($grp | Sort-Object Date)
            $waste += $items[0].Size * ($items.Count - 1)
            for ($k = 0; $k -lt $items.Count; $k++) { $it = $items[$k]; [void]$rows.Add([pscustomobject]@{ Group = $g; Name = $it.Name; Path = $it.Path; Dir = [IO.Path]::GetDirectoryName($it.Path); SizeText = (Format-Size $it.Size); Date = $it.Date.ToString('dd.MM.yyyy'); Copy = ($k -gt 0); Level = $(if ($k -gt 0) { '' } else { 'Good' }) }) }
        }
        Set-GridItems $ui.DupGrid @($rows)
        $ui.DupInfo.Text = if ($g) { '{0} Gruppen doppelter Dateien - {1} ließen sich sparen. Grün = Original (älteste Datei).' -f $g, (Format-Size $waste) } else { 'Keine doppelten Dateien gefunden.' }
    }
}

# ---------------------------------------------------------------- Datensicherung (Oberfläche)
function Sync-BkSources { $ui.Backup_Sources.Text = (@($ui.BkSourceList.Items | ForEach-Object { [string]$_ }) -join ';') }
function Add-BkSource([string]$Path) {
    if (-not $Path) { return }
    foreach ($i in $ui.BkSourceList.Items) { if ([string]$i -eq $Path) { return } }
    [void]$ui.BkSourceList.Items.Add($Path); Sync-BkSources
}
function Load-BkSources {
    $ui.BkSourceList.Items.Clear()
    foreach ($p in @(([string]$ui.Backup_Sources.Text) -split ';' | Where-Object { $_.Trim() })) { [void]$ui.BkSourceList.Items.Add($p.Trim()) }
}
function Update-BkInfo {
    $t = $ui.Backup_Target.Text.Trim()
    $ui.BkTargetInfo.Text = ''
    if ($t -match '^[A-Za-z]:') {
        try { $d = New-Object IO.DriveInfo $t.Substring(0, 2); $ui.BkTargetInfo.Text = 'Laufwerk {0} ({1}, {2}): {3:N0} GB frei von {4:N0} GB' -f $d.Name, $d.DriveType, $d.DriveFormat, ($d.AvailableFreeSpace / 1GB), ($d.TotalSize / 1GB) }
        catch { $ui.BkTargetInfo.Text = 'Laufwerk ist gerade nicht angeschlossen.' }
    } elseif ($t -like '\\*') { $ui.BkTargetInfo.Text = 'Netzwerkziel - für die automatische Sicherung bitte NAS-Benutzer und Kennwort speichern.' }
    $c = Get-BackupCred
    $ui.BkNasInfo.Text = if ($c -and $c.User) { 'NAS-Zugang gespeichert für: ' + $c.User } else { 'Kein NAS-Zugang gespeichert.' }
    $lf = Join-Path $DataDir 'backup_last.json'
    if (Test-Path $lf) { $l = Get-Content $lf -Raw | ConvertFrom-Json; $ui.BkLast.Text = '{0} - {1} ({2} Min., {3} Problem(e))' -f $l.Date, $l.Target, $l.Minutes, $l.Errors } else { $ui.BkLast.Text = 'noch nie' }
    $tk = Get-ScheduledTask -TaskName 'PC-Pflege Sicherung' -ErrorAction SilentlyContinue
    $ui.BkTaskInfo.Text = if ($tk) { $i = $tk | Get-ScheduledTaskInfo; 'Automatische Sicherung aktiv - nächster Lauf: {0:dd.MM.yyyy HH:mm}' -f $i.NextRunTime } else { 'Automatische Sicherung ist aus.' }
}
function Register-BackupTask($Cfg) {
    $tn = 'PC-Pflege Sicherung'
    if ($Script:IsPortable) { return '' }
    $b = $Cfg.Backup
    if (-not $b.Enabled -or -not [string]$b.Target) { Unregister-ScheduledTask -TaskName $tn -Confirm:$false -ErrorAction SilentlyContinue; return '' }
    $time = [datetime]::MinValue
    if (-not [datetime]::TryParseExact([string]$b.Time, 'HH:mm', [Globalization.CultureInfo]::InvariantCulture, 'None', [ref]$time)) { throw 'Sicherung: Uhrzeit bitte als HH:mm angeben, z.B. 20:00' }
    $days = @{ 'Montag' = 'Monday'; 'Dienstag' = 'Tuesday'; 'Mittwoch' = 'Wednesday'; 'Donnerstag' = 'Thursday'; 'Freitag' = 'Friday'; 'Samstag' = 'Saturday'; 'Sonntag' = 'Sunday' }
    $trg = switch ([string]$b.Frequency) {
        'Werktags'    { New-ScheduledTaskTrigger -Weekly -DaysOfWeek Monday, Tuesday, Wednesday, Thursday, Friday -At $time }
        'Wöchentlich' { New-ScheduledTaskTrigger -Weekly -DaysOfWeek $(if ($days[[string]$b.Day]) { $days[[string]$b.Day] } else { 'Friday' }) -At $time }
        default       { New-ScheduledTaskTrigger -Daily -At $time }
    }
    Sync-PflegeFiles
    $act = New-ScheduledTaskAction -Execute $PsExe -Argument (Get-PsArgString (Join-Path $DataDir 'PCPflege.ps1') @('-Backup'))
    $pr = New-ScheduledTaskPrincipal -UserId 'NT AUTHORITY\SYSTEM' -LogonType ServiceAccount -RunLevel Highest
    $set = New-ScheduledTaskSettingsSet -StartWhenAvailable -AllowStartIfOnBatteries -DontStopIfGoingOnBatteries -ExecutionTimeLimit (New-TimeSpan -Hours 12) -MultipleInstances IgnoreNew
    $set.WakeToRun = [bool]$b.WakeToRun
    Register-ScheduledTask -TaskName $tn -Action $act -Trigger $trg -Principal $pr -Settings $set -Description 'PC-Tools: Datensicherung' -Force | Out-Null
    return ' Sicherung eingeplant.'
}
function Read-BkRestoreSet {
    $ui.BkRestoreList.Children.Clear(); $script:BkRestoreRows = @()
    $set = $ui.BkRestoreSet.Text.Trim()
    $mf = Join-Path $set 'sicherung.json'
    if (-not (Test-Path -LiteralPath $mf)) { Show-UiError 'In diesem Ordner liegt keine Sicherung von PC-Tools (sicherung.json fehlt). Bitte den Ordner "Aktuell" oder einen Datumsordner wählen.'; $ui.BtnBkRestore.IsEnabled = $false; return }
    $m = Get-Content -LiteralPath $mf -Raw -Encoding UTF8 | ConvertFrom-Json
    $h = New-Object Windows.Controls.TextBlock; $h.Text = 'Sicherung von {0} vom {1} ({2})' -f $m.Computer, $m.Date, $m.Mode; $h.Margin = '0,0,0,4'; $h.FontWeight = 'SemiBold'
    [void]$ui.BkRestoreList.Children.Add($h)
    foreach ($f in @($m.Folders)) {
        $cb = New-Object Windows.Controls.CheckBox; $cb.IsChecked = $true; $cb.Margin = '0,2'
        $cb.Content = '{0}   ->   {1}' -f $f.Name, $f.Source
        [void]$ui.BkRestoreList.Children.Add($cb)
        $script:BkRestoreRows += [pscustomobject]@{ Name = $f.Name; Source = $f.Source; Check = $cb }
    }
    $ui.BtnBkRestore.IsEnabled = [bool]$script:BkRestoreRows.Count
}
function Start-BkRestore {
    $sel = @($script:BkRestoreRows | Where-Object { $_.Check.IsChecked })
    if (-not $sel.Count) { return }
    $other = [bool]$ui.BkRestoreOther.IsChecked; $ot = $ui.BkRestoreTarget.Text.Trim()
    if ($other -and -not $ot) { Show-UiError 'Bitte den anderen Zielordner angeben.'; return }
    $items = @($sel | ForEach-Object { @{ Name = $_.Name; Dest = $(if ($other) { Join-Path $ot $_.Name } else { $_.Source }) } })
    $txt = ($items | ForEach-Object { '{0} -> {1}' -f $_.Name, $_.Dest }) -join "`n"
    if (-not (Confirm-Ui ("Diese Ordner wiederherstellen?`n`n{0}`n`n{1}" -f $txt, $ui.BkRestoreMode.SelectedItem.Content))) { return }
    Start-Run -Parts @('Restore') -Job @{ Set = $ui.BkRestoreSet.Text.Trim(); Items = $items; OnlyNewer = ($ui.BkRestoreMode.SelectedIndex -eq 1) }
}

# ---------------------------------------------------------------- PC-Umzug (Oberfläche)
function Build-MigFolders {
    $ui.MigFolders.Children.Clear()
    foreach ($f in (Get-KnownFolders)) {
        $cb = New-Object Windows.Controls.CheckBox; $cb.Content = $f.Name; $cb.Tag = $f.Path; $cb.IsChecked = $true; $cb.Width = 160; $cb.Margin = '0,3'
        $cb.ToolTip = $f.Path
        if ($f.Path -like '\\*') { $cb.Content = $f.Name + ' (NAS)'; $cb.IsChecked = $false; $cb.ToolTip = $f.Path + ' - liegt schon auf dem NAS, muss meist nicht umziehen' }
        [void]$ui.MigFolders.Children.Add($cb)
    }
}
function Read-MigAppData {
    $ui.MigAppData.Children.Clear()
    $t = New-Object Windows.Controls.TextBlock; $t.Text = 'Wird eingelesen ...'; [void]$ui.MigAppData.Children.Add($t)
    Invoke-Bg -Script {
        param($root)
        foreach ($d in @(Get-ChildItem -LiteralPath $root -Directory -Force -ErrorAction SilentlyContinue | Where-Object { $_.Name -notin 'Microsoft', 'Temp', 'Mozilla' })) {
            $size = 0; try { $size = (Get-ChildItem -LiteralPath $d.FullName -Recurse -File -Force -ErrorAction SilentlyContinue | Measure-Object Length -Sum).Sum } catch { }
            [pscustomobject]@{ Name = $d.Name; MB = [math]::Round($size / 1MB, 1) }
        }
    } -Arguments @($env:APPDATA) -Done {
        param($r, $err)
        $ui.MigAppData.Children.Clear()
        foreach ($x in @($r | Where-Object { $_ } | Sort-Object Name)) {
            $cb = New-Object Windows.Controls.CheckBox; $cb.Content = '{0} ({1:N1} MB)' -f $x.Name, $x.MB; $cb.Tag = $x.Name; $cb.Width = 260; $cb.Margin = '0,2'
            [void]$ui.MigAppData.Children.Add($cb)
        }
    }
}
function Start-MigExport {
    $t = $ui.MigTarget.Text.Trim()
    if (-not $t) { Show-UiError 'Bitte einen Speicherort für das Umzugspaket wählen.'; return }
    $folders = @($ui.MigFolders.Children | Where-Object { $_.IsChecked } | ForEach-Object { @{ Name = ([string]$_.Content -replace ' \(NAS\)$', ''); Path = [string]$_.Tag } })
    $settings = @($ui.MigSettings.Children | Where-Object { $_.IsChecked } | ForEach-Object { [string]$_.Tag })
    $apps = @($ui.MigAppData.Children | Where-Object { $_ -is [Windows.Controls.CheckBox] -and $_.IsChecked } | ForEach-Object { [string]$_.Tag })
    Start-Run -Parts @('MigrateExport') -Job @{ Target = $t; Folders = $folders; Programs = [bool]$ui.MigPrograms.IsChecked; Settings = $settings; AppData = $apps }
}
function New-BrowserButton([string]$Key, [string]$Text, [bool]$Primary) {
    $b = New-Object Windows.Controls.Button
    if (-not $Primary) { $b.Style = $window.FindResource('Sec') }
    $b.Content = $Text; $b.Tag = $Key; $b.Padding = '14,7'; $b.Margin = '0,0,8,8'
    return $b
}
function Build-MigPwButtons {
    $ui.MigPwExport.Children.Clear()
    $found = 0
    foreach ($k in $BrowserPwDefs.Keys) {
        if (-not (Get-BrowserExe $k)) { continue }
        $found++
        $b = New-BrowserButton $k ('{0}: Kennwörter exportieren' -f $BrowserPwDefs[$k].Name) $false
        $b.Add_Click({ param($s, $e) Start-BrowserPw ([string]$s.Tag) 'Export' })
        [void]$ui.MigPwExport.Children.Add($b)
    }
    if (-not $found) { $t = New-Object Windows.Controls.TextBlock; $t.Text = 'Kein unterstützter Browser gefunden.'; [void]$ui.MigPwExport.Children.Add($t) }
    Update-MigPwInfo
}
function Update-MigPwInfo {
    $t = $ui.MigTarget.Text.Trim()
    if (-not $t) { $ui.MigPwInfo.Text = 'Zuerst oben den Speicherort des Pakets wählen.'; return }
    $csv = @(Get-ChildItem -LiteralPath (Get-PwFolder $t) -Filter *.csv -File -ErrorAction SilentlyContinue)
    $ui.MigPwInfo.Text = if ($csv.Count) { 'Bereit fürs Paket: ' + (($csv | ForEach-Object { $_.Name }) -join ', ') } else { ('Noch keine Kennwort-Datei in {0}' -f (Get-PwFolder $t)) }
}
function Start-BrowserPw([string]$Key, [string]$Mode) {
    $b = $BrowserPwDefs[$Key]; $exe = Get-BrowserExe $Key
    if (-not $exe) { Show-UiError ('{0} ist nicht installiert.' -f $b.Name); return }
    if ($Mode -eq 'Export') {
        $t = $ui.MigTarget.Text.Trim()
        if (-not $t) { Show-UiError 'Bitte zuerst den Speicherort des Umzugspakets wählen.'; return }
        $dir = Get-PwFolder $t
        try { New-Item $dir -ItemType Directory -Force -ErrorAction Stop | Out-Null } catch { Show-UiError ('Ordner kann nicht angelegt werden: ' + $_.Exception.Message); return }
        $msg = "{0} öffnet jetzt die Kennwort-Verwaltung.`n`n1. {1}`n2. Mit Windows-Kennwort oder PIN bestätigen.`n3. Im Speichern-Fenster oben in die Adresszeile klicken, Strg+V (Ordner steht in der Zwischenablage) und Enter, dann Speichern.`n`nOrdner: {2}`n`nDanach hier 'Umzugspaket erstellen' - die Datei wandert ins Paket." -f $b.Name, $(switch ($Key) {
            'Firefox' { 'Oben rechts auf "..." klicken > "Zugangsdaten exportieren ..." (nur nötig, wenn Firefox auf dem neuen PC nicht per Profil umzieht).' }
            'Edge'    { 'Bei "Kennwörter" auf "..." klicken > "Kennwörter exportieren".' }
            'Opera'   { 'Bei "Passwörter" auf "..." klicken > "Passwörter exportieren".' }
            default   { 'Bei "Kennwörter exportieren" auf "Datei herunterladen" klicken.' } }), $dir
        $target = $dir; $url = $b.Export
    } else {
        $dir = [string]$script:MigPwDir
        $csv = @(Get-ChildItem -LiteralPath $dir -Filter *.csv -File -ErrorAction SilentlyContinue)
        $pick = $csv | Where-Object { $_.Name -match [regex]::Escape($b.Name) } | Select-Object -First 1
        if (-not $pick) { $pick = $csv | Select-Object -First 1 }
        $target = if ($pick) { $pick.FullName } else { $dir }
        $msg = "{0} öffnet jetzt den Import.`n`n1. {1}`n2. Im Datei-Fenster unten bei Dateiname Strg+V (der Pfad steht in der Zwischenablage) und Enter.`n`nDatei: {2}`n`nWichtig: erst NACH 'Ausgewählte zurückspielen' importieren, sonst überschreibt das Browser-Profil die Kennwörter wieder. Zum Schluss 'Kennwort-Dateien jetzt löschen'." -f $b.Name, $(switch ($Key) {
            'Firefox' { 'Oben rechts auf "..." klicken > "Aus Datei importieren ...".' }
            'Edge'    { 'Bei "Importieren aus" die Option "Kennwörter-CSV-Datei" wählen > "Datei auswählen".' }
            'Opera'   { 'Als Quelle "Passwörter-CSV-Datei" wählen > "Datei auswählen".' }
            default   { 'Bei "Kennwörter importieren" auf "Datei auswählen" klicken.' } }), $target
        $url = $b.Import
    }
    try { Set-Clipboard -Value $target } catch { try { [Windows.Clipboard]::SetText($target) } catch { } }
    [Windows.MessageBox]::Show((T ($msg)), (T ('PC-Tools - ' + $b.Name)), 'OK', 'Information') | Out-Null
    try { Start-Process -FilePath $exe -ArgumentList $url } catch { Show-UiError ('{0} konnte nicht gestartet werden: {1}' -f $b.Name, $_.Exception.Message) }
    if ($Mode -eq 'Export') { $ui.StatusText.Text = 'Kennwort-Export: Ordner in der Zwischenablage - nach dem Speichern "Umzugspaket erstellen".' }
}
function Update-MigPwImport([string]$Package) {
    $script:MigPwDir = $null
    $cands = @((Join-Path $Package 'Kennwoerter'), (Get-PwFolder (Split-Path $Package -Parent)))
    foreach ($c in $cands) { if (@(Get-ChildItem -LiteralPath $c -Filter *.csv -File -ErrorAction SilentlyContinue).Count) { $script:MigPwDir = $c; break } }
    $ui.MigPwImport.Children.Clear()
    if (-not $script:MigPwDir) { $ui.MigPwImpBox.Visibility = 'Collapsed'; return }
    $csv = @(Get-ChildItem -LiteralPath $script:MigPwDir -Filter *.csv -File)
    $ui.MigPwImpInfo.Text = ('Im Paket: {0}. Erst "Ausgewählte zurückspielen", dann hier je Browser importieren. Der Pfad kommt automatisch in die Zwischenablage.' -f (($csv | ForEach-Object { $_.Name }) -join ', '))
    foreach ($k in $BrowserPwDefs.Keys) {
        if (-not (Get-BrowserExe $k)) { continue }
        $b = New-BrowserButton $k ('In {0} importieren' -f $BrowserPwDefs[$k].Name) $true
        $b.Add_Click({ param($s, $e) Start-BrowserPw ([string]$s.Tag) 'Import' })
        [void]$ui.MigPwImport.Children.Add($b)
    }
    $ui.MigPwImpBox.Visibility = 'Visible'
}
function Read-MigPackage {
    $p = $ui.MigPackage.Text.Trim()
    $mf = Join-Path $p 'umzug.json'
    if (-not (Test-Path -LiteralPath $mf)) { Show-UiError 'Kein Umzugspaket gefunden (umzug.json fehlt). Bitte den Ordner PC-Umzug_... wählen.'; return }
    $m = Get-Content -LiteralPath $mf -Raw -Encoding UTF8 | ConvertFrom-Json
    $ui.MigInfo.Text = 'Umzugspaket von {0} (Benutzer {1}, {2}), erstellt am {3}' -f $m.Computer, $m.User, $m.Windows, $m.Date
    foreach ($w in 'MigImpFolders', 'MigImpPrograms', 'MigImpSettings', 'MigImpAppData') { $ui[$w].Children.Clear() }
    foreach ($f in @($m.Folders)) { $cb = New-Object Windows.Controls.CheckBox; $cb.Content = $f.Name; $cb.Tag = $f.Name; $cb.IsChecked = $true; $cb.Width = 160; $cb.Margin = '0,3'; [void]$ui.MigImpFolders.Children.Add($cb) }
    foreach ($k in @($m.Settings)) { $cb = New-Object Windows.Controls.CheckBox; $cb.Content = $MigSettingDefs[$k]; $cb.Tag = $k; $cb.IsChecked = $true; $cb.Width = 330; $cb.Margin = '0,3'; [void]$ui.MigImpSettings.Children.Add($cb) }
    foreach ($a in @($m.AppData)) { $cb = New-Object Windows.Controls.CheckBox; $cb.Content = $a; $cb.Tag = $a; $cb.IsChecked = $true; $cb.Width = 260; $cb.Margin = '0,3'; [void]$ui.MigImpAppData.Children.Add($cb) }
    $manual = @()
    $pf = Join-Path $p 'Programme\Programme.json'
    if (Test-Path -LiteralPath $pf) {
        $installed = @{}; foreach ($x in (Get-InstalledPrograms)) { $installed[$x.Name.ToLower()] = $true }
        $ninNames = @($NiniteCatalog -split "`n" | ForEach-Object { ($_ -split '\|')[1] } | Where-Object { $_ })
        foreach ($x in @(Get-Content -LiteralPath $pf -Raw -Encoding UTF8 | ConvertFrom-Json | Sort-Object Name)) {
            $src = ''; $id = ''
            if ($x.Id) { $src = 'winget'; $id = $x.Id }
            else {
                $nn = $ninNames | Where-Object { $x.Name -match ('(^|\s)' + [regex]::Escape($_) + '(\s|$|\d)') } | Sort-Object Length -Descending | Select-Object -First 1
                if ($nn) { $src = 'Ninite'; $id = $nn } else { $manual += ('{0}  {1}  ({2})' -f $x.Name, $x.Version, $x.Publisher); continue }
            }
            if ($x.Name -match '^(Microsoft Visual C\+\+|Microsoft \.NET|Windows SDK|Microsoft Edge WebView|Microsoft Update Health)') { continue }
            $cb = New-Object Windows.Controls.CheckBox; $cb.Width = 300; $cb.Margin = '0,2'; $cb.Tag = ('{0}|{1}' -f $src, $id)
            $cb.Content = '{0}  [{1}]' -f $x.Name, $src; $cb.ToolTip = $id
            $cb.IsChecked = -not $installed.ContainsKey(([string]$x.Name).ToLower())
            if (-not $cb.IsChecked) { $cb.Content = [string]$cb.Content + ' - schon da' }
            [void]$ui.MigImpPrograms.Children.Add($cb)
        }
    }
    $ui.MigImpProgTitle.Text = 'Programme ({0} automatisch installierbar)' -f $ui.MigImpPrograms.Children.Count
    $ui.MigImpManual.Text = if ($manual.Count) { $manual -join [Environment]::NewLine } else { '(keine)' }
    $ui.MigImport.Visibility = 'Visible'
    Update-MigPwImport $p
}
function Start-MigImport {
    $progs = @($ui.MigImpPrograms.Children | Where-Object { $_.IsChecked } | ForEach-Object { [string]$_.Tag })
    $wg = @($progs | Where-Object { $_ -like 'winget|*' } | ForEach-Object { $_.Substring(7) })
    $nin = @($progs | Where-Object { $_ -like 'Ninite|*' } | ForEach-Object { $_.Substring(7) })
    $job = @{ Package = $ui.MigPackage.Text.Trim()
              Folders = @($ui.MigImpFolders.Children | Where-Object { $_.IsChecked } | ForEach-Object { [string]$_.Tag })
              Settings = @($ui.MigImpSettings.Children | Where-Object { $_.IsChecked } | ForEach-Object { [string]$_.Tag })
              AppData = @($ui.MigImpAppData.Children | Where-Object { $_.IsChecked } | ForEach-Object { [string]$_.Tag }) }
    if ($nin.Count -and -not (Get-NinitePathGui)) { $nin = @() }
    $txt = '{0} Programme installieren (winget {1}, Ninite {2}), {3} Datenordner, {4} Einstellungen, {5} Programmeinstellungen übernehmen?' -f ($wg.Count + $nin.Count), $wg.Count, $nin.Count, $job.Folders.Count, $job.Settings.Count, $job.AppData.Count
    if (-not (Confirm-Ui $txt)) { return }
    $parts = @(); if ($nin.Count) { $parts += 'NiniteInstall' }; if ($wg.Count) { $parts += 'WingetInstall' }; $parts += 'MigrateImport'
    Start-Run -Parts $parts -Apps $nin -WingetApps $wg -Job $job
}

# ---------------------------------------------------------------- Tuning: Windows-Optimierungen
function Set-RegValue([string]$Path, [string]$Name, $Value, [string]$Type = 'DWord') {
    if (-not (Test-Path -LiteralPath $Path)) { New-Item -Path $Path -Force | Out-Null }
    New-ItemProperty -LiteralPath $Path -Name $Name -Value $Value -PropertyType $Type -Force | Out-Null
}
function Get-RegValue([string]$Path, [string]$Name) {
    try { return (Get-ItemProperty -LiteralPath $Path -Name $Name -ErrorAction Stop).$Name } catch { return $null }
}
function Remove-RegValue([string]$Path, [string]$Name) { Remove-ItemProperty -LiteralPath $Path -Name $Name -ErrorAction SilentlyContinue }

$Adv  = 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced'
$Cdm  = 'HKCU:\Software\Microsoft\Windows\CurrentVersion\ContentDeliveryManager'
$Srch = 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Search'
$PolW = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows'
$CdmValues = 'SubscribedContent-338388Enabled', 'SubscribedContent-338389Enabled', 'SubscribedContent-353694Enabled', 'SubscribedContent-353696Enabled',
             'SubscribedContent-310093Enabled', 'SystemPaneSuggestionsEnabled', 'SoftLandingEnabled', 'SilentInstalledAppsEnabled', 'RotatingLockScreenOverlayEnabled'
$PlanUltimate = 'e9a42b02-d5df-448d-aa00-03f14749eb61'; $PlanHigh = '8c5e7fda-e8bf-4a96-9a85-a6e23a8c635c'; $PlanBalanced = '381b4222-f694-41f0-9685-ff5bb260df2e'
function Get-ActivePlan { $o = (& powercfg.exe /getactivescheme) -join ' '; if ($o -match '([0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})') { $Matches[1] } }

# Presets: E = Empfohlen, L = Leistung, D = Datenschutz
$Tweaks = @(
    # ------------------------------------------------ Leistung
    @{ Id = 'Plan'; Group = 'Leistung'; P = 'L'; Title = 'Energiesparplan "Ultimative Leistung"'; Desc = 'Maximale Leistung ohne Stromspar-Verzögerungen. Ideal für Desktop-PCs, bei Laptops kostet es Akku.'
       Test = { [bool]((& powercfg.exe /list) | Where-Object { $_ -match '\*\s*$' -and $_ -match 'Ultimat|Höchstleistung|High performance' }) }
       On = { $l = (& powercfg.exe /list) -join "`n"; $g = $null
              foreach ($line in ($l -split "`n")) { if ($line -match '([0-9a-f\-]{36}).*\((.*Ultimat.*)\)') { $g = $Matches[1] } }
              if (-not $g) { $o = (& powercfg.exe -duplicatescheme $PlanUltimate) -join ' '; if ($o -match '([0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})') { $g = $Matches[1] } }
              if (-not $g) { $g = $PlanHigh }
              & powercfg.exe /setactive $g | Out-Null }
       Off = { & powercfg.exe /setactive $PlanBalanced | Out-Null } }
    @{ Id = 'VisualFX'; Group = 'Leistung'; P = 'L'; Title = 'Visuelle Effekte auf Leistung stellen'; Desc = 'Animationen und Schatten aus, Schriftglättung bleibt. Spürbar schneller auf älteren Geräten.'; Need = 'Abmelden'
       Test = { (Get-RegValue 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\VisualEffects' 'VisualFXSetting') -eq 2 }
       On = { Set-RegValue 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\VisualEffects' 'VisualFXSetting' 2; Set-RegValue 'HKCU:\Control Panel\Desktop' 'FontSmoothing' '2' 'String' }
       Off = { Set-RegValue 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\VisualEffects' 'VisualFXSetting' 0 } }
    @{ Id = 'StartDelay'; Group = 'Leistung'; P = 'EL'; Title = 'Autostart-Verzögerung entfernen'; Desc = 'Autostart-Programme starten nach der Anmeldung sofort statt verzögert.'
       Test = { (Get-RegValue 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Serialize' 'StartupDelayInMSec') -eq 0 }
       On = { Set-RegValue 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Serialize' 'StartupDelayInMSec' 0 }
       Off = { Remove-RegValue 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Serialize' 'StartupDelayInMSec' } }
    @{ Id = 'GameDVR'; Group = 'Leistung'; P = 'EL'; Title = 'Xbox-Hintergrundaufnahme (Game DVR) aus'; Desc = 'Verhindert ständige Aufnahme im Hintergrund - mehr FPS, weniger Last.'
       Test = { (Get-RegValue 'HKCU:\System\GameConfigStore' 'GameDVR_Enabled') -eq 0 }
       On = { Set-RegValue 'HKCU:\System\GameConfigStore' 'GameDVR_Enabled' 0; Set-RegValue 'HKCU:\Software\Microsoft\Windows\CurrentVersion\GameDVR' 'AppCaptureEnabled' 0 }
       Off = { Set-RegValue 'HKCU:\System\GameConfigStore' 'GameDVR_Enabled' 1; Set-RegValue 'HKCU:\Software\Microsoft\Windows\CurrentVersion\GameDVR' 'AppCaptureEnabled' 1 } }
    @{ Id = 'GameMode'; Group = 'Leistung'; P = 'L'; Title = 'Spielmodus aktivieren'; Desc = 'Windows priorisiert Spiele und hält Update-Neustarts währenddessen zurück.'
       Test = { (Get-RegValue 'HKCU:\Software\Microsoft\GameBar' 'AutoGameModeEnabled') -eq 1 }
       On = { Set-RegValue 'HKCU:\Software\Microsoft\GameBar' 'AutoGameModeEnabled' 1 }
       Off = { Set-RegValue 'HKCU:\Software\Microsoft\GameBar' 'AutoGameModeEnabled' 0 } }
    @{ Id = 'HAGS'; Group = 'Leistung'; P = 'L'; Title = 'Hardwarebeschleunigte GPU-Planung'; Desc = 'Die Grafikkarte verwaltet ihren Speicher selbst - weniger Latenz. Benötigt aktuelle Grafiktreiber.'; Need = 'Neustart'
       Test = { (Get-RegValue 'HKLM:\SYSTEM\CurrentControlSet\Control\GraphicsDrivers' 'HwSchMode') -eq 2 }
       On = { Set-RegValue 'HKLM:\SYSTEM\CurrentControlSet\Control\GraphicsDrivers' 'HwSchMode' 2 }
       Off = { Set-RegValue 'HKLM:\SYSTEM\CurrentControlSet\Control\GraphicsDrivers' 'HwSchMode' 1 } }
    @{ Id = 'BgApps'; Group = 'Leistung'; P = 'L'; Title = 'Store-Apps im Hintergrund stoppen'; Desc = 'Apps aus dem Store laufen nicht mehr heimlich weiter. Deren Live-Benachrichtigungen können entfallen.'
       Test = { (Get-RegValue 'HKCU:\Software\Microsoft\Windows\CurrentVersion\BackgroundAccessApplications' 'GlobalUserDisabled') -eq 1 }
       On = { Set-RegValue 'HKCU:\Software\Microsoft\Windows\CurrentVersion\BackgroundAccessApplications' 'GlobalUserDisabled' 1 }
       Off = { Set-RegValue 'HKCU:\Software\Microsoft\Windows\CurrentVersion\BackgroundAccessApplications' 'GlobalUserDisabled' 0 } }
    @{ Id = 'Hibernate'; Group = 'Leistung'; P = 'L'; Title = 'Ruhezustand abschalten (hiberfil.sys löschen)'; Desc = 'Gibt mehrere GB auf C: frei. Nur für Desktop-PCs - Laptops brauchen den Ruhezustand oft.'
       Test = { (Get-RegValue 'HKLM:\SYSTEM\CurrentControlSet\Control\Power' 'HibernateEnabled') -eq 0 }
       On = { & powercfg.exe /hibernate off | Out-Null }
       Off = { & powercfg.exe /hibernate on | Out-Null } }
    @{ Id = 'EdgeBg'; Group = 'Leistung'; P = 'EL'; Title = 'Edge nicht im Hintergrund laufen lassen'; Desc = 'Schaltet "Start-Boost" und Hintergrundbetrieb von Microsoft Edge ab.'
       Test = { (Get-RegValue 'HKLM:\SOFTWARE\Policies\Microsoft\Edge' 'StartupBoostEnabled') -eq 0 }
       On = { Set-RegValue 'HKLM:\SOFTWARE\Policies\Microsoft\Edge' 'StartupBoostEnabled' 0; Set-RegValue 'HKLM:\SOFTWARE\Policies\Microsoft\Edge' 'BackgroundModeEnabled' 0 }
       Off = { Remove-RegValue 'HKLM:\SOFTWARE\Policies\Microsoft\Edge' 'StartupBoostEnabled'; Remove-RegValue 'HKLM:\SOFTWARE\Policies\Microsoft\Edge' 'BackgroundModeEnabled' } }
    # ------------------------------------------------ Datenschutz
    @{ Id = 'Telemetry'; Group = 'Datenschutz'; P = 'ED'; Title = 'Diagnosedaten auf Minimum'; Desc = 'Nur noch erforderliche Diagnosedaten an Microsoft. Windows zeigt danach "Von Ihrer Organisation verwaltet".'
       Test = { (Get-RegValue "$PolW\DataCollection" 'AllowTelemetry') -eq 1 }
       On = { Set-RegValue "$PolW\DataCollection" 'AllowTelemetry' 1 }
       Off = { Remove-RegValue "$PolW\DataCollection" 'AllowTelemetry' } }
    @{ Id = 'AdId'; Group = 'Datenschutz'; P = 'ED'; Title = 'Werbe-ID abschalten'; Desc = 'Apps können kein Werbeprofil mehr über die Windows-Werbe-ID bilden.'
       Test = { (Get-RegValue 'HKCU:\Software\Microsoft\Windows\CurrentVersion\AdvertisingInfo' 'Enabled') -eq 0 }
       On = { Set-RegValue 'HKCU:\Software\Microsoft\Windows\CurrentVersion\AdvertisingInfo' 'Enabled' 0; Set-RegValue "$PolW\AdvertisingInfo" 'DisabledByGroupPolicy' 1 }
       Off = { Set-RegValue 'HKCU:\Software\Microsoft\Windows\CurrentVersion\AdvertisingInfo' 'Enabled' 1; Remove-RegValue "$PolW\AdvertisingInfo" 'DisabledByGroupPolicy' } }
    @{ Id = 'Tips'; Group = 'Datenschutz'; P = 'ED'; Title = 'Tipps, Vorschläge und Werbung aus'; Desc = 'Keine App-Vorschläge im Startmenü, keine automatisch installierten Werbe-Apps, keine Tipps auf dem Sperrbildschirm.'; Need = 'Explorer'
       Test = { (Get-RegValue $Cdm 'SilentInstalledAppsEnabled') -eq 0 -and (Get-RegValue $Cdm 'SystemPaneSuggestionsEnabled') -eq 0 }
       On = { foreach ($v in $CdmValues) { Set-RegValue $Cdm $v 0 }; Set-RegValue $Adv 'Start_IrisRecommendations' 0; Set-RegValue $Adv 'ShowSyncProviderNotifications' 0
              Set-RegValue 'HKCU:\Software\Microsoft\Windows\CurrentVersion\UserProfileEngagement' 'ScoobeSystemSettingEnabled' 0 }
       Off = { foreach ($v in $CdmValues) { Set-RegValue $Cdm $v 1 }; Set-RegValue $Adv 'Start_IrisRecommendations' 1; Set-RegValue $Adv 'ShowSyncProviderNotifications' 1
