    @{ Id = 'Activity'; Group = 'Datenschutz'; P = 'ED'; Title = 'Aktivitätsverlauf abschalten'; Desc = 'Windows speichert und synchronisiert nicht mehr, welche Programme und Dateien genutzt wurden.'
       Test = { (Get-RegValue "$PolW\System" 'PublishUserActivities') -eq 0 }
       On = { Set-RegValue "$PolW\System" 'PublishUserActivities' 0; Set-RegValue "$PolW\System" 'UploadUserActivities' 0 }
       Off = { Remove-RegValue "$PolW\System" 'PublishUserActivities'; Remove-RegValue "$PolW\System" 'UploadUserActivities' } }
