    @{ Id = 'StorageSense'; Group = 'System'; P = 'E'; Title = 'Speicheroptimierung aktivieren'; Desc = 'Windows leert bei Platzmangel automatisch Papierkorb und temporäre Dateien.'
       Test = { (Get-RegValue 'HKCU:\Software\Microsoft\Windows\CurrentVersion\StorageSense\Parameters\StoragePolicy' '01') -eq 1 }
       On = { Set-RegValue 'HKCU:\Software\Microsoft\Windows\CurrentVersion\StorageSense\Parameters\StoragePolicy' '01' 1 }
       Off = { Set-RegValue 'HKCU:\Software\Microsoft\Windows\CurrentVersion\StorageSense\Parameters\StoragePolicy' '01' 0 } }
    @{ Id = 'LongPaths'; Group = 'System'; P = 'E'; Title = 'Lange Dateipfade erlauben'; Desc = 'Hebt die alte 260-Zeichen-Grenze auf - hilft bei tief verschachtelten Ordnern und Entwicklung.'
       Test = { (Get-RegValue 'HKLM:\SYSTEM\CurrentControlSet\Control\FileSystem' 'LongPathsEnabled') -eq 1 }
       On = { Set-RegValue 'HKLM:\SYSTEM\CurrentControlSet\Control\FileSystem' 'LongPathsEnabled' 1 }
       Off = { Set-RegValue 'HKLM:\SYSTEM\CurrentControlSet\Control\FileSystem' 'LongPathsEnabled' 0 } }
    @{ Id = 'NumLock'; Group = 'System'; P = 'E'; Title = 'NumLock beim Start einschalten'; Desc = 'Der Ziffernblock ist beim Anmeldebildschirm sofort aktiv.'
       Test = { [string](Get-RegValue 'Registry::HKEY_USERS\.DEFAULT\Control Panel\Keyboard' 'InitialKeyboardIndicators') -eq '2' }
       On = { Set-RegValue 'Registry::HKEY_USERS\.DEFAULT\Control Panel\Keyboard' 'InitialKeyboardIndicators' '2' 'String'; Set-RegValue 'HKCU:\Control Panel\Keyboard' 'InitialKeyboardIndicators' '2' 'String' }
       Off = { Set-RegValue 'Registry::HKEY_USERS\.DEFAULT\Control Panel\Keyboard' 'InitialKeyboardIndicators' '0' 'String'; Set-RegValue 'HKCU:\Control Panel\Keyboard' 'InitialKeyboardIndicators' '0' 'String' } }
    @{ Id = 'Autoplay'; Group = 'System'; P = 'E'; Title = 'Automatische Wiedergabe (AutoPlay) aus'; Desc = 'USB-Sticks und DVDs starten nichts mehr automatisch - mehr Sicherheit.'
       Test = { (Get-RegValue 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\AutoplayHandlers' 'DisableAutoplay') -eq 1 }
       On = { Set-RegValue 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\AutoplayHandlers' 'DisableAutoplay' 1 }
       Off = { Set-RegValue 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\AutoplayHandlers' 'DisableAutoplay' 0 } }
)

$script:TweakRows = [System.Collections.Generic.List[object]]::new()
function Build-Tweaks {
    $ui.TweakPanel.Children.Clear(); $script:TweakRows.Clear()
    foreach ($grp in ($Tweaks | ForEach-Object { $_.Group } | Select-Object -Unique)) {
        $card = New-Object Windows.Controls.Border
        $card.Background = (New-UiBrush 'White'); $card.CornerRadius = '10'; $card.Padding = '18,12'; $card.Margin = '0,0,0,14'
        $card.BorderBrush = (New-UiBrush '#E2E7F0'); $card.BorderThickness = '1'
        $sp = New-Object Windows.Controls.StackPanel
        $h = New-Object Windows.Controls.TextBlock; $h.Text = $grp; $h.FontSize = 15; $h.FontWeight = 'SemiBold'; $h.Foreground = (New-UiBrush '#1F2A44'); $h.Margin = '0,0,0,6'
        [void]$sp.Children.Add($h)
        foreach ($t in ($Tweaks | Where-Object { $_.Group -eq $grp })) {
            $g = New-Object Windows.Controls.Grid; $g.Margin = '0,5'
            $c1 = New-Object Windows.Controls.ColumnDefinition; $c2 = New-Object Windows.Controls.ColumnDefinition; $c2.Width = 'Auto'
            [void]$g.ColumnDefinitions.Add($c1); [void]$g.ColumnDefinitions.Add($c2)
            $st = New-Object Windows.Controls.StackPanel
            $cb = New-Object Windows.Controls.CheckBox; $cb.Content = $t.Title; $cb.FontWeight = 'SemiBold'; $cb.Foreground = (New-UiBrush '#1F2A44')
            $cb.Add_Click({ Update-TweakInfo })
            $ds = New-Object Windows.Controls.TextBlock; $ds.Text = $t.Desc + $(if ($t.Need) { '  (wirkt nach: ' + $t.Need + ')' } else { '' })
            $ds.FontSize = 12; $ds.Foreground = (New-UiBrush '#6B7890'); $ds.TextWrapping = 'Wrap'; $ds.Margin = '21,2,0,0'
            [void]$st.Children.Add($cb); [void]$st.Children.Add($ds)
            $bd = New-Object Windows.Controls.Border; $bd.CornerRadius = '4'; $bd.Padding = '8,2'; $bd.Margin = '12,0,0,0'; $bd.VerticalAlignment = 'Top'
            $bt = New-Object Windows.Controls.TextBlock; $bt.FontSize = 11; $bd.Child = $bt
            [Windows.Controls.Grid]::SetColumn($bd, 1)
            [void]$g.Children.Add($st); [void]$g.Children.Add($bd)
            [void]$sp.Children.Add($g)
            $script:TweakRows.Add([pscustomobject]@{ T = $t; Check = $cb; Badge = $bd; BadgeText = $bt; Current = $false })
        }
        $card.Child = $sp
        [void]$ui.TweakPanel.Children.Add($card)
    }
    Update-TweakState
}
function Update-TweakState {
    foreach ($r in $script:TweakRows) {
        $on = $false
        try { $on = [bool](& $r.T.Test) } catch { }
        $r.Current = $on
        $r.Check.IsChecked = $on
        $r.BadgeText.Text = if ($on) { 'aktiv' } else { 'Windows-Standard' }
        $r.Badge.Background = if ($on) { New-UiBrush '#DCFCE7' } else { New-UiBrush '#EEF2F8' }
        $r.BadgeText.Foreground = if ($on) { New-UiBrush '#166534' } else { New-UiBrush '#6B7890' }
    }
    Update-TweakInfo
}
function Update-TweakInfo {
    $ch = @($script:TweakRows | Where-Object { [bool]$_.Check.IsChecked -ne $_.Current })
    $act = @($script:TweakRows | Where-Object { $_.Current }).Count
    $ui.TweakInfo.Text = if ($ch.Count) { '{0} Änderung(en) ausstehend - mit "Übernehmen" anwenden' -f $ch.Count } else { '{0} von {1} Optimierungen aktiv' -f $act, $script:TweakRows.Count }
    $ui.BtnTweakApply.IsEnabled = [bool]$ch.Count
}
function Set-TweakPreset([string]$Code) {
    foreach ($r in $script:TweakRows) {
        $r.Check.IsChecked = if ($Code -eq 'X') { $false } elseif ($Code -eq 'C') { $r.Current } else { $r.Current -or ([string]$r.T.P).Contains($Code) }
    }
    Update-TweakInfo
}
function Invoke-TweakApply {
    $ch = @($script:TweakRows | Where-Object { [bool]$_.Check.IsChecked -ne $_.Current })
    if (-not $ch.Count) { return }
    $list = ($ch | ForEach-Object { '{0} {1}' -f $(if ($_.Check.IsChecked) { '[an] ' } else { '[aus]' }), $_.T.Title }) -join "`n"
    if ([Windows.MessageBox]::Show((T (("Folgende Änderungen übernehmen?`n`n{0}`n`nVorher wird ein Wiederherstellungspunkt erstellt." -f $list))), (T ('PC-Tools - Tuning')), 'YesNo', 'Question') -ne 'Yes') { return }
    $window.Cursor = 'Wait'
    $ui.StatusText.Text = 'Wiederherstellungspunkt wird erstellt ...'
    try {
        New-ItemProperty -Path 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\SystemRestore' -Name 'SystemRestorePointCreationFrequency' -Value 0 -PropertyType DWord -Force | Out-Null
        Checkpoint-Computer -Description 'PC-Tools Tuning' -RestorePointType MODIFY_SETTINGS -ErrorAction Stop
    } catch { }
    $log = Join-Path (Join-Path $DataDir 'Logs') ('Tuning_{0:yyyyMMdd_HHmmss}.log' -f (Get-Date))
    New-Item (Split-Path $log) -ItemType Directory -Force | Out-Null
    $needs = @{}; $fail = 0
    foreach ($r in $ch) {
        $on = [bool]$r.Check.IsChecked
        try { if ($on) { & $r.T.On } else { & $r.T.Off }; $res = 'OK'; if ($r.T.Need) { $needs[$r.T.Need] = $true } }
        catch { $res = 'FEHLER: ' + $_.Exception.Message; $fail++ }
        Add-Content -LiteralPath $log -Value ('{0:HH:mm:ss} {1} {2} - {3}' -f (Get-Date), $(if ($on) { 'AN ' } else { 'AUS' }), $r.T.Title, $res) -Encoding UTF8
    }
    $window.Cursor = $null
    Update-TweakState
    $msg = '{0} Änderung(en) übernommen{1}.' -f ($ch.Count - $fail), $(if ($fail) { ", $fail fehlgeschlagen (siehe Protokoll)" } else { '' })
    $ui.StatusText.Text = $msg
    if ($needs['Explorer']) {
        if ([Windows.MessageBox]::Show((T ($msg + "`n`nEinige Änderungen werden erst nach einem Neustart des Explorers sichtbar. Jetzt neu starten? (Offene Explorer-Fenster werden geschlossen.)")), (T ('PC-Tools')), 'YesNo', 'Question') -eq 'Yes') { Restart-Explorer }
    }
    if ($needs['Neustart'] -or $needs['Abmelden']) {
        [Windows.MessageBox]::Show((T ('Einige Änderungen wirken erst nach ' + $(if ($needs['Neustart']) { 'einem Neustart' } else { 'dem nächsten Abmelden' }) + '.')), (T ('PC-Tools')), 'OK', 'Information') | Out-Null
    }
}
# ---------------------------------------------------------------- Alle Optimierungen: jede Tuning-Einstellung mit einem Klick an
function Invoke-AllTweaks {
    $todo = @(foreach ($t in $Tweaks) { $on = $false; try { $on = [bool](& $t.Test) } catch { }; if (-not $on) { $t } })
    if (-not $todo.Count) { [Windows.MessageBox]::Show((T (('Alle {0} Optimierungen sind bereits aktiv.' -f $Tweaks.Count))), (T ('PC-Tools - Alle Optimierungen')), 'OK', 'Information') | Out-Null; return }
    $q = "Alle Optimierungen einschalten?`n`n{0} von {1} Einstellungen werden gesetzt:`n{2}`n`nVorher wird ein Wiederherstellungspunkt erstellt. Rückgängig: Seite Tuning (Vorgabe ""Windows-Standard"")." -f $todo.Count, $Tweaks.Count, (($todo | ForEach-Object { '  - ' + $_.Title }) -join "`n")
    if (-not (Confirm-Ui $q)) { return }
    $window.Cursor = 'Wait'; $ui.StatusText.Text = 'Alle Optimierungen: Wiederherstellungspunkt ...'
    try { New-ItemProperty -Path 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\SystemRestore' -Name 'SystemRestorePointCreationFrequency' -Value 0 -PropertyType DWord -Force | Out-Null; Checkpoint-Computer -Description 'PC-Tools Alle Optimierungen' -RestorePointType MODIFY_SETTINGS -ErrorAction Stop } catch { }
    $log = Join-Path (Join-Path $DataDir 'Logs') ('Tuning_{0:yyyyMMdd_HHmmss}.log' -f (Get-Date))
    New-Item (Split-Path $log) -ItemType Directory -Force | Out-Null
    $needs = @{}; $fail = [System.Collections.Generic.List[string]]::new()
    foreach ($t in $todo) {
        $ui.StatusText.Text = 'Alle Optimierungen: ' + $t.Title
        try { & $t.On; $res = 'OK'; if ($t.Need) { $needs[$t.Need] = $true } } catch { $res = 'FEHLER: ' + $_.Exception.Message; $fail.Add($t.Title) }
        try { Add-Content -LiteralPath $log -Value ('{0:HH:mm:ss} AN  {1} - {2}' -f (Get-Date), $t.Title, $res) -Encoding UTF8 } catch { }
    }
    $window.Cursor = $null
    try { if ($script:TweakRows -and $script:TweakRows.Count) { Update-TweakState } } catch { }
    $msg = '{0} Optimierung(en) eingeschaltet{1}.' -f ($todo.Count - $fail.Count), $(if ($fail.Count) { ', nicht geklappt: ' + ($fail -join ', ') } else { '' })
    $ui.StatusText.Text = 'Alle Optimierungen: ' + $msg
    if ($needs['Explorer']) {
        if ([Windows.MessageBox]::Show((T ($msg + "`n`nEinige Änderungen werden erst nach einem Neustart des Explorers sichtbar. Jetzt neu starten? (Offene Explorer-Fenster werden geschlossen.)")), (T ('PC-Tools')), 'YesNo', 'Question') -eq 'Yes') { Restart-Explorer }
    } else { [Windows.MessageBox]::Show((T ($msg)), (T ('PC-Tools - Alle Optimierungen')), 'OK', 'Information') | Out-Null }
    if ($needs['Neustart'] -or $needs['Abmelden']) { [Windows.MessageBox]::Show((T ('Einige Änderungen wirken erst nach ' + $(if ($needs['Neustart']) { 'einem Neustart' } else { 'dem nächsten Abmelden' }) + '.')), (T ('PC-Tools')), 'OK', 'Information') | Out-Null }
}
# ---------------------------------------------------------------- Mega-Leistung: ein Klick auf maximale Leistung
function Enable-UltimatePerfPlan {
    $guid = 'e9a42b02-d5df-448d-aa00-03f14749eb61'
    try {
        $have = (& powercfg.exe /list) -join "`n"
        if ($have -notmatch $guid) { $o = (& powercfg.exe /duplicatescheme $guid 2>&1) -join ' '; if ($o -match '([0-9a-f\-]{36})') { $guid = $Matches[1] } }
        $null = & powercfg.exe /setactive $guid 2>&1
        return ($LASTEXITCODE -eq 0)
    } catch { return $false }
}
function Invoke-MegaPerf {
    if (-not (Confirm-Ui ("Diesen PC auf MAXIMALE LEISTUNG trimmen?`n`n- Energieplan `"Ultimative Leistung`" einschalten`n- Visuelle Effekte/Animationen aus, Leistungs-Tweaks setzen`n- Energiesparen von CPU/USB abschalten`n- Alle unnötigen und optionalen Autostart-Programme deaktivieren (Sicherheit, Treiber-Helfer und PC-Tools bleiben)`n`nVorher wird ein Wiederherstellungspunkt erstellt. Gut für Desktop-PCs; auf Notebooks sinkt die Akkulaufzeit.") 'Warning')) { return }
    $window.Cursor = 'Wait'; $ui.StatusText.Text = 'Mega-Leistung wird eingerichtet - Wiederherstellungspunkt ...'
    try { New-ItemProperty -Path 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\SystemRestore' -Name 'SystemRestorePointCreationFrequency' -Value 0 -PropertyType DWord -Force | Out-Null; Checkpoint-Computer -Description 'PC-Tools Mega-Leistung' -RestorePointType MODIFY_SETTINGS -ErrorAction Stop } catch { }
    $done = [System.Collections.Generic.List[string]]::new()
    # 1. Ultimative Leistung
    if (Enable-UltimatePerfPlan) { $done.Add('Energieplan "Ultimative Leistung" aktiv') } else { $done.Add('Energieplan konnte nicht gesetzt werden') }
    # 2. Leistungs-Tweaks (alle mit Preset-Code L), ohne Rückfrage
    $tw = 0; try { foreach ($r in @($script:TweakRows | Where-Object { ([string]$_.T.P).Contains('L') -and -not $_.Current })) { try { & $r.T.On; $tw++ } catch { } } } catch { }
    if ($tw) { $done.Add(('{0} Leistungs-Einstellungen gesetzt (Effekte/Animationen aus)' -f $tw)) }
    # 3. Energiesparen hart aus (CPU-Drosselung, USB selektives Energiesparen, Power Throttling)
    try { Set-PReg 'HKLM:\SYSTEM\CurrentControlSet\Control\Power\PowerThrottling' 'PowerThrottlingOff' 1; $done.Add('Leistungsdrosselung (Power Throttling) aus') } catch { }
    try {
        $pl = [regex]::Match((& powercfg.exe /getactivescheme), '[0-9a-fA-F]{8}-[0-9a-fA-F\-]{27}').Value
        if ($pl) {
            foreach ($sw in '/setacvalueindex', '/setdcvalueindex') {
                $null = & powercfg.exe $sw $pl SUB_PROCESSOR PROCTHROTTLEMIN 100 2>&1
                $null = & powercfg.exe $sw $pl 2a737441-1930-4402-8d77-b2bebba308a3 48e6b7a6-50f5-4782-a5d4-53bb8f07e226 0 2>&1
            }
            $null = & powercfg.exe /setactive $pl 2>&1
            $done.Add('Prozessor-Minimum 100 %, USB-Energiesparen aus')
        }
    } catch { }
    # 4. Unnötige und optionale Autostart-Programme deaktivieren (Notwendige und angepinnte bleiben)
    $off = 0
    try {
        foreach ($e in @(Get-AutostartEntries $true | Where-Object { $_ -and $_.Enabled -and -not $_.Keep -and $_.Category -in 'Überflüssig', 'Optional' })) {
            try { Set-AutostartEntry $e $false; $off++ } catch { }
        }
    } catch { }
    if ($off) { $done.Add(('{0} unnötige Autostart-Programme deaktiviert' -f $off)) }
    $window.Cursor = $null
    try { if ($script:TweakRows) { Update-TweakState } } catch { }
    try { Build-Autostart } catch { }
    $ui.StatusText.Text = 'Mega-Leistung aktiv: ' + ($done -join ' · ')
    [Windows.MessageBox]::Show((T (("Fertig - der PC läuft jetzt auf maximale Leistung:`n`n- {0}`n`nRückgängig: Seite Tuning (Vorgabe ""Windows-Standard"") bzw. Autostart-Manager, oder der erstellte Wiederherstellungspunkt. Einige Effekte wirken nach einem Neustart." -f ($done -join "`n- ")))), (T ('PC-Tools - Mega-Leistung')), 'OK', 'Information') | Out-Null
}
# ---------------------------------------------------------------- Tuning: Autostart-Manager
$AutoSources = @(
    @{ Label = 'Benutzer';        Key = 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Run';                 Appr = 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\StartupApproved\Run' }
    @{ Label = 'Alle Benutzer';   Key = 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Run';                 Appr = 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Explorer\StartupApproved\Run' }
    @{ Label = 'Alle (32-Bit)';   Key = 'HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Run';     Appr = 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Explorer\StartupApproved\Run32' }
)
# Notwendig: Sicherheit, Treiber-Helfer (Ton, Touchpad, Tasten, Stift), PC-Tools selbst
$AutoNeeded = 'SecurityHealth|Windows ?Defender|MsMpEng|Windows-Sicherheit|RtkAud|Realtek|RAVCpl|RAVBg|Waves|MaxxAudio|Nahimic|Dolby|SynTP|Synaptics|\bETD|ELAN|Alps|Precision ?Touch|HotKey|HPHotkey|HP ?Quick|LenovoUtility|Lenovo.*(Hotkey|Vantage ?Service)|Fn ?Key|Wacom|Pen ?Tablet|Intel.*(Rapid|RST|iaStor)|iaStor|Bluetooth|btvStack|PCPflege|PC-Tools|avast|\bavg\b|avira|bitdefender|kaspersky|\beset\b|egui|ekrn|norton|malwarebytes|mbam|sophos|panda|mcafee|trend ?micro|g ?data|f-secure|webroot'
# Überflüssig beim Start: Updater, Launcher, Chat, Store-Helfer - starten bei Bedarf von selbst
$AutoUseless = 'update|updater|updtr|\bhelper\b|iTunesHelper|jusched|Java|Adobe|AcroTray|CCXProcess|Creative ?Cloud|Spotify|Steam|Discord|Epic ?Games|EADesktop|\bOrigin\b|Battle\.net|Ubisoft|GOG ?Galaxy|Teams|Skype|Zoom|Webex|Slack|WhatsApp|Telegram|Signal|Messenger|EdgeAutoLaunch|MicrosoftEdge|Opera|Brave|GoogleChrome|Chrome|Firefox|CCleaner|uTorrent|BitTorrent|qBittorrent|Cortana|Xbox|GameBar|Dropbox|Google ?Drive|iCloud|Amazon|Evernote|Grammarly|Razer ?Synapse|iCUE|Corsair|SteelSeries|Wallpaper ?Engine|Overwolf|Kindle|Deezer|Tidal|Line\b|Viber|Canva|Notion|Figma|Loom|Clipchamp|Phone ?Link|YourPhone|Duet|AnyDesk|TeamViewer|Rust ?Desk'
$AutoKeepFile = Join-Path $DataDir 'autostart-behalten.json'
$AutoUndoFile = Join-Path $DataDir 'autostart-rueckgaengig.json'
function Get-AutoKeep { try { $j = Get-Content -LiteralPath $AutoKeepFile -Raw -Encoding UTF8 -ErrorAction Stop | ConvertFrom-Json; @($j | ForEach-Object { [string]$_ }) } catch { @() } }
function Save-AutoKeep([string[]]$Names) { ConvertTo-Json -InputObject @($Names | Sort-Object -Unique) | Set-Content -LiteralPath $AutoKeepFile -Encoding UTF8 }
function Get-AutoExePath([string]$Cmd) {
    $c = [Environment]::ExpandEnvironmentVariables($Cmd.Trim())
    if ($c -match '^"([^"]+)"') { return $Matches[1] }
    if ($c -match '^(.+?\.(exe|cmd|bat|com|lnk|vbs|ps1|url))(\s|$)') { return $Matches[1] }
    return ($c -split ' ')[0]
}
function Get-AutostartEntries([bool]$Tasks = $true) {
    $script:AutoErr = @()
    $list = [System.Collections.Generic.List[object]]::new()
    foreach ($s in $AutoSources) {
        $p = Get-ItemProperty -LiteralPath $s.Key -ErrorAction SilentlyContinue
        if (-not $p) { continue }
        foreach ($prop in $p.PSObject.Properties) {
            if ($prop.Name -like 'PS*') { continue }
            $list.Add([pscustomobject]@{ Name = $prop.Name; Cmd = [string]$prop.Value; Source = $s.Label; Kind = 'Reg'; Appr = $s.Appr; Key = $s.Key; Enabled = $true })
        }
    }
    foreach ($f in @(@{ Label = 'Autostart-Ordner'; Path = [Environment]::GetFolderPath('Startup'); Appr = 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\StartupApproved\StartupFolder' },
                     @{ Label = 'Autostart (alle)'; Path = [Environment]::GetFolderPath('CommonStartup'); Appr = 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Explorer\StartupApproved\StartupFolder' })) {
        if (-not $f.Path -or -not (Test-Path -LiteralPath $f.Path)) { continue }
        Get-ChildItem -LiteralPath $f.Path -File -ErrorAction SilentlyContinue | Where-Object { $_.Name -ne 'desktop.ini' } | ForEach-Object {
            $cmd = $_.FullName
            if ($_.Extension -eq '.lnk') { try { $t = (New-Object -ComObject WScript.Shell).CreateShortcut($_.FullName).TargetPath; if ($t) { $cmd = $t } } catch { } }
            $list.Add([pscustomobject]@{ Name = $_.Name; Cmd = $cmd; Source = $f.Label; Kind = 'Folder'; Appr = $f.Appr; Key = $_.FullName; Enabled = $true })
        }
    }
    foreach ($e in $list) {
        # StartupApproved: erstes Byte gerade = an, ungerade = aus (Funktionsrückgabe würde das Byte-Array auflösen, daher direkt lesen)
        try { $b = @(Get-RegValue $e.Appr $e.Name); $e.Enabled = if ($b.Count -ge 1 -and $null -ne $b[0]) { ([int]$b[0] % 2) -eq 0 } else { $true } } catch { }
    }
    # Store-Apps mit Startaufgabe (z.B. Teams, Spotify, Terminal)
    try {
    $sad = 'HKCU:\Software\Classes\Local Settings\Software\Microsoft\Windows\CurrentVersion\AppModel\SystemAppData'
    foreach ($k in @(Get-ChildItem -LiteralPath $sad -ErrorAction SilentlyContinue)) {
        foreach ($t in @(Get-ChildItem -LiteralPath $k.PSPath -ErrorAction SilentlyContinue)) {
            $st = (Get-ItemProperty -LiteralPath $t.PSPath -Name State -ErrorAction SilentlyContinue).State
            if ($null -eq $st) { continue }
            $pkg = ($k.PSChildName -split '_')[0]
            $list.Add([pscustomobject]@{ Name = ('{0} ({1})' -f ($pkg -replace '^[^.]+\.', ''), $t.PSChildName); Cmd = $k.PSChildName; Source = 'Store-App'; Kind = 'App'; Appr = ''; Key = $t.PSPath; Enabled = ($st -in 2, 4) })
        }
    }
    } catch { $script:AutoErr += 'Store-Apps: ' + $_.Exception.Message }
    # Aufgaben, die bei der Anmeldung starten (ohne Windows-eigene und PC-Tools)
    if ($Tasks) { try {
        foreach ($t in @(Get-ScheduledTask -ErrorAction SilentlyContinue | Where-Object { $_.TaskPath -notlike '\Microsoft\*' -and $_.TaskName -notlike 'PC-Pflege*' -and ($_.Triggers | Where-Object { $_.CimClass.CimClassName -eq 'MSFT_TaskLogonTrigger' }) })) {
            $act = @($t.Actions | Where-Object { $_.Execute } | Select-Object -First 1)
            $cmd = if ($act) { ('{0} {1}' -f $act[0].Execute, $act[0].Arguments).Trim() } else { '' }
            $list.Add([pscustomobject]@{ Name = $t.TaskName; Cmd = $cmd; Source = 'Aufgabe bei Anmeldung'; Kind = 'Task'; Appr = ''; Key = $t.TaskPath; Enabled = ([string]$t.State -ne 'Disabled') })
        }
    } catch { $script:AutoErr += 'Aufgaben: ' + $_.Exception.Message } }
    $keep = Get-AutoKeep
    foreach ($e in $list) {
        $exists = $true; $pub = ''
        try {
            $exe = Get-AutoExePath $e.Cmd
            if ($e.Kind -ne 'App' -and $exe -and $exe -notmatch '[<>|*?]') {
                $full = $exe.Trim('"').Trim()
                if ($full -notmatch '^[A-Za-z]:\\|^\\\\') { $w = Get-Command $full -CommandType Application -ErrorAction SilentlyContinue | Select-Object -First 1; if ($w) { $full = $w.Source } else { $full = $null } }
                if ($full -and (Test-Path -LiteralPath $full -ErrorAction SilentlyContinue)) { try { $pub = [string][Diagnostics.FileVersionInfo]::GetVersionInfo($full).CompanyName } catch { } }
                elseif ($full) { $exists = $false }
            }
        } catch { }
        $txt = '{0} {1} {2}' -f $e.Name, $e.Cmd, $pub
        $cat = if ($txt -match $AutoNeeded) { 'Notwendig' } elseif ($txt -match $AutoUseless) { 'Überflüssig' } else { 'Optional' }
        $e | Add-Member -NotePropertyName Publisher -NotePropertyValue ([string]$pub) -Force
        $e | Add-Member -NotePropertyName Exists -NotePropertyValue $exists -Force
        $e | Add-Member -NotePropertyName Category -NotePropertyValue $cat -Force
        $e | Add-Member -NotePropertyName Keep -NotePropertyValue ($keep -contains $e.Name) -Force
    }
    return , $list
}
function Set-AutostartEntry($Entry, [bool]$Enable) {
    switch ($Entry.Kind) {
        'Task' { if ($Enable) { $null = Enable-ScheduledTask -TaskName $Entry.Name -TaskPath $Entry.Key -ErrorAction Stop } else { $null = Disable-ScheduledTask -TaskName $Entry.Name -TaskPath $Entry.Key -ErrorAction Stop } }
        'App'  { Set-ItemProperty -LiteralPath $Entry.Key -Name State -Value $(if ($Enable) { 2 } else { 1 }) -Type DWord -ErrorAction Stop }
        default {
            $bytes = New-Object byte[] 12
            if ($Enable) { $bytes[0] = 2 } else { $bytes[0] = 3; [BitConverter]::GetBytes((Get-Date).ToFileTime()).CopyTo($bytes, 4) }
            Set-RegValue $Entry.Appr $Entry.Name $bytes 'Binary'
        }
    }
    $Entry.Enabled = $Enable
}
function New-AutoBadge([string]$Text, [string]$Bg, [string]$Fg) {
    $b = New-Object Windows.Controls.Border; $b.CornerRadius = '4'; $b.Padding = '7,1'; $b.Margin = '8,0,0,0'; $b.VerticalAlignment = 'Center'; $b.Background = New-UiBrush $Bg
    $t = New-Object Windows.Controls.TextBlock; $t.Text = $Text; $t.FontSize = 11; $t.FontWeight = 'SemiBold'; $t.Foreground = New-UiBrush $Fg; $b.Child = $t
    return $b
}
function Build-Autostart {
    try { $script:AutoEntries = @(Get-AutostartEntries ([bool]$ui.AutoShowTasks.IsChecked) | ForEach-Object { $_ } | Where-Object { $_ -and $_.Name }) }
    catch { $script:AutoEntries = @(); $script:AutoErr = @('Einlesen: ' + $_.Exception.Message + ' (Zeile ' + $_.InvocationInfo.ScriptLineNumber + ')') }
    Show-Autostart
}
function Show-Autostart {
    $ui.AutoList.Children.Clear()
    $all = @($script:AutoEntries | Where-Object { $_ })
    $f = [math]::Max(0, $ui.AutoFilter.SelectedIndex)
    $order = @{ 'Notwendig' = 0; 'Optional' = 1; 'Überflüssig' = 2 }
    foreach ($e in ($all | Sort-Object @{ e = { $order[$_.Category] } }, Name)) {
        $show = switch ($f) { 1 { [bool]$e.Enabled } 2 { -not $e.Enabled } 3 { $e.Category -eq 'Überflüssig' } 4 { $e.Category -eq 'Notwendig' } 5 { -not $e.Exists } default { $true } }
        if (-not $show) { continue }
        $row = New-Object Windows.Controls.Border; $row.BorderBrush = New-UiBrush '#EEF2F8'; $row.BorderThickness = '0,0,0,1'; $row.Padding = '0,6'
        $g = New-Object Windows.Controls.Grid
        foreach ($w in -1, 170, 40) { $c = New-Object Windows.Controls.ColumnDefinition; if ($w -gt 0) { $c.Width = $w }; [void]$g.ColumnDefinitions.Add($c) }
        $sp = New-Object Windows.Controls.StackPanel
        $head = New-Object Windows.Controls.StackPanel; $head.Orientation = 'Horizontal'
        $cb = New-Object Windows.Controls.CheckBox; $cb.Content = $e.Name; $cb.IsChecked = $e.Enabled; $cb.FontWeight = 'SemiBold'; $cb.Tag = $e
        $cb.Add_Click({ param($sender, $ev)
            try { Set-AutostartEntry $sender.Tag ([bool]$sender.IsChecked); $ui.StatusText.Text = ('Autostart "{0}" {1}' -f $sender.Tag.Name, $(if ($sender.IsChecked) { 'aktiviert' } else { 'deaktiviert' })); Update-AutoSummary }
            catch { [Windows.MessageBox]::Show((T ('Nicht möglich: ' + $_.Exception.Message)), (T ('PC-Tools'))) | Out-Null; $sender.IsChecked = -not $sender.IsChecked } })
        [void]$head.Children.Add($cb)
        switch ($e.Category) {
            'Notwendig'   { [void]$head.Children.Add((New-AutoBadge 'notwendig' '#DCFCE7' '#15803D')) }
            'Überflüssig' { [void]$head.Children.Add((New-AutoBadge 'überflüssig' '#FFEDD5' '#C2410C')) }
            default       { [void]$head.Children.Add((New-AutoBadge 'optional' '#E3E8F2' '#475569')) }
        }
        if (-not $e.Exists) { [void]$head.Children.Add((New-AutoBadge 'Datei fehlt' '#FFEDD5' '#C81E1E')) }
        $cm = New-Object Windows.Controls.TextBlock; $cm.Text = $(if ($e.Publisher) { $e.Publisher + '  ·  ' } else { '' }) + $e.Cmd; $cm.FontSize = 12; $cm.Foreground = (New-UiBrush '#475569'); $cm.TextTrimming = 'CharacterEllipsis'; $cm.Margin = '21,2,0,0'; $cm.ToolTip = $e.Cmd
        [void]$sp.Children.Add($head); [void]$sp.Children.Add($cm)
        $src = New-Object Windows.Controls.TextBlock; $src.Text = $e.Source; $src.FontSize = 12; $src.Foreground = (New-UiBrush '#475569'); $src.HorizontalAlignment = 'Right'; $src.VerticalAlignment = 'Center'
        [Windows.Controls.Grid]::SetColumn($src, 1)
        if (-not $script:PinTemplate) { $script:PinTemplate = [Windows.Markup.XamlReader]::Parse('<ControlTemplate xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" TargetType="Button"><Border Background="Transparent"><ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center"/></Border></ControlTemplate>') }
        $pin = New-Object Windows.Controls.Button; $pin.Template = $script:PinTemplate; $pin.Content = [string][char]0xE718; $pin.FontFamily = 'Segoe MDL2 Assets'; $pin.FontSize = 15; $pin.Width = 30; $pin.Height = 28; $pin.Margin = '0'; $pin.Padding = '0'; $pin.HorizontalAlignment = 'Right'; $pin.VerticalAlignment = 'Center'
        $pin.Cursor = 'Hand'; $pin.Tag = $e
        $pin.Foreground = New-UiBrush $(if ($e.Keep) { '#2D7FF9' } else { '#8A97B3' })
        $pin.ToolTip = 'Immer behalten - bleibt bei "Nur das Nötige" und "Alle aus" an'
        $pin.Add_Click({ param($sender, $ev)
            $en = $sender.Tag; $en.Keep = -not $en.Keep
            $sender.Foreground = New-UiBrush $(if ($en.Keep) { '#2D7FF9' } else { '#8A97B3' })
            Save-AutoKeep @($script:AutoEntries | Where-Object Keep | ForEach-Object { $_.Name }) })
        [Windows.Controls.Grid]::SetColumn($pin, 2)
        [void]$g.Children.Add($sp); [void]$g.Children.Add($src); [void]$g.Children.Add($pin)
        $row.Child = $g
        [void]$ui.AutoList.Children.Add($row)
    }
    Update-AutoSummary
}
function Update-AutoSummary {
    $all = @($script:AutoEntries | Where-Object { $_ })
    $ui.AutoSummary.Text = '{0} von {1} aktiv  ·  {2} überflüssig aktiv  ·  {3} kaputt' -f @($all | Where-Object { $_.Enabled }).Count, $all.Count, @($all | Where-Object { $_.Enabled -and $_.Category -eq 'Überflüssig' }).Count, @($all | Where-Object { -not $_.Exists }).Count
    if ($script:AutoErr) { $ui.AutoSummary.Text += '   (Hinweis: ' + ($script:AutoErr -join '; ') + ')' }
}
function Set-AutoBulk([string]$Mode, [switch]$NoConfirm) {
    $all = @($script:AutoEntries | Where-Object { $_ })
    if (-not $all.Count) { Build-Autostart; $all = @($script:AutoEntries | Where-Object { $_ }) }
    if (-not $all.Count) { Show-UiError ('Keine Autostart-Einträge gelesen. ' + ($script:AutoErr -join '; ')); return }
    foreach ($e in $all) {
        $w = switch ($Mode) {
            'On'          { $true }
            'Off'         { $e.Keep -or $e.Name -match 'SecurityHealth|PCPflege|PC-Tools' }
            'Minimal'     { $e.Keep -or ($e.Category -eq 'Notwendig' -and $e.Exists) }
            'Recommended' { if ($e.Category -eq 'Überflüssig' -and -not $e.Keep) { $false } else { $e.Enabled } }
        }
        $e | Add-Member -NotePropertyName Want -NotePropertyValue ([bool]($w -eq $true)) -Force
    }
    $chg = @($all | Where-Object { [bool]$_.Want -ne [bool]$_.Enabled })
    if (-not $chg.Count) { $ui.StatusText.Text = 'Autostart: nichts zu ändern.'; return }
    $on = @($all | Where-Object { $_.Want } | ForEach-Object { $_.Name })
    $txt = switch ($Mode) { 'On' { 'Alle Autostart-Einträge einschalten' } 'Off' { 'Alle Autostart-Einträge ausschalten (Windows-Sicherheit, PC-Tools und angepinnte bleiben an)' } 'Minimal' { 'Autostart auf das Nötige reduzieren' } default { 'Überflüssige Autostart-Einträge ausschalten' } }
    $q = "{0}?`n`n{1} Einträge werden geändert. Danach aktiv ({2}):`n{3}`n`nMit 'Rückgängig' lässt sich alles wiederherstellen." -f $txt, $chg.Count, $on.Count, $(if ($on.Count) { ($on | Select-Object -First 25 | ForEach-Object { '  - ' + $_ }) -join "`n" } else { '  (keine)' })
    if (-not $NoConfirm -and -not (Confirm-Ui $q)) { return }
    @($all | ForEach-Object { [pscustomobject]@{ Name = $_.Name; Kind = $_.Kind; Appr = $_.Appr; Key = $_.Key; Enabled = $_.Enabled } }) | ConvertTo-Json -Depth 3 | Set-Content -LiteralPath $AutoUndoFile -Encoding UTF8
    $err = @()
    foreach ($e in $chg) { try { Set-AutostartEntry $e ([bool]$e.Want) } catch { $err += ('{0}: {1}' -f $e.Name, $_.Exception.Message) } }
    $ui.BtnAutoUndo.IsEnabled = $true
    Show-Autostart
    $ui.StatusText.Text = 'Autostart: {0} Einträge geändert.' -f ($chg.Count - $err.Count)
    if ($err) { Show-UiError ("Nicht alles ging:`n" + ($err -join "`n")) }
}
function Undo-AutoBulk {
    if (-not (Test-Path -LiteralPath $AutoUndoFile)) { return }
    $j = Get-Content -LiteralPath $AutoUndoFile -Raw -Encoding UTF8 | ConvertFrom-Json; $old = @($j | ForEach-Object { $_ })
    $n = 0
    foreach ($o in $old) {
        $e = @($script:AutoEntries | Where-Object { $_.Name -eq $o.Name -and $_.Kind -eq $o.Kind -and $_.Key -eq $o.Key }) | Select-Object -First 1
        if ($e -and [bool]$e.Enabled -ne [bool]$o.Enabled) { try { Set-AutostartEntry $e ([bool]$o.Enabled); $n++ } catch { } }
    }
    Remove-Item -LiteralPath $AutoUndoFile -Force -ErrorAction SilentlyContinue
    $ui.BtnAutoUndo.IsEnabled = $false
    Show-Autostart; $ui.StatusText.Text = 'Autostart: {0} Einträge zurückgesetzt.' -f $n
}
function Remove-AutoBroken {
    $bad = @($script:AutoEntries | Where-Object { -not $_.Exists -and $_.Kind -in 'Reg', 'Folder' })
    if (-not $bad.Count) { $ui.StatusText.Text = 'Keine kaputten Autostart-Einträge.'; return }
    if (-not (Confirm-Ui ("Diese Einträge zeigen auf Programme, die es nicht mehr gibt, und werden entfernt:`n`n{0}`n`nEine Sicherung kommt nach {1}." -f (($bad | ForEach-Object { '  - ' + $_.Name }) -join "`n"), $DataDir))) { return }
    $bk = Join-Path $DataDir ('autostart-entfernt_{0:yyyyMMdd_HHmmss}.json' -f (Get-Date))
    @($bad | Select-Object Name, Cmd, Source, Kind, Key) | ConvertTo-Json | Set-Content -LiteralPath $bk -Encoding UTF8
    foreach ($e in $bad) {
        try { if ($e.Kind -eq 'Reg') { Remove-ItemProperty -LiteralPath $e.Key -Name $e.Name -ErrorAction Stop } else { Remove-Item -LiteralPath $e.Key -Force -ErrorAction Stop } } catch { }
    }
    Build-Autostart; $ui.StatusText.Text = '{0} kaputte Autostart-Einträge entfernt (Sicherung: {1}).' -f $bad.Count, $bk
}

# ---------------------------------------------------------------- Update mit Fortschrittsanzeige und Neustart-Angebote
function Show-UpdateProgress($Manifest, [string]$Source) {
    $gh = Get-GitHubSource $Source
    $tmp = Join-Path $DataDir 'Update'
    $items = @(foreach ($f in $Manifest.Files) {
        $name = [IO.Path]::GetFileName([string]$f.Name)
        if ($UpdateFiles -notcontains $name) { throw ('Unerwartete Datei im Update: {0}' -f $name) }
        $cur = Join-Path $DataDir $name; $est = if (Test-Path -LiteralPath $cur) { (Get-Item -LiteralPath $cur).Length } else { 300KB }
        $it = @{ Name = $name; Sha = ([string]$f.Sha256).ToUpper(); Est = [int64][math]::Max(1KB, $est); Url = ''; Headers = @{}; Src = '' }
        if ($gh) { $it.Url = 'https://api.github.com/repos/{0}/contents/{1}?ref={2}' -f $gh.Repo, $name, $gh.Branch; $it.Headers = Get-GitHubHeaders 'application/vnd.github.raw' }
        elseif ($Source -match '^https?://') { $it.Url = $Source.TrimEnd('/') + '/' + $name }
        else { $it.Src = Join-Path $Source $name }
        $it
    })
    $st = [hashtable]::Synchronized(@{ Bytes = [int64]0; Total = [int64](($items | ForEach-Object { $_.Est } | Measure-Object -Sum).Sum); File = ''; FileNo = 0; FileCount = $items.Count; FileDone = [int64]0; FileSize = [int64]0; Done = $false; Error = ''; Started = Get-Date })
    $x = @"
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Width="560" SizeToContent="Height" WindowStartupLocation="CenterOwner" WindowStyle="None" AllowsTransparency="True" Background="Transparent" ResizeMode="NoResize" FontFamily="Segoe UI" ShowInTaskbar="False" Topmost="True">
  <Border CornerRadius="16" Background="#FFFFFF" BorderBrush="#D8DEEA" BorderThickness="1" Margin="12">
    <Border.Effect><DropShadowEffect BlurRadius="24" ShadowDepth="4" Opacity="0.35"/></Border.Effect>
    <StackPanel>
      <Border CornerRadius="16,16,0,0" Padding="24,20">
        <Border.Background><LinearGradientBrush StartPoint="0,0" EndPoint="1,1"><GradientStop Color="#2D7FF9" Offset="0"/><GradientStop Color="#6D4AE8" Offset="1"/></LinearGradientBrush></Border.Background>
        <StackPanel Orientation="Horizontal">
          <Image x:Name="ULogo" Width="52" Height="52" Margin="0,0,16,0" RenderOptions.BitmapScalingMode="HighQuality"/>
          <StackPanel VerticalAlignment="Center">
            <TextBlock x:Name="UTitle" Text="PC-Tools wird aktualisiert" Foreground="White" FontSize="20" FontWeight="SemiBold"/>
            <TextBlock x:Name="UVer" Foreground="#E6ECFF" FontSize="13" Margin="0,2,0,0"/>
          </StackPanel>
        </StackPanel>
      </Border>
      <StackPanel Margin="24,18,24,20">
        <TextBlock x:Name="UStep" Text="Verbinde mit der Update-Quelle ..." FontSize="14" FontWeight="SemiBold" Foreground="#1F2A44"/>
        <Grid Margin="0,12,0,0">
          <Border Height="12" CornerRadius="6" Background="#E6EAF2"/>
          <Border x:Name="UBar" Height="12" CornerRadius="6" HorizontalAlignment="Left" Width="0">
            <Border.Background><LinearGradientBrush StartPoint="0,0" EndPoint="1,0"><GradientStop Color="#2D7FF9" Offset="0"/><GradientStop Color="#6D4AE8" Offset="1"/></LinearGradientBrush></Border.Background>
          </Border>
        </Grid>
        <Grid Margin="0,6,0,0"><TextBlock x:Name="UDetail" Foreground="#6B7890" FontSize="12"/><TextBlock x:Name="UPct" HorizontalAlignment="Right" Foreground="#1F2A44" FontWeight="SemiBold" FontSize="12"/></Grid>
        <ItemsControl x:Name="UFiles" Margin="0,12,0,0"/>
        <TextBlock x:Name="UNotes" TextWrapping="Wrap" Foreground="#475569" FontSize="12" Margin="0,12,0,0"/>
        <Button x:Name="UClose" Content="Schließen" HorizontalAlignment="Right" Padding="18,6" Margin="0,14,0,0" Visibility="Collapsed"/>
      </StackPanel>
    </StackPanel>
  </Border>
</Window>
"@
    $dlg = [Windows.Markup.XamlReader]::Parse($x)
    try { $dlg.Owner = $window } catch { }
    $u = @{}; foreach ($n in 'ULogo', 'UTitle', 'UVer', 'UStep', 'UBar', 'UDetail', 'UPct', 'UFiles', 'UNotes', 'UClose') { $u[$n] = $dlg.FindName($n) }
    if ($script:bigFrame) { $u.ULogo.Source = $script:bigFrame }
    $u.UVer.Text = 'Version {0}  ->  {1}' -f $AppVersion, $Manifest.Version
    $u.UNotes.Text = if ($Manifest.Notes) { 'Neu: ' + $Manifest.Notes } else { '' }
    $rows = @{}
    foreach ($it in $items) {
        $g = New-Object Windows.Controls.Grid; $g.Margin = '0,2'
        $c1 = New-Object Windows.Controls.ColumnDefinition; $c1.Width = '22'; $c2 = New-Object Windows.Controls.ColumnDefinition; $c3 = New-Object Windows.Controls.ColumnDefinition; $c3.Width = 'Auto'
        [void]$g.ColumnDefinitions.Add($c1); [void]$g.ColumnDefinitions.Add($c2); [void]$g.ColumnDefinitions.Add($c3)
        $i = New-Object Windows.Controls.TextBlock; $i.FontFamily = 'Segoe MDL2 Assets'; $i.Text = [char]0xE823; $i.Foreground = [Windows.Media.Brushes]::Gray; $i.VerticalAlignment = 'Center'
        $t = New-Object Windows.Controls.TextBlock; $t.Text = $it.Name; $t.Foreground = [Windows.Media.Brushes]::DimGray; [Windows.Controls.Grid]::SetColumn($t, 1)
        $s = New-Object Windows.Controls.TextBlock; $s.Text = 'wartet'; $s.Foreground = [Windows.Media.Brushes]::Gray; $s.FontSize = 11.5; [Windows.Controls.Grid]::SetColumn($s, 2)
        [void]$g.Children.Add($i); [void]$g.Children.Add($t); [void]$g.Children.Add($s); [void]$u.UFiles.Items.Add($g)
        $rows[$it.Name] = @{ I = $i; S = $s }
    }
    $ps = [powershell]::Create()
    [void]$ps.AddScript({
        param($items, $tmp, $st)
        try {
            try { [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12 } catch { }
            Remove-Item -LiteralPath $tmp -Recurse -Force -ErrorAction SilentlyContinue; New-Item $tmp -ItemType Directory -Force | Out-Null
            $n = 0
            foreach ($it in $items) {
                $n++; $st.FileNo = $n; $st.File = $it.Name; $st.FileDone = 0; $st.FileSize = $it.Est
                $dst = Join-Path $tmp $it.Name
                if ($it.Url) {
                    $rq = [Net.HttpWebRequest]::Create($it.Url); $rq.Timeout = 30000; $rq.ReadWriteTimeout = 60000; $rq.UserAgent = 'PC-Tools'
                    foreach ($k in $it.Headers.Keys) { switch ($k) { 'Accept' { $rq.Accept = $it.Headers[$k] } 'User-Agent' { $rq.UserAgent = $it.Headers[$k] } default { $rq.Headers.Add($k, [string]$it.Headers[$k]) } } }
                    $rs = $rq.GetResponse(); if ($rs.ContentLength -gt 0) { $st.Total += ($rs.ContentLength - $it.Est); $st.FileSize = $rs.ContentLength }
                    $in = $rs.GetResponseStream(); $out = [IO.File]::Create($dst); $buf = New-Object byte[] 65536
                    try { while (($r = $in.Read($buf, 0, $buf.Length)) -gt 0) { $out.Write($buf, 0, $r); $st.FileDone += $r; $st.Bytes += $r } } finally { $out.Close(); $in.Close(); $rs.Close() }
                } else {
                    Copy-Item -LiteralPath $it.Src -Destination $dst -Force -ErrorAction Stop; $len = (Get-Item -LiteralPath $dst).Length; $st.FileDone = $len; $st.Bytes += $len
                }
                $h = (Get-FileHash -LiteralPath $dst -Algorithm SHA256).Hash
                if ($h -ne $it.Sha) { throw ('Prüfsumme stimmt nicht: {0} - Update abgebrochen, nichts wurde geändert.' -f $it.Name) }
                $st['OK_' + $it.Name] = $true
            }
        } catch { $st.Error = $_.Exception.Message }
        $st.Done = $true
    })
    [void]$ps.AddArgument($items); [void]$ps.AddArgument($tmp); [void]$ps.AddArgument($st)
    $hnd = $ps.BeginInvoke()
    $script:UpdResult = $false; $script:UpdPhase = 'dl'; $script:UpdCount = 3
    $tm = New-Object Windows.Threading.DispatcherTimer; $tm.Interval = [TimeSpan]::FromMilliseconds(120)
    $fmt = { param($b) if ($b -ge 1MB) { '{0:N1} MB' -f ($b / 1MB) } else { '{0:N0} KB' -f ($b / 1KB) } }
    $script:UpdU = $u; $script:UpdSt = $st; $script:UpdRows = $rows; $script:UpdDlg = $dlg; $script:UpdTm = $tm; $script:UpdMan = $Manifest; $script:UpdTmp = $tmp; $script:UpdFmt = $fmt; $script:UpdTick = 0
    $tm.Add_Tick({
        $w = [math]::Max(0.0, $script:UpdU.UBar.Parent.ActualWidth)
        if ($script:UpdPhase -eq 'dl') {
            $pct = if ($script:UpdSt.Total -gt 0) { [math]::Min(96, 96.0 * $script:UpdSt.Bytes / $script:UpdSt.Total) } else { 0 }
            $script:UpdU.UBar.Width = $w * $pct / 100; $script:UpdU.UPct.Text = '{0:N0} %' -f $pct
            $sec = [math]::Max(0.5, ((Get-Date) - $script:UpdSt.Started).TotalSeconds)
            if ($script:UpdSt.File) { $script:UpdU.UStep.Text = 'Lade Datei {0} von {1}: {2}' -f $script:UpdSt.FileNo, $script:UpdSt.FileCount, $script:UpdSt.File; $script:UpdU.UDetail.Text = '{0} von {1}  ·  {2}/s' -f (& $script:UpdFmt $script:UpdSt.FileDone), (& $script:UpdFmt $script:UpdSt.FileSize), (& $script:UpdFmt ($script:UpdSt.Bytes / $sec)) }
            foreach ($k in $script:UpdRows.Keys) {
                if ($script:UpdSt['OK_' + $k]) { $script:UpdRows[$k].I.Text = [char]0xE73E; $script:UpdRows[$k].I.Foreground = [Windows.Media.Brushes]::SeaGreen; $script:UpdRows[$k].S.Text = 'geprüft (SHA-256)' }
                elseif ($k -eq $script:UpdSt.File) { $script:UpdRows[$k].I.Text = [char]0xE896; $script:UpdRows[$k].I.Foreground = [Windows.Media.Brushes]::RoyalBlue; $script:UpdRows[$k].S.Text = 'lädt ...' }
            }
            if ($script:UpdSt.Done) {
                if ($script:UpdSt.Error) {
                    $script:UpdTm.Stop(); $script:UpdU.UStep.Text = 'Update nicht möglich'; $script:UpdU.UDetail.Text = $script:UpdSt.Error; $script:UpdU.UStep.Foreground = [Windows.Media.Brushes]::Firebrick
                    $script:UpdU.UNotes.Text = 'PC-Tools läuft mit der bisherigen Version {0} weiter.' -f $AppVersion; $script:UpdU.UClose.Visibility = 'Visible'
                } else { $script:UpdPhase = 'inst' }
            }
        } elseif ($script:UpdPhase -eq 'inst') {
            $script:UpdU.UStep.Text = 'Installiere Version {0} ...' -f $script:UpdMan.Version; $script:UpdU.UBar.Width = $w * 0.98; $script:UpdU.UPct.Text = '98 %'
            try { Install-PflegeUpdateFiles $script:UpdTmp $script:UpdMan; $script:UpdResult = $true; $script:UpdPhase = 'wait'; $script:UpdCount = 3 }
            catch { $script:UpdTm.Stop(); $script:UpdU.UStep.Text = 'Installation fehlgeschlagen'; $script:UpdU.UDetail.Text = $_.Exception.Message; $script:UpdU.UClose.Visibility = 'Visible' }
        } elseif ($script:UpdPhase -eq 'wait') {
            $script:UpdU.UBar.Width = $w; $script:UpdU.UPct.Text = '100 %'
            $script:UpdU.UStep.Text = 'Fertig - Version {0} ist installiert.' -f $script:UpdMan.Version; $script:UpdU.UStep.Foreground = [Windows.Media.Brushes]::SeaGreen
            $script:UpdTick = 1 + [int]$script:UpdTick
            if ($script:UpdTick % 8 -eq 0) { $script:UpdCount-- }
            $script:UpdU.UDetail.Text = 'PC-Tools startet in {0} Sekunden neu ...' -f [math]::Max(0, $script:UpdCount)
            if ($script:UpdCount -le 0) { $script:UpdTm.Stop(); $script:UpdDlg.Close() }
        }
    })
    $script:UpdU.UClose.Add_Click({ $script:UpdDlg.Close() })
    $tm.Start()
    [void]$dlg.ShowDialog()
    $tm.Stop(); try { $ps.Dispose() } catch { }
    return $script:UpdResult
}
function Show-RebootPrompt([string]$Why) {
    if ($script:Job) { return }
    $x = @"
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Width="520" SizeToContent="Height" WindowStartupLocation="CenterOwner" WindowStyle="None" AllowsTransparency="True" Background="Transparent" ResizeMode="NoResize" FontFamily="Segoe UI" ShowInTaskbar="False" Topmost="True">
  <Border CornerRadius="16" Background="#FFFFFF" BorderBrush="#D8DEEA" BorderThickness="1" Margin="12">
    <Border.Effect><DropShadowEffect BlurRadius="24" ShadowDepth="4" Opacity="0.35"/></Border.Effect>
    <StackPanel>
      <Border CornerRadius="16,16,0,0" Padding="24,18" Background="#EA580C">
        <StackPanel Orientation="Horizontal"><TextBlock Text="&#xE777;" FontFamily="Segoe MDL2 Assets" FontSize="30" Foreground="White" Margin="0,0,14,0" VerticalAlignment="Center"/><TextBlock Text="Neustart nötig" Foreground="White" FontSize="20" FontWeight="SemiBold" VerticalAlignment="Center"/></StackPanel>
      </Border>
      <StackPanel Margin="24,16,24,20">
        <TextBlock x:Name="RWhy" TextWrapping="Wrap" Foreground="#1F2A44" FontSize="13.5"/>
        <TextBlock Text="Vorher alles speichern - offene Programme werden geschlossen." TextWrapping="Wrap" Foreground="#6B7890" FontSize="12" Margin="0,8,0,0"/>
        <WrapPanel HorizontalAlignment="Right" Margin="0,16,0,0">
          <Button x:Name="RNow" Content="Jetzt neu starten" Padding="16,7" Margin="0,0,8,0" Background="#EA580C" Foreground="White" BorderThickness="0" FontWeight="SemiBold"/>
          <Button x:Name="R10" Content="In 10 Minuten" Padding="14,7" Margin="0,0,8,0"/>
          <Button x:Name="RLater" Content="Später" Padding="14,7"/>
        </WrapPanel>
      </StackPanel>
    </StackPanel>
  </Border>
</Window>
"@
    $d = [Windows.Markup.XamlReader]::Parse($x); try { $d.Owner = $window } catch { }
    $d.FindName('RWhy').Text = $Why
    $script:RbChoice = 'later'
    $script:RbDlg = $d
    $d.FindName('RNow').Add_Click({ $script:RbChoice = 'now'; $script:RbDlg.Close() })
    $d.FindName('R10').Add_Click({ $script:RbChoice = '10'; $script:RbDlg.Close() })
    $d.FindName('RLater').Add_Click({ $script:RbChoice = 'later'; $script:RbDlg.Close() })
    [void]$d.ShowDialog()
    switch ($script:RbChoice) {
        'now' { $script:Restarting = $true; & shutdown.exe /r /t 5 /c 'PC-Tools: Neustart' | Out-Null; $ui.StatusText.Text = 'Der PC startet in 5 Sekunden neu ...' }
        '10' { & shutdown.exe /r /t 600 /c 'PC-Tools: Neustart in 10 Minuten (abbrechen: shutdown /a)' | Out-Null; $ui.StatusText.Text = 'Neustart in 10 Minuten geplant - abbrechen mit "shutdown /a" in der Eingabeaufforderung.' }
        default { $script:RebootLater = $Why; $ui.StatusText.Text = 'Neustart ausstehend - PC-Tools erinnert beim Schließen daran.' }
    }
}

# ---------------------------------------------------------------- Selbst-Update (Oberfläche)
$script:UpdManifest = $null
function Invoke-UpdateCheck([switch]$Quiet) {
    $src = $ui.Settings_UpdateSource.Text.Trim()
    $ui.InfoAppVer.Text = 'Version {0}' -f $AppVersion
    if (-not $src) { $ui.UpdStatus.Text = ('Installiert: {0} - keine Update-Quelle eingetragen' -f $AppVersion); $ui.BtnUpdInstall.IsEnabled = $false; return }
    # V14: Abruf im Hintergrund - langsames/fehlendes Netz lässt das Fenster nicht mehr hängen
    $script:UpdQuiet = [bool]$Quiet
    $ui.UpdStatus.Text = 'Suche nach neuer Version ...'
    Invoke-Bg -Script { param($s) Get-UpdateManifest $s } -Arguments @($src) -Functions @('Get-UpdateManifest') -Done {
        param($r, $e)
        $m = @($r | Where-Object { $_ -and $_.PSObject.Properties['Version'] })[0]
        try { Complete-UpdateCheck $m $script:UpdQuiet } catch { $ui.UpdStatus.Text = 'Update-Prüfung: ' + $_.Exception.Message }
    }
}
function Complete-UpdateCheck($m, [bool]$Quiet) {
    $script:UpdManifest = $m
    if (-not $m) { $ui.UpdStatus.Text = ('Installiert: {0} - Update-Quelle nicht erreichbar oder leer' -f $AppVersion); $ui.BtnUpdInstall.IsEnabled = $false; return }
    if (Test-NewerVersion $m.Version $AppVersion) {
        $ui.UpdStatus.Text = ('Neue Version {0} verfügbar (vom {1}) - installiert: {2}{3}' -f $m.Version, $m.Date, $AppVersion, $(if ($m.Notes) { [Environment]::NewLine + 'Neu: ' + $m.Notes } else { '' }))
        $ui.UpdStatus.Foreground = $Brush.Orange
        $ui.InfoAppVer.Text = ('Version {0} - Update auf {1} verfügbar (Einstellungen)' -f $AppVersion, $m.Version)
        $ui.InfoAppVer.Foreground = $Brush.Orange
        $ui.BtnUpdInstall.IsEnabled = $true
        $cfgU = $null; try { $cfgU = Get-ConfigFromUi } catch { }
        $dueU = Get-UpdateDue $m $cfgU; $skipU = @(Get-UpdateSkip) -contains [string]$m.Version
        if ($skipU) { $ui.UpdStatus.Text += [Environment]::NewLine + 'Diese Version wurde nach einem Startproblem zurückgenommen und wird nicht automatisch installiert.' }
        elseif ($dueU) { $ui.UpdStatus.Text += [Environment]::NewLine + ('Automatische Installation ab {0:dd.MM.yyyy HH:mm} (Update-Verzögerung) - "Update installieren" geht sofort.' -f $dueU) }
        if (-not $Quiet) { return }
        if ($skipU -or $dueU) { return }
        if ($script:Job) { $ui.StatusText.Text = ('Version {0} ist verfügbar - wird nach der laufenden Pflege installiert (Einstellungen > Update).' -f $m.Version); return }
        Install-UpdateGui
    } else {
        $ui.UpdStatus.Text = ('Aktuell: {0} (Quelle: {1})' -f $AppVersion, $m.Version)
        $ui.UpdStatus.Foreground = $Brush.Green
        $ui.BtnUpdInstall.IsEnabled = $false
    }
}
function Install-UpdateGui {
    if ($script:Job) { [Windows.MessageBox]::Show((T ('Bitte warten, bis die laufende Pflege fertig ist.')), (T ('PC-Tools'))) | Out-Null; return }
    if (-not $script:UpdManifest) { return }
    $ok = $false
    try { $ok = Show-UpdateProgress $script:UpdManifest $ui.Settings_UpdateSource.Text.Trim() } catch { Show-UiError ('Update fehlgeschlagen: ' + $_.Exception.Message); return }
    if (-not $ok) { return }
    $script:Restarting = $true
    $null = Start-HiddenPS $PSCommandPath
    $window.Close()
}

# ---------------------------------------------------------------- Einstellungen
function Update-SettingsInfo {
    $ui.InfoVersion.Text = 'PC-Tools {0}  ·  by RH' -f $AppVersion
    $ui.InfoScript.Text = [string]$PSCommandPath
    $ui.InfoData.Text = $DataDir
    $ui.InfoComputer.Text = '{0} - {1}' -f $env:COMPUTERNAME, [Security.Principal.WindowsIdentity]::GetCurrent().Name
    if ($ui.InfoChecksum) {
        try { $h = (Get-FileHash -LiteralPath $PSCommandPath -Algorithm SHA256).Hash; $ui.InfoChecksum.Text = ('SHA-256 dieser Programmdatei (zum Prüfen der Echtheit): {0}' -f $h) } catch { $ui.InfoChecksum.Text = '' }
    }
}
function Get-GitHubWebUrl {
    $src = ''; try { $src = [string](Read-PflegeConfig).Settings.UpdateSource } catch { }
    if (-not $src) { $src = $DefaultUpdateSource }
    $repo = ($src -replace '^github:', '') -replace '#.*$', ''
    if (-not $repo) { $repo = 'rhedv42-sudo/pc-tools' }
    return ('https://github.com/{0}' -f $repo)
}
function Show-FirstRunOrNews {
    $marker = Join-Path $DataDir 'gesehen.json'
    $last = ''; try { if (Test-Path -LiteralPath $marker) { $last = [string]((Get-Content -LiteralPath $marker -Raw -ErrorAction Stop | ConvertFrom-Json).Version) } } catch { }
    try { @{ Version = [string]$AppVersion; Seen = (Get-Date).ToString('s') } | ConvertTo-Json | Set-Content -LiteralPath $marker -Encoding UTF8 } catch { }
    if (-not $last) {
        $nl = [Environment]::NewLine
        [Windows.MessageBox]::Show((T (('Willkommen bei PC-Tools!' + $nl + $nl +
            'PC-Tools ist kostenlos und quelloffen (Open Source, Apache 2.0) - von René Hütt (by RH).' + $nl + $nl +
            'Es hält Windows gepflegt, aktuell und schnell: Updates, Treiber, Aufräumen, Reparatur, Sicherheit - vieles davon mit einem Klick ("Alles automatisch" auf der Startseite).' + $nl + $nl +
            'Datenschutz: PC-Tools sendet nichts nach Hause. Keine Telemetrie, keine Nutzerdaten.' + $nl + $nl +
            'Tipp: Keine Technik-Kenntnisse nötig - der grüne Knopf "Alles automatisch" erledigt alles von selbst.'))), (T ('PC-Tools - Willkommen')), 'OK', 'Information') | Out-Null
        return
    }
    if ($last -ne [string]$AppVersion) { try { Show-WhatsNew } catch { } }
}
function Show-WhatsNew {
    $news = @($ManualNews | Where-Object { $_ -match ('Version ' + [regex]::Escape($AppVersion)) })
    if (-not $news.Count) { $news = @($ManualNews | Select-Object -First 6) }
    $body = ($news | ForEach-Object { '•  ' + ($_ -replace '^Version [0-9.]+:\s*', '') }) -join [Environment]::NewLine + [Environment]::NewLine
    [Windows.MessageBox]::Show((T (('Was ist neu in PC-Tools {0}:{1}{1}{2}' -f $AppVersion, [Environment]::NewLine, $body))), (T ('PC-Tools - Neuigkeiten')), 'OK', 'Information') | Out-Null
}

# ---------------------------------------------------------------- Ninite: Programmauswahl
$script:NinApps = [System.Collections.Generic.List[object]]::new()
$script:NinAudit = $null
function Get-NinitePathGui {
    $c = @($ui.Update_NinitePath.Text, (Join-Path $PSScriptRoot 'NinitePro.exe'), (Join-Path $DataDir 'NinitePro.exe'))
    return ($c | Where-Object { $_ -and (Test-Path -LiteralPath $_) } | Select-Object -First 1)
}
function New-UiBrush([string]$hex) { if ($Script:Dark) { $k = $hex.ToUpper(); if ($ThemeMap.ContainsKey($k)) { $hex = $ThemeMap[$k] } }; (New-Object Windows.Media.BrushConverter).ConvertFromString($hex) }

function Build-NiniteList {
    $cats = [System.Collections.Generic.List[string]]::new()
    $groups = [ordered]@{}
    foreach ($line in ($NiniteCatalog -split "`r?`n")) {
        if (-not $line.Trim()) { continue }
        $p = $line.Split('|')
        $cat = $p[0]; $name = $p[1]; $desc = $p[2]
        if (-not $groups.Contains($cat)) {
            $hdr = New-Object Windows.Controls.TextBlock
            $hdr.Text = $cat; $hdr.FontSize = 15; $hdr.FontWeight = 'SemiBold'; $hdr.Foreground = (New-UiBrush '#1F2A44'); $hdr.Margin = '0,10,0,6'
            $wrap = New-Object Windows.Controls.WrapPanel
            [void]$ui.NinPanel.Children.Add($hdr); [void]$ui.NinPanel.Children.Add($wrap)
            $groups[$cat] = @{ Header = $hdr; Wrap = $wrap }
            $cats.Add($cat)
        }
        $card = New-Object Windows.Controls.Border
        $card.Width = 230; $card.Margin = '0,0,10,10'; $card.Padding = '10,8'; $card.CornerRadius = '8'
        $card.BorderThickness = '1'; $card.BorderBrush = (New-UiBrush '#E2E7F0'); $card.Background = (New-UiBrush '#F8FAFD')
        $sp = New-Object Windows.Controls.StackPanel
        $cb = New-Object Windows.Controls.CheckBox
        $cb.Content = $name; $cb.FontWeight = 'SemiBold'; $cb.Foreground = (New-UiBrush '#1F2A44')
        $d = New-Object Windows.Controls.TextBlock
        $d.Text = $desc; $d.FontSize = 11; $d.Foreground = (New-UiBrush '#6B7890'); $d.TextWrapping = 'Wrap'; $d.Margin = '21,2,0,0'
        $st = New-Object Windows.Controls.TextBlock
        $st.FontSize = 11; $st.Margin = '21,3,0,0'; $st.Visibility = 'Collapsed'
        [void]$sp.Children.Add($cb); [void]$sp.Children.Add($d); [void]$sp.Children.Add($st)
        $card.Child = $sp
        [void]$groups[$cat].Wrap.Children.Add($card)
        $cb.Add_Checked({ Update-NinSelection }); $cb.Add_Unchecked({ Update-NinSelection })
        $script:NinApps.Add([pscustomobject]@{ Name = $name; Cat = $cat; Desc = $desc; Card = $card; Check = $cb; Status = $st; Group = $groups[$cat]; State = '' })
    }
    [void]$ui.NinCategory.Items.Add('Alle Kategorien')
    foreach ($c in $cats) { [void]$ui.NinCategory.Items.Add($c) }
    $ui.NinCategory.SelectedIndex = 0
    foreach ($s in @('Geprüfter Katalog', 'Online: winget', 'Online: Chocolatey', 'Online: alle Quellen')) { [void]$ui.NinSource.Items.Add($s) }
    $ui.NinSource.SelectedIndex = 0
    Update-NinSelection
    Update-NinMode
}
$script:NinOnline = [System.Collections.Generic.List[object]]::new()
$script:NinSearchBusy = $false
function Get-NinSrcKey { switch ([string]$ui.NinSource.SelectedItem) { 'Online: winget' { 'winget' } 'Online: Chocolatey' { 'choco' } 'Online: alle Quellen' { 'beide' } default { 'cat' } } }
function Update-NinMode {
    $k = Get-NinSrcKey
    $online = ($k -ne 'cat')
    $ui.NinCatView.Visibility    = if ($online) { 'Collapsed' } else { 'Visible' }
    $ui.NinOnlineView.Visibility = if ($online) { 'Visible' } else { 'Collapsed' }
    $ui.NinCategory.Visibility   = if ($online) { 'Collapsed' } else { 'Visible' }
    $ui.NinCatOpts.Visibility    = if ($online) { 'Collapsed' } else { 'Visible' }
    $ui.BtnNinOnline.Visibility  = if ($online) { 'Visible' } else { 'Collapsed' }
    $ui.NinSearchHint.Text = if ($online) { 'Programmnamen eingeben und Enter drücken ...' } else { 'Katalog durchsuchen ...' }
    $ui.NinSearchHint.Visibility = if ([string]$ui.NinSearch.Text) { 'Collapsed' } else { 'Visible' }
    Update-NinSelection
}
function Start-NinOnlineSearch {
    if ($script:NinSearchBusy) { return }
    $term = $ui.NinSearch.Text.Trim()
    $src = Get-NinSrcKey
    if ($src -eq 'cat') { return }
    if ($term.Length -lt 2) { $ui.NinOnlineEmpty.Text = 'Bitte mindestens 2 Zeichen eingeben.'; $ui.NinOnlineEmpty.Visibility = 'Visible'; return }
    $script:NinSearchBusy = $true
    $ui.BtnNinOnline.IsEnabled = $false; $ui.BtnNinOnline.Content = 'Suche läuft ...'
    $ui.NinOnlineEmpty.Text = ('Suche nach "{0}" ...' -f $term); $ui.NinOnlineEmpty.Visibility = 'Visible'
    $ui.NinOnlineGrid.ItemsSource = $null
    Invoke-Bg -Script { param($t, $s) , (Search-AppCatalog -Term $t -Src $s) } -Arguments @($term, $src) `
        -Functions @('Search-AppCatalog', 'Get-WingetPath', 'Get-ChocoPath', 'Test-WingetBlocked') -Done {
        param($res, $err)
        $script:NinSearchBusy = $false
        $ui.BtnNinOnline.IsEnabled = $true; $ui.BtnNinOnline.Content = 'Online suchen'
        if ($err) { $ui.NinOnlineEmpty.Text = 'Suche fehlgeschlagen: ' + $err.Message; $ui.NinOnlineEmpty.Visibility = 'Visible'; return }
        $rows = @(); if ($res) { $rows = @($res | Where-Object { $_ -and $_.Name }) }
        $term2 = $ui.NinSearch.Text.Trim()
        if ($term2 -and (Get-NinitePathGui)) {
            $nin = @($script:NinApps | Where-Object { $_.Name -like "*$term2*" -or $_.Desc -like "*$term2*" } |
                    ForEach-Object { [pscustomobject]@{ Name = $_.Name; Id = $_.Name; Version = ''; Source = 'Ninite' } })
            if ($nin.Count) { $rows = @($nin) + @($rows) }
        }
        $rows = @($rows | Sort-Object @{ Expression = { if ($_.Source -eq 'Ninite') { 0 } else { 1 } } }, Name)
        $script:NinOnline = [System.Collections.Generic.List[object]]@($rows)
        $ui.NinOnlineGrid.ItemsSource = [System.Collections.ArrayList]@($rows)
        if ($rows.Count) { $ui.NinOnlineEmpty.Visibility = 'Collapsed' }
        else { $ui.NinOnlineEmpty.Text = 'Nichts gefunden. Anderen Begriff versuchen (z.B. den Herstellernamen) oder Quelle "alle Quellen" wählen.'; $ui.NinOnlineEmpty.Visibility = 'Visible' }
        $src2 = Get-NinSrcKey
        $hint = if ($src2 -eq 'beide') { 'winget und Chocolatey' } elseif ($src2 -eq 'winget') { 'winget' } else { 'Chocolatey' }
        $ui.NinInfo.Text = ('{0} Treffer aus {1} - zum Installieren markieren (Strg/Umschalt für mehrere).' -f $rows.Count, $hint)
    }
}
function Update-NinSelection {
    if ((Get-NinSrcKey) -ne 'cat') {
        $n = @($ui.NinOnlineGrid.SelectedItems).Count
        $ui.BtnNinInstall.Content = if ($n) { 'Markierte installieren ({0})' -f $n } else { 'Markierte installieren' }
        return
    }
    $sel = @($script:NinApps | Where-Object { $_.Check.IsChecked })
    foreach ($a in $script:NinApps) { $a.Card.Background = if ($a.Check.IsChecked) { $Brush.SelBg } else { $Brush.CardBg } }
    $ui.NinInfo.Text = if ($sel.Count) { '{0} ausgewählt: {1}' -f $sel.Count, (($sel | ForEach-Object { $_.Name }) -join ', ') } else { 'Nichts ausgewählt' }
    $ui.BtnNinInstall.Content = if ($sel.Count) { 'Ausgewählte installieren ({0})' -f $sel.Count } else { 'Ausgewählte installieren' }
    if ($ui.NinOnlySel.IsChecked) { Update-NinFilter }
}
function Update-NinFilter {
    $q = $ui.NinSearch.Text.Trim()
    $cat = [string]$ui.NinCategory.SelectedItem
    $vis = @{}
    foreach ($a in $script:NinApps) {
        $show = $true
        if ($q -and -not ($a.Name -like "*$q*" -or $a.Desc -like "*$q*" -or $a.Cat -like "*$q*")) { $show = $false }
        if ($cat -and $cat -ne 'Alle Kategorien' -and $a.Cat -ne $cat) { $show = $false }
        if ($ui.NinOnlySel.IsChecked -and -not $a.Check.IsChecked) { $show = $false }
        if ($ui.NinHideInst.IsChecked -and $a.State -eq 'ok') { $show = $false }
        $a.Card.Visibility = if ($show) { 'Visible' } else { 'Collapsed' }
        if ($show) { $vis[$a.Cat] = $true }
    }
    foreach ($a in $script:NinApps) {
        $v = if ($vis[$a.Cat]) { 'Visible' } else { 'Collapsed' }
        $a.Group.Header.Visibility = $v; $a.Group.Wrap.Visibility = $v
    }
}
function Start-NiniteAudit {
    if ($script:NinAudit -or $script:Job) { return }
    $exe = Get-NinitePathGui
    if (-not $exe) { [Windows.MessageBox]::Show((T ('NinitePro.exe nicht gefunden.' + [char]10 + [char]10 + 'Programm-Updates laufen auch ohne Ninite ueber winget (kostenlos, in Windows enthalten).' + [char]10 + 'NinitePro Pro (mehr Programme, Zwischenspeicher) gibt es unter ninite.com/pro - danach den Pfad unter Updates eintragen.')), (T ('PC-Tools')), 'OK', 'Information') | Out-Null; return }
    $dir = Join-Path $DataDir 'Ninite'; New-Item $dir -ItemType Directory -Force | Out-Null
    $rep = Join-Path $dir ('Ninite_Audit_{0:yyyyMMdd_HHmmss}.txt' -f (Get-Date))
    $p = Start-Process -FilePath $exe -ArgumentList @('/audit', '/silent', ('"{0}"' -f $rep)) -WindowStyle Hidden -PassThru
    $script:NinAudit = @{ Proc = $p; Report = $rep; Start = Get-Date }
    $ui.BtnNinAudit.IsEnabled = $false
    $ui.NinInfo.Text = 'Ninite prüft, welche Programme installiert sind ...'
}
function Complete-NiniteAudit {
    $a = $script:NinAudit; $script:NinAudit = $null
    $ui.BtnNinAudit.IsEnabled = -not [bool]$script:Job
    if (-not (Test-Path -LiteralPath $a.Report)) { $ui.NinInfo.Text = 'Ninite hat keinen Prüfbericht erstellt.'; return }
    $map = @{}
    foreach ($l in (Get-Content -LiteralPath $a.Report -ErrorAction SilentlyContinue)) {
        if ($l -match '^\s*(?<n>.+?)\s*:\s*(?<s>.+?)\s*$') { $map[$Matches.n] = $Matches.s }
    }
    $inst = 0; $upd = 0
    foreach ($app in $script:NinApps) {
        $s = $map[$app.Name]
        $app.State = ''; $app.Status.Visibility = 'Collapsed'
        if (-not $s -or $s -match '(?i)not installed') { continue }
        if ($s -match '(?i)^Update') {
            $app.State = 'update'; $upd++
            $app.Status.Text = 'Update verfügbar: ' + ($s -replace '(?i)^Update\s*-\s*', '')
            $app.Status.Foreground = $Brush.Orange
        } elseif ($s -match '(?i)^(OK|Skipped)') {
            $app.State = 'ok'; $inst++
            $app.Status.Text = 'installiert ' + ($s -replace '(?i)^(OK|Skipped)\s*-?\s*', '')
            $app.Status.Foreground = $Brush.Green
        } else { $app.Status.Text = $s; $app.Status.Foreground = $Brush.Gray }
        $app.Status.Visibility = 'Visible'
    }
    Update-NinSelection
    Update-NinFilter
    $ui.NinInfo.Text = ('{0} Programme installiert, davon {1} mit Update. {2}' -f ($inst + $upd), $upd, $ui.NinInfo.Text)
}

function Format-Rate([double]$b) {
    if ($b -ge 1MB) { return ('{0:N1} MB/s' -f ($b / 1MB)) }
    if ($b -ge 1KB) { return ('{0:N0} KB/s' -f ($b / 1KB)) }
    return '0 KB/s'
}
function Format-Dur([TimeSpan]$t) {
    if ($t.TotalHours -ge 1) { return ('{0}:{1:mm\:ss} h' -f [int][math]::Floor($t.TotalHours), $t) }
    return ('{0:mm\:ss} min' -f $t)
}
$Brush = @{}
foreach ($c in @{ Green = '#16A34A'; Orange = '#D97706'; Gray = '#9AA5B8'; Red = '#EF4444'; SelBg = '#E6F0FF'; CardBg = '#F8FAFD' }.GetEnumerator()) {
    $Brush[$c.Key] = New-UiBrush $c.Value
}
$script:Act = @{ Sw = [Diagnostics.Stopwatch]::StartNew(); LastSample = $null; LastCpu = 0.0; LastIo = 0.0; LastActive = (Get-Date); Info = ''; StepStart = $null }

# Prozessbaum des Hintergrundlaufs + Installer-Dienste messen (CPU und Datenträger/Netz)
function Update-Activity {
    $j = $script:Job
    if (-not $j) { return }
    if ($script:Act.Sw.Elapsed.TotalSeconds -lt 2) { return }
    $script:Act.Sw.Restart()
    $all = @(Get-CimInstance Win32_Process -Property ProcessId, ParentProcessId, Name, UserModeTime, KernelModeTime, ReadTransferCount, WriteTransferCount, CommandLine, CreationDate -ErrorAction SilentlyContinue)
    $byParent = @{}
    foreach ($p in $all) {
        $pp = [int]$p.ParentProcessId
        if (-not $byParent.ContainsKey($pp)) { $byParent[$pp] = [System.Collections.Generic.List[object]]::new() }
        $byParent[$pp].Add($p)
    }
    $root = $all | Where-Object { $_.ProcessId -eq $j.Proc.Id } | Select-Object -First 1
    $tree = [System.Collections.Generic.List[object]]::new()
    if ($root) {
        $stack = New-Object System.Collections.Stack
        $stack.Push($root)
        while ($stack.Count) {
            $cur = $stack.Pop()
            if ($byParent.ContainsKey([int]$cur.ProcessId)) {
                foreach ($c in $byParent[[int]$cur.ProcessId]) {
                    if ($c.ProcessId -eq $cur.ProcessId) { continue }
                    if ($cur.CreationDate -and $c.CreationDate -and $c.CreationDate -lt $cur.CreationDate) { continue }
                    $tree.Add($c); $stack.Push($c)
                }
            }
        }
    }
    $treeIds = @($tree | ForEach-Object { $_.ProcessId })
    $svc = @($all | Where-Object { $_.Name -in 'msiexec.exe', 'TiWorker.exe', 'TrustedInstaller.exe' -and $treeIds -notcontains $_.ProcessId })
    $cpu = 0.0; $io = 0.0
    foreach ($p in @($root) + @($tree) + $svc) {
        if (-not $p) { continue }
        $cpu += [double]$p.UserModeTime + [double]$p.KernelModeTime
        $io  += [double]$p.ReadTransferCount + [double]$p.WriteTransferCount
    }
    $now = Get-Date
    $cpuPct = 0.0; $ioRate = 0.0
    if ($script:Act.LastSample) {
        $dt = ($now - $script:Act.LastSample).TotalSeconds
        if ($dt -gt 0) {
            $cpuPct = [math]::Max(0, ($cpu - $script:Act.LastCpu) / 1e7 / $dt / [Environment]::ProcessorCount * 100)
            $ioRate = [math]::Max(0, ($io - $script:Act.LastIo) / $dt)
        }
        if ($cpuPct -ge 0.5 -or $ioRate -ge 20KB) { $script:Act.LastActive = $now }
    } else { $script:Act.LastActive = $now }
    $script:Act.LastSample = $now; $script:Act.LastCpu = $cpu; $script:Act.LastIo = $io

    $names = [System.Collections.Generic.List[string]]::new()
    foreach ($p in $tree) {
        if ($p.Name -in 'conhost.exe') { continue }
        $n = $p.Name
        if ($n -eq 'msiexec.exe' -and $p.CommandLine -match '(?i)[/-][if]\s+"?([^"]+?\.msi)') { $n += ' (' + (Split-Path $Matches[1] -Leaf) + ')' }
        if (-not $names.Contains($n)) { $names.Add($n) }
    }
    foreach ($p in $svc) {
        $n = $p.Name
        if ($p.CommandLine -match '(?i)[/-][if]\s+"?([^"]+?\.msi)') { $n += ' (' + (Split-Path $Matches[1] -Leaf) + ')' }
        $n += ' [Dienst]'
        if (-not $names.Contains($n)) { $names.Add($n) }
    }
    $procTxt = if ($names.Count) { $names -join '  >  ' } else { 'PowerShell (interne Verarbeitung / Windows-Dienste)' }
    $ui.ActProc.Text = ('Aktive Prozesse: {0}{1}Last: CPU {2:N0} %  -  Datenträger/Netz {3}' -f $procTxt, [Environment]::NewLine, $cpuPct, (Format-Rate $ioRate))

    $idle = ($now - $script:Act.LastActive)
    if ($idle.TotalSeconds -lt 30) {
        $ui.ActDot.Fill = $Brush.Green
        $script:Act.Info = 'arbeitet'
    } else {
        $ui.ActDot.Fill = $Brush.Orange
        $script:Act.Info = ('wartet - seit {0} keine messbare Aktivität (bei Downloads, Windows Update oder Installer-Dialogen normal)' -f (Format-Dur $idle))
    }
}

$timer = New-Object System.Windows.Threading.DispatcherTimer
$timer.Interval = [TimeSpan]::FromMilliseconds(400)
$timer.Add_Tick({
    if ($script:NinAudit -and $script:NinAudit.Proc.HasExited) { Complete-NiniteAudit }
    if ($script:NinAudit -and ((Get-Date) - $script:NinAudit.Start).TotalMinutes -gt 10) { try { $script:NinAudit.Proc.Kill() } catch { } }
    if (-not $script:Job) { return }
    Read-JobLog
    try {
        if ([IO.File]::Exists($script:Job.Status)) {
            $st = [IO.File]::ReadAllText($script:Job.Status) | ConvertFrom-Json
            $ui.Progress.Value = [double]$st.Progress
            $elapsed = ''
            if ($st.StepStart) { $elapsed = Format-Dur ((Get-Date) - [datetime]::Parse($st.StepStart)) }
            if ($st.Step) {
                $ui.ActStep.Text = if ($st.StepCount) { '{0}   (Schritt {1} von {2})' -f $st.Step, $st.StepNo, $st.StepCount } else { [string]$st.Step }
            } else { $ui.ActStep.Text = 'Wird vorbereitet ...' }
            $ui.ActState.Text = ('läuft seit {0}  -  {1}' -f $elapsed, $script:Act.Info)
            $det = @()
            if ($st.Status -and $st.Step -and ([string]$st.Status -notlike ('{0} (*' -f $st.Step))) { $det += [string]$st.Status }
            if ($st.Detail) { $det += [string]$st.Detail }
            $ui.ActDetail.Text = $det -join [Environment]::NewLine
            $ui.ActLast.Text = if ($st.LastLine) { 'Letzte Meldung: ' + [string]$st.LastLine } else { '' }
            $ui.StatusText.Text = ('{0}  -  seit {1}' -f $st.Status, $elapsed)
        }
    } catch { }
    Update-Activity
    if ($script:Job.Proc.HasExited) {
        Read-JobLog
        if ($script:Job.Rest) { $ui.LogBox.AppendText($script:Job.Rest + [Environment]::NewLine) }
        if (-not [IO.File]::Exists($script:Job.Log)) {
            $ui.LogBox.AppendText(('FEHLER: Hintergrundprozess beendet (Code {0}), kein Protokoll erzeugt.' -f $script:Job.Proc.ExitCode) + [Environment]::NewLine)
        }
        $ui.Progress.Value = 100
        Remove-Item $script:Job.Cancel -Force -ErrorAction SilentlyContinue
        $wasInstall = @($script:Job.Parts) -contains 'NiniteInstall'
        $jobParts = @($script:Job.Parts); $jobMode = $(try { [string]$script:Job.Mode } catch { '' })
        $script:Job = $null
        Set-Busy $false
        Update-Overview
        try {
            $lrf = Join-Path $DataDir 'lastrun.json'
            if ((Test-Path -LiteralPath $lrf) -and (Get-Item -LiteralPath $lrf).LastWriteTime -gt (Get-Date).AddMinutes(-3)) {
                $lrj = Get-Content -LiteralPath $lrf -Raw -Encoding UTF8 | ConvertFrom-Json
                if ($lrj.Neustart) { Show-RebootPrompt ('Die Pflege ist fertig ({0}). Ein installiertes Update, ein Treiber oder eine Reparatur braucht einen Neustart, damit alles wirksam wird.' -f $lrj.Teile) }
            }
        } catch { }
        if ($wasInstall) {
            foreach ($a in $script:NinApps) { $a.Check.IsChecked = $false }
            Start-NiniteAudit
        }
        try { if (Get-Command Start-AiAutoDiag -ErrorAction SilentlyContinue) { Start-AiAutoDiag $jobParts } } catch { }
    }
})

