function Update-GhReadStatus {
    if (Get-ReadToken) { $ui.GhReadStatus.Text = 'Nur-Lesen-Token ist hinterlegt - Einrichtungspakete können erstellt werden.'; $ui.GhReadStatus.Foreground = $Brush.Green }
    else { $ui.GhReadStatus.Text = 'Noch kein Nur-Lesen-Token hinterlegt. GitHub > Settings > Developer settings > Fine-grained tokens: nur Repository pc-pflege, Contents: Read-only.'; $ui.GhReadStatus.Foreground = $Brush.Gray }
}
function Save-ReadTokenGui {
    $t = $ui.GhReadToken.Password.Trim()
    if (-not $t) { return }
    $gh = Get-GitHubSource $(if ($ui.Settings_UpdateSource.Text.Trim()) { $ui.Settings_UpdateSource.Text.Trim() } else { $DefaultUpdateSource })
    if (-not $gh) { [Windows.MessageBox]::Show((T ('Die Update-Quelle ist kein GitHub-Repository.')), (T ('PC-Tools'))) | Out-Null; return }
    $window.Cursor = 'Wait'
    try { $r = Test-GitHubToken $gh.Repo $t }
    catch { $window.Cursor = $null; $ui.GhReadStatus.Text = 'Token funktioniert nicht: ' + $_.Exception.Message + ' - ist beim Token das Repository pc-pflege ausgewählt?'; $ui.GhReadStatus.Foreground = $Brush.Red; return }
    $window.Cursor = $null
    if ($r.Push) {
        $ui.GhReadStatus.Text = 'Dieser Token darf SCHREIBEN - für andere PCs bitte einen Token mit Contents: Read-only erstellen. Nicht gespeichert.'
        $ui.GhReadStatus.Foreground = $Brush.Red; return
    }
    Save-ReadToken $t
    $ui.GhReadToken.Password = ''
    Update-GhReadStatus
}
function New-SetupPackage {
    $rt = Get-ReadToken
    if (-not $rt) { [Windows.MessageBox]::Show((T ('Bitte zuerst einen Nur-Lesen-Token hinterlegen.')), (T ('PC-Tools'))) | Out-Null; return }
    Add-Type -AssemblyName System.Windows.Forms
    $d = New-Object System.Windows.Forms.FolderBrowserDialog
    $d.Description = 'Wohin soll das Einrichtungspaket? (z.B. NAS-Ordner oder USB-Stick)'
    $d.SelectedPath = [Environment]::GetFolderPath('Desktop')
    if ($d.ShowDialog() -ne 'OK') { return }
    $dir = Join-Path $d.SelectedPath 'PC-Tools Einrichtung'
    try {
        New-Item $dir -ItemType Directory -Force | Out-Null
        foreach ($n in $UpdateFiles) {
            $f = Join-Path $PSScriptRoot $n
            if (-not (Test-Path -LiteralPath $f)) { $f = Join-Path $DataDir $n }
            if (Test-Path -LiteralPath $f) { Copy-Item -LiteralPath $f -Destination (Join-Path $dir $n) -Force }
        }
        Set-Content -LiteralPath (Join-Path $dir 'pcpflege.token') -Value (Protect-PkgToken $rt) -Encoding ASCII
        Set-Content -LiteralPath (Join-Path $dir 'Einrichten.cmd') -Encoding ASCII -Value @('@echo off', 'title PC-Tools einrichten', 'echo PC-Tools wird eingerichtet - bitte die Administrator-Abfrage bestaetigen ...', 'powershell.exe -NoProfile -ExecutionPolicy Bypass -WindowStyle Hidden -File "%~dp0PCPflege.ps1" -Install')
        Set-Content -LiteralPath (Join-Path $dir 'LIES MICH.txt') -Encoding UTF8 -Value @(
            'PC-Tools einrichten', '', 'Auf dem PC doppelt auf "Einrichten.cmd" klicken und die Administrator-Abfrage bestätigen.',
            'PC-Tools wird installiert (oder auf diese Version aktualisiert), Update-Quelle und Zugangs-Token werden automatisch übernommen.',
            'Danach aktualisiert sich PC-Tools selbst.', '', 'Achtung: Der Ordner enthält einen Lese-Zugang zum privaten Repository - nur auf eigenem NAS oder Stick aufbewahren, nicht weitergeben.',
            ('Erstellt am {0:dd.MM.yyyy HH:mm} mit PC-Tools {1}' -f (Get-Date), $AppVersion))
        $ui.StatusText.Text = 'Einrichtungspaket erstellt: ' + $dir
        Start-Process explorer.exe ('"{0}"' -f $dir)
    } catch { [Windows.MessageBox]::Show((T ('Paket konnte nicht erstellt werden: ' + $_.Exception.Message)), (T ('PC-Tools')), 'OK', 'Warning') | Out-Null }
}
