    if ($d.ShowDialog() -eq 'OK') { @($script:DrvAll) | Select-Object Name, ClassDe, Maker, Provider, Version, Date, AgeText, Status, Inf, HwId | Export-Csv -LiteralPath $d.FileName -NoTypeInformation -Delimiter ';' -Encoding UTF8; $ui.StatusText.Text = 'Treiberliste gespeichert: ' + $d.FileName }
})
