$ui.BtnDrvAddFolder.Add_Click({
    Add-Type -AssemblyName System.Windows.Forms; $d = New-Object System.Windows.Forms.FolderBrowserDialog; $d.Description = 'Ordner mit Treibern (.inf) - Unterordner werden mit durchsucht, z.B. eine Treiber-Sicherung'
    if ($d.ShowDialog() -ne 'OK') { return }
    if (-not (Confirm-Ui ("Alle Treiber (.inf) aus`n{0}`nund Unterordnern installieren? Windows nimmt nur Treiber, die zu vorhandenen Geräten passen." -f $d.SelectedPath))) { return }
    $o = & (Join-Path $env:windir 'System32\pnputil.exe') /add-driver (Join-Path $d.SelectedPath '*.inf') /subdirs /install 2>&1
    $ui.StatusText.Text = 'pnputil: ' + (($o | Where-Object { $_ -match '\d' } | Select-Object -Last 2) -join ' ')
    Update-DrvInventory
})
