$ui.Tabs.Add_SelectionChanged({
    param($s, $e)
    if ($e.OriginalSource -ne $s) { return }
    if ($s.SelectedItem -eq $ui.TabDebloat -and -not $script:BloatLoaded) { $script:BloatLoaded = $true; Update-Bloat }
    elseif ($s.SelectedItem -eq $ui.TabPrivacy -and -not $script:PrivLoaded) { $script:PrivLoaded = $true; try { Update-Privacy } catch { $ui.StatusText.Text = 'Datenschutz: ' + $_.Exception.Message } }
    elseif ($s.SelectedItem -eq $ui.TabNet -and -not $script:NetLoaded) { $script:NetLoaded = $true; Update-NetPage }
    elseif ($s.SelectedItem -eq $ui.TabSpace -and -not $ui.SpcRoot.Text) { $ui.SpcRoot.Text = $env:SystemDrive + '\' }
})
