    $sel = @($ui.BloatList.Children | ForEach-Object { $_.Children[0] } | Where-Object { $_.IsChecked } | ForEach-Object { $_.Tag })
    if (-not $sel.Count) { Show-UiError 'Bitte Apps auswählen (Schnellwahl oben).'; return }
    if (-not (Confirm-Ui ("{0} Apps entfernen?`n`n{1}`n`nVorher wird ein Wiederherstellungspunkt gesetzt; Apps lassen sich im Store wiederholen." -f $sel.Count, (($sel | Select-Object -First 30 | ForEach-Object { '  - ' + $_.Name }) -join "`n")))) { return }
    Start-Run -Parts @('Debloat') -Job @{ Apps = @($sel | Where-Object Kind -eq 'App' | ForEach-Object { $_.Id }); Win32 = @($sel | Where-Object Kind -eq 'Programm' | ForEach-Object { $_.Id }); Provisioned = [bool]$ui.BloatProv.IsChecked }
