        $i = [math]::Max(0, $ui.PrivCap.SelectedIndex); if ($i -eq 0) { Show-UiError 'Bitte oben links eine Berechtigung wählen (z.B. Mikrofon).'; return }
        $cap = @($PrivacyCaps.Keys)[$i - 1]
        foreach ($root in 'HKCU:', 'HKLM:') { $k = "$root\Software\Microsoft\Windows\CurrentVersion\CapabilityAccessManager\ConsentStore\$cap"; if (Test-Path $k) { Set-ItemProperty $k -Name Value -Value ([string]$s.Tag) -Type String -ErrorAction SilentlyContinue } }
        $ui.StatusText.Text = '{0}: für alle Apps {1}' -f $PrivacyCaps[$cap], $(if ($s.Tag -eq 'Deny') { 'ausgeschaltet' } else { 'erlaubt' }); Update-PrivApps })
}
