# ---------------------------------------------------------------- Lizenzen (Oberfläche)
$script:LicWin = $null; $script:LicShowKeys = $false; $script:LicVault = @()
function Get-LicMasked([string]$Key) {
    if (-not $Key) { return '' }
    if ($script:LicShowKeys) { return $Key }
    if ($Key.Length -le 6) { return '******' }
    return ($Key.Substring(0, 5) + ('*' * [math]::Min(20, $Key.Length - 10)) + $Key.Substring($Key.Length - 5))
}
function Get-LicAdvice($w) {
    $t = @()
    if ($w.InstalledNote) {
        $t += 'Digitale Lizenz: Windows ist über die Hardware-ID bzw. dein Microsoft-Konto aktiviert - es gibt keinen eigenen Schlüssel zum Abschreiben (der installierte ist ein allgemeiner Standard-Schlüssel).'
        $t += 'Umzug: Konto unter "Mit Microsoft-Konto verknüpfen" prüfen. Auf dem neuen PC mit demselben Konto anmelden. Ist die Lizenz eine übertragbare Retail-Lizenz, dort unter Aktivierung > Problembehandlung > "Ich habe kürzlich die Hardware geändert" dieses Gerät auswählen.'
    } elseif ($w.Channel -match 'OEM') {
        $t += 'OEM-Lizenz: sie gehört fest zu diesem Gerät (meist Schlüssel im BIOS) und darf nicht auf einen anderen PC umziehen. Der neue PC bringt in der Regel seine eigene Lizenz mit.'
    } elseif ($w.Channel -match 'Retail') {
        $t += 'Einzelhandels-Lizenz (Retail): darf umziehen, aber nur auf einem PC gleichzeitig aktiv sein.'
        $t += 'Umzug: 1. Schlüssel in den Tresor übernehmen und exportieren. 2. Hier "Lizenz von diesem PC lösen". 3. Auf dem neuen PC den Schlüssel eintragen und aktivieren (klappt die Online-Aktivierung nicht: Aktivierung > Problembehandlung oder telefonisch).'
    } elseif ($w.Channel -match 'Volume|KMS|MAK|GVLK') {
        $t += 'Volumenlizenz: gehört der Firma bzw. Organisation - nicht privat übertragbar.'
    } else { $t += 'Lizenzart nicht eindeutig. Im Zweifel den Schlüssel sichern und das Microsoft-Konto verknüpfen.' }
    if ($w.Firmware) { $t += ('Im BIOS/UEFI steckt ein Schlüssel für {0} - Windows nutzt ihn bei einer Neuinstallation auf diesem Gerät automatisch.' -f $(if ($w.FirmwareDesc) { $w.FirmwareDesc } else { 'Windows' })) }
    if ($w.Status -ne 'aktiviert') { $t += 'ACHTUNG: Windows ist derzeit nicht aktiviert (' + $w.Status + ').' }
    return ($t -join "`n")
}
function Update-LicPage {
    foreach ($n in 'LicWinName', 'LicWinStatus', 'LicWinKind', 'LicWinKey', 'LicWinFw', 'LicWinPid') { $ui[$n].Text = '...' }
    $ui.LicWinAdvice.Text = 'Lizenzen werden ausgelesen ...'
    Invoke-Bg -Script { param($h) $GenericWinKeys = $h.G; $LicenseKnowledge = $h.K
        $w = $null; $o = @(); $s = @()
        try { $w = Get-WindowsLicense } catch { }
        try { $o = @(Get-OfficeLicenses) } catch { }
        try { $s = @(Get-SoftwareLicenses) } catch { }
        [pscustomobject]@{ Win = $w; Office = $o; Soft = $s }
    } -Arguments @(@{ G = $GenericWinKeys; K = $LicenseKnowledge }) -Functions @('ConvertFrom-DigitalProductId', 'Get-WindowsLicense', 'Get-OfficeLicenses', 'Get-SoftwareLicenses') -Done {
        param($r, $err)
        if ($err) { $ui.LicWinAdvice.Text = 'Nicht lesbar: ' + $err.Message; return }
        $x = @($r | Where-Object { $_ })[0]; $w = $x.Win; $script:LicWin = $w
        if ($w) {
            $ui.LicWinName.Text = '{0} ({1}), Build {2}' -f $w.Name, $w.Edition, $w.Build
            $ui.LicWinStatus.Text = $w.Status; $ui.LicWinStatus.Foreground = $(if ($w.Status -eq 'aktiviert') { $Brush.Green } else { $Brush.Red })
            $ui.LicWinKind.Text = $w.Kind
            $ui.LicWinKey.Text = $(if ($w.InstalledNote) { '{0}  ({1})' -f $w.Installed, $w.InstalledNote } elseif ($w.Installed) { $w.Installed } else { 'XXXXX-XXXXX-XXXXX-XXXXX-' + $w.Partial })
            $ui.LicWinFw.Text = $(if ($w.Firmware) { '{0}  ({1})' -f $w.Firmware, $w.FirmwareDesc } else { 'keiner (normal bei selbst gebauten PCs und Retail)' })
            $ui.LicWinPid.Text = $w.ProductId
            $ui.LicWinAdvice.Text = Get-LicAdvice $w
        } else { $ui.LicWinAdvice.Text = 'Windows-Lizenz konnte nicht gelesen werden.' }
        $script:LicOffice = @($x.Office | ForEach-Object { $_ } | Where-Object { $_ })
        Set-GridItems $ui.LicOffGrid $script:LicOffice
        $script:LicSoft = @($x.Soft | ForEach-Object { $_ } | Where-Object { $_ })
        Set-GridItems $ui.LicSwGrid $script:LicSoft
        $ui.StatusText.Text = 'Lizenzen: Windows, {0} Office-Einträge, {1} Programme mit bekannter Lizenzart.' -f $script:LicOffice.Count, $script:LicSoft.Count
    }
    Update-LicVault
}
function Update-LicVault {
    try { $script:LicVault = @(Read-LicVault) } catch { $script:LicVault = @(); Show-UiError $_.Exception.Message }
    $rows = foreach ($v in $script:LicVault) { [pscustomobject]@{ Name = [string]$v.Name; Key = [string]$v.Key; KeyShow = (Get-LicMasked ([string]$v.Key)); FileName = [string]$v.FileName; FileData = [string]$v.FileData; Note = [string]$v.Note; Added = [string]$v.Added } }
    Set-GridItems $ui.LicVaultGrid @($rows)
}
function Save-LicVaultRows($Rows) {
    Save-LicVault @($Rows | ForEach-Object { [pscustomobject]@{ Name = $_.Name; Key = $_.Key; FileName = $_.FileName; FileData = $_.FileData; Note = $_.Note; Added = $_.Added } })
    Update-LicVault
}
function Add-LicVaultItem([string]$Name, [string]$Key, [string]$Note, [string]$FileName = '', [string]$FileData = '') {
    $all = @($script:LicVault)
    if (@($all | Where-Object { $_.Name -eq $Name -and [string]$_.Key -eq $Key -and [string]$_.FileName -eq $FileName }).Count) { $ui.StatusText.Text = '"' + $Name + '" ist schon im Tresor.'; return }
    $all += [pscustomobject]@{ Name = $Name; Key = $Key; FileName = $FileName; FileData = $FileData; Note = $Note; Added = (Get-Date).ToString('dd.MM.yyyy') }
    Save-LicVaultRows $all
    $ui.StatusText.Text = '"' + $Name + '" im Lizenz-Tresor gespeichert (verschlüsselt mit deinem Windows-Konto).'
}
function Invoke-Slmgr([string[]]$ArgList, [string]$Title) {
    $ui.LicSlmgrOut.Text = $Title + ' ...'
    Invoke-Bg -Script { param($a) $out = @(); foreach ($x in $a) { $out += (& cscript.exe //nologo (Join-Path $env:windir 'System32\slmgr.vbs') @($x -split ' ') 2>&1) -join ' ' }; $out -join "`n" } -Arguments @(, $ArgList) -Done {
        param($r, $err)
        $ui.LicSlmgrOut.Text = if ($err) { $err.Message } else { (@($r) -join "`n").Trim() }
        Update-LicPage
    }
}
function Get-OsppPath {
    foreach ($b in @($env:ProgramFiles, ${env:ProgramFiles(x86)})) { foreach ($v in 'Office16', 'Office15') { $p = Join-Path $b ('Microsoft Office\' + $v + '\OSPP.VBS'); if ($b -and (Test-Path -LiteralPath $p)) { return $p } } }
    return $null
}
function Export-LicReport {
    Add-Type -AssemblyName System.Windows.Forms
    $d = New-Object System.Windows.Forms.SaveFileDialog; $d.Filter = 'Textdatei (*.txt)|*.txt'; $d.FileName = ('Lizenzen_{0}_{1:yyyy-MM-dd}.txt' -f $env:COMPUTERNAME, (Get-Date))
    if ($d.ShowDialog() -ne 'OK') { return }
    $plain = Confirm-Ui "Schlüssel im Klartext in die Datei schreiben?`n`nJa = vollständige Schlüssel (Datei danach sicher aufbewahren!)`nNein = Schlüssel gekürzt"
    $mask = { param($k) if ($plain -or -not $k -or $k.Length -lt 10) { $k } else { $k.Substring(0, 5) + '-*****-*****-*****-' + $k.Substring($k.Length - 5) } }
    $w = $script:LicWin; $L = @()
    $L += 'Lizenzübersicht {0} - erstellt {1:dd.MM.yyyy HH:mm} mit PC-Tools {2}' -f $env:COMPUTERNAME, (Get-Date), $AppVersion
    $L += ('=' * 70); $L += 'WINDOWS'
    if ($w) {
        $L += '  Version:       {0} ({1}), Build {2}' -f $w.Name, $w.Edition, $w.Build
        $L += '  Aktivierung:   ' + $w.Status; $L += '  Lizenzart:     ' + $w.Kind
        $L += '  Schlüssel:     ' + $(if ($w.InstalledNote) { $w.Installed + ' (' + $w.InstalledNote + ')' } else { & $mask $w.Installed })
        $L += '  BIOS/UEFI:     ' + $(if ($w.Firmware) { (& $mask $w.Firmware) + ' (' + $w.FirmwareDesc + ')' } else { '-' })
        $L += '  Produkt-ID:    ' + $w.ProductId; $L += ''; $L += '  ' + ((Get-LicAdvice $w) -replace "`n", "`n  ")
    }
    $L += ''; $L += 'OFFICE'
    if (@($script:LicOffice).Count) { foreach ($o in $script:LicOffice) { $L += '  - {0} | {1} | {2} | {3}' -f $o.Product, $o.Type, $o.Key, $o.Status; $L += '    Umzug: ' + $o.Transfer } } else { $L += '  keine Office-Lizenz gefunden' }
    $L += ''; $L += 'WEITERE PROGRAMME'
    if (@($script:LicSoft).Count) { foreach ($s in $script:LicSoft) { $L += '  - {0} {1} ({2}): {3}{4}' -f $s.Program, $s.Version, $s.Kind, $s.Hint, $(if ($s.File) { ' Datei: ' + $s.File } else { '' }) } } else { $L += '  keine bekannten Programme gefunden' }
    $L += ''; $L += 'LIZENZ-TRESOR'
    if (@($script:LicVault).Count) { foreach ($v in $script:LicVault) { $L += '  - {0}: {1}{2}{3}' -f $v.Name, $(if ($v.Key) { & $mask ([string]$v.Key) } else { '-' }), $(if ($v.FileName) { ' | Datei: ' + $v.FileName } else { '' }), $(if ($v.Note) { ' | ' + $v.Note } else { '' }) } } else { $L += '  leer' }
    Set-Content -LiteralPath $d.FileName -Value ($L -join "`r`n") -Encoding UTF8
    $ui.StatusText.Text = 'Lizenzübersicht gespeichert: ' + $d.FileName
    Start-Process notepad.exe ('"{0}"' -f $d.FileName)
}

$ui.Tabs.Add_SelectionChanged({
    param($s, $e)
    if ($e.OriginalSource -ne $s -or $s.SelectedItem -ne $ui.TabLic -or $script:LicLoaded) { return }
    $script:LicLoaded = $true; Update-LicPage
})
$ui.BtnLicCopyKey.Add_Click({
    $w = $script:LicWin; if (-not $w) { return }
    $k = if ($w.InstalledNote -and $w.Firmware) { $w.Firmware } else { $w.Installed }
    if (-not $k) { Show-UiError 'Der vollständige Schlüssel ist nicht auslesbar (nur die letzten 5 Zeichen sind gespeichert).'; return }
    Set-Clipboard -Value $k; $ui.StatusText.Text = 'Windows-Schlüssel kopiert' + $(if ($w.InstalledNote -and $w.Firmware) { ' (BIOS-Schlüssel)' } elseif ($w.InstalledNote) { ' - Hinweis: das ist nur der allgemeine Standard-Schlüssel, die Lizenz ist digital.' } else { '.' })
})
$ui.BtnLicToVault.Add_Click({
    $w = $script:LicWin; if (-not $w) { return }
    $n = 0
    if ($w.Installed -and -not $w.InstalledNote) { Add-LicVaultItem ('Windows ' + $w.Edition) $w.Installed ($w.Kind + ', von ' + $env:COMPUTERNAME); $n++ }
    if ($w.Firmware) { Add-LicVaultItem ('Windows (BIOS) ' + $w.FirmwareDesc) $w.Firmware ('OEM-Schlüssel aus dem BIOS von ' + $env:COMPUTERNAME + ' - gilt nur für dieses Gerät'); $n++ }
    if (-not $n) { [Windows.MessageBox]::Show((T ('Diese Windows-Lizenz ist digital (an Hardware bzw. Microsoft-Konto gebunden) - es gibt keinen Schlüssel zum Sichern. Wichtig ist, dass dein Microsoft-Konto verknüpft ist (Knopf daneben).')), (T ('PC-Tools')), 'OK', 'Information') | Out-Null }
})
$ui.BtnLicActivation.Add_Click({ Start-Process 'ms-settings:activation' })
$ui.BtnLicAccount.Add_Click({ Start-Process 'https://account.microsoft.com/devices' })
$ui.BtnLicRelease.Add_Click({
    $w = $script:LicWin
    if ($w -and $w.Channel -match 'OEM') { Show-UiError 'OEM-Lizenzen gehören zum Gerät und können nicht umziehen - Lösen bringt hier nichts.'; return }
    if ($w -and $w.InstalledNote) { if (-not (Confirm-Ui 'Die Lizenz ist digital. Lösen ist meist nicht nötig - auf dem neuen PC genügt die Anmeldung mit dem Microsoft-Konto. Trotzdem fortfahren?' 'Warning')) { return } }
    $r = Show-InputDialog 'Lizenz lösen' "Windows wird auf diesem PC DEAKTIVIERT (Schlüssel entfernen, slmgr /upk und /cpky). Danach läuft Windows hier unaktiviert mit Wasserzeichen.`n`nVorher den Schlüssel sichern! Zum Bestätigen LÖSEN eintippen:" @(@{ Key = 'C'; Label = 'Bestätigung'; Type = 'Text' })
    if (-not $r -or $r.C -cne 'LÖSEN') { return }
    Invoke-Slmgr @('/upk', '/cpky') 'Lizenz wird gelöst'
})
$ui.BtnLicActivate.Add_Click({
    $k = $ui.LicNewKey.Text.Trim().ToUpper()
    if ($k -notmatch '^[A-Z0-9]{5}(-[A-Z0-9]{5}){4}$') { Show-UiError 'Bitte einen Schlüssel im Format XXXXX-XXXXX-XXXXX-XXXXX-XXXXX eingeben.'; return }
    if (-not (Confirm-Ui ('Schlüssel {0} installieren und Windows online aktivieren?' -f $k))) { return }
    Invoke-Slmgr @("/ipk $k", '/ato') 'Schlüssel wird installiert und aktiviert'
    $ui.LicNewKey.Text = ''
})
$ui.BtnLicOffRemove.Add_Click({
    $r = $ui.LicOffGrid.SelectedItem
    if (-not $r) { Show-UiError 'Bitte eine Office-Lizenz auswählen.'; return }
    if (-not $r.Partial) { Show-UiError 'Diese Office-Version hängt am Microsoft-Konto: in Office unter Datei > Konto abmelden bzw. unter account.microsoft.com/services die Installation deaktivieren.'; Start-Process 'https://account.microsoft.com/services'; return }
    $os = Get-OsppPath; if (-not $os) { Show-UiError 'OSPP.VBS wurde nicht gefunden.'; return }
    if (-not (Confirm-Ui ("Office-Lizenz {0} (…{1}) von diesem PC entfernen? Office läuft hier danach unlizenziert.`nSchlüssel vorher gesichert?" -f $r.Product, $r.Partial) 'Warning')) { return }
    $o = (& cscript.exe //nologo $os ('/unpkey:' + $r.Partial) 2>&1) -join "`n"
    $ui.LicSlmgrOut.Text = $o.Trim(); Update-LicPage
})
$ui.BtnLicOffAccount.Add_Click({ Start-Process 'https://account.microsoft.com/services' })
$ui.BtnLicSwFile.Add_Click({
    $r = $ui.LicSwGrid.SelectedItem
    if (-not $r -or -not $r.HasFile) { Show-UiError 'Bitte ein Programm mit Lizenzdatei auswählen (Spalte "Lizenzdatei").'; return }
    foreach ($f in @($r.File -split '; ' | Where-Object { $_ })) {
        try { $b = [IO.File]::ReadAllBytes($f); Add-LicVaultItem ($r.Program + ' - Lizenzdatei') '' ('Original: ' + $f) (Split-Path $f -Leaf) ([Convert]::ToBase64String($b)) } catch { Show-UiError ('{0}: {1}' -f $f, $_.Exception.Message) }
    }
})
$ui.BtnLicSwAdd.Add_Click({ $r = $ui.LicSwGrid.SelectedItem; if ($r) { $ui.LicVName.Text = $r.Program; $ui.LicVNote.Text = $r.Hint; $ui.LicVKey.Text = ''; [void]$ui.LicVKey.Focus(); $ui.StatusText.Text = 'Schlüssel unten eintragen und "Hinzufügen" klicken.' } })
$ui.BtnLicVAdd.Add_Click({
    $n = $ui.LicVName.Text.Trim(); $k = $ui.LicVKey.Text.Trim()
    if (-not $n) { Show-UiError 'Bitte einen Namen eingeben.'; return }
    if (-not $k -and -not $ui.LicVNote.Text.Trim()) { Show-UiError 'Bitte einen Schlüssel oder eine Notiz eingeben.'; return }
    Add-LicVaultItem $n $k $ui.LicVNote.Text.Trim()
    $ui.LicVName.Text = ''; $ui.LicVKey.Text = ''; $ui.LicVNote.Text = ''
})
$ui.BtnLicVShow.Add_Click({ $script:LicShowKeys = -not $script:LicShowKeys; $ui.BtnLicVShow.Content = $(if ($script:LicShowKeys) { 'Schlüssel verbergen' } else { 'Schlüssel anzeigen' }); Update-LicVault })
$ui.BtnLicVCopy.Add_Click({ $r = $ui.LicVaultGrid.SelectedItem; if ($r -and $r.Key) { Set-Clipboard -Value $r.Key; $ui.StatusText.Text = 'Schlüssel von "' + $r.Name + '" kopiert.' } elseif ($r) { Show-UiError 'Dieser Eintrag hat keinen Schlüssel.' } })
$ui.BtnLicVSaveFile.Add_Click({
    $r = $ui.LicVaultGrid.SelectedItem
    if (-not $r -or -not $r.FileData) { Show-UiError 'Bitte einen Eintrag mit Lizenzdatei auswählen.'; return }
    $orig = if ($r.Note -match '^Original: (.+)$') { $Matches[1] } else { '' }
    Add-Type -AssemblyName System.Windows.Forms
    $d = New-Object System.Windows.Forms.SaveFileDialog; $d.FileName = $r.FileName; $d.Filter = 'Alle Dateien (*.*)|*.*'
    if ($orig) { $dir = Split-Path $orig -Parent; if (Test-Path -LiteralPath $dir) { $d.InitialDirectory = $dir } }
    if ($d.ShowDialog() -ne 'OK') { return }
    try { [IO.File]::WriteAllBytes($d.FileName, [Convert]::FromBase64String($r.FileData)); $ui.StatusText.Text = 'Lizenzdatei gespeichert: ' + $d.FileName } catch { Show-UiError ('Speichern fehlgeschlagen (Programmordner brauchen Adminrechte): ' + $_.Exception.Message) }
})
$ui.BtnLicVDel.Add_Click({
    $r = $ui.LicVaultGrid.SelectedItem; if (-not $r) { return }
    if (-not (Confirm-Ui ('"{0}" aus dem Tresor entfernen?' -f $r.Name))) { return }
    Save-LicVaultRows @($ui.LicVaultGrid.ItemsSource | Where-Object { $_ -ne $r })
})
$ui.BtnLicVExport.Add_Click({
    $p = $ui.LicVPwd.Password
    if ($p.Length -lt 8) { Show-UiError 'Bitte ein Kennwort mit mindestens 8 Zeichen eingeben - damit wird die Exportdatei verschlüsselt (AES-256).'; return }
    if (-not @($script:LicVault).Count) { Show-UiError 'Der Tresor ist leer. Erst Schlüssel oder Lizenzdateien hinzufügen.'; return }
    Add-Type -AssemblyName System.Windows.Forms
    $d = New-Object System.Windows.Forms.SaveFileDialog; $d.Filter = 'PC-Tools Lizenzen (*.pclic)|*.pclic'; $d.FileName = ('Lizenzen_{0}_{1:yyyy-MM-dd}.pclic' -f $env:COMPUTERNAME, (Get-Date))
    if ($d.ShowDialog() -ne 'OK') { return }
    try {
        $j = ConvertTo-Json -InputObject @($script:LicVault) -Depth 4 -Compress
        [IO.File]::WriteAllBytes($d.FileName, (Protect-WithPassword ([Text.Encoding]::UTF8.GetBytes($j)) $p))
        $ui.LicVPwd.Password = ''
        [Windows.MessageBox]::Show((T (("{0} Einträge verschlüsselt exportiert:`n{1}`n`nAuf dem neuen PC: PC-Tools > Lizenzen > Import, gleiches Kennwort eingeben. Das Kennwort NICHT zusammen mit der Datei aufbewahren." -f @($script:LicVault).Count, $d.FileName))), (T ('PC-Tools')), 'OK', 'Information') | Out-Null
    } catch { Show-UiError ('Export fehlgeschlagen: ' + $_.Exception.Message) }
})
$ui.BtnLicVImport.Add_Click({
    $p = $ui.LicVPwd.Password
    if (-not $p) { Show-UiError 'Bitte zuerst das Kennwort der Exportdatei eingeben.'; return }
    Add-Type -AssemblyName System.Windows.Forms
    $d = New-Object System.Windows.Forms.OpenFileDialog; $d.Filter = 'PC-Tools Lizenzen (*.pclic)|*.pclic|Alle Dateien (*.*)|*.*'
    if ($d.ShowDialog() -ne 'OK') { return }
    try {
        $data = Unprotect-WithPassword ([IO.File]::ReadAllBytes($d.FileName)) $p
        $items = @(([Text.Encoding]::UTF8.GetString($data) | ConvertFrom-Json) | ForEach-Object { $_ })
        $all = @($script:LicVault); $new = 0
        foreach ($i in $items) { if (-not @($all | Where-Object { $_.Name -eq $i.Name -and [string]$_.Key -eq [string]$i.Key -and [string]$_.FileName -eq [string]$i.FileName }).Count) { $all += $i; $new++ } }
        Save-LicVaultRows $all; $ui.LicVPwd.Password = ''
        [Windows.MessageBox]::Show((T (("{0} Einträge gelesen, {1} neu im Tresor.`n`nWindows-Schlüssel: oben eintragen und aktivieren. Lizenzdateien: Eintrag wählen > ""Datei speichern unter"" (in den Programmordner)." -f $items.Count, $new))), (T ('PC-Tools')), 'OK', 'Information') | Out-Null
    } catch { Show-UiError $_.Exception.Message }
})
$ui.BtnLicReport.Add_Click({ Export-LicReport })


# ---------------------------------------------------------------- PDF-Bericht
$PdfReportScript = {
    param($h)
    $GenericWinKeys = $h.G
    function E($s) { [Net.WebUtility]::HtmlEncode([string]$s) }
    function Row($k, $v) { '<tr><th>{0}</th><td>{1}</td></tr>' -f (E $k), (E $v) }
    function Bar([double]$Pct, [string]$Col) { '<div class="bar"><div style="width:{0}%;background:{1}"></div></div>' -f [math]::Round([math]::Max(0, [math]::Min(100, $Pct))), $Col }
    $os = Get-CimInstance Win32_OperatingSystem; $cs = Get-CimInstance Win32_ComputerSystem; $bios = Get-CimInstance Win32_BIOS
    $reg = Get-ItemProperty 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion'
    $cpu = @(Get-CimInstance Win32_Processor)[0]; $gpu = @(Get-CimInstance Win32_VideoController | Where-Object { $_.Name -notmatch 'Basic Display|Remote|Virtual' } | ForEach-Object { $_.Name + ' (Treiber ' + $_.DriverVersion + ')' })
    $items = @(); try { $items = @(Get-HealthItems $h.A | Where-Object { $_ }) } catch { }
    $state = if (@($items | Where-Object Level -eq 'Red').Count) { 'Red' } elseif (@($items | Where-Object Level -eq 'Yellow').Count) { 'Yellow' } else { 'Green' }
    $stTxt = @{ Red = 'Handlungsbedarf'; Yellow = 'Kleinigkeiten zu erledigen'; Green = 'Alles in Ordnung' }[$state]
    $stCol = @{ Red = '#DC2626'; Yellow = '#D97706'; Green = '#16A34A' }[$state]
    $HT = [System.Collections.Generic.List[string]]::new()
    $HT.Add('<!DOCTYPE html><html lang="de"><head><meta charset="utf-8"><title>PC-Bericht ' + (E $env:COMPUTERNAME) + '</title><style>')
    $HT.Add('@page{size:A4;margin:14mm} body{font-family:"Segoe UI",Arial,sans-serif;color:#1F2A44;font-size:10.5pt;margin:0} h1{font-size:22pt;margin:0} h2{font-size:13pt;margin:18px 0 6px;padding-bottom:3px;border-bottom:2px solid #2D7FF9;page-break-after:avoid}')
    $HT.Add('.hero{background:linear-gradient(120deg,#1E3A8A,#2D7FF9);color:#fff;border-radius:12px;padding:18px 22px;display:flex;justify-content:space-between;align-items:center} .hero small{opacity:.8} .badge{border-radius:30px;padding:8px 18px;font-weight:600;background:#fff}')
    $HT.Add('table{border-collapse:collapse;width:100%;page-break-inside:auto} tr{page-break-inside:avoid} th,td{text-align:left;padding:4px 8px;border-bottom:1px solid #E2E7F0;vertical-align:top} th{width:32%;color:#475569;font-weight:600} table.grid th{width:auto;background:#F4F6FA}')
    $HT.Add('.dot{display:inline-block;width:10px;height:10px;border-radius:5px;margin-right:6px} .bar{height:8px;background:#E3E8F2;border-radius:4px;overflow:hidden;min-width:120px} .bar div{height:8px} .muted{color:#6B7890;font-size:9pt} .cols{display:flex;gap:18px} .cols>div{flex:1}')
    $HT.Add('</style></head><body>')
    $HT.Add(('<div class="hero"><div><h1>PC-Bericht {0}</h1><small>{1} {2} &middot; erstellt am {3:dd.MM.yyyy HH:mm} mit PC-Tools {4}</small></div><div class="badge" style="color:{5}"><span class="dot" style="background:{5}"></span>{6}</div></div>' -f (E $env:COMPUTERNAME), (E $cs.Manufacturer), (E $cs.Model), (Get-Date), (E $h.V), $stCol, (E $stTxt)))
    # Zustand
    $HT.Add('<h2>Zustand (Ampel)</h2>')
    if ($items.Count) { $HT.Add('<table class="grid"><tr><th></th><th>Punkt</th><th>Was tun?</th></tr>'); foreach ($i in $items) { $c = @{ Red = '#DC2626'; Yellow = '#D97706'; Green = '#16A34A' }[[string]$i.Level]; if (-not $c) { $c = '#6B7890' }; $HT.Add(('<tr><td><span class="dot" style="background:{0}"></span></td><td><b>{1}</b></td><td>{2}</td></tr>' -f $c, (E $i.Text), (E $i.Detail))) }; $HT.Add('</table>') } else { $HT.Add('<p>Keine Auffälligkeiten.</p>') }
    # System
    $HT.Add('<h2>System</h2><table>')
    $HT.Add((Row 'Windows' ('{0} {1} (Build {2}.{3})' -f $os.Caption, $reg.DisplayVersion, $reg.CurrentBuild, $reg.UBR)))
    $HT.Add((Row 'Installiert am' $os.InstallDate.ToString('dd.MM.yyyy'))); $HT.Add((Row 'Letzter Start' ('{0:dd.MM.yyyy HH:mm} (seit {1:N1} Tagen)' -f $os.LastBootUpTime, ((Get-Date) - $os.LastBootUpTime).TotalDays)))
    $HT.Add((Row 'Gerät' ('{0} {1}' -f $cs.Manufacturer, $cs.Model))); $HT.Add((Row 'Seriennummer' $bios.SerialNumber)); $HT.Add((Row 'BIOS/UEFI' ('{0} vom {1:dd.MM.yyyy}' -f $bios.SMBIOSBIOSVersion, $bios.ReleaseDate)))
    $HT.Add((Row 'Prozessor' ('{0} ({1} Kerne / {2} Threads)' -f $cpu.Name.Trim(), $cpu.NumberOfCores, $cpu.NumberOfLogicalProcessors)))
    $HT.Add((Row 'Arbeitsspeicher' ('{0:N0} GB' -f ($cs.TotalPhysicalMemory / 1GB)))); $HT.Add((Row 'Grafik' ($gpu -join '; ')))
    $HT.Add('</table>')
    # Laufwerke
    $HT.Add('<h2>Laufwerke</h2><table class="grid"><tr><th>Laufwerk</th><th>Größe</th><th>Frei</th><th style="width:30%">Belegung</th></tr>')
    foreach ($v in @(Get-Volume -ErrorAction SilentlyContinue | Where-Object { $_.DriveLetter -and $_.Size -gt 1GB } | Sort-Object DriveLetter)) {
        $used = 100 - $v.SizeRemaining * 100 / $v.Size
        $HT.Add(('<tr><td>{0}: {1}</td><td>{2:N0} GB</td><td>{3:N0} GB</td><td>{4}</td></tr>' -f $v.DriveLetter, (E $v.FileSystemLabel), ($v.Size / 1GB), ($v.SizeRemaining / 1GB), (Bar $used $(if ($used -gt 90) { '#DC2626' } elseif ($used -gt 80) { '#D97706' } else { '#2D7FF9' }))))
    }
    $HT.Add('</table><table class="grid" style="margin-top:8px"><tr><th>Datenträger</th><th>Art</th><th>Zustand</th><th>Verschleiß</th><th>Temperatur</th></tr>')
    foreach ($pd in @(Get-PhysicalDisk -ErrorAction SilentlyContinue)) {
        $rc = $null; try { $rc = $pd | Get-StorageReliabilityCounter -ErrorAction Stop } catch { }
        $HT.Add(('<tr><td>{0} ({1:N0} GB)</td><td>{2} {3}</td><td>{4}</td><td>{5}</td><td>{6}</td></tr>' -f (E $pd.FriendlyName), ($pd.Size / 1GB), $pd.MediaType, $pd.BusType, $(if ([string]$pd.HealthStatus -eq 'Healthy') { 'gesund' } else { E $pd.HealthStatus }), $(if ($rc -and $null -ne $rc.Wear) { [string]$rc.Wear + ' %' } else { '-' }), $(if ($rc -and $rc.Temperature) { [string]$rc.Temperature + ' &deg;C' } else { '-' })))
    }
    $HT.Add('</table>')
    # Akku
    try {
        $des = @(Get-CimInstance -Namespace root\wmi -ClassName BatteryStaticData -ErrorAction Stop)[0].DesignedCapacity; $full = @(Get-CimInstance -Namespace root\wmi -ClassName BatteryFullChargedCapacity -ErrorAction Stop)[0].FullChargedCapacity
        if ($des) { $cyc = ''; try { $cyc = @(Get-CimInstance -Namespace root\wmi -ClassName BatteryCycleCount -ErrorAction Stop)[0].CycleCount } catch { }
            $p = $full * 100 / $des
            $HT.Add(('<h2>Akku</h2><table>{0}{1}{2}</table>' -f (Row 'Restkapazität' ('{0:N0} % ({1:N0} von {2:N0} mWh)' -f $p, $full, $des)), (Row 'Ladezyklen' $(if ($cyc) { $cyc } else { '-' })), ('<tr><th></th><td>' + (Bar $p $(if ($p -lt 60) { '#DC2626' } elseif ($p -lt 80) { '#D97706' } else { '#16A34A' })) + '</td></tr>'))) }
    } catch { }
    # Sicherheit
    $HT.Add('<h2>Sicherheit</h2><table>')
    $av = @(Get-CimInstance -Namespace root/SecurityCenter2 -ClassName AntiVirusProduct -ErrorAction SilentlyContinue | ForEach-Object { $_.displayName + $(if (((([int]$_.productState) -shr 12) -band 0xF) -in 1, 3) { ' (aktiv)' } else { ' (aus)' }) })
    $HT.Add((Row 'Virenschutz' $(if ($av.Count) { $av -join ', ' } else { 'nicht ermittelbar' })))
    try { $mp = Get-MpComputerStatus -ErrorAction Stop; $HT.Add((Row 'Defender-Definitionen' ('{0:dd.MM.yyyy} (Version {1})' -f $mp.AntivirusSignatureLastUpdated, $mp.AntivirusSignatureVersion))); $HT.Add((Row 'Letzte Schnellprüfung' $(if ($mp.QuickScanEndTime) { $mp.QuickScanEndTime.ToString('dd.MM.yyyy HH:mm') } else { 'noch nie' }))) } catch { }
    $fw = @(Get-NetFirewallProfile -ErrorAction SilentlyContinue | ForEach-Object { '{0}: {1}' -f $_.Name, $(if ($_.Enabled) { 'an' } else { 'AUS' }) }); $HT.Add((Row 'Firewall' ($fw -join ', ')))
    try { $HT.Add((Row 'Secure Boot' $(if (Confirm-SecureBootUEFI -ErrorAction Stop) { 'an' } else { 'aus' }))) } catch { $HT.Add((Row 'Secure Boot' 'nicht unterstützt / Legacy-BIOS')) }
    try { $t = Get-Tpm -ErrorAction Stop; $HT.Add((Row 'TPM' $(if ($t.TpmPresent) { 'vorhanden' + $(if ($t.TpmReady) { ', bereit' } else { ', nicht bereit' }) } else { 'nicht vorhanden' }))) } catch { }
    try { $bl = @(Get-BitLockerVolume -ErrorAction Stop | ForEach-Object { '{0} {1}' -f $_.MountPoint, $(if ([string]$_.ProtectionStatus -eq 'On') { 'verschlüsselt' } else { 'nicht verschlüsselt' }) }); $HT.Add((Row 'BitLocker' ($bl -join ', '))) } catch { }
    $HT.Add('</table>')
    # Lizenz
    try {
        $w = Get-WindowsLicense
        $HT.Add('<h2>Windows-Lizenz</h2><table>'); $HT.Add((Row 'Aktivierung' $w.Status)); $HT.Add((Row 'Lizenzart' $w.Kind))
        $HT.Add((Row 'Schlüssel (gekürzt)' ('XXXXX-XXXXX-XXXXX-XXXXX-' + $w.Partial))); if ($w.FirmwareDesc) { $HT.Add((Row 'Schlüssel im BIOS' $w.FirmwareDesc)) }; $HT.Add('</table>')
    } catch { }
    # Stabilität
    $bs = 0; $crash = 0
    try { $bs = @(Get-WinEvent -FilterHashtable @{ LogName = 'System'; ProviderName = 'Microsoft-Windows-WER-SystemErrorReporting'; StartTime = (Get-Date).AddDays(-30) } -ErrorAction Stop).Count } catch { }
    try { $crash = @(Get-WinEvent -FilterHashtable @{ LogName = 'Application'; Id = 1000; StartTime = (Get-Date).AddDays(-30) } -ErrorAction Stop).Count } catch { }
    $HT.Add('<h2>Stabilität (30 Tage)</h2><table>'); $HT.Add((Row 'Bluescreens' $bs)); $HT.Add((Row 'Programmabstürze' $crash)); $HT.Add('</table>')
    # Verlauf
    $vf = Join-Path $h.D 'Verlauf.csv'
    if (Test-Path -LiteralPath $vf) {
        $rows = @(Import-Csv -LiteralPath $vf -Delimiter ';' -Encoding UTF8 | Select-Object -Last 12)
        if ($rows.Count) {
            $HT.Add('<h2>Verlauf (letzte Messungen)</h2><table class="grid"><tr><th>Datum</th><th>Frei C: (GB)</th><th>Start (s)</th><th>Akku %</th><th>SSD-Verschleiß %</th><th>SSD &deg;C</th></tr>')
            foreach ($r in $rows) { $HT.Add(('<tr><td>{0}</td><td>{1}</td><td>{2}</td><td>{3}</td><td>{4}</td><td>{5}</td></tr>' -f (E $r.Datum), (E $r.FreiGB), (E $r.StartSek), (E $r.AkkuProzent), (E $r.SsdVerschleiss), (E $r.SsdTemperatur))) }
            $HT.Add('</table>')
        }
    }
    $HT.Add('<p class="muted" style="margin-top:20px">Erstellt mit PC-Tools. Alle Angaben wurden lokal auf diesem PC ausgelesen.</p></body></html>')
    $html = $HT -join "`n"
    $tmp = Join-Path $env:TEMP ('PCPflege-Bericht-{0}.html' -f $PID)
    [IO.File]::WriteAllText($tmp, $html, (New-Object Text.UTF8Encoding $true))
    $edge = @((Join-Path ${env:ProgramFiles(x86)} 'Microsoft\Edge\Application\msedge.exe'), (Join-Path $env:ProgramFiles 'Microsoft\Edge\Application\msedge.exe')) | Where-Object { Test-Path -LiteralPath $_ } | Select-Object -First 1
    if ($h.Pdf -and $edge) {
        if (Test-Path -LiteralPath $h.Out) { Remove-Item -LiteralPath $h.Out -Force }
        $prof = Join-Path $env:TEMP 'PCPflege-Edge'
        $p = Start-Process -FilePath $edge -ArgumentList @('--headless=new', '--disable-gpu', '--no-first-run', '--no-default-browser-check', '--no-pdf-header-footer', ('--user-data-dir="{0}"' -f $prof), ('--print-to-pdf="{0}"' -f $h.Out), ('"file:///{0}"' -f ($tmp -replace '\\', '/'))) -PassThru -WindowStyle Hidden
        $null = $p.WaitForExit(60000)
        for ($i = 0; $i -lt 20 -and -not (Test-Path -LiteralPath $h.Out); $i++) { Start-Sleep -Milliseconds 500 }
        if (Test-Path -LiteralPath $h.Out) { Remove-Item -LiteralPath $tmp -Force -ErrorAction SilentlyContinue; return $h.Out }
    }
    $html2 = [IO.Path]::ChangeExtension($h.Out, '.html'); Move-Item -LiteralPath $tmp -Destination $html2 -Force
    return $html2
}
function Start-PdfReport {
    Add-Type -AssemblyName System.Windows.Forms
    $d = New-Object System.Windows.Forms.SaveFileDialog; $d.Filter = 'PDF (*.pdf)|*.pdf|Webseite (*.html)|*.html'; $d.FileName = ('PC-Bericht_{0}_{1:yyyy-MM-dd}.pdf' -f $env:COMPUTERNAME, (Get-Date))
    if ($d.ShowDialog() -ne 'OK') { return }
    $script:PdfTarget = $d.FileName
    $ui.StatusText.Text = 'PC-Bericht wird erstellt (ca. 20-40 Sekunden) ...'; $window.Cursor = 'AppStarting'
    Invoke-Bg -Script $PdfReportScript -Arguments @(@{ G = $GenericWinKeys; A = (Get-HealthArgs); D = $DataDir; V = $AppVersion; Out = $d.FileName; Pdf = ($d.FileName -match '\.pdf$') }) -Functions @('Get-HealthItems', 'ConvertFrom-DigitalProductId', 'Get-WindowsLicense') -Done {
        param($r, $err)
        $window.Cursor = $null
        if ($err) { Show-UiError ('Bericht fehlgeschlagen: ' + $err.Message); $ui.StatusText.Text = 'Bericht fehlgeschlagen.'; return }
        $f = [string](@($r | Where-Object { $_ })[-1])
        $ui.StatusText.Text = 'PC-Bericht gespeichert: ' + $f
        if ($f -match '\.html$' -and $script:PdfTarget -match '\.pdf$') { [Windows.MessageBox]::Show((T ('Microsoft Edge wurde nicht gefunden - der Bericht wurde als Webseite gespeichert. Zum PDF: öffnen und mit "Drucken > Microsoft Print to PDF" speichern.')), (T ('PC-Tools')), 'OK', 'Information') | Out-Null }
        try { Start-Process -FilePath $f } catch { }
    }
}

# ---------------------------------------------------------------- Sorgenfrei-Modus
function Set-UiCheck([string]$Name, [bool]$Value) { $c = $window.FindName($Name); if ($c) { $c.IsChecked = $Value } }
function Start-Carefree {
    $hasTarget = [bool]$ui.Backup_Target.Text.Trim()
    $hasNotify = [bool]($ui.Notify_Ntfy.Text.Trim() -or $ui.Notify_HaWebhook.Text.Trim() -or $ui.Notify_ChatWebhook.Text.Trim())
    $defOk = $false; try { $defOk = ((Get-MpComputerStatus -ErrorAction Stop).AMRunningMode -eq 'Normal') } catch { }
    $f = @(
        @{ Key = 'Sched'; Type = 'Check'; Value = $true; Label = 'Automatische Pflege jede Woche (Sonntag 3 Uhr: Aufräumen, Optimieren, alle Updates; PC wird dafür geweckt)' }
        @{ Key = 'OneClick'; Type = 'Check'; Value = $true; Label = 'Die automatische Pflege als Ein-Klick-Optimierung ausführen (zusätzlich Treiber, Systemprüfung und Vorher/Nachher-Bericht)' }
        @{ Key = 'Self'; Type = 'Check'; Value = $true; Label = 'PC-Tools hält sich selbst aktuell' }
        @{ Key = 'Rp'; Type = 'Check'; Value = $true; Label = 'Vor jeder Änderung einen Wiederherstellungspunkt setzen' }
        @{ Key = 'Backup'; Type = 'Check'; Value = $hasTarget; Label = $(if ($hasTarget) { 'Datensicherung jeden Tag um 20 Uhr nach ' + $ui.Backup_Target.Text.Trim() } else { 'Datensicherung täglich (erst Ziel auf der Seite Datensicherung eintragen)' }) }
        @{ Key = 'Def'; Type = 'Check'; Value = $defOk; Label = $(if ($defOk) { 'Microsoft Defender auf empfohlene Werte (Echtzeit, Cloud, unerwünschte Apps, Netzwerkschutz)' } else { 'Defender-Empfehlungen (ein anderer Virenschutz ist aktiv - wird übersprungen)' }) }
        @{ Key = 'Fw'; Type = 'Check'; Value = $true; Label = 'Firewall für alle Netzwerke einschalten' }
        @{ Key = 'Auto'; Type = 'Check'; Value = $true; Label = 'Überflüssige Autostart-Programme ausschalten (rückgängig machbar)' }
        @{ Key = 'Notify'; Type = 'Check'; Value = $hasNotify; Label = $(if ($hasNotify) { 'Handy-Benachrichtigung bei Problemen' } else { 'Handy-Benachrichtigung (erst auf der Seite Meine PCs einrichten)' }) }
    )
    $r = Show-InputDialog 'Sorgenfrei-Modus' "Mit einem Klick alles so einstellen, dass sich PC-Tools ab jetzt allein um diesen PC kümmert. Alles lässt sich später auf den einzelnen Seiten wieder ändern." $f
    if (-not $r) { return }
    $done = @(); $skip = @()
    if ($r.Sched) {
        foreach ($n in 'Schedule_Enabled', 'Schedule_Clean', 'Schedule_Optimize', 'Schedule_Update', 'Schedule_WakeToRun') { Set-UiCheck $n $true }
        if (-not $ui.Schedule_Time.Text.Trim()) { $ui.Schedule_Time.Text = '03:00' }
        $done += 'Automatische Pflege eingeschaltet'
    }
    if ($r.OneClick) { Set-UiCheck 'Schedule_OneClick' $true; Set-UiCheck 'Schedule_Enabled' $true; try { Update-OkSchedInfo } catch { }; $done += 'Automatische Pflege als Ein-Klick-Optimierung' }
    if ($r.Self) { Set-UiCheck 'Settings_UpdateAuto' $true; Set-UiCheck 'Settings_UpdateInSchedule' $true; $done += 'Selbst-Aktualisierung an' }
    if ($r.Rp) { Set-UiCheck 'Optimize_RestorePoint' $true; $done += 'Wiederherstellungspunkte an' }
    if ($r.Backup) { if ($hasTarget) { Set-UiCheck 'Backup_Enabled' $true; Set-UiCheck 'Backup_OnlyIfTarget' $true; $done += 'Tägliche Datensicherung an' } else { $skip += 'Datensicherung: kein Ziel eingetragen' } }
    if ($r.Notify) { if ($hasNotify) { Set-UiCheck 'Notify_Enabled' $true; foreach ($n in 'Notify_OnRed', 'Notify_OnBackup', 'Notify_OnBluescreen') { Set-UiCheck $n $true }; $done += 'Benachrichtigungen an' } else { $skip += 'Benachrichtigung: kein Ziel eingerichtet' } }
    if (-not (Save-All -Quiet)) { $skip += 'Einstellungen konnten nicht vollständig gespeichert werden' }
    if ($r.Def) {
        if ($defOk) {
            $e = 0; foreach ($p in @(@{ DisableRealtimeMonitoring = $false }, @{ MAPSReporting = 2 }, @{ PUAProtection = 1 }, @{ EnableNetworkProtection = 1 }, @{ DisableBehaviorMonitoring = $false }, @{ DisableScriptScanning = $false }, @{ DisableRemovableDriveScanning = $false })) { try { Set-MpPreference @p -ErrorAction Stop } catch { $e++ } }
            $done += $(if ($e) { 'Defender teilweise angepasst ({0} Werte gesperrt)' -f $e } else { 'Defender auf empfohlene Werte' })
        } else { $skip += 'Defender: anderer Virenschutz aktiv' }
    }
    if ($r.Fw) { try { Set-NetFirewallProfile -Profile Domain, Private, Public -Enabled True -ErrorAction Stop; $done += 'Firewall überall an' } catch { $skip += 'Firewall: ' + $_.Exception.Message } }
    if ($r.Auto) { try { $n = Set-AutoBulk 'Recommended' -NoConfirm; $done += 'Autostart aufgeräumt' } catch { $skip += 'Autostart: ' + $_.Exception.Message } }
    try { Update-Security } catch { }; try { Update-Ampel } catch { }
    $ui.CarefreeState.Text = 'Sorgenfrei-Modus eingerichtet am ' + (Get-Date).ToString('dd.MM.yyyy')
    try { Set-Content -LiteralPath (Join-Path $DataDir 'sorgenfrei.txt') -Value (Get-Date).ToString('o') } catch { }
    [Windows.MessageBox]::Show((T (("Sorgenfrei-Modus eingerichtet:`n`n{0}{1}" -f (($done | ForEach-Object { '  ✓ ' + $_ }) -join "`n"), $(if ($skip) { "`n`nNicht erledigt:`n" + (($skip | ForEach-Object { '  - ' + $_ }) -join "`n") } else { '' })))), (T ('PC-Tools')), 'OK', 'Information') | Out-Null
}

