function Update-SearchList {
    $q = $ui.SearchBox.Text.Trim().ToLower(); $ui.SearchList.Items.Clear()
    $words = @($q -split '\s+' | Where-Object { $_ })
    $hits = if (-not $words.Count) { @($SearchIndex | Select-Object -First 12) } else {
        @($SearchIndex | ForEach-Object { $e = $_; $ok = $true; $score = 0
            foreach ($w in $words) { if ($e.Keys.Contains($w)) { if ($e.Title.ToLower().StartsWith($w)) { $score += 3 } elseif ($e.Title.ToLower().Contains($w)) { $score += 2 } else { $score += 1 } } else { $ok = $false } }
            if ($ok) { [pscustomobject]@{ E = $e; S = $score } } } | Sort-Object S -Descending | Select-Object -First 12 | ForEach-Object { $_.E })
    }
    $fg = if ($Script:Dark) { '#E4E8EF' } else { '#1F2A44' }; $fg2 = if ($Script:Dark) { '#98A2B6' } else { '#6B7890' }
    foreach ($h in $hits) {
        $li = New-Object Windows.Controls.ListBoxItem; $li.Tag = $h; $li.Padding = '8,6'
        $sp = New-Object Windows.Controls.StackPanel; $sp.Orientation = 'Horizontal'
        $g = New-Object Windows.Controls.TextBlock; $g.FontFamily = 'Segoe MDL2 Assets'; $g.FontSize = 16; $g.Width = 30; $g.VerticalAlignment = 'Center'; $g.Foreground = '#2D7FF9'
        $g.Text = [regex]::Replace($h.Glyph, '&#x([0-9A-Fa-f]+);', { param($m) [string][char][Convert]::ToInt32($m.Groups[1].Value, 16) })
        $t = New-Object Windows.Controls.TextBlock; $t.Text = $h.Title; $t.FontSize = 14; $t.Foreground = $fg; $t.VerticalAlignment = 'Center'
        $w = New-Object Windows.Controls.TextBlock; $w.Text = '  ·  ' + $h.Where; $w.Foreground = $fg2; $w.VerticalAlignment = 'Center'
        [void]$sp.Children.Add($g); [void]$sp.Children.Add($t); [void]$sp.Children.Add($w); $li.Content = $sp
        [void]$ui.SearchList.Items.Add($li)
    }
    if ($ui.SearchList.Items.Count) { $ui.SearchList.SelectedIndex = 0 }
}
function Show-Search { $ui.SearchOverlay.Visibility = 'Visible'; $ui.SearchBox.Text = ''; Update-SearchList; [void]$ui.SearchBox.Focus() }
function Hide-Search { $ui.SearchOverlay.Visibility = 'Collapsed' }
function Invoke-SearchHit {
    $li = $ui.SearchList.SelectedItem; if (-not $li) { return }
    Hide-Search
    try { & $li.Tag.Do } catch { Show-UiError $_.Exception.Message }
}
$ui.SearchBox.Add_TextChanged({ Update-SearchList })
$ui.SearchBox.Add_PreviewKeyDown({
    param($s, $e)
    switch ([string]$e.Key) {
        'Down' { if ($ui.SearchList.SelectedIndex -lt $ui.SearchList.Items.Count - 1) { $ui.SearchList.SelectedIndex++ }; $ui.SearchList.ScrollIntoView($ui.SearchList.SelectedItem); $e.Handled = $true }
        'Up' { if ($ui.SearchList.SelectedIndex -gt 0) { $ui.SearchList.SelectedIndex-- }; $ui.SearchList.ScrollIntoView($ui.SearchList.SelectedItem); $e.Handled = $true }
        'Return' { Invoke-SearchHit; $e.Handled = $true }
    }
})
$ui.SearchList.Add_MouseUp({ Invoke-SearchHit })
$ui.SearchOverlay.Add_MouseDown({ param($s, $e) if ($e.OriginalSource -eq $ui.SearchOverlay) { Hide-Search } })
$window.Add_PreviewKeyDown({
    param($s, $e)
    $ctrl = ([Windows.Input.Keyboard]::Modifiers -band [Windows.Input.ModifierKeys]::Control) -ne 0
    if ($ctrl -and ([string]$e.Key -eq 'K' -or [string]$e.Key -eq 'F')) { Show-Search; $e.Handled = $true }
    elseif ([string]$e.Key -eq 'Escape' -and $ui.SearchOverlay.Visibility -eq 'Visible') { Hide-Search; $e.Handled = $true }
})
$window.Add_Loaded({ try { $b = $ui.Tabs.Template.FindName('SideSearch', $ui.Tabs); if ($b) { $b.Add_Click({ Show-Search }) } } catch { } })
$ui.BtnQuickSearch.Add_Click({ Show-Search })
$ui.BtnQuickPdf.Add_Click({ Start-PdfReport })
$ui.BtnQuickCarefree.Add_Click({ Start-Carefree })
try { $cf = Join-Path $DataDir 'sorgenfrei.txt'; if (Test-Path -LiteralPath $cf) { $ui.CarefreeState.Text = 'Sorgenfrei-Modus eingerichtet am ' + ([datetime](Get-Content -LiteralPath $cf -Raw).Trim()).ToString('dd.MM.yyyy') } } catch { }



# ---------------------------------------------------------------- BIOS / UEFI (Oberfläche)
$BiosCats = [ordered]@{
    'Start und Meldungen'    = '(?i)warn|prompt|error|post(?!al)|f1prompt|pause|quiet|splash|logo|diagnostic|fast.?boot|quick.?boot|boot.?(mode|display|up.?num)|wattage|adapter'
    'Tastatur und Eingabe'   = '(?i)keyboard|kbd|fnctrl|fn.?(lock|sticky|key|swap)|f1f12|hotkey|numlock|backlit|illumin|action.?key|trackpoint|touchpad|mouse|pointing'
    'Sicherheit'             = '(?i)secure|tpm|security|password|pwd|chip|guard|rollback|physical|intrusion|absolute|computrace|ptt|fingerprint|dma|bitlocker|lock(?!.*boot)'
    'Virtualisierung und CPU' = '(?i)virtual|\bvt|vtd|vtx|hyper|cpu|core|thread|sgx|txt|iommu|turbo|speedstep|c.?state|amt|vpro|management.?engine'
    'Start-Reihenfolge'      = '(?i)boot|pxe|uefi|legacy|csm|ipv4|ipv6|network.?stack|option.?rom'
    'Energie und Akku'       = '(?i)power|wake|wol|batt|charg|sleep|lid|standby|s3|s4|modern|always.?on|acattach|ac.?recovery|thermal|fan|cool|performance|energy'
    'Geräte und Anschlüsse'  = '(?i)usb|thunderbolt|tbt|camera|microphone|mic|audio|speaker|wireless|wlan|wifi|wwan|bluetooth|lan|ethernet|nic|card|nfc|serial|parallel|sata|nvme|storage|port|dock|sensor'
    'Anzeige und Grafik'     = '(?i)display|graphic|gpu|video|lcd|panel|bright|hybrid|optimus|igd|dvmt'
}
$BiosQuickGroups = @(
    @{ T = 'Warnungen und Meldungen beim Start'; R = '(?i)adapter|wattage|warn|prompt|error.?(pause|halt)|post.?(error|message|hotkey|delay|display)|f1.?prompt|quiet|splash|logo|fast.?boot|quick.?boot|boot.?mode|diagnostic'
       H = @{ Lenovo = 'ThinkPad: Die Meldung "The connected AC adapter has a lower wattage than the recommended AC adapter" kommt direkt aus der Firmware, wenn das Netzteil weniger Leistung meldet als das Original (bei T480/T490 meist 65 W). Viele ThinkPads haben dafür keinen Schalter - steht hier keine passende Einstellung, lässt sie sich nicht abschalten. Abhilfe: USB-C-Netzteil mit mindestens 65 W und Power Delivery, anderes Kabel (manche Kabel können nur 3 A/60 W), Dock mit genug Leistung, BIOS aktualisieren. Mit zu schwachem Netzteil lädt der Akku nur langsam oder gar nicht.'
             Dell = 'Dell: "Warnungen und Fehler" (WarningsAndErr) auf "Bei Warnungen und Fehlern fortfahren" stellen - dann bleibt der PC bei Warnungen (z.B. Netzteil zu schwach) nicht mehr stehen. Wo vorhanden, schaltet "Adapter-Warnungen" die Netzteil-Meldung ganz ab.'
             HP = 'HP: Unter "POST Prompt" / "Prompt on ..." bzw. "Fast Boot" lassen sich Start-Meldungen reduzieren. Netzteil-Warnungen ("Smart AC adapter") lassen sich bei den meisten Modellen nicht abschalten.' } }
    @{ T = 'Einschalten und Aufwachen'; R = '(?i)wake|wol|power.?on|acattach|after.?power|power.?loss|ac.?recovery|restore.?ac|auto.?on|lid.?open|flip.?to.?(boot|start)'; H = @{} }
    @{ T = 'Akku und Laden'; R = '(?i)batt|charg|express|usb.?power|always.?on.?usb|alwaysonusb|primarybatt'; H = @{ Lenovo = 'Ladegrenzen (z.B. 80 %) setzt man bei Lenovo nicht im BIOS, sondern auf der Seite Individualisieren > Akku.' } }
    @{ T = 'Leistung und Lüfter'; R = '(?i)thermal|fan|cool|performance|turbo|speedstep|c.?state|hyper.?thread|cpu.?power|adaptive.?thermal'; H = @{} }
    @{ T = 'Tastatur'; R = '(?i)keyboard|kbd|fnctrl|fn.?(lock|sticky|key|swap)|f1f12|hotkey|numlock|backlit|illumin|action.?key|trackpoint|touchpad'; H = @{} }
    @{ T = 'Virtualisierung (Hyper-V, WSL, Sandbox)'; R = '(?i)virtual|\bvt|vtd|vtx|iommu|sgx|txt|kernel.?dma'; H = @{} }
    @{ T = 'Sicherheit'; R = '(?i)secure.?boot|tpm|security.?chip|ptt|physical.?presence|guard|intrusion|absolute|computrace|rollback|smart.?usb|device.?guard'; H = @{} }
    @{ T = 'Start-Reihenfolge und Netzwerkstart'; R = '(?i)boot.?order|usb.?boot|network.?boot|pxe|legacy|csm|ipv4|ipv6|option.?rom|boot.?menu|f12'; H = @{} }
    @{ T = 'Kamera, Mikrofon und Funk'; R = '(?i)camera|microphone|\bmic|audio|speaker|wireless|wlan|wifi|wwan|bluetooth|nfc|fingerprint'; H = @{} }
    @{ T = 'Anschlüsse'; R = '(?i)usb|thunderbolt|tbt|card.?reader|sd.?card|ethernet|lan|sata|nvme|dock|serial|memory.?card'; H = @{} }
)
$script:BiosPending = @{}; $script:BiosRows = @(); $script:BiosInfoData = $null; $script:BiosSync = $false
function Get-BiosCat([string]$Name, [string]$Path) {
    if ($Path) { $p = ($Path -split '\\' | Where-Object { $_ })[0]; if ($p) { $x = $p.Trim() } }
    foreach ($k in $BiosCats.Keys) { if ($Name -match $BiosCats[$k]) { return $k } }
    if ($x) { return $x }
    return 'Sonstiges'
}
function Update-BiosPage {
    $ui.BiosDevice.Text = 'wird gelesen ...'; $ui.BiosQuick.Children.Clear(); $ui.BiosHint.Text = ''
    Invoke-Bg -Script { Get-BiosInfo } -Functions @('Get-BiosInfo') -Done {
        param($r, $err)
        if ($err) { $ui.BiosDevice.Text = $err.Message; return }
        $i = @($r | Where-Object { $_ })[0]; $script:BiosInfoData = $i
        $ui.BiosDevice.Text = '{0} {1}  ·  Seriennummer {2}' -f $i.Manufacturer, $i.Model, $i.Serial
        $ui.BiosVer.Text = '{0} vom {1:dd.MM.yyyy}{2}' -f $i.BiosVer, $i.BiosDate, $(if ($i.Ec) { '  ·  Embedded Controller ' + $i.Ec } else { '' })
        $ui.BiosMode.Text = $i.Firmware; $ui.BiosSec.Text = 'Secure Boot {0}  ·  {1}' -f $i.SecureBoot, $i.Tpm
        $ui.BiosIface.Text = $i.Iface; $ui.BiosPwState.Text = $i.Pw
        $keys = @{ Lenovo = 'ThinkPad: beim Start F1 (Boot-Menü F12, Enter für Menü). IdeaPad/Legion: F2 oder Novo-Taste'; HP = 'F10 (Boot-Menü F9, Esc für Startmenü)'; Dell = 'F2 (Boot-Menü F12)'; ASUS = 'F2 oder Entf (Boot-Menü F8/Esc)'; Acer = 'F2 (Boot-Menü F12)'; MSI = 'Entf (Boot-Menü F11)'; Gigabyte = 'Entf (Boot-Menü F12)'; Fujitsu = 'F2 (Boot-Menü F12)'; Medion = 'F2 oder Entf'; Microsoft = 'Surface ausschalten, Lauter-Taste halten und einschalten' }
        $k = if ($keys.ContainsKey($i.Vendor)) { $keys[$i.Vendor] } else { 'meist F2, Entf oder F10' }
        $ui.BiosHint.Text = if ($i.Vendor -in 'Lenovo', 'HP', 'Dell') { 'BIOS-Taste beim Start: {0}. Oder bequemer: "Jetzt neu starten ins BIOS/UEFI". Alle Einstellungen unten lassen sich direkt aus Windows ändern.' -f $k }
                            else { '{0} bietet keine offizielle Schnittstelle, um BIOS-Einstellungen aus Windows zu ändern - hier gibt es Infos und den direkten Neustart ins BIOS. BIOS-Taste beim Start: {1}.{2}' -f $i.Manufacturer, $k, $(if ($i.Vendor -eq 'Fujitsu') { ' Fujitsu-Firmenmodelle: "DeskView BIOS Management" des Herstellers.' } elseif ($i.Vendor -eq 'Microsoft') { ' Surface-Firmenmodelle: "Surface UEFI Configurator" (SEMM).' } else { '' }) }
        $ui.BtnBiosDefaults.IsEnabled = ($i.Vendor -eq 'Lenovo')
        if ($i.Vendor -in 'Lenovo', 'HP', 'Dell') { Update-BiosSettings } else { $script:BiosRows = @(); Set-GridItems $ui.BiosGrid @(); $t = New-Object Windows.Controls.TextBlock; $t.Text = 'Bei diesem Hersteller nicht verfügbar.'; $t.Foreground = New-UiBrush '#6B7890'; [void]$ui.BiosQuick.Children.Add($t) }
    }
}
function Update-BiosSettings {
    $ui.BiosPendingInfo.Text = 'BIOS-Einstellungen werden gelesen ...'
    Invoke-Bg -Script { Get-BiosFull } -Functions @('Get-BiosFull') -Done {
        param($r, $err)
        if ($err) { $ui.BiosPendingInfo.Text = 'Nicht lesbar: ' + $err.Message + ' (PC-Tools als Administrator? Bei Dell: neueres BIOS nötig.)'; return }
        $all = @($r | ForEach-Object { $_ } | Where-Object { $_ -and $_.Name })
        $script:BiosRows = @($all | ForEach-Object {
            $_ | Add-Member -NotePropertyName Cat -NotePropertyValue (Get-BiosCat $_.Name $_.Path) -Force
            $_ | Add-Member -NotePropertyName Pending -NotePropertyValue $(if ($script:BiosPending.ContainsKey($_.Name)) { $script:BiosPending[$_.Name] } else { '' }) -Force
            $_ | Add-Member -NotePropertyName OptText -NotePropertyValue $(if ($_.ReadOnly) { '(nur lesbar)' } elseif ($_.Options.Count) { $_.Options -join ', ' } else { $_.Type }) -Force
            $_ } | Sort-Object Cat, Label)
        $cur = [string]$ui.BiosCat.SelectedItem
        $ui.BiosCat.Items.Clear(); [void]$ui.BiosCat.Items.Add('Alle Themen'); foreach ($c in @($script:BiosRows | ForEach-Object { $_.Cat } | Sort-Object -Unique)) { [void]$ui.BiosCat.Items.Add($c) }
        $ui.BiosCat.SelectedItem = $(if ($cur -and $ui.BiosCat.Items.Contains($cur)) { $cur } else { 'Alle Themen' })
        Set-GridItems $ui.BiosGrid $script:BiosRows; Update-BiosFilter
        Build-BiosQuick; Update-BiosPendingInfo
    }
}
function Update-BiosFilter {
    $q = $ui.BiosSearch.Text.Trim(); $c = [string]$ui.BiosCat.SelectedItem; $only = [bool]$ui.BiosChangedOnly.IsChecked
    Set-GridFilter $ui.BiosGrid { param($x) (-not $q -or $x.Label -match [regex]::Escape($q) -or $x.Current -match [regex]::Escape($q) -or $x.OptText -match [regex]::Escape($q)) -and (-not $c -or $c -eq 'Alle Themen' -or $x.Cat -eq $c) -and (-not $only -or $x.Pending) }.GetNewClosure()
}
function Build-BiosQuick {
    $ui.BiosQuick.Children.Clear()
    $vendor = if ($script:BiosInfoData) { $script:BiosInfoData.Vendor } else { '' }
    $used = @{}
    foreach ($g in $BiosQuickGroups) {
        $hit = @($script:BiosRows | Where-Object { -not $_.ReadOnly -and $_.Options.Count -and -not $used.ContainsKey($_.Name) -and ($_.Name -match $g.R -or $_.Label -match $g.R) } | Select-Object -First 16)
        $hint = if ($g.H.ContainsKey($vendor)) { $g.H[$vendor] } else { '' }
        if (-not $hit.Count -and -not $hint) { continue }
        foreach ($h in $hit) { $used[$h.Name] = 1 }
        $hd = New-Object Windows.Controls.TextBlock; $hd.Text = '{0}  ({1})' -f $g.T, $(if ($hit.Count) { $hit.Count } else { 'bei diesem Modell keine Einstellung' }); $hd.FontWeight = 'SemiBold'; $hd.FontSize = 14; $hd.Margin = '0,10,0,4'; $hd.Foreground = New-UiBrush '#1F2A44'
        [void]$ui.BiosQuick.Children.Add($hd)
        if ($hint) { $ht = New-Object Windows.Controls.TextBlock; $ht.Text = $hint; $ht.TextWrapping = 'Wrap'; $ht.FontSize = 12; $ht.Margin = '0,0,0,6'; $ht.Foreground = New-UiBrush '#6B7890'; [void]$ui.BiosQuick.Children.Add($ht) }
        foreach ($s in $hit) {
            $row = New-Object Windows.Controls.Grid; $row.Margin = '0,2'
            foreach ($w in 380, -1) { $cd = New-Object Windows.Controls.ColumnDefinition; if ($w -gt 0) { $cd.Width = $w }; [void]$row.ColumnDefinitions.Add($cd) }
            $t = New-Object Windows.Controls.TextBlock; $t.Text = $s.Label; $t.TextWrapping = 'Wrap'; $t.VerticalAlignment = 'Center'; $t.Foreground = New-UiBrush '#1F2A44'
            $cb = New-Object Windows.Controls.ComboBox; $cb.Width = 280; $cb.HorizontalAlignment = 'Left'; $cb.Tag = $s
            foreach ($o in $s.Options) { [void]$cb.Items.Add($o) }
            if (-not $cb.Items.Contains($s.Current)) { [void]$cb.Items.Insert(0, $s.Current) }
            $cb.SelectedItem = $(if ($s.Pending) { $s.Pending } else { $s.Current })
            $cb.Add_SelectionChanged({ param($sn, $ev) $ev.Handled = $true; if ($script:BiosSync) { return }; Set-BiosPending $sn.Tag ([string]$sn.SelectedItem) })
            [Windows.Controls.Grid]::SetColumn($cb, 1); [void]$row.Children.Add($t); [void]$row.Children.Add($cb)
            [void]$ui.BiosQuick.Children.Add($row)
        }
    }
    if (-not $ui.BiosQuick.Children.Count) { $t = New-Object Windows.Controls.TextBlock; $t.Text = 'Keine änderbaren Einstellungen gefunden.'; [void]$ui.BiosQuick.Children.Add($t) }
}
function Set-BiosPending($Row, [string]$Value) {
    if ($Row.ReadOnly) { Show-UiError 'Diese Einstellung ist nur lesbar.'; return }
    if ($Value -eq $Row.Current -or -not $Value) { [void]$script:BiosPending.Remove($Row.Name); $Row.Pending = '' }
    else {
        if ($Row.Type -eq 'Enum' -and $Row.Options.Count -and $Value -notin $Row.Options) { Show-UiError ('"{0}" ist kein gültiger Wert. Möglich: {1}' -f $Value, ($Row.Options -join ', ')); return }
        if ($Row.Type -like 'Integer*' -and $Value -notmatch '^\d+$') { Show-UiError 'Bitte eine Zahl eingeben.'; return }
        $script:BiosPending[$Row.Name] = $Value; $Row.Pending = $Value
    }
    $ui.BiosGrid.Items.Refresh()
    $script:BiosSync = $true
    try { foreach ($o in $ui.BiosQuick.Children) { if ($o -is [Windows.Controls.Grid]) { $cb = $o.Children[1]; if ($cb.Tag.Name -eq $Row.Name) { $want = if ($Row.Pending) { $Row.Pending } else { $Row.Current }; if ([string]$cb.SelectedItem -ne $want) { $cb.SelectedItem = $want } } } } } finally { $script:BiosSync = $false }
    Update-BiosPendingInfo
}
function Update-BiosPendingInfo {
    $n = $script:BiosPending.Count
    $ui.BiosPendingInfo.Text = if ($n) { '{0} Änderung(en) vorgemerkt: {1}' -f $n, (($script:BiosPending.GetEnumerator() | Sort-Object Name | ForEach-Object { '{0} = {1}' -f $_.Name, $_.Value }) -join '  ·  ') } else { '{0} BIOS-Einstellungen gelesen - keine Änderungen vorgemerkt.' -f @($script:BiosRows).Count }
    $ui.BtnBiosApplyAll.IsEnabled = [bool]$n
}
function Invoke-BiosApply {
    if (-not $script:BiosPending.Count) { return }
    $vendor = $script:BiosInfoData.Vendor
    $chg = @($script:BiosPending.GetEnumerator() | Sort-Object Name | ForEach-Object { [pscustomobject]@{ Vendor = $vendor; Name = $_.Name; Value = $_.Value } })
    $risky = @($chg | Where-Object { $_.Name -match '(?i)secure.?boot|tpm|security.?chip|ptt|boot.?mode|legacy|csm|uefi|sata|raid|ahci|storage' })
    $q = "Diese BIOS-Einstellungen ändern?`n`n{0}`n`nWirkt nach dem nächsten Neustart." -f (($chg | ForEach-Object { '  {0}: {1} -> {2}' -f $_.Name, (@($script:BiosRows | Where-Object Name -eq $_.Name)[0].Current), $_.Value }) -join "`n")
    if ($risky.Count) { $q += "`n`nACHTUNG: Secure Boot/TPM/Startmodus/Laufwerksmodus betroffen. Ist BitLocker an, fragt Windows danach evtl. den Wiederherstellungsschlüssel ab. Falscher Laufwerksmodus (SATA/RAID) kann den Start verhindern." }
    if (-not (Confirm-Ui $q 'Warning')) { return }
    $res = @(Set-OemBiosSettings $chg $ui.BiosPwd.Password)
    $ok = @($res | Where-Object Ok); $bad = @($res | Where-Object { -not $_.Ok })
    foreach ($o in $ok) { [void]$script:BiosPending.Remove($o.Name) }
    try { Add-Content -LiteralPath (Join-Path $DataDir 'BIOS-Aenderungen.log') -Value (($res | ForEach-Object { '{0:yyyy-MM-dd HH:mm}  {1} = {2}  {3}' -f (Get-Date), $_.Name, $_.Value, $(if ($_.Ok) { 'OK' } else { 'FEHLER ' + $_.Msg }) }) -join "`r`n") -Encoding UTF8 } catch { }
    if ($bad.Count) { Show-UiError ("{0} übernommen, {1} nicht:`n{2}`n`nAccess Denied / 6 = BIOS-Kennwort nötig oder falsch. Invalid Parameter / 2 = Wert passt nicht. Not Supported = bei diesem Modell nicht änderbar." -f $ok.Count, $bad.Count, (($bad | ForEach-Object { '  {0}: {1}' -f $_.Name, $_.Msg }) -join "`n")) }
    else { $ui.StatusText.Text = '{0} BIOS-Einstellung(en) gespeichert - aktiv nach dem nächsten Neustart.' -f $ok.Count }
    $ui.BiosPwd.Password = ''
    if ($ok.Count -and $ui.BiosRebootAfter.IsChecked -and (Confirm-Ui 'Jetzt neu starten und das BIOS öffnen? Offene Dateien vorher speichern.')) { & shutdown.exe /r /fw /t 5 | Out-Null; return }
    Update-BiosSettings
}

$ui.Tabs.Add_SelectionChanged({
    param($s, $e)
    if ($e.OriginalSource -ne $s -or $s.SelectedItem -ne $ui.TabBios -or $script:BiosLoaded) { return }
    $script:BiosLoaded = $true; Update-BiosPage
})
$ui.BtnBiosReload.Add_Click({ Update-BiosPage })
$ui.BtnBiosReboot.Add_Click({ if (Confirm-Ui 'Jetzt neu starten und direkt das BIOS/UEFI öffnen? Offene Dateien vorher speichern.' 'Warning') { $o = & shutdown.exe /r /fw /t 5 2>&1; if ($LASTEXITCODE) { Show-UiError ('Direkter Start ins BIOS nicht möglich (Legacy-BIOS?): ' + ($o -join ' ') + "`nDann beim Start die BIOS-Taste drücken.") } } })
$ui.BtnBiosUpdate.Add_Click({ $ui.Tabs.SelectedItem = $ui.TabDrv })
$ui.BtnBiosSerial.Add_Click({ if ($script:BiosInfoData) { Set-Clipboard -Value $script:BiosInfoData.Serial; $ui.StatusText.Text = 'Seriennummer kopiert: ' + $script:BiosInfoData.Serial } })
$ui.BtnBiosSupport.Add_Click({
    $i = $script:BiosInfoData; if (-not $i) { return }
    $sn = [uri]::EscapeDataString($i.Serial)
    $u = switch ($i.Vendor) { 'Lenovo' { 'https://pcsupport.lenovo.com/de/de/search?query=' + $sn } 'HP' { 'https://support.hp.com/de-de/check-warranty' } 'Dell' { 'https://www.dell.com/support/home/de-de/product-support/servicetag/' + $sn } default { 'https://www.bing.com/search?q=' + [uri]::EscapeDataString($i.Manufacturer + ' ' + $i.Model + ' BIOS update') } }
    Start-Process $u
})
$ui.BiosSearch.Add_TextChanged({ if ($script:BiosRows) { Update-BiosFilter } })
$ui.BiosCat.Add_SelectionChanged({ param($s, $e) $e.Handled = $true; if ($script:BiosRows) { Update-BiosFilter } })
$ui.BiosChangedOnly.Add_Click({ Update-BiosFilter })
$ui.BiosGrid.Add_SelectionChanged({
    param($s, $e)
    $r = $ui.BiosGrid.SelectedItem; $ui.BiosSelValue.Items.Clear()
    if (-not $r) { $ui.BiosSelName.Text = 'Einstellung wählen:'; $ui.BiosSelInfo.Text = ''; return }
    $ui.BiosSelName.Text = $r.Name
    foreach ($o in $r.Options) { [void]$ui.BiosSelValue.Items.Add($o) }
    $ui.BiosSelValue.Text = $(if ($r.Pending) { $r.Pending } else { $r.Current })
    $ui.BiosSelValue.IsEnabled = -not $r.ReadOnly
    $ui.BiosSelInfo.Text = '{0}  ·  Typ: {1}  ·  Aktuell: {2}{3}{4}' -f $r.Label, $r.Type, $r.Current, $(if ($r.Path) { '  ·  Menü: ' + $r.Path } else { '' }), $(if ($r.ReadOnly) { '  ·  nur lesbar' } elseif ($r.Type -eq 'Order') { '  ·  Reihenfolge als Liste eingeben (Lenovo mit ":" getrennt, HP mit ",")' } else { '' })
})
$ui.BiosGrid.Add_MouseDoubleClick({ [void]$ui.BiosSelValue.Focus() })
$ui.BtnBiosMark.Add_Click({ $r = $ui.BiosGrid.SelectedItem; if ($r) { Set-BiosPending $r $ui.BiosSelValue.Text.Trim() } })
$ui.BtnBiosUnmark.Add_Click({ $r = $ui.BiosGrid.SelectedItem; if ($r) { Set-BiosPending $r $r.Current } })
$ui.BtnBiosUnmarkAll.Add_Click({ foreach ($r in @($script:BiosRows | Where-Object Pending)) { Set-BiosPending $r $r.Current } })
$ui.BtnBiosApplyAll.Add_Click({ Invoke-BiosApply })
$ui.BtnBiosBackup.Add_Click({
    if (-not @($script:BiosRows).Count) { return }
    Add-Type -AssemblyName System.Windows.Forms
    $d = New-Object System.Windows.Forms.SaveFileDialog; $d.Filter = 'BIOS-Sicherung (*.json)|*.json'; $d.FileName = ('BIOS_{0}_{1:yyyy-MM-dd}.json' -f $env:COMPUTERNAME, (Get-Date))
    if ($d.ShowDialog() -ne 'OK') { return }
    $i = $script:BiosInfoData
    [pscustomobject]@{ Computer = $env:COMPUTERNAME; Vendor = $i.Vendor; Model = $i.Model; Bios = $i.BiosVer; Date = (Get-Date).ToString('o'); Settings = @($script:BiosRows | ForEach-Object { [pscustomobject]@{ Name = $_.Name; Value = $_.Current; ReadOnly = $_.ReadOnly } }) } | ConvertTo-Json -Depth 4 | Set-Content -LiteralPath $d.FileName -Encoding UTF8
    $ui.StatusText.Text = '{0} BIOS-Einstellungen gesichert: {1}' -f @($script:BiosRows).Count, $d.FileName
})
$ui.BtnBiosRestore.Add_Click({
    Add-Type -AssemblyName System.Windows.Forms
    $d = New-Object System.Windows.Forms.OpenFileDialog; $d.Filter = 'BIOS-Sicherung (*.json)|*.json'
    if ($d.ShowDialog() -ne 'OK') { return }
    try { $b = Get-Content -LiteralPath $d.FileName -Raw -Encoding UTF8 | ConvertFrom-Json } catch { Show-UiError 'Datei nicht lesbar.'; return }
    if ($b.Vendor -ne $script:BiosInfoData.Vendor) { Show-UiError ('Die Sicherung stammt von einem {0}-Gerät - nicht übertragbar.' -f $b.Vendor); return }
    if ($b.Model -ne $script:BiosInfoData.Model -and -not (Confirm-Ui ("Sicherung stammt von {0} ({1}), dieser PC ist {2}. Nur gleichnamige Einstellungen übernehmen?" -f $b.Computer, $b.Model, $script:BiosInfoData.Model))) { return }
    $n = 0
    foreach ($s in @($b.Settings | ForEach-Object { $_ })) {
        if ($s.ReadOnly -or $s.Name -match '(?i)password|asset|ownership|serial') { continue }
        $r = @($script:BiosRows | Where-Object Name -eq $s.Name)[0]
        if ($r -and -not $r.ReadOnly -and [string]$s.Value -ne $r.Current) { $script:BiosPending[$r.Name] = [string]$s.Value; $r.Pending = [string]$s.Value; $n++ }
    }
    $ui.BiosGrid.Items.Refresh(); Build-BiosQuick; Update-BiosPendingInfo
    $ui.BiosChangedOnly.IsChecked = [bool]$n; Update-BiosFilter
    $ui.StatusText.Text = '{0} abweichende Einstellung(en) aus der Sicherung vorgemerkt - prüfen und "Änderungen übernehmen".' -f $n
})
$ui.BtnBiosCsv.Add_Click({
    if (-not @($script:BiosRows).Count) { return }
    Add-Type -AssemblyName System.Windows.Forms
    $d = New-Object System.Windows.Forms.SaveFileDialog; $d.Filter = 'CSV (*.csv)|*.csv'; $d.FileName = ('BIOS_{0}_{1:yyyy-MM-dd}.csv' -f $env:COMPUTERNAME, (Get-Date))
    if ($d.ShowDialog() -ne 'OK') { return }
    $script:BiosRows | Select-Object Cat, Name, Label, Current, OptText, Type, ReadOnly, Path | Export-Csv -LiteralPath $d.FileName -Delimiter ';' -NoTypeInformation -Encoding UTF8
    $ui.StatusText.Text = 'BIOS-Liste gespeichert: ' + $d.FileName
})
$ui.BtnBiosDefaults.Add_Click({
    if ($script:BiosInfoData.Vendor -ne 'Lenovo') { return }
    $r = Show-InputDialog 'BIOS-Werkseinstellungen' "ALLE BIOS-Einstellungen auf Lenovo-Werkseinstellungen zurücksetzen (Kennwörter bleiben)?`nVorher mit ""Alle Einstellungen sichern"" eine Sicherung anlegen! Zum Bestätigen STANDARD eintippen:" @(@{ Key = 'C'; Label = 'Bestätigung'; Type = 'Text' })
    if (-not $r -or $r.C -cne 'STANDARD') { return }
    try {
        $p = $ui.BiosPwd.Password
        $ld = Get-WmiObject -Namespace root\wmi -Class Lenovo_LoadDefaultSettings
        $x = if ($p) { $ld.LoadDefaultSettings(('{0},ascii,us' -f $p)).return } else { $ld.LoadDefaultSettings().return }
        if ($x -ne 'Success') { throw $x }
        $sv = Get-WmiObject -Namespace root\wmi -Class Lenovo_SaveBiosSettings
        $y = if ($p) { $sv.SaveBiosSettings(('{0},ascii,us' -f $p)).return } else { $sv.SaveBiosSettings().return }
        if ($y -ne 'Success') { throw $y }
        $ui.StatusText.Text = 'BIOS-Werkseinstellungen geladen - aktiv nach dem Neustart.'; Update-BiosSettings
    } catch { Show-UiError ('Nicht möglich: ' + $_.Exception.Message + ' (BIOS-Kennwort nötig?)') }
})
# ---------------------------------------------------------------- Einrichtungs-Assistent (Oberfläche)
$WizFields = @('WizOnBase', 'WizName', 'WizTheme', 'WizRegion', 'WizOnPower', 'WizPower', 'WizScrAc', 'WizScrDc', 'WizSlpAc', 'WizSlpDc', 'WizLid', 'WizOnUx', 'WizPrivacy', 'WizExplorer', 'WizHidden', 'WizClassic', 'WizTaskbar', 'WizTaskLeft', 'WizRdp',
    'WizOnBloat', 'WizBloat', 'WizOnApps', 'WizUseSetup', 'WizOnUpd', 'WizOemPack', 'WizDrivers', 'WizUpdates', 'WizReboot', 'WizRounds', 'WizOnNet', 'WizUsers', 'WizDrives', 'WizPrinters', 'WizOnSet', 'WizSetDir', 'WizOnCorp', 'WizCoOrg', 'WizCoOwner', 'WizCoNaming', 'WizCoAsset', 'WizCoInvDir', 'WizCoSupName', 'WizCoSupPhone', 'WizCoSupUrl', 'WizCoDomain', 'WizCoOu', 'WizCoDomUser', 'WizCoTenant', 'WizCoEntra', 'WizCoLock', 'WizCoPwLen', 'WizCoPwLock', 'WizCoUsb', 'WizCoAsr', 'WizCoAdminOff', 'WizCoNoConsumer', 'WizCoLegal', 'WizCoLockImg', 'WizCoDeskImg', 'WizCoWifi', 'WizCoVpnName', 'WizCoVpnSrv', 'WizCoVpnType', 'WizCoProxy', 'WizCoProxyEx', 'WizCoNtp', 'WizCoCertDir', 'WizOnFinish', 'WizBitLocker', 'WizKeyDir', 'WizCarefree', 'WizReport')
function Get-TzItems { @(Get-TimeZone -ListAvailable | ForEach-Object { $i = New-Object Windows.Controls.ComboBoxItem; $i.Content = $_.DisplayName; $i.Tag = $_.Id; $i }) }
function Initialize-Wizard {
    if ($script:WizInit) { return }; $script:WizInit = $true
    $ui.WizNameNow.Text = '(jetzt: {0})' -f $env:COMPUTERNAME
    $cur = (Get-TimeZone).Id
    foreach ($cb in @($ui.WizTz, $ui.UaTz)) { $cb.Items.Clear(); foreach ($i in (Get-TzItems)) { [void]$cb.Items.Add($i); if ($i.Tag -eq $cur) { $cb.SelectedItem = $i } } }
    Update-WizProfiles
    $ui.WizSetItems.Children.Clear()
    foreach ($k in $WinSettingsDefs.Keys) { $c = New-Object Windows.Controls.CheckBox; $c.Content = $WinSettingsDefs[$k]; $c.Tag = $k; $c.Width = 400; $c.Margin = '0,0,0,6'; $c.IsChecked = ($k -notin 'Hosts', 'Umgebung'); [void]$ui.WizSetItems.Children.Add($c) }
    foreach ($n in $WizFields) { $c = $ui[$n]; if ($c -is [Windows.Controls.CheckBox]) { $c.Add_Click({ Update-WizSummary }) } elseif ($c -is [Windows.Controls.ComboBox]) { $c.Add_SelectionChanged({ param($s, $e) $e.Handled = $true; Update-WizSummary }) } }
    $last = Join-Path $WizardDir 'vorlage.json'; if (Test-Path -LiteralPath $last) { try { Set-WizState (Get-Content -LiteralPath $last -Raw -Encoding UTF8 | ConvertFrom-Json) } catch { } }
    Update-WizSummary
}
function Update-WizProfiles {
    $sel = @($ui.WizProfiles.Children | Where-Object { $_.IsChecked } | ForEach-Object { $_.Tag })
    if (-not $ui.WizProfiles.Children.Count) { $sel = @('Basis') }
    $ui.WizProfiles.Children.Clear()
    foreach ($p in $DeviceProfiles) {
        $c = New-Object Windows.Controls.CheckBox; $c.Tag = $p.Key; $c.Width = 230; $c.Margin = '0,0,0,6'; $c.IsChecked = ($sel -contains $p.Key)
        $sp = New-Object Windows.Controls.StackPanel; $sp.Orientation = 'Horizontal'
        $dot = New-Object Windows.Controls.Border; $dot.Width = 10; $dot.Height = 10; $dot.CornerRadius = '5'; $dot.Background = New-UiBrush $p.Color; $dot.Margin = '0,0,6,0'; $dot.VerticalAlignment = 'Center'
        $t = New-Object Windows.Controls.TextBlock; $t.Text = $p.Name; $t.Foreground = New-UiBrush '#1F2A44'
        [void]$sp.Children.Add($dot); [void]$sp.Children.Add($t); $c.Content = $sp; $c.ToolTip = $p.Desc
        $c.Add_Click({ Update-WizSummary })
        [void]$ui.WizProfiles.Children.Add($c)
    }
}
function Get-WizLines([string]$Text) { @(($Text -split "`r?`n") | ForEach-Object { $_.Trim() } | Where-Object { $_ -and -not $_.StartsWith('#') } | ForEach-Object { , @($_ -split '\s*\|\s*') }) }
function Get-WizState {
    $h = [ordered]@{}
    foreach ($n in $WizFields) { $c = $ui[$n]; $h[$n] = if ($c -is [Windows.Controls.CheckBox]) { [bool]$c.IsChecked } elseif ($c -is [Windows.Controls.ComboBox]) { $c.SelectedIndex } else { $c.Text } }
    $h.Tz = [string]$ui.WizTz.SelectedItem.Tag
    $h.Profiles = @($ui.WizProfiles.Children | Where-Object { $_.IsChecked } | ForEach-Object { $_.Tag })
    $h.SetItems = @($ui.WizSetItems.Children | Where-Object { $_.IsChecked } | ForEach-Object { $_.Tag })
    return $h
}
function Set-WizState($s) {
    foreach ($n in $WizFields) { if ($null -eq $s.$n) { continue }; $c = $ui[$n]; if ($c -is [Windows.Controls.CheckBox]) { $c.IsChecked = [bool]$s.$n } elseif ($c -is [Windows.Controls.ComboBox]) { $c.SelectedIndex = [int]$s.$n } else { $c.Text = [string]$s.$n } }
    if ($s.Tz) { foreach ($i in $ui.WizTz.Items) { if ($i.Tag -eq $s.Tz) { $ui.WizTz.SelectedItem = $i } } }
    if ($s.Profiles) { foreach ($c in $ui.WizProfiles.Children) { $c.IsChecked = (@($s.Profiles) -contains $c.Tag) } }
    if ($s.SetItems) { foreach ($c in $ui.WizSetItems.Children) { $c.IsChecked = (@($s.SetItems) -contains $c.Tag) } }
}
# Aus der Oberfläche die Beschreibung des Laufs bauen (Teile, Programme, Job). -ForStick: Kennwörter nicht an diesen PC binden
function Get-WizSpec([switch]$ForStick) {
    $prot = { param($p) if (-not $p) { '' } elseif ($ForStick) { 'plain:' + $p } else { Protect-PString $p } }
    $on = { param($n) [bool]$ui[$n].IsChecked }
    $w = [ordered]@{ Round = 1 }
    if (& $on 'WizOnBase') { $w.ComputerName = $ui.WizName.Text.Trim(); $w.TimeZone = [string]$ui.WizTz.SelectedItem.Tag; $w.Region = & $on 'WizRegion'; $w.Theme = [string]$ui.WizTheme.SelectedItem.Content }
    if (& $on 'WizOnPower') { $w.Power = [string]$ui.WizPower.SelectedItem.Content; $w.ScreenAc = $ui.WizScrAc.Text.Trim(); $w.ScreenDc = $ui.WizScrDc.Text.Trim(); $w.SleepAc = $ui.WizSlpAc.Text.Trim(); $w.SleepDc = $ui.WizSlpDc.Text.Trim(); $w.Lid = [string]$ui.WizLid.SelectedItem.Content }
    if (& $on 'WizOnUx') { $w.Privacy = & $on 'WizPrivacy'; $w.Explorer = & $on 'WizExplorer'; $w.ShowHidden = & $on 'WizHidden'; $w.ClassicMenu = & $on 'WizClassic'; $w.Taskbar = & $on 'WizTaskbar'; $w.TaskbarLeft = & $on 'WizTaskLeft'; $w.Rdp = & $on 'WizRdp' }
    if (& $on 'WizOnBloat') { $w.DebloatLevel = $ui.WizBloat.SelectedIndex + 1 }
    if (& $on 'WizOnNet') {
        $w.Users = @(Get-WizLines $ui.WizUsers.Text | ForEach-Object { [pscustomobject]@{ Name = $_[0]; Pwd = (& $prot $(if ($_.Count -gt 1) { $_[1] } else { '' })); Admin = ($_.Count -gt 2 -and $_[2] -match '^(admin|ja|j|yes|1)$'); Full = '' } })
        $w.Drives = @(Get-WizLines $ui.WizDrives.Text | Where-Object { $_.Count -ge 2 } | ForEach-Object { [pscustomobject]@{ Letter = $_[0].TrimEnd(':'); Path = $_[1]; User = $(if ($_.Count -gt 2) { $_[2] } else { '' }); Pwd = (& $prot $(if ($_.Count -gt 3) { $_[3] } else { '' })) } })
        $w.Printers = @(Get-WizLines $ui.WizPrinters.Text | Where-Object { $_.Count -ge 2 } | ForEach-Object { [pscustomobject]@{ Name = $_[0]; Ip = $_[1]; Driver = $(if ($_.Count -gt 2) { $_[2] } else { '' }) } })
    }
    if (& $on 'WizOnUpd') { $w.UpdateRounds = $ui.WizRounds.SelectedIndex + 1; $w.AllowReboot = & $on 'WizReboot' } else { $w.UpdateRounds = 1; $w.AllowReboot = $false }
    if (& $on 'WizOnCorp') {
        $t = { param($n) $ui[$n].Text.Trim() }
        $w.Company = [ordered]@{ Org = & $t 'WizCoOrg'; Owner = & $t 'WizCoOwner'; Naming = & $t 'WizCoNaming'; Asset = & $t 'WizCoAsset'; InvDir = & $t 'WizCoInvDir'; SupName = & $t 'WizCoSupName'; SupPhone = & $t 'WizCoSupPhone'; SupUrl = & $t 'WizCoSupUrl'
            Domain = & $t 'WizCoDomain'; Ou = & $t 'WizCoOu'; DomUser = & $t 'WizCoDomUser'; DomPwd = (& $prot $ui.WizCoDomPwd.Password); Tenant = & $t 'WizCoTenant'; Entra = & $on 'WizCoEntra'
            LockMin = & $t 'WizCoLock'; PwLen = & $t 'WizCoPwLen'; PwLock = & $t 'WizCoPwLock'; Usb = [string]$ui.WizCoUsb.SelectedItem.Content; Asr = [string]$ui.WizCoAsr.SelectedItem.Content; AdminOff = & $on 'WizCoAdminOff'; NoConsumer = & $on 'WizCoNoConsumer'
            Legal = & $t 'WizCoLegal'; LockImg = & $t 'WizCoLockImg'; DeskImg = & $t 'WizCoDeskImg'; Wifi = & $t 'WizCoWifi'; WifiPwd = (& $prot $ui.WizCoWifiPwd.Password); VpnName = & $t 'WizCoVpnName'; VpnSrv = & $t 'WizCoVpnSrv'; VpnType = [string]$ui.WizCoVpnType.SelectedItem.Content; VpnPsk = (& $prot $ui.WizCoVpnPsk.Password)
            Proxy = & $t 'WizCoProxy'; ProxyEx = & $t 'WizCoProxyEx'; Ntp = & $t 'WizCoNtp'; CertDir = & $t 'WizCoCertDir' }
    }
    if (& $on 'WizOnFinish') { $w.BitLocker = & $on 'WizBitLocker'; $w.KeyDir = $ui.WizKeyDir.Text.Trim(); $w.Report = & $on 'WizReport' }
    $parts = [System.Collections.Generic.List[string]]::new()
    if ((& $on 'WizOnBase') -or (& $on 'WizOnPower') -or (& $on 'WizOnUx') -or (& $on 'WizOnBloat') -or (@($w.Users).Count)) { $parts.Add('WizardBase') }
    if (& $on 'WizOnCorp') { if (-not $parts.Contains('WizardBase')) { $parts.Add('WizardBase') }; $parts.Add('WizardCompany') }
    if (& $on 'WizOnBloat') { $parts.Add('Debloat') }
    $nin = @(); $wg = @(); $dir = @(); $win = @()
    if (& $on 'WizOnApps') {
        $items = if ((& $on 'WizUseSetup') -and @($script:ProfItems).Count) { @($script:ProfItems | Where-Object { $_.Check.IsChecked } | ForEach-Object { $_.Item }) }
                 else { $keys = @($ui.WizProfiles.Children | Where-Object { $_.IsChecked } | ForEach-Object { $_.Tag }); @($DeviceProfiles | Where-Object { $keys -contains $_.Key } | ForEach-Object { Get-ProfileItems $_ } | Where-Object Pre) }
        $nin = @($items | Where-Object Src -eq 'Ninite' | ForEach-Object { $_.Id } | Select-Object -Unique); $wg = @($items | Where-Object Src -eq 'winget' | ForEach-Object { $_.Id } | Select-Object -Unique)
        $dir = @($items | Where-Object Src -eq 'Hersteller' | ForEach-Object { $_.Id } | Select-Object -Unique); $win = @($items | Where-Object Src -eq 'Windows' | ForEach-Object { $_.Id } | Select-Object -Unique)
        if ($nin.Count) { $parts.Add('NiniteInstall') }; if ($wg.Count) { $parts.Add('WingetInstall') }; if ($dir.Count) { $parts.Add('DirectInstall') }; if ($win.Count) { $parts.Add('WinFeatures') }
    }
    if (& $on 'WizOnUpd') { if (& $on 'WizOemPack') { $parts.Add('OemPack') }; if (& $on 'WizDrivers') { $parts.Add('Drivers') } }
    if ((& $on 'WizOnNet') -and (@($w.Drives).Count -or @($w.Printers).Count)) { $parts.Add('NetSetup') }
    $setDir = ''; $setItems = @()
    if ((& $on 'WizOnSet') -and $ui.WizSetDir.Text.Trim()) { $setDir = $ui.WizSetDir.Text.Trim(); $setItems = @($ui.WizSetItems.Children | Where-Object { $_.IsChecked } | ForEach-Object { $_.Tag }); $parts.Add('WinSettingsImport') }
    if ((& $on 'WizOnUpd') -and (& $on 'WizUpdates')) { $parts.Add('Update') }
    $parts.Add('WizardFinish')
    $job = @{ Wizard = $w; WinFeatures = $win; SettingsDir = $setDir; SettingsItems = $setItems; Provisioned = $true; Apps = @(); Win32 = @() }
    [pscustomobject]@{ Parts = @($parts); NiniteApps = $nin; WingetApps = $wg; DirectApps = $dir; Job = $job; Carefree = ((& $on 'WizOnFinish') -and (& $on 'WizCarefree')) }
}
function Update-WizSummary {
    if (-not $script:WizInit) { return }
    $ui.WizSteps.Children.Clear()
    $steps = @(@('WizOnBase', 'Gerät'), @('WizOnPower', 'Energie'), @('WizOnUx', 'Datenschutz'), @('WizOnBloat', 'Apps weg'), @('WizOnApps', 'Programme'), @('WizOnUpd', 'Treiber/Updates'), @('WizOnNet', 'Konten/Netz'), @('WizOnSet', 'Alte Einstellungen'), @('WizOnCorp', 'Unternehmen'), @('WizOnFinish', 'Abschluss'))
    $i = 0
    foreach ($st in $steps) {
        $i++; $on = [bool]$ui[$st[0]].IsChecked
        $b = New-Object Windows.Controls.Border; $b.CornerRadius = '14'; $b.Padding = '10,4'; $b.Margin = '0,0,8,6'
        $b.Background = (New-Object Windows.Media.BrushConverter).ConvertFromString($(if ($on) { '#FFFFFF' } else { '#40FFFFFF' }))
        $t = New-Object Windows.Controls.TextBlock; $t.Text = '{0}  {1}' -f $i, $st[1]; $t.FontWeight = 'SemiBold'
        $t.Foreground = (New-Object Windows.Media.BrushConverter).ConvertFromString($(if ($on) { '#2D3FA8' } else { '#FFFFFF' })); $t.TextDecorations = $(if ($on) { $null } else { [Windows.TextDecorations]::Strikethrough })
        $b.Child = $t; [void]$ui.WizSteps.Children.Add($b)
    }
    try {
        $s = Get-WizSpec
        $napps = @($s.NiniteApps).Count + @($s.WingetApps).Count + @($s.DirectApps).Count
        $ui.WizSummary.Text = 'Ablauf: {0}.  {1} Programme.  {2} Update-Runde(n){3}.  Dauer je nach Internet und Updates: 30 Minuten bis 2 Stunden.' -f (($s.Parts | ForEach-Object { switch ($_) { 'WizardBase' { 'Grundeinstellungen' } 'WizardCompany' { 'Unternehmen' } 'Debloat' { 'Apps entfernen' } 'NiniteInstall' { 'Programme (Ninite)' } 'WingetInstall' { 'Programme (winget)' } 'DirectInstall' { 'Programme (Hersteller)' } 'WinFeatures' { 'Windows-Funktionen' } 'OemPack' { 'Treiberpaket' } 'Drivers' { 'Treiber' } 'NetSetup' { 'Laufwerke/Drucker' } 'WinSettingsImport' { 'alte Einstellungen' } 'Update' { 'Updates' } 'WizardFinish' { 'Abschluss' } default { $_ } } }) -join ' > '), $napps, $s.Job.Wizard.UpdateRounds, $(if ($s.Job.Wizard.AllowReboot) { ' mit automatischem Neustart' } else { '' })
    } catch { $ui.WizSummary.Text = $_.Exception.Message }
}
function Set-CarefreeSilent {
    foreach ($n in 'Schedule_Enabled', 'Schedule_Clean', 'Schedule_Optimize', 'Schedule_Update', 'Schedule_WakeToRun', 'Settings_UpdateAuto', 'Settings_UpdateInSchedule', 'Optimize_RestorePoint') { Set-UiCheck $n $true }
    if ($ui.Backup_Target.Text.Trim()) { Set-UiCheck 'Backup_Enabled' $true }
    $null = Save-All -Quiet
    try { Set-NetFirewallProfile -Profile Domain, Private, Public -Enabled True -ErrorAction Stop } catch { }
    try { Set-Content -LiteralPath (Join-Path $DataDir 'sorgenfrei.txt') -Value (Get-Date).ToString('o') } catch { }
}
function Start-Wizard {
    if ($script:Job) { Show-UiError 'Es läuft bereits eine Aufgabe - bitte warten, bis sie fertig ist.'; return }
    $s = Get-WizSpec
    if ($s.Job.Wizard.ComputerName -and ($s.Job.Wizard.ComputerName -notmatch '^[A-Za-z0-9-]{1,15}$' -or $s.Job.Wizard.ComputerName -match '^\d+$')) { Show-UiError 'Computername: 1-15 Zeichen, nur Buchstaben, Ziffern und Bindestrich, nicht nur Ziffern.'; return }
    $co = $s.Job.Wizard.Company
    if ($co -and $co.Domain -and (-not $co.DomUser -or -not $co.DomPwd)) { Show-UiError 'Für den Domänenbeitritt bitte Beitritts-Konto und Kennwort angeben.'; return }
    if ($co -and $co.Domain) { try { $null = [Net.Dns]::GetHostAddresses([string]$co.Domain) } catch { if (-not (Confirm-Ui ('Die Domäne {0} ist von hier aus nicht auflösbar (DNS-Server = Domänencontroller?). Trotzdem starten?' -f $co.Domain) 'Warning')) { return } } }
    if ($s.Parts -contains 'NiniteInstall' -and -not (Get-NinitePathGui)) { if (-not (Confirm-Ui 'NinitePro.exe fehlt - Ninite-Programme werden übersprungen. Trotzdem starten?')) { return }; $s.NiniteApps = @(); $s.Parts = @($s.Parts | Where-Object { $_ -ne 'NiniteInstall' }) }
    $q = "Einrichtung starten?`n`n{0}`n`nDu kannst währenddessen weiterarbeiten. {1}" -f $ui.WizSummary.Text, $(if ($s.Job.Wizard.AllowReboot) { 'Der PC startet zwischendurch neu - danach einfach anmelden, es geht nach einer Minute automatisch weiter.' } else { 'Neustarts machst du selbst - danach geht es nach der Anmeldung automatisch weiter.' })
    if (-not (Confirm-Ui $q)) { return }
    New-Item $WizardDir -ItemType Directory -Force | Out-Null
    try { Get-WizState | ConvertTo-Json -Depth 4 | Set-Content (Join-Path $WizardDir 'vorlage.json') -Encoding UTF8 } catch { }
    if ($s.Carefree) { Set-CarefreeSilent }
    Start-Run -Parts $s.Parts -Apps $s.NiniteApps -WingetApps $s.WingetApps -DirectApps $s.DirectApps -Job $s.Job
}
$ui.BtnWizStart.Add_Click({ Start-Wizard })
$ui.BtnWizSetDir.Add_Click({ Select-FolderInto $ui.WizSetDir; Update-WizSummary })
