    if ($d.ShowDialog() -ne 'OK') { return }
    Get-WizState | ConvertTo-Json -Depth 4 | Set-Content -LiteralPath $d.FileName -Encoding UTF8
    $ui.StatusText.Text = 'Vorlage gespeichert (enthält Kennwörter aus Schritt 7 im Klartext - sicher aufbewahren): ' + $d.FileName
