    elseif ($s.SelectedItem -eq $ui.TabUnattend) { Initialize-Wizard; Update-UaPage }
})

# ---------------------------------------------------------------- Eigene Profile (Seite Neues Gerät)
$ProfileDir = Join-Path $DataDir 'Profile'
function Import-CustomProfiles {
    $script:DeviceProfiles = @($DeviceProfiles | Where-Object { -not $_.Custom })
    foreach ($f in @(Get-ChildItem $ProfileDir -Filter *.json -ErrorAction SilentlyContinue | Sort-Object Name)) {
        try {
            $j = Get-Content -LiteralPath $f.FullName -Raw -Encoding UTF8 | ConvertFrom-Json
            if (-not $j.Name -or -not @($j.Apps).Count) { continue }
            $script:DeviceProfiles += [ordered]@{ Key = 'Eigen_' + $f.BaseName; Name = [string]$j.Name; Glyph = 0xE77B; Color = $(if ($j.Color) { [string]$j.Color } else { '#0F766E' }); Desc = $(if ($j.Desc) { [string]$j.Desc } else { 'Eigenes Profil' }); Apps = @($j.Apps | ForEach-Object { [string]$_ }); Custom = $true; File = $f.FullName }
        } catch { }
    }
}
function Update-ProfileCards {
    Import-CustomProfiles
    $ui.ProfPanel.Children.Clear()
    $keep = @($script:ProfSel | Where-Object { $k = $_; @($DeviceProfiles | Where-Object { $_.Key -eq $k }).Count })
    $script:ProfSel.Clear(); foreach ($k in $keep) { $script:ProfSel.Add($k) }
    Build-Profiles; Show-ProfileApps
    if ($script:WizInit) { Update-WizProfiles }
}
function ConvertTo-ProfileEntry($it) {
    switch ($it.Src) { 'Ninite' { 'n:' + $it.Id } 'Hersteller' { 'u:{0}|{1}' -f $it.Id, $it.Label } 'Windows' { '{0}|{1}' -f $it.Id, $it.Label } default { 'w:{0}|{1}' -f $it.Id, $it.Label } }
}
function Save-CustomProfile([string]$Name, [string]$Desc, [string[]]$Apps) {
    New-Item $ProfileDir -ItemType Directory -Force | Out-Null
    $safe = ($Name -replace '[^\w\-äöüÄÖÜß ]', '').Trim() -replace '\s+', '_'
    if (-not $safe) { $safe = 'Profil_{0:yyyyMMddHHmm}' -f (Get-Date) }
    $cols = @('#0F766E', '#2D7FF9', '#7C3AED', '#DB2777', '#EA580C', '#0891B2', '#16A34A')
    [pscustomobject]@{ Name = $Name; Desc = $Desc; Color = $cols[(Get-Random -Maximum $cols.Count)]; Apps = @($Apps); Created = (Get-Date).ToString('o'); Computer = $env:COMPUTERNAME } | ConvertTo-Json -Depth 3 | Set-Content (Join-Path $ProfileDir ($safe + '.json')) -Encoding UTF8
    Update-ProfileCards
}
function Select-CustomProfile([string]$Title) {
    $c = @($DeviceProfiles | Where-Object Custom)
    if (-not $c.Count) { Show-UiError 'Es gibt noch keine eigenen Profile.'; return $null }
    $r = Show-InputDialog $Title 'Eigenes Profil wählen:' @(@{ Key = 'P'; Label = 'Profil'; Type = 'Combo'; Items = @($c | ForEach-Object { $_.Name }) })
    if (-not $r) { return $null }
    return @($c | Where-Object { $_.Name -eq $r.P })[0]
}
$ui.BtnProfSave.Add_Click({
    $sel = @($script:ProfItems | Where-Object { $_.Check.IsChecked } | ForEach-Object { $_.Item })
    if (-not $sel.Count) { Show-UiError 'Bitte oben Profile wählen und unten die gewünschten Programme ankreuzen.'; return }
    $r = Show-InputDialog 'Eigenes Profil speichern' ('{0} ausgewählte Programme als eigenes Profil speichern. Es erscheint danach als eigene Karte und im Einrichtungs-Assistenten.' -f $sel.Count) @(@{ Key = 'N'; Label = 'Name (z.B. Renés Standard)'; Type = 'Text' }, @{ Key = 'D'; Label = 'Beschreibung'; Type = 'Text' })
    if (-not $r -or -not $r.N) { return }
    Save-CustomProfile $r.N $r.D @($sel | ForEach-Object { ConvertTo-ProfileEntry $_ })
    $ui.StatusText.Text = 'Profil "' + $r.N + '" gespeichert.'
})
$ui.BtnProfFromPc.Add_Click({
    $ui.StatusText.Text = 'Installierte Programme werden mit winget abgeglichen (ca. 30 Sekunden) ...'; $window.Cursor = 'Wait'
    Invoke-Bg -Script {
        $wg = Get-WingetPathX; if (-not $wg) { throw 'winget fehlt (App-Installer aus dem Store).' }
        $f = Join-Path $env:TEMP ('pcpflege-export-{0}.json' -f (Get-Random))
        $null = & $wg export -o $f --accept-source-agreements --disable-interactivity 2>&1
        if (-not (Test-Path $f)) { throw 'winget export hat nichts geliefert.' }
        $j = Get-Content $f -Raw | ConvertFrom-Json; Remove-Item $f -Force -ErrorAction SilentlyContinue
        @($j.Sources | Where-Object { $_.SourceDetails.Name -eq 'winget' } | ForEach-Object { $_.Packages } | ForEach-Object { [string]$_.PackageIdentifier })
    } -Functions @('Get-WingetPathX') -Done {
        param($r, $err)
        $window.Cursor = $null
        if ($err) { Show-UiError $err.Message; return }
        $ids = @($r | Where-Object { $_ } | Where-Object { $_ -notmatch '^Microsoft\.(VCRedist|VCLibs|UI\.Xaml|DotNet|WindowsAppRuntime|AppInstaller|Edge|EdgeWebView|OneDrive|Teams\.Classic)|^Microsoft\.DirectX' } | Sort-Object -Unique)
        if (-not $ids.Count) { Show-UiError 'Keine Programme gefunden, die sich über winget installieren lassen.'; return }
        $lbl = { param($id) $p = $id -split '\.'; if ($p.Count -gt 1) { ($p[1..($p.Count - 1)] -join ' ') } else { $id } }
        $d = Show-InputDialog 'Profil aus diesem PC' ("{0} Programme dieses PCs lassen sich automatisch installieren:`n{1}" -f $ids.Count, (($ids | Select-Object -First 18) -join ', ') + $(if ($ids.Count -gt 18) { ' ...' } else { '' })) @(@{ Key = 'N'; Label = 'Name des Profils'; Type = 'Text'; Value = ('Programme von ' + $env:COMPUTERNAME) })
        if (-not $d -or -not $d.N) { return }
        Save-CustomProfile $d.N ('Aus {0} übernommen ({1} Programme)' -f $env:COMPUTERNAME, $ids.Count) @($ids | ForEach-Object { 'w:{0}|{1}' -f $_, (& $lbl $_) })
        $ui.StatusText.Text = ('Profil "{0}" mit {1} Programmen angelegt - oben als Karte auswählbar.' -f $d.N, $ids.Count)
    }
})
$ui.BtnProfImport.Add_Click({
    Add-Type -AssemblyName System.Windows.Forms
    $d = New-Object System.Windows.Forms.OpenFileDialog; $d.Filter = 'PC-Tools-Profil (*.json)|*.json'
    if ($d.ShowDialog() -ne 'OK') { return }
    try { $j = Get-Content -LiteralPath $d.FileName -Raw -Encoding UTF8 | ConvertFrom-Json; if (-not $j.Name -or -not @($j.Apps).Count) { throw 'Kein gültiges Profil.' }; New-Item $ProfileDir -ItemType Directory -Force | Out-Null; Copy-Item -LiteralPath $d.FileName (Join-Path $ProfileDir ([IO.Path]::GetFileName($d.FileName))) -Force; Update-ProfileCards; $ui.StatusText.Text = 'Profil "' + $j.Name + '" importiert.' } catch { Show-UiError $_.Exception.Message }
})
$ui.BtnProfExport.Add_Click({
    $p = Select-CustomProfile 'Profil exportieren'; if (-not $p) { return }
    Add-Type -AssemblyName System.Windows.Forms
    $d = New-Object System.Windows.Forms.SaveFileDialog; $d.Filter = 'PC-Tools-Profil (*.json)|*.json'; $d.FileName = [IO.Path]::GetFileName($p.File)
    if ($d.ShowDialog() -eq 'OK') { Copy-Item -LiteralPath $p.File $d.FileName -Force; $ui.StatusText.Text = 'Profil exportiert: ' + $d.FileName }
})
$ui.BtnProfDelete.Add_Click({
    $p = Select-CustomProfile 'Profil löschen'; if (-not $p) { return }
    if (Confirm-Ui ('Eigenes Profil "{0}" löschen?' -f $p.Name)) { Remove-Item -LiteralPath $p.File -Force; [void]$script:ProfSel.Remove($p.Key); Update-ProfileCards }
})

# ---------------------------------------------------------------- Automatische Installation (Oberfläche)
function Update-UaDrives {
    $ui.UaDrive.Items.Clear()
    foreach ($v in @(Get-Volume -ErrorAction SilentlyContinue | Where-Object { $_.DriveLetter -and ($_.DriveType -eq 'Removable' -or ((Get-Partition -DriveLetter $_.DriveLetter -ErrorAction SilentlyContinue | Get-Disk -ErrorAction SilentlyContinue).BusType -eq 'USB')) })) {
        $root = '{0}:\' -f $v.DriveLetter
        $win = (Test-Path (Join-Path $root 'setup.exe')) -and (Test-Path (Join-Path $root 'sources'))
        $i = New-Object Windows.Controls.ComboBoxItem; $i.Tag = $root
        $i.Content = '{0}  {1}  ({2:N0} GB){3}' -f $root, $v.FileSystemLabel, ($v.Size / 1GB), $(if ($win) { '  -  Windows-Installationsstick erkannt' } else { '  -  kein Windows-Stick' })
        [void]$ui.UaDrive.Items.Add($i)
    }
    if ($ui.UaDrive.Items.Count) { $ui.UaDrive.SelectedIndex = 0; $ui.UaInfo.Text = '' } else { $ui.UaInfo.Text = 'Kein USB-Stick gefunden. Stick einstecken und "Laufwerke neu suchen".' }
}
function Update-UaPage {
    if (-not $ui.UaDrive.Items.Count) { Update-UaDrives }
    $ui.UaSpecInfo.Text = 'Nach der Installation läuft der Einrichtungs-Assistent mit diesen Schritten: ' + $ui.WizSummary.Text
}
function Get-UaOptions {
    [pscustomobject]@{ Language = [string]$ui.UaLang.SelectedItem.Content; Edition = [string]$ui.UaEdition.SelectedItem.Content; ComputerName = $ui.UaName.Text.Trim(); TimeZone = [string]$ui.UaTz.SelectedItem.Tag
        User = $ui.UaUser.Text.Trim(); Password = $ui.UaPwd.Password; NoConsumer = [bool]$ui.UaNoConsumer.IsChecked; NoAutoBitLocker = [bool]$ui.UaNoBitLocker.IsChecked; ShowWifi = [bool]$ui.UaWifi.IsChecked; Bypass = [bool]$ui.UaBypass.IsChecked
        RunPflege = [bool]$ui.UaRunPflege.IsChecked; Token = [bool]$ui.UaToken.IsChecked }
}
function Test-UaOptions($o) {
    if ($o.User -and $o.User -notmatch '^[\w\.\- ]{1,20}$') { Show-UiError 'Benutzername: bis 20 Zeichen, keine Sonderzeichen wie \ / " [ ] : ; | = , + * ? < >'; return $false }
    if ($o.Password -match '"') { Show-UiError 'Das Kennwort darf keine Anführungszeichen enthalten.'; return $false }
    if ($o.ComputerName -and ($o.ComputerName -notmatch '^[A-Za-z0-9-]{1,15}$' -or $o.ComputerName -match '^\d+$')) { Show-UiError 'Computername: 1-15 Zeichen, Buchstaben, Ziffern und Bindestrich.'; return $false }
    if (-not $o.User -and -not (Confirm-Ui 'Ohne Benutzername fragt Windows beim Setup nach einem Konto (und drängt zum Microsoft-Konto). Trotzdem so?')) { return $false }
    return $true
}
$ui.BtnUaRefresh.Add_Click({ Update-UaDrives })
$ui.BtnUaWizard.Add_Click({ $ui.Tabs.SelectedItem = $ui.TabWizard })
$ui.BtnUaMedia.Add_Click({ $ui.Tabs.SelectedItem = $ui.TabMedia })
$ui.BtnUaWrite.Add_Click({
    $i = $ui.UaDrive.SelectedItem; if (-not $i) { Show-UiError 'Bitte einen USB-Stick wählen.'; return }
    $o = Get-UaOptions; if (-not (Test-UaOptions $o)) { return }
    if ($i.Content -match 'kein Windows-Stick' -and -not (Confirm-Ui 'Auf dem Stick wurde keine Windows-Installation gefunden. Die Antwortdatei wirkt nur auf einem Windows-Installationsstick. Trotzdem schreiben?')) { return }
    $spec = $null; if ($o.RunPflege) { Initialize-Wizard; $spec = Get-WizSpec -ForStick; $spec.Job.Wizard.ComputerName = '' }
    if ($spec -and (@($spec.Job.Wizard.Users | Where-Object { $_.Pwd }).Count -or @($spec.Job.Wizard.Drives | Where-Object { $_.Pwd }).Count) -and -not (Confirm-Ui 'Die Kennwörter aus Schritt 7 des Assistenten stehen dann im Klartext auf dem Stick. Stick danach sicher aufbewahren. Weiter?')) { return }
    try {
        $files = Write-UnattendStick $i.Tag $o $spec
        $ui.UaInfo.Text = 'Fertig. Geschrieben: ' + ($files -join ', ') + '. Vom Stick starten (Boot-Menü: F12 bei Lenovo/Dell, F9 bei HP) - der Rest läuft allein.'
        [Windows.MessageBox]::Show((T (("Der Stick ist bereit.`n`nSo geht es weiter:`n1. Stick in den neuen PC, vom Stick starten (Boot-Menü F12/F9/F11/Esc).`n2. Bei der Frage nach der Festplatte die richtige wählen (alte Partitionen ggf. löschen).`n3. Den Rest macht Windows allein - nach dem ersten Anmelden richtet sich PC-Tools ein und startet den Einrichtungs-Assistenten.`n`nAchtung: Der Stick installiert auf jedem PC, von dem gestartet wird, ohne weitere Fragen - vorsichtig aufbewahren."))), (T ('PC-Tools')), 'OK', 'Information') | Out-Null
    } catch { Show-UiError ('Schreiben fehlgeschlagen: ' + $_.Exception.Message) }
})
$ui.BtnUaSave.Add_Click({
    $o = Get-UaOptions; if (-not (Test-UaOptions $o)) { return }
    Add-Type -AssemblyName System.Windows.Forms
    $d = New-Object System.Windows.Forms.SaveFileDialog; $d.Filter = 'Antwortdatei (autounattend.xml)|autounattend.xml|XML (*.xml)|*.xml'; $d.FileName = 'autounattend.xml'
    if ($d.ShowDialog() -ne 'OK') { return }
    $o.RunPflege = $false
    [IO.File]::WriteAllText($d.FileName, (New-UnattendXml $o), (New-Object Text.UTF8Encoding $false))
    $ui.StatusText.Text = 'Antwortdatei gespeichert (ohne PC-Tools-Erststart): ' + $d.FileName
})

# ---------------------------------------------------------------- Neugerät-Check (Oberfläche)
$ChkTests = @(
    @{ K = 'Display';  T = 'Bildschirm';           G = 0xE7F4; C = '#2D7FF9'; A = $false; D = 'Farbflächen im Vollbild: auf Pixelfehler, Flecken und helle Ränder achten.' }
    @{ K = 'Keyboard'; T = 'Tastatur';             G = 0xE765; C = '#7C3AED'; A = $false; D = 'Jede Taste einmal drücken - gedrückte Tasten werden grün.' }
    @{ K = 'Camera';   T = 'Kamera';               G = 0xE722; C = '#0891B2'; A = $false; D = 'Öffnet die Kamera-App: Bild scharf, Farben natürlich?' }
    @{ K = 'Mic';      T = 'Mikrofon';             G = 0xE720; C = '#DB2777'; A = $false; D = '5 Sekunden sprechen, dann wird die Aufnahme abgespielt und der Pegel gemessen.' }
    @{ K = 'Speaker';  T = 'Lautsprecher';         G = 0xE767; C = '#EA580C'; A = $false; D = 'Ton erst links, dann rechts, dann beide - auf Kratzen und Scheppern achten.' }
    @{ K = 'Usb';      T = 'USB-Anschlüsse';       G = 0xE88E; C = '#475569'; A = $false; D = 'Einen USB-Stick nacheinander in jeden Anschluss stecken - jeder wird angezeigt.' }
    @{ K = 'Net';      T = 'WLAN und Bluetooth';   G = 0xE701; C = '#2D7FF9'; A = $true;  D = 'Adapter, Signalstärke, Netze in Reichweite und Bluetooth-Funk.' }
    @{ K = 'Battery';  T = 'Akku';                 G = 0xE83F; C = '#16A34A'; A = $true;  D = 'Kapazität gegenüber Neuzustand, Ladezyklen und ausführlicher Akkubericht.' }
    @{ K = 'Disk';     T = 'SSD / Festplatte';     G = 0xEDA2; C = '#0F766E'; A = $true;  D = 'Zustand, Verschleiß, Betriebsstunden, Temperatur und Tempo-Messung (1 GB).' }
    @{ K = 'Stress';   T = 'Belastungstest';       G = 0xE945; C = '#DC2626'; A = $true;  D = '60 Sekunden volle Prozessorlast: Takt, Temperatur, Drosselung.' }
    @{ K = 'Ram';      T = 'Arbeitsspeicher';      G = 0xE964; C = '#7C3AED'; A = $false; D = 'Speicherriegel anzeigen und Windows-Speicherdiagnose beim Neustart.' }
    @{ K = 'Devices';  T = 'Geräte und Treiber';   G = 0xE7F8; C = '#D97706'; A = $true;  D = 'Alle Geräte haben Treiber und laufen fehlerfrei.' }
    @{ K = 'License';  T = 'Windows-Lizenz';       G = 0xE8D7; C = '#D97706'; A = $true;  D = 'Windows aktiviert? Welche Lizenzart?' }
)
$ChkFile = Join-Path $DataDir 'Neugeraet-Check.json'
$script:ChkRes = @{}; $script:ChkTiles = @{}; $script:ChkQueue = [System.Collections.Generic.List[string]]::new()
function Add-ChkLog([string]$Text) { $ui.ChkLog.AppendText(('{0:HH:mm:ss}  {1}' -f (Get-Date), $Text) + [Environment]::NewLine); $ui.ChkLog.ScrollToEnd() }
function Set-ChkResult([string]$K, [string]$State, [string]$Detail) {
    $script:ChkRes[$K] = [pscustomobject]@{ State = $State; Detail = $Detail; Time = (Get-Date).ToString('dd.MM.yyyy HH:mm') }
    $t = @($ChkTests | Where-Object { $_.K -eq $K })[0]
    Add-ChkLog ('{0}: {1}{2}' -f $t.T, @{ ok = 'in Ordnung'; bad = 'FEHLER'; warn = 'Hinweis'; run = 'läuft ...'; open = 'offen' }[$State], $(if ($Detail) { ' - ' + $Detail } else { '' }))
    Update-ChkTile $K
    if ($State -ne 'run') { try { $o = @{}; foreach ($k in $script:ChkRes.Keys) { if ($script:ChkRes[$k].State -ne 'run') { $o[$k] = $script:ChkRes[$k] } }; [pscustomobject]$o | ConvertTo-Json -Depth 3 | Set-Content $ChkFile -Encoding UTF8 } catch { } }
    if ($State -ne 'run' -and $script:ChkQueue.Count) { $n = $script:ChkQueue[0]; $script:ChkQueue.RemoveAt(0); Start-ChkTest $n }
}
function Update-ChkTile([string]$K) {
    $tile = $script:ChkTiles[$K]; if (-not $tile) { return }
    $r = $script:ChkRes[$K]; $st = if ($r) { $r.State } else { 'open' }
    $map = @{ ok = @('#DCFCE7', '#15803D', 'In Ordnung'); bad = @('#FEE2E2', '#C81E1E', 'Fehler'); warn = @('#FEF3C7', '#B45309', 'Hinweis'); run = @('#DCE8FF', '#1D4ED8', 'Läuft ...'); open = @('#EEF2F8', '#475569', 'Offen') }
    $m = $map[$st]
    $tile.Badge.Background = New-UiBrush $m[0]; $tile.BadgeText.Foreground = New-UiBrush $m[1]; $tile.BadgeText.Text = $m[2]
    $tile.Detail.Text = if ($r -and $r.Detail) { $r.Detail } else { '' }
    $tile.Card.BorderBrush = New-UiBrush $(if ($st -eq 'bad') { '#F87171' } elseif ($st -eq 'ok') { '#86EFAC' } else { '#E2E7F0' })
    $vals = @($script:ChkRes.Values)
    $ok = @($vals | Where-Object State -eq 'ok').Count; $bad = @($vals | Where-Object State -eq 'bad').Count
    $ui.ChkOk.Text = [string]$ok; $ui.ChkBad.Text = [string]$bad; $ui.ChkOpen.Text = [string]($ChkTests.Count - @($vals | Where-Object { $_.State -in 'ok', 'bad', 'warn' }).Count)
    $ui.ChkTitle.Text = if ($bad) { '{0} Test(s) mit Fehler - Rückgabe oder Garantie prüfen' -f $bad } elseif ($ok -eq $ChkTests.Count) { 'Alles geprüft - das Gerät ist in Ordnung' } elseif ($ok) { '{0} von {1} Tests bestanden' -f $ok, $ChkTests.Count } else { 'Noch nichts geprüft' }
}
function Build-ChkTiles {
    $ui.ChkTiles.Children.Clear(); $script:ChkTiles = @{}
    foreach ($t in $ChkTests) {
        $card = New-Object Windows.Controls.Border; $card.Width = 300; $card.Margin = '0,0,12,12'; $card.Padding = '14,12'; $card.CornerRadius = '12'; $card.BorderThickness = '1.5'
        $card.Background = New-UiBrush 'White'; $card.BorderBrush = New-UiBrush '#E2E7F0'
        $sp = New-Object Windows.Controls.StackPanel
        $hd = New-Object Windows.Controls.Grid
        foreach ($w in 'Auto', '*', 'Auto') { $cd = New-Object Windows.Controls.ColumnDefinition; $cd.Width = $w; [void]$hd.ColumnDefinitions.Add($cd) }
        $ic = New-Object Windows.Controls.Border; $ic.Width = 36; $ic.Height = 36; $ic.CornerRadius = '10'; $ic.Background = New-UiBrush $t.C; $ic.Margin = '0,0,10,0'
        $gl = New-Object Windows.Controls.TextBlock; $gl.FontFamily = 'Segoe MDL2 Assets'; $gl.Text = [string][char]$t.G; $gl.FontSize = 17; $gl.Foreground = New-UiBrush '#FFFFFF'; $gl.HorizontalAlignment = 'Center'; $gl.VerticalAlignment = 'Center'; $ic.Child = $gl
        $tt = New-Object Windows.Controls.TextBlock; $tt.Text = $t.T; $tt.FontSize = 15; $tt.FontWeight = 'SemiBold'; $tt.Foreground = New-UiBrush '#1F2A44'; $tt.VerticalAlignment = 'Center'; [Windows.Controls.Grid]::SetColumn($tt, 1)
        $bg = New-Object Windows.Controls.Border; $bg.CornerRadius = '9'; $bg.Padding = '8,2'; $bg.VerticalAlignment = 'Center'; [Windows.Controls.Grid]::SetColumn($bg, 2)
        $bt = New-Object Windows.Controls.TextBlock; $bt.FontSize = 11; $bt.FontWeight = 'SemiBold'; $bg.Child = $bt
        [void]$hd.Children.Add($ic); [void]$hd.Children.Add($tt); [void]$hd.Children.Add($bg)
        $ds = New-Object Windows.Controls.TextBlock; $ds.Text = $t.D; $ds.TextWrapping = 'Wrap'; $ds.FontSize = 12; $ds.Foreground = New-UiBrush '#6B7890'; $ds.Margin = '0,8,0,0'; $ds.Height = 34
        $dt = New-Object Windows.Controls.TextBlock; $dt.TextWrapping = 'Wrap'; $dt.FontSize = 12; $dt.Foreground = New-UiBrush '#1F2A44'; $dt.Margin = '0,4,0,0'; $dt.MinHeight = 32; $dt.MaxHeight = 64; $dt.TextTrimming = 'WordEllipsis'
        $bp = New-Object Windows.Controls.WrapPanel; $bp.Margin = '0,8,0,0'
        foreach ($b in @(@('Testen', 'go'), @('OK', 'ok'), @('Fehler', 'bad'))) {
            $btn = New-Object Windows.Controls.Button; $btn.Content = $b[0]; $btn.Tag = ('{0}|{1}' -f $t.K, $b[1]); $btn.Padding = '12,5'; $btn.Margin = '0,0,6,0'
            if ($b[1] -ne 'go') { $btn.Style = $window.FindResource('Sec') }
            $btn.Add_Click({ param($s, $e) $k, $a = ([string]$s.Tag) -split '\|'; if ($a -eq 'go') { Start-ChkTest $k } else { $r = $script:ChkRes[$k]; Set-ChkResult $k $a $(if ($r -and $r.Detail) { $r.Detail } else { $(if ($a -eq 'ok') { 'von Hand bestätigt' } else { 'von Hand als Fehler markiert' }) }) } })
            [void]$bp.Children.Add($btn)
        }
        [void]$sp.Children.Add($hd); [void]$sp.Children.Add($ds); [void]$sp.Children.Add($dt); [void]$sp.Children.Add($bp)
        $card.Child = $sp
        $script:ChkTiles[$t.K] = [pscustomobject]@{ Card = $card; Badge = $bg; BadgeText = $bt; Detail = $dt }
        [void]$ui.ChkTiles.Children.Add($card)
    }
    try { $j = Get-Content $ChkFile -Raw -Encoding UTF8 | ConvertFrom-Json; foreach ($p in $j.PSObject.Properties) { $script:ChkRes[$p.Name] = $p.Value } } catch { }
    foreach ($t in $ChkTests) { Update-ChkTile $t.K }
}
function New-ToneWav([int]$Channel, [double]$Freq = 440, [double]$Sec = 1.2) {
    $rate = 44100; $n = [int]($rate * $Sec); $ms = New-Object IO.MemoryStream; $bw = New-Object IO.BinaryWriter($ms)
    $data = $n * 4
    $bw.Write([Text.Encoding]::ASCII.GetBytes('RIFF')); $bw.Write([int](36 + $data)); $bw.Write([Text.Encoding]::ASCII.GetBytes('WAVEfmt ')); $bw.Write([int]16); $bw.Write([int16]1); $bw.Write([int16]2); $bw.Write([int]$rate); $bw.Write([int]($rate * 4)); $bw.Write([int16]4); $bw.Write([int16]16)
    $bw.Write([Text.Encoding]::ASCII.GetBytes('data')); $bw.Write([int]$data)
    for ($i = 0; $i -lt $n; $i++) {
        $env = [math]::Min(1, [math]::Min($i, $n - $i) / 2000.0)
        $v = [int16](12000 * $env * [math]::Sin(2 * [math]::PI * $Freq * $i / $rate))
        $bw.Write([int16]$(if ($Channel -ne 2) { $v } else { 0 })); $bw.Write([int16]$(if ($Channel -ne 1) { $v } else { 0 }))
    }
    $bw.Flush(); $ms.Position = 0; return $ms
}
function Show-DisplayTest {
