function Show-KeyboardTest {
    $rows = @(
        @('Escape:Esc', 'F1', 'F2', 'F3', 'F4', 'F5', 'F6', 'F7', 'F8', 'F9', 'F10', 'F11', 'F12', 'Snapshot:Druck', 'Insert:Einfg', 'Delete:Entf'),
        @('Oem5:^', 'D1:1', 'D2:2', 'D3:3', 'D4:4', 'D5:5', 'D6:6', 'D7:7', 'D8:8', 'D9:9', 'D0:0', 'OemOpenBrackets:ß', 'Oem6:´', 'Back:← Rück'),
        @('Tab:Tab', 'Q', 'W', 'E', 'R', 'T', 'Z', 'U', 'I', 'O', 'P', 'Oem1:Ü', 'OemPlus:+', 'Return:Enter'),
        @('Capital:Feststell', 'A', 'S', 'D', 'F', 'G', 'H', 'J', 'K', 'L', 'Oem3:Ö', 'OemQuotes:Ä', 'OemQuestion:#'),
        @('LeftShift:Umschalt', 'OemBackslash:<', 'Y', 'X', 'C', 'V', 'B', 'N', 'M', 'OemComma:,', 'OemPeriod:.', 'OemMinus:-', 'RightShift:Umschalt'),
        @('LeftCtrl:Strg', 'LWin:Win', 'LeftAlt:Alt', 'Space:Leertaste', 'RightAlt:AltGr', 'Apps:Menü', 'RightCtrl:Strg', 'Left:←', 'Up:↑', 'Down:↓', 'Right:→'),
        @('Home:Pos1', 'End:Ende', 'PageUp:Bild↑', 'Next:Bild↓', 'NumLock:Num', 'Divide:/', 'Multiply:*', 'Subtract:-', 'Add:+', 'NumPad0:0', 'NumPad1:1', 'NumPad2:2', 'NumPad3:3', 'NumPad4:4', 'NumPad5:5', 'NumPad6:6', 'NumPad7:7', 'NumPad8:8', 'NumPad9:9', 'Decimal:,'))
    $w = New-Object Windows.Window; $w.Title = 'Tastaturtest - jede Taste einmal drücken'; $w.Width = 1200; $w.SizeToContent = 'Height'; $w.WindowStartupLocation = 'CenterOwner'; $w.Owner = $window; $w.Background = New-UiBrush '#F4F6FA'
    $root = New-Object Windows.Controls.StackPanel; $root.Margin = '20'
    $info = New-Object Windows.Controls.TextBlock; $info.FontSize = 15; $info.FontWeight = 'SemiBold'; $info.Margin = '0,0,0,12'; $info.Foreground = New-UiBrush '#1F2A44'; [void]$root.Children.Add($info)
    $keys = @{}; $total = 0
    for ($ri = 0; $ri -lt $rows.Count; $ri++) {
        $wp = New-Object Windows.Controls.WrapPanel; $wp.Margin = '0,0,0,6'
        if ($ri -eq $rows.Count - 1) { $lb = New-Object Windows.Controls.TextBlock; $lb.Text = 'Navigation und Ziffernblock (falls vorhanden):'; $lb.Foreground = New-UiBrush '#6B7890'; $lb.Margin = '0,8,0,4'; [void]$root.Children.Add($lb) }
        foreach ($k in $rows[$ri]) {
            $name, $lbl = $k -split ':', 2; if (-not $lbl) { $lbl = $name }
            $b = New-Object Windows.Controls.Border; $b.MinWidth = $(if ($name -eq 'Space') { 260 } elseif ($lbl.Length -gt 3) { 78 } else { 50 }); $b.Height = 44; $b.Margin = '0,0,5,0'; $b.CornerRadius = '7'; $b.BorderThickness = '1'; $b.BorderBrush = New-UiBrush '#C5CEDD'; $b.Background = New-UiBrush 'White'
            $t = New-Object Windows.Controls.TextBlock; $t.Text = $lbl; $t.HorizontalAlignment = 'Center'; $t.VerticalAlignment = 'Center'; $t.Margin = '6,0'; $t.Foreground = New-UiBrush '#1F2A44'; $b.Child = $t
            [void]$wp.Children.Add($b)
            if (-not $keys.ContainsKey($name)) { $keys[$name] = @() }; $keys[$name] += $b
            if ($ri -lt $rows.Count - 1) { $total++ }
        }
        [void]$root.Children.Add($wp)
    }
    $done = New-Object Windows.Controls.Button; $done.Content = 'Fertig'; $done.Padding = '20,8'; $done.HorizontalAlignment = 'Right'; $done.Margin = '0,10,0,0'; $done.Focusable = $false; $done.Add_Click({ $w.Close() }); [void]$root.Children.Add($done)
    $w.Content = $root
    $script:KbHit = @{}
    $upd = { $main = @($script:KbHit.Keys | Where-Object { $k = $_; $rows[0..($rows.Count - 2)] | ForEach-Object { $_ } | Where-Object { ($_ -split ':')[0] -eq $k } }).Count; $info.Text = '{0} von {1} Haupttasten erkannt. AltGr meldet Windows als Strg+Alt; die Fn-Taste allein ist nicht messbar.' -f $main, $total; $script:KbMain = $main }
    & $upd
    $mark = { param($e) $k = if ($e.Key -eq 'System') { [string]$e.SystemKey } elseif ($e.Key -eq 'ImeProcessed') { [string]$e.ImeProcessedKey } else { [string]$e.Key }; if ($keys.ContainsKey($k)) { foreach ($b in $keys[$k]) { $b.Background = New-UiBrush '#DCFCE7'; $b.BorderBrush = New-UiBrush '#16A34A' }; $script:KbHit[$k] = 1; & $upd }; $e.Handled = $true }
    $w.Add_PreviewKeyDown({ param($s, $e) & $mark $e })
    $w.Add_PreviewKeyUp({ param($s, $e) if ($e.Key -eq 'Snapshot' -or $e.Key -eq 'System') { & $mark $e } })
    [void]$w.ShowDialog()
    $miss = $total - [int]$script:KbMain
    if ($miss -le 0) { Set-ChkResult 'Keyboard' 'ok' ('alle {0} Haupttasten funktionieren' -f $total) }
    elseif (Confirm-Ui ("{0} Haupttaste(n) wurden nicht erkannt. Liegt das nur daran, dass du sie nicht gedrückt hast bzw. die Tastatur sie nicht hat (z.B. kein Druck/Einfg)?`n`nJa = Tastatur in Ordnung, Nein = Tasten defekt" -f $miss)) { Set-ChkResult 'Keyboard' 'ok' ('{0} von {1} Tasten erkannt, Rest nicht vorhanden' -f $script:KbMain, $total) }
    else { Set-ChkResult 'Keyboard' 'bad' ('{0} Taste(n) reagieren nicht' -f $miss) }
}
if (-not ('PCPflege.Mci' -as [type])) { try { Add-Type -Namespace PCPflege -Name Mci -MemberDefinition '[DllImport("winmm.dll", CharSet = CharSet.Unicode)] public static extern int mciSendString(string cmd, System.Text.StringBuilder ret, int len, IntPtr cb);' } catch { } }
function Start-MicTest {
    $f = Join-Path $env:TEMP 'pcpflege-mikrofon.wav'; Remove-Item $f -Force -ErrorAction SilentlyContinue; $script:MicFile = $f
    $m = { param($c) [PCPflege.Mci]::mciSendString($c, $null, 0, [IntPtr]::Zero) }
    $null = & $m 'close pcrec'
    if ((& $m 'open new type waveaudio alias pcrec') -ne 0) { Set-ChkResult 'Mic' 'bad' 'Kein Aufnahmegerät gefunden (Mikrofon aus oder in den Datenschutz-Einstellungen gesperrt?)'; return }
    $null = & $m 'set pcrec bitspersample 16 channels 1 samplespersec 44100'; $null = & $m 'record pcrec'
    Set-ChkResult 'Mic' 'run' 'Jetzt 5 Sekunden sprechen ...'
    $t = New-Object Windows.Threading.DispatcherTimer; $t.Interval = [TimeSpan]::FromSeconds(5)
    $t.Add_Tick({
        $this.Stop(); $f = $script:MicFile
        $null = [PCPflege.Mci]::mciSendString('stop pcrec', $null, 0, [IntPtr]::Zero); $null = [PCPflege.Mci]::mciSendString(('save pcrec "{0}"' -f $f), $null, 0, [IntPtr]::Zero); $null = [PCPflege.Mci]::mciSendString('close pcrec', $null, 0, [IntPtr]::Zero)
        if (-not (Test-Path $f)) { Set-ChkResult 'Mic' 'bad' 'Aufnahme fehlgeschlagen'; return }
        $b = [IO.File]::ReadAllBytes($f); $peak = 0; $sum = 0.0; $n = 0
        for ($i = 44; $i -lt $b.Length - 1; $i += 8) { $v = [math]::Abs([int][BitConverter]::ToInt16($b, $i)); if ($v -gt $peak) { $peak = $v }; $sum += $v; $n++ }
        $pct = [math]::Round($peak * 100 / 32768, 0)
        try { $sp = New-Object Media.SoundPlayer $f; $sp.PlaySync() } catch { }
        $ok = Confirm-Ui ("Aufnahme abgespielt (Spitzenpegel {0} %). Klang deine Stimme klar und ohne Rauschen?" -f $pct)
        if ($pct -lt 2) { Set-ChkResult 'Mic' 'bad' ('fast keine Aufnahme (Pegel {0} %) - Mikrofon stumm oder defekt?' -f $pct) }
        elseif ($ok) { Set-ChkResult 'Mic' 'ok' ('Pegel {0} %, Klang in Ordnung' -f $pct) } else { Set-ChkResult 'Mic' 'bad' ('Pegel {0} %, Klang schlecht' -f $pct) }
    })
    $t.Start()
}
function Start-SpeakerTest {
    Set-ChkResult 'Speaker' 'run' 'Ton links, rechts, beide ...'
    foreach ($ch in 1, 2, 0) { try { $sp = New-Object Media.SoundPlayer (New-ToneWav $ch $(switch ($ch) { 1 { 440 } 2 { 554 } default { 659 } })); $sp.PlaySync(); Start-Sleep -Milliseconds 250 } catch { } }
    $r = [Windows.MessageBox]::Show((T ("Kam der erste Ton nur links, der zweite nur rechts und der dritte aus beiden - ohne Kratzen?`n`nJa = in Ordnung, Nein = Fehler, Abbrechen = nochmal")), (T ('PC-Tools - Lautsprecher')), 'YesNoCancel', 'Question')
    if ($r -eq 'Yes') { Set-ChkResult 'Speaker' 'ok' 'links, rechts und beide in Ordnung' } elseif ($r -eq 'No') { Set-ChkResult 'Speaker' 'bad' 'Ton fehlt, falsche Seite oder verzerrt' } else { Start-SpeakerTest }
}
function Get-UsbDisks { @(Get-CimInstance Win32_DiskDrive -Filter "InterfaceType='USB'" -ErrorAction SilentlyContinue | ForEach-Object { [pscustomobject]@{ Id = [string]$_.PNPDeviceID; Name = ('{0} ({1:N0} GB)' -f $_.Model, ($_.Size / 1GB)) } }) }
function Start-UsbTest {
    $ctl = @(Get-CimInstance Win32_USBController -ErrorAction SilentlyContinue | ForEach-Object { $_.Name })
    $script:UsbSeen = @{}; foreach ($d in (Get-UsbDisks)) { $script:UsbSeen[$d.Id] = $true }
    $script:UsbCount = 0
    Add-ChkLog ('USB-Controller: ' + ($ctl -join '; '))
    Set-ChkResult 'Usb' 'run' 'Stick jetzt nacheinander in jeden Anschluss stecken (3 Minuten) ...'
    if ($script:UsbTimer) { $script:UsbTimer.Stop() }
    $script:UsbEnd = (Get-Date).AddMinutes(3)
    $script:UsbTimer = New-Object Windows.Threading.DispatcherTimer; $script:UsbTimer.Interval = [TimeSpan]::FromSeconds(1.5)
    $script:UsbTimer.Add_Tick({
        $now = @(Get-UsbDisks); $ids = @($now | ForEach-Object { $_.Id })
        foreach ($d in $now) { if (-not $script:UsbSeen.ContainsKey($d.Id) -or -not $script:UsbSeen[$d.Id]) { $script:UsbCount++; Add-ChkLog ('USB: erkannt ({0}. Anschluss): {1}' -f $script:UsbCount, $d.Name); $script:UsbSeen[$d.Id] = $true } }
        foreach ($k in @($script:UsbSeen.Keys)) { if ($ids -notcontains $k -and $script:UsbSeen[$k]) { $script:UsbSeen[$k] = $false; Add-ChkLog 'USB: abgezogen - jetzt den nächsten Anschluss' } }
        if ((Get-Date) -gt $script:UsbEnd) {
            $script:UsbTimer.Stop()
            $ok = Confirm-Ui ('{0} Mal wurde ein Stick erkannt. Haben alle Anschlüsse funktioniert?' -f $script:UsbCount)
            Set-ChkResult 'Usb' $(if ($ok) { 'ok' } else { 'bad' }) ('{0} Anschluss-Tests erkannt' -f $script:UsbCount)
        }
    })
    $script:UsbTimer.Start()
}
$ChkBgTests = @{
