        $ad = @(Get-NetAdapter -Physical -ErrorAction SilentlyContinue | Where-Object { $_.InterfaceDescription -match 'Wi-?Fi|Wireless|WLAN|802\.11' })
        if ($ad.Count) { $o += ('WLAN: {0} ({1})' -f $ad[0].InterfaceDescription, $ad[0].Status); if ($wl -match '(?m)^\s*(Signal)\s*:\s*(\d+)%') { $o += ('Signal {0} %' -f $Matches[2]) }; $nets = @((& netsh.exe wlan show networks 2>$null) | Where-Object { $_ -match '^SSID \d+' }).Count; $o += ('{0} Netze in Reichweite' -f $nets); if ($nets -eq 0 -and $ad[0].Status -ne 'Disabled') { $st = 'warn' } }
        else { $o += 'kein WLAN-Adapter'; $st = 'warn' }
        $bt = @(Get-PnpDevice -Class Bluetooth -ErrorAction SilentlyContinue | Where-Object { $_.FriendlyName -match 'Bluetooth|Wireless' -and $_.FriendlyName -notmatch 'Enumerator|RFCOMM|LE Generic|Device \(' })
        if ($bt.Count) { $ok = @($bt | Where-Object Status -eq 'OK').Count; $o += ('Bluetooth: {0}{1}' -f ($bt[0].FriendlyName), $(if ($ok) { ', in Ordnung' } else { ', Problem: ' + $bt[0].Status })); if (-not $ok) { $st = 'bad' } } else { $o += 'kein Bluetooth'; if ($st -eq 'ok') { $st = 'warn' } }
        [pscustomobject]@{ State = $st; Detail = ($o -join ' · ') }
    }
    Battery = {
        param($d)
        try { $des = @(Get-CimInstance -Namespace root\wmi -ClassName BatteryStaticData -ErrorAction Stop)[0].DesignedCapacity; $full = @(Get-CimInstance -Namespace root\wmi -ClassName BatteryFullChargedCapacity -ErrorAction Stop)[0].FullChargedCapacity } catch { return [pscustomobject]@{ State = 'ok'; Detail = 'kein Akku (Desktop-PC)' } }
        $cyc = ''; try { $cyc = @(Get-CimInstance -Namespace root\wmi -ClassName BatteryCycleCount -ErrorAction Stop)[0].CycleCount } catch { }
        $rep = Join-Path $d 'Akkubericht.html'; $null = & powercfg.exe /batteryreport /output $rep 2>&1
        $p = if ($des) { [math]::Round($full * 100 / $des, 0) } else { 0 }
        [pscustomobject]@{ State = $(if ($p -ge 85) { 'ok' } elseif ($p -ge 70) { 'warn' } else { 'bad' }); Detail = ('{0} % der Neukapazität ({1:N0} von {2:N0} mWh){3}. Bericht: {4}' -f $p, $full, $des, $(if ($cyc) { ', ' + $cyc + ' Ladezyklen' } else { '' }), $rep) }
    }
    Disk = {
        $o = @(); $st = 'ok'
        foreach ($pd in @(Get-PhysicalDisk -ErrorAction SilentlyContinue)) {
            $rc = $null; try { $rc = $pd | Get-StorageReliabilityCounter -ErrorAction Stop } catch { }
            $h = [string]$pd.HealthStatus; if ($h -ne 'Healthy') { $st = 'bad' }
            $x = '{0} ({1:N0} GB, {2}): {3}' -f $pd.FriendlyName, ($pd.Size / 1GB), $pd.MediaType, $(if ($h -eq 'Healthy') { 'gesund' } else { $h })
            if ($rc) { if ($null -ne $rc.Wear) { $x += (', Verschleiß {0} %' -f $rc.Wear); if ($rc.Wear -gt 10) { $st = 'warn' } }; if ($rc.PowerOnHours) { $x += (', {0} Betriebsstunden' -f $rc.PowerOnHours); if ($rc.PowerOnHours -gt 300) { $x += ' (für ein Neugerät viel!)'; if ($st -eq 'ok') { $st = 'warn' } } }; if ($rc.Temperature) { $x += (', {0} °C' -f $rc.Temperature) }; if ($rc.ReadErrorsUncorrected) { $x += (', {0} Lesefehler' -f $rc.ReadErrorsUncorrected); $st = 'bad' } }
            $o += $x
        }
        $f = Join-Path $env:SystemDrive ('pcpflege-tempo-{0}.tmp' -f $PID); $buf = New-Object byte[] (4MB); (New-Object Random).NextBytes($buf)
        try {
            $fs = New-Object IO.FileStream($f, 'Create', 'Write', 'None', 4MB, [IO.FileOptions]::WriteThrough)
            $sw = [Diagnostics.Stopwatch]::StartNew(); for ($i = 0; $i -lt 256; $i++) { $fs.Write($buf, 0, $buf.Length) }; $fs.Flush($true); $fs.Close(); $sw.Stop()
            $wr = [math]::Round(1024 / $sw.Elapsed.TotalSeconds, 0)
            $cached = ''
            try { $fs = New-Object IO.FileStream($f, 'Open', 'Read', 'None', 4MB, [IO.FileOptions]([int]0x20000000)); $sw = [Diagnostics.Stopwatch]::StartNew(); while ($fs.Read($buf, 0, $buf.Length) -gt 0) { }; $fs.Close(); $sw.Stop() }
            catch { try { $fs.Close() } catch { }; $cached = ' (mit Zwischenspeicher gemessen)'; $fs = New-Object IO.FileStream($f, 'Open', 'Read', 'None', 4MB, [IO.FileOptions]::SequentialScan); $sw = [Diagnostics.Stopwatch]::StartNew(); while ($fs.Read($buf, 0, $buf.Length) -gt 0) { }; $fs.Close(); $sw.Stop() }
            $rd = [math]::Round(1024 / $sw.Elapsed.TotalSeconds, 0)
            $o += ('Tempo {0}: lesen {1} MB/s{4}, schreiben {2} MB/s{3}' -f $env:SystemDrive, $rd, $wr, $(if ($rd -lt 300) { ' (langsam - eher Festplatte/eMMC)' } elseif ($rd -gt 1500) { ' (schnelle NVMe-SSD)' } else { '' }), $cached)
        } catch { $o += ('Tempo-Messung nicht möglich: ' + $_.Exception.Message) } finally { Remove-Item $f -Force -ErrorAction SilentlyContinue }
        [pscustomobject]@{ State = $st; Detail = ($o -join ' · ') }
    }
    Stress = {
        $cpu = @(Get-CimInstance Win32_Processor)[0]; $n = [int]$cpu.NumberOfLogicalProcessors; $max = [int]$cpu.MaxClockSpeed
        $pool = @(); for ($i = 0; $i -lt $n; $i++) { $ps = [powershell]::Create(); [void]$ps.AddScript('$e = (Get-Date).AddSeconds(60); $x = 0.0; while ((Get-Date) -lt $e) { for ($j = 0; $j -lt 200000; $j++) { $x += [math]::Sqrt($j) } }'); $pool += [pscustomobject]@{ P = $ps; H = $ps.BeginInvoke() } }
        $mhz = @(); $temps = @(); $end = (Get-Date).AddSeconds(58)
        while ((Get-Date) -lt $end) {
            Start-Sleep -Seconds 3
            try { $pf = (Get-Counter '\Processor Information(_Total)\% Processor Performance' -ErrorAction Stop).CounterSamples[0].CookedValue; $mhz += [math]::Round($max * $pf / 100, 0) } catch { }
            try { foreach ($z in @(Get-CimInstance -Namespace root\wmi -ClassName MSAcpi_ThermalZoneTemperature -ErrorAction Stop)) { $temps += [math]::Round($z.CurrentTemperature / 10 - 273.15, 0) } } catch { }
        }
        foreach ($p in $pool) { try { $p.P.Stop(); $p.P.Dispose() } catch { } }
        $st = 'ok'; $o = @('{0}, {1} Threads' -f $cpu.Name.Trim(), $n)
        if ($mhz.Count) { $avg = [math]::Round(($mhz | Measure-Object -Average).Average, 0); $o += ('Takt unter Last: Ø {0} MHz (min {1}, max {2}, Nenntakt {3})' -f $avg, ($mhz | Measure-Object -Minimum).Minimum, ($mhz | Measure-Object -Maximum).Maximum, $max); if ($avg -lt $max * 0.6) { $st = 'warn'; $o += 'deutliche Drosselung - Kühlung/Energieplan prüfen' } }
        if ($temps.Count) { $tm = ($temps | Measure-Object -Maximum).Maximum; $o += ('höchste Temperatur {0} °C' -f $tm); if ($tm -ge 95) { $st = 'bad' } elseif ($tm -ge 88 -and $st -eq 'ok') { $st = 'warn' } } else { $o += 'Temperatur von Windows nicht auslesbar (normal bei vielen Geräten)' }
        [pscustomobject]@{ State = $st; Detail = ($o -join ' · ') }
    }
    Devices = {
        $bad = @(Get-CimInstance Win32_PnPEntity -ErrorAction SilentlyContinue | Where-Object { $_.ConfigManagerErrorCode -and $_.ConfigManagerErrorCode -ne 22 -and -not ($_.ConfigManagerErrorCode -eq 24 -and ([string]$_.DeviceID -match '^ACPI\\(PNP03|PNP0F|HPQ8001|MSF0001)' -or [string]$_.Name -match 'PS/2')) -and (@((Get-ItemProperty 'HKLM:\SOFTWARE\PCPflege' -Name DevIgnore -ErrorAction SilentlyContinue).DevIgnore) -notcontains [string]$_.DeviceID) })
        if (-not $bad.Count) { [pscustomobject]@{ State = 'ok'; Detail = 'alle Geräte laufen fehlerfrei' } } else { [pscustomobject]@{ State = 'warn'; Detail = ('{0} Gerät(e) mit Problem: {1} - Seite Treiber' -f $bad.Count, (($bad | Select-Object -First 4 | ForEach-Object { '{0} (Code {1})' -f $(if ($_.Name) { $_.Name } else { $_.PNPDeviceID }), $_.ConfigManagerErrorCode }) -join ', ')) } }
    }
    License = {
        $p = @(Get-CimInstance SoftwareLicensingProduct -Filter "ApplicationID='55c92734-d682-4d71-983e-d6ec3f16059f' AND PartialProductKey IS NOT NULL" -ErrorAction SilentlyContinue) | Select-Object -First 1
        $oem = [string](Get-CimInstance SoftwareLicensingService).OA3xOriginalProductKeyDescription
        [pscustomobject]@{ State = $(if ($p.LicenseStatus -eq 1) { 'ok' } else { 'bad' }); Detail = ('{0}{1}{2}' -f $(if ($p.LicenseStatus -eq 1) { 'aktiviert' } else { 'NICHT aktiviert' }), $(if ($p.Description) { ', ' + ($p.Description -replace '^.*?(OEM|RETAIL|VOLUME\S*).*$', '$1') } else { '' }), $(if ($oem) { ', Schlüssel im BIOS: ' + $oem } else { '' })) }
    }
}
function Start-ChkTest([string]$K) {
    switch ($K) {
        'Display'  { Show-DisplayTest }
        'Keyboard' { Show-KeyboardTest }
        'Camera'   { try { Start-Process 'microsoft.windows.camera:'; Set-ChkResult 'Camera' 'run' 'Kamera-App geöffnet - danach OK oder Fehler klicken' } catch { Set-ChkResult 'Camera' 'bad' 'Kamera-App nicht startbar' }
                     $cams = @(Get-PnpDevice -Class Camera, Image -ErrorAction SilentlyContinue | Where-Object Status -eq 'OK'); Add-ChkLog ('Kameras: ' + $(if ($cams.Count) { ($cams | ForEach-Object { $_.FriendlyName }) -join ', ' } else { 'keine gefunden (Kamera-Schalter/Schieber am Gerät?)' })) }
        'Mic'      { Start-MicTest }
        'Speaker'  { Start-SpeakerTest }
        'Usb'      { Start-UsbTest }
        'Ram'      {
            $m = @(Get-CimInstance Win32_PhysicalMemory -ErrorAction SilentlyContinue | ForEach-Object { '{0:N0} GB {1} MHz {2} {3}' -f ($_.Capacity / 1GB), $_.ConfiguredClockSpeed, ([string]$_.Manufacturer).Trim(), ([string]$_.PartNumber).Trim() })
            $slots = @(Get-CimInstance Win32_PhysicalMemoryArray -ErrorAction SilentlyContinue | ForEach-Object { $_.MemoryDevices } | Measure-Object -Sum).Sum
            $d = '{0} Riegel{1}: {2}' -f $m.Count, $(if ($slots) { " in $slots Steckplätzen" } else { '' }), ($m -join ' | ')
            if (Confirm-Ui ("$d`n`nJetzt die Windows-Speicherdiagnose planen? Sie läuft beim nächsten Neustart (ca. 10-20 Minuten), das Ergebnis zeigt Windows nach der Anmeldung.")) { Start-Process mdsched.exe }
            Set-ChkResult 'Ram' 'warn' ($d + ' - Ergebnis der Speicherdiagnose danach mit OK/Fehler bestätigen')
        }
        default {
            if (-not $ChkBgTests.ContainsKey($K)) { return }
            Set-ChkResult $K 'run' $(if ($K -eq 'Stress') { '60 Sekunden volle Last - der Lüfter wird laut, das ist normal' } elseif ($K -eq 'Disk') { 'schreibt und liest 1 GB ...' } else { '' })
            $script:ChkRunK = $K
            Invoke-Bg -Script $ChkBgTests[$K] -Arguments @($DataDir) -Done {
                param($r, $err)
                $k = $script:ChkRunK
                if ($err) { Set-ChkResult $k 'bad' $err.Message; return }
                $x = @($r | Where-Object { $_ -and $_.State })[-1]
                if ($x) { Set-ChkResult $k $x.State $x.Detail } else { Set-ChkResult $k 'warn' 'kein Ergebnis' }
            }
        }
    }
}
function Export-ChkReport {
    Add-Type -AssemblyName System.Windows.Forms
    $d = New-Object System.Windows.Forms.SaveFileDialog; $d.Filter = 'PDF (*.pdf)|*.pdf'; $d.FileName = ('Neugeraet-Check_{0}_{1:yyyy-MM-dd}.pdf' -f $env:COMPUTERNAME, (Get-Date))
    if ($d.ShowDialog() -ne 'OK') { return }
    $cs = Get-CimInstance Win32_ComputerSystem; $b = Get-CimInstance Win32_BIOS; $os = Get-CimInstance Win32_OperatingSystem
    $E = { param($s) ConvertTo-HtmlText $s }
    $H = [System.Collections.Generic.List[string]]::new()
    $H.Add('<!DOCTYPE html><html lang="de"><head><meta charset="utf-8"><style>' + $ReportCss + '</style></head><body>')
    $H.Add(('<div class="hero"><h1>Prüfbericht Neugerät</h1><small>{0} {1} &middot; Seriennummer {2} &middot; {3} &middot; geprüft am {4:dd.MM.yyyy}</small></div>' -f (& $E $cs.Manufacturer), (& $E $cs.Model), (& $E $b.SerialNumber), (& $E $os.Caption), (Get-Date)))
    $H.Add('<h2>Ergebnisse</h2><table><tr><th>Test</th><th>Ergebnis</th><th>Details</th><th>Zeit</th></tr>')
    foreach ($t in $ChkTests) { $r = $script:ChkRes[$t.K]; $st = if ($r) { $r.State } else { 'open' }
        $H.Add(('<tr><td><b>{0}</b></td><td class="{1}">{2}</td><td>{3}</td><td>{4}</td></tr>' -f (& $E $t.T), @{ ok = 'ok'; bad = 'bad'; warn = 'warn'; open = 'muted'; run = 'muted' }[$st], @{ ok = 'in Ordnung'; bad = 'FEHLER'; warn = 'Hinweis'; open = 'nicht geprüft'; run = 'nicht abgeschlossen' }[$st], (& $E $(if ($r) { $r.Detail } else { '' })), (& $E $(if ($r) { $r.Time } else { '' })))) }
    $H.Add('</table><p class="muted">Erstellt mit PC-Tools ' + $AppVersion + '. Bei Fehlern innerhalb der Rückgabe- bzw. Gewährleistungsfrist beim Händler melden und diesen Bericht beilegen.</p></body></html>')
    $window.Cursor = 'Wait'
    try { $f = Convert-HtmlToPdf ($H -join "`n") $d.FileName; $ui.StatusText.Text = 'Prüfbericht gespeichert: ' + $f; Start-Process -FilePath $f } catch { Show-UiError $_.Exception.Message } finally { $window.Cursor = $null }
}
$ui.BtnChkReport.Add_Click({ Export-ChkReport })
$ui.BtnChkAuto.Add_Click({ $script:ChkQueue.Clear(); foreach ($k in 'Battery', 'Devices', 'License', 'Disk', 'Stress') { $script:ChkQueue.Add($k) }; Start-ChkTest 'Net' })
$ui.BtnChkReset.Add_Click({ if (Confirm-Ui 'Alle Testergebnisse löschen und neu beginnen?') { $script:ChkRes = @{}; Remove-Item $ChkFile -Force -ErrorAction SilentlyContinue; $ui.ChkLog.Clear(); foreach ($t in $ChkTests) { Update-ChkTile $t.K } } })
$ui.BtnChkWarranty.Add_Click({ $ui.Tabs.SelectedItem = $ui.TabBios })
$ui.Tabs.Add_SelectionChanged({ param($s, $e) if ($e.OriginalSource -eq $s -and $s.SelectedItem -eq $ui.TabCheck -and -not $ui.ChkTiles.Children.Count) { Build-ChkTiles } })

# ---------------------------------------------------------------- Einstellungen übertragen (Oberfläche)
function Build-WsItems {
    if ($ui.WsItems.Children.Count) { return }
    foreach ($k in $WinSettingsDefs.Keys) { $c = New-Object Windows.Controls.CheckBox; $c.Content = $WinSettingsDefs[$k]; $c.Tag = $k; $c.Width = 420; $c.Margin = '0,0,0,6'; $c.IsChecked = ($k -notin 'Hosts', 'Umgebung'); [void]$ui.WsItems.Children.Add($c) }
    if (-not $ui.WsExpDir.Text) { $ui.WsExpDir.Text = Join-Path ([Environment]::GetFolderPath('Desktop')) ('Windows-Einstellungen_' + $env:COMPUTERNAME) }
}
function Get-WsSelected { @($ui.WsItems.Children | Where-Object { $_.IsChecked } | ForEach-Object { [string]$_.Tag }) }
function Read-WsImport {
    $d = $ui.WsImpDir.Text.Trim(); $m = Join-Path $d 'Einstellungen.json'
    if (-not (Test-Path -LiteralPath $m)) { $ui.WsImpInfo.Text = 'In diesem Ordner liegt keine Sicherung von PC-Tools (Einstellungen.json fehlt).'; return }
    try { $j = Get-Content -LiteralPath $m -Raw -Encoding UTF8 | ConvertFrom-Json } catch { $ui.WsImpInfo.Text = 'Sicherung nicht lesbar.'; return }
    $ui.WsImpInfo.Text = 'Gesichert auf {0} (Konto {1}) am {2:dd.MM.yyyy HH:mm}: {3}' -f $j.Computer, $j.User, [datetime]$j.Date, ((@($j.Items) | ForEach-Object { $_ }) -join ', ')
    foreach ($c in $ui.WsItems.Children) { $c.IsChecked = (@($j.Items) -contains [string]$c.Tag) }
}
$ui.BtnWsAll.Add_Click({ foreach ($c in $ui.WsItems.Children) { $c.IsChecked = $true } })
$ui.BtnWsNone.Add_Click({ foreach ($c in $ui.WsItems.Children) { $c.IsChecked = $false } })
$ui.BtnWsExpDir.Add_Click({ Select-FolderInto $ui.WsExpDir })
$ui.BtnWsImpDir.Add_Click({ Select-FolderInto $ui.WsImpDir; if ($ui.WsImpDir.Text) { Read-WsImport } })
$ui.WsImpDir.Add_LostFocus({ if ($ui.WsImpDir.Text) { Read-WsImport } })
$ui.BtnWsExport.Add_Click({
    $d = $ui.WsExpDir.Text.Trim(); $it = Get-WsSelected
    if (-not $d -or -not $it.Count) { Show-UiError 'Bitte Zielordner und mindestens einen Bereich wählen.'; return }
    $ui.WsLog.Text = 'Sichere ...'; $ui.BtnWsExport.IsEnabled = $false
    Invoke-Bg -Script { param($d, $it) Export-WinSettings $d $it } -Arguments @($d, $it) -Functions @('Export-WinSettings') -Done {
        param($r, $err)
        $ui.BtnWsExport.IsEnabled = $true
        if ($err) { $ui.WsLog.Text = 'Fehler: ' + $err.Message; return }
        $ui.WsLog.Text = ((@($r | ForEach-Object { $_ }) -join "`r`n") + "`r`n`r`nFertig. Ordner auf den neuen PC mitnehmen: " + $ui.WsExpDir.Text)
        Start-Process explorer.exe ('"{0}"' -f $ui.WsExpDir.Text.Trim())
    }
})
$ui.BtnWsImport.Add_Click({
    $d = $ui.WsImpDir.Text.Trim(); $it = Get-WsSelected
    if (-not (Test-Path -LiteralPath (Join-Path $d 'Einstellungen.json'))) { Show-UiError 'Bitte den Ordner mit der Sicherung wählen.'; return }
    if (-not (Confirm-Ui ("Diese Einstellungen übernehmen?`n`n{0}`n`nDer Explorer startet danach kurz neu." -f (($it | ForEach-Object { '  - ' + $WinSettingsDefs[$_] }) -join "`n")))) { return }
    $ui.WsLog.Text = 'Übernehme ...'; $ui.BtnWsImport.IsEnabled = $false
    Invoke-Bg -Script { param($d, $it) Import-WinSettings $d $it } -Arguments @($d, $it) -Functions @('Import-WinSettings', 'Set-PReg', 'Add-NetDrive') -Done {
        param($r, $err)
        $ui.BtnWsImport.IsEnabled = $true
        if ($err) { $ui.WsLog.Text = 'Fehler: ' + $err.Message; return }
        $ui.WsLog.Text = (@($r | ForEach-Object { $_ }) -join "`r`n")
        try { Stop-Process -Name explorer -Force -ErrorAction SilentlyContinue } catch { }
        if ((Get-WsSelected) -contains 'StandardApps') { Start-Process 'ms-settings:defaultapps'; $lst = Join-Path $ui.WsImpDir.Text.Trim() 'Standard-Apps-Liste.txt'; if (Test-Path $lst) { Start-Process notepad.exe ('"{0}"' -f $lst) } }
    }
})
$ui.Tabs.Add_SelectionChanged({ param($s, $e) if ($e.OriginalSource -eq $s -and $s.SelectedItem -eq $ui.TabWinSet) { Build-WsItems } })

# ---------------------------------------------------------------- Konten und Netzwerk (Oberfläche)
function Get-AdminNames {
    $g = (New-Object Security.Principal.SecurityIdentifier('S-1-5-32-544')).Translate([Security.Principal.NTAccount]).Value.Split('\')[-1]
    $out = & net.exe localgroup $g 2>$null; $on = $false; $names = @()
    foreach ($l in $out) { if ($l -match '^-{5,}') { $on = $true; continue }; if ($on -and $l.Trim() -and $l -notmatch '(erfolgreich|successfully)') { $names += ($l.Trim() -split '\\')[-1] } }
    return $names
}
function Update-Accounts {
    $adm = @(Get-AdminNames)
    $rows = @(Get-LocalUser -ErrorAction SilentlyContinue | Sort-Object { -not $_.Enabled }, Name | ForEach-Object {
        [pscustomobject]@{ Name = $_.Name; Full = $_.FullName; Kind = $(if ($adm -contains $_.Name) { 'Administrator' } else { 'Standardbenutzer' }) + $(if ($_.Name -eq $env:USERNAME) { ' (du)' } else { '' }); Enabled = $(if ($_.Enabled) { 'ja' } else { 'nein' })
            PwdInfo = $(if (-not $_.PasswordRequired -and -not $_.PasswordLastSet) { 'ohne Kennwort' } elseif ($_.PasswordExpires) { 'läuft ab ' + $_.PasswordExpires.ToString('dd.MM.yyyy') } else { 'läuft nie ab' }); Last = $(if ($_.LastLogon) { $_.LastLogon.ToString('dd.MM.yyyy HH:mm') } else { 'nie' }); IsAdmin = ($adm -contains $_.Name); User = $_ } })
    Set-GridItems $ui.AccGrid $rows
    try { $v = Get-BitLockerVolume -MountPoint $env:SystemDrive -ErrorAction Stop; $ui.AccBlState.Text = 'BitLocker {0}: {1}, {2} % verschlüsselt, Schlüssel: {3}' -f $env:SystemDrive, $(if ([string]$v.ProtectionStatus -eq 'On') { 'AN' } else { 'aus' }), $v.EncryptionPercentage, $(if (@($v.KeyProtector | Where-Object KeyProtectorType -eq 'RecoveryPassword').Count) { 'Wiederherstellungsschlüssel vorhanden' } else { 'kein Wiederherstellungsschlüssel' }) } catch { $ui.AccBlState.Text = 'BitLocker ist in dieser Windows-Edition nicht verfügbar (Home: nur "Geräteverschlüsselung" in den Einstellungen).' }
}
function Update-NetDrives {
    $map = @{}; foreach ($m in @(Get-SmbMapping -ErrorAction SilentlyContinue)) { $map[$m.LocalPath.TrimEnd(':').ToUpper()] = [string]$m.Status }
    $rows = @(Get-ChildItem 'HKCU:\Network' -ErrorAction SilentlyContinue | ForEach-Object { $p = Get-ItemProperty $_.PSPath; $l = $_.PSChildName.ToUpper(); [pscustomobject]@{ Letter = $l + ':'; Path = [string]$p.RemotePath; User = [string]$p.UserName; State = $(if ($map.ContainsKey($l)) { $(if ($map[$l] -eq 'OK') { 'verbunden' } else { $map[$l] }) } elseif (Test-Path ($l + ':\')) { 'verbunden' } else { 'gespeichert' }) } })
    Set-GridItems $ui.NdGrid $rows
    $used = @([IO.DriveInfo]::GetDrives() | ForEach-Object { $_.Name.Substring(0, 1) }) + @($rows | ForEach-Object { $_.Letter.Substring(0, 1) })
    $ui.NdLetter.Items.Clear(); foreach ($c in [char[]]'ZYXWVUTSRQPONMLKJIHGFED') { if ($used -notcontains [string]$c) { [void]$ui.NdLetter.Items.Add([string]$c + ':') } }
    if ($ui.NdLetter.Items.Count) { $ui.NdLetter.SelectedIndex = 0 }
}
function Get-AccSel { $r = $ui.AccGrid.SelectedItem; if (-not $r) { Show-UiError 'Bitte ein Konto auswählen.' }; return $r }
$ui.BtnAccRefresh.Add_Click({ Update-Accounts })
$ui.BtnAccAdd.Add_Click({
    $n = $ui.AccName.Text.Trim(); if ($n -notmatch '^[\w\.\- ]{1,20}$') { Show-UiError 'Benutzername: 1-20 Zeichen, keine Sonderzeichen wie \ / " [ ] : ; | = , + * ? < >'; return }
    try {
        $pw = $ui.AccPwdBox.Password
        if ($pw) { $null = New-LocalUser -Name $n -Password (ConvertTo-SecureString $pw -AsPlainText -Force) -FullName $ui.AccFull.Text.Trim() -PasswordNeverExpires -AccountNeverExpires -ErrorAction Stop } else { $null = New-LocalUser -Name $n -NoPassword -FullName $ui.AccFull.Text.Trim() -AccountNeverExpires -ErrorAction Stop }
        Add-LocalGroupMember -SID $(if ($ui.AccIsAdmin.IsChecked) { 'S-1-5-32-544' } else { 'S-1-5-32-545' }) -Member $n -ErrorAction Stop
        $ui.AccName.Text = ''; $ui.AccFull.Text = ''; $ui.AccPwdBox.Password = ''; $ui.StatusText.Text = 'Konto ' + $n + ' angelegt - das Profil entsteht bei der ersten Anmeldung.'
    } catch { Show-UiError $_.Exception.Message }
    Update-Accounts
})
$ui.BtnAccToggle.Add_Click({ $r = Get-AccSel; if (-not $r) { return }; if ($r.Name -eq $env:USERNAME) { Show-UiError 'Das eigene Konto lässt sich hier nicht deaktivieren.'; return }; try { if ($r.Enabled -eq 'ja') { Disable-LocalUser -Name $r.Name -ErrorAction Stop } else { Enable-LocalUser -Name $r.Name -ErrorAction Stop } } catch { Show-UiError $_.Exception.Message }; Update-Accounts })
$ui.BtnAccAdmin.Add_Click({
    $r = Get-AccSel; if (-not $r) { return }
    if ($r.IsAdmin -and $r.Name -eq $env:USERNAME) { Show-UiError 'Dem eigenen Konto die Administratorrechte zu nehmen, geht hier nicht (sonst sperrst du dich aus).'; return }
    try { if ($r.IsAdmin) { Remove-LocalGroupMember -SID 'S-1-5-32-544' -Member $r.Name -ErrorAction Stop; Add-LocalGroupMember -SID 'S-1-5-32-545' -Member $r.Name -ErrorAction SilentlyContinue } else { Add-LocalGroupMember -SID 'S-1-5-32-544' -Member $r.Name -ErrorAction Stop } } catch { Show-UiError $_.Exception.Message }
    Update-Accounts
})
$ui.BtnAccPwd.Add_Click({
    $r = Get-AccSel; if (-not $r) { return }
    $d = Show-InputDialog 'Kennwort setzen' ('Neues Kennwort für {0}. Bei Microsoft-Konten bitte online ändern (account.microsoft.com).' -f $r.Name) @(@{ Key = 'A'; Label = 'Neues Kennwort'; Type = 'Password' }, @{ Key = 'B'; Label = 'Wiederholen'; Type = 'Password' })
    if (-not $d) { return }; if ($d.A -ne $d.B) { Show-UiError 'Die Kennwörter stimmen nicht überein.'; return }
    try { Set-LocalUser -Name $r.Name -Password (ConvertTo-SecureString $d.A -AsPlainText -Force) -ErrorAction Stop; $ui.StatusText.Text = 'Kennwort von ' + $r.Name + ' geändert.' } catch { Show-UiError $_.Exception.Message }
})
$ui.BtnAccDel.Add_Click({
    $r = Get-AccSel; if (-not $r) { return }; if ($r.Name -eq $env:USERNAME) { Show-UiError 'Das eigene Konto kann nicht gelöscht werden.'; return }
    if (-not (Confirm-Ui ("Konto {0} löschen?`nDer Profilordner (C:\Users\{0}) bleibt erhalten und kann danach von Hand gelöscht werden." -f $r.Name) 'Warning')) { return }
    try { Remove-LocalUser -Name $r.Name -ErrorAction Stop } catch { Show-UiError $_.Exception.Message }; Update-Accounts
})
$ui.BtnAccHello.Add_Click({ Start-Process 'ms-settings:signinoptions' })
$ui.BtnAccNetplwiz.Add_Click({ Start-Tool 'netplwiz.exe' })
$ui.BtnNdRefresh.Add_Click({ Update-NetDrives })
$ui.BtnNdAdd.Add_Click({
    $l = [string]$ui.NdLetter.SelectedItem; $p = $ui.NdPath.Text.Trim()
    if (-not $l -or $p -notmatch '^\\\\[^\\]+\\[^\\]+') { Show-UiError 'Bitte Laufwerksbuchstabe und Pfad (\\Server\Freigabe) angeben.'; return }
    $window.Cursor = 'Wait'
    try { $o = Add-NetDrive $l $p $ui.NdUser.Text.Trim() $ui.NdPwd.Password; $ui.StatusText.Text = 'Netzlaufwerk ' + $l + ': ' + $o; $ui.NdPath.Text = ''; $ui.NdPwd.Password = '' } catch { Show-UiError $_.Exception.Message } finally { $window.Cursor = $null }
    Update-NetDrives
})
$ui.BtnNdOpen.Add_Click({ $r = $ui.NdGrid.SelectedItem; if ($r) { Start-Process explorer.exe $(if (Test-Path ($r.Letter + '\')) { $r.Letter + '\' } else { $r.Path }) } })
$ui.BtnNdDel.Add_Click({ $r = $ui.NdGrid.SelectedItem; if (-not $r) { return }; if (Confirm-Ui ('Netzlaufwerk {0} ({1}) trennen?' -f $r.Letter, $r.Path)) { $null = & net.exe use $r.Letter /delete /y 2>&1; Remove-Item ('HKCU:\Network\' + $r.Letter.TrimEnd(':')) -Recurse -Force -ErrorAction SilentlyContinue; Update-NetDrives } })
$ui.BtnNdLinked.Add_Click({ try { Set-PReg 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\System' 'EnableLinkedConnections' 1; [Windows.MessageBox]::Show((T ('Eingeschaltet. Nach dem nächsten Neustart sehen auch Programme mit Administratorrechten (z.B. Installer) die Netzlaufwerke.')), (T ('PC-Tools')), 'OK', 'Information') | Out-Null } catch { Show-UiError $_.Exception.Message } })
$ui.BtnAccKeyDir.Add_Click({ Select-FolderInto $ui.AccKeyDir })
$ui.BtnAccBlOn.Add_Click({ if (Confirm-Ui ("BitLocker für {0} einschalten?`n`nDer Wiederherstellungsschlüssel wird unter {1}\BitLocker-Schluessel{2} gespeichert (mit Hinweis-Datei zum Sichern). Die Verschlüsselung läuft im Hintergrund (PC bleibt nutzbar).`n`nWICHTIG: Den Schlüssel danach zusätzlich außerhalb des PCs sichern." -f $env:SystemDrive, $DataDir, $(if ($ui.AccKeyDir.Text.Trim()) { ' und in ' + $ui.AccKeyDir.Text.Trim() } else { '' }))) { Start-Run -Parts @('BitLockerSetup') -Job @{ KeyDir = $ui.AccKeyDir.Text.Trim() } } })
$ui.BtnAccBlVault.Add_Click({
    try { $v = Get-BitLockerVolume -ErrorAction Stop } catch { Show-UiError 'BitLocker ist nicht verfügbar.'; return }
    $n = 0; foreach ($x in @($v)) { foreach ($k in @($x.KeyProtector | Where-Object KeyProtectorType -eq 'RecoveryPassword')) { try { $script:LicVault = @(Read-LicVault) } catch { }; Add-LicVaultItem ('BitLocker {0} {1}' -f $env:COMPUTERNAME, $x.MountPoint) $k.RecoveryPassword ('Kennung ' + $k.KeyProtectorId); $n++ } }
    if (-not $n) { Show-UiError 'Keine BitLocker-Wiederherstellungsschlüssel gefunden.' } else { $ui.StatusText.Text = '{0} Schlüssel im Lizenz-Tresor (Seite Lizenzen) - verschlüsselt gespeichert.' -f $n }
})
$ui.BtnAccBlPage.Add_Click({ $ui.Tabs.SelectedItem = $ui.TabSecurity })
$ui.Tabs.Add_SelectionChanged({ param($s, $e) if ($e.OriginalSource -eq $s -and $s.SelectedItem -eq $ui.TabAccounts) { try { Update-Accounts } catch { }; try { Update-NetDrives } catch { } } })
$ui.BtnAccPrinters.Add_Click({ $ui.Tabs.SelectedItem = $ui.TabPrinter })

# ---------------------------------------------------------------- Update-Steuerung (Oberfläche)
function Update-UcPage {
    if (-not $ui.UcActS.Items.Count) { for ($h = 0; $h -lt 24; $h++) { [void]$ui.UcActS.Items.Add([string]$h); [void]$ui.UcActE.Items.Add([string]$h) } }
    try { $c = Get-UpdateControl } catch { $ui.UcRules.Text = $_.Exception.Message; return }
    $ui.UcBuild.Text = $c.Build; $ui.UcInsider.Text = $(if ($c.Insider) { $c.Insider } else { 'nicht angemeldet' })
    $ui.UcPause.Text = $(if ($c.PausedUntil) { 'pausiert bis ' + $c.PausedUntil } else { 'keine Pause' })
    $r = @(); if ($c.Pin) { $r += 'bleibt auf ' + $c.PinVer }; if ($c.DeferFeature) { $r += ('Funktionsupdates +{0} Tage' -f $c.DeferFeature) }; if ($c.DeferQuality) { $r += ('Sicherheitsupdates +{0} Tage' -f $c.DeferQuality) }; if ($c.NoDrivers) { $r += 'keine Treiber' }; if ($c.NoAutoReboot) { $r += 'kein Zwangs-Neustart' }
    $ui.UcRules.Text = $(if ($r.Count) { $r -join '  ·  ' } else { 'Windows-Standard' })
    $ui.UcPin.IsChecked = $c.Pin; $ui.UcPinVer.Text = $(if ($c.PinVer) { $c.PinVer } else { ((Get-ItemProperty 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion').DisplayVersion) })
    Set-ComboText $ui.UcDeferF ([string]$c.DeferFeature); Set-ComboText $ui.UcDeferQ ([string]$c.DeferQuality); Set-ComboText $ui.UcStore $c.StoreAuto
    $ui.UcActS.SelectedItem = [string]$c.ActiveStart; $ui.UcActE.SelectedItem = [string]$c.ActiveEnd
    $ui.UcNoDrivers.IsChecked = $c.NoDrivers; $ui.UcNoReboot.IsChecked = $c.NoAutoReboot; $ui.UcPreview.IsChecked = $c.Preview
    try { $b = Get-Win11BypassState; $ui.UcHwState.Text = ('Status: Windows 11 ohne TPM/Secure Boot {0} · Hinweise/Wasserzeichen {1}.' -f $(if ($b.Allowed) { 'ERLAUBT' } else { 'nicht erlaubt (Windows-Standard)' }), $(if ($b.NagOff) { 'unterdrückt' } else { 'an (Windows-Standard)' })) } catch { }
}
function Set-ComboText($Cb, [string]$Text) { foreach ($i in $Cb.Items) { $t = if ($i -is [Windows.Controls.ComboBoxItem]) { [string]$i.Content } else { [string]$i }; if ($t -eq $Text) { $Cb.SelectedItem = $i; return } }; if ($Cb.IsEditable) { $Cb.Text = $Text } }
function Get-ComboText($Cb) { $i = $Cb.SelectedItem; if ($i -is [Windows.Controls.ComboBoxItem]) { [string]$i.Content } elseif ($i) { [string]$i } else { [string]$Cb.Text } }
foreach ($d in 7, 14, 35) { $ui[('BtnUcPause{0}' -f $d)].Tag = $d; $ui[('BtnUcPause{0}' -f $d)].Add_Click({ param($s, $e) try { $ui.StatusText.Text = Set-UpdatePause ([int]$s.Tag) } catch { Show-UiError $_.Exception.Message }; Update-UcPage }) }
$ui.BtnUcResume.Add_Click({ try { $ui.StatusText.Text = Set-UpdatePause 0 } catch { Show-UiError $_.Exception.Message }; Update-UcPage })
$ui.BtnUcApply.Add_Click({
    $o = [pscustomobject]@{ Pin = [bool]$ui.UcPin.IsChecked; PinVer = (Get-ComboText $ui.UcPinVer).Trim().ToUpper(); DeferFeature = [int](Get-ComboText $ui.UcDeferF); DeferQuality = [int](Get-ComboText $ui.UcDeferQ); NoDrivers = [bool]$ui.UcNoDrivers.IsChecked; NoAutoReboot = [bool]$ui.UcNoReboot.IsChecked
        ActiveStart = [int]$ui.UcActS.SelectedItem; ActiveEnd = [int]$ui.UcActE.SelectedItem; Preview = [bool]$ui.UcPreview.IsChecked; StoreAuto = (Get-ComboText $ui.UcStore) }
    if ($o.Pin -and $o.PinVer -notmatch '^\d{2}H\d$') { Show-UiError 'Version bitte wie 24H2 angeben.'; return }
    if ($o.DeferQuality -gt 7 -and -not (Confirm-Ui 'Sicherheitsupdates mehr als eine Woche zurückzustellen lässt Lücken länger offen. Trotzdem?' 'Warning')) { return }
    try { $l = Set-UpdateControl $o; $ui.StatusText.Text = 'Update-Regeln übernommen: ' + (@($l) -join ', ') } catch { Show-UiError $_.Exception.Message }
    Update-UcPage
})
$ui.BtnUcDefault.Add_Click({ if (Confirm-Ui 'Alle Update-Regeln entfernen und Windows-Standard herstellen (Pause bleibt)?') { try { $null = Set-UpdateControl ([pscustomobject]@{ Pin = $false; DeferFeature = 0; DeferQuality = 0; NoDrivers = $false; NoAutoReboot = $false; ActiveStart = 8; ActiveEnd = 17; Preview = $false; StoreAuto = 'Standard' }) } catch { Show-UiError $_.Exception.Message }; Update-UcPage } })
