        $ui.UcSearchInfo.Text = '{0} Updates verfügbar, {1} ausgeblendet. Mehrere mit Strg/Umschalt markieren.' -f @($rows | Where-Object { -not $_.Hidden }).Count, @($rows | Where-Object Hidden).Count
