# ---------------------------------------------------------------- Sicherheitslücken (Oberfläche)
function Update-VulnFilter {
    if (-not $script:VulnRows) { return }
    $all = [bool]($ui.VulnFilter.SelectedIndex -eq 1); $q = $ui.VulnSearch.Text.Trim()
    Set-GridFilter $ui.VulnGrid { param($x) ($all -or $x.Level -le 2) -and (-not $q -or $x.Name -match [regex]::Escape($q) -or $x.Publisher -match [regex]::Escape($q)) }.GetNewClosure()
}
function Start-VulnScan {
    $ui.VulnInfo.Text = 'Prüfe installierte Programme und frage winget nach neuen Versionen (ca. 30-60 Sekunden) ...'; $ui.BtnVulnScan.IsEnabled = $false
    Invoke-Bg -Script { param($h) $VulnRules = $h.R; $VulnAlwaysUpdate = $h.A; Get-VulnReport } -Arguments @(@{ R = $VulnRules; A = $VulnAlwaysUpdate }) -Functions @('Get-VulnReport', 'Get-WingetUpgradeTable', 'Get-WingetPathX', 'ConvertTo-LooseVersion') -Done {
        param($r, $err)
        $ui.BtnVulnScan.IsEnabled = $true
        if ($err) { $ui.VulnInfo.Text = 'Prüfung fehlgeschlagen: ' + $err.Message; return }
        $script:VulnRows = @($r | ForEach-Object { $_ } | Where-Object { $_ -and $_.Name } | Sort-Object Level, Name)
        Set-GridItems $ui.VulnGrid $script:VulnRows; Update-VulnFilter
        $c = @(0, 0, 0, 0); foreach ($x in $script:VulnRows) { $c[[int]$x.Level]++ }
        $ui.VulnS0.Text = [string]$c[0]; $ui.VulnS1.Text = [string]$c[1]; $ui.VulnS2.Text = [string]$c[2]; $ui.VulnS3.Text = [string]$c[3]
        $ui.VulnInfo.Text = 'Geprüft am {0:dd.MM.yyyy HH:mm}: {1} Programme. {2}' -f (Get-Date), $script:VulnRows.Count, $(if ($c[0] + $c[1]) { 'Rot und orange zuerst erledigen - "Alle kritischen und Sicherheitsupdates installieren".' } else { 'Keine bekannten Sicherheitsprobleme.' })
        try { [pscustomobject]@{ Time = (Get-Date).ToString('o'); Critical = $c[0]; Security = $c[1]; Updates = $c[2] } | ConvertTo-Json | Set-Content (Join-Path $DataDir 'sicherheitsluecken.json') -Encoding UTF8 } catch { }
    }
}
$ui.BtnVulnScan.Add_Click({ Start-VulnScan })
$ui.VulnFilter.Add_SelectionChanged({ param($s, $e) $e.Handled = $true; Update-VulnFilter })
$ui.VulnSearch.Add_TextChanged({ Update-VulnFilter })
$ui.BtnVulnFixAll.Add_Click({
    $ids = @($script:VulnRows | Where-Object { $_.Level -le 1 -and $_.WingetId } | ForEach-Object { $_.WingetId } | Select-Object -Unique)
    $eol = @($script:VulnRows | Where-Object { $_.Level -le 1 -and -not $_.WingetId })
    if (-not $ids.Count) { Show-UiError $(if ($eol.Count) { 'Die markierten Programme lassen sich nicht automatisch aktualisieren (veraltet, keine Updates mehr) - bitte deinstallieren oder beim Hersteller eine neue Version holen.' } else { 'Nichts zu tun - zuerst "Jetzt prüfen".' }); return }
    if (Confirm-Ui ("{0} Programme aktualisieren?`n`n{1}{2}" -f $ids.Count, (($ids | ForEach-Object { '  - ' + $_ }) -join "`n"), $(if ($eol.Count) { "`n`nNicht automatisch möglich (bitte deinstallieren): " + (($eol | ForEach-Object { $_.Name }) -join ', ') } else { '' }))) { Start-Run -Parts @('WingetInstall') -WingetApps $ids; $script:VulnRows = $null }
})
$ui.BtnVulnUpdate.Add_Click({ $ids = @($ui.VulnGrid.SelectedItems | Where-Object WingetId | ForEach-Object { $_.WingetId } | Select-Object -Unique); if (-not $ids.Count) { Show-UiError 'Für die Auswahl gibt es kein automatisches Update (winget kennt das Programm nicht).'; return }; if (Confirm-Ui ('{0} aktualisieren?' -f ($ids -join ', '))) { Start-Run -Parts @('WingetInstall') -WingetApps $ids } })
$ui.BtnVulnRemove.Add_Click({
    $sel = @($ui.VulnGrid.SelectedItems); if (-not $sel.Count) { return }
    if (-not (Confirm-Ui ("Diese Programme deinstallieren?`n`n{0}`n`nVorher wird ein Wiederherstellungspunkt gesetzt." -f (($sel | ForEach-Object { '  - ' + $_.Name }) -join "`n")) 'Warning')) { return }
    Start-Run -Parts @('Debloat') -Job @{ Apps = @(); Win32 = @($sel | ForEach-Object { $_.Key }); Provisioned = $false }
})
$ui.BtnVulnWeb.Add_Click({ $r = $ui.VulnGrid.SelectedItem; if ($r) { Start-Process ('https://www.bing.com/search?q=' + [uri]::EscapeDataString(('{0} {1} Sicherheitslücke CVE' -f $r.Name, $r.Version))) } })
$ui.Tabs.Add_SelectionChanged({ param($s, $e) if ($e.OriginalSource -eq $s -and $s.SelectedItem -eq $ui.TabVuln -and -not $script:VulnRows) { Start-VulnScan } })

# ---------------------------------------------------------------- Meine PCs: Fernaufträge und Anbindung (Oberfläche)
function Update-RemPage {
    $cur = [string]$ui.RemPc.SelectedItem
    $ui.RemPc.Items.Clear(); foreach ($p in @($script:FleetPcs | ForEach-Object { $_.Computer } | Sort-Object -Unique)) { [void]$ui.RemPc.Items.Add($p) }
    if (-not $ui.RemPc.Items.Contains($env:COMPUTERNAME)) { [void]$ui.RemPc.Items.Add($env:COMPUTERNAME) }
    $ui.RemPc.SelectedItem = $(if ($cur -and $ui.RemPc.Items.Contains($cur)) { $cur } else { $ui.RemPc.Items[0] })
    if (-not $ui.RemAction.Items.Count) { foreach ($k in $FleetActions.Keys) { $i = New-Object Windows.Controls.ComboBoxItem; $i.Content = $FleetActions[$k]; $i.Tag = $k; [void]$ui.RemAction.Items.Add($i) }; $ui.RemAction.SelectedIndex = 1 }
    Update-RemJobs
}
function Update-RemJobs {
    $dir = $ui.Fleet_Dir.Text.Trim(); $pc = [string]$ui.RemPc.SelectedItem
    if (-not $dir -or -not $pc) { $ui.RemSeen.Text = 'Erst oben den gemeinsamen Ordner einstellen.'; return }
    try { $x = Get-FleetJobs $dir $pc } catch { $ui.RemSeen.Text = $_.Exception.Message; return }
    Set-GridItems $ui.RemGrid @($x.Jobs)
    $ui.RemSeen.Text = if ($x.Seen) { $age = ((Get-Date) - [datetime]$x.Seen).TotalMinutes; '{0} hat zuletzt vor {1} nach Aufträgen geschaut{2}.' -f $pc, $(if ($age -lt 1) { 'weniger als einer Minute' } elseif ($age -lt 120) { '{0:N0} Minuten' -f $age } else { '{0:N0} Stunden' -f ($age / 60) }), $(if ($age -gt 30) { ' - der PC ist wohl aus oder Fernaufträge sind dort nicht eingeschaltet' } else { ' - online' }) } else { $pc + ' hat noch nie nach Aufträgen geschaut - dort in PC-Tools "Aufträge annehmen" einschalten und speichern.' }
}
$ui.RemPc.Add_SelectionChanged({ param($s, $e) $e.Handled = $true; Update-RemJobs })
$ui.BtnRemRefresh.Add_Click({ Update-RemJobs })
$ui.BtnRemSend.Add_Click({
    $dir = $ui.Fleet_Dir.Text.Trim(); $pc = [string]$ui.RemPc.SelectedItem; $a = $ui.RemAction.SelectedItem
    if (-not $dir -or -not $pc -or -not $a) { return }
    if ([string]$a.Tag -in 'Neustart', 'Aus' -and -not (Confirm-Ui ('{0} auf {1} wirklich auslösen? Wer dort arbeitet, bekommt 5 Minuten Vorwarnung.' -f $a.Content, $pc) 'Warning')) { return }
    try { Connect-BackupTarget $dir; $id = Send-FdJob $dir $pc ([string]$a.Tag) @{} (Get-FdKeySafe) ''; $ui.StatusText.Text = ('Auftrag an {0} gesendet - wird innerhalb von 10 Minuten ausgeführt.' -f $pc) } catch { Show-UiError $_.Exception.Message }
    Update-RemJobs
})
$ui.BtnIntSave.Add_Click({
    try {
        $s = Get-IntegrationSecrets
        if ($ui.IntMqttPwd.Password) { $s.MqttPass = $ui.IntMqttPwd.Password }; if ($ui.IntHaToken.Password) { $s.HaToken = $ui.IntHaToken.Password }; if ($ui.IntRmmToken.Password) { $s.RmmToken = $ui.IntRmmToken.Password }
        Save-IntegrationSecrets $s; $ui.IntMqttPwd.Password = ''; $ui.IntHaToken.Password = ''; $ui.IntRmmToken.Password = ''
        $null = Save-All -Quiet; $ui.IntInfo.Text = 'Gespeichert. Gesendet wird nach jeder Pflege und alle 10 Minuten (mit Fernaufträgen).'
    } catch { Show-UiError $_.Exception.Message }
})
$ui.BtnIntTest.Add_Click({
