$ui.BtnIntExample.Add_Click({
    $pc = ($env:COMPUTERNAME.ToLower() -replace '[^a-z0-9_]', '_')
    $y = @"
# Home Assistant: Benachrichtigung, wenn ein PC rot wird (MQTT-Sensoren von PC-Tools)
alias: PC-Tools $env:COMPUTERNAME rot
triggers:
  - trigger: state
    entity_id: sensor.${pc}_ampel
