    [Windows.MessageBox]::Show((T (("In die Zwischenablage kopiert - in Home Assistant unter Einstellungen > Automatisierungen > neu > YAML einfügen:`n`n" + $y))), (T ('PC-Tools - Beispiel')), 'OK', 'Information') | Out-Null
})
