# ---------------------------------------------------------------- Garantie (Seite BIOS)
function Show-Warranty($w) {
    if (-not $w) { $ui.WarEnd.Text = 'unbekannt'; $ui.WarDetails.Text = 'noch nicht geprüft'; return }
    $end = $null; try { if ($w.End) { $end = [datetime]$w.End } } catch { }
    $ui.WarEnd.Text = if ($end) { '{0:dd.MM.yyyy}  ({1})' -f $end, $(if ($end -lt (Get-Date)) { 'abgelaufen' } else { 'noch {0} Tage' -f [int]($end - (Get-Date)).TotalDays }) } else { 'unbekannt' }
    $ui.WarEnd.Foreground = $(if (-not $end) { $Brush.Gray } elseif ($end -lt (Get-Date)) { $Brush.Red } elseif (($end - (Get-Date)).TotalDays -lt 60) { New-UiBrush '#B45309' } else { $Brush.Green })
    $ui.WarDetails.Text = $(if (@($w.Items).Count) { (@($w.Items) | ForEach-Object { '{0}: {1} bis {2}' -f $_.Name, ($_.Start -split 'T')[0], ($_.End -split 'T')[0] }) -join '  ·  ' } else { 'Quelle: ' + $w.Source }) + $(if ($w.Note) { '  ·  ' + $w.Note } else { '' })
    if ($end) { $ui.WarDate.SelectedDate = $end }
}
$ui.BtnWarCheck.Add_Click({ $window.Cursor = 'Wait'; try { Show-Warranty (Get-WarrantyInfo -Online) } catch { Show-UiError $_.Exception.Message } finally { $window.Cursor = $null } })
$ui.BtnWarOpen.Add_Click({ $b = Get-CimInstance Win32_BIOS; $cs = Get-CimInstance Win32_ComputerSystem; Set-Clipboard -Value ([string]$b.SerialNumber).Trim(); $ui.StatusText.Text = 'Seriennummer kopiert: ' + $b.SerialNumber; Start-Process (Get-WarrantyUrl ([string]$cs.Manufacturer) ([string]$b.SerialNumber).Trim()) })
$ui.BtnWarSave.Add_Click({
    if (-not $ui.WarDate.SelectedDate) { Show-UiError 'Bitte ein Datum wählen.'; return }
    $w = Get-WarrantyInfo; $w | Add-Member -NotePropertyName End -NotePropertyValue $ui.WarDate.SelectedDate.ToString('yyyy-MM-dd') -Force; $w | Add-Member -NotePropertyName Source -NotePropertyValue 'selbst eingetragen' -Force
    $w | ConvertTo-Json -Depth 4 | Set-Content $WarrantyFile -Encoding UTF8; Show-Warranty $w; $ui.StatusText.Text = 'Garantie gespeichert.'
})
$ui.Tabs.Add_SelectionChanged({ param($s, $e) if ($e.OriginalSource -eq $s -and $s.SelectedItem -eq $ui.TabBios) { try { Show-Warranty (Get-WarrantyInfo) } catch { } } })

