        param($r, $err)
        if ($err) { $ui.OemPackInfo.Text = 'Kein Komplettpaket: ' + $err.Message + ' — "Treiberpaket installieren" nutzt dann automatisch Windows Update (deckt Kamera, Drucker, USB, Sound usw. ab), oder oben "Alle Treiber jetzt aktualisieren".'; return }
        $i = @($r | Where-Object { $_ -and $_.Url })[0]
        $ui.OemPackInfo.Text = '{0}: {1}, Version {2} vom {3} ({4}){5}' -f $i.Model, $i.Name, $i.Version, (($i.Date -split 'T')[0]), $i.Os, $(if ($i.Hash) { ' - mit Prüfsumme' } else { '' })
    }
