# ---------------------------------------------------------------- Oberfläche: sanftes Einblenden beim Seitenwechsel
$ui.Tabs.Add_SelectionChanged({
    param($s, $e)
    if ($e.OriginalSource -ne $s) { return }
    try {
        $c = $s.SelectedItem.Content; if (-not ($c -is [Windows.UIElement])) { return }
        $tt = New-Object Windows.Media.TranslateTransform; $c.RenderTransform = $tt
        $ease = New-Object Windows.Media.Animation.CubicEase; $ease.EasingMode = 'EaseOut'
        $fa = New-Object Windows.Media.Animation.DoubleAnimation(0, 1, [TimeSpan]::FromMilliseconds(220)); $fa.EasingFunction = $ease
        $ma = New-Object Windows.Media.Animation.DoubleAnimation(14, 0, [TimeSpan]::FromMilliseconds(260)); $ma.EasingFunction = $ease
        $c.BeginAnimation([Windows.UIElement]::OpacityProperty, $fa); $tt.BeginAnimation([Windows.Media.TranslateTransform]::YProperty, $ma)
    } catch { }
})

