# ---------------------------------------------------------------- Drucker und Scanner (Oberfläche)
$PrnVendors = [ordered]@{
    HP        = @{ M = '(?i)\bHP\b|Hewlett|LaserJet|OfficeJet|DeskJet|ENVY|Smart Tank|PageWide'; Site = 'support.hp.com'; App = 'HP Smart'; Url = 'https://support.hp.com/de-de/drivers' }
    Brother   = @{ M = '(?i)Brother|\b(MFC|DCP|HL)-'; Site = 'support.brother.com'; App = 'Brother iPrint&Scan'; Url = 'https://support.brother.com/g/b/productsearch.aspx?c=de&lang=de&content=dl' }
    Canon     = @{ M = '(?i)Canon|PIXMA|MAXIFY|i-SENSYS|imageRUNNER|imageCLASS'; Site = 'canon.de'; App = 'Canon PRINT'; Url = 'https://www.canon.de/support/' }
    Epson     = @{ M = '(?i)Epson|EcoTank|WorkForce|Expression'; Site = 'epson.de'; App = 'Epson'; Url = 'https://www.epson.de/de_DE/support' }
    Samsung   = @{ M = '(?i)Samsung|Xpress'; Site = 'support.hp.com'; App = 'Samsung Easy Printer Manager'; Url = 'https://support.hp.com/de-de/drivers' }
    Kyocera   = @{ M = '(?i)Kyocera|ECOSYS|TASKalfa'; Site = 'kyoceradocumentsolutions.de'; App = 'Kyocera'; Url = 'https://www.kyoceradocumentsolutions.de/de/support/downloads.html' }
    Lexmark   = @{ M = '(?i)Lexmark'; Site = 'support.lexmark.com'; App = 'Lexmark'; Url = 'https://support.lexmark.com/' }
    Xerox     = @{ M = '(?i)Xerox|VersaLink|AltaLink|WorkCentre|Phaser'; Site = 'support.xerox.com'; App = 'Xerox'; Url = 'https://www.support.xerox.com/' }
    Ricoh     = @{ M = '(?i)Ricoh|Aficio|\bSP C?\d{3}'; Site = 'ricoh.de'; App = 'Ricoh'; Url = 'https://support.ricoh.com/' }
    Konica    = @{ M = '(?i)Konica|Minolta|bizhub'; Site = 'konicaminolta.de'; App = 'Konica Minolta'; Url = 'https://www.konicaminolta.de/de-de/support/download-center' }
    OKI       = @{ M = '(?i)\bOKI\b'; Site = 'oki.com'; App = 'OKI'; Url = 'https://www.oki.com/eu/printing/support/drivers-and-utilities/' }
    Sharp     = @{ M = '(?i)Sharp'; Site = 'sharp.de'; App = 'Sharp'; Url = 'https://www.sharp.de/' }
    Dell      = @{ M = '(?i)\bDell\b'; Site = 'dell.com'; App = 'Dell'; Url = 'https://www.dell.com/support/home/de-de' }
}
function Get-PrnVendor([string]$Text) { foreach ($k in $PrnVendors.Keys) { if ($Text -match $PrnVendors[$k].M) { return $k } }; return '' }
function Get-SnmpString([string]$Ip, [string]$Oid, [string]$Community = 'public', [int]$Timeout = 900) {
    $tlv = { param([byte]$t, [byte[]]$v) $l = $v.Length; $h = if ($l -lt 128) { [byte[]]@($t, $l) } elseif ($l -lt 256) { [byte[]]@($t, 0x81, $l) } else { [byte[]]@($t, 0x82, ($l -shr 8), ($l -band 255)) }; [byte[]]($h + $v) }
    $p = @($Oid.Split('.') | ForEach-Object { [int]$_ }); $ob = [System.Collections.Generic.List[byte]]::new(); $ob.Add([byte](40 * $p[0] + $p[1]))
    for ($i = 2; $i -lt $p.Count; $i++) { $v = $p[$i]; $tmp = [System.Collections.Generic.List[byte]]::new(); $tmp.Insert(0, [byte]($v -band 0x7F)); $v = $v -shr 7; while ($v -gt 0) { $tmp.Insert(0, [byte](($v -band 0x7F) -bor 0x80)); $v = $v -shr 7 }; $ob.AddRange($tmp) }
    $oidT = & $tlv 0x06 $ob.ToArray()
    $vb = & $tlv 0x30 ([byte[]]($oidT + [byte[]]@(0x05, 0x00)))
    $pdu = & $tlv 0xA0 ([byte[]]([byte[]]@(0x02, 0x01, 0x01, 0x02, 0x01, 0x00, 0x02, 0x01, 0x00) + (& $tlv 0x30 $vb)))
    $msg = & $tlv 0x30 ([byte[]]([byte[]]@(0x02, 0x01, 0x00) + (& $tlv 0x04 ([Text.Encoding]::ASCII.GetBytes($Community))) + $pdu))
    $u = New-Object Net.Sockets.UdpClient; $u.Client.ReceiveTimeout = $Timeout
    try {
        $null = $u.Send($msg, $msg.Length, $Ip, 161); $ep = New-Object Net.IPEndPoint([Net.IPAddress]::Any, 0); $r = $u.Receive([ref]$ep)
        for ($i = 0; $i -le $r.Length - $oidT.Length; $i++) {
            $m = $true; for ($j = 0; $j -lt $oidT.Length; $j++) { if ($r[$i + $j] -ne $oidT[$j]) { $m = $false; break } }
            if ($m) { $k = $i + $oidT.Length; if ($r[$k] -ne 0x04) { return '' }; $len = [int]$r[$k + 1]; $st = $k + 2; if ($len -eq 0x81) { $len = [int]$r[$k + 2]; $st = $k + 3 } elseif ($len -eq 0x82) { $len = [int]$r[$k + 2] * 256 + $r[$k + 3]; $st = $k + 4 }; return ([Text.Encoding]::UTF8.GetString($r, $st, [math]::Min($len, $r.Length - $st)) -replace '[\x00-\x1F]', ' ').Trim() }
        }
    } catch { } finally { $u.Close() }
    return ''
}
function Find-NetPrinters {
    $ips = @(Get-NetIPAddress -AddressFamily IPv4 -ErrorAction SilentlyContinue | Where-Object { $_.IPAddress -notlike '127.*' -and $_.IPAddress -notlike '169.254*' -and $_.PrefixLength -ge 16 -and $_.PrefixLength -le 30 } | Select-Object -First 2)
    $tasks = [System.Collections.Generic.List[object]]::new()
    foreach ($a in $ips) { $pre = ($a.IPAddress -split '\.')[0..2] -join '.'; for ($i = 1; $i -lt 255; $i++) { foreach ($port in 9100, 631, 515) { $c = New-Object Net.Sockets.TcpClient; $tasks.Add([pscustomobject]@{ Ip = "$pre.$i"; Port = $port; C = $c; T = $c.ConnectAsync("$pre.$i", $port) }) } } }
    Start-Sleep -Milliseconds 2500
    $hit = @{}; foreach ($t in $tasks) { if ($t.T.Status -eq 'RanToCompletion' -and $t.C.Connected) { if (-not $hit.ContainsKey($t.Ip)) { $hit[$t.Ip] = @() }; $hit[$t.Ip] += $t.Port }; try { $t.C.Close() } catch { } }
    $names = @{}; foreach ($ip in $hit.Keys) { $names[$ip] = [Net.Dns]::GetHostEntryAsync($ip) }
    Start-Sleep -Milliseconds 1200
    $ports = @(Get-PrinterPort -ErrorAction SilentlyContinue | ForEach-Object { [string]$_.PrinterHostAddress })
    foreach ($ip in ($hit.Keys | Sort-Object { [version]$_ })) {
        $model = Get-SnmpString $ip '1.3.6.1.2.1.25.3.2.1.3.1'; if (-not $model) { $model = Get-SnmpString $ip '1.3.6.1.2.1.1.1.0' }
        if (-not $model) { try { $w = Invoke-WebRequest -Uri ('http://{0}/' -f $ip) -UseBasicParsing -TimeoutSec 3 -ErrorAction Stop; if ($w.Content -match '<title>\s*([^<]{3,80})</title>') { $model = $Matches[1].Trim() } } catch { } }
        $nm = ''; if ($names[$ip].Status -eq 'RanToCompletion') { $nm = $names[$ip].Result.HostName }
        [pscustomobject]@{ Ip = $ip; Host = $nm; Model = $model; Vendor = ''; Ports = ($hit[$ip] -join ', '); Known = $(if ($ports -contains $ip) { 'ja' } else { '' }) }
    }
}
function Update-Printers {
    $def = [string](@(Get-CimInstance Win32_Printer -Filter 'Default=TRUE' -ErrorAction SilentlyContinue)[0].Name)
    $wp = @{}; foreach ($x in @(Get-CimInstance Win32_Printer -ErrorAction SilentlyContinue)) { $wp[$x.Name] = $x }
    $pp = @{}; foreach ($x in @(Get-PrinterPort -ErrorAction SilentlyContinue)) { $pp[$x.Name] = $x }
    $rows = @(Get-Printer -ErrorAction SilentlyContinue | Sort-Object Name | ForEach-Object {
        $w = $wp[$_.Name]; $port = $pp[$_.PortName]; $addr = if ($port -and $port.PrinterHostAddress) { '{0} ({1})' -f $port.PrinterHostAddress, $_.PortName } else { $_.PortName }
        $st = [string]$_.PrinterStatus; if ($w -and $w.WorkOffline) { $st = 'offline verwenden' }
        $jobs = @(Get-PrintJob -PrinterName $_.Name -ErrorAction SilentlyContinue).Count
        [pscustomobject]@{ Name = $_.Name; Driver = $_.DriverName; Port = $addr; Default = $(if ($_.Name -eq $def) { 'ja' } else { '' }); State = $(switch ($st) { 'Normal' { 'bereit' } 'Error' { 'Fehler' } 'Offline' { 'offline' } 'PaperJam' { 'Papierstau' } 'PaperOut' { 'kein Papier' } 'TonerLow' { 'Toner/Tinte niedrig' } default { $st } }); Jobs = $jobs; Bad = ($st -notin 'Normal', ''); Ip = $(if ($port) { [string]$port.PrinterHostAddress } else { '' }); Shared = [bool]$_.Shared; Type = [string]$_.Type }
    })
    Set-GridItems $ui.PrnGrid $rows
    $cur = $ui.PrnDriver.Text
    $ui.PrnDriver.Items.Clear()
    foreach ($n in @(Get-PrinterDriver -ErrorAction SilentlyContinue | Where-Object { $_.Name -notmatch 'Microsoft (XPS|Print To PDF|Shared Fax|enhanced Point)|Remote Desktop|OneNote|Fax' } | ForEach-Object { $_.Name } | Sort-Object -Unique) + @('Microsoft IPP Class Driver', 'Microsoft PCL6 Class Driver', 'Microsoft PS Class Driver')) { if (-not $ui.PrnDriver.Items.Contains($n)) { [void]$ui.PrnDriver.Items.Add($n) } }
    $ui.PrnDriver.Text = $(if ($cur) { $cur } else { 'Microsoft IPP Class Driver' })
    $sc = @(Get-PnpDevice -Class Image -ErrorAction SilentlyContinue | Where-Object { $_.Present })
    $svc = Get-Service stisvc -ErrorAction SilentlyContinue
    $ui.PrnScanInfo.Text = 'Scanner: {0}  ·  Scanner-Dienst (WIA): {1}' -f $(if ($sc.Count) { ($sc | ForEach-Object { '{0} ({1})' -f $_.FriendlyName, $(if ($_.Status -eq 'OK') { 'bereit' } else { $_.Status }) }) -join ', ' } else { 'keiner erkannt - bei Multifunktionsgeräten meist erst nach Installation des Herstellerpakets' }), $(if ($svc) { $(if ($svc.Status -eq 'Running') { 'läuft' } else { [string]$svc.Status }) } else { 'fehlt' })
}
function Get-PrnSel { $r = $ui.PrnGrid.SelectedItem; if (-not $r) { Show-UiError 'Bitte oben einen Drucker auswählen.' }; return $r }
function Set-PrnTarget([string]$Ip, [string]$Name, [string]$Model) {
    if ($Ip) { $ui.PrnIp.Text = $Ip }; if ($Name -and -not $ui.PrnName.Text) { $ui.PrnName.Text = $Name }
    $script:PrnModel = $Model; $v = Get-PrnVendor $Model; $script:PrnVendor = $v
    $ui.PrnModelInfo.Text = if ($Model) { '{0}{1}' -f $Model, $(if ($v) { '  (Hersteller: ' + $v + ')' } else { '' }) } else { '' }
    if ($v) { $d = @($ui.PrnDriver.Items | Where-Object { $_ -match [regex]::Escape($v) -or ($Model -and $_ -match [regex]::Escape((($Model -split '\s+') | Select-Object -Last 1))) }) | Select-Object -First 1; if ($d) { $ui.PrnDriver.Text = $d } }
}
function Get-PrnDiag {
    $out = [System.Collections.Generic.List[object]]::new()
    function R($lvl, $title, $detail, $fix = '', $fixText = '', $arg = '') { $out.Add([pscustomobject]@{ Level = $lvl; StateText = @{ ok = 'in Ordnung'; warn = 'Hinweis'; bad = 'Problem' }[$lvl]; Title = $title; Detail = $detail; Fix = $fix; FixText = $fixText; Arg = $arg }) }
    $sp = Get-Service Spooler -ErrorAction SilentlyContinue
    if (-not $sp -or $sp.Status -ne 'Running' -or $sp.StartType -ne 'Automatic') { R 'bad' 'Druckwarteschlange (Dienst)' ('Status {0}, Start {1}' -f $sp.Status, $sp.StartType) 'Spooler' 'Dienst starten und auf automatisch' } else { R 'ok' 'Druckwarteschlange (Dienst)' 'läuft, startet automatisch' }
    $spool = Join-Path $env:SystemRoot 'System32\spool\PRINTERS'
    $stuck = @(Get-ChildItem $spool -File -ErrorAction SilentlyContinue | Where-Object { $_.LastWriteTime -lt (Get-Date).AddMinutes(-15) })
    if ($stuck.Count) { R 'bad' 'Hängende Druckaufträge' ('{0} alte Dateien im Druckspeicher (älter als 15 Minuten)' -f $stuck.Count) 'Clear' 'Warteschlange leeren' } else { R 'ok' 'Hängende Druckaufträge' 'keine' }
    foreach ($p in @(Get-Printer -ErrorAction SilentlyContinue)) {
        if ($p.Name -match 'Microsoft (XPS|Print to PDF)|OneNote|Fax') { continue }
        $w = Get-CimInstance Win32_Printer -Filter ("Name='{0}'" -f ($p.Name -replace '\\', '\\' -replace "'", "\'")) -ErrorAction SilentlyContinue
        if ($w -and $w.WorkOffline) { R 'bad' ('{0}: "Drucker offline verwenden" ist an' -f $p.Name) 'Windows schickt nichts an den Drucker.' 'Online' 'Online schalten' $p.Name }
        $port = Get-PrinterPort -Name $p.PortName -ErrorAction SilentlyContinue
        if ($port -and $port.PrinterHostAddress) {
            $ip = [string]$port.PrinterHostAddress
            $ok = $false; try { $ok = (New-Object Net.NetworkInformation.Ping).Send($ip, 1500).Status -eq 'Success' } catch { }
            $open = @(); foreach ($pt in 9100, 631, 515, 80) { $c = New-Object Net.Sockets.TcpClient; try { if ($c.ConnectAsync($ip, $pt).Wait(900) -and $c.Connected) { $open += $pt } } catch { } finally { $c.Close() } }
            if (-not $ok -and -not $open.Count) { R 'bad' ('{0}: nicht erreichbar ({1})' -f $p.Name, $ip) 'Drucker aus, im Energiesparmodus, im anderen WLAN - oder er hat eine neue IP-Adresse bekommen.' 'NewIp' 'Neue Adresse suchen' $p.Name }
            elseif (-not ($open -contains 9100 -or $open -contains 631 -or $open -contains 515)) { R 'warn' ('{0}: erreichbar, aber kein Druckanschluss offen' -f $p.Name) ('{0} antwortet, Anschlüsse 9100/631/515 zu - ist das wirklich der Drucker?' -f $ip) 'NewIp' 'Neue Adresse suchen' $p.Name }
            else { R 'ok' ('{0}: erreichbar' -f $p.Name) ('{0}, Anschlüsse {1}' -f $ip, ($open -join ', ')) }
            $sn = Get-ItemProperty ('HKLM:\SYSTEM\CurrentControlSet\Control\Print\Monitors\Standard TCP/IP Port\Ports\' + $p.PortName) -ErrorAction SilentlyContinue
            if ($sn -and $sn.'SNMP Enabled' -eq 1) { R 'warn' ('{0}: SNMP-Statusabfrage an' -f $p.Name) 'Häufigste Ursache für ein falsches "Offline", obwohl der Drucker druckt.' 'Snmp' 'SNMP-Abfrage aus' $p.PortName }
        } elseif ($p.PortName -match '^WSD') { R 'warn' ('{0}: per WSD verbunden' -f $p.Name) 'WSD-Anschlüsse verlieren gern die Verbindung (z.B. nach IP-Wechsel). Stabiler: als TCP/IP-Drucker neu einrichten.' 'Recreate' 'Als TCP/IP-Drucker neu anlegen' $p.Name }
        if ([string]$p.PrinterStatus -in 'Error', 'Offline' -and -not ($w -and $w.WorkOffline)) { R 'warn' ('{0}: meldet "{1}"' -f $p.Name, $p.PrinterStatus) 'Papier, Toner/Tinte, Klappen und Display am Gerät prüfen.' }
        $drv = Get-PrinterDriver -Name $p.DriverName -ErrorAction SilentlyContinue
        if (-not $drv) { R 'bad' ('{0}: Treiber fehlt' -f $p.Name) $p.DriverName 'Driver' 'Treiber neu installieren (Seite oben)' $p.Name }
    }
    $pnp = @(Get-PnpDevice -Class Printer, Image -ErrorAction SilentlyContinue | Where-Object { $_.Present -and $_.Status -ne 'OK' })
    foreach ($d in $pnp) { R 'bad' ('Gerät ohne funktionierenden Treiber: {0}' -f $d.FriendlyName) ('Status {0}' -f $d.Status) 'WuDriver' 'Treiber über Windows Update suchen' }
    $ev = @(Get-WinEvent -FilterHashtable @{ LogName = 'Microsoft-Windows-PrintService/Admin'; Level = 2, 3; StartTime = (Get-Date).AddDays(-7) } -MaxEvents 200 -ErrorAction SilentlyContinue)
    if ($ev.Count) { $g = @($ev | Group-Object Id | Sort-Object Count -Descending | Select-Object -First 3 | ForEach-Object { 'Ereignis {0} ({1}x): {2}' -f $_.Name, $_.Count, (($_.Group[0].Message -split "`n")[0]).Trim() }); R 'warn' ('{0} Druck-Fehler in 7 Tagen' -f $ev.Count) ($g -join ' | ') } else { R 'ok' 'Druck-Ereignisprotokoll' 'keine Fehler in den letzten 7 Tagen' }
    $shared = @(Get-Printer -ErrorAction SilentlyContinue | Where-Object { $_.Type -eq 'Connection' })
    if ($shared.Count) { $v = (Get-ItemProperty 'HKLM:\SYSTEM\CurrentControlSet\Control\Print' -ErrorAction SilentlyContinue).RpcAuthnLevelPrivacyEnabled; R 'warn' ('{0} Drucker über einen anderen PC freigegeben' -f $shared.Count) 'Bei Fehler 0x0000011b beim Verbinden: Den freigebenden PC aktualisieren. Nur als Notlösung auf dem Druckserver die RPC-Verschlüsselung lockern.' $(if ($v -ne 0) { 'Rpc11b' } else { '' }) $(if ($v -ne 0) { 'Notlösung 0x11b (weniger sicher)' } else { '' }) }
    $st = Get-Service stisvc -ErrorAction SilentlyContinue
    if ($st -and $st.Status -ne 'Running') { R 'warn' 'Scanner-Dienst (WIA) läuft nicht' ('Status ' + $st.Status) 'Wia' 'Scanner-Dienst starten' }
    $fd = Get-Service FDResPub, fdPHost -ErrorAction SilentlyContinue | Where-Object { $_.Status -ne 'Running' }
    if ($fd) { R 'warn' 'Netzwerkerkennung eingeschränkt' ('Dienste aus: ' + (($fd | ForEach-Object { $_.Name }) -join ', ') + ' - neue Drucker werden evtl. nicht gefunden') 'Discovery' 'Dienste starten' }
    return , $out
}
function Invoke-PrnFix($Row) {
    switch ($Row.Fix) {
        'Spooler' { Set-Service Spooler -StartupType Automatic; Start-Service Spooler }
        'Clear'   { Stop-Service Spooler -Force; Start-Sleep 2; Remove-Item (Join-Path $env:SystemRoot 'System32\spool\PRINTERS\*') -Force -ErrorAction SilentlyContinue; Start-Service Spooler }
        'Online'  { $w = Get-CimInstance Win32_Printer -Filter ("Name='{0}'" -f ($Row.Arg -replace '\\', '\\' -replace "'", "\'")); $w.WorkOffline = $false; Set-CimInstance -InputObject $w }
        'Snmp'    { Set-ItemProperty ('HKLM:\SYSTEM\CurrentControlSet\Control\Print\Monitors\Standard TCP/IP Port\Ports\' + $Row.Arg) -Name 'SNMP Enabled' -Value 0 -Type DWord; Restart-Service Spooler -Force }
        'Wia'     { Set-Service stisvc -StartupType Automatic; Restart-Service stisvc -Force }
        'Discovery' { foreach ($n in 'FDResPub', 'fdPHost', 'SSDPSRV', 'upnphost') { Set-Service $n -StartupType Automatic -ErrorAction SilentlyContinue; Start-Service $n -ErrorAction SilentlyContinue } }
        'Rpc11b'  { if (Confirm-Ui 'Diese Notlösung senkt die Sicherheit (PrintNightmare-Schutz). Nur auf dem PC setzen, der den Drucker freigibt, und nur wenn Updates nicht helfen. Wirklich?' 'Warning') { Set-PReg 'HKLM:\SYSTEM\CurrentControlSet\Control\Print' 'RpcAuthnLevelPrivacyEnabled' 0; Restart-Service Spooler -Force } }
        'WuDriver' { Start-Run -Parts @('WUDrivers') -Job @{ DriverIds = @() } }
        'Driver'  { $ui.PrnName.Text = $Row.Arg; [void]$ui.PrnDriver.Focus() }
        'NewIp'   { $script:PrnFixTarget = $Row.Arg; $ui.BtnPrnScan.RaiseEvent((New-Object Windows.RoutedEventArgs ([Windows.Controls.Button]::ClickEvent))); [Windows.MessageBox]::Show((T ('Die Suche läuft. Danach den Drucker in der Liste "gefunden" doppelt anklicken - PC-Tools stellt den vorhandenen Drucker auf die neue Adresse um.')), (T ('PC-Tools')), 'OK', 'Information') | Out-Null }
        'Recreate' { $p = Get-Printer -Name $Row.Arg; $ui.PrnName.Text = $p.Name + ' (TCP/IP)'; $ui.PrnDriver.Text = $p.DriverName; [Windows.MessageBox]::Show((T ('Name und Treiber sind unten eingetragen. Jetzt "Im Netz suchen", Drucker wählen und "Drucker einrichten" - danach den alten WSD-Drucker entfernen.')), (T ('PC-Tools')), 'OK', 'Information') | Out-Null }
    }
}
function Start-PrnDiag {
    $ui.PrnDiagGrid.ItemsSource = $null; $ui.StatusText.Text = 'Prüfe Drucker (bis zu 30 Sekunden) ...'; $ui.BtnPrnDiag.IsEnabled = $false
    Invoke-Bg -Script { Get-PrnDiag } -Functions @('Get-PrnDiag') -Done {
        param($r, $err)
        $ui.BtnPrnDiag.IsEnabled = $true
        if ($err) { $ui.StatusText.Text = 'Druckerprüfung: ' + $err.Message; return }
        $rows = @($r | ForEach-Object { $_ } | Where-Object { $_ -and $_.Title } | Sort-Object @{ e = { @{ bad = 0; warn = 1; ok = 2 }[$_.Level] } }, Title)
        Set-GridItems $ui.PrnDiagGrid $rows
        $ui.StatusText.Text = 'Druckerprüfung: {0} Problem(e), {1} Hinweis(e).' -f @($rows | Where-Object Level -eq 'bad').Count, @($rows | Where-Object Level -eq 'warn').Count
    }
}
$ui.BtnPrnRefresh.Add_Click({ Update-Printers })
$ui.PrnGrid.Add_SelectionChanged({ param($s, $e) $r = $ui.PrnGrid.SelectedItem; if ($r) { $ui.PrnSelInfo.Text = '{0}: Treiber {1}, {2}{3}' -f $r.Name, $r.Driver, $(if ($r.Shared) { 'im Netz freigegeben' } else { 'nicht freigegeben' }), $(if ($r.Type -eq 'Connection') { ', verbunden über einen anderen PC' } else { '' }) } })
$ui.BtnPrnDefault.Add_Click({ $r = Get-PrnSel; if ($r) { try { $p = Get-CimInstance Win32_Printer -Filter ("Name='{0}'" -f ($r.Name -replace '\\', '\\' -replace "'", "\'")); $null = Invoke-CimMethod -InputObject $p -MethodName SetDefaultPrinter; Set-PReg 'HKCU:\Software\Microsoft\Windows NT\CurrentVersion\Windows' 'LegacyDefaultPrinterMode' 1; Update-Printers; $ui.StatusText.Text = $r.Name + ' ist jetzt Standard (Windows wechselt den Standard nicht mehr selbst).' } catch { Show-UiError $_.Exception.Message } } })
$ui.BtnPrnTest.Add_Click({ $r = Get-PrnSel; if ($r) { try { $p = Get-CimInstance Win32_Printer -Filter ("Name='{0}'" -f ($r.Name -replace '\\', '\\' -replace "'", "\'")); $x = Invoke-CimMethod -InputObject $p -MethodName PrintTestPage; $ui.StatusText.Text = 'Testseite an ' + $r.Name + ' gesendet (Code ' + $x.ReturnValue + ').' } catch { Show-UiError $_.Exception.Message } } })
$ui.BtnPrnPrefs.Add_Click({ $r = Get-PrnSel; if ($r) { Start-Process rundll32.exe -ArgumentList ('printui.dll,PrintUIEntry /e /n "{0}"' -f $r.Name) } })
$ui.BtnPrnQueueOpen.Add_Click({ $r = Get-PrnSel; if ($r) { Start-Process rundll32.exe -ArgumentList ('printui.dll,PrintUIEntry /o /n "{0}"' -f $r.Name) } })
$ui.BtnPrnQueue.Add_Click({ $r = Get-PrnSel; if ($r) { $n = @(Get-PrintJob -PrinterName $r.Name -ErrorAction SilentlyContinue).Count; Get-PrintJob -PrinterName $r.Name -ErrorAction SilentlyContinue | Remove-PrintJob -ErrorAction SilentlyContinue; $ui.StatusText.Text = '{0} Druckaufträge gelöscht.' -f $n; Update-Printers } })
$ui.BtnPrnWeb.Add_Click({ $r = Get-PrnSel; if ($r) { if ($r.Ip) { Start-Process ('http://{0}/' -f $r.Ip) } else { Show-UiError 'Dieser Drucker hat keine Netzwerkadresse (USB oder Freigabe).' } } })
$ui.BtnPrnRename.Add_Click({ $r = Get-PrnSel; if (-not $r) { return }; $d = Show-InputDialog 'Drucker umbenennen' ('Neuer Name für "{0}":' -f $r.Name) @(@{ Key = 'N'; Label = 'Name'; Type = 'Text'; Value = $r.Name }); if ($d -and $d.N -and $d.N -ne $r.Name) { try { Rename-Printer -Name $r.Name -NewName $d.N -ErrorAction Stop; Update-Printers } catch { Show-UiError $_.Exception.Message } } })
$ui.BtnPrnShare.Add_Click({ $r = Get-PrnSel; if (-not $r) { return }; try { if ($r.Shared) { Set-Printer -Name $r.Name -Shared $false -ErrorAction Stop } else { Set-Printer -Name $r.Name -Shared $true -ShareName (($r.Name -replace '[^\w\-]', '_').Substring(0, [math]::Min(40, $r.Name.Length))) -ErrorAction Stop; Enable-NetFirewallRule -Group '@FirewallAPI.dll,-28502' -ErrorAction SilentlyContinue }; Update-Printers } catch { Show-UiError $_.Exception.Message } })
$ui.BtnPrnDel.Add_Click({ $r = Get-PrnSel; if ($r -and (Confirm-Ui ('Drucker "{0}" entfernen?' -f $r.Name))) { try { Remove-Printer -Name $r.Name -ErrorAction Stop } catch { Show-UiError $_.Exception.Message }; Update-Printers } })
$ui.BtnPrnSettings.Add_Click({ Start-Process 'ms-settings:printers' })
$ui.BtnPrnWinAdd.Add_Click({ Start-Process rundll32.exe -ArgumentList 'printui.dll,PrintUIEntry /il' })
$ui.BtnPrnScan.Add_Click({
    $ui.PrnFound.ItemsSource = $null; $ui.StatusText.Text = 'Suche Drucker im Netz (ca. 10 Sekunden) ...'; $ui.BtnPrnScan.IsEnabled = $false
    Invoke-Bg -Script { Find-NetPrinters } -Functions @('Find-NetPrinters', 'Get-SnmpString') -Done {
        param($r, $err)
        $ui.BtnPrnScan.IsEnabled = $true
        $list = @($r | Where-Object { $_ -and $_.Ip }); foreach ($x in $list) { $x.Vendor = Get-PrnVendor ('{0} {1}' -f $x.Model, $x.Host) }
        Set-GridItems $ui.PrnFound $list
        $ui.StatusText.Text = $(if ($list.Count) { '{0} Drucker gefunden - anklicken übernimmt Adresse und Modell.' -f $list.Count } else { 'Keine Netzwerkdrucker gefunden (Drucker an und im selben Netz? Per USB angeschlossen?).' })
    }
})
$ui.PrnFound.Add_SelectionChanged({ param($s, $e) $e.Handled = $true; $x = $ui.PrnFound.SelectedItem; if ($x) { $ui.PrnName.Text = ''; Set-PrnTarget $x.Ip $(if ($x.Model) { ($x.Model -replace '\s*(series|Series|Printer).*$', '').Trim() } elseif ($x.Host) { ($x.Host -split '\.')[0] } else { 'Drucker ' + $x.Ip }) $x.Model } })
$ui.PrnFound.Add_MouseDoubleClick({
    $x = $ui.PrnFound.SelectedItem; if (-not $x -or -not $script:PrnFixTarget) { return }
    $p = Get-Printer -Name $script:PrnFixTarget -ErrorAction SilentlyContinue; if (-not $p) { return }
    if (Confirm-Ui ('Drucker "{0}" auf die neue Adresse {1} umstellen?' -f $p.Name, $x.Ip)) {
        try { $port = 'IP_' + $x.Ip; if (-not (Get-PrinterPort -Name $port -ErrorAction SilentlyContinue)) { Add-PrinterPort -Name $port -PrinterHostAddress $x.Ip -ErrorAction Stop }; Set-Printer -Name $p.Name -PortName $port -ErrorAction Stop; $script:PrnFixTarget = $null; Update-Printers; Start-PrnDiag } catch { Show-UiError $_.Exception.Message }
    }
})
$ui.BtnPrnUsb.Add_Click({
    $d = @(Get-PnpDevice -Class Printer, Image -ErrorAction SilentlyContinue | Where-Object { $_.Present -and $_.InstanceId -match '^USB|^SWD\\PRINTENUM' -or ($_.Present -and $_.InstanceId -match 'USBPRINT') })
    if (-not $d.Count) { Show-UiError 'Kein Drucker per USB erkannt. Kabel und Gerät prüfen - manche Geräte brauchen erst das Herstellerpaket.'; return }
    [Windows.MessageBox]::Show((T (('Per USB erkannt:' + "`n`n" + (($d | ForEach-Object { '{0}  -  {1}' -f $_.FriendlyName, $(if ($_.Status -eq 'OK') { 'Treiber in Ordnung' } else { 'ohne Treiber (' + $_.Status + ')' }) }) -join "`n")))), (T ('PC-Tools')), 'OK', 'Information') | Out-Null
    $m = ($d | Select-Object -First 1).FriendlyName; Set-PrnTarget '' $m $m
})
$ui.BtnPrnVendorPage.Add_Click({
    $m = $script:PrnModel; if (-not $m) { $m = $ui.PrnName.Text }
    $v = Get-PrnVendor $m
    if (-not $m) { Show-UiError 'Erst unten einen Drucker aus der Suche wählen oder den Modellnamen als Namen eintragen.'; return }
    $q = [uri]::EscapeDataString(('{0} Treiber Download komplettes Paket' -f $m))
    if ($v) { Set-Clipboard -Value $m; Start-Process ('https://www.bing.com/search?q={0}+site%3A{1}' -f $q, $PrnVendors[$v].Site); $ui.StatusText.Text = 'Modellname kopiert. Auf der Herstellerseite das "vollständige Treiber- und Softwarepaket" laden, dann "Heruntergeladenes Paket installieren".' }
    else { Start-Process ('https://www.bing.com/search?q=' + $q) }
})
$ui.BtnPrnVendorApp.Add_Click({
    $m = $script:PrnModel; $v = Get-PrnVendor $m; if (-not $v) { $v = Get-PrnVendor $ui.PrnName.Text }
    if (-not $v) { Show-UiError 'Hersteller unbekannt - bitte erst einen Drucker aus der Suche wählen.'; return }
    $ui.PrnVendorApps.Items.Clear(); [void]$ui.PrnVendorApps.Items.Add('Suche bei winget ...')
    Invoke-Bg -Script { param($q) $wg = Get-WingetPathX; if (-not $wg) { return }; (& $wg search $q --accept-source-agreements --disable-interactivity 2>$null) | ForEach-Object { ([string]$_ -split "`r")[-1] } } -Arguments @($(if ($v -eq 'Samsung') { 'Samsung Printer' } else { $v })) -Functions @('Get-WingetPathX') -Done {
        param($r, $err)
        $ui.PrnVendorApps.Items.Clear()
        $lines = @($r | Where-Object { $_ -and $_ -notmatch '^-{5,}|^Name\s+ID|^\s*$' } | Where-Object { $_ -match '(?i)print|scan|drucker|smart|easy|utility|driver|ij|epson|brother|canon|hp ' })
        if (-not $lines.Count) { [void]$ui.PrnVendorApps.Items.Add('Nichts passendes bei winget - bitte "Treiberseite des Herstellers" nutzen.'); return }
        foreach ($l in ($lines | Select-Object -First 15)) { $i = New-Object Windows.Controls.ListBoxItem; $i.Content = $l.Trim(); $i.Tag = (($l -split '\s{2,}') | Where-Object { $_ -match '^[\w\.\-]+\.[\w\.\-]+$' } | Select-Object -First 1); [void]$ui.PrnVendorApps.Items.Add($i) }
        [void]$ui.PrnVendorApps.Items.Add('Doppelklick installiert den Eintrag.')
    }
})
$ui.PrnVendorApps.Add_MouseDoubleClick({ $i = $ui.PrnVendorApps.SelectedItem; if ($i -and $i.Tag -and (Confirm-Ui ('{0} installieren?' -f $i.Tag))) { Start-Run -Parts @('WingetInstall') -WingetApps @([string]$i.Tag) } })
$ui.BtnPrnPackage.Add_Click({
    Add-Type -AssemblyName System.Windows.Forms
    $d = New-Object System.Windows.Forms.OpenFileDialog; $d.Filter = 'Treiberpaket (*.exe;*.msi;*.zip;*.inf)|*.exe;*.msi;*.zip;*.inf|Alle Dateien (*.*)|*.*'; $d.InitialDirectory = Join-Path $env:USERPROFILE 'Downloads'
    if ($d.ShowDialog() -ne 'OK') { return }
    $f = $d.FileName; $before = @(Get-PrinterDriver -ErrorAction SilentlyContinue | ForEach-Object { $_.Name })
    try {
        switch -Regex ($f) {
            '\.(exe|msi)$' {
                $sig = Get-AuthenticodeSignature -FilePath $f
                if ($sig.Status -ne 'Valid' -and -not (Confirm-Ui ('Das Paket ist nicht gültig signiert ({0}). Trotzdem ausführen?' -f $sig.Status) 'Warning')) { return }
                [Windows.MessageBox]::Show((T (('Der Installer des Herstellers ({0}) startet jetzt. Bei der Frage nach der Verbindung "Netzwerk" bzw. "USB" wählen - das Gerät wird dabei meist automatisch gefunden. Danach hier "Neu einlesen".' -f ($sig.SignerCertificate.Subject -replace '^CN=([^,]+).*$', '$1')))), (T ('PC-Tools')), 'OK', 'Information') | Out-Null
                $null = Invoke-UiWait { param($f) $p = if ($f -match '\.msi$') { Start-Process msiexec.exe -ArgumentList ('/i "{0}"' -f $f) -PassThru } else { Start-Process -FilePath $f -PassThru }; [void]$p.WaitForExit(3600000); 'ok' } @($f) @() 3700 'Der Hersteller-Installer läuft ... (PC-Tools wartet, bis er fertig ist)'
            }
            '\.zip$' { $o = [string]@(Invoke-UiWait { param($f) $x = Join-Path $env:TEMP ('PCPflege-Drucker-' + (Get-Random)); Expand-Archive -LiteralPath $f -DestinationPath $x -Force; $o = (& pnputil.exe /add-driver (Join-Path $x '*.inf') /subdirs /install 2>&1) -join "`n"; Remove-Item $x -Recurse -Force -ErrorAction SilentlyContinue; $o } @($f) @() 600 'Treiber wird installiert ...')[-1]; $ui.StatusText.Text = 'pnputil: ' + (($o -split "`n") | Select-Object -Last 3) -join ' ' }
            '\.inf$' { $o = [string]@(Invoke-UiWait { param($f) (& pnputil.exe /add-driver $f /install 2>&1) -join "`n" } @($f) @() 600 'Treiber wird installiert ...')[-1]; $ui.StatusText.Text = 'pnputil: ' + (($o -split "`n") | Select-Object -Last 3) -join ' ' }
        }
    } catch { Show-UiError $_.Exception.Message }
    # neu hinzugekommene Druckertreiber aus dem Treiberspeicher registrieren
    try { $null = Invoke-UiWait { param($before) foreach ($n in @(Get-CimInstance Win32_PnPSignedDriver -Filter "DeviceClass='PRINTER'" -ErrorAction SilentlyContinue | ForEach-Object { $_.DeviceName } | Where-Object { $_ } | Sort-Object -Unique)) { if ($before -notcontains $n) { try { Add-PrinterDriver -Name $n -ErrorAction Stop } catch { } } }; 'ok' } @(, $before) @() 300 'Neue Druckertreiber werden registriert ...' } catch { }
    Update-Printers
    $new = @(Get-PrinterDriver -ErrorAction SilentlyContinue | ForEach-Object { $_.Name } | Where-Object { $before -notcontains $_ })
    if ($new.Count) { $ui.PrnDriver.Text = $new[0]; [Windows.MessageBox]::Show((T (('Neue Druckertreiber: ' + ($new -join ', ') + "`n`nDer erste ist unten ausgewählt - jetzt ""Drucker einrichten"", falls der Hersteller-Installer das Gerät nicht schon selbst eingerichtet hat."))), (T ('PC-Tools')), 'OK', 'Information') | Out-Null }
})
$ui.BtnPrnWuDrv.Add_Click({ if (Confirm-Ui 'Windows Update nach Drucker- und Scannertreibern durchsuchen und installieren? Das nutzt den normalen Treiberlauf (alle Geräte).') { Start-Run -Parts @('WUDrivers') -Job @{ DriverIds = @() } } })
$ui.BtnPrnAdd.Add_Click({
    $ip = $ui.PrnIp.Text.Trim(); $n = $ui.PrnName.Text.Trim(); if (-not $n) { $n = 'Drucker ' + $ip }
    if ($ip -notmatch '^[\w\.\-]+$') { Show-UiError 'Bitte die IP-Adresse oder den Netzwerknamen des Druckers eintragen (oder oben suchen und anklicken).'; return }
    if (Get-Printer -Name $n -ErrorAction SilentlyContinue) { Show-UiError 'Einen Drucker mit diesem Namen gibt es schon.'; return }
    $window.Cursor = 'Wait'
    try {
        Add-NetPrinter $ip $n $ui.PrnDriver.Text.Trim()
        $port = 'IP_' + $ip
        if ($ui.PrnNoSnmp.IsChecked) { Set-ItemProperty ('HKLM:\SYSTEM\CurrentControlSet\Control\Print\Monitors\Standard TCP/IP Port\Ports\' + $port) -Name 'SNMP Enabled' -Value 0 -Type DWord -ErrorAction SilentlyContinue }
        if ($ui.PrnSetDefault.IsChecked) { $p = Get-CimInstance Win32_Printer -Filter ("Name='{0}'" -f ($n -replace "'", "\'")); $null = Invoke-CimMethod -InputObject $p -MethodName SetDefaultPrinter; Set-PReg 'HKCU:\Software\Microsoft\Windows NT\CurrentVersion\Windows' 'LegacyDefaultPrinterMode' 1 }
        if ($ui.PrnTestAfter.IsChecked) { Start-Sleep -Seconds 2; $p = Get-CimInstance Win32_Printer -Filter ("Name='{0}'" -f ($n -replace "'", "\'")); $null = Invoke-CimMethod -InputObject $p -MethodName PrintTestPage }
        $ui.StatusText.Text = 'Drucker ' + $n + ' eingerichtet.'; $ui.PrnName.Text = ''; $ui.PrnIp.Text = ''; $ui.PrnModelInfo.Text = ''
    } catch { Show-UiError ('Drucker konnte nicht eingerichtet werden: ' + $_.Exception.Message + "`n`nTipp: Weg 1 - das Herstellerpaket installieren, dann den Treiber hier wählen.") } finally { $window.Cursor = $null }
    Update-Printers
})
$ui.BtnPrnDiag.Add_Click({ Start-PrnDiag })
$ui.BtnPrnFix.Add_Click({ $r = $ui.PrnDiagGrid.SelectedItem; if (-not $r -or -not $r.Fix) { Show-UiError 'Bitte ein Problem mit Lösung auswählen.'; return }; try { Invoke-PrnFix $r; Start-Sleep 1; Update-Printers; if ($r.Fix -notin 'NewIp', 'Recreate', 'Driver', 'WuDriver') { Start-PrnDiag } } catch { Show-UiError $_.Exception.Message } })
$ui.BtnPrnFixAll.Add_Click({ $rows = @($ui.PrnDiagGrid.ItemsSource | Where-Object { $_.Fix -in 'Spooler', 'Clear', 'Online', 'Snmp', 'Wia', 'Discovery' }); if (-not $rows.Count) { Show-UiError 'Keine automatisch lösbaren Probleme (zuerst "Jetzt prüfen").'; return }; foreach ($r in $rows) { try { Invoke-PrnFix $r } catch { } }; Update-Printers; Start-PrnDiag })
$ui.BtnPrnReset.Add_Click({
    if (-not (Confirm-Ui "Drucksystem komplett zurücksetzen?`n`n- Druckwarteschlange anhalten, alle Aufträge löschen`n- Druck-, Scanner- und Erkennungsdienste neu starten`n- Druckereinstellungen der Benutzer bleiben erhalten" 'Warning')) { return }
    try { Stop-Service Spooler -Force; Start-Sleep 2; Remove-Item (Join-Path $env:SystemRoot 'System32\spool\PRINTERS\*') -Force -ErrorAction SilentlyContinue; Set-Service Spooler -StartupType Automatic; Start-Service Spooler; foreach ($n in 'stisvc', 'FDResPub', 'fdPHost', 'SSDPSRV') { Restart-Service $n -Force -ErrorAction SilentlyContinue }; $ui.StatusText.Text = 'Drucksystem zurückgesetzt.' } catch { Show-UiError $_.Exception.Message }
    Update-Printers; Start-PrnDiag
})
$ui.BtnPrnCleanDrv.Add_Click({
    $used = @(Get-Printer -ErrorAction SilentlyContinue | ForEach-Object { $_.DriverName })
    $un = @(Get-PrinterDriver -ErrorAction SilentlyContinue | Where-Object { $used -notcontains $_.Name -and $_.Name -notmatch '^Microsoft|Remote Desktop|OneNote' })
    if (-not $un.Count) { $ui.StatusText.Text = 'Keine unbenutzten Druckertreiber.'; return }
    if (-not (Confirm-Ui ("{0} unbenutzte Druckertreiber entfernen?`n`n{1}" -f $un.Count, (($un | ForEach-Object { '  - ' + $_.Name }) -join "`n")))) { return }
    $n = 0; foreach ($d in $un) { try { Remove-PrinterDriver -Name $d.Name -RemoveFromDriverStore -ErrorAction Stop; $n++ } catch { try { Remove-PrinterDriver -Name $d.Name -ErrorAction Stop; $n++ } catch { } } }
    $ui.StatusText.Text = '{0} Druckertreiber entfernt.' -f $n; Update-Printers
})
$ui.BtnPrnTrouble.Add_Click({ Start-Process 'ms-settings:troubleshoot' })
$ui.BtnPrnScanApp.Add_Click({ try { Start-Process 'ms-windows-store://pdp/?productid=9WZDNCRFJ3PV' } catch { } })
$ui.BtnPrnWfs.Add_Click({ $f = Join-Path $env:SystemRoot 'System32\WFS.exe'; if (Test-Path $f) { Start-Process $f } else { Show-UiError 'Windows-Fax und -Scan ist nicht installiert (Optionale Features > "Windows-Fax und -Scan").' } })
$ui.BtnPrnWia.Add_Click({ try { Set-Service stisvc -StartupType Automatic; Restart-Service stisvc -Force; $ui.StatusText.Text = 'Scanner-Dienst neu gestartet.'; Update-Printers } catch { Show-UiError $_.Exception.Message } })
$ui.Tabs.Add_SelectionChanged({ param($s, $e) if ($e.OriginalSource -eq $s -and $s.SelectedItem -eq $ui.TabPrinter) { try { Update-Printers } catch { }; if (-not $ui.PrnDiagGrid.ItemsSource) { Start-PrnDiag } } })

