$NsLevelText = @('hoch', 'mittel', 'Hinweis', 'OK')
function Get-LocalNetFindings {
    $o = [System.Collections.Generic.List[object]]::new()
    function F($rank, $area, $title, $detail, $fix = '', $fixText = '', $arg = '') { $o.Add([pscustomobject]@{ Rank = $rank; Area = $area; Title = $title; Detail = $detail; Fix = $fix; FixText = $fixText; Arg = $arg }) }
    foreach ($p in @(Get-NetFirewallProfile -ErrorAction SilentlyContinue)) { if ([string]$p.Enabled -ne 'True') { F 0 'Dieser PC' ('Firewall aus ({0})' -f $p.Name) 'Jeder im Netz kann offene Dienste dieses PCs erreichen.' 'Firewall' 'Firewall einschalten' $p.Name } }
    if (-not @($o | Where-Object Fix -eq 'Firewall').Count) { F 3 'Dieser PC' 'Firewall' 'für alle Netzwerke an' }
    foreach ($c in @(Get-NetConnectionProfile -ErrorAction SilentlyContinue)) { F $(if ([string]$c.NetworkCategory -eq 'Private') { 2 } else { 3 }) 'Dieser PC' ('Netzwerkprofil "{0}": {1}' -f $c.Name, $(if ([string]$c.NetworkCategory -eq 'Private') { 'Privat' } elseif ([string]$c.NetworkCategory -eq 'Public') { 'Öffentlich' } else { $c.NetworkCategory })) $(if ([string]$c.NetworkCategory -eq 'Private') { 'Privat erlaubt Freigaben und Netzwerkerkennung - richtig zu Hause, falsch in Hotel/Café.' } else { 'Öffentlich ist die sichere Einstellung (Freigaben und Erkennung aus).' }) $(if ([string]$c.NetworkCategory -eq 'Private') { 'Public' } else { 'Private' }) $(if ([string]$c.NetworkCategory -eq 'Private') { 'Auf Öffentlich stellen' } else { 'Auf Privat stellen (nur Heimnetz)' }) ([string]$c.InterfaceIndex) }
    try { $s1 = (Get-SmbServerConfiguration -ErrorAction Stop).EnableSMB1Protocol; $c1 = (Get-WindowsOptionalFeature -Online -FeatureName SMB1Protocol -ErrorAction SilentlyContinue).State; if ($s1 -or [string]$c1 -eq 'Enabled') { F 0 'Dieser PC' 'SMBv1 eingeschaltet' 'Veraltetes Freigabe-Protokoll (WannaCry-Lücke).' 'Smb1' 'SMBv1 entfernen' } else { F 3 'Dieser PC' 'SMBv1' 'aus' } } catch { }
    try { $sig = (Get-SmbServerConfiguration -ErrorAction Stop).RequireSecuritySignature; if (-not $sig) { F 2 'Dieser PC' 'SMB-Signierung nicht erzwungen' 'Schützt Freigaben vor Manipulation unterwegs. Windows 11 24H2 erzwingt sie standardmäßig.' 'SmbSign' 'Signierung erzwingen' } } catch { }
    $ll = (Get-ItemProperty 'HKLM:\SOFTWARE\Policies\Microsoft\Windows NT\DNSClient' -ErrorAction SilentlyContinue).EnableMulticast
    if ($ll -ne 0) { F 1 'Dieser PC' 'LLMNR an' 'Angreifer im selben Netz können Namensanfragen beantworten und Kennwort-Hashes abgreifen.' 'Llmnr' 'LLMNR ausschalten' } else { F 3 'Dieser PC' 'LLMNR' 'aus' }
    $nb = @(Get-CimInstance Win32_NetworkAdapterConfiguration -Filter 'IPEnabled=TRUE' -ErrorAction SilentlyContinue | Where-Object { $_.TcpipNetbiosOptions -ne 2 })
    if ($nb.Count) { F 1 'Dieser PC' 'NetBIOS über TCP/IP an' ('{0} Adapter - gleiche Gefahr wie LLMNR; nur für sehr alte Geräte nötig.' -f $nb.Count) 'Netbios' 'NetBIOS ausschalten' }
    $wpad = (Get-ItemProperty 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Internet Settings' -ErrorAction SilentlyContinue).AutoDetect
    if ($wpad -ne 0) { F 2 'Dieser PC' 'Proxy automatisch erkennen (WPAD) an' 'Im fremden Netz kann ein Angreifer sich als Proxy ausgeben. Zu Hause meist unnötig.' 'Wpad' 'Automatische Proxy-Erkennung aus' }
    $rdp = (Get-ItemProperty 'HKLM:\System\CurrentControlSet\Control\Terminal Server' -ErrorAction SilentlyContinue).fDenyTSConnections
    if ($rdp -eq 0) { $nla = (Get-ItemProperty 'HKLM:\System\CurrentControlSet\Control\Terminal Server\WinStations\RDP-Tcp' -ErrorAction SilentlyContinue).UserAuthentication; if ($nla -ne 1) { F 0 'Dieser PC' 'Remotedesktop ohne Netzwerkebenen-Authentifizierung' 'Anmeldebildschirm ist ohne vorherige Anmeldung erreichbar (BlueKeep-artige Angriffe).' 'Nla' 'NLA einschalten' } else { F 2 'Dieser PC' 'Remotedesktop an (mit NLA)' 'In Ordnung, wenn du ihn nutzt - starkes Kennwort verwenden.' 'RdpOff' 'Remotedesktop aus' } }
    $rr = Get-Service RemoteRegistry -ErrorAction SilentlyContinue; if ($rr -and ($rr.Status -eq 'Running' -or [string]$rr.StartType -eq 'Automatic')) { F 1 'Dieser PC' 'Remote-Registrierung aktiv' 'Erlaubt Zugriff auf die Registrierung über das Netz.' 'RemoteReg' 'Dienst ausschalten' }
    $g = Get-LocalUser -ErrorAction SilentlyContinue | Where-Object { $_.SID -like '*-501' -and $_.Enabled }; if ($g) { F 1 'Dieser PC' 'Gastkonto aktiv' 'Anmeldung ohne Kennwort möglich.' 'Guest' 'Gastkonto aus' }
    foreach ($s in @(Get-SmbShare -ErrorAction SilentlyContinue | Where-Object { $_.Name -notmatch '\$$' })) {
        $acc = @(Get-SmbShareAccess -Name $s.Name -ErrorAction SilentlyContinue | Where-Object { $_.AccountName -match 'Jeder|Everyone|Gast|Guest' -and $_.AccessControlType -eq 'Allow' })
        if ($acc.Count) { F $(if (@($acc | Where-Object AccessRight -in 'Full', 'Change').Count) { 0 } else { 1 }) 'Dieser PC' ('Freigabe "{0}" für Jeden' -f $s.Name) ('{0} - Recht: {1}' -f $s.Path, (($acc | ForEach-Object { $_.AccessRight }) -join ', ')) 'ShareMgr' 'Freigabe prüfen' } else { F 2 'Dieser PC' ('Freigabe "{0}"' -f $s.Name) $s.Path }
    }
    $risky = @{ 21 = 'FTP'; 23 = 'Telnet'; 3389 = 'Remotedesktop'; 5900 = 'VNC'; 3306 = 'MySQL'; 5432 = 'PostgreSQL'; 1433 = 'SQL Server'; 6379 = 'Redis'; 27017 = 'MongoDB'; 8080 = 'Webserver'; 80 = 'Webserver'; 1883 = 'MQTT'; 22 = 'SSH' }
    foreach ($l in @(Get-NetTCPConnection -State Listen -ErrorAction SilentlyContinue | Where-Object { $_.LocalAddress -in '0.0.0.0', '::' -and $risky.ContainsKey([int]$_.LocalPort) } | Sort-Object LocalPort -Unique)) {
        $pn = ''; try { $pn = (Get-Process -Id $l.OwningProcess -ErrorAction Stop).ProcessName } catch { }
        F $(if ([int]$l.LocalPort -in 23, 5900, 6379, 27017) { 0 } else { 1 }) 'Dieser PC' ('Anschluss {0} ({1}) offen' -f $l.LocalPort, $risky[[int]$l.LocalPort]) ('Programm: {0}. Wenn nicht gebraucht: Programm beenden/deinstallieren oder den Anschluss sperren.' -f $pn) 'Block' 'Eingehend sperren' ([string]$l.LocalPort)
    }
    $wl = (& netsh.exe wlan show interfaces 2>$null) -join "`n"
    if ($wl -match '(?m)^\s*(Authentifizierung|Authentication)\s*:\s*(.+)$') { $au = $Matches[2].Trim(); F $(if ($au -match 'Offen|Open|WEP') { 0 } elseif ($au -match 'WPA3') { 3 } elseif ($au -match 'WPA2') { 2 } else { 1 }) 'WLAN' ('Verbundenes WLAN: {0}' -f $au) $(if ($au -match 'Offen|Open') { 'Unverschlüsselt - jeder in der Nähe kann mitlesen. Nur mit VPN nutzen.' } elseif ($au -match 'WEP') { 'WEP ist in Minuten geknackt - im Router auf WPA2/WPA3 umstellen.' } elseif ($au -match 'WPA3') { 'Beste verfügbare Verschlüsselung.' } else { 'WPA2 ist in Ordnung - wenn Router und Geräte es können, auf WPA2/WPA3-Mischbetrieb umstellen.' }) }
    foreach ($pf in @((& netsh.exe wlan show profiles 2>$null) | Where-Object { $_ -match ':\s*(.+)$' -and $_ -match 'Profil|Profile' } | ForEach-Object { ($_ -split ':', 2)[1].Trim() })) {
        $d = (& netsh.exe wlan show profile name="$pf" 2>$null) -join "`n"
        if ($d -match '(?m)(Authentifizierung|Authentication)\s*:\s*(Offen|Open)' -and $d -match '(?m)(Verbindungsmodus|Connection mode)\s*:\s*(Automatisch|Connect automatically)') { F 1 'WLAN' ('Offenes WLAN "{0}" verbindet automatisch' -f $pf) 'Angreifer können ein gleichnamiges Netz aufspannen - der PC verbindet sich dann selbst.' 'ForgetWifi' 'WLAN vergessen' $pf }
    }
    try { $mp = Get-MpPreference -ErrorAction Stop; if ($mp.EnableNetworkProtection -ne 1) { F 2 'Dieser PC' 'Defender-Netzwerkschutz aus' 'Blockiert Verbindungen zu bekannten Schad- und Betrugsseiten in allen Programmen.' 'NetProt' 'Netzwerkschutz an' } } catch { }
    return , $o
}
function Invoke-LanScan([string[]]$Extra) {
    $ports = @(21, 22, 23, 53, 80, 135, 139, 443, 445, 554, 631, 1433, 1883, 2323, 3000, 3306, 3389, 5000, 5001, 5432, 5800, 5900, 6379, 7547, 8000, 8080, 8123, 8443, 9100, 9200, 11211, 27017)
    $nets = @(Get-NetIPAddress -AddressFamily IPv4 -ErrorAction SilentlyContinue | Where-Object { $_.IPAddress -notlike '127.*' -and $_.IPAddress -notlike '169.254*' -and $_.PrefixLength -ge 16 -and $_.PrefixLength -le 30 -and $_.IPAddress -match '^(10\.|192\.168\.|172\.(1[6-9]|2\d|3[01])\.)' } | Select-Object -First 2)
    $gw = @(Get-NetRoute -DestinationPrefix '0.0.0.0/0' -ErrorAction SilentlyContinue | Sort-Object RouteMetric | ForEach-Object { $_.NextHop } | Where-Object { $_ -ne '0.0.0.0' })[0]
    $hosts = [System.Collections.Generic.List[string]]::new()
    foreach ($n in $nets) {
        $pre = ($n.IPAddress -split '\.')[0..2] -join '.'
        $pings = @(); for ($i = 1; $i -lt 255; $i++) { $pg = New-Object Net.NetworkInformation.Ping; $pings += [pscustomobject]@{ Ip = "$pre.$i"; T = $pg.SendPingAsync("$pre.$i", 800) } }
        Start-Sleep -Milliseconds 1500
        foreach ($p in $pings) { if ($p.T.Status -eq 'RanToCompletion' -and $p.T.Result.Status -eq 'Success' -and -not $hosts.Contains($p.Ip)) { $hosts.Add($p.Ip) } }
    }
    $arp = @{}; foreach ($x in @(Get-NetNeighbor -AddressFamily IPv4 -ErrorAction SilentlyContinue | Where-Object { $_.State -in 'Reachable', 'Stale', 'Delay', 'Probe', 'Permanent' -and $_.LinkLayerAddress -and $_.LinkLayerAddress -notmatch '^(00-00-00|FF-FF-FF|01-00-5E)' })) { $arp[$x.IPAddress] = $x.LinkLayerAddress; if ($x.IPAddress -match '^(10\.|192\.168\.|172\.)' -and -not $hosts.Contains($x.IPAddress) -and $x.IPAddress -notmatch '\.255$') { $hosts.Add($x.IPAddress) } }
    $me = @($nets | ForEach-Object { $_.IPAddress })
    $res = [System.Collections.Generic.List[object]]::new()
    $list = @($hosts | Where-Object { $me -notcontains $_ })
    for ($b = 0; $b -lt $list.Count; $b += 16) {
        $batch = $list[$b..([math]::Min($b + 15, $list.Count - 1))]; $tasks = @()
        foreach ($h in $batch) { foreach ($pt in $ports) { $c = New-Object Net.Sockets.TcpClient; $tasks += [pscustomobject]@{ Ip = $h; Port = $pt; C = $c; T = $c.ConnectAsync($h, $pt) } } }
        Start-Sleep -Milliseconds 1300
        $open = @{}; foreach ($t in $tasks) { if ($t.T.Status -eq 'RanToCompletion' -and $t.C.Connected) { if (-not $open.ContainsKey($t.Ip)) { $open[$t.Ip] = @() }; $open[$t.Ip] += $t.Port }; try { $t.C.Close() } catch { } }
        foreach ($h in $batch) { $res.Add([pscustomobject]@{ Ip = $h; Mac = [string]$arp[$h]; Ports = @($open[$h] | Sort-Object); Gateway = ($h -eq $gw); Host = ''; Title = '' }) }
    }
    $dn = @{}; foreach ($r in $res) { $dn[$r.Ip] = [Net.Dns]::GetHostEntryAsync($r.Ip) }
    Start-Sleep -Milliseconds 1500
    foreach ($r in $res) { if ($dn[$r.Ip].Status -eq 'RanToCompletion') { $r.Host = $dn[$r.Ip].Result.HostName }
        if (@($r.Ports | Where-Object { $_ -in 80, 8080, 5000 }).Count) { $u = if ($r.Ports -contains 80) { "http://$($r.Ip)/" } elseif ($r.Ports -contains 8080) { "http://$($r.Ip):8080/" } else { "http://$($r.Ip):5000/" }
            try { $w = Invoke-WebRequest -Uri $u -UseBasicParsing -TimeoutSec 3 -ErrorAction Stop; if ($w.Content -match '<title>\s*([^<]{2,80})</title>') { $r.Title = $Matches[1].Trim() } elseif ($w.Headers.Server) { $r.Title = [string]$w.Headers.Server } } catch { } } }
    return [pscustomobject]@{ Devices = @($res); Gateway = $gw; Nets = @($nets | ForEach-Object { '{0}/{1}' -f $_.IPAddress, $_.PrefixLength }) }
}
function Invoke-NsFix($Row) {
    switch ($Row.Fix) {
        'Firewall' { Set-NetFirewallProfile -Profile $Row.Arg -Enabled True }
        'Public'   { Set-NetConnectionProfile -InterfaceIndex ([int]$Row.Arg) -NetworkCategory Public }
        'Private'  { Set-NetConnectionProfile -InterfaceIndex ([int]$Row.Arg) -NetworkCategory Private }
        'Smb1'     { $null = Invoke-UiWait { Set-SmbServerConfiguration -EnableSMB1Protocol $false -Force -ErrorAction SilentlyContinue; $null = Disable-WindowsOptionalFeature -Online -FeatureName SMB1Protocol -NoRestart -ErrorAction SilentlyContinue; 'ok' } @() @() 900 'SMB1 wird abgeschaltet ...' }
        'SmbSign'  { Set-SmbServerConfiguration -RequireSecuritySignature $true -Force }
        'Llmnr'    { Set-PReg 'HKLM:\SOFTWARE\Policies\Microsoft\Windows NT\DNSClient' 'EnableMulticast' 0 }
        'Netbios'  { foreach ($a in @(Get-CimInstance Win32_NetworkAdapterConfiguration -Filter 'IPEnabled=TRUE')) { $null = Invoke-CimMethod -InputObject $a -MethodName SetTcpipNetbios -Arguments @{ TcpipNetbiosOptions = [uint32]2 } } }
        'Wpad'     { Set-PReg 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Internet Settings' 'AutoDetect' 0 }
        'Nla'      { Set-PReg 'HKLM:\System\CurrentControlSet\Control\Terminal Server\WinStations\RDP-Tcp' 'UserAuthentication' 1 }
        'RdpOff'   { Set-PReg 'HKLM:\System\CurrentControlSet\Control\Terminal Server' 'fDenyTSConnections' 1 }
        'RemoteReg' { Stop-Service RemoteRegistry -Force -ErrorAction SilentlyContinue; Set-Service RemoteRegistry -StartupType Disabled }
        'Guest'    { Get-LocalUser | Where-Object { $_.SID -like '*-501' } | Disable-LocalUser }
        'ShareMgr' { Start-Process fsmgmt.msc }
        'Block'    { New-NetFirewallRule -DisplayName ('PC-Tools Sperre Anschluss ' + $Row.Arg) -Direction Inbound -Protocol TCP -LocalPort ([int]$Row.Arg) -Action Block | Out-Null }
        'ForgetWifi' { $null = & netsh.exe wlan delete profile name="$($Row.Arg)" }
        'NetProt'  { Set-MpPreference -EnableNetworkProtection Enabled }
        'Web'      { Start-Process $Row.Arg }
        'Upnp'     { Start-Process $Row.Arg }
    }
}
function Update-NsFilter {
    if (-not $script:NsRows) { return }
    $all = [bool]($ui.NsFilter.SelectedIndex -eq 1); $q = $ui.NsSearch.Text.Trim()
    Set-GridFilter $ui.NsGrid { param($x) ($all -or $x.Rank -le 2) -and (-not $q -or $x.Title -match [regex]::Escape($q) -or $x.Detail -match [regex]::Escape($q) -or $x.Area -match [regex]::Escape($q)) }.GetNewClosure()
}
function Show-NsResult {
    $rows = @($script:NsRows | Sort-Object Rank, Area, Title)
    foreach ($r in $rows) { $r | Add-Member -NotePropertyName LevelText -NotePropertyValue $NsLevelText[[int]$r.Rank] -Force }
    Set-GridItems $ui.NsGrid $rows; Update-NsFilter
    $c = @(0, 0, 0, 0); foreach ($r in $rows) { $c[[int]$r.Rank]++ }
    $ui.NsS0.Text = [string]$c[0]; $ui.NsS1.Text = [string]$c[1]; $ui.NsS2.Text = [string]$c[2]; $ui.NsS3.Text = [string]$c[3]; $ui.NsDev.Text = [string]@($script:NsDevices).Count
}
function Start-NsScan {
    $script:NsRows = [System.Collections.Generic.List[object]]::new(); $script:NsDevices = @()
    $ui.NsProgress.Visibility = 'Visible'; $ui.NsProgress.IsIndeterminate = $true; $ui.BtnNsScan.IsEnabled = $false
    $ui.NsInfo.Text = 'Prüfe ...'
    if ($ui.NsLocal.IsChecked -or $ui.NsWifi.IsChecked) { try { foreach ($f in (Get-LocalNetFindings)) { if ($f.Area -eq 'WLAN' -and -not $ui.NsWifi.IsChecked) { continue }; if ($f.Area -ne 'WLAN' -and -not $ui.NsLocal.IsChecked) { continue }; $script:NsRows.Add($f) } } catch { } }
    Show-NsResult
    $script:NsPending = 0
    if ($ui.NsLan.IsChecked -or $ui.NsRouter.IsChecked) {
        $script:NsPending++; $ui.NsInfo.Text = 'Suche Geräte im Netz und prüfe deren Anschlüsse (bis zu 2 Minuten) ...'
        Invoke-Bg -Script { Invoke-LanScan } -Functions @('Invoke-LanScan') -Done {
            param($r, $err)
            $x = @($r | Where-Object { $_ -and $_.Devices -ne $null })[0]
            if ($err -or -not $x) { $ui.NsInfo.Text = 'Netzwerk-Scan: ' + $(if ($err) { $err.Message } else { 'kein Ergebnis' }) }
            else {
                $script:NsGateway = $x.Gateway
                $devs = foreach ($d in @($x.Devices)) {
                    $risk = 3; $kind = if ($d.Gateway) { 'Router' } elseif (@($d.Ports | Where-Object { $_ -in 9100, 631 }).Count) { 'Drucker' } elseif ($d.Ports -contains 554) { 'Kamera' } elseif ($d.Ports -contains 8123) { 'Home Assistant' } elseif ($d.Ports -contains 5000 -or $d.Ports -contains 5001) { 'NAS' } elseif ($d.Ports -contains 3389 -or $d.Ports -contains 135) { 'Windows-PC' } elseif ($d.Ports -contains 1883) { 'MQTT-Broker' } elseif (-not @($d.Ports).Count) { 'Gerät (keine offenen Anschlüsse)' } else { 'Gerät' }
                    if ($d.Title) { $kind += ' - ' + $d.Title }
                    if ($d.Gateway -and -not $ui.NsRouter.IsChecked) { } elseif (-not $d.Gateway -and -not $ui.NsLan.IsChecked) { } else {
                        foreach ($p in @($d.Ports)) {
                            $rule = $NsPortRules[[int]$p]; if (-not $rule) { continue }
                            $rank = [int]$rule[0]
                            if ($p -in 80, 8080 -and ($d.Ports -contains 443 -or $d.Ports -contains 8443)) { $rank = 3 }
                            if ($p -in 135, 139, 445 -and -not $d.Gateway) { $rank = 3 }
                            if ($d.Gateway -and $p -in 445, 139, 21, 22, 23) { $rank = [math]::Min($rank, 1) }
                            if ($rank -lt $risk) { $risk = $rank }
                            if ($rank -le 2) { $script:NsRows.Add([pscustomobject]@{ Rank = $rank; Area = $(if ($d.Gateway) { 'Router' } else { 'Gerät im Netz' }); Title = ('{0}: {1}' -f $(if ($d.Host) { $d.Host } else { $d.Ip }), $rule[1]); Detail = ('{0}, Anschluss {1}. {2}' -f $d.Ip, $p, $rule[2]); Fix = $(if ($p -in 80, 8080, 443, 5000) { 'Web' } else { '' }); FixText = $(if ($p -in 80, 8080, 443, 5000) { 'Weboberfläche öffnen' } else { 'am Gerät abschalten' }); Arg = $(if ($p -eq 8080) { "http://$($d.Ip):8080/" } elseif ($p -eq 5000) { "http://$($d.Ip):5000/" } else { "http://$($d.Ip)/" }) }) }
                        }
                    }
                    [pscustomobject]@{ Ip = $d.Ip; Host = $d.Host; Mac = $d.Mac; Kind = $kind; Ports = (@($d.Ports) -join ', '); Risk = $NsLevelText[$risk]; Gateway = $d.Gateway; PortList = @($d.Ports) }
                }
                $script:NsDevices = @($devs | Sort-Object { try { [version]$_.Ip } catch { [version]'0.0' } })
                Set-GridItems $ui.NsDevGrid $script:NsDevices
                if ($x.Gateway -and $ui.NsRouter.IsChecked) { $gd = @($script:NsDevices | Where-Object Gateway)[0]; if ($gd -and $gd.PortList -contains 80 -and -not ($gd.PortList -contains 443)) { $script:NsRows.Add([pscustomobject]@{ Rank = 2; Area = 'Router'; Title = 'Router-Oberfläche nur ohne HTTPS'; Detail = 'Anmeldung am Router unverschlüsselt. Starkes Router-Kennwort, Firmware aktuell halten, Fernzugriff aus dem Internet nur wenn nötig.'; Fix = 'Web'; FixText = 'Router öffnen'; Arg = "http://$($x.Gateway)/" }) }; $script:NsRows.Add([pscustomobject]@{ Rank = 2; Area = 'Router'; Title = 'Router-Firmware aktuell halten'; Detail = ('Router {0}: Im Menü nach Updates suchen, automatische Updates einschalten, WPS und Fernwartung ausschalten wenn ungenutzt.' -f $x.Gateway); Fix = 'Web'; FixText = 'Router öffnen'; Arg = "http://$($x.Gateway)/" }) }
                $ui.NsInfo.Text = 'Netz {0}: {1} Geräte gefunden.' -f ($x.Nets -join ', '), $script:NsDevices.Count
            }
            Show-NsResult; $script:NsPending--; if ($script:NsPending -le 0) { $ui.NsProgress.Visibility = 'Collapsed'; $ui.BtnNsScan.IsEnabled = $true; $ui.NsInfo.Text += '  Geprüft am ' + (Get-Date).ToString('dd.MM.yyyy HH:mm') + '.' }
        }
    }
    if ($ui.NsRouter.IsChecked) {
        $script:NsPending++
        Invoke-Bg -Script { Get-UpnpInfo } -Functions @('Get-UpnpInfo') -Done {
            param($r, $err)
            $x = @($r | Where-Object { $_ -and $_.PSObject.Properties['On'] })[0]
            if ($x -and $x.On) {
                Set-GridItems $ui.NsUpnpGrid @($x.Maps)
                $ui.NsUpnpInfo.Text = 'UPnP ist im Router {0} eingeschaltet. {1} Portfreigabe(n) von außen{2}.' -f $x.Router, @($x.Maps).Count, $(if ($x.Ext) { ', öffentliche Adresse ' + $x.Ext } else { '' })
                $script:NsRows.Add([pscustomobject]@{ Rank = $(if (@($x.Maps).Count) { 1 } else { 2 }); Area = 'Router'; Title = 'UPnP im Router an'; Detail = ('Geräte und Programme dürfen selbst Anschlüsse ins Internet öffnen. {0} Freigabe(n) aktiv. Wenn keine Spielkonsole/kein Programm es braucht: im Router ausschalten.' -f @($x.Maps).Count); Fix = 'Upnp'; FixText = 'Router öffnen'; Arg = $(if ($script:NsGateway) { "http://$($script:NsGateway)/" } else { 'http://192.168.178.1/' }) })
                foreach ($m in @($x.Maps)) { $rule = $NsPortRules[[int]$m.Ext]; $script:NsRows.Add([pscustomobject]@{ Rank = $(if ($rule -and [int]$rule[0] -le 1) { 0 } else { 1 }); Area = 'Router'; Title = ('Aus dem Internet erreichbar: Anschluss {0}/{1}' -f $m.Ext, $m.Proto); Detail = ('weitergeleitet an {0} ({1}){2}' -f $m.Int, $m.Desc, $(if ($rule) { ' - ' + $rule[1] } else { '' })); Fix = 'Upnp'; FixText = 'Im Router löschen'; Arg = $(if ($script:NsGateway) { "http://$($script:NsGateway)/" } else { '' }) }) }
            } else { $ui.NsUpnpInfo.Text = 'Kein Router mit UPnP gefunden - gut (UPnP aus) oder der Router antwortet nicht. Portfreigaben im Router von Hand prüfen.'; $script:NsRows.Add([pscustomobject]@{ Rank = 3; Area = 'Router'; Title = 'UPnP'; Detail = 'kein UPnP-Router gefunden' }) }
            Show-NsResult; $script:NsPending--; if ($script:NsPending -le 0) { $ui.NsProgress.Visibility = 'Collapsed'; $ui.BtnNsScan.IsEnabled = $true }
        }
    }
    if ($script:NsPending -le 0) { $ui.NsProgress.Visibility = 'Collapsed'; $ui.BtnNsScan.IsEnabled = $true; $ui.NsInfo.Text = 'Fertig.' }
}
$ui.BtnNsScan.Add_Click({ Start-NsScan })
$ui.NsFilter.Add_SelectionChanged({ param($s, $e) $e.Handled = $true; Update-NsFilter })
$ui.NsSearch.Add_TextChanged({ Update-NsFilter })
$ui.BtnNsFix.Add_Click({
    $sel = @($ui.NsGrid.SelectedItems | Where-Object { $_.Fix }); if (-not $sel.Count) { Show-UiError 'Bitte Befunde mit Lösung markieren.'; return }
    if (-not (Confirm-Ui ("Beheben:`n`n{0}" -f (($sel | ForEach-Object { '  - {0}: {1}' -f $_.Title, $_.FixText }) -join "`n")))) { return }
    $err = @(); foreach ($r in $sel) { try { Invoke-NsFix $r } catch { $err += $r.Title + ': ' + $_.Exception.Message } }
    if ($err) { Show-UiError ($err -join "`n") } else { $ui.StatusText.Text = 'Erledigt - manches wirkt erst nach einem Neustart. Danach erneut prüfen.' }
})
$ui.BtnNsFixAll.Add_Click({
    $auto = @($script:NsRows | Where-Object { $_.Rank -le 2 -and $_.Fix -in 'Firewall', 'Smb1', 'Llmnr', 'Netbios', 'Nla', 'RemoteReg', 'Guest', 'ForgetWifi', 'NetProt', 'SmbSign' })
    if (-not $auto.Count) { Show-UiError 'Nichts automatisch zu beheben (Router- und Gerätebefunde muss man am Gerät selbst ändern).'; return }
    if (-not (Confirm-Ui ("{0} Befunde automatisch beheben?`n`n{1}`n`nHinweis: Ohne NetBIOS/LLMNR finden sehr alte Geräte (z.B. NAS vor 2015) diesen PC evtl. nicht mehr per Name - dann per IP-Adresse verbinden." -f $auto.Count, (($auto | ForEach-Object { '  - ' + $_.Title }) -join "`n")))) { return }
    foreach ($r in $auto) { try { Invoke-NsFix $r } catch { } }
    $ui.StatusText.Text = 'Behoben - einige Änderungen wirken nach dem Neustart.'; Start-NsScan
})
$ui.BtnNsRouterWeb.Add_Click({ $gw = if ($script:NsGateway) { $script:NsGateway } else { @(Get-NetRoute -DestinationPrefix '0.0.0.0/0' -ErrorAction SilentlyContinue | Sort-Object RouteMetric | ForEach-Object { $_.NextHop })[0] }; if ($gw) { Start-Process ('http://{0}/' -f $gw) } })
$ui.BtnNsDevWeb.Add_Click({ $d = $ui.NsDevGrid.SelectedItem; if ($d) { Start-Process $(if ($d.PortList -contains 443) { "https://$($d.Ip)/" } elseif ($d.PortList -contains 8080) { "http://$($d.Ip):8080/" } else { "http://$($d.Ip)/" }) } })
$ui.BtnNsDevCopy.Add_Click({ if ($script:NsDevices) { Set-Clipboard -Value (($script:NsDevices | ForEach-Object { "{0}`t{1}`t{2}`t{3}`t{4}" -f $_.Ip, $_.Host, $_.Mac, $_.Kind, $_.Ports }) -join "`r`n"); $ui.StatusText.Text = 'Geräteliste kopiert.' } })
$ui.BtnNsReport.Add_Click({
    if (-not $script:NsRows) { Show-UiError 'Zuerst "Netzwerk jetzt prüfen".'; return }
    Add-Type -AssemblyName System.Windows.Forms
    $d = New-Object System.Windows.Forms.SaveFileDialog; $d.Filter = 'PDF (*.pdf)|*.pdf'; $d.FileName = ('Netzwerk-Sicherheit_{0:yyyy-MM-dd}.pdf' -f (Get-Date))
    if ($d.ShowDialog() -ne 'OK') { return }
    $E = { param($s) ConvertTo-HtmlText $s }
    $H = [System.Collections.Generic.List[string]]::new()
    $H.Add('<!DOCTYPE html><html lang="de"><head><meta charset="utf-8"><style>' + $ReportCss + '</style></head><body>')
    $H.Add(('<div class="hero"><h1>Netzwerk-Sicherheit</h1><small>geprüft von {0} am {1:dd.MM.yyyy HH:mm} &middot; {2} Geräte &middot; PC-Tools {3}</small></div>' -f (& $E $env:COMPUTERNAME), (Get-Date), @($script:NsDevices).Count, $AppVersion))
    $H.Add('<h2>Befunde</h2><table><tr><th>Risiko</th><th>Bereich</th><th>Befund</th><th>Details</th></tr>')
    foreach ($r in @($script:NsRows | Sort-Object Rank)) { $H.Add(('<tr><td class="{0}">{1}</td><td>{2}</td><td><b>{3}</b></td><td>{4}</td></tr>' -f @('bad', 'warn', 'muted', 'ok')[[int]$r.Rank], $NsLevelText[[int]$r.Rank], (& $E $r.Area), (& $E $r.Title), (& $E $r.Detail))) }
    $H.Add('</table><h2>Geräte im Netz</h2><table><tr><th>Adresse</th><th>Name</th><th>MAC</th><th>Gerät</th><th>Offene Anschlüsse</th></tr>')
    foreach ($x in @($script:NsDevices)) { $H.Add(('<tr><td>{0}</td><td>{1}</td><td>{2}</td><td>{3}</td><td>{4}</td></tr>' -f (& $E $x.Ip), (& $E $x.Host), (& $E $x.Mac), (& $E $x.Kind), (& $E $x.Ports))) }
    $H.Add('</table></body></html>')
    $window.Cursor = 'Wait'; try { $f = Convert-HtmlToPdf ($H -join "`n") $d.FileName; Start-Process $f } catch { Show-UiError $_.Exception.Message } finally { $window.Cursor = $null }
})
foreach ($x in @(@('TabPrinter', 'drucker scanner multifunktionsgerät treiber hp brother canon epson kyocera offline druckwarteschlange hängt spooler testseite scannen'), @('TabNetSec', 'netzwerk sicherheit schwachstellen scan offene ports router upnp portfreigabe telnet smb llmnr netbios wlan verschlüsselung geräte im netz'))) {
    foreach ($e in $SearchIndex) { if ($ui[$x[0]] -and $e.Title -eq @($ui[$x[0]].Header.Children)[-1].Text) { $e.Keys += ' ' + $x[1] } }
}
Add-SearchEntry 'Drucker druckt nicht' 'Drucker und Scanner' 'druckprobleme offline hängt fehlerbehebung' '&#xE749;' { $ui.Tabs.SelectedItem = $ui.TabPrinter; Start-PrnDiag }
Add-SearchEntry 'Netzwerk auf Schwachstellen prüfen' 'Netzwerk-Sicherheit' 'scan schwachstellen ports' '&#xE72E;' { $ui.Tabs.SelectedItem = $ui.TabNetSec; Start-NsScan }
$ui.Tabs.Add_SelectionChanged({ param($s, $e) if ($e.OriginalSource -eq $s -and $s.SelectedItem -eq $ui.TabNetSec -and -not $script:NsRows) { $ui.NsInfo.Text = 'Bereit - "Netzwerk jetzt prüfen" klicken. Es werden nur Geräte im eigenen Netz geprüft, nichts wird verändert, bis du auf "beheben" klickst.' } })

# ---------------------------------------------------------------- Treiber-Seite: Update-Center, Details, Treiberspeicher, Verlauf, Sicherungen
$DrvBackupDir = Join-Path $DataDir 'Treiber-Sicherung'
function Update-DrvStats {
    $all = @($script:DrvAll)
    $ui.DrvS0.Text = [string]$all.Count; $ui.DrvS1.Text = [string]@($all | Where-Object { $_.Code -and $_.Code -ne 22 -and -not $_.Harmless }).Count; $ui.DrvS2.Text = [string]@($all | Where-Object { $_.Age -ge 3 -and -not $_.Inbox }).Count
    $b = @(Get-ChildItem $DrvBackupDir -Directory -ErrorAction SilentlyContinue | Sort-Object CreationTime -Descending)[0]
    $ui.DrvS4.Text = if ($b) { $b.CreationTime.ToString('dd.MM.') } else { 'nie' }
}
function Start-UcDrvScan {
    $ui.UcDrvProg.Visibility = 'Visible'; $ui.BtnUcDrvScan.IsEnabled = $false; $ui.UcDrvInfo.Text = 'Frage NVIDIA, Intel und Windows Update ab (1-3 Minuten) ...'; $ui.UcDrvGrid.ItemsSource = $null
    Invoke-Bg -Script {
        param($iw)
        $out = [System.Collections.Generic.List[object]]::new()
        foreach ($g in @(Get-GpuList)) {
            try {
                if ($g.Vendor -eq 'NVIDIA') { $l = Get-NvidiaLatest $g.Name; $newer = $false; try { $newer = [version]$l.Version -gt [version]$g.NvVersion } catch { }; if ($newer) { $out.Add([pscustomobject]@{ Source = 'NVIDIA'; Part = 'GpuDriver'; Id = ''; Name = $g.Name; Have = $g.NvVersion; New = $l.Version; Date = $l.Date; Size = ''; Note = 'direkt von NVIDIA'; Hot = $true }) } }
                elseif ($g.Vendor -eq 'Intel') { $o = Get-IntelGfxOffer $g; if ($o.Newer) { $out.Add([pscustomobject]@{ Source = 'Intel'; Part = 'IntelAll'; Id = ''; Name = $g.Name; Have = $g.DriverVersion; New = $o.Full; Date = ''; Size = ''; Note = 'Intel-Download-Center'; Hot = $true }) } }
            } catch { $out.Add([pscustomobject]@{ Source = $g.Vendor; Part = ''; Id = ''; Name = $g.Name; Have = $g.DriverVersion; New = '?'; Date = ''; Size = ''; Note = 'Abfrage nicht möglich: ' + $_.Exception.Message; Hot = $false }) }
        }
        $devs = @(Get-CimInstance Win32_PnPSignedDriver -ErrorAction SilentlyContinue | Where-Object { $_.Manufacturer -match 'Intel' -and $_.DeviceClass -in 'NET', 'BLUETOOTH' })
        foreach ($w in $iw) {
            $d = @($devs | Where-Object { $_.DeviceClass -eq $w.Class -and $_.DeviceName -match $w.Match })[0]; if (-not $d) { continue }
            try { $i = Get-IntelDownloadInfo $w.PageId $w.Pattern; $have = [string]$d.DriverVersion; $nv = [string]$i.Version
                  $newer = $false; try { $a = [version](($nv -split '\.')[0..2] -join '.'); $b = [version](($have -split '\.')[0..2] -join '.'); $newer = $a -gt $b } catch { }
                  if ($newer) { $out.Add([pscustomobject]@{ Source = 'Intel'; Part = 'IntelWireless'; Id = ''; Name = $d.DeviceName; Have = $have; New = $nv; Date = ''; Size = ''; Note = 'Intel-Download-Center'; Hot = $true }) } } catch { }
        }
        try {
            $s = New-Object -ComObject Microsoft.Update.Session; $r = $s.CreateUpdateSearcher().Search("IsInstalled=0 and IsHidden=0 and Type='Driver'")
            foreach ($u in $r.Updates) { $out.Add([pscustomobject]@{ Source = 'Windows Update'; Part = 'WUDrivers'; Id = [string]$u.Identity.UpdateID; Name = [string]$u.Title; Have = ''; New = [string]$u.DriverModel; Date = $(try { ([datetime]$u.DriverVerDate).ToString('dd.MM.yyyy') } catch { '' }); Size = ('{0:N1} MB' -f ($u.MaxDownloadSize / 1MB)); Note = $(if ($u.BrowseOnly) { 'optional' } else { 'empfohlen' }) + $(if ($u.DriverClass) { ', ' + $u.DriverClass } else { '' }); Hot = -not $u.BrowseOnly }) }
        } catch { $out.Add([pscustomobject]@{ Source = 'Windows Update'; Part = ''; Id = ''; Name = 'Suche fehlgeschlagen'; Have = ''; New = ''; Date = ''; Size = ''; Note = $_.Exception.Message; Hot = $false }) }
        return , $out
    } -Arguments @(, @(@{ Class = 'NET'; Match = 'Wi-?Fi|Wireless|WLAN'; PageId = 19351; Pattern = 'WiFi-[\d\.]+-Driver64-Win10-Win11\.exe' }, @{ Class = 'BLUETOOTH'; Match = 'Bluetooth'; PageId = 18649; Pattern = 'BT-[\d\.]+-64UWD-Win10-Win11\.exe' })) -Functions @('Get-GpuList', 'Get-NvidiaLatest', 'Get-IntelGfxPageId', 'Get-WebHtml', 'Get-IntelDownloadInfo', 'Get-IntelGfxOffer') -Done {
        param($r, $err)
        $ui.UcDrvProg.Visibility = 'Collapsed'; $ui.BtnUcDrvScan.IsEnabled = $true
        if ($err) { $ui.UcDrvInfo.Text = 'Suche fehlgeschlagen: ' + $err.Message; return }
        $script:UcDrv = @($r | ForEach-Object { $_ } | Where-Object { $_ -and $_.Name })
        Set-GridItems $ui.UcDrvGrid $script:UcDrv
        $n = @($script:UcDrv | Where-Object Part).Count; $ui.DrvS3.Text = [string]$n
        $ui.UcDrvInfo.Text = if ($n) { '{0} Treiber-Update(s) gefunden ({1:dd.MM.yyyy HH:mm}). Orange = empfohlen. Markieren (Strg/Umschalt) und "Markierte installieren".' -f $n, (Get-Date) } else { 'Alle Treiber sind aktuell - bei NVIDIA, Intel und Windows Update gibt es nichts Neueres ({0:dd.MM.yyyy HH:mm}).' -f (Get-Date) }
    }
}
function Install-UcDrv($Rows) {
    $rows = @($Rows | Where-Object Part); if (-not $rows.Count) { Show-UiError 'Nichts zu installieren - zuerst suchen bzw. Einträge markieren.'; return }
    $parts = @(); if ($ui.UcDrvBackup.IsChecked) { $parts += 'DriverBackup' }
    $parts += @($rows | ForEach-Object { $_.Part } | Select-Object -Unique)
    $ids = @($rows | Where-Object { $_.Part -eq 'WUDrivers' } | ForEach-Object { $_.Id })
    if (-not (Confirm-Ui ("{0} Treiber installieren?`n`n{1}`n`nVorher wird ein Wiederherstellungspunkt gesetzt{2}. Der Bildschirm kann kurz flackern." -f $rows.Count, (($rows | ForEach-Object { '  - {0}: {1}' -f $_.Source, $_.Name }) -join "`n"), $(if ($ui.UcDrvBackup.IsChecked) { ' und alle Treiber gesichert' } else { '' })))) { return }
    Start-Run -Parts $parts -Job @{ DriverIds = $ids }
}
$ui.BtnUcDrvScan.Add_Click({ Start-UcDrvScan })
$ui.BtnUcDrvInstall.Add_Click({ Install-UcDrv @($ui.UcDrvGrid.SelectedItems) })
$ui.BtnUcDrvAll.Add_Click({ Install-UcDrv @($script:UcDrv) })
$ui.DrvGrid.Add_SelectionChanged({
    param($s, $e)
    $r = $ui.DrvGrid.SelectedItem; if (-not $r) { return }
    $ui.DrvDName.Text = '{0}  ({1}, {2})' -f $r.Name, $r.ClassDe, $r.Maker
    $ui.DrvDVer.Text = '{0} vom {1} von {2}{3}' -f $r.Version, $r.Date, $r.Provider, $(if ($r.Signed) { ', signiert' } else { ', NICHT signiert' })
    $ui.DrvDInf.Text = $r.Inf; $ui.DrvDHw.Text = $r.HwId; $ui.DrvDDev.Text = $r.DevId + $(if ($u = Get-UsbDevInfo $r.DevId) { '   ->  ' + $u } else { '' })
    $ui.DrvDState.Text = if ($r.Code) { '{0} - {1}' -f $r.Status, (Get-CmErrorText $r.Code) } else { $r.Status }
})
function Get-CmErrorText([int]$c) {
    switch ($c) { 1 { 'nicht richtig konfiguriert' } 3 { 'Treiber beschädigt oder zu wenig Speicher' } 10 { 'Gerät kann nicht starten - Treiber neu installieren' } 12 { 'Ressourcenkonflikt' } 14 { 'Neustart nötig' } 18 { 'Treiber neu installieren' } 19 { 'Registrierung beschädigt' } 21 { 'wird entfernt' } 22 { 'deaktiviert' } 24 { 'Gerät nicht vorhanden oder fehlerhaft' } 28 { 'kein Treiber installiert' } 31 { 'Treiber passt nicht' } 32 { 'Dienst deaktiviert' } 37 { 'Treiber meldet Fehler beim Start' } 39 { 'Treiber beschädigt oder fehlt' } 43 { 'Gerät meldet Fehler (oft Hardware)' } 45 { 'Gerät nicht angeschlossen' } 48 { 'Treiber blockiert (Kompatibilität)' } 52 { 'Signatur ungültig' } default { 'siehe Geräte-Manager' } }
}
function Invoke-PnpDev([string]$Verb, [string]$Msg) {
    $r = $ui.DrvGrid.SelectedItem; if (-not $r) { Show-UiError 'Bitte zuerst in der Treiberliste ein Gerät anklicken.'; return }
    $o = (& (Join-Path $env:windir 'System32\pnputil.exe') $Verb $r.DevId 2>&1) -join ' '
    $ui.StatusText.Text = '{0}: {1}' -f $Msg, (($o -split '\s{2,}') | Select-Object -Last 1)
}
$ui.BtnDrvFixDev.Add_Click({
    $r = $ui.DrvGrid.SelectedItem
    if (-not $r) { $r = @($script:DrvAll | Where-Object { $_.Level -eq 'Error' }) | Select-Object -First 1; if ($r) { $ui.DrvGrid.SelectedItem = $r } }
    if (-not $r) { Show-UiError 'Kein Gerät mit Problem ausgewählt.'; return }
    $ui.StatusText.Text = ('Repariere "{0}" (bis zu 2 Minuten, Gerät ist kurz weg) ...' -f $r.Name); $ui.BtnDrvFixDev.IsEnabled = $false
    $script:DrvFixName = $r.Name
    Invoke-Bg -Script { param($i) Repair-PnpDevice $i } -Arguments @($r.DevId) -Functions @('Repair-PnpDevice', 'Invoke-NdCmd', 'Get-UsbDevInfo', 'Set-DevHarm', 'Get-DevHarmIds') -Done {
        param($x, $err)
        $ui.BtnDrvFixDev.IsEnabled = $true
        if ($err) { Show-UiError ('Reparatur: ' + $err.Message); return }
        $lines = @($x | ForEach-Object { [string]$_ }); $ok = $lines -contains '#FIXED'
        [Windows.MessageBox]::Show((T ((($lines | Where-Object { $_ -ne '#FIXED' }) -join "`n"))), (T (('PC-Tools - ' + $script:DrvFixName))), 'OK', $(if ($ok) { 'Information' } else { 'Warning' })) | Out-Null
        $ui.StatusText.Text = $(if ($ok) { $script:DrvFixName + ': erledigt.' } else { $script:DrvFixName + ': nicht automatisch behebbar - siehe Hinweis.' })
        Update-DrvInventory
    }
})
$ui.BtnDrvHarm.Add_Click({
    $r = $ui.DrvGrid.SelectedItem; if (-not $r) { Show-UiError 'Bitte zuerst ein Gerät anklicken.'; return }
    $on = -not ((Get-DevHarmIds) -contains $r.DevId)
    if ($on -and -not (Confirm-Ui ('"{0}" als harmlos ausblenden?{1}{1}Es zählt dann nicht mehr als Problem (Übersicht, Gerätezustand, Meine PCs). Sinnvoll für Anschlüsse ohne Gerät oder bekannte Meldungen, die nicht stören.' -f $r.Name, "`n"))) { return }
    Set-DevHarm $r.DevId $on; $ui.StatusText.Text = $(if ($on) { $r.Name + ' wird als harmlos ausgeblendet.' } else { $r.Name + ' wird wieder als Problem gezeigt.' }); Update-DrvInventory
})
$ui.BtnDrvRestartDev.Add_Click({ Invoke-PnpDev '/restart-device' 'Gerät neu gestartet'; Update-DrvInventory })
$ui.BtnDrvToggleDev.Add_Click({ $r = $ui.DrvGrid.SelectedItem; if (-not $r) { return }; if ($r.Code -eq 22) { Invoke-PnpDev '/enable-device' 'Aktiviert' } elseif (Confirm-Ui ('"{0}" deaktivieren?' -f $r.Name) 'Warning') { Invoke-PnpDev '/disable-device' 'Deaktiviert' }; Update-DrvInventory })
$ui.BtnDrvUninstDev.Add_Click({ $r = $ui.DrvGrid.SelectedItem; if (-not $r) { return }; if (Confirm-Ui ("Gerät ""{0}"" entfernen und sofort neu erkennen lassen? Windows installiert dabei den passenden Treiber neu (Tastatur/Maus/Netzwerk kurz weg)." -f $r.Name) 'Warning') { Invoke-PnpDev '/remove-device' 'Entfernt'; $null = & (Join-Path $env:windir 'System32\pnputil.exe') /scan-devices 2>&1; Start-Sleep 2; Update-DrvInventory } })
$ui.BtnDrvDelPkg.Add_Click({
    $r = $ui.DrvGrid.SelectedItem; if (-not $r) { return }
    if ($r.Inf -notmatch '^oem\d+\.inf$') { Show-UiError 'Das ist ein Windows-eigener Treiber - er lässt sich nicht löschen.'; return }
    if (-not (Confirm-Ui ("Treiberpaket {0} ({1}, {2}) aus Windows löschen?`n`nDas Gerät bekommt danach einen anderen passenden Treiber (älter oder Windows-Standard). Nur bei fehlerhaften Treibern sinnvoll." -f $r.Inf, $r.Provider, $r.Version) 'Warning')) { return }
    $o = (& (Join-Path $env:windir 'System32\pnputil.exe') /delete-driver $r.Inf /uninstall /force 2>&1) -join ' '; $null = & (Join-Path $env:windir 'System32\pnputil.exe') /scan-devices 2>&1
    $ui.StatusText.Text = 'pnputil: ' + $o; Update-DrvInventory
})
$ui.BtnDrvWuDev.Add_Click({ $r = $ui.DrvGrid.SelectedItem; if ($r) { $id = ($r.HwId -split '&REV_|\\\\')[0]; Set-Clipboard -Value $r.HwId; Start-Process ('https://www.catalog.update.microsoft.com/Search.aspx?q=' + [uri]::EscapeDataString($r.Name)) ; $ui.StatusText.Text = 'Microsoft-Update-Katalog geöffnet, Hardware-ID kopiert.' } })
$ui.BtnDrvDevMgr2.Add_Click({ Start-Process devmgmt.msc })
# Treiberspeicher
$ui.BtnDsLoad.Add_Click({
    $ui.DsInfo.Text = 'Lese Treiberspeicher ...'
    Invoke-Bg -Script {
        $use = @{}; foreach ($d in @(Get-CimInstance Win32_PnPSignedDriver -ErrorAction SilentlyContinue)) { if ($d.InfName) { $use[[string]$d.InfName] = $true } }
        $rows = foreach ($d in @(Get-WindowsDriver -Online -ErrorAction Stop)) {
            $dir = Split-Path ([string]$d.OriginalFileName); $size = 0; try { $size = (Get-ChildItem -LiteralPath $dir -Recurse -File -ErrorAction Stop | Measure-Object Length -Sum).Sum } catch { }
            [pscustomobject]@{ Oem = [string]$d.Driver; Orig = [IO.Path]::GetFileName([string]$d.OriginalFileName); Provider = [string]$d.ProviderName; Class = [string]$d.ClassName; Version = [string]$d.Version; DateObj = $d.Date; Date = $(try { ([datetime]$d.Date).ToString('dd.MM.yyyy') } catch { '' }); Size = [int64]$size; SizeText = ('{0:N1} MB' -f ($size / 1MB)); Dir = $dir; InUse = $use.ContainsKey([string]$d.Driver); State = ''; Hot = $false; Old = $false }
        }
        foreach ($g in @($rows | Group-Object { '{0}|{1}|{2}' -f $_.Orig, $_.Provider, $_.Class })) {
            $sorted = @($g.Group | Sort-Object { try { [version]$_.Version } catch { [version]'0.0' } } -Descending)
            for ($i = 0; $i -lt $sorted.Count; $i++) { $x = $sorted[$i]; if ($i -gt 0) { $x.Old = $true; $x.Hot = $true }; $x.State = '{0}{1}' -f $(if ($x.InUse) { 'in Benutzung' } else { 'nicht in Benutzung' }), $(if ($x.Old) { ', ältere Version (entfernbar)' } else { '' }) }
        }
        @($rows)
    } -Done {
        param($r, $err)
        if ($err) { $ui.DsInfo.Text = 'Nicht lesbar: ' + $err.Message; return }
        $script:DsRows = @($r | Where-Object { $_ -and $_.Oem } | Sort-Object Class, Orig, Version)
        Set-GridItems $ui.DsGrid $script:DsRows
        $old = @($script:DsRows | Where-Object Old)
        $ui.DsInfo.Text = '{0} Treiberpakete, zusammen {1:N0} MB. {2} ältere Versionen ({3:N0} MB) können entfernt werden.' -f $script:DsRows.Count, (($script:DsRows | Measure-Object Size -Sum).Sum / 1MB), $old.Count, (($old | Measure-Object Size -Sum).Sum / 1MB)
    }
})
function Remove-DsPackages($Rows) {
    $rows = @($Rows); if (-not $rows.Count) { return }
    if (-not (Confirm-Ui ("{0} Treiberpaket(e) entfernen?`n`n{1}" -f $rows.Count, (($rows | Select-Object -First 25 | ForEach-Object { '  - {0} {1} {2} ({3})' -f $_.Oem, $_.Provider, $_.Version, $_.State }) -join "`n")) 'Warning')) { return }
    $ok = 0; $fail = @()
    foreach ($x in $rows) { $o = (& (Join-Path $env:windir 'System32\pnputil.exe') /delete-driver $x.Oem 2>&1) -join ' '; if ($LASTEXITCODE -eq 0) { $ok++ } else { $fail += ('{0}: {1}' -f $x.Oem, (($o -split '\s{2,}') | Select-Object -Last 1)) } }
    $ui.StatusText.Text = '{0} Treiberpakete entfernt{1}.' -f $ok, $(if ($fail.Count) { ', {0} in Benutzung und übersprungen' -f $fail.Count } else { '' })
    $ui.BtnDsLoad.RaiseEvent((New-Object Windows.RoutedEventArgs ([Windows.Controls.Button]::ClickEvent)))
}
$ui.BtnDsOld.Add_Click({ Remove-DsPackages @($script:DsRows | Where-Object { $_.Old -and -not $_.InUse }) })
$ui.BtnDsDel.Add_Click({ $sel = @($ui.DsGrid.SelectedItems); if (@($sel | Where-Object InUse).Count -and -not (Confirm-Ui 'Darunter sind Treiber, die gerade benutzt werden - die werden übersprungen. Weiter?')) { return }; Remove-DsPackages @($sel | Where-Object { -not $_.InUse }) })
$ui.BtnDsOpen.Add_Click({ $r = $ui.DsGrid.SelectedItem; Start-Process explorer.exe $(if ($r) { '"{0}"' -f $r.Dir } else { (Join-Path $env:windir 'System32\DriverStore\FileRepository') }) })
# Verlauf
$ui.BtnDhLoad.Add_Click({
    Invoke-Bg -Script {
        foreach ($e in @(Get-WinEvent -FilterHashtable @{ LogName = 'System'; ProviderName = 'Microsoft-Windows-UserPnp'; Id = 20001, 20003; StartTime = (Get-Date).AddDays(-90) } -MaxEvents 300 -ErrorAction SilentlyContinue)) {
            $m = [string]$e.Message; $inf = if ($m -match '(oem\d+\.inf|\w+\.inf)') { $Matches[1] } else { '' }
            $dev = if ($m -match '\(([^)]{3,120})\)') { $Matches[1] } elseif ($m -match '(?:Geräteinstanz-ID|Device Instance ID)\s+(\S+)') { $Matches[1] } else { '' }
            $st = if ($m -match '0x([0-9A-Fa-f]+)\.?\s*$') { $Matches[1] } else { '' }
            [pscustomobject]@{ Time = $e.TimeCreated.ToString('dd.MM.yyyy HH:mm'); Device = $(if ($dev) { $dev } else { ($m -split "`n")[0] }); Inf = $inf; Result = $(if ($e.Id -eq 20003) { 'Dienst hinzugefügt' } elseif ($st -eq '0') { 'installiert' } elseif ($st) { 'Fehler 0x' + $st } else { 'installiert' }) }
        }
    } -Done { param($r, $err) Set-GridItems $ui.DhGrid @($r | Where-Object { $_ -and $_.Time }) }
})
# Sicherungen
function Update-DrvBackups {
    $rows = foreach ($d in @(Get-ChildItem $DrvBackupDir -Directory -ErrorAction SilentlyContinue | Sort-Object CreationTime -Descending)) { $f = @(Get-ChildItem $d.FullName -Recurse -File -ErrorAction SilentlyContinue); [pscustomobject]@{ Name = $d.Name; Date = $d.CreationTime.ToString('dd.MM.yyyy HH:mm'); Count = @($f | Where-Object Extension -eq '.inf').Count; SizeText = ('{0:N0} MB' -f (($f | Measure-Object Length -Sum).Sum / 1MB)); Path = $d.FullName } }
    Set-GridItems $ui.DbGrid @($rows); Update-DrvStats
}
$ui.BtnDbNew.Add_Click({ Start-Run -Parts @('DriverBackup') })
$ui.BtnDbOpen.Add_Click({ $r = $ui.DbGrid.SelectedItem; New-Item $DrvBackupDir -ItemType Directory -Force | Out-Null; Start-Process explorer.exe ('"{0}"' -f $(if ($r) { $r.Path } else { $DrvBackupDir })) })
$ui.BtnDbRestore.Add_Click({
    $r = $ui.DbGrid.SelectedItem; if (-not $r) { Show-UiError 'Bitte eine Sicherung wählen.'; return }
    if (-not (Confirm-Ui ("Alle {0} Treiber aus ""{1}"" zurückspielen?`nWindows übernimmt nur Treiber, die zu vorhandenen Geräten passen." -f $r.Count, $r.Name))) { return }
    $ui.StatusText.Text = 'Treiber werden zurückgespielt ...'; $window.Cursor = 'AppStarting'
    Invoke-Bg -Script { param($p) (& (Join-Path $env:windir 'System32\pnputil.exe') /add-driver (Join-Path $p '*.inf') /subdirs /install 2>&1) -join "`n" } -Arguments @($r.Path) -Done { param($x, $err) $window.Cursor = $null; $ui.StatusText.Text = 'Zurückgespielt: ' + ((@($x) -join ' ' -split "`n" | Where-Object { $_ -match '\d' } | Select-Object -Last 2) -join ' '); Update-DrvInventory }
})
