$ui.BtnDbDel.Add_Click({ $r = $ui.DbGrid.SelectedItem; if ($r -and (Confirm-Ui ('Sicherung "{0}" löschen?' -f $r.Name))) { Remove-Item -LiteralPath $r.Path -Recurse -Force -ErrorAction SilentlyContinue; Update-DrvBackups } })
