# ---------------------------------------------------------------- Update-Seite: Stand, Programm-Updates, Windows-Updates, Verlauf
function Update-UpStatus {
    $reg = Get-ItemProperty 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion'
    $ui.UpWin.Text = '{0} {1} (Build {2}.{3})' -f ((Get-CimInstance Win32_OperatingSystem).Caption -replace '^Microsoft ', ''), $reg.DisplayVersion, $reg.CurrentBuild, $reg.UBR
    try { $au = (New-Object -ComObject Microsoft.Update.AutoUpdate).Results; $ui.UpWu.Text = 'letzte Suche {0}, letzte Installation {1}' -f $(if ($au.LastSearchSuccessDate) { ([datetime]$au.LastSearchSuccessDate).ToLocalTime().ToString('dd.MM.yyyy HH:mm') } else { '-' }), $(if ($au.LastInstallationSuccessDate) { ([datetime]$au.LastInstallationSuccessDate).ToLocalTime().ToString('dd.MM.yyyy HH:mm') } else { '-' }) } catch { $ui.UpWu.Text = '-' }
    $last = $null; try { $last = (Get-HotFix -ErrorAction Stop | Where-Object InstalledOn | Sort-Object InstalledOn -Descending | Select-Object -First 1).InstalledOn } catch { }
    $ui.UpS2.Text = $(if ($last) { [string][int]((Get-Date) - $last).TotalDays } else { '?' })
    $pend = (Test-Path 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Component Based Servicing\RebootPending') -or (Test-Path 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\WindowsUpdate\Auto Update\RebootRequired')
    $ui.UpS3.Text = $(if ($pend) { 'ja' } else { 'nein' })
    $c2r = Get-ItemProperty 'HKLM:\SOFTWARE\Microsoft\Office\ClickToRun\Configuration' -ErrorAction SilentlyContinue
    $ui.UpOffice.Text = if ($c2r) { $ch = switch -Regex ([string]$c2r.CDNBaseUrl + [string]$c2r.UpdateChannel) { '492350f6' { 'Aktueller Kanal' } '55336b82' { 'Monatlicher Enterprise-Kanal' } '7ffbc6bf' { 'Halbjährlicher Enterprise-Kanal' } '64256afe' { 'Aktueller Kanal (Vorschau)' } '5440fd1f' { 'Beta-Kanal' } default { 'Kanal unbekannt' } }; '{0}, Version {1} ({2}), automatische Updates {3}' -f ([string]$c2r.ProductReleaseIds -replace ',', ', '), $c2r.VersionToReport, $ch, $(if ($c2r.UpdatesEnabled -eq 'False') { 'AUS' } else { 'an' }) } else { 'nicht installiert (oder MSI-Version)' }
    try { $mp = Get-MpComputerStatus -ErrorAction Stop; $ui.UpDef.Text = 'Version {0} vom {1:dd.MM.yyyy HH:mm} ({2} Tage alt), Engine {3}' -f $mp.AntivirusSignatureVersion, $mp.AntivirusSignatureLastUpdated, $mp.AntivirusSignatureAge, $mp.AMEngineVersion } catch { $ui.UpDef.Text = 'Defender nicht aktiv (anderer Virenschutz)' }
    $ai = Get-AppxPackage Microsoft.DesktopAppInstaller -ErrorAction SilentlyContinue; $ui.UpWinget.Text = if ($ai) { 'App-Installer {0}' -f $ai.Version } else { 'fehlt - im Microsoft Store "App-Installer" installieren' }
    $ui.UpPflege.Text = 'Version {0}{1}' -f $AppVersion, $(if ($script:UpdManifest -and (Test-NewerVersion $script:UpdManifest.Version $AppVersion)) { ' - neue Version {0} verfügbar' -f $script:UpdManifest.Version } else { ' - aktuell' })
}
function Start-UpAppScan {
    $ui.UpAppInfo.Text = 'Frage winget nach neuen Versionen (ca. 20-60 Sekunden) ...'; $ui.BtnUpAppScan.IsEnabled = $false
    Invoke-Bg -Script { param($u) $wg = Get-WingetPathX; if (-not $wg) { throw 'winget fehlt.' }; $a = @('upgrade', '--accept-source-agreements', '--disable-interactivity'); if ($u) { $a += '--include-unknown' }
        $raw = & $wg @a 2>$null; $lines = @($raw | ForEach-Object { ([string]$_ -split "`r")[-1] })
        $hdr = -1; for ($i = 0; $i -lt $lines.Count; $i++) { if ($lines[$i] -match '^\s*Name\s+ID\s+Version' -and $i + 1 -lt $lines.Count -and $lines[$i + 1] -match '^-{10,}') { $hdr = $i; break } }
        if ($hdr -lt 0) { return @() }
        $h = $lines[$hdr]; $cId = $h.IndexOf('ID'); $cVer = $h.IndexOf('Version'); $m = [regex]::Match($h, 'Verfügbar|Available'); $cAv = if ($m.Success) { $m.Index } else { -1 }; $m2 = [regex]::Match($h, 'Quelle|Source'); $cSrc = if ($m2.Success) { $m2.Index } else { $h.Length }
        foreach ($l in $lines[($hdr + 2)..($lines.Count - 1)]) {
            if (-not $l.Trim() -or $l.Length -lt $cVer -or $l -match '^\d+ (Aktualisierung|upgrade|Paket|package)' -or $l -match '^-{5,}') { continue }
            $name = $l.Substring(0, $cId).Trim(); $id = ($l.Substring($cId, [math]::Max(0, $cVer - $cId)).Trim() -split '\s+')[0]
            $ver = if ($cAv -gt 0 -and $l.Length -gt $cAv) { $l.Substring($cVer, $cAv - $cVer).Trim() } else { ($l.Substring($cVer).Trim() -split '\s+')[0] }
            $av = if ($cAv -gt 0 -and $l.Length -gt $cAv) { ($l.Substring($cAv, [math]::Max(0, [math]::Min($l.Length, $cSrc) - $cAv)).Trim() -split '\s+')[0] } else { '' }
            if ($id -match '^[\w\.\-\+]+$') { [pscustomobject]@{ Name = $name; Id = $id; Version = $ver; Available = $av } }
        }
    } -Arguments @([bool]$ui.UpAppUnknown.IsChecked) -Functions @('Get-WingetPathX') -Done {
        param($r, $err)
        $ui.BtnUpAppScan.IsEnabled = $true
        if ($err) { $ui.UpAppInfo.Text = 'Suche fehlgeschlagen: ' + $err.Message; return }
        $excl = @(([string]$ui.Update_WingetExclude.Text) -split '[,;\s]+' | Where-Object { $_ })
        $sec = $VulnAlwaysUpdate
        $script:UpApps = @($r | Where-Object { $_ -and $_.Id } | ForEach-Object { $x = $_; $isEx = $excl -contains $x.Id; $isSec = $x.Name -match $sec
            [pscustomobject]@{ Name = $x.Name; Id = $x.Id; Version = $x.Version; Available = $x.Available; Excluded = $isEx; Hot = ($isSec -and -not $isEx); Note = $(if ($isEx) { 'ausgenommen' } elseif ($isSec) { 'Sicherheitsrelevant (Internet)' } elseif ($x.Version -match 'Unknown|Unbekannt|<') { 'Version unbekannt' } else { '' }) } } | Sort-Object @{ e = { -not $_.Hot } }, Name)
        Set-GridItems $ui.UpAppGrid $script:UpApps; Update-UpAppFilter
        $ui.UpS1.Text = [string]@($script:UpApps | Where-Object { -not $_.Excluded }).Count
        $ui.UpAppInfo.Text = '{0} Programme mit neuer Version ({1} sicherheitsrelevant, {2} ausgenommen) - Stand {3:HH:mm}.' -f $script:UpApps.Count, @($script:UpApps | Where-Object Hot).Count, @($script:UpApps | Where-Object Excluded).Count, (Get-Date)
    }
}
function Update-UpAppFilter { if (-not $script:UpApps) { return }; $q = $ui.UpAppSearch.Text.Trim(); Set-GridFilter $ui.UpAppGrid { param($x) -not $q -or $x.Name -match [regex]::Escape($q) -or $x.Id -match [regex]::Escape($q) }.GetNewClosure() }
function Set-UpExclude([string[]]$Ids, [bool]$Add) {
    $cur = [System.Collections.Generic.List[string]]::new(); foreach ($x in (([string]$ui.Update_WingetExclude.Text) -split '[,;\s]+' | Where-Object { $_ })) { $cur.Add($x) }
    foreach ($i in $Ids) { if ($Add -and -not $cur.Contains($i)) { $cur.Add($i) } elseif (-not $Add) { [void]$cur.Remove($i) } }
    $ui.Update_WingetExclude.Text = ($cur -join ', '); $null = Save-All -Quiet
    if (-not $Add) { $wg = Get-WingetPathX; if ($wg) { $null = Invoke-UiWait { param($w, $ids) foreach ($i in $ids) { $null = Invoke-NdCmd $w ('pin remove --id "{0}" --accept-source-agreements --disable-interactivity' -f $i) 60 }; 'ok' } @($wg, @($Ids)) @('Invoke-NdCmd') 300 'winget: Ausnahme wird entfernt ...' } }
    foreach ($a in @($script:UpApps)) { if ($Ids -contains $a.Id) { $a.Excluded = $Add; $a.Note = $(if ($Add) { 'ausgenommen' } else { '' }); $a.Hot = $false } }
    $ui.UpAppGrid.Items.Refresh()
}
