$ui.BtnUpWuScan.Add_Click({
    $ui.UpWuInfo.Text = 'Suche bei Windows Update (1-3 Minuten) ...'; $ui.BtnUpWuScan.IsEnabled = $false
    Invoke-Bg -Script {
        $s = New-Object -ComObject Microsoft.Update.Session; $r = $s.CreateUpdateSearcher().Search("IsInstalled=0 and IsHidden=0")
        foreach ($u in $r.Updates) { [pscustomobject]@{ Id = [string]$u.Identity.UpdateID; Title = [string]$u.Title; KB = (@($u.KBArticleIDs | ForEach-Object { 'KB' + $_ }) -join ', '); Kind = $(if ($u.Type -eq 2) { 'Treiber' } elseif ([string]$u.Title -match 'Funktionsupdate|Feature update|Windows 11, version') { 'Funktionsupdate' } elseif ([string]$u.Title -match 'Sicherheit|Security|Kumulativ|Cumulative') { 'Sicherheitsupdate' } elseif ([string]$u.Title -match 'Defender|Security Intelligence') { 'Virenschutz' } elseif ([string]$u.Title -match '\.NET') { '.NET' } else { 'Update' }); Size = ('{0:N0} MB' -f ($u.MaxDownloadSize / 1MB)); Reboot = $(if ($u.InstallationBehavior.RebootBehavior -gt 0) { 'ja' } else { '' }); Hot = ([string]$u.Title -match 'Sicherheit|Security|Kumulativ|Cumulative'); Optional = [bool]$u.BrowseOnly } }
    } -Done {
        param($r, $err)
        $ui.BtnUpWuScan.IsEnabled = $true
        if ($err) { $ui.UpWuInfo.Text = 'Suche fehlgeschlagen: ' + $err.Message; return }
        $script:UpWu = @($r | Where-Object { $_ -and $_.Id } | Sort-Object @{ e = { -not $_.Hot } }, Kind, Title)
        Set-GridItems $ui.UpWuGrid $script:UpWu; $ui.UpS0.Text = [string]$script:UpWu.Count
        $ui.UpWuInfo.Text = $(if ($script:UpWu.Count) { '{0} Updates verfügbar ({1} Sicherheitsupdates, orange).' -f $script:UpWu.Count, @($script:UpWu | Where-Object Hot).Count } else { 'Windows ist auf dem neuesten Stand.' })
    }
})
