$ui.BtnUpHist.Add_Click({
    Invoke-Bg -Script {
        param($dir)
        foreach ($f in @(Get-ChildItem $dir -Filter '*.log' -ErrorAction SilentlyContinue | Sort-Object LastWriteTime -Descending | Select-Object -First 30)) {
            $day = $f.LastWriteTime.ToString('dd.MM.yyyy')
            foreach ($l in @(Get-Content -LiteralPath $f.FullName -Encoding UTF8 -ErrorAction SilentlyContinue)) {
                if ($l -match '^(\d\d:\d\d):\d\d \[(OK|WARN|FEHLER)\s*\]\s+(\S.+?):\s+(aktualisiert.*|installiert.*|fehlgeschlagen.*|bereits aktuell.*|kein passendes Update)$') { [pscustomobject]@{ Time = '{0} {1}' -f $day, $Matches[1]; Name = $Matches[3].Trim(); Result = $Matches[4]; Src = 'Programme' } }
                elseif ($l -match '^(\d\d:\d\d):\d\d \[(OK|WARN|FEHLER)\s*\]\s+(installiert|FEHLER): (.+)$') { [pscustomobject]@{ Time = '{0} {1}' -f $day, $Matches[1]; Name = $Matches[4].Trim(); Result = $Matches[3]; Src = 'Windows Update' } }
                elseif ($l -match '^(\d\d:\d\d):\d\d \[OK\s*\]\s+(Intel.+installiert.*|NVIDIA-Treiber .+ installiert.*)$') { [pscustomobject]@{ Time = '{0} {1}' -f $day, $Matches[1]; Name = $Matches[2]; Result = 'installiert'; Src = 'Treiber' } }
            }
        }
    } -Arguments @((Join-Path $DataDir 'Logs')) -Done { param($r, $err) Set-GridItems $ui.UpHistGrid @($r | Where-Object { $_ -and $_.Name -and $_.Result -notmatch 'bereits aktuell|kein passendes' } | Select-Object -First 300) }
})
