$ui.BtnPrnSpoolReset.Add_Click({
    $ui.StatusText.Text = 'Druckwarteschlange wird bereinigt und neu gestartet ...'; $window.Cursor = 'Wait'
    try {
        $jobs = @(Get-Printer -ErrorAction SilentlyContinue | ForEach-Object { @(Get-PrintJob -PrinterName $_.Name -ErrorAction SilentlyContinue) }).Count
        Stop-Service Spooler -Force -ErrorAction Stop; Start-Sleep -Seconds 2
        $spool = Join-Path $env:SystemRoot 'System32\spool\PRINTERS'; $files = @(Get-ChildItem $spool -File -ErrorAction SilentlyContinue)
        $files | Remove-Item -Force -ErrorAction SilentlyContinue
        Set-Service Spooler -StartupType Automatic; Start-Service Spooler -ErrorAction Stop; Start-Sleep -Seconds 1
        $st = (Get-Service Spooler).Status
        $ui.StatusText.Text = 'Druckwarteschlange bereinigt ({0} Aufträge, {1} Dateien gelöscht) und neu gestartet - Dienst: {2}.' -f $jobs, $files.Count, $(if ($st -eq 'Running') { 'läuft' } else { $st })
    } catch { Show-UiError ('Druckwarteschlange: ' + $_.Exception.Message) } finally { $window.Cursor = $null }
    Update-Printers
})
