# ---------------------------------------------------------------- Hardware-Test (Oberfläche) - Testbausteine in C# (laufen in eigenen Threads, die Oberfläche fragt den Fortschritt ab)
$HwCs = @'
using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.Runtime.InteropServices;
using System.Threading;

namespace PCToolsHw
{
    // ------------------------------------------------------------ Arbeitsspeicher
    public class RamTest
    {
        public volatile int Percent;
        public volatile bool Done;
        public volatile bool Cancel;
        public volatile string Phase = "";
        public long Errors;
        public long TestedMB;
        public long TargetMB;
        public double MBps;
        public double Seconds;
        public int PatternsDone;
        public int PatternsTotal;
        public string Error = "";
        public string AllocNote = "";
        private readonly List<string> log = new List<string>();
        private Thread worker;

        public string[] GetLog() { lock (log) { return log.ToArray(); } }
        private void Log(string s) { lock (log) { if (log.Count < 400) log.Add(DateTime.Now.ToString("HH:mm:ss") + "  " + s); } }

        public void Start(long megabytes, int passes, long seed)
        {
            TargetMB = megabytes;
            worker = new Thread(delegate () { Run(megabytes, passes, seed); });
            worker.IsBackground = true;
            worker.Priority = ThreadPriority.BelowNormal;
            worker.Start();
        }

        private static ulong Mix(ulong z)
        {
            z += 0x9E3779B97F4A7C15UL;
            z = (z ^ (z >> 30)) * 0xBF58476D1CE4E5B9UL;
            z = (z ^ (z >> 27)) * 0x94D049BB133111EBUL;
            return z ^ (z >> 31);
        }

        private void Run(long megabytes, int passes, long seed)
        {
            List<long[]> chunks = new List<long[]>();
            Stopwatch sw = Stopwatch.StartNew();
            double bytesDone = 0;
            try
            {
                const int chunkMB = 64;
                const int words = chunkMB * 1024 * 1024 / 8;
                Phase = "Speicher wird reserviert ...";
                long want = Math.Max(1, megabytes / chunkMB);
                for (long i = 0; i < want && !Cancel; i++)
                {
                    try { chunks.Add(new long[words]); }
                    catch (OutOfMemoryException) { AllocNote = "Nur " + (chunks.Count * chunkMB) + " MB reservierbar (Windows hat den Rest nicht freigegeben)."; break; }
                    TestedMB = chunks.Count * (long)chunkMB;
                    Percent = (int)(i * 5 / want);
                }
                if (chunks.Count == 0) { Error = "Es konnte kein Speicher reserviert werden."; return; }
                Log("Reserviert: " + TestedMB + " MB in " + chunks.Count + " Blöcken zu 64 MB");
                string[] names = { "0x00 (alle Bits 0)", "0xFF (alle Bits 1)", "0x55 (01010101)", "0xAA (10101010)", "Wandernde Einsen", "Zufallsmuster (Seed " + seed + ")" };
                PatternsTotal = names.Length * Math.Max(1, passes);
                long steps = (long)PatternsTotal * chunks.Count * 2;
                long step = 0;
                for (int pass = 0; pass < Math.Max(1, passes) && !Cancel; pass++)
                {
                    for (int p = 0; p < names.Length && !Cancel; p++)
                    {
                        ulong pseed = (ulong)seed + (ulong)pass * 7919UL;
                        for (int rw = 0; rw < 2 && !Cancel; rw++)
                        {
                            Phase = "Durchlauf " + (pass + 1) + ": " + names[p] + (rw == 0 ? " schreiben" : " prüfen");
                            for (int c = 0; c < chunks.Count && !Cancel; c++)
                            {
                                long[] a = chunks[c];
                                ulong baseIdx = (ulong)c * (ulong)words;
                                long bad = 0;
                                if (rw == 0)
                                {
                                    switch (p)
                                    {
                                        case 0: for (int i = 0; i < a.Length; i++) a[i] = 0; break;
                                        case 1: for (int i = 0; i < a.Length; i++) a[i] = -1; break;
                                        case 2: for (int i = 0; i < a.Length; i++) a[i] = 0x5555555555555555L; break;
                                        case 3: for (int i = 0; i < a.Length; i++) a[i] = unchecked((long)0xAAAAAAAAAAAAAAAAUL); break;
                                        case 4: for (int i = 0; i < a.Length; i++) a[i] = unchecked((long)(1UL << (i & 63))); break;
                                        default: for (int i = 0; i < a.Length; i++) a[i] = unchecked((long)Mix(pseed + baseIdx + (ulong)i)); break;
                                    }
                                }
                                else
                                {
                                    for (int i = 0; i < a.Length; i++)
                                    {
                                        long exp;
                                        switch (p)
                                        {
                                            case 0: exp = 0; break;
                                            case 1: exp = -1; break;
                                            case 2: exp = 0x5555555555555555L; break;
                                            case 3: exp = unchecked((long)0xAAAAAAAAAAAAAAAAUL); break;
                                            case 4: exp = unchecked((long)(1UL << (i & 63))); break;
                                            default: exp = unchecked((long)Mix(pseed + baseIdx + (ulong)i)); break;
                                        }
                                        if (a[i] != exp)
                                        {
                                            bad++;
                                            if (Interlocked.Read(ref Errors) + bad <= 20)
                                                Log(string.Format("FEHLER bei {0}: Block {1}, Wort {2}: erwartet {3:X16}, gelesen {4:X16} (abweichende Bits {5:X16})", names[p], c, i, exp, a[i], exp ^ a[i]));
                                        }
                                    }
                                }
                                if (bad > 0) Interlocked.Add(ref Errors, bad);
                                bytesDone += (double)a.Length * 8;
                                step++;
                                Seconds = sw.Elapsed.TotalSeconds;
                                MBps = bytesDone / 1048576.0 / Math.Max(0.001, Seconds);
                                Percent = 5 + (int)(step * 95 / Math.Max(1, steps));
                            }
                        }
                        if (!Cancel) { PatternsDone++; Log(names[p] + " fertig (Durchlauf " + (pass + 1) + "), Fehler bisher: " + Interlocked.Read(ref Errors)); }
                    }
                }
                Phase = Cancel ? "Abgebrochen" : "Fertig";
                if (!Cancel) Percent = 100;
            }
            catch (Exception ex) { Error = ex.GetType().Name + ": " + ex.Message; }
            finally
            {
                chunks.Clear(); chunks = null;
                GC.Collect(); GC.WaitForPendingFinalizers(); GC.Collect();
                Seconds = sw.Elapsed.TotalSeconds;
                Done = true;
            }
        }
    }

    // ------------------------------------------------------------ Datenträger-Lesetest (nur lesen)
    public class DiskReadTest
    {
        [DllImport("kernel32.dll", SetLastError = true, CharSet = CharSet.Unicode)]
        private static extern IntPtr CreateFile(string name, uint access, uint share, IntPtr sec, uint disp, uint flags, IntPtr tmpl);
        [DllImport("kernel32.dll", SetLastError = true)]
        private static extern bool ReadFile(IntPtr h, IntPtr buf, uint len, out uint read, IntPtr ovl);
        [DllImport("kernel32.dll", SetLastError = true)]
        private static extern bool SetFilePointerEx(IntPtr h, long dist, out long newPos, uint method);
        [DllImport("kernel32.dll", SetLastError = true)]
        private static extern bool CloseHandle(IntPtr h);
        [DllImport("kernel32.dll", SetLastError = true)]
        private static extern bool DeviceIoControl(IntPtr h, uint code, IntPtr inBuf, uint inLen, out long outBuf, uint outLen, out uint ret, IntPtr ovl);
        [DllImport("kernel32.dll", SetLastError = true)]
        private static extern IntPtr VirtualAlloc(IntPtr addr, UIntPtr size, uint type, uint protect);
        [DllImport("kernel32.dll", SetLastError = true)]
        private static extern bool VirtualFree(IntPtr addr, UIntPtr size, uint type);

        public const int Buckets = 400;
        public volatile int Percent;
        public volatile bool Done;
        public volatile bool Cancel;
        public volatile string Phase = "";
        public long DiskSize;
        public long BytesRead;
        public long Blocks;
        public long Slow200;
        public long Slow500;
        public long ReadErrors;
        public double MaxMs;
        public double CurMBps;
        public double AvgMBps;
        public double MinMBps = double.MaxValue;
        public double MaxMBps;
        public double Seconds;
        public double EtaSeconds = -1;
        public double Coverage;
        public string Error = "";
        public readonly double[] BucketSum = new double[Buckets];
        public readonly int[] BucketCount = new int[Buckets];
        public readonly double[] BucketMin = new double[Buckets];
        public readonly int[] BucketSlow = new int[Buckets];
        public readonly int[] BucketErr = new int[Buckets];
        private readonly List<string> log = new List<string>();
        private Thread worker;

        public string[] GetLog() { lock (log) { return log.ToArray(); } }
        private void Log(string s) { lock (log) { if (log.Count < 300) log.Add(DateTime.Now.ToString("HH:mm:ss") + "  " + s); } }

        // Durchschnittsgeschwindigkeit je Abschnitt (NaN = noch nicht gemessen)
        public double[] GetCurve()
        {
            double[] r = new double[Buckets];
            lock (BucketSum) { for (int i = 0; i < Buckets; i++) r[i] = BucketCount[i] > 0 ? BucketSum[i] / BucketCount[i] : double.NaN; }
            return r;
        }
        public int[] GetSlowMarks() { int[] r = new int[Buckets]; lock (BucketSum) { for (int i = 0; i < Buckets; i++) r[i] = BucketSlow[i] + BucketErr[i] * 1000; } return r; }

        // mode 0 = Schnelltest (verteilte Stichproben, Zeitbudget), 1 = vollständig
        public void Start(int driveNumber, long sizeFallback, int blockMB, int mode, int quickSeconds)
        {
            for (int i = 0; i < Buckets; i++) BucketMin[i] = double.MaxValue;
            worker = new Thread(delegate () { Run(driveNumber, sizeFallback, blockMB, mode, quickSeconds); });
            worker.IsBackground = true;
            worker.Start();
        }

        private void Run(int driveNumber, long sizeFallback, int blockMB, int mode, int quickSeconds)
        {
            IntPtr h = new IntPtr(-1);
            IntPtr buf = IntPtr.Zero;
            int block = Math.Max(1, Math.Min(4, blockMB)) * 1024 * 1024;
            Stopwatch total = Stopwatch.StartNew();
            try
            {
                Phase = "Datenträger wird geöffnet ...";
                // GENERIC_READ, FILE_SHARE_READ|WRITE, OPEN_EXISTING, FILE_FLAG_NO_BUFFERING (0x20000000)
                h = CreateFile(@"\\.\PhysicalDrive" + driveNumber, 0x80000000, 3, IntPtr.Zero, 3, 0x20000000, IntPtr.Zero);
                if (h == new IntPtr(-1)) { Error = "Datenträger " + driveNumber + " lässt sich nicht öffnen (Fehler " + Marshal.GetLastWin32Error() + "). PC-Tools braucht Administratorrechte."; return; }
                long size; uint ret;
                if (DeviceIoControl(h, 0x7405C, IntPtr.Zero, 0, out size, 8, out ret, IntPtr.Zero) && size > 0) DiskSize = size; else DiskSize = sizeFallback;
                if (DiskSize <= 0) { Error = "Größe des Datenträgers unbekannt."; return; }
                buf = VirtualAlloc(IntPtr.Zero, new UIntPtr((uint)block), 0x3000, 0x04);
                if (buf == IntPtr.Zero) { Error = "Lesepuffer konnte nicht angelegt werden."; return; }
                long nBlocks = (DiskSize + block - 1) / block;
                Log(string.Format("Datenträger {0}: {1:N0} Bytes, Blockgröße {2} MB, {3:N0} Blöcke, Modus {4}", driveNumber, DiskSize, block / 1048576, nBlocks, mode == 0 ? "Schnelltest" : "vollständig"));
                if (mode == 1)
                {
                    for (long b = 0; b < nBlocks && !Cancel; b++)
                    {
                        ReadBlock(h, buf, b * block, block);
                        Percent = (int)((b + 1) * 100 / nBlocks);
                        Coverage = (double)(b + 1) * 100.0 / nBlocks;
                        Seconds = total.Elapsed.TotalSeconds;
                        double rate = BytesRead / Math.Max(0.001, Seconds);
                        EtaSeconds = rate > 0 ? (DiskSize - (b + 1) * (double)block) / rate : -1;
                        Phase = string.Format("Liest Block {0:N0} von {1:N0}", b + 1, nBlocks);
                    }
                }
                else
                {
                    // Stichproben in immer dichter werdenden Runden (256, 512, 1024 ...), bis das Zeitbudget verbraucht ist
                    Dictionary<long, bool> seen = new Dictionary<long, bool>();
                    long n = 256; int round = 1;
                    while (!Cancel && total.Elapsed.TotalSeconds < quickSeconds)
                    {
                        long count = Math.Min(n, nBlocks);
                        for (long k = 0; k < count && !Cancel && total.Elapsed.TotalSeconds < quickSeconds; k++)
                        {
                            long b = (long)(((double)k + 0.5) * nBlocks / count);
                            if (b >= nBlocks) b = nBlocks - 1;
                            if (seen.ContainsKey(b)) continue;
                            seen[b] = true;
                            ReadBlock(h, buf, b * block, block);
                            Seconds = total.Elapsed.TotalSeconds;
                            Percent = (int)Math.Min(99, Seconds * 100 / quickSeconds);
                            Coverage = seen.Count * 100.0 / nBlocks;
                            EtaSeconds = Math.Max(0, quickSeconds - Seconds);
                            Phase = string.Format("Runde {0}: Stichprobe {1:N0} von {2:N0}", round, k + 1, count);
                        }
                        if (count >= nBlocks) break;
                        n *= 2; round++;
                    }
                    if (!Cancel) Percent = 100;
                }
                Seconds = total.Elapsed.TotalSeconds;
                AvgMBps = BytesRead / 1048576.0 / Math.Max(0.001, Seconds);
                Phase = Cancel ? "Abgebrochen" : "Fertig";
            }
            catch (Exception ex) { Error = ex.GetType().Name + ": " + ex.Message; }
            finally
            {
                if (buf != IntPtr.Zero) VirtualFree(buf, UIntPtr.Zero, 0x8000);
                if (h != new IntPtr(-1)) CloseHandle(h);
                Seconds = total.Elapsed.TotalSeconds;
                Done = true;
            }
        }

        private void ReadBlock(IntPtr h, IntPtr buf, long offset, int block)
        {
            long len = Math.Min((long)block, DiskSize - offset);
            len = len / 4096 * 4096;
            if (len <= 0) return;
            int bucket = (int)Math.Min(Buckets - 1, (long)((double)offset / DiskSize * Buckets));
            Stopwatch sw = Stopwatch.StartNew();
            long np; uint read = 0; bool ok = SetFilePointerEx(h, offset, out np, 0) && ReadFile(h, buf, (uint)len, out read, IntPtr.Zero) && read > 0;
            int err = ok ? 0 : Marshal.GetLastWin32Error();
            if (!ok)
            {
                // zweiter Versuch - manche Sektoren lassen sich nach einem Wiederholversuch lesen
                ok = SetFilePointerEx(h, offset, out np, 0) && ReadFile(h, buf, (uint)len, out read, IntPtr.Zero) && read > 0;
                if (ok) Log(string.Format("Lesefehler bei {0:N0} MB, zweiter Versuch erfolgreich (Fehler {1})", offset / 1048576, err));
            }
            sw.Stop();
            double ms = sw.Elapsed.TotalMilliseconds;
            Interlocked.Increment(ref Blocks);
            if (!ok)
            {
                Interlocked.Increment(ref ReadErrors);
                lock (BucketSum) { BucketErr[bucket]++; }
                Log(string.Format("LESEFEHLER bei Position {0:N0} MB (Fehler {1})", offset / 1048576, err));
                return;
            }
            Interlocked.Add(ref BytesRead, read);
            double mbps = read / 1048576.0 / Math.Max(0.0001, ms / 1000.0);
            CurMBps = mbps;
            if (ms > MaxMs) MaxMs = ms;
            if (mbps < MinMBps) MinMBps = mbps;
            if (mbps > MaxMBps) MaxMBps = mbps;
            lock (BucketSum)
            {
                BucketSum[bucket] += mbps; BucketCount[bucket]++;
                if (mbps < BucketMin[bucket]) BucketMin[bucket] = mbps;
                if (ms > 200) BucketSlow[bucket]++;
            }
            if (ms > 500) { Interlocked.Increment(ref Slow500); Log(string.Format("Sehr langsamer Block bei {0:N0} MB: {1:N0} ms", offset / 1048576, ms)); }
            else if (ms > 200) Interlocked.Increment(ref Slow200);
        }
    }

    // ------------------------------------------------------------ Prozessor-Belastungstest
    public class CpuStress
    {
        [DllImport("pdh.dll", CharSet = CharSet.Unicode)]
        private static extern uint PdhOpenQuery(string src, IntPtr user, out IntPtr query);
        [DllImport("pdh.dll", CharSet = CharSet.Unicode)]
        private static extern uint PdhAddEnglishCounter(IntPtr query, string path, IntPtr user, out IntPtr counter);
        [DllImport("pdh.dll")]
        private static extern uint PdhCollectQueryData(IntPtr query);
        [DllImport("pdh.dll")]
        private static extern uint PdhGetFormattedCounterValue(IntPtr counter, uint format, IntPtr type, out PdhValue value);
        [DllImport("pdh.dll", CharSet = CharSet.Unicode)]
        private static extern uint PdhGetFormattedCounterArray(IntPtr counter, uint format, ref uint size, out uint count, IntPtr items);
        [DllImport("pdh.dll")]
        private static extern uint PdhCloseQuery(IntPtr query);
        [DllImport("kernel32.dll")]
        private static extern bool GetSystemTimes(out long idle, out long kernel, out long user);

        [StructLayout(LayoutKind.Explicit)]
        private struct PdhValue { [FieldOffset(0)] public uint Status; [FieldOffset(8)] public double Value; }

        public volatile bool Done;
        public volatile bool Cancel;
        public volatile int Percent;
        public double ExternalTemp = double.NaN;   // kann von außen (WMI) gesetzt werden
        public bool PerfCounterOk;
        public bool TempCounterOk;
        public int Threads;
        public double MaxMHz;
        public double DurationSec;
        public double Elapsed;
        public long Iterations;
        public string Error = "";
        private readonly List<double[]> samples = new List<double[]>();
        private readonly List<Thread> workers = new List<Thread>();
        private DateTime endAt;

        // Messwerte: {Sekunde, Takt MHz, Last %, Temperatur °C (NaN = unbekannt)}
        public double[][] GetSamples() { lock (samples) { return samples.ToArray(); } }

        public void Start(int threads, double seconds, double maxMHz)
        {
            Threads = Math.Max(1, threads); MaxMHz = maxMHz; DurationSec = seconds;
            endAt = DateTime.UtcNow.AddSeconds(seconds);
            for (int i = 0; i < Threads; i++)
            {
                int seed = i + 1;
                Thread t = new Thread(delegate () { Work(seed); });
                t.IsBackground = true; t.Priority = ThreadPriority.BelowNormal;
                workers.Add(t);
            }
            Thread s = new Thread(Sample); s.IsBackground = true; s.Start();
            foreach (Thread t in workers) t.Start();
        }

        private void Work(int seed)
        {
            double x = seed * 0.5 + 1, y = 1.000001, acc = 0;
            ulong v = (ulong)seed * 0x9E3779B97F4A7C15UL;
            long local = 0;
            while (!Cancel && DateTime.UtcNow < endAt)
            {
                for (int i = 0; i < 200000; i++)
                {
                    x = x * y + Math.Sqrt(x + i) - Math.Sin(x) * 0.001;
                    if (x > 1e9) x = seed;
                    v ^= v << 13; v ^= v >> 7; v ^= v << 17;
                    acc += (v & 0xFF) * 1e-9;
                }
                local++;
            }
            Interlocked.Add(ref Iterations, local);
            if (acc == double.MinValue) Error = "";   // verhindert, dass der Compiler die Rechnung wegoptimiert
        }

        private static double ReadCounter(IntPtr c)
        {
            PdhValue v;
            if (c == IntPtr.Zero) return double.NaN;
            if (PdhGetFormattedCounterValue(c, 0x00000200 | 0x00008000, IntPtr.Zero, out v) != 0) return double.NaN; // PDH_FMT_DOUBLE | PDH_FMT_NOCAP100
            if (v.Status != 0 && v.Status != 1) return double.NaN;
            return v.Value;
        }

        private static double ReadMaxOfArray(IntPtr c)
        {
            if (c == IntPtr.Zero) return double.NaN;
            uint size = 0, count;
            PdhGetFormattedCounterArray(c, 0x00000200, ref size, out count, IntPtr.Zero);
            if (size == 0) return double.NaN;
            IntPtr mem = Marshal.AllocHGlobal((int)size);
            try
            {
                if (PdhGetFormattedCounterArray(c, 0x00000200, ref size, out count, mem) != 0) return double.NaN;
                double max = double.NaN;
                int item = IntPtr.Size == 8 ? 24 : 24;
                for (int i = 0; i < count; i++)
                {
                    IntPtr p = new IntPtr(mem.ToInt64() + i * item);
                    uint st = (uint)Marshal.ReadInt32(p, 8);
                    double d = BitConverter.Int64BitsToDouble(Marshal.ReadInt64(p, 16));
                    if ((st == 0 || st == 1) && d > 0 && (double.IsNaN(max) || d > max)) max = d;
                }
                return max;
            }
            finally { Marshal.FreeHGlobal(mem); }
        }

        private void Sample()
        {
            IntPtr q = IntPtr.Zero, cPerf = IntPtr.Zero, cTemp = IntPtr.Zero;
            try
            {
                try
                {
                    if (PdhOpenQuery(null, IntPtr.Zero, out q) == 0)
                    {
                        if (PdhAddEnglishCounter(q, @"\Processor Information(_Total)\% Processor Performance", IntPtr.Zero, out cPerf) != 0) cPerf = IntPtr.Zero;
                        if (PdhAddEnglishCounter(q, @"\Thermal Zone Information(*)\Temperature", IntPtr.Zero, out cTemp) != 0) cTemp = IntPtr.Zero;
                        PdhCollectQueryData(q);
                    }
                    else q = IntPtr.Zero;
                }
                catch (Exception ex) { q = IntPtr.Zero; cPerf = IntPtr.Zero; cTemp = IntPtr.Zero; Error = "Leistungsindikatoren nicht verfügbar: " + ex.Message; }
                bool sysTimes = true;
                long i0 = 0, k0 = 0, u0 = 0;
                try { GetSystemTimes(out i0, out k0, out u0); } catch { sysTimes = false; }
                Stopwatch sw = Stopwatch.StartNew();
                while (!Cancel && DateTime.UtcNow < endAt)
                {
                    Thread.Sleep(1000);
                    if (q != IntPtr.Zero) PdhCollectQueryData(q);
                    double load = double.NaN;
                    if (sysTimes)
                    {
                        long i1, k1, u1; GetSystemTimes(out i1, out k1, out u1);
                        double busy = (k1 - k0) + (u1 - u0), idle = i1 - i0;
                        if (busy > 0) load = Math.Max(0, Math.Min(100, (busy - idle) * 100.0 / busy));
                        i0 = i1; k0 = k1; u0 = u1;
                    }
                    double perf = q != IntPtr.Zero ? ReadCounter(cPerf) : double.NaN;
                    double mhz = double.NaN;
                    if (!double.IsNaN(perf) && perf > 0 && MaxMHz > 0) { mhz = MaxMHz * perf / 100.0; PerfCounterOk = true; }
                    double temp = double.NaN;
                    double tk = q != IntPtr.Zero ? ReadMaxOfArray(cTemp) : double.NaN;
                    if (!double.IsNaN(tk) && tk > 200 && tk < 420) { temp = tk - 273.15; TempCounterOk = true; }
                    if (double.IsNaN(temp) && !double.IsNaN(ExternalTemp)) temp = ExternalTemp;
                    Elapsed = sw.Elapsed.TotalSeconds;
                    Percent = (int)Math.Min(100, Elapsed * 100 / Math.Max(1, DurationSec));
                    lock (samples) { samples.Add(new double[] { Math.Round(Elapsed, 1), mhz, load, temp }); }
                }
            }
            catch (Exception ex) { Error = ex.GetType().Name + ": " + ex.Message; }
            finally
            {
                Cancel = true;
                foreach (Thread t in workers) { try { t.Join(3000); } catch { } }
                if (q != IntPtr.Zero) PdhCloseQuery(q);
                Done = true;
            }
        }
    }
}
'@
function Initialize-HwTypes {
    if ('PCToolsHw.RamTest' -as [type]) { return }
    Add-Type -TypeDefinition $HwCs -Language CSharp -ErrorAction Stop
}

# ---- Diagramme (Linien auf einem Canvas, mit Achsen, Gitter und Legende) - zeichnet bei Größenänderung automatisch neu
$script:HwChartHooked = @{}
function New-HwText([string]$Text, [double]$Size = 10.5, [string]$Color = '#6B7890') {
    $t = New-Object Windows.Controls.TextBlock; $t.Text = $Text; $t.FontSize = $Size; $t.Foreground = New-UiBrush $Color; return $t
}
function Update-HwChart {
    param($Canvas, [object[]]$Series = @(), [double]$XMin = 0, [double]$XMax = 100, [double]$YMax = 100, [string]$YFmt = '{0:N0}', [double]$Y2Max = 0, [string]$Y2Fmt = '{0:N0}',
          [scriptblock]$XFmt = $null, [object[]]$Marks = @(), [string]$Empty = '', [double]$YMin = 0)
    if (-not $Canvas) { return }
    $Canvas.Tag = @{ Canvas = $Canvas; Series = $Series; XMin = $XMin; XMax = $XMax; YMax = $YMax; YFmt = $YFmt; Y2Max = $Y2Max; Y2Fmt = $Y2Fmt; XFmt = $XFmt; Marks = $Marks; Empty = $Empty; YMin = $YMin }
    $hk = $Canvas.GetHashCode()
    if (-not $script:HwChartHooked.ContainsKey($hk)) {
        $script:HwChartHooked[$hk] = $true
        $Canvas.Add_SizeChanged({ param($s, $e) if ($e.WidthChanged -and $s.Tag -is [hashtable]) { $ca = $s.Tag; try { Update-HwChart @ca } catch { } } })
    }
    $Canvas.Children.Clear()
    $cw = [double]$Canvas.ActualWidth; if ($cw -lt 60) { $cw = 760 }
    $ch = [double]$Canvas.ActualHeight; if ($ch -lt 40) { $ch = [double]$Canvas.Height }; if (-not ($ch -gt 40)) { $ch = 180 }
    $pl0 = 54; $pr0 = $(if ($Y2Max -gt 0) { 50 } else { 14 }); $pt0 = 24; $pb0 = 22
    $pw = $cw - $pl0 - $pr0; $ph = $ch - $pt0 - $pb0
    if ($pw -lt 40 -or $ph -lt 30) { return }
    if ($XMax -le $XMin) { $XMax = $XMin + 1 }
    if ($YMax -le $YMin) { $YMax = $YMin + 1 }
    $gridBr = New-UiBrush '#E2E7F0'
    for ($gi = 0; $gi -le 4; $gi++) {
        $gy = $pt0 + $ph * $gi / 4
        $ln = New-Object Windows.Shapes.Line; $ln.X1 = $pl0; $ln.X2 = $pl0 + $pw; $ln.Y1 = $gy; $ln.Y2 = $gy; $ln.Stroke = $gridBr; $ln.StrokeThickness = 1
        if ($gi -lt 4) { $dc = New-Object Windows.Media.DoubleCollection; $dc.Add(3); $dc.Add(3); $ln.StrokeDashArray = $dc }
        [void]$Canvas.Children.Add($ln)
        $lv = $YMax - ($YMax - $YMin) * $gi / 4
        $tl = New-HwText ($YFmt -f $lv); $tl.Width = $pl0 - 8; $tl.TextAlignment = 'Right'
        [Windows.Controls.Canvas]::SetLeft($tl, 0); [Windows.Controls.Canvas]::SetTop($tl, $gy - 8); [void]$Canvas.Children.Add($tl)
        if ($Y2Max -gt 0) { $tr = New-HwText ($Y2Fmt -f ($Y2Max * (4 - $gi) / 4)); [Windows.Controls.Canvas]::SetLeft($tr, $pl0 + $pw + 6); [Windows.Controls.Canvas]::SetTop($tr, $gy - 8); [void]$Canvas.Children.Add($tr) }
    }
    for ($xi = 0; $xi -le 5; $xi++) {
        $xv = $XMin + ($XMax - $XMin) * $xi / 5
        $xs = if ($XFmt) { [string](& $XFmt $xv) } else { '{0:N0}' -f $xv }
        $tx = New-HwText $xs; $tx.Width = 90; $tx.TextAlignment = $(if ($xi -eq 0) { 'Left' } elseif ($xi -eq 5) { 'Right' } else { 'Center' })
        $xl = $pl0 + $pw * $xi / 5 - $(if ($xi -eq 0) { 0 } elseif ($xi -eq 5) { 90 } else { 45 })
        [Windows.Controls.Canvas]::SetLeft($tx, $xl); [Windows.Controls.Canvas]::SetTop($tx, $pt0 + $ph + 4); [void]$Canvas.Children.Add($tx)
    }
    $any = $false
    foreach ($sr in $Series) {
        if (-not $sr) { continue }
        $ymx = if ($sr.Right) { $Y2Max } else { $YMax }; $ymn = if ($sr.Right) { 0 } else { $YMin }
        if ($ymx -le $ymn) { continue }
        $br = New-UiBrush ([string]$sr.Color)
        $segs = [System.Collections.Generic.List[object]]::new(); $cur = New-Object Windows.Media.PointCollection
        foreach ($pt in @($sr.Points)) {
            if ($null -eq $pt) { continue }
            $vx = [double]$pt[0]; $vy = [double]$pt[1]
            if ([double]::IsNaN($vy) -or [double]::IsNaN($vx)) { if ($cur.Count) { $segs.Add($cur); $cur = New-Object Windows.Media.PointCollection }; continue }
            $px = $pl0 + ($vx - $XMin) / ($XMax - $XMin) * $pw
            $py = $pt0 + $ph - ([math]::Max($ymn, [math]::Min($ymx, $vy)) - $ymn) / ($ymx - $ymn) * $ph
            $cur.Add((New-Object Windows.Point($px, $py)))
        }
        if ($cur.Count) { $segs.Add($cur) }
        foreach ($sg in $segs) {
            $any = $true
            if ($sr.Fill -and $sg.Count -gt 1) {
                $pg = New-Object Windows.Shapes.Polygon; $pc = New-Object Windows.Media.PointCollection
                foreach ($p in $sg) { $pc.Add($p) }
                $pc.Add((New-Object Windows.Point($sg[$sg.Count - 1].X, ($pt0 + $ph)))); $pc.Add((New-Object Windows.Point($sg[0].X, ($pt0 + $ph))))
                $pg.Points = $pc; $pg.Fill = $br; $pg.Opacity = 0.13; [void]$Canvas.Children.Add($pg)
            }
            if ($sg.Count -eq 1) {
                $el = New-Object Windows.Shapes.Ellipse; $el.Width = 5; $el.Height = 5; $el.Fill = $br
                [Windows.Controls.Canvas]::SetLeft($el, $sg[0].X - 2.5); [Windows.Controls.Canvas]::SetTop($el, $sg[0].Y - 2.5); [void]$Canvas.Children.Add($el)
            } else {
                $pl = New-Object Windows.Shapes.Polyline; $pl.Points = $sg; $pl.Stroke = $br; $pl.StrokeThickness = $(if ($sr.Thin) { 1.3 } else { 2 }); $pl.StrokeLineJoin = 'Round'
                if ($sr.Dash) { $dd = New-Object Windows.Media.DoubleCollection; $dd.Add(4); $dd.Add(3); $pl.StrokeDashArray = $dd }
                [void]$Canvas.Children.Add($pl)
            }
        }
    }
    foreach ($mk in @($Marks)) {
        if (-not $mk) { continue }
        $mx = $pl0 + ([double]$mk.X - $XMin) / ($XMax - $XMin) * $pw
        $rc = New-Object Windows.Shapes.Rectangle; $rc.Width = 3; $rc.Height = 8; $rc.Fill = New-UiBrush ([string]$mk.Color); $rc.RadiusX = 1; $rc.RadiusY = 1
        if ($mk.Tip) { $rc.ToolTip = [string]$mk.Tip }
        [Windows.Controls.Canvas]::SetLeft($rc, $mx - 1.5); [Windows.Controls.Canvas]::SetTop($rc, $pt0 + $ph - 8); [void]$Canvas.Children.Add($rc)
    }
    $lg = New-Object Windows.Controls.StackPanel; $lg.Orientation = 'Horizontal'
    foreach ($sr in $Series) {
        if (-not $sr -or -not $sr.Name) { continue }
        $sw = New-Object Windows.Shapes.Rectangle; $sw.Width = 14; $sw.Height = 4; $sw.RadiusX = 2; $sw.RadiusY = 2; $sw.Fill = New-UiBrush ([string]$sr.Color); $sw.Margin = '0,0,5,0'; $sw.VerticalAlignment = 'Center'
        $lt = New-HwText ([string]$sr.Name) 11 '#475569'; $lt.Margin = '0,0,14,0'; $lt.VerticalAlignment = 'Center'
        [void]$lg.Children.Add($sw); [void]$lg.Children.Add($lt)
    }
    [Windows.Controls.Canvas]::SetLeft($lg, $pl0); [Windows.Controls.Canvas]::SetTop($lg, 3); [void]$Canvas.Children.Add($lg)
    if (-not $any -and $Empty) {
        $et = New-HwText $Empty 12.5 '#6B7890'; $et.Width = $pw; $et.TextAlignment = 'Center'; $et.TextWrapping = 'Wrap'
        [Windows.Controls.Canvas]::SetLeft($et, $pl0); [Windows.Controls.Canvas]::SetTop($et, $pt0 + $ph / 2 - 10); [void]$Canvas.Children.Add($et)
    }
}

# ---------------------------------------------------------------- Hardware-Test: Ergebnisse, Kacheln, Gerätedaten
$HwFile = Join-Path $DataDir 'Hardwaretest.json'
$HwTestDefs = @(
    @{ K = 'Ram'; T = 'Arbeitsspeicher' }, @{ K = 'RamDiag'; T = 'Windows-Speicherdiagnose' }, @{ K = 'Disk'; T = 'Datenträger-Lesetest' }, @{ K = 'Cpu'; T = 'Prozessor-Belastungstest' },
    @{ K = 'Bat'; T = 'Akku-Test' }, @{ K = 'Disp'; T = 'Bildschirm-Pixeltest' }, @{ K = 'Kbd'; T = 'Tastatur-Test' }, @{ K = 'Touch'; T = 'Touch/Stift-Test' })
$script:HwRes = @{}; $script:HwDev = $null; $script:HwLoaded = $false
$HwStateMap = @{ ok = @('#DCFCE7', '#15803D', 'Bestanden'); warn = @('#FEF3C7', '#B45309', 'Warnung'); bad = @('#FEE2E2', '#C81E1E', 'Fehler'); run = @('#DCE8FF', '#1D4ED8', 'Läuft ...'); open = @('#EEF2F8', '#475569', 'Nicht geprüft') }

function Import-HwResults {
    $script:HwRes = @{}
    try { $j = Get-Content -LiteralPath $HwFile -Raw -Encoding UTF8 -ErrorAction Stop | ConvertFrom-Json; if ($j.Results) { foreach ($p in $j.Results.PSObject.Properties) { $script:HwRes[$p.Name] = $p.Value } } } catch { }
}
function Save-HwResults {
    try { [pscustomobject]@{ Computer = $env:COMPUTERNAME; Saved = (Get-Date).ToString('o'); Device = $script:HwDev; Results = [pscustomobject]$script:HwRes } | ConvertTo-Json -Depth 6 | Set-Content -LiteralPath $HwFile -Encoding UTF8 } catch { $ui.StatusText.Text = 'Testergebnisse konnten nicht gespeichert werden: ' + $_.Exception.Message }
}
function Set-HwResult([string]$K, [string]$State, [string]$Summary, [string]$Details = '') {
    $script:HwRes[$K] = [pscustomobject]@{ State = $State; Summary = $Summary; Details = $Details; Time = (Get-Date).ToString('o') }
    Save-HwResults; Update-HwBadge $K; Update-HwStats
    $t = @($HwTestDefs | Where-Object { $_.K -eq $K })[0]
    $ui.StatusText.Text = '{0}: {1} - {2}' -f $t.T, $HwStateMap[$State][2], $Summary
}
function Update-HwBadge([string]$K, [string]$Override = '') {
    $r = $script:HwRes[$K]
    $st = if ($Override) { $Override } elseif ($r) { [string]$r.State } else { 'open' }
    if (-not $HwStateMap.ContainsKey($st)) { $st = 'open' }
    $m = $HwStateMap[$st]
    $b = $ui["Hw${K}Badge"]; $bt = $ui["Hw${K}BadgeText"]
    if ($b) { $b.Background = New-UiBrush $m[0] }
    if ($bt) { $bt.Foreground = New-UiBrush $m[1]; $bt.Text = $m[2] }
    $dt = $ui["Hw${K}Detail"]
    if ($dt -and -not $Override) { $dt.Text = if ($r) { 'Letztes Ergebnis ({0:dd.MM.yyyy HH:mm}): {1}' -f ([datetime]$r.Time), $r.Summary } else { '' } }
    if ($K -eq 'RamDiag' -and $r) { $ui.HwRamStatus.Text = 'Windows-Speicherdiagnose ({0:dd.MM.yyyy}): {1}' -f ([datetime]$r.Time), $r.Summary }
}
function Update-HwStats {
    $vals = @($HwTestDefs | ForEach-Object { $script:HwRes[$_.K] } | Where-Object { $_ })
    $ui.HwStatOk.Text = [string]@($vals | Where-Object { $_.State -eq 'ok' }).Count
    $ui.HwStatWarn.Text = [string]@($vals | Where-Object { $_.State -eq 'warn' }).Count
    $ui.HwStatBad.Text = [string]@($vals | Where-Object { $_.State -eq 'bad' }).Count
    $last = @($vals | ForEach-Object { try { [datetime]$_.Time } catch { } } | Sort-Object -Descending)
    $ui.HwStatLast.FontSize = 24
    $ui.HwStatLast.Text = if ($last.Count) { $last[0].ToString('dd.MM.yyyy') } else { 'noch nie' }
}

function Update-HwDevice {
    $ui.HwInfoModel.Text = 'wird gelesen ...'
    Invoke-Bg -Script {
        $o = @{}
        $cs = Get-CimInstance Win32_ComputerSystem; $bios = Get-CimInstance Win32_BIOS; $os = Get-CimInstance Win32_OperatingSystem; $prod = Get-CimInstance Win32_ComputerSystemProduct -ErrorAction SilentlyContinue
        $cpu = @(Get-CimInstance Win32_Processor)[0]
        $o.Maker = ([string]$cs.Manufacturer).Trim()
        $o.Model = ([string]$cs.Model).Trim(); if ($o.Maker -match 'LENOVO' -and $prod -and $prod.Version) { $o.Model = '{0} ({1})' -f ([string]$prod.Version).Trim(), $o.Model }
        $o.Serial = ([string]$bios.SerialNumber).Trim()
        $o.Bios = '{0}{1}' -f ([string]$bios.SMBIOSBIOSVersion).Trim(), $(if ($bios.ReleaseDate) { ' vom ' + ([datetime]$bios.ReleaseDate).ToString('dd.MM.yyyy') } else { '' })
        $reg = Get-ItemProperty 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion' -ErrorAction SilentlyContinue
        $o.Os = '{0} {1} (Build {2}.{3})' -f $os.Caption, $reg.DisplayVersion, $reg.CurrentBuild, $reg.UBR
        $o.Cpu = ([string]$cpu.Name).Trim() -replace '\s+', ' '; $o.Cores = [int]$cpu.NumberOfCores; $o.Threads = [int]$cpu.NumberOfLogicalProcessors; $o.MaxMHz = [int]$cpu.MaxClockSpeed
        $types = @{ 20 = 'DDR'; 21 = 'DDR2'; 24 = 'DDR3'; 26 = 'DDR4'; 27 = 'LPDDR'; 28 = 'LPDDR2'; 29 = 'LPDDR3'; 30 = 'LPDDR4'; 34 = 'DDR5'; 35 = 'LPDDR5' }
        $mods = @(Get-CimInstance Win32_PhysicalMemory -ErrorAction SilentlyContinue)
        $o.RamModules = @($mods | ForEach-Object { '{0:N0} GB {1}{2} {3} {4}' -f ($_.Capacity / 1GB), $(if ($types.ContainsKey([int]$_.SMBIOSMemoryType)) { $types[[int]$_.SMBIOSMemoryType] } else { 'RAM' }), $(if ($_.ConfiguredClockSpeed) { '-' + $_.ConfiguredClockSpeed } elseif ($_.Speed) { '-' + $_.Speed } else { '' }), ([string]$_.Manufacturer).Trim(), ([string]$_.PartNumber).Trim() })
        $o.RamSlots = [int](@(Get-CimInstance Win32_PhysicalMemoryArray -ErrorAction SilentlyContinue | ForEach-Object { $_.MemoryDevices }) | Measure-Object -Sum).Sum
        $o.RamGB = [math]::Round($cs.TotalPhysicalMemory / 1GB, 1)
        $o.RamFreeMB = [math]::Round([double]$os.FreePhysicalMemory / 1024, 0)
        $o.Gpu = (@(Get-CimInstance Win32_VideoController -ErrorAction SilentlyContinue | Where-Object { $_.Name } | ForEach-Object { ([string]$_.Name).Trim() }) -join ', ')
        $o.Disks = @(Get-PhysicalDisk -ErrorAction SilentlyContinue | Sort-Object { [int]$_.DeviceId } | ForEach-Object {
            $rc = $null; try { $rc = $_ | Get-StorageReliabilityCounter -ErrorAction Stop } catch { }
            [pscustomobject]@{ Number = [int]$_.DeviceId; Name = ([string]$_.FriendlyName).Trim(); Serial = ([string]$_.SerialNumber).Trim(); Media = [string]$_.MediaType; Bus = [string]$_.BusType; Size = [int64]$_.Size
                SizeText = ('{0:N0} GB' -f ($_.Size / 1GB)); Health = $(switch ([string]$_.HealthStatus) { 'Healthy' { 'gesund' } 'Warning' { 'WARNUNG' } 'Unhealthy' { 'DEFEKT' } default { [string]$_.HealthStatus } })
                Temp = $(if ($rc -and $rc.Temperature) { '{0} °C' -f $rc.Temperature } else { '-' }); Wear = $(if ($rc -and $null -ne $rc.Wear) { '{0} %' -f $rc.Wear } else { '-' })
                ReadErr = $(if ($rc -and $null -ne $rc.ReadErrorsUncorrected) { [string]$rc.ReadErrorsUncorrected } else { '-' }); Hours = $(if ($rc -and $rc.PowerOnHours) { '{0:N0} h' -f $rc.PowerOnHours } else { '-' })
                WearN = $(if ($rc -and $null -ne $rc.Wear) { [int]$rc.Wear } else { -1 }); ReadErrN = $(if ($rc -and $null -ne $rc.ReadErrorsUncorrected) { [int64]$rc.ReadErrorsUncorrected } else { -1 }); TempN = $(if ($rc -and $rc.Temperature) { [int]$rc.Temperature } else { -1 }); HoursN = $(if ($rc -and $rc.PowerOnHours) { [int64]$rc.PowerOnHours } else { -1 }) } })
        $o.BatDesign = 0; $o.BatFull = 0; $o.BatCycles = -1; $o.BatName = ''
        try { $o.BatDesign = [double](@(Get-CimInstance -Namespace root\wmi -ClassName BatteryStaticData -ErrorAction Stop) | Measure-Object DesignedCapacity -Sum).Sum; $o.BatFull = [double](@(Get-CimInstance -Namespace root\wmi -ClassName BatteryFullChargedCapacity -ErrorAction Stop) | Measure-Object FullChargedCapacity -Sum).Sum } catch { }
        try { $o.BatCycles = [int]@(Get-CimInstance -Namespace root\wmi -ClassName BatteryCycleCount -ErrorAction Stop)[0].CycleCount } catch { }
        try { $b = @(Get-CimInstance Win32_Battery -ErrorAction Stop)[0]; if ($b) { $o.BatName = '{0}{1}' -f ([string]$b.Name).Trim(), $(switch ([int]$b.Chemistry) { 6 { ' (Lithium-Ionen)' } 8 { ' (Lithium-Polymer)' } default { '' } }) } } catch { }
        $o.Time = (Get-Date).ToString('o')
        [pscustomobject]$o
    } -Done {
        param($r, $err)
        if ($err) { $ui.HwInfoModel.Text = 'Gerätedaten nicht lesbar: ' + $err.Message; return }
        $d = @($r | Where-Object { $_ -and $_.Model -ne $null })[0]; if (-not $d) { return }
        $script:HwDev = $d
        $ui.HwInfoMaker.Text = $d.Maker; $ui.HwInfoModel.Text = $d.Model; $ui.HwInfoSerial.Text = $(if ($d.Serial) { $d.Serial } else { 'nicht hinterlegt' })
        $ui.HwInfoCpu.Text = '{0} - {1} Kerne / {2} Threads, Nenntakt {3:N0} MHz' -f $d.Cpu, $d.Cores, $d.Threads, $d.MaxMHz
        $ui.HwInfoRam.Text = '{0:N1} GB{1}{2}' -f $d.RamGB, $(if (@($d.RamModules).Count) { ' - ' + (@($d.RamModules) -join ' | ') } else { '' }), $(if ($d.RamSlots) { ' (Steckplätze: {0} belegt von {1})' -f @($d.RamModules).Count, $d.RamSlots } else { '' })
        $ui.HwInfoDisks.Text = if (@($d.Disks).Count) { (@($d.Disks) | ForEach-Object { '{0} ({1}, {2}, {3})' -f $_.Name, $_.SizeText, $_.Bus, $_.Health }) -join ' | ' } else { 'keine gefunden' }
        $ui.HwInfoGpu.Text = $(if ($d.Gpu) { $d.Gpu } else { '-' })
        $ui.HwInfoOs.Text = '{0} · BIOS {1}' -f $d.Os, $d.Bios
        $ui.HwRamInfo.Text = 'Installiert: {0:N1} GB, davon jetzt frei: {1:N1} GB. Der Test belegt den gewählten Anteil des freien Speichers (mindestens 1 GB bzw. 10 % bleiben für Windows frei).' -f $d.RamGB, ($d.RamFreeMB / 1024)
        # Datenträger-Auswahl und Zuverlässigkeitswerte
        $sel = $ui.HwDiskSel.SelectedIndex; $ui.HwDiskSel.Items.Clear()
        foreach ($k in @($d.Disks)) { $ci = New-Object Windows.Controls.ComboBoxItem; $ci.Content = 'Datenträger {0}: {1} ({2}, {3}, {4})' -f $k.Number, $k.Name, $k.SizeText, $k.Bus, $(if ($k.Media -and $k.Media -ne 'Unspecified') { $k.Media } else { 'Typ ?' }); $ci.Tag = $k; [void]$ui.HwDiskSel.Items.Add($ci) }
        if ($ui.HwDiskSel.Items.Count) { $ui.HwDiskSel.SelectedIndex = [math]::Max(0, [math]::Min($sel, $ui.HwDiskSel.Items.Count - 1)) }
        Set-GridItems $ui.HwDiskRelGrid @($d.Disks)
        Update-HwBatInfo
        Save-HwResults
    }
}
function Update-HwBatInfo {
    $d = $script:HwDev; if (-not $d) { return }
    if ($d.BatDesign -gt 0 -and $d.BatFull -gt 0) {
        $h = [math]::Round([math]::Min(100, $d.BatFull * 100 / $d.BatDesign), 0)
        $ui.HwBatDesign.Text = '{0:N1} Wh{1}' -f ($d.BatDesign / 1000), $(if ($d.BatName) { ' - ' + $d.BatName } else { '' })
        $ui.HwBatFull.Text = '{0:N1} Wh' -f ($d.BatFull / 1000)
        $ui.HwBatHealth.Text = '{0} % der Originalkapazität - {1}' -f $h, $(if ($h -ge 80) { 'gut' } elseif ($h -ge 60) { 'deutlich gealtert, Laufzeit spürbar kürzer' } else { 'verschlissen - Akkutausch empfohlen' })
        $ui.HwBatCycles.Text = if ($d.BatCycles -gt 0) { '{0} {1}' -f $d.BatCycles, $(if ($d.BatCycles -gt 800) { '(viele - typisch sind 500-1000 Zyklen Lebensdauer)' } else { '' }) } else { 'vom Akku nicht gemeldet' }
    } else {
        foreach ($n in 'HwBatDesign', 'HwBatFull', 'HwBatHealth', 'HwBatCycles') { $ui[$n].Text = '-' }
        $ui.HwBatHealth.Text = 'Kein Akku gefunden (Desktop-PC) - der Akku-Test entfällt.'
    }
    $s = Get-HwBatStatus
    $ui.HwBatNow.Text = if ($s) { '{0:N1} Wh geladen · {1}{2}' -f ($s.Remaining / 1000), $(if ($s.Online) { 'am Netzteil' } else { 'Akkubetrieb' }), $(if ($s.Rate -gt 0) { (' · Verbrauch {0:N1} W' -f ($s.Rate / 1000)) } elseif ($s.Charging) { ' · lädt' } else { '' }) } else { '-' }
}
function Get-HwBatStatus {
    try {
        $all = @(Get-CimInstance -Namespace root\wmi -ClassName BatteryStatus -ErrorAction Stop -OperationTimeoutSec 3 | Where-Object { $null -ne $_.RemainingCapacity })
        if (-not $all.Count) { return $null }
        [pscustomobject]@{
            Online = [bool](@($all | Where-Object { $_.PowerOnline }).Count); Charging = [bool](@($all | Where-Object { $_.Charging }).Count)
            Remaining = [double]($all | Measure-Object RemainingCapacity -Sum).Sum; Rate = [double](@($all | Where-Object { [int]$_.DischargeRate -gt 0 -and [int]$_.DischargeRate -lt 500000 }) | Measure-Object DischargeRate -Sum).Sum
            Voltage = [double]@($all)[0].Voltage
        }
    } catch { return $null }
}

# ---- gemeinsamer Takt für die laufenden Tests
$script:HwTimer = New-Object Windows.Threading.DispatcherTimer
$script:HwTimer.Interval = [TimeSpan]::FromMilliseconds(500)
$script:HwTimer.Add_Tick({ try { Update-HwLive } catch { $ui.StatusText.Text = 'Hardware-Test: ' + $_.Exception.Message } })
$script:HwRamObj = $null; $script:HwDiskObj = $null; $script:HwCpuObj = $null; $script:HwTick = 0
function Update-HwLive {
    $script:HwTick++
    $active = $false
    if ($script:HwRamObj) { if ($script:HwRamObj.Done) { Complete-HwRam } else { Show-HwRamLive; $active = $true } }
    if ($script:HwDiskObj) { if ($script:HwDiskObj.Done) { Show-HwDiskLive; Complete-HwDisk } else { Show-HwDiskLive; $active = $true } }
    if ($script:HwCpuObj) { if ($script:HwCpuObj.Done) { Show-HwCpuLive; Complete-HwCpu } else { Show-HwCpuLive; $active = $true } }
    if (-not $active) { $script:HwTimer.Stop() }
}
function Format-HwDuration([double]$Sec) {
    if ($Sec -lt 0) { return '-' }
    $ts = [TimeSpan]::FromSeconds([math]::Round($Sec))
    if ($ts.TotalHours -ge 1) { '{0}:{1:00} h' -f [int][math]::Floor($ts.TotalHours), $ts.Minutes } elseif ($ts.TotalMinutes -ge 1) { '{0}:{1:00} min' -f $ts.Minutes, $ts.Seconds } else { '{0} s' -f $ts.Seconds }
}

# ---------------------------------------------------------------- Arbeitsspeicher
function Start-HwRam {
    if ($script:HwRamObj) { return }
    try { Initialize-HwTypes } catch { Show-UiError ('Der Testbaustein konnte nicht geladen werden: ' + $_.Exception.Message); return }
    $os = Get-CimInstance Win32_OperatingSystem
    $freeMB = [double]$os.FreePhysicalMemory / 1024; $totalMB = [double]$os.TotalVisibleMemorySize / 1024
    $pct = @(25, 50, 75)[[math]::Max(0, $ui.HwRamAmount.SelectedIndex)]
    $mb = [math]::Min($freeMB * $pct / 100, $freeMB - [math]::Max(1024, $totalMB * 0.1))
    if (-not [Environment]::Is64BitProcess) { $mb = [math]::Min($mb, 1024) }
    $mb = [int64]([math]::Floor($mb / 64) * 64)
    if ($mb -lt 256) { Show-UiError ('Zu wenig freier Arbeitsspeicher für den Test ({0:N0} MB frei). Bitte Programme schließen und erneut versuchen - oder die Windows-Speicherdiagnose beim Neustart verwenden.' -f $freeMB); return }
    $passes = @(1, 2, 3, 5)[[math]::Max(0, $ui.HwRamPasses.SelectedIndex)]
    $seed = Get-Random -Minimum 1 -Maximum 2147483647
    $o = New-Object PCToolsHw.RamTest
    $o.Start($mb, $passes, [int64]$seed)
    $script:HwRamObj = $o
    $script:HwRamMeta = @{ MB = $mb; FreeMB = $freeMB; TotalMB = $totalMB; Pct = $pct; Passes = $passes; Seed = $seed; Start = Get-Date; LogCount = 0 }
    $ui.BtnHwRamStart.IsEnabled = $false; $ui.BtnHwRamStop.IsEnabled = $true; $ui.HwRamLog.Clear()
    Update-HwBadge 'Ram' 'run'
    $ui.HwRamStatus.Text = 'Prüfe {0:N1} GB mit 6 Mustern, {1} Durchlauf/Durchläufe ...' -f ($mb / 1024), $passes
    $script:HwTimer.Start()
}
function Show-HwRamLive {
    $o = $script:HwRamObj; if (-not $o) { return }
    $ui.HwRamProg.Value = $o.Percent; $ui.HwRamPct.Text = '{0} %' -f $o.Percent
    $el = ((Get-Date) - $script:HwRamMeta.Start).TotalSeconds
    $eta = if ($o.Percent -gt 6) { $el * (100 - $o.Percent) / [math]::Max(1, $o.Percent - 5) } else { -1 }
    $ui.HwRamStatus.Text = '{0}  ·  {1:N0} MB/s  ·  Fehler: {2}  ·  Restzeit ca. {3}' -f $o.Phase, $o.MBps, $o.Errors, (Format-HwDuration $eta)
    $lg = $o.GetLog(); if ($lg.Count -ne $script:HwRamMeta.LogCount) { $script:HwRamMeta.LogCount = $lg.Count; $ui.HwRamLog.Text = ($lg -join "`r`n"); $ui.HwRamLog.ScrollToEnd() }
}
function Complete-HwRam {
    Show-HwRamLive
    $o = $script:HwRamObj; $script:HwRamObj = $null; $m = $script:HwRamMeta
    $ui.BtnHwRamStart.IsEnabled = $true; $ui.BtnHwRamStop.IsEnabled = $false
    if ($o.Error) { Update-HwBadge 'Ram'; $ui.HwRamStatus.Text = 'Test nicht möglich: ' + $o.Error; return }
    if ($m.Cancelled) { Update-HwBadge 'Ram'; $ui.HwRamStatus.Text = 'Abgebrochen nach {0} - bis dahin {1} Fehler.' -f (Format-HwDuration $o.Seconds), $o.Errors; return }
    $det = 'Geprüft: {0:N0} MB ({1} % des freien Speichers von {2:N0} MB), {3} Muster × {4} Durchlauf/Durchläufe, Zufalls-Seed {5}, Dauer {6}, Ø {7:N0} MB/s. {8}' -f $o.TestedMB, $m.Pct, $m.FreeMB, 6, $m.Passes, $m.Seed, (Format-HwDuration $o.Seconds), $o.MBps, $o.AllocNote
    if ($o.Errors -gt 0) {
        $err = @($o.GetLog() | Where-Object { $_ -match 'FEHLER' } | Select-Object -First 5)
        Set-HwResult 'Ram' 'bad' ('{0} Speicherfehler in {1:N1} GB gefunden - Arbeitsspeicher defekt oder instabil' -f $o.Errors, ($o.TestedMB / 1024)) ($det + "`n" + ($err -join "`n") + "`nEmpfehlung: Riegel einzeln testen (Windows-Speicherdiagnose oder MemTest86), XMP/EXPO-Übertaktung im BIOS abschalten, Kontakte reinigen.")
    } else {
        Set-HwResult 'Ram' 'ok' ('{0:N1} GB fehlerfrei geprüft ({1} Muster × {2}, Ø {3:N0} MB/s)' -f ($o.TestedMB / 1024), 6, $m.Passes, $o.MBps) $det
    }
    $ui.HwRamStatus.Text = 'Fertig: ' + $script:HwRes['Ram'].Summary
    $ui.HwRamProg.Value = 100
}
function Start-HwMemDiag {
    if (-not (Confirm-Ui ("Die Windows-Speicherdiagnose prüft den gesamten Arbeitsspeicher außerhalb von Windows - auch den Teil, den Windows selbst belegt.`n`nSie wird für den nächsten Neustart eingeplant und dauert je nach Speichergröße 10-60 Minuten. Danach startet Windows normal; das Ergebnis liest PC-Tools mit 'Ergebnis der Speicherdiagnose'.`n`nJetzt einplanen?"))) { return }
    $ok = $false
    try { $out = & bcdedit.exe /bootsequence '{memdiag}' 2>&1; $ok = ($LASTEXITCODE -eq 0) } catch { }
    if (-not $ok) { try { Start-Process mdsched.exe; $ui.StatusText.Text = 'Windows-Speicherdiagnose geöffnet - dort "Beim nächsten Start des Computers nach Problemen suchen" wählen.'; return } catch { Show-UiError ('Speicherdiagnose konnte nicht eingeplant werden: ' + $_.Exception.Message); return } }
    $ui.HwRamStatus.Text = 'Windows-Speicherdiagnose ist für den nächsten Neustart eingeplant.'
    if (Confirm-Ui 'Eingeplant. Jetzt neu starten? (Vorher alle Dateien speichern!)' 'Warning') { Start-Process shutdown.exe -ArgumentList '/r /t 5 /c "PC-Tools: Neustart für die Windows-Speicherdiagnose"' -WindowStyle Hidden }
}
function Read-HwMemDiagResult {
    $ev = @(); try { $ev = @(Get-WinEvent -FilterHashtable @{ LogName = 'System'; ProviderName = 'Microsoft-Windows-MemoryDiagnostics-Results'; Id = 1101, 1201 } -MaxEvents 1 -ErrorAction Stop) } catch { }
    if (-not $ev.Count) { $ui.HwRamStatus.Text = 'Es gibt noch kein Ergebnis der Windows-Speicherdiagnose (noch nie gelaufen oder Ereignisprotokoll geleert).'; return }
    $e = $ev[0]; $msg = ([string]$e.Message -replace '\s+', ' ').Trim()
    $bad = if ($msg -match 'no errors|keine Fehler') { $false } elseif ($msg -match 'hardware errors|Hardwarefehler|errors were detected|Fehler (erkannt|festgestellt)') { $true } else { $e.Id -eq 1101 }
    Set-HwResult 'RamDiag' $(if ($bad) { 'bad' } else { 'ok' }) $(if ($bad) { 'Hardwarefehler im Arbeitsspeicher gefunden' } else { 'keine Fehler gefunden' }) ('Ereignis {0} vom {1:dd.MM.yyyy HH:mm}: {2}' -f $e.Id, $e.TimeCreated, $msg)
}

# ---------------------------------------------------------------- Datenträger-Lesetest
function Start-HwDisk {
    if ($script:HwDiskObj) { return }
    if (-not (Test-IsAdmin)) { Show-UiError 'Der Lesetest greift direkt auf den Datenträger zu und braucht dafür Administratorrechte. Bitte PC-Tools als Administrator starten.'; return }
    $it = $ui.HwDiskSel.SelectedItem
    if (-not $it -or -not $it.Tag) { Show-UiError 'Bitte zuerst einen Datenträger auswählen (die Liste wird beim Öffnen der Seite gefüllt).'; return }
    $d = $it.Tag; $mode = [math]::Max(0, $ui.HwDiskMode.SelectedIndex); $blk = @(1, 2, 4)[[math]::Max(0, $ui.HwDiskBlock.SelectedIndex)]
    if ($mode -eq 1) {
        $gb = $d.Size / 1GB
        if (-not (Confirm-Ui ("Vollständiger Lesetest von {0} ({1:N0} GB).`n`nEs wird jeder Block gelesen - nichts wird verändert. Geschätzte Dauer: NVMe-SSD ca. {2}, SATA-SSD ca. {3}, Festplatte ca. {4}. Der PC bleibt benutzbar, wird aber langsamer.`n`nStarten?" -f $d.Name, $gb, (Format-HwDuration ($d.Size / 1500MB)), (Format-HwDuration ($d.Size / 450MB)), (Format-HwDuration ($d.Size / 120MB))))) { return }
    }
    try { Initialize-HwTypes } catch { Show-UiError ('Der Testbaustein konnte nicht geladen werden: ' + $_.Exception.Message); return }
    $o = New-Object PCToolsHw.DiskReadTest
    $o.Start([int]$d.Number, [int64]$d.Size, [int]$blk, [int]$mode, 120)
    $script:HwDiskObj = $o; $script:HwDiskMeta = @{ Disk = $d; Mode = $mode; Block = $blk; LogCount = 0; Cancelled = $false }
    $ui.BtnHwDiskStart.IsEnabled = $false; $ui.BtnHwDiskStop.IsEnabled = $true; $ui.HwDiskSel.IsEnabled = $false; $ui.HwDiskLog.Clear()
    Update-HwBadge 'Disk' 'run'
    $script:HwTimer.Start()
}
function Show-HwDiskLive {
    $o = $script:HwDiskObj; if (-not $o) { return }
    $ui.HwDiskProg.Value = $o.Percent; $ui.HwDiskPct.Text = '{0} %' -f $o.Percent
    $ui.HwDiskStatus.Text = '{0}{1}' -f $o.Phase, $(if ($o.EtaSeconds -ge 0 -and -not $o.Done) { '  ·  Restzeit ca. ' + (Format-HwDuration $o.EtaSeconds) } else { '' })
    $ui.HwDiskLive.Text = 'Aktuell {0:N0} MB/s  ·  gelesen {1:N1} GB  ·  Abdeckung {2:N1} %  ·  langsame Blöcke > 200 ms: {3}  ·  > 500 ms: {4}  ·  Lesefehler: {5}  ·  langsamster Block {6:N0} ms' -f $o.CurMBps, ($o.BytesRead / 1GB), $o.Coverage, ($o.Slow200 + $o.Slow500), $o.Slow500, $o.ReadErrors, $o.MaxMs
    $cv = $o.GetCurve(); $pts = [System.Collections.Generic.List[object]]::new(); $ymax = 50
    for ($i = 0; $i -lt $cv.Count; $i++) { if (-not [double]::IsNaN($cv[$i])) { $pts.Add(@((($i + 0.5) * 100 / $cv.Count), $cv[$i])); if ($cv[$i] -gt $ymax) { $ymax = $cv[$i] } } }
    $sm = $o.GetSlowMarks(); $marks = @(for ($i = 0; $i -lt $sm.Count; $i++) { if ($sm[$i] -gt 0) { @{ X = (($i + 0.5) * 100 / $sm.Count); Color = $(if ($sm[$i] -ge 1000) { '#DC2626' } else { '#EA580C' }); Tip = $(if ($sm[$i] -ge 1000) { 'Lesefehler' } else { '{0} langsame(r) Block/Blöcke' -f $sm[$i] }) } } })
    $ytop = [math]::Ceiling($ymax * 1.15 / 50) * 50
    Update-HwChart -Canvas $ui.HwDiskChart -Series @(@{ Name = 'Lesegeschwindigkeit (MB/s) über die Position auf dem Datenträger'; Color = '#0F766E'; Points = $pts; Fill = $true }) -XMin 0 -XMax 100 -YMax $ytop -YFmt '{0:N0} MB/s' -XFmt { param($v) '{0:N0} %' -f $v } -Marks $marks -Empty 'Noch keine Messwerte - Test starten.'
    $lg = $o.GetLog(); if ($lg.Count -ne $script:HwDiskMeta.LogCount) { $script:HwDiskMeta.LogCount = $lg.Count; $ui.HwDiskLog.Text = ($lg -join "`r`n"); $ui.HwDiskLog.ScrollToEnd() }
}
function Complete-HwDisk {
    $o = $script:HwDiskObj; $script:HwDiskObj = $null; $m = $script:HwDiskMeta; $d = $m.Disk
    $ui.BtnHwDiskStart.IsEnabled = $true; $ui.BtnHwDiskStop.IsEnabled = $false; $ui.HwDiskSel.IsEnabled = $true
    if ($o.Error) { Update-HwBadge 'Disk'; $ui.HwDiskStatus.Text = 'Test nicht möglich: ' + $o.Error; return }
    $avg = if ($o.Seconds -gt 0) { $o.BytesRead / 1MB / $o.Seconds } else { 0 }
    $slowAll = $o.Slow200 + $o.Slow500
    $sum = '{0}: Ø {1:N0} MB/s (min {2:N0}, max {3:N0}), {4:N1} GB gelesen ({5:N1} % Abdeckung), langsame Blöcke > 200 ms: {6}, > 500 ms: {7}, Lesefehler: {8}' -f $d.Name, $avg, $(if ($o.MinMBps -lt 1e300) { $o.MinMBps } else { 0 }), $o.MaxMBps, ($o.BytesRead / 1GB), $o.Coverage, $slowAll, $o.Slow500, $o.ReadErrors
    if ($m.Cancelled) { Update-HwBadge 'Disk'; $ui.HwDiskStatus.Text = 'Abgebrochen. Bis dahin: ' + $sum; return }
    $st = 'ok'; $why = [System.Collections.Generic.List[string]]::new()
    if ($o.ReadErrors -gt 0) { $st = 'bad'; $why.Add(('{0} Block/Blöcke nicht lesbar - defekte Sektoren, sofort Daten sichern' -f $o.ReadErrors)) }
    if ($o.Slow500 -gt 0) { if ($st -eq 'ok') { $st = 'warn' }; $why.Add(('{0} sehr langsame Block/Blöcke (> 500 ms) - schwache Bereiche' -f $o.Slow500)) }
    elseif ($slowAll -gt [math]::Max(3, $o.Blocks * 0.01)) { if ($st -eq 'ok') { $st = 'warn' }; $why.Add(('{0} langsame Blöcke (> 200 ms)' -f $slowAll)) }
    $rel = @(@($script:HwDev.Disks) | Where-Object { $_.Number -eq $d.Number })[0]
    if ($rel) {
        if ($rel.Health -ne 'gesund') { $st = 'bad'; $why.Add('Laufwerk meldet Zustand ' + $rel.Health) }
        if ($rel.ReadErrN -gt 0) { $st = 'bad'; $why.Add(('Laufwerk meldet {0} nicht korrigierbare Lesefehler' -f $rel.ReadErrN)) }
        if ($rel.WearN -ge 80) { if ($st -eq 'ok') { $st = 'warn' }; $why.Add(('Verschleiß {0} %' -f $rel.WearN)) }
        if ($rel.TempN -ge 70) { if ($st -eq 'ok') { $st = 'warn' }; $why.Add(('Temperatur {0} °C' -f $rel.TempN)) }
    }
    $det = '{0} ({1}, {2}, Seriennummer {3}) - Modus {4}, Blockgröße {5} MB, Dauer {6}. Zuverlässigkeit: Zustand {7}, Temperatur {8}, Verschleiß {9}, nicht korrigierbare Lesefehler {10}, Betriebsstunden {11}.{12}' -f $d.Name, $d.SizeText, $d.Bus, $d.Serial, $(if ($m.Mode -eq 1) { 'vollständig' } else { 'Schnelltest (Stichproben)' }), $m.Block, (Format-HwDuration $o.Seconds), $(if ($rel) { $rel.Health } else { '-' }), $(if ($rel) { $rel.Temp } else { '-' }), $(if ($rel) { $rel.Wear } else { '-' }), $(if ($rel) { $rel.ReadErr } else { '-' }), $(if ($rel) { $rel.Hours } else { '-' }), $(if ($why.Count) { ' Auffällig: ' + ($why -join '; ') + '.' } else { '' })
    Set-HwResult 'Disk' $st $(if ($why.Count) { $sum + ' - ' + ($why -join '; ') } else { $sum }) $det
    $ui.HwDiskStatus.Text = 'Fertig: ' + $(switch ($st) { 'ok' { 'keine Auffälligkeiten.' } 'warn' { 'mit Warnung - ' + ($why -join '; ') } default { 'FEHLER - ' + ($why -join '; ') } })
}

# ---------------------------------------------------------------- Prozessor-Belastungstest
function Start-HwCpu {
    if ($script:HwCpuObj) { return }
    try { Initialize-HwTypes } catch { Show-UiError ('Der Testbaustein konnte nicht geladen werden: ' + $_.Exception.Message); return }
    $n = [Environment]::ProcessorCount
    $thr = switch ([math]::Max(0, $ui.HwCpuThreads.SelectedIndex)) { 0 { $n } 1 { [math]::Max(1, [int]($n / 2)) } default { 1 } }
    $dur = @(60, 300, 600)[[math]::Max(0, $ui.HwCpuDur.SelectedIndex)]
    $max = if ($script:HwDev -and $script:HwDev.MaxMHz) { [double]$script:HwDev.MaxMHz } else { try { [double]@(Get-CimInstance Win32_Processor)[0].MaxClockSpeed } catch { 0 } }
    $wmiT = $false; try { $null = @(Get-CimInstance -Namespace root\wmi -ClassName MSAcpi_ThermalZoneTemperature -ErrorAction Stop -OperationTimeoutSec 2)[0].CurrentTemperature; $wmiT = $true } catch { }
    $bat = Get-HwBatStatus
    if ($bat -and -not $bat.Online -and -not (Confirm-Ui 'Der Laptop läuft gerade im Akkubetrieb. Unter Akku drosselt Windows den Prozessor meist absichtlich - das Ergebnis ist dann nicht aussagekräftig. Trotzdem starten?')) { return }
    $o = New-Object PCToolsHw.CpuStress
    $o.Start([int]$thr, [double]$dur, $max)
    $script:HwCpuObj = $o; $script:HwCpuMeta = @{ Threads = $thr; Dur = $dur; Max = $max; Wmi = $wmiT; Cancelled = $false; OnBattery = [bool]($bat -and -not $bat.Online) }
    $ui.BtnHwCpuStart.IsEnabled = $false; $ui.BtnHwCpuStop.IsEnabled = $true
    Update-HwBadge 'Cpu' 'run'
    $ui.HwCpuStatus.Text = 'Belastung mit {0} Thread(s) für {1} ...' -f $thr, (Format-HwDuration $dur)
    $script:HwTimer.Start()
}
function Show-HwCpuLive {
    $o = $script:HwCpuObj; if (-not $o) { return }; $m = $script:HwCpuMeta
    if ($m.Wmi -and -not $o.TempCounterOk -and ($script:HwTick % 4) -eq 0 -and -not $o.Done) {
        try { $z = @(Get-CimInstance -Namespace root\wmi -ClassName MSAcpi_ThermalZoneTemperature -ErrorAction Stop -OperationTimeoutSec 1 | ForEach-Object { $_.CurrentTemperature / 10 - 273.15 } | Where-Object { $_ -gt 5 -and $_ -lt 130 }); if ($z.Count) { $o.ExternalTemp = ($z | Measure-Object -Maximum).Maximum } } catch { $m.Wmi = $false }
    }
    $ui.HwCpuProg.Value = $o.Percent; $ui.HwCpuPct.Text = '{0} %' -f $o.Percent
    $sm = @($o.GetSamples())
    $clk = [System.Collections.Generic.List[object]]::new(); $ld = [System.Collections.Generic.List[object]]::new(); $tp = [System.Collections.Generic.List[object]]::new(); $cmax = [double]$m.Max
    foreach ($s in $sm) { $clk.Add(@($s[0], $s[1])); $ld.Add(@($s[0], $s[2])); $tp.Add(@($s[0], $s[3])); if (-not [double]::IsNaN($s[1]) -and $s[1] -gt $cmax) { $cmax = $s[1] } }
    if ($cmax -le 0) { $cmax = 4000 }
    $ytop = [math]::Ceiling($cmax * 1.12 / 500) * 500
    $hasT = @($sm | Where-Object { -not [double]::IsNaN($_[3]) }).Count -gt 0
    $series = @(@{ Name = 'Takt (MHz, links)'; Color = '#2D7FF9'; Points = $clk; Fill = $true }, @{ Name = 'Last (%, rechts)'; Color = '#16A34A'; Points = $ld; Right = $true; Thin = $true })
    if ($hasT) { $series += @{ Name = 'Temperatur (°C, rechts)'; Color = '#DC2626'; Points = $tp; Right = $true } }
    Update-HwChart -Canvas $ui.HwCpuChart -Series $series -XMin 0 -XMax $m.Dur -YMax $ytop -YFmt '{0:N0}' -Y2Max 100 -Y2Fmt '{0:N0}' -XFmt { param($v) Format-HwDuration $v } -Empty 'Messwerte erscheinen nach einer Sekunde ...'
    if ($sm.Count) {
        $l = $sm[$sm.Count - 1]
        $ui.HwCpuLive.Text = 'Takt {0}  ·  Last {1}  ·  Temperatur {2}  ·  Laufzeit {3} von {4}{5}' -f $(if ([double]::IsNaN($l[1])) { 'nicht messbar' } else { '{0:N0} MHz' -f $l[1] }), $(if ([double]::IsNaN($l[2])) { '-' } else { '{0:N0} %' -f $l[2] }), $(if ([double]::IsNaN($l[3])) { 'von Windows nicht lieferbar' } else { '{0:N0} °C' -f $l[3] }), (Format-HwDuration $l[0]), (Format-HwDuration $m.Dur), $(if ($m.OnBattery) { '  ·  Akkubetrieb!' } else { '' })
    }
}
function Complete-HwCpu {
    $o = $script:HwCpuObj; $script:HwCpuObj = $null; $m = $script:HwCpuMeta
    $ui.BtnHwCpuStart.IsEnabled = $true; $ui.BtnHwCpuStop.IsEnabled = $false
    $sm = @($o.GetSamples())
    if ($sm.Count -lt 3) { Update-HwBadge 'Cpu'; $ui.HwCpuStatus.Text = 'Test nicht möglich' + $(if ($o.Error) { ': ' + $o.Error } else { ' (keine Messwerte).' }); return }
    if ($m.Cancelled -and $sm.Count -lt 20) { Update-HwBadge 'Cpu'; $ui.HwCpuStatus.Text = 'Abgebrochen (zu kurz für eine Bewertung).'; return }
    $load = @($sm | Where-Object { $_[0] -ge 3 -and -not [double]::IsNaN($_[2]) -and $_[2] -ge 80 })
    $clkL = @($load | Where-Object { -not [double]::IsNaN($_[1]) } | ForEach-Object { $_[1] })
    $temps = @($sm | Where-Object { -not [double]::IsNaN($_[3]) } | ForEach-Object { $_[3] })
    $st = 'ok'; $out = [System.Collections.Generic.List[string]]::new(); $why = [System.Collections.Generic.List[string]]::new()
    $out.Add(('{0} Thread(s), {1}{2}' -f $m.Threads, (Format-HwDuration ($sm[$sm.Count - 1][0])), $(if ($m.Cancelled) { ' (vorzeitig beendet)' } else { '' })))
    $avgLoad = if (@($sm | Where-Object { -not [double]::IsNaN($_[2]) }).Count) { (@($sm | Where-Object { -not [double]::IsNaN($_[2]) } | ForEach-Object { $_[2] }) | Measure-Object -Average).Average } else { 0 }
    $out.Add(('Ø Last {0:N0} %' -f $avgLoad))
    if ($clkL.Count -ge 5) {
        $first = @($clkL | Select-Object -First ([math]::Max(3, [int]($clkL.Count * 0.15))) | Sort-Object -Descending)
        $peak = $first[0]; $avgC = ($clkL | Measure-Object -Average).Average; $minC = ($clkL | Measure-Object -Minimum).Minimum
        $thrN = @($clkL | Where-Object { $_ -lt $peak * 0.75 }).Count; $thrPct = $thrN * 100 / $clkL.Count
        $out.Add(('Takt unter Last: Spitze {0:N0} MHz, Ø {1:N0} MHz, Minimum {2:N0} MHz (Nenntakt {3:N0} MHz)' -f $peak, $avgC, $minC, $m.Max))
        if ($thrPct -ge 10) {
            $st = 'warn'
            $hotThr = @($load | Where-Object { -not [double]::IsNaN($_[1]) -and $_[1] -lt $peak * 0.75 -and -not [double]::IsNaN($_[3]) -and $_[3] -ge 88 }).Count
            $why.Add(('Drosselung: in {0:N0} % der Zeit lag der Takt mehr als 25 % unter der Spitze{1}' -f $thrPct, $(if ($hotThr) { ' - wegen Überhitzung (Kühler/Lüfter reinigen, Wärmeleitpaste erneuern)' } elseif ($m.OnBattery) { ' - im Akkubetrieb normal' } else { ' - vermutlich Leistungsgrenze des Herstellers (PL1/PL2) oder Energieplan; bei Laptops häufig normal' })))
        }
        if ($m.Max -gt 0 -and $avgC -lt $m.Max * 0.6) { $st = 'warn'; $why.Add('Ø Takt unter 60 % des Nenntakts - Energieplan "Höchstleistung" wählen, Kühlung und Netzteil prüfen') }
    } elseif (-not $o.PerfCounterOk) { $out.Add('Takt nicht messbar (Leistungsindikator fehlt)') }
    if ($temps.Count) {
        $tmax = ($temps | Measure-Object -Maximum).Maximum; $out.Add(('höchste Temperatur {0:N0} °C' -f $tmax))
        if ($tmax -ge 95) { $st = 'bad'; $why.Add('Überhitzung (≥ 95 °C) - Kühlung dringend prüfen') } elseif ($tmax -ge 90) { if ($st -eq 'ok') { $st = 'warn' }; $why.Add('sehr heiß (≥ 90 °C)') }
    } else { $out.Add('Temperatur von Windows nicht auslesbar (bei vielen Geräten normal - Herstellertool oder HWiNFO zeigen sie)') }
    if ($avgLoad -lt 70 -and $m.Threads -ge [Environment]::ProcessorCount) { if ($st -eq 'ok') { $st = 'warn' }; $why.Add('Last blieb unter 70 % - andere Programme oder Energiesparen bremsen') }
    $out.Add('kein Absturz, kein Einfrieren während der Belastung')
    $sum = if ($why.Count) { ($why -join '; ') } else { 'stabil, keine Drosselung{0}' -f $(if ($temps.Count) { ', max. {0:N0} °C' -f ($temps | Measure-Object -Maximum).Maximum } else { '' }) }
    Set-HwResult 'Cpu' $st $sum ($out -join ' · ')
    $ui.HwCpuStatus.Text = 'Fertig: ' + ($out -join ' · ')
}

# ---------------------------------------------------------------- Akku-Test (3-Minuten-Messung ohne Netzteil)
$script:HwBatTimer = New-Object Windows.Threading.DispatcherTimer
$script:HwBatTimer.Interval = [TimeSpan]::FromSeconds(2)
$script:HwBatTimer.Add_Tick({ try { Update-HwBatMeasure } catch { $script:HwBatTimer.Stop(); $ui.HwBatStatus.Text = 'Messung abgebrochen: ' + $_.Exception.Message; $ui.BtnHwBatStart.IsEnabled = $true; $ui.BtnHwBatStop.IsEnabled = $false } })
$script:HwBat = $null
function Start-HwBat {
    if ($script:HwBat) { return }
    $s = Get-HwBatStatus
    if (-not $s) { Show-UiError 'Es wurde kein Akku gefunden (oder Windows liefert keine Akkuwerte). Bei Desktop-PCs entfällt der Akku-Test.'; return }
    if ($s.Remaining -le 0) { Show-UiError 'Der Akku meldet keine Restkapazität - eine Messung ist nicht möglich. Oft hilft ein Neustart oder das BIOS-/Firmware-Update des Herstellers.'; return }
    $script:HwBat = @{ Phase = 'wait'; T0 = Get-Date; Samples = [System.Collections.Generic.List[object]]::new(); Last = [datetime]::MinValue; Sec = 180 }
    $ui.BtnHwBatStart.IsEnabled = $false; $ui.BtnHwBatStop.IsEnabled = $true
    Update-HwBadge 'Bat' 'run'; $ui.HwBatProg.Value = 0; $ui.HwBatPct.Text = ''
    if ($s.Online) { $ui.HwBatStatus.Text = 'Bitte jetzt das Netzteil abziehen - die Messung beginnt automatisch (wartet bis zu 2 Minuten). Bildschirmhelligkeit und Programme wie im Alltag lassen.'; [Windows.MessageBox]::Show((T ('Bitte jetzt das Netzteil abziehen. Die 3-Minuten-Messung beginnt automatisch, sobald der Laptop im Akkubetrieb läuft.')), (T ('PC-Tools - Akku-Test')), 'OK', 'Information') | Out-Null }
    $script:HwBatTimer.Start()
    Update-HwBatMeasure
}
function Stop-HwBat([string]$Why) {
    $script:HwBatTimer.Stop(); $script:HwBat = $null
    $ui.BtnHwBatStart.IsEnabled = $true; $ui.BtnHwBatStop.IsEnabled = $false
    Update-HwBadge 'Bat'; $ui.HwBatStatus.Text = $Why
}
function Update-HwBatMeasure {
    $b = $script:HwBat; if (-not $b) { $script:HwBatTimer.Stop(); return }
    $s = Get-HwBatStatus
    if (-not $s) { Stop-HwBat 'Akkuwerte nicht mehr lesbar - Messung abgebrochen.'; return }
    $now = Get-Date
    if ($b.Phase -eq 'wait') {
        if (-not $s.Online) { $b.Phase = 'measure'; $b.T0 = $now; $b.Cap0 = $s.Remaining; $ui.HwBatStatus.Text = 'Messung läuft - Laptop bitte normal weiterbenutzen oder ruhen lassen, NICHT das Netzteil einstecken.' }
        elseif (($now - $b.T0).TotalSeconds -gt 120) { Stop-HwBat 'Das Netzteil wurde nicht abgezogen - Messung nicht gestartet.'; return }
        else { $ui.HwBatPct.Text = ''; return }
    }
    if ($s.Online) { Stop-HwBat 'Das Netzteil wurde wieder eingesteckt - Messung abgebrochen. Bitte erneut starten.'; return }
    $el = ($now - $b.T0).TotalSeconds
    if (($now - $b.Last).TotalSeconds -ge 4.5 -or $b.Samples.Count -eq 0) { $b.Last = $now; $b.Samples.Add([pscustomobject]@{ T = $el; Cap = $s.Remaining; Rate = $s.Rate; Volt = $s.Voltage }) }
    $pct = [int][math]::Min(100, $el * 100 / $b.Sec); $ui.HwBatProg.Value = $pct; $ui.HwBatPct.Text = '{0} %' -f $pct
    $pw = [System.Collections.Generic.List[object]]::new(); $ymax = 10
    foreach ($x in $b.Samples) { $w = $(if ($x.Rate -gt 0) { $x.Rate / 1000 } else { [double]::NaN }); $pw.Add(@($x.T, $w)); if ($w -gt $ymax) { $ymax = $w } }
    Update-HwChart -Canvas $ui.HwBatChart -Series @(@{ Name = 'Verbrauch laut Akku (Watt)'; Color = '#16A34A'; Points = $pw; Fill = $true }) -XMin 0 -XMax $b.Sec -YMax ([math]::Ceiling($ymax * 1.2 / 5) * 5) -YFmt '{0:N0} W' -XFmt { param($v) Format-HwDuration $v } -Empty 'Warte auf Akkubetrieb ...'
    $ui.HwBatNow.Text = '{0:N1} Wh geladen · Verbrauch {1} · noch {2}' -f ($s.Remaining / 1000), $(if ($s.Rate -gt 0) { '{0:N1} W' -f ($s.Rate / 1000) } else { 'wird ermittelt' }), (Format-HwDuration ($b.Sec - $el))
    if ($el -ge $b.Sec) { Complete-HwBat $s }
}
function Complete-HwBat($Now) {
    $b = $script:HwBat; $script:HwBatTimer.Stop(); $script:HwBat = $null
    $ui.BtnHwBatStart.IsEnabled = $true; $ui.BtnHwBatStop.IsEnabled = $false
    $d = $script:HwDev
    $hrs = [math]::Max(0.01, ($b.Samples[$b.Samples.Count - 1].T) / 3600)
    $rates = @($b.Samples | Where-Object { $_.Rate -gt 0 } | ForEach-Object { $_.Rate })
    $delta = $b.Cap0 - $Now.Remaining
    $pwr = if ($rates.Count) { ($rates | Measure-Object -Average).Average } elseif ($delta -gt 0) { $delta / $hrs } else { 0 }
    $des = if ($d) { [double]$d.BatDesign } else { 0 }; $full = if ($d) { [double]$d.BatFull } else { 0 }
    $health = if ($des -gt 0 -and $full -gt 0) { [math]::Min(100, $full * 100 / $des) } else { -1 }
    $st = if ($health -lt 0) { 'warn' } elseif ($health -ge 80) { 'ok' } elseif ($health -ge 60) { 'warn' } else { 'bad' }
    $parts = [System.Collections.Generic.List[string]]::new()
    if ($health -ge 0) { $parts.Add(('Zustand {0:N0} % ({1:N1} von {2:N1} Wh)' -f $health, ($full / 1000), ($des / 1000))) }
    if ($d -and $d.BatCycles -gt 0) { $parts.Add(('{0} Ladezyklen' -f $d.BatCycles)); if ($d.BatCycles -gt 1000 -and $st -eq 'ok') { $st = 'warn' } }
    if ($pwr -gt 0) {
        $parts.Add(('Verbrauch Ø {0:N1} W' -f ($pwr / 1000)))
        if ($full -gt 0) { $parts.Add(('volle Ladung reicht ca. {0} bei gleicher Nutzung' -f (Format-HwDuration ($full / $pwr * 3600)))) }
        $parts.Add(('aktuelle Ladung noch ca. {0}' -f (Format-HwDuration ($Now.Remaining / $pwr * 3600))))
    } else { $parts.Add('Verbrauch nicht messbar - der Akku meldet keine Entladewerte'); if ($st -eq 'ok') { $st = 'warn' } }
    $det = 'Messung {0} ohne Netzteil: Ladung {1:N2} -> {2:N2} Wh ({3:N0} mWh verbraucht), {4} Messpunkte, Spannung {5:N2} V.' -f (Format-HwDuration ($hrs * 3600)), ($b.Cap0 / 1000), ($Now.Remaining / 1000), $delta, $b.Samples.Count, ($Now.Voltage / 1000)
    Set-HwResult 'Bat' $st ($parts -join ', ') $det
    $ui.HwBatStatus.Text = 'Fertig: ' + ($parts -join ' · ') + '. Das Netzteil kann wieder eingesteckt werden.'
    Update-HwBatInfo
}
function Start-HwBatReport {
    $f = Join-Path $DataDir 'Akkubericht.html'
    $ui.HwBatStatus.Text = 'Akkubericht wird erstellt ...'
    $script:HwBatRepFile = $f
    Invoke-Bg -Script { param($p) $o = & powercfg.exe /batteryreport /output $p 2>&1; [pscustomobject]@{ Ok = (Test-Path -LiteralPath $p); Out = ($o -join ' ') } } -Arguments @($f) -Done {
        param($r, $err)
        $x = @($r | Where-Object { $_ })[0]
        if ($err -or -not $x -or -not $x.Ok) { $ui.HwBatStatus.Text = 'Akkubericht nicht möglich: ' + $(if ($err) { $err.Message } elseif ($x) { $x.Out } else { 'unbekannter Fehler' }); return }
        $ui.HwBatStatus.Text = 'Akkubericht gespeichert: ' + $script:HwBatRepFile
        try { Start-Process -FilePath $script:HwBatRepFile } catch { }
    }
}

# ---------------------------------------------------------------- Bildschirm-Pixeltest (Vollbild) und Pixel-Wiederbeleber
function Show-HwDisplayTest {
    $bc = New-Object Windows.Media.BrushConverter
    $ns = 'xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"'
    $mkGrad = { param($from, $to, $vert) [Windows.Markup.XamlReader]::Parse(('<LinearGradientBrush {0} StartPoint="0,0" EndPoint="{3}"><GradientStop Color="{1}" Offset="0"/><GradientStop Color="{2}" Offset="1"/></LinearGradientBrush>' -f $ns, $from, $to, $(if ($vert) { '0,1' } else { '1,0' }))) }
    $steps = New-Object Windows.Controls.Primitives.UniformGrid; $steps.Columns = 16
    for ($i = 0; $i -lt 16; $i++) { $v = [int]($i * 17); $bd = New-Object Windows.Controls.Border; $bd.Background = $bc.ConvertFromString(('#{0:X2}{0:X2}{0:X2}' -f $v)); [void]$steps.Children.Add($bd) }
    $ramps = New-Object Windows.Controls.Primitives.UniformGrid; $ramps.Rows = 4
    foreach ($c in '#FF0000', '#00FF00', '#0000FF', '#FFFFFF') { $bd = New-Object Windows.Controls.Border; $bd.Background = & $mkGrad '#000000' $c $false; [void]$ramps.Children.Add($bd) }
    $grid = [Windows.Markup.XamlReader]::Parse(('<DrawingBrush {0} TileMode="Tile" Viewport="0,0,48,48" ViewportUnits="Absolute"><DrawingBrush.Drawing><GeometryDrawing Brush="#000000"><GeometryDrawing.Pen><Pen Brush="#FFFFFF" Thickness="1"/></GeometryDrawing.Pen><GeometryDrawing.Geometry><RectangleGeometry Rect="0.5,0.5,48,48"/></GeometryDrawing.Geometry></GeometryDrawing></DrawingBrush.Drawing></DrawingBrush>' -f $ns))
    $check = [Windows.Markup.XamlReader]::Parse(('<DrawingBrush {0} TileMode="Tile" Viewport="0,0,2,2" ViewportUnits="Absolute"><DrawingBrush.Drawing><DrawingGroup><GeometryDrawing Brush="#FFFFFF" Geometry="M0,0 H2 V2 H0Z"/><GeometryDrawing Brush="#000000" Geometry="M0,0 H1 V1 H0Z M1,1 H2 V2 H1Z"/></DrawingGroup></DrawingBrush.Drawing></DrawingBrush>' -f $ns))
    $pats = @(
        @{ N = 'Schwarz'; H = 'Helle Punkte = Pixel hängt an (heller Pixelfehler). Helle Flecken am Rand = Lichthof (Backlight-Bleeding).'; B = $bc.ConvertFromString('#000000') },
        @{ N = 'Weiß'; H = 'Dunkle Punkte = toter Pixel. Gelbstich, Wolken oder dunklere Ecken = ungleichmäßige Ausleuchtung.'; B = $bc.ConvertFromString('#FFFFFF') },
        @{ N = 'Rot'; H = 'Andersfarbige Punkte = hängender Subpixel (Grün/Blau).'; B = $bc.ConvertFromString('#FF0000') },
        @{ N = 'Grün'; H = 'Andersfarbige Punkte = hängender Subpixel (Rot/Blau).'; B = $bc.ConvertFromString('#00FF00') },
        @{ N = 'Blau'; H = 'Andersfarbige Punkte = hängender Subpixel (Rot/Grün).'; B = $bc.ConvertFromString('#0000FF') },
        @{ N = 'Grau 50 %'; H = 'Flecken, Schlieren (Mura) oder Streifen fallen auf Grau besonders auf.'; B = $bc.ConvertFromString('#808080') },
        @{ N = 'Grauverlauf'; H = 'Der Verlauf sollte gleichmäßig sein - sichtbare Stufen/Bänder deuten auf schwache Farbtiefe oder falsche Einstellungen hin.'; B = (& $mkGrad '#000000' '#FFFFFF' $false) },
        @{ N = '16 Graustufen'; H = 'Alle 16 Felder sollten unterscheidbar sein - auch die beiden dunkelsten und hellsten.'; B = $null; E = $steps },
        @{ N = 'Farbverläufe'; H = 'Rot, Grün, Blau und Weiß von dunkel nach hell - ohne Farbstich und ohne harte Stufen.'; B = $null; E = $ramps },
        @{ N = 'Raster'; H = 'Linien sollten gerade, scharf und überall gleich hell sein (Geometrie, Schärfe, Ränder).'; B = $grid },
        @{ N = 'Feines Schachbrett'; H = 'Flimmern, Moiré oder Streifen = Probleme mit Ansteuerung, Kabel oder Skalierung.'; B = $check }
    )
    $w = New-Object Windows.Window; $w.WindowStyle = 'None'; $w.WindowState = 'Maximized'; $w.ResizeMode = 'NoResize'; $w.Topmost = $true; $w.Background = $bc.ConvertFromString('#000000'); $w.Cursor = [Windows.Input.Cursors]::None; $w.Title = 'PC-Tools - Bildschirm-Pixeltest'
    $root = New-Object Windows.Controls.Grid
    $stage = New-Object Windows.Controls.Border; [Windows.Media.RenderOptions]::SetEdgeMode($stage, 'Aliased'); [void]$root.Children.Add($stage)
    $intro = New-Object Windows.Controls.TextBlock; $intro.Foreground = $bc.ConvertFromString('#FFFFFF'); $intro.FontSize = 22; $intro.TextAlignment = 'Center'; $intro.HorizontalAlignment = 'Center'; $intro.VerticalAlignment = 'Center'; $intro.TextWrapping = 'Wrap'; $intro.MaxWidth = 900
    $intro.Text = ("Bildschirm-Pixeltest`n`n{0} Testbilder. Weiter: Klick, Leertaste, → oder ↓.   Zurück: Rechtsklick, ← oder ↑.   H: Hinweis ein/aus.   Esc: Ende.`n`nAus etwa 50 cm Abstand und aus leicht seitlichem Winkel schauen. Den Bildschirm vorher reinigen - Staub sieht aus wie ein Pixelfehler." -f $pats.Count)
    $stage.Child = $intro
    $hint = New-Object Windows.Controls.Border; $hint.Background = $bc.ConvertFromString('#D0101418'); $hint.CornerRadius = '12'; $hint.Padding = '18,10'; $hint.HorizontalAlignment = 'Center'; $hint.VerticalAlignment = 'Bottom'; $hint.Margin = '0,0,0,40'; $hint.MaxWidth = 900; $hint.Visibility = 'Collapsed'
    $hintT = New-Object Windows.Controls.TextBlock; $hintT.Foreground = $bc.ConvertFromString('#FFFFFF'); $hintT.FontSize = 15; $hintT.TextWrapping = 'Wrap'; $hintT.TextAlignment = 'Center'; $hint.Child = $hintT
    [void]$root.Children.Add($hint)
    $w.Content = $root
    $script:HwDispIdx = -1; $script:HwDispHintAlways = $false
    $hideT = New-Object Windows.Threading.DispatcherTimer; $hideT.Interval = [TimeSpan]::FromSeconds(3)
    $hideT.Add_Tick({ $hideT.Stop(); if (-not $script:HwDispHintAlways) { $hint.Visibility = 'Collapsed' } })
    $show = {
        param([int]$Step)
        $n = $script:HwDispIdx + $Step
        if ($n -ge $pats.Count) { $w.Close(); return }
        if ($n -lt 0) { $n = 0 }
        $script:HwDispIdx = $n; $p = $pats[$n]
        $stage.Child = $null; $stage.Background = $(if ($p.B) { $p.B } else { $bc.ConvertFromString('#000000') }); if ($p.E) { $stage.Child = $p.E }
        $hintT.Text = ('{0} / {1}:  {2}' -f ($n + 1), $pats.Count, $p.N) + "`n" + $p.H + "`nWeiter: Klick/Leertaste/→   Zurück: ←   Hinweis dauerhaft: H   Ende: Esc"
        $hint.Visibility = 'Visible'; $hideT.Stop(); $hideT.Start()
    }
    $w.Add_MouseLeftButtonUp({ & $show 1 })
    $w.Add_MouseRightButtonUp({ & $show -1 })
    $w.Add_KeyDown({ param($s, $e)
        switch ([string]$e.Key) {
            'Escape' { $w.Close() }
            { $_ -in 'Space', 'Right', 'Down', 'Next', 'Return', 'Enter' } { & $show 1 }
            { $_ -in 'Left', 'Up', 'PageUp', 'Prior', 'Back' } { & $show -1 }
            'H' { $script:HwDispHintAlways = -not $script:HwDispHintAlways; $hint.Visibility = $(if ($script:HwDispHintAlways) { 'Visible' } else { 'Collapsed' }) }
        }
        $e.Handled = $true })
    try { $w.Owner = $window } catch { }
    [void]$w.ShowDialog(); $hideT.Stop()
    $seen = $script:HwDispIdx + 1
    if ($seen -le 0) { $ui.HwDispStatus.Text = 'Test beendet, bevor ein Testbild gezeigt wurde.'; return }
    $a = [Windows.MessageBox]::Show((T (("{0} von {1} Testbildern angesehen.`n`nWar der Bildschirm überall einwandfrei - keine hellen/dunklen Punkte, Flecken, Streifen oder Lichthöfe?`n`nJa = einwandfrei   Nein = Fehler gefunden   Abbrechen = nicht bewerten" -f $seen, $pats.Count))), (T ('PC-Tools - Bildschirm-Pixeltest')), 'YesNoCancel', 'Question')
    if ($a -eq 'Yes') { Set-HwResult 'Disp' $(if ($seen -ge $pats.Count) { 'ok' } else { 'warn' }) $(if ($seen -ge $pats.Count) { 'alle {0} Testbilder einwandfrei' -f $pats.Count } else { '{0} von {1} Testbildern einwandfrei (nicht alle angesehen)' -f $seen, $pats.Count }) ('Geprüft: ' + (($pats | Select-Object -First $seen | ForEach-Object { $_.N }) -join ', ')); return }
    if ($a -ne 'No') { return }
    $r = Show-InputDialog 'Bildschirm-Pixeltest' 'Was ist aufgefallen?' @(
        @{ Key = 'Kind'; Label = 'Art des Fehlers'; Type = 'Combo'; Items = @('Einzelner Pixelfehler (heller oder toter Punkt)', 'Mehrere Pixelfehler', 'Lichthof / ungleichmäßige Ausleuchtung', 'Flecken, Schlieren oder Druckstellen', 'Streifen, Linien oder Flimmern', 'Sonstiges') },
        @{ Key = 'Where'; Label = 'Wo und bei welchem Testbild? (z.B. "oben rechts, auf Schwarz hell")'; Type = 'Text'; Value = '' })
    if (-not $r) { return }
    $kind = [string]$r.Kind
    $st = if ($kind -match '^Einzelner|^Lichthof') { 'warn' } else { 'bad' }
    Set-HwResult 'Disp' $st ($kind + $(if ($r.Where) { ': ' + $r.Where } else { '' })) ('{0} von {1} Testbildern angesehen. Hinweis: Ein einzelner Pixelfehler gilt bei vielen Herstellern (ISO 9241-307, Pixelfehlerklasse II) noch nicht als Mangel; hängende Pixel lassen sich manchmal mit dem Pixel-Wiederbeleber lösen.' -f $seen, $pats.Count)
}
function Show-HwPixelReviver {
    if ($script:HwReviver) { try { $script:HwReviver.Activate() | Out-Null; return } catch { } }
    if (-not (Confirm-Ui ("Der Pixel-Wiederbeleber zeigt ein kleines, sehr schnell blinkendes Farbquadrat. Es kann einen hängenden (farbigen oder hellen) Pixel manchmal wieder lösen - tote (schwarze) Pixel nicht.`n`nACHTUNG: schnelles Flackern kann bei lichtempfindlichen Menschen epileptische Anfälle auslösen. Nicht direkt hineinschauen.`n`nBedienung: Quadrat mit der Maus auf den Pixelfehler ziehen, Mausrad = Größe, Rechtsklick oder Esc = beenden. 10-30 Minuten laufen lassen, bei Bedarf mehrmals wiederholen.`n`nStarten?") 'Warning')) { return }
    $bc = New-Object Windows.Media.BrushConverter
    $rv = New-Object Windows.Window; $rv.WindowStyle = 'None'; $rv.ResizeMode = 'NoResize'; $rv.Topmost = $true; $rv.ShowInTaskbar = $true; $rv.Width = 90; $rv.Height = 90; $rv.WindowStartupLocation = 'CenterScreen'; $rv.Title = 'PC-Tools - Pixel-Wiederbeleber'; $rv.Cursor = [Windows.Input.Cursors]::SizeAll
    $rv.ToolTip = 'Auf den Pixelfehler ziehen · Mausrad = Größe · Rechtsklick/Esc = beenden'
    $script:HwReviver = $rv; $script:HwRevBrushes = @('#FF0000', '#00FF00', '#0000FF', '#FFFFFF', '#000000', '#FFFF00', '#00FFFF', '#FF00FF') | ForEach-Object { $b = $bc.ConvertFromString($_); $b.Freeze(); $b }
    $script:HwRevRnd = New-Object Random; $script:HwRevStart = Get-Date
    $script:HwRevTimer = New-Object Windows.Threading.DispatcherTimer; $script:HwRevTimer.Interval = [TimeSpan]::FromMilliseconds(33)
    $script:HwRevTimer.Add_Tick({ if ($script:HwReviver) { $script:HwReviver.Background = $script:HwRevBrushes[$script:HwRevRnd.Next(0, $script:HwRevBrushes.Count)] } })
    $rv.Add_MouseLeftButtonDown({ param($s, $e) try { $s.DragMove() } catch { } })
    $rv.Add_MouseRightButtonUp({ param($s, $e) $s.Close() })
    $rv.Add_KeyDown({ param($s, $e) if ($e.Key -eq 'Escape') { $s.Close() } })
    $rv.Add_MouseWheel({ param($s, $e) $n = [math]::Max(12, [math]::Min(600, $s.Width + $(if ($e.Delta -gt 0) { 10 } else { -10 }))); $s.Width = $n; $s.Height = $n })
    $rv.Add_Closed({ try { $script:HwRevTimer.Stop() } catch { }; $script:HwReviver = $null; $ui.HwDispStatus.Text = 'Pixel-Wiederbeleber beendet nach {0}. Danach den Pixeltest wiederholen.' -f (Format-HwDuration ((Get-Date) - $script:HwRevStart).TotalSeconds) })
    $rv.Show(); $script:HwRevTimer.Start()
    $ui.HwDispStatus.Text = 'Pixel-Wiederbeleber läuft - Quadrat auf den Pixelfehler ziehen.'
}

