function Show-HwKeyboardTest {
    $u = 46
    $bd0 = New-UiBrush '#C5CEDD'; $bg0 = New-UiBrush 'White'; $fg0 = New-UiBrush '#1F2A44'
    $bgOk = New-UiBrush '#DCFCE7'; $bdOk = New-UiBrush '#16A34A'; $bgDown = (New-Object Windows.Media.BrushConverter).ConvertFromString('#2D7FF9'); $fgDown = (New-Object Windows.Media.BrushConverter).ConvertFromString('#FFFFFF')
    $cv = New-Object Windows.Controls.Canvas; $cv.Width = 23 * $u; $cv.Height = 6.5 * $u; $cv.Margin = '0,6,0,10'
    $keys = @{}; $main = [System.Collections.Generic.HashSet[string]]::new(); $opt = [System.Collections.Generic.HashSet[string]]::new(); $idByInt = @{}
    foreach ($spec in $HwKbdLayout) {
        $f = $spec -split '\|'
        $id = $f[0]; $kx = [double]$f[2]; $ky = [double]$f[3]
        $kw = if ($f.Count -gt 4) { [double]$f[4] } else { 1 }; $kh = if ($f.Count -gt 5) { [double]$f[5] } else { 1 }
        $b = New-Object Windows.Controls.Border; $b.Width = $kw * $u - 4; $b.Height = $kh * $u - 4; $b.CornerRadius = '6'; $b.BorderThickness = '1'; $b.BorderBrush = $bd0; $b.Background = $bg0
        $t = New-Object Windows.Controls.TextBlock; $t.Text = $f[1]; $t.FontSize = $(if ($f[1].Length -gt 4) { 10.5 } else { 13 }); $t.Foreground = $fg0; $t.HorizontalAlignment = 'Center'; $t.VerticalAlignment = 'Center'; $t.TextAlignment = 'Center'; $t.TextWrapping = 'Wrap'; $b.Child = $t
        [Windows.Controls.Canvas]::SetLeft($b, $kx * $u + 2); [Windows.Controls.Canvas]::SetTop($b, $ky * $u + 2); [void]$cv.Children.Add($b)
        if (-not $keys.ContainsKey($id)) { $keys[$id] = [System.Collections.Generic.List[object]]::new() }; $keys[$id].Add($b)
        if ($f.Count -gt 6 -and $f[6] -eq 'o') { [void]$opt.Add($id) } else { [void]$main.Add($id) }
        if ($id -ne 'NumEnter') { try { $idByInt[[int][Windows.Input.Key]$id] = $id } catch { } }
    }
    $idByInt[[int][Windows.Input.Key]::Clear] = 'Clear'
    $numMap = @{ Insert = 'NumPad0'; End = 'NumPad1'; Down = 'NumPad2'; Next = 'NumPad3'; Left = 'NumPad4'; Clear = 'NumPad5'; Right = 'NumPad6'; Home = 'NumPad7'; Up = 'NumPad8'; PageUp = 'NumPad9'; Delete = 'Decimal' }
    $extProp = [Windows.Input.KeyEventArgs].GetProperty('IsExtendedKey', [Reflection.BindingFlags]'NonPublic, Instance')
    $w = New-Object Windows.Window; $w.Title = 'PC-Tools - Tastatur-Test'; $w.SizeToContent = 'WidthAndHeight'; $w.ResizeMode = 'CanMinimize'; $w.WindowStartupLocation = 'CenterOwner'; $w.Background = New-UiBrush '#F4F6FA'; $w.FontFamily = 'Segoe UI'
    try { $w.Owner = $window } catch { }
    $root = New-Object Windows.Controls.StackPanel; $root.Margin = '20,16'
    $hd = New-HwText 'Jede Taste einmal drücken - gedrückte Tasten werden grün, eine gerade gehaltene Taste blau. Bleibt eine Taste blau, obwohl sie losgelassen ist, klemmt sie.' 13 '#1F2A44'; $hd.TextWrapping = 'Wrap'; $hd.MaxWidth = 23 * $u; [void]$root.Children.Add($hd)
    [void]$root.Children.Add($cv)
    $cnt = New-HwText '' 16 '#1F2A44'; $cnt.FontWeight = 'SemiBold'; [void]$root.Children.Add($cnt)
    $lastT = New-HwText '' 12.5 '#475569'; $lastT.TextWrapping = 'Wrap'; $lastT.MaxWidth = 23 * $u; $lastT.Margin = '0,6,0,0'; [void]$root.Children.Add($lastT)
    $unkT = New-HwText '' 12 '#6B7890'; $unkT.TextWrapping = 'Wrap'; $unkT.MaxWidth = 23 * $u; $unkT.Margin = '0,4,0,0'; [void]$root.Children.Add($unkT)
    $tip = New-HwText 'Hinweise: Die Fn-Taste allein meldet Windows nicht. AltGr meldet Windows als Strg links + AltGr. Druck wird erst beim Loslassen erkannt. Ohne Num-Taste liefert der Ziffernblock Pfeil-/Navigationstasten - PC-Tools ordnet sie trotzdem richtig zu. Windows-Taste und Tastenkombinationen können Windows-Funktionen auslösen.' 11.5 '#6B7890'; $tip.TextWrapping = 'Wrap'; $tip.MaxWidth = 23 * $u; $tip.Margin = '0,8,0,0'; [void]$root.Children.Add($tip)
    $bp = New-Object Windows.Controls.StackPanel; $bp.Orientation = 'Horizontal'; $bp.HorizontalAlignment = 'Right'; $bp.Margin = '0,12,0,0'
    $bReset = New-Object Windows.Controls.Button; $bReset.Content = 'Zurücksetzen'; $bReset.Padding = '14,6'; $bReset.Margin = '0,0,8,0'; $bReset.Focusable = $false
    $bDone = New-Object Windows.Controls.Button; $bDone.Content = 'Fertig'; $bDone.Padding = '22,6'; $bDone.Focusable = $false
    [void]$bp.Children.Add($bReset); [void]$bp.Children.Add($bDone); [void]$root.Children.Add($bp)
    $w.Content = $root
    $script:HwKbdHit = @{}; $script:HwKbdUnknown = [System.Collections.Generic.List[string]]::new(); $script:HwKbdLast = [System.Collections.Generic.List[string]]::new(); $script:HwKbdPresses = 0
    $upd = {
        $mh = @($main | Where-Object { $script:HwKbdHit.ContainsKey($_) }).Count; $oh = @($opt | Where-Object { $script:HwKbdHit.ContainsKey($_) }).Count
        $cnt.Text = 'Haupttasten: {0} von {1}   ·   Navigation/Ziffernblock: {2} von {3}   ·   Tastendrücke: {4}' -f $mh, $main.Count, $oh, $opt.Count, $script:HwKbdPresses
        $lastT.Text = if ($script:HwKbdLast.Count) { 'Zuletzt: ' + ($script:HwKbdLast -join '  ·  ') } else { 'Zuletzt: -' }
        $unkT.Text = if ($script:HwKbdUnknown.Count) { 'Weitere erkannte Tasten (nicht im Bild): ' + ($script:HwKbdUnknown -join ', ') } else { '' }
    }
    & $upd
    $resolve = {
        param($e)
        $k = $e.Key
        if ($k -eq [Windows.Input.Key]::System) { $k = $e.SystemKey } elseif ($k -eq [Windows.Input.Key]::ImeProcessed) { $k = $e.ImeProcessedKey } elseif ($k -eq [Windows.Input.Key]::DeadCharProcessed) { $k = $e.DeadCharProcessedKey }
        $ext = $null; if ($extProp) { try { $ext = [bool]$extProp.GetValue($e, $null) } catch { } }
        $id = $idByInt[[int]$k]
        if ($id -eq 'Return' -and $ext -eq $true) { $id = 'NumEnter' }
        if ($id -and $ext -eq $false -and $numMap.ContainsKey($id)) { $id = $numMap[$id] }
        if (-not $id) { $id = '?' + [string]$k }
        return $id
    }
    $press = {
        param($id, [bool]$down)
        $nm = if ($id.StartsWith('?')) { $id.Substring(1) } elseif ($HwKbdNames.ContainsKey($id)) { $HwKbdNames[$id] } else { $id -replace '^D(\d)$', '$1' -replace '^NumPad(\d)$', 'Ziffernblock $1' }
        if ($id.StartsWith('?')) { if (-not $script:HwKbdUnknown.Contains($nm)) { $script:HwKbdUnknown.Add($nm) } }
        elseif ($keys.ContainsKey($id)) {
            foreach ($b in $keys[$id]) { if ($down) { $b.Background = $bgDown; $b.BorderBrush = $bgDown; $b.Child.Foreground = $fgDown } else { $b.Background = $bgOk; $b.BorderBrush = $bdOk; $b.Child.Foreground = $fg0 } }
            if (-not $down) { $script:HwKbdHit[$id] = $true }
        }
        if ($down -or $id -eq 'Snapshot') { $script:HwKbdPresses++; $script:HwKbdLast.Insert(0, $nm); while ($script:HwKbdLast.Count -gt 14) { $script:HwKbdLast.RemoveAt($script:HwKbdLast.Count - 1) } }
        & $upd
    }
    $w.Add_PreviewKeyDown({ param($s, $e) $id = & $resolve $e; if (-not $e.IsRepeat) { & $press $id $true }; $e.Handled = $true })
    $w.Add_PreviewKeyUp({ param($s, $e) $id = & $resolve $e; & $press $id $false; $e.Handled = $true })
    $bReset.Add_Click({ $script:HwKbdHit = @{}; $script:HwKbdUnknown.Clear(); $script:HwKbdLast.Clear(); $script:HwKbdPresses = 0; foreach ($l in $keys.Values) { foreach ($b in $l) { $b.Background = $bg0; $b.BorderBrush = $bd0; $b.Child.Foreground = $fg0 } }; & $upd })
    $bDone.Add_Click({ $w.Close() })
    $w.Add_ContentRendered({ $w.Activate() | Out-Null; $w.Focus() | Out-Null })
    [void]$w.ShowDialog()
    $mh = @($main | Where-Object { $script:HwKbdHit.ContainsKey($_) }).Count; $oh = @($opt | Where-Object { $script:HwKbdHit.ContainsKey($_) }).Count
    $miss = @($main | Where-Object { -not $script:HwKbdHit.ContainsKey($_) } | ForEach-Object { if ($HwKbdNames.ContainsKey($_)) { $HwKbdNames[$_] } else { $_ -replace '^D(\d)$', '$1' } })
    if ($script:HwKbdPresses -eq 0) { $ui.HwKbdStatus.Text = 'Keine Taste gedrückt - Test nicht bewertet.'; return }
    $det = 'Haupttasten {0}/{1}, Navigation/Ziffernblock {2}/{3}, {4} Tastendrücke.{5}{6}' -f $mh, $main.Count, $oh, $opt.Count, $script:HwKbdPresses, $(if ($miss.Count) { ' Nicht erkannt: ' + ($miss -join ', ') + '.' } else { '' }), $(if ($script:HwKbdUnknown.Count) { ' Zusätzlich: ' + ($script:HwKbdUnknown -join ', ') + '.' } else { '' })
    if (-not $miss.Count) { Set-HwResult 'Kbd' 'ok' ('alle {0} Haupttasten funktionieren{1}' -f $main.Count, $(if ($oh) { ', dazu {0} Navigations-/Ziffernblocktasten' -f $oh } else { '' })) $det; return }
    $a = [Windows.MessageBox]::Show((T (("{0} Haupttaste(n) wurden nicht erkannt:`n{1}`n`nLiegt das nur daran, dass du sie nicht gedrückt hast bzw. die Tastatur sie nicht hat?`n`nJa = Tastatur in Ordnung   Nein = diese Tasten sind defekt   Abbrechen = nicht bewerten" -f $miss.Count, ($miss -join ', ')))), (T ('PC-Tools - Tastatur-Test')), 'YesNoCancel', 'Question')
    if ($a -eq 'Yes') { Set-HwResult 'Kbd' 'ok' ('{0} von {1} Haupttasten geprüft, Rest nicht vorhanden/nicht gedrückt' -f $mh, $main.Count) $det }
    elseif ($a -eq 'No') { Set-HwResult 'Kbd' 'bad' ('{0} Taste(n) reagieren nicht: {1}' -f $miss.Count, ($miss -join ', ')) $det }
}

# ---------------------------------------------------------------- Touch/Stift-Test (Vollbild-Zeichenfläche mit Abdeckungsraster)
function Show-HwTouchTest {
    $bc = New-Object Windows.Media.BrushConverter
    $cols = 16; $rows = 10
    $w = New-Object Windows.Window; $w.WindowStyle = 'None'; $w.WindowState = 'Maximized'; $w.ResizeMode = 'NoResize'; $w.Topmost = $true; $w.Background = $bc.ConvertFromString('#0F172A'); $w.Title = 'PC-Tools - Touch/Stift-Test'
