    [void]$root.Children.Add($ug)
    $ink = New-Object Windows.Controls.InkCanvas; $ink.Background = [Windows.Media.Brushes]::Transparent
    $ink.DefaultDrawingAttributes.Color = [Windows.Media.ColorConverter]::ConvertFromString('#38BDF8'); $ink.DefaultDrawingAttributes.Width = 5; $ink.DefaultDrawingAttributes.Height = 5; $ink.DefaultDrawingAttributes.IgnorePressure = $false; $ink.DefaultDrawingAttributes.FitToCurve = $true
    [void]$root.Children.Add($ink)
    $bar = New-Object Windows.Controls.Border; $bar.Background = $bc.ConvertFromString('#E60F172A'); $bar.CornerRadius = '12'; $bar.Padding = '16,10'; $bar.Margin = '0,16,0,0'; $bar.HorizontalAlignment = 'Center'; $bar.VerticalAlignment = 'Top'
    $bsp = New-Object Windows.Controls.StackPanel; $bsp.Orientation = 'Horizontal'
    $info = New-Object Windows.Controls.TextBlock; $info.Foreground = $bc.ConvertFromString('#FFFFFF'); $info.FontSize = 15; $info.VerticalAlignment = 'Center'; $info.Margin = '0,0,16,0'
    $bClr = New-Object Windows.Controls.Button; $bClr.Content = 'Löschen (C)'; $bClr.Padding = '12,5'; $bClr.Margin = '0,0,8,0'; $bClr.Focusable = $false
    $bEnd = New-Object Windows.Controls.Button; $bEnd.Content = 'Fertig (Esc)'; $bEnd.Padding = '12,5'; $bEnd.Focusable = $false
    [void]$bsp.Children.Add($info); [void]$bsp.Children.Add($bClr); [void]$bsp.Children.Add($bEnd); $bar.Child = $bsp
    [void]$root.Children.Add($bar)
    $w.Content = $root
    $script:HwTouch = @{ Hit = New-Object 'bool[]' ($cols * $rows); Count = 0; Kinds = @{}; Pressures = [System.Collections.Generic.HashSet[int]]::new(); PMax = 0.0; PCur = -1.0; Touches = 0; MaxTouches = 0 }
    $upd = {
        $t = $script:HwTouch; $pct = $t.Count * 100.0 / $cells.Length
        $info.Text = 'Überall hinmalen - Abdeckung {0:N0} %  ·  Eingabe: {1}  ·  Andruck: {2}  ·  gleichzeitige Finger (max.): {3}' -f $pct, $(if ($t.Kinds.Count) { ($t.Kinds.Keys | Sort-Object) -join ', ' } else { '-' }), $(if ($t.PCur -ge 0) { '{0:N0} %' -f ($t.PCur * 100) } else { '-' }), $t.MaxTouches
    }
    $mark = {
        param([Windows.Point]$p)
        $aw = $ink.ActualWidth; $ah = $ink.ActualHeight; if ($aw -le 0 -or $ah -le 0) { return }
        $cx = [int][math]::Floor($p.X / $aw * $cols); $cy = [int][math]::Floor($p.Y / $ah * $rows)
        if ($cx -lt 0 -or $cy -lt 0 -or $cx -ge $cols -or $cy -ge $rows) { return }
        $ix = $cy * $cols + $cx
        if (-not $script:HwTouch.Hit[$ix]) { $script:HwTouch.Hit[$ix] = $true; $script:HwTouch.Count++; $cells[$ix].Background = $cOn }
    }
    $ink.Add_PreviewMouseMove({ param($s, $e) if ($e.StylusDevice -eq $null -and $e.LeftButton -eq 'Pressed') { $script:HwTouch.Kinds['Maus'] = 1; & $mark ($e.GetPosition($ink)); & $upd } })
    $ink.Add_PreviewMouseLeftButtonDown({ param($s, $e) if ($e.StylusDevice -eq $null) { $script:HwTouch.Kinds['Maus'] = 1; & $mark ($e.GetPosition($ink)); & $upd } })
    $stylusH = {
        param($s, $e)
        $kind = 'Stift'; try { if ([string]$e.StylusDevice.TabletDevice.Type -eq 'Touch') { $kind = 'Finger' } } catch { }
        $script:HwTouch.Kinds[$kind] = 1
        foreach ($sp in $e.GetStylusPoints($ink)) {
            & $mark (New-Object Windows.Point($sp.X, $sp.Y))
            if ($kind -eq 'Stift') { $pf = [double]$sp.PressureFactor; $script:HwTouch.PCur = $pf; if ($pf -gt $script:HwTouch.PMax) { $script:HwTouch.PMax = $pf }; [void]$script:HwTouch.Pressures.Add([int]($pf * 100)) }
        }
        & $upd
    }
    $ink.Add_PreviewStylusDown($stylusH); $ink.Add_PreviewStylusMove($stylusH)
    $ink.Add_PreviewTouchDown({ param($s, $e) $script:HwTouch.Touches++; if ($script:HwTouch.Touches -gt $script:HwTouch.MaxTouches) { $script:HwTouch.MaxTouches = $script:HwTouch.Touches }; & $upd })
    $ink.Add_PreviewTouchUp({ param($s, $e) $script:HwTouch.Touches = [math]::Max(0, $script:HwTouch.Touches - 1) })
    $clear = { $ink.Strokes.Clear(); for ($i = 0; $i -lt $cells.Length; $i++) { $cells[$i].Background = $cOff; $script:HwTouch.Hit[$i] = $false }; $script:HwTouch.Count = 0; & $upd }
    $bClr.Add_Click({ & $clear }); $bEnd.Add_Click({ $w.Close() })
    $w.Add_PreviewKeyDown({ param($s, $e) if ($e.Key -eq 'Escape') { $w.Close(); $e.Handled = $true } elseif ($e.Key -eq 'C') { & $clear; $e.Handled = $true } })
    & $upd
    try { $w.Owner = $window } catch { }
    [void]$w.ShowDialog()
    $t = $script:HwTouch; $pct = [math]::Round($t.Count * 100.0 / $cells.Length, 0)
    if ($t.Count -eq 0) { $ui.HwTouchStatus.Text = 'Nichts gezeichnet - Test nicht bewertet.'; return }
    $kinds = if ($t.Kinds.Count) { ($t.Kinds.Keys | Sort-Object) -join ', ' } else { '-' }
    $penTxt = if ($t.Kinds.ContainsKey('Stift')) { $(if ($t.Pressures.Count -ge 10) { ' Stift-Andruck funktioniert ({0} Druckstufen gesehen, max. {1:N0} %).' -f $t.Pressures.Count, ($t.PMax * 100) } else { ' Stift-Andruck kaum verändert ({0} Druckstufen) - Stift ohne Drucksensor, Treiber fehlt oder nicht unterschiedlich fest gedrückt.' -f $t.Pressures.Count }) } else { '' }
    $det = 'Abdeckung {0} % ({1} von {2} Feldern), Eingabe per {3}, max. {4} gleichzeitige Berührung(en).{5}' -f $pct, $t.Count, $cells.Length, $kinds, $t.MaxTouches, $penTxt
    if (-not ($t.Kinds.ContainsKey('Finger') -or $t.Kinds.ContainsKey('Stift'))) { $det += ' Nur mit der Maus getestet - Touch/Stift damit nicht geprüft.' }
    if ($pct -ge 95) { Set-HwResult 'Touch' $(if ($t.Kinds.ContainsKey('Finger') -or $t.Kinds.ContainsKey('Stift')) { 'ok' } else { 'warn' }) ('{0} % der Fläche reagiert ({1})' -f $pct, $kinds) $det; return }
    $a = [Windows.MessageBox]::Show((T (("Es wurden {0} % der Felder erreicht.`n`nGab es Stellen, die trotz Berührung NICHT reagiert haben?`n`nJa = es gibt tote Bereiche (Fehler)   Nein = nur nicht überall gemalt (Warnung)   Abbrechen = nicht bewerten" -f $pct))), (T ('PC-Tools - Touch/Stift-Test')), 'YesNoCancel', 'Question')
    if ($a -eq 'Yes') { Set-HwResult 'Touch' 'bad' ('Bereiche reagieren nicht (Abdeckung {0} %)' -f $pct) $det }
    elseif ($a -eq 'No') { Set-HwResult 'Touch' 'warn' ('nur {0} % der Fläche geprüft ({1})' -f $pct, $kinds) $det }
}

# ---------------------------------------------------------------- Prüfprotokoll (PDF)
function Export-HwReport {
    if (-not $script:HwDev) { Update-HwDevice; Show-UiError 'Die Gerätedaten werden gerade gelesen - bitte in ein paar Sekunden noch einmal klicken.'; return }
    $inp = Show-InputDialog 'Prüfprotokoll' 'Angaben für das Protokoll (alles optional):' @(
        @{ Key = 'Tester'; Label = 'Geprüft von'; Type = 'Text'; Value = $env:USERNAME },
        @{ Key = 'Recipient'; Label = 'Übergabe an / Käufer'; Type = 'Text'; Value = '' },
        @{ Key = 'Place'; Label = 'Ort'; Type = 'Text'; Value = '' },
        @{ Key = 'Note'; Label = 'Bemerkungen (z.B. Zubehör, optischer Zustand, Kratzer)'; Type = 'Text'; Value = '' })
    if (-not $inp) { return }
    Add-Type -AssemblyName System.Windows.Forms
    $sd = New-Object System.Windows.Forms.SaveFileDialog; $sd.Filter = 'PDF (*.pdf)|*.pdf|Webseite (*.html)|*.html'; $sd.FileName = ('Hardware-Pruefprotokoll_{0}_{1:yyyy-MM-dd}.pdf' -f $env:COMPUTERNAME, (Get-Date))
    if ($sd.ShowDialog() -ne 'OK') { return }
    $E = { param($s) ConvertTo-HtmlText $s }
    $d = $script:HwDev
    $vals = @($HwTestDefs | ForEach-Object { $script:HwRes[$_.K] } | Where-Object { $_ })
    $nOk = @($vals | Where-Object State -eq 'ok').Count; $nWarn = @($vals | Where-Object State -eq 'warn').Count; $nBad = @($vals | Where-Object State -eq 'bad').Count; $nOpen = $HwTestDefs.Count - $vals.Count
    $verdict = if ($nBad) { @('#C81E1E', ('Mängel festgestellt: {0} Test(s) mit Fehler' -f $nBad)) } elseif ($nWarn) { @('#B45309', ('Funktionsfähig mit Hinweisen ({0} Warnung(en))' -f $nWarn)) } elseif ($nOk -and -not $nOpen) { @('#15803D', 'Alle Tests bestanden - Gerät einwandfrei') } elseif ($nOk) { @('#15803D', ('{0} Test(s) bestanden, {1} nicht durchgeführt' -f $nOk, $nOpen)) } else { @('#6B7890', 'Noch keine Tests durchgeführt') }
    $pill = @{ ok = 'background:#DCFCE7;color:#15803D'; warn = 'background:#FEF3C7;color:#B45309'; bad = 'background:#FEE2E2;color:#C81E1E'; open = 'background:#EEF2F8;color:#475569' }
    $H = [System.Collections.Generic.List[string]]::new()
    $H.Add('<!DOCTYPE html><html lang="de"><head><meta charset="utf-8"><title>Hardware-Prüfprotokoll</title><style>' + $ReportCss + ' .sig td{border:none;padding:40px 18px 0 0;width:33%} .sig div{border-top:1px solid #1F2A44;padding-top:4px;font-size:9pt;color:#6B7890} .verdict{font-size:14pt;font-weight:600;margin:10px 0 2px} .det{color:#6B7890;font-size:8.8pt}</style></head><body>')
    $H.Add(('<div class="hero"><h1>Hardware-Prüfprotokoll</h1><small>{0} {1} &middot; Seriennummer {2} &middot; Computername {3} &middot; erstellt am {4:dd.MM.yyyy HH:mm}</small></div>' -f (& $E $d.Maker), (& $E $d.Model), (& $E $(if ($d.Serial) { $d.Serial } else { '-' })), (& $E $env:COMPUTERNAME), (Get-Date)))
    $H.Add(('<div class="verdict" style="color:{0}">{1}</div><div class="muted">{2} bestanden &middot; {3} Warnung(en) &middot; {4} Fehler &middot; {5} nicht durchgeführt</div>' -f $verdict[0], (& $E $verdict[1]), $nOk, $nWarn, $nBad, $nOpen))
    $H.Add('<h2>Gerät</h2><table>')
    $bat = if ($d.BatDesign -gt 0 -and $d.BatFull -gt 0) { '{0:N0} % der Originalkapazität ({1:N1} von {2:N1} Wh){3}{4}' -f ([math]::Min(100, $d.BatFull * 100 / $d.BatDesign)), ($d.BatFull / 1000), ($d.BatDesign / 1000), $(if ($d.BatCycles -gt 0) { ', {0} Ladezyklen' -f $d.BatCycles } else { '' }), $(if ($d.BatName) { ' - ' + $d.BatName } else { '' }) } else { 'kein Akku' }
    foreach ($row in @(@('Hersteller', $d.Maker), @('Modell', $d.Model), @('Seriennummer', $d.Serial), @('BIOS', $d.Bios), @('Prozessor', ('{0} ({1} Kerne / {2} Threads, {3:N0} MHz)' -f $d.Cpu, $d.Cores, $d.Threads, $d.MaxMHz)), @('Arbeitsspeicher', ('{0:N1} GB{1}' -f $d.RamGB, $(if (@($d.RamModules).Count) { ' - ' + (@($d.RamModules) -join '; ') } else { '' }))), @('Grafik', $d.Gpu), @('Windows', $d.Os), @('Akku', $bat))) {
        $H.Add(('<tr><th style="width:150px">{0}</th><td>{1}</td></tr>' -f (& $E $row[0]), (& $E $row[1])))
    }
    $H.Add('</table><h2>Datenträger</h2><table><tr><th>Nr.</th><th>Modell</th><th>Seriennummer</th><th>Größe</th><th>Bus</th><th>Zustand</th><th>Temp.</th><th>Verschleiß</th><th>Lesefehler</th><th>Betriebsstunden</th></tr>')
    foreach ($k in @($d.Disks)) { $H.Add(('<tr><td>{0}</td><td>{1}</td><td>{2}</td><td>{3}</td><td>{4}</td><td class="{5}">{6}</td><td>{7}</td><td>{8}</td><td>{9}</td><td>{10}</td></tr>' -f $k.Number, (& $E $k.Name), (& $E $k.Serial), (& $E $k.SizeText), (& $E $k.Bus), $(if ($k.Health -eq 'gesund') { 'ok' } else { 'bad' }), (& $E $k.Health), (& $E $k.Temp), (& $E $k.Wear), (& $E $k.ReadErr), (& $E $k.Hours))) }
    $H.Add('</table><h2>Testergebnisse</h2><table><tr><th style="width:170px">Test</th><th style="width:90px">Ergebnis</th><th>Befund</th><th style="width:95px">Datum</th></tr>')
    foreach ($t in $HwTestDefs) {
        $r = $script:HwRes[$t.K]; $st = if ($r) { [string]$r.State } else { 'open' }; if (-not $pill.ContainsKey($st)) { $st = 'open' }
        $H.Add(('<tr><td><b>{0}</b></td><td><span class="pill" style="{1}">{2}</span></td><td>{3}{4}</td><td>{5}</td></tr>' -f (& $E $t.T), $pill[$st], (& $E $HwStateMap[$st][2]), (& $E $(if ($r) { $r.Summary } else { 'nicht durchgeführt' })), $(if ($r -and $r.Details) { '<div class="det">' + ((& $E $r.Details) -replace "`r?`n", '<br>') + '</div>' } else { '' }), $(if ($r) { ([datetime]$r.Time).ToString('dd.MM.yyyy HH:mm') } else { '' })))
    }
    $H.Add('</table>')
    if ($inp.Note) { $H.Add(('<h2>Bemerkungen</h2><p>{0}</p>' -f (& $E $inp.Note))) }
    $H.Add(('<h2>Bestätigung</h2><p class="muted">Die oben aufgeführten Tests wurden am angegebenen Datum an diesem Gerät durchgeführt. Das Protokoll gibt den Zustand zum Prüfzeitpunkt wieder.</p><table class="sig"><tr><td><div>Ort, Datum{0}</div></td><td><div>Geprüft von{1}</div></td><td><div>Übernommen von{2}</div></td></tr></table>' -f $(if ($inp.Place) { ': ' + (& $E $inp.Place) + ', ' + (Get-Date).ToString('dd.MM.yyyy') } else { '' }), $(if ($inp.Tester) { ': ' + (& $E $inp.Tester) } else { '' }), $(if ($inp.Recipient) { ': ' + (& $E $inp.Recipient) } else { '' })))
    $H.Add(('<p class="muted" style="margin-top:28px">Erstellt mit PC-Tools {0}. Arbeitsspeicher-, Datenträger- und Prozessortests laufen unter Windows und prüfen nur lesend; sie ersetzen keine Herstellerdiagnose und keine Garantieaussage.</p></body></html>' -f (& $E $AppVersion)))
    $window.Cursor = [Windows.Input.Cursors]::Wait
    try { $f = Convert-HtmlToPdf ($H -join "`n") $sd.FileName; $ui.StatusText.Text = 'Prüfprotokoll gespeichert: ' + $f; Start-Process -FilePath $f } catch { Show-UiError ('Prüfprotokoll konnte nicht erstellt werden: ' + $_.Exception.Message) } finally { $window.Cursor = $null }
}

# ---------------------------------------------------------------- Hardware-Test: Knöpfe
$ui.BtnHwRamStart.Add_Click({ Start-HwRam })
$ui.BtnHwRamStop.Add_Click({ if ($script:HwRamObj) { $script:HwRamMeta.Cancelled = $true; $script:HwRamObj.Cancel = $true; $ui.HwRamStatus.Text = 'Wird abgebrochen ...' } })
$ui.BtnHwRamDiag.Add_Click({ Start-HwMemDiag })
$ui.BtnHwRamDiagResult.Add_Click({ Read-HwMemDiagResult })
$ui.BtnHwDiskStart.Add_Click({ Start-HwDisk })
$ui.BtnHwDiskStop.Add_Click({ if ($script:HwDiskObj) { $script:HwDiskMeta.Cancelled = $true; $script:HwDiskObj.Cancel = $true; $ui.HwDiskStatus.Text = 'Wird abgebrochen ...' } })
$ui.BtnHwCpuStart.Add_Click({ Start-HwCpu })
$ui.BtnHwCpuStop.Add_Click({ if ($script:HwCpuObj) { $script:HwCpuMeta.Cancelled = $true; $script:HwCpuObj.Cancel = $true; $ui.HwCpuStatus.Text = 'Wird abgebrochen ...' } })
$ui.BtnHwBatStart.Add_Click({ Start-HwBat })
