$ui.BtnHwDispStart.Add_Click({ try { Show-HwDisplayTest } catch { Show-UiError ('Pixeltest: ' + $_.Exception.Message) } })
$ui.BtnHwDispRevive.Add_Click({ try { Show-HwPixelReviver } catch { Show-UiError ('Pixel-Wiederbeleber: ' + $_.Exception.Message) } })
$ui.BtnHwKbdStart.Add_Click({ try { Show-HwKeyboardTest } catch { Show-UiError ('Tastatur-Test: ' + $_.Exception.Message) } })
$ui.BtnHwTouchStart.Add_Click({ try { Show-HwTouchTest } catch { Show-UiError ('Touch/Stift-Test: ' + $_.Exception.Message) } })
