$ui.BtnHwRefresh.Add_Click({ Update-HwDevice })
$ui.BtnHwReset.Add_Click({
    if (-not (Confirm-Ui 'Alle gespeicherten Ergebnisse des Hardware-Tests löschen und neu beginnen?' 'Warning')) { return }
    $script:HwRes = @{}; Save-HwResults
    foreach ($t in $HwTestDefs) { Update-HwBadge $t.K; $st = $ui["Hw$($t.K)Status"]; if ($st) { $st.Text = '' } }
    Update-HwStats; $ui.StatusText.Text = 'Ergebnisse des Hardware-Tests gelöscht.'
})
$ui.Tabs.Add_SelectionChanged({ param($s, $e)
    if ($e.OriginalSource -eq $s -and $s.SelectedItem -eq $ui.TabHwTest -and -not $script:HwLoaded) {
        $script:HwLoaded = $true
        Import-HwResults
        foreach ($t in $HwTestDefs) { Update-HwBadge $t.K }
        Update-HwStats; Update-HwDevice
        Update-HwChart -Canvas $ui.HwDiskChart -Series @() -YMax 100 -YFmt '{0:N0} MB/s' -XFmt { param($v) '{0:N0} %' -f $v } -Empty 'Datenträger wählen und "Test starten" - hier erscheint die Lesegeschwindigkeit über den ganzen Datenträger.'
        Update-HwChart -Canvas $ui.HwCpuChart -Series @() -XMax 60 -YMax 4000 -Y2Max 100 -XFmt { param($v) Format-HwDuration $v } -Empty 'Hier erscheinen Takt, Auslastung und Temperatur während des Tests.'
        Update-HwChart -Canvas $ui.HwBatChart -Series @() -XMax 180 -YMax 20 -YFmt '{0:N0} W' -XFmt { param($v) Format-HwDuration $v } -Empty 'Hier erscheint der gemessene Verbrauch.'
    } })
$window.Add_Closing({ try { foreach ($o in @($script:HwRamObj, $script:HwDiskObj, $script:HwCpuObj)) { if ($o) { $o.Cancel = $true } }; if ($script:HwReviver) { $script:HwReviver.Close() } } catch { } })

# ---------------------------------------------------------------- Zustands-Score (Karte auf der Übersicht, Verlauf)
function Set-SideScore([double]$S, [string]$Grade) {
    # kleine Score-Anzeige unten in der Seitenleiste (liegt im TabControl-Template)
    $script:SideScoreLast = @($S, $Grade)
    try {
        $tp = $ui.Tabs.Template; if (-not $tp) { return }
        $v = $tp.FindName('SideScoreVal', $ui.Tabs); if (-not $v) { return }
        $col = Get-ScColor $S
        $v.Text = [string][int]$S
        $tp.FindName('SideScoreRing', $ui.Tabs).Stroke = New-UiBrush $col
        $tp.FindName('SideScoreTxt', $ui.Tabs).Text = $Grade
    } catch { }
}
function Get-ScColor([double]$S) { if ($S -ge 85) { '#16A34A' } elseif ($S -ge 65) { '#D97706' } else { '#DC2626' } }
function Set-ScRing([double]$Score, [string]$Color) {
    $cv = $ui.ScRing; if (-not $cv) { return }
    $cv.Children.Clear()
    $sz = 170.0; $th = 14.0; $rr = ($sz - $th) / 2; $cc = $sz / 2
    $trk = New-Object Windows.Shapes.Ellipse; $trk.Width = $sz - $th; $trk.Height = $sz - $th; $trk.Stroke = New-UiBrush '#E2E7F0'; $trk.StrokeThickness = $th
    [Windows.Controls.Canvas]::SetLeft($trk, $th / 2); [Windows.Controls.Canvas]::SetTop($trk, $th / 2); [void]$cv.Children.Add($trk)
    $pct = [math]::Max(0, [math]::Min(100, $Score))
    if ($pct -le 0) { return }
    $br = New-UiBrush $Color
    $fx = New-Object Windows.Media.Effects.DropShadowEffect; $fx.Color = [Windows.Media.ColorConverter]::ConvertFromString($Color); $fx.BlurRadius = 14; $fx.ShadowDepth = 0; $fx.Opacity = 0.35
    if ($pct -ge 99.9) {
        $full = New-Object Windows.Shapes.Ellipse; $full.Width = $sz - $th; $full.Height = $sz - $th; $full.Stroke = $br; $full.StrokeThickness = $th; $full.Effect = $fx
        [Windows.Controls.Canvas]::SetLeft($full, $th / 2); [Windows.Controls.Canvas]::SetTop($full, $th / 2); [void]$cv.Children.Add($full); return
    }
    $ang = 2 * [math]::PI * $pct / 100
    $fig = New-Object Windows.Media.PathFigure; $fig.StartPoint = New-Object Windows.Point($cc, ($cc - $rr)); $fig.IsClosed = $false
    $end = New-Object Windows.Point(($cc + $rr * [math]::Sin($ang)), ($cc - $rr * [math]::Cos($ang)))
    $seg = New-Object Windows.Media.ArcSegment($end, (New-Object Windows.Size($rr, $rr)), 0, ($pct -gt 50), ([Windows.Media.SweepDirection]::Clockwise), $true)
    [void]$fig.Segments.Add($seg)
    $geo = New-Object Windows.Media.PathGeometry; [void]$geo.Figures.Add($fig)
    $path = New-Object Windows.Shapes.Path; $path.Data = $geo; $path.Stroke = $br; $path.StrokeThickness = $th; $path.StrokeStartLineCap = 'Round'; $path.StrokeEndLineCap = 'Round'; $path.Effect = $fx
    [void]$cv.Children.Add($path)
}
function Update-ScSpark([object[]]$Rows) {
    $cv = $ui.ScSpark; if (-not $cv) { return }
    $cv.Children.Clear()
    $pts = @($Rows | Where-Object { $_ -and $_.Score -match '^\d+$' })
    $cw = [double]$cv.ActualWidth; if ($cw -lt 40) { $cw = 240 }; $ch = 64.0
    if ($pts.Count -lt 2) { $t = New-HwText 'Der Verlauf erscheint nach ein paar Tagen - PC-Tools notiert den Score einmal täglich.' 11 '#6B7890'; $t.TextWrapping = 'Wrap'; $t.Width = $cw; [void]$cv.Children.Add($t); $ui.ScSparkInfo.Text = ''; return }
    $today = (Get-Date).Date
    $vals = @($pts | ForEach-Object { [double]$_.Score })
    $mn = [math]::Max(0, (($vals | Measure-Object -Minimum).Minimum) - 5); $mx = [math]::Min(100, (($vals | Measure-Object -Maximum).Maximum) + 5); if ($mx - $mn -lt 10) { $mn = [math]::Max(0, $mx - 10) }
    $pc = New-Object Windows.Media.PointCollection
    foreach ($r in $pts) {
        $dd = ([datetime]::ParseExact($r.Datum, 'yyyy-MM-dd', $null) - $today).TotalDays
        $px = ($dd + 90) / 90 * ($cw - 6) + 3; $py = $ch - 4 - ([double]$r.Score - $mn) / ($mx - $mn) * ($ch - 8)
        $pc.Add((New-Object Windows.Point($px, $py)))
    }
    $last = $pts[$pts.Count - 1]; $col = Get-ScColor ([double]$last.Score)
    $area = New-Object Windows.Shapes.Polygon; $ap = New-Object Windows.Media.PointCollection; foreach ($p in $pc) { $ap.Add($p) }; $ap.Add((New-Object Windows.Point($pc[$pc.Count - 1].X, $ch))); $ap.Add((New-Object Windows.Point($pc[0].X, $ch)))
    $area.Points = $ap; $area.Fill = New-UiBrush '#2D7FF9'; $area.Opacity = 0.12; [void]$cv.Children.Add($area)
    $pl = New-Object Windows.Shapes.Polyline; $pl.Points = $pc; $pl.Stroke = New-UiBrush '#2D7FF9'; $pl.StrokeThickness = 2; $pl.StrokeLineJoin = 'Round'; [void]$cv.Children.Add($pl)
    $dot = New-Object Windows.Shapes.Ellipse; $dot.Width = 8; $dot.Height = 8; $dot.Fill = New-UiBrush $col; $dot.Stroke = New-UiBrush 'White'; $dot.StrokeThickness = 1.5
    [Windows.Controls.Canvas]::SetLeft($dot, $pc[$pc.Count - 1].X - 4); [Windows.Controls.Canvas]::SetTop($dot, $pc[$pc.Count - 1].Y - 4); [void]$cv.Children.Add($dot)
    $ui.ScSparkInfo.Text = '{0} Messungen · tiefster Wert {1:N0} · höchster Wert {2:N0}' -f $pts.Count, ($vals | Measure-Object -Minimum).Minimum, ($vals | Measure-Object -Maximum).Maximum
    $script:ScSparkRows = $Rows
}
function Show-ScComponents([object[]]$Comps) {
    $ui.ScComps.Children.Clear()
    $lvlCol = @{ Good = '#16A34A'; Warn = '#D97706'; Bad = '#DC2626'; NA = '#9AA5B8' }
    foreach ($c in @($Comps | Where-Object { $_ })) {
        $g = New-Object Windows.Controls.Grid; $g.Margin = '0,4,0,0'
        foreach ($cw in @(118, -1, 62)) { $cd = New-Object Windows.Controls.ColumnDefinition; $cd.Width = $(if ($cw -lt 0) { New-Object Windows.GridLength(1, 'Star') } else { New-Object Windows.GridLength($cw) }); [void]$g.ColumnDefinitions.Add($cd) }
        $nm = New-HwText ([string]$c.Name) 12.5 '#1F2A44'; $nm.FontWeight = 'SemiBold'; $nm.VerticalAlignment = 'Center'; [void]$g.Children.Add($nm)
        $trk = New-Object Windows.Controls.Border; $trk.Height = 8; $trk.CornerRadius = '4'; $trk.Background = New-UiBrush '#EEF2F8'; $trk.VerticalAlignment = 'Center'; $trk.Margin = '0,0,10,0'
        $ig = New-Object Windows.Controls.Grid
        $mx = [double]$c.Max; $pt = [double]$c.Points
        if ($mx -gt 0) {
            $c1 = New-Object Windows.Controls.ColumnDefinition; $c1.Width = New-Object Windows.GridLength([math]::Max(0.0001, $pt), 'Star'); $c2 = New-Object Windows.Controls.ColumnDefinition; $c2.Width = New-Object Windows.GridLength([math]::Max(0.0001, $mx - $pt), 'Star')
            [void]$ig.ColumnDefinitions.Add($c1); [void]$ig.ColumnDefinitions.Add($c2)
            $fill = New-Object Windows.Controls.Border; $fill.CornerRadius = '4'; $fill.Background = New-UiBrush $lvlCol[[string]$c.Level]; if ($pt -le 0) { $fill.Visibility = 'Collapsed' }; [void]$ig.Children.Add($fill)
        }
        $trk.Child = $ig; [Windows.Controls.Grid]::SetColumn($trk, 1); [void]$g.Children.Add($trk)
        $pv = New-HwText $(if ($mx -gt 0) { '{0:0.#} / {1:0}' -f $pt, $mx } else { 'entfällt' }) 12 '#475569'; $pv.TextAlignment = 'Right'; $pv.VerticalAlignment = 'Center'; [Windows.Controls.Grid]::SetColumn($pv, 2); [void]$g.Children.Add($pv)
        [void]$ui.ScComps.Children.Add($g)
        if ($c.Reason) { $rs = New-HwText ([string]$c.Reason) 11.5 '#6B7890'; $rs.TextWrapping = 'Wrap'; $rs.Margin = '118,1,62,2'; [void]$ui.ScComps.Children.Add($rs) }
    }
}
function Show-ScScore($Sc, $Avg7, [object[]]$Hist, [string]$When = '') {
    if (-not $Sc) { return }
    $s = [double]$Sc.Score; $col = Get-ScColor $s
    $ui.ScValue.Text = [string][int]$s; $ui.ScValue.Foreground = New-UiBrush $col
    $ui.ScGrade.Text = [string]$Sc.Grade; $ui.ScGrade.Foreground = New-UiBrush $col
    Set-ScRing $s $col
    if ($null -ne $Avg7 -and [string]$Avg7 -ne '') {
        $df = [math]::Round($s - [double]$Avg7, 0)
        $ui.ScTrendArrow.Text = $(if ($df -ge 2) { [string][char]0xE74A } elseif ($df -le -2) { [string][char]0xE74B } else { [string][char]0xE72A })
        $tc = if ($df -ge 2) { '#16A34A' } elseif ($df -le -10) { '#DC2626' } elseif ($df -le -2) { '#D97706' } else { '#6B7890' }
        $ui.ScTrendArrow.Foreground = New-UiBrush $tc
        $ui.ScTrend.Text = if ($df -ge 1) { '+{0} Punkte' -f $df } elseif ($df -le -1) { '{0} Punkte' -f $df } else { 'unverändert' }
        $ui.ScTrendSub.Text = 'gegenüber dem Durchschnitt der letzten 7 Tage ({0:N0}){1}' -f [double]$Avg7, $(if ($df -le -10) { ' - deutlicher Einbruch, siehe Bestandteile' } else { '' })
    } else {
        $ui.ScTrendArrow.Text = ''; $ui.ScTrend.Text = 'noch kein Vergleich'
        $ui.ScTrendSub.Text = 'Der Trend erscheint, sobald Werte von mindestens 3 der letzten 7 Tage vorliegen.'
    }
    Update-ScSpark @($Hist)
    Show-ScComponents @($Sc.Components)
    Set-SideScore $s ([string]$Sc.Grade)
    $ui.ScInfo.Text = $When
}
function Show-ScCached {
    # beim Start sofort den letzten gespeicherten Wert zeigen, bis die neue Berechnung fertig ist
    $rows = @(Get-ScScoreHistory $DataDir 90)
    if (-not $rows.Count) { $ui.ScInfo.Text = 'noch nie berechnet'; Set-ScRing 0 '#2D7FF9'; return }
    $l = $rows[$rows.Count - 1]
    $comps = foreach ($k in (Get-ScComponentDefs)) { $v = [string]$l.($k[2]); if ($v -match '^([\d\.]+)/([\d\.]+)$') { $pt = [double]::Parse($Matches[1], [Globalization.CultureInfo]::InvariantCulture); $mx = [double]::Parse($Matches[2], [Globalization.CultureInfo]::InvariantCulture); [pscustomobject]@{ Name = $k[1]; Points = $pt; Max = $mx; Reason = ''; Level = $(if ($pt -ge $mx * 0.85) { 'Good' } elseif ($pt -ge $mx * 0.5) { 'Warn' } else { 'Bad' }) } } }
    $s = [int]$l.Score
    $prev = @($rows | Where-Object { $_.Datum -lt $l.Datum -and $_.Datum -ge ([datetime]::ParseExact($l.Datum, 'yyyy-MM-dd', $null)).AddDays(-7).ToString('yyyy-MM-dd') })
    $avg = if ($prev.Count -ge 3) { ($prev | ForEach-Object { [double]$_.Score } | Measure-Object -Average).Average } else { $null }
    Show-ScScore ([pscustomobject]@{ Score = $s; Grade = $(if ($s -ge 90) { 'sehr gut' } elseif ($s -ge 75) { 'gut' } elseif ($s -ge 60) { 'befriedigend' } elseif ($s -ge 40) { 'mangelhaft' } else { 'kritisch' }); Components = @($comps) }) $avg $rows ('Stand {0:dd.MM.yyyy} - wird neu berechnet ...' -f [datetime]::ParseExact($l.Datum, 'yyyy-MM-dd', $null))
}
$script:ScBusy = $false
function Update-ScScoreUi {
    if ($script:ScBusy) { return }
    $script:ScBusy = $true
    $ui.BtnScRefresh.IsEnabled = $false
    if ($ui.ScValue.Text -eq '-') { $ui.ScGrade.Text = 'wird berechnet ...' } else { $ui.ScInfo.Text = 'wird neu berechnet ...' }
    $sec = if ($script:SecState -and $null -ne $script:SecState.Score) { [int]$script:SecState.Score } else { -1 }
    Invoke-Bg -Script {
        param($dir, $secScore)
        $x = Add-ScScoreHistory -Dir $dir -NoNotify -SecScore $secScore
        [pscustomobject]@{ Res = $x; Hist = @(Get-ScScoreHistory $dir 90) }
    } -Arguments @($DataDir, $sec) -Functions @('Get-ScComponentDefs', 'Get-ScHealthScore', 'Get-ScScoreHistory', 'Add-ScScoreHistory') -Done {
        param($r, $err)
        $script:ScBusy = $false; $ui.BtnScRefresh.IsEnabled = $true
        if ($err) { $ui.ScInfo.Text = 'Berechnung fehlgeschlagen: ' + $err.Message; if ($ui.ScValue.Text -eq '-') { $ui.ScGrade.Text = 'nicht verfügbar' }; return }
        $x = @($r | Where-Object { $_ -and $_.Res })[0]
        if (-not $x) { $ui.ScInfo.Text = 'Berechnung ohne Ergebnis.'; return }
        $script:ScLast = $x.Res.Result
        Show-ScScore $x.Res.Result $x.Res.Avg7 @($x.Hist) ('berechnet {0:HH:mm} Uhr in {1:N1} s' -f (Get-Date), [double]$x.Res.Result.Seconds)
        if ($x.Res.Notify -and $x.Res.Text) {
            $ui.StatusText.Text = 'Zustands-Score deutlich gefallen - Benachrichtigung wird gesendet.'
            Invoke-Bg -Script { param($cf, $cv, $txt) $ConfigFile = $cf; $ConfigVersion = $cv; $DefaultUpdateSource = ''; Send-PflegeNotify 'Zustands-Score gefallen' $txt 'Yellow' } -Arguments @($ConfigFile, $ConfigVersion, $x.Res.Text) -Functions @('Send-PflegeNotify', 'Read-PflegeConfig', 'Get-DefaultConfig') -Done { param($r2, $e2) }
        }
    }
}
function Show-ScHistory {
    $x = @"
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Title="PC-Tools - Verlauf des Zustands-Scores" Width="1020" Height="700" WindowStartupLocation="CenterOwner" FontFamily="Segoe UI" FontSize="13" Background="#F4F6FA">
  <Grid Margin="20">
    <Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="320"/><RowDefinition Height="*"/></Grid.RowDefinitions>
    <Grid>
      <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
      <StackPanel><TextBlock Text="Verlauf des Zustands-Scores" FontSize="20" FontWeight="SemiBold" Foreground="#1F2A44"/><TextBlock x:Name="HistInfo" Text="" Foreground="#6B7890" Margin="0,2,0,0" TextWrapping="Wrap"/></StackPanel>
      <StackPanel Grid.Column="1" Orientation="Horizontal" VerticalAlignment="Top">
        <Button x:Name="H30" Content="30 Tage" Padding="12,5" Margin="0,0,6,0"/><Button x:Name="H90" Content="90 Tage" Padding="12,5" Margin="0,0,6,0"/><Button x:Name="H365" Content="365 Tage" Padding="12,5" Margin="0,0,14,0"/><Button x:Name="HCsv" Content="Als Tabelle öffnen (CSV)" Padding="12,5"/>
      </StackPanel>
    </Grid>
    <TextBlock Grid.Row="1" Text="Blau: Score pro Tag · grau gestrichelt: Durchschnitt der letzten 7 Tage · rote Marken: Einbruch um mindestens 10 Punkte" FontSize="11.5" Foreground="#6B7890" Margin="0,10,0,4"/>
    <Border Grid.Row="2" Background="White" CornerRadius="12" BorderBrush="#E2E7F0" BorderThickness="1" Padding="6"><Canvas x:Name="HistChart" ClipToBounds="True"/></Border>
    <Border Grid.Row="3" Background="White" CornerRadius="12" BorderBrush="#E2E7F0" BorderThickness="1" Padding="4" Margin="0,12,0,0">
      <DataGrid x:Name="HistGrid" AutoGenerateColumns="False" IsReadOnly="True" HeadersVisibility="Column" GridLinesVisibility="Horizontal" CanUserAddRows="False" Background="White" BorderThickness="0" RowBackground="White">
        <DataGrid.Columns>
          <DataGridTextColumn Header="Datum" Binding="{Binding DatumText}" Width="95"/><DataGridTextColumn Header="Score" Binding="{Binding Score}" Width="60"/>
          <DataGridTextColumn Header="Sicherheit" Binding="{Binding Sicherheit}" Width="*"/><DataGridTextColumn Header="Updates" Binding="{Binding Updates}" Width="*"/><DataGridTextColumn Header="Speicherplatz" Binding="{Binding Speicherplatz}" Width="*"/>
          <DataGridTextColumn Header="Datenträger" Binding="{Binding Datentraeger}" Width="*"/><DataGridTextColumn Header="Akku" Binding="{Binding Akku}" Width="*"/><DataGridTextColumn Header="Stabilität" Binding="{Binding Stabilitaet}" Width="*"/>
          <DataGridTextColumn Header="Startzeit" Binding="{Binding Startzeit}" Width="*"/><DataGridTextColumn Header="Geräte" Binding="{Binding Geraete}" Width="*"/><DataGridTextColumn Header="Temperatur" Binding="{Binding Temperatur}" Width="*"/>
        </DataGrid.Columns>
      </DataGrid>
    </Border>
  </Grid>
</Window>
"@
    $dlg = [Windows.Markup.XamlReader]::Parse((Convert-ThemeXaml $x)); try { $dlg.Owner = $window } catch { }
    $chart = $dlg.FindName('HistChart'); $grid = $dlg.FindName('HistGrid'); $info = $dlg.FindName('HistInfo')
    $all = @(Get-ScScoreHistory $DataDir 365)
    $draw = {
        param([int]$Days)
        $today = (Get-Date).Date; $from = $today.AddDays(-$Days).ToString('yyyy-MM-dd')
        $rows = @($all | Where-Object { $_.Datum -ge $from })
        $pts = [System.Collections.Generic.List[object]]::new(); $avgP = [System.Collections.Generic.List[object]]::new(); $marks = [System.Collections.Generic.List[object]]::new()
        for ($i = 0; $i -lt $rows.Count; $i++) {
            $dx = ([datetime]::ParseExact($rows[$i].Datum, 'yyyy-MM-dd', $null) - $today).TotalDays
            $sv = [double]$rows[$i].Score; $pts.Add(@($dx, $sv))
            $d0 = [datetime]::ParseExact($rows[$i].Datum, 'yyyy-MM-dd', $null)
            $win = @($all | Where-Object { $_.Datum -lt $rows[$i].Datum -and $_.Datum -ge $d0.AddDays(-7).ToString('yyyy-MM-dd') } | ForEach-Object { [double]$_.Score })
            if ($win.Count -ge 3) { $av = ($win | Measure-Object -Average).Average; $avgP.Add(@($dx, $av)); if ($av - $sv -ge 10) { $marks.Add(@{ X = $dx; Color = '#DC2626'; Tip = ('{0:dd.MM.yyyy}: {1} (Ø {2:N0})' -f $d0, $sv, $av) }) } } else { $avgP.Add(@($dx, [double]::NaN)) }
        }
        Update-HwChart -Canvas $chart -Series @(@{ Name = 'Score'; Color = '#2D7FF9'; Points = $pts; Fill = $true }, @{ Name = 'Ø 7 Tage'; Color = '#9AA5B8'; Points = $avgP; Dash = $true; Thin = $true }) -XMin (-$Days) -XMax 0 -YMin 0 -YMax 100 -YFmt '{0:N0}' -XFmt { param($v) (Get-Date).Date.AddDays([math]::Round($v)).ToString('dd.MM.yy') } -Marks @($marks) -Empty 'Für diesen Zeitraum gibt es noch keine Werte.'
        Set-GridItems $grid @($rows | Sort-Object Datum -Descending | ForEach-Object { $o = $_ | Select-Object *; $o | Add-Member -NotePropertyName DatumText -NotePropertyValue ([datetime]::ParseExact($_.Datum, 'yyyy-MM-dd', $null).ToString('dd.MM.yyyy')) -Force; $o })
        $vals = @($rows | ForEach-Object { [double]$_.Score })
        $info.Text = if ($vals.Count) { 'Letzte {0} Tage: {1} Messungen · Ø {2:N0} · tiefster Wert {3:N0} · höchster Wert {4:N0} · {5} Einbruch/Einbrüche' -f $Days, $vals.Count, ($vals | Measure-Object -Average).Average, ($vals | Measure-Object -Minimum).Minimum, ($vals | Measure-Object -Maximum).Maximum, $marks.Count } else { 'Noch keine Werte in diesem Zeitraum. Der Score wird bei jedem Start von PC-Tools und nach jeder Pflege einmal täglich gespeichert.' }
    }
    $dlg.FindName('H30').Add_Click({ & $draw 30 }); $dlg.FindName('H90').Add_Click({ & $draw 90 }); $dlg.FindName('H365').Add_Click({ & $draw 365 })
    $dlg.FindName('HCsv').Add_Click({ $f = Join-Path $DataDir 'Score.csv'; if (Test-Path -LiteralPath $f) { Start-Process -FilePath $f } else { Show-UiError 'Es gibt noch keine Score.csv.' } })
    $dlg.Add_ContentRendered({ & $draw 90 })
    [void]$dlg.ShowDialog()
}
$ui.BtnScRefresh.Add_Click({ Update-ScScoreUi })
$ui.BtnScHistory.Add_Click({ try { Show-ScHistory } catch { Show-UiError ('Verlauf: ' + $_.Exception.Message) } })
# ---- "Punkte beheben": alles, was sich sicher automatisch beheben lässt, mit einem Klick
function Start-ScFixAll {
    if ($script:Job) { Show-UiError 'Es läuft bereits eine Aufgabe - bitte warten, bis sie fertig ist.'; return }
    $res = $script:ScLast
    if (-not $res) { Show-UiError 'Der Zustands-Score wird noch berechnet - bitte gleich noch einmal klicken.'; return }
    $parts = @($res.Components | Where-Object { $_ -and [double]$_.Max -gt 0 -and [double]$_.Points -lt [double]$_.Max })
    $plan = [System.Collections.Generic.List[string]]::new(); $hand = [System.Collections.Generic.List[string]]::new()
    $acts = [System.Collections.Generic.List[string]]::new(); $run = [System.Collections.Generic.List[string]]::new()
    $autoMin = $false; $bitlocker = $false
    foreach ($p in $parts) {
        $why = [string]$p.Reason
        switch ([string]$p.Key) {
            'Security' {
                if ($why -match 'Virendefinitionen veraltet') { $acts.Add('AvSig'); $plan.Add('Virendefinitionen aktualisieren') }
                if ($why -match 'Firewall aus') { $acts.Add('Firewall'); $plan.Add('Firewall wieder einschalten') }
                if ($why -match 'nicht verschlüsselt') { $bitlocker = $true; $plan.Add('BitLocker-Assistent öffnen: prüfen, verschlüsseln und den Wiederherstellungsschlüssel an mehreren Orten sichern') }
                if ($why -match 'Secure Boot aus') { $hand.Add('Secure Boot lässt sich nur im BIOS/UEFI des PCs einschalten (Seite "BIOS"). Vorher prüfen, dass Windows im UEFI-Modus installiert ist - sonst startet der PC danach nicht.') }
                if ($why -match 'KEIN Virenschutz') { $hand.Add('Kein Virenschutz aktiv: Seite "Sicherheit" öffnen und Microsoft Defender einschalten.') }
            }
            'Updates' { if (-not $run.Contains('Update')) { $run.Add('Update'); $plan.Add('Windows-, Treiber- und Programm-Updates installieren (fehlgeschlagene Updates werden erneut versucht)') } }
            'Space' { $run.Add('Clean'); $plan.Add('Aufräumen (temporäre Dateien, Caches, Papierkorb)') }
            'Boot' { $autoMin = $true; $plan.Add('Startzeit-Analyse: Programme, die den Start messbar bremsen, aus dem Autostart nehmen und Drittanbieter-Dienste verzögert starten'); $plan.Add('Autostart aufräumen: überflüssige Programme beim Start abschalten (schnellerer Start; jederzeit rückgängig auf der Seite Autostart)') }
            'Devices' {
                $acts.Add('Devices'); $plan.Add('Geräte-Probleme reparieren und Geräte neu erkennen')
                $run.Add('ProblemDrivers'); $plan.Add('Treiber für die betroffenen Geräte suchen: gezielt über Windows Update, sonst über das Treiberpaket des Herstellers (HP/Lenovo/Dell)')
                if ($why -match 'Code 48|Code 28|Code 10') { $hand.Add('Bleibt ein Gerät mit Code 48/28 übrig, braucht es einen neueren Treiber vom Hersteller (Seite "Treiber" > Hersteller-Tool).') }
            }
            'Disk' { $hand.Add('Datenträger: Verschleiß oder Lesefehler lassen sich nicht reparieren - bitte Daten sichern (Seite "Datensicherung").') }
            'Stability' { $hand.Add('Abstürze: Der KI-Assistent erklärt die Ursache ("Warum stürzt mein PC ab?").') }
            'Temp' { $hand.Add('Temperatur: Lüfter und Luftschlitze reinigen, PC nicht auf weicher Unterlage betreiben.') }
            'Battery' { $hand.Add('Akku: Verschleiß lässt sich nicht reparieren - Seite "Akku und Energie" zeigt Tipps.') }
        }
    }
    if (-not $plan.Count -and -not $hand.Count) { [Windows.MessageBox]::Show((T 'Alles in Ordnung - es gibt nichts zu beheben.'), 'PC-Tools', 'OK', 'Information') | Out-Null; return }
    if (-not $plan.Count) { [Windows.MessageBox]::Show((T ("Automatisch lässt sich hier nichts beheben. Von Hand:`n`n- " + ($hand -join "`n- "))), 'PC-Tools', 'OK', 'Information') | Out-Null; return }
    $msg = "Das wird jetzt erledigt:`n`n- " + ($plan -join "`n- ")
    if ($hand.Count) { $msg += "`n`nNur von Hand möglich (zur Info):`n- " + ($hand -join "`n- ") }
    $msg += "`n`nVorher wird ein Wiederherstellungspunkt erstellt. Jetzt starten?"
    if (-not (Confirm-Ui $msg)) { return }
    $ui.BtnScFix.IsEnabled = $false
    $ui.ScInfo.Text = 'Punkte werden behoben ...'
    try { $null = Invoke-UiWait { Checkpoint-Computer -Description 'PC-Tools: Punkte beheben' -RestorePointType MODIFY_SETTINGS -ErrorAction SilentlyContinue } @() @() 180 'Wiederherstellungspunkt wird erstellt ...' } catch { }
    if ($autoMin) {
        try { $null = Set-AutoBulk 'Recommended' -NoConfirm } catch { }
        try { $ba = @(Invoke-UiWait { Get-BootAnalysis 60 } @() @('Get-BootAnalysis') 120 'Startzeit wird analysiert ...') | Where-Object { $_ -and $_.PSObject.Properties['Items'] } | Select-Object -First 1; if ($ba) { $null = Invoke-BootFix @($ba.Items | Where-Object { $_.AvgSec -ge 1 }) -NoConfirm } } catch { }
    }
    if ($bitlocker) { try { Show-BlWizard } catch { try { Start-Process 'control.exe' '/name Microsoft.BitLockerDriveEncryption' } catch { try { Start-Process 'ms-settings:deviceencryption' } catch { } } } }
    $script:ScFixRun = @($run)
    if ($acts.Count) {
        Invoke-Bg -Script { param($a) Invoke-ScQuickFixes $a } -Arguments @(, [string[]]$acts.ToArray()) -Functions @('Invoke-ScQuickFixes') -Done {
            param($r, $e)
            $t = (@($r | Where-Object { $_ -is [string] }) -join "`r`n")
            $ui.StatusText.Text = 'Punkte beheben: ' + $(if ($e) { $e.Message } else { ($t -split "`r?`n" | Where-Object { $_ } | Select-Object -First 1) })
            $ui.BtnScFix.IsEnabled = $true
            if ($script:ScFixRun.Count -and -not $script:Job) { $null = Start-Run -Parts $script:ScFixRun } else { Update-ScScoreUi }
        }
    } else {
        $ui.BtnScFix.IsEnabled = $true
        if ($run.Count) { $null = Start-Run -Parts $run.ToArray() } else { Update-ScScoreUi }
    }
}
$ui.BtnScFix.Add_Click({ try { Start-ScFixAll } catch { $ui.BtnScFix.IsEnabled = $true; Show-UiError ('Punkte beheben: ' + $_.Exception.Message) } })
function Save-AutoFixSetting {
    try {
        $c = Read-PflegeConfig
        $b = 85; $n = 0; if ([int]::TryParse((([string]$ui.AutoFix_Below.Text) -replace '[^\d]', ''), [ref]$n) -and $n -ge 10 -and $n -le 100) { $b = $n }
        $ui.AutoFix_Below.Text = [string]$b
        $c.AutoFix | Add-Member -NotePropertyName Enabled -NotePropertyValue ([bool]$ui.AutoFix_Enabled.IsChecked) -Force
        $c.AutoFix | Add-Member -NotePropertyName Below -NotePropertyValue $b -Force
        Save-PflegeConfig $c
        $ui.StatusText.Text = $(if ($ui.AutoFix_Enabled.IsChecked) { ('Automatisches Beheben ist an (unter {0} Punkten, nach geplanten Läufen).' -f $b) } else { 'Automatisches Beheben ist aus.' })
    } catch { }
}
$ui.AutoFix_Enabled.Add_Click({ Save-AutoFixSetting })
$ui.AutoFix_Below.Add_LostFocus({ Save-AutoFixSetting })
# ---- Startzeit-Analyse (Seite Autostart)
$script:BootRes = $null
function Start-BootAnalysis {
    $ui.BtnBootAnalyze.IsEnabled = $false; $ui.BootSummary.Text = 'Werte das Start-Protokoll von Windows aus ...'
    Invoke-Bg -Script { Get-BootAnalysis 60 } -Functions @('Get-BootAnalysis') -Done {
        param($r, $e)
        $ui.BtnBootAnalyze.IsEnabled = $true
        $x = @($r | Where-Object { $_ -and $_.PSObject.Properties['Items'] })[0]
        if ($e -or -not $x) { $ui.BootSummary.Text = 'Auswertung nicht möglich: ' + $(if ($e) { $e.Message } else { 'keine Daten' }); return }
        $script:BootRes = $x
        Set-GridItems $ui.BootTimeGrid @($x.Items)
        $ui.BtnBootFix.IsEnabled = [bool]@($x.Items | Where-Object { $_.Action -in 'Autostart abschalten', 'verzögert starten' }).Count
        $ui.BootSummary.Text = $(if (@($x.Boots).Count) { 'Letzter Start: {0:N0} s · Ø der letzten {1} Starts: {2:N0} s · {3} Bremsen gefunden (Windows misst nur, was den Start spürbar verzögert)' -f $x.LastBoot, [math]::Min(10, @($x.Boots).Count), $x.AvgBoot, @($x.Items).Count } else { 'Windows hat noch keine Startzeiten aufgezeichnet (Protokoll "Diagnostics-Performance" leer oder ausgeschaltet).' })
    }
}
function Invoke-BootFix([object[]]$Rows, [switch]$NoConfirm) {
    $rows = @($Rows | Where-Object { $_ -and $_.Action -in 'Autostart abschalten', 'verzögert starten' })
    if (-not $rows.Count) { if (-not $NoConfirm) { Show-UiError 'In der Auswahl ist nichts, was PC-Tools ändern kann (Treiber und Windows-Dienste werden nicht angefasst).' }; return 0 }
    if (-not $NoConfirm -and -not (Confirm-Ui (("Diese Startbremsen entschärfen?`n`n- " + ((@($rows | ForEach-Object { '{0} ({1}, Ø {2})' -f $_.Display, $_.Action, $_.AvgText })) -join "`n- ")) + "`n`nProgramme starten dann nicht mehr automatisch (jederzeit wieder einschaltbar), Dienste starten etwas später nach der Anmeldung."))) { return 0 }
    if (-not @($script:AutoEntries).Count) { try { Build-Autostart } catch { } }
    $n = 0; $err = @()
    foreach ($r in $rows) {
        try {
            if ($r.Action -eq 'verzögert starten') { Set-ServiceDelayedStart $r.Key; $n++; continue }
            $fn = ([string]$r.Key).ToLower()
            $hit = @($script:AutoEntries | Where-Object { $_ -and $_.Enabled -and -not $_.Keep -and ([string]$_.Cmd).ToLower().Contains($fn) })
            if (-not $hit.Count) { $err += ('{0}: kein Autostart-Eintrag gefunden (startet evtl. über einen Dienst)' -f $r.Display); continue }
            foreach ($h in $hit) { Set-AutostartEntry $h $false; $n++ }
        } catch { $err += ('{0}: {1}' -f $r.Display, $_.Exception.Message) }
    }
    try { Show-Autostart } catch { }
    $ui.StatusText.Text = ('Startzeit: {0} Bremse(n) entschärft.' -f $n)
    if ($err -and -not $NoConfirm) { Show-UiError ("Nicht alles ging:`n" + ($err -join "`n")) }
    return $n
}
