# ---------------------------------------------------------------- Notfall-Stick (Oberfläche)
$script:RsLoaded = $false; $script:RsWinRe = $null; $script:RsChecking = $false
function Update-RsDiskList {
    $ui.RsDisk.Items.Clear()
    $rsDisks = @()
    try { $rsDisks = @(Get-Disk -ErrorAction Stop | Where-Object { [string]$_.BusType -eq 'USB' -and -not $_.IsBoot -and -not $_.IsSystem } | Sort-Object Number) } catch { }
    foreach ($d in $rsDisks) {
        $letters = (@(Get-Partition -DiskNumber $d.Number -ErrorAction SilentlyContinue | Where-Object { $_.DriveLetter -and [int][char]$_.DriveLetter -ne 0 } | ForEach-Object { "$($_.DriveLetter):" }) -join ' ')
        $ci = New-Object Windows.Controls.ComboBoxItem
        $ci.Content = 'Datenträger {0}: {1}  ({2:N1} GB){3}' -f $d.Number, $d.FriendlyName, ($d.Size / 1GB), $(if ($letters) { '  - ' + $letters } else { '' })
        $ci.Tag = [int]$d.Number
        [void]$ui.RsDisk.Items.Add($ci)
    }
    $ui.RsS2.Text = [string]$rsDisks.Count
    if ($ui.RsDisk.Items.Count) { $ui.RsDisk.SelectedIndex = 0 }
    else { $ci = New-Object Windows.Controls.ComboBoxItem; $ci.Content = 'Kein USB-Stick gefunden - einstecken und "Aktualisieren"'; $ci.IsEnabled = $false; [void]$ui.RsDisk.Items.Add($ci); $ui.RsDiskInfo.Text = 'Kein USB-Stick eingesteckt.' }
}
function Get-RsSelDisk { $ci = $ui.RsDisk.SelectedItem; if ($ci -and $null -ne $ci.Tag) { return [int]$ci.Tag }; return -1 }
function Get-RsSelRoots {
    $n = Get-RsSelDisk; if ($n -lt 0) { return @() }
    @(Get-Partition -DiskNumber $n -ErrorAction SilentlyContinue | Where-Object { $_.DriveLetter -and [int][char]$_.DriveLetter -ne 0 } | Sort-Object PartitionNumber | ForEach-Object { '{0}:\' -f $_.DriveLetter })
}
function Update-RsDiskInfo {
    $n = Get-RsSelDisk
    if ($n -lt 0) { return }
    try {
        $d = Get-Disk -Number $n -ErrorAction Stop
        $vv = @(Get-Partition -DiskNumber $n -ErrorAction SilentlyContinue | Sort-Object PartitionNumber | ForEach-Object {
                $v = $_ | Get-Volume -ErrorAction SilentlyContinue
                '{0}{1} {2:N1} GB{3}' -f $(if ($_.DriveLetter -and [int][char]$_.DriveLetter -ne 0) { [string]$_.DriveLetter + ': ' } else { '' }), $(if ($v -and $v.FileSystem) { $v.FileSystem } else { 'ohne Dateisystem' }), ($_.Size / 1GB), $(if ($v -and $v.FileSystemLabel) { ' "' + $v.FileSystemLabel + '"' } else { '' }) })
        $known = $null
        foreach ($r in (Get-RsSelRoots)) { $sf = Join-Path $r 'PC-Tools-Stick.json'; if (Test-Path -LiteralPath $sf) { try { $known = Get-Content -LiteralPath $sf -Raw -Encoding UTF8 | ConvertFrom-Json } catch { } } }
        $ui.RsDiskInfo.Text = '{0}, {1:N1} GB, {2}. Partitionen: {3}{4}' -f $d.FriendlyName, ($d.Size / 1GB), $(if ([string]$d.PartitionStyle -eq 'RAW') { 'leer' } else { [string]$d.PartitionStyle }), $(if ($vv.Count) { $vv -join ' | ' } else { 'keine' }), $(if ($known) { "`nSchon ein Notfall-Stick (erstellt {0} auf {1}). Zum Aktualisieren ohne Löschen den Haken ""Stick neu einrichten"" entfernen." -f $known.Created, $known.Computer } else { '' })
        if ($known) { $ui.RsFormat.IsChecked = $false } else { $ui.RsFormat.IsChecked = $true }
        if ($d.Size -lt 3.5GB) { $ui.RsDiskInfo.Text += "`nAchtung: sehr kleiner Stick - für Reparatursystem und Treiber werden 4 GB oder mehr empfohlen." }
    } catch { $ui.RsDiskInfo.Text = 'Stick konnte nicht gelesen werden: ' + $_.Exception.Message }
}
function Update-RsOverview {
    $ui.RsS0.Text = '...'; $ui.RsS1.Text = '...'
    $uefi = Test-Path 'HKLM:\SYSTEM\CurrentControlSet\Control\SecureBoot\State'
    $sb = $null; try { $sb = Confirm-SecureBootUEFI -ErrorAction Stop } catch { }
    $ui.RsS3.Text = $(if (-not $uefi) { 'BIOS' } elseif ($sb) { 'UEFI + SB' } else { 'UEFI' })
    $tb = Join-Path $DataDir 'Toolbox'
    $ui.RsToolbox.IsEnabled = [bool](Test-Path -LiteralPath $tb)
    if (-not $ui.RsToolbox.IsEnabled) { $ui.RsToolbox.IsChecked = $false; $ui.RsToolboxInfo.Text = 'Kein Toolbox-Ordner vorhanden (' + $tb + ').' } else { $ui.RsToolboxInfo.Text = 'Wird gezählt ...' }
    Set-GridItems $ui.RsKeyGrid @($RsBootKeys)
    Invoke-Bg -Script {
        param($tbDir)
        $w = $null; try { $w = Get-RsWinReInfo } catch { }
        $tbs = $null; if (Test-Path -LiteralPath $tbDir) { $fl = @(Get-ChildItem -LiteralPath $tbDir -Recurse -File -Force -ErrorAction SilentlyContinue); $tbs = [pscustomobject]@{ Count = $fl.Count; Size = [int64](($fl | Measure-Object Length -Sum).Sum) } }
        [pscustomobject]@{ WinRe = $w; Toolbox = $tbs }
    } -Arguments @($tb) -Functions @('Get-RsWinReInfo', 'ConvertFrom-RsReagentc', 'Invoke-NdCmd', 'Get-RsSysDir') -Done {
        param($r, $err)
        $x = @($r) | Select-Object -Last 1
        $w = if ($x) { $x.WinRe } else { $null }
        $script:RsWinRe = $w
        $ui.RsBanner.Visibility = 'Collapsed'
        if (-not $w -or -not $w.Admin) {
            $ui.RsS0.Text = '?'; $ui.RsS1.Text = '?'
            $ui.RsBannerText.Text = 'Der Zustand der Wiederherstellungsumgebung (reagentc /info) konnte nicht gelesen werden - PC-Tools braucht dafür Administratorrechte. Der Stick kann trotzdem erstellt werden.'; $ui.RsBanner.Visibility = 'Visible'
        } elseif ($w.Enabled) {
            $ui.RsS0.Text = 'aktiv'
            $ui.RsS1.Text = $(if ($w.PartSize -gt 0 -and $w.PartFree -gt 0) { '~{0:N0} MB' -f (($w.PartSize - $w.PartFree) / 1MB) } else { '~0,6 GB' })
        } elseif ($w.LocalWim) {
            $ui.RsS0.Text = 'aus'; $ui.RsS1.Text = '{0:N0} MB' -f ($w.LocalSize / 1MB)
            $ui.RsBannerText.Text = 'Die Wiederherstellungsumgebung ist auf diesem PC ausgeschaltet, die Datei Winre.wim ist aber vorhanden - der Stick funktioniert trotzdem. Tipp: "reagentc /enable" als Administrator schaltet sie wieder ein (dann gibt es die Reparatur auch ohne Stick).'; $ui.RsBanner.Visibility = 'Visible'
        } else {
            $ui.RsS0.Text = 'fehlt'; $ui.RsS1.Text = '-'
            $ui.RsBannerText.Text = 'Auf diesem PC gibt es keine Wiederherstellungsumgebung (Winre.wim fehlt). Kein Problem: Als Quelle ist die neueste offizielle Windows-11-ISO gewählt, die PC-Tools automatisch lädt.'; $ui.RsBanner.Visibility = 'Visible'
            $ui.RsSrcLatest.IsChecked = $true
        }
        if ($x -and $x.Toolbox) { $ui.RsToolboxInfo.Text = '{0} Dateien, {1} aus {2} - wird nach \Toolbox kopiert.' -f $x.Toolbox.Count, (Format-Bytes $x.Toolbox.Size), (Join-Path $DataDir 'Toolbox') }
    }
}
function Start-RsBuild {
    $n = Get-RsSelDisk
    if ($n -lt 0) { Show-UiError 'Bitte zuerst einen USB-Stick einstecken und auswählen.'; return }
    $d = $null; try { $d = Get-Disk -Number $n -ErrorAction Stop } catch { }
    if (-not $d -or $d.IsBoot -or $d.IsSystem -or [string]$d.BusType -ne 'USB') { Show-UiError 'Das gewählte Laufwerk ist kein USB-Stick (oder nicht mehr vorhanden). Bitte "Aktualisieren".'; Update-RsDiskList; return }
    $rep = [bool]$ui.RsRepair.IsChecked; $pf = [bool]$ui.RsPflege.IsChecked; $tbx = [bool]($ui.RsToolbox.IsChecked -and $ui.RsToolbox.IsEnabled); $drv = [bool]$ui.RsDrivers.IsChecked; $fmt = [bool]$ui.RsFormat.IsChecked
    if (-not ($rep -or $pf -or $tbx -or $drv)) { Show-UiError 'Bitte mindestens einen Inhalt ankreuzen.'; return }
    $src = if ($ui.RsSrcIso.IsChecked) { 'Iso' } elseif ($ui.RsSrcLatest.IsChecked) { 'Latest' } else { 'WinRe' }
    $iso = $ui.RsIso.Text.Trim()
    if ($rep -and $src -eq 'Iso' -and -not ($iso -and (Test-Path -LiteralPath $iso))) { Show-UiError 'Bitte eine vorhandene Windows-ISO wählen.'; return }
    if ($rep -and $src -eq 'WinRe' -and $script:RsWinRe -and $script:RsWinRe.Admin -and -not $script:RsWinRe.Enabled -and -not $script:RsWinRe.LocalWim) { Show-UiError 'Auf diesem PC gibt es keine Wiederherstellungsumgebung. Bitte eine Windows-ISO als Quelle wählen.'; return }
    if ($rep -and $d.Size -lt 1.5GB) { Show-UiError 'Der Stick ist zu klein - für das Reparatursystem werden mindestens 2 GB gebraucht.'; return }
    if ($rep -and -not $fmt) {
        $hasFat = @(Get-Partition -DiskNumber $n -ErrorAction SilentlyContinue | Get-Volume -ErrorAction SilentlyContinue | Where-Object { [string]$_.FileSystem -eq 'FAT32' }).Count
        if (-not $hasFat) { Show-UiError 'Für das Reparatursystem braucht der Stick eine FAT32-Partition. Bitte "Stick neu einrichten" ankreuzen (löscht den Stick).'; return }
    }
    $what = @(); if ($rep) { $what += $(if ($src -eq 'Latest') { 'Reparatursystem aus der neuesten Windows-11-ISO (wird geladen) + ISO und Reparaturquelle auf der Datenpartition' } elseif ($src -eq 'Iso') { 'Reparatursystem aus ' + [IO.Path]::GetFileName($iso) } else { 'Reparatursystem (WinRE dieses PCs)' }) }; if ($pf) { $what += 'PC-Tools portabel' }; if ($tbx) { $what += 'Toolbox' }; if ($drv) { $what += 'Treiber-Sicherung' }
    if ($fmt) {
        $selfDisks = @(foreach ($pp in @($PSCommandPath, $DataDir)) { if ([string]$pp -match '^([A-Za-z]):') { try { [int](Get-Partition -DriveLetter $Matches[1] -ErrorAction Stop | Select-Object -First 1).DiskNumber } catch { } } })
        if ($selfDisks -contains [int]$d.Number) { Show-UiError 'PC-Tools läuft von diesem Stick bzw. speichert dort seine Daten - er kann nicht gelöscht werden. Bitte "Stick neu einrichten" abwählen (Stick nur ergänzen) oder PC-Tools von einem anderen Laufwerk starten.'; return }
        $txt = "Datenträger {0}: {1}  ({2:N1} GB)`n`nALLE DATEN AUF DIESEM STICK WERDEN GELÖSCHT.`n`nDanach kommt auf den Stick: {3}`n`nFortfahren?" -f $d.Number, $d.FriendlyName, ($d.Size / 1GB), ($what -join ', ')
        if (-not (Confirm-Ui $txt 'Warning')) { return }
    } else {
        if (-not (Confirm-Ui ("Datenträger {0}: {1} ({2:N1} GB) wird ergänzt - vorhandene Dateien bleiben, gleichnamige werden ersetzt.`n`nInhalt: {3}`n`nFortfahren?" -f $d.Number, $d.FriendlyName, ($d.Size / 1GB), ($what -join ', ')))) { return }
    }
    Start-Run -Parts @('RescueStick') -Job @{ DiskNumber = [int]$n; Format = $fmt; Repair = $rep; Source = $src; Iso = $(if ($src -eq 'Iso') { $iso } else { '' }); Pflege = $pf; WithToken = [bool]$ui.RsToken.IsChecked; Toolbox = $tbx; Drivers = $drv }
}
function Start-RsCheck {
    if ($script:RsChecking) { return }
    $roots = @(Get-RsSelRoots)
    if (-not $roots.Count) { Show-UiError 'Bitte einen USB-Stick mit Laufwerksbuchstaben auswählen.'; return }
    $script:RsChecking = $true; $ui.RsProgress.Visibility = 'Visible'; $ui.RsCheckInfo.Text = 'Stick wird geprüft ({0}) ...' -f ($roots -join ' ')
    Invoke-Bg -Script { param($rr) Get-RsStickReport $rr } -Arguments @(, $roots) -Functions @('Get-RsStickReport') -Done {
        param($r, $err)
        $script:RsChecking = $false; $ui.RsProgress.Visibility = 'Collapsed'
        if ($err) { $ui.RsCheckInfo.Text = 'Prüfung fehlgeschlagen: ' + $err.Message; return }
        $rows = @($r | ForEach-Object { $_ } | Where-Object { $_ -and $_.PSObject.Properties['Rank'] })
        Set-GridItems $ui.RsCheckGrid $rows
        $bootItems = @($rows | Where-Object { $_.Item -match 'boot\.wim|boot\.sdi|Start-Manager|Startkonfiguration' })
        $bootOk = $bootItems.Count -ge 4 -and -not @($bootItems | Where-Object { $_.Level -eq 'bad' }).Count
        $ui.RsCheckInfo.Text = '{0:HH:mm:ss}: {1}  {2} Bestandteil(e) vorhanden, {3} fehlen, {4} Hinweis(e).' -f (Get-Date), $(if ($bootOk) { 'Der Stick ist bootfähig (UEFI).' } else { 'Der Stick ist NICHT bootfähig - "Stick erstellen" mit "Reparatursystem".' }), @($rows | Where-Object Level -eq 'ok').Count, @($rows | Where-Object Level -eq 'bad').Count, @($rows | Where-Object Level -eq 'warn').Count
        $ui.StatusText.Text = 'Notfall-Stick geprüft.'
    }
}
$ui.BtnRsRefresh.Add_Click({ Update-RsDiskList })
$ui.RsDisk.Add_SelectionChanged({ Update-RsDiskInfo })
$ui.RsRepair.Add_Click({ $ui.RsSrcPanel.IsEnabled = [bool]$ui.RsRepair.IsChecked })
$ui.RsSrcIso.Add_Checked({ $ui.RsIso.IsEnabled = $true; $ui.BtnRsIsoBrowse.IsEnabled = $true })
$ui.RsSrcWinRe.Add_Checked({ $ui.RsIso.IsEnabled = $false; $ui.BtnRsIsoBrowse.IsEnabled = $false })
$ui.RsSrcLatest.Add_Checked({ $ui.RsIso.IsEnabled = $false; $ui.BtnRsIsoBrowse.IsEnabled = $false })
$ui.RsPflege.Add_Click({ $ui.RsToken.IsEnabled = [bool]$ui.RsPflege.IsChecked })
$ui.BtnRsIsoBrowse.Add_Click({
    $f = Select-IsoFile 'Windows-ISO für das Reparatursystem wählen'
    if ($f) { $ui.RsIso.Text = $f }
    elseif (-not $ui.RsIso.Text) { $last = Join-Path $DataDir 'iso_last.txt'; if (Test-Path $last) { $x = (Get-Content $last -Raw).Trim(); if (Test-Path -LiteralPath $x) { $ui.RsIso.Text = $x } } }
})
$ui.BtnRsBuild.Add_Click({ try { Start-RsBuild } catch { Show-UiError ('Stick erstellen: ' + $_.Exception.Message) } })
$ui.BtnRsCheck.Add_Click({ try { Start-RsCheck } catch { $script:RsChecking = $false; $ui.RsProgress.Visibility = 'Collapsed'; Show-UiError ('Stick prüfen: ' + $_.Exception.Message) } })
$ui.BtnRsOpen.Add_Click({ $rr = @(Get-RsSelRoots); if ($rr.Count) { foreach ($r in $rr) { Start-Process explorer.exe $r } } else { Show-UiError 'Der gewählte Stick hat kein Laufwerk mit Buchstaben.' } })
$ui.BtnRsReadme.Add_Click({
    try {
        $f = Join-Path $env:TEMP 'PC-Tools Notfall-Stick - Anleitung.txt'
        Set-Content -LiteralPath $f -Encoding UTF8 -Value (Get-RsReadme $null)
        Start-Process notepad.exe ('"{0}"' -f $f)
    } catch { Show-UiError $_.Exception.Message }
})
$ui.BtnRsBootNow.Add_Click({
    if (-not (Confirm-Ui "Der PC startet jetzt in den erweiterten Start von Windows.`n`nDort ""Ein Gerät verwenden"" wählen und den USB-Stick (""EFI USB Device"" bzw. den Namen des Sticks) anklicken.`n`nOffene Dateien vorher speichern. Jetzt neu starten?")) { return }
    try { Start-Process shutdown.exe -ArgumentList '/r /o /t 5 /c "PC-Tools: Neustart in den erweiterten Start (vom Notfall-Stick starten)"' -WindowStyle Hidden; $ui.StatusText.Text = 'Neustart in den erweiterten Start in 5 Sekunden ...' } catch { Show-UiError $_.Exception.Message }
})
$ui.BtnRsSurface.Add_Click({ $ui.Tabs.SelectedItem = $ui.TabSurface })

# ---------------------------------------------------------------- Fernhilfe (Oberfläche)
$script:FhLoaded = $false; $script:FhBusy = $false; $script:FhDlBusy = $false; $script:FhLast = $null; $script:FhReq = $null; $script:FhPrevState = 'Maximized'; $script:FhShotTimer = $null; $script:FhDev = $null; $script:FhQaApp = $false
$FhToolNames = @('Schnellhilfe', 'RustDesk', 'TeamViewer', 'AnyDesk')
function Update-FhHelperShow {
    $s = Get-FhSettings
    if ([string]$s.HelperName -or [string]$s.HelperPhone) {
        $bits = @(); if ([string]$s.HelperName) { $bits += [string]$s.HelperName }; if ([string]$s.HelperPhone) { $bits += ('Tel. ' + $s.HelperPhone) }; if ([string]$s.HelperMail) { $bits += [string]$s.HelperMail }
        $ui.FhHelperShow.Text = 'Dein Helfer: {0}  ·  Programm: {1}' -f ($bits -join '  ·  '), $s.Tool
    } else { $ui.FhHelperShow.Text = 'Noch kein Helfer eingetragen - unten unter "Einstellungen: dein Helfer" Name und Telefonnummer eintragen.' }
}
function Import-FhSettingsToUi {
    $s = Get-FhSettings
    $ui.FhName.Text = [string]$s.HelperName; $ui.FhPhone.Text = [string]$s.HelperPhone; $ui.FhMail.Text = [string]$s.HelperMail
    $ix = [array]::IndexOf($FhToolNames, [string]$s.Tool); if ($ix -lt 0) { $ix = 0 }
    $ui.FhTool.SelectedIndex = $ix; $ui.FhGuideTool.SelectedIndex = $ix
    $ui.FhShot.IsChecked = [bool]$s.Screenshot; $ui.FhNet.IsChecked = [bool]$s.NetCheck
    Update-FhHelperShow; Update-FhGuide
}
function Save-FhFromUi {
    $s = [pscustomobject]@{ HelperName = $ui.FhName.Text.Trim(); HelperPhone = $ui.FhPhone.Text.Trim(); HelperMail = $ui.FhMail.Text.Trim(); Tool = $FhToolNames[[math]::Max(0, $ui.FhTool.SelectedIndex)]; Screenshot = [bool]$ui.FhShot.IsChecked; NetCheck = [bool]$ui.FhNet.IsChecked }
    Save-FhSettings $s
    Update-FhHelperShow
    return $s
}
function Update-FhGuide { try { $ui.FhGuideText.Text = Get-FhGuideText $FhToolNames[[math]::Max(0, $ui.FhGuideTool.SelectedIndex)] (Get-FhSettings) } catch { } }
function Update-FhToolState {
    $dir = Join-Path $DataDir 'Fernhilfe'
    foreach ($t in $FhTools) {
        $f = Join-Path $dir $t.File
        $ui[('FhSt' + $t.Key)].Text = $(if (Test-Path -LiteralPath $f) { $fi = Get-Item -LiteralPath $f; $v = ''; try { $v = [Diagnostics.FileVersionInfo]::GetVersionInfo($f).ProductVersion } catch { }; 'Geladen: Version {0}, Stand {1:dd.MM.yyyy} - wird vor jedem Start neu geprüft.' -f $(if ($v) { $v } else { '?' }), $fi.LastWriteTime } else { 'Wird beim ersten Klick geladen und geprüft.' })
    }
    $qa = Join-Path $env:windir 'System32\quickassist.exe'
    $ui.FhStQa.Text = $(if ($script:FhQaApp) { 'Installiert (App aus dem Microsoft Store). Tastenkürzel: Strg + Windows + Q' } elseif (Test-Path -LiteralPath $qa) { 'Vorhanden (in Windows eingebaut). Tastenkürzel: Strg + Windows + Q' } else { 'Wird geprüft ...' })
}
function Update-FhDevice {
    $ui.FhPc.Text = $env:COMPUTERNAME; $ui.FhUser.Text = $env:USERNAME
    Invoke-Bg -Script {
        $dv = Get-FhDeviceInfo
        $app = $false; try { $app = [bool](Get-AppxPackage -Name 'MicrosoftCorporationII.QuickAssist' -ErrorAction Stop) } catch { }
        [pscustomobject]@{ Dev = $dv; QaApp = $app }
    } -Functions @('Get-FhDeviceInfo') -Done {
        param($r, $err)
        $x = @($r) | Select-Object -Last 1
        if (-not $x) { return }
        $dv = $x.Dev; $script:FhDev = $dv; $script:FhQaApp = [bool]$x.QaApp
        $ui.FhPc.Text = $dv.Computer; $ui.FhUser.Text = $dv.User
        $ui.FhIp.Text = $(if ($dv.Ips) { ($dv.Ips -replace ', ', "`n") } else { 'keine (kein Netzwerk?)' })
        $ui.FhWin.Text = $dv.Windows; $ui.FhModel.Text = '{0}{1}' -f $dv.Model, $(if ($dv.Serial) { "`nS/N " + $dv.Serial } else { '' })
        $ids = @(); if ($dv.RustDeskId) { $ids += ('RustDesk: ' + $dv.RustDeskId) }; if ($dv.TeamViewerId) { $ids += ('TeamViewer: ' + $dv.TeamViewerId) }
        $ui.FhIds.Text = $(if ($ids.Count) { $ids -join "`n" } else { 'noch keine (erscheinen nach dem ersten Start)' })
        $qa = Join-Path $env:windir 'System32\quickassist.exe'
        $ui.FhStQa.Text = $(if ($script:FhQaApp) { 'Installiert (App aus dem Microsoft Store). Tastenkürzel: Strg + Windows + Q' } elseif (Test-Path -LiteralPath $qa) { 'Vorhanden (in Windows eingebaut). Tastenkürzel: Strg + Windows + Q' } else { 'Nicht installiert - beim Klick geht es zum Microsoft Store.' })
    }
}
function Start-FhQuickAssist {
    $qa = Join-Path $env:windir 'System32\quickassist.exe'
    try { Start-Process 'ms-quick-assist:' -ErrorAction Stop; $ui.StatusText.Text = 'Schnellhilfe wird geöffnet ...'; return } catch { }
    if (Test-Path -LiteralPath $qa) { try { Start-Process -FilePath $qa -ErrorAction Stop; return } catch { } }
    if (Confirm-Ui 'Die Windows-Schnellhilfe ist auf diesem PC nicht installiert. Jetzt kostenlos aus dem Microsoft Store installieren?') {
        try { Start-Process 'ms-windows-store://pdp/?productid=9P7BP5VNWKX5' -ErrorAction Stop }
        catch { $wg = Get-WingetPath; if ($wg) { Start-Process -FilePath $wg -ArgumentList 'install --id 9P7BP5VNWKX5 -s msstore --accept-package-agreements --accept-source-agreements' } else { Start-Process 'https://apps.microsoft.com/detail/9P7BP5VNWKX5' } }
    }
}
function Start-FhTool([string]$Key) {
    if ($script:FhDlBusy) { $ui.FhDlInfo.Text = 'Bitte warten - es wird gerade ein Programm geladen.'; return }
    $t = @($FhTools | Where-Object { $_.Key -eq $Key })[0]
    if (-not $t) { return }
    $script:FhDlBusy = $true; $script:FhDlKey = $Key
    $ui.FhDlProgress.Visibility = 'Visible'
    $ui.FhDlInfo.Text = '{0}: wird geladen und die Signatur geprüft ...' -f $t.Title
    $ui.StatusText.Text = $ui.FhDlInfo.Text
    Invoke-Bg -Script { param($tt, $dd) Get-FhTool $tt $dd $false } -Arguments @($t, (Join-Path $DataDir 'Fernhilfe')) -Functions @('Get-FhTool', 'Select-FhGithubAsset') -Done {
        param($r, $err)
        $script:FhDlBusy = $false; $ui.FhDlProgress.Visibility = 'Collapsed'
        $t = @($FhTools | Where-Object { $_.Key -eq $script:FhDlKey })[0]
        $x = @($r | Where-Object { $_ -and $_.PSObject.Properties['File'] }) | Select-Object -Last 1
        if ($err -or -not $x) {
            $msg = if ($err) { $err.Message } else { 'unbekannter Fehler' }
            $ui.FhDlInfo.Text = '{0}: Download fehlgeschlagen - {1}' -f $t.Title, $msg
            $wg = Get-WingetPath
            if ($wg -and $t.Winget -and (Confirm-Ui ("{0} konnte nicht geladen werden:`n{1}`n`nStattdessen mit winget installieren ({2})?" -f $t.Title, $msg, $t.Winget))) {
                Start-Process -FilePath $wg -ArgumentList ('install --id {0} -e --accept-package-agreements --accept-source-agreements' -f $t.Winget)
                $ui.FhDlInfo.Text = '{0} wird mit winget installiert (eigenes Fenster). Danach im Startmenü öffnen.' -f $t.Title
            } elseif (-not $wg) { Show-UiError ('{0} konnte nicht geladen werden: {1}' -f $t.Title, $msg) }
            return
        }
        $start = $false
        if ($x.SignerOk) { $start = $true }
        elseif ($x.Status -eq 'Valid') { $start = Confirm-Ui ("{0} ist gültig signiert, aber von ""{1}"" - erwartet war der Hersteller ({2}).`n`nNur starten, wenn du dir sicher bist. Trotzdem starten?" -f $t.Title, $x.Signer, $t.Signer) 'Warning' }
        elseif ($x.HashOk -eq $true) { $start = Confirm-Ui ("{0} hat keine gültige digitale Signatur ({1}), die Prüfsumme (SHA-256) stimmt aber mit der offiziellen GitHub-Veröffentlichung überein.`n`nStarten?" -f $t.Title, $x.Status) 'Warning' }
        else {
            try { Remove-Item -LiteralPath $x.File -Force -ErrorAction Stop } catch { }
            $ui.FhDlInfo.Text = '{0}: NICHT gestartet - Signatur ungültig ({1}). Datei gelöscht.' -f $t.Title, $x.Status
            Show-UiError ('{0} wurde NICHT gestartet: Die digitale Signatur ist nicht gültig ({1}). Die Datei wurde gelöscht. Bitte später erneut versuchen oder direkt beim Hersteller laden.' -f $t.Title, $x.Status)
            return
        }
        if (-not $start) { $ui.FhDlInfo.Text = '{0}: nicht gestartet.' -f $t.Title; return }
        try {
            Start-Process -FilePath $x.File -WorkingDirectory (Split-Path $x.File) -ErrorAction Stop
            $ui.FhDlInfo.Text = '{0} {1} gestartet - Signatur: {2} ({3}){4}. Sag deinem Helfer die ID und das Passwort aus dem Fenster.' -f $t.Title, $x.Version, $x.Signer, $x.Status, $(if ($x.HashOk -eq $true) { ', SHA-256 bestätigt' } else { '' })
            $ui.StatusText.Text = '{0} gestartet.' -f $t.Title
        } catch { Show-UiError ('{0} konnte nicht gestartet werden: {1}' -f $t.Title, $_.Exception.Message) }
        Update-FhToolState
    }
}
function Set-FhBusy([bool]$On) {
    $script:FhBusy = $On
    $ui.BtnFhSend.IsEnabled = -not $On
    $ui.FhProgress.Visibility = $(if ($On) { 'Visible' } else { 'Collapsed' })
}
function Start-FhHelp {
    if ($script:FhBusy) { return }
    $null = Save-FhFromUi
    $cat = [string]$ui.FhCat.SelectedItem.Content; if (-not $cat) { $cat = 'Sonstiges' }
    $script:FhReq = @{ Category = $cat; Text = $ui.FhDesc.Text.Trim(); Net = [bool]$ui.FhNet.IsChecked; Events = [bool]$ui.FhEvents.IsChecked; Shot = ''; ShotErr = '' }
    Set-FhBusy $true
    $ui.FhResult.Visibility = 'Collapsed'
    $ui.FhSendInfo.Text = 'Hilfe-Paket wird geschnürt ...'
    if ($ui.FhShot.IsChecked) {
        $script:FhPrevState = [string]$window.WindowState
        $window.WindowState = 'Minimized'
        $script:FhShotTimer = New-Object Windows.Threading.DispatcherTimer
        $script:FhShotTimer.Interval = [TimeSpan]::FromMilliseconds(900)
        $script:FhShotTimer.Add_Tick({
            $script:FhShotTimer.Stop()
            try { $sf = Join-Path $env:TEMP ('PCTools_Hilfe_{0:yyyyMMdd_HHmmss}.png' -f (Get-Date)); $null = Save-FhScreenshot $sf; $script:FhReq.Shot = $sf } catch { $script:FhReq.ShotErr = $_.Exception.Message }
            try { $window.WindowState = $script:FhPrevState; $null = $window.Activate() } catch { }
            Start-FhCollect
        })
        $script:FhShotTimer.Start()
    } else { Start-FhCollect }
}
function Start-FhCollect {
    try {
        $cfg = $null; try { $cfg = Read-PflegeConfig } catch { }
        $fleet = if ($cfg -and $cfg.Fleet.Enabled -and [string]$cfg.Fleet.Dir) { [string]$cfg.Fleet.Dir } else { '' }
        $ha = $null; try { $ha = Get-HealthArgs } catch { $ha = @{} }
        $p = @{ DataDir = $DataDir; Category = $script:FhReq.Category; Text = $script:FhReq.Text; Net = $script:FhReq.Net; Events = $script:FhReq.Events; Shot = $script:FhReq.Shot; AppVersion = $AppVersion; HealthArgs = $ha; FleetDir = $fleet; ConfigFile = $ConfigFile; ConfigVersion = $ConfigVersion; UpdSrc = $DefaultUpdateSource }
        $fns = @('New-FhHelpPackage', 'Get-FhDeviceInfo', 'Get-HealthItems', 'Send-PflegeNotify', 'Read-PflegeConfig', 'Get-DefaultConfig', 'Invoke-NdCmd')
        if ($p.Net -and (Get-Command Get-NetDiag -ErrorAction SilentlyContinue)) {
            $ndList = if ($NdFns) { @($NdFns) } else { @('Get-NetDiag', 'Get-NetDiagAdapters', 'Get-NdWlanInfo', 'Get-NdIpv4', 'Get-HvNetInfo') }
            $fns += @($ndList | Where-Object { Get-Command $_ -CommandType Function -ErrorAction SilentlyContinue })
        }
        $fns = @($fns | Select-Object -Unique)
        $ui.FhSendInfo.Text = $(if ($p.Net) { 'Zustand, Netzwerk und Fehlermeldungen werden gesammelt (20-60 Sekunden) ...' } else { 'Zustand und Fehlermeldungen werden gesammelt ...' })
        Invoke-Bg -Script {
            param($pp)
            $ConfigFile = $pp.ConfigFile; $ConfigVersion = $pp.ConfigVersion; $DefaultUpdateSource = $pp.UpdSrc; $DataDir = $pp.DataDir
            $res = New-FhHelpPackage $pp
            $sent = @(); try { $sent = @(Send-PflegeNotify ('Hilfe angefordert: ' + $pp.Category) $res.Message $res.Level -Force) } catch { $sent = @('Benachrichtigung: ' + $_.Exception.Message) }
            $res | Add-Member -NotePropertyName Sent -NotePropertyValue $sent -Force
            $res
        } -Arguments @($p) -Functions $fns -Done { param($r, $err) Show-FhResult $r $err }
    } catch { Set-FhBusy $false; $ui.FhSendInfo.Text = 'Fehler: ' + $_.Exception.Message; Show-UiError ('Hilfe anfordern: ' + $_.Exception.Message) }
}
function Show-FhResult($r, $err) {
    Set-FhBusy $false
    $x = @($r | Where-Object { $_ -and $_.PSObject.Properties['Zip'] }) | Select-Object -Last 1
    $bc = New-Object Windows.Media.BrushConverter
    $ui.FhResult.Visibility = 'Visible'
    if ($err -or -not $x) {
        $ui.FhResultGlyph.Text = [string][char]0xE783; $ui.FhResultGlyph.Foreground = $bc.ConvertFromString('#B91C1C')
        $ui.FhResultTitle.Text = 'Das Hilfe-Paket konnte nicht erstellt werden'
        $ui.FhResultText.Text = $(if ($err) { $err.Message } else { 'keine Daten' }) + "`r`n`r`nBitte deinen Helfer direkt anrufen."
        $ui.FhSendInfo.Text = 'Fehlgeschlagen.'
        return
    }
    $script:FhLast = $x
    $sent = @($x.Sent | Where-Object { $_ })
    $okN = @($sent | Where-Object { [string]$_ -match ':\s*OK$' }).Count
    if ($okN) { $ui.FhResultGlyph.Text = [string][char]0xE73E; $ui.FhResultGlyph.Foreground = $bc.ConvertFromString('#15803D'); $ui.FhResultTitle.Text = 'Hilfe ist angefordert - dein Helfer hat eine Nachricht bekommen' }
    else { $ui.FhResultGlyph.Text = [string][char]0xE7BA; $ui.FhResultGlyph.Foreground = $bc.ConvertFromString('#C2410C'); $ui.FhResultTitle.Text = $(if ($sent.Count) { 'Hilfe-Paket ist fertig - die Benachrichtigung ist aber fehlgeschlagen' } else { 'Hilfe-Paket ist fertig - bitte deinen Helfer anrufen oder per E-Mail schicken' }) }
    $lines = [System.Collections.Generic.List[string]]::new()
    $lines.Add('NACHRICHT AN DEINEN HELFER:'); foreach ($l in @(([string]$x.Message) -split "`n")) { $lines.Add('  ' + $l) }
    $lines.Add('')
    if ($sent.Count) { $lines.Add('Verschickt über: ' + ($sent -join ' | ')) } else { $lines.Add('Nicht verschickt: In "Meine PCs > Handy-Benachrichtigungen" ist kein Kanal (ntfy, Home Assistant, Chat-Webhook) eingetragen.') }
    if ($script:FhReq -and $script:FhReq.ShotErr) { $lines.Add('Bildschirmfoto nicht möglich: ' + $script:FhReq.ShotErr) }
    $lines.Add('')
    $lines.Add('HILFE-PAKET (bleibt auf diesem PC): ' + $x.Zip)
    if ($x.Copied) { $lines.Add('Kopie im gemeinsamen Ordner: ' + $x.Copied) }
    $lines.Add('Inhalt: ' + (@($x.Files) -join ', '))
    $ui.FhResultText.Text = $lines -join "`r`n"
    $ui.FhSendInfo.Text = 'Fertig um {0:HH:mm}.' -f (Get-Date)
    $ui.StatusText.Text = $ui.FhResultTitle.Text
}
$ui.BtnFhSend.Add_Click({ try { Start-FhHelp } catch { Set-FhBusy $false; Show-UiError ('Hilfe anfordern: ' + $_.Exception.Message) } })
$ui.BtnFhOpenZip.Add_Click({ if ($script:FhLast -and (Test-Path -LiteralPath $script:FhLast.Zip)) { Start-Process explorer.exe ('/select,"{0}"' -f $script:FhLast.Zip) } })
