$ui.BtnFhMail.Add_Click({
    if (-not $script:FhLast) { return }
    $s = Get-FhSettings
    $subj = 'Hilfe-Anfrage von {0}: {1}' -f $env:COMPUTERNAME, $script:FhReq.Category
