$ui.BtnFhSave.Add_Click({ try { $null = Save-FhFromUi; Update-FhGuide; $ui.StatusText.Text = 'Fernhilfe-Einstellungen gespeichert.' } catch { Show-UiError ('Speichern: ' + $_.Exception.Message) } })
