    elseif ($s.SelectedItem -eq $ui.TabRemote -and -not $script:FhLoaded) { $script:FhLoaded = $true; try { Import-FhSettingsToUi; Update-FhToolState; Update-FhDevice } catch { $ui.StatusText.Text = 'Fernhilfe: ' + $_.Exception.Message } }
})

