# ---------------------------------------------------------------- Netzwerk-Werkzeuge (Oberfläche)
$script:NtDevFile = Join-Path $DataDir 'netzgeraete.json'
$script:NtWolFile = Join-Path $DataDir 'wol.json'
$script:NtSpFile = Join-Path $DataDir 'speedtest.csv'
$script:NtNetFns = @('Get-NtActiveNet', 'Format-NtMac', 'Get-NtBroadcast', 'ConvertTo-NtNum', 'ConvertFrom-NtNum')
$script:NtPalette = @('#EA580C', '#16A34A', '#7C3AED', '#DB2777', '#0891B2', '#CA8A04', '#DC2626', '#0F766E', '#9333EA', '#65A30D', '#C2410C', '#4F46E5')

# Fortschritt: Hintergrundjobs schreiben in eine synchronisierte Hashtable (P = Prozent, T = Text), ein Timer zeigt sie an
$script:NtProgList = New-Object System.Collections.ArrayList
$script:NtProgTimer = New-Object Windows.Threading.DispatcherTimer
$script:NtProgTimer.Interval = [TimeSpan]::FromMilliseconds(200)
$script:NtProgTimer.Add_Tick({
    foreach ($ntPg in @($script:NtProgList)) { try { $ntPg.Bar.Value = [double]$ntPg.Sync.P; if ($ntPg.Sync.T) { $ntPg.Label.Text = [string]$ntPg.Sync.T } } catch { } }
    if (-not $script:NtProgList.Count) { $script:NtProgTimer.Stop() }
})
function Start-NtProgress($Bar, $Label, [string]$Text, [switch]$Indeterminate) {
    $sync = [hashtable]::Synchronized(@{ P = 0; T = $Text })
    $Bar.Visibility = 'Visible'; $Bar.IsIndeterminate = [bool]$Indeterminate; $Bar.Value = 0; $Label.Text = $Text
    if (-not $Indeterminate) { [void]$script:NtProgList.Add(@{ Bar = $Bar; Label = $Label; Sync = $sync }); $script:NtProgTimer.Start() }
    return $sync
}
function Stop-NtProgress($Bar, $Label, [string]$Text) {
    foreach ($ntPg in @($script:NtProgList)) { if ($ntPg.Bar -eq $Bar) { $script:NtProgList.Remove($ntPg) } }
    $Bar.Visibility = 'Collapsed'; $Label.Text = $Text
}
function Get-NtBrush([string]$Hex) { (New-Object Windows.Media.BrushConverter).ConvertFromString($Hex) }
function Add-NtText($Canvas, [string]$Text, [double]$X, [double]$Y, [string]$Color = '#6B7890', [double]$Size = 11, [string]$Align = 'Left', [double]$Width = 0, [switch]$Bold) {
    $t = New-Object Windows.Controls.TextBlock; $t.Text = $Text; $t.FontSize = $Size; $t.Foreground = New-UiBrush $Color
    if ($Bold) { $t.FontWeight = 'SemiBold' }
    if ($Width -gt 0) { $t.Width = $Width; $t.TextAlignment = $Align; $t.TextTrimming = 'CharacterEllipsis' }
    [Windows.Controls.Canvas]::SetLeft($t, $X); [Windows.Controls.Canvas]::SetTop($t, $Y); [void]$Canvas.Children.Add($t)
    return $t
}
function Add-NtLine($Canvas, [double]$X1, [double]$Y1, [double]$X2, [double]$Y2, [string]$Color = '#E2E7F0', [double]$Thick = 1, [switch]$Dash) {
    $l = New-Object Windows.Shapes.Line; $l.X1 = $X1; $l.Y1 = $Y1; $l.X2 = $X2; $l.Y2 = $Y2; $l.Stroke = New-UiBrush $Color; $l.StrokeThickness = $Thick
    if ($Dash) { $dc = New-Object Windows.Media.DoubleCollection; $dc.Add(4); $dc.Add(3); $l.StrokeDashArray = $dc }
    [void]$Canvas.Children.Add($l)
}
function Get-NtNiceStep([double]$Range, [int]$Ticks = 4) {
    if ($Range -le 0) { $Range = 1 }
    $raw = $Range / $Ticks; $mag = [math]::Pow(10, [math]::Floor([math]::Log10($raw))); $norm = $raw / $mag
    foreach ($c in 1, 2, 2.5, 5, 10) { if ($norm -le $c) { return $c * $mag } }
    return 10 * $mag
}
# Liniendiagramm mit Achsen. Series: @( @{ Name; Color; Values = [double[]] (NaN = keine Messung) } ), XLabels je Punkt
function Show-NtLineChart($Canvas, $Series, [string[]]$XLabels, [string]$Unit, [switch]$ZeroBase) {
    $Canvas.Tag = @{ S = $Series; L = $XLabels; U = $Unit; Z = [bool]$ZeroBase }
    $Canvas.Children.Clear()
    $w = [double]$Canvas.ActualWidth; if ($w -lt 120) { $w = 820 }
    $h = [double]$Canvas.Height; $pl = 62; $pr = 16; $pt = 12; $pb = 26
    $pw = $w - $pl - $pr; $ph = $h - $pt - $pb
    $vals = @(foreach ($s in @($Series)) { foreach ($v in @($s.Values)) { if (-not [double]::IsNaN([double]$v)) { [double]$v } } })
    $n = @($XLabels).Count
    if (-not $vals.Count -or $n -lt 1) { $null = Add-NtText $Canvas 'Noch keine Messwerte vorhanden.' 0 ($h / 2 - 10) '#6B7890' 13 'Center' $w; return }
    $max = ($vals | Measure-Object -Maximum).Maximum; $min = ($vals | Measure-Object -Minimum).Minimum
    $lo = 0.0; if (-not $ZeroBase -and $min -gt 0 -and $min -gt 0.55 * $max) { $lo = $min - ($max - $min) * 0.3 }
    $step = Get-NtNiceStep ($max - $lo) 4
    $lo = [math]::Floor($lo / $step) * $step; $hi = [math]::Ceiling($max / $step) * $step; if ($hi -le $lo) { $hi = $lo + $step }
    $yOf = { param($v) $pt + $ph * (1 - ($v - $lo) / ($hi - $lo)) }
    $fmt = if ($step -lt 1) { 'N1' } else { 'N0' }
    for ($gv = $lo; $gv -le $hi + $step / 2; $gv += $step) {
        $gy = & $yOf $gv
        Add-NtLine $Canvas $pl $gy ($w - $pr) $gy '#E2E7F0' 1
        $null = Add-NtText $Canvas ($gv.ToString($fmt) + $(if ([math]::Abs($gv - $hi) -lt $step / 2) { ' ' + $Unit } else { '' })) 0 ($gy - 8) '#6B7890' 10.5 'Right' ($pl - 6)
    }
    Add-NtLine $Canvas $pl $pt $pl ($pt + $ph) '#C5CEDD' 1
    $xOf = { param($i) if ($n -le 1) { $pl + $pw / 2 } else { $pl + $pw * $i / ($n - 1) } }
    $k = [math]::Min($n, [math]::Max(2, [math]::Floor($pw / 115)))
    $shown = @{}
    for ($j = 0; $j -lt $k; $j++) {
        $i = if ($k -le 1) { 0 } else { [int][math]::Round($j * ($n - 1) / ($k - 1)) }
        if ($shown.ContainsKey($i)) { continue }; $shown[$i] = $true
        $null = Add-NtText $Canvas $XLabels[$i] ((& $xOf $i) - 45) ($pt + $ph + 6) '#6B7890' 10.5 'Center' 90
    }
    $first = $true
    foreach ($s in @($Series)) {
        $col = [string]$s.Color; $sv = @($s.Values)
        $pts = New-Object Windows.Media.PointCollection
        for ($i = 0; $i -lt $sv.Count; $i++) { if (-not [double]::IsNaN([double]$sv[$i])) { $pts.Add((New-Object Windows.Point ((& $xOf $i), (& $yOf ([double]$sv[$i]))))) } }
        if (-not $pts.Count) { continue }
        if ($first -and $pts.Count -ge 2) {
            $fill = New-Object Windows.Shapes.Polygon; $fp = New-Object Windows.Media.PointCollection
            $fp.Add((New-Object Windows.Point ($pts[0].X, ($pt + $ph)))); foreach ($q in $pts) { $fp.Add($q) }; $fp.Add((New-Object Windows.Point ($pts[$pts.Count - 1].X, ($pt + $ph))))
            $fill.Points = $fp; $fill.Fill = Get-NtBrush $col; $fill.Opacity = 0.09; [void]$Canvas.Children.Add($fill)
        }
        $first = $false
        $pl2 = New-Object Windows.Shapes.Polyline; $pl2.Points = $pts; $pl2.Stroke = Get-NtBrush $col; $pl2.StrokeThickness = 2.4; $pl2.StrokeLineJoin = 'Round'; [void]$Canvas.Children.Add($pl2)
        if ($sv.Count -le 90) {
            for ($i = 0; $i -lt $sv.Count; $i++) {
                if ([double]::IsNaN([double]$sv[$i])) { continue }
                $dot = New-Object Windows.Shapes.Ellipse; $dot.Width = 8; $dot.Height = 8; $dot.Fill = Get-NtBrush $col; $dot.Stroke = New-UiBrush '#FFFFFF'; $dot.StrokeThickness = 1.5
                $dot.ToolTip = '{0}: {1:N1} {2} ({3})' -f $XLabels[$i], [double]$sv[$i], $Unit, $s.Name
                [Windows.Controls.Canvas]::SetLeft($dot, (& $xOf $i) - 4); [Windows.Controls.Canvas]::SetTop($dot, (& $yOf ([double]$sv[$i])) - 4); [void]$Canvas.Children.Add($dot)
            }
        }
    }
}
foreach ($ntCv in @($ui.NtSpCanvas, $ui.AkHistCanvas)) {
    $ntCv.Add_SizeChanged({ param($s, $e) if ($s.Tag -and [math]::Abs($e.NewSize.Width - $e.PreviousSize.Width) -gt 2) { try { Show-NtLineChart $s $s.Tag.S $s.Tag.L $s.Tag.U -ZeroBase:([bool]$s.Tag.Z) } catch { } } })
}

# ---- Geräte im Netz
function Update-NtDevFilter {
    $script:FNtDev = @{ T = $ui.NtDevFilter.Text.Trim(); N = [bool]$ui.NtDevOnlyNew.IsChecked }
    if (-not $script:FNtDev.T -and -not $script:FNtDev.N) { Set-GridFilter $ui.NtDevGrid $null; return }
    Set-GridFilter $ui.NtDevGrid { param($o) $f = $script:FNtDev; (-not $f.N -or $o.IsNew) -and (Test-Match $o $f.T @('Name', 'Ip', 'Mac', 'Vendor', 'Host', 'Ports', 'NewText')) }
}
function Show-NtDevStoreInfo {
    try {
        $st = Read-NtDevStore $script:NtDevFile
        if ($st.Time) { $ui.NtDevNet.Text = 'Letzter Scan am {0:dd.MM.yyyy HH:mm} ({1}): {2} Geräte. Insgesamt bisher gesehen: {3} Geräte.' -f [datetime]$st.Time, $st.Net, @($st.LastScan).Count, @($st.Devices).Count; $ui.NtT0.Text = [string]@($st.LastScan).Count }
    } catch { }
}
function Start-NtDevScan {
    $ui.BtnNtDevScan.IsEnabled = $false
    $sync = Start-NtProgress $ui.NtDevProg $ui.NtDevState 'Ermittle das Netz ...'
    Invoke-Bg -Script {
        param($cp, $ports, $sy)
        $net = Get-NtActiveNet
        if (-not $net -or -not $net.Ip) { throw 'Kein aktiver Netzwerkadapter mit IPv4-Adresse gefunden.' }
        $dev = @(Invoke-NtSweep $net $cp $ports $sy)
        [pscustomobject]@{ Net = $net; Devices = $dev }
    } -Arguments @([bool]$ui.NtDevPorts.IsChecked, $NtQuickPorts, $sync) -Functions (@('Invoke-NtSweep', 'Get-NtSubnetHosts', 'Get-NtIpSort') + $script:NtNetFns) -Done {
        param($r, $err)
        $ui.BtnNtDevScan.IsEnabled = $true
        $x = @($r | Where-Object { $_ -and $_.PSObject.Properties['Devices'] })[0]
        if ($err -or -not $x) { Stop-NtProgress $ui.NtDevProg $ui.NtDevState ('Suche fehlgeschlagen: ' + $(if ($err) { $err.Message } else { 'kein Ergebnis' })); return }
        try {
            $store = Read-NtDevStore $script:NtDevFile
            $rows = ConvertTo-NtDeviceRows $x.Devices $store $x.Net $NtOui
            $netTxt = '{0}/{1} über {2}' -f $x.Net.Ip, $x.Net.Prefix, $x.Net.Name
            $script:NtDevStore = Save-NtDevStore $script:NtDevFile $store $rows $netTxt
            $script:NtDevRows = @($rows); $script:NtDevNet = $x.Net
            Set-GridItems $ui.NtDevGrid $script:NtDevRows; Update-NtDevFilter
            $newCnt = @($rows | Where-Object IsNew).Count
            $gone = @(@($store.LastScan) | Where-Object { $k = $_; -not @($rows | Where-Object { $_.Key -eq $k }).Count }).Count
            $ui.NtT0.Text = [string]$rows.Count; $ui.NtT1.Text = [string]$newCnt
            $ui.NtDevNet.Text = 'Netz {0} ({1}, Router {2}): {3} Geräte gefunden, {4} davon neu{5}. {6} antworten nicht auf Ping, stehen aber in der ARP-Tabelle.' -f $netTxt, $x.Net.Kind, $x.Net.Gateway, $rows.Count, $newCnt, $(if ($gone) { ', {0} vom letzten Mal sind gerade nicht erreichbar (aus/Standby)' -f $gone } else { '' }), @($rows | Where-Object { $_.Rtt -lt 0 -and -not $_.Self }).Count
            Stop-NtProgress $ui.NtDevProg $ui.NtDevState ('Fertig am {0:dd.MM.yyyy HH:mm}. Doppelklick auf ein Gerät öffnet seine Weboberfläche.' -f (Get-Date))
            if ($newCnt) { $ui.StatusText.Text = '{0} neue(s) Gerät(e) im Netz - orange markiert.' -f $newCnt }
        } catch { Stop-NtProgress $ui.NtDevProg $ui.NtDevState ('Auswertung fehlgeschlagen: ' + $_.Exception.Message) }
    }
}
function Open-NtDevWeb($Row) {
    if (-not $Row) { Show-UiError 'Bitte ein Gerät auswählen.'; return }
    $p = @($Row.PortList)
    $u = if ($p -contains 443) { "https://$($Row.Ip)/" } elseif ($p -contains 80) { "http://$($Row.Ip)/" } elseif ($p -contains 8080) { "http://$($Row.Ip):8080/" } elseif ($p -contains 8123) { "http://$($Row.Ip):8123/" } elseif ($p -contains 5000) { "http://$($Row.Ip):5000/" } else { "http://$($Row.Ip)/" }
    try { Start-Process $u } catch { Show-UiError ('Konnte {0} nicht öffnen: {1}' -f $u, $_.Exception.Message) }
}
$ui.BtnNtDevScan.Add_Click({ Start-NtDevScan })
$ui.NtDevFilter.Add_TextChanged({ Update-NtDevFilter })
$ui.NtDevOnlyNew.Add_Click({ Update-NtDevFilter })
$ui.NtDevGrid.Add_MouseDoubleClick({ if ($ui.NtDevGrid.SelectedItem) { Open-NtDevWeb $ui.NtDevGrid.SelectedItem } })
$ui.BtnNtDevWeb.Add_Click({ Open-NtDevWeb $ui.NtDevGrid.SelectedItem })
$ui.BtnNtDevCopy.Add_Click({
    if (-not $script:NtDevRows) { Show-UiError 'Bitte zuerst das Netz durchsuchen.'; return }
    Set-Clipboard -Value ((@("Name`tIP`tMAC`tHersteller`tAntwort`tAnschlüsse`tStatus") + @($script:NtDevRows | ForEach-Object { "{0}`t{1}`t{2}`t{3}`t{4}`t{5}`t{6}" -f $_.Name, $_.Ip, $_.Mac, $_.Vendor, $_.RttText, $_.Ports, $_.NewText })) -join "`r`n")
    $ui.StatusText.Text = 'Geräteliste in die Zwischenablage kopiert (für Excel geeignet).'
})
$ui.BtnNtDevName.Add_Click({
    $row = $ui.NtDevGrid.SelectedItem; if (-not $row) { Show-UiError 'Bitte ein Gerät auswählen.'; return }
    $st = Read-NtDevStore $script:NtDevFile
    $cur = ''; if ($st.Names.PSObject.Properties[$row.Key]) { $cur = [string]$st.Names.($row.Key) }
    $res = Show-InputDialog 'Gerätename' ('Eigener Name für {0} ({1}{2}). Leer lassen = automatischer Name.' -f $row.Ip, $row.Mac, $(if ($row.Vendor) { ', ' + $row.Vendor } else { '' })) @(@{ Key = 'Name'; Label = 'Name, z.B. "Drucker Büro" oder "Shelly Flur"'; Type = 'Text'; Value = $cur })
    if ($null -eq $res) { return }
    try {
        if ($res.Name) { $st.Names | Add-Member -NotePropertyName $row.Key -NotePropertyValue $res.Name -Force } elseif ($st.Names.PSObject.Properties[$row.Key]) { $st.Names.PSObject.Properties.Remove($row.Key) }
        $st | ConvertTo-Json -Depth 5 | Set-Content -LiteralPath $script:NtDevFile -Encoding UTF8
        $row.Name = $(if ($res.Name) { $res.Name } elseif ($row.Host) { $row.Host } else { '(unbekannt)' }) + $(if ($row.Gateway) { '  [Router]' } elseif ($row.Self) { '  [dieser PC]' } else { '' })
        $ui.NtDevGrid.Items.Refresh()
    } catch { Show-UiError ('Speichern fehlgeschlagen: ' + $_.Exception.Message) }
})

# ---- Wake-on-LAN
function Update-NtWolGrid {
    $script:NtWol = @(Read-NtWolList $script:NtWolFile | ForEach-Object {
            $_ | Add-Member -NotePropertyName LastText -NotePropertyValue $(if ($_.Last) { try { ([datetime]$_.Last).ToString('dd.MM.yyyy HH:mm') } catch { '' } } else { 'noch nie' }) -Force -PassThru })
    foreach ($w in $script:NtWol) { if (-not $w.PSObject.Properties['Ip']) { $w | Add-Member -NotePropertyName Ip -NotePropertyValue '' } }
    Set-GridItems $ui.NtWolGrid $script:NtWol
}
function Add-NtWolEntry([string]$Name, [string]$Mac, [string]$Bc, [string]$Ip) {
    try { $null = ConvertTo-NtMacBytes $Mac } catch { Show-UiError $_.Exception.Message; return $false }
    $mac2 = Format-NtMac $Mac
    $list = [System.Collections.Generic.List[object]]::new(); foreach ($w in @(Read-NtWolList $script:NtWolFile)) { if ((Format-NtMac $w.Mac) -ne $mac2) { $list.Add($w) } }
    $list.Add([pscustomobject]@{ Name = $(if ($Name) { $Name } else { $mac2 }); Mac = $mac2; Broadcast = $(if ($Bc) { $Bc } else { '255.255.255.255' }); Ip = $Ip; Last = '' })
    Save-NtWolList $script:NtWolFile $list; Update-NtWolGrid
    $ui.NtWolInfo.Text = '"{0}" ({1}) gespeichert.' -f $Name, $mac2
    return $true
}
function Get-NtDefaultBroadcast { if ($script:NtDevNet) { return [string]$script:NtDevNet.Broadcast }; try { $n = Get-NtActiveNet; if ($n) { return [string]$n.Broadcast } } catch { }; return '255.255.255.255' }
$ui.BtnNtWolAdd.Add_Click({
    $res = Show-InputDialog 'Wake-on-LAN' 'Gerät hinzufügen, das per Netzwerk eingeschaltet werden soll. Die MAC-Adresse steht z.B. in der Router-Oberfläche oder auf dem Ziel-PC unter "ipconfig /all" (Physische Adresse des Kabel-Adapters).' @(
        @{ Key = 'Name'; Label = 'Name'; Type = 'Text'; Value = '' }, @{ Key = 'Mac'; Label = 'MAC-Adresse (z.B. 3C:A6:2F:12:34:56)'; Type = 'Text'; Value = '' },
        @{ Key = 'Bc'; Label = 'Broadcast-Adresse des Netzes'; Type = 'Text'; Value = (Get-NtDefaultBroadcast) }, @{ Key = 'Ip'; Label = 'IP-Adresse (optional, zum Prüfen ob er wach ist)'; Type = 'Text'; Value = '' })
    if ($res) { $null = Add-NtWolEntry $res.Name $res.Mac $res.Bc $res.Ip }
})
$ui.BtnNtWolEdit.Add_Click({
    $w = $ui.NtWolGrid.SelectedItem; if (-not $w) { Show-UiError 'Bitte einen Eintrag auswählen.'; return }
    $res = Show-InputDialog 'Wake-on-LAN' 'Eintrag bearbeiten.' @(@{ Key = 'Name'; Label = 'Name'; Type = 'Text'; Value = $w.Name }, @{ Key = 'Mac'; Label = 'MAC-Adresse'; Type = 'Text'; Value = $w.Mac }, @{ Key = 'Bc'; Label = 'Broadcast-Adresse'; Type = 'Text'; Value = $w.Broadcast }, @{ Key = 'Ip'; Label = 'IP-Adresse (optional)'; Type = 'Text'; Value = $w.Ip })
    if (-not $res) { return }
    try { $null = ConvertTo-NtMacBytes $res.Mac } catch { Show-UiError $_.Exception.Message; return }
    $list = @(Read-NtWolList $script:NtWolFile | Where-Object { (Format-NtMac $_.Mac) -ne (Format-NtMac $w.Mac) })
    $list += [pscustomobject]@{ Name = $res.Name; Mac = (Format-NtMac $res.Mac); Broadcast = $res.Bc; Ip = $res.Ip; Last = $w.Last }
    Save-NtWolList $script:NtWolFile $list; Update-NtWolGrid
})
$ui.BtnNtWolDel.Add_Click({
    $w = $ui.NtWolGrid.SelectedItem; if (-not $w) { Show-UiError 'Bitte einen Eintrag auswählen.'; return }
    if (-not (Confirm-Ui ('"{0}" ({1}) aus der Wake-on-LAN-Liste entfernen?' -f $w.Name, $w.Mac))) { return }
    Save-NtWolList $script:NtWolFile @(Read-NtWolList $script:NtWolFile | Where-Object { (Format-NtMac $_.Mac) -ne (Format-NtMac $w.Mac) }); Update-NtWolGrid
})
function Add-NtWolFromRow($Row) {
    if (-not $Row -or -not $Row.Mac) { Show-UiError 'Für dieses Gerät ist keine MAC-Adresse bekannt.'; return }
    if ($Row.Vendor -like 'Zufällige*' -and -not (Confirm-Ui ('{0} benutzt eine zufällige MAC-Adresse (typisch für Handys/Tablets). Wake-on-LAN funktioniert damit meist nicht. Trotzdem übernehmen?' -f $Row.Name))) { return }
    $nm = ($Row.Name -replace '\s+\[(Router|dieser PC)\]$', '') -replace '^\((.*)\)$', '$1'
    if (Add-NtWolEntry $nm $Row.Mac (Get-NtDefaultBroadcast) $Row.Ip) { Show-NtSection 'NtSecWol' }
}
$ui.BtnNtDevWol.Add_Click({ Add-NtWolFromRow $ui.NtDevGrid.SelectedItem })
$ui.BtnNtWolScan.Add_Click({
    $cand = @($script:NtDevRows | Where-Object { $_.Mac -and -not $_.Gateway -and -not $_.Self })
    if (-not $cand.Count) { Show-UiError 'Noch keine Geräte gefunden - bitte oben zuerst "Netz durchsuchen" (der Ziel-PC muss dabei eingeschaltet sein).'; return }
    $labels = @($cand | ForEach-Object { '{0} - {1} - {2}{3}' -f $_.Name, $_.Ip, $_.Mac, $(if ($_.Vendor) { ' (' + $_.Vendor + ')' } else { '' }) })
    $res = Show-InputDialog 'Aus Scan übernehmen' 'Welches Gerät soll per Wake-on-LAN geweckt werden können?' @(@{ Key = 'Dev'; Label = 'Gerät'; Type = 'Combo'; Items = $labels })
    if (-not $res) { return }
    $i = [array]::IndexOf($labels, [string]$res.Dev); if ($i -ge 0) { Add-NtWolFromRow $cand[$i] }
})
$ui.BtnNtWolSend.Add_Click({
    $w = $ui.NtWolGrid.SelectedItem; if (-not $w) { Show-UiError 'Bitte einen Eintrag auswählen.'; return }
    try { $to = Send-NtWol $w.Mac $w.Broadcast } catch { $ui.NtWolInfo.Text = 'Senden fehlgeschlagen: ' + $_.Exception.Message; return }
    $list = @(Read-NtWolList $script:NtWolFile); foreach ($x in $list) { if ((Format-NtMac $x.Mac) -eq (Format-NtMac $w.Mac)) { $x | Add-Member -NotePropertyName Last -NotePropertyValue (Get-Date).ToString('o') -Force } }
    Save-NtWolList $script:NtWolFile $list; Update-NtWolGrid
    $ui.NtWolInfo.Text = 'Magic Packet für "{0}" gesendet an {1}. Ein PC braucht meist 10-60 Sekunden zum Starten.' -f $w.Name, $to
    if ($w.Ip) {
        $script:NtWolWait = $w
        $ui.NtWolInfo.Text += (' Prüfe, ob {0} antwortet ...' -f $w.Ip)
        Invoke-Bg -Script { param($ip) $pg = New-Object Net.NetworkInformation.Ping; $sw = [Diagnostics.Stopwatch]::StartNew(); while ($sw.Elapsed.TotalSeconds -lt 120) { try { if ($pg.Send($ip, 1000).Status -eq 'Success') { return [int]$sw.Elapsed.TotalSeconds } } catch { }; Start-Sleep -Milliseconds 1500 }; return -1 } -Arguments @($w.Ip) -Done {
            param($r, $err)
            $sec = [int](@($r)[-1])
            $ui.NtWolInfo.Text = if ($sec -ge 0) { '"{0}" ist wach - antwortet nach {1} Sekunden auf {2}.' -f $script:NtWolWait.Name, $sec, $script:NtWolWait.Ip } else { '"{0}" antwortet nach 2 Minuten noch nicht auf {1}. Prüfen: Wake-on-LAN im BIOS und beim Adapter an, Windows-Schnellstart aus, Kabelverbindung (nicht WLAN), richtige MAC. Manche PCs blocken Ping in der Firewall - dann ist er evtl. trotzdem an.' -f $script:NtWolWait.Name, $script:NtWolWait.Ip }
        }
    }
})

# ---- Speedtest-Verlauf
function Update-NtSpeed {
    $all = @(Read-NtSpeedHistory $script:NtSpFile | ForEach-Object { $_ })
    $kind = @('', 'LAN', 'WLAN')[[math]::Max(0, $ui.NtSpKind.SelectedIndex)]
    $days = @(30, 90, 365, 100000)[[math]::Max(0, $ui.NtSpRange.SelectedIndex)]
    $from = (Get-Date).AddDays(-$days)
    $rows = @($all | Where-Object { $_.Date -ge $from -and (-not $kind -or $_.Kind -eq $kind) })
    $script:NtSpRows = $rows
    Set-GridItems $ui.NtSpGrid @($rows | Sort-Object Date -Descending)
    $ok = @($rows | Where-Object { $_.Down -gt 0 })
    if ($all.Count) { $lastOk = @($all | Where-Object { $_.Down -gt 0 })[-1]; if ($lastOk) { $ui.NtT2.Text = '{0:N0}' -f $lastOk.Down } }
    if ($ok.Count) {
        $avgD = ($ok | Measure-Object Down -Average).Average; $avgU = ($ok | Measure-Object Up -Average).Average; $avgP = (@($ok | Where-Object { $_.Ping -ge 0 }) | Measure-Object Ping -Average).Average
        $maxD = ($ok | Measure-Object Down -Maximum).Maximum; $minD = ($ok | Measure-Object Down -Minimum).Minimum
        $lan = @($ok | Where-Object Kind -eq 'LAN'); $wl = @($ok | Where-Object Kind -eq 'WLAN')
        $cmp = if ($lan.Count -and $wl.Count) { $a1 = ($lan | Measure-Object Down -Average).Average; $a2 = ($wl | Measure-Object Down -Average).Average; ' LAN im Schnitt {0:N0}, WLAN {1:N0} Mbit/s{2}.' -f $a1, $a2, $(if ($a2 -lt 0.6 * $a1) { ' - das WLAN bremst deutlich' } else { '' }) } else { '' }
        $fails = @($rows | Where-Object { $_.Down -le 0 }).Count
        $ui.NtSpInfo.Text = '{0} Messungen: Download im Schnitt {1:N0} Mbit/s (min. {2:N0}, max. {3:N0}), Upload {4:N0} Mbit/s, Ping {5:N0} ms.{6}{7}' -f $ok.Count, $avgD, $minD, $maxD, $avgU, $avgP, $cmp, $(if ($fails) { ' {0} Messung(en) ohne Ergebnis (Internet weg?).' -f $fails } else { '' })
    } else { $ui.NtSpInfo.Text = if ($all.Count) { 'Keine Messungen im gewählten Zeitraum/Filter.' } else { 'Noch keine Messungen. "Jetzt messen" starten - Messungen auf der Seite Netzwerk werden ebenfalls hier gespeichert.' } }
    $sameYear = $true; if ($rows.Count) { $sameYear = ($rows[0].Date.Year -eq $rows[-1].Date.Year) -and ($rows[0].Date.Year -eq (Get-Date).Year) }
    $lab = [string[]]@($rows | ForEach-Object { $_.Date.ToString($(if ($sameYear) { 'dd.MM. HH:mm' } else { 'dd.MM.yy' })) })
    $dn = [double[]]@($rows | ForEach-Object { if ($_.Down -gt 0) { $_.Down } else { [double]::NaN } })
    $upv = [double[]]@($rows | ForEach-Object { if ($_.Up -gt 0) { $_.Up } else { [double]::NaN } })
    Show-NtLineChart $ui.NtSpCanvas @(@{ Name = 'Download'; Color = '#2D7FF9'; Values = $dn }, @{ Name = 'Upload'; Color = '#7C3AED'; Values = $upv }) $lab 'Mbit/s' -ZeroBase
}
$ui.NtSpKind.Add_SelectionChanged({ param($s, $e) $e.Handled = $true; if ($script:NtLoaded) { Update-NtSpeed } })
$ui.NtSpRange.Add_SelectionChanged({ param($s, $e) $e.Handled = $true; if ($script:NtLoaded) { Update-NtSpeed } })
$ui.BtnNtSpRun.Add_Click({
    $ui.BtnNtSpRun.IsEnabled = $false
    $null = Start-NtProgress $ui.NtSpProg $ui.NtSpState 'Messe Ping, Download (50 MB) und Upload (10 MB) - ca. 20-40 Sekunden ...' -Indeterminate
    Invoke-Bg -Script { $n = $null; try { $n = Get-NtActiveNet } catch { }; [pscustomobject]@{ Speed = (Invoke-SpeedTest); Net = $n } } -Functions (@('Invoke-SpeedTest') + $script:NtNetFns) -Done {
        param($r, $err)
        $ui.BtnNtSpRun.IsEnabled = $true
        $x = @($r | Where-Object { $_ -and $_.PSObject.Properties['Speed'] })[0]
        if ($err -or -not $x) { Stop-NtProgress $ui.NtSpProg $ui.NtSpState ('Messung fehlgeschlagen: ' + $(if ($err) { $err.Message } else { 'kein Ergebnis' })); return }
        try { Add-NtSpeedHistory $x.Speed $x.Net } catch { $ui.StatusText.Text = 'Speichern der Messung fehlgeschlagen: ' + $_.Exception.Message }
        $s = $x.Speed
        Stop-NtProgress $ui.NtSpProg $ui.NtSpState $(if ([double]$s.Down -gt 0) { 'Gemessen ({0}): Download {1:N1} Mbit/s, Upload {2:N1} Mbit/s, Ping {3} ms, Schwankung {4} ms.' -f $(if ($x.Net) { $x.Net.Kind } else { '?' }), [double]$s.Down, [double]$s.Up, $s.Ping, $s.Jitter } else { 'Keine Verbindung zum Messserver - Internet erreichbar? (Die fehlgeschlagene Messung ist im Verlauf rot vermerkt.)' })
        Update-NtSpeed
    }
})
$ui.BtnNtSpDel.Add_Click({
    $row = $ui.NtSpGrid.SelectedItem; if (-not $row) { Show-UiError 'Bitte eine Messung auswählen.'; return }
    if (Confirm-Ui ('Messung vom {0} ({1}) löschen?' -f $row.DateText, $row.DownText)) { try { Remove-NtSpeedEntry $script:NtSpFile $row.Raw; Update-NtSpeed } catch { Show-UiError $_.Exception.Message } }
})
$ui.BtnNtSpOpen.Add_Click({ if (Test-Path -LiteralPath $script:NtSpFile) { try { Start-Process -FilePath $script:NtSpFile } catch { Start-Process explorer.exe -ArgumentList ('/select,"{0}"' -f $script:NtSpFile) } } else { Show-UiError 'Noch keine Messungen gespeichert.' } })

# ---- DNS-Vergleich
function Show-NtDnsChart($Rows, [string]$Best) {
    $cv = $ui.NtDnsCanvas; $cv.Children.Clear()
    $list = @($Rows); $cv.Height = [math]::Max(60, $list.Count * 36 + 12)
    if (-not $list.Count) { return }
    $w = [double]$cv.ActualWidth; if ($w -lt 300) { $w = 820 }
    $lw = 210; $vw = 190; $bw = [math]::Max(80, $w - $lw - $vw)
    $mx = [double](@($list | ForEach-Object { [math]::Max([double]$_.Median, [double]$_.Avg) }) | Measure-Object -Maximum).Maximum; if ($mx -le 0) { $mx = 1 }
    $mx = [math]::Ceiling($mx / (Get-NtNiceStep $mx 4)) * (Get-NtNiceStep $mx 4)
    for ($i = 0; $i -lt $list.Count; $i++) {
        $d = $list[$i]; $y = 6 + $i * 36
        $null = Add-NtText $cv ('{0}' -f $d.Name) 0 ($y + 1) '#1F2A44' 12 'Left' ($lw - 10) -Bold
        $null = Add-NtText $cv $d.Server 0 ($y + 17) '#6B7890' 10.5 'Left' ($lw - 10)
        $bg = New-Object Windows.Shapes.Rectangle; $bg.Width = $bw; $bg.Height = 20; $bg.RadiusX = 5; $bg.RadiusY = 5; $bg.Fill = New-UiBrush '#EEF2F8'
        [Windows.Controls.Canvas]::SetLeft($bg, $lw); [Windows.Controls.Canvas]::SetTop($bg, $y + 6); [void]$cv.Children.Add($bg)
        if ([double]$d.Median -ge 0) {
            $col = if ($d.Server -eq $Best) { '#16A34A' } elseif ($d.Router -or $d.Current) { '#2D7FF9' } else { '#8B5CF6' }
            $bar = New-Object Windows.Shapes.Rectangle; $bar.Width = [math]::Max(3, $bw * [double]$d.Median / $mx); $bar.Height = 20; $bar.RadiusX = 5; $bar.RadiusY = 5; $bar.Fill = Get-NtBrush $col
            $bar.ToolTip = 'Median {0:N1} ms, Mittelwert {1:N1} ms, schnellste {2:N1} ms, langsamste {3:N1} ms' -f $d.Median, $d.Avg, $d.Min, $d.Max
            [Windows.Controls.Canvas]::SetLeft($bar, $lw); [Windows.Controls.Canvas]::SetTop($bar, $y + 6); [void]$cv.Children.Add($bar)
            $mk = New-Object Windows.Shapes.Rectangle; $mk.Width = 2.5; $mk.Height = 28; $mk.Fill = New-UiBrush '#1F2A44'
            [Windows.Controls.Canvas]::SetLeft($mk, $lw + [math]::Min($bw - 2, $bw * [double]$d.Avg / $mx)); [Windows.Controls.Canvas]::SetTop($mk, $y + 2); [void]$cv.Children.Add($mk)
            $t = Add-NtText $cv ('{0:N0} ms  (Ø {1:N0} ms){2}' -f $d.Median, $d.Avg, $(if ($d.Fail) { '  ·  {0} Ausfälle' -f $d.Fail } else { '' })) ($lw + $bw + 10) ($y + 7) $(if ($d.Fail) { '#C81E1E' } else { '#1F2A44' }) 12
        } else { $null = Add-NtText $cv 'keine Antwort (blockiert oder offline)' ($lw + 8) ($y + 8) '#C81E1E' 12 }
    }
}
$ui.BtnNtDnsRun.Add_Click({
    $ui.BtnNtDnsRun.IsEnabled = $false; $ui.NtDnsAdvice.Text = ''
    $sync = Start-NtProgress $ui.NtDnsProg $ui.NtDnsState 'Ermittle den aktuellen DNS-Server ...'
    Invoke-Bg -Script {
        param($pub, $doms, $sy)
        $net = $null; try { $net = Get-NtActiveNet } catch { }
        $srv = [System.Collections.Generic.List[object]]::new()
        $cur = if ($net) { @($net.Dns | Where-Object { $_ -match '^\d+\.\d+\.\d+\.\d+$' }) } else { @() }
        if ($cur.Count) { $isGw = [bool]($net -and $cur[0] -eq $net.Gateway); $srv.Add(@{ Name = $(if ($isGw) { 'Router (aktuell)' } elseif ($pub.Contains($cur[0])) { $pub[$cur[0]] + ' (aktuell)' } else { 'Aktuell eingestellt' }); Ip = $cur[0]; Router = $isGw; Current = $true }) }
        if ($net -and $net.Gateway -and -not @($srv | Where-Object { $_.Ip -eq $net.Gateway }).Count) { $srv.Add(@{ Name = 'Router'; Ip = $net.Gateway; Router = $true; Current = $false }) }
        foreach ($k in $pub.Keys) { if (-not @($srv | Where-Object { $_.Ip -eq $k }).Count) { $srv.Add(@{ Name = $pub[$k]; Ip = $k; Router = $false; Current = $false }) } }
        $res = @(Measure-NtDns $srv.ToArray() $doms 2 $sy)
        [pscustomobject]@{ Net = $net; Rows = $res }
    } -Arguments @($NtDnsServers, $NtDnsDomains, $sync) -Functions (@('Measure-NtDns', 'Get-NtStats') + $script:NtNetFns) -Done {
        param($r, $err)
        $ui.BtnNtDnsRun.IsEnabled = $true
        $x = @($r | Where-Object { $_ -and $_.PSObject.Properties['Rows'] })[0]
        if ($err -or -not $x) { Stop-NtProgress $ui.NtDnsProg $ui.NtDnsState ('Vergleich fehlgeschlagen: ' + $(if ($err) { $err.Message } else { 'kein Ergebnis' })); return }
        $script:NtDnsNet = $x.Net
        $rank = Get-NtDnsRanking @($x.Rows)
        $i = 0; $pos = @{}; foreach ($q in @($rank.Ranked)) { $i++; $pos[$q.Server] = $i }
        $script:NtDnsRows = @($x.Rows | ForEach-Object {
                $_ | Add-Member -NotePropertyName Rank -NotePropertyValue $(if ($pos.ContainsKey($_.Server)) { $pos[$_.Server] } else { 99 }) -Force
                $_ | Add-Member -NotePropertyName RankText -NotePropertyValue $(if ($pos.ContainsKey($_.Server)) { [string]$pos[$_.Server] } else { '-' }) -Force
                foreach ($p in @(@('MedText', 'Median'), @('AvgText', 'Avg'), @('MinText', 'Min'), @('MaxText', 'Max'))) { $_ | Add-Member -NotePropertyName $p[0] -NotePropertyValue $(if ([double]$_.($p[1]) -ge 0) { '{0:N0} ms' -f [double]$_.($p[1]) } else { '-' }) -Force }
                $_ | Add-Member -NotePropertyName FailText -NotePropertyValue ('{0} / {1}' -f $_.Fail, $_.Count) -Force
                $_ | Add-Member -NotePropertyName Level -NotePropertyValue $(if ($rank.Best -and $_.Server -eq $rank.Best.Server) { 'Good' } elseif ([double]$_.Median -lt 0) { 'Error' } elseif ($_.Fail) { 'Warn' } else { '' }) -Force
                $_ } | Sort-Object Rank)
        Set-GridItems $ui.NtDnsGrid $script:NtDnsRows
        $script:NtDnsBest = $rank.Best
        Show-NtDnsChart $script:NtDnsRows $(if ($rank.Best) { $rank.Best.Server } else { '' })
        $ui.NtDnsAdvice.Text = $rank.Text
        if ($rank.Best) { $ui.NtT3.Text = '{0:N0}' -f $rank.Best.Median }
        Stop-NtProgress $ui.NtDnsProg $ui.NtDnsState ('Gemessen am {0:dd.MM.yyyy HH:mm}: {1} Server, je {2} Abfragen über den aktiven Adapter{3}.' -f (Get-Date), @($x.Rows).Count, $NtDnsDomains.Count * 2, $(if ($x.Net) { ' ' + $x.Net.Name } else { '' }))
    }
})
$ui.NtDnsCanvas.Add_SizeChanged({ param($s, $e) if ($script:NtDnsRows -and [math]::Abs($e.NewSize.Width - $e.PreviousSize.Width) -gt 2) { try { Show-NtDnsChart $script:NtDnsRows $(if ($script:NtDnsBest) { $script:NtDnsBest.Server } else { '' }) } catch { } } })
$ui.BtnNtDnsApply.Add_Click({
    $row = $ui.NtDnsGrid.SelectedItem; if (-not $row) { $row = $script:NtDnsBest }
    if (-not $row) { Show-UiError 'Bitte zuerst den Vergleich starten.'; return }
    $net = $script:NtDnsNet; if (-not $net) { try { $net = Get-NtActiveNet } catch { } }
    if (-not $net) { Show-UiError 'Kein aktiver Netzwerkadapter gefunden.'; return }
    $auto = [bool]$row.Router
    $servers = if ($auto) { @() } else { @($row.Server) + @($(if ($NtDnsPairs.ContainsKey($row.Server)) { $NtDnsPairs[$row.Server] })) | Where-Object { $_ } }
    if ($row.Current -and -not $auto) { Show-UiError ('{0} ({1}) ist bereits eingestellt.' -f $row.Name, $row.Server); return }
    $msg = if ($auto) { "DNS für den Adapter ""{0}"" wieder auf automatisch stellen (DNS-Server kommt per DHCP, normalerweise der Router {1})?" -f $net.Name, $net.Gateway } else { "DNS für den Adapter ""{0}"" auf {1} ({2}) umstellen?`n`nAchtung: Namen aus dem Heimnetz (z.B. fritz.box, NAS, Drucker per Name) lassen sich danach evtl. nicht mehr auflösen. Besser ist es meist, den Anbieter im Router als Upstream-DNS einzutragen.`n`nRückgängig: hier die Zeile ""Router"" wählen und übernehmen, oder Seite Netzwerk > DNS-Server > Automatisch." -f $net.Name, $row.Name, ($servers -join ', ') }
    if (-not (Confirm-Ui $msg)) { return }
    try {
        if ($auto) { Set-DnsClientServerAddress -InterfaceIndex $net.Index -ResetServerAddresses -ErrorAction Stop } else { Set-DnsClientServerAddress -InterfaceIndex $net.Index -ServerAddresses $servers -ErrorAction Stop }
        Clear-DnsClientCache -ErrorAction SilentlyContinue
        $ui.StatusText.Text = 'DNS für {0}: {1}' -f $net.Name, $(if ($auto) { 'automatisch' } else { $servers -join ', ' })
        $ui.NtDnsAdvice.Text = 'Übernommen: {0}. Der DNS-Cache wurde geleert.' -f $(if ($auto) { 'automatisch vom Router' } else { '{0} ({1})' -f $row.Name, ($servers -join ', ') })
        if ($script:NetLoaded) { try { Update-NetPage } catch { } }
    } catch { Show-UiError ('DNS konnte nicht gesetzt werden (Administratorrechte?): ' + $_.Exception.Message) }
})

# ---- WLAN-Kanal-Planer
function Get-NtSsidColor([string]$Ssid, [bool]$Own) {
    if ($Own) { return '#2D7FF9' }
    $sum = 0; foreach ($ch in $Ssid.ToCharArray()) { $sum += [int]$ch }
    return $script:NtPalette[$sum % $script:NtPalette.Count]
}
function Show-NtWlan24($Nets, [string]$OwnSsid, [int]$Best) {
    $cv = $ui.NtWlan24; $cv.Children.Clear()
    $w = [double]$cv.ActualWidth; if ($w -lt 300) { $w = 820 }
    $h = [double]$cv.Height; $pl = 40; $pr = 12; $pt = 18; $pb = 24; $pw = $w - $pl - $pr; $ph = $h - $pt - $pb
    $xOf = { param($c) $pl + $pw * ($c + 1) / 16.0 }
    $yOf = { param($s) $pt + $ph * (1 - $s / 100.0) }
    foreach ($g in 25, 50, 75, 100) { $gy = & $yOf $g; Add-NtLine $cv $pl $gy ($w - $pr) $gy '#E2E7F0' 1; $null = Add-NtText $cv ('{0} %' -f $g) 0 ($gy - 8) '#6B7890' 10 'Right' ($pl - 6) }
    Add-NtLine $cv $pl ($pt + $ph) ($w - $pr) ($pt + $ph) '#C5CEDD' 1
    foreach ($c in 1..13) {
        $cx = & $xOf $c
        if ($c -in 1, 6, 11) { Add-NtLine $cv $cx $pt $cx ($pt + $ph) $(if ($c -eq $Best) { '#16A34A' } else { '#C5CEDD' }) $(if ($c -eq $Best) { 2 } else { 1 }) -Dash }
        $null = Add-NtText $cv ([string]$c) ($cx - 15) ($pt + $ph + 4) $(if ($c -eq $Best) { '#15803D' } else { '#6B7890' }) 11 'Center' 30 -Bold:($c -in 1, 6, 11)
    }
    if ($Best) { $null = Add-NtText $cv ('Empfehlung: Kanal {0}' -f $Best) ((& $xOf $Best) - 70) 0 '#15803D' 11 'Center' 140 -Bold }
    $inv = [Globalization.CultureInfo]::InvariantCulture
    $list = @($Nets | Where-Object { $_.BandKey -eq '2.4' -and $_.Channel -ge 1 -and $_.Channel -le 14 } | Sort-Object @{ e = { $_.Ssid -eq $OwnSsid } }, Signal)
    $labelled = @{}
    $strong = @($list | Sort-Object Signal -Descending | Select-Object -First 12 | ForEach-Object { $_.Bssid })
    foreach ($n in $list) {
        $own = ($OwnSsid -and $n.Ssid -eq $OwnSsid); $col = Get-NtSsidColor $n.Ssid $own
        $x0 = & $xOf ($n.Channel - 2); $x1 = & $xOf ($n.Channel - 1); $x2 = & $xOf ($n.Channel + 1); $x3 = & $xOf ($n.Channel + 2)
        $base = $pt + $ph; $top = & $yOf ([math]::Max(3, $n.Signal)); $cy = $base - ($base - $top) / 0.75
        $p = New-Object Windows.Shapes.Path
        $p.Data = [Windows.Media.Geometry]::Parse([string]::Format($inv, 'M {0:0.0},{1:0.0} C {2:0.0},{3:0.0} {4:0.0},{3:0.0} {5:0.0},{1:0.0} Z', $x0, $base, $x1, $cy, $x2, $x3))
        $fb = Get-NtBrush $col; if ($fb.IsFrozen) { $fb = $fb.Clone() }; $fb.Opacity = $(if ($own) { 0.30 } else { 0.14 }); $p.Fill = $fb; $p.Stroke = Get-NtBrush $col; $p.StrokeThickness = $(if ($own) { 3 } else { 1.4 })
        $p.ToolTip = '{0}  ·  {1}  ·  Kanal {2}  ·  Signal {3} %  ·  {4}' -f $n.Ssid, $n.Bssid, $n.Channel, $n.Signal, $n.Auth
        [void]$cv.Children.Add($p)
        $key = '{0}|{1}' -f $n.Ssid, $n.Channel
        if (($own -or $strong -contains $n.Bssid) -and -not $labelled.ContainsKey($key)) { $labelled[$key] = $true; $null = Add-NtText $cv $n.Ssid ((& $xOf $n.Channel) - 60) ($top - 16) $col 10.5 'Center' 120 -Bold:$own }
    }
    if (-not $list.Count) { $null = Add-NtText $cv 'Keine 2,4-GHz-Netze gefunden.' $pl ($pt + $ph / 2 - 10) '#6B7890' 13 'Center' $pw }
}
function Show-NtWlan5($Nets, [string]$OwnSsid, [int]$Best, [int]$OwnCh) {
    $cv = $ui.NtWlan5; $cv.Children.Clear()
    $w = [double]$cv.ActualWidth; if ($w -lt 300) { $w = 820 }
    $h = [double]$cv.Height; $pl = 40; $pr = 12; $pt = 18; $pb = 24; $pw = $w - $pl - $pr; $ph = $h - $pt - $pb
    $list = @($Nets | Where-Object { $_.BandKey -eq '5' })
    $chs = @(@($list | ForEach-Object { [int]$_.Channel }) + @($(if ($Best) { $Best })) | Sort-Object -Unique)
    if (-not $list.Count) { $null = Add-NtText $cv 'Keine 5-GHz-Netze gefunden (oder der WLAN-Adapter kann kein 5 GHz).' $pl ($pt + $ph / 2 - 10) '#6B7890' 13 'Center' $pw; return }
    $cnt = @{}; foreach ($c in $chs) { $cnt[$c] = @($list | Where-Object { $_.Channel -eq $c }) }
    $mx = [math]::Max(2, (@($chs | ForEach-Object { $cnt[$_].Count }) | Measure-Object -Maximum).Maximum)
    foreach ($g in 1..$mx) { if ($mx -le 6 -or $g % [math]::Ceiling($mx / 5) -eq 0) { $gy = $pt + $ph * (1 - $g / $mx); Add-NtLine $cv $pl $gy ($w - $pr) $gy '#E2E7F0' 1; $null = Add-NtText $cv ([string]$g) 0 ($gy - 8) '#6B7890' 10 'Right' ($pl - 6) } }
    Add-NtLine $cv $pl ($pt + $ph) ($w - $pr) ($pt + $ph) '#C5CEDD' 1
    $slot = $pw / [math]::Max(8, $chs.Count); $bwid = [math]::Min(46, $slot * 0.62)
    for ($i = 0; $i -lt $chs.Count; $i++) {
        $c = $chs[$i]; $cx = $pl + $slot * ($i + 0.5); $chNets = @($cnt[$c]); $own = ($c -eq $OwnCh)
        $dfs = ($c -ge 52 -and $c -le 144)
        if ($chNets.Count) {
            $bh = $ph * $chNets.Count / $mx
            $r = New-Object Windows.Shapes.Rectangle; $r.Width = $bwid; $r.Height = $bh; $r.RadiusX = 4; $r.RadiusY = 4
            $r.Fill = Get-NtBrush $(if ($own) { '#2D7FF9' } else { '#EA580C' }); $r.Opacity = $(if ($own) { 0.95 } else { 0.35 + 0.6 * ((($chNets | Measure-Object Signal -Maximum).Maximum) / 100.0) })
            $r.ToolTip = "Kanal {0}{1}:`n{2}" -f $c, $(if ($dfs) { ' (DFS)' } else { '' }), (($chNets | Sort-Object Signal -Descending | ForEach-Object { '{0} ({1} %)' -f $_.Ssid, $_.Signal }) -join "`n")
            [Windows.Controls.Canvas]::SetLeft($r, $cx - $bwid / 2); [Windows.Controls.Canvas]::SetTop($r, $pt + $ph - $bh); [void]$cv.Children.Add($r)
            $null = Add-NtText $cv ([string]$chNets.Count) ($cx - 20) ($pt + $ph - $bh - 15) $(if ($own) { '#2D7FF9' } else { '#1F2A44' }) 11 'Center' 40 -Bold
        } else {
            $null = Add-NtText $cv 'frei' ($cx - 25) ($pt + $ph - 18) '#15803D' 11 'Center' 50 -Bold
        }
        $null = Add-NtText $cv ('{0}{1}' -f $c, $(if ($dfs) { '*' } else { '' })) ($cx - 25) ($pt + $ph + 4) $(if ($c -eq $Best) { '#15803D' } elseif ($own) { '#2D7FF9' } else { '#6B7890' }) 11 'Center' 50 -Bold:(($c -eq $Best) -or $own)
    }
    if ($Best) { $bi = [array]::IndexOf($chs, $Best); if ($bi -ge 0) { $null = Add-NtText $cv ('Empfehlung: Kanal {0}' -f $Best) ($pl + $slot * ($bi + 0.5) - 70) 0 '#15803D' 11 'Center' 140 -Bold } }
}
function Get-NtWifiGen([string]$Radio) {
    switch -regex ($Radio) { '11be' { 'Wi-Fi 7 (be)'; break } '11ax' { 'Wi-Fi 6/6E (ax)'; break } '11ac' { 'Wi-Fi 5 (ac)'; break } '11n' { 'Wi-Fi 4 (n)'; break } '11[abg]' { 'alt (' + ($Radio -replace '802\.', '') + ')'; break } default { $Radio } }
}
function Show-NtWlanResult {
    $x = $script:NtWlanData; if (-not $x) { return }
    $cur = $x.Current; $own = [string]$cur.Ssid
    $adv = Get-NtChannelAdvice @($x.Nets) $own
    $script:NtWlanAdv = $adv
    Show-NtWlan24 @($x.Nets) $own $adv.Best24
    Show-NtWlan5 @($x.Nets) $own $adv.Best5 $(if ([int]$cur.Channel -gt 14 -and [string]$cur.Band -notmatch '^\s*6') { [int]$cur.Channel } else { 0 })
    $rows = @($x.Nets | Sort-Object @{ e = { $_.Ssid -ne $own } }, @{ e = { $_.Signal }; Descending = $true } | ForEach-Object {
            $isOwn = ($own -and $_.Ssid -eq $own)
            $_ | Add-Member -NotePropertyName SignalText -NotePropertyValue ('{0} %' -f $_.Signal) -Force
            $_ | Add-Member -NotePropertyName RadioText -NotePropertyValue (Get-NtWifiGen $_.Radio) -Force
            $_ | Add-Member -NotePropertyName UtilText -NotePropertyValue $(if ($_.Util -ge 0) { '{0} %' -f $_.Util } else { '-' }) -Force
            $_ | Add-Member -NotePropertyName Level -NotePropertyValue $(if ($isOwn) { 'Good' } elseif ($_.Auth -match '^(Offen|Open)') { 'Warn' } else { '' }) -Force
            $_ })
    Set-GridItems $ui.NtWlanGrid $rows
    $lines = @()
    $lines += '{0} Sender von {1} Netzen in Reichweite ({2} x 2,4 GHz, {3} x 5 GHz{4}).' -f @($x.Nets).Count, @($x.Nets | ForEach-Object { $_.Ssid } | Select-Object -Unique).Count, @($x.Nets | Where-Object BandKey -eq '2.4').Count, @($x.Nets | Where-Object BandKey -eq '5').Count, $(if (@($x.Nets | Where-Object BandKey -eq '6').Count) { ', {0} x 6 GHz' -f @($x.Nets | Where-Object BandKey -eq '6').Count } else { '' })
    if ($own) {
        $ch = [int]$cur.Channel
        if ($ch -ge 1 -and $ch -le 14) {
            $diff = [double]$adv.Load24[[math]::Min(13, $ch)] - [double]$adv.Load24[$adv.Best24]
            $lines += 'Verbunden mit "{0}" auf Kanal {1} (2,4 GHz, Signal {2}). {3}' -f $own, $ch, $cur.Signal, $(if ($ch -notin 1, 6, 11) { 'Kanal {0} überlappt mit zwei Nachbarkanälen - besser einen der Kanäle 1, 6 oder 11 nehmen: Empfehlung Kanal {1}.' -f $ch, $adv.Best24 } elseif ($ch -eq $adv.Best24 -or $diff -lt 0.3) { 'Der Kanal passt - kaum weniger belegte Alternative in der Nähe.' } else { 'Kanal {0} ist deutlich freier - im Router umstellen bringt spürbar mehr Tempo und weniger Abbrüche.' -f $adv.Best24 })
            $lines += 'Tipp: Wenn Router und Gerät es können, 5 GHz nutzen - viel mehr freie Kanäle und höhere Geschwindigkeit (Reichweite etwas geringer).'
        } elseif ([string]$cur.Band -match '^\s*6') {
            $lines += 'Verbunden mit "{0}" im 6-GHz-Band (Kanal {1}, Signal {2}) - Wi-Fi 6E/7, praktisch störungsfrei.' -f $own, $ch, $cur.Signal
        } elseif ($ch -gt 14) {
            $myBlock = @($adv.Load5.Keys | Where-Object { $k = $_; (@{ '36-48' = 36..48; '52-64 (DFS)' = 52..64; '100-112 (DFS)' = 100..112; '116-128 (DFS)' = 116..128; '132-140 (DFS)' = 132..144 })[$k] -contains $ch })[0]
            $lines += 'Verbunden mit "{0}" auf Kanal {1} (5 GHz, Signal {2}) - sehr gut. {3}' -f $own, $ch, $cur.Signal, $(if ($myBlock -and $myBlock -ne $adv.Best5Block -and ([double]$adv.Load5[$myBlock] - [double]$adv.Load5[$adv.Best5Block]) -gt 0.5) { 'Am wenigsten belegt ist der Bereich {0} (z.B. Kanal {1}).' -f $adv.Best5Block, $adv.Best5 } else { 'Der Kanalbereich ist nicht überfüllt.' })
        }
    } else { $lines += 'Dieser PC ist gerade nicht per WLAN verbunden - die Empfehlung gilt für den Router in der Nähe dieses PCs.' }
    $lines += 'Empfehlung 2,4 GHz: Kanal {0} (nur 1, 6 und 11 überlappen sich nicht).  ·  5 GHz: Kanal {1} (Bereich {2}).{3}' -f $adv.Best24, $adv.Best5, $adv.Best5Block, $(if ($adv.Best5Block -match 'DFS') { ' DFS-Kanäle sind oft frei, der Router muss dort aber auf Wetterradar achten und wechselt dann kurz den Kanal.' } else { '' })
    $lines += 'Bei FRITZ!Box, Mesh-Systemen und den meisten Routern ist "Automatisch" meist die beste Einstellung - die Empfehlung hilft, wenn der Router trotzdem einen vollen Kanal wählt.'
    $ui.NtWlanAdvice.Text = $lines -join "`n"; $ui.NtWlanAdviceBox.Visibility = 'Visible'
}
$ui.BtnNtWlanScan.Add_Click({
    $ui.BtnNtWlanScan.IsEnabled = $false; $ui.BtnNtWlanLoc.Visibility = 'Collapsed'
    $null = Start-NtProgress $ui.NtWlanProg $ui.NtWlanState 'Lese WLAN-Sender (netsh wlan) ...' -Indeterminate
    Invoke-Bg -Script { Get-NtWlanScan } -Functions @('Get-NtWlanScan', 'ConvertFrom-NtWlanText', 'Get-NtWlanCurrent', 'Format-NtMac') -Done {
        param($r, $err)
        $ui.BtnNtWlanScan.IsEnabled = $true
        $x = @($r | Where-Object { $_ -and $_.PSObject.Properties['Nets'] })[0]
        if ($err -or -not $x) { Stop-NtProgress $ui.NtWlanProg $ui.NtWlanState ('WLAN-Abfrage fehlgeschlagen: ' + $(if ($err) { $err.Message } else { 'kein Ergebnis' })); return }
        if ($x.NeedLocation) { $ui.BtnNtWlanLoc.Visibility = 'Visible'; Stop-NtProgress $ui.NtWlanProg $ui.NtWlanState 'Windows verweigert die WLAN-Liste, weil die Standortberechtigung fehlt (ab Windows 11 24H2). Bitte "Standortdienste öffnen" > Position einschalten und "Desktop-Apps den Zugriff auf Ihre Position erlauben" aktivieren, dann erneut scannen.'; return }
        if (-not @($x.Nets).Count) { Stop-NtProgress $ui.NtWlanProg $ui.NtWlanState ('Keine WLANs gefunden. WLAN eingeschaltet und ein WLAN-Adapter vorhanden? {0}' -f $x.Raw); return }
        $script:NtWlanData = $x
        try { Show-NtWlanResult } catch { $ui.NtWlanState.Text = 'Darstellung fehlgeschlagen: ' + $_.Exception.Message }
        Stop-NtProgress $ui.NtWlanProg $ui.NtWlanState ('Gescannt am {0:dd.MM.yyyy HH:mm}. Maus über eine Kurve zeigt Details.' -f (Get-Date))
    }
})
$ui.BtnNtWlanLoc.Add_Click({ Start-Process 'ms-settings:privacy-location' })
foreach ($ntCv in @($ui.NtWlan24, $ui.NtWlan5)) { $ntCv.Add_SizeChanged({ param($s, $e) if ($script:NtWlanData -and [math]::Abs($e.NewSize.Width - $e.PreviousSize.Width) -gt 2) { try { Show-NtWlanResult } catch { } } }) }

# ---- Router-Check
function Show-NtRouterList($Rows) {
    $ui.NtRtList.Children.Clear()
    $map = @{ Good = @('&#xE73E;', '#16A34A', 'OK', '#DCFCE7', '#15803D'); Warn = @('&#xE7BA;', '#EA580C', 'Prüfen', '#FFEDD5', '#B45309'); Bad = @('&#xE711;', '#DC2626', 'Problem', '#FEE2E2', '#C81E1E'); Info = @('&#xE946;', '#2D7FF9', 'Info', '#E6F0FF', '#2D7FF9') }
    foreach ($row in @($Rows)) {
        $m = $map[[string]$row.Level]; if (-not $m) { $m = $map.Info }
        $glyph = [Net.WebUtility]::HtmlDecode($m[0])
        $b = New-Object Windows.Controls.Border; $b.CornerRadius = '10'; $b.Padding = '12,10'; $b.Margin = '0,0,0,8'; $b.BorderThickness = '1'; $b.BorderBrush = New-UiBrush '#E2E7F0'; $b.Background = New-UiBrush '#F8FAFD'
        $g = New-Object Windows.Controls.Grid
        foreach ($cw in 'Auto', '*', 'Auto') { $cd = New-Object Windows.Controls.ColumnDefinition; $cd.Width = $cw; [void]$g.ColumnDefinitions.Add($cd) }
        $ic = New-Object Windows.Controls.Border; $ic.Width = 30; $ic.Height = 30; $ic.CornerRadius = '15'; $ic.Background = Get-NtBrush $m[1]; $ic.Margin = '0,0,12,0'; $ic.VerticalAlignment = 'Top'
        $it = New-Object Windows.Controls.TextBlock; $it.Text = $glyph; $it.FontFamily = 'Segoe MDL2 Assets'; $it.FontSize = 14; $it.Foreground = Get-NtBrush '#FFFFFF'; $it.HorizontalAlignment = 'Center'; $it.VerticalAlignment = 'Center'; $ic.Child = $it
        $sp = New-Object Windows.Controls.StackPanel; [Windows.Controls.Grid]::SetColumn($sp, 1)
        $t1 = New-Object Windows.Controls.TextBlock; $t1.Text = [string]$row.Title; $t1.FontWeight = 'SemiBold'; $t1.Foreground = New-UiBrush '#1F2A44'; $t1.TextWrapping = 'Wrap'
        $t2 = New-Object Windows.Controls.TextBlock; $t2.Text = [string]$row.Detail; $t2.FontSize = 12; $t2.Foreground = New-UiBrush '#6B7890'; $t2.TextWrapping = 'Wrap'; $t2.Margin = '0,2,0,0'
        [void]$sp.Children.Add($t1); [void]$sp.Children.Add($t2)
        $pill = New-Object Windows.Controls.Border; $pill.CornerRadius = '10'; $pill.Padding = '10,2'; $pill.Margin = '12,0,0,0'; $pill.VerticalAlignment = 'Top'; $pill.Background = New-UiBrush $m[3]; [Windows.Controls.Grid]::SetColumn($pill, 2)
        $pt = New-Object Windows.Controls.TextBlock; $pt.Text = $m[2]; $pt.FontSize = 11; $pt.FontWeight = 'SemiBold'; $pt.Foreground = New-UiBrush $m[4]; $pill.Child = $pt
        [void]$g.Children.Add($ic); [void]$g.Children.Add($sp); [void]$g.Children.Add($pill); $b.Child = $g
        [void]$ui.NtRtList.Children.Add($b)
    }
}
$ui.BtnNtRtRun.Add_Click({
    $ui.BtnNtRtRun.IsEnabled = $false; $ui.NtRtList.Children.Clear(); $ui.NtRtTitle.Text = ''
    $sync = Start-NtProgress $ui.NtRtProg $ui.NtRtState 'Starte ...'
    Invoke-Bg -Script { param($code, $sy) Get-NtRouterData $code $sy } -Arguments @($NtTlsCode, $sync) -Functions (@('Get-NtRouterData', 'Get-NtHttpInfo', 'ConvertFrom-NtBoxInfo', 'Get-UpnpInfo') + $script:NtNetFns) -Done {
        param($r, $err)
        $ui.BtnNtRtRun.IsEnabled = $true
        $x = @($r | Where-Object { $_ -and $_.PSObject.Properties['Box'] })[0]
        if ($err -or -not $x) { Stop-NtProgress $ui.NtRtProg $ui.NtRtState ('Prüfung fehlgeschlagen: ' + $(if ($err) { $err.Message } else { 'kein Ergebnis' })); return }
        $script:NtRtData = $x
        try {
            $rows = Get-NtRouterChecklist $x $NtOui
            Show-NtRouterList $rows
            $vend = if ($x.GwMac) { Get-NtVendor $x.GwMac $NtOui } else { '' }
            $ui.NtRtTitle.Text = if ($x.Box) { '{0} (FRITZ!OS {1}) unter {2}' -f $x.Box.Name, $x.Box.Os, $x.Net.Gateway } elseif ($x.Net -and $x.Net.Gateway) { 'Router {0}{1}{2}' -f $x.Net.Gateway, $(if ($vend) { ' · ' + $vend } else { '' }), $(if ($x.Upnp -and $x.Upnp.Router) { ' · ' + $x.Upnp.Router } elseif ($x.Http -and $x.Http.Title) { ' · "' + $x.Http.Title + '"' } else { '' }) } else { 'Kein Router gefunden' }
            Set-GridItems $ui.NtRtUpnpGrid @($(if ($x.Upnp) { @($x.Upnp.Maps) }))
            $cG = @($rows | Where-Object Level -eq 'Good').Count; $cW = @($rows | Where-Object Level -eq 'Warn').Count; $cB = @($rows | Where-Object Level -eq 'Bad').Count
            Stop-NtProgress $ui.NtRtProg $ui.NtRtState ('Geprüft am {0:dd.MM.yyyy HH:mm}: {1} in Ordnung, {2} prüfen, {3} Problem(e).' -f (Get-Date), $cG, $cW, $cB)
        } catch { Stop-NtProgress $ui.NtRtProg $ui.NtRtState ('Auswertung fehlgeschlagen: ' + $_.Exception.Message) }
    }
})
$ui.BtnNtRtWeb.Add_Click({
    $x = $script:NtRtData; $gw = if ($x -and $x.Net) { [string]$x.Net.Gateway } else { $n = $null; try { $n = Get-NtActiveNet } catch { }; if ($n) { [string]$n.Gateway } else { '' } }
    if (-not $gw) { Show-UiError 'Kein Router gefunden.'; return }
    $https = $x -and (($x.Https -and $x.Https.Code -ge 200 -and $x.Https.Code -lt 500) -or ($x.Tls -and $x.Tls.State -eq 'ok'))
    Start-Process $(if ($x -and $x.Box) { 'http://fritz.box/' } elseif ($https) { "https://$gw/" } else { "http://$gw/" })
})

# ---- Sprungleiste und Laden der Seite (Sprung erst nach dem Seitenaufbau, deshalb kurz verzögert)
$script:NtJumpTimer = New-Object Windows.Threading.DispatcherTimer
$script:NtJumpTimer.Interval = [TimeSpan]::FromMilliseconds(150)
$script:NtJumpTimer.Add_Tick({ $script:NtJumpTimer.Stop(); try { $t = $ui[[string]$script:NtJumpTo]; if ($t) { $t.BringIntoView() } } catch { } })
function Show-NtSection([string]$Name) { $ui.Tabs.SelectedItem = $ui.TabNetTools; $script:NtJumpTo = $Name; $script:NtJumpTimer.Stop(); $script:NtJumpTimer.Start() }
foreach ($ntJ in @(@('NtJDev', 'NtSecDev'), @('NtJWol', 'NtSecWol'), @('NtJSpeed', 'NtSecSpeed'), @('NtJDns', 'NtSecDns'), @('NtJWlan', 'NtSecWlan'), @('NtJRouter', 'NtSecRouter'))) {
    $ui[$ntJ[0]].Tag = $ntJ[1]
    $ui[$ntJ[0]].Add_Click({ param($s, $e) Show-NtSection ([string]$s.Tag) })
}
$ui.Tabs.Add_SelectionChanged({
    param($s, $e)
    if ($e.OriginalSource -ne $s -or $s.SelectedItem -ne $ui.TabNetTools) { return }
    if (-not $script:NtLoaded) { $script:NtLoaded = $true; try { Show-NtDevStoreInfo; Update-NtWolGrid } catch { $ui.StatusText.Text = 'Netzwerk-Werkzeuge: ' + $_.Exception.Message } }
    try { Update-NtSpeed } catch { $ui.NtSpInfo.Text = 'Verlauf nicht lesbar: ' + $_.Exception.Message }
})

# ---------------------------------------------------------------- Geräte-Akte (Oberfläche)
$script:AkFile = Join-Path $DataDir 'geraeteakte.json'
$script:AkDirBase = Join-Path $DataDir 'Akte\Dateien'
$script:AkHistDefs = @(@('AkkuProzent', '%', '#16A34A'), @('SsdVerschleiss', '%', '#EA580C'), @('SsdTemperatur', '°C', '#DC2626'), @('FreiGB', 'GB', '#2D7FF9'), @('StartSek', 's', '#7C3AED'))
function Get-AkFileDir { $d = Join-Path $script:AkDirBase ($env:COMPUTERNAME -replace '[\\/:*?"<>|]', '_'); if (-not (Test-Path -LiteralPath $d)) { New-Item -Path $d -ItemType Directory -Force | Out-Null }; return $d }
# Datensatz ändern: Akte frisch lesen, $Change mit dem Datensatz aufrufen, speichern (so gehen parallele Änderungen nicht verloren)
function Edit-AkRecord([scriptblock]$Change) {
    $akEdStore = Read-AkStore $script:AkFile
    $akEdRec = Get-AkRecord $akEdStore $env:COMPUTERNAME $script:AkSerial -Create
    & $Change $akEdRec
    $akEdRec.Updated = (Get-Date).ToString('o')
    Save-AkStore $script:AkFile $akEdStore
    $script:AkRec = $akEdRec
    return $akEdRec
}
function New-AkBadge([string]$Glyph, [string]$Text, [string]$Dot) {
    $b = New-Object Windows.Controls.Border; $b.CornerRadius = '14'; $b.Padding = '10,5,12,5'; $b.Margin = '0,0,8,8'; $b.Background = Get-NtBrush '#2EFFFFFF'; $b.BorderBrush = Get-NtBrush '#40FFFFFF'; $b.BorderThickness = '1'
    $sp = New-Object Windows.Controls.StackPanel; $sp.Orientation = 'Horizontal'
    $e = New-Object Windows.Shapes.Ellipse; $e.Width = 9; $e.Height = 9; $e.Fill = Get-NtBrush $Dot; $e.Margin = '0,0,8,0'; $e.VerticalAlignment = 'Center'
    $g = New-Object Windows.Controls.TextBlock; $g.Text = [Net.WebUtility]::HtmlDecode($Glyph); $g.FontFamily = 'Segoe MDL2 Assets'; $g.FontSize = 13; $g.Foreground = Get-NtBrush '#FFFFFF'; $g.Margin = '0,0,7,0'; $g.VerticalAlignment = 'Center'
    $t = New-Object Windows.Controls.TextBlock; $t.Text = $Text; $t.Foreground = Get-NtBrush '#FFFFFF'; $t.FontWeight = 'SemiBold'; $t.VerticalAlignment = 'Center'
    [void]$sp.Children.Add($e); [void]$sp.Children.Add($g); [void]$sp.Children.Add($t); $b.Child = $sp
    return $b
}
function Get-AkWarrantyEnd {
    $w = $null; try { $w = Get-WarrantyInfo } catch { }
    $end = $null; if ($w -and $w.End) { $end = ConvertTo-AkDate ([string]$w.End); if (-not $end) { try { $end = [datetime]$w.End } catch { } } }
    return [pscustomobject]@{ Info = $w; End = $end }
}
function Show-AkBadges {
    $ui.AkBadges.Children.Clear()
    $a = $script:AkAuto; $rec = $script:AkRec
    $war = $script:AkWarranty
    if ($war -and $war.End) { $dd = ($war.End - (Get-Date)).TotalDays; [void]$ui.AkBadges.Children.Add((New-AkBadge '&#xE83D;' $(if ($dd -lt 0) { 'Garantie abgelaufen ({0:dd.MM.yyyy})' -f $war.End } else { 'Garantie bis {0:dd.MM.yyyy}' -f $war.End }) $(if ($dd -lt 0) { '#F87171' } elseif ($dd -lt 60) { '#FBBF24' } else { '#4ADE80' }))) }
    else { [void]$ui.AkBadges.Children.Add((New-AkBadge '&#xE83D;' 'Garantie unbekannt' '#CBD5E1')) }
    $kd = if ($rec) { ConvertTo-AkDate $rec.Manual.Kaufdatum } else { $null }
    if ($kd) { $yrs = ((Get-Date) - $kd).TotalDays / 365.25; [void]$ui.AkBadges.Children.Add((New-AkBadge '&#xE787;' ('Alter: ' + (Get-AkAge $kd)) $(if ($yrs -ge 6) { '#F87171' } elseif ($yrs -ge 4) { '#FBBF24' } else { '#4ADE80' }))) }
    else { [void]$ui.AkBadges.Children.Add((New-AkBadge '&#xE787;' 'Alter: Kaufdatum eintragen' '#CBD5E1')) }
    if ($a -and [int]$a.AkkuProzent -ge 0) { $bp = [int]$a.AkkuProzent; [void]$ui.AkBadges.Children.Add((New-AkBadge '&#xE83F;' ('Akku {0} %' -f $bp) $(if ($bp -lt 60) { '#F87171' } elseif ($bp -lt 80) { '#FBBF24' } else { '#4ADE80' }))) }
    elseif ($a) { [void]$ui.AkBadges.Children.Add((New-AkBadge '&#xE83F;' 'kein Akku' '#CBD5E1')) }
    $hi = @($script:AkHealth)
    if ($hi.Count) { $red = @($hi | Where-Object Level -eq 'Red').Count; $yel = @($hi | Where-Object Level -eq 'Yellow').Count
        [void]$ui.AkBadges.Children.Add((New-AkBadge '&#xE9D9;' $(if ($red) { 'Zustand: {0} dringend' -f $red } elseif ($yel) { 'Zustand: {0} Hinweis(e)' -f $yel } else { 'Zustand: gut' }) $(if ($red) { '#F87171' } elseif ($yel) { '#FBBF24' } else { '#4ADE80' }))) }
    elseif ($a) { [void]$ui.AkBadges.Children.Add((New-AkBadge '&#xE9D9;' 'Zustand: gut' '#4ADE80')) }
}
function Show-AkRecord {
    $a = $script:AkAuto; $rec = $script:AkRec
    if ($a) {
        $ui.AkGlyph.Text = [Net.WebUtility]::HtmlDecode($(switch ($a.Bauform) { 'Notebook' { '&#xE7F8;' } 'Tablet' { '&#xE70A;' } default { '&#xE977;' } }))
        $ui.AkHeroVendor.Text = '{0}{1}' -f $a.Hersteller, $(if ($a.Typnummer) { '  ·  ' + $a.Typnummer } else { '' })
        $ui.AkHeroModel.Text = $(if ($a.Modell) { $a.Modell } else { 'Unbekanntes Modell' })
        $ui.AkHeroSerial.Text = 'Seriennummer {0}  ·  Computername {1}  ·  {2}' -f $(if ($a.Seriennummer) { $a.Seriennummer } else { 'nicht hinterlegt' }), $a.Computer, $a.Bauform
        $map = [ordered]@{ AkHwMaker = $a.Hersteller; AkHwModel = $a.Modell; AkHwSku = $a.Typnummer; AkHwSerial = $a.Seriennummer; AkHwForm = $a.Bauform; AkHwBios = $a.Bios; AkHwFw = $a.Firmware; AkHwCpu = $a.Prozessor
            AkHwRam = ([string]$a.Arbeitsspeicher + $(if (@($a.RamModule).Count) { "`n" + (@($a.RamModule) -join "`n") } else { '' })); AkHwDisk = (@($a.Datentraeger) -join "`n"); AkHwGpu = (@($a.Grafik) -join "`n"); AkHwWin = $a.Windows
            AkHwInst = $(if ($a.Installiert) { try { ([datetime]$a.Installiert).ToString('dd.MM.yyyy') + ' (vor ' + (Get-AkAge ([datetime]$a.Installiert)) + ')' } catch { $a.Installiert } } else { '' }); AkHwAct = $a.Aktivierung; AkHwMac = (@($a.Netzwerk) -join "`n"); AkHwBat = $(if ($a.Akku) { $a.Akku } else { 'kein Akku verbaut' }) }
        foreach ($k in $map.Keys) { $ui[$k].Text = $(if ([string]$map[$k]) { [string]$map[$k] } else { '-' }) }
        $ui.AkHwAct.Foreground = New-UiBrush $(if ([string]$a.Aktivierung -like 'aktiviert*') { '#15803D' } elseif ($a.Aktivierung) { '#C81E1E' } else { '#1F2A44' })
    }
    $war = $script:AkWarranty
    $ui.AkHwWar.Text = if ($war -and $war.End) { 'bis {0:dd.MM.yyyy} ({1}){2}' -f $war.End, $(if ($war.End -lt (Get-Date)) { 'abgelaufen' } else { 'noch ' + (Get-AkAge (Get-Date) $war.End) }), $(if ($war.Info -and $war.Info.Source) { ' - Quelle: ' + $war.Info.Source } else { '' }) } else { 'unbekannt - unter "Garantie prüfen ..." abfragen oder eintragen' }
    if ($rec) {
        $m = $rec.Manual
        $kd = ConvertTo-AkDate $m.Kaufdatum
        $ui.AkBuyDate.SelectedDate = $(if ($kd) { $kd } else { $null })
        $ui.AkPrice.Text = [string]$m.Preis; $ui.AkShop.Text = [string]$m.Haendler; $ui.AkInvoice.Text = [string]$m.Rechnungsnummer; $ui.AkInvNo.Text = [string]$m.Inventarnummer
        $ui.AkLocation.Text = [string]$m.Standort; $ui.AkOwner.Text = [string]$m.Besitzer; $ui.AkNotes.Text = [string]$m.Notizen
        $ui.AkAgeText.Text = if ($kd) { 'Gerät ist {0} alt.{1}' -f (Get-AkAge $kd), $(if (((Get-Date) - $kd).TotalDays -lt 730) { ' Gesetzliche Gewährleistung (2 Jahre ab Kauf) läuft noch bis {0:dd.MM.yyyy}.' -f $kd.AddYears(2) } else { '' }) } else { '' }
        $ui.AkSaveInfo.Text = if ($rec.Updated) { try { 'Zuletzt gespeichert am {0:dd.MM.yyyy HH:mm}' -f [datetime]$rec.Updated } catch { '' } } else { 'Noch nicht gespeichert.' }
        Show-AkLog; Show-AkFiles
    }
    Show-AkBadges
}
function Show-AkLog {
    $rec = $script:AkRec; $sum = 0.0
    $rows = @(@($rec.Log) | ForEach-Object {
            $dt = ConvertTo-AkDate $_.Datum; $c = ConvertTo-AkMoney $_.Kosten; if ($null -ne $c) { $sum += $c }
            [pscustomobject]@{ Id = $_.Id; SortDate = $(if ($dt) { $dt.ToString('yyyy-MM-dd') } else { [string]$_.Datum }); DateText = $(if ($dt) { $dt.ToString('dd.MM.yyyy') } else { [string]$_.Datum }); Art = [string]$_.Art; Text = (([string]$_.Text) -replace "`r?`n", ' / '); CostNum = $(if ($null -ne $c) { $c } else { 0.0 }); CostText = $(if ($null -ne $c) { Format-AkMoney $c } else { '' }); Level = $(if ($_.Art -in 'Reparatur', 'Garantiefall', 'Akkutausch') { 'Warn' } else { '' }); Src = $_ }
        } | Sort-Object SortDate -Descending)
    Set-GridItems $ui.AkLogGrid $rows
    $lr = Get-AkLastRepair $rec
    $ui.AkLogSum.Text = if ($rows.Count) { '{0} Einträge  ·  Kosten gesamt {1}{2}' -f $rows.Count, (Format-AkMoney $sum), $(if ($lr) { '  ·  letzte Reparatur: ' + $lr } else { '' }) } else { 'Noch keine Einträge.' }
}
function Show-AkFiles {
    $rec = $script:AkRec
    $rows = @(@($rec.Files) | ForEach-Object {
            $full = Join-Path $DataDir ([string]$_.File)
            [pscustomobject]@{ Id = $_.Id; Name = [string]$_.Name; Art = [string]$_.Art; Size = [double]$_.Size; SizeText = $(if ([double]$_.Size -ge 1MB) { '{0:N1} MB' -f ([double]$_.Size / 1MB) } else { '{0:N0} KB' -f ([double]$_.Size / 1KB) }); Added = [string]$_.Added; AddedText = $(try { ([datetime]$_.Added).ToString('dd.MM.yyyy') } catch { '' }); Full = $full; Level = $(if (-not (Test-Path -LiteralPath $full)) { 'Error' } else { '' }) }
        } | Sort-Object Added -Descending)
    Set-GridItems $ui.AkFileGrid $rows
    $miss = @($rows | Where-Object Level -eq 'Error').Count
    $ui.AkFileInfo.Text = '{0} Datei(en), {1:N1} MB, abgelegt in {2}{3}' -f $rows.Count, ((@($rows) | Measure-Object Size -Sum).Sum / 1MB), (Get-AkFileDir), $(if ($miss) { ('  ·  {0} Datei(en) fehlen im Ordner (rot)' -f $miss) } else { '' })
}
function Update-AkHist {
    $f = Join-Path $DataDir 'Verlauf.csv'
    $rows = @(); try { if (Test-Path -LiteralPath $f) { $rows = @(Import-Csv -LiteralPath $f -Delimiter ';' -Encoding UTF8) } } catch { }
    $script:AkHist = $rows
    $i = [math]::Max(0, $ui.AkHistSel.SelectedIndex); $def = $script:AkHistDefs[$i]
    $inv = [Globalization.CultureInfo]::InvariantCulture
    $vals = [double[]]@($rows | ForEach-Object { $v = 0.0; if ([double]::TryParse(([string]$_.($def[0])).Replace(',', '.'), [Globalization.NumberStyles]::Float, $inv, [ref]$v)) { $v } else { [double]::NaN } })
    $lab = [string[]]@($rows | ForEach-Object { try { ([datetime]::ParseExact([string]$_.Datum, 'yyyy-MM-dd', $inv)).ToString('dd.MM.yy') } catch { [string]$_.Datum } })
    Show-NtLineChart $ui.AkHistCanvas @(@{ Name = [string]$ui.AkHistSel.SelectedItem.Content; Color = $def[2]; Values = $vals }) $lab $def[1]
    $ok = @($vals | Where-Object { -not [double]::IsNaN($_) })
    $ui.AkHistInfo.Text = if ($rows.Count -lt 2) { 'Es gibt erst {0} Messpunkt(e) - PC-Tools speichert einmal täglich einen Wert.' -f $rows.Count } elseif (-not $ok.Count) { 'Für diesen Wert liegen keine Messungen vor (z.B. kein Akku oder die SSD meldet ihn nicht).' } else { '{0} Messpunkte vom {1} bis {2}, aktuell {3:N1} {4}.' -f $rows.Count, $lab[0], $lab[-1], $ok[-1], $def[1] }
}
function Update-AkPage {
    $ui.AkProg.Visibility = 'Visible'; $ui.BtnAkRefresh.IsEnabled = $false
    try { $script:AkWarranty = Get-AkWarrantyEnd } catch { }
    $ha = $null; try { $ha = Get-HealthArgs } catch { }
    Invoke-Bg -Script { param($h) $a = Get-AkAutoData; $items = @(); if ($h) { try { $items = @(Get-HealthItems $h | ForEach-Object { $_ } | Where-Object { $_ -and $_.Text }) } catch { } }; [pscustomobject]@{ Auto = $a; Health = $items } } -Arguments @(, $ha) -Functions @('Get-AkAutoData', 'Get-HealthItems') -Done {
        param($r, $err)
        $ui.AkProg.Visibility = 'Collapsed'; $ui.BtnAkRefresh.IsEnabled = $true
        $x = @($r | Where-Object { $_ -and $_.PSObject.Properties['Auto'] })[0]
        if ($err -or -not $x) { $ui.AkHeroModel.Text = 'Einlesen fehlgeschlagen'; $ui.AkHeroSerial.Text = $(if ($err) { $err.Message } else { 'kein Ergebnis' }); return }
        $script:AkAuto = $x.Auto; $script:AkHealth = @($x.Health); $script:AkSerial = [string]$x.Auto.Seriennummer
        try { $null = Edit-AkRecord { param($R) $R.Auto = $script:AkAuto } } catch { Show-UiError $_.Exception.Message }
        try { Show-AkRecord } catch { $ui.StatusText.Text = 'Geräte-Akte: ' + $_.Exception.Message }
        try { Update-AkHist } catch { }
    }
}
