    if ($ui.AkPrice.Text.Trim() -and $null -eq $pr) { Show-UiError 'Der Preis ist keine Zahl (Beispiel: 1.299,00).'; return }
    try {
        $null = Edit-AkRecord { param($R)
            $R.Manual.Kaufdatum = $(if ($ui.AkBuyDate.SelectedDate) { ([datetime]$ui.AkBuyDate.SelectedDate).ToString('yyyy-MM-dd') } else { '' })
            $R.Manual.Preis = $(if ($null -ne $pr) { (Format-AkMoney $pr) } else { '' })
            $R.Manual.Haendler = $ui.AkShop.Text.Trim(); $R.Manual.Rechnungsnummer = $ui.AkInvoice.Text.Trim(); $R.Manual.Inventarnummer = $ui.AkInvNo.Text.Trim()
            $R.Manual.Standort = $ui.AkLocation.Text.Trim(); $R.Manual.Besitzer = $ui.AkOwner.Text.Trim(); $R.Manual.Notizen = $ui.AkNotes.Text.Trim() }
        Show-AkRecord
        $ui.StatusText.Text = 'Geräte-Akte gespeichert.'
    } catch { Show-UiError ('Speichern fehlgeschlagen: ' + $_.Exception.Message) }
})
function Edit-AkLogEntry($Src) {
    $types = @($AkLogTypes); if ($Src -and $Src.Art) { $types = @([string]$Src.Art) + @($types | Where-Object { $_ -ne [string]$Src.Art }) }
    $dt0 = if ($Src) { $d = ConvertTo-AkDate $Src.Datum; if ($d) { $d.ToString('dd.MM.yyyy') } else { [string]$Src.Datum } } else { (Get-Date).ToString('dd.MM.yyyy') }
    $res = Show-InputDialog $(if ($Src) { 'Eintrag bearbeiten' } else { 'Wartung / Reparatur eintragen' }) 'Was wurde am Gerät gemacht? Kosten sind optional (in Euro).' @(
        @{ Key = 'Datum'; Label = 'Datum (TT.MM.JJJJ)'; Type = 'Text'; Value = $dt0 }, @{ Key = 'Art'; Label = 'Art'; Type = 'Combo'; Items = $types },
        @{ Key = 'Text'; Label = 'Beschreibung (z.B. "Akku getauscht, Originalteil, Werkstatt Müller")'; Type = 'Text'; Value = $(if ($Src) { [string]$Src.Text } else { '' }) },
        @{ Key = 'Kosten'; Label = 'Kosten (optional, z.B. 89,90)'; Type = 'Text'; Value = $(if ($Src) { [string]$Src.Kosten } else { '' }) })
    if (-not $res) { return }
    $dt = ConvertTo-AkDate $res.Datum; if (-not $dt) { Show-UiError ('"{0}" ist kein gültiges Datum (Beispiel: 15.03.2026).' -f $res.Datum); return }
    if (-not $res.Text) { Show-UiError 'Bitte eine Beschreibung eingeben.'; return }
    $c = ConvertTo-AkMoney $res.Kosten; if ($res.Kosten -and $null -eq $c) { Show-UiError 'Die Kosten sind keine Zahl (Beispiel: 89,90).'; return }
    $script:AkLogNew = [pscustomobject]@{ Id = $(if ($Src) { [string]$Src.Id } else { [guid]::NewGuid().ToString('N') }); Datum = $dt.ToString('yyyy-MM-dd'); Art = [string]$res.Art; Text = [string]$res.Text; Kosten = $(if ($null -ne $c) { $c.ToString('0.00', [Globalization.CultureInfo]::InvariantCulture) } else { '' }) }
    try {
        $null = Edit-AkRecord { param($R) $R.Log = @(@($R.Log | Where-Object { [string]$_.Id -ne $script:AkLogNew.Id }) + $script:AkLogNew) }
        Show-AkLog; Show-AkBadges
    } catch { Show-UiError ('Speichern fehlgeschlagen: ' + $_.Exception.Message) }
}
$ui.BtnAkLogAdd.Add_Click({ if (-not $script:AkAuto) { Show-UiError 'Die Akte wird noch eingelesen.'; return }; Edit-AkLogEntry $null })
$ui.BtnAkLogEdit.Add_Click({ $r = $ui.AkLogGrid.SelectedItem; if (-not $r) { Show-UiError 'Bitte einen Eintrag auswählen.'; return }; Edit-AkLogEntry $r.Src })
$ui.AkLogGrid.Add_MouseDoubleClick({ $r = $ui.AkLogGrid.SelectedItem; if ($r) { Edit-AkLogEntry $r.Src } })
$ui.BtnAkLogDel.Add_Click({
    $r = $ui.AkLogGrid.SelectedItem; if (-not $r) { Show-UiError 'Bitte einen Eintrag auswählen.'; return }
    if (-not (Confirm-Ui ('Eintrag vom {0} ({1}: {2}) löschen?' -f $r.DateText, $r.Art, $r.Text))) { return }
    $script:AkDelId = [string]$r.Id
    try { $null = Edit-AkRecord { param($R) $R.Log = @($R.Log | Where-Object { [string]$_.Id -ne $script:AkDelId }) }; Show-AkLog } catch { Show-UiError $_.Exception.Message }
