$ui.BtnAkFileAdd.Add_Click({
    if (-not $script:AkAuto) { Show-UiError 'Die Akte wird noch eingelesen.'; return }
    $dlg = New-Object Microsoft.Win32.OpenFileDialog; $dlg.Multiselect = $true; $dlg.Title = 'Rechnungen, Fotos oder Belege zur Geräte-Akte hinzufügen'
    $dlg.Filter = 'Belege und Fotos|*.pdf;*.jpg;*.jpeg;*.png;*.heic;*.webp;*.tif;*.tiff;*.bmp;*.gif;*.doc;*.docx;*.odt;*.xlsx;*.txt;*.eml;*.msg;*.zip|Alle Dateien|*.*'
    if (-not $dlg.ShowDialog()) { return }
    $res = Show-InputDialog 'Art der Datei' ('{0} Datei(en) werden in den PC-Tools-Datenordner kopiert (die Originale bleiben, wo sie sind).' -f $dlg.FileNames.Count) @(@{ Key = 'Art'; Label = 'Art'; Type = 'Combo'; Items = @('Rechnung', 'Foto', 'Garantiebeleg', 'Reparaturbericht', 'Handbuch / Datenblatt', 'Lizenz', 'Sonstiges') })
    if (-not $res) { return }
    $dir = Get-AkFileDir; $added = [System.Collections.Generic.List[object]]::new(); $errs = @()
    foreach ($src in $dlg.FileNames) {
        try {
            $fi = Get-Item -LiteralPath $src
            if ($fi.Length -gt 100MB -and -not (Confirm-Ui ('{0} ist {1:N0} MB groß. Trotzdem kopieren?' -f $fi.Name, ($fi.Length / 1MB)))) { continue }
            $base = [IO.Path]::GetFileNameWithoutExtension($fi.Name); $ext = $fi.Extension; $target = Join-Path $dir $fi.Name; $n = 2
            while (Test-Path -LiteralPath $target) { $target = Join-Path $dir ('{0} ({1}){2}' -f $base, $n, $ext); $n++ }
            Copy-Item -LiteralPath $fi.FullName -Destination $target -ErrorAction Stop
            $rel = $target.Substring($DataDir.TrimEnd('\').Length).TrimStart('\')
            $added.Add([pscustomobject]@{ Id = [guid]::NewGuid().ToString('N'); Name = [IO.Path]::GetFileName($target); File = $rel; Art = [string]$res.Art; Added = (Get-Date).ToString('o'); Size = [double]$fi.Length })
        } catch { $errs += ('{0}: {1}' -f $src, $_.Exception.Message) }
    }
    $script:AkAdded = @($added)
    try { $null = Edit-AkRecord { param($R) $R.Files = @(@($R.Files) + $script:AkAdded) }; Show-AkFiles } catch { $errs += $_.Exception.Message }
    $ui.StatusText.Text = '{0} Datei(en) zur Geräte-Akte hinzugefügt.' -f $added.Count
    if ($errs.Count) { Show-UiError ("Nicht alles hat geklappt:`n" + ($errs -join "`n")) }
})
function Open-AkFile { $r = $ui.AkFileGrid.SelectedItem; if (-not $r) { Show-UiError 'Bitte eine Datei auswählen.'; return }; if (-not (Test-Path -LiteralPath $r.Full)) { Show-UiError ('Die Datei fehlt: ' + $r.Full); return }; try { Start-Process -FilePath $r.Full } catch { Show-UiError $_.Exception.Message } }
$ui.BtnAkFileOpen.Add_Click({ Open-AkFile })
$ui.AkFileGrid.Add_MouseDoubleClick({ if ($ui.AkFileGrid.SelectedItem) { Open-AkFile } })
$ui.BtnAkFileDel.Add_Click({
    $r = $ui.AkFileGrid.SelectedItem; if (-not $r) { Show-UiError 'Bitte eine Datei auswählen.'; return }
    if (-not (Confirm-Ui ("""{0}"" aus der Geräte-Akte entfernen?`n`nDie Kopie im PC-Tools-Datenordner wird gelöscht (das Original, aus dem sie hinzugefügt wurde, bleibt unberührt)." -f $r.Name) 'Warning')) { return }
    $script:AkDelId = [string]$r.Id
    try {
        if (Test-Path -LiteralPath $r.Full) { Remove-Item -LiteralPath $r.Full -Force -ErrorAction Stop }
        $null = Edit-AkRecord { param($R) $R.Files = @($R.Files | Where-Object { [string]$_.Id -ne $script:AkDelId }) }; Show-AkFiles
    } catch { Show-UiError $_.Exception.Message }
})
