$ui.BtnAkHealth.Add_Click({ $ui.Tabs.SelectedItem = $ui.TabHealth })
$ui.BtnAkCopy.Add_Click({
    $a = $script:AkAuto; if (-not $a) { return }; $m = $script:AkRec.Manual
    $t = @(('Geräte-Akte {0} ({1:dd.MM.yyyy})' -f $a.Computer, (Get-Date)), '', ('Hersteller: {0}' -f $a.Hersteller), ('Modell: {0} {1}' -f $a.Modell, $a.Typnummer), ('Seriennummer: {0}' -f $a.Seriennummer), ('BIOS: {0}' -f $a.Bios), ('Firmware: {0}' -f $a.Firmware), ('Prozessor: {0}' -f $a.Prozessor), ('Arbeitsspeicher: {0}' -f $a.Arbeitsspeicher))
    $t += @($a.Datentraeger | ForEach-Object { 'Datenträger: ' + $_ }); $t += @($a.Grafik | ForEach-Object { 'Grafik: ' + $_ })
    $t += @(('Windows: {0}' -f $a.Windows), ('Installiert: {0}' -f $a.Installiert), ('Aktivierung: {0}' -f $a.Aktivierung)); $t += @($a.Netzwerk | ForEach-Object { 'Netzwerk: ' + $_ })
    $t += @(('Akku: {0}' -f $a.Akku), ('Garantie: {0}' -f $ui.AkHwWar.Text), '', ('Kaufdatum: {0}' -f $m.Kaufdatum), ('Preis: {0}' -f $m.Preis), ('Händler: {0}' -f $m.Haendler), ('Rechnungsnummer: {0}' -f $m.Rechnungsnummer), ('Inventarnummer: {0}' -f $m.Inventarnummer), ('Standort: {0}' -f $m.Standort), ('Besitzer: {0}' -f $m.Besitzer))
    Set-Clipboard -Value ($t -join "`r`n"); $ui.StatusText.Text = 'Geräte-Akte als Text kopiert.'
})
$ui.BtnAkPdf.Add_Click({
    if (-not $script:AkAuto -or -not $script:AkRec) { Show-UiError 'Die Akte wird noch eingelesen - bitte einen Moment warten.'; return }
    Add-Type -AssemblyName System.Windows.Forms
    $d = New-Object System.Windows.Forms.SaveFileDialog; $d.Filter = 'PDF (*.pdf)|*.pdf|Webseite (*.html)|*.html'; $d.FileName = ('Geraeteakte_{0}_{1:yyyy-MM-dd}.pdf' -f $env:COMPUTERNAME, (Get-Date))
    if ($d.ShowDialog() -ne 'OK') { return }
    try { $html = ConvertTo-AkHtml @{ Rec = $script:AkRec; Auto = $script:AkAuto; Warranty = $(if ($script:AkWarranty -and $script:AkWarranty.End) { [pscustomobject]@{ End = $script:AkWarranty.End.ToString('yyyy-MM-dd') } } else { $null }); Hist = @($script:AkHist); Css = $ReportCss; Version = $AppVersion; Health = @($script:AkHealth) } }
    catch { Show-UiError ('Bericht konnte nicht erstellt werden: ' + $_.Exception.Message); return }
    $script:AkPdfTarget = $d.FileName; $ui.StatusText.Text = 'Geräte-Akte wird als PDF erstellt ...'; $window.Cursor = 'AppStarting'
    Invoke-Bg -Script { param($h, $o) Convert-HtmlToPdf $h $o } -Arguments @($html, $d.FileName) -Functions @('Convert-HtmlToPdf', 'Get-EdgePath') -Done {
        param($r, $err)
        $window.Cursor = $null
        if ($err) { Show-UiError ('PDF fehlgeschlagen: ' + $err.Message); return }
        $f = [string](@($r | Where-Object { $_ })[-1]); $ui.StatusText.Text = 'Geräte-Akte gespeichert: ' + $f
        if ($f -match '\.html$' -and $script:AkPdfTarget -match '\.pdf$') { [Windows.MessageBox]::Show((T ('Microsoft Edge wurde nicht gefunden - die Akte wurde als Webseite gespeichert. Zum PDF: öffnen und mit "Drucken > Microsoft Print to PDF" speichern.')), (T ('PC-Tools')), 'OK', 'Information') | Out-Null }
        try { Start-Process -FilePath $f } catch { }
    }
})
$ui.BtnAkExport.Add_Click({
    if (-not $script:AkRec) { Show-UiError 'Die Akte wird noch eingelesen.'; return }
    Add-Type -AssemblyName System.Windows.Forms
    $d = New-Object System.Windows.Forms.SaveFileDialog; $d.Filter = 'Akte mit allen Dateien (*.zip)|*.zip|Nur Daten (*.json)|*.json'; $d.FileName = ('Geraeteakte_{0}_{1:yyyy-MM-dd}.zip' -f $env:COMPUTERNAME, (Get-Date))
    if ($d.ShowDialog() -ne 'OK') { return }
    try {
        $json = [pscustomobject]@{ Format = 1; Exported = (Get-Date).ToString('o'); Record = $script:AkRec } | ConvertTo-Json -Depth 8
        if ($d.FileName -match '\.zip$') {
            $tmp = Join-Path $env:TEMP ('PCTools-Akte-{0}' -f (Get-Random)); New-Item -Path (Join-Path $tmp 'Dateien') -ItemType Directory -Force | Out-Null
            [IO.File]::WriteAllText((Join-Path $tmp 'akte.json'), $json, (New-Object Text.UTF8Encoding $false))
            foreach ($fx in @($script:AkRec.Files)) { $full = Join-Path $DataDir ([string]$fx.File); if (Test-Path -LiteralPath $full) { Copy-Item -LiteralPath $full -Destination (Join-Path (Join-Path $tmp 'Dateien') ([string]$fx.Id + '_' + [string]$fx.Name)) -Force } }
            if (Test-Path -LiteralPath $d.FileName) { Remove-Item -LiteralPath $d.FileName -Force }
            Compress-Archive -Path (Join-Path $tmp '*') -DestinationPath $d.FileName -Force
            Remove-Item -LiteralPath $tmp -Recurse -Force -ErrorAction SilentlyContinue
        } else { [IO.File]::WriteAllText($d.FileName, $json, (New-Object Text.UTF8Encoding $false)) }
        $ui.StatusText.Text = 'Geräte-Akte exportiert: ' + $d.FileName
    } catch { Show-UiError ('Export fehlgeschlagen: ' + $_.Exception.Message) }
})
$ui.BtnAkImport.Add_Click({
    if (-not $script:AkAuto) { Show-UiError 'Die Akte wird noch eingelesen.'; return }
    $dlg = New-Object Microsoft.Win32.OpenFileDialog; $dlg.Filter = 'Geräte-Akte (*.zip;*.json)|*.zip;*.json'; $dlg.Title = 'Geräte-Akte importieren'
    if (-not $dlg.ShowDialog()) { return }
    $tmp = $null
    try {
        $src = $dlg.FileName; $jsonFile = $src
        if ($src -match '\.zip$') { $tmp = Join-Path $env:TEMP ('PCTools-AkteImp-{0}' -f (Get-Random)); Expand-Archive -LiteralPath $src -DestinationPath $tmp -Force; $jsonFile = Join-Path $tmp 'akte.json' }
        $imp = Get-Content -LiteralPath $jsonFile -Raw -Encoding UTF8 | ConvertFrom-Json
        $ir = if ($imp.PSObject.Properties['Record']) { $imp.Record } else { $imp }
        if (-not $ir.PSObject.Properties['Manual']) { throw 'Die Datei enthält keine Geräte-Akte von PC-Tools.' }
        $ir = Repair-AkRecord $ir
        $other = ([string]$ir.Serial -and $script:AkSerial -and [string]$ir.Serial -ne $script:AkSerial)
        $q = "Akte von {0} (Seriennummer {1}) importieren?`n`nAngaben zu Kauf und Inventar werden übernommen (leere Felder bleiben unverändert), Wartungseinträge und Dateien werden ergänzt.{2}" -f $ir.Computer, $(if ($ir.Serial) { $ir.Serial } else { '?' }), $(if ($other) { "`n`nACHTUNG: Die Seriennummer passt nicht zu diesem PC ($($script:AkSerial)) - nur fortfahren, wenn das so gewollt ist." } else { '' })
        if (-not (Confirm-Ui $q $(if ($other) { 'Warning' } else { 'Question' }))) { return }
        $newFiles = [System.Collections.Generic.List[object]]::new()
        if ($tmp) {
            $dir = Get-AkFileDir
            foreach ($fx in @($ir.Files)) {
                $zf = Join-Path (Join-Path $tmp 'Dateien') ([string]$fx.Id + '_' + [string]$fx.Name)
                if (-not (Test-Path -LiteralPath $zf)) { continue }
                $target = Join-Path $dir ([string]$fx.Name); $n = 2; while (Test-Path -LiteralPath $target) { $target = Join-Path $dir ('{0} ({1}){2}' -f [IO.Path]::GetFileNameWithoutExtension([string]$fx.Name), $n, [IO.Path]::GetExtension([string]$fx.Name)); $n++ }
                Copy-Item -LiteralPath $zf -Destination $target -Force
                $newFiles.Add([pscustomobject]@{ Id = [string]$fx.Id; Name = [IO.Path]::GetFileName($target); File = $target.Substring($DataDir.TrimEnd('\').Length).TrimStart('\'); Art = [string]$fx.Art; Added = [string]$fx.Added; Size = [double]$fx.Size })
            }
        }
        $script:AkImp = $ir; $script:AkImpFiles = @($newFiles)
        $null = Edit-AkRecord { param($R)
            foreach ($k in $AkManualKeys) { if ([string]$script:AkImp.Manual.$k) { $R.Manual.$k = [string]$script:AkImp.Manual.$k } }
            $ids = @($R.Log | ForEach-Object { [string]$_.Id }); $R.Log = @(@($R.Log) + @($script:AkImp.Log | Where-Object { $ids -notcontains [string]$_.Id }))
            $fids = @($R.Files | ForEach-Object { [string]$_.Id }); $R.Files = @(@($R.Files) + @($script:AkImpFiles | Where-Object { $fids -notcontains [string]$_.Id })) }
        Show-AkRecord
        $ui.StatusText.Text = 'Geräte-Akte importiert ({0} Datei(en) übernommen).' -f $newFiles.Count
    } catch { Show-UiError ('Import fehlgeschlagen: ' + $_.Exception.Message) }
    finally { if ($tmp) { Remove-Item -LiteralPath $tmp -Recurse -Force -ErrorAction SilentlyContinue } }
})
$ui.Tabs.Add_SelectionChanged({
    param($s, $e)
    if ($e.OriginalSource -ne $s -or $s.SelectedItem -ne $ui.TabDevFile) { return }
    if (-not $script:AkLoaded) { $script:AkLoaded = $true; Update-AkPage }
    else { try { $script:AkWarranty = Get-AkWarrantyEnd; Show-AkBadges; Update-AkHist } catch { } }
})

