function Get-WrSvcKeys {
    $k = @()
    if (@($script:WrSvcRows | Where-Object { $_.Gruppe -eq 'Netzwerk' }).Count) { $k += 'NetSvcDefaults' }
    if (@($script:WrSvcRows | Where-Object { $_.Gruppe -eq 'System' }).Count) { $k += 'SvcCore' }
    if (-not $k.Count) { $k = @('NetSvcDefaults', 'SvcCore') }
    return $k
}
