$ui.BtnWrConsole.Add_Click({ try { Start-Process powershell.exe -ArgumentList ('-NoProfile -ExecutionPolicy Bypass -File "{0}" -WinRepair' -f $PSCommandPath) } catch { Show-UiError $_.Exception.Message } })
