# ---------------------------------------------------------------- Toolbox: automatische Aktualisierung (Oberfläche)
function Test-TbAutoOn { -not [IO.File]::Exists((Join-Path (Get-TbDir) 'autosync.off')) }
function Get-TbAutoState {
    $dir = Get-TbDir
    $st = [ordered]@{ Running = $false; Status = ''; Pct = 0; Last = $null; Ok = $true; Summary = '' }
    $lock = Join-Path $dir 'sync.lock'
    if ([IO.File]::Exists($lock)) { try { $p = [int](Get-Content -LiteralPath $lock -Raw).Trim(); if ($p -and (Get-Process -Id $p -ErrorAction SilentlyContinue)) { $st.Running = $true } } catch { } }
    if ($st.Running) { try { $j = Get-Content -LiteralPath (Join-Path $dir 'sync.status.json') -Raw -Encoding UTF8 | ConvertFrom-Json; $st.Status = [string]$j.Status; $st.Pct = [int]$j.Progress } catch { } }
    try { $j = Get-Content -LiteralPath (Join-Path $dir 'sync.json') -Raw -Encoding UTF8 | ConvertFrom-Json; $st.Last = [datetime]$j.Last; $st.Ok = [bool]$j.Ok; $st.Summary = [string]$j.Summary } catch { }
    [pscustomobject]$st
}
function Start-TbAutoSync([switch]$Force) {
    if ($Script:IsLite -and -not $Force) { return }
    $s = Get-TbAutoState
    if ($s.Running) { return }
    if (-not $Force) {
        if (-not (Test-TbAutoOn)) { return }
        $missing = @(Get-TbPortableKeys | Where-Object { -not (Read-TbMeta (Get-TbDir) $_) }).Count
        if ($s.Last -and ((Get-Date) - $s.Last).TotalHours -lt 12 -and -not $missing) { return }
    }
    try { $null = Start-HiddenPS $PSCommandPath @('-TbSync'); $script:TbAutoWasRunning = $true; $script:TbAutoStartAt = Get-Date } catch { }
    Update-TbAutoUi
}
function Update-TbAutoUi {
    if (-not $ui.TbAutoText) { return }
    $s = Get-TbAutoState
    $ui.TbAutoOn.IsChecked = (Test-TbAutoOn)
    if ($s.Running) {
        $ui.TbAutoBar.Visibility = 'Visible'; $ui.TbAutoBar.Value = [math]::Max(2, $s.Pct)
        $ui.TbAutoText.Text = 'Werkzeuge werden im Hintergrund aktualisiert - du kannst PC-Tools ganz normal weiter benutzen.'
        $ui.TbAutoSub.Text = $s.Status
        $ui.BtnTbAutoNow.IsEnabled = $false
    } else {
        $ui.TbAutoBar.Visibility = 'Collapsed'; $ui.BtnTbAutoNow.IsEnabled = $true
        if ($s.Last) {
            $ui.TbAutoText.Text = $(if ($s.Ok) { 'Toolbox ist eingebaut und aktuell' } else { 'Letzte automatische Aktualisierung mit Problemen' }) + (' - geprüft am {0:dd.MM.yyyy} um {0:HH:mm} Uhr' -f $s.Last)
            $ui.TbAutoSub.Text = $s.Summary
        } else {
            $ui.TbAutoText.Text = 'Die Werkzeuge werden beim Start von PC-Tools automatisch geladen und danach aktuell gehalten.'
            $ui.TbAutoSub.Text = $(if (Test-TbAutoOn) { 'Die erste Aktualisierung startet in Kürze (ca. 250 MB).' } else { 'Automatik ist aus.' })
        }
    }
    if ($script:TbAutoWasRunning -and -not $s.Running -and (-not $script:TbAutoStartAt -or ((Get-Date) - $script:TbAutoStartAt).TotalSeconds -gt 60)) {
        $script:TbAutoWasRunning = $false
        if ($script:TbBuilt) { try { Update-TbView; Start-TbSizeScan } catch { } }
    }
    if ($s.Running) { $script:TbAutoWasRunning = $true }
}
$ui.BtnTbAutoNow.Add_Click({ Start-TbAutoSync -Force })
$ui.BtnTbAutoLog.Add_Click({ $lf = Join-Path (Get-TbDir) 'sync.log'; if (Test-Path -LiteralPath $lf) { Start-Process notepad.exe ('"{0}"' -f $lf) } else { $ui.StatusText.Text = 'Noch kein Protokoll vorhanden.' } })
$ui.TbAutoOn.Add_Click({
    $off = Join-Path (Get-TbDir) 'autosync.off'
    try { New-Item -Path (Get-TbDir) -ItemType Directory -Force | Out-Null; if ($ui.TbAutoOn.IsChecked) { Remove-Item -LiteralPath $off -Force -ErrorAction SilentlyContinue; Start-TbAutoSync } else { Set-Content -LiteralPath $off -Value 'aus' -Encoding ASCII } } catch { }
    Update-TbAutoUi
})
$script:TbAutoTimer = New-Object System.Windows.Threading.DispatcherTimer
$script:TbAutoTimer.Interval = [TimeSpan]::FromSeconds(20)
$script:TbAutoTicks = 0
$script:TbAutoTimer.Add_Tick({
    $script:TbAutoTicks++
    if ($script:TbAutoTicks -eq 1) { $script:TbAutoTimer.Interval = [TimeSpan]::FromSeconds(3); try { Start-TbAutoSync } catch { } }
    try { if ($ui.Tabs.SelectedItem -eq $ui.TabToolbox -or $script:TbAutoWasRunning) { Update-TbAutoUi } } catch { }
})
$script:TbAutoTimer.Start()
$ui.Tabs.Add_SelectionChanged({ param($s, $e) if ($e.OriginalSource -eq $s -and $s.SelectedItem -eq $ui.TabToolbox) { try { Update-TbAutoUi } catch { } } })
function Get-ServerModeOn {
    $sc = $null; try { $sc = Get-SysClassCached } catch { }
    if ($sc -and $sc.IsServer) { return $true }
    try { return [bool](Read-PflegeConfig).Settings.ServerMode } catch { return $false }
}
# ---------------------------------------------------------------- Lite-Ansicht und Stabilität / Selbsttest (9.3)
$LiteTabs = @('TabOverview', 'TabAssistant', 'TabClean', 'TabCleaner', 'TabOpt', 'TabUpd', 'TabDrv', 'TabSched', 'TabSecurity', 'TabRepair', 'TabWinRepair', 'TabHealth', 'TabBackup', 'TabFullBackup', 'TabToolbox', 'TabRescue', 'TabRemote', 'TabNetDiag', 'TabWlan', 'TabNetDoc', 'TabSettings', 'TabManual', 'TabLog')
function Set-LiteView([bool]$On) {
    $items = @($ui.Tabs.Items)
    foreach ($it in $items) {
        if ([string]$it.Tag -eq 'H') { continue }
        $it.Visibility = $(if (-not $On -or $LiteTabs -contains [string]$it.Name) { 'Visible' } else { 'Collapsed' })
    }
    # Server-Tools nur auf Windows Server oder bei eingeschaltetem Server-Modus zeigen
    if ($ui.TabServer) { $ui.TabServer.Visibility = $(if (Get-ServerModeOn) { 'Visible' } else { 'Collapsed' }) }
    # Abschnitts-Überschriften ohne sichtbare Seite ausblenden
    for ($i = 0; $i -lt $items.Count; $i++) {
        if ([string]$items[$i].Tag -ne 'H') { continue }
        $vis = $false
        for ($j = $i + 1; $j -lt $items.Count -and [string]$items[$j].Tag -ne 'H'; $j++) { if ($items[$j].Visibility -eq 'Visible') { $vis = $true; break } }
        $items[$i].Visibility = $(if ($vis) { 'Visible' } else { 'Collapsed' })
    }
    if ($On) { $window.Title = $window.Title -replace '^PC-Tools(?! Lite)', 'PC-Tools Lite' } else { $window.Title = $window.Title -replace '^PC-Tools Lite', 'PC-Tools' }
    try { $ui.StabLite.Text = $(if ($On) { 'Lite-Ansicht ist an: nur die wichtigsten Seiten, weniger Hintergrundarbeit. Alle anderen Funktionen findest du über die Suche (Strg+K) - sie werden dann eingeblendet.' } else { 'Volle Ansicht mit allen Seiten.' }); $ui.BtnLiteToggle.Content = $(if ($On) { 'Volle Ansicht einschalten' } else { 'Lite-Ansicht einschalten' }) } catch { }
}
# Über Suche oder Knöpfe geöffnete ausgeblendete Seiten einblenden
$ui.Tabs.Add_SelectionChanged({ param($s, $e) if ($e.OriginalSource -eq $s -and $s.SelectedItem -and $s.SelectedItem.Visibility -ne 'Visible') { $s.SelectedItem.Visibility = 'Visible' } })
