'@
    $x = $x.Replace('PC-Tools 10', 'PC-Tools ' + (($AppVersion -split '\.')[0]))
    $x = $x.Replace('__LANGITEMS__', ((@($LangList.Keys | ForEach-Object { '<ComboBoxItem Uid="notr" Content="{0}" Tag="{1}"/>' -f $LangList[$_], $_ })) -join ''))
    $w = [Windows.Markup.XamlReader]::Parse($x)
    $script:EdRelaunch = $false
    $lb = $w.FindName('EdLang'); foreach ($it in $lb.Items) { if ([string]$it.Tag -eq $script:UiLang) { $lb.SelectedItem = $it } }
    $lb.Add_SelectionChanged({
        param($sd, $e)
        $c = [string]$sd.SelectedItem.Tag; if (-not $c -or $c -eq $script:UiLang) { return }
        $sd.IsEnabled = $false; $script:EdW.Cursor = 'Wait'
        $ok = $false; try { $ok = Initialize-I18n $c -Download } catch { }
        $script:EdW.Cursor = $null
        if (-not $ok -and $c -ne 'de-DE') { [Windows.MessageBox]::Show((T (('The language file for {0} could not be loaded (no internet connection?). PC-Tools stays in German for now - you can change the language later under Settings.' -f $LangList[$c]))), (T ('PC-Tools')), 'OK', 'Warning') | Out-Null; $sd.IsEnabled = $true; return }
        Set-UiLang $c
        $script:EdRelaunch = $true; $script:EdW.Close()
    })
    $script:EdLite = $PreLite; $script:EdW = $w; $script:EdOk = $false
    $script:EdCards = @{ Lite = $w.FindName('CardLite'); Full = $w.FindName('CardFull') }
    $script:EdPaint = {
        $on = (New-Object Windows.Media.BrushConverter).ConvertFromString('#2D7FF9'); $off = (New-Object Windows.Media.BrushConverter).ConvertFromString('#E2E7F0')
        $script:EdCards.Lite.BorderBrush = $(if ($script:EdLite) { $on } else { $off }); $script:EdCards.Full.BorderBrush = $(if ($script:EdLite) { $off } else { $on })
        $script:EdCards.Lite.BorderThickness = $(if ($script:EdLite) { 3 } else { 2 }); $script:EdCards.Full.BorderThickness = $(if ($script:EdLite) { 2 } else { 3 })
    }
    & $script:EdPaint
    # MouseDown + Handled: sonst startet das DragMove des Fensters und das MouseUp der Karte kommt nie an
    $script:EdCards.Lite.Add_MouseLeftButtonDown({ param($s, $e) $script:EdLite = $true; & $script:EdPaint; $e.Handled = $true; if ($e.ClickCount -ge 2) { $script:EdOk = $true; $script:EdW.Close() } })
    $script:EdCards.Full.Add_MouseLeftButtonDown({ param($s, $e) $script:EdLite = $false; & $script:EdPaint; $e.Handled = $true; if ($e.ClickCount -ge 2) { $script:EdOk = $true; $script:EdW.Close() } })
    $w.FindName('BtnGo').Add_Click({ $script:EdOk = $true; $script:EdW.Close() })
    $w.Add_MouseLeftButtonDown({ param($s, $e) try { if ($e.OriginalSource -isnot [Windows.Controls.Primitives.ButtonBase]) { $s.DragMove() } } catch { } })
    $w.Add_KeyDown({ param($s, $e) if ($e.Key -eq 'Return') { $script:EdOk = $true; $s.Close() } elseif ($e.Key -eq 'Escape') { $s.Close() } })
    [void]$w.ShowDialog()
    return [pscustomobject]@{ Relaunch = [bool]$script:EdRelaunch; Ok = $script:EdOk; Lite = [bool]$script:EdLite; Remember = [bool]$w.FindName('Remember').IsChecked; TbAuto = [bool]$w.FindName('TbAutoFirst').IsChecked; Simple = [bool]$w.FindName('EdSimple').IsChecked }
}
function Set-EditionFiles([bool]$Lite) {
    $files = @(Join-Path $DataDir 'lite.txt'); if ($PSScriptRoot -and ($PSScriptRoot.TrimEnd('\') -ne $DataDir.TrimEnd('\'))) { $files += (Join-Path $PSScriptRoot 'lite.txt') }
    foreach ($lf in $files) { if ($Lite) { Set-Content -LiteralPath $lf -Value 'PC-Tools Lite' -Encoding ASCII -ErrorAction SilentlyContinue } else { Remove-Item -LiteralPath $lf -Force -ErrorAction SilentlyContinue } }
    $Script:IsLite = $Lite
}
$EditionFile = Join-Path $DataDir 'edition.txt'
$edMode = ''; try { if (Test-Path -LiteralPath $EditionFile) { $edMode = ([string](Get-Content -LiteralPath $EditionFile -Raw)).Trim() } } catch { }
if ($edMode -notin 'Lite', 'Voll') {
    try {
        $ch = Show-EditionChooser ([bool]$Script:IsLite)
        $nRel = 0
        while ($ch.Relaunch -and $nRel -lt 12) { $nRel++; $ch = Show-EditionChooser ([bool]$ch.Lite) }
        if ($ch.Ok) {
            Set-EditionFiles $ch.Lite
            if ($ch.Simple) { try { Set-Content -LiteralPath (Join-Path $DataDir 'einfach.txt') -Value 'Einfach-Modus' -Encoding ASCII } catch { } }
            Set-Content -LiteralPath $EditionFile -Value $(if (-not $ch.Remember) { 'Fragen' } elseif ($ch.Lite) { 'Lite' } else { 'Voll' }) -Encoding ASCII
            # Erststart-Frage: Toolbox automatisch aktuell halten (steuert die autosync.off-Markierung)
            try {
                $tbOff = Join-Path (Get-TbDir) 'autosync.off'
                if ($ch.TbAuto) { Remove-Item -LiteralPath $tbOff -Force -ErrorAction SilentlyContinue }
                else { New-Item (Split-Path $tbOff) -ItemType Directory -Force -ErrorAction SilentlyContinue | Out-Null; Set-Content -LiteralPath $tbOff -Value 'aus' -Encoding ASCII -ErrorAction SilentlyContinue }
            } catch { }
        }
    } catch { }
}

if ($Script:IsLite) { try { Set-LiteView $true } catch { } }
$ui.BtnLiteToggle.Add_Click({
    $on = -not $Script:IsLite
    $files = @(Join-Path $DataDir 'lite.txt'); if ($PSScriptRoot -and ($PSScriptRoot.TrimEnd('\') -ne $DataDir.TrimEnd('\'))) { $files += (Join-Path $PSScriptRoot 'lite.txt') }
    try {
        foreach ($lf in $files) { if ($on) { Set-Content -LiteralPath $lf -Value 'PC-Tools Lite' -Encoding ASCII -ErrorAction SilentlyContinue } else { Remove-Item -LiteralPath $lf -Force -ErrorAction SilentlyContinue } }
        $Script:IsLite = $on
        Set-LiteView $on
        try { $ef = Join-Path $DataDir 'edition.txt'; if (Test-Path -LiteralPath $ef) { $em = ([string](Get-Content -LiteralPath $ef -Raw)).Trim(); if ($em -in 'Lite', 'Voll') { Set-Content -LiteralPath $ef -Value $(if ($on) { 'Lite' } else { 'Voll' }) -Encoding ASCII } } } catch { }
        $ui.StatusText.Text = $(if ($on) { 'Lite-Ansicht eingeschaltet.' } else { 'Volle Ansicht eingeschaltet.' })
    } catch { Show-UiError $_.Exception.Message }
})
