# ---- Hilfe holen und Einfach-Modus (14.2)
function Start-HelpRequest {
    $big = ($ui.SimpleOverlay.Visibility -eq 'Visible')
    $x = @"
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Title="PC-Tools - Hilfe holen" Width="620" SizeToContent="Height" WindowStartupLocation="CenterOwner" ResizeMode="NoResize" FontFamily="Segoe UI" FontSize="$(if ($big) { 18 } else { 14 })" Background="#F4F6FA">
  <StackPanel Margin="24">
    <TextBlock Text="Hilfe holen" FontSize="$(if ($big) { 28 } else { 22 })" FontWeight="SemiBold" Foreground="#1F2A44"/>
    <TextBlock Text="Was ist los? Ein Satz reicht - zum Beispiel: Drucker geht nicht, PC ist langsam, komische Meldung. Du kannst das Feld auch leer lassen." TextWrapping="Wrap" Foreground="#475569" Margin="0,8,0,10"/>
    <TextBox x:Name="HMsg" Height="$(if ($big) { 130 } else { 100 })" AcceptsReturn="True" TextWrapping="Wrap" VerticalScrollBarVisibility="Auto" Padding="8"/>
    <TextBlock Text="Mitgeschickt werden: Zustand des PCs, gefundene Probleme, Fehler aus den letzten 3 Tagen und die letzten Zeilen des Protokolls. Keine Passwörter, keine Dateien." TextWrapping="Wrap" Foreground="#6B7890" FontSize="$(if ($big) { 15 } else { 12 })" Margin="0,10,0,0"/>
    <StackPanel Orientation="Horizontal" HorizontalAlignment="Right" Margin="0,18,0,0">
      <Button x:Name="HOk" Content="Hilfe anfordern" Padding="20,10" Margin="0,0,10,0" IsDefault="True"/>
      <Button x:Name="HNo" Content="Abbrechen" Padding="20,10" IsCancel="True"/>
    </StackPanel>
  </StackPanel>
</Window>
"@
    $dlg = [Windows.Markup.XamlReader]::Parse((Convert-ThemeXaml $x)); try { $dlg.Owner = $window } catch { }
    $dlg.FindName('HOk').Add_Click({ $dlg.DialogResult = $true }.GetNewClosure())
    $dlg.Add_ContentRendered({ try { $dlg.FindName('HMsg').Focus() } catch { } }.GetNewClosure())
    if (-not $dlg.ShowDialog()) { return }
    $msg = ([string]$dlg.FindName('HMsg').Text).Trim()
    $ui.StatusText.Text = 'Hilfe wird angefordert ...'
    if ($ui.SimpleState) { $ui.SimpleState.Text = 'Hilfe wird angefordert ...' }
    $ui.BtnSimpleHelp.IsEnabled = $false; $ui.BtnScHelp.IsEnabled = $false
    Invoke-Bg -Script { param($m, $sc) $r = New-HelpReport $m $sc; Send-HelpRequest $r } -Arguments @($msg, $script:ScLast) -Functions @('New-HelpReport', 'Format-HelpReportText', 'Send-HelpRequest', 'Get-HealthItems', 'Get-HealthArgs', 'Get-HealthState', 'Read-PflegeConfig', 'Send-PflegeNotify', 'Write-FleetStatus', 'Connect-BackupTarget') -Done {
        param($r, $err)
        $ui.BtnSimpleHelp.IsEnabled = $true; $ui.BtnScHelp.IsEnabled = $true
        $x = @($r | Where-Object { $_ -and $_.PSObject.Properties['TxtFile'] })[0]
        if ($err -or -not $x) { $ui.StatusText.Text = 'Hilfe holen fehlgeschlagen.'; Show-UiError ('Hilfe holen hat nicht geklappt: ' + $(if ($err) { $err.Message } else { 'kein Ergebnis' })); return }
        $ways = [System.Collections.Generic.List[string]]::new()
        if ($x.Fleet) { $ways.Add('Dein Helfer sieht den Hilferuf in PC-Tools unter "Meine PCs".') }
        if ($x.Notified) { $ways.Add('Dein Helfer hat eine Nachricht aufs Handy bekommen.') }
        $mail = ''; try { $mail = [string](Read-PflegeConfig).Help.Mail } catch { }
        if ($mail -match '^[^@\s]+@[^@\s]+\.[^@\s]+$') {
            try {
                $body = [string]$x.Text; if ($body.Length -gt 900) { $body = $body.Substring(0, 900) + "`r`n... (vollständiger Bericht im Anhang: " + [IO.Path]::GetFileName($x.TxtFile) + ')' }
                Start-Process ('mailto:{0}?subject={1}&body={2}' -f $mail, [Uri]::EscapeDataString(('PC-Tools: Hilfe für {0}' -f $env:COMPUTERNAME)), [Uri]::EscapeDataString($body))
                Start-Process 'explorer.exe' ('/select,"{0}"' -f $x.TxtFile)
                $ways.Add(('Eine E-Mail an {0} ist vorbereitet - bitte nur noch auf Senden klicken (die Datei mit dem Bericht ist im geöffneten Ordner markiert und kann angehängt werden).' -f $mail))
            } catch { }
        }
        if (-not $ways.Count) {
            $desk = Join-Path ([Environment]::GetFolderPath('Desktop')) 'PC-Tools Hilfe.txt'
            try { Copy-Item -LiteralPath $x.TxtFile -Destination $desk -Force } catch { $desk = $x.TxtFile }
            try { [Windows.Clipboard]::SetText([string]$x.Text) } catch { }
            [Windows.MessageBox]::Show((T ("Der Bericht liegt jetzt auf dem Desktop: ""PC-Tools Hilfe.txt"" und ist auch in die Zwischenablage kopiert.`n`nSchick ihn deinem Helfer, zum Beispiel per E-Mail oder WhatsApp (einfach einfügen).`n`nTipp für den Helfer: Unter Einstellungen > Stabilität > ""E-Mail des Helfers"" eintragen oder ""Meine PCs"" einrichten - dann geht es beim nächsten Mal automatisch.")), (T 'PC-Tools'), 'OK', 'Information') | Out-Null
            $ui.StatusText.Text = 'Hilfe-Bericht auf dem Desktop gespeichert.'
        } else {
            [Windows.MessageBox]::Show((T ("Deine Hilfe-Anfrage ist unterwegs.`n`n- " + ($ways -join "`n- "))), (T 'PC-Tools'), 'OK', 'Information') | Out-Null
            $ui.StatusText.Text = 'Hilfe angefordert.'
        }
        if ($ui.SimpleState) { $ui.SimpleState.Text = $ui.StatusText.Text }
    }
}
$ui.BtnScHelp.Add_Click({ try { Start-HelpRequest } catch { Show-UiError ('Hilfe holen: ' + $_.Exception.Message) } })
$ui.BtnHelpTry.Add_Click({ try { try { Save-PflegeConfig (Get-ConfigFromUi) } catch { }; Start-HelpRequest } catch { Show-UiError ('Hilfe holen: ' + $_.Exception.Message) } })
$ui.Help_Mail.Add_LostFocus({ try { $c = Read-PflegeConfig; $c.Help | Add-Member -NotePropertyName Mail -NotePropertyValue ([string]$ui.Help_Mail.Text).Trim() -Force; Save-PflegeConfig $c } catch { } })
$script:SimpleFile = Join-Path $DataDir 'einfach.txt'
$script:SimpleWasBusy = $false; $script:SimpleScAsk = [datetime]::MinValue
$simpleTimer = New-Object Windows.Threading.DispatcherTimer
$simpleTimer.Interval = [TimeSpan]::FromSeconds(2)
function Update-SimpleView {
    if ($ui.SimpleOverlay.Visibility -ne 'Visible') { return }
    $busy = [bool]$script:Job
    if ($script:SimpleWasBusy -and -not $busy) { $script:SimpleScAsk = Get-Date; try { Update-ScScoreUi } catch { } }
    $script:SimpleWasBusy = $busy
    $ui.BtnSimpleFix.IsEnabled = -not $busy
    if ($busy) {
        $ui.SimpleLight.Fill = New-UiBrush '#2D7FF9'; $ui.SimpleHead.Text = 'PC-Tools arbeitet gerade ...'
        $ui.SimpleSub.Text = $(if ([string]$ui.ActStep.Text) { [string]$ui.ActStep.Text } else { 'Bitte den PC eingeschaltet lassen.' })
        $ui.SimpleProgress.Visibility = 'Visible'; try { $ui.SimpleProgress.Value = [double]$ui.Progress.Value } catch { }
        $ui.SimpleState.Text = 'Du kannst nebenbei weiterarbeiten. Wenn alles fertig ist, springt die Ampel wieder um.'
        return
    }
    $ui.SimpleProgress.Visibility = 'Collapsed'
    $r = $script:ScLast
    if (-not $r) {
        $ui.SimpleLight.Fill = New-UiBrush '#9AA5B8'; $ui.SimpleHead.Text = 'Der Zustand wird geprüft ...'; $ui.SimpleSub.Text = 'Einen Moment bitte.'
        if (-not $script:ScBusy -and ((Get-Date) - $script:SimpleScAsk).TotalSeconds -gt 90) { $script:SimpleScAsk = Get-Date; try { Update-ScScoreUi } catch { } }
        return
    }
    $s = 0; try { $s = [int]$r.Score } catch { }
    $bad = @(@($r.Components) | Where-Object { $_ -and [double]$_.Max -gt 0 -and [double]$_.Points -lt [double]$_.Max } | Sort-Object { [double]$_.Points - [double]$_.Max } | Select-Object -First 3 | ForEach-Object { [string]$_.Name })
    if ($s -ge 80) { $ui.SimpleLight.Fill = New-UiBrush '#22C55E'; $ui.SimpleHead.Text = 'Alles in Ordnung' }
    elseif ($s -ge 60) { $ui.SimpleLight.Fill = New-UiBrush '#F59E0B'; $ui.SimpleHead.Text = 'Ein paar Kleinigkeiten' }
    else { $ui.SimpleLight.Fill = New-UiBrush '#DC2626'; $ui.SimpleHead.Text = 'Bitte reparieren' }
    $ui.SimpleSub.Text = ('Zustand: {0} von 100 Punkten.' -f $s) + $(if ($bad.Count -and $s -lt 100) { "`n" + (T 'Verbesserungsbedarf:') + ' ' + ($bad -join ', ') } else { '' })
    if (-not [string]$ui.SimpleState.Text -or $ui.SimpleState.Text -like 'Du kannst nebenbei*') { $ui.SimpleState.Text = $(if ($s -lt 80) { 'Tipp: "Alles reparieren" erledigt alles, was automatisch geht. Wenn danach noch etwas nicht stimmt: "Hilfe holen".' } else { 'Wenn trotzdem etwas nicht funktioniert: "Hilfe holen".' }) }
}
function Set-SimpleMode([bool]$On) {
    try { if ($On) { Set-Content -LiteralPath $script:SimpleFile -Value 'Einfach-Modus' -Encoding ASCII } else { Remove-Item -LiteralPath $script:SimpleFile -Force -ErrorAction SilentlyContinue } } catch { }
    $ui.SimpleOverlay.Visibility = $(if ($On) { 'Visible' } else { 'Collapsed' })
    if ($On) { $simpleTimer.Start(); Update-SimpleView } else { $simpleTimer.Stop(); $ui.StatusText.Text = 'Normale Ansicht. Den Einfach-Modus gibt es unter Einstellungen > Stabilität.' }
}
$simpleTimer.Add_Tick({ try { Update-SimpleView } catch { } })
$ui.BtnSimpleFix.Add_Click({
    try {
        if (-not $script:ScLast) { Show-UiError 'Der Zustand wird noch geprüft - bitte gleich noch einmal klicken.'; return }
        $ui.SimpleState.Text = ''
        Start-ScFixAll
        Update-SimpleView
    } catch { Show-UiError ('Alles reparieren: ' + $_.Exception.Message) }
})
$ui.BtnSimpleHelp.Add_Click({ try { Start-HelpRequest } catch { Show-UiError ('Hilfe holen: ' + $_.Exception.Message) } })
$ui.BtnSimpleExit.Add_Click({ Set-SimpleMode $false })
$ui.BtnSimpleOn.Add_Click({ Set-SimpleMode $true })
if (Test-Path -LiteralPath $script:SimpleFile) { try { Set-SimpleMode $true } catch { } }
function Update-StabInfo {
    $pv = Get-PflegeVorversion
    $sk = @(Get-UpdateSkip)
    $ui.StabInfo.Text = ('Installiert: {0}{1}  ·  gesicherte Vorversion: {2}{3}' -f $AppVersion, $(if ($Script:IsLite) { ' Lite' } else { '' }), $(if ($pv) { $pv } else { 'keine (entsteht beim nächsten Update)' }), $(if ($sk.Count) { '  ·  zurückgenommene Versionen: ' + ($sk -join ', ') } else { '' }))
    $ui.BtnRollback.IsEnabled = [bool]($pv -and $pv -ne $AppVersion)
}
$ui.BtnRollback.Add_Click({
    $pv = Get-PflegeVorversion
    if (-not $pv) { return }
    if ($script:Job) { Show-UiError 'Bitte warten, bis die laufende Aufgabe fertig ist.'; return }
    if (-not (Confirm-Ui ("Zurück auf Version {0}?`n`nVersion {1} wird danach nicht mehr automatisch installiert - erst die nächste neuere Version. PC-Tools startet neu." -f $pv, $AppVersion))) { return }
    try { $null = Restore-PflegeVorversion 'von Hand zurückgesetzt'; $script:Restarting = $true; $null = Start-HiddenPS $PSCommandPath; $window.Close() } catch { Show-UiError ('Zurücksetzen nicht möglich: ' + $_.Exception.Message) }
})
$ui.BtnErrLog.Add_Click({
    $l = @($script:GuiErrLog, (Join-Path (Join-Path $DataDir 'Logs') 'Update-Verlauf.log')) | Where-Object { Test-Path -LiteralPath $_ }
    if (-not $l.Count) { $ui.StatusText.Text = 'Keine Fehler protokolliert - bestens.'; return }
    foreach ($x in $l) { Start-Process notepad.exe ('"{0}"' -f $x) }
})
$ui.BtnSelfTest.Add_Click({ Start-SelfTest })
function Start-SelfTest {
    $ui.BtnSelfTest.IsEnabled = $false; $ui.SelfTestInfo.Text = 'Selbsttest läuft (ca. 10-20 Sekunden) ...'
    $srcVer = if ($script:UpdManifest) { [string]$script:UpdManifest.Version } else { '' }
    $arg = @{ DataDir = $DataDir; ConfigFile = $ConfigFile; Task = $TaskName; Ver = $AppVersion; SrcVer = $srcVer; Script = $PSCommandPath; Vor = [string](Get-PflegeVorversion); Lite = [bool]$Script:IsLite; Portable = [bool]$Script:IsPortable }
    Invoke-Bg -Arguments @($arg) -Script {
        param($a)
        $rows = [System.Collections.Generic.List[object]]::new()
        function R([string]$Area, [string]$Level, [string]$State, [string]$Detail) { $rows.Add([pscustomobject]@{ Area = $Area; State = $State; Detail = $Detail; Level = $Level }) }
        $psv = $PSVersionTable.PSVersion
        R 'PowerShell' $(if ($psv.Major -eq 5 -and $psv.Minor -ge 1) { 'Good' } else { 'Warn' }) ('{0}' -f $psv) $(if ($psv.Major -eq 5) { 'Windows PowerShell 5.1 - passt.' } else { 'PC-Tools ist für Windows PowerShell 5.1 gebaut.' })
        $rel = 0; try { $rel = [int](Get-ItemProperty 'HKLM:\SOFTWARE\Microsoft\NET Framework Setup\NDP\v4\Full' -ErrorAction Stop).Release } catch { }
        R '.NET Framework' $(if ($rel -ge 461808) { 'Good' } else { 'Warn' }) $(if ($rel -ge 528040) { '4.8' } elseif ($rel -ge 461808) { '4.7.2' } else { 'alt' }) 'Wird für Oberfläche und Downloads gebraucht (ab 4.7.2).'
        $adm = ([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)
        R 'Administratorrechte' $(if ($adm) { 'Good' } else { 'Error' }) $(if ($adm) { 'ja' } else { 'nein' }) 'Ohne Administratorrechte funktionieren die meisten Aufgaben nicht.'
        $wr = $false; try { $tf = Join-Path $a.DataDir ('selftest-{0}.tmp' -f $PID); Set-Content -LiteralPath $tf -Value 'x' -ErrorAction Stop; Remove-Item -LiteralPath $tf -Force; $wr = $true } catch { }
        R 'Datenordner' $(if ($wr) { 'Good' } else { 'Error' }) $(if ($wr) { 'beschreibbar' } else { 'NICHT beschreibbar' }) $a.DataDir
        try { $dr = New-Object IO.DriveInfo ([IO.Path]::GetPathRoot($a.DataDir)); $gb = $dr.AvailableFreeSpace / 1GB; R 'Freier Speicher' $(if ($gb -ge 10) { 'Good' } elseif ($gb -ge 3) { 'Warn' } else { 'Error' }) ('{0:N1} GB frei auf {1}' -f $gb, $dr.Name) 'Unter 3 GB scheitern Updates und Downloads.' } catch { }
        $cfgOk = $false; $cfgMsg = 'fehlt (Standardwerte)'
        if (Test-Path -LiteralPath $a.ConfigFile) { try { $null = Get-Content -LiteralPath $a.ConfigFile -Raw -Encoding UTF8 | ConvertFrom-Json -ErrorAction Stop; $cfgOk = $true; $cfgMsg = 'gültig' } catch { $cfgMsg = 'BESCHÄDIGT' } }
        R 'Einstellungen (config.json)' $(if ($cfgOk) { 'Good' } elseif ($cfgMsg -like 'fehlt*') { 'Warn' } else { 'Error' }) $cfgMsg $(if (Test-Path -LiteralPath ($a.ConfigFile + '.bak')) { 'Sicherungskopie config.json.bak vorhanden.' } else { 'Noch keine Sicherungskopie (entsteht beim nächsten Speichern).' })
        $scr = Join-Path $a.DataDir 'PCPflege.ps1'; if (-not (Test-Path -LiteralPath $scr)) { $scr = $a.Script }
        try { $t0 = $null; $e0 = $null; [void][System.Management.Automation.Language.Parser]::ParseFile($scr, [ref]$t0, [ref]$e0); R 'Programmdatei' $(if (@($e0).Count) { 'Error' } else { 'Good' }) $(if (@($e0).Count) { '{0} Fehler' -f @($e0).Count } else { 'fehlerfrei' }) $scr } catch { R 'Programmdatei' 'Warn' 'nicht prüfbar' $_.Exception.Message }
        if ($a.Portable) { R 'Zeitplan' 'Good' 'portabel' 'Vom Stick gibt es keinen Zeitplan.' } else {
            $tk = $null; try { $tk = Get-ScheduledTask -TaskName $a.Task -ErrorAction Stop } catch { }
            if (-not $tk) { R 'Zeitplan' 'Warn' 'nicht eingerichtet' 'Automatische Pflege ist aus oder die Aufgabe fehlt (Einstellungen speichern richtet sie ein).' }
            else {
                $argx = [string]$tk.Actions[0].Arguments; $tp = ''; if ($argx -match '-File "([^"]+)"') { $tp = $Matches[1] }
                $info = $null; try { $info = Get-ScheduledTaskInfo -TaskName $a.Task -ErrorAction Stop } catch { }
                $res = if ($info) { [int64]$info.LastTaskResult } else { -1 }
                $okRes = $res -in 0, 267011, 267009
                R 'Zeitplan' $(if ($tp -and -not (Test-Path -LiteralPath $tp)) { 'Error' } elseif ($okRes) { 'Good' } else { 'Warn' }) $(if ($info -and $info.LastRunTime -and $info.LastRunTime.Year -gt 2000) { 'zuletzt {0:dd.MM.yyyy HH:mm}' -f $info.LastRunTime } else { 'noch nicht gelaufen' }) $(if ($tp -and -not (Test-Path -LiteralPath $tp)) { 'Die Aufgabe zeigt auf eine fehlende Datei - Einstellungen einmal speichern.' } elseif (-not $okRes) { 'Letztes Ergebnis 0x{0:X} - Protokoll ansehen.' -f $res } else { 'Nächster Lauf: ' + $(if ($info -and $info.NextRunTime) { $info.NextRunTime.ToString('dd.MM.yyyy HH:mm') } else { '-' }) })
            }
        }
        R 'Update-Quelle' $(if (-not $a.SrcVer) { 'Warn' } else { 'Good' }) $(if ($a.SrcVer) { 'erreichbar, Version ' + $a.SrcVer } else { 'nicht erreichbar/nicht geprüft' }) ('Installiert: {0}' -f $a.Ver)
        R 'Vorversion (Rückfall)' $(if ($a.Vor) { 'Good' } else { 'Warn' }) $(if ($a.Vor) { $a.Vor } else { 'keine' }) 'Wird bei jedem Update automatisch gesichert. Startet eine neue Version zweimal nicht, geht PC-Tools selbst zurück.'
        $wg = $null; try { $wg = Get-Command winget.exe -ErrorAction Stop } catch { }
        if (-not $wg) { $wg = Get-ChildItem -Path (Join-Path $env:ProgramFiles 'WindowsApps') -Filter 'winget.exe' -Recurse -ErrorAction SilentlyContinue | Select-Object -First 1 }
        R 'winget' $(if ($wg) { 'Good' } else { 'Warn' }) $(if ($wg) { 'vorhanden' } else { 'fehlt' }) 'Für Programm-Updates und den Software-Kiosk (App-Installer aus dem Store).'
        try { $ls = [int64]0; Get-ChildItem -LiteralPath (Join-Path $a.DataDir 'Logs') -File -Recurse -ErrorAction SilentlyContinue | ForEach-Object { $ls += $_.Length }; R 'Protokolle' $(if ($ls -gt 500MB) { 'Warn' } else { 'Good' }) ('{0:N0} MB' -f ($ls / 1MB)) 'Alte Protokolle räumt die Pflege automatisch auf.' } catch { }
        $el = Join-Path (Join-Path $a.DataDir 'Logs') 'Oberflaeche-Fehler.log'; $ec = 0
        if (Test-Path -LiteralPath $el) { $lim = (Get-Date).AddDays(-7).ToString('yyyy-MM-dd'); $ec = @(Get-Content -LiteralPath $el -Encoding UTF8 | Where-Object { $_ -match '^(\d{4}-\d{2}-\d{2})' -and $Matches[1] -ge $lim }).Count }
        R 'Abgefangene Fehler (7 Tage)' $(if ($ec -eq 0) { 'Good' } elseif ($ec -lt 5) { 'Warn' } else { 'Error' }) ([string]$ec) $(if ($ec) { 'Fehlerprotokoll ansehen und an den Entwickler schicken.' } else { 'keine' })
        $st = $null; try { $st = Get-Content -LiteralPath (Join-Path $a.DataDir 'start.json') -Raw -Encoding UTF8 | ConvertFrom-Json } catch { }
        R 'Startschutz' 'Good' $(if ($st) { 'aktiv' } else { 'aktiv (erster Start)' }) 'Überwacht jeden Start dieser Version.'
        R 'Ansicht' 'Good' $(if ($a.Lite) { 'Lite' } else { 'Voll' }) 'Umschaltbar unter Einstellungen > Stabilität.'
        , $rows
    } -Done {
        param($r, $err)
        $ui.BtnSelfTest.IsEnabled = $true
        if ($err) { $ui.SelfTestInfo.Text = 'Selbsttest fehlgeschlagen: ' + $err.Message; return }
        $rows = @($r | ForEach-Object { $_ } | Where-Object { $_ -and $_.PSObject.Properties['Area'] })
        Set-GridItems $ui.SelfTestGrid $rows
        $bad = @($rows | Where-Object { $_.Level -eq 'Error' }).Count; $warn = @($rows | Where-Object { $_.Level -eq 'Warn' }).Count
        $ui.SelfTestInfo.Text = $(if ($bad) { '{0} Problem(e), {1} Hinweis(e) - Details in der Liste.' -f $bad, $warn } elseif ($warn) { 'Alles läuft - {0} Hinweis(e).' -f $warn } else { 'Alles in Ordnung.' })
    }
}
$ui.Tabs.Add_SelectionChanged({ param($s, $e) if ($e.OriginalSource -eq $s -and $s.SelectedItem -eq $ui.TabSettings) { try { Update-StabInfo } catch { } } })
Add-SearchEntry 'PC-Tools Selbsttest' 'Einstellungen' 'selbsttest stabilität fehler diagnose vorversion zurück rollback lite ansicht update verzögerung' '&#xE9D9;' { $ui.Tabs.SelectedItem = $ui.TabSettings; Start-SelfTest }
Add-SearchEntry 'Lite-Ansicht umschalten' 'Einstellungen' 'lite einfach weniger seiten voll ansicht' '&#xE8A9;' { $ui.Tabs.SelectedItem = $ui.TabSettings }







# ================================================================ PC-Tools 10.0 (Oberfläche)
# ---------------------------------------------------------------- Komplettsicherung (Oberfläche)
$script:FbLoaded = $false; $script:FbBusy = $false; $script:FbData = $null; $script:FbLastRefresh = [datetime]::MinValue
$script:FbMount = $null; $script:FbIncBoxes = @(); $script:FbHistRows = @(); $script:FbIncBuilt = ''
$RunButtons = @($RunButtons) + @('BtnFbRun', 'BtnFbVerify', 'BtnFbVerifyDeep', 'BtnFbPrune', 'BtnFbPkgWrite', 'BtnFbStick')

# Geplante Aufgabe "PC-Tools Komplettsicherung" (eigene Aufgabe, als SYSTEM; Aufruf PCPflege.ps1 -FullBackup)
function Register-FbTask($Cfg) {
    if ($Script:IsPortable) { return '' }
    $F = $Cfg.FullBackup
    if (-not $F -or -not $F.Enabled -or -not [string]$F.Target) { Unregister-ScheduledTask -TaskName $FbTaskName -Confirm:$false -ErrorAction SilentlyContinue; return '' }
    $t = ConvertTo-FbTarget ([string]$F.Target)
    if (-not $t.Valid) { throw 'Komplettsicherung: Das Ziel ist kein Laufwerk (E:) und keine Freigabe (\\Server\Freigabe).' }
    Sync-PflegeFiles
    $o = @{ Frequency = [string]$F.Frequency; Day = [string]$F.Day; Time = [string]$F.Time; MonthWeek = [string]$F.MonthWeek; WakeToRun = [bool]$F.WakeToRun; OnlyAc = [bool]$F.OnlyAc
        Retry = [bool]$F.Retry; CatchUp = [bool]$F.CatchUp; Network = [bool]$t.IsNas; Command = $PsExe; Arguments = (Get-PsArgString (Join-Path $DataDir 'PCPflege.ps1') @('-FullBackup')) }
    $xml = Get-FbTaskXml $o
    Register-ScheduledTask -TaskName $FbTaskName -Xml $xml -Force -ErrorAction Stop | Out-Null
    return ' Komplettsicherung eingeplant (' + (Get-FbScheduleText $F) + ').'
}
function Get-FbUiParams([bool]$WithVersions = $true) {
    $k = 0; [void][int]::TryParse(([string]$ui.FullBackup_Keep.Text).Trim(), [ref]$k)
    $fq = $(if ($ui.FullBackup_Frequency.SelectedItem) { [string]$ui.FullBackup_Frequency.SelectedItem.Content } else { 'Wöchentlich' })
    @{ Target = $ui.FullBackup_Target.Text.Trim(); Include = $ui.FullBackup_Include.Text.Trim(); NasVersions = [bool]$ui.FullBackup_NasVersions.IsChecked; Keep = $k
        CredFile = (Join-Path $DataDir 'fullbackup.cred'); AltCredFile = (Join-Path $DataDir 'backup.cred'); HistDir = (Join-Path $DataDir 'Komplettsicherung')
        IntervalDays = (Get-FbIntervalDays $fq); TaskName = $FbTaskName; PkgFolder = $FbPkgFolder; NasFolder = $FbNasFolder; Machine = $env:COMPUTERNAME; WithVersions = $WithVersions }
}
function Update-FbStatus([switch]$NoVersions) {
    if ($script:FbBusy) { return }
    $script:FbBusy = $true; $script:FbLastRefresh = Get-Date
    $ui.BtnFbRefresh.IsEnabled = $false
    if (-not $script:FbData) { $ui.FbHeroTitle.Text = 'Komplettsicherung wird gelesen ...' }
    $ui.FbVerInfo.Text = $(if ($NoVersions) { '' } else { 'Versionen am Ziel werden gelesen (wbadmin get versions) ...' })
    $p = Get-FbUiParams (-not $NoVersions)
    Invoke-Bg -Script { param($pp) Get-FbStatusData $pp } -Arguments @(, $p) -Functions $FbBgFunctions -Done {
        param($r, $err)
        $script:FbBusy = $false; $ui.BtnFbRefresh.IsEnabled = $true
        if ($err) { $ui.FbHeroTitle.Text = 'Status nicht lesbar'; $ui.FbHeroSub.Text = $err.Message; return }
        $d = @($r | Where-Object { $_ -and $_.PSObject.Properties['Usage'] }) | Select-Object -Last 1
        if (-not $d) { $ui.FbHeroTitle.Text = 'Status nicht lesbar'; return }
        if (-not $d.Versions -and $script:FbData -and $script:FbData.Versions -and ([string]$script:FbData.Target.Target -eq [string]$d.Target.Target)) { $d.Versions = $script:FbData.Versions }
        $script:FbData = $d
        try { Show-FbStatus $d } catch { $ui.StatusText.Text = 'Komplettsicherung: ' + $_.Exception.Message }
    }
}
function Format-FbAge($Days) {
    if ($null -eq $Days) { return 'noch nie' }
    $dd = [double]$Days
    if ($dd -lt (1.0 / 24)) { return 'gerade eben' }
    if ($dd -lt 1) { return ('vor {0:N0} Std.' -f ($dd * 24)) }
    if ($dd -lt 2) { return 'gestern' }
    return ('vor {0:N0} Tagen' -f [math]::Floor($dd))
}
function Add-FbChip($Panel, [string]$Text) {
    $b = New-Object Windows.Controls.Border; $b.CornerRadius = '12'; $b.Padding = '11,4'; $b.Margin = '0,0,8,6'
    $b.Background = (New-Object Windows.Media.BrushConverter).ConvertFromString('#33FFFFFF')
    $t = New-Object Windows.Controls.TextBlock; $t.Text = $Text; $t.FontSize = 12; $t.Foreground = [Windows.Media.Brushes]::White
    $b.Child = $t; [void]$Panel.Children.Add($b)
}
function Add-FbLevelRow($Panel, [string]$Level, [string]$Text) {
    $g = New-Object Windows.Controls.Grid; $g.Margin = '0,2'
    foreach ($w in 20, -1) { $c = New-Object Windows.Controls.ColumnDefinition; if ($w -gt 0) { $c.Width = $w }; [void]$g.ColumnDefinitions.Add($c) }
    $col = switch ($Level) { 'ok' { '#16A34A' } 'warn' { '#EA580C' } 'bad' { '#DC2626' } default { '#2D7FF9' } }
    $gl = switch ($Level) { 'ok' { [string][char]0xE73E } 'warn' { [string][char]0xE7BA } 'bad' { [string][char]0xE711 } default { [string][char]0xE946 } }
    $i = New-Object Windows.Controls.TextBlock; $i.Text = $gl; $i.FontFamily = 'Segoe MDL2 Assets'; $i.FontSize = 12; $i.Margin = '0,3,0,0'; $i.Foreground = New-UiBrush $col
    $t = New-Object Windows.Controls.TextBlock; $t.Text = $Text; $t.TextWrapping = 'Wrap'; $t.FontSize = 12.5; $t.Foreground = New-UiBrush '#1F2A44'
    [Windows.Controls.Grid]::SetColumn($t, 1)
    [void]$g.Children.Add($i); [void]$g.Children.Add($t); [void]$Panel.Children.Add($g)
}
function Get-FbIncludeList { @(([string]$ui.FullBackup_Include.Text) -split '[;, ]' | ForEach-Object { $_.Trim().TrimEnd('\').ToUpper() } | Where-Object { $_ -match '^[A-Z]:$' } | Select-Object -Unique) }
# Bewertung und Schätzung neu (ohne Hintergrund-Lesen: nur aus den zuletzt gelesenen Daten)
function Update-FbVerdictUi {
    $d = $script:FbData; if (-not $d) { return }
    $inc = @(Get-FbIncludeList)
    $est = Measure-FbEstimate $d.Usage $inc
    $ui.FbVerdict.Children.Clear()
    $k = 0; [void][int]::TryParse(([string]$ui.FullBackup_Keep.Text).Trim(), [ref]$k)
    $tgtNow = ConvertTo-FbTarget $ui.FullBackup_Target.Text
    if ($d.Target -and ([string]$d.Target.Target -ne [string]$tgtNow.Path)) { Add-FbLevelRow $ui.FbVerdict 'info' 'Das Ziel wurde geändert - "Ziel prüfen" liest es neu ein.' }
    foreach ($v in @(Get-FbTargetVerdict $d.Target $est.Bytes ([bool]$ui.FullBackup_NasVersions.IsChecked) $k $inc | ForEach-Object { $_ })) { Add-FbLevelRow $ui.FbVerdict $v.Level $v.Text }
    $ui.FbEstimate.Text = 'Geschätzte Größe des Abbilds: {0} ({1}). Die erste Sicherung kopiert alles (bei USB 3 etwa 20-40 Minuten je 100 GB), danach speichert Windows auf Festplatten nur noch die Änderungen.' -f (Format-FbBytes $est.Bytes), (@($est.Names) -join ', ')
    return $est
}
function Update-FbIncludeUi($Usage) {
    $tg = ConvertTo-FbTarget $ui.FullBackup_Target.Text
    $cand = @(@($Usage) | Where-Object { $_.Letter -and $_.Kind -eq 'Daten' -and [string]$_.Fs -in 'NTFS', 'ReFS' -and [string]$_.BusType -ne 'USB' -and [string]$_.DriveType -ne 'Removable' -and $_.Letter -ne $tg.Path })
    $sig = (@($cand | ForEach-Object { $_.Letter }) -join ',') + '|' + $tg.Path
    if ($sig -eq $script:FbIncBuilt) { return }
    $script:FbIncBuilt = $sig
    $ui.FbIncludePanel.Children.Clear(); $script:FbIncBoxes = @()
    $sel = @(Get-FbIncludeList)
    if (-not $cand.Count) { $t = New-Object Windows.Controls.TextBlock; $t.Text = 'Keine weiteren internen NTFS-Laufwerke vorhanden.'; $t.Foreground = New-UiBrush '#6B7890'; $t.FontSize = 12; [void]$ui.FbIncludePanel.Children.Add($t); return }
    foreach ($c in $cand) {
        $cb = New-Object Windows.Controls.CheckBox; $cb.Margin = '0,3,18,3'; $cb.Tag = [string]$c.Letter
        $cb.Content = '{0} {1}  ({2} belegt, {3})' -f $c.Letter, $(if ($c.Label) { '"' + $c.Label + '"' } else { '' }), (Format-FbBytes $c.Used), $(if ($c.DiskName) { $c.DiskName } else { $c.Fs })
        $cb.IsChecked = ($sel -contains [string]$c.Letter)
        $cb.Add_Click({ $ui.FullBackup_Include.Text = (@($script:FbIncBoxes | Where-Object { $_.IsChecked } | ForEach-Object { [string]$_.Tag }) -join ';'); try { $null = Update-FbVerdictUi } catch { } })
        [void]$ui.FbIncludePanel.Children.Add($cb); $script:FbIncBoxes += $cb
    }
}
function Show-FbStatus($d) {
    $s = $d.Summary; $last = $(if ($s) { $s.Last } else { $null }); $ok = $(if ($s) { $s.LastOk } else { $null })
    $okEnd = $(if ($ok) { ConvertTo-FbDate $ok.End } else { $null })
    $cfgOn = [bool]$ui.FullBackup_Enabled.IsChecked
    $tgt = $d.Target
    # ---- Kopf
    $state = $(if ($s) { [string]$s.State } else { 'never' })
    $ui.FbHeroGlyph.Text = $(switch ($state) { 'ok' { [string][char]0xE73E } 'due' { [string][char]0xE823 } 'overdue' { [string][char]0xE7BA } default { [string][char]0xE78C } })
    $ui.FbHeroTitle.Text = $(switch ($state) { 'ok' { 'Komplettsicherung ist aktuell' } 'due' { 'Komplettsicherung ist bald fällig' } 'overdue' { 'Komplettsicherung ist überfällig' } default { 'Noch keine Komplettsicherung' } })
    if ($s -and $s.Failed) { $ui.FbHeroTitle.Text += ' - letzter Lauf fehlgeschlagen' }
    if ($okEnd) {
        $ui.FbHeroSub.Text = 'Letzte erfolgreiche Sicherung am {0:dd.MM.yyyy} um {0:HH:mm} Uhr auf {1}: {2}, {3:N0} Minuten, {4}.' -f $okEnd, [string]$ok.Target, (Format-FbBytes ([double]$ok.Bytes)), [double]$ok.Minutes, $(if ($ok.Verify) { [string]$ok.Verify } else { 'nicht geprüft' })
        if ($s.Failed -and $last.Message) { $ui.FbHeroSub.Text += ' Letzter Versuch: ' + [string]$last.Message }
        $age = [double]$s.AgeDays
        if ($age -lt 1) { $ui.FbHeroAge.Text = '{0:N0}' -f [math]::Max([double]0, $age * 24); $ui.FbHeroAgeUnit.Text = 'Stunden alt' } else { $ui.FbHeroAge.Text = '{0:N0}' -f [math]::Floor($age); $ui.FbHeroAgeUnit.Text = $(if ([math]::Floor($age) -eq 1) { 'Tag alt' } else { 'Tage alt' }) }
    } else {
        $ui.FbHeroSub.Text = $(if (-not $tgt -or -not $tgt.Valid) { 'Unten ein Sicherungsziel wählen (externe Festplatte oder NAS), dann "Jetzt komplett sichern". Danach am besten einen Zeitplan einschalten und ein Wiederherstellungsmedium bereitlegen.' } elseif ($last) { 'Bisher hat keine Sicherung geklappt. Letzter Versuch: ' + [string]$last.Message } else { 'Ziel ist eingestellt - "Jetzt komplett sichern" erstellt das erste Abbild.' })
        $ui.FbHeroAge.Text = '-'; $ui.FbHeroAgeUnit.Text = 'noch keine Sicherung'
    }
    $ui.FbHeroChips.Children.Clear()
    Add-FbChip $ui.FbHeroChips ('Ziel: ' + $(if ($tgt -and $tgt.Valid) { [string]$tgt.Target + $(if ($tgt.Exists) { '' } else { ' (nicht erreichbar)' }) } else { 'nicht gewählt' }))
    Add-FbChip $ui.FbHeroChips ('Zeitplan: ' + $(if ($d.Task) { $(if ($d.Task.Next) { 'nächster Lauf ' + ([datetime]$d.Task.Next).ToString('dd.MM. HH:mm') } else { [string]$d.Task.State }) } elseif ($cfgOn) { 'noch nicht gespeichert' } else { 'aus' }))
    if ($d.Versions -and $d.Versions.Ok) { Add-FbChip $ui.FbHeroChips ('{0} Version(en) am Ziel' -f @($d.Versions.Rows).Count) }
    Add-FbChip $ui.FbHeroChips ('Paket: ' + $(if ($d.Package -and $d.Package.Ok) { 'vorhanden' } elseif ($d.Package -and $d.Package.Exists) { 'unvollständig' } else { 'fehlt' }))
    $st = @($d.Sticks)
    Add-FbChip $ui.FbHeroChips ('Notfall-Stick: ' + $(if (-not $st.Count) { 'nicht eingesteckt' } elseif (@($st | Where-Object { $_.Outdated }).Count) { 'veraltet' } else { 'aktuell' }))
    # ---- Kennzahlen
    $ui.FbKLast.Text = $(if ($last) { $le = ConvertTo-FbDate $last.Start; $(if ($le) { '{0:dd.MM.yyyy HH:mm} ({1})' -f $le, (Format-FbAge ((Get-Date) - $le).TotalDays) } else { '-' }) } else { 'noch nie' })
    $ui.FbKResult.Text = $(if ($last) { [string]$last.Result + $(if ($last.Verify) { ', ' + [string]$last.Verify } else { '' }) } else { '-' })
    $ui.FbKResult.Foreground = New-UiBrush $(if (-not $last) { '#1F2A44' } elseif ([string]$last.Result -eq 'OK') { '#16A34A' } elseif ([string]$last.Result -eq 'Fehler') { '#DC2626' } elseif ([string]$last.Result -eq 'Warnung') { '#EA580C' } else { '#6B7890' })
    $ui.FbKSize.Text = $(if ($ok -and [double]$ok.Bytes -gt 0) { Format-FbBytes ([double]$ok.Bytes) } elseif ($d.Estimate) { '~' + (Format-FbBytes $d.Estimate.Bytes) + ' (geschätzt)' } else { '-' })
    $ui.FbKDuration.Text = $(if ($ok) { '{0:N0} Minuten' -f [double]$ok.Minutes } else { '-' })
    $ui.FbKNext.Text = $(if ($d.Task -and $d.Task.Next) { ([datetime]$d.Task.Next).ToString('ddd dd.MM. HH:mm') } elseif ($d.Task) { 'Aufgabe ' + [string]$d.Task.State } else { 'kein Zeitplan' })
    $ui.FbKFree.Text = $(if ($tgt -and $tgt.Exists -and [int64]$tgt.Free -ge 0) { '{0} von {1}' -f (Format-FbBytes $tgt.Free), (Format-FbBytes $tgt.Size) } elseif ($tgt -and $tgt.Valid) { 'nicht erreichbar' } else { '-' })
    $ui.FbKVersions.Text = $(if ($d.Versions -and $d.Versions.Ok) { [string]@($d.Versions.Rows).Count } elseif ($d.Versions -and $d.Versions.Error) { '?' } else { '-' })
    $ui.FbKMedia.Text = 'Paket {0} · Stick {1}' -f $(if ($d.Package -and $d.Package.Ok) { 'ok' } else { 'fehlt' }), $(if (-not $st.Count) { 'fehlt' } elseif (@($st | Where-Object { $_.Outdated }).Count) { 'veraltet' } else { 'ok' })
    # ---- Ziel, Laufwerke, Bewertung
    $ui.FbDriveCombo.Items.Clear()
    $sysL = ([string]$env:SystemDrive).ToUpper()
    foreach ($u in @(@($d.Usage) | Where-Object { $_.Letter -and $_.Letter -ne $sysL -and $_.Kind -eq 'Daten' } | Sort-Object Letter)) {
        $ci = New-Object Windows.Controls.ComboBoxItem
        $ci.Content = '{0}  {1}  -  {2}, {3}, {4} frei von {5}{6}' -f $u.Letter, $(if ($u.Label) { '"' + $u.Label + '"' } else { '' }), $(if ($u.Fs) { $u.Fs } else { 'ohne Dateisystem' }), $(if ($u.BusType -eq 'USB') { 'USB' } elseif ($u.BusType) { 'intern (' + $u.BusType + ')' } else { 'Laufwerk' }), (Format-FbBytes $u.Free), (Format-FbBytes $u.Size), $(if ($u.OnSystemDisk) { '  - gleiche Festplatte wie Windows!' } elseif ([string]$u.Fs -notin 'NTFS', 'ReFS') { '  - nicht geeignet (kein NTFS)' } else { '' })
        $ci.Tag = [string]$u.Letter
        [void]$ui.FbDriveCombo.Items.Add($ci)
    }
    if ($ui.FbDriveCombo.Items.Count) { $ui.FbDriveCombo.SelectedIndex = 0 } else { $ci = New-Object Windows.Controls.ComboBoxItem; $ci.Content = 'Keine weitere Festplatte angeschlossen'; $ci.IsEnabled = $false; [void]$ui.FbDriveCombo.Items.Add($ci) }
    Update-FbIncludeUi $d.Usage
    $ui.FbCritList.Children.Clear()
    foreach ($u in @(@($d.Usage) | Where-Object { $_.Critical })) {
        $nm = $(if ($u.Letter) { '{0} {1}' -f $u.Letter, $(if ($u.Kind -eq 'System') { 'Windows' } else { $u.Label }) } else { switch ($u.Kind) { 'EFI' { 'EFI-Systempartition' } 'Wiederherstellung' { 'Wiederherstellungspartition' } default { 'System-reserviert' } } })
        Add-FbLevelRow $ui.FbCritList 'ok' ('{0}: {1} belegt, davon etwa {2} im Abbild' -f $nm, (Format-FbBytes $u.Used), (Format-FbBytes $u.Est))
    }
    $null = Update-FbVerdictUi
    foreach ($e in @($d.Errors)) { Add-FbLevelRow $ui.FbVerdict 'warn' $e }
    # ---- Versionen
    if ($d.Versions) {
        if ($d.Versions.Ok) {
            Set-GridItems $ui.FbVerGrid @($d.Versions.Rows)
            $vf = @($d.Versions.Rows | Where-Object { $_.Folder }).Count
            $ui.FbVerInfo.Text = '{0} Version(en) am Ziel, {1} davon als eigener Ordner (einzeln einbindbar). Stand {2:HH:mm} Uhr.' -f @($d.Versions.Rows).Count, $vf, (Get-Date)
        } else { Set-GridItems $ui.FbVerGrid @(); $ui.FbVerInfo.Text = [string]$d.Versions.Error }
    } elseif ($tgt -and $tgt.Valid -and -not $tgt.Exists) { $ui.FbVerInfo.Text = 'Ziel nicht erreichbar - Versionen können nicht gelesen werden.' }
    # ---- Medien
    $ui.FbPkgState.Text = $(if ($d.Package) { [string]$d.Package.Text } elseif ($tgt -and $tgt.Exists) { 'Noch kein Wiederherstellungspaket am Ziel.' } else { 'Ziel nicht erreichbar.' })
    $ui.FbStickState.Text = $(if (-not $st.Count) { 'Kein Notfall-Stick (PCT-NOTFALL) eingesteckt. Einen Stick ab 8 GB einstecken und "erstellen/aktualisieren" - oder auf der Seite Notfall-Stick einrichten.' } else { (@($st | ForEach-Object { '{0} {1}: {2}{3}' -f $_.Root, $_.Name, $_.Reason, $(if ($_.Outdated) { ' - bitte aktualisieren' } else { '' }) }) -join "`n") })
    # ---- Zeitplan
    $ui.FbTaskInfo.Text = $(if ($d.Task) { 'Geplante Aufgabe: {0}, nächster Lauf {1}, letzter Lauf {2}{3}' -f $(if ($d.Task.State -eq 'Disabled') { 'deaktiviert' } else { 'aktiv' }), $(if ($d.Task.Next) { ([datetime]$d.Task.Next).ToString('dd.MM.yyyy HH:mm') } else { '-' }), $(if ($d.Task.Last) { ([datetime]$d.Task.Last).ToString('dd.MM.yyyy HH:mm') } else { 'noch nie' }), $(if ($d.Task.Last -and [int64]$d.Task.LastResult -ne 0) { ' (Code 0x{0:X})' -f [int64]$d.Task.LastResult } else { '' }) } elseif ($cfgOn) { 'Zeitplan eingeschaltet, aber noch nicht gespeichert - "Einstellungen und Zeitplan speichern".' } else { 'Kein Zeitplan - die Komplettsicherung läuft nur von Hand.' })
    # ---- Verlauf und Zeitleiste
    $rows = [System.Collections.Generic.List[object]]::new()
    foreach ($e in @(@($d.History) | Select-Object -Last 80)) {
        $sd = ConvertTo-FbDate $e.Start
        $rows.Insert(0, [pscustomobject]@{ StartText = $(if ($sd) { $sd.ToString('dd.MM.yyyy HH:mm') } else { '-' }); Result = [string]$e.Result; DurText = $(if ([double]$e.Minutes -gt 0) { '{0:N0} Min.' -f [double]$e.Minutes } else { '-' })
            SizeText = $(if ([double]$e.Bytes -gt 0) { Format-FbBytes ([double]$e.Bytes) } else { '-' }); Target = [string]$e.Target; Verify = [string]$e.Verify; Message = [string]$e.Message; Raw = $e })
    }
    $script:FbHistRows = @($rows)
    Set-GridItems $ui.FbHistGrid @($rows)
    Show-FbHelp $(if ($last -and [string]$last.Result -in 'Fehler', 'Warnung') { $last } else { $null })
    Update-FbTimeline
}
function Show-FbHelp($Entry) {
    $ui.FbHelpList.Children.Clear()
    if (-not $Entry -or [string]$Entry.Result -notin 'Fehler', 'Warnung', 'Übersprungen') { $ui.FbHelpBox.Visibility = 'Collapsed'; return }
    $txt = ([string]$Entry.Message) + ' ' + (@($Entry.Codes) -join ' ')
    try { if ($Entry.Log -and (Test-Path -LiteralPath ([string]$Entry.Log))) { $txt += "`n" + ((Get-Content -LiteralPath ([string]$Entry.Log) -Encoding UTF8 -ErrorAction Stop | Where-Object { $_ -match '0x[0-9A-Fa-f]{8}|\[(WARN|FEHLER)' } | Select-Object -Last 40) -join "`n") } } catch { }
    $help = @(Get-FbErrorHelp $txt $FbErrorCatalog | ForEach-Object { $_ })
    $sd = ConvertTo-FbDate $Entry.Start
    $ui.FbHelpTitle.Text = 'Sicherung vom {0}: {1} - {2}' -f $(if ($sd) { $sd.ToString('dd.MM.yyyy HH:mm') } else { '?' }), [string]$Entry.Result, $(if ($Entry.Message) { [string]$Entry.Message } else { 'keine Meldung' })
    if (-not $help.Count) { $help = @([pscustomobject]@{ Code = ''; Title = 'Was tun?'; Fix = 'Das Protokoll des Laufs ("Protokoll des Laufs öffnen") zeigt die genaue Meldung der Windows-Sicherung. Häufig hilft: Ziel prüfen, PC neu starten, erneut sichern. Die Ereignisanzeige (Anwendungs- und Dienstprotokolle > Microsoft > Windows > Backup) nennt die Ursache.' }) }
    foreach ($h in $help) {
        $sp = New-Object Windows.Controls.StackPanel; $sp.Margin = '0,4,0,4'
        $t1 = New-Object Windows.Controls.TextBlock; $t1.Text = [string]$h.Title + $(if ($h.Code) { '  (' + $h.Code + ')' } else { '' }); $t1.FontWeight = 'SemiBold'; $t1.Foreground = New-UiBrush '#1F2A44'; $t1.TextWrapping = 'Wrap'
        $t2 = New-Object Windows.Controls.TextBlock; $t2.Text = [string]$h.Fix; $t2.FontSize = 12.5; $t2.Foreground = New-UiBrush '#475569'; $t2.TextWrapping = 'Wrap'
        [void]$sp.Children.Add($t1); [void]$sp.Children.Add($t2); [void]$ui.FbHelpList.Children.Add($sp)
    }
    $ui.FbHelpBox.Visibility = 'Visible'
}
# Zeitleiste der letzten 12 Sicherungen (Balkenhöhe = Größe, Farbe = Ergebnis)
function Update-FbTimeline {
    $cv = $ui.FbTimeline; $cv.Children.Clear()
    $W = [double]$cv.ActualWidth; $H = [double]$cv.ActualHeight
    if ($W -lt 50) { return }
    if ($H -lt 50) { $H = 150 }
    $hist = @(); if ($script:FbData) { $hist = @(@($script:FbData.History) | Where-Object { $_ } | Select-Object -Last 12) }
    $base = New-Object Windows.Shapes.Line; $base.X1 = 0; $base.X2 = $W; $base.Y1 = $H - 22; $base.Y2 = $H - 22; $base.Stroke = New-UiBrush '#CBD5E1'; $base.StrokeThickness = 1
    [void]$cv.Children.Add($base)
    if (-not $hist.Count) {
        $t = New-Object Windows.Controls.TextBlock; $t.Text = 'Noch keine Sicherung - die Zeitleiste füllt sich mit jedem Lauf.'; $t.Foreground = New-UiBrush '#6B7890'
        [Windows.Controls.Canvas]::SetLeft($t, 12); [Windows.Controls.Canvas]::SetTop($t, ($H / 2) - 18); [void]$cv.Children.Add($t)
        $ui.FbTimelineInfo.Text = ''
        return
    }
    $max = [double]1; foreach ($e in $hist) { if ([double]$e.Bytes -gt $max) { $max = [double]$e.Bytes } }
    if ($script:FbData.Estimate -and [double]$script:FbData.Estimate.Bytes -gt $max) { $max = [double]$script:FbData.Estimate.Bytes }
    $slot = $W / 12; $bw = [math]::Min([double]46, $slot * 0.62); $top = 18; $avail = $H - 22 - $top
    $i = 12 - $hist.Count
    foreach ($e in $hist) {
        $res = [string]$e.Result
        $col = switch ($res) { 'OK' { '#16A34A' } 'Warnung' { '#EA580C' } 'Fehler' { '#DC2626' } default { '#94A3B8' } }
        $bytes = [double]$e.Bytes
        $bh = $(if ($bytes -gt 0) { [math]::Max([double]8, $avail * $bytes / $max) } else { [double]14 })
        $x = $i * $slot + ($slot - $bw) / 2
        $r = New-Object Windows.Shapes.Rectangle; $r.Width = $bw; $r.Height = $bh; $r.RadiusX = 5; $r.RadiusY = 5
        $r.Fill = New-UiBrush $col
        if ($bytes -le 0) { $r.Opacity = 0.55 }
        $sd = ConvertTo-FbDate $e.Start
        $r.ToolTip = '{0}  -  {1}{2}{3}{4}{5}' -f $(if ($sd) { $sd.ToString('dd.MM.yyyy HH:mm') } else { '?' }), $res, $(if ($bytes -gt 0) { ', ' + (Format-FbBytes $bytes) } else { '' }), $(if ([double]$e.Minutes -gt 0) { (', {0:N0} Min.' -f [double]$e.Minutes) } else { '' }), $(if ($e.Verify) { ', ' + [string]$e.Verify } else { '' }), $(if ($e.Message) { "`n" + [string]$e.Message } else { '' })
        [Windows.Controls.Canvas]::SetLeft($r, $x); [Windows.Controls.Canvas]::SetTop($r, $H - 22 - $bh)
        [void]$cv.Children.Add($r)
        if ($res -in 'Fehler', 'Abgebrochen', 'Übersprungen' -and $bytes -le 0) {
            $m = New-Object Windows.Controls.TextBlock; $m.Text = $(if ($res -eq 'Fehler') { '!' } else { '–' }); $m.FontWeight = 'Bold'; $m.Foreground = [Windows.Media.Brushes]::White; $m.FontSize = 11
            [Windows.Controls.Canvas]::SetLeft($m, $x + $bw / 2 - 3); [Windows.Controls.Canvas]::SetTop($m, $H - 22 - $bh - 1); $m.IsHitTestVisible = $false; [void]$cv.Children.Add($m)
        }
        if ($bytes -gt 0 -and $slot -ge 52) {
            $v = New-Object Windows.Controls.TextBlock; $v.Text = $(if ($bytes -ge 1TB) { '{0:N1}T' -f ($bytes / 1TB) } else { '{0:N0}G' -f ($bytes / 1GB) }); $v.FontSize = 10.5; $v.Foreground = New-UiBrush '#475569'
            [Windows.Controls.Canvas]::SetLeft($v, $x); [Windows.Controls.Canvas]::SetTop($v, $H - 22 - $bh - 15); [void]$cv.Children.Add($v)
        }
        $l = New-Object Windows.Controls.TextBlock; $l.Text = $(if ($sd) { $sd.ToString('dd.MM.') } else { '?' }); $l.FontSize = 10.5; $l.Foreground = New-UiBrush '#6B7890'
        [Windows.Controls.Canvas]::SetLeft($l, $i * $slot + ($slot / 2) - 15); [Windows.Controls.Canvas]::SetTop($l, $H - 18); [void]$cv.Children.Add($l)
        $i++
    }
    $okc = @($hist | Where-Object { [string]$_.Result -in 'OK', 'Warnung' }).Count
    $ui.FbTimelineInfo.Text = '{0} von {1} Läufen erfolgreich. Balkenhöhe = Größe des Abbilds, Maus darüber zeigt Details.' -f $okc, $hist.Count
}
function Get-FbSelectedVhdx {
    $d = $script:FbData
    $row = $ui.FbVerGrid.SelectedItem
    $folder = ''
    if ($row) {
        if (-not $row.Folder) { throw ('Die Version vom {0} liegt nur als Schattenkopie am Ziel und lässt sich nicht direkt einbinden. Einzelne Dateien daraus holt "wbadmin start recovery -version:{1} -itemType:File" bzw. die Systemimage-Wiederherstellung - oder die neueste Version einbinden.' -f $row.DateText, $row.Version) }
        $folder = [string]$row.Folder
    } elseif ($d -and $d.Versions -and @($d.Versions.Folders).Count) { $folder = [string]@($d.Versions.Folders)[0].Folder }
    if (-not $folder) { throw 'Keine Sicherung gefunden - erst "Versionen lesen" (Ziel angeschlossen?).' }
    $vh = @(Get-ChildItem -LiteralPath $folder -File -ErrorAction Stop | Where-Object { $_.Extension -in '.vhdx', '.vhd' } | Sort-Object Length -Descending)
    if (-not $vh.Count) { throw ('Im Ordner {0} liegt keine Abbild-Datei (.vhdx).' -f $folder) }
    $big = @($vh | Where-Object { $_.Length -gt 1GB })
    if ($big.Count -gt 1) {
        $items = @($big | ForEach-Object { '{0}  ({1})' -f $_.Name, (Format-FbBytes $_.Length) })
        $a = Show-InputDialog 'Abbild-Datei wählen' 'Die Sicherung enthält mehrere Laufwerke (je eine Datei). Die größte ist meist C:. Welche soll eingebunden werden?' @(@{ Key = 'F'; Label = 'Abbild-Datei'; Type = 'Combo'; Items = $items })
        if (-not $a) { return '' }
        $ix = [array]::IndexOf($items, [string]$a.F); if ($ix -lt 0) { $ix = 0 }
        return [string]$big[$ix].FullName
    }
    return [string]$vh[0].FullName
}
function Start-FbMount {
    if ($script:FbMount) { Show-UiError 'Es ist schon ein Abbild eingebunden - erst "Abbild wieder trennen".'; return }
    $vhd = Get-FbSelectedVhdx
    if (-not $vhd) { return }
    $md = Join-Path $DataDir 'Komplettsicherung'
    $ui.FbMountInfo.Text = 'Abbild wird schreibgeschützt eingebunden: {0} ...' -f $vhd
    $ui.BtnFbMount.IsEnabled = $false
    Invoke-Bg -Script { param($v, $m) Mount-FbVhd $v $m } -Arguments @($vhd, $md) -Functions $FbBgFunctions -Done {
        param($r, $err)
        $ui.BtnFbMount.IsEnabled = $true
        if ($err) { $ui.FbMountInfo.Text = 'Einbinden fehlgeschlagen: ' + $err.Message; return }
        $m = @($r | Where-Object { $_ -and $_.PSObject.Properties['Roots'] }) | Select-Object -Last 1
        if (-not $m) { $ui.FbMountInfo.Text = 'Einbinden fehlgeschlagen.'; return }
        $script:FbMount = $m; $ui.BtnFbUnmount.IsEnabled = $true
        if ($m.Error) { $ui.FbMountInfo.Text = 'Eingebunden, aber: ' + $m.Error + ' - "Abbild wieder trennen" nicht vergessen.'; return }
        $root = @($m.Roots | Where-Object { Test-Path -LiteralPath (Join-Path $_ 'Users') }) | Select-Object -First 1
        if (-not $root) { $root = @($m.Roots)[0] }
        $ui.FbMountInfo.Text = 'Abbild schreibgeschützt eingebunden als {0}. Dateien im Explorer herauskopieren (z.B. {1}Users\<Name>\Documents) und danach "Abbild wieder trennen".' -f (@($m.Roots) -join ', '), $root
        try { Start-Process explorer.exe -ArgumentList ('"{0}"' -f $root) } catch { }
    }
}
function Stop-FbMount([switch]$Quiet) {
    $m = $script:FbMount; if (-not $m) { return }
    if ($Quiet) { try { $null = Dismount-FbVhd ([string]$m.Path) @($m.AccessPaths) } catch { }; $script:FbMount = $null; return }
    $ui.BtnFbUnmount.IsEnabled = $false; $ui.FbMountInfo.Text = 'Abbild wird getrennt ...'
    Invoke-Bg -Script { param($p, $a) Dismount-FbVhd $p $a } -Arguments @([string]$m.Path, @($m.AccessPaths)) -Functions $FbBgFunctions -Done {
        param($r, $err)
        if ($err) { $ui.FbMountInfo.Text = 'Trennen fehlgeschlagen: ' + $err.Message + ' - Explorer-Fenster auf dem Abbild schließen und erneut versuchen (oder Datenträgerverwaltung > Virtuelle Festplatte trennen).'; $ui.BtnFbUnmount.IsEnabled = $true; return }
        $script:FbMount = $null; $ui.FbMountInfo.Text = 'Abbild getrennt.'
    }
}
function Start-FbRun {
    $cfg = Get-ConfigFromUi
    $t = ConvertTo-FbTarget ([string]$cfg.FullBackup.Target)
    if (-not $t.Valid) { Show-UiError 'Bitte zuerst ein Sicherungsziel eintragen: Laufwerksbuchstabe einer externen NTFS-Festplatte (z.B. E:) oder eine NAS-Freigabe (\\Server\Freigabe).'; return }
    $d = $script:FbData
    $bad = @()
    if ($d -and $d.Target -and [string]$d.Target.Target -eq $t.Path) {
        $est = Measure-FbEstimate $d.Usage @(Get-FbIncludeList)
        $bad = @(Get-FbTargetVerdict $d.Target $est.Bytes ([bool]$cfg.FullBackup.NasVersions) ([int]$cfg.FullBackup.Keep) @(Get-FbIncludeList) | ForEach-Object { $_ } | Where-Object { $_.Level -eq 'bad' })
    }
    if ($bad.Count) {
        if (-not (Confirm-Ui ("Das Ziel {0} ist so nicht geeignet:`n`n{1}`n`nTrotzdem versuchen? (Die Sicherung prüft das Ziel noch einmal und bricht ab, wenn es nicht geht.)" -f $t.Path, (($bad | ForEach-Object { '- ' + $_.Text }) -join "`n")) 'Warning')) { return }
    } else {
        $sz = $(if ($d -and $d.Estimate) { ' (etwa ' + (Format-FbBytes (Measure-FbEstimate $d.Usage @(Get-FbIncludeList)).Bytes) + ')' } else { '' })
        if (-not (Confirm-Ui ("Komplettsicherung jetzt starten?`n`nZiel: {0}{1}`nDie Sicherung läuft im Hintergrund weiter, auch wenn das Fenster geschlossen wird. Die erste Sicherung dauert je nach Größe 30 Minuten bis einige Stunden; der PC kann währenddessen benutzt werden." -f $t.Path, $sz))) { return }
    }
    Start-Run -Parts @('FullBackup') -Job @{ Manual = $true }
}
function Start-FbStickUpdate {
    $sticks = @(Find-FbRescueSticks | ForEach-Object { $_ })
    if (-not $sticks.Count) {
        if (Confirm-Ui "Es ist kein Notfall-Stick (Bezeichnung PCT-NOTFALL) eingesteckt.`n`nEinen neuen Stick richtet die Seite Notfall-Stick ein (der Stick wird dabei gelöscht). Jetzt dorthin wechseln?") { $ui.Tabs.SelectedItem = $ui.TabRescue }
        return
    }
    $s = $sticks[0]
    if ($sticks.Count -gt 1) {
        $items = @($sticks | ForEach-Object { '{0} - {1} (Datenträger {2})' -f $_.Root, $_.Name, $_.DiskNumber })
        $a = Show-InputDialog 'Notfall-Stick wählen' 'Mehrere Notfall-Sticks sind eingesteckt. Welcher soll aktualisiert werden?' @(@{ Key = 'S'; Label = 'Stick'; Type = 'Combo'; Items = $items })
        if (-not $a) { return }
        $ix = [array]::IndexOf($items, [string]$a.S); if ($ix -lt 0) { $ix = 0 }; $s = $sticks[$ix]
    }
    $os = Get-FbOsBuild
    $chk = Test-FbStickOutdated $s.Stamp $os.Build $os.Install
    $src = $(if ($s.Stamp -and [string]$s.Stamp.Source -match '(?i)ISO') { 'Latest' } else { 'WinRe' })
    $pf = (-not $s.Stamp) -or (@($s.Stamp.Parts) -contains 'PC-Tools portabel')
    if (-not (Confirm-Ui ("Notfall-Stick {0} ({1}) aktualisieren?`n`nZustand: {2}`nReparatursystem aus: {3}`n`nEs wird nur ergänzt und ersetzt - der Stick wird NICHT formatiert, gerettete Dateien und Treiber bleiben." -f $s.Root, $s.Name, $chk.Reason, $(if ($src -eq 'Latest') { 'neuester Windows-11-ISO' } else { 'WinRE dieses PCs' })))) { return }
    Start-Run -Parts @('RescueStick') -Job @{ DiskNumber = [int]$s.DiskNumber; Format = $false; Repair = $true; Source = $src; Iso = ''; Pflege = [bool]$pf; WithToken = $false; Toolbox = $false; Drivers = $false }
}
function Open-FbReadme {
    $pr = Get-FbPackageRoot $ui.FullBackup_Target.Text $env:COMPUTERNAME $FbPkgFolder
    $f = $(if ($pr) { Join-Path $pr 'LIESMICH.txt' } else { '' })
    if (-not $f -or -not (Test-Path -LiteralPath $f)) {
        $os = Get-FbOsBuild
        $tg = ConvertTo-FbTarget $ui.FullBackup_Target.Text
        $f = Join-Path $env:TEMP 'PC-Tools-Komplettsicherung-LIESMICH.txt'
        $info = [pscustomobject]@{ Computer = $env:COMPUTERNAME; Model = ''; Windows = ('{0} (Build {1})' -f $os.Display, $os.Text); Created = (Get-Date).ToString('dd.MM.yyyy HH:mm'); AppVersion = $AppVersion
            ImagePath = $(if ($tg.Valid) { $(if ($tg.IsNas) { $tg.Path } else { $tg.Path + '\WindowsImageBackup\' + $env:COMPUTERNAME }) } else { '(noch kein Ziel)' }); NasHint = $(if ($tg.IsNas) { $tg.Path } else { 'nur bei NAS-Sicherungen' }); BitLocker = '' }
        Set-Content -LiteralPath $f -Value (Get-FbReadme $info) -Encoding UTF8
    }
    Start-Process notepad.exe -ArgumentList ('"{0}"' -f $f)
}

# ---- Ereignisse
function Get-InstalledBackupTools {
    $known = @('Veeam', 'AOMEI', 'Macrium', 'Hasleo', 'Acronis', 'EaseUS Todo Backup', 'Paragon', 'Duplicati', 'Duplicacy', 'restic', 'Cobian', 'Iperius', 'Ashampoo Backup', 'O&O DiskImage', 'Active Backup', 'Synology Drive', 'Nova Backup', 'Genie', 'Carbonite', 'IDrive', 'Backblaze', 'Uranium Backup')
    $found = [System.Collections.Generic.List[string]]::new()
    try {
        foreach ($p in @(Get-ItemProperty 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*', 'HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*', 'HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*' -ErrorAction SilentlyContinue | Where-Object { $_.DisplayName })) {
            foreach ($k in $known) { if ([string]$p.DisplayName -like ('*' + $k + '*') -and -not @($found | Where-Object { $_ -like ($p.DisplayName + '*') }).Count) { $found.Add(('{0}{1}' -f $p.DisplayName, $(if ($p.DisplayVersion) { ' ' + $p.DisplayVersion } else { '' }))); break } }
        }
    } catch { }
    return , $found.ToArray()
}
