$ui.BtnFbReboot.Add_Click({
    $txt = "Der PC startet jetzt neu in die Windows-Wiederherstellungsumgebung (erweiterte Startoptionen).`n`nDort: Problembehandlung > Erweiterte Optionen > Weitere Wiederherstellungsoptionen anzeigen > Systemimage-Wiederherstellung.`n`nVorher: alle Programme schließen und Dateien speichern, die Sicherungsfestplatte anschließen und - falls BitLocker aktiv ist - den Wiederherstellungsschlüssel bereithalten (aka.ms/myrecoverykey).`n`nJetzt neu starten?"
    if (Confirm-Ui $txt 'Warning') { try { & shutdown.exe /r /o /t 0 } catch { Show-UiError $_.Exception.Message } }
})
$ui.BtnFbMount.Add_Click({ try { Start-FbMount } catch { $ui.BtnFbMount.IsEnabled = $true; Show-UiError $_.Exception.Message } })
$ui.BtnFbUnmount.Add_Click({ try { Stop-FbMount } catch { Show-UiError $_.Exception.Message } })
$ui.BtnFbReadme.Add_Click({ try { Open-FbReadme } catch { Show-UiError $_.Exception.Message } })
$ui.FbHistGrid.Add_SelectionChanged({ $row = $ui.FbHistGrid.SelectedItem; if ($row) { try { Show-FbHelp $row.Raw } catch { } } })
$ui.BtnFbHistLog.Add_Click({
    $row = $ui.FbHistGrid.SelectedItem; if (-not $row -and @($script:FbHistRows).Count) { $row = @($script:FbHistRows)[0] }
    $lf = $(if ($row) { [string]$row.Raw.Log } else { '' })
    if ($lf -and (Test-Path -LiteralPath $lf)) { Start-Process notepad.exe -ArgumentList ('"{0}"' -f $lf) } else { Show-UiError 'Zu diesem Lauf gibt es kein Protokoll (mehr).' }
})
$ui.BtnFbHistDir.Add_Click({ $p = Join-Path $DataDir 'Komplettsicherung'; New-Item $p -ItemType Directory -Force -ErrorAction SilentlyContinue | Out-Null; Start-Process explorer.exe -ArgumentList ('"{0}"' -f $p) })
$ui.FbTimeline.Add_SizeChanged({ param($s, $e) if ($e.WidthChanged) { try { Update-FbTimeline } catch { } } })
$ui.Tabs.Add_SelectionChanged({
    param($s, $e)
    if ($e.OriginalSource -eq $s -and $s.SelectedItem -eq $ui.TabFullBackup) {
        if (-not $script:FbLoaded -or ((Get-Date) - $script:FbLastRefresh).TotalSeconds -gt 60) {
            $script:FbLoaded = $true
            $ui.FbMonthPanel.Visibility = $(if ($ui.FullBackup_Frequency.SelectedItem -and [string]$ui.FullBackup_Frequency.SelectedItem.Content -eq 'Monatlich') { 'Visible' } else { 'Collapsed' })
            Update-FbStatus
        }
    }
})
$window.Add_Closing({ try { if ($script:FbMount) { Stop-FbMount -Quiet } } catch { } })

