# ---------------------------------------------------------------- PC-Reiniger (Oberfläche)
# Zeilen-Klasse für Tabellen mit Ankreuz-Spalte (Zwei-Wege-Bindung an Sel)
Add-Type -TypeDefinition 'namespace PCPflege { public class CcRow { public bool Sel { get; set; } public string Cat { get; set; } public string Problem { get; set; } public string Key { get; set; } public string Data { get; set; } public string Size { get; set; } public string Level { get; set; } public object Tag { get; set; } } }' -ErrorAction SilentlyContinue
$script:CcCat = @(Get-CcCatalog | ForEach-Object { $_ })
$script:CcById = @{}; foreach ($x in $script:CcCat) { $script:CcById[$x.Id] = $x }
$script:CcChecks = @{}; $script:CcSizeLbl = @{}; $script:CcRunBadge = @{}; $script:CcPresent = @{}
$script:CcLoaded = @{}; $script:CcPageLoaded = $false
$script:CcProgSync = [hashtable]::Synchronized(@{ Text = ''; Pct = 0 })
$script:CcRegSync = [hashtable]::Synchronized(@{ Text = '' })
$script:CcBusy = $false; $script:CcRegBusy = $false; $script:CcPrgBusy = $false; $script:CcJobWatch = $false
$script:CcPrgRows = @(); $script:CcExtRows = @(); $script:CcCtxRows = @(); $script:CcTaskRows = @(); $script:CcCounts = $null
$script:CcLeftFor = $null; $script:CcUninstTarget = $null; $script:CcPendingIds = @(); $script:CcPendingExt = $null
$script:CcSections = [ordered]@{ CcNavClean = 'CcSecClean'; CcNavReg = 'CcSecReg'; CcNavPrg = 'CcSecPrg'; CcNavExt = 'CcSecExt'; CcNavCtx = 'CcSecCtx'; CcNavTask = 'CcSecTask'; CcNavWipe = 'CcSecWipe' }
$CcGroupColor = @{ 'Windows' = '#2D7FF9'; 'Browser' = '#0891B2'; 'Anwendungen' = '#7C3AED'; 'Windows-Extras' = '#EA580C' }

# ---- kleine Bausteine
function New-CcText([string]$Text, [double]$Size = 12.5, [string]$Color = '#1F2A44', [string]$Weight = 'Normal') {
    $t = New-Object Windows.Controls.TextBlock
    $t.Text = $Text; $t.FontSize = $Size; $t.Foreground = New-UiBrush $Color; $t.FontWeight = $Weight; $t.TextWrapping = 'Wrap'
    return $t
}
function New-CcBadge([string]$Text, [string]$Bg, [string]$Fg) {
    $b = New-Object Windows.Controls.Border
    $b.CornerRadius = '4'; $b.Padding = '6,0,6,1'; $b.Margin = '6,0,0,0'; $b.VerticalAlignment = 'Center'; $b.Background = New-UiBrush $Bg
    $t = New-Object Windows.Controls.TextBlock; $t.Text = $Text; $t.FontSize = 10.5; $t.FontWeight = 'SemiBold'; $t.Foreground = New-UiBrush $Fg
    $b.Child = $t
    return $b
}
function New-CcGlyph([string]$Entity, [string]$Color, [int]$Size = 30) {
    $b = New-Object Windows.Controls.Border
    $b.Width = $Size; $b.Height = $Size; $b.CornerRadius = '8'; $b.Background = New-UiBrush $Color; $b.VerticalAlignment = 'Center'; $b.Margin = '0,0,10,0'
    $g = New-Object Windows.Controls.TextBlock
    $code = 0xE8A5; if ($Entity -match '&#x([0-9A-Fa-f]+);') { $code = [Convert]::ToInt32($Matches[1], 16) }
    $g.Text = [string][char]$code; $g.FontFamily = 'Segoe MDL2 Assets'; $g.FontSize = [math]::Round($Size * 0.5); $g.Foreground = New-UiBrush '#FFFFFF'
    $g.HorizontalAlignment = 'Center'; $g.VerticalAlignment = 'Center'
    $b.Child = $g
    return $b
}
function New-CcLinkButton([string]$Text, [string]$Tag) {
    $b = New-Object Windows.Controls.Button
    $b.Style = $window.FindResource('Sec'); $b.Content = $Text; $b.Tag = $Tag; $b.Padding = '8,2'; $b.Margin = '6,0,0,0'; $b.FontSize = 11.5; $b.VerticalAlignment = 'Center'
    return $b
}
function Set-CcBusyUi([string[]]$Names, [bool]$Busy) { foreach ($n in $Names) { if ($ui[$n]) { $ui[$n].IsEnabled = -not $Busy } } }

# ---- Bereiche umschalten (Unterseiten werden beim ersten Öffnen eingelesen)
function Show-CcSection([string]$Nav) {
    foreach ($k in $script:CcSections.Keys) { $ui[$script:CcSections[$k]].Visibility = $(if ($k -eq $Nav) { 'Visible' } else { 'Collapsed' }) }
    if ($script:CcLoaded[$Nav]) { return }
    $script:CcLoaded[$Nav] = $true
    switch ($Nav) {
        'CcNavReg'  { Update-CcRegBackups }
        'CcNavPrg'  { Update-CcPrograms }
        'CcNavExt'  { Update-CcExtensions }
        'CcNavCtx'  { Update-CcContext }
        'CcNavTask' { Update-CcTasks }
        'CcNavWipe' { Update-CcDrives }
    }
}
foreach ($n in @($script:CcSections.Keys)) { $ui[$n].Add_Checked({ param($s, $e) try { Show-CcSection ([string]$s.Name) } catch { $ui.StatusText.Text = 'PC-Reiniger: ' + $_.Exception.Message } }) }

# ---- Kacheln
function Update-CcTiles {
    $st = Get-CcState $CcStateFile
    $la = $st.PSObject.Properties['LastAnalysis']; $lc = $st.PSObject.Properties['LastClean']; $lr = $st.PSObject.Properties['LastReg']
    if ($la -and $la.Value) { $ui.CcTileSpaceVal.Text = Format-CcSize ([double]$la.Value.Bytes); $ui.CcTileSpaceSub.Text = 'Analyse vom ' + [string]$la.Value.Time } else { $ui.CcTileSpaceVal.Text = '-'; $ui.CcTileSpaceSub.Text = 'noch nicht analysiert' }
    if ($lc -and $lc.Value) { $ui.CcTileSpaceSub.Text += [Environment]::NewLine + ('zuletzt gereinigt {0}: {1}' -f [string]$lc.Value.Time, (Format-CcSize ([double]$lc.Value.Bytes))) }
    if ($lr -and $lr.Value) { $ui.CcTileRegVal.Text = [string]$lr.Value.Count; $ui.CcTileRegSub.Text = 'Suche vom ' + [string]$lr.Value.Time } else { $ui.CcTileRegVal.Text = '-'; $ui.CcTileRegSub.Text = 'noch nicht gesucht' }
    $c = $script:CcCounts
    if ($c) {
        $ui.CcTileAutoVal.Text = [string]$c.Startup; $ui.CcTileAutoSub.Text = 'Run-Schlüssel und Autostart-Ordner'
        $ui.CcTilePrgVal.Text = [string]([int]$c.Programs + [int]$c.Apps); $ui.CcTilePrgSub.Text = '{0} Desktop-Programme, {1} Store-Apps' -f $c.Programs, $c.Apps
        $ui.CcTileExtVal.Text = [string]$c.Extensions; $ui.CcTileExtSub.Text = 'alle Browser und Profile'
    }
}
function Start-CcCounts {
    Invoke-Bg -Script { Get-CcQuickCounts } -Functions $CcBgFunctions -Done {
        param($r, $err)
        if ($err -or -not $r) { return }
        $script:CcCounts = @($r)[-1]
        Update-CcTiles
    }
}

# ---- Seite beim ersten Öffnen
function Initialize-CcPage {
    Update-CcTiles
    Start-CcCounts
    $ui.CcList.Children.Clear()
    [void]$ui.CcList.Children.Add((New-CcText 'Prüfe, welche Browser und Programme auf diesem PC vorhanden sind ...' 12.5 '#6B7890'))
    Invoke-Bg -Script { param($items) Get-CcPresence $items } -Arguments @(, $script:CcCat) -Functions $CcBgFunctions -Done {
        param($r, $err)
        $script:CcPresent = @{}
        if (-not $err) { foreach ($x in @($r)) { if ($x -is [hashtable]) { $script:CcPresent = [hashtable]$x } } }
        else { foreach ($i in $script:CcCat) { $script:CcPresent[$i.Id] = $true } }
        Build-CcList
        if ([string]$ui.Cleaner_Items.Text) { Set-CcProfile 'Eigene' } else { Set-CcProfile 'Sicher' }
    }
}
$ui.Tabs.Add_SelectionChanged({ param($s, $e) if ($e.OriginalSource -eq $s -and $s.SelectedItem -eq $ui.TabCleaner -and -not $script:CcPageLoaded) { $script:CcPageLoaded = $true; try { Initialize-CcPage } catch { $ui.StatusText.Text = 'PC-Reiniger: ' + $_.Exception.Message } } })

# ---- Auswahlliste (Gruppen, Unterpunkte, Größe nach der Analyse)
function New-CcItemRow($It) {
    $row = New-Object Windows.Controls.Border; $row.BorderBrush = New-UiBrush '#EEF2F8'; $row.BorderThickness = '0,0,0,1'; $row.Padding = '0,6,0,6'
    $g = New-Object Windows.Controls.Grid
    $c1 = New-Object Windows.Controls.ColumnDefinition; $c2 = New-Object Windows.Controls.ColumnDefinition; $c2.Width = 'Auto'
    [void]$g.ColumnDefinitions.Add($c1); [void]$g.ColumnDefinitions.Add($c2)
    $sp = New-Object Windows.Controls.StackPanel
    $hd = New-Object Windows.Controls.WrapPanel
    $cb = New-Object Windows.Controls.CheckBox; $cb.Content = $It.Title; $cb.FontWeight = 'SemiBold'; $cb.Tag = $It.Id
    $cb.Add_Click({ Update-CcSelInfo })
    [void]$hd.Children.Add($cb)
    if ($It.Priv) { [void]$hd.Children.Add((New-CcBadge 'Datenschutz' '#EDE9FE' '#6D28D9')) }
    elseif ($It.Deep -and -not $It.Def) { [void]$hd.Children.Add((New-CcBadge 'gründlich' '#E6F0FF' '#1D4ED8')) }
    if ($It.Fn) { [void]$hd.Children.Add((New-CcBadge 'wie Aufräumen' '#DCFCE7' '#15803D')) }
    $rb = New-CcBadge 'läuft' '#FFEDD5' '#C2410C'; $rb.Visibility = 'Collapsed'; [void]$hd.Children.Add($rb)
    $ds = New-CcText $It.Desc 11.5 '#6B7890'; $ds.Margin = '45,2,0,0'
    [void]$sp.Children.Add($hd); [void]$sp.Children.Add($ds)
    $sz = New-CcText '' 12 '#1F2A44' 'SemiBold'; $sz.TextWrapping = 'NoWrap'; $sz.Margin = '12,2,0,0'; $sz.VerticalAlignment = 'Top'; $sz.HorizontalAlignment = 'Right'
    [Windows.Controls.Grid]::SetColumn($sz, 1)
    [void]$g.Children.Add($sp); [void]$g.Children.Add($sz)
    $row.Child = $g
    $script:CcChecks[$It.Id] = $cb; $script:CcSizeLbl[$It.Id] = $sz; $script:CcRunBadge[$It.Id] = $rb
    return $row
}
function Build-CcList {
    $ui.CcList.Children.Clear(); $script:CcChecks = @{}; $script:CcSizeLbl = @{}; $script:CcRunBadge = @{}
    $gi = Get-CcGroupInfo
    foreach ($gname in $gi.Keys) {
        $info = $gi[$gname]
        $items = @($script:CcCat | Where-Object { $_.Group -eq $gname })
        $box = New-Object Windows.Controls.Border; $box.Background = New-UiBrush '#F8FAFD'; $box.CornerRadius = '10'; $box.Padding = '12,10,12,8'; $box.Margin = '0,0,0,12'; $box.BorderBrush = New-UiBrush '#E2E7F0'; $box.BorderThickness = '1'
        $st = New-Object Windows.Controls.StackPanel
        $head = New-Object Windows.Controls.DockPanel; $head.Margin = '0,0,0,4'
        $bAll = New-CcLinkButton 'alle' $gname; $bNone = New-CcLinkButton 'keine' $gname
        $bAll.Add_Click({ param($s, $e) foreach ($i in @($script:CcCat | Where-Object { $_.Group -eq [string]$s.Tag })) { if ($script:CcChecks.ContainsKey($i.Id)) { $script:CcChecks[$i.Id].IsChecked = $true } }; Update-CcSelInfo })
        $bNone.Add_Click({ param($s, $e) foreach ($i in @($script:CcCat | Where-Object { $_.Group -eq [string]$s.Tag })) { if ($script:CcChecks.ContainsKey($i.Id)) { $script:CcChecks[$i.Id].IsChecked = $false } }; Update-CcSelInfo })
        [Windows.Controls.DockPanel]::SetDock($bNone, 'Right'); [Windows.Controls.DockPanel]::SetDock($bAll, 'Right')
        [void]$head.Children.Add($bNone); [void]$head.Children.Add($bAll)
        [void]$head.Children.Add((New-CcGlyph $info.Glyph $info.Color 30))
        $ht = New-Object Windows.Controls.StackPanel
        [void]$ht.Children.Add((New-CcText $gname 15 '#1F2A44' 'SemiBold'))
        [void]$ht.Children.Add((New-CcText $info.Text 11.5 '#6B7890'))
        [void]$head.Children.Add($ht)
        [void]$st.Children.Add($head)
        $missing = [System.Collections.Generic.List[string]]::new()
        foreach ($sub in @($items | ForEach-Object { $_.Sub } | Select-Object -Unique)) {
            $subItems = @($items | Where-Object { $_.Sub -eq $sub })
            $present = @($subItems | Where-Object { $script:CcPresent[$_.Id] })
            if (-not $present.Count) { $missing.Add($sub); continue }
            if ($gname -ne 'Windows') {
                $sh = New-CcText $sub 12.5 '#2D7FF9' 'SemiBold'; $sh.Margin = '0,10,0,2'
                [void]$st.Children.Add($sh)
            }
            foreach ($it in $present) { [void]$st.Children.Add((New-CcItemRow $it)) }
            $notHere = @($subItems | Where-Object { -not $script:CcPresent[$_.Id] })
            if ($notHere.Count -and $gname -eq 'Anwendungen') { foreach ($nh in $notHere) { $missing.Add($nh.Title) } }
        }
        if ($missing.Count) {
            $mt = New-CcText ('Auf diesem PC nicht gefunden (ausgeblendet): ' + ($missing -join ', ')) 11.5 '#9AA5B8'; $mt.Margin = '0,8,0,0'
            [void]$st.Children.Add($mt)
        }
        $box.Child = $st
        [void]$ui.CcList.Children.Add($box)
    }
    Update-CcSelInfo
}
function Get-CcSelectedIds { @($script:CcChecks.Keys | Where-Object { $script:CcChecks[$_].IsChecked } | Sort-Object) }
function Update-CcSelInfo {
    $ids = @(Get-CcSelectedIds)
    $pv = @($ids | Where-Object { $script:CcById[$_].Priv }).Count
    $ui.CcSelInfo.Text = '{0} von {1} Bereichen ausgewählt{2}' -f $ids.Count, $script:CcChecks.Count, $(if ($pv) { (', davon {0} Datenschutz' -f $pv) } else { '' })
}
function Set-CcSelection([string[]]$Ids) {
    foreach ($k in @($script:CcChecks.Keys)) { $script:CcChecks[$k].IsChecked = ($Ids -contains $k) }
    Update-CcSelInfo
}
function Set-CcProfile([string]$Mode) {
    if ($Mode -eq 'Eigene') {
        $ids = @(ConvertTo-CcIdList ([string]$ui.Cleaner_Items.Text) | ForEach-Object { $_ })
        if (-not $ids.Count) { Show-UiError 'Es ist noch keine eigene Auswahl gespeichert. Häkchen in der Liste setzen und dann "Aktuelle Auswahl als Eigene speichern" klicken.'; return }
        Set-CcSelection $ids
        $ui.CcProfInfo.Text = 'Profil: Eigene Auswahl ({0} Bereiche) - diese Auswahl nutzt auch die automatische Pflege, wenn unten eingeschaltet.' -f $ids.Count
        return
    }
    Set-CcSelection @(Get-CcProfileIds $Mode $script:CcCat)
    $ui.CcProfInfo.Text = switch ($Mode) {
        'Gründlich'   { 'Profil: Gründlich - zusätzlich Shader-Caches, Speicherabbilder, Adobe- und Entwickler-Caches. Programme bauen ihre Caches danach neu auf (erster Start etwas langsamer).' }
        'Datenschutz' { 'Profil: Datenschutz - zusätzlich Verlauf, Cookies (außer Ausnahmeliste), Sitzungen, Formulardaten und Windows-Verlaufslisten. Danach sind Sie auf Webseiten abgemeldet.' }
        default       { 'Profil: Sicher - nur Caches, Temp-Dateien und Protokolle, die automatisch neu entstehen. Keine Anmeldungen, kein Verlauf.' }
    }
}
$ui.BtnCcProfSafe.Add_Click({ Set-CcProfile 'Sicher' })
$ui.BtnCcProfDeep.Add_Click({ Set-CcProfile 'Gründlich' })
$ui.BtnCcProfPriv.Add_Click({ Set-CcProfile 'Datenschutz' })
$ui.BtnCcProfOwn.Add_Click({ Set-CcProfile 'Eigene' })
$ui.BtnCcNone.Add_Click({ Set-CcSelection @(); $ui.CcProfInfo.Text = 'Keine Auswahl.' })
$ui.BtnCcSaveOwn.Add_Click({
    $ids = @(Get-CcSelectedIds)
    if (-not $ids.Count) { Show-UiError 'Bitte zuerst mindestens einen Bereich ankreuzen.'; return }
    $ui.Cleaner_Items.Text = ($ids -join ',')
    try { Save-PflegeConfig (Get-ConfigFromUi); $ui.CcProfInfo.Text = 'Eigene Auswahl mit {0} Bereichen gespeichert.' -f $ids.Count; $ui.StatusText.Text = $ui.CcProfInfo.Text } catch { Show-UiError ('Speichern nicht möglich: ' + $_.Exception.Message) }
})
$ui.Cleaner_InSchedule.Add_Click({ try { Save-PflegeConfig (Get-ConfigFromUi); $ui.StatusText.Text = $(if ($ui.Cleaner_InSchedule.IsChecked) { 'PC-Reiniger läuft ab jetzt bei der automatischen Pflege mit.' } else { 'PC-Reiniger läuft nicht mehr bei der automatischen Pflege mit.' }) } catch { } })
$ui.Cleaner_KeepCookies.Add_LostFocus({ try { Save-PflegeConfig (Get-ConfigFromUi) } catch { } })

# ---- Analyse
function Start-CcAnalyze {
    if ($script:CcBusy) { return }
    $ids = @(Get-CcSelectedIds)
    if (-not $ids.Count) { Show-UiError 'Bitte zuerst Bereiche auswählen (oder ein Profil wählen).'; return }
    $items = @($script:CcCat | Where-Object { $ids -contains $_.Id })
    $cfg = Get-ConfigFromUi
    $days = @{}; foreach ($k in 'UserTempDays', 'WinTempDays', 'RecycleBinDays', 'WERDays', 'OldLogsDays') { try { $days[$k] = [int]$cfg.Clean.$k } catch { } }
    $opt = @{ Days = $days; Keep = [string]$ui.Cleaner_KeepCookies.Text }
    $script:CcBusy = $true; $script:CcProgSync.Text = 'wird vorbereitet ...'; $script:CcProgSync.Pct = 0
    $ui.CcProg.Visibility = 'Visible'; $ui.CcProg.Value = 0
    Set-CcBusyUi @('BtnCcAnalyze', 'BtnCcClean') $true
    $ui.CcTotalSub.Text = 'Analyse läuft - es wird nichts gelöscht ...'
    foreach ($l in $script:CcSizeLbl.Values) { $l.Text = '' }
    Invoke-Bg -Script { param($items, $opt, $prog) Invoke-CcAnalyze $items $opt $prog } -Arguments @($items, $opt, $script:CcProgSync) -Functions $CcBgFunctions -Done {
        param($r, $err)
        $script:CcBusy = $false
        $ui.CcProg.Visibility = 'Collapsed'; $ui.CcProgText.Text = ''
        Set-CcBusyUi @('BtnCcAnalyze', 'BtnCcClean') $false
        if ($err) { $ui.CcTotalSub.Text = 'Analyse fehlgeschlagen: ' + $err.Message; return }
        Show-CcResults @($r | Where-Object { $_ -and $_.PSObject.Properties['Id'] })
    }
}
function Show-CcResults($Rows) {
    $tot = [double]0; $files = 0; $ent = [int64]0; $runN = 0
    $grid = [System.Collections.Generic.List[object]]::new()
    $grp = [ordered]@{}
    foreach ($r in $Rows) {
        $it = $script:CcById[$r.Id]; if (-not $it) { continue }
        $tot += [double]$r.Bytes; $files += [int]$r.Files; $ent += [int64]$r.Entries
        if ($r.Running) { $runN++ }
        if (-not $grp.Contains($it.Group)) { $grp[$it.Group] = [double]0 }
        $grp[$it.Group] += [double]$r.Bytes
        $lbl = $script:CcSizeLbl[$r.Id]
        if ($lbl) {
            $lbl.Text = $(if ([double]$r.Bytes -gt 0) { Format-CcSize ([double]$r.Bytes) } elseif ([int64]$r.Entries -gt 0) { '{0:N0} Einträge' -f [int64]$r.Entries } else { '-' })
            if ([int64]$r.Entries -gt 0 -and [double]$r.Bytes -gt 0) { $lbl.Text += [Environment]::NewLine + ('{0:N0} Einträge' -f [int64]$r.Entries) }
            $lbl.ToolTip = $(if ($r.Note) { [string]$r.Note } else { $null })
        }
        $rb = $script:CcRunBadge[$r.Id]; if ($rb) { $rb.Visibility = $(if ($r.Running) { 'Visible' } else { 'Collapsed' }) }
        $grid.Add([pscustomobject]@{
            Group = $it.Group; Sub = $(if ($it.Group -eq 'Windows' -or $it.Group -eq 'Windows-Extras') { '' } else { $it.Sub }); Title = $it.Title
            Bytes = [double]$r.Bytes; SizeText = $(if ([double]$r.Bytes -gt 0) { Format-CcSize ([double]$r.Bytes) } else { '' }); Files = [int]$r.Files; FilesText = $(if ($r.Files) { '{0:N0}' -f $r.Files } else { '' })
            Entries = [int64]$r.Entries; EntriesText = $(if ($r.Entries) { '{0:N0}' -f $r.Entries } else { '' }); Note = [string]$r.Note
            Level = $(if ($r.Running) { 'Warn' } elseif ([double]$r.Bytes -le 0 -and [int64]$r.Entries -le 0) { 'Off' } else { '' })
        })
    }
    Set-GridItems $ui.CcResGrid @($grid | Sort-Object Bytes -Descending)
    $ui.CcTotal.Text = Format-CcSize $tot
    $ui.CcTotalSub.Text = '{0:N0} Dateien in {1} Bereichen{2}{3}' -f $files, @($Rows).Count, $(if ($ent) { (', dazu {0:N0} Einträge (Verlauf, Cookies, Listen)' -f $ent) } else { '' }), $(if ($runN) { ('. {0} Bereich(e) gehören zu laufenden Programmen - beim Reinigen fragt PC-Tools, ob sie geschlossen werden sollen.' -f $runN) } else { '.' })
    $ui.CcResInfo.Text = 'Analyse vom {0:dd.MM.yyyy HH:mm} - sortiert nach Größe. Grau = nichts zu tun, orange = Programm läuft gerade.' -f (Get-Date)
    Build-CcChart @($grid | Where-Object { $_.Bytes -gt 0 } | Sort-Object Bytes -Descending | Select-Object -First 10) $grp
    Set-CcState $CcStateFile 'LastAnalysis' ([pscustomobject]@{ Time = (Get-Date).ToString('dd.MM.yyyy HH:mm'); Bytes = $tot; Files = $files; Entries = $ent; Items = @($Rows).Count })
    Update-CcTiles
}
function Build-CcChart($Top, $Groups) {
    $ui.CcChart.Children.Clear(); $ui.CcGroupSum.Children.Clear()
    $top = @($Top)
    if (-not $top.Count) { $ui.CcChartInfo.Text = 'Nichts Nennenswertes gefunden - dieser PC ist schon sauber.'; return }
    $ui.CcChartInfo.Text = 'Die größten Posten der Auswahl:'
    $max = [double]($top | Measure-Object Bytes -Maximum).Maximum; if ($max -le 0) { $max = 1 }
    foreach ($t in $top) {
        $g = New-Object Windows.Controls.Grid; $g.Margin = '0,3,0,3'
        foreach ($w in 132, -1, 74) { $cd = New-Object Windows.Controls.ColumnDefinition; if ($w -gt 0) { $cd.Width = $w }; [void]$g.ColumnDefinitions.Add($cd) }
        $nm = New-Object Windows.Controls.TextBlock; $nm.Text = $(if ($t.Group -eq 'Browser') { $t.Sub + ': ' + $t.Title } else { $t.Title }); $nm.TextTrimming = 'CharacterEllipsis'; $nm.FontSize = 11.5; $nm.Foreground = New-UiBrush '#1F2A44'; $nm.ToolTip = $nm.Text; $nm.VerticalAlignment = 'Center'
        $track = New-Object Windows.Controls.Grid; $track.Height = 12; $track.Margin = '8,0,8,0'; $track.VerticalAlignment = 'Center'
        $frac = [math]::Max([double]0.02, [double]$t.Bytes / $max)
        $a = New-Object Windows.Controls.ColumnDefinition; $a.Width = New-Object Windows.GridLength($frac, 'Star')
        $b = New-Object Windows.Controls.ColumnDefinition; $b.Width = New-Object Windows.GridLength([math]::Max([double]0.0001, 1 - $frac), 'Star')
        [void]$track.ColumnDefinitions.Add($a); [void]$track.ColumnDefinitions.Add($b)
        $bg = New-Object Windows.Controls.Border; $bg.CornerRadius = '6'; $bg.Background = New-UiBrush '#EEF2F8'; [Windows.Controls.Grid]::SetColumnSpan($bg, 2)
        $bar = New-Object Windows.Controls.Border; $bar.CornerRadius = '6'; $bar.Background = New-UiBrush $(if ($CcGroupColor[$t.Group]) { $CcGroupColor[$t.Group] } else { '#2D7FF9' })
        [void]$track.Children.Add($bg); [void]$track.Children.Add($bar)
        [Windows.Controls.Grid]::SetColumn($track, 1)
        $sz = New-Object Windows.Controls.TextBlock; $sz.Text = $t.SizeText; $sz.FontSize = 11.5; $sz.FontWeight = 'SemiBold'; $sz.Foreground = New-UiBrush '#1F2A44'; $sz.HorizontalAlignment = 'Right'; $sz.VerticalAlignment = 'Center'
        [Windows.Controls.Grid]::SetColumn($sz, 2)
        [void]$g.Children.Add($nm); [void]$g.Children.Add($track); [void]$g.Children.Add($sz)
        [void]$ui.CcChart.Children.Add($g)
    }
    foreach ($k in $Groups.Keys) {
        if ([double]$Groups[$k] -le 0) { continue }
        $chip = New-Object Windows.Controls.Border; $chip.CornerRadius = '10'; $chip.Padding = '9,3'; $chip.Margin = '0,4,6,0'; $chip.Background = New-UiBrush $(if ($CcGroupColor[$k]) { $CcGroupColor[$k] } else { '#2D7FF9' })
        $tx = New-Object Windows.Controls.TextBlock; $tx.Text = '{0}: {1}' -f $k, (Format-CcSize ([double]$Groups[$k])); $tx.Foreground = New-UiBrush '#FFFFFF'; $tx.FontSize = 11.5; $tx.FontWeight = 'SemiBold'
        $chip.Child = $tx
        [void]$ui.CcGroupSum.Children.Add($chip)
    }
}
$ui.BtnCcAnalyze.Add_Click({ try { Start-CcAnalyze } catch { $script:CcBusy = $false; Show-UiError ('Analyse nicht möglich: ' + $_.Exception.Message) } })

# ---- Reinigen (läuft als Engine-Teil CleanerRun)
function Start-CcCleanRun($Ids) {
    if ($script:Job) { Show-UiError 'Es läuft bereits eine Aufgabe - bitte warten, bis sie fertig ist.'; return }
    Start-Run -Parts @('CleanerRun') -Job @{ Items = @($Ids); KeepCookies = ([string]$ui.Cleaner_KeepCookies.Text).Trim() }
    $script:CcJobWatch = $true
}
function Start-CcClean {
    if ($script:Job) { Show-UiError 'Es läuft bereits eine Aufgabe - bitte warten, bis sie fertig ist.'; return }
    $ids = @(Get-CcSelectedIds)
    if (-not $ids.Count) { Show-UiError 'Bitte zuerst Bereiche auswählen (oder ein Profil wählen).'; return }
    $items = @($script:CcCat | Where-Object { $ids -contains $_.Id })
    $priv = @($items | Where-Object { $_.Priv })
    $msg = '{0} Bereiche jetzt reinigen?' -f $items.Count
    if ($priv.Count) {
        $msg += [Environment]::NewLine + [Environment]::NewLine + 'Darunter sind Datenschutz-Bereiche (' + (@($priv | ForEach-Object { $(if ($_.Group -eq 'Browser') { $_.Sub + ' ' + ($_.Title -split ' ')[0] } else { $_.Title }) } | Select-Object -First 6) -join ', ') + $(if ($priv.Count -gt 6) { ' ...' } else { '' }) + ').'
        if (@($priv | Where-Object { $_.Id -like '*.Cookies' }).Count) { $msg += [Environment]::NewLine + 'Nach dem Löschen der Cookies sind Sie auf Webseiten abgemeldet' + $(if ([string]$ui.Cleaner_KeepCookies.Text) { ' (außer: ' + $ui.Cleaner_KeepCookies.Text + ')' } else { '' }) + '.' }
        $msg += [Environment]::NewLine + 'Gespeicherte Kennwörter bleiben erhalten.'
    }
    if (-not (Confirm-Ui $msg)) { return }
    $run = Get-CcRunningSet
    $hit = @{}
    foreach ($it in $items) { foreach ($p in @($it.Proc)) { if ($p -and $run.ContainsKey(([string]$p).ToLower())) { $hit[[string]$p] = [string]$it.Sub } } }
    if ($hit.Count) {
        $names = (@($hit.Values | Select-Object -Unique) -join ', ')
        $a = [Windows.MessageBox]::Show((T (('Diese Programme laufen gerade: {0}{1}{1}Ja = jetzt schließen und alles reinigen (nicht gespeicherte Eingaben in diesen Programmen gehen verloren){1}Nein = diese Bereiche überspringen, den Rest reinigen{1}Abbrechen = nichts tun' -f $names, [Environment]::NewLine))), (T ('PC-Tools')), 'YesNoCancel', 'Question')
        if ([string]$a -eq 'Cancel') { return }
        if ([string]$a -eq 'Yes') {
            $script:CcPendingIds = $ids
            $ui.CcTotalSub.Text = 'Schließe ' + $names + ' ...'
            Set-CcBusyUi @('BtnCcAnalyze', 'BtnCcClean') $true
            Invoke-Bg -Script {
                param($procs)
                foreach ($p in @(Get-Process -Name $procs -ErrorAction SilentlyContinue)) { try { if ($p.MainWindowHandle -ne [IntPtr]::Zero) { [void]$p.CloseMainWindow() } } catch { } }
                $sw = [Diagnostics.Stopwatch]::StartNew()
                while ($sw.Elapsed.TotalSeconds -lt 8 -and @(Get-Process -Name $procs -ErrorAction SilentlyContinue).Count) { Start-Sleep -Milliseconds 500 }
                Get-Process -Name $procs -ErrorAction SilentlyContinue | Stop-Process -Force -ErrorAction SilentlyContinue
                Start-Sleep -Seconds 1
            } -Arguments @(, [string[]]@($hit.Keys)) -Done {
                param($r, $err)
                Set-CcBusyUi @('BtnCcAnalyze', 'BtnCcClean') $false
                Start-CcCleanRun $script:CcPendingIds
            }
            return
        }
    }
    Start-CcCleanRun $ids
}
$ui.BtnCcClean.Add_Click({ try { Start-CcClean } catch { Show-UiError ('Reinigung nicht möglich: ' + $_.Exception.Message) } })
function Complete-CcJob {
    Update-CcTiles
    $st = Get-CcState $CcStateFile
    $lc = $st.PSObject.Properties['LastClean']
    if ($lc -and $lc.Value) {
        $ui.CcTotalSub.Text = 'Reinigung fertig ({0}): {1} freigegeben{2}. Erneut "Analysieren" zeigt den neuen Stand.' -f [string]$lc.Value.Time, (Format-CcSize ([double]$lc.Value.Bytes)), $(if ([int]$lc.Value.Skipped) { (', {0} Bereich(e) übersprungen (Programm lief)' -f $lc.Value.Skipped) } else { '' })
    }
    if ($script:CcLoaded['CcNavWipe']) { Update-CcDrives }
    Start-CcCounts
}

