# ---- Registry
function Start-CcRegScan {
    if ($script:CcRegBusy) { return }
    $cats = @(foreach ($k in (Get-CcRegCatNames).Keys) { if ($ui['CcRegCat_' + $k].IsChecked) { $k } })
    if (-not $cats.Count) { Show-UiError 'Bitte mindestens eine Kategorie ankreuzen.'; return }
    $script:CcRegBusy = $true; $script:CcRegSync.Text = ''
    $ui.CcRegProg.Visibility = 'Visible'; $ui.CcRegInfo.Text = 'Suche läuft ...'
    Set-CcBusyUi @('BtnCcRegScan', 'BtnCcRegFix') $true
    Invoke-Bg -Script { param($c, $p) Get-CcRegFindings $c $p } -Arguments @($cats, $script:CcRegSync) -Functions $CcBgFunctions -Done {
        param($r, $err)
        $script:CcRegBusy = $false; $ui.CcRegProg.Visibility = 'Collapsed'
        Set-CcBusyUi @('BtnCcRegScan', 'BtnCcRegFix') $false
        if ($err) { $ui.CcRegInfo.Text = 'Suche fehlgeschlagen: ' + $err.Message; return }
        $rows = [System.Collections.Generic.List[object]]::new()
        foreach ($f in @($r | ForEach-Object { $_ } | Where-Object { $_ -and $_.PSObject.Properties['Action'] })) {
            $x = New-Object PCPflege.CcRow
            $x.Sel = $true; $x.Cat = [string]$f.Cat; $x.Problem = [string]$f.Problem; $x.Key = [string]$f.Key; $x.Data = [string]$f.Data; $x.Level = ''; $x.Tag = $f
            $rows.Add($x)
        }
        Set-GridItems $ui.CcRegGrid $rows
        $byCat = @($rows | Group-Object Cat | ForEach-Object { '{0}: {1}' -f $_.Name, $_.Count })
        $ui.CcRegInfo.Text = $(if ($rows.Count) { '{0} verwaiste Einträge gefunden - alle sind angekreuzt. {1}' -f $rows.Count, ($byCat -join ' · ') } else { 'Keine verwaisten Einträge gefunden - die Registry ist in Ordnung.' })
        Set-CcState $CcStateFile 'LastReg' ([pscustomobject]@{ Time = (Get-Date).ToString('dd.MM.yyyy HH:mm'); Count = $rows.Count })
        Update-CcTiles
    }
}
function Invoke-CcRegFixUi {
    $sel = @($ui.CcRegGrid.ItemsSource | Where-Object { $_.Sel })
    if (-not $sel.Count) { Show-UiError 'Bitte die zu behebenden Einträge ankreuzen.'; return }
    if (-not (Confirm-Ui ('{0} Einträge beheben?{1}{1}Vorher wird jeder betroffene Registry-Schlüssel als .reg-Datei gesichert (Datenordner\Registry-Sicherung). Einträge, die sich nicht sichern lassen, bleiben unverändert. Die Sicherung lässt sich unten jederzeit zurückspielen.' -f $sel.Count, [Environment]::NewLine))) { return }
    $dir = Join-Path $CcRegBackupRoot (Get-Date -Format 'yyyyMMdd_HHmmss')
    $script:CcRegBusy = $true; $ui.CcRegProg.Visibility = 'Visible'; $ui.CcRegInfo.Text = 'Sichere und behebe ...'
    Set-CcBusyUi @('BtnCcRegScan', 'BtnCcRegFix') $true
    Invoke-Bg -Script { param($rows, $dir) Invoke-CcRegFix $rows $dir 'Registry-Reinigung' } -Arguments @(@($sel | ForEach-Object { $_.Tag }), $dir) -Functions $CcBgFunctions -Done {
        param($r, $err)
        $script:CcRegBusy = $false; $ui.CcRegProg.Visibility = 'Collapsed'
        Set-CcBusyUi @('BtnCcRegScan', 'BtnCcRegFix') $false
        if ($err) { Show-UiError ('Nicht möglich: ' + $err.Message); return }
        $res = @($r | ForEach-Object { $_ } | Where-Object { $_ -and $_.PSObject.Properties['Ok'] })
        $okKeys = @{}; foreach ($x in $res) { if ($x.Ok) { $okKeys[$x.Key] = $true } }
        $left = [System.Collections.Generic.List[object]]::new()
        foreach ($row in @($ui.CcRegGrid.ItemsSource)) {
            if ($okKeys.ContainsKey($row.Key)) { continue }
            $f = @($res | Where-Object { $_.Key -eq $row.Key }) | Select-Object -First 1
            if ($f) { $row.Level = 'Error'; $row.Problem = $row.Problem + ' - ' + $f.Msg; $row.Sel = $false }
            $left.Add($row)
        }
        Set-GridItems $ui.CcRegGrid $left
        $bad = @($res | Where-Object { -not $_.Ok }).Count
        $ui.CcRegInfo.Text = '{0} Einträge behoben und gesichert{1}.' -f $okKeys.Count, $(if ($bad) { (', {0} nicht möglich (rot markiert)' -f $bad) } else { '' })
        $ui.StatusText.Text = $ui.CcRegInfo.Text
        Set-CcState $CcStateFile 'LastReg' ([pscustomobject]@{ Time = (Get-Date).ToString('dd.MM.yyyy HH:mm'); Count = $left.Count })
        Update-CcTiles; Update-CcRegBackups
    }
}
function Update-CcRegBackups {
    try { Set-GridItems $ui.CcRegBakGrid @(Get-CcRegBackups $CcRegBackupRoot | ForEach-Object { $_ }) } catch { }
}
$ui.BtnCcRegScan.Add_Click({ try { Start-CcRegScan } catch { $script:CcRegBusy = $false; Show-UiError ('Suche nicht möglich: ' + $_.Exception.Message) } })
$ui.BtnCcRegFix.Add_Click({ try { Invoke-CcRegFixUi } catch { Show-UiError ('Nicht möglich: ' + $_.Exception.Message) } })
$ui.BtnCcRegAll.Add_Click({ foreach ($x in @($ui.CcRegGrid.ItemsSource)) { $x.Sel = $true }; $ui.CcRegGrid.Items.Refresh() })
$ui.BtnCcRegNone.Add_Click({ foreach ($x in @($ui.CcRegGrid.ItemsSource)) { $x.Sel = $false }; $ui.CcRegGrid.Items.Refresh() })
$ui.BtnCcRegBakRefresh.Add_Click({ Update-CcRegBackups })
$ui.BtnCcRegBakOpen.Add_Click({ $b = $ui.CcRegBakGrid.SelectedItem; $d = if ($b) { $b.Dir } else { $CcRegBackupRoot }; New-Item -Path $d -ItemType Directory -Force -ErrorAction SilentlyContinue | Out-Null; Start-Process explorer.exe $d })
$ui.BtnCcRegRestore.Add_Click({
    $b = $ui.CcRegBakGrid.SelectedItem
    if (-not $b) { Show-UiError 'Bitte eine Sicherung in der Liste auswählen.'; return }
    if (-not (Confirm-Ui ('Sicherung vom {0} ({1}, {2} Änderungen) zurückspielen?{3}{3}Alle .reg-Dateien dieser Sicherung werden importiert - entfernte Einträge sind danach wieder da.' -f $b.Time, $b.Title, $b.Count, [Environment]::NewLine))) { return }
    try {
        $r = Restore-CcRegBackup $b.Dir
        $ui.StatusText.Text = 'Sicherung zurückgespielt: {0} Datei(en) importiert{1}.' -f $r.Ok, $(if ($r.Bad) { (', {0} fehlgeschlagen' -f $r.Bad) } else { '' })
        [Windows.MessageBox]::Show((T ($ui.StatusText.Text)), (T ('PC-Tools'))) | Out-Null
    } catch { Show-UiError ('Zurückspielen nicht möglich: ' + $_.Exception.Message) }
})

# ---- Programme
function Test-CcPrgKind($O, [int]$Kind) {
    switch ($Kind) {
        1 { return ($O.Kind -eq 'Programm') }
        2 { return ($O.Kind -eq 'Store-App') }
        3 { return [bool]$O.Orphan }
        4 { return ([double]$O.Size -ge 500MB) }
        5 { return ($O.Date -and $O.Date -ge (Get-Date).AddDays(-30)) }
        default { return $true }
    }
}
function Update-CcPrgFilter {
    $script:FCcPrg = $ui.CcPrgFilter.Text.Trim(); $script:FCcPrgKind = [math]::Max(0, $ui.CcPrgKind.SelectedIndex)
    Set-GridFilter $ui.CcPrgGrid { param($o) (Test-Match $o $script:FCcPrg @('Name', 'Publisher', 'Version')) -and (Test-CcPrgKind $o $script:FCcPrgKind) }
    $vis = @($script:CcPrgRows | Where-Object { (Test-Match $_ $script:FCcPrg @('Name', 'Publisher', 'Version')) -and (Test-CcPrgKind $_ $script:FCcPrgKind) }).Count
    $orph = @($script:CcPrgRows | Where-Object { $_.Orphan }).Count
    $ui.CcPrgCount.Text = '{0} von {1} angezeigt{2}' -f $vis, $script:CcPrgRows.Count, $(if ($orph) { (' · {0} verwaiste Einträge (orange)' -f $orph) } else { '' })
}
function Update-CcPrograms {
    if ($script:CcPrgBusy) { return }
    $script:CcPrgBusy = $true; $ui.CcPrgProg.Visibility = 'Visible'; $ui.CcPrgCount.Text = 'Programme werden eingelesen ...'
    Invoke-Bg -Script { Get-CcPrograms $true } -Functions $CcBgFunctions -Done {
        param($r, $err)
        $script:CcPrgBusy = $false; $ui.CcPrgProg.Visibility = 'Collapsed'
        if ($err) { $ui.CcPrgCount.Text = 'Fehler: ' + $err.Message; return }
        $script:CcPrgRows = @($r | ForEach-Object { $_ } | Where-Object { $_ -and $_.PSObject.Properties['Kind'] } | Sort-Object Name)
        Set-GridItems $ui.CcPrgGrid $script:CcPrgRows
        Update-CcPrgFilter
    }
}
function Show-CcPrgInfo {
    $p = $ui.CcPrgGrid.SelectedItem
    if (-not $p) { $ui.CcPrgInfo.Text = 'Programm auswählen - Details erscheinen hier.'; return }
    $l = @(('{0}  {1}  ·  {2}' -f $p.Name, $p.Version, $(if ($p.Publisher) { $p.Publisher } else { 'Herausgeber unbekannt' })))
    if ($p.Kind -eq 'Store-App') { $l += 'Store-App · Paket: ' + $p.Pkg; if ($p.Location) { $l += 'Ordner: ' + $p.Location } }
    else {
        $l += '{0} · {1}{2}' -f $p.KindText, $p.Scope, $(if ($p.Guid) { ' · Produktcode ' + $p.Guid } else { '' })
        if ($p.Location) { $l += 'Installiert in: ' + $p.Location }
        if ($p.Uninstall) { $l += 'Deinstallation: ' + $p.Uninstall }
        $l += $(if ($p.Quiet -or ($p.Msi -and $p.Guid)) { 'Stille Deinstallation möglich.' } else { 'Keine stille Deinstallation hinterlegt - das Programm des Herstellers öffnet sich.' })
        if ($p.Orphan) { $l += 'VERWAIST: Das Deinstallationsprogramm fehlt (oder Windows Installer kennt das Produkt nicht mehr). "Verwaisten Eintrag entfernen" nimmt den Eintrag gesichert aus der Liste, danach "Nach Resten suchen".' }
    }
    $ui.CcPrgInfo.Text = $l -join [Environment]::NewLine
    $ui.BtnCcPrgModify.IsEnabled = [bool]$p.CanModify; $ui.BtnCcPrgRepair.IsEnabled = [bool]$p.CanRepair; $ui.BtnCcPrgOrphan.IsEnabled = [bool]$p.Orphan
}
function Start-CcUninstall {
    $p = $ui.CcPrgGrid.SelectedItem
    if (-not $p) { Show-UiError 'Bitte ein Programm in der Liste auswählen.'; return }
    if ($p.Orphan) { Show-UiError ('Für "{0}" fehlt das Deinstallationsprogramm. Nutzen Sie "Verwaisten Eintrag entfernen" und danach "Nach Resten suchen".' -f $p.Name); return }
    $quiet = [bool]$ui.CcPrgQuiet.IsChecked
    $how = if ($p.Kind -eq 'Store-App') { 'Die App wird für diesen Benutzer entfernt (im Microsoft Store jederzeit wieder installierbar).' }
           elseif ($quiet -and ($p.Quiet -or ($p.Msi -and $p.Guid))) { 'Die Deinstallation läuft still, ohne Rückfragen des Programms.' }
           else { 'Das Deinstallationsprogramm des Herstellers öffnet sich - bitte dort bestätigen. PC-Tools wartet, bis es fertig ist.' }
    if (-not (Confirm-Ui ('"{0}" deinstallieren?{1}{1}{2}{1}Danach bietet PC-Tools an, nach Resten zu suchen.' -f $p.Name, [Environment]::NewLine, $how))) { return }
    $script:CcUninstTarget = $p; $script:CcPrgBusy = $true
    $ui.CcPrgProg.Visibility = 'Visible'; $ui.CcPrgInfo.Text = 'Deinstallation von "{0}" läuft ...' -f $p.Name
    Set-CcBusyUi @('BtnCcPrgUninst', 'BtnCcPrgOrphan', 'BtnCcPrgLeft', 'BtnCcPrgRefresh') $true
    Invoke-Bg -Script { param($p, $q) Invoke-CcUninstall $p $q } -Arguments @($p, $quiet) -Functions $CcBgFunctions -Done {
        param($r, $err)
        $script:CcPrgBusy = $false; $ui.CcPrgProg.Visibility = 'Collapsed'
        Set-CcBusyUi @('BtnCcPrgUninst', 'BtnCcPrgOrphan', 'BtnCcPrgLeft', 'BtnCcPrgRefresh') $false
        $t = $script:CcUninstTarget
        if ($err) { Show-UiError ('Deinstallation nicht möglich: ' + $err.Message); return }
        $x = @($r | Where-Object { $_ -and $_.PSObject.Properties['Removed'] }) | Select-Object -Last 1
        if ($x -and $x.Removed) {
            $ui.CcPrgInfo.Text = '"{0}" wurde deinstalliert (Rückgabewert {1}).' -f $t.Name, $x.Code
            $ui.StatusText.Text = $ui.CcPrgInfo.Text
            if ($t.Kind -ne 'Store-App' -and (Confirm-Ui ('"{0}" wurde entfernt. Jetzt nach Resten suchen (Ordner und Registry)?' -f $t.Name))) { Start-CcLeftovers $t }
        } else {
            $ui.CcPrgInfo.Text = '"{0}" ist noch eingetragen (Rückgabewert {1}). Wurde die Deinstallation abgebrochen, oder braucht sie erst einen Neustart (3010)?' -f $t.Name, $(if ($x) { $x.Code } else { '?' })
        }
        Update-CcPrograms
        Start-CcCounts
    }
}
function Start-CcLeftovers($P) {
    if (-not $P) { Show-UiError 'Bitte ein Programm in der Liste auswählen.'; return }
    if ($P.Kind -eq 'Store-App') { Show-UiError 'Store-Apps hinterlassen keine Reste außerhalb ihres Paketordners - Windows räumt sie selbst weg.'; return }
    if (-not $P.Orphan -and (Test-CcProgramPresent $P)) {
        if (-not (Confirm-Ui ('"{0}" ist noch installiert. Die Suche findet dann die Ordner des installierten Programms - diese NICHT entfernen, solange es benutzt wird.{1}{1}Trotzdem suchen?' -f $P.Name, [Environment]::NewLine) 'Warning')) { return }
    }
    $script:CcLeftFor = $P
    $ui.CcLeftCard.Visibility = 'Visible'; $ui.CcLeftTitle.Text = 'Reste von "{0}"' -f $P.Name; $ui.CcLeftInfo.Text = 'Suche läuft ...'
    Set-GridItems $ui.CcLeftGrid @()
    Invoke-Bg -Script { param($p) Find-CcLeftovers $p } -Arguments @(, $P) -Functions $CcBgFunctions -Done {
        param($r, $err)
        if ($err) { $ui.CcLeftInfo.Text = 'Suche fehlgeschlagen: ' + $err.Message; return }
        $rows = [System.Collections.Generic.List[object]]::new()
        foreach ($f in @($r | ForEach-Object { $_ } | Where-Object { $_ -and $_.PSObject.Properties['Kind'] })) {
            $x = New-Object PCPflege.CcRow
            $x.Sel = [bool]$f.Sel; $x.Cat = [string]$f.Cat; $x.Key = [string]$f.Key; $x.Size = [string]$f.Size; $x.Problem = [string]$f.Problem; $x.Level = ''; $x.Tag = $f
            $rows.Add($x)
        }
        Set-GridItems $ui.CcLeftGrid $rows
        $ui.CcLeftInfo.Text = $(if ($rows.Count) { '{0} mögliche Reste gefunden. Gesucht wurde nur nach Ordnern und Registry-Schlüsseln, die genau zum Programm- bzw. Herstellernamen passen. Bitte kurz prüfen: Ordner wandern in den Papierkorb, Registry-Schlüssel werden vorher als .reg gesichert.' -f $rows.Count } else { 'Keine Reste gefunden - das Programm hat sauber aufgeräumt.' })
    }
}
function Remove-CcLeftoversUi {
    $sel = @($ui.CcLeftGrid.ItemsSource | Where-Object { $_.Sel })
    if (-not $sel.Count) { Show-UiError 'Bitte die zu entfernenden Reste ankreuzen.'; return }
    if (-not (Confirm-Ui ('{0} Reste entfernen?{1}{1}Ordner kommen in den Papierkorb (wiederherstellbar), Registry-Schlüssel werden vorher unter Datenordner\Registry-Sicherung gesichert.' -f $sel.Count, [Environment]::NewLine))) { return }
    $dir = Join-Path $CcRegBackupRoot ((Get-Date -Format 'yyyyMMdd_HHmmss') + '_Reste')
    $ui.CcLeftInfo.Text = 'Entferne ...'
    Invoke-Bg -Script { param($rows, $dir) Remove-CcLeftovers $rows $dir } -Arguments @(@($sel | ForEach-Object { $_.Tag }), $dir) -Functions $CcBgFunctions -Done {
        param($r, $err)
        if ($err) { $ui.CcLeftInfo.Text = 'Fehler: ' + $err.Message; return }
        $msgs = @($r | ForEach-Object { $_ } | Where-Object { $_ -is [string] })
        $ui.CcLeftInfo.Text = ($msgs -join [Environment]::NewLine)
        Set-GridItems $ui.CcLeftGrid @($ui.CcLeftGrid.ItemsSource | Where-Object { -not $_.Sel })
        $ui.StatusText.Text = 'Reste entfernt.'
        Update-CcRegBackups
    }
}
function Remove-CcOrphanUi {
    $p = $ui.CcPrgGrid.SelectedItem
    if (-not $p -or -not $p.Orphan) { Show-UiError 'Bitte einen verwaisten Eintrag (orange) auswählen.'; return }
    if (-not (Confirm-Ui ('Den verwaisten Eintrag "{0}" aus der Programmliste entfernen?{1}{1}Der Registry-Schlüssel wird vorher als .reg gesichert. Dateien werden nicht angefasst.' -f $p.Name, [Environment]::NewLine))) { return }
    $script:CcUninstTarget = $p
    $row = [pscustomobject]@{ Hive = $p.Hive; Path = $p.Path; Value = ''; Action = 'DeleteKey'; Key = ('{0}\{1}' -f $p.Hive, $p.Path); Problem = 'Verwaister Programmeintrag: ' + $p.Name }
    $dir = Join-Path $CcRegBackupRoot ((Get-Date -Format 'yyyyMMdd_HHmmss') + '_Programmeintrag')
    Invoke-Bg -Script { param($row, $dir) Invoke-CcRegFix @($row) $dir 'Verwaister Programmeintrag' } -Arguments @($row, $dir) -Functions $CcBgFunctions -Done {
        param($r, $err)
        if ($err) { Show-UiError ('Nicht möglich: ' + $err.Message); return }
        $x = @($r | ForEach-Object { $_ } | Where-Object { $_ -and $_.PSObject.Properties['Ok'] }) | Select-Object -First 1
        if ($x -and $x.Ok) {
            $ui.StatusText.Text = 'Verwaister Eintrag entfernt (gesichert).'
            Update-CcPrograms; Update-CcRegBackups
            if (Confirm-Ui ('Eintrag entfernt. Jetzt nach Resten von "{0}" suchen?' -f $script:CcUninstTarget.Name)) { Start-CcLeftovers $script:CcUninstTarget }
        } else { Show-UiError ('Nicht entfernt: ' + $(if ($x) { $x.Msg } else { 'unbekannt' })) }
    }
}
$ui.CcPrgGrid.Add_SelectionChanged({ param($s, $e) if ($e.OriginalSource -eq $s) { Show-CcPrgInfo } })
$ui.CcPrgFilter.Add_TextChanged({ Update-CcPrgFilter })
$ui.CcPrgKind.Add_SelectionChanged({ if ($script:CcPrgRows) { Update-CcPrgFilter } })
$ui.BtnCcPrgRefresh.Add_Click({ Update-CcPrograms })
$ui.BtnCcPrgUninst.Add_Click({ try { Start-CcUninstall } catch { $script:CcPrgBusy = $false; Show-UiError ('Nicht möglich: ' + $_.Exception.Message) } })
$ui.BtnCcPrgLeft.Add_Click({ try { Start-CcLeftovers $ui.CcPrgGrid.SelectedItem } catch { Show-UiError ('Nicht möglich: ' + $_.Exception.Message) } })
$ui.BtnCcPrgOrphan.Add_Click({ try { Remove-CcOrphanUi } catch { Show-UiError ('Nicht möglich: ' + $_.Exception.Message) } })
$ui.BtnCcLeftRemove.Add_Click({ try { Remove-CcLeftoversUi } catch { Show-UiError ('Nicht möglich: ' + $_.Exception.Message) } })
$ui.BtnCcLeftClose.Add_Click({ $ui.CcLeftCard.Visibility = 'Collapsed' })

# ---------------------------------------------------------------- Nicht genutzte Programme
$script:UnRun = {
    if ($script:CcPrgBusy) { Show-UiError 'Es läuft bereits eine Deinstallation - bitte warten.'; return }
    $days = @(5, 7, 14, 30, 60, 90, 180, 365, 730)[[math]::Max(0, $ui.UnDays.SelectedIndex)]; $script:UnDaysLast = $days
    $ui.BtnUnScan.IsEnabled = $false; $ui.BtnUnRemove.IsEnabled = $false; $ui.UnProg.Visibility = 'Visible'; $ui.UnState.Text = 'Suche nicht genutzte Programme ... (wertet Programmstarts aller Benutzer aus, ca. 10-30 Sekunden)'
    Invoke-Bg -Script { param($d, $rx) $UnusedProtect = $rx; Get-UnusedPrograms $d } -Arguments @($days, $UnusedProtect) -Functions (@('Get-ProgUsageMap', 'Get-ProgExeNames', 'Get-SilentUninstallCmd', 'Get-UnusedPrograms') + $CcBgFunctions) -Done {
        param($r, $err)
        $ui.BtnUnScan.IsEnabled = $true; $ui.UnProg.Visibility = 'Collapsed'
        if ($err) { $ui.UnState.Text = 'Suche fehlgeschlagen: ' + $err.Message; return }
        $rows = @($r | ForEach-Object { $_ } | Where-Object { $_ -and $_.PSObject.Properties['Prog'] })
        Set-GridItems $ui.UnGrid $rows
        $sel = @($rows | Where-Object { $_.Sel })
        $ui.BtnUnRemove.IsEnabled = [bool]$rows.Count
        $ui.UnState.Text = if ($rows.Count) { ('{0} Programme gefunden, {1} davon vorausgewählt (Nutzung sicher erkannt). Häkchen bei Bedarf anpassen, dann "Angehakte jetzt entfernen".' -f $rows.Count, $sel.Count) + $(if ($script:UnDaysLast -lt 30) { ' Achtung: kurzer Zeitraum - darunter können auch Programme sein, die du nur selten brauchst. Liste bitte kurz prüfen.' } else { '' }) } else { 'Keine nicht genutzten Programme gefunden.' }
    }
}
$ui.BtnUnScan.Add_Click({ & $script:UnRun })
$ui.BtnUnRemove.Add_Click({
    $sel = @($ui.UnGrid.ItemsSource | Where-Object { $_.Sel })
    if (-not $sel.Count) { Show-UiError 'Bitte die zu entfernenden Programme anhaken.'; return }
    $manual = @($sel | Where-Object { -not $_.Silent })
    $list = (@($sel | Select-Object -First 25 | ForEach-Object { '  - ' + $_.Name + $(if ($_.SizeText) { ' (' + $_.SizeText + ')' } else { '' }) }) -join "`n") + $(if ($sel.Count -gt 25) { "`n  ... und {0} weitere" -f ($sel.Count - 25) } else { '' })
    if (-not (Confirm-Ui ("Diese {0} Programme jetzt entfernen?`n`n{1}`n`nDanach läuft alles ohne weitere Rückfrage durch: Wiederherstellungspunkt, stille Deinstallation, Reste (Ordner in den Papierkorb, Registry mit Sicherung) und verwaiste Verknüpfungen.{2}" -f $sel.Count, $list, $(if ($manual.Count) { "`n`nHinweis: {0} davon lassen sich nicht still entfernen und werden übersprungen." -f $manual.Count } else { '' })) 'Warning')) { return }
    $script:CcPrgBusy = $true
    $ui.BtnUnScan.IsEnabled = $false; $ui.BtnUnRemove.IsEnabled = $false; $ui.UnProg.Visibility = 'Visible'
    $ui.UnState.Text = 'Entferne {0} Programme ... (bitte nicht ausschalten; je Programm meist unter einer Minute)' -f $sel.Count; $ui.UnOut.Text = ''
    $dir = Join-Path $CcRegBackupRoot ((Get-Date -Format 'yyyyMMdd_HHmmss') + '_Ungenutzte-Programme')
    Invoke-Bg -Script { param($items, $dir) Invoke-UnusedUninstall $items $dir } -Arguments @(@($sel), $dir) -Functions (@('Get-SilentUninstallCmd', 'Remove-ProgShortcuts', 'Invoke-UnusedUninstall') + $CcBgFunctions) -Done {
        param($r, $err)
        $script:CcPrgBusy = $false; $ui.UnProg.Visibility = 'Collapsed'; $ui.BtnUnScan.IsEnabled = $true
        if ($err) { $ui.UnState.Text = 'Fehler: ' + $err.Message; return }
        $t = [string]@($r | Where-Object { $_ -is [string] })[-1]
        $ui.UnOut.Text = $t; $ui.UnState.Text = ($t -split "`r?`n")[0]
        try { $script:CcLoaded['CcNavPrg'] = $false; Update-CcPrograms; Update-CcRegBackups } catch { }
        & $script:UnRun
    }
})
$ui.BtnCcPrgModify.Add_Click({
    $p = $ui.CcPrgGrid.SelectedItem; if (-not $p -or -not $p.CanModify) { return }
    try { $sp = Split-CcCommand $p.Modify; if ($sp[1]) { Start-Process -FilePath $sp[0] -ArgumentList $sp[1] } else { Start-Process -FilePath $sp[0] } } catch { Show-UiError ('Ändern nicht möglich: ' + $_.Exception.Message) }
})
$ui.BtnCcPrgRepair.Add_Click({
    $p = $ui.CcPrgGrid.SelectedItem; if (-not $p -or -not $p.CanRepair) { return }
    if (-not (Confirm-Ui ('"{0}" reparieren?{1}{1}Windows Installer prüft alle Dateien und Registry-Einträge des Programms und ersetzt fehlende oder beschädigte (msiexec /fomus). Unter Umständen wird der Installationsdatenträger verlangt.' -f $p.Name, [Environment]::NewLine))) { return }
    try { Start-Process -FilePath (Join-Path $env:SystemRoot 'System32\msiexec.exe') -ArgumentList ('/fomus {0}' -f $p.Guid); $ui.StatusText.Text = 'Reparatur gestartet: ' + $p.Name } catch { Show-UiError ('Reparatur nicht möglich: ' + $_.Exception.Message) }
})
$ui.BtnCcPrgAppwiz.Add_Click({ $p = $ui.CcPrgGrid.SelectedItem; if ($p -and $p.Kind -eq 'Store-App') { Start-Process 'ms-settings:appsfeatures' } else { Start-Process (Join-Path $env:SystemRoot 'System32\control.exe') 'appwiz.cpl' } })

# ---- Browser-Erweiterungen
function Update-CcExtFilter {
    $script:FCcExt = $ui.CcExtFilter.Text.Trim()
    Set-GridFilter $ui.CcExtGrid { param($o) Test-Match $o $script:FCcExt @('Name', 'Browser', 'Profile', 'Id', 'Source') }
}
function Update-CcExtensions {
    $ui.CcExtInfo.Text = 'Erweiterungen und Startseiten werden eingelesen ...'
    Invoke-Bg -Script { @{ Ext = @(Get-CcExtensions | ForEach-Object { $_ }); Home = @(Get-CcBrowserHome | ForEach-Object { $_ }) } } -Functions $CcBgFunctions -Done {
        param($r, $err)
        if ($err) { $ui.CcExtInfo.Text = 'Fehler: ' + $err.Message; return }
        $h = @($r | Where-Object { $_ -is [hashtable] }) | Select-Object -First 1
        if (-not $h) { $ui.CcExtInfo.Text = 'Keine Daten.'; return }
        $script:CcExtRows = @($h.Ext | Sort-Object Browser, Profile, Name)
        Set-GridItems $ui.CcExtGrid $script:CcExtRows
        Update-CcExtFilter
        Set-GridItems $ui.CcHijGrid @($h.Home)
        $warn = @($script:CcExtRows | Where-Object { $_.Level -eq 'Warn' }).Count
        $hij = @($h.Home | Where-Object { $_.Level -eq 'Warn' }).Count
        $ui.CcExtInfo.Text = '{0} Erweiterungen in {1} Browser-Profilen{2}{3}. Erweiterung auswählen für Details.' -f $script:CcExtRows.Count, @($h.Home).Count, $(if ($warn) { (' - {0} nicht aus dem offiziellen Store (orange)' -f $warn) } else { '' }), $(if ($hij) { ('; {0} Profil(e) mit auffälliger Start-/Suchseite' -f $hij) } else { '' })
        if ($script:CcCounts) { $script:CcCounts.Extensions = $script:CcExtRows.Count; Update-CcTiles }
    }
}
$ui.CcExtGrid.Add_SelectionChanged({ param($s, $e)
    if ($e.OriginalSource -ne $s) { return }
    $x = $ui.CcExtGrid.SelectedItem; if (-not $x) { return }
    $l = @(('{0} {1} - {2}, Profil {3}, {4}' -f $x.Name, $x.Version, $x.Browser, $x.Profile, $x.StatusText), ('ID: {0} · Quelle: {1}' -f $x.Id, $(if ($x.Source) { $x.Source } else { 'unbekannt' })))
    if ($x.Desc) { $l += 'Beschreibung: ' + $x.Desc }
    if ($x.Perms) { $l += 'Berechtigungen: ' + $x.Perms }
    if ($x.Path) { $l += 'Ordner: ' + $x.Path }
    if ($x.Level -eq 'Warn') { $l += 'Hinweis: nicht aus dem offiziellen Store installiert - kennen Sie diese Erweiterung nicht, entfernen.' }
    $ui.CcExtInfo.Text = $l -join [Environment]::NewLine
})
$ui.CcExtFilter.Add_TextChanged({ Update-CcExtFilter })
$ui.BtnCcExtScan.Add_Click({ Update-CcExtensions })
$ui.BtnCcExtOpen.Add_Click({
    $x = $ui.CcExtGrid.SelectedItem
    $k = if ($x) { $x.BrowserKey } else { 'Edge' }
    $m = @{ Edge = @('msedge.exe', 'edge://extensions'); Chrome = @('chrome.exe', 'chrome://extensions'); Brave = @('brave.exe', 'brave://extensions'); Vivaldi = @('vivaldi.exe', 'vivaldi://extensions'); Opera = @('opera.exe', 'opera://extensions'); OperaGX = @('opera.exe', 'opera://extensions'); Firefox = @('firefox.exe', 'about:addons') }
    try { Start-Process -FilePath $m[$k][0] -ArgumentList $m[$k][1] } catch { Show-UiError ('Browser ließ sich nicht starten: ' + $_.Exception.Message + ' - bitte die Adresse ' + $m[$k][1] + ' im Browser eingeben.') }
})
$ui.BtnCcExtRemove.Add_Click({
    $x = $ui.CcExtGrid.SelectedItem
    if (-not $x) { Show-UiError 'Bitte eine Erweiterung auswählen.'; return }
    if ($x.Kind -eq 'Firefox') {
        if (Confirm-Ui 'Firefox-Erweiterungen entfernt man am sichersten in Firefox selbst: about:addons > Erweiterung > ... > Entfernen. Firefox jetzt mit dieser Seite öffnen?') { try { Start-Process -FilePath 'firefox.exe' -ArgumentList 'about:addons' } catch { Show-UiError ('Firefox ließ sich nicht starten: ' + $_.Exception.Message) } }
        return
    }
    if (-not (Confirm-Ui ('Erweiterung "{0}" aus {1} (Profil {2}) entfernen?{3}{3}Der Erweiterungsordner kommt in den Papierkorb. Ist die Synchronisierung des Browsers eingeschaltet, kann die Erweiterung zurückkommen - dann zusätzlich im Browser unter Erweiterungen entfernen. Wird sie per Richtlinie erzwungen, installiert der Browser sie neu.' -f $x.Name, $x.Browser, $x.Profile, [Environment]::NewLine))) { return }
    $close = $false
    if (@(Get-Process -Name $x.Proc -ErrorAction SilentlyContinue).Count) {
        if (-not (Confirm-Ui ('{0} läuft noch und muss dafür geschlossen werden. Jetzt schließen? (Offene Tabs werden beim nächsten Start je nach Einstellung wiederhergestellt.)' -f $x.Browser))) { return }
        $close = $true
    }
    $script:CcPendingExt = $x
    $ui.CcExtInfo.Text = 'Entferne ...'
    Invoke-Bg -Script {
        param($row, $close)
        if ($close) {
            foreach ($p in @(Get-Process -Name $row.Proc -ErrorAction SilentlyContinue)) { try { if ($p.MainWindowHandle -ne [IntPtr]::Zero) { [void]$p.CloseMainWindow() } } catch { } }
            $sw = [Diagnostics.Stopwatch]::StartNew()
            while ($sw.Elapsed.TotalSeconds -lt 8 -and @(Get-Process -Name $row.Proc -ErrorAction SilentlyContinue).Count) { Start-Sleep -Milliseconds 500 }
            Get-Process -Name $row.Proc -ErrorAction SilentlyContinue | Stop-Process -Force -ErrorAction SilentlyContinue
            Start-Sleep -Seconds 1
        }
        Remove-CcExtension $row
    } -Arguments @($x, $close) -Functions $CcBgFunctions -Done {
        param($r, $err)
        if ($err) { Show-UiError ('Entfernen nicht möglich: ' + $err.Message); $ui.CcExtInfo.Text = ''; return }
        $ui.StatusText.Text = 'Erweiterung "{0}" entfernt (Papierkorb).' -f $script:CcPendingExt.Name
        Update-CcExtensions
    }
})

# ---- Kontextmenü
function Update-CcCtxFilter {
    $script:FCcCtx = $ui.CcCtxFilter.Text.Trim()
    Set-GridFilter $ui.CcCtxGrid { param($o) Test-Match $o $script:FCcCtx @('Name', 'Where', 'Company', 'Target') }
}
function Update-CcContext {
    $on = Test-Path -LiteralPath 'HKCU:\Software\Classes\CLSID\{86ca1aa0-34aa-4e8b-a509-50c905bae2a2}\InprocServer32'
    $ui.CcCtxClassic.Text = $(if ($on) { 'Das klassische, vollständige Kontextmenü ist eingeschaltet.' } else { 'Aktiv ist das kurze Windows-11-Menü - Einträge von Programmen stehen unter "Weitere Optionen anzeigen".' })
    $ui.CcCtxInfo.Text = 'Kontextmenü wird eingelesen ...'
    Invoke-Bg -Script { param($ms) Get-CcContextItems $ms } -Arguments @([bool]$ui.CcCtxMs.IsChecked) -Functions $CcBgFunctions -Done {
        param($r, $err)
        if ($err) { $ui.CcCtxInfo.Text = 'Fehler: ' + $err.Message; return }
        $script:CcCtxRows = @($r | ForEach-Object { $_ } | Where-Object { $_ -and $_.PSObject.Properties['Kind'] } | Sort-Object Where, Name)
        Set-GridItems $ui.CcCtxGrid $script:CcCtxRows
        Update-CcCtxFilter
        $off = @($script:CcCtxRows | Where-Object { -not $_.Enabled }).Count
        $ui.CcCtxInfo.Text = '{0} Einträge{1}{2}. Mehrere markieren mit Strg/Umschalt.' -f $script:CcCtxRows.Count, $(if ($ui.CcCtxMs.IsChecked) { ' (inkl. Windows)' } else { ' von Drittherstellern' }), $(if ($off) { (', davon {0} ausgeblendet (grau)' -f $off) } else { '' })
    }
}
function Set-CcContextUi([bool]$Enable) {
    $sel = @($ui.CcCtxGrid.SelectedItems)
    if (-not $sel.Count) { Show-UiError 'Bitte einen oder mehrere Einträge markieren.'; return }
    if (-not $Enable -and @($sel | Where-Object { $_.Ms }).Count -and -not (Confirm-Ui 'Unter der Auswahl sind Windows-Einträge. Ausblenden kann Funktionen im Explorer verstecken (z.B. Senden an, Teilen). Trotzdem ausblenden?' 'Warning')) { return }
    $n = 0; $errs = @()
    foreach ($x in $sel) { try { Set-CcContextItem $x $Enable; $n++ } catch { $errs += ('{0}: {1}' -f $x.Name, $_.Exception.Message) } }
    $ui.StatusText.Text = '{0} Einträge {1} - wirkt nach "Explorer neu starten".' -f $n, $(if ($Enable) { 'eingeblendet' } else { 'ausgeblendet' })
    if ($errs.Count) { Show-UiError ($errs -join [Environment]::NewLine) }
    Update-CcContext
}
$ui.CcCtxFilter.Add_TextChanged({ Update-CcCtxFilter })
$ui.CcCtxMs.Add_Click({ Update-CcContext })
$ui.BtnCcCtxScan.Add_Click({ Update-CcContext })
$ui.BtnCcCtxOff.Add_Click({ Set-CcContextUi $false })
$ui.BtnCcCtxOn.Add_Click({ Set-CcContextUi $true })
$ui.BtnCcCtxExplorer.Add_Click({ if (Confirm-Ui 'Explorer jetzt neu starten? Taskleiste und offene Explorer-Fenster verschwinden kurz.') { try { Restart-ExplorerShell; $ui.StatusText.Text = 'Explorer neu gestartet.' } catch { Show-UiError $_.Exception.Message } } })
$ui.CcCtxGrid.Add_SelectionChanged({ param($s, $e)
    if ($e.OriginalSource -ne $s) { return }
    $x = $ui.CcCtxGrid.SelectedItem; if (-not $x) { return }
    $ui.CcCtxInfo.Text = '{0} - {1}, {2} ({3}){4}{5}{4}Registry: {6}\{7}{8}' -f $x.Name, $x.Kind, $x.Where, $x.StatusText, [Environment]::NewLine, $(if ($x.Target) { 'Ziel: ' + $x.Target } else { '' }), $x.Hive, $x.KeyPath, $(if ($x.Clsid) { ' · CLSID ' + $x.Clsid } else { '' })
})

# ---- Geplante Aufgaben
function Update-CcTaskFilter {
    $script:FCcTask = $ui.CcTaskFilter.Text.Trim()
    Set-GridFilter $ui.CcTaskGrid { param($o) Test-Match $o $script:FCcTask @('Name', 'Path', 'Author', 'Action', 'Trigger') }
}
function Update-CcTasks {
    $ui.CcTaskInfo.Text = 'Aufgaben werden eingelesen ...'
    Invoke-Bg -Script { Get-CcTasks } -Functions $CcBgFunctions -Done {
        param($r, $err)
        if ($err) { $ui.CcTaskInfo.Text = 'Fehler: ' + $err.Message; return }
        $script:CcTaskRows = @($r | ForEach-Object { $_ } | Where-Object { $_ -and $_.PSObject.Properties['Trigger'] } | Sort-Object Path, Name)
        Set-GridItems $ui.CcTaskGrid $script:CcTaskRows
        Update-CcTaskFilter
        $miss = @($script:CcTaskRows | Where-Object { $_.Missing }).Count
        $ui.CcTaskInfo.Text = '{0} Aufgaben anderer Hersteller{1}. Aufgabe auswählen für Details.' -f $script:CcTaskRows.Count, $(if ($miss) { (' - {0} starten ein Programm, das nicht mehr existiert (rot)' -f $miss) } else { '' })
    }
}
function Invoke-CcTaskAction([string]$Act) {
    $t = $ui.CcTaskGrid.SelectedItem
    if (-not $t) { Show-UiError 'Bitte eine Aufgabe auswählen.'; return }
    if ($t.Own -and $Act -ne 'Run') { Show-UiError 'Das ist eine Aufgabe von PC-Tools selbst - bitte über die Seiten Zeitplan bzw. Einstellungen steuern.'; return }
    try {
        switch ($Act) {
            'Run' { Start-ScheduledTask -TaskName $t.Name -TaskPath $t.Path -ErrorAction Stop }
            'On'  { $null = Enable-ScheduledTask -TaskName $t.Name -TaskPath $t.Path -ErrorAction Stop }
            'Off' { $null = Disable-ScheduledTask -TaskName $t.Name -TaskPath $t.Path -ErrorAction Stop }
            'Del' {
                if (-not (Confirm-Ui ('Aufgabe "{0}" löschen?{1}{1}Aktion: {2}{1}Vorher wird sie als XML gesichert (Datenordner\Aufgaben-Sicherung). Wenn Sie nur verhindern wollen, dass sie läuft, genügt "Deaktivieren".' -f $t.Name, [Environment]::NewLine, $t.Action) 'Warning')) { return }
                New-Item -Path $CcTaskBackupDir -ItemType Directory -Force -ErrorAction SilentlyContinue | Out-Null
                $file = Join-Path $CcTaskBackupDir ('{0}_{1:yyyyMMdd_HHmmss}.xml' -f ($t.Name -replace '[^A-Za-z0-9_\-\. ]', '_'), (Get-Date))
                Export-ScheduledTask -TaskName $t.Name -TaskPath $t.Path -ErrorAction Stop | Set-Content -LiteralPath $file -Encoding Unicode
                if (-not (Test-Path -LiteralPath $file) -or (Get-Item -LiteralPath $file).Length -lt 50) { throw 'Sicherung fehlgeschlagen - Aufgabe wurde nicht gelöscht.' }
                Unregister-ScheduledTask -TaskName $t.Name -TaskPath $t.Path -Confirm:$false -ErrorAction Stop
            }
        }
        $ui.StatusText.Text = 'Aufgabe "{0}": {1}' -f $t.Name, $(switch ($Act) { 'Run' { 'gestartet' } 'On' { 'aktiviert' } 'Off' { 'deaktiviert' } default { 'gelöscht (gesichert)' } })
    } catch { Show-UiError ('Nicht möglich: ' + $_.Exception.Message) }
    Update-CcTasks
}
$ui.CcTaskGrid.Add_SelectionChanged({ param($s, $e)
    if ($e.OriginalSource -ne $s) { return }
    $t = $ui.CcTaskGrid.SelectedItem; if (-not $t) { return }
    $l = @(('{0}{1} - {2}' -f $t.Path, $t.Name, $t.StateText), ('Aktion: ' + $t.Action), ('Auslöser: ' + $t.Trigger), ('Konto: ' + $t.Account + $(if ($t.Author) { ' · Hersteller/Autor: ' + $t.Author } else { '' })))
    if ($t.Desc) { $l += 'Beschreibung: ' + $t.Desc }
    if ($t.Missing) { $l += 'Das gestartete Programm existiert nicht mehr - die Aufgabe ist ein Rest und kann gelöscht werden.' }
    if ($t.Own) { $l += 'Aufgabe von PC-Tools - geschützt.' }
    $ui.CcTaskInfo.Text = $l -join [Environment]::NewLine
})
$ui.CcTaskFilter.Add_TextChanged({ Update-CcTaskFilter })
$ui.BtnCcTaskRefresh.Add_Click({ Update-CcTasks })
$ui.BtnCcTaskRun.Add_Click({ Invoke-CcTaskAction 'Run' })
$ui.BtnCcTaskOn.Add_Click({ Invoke-CcTaskAction 'On' })
$ui.BtnCcTaskOff.Add_Click({ Invoke-CcTaskAction 'Off' })
$ui.BtnCcTaskDel.Add_Click({ Invoke-CcTaskAction 'Del' })
$ui.BtnCcTaskMmc.Add_Click({ Start-Process (Join-Path $env:SystemRoot 'System32\taskschd.msc') })

# ---- Laufwerk säubern
function Update-CcDrives {
    $ui.CcWipeInfo.Text = 'Laufwerke werden eingelesen ...'
    Invoke-Bg -Script { Get-CcDrives } -Functions $CcBgFunctions -Done {
        param($r, $err)
        if ($err) { $ui.CcWipeInfo.Text = 'Fehler: ' + $err.Message; return }
        Set-GridItems $ui.CcWipeGrid @($r | ForEach-Object { $_ } | Where-Object { $_ -and $_.PSObject.Properties['Letter'] })
        $ui.CcWipeInfo.Text = 'Laufwerk in der Liste auswählen.'
    }
}
$ui.CcWipeGrid.Add_SelectionChanged({ param($s, $e)
    if ($e.OriginalSource -ne $s) { return }
    $d = $ui.CcWipeGrid.SelectedItem; if (-not $d) { return }
    $ui.CcWipeInfo.Text = '{0}: {1} - {2}, {3}, {4} frei von {5}{6}{7}' -f $d.Letter, $(if ($d.Label) { $d.Label } else { 'ohne Namen' }), $d.Media, $d.FileSystem, $d.FreeText, $d.SizeText, [Environment]::NewLine, $d.Advice
    $ui.BtnCcWipeTrim.IsEnabled = [bool]$d.FsOk; $ui.BtnCcWipeRun.IsEnabled = [bool]$d.FsOk
})
$ui.BtnCcWipeRefresh.Add_Click({ Update-CcDrives })
$ui.BtnCcWipeTrim.Add_Click({
    $d = $ui.CcWipeGrid.SelectedItem
    if (-not $d) { Show-UiError 'Bitte ein Laufwerk auswählen.'; return }
    if (-not $d.IsSsd -and -not (Confirm-Ui ('Laufwerk {0}: wurde nicht als SSD erkannt ({1}). TRIM wirkt nur bei SSDs und virtuellen Datenträgern - bei Festplatten meldet Windows einen Fehler. Trotzdem versuchen?' -f $d.Letter, $d.Media))) { return }
    $ui.CcWipeProg.Visibility = 'Visible'; $ui.CcWipeInfo.Text = 'TRIM läuft auf {0}: ...' -f $d.Letter
    Set-CcBusyUi @('BtnCcWipeTrim', 'BtnCcWipeRun') $true
    Invoke-Bg -Script { param($l) Optimize-Volume -DriveLetter $l -ReTrim -ErrorAction Stop; $l } -Arguments @([string]$d.Letter) -Done {
        param($r, $err)
        $ui.CcWipeProg.Visibility = 'Collapsed'
        Set-CcBusyUi @('BtnCcWipeTrim', 'BtnCcWipeRun') $false
        if ($err) { $ui.CcWipeInfo.Text = 'TRIM nicht möglich: ' + $err.Message; return }
        $ui.CcWipeInfo.Text = 'TRIM auf {0}: abgeschlossen - die SSD hat alle freien Bereiche als ungenutzt gemeldet bekommen und löscht sie intern.' -f (@($r)[-1])
        $ui.StatusText.Text = $ui.CcWipeInfo.Text
    }
})
$ui.BtnCcWipeRun.Add_Click({
    $d = $ui.CcWipeGrid.SelectedItem
    if (-not $d) { Show-UiError 'Bitte ein Laufwerk auswählen.'; return }
    if (-not $d.FsOk) { Show-UiError ('Laufwerk {0}: hat das Dateisystem {1} - cipher /w wird nur für NTFS und ReFS unterstützt.' -f $d.Letter, $d.FileSystem); return }
    if ($script:Job) { Show-UiError 'Es läuft bereits eine Aufgabe - bitte warten, bis sie fertig ist.'; return }
    if ($d.IsSsd -and -not (Confirm-Ui ('Laufwerk {0}: ist eine SSD.{1}{1}Überschreiben erreicht auf SSDs wegen der internen Verteilung der Schreibzugriffe nicht alle alten Daten und kostet Lebensdauer (hier ca. {2} zusätzliche Schreibmenge). Empfohlen ist stattdessen "TRIM jetzt ausführen".{1}{1}Trotzdem überschreiben?' -f $d.Letter, [Environment]::NewLine, (Format-CcSize ([double]$d.Free * 3))) 'Warning')) { return }
    if (-not (Confirm-Ui ('Freien Speicher auf {0}: ({1} frei) jetzt dreimal überschreiben?{2}{2}Vorhandene Dateien bleiben unberührt. Das Laufwerk ist währenddessen zeitweise fast voll. {3}{2}Läuft im Hintergrund weiter, auch wenn PC-Tools geschlossen wird; Abbrechen auf der Protokoll-Seite.' -f $d.Letter, $d.FreeText, [Environment]::NewLine, $d.Advice) 'Warning')) { return }
    Start-Run -Parts @('CleanerWipe') -Job @{ Drive = [string]$d.Letter }
    $script:CcJobWatch = $true
})

