# ---------------------------------------------------------------- PC-Tools 10 (Team D): Ein-Klick-Optimierung (Übersicht)
$RunButtons = @($RunButtons) + 'BtnOkStart' + 'BtnOkAuto'
$script:OkTrack = $null
$script:OkLast = $null
$script:OkJump = ''
$script:OkSpin = $null
$OkStateStyle = @{
    wait   = @('#EEF2F8', '#6B7890', 0xE91F)
    run    = @('#DCE8FF', '#2D7FF9', 0xE895)
    ok     = @('#DCFCE7', '#16A34A', 0xE73E)
    warn   = @('#FFEDD5', '#EA580C', 0xE7BA)
    skip   = @('#F7F9FC', '#9AA5B8', 0xE738)
    cancel = @('#F7F9FC', '#9AA5B8', 0xE711)
}
function Get-OkPlanPhases {
    $sel = @{ Windows = [bool]$ui.OneClick_Updates.IsChecked; Drivers = [bool]$ui.OneClick_Drivers.IsChecked; Programs = [bool]$ui.OneClick_Programs.IsChecked; Repair = [bool]$ui.OneClick_Repair.IsChecked; AutoRepair = [bool]$ui.OneClick_AutoRepair.IsChecked; Restore = [bool]$(if ($ui.Optimize_RestorePoint) { $ui.Optimize_RestorePoint.IsChecked } else { $true }) }
    foreach ($d in (Get-OkPhaseDefs)) {
        $on = $true; if ($sel.ContainsKey($d[0])) { $on = $sel[$d[0]] }
        [pscustomobject]@{ Key = $d[0]; Title = $d[1]; State = $(if ($on) { 'wait' } else { 'skip' }); Info = $(if ($on) { '' } else { 'abgewählt' }); Glyph = $d[3] }
    }
}
function Show-OkPhases([object[]]$Phases) {
    $ui.OkPhases.Children.Clear()
    foreach ($p in @($Phases | Where-Object { $_ })) {
        $sty = $OkStateStyle[[string]$p.State]; if (-not $sty) { $sty = $OkStateStyle['wait'] }
        $b = New-Object Windows.Controls.Border
        $b.CornerRadius = '12'; $b.Padding = '9,3,11,4'; $b.Margin = '0,0,6,6'; $b.Background = New-UiBrush $sty[0]
        $sp = New-Object Windows.Controls.StackPanel; $sp.Orientation = 'Horizontal'
        $g = New-Object Windows.Controls.TextBlock; $g.FontFamily = 'Segoe MDL2 Assets'; $g.FontSize = 11; $g.Text = [string][char][int]$sty[2]; $g.Foreground = New-UiBrush $sty[1]; $g.VerticalAlignment = 'Center'; $g.Margin = '0,1,6,0'
        $t = New-Object Windows.Controls.TextBlock; $t.Text = [string]$p.Title; $t.FontSize = 12; $t.Foreground = New-UiBrush $sty[1]; $t.VerticalAlignment = 'Center'
        if ([string]$p.State -eq 'run') { $t.FontWeight = 'SemiBold' }
        if ([string]$p.State -in 'skip', 'cancel') { $t.TextDecorations = [Windows.TextDecorations]::Strikethrough }
        [void]$sp.Children.Add($g); [void]$sp.Children.Add($t); $b.Child = $sp
        $tip = [string]$p.Title; if ($p.Info) { $tip += ': ' + [string]$p.Info }
        $b.ToolTip = $tip
        [void]$ui.OkPhases.Children.Add($b)
    }
}
function Read-OkLast {
    $f = Join-Path (Join-Path $DataDir 'EinKlick') 'letzter.json'
    if (-not (Test-Path -LiteralPath $f)) { return $null }
    try { return (Get-Content -LiteralPath $f -Raw -Encoding UTF8 | ConvertFrom-Json) } catch { return $null }
}
function Update-OkLast {
    $script:OkLast = Read-OkLast
    $r = $script:OkLast
    if (-not $r) { $ui.OkLastScore.Text = '-'; $ui.OkLastText.Text = 'noch nie ausgeführt - ein Klick auf den runden Knopf genügt.'; $ui.BtnOkReport.IsEnabled = $false; return }
    $b = [int]$r.ScoreBefore.Score; $a = [int]$r.ScoreAfter.Score; $d = $a - $b
    $ui.OkLastScore.Text = '{0} → {1}' -f $b, $a
    $ui.OkLastScore.Foreground = New-UiBrush (Get-ScColor ([double]$a))
    $when = ''; try { $when = ([datetime]$r.Start).ToString('dd.MM.yyyy HH:mm') } catch { }
    $ui.OkLastText.Text = ('{0}{1} · {2} Punkte · {3} frei · {4} Update(s) · {5} offen{6}' -f $when, $(if ($r.Auto) { ' (automatisch)' } else { '' }), $(if ($d -gt 0) { '+' + $d } else { [string]$d }), $r.FreedText, [int]$r.Updates, @($r.Remaining).Count, $(if ($r.Cancelled) { ' · abgebrochen' } else { '' }))
    $ui.BtnOkReport.IsEnabled = $true
}
function Update-OkSchedInfo {
    if (-not $ui.Schedule_OneClick.IsChecked) { $ui.OkSchedInfo.Text = ''; return }
    $fr = ''; $dy = ''; try { $fr = [string]$ui.Schedule_Frequency.SelectedItem.Content } catch { }; try { $dy = [string]$ui.Schedule_Day.SelectedItem.Content } catch { }
    $tm = ''; try { $tm = $ui.Schedule_Time.Text.Trim() } catch { }
    $on = $true; try { $on = [bool]$ui.Schedule_Enabled.IsChecked } catch { }
    $ui.OkSchedInfo.Text = if (-not $on) { 'Zeitplan ist aus - auf der Seite Zeitplan einschalten.' } elseif ($fr -eq 'Täglich') { 'läuft täglich um {0} Uhr' -f $tm } elseif ($fr) { 'läuft {0}, {1} um {2} Uhr' -f $fr.ToLower(), $dy, $tm } else { 'läuft nach dem Zeitplan' }
}
function Set-OkRunUi([bool]$Running) {
    $ui.OkRunPanel.Visibility = $(if ($Running) { 'Visible' } else { 'Collapsed' })
    $ui.BtnOkCancel.Visibility = $(if ($Running) { 'Visible' } else { 'Collapsed' })
    $ui.OkBtnText.Text = $(if ($Running) { 'läuft ...' } else { 'Optimieren' })
    $ui.OkGlyph.Text = [string][char]$(if ($Running) { 0xE895 } else { 0xE945 })
    foreach ($n in 'OneClick_Updates', 'OneClick_Drivers', 'OneClick_Programs', 'OneClick_Repair', 'OneClick_AutoRepair') { $ui[$n].IsEnabled = -not $Running }
    try {
        if ($Running) {
            $rt = New-Object Windows.Media.RotateTransform; $ui.OkGlyph.RenderTransform = $rt
            $an = New-Object Windows.Media.Animation.DoubleAnimation(0, 360, (New-Object Windows.Duration([TimeSpan]::FromSeconds(1.6))))
            $an.RepeatBehavior = [Windows.Media.Animation.RepeatBehavior]::Forever
            $rt.BeginAnimation([Windows.Media.RotateTransform]::AngleProperty, $an)
        } else { $ui.OkGlyph.RenderTransform = $null }
    } catch { }
}
function Start-OkRun {
    if ($script:Job) { Show-UiError 'Es läuft bereits eine Aufgabe von PC-Tools (siehe Protokoll). Bitte warten, bis sie fertig ist.'; return }
    $plan = @(Get-OkPlanPhases | Where-Object { $_.State -eq 'wait' } | ForEach-Object { $_.Title })
    $q = "Ein-Klick-Optimierung jetzt starten?`n`nDer Reihe nach: " + ($plan -join ' > ') + ".`n`n" +
         "Dauer meist 20-90 Minuten (Windows-Updates und Treiber am längsten). Der PC bleibt benutzbar, PC-Tools darf geschlossen werden - der Lauf geht im Hintergrund weiter. " +
         "Vor Treiber- und BIOS-Updates werden die Treiber automatisch gesichert. Neu gestartet wird nicht ohne Rückfrage."
    if (-not (Confirm-Ui $q)) { return }
    try { Remove-Item -LiteralPath (Join-Path (Join-Path $DataDir 'EinKlick') 'phasen.json') -Force -ErrorAction SilentlyContinue } catch { }
    try {
        Start-Run -Parts @('OneClick') -Job @{ Updates = [bool]$ui.OneClick_Updates.IsChecked; Drivers = [bool]$ui.OneClick_Drivers.IsChecked; Programs = [bool]$ui.OneClick_Programs.IsChecked; Repair = [bool]$ui.OneClick_Repair.IsChecked; AutoRepair = [bool]$ui.OneClick_AutoRepair.IsChecked }
    } catch { Show-UiError ('Start fehlgeschlagen: ' + $_.Exception.Message); return }
    if (-not $script:Job) { return }
    $ui.Tabs.SelectedItem = $ui.TabOverview
    $script:OkTrack = @{ Log = [string]$script:Job.Log; Status = [string]$script:Job.Status; Start = Get-Date }
    $ui.OkBar.Value = 0; $ui.OkStatus.Text = 'Wird gestartet ...'; $ui.OkDetail.Text = ''
    Set-OkRunUi $true
    Show-OkPhases @(Get-OkPlanPhases)
    $script:OkTimer.Start()
    try { $ui.OkCard.BringIntoView() } catch { }
}
$script:OkTimer = New-Object Windows.Threading.DispatcherTimer
$script:OkTimer.Interval = [TimeSpan]::FromMilliseconds(800)
$script:OkTimer.Add_Tick({
    $t = $script:OkTrack
    if (-not $t) { $script:OkTimer.Stop(); return }
    try {
        if ([IO.File]::Exists($t.Status)) {
            $ost = [IO.File]::ReadAllText($t.Status) | ConvertFrom-Json
            $ui.OkBar.Value = [double]$ost.Progress
            if ($ost.Status) { $ui.OkStatus.Text = ('{0}   ({1:N0} %, seit {2})' -f [string]$ost.Status, [double]$ost.Progress, (Format-Dur ((Get-Date) - $t.Start))) }
            $dt = @(); if ($ost.Detail) { $dt += [string]$ost.Detail }; if ($ost.LastLine -and [string]$ost.LastLine -ne [string]$ost.Detail) { $dt += [string]$ost.LastLine }
            $ui.OkDetail.Text = ($dt -join '  ·  ')
        }
        $pf = Join-Path (Join-Path $DataDir 'EinKlick') 'phasen.json'
        if ([IO.File]::Exists($pf) -and [IO.File]::GetLastWriteTime($pf) -ge $t.Start.AddSeconds(-5)) { Show-OkPhases @([IO.File]::ReadAllText($pf) | ConvertFrom-Json | ForEach-Object { $_ }) }
    } catch { }
    if ($script:Job -and [string]$script:Job.Log -eq $t.Log) { return }
    # Lauf beendet
    $script:OkTimer.Stop(); $script:OkTrack = $null
    Set-OkRunUi $false
    Update-OkLast
    $r = $script:OkLast
    $fresh = $false; try { $fresh = ($r -and [datetime]$r.Start -ge $t.Start.AddMinutes(-2)) } catch { }
    if ($fresh) {
        Show-OkPhases @($r.Phases)
        $ui.StatusText.Text = ('Ein-Klick-Optimierung fertig: Zustands-Score {0} → {1}.' -f [int]$r.ScoreBefore.Score, [int]$r.ScoreAfter.Score)
        try { Update-ScScoreUi } catch { }; try { Update-Ampel } catch { }
        try { Show-OkReport $r } catch { Show-UiError ('Bericht: ' + $_.Exception.Message) }
    } else {
        Show-OkPhases @(Get-OkPlanPhases)
        $ui.StatusText.Text = 'Ein-Klick-Optimierung beendet - kein Bericht erstellt (abgebrochen oder Fehler, siehe Protokoll).'
    }
})

# ---- Vorher/Nachher-Bericht
function Add-OkRing($Canvas, [double]$Score, [double]$Size, [string]$Color, [double]$Opacity = 1.0) {
    $Canvas.Children.Clear()
    $th = 10.0; $r = ($Size - $th) / 2; $cx = $Size / 2; $cy = $Size / 2
    $bg = New-Object Windows.Shapes.Ellipse; $bg.Width = $Size - $th; $bg.Height = $Size - $th; $bg.Stroke = (New-Object Windows.Media.BrushConverter).ConvertFromString('#FFFFFF'); $bg.Opacity = 0.22; $bg.StrokeThickness = $th
    [Windows.Controls.Canvas]::SetLeft($bg, $th / 2); [Windows.Controls.Canvas]::SetTop($bg, $th / 2); [void]$Canvas.Children.Add($bg)
    $v = [math]::Max(0.0, [math]::Min(99.99, $Score)); if ($v -le 0) { return }
    $ang = $v / 100.0 * 2 * [math]::PI
    $fig = New-Object Windows.Media.PathFigure; $fig.StartPoint = New-Object Windows.Point($cx, ($cy - $r))
    $arc = New-Object Windows.Media.ArcSegment
    $arc.Point = New-Object Windows.Point(($cx + $r * [math]::Sin($ang)), ($cy - $r * [math]::Cos($ang)))
    $arc.Size = New-Object Windows.Size($r, $r); $arc.IsLargeArc = ($v -gt 50); $arc.SweepDirection = 'Clockwise'
    [void]$fig.Segments.Add($arc)
    $geo = New-Object Windows.Media.PathGeometry; [void]$geo.Figures.Add($fig)
    $p = New-Object Windows.Shapes.Path; $p.Data = $geo; $p.Stroke = (New-Object Windows.Media.BrushConverter).ConvertFromString($Color); $p.StrokeThickness = $th; $p.StrokeStartLineCap = 'Round'; $p.StrokeEndLineCap = 'Round'; $p.Opacity = $Opacity
    [void]$Canvas.Children.Add($p)
}
function New-OkRow([string]$Glyph, [string]$Color, [string]$Title, [string]$Text, [string]$Right = '') {
    $g = New-Object Windows.Controls.Grid; $g.Margin = '0,3,0,3'
    foreach ($w in @(30, -1, -2)) { $cd = New-Object Windows.Controls.ColumnDefinition; $cd.Width = $(if ($w -eq -1) { New-Object Windows.GridLength(1, 'Star') } elseif ($w -eq -2) { [Windows.GridLength]::Auto } else { New-Object Windows.GridLength($w) }); [void]$g.ColumnDefinitions.Add($cd) }
    $ic = New-Object Windows.Controls.TextBlock; $ic.FontFamily = 'Segoe MDL2 Assets'; $ic.Text = $Glyph; $ic.FontSize = 14; $ic.Foreground = New-UiBrush $Color; $ic.Margin = '0,2,0,0'
    $sp = New-Object Windows.Controls.StackPanel; [Windows.Controls.Grid]::SetColumn($sp, 1)
    $t1 = New-Object Windows.Controls.TextBlock; $t1.Text = $Title; $t1.FontWeight = 'SemiBold'; $t1.Foreground = New-UiBrush '#1F2A44'; $t1.TextWrapping = 'Wrap'
    [void]$sp.Children.Add($t1)
    if ($Text) { $t2 = New-Object Windows.Controls.TextBlock; $t2.Text = $Text; $t2.FontSize = 12; $t2.Foreground = New-UiBrush '#6B7890'; $t2.TextWrapping = 'Wrap'; [void]$sp.Children.Add($t2) }
    [void]$g.Children.Add($ic); [void]$g.Children.Add($sp)
    if ($Right) { $t3 = New-Object Windows.Controls.TextBlock; $t3.Text = $Right; $t3.FontSize = 12; $t3.Foreground = New-UiBrush '#6B7890'; $t3.Margin = '12,2,0,0'; [Windows.Controls.Grid]::SetColumn($t3, 2); [void]$g.Children.Add($t3) }
    return $g
}
function Show-OkReport($R) {
    if (-not $R) { $R = Read-OkLast }
    if (-not $R) { Show-UiError 'Es gibt noch keinen Bericht - zuerst die Ein-Klick-Optimierung ausführen.'; return }
    $x = @'
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Title="PC-Tools - Ein-Klick-Optimierung: Vorher / Nachher" Width="1000" Height="780" MinWidth="760" MinHeight="560" WindowStartupLocation="CenterOwner" FontFamily="Segoe UI" FontSize="13" Background="#F4F6FA">
  <Window.Resources></Window.Resources>
  <Grid>
    <Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="*"/><RowDefinition Height="Auto"/></Grid.RowDefinitions>
    <Border Padding="30,22">
      <Border.Background><LinearGradientBrush StartPoint="0,0" EndPoint="1,1"><GradientStop Color="#2563EB" Offset="0"/><GradientStop Color="#6D4AE8" Offset="0.55"/><GradientStop Color="#A23FD1" Offset="1"/></LinearGradientBrush></Border.Background>
      <Grid>
        <Grid.ColumnDefinitions><ColumnDefinition Width="Auto"/><ColumnDefinition Width="Auto"/><ColumnDefinition Width="Auto"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>
        <Grid Width="120" Height="120"><Canvas x:Name="RepRingA" Width="120" Height="120"/><StackPanel VerticalAlignment="Center" HorizontalAlignment="Center"><TextBlock x:Name="RepScoreA" Text="-" FontSize="36" FontWeight="Bold" Foreground="#FFFFFF" HorizontalAlignment="Center"/><TextBlock Text="vorher" Foreground="#FFFFFF" Opacity="0.8" FontSize="12" HorizontalAlignment="Center" Margin="0,-4,0,0"/></StackPanel></Grid>
        <TextBlock Grid.Column="1" Text="&#xE72A;" FontFamily="Segoe MDL2 Assets" FontSize="26" Foreground="#FFFFFF" Opacity="0.85" VerticalAlignment="Center" Margin="18,0"/>
        <Grid Grid.Column="2" Width="120" Height="120"><Canvas x:Name="RepRingB" Width="120" Height="120"/><StackPanel VerticalAlignment="Center" HorizontalAlignment="Center"><TextBlock x:Name="RepScoreB" Text="-" FontSize="36" FontWeight="Bold" Foreground="#FFFFFF" HorizontalAlignment="Center"/><TextBlock Text="nachher" Foreground="#FFFFFF" Opacity="0.8" FontSize="12" HorizontalAlignment="Center" Margin="0,-4,0,0"/></StackPanel></Grid>
        <StackPanel Grid.Column="3" Margin="28,0,0,0" VerticalAlignment="Center">
          <TextBlock x:Name="RepKicker" Text="EIN-KLICK-OPTIMIERUNG" Foreground="#FFFFFF" Opacity="0.8" FontSize="11" FontWeight="Bold"/>
          <TextBlock x:Name="RepTitle" Text="" Foreground="#FFFFFF" FontSize="24" FontWeight="SemiBold" TextWrapping="Wrap"/>
          <TextBlock x:Name="RepSub" Text="" Foreground="#FFFFFF" Opacity="0.88" TextWrapping="Wrap" Margin="0,2,0,8"/>
          <Border x:Name="RepDelta" HorizontalAlignment="Left" CornerRadius="12" Padding="12,3" Background="#16A34A"><TextBlock x:Name="RepDeltaText" Text="" Foreground="#FFFFFF" FontWeight="SemiBold"/></Border>
        </StackPanel>
      </Grid>
    </Border>
    <ScrollViewer Grid.Row="1" VerticalScrollBarVisibility="Auto">
      <StackPanel Margin="24,16,24,10">
        <UniformGrid Columns="4" Margin="0,0,0,12">
          <Border Background="#2D7FF9" CornerRadius="12" Padding="16,12" Margin="0,0,10,0"><StackPanel><TextBlock x:Name="RepFreed" Text="-" FontSize="26" FontWeight="Bold" Foreground="#FFFFFF"/><TextBlock Text="Speicher frei geworden" Foreground="#FFFFFF" Opacity="0.92"/></StackPanel></Border>
          <Border Background="#7C3AED" CornerRadius="12" Padding="16,12" Margin="0,0,10,0"><StackPanel><TextBlock x:Name="RepUpd" Text="-" FontSize="26" FontWeight="Bold" Foreground="#FFFFFF"/><TextBlock Text="Updates installiert" Foreground="#FFFFFF" Opacity="0.92"/></StackPanel></Border>
          <Border Background="#16A34A" CornerRadius="12" Padding="16,12" Margin="0,0,10,0"><StackPanel><TextBlock x:Name="RepFix" Text="-" FontSize="26" FontWeight="Bold" Foreground="#FFFFFF"/><TextBlock Text="Probleme behoben" Foreground="#FFFFFF" Opacity="0.92"/></StackPanel></Border>
          <Border Background="#EA580C" CornerRadius="12" Padding="16,12"><StackPanel><TextBlock x:Name="RepOpen" Text="-" FontSize="26" FontWeight="Bold" Foreground="#FFFFFF"/><TextBlock Text="Empfehlungen offen" Foreground="#FFFFFF" Opacity="0.92"/></StackPanel></Border>
        </UniformGrid>
        <Border x:Name="RepReboot" Background="#FFEDD5" CornerRadius="10" Padding="16,10" Margin="0,0,0,12" Visibility="Collapsed">
          <Grid><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
            <TextBlock Text="Ein Neustart ist nötig, damit alle Updates fertig installiert werden. Danach steigt der Zustands-Score meist noch weiter." Foreground="#1F2A44" TextWrapping="Wrap" VerticalAlignment="Center"/>
            <Button x:Name="RepBtnReboot" Grid.Column="1" Content="Neu starten ..." Padding="12,5" Margin="12,0,0,0"/>
          </Grid>
        </Border>
        <Border Background="White" CornerRadius="12" Padding="18,14" Margin="0,0,0,12" BorderBrush="#E2E7F0" BorderThickness="1"><StackPanel><TextBlock Text="Noch zu tun" FontSize="16" FontWeight="SemiBold" Foreground="#1F2A44" Margin="0,0,0,6"/><StackPanel x:Name="RepRemain"/></StackPanel></Border>
        <Border Background="White" CornerRadius="12" Padding="18,14" Margin="0,0,0,12" BorderBrush="#E2E7F0" BorderThickness="1"><StackPanel><TextBlock Text="Was wurde gemacht" FontSize="16" FontWeight="SemiBold" Foreground="#1F2A44" Margin="0,0,0,6"/><StackPanel x:Name="RepPhases"/></StackPanel></Border>
        <Border Background="White" CornerRadius="12" Padding="18,14" Margin="0,0,0,12" BorderBrush="#E2E7F0" BorderThickness="1"><StackPanel><TextBlock Text="Zustands-Score im Detail" FontSize="16" FontWeight="SemiBold" Foreground="#1F2A44" Margin="0,0,0,6"/><StackPanel x:Name="RepComps"/></StackPanel></Border>
        <Border x:Name="RepFixedCard" Background="White" CornerRadius="12" Padding="18,14" Margin="0,0,0,12" BorderBrush="#E2E7F0" BorderThickness="1"><StackPanel><TextBlock Text="Behoben" FontSize="16" FontWeight="SemiBold" Foreground="#1F2A44" Margin="0,0,0,6"/><StackPanel x:Name="RepFixed"/></StackPanel></Border>
        <Border x:Name="RepDrvCard" Background="White" CornerRadius="12" Padding="18,14" Margin="0,0,0,12" BorderBrush="#E2E7F0" BorderThickness="1"><StackPanel>
          <Grid Margin="0,0,0,6"><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions><TextBlock Text="Geänderte Treiber und Firmware" FontSize="16" FontWeight="SemiBold" Foreground="#1F2A44" VerticalAlignment="Center"/><Button x:Name="RepBtnDrv" Grid.Column="1" Content="Treiber-Sicherungen öffnen" Padding="12,5"/></Grid>
          <StackPanel x:Name="RepDrv"/></StackPanel></Border>
        <Border Background="White" CornerRadius="12" Padding="18,14" Margin="0,0,0,12" BorderBrush="#E2E7F0" BorderThickness="1"><StackPanel><TextBlock Text="Sicherheit und Datensicherung" FontSize="16" FontWeight="SemiBold" Foreground="#1F2A44" Margin="0,0,0,6"/><StackPanel x:Name="RepSec"/></StackPanel></Border>
      </StackPanel>
    </ScrollViewer>
    <Border Grid.Row="2" Background="White" BorderBrush="#E2E7F0" BorderThickness="0,1,0,0" Padding="24,10">
      <Grid><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
        <TextBlock x:Name="RepFoot" Text="" Foreground="#6B7890" FontSize="12" VerticalAlignment="Center" TextTrimming="CharacterEllipsis"/>
        <StackPanel Grid.Column="1" Orientation="Horizontal">
          <Button x:Name="RepBtnPdf" Content="Als PDF speichern ..." Padding="14,6" Margin="0,0,8,0"/>
          <Button x:Name="RepBtnHtml" Content="Im Browser öffnen" Padding="14,6" Margin="0,0,8,0"/>
          <Button x:Name="RepBtnLog" Content="Protokoll" Padding="14,6" Margin="0,0,8,0"/>
          <Button x:Name="RepBtnClose" Content="Schließen" Padding="14,6" IsCancel="True"/>
        </StackPanel>
      </Grid>
    </Border>
  </Grid>
</Window>
'@
    $dlg = [Windows.Markup.XamlReader]::Parse((Convert-ThemeXaml $x)); try { $dlg.Owner = $window } catch { }
    $script:OkDlg = $dlg; $script:OkDlgR = $R; $script:OkJump = ''
    $f = { param($n) $dlg.FindName($n) }
    $b = [int]$R.ScoreBefore.Score; $a = [int]$R.ScoreAfter.Score; $d = $a - $b
    (& $f 'RepScoreA').Text = [string]$b; (& $f 'RepScoreB').Text = [string]$a
    Add-OkRing (& $f 'RepRingA') ([double]$b) 120 '#FFFFFF' 0.55
    Add-OkRing (& $f 'RepRingB') ([double]$a) 120 '#FFFFFF' 1.0
    (& $f 'RepTitle').Text = $(if ($R.Cancelled) { 'Abgebrochen - das bisher Erledigte' } elseif ($d -ge 5) { 'Fertig - dein PC ist spürbar besser in Form' } elseif ($d -ge 0) { 'Fertig - dein PC ist gepflegt' } else { 'Fertig - bitte die offenen Punkte ansehen' })
    $sbs = ''; try { $sbs = [string]$R.ScoreAfter.Grade } catch { }
    (& $f 'RepSub').Text = ('{0} · {1} · {2} · Dauer {3} · jetzt "{4}"' -f $R.Computer, $R.StartText, $R.Mode, $R.Duration, $sbs)
    (& $f 'RepDeltaText').Text = $(if ($d -gt 0) { '+{0} Punkte' -f $d } elseif ($d -lt 0) { '{0} Punkte (oft nur bis zum Neustart)' -f $d } else { 'Score unverändert' })
    (& $f 'RepDelta').Background = New-UiBrush $(if ($d -gt 0) { '#16A34A' } elseif ($d -lt 0) { '#D97706' } else { '#52627A' })
    (& $f 'RepFreed').Text = [string]$R.FreedText; (& $f 'RepUpd').Text = [string][int]$R.Updates
    (& $f 'RepFix').Text = [string]@($R.Fixed).Count; (& $f 'RepOpen').Text = [string]@($R.Remaining).Count
    if ($R.RebootNeeded) { (& $f 'RepReboot').Visibility = 'Visible' }
    # Noch zu tun (mit Sprung-Knöpfen)
    $pnl = & $f 'RepRemain'
    if (-not @($R.Remaining).Count) { [void]$pnl.Children.Add((New-OkRow ([string][char]0xE73E) '#16A34A' 'Nichts - dieser PC ist rundum gepflegt.' '')) }
    foreach ($it in @($R.Remaining)) {
        if (-not $it) { continue }
        $row = New-OkRow ([string][char]$(if ($it.Level -eq 'Red') { 0xEA39 } else { 0xE7BA })) $(if ($it.Level -eq 'Red') { '#DC2626' } else { '#D97706' }) ([string]$it.Text) ([string]$it.Detail)
        if ($it.Action) {
            $bt = New-Object Windows.Controls.Button; $bt.Content = $(if ($it.Button) { [string]$it.Button } else { 'Öffnen' }); $bt.Tag = [string]$it.Action; $bt.Padding = '12,4'; $bt.Margin = '12,0,0,0'; $bt.VerticalAlignment = 'Center'
            try { $bt.Style = $window.FindResource('Sec') } catch { }
            $bt.Add_Click({ param($s, $e) $script:OkJump = [string]$s.Tag; $script:OkDlg.Close() })
            [Windows.Controls.Grid]::SetColumn($bt, 2); [void]$row.Children.Add($bt)
        }
        [void]$pnl.Children.Add($row)
    }
    # Schritte
    $pnl = & $f 'RepPhases'
    foreach ($p in @($R.Phases)) {
        if (-not $p) { continue }
        $sty = $OkStateStyle[[string]$p.State]; if (-not $sty) { $sty = $OkStateStyle['wait'] }
        $stt = switch ([string]$p.State) { 'ok' { 'erledigt' } 'warn' { 'mit Hinweis' } 'skip' { 'übersprungen' } 'cancel' { 'abgebrochen' } default { 'nicht ausgeführt' } }
        [void]$pnl.Children.Add((New-OkRow ([string][char][int]$sty[2]) $sty[1] ('{0} - {1}' -f $p.Title, $stt) ([string]$p.Info) $(if ([double]$p.Seconds -ge 60) { '{0:N0} min' -f ([double]$p.Seconds / 60) } elseif ([double]$p.Seconds -ge 1) { '{0:N0} s' -f [double]$p.Seconds } else { '' })))
    }
    # Score-Bestandteile vorher/nachher
    $pnl = & $f 'RepComps'
    $bc = @{}; foreach ($c in @($R.ScoreBefore.Components)) { if ($c) { $bc[[string]$c.Key] = $c } }
    foreach ($c in @($R.ScoreAfter.Components)) {
        if (-not $c -or [double]$c.Max -le 0) { continue }
        $o = $bc[[string]$c.Key]; $ov = if ($o) { [double]$o.Points } else { [double]$c.Points }
        $dv = [double]$c.Points - $ov
        $g = New-Object Windows.Controls.Grid; $g.Margin = '0,4,0,0'
        foreach ($w in @(120, -1, 120)) { $cd = New-Object Windows.Controls.ColumnDefinition; $cd.Width = $(if ($w -lt 0) { New-Object Windows.GridLength(1, 'Star') } else { New-Object Windows.GridLength($w) }); [void]$g.ColumnDefinitions.Add($cd) }
        $nm = New-Object Windows.Controls.TextBlock; $nm.Text = [string]$c.Name; $nm.FontWeight = 'SemiBold'; $nm.Foreground = New-UiBrush '#1F2A44'; $nm.VerticalAlignment = 'Center'
        $trk = New-Object Windows.Controls.Grid; $trk.Height = 10; $trk.Margin = '0,0,12,0'; $trk.VerticalAlignment = 'Center'; [Windows.Controls.Grid]::SetColumn($trk, 1)
        $bgb = New-Object Windows.Controls.Border; $bgb.CornerRadius = '5'; $bgb.Background = New-UiBrush '#EEF2F8'; [void]$trk.Children.Add($bgb)
        foreach ($pair in @(@($ov, '#AFC4EA', 0.9), @([double]$c.Points, $(if ([string]$c.Level -eq 'Good') { '#16A34A' } elseif ([string]$c.Level -eq 'Warn') { '#D97706' } else { '#DC2626' }), 1.0))) {
            $ig = New-Object Windows.Controls.Grid
            $c1 = New-Object Windows.Controls.ColumnDefinition; $c1.Width = New-Object Windows.GridLength([math]::Max(0.0001, [double]$pair[0]), 'Star')
            $c2 = New-Object Windows.Controls.ColumnDefinition; $c2.Width = New-Object Windows.GridLength([math]::Max(0.0001, [double]$c.Max - [double]$pair[0]), 'Star')
            [void]$ig.ColumnDefinitions.Add($c1); [void]$ig.ColumnDefinitions.Add($c2)
            $fl = New-Object Windows.Controls.Border; $fl.CornerRadius = '5'; $fl.Background = New-UiBrush $pair[1]; $fl.Opacity = $pair[2]; if ([double]$pair[0] -le 0) { $fl.Visibility = 'Collapsed' }
            if ($pair[1] -eq '#AFC4EA') { $fl.Margin = '0,-2,0,-2'; $fl.Opacity = 0.55 } else { $fl.Margin = '0,2,0,2' }
            [void]$ig.Children.Add($fl); [void]$trk.Children.Add($ig)
        }
        $pv = New-Object Windows.Controls.TextBlock; $pv.Text = ('{0:0.#} → {1:0.#} / {2:0}{3}' -f $ov, [double]$c.Points, [double]$c.Max, $(if ($dv -gt 0.05) { ('  (+{0:0.#})' -f $dv) } elseif ($dv -lt -0.05) { ('  ({0:0.#})' -f $dv) } else { '' })); $pv.FontSize = 12; $pv.Foreground = New-UiBrush $(if ($dv -gt 0.05) { '#15803D' } elseif ($dv -lt -0.05) { '#B45309' } else { '#475569' }); $pv.TextAlignment = 'Right'; $pv.VerticalAlignment = 'Center'; [Windows.Controls.Grid]::SetColumn($pv, 2)
        [void]$g.Children.Add($nm); [void]$g.Children.Add($trk); [void]$g.Children.Add($pv)
        $g.ToolTip = [string]$c.Reason
        [void]$pnl.Children.Add($g)
    }
    # Behoben
    $pnl = & $f 'RepFixed'
    if (@($R.Fixed).Count) { foreach ($fx in @($R.Fixed)) { [void]$pnl.Children.Add((New-OkRow ([string][char]0xE73E) '#16A34A' ([string]$fx) '')) } }
    else { [void]$pnl.Children.Add((New-OkRow ([string][char]0xE946) '#6B7890' 'Keine Probleme der Ampel waren offen bzw. noch keine gelöst.' 'Aufräumen, Updates und Prüfungen sind trotzdem gelaufen - siehe "Was wurde gemacht".')) }
    # Treiber
    $pnl = & $f 'RepDrv'
    if (@($R.DriverChanges).Count) {
        foreach ($c in @($R.DriverChanges | Select-Object -First 30)) { if ($c) { [void]$pnl.Children.Add((New-OkRow ([string][char]0xE964) '#7C3AED' ('{0}: {1} → {2}' -f $c.Device, $(if ($c.Before) { $c.Before } else { '-' }), $(if ($c.After) { $c.After } else { '-' })) ('{0} · {1}' -f $c.Kind, $c.Change))) } }
        [void]$pnl.Children.Add((New-OkRow ([string][char]0xE946) '#6B7890' 'Der vorherige Stand ist gesichert und lässt sich je Gerät zurückspielen.' ([string]$R.DriverSet)))
    } else { (& $f 'RepDrvCard').Visibility = 'Collapsed' }
    # Sicherheit und Datensicherung
    $pnl = & $f 'RepSec'
    foreach ($s in @(@($R.Security) + @($R.Backup))) {
        if (-not $s) { continue }
        [void]$pnl.Children.Add((New-OkRow ([string][char]$(if ($s.State -eq 'ok') { 0xE73E } elseif ($s.State -eq 'bad') { 0xEA39 } else { 0xE7BA })) $(if ($s.State -eq 'ok') { '#16A34A' } elseif ($s.State -eq 'bad') { '#DC2626' } else { '#D97706' }) ([string]$s.Name) ([string]$s.Text)))
    }
    (& $f 'RepFoot').Text = $(if ($R.Pdf) { 'PDF: ' + [string]$R.Pdf } elseif ($R.Html) { 'Bericht: ' + [string]$R.Html } else { '' })
    (& $f 'RepBtnClose').Add_Click({ $script:OkDlg.Close() })
    (& $f 'RepBtnReboot').Add_Click({ $script:OkJump = 'Restart'; $script:OkDlg.Close() })
    (& $f 'RepBtnDrv').Add_Click({ $script:OkJump = 'DsSets'; $script:OkDlg.Close() })
    (& $f 'RepBtnLog').Add_Click({ $lf = [string]$script:OkDlgR.Log; if ($lf -and (Test-Path -LiteralPath $lf)) { Start-Process notepad.exe -ArgumentList ('"{0}"' -f $lf) } else { Show-UiError 'Das Protokoll ist nicht mehr vorhanden.' } })
    (& $f 'RepBtnHtml').Add_Click({
        $hf = [string]$script:OkDlgR.Html
        if (-not ($hf -and (Test-Path -LiteralPath $hf))) { $hf = Join-Path $env:TEMP ('PCTools-EinKlick-{0}.html' -f (Get-Random)); [IO.File]::WriteAllText($hf, (New-OkReportHtml $script:OkDlgR $ReportCss), (New-Object Text.UTF8Encoding $true)) }
        try { Start-Process -FilePath $hf } catch { Show-UiError $_.Exception.Message }
    })
    (& $f 'RepBtnPdf').Add_Click({
        Add-Type -AssemblyName System.Windows.Forms
        $sd = New-Object System.Windows.Forms.SaveFileDialog; $sd.Filter = 'PDF-Dokument (*.pdf)|*.pdf'
        $st = ''; try { $st = ([datetime]$script:OkDlgR.Start).ToString('yyyy-MM-dd_HHmm') } catch { }
        $sd.FileName = ('Ein-Klick-Bericht_{0}_{1}.pdf' -f $env:COMPUTERNAME, $st); $sd.InitialDirectory = [Environment]::GetFolderPath('Desktop')
        if ($sd.ShowDialog() -ne 'OK') { return }
        $target = $sd.FileName
        if ($script:OkDlgR.Pdf -and (Test-Path -LiteralPath ([string]$script:OkDlgR.Pdf))) {
            try { Copy-Item -LiteralPath ([string]$script:OkDlgR.Pdf) -Destination $target -Force; $ui.StatusText.Text = 'Bericht gespeichert: ' + $target; Start-Process -FilePath $target } catch { Show-UiError $_.Exception.Message }
            return
        }
        $ui.StatusText.Text = 'PDF wird erstellt ...'
        Invoke-Bg -Script { param($html, $out) Convert-HtmlToPdf $html $out } -Arguments @((New-OkReportHtml $script:OkDlgR $ReportCss), $target) -Functions @('Convert-HtmlToPdf', 'Get-EdgePath') -Done {
            param($r, $err)
            if ($err) { $ui.StatusText.Text = 'PDF fehlgeschlagen: ' + $err.Message; return }
            $o = [string]@($r | Where-Object { $_ })[-1]
            $ui.StatusText.Text = $(if ($o -like '*.pdf') { 'Bericht gespeichert: ' + $o } else { 'Edge nicht gefunden - als HTML gespeichert: ' + $o })
            try { if ($o) { Start-Process -FilePath $o } } catch { }
        }
    })
    [void]$dlg.ShowDialog()
    $j = $script:OkJump; $script:OkJump = ''; $script:OkDlg = $null
    if ($j -eq 'DsSets') { $ui.Tabs.SelectedItem = $ui.TabDrv; try { Update-DsSetList } catch { }; try { $window.Dispatcher.BeginInvoke([Action]{ try { $ui.DsSetGrid.BringIntoView() } catch { } }, [Windows.Threading.DispatcherPriority]::Background) | Out-Null } catch { } }
    elseif ($j) { try { Invoke-AmpAction $j } catch { Show-UiError $_.Exception.Message } }
}
$ui.BtnOkStart.Add_Click({ Start-OkRun })
$ui.BtnOkAuto.Add_Click({
    if ($script:Job) { Show-UiError 'Es läuft bereits eine Aufgabe von PC-Tools (siehe Protokoll). Bitte warten, bis sie fertig ist.'; return }
    if (-not (Confirm-Ui ("Alles automatisch erledigen?`n`nPC-Tools misst den Zustand, setzt einen Wiederherstellungspunkt, räumt auf, installiert Windows-, Treiber- und Programm-Updates, optimiert, prüft die Systemdateien, ERKENNT selbst Probleme (Dienste, Windows Update, Netzwerk, WMI ...) und BEHEBT sie - ganz ohne Rückfragen.`n`nDauer meist 20-90 Minuten. Der PC bleibt benutzbar, der Lauf geht im Hintergrund weiter. Neu gestartet wird nur nach Rückfrage."))) { return }
    foreach ($n in 'OneClick_Updates', 'OneClick_Drivers', 'OneClick_Programs', 'OneClick_Repair', 'OneClick_AutoRepair') { try { $ui[$n].IsChecked = $true } catch { } }
    try { Save-PflegeConfig (Get-ConfigFromUi) } catch { }
    try { Remove-Item -LiteralPath (Join-Path (Join-Path $DataDir 'EinKlick') 'phasen.json') -Force -ErrorAction SilentlyContinue } catch { }
    try {
        Start-Run -Parts @('OneClick') -Job @{ Updates = $true; Drivers = $true; Programs = $true; Repair = $true; AutoRepair = $true }
    } catch { Show-UiError ('Start fehlgeschlagen: ' + $_.Exception.Message); return }
    if (-not $script:Job) { return }
    $ui.Tabs.SelectedItem = $ui.TabOverview
    $script:OkTrack = @{ Log = [string]$script:Job.Log; Status = [string]$script:Job.Status; Start = Get-Date }
    $ui.OkBar.Value = 0; $ui.OkStatus.Text = 'Wird gestartet ...'; $ui.OkDetail.Text = ''
    Set-OkRunUi $true
    Show-OkPhases @(Get-OkPlanPhases)
    $script:OkTimer.Start()
    try { $ui.OkCard.BringIntoView() } catch { }
})
$ui.BtnOkMega.Add_Click({ try { Invoke-MegaPerf } catch { Show-UiError ('Mega-Leistung: ' + $_.Exception.Message) } })
if ($ui.BtnAboutGitHub) { $ui.BtnAboutGitHub.Add_Click({ try { Start-Process (Get-GitHubWebUrl) } catch { } }) }
if ($ui.BtnAboutIssue) { $ui.BtnAboutIssue.Add_Click({ try { Start-Process ((Get-GitHubWebUrl) + '/issues/new') } catch { } }) }
if ($ui.BtnAboutLicense) { $ui.BtnAboutLicense.Add_Click({ try { Start-Process ((Get-GitHubWebUrl) + '/blob/main/LICENSE') } catch { } }) }
if ($ui.BtnAboutWhatsNew) { $ui.BtnAboutWhatsNew.Add_Click({ Show-WhatsNew }) }
$ui.BtnOkReport.Add_Click({ try { Show-OkReport (Read-OkLast) } catch { Show-UiError ('Bericht: ' + $_.Exception.Message) } })
$ui.BtnOkCancel.Add_Click({ if ($script:Job -and $script:OkTrack -and (Confirm-Ui 'Ein-Klick-Optimierung abbrechen? Der laufende Schritt wird beendet, danach wird der Zustand gemessen und ein Bericht über das bisher Erledigte erstellt.')) { New-Item -Path $script:Job.Cancel -ItemType File -Force | Out-Null; $ui.OkStatus.Text = 'Wird abgebrochen ...' } })
foreach ($n in 'OneClick_Updates', 'OneClick_Drivers', 'OneClick_Programs', 'OneClick_Repair', 'OneClick_AutoRepair') {
    $ui[$n].Add_Click({ try { Save-PflegeConfig (Get-ConfigFromUi) } catch { }; if (-not $script:OkTrack) { Show-OkPhases @(Get-OkPlanPhases) } })
}
$ui.Schedule_OneClick.Add_Click({
    if ($ui.Schedule_OneClick.IsChecked) { $ui.Schedule_Enabled.IsChecked = $true }
    $null = Save-All -Quiet
    Update-OkSchedInfo
    $ui.StatusText.Text = $(if ($ui.Schedule_OneClick.IsChecked) { 'Die automatische Pflege führt ab jetzt die Ein-Klick-Optimierung aus (Seite Zeitplan: Tag und Uhrzeit).' } else { 'Die automatische Pflege läuft wieder nach den Haken auf der Seite Zeitplan.' })
})
$window.Add_Loaded({ try { Update-OkLast; Show-OkPhases @(Get-OkPlanPhases); Update-OkSchedInfo } catch { } })

# ---------------------------------------------------------------- PC-Tools 10 (Team D): Treiber-Sicherungen vor Updates (Treiber-Seite)
$script:DsSetRows = @()
$script:DsSetLoaded = $false
function Update-DsSetList {
    $ui.DsSetProg.Visibility = 'Visible'; $ui.DsSetInfo.Text = 'Sicherungen werden gelesen und mit den jetzigen Treibern verglichen ...'
    $ui.BtnDsSetRefresh.IsEnabled = $false
    Invoke-Bg -Script {
        param($root)
        $rows = @(); $bios = $null; $err = ''
        try { $rows = @(Get-DsDriverRows) } catch { $err = $_.Exception.Message }
        try { $bios = Get-DsBiosInfo } catch { }
        $now = @{}; foreach ($d in $rows) { $now[([string]$d.DeviceId).ToUpper()] = $d }
        foreach ($s in @(Get-DsSets $root | Sort-Object Created -Descending)) {
            $m = $s.Manifest
            $chg = @(Compare-DsManifest $m $rows $bios)
            $size = [int64](@(Get-ChildItem -LiteralPath $s.Path -Recurse -File -Force -ErrorAction SilentlyContinue) | Measure-Object Length -Sum).Sum
            $ck = @{}; foreach ($c in $chg) { $ck[([string]$c.DeviceId).ToUpper()] = $c }
            $all = foreach ($d in @($m.Drivers)) {
                $k = ([string]$d.DeviceId).ToUpper(); $n = $now[$k]; $c = $ck[$k]
                [pscustomobject]@{ Device = [string]$d.Device; Kind = $(if ($d.Firmware) { 'Firmware' } else { 'Treiber' }); Class = [string]$d.Class; DeviceId = [string]$d.DeviceId
                    Before = [string]$d.Version; After = $(if ($n) { [string]$n.Version } else { '' }); Change = $(if ($c) { [string]$c.Change } else { 'unverändert' })
                    SavedInf = [string]$d.Inf; NowInf = $(if ($n) { [string]$n.Inf } else { '' }); Path = [string]$d.Path; CanRestore = [bool]($d.Path -and -not $d.Firmware); Hot = [bool]$c }
            }
            [pscustomobject]@{ Path = $s.Path; Name = $s.Name; Kind = $s.Kind; KindText = $(if ($s.Kind -eq 'Auto') { 'vor Update' } else { 'von Hand' }); Created = $s.Created
                DateText = $(try { ([datetime]$s.Created).ToString('dd.MM.yyyy HH:mm') } catch { $s.Created }); Reason = $s.Reason; Count = [int]$m.Count; Packages = [int]$m.Packages
                BiosText = $(if ($m.Bios) { '{0} ({1})' -f $m.Bios.Version, $m.Bios.Release } else { '-' }); Bios = $m.Bios; BiosNow = $bios; ExportOk = [bool]$m.ExportOk
                ChangeText = $(if (-not $chg.Count) { 'nichts' } else { '{0} Gerät(e){1}' -f @($chg | Where-Object { $_.Kind -ne 'BIOS' }).Count, $(if (@($chg | Where-Object { $_.Kind -eq 'BIOS' }).Count) { ' + BIOS' } else { '' }) })
                SizeText = ('{0:N0} MB' -f ($size / 1MB)); Changes = $chg; All = @($all); Error = $err }
        }
    } -Arguments @((Get-DsRoot)) -Functions @('Get-DsSets', 'Read-DsManifest', 'Get-DsDriverRows', 'ConvertTo-DsDriverRow', 'Get-DsBiosInfo', 'Compare-DsManifest', 'Compare-DsVersion') -Done {
        param($r, $err)
        $ui.DsSetProg.Visibility = 'Collapsed'; $ui.BtnDsSetRefresh.IsEnabled = $true
        if ($err) { $ui.DsSetInfo.Text = 'Einlesen fehlgeschlagen: ' + $err.Message; return }
        $script:DsSetRows = @($r | Where-Object { $_ -and $_.Path })
        Set-GridItems $ui.DsSetGrid $script:DsSetRows
        $auto = @($script:DsSetRows | Where-Object { $_.Kind -eq 'Auto' }).Count
        $ui.DsSetInfo.Text = $(if (-not $script:DsSetRows.Count) { 'Noch keine Sicherung mit Geräteliste. Sie entsteht automatisch vor dem nächsten Treiber-, BIOS- oder Firmware-Update - oder jetzt mit "Jetzt sichern".' } else { '{0} Sicherung(en), davon {1} automatisch vor Updates. Oben eine Sicherung wählen: unten stehen die Geräte, deren Treiber sich seitdem geändert haben.' -f $script:DsSetRows.Count, $auto })
        if ($script:DsSetRows.Count) { $ui.DsSetGrid.SelectedIndex = 0 } else { Set-GridItems $ui.DsChgGrid @(); $ui.DsSetBiosInfo.Text = '' }
    }
}
function Show-DsSetDetail {
    $s = $ui.DsSetGrid.SelectedItem
    if (-not $s) { Set-GridItems $ui.DsChgGrid @(); $ui.DsSetBiosInfo.Text = ''; return }
    $rows = if ($ui.DsSetShowAll.IsChecked) { @($s.All) } else {
        @($s.Changes | Where-Object { $_.Kind -ne 'BIOS' } | ForEach-Object { [pscustomobject]@{ Device = $_.Device; Kind = $_.Kind; Class = $_.Class; DeviceId = $_.DeviceId; Before = $_.Before; After = $_.After; Change = $_.Change; SavedInf = $_.SavedInf; NowInf = $_.NowInf; Path = $_.Path; CanRestore = [bool]$_.CanRestore; Hot = $true } })
    }
    foreach ($x in $rows) { $x | Add-Member -NotePropertyName RestoreText -NotePropertyValue $(if ($x.Kind -eq 'Firmware') { 'nie automatisch' } elseif ($x.CanRestore -and $x.Change -ne 'unverändert') { 'möglich' } elseif ($x.CanRestore) { '(gleich)' } else { 'kein Paket' }) -Force }
    Set-GridItems $ui.DsChgGrid @($rows)
    $bn = $s.BiosNow; $bo = $s.Bios
    $ui.DsSetBiosInfo.Text = if ($bo -and $bn) { 'BIOS gesichert: {0} vom {1}  ·  jetzt: {2} vom {3}{4}' -f $bo.Version, $bo.Release, $bn.Version, $bn.Release, $(if ([string]$bo.Version -ne [string]$bn.Version) { '  ·  GEÄNDERT' } else { '' }) } else { '' }
    $ui.DsSetBiosInfo.Foreground = New-UiBrush $(if ($bo -and $bn -and [string]$bo.Version -ne [string]$bn.Version) { '#B45309' } else { '#1F2A44' })
    if (-not $rows.Count -and -not $ui.DsSetShowAll.IsChecked) { $ui.DsSetInfo.Text = ('Sicherung vom {0}: seitdem keine Treiber geändert. Mit "alle gesicherten Treiber zeigen" lässt sich trotzdem jeder Treiber einzeln zurückspielen.' -f $s.DateText) }
}
function Invoke-DsSetRestoreDevice {
    $s = $ui.DsSetGrid.SelectedItem; $x = $ui.DsChgGrid.SelectedItem
    if (-not $s -or -not $x) { Show-UiError 'Bitte oben eine Sicherung und unten ein Gerät wählen.'; return }
    if ($x.Kind -eq 'Firmware') { Show-UiError ("Firmware ({0}) wird nicht automatisch zurückgespielt - ein abgebrochener oder falscher Firmware-Stand kann ein Gerät unbrauchbar machen.`n`nWeg: Geräte-Manager > Firmware > Eigenschaften > Treiber > ""Vorheriger Treiber"" (falls angeboten) oder die ältere Firmware beim Hersteller laden. Für das BIOS: Knopf ""BIOS: Rückweg""." -f $x.Device); return }
    if (-not $x.CanRestore) { Show-UiError ('Für "{0}" liegt in dieser Sicherung kein Treiberpaket (z.B. nur Geräteliste wegen Platzmangel, oder Treiber von Windows selbst).' -f $x.Device); return }
    $inf = Join-Path $s.Path $x.Path
    if (-not (Test-Path -LiteralPath $inf)) { Show-UiError ('Paket nicht gefunden: ' + $inf); return }
    $crit = ([string]$x.Class -match '^(?i)(SCSIAdapter|HDC|System|DiskDrive|Volume|SoftwareComponent)$')
    if (-not (Confirm-Ui ("Gesicherten Treiber zurückspielen?`n`nGerät: {0}`nGesichert: {1}`nJetzt: {2}`nPaket: {3}{4}`n`nVorher wird kein weiterer Wiederherstellungspunkt gesetzt - der automatische vom Update besteht." -f $x.Device, $x.Before, $(if ($x.After) { $x.After } else { '-' }), $x.Path, $(if ($crit) { "`n`nACHTUNG: Speicher- bzw. Systemtreiber - nur zurückspielen, wenn das Problem sicher von diesem Treiber kommt." } else { '' })) $(if ($crit) { 'Warning' } else { 'Question' }))) { return }
    $script:DsRestoreCtx = @{ Device = [string]$x.Device; DeviceId = [string]$x.DeviceId; Want = [string]$x.Before; NowInf = [string]$x.NowInf; Inf = $inf; Crit = $crit; Set = $s }
    $ui.DsSetProg.Visibility = 'Visible'; $ui.StatusText.Text = ('Treiber für {0} wird zurückgespielt ...' -f $x.Device); $window.Cursor = 'AppStarting'
    Invoke-Bg -Script {
        param($inf, $devId)
        $o = (& (Join-Path $env:SystemRoot 'System32\pnputil.exe') /add-driver ('"{0}"' -f $inf) /install 2>&1) -join "`n"
        Start-Sleep -Seconds 2
        $n = @(Get-CimInstance Win32_PnPSignedDriver -ErrorAction SilentlyContinue | Where-Object { [string]$_.DeviceID -eq $devId })[0]
        [pscustomobject]@{ Out = $o; Version = $(if ($n) { [string]$n.DriverVersion } else { '' }); Inf = $(if ($n) { ([string]$n.InfName).ToLower() } else { '' }) }
    } -Arguments @($inf, [string]$x.DeviceId) -Done {
        param($r, $err)
        $ui.DsSetProg.Visibility = 'Collapsed'; $window.Cursor = $null
        $c = $script:DsRestoreCtx
        if ($err) { Show-UiError ('pnputil: ' + $err.Message); return }
        $res = @($r | Where-Object { $_ -and $_.PSObject.Properties['Out'] })[0]
        if ($res -and [string]$res.Version -eq $c.Want) { $ui.StatusText.Text = ('{0}: Treiber {1} ist wieder aktiv.' -f $c.Device, $c.Want); [Windows.MessageBox]::Show((T (('Erledigt: "{0}" nutzt wieder den gesicherten Treiber {1}.' -f $c.Device, $c.Want))), (T ('PC-Tools')), 'OK', 'Information') | Out-Null; Update-DsSetList; return }
        $nowInf = if ($res -and $res.Inf) { [string]$res.Inf } else { $c.NowInf }
        $users = @($c.Set.All | Where-Object { [string]$_.NowInf -eq $nowInf -and $nowInf }).Count
        $q = ("Das gesicherte Paket ist jetzt im Treiberspeicher, aber Windows nutzt für ""{0}"" weiter Version {1} - der neuere Treiber hat eine bessere Einstufung.`n`nSoll PC-Tools das neuere Paket {2} entfernen (pnputil /delete-driver {2} /uninstall) und die Geräte neu erkennen lassen? Dann greift Windows auf den gesicherten Treiber {3} zurück.`n`nDas betrifft alle Geräte, die {2} nutzen ({4}).{5}`n`nNein = stattdessen die Geräte-Eigenschaften öffnen (Treiber > ""Vorheriger Treiber"" bzw. ""Treiber aktualisieren > Auf meinem Computer suchen > Aus einer Liste"")." -f $c.Device, $(if ($res) { $res.Version } else { '?' }), $nowInf, $c.Want, $(if ($users) { '{0} Gerät(e) laut Sicherung' -f $users } else { 'Anzahl unbekannt' }), $(if ($c.Crit) { "`n`nACHTUNG: Speicher-/Systemtreiber - im Zweifel Nein wählen." } else { '' }))
        if (-not $nowInf -or $nowInf -notmatch '^oem\d+\.inf$') { Start-Process rundll32.exe -ArgumentList ('devmgr.dll,DeviceProperties_RunDLL /DeviceID "{0}"' -f $c.DeviceId); return }
        if (-not (Confirm-Ui $q 'Warning')) { Start-Process rundll32.exe -ArgumentList ('devmgr.dll,DeviceProperties_RunDLL /DeviceID "{0}"' -f $c.DeviceId); return }
        $ui.DsSetProg.Visibility = 'Visible'; $ui.StatusText.Text = ('Neueres Paket {0} wird entfernt ...' -f $nowInf); $window.Cursor = 'AppStarting'
        Invoke-Bg -Script {
            param($oem, $devId)
            $pn = Join-Path $env:SystemRoot 'System32\pnputil.exe'
            $o = (& $pn /delete-driver $oem /uninstall 2>&1) -join "`n"
            $o += "`n" + ((& $pn /scan-devices 2>&1) -join "`n")
            Start-Sleep -Seconds 4
            $n = @(Get-CimInstance Win32_PnPSignedDriver -ErrorAction SilentlyContinue | Where-Object { [string]$_.DeviceID -eq $devId })[0]
            [pscustomobject]@{ Out = $o; Version = $(if ($n) { [string]$n.DriverVersion } else { '' }) }
        } -Arguments @($nowInf, $c.DeviceId) -Done {
            param($r2, $err2)
            $ui.DsSetProg.Visibility = 'Collapsed'; $window.Cursor = $null
            $c2 = $script:DsRestoreCtx
            $x2 = @($r2 | Where-Object { $_ -and $_.PSObject.Properties['Out'] })[0]
            if ($x2 -and [string]$x2.Version -eq $c2.Want) { [Windows.MessageBox]::Show((T (('Erledigt: "{0}" nutzt wieder den gesicherten Treiber {1}. Ein Neustart schadet nicht.' -f $c2.Device, $c2.Want))), (T ('PC-Tools')), 'OK', 'Information') | Out-Null }
            else { Show-UiError (("Noch nicht am Ziel (jetzt: {0}). Es öffnen sich die Geräte-Eigenschaften: Treiber > ""Treiber aktualisieren"" > ""Auf meinem Computer suchen"" > ""Aus einer Liste verfügbarer Treiber"" und die Version {1} wählen.`n`npnputil:`n{2}" -f $(if ($x2 -and $x2.Version) { $x2.Version } else { 'Gerät nicht gefunden' }), $c2.Want, $(if ($x2) { ([string]$x2.Out).Trim() } else { [string]$err2 }))); Start-Process rundll32.exe -ArgumentList ('devmgr.dll,DeviceProperties_RunDLL /DeviceID "{0}"' -f $c2.DeviceId) }
            Update-DsSetList
        }
    }
}
function Get-DsSupportUrl([string]$Vendor) {
    switch -Regex ($Vendor) { 'HP|Hewlett' { 'https://support.hp.com/de-de/drivers' } 'Lenovo' { 'https://pcsupport.lenovo.com/de/de' } 'Dell' { 'https://www.dell.com/support/home/de-de' } 'Microsoft' { 'https://support.microsoft.com/de-de/surface' } 'ASUS' { 'https://www.asus.com/de/support/' } 'Acer' { 'https://www.acer.com/de-de/support' } default { '' } }
}
$ui.BtnDsSetRefresh.Add_Click({ Update-DsSetList })
$ui.BtnDsSetNow.Add_Click({ Start-Run -Parts @('DriverBackup') })
$ui.DsSetGrid.Add_SelectionChanged({ try { Show-DsSetDetail } catch { } })
$ui.DsSetShowAll.Add_Click({ try { Show-DsSetDetail } catch { } })
$ui.BtnDsSetDevice.Add_Click({ try { Invoke-DsSetRestoreDevice } catch { Show-UiError $_.Exception.Message } })
$ui.DsChgGrid.Add_MouseDoubleClick({ try { Invoke-DsSetRestoreDevice } catch { Show-UiError $_.Exception.Message } })
$ui.BtnDsSetWhole.Add_Click({
    $s = $ui.DsSetGrid.SelectedItem; if (-not $s) { Show-UiError 'Bitte eine Sicherung wählen.'; return }
    if (-not $s.ExportOk) { Show-UiError 'Diese Sicherung enthält nur die Geräteliste (beim Sichern war zu wenig Platz) - zurückspielen ist nicht möglich.'; return }
    if (-not (Confirm-Ui ("Alle {0} Treiberpakete aus der Sicherung vom {1} zurückspielen?`n`nWindows installiert sie für passende Geräte. Neuere Treiber bleiben aktiv, wenn Windows sie besser einstuft - für ein gezieltes Zurück einzelne Geräte unten wählen und ""Diesen Stand zurückspielen (Gerät)"" nutzen." -f $s.Packages, $s.DateText))) { return }
    $ui.DsSetProg.Visibility = 'Visible'; $ui.StatusText.Text = 'Treiber werden zurückgespielt ...'; $window.Cursor = 'AppStarting'
    Invoke-Bg -Script { param($p) (& (Join-Path $env:SystemRoot 'System32\pnputil.exe') /add-driver (Join-Path $p '*.inf') /subdirs /install 2>&1) -join "`n" } -Arguments @($s.Path) -Done {
        param($x, $err)
        $ui.DsSetProg.Visibility = 'Collapsed'; $window.Cursor = $null
        if ($err) { Show-UiError ('pnputil: ' + $err.Message); return }
        $ui.StatusText.Text = 'Zurückgespielt: ' + ((@($x) -join ' ' -split "`n" | Where-Object { $_ -match '\d' } | Select-Object -Last 2) -join ' ')
        Update-DsSetList
    }
})
$ui.BtnDsSetBios.Add_Click({
    $s = $ui.DsSetGrid.SelectedItem
    $bo = if ($s) { $s.Bios } else { $null }; $bn = if ($s) { $s.BiosNow } else { $null }
    if (-not $bn) { try { $bn = Get-DsBiosInfo } catch { } }
    $vendor = if ($bn) { [string]$bn.Vendor } else { '' }
    $t = ("BIOS/UEFI jetzt: {0} vom {1}{2}`n`n{3}`n`nPC-Tools spielt BIOS und Firmware nie selbst ein - ein abgebrochener Flash-Vorgang kann den PC unbrauchbar machen." -f $(if ($bn) { $bn.Version } else { '?' }), $(if ($bn) { $bn.Release } else { '?' }), $(if ($bo) { "`nGesichert ({0}): {1} vom {2}{3}" -f $s.DateText, $bo.Version, $bo.Release, $(if ([string]$bo.Version -ne [string]$bn.Version) { '  -> seitdem GEÄNDERT' } else { '  (unverändert)' }) } else { '' }), (Get-DsBiosHint $vendor))
    $u = Get-DsSupportUrl $vendor
    if ($u) { if (Confirm-Ui ($t + "`n`nSupport-Seite des Herstellers öffnen?") 'Information') { Start-Process $u } }
    else { [Windows.MessageBox]::Show((T ($t)), (T ('PC-Tools')), 'OK', 'Information') | Out-Null }
})
$ui.BtnDsSetDevMgr.Add_Click({ $x = $ui.DsChgGrid.SelectedItem; if ($x -and $x.DeviceId) { Start-Process rundll32.exe -ArgumentList ('devmgr.dll,DeviceProperties_RunDLL /DeviceID "{0}"' -f $x.DeviceId) } else { Start-Process devmgmt.msc } })
$ui.BtnDsSetOpen.Add_Click({ $s = $ui.DsSetGrid.SelectedItem; $p = if ($s) { $s.Path } else { Get-DsRoot }; New-Item $p -ItemType Directory -Force -ErrorAction SilentlyContinue | Out-Null; Start-Process explorer.exe ('"{0}"' -f $p) })
$ui.BtnDsSetDel.Add_Click({
    $s = $ui.DsSetGrid.SelectedItem; if (-not $s) { return }
    if (Confirm-Ui ('Sicherung vom {0} ({1}, {2}) löschen? Die darin gesicherten Treiber lassen sich danach nicht mehr zurückspielen.' -f $s.DateText, $s.Reason, $s.SizeText) 'Warning') {
        try { Remove-Item -LiteralPath $s.Path -Recurse -Force -ErrorAction Stop } catch { Show-UiError $_.Exception.Message }
        Update-DsSetList; try { Update-DrvBackups } catch { }
    }
})
$ui.DriverSafety_Enabled.Add_Click({
    if (-not $ui.DriverSafety_Enabled.IsChecked -and -not (Confirm-Ui 'Automatische Treiber-Sicherung vor Updates wirklich ausschalten? Dann gibt es nach einem misslungenen Treiber- oder BIOS-Update nur noch den Wiederherstellungspunkt als Rückweg.' 'Warning')) { $ui.DriverSafety_Enabled.IsChecked = $true; return }
    try { Save-PflegeConfig (Get-ConfigFromUi); $ui.StatusText.Text = 'Einstellung gespeichert.' } catch { }
})
$ui.DriverSafety_Keep.Add_LostFocus({ $n = 0; if (-not [int]::TryParse($ui.DriverSafety_Keep.Text.Trim(), [ref]$n) -or $n -lt 1) { $ui.DriverSafety_Keep.Text = '5' } elseif ($n -gt 30) { $ui.DriverSafety_Keep.Text = '30' }; try { Save-PflegeConfig (Get-ConfigFromUi) } catch { } })
$ui.Tabs.Add_SelectionChanged({ param($s, $e) if ($e.OriginalSource -eq $s -and $s.SelectedItem -eq $ui.TabDrv -and -not $script:DsSetLoaded) { $script:DsSetLoaded = $true; try { Update-DsSetList } catch { } } })

