# ---- Lite-Ansicht: Seite nur auf Geräten mit Akku (oder USV) zeigen
$script:EnHasBattery = $true
try {
    Add-Type -AssemblyName System.Windows.Forms -ErrorAction Stop
    $enBcs = [int][System.Windows.Forms.SystemInformation]::PowerStatus.BatteryChargeStatus
    $script:EnHasBattery = -not ($enBcs -ne 255 -and ($enBcs -band 128))
} catch { }
