    $script:LiteTabs = @($LiteTabs) + 'TabEnergy'
    if ($Script:IsLite) { try { Set-LiteView $true } catch { } }
}

# ---- kleine Zeichen-Helfer
function Set-EnRing($Canvas, [double]$Pct, [string]$Color, [double]$Thick = 12) {
    if (-not $Canvas) { return }
    $Canvas.Children.Clear()
    $sz = [double]$Canvas.Width; if (-not ($sz -gt 20)) { $sz = 150 }
    $rr = ($sz - $Thick) / 2; $cc = $sz / 2
    $trk = New-Object Windows.Shapes.Ellipse; $trk.Width = $sz - $Thick; $trk.Height = $sz - $Thick; $trk.Stroke = New-UiBrush '#E2E7F0'; $trk.StrokeThickness = $Thick
    [Windows.Controls.Canvas]::SetLeft($trk, $Thick / 2); [Windows.Controls.Canvas]::SetTop($trk, $Thick / 2); [void]$Canvas.Children.Add($trk)
    if ([double]::IsNaN($Pct) -or $Pct -le 0) { return }
    $p = [math]::Min(100.0, $Pct)
    $br = New-UiBrush $Color
    $fx = New-Object Windows.Media.Effects.DropShadowEffect; $fx.Color = [Windows.Media.ColorConverter]::ConvertFromString($Color); $fx.BlurRadius = 12; $fx.ShadowDepth = 0; $fx.Opacity = 0.35
    if ($p -ge 99.9) {
        $full = New-Object Windows.Shapes.Ellipse; $full.Width = $sz - $Thick; $full.Height = $sz - $Thick; $full.Stroke = $br; $full.StrokeThickness = $Thick; $full.Effect = $fx
        [Windows.Controls.Canvas]::SetLeft($full, $Thick / 2); [Windows.Controls.Canvas]::SetTop($full, $Thick / 2); [void]$Canvas.Children.Add($full); return
    }
    $ang = 2 * [math]::PI * $p / 100
    $fig = New-Object Windows.Media.PathFigure; $fig.StartPoint = New-Object Windows.Point($cc, ($cc - $rr)); $fig.IsClosed = $false
    $end = New-Object Windows.Point(($cc + $rr * [math]::Sin($ang)), ($cc - $rr * [math]::Cos($ang)))
    $seg = New-Object Windows.Media.ArcSegment($end, (New-Object Windows.Size($rr, $rr)), 0, ($p -gt 50), ([Windows.Media.SweepDirection]::Clockwise), $true)
    [void]$fig.Segments.Add($seg)
    $geo = New-Object Windows.Media.PathGeometry; [void]$geo.Figures.Add($fig)
    $path = New-Object Windows.Shapes.Path; $path.Data = $geo; $path.Stroke = $br; $path.StrokeThickness = $Thick; $path.StrokeStartLineCap = 'Round'; $path.StrokeEndLineCap = 'Round'; $path.Effect = $fx
    [void]$Canvas.Children.Add($path)
}
function New-EnText([string]$Text, [double]$Size = 12.5, [string]$Color = '#1F2A44', [string]$Weight = 'Normal') {
    $t = New-Object Windows.Controls.TextBlock; $t.Text = $Text; $t.FontSize = $Size; $t.Foreground = New-UiBrush $Color; $t.FontWeight = $Weight; $t.TextWrapping = 'Wrap'; return $t
}
function Get-EnLevelColor([double]$P) { if ([double]::IsNaN($P)) { '#9AA5B8' } elseif ($P -ge 80) { '#16A34A' } elseif ($P -ge 60) { '#D97706' } else { '#DC2626' } }
function Get-EnSelGuid($Combo) { $t = Get-ComboTag $Combo; if ($t -match '^[0-9a-fA-F\-]{36}$') { $t } else { '' } }

# ---------------------------------------------------------------- Laden und Anzeigen: Akku
function Start-EnLoad {
    $ui.EnHeadline.Text = 'wird eingelesen ...'
    Start-EnBatteryLoad $true
    Start-EnReportLoad
    Start-EnSleepLoad
    Start-EnChargeLoad
}
function Start-EnBatteryLoad([bool]$Full) {
    if ($script:EnLiveBusy -and -not $Full) { return }
    $script:EnLiveBusy = $true
    Invoke-Bg -Script { param($dd, $full)
        $DataDir = $dd
        $b = Get-EnBatteryInfo
        $o = [ordered]@{ Bat = $b; Full = $full; Own = @(); Score = ''; Overlay = $null; Plans = @(); Saver = -1; Crit = $null }
        if ($full) {
            try { $o.Own = @(Get-EnOwnHistory $dd) } catch { }
            try { $sc = @(Get-ScScoreHistory $dd 30); if ($sc.Count) { $o.Score = [string]$sc[$sc.Count - 1].Akku } } catch { }
            try { $o.Overlay = Get-EnOverlay } catch { }
            try { $o.Plans = @(Get-EnPlans) } catch { }
            try { $o.Saver = (Get-PwrValue 'SUB_ENERGYSAVER' 'ESBATTTHRESHOLD')[1] } catch { }
            try { $lv = Get-PwrValue 'SUB_BATTERY' 'BATLEVELCRIT'; $ac = Get-PwrValue 'SUB_BATTERY' 'BATACTIONCRIT'; $o.Crit = [pscustomobject]@{ Level = $lv[1]; Action = $ac[1] } } catch { }
        }
        [pscustomobject]$o
    } -Arguments @($DataDir, $Full) -Functions $script:EnFnAll -Done {
        param($r, $err)
        $script:EnLiveBusy = $false
        $x = @($r | Where-Object { $_ })[0]
        if ($err -or -not $x) { $ui.EnHeadline.Text = 'Akkudaten nicht lesbar: ' + $(if ($err) { $err.Message } else { 'keine Antwort' }); return }
        $script:EnBat = $x.Bat
        if ($x.Full) {
            $script:EnOwnHist = @($x.Own); $script:EnScoreTxt = [string]$x.Score; $script:EnOverlay = $x.Overlay; $script:EnPlansData = @($x.Plans); $script:EnSaverLvl = [int]$x.Saver; $script:EnCrit = $x.Crit
            Show-EnBattery; Show-EnHistory; Show-EnPlans; Show-EnMode; Show-EnUps
        } else { Show-EnBatteryLive }
    }
}
function Show-EnBatteryLive {
    $b = $script:EnBat; if (-not $b) { return }
    if ($b.Present) {
        $pc = [double]$b.Percent
        Set-EnRing $ui.EnRingCharge $pc $(if ($b.Charging) { '#2D7FF9' } elseif ($pc -lt 20) { '#DC2626' } elseif ($pc -lt 50) { '#D97706' } else { '#16A34A' })
        $ui.EnRingChargeVal.Text = $(if ($pc -ge 0) { '{0:N0} %' -f $pc } else { '-' })
        $ui.EnRingChargeSub.Text = $(if ($b.Charging) { 'lädt' } elseif ($b.Online) { 'am Netzteil' } else { 'Akkubetrieb' })
        $ui.EnHeadline.Text = $(if ($b.Charging) { 'Akku lädt' + $(if (-not [double]::IsNaN($b.ToFullMin)) { ' - voll in ca. ' + (Format-EnDur $b.ToFullMin) } else { '' }) }
            elseif ($b.Online) { $(if ($pc -ge 95) { 'Am Netzteil - Akku voll' } else { 'Am Netzteil - Akku lädt gerade nicht' }) }
            else { 'Akkubetrieb' + $(if (-not [double]::IsNaN($b.EstMin)) { ' - noch ca. ' + (Format-EnDur $b.EstMin) } else { '' }) })
        $sub = @()
        if ($b.Online -and -not $b.Charging -and $pc -lt 95 -and $pc -ge 0) { $sub += ('Bleibt die Ladung am Netzteil bei ca. {0:N0} % stehen, ist meist eine Ladegrenze aktiv (siehe "Ladegrenze" unten) - das ist gewollt und schont den Akku.' -f $pc) }
        if ($b.Saver) { $sub += 'Der Energiesparmodus ist gerade eingeschaltet.' }
        $ui.EnHeadSub.Text = $sub -join ' '
        $ui.EnPowerSrc.Text = $(if ($b.Online) { 'Netzteil' + $(if ($b.ChargeRate -gt 0) { ' (lädt mit {0:N1} W)' -f ($b.ChargeRate / 1000) } else { '' }) } else { 'Akku' })
        $ui.EnS0.Text = $(if (-not $b.Online -and -not [double]::IsNaN($b.EstMin)) { Format-EnDur $b.EstMin } elseif ($b.Online) { 'am Netz' } else { '-' })
        $fm = $b.FullMin; if ([double]::IsNaN($fm) -and $script:EnReport) { $fm = $script:EnReport.RuntimeFullMin }
        $ui.EnS1.Text = Format-EnDur $fm
        $ui.EnS2.Text = $(if ($b.Rate -gt 0) { '{0:N1} W' -f ($b.Rate / 1000) } elseif ($b.ChargeRate -gt 0) { '+{0:N1} W' -f ($b.ChargeRate / 1000) } else { '-' })
        $ui.EnS3.Text = $(if ($b.Cycles -ge 0) { [string]$b.Cycles } else { '-' })
        $ui.EnLiveInfo.Text = 'Stand {0:HH:mm:ss} - wird alle 10 Sekunden aktualisiert, solange diese Seite offen ist.{1}' -f (Get-Date), $(if ($b.Online -and $b.Rate -le 0) { ' Den Verbrauch misst der Akku nur im Akkubetrieb - Netzteil kurz abziehen.' } else { '' })
    } elseif ($b.Ups.Count) {
        $u = $b.Ups[0]
        Set-EnRing $ui.EnRingCharge ([double]$u.Percent) $(if ($u.OnBattery) { '#DC2626' } else { '#16A34A' })
        $ui.EnRingChargeVal.Text = '{0} %' -f $u.Percent; $ui.EnRingChargeSub.Text = 'USV'
        $ui.EnHeadline.Text = $(if ($u.OnBattery) { 'STROMAUSFALL - der PC läuft über die USV' } else { 'Desktop-PC mit USV - Netzbetrieb' })
        $ui.EnPowerSrc.Text = $u.Status
        $ui.EnS0.Text = $(if (-not [double]::IsNaN($u.RunMin)) { Format-EnDur $u.RunMin } else { '-' })
        Show-EnUps
    }
}
function Show-EnBattery {
    $b = $script:EnBat; if (-not $b) { return }
    $isBat = [bool]$b.Present
    $ui.EnBatPanel.Visibility = $(if ($isBat) { 'Visible' } else { 'Collapsed' })
    $ui.EnChgPanel.Visibility = $(if ($isBat) { 'Visible' } else { 'Collapsed' })
    $ui.EnDeskPanel.Visibility = $(if ($isBat) { 'Collapsed' } else { 'Visible' })
    $ui.EnUpsPanel.Visibility = $(if ($b.Ups.Count) { 'Visible' } else { 'Collapsed' })
    $ui.EnScorePart.Text = $(if ($script:EnScoreTxt -match '^([\d\.]+)/([\d\.]+)$') { $(if ([double]::Parse($Matches[2], [Globalization.CultureInfo]::InvariantCulture) -gt 0) { '{0} von {1} Punkten' -f $Matches[1], $Matches[2] } else { 'zählt nicht mit (kein Akku)' }) } else { 'noch nicht berechnet (Übersicht)' })
    if (-not $isBat) {
        Set-EnRing $ui.EnRingHealth ([double]::NaN) '#9AA5B8'; $ui.EnRingHealthVal.Text = '-'; $ui.EnRingHealthSub.Text = ''
        if (-not $b.Ups.Count) { Set-EnRing $ui.EnRingCharge ([double]::NaN) '#9AA5B8'; $ui.EnRingChargeVal.Text = '-'; $ui.EnRingChargeSub.Text = 'kein Akku'; $ui.EnHeadline.Text = 'Kein Akku - Desktop-PC'; $ui.EnPowerSrc.Text = 'Netz (direkt)'; foreach ($n in 'EnS0', 'EnS1', 'EnS2', 'EnS3') { $ui[$n].Text = '-' } }
        $ui.EnHeadSub.Text = 'Für Desktop-PCs zeigt diese Seite Standby- und Aufwach-Diagnose, Energiesparpläne, Stromspartipps und - falls angeschlossen - die USV.'
        $ui.EnLiveInfo.Text = ''
        Show-EnBatteryLive; Show-EnDesk; return
    }
    Show-EnBatteryLive
    $h = [double]$b.Health
    Set-EnRing $ui.EnRingHealth $h (Get-EnLevelColor $h)
    $ui.EnRingHealthVal.Text = $(if (-not [double]::IsNaN($h)) { '{0:N0} %' -f $h } else { '-' })
    $ui.EnRingHealthSub.Text = $(if ([double]::IsNaN($h)) { 'nicht gemeldet' } elseif ($h -ge 80) { 'gut' } elseif ($h -ge 60) { 'gebraucht' } else { 'verschlissen' })
    $one = @($b.Batteries)[0]
    $ui.EnBatName.Text = $(if ($b.Batteries.Count -gt 1) { '{0} Akkus: {1}' -f $b.Batteries.Count, ((@($b.Batteries) | ForEach-Object { $_.Name }) -join ' + ') } elseif ($one.Name) { $one.Name } else { '-' })
    $ui.EnBatMaker.Text = $(if ($b.Maker) { $b.Maker } else { '-' })
    $ui.EnBatChem.Text = $(if ($b.Chemistry) { $b.Chemistry } else { '-' })
    $ui.EnBatSerial.Text = $(if ($b.Serial) { $b.Serial } else { '-' })
    $ui.EnBatDate.Text = $(if ($one.ManufactureDate) { $one.ManufactureDate } else { 'vom Akku nicht gemeldet' })
    $ui.EnBatDesign.Text = $(if ($b.Design -gt 0) { '{0:N1} Wh ({1:N0} mWh)' -f ($b.Design / 1000), $b.Design } else { '-' })
    $ui.EnBatFull.Text = $(if ($b.Full -gt 0) { '{0:N1} Wh ({1:N0} mWh)' -f ($b.Full / 1000), $b.Full } else { '-' })
    $ui.EnBatWear.Text = $(if (-not [double]::IsNaN($h)) { '{0:N1} % Kapazität verloren' -f (100 - $h) } else { '-' })
    $ui.EnBatVolt.Text = $(if ($b.Voltage -gt 0) { '{0:N2} V' -f ($b.Voltage / 1000) } else { '-' })
    $v = @()
    if ([double]::IsNaN($h)) { $v += 'Der Akku meldet keine Kapazitätswerte. Oft hilft ein BIOS-/Firmware-Update oder das Neuladen des Akkutreibers (Geräte-Manager > Akkus > "Microsoft ACPI-konforme Kontrollmethodenbatterie" deinstallieren und neu starten).' }
    elseif ($h -ge 90) { $v += ('Sehr guter Zustand: {0:N0} % der ursprünglichen Kapazität.' -f $h) }
    elseif ($h -ge 80) { $v += ('Guter Zustand: {0:N0} % der ursprünglichen Kapazität - normaler Verschleiß.' -f $h) }
    elseif ($h -ge 60) { $v += ('Gebraucht: {0:N0} % der ursprünglichen Kapazität - die Laufzeit ist spürbar kürzer. Eine Ladegrenze verlangsamt den weiteren Verschleiß.' -f $h) }
    else { $v += ('Verschlissen: nur noch {0:N0} % der ursprünglichen Kapazität. Ein Akkutausch ist sinnvoll; ab ca. 40 % kann der Laptop bei Last plötzlich ausgehen.' -f $h) }
    if ($b.Cycles -gt 800) { $v += ('{0} Ladezyklen sind viel - typische Lebensdauer 500-1000 Zyklen.' -f $b.Cycles) }
    if (-not [double]::IsNaN($h) -and $h -gt 100.5) { $v += 'Mehr als 100 % sind normal bei neuen Akkus (Fertigungstoleranz).' }
    $ui.EnBatVerdict.Text = $v -join ' '
}
function Show-EnHistory {
    $own = @($script:EnOwnHist | Where-Object { $_ })
    $rep = @(); if ($script:EnReport) { $rep = @($script:EnReport.History) }
    $days = 0; $t = Get-ComboTag $ui.EnHistRange; if ($t -match '^\d+$') { $days = [int]$t }
    $from = if ($days -gt 0) { (Get-Date).AddDays(-$days) } else { [datetime]::MinValue }
    $p1 = [System.Collections.Generic.List[object]]::new(); $p2 = [System.Collections.Generic.List[object]]::new(); $all = [System.Collections.Generic.List[object]]::new()
    foreach ($h in $rep) { if ($h.Start -ge $from) { $p1.Add(@($h.Start.ToOADate(), [double]$h.Pct)); $all.Add([pscustomobject]@{ Date = $h.Start; Pct = [double]$h.Pct }) } }
    foreach ($h in $own) { if ($h.Date -ge $from) { $p2.Add(@($h.Date.ToOADate(), [double]$h.Pct)); $all.Add([pscustomobject]@{ Date = $h.Date; Pct = [double]$h.Pct }) } }
    if (-not $all.Count) {
        Update-HwChart -Canvas $ui.EnHistChart -Series @() -Empty $(if ($script:EnReport -or $own.Count) { 'Keine Messpunkte in diesem Zeitraum.' } else { 'Verlauf wird geladen ...' })
        $ui.EnHistInfo.Text = ''; return
    }
    $xs = @($all | ForEach-Object { $_.Date.ToOADate() }); $ys = @($all | ForEach-Object { $_.Pct })
    $xmin = [double]($xs | Measure-Object -Minimum).Minimum; $xmax = [double]($xs | Measure-Object -Maximum).Maximum
    if ($xmax - $xmin -lt 7) { $xmin -= 7; $xmax += 1 }
    $ymin = [double]([math]::Floor(([double]($ys | Measure-Object -Minimum).Minimum - 5) / 10) * 10); if ($ymin -lt 0) { $ymin = 0 }; if ($ymin -gt 70) { $ymin = 70 }
    $ymax = [double]([math]::Max(100.0, [math]::Ceiling([double]($ys | Measure-Object -Maximum).Maximum / 10) * 10))
    $ser = @()
    if ($p1.Count) { $ser += @{ Name = 'Windows-Akkubericht (wöchentlich)'; Color = '#16A34A'; Points = $p1.ToArray(); Fill = $true } }
    if ($p2.Count) { $ser += @{ Name = 'PC-Tools (täglich)'; Color = '#2D7FF9'; Points = $p2.ToArray(); Thin = $true } }
    $ser += @{ Name = 'Grenze "gut" (80 %)'; Color = '#D97706'; Points = @(@($xmin, 80.0), @($xmax, 80.0)); Dash = $true; Thin = $true }
    Update-HwChart -Canvas $ui.EnHistChart -Series $ser -XMin $xmin -XMax $xmax -YMin $ymin -YMax $ymax -YFmt '{0:N0} %' -XFmt { param($v) [datetime]::FromOADate($v).ToString('MM.yyyy') }
    $first = @($all | Sort-Object Date)[0].Date; $last = @($all | Sort-Object Date)[-1].Date
    $ui.EnHistInfo.Text = '{0} Messpunkte vom {1:dd.MM.yyyy} bis {2:dd.MM.yyyy}' -f $all.Count, $first, $last
    $tr = Get-EnWearTrend @($all)
    $ui.EnBatTrend.Text = $tr.Text
    if ($script:EnReport) {
        $ui.EnRtFull.Text = Format-EnDur $script:EnReport.RuntimeFullMin
        $ui.EnRtDesign.Text = Format-EnDur $script:EnReport.RuntimeDesignMin
        if ($script:EnBat -and [double]::IsNaN($script:EnBat.FullMin)) { $ui.EnS1.Text = Format-EnDur $script:EnReport.RuntimeFullMin }
    }
}
function Start-EnReportLoad {
    if (-not $script:EnHasBattery) { return }
    $ui.EnHistInfo.Text = 'Akkubericht von Windows wird erstellt ...'
    Invoke-Bg -Script { param($d) Get-EnBatteryReport $d } -Arguments @($script:EnDir) -Functions $script:EnFnAll -Done {
        param($r, $err)
        $x = @($r | Where-Object { $_ })[0]
        if ($err -or -not $x) { $ui.EnHistInfo.Text = 'Akkubericht nicht möglich: ' + $(if ($err) { $err.Message } else { 'keine Daten' }); $ui.EnRtFull.Text = '-'; $ui.EnRtDesign.Text = '-'; Show-EnHistory; return }
        $script:EnReport = $x
        Show-EnHistory
    }
}

# ---------------------------------------------------------------- Was zieht den Akku leer? (SRUM)
function Start-EnSrum {
    if ($script:EnBusy['Srum']) { return }
    $days = 7; $t = Get-ComboTag $ui.EnSrumDays; if ($t -match '^\d+$') { $days = [int]$t }
    $script:EnBusy['Srum'] = $true; $ui.BtnEnSrum.IsEnabled = $false
    $ui.EnSrumInfo.Text = 'Energiedaten werden aus dem Systemressourcen-Monitor gelesen (dauert einige Sekunden) ...'
    Invoke-Bg -Script { param($d, $n) Get-EnSrum $d $n } -Arguments @($script:EnDir, $days) -Functions $script:EnFnAll -Done {
        param($r, $err)
        $script:EnBusy['Srum'] = $false; $ui.BtnEnSrum.IsEnabled = $true
        $x = @($r | Where-Object { $_ })[0]
        if ($err -or -not $x) { $ui.EnSrumInfo.Text = 'Auswertung nicht möglich: ' + $(if ($err) { $err.Message } else { 'keine Daten' }); return }
        $script:EnSrumData = $x
        Show-EnSrum
    }
}
function Show-EnSrum {
    $x = $script:EnSrumData; if (-not $x) { return }
    $flt = [string]$ui.EnSrumFilter.Text
    $apps = @($x.Apps | Where-Object { Test-Match $_ $flt @('Name', 'Id') })
    Set-GridItems $ui.EnSrumGrid $apps
    $ui.EnSrumBars.Children.Clear()
    if (-not @($x.Apps).Count) { $ui.EnSrumInfo.Text = 'Für diesen Zeitraum liegen keine Energiedaten vor. ' + $x.Note + ' (Auf Desktop-PCs ohne Akku schätzt Windows den Energieverbrauch teilweise nicht.)'; return }
    $span = if ($x.From -and $x.To) { ' ({0:dd.MM. HH:mm} bis {1:dd.MM. HH:mm})' -f $x.From, $x.To } else { '' }
    $ui.EnSrumInfo.Text = '{0} Programme und Dienste{1}. Die 12 größten Verbraucher - Anteil am geschätzten Gesamtverbrauch aller Programme, farbig aufgeteilt nach Prozessor, Bildschirm, Netzwerk und Datenträger:' -f @($x.Apps).Count, $span
    # Legende
    $lg = New-Object Windows.Controls.WrapPanel; $lg.Margin = '0,0,0,6'
    foreach ($q in @(@('Prozessor', '#2D7FF9'), @('Bildschirm', '#F59E0B'), @('Netzwerk', '#0891B2'), @('Datenträger', '#7C3AED'), @('Sonstiges', '#94A3B8'))) {
        $sw = New-Object Windows.Shapes.Rectangle; $sw.Width = 12; $sw.Height = 12; $sw.RadiusX = 3; $sw.RadiusY = 3; $sw.Fill = New-UiBrush $q[1]; $sw.Margin = '0,0,5,0'; $sw.VerticalAlignment = 'Center'
        $tl = New-EnText $q[0] 11.5 '#475569'; $tl.Margin = '0,0,16,0'; $tl.VerticalAlignment = 'Center'
        [void]$lg.Children.Add($sw); [void]$lg.Children.Add($tl)
    }
    [void]$ui.EnSrumBars.Children.Add($lg)
    $top = @($apps | Select-Object -First 12)
    $mx = [double](($top | Measure-Object Share -Maximum).Maximum); if (-not ($mx -gt 0)) { $mx = 1 }
    foreach ($a in $top) {
        $g = New-Object Windows.Controls.Grid; $g.Margin = '0,3,0,3'
        foreach ($w in @(250, -1, 70)) { $cd = New-Object Windows.Controls.ColumnDefinition; $cd.Width = $(if ($w -lt 0) { New-Object Windows.GridLength(1, 'Star') } else { New-Object Windows.GridLength($w) }); [void]$g.ColumnDefinitions.Add($cd) }
        $nm = New-EnText $a.Name 12.5 '#1F2A44' 'SemiBold'; $nm.TextWrapping = 'NoWrap'; $nm.TextTrimming = 'CharacterEllipsis'; $nm.VerticalAlignment = 'Center'; $nm.Margin = '0,0,10,0'
        [void]$g.Children.Add($nm)
        $track = New-Object Windows.Controls.Border; $track.Height = 14; $track.CornerRadius = '7'; $track.Background = New-UiBrush '#EEF2F8'; $track.VerticalAlignment = 'Center'
        [Windows.Controls.Grid]::SetColumn($track, 1)
        $bar = New-Object Windows.Controls.Grid
        $fill = [double]$a.Share / $mx
        $segs = @(@($a.CpuPct, '#2D7FF9'), @($a.DisplayPct, '#F59E0B'), @($a.NetPct, '#0891B2'), @($a.DiskPct, '#7C3AED'), @($a.OtherPct, '#94A3B8'))
        $sum = 0.0; foreach ($s in $segs) { $sum += [double]$s[0] }; if ($sum -le 0) { $segs = @(@(100, '#2D7FF9')); $sum = 100 }
        $ci = 0
        foreach ($s in $segs) {
            if ([double]$s[0] -le 0) { continue }
            $cd = New-Object Windows.Controls.ColumnDefinition; $cd.Width = New-Object Windows.GridLength(([double]$s[0] / $sum * $fill * 1000), 'Star'); [void]$bar.ColumnDefinitions.Add($cd)
            $rc = New-Object Windows.Controls.Border; $rc.Background = New-UiBrush $s[1]; [Windows.Controls.Grid]::SetColumn($rc, $ci); [void]$bar.Children.Add($rc); $ci++
        }
        $cd = New-Object Windows.Controls.ColumnDefinition; $cd.Width = New-Object Windows.GridLength(([math]::Max(0.0, (1 - $fill)) * 1000), 'Star'); [void]$bar.ColumnDefinitions.Add($cd)
        $clip = New-Object Windows.Controls.Border; $clip.CornerRadius = '7'; $clip.ClipToBounds = $true; $clip.Child = $bar
        $track.Child = $clip
        [void]$g.Children.Add($track)
        $vt = New-EnText $a.ShareText 12.5 '#1F2A44' 'SemiBold'; $vt.TextAlignment = 'Right'; $vt.VerticalAlignment = 'Center'; [Windows.Controls.Grid]::SetColumn($vt, 2); [void]$g.Children.Add($vt)
        $g.ToolTip = '{0}{1}{2}' -f $a.Mix, "`n", $a.Id
        [void]$ui.EnSrumBars.Children.Add($g)
    }
}

# ---------------------------------------------------------------- Energie-Analyse (powercfg /energy)
$script:EnEnergyTimer = New-Object Windows.Threading.DispatcherTimer
$script:EnEnergyTimer.Interval = [TimeSpan]::FromMilliseconds(500)
$script:EnEnergyTimer.Add_Tick({
    if (-not $script:EnEnergyStart) { $script:EnEnergyTimer.Stop(); return }
    $s = ((Get-Date) - $script:EnEnergyStart).TotalSeconds
    $ui.EnEnergyProg.Value = [math]::Min(98.0, $s * 100 / 62)
    $ui.EnEnergyState.Text = $(if ($s -lt 60) { 'Messung läuft - noch {0:N0} s' -f (60 - $s) } else { 'Bericht wird ausgewertet ...' })
})
function Start-EnEnergy {
    if ($script:EnBusy['Energy']) { return }
    $script:EnBusy['Energy'] = $true; $ui.BtnEnEnergy.IsEnabled = $false
    $ui.EnEnergyList.Children.Clear(); foreach ($n in 'EnEnErr', 'EnEnWarn', 'EnEnInfo') { $ui[$n].Text = '0' }
    $script:EnEnergyStart = Get-Date; $ui.EnEnergyProg.Value = 0; $script:EnEnergyTimer.Start()
    $ui.StatusText.Text = 'Energie-Analyse läuft (60 Sekunden) - den PC möglichst nicht benutzen.'
    Invoke-Bg -Script { param($f) Invoke-EnEnergyTrace $f 60 } -Arguments @((Join-Path $script:EnDir 'Energiebericht.html')) -Functions $script:EnFnAll -Done {
        param($r, $err)
        $script:EnBusy['Energy'] = $false; $ui.BtnEnEnergy.IsEnabled = $true; $script:EnEnergyStart = $null; $script:EnEnergyTimer.Stop()
        $x = @($r | Where-Object { $_ })[0]
        if ($err -or -not $x -or -not $x.Ok) { $ui.EnEnergyProg.Value = 0; $ui.EnEnergyState.Text = 'fehlgeschlagen'; Show-UiError ('Die Energie-Analyse war nicht möglich: ' + $(if ($err) { $err.Message } elseif ($x) { $x.Output } else { 'keine Antwort' }) + "`n`nHinweis: Es darf keine andere Ablaufverfolgung laufen (z.B. eine zweite Analyse oder ein Leistungsmesswerkzeug)."); return }
        $ui.EnEnergyProg.Value = 100; $ui.EnEnergyState.Text = 'fertig ({0:HH:mm})' -f (Get-Date)
        $script:EnEnergyRes = $x
        Show-EnEnergy
        $ui.StatusText.Text = 'Energie-Analyse fertig.'
    }
}
function Show-EnEnergy {
    $x = $script:EnEnergyRes; if (-not $x) { return }
    $items = @($x.Items)
    $ui.EnEnErr.Text = [string]@($items | Where-Object Severity -eq 'Fehler').Count
    $ui.EnEnWarn.Text = [string]@($items | Where-Object Severity -eq 'Warnung').Count
    $ui.EnEnInfo.Text = [string]@($items | Where-Object Severity -eq 'Info').Count
    $ui.EnEnergyList.Children.Clear()
    $show = @($items | Where-Object { $_.Severity -ne 'Info' -or $ui.EnEnShowInfo.IsChecked })
    if (-not $show.Count) { [void]$ui.EnEnergyList.Children.Add((New-EnText $(if ($items.Count) { 'Keine Fehler und Warnungen - sehr gut. (Informationen über das Kästchen oben einblenden.)' } else { 'Der Bericht enthielt keine auswertbaren Einträge - "Originalbericht öffnen" zeigt ihn vollständig.' }) 12.5 '#16A34A' 'SemiBold')); return }
    foreach ($it in $show) {
        $col = switch ($it.Severity) { 'Fehler' { '#DC2626' } 'Warnung' { '#D97706' } default { '#2D7FF9' } }
        $bd = New-Object Windows.Controls.Border; $bd.CornerRadius = '10'; $bd.BorderThickness = '1'; $bd.BorderBrush = New-UiBrush '#E2E7F0'; $bd.Background = New-UiBrush '#F8FAFD'; $bd.Margin = '0,0,0,8'
        $gr = New-Object Windows.Controls.Grid
        $c0 = New-Object Windows.Controls.ColumnDefinition; $c0.Width = New-Object Windows.GridLength(5); $c1 = New-Object Windows.Controls.ColumnDefinition; [void]$gr.ColumnDefinitions.Add($c0); [void]$gr.ColumnDefinitions.Add($c1)
        $strip = New-Object Windows.Controls.Border; $strip.Background = New-UiBrush $col; $strip.CornerRadius = '10,0,0,10'; [void]$gr.Children.Add($strip)
        $sp = New-Object Windows.Controls.StackPanel; $sp.Margin = '12,9,12,9'; [Windows.Controls.Grid]::SetColumn($sp, 1)
        $hd = New-Object Windows.Controls.WrapPanel
        $tag = New-Object Windows.Controls.Border; $tag.CornerRadius = '6'; $tag.Background = New-UiBrush $col; $tag.Padding = '7,1'; $tag.Margin = '0,0,8,0'; $tag.VerticalAlignment = 'Center'
        $tt = New-EnText $it.Severity 11 '#FFFFFF' 'SemiBold'; $tag.Child = $tt; [void]$hd.Children.Add($tag)
        $ht = New-EnText $it.German 13.5 '#1F2A44' 'SemiBold'; $ht.VerticalAlignment = 'Center'; [void]$hd.Children.Add($ht)
        [void]$sp.Children.Add($hd)
        if ($it.German -ne $it.Title) { $ot = New-EnText ('Windows: ' + $it.Title) 11.5 '#6B7890'; $ot.Margin = '0,3,0,0'; [void]$sp.Children.Add($ot) }
        if ($it.Explain) { $et = New-EnText $it.Explain 12.5 '#1F2A44'; $et.Margin = '0,5,0,0'; [void]$sp.Children.Add($et) }
        if ($it.Desc) { $dt = New-EnText $it.Desc 12 '#475569'; $dt.Margin = '0,4,0,0'; $dt.FontStyle = 'Italic'; [void]$sp.Children.Add($dt) }
        if ($it.Tip) { $tp = New-EnText ('Tipp: ' + $it.Tip) 12.5 '#0F766E'; $tp.Margin = '0,5,0,0'; [void]$sp.Children.Add($tp) }
        if (@($it.Details).Count) {
            $ex = New-Object Windows.Controls.Expander; $ex.Header = 'Details ({0})' -f @($it.Details).Count; $ex.Margin = '0,6,0,0'; $ex.Foreground = New-UiBrush '#475569'
            $dtx = New-Object Windows.Controls.TextBox; $dtx.Text = (@($it.Details) -join "`r`n"); $dtx.IsReadOnly = $true; $dtx.TextWrapping = 'Wrap'; $dtx.FontFamily = 'Consolas'; $dtx.FontSize = 11.5; $dtx.MaxHeight = 220; $dtx.VerticalScrollBarVisibility = 'Auto'; $dtx.Margin = '0,4,0,0'
            $ex.Content = $dtx; [void]$sp.Children.Add($ex)
        }
        [void]$gr.Children.Add($sp); $bd.Child = $gr
        [void]$ui.EnEnergyList.Children.Add($bd)
    }
}

# ---------------------------------------------------------------- Standby und Aufwachen
function Start-EnSleepLoad {
    if ($script:EnBusy['Sleep']) { return }
    $script:EnBusy['Sleep'] = $true
    $ui.EnSlpType.Text = 'wird eingelesen ...'
    Invoke-Bg -Script { Get-EnSleepInfo } -Functions $script:EnFnAll -Done {
        param($r, $err)
        $script:EnBusy['Sleep'] = $false
        $x = @($r | Where-Object { $_ })[0]
        if ($err -or -not $x) { $ui.EnSlpType.Text = 'nicht lesbar: ' + $(if ($err) { $err.Message } else { 'keine Daten' }); return }
        $script:EnSleep = $x
        Show-EnSleep
    }
}
function Show-EnSleep {
    $s = $script:EnSleep; if (-not $s) { return }
    $st = $s.States
    $ui.EnSlpType.Text = $(if ($st.ModernStandby) { 'Modern Standby (S0 "Niedrigenergie-Leerlauf"){0}' -f $(if ($st.S0Network) { ', Netzwerk bleibt verbunden' } else { ', Netzwerk getrennt' }) } elseif ($st.S3) { 'Klassischer Standby (S3)' } else { 'Kein Standby verfügbar' })
    $ui.EnSlpAvail.Text = $(if (@($st.Available).Count) { (@($st.Available) | ForEach-Object { $_.Name }) -join ', ' } else { '-' })
    $ui.EnSlpNot.Text = $(if (@($st.NotAvailable).Count) { (@($st.NotAvailable) | ForEach-Object { $_.Name }) -join ', ' } else { '-' })
    $tip = (@($st.NotAvailable) | ForEach-Object { '{0}: {1}' -f $_.Name, (@($_.Reasons) -join ' ') }) -join "`n"
    $ui.EnSlpNot.ToolTip = $(if ($tip) { $tip } else { $null })
    $ui.EnLastWake.Text = $(if (@($s.LastWake).Count) { (@($s.LastWake) | ForEach-Object { $_.Text }) -join ', ' } elseif (@($s.History).Count) { @($s.History)[0].Source } else { 'unbekannt' })
    $ui.EnHibState.Text = $(if ($s.HibOn) { 'an' + $(if ($s.HibType) { ', Datei ' + $s.HibType } else { '' }) + $(if ($s.HibSize -gt 0) { ' ({0:N1} GB auf {1})' -f ($s.HibSize / 1GB), $env:SystemDrive } else { '' }) } else { 'aus' })
    $ui.EnFastState.Text = $(if ($s.FastStartup -and $s.HibOn) { 'an (Herunterfahren ist ein halber Ruhezustand - nach Treiber-/Update-Problemen besser "Neu starten")' } elseif ($s.FastStartup) { 'eingestellt, aber wirkungslos (Ruhezustand ist aus)' } else { 'aus (jeder Start ist ein echter Kaltstart)' })
    $ex = @()
    if ($st.ModernStandby) {
        $ex += 'Modern Standby: Der PC schläft wie ein Handy - der Bildschirm ist aus, Windows holt aber zwischendurch E-Mails und Updates. Normal sind 0,5-2 % Akku pro Stunde. Wird der Laptop in der Tasche warm oder ist morgens leer, verhindert meist ein Programm oder Gerät den Tiefschlaf - die Standby-Analyse unten zeigt den Verursacher.'
        if (-not $s.HibOn) { $ex += 'Tipp: Den Ruhezustand einschalten und unter Individualisieren "Ruhezustand nach" im Akkubetrieb auf z.B. 3 Stunden stellen - dann wechselt ein langer Standby automatisch in den stromlosen Ruhezustand.' }
        if (@($st.NotAvailable | Where-Object { $_.Id -eq 'S3' }).Count) { $ex += 'Der klassische Standby (S3) ist auf diesem Gerät abgeschaltet, weil Modern Standby unterstützt wird - bei neueren Geräten lässt er sich nicht zurückholen.' }
    } elseif ($st.S3) {
        $ex += 'Klassischer Standby (S3): Nur der Arbeitsspeicher bleibt mit Strom versorgt, alles andere ist aus - sehr sparsam (Laptop ca. 0,5-1 % pro Stunde). Aufwecken können nur die unten erlaubten Geräte und Weckzeitgeber.'
    } else { $ex += 'Es ist kein Standby verfügbar - meist fehlt der Grafik- oder Chipsatztreiber (Geräte-Manager prüfen) oder es läuft eine virtuelle Maschine.' }
    if (@($s.Requests).Count) { $ex += ('Gerade hält {0} den PC wach (siehe Tabelle).' -f $(if (@($s.Requests).Count -eq 1) { 'ein Eintrag' } else { '{0} Einträge' -f @($s.Requests).Count })) }
    $ui.EnSlpExplain.Text = $ex -join ' '
    Set-GridItems $ui.EnReqGrid @($s.Requests)
    Set-GridItems $ui.EnTimerGrid @(@($s.Timers) | ForEach-Object { [pscustomobject]@{ When = $_.When; Name = $_.Name; Reason = $(if ($_.Task) { $_.Task } else { $_.Reason }) } })
    Set-GridItems $ui.EnWakeGrid @($s.Devices)
    Set-GridItems $ui.EnWakeHist @($s.History)
    $ui.BtnEnHib.Content = $(if ($s.HibOn) { 'Ruhezustand ausschalten' } else { 'Ruhezustand einschalten' })
    $ui.BtnEnHibType.Content = $(if ($s.HibType -eq 'reduziert') { 'Ruhezustandsdatei: vollständig' } else { 'Ruhezustandsdatei: reduziert (spart Platz)' })
    $ui.BtnEnHibType.IsEnabled = [bool]$s.HibOn
    $ui.BtnEnFast.Content = $(if ($s.FastStartup) { 'Schnellstart ausschalten' } else { 'Schnellstart einschalten' })
    $ui.BtnEnSleepStudy.IsEnabled = [bool]$st.ModernStandby
    $ui.BtnEnSleepStudy.ToolTip = $(if ($st.ModernStandby) { $null } else { 'Nur bei Modern Standby (S0) verfügbar - bei S3 die System-Standby-Diagnose nutzen.' })
}
function Invoke-EnPowerCfg([string]$ArgLine, [string]$Done) {
    $o = Invoke-NdCmd 'powercfg.exe' $ArgLine 30
    if ($o -and $o -match '(?i)error|fehler|ungültig|invalid|nicht|denied|verweigert') { Show-UiError ('powercfg {0}:{1}{2}' -f $ArgLine, "`n", $o); return $false }
    $ui.StatusText.Text = $Done
    return $true
}
function Set-EnWake([bool]$Allow) {
    $sel = @($ui.EnWakeGrid.SelectedItems | Where-Object { $_ -and ([bool]$_.Armed -ne $Allow) })
    if (-not $sel.Count) { Show-UiError $(if ($Allow) { 'Bitte ein oder mehrere Geräte auswählen, die den PC noch NICHT wecken dürfen.' } else { 'Bitte ein oder mehrere Geräte auswählen, die den PC wecken dürfen (Spalte "Darf wecken" = Ja).' }); return }
    $names = ($sel | ForEach-Object { '- ' + $_.Name }) -join "`n"
    $q = if ($Allow) { "Diesen Geräten erlauben, den PC aus dem Standby zu wecken?`n`n{0}" -f $names } else { "Diesen Geräten das Wecken aus dem Standby verbieten?`n`n{0}`n`nHinweis: Verbietet man es Tastatur UND Maus, lässt sich der PC nur noch mit dem Netzschalter aufwecken. Bei der Netzwerkkarte funktioniert danach Wake-on-LAN nicht mehr." -f $names }
    if (-not (Confirm-Ui $q $(if ($Allow) { 'Question' } else { 'Warning' }))) { return }
    $bad = @()
    foreach ($d in $sel) {
        $o = Invoke-NdCmd 'powercfg.exe' ('{0} "{1}"' -f $(if ($Allow) { '/deviceenablewake' } else { '/devicedisablewake' }), ($d.Name -replace '"', '')) 20
        if ($o.Trim()) { $bad += ('{0}: {1}' -f $d.Name, $o.Trim()) }
    }
    if ($bad.Count) { Show-UiError ("Nicht bei allen Geräten möglich:`n" + ($bad -join "`n")) } else { $ui.StatusText.Text = $(if ($Allow) { 'Wecken erlaubt.' } else { 'Wecken verboten.' }) }
    Start-EnSleepLoad
}
function Start-EnSleepStudy {
    if ($script:EnBusy['Study']) { return }
    $script:EnBusy['Study'] = $true; $ui.BtnEnSleepStudy.IsEnabled = $false
    $ui.EnSsInfo.Text = 'Standby-Analyse der letzten 3 Tage wird erstellt ...'
    Invoke-Bg -Script { param($d) Get-EnSleepStudy $d 3 } -Arguments @($script:EnDir) -Functions $script:EnFnAll -Done {
        param($r, $err)
        $script:EnBusy['Study'] = $false; $ui.BtnEnSleepStudy.IsEnabled = $true
        $x = @($r | Where-Object { $_ })[0]
        if ($err -or -not $x) { $ui.EnSsInfo.Text = 'Nicht möglich: ' + $(if ($err) { $err.Message } else { 'keine Antwort' }); return }
        $script:EnSleepHtml = $x.Html
        if (-not $x.Ok) { $ui.EnSsInfo.Text = 'Die Daten konnten nicht ausgewertet werden' + $(if ($x.Html) { ' - "Bericht öffnen" zeigt den vollständigen Bericht von Windows.' } else { ': ' + $x.Output }); Set-GridItems $ui.EnSsGrid @(); return }
        $d = $x.Data
        $ss = @($d.Sessions)
        if (-not $ss.Count) { $ui.EnSsInfo.Text = 'In den letzten 3 Tagen gab es keine Standby-Phasen.'; Set-GridItems $ui.EnSsGrid @(); return }
        $ui.EnSsInfo.Text = '{0} Standby-Phasen{1}{2}. Tiefschlaf-Anteil (DRIPS) über 90 % ist gut, unter 80 % verbraucht der Standby unnötig Strom - in der Spalte "Hauptverursacher" steht, wer gestört hat.' -f $d.StandbyCount, $(if (-not [double]::IsNaN([double]$d.AvgDrips)) { ', Tiefschlaf im Mittel {0:N0} %' -f $d.AvgDrips } else { '' }), $(if ($d.BadCount) { ', davon {0} auffällig' -f $d.BadCount } else { ', keine auffällig' })
        Set-GridItems $ui.EnSsGrid $ss
    }
}
function Start-EnSleepDiag {
    $f = Join-Path $script:EnDir 'System-Standby-Diagnose.html'; $script:EnDiagFile = $f
    $ui.StatusText.Text = 'System-Standby-Diagnose wird erstellt ...'
    Invoke-Bg -Script { param($p) $null = New-Item (Split-Path $p -Parent) -ItemType Directory -Force -ErrorAction SilentlyContinue; $o = Invoke-NdCmd 'powercfg.exe' ('/systemsleepdiagnostics /output "{0}"' -f $p) 120; [pscustomobject]@{ Ok = (Test-Path -LiteralPath $p); Out = $o } } -Arguments @($f) -Functions $script:EnFnAll -Done {
        param($r, $err)
        $x = @($r | Where-Object { $_ })[0]
        if ($err -or -not $x -or -not $x.Ok) { Show-UiError ('Die System-Standby-Diagnose war nicht möglich: ' + $(if ($err) { $err.Message } elseif ($x) { $x.Out } else { '' })); return }
        $ui.StatusText.Text = 'System-Standby-Diagnose gespeichert: ' + $script:EnDiagFile
        try { Start-Process -FilePath $script:EnDiagFile } catch { }
    }
}

# ---------------------------------------------------------------- Energiepläne und Energiemodus
function Start-EnPlansLoad {
    Invoke-Bg -Script { [pscustomobject]@{ Plans = @(Get-EnPlans); Overlay = (Get-EnOverlay) } } -Functions $script:EnFnAll -Done {
        param($r, $err)
        $x = @($r | Where-Object { $_ })[0]; if ($err -or -not $x) { return }
        $script:EnPlansData = @($x.Plans); $script:EnOverlay = $x.Overlay
        Show-EnPlans; Show-EnMode
    }
}
function Show-EnPlans {
    $pl = @($script:EnPlansData)
    Set-GridItems $ui.EnPlanGrid $pl
    $act = @($pl | Where-Object Active)[0]
    if ($act) { $ui.EnPlanGrid.SelectedItem = @($ui.EnPlanGrid.ItemsSource | Where-Object Active)[0] }
    $ov = $script:EnOverlay
    $mode = ''
    if ($ov -and $act -and $act.Guid -eq $EnBalancedGuid) { $g = $(if ($script:EnBat -and -not $script:EnBat.Online) { $ov.Dc } else { $ov.Ac }); $m = @(Get-EnOverlayDefs | Where-Object { $_.Guid -eq $g })[0]; if ($m) { $mode = ' · Modus "{0}"' -f $m.Name } }
    $ui.EnPlanNow.Text = $(if ($act) { $act.Name + $mode } else { '-' })
}
function Show-EnMode {
    $ov = $script:EnOverlay
    if (-not $ov) { $ui.EnModeInfo.Text = 'Energiemodus nicht lesbar.'; return }
    Set-ComboByTag $ui.EnModeAc $ov.Ac; Set-ComboByTag $ui.EnModeDc $ov.Dc
    $act = @($script:EnPlansData | Where-Object Active)[0]
    $ui.EnModeInfo.Text = $(if ($act -and $act.Guid -ne $EnBalancedGuid) { 'Hinweis: Aktiv ist "{0}" - der Energiemodus wirkt nur mit "Ausbalanciert".' -f $act.Name } else { '' })
    $ui.EnModeDc.IsEnabled = [bool]($script:EnBat -and $script:EnBat.Present)
    $lv = [int]$script:EnSaverLvl
    $ui.EnSaverInfo.Text = $(if ($script:EnBat -and $script:EnBat.Saver) { 'Der Energiesparmodus ist gerade EINGESCHALTET. ' } else { 'Der Energiesparmodus ist gerade aus. ' }) + $(if ($lv -eq 100) { 'Er ist im Akkubetrieb immer an.' } elseif ($lv -gt 0) { 'Er schaltet sich im Akkubetrieb bei {0} % Restladung automatisch ein.' -f $lv } elseif ($lv -eq 0) { 'Er schaltet sich nie automatisch ein.' } else { '' })
}
function New-EnPlanFromPreset {
    $key = Get-ComboTag $ui.EnPlanPreset; if (-not $key) { return }
    $pre = @(Get-EnPlanPresets | Where-Object { $_.Key -eq $key })[0]
    $old = @($script:EnPlansData | Where-Object { $_.Name -eq $pre.Name })
    $q = 'Energiesparplan "{0}" anlegen und aktivieren?{1}{1}{2}' -f $pre.Name, "`n", $pre.Desc
    if ($old.Count) { $q += "`n`nEinen Plan mit diesem Namen gibt es schon - er wird durch den neuen ersetzt." }
    if (-not (Confirm-Ui $q)) { return }
    foreach ($p in $old) {
        if ($p.Active) { $null = Invoke-NdCmd 'powercfg.exe' ('/setactive {0}' -f $EnBalancedGuid) 15 }
        $null = Invoke-NdCmd 'powercfg.exe' ('/delete {0}' -f $p.Guid) 15
    }
    $ui.StatusText.Text = 'Energiesparplan wird angelegt ...'
    Invoke-Bg -Script { param($k) New-EnPowerPlan $k $true } -Arguments @($key) -Functions $script:EnFnAll -Done {
        param($r, $err)
        $x = @($r | Where-Object { $_ })[0]
        if ($err -or -not $x) { Show-UiError ('Plan konnte nicht angelegt werden: ' + $(if ($err) { $err.Message } else { 'unbekannter Fehler' })); return }
        $ui.StatusText.Text = 'Energiesparplan "{0}" angelegt und aktiv.{1}' -f $x.Name, $(if (@($x.Notes).Count) { ' Einige Werte unterstützt dieses Gerät nicht: ' + (@($x.Notes) -join '; ') } else { '' })
        Start-EnPlansLoad
    }
}

# ---------------------------------------------------------------- Ladegrenze
function Start-EnChargeLoad {
    if (-not $script:EnHasBattery) { return }
    if ($script:EnBusy['Chg']) { return }
    $script:EnBusy['Chg'] = $true
    $ui.EnChgMethod.Text = 'wird eingelesen ...'; $ui.EnChgList.Children.Clear(); $ui.BtnEnChgApply.IsEnabled = $false
    Invoke-Bg -Script { Get-EnChargeLimit } -Functions $script:EnFnAll -Done {
        param($r, $err)
        $script:EnBusy['Chg'] = $false
        $x = @($r | Where-Object { $_ })[0]
        if ($err -or -not $x) { $ui.EnChgMethod.Text = 'nicht lesbar: ' + $(if ($err) { $err.Message } else { '-' }); return }
        $script:EnChg = $x
        Show-EnCharge
    }
}
function Show-EnCharge {
    $c = $script:EnChg; if (-not $c) { return }
    $ui.EnChgDevice.Text = '{0} {1}' -f $c.Vendor, $c.Model
    $ui.EnChgMethod.Text = $c.Method
    $st = $c.State
    if (-not $st -and @($c.Settings).Count) { $st = (@($c.Settings) | ForEach-Object { '{0}: {1}' -f $_.Label, $_.CurrentText }) -join ' · ' }
    if (-not $st -and $script:EnBat -and $script:EnBat.Online -and -not $script:EnBat.Charging -and $script:EnBat.Percent -ge 45 -and $script:EnBat.Percent -le 85) { $st = 'Der Akku bleibt am Netzteil bei {0} % stehen - vermutlich ist eine Ladegrenze aktiv.' -f $script:EnBat.Percent }
    $ui.EnChgState.Text = $(if ($st) { $st } else { 'nicht aus Windows auslesbar' })
    $ui.EnChgList.Children.Clear(); $script:EnChgCtl.Clear()
    foreach ($s in @($c.Settings)) {
        $g = New-Object Windows.Controls.Grid; $g.Margin = '0,3,0,3'
        $c0 = New-Object Windows.Controls.ColumnDefinition; $c0.Width = New-Object Windows.GridLength(300); $c1 = New-Object Windows.Controls.ColumnDefinition; [void]$g.ColumnDefinitions.Add($c0); [void]$g.ColumnDefinitions.Add($c1)
        $lb = New-EnText ([string]$s.Label) 12.5 '#1F2A44'; $lb.VerticalAlignment = 'Center'; $lb.Margin = '0,0,10,0'; [void]$g.Children.Add($lb)
        if (@($s.Options).Count) {
            $ctl = New-Object Windows.Controls.ComboBox; $ctl.Width = 380; $ctl.HorizontalAlignment = 'Left'
            foreach ($op in @($s.Options)) { $ci = New-Object Windows.Controls.ComboBoxItem; $ci.Content = Get-EnChargeValueText $s.Name $op; $ci.Tag = [string]$op; [void]$ctl.Items.Add($ci); if ([string]$op -eq [string]$s.Current) { $ctl.SelectedItem = $ci } }
        } else {
            $ctl = New-Object Windows.Controls.TextBox; $ctl.Width = 120; $ctl.HorizontalAlignment = 'Left'; $ctl.Text = [string]$s.Current; $ctl.Padding = '4,3'
            if ([string]$s.Type -match 'Integer (\d+)-(\d+)') { $ctl.ToolTip = 'erlaubt: {0} bis {1}' -f $Matches[1], $Matches[2] }
        }
        $ctl.IsEnabled = -not [bool]$s.ReadOnly
        [Windows.Controls.Grid]::SetColumn($ctl, 1); [void]$g.Children.Add($ctl)
        [void]$ui.EnChgList.Children.Add($g)
        $script:EnChgCtl.Add([pscustomobject]@{ Setting = $s; Control = $ctl })
    }
    $ui.EnChgPwdRow.Visibility = $(if ($c.Settable) { 'Visible' } else { 'Collapsed' })
    $ui.BtnEnChgApply.IsEnabled = [bool]$c.Settable
    $ui.BtnEnChgApply.Visibility = $(if (@($c.Settings).Count) { 'Visible' } else { 'Collapsed' })
    $hint = @(); if ($c.Hint) { $hint += $c.Hint }; if ($c.App) { $hint += $c.App }; foreach ($e in @($c.Extra)) { $hint += $e }
    $ui.EnChgHint.Text = $hint -join "`n"
}
function Save-EnCharge {
    $chg = [System.Collections.Generic.List[object]]::new()
    foreach ($m in $script:EnChgCtl) {
        $s = $m.Setting; if ($s.ReadOnly) { continue }
        $val = if ($m.Control -is [Windows.Controls.ComboBox]) { if ($m.Control.SelectedItem) { [string]$m.Control.SelectedItem.Tag } else { '' } } else { ([string]$m.Control.Text).Trim() }
        if (-not $val -or $val -eq [string]$s.Current) { continue }
        if ([string]$s.Type -match 'Integer (\d+)-(\d+)') { if ($val -notmatch '^\d+$' -or [int]$val -lt [int]$Matches[1] -or [int]$val -gt [int]$Matches[2]) { Show-UiError ('{0}: bitte eine Zahl von {1} bis {2} eingeben.' -f $s.Label, $Matches[1], $Matches[2]); return } }
        $chg.Add([pscustomobject]@{ Vendor = $s.Vendor; Name = $s.Name; Value = $val; Label = $s.Label; Text = (Get-EnChargeValueText $s.Name $val); IsInt = ([string]$s.Type -like 'Integer*') })
    }
    if (-not $chg.Count) { $ui.StatusText.Text = 'Keine Änderung an der Ladegrenze.'; return }
    # Zahlen (Start/Stopp) zuerst, dann den Modus - sonst lehnt das BIOS "Benutzerdefiniert" ab
    $ordered = @(@($chg | Where-Object IsInt) + @($chg | Where-Object { -not $_.IsInt }))
    $txt = ($ordered | ForEach-Object { '- {0}: {1}' -f $_.Label, $_.Text }) -join "`n"
    if (-not (Confirm-Ui ("Diese Einstellungen im BIOS/UEFI ändern?`n`n{0}`n`nDie Ladegrenze gilt meist sofort, spätestens nach dem nächsten Neustart." -f $txt))) { return }
    $ui.BtnEnChgApply.IsEnabled = $false; $ui.StatusText.Text = 'Ladegrenze wird gesetzt ...'
    $enArgs = New-Object object[] 2; $enArgs[0] = $ordered; $enArgs[1] = [string]$ui.EnChgPwd.Password
    Invoke-Bg -Script { param($c, $p) Set-OemBiosSettings $c $p } -Arguments $enArgs -Functions $script:EnFnAll -Done {
        param($r, $err)
        $ui.EnChgPwd.Password = ''
        $res = @($r | Where-Object { $_ })
        if ($err) { Show-UiError ('Ladegrenze konnte nicht gesetzt werden: ' + $err.Message); Start-EnChargeLoad; return }
        $bad = @($res | Where-Object { -not $_.Ok })
        if ($bad.Count) { Show-UiError ("Nicht übernommen:`n" + (($bad | ForEach-Object { '{0} = {1}: {2}' -f $_.Name, $_.Value, $(if ($_.Msg -match '^(6|Access Denied|5)$') { 'Zugriff verweigert - BIOS-Kennwort nötig oder falsch' } else { $_.Msg }) }) -join "`n")) }
        else { $ui.StatusText.Text = 'Ladegrenze übernommen ({0} Einstellung(en)).' -f $res.Count }
        Start-EnChargeLoad
    }
}
function Start-EnStoreApp([string[]]$Names) {
    foreach ($n in $Names) {
        try {
            $p = @(Get-AppxPackage -Name $n -ErrorAction Stop)[0]; if (-not $p) { continue }
            $id = @(([xml](Get-Content -LiteralPath (Join-Path $p.InstallLocation 'AppxManifest.xml') -Raw)).Package.Applications.Application)[0].Id
            Start-Process ('shell:AppsFolder\{0}!{1}' -f $p.PackageFamilyName, $id); return $true
        } catch { }
    }
    return $false
}
function Open-EnChargeApp {
    $v = $(if ($script:EnChg) { [string]$script:EnChg.Vendor } else { '' })
    switch ($v) {
        'Lenovo' { $ui.BtnBatVantage.RaiseEvent((New-Object Windows.RoutedEventArgs ([Windows.Controls.Primitives.ButtonBase]::ClickEvent))); return }
        'Surface' { if (Start-EnStoreApp @('Microsoft.SurfaceHub')) { return } }
        'ASUS' { if (Start-EnStoreApp @('B9ECED6F.ASUSPCAssistant')) { return } }
        'HP' { if (Start-EnStoreApp @('AD2F1837.HPSupportAssistant', 'AD2F1837.HPPowerManager')) { return } }
        'Dell' { if (Start-EnStoreApp @('DellInc.DellPowerManager', 'DellInc.DellOptimizer')) { return } }
        'Acer' { if (Start-EnStoreApp @('AcerIncorporated.AcerCareCenterS', 'AcerIncorporated.AcerSense')) { return } }
        'MSI' { if (Start-EnStoreApp @('9426MICRO-STARINTERNATION.MSICenter')) { return } }
    }
    try { Start-Process 'ms-settings:batterysaver' } catch { }
    $ui.StatusText.Text = 'Keine Hersteller-App gefunden - Windows-Einstellungen "Energie und Akku" geöffnet.'
}

# ---------------------------------------------------------------- USV und Desktop
function Show-EnUps {
    $b = $script:EnBat; if (-not $b -or -not @($b.Ups).Count) { return }
    $u = @($b.Ups)[0]
    $ui.EnUpsName.Text = $(if (@($b.Ups).Count -gt 1) { '{0} (+{1} weitere)' -f $u.Name, (@($b.Ups).Count - 1) } else { $u.Name })
    $ui.EnUpsState.Text = $u.Status
    $ui.EnUpsState.Foreground = New-UiBrush $(if ($u.OnBattery) { '#DC2626' } else { '#16A34A' })
    $ui.EnUpsCharge.Text = '{0} %' -f $u.Percent
    $ui.EnUpsRun.Text = $(if (-not [double]::IsNaN([double]$u.RunMin)) { 'ca. ' + (Format-EnDur $u.RunMin) + ' bei der aktuellen Last' } else { 'von der USV nicht gemeldet' })
    $cr = $script:EnCrit
    if ($cr) {
        $an = switch ([int]$cr.Action) { 0 { 'nichts tun (gefährlich: der PC geht hart aus, wenn die USV leer ist)' } 1 { 'Energie sparen' } 2 { 'Ruhezustand' } 3 { 'Herunterfahren' } default { '?' } }
        $ui.EnUpsAction.Text = 'Bei {0} % Restladung: {1}' -f $cr.Level, $an
        Set-ComboByTag $ui.EnUpsLevel ([string]$cr.Level); Set-ComboByTag $ui.EnUpsAct ([string]$cr.Action)
    } else { $ui.EnUpsAction.Text = '-' }
}
function Save-EnUps {
    $lv = Get-ComboInt $ui.EnUpsLevel; $ac = Get-ComboInt $ui.EnUpsAct
    if ($lv -lt 0 -or $ac -lt 0) { Show-UiError 'Bitte Restladung und Aktion auswählen.'; return }
    if (-not (Confirm-Ui ('Bei Stromausfall (Betrieb über die USV) ab {0} % Restladung: {1}?' -f $lv, $ui.EnUpsAct.SelectedItem.Content))) { return }
    Set-PwrValue 'SUB_BATTERY' 'BATLEVELCRIT' -1 $lv; Set-PwrValue 'SUB_BATTERY' 'BATACTIONCRIT' -1 $ac
    $null = & powercfg.exe /setactive SCHEME_CURRENT 2>&1
    $ui.StatusText.Text = 'USV-Einstellung für den aktiven Energiesparplan übernommen.'
    Start-EnBatteryLoad $true
}
$EnDeskTips = @(
    @('&#xE7F4;', 'Bildschirme', 'Der Monitor braucht oft mehr als der PC im Leerlauf (25-60 W). "Bildschirm ausschalten nach" auf 5-10 Minuten, Helligkeit reduzieren, Monitor-Eco-Modus nutzen und die Steckdosenleiste abends ausschalten.'),
    @('&#xE708;', 'Standby statt Leerlauf', 'Ein Büro-PC im Leerlauf zieht 30-80 W, im Standby 1-3 W. "Energie sparen nach" auf 20-30 Minuten stellen. Muss der PC nachts für Updates oder Fernwartung erreichbar sein: Wake-on-LAN statt Durchlaufen.'),
    @('&#xE945;', 'Energiesparplan', '"Ausbalanciert" oder "PC-Tools Ausgewogen leise" statt "Höchstleistung"/"Ultimative Leistung" - die Leistung ist im Alltag gleich, der Prozessor darf aber im Leerlauf heruntertakten und Kerne schlafen legen.'),
    @('&#xE950;', 'BIOS: C-States, ASPM und ErP', 'Im BIOS/UEFI die Energiesparzustände des Prozessors (C-States, "Package C-State"), PCIe ASPM und den ErP-/EuP-Modus (unter 0,5 W im ausgeschalteten Zustand) einschalten. Übertaktungsprofile (XMP/EXPO, "Multicore Enhancement") erhöhen den Verbrauch deutlich.'),
    @('&#xE7F8;', 'Grafikkarte', 'Mehrere Monitore mit hoher Bildwiederholrate halten viele Grafikkarten im Leerlauf auf hohem Takt (20-40 W mehr). Bildwiederholrate des Zweitmonitors auf 60 Hz senken oder die integrierte Grafik für Büroarbeit nutzen.'),
    @('&#xE7E8;', 'Peripherie und Netzteil', 'Drucker, Lautsprecher, USB-Hubs und Ladegeräte über eine schaltbare Steckdosenleiste. Ein Netzteil mit 80-PLUS-Gold-Zertifikat und passender Leistung (nicht überdimensioniert) spart dauerhaft 5-10 %.'),
    @('&#xE9D9;', 'Hintergrundprogramme', '"Was zieht den Akku leer?" funktioniert auch am Desktop: Programme mit hohem Prozessoranteil im Leerlauf (Updater, Synchronisierung, Browser-Tabs) verhindern Stromsparzustände.')
)
function Show-EnDesk {
    $ui.EnDeskIntro.Text = 'Dieser PC hat keinen Akku. Ein Büro-PC läuft schnell 2.000 Stunden im Jahr - jedes eingesparte Watt im Dauerbetrieb sind rund 9 kWh bzw. 3 Euro pro Jahr. Die wirksamsten Stellschrauben:'
    if ($ui.EnDeskTips.Children.Count) { return }
    foreach ($t in $EnDeskTips) {
        $g = New-Object Windows.Controls.Grid; $g.Margin = '0,0,0,10'
        $c0 = New-Object Windows.Controls.ColumnDefinition; $c0.Width = New-Object Windows.GridLength(40); $c1 = New-Object Windows.Controls.ColumnDefinition; [void]$g.ColumnDefinitions.Add($c0); [void]$g.ColumnDefinitions.Add($c1)
        $bd = New-Object Windows.Controls.Border; $bd.Width = 30; $bd.Height = 30; $bd.CornerRadius = '9'; $bd.Background = New-UiBrush '#16A34A'; $bd.VerticalAlignment = 'Top'; $bd.HorizontalAlignment = 'Left'
        $gl = New-Object Windows.Controls.TextBlock; $gl.FontFamily = 'Segoe MDL2 Assets'; $gl.Text = [System.Net.WebUtility]::HtmlDecode($t[0]); $gl.FontSize = 14; $gl.Foreground = New-UiBrush '#FFFFFF'; $gl.HorizontalAlignment = 'Center'; $gl.VerticalAlignment = 'Center'; $bd.Child = $gl
        [void]$g.Children.Add($bd)
        $sp = New-Object Windows.Controls.StackPanel; [Windows.Controls.Grid]::SetColumn($sp, 1)
        [void]$sp.Children.Add((New-EnText $t[1] 13.5 '#1F2A44' 'SemiBold')); $tx = New-EnText $t[2] 12.5 '#475569'; $tx.Margin = '0,2,0,0'; [void]$sp.Children.Add($tx)
        [void]$g.Children.Add($sp); [void]$ui.EnDeskTips.Children.Add($g)
    }
    Update-EnCalc
}
function Update-EnCalc {
    $w = ConvertTo-EnNum $ui.EnCalcW.Text; $h = ConvertTo-EnNum $ui.EnCalcH.Text; $d = ConvertTo-EnNum $ui.EnCalcD.Text; $ct = ConvertTo-EnNum $ui.EnCalcCt.Text
    if ([double]::IsNaN($w) -or [double]::IsNaN($h) -or [double]::IsNaN($d) -or [double]::IsNaN($ct) -or $w -lt 0 -or $h -lt 0 -or $h -gt 24 -or $d -lt 0 -or $d -gt 7) { $ui.EnCalcRes.Text = 'Bitte gültige Zahlen eingeben (Stunden 0-24, Tage 0-7).'; return }
    $kwh = $w * $h * $d * 52.143 / 1000
    $eur = $kwh * $ct / 100
    $ui.EnCalcRes.Text = 'ca. {0:N0} kWh pro Jahr = {1:N2} Euro (bei {2:N1} Cent/kWh). Zum Vergleich: 1 Watt rund um die Uhr kostet {3:N2} Euro im Jahr - ein PC, der nachts durchläuft, kostet so schnell 50-150 Euro extra.' -f $kwh, $eur, $ct, (8.76 * $ct / 100)
}

