    $q = if ($on) { 'Schnellstart einschalten? Der PC startet nach dem Herunterfahren schneller (Windows-Kern wird wie beim Ruhezustand gespeichert). Voraussetzung: Ruhezustand ist an.' } else { 'Schnellstart ausschalten? Jeder Start ist dann ein echter Kaltstart (dauert etwas länger). Empfohlen bei Dual-Boot, Problemen mit Treibern/Updates oder wenn Wake-on-LAN nach dem Herunterfahren nicht funktioniert.' }
    if (-not (Confirm-Ui ($q + $(if ($on) { "`n`nHinweis: Die Pflege schaltet den Schnellstart bei jedem Lauf wieder ab, solange auf der Seite Optimieren ""Schnellstart deaktivieren"" angehakt ist (Standard)." } else { '' })))) { return }
    try { Set-ItemProperty 'HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Power' -Name HiberbootEnabled -Value $(if ($on) { 1 } else { 0 }) -Type DWord -ErrorAction Stop; if ($on -and -not $s.HibOn) { $null = Invoke-NdCmd 'powercfg.exe' '/hibernate on' 20 }; $ui.StatusText.Text = $(if ($on) { 'Schnellstart eingeschaltet.' } else { 'Schnellstart ausgeschaltet.' }) } catch { Show-UiError ('Nicht möglich: ' + $_.Exception.Message) }
    Start-EnSleepLoad
})
