$script:FdBusy = $false; $script:FdBusySince = $null; $script:FdData = $null; $script:FdRows = @(); $script:FdJobRows = @(); $script:FdSelPc = ''
$script:FdSuppress = $false; $script:FdRemInit = $false; $script:FdLogPc = ''; $script:FdLocalFp = ''; $script:FdConnected = $false; $script:FdLogPath = ''
function Get-FdDir { return [string]$ui.Fleet_Dir.Text.Trim() }
function Get-FdOnlineMin { $n = 25; try { $x = [int]$ui.Fleet_OnlineMin.Text.Trim(); if ($x -ge 5) { $n = $x } } catch { }; return $n }
function Get-FdSelectedPcs { @($ui.FdGrid.SelectedItems | ForEach-Object { [string]$_.Computer } | Where-Object { $_ }) }

function Update-FdDashboard {
    $dir = Get-FdDir
    if (-not $dir) { $ui.FdInfo.Text = 'Noch kein gemeinsamer Ordner eingestellt - weiter unten bei "Gemeinsamer Statusordner" eintragen und "Einstellungen speichern".'; $ui.FdLiveDot.Fill = New-UiBrush '#9AA5B8'; return }
    if ($script:FdBusy -and $script:FdBusySince -and ((Get-Date) - $script:FdBusySince).TotalSeconds -lt 120) { return }
    $script:FdBusy = $true; $script:FdBusySince = Get-Date
    $ui.FdLiveDot.Fill = New-UiBrush '#F59E0B'
    if (-not $script:FdConnected) { $script:FdConnected = $true; try { Connect-BackupTarget $dir } catch { } }
    try { $script:FdLocalFp = [string](Get-FdKeyFingerprint) } catch { $script:FdLocalFp = '' }
    Invoke-Bg -Script { param($d, $m) Read-FdFleetData $d $m } -Arguments @($dir, 40) -Functions @('Read-FdFleetData') -Done {
        param($r, $err)
        $script:FdBusy = $false
        if ($err) { $ui.FdLiveDot.Fill = New-UiBrush '#DC2626'; $ui.FdInfo.Text = 'Ordner nicht erreichbar: ' + $err.Message; return }
        $data = @($r | Where-Object { $_ -and $_.PSObject.Properties['Status'] })
        if (-not $data.Count) { $ui.FdLiveDot.Fill = New-UiBrush '#DC2626'; $ui.FdInfo.Text = 'Keine Daten gelesen.'; return }
        try { Show-FdData $data[0] } catch { $ui.FdInfo.Text = 'Anzeige-Fehler: ' + $_.Exception.Message }
    }
}
function Show-FdData($Data) {
    $script:FdData = $Data
    $now = Get-Date
    $script:FdRows = @(Get-FdRows $Data $now (Get-FdOnlineMin) $script:FdLocalFp)
    Add-FdHelpFields $script:FdRows $Data
    $script:FdRows = @($script:FdRows | Sort-Object @{ e = { if ($_.Help) { 0 } else { 1 } } }, StateSort, OnlineSort, Computer)
    $script:FdJobRows = @(@($Data.Jobs) | Where-Object { $_ } | ForEach-Object { ConvertTo-FdJobRow $_ $now })
    $script:FleetPcs = @(@($Data.Status) | Where-Object { $_ })
    $c = Get-FdTileCounts $script:FdRows
    $ui.FdTOnline.Text = [string]$c.Online; $ui.FdTOffline.Text = [string]$c.Offline; $ui.FdTRed.Text = [string]$c.Red; $ui.FdTYellow.Text = [string]$c.Yellow; $ui.FdTGreen.Text = [string]$c.Green; $ui.FdTJobs.Text = [string]$c.JobsOpen
    $ui.FdInfo.Text = '{0} PC(s) · {1} online · {2} offline{3}{4}{5} · Stand {6:HH:mm:ss}' -f $c.Total, $c.Online, $c.Offline, $(if ($c.NoBeat) { ' (davon {0} ohne Lebenszeichen)' -f $c.NoBeat } else { '' }), $(if ($c.Reboot) { ' · {0} warten auf Neustart' -f $c.Reboot } else { '' }), $(if ($c.JobsFailed) { ' · {0} Auftrag/Aufträge fehlgeschlagen (24 Std.)' -f $c.JobsFailed } else { '' }), $now
    $ui.FdLiveDot.Fill = New-UiBrush $(if ($c.Red) { '#DC2626' } elseif ($c.Yellow -or $c.JobsFailed) { '#F59E0B' } else { '#22C55E' })
    Set-FdGridRows
    Update-FdJobGrid
    Update-FdWarnings
    try { Update-FdHelpBox } catch { }
    if ($script:FdSelPc) { $row = @($script:FdRows | Where-Object { $_.Computer -eq $script:FdSelPc })[0]; if ($row) { Show-FdDetail $row } }
    if (-not $script:FdRemInit) { $script:FdRemInit = $true; try { Update-RemPage } catch { } }
}
function Add-FdHelpFields($Rows, $Data) {
    $h = @{}; if ($Data -and $Data.PSObject.Properties['Help'] -and $Data.Help) { $h = $Data.Help }
    foreach ($r in @($Rows)) {
        if (-not $r) { continue }
        $k = ([string]$r.Computer).ToUpper(); $x = $null; if ($h.ContainsKey($k)) { $x = $h[$k] }
        $txt = ''; if ($x) { $txt = try { 'Hilfe! ' + ([datetime]$x.Time).ToString('dd.MM. HH:mm') } catch { 'Hilfe!' } }
        $r | Add-Member -NotePropertyName Help -NotePropertyValue $x -Force
        $r | Add-Member -NotePropertyName HelpText -NotePropertyValue $txt -Force
        if ($x) { $r.Problem = $true; $r.Level = 'Error' }
    }
}
function Update-FdHelpBox {
    $open = @($script:FdRows | Where-Object { $_.Help })
    if (-not $open.Count) { $ui.FdHelpBox.Visibility = 'Collapsed'; return }
    $ui.FdHelpBox.Visibility = 'Visible'
    $ui.FdHelpText.Text = ('Hilferuf von {0} - Bericht ansehen, dann z.B. "Pflege" oder "Zustand melden" an diesen PC senden.' -f (($open | ForEach-Object { $m = [string]$_.Help.Message; if ($m.Length -gt 60) { $m = $m.Substring(0, 60) + ' ...' }; if ($m) { '{0} ("{1}")' -f $_.Computer, $m } else { $_.Computer } }) -join ', '))
}
function Get-FdHelpRow {
    $sel = @($ui.FdGrid.SelectedItems | Where-Object { $_.Help })
    if ($sel.Count) { return $sel[0] }
    return @($script:FdRows | Where-Object { $_.Help })[0]
}
function Show-FdHelp {
    $row = Get-FdHelpRow; if (-not $row) { Show-UiError 'Es gibt keinen offenen Hilferuf.'; return }
    $txt = Format-HelpReportText $row.Help
    $x = @"
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Title="PC-Tools - Hilferuf" Width="900" Height="680" WindowStartupLocation="CenterOwner" FontFamily="Segoe UI" FontSize="13" Background="#F4F6FA">
  <Grid Margin="18"><Grid.RowDefinitions><RowDefinition Height="*"/><RowDefinition Height="Auto"/></Grid.RowDefinitions>
    <Border Background="White" CornerRadius="10" BorderBrush="#E2E7F0" BorderThickness="1"><TextBox x:Name="HT" Uid="notr" IsReadOnly="True" BorderThickness="0" FontFamily="Consolas" FontSize="12" Padding="10" TextWrapping="Wrap" VerticalScrollBarVisibility="Auto"/></Border>
    <StackPanel Grid.Row="1" Orientation="Horizontal" HorizontalAlignment="Right" Margin="0,12,0,0">
      <Button x:Name="HSel" Content="PC in der Liste wählen" Padding="14,7" Margin="0,0,8,0"/><Button x:Name="HCopy" Content="Kopieren" Padding="14,7" Margin="0,0,8,0"/><Button x:Name="HClose" Content="Schließen" Padding="14,7" IsCancel="True"/>
    </StackPanel>
  </Grid>
</Window>
"@
    $dlg = [Windows.Markup.XamlReader]::Parse((Convert-ThemeXaml $x)); try { $dlg.Owner = $window } catch { }
    $dlg.FindName('HT').Text = $txt
    $pc = [string]$row.Computer
    $dlg.FindName('HCopy').Add_Click({ try { [Windows.Clipboard]::SetText($txt) } catch { } }.GetNewClosure())
    $dlg.FindName('HClose').Add_Click({ $dlg.Close() }.GetNewClosure())
    $script:FdHelpDlg = $dlg; $script:FdHelpPc = $pc
    $dlg.FindName('HSel').Add_Click({
        $script:FdSuppress = $true
        try { $ui.FdGrid.UnselectAll(); foreach ($it in @($ui.FdGrid.Items)) { if ([string]$it.Computer -eq $script:FdHelpPc) { [void]$ui.FdGrid.SelectedItems.Add($it); $ui.FdGrid.ScrollIntoView($it) } } } finally { $script:FdSuppress = $false }
        Update-FdSelInfo; $script:FdHelpDlg.Close()
    })
    [void]$dlg.ShowDialog()
}
function Close-FdHelp {
    $row = Get-FdHelpRow; if (-not $row) { Show-UiError 'Es gibt keinen offenen Hilferuf.'; return }
    if (-not (Confirm-Ui ('Hilferuf von {0} als erledigt markieren?' -f $row.Computer))) { return }
    try {
        $f = [string]$row.Help.File; $o = Get-Content -LiteralPath $f -Raw -Encoding UTF8 | ConvertFrom-Json
        $o | Add-Member -NotePropertyName Status -NotePropertyValue 'erledigt' -Force
        $o | Add-Member -NotePropertyName Done -NotePropertyValue ((Get-Date).ToString('o')) -Force
        $o | Add-Member -NotePropertyName DoneBy -NotePropertyValue $env:COMPUTERNAME -Force
        $o | ConvertTo-Json -Depth 5 | Set-Content -LiteralPath $f -Encoding UTF8
        $ui.StatusText.Text = ('Hilferuf von {0} ist erledigt.' -f $row.Computer)
        Update-FdDashboard
    } catch { Show-UiError ('Konnte den Hilferuf nicht ändern: ' + $_.Exception.Message) }
}
function Set-FdGridRows {
    $g = $ui.FdGrid
    $txt = $ui.FdFilter.Text.Trim(); $mode = [int]$ui.FdShow.SelectedIndex
    $rows = @($script:FdRows | Where-Object { Test-FdRowShow $_ $txt $mode })
    $sel = @(Get-FdSelectedPcs)
    $sorts = @(); if ($g.ItemsSource) { $v = [Windows.Data.CollectionViewSource]::GetDefaultView($g.ItemsSource); if ($v) { $sorts = @($v.SortDescriptions | ForEach-Object { $_ }) } }
    $dirs = @{}; foreach ($col in $g.Columns) { if ($null -ne $col.SortDirection) { $dirs[[string]$col.SortMemberPath] = $col.SortDirection } }
    $script:FdSuppress = $true
    try {
        Set-GridItems $g $rows
        $v2 = [Windows.Data.CollectionViewSource]::GetDefaultView($g.ItemsSource)
        if ($v2) { foreach ($sd in $sorts) { $v2.SortDescriptions.Add($sd) } }
        foreach ($col in $g.Columns) { if ($dirs.ContainsKey([string]$col.SortMemberPath)) { $col.SortDirection = $dirs[[string]$col.SortMemberPath] } }
        foreach ($it in @($g.Items)) { if ($sel -contains [string]$it.Computer) { [void]$g.SelectedItems.Add($it) } }
    } finally { $script:FdSuppress = $false }
    Update-FdSelInfo
}
function Update-FdSelInfo {
    $n = @(Get-FdSelectedPcs).Count
    $names = (@(Get-FdSelectedPcs) | Select-Object -First 12) -join ', '
    if ($n -gt 12) { $names = $names + ' ...' }
    $ui.FdSelInfo.Text = if ($n) { '{0} PC(s) gewählt: {1}' -f $n, $names } else { 'Mehrere PCs: Strg oder Umschalt gedrückt halten. Aufträge gehen an alle gewählten PCs.' }
}
function Update-FdWarnings {
    $w = [System.Collections.Generic.List[string]]::new()
    $rows = @($script:FdRows)
    $mis = @($rows | Where-Object { $_.KeyText -eq 'anderer Schlüssel' } | ForEach-Object { $_.Computer })
    if ($mis.Count) { $w.Add(('Anderer Auftragsschlüssel auf {0} - Aufträge von hier werden dort abgelehnt.' -f ($mis -join ', '))) }
    if ($script:FdLocalFp) { $no = @($rows | Where-Object { $_.KeyText -eq 'ohne' -and $_.Raw -and $_.Raw.PSObject.Properties['KeyFp'] } | ForEach-Object { $_.Computer }); if ($no.Count) { $w.Add(('Ohne Auftragsschlüssel (nehmen jeden Auftrag an): {0}.' -f ($no -join ', '))) } }
    $old = @($rows | Where-Object { $_.Raw -and -not $_.Raw.PSObject.Properties['Schema'] } | ForEach-Object { $_.Computer })
    if ($old.Count) { $w.Add(('Ältere PC-Tools-Version ohne erweiterte Meldung: {0} - dort "Selbstupdate" senden.' -f ($old -join ', '))) }
    $watchers = @($rows | Where-Object { $_.Raw -and $_.Raw.Watcher } | ForEach-Object { $_.Computer })
    if ($ui.Fleet_Watch.IsChecked -and -not $ui.Notify_Enabled.IsChecked) { $w.Add('Die Überwachung ist auf diesem PC an, die Benachrichtigungen aufs Handy aber aus - es würde nichts gemeldet.') }
    $ui.FdWatchInfo.Text = if ($watchers.Count) { 'Überwacht wird von: {0}.' -f ($watchers -join ', ') } else { 'Noch kein PC überwacht die anderen - unten auf einem PC, der meist läuft, einschalten.' }
    $ui.FdWarn.Text = ($w -join "`n")
    $ui.FdWarnBox.Visibility = $(if ($w.Count) { 'Visible' } else { 'Collapsed' })
}
function Update-FdJobGrid {
    $mode = [int]$ui.FdJobView.SelectedIndex
    $only = [bool]$ui.FdJobOnlySel.IsChecked
    $sel = @(Get-FdSelectedPcs)
    $rows = @($script:FdJobRows | Where-Object {
            ($mode -ne 0 -or $_.Open) -and ($mode -ne 2 -or $_.StateKey -eq 'failed') -and ($mode -ne 3 -or $_.StateKey -eq 'done') -and (-not $only -or $sel -contains [string]$_.Pc)
        } | Sort-Object @{ e = { $_.StateSort } }, @{ e = { $_.TimeSort }; Descending = $true })
    if ($mode -ne 0) { $rows = @($rows | Sort-Object @{ e = { $_.TimeSort }; Descending = $true }) }
    Set-GridItems $ui.FdJobGrid $rows
    $open = @($script:FdJobRows | Where-Object { $_.Open }).Count
    $ui.FdJobInfo.Text = '{0} Auftrag/Aufträge angezeigt · {1} offen · {2} insgesamt in den Auftragsordnern (je PC die letzten 40)' -f $rows.Count, $open, @($script:FdJobRows).Count
}
function Show-FdDetail($Row) {
    if (-not $Row) { return }
    $q = $Row.Raw
    $ui.FdDName.Text = $Row.Computer
    $ui.FdDDot.Fill = New-UiBrush $(if (-not $Row.Online) { '#9AA5B8' } elseif ($Row.State -eq 'Red') { '#EF4444' } elseif ($Row.State -eq 'Yellow') { '#F59E0B' } else { '#22C55E' })
    $ui.FdDBadge.Visibility = 'Visible'
    $ui.FdDBadgeText.Text = '{0} · {1}' -f $Row.OnlineText, $Row.SeenText
    $l = [System.Collections.Generic.List[string]]::new()
    $l.Add(('{0}  ·  Windows {1}  ·  PC-Tools {2}' -f $(if ($Row.Model) { $Row.Model } else { 'Modell unbekannt' }), $Row.Build, $Row.VerText))
    $l.Add(('Benutzer: {0}  ·  IP: {1}  ·  läuft seit {2}  ·  C: {3} frei' -f $(if ($Row.User) { $Row.User } else { '-' }), $(if ($Row.IP) { $Row.IP } else { '-' }), $Row.UptimeText, $Row.FreeText))
    $l.Add(('Neustart nötig: {0}  ·  offene Windows-Updates: {1}  ·  Fehler im Systemprotokoll (24 Std.): {2}' -f $(if ($Row.RebootPending) { 'ja' } else { 'nein' }), $Row.WuText, $Row.ErrText))
    $l.Add(('Datensicherung: {0}  ·  Komplettsicherung: {1}{2}' -f $Row.BackupText, $Row.FullText, $(if ($Row.FullBackup -and $Row.FullBackup.Last) { try { ' (zuletzt {0:dd.MM.yyyy})' -f (Get-FdTime $Row.FullBackup.Last) } catch { '' } } else { '' })))
    if ($q) {
        $l.Add(('Sicherheitswert: {0}  ·  letzte Pflege: {1}  ·  Fernaufträge: {2}  ·  Auftragsschutz: {3}{4}' -f $(if ([int]$q.SecScore -ge 0) { [int]$q.SecScore } else { '-' }), $(if ($q.LastRun) { $q.LastRun } else { 'nie' }), $(if ($q.Remote) { 'an' } else { 'aus' }), $Row.KeyText, $(if ($q.PSObject.Properties['StrictAcl'] -and $q.StrictAcl) { ', strenge Ordnerrechte' } else { '' })))
        if ($q.PSObject.Properties['RescueStick'] -and $q.RescueStick) { $l.Add(('Notfall-Stick: {0} (geprüft {1})' -f [string]$q.RescueStick.Text, $(try { (Get-FdTime $q.RescueStick.Time).ToString('dd.MM.yyyy HH:mm') } catch { '-' }))) }
    }
    $ui.FdDInfo.Text = ($l -join "`n")
    $ui.FdDItems.Text = if ($q -and @($q.Items).Count) { (@($q.Items) | ForEach-Object { '{0} {1} - {2}' -f $(if ($_.Level -eq 'Red') { '●' } else { '○' }), $_.Text, $_.Detail }) -join "`n" } elseif ($q) { '✓ Keine offenen Punkte auf der Ampel.' } else { 'Von diesem PC gibt es bisher nur ein Lebenszeichen, noch keinen Zustand.' }
    $ui.FdDItems.Foreground = New-UiBrush $(if ($Row.State -eq 'Red') { '#C81E1E' } elseif ($Row.State -eq 'Yellow') { '#B45309' } else { '#15803D' })
    $ak = if ($q -and $q.PSObject.Properties['Akte']) { $q.Akte } else { $null }
    $ui.FdDAkte.Text = if ($ak) { 'Geräte-Akte: Kaufdatum {0}  ·  Standort {1}  ·  Besitzer {2}  ·  Inventarnummer {3}  ·  letzte Reparatur {4}' -f $(if ($ak.Kaufdatum) { try { ([datetime]$ak.Kaufdatum).ToString('dd.MM.yyyy') } catch { $ak.Kaufdatum } } else { '-' }), $(if ($ak.Standort) { $ak.Standort } else { '-' }), $(if ($ak.Besitzer) { $ak.Besitzer } else { '-' }), $(if ($ak.Inventarnummer) { $ak.Inventarnummer } else { '-' }), $(if ($ak.LetzteReparatur) { $ak.LetzteReparatur } else { 'keine' }) } else { 'Geräte-Akte: keine Angaben (auf dem PC unter WERKZEUGE > Geräte-Akte pflegen).' }
    Show-FdChart @($Row.ScoreHist)
    if ($script:FdLogPc -ne $Row.Computer) { $script:FdLogPc = $Row.Computer; Update-FdLog $Row }
}
function Show-FdChart($Hist) {
    $cv = $ui.FdDChart; if (-not $cv) { return }
    $cv.Children.Clear()
    $w = [double]$cv.ActualWidth; if ($w -lt 60) { $w = 330 }; $h = 140.0
    $pts = @(Get-FdChartPoints $Hist $w $h 8)
    $y = { param($v) 8 + ($h - 16) * (100 - $v) / 100 }
    foreach ($band in @(@(100, 85, '#16A34A'), @(85, 65, '#D97706'), @(65, 0, '#DC2626'))) {
        $rc = New-Object Windows.Shapes.Rectangle; $rc.Width = $w; $rc.Height = [math]::Max([double]1, (& $y $band[1]) - (& $y $band[0])); $rc.Fill = New-UiBrush $band[2]; $rc.Opacity = 0.07
        [Windows.Controls.Canvas]::SetLeft($rc, 0); [Windows.Controls.Canvas]::SetTop($rc, (& $y $band[0])); [void]$cv.Children.Add($rc)
    }
    if (-not $pts.Count) { $t = New-Object Windows.Controls.TextBlock; $t.Text = 'Noch kein Score-Verlauf gemeldet (PC-Tools 10 nötig, ein Eintrag pro Tag).'; $t.TextWrapping = 'Wrap'; $t.Width = $w - 20; $t.FontSize = 11.5; $t.Foreground = New-UiBrush '#6B7890'; [Windows.Controls.Canvas]::SetLeft($t, 10); [Windows.Controls.Canvas]::SetTop($t, 50); [void]$cv.Children.Add($t); $ui.FdDScoreTxt.Text = ''; return }
    $last = $pts[$pts.Count - 1]
    $col = Get-ScColor ([double]$last.S)
    if ($pts.Count -gt 1) {
        $pl = New-Object Windows.Shapes.Polyline; $pl.Stroke = New-UiBrush $col; $pl.StrokeThickness = 2.4; $pl.StrokeLineJoin = 'Round'
        foreach ($pt in $pts) { [void]$pl.Points.Add((New-Object Windows.Point([double]$pt.X, [double]$pt.Y))) }
        [void]$cv.Children.Add($pl)
    }
    foreach ($pt in $pts) {
        $e = New-Object Windows.Shapes.Ellipse; $e.Width = 6; $e.Height = 6; $e.Fill = New-UiBrush (Get-ScColor ([double]$pt.S)); $e.ToolTip = '{0}: {1}' -f $pt.D, $pt.S
        [Windows.Controls.Canvas]::SetLeft($e, [double]$pt.X - 3); [Windows.Controls.Canvas]::SetTop($e, [double]$pt.Y - 3); [void]$cv.Children.Add($e)
    }
    $vals = @($pts | ForEach-Object { [int]$_.S })
    $ui.FdDScoreTxt.Text = 'Aktuell {0} (am {1}) · niedrigster {2} · höchster {3} · {4} Einträge' -f $last.S, $last.D, ($vals | Measure-Object -Minimum).Minimum, ($vals | Measure-Object -Maximum).Maximum, $pts.Count
}
function Update-FdLog($Row) {
    $dir = Get-FdDir
    $rel = if ($Row.Raw -and $Row.Raw.PSObject.Properties['LogFile'] -and [string]$Row.Raw.LogFile) { [string]$Row.Raw.LogFile } else { 'Protokolle\{0}.txt' -f $Row.Computer }
    $script:FdLogPath = Join-Path $dir $rel
    $ui.FdDLog.Text = 'Wird geladen ...'
    Invoke-Bg -Script { param($f) if (Test-Path -LiteralPath $f) { [pscustomobject]@{ Ok = $true; Text = (Get-Content -LiteralPath $f -Raw -Encoding UTF8); Time = (Get-Item -LiteralPath $f).LastWriteTime } } else { [pscustomobject]@{ Ok = $false; Text = ''; Time = $null } } } -Arguments @($script:FdLogPath) -Done {
        param($r, $err)
        if ($err) { $ui.FdDLog.Text = 'Protokoll nicht lesbar: ' + $err.Message; return }
        $o = @($r | Where-Object { $_ -and $_.PSObject.Properties['Ok'] })[0]
        if (-not $o -or -not $o.Ok) { $ui.FdDLog.Text = 'Dieser PC hat noch keinen Protokoll-Auszug hochgeladen (ab PC-Tools 10 mit "Protokoll-Auszug hochladen").'; return }
        $ui.FdDLog.Text = [string]$o.Text
        $ui.FdDLog.ScrollToEnd()
    }
}
function Send-FdJobsUi([string]$Action) {
    $dir = Get-FdDir
    if (-not $dir) { Show-UiError 'Bitte zuerst den gemeinsamen Ordner einstellen und speichern.'; return }
    $pcs = @(Get-FdSelectedPcs)
    if (-not $pcs.Count) { Show-UiError 'Bitte zuerst in der Liste einen oder mehrere PCs auswählen (Strg oder Umschalt für mehrere, oder "Alle wählen").'; return }
    if (-not $FleetActions.Contains($Action)) { return }
    $params = @{}
    $names = ($pcs -join ', ')
    if ($Action -in 'Neustart', 'Aus') {
        $what = if ($Action -eq 'Aus') { 'Herunterfahren' } else { 'Neustart' }
        $r = Show-InputDialog ('{0} auf {1} PC(s)' -f $what, $pcs.Count) ('Betrifft: {0}. Wer dort angemeldet ist, bekommt sofort eine Nachricht und hat die gewählte Zeit zum Speichern. Abbrechen ist jederzeit mit "Neustart abbrechen" möglich (bzw. am PC mit shutdown /a).' -f $names) @(
            @{ Key = 'Delay'; Label = 'Wartezeit'; Type = 'Combo'; Items = @('5 Minuten', '1 Minute', '2 Minuten', '10 Minuten', '15 Minuten', '30 Minuten', '60 Minuten', '120 Minuten') },
            @{ Key = 'Message'; Label = 'Nachricht an den angemeldeten Benutzer'; Type = 'Text'; Value = 'Bitte speichere deine Arbeit.' })
        if (-not $r) { return }
        $params.Delay = [int](([string]$r.Delay -split ' ')[0]); $params.Message = [string]$r.Message
        if (-not (Confirm-Ui ('{0} in {1} Minute(n) auf {2} PC(s) wirklich auslösen?{3}{4}' -f $what, $params.Delay, $pcs.Count, "`n`n", $names) 'Warning')) { return }
    } elseif ($Action -in 'Pflege', 'Updates', 'Aufraeumen', 'Sicherung', 'Virenscan', 'Selbstupdate', 'Komplettsicherung') {
        $extra = switch ($Action) { 'Updates' { "`n`nUpdates können einen Neustart planen (nur wenn das in den Einstellungen des PCs erlaubt ist)." } 'Komplettsicherung' { "`n`nDie Komplettsicherung dauert lange und nutzt die Einstellungen (Ziel) des jeweiligen PCs." } default { '' } }
        if (-not (Confirm-Ui ('"{0}" auf {1} PC(s) starten?{2}{3}{4}' -f $FleetActions[$Action], $pcs.Count, "`n`n", $names, $extra))) { return }
    }
    $off = @($script:FdRows | Where-Object { $pcs -contains $_.Computer -and -not $_.Online } | ForEach-Object { $_.Computer })
    $key = Get-FdKeySafe
    $batch = 'B{0:yyyyMMddHHmmss}' -f (Get-Date)
    $ok = 0; $errs = [System.Collections.Generic.List[string]]::new()
    $window.Cursor = 'Wait'
    try {
        foreach ($pc in $pcs) { try { $null = Send-FdJob $dir $pc $Action $params $key $batch; $ok++ } catch { $errs.Add(('{0}: {1}' -f $pc, $_.Exception.Message)) } }
    } finally { $window.Cursor = $null }
    $ui.StatusText.Text = '"{0}" an {1} PC(s) gesendet - wird innerhalb von 10 Minuten ausgeführt.{2}' -f (Get-FdShortAction $Action), $ok, $(if ($off.Count) { ' Offline (erst beim nächsten Start): ' + ($off -join ', ') } else { '' })
    if ($errs.Count) { Show-UiError ("Nicht gesendet:`n" + ($errs -join "`n")) }
    $ui.FdJobView.SelectedIndex = 0
    Update-FdDashboard
}
function Show-FdJobResult($Row) {
    if (-not $Row) { Show-UiError 'Bitte zuerst einen Auftrag in der Liste wählen.'; return }
    $sb = New-Object Text.StringBuilder
    $null = $sb.AppendLine(('{0} auf {1}' -f $Row.ActionText, $Row.Pc))
    $null = $sb.AppendLine(('Gesendet {0} von {1}{2}' -f $Row.TimeText, $Row.From, $(if ($Row.Signed) { ' (signiert)' } else { '' })))
    $null = $sb.AppendLine(('Zustand: {0}{1}' -f $Row.StateText, $(if ($Row.EndText) { ', fertig ' + $Row.EndText } else { '' })))
    if ($Row.Message) { $null = $sb.AppendLine(); $null = $sb.AppendLine($Row.Message) }
    if ($Row.HasData) {
        $null = $sb.AppendLine()
        foreach ($d in @($Row.Data)) { if ($d) { $null = $sb.AppendLine(('{0} {1}: {2}{3}' -f $(switch ([string]$d.Level) { 'Error' { '✗' } 'Warn' { '!' } default { '✓' } }), $d.Area, $d.State, $(if ($d.Detail) { ' - ' + $d.Detail } else { '' }))) } }
    }
    [Windows.MessageBox]::Show((T ($sb.ToString())), (T ('PC-Tools - Ergebnis des Auftrags')), 'OK', 'Information') | Out-Null
}

