$ui.FdBtnRdp.Add_Click({ $p = @(Get-FdSelectedPcs); if ($p.Count) { Start-Process mstsc.exe -ArgumentList ('/v:{0}' -f $p[0]) } else { Show-UiError 'Bitte zuerst einen PC wählen.' } })
