$ui.FdBtnRemove.Add_Click({
    $pcs = @(Get-FdSelectedPcs); $dir = Get-FdDir
    if (-not $pcs.Count -or -not $dir) { Show-UiError 'Bitte zuerst einen oder mehrere PCs wählen.'; return }
    if (-not (Confirm-Ui ('{0} aus der Übersicht entfernen?{1}{1}Gelöscht werden nur die Statusdatei und das Lebenszeichen im gemeinsamen Ordner (Aufträge und Protokoll bleiben). Meldet sich ein PC wieder, taucht er erneut auf - für ausgemusterte PCs dort vorher "Zustand ablegen" ausschalten.' -f ($pcs -join ', '), "`n"))) { return }
    foreach ($pc in $pcs) {
        if ($pc -notmatch '^[A-Za-z0-9_\-\.]{1,63}$') { continue }
        foreach ($f in @((Join-Path $dir ($pc + '.json')), (Join-Path (Join-Path $dir 'Heartbeat') ($pc + '.json')))) { Remove-Item -LiteralPath $f -Force -ErrorAction SilentlyContinue }
    }
    $script:FdSelPc = ''; $ui.FdGrid.UnselectAll(); Update-FdDashboard
})
