$ui.FdBtnJobRetract.Add_Click({
    $sel = @($ui.FdJobGrid.SelectedItems | Where-Object { $_.StateKey -eq 'queued' })
    if (-not $sel.Count) { Show-UiError 'Bitte einen oder mehrere wartende Aufträge wählen (laufende oder fertige lassen sich nicht zurückziehen).'; return }
    if (-not (Confirm-Ui ('{0} wartende(n) Auftrag/Aufträge zurückziehen? Sie werden aus dem Auftragsordner gelöscht.' -f $sel.Count))) { return }
    $n = 0
    foreach ($j in $sel) { try { $rf = Join-Path ([IO.Path]::GetDirectoryName($j.File)) ($j.Id + '.result.json'); if (-not (Test-Path -LiteralPath $rf)) { Remove-Item -LiteralPath $j.File -Force -ErrorAction Stop; $n++ } } catch { } }
    $ui.StatusText.Text = '{0} Auftrag/Aufträge zurückgezogen.' -f $n
    Update-FdDashboard
})
$ui.FdBtnJobRepeat.Add_Click({
    $sel = @($ui.FdJobGrid.SelectedItems)
    if (-not $sel.Count) { Show-UiError 'Bitte einen oder mehrere Aufträge wählen.'; return }
    if (-not (Confirm-Ui ('{0} Auftrag/Aufträge noch einmal senden?' -f $sel.Count))) { return }
    $dir = Get-FdDir; $key = Get-FdKeySafe; $n = 0; $batch = 'B{0:yyyyMMddHHmmss}' -f (Get-Date)
    foreach ($j in $sel) {
        $pp = @{}; if ($j.Params) { if ($null -ne $j.Params.Delay) { $pp.Delay = [int]$j.Params.Delay }; if ($null -ne $j.Params.Message) { $pp.Message = [string]$j.Params.Message } }
        if ($j.Action -in 'Neustart', 'Aus' -and -not $pp.ContainsKey('Delay')) { $pp.Delay = 5 }
        try { $null = Send-FdJob $dir $j.Pc $j.Action $pp $key $batch; $n++ } catch { $ui.StatusText.Text = $_.Exception.Message }
    }
    $ui.StatusText.Text = '{0} Auftrag/Aufträge erneut gesendet.' -f $n
    Update-FdDashboard
})
$ui.FdBtnDLog.Add_Click({
    if (-not $script:FdLogPath -or -not (Test-Path -LiteralPath $script:FdLogPath)) { Show-UiError 'Für diesen PC gibt es noch keinen Protokoll-Auszug.'; return }
    try { $tmp = Join-Path $env:TEMP ('PC-Tools Protokoll {0}.txt' -f $script:FdSelPc); Copy-Item -LiteralPath $script:FdLogPath -Destination $tmp -Force; Start-Process notepad.exe ('"{0}"' -f $tmp) } catch { Show-UiError $_.Exception.Message }
})
