    if (-not (Confirm-Ui 'Auftragsschlüssel auf diesem PC entfernen? Danach nimmt dieser PC wieder unsignierte Aufträge an, und seine eigenen Aufträge werden von PCs mit Schlüssel abgelehnt.' 'Warning')) { return }
    Remove-FdKey; Update-FdKeyInfo; Update-FdDashboard
})
$ui.FdBtnAcl.Add_Click({
    $dir = Get-FdDir; if (-not $dir) { Show-UiError 'Bitte zuerst den gemeinsamen Ordner einstellen.'; return }
    $p = Join-Path $dir 'Auftraege'; if (-not (Test-Path -LiteralPath $p)) { $p = $dir }
    $ui.FdAclInfo.Text = 'Prüfe ...'
    Invoke-Bg -Script { param($x) Get-FdShareAclRisk $x } -Arguments @($p) -Functions @('Get-FdShareAclRisk', 'Get-FdAclRisk') -Done {
        param($r, $err)
        if ($err) { $ui.FdAclInfo.Text = 'Rechte nicht lesbar: ' + $err.Message + ' - mit "Nur bei sicheren Ordnerrechten" würden Aufträge abgelehnt.'; return }
        $bad = @($r | Where-Object { $_ })
        $ui.FdAclInfo.Text = if ($bad.Count) { 'Zu offen: {0} dürfen in den Auftragsordner schreiben. Auf dem NAS die Freigabe so einstellen, dass nur dein Administrator-Konto (bzw. das NAS-Konto aus der Datensicherung) schreiben darf.' -f ($bad -join ', ') } else { 'In Ordnung: keine allgemeinen Gruppen (Jeder, Benutzer, Gäste ...) mit Schreibrecht gefunden.' }
        $ui.FdAclInfo.Foreground = New-UiBrush $(if ($bad.Count) { '#B45309' } else { '#15803D' })
    }
})
