# ---- Hilfen
function Get-AiTabTitle($Tab) { try { $t = [string](@($Tab.Header.Children)[-1].Text); if ($t) { return $t } } catch { }; return [string]$Tab.Header }
function Get-AiPageList { @($ui.Tabs.Items | Where-Object { [string]$_.Tag -ne 'H' -and [string]$_.Name -ne 'TabAssistant' } | ForEach-Object { Get-AiTabTitle $_ } | Where-Object { $_ }) }
function Get-AiTabByTitle([string]$Title) { foreach ($t in @($ui.Tabs.Items)) { if ([string]$t.Tag -ne 'H' -and (Get-AiTabTitle $t) -eq $Title) { return $t } }; return $null }
function Set-AiLastPage($Tab) { if (-not $Tab -or [string]$Tab.Tag -eq 'H' -or $Tab -eq $ui.TabAssistant) { return }; $script:AiLastTab = $Tab; $script:AiLastPage = Get-AiTabTitle $Tab }
function Copy-AiText([string]$Text) {
    try { [Windows.Clipboard]::SetText($Text) } catch { try { Set-Clipboard -Value $Text } catch { } }
    $ui.StatusText.Text = 'In die Zwischenablage kopiert.'
}
function New-AiActRes([string]$Text, [bool]$IsError = $false, [string]$Show = '') { [pscustomobject]@{ Text = $Text; IsError = $IsError; Show = $(if ($Show) { $Show } else { $Text }) } }
function Add-AiEntry([string]$Role, [string]$Text) { $script:AiEntries.Add([pscustomobject]@{ Role = $Role; Time = (Get-Date); Text = $Text }) }
function Get-AiSettings {
    $pid0 = 'ollama'; try { if ($ui.AiProvider.SelectedItem) { $pid0 = [string]$ui.AiProvider.SelectedItem.Tag } } catch { }
    $pv = Get-AiProvider $pid0
    $s = [pscustomobject]@{ Provider = $pv.Id; Prov = $pv; Kind = $pv.Kind; Url = $pv.Url; Model = ''; Limit = [long]0; MaxTokens = 1024; Page = $true; System = $false; Health = $false; Log = $false; Attach = $true; ErrorButton = $true; Scope = 'CurrentUser' }
    try { $s.Model = ([string]$ui.AiModelBox.Text).Trim() } catch { }
    if (-not $s.Model -and @($pv.Models).Count) { $s.Model = [string]@($pv.Models)[0] }
    if ($pv.Id -eq 'custom') { $s.Url = ([string]$ui.Assistant_CustomUrl.Text).Trim() }
    $n = [long]0; if ([long]::TryParse((([string]$ui.Assistant_MonthlyLimit.Text) -replace '[^\d]', ''), [ref]$n) -and $n -ge 0) { $s.Limit = $n }
    $m = 0; if ([int]::TryParse((([string]$ui.Assistant_MaxTokens.Text) -replace '[^\d]', ''), [ref]$m) -and $m -ge 64) { $s.MaxTokens = [int][math]::Min(16000, [double]$m) }
    $s.Page = [bool]$ui.Assistant_CtxPage.IsChecked; $s.System = [bool]$ui.Assistant_CtxSystem.IsChecked; $s.Health = [bool]$ui.Assistant_CtxHealth.IsChecked
    $s.Log = [bool]$ui.Assistant_CtxLog.IsChecked; $s.Attach = [bool]$ui.Assistant_CtxSelection.IsChecked; $s.ErrorButton = [bool]$ui.Assistant_ErrorButton.IsChecked
    try { if ([string]$ui.Assistant_KeyScope.SelectedItem.Content -like 'Alle*') { $s.Scope = 'LocalMachine' } } catch { }
    return $s
}
function Save-AiSettings {
    # nur den Abschnitt Assistant speichern - andere, evtl. halb bearbeitete Einstellungen bleiben unberührt
    try {
        $c = Read-PflegeConfig
        if (-not $c.PSObject.Properties['Assistant']) { return }
        $s = Get-AiSettings
        $map = ConvertFrom-AiModelMap ([string]$ui.Assistant_Model.Text); if ($s.Model) { $map[$s.Provider] = $s.Model }
        $ui.Assistant_Model.Text = ConvertTo-AiModelMap $map; $ui.Assistant_Provider.Text = $s.Provider
        foreach ($kv in @(@('Provider', $s.Provider), @('Model', [string]$ui.Assistant_Model.Text), @('CustomUrl', ([string]$ui.Assistant_CustomUrl.Text).Trim()))) { $c.Assistant | Add-Member -NotePropertyName $kv[0] -NotePropertyValue $kv[1] -Force }
        $c.Assistant.MonthlyLimit = [int][math]::Min([double]2147483647, [double]$s.Limit); $c.Assistant.MaxTokens = [int]$s.MaxTokens
        $c.Assistant.KeyScope = [string]$ui.Assistant_KeyScope.SelectedItem.Content
        $c.Assistant.CtxPage = $s.Page; $c.Assistant.CtxSystem = $s.System; $c.Assistant.CtxHealth = $s.Health; $c.Assistant.CtxLog = $s.Log
        $c.Assistant.CtxSelection = $s.Attach; $c.Assistant.ErrorButton = $s.ErrorButton
        foreach ($nm in 'AutoDiag', 'AutoCloud', 'Weekly', 'Speak', 'SaveChat', 'Memory') { $c.Assistant | Add-Member -NotePropertyName $nm -NotePropertyValue ([bool]$ui[('Assistant_' + $nm)].IsChecked) -Force }
        Save-PflegeConfig $c
    } catch { }
}

# ---- Kontext (nur, was angehakt ist)
function Get-AiSystemInfoText {
    $rows = [System.Collections.Generic.List[string]]::new()
    $adm = $false; try { $adm = Test-IsAdmin } catch { }
    $rows.Add(('PC-Tools {0}{1}{2}' -f $AppVersion, $(if ($Script:IsPortable) { ' (portabel vom Stick)' } else { '' }), $(if ($adm) { ', läuft mit Administratorrechten' } else { '' })))
    foreach ($pair in @(@('Windows', 'InfoOS'), @('Gerät', 'InfoModel'), @('Prozessor', 'InfoCpu'), @('Arbeitsspeicher', 'InfoRam'), @('Grafik', 'InfoGpu'), @('Laufwerk C:', 'InfoDisk'), @('Laufwerke', 'InfoVolumes'),
            @('Datenträger', 'InfoDisks'), @('Akku', 'InfoBattery'), @('Laufzeit seit Start', 'InfoUptime'), @('Neustart', 'InfoReboot'), @('Letzte Pflege', 'InfoLastRun'), @('Sicherheit', 'InfoSec'), @('Auslastung', 'InfoLoad'))) {
        $c = $ui[$pair[1]]; if (-not $c) { continue }
        $t = ''; try { $t = ([string]$c.Text).Trim() } catch { }
        if (-not $t -or $t -eq '...' -or $t -eq '-') { continue }
        $rows.Add(('{0}: {1}' -f $pair[0], ($t -replace '\s*\r?\n\s*', '; ')))
    }
    if ($rows.Count -lt 3) {
        try { $cv = Get-ItemProperty 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion' -ErrorAction Stop; $rows.Add(('Windows: {0} {1} (Build {2}.{3})' -f $cv.ProductName, $cv.DisplayVersion, $cv.CurrentBuild, $cv.UBR)) } catch { }
        try { $cs = Get-CimInstance Win32_ComputerSystem -OperationTimeoutSec 3 -ErrorAction Stop; $rows.Add(('Gerät: {0} {1}' -f $cs.Manufacturer, $cs.Model)); $rows.Add(('Arbeitsspeicher: {0:N0} GB' -f ($cs.TotalPhysicalMemory / 1GB))) } catch { }
        try { $dv = New-Object IO.DriveInfo $env:SystemDrive; $rows.Add(('Laufwerk C: {0:N1} GB frei von {1:N0} GB' -f ($dv.AvailableFreeSpace / 1GB), ($dv.TotalSize / 1GB))) } catch { }
    }
    return ($rows -join "`n")
}
function Get-AiHealthText {
    $sb = New-Object Text.StringBuilder
    if ($script:ScLast) {
        [void]$sb.AppendLine(('Zustands-Score: {0} von 100 ({1})' -f $script:ScLast.Score, $script:ScLast.Grade))
        foreach ($c in @($script:ScLast.Components)) { if ($c -and [double]$c.Max -gt 0) { [void]$sb.AppendLine(('  {0}: {1}/{2} - {3}' -f $c.Name, $c.Points, $c.Max, $c.Reason)) } }
    }
    $amp = @($script:AmpItems | Where-Object { $_ -and $_.Text })
    if ($amp.Count) {
        [void]$sb.AppendLine('Ampel-Punkte:')
        foreach ($a in $amp) { $lv = switch ([string]$a.Level) { 'Red' { 'ROT' } 'Yellow' { 'GELB' } default { [string]$a.Level } }; [void]$sb.AppendLine(('  [{0}] {1} - {2}' -f $lv, $a.Text, $a.Detail)) }
    } elseif ($script:ScLast) { [void]$sb.AppendLine('Ampel: keine offenen Punkte bekannt.') }
    $t = $sb.ToString().Trim()
    if (-not $t) { $t = 'Der Zustand wurde in dieser Sitzung noch nicht berechnet (Übersicht öffnen oder Aktion zustand_pruefen).' }
    return $t
}
function Get-AiContextParts($S) {
    $p = @{}
    if ($S.Page -and $script:AiLastPage) {
        $p.Seite = $script:AiLastPage
        if ($script:AiLastTab) { $p.Seitenhilfe = Get-AiPageHelp ([string]$script:AiLastTab.Name) $ManualChapters }
    }
    if ($S.System) { $p.System = Get-AiSystemInfoText }
    if ($S.Health) { $p.Zustand = Get-AiHealthText }
    if ($S.Log) { $p.Protokoll = Get-AiLogSummary (Join-Path $DataDir 'Logs') }
    return $p
}
function Update-AiCtxLabel {
    $s = Get-AiSettings; $parts = [System.Collections.Generic.List[string]]::new()
    if ($s.Page -and $script:AiLastPage) { $parts.Add(('Seite "{0}"' -f $script:AiLastPage)) }
    if ($s.System) { $parts.Add('Systemübersicht') }
    if ($s.Health) { $parts.Add('Zustand und Score') }
    if ($s.Log) { $parts.Add('letzter Lauf') }
    if ($script:AiAttach.Count) { $parts.Add(('{0} Anhang/Anhänge' -f $script:AiAttach.Count)) }
    $ui.AiCtxLabel.Text = $(if ($parts.Count) { ('Wird mit der Frage an {0} gesendet: ' -f $s.Prov.Where) + ($parts -join ', ') } else { 'Wird gesendet: nur deine Frage und der Gesprächsverlauf' })
}

# ---- Darstellung (Blasen, Markdown-light)
function New-AiTb([double]$Size = 13.5, [string]$Color = '#1F2A44') { $t = New-Object Windows.Controls.TextBlock; $t.TextWrapping = 'Wrap'; $t.FontSize = $Size; $t.Foreground = New-UiBrush $Color; return $t }
function Add-AiInlines($Tb, $Runs) {
    foreach ($r in $Runs) {
        $run = New-Object Windows.Documents.Run ([string]$r.Text)
        if ($r.Bold) { $run.FontWeight = 'SemiBold' }
        if ($r.Italic) { $run.FontStyle = 'Italic' }
        if ($r.Code) { $run.FontFamily = 'Consolas'; $run.Background = New-UiBrush '#EEF2F8' }
        [void]$Tb.Inlines.Add($run)
    }
}
function New-AiMiniButton([string]$Text, [string]$Glyph, [string]$Tag) {
    $b = New-Object Windows.Controls.Button
    try { $b.Style = $window.FindResource('Sec') } catch { }
    $b.Padding = '8,3'; $b.Margin = '0,0,6,0'; $b.FontSize = 11.5; $b.FontWeight = 'Normal'; $b.Tag = $Tag; $b.Focusable = $false
    $sp = New-Object Windows.Controls.StackPanel; $sp.Orientation = 'Horizontal'
    if ($Glyph) { $g = New-Object Windows.Controls.TextBlock; $g.FontFamily = 'Segoe MDL2 Assets'; $g.Text = [string][char][Convert]::ToInt32($Glyph, 16); $g.FontSize = 11; $g.Margin = '0,0,5,0'; $g.VerticalAlignment = 'Center'; [void]$sp.Children.Add($g) }
    $t = New-Object Windows.Controls.TextBlock; $t.Text = $Text; $t.VerticalAlignment = 'Center'; [void]$sp.Children.Add($t)
    $b.Content = $sp
    return $b
}
function New-AiCodeBlock([string]$Code, [string]$Lang) {
    $bd = New-Object Windows.Controls.Border; $bd.Background = New-UiBrush '#111827'; $bd.CornerRadius = '8'; $bd.Margin = '0,2,0,10'
    $g = New-Object Windows.Controls.Grid
    $r1 = New-Object Windows.Controls.RowDefinition; $r1.Height = 'Auto'; $r2 = New-Object Windows.Controls.RowDefinition
    [void]$g.RowDefinitions.Add($r1); [void]$g.RowDefinitions.Add($r2)
    $hd = New-Object Windows.Controls.DockPanel; $hd.Margin = '12,6,8,0'
    $cp = New-AiMiniButton 'Kopieren' 'E8C8' $Code; [Windows.Controls.DockPanel]::SetDock($cp, 'Right'); $cp.Margin = '0'
    $cp.Add_Click({ param($s, $e) Copy-AiText ([string]$s.Tag) })
    [void]$hd.Children.Add($cp)
    $lt = New-Object Windows.Controls.TextBlock; $lt.Text = $(if ($Lang) { $Lang } else { 'Code' }); $lt.Foreground = New-UiBrush '#9AA5B8'; $lt.FontSize = 11; $lt.VerticalAlignment = 'Center'
    [void]$hd.Children.Add($lt)
    [void]$g.Children.Add($hd)
    $tb = New-Object Windows.Controls.TextBox
    $tb.Text = $Code; $tb.IsReadOnly = $true; $tb.FontFamily = 'Consolas'; $tb.FontSize = 12.5; $tb.Foreground = New-UiBrush '#D1FAE5'
    $tb.Background = [Windows.Media.Brushes]::Transparent; $tb.BorderThickness = '0'; $tb.TextWrapping = 'NoWrap'; $tb.Padding = '10,4,10,10'
    $tb.HorizontalScrollBarVisibility = 'Auto'; $tb.VerticalScrollBarVisibility = 'Disabled'; $tb.CaretBrush = New-UiBrush '#D1FAE5'
    [Windows.Controls.Grid]::SetRow($tb, 1); [void]$g.Children.Add($tb)
    $bd.Child = $g
    return $bd
}
function New-AiMarkdownPanel([string]$Text) {
    $sp = New-Object Windows.Controls.StackPanel
    $blocks = ConvertFrom-AiMarkdown $Text
    $bullets = @([string][char]0x2022, [string][char]0x25E6, [string][char]0x25AA, [string][char]0x2013)
    foreach ($b in $blocks) {
        switch ([string]$b.Type) {
            'Para' { $tb = New-AiTb; $tb.Margin = '0,0,0,8'; $tb.LineHeight = 20; Add-AiInlines $tb $b.Runs; [void]$sp.Children.Add($tb) }
            'Heading' { $tb = New-AiTb $(if ($b.Level -le 2) { 16 } else { 14.5 }); $tb.FontWeight = 'SemiBold'; $tb.Margin = '0,4,0,6'; Add-AiInlines $tb $b.Runs; [void]$sp.Children.Add($tb) }
            'List' {
                $lp = New-Object Windows.Controls.StackPanel; $lp.Margin = '0,0,0,8'
                foreach ($it in $b.Items) {
                    $g = New-Object Windows.Controls.Grid; $g.Margin = ('{0},1,0,3' -f (4 + 18 * [int]$it.Level))
                    $c1 = New-Object Windows.Controls.ColumnDefinition; $c1.Width = 'Auto'; [void]$g.ColumnDefinitions.Add($c1); [void]$g.ColumnDefinitions.Add((New-Object Windows.Controls.ColumnDefinition))
                    $mk = New-AiTb 13.5 '#6B7890'; $mk.MinWidth = 18; $mk.Margin = '0,0,6,0'
                    $mk.Text = $(if ($it.Ordered) { [string]$it.Number + '.' } else { $bullets[[math]::Min(3, [int]$it.Level)] })
                    if ($it.Ordered) { $mk.FontWeight = 'SemiBold'; $mk.Foreground = New-UiBrush '#D97757' }
                    $tx = New-AiTb; $tx.LineHeight = 20; Add-AiInlines $tx $it.Runs; [Windows.Controls.Grid]::SetColumn($tx, 1)
                    [void]$g.Children.Add($mk); [void]$g.Children.Add($tx); [void]$lp.Children.Add($g)
                }
                [void]$sp.Children.Add($lp)
            }
            'Code' { [void]$sp.Children.Add((New-AiCodeBlock ([string]$b.Text) ([string]$b.Lang))) }
            'Quote' {
                $q = New-Object Windows.Controls.Border; $q.BorderThickness = '3,0,0,0'; $q.BorderBrush = New-UiBrush '#AFC4EA'; $q.Padding = '10,2,0,2'; $q.Margin = '0,0,0,8'
                $tb = New-AiTb 13.5 '#6B7890'; $tb.FontStyle = 'Italic'; Add-AiInlines $tb $b.Runs; $q.Child = $tb; [void]$sp.Children.Add($q)
            }
            'Rule' { $r = New-Object Windows.Controls.Border; $r.Height = 1; $r.Background = New-UiBrush '#E2E7F0'; $r.Margin = '0,4,0,10'; [void]$sp.Children.Add($r) }
        }
    }
    if ($sp.Children.Count) { $sp.Children[$sp.Children.Count - 1].Margin = '0' }
    return $sp
}
