function Update-AiSendState { $ui.AiBtnSend.IsEnabled = -not $script:AiBusy }

# ---- Anhänge
function Update-AiAttachUi {
    $ui.AiAttachPanel.Children.Clear()
    for ($i = 0; $i -lt $script:AiAttach.Count; $i++) {
        $a = $script:AiAttach[$i]
        $bd = New-Object Windows.Controls.Border; $bd.CornerRadius = '12'; $bd.Padding = '10,4,6,4'; $bd.Margin = '0,4,8,0'; $bd.Background = New-UiBrush '#E6F0FF'; $bd.BorderBrush = New-UiBrush '#AFC4EA'; $bd.BorderThickness = '1'
        $sp = New-Object Windows.Controls.StackPanel; $sp.Orientation = 'Horizontal'
        $g = New-AiTb 12 '#2D7FF9'; $g.FontFamily = 'Segoe MDL2 Assets'; $g.Text = [string][char]0xE723; $g.Margin = '0,1,6,0'; [void]$sp.Children.Add($g)
        $t = New-AiTb 12; $t.Text = ('{0} ({1:N0} Zeichen)' -f $a.Label, ([string]$a.Text).Length); $t.TextWrapping = 'NoWrap'; [void]$sp.Children.Add($t)
        $x = New-Object Windows.Controls.Button; $x.Content = [string][char]0xE711; $x.FontFamily = 'Segoe MDL2 Assets'; $x.FontSize = 9; $x.Padding = '5,3'; $x.Margin = '6,0,0,0'; $x.Tag = $i; $x.ToolTip = 'Anhang entfernen'; $x.Focusable = $false
        try { $x.Style = $window.FindResource('Sec') } catch { }
        $x.Add_Click({ param($s, $e) $ix = [int]$s.Tag; if ($ix -lt $script:AiAttach.Count) { $script:AiAttach.RemoveAt($ix) }; Update-AiAttachUi })
        [void]$sp.Children.Add($x)
        $bd.Child = $sp; [void]$ui.AiAttachPanel.Children.Add($bd)
    }
    Update-AiCtxLabel
}
function Add-AiAttachment([string]$Label, [string]$Text) {
    if (-not ([string]$Text).Trim()) { return }
    if (-not $ui.Assistant_CtxSelection.IsChecked) {
        if (-not (Confirm-Ui ("Anhänge sind in den Datenschutz-Einstellungen des Assistenten ausgeschaltet.`n`nDiesen Anhang (""{0}"") trotzdem mit der nächsten Frage an den KI-Anbieter senden?" -f $Label))) { return }
    }
    $script:AiAttach.Add([pscustomobject]@{ Label = $Label; Text = (Limit-AiText ([string]$Text) 8000) })
    Update-AiAttachUi
}

# ---- Werkzeug-Aufrufe (Bestätigungskarten)
function Get-AiUseDetail($Use) {
    $d = ''
    try {
        if ($Use.Input.seite) { $d = 'Seite: ' + [string]$Use.Input.seite }
        if ($Use.Input.profil) { $wp = @($WrProfiles | Where-Object { $_.Key -eq [string]$Use.Input.profil })[0]; $d = 'Profil: ' + $(if ($wp) { [string]$wp.Title } else { [string]$Use.Input.profil }) }
    } catch { }
    return $d
}
function Add-AiToolCard($Use) {
    $def = Get-AiActionDef $Use.Name
    $bd = New-Object Windows.Controls.Border; $bd.Background = New-UiBrush 'White'; $bd.BorderBrush = New-UiBrush '#EA580C'; $bd.BorderThickness = '1.5'; $bd.CornerRadius = '12'; $bd.Padding = '16,12'; $bd.Margin = '40,4,60,10'; $bd.HorizontalAlignment = 'Left'; $bd.MaxWidth = 640
    $sp = New-Object Windows.Controls.StackPanel
    $hd = New-Object Windows.Controls.StackPanel; $hd.Orientation = 'Horizontal'
    $gl = New-AiTb 13 '#EA580C'; $gl.FontFamily = 'Segoe MDL2 Assets'; $gl.Text = $(switch ($def.Kind) { 'Read' { [string][char]0xE8A1 } 'Open' { [string][char]0xE8A7 } default { [string][char]0xE945 } }); $gl.Margin = '0,1,8,0'; [void]$hd.Children.Add($gl)
    $ht = New-AiTb 11 '#6B7890'; $ht.Text = 'DER ASSISTENT SCHLÄGT EINE AKTION VOR'; $ht.FontWeight = 'Bold'; [void]$hd.Children.Add($ht)
    [void]$sp.Children.Add($hd)
    $tt = New-AiTb 15; $tt.Text = [string]$def.Title; $tt.FontWeight = 'SemiBold'; $tt.Margin = '0,6,0,2'; [void]$sp.Children.Add($tt)
    $det = Get-AiUseDetail $Use
    if ($det) { $dt = New-AiTb 13 '#1F2A44'; $dt.Text = $det; $dt.FontWeight = 'SemiBold'; [void]$sp.Children.Add($dt) }
    $ds = New-AiTb 12.5 '#6B7890'; $ds.Text = [string]$def.Desc; $ds.Margin = '0,2,0,0'; [void]$sp.Children.Add($ds)
    $kn = New-AiTb 12 '#B45309'; $kn.Margin = '0,4,0,0'
    $kn.Text = $(switch ($def.Kind) { 'Read' { 'Dabei werden diese Daten an den gewählten KI-Anbieter gesendet.' } 'Open' { 'Öffnet nur eine Seite - es wird nichts verändert.' } default { 'Startet eine Aufgabe in PC-Tools (wie der passende Knopf auf der Seite).' } })
    [void]$sp.Children.Add($kn)
    $bp = New-Object Windows.Controls.WrapPanel; $bp.Margin = '0,10,0,0'
    $q = New-AiTb 13.5; $q.Text = 'Ausführen?'; $q.FontWeight = 'SemiBold'; $q.VerticalAlignment = 'Center'; $q.Margin = '0,0,12,0'; [void]$bp.Children.Add($q)
    $yes = New-Object Windows.Controls.Button; $yes.Content = 'Ja, ausführen'; $yes.Padding = '14,6'; $yes.Margin = '0,0,8,0'; $yes.Tag = [string]$Use.Id
    $no = New-Object Windows.Controls.Button; $no.Content = 'Nein'; $no.Padding = '14,6'; $no.Margin = '0'; $no.Tag = [string]$Use.Id
    try { $no.Style = $window.FindResource('Sec') } catch { }
    $yes.Add_Click({ param($s, $e) Resolve-AiTool ([string]$s.Tag) $true })
    $no.Add_Click({ param($s, $e) Resolve-AiTool ([string]$s.Tag) $false })
    [void]$bp.Children.Add($yes); [void]$bp.Children.Add($no); [void]$sp.Children.Add($bp)
    $res = New-AiTb 12.5 '#15803D'; $res.Margin = '0,8,0,0'; $res.Visibility = 'Collapsed'; [void]$sp.Children.Add($res)
    $bd.Child = $sp
    Add-AiChatElement $bd
    $script:AiPending.Cards[[string]$Use.Id] = @{ Yes = $yes; No = $no; Result = $res; Panel = $bp }
}
function Start-AiPending([object[]]$Uses) {
    $script:AiPending = @{ Uses = [System.Collections.Generic.List[object]]::new(); Results = [ordered]@{}; Cards = @{} }
    foreach ($u in $Uses) {
        $script:AiPending.Uses.Add($u)
        if (-not (Get-AiActionDef ([string]$u.Name))) {
            # nicht in der Whitelist -> niemals ausführen
            $script:AiPending.Results[[string]$u.Id] = New-AiToolResult ([string]$u.Id) ('Die Aktion "' + [string]$u.Name + '" gibt es in PC-Tools nicht. Nur die bereitgestellten Werkzeuge sind erlaubt.') $true
            continue
        }
        Add-AiToolCard $u
    }
    if ($script:AiPending.Results.Count -ge $script:AiPending.Uses.Count) { Submit-AiToolResults }
}
function Resolve-AiTool([string]$Id, [bool]$Yes) {
    $p = $script:AiPending
    if (-not $p -or $p.Results.Contains($Id) -or $script:AiBusy) { return }
    $use = @($p.Uses | Where-Object { [string]$_.Id -eq $Id })[0]; if (-not $use) { return }
    $card = $p.Cards[$Id]
    if ($card) { $card.Yes.IsEnabled = $false; $card.No.IsEnabled = $false; $card.Panel.Visibility = 'Collapsed' }
    $def = Get-AiActionDef ([string]$use.Name)
    if ($Yes) { $res = Invoke-AiAction $use }
    else { $res = New-AiActRes 'Der Nutzer hat die Aktion abgelehnt. Bitte nicht erneut vorschlagen, außer er fragt ausdrücklich danach.' $false 'Abgelehnt - nichts ausgeführt.' }
    $p.Results[$Id] = New-AiToolResult $Id ([string]$res.Text) ([bool]$res.IsError)
    if ($card) {
        $card.Result.Text = $(if ($Yes -and -not $res.IsError) { [string][char]0x2713 + ' ' + $res.Show } else { $res.Show })
        $card.Result.Foreground = New-UiBrush $(if ($res.IsError) { $(if ($Script:Dark) { '#F87171' } else { '#C81E1E' }) } elseif ($Yes) { $(if ($Script:Dark) { '#4ADE80' } else { '#15803D' }) } else { '#6B7890' })
        $card.Result.Visibility = 'Visible'
    }
    Add-AiEntry 'action' ('{0}{1}: {2}' -f $def.Title, $(if ($Yes) { '' } else { ' (abgelehnt)' }), $res.Show)
    if ($p.Results.Count -ge $p.Uses.Count) { Submit-AiToolResults }
}
function Close-AiPending {
    # offene Vorschläge als "übersprungen" beantworten (z.B. wenn eine neue Frage kommt)
    $p = $script:AiPending; $script:AiPending = $null
    $out = [System.Collections.Generic.List[object]]::new()
    if (-not $p) { return , $out }
    foreach ($u in $p.Uses) {
        $id = [string]$u.Id
        if (-not $p.Results.Contains($id)) {
            $p.Results[$id] = New-AiToolResult $id 'Übersprungen: Der Nutzer hat stattdessen eine neue Frage gestellt - nichts ausgeführt.' $false
            $c = $p.Cards[$id]; if ($c) { $c.Panel.Visibility = 'Collapsed'; $c.Result.Text = 'Übersprungen - nichts ausgeführt.'; $c.Result.Foreground = New-UiBrush '#6B7890'; $c.Result.Visibility = 'Visible' }
        }
        $out.Add($p.Results[$id])
    }
    return , $out
}
function Submit-AiToolResults {
    $p = $script:AiPending; $script:AiPending = $null
    if (-not $p) { return }
    $content = [System.Collections.Generic.List[object]]::new()
    foreach ($u in $p.Uses) { $content.Add($p.Results[[string]$u.Id]) }
    $script:AiHistory.Add([ordered]@{ role = 'user'; content = $content.ToArray() })
    $script:AiRounds++
    if ($script:AiRounds -gt $AiMaxToolRounds) { Add-AiNote 'Viele Aktionen hintereinander - der Assistent wartet jetzt auf deine nächste Frage.'; return }
    Invoke-AiRequest
}
function Start-AiRun([string[]]$Parts, [string]$Mode, [string]$Label) {
    if ($script:Job) { return (New-AiActRes ('Es läuft bereits eine Aufgabe ({0}) - bitte warten, bis sie fertig ist, und es dann erneut versuchen.' -f (@($script:Job.Parts) -join ', ')) $true 'Nicht gestartet: Es läuft bereits eine Aufgabe.') }
    switch ($Mode) {
        'Analyze' { $null = Start-Run -Parts $Parts -Analyze }
        'Check' { $null = Start-Run -Parts $Parts -CheckOnly }
        default { $null = Start-Run -Parts $Parts }
    }
    if (-not $script:Job) { return (New-AiActRes ($Label + ' konnte nicht gestartet werden.') $true) }
    $ui.Tabs.SelectedItem = $ui.TabAssistant
    return (New-AiActRes ('{0} wurde gestartet und läuft im Hintergrund (Fortschritt auf der Seite Protokoll und in der Statusleiste). Das Ergebnis liegt erst nach dem Ende vor - dann kann es mit protokoll_lesen gelesen werden.' -f $Label) $false ('{0} gestartet - Fortschritt unten in der Statusleiste und auf der Seite Protokoll.' -f $Label))
}
function Invoke-AiAction($Use) {
    # NUR Whitelist - Eingaben des Modells werden geprüft, nie als Befehl ausgeführt
    $in = $Use.Input
    try {
        switch ([string]$Use.Name) {
            'seite_oeffnen' {
                $title = [string]$in.seite; $tab = Get-AiTabByTitle $title
                if (-not $tab) { return (New-AiActRes ('Die Seite "{0}" gibt es nicht.' -f $title) $true) }
                $tab.Visibility = 'Visible'; $ui.Tabs.SelectedItem = $tab
                return (New-AiActRes ('Seite "{0}" wurde geöffnet.' -f $title))
            }
            'aufraeumen_analysieren' { return (Start-AiRun @('Clean') 'Analyze' 'Die Aufräum-Analyse') }
            'aufraeumen_starten' { return (Start-AiRun @('Clean') '' 'Das Aufräumen') }
            'optimieren_starten' { return (Start-AiRun @('Optimize') '' 'Die Optimierung') }
            'updates_suchen' { return (Start-AiRun @('Update') 'Check' 'Die Update-Suche') }
            'updates_installieren' { return (Start-AiRun @('Update') '' 'Die Update-Installation') }
            'netzwerk_diagnose' {
                $ui.TabNetDiag.Visibility = 'Visible'; $ui.Tabs.SelectedItem = $ui.TabNetDiag; Start-NdScan
                return (New-AiActRes 'Die Netzwerk-Diagnose wurde geöffnet und die Prüfung gestartet (10-30 Sekunden). Das Ergebnis sieht der Nutzer auf der Seite Netzwerk-Diagnose.' $false 'Netzwerk-Diagnose geöffnet, Prüfung läuft.')
            }
            'sicherheit_pruefen' {
                $ui.TabSecurity.Visibility = 'Visible'; $ui.Tabs.SelectedItem = $ui.TabSecurity
                if (Get-Command Update-Security -ErrorAction SilentlyContinue) { $null = Update-Security }
                return (New-AiActRes 'Die Seite Sicherheit wurde geöffnet und die Prüfung gestartet. Das Ergebnis sieht der Nutzer dort.' $false 'Seite Sicherheit geöffnet, Prüfung läuft.')
            }
            'zustand_pruefen' {
                if (Get-Command Update-ScScoreUi -ErrorAction SilentlyContinue) { $null = Update-ScScoreUi }
                if (Get-Command Update-Ampel -ErrorAction SilentlyContinue) { $null = Update-Ampel }
                return (New-AiActRes 'Zustands-Score und Ampel werden neu berechnet (10-30 Sekunden). Danach kann das Ergebnis mit zustand_lesen gelesen werden.' $false 'Neuberechnung läuft (10-30 Sekunden).')
            }
            'selbsttest' {
                $ui.Tabs.SelectedItem = $ui.TabSettings; Start-SelfTest
                return (New-AiActRes 'Der Selbsttest läuft (10-20 Sekunden); das Ergebnis steht auf der Seite Einstellungen unter Stabilität.' $false 'Selbsttest läuft - Ergebnis unter Einstellungen > Stabilität.')
            }
            'wiederherstellungspunkt_erstellen' {
                $ui.BtnRpCreate.RaiseEvent((New-Object Windows.RoutedEventArgs ([Windows.Controls.Primitives.ButtonBase]::ClickEvent)))
                return (New-AiActRes 'Der Wiederherstellungspunkt wird im Hintergrund erstellt; das Ergebnis erscheint in der Statusleiste.' $false 'Wird erstellt - Ergebnis unten in der Statusleiste.')
            }
            'windows_reparatur_vorbereiten' {
                $k = [string]$in.profil; $wp = @($WrProfiles | Where-Object { [string]$_.Key -eq $k })[0]
                if (-not $wp) { return (New-AiActRes ('Das Profil "{0}" gibt es nicht.' -f $k) $true) }
                $ui.TabWinRepair.Visibility = 'Visible'; $ui.Tabs.SelectedItem = $ui.TabWinRepair
                $pb = $ui[('BtnWrProf_' + $k)]
                if ($pb) { $pb.RaiseEvent((New-Object Windows.RoutedEventArgs ([Windows.Controls.Primitives.ButtonBase]::ClickEvent))) }
                return (New-AiActRes ('Seite Windows-Reparatur geöffnet und Profil "{0}" vorgewählt. Gestartet wird erst, wenn der Nutzer dort auf "Auswahl jetzt reparieren" klickt.' -f $wp.Title) $false ('Profil "{0}" vorgewählt - zum Starten dort "Auswahl jetzt reparieren" klicken.' -f $wp.Title))
            }
            'protokoll_lesen' {
                $t = Get-AiLogSummary (Join-Path $DataDir 'Logs')
                if (-not $t) { return (New-AiActRes 'Es gibt noch kein Protokoll eines PC-Tools-Laufs.' $false 'Kein Protokoll vorhanden.') }
                return (New-AiActRes $t $false 'Zusammenfassung des letzten Laufs gesendet.')
            }
            'zustand_lesen' { return (New-AiActRes (Protect-AiText (Get-AiHealthText)) $false 'Zustand und Score gesendet.') }
            'ereignisse_lesen' {
                $d = 7; try { if ($in.tage) { $d = [int][math]::Max(1, [math]::Min(60, [int]$in.tage)) } } catch { }
                $t = (@(Invoke-UiWait { param($x) Get-AiEventText $x } @($d) @('Get-AiEventText') 120 'Lese das Windows-Ereignisprotokoll ...') | ForEach-Object { [string]$_ }) -join "`n"
                return (New-AiActRes (Protect-AiText $t) $false ('Ereignisprotokoll der letzten {0} Tage gesendet.' -f $d))
            }
            'abstuerze_lesen' {
                $t = (@(Invoke-UiWait { Get-AiCrashText 90 } @() @('Get-AiCrashText') 120 'Suche Bluescreens und Abstürze ...') | ForEach-Object { [string]$_ }) -join "`n"
                return (New-AiActRes (Protect-AiText $t) $false 'Bluescreens und Abstürze gesendet.')
            }
            'autostart_lesen' {
                $en = @(Get-AutostartEntries $true | ForEach-Object { $_ } | Where-Object { $_ -and $_.Name })
                $t = ('{0} Autostart-Einträge (Name | Quelle | Zustand | Einstufung):' -f $en.Count) + "`n" + ((@($en | ForEach-Object { '- {0} | {1} | {2} | {3}' -f $_.Name, $_.Source, $(if ($_.Enabled) { 'aktiv' } else { 'aus' }), $(if ($_.PSObject.Properties['Category']) { $_.Category } else { '' }) })) -join "`n")
                return (New-AiActRes (Protect-AiText $t) $false ('{0} Autostart-Einträge gesendet.' -f $en.Count))
            }
            'treiber_lesen' {
                $t = (@(Invoke-UiWait { Get-AiDriverText } @() @('Get-AiDriverText') 120 'Lese Geräte und Treiber ...') | ForEach-Object { [string]$_ }) -join "`n"
                return (New-AiActRes (Protect-AiText $t) $false 'Geräte und Treiber gesendet.')
            }
            'updates_lesen' {
                $t = (@(Invoke-UiWait { Get-AiUpdateText } @() @('Get-AiUpdateText') 300 'Lese Windows-Updates (bis zu 2 Minuten) ...') | ForEach-Object { [string]$_ }) -join "`n"
                return (New-AiActRes (Protect-AiText $t) $false 'Update-Verlauf und ausstehende Updates gesendet.')
            }
            'netzwerkbericht_lesen' {
                if (-not $script:Ndoc) { return (New-AiActRes 'In dieser Sitzung wurde das Netzwerk noch nicht erfasst. Der Nutzer kann auf der Seite "Netzwerk dokumentieren" auf "Netzwerk jetzt erfassen" klicken (dauert 1-3 Minuten).' $false 'Noch keine Netzwerk-Erfassung vorhanden.') }
                return (New-AiActRes (Get-AiNetReportText $script:Ndoc) $false 'Netzwerk-Bericht gesendet.')
            }
        }
        return (New-AiActRes ('Unbekannte Aktion "{0}" - nicht ausgeführt.' -f $Use.Name) $true)
    } catch { return (New-AiActRes ('Fehler bei der Ausführung: ' + $_.Exception.Message) $true) }
}


# ================================================================ KI 13.9: Automatik, Diagnose, Sprache, Gedächtnis
# ---- Einmal-Anfrage ohne Werkzeuge (Auto-Diagnose, Wochenbericht, Gedächtnis). Rückruf: & $Done $Text $Fehler
$script:AiShots = @{}
function Test-AiAutoAllowed {
    $s = Get-AiSettings
    if (Get-AiNotReadyText $s) { return $false }
    if ($s.Prov.Local) { return [bool](Get-OllamaExe) }
    return [bool]$ui.Assistant_AutoCloud.IsChecked
}
function Invoke-AiOneShot([string]$Task, [string]$Data, [scriptblock]$Done, [int]$MaxTokens = 900) {
    $s = Get-AiSettings
    $why = Get-AiNotReadyText $s
    if ($why) { & $Done '' $why; return }
    $sys = "Du bist der KI-Assistent in PC-Tools (Version $AppVersion), einem Windows-Werkzeugkasten. Antworte immer auf " + $(if ($script:UiLang -ne 'de-DE') { $LangAiName[$script:UiLang] + ' (Sprache der Oberfläche)' } else { 'Deutsch' }) + ", freundlich und so einfach, dass es Menschen ohne IT-Wissen verstehen. Erfinde nichts: Wenn die Daten etwas nicht hergeben, sag das. Nenne konkrete nächste Schritte, möglichst mit den passenden Seiten von PC-Tools."
    $msg = @([ordered]@{ role = 'user'; content = ($Task + "`n`n--- Daten ---`n" + (Limit-AiText (Protect-AiText $Data) 14000)) })
    $json = if ($s.Kind -eq 'anthropic') { New-AiRequestBody $s.Model $sys $msg @() $MaxTokens } else { New-AiOpenAiBody $s.Model $sys $msg @() $MaxTokens ([string]$s.Prov.TokField) }
    $id = [guid]::NewGuid().ToString('N'); $script:AiShots[$id] = $Done
    $toSec = $(if ($s.Prov.Local -or $s.Provider -eq 'custom') { 600 } else { 150 })
    Invoke-Bg -Script { param($k, $b, $url, $ver, $kind, $to, $i) [pscustomobject]@{ ShotId = $i; Res = (Invoke-AiMessages $k $b $url $ver $kind $to) } } -Arguments @([string](Get-AiKey $DataDir $s.Provider), [Text.Encoding]::UTF8.GetBytes($json), $s.Url, $AiApiVersion, $s.Kind, $toSec, $id) -Functions @('Invoke-AiMessages', 'Invoke-AiHttp') -Done {
        param($r, $err)
        $x = $null; foreach ($y in @($r)) { if ($y -and $y.PSObject.Properties['ShotId']) { $x = $y } }
        if (-not $x) { foreach ($k in @($script:AiShots.Keys)) { $cb = $script:AiShots[$k]; $script:AiShots.Remove($k); try { & $cb '' $(if ($err) { $err.Message } else { 'keine Antwort' }) } catch { } }; return }
        $cb = $script:AiShots[[string]$x.ShotId]; $script:AiShots.Remove([string]$x.ShotId)
        if (-not $cb) { return }
        $res = $x.Res; $nm = [string](Get-AiSettings).Prov.Name
        if (-not $res -or [int]$res.Status -ne 200) { try { & $cb '' (Get-AiErrorText ([int]$res.Status) ([string]$res.Body) ([string]$res.Error) $nm) } catch { }; return }
        try {
            $p = ConvertFrom-AiResponse ([string]$res.Body)
            try { $null = Add-AiUsage (Get-AiUsageFile $DataDir) $p.InTokens $p.OutTokens } catch { }
            & $cb ([string]$p.Text) ''
        } catch { try { & $cb '' $_.Exception.Message } catch { } }
    }
}
# Ergebnis einer Automatik im Chat zeigen und als Gesprächsteil merken (damit Rückfragen funktionieren)
function Add-AiAutoResult([string]$Title, [string]$Question, [string]$Text) {
    if (-not $Text) { return }
    try {
        Add-AiNote $Title
        Add-AiAssistantBubble $Text
        if (-not $script:AiBusy -and -not $script:AiPending) {
            $last = $null; if ($script:AiHistory.Count) { $last = $script:AiHistory[$script:AiHistory.Count - 1] }
            if (-not $last -or [string]$last.role -eq 'assistant') {
                $script:AiHistory.Add([ordered]@{ role = 'user'; content = $Question })
                $script:AiHistory.Add([ordered]@{ role = 'assistant'; content = @([ordered]@{ type = 'text'; text = $Text }) })
            }
        }
        Save-AiChat
        if ($ui.Assistant_Speak.IsChecked -and $ui.Tabs.SelectedItem -eq $ui.TabAssistant) { Invoke-AiSpeak $Text }
    } catch { }
}

# ---- Automatische Diagnose nach jedem Pflegelauf
function Start-AiAutoDiag([string[]]$Parts) {
    if (-not $ui.Assistant_AutoDiag.IsChecked) { return }
    if (@($Parts) -contains 'NiniteInstall') { return }
    if (-not (Test-AiAutoAllowed)) { return }
    $log = Get-AiLogSummary (Join-Path $DataDir 'Logs')
    if (-not $log) { return }
    $ui.StatusText.Text = 'KI-Diagnose: Die KI wertet den Pflegelauf aus ...'
    Invoke-AiOneShot 'Hier ist die Zusammenfassung des gerade beendeten PC-Tools-Pflegelaufs. Erkläre in höchstens 5 kurzen Sätzen, was passiert ist und ob alles in Ordnung ist. Wenn es Warnungen oder Fehler gibt: Was bedeuten sie, und was sollte der Nutzer jetzt tun (wichtigstes zuerst)? Wenn alles gut ist, sag das einfach.' $log {
        param($t, $e)
        if ($e) { $ui.StatusText.Text = 'KI-Diagnose nicht möglich: ' + $e; return }
        try { $f = Join-Path (Join-Path $DataDir 'Assistant') 'diagnose-letzter-lauf.txt'; New-Item (Split-Path -Parent $f) -ItemType Directory -Force | Out-Null; [IO.File]::WriteAllText($f, ('{0:dd.MM.yyyy HH:mm}' -f (Get-Date)) + "`r`n" + $t, (New-Object Text.UTF8Encoding $true)) } catch { }
        Add-AiAutoResult ('Automatische Diagnose nach dem Pflegelauf ({0:HH:mm})' -f (Get-Date)) 'Erkläre mir kurz das Ergebnis des letzten Pflegelaufs.' $t
        $ui.StatusText.Text = 'KI-Diagnose fertig - im KI-Assistenten ansehen (Strg+Umschalt+A).'
    }
}

# ---- Wochen-Zusammenfassung
function Start-AiWeekly([switch]$Force) {
    if (-not $Force) {
        if (-not $ui.Assistant_Weekly.IsChecked -or -not (Test-AiAutoAllowed)) { return }
        $f = Join-Path (Join-Path $DataDir 'Assistant') 'woche-zuletzt.txt'
        try { if ((Test-Path -LiteralPath $f) -and (Get-Item -LiteralPath $f).LastWriteTime -gt (Get-Date).AddDays(-7)) { return } } catch { }
    } else {
        $why = Get-AiNotReadyText (Get-AiSettings); if ($why) { Add-AiNote $why 'Warn'; return }
        Add-AiNote 'Sammle die Daten der letzten 7 Tage (Läufe, Abstürze, Ereignisprotokoll, Updates) ...'
    }
    Invoke-Bg -Script { param($ld) Get-AiWeekData $ld } -Arguments @((Join-Path $DataDir 'Logs')) -Functions @('Get-AiWeekData') -Done {
        param($r, $err)
        $d = (@($r) | ForEach-Object { [string]$_ }) -join "`n"
        if (-not $d) { return }
        Invoke-AiOneShot 'Schreibe eine kurze Wochen-Zusammenfassung "Was ist diese Woche auf deinem PC passiert?" für einen Laien: höchstens 8 Stichpunkte (gut gelaufen / Auffälligkeiten / Abstürze / Updates) und zum Schluss 1-3 konkrete Empfehlungen, wichtigstes zuerst. Harmlose Routine-Fehler im Ereignisprotokoll nicht dramatisieren.' $d {
            param($t, $e)
            if ($e) { $ui.StatusText.Text = 'Wochen-Zusammenfassung nicht möglich: ' + $e; return }
            try { $f = Join-Path (Join-Path $DataDir 'Assistant') 'woche-zuletzt.txt'; New-Item (Split-Path -Parent $f) -ItemType Directory -Force | Out-Null; [IO.File]::WriteAllText($f, ('{0:dd.MM.yyyy HH:mm}' -f (Get-Date)) + "`r`n" + $t, (New-Object Text.UTF8Encoding $true)) } catch { }
            Add-AiAutoResult ('Deine Wochen-Zusammenfassung ({0:dd.MM.yyyy})' -f (Get-Date)) 'Was ist diese Woche auf meinem PC passiert?' $t
            $ui.StatusText.Text = 'Neue Wochen-Zusammenfassung im KI-Assistenten.'
        } 1100
    }
}
$script:AiWeekTimer = New-Object System.Windows.Threading.DispatcherTimer
$script:AiWeekTimer.Interval = [TimeSpan]::FromSeconds(90)
$script:AiWeekTimer.Add_Tick({ $script:AiWeekTimer.Stop(); try { if (-not $script:Job) { Start-AiWeekly } } catch { } })

# ---- Gespräch je PC speichern / laden, Gedächtnis
function Save-AiChat {
    try {
        if (-not $ui.Assistant_SaveChat.IsChecked) { return }
        $f = Get-AiChatFile $DataDir; New-Item (Split-Path -Parent $f) -ItemType Directory -Force | Out-Null
        $ents = @($script:AiEntries | Where-Object { $_.Role -in 'user', 'assistant', 'note' } | Select-Object -Last 80 | ForEach-Object { [ordered]@{ Role = $_.Role; Time = $_.Time.ToString('o'); Text = [string]$_.Text } })
        $obj = [ordered]@{ Saved = (Get-Date).ToString('o'); History = @($script:AiHistory.ToArray()); Entries = $ents }
        [IO.File]::WriteAllText($f, (ConvertTo-AiJson $obj), (New-Object Text.UTF8Encoding $false))
    } catch { }
}
function Restore-AiChat {
    if (-not $ui.Assistant_SaveChat.IsChecked) { return }
    $f = Get-AiChatFile $DataDir
    if (-not (Test-Path -LiteralPath $f)) { return }
    try {
        $j = [IO.File]::ReadAllText($f, [Text.Encoding]::UTF8) | ConvertFrom-Json
        if (-not $j -or -not @($j.Entries).Count) { return }
        $script:AiHistory = [System.Collections.Generic.List[object]]::new(); foreach ($m in @($j.History)) { if ($m) { $script:AiHistory.Add($m) } }
        $script:AiEntries.Clear()
        foreach ($e in @($j.Entries)) {
            switch ([string]$e.Role) { 'user' { Add-AiUserBubble ([string]$e.Text) @() } 'assistant' { Add-AiAssistantBubble ([string]$e.Text) } default { Add-AiNote ([string]$e.Text) } }
        }
        $dt = ''; try { $dt = ([datetime]$j.Saved).ToString('dd.MM.yyyy HH:mm') } catch { }
        Add-AiNote ('Gespräch vom {0} fortgesetzt. "Neues Gespräch" beginnt von vorn.' -f $dt)
    } catch { }
}
function Save-AiMemoryFromChat {
    # beim Beginn eines neuen Gesprächs: wichtigste Probleme/Lösungen kurz merken
    if (-not $ui.Assistant_Memory.IsChecked) { return }
    $txt = (@($script:AiEntries | Where-Object { $_.Role -in 'user', 'assistant' } | Select-Object -Last 20 | ForEach-Object { '{0}: {1}' -f $(if ($_.Role -eq 'user') { 'Nutzer' } else { 'Assistent' }), (Limit-AiText ([string]$_.Text) 1200) }) -join "`n")
    if ($txt.Length -lt 40 -or (Get-AiNotReadyText (Get-AiSettings))) { return }
    if (-not (Get-AiSettings).Prov.Local -and -not $ui.Assistant_AutoCloud.IsChecked) {
        # Online-KI: nur einfache Notiz ohne zusätzliche Anfrage (die Fragen selbst)
        $qs = @($script:AiEntries | Where-Object { $_.Role -eq 'user' } | Select-Object -Last 3 | ForEach-Object { 'Frage: ' + (Limit-AiText ([string]$_.Text) 160) })
        if ($qs.Count) { try { Add-AiMemory $DataDir ($qs -join "`n") } catch { } }
        return
    }
    Invoke-AiOneShot 'Fasse dieses Gespräch für das Gedächtnis des Assistenten zusammen: höchstens 3 Zeilen im Format "Problem -> Ergebnis/Lösung". Nur Dinge, die für spätere Fragen zu diesem PC nützlich sind. Keine Kennwörter, keine persönlichen Daten. Wenn nichts Wichtiges dabei war, antworte nur mit "-".' $txt {
        param($t, $e)
        if ($e -or -not $t -or $t.Trim() -eq '-') { return }
        try { Add-AiMemory $DataDir $t } catch { }
    } 300
}

# ---- Sprache: Diktat (Windows-Spracheingabe Win+H) und Vorlesen
function Start-AiDictation {
    try {
        if (-not ('PcTools.Kb' -as [type])) { Add-Type -Namespace PcTools -Name Kb -MemberDefinition '[DllImport("user32.dll")] public static extern void keybd_event(byte bVk, byte bScan, uint dwFlags, UIntPtr dwExtraInfo);' }
        [void]$ui.AiInput.Focus(); $ui.AiInput.CaretIndex = $ui.AiInput.Text.Length
        Invoke-UiDoEvents; Start-Sleep -Milliseconds 150
        [PcTools.Kb]::keybd_event(0x5B, 0, 0, [UIntPtr]::Zero); [PcTools.Kb]::keybd_event(0x48, 0, 0, [UIntPtr]::Zero)
        [PcTools.Kb]::keybd_event(0x48, 0, 2, [UIntPtr]::Zero); [PcTools.Kb]::keybd_event(0x5B, 0, 2, [UIntPtr]::Zero)
        $ui.StatusText.Text = 'Spracheingabe von Windows geöffnet - einfach sprechen, der Text erscheint im Eingabefeld. Danach Enter drücken.'
    } catch { $ui.StatusText.Text = 'Spracheingabe nicht möglich: ' + $_.Exception.Message + ' (Alternativ Windows-Taste + H drücken.)' }
}
$script:AiSynth = $null
function Invoke-AiSpeak([string]$Text) {
    try {
        if (-not $script:AiSynth) {
            Add-Type -AssemblyName System.Speech
            $script:AiSynth = New-Object System.Speech.Synthesis.SpeechSynthesizer
            $v = @($script:AiSynth.GetInstalledVoices() | Where-Object { $_.Enabled -and $_.VoiceInfo.Culture.TwoLetterISOLanguageName -eq 'de' } | Select-Object -First 1)
            if ($v.Count) { $script:AiSynth.SelectVoice($v[0].VoiceInfo.Name) }
            $script:AiSynth.Rate = 0
        }
        if ([string]$script:AiSynth.State -eq 'Speaking') { $script:AiSynth.SpeakAsyncCancelAll(); return }
        $t = ConvertTo-AiSpeechText $Text
        if ($t) { [void]$script:AiSynth.SpeakAsync($t) }
    } catch { $ui.StatusText.Text = 'Vorlesen nicht möglich: ' + $_.Exception.Message }
}
function Stop-AiSpeak { try { if ($script:AiSynth) { $script:AiSynth.SpeakAsyncCancelAll() } } catch { } }

# ---- Kostenlose KI ohne Zutun: Ollama einrichten (auch automatisch beim ersten Senden)
$script:AiQueued = ''
function Start-AiOllamaSetup([switch]$Auto) {
    if ($script:AiOllamaBusy) { return }
    $m = ([string]$ui.AiModelBox.Text).Trim(); if (-not $m) { $m = Get-OllamaSuggestedModel; $ui.AiModelBox.Text = $m }
    $inst = [bool](Get-OllamaExe)
    $size = $(if ($m -match '8b') { 'ca. 5 GB' } elseif ($m -match '20b') { 'ca. 13 GB' } else { 'ca. 2,5 GB' })
    if (-not $inst -and -not (Confirm-Ui ("Die kostenlose KI wird jetzt einmalig eingerichtet:`n`n- Ollama (Open Source, ca. 1 GB) wird installiert`n- das KI-Modell {0} ({1}) wird geladen`n`nDanach antwortet der Assistent ohne Konto und ohne Kosten, und deine Fragen verlassen diesen PC nicht. Dauer je nach Internet 5-30 Minuten, PC-Tools bleibt bedienbar.`n`nJetzt einrichten?" -f $m, $size))) { $script:AiQueued = ''; return }
    Save-AiSettings
    $script:AiOllamaBusy = $true
    $ui.AiBtnOllamaSetup.IsEnabled = $false; $ui.AiOllamaProg.Visibility = 'Visible'; try { $ui.AiBtnQuickSetup.IsEnabled = $false } catch { }
    $msg = $(if ($inst) { ('Ollama wird gestartet und das Modell {0} geladen ({1}) ...' -f $m, $size) } else { ('Kostenlose KI wird eingerichtet: Ollama installieren und Modell {0} laden ({1}) - das kann 5-30 Minuten dauern.' -f $m, $size) })
    $ui.AiOllamaState.Text = $msg; Add-AiNote ($msg + ' Du kannst PC-Tools so lange normal weiter benutzen.')
    $ui.StatusText.Text = 'KI-Assistent: ' + $msg
    Invoke-Bg -Script { param($mm) Install-OllamaModel $mm -InstallApp } -Arguments @($m) -Functions @('Install-OllamaModel') -Done {
        param($r, $err)
        $script:AiOllamaBusy = $false
        $ui.AiOllamaProg.Visibility = 'Collapsed'; $ui.AiBtnOllamaSetup.IsEnabled = $true; try { $ui.AiBtnQuickSetup.IsEnabled = $true } catch { }
        $lines = @($r | ForEach-Object { [string]$_ } | Where-Object { $_ })
        $ok = [bool](@($lines | Where-Object { $_ -match '^OK:|bereits geladen' }).Count)
        $ui.AiKeyTestInfo.Text = $(if ($err) { 'Fehler: ' + $err.Message } else { $lines -join "`n" })
        if ($ok) { Add-AiNote ([string][char]0x2713 + ' Die kostenlose KI ist eingerichtet und läuft auf diesem PC.') } else { Add-AiNote ('Einrichtung nicht abgeschlossen: ' + $(if ($err) { $err.Message } else { ($lines | Select-Object -Last 1) })) 'Warn' }
        Update-AiOllamaUi; Update-AiKeyUi; Update-AiWelcomeSetup
        if ($ok -and $script:AiQueued) { $q = $script:AiQueued; $script:AiQueued = ''; $ui.AiInput.Text = $q; Send-AiQuestion $q -FromInput }
    }
}
function Update-AiWelcomeSetup {
    try {
        $s = Get-AiSettings
        $show = $false
        if ($s.Prov.Local) { $show = -not [bool](Get-OllamaExe) } elseif (Get-AiNotReadyText $s) { $show = $true }
        $ui.AiSetupPanel.Visibility = $(if ($show) { 'Visible' } else { 'Collapsed' })
    } catch { }
}

# ---- Netzwerk-Bericht als Text für die KI
function Get-AiNetReportText($Res) {
    $o = [System.Collections.Generic.List[string]]::new()
    $rows = @($Res.Rows | Where-Object { $_ -and -not $_.Offline }); $find = @($Res.Find | Sort-Object SevNo)
    $sc = $null; try { $sc = Get-NdocScore $find } catch { }
    $o.Add(('Netzwerk {0}/{1}: {2} Geräte online{3}' -f $Res.Data.Net.Ip, $Res.Data.Net.Prefix, $rows.Count, $(if ($sc) { ', Bewertung {0}/100 ({1})' -f $sc.Score, $sc.Grade } else { '' })))
    $o.Add(''); $o.Add(('Befunde ({0}), wichtigste zuerst:' -f $find.Count))
    foreach ($f in @($find | Select-Object -First 40)) { $o.Add(('- [{0}] {1}: {2} - {3} Maßnahme: {4}' -f $f.Sev, $f.Device, $f.Title, $f.Detail, $f.Fix)) }
    $ex = @($Res.Exposure)
    if ($ex.Count) { $o.Add(''); $o.Add('Von außen erreichbar:'); foreach ($e in @($ex | Select-Object -First 15)) { $o.Add('- ' + ((@($e.PSObject.Properties | ForEach-Object { '{0}={1}' -f $_.Name, $_.Value })) -join '; ')) } }
    $o.Add(''); $o.Add('Geräte (Name | Typ | Hersteller | offene Dienste):')
    foreach ($r in @($rows | Select-Object -First 60)) { $o.Add(('- {0} | {1} | {2} | {3}' -f $r.Name, $(if ($r.PSObject.Properties['Type']) { $r.Type } else { '' }), $(if ($r.PSObject.Properties['Vendor']) { $r.Vendor } else { '' }), $(if ($r.PSObject.Properties['Ports']) { $r.Ports } else { '' }))) }
    return ($o -join "`n")
}
# ---- Bereit? (leer = ja, sonst Hinweistext)
function Get-AiNotReadyText($S) {
    $pv = $S.Prov
    if ($pv.Id -eq 'custom' -and -not $S.Url) { return 'Für "Andere KI / eigener Server" bitte rechts unter "Verbindung zur KI" die Adresse eintragen.' }
    if (-not $S.Model) { return 'Bitte rechts unter "Verbindung zur KI" ein Modell wählen oder eintragen.' }
    if ($pv.NeedKey -and -not (Get-AiKey $DataDir $pv.Id)) { return ('Für {0} ist ein API-Schlüssel nötig (rechts unter "Verbindung zur KI"). Komplett kostenlos und ohne Konto: oben "Ollama" wählen. Ohne alles: "In Claude.ai fragen" öffnet den Browser.' -f $pv.Name) }
    return ''
}
# ---- Anfrage an die KI (im Hintergrund)
function Invoke-AiRequest {
    $s = Get-AiSettings
    $key = Get-AiKey $DataDir $s.Provider
    $why = Get-AiNotReadyText $s
    if ($why) { Add-AiNote $why 'Warn'; Set-AiSidebar $true; return }
    $u = Get-AiUsage (Get-AiUsageFile $DataDir)
    if (Test-AiLimitReached $u $s.Limit) { Add-AiNote ('Das Monatslimit von {0:N0} Token ist erreicht - der Assistent pausiert bis zum nächsten Monat. Limit rechts unter "Verbrauch" ändern oder "In Claude.ai fragen" nutzen.' -f $s.Limit) 'Warn'; return }
    $trim = Limit-AiHistory $script:AiHistory.ToArray() $AiMaxHistoryChars
    if ($trim.Count -lt $script:AiHistory.Count) { $script:AiHistory = $trim; Add-AiNote 'Das Gespräch ist lang geworden - die ältesten Teile werden nicht mehr mitgeschickt.' }
    $pages = @(Get-AiPageList)
    $sys = Get-AiSystemPrompt $AppVersion (Get-AiFeatureText $pages $ManualChapters) (New-AiContextText (Get-AiContextParts $s))
    if ($ui.Assistant_Memory.IsChecked) { $mem = Get-AiMemoryText $DataDir; if ($mem) { $sys += "`n`nFrühere Probleme und Ergebnisse auf diesem PC (aus früheren Gesprächen, nur zur Orientierung):`n" + (Limit-AiText (Protect-AiText $mem) 3000) } }
    $tools = Get-AiToolDefs $pages $WrProfiles
    $json = if ($s.Kind -eq 'anthropic') { New-AiRequestBody $s.Model $sys $script:AiHistory.ToArray() $tools.ToArray() $s.MaxTokens } else { New-AiOpenAiBody $s.Model $sys $script:AiHistory.ToArray() $tools.ToArray() $s.MaxTokens ([string]$s.Prov.TokField) }
    $toSec = $(if ($s.Prov.Local -or $s.Provider -eq 'custom') { 600 } else { 150 })
    $bytes = [Text.Encoding]::UTF8.GetBytes($json)
    $script:AiBusy = $true; Update-AiSendState; Show-AiTyping
    $ui.StatusText.Text = ('KI-Assistent: {0} antwortet ...{1}' -f $s.Prov.Name, $(if ($s.Prov.Local) { ' (lokal - die erste Antwort kann etwas dauern)' } else { '' }))
    Invoke-Bg -Script { param($k, $b, $url, $ver, $kind, $to) Invoke-AiMessages $k $b $url $ver $kind $to } -Arguments @([string]$key, $bytes, $s.Url, $AiApiVersion, $s.Kind, $toSec) -Functions @('Invoke-AiMessages', 'Invoke-AiHttp') -Done {
        param($r, $err)
        Complete-AiRequest $r $err
    }
    $key = $null
}
function Add-AiFail([string]$Msg) {
    # letzte Nutzer-Nachricht für "Nochmal versuchen" zurücklegen
    if ($script:AiHistory.Count -and [string]$script:AiHistory[$script:AiHistory.Count - 1].role -eq 'user') {
        $script:AiFailedMsg = $script:AiHistory[$script:AiHistory.Count - 1]
        $script:AiHistory.RemoveAt($script:AiHistory.Count - 1)
    }
    Add-AiNote $Msg 'Error' -Retry:($null -ne $script:AiFailedMsg)
    $ui.StatusText.Text = 'KI-Assistent: ' + $Msg
}
function Invoke-AiRetry {
    if ($script:AiBusy -or -not $script:AiFailedMsg) { return }
    $script:AiHistory.Add($script:AiFailedMsg); $script:AiFailedMsg = $null
    Invoke-AiRequest
}
function Complete-AiRequest($R, $Err) {
    Hide-AiTyping
    $script:AiBusy = $false; Update-AiSendState
    $res = $null; foreach ($x in @($R)) { if ($x -and $x.PSObject.Properties['Status']) { $res = $x } }
    if ($Err -or -not $res) { Add-AiFail ('Interner Fehler: ' + $(if ($Err) { $Err.Message } else { 'keine Antwort erhalten' })); return }
    $cs = Get-AiSettings
    if ([int]$res.Status -ne 200) {
        if ($cs.Provider -eq 'ollama' -and [int]$res.Status -in 0, 404) {
            # automatisch reparieren: Ollama starten bzw. Modell laden, danach die Frage erneut senden
            $lastQ = ''; if ($script:AiHistory.Count -and [string]$script:AiHistory[$script:AiHistory.Count - 1].role -eq 'user') { $lm = $script:AiHistory[$script:AiHistory.Count - 1]; $lastQ = $(if ($lm.content -is [string]) { [string]$lm.content } else { '' }); $script:AiHistory.RemoveAt($script:AiHistory.Count - 1) }
            Add-AiNote $(if ([int]$res.Status -eq 404) { ('Das Modell {0} fehlt noch - PC-Tools lädt es jetzt automatisch.' -f $cs.Model) } else { 'Ollama lief nicht - PC-Tools richtet es jetzt automatisch ein.' })
            if ($lastQ) { $script:AiQueued = ($lastQ -split "`n")[0] }
            Start-AiOllamaSetup -Auto; return
        }
        Add-AiFail (Get-AiErrorText ([int]$res.Status) ([string]$res.Body) ([string]$res.Error) ([string]$cs.Prov.Name)); return
    }
    $p = $null
    try { $p = ConvertFrom-AiResponse ([string]$res.Body) } catch { Add-AiFail ('Die Antwort von {0} ist nicht lesbar: {1}' -f $cs.Prov.Name, $_.Exception.Message); return }
    try { $null = Add-AiUsage (Get-AiUsageFile $DataDir) $p.InTokens $p.OutTokens; Update-AiUsageUi } catch { }
    $script:AiHistory.Add([ordered]@{ role = 'assistant'; content = $p.Content })
    $note = ''
    if ($p.StopReason -eq 'max_tokens') { $note = 'Die Antwort wurde bei der eingestellten Höchstlänge abgeschnitten ("Max. Länge einer Antwort" rechts erhöhen oder "Bitte weiter" schreiben).' }
    if ($p.Text) { Add-AiAssistantBubble $p.Text $note } elseif ($note) { Add-AiNote $note 'Warn' }
    $ui.StatusText.Text = ('KI-Assistent: Antwort erhalten ({0:N0} + {1:N0} Token).' -f $p.InTokens, $p.OutTokens)
    $uses = @($p.ToolUses)
    if ($uses.Count) { Start-AiPending $uses } else { $script:AiRounds = 0 }
    Save-AiChat
    if ($p.Text -and $ui.Assistant_Speak.IsChecked) { Invoke-AiSpeak $p.Text }
}
function Send-AiQuestion([string]$Text, [switch]$FromInput) {
    $q = ([string]$Text).Trim()
    if (-not $q) { return }
    if ($script:AiBusy) { $ui.StatusText.Text = 'Der Assistent antwortet noch - bitte einen Moment.'; return }
    $why = Get-AiNotReadyText (Get-AiSettings)
    if ($why) { Add-AiNote $why 'Warn'; Set-AiSidebar $true; Update-AiWelcomeSetup; return }
    $s = Get-AiSettings
    if ($s.Prov.Local -and -not (Get-OllamaExe)) {
        # kostenlose KI noch nicht da: einmal einrichten, danach wird die Frage automatisch gesendet
        $script:AiQueued = $q
        if ($script:AiOllamaBusy) { Add-AiNote 'Die kostenlose KI wird gerade noch eingerichtet - deine Frage wird danach automatisch gesendet.'; return }
        Start-AiOllamaSetup -Auto; return
    }
    if (Test-AiLimitReached (Get-AiUsage (Get-AiUsageFile $DataDir)) $s.Limit) { Add-AiNote ('Das Monatslimit von {0:N0} Token ist erreicht - der Assistent pausiert bis zum nächsten Monat.' -f $s.Limit) 'Warn'; return }
    $att = @($script:AiAttach.ToArray())
    $userText = New-AiUserText $q $att
    $blocks = [System.Collections.Generic.List[object]]::new()
    if ($script:AiPending) { foreach ($tr in (Close-AiPending)) { $blocks.Add($tr) } }
    elseif ($script:AiFailedMsg -and -not ($script:AiFailedMsg.content -is [string])) { foreach ($b in @($script:AiFailedMsg.content)) { if ($b -and [string]$b.type -eq 'tool_result') { $blocks.Add($b) } } }
    $script:AiFailedMsg = $null
    $content = $userText
    if ($blocks.Count) { $blocks.Add([ordered]@{ type = 'text'; text = $userText }); $content = $blocks.ToArray() }
    $last = $null; if ($script:AiHistory.Count) { $last = $script:AiHistory[$script:AiHistory.Count - 1] }
    if ($last -and [string]$last.role -eq 'user') {
        # zwei Nutzer-Nachrichten hintereinander zu einer zusammenfassen
        $arr = [System.Collections.Generic.List[object]]::new()
        if ($last.content -is [string]) { $arr.Add([ordered]@{ type = 'text'; text = [string]$last.content }) } else { foreach ($b in @($last.content)) { $arr.Add($b) } }
        if ($content -is [string]) { $arr.Add([ordered]@{ type = 'text'; text = $content }) } else { foreach ($b in $content) { $arr.Add($b) } }
        $last.content = $arr.ToArray()
    } else { $script:AiHistory.Add([ordered]@{ role = 'user'; content = $content }) }
    Add-AiUserBubble $q @($att | ForEach-Object { [string]$_.Label })
    if ($FromInput) { $ui.AiInput.Clear() }
    $script:AiAttach.Clear(); Update-AiAttachUi
    $script:AiRounds = 0
    Invoke-AiRequest
}
function Invoke-AiSendInput { Send-AiQuestion $ui.AiInput.Text -FromInput }
function Invoke-AiClaudeAi {
    $q = ([string]$ui.AiInput.Text).Trim()
    if (-not $q) { Add-AiNote 'Bitte zuerst unten die Frage eingeben - dann "In Claude.ai fragen" klicken.' 'Warn'; [void]$ui.AiInput.Focus(); return }
    $s = Get-AiSettings
    $txt = New-AiClaudeAiText $q (New-AiContextText (Get-AiContextParts $s)) @($script:AiAttach.ToArray()) $AppVersion
    Copy-AiText $txt
    try { Start-Process 'https://claude.ai/new' } catch { Show-UiError ('Der Browser konnte nicht geöffnet werden: ' + $_.Exception.Message + "`n`nBitte https://claude.ai/new selbst öffnen - der Text ist in der Zwischenablage.") }
    Add-AiUserBubble $q @($script:AiAttach | ForEach-Object { [string]$_.Label })
    Add-AiNote 'Frage und PC-Infos sind in der Zwischenablage, claude.ai wird im Browser geöffnet. Dort anmelden, ins Eingabefeld klicken, Strg+V drücken und absenden.'
    $ui.AiInput.Clear(); $script:AiAttach.Clear(); Update-AiAttachUi
}
function Invoke-AiChip([string]$Question) {
    if ($Question -like 'Was ist diese Woche*' -and -not (Get-AiNotReadyText (Get-AiSettings))) { Add-AiUserBubble $Question @(); Start-AiWeekly -Force; return }
    if (-not (Get-AiNotReadyText (Get-AiSettings))) { Send-AiQuestion $Question }
    else { $ui.AiInput.Text = $Question; Invoke-AiClaudeAi }
}
function New-AiChips {
    $ui.AiChips.Children.Clear()
    foreach ($q in $AiStarters) {
        $bd = New-Object Windows.Controls.Border; $bd.CornerRadius = '16'; $bd.Padding = '13,7'; $bd.Margin = '0,0,8,8'; $bd.Cursor = 'Hand'; $bd.Tag = $q
        $bd.Background = New-UiBrush 'White'; $bd.BorderBrush = New-UiBrush '#AFC4EA'; $bd.BorderThickness = '1'
        $t = New-AiTb 13; $t.Text = $q; $t.TextWrapping = 'NoWrap'; $bd.Child = $t
        $bd.Add_MouseEnter({ param($s, $e) $s.Background = New-UiBrush '#E6F0FF' })
        $bd.Add_MouseLeave({ param($s, $e) $s.Background = New-UiBrush 'White' })
        $bd.Add_MouseLeftButtonUp({ param($s, $e) Invoke-AiChip ([string]$s.Tag) })
        [void]$ui.AiChips.Children.Add($bd)
    }
}
function Reset-AiChat {
    try { Save-AiMemoryFromChat } catch { }
    try { $cf = Get-AiChatFile $DataDir; if (Test-Path -LiteralPath $cf) { Remove-Item -LiteralPath $cf -Force } } catch { }
    Stop-AiSpeak
    $script:AiHistory = [System.Collections.Generic.List[object]]::new()
    $script:AiEntries.Clear(); $script:AiPending = $null; $script:AiFailedMsg = $null; $script:AiRounds = 0
    $script:AiAttach.Clear(); Update-AiAttachUi
    Hide-AiTyping
    $ui.AiChat.Children.Clear(); [void]$ui.AiChat.Children.Add($ui.AiWelcome); $ui.AiWelcome.Visibility = 'Visible'
    $ui.StatusText.Text = 'KI-Assistent: neues Gespräch.'
}

# ---- Seite öffnen / Einstellungen / Schlüssel
function Open-AiAssistant([string]$Question = '', [string]$AttachLabel = '', [string]$AttachText = '') {
    $cur = $ui.Tabs.SelectedItem
    if ($cur -and $cur -ne $ui.TabAssistant) { Set-AiLastPage $cur }
    $ui.TabAssistant.Visibility = 'Visible'
    $ui.Tabs.SelectedItem = $ui.TabAssistant
    if ($AttachText) { Add-AiAttachment $AttachLabel $AttachText }
    if ($Question -and -not ([string]$ui.AiInput.Text).Trim()) { $ui.AiInput.Text = $Question; $ui.AiInput.CaretIndex = $ui.AiInput.Text.Length }
    Update-AiCtxLabel
    try { $null = $ui.AiInput.Dispatcher.BeginInvoke([Action] { try { [void]$ui.AiInput.Focus() } catch { } }, [Windows.Threading.DispatcherPriority]::Input) } catch { }
}
function Set-AiSidebar([bool]$On) {
    $ui.AiSide.Visibility = $(if ($On) { 'Visible' } else { 'Collapsed' })
    $ui.AiSideCol.Width = New-Object Windows.GridLength $(if ($On) { 340 } else { 0 })
}
function Update-AiKeyUi {
    $s = Get-AiSettings; $pv = $s.Prov
    $ui.AiProvHint.Text = ('{0} Daten gehen an: {1}.' -f $(if ($pv.Local) { 'Komplett kostenlos, ohne Konto.' } elseif ($pv.Free) { 'Kostenlos nutzbar (mit Gratis-Konto/Tageslimit).' } elseif ($pv.Id -eq 'custom') { '' } else { 'Kostenpflichtig (Abrechnung nach Verbrauch).' }), $pv.Where)
    $ui.AiUrlPanel.Visibility = $(if ($pv.Id -eq 'custom') { 'Visible' } else { 'Collapsed' })
    $ui.AiOllamaPanel.Visibility = $(if ($pv.Local) { 'Visible' } else { 'Collapsed' })
    $ui.AiKeyPanel.Visibility = $(if ($pv.Local) { 'Collapsed' } else { 'Visible' })
    $ui.AiKeyLabel.Text = $(if ($pv.NeedKey) { 'API-Schlüssel ({0})' -f $pv.Name } else { 'API-Schlüssel (nur falls der Server einen verlangt)' })
    $ui.AiLinkLine.Visibility = $(if ($pv.KeyUrl) { 'Visible' } else { 'Collapsed' })
    $ui.AiLinkRun.Text = $(if ($pv.Local) { 'Ollama-Webseite' } else { 'Schlüssel bei {0} erstellen' -f $pv.Name })
    try { $ui.AiPrivacyText.Text = $(if ($pv.Local) { 'Ollama läuft auf diesem PC: Deine Frage und die eingeschalteten Angaben verlassen den Rechner nicht.' } else { 'Deine Frage und die hier eingeschalteten Angaben gehen an {0} und werden dort verarbeitet. Ohne deine ausdrückliche Frage wird nichts gesendet. Kennwörter, Schlüssel und Benutzernamen in Pfaden werden vorher unkenntlich gemacht.' -f $pv.Where }) } catch { }
    $st = Get-AiKeyState $DataDir $pv.Id
    $why = Get-AiNotReadyText $s
    if ($pv.Local) {
        $ui.AiKeyDot.Fill = New-UiBrush '#16A34A'
        $ui.AiKeyState.Text = 'Kostenlose lokale KI (Ollama) gewählt - kein Schlüssel nötig.'
        $ui.AiModeText.Text = 'Kostenlos lokal  ·  ' + $s.Model; $ui.AiModeDot.Fill = New-UiBrush '#16A34A'; $ui.AiWelcomeHint.Text = ''
    } elseif (-not $why) {
        $ui.AiKeyDot.Fill = New-UiBrush '#16A34A'
        $ui.AiKeyState.Text = $(if ($st.Present) { ('API-Schlüssel für {0} hinterlegt (seit {1:dd.MM.yyyy}) - verschlüsselt mit dem Windows-Datenschutz (DPAPI) für {2}. Er wird nie wieder angezeigt und nirgends protokolliert.' -f $pv.Name, $st.Date, $(if ($st.Scope -eq 'LocalMachine') { 'alle Konten dieses PCs' } else { 'dein Windows-Konto' })) } else { 'Bereit (ohne Schlüssel).' })
        $ui.AiModeText.Text = ('{0}  ·  {1}' -f $pv.Name, $s.Model); $ui.AiModeDot.Fill = New-UiBrush '#16A34A'; $ui.AiWelcomeHint.Text = ''
    } elseif ($st.Present -and -not $st.Readable) {
        $ui.AiKeyDot.Fill = New-UiBrush '#EA580C'
        $ui.AiKeyState.Text = 'Ein gespeicherter Schlüssel ist hier nicht lesbar (anderer PC, anderes Windows-Konto oder beschädigt). Bitte den Schlüssel neu einfügen und speichern.'
        $ui.AiModeText.Text = 'Schlüssel nicht lesbar  ·  Claude.ai'; $ui.AiModeDot.Fill = New-UiBrush '#EA580C'
        $ui.AiWelcomeHint.Text = 'Der gespeicherte Schlüssel ist nicht lesbar - Vorschläge öffnen bis dahin Claude.ai im Browser.'
    } else {
        $ui.AiKeyDot.Fill = New-UiBrush '#9AA5B8'
        $ui.AiKeyState.Text = $why
        $ui.AiModeText.Text = 'Noch nicht eingerichtet  ·  Claude.ai im Browser'; $ui.AiModeDot.Fill = New-UiBrush '#9AA5B8'
        $ui.AiWelcomeHint.Text = 'Noch nicht eingerichtet: Rechts einen KI-Anbieter wählen (z.B. kostenlos "Ollama"). Bis dahin öffnet ein Klick auf einen Vorschlag Claude.ai im Browser.'
    }
    $ui.AiBtnKeyRemove.IsEnabled = [bool]$st.Present
    $ui.AiModelHint.Text = $(if ($pv.Id -eq 'anthropic') { [string]$AiModelHints[$s.Model] } elseif ($pv.Local) { 'qwen3:4b braucht ca. 8 GB Arbeitsspeicher (Download ca. 2,5 GB), qwen3:8b ca. 16 GB (5 GB), gpt-oss:20b ca. 24 GB. Mit Grafikkarte deutlich schneller.' } else { [string]$pv.KeyHint })
}
function Update-AiUsageUi {
    $s = Get-AiSettings; $u = Get-AiUsage (Get-AiUsageFile $DataDir)
    $tot = [double]$u.In + [double]$u.Out
    $ui.AiUsageBig.Text = ('{0:N0} Token' -f $tot)
    $lim = ''
    if ($s.Limit -gt 0) { $lim = (' · Limit {0:N0} ({1:N0} % verbraucht)' -f $s.Limit, ($tot * 100.0 / [double]$s.Limit)) } else { $lim = ' · kein Limit' }
    $ui.AiUsageInfo.Text = ('{0:MMMM yyyy}: Eingabe {1:N0} · Ausgabe {2:N0} · {3} Anfrage(n){4}' -f (Get-Date), $u.In, $u.Out, $u.Calls, $lim)
    $pct = 0.0; if ($s.Limit -gt 0) { $pct = [math]::Min(100.0, $tot * 100.0 / [double]$s.Limit) }
    $ui.AiUsageBar.Value = $pct
    $ui.AiUsageBar.Foreground = New-UiBrush $(if ($pct -ge 90) { '#DC2626' } elseif ($pct -ge 70) { '#EA580C' } else { '#D97757' })
}
function Update-AiOnOpen {
    try {
        if (-not $script:AiOpened) { $script:AiOpened = $true; try { New-AiChips } catch { }; try { Restore-AiChat } catch { } }
        Update-AiKeyUi; Update-AiUsageUi; Update-AiCtxLabel; Update-AiOllamaUi; Update-AiWelcomeSetup
    } catch { }
}
function Show-AiPreview {
    $s = Get-AiSettings
    $ctx = New-AiContextText (Get-AiContextParts $s)
    $sb = New-Object Text.StringBuilder
    [void]$sb.AppendLine(('Mit jeder Frage gehen zusätzlich zu deiner Frage und dem bisherigen Gespräch diese Angaben an {0}:' -f $s.Prov.Where))
    [void]$sb.AppendLine()
    [void]$sb.AppendLine($(if ($ctx) { $ctx } else { '(keine - nur deine Frage und der Gesprächsverlauf)' }))
    foreach ($a in $script:AiAttach) { [void]$sb.AppendLine(); [void]$sb.AppendLine(('## Anhang: {0}' -f $a.Label)); [void]$sb.AppendLine((Protect-AiText ([string]$a.Text))) }
    [void]$sb.AppendLine()
    if ($ui.Assistant_Memory.IsChecked) { $mm = Get-AiMemoryText $DataDir; if ($mm) { [void]$sb.AppendLine(); [void]$sb.AppendLine('Gedächtnis (frühere Probleme auf diesem PC):'); [void]$sb.AppendLine($mm) } }
    [void]$sb.AppendLine('Immer dabei: Anweisungen für die KI (Rolle, Antwortstil, Liste der PC-Tools-Seiten und der erlaubten Aktionen) - ohne persönliche Daten.')
    $x = @"
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Title="KI-Assistent - Vorschau der gesendeten Daten" Width="760" Height="560" WindowStartupLocation="CenterOwner" FontFamily="Segoe UI" FontSize="13" Background="#F4F6FA">
  <Window.Resources></Window.Resources>
  <Grid Margin="18">
    <Grid.RowDefinitions><RowDefinition Height="*"/><RowDefinition Height="Auto"/></Grid.RowDefinitions>
    <Border Background="White" CornerRadius="10" BorderBrush="#E2E7F0" BorderThickness="1" Padding="4">
      <TextBox x:Name="T" IsReadOnly="True" TextWrapping="Wrap" VerticalScrollBarVisibility="Auto" FontFamily="Consolas" FontSize="12" BorderThickness="0" Background="Transparent" Foreground="#1F2A44" Padding="8"/>
    </Border>
    <StackPanel Grid.Row="1" Orientation="Horizontal" HorizontalAlignment="Right" Margin="0,12,0,0">
      <Button x:Name="Ok" Content="Schließen" Width="110" Padding="0,7" IsDefault="True" IsCancel="True"/>
    </StackPanel>
  </Grid>
</Window>
"@
    $w = [Windows.Markup.XamlReader]::Parse((Convert-ThemeXaml $x))
    $w.Owner = $window
    $w.FindName('T').Text = $sb.ToString()
    $w.FindName('Ok').Add_Click({ $w.Close() })
    [void]$w.ShowDialog()
}
# Fehlerfenster mit "Assistent fragen" (wird von Show-UiError aufgerufen; $false = normales Fenster zeigen)
function Show-AiErrorDialog([string]$Text) {
    try {
        if (-not $window -or -not $window.IsVisible) { return $false }
        if (-not $ui.Assistant_ErrorButton -or -not $ui.Assistant_ErrorButton.IsChecked) { return $false }
        $x = @"
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Title="PC-Tools" Width="500" SizeToContent="Height" MaxHeight="640" WindowStartupLocation="CenterOwner" ResizeMode="NoResize" FontFamily="Segoe UI" FontSize="13" Background="#F4F6FA" ShowInTaskbar="False">
  <Window.Resources></Window.Resources>
  <StackPanel Margin="20,18,20,16">
    <Grid>
      <Grid.ColumnDefinitions><ColumnDefinition Width="Auto"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>
      <Border Width="38" Height="38" CornerRadius="19" Background="#FFEDD5" VerticalAlignment="Top" Margin="0,0,14,0"><TextBlock Text="&#xE7BA;" FontFamily="Segoe MDL2 Assets" FontSize="18" Foreground="#EA580C" HorizontalAlignment="Center" VerticalAlignment="Center"/></Border>
      <TextBox x:Name="T" Grid.Column="1" IsReadOnly="True" TextWrapping="Wrap" BorderThickness="0" Background="Transparent" Foreground="#1F2A44" MaxHeight="420" VerticalScrollBarVisibility="Auto" Padding="0,8,0,0"/>
    </Grid>
    <StackPanel Orientation="Horizontal" HorizontalAlignment="Right" Margin="0,18,0,0">
      <Button x:Name="Ask" Padding="14,7" Margin="0,0,8,0" ToolTip="Öffnet den KI-Assistenten mit dieser Meldung als Anhang - gesendet wird erst, wenn du dort auf Senden klickst."><StackPanel Orientation="Horizontal"><TextBlock Text="&#xE99A;" FontFamily="Segoe MDL2 Assets" VerticalAlignment="Center" Margin="0,0,7,0"/><TextBlock Text="Assistent fragen"/></StackPanel></Button>
      <Button x:Name="Ok" Content="OK" Width="96" Padding="0,7" IsDefault="True" IsCancel="True"/>
    </StackPanel>
  </StackPanel>
</Window>
"@
        $w = [Windows.Markup.XamlReader]::Parse((Convert-ThemeXaml $x))
        $w.Owner = $window
        $w.FindName('T').Text = $Text
        $script:AiErrAsk = $false
        $w.FindName('Ask').Add_Click({ $script:AiErrAsk = $true; $w.Close() })
        $w.FindName('Ok').Add_Click({ $w.Close() })
        [void]$w.ShowDialog()
        if ($script:AiErrAsk) { $script:AiErrAsk = $false; Open-AiAssistant 'Was bedeutet diese Fehlermeldung von PC-Tools und was kann ich tun?' 'Fehlermeldung' $Text }
        return $true
    } catch { return $false }
}
function Start-AiExplainLog {
    $sel = ''; try { $sel = [string]$ui.LogBox.SelectedText } catch { }
    $label = 'Markierter Protokollausschnitt'; $txt = $sel
    if (-not $txt.Trim()) {
        $all = [string]$ui.LogBox.Text
        if ($all.Trim()) { $txt = (@($all -split '\r?\n') | Select-Object -Last 80) -join "`n"; $label = 'Protokoll (letzte 80 Zeilen der Anzeige)' }
    }
    if (-not $txt.Trim()) { $txt = Get-AiLogSummary (Join-Path $DataDir 'Logs'); $label = 'Zusammenfassung des letzten Laufs' }
    if (-not ([string]$txt).Trim()) { $ui.StatusText.Text = 'Es gibt noch kein Protokoll, das erklärt werden könnte.'; return }
    Open-AiAssistant 'Erkläre mir bitte dieses Protokoll: Was ist passiert, gibt es Probleme, und was sollte ich tun?' $label $txt
}

# ---- Einbau in Fenster: Knopf in der Statusleiste, Strg+Umschalt+A, Protokoll-Seite
function Add-AiFab {
    $bar = $ui.BtnCancel.Parent
    if (-not $bar -or -not ($bar -is [Windows.Controls.Panel])) { return }
    $fx = @'
<Button xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml" Cursor="Hand" Focusable="False" Margin="0,0,12,0" VerticalAlignment="Center" ToolTip="Frag den Assistenten - mit der aktuellen Seite als Kontext (Strg+Umschalt+A)">
  <Button.Template>
    <ControlTemplate TargetType="Button">
      <Border x:Name="F" CornerRadius="16" Height="32" Padding="4,0,13,0">
        <Border.Background><LinearGradientBrush StartPoint="0,0" EndPoint="1,1"><GradientStop Color="#D97757" Offset="0"/><GradientStop Color="#C2410C" Offset="1"/></LinearGradientBrush></Border.Background>
        <StackPanel Orientation="Horizontal">
          <Border Width="24" Height="24" CornerRadius="12" Background="#33FFFFFF" Margin="0,0,7,0" VerticalAlignment="Center"><TextBlock Text="&#xE99A;" FontFamily="Segoe MDL2 Assets" FontSize="12" Foreground="#FFFFFF" HorizontalAlignment="Center" VerticalAlignment="Center"/></Border>
          <TextBlock Text="Assistent" Foreground="#FFFFFF" FontWeight="SemiBold" VerticalAlignment="Center"/>
        </StackPanel>
      </Border>
      <ControlTemplate.Triggers>
        <Trigger Property="IsMouseOver" Value="True"><Setter TargetName="F" Property="Opacity" Value="0.88"/></Trigger>
        <Trigger Property="IsPressed" Value="True"><Setter TargetName="F" Property="Opacity" Value="0.75"/></Trigger>
      </ControlTemplate.Triggers>
    </ControlTemplate>
  </Button.Template>
</Button>
'@
    $b = [Windows.Markup.XamlReader]::Parse($fx)
    $b.Add_Click({ Open-AiAssistant })
    $bar.Children.Insert(0, $b)
    $script:AiFab = $b
}
function Add-AiLogHooks {
    $wp = $ui.BtnClearLog.Parent
    if ($wp -and ($wp -is [Windows.Controls.Panel])) {
        $b = New-Object Windows.Controls.Button
        $sp = New-Object Windows.Controls.StackPanel; $sp.Orientation = 'Horizontal'
        $g = New-Object Windows.Controls.TextBlock; $g.FontFamily = 'Segoe MDL2 Assets'; $g.Text = [string][char]0xE99A; $g.Margin = '0,0,7,0'; $g.VerticalAlignment = 'Center'; [void]$sp.Children.Add($g)
        $t = New-Object Windows.Controls.TextBlock; $t.Text = 'Protokoll erklären (KI)'; [void]$sp.Children.Add($t)
        $b.Content = $sp; $b.ToolTip = 'Markierten Ausschnitt (oder die letzten Zeilen) vom KI-Assistenten erklären lassen'
        $b.Add_Click({ Start-AiExplainLog })
        [void]$wp.Children.Add($b)
    }
    # Kontextmenü im Protokoll: Kopieren + Markierung erklären
    $cm = New-Object Windows.Controls.ContextMenu
    $mc = New-Object Windows.Controls.MenuItem; $mc.Header = 'Kopieren'; $mc.Command = [Windows.Input.ApplicationCommands]::Copy; [void]$cm.Items.Add($mc)
    $ma = New-Object Windows.Controls.MenuItem; $ma.Header = 'Alles markieren'; $ma.Command = [Windows.Input.ApplicationCommands]::SelectAll; [void]$cm.Items.Add($ma)
    [void]$cm.Items.Add((New-Object Windows.Controls.Separator))
    $me = New-Object Windows.Controls.MenuItem; $me.Header = 'Mit KI-Assistent erklären'; $me.Add_Click({ Start-AiExplainLog }); [void]$cm.Items.Add($me)
    $ui.LogBox.ContextMenu = $cm
}

# ---- Ereignisse
$ui.AiBtnSend.Add_Click({ Invoke-AiSendInput })
$ui.AiBtnClaudeAi.Add_Click({ Invoke-AiClaudeAi })
$ui.AiInput.Add_TextChanged({ $ui.AiInputHint.Visibility = $(if ($ui.AiInput.Text) { 'Collapsed' } else { 'Visible' }) })
$ui.AiInput.Add_PreviewKeyDown({
    param($s, $e)
    if ([string]$e.Key -eq 'Return' -and -not (([Windows.Input.Keyboard]::Modifiers -band [Windows.Input.ModifierKeys]::Shift) -ne 0)) { $e.Handled = $true; Invoke-AiSendInput }
})
$ui.AiBtnNew.Add_Click({
    if ($script:AiBusy) { $ui.StatusText.Text = 'Bitte warten, bis die KI geantwortet hat.'; return }
    if ($script:AiEntries.Count -and -not (Confirm-Ui 'Neues Gespräch beginnen? Der bisherige Verlauf wird verworfen (vorher bei Bedarf exportieren).')) { return }
    Reset-AiChat
})
$ui.AiBtnExport.Add_Click({
    if (-not $script:AiEntries.Count) { $ui.StatusText.Text = 'Noch kein Gespräch zum Exportieren.'; return }
    try {
        $d = New-Object Microsoft.Win32.SaveFileDialog; $d.Filter = 'Textdatei (*.txt)|*.txt'; $d.FileName = ('KI-Assistent_{0}_{1:yyyy-MM-dd_HHmm}.txt' -f $env:COMPUTERNAME, (Get-Date))
        if ($d.ShowDialog($window)) { [IO.File]::WriteAllText($d.FileName, (ConvertTo-AiTranscript $script:AiEntries.ToArray() $AppVersion), (New-Object Text.UTF8Encoding $true)); $ui.StatusText.Text = 'Gespräch gespeichert: ' + $d.FileName }
    } catch { Show-UiError ('Export nicht möglich: ' + $_.Exception.Message) }
})
$ui.AiBtnSidebar.Add_Click({ Set-AiSidebar ($ui.AiSide.Visibility -ne 'Visible') })
$ui.AiBtnPreview.Add_Click({ try { Show-AiPreview } catch { Show-UiError $_.Exception.Message } })
$ui.AiLinkConsole.Add_Click({ try { $u = [string](Get-AiSettings).Prov.KeyUrl; if ($u) { Start-Process $u } } catch { } })
$ui.AiBtnKeySave.Add_Click({
    $k = [string]$ui.AiKeyBox.Password
    if (-not $k.Trim()) { $ui.AiKeyTestInfo.Text = 'Bitte zuerst den API-Schlüssel in das Feld einfügen.'; return }
    $pv = (Get-AiSettings).Prov
    try {
        if ($pv.KeyPrefix -and $k.Trim() -notmatch ('^' + [regex]::Escape([string]$pv.KeyPrefix)) -and -not (Confirm-Ui ('Der Schlüssel beginnt nicht mit "{0}" - Schlüssel von {1} sehen normalerweise so aus. Trotzdem speichern?' -f $pv.KeyPrefix, $pv.Name))) { return }
        $null = Save-AiKey $k $DataDir (Get-AiSettings).Scope $pv.Id
        $ui.AiKeyBox.Clear()
        Save-AiSettings; Update-AiKeyUi
        $ui.AiKeyTestInfo.Text = 'Gespeichert. Tipp: "Verbindung testen" prüft Schlüssel und Modell.'
    } catch { $ui.AiKeyTestInfo.Text = 'Der Schlüssel konnte nicht gespeichert werden: ' + $_.Exception.Message }
    $k = $null
})
$ui.AiBtnKeyTest.Add_Click({
    if ($script:AiKeyTesting) { return }
    $s = Get-AiSettings; $pv = $s.Prov
    $k = ([string]$ui.AiKeyBox.Password).Trim(); $script:AiTestFromBox = [bool]$k
    if (-not $k) { $k = [string](Get-AiKey $DataDir $pv.Id) }
    if ($pv.NeedKey -and -not $k) { $ui.AiKeyTestInfo.Text = 'Kein Schlüssel zum Testen - bitte oben einfügen.'; return }
    if (-not $s.Url) { $ui.AiKeyTestInfo.Text = 'Bitte zuerst die Adresse eintragen.'; return }
    $script:AiKeyTesting = $true; $ui.AiBtnKeyTest.IsEnabled = $false; $ui.AiKeyTestInfo.Text = ('Teste die Verbindung zu {0} ...' -f $pv.Name)
    $script:AiTestModel = $s.Model; $script:AiTestName = [string]$pv.Name
    if ($pv.Kind -eq 'anthropic') { $tu = 'https://api.anthropic.com/v1/models?limit=100'; $th = @{ 'x-api-key' = $k; 'anthropic-version' = $AiApiVersion } }
    else { $tu = (Get-AiBaseUrl $s.Url) + '/models'; $th = @{}; if ($k) { $th['Authorization'] = 'Bearer ' + $k } }
    $tl = [bool]($tu -match '^https?://(localhost|127\.0\.0\.1)')
    Invoke-Bg -Script { param($u, $h, $l) Invoke-AiHttp 'GET' $u $h $null 30 -NoProxy:$l } -Arguments @($tu, $th, $tl) -Functions @('Invoke-AiHttp') -Done {
        param($r, $err)
        $script:AiKeyTesting = $false; $ui.AiBtnKeyTest.IsEnabled = $true
        $res = $null; foreach ($x in @($r)) { if ($x -and $x.PSObject.Properties['Status']) { $res = $x } }
        if ($err -or -not $res) { $ui.AiKeyTestInfo.Text = 'Test fehlgeschlagen: ' + $(if ($err) { $err.Message } else { 'keine Antwort' }); return }
        if ([int]$res.Status -eq 200) {
            $ids = @(); try { $ids = @(($res.Body | ConvertFrom-Json).data | ForEach-Object { [string]$_.id }) } catch { }
            $mt = ''
            if ($ids.Count) {
                $hit = ($ids -contains $script:AiTestModel) -or ($ids -contains ('models/' + $script:AiTestModel)) -or ($ids -contains ($script:AiTestModel + ':latest'))
                $mt = $(if ($hit) { (' Das gewählte Modell {0} ist verfügbar.' -f $script:AiTestModel) } else { (' Achtung: Das Modell {0} ist nicht aufgeführt - verfügbar z.B.: {1}.' -f $script:AiTestModel, (($ids | Select-Object -First 8) -join ', ')) })
            }
            $ui.AiKeyTestInfo.Text = ([string][char]0x2713 + (' Verbindung zu {0} funktioniert.' -f $script:AiTestName) + $mt + $(if ($script:AiTestFromBox) { ' Schlüssel noch nicht gespeichert: bitte "Speichern" klicken.' } else { '' }))
        } elseif ([int]$res.Status -eq 0 -and $script:AiTestName -eq 'Ollama') { $ui.AiKeyTestInfo.Text = 'Ollama antwortet nicht - bitte "Ollama einrichten" klicken.' }
        else { $ui.AiKeyTestInfo.Text = Get-AiErrorText ([int]$res.Status) ([string]$res.Body) ([string]$res.Error) $script:AiTestName }
    }
    $k = $null
})
$ui.AiBtnKeyRemove.Add_Click({
    $pv = (Get-AiSettings).Prov
    if (-not (Confirm-Ui ('Den gespeicherten API-Schlüssel für {0} von diesem PC entfernen?' -f $pv.Name))) { return }
    try { Remove-AiKey $DataDir $pv.Id; $ui.AiKeyTestInfo.Text = 'Schlüssel entfernt.' } catch { $ui.AiKeyTestInfo.Text = 'Entfernen nicht möglich: ' + $_.Exception.Message }
    Update-AiKeyUi
})
# ---- Anbieter / Modell
$script:AiProvInit = $false
function Set-AiModelList([string]$Id, [string]$Want = '') {
    $pv = Get-AiProvider $Id
    $ui.AiModelBox.Items.Clear()
    $list = [System.Collections.Generic.List[string]]::new(); foreach ($m in @($pv.Models)) { if ($m -and -not $list.Contains([string]$m)) { $list.Add([string]$m) } }
    if ($pv.Local -and $script:AiOllamaModels) { foreach ($m in @($script:AiOllamaModels)) { $mm = ([string]$m) -replace ':latest$', ''; if ($mm -and -not $list.Contains($mm)) { $list.Add($mm) } } }
    foreach ($m in $list) { $it = New-Object Windows.Controls.ComboBoxItem; $it.Content = $m; if ($pv.Id -eq 'anthropic' -and $AiModelHints[$m]) { $it.ToolTip = [string]$AiModelHints[$m] }; [void]$ui.AiModelBox.Items.Add($it) }
    if (-not $Want) { $Want = [string](ConvertFrom-AiModelMap ([string]$ui.Assistant_Model.Text))[$pv.Id] }
    if (-not $Want -and $pv.Local) { try { $Want = Get-OllamaSuggestedModel } catch { } }
    if (-not $Want -and $list.Count) { $Want = $list[0] }
    $ui.AiModelBox.Text = [string]$Want
}
function Initialize-AiProvider {
    $c = $null; try { $c = Read-PflegeConfig } catch { }
    $id = ''; $mp = ''; $cu = ''
    if ($c -and $c.Assistant) { $id = [string]$c.Assistant.Provider; $mp = [string]$c.Assistant.Model; $cu = [string]$c.Assistant.CustomUrl }
    if (-not $id) { $id = $(if (Test-Path -LiteralPath (Get-AiKeyFile $DataDir 'anthropic')) { 'anthropic' } else { 'ollama' }) }
    $ui.Assistant_Model.Text = $mp; $ui.Assistant_Provider.Text = $id; $ui.Assistant_CustomUrl.Text = $cu
    foreach ($it in $ui.AiProvider.Items) { if ([string]$it.Tag -eq $id) { $ui.AiProvider.SelectedItem = $it } }
    Set-AiModelList $id
    $script:AiProvInit = $true
}
function Update-AiOllamaUi {
    if (-not (Get-AiSettings).Prov.Local) { return }
    $ui.AiOllamaState.Text = 'Prüfe Ollama ...'
    Invoke-Bg -Script { Get-OllamaState } -Functions @('Get-OllamaState', 'Get-OllamaExe', 'Invoke-AiHttp') -Done {
        param($r, $err)
        $st = $null; foreach ($x in @($r)) { if ($x -and $x.PSObject.Properties['Running']) { $st = $x } }
        if (-not $st) { $ui.AiOllamaState.Text = 'Status unbekannt.'; return }
        $script:AiOllamaModels = @($st.Models)
        $m = ([string]$ui.AiModelBox.Text).Trim()
        $has = (@($st.Models) -contains $m) -or (@($st.Models) -contains ($m + ':latest'))
        $ui.AiOllamaState.Text = $(if (-not $st.Installed) { 'Ollama ist noch nicht installiert. "Ollama einrichten" installiert es (ca. 1 GB) und lädt das Modell.' }
            elseif (-not $st.Running) { 'Ollama ist installiert, läuft aber gerade nicht. "Ollama einrichten" startet es.' }
            elseif (-not $has) { ('Ollama läuft. Das Modell {0} ist noch nicht geladen - "Ollama einrichten" lädt es herunter. Vorhanden: {1}' -f $m, $(if (@($st.Models).Count) { @($st.Models) -join ', ' } else { 'keins' })) }
            else { ([string][char]0x2713 + (' Ollama läuft, Modell {0} ist bereit. Alles kostenlos und lokal.' -f $m)) })
        $ui.AiBtnOllamaSetup.IsEnabled = -not ($st.Running -and $has)
    }
}
$ui.AiProvider.Add_SelectionChanged({
