    if ((($md -band [Windows.Input.ModifierKeys]::Control) -ne 0) -and (($md -band [Windows.Input.ModifierKeys]::Shift) -ne 0) -and [string]$e.Key -eq 'A') { try { Open-AiAssistant } catch { }; $e.Handled = $true }
