# ---------------------------------------------------------------- Netzwerk-Diagnose (Oberfläche)
$NdFns = @('Get-NetDiag', 'Get-NetDiagAdapters', 'Get-NdWlanInfo', 'Invoke-NdCmd', 'Get-NdIpv4', 'Invoke-NetDiagFix', 'Invoke-NetAutoRepair', 'Save-NetDiagReport', 'Get-HvNetInfo', 'Invoke-DhcpLiveTest', 'Read-PktmonDhcp', 'Get-DhcpVerdict', 'Get-PktmonNicIds')
$script:NdDiag = $null; $script:NdBusy = $false
function Add-NdLog([string]$Text) { $ui.NdLog.AppendText(('{0:HH:mm:ss}  {1}' -f (Get-Date), $Text) + "`r`n"); $ui.NdLog.ScrollToEnd() }
function Set-NdBusy([bool]$On, [string]$Text = '') {
    $script:NdBusy = $On; $ui.NdProgress.Visibility = $(if ($On) { 'Visible' } else { 'Collapsed' })
    foreach ($b in 'BtnNdScan', 'BtnNdAuto', 'BtnNdFix', 'BtnNdDeep', 'BtnNdRenew', 'BtnNdRestart', 'BtnNdDhcp', 'BtnNdStatic', 'BtnNdPower', 'BtnNdBcast', 'BtnNdRand', 'BtnNdDrv', 'BtnNdWlanReNew', 'BtnNdReport') { $ui[$b].IsEnabled = -not $On }
    if ($Text) { $ui.NdInfo.Text = $Text; $ui.StatusText.Text = $Text }
}
function Show-NdResult($d) {
    $script:NdDiag = $d
    $f = @($d.Findings)
    Set-GridItems $ui.NdFindGrid $f
    $sel = $ui.NdAdGrid.SelectedItem; $selIf = if ($sel) { $sel.If } else { 0 }
    Set-GridItems $ui.NdAdGrid @($d.Adapters | Where-Object { $_.Hw -or $_.RawStatus -eq 'Up' })
    if ($selIf) { foreach ($x in $ui.NdAdGrid.Items) { if ($x.If -eq $selIf) { $ui.NdAdGrid.SelectedItem = $x } } }
    if (-not $ui.NdAdGrid.SelectedItem) { $b = @($ui.NdAdGrid.Items | Where-Object { $_.Bad }) + @($ui.NdAdGrid.Items | Where-Object { $_.RawStatus -eq 'Up' }) + @($ui.NdAdGrid.Items); if ($b.Count) { $ui.NdAdGrid.SelectedItem = $b[0] } }
    $ui.NdS0.Text = [string]@($f | Where-Object Level -eq 'bad').Count; $ui.NdS1.Text = [string]@($f | Where-Object Level -eq 'warn').Count
    $good = @($d.Adapters | Where-Object { $_.Hw -and $_.RawStatus -eq 'Up' -and $_.Ip -and -not $_.Apipa }); $ui.NdS2.Text = [string]$good.Count
    $inet = @($f | Where-Object { $_.Area -eq 'Verbindung' -and $_.Title -like 'Internet erreichbar*' }).Count
    $ui.NdS3.Text = $(if ($inet) { 'ja' } else { 'nein' })
    $ap = @($d.Adapters | Where-Object { $_.Bad })
    if ($ap.Count) { $ui.NdBannerText.Text = ('{0} hat keine gültige IPv4-Adresse ({1}). "Automatisch reparieren" klicken - oder Befund doppelklicken.' -f (($ap | ForEach-Object { $_.Name }) -join ', '), (($ap | ForEach-Object { if ($_.Ip) { $_.Ip } else { 'keine' } }) -join ', ')); $ui.NdBanner.Visibility = 'Visible' } else { $ui.NdBanner.Visibility = 'Collapsed' }
    if ($d.Wlan) {
        $ui.NdWlanText.Text = $d.Wlan.Raw
        $cur = $ui.NdWlanProf.Text; $ui.NdWlanProf.Items.Clear()
        foreach ($p in @($d.Wlan.Profiles)) { [void]$ui.NdWlanProf.Items.Add($p) }
        if ($d.Wlan.Profile -and $ui.NdWlanProf.Items.Contains($d.Wlan.Profile)) { $ui.NdWlanProf.SelectedItem = $d.Wlan.Profile } elseif ($cur -and $ui.NdWlanProf.Items.Contains($cur)) { $ui.NdWlanProf.SelectedItem = $cur } elseif ($ui.NdWlanProf.Items.Count) { $ui.NdWlanProf.SelectedIndex = 0 }
    } else { $ui.NdWlanText.Text = 'Kein WLAN-Adapter gefunden.' }
    Show-HvResult $d
    $ui.NdInfo.Text = 'Geprüft um {0:HH:mm:ss}: {1} Problem(e), {2} Hinweis(e). Doppelklick auf einen Befund wendet die Lösung an.' -f $d.Time, $ui.NdS0.Text, $ui.NdS1.Text
}
function Show-HvResult($d) {
    $h = $d.Hv; if (-not $h) { return }
    $rows = [System.Collections.Generic.List[object]]::new()
    foreach ($sw in @($h.Switches)) {
        $ve = @($d.Adapters | Where-Object { $_.Name -like ('vEthernet ({0})*' -f $sw.Name) }) | Select-Object -First 1
        $pa = @($d.Adapters | Where-Object { $_.Hw -and $sw.Nic -and $_.Desc -eq $sw.Nic }) | Select-Object -First 1
        $rows.Add([pscustomobject]@{ Name = $sw.Name; Type = $sw.Type; Nic = $sw.Nic; VEth = $(if ($ve) { $ve.Name } else { '-' }); Ip = $(if ($ve) { $ve.Ip } else { '' }); State = $(if ($sw.Type -eq 'External' -and -not $sw.Mgmt) { 'PC darf Adapter nicht nutzen' } elseif ($ve -and $ve.Apipa) { 'keine IPv4 (169.254)' } elseif ($ve -and $ve.Ip) { 'OK' } elseif ($sw.Type -eq 'Private') { 'nur VMs' } else { 'ohne IPv4' }); If = $(if ($pa) { $pa.If } else { 0 }); SwName = $sw.Name })
    }
    foreach ($bn in @($h.Bound)) {
        $pa = @($d.Adapters | Where-Object { $_.Name -eq $bn }) | Select-Object -First 1
        if ($pa -and -not @($h.Switches | Where-Object { $_.Nic -eq $pa.Desc }).Count) { $rows.Add([pscustomobject]@{ Name = '(verwaist)'; Type = '?'; Nic = $pa.Desc; VEth = '-'; Ip = ''; State = 'Bindung ohne Switch - IPv4 aus'; If = $pa.If; SwName = '' }) }
    }
    Set-GridItems $ui.HvGrid @($rows)
    $ui.HvInfo.Text = 'Hyper-V: {0}  |  Hypervisor beim Start: {1}  |  ICS: {2}  |  NAT: {3}  |  UDP 68: {4}  |  Reservierte Ports 67/68: {5}' -f $(if ($h.Enabled) { 'installiert' } else { 'nicht installiert' }), $(if ($h.Hypervisor) { $h.Hypervisor } else { 'auto' }), $h.Ics, $(if ($h.Nat.Count) { $h.Nat -join ', ' } else { 'keine' }), $(if ($h.Udp68Bad) { 'BELEGT von ' + $h.Udp68 } else { 'frei (DHCP-Client)' }), $(if ($h.ExclBad) { 'JA ' + $h.Excl } else { 'nein' })
}
function Start-NdScan([switch]$Quiet) {
    if ($script:NdBusy) { return }
    Set-NdBusy $true 'Netzwerk wird geprüft (10-30 Sekunden, ohne Internet möglich) ...'
    Invoke-Bg -Script { Get-NetDiag } -Functions $NdFns -Done {
        param($r, $err)
        Set-NdBusy $false
        if ($err -or -not $r) { $ui.NdInfo.Text = 'Prüfung fehlgeschlagen: ' + $(if ($err) { $err.Message } else { 'kein Ergebnis' }); return }
        Show-NdResult $r[0]
        $ui.StatusText.Text = 'Netzwerk-Diagnose: ' + $ui.NdInfo.Text
    }
}
function Get-NdAdapterSel([switch]$Silent) {
    $a = $ui.NdAdGrid.SelectedItem
    if (-not $a -and $script:NdDiag) { $a = @($script:NdDiag.Adapters | Where-Object { $_.Bad }) + @($script:NdDiag.Adapters | Where-Object { $_.Hw -and $_.RawStatus -eq 'Up' }) | Select-Object -First 1 }
    if (-not $a -and -not $Silent) { Show-UiError 'Bitte zuerst prüfen und in der Adapterliste einen Adapter wählen.' }
    return $a
}
function Invoke-NdAction([string]$Fix, [int]$If = 0, [string]$Arg = '', [string]$Label = '') {
    if ($script:NdBusy) { return }
    if (-not $Label) { $Label = $Fix }
    Add-NdLog ('{0} ...' -f $Label); Set-NdBusy $true ($Label + ' ...')
    Invoke-Bg -Script { param($f, $i, $a) Invoke-NetDiagFix $f $i $a } -Arguments @($Fix, $If, $Arg) -Functions $NdFns -Done {
        param($r, $err)
        Set-NdBusy $false
        if ($err) { Add-NdLog ('   Fehler: ' + $err.Message); $ui.StatusText.Text = 'Fehler: ' + $err.Message } else { $t = (@($r) -join ' ').Trim(); Add-NdLog ('   ' + $t); $ui.StatusText.Text = $t; if ($t -match '(?i)neu starten|neustart') { Show-RebootPrompt $t } }
        Start-NdScan
    }
}
function Start-NdAuto([int]$If) {
    if ($script:NdBusy) { return }
    Add-NdLog '=== Automatische Reparatur ==='; Set-NdBusy $true 'Automatische Reparatur läuft (1-5 Minuten) - das Netzwerk kann kurz wegfallen ...'
    Invoke-Bg -Script { param($i) $ndOut = [System.Collections.Generic.List[string]]::new(); $ok = Invoke-NetAutoRepair $i { param($t) $ndOut.Add($t) }; $ndOut.Add($(if ($ok) { '#OK' } else { '#FAIL' })); $ndOut } -Arguments @($If) -Functions $NdFns -Done {
        param($r, $err)
        Set-NdBusy $false
        if ($err) { Add-NdLog ('Fehler: ' + $err.Message) }
        $ok = $false; foreach ($l in @($r)) { if ($l -eq '#OK') { $ok = $true } elseif ($l -ne '#FAIL') { Add-NdLog $l } }
        $ui.StatusText.Text = $(if ($ok) { 'Reparatur erfolgreich - der Adapter hat wieder eine gültige IPv4-Adresse.' } else { 'Automatische Reparatur ohne Erfolg - siehe Protokoll. Nächster Schritt: "Tiefe Reparatur" oder Surface-Treiberpaket.' })
        Start-NdScan; Save-NdReportBg -Quiet -Fresh
    }
}
function Get-NdDir { $d = Get-NetDiagDir; New-Item $d -ItemType Directory -Force -ErrorAction SilentlyContinue | Out-Null; return $d }
function Save-NdReportBg([switch]$Quiet, [switch]$Fresh) {
    $dir = Get-NdDir; $script:NdRepQuiet = [bool]$Quiet; $dg = if ($Fresh) { $null } else { $script:NdDiag }
    if (-not $Quiet) { Set-NdBusy $true 'Bericht wird erstellt (mit WLAN-Bericht von Windows, ca. 30 Sekunden) ...' }
    Invoke-Bg -Script { param($d, $g) Save-NetDiagReport $d $g } -Arguments @($dir, $dg) -Functions $NdFns -Done {
        param($r, $err)
        if (-not $script:NdRepQuiet) { Set-NdBusy $false }
        if ($err) { Add-NdLog ('Bericht: ' + $err.Message); return }
        $script:NdLastReport = [string]@($r)[-1]; Add-NdLog ('Bericht gespeichert: ' + $script:NdLastReport)
        if (-not $script:NdRepQuiet) { $ui.StatusText.Text = 'Bericht gespeichert: ' + $script:NdLastReport; try { Start-Process explorer.exe ('/select,"{0}"' -f $script:NdLastReport) } catch { } }
    }
}
function Invoke-NdFinding($x) {
    if (-not $x -or -not $x.Fix) { if ($x) { $ui.StatusText.Text = 'Für diesen Befund gibt es keine automatische Lösung - siehe Details.' }; return }
    switch ($x.Fix) {
        'Auto' { Start-NdAuto $x.If }
        'WlanUi' { Start-Process 'ms-availablenetworks:' }
        'LocUi' { Start-Process 'ms-settings:privacy-location' }
        'Deep' { Start-NdDeep }
        default {
            if ($x.Fix -in 'DrvRe', 'Unbind', 'WlanReNew', 'Winsock', 'Drv', 'NlaClean', 'HvUnbind', 'HvSwitchDel', 'HvNetReset', 'HvBootOff', 'IcsOff', 'HvMgmt' -and -not (Confirm-Ui (('{0}?' -f $x.FixText) + "`n`n" + $x.Title))) { return }
            Invoke-NdAction $x.Fix $x.If $x.Arg $x.FixText
        }
    }
}
$ui.BtnNdScan.Add_Click({ Start-NdScan })
$script:NdLiveLast = $null
$ui.BtnNdLive.Add_Click({
    if ($script:NdBusy) { return }
    $a = Get-NdAdapterSel -Silent
    Add-NdLog '=== DHCP-Live-Test: Mitschnitt läuft, Adresse wird neu angefordert (bis 30 Sekunden) ==='; Set-NdBusy $true 'DHCP-Live-Test läuft (30 Sekunden) - wer fragt, wer antwortet, welches Netz ...'
    Invoke-Bg -Script { param($i) Invoke-DhcpLiveTest $i 30 } -Arguments @($(if ($a) { $a.If } else { 0 })) -Functions $NdFns -Done {
        param($r, $err)
        Set-NdBusy $false
        if ($err) { Add-NdLog ('Fehler: ' + $err.Message); return }
        $t = @($r)[-1]; $script:NdLiveLast = $t
        if ($t.Error) { Add-NdLog ('Live-Test: ' + $t.Error); return }
        $an = $t.Analysis
        Add-NdLog ('Adapter: {0}, {1} Sekunden' -f $t.Adapter, $t.Seconds)
        if ($an) {
            Add-NdLog ('Eigene DHCP-Anfragen: {0}  |  antwortende DHCP-Server: {1}  |  andere Geräte ohne Antwort: {2}  |  von Windows verworfene Antworten: {3}' -f $an.OwnTx, @($an.Replies).Count, @($an.Others).Count, $an.Drops68)
            foreach ($rp in @($an.Replies)) { Add-NdLog ('   Antwort von {0} (MAC {1}): {2} Pakete' -f $rp.Server, $rp.Mac, $rp.Anzahl) }
            foreach ($ot in @($an.Others)) { Add-NdLog ('   anderes Gerät {0}: {1} Anfragen ohne Antwort' -f $ot.Mac, $ot.Anfragen) }
        }
        foreach ($v in @($t.Verdict)) { Add-NdLog ('>>> ' + $v) }
        $ui.NdBannerText.Text = (@($t.Verdict) -join "`n"); $ui.NdBanner.Visibility = 'Visible'
        [Windows.MessageBox]::Show((T ((@($t.Verdict) -join "`n`n"))), (T ('PC-Tools - DHCP-Live-Test')), 'OK', $(if ($t.Ok) { 'Information' } else { 'Warning' })) | Out-Null
        Start-NdScan
    }
})
$ui.BtnNdLiveStatic.Add_Click({
    $t = $script:NdLiveLast
    if (-not $t -or -not $t.Analysis -or -not $t.Analysis.Suggest) { Show-UiError 'Bitte zuerst den DHCP-Live-Test laufen lassen - er erkennt Netz, Router und eine freie Adresse.'; return }
    $a = Get-NdAdapterSel; if (-not $a) { return }
    $an = $t.Analysis
    $d = Show-InputDialog 'Feste IP aus dem Test' ('Der Test hat das Netz {0} erkannt. Diese Werte werden für "{1}" eingestellt - damit geht das Internet sofort, auch wenn der DHCP-Server nicht antwortet. Windows prüft beim Setzen selbst, ob die Adresse schon vergeben ist. Später mit "Auf automatisch (DHCP)" zurückstellen.' -f $an.Subnet, $a.Name) @(@{ Key = 'Ip'; Label = 'IP-Adresse'; Value = $an.Suggest }, @{ Key = 'Pl'; Label = 'Präfixlänge (24 = 255.255.255.0)'; Value = '24' }, @{ Key = 'Gw'; Label = 'Router'; Value = $an.Gateway }, @{ Key = 'Dns'; Label = 'DNS-Server (mehrere mit Komma)'; Value = ('{0}, 1.1.1.1' -f $an.Gateway) })
    if (-not $d -or -not $d.Ip) { return }
    Invoke-NdAction 'Static' $a.If ('{0};{1};{2};{3}' -f $d.Ip, $d.Pl, $d.Gw, $d.Dns) ('Feste IP {0} ({1})' -f $d.Ip, $a.Name)
})
$ui.BtnNdAuto.Add_Click({ $a = Get-NdAdapterSel -Silent; Start-NdAuto $(if ($a) { $a.If } else { 0 }) })
$ui.BtnNdFix.Add_Click({ $x = $ui.NdFindGrid.SelectedItem; if (-not $x) { Show-UiError 'Bitte einen Befund auswählen.'; return }; Invoke-NdFinding $x })
$ui.NdFindGrid.Add_MouseDoubleClick({ Invoke-NdFinding $ui.NdFindGrid.SelectedItem })
$ui.BtnNdReport.Add_Click({ if (-not $script:NdDiag) { Show-UiError 'Bitte zuerst prüfen.'; return }; Save-NdReportBg })
$ui.BtnNdOpenDir.Add_Click({ Start-Process explorer.exe (Get-NdDir) })
function Start-NdDeep {
    $d = Show-InputDialog 'Tiefe Reparatur' ('Setzt TCP/IP (IPv4 und IPv6), Winsock und Proxy komplett auf Windows-Standard zurück. Danach ist ein Neustart nötig. WLAN-Profile bleiben erhalten; VPN-Programme müssen evtl. neu installiert werden.' + "`n`n" + 'Die Variante "alle Netzwerkadapter neu installieren" entspricht "Netzwerk zurücksetzen" in den Windows-Einstellungen.') @(@{ Key = 'N'; Label = 'Zusätzlich alle Netzwerkadapter neu installieren (netcfg -d)'; Type = 'Check'; Value = $false }, @{ Key = 'R'; Label = 'Danach sofort neu starten'; Type = 'Check'; Value = $true })
    if (-not $d) { return }
    Add-NdLog 'Tiefe Reparatur ...'; Set-NdBusy $true 'Netzwerk wird zurückgesetzt ...'
    $script:NdDeepRestart = [bool]$d.R
    Invoke-Bg -Script { param($n) Invoke-NetDiagFix 'Deep' 0 $n } -Arguments @($(if ($d.N) { 'netcfg' } else { '' })) -Functions $NdFns -Done {
        param($r, $err)
        Set-NdBusy $false
        if ($err) { Add-NdLog ('Fehler: ' + $err.Message); return }
        Add-NdLog ('   ' + (@($r) -join ' ')); $ui.StatusText.Text = 'Netzwerk zurückgesetzt - Neustart nötig.'
        if ($script:NdDeepRestart -and (Confirm-Ui 'Jetzt neu starten?')) { Restart-Computer -Force }
    }
}
$ui.BtnNdDeep.Add_Click({ Start-NdDeep })
function Show-NdProps {
    $a = $ui.NdAdGrid.SelectedItem; if (-not $a) { return }
    $ui.NdAdInfo.Text = '{0}: {1} | Treiber {2} | {3}{4}{5}' -f $a.Name, $a.Desc, $a.Driver, $(if ($a.Speed) { $a.Speed } else { '' }), $(if ($a.V6) { ' | IPv6 ' + $a.V6 } else { '' }), $(if ($a.RandomMac) { ' | zufällige MAC aktiv' } else { '' })
    $rows = @(Get-NetAdapterAdvancedProperty -Name $a.Name -ErrorAction SilentlyContinue | Where-Object { $_.DisplayName } | Sort-Object DisplayName | ForEach-Object {
        [pscustomobject]@{ Name = $_.DisplayName; Value = $_.DisplayValue; Key = $_.RegistryKeyword; Valid = $(if ($_.ValidDisplayValues) { ($_.ValidDisplayValues -join ' | ') } elseif ($_.NumericParameterMaxValue) { '{0} bis {1}' -f $_.NumericParameterMinValue, $_.NumericParameterMaxValue } else { 'Text' }); List = @($_.ValidDisplayValues); Adapter = $a.Name }
    })
    Set-GridItems $ui.NdPropGrid $rows
}
$ui.NdAdGrid.Add_SelectionChanged({ param($s, $e) $e.Handled = $true; Show-NdProps })
$ui.NdPropGrid.Add_SelectionChanged({ param($s, $e) $e.Handled = $true; $p = $ui.NdPropGrid.SelectedItem; $ui.NdPropVal.Items.Clear(); if ($p) { foreach ($v in $p.List) { if ($v) { [void]$ui.NdPropVal.Items.Add($v) } }; $ui.NdPropVal.Text = [string]$p.Value } })
$ui.BtnNdPropSet.Add_Click({
    $p = $ui.NdPropGrid.SelectedItem; $v = $ui.NdPropVal.Text; if (-not $p -or $v -eq '') { Show-UiError 'Bitte Eigenschaft und Wert wählen.'; return }
    try {
        if (@($p.List).Count -and $p.List -contains $v) { Set-NetAdapterAdvancedProperty -Name $p.Adapter -DisplayName $p.Name -DisplayValue $v -ErrorAction Stop } else { Set-NetAdapterAdvancedProperty -Name $p.Adapter -RegistryKeyword $p.Key -RegistryValue $v -ErrorAction Stop }
        Add-NdLog ('{0}: "{1}" = {2}' -f $p.Adapter, $p.Name, $v); Show-NdProps
        $ui.StatusText.Text = 'Übernommen - der Adapter startet kurz neu.'
    } catch { Show-UiError $_.Exception.Message }
})
$ui.BtnNdPropReset.Add_Click({ $a = Get-NdAdapterSel; if ($a -and (Confirm-Ui ('Alle erweiterten Treibereinstellungen von "{0}" auf Standard zurücksetzen?' -f $a.Name))) { try { Reset-NetAdapterAdvancedProperty -Name $a.Name -DisplayName '*' -ErrorAction Stop; Add-NdLog ($a.Name + ': erweiterte Einstellungen auf Standard.'); Start-NdScan } catch { Show-UiError $_.Exception.Message } } })
$ui.BtnNdRenew.Add_Click({ $a = Get-NdAdapterSel; if ($a) { Invoke-NdAction 'Renew' $a.If '' ('Adresse neu anfordern ({0})' -f $a.Name) } })
$ui.BtnNdRestart.Add_Click({ $a = Get-NdAdapterSel; if ($a) { Invoke-NdAction 'Restart' $a.If '' ('Adapter neu starten ({0})' -f $a.Name) } })
$ui.BtnNdDhcp.Add_Click({ $a = Get-NdAdapterSel; if ($a) { Invoke-NdAction 'SetDhcp' $a.If '' ('DHCP einschalten ({0})' -f $a.Name) } })
$ui.BtnNdPower.Add_Click({ $a = Get-NdAdapterSel; if ($a) { Invoke-NdAction 'PowerOff' $a.If '' ('Energiesparen aus ({0})' -f $a.Name) } })
$ui.BtnNdBcast.Add_Click({ $a = Get-NdAdapterSel; if ($a) { Invoke-NdAction 'Bcast' $a.If '' ('DHCP-Broadcast-Flag aus ({0})' -f $a.Name) } })
$ui.BtnNdRand.Add_Click({ $a = Get-NdAdapterSel; if ($a) { Invoke-NdAction 'RandMac' $a.If '' ('Zufällige MAC aus ({0})' -f $a.Name) } })
$ui.BtnNdDrv.Add_Click({ $a = Get-NdAdapterSel; if ($a -and (Confirm-Ui ('Treiber von "{0}" neu installieren?{1}{1}Das Gerät wird entfernt und sofort neu erkannt; Windows lädt den Treiber aus dem Treiberspeicher neu. Die Verbindung ist dabei kurz weg.' -f $a.Desc, "`n"))) { Invoke-NdAction 'DrvRe' $a.If $a.Pnp ('Treiber neu installieren ({0})' -f $a.Name) } })
$ui.BtnNdOnOff.Add_Click({ $a = Get-NdAdapterSel; if (-not $a) { return }; try { if ($a.RawStatus -eq 'Disabled') { Enable-NetAdapter -Name $a.Name -Confirm:$false -ErrorAction Stop; Add-NdLog ($a.Name + ' aktiviert.') } elseif (Confirm-Ui ('"{0}" deaktivieren?' -f $a.Name)) { Disable-NetAdapter -Name $a.Name -Confirm:$false -ErrorAction Stop; Add-NdLog ($a.Name + ' deaktiviert.') }; Start-NdScan } catch { Show-UiError $_.Exception.Message } })
$ui.BtnNdStatic.Add_Click({
    $a = Get-NdAdapterSel; if (-not $a) { return }
    $d = Show-InputDialog 'Feste IPv4-Adresse' ('Setzt für "{0}" vorübergehend eine feste Adresse - so lässt sich prüfen, ob nur DHCP klemmt (dann gibt es mit fester Adresse Internet). Die Adresse muss zum Router passen und darf im Netz nicht vergeben sein. Später "Auf automatisch (DHCP)" klicken.' -f $a.Name) @(@{ Key = 'Ip'; Label = 'IP-Adresse (z.B. 192.168.178.199)'; Value = '' }, @{ Key = 'Pl'; Label = 'Präfixlänge (24 = 255.255.255.0)'; Value = '24' }, @{ Key = 'Gw'; Label = 'Router (z.B. 192.168.178.1)'; Value = '' }, @{ Key = 'Dns'; Label = 'DNS-Server (leer = Router, mehrere mit Komma)'; Value = '' })
    if (-not $d -or -not $d.Ip) { return }
    if ($d.Ip -notmatch '^\d{1,3}(\.\d{1,3}){3}$' -or ($d.Gw -and $d.Gw -notmatch '^\d{1,3}(\.\d{1,3}){3}$')) { Show-UiError 'Bitte gültige IPv4-Adressen eingeben.'; return }
    Invoke-NdAction 'Static' $a.If ('{0};{1};{2};{3}' -f $d.Ip, $(if ($d.Pl) { $d.Pl } else { '24' }), $d.Gw, $(if ($d.Dns) { $d.Dns } else { $d.Gw })) ('Feste IP {0} ({1})' -f $d.Ip, $a.Name)
})
function Get-HvSel { $r = $ui.HvGrid.SelectedItem; if (-not $r) { $r = @($ui.HvGrid.Items) | Select-Object -First 1 }; if (-not $r) { Show-UiError 'Keine Hyper-V-Switches gefunden - bitte zuerst prüfen.' }; return $r }
$ui.BtnHvUnbind.Add_Click({ $r = Get-HvSel; if (-not $r) { return }; if (-not $r.If) { Show-UiError 'Dieser Switch hängt an keinem echten Adapter (intern/privat) - hier "Switch löschen" verwenden.'; return }; if (Confirm-Ui ('Echten Adapter "{0}" vom Hyper-V-Switch lösen und IPv4 wieder direkt einschalten?{1}{1}VMs an diesem Switch haben danach kein Netz mehr.' -f $r.Nic, "`n")) { Invoke-NdAction 'HvUnbind' $r.If '' ('Vom Hyper-V-Switch lösen ({0})' -f $r.Nic) } })
$ui.BtnHvDel.Add_Click({ $r = Get-HvSel; if (-not $r -or -not $r.SwName) { if ($r) { Show-UiError 'Verwaiste Bindung - bitte "Adapter vom Switch lösen" verwenden.' }; return }; if ($r.SwName -eq 'Default Switch') { Show-UiError 'Der "Default Switch" wird von Windows verwaltet und kann nicht gelöscht werden - "Hyper-V-Netzwerk zurücksetzen" setzt ihn neu auf.'; return }; if (Confirm-Ui ('Hyper-V-Switch "{0}" löschen? VMs, die ihn nutzen, müssen danach einem anderen Switch zugeordnet werden.' -f $r.SwName) 'Warning') { Invoke-NdAction 'HvSwitchDel' $r.If $r.SwName ('Switch löschen ({0})' -f $r.SwName) } })
$ui.BtnHvWinNat.Add_Click({ Invoke-NdAction 'WinNat' 0 '' 'WinNAT/HNS neu starten' })
$ui.BtnHvIcsOff.Add_Click({ Invoke-NdAction 'IcsOff' 0 '' 'Internetverbindungsfreigabe aus' })
$ui.BtnHvIcsOn.Add_Click({ Invoke-NdAction 'IcsOn' 0 '' 'Internetverbindungsfreigabe an' })
$ui.BtnHvBootOff.Add_Click({ if (Confirm-Ui "Hypervisor beim nächsten Start abschalten?`n`nNichts wird deinstalliert. Hyper-V, WSL2, Docker, Windows-Sandbox und Speicherintegrität laufen dann bis zum Zurückschalten nicht. Danach neu starten und prüfen, ob es IPv4 gibt.") { Invoke-NdAction 'HvBootOff' 0 '' 'Hypervisor beim Start aus'; if (Confirm-Ui 'Jetzt neu starten?') { Restart-Computer -Force } } })
$ui.BtnHvBootOn.Add_Click({ Invoke-NdAction 'HvBootOn' 0 '' 'Hypervisor wieder an' })
$ui.BtnHvReset.Add_Click({ if (Confirm-Ui "Hyper-V-Netzwerk komplett zurücksetzen?`n`n- alle selbst angelegten virtuellen Switches und NAT-Netze werden gelöscht`n- der Host-Netzwerkdienst (HNS) wird zurückgesetzt`n- die echten Adapter werden wieder direkt an IPv4 gebunden`n`nVMs bleiben erhalten, brauchen danach aber wieder einen Switch. Danach Neustart." 'Warning') { Invoke-NdAction 'HvNetReset' 0 '' 'Hyper-V-Netzwerk zurücksetzen'; if (Confirm-Ui 'Zum Abschluss jetzt neu starten?') { Restart-Computer -Force } } })
$ui.BtnHvRemove.Add_Click({ if (Confirm-Ui "Hyper-V deinstallieren?`n`nVMs und virtuelle Festplatten bleiben als Dateien erhalten, können aber erst nach erneuter Installation gestartet werden. Neustart nötig." 'Warning') { Invoke-NdAction 'HvFeatureOff' 0 '' 'Hyper-V deinstallieren' } })
$ui.BtnHvMgr.Add_Click({ try { Start-Process 'virtmgmt.msc' } catch { Show-UiError 'Hyper-V-Manager ist nicht installiert.' } })
$ui.BtnNdMacTest.Add_Click({ $a = Get-NdAdapterSel; if ($a -and (Confirm-Ui ("Adapter ""{0}"" bekommt testweise eine neue, zufällige MAC-Adresse.`n`nFür den Router ist das ein neues Gerät. Bekommt er damit sofort eine IPv4-Adresse, verweigert der Router nur der alten MAC eine Adresse (alter Geräte-Eintrag, feste Zuordnung, Sperre). Kommt auch dann nichts, liegt es am Router/DHCP-Server selbst oder am PC.`n`nDie Verbindung ist kurz weg. Rückgängig mit ""Original-MAC zurück""." -f $a.Name))) { Invoke-NdAction 'MacTest' $a.If '' ('Test mit neuer MAC ({0})' -f $a.Name) } })
$ui.BtnNdMacBack.Add_Click({ $a = Get-NdAdapterSel; if ($a) { Invoke-NdAction 'MacRestore' $a.If '' ('Original-MAC zurück ({0})' -f $a.Name) } })
$ui.BtnNdNla.Add_Click({ if (Confirm-Ui 'Alle gespeicherten Netzwerkprofile ("Netz 2", "Netz 3" ...) löschen? Windows legt beim nächsten Verbinden je Netz ein frisches Profil an. Eine Sicherung wird vorher gespeichert.') { Invoke-NdAction 'NlaClean' 0 '' 'Netzwerkprofile bereinigen' } })
$ui.BtnNdNcpa.Add_Click({ Start-Process 'ncpa.cpl' })
$ui.BtnNdDevMgr.Add_Click({ Start-Process 'devmgmt.msc' })
$ui.BtnNdWlanReNew.Add_Click({ $p = [string]$ui.NdWlanProf.SelectedItem; if (-not $p) { Show-UiError 'Kein WLAN-Profil gewählt.'; return }; if (Confirm-Ui ('WLAN-Profil "{0}" löschen und mit gleichem Kennwort neu anlegen? Das behebt beschädigte Profile und alte Einstellungen (z.B. feste MAC/IP je Netz).' -f $p)) { Invoke-NdAction 'WlanReNew' 0 $p ('WLAN-Profil neu anlegen ({0})' -f $p) } })
$ui.BtnNdWlanForget.Add_Click({ $p = [string]$ui.NdWlanProf.SelectedItem; if ($p -and (Confirm-Ui ('WLAN "{0}" vergessen? Beim nächsten Verbinden muss das Kennwort neu eingegeben werden.' -f $p) 'Warning')) { Add-NdLog ((Invoke-NdCmd 'netsh.exe' ('wlan delete profile name="{0}"' -f $p) 15) -replace '\s+', ' '); Start-NdScan } })
$ui.BtnNdWlanList.Add_Click({ Start-Process 'ms-availablenetworks:' })
$ui.BtnNdWlanReport.Add_Click({
    Set-NdBusy $true 'Windows erstellt den WLAN-Bericht (bis zu 60 Sekunden) ...'
    Invoke-Bg -Script { Invoke-NdCmd 'netsh.exe' 'wlan show wlanreport' 90 } -Functions @('Invoke-NdCmd') -Done {
        param($r, $err)
        Set-NdBusy $false
        $f = Join-Path $env:ProgramData 'Microsoft\Windows\WlanReport\wlan-report-latest.html'
        if (Test-Path $f) { Start-Process $f; $ui.StatusText.Text = 'WLAN-Bericht geöffnet: Verbindungsabbrüche, Fehlergründe und Sitzungen der letzten 3 Tage.' } else { Show-UiError ('WLAN-Bericht nicht erstellt: ' + (@($r) -join ' ')) }
    }
})
function Select-NdFolder([string]$Desc) {
    Add-Type -AssemblyName System.Windows.Forms
    $d = New-Object System.Windows.Forms.FolderBrowserDialog; $d.Description = $Desc; $d.ShowNewFolderButton = $true
    $rm = @(Get-CimInstance Win32_LogicalDisk -Filter 'DriveType=2' -ErrorAction SilentlyContinue | Select-Object -First 1)
    if ($rm.Count) { $d.SelectedPath = $rm[0].DeviceID + '\' }
    if ($d.ShowDialog() -eq 'OK') { return $d.SelectedPath }; return ''
}
$ui.BtnNdStick.Add_Click({
    $p = Select-NdFolder 'USB-Stick oder Ordner für die portablen PC-Tools (es wird ein Unterordner "PCPflege" angelegt)'
    if (-not $p) { return }
    $dest = Join-Path $p 'PCPflege'
    try { Copy-PortablePflege $dest $false; $ui.StatusText.Text = ('Portable PC-Tools mit Netzwerk-Notfall liegt in {0}' -f $dest); Start-Process explorer.exe $dest } catch { Show-UiError $_.Exception.Message }
})
$ui.BtnNdDeep2.Add_Click({
    $o = @('x'); if ($ui.NdDeepLive.IsChecked) { $o += 'live' }; if ($ui.NdDeepProbe.IsChecked -and $ui.NdDeepLive.IsChecked) { $o += 'probe' }; if ($ui.NdDeepWfp.IsChecked) { $o += 'wfp' }; if ($ui.NdDeepTrace.IsChecked -and $ui.NdDeepLive.IsChecked) { $o += 'trace' }
    Start-Process powershell.exe -ArgumentList ('-NoProfile -ExecutionPolicy Bypass -File "{0}" -NetDeep -DeepOpts "{1}"' -f $PSCommandPath, ($o -join ','))
    Add-NdLog 'Tiefenanalyse im eigenen Fenster gestartet - die ZIP-Datei landet im Berichtsordner.'
})
$ui.BtnNdDeepDir.Add_Click({ Start-Process explorer.exe (Get-NdDir) })
$ui.BtnNdConsole.Add_Click({ Start-Process powershell.exe -ArgumentList ('-NoProfile -ExecutionPolicy Bypass -File "{0}" -NetDiag' -f $PSCommandPath) })
$ui.BtnNdSurface.Add_Click({ $ui.Tabs.SelectedItem = $ui.TabSurface })
$ui.BtnNdRescue.Add_Click({ $ui.Tabs.SelectedItem = $ui.TabRescue })
$ui.Tabs.Add_SelectionChanged({ param($s, $e) if ($e.OriginalSource -eq $s -and $s.SelectedItem -eq $ui.TabNetDiag -and -not $script:NdDiag -and -not $script:NdBusy) { Start-NdScan } })

# ---------------------------------------------------------------- Microsoft Surface (Oberfläche)
$SfKnown = @(
    @{ P = 'WLAN: "Keine gültige IP-Konfiguration", 169.254.x.x, kein Internet'; M = 'v.a. Marvell-WLAN: Pro 3-6, Pro (2017), Book 1/2, Laptop 1/2, Studio 1/2'; L = 'Seite Netzwerk-Diagnose > "Automatisch reparieren" (Energiesparen aus, Broadcast-Flag, zufällige MAC aus, Profil neu, Treiber neu). Dann Surface-Paket oder "Nur Netzwerktreiber" vom Stick. Router: DHCP an, MAC-Filter/Gerätesperre, freie Adressen im DHCP-Bereich. Test: Handy-Hotspot oder USB-LAN-Adapter.' }
    @{ P = 'WLAN bricht nach Standby/Zuklappen ab'; M = 'Marvell-WLAN, Pro 3-6, Book 1/2, Laptop 1/2'; L = 'Energiesparen des Adapters aus, WLAN-Energiesparmodus auf Höchstleistung, Schnellstart aus, aktuelles Surface-Paket. Hilft nur Neustart: Treiber neu installieren.' }
    @{ P = 'Akku lädt nicht / "angeschlossen, wird nicht geladen"'; M = 'alle'; L = 'Surface-Connect-Stecker und -Buchse reinigen (Kontakte!), anderes Netzteil (LED am Stecker muss leuchten), erzwungener Neustart, im UEFI "Akkubegrenzung" prüfen (lädt dann nur bis 50 %), Akkutreiber neu laden (Button oben).' }
    @{ P = 'Surface startet nicht / schwarzer Bildschirm'; M = 'alle'; L = '15 Minuten am Netzteil laden, dann Ein/Aus 20 Sekunden halten (ältere Modelle: Zwei-Tasten-Methode, siehe oben). Bild weg, Surface läuft: Windows+Strg+Umschalt+B (Grafik neu starten).' }
    @{ P = 'Type Cover wird nicht erkannt'; M = 'Pro, Go'; L = 'Abnehmen, Kontakte reinigen, wieder anstecken; "Gerät neu starten" in der Liste oben; erzwungener Neustart; aktuelles Surface-Paket. Geht die Tastatur im UEFI, ist es ein Treiberproblem.' }
    @{ P = 'Bildschirm flackert oder Geister-Touch'; M = 'bekannt bei Pro 4 und Book 1'; L = 'Touch neu kalibrieren, Touch-Gerät neu starten, Surface-Paket. Bleibt es: bekannter Hardware-Fehler (Pro 4 "Flickergate"), Reparatur über Microsoft.' }
    @{ P = 'Firmware-Update scheitert / BitLocker fragt nach Schlüssel'; M = 'alle'; L = 'Netzteil anschließen, Akku über 40 %, vorher "BitLocker für Firmware-Update aussetzen", dann Paket installieren und neu starten (beim Neustart NICHT ausschalten).' }
    @{ P = 'Stift reagiert nicht'; M = 'Pro, Go, Book, Studio, Laptop Studio'; L = 'Batterie (AAAA) tauschen bzw. Slim Pen laden, neu koppeln (obere Taste 5-7 Sekunden halten), Bluetooth-Treiber, Stift-Einstellungen prüfen.' }
    @{ P = 'Lüfter laut, Gerät heiß, langsam'; M = 'Pro, Book, Laptop'; L = 'Aktuelles Surface-Paket (enthält Thermik-/SAM-Firmware), Energiemodus "Ausbalanciert", Autostart aufräumen (Seite Optimieren).' }
    @{ P = 'Kamera / Windows Hello geht nicht'; M = 'alle'; L = 'Kamera-Datenschutz (Button oben), Kamera "neu starten" in der Liste, Surface-Paket (Kamera- und IR-Treiber).' }
    @{ P = 'Surface Dock: kein Bild, kein Netzwerk am Dock'; M = 'Surface Dock 1/2, USB-C/Thunderbolt-Dock'; L = 'Dock 10 Sekunden vom Strom, "Surface Dock Firmware-Update" installieren, Surface-Paket aktualisieren. LAN am Dock ist ein eigener Adapter (Realtek) - in der Netzwerk-Diagnose sichtbar.' }
)
Set-GridItems $ui.SfKnownGrid @($SfKnown | ForEach-Object { [pscustomobject]$_ })
foreach ($m in $SurfaceModels) { [void]$ui.SfModelCombo.Items.Add(('{0}{1}' -f $m.N, $(if ($m.Id) { '  (ID ' + $m.Id + ')' } else { '  (nur Windows Update)' }))) }
$script:SfInfo = $null; $script:SfDrv = $null; $script:SfPack = $null
function Get-SfSelModel { $i = $ui.SfModelCombo.SelectedIndex; if ($i -lt 0) { Show-UiError 'Bitte das Surface-Modell wählen.'; return $null }; return $SurfaceModels[$i] }
function Update-SfLocal {
    $k = if ($ui.SfModelCombo.SelectedIndex -ge 0) { (($SurfaceModels[$ui.SfModelCombo.SelectedIndex].N -replace '\(.*$', '') -replace 'Surface', '').Trim() } else { '' }
    $l = @(Find-SurfaceLocalPack $k)
    $ui.SfLocalInfo.Text = $(if ($l.Count) { 'Gefundene Pakete: ' + (($l | Select-Object -First 3 | ForEach-Object { '{0} ({1:N0} MB, {2})' -f $_.Name, ($_.Length / 1MB), $_.DirectoryName }) -join '; ') } else { 'Kein Surface-Paket auf Stick oder im Datenordner gefunden.' })
    return $l
}
function Update-Surface {
    $si = Get-SurfaceInfo; $script:SfInfo = $si
    $ui.SfNoSurface.Visibility = $(if ($si.IsSurface) { 'Collapsed' } else { 'Visible' })
    $ui.SfModel.Text = '{0} {1}{2}' -f $si.Maker, $si.Model, $(if ($si.Entry) { '  ->  Paket: ' + $si.Entry.N } elseif ($si.IsSurface) { '  (Modell nicht in der Liste - unten von Hand wählen)' } else { '' })
    $ui.SfSku.Text = '{0}  /  {1}' -f $(if ($si.Sku) { $si.Sku } else { '-' }), $si.Serial
    $ui.SfUefi.Text = '{0}{1}' -f $si.Uefi, $(if ($si.UefiDate) { '  vom ' + $si.UefiDate } else { '' })
    $ui.SfCpu.Text = '{0} ({1})' -f $si.Cpu, $si.CpuKind
    $os = Get-CimInstance Win32_OperatingSystem -ErrorAction SilentlyContinue
    $ui.SfOs.Text = '{0}, Version {1}, Build {2}' -f $os.Caption, (Get-ItemProperty 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion' -ErrorAction SilentlyContinue).DisplayVersion, $os.BuildNumber
    $sb = try { if (Confirm-SecureBootUEFI -ErrorAction Stop) { 'Secure Boot an' } else { 'Secure Boot AUS' } } catch { 'Secure Boot unbekannt' }
    $tp = try { $t = Get-Tpm -ErrorAction Stop; if ($t.TpmReady) { 'TPM bereit' } elseif ($t.TpmPresent) { 'TPM vorhanden, nicht bereit' } else { 'kein TPM' } } catch { 'TPM unbekannt' }
    $bl = try { $v = Get-BitLockerVolume -MountPoint $env:SystemDrive -ErrorAction Stop; 'BitLocker {0}' -f $(if ($v.ProtectionStatus -eq 'On') { 'an' } elseif ($v.VolumeStatus -ne 'FullyDecrypted') { 'ausgesetzt' } else { 'aus' }) } catch { 'BitLocker unbekannt' }
    $ui.SfSec.Text = '{0}, {1}, {2}' -f $sb, $tp, $bl
    $w = @(Get-NetAdapter -ErrorAction SilentlyContinue | Where-Object { $_.HardwareInterface -and $_.InterfaceDescription -match 'Wi-?Fi|Wireless|WLAN|802\.11|AVASTAR' } | Select-Object -First 1)
    $ui.SfWlan.Text = $(if ($w.Count) { '{0}  -  Treiber {1} vom {2}{3}' -f $w[0].InterfaceDescription, $w[0].DriverVersion, $w[0].DriverDate, $(if ($w[0].InterfaceDescription -match 'Marvell|AVASTAR') { '  (Marvell: bekannte Verbindungsprobleme, siehe unten)' } else { '' }) } else { 'kein WLAN-Adapter gefunden (Treiber fehlt?)' })
    $ipOk = @(Get-NetAdapter -ErrorAction SilentlyContinue | Where-Object { $_.HardwareInterface -and $_.Status -eq 'Up' } | Where-Object { @(Get-NetIPAddress -InterfaceIndex $_.ifIndex -AddressFamily IPv4 -ErrorAction SilentlyContinue | Where-Object { $_.IPAddress -notlike '169.254.*' }).Count })
    $apipa = @(Get-NetAdapter -ErrorAction SilentlyContinue | Where-Object { $_.HardwareInterface -and $_.Status -eq 'Up' } | Where-Object { $ix = $_.ifIndex; @(Get-NetIPAddress -InterfaceIndex $ix -AddressFamily IPv4 -ErrorAction SilentlyContinue | Where-Object { $_.IPAddress -like '169.254.*' }).Count -and -not @(Get-NetIPAddress -InterfaceIndex $ix -AddressFamily IPv4 -ErrorAction SilentlyContinue | Where-Object { $_.IPAddress -notlike '169.254.*' }).Count })
    $ui.SfS3.Text = $(if ($ipOk.Count) { 'OK' } elseif ($apipa.Count) { '169.254' } else { 'keine' })
    if ($apipa.Count -or -not $ipOk.Count) { $ui.SfBannerText.Text = $(if ($apipa.Count) { '{0} bekommt keine IPv4-Adresse (169.254.x.x) - kein Internet. Die Netzwerk-Diagnose findet die Ursache und repariert ohne Internet.' -f (($apipa | ForEach-Object { $_.Name }) -join ', ') } else { 'Kein Adapter mit gültiger IPv4-Adresse - kein Internet. Die Netzwerk-Diagnose findet die Ursache und repariert ohne Internet.' }); $ui.SfBanner.Visibility = 'Visible' } else { $ui.SfBanner.Visibility = 'Collapsed' }
    $vc = @(Get-CimInstance Win32_VideoController -ErrorAction SilentlyContinue | Where-Object { $_.CurrentHorizontalResolution } | Select-Object -First 1)
    $ui.SfDisp.Text = $(if ($vc.Count) { '{0} x {1}, {2} Hz, {3} (Treiber {4})' -f $vc[0].CurrentHorizontalResolution, $vc[0].CurrentVerticalResolution, $vc[0].CurrentRefreshRate, $vc[0].Name, $vc[0].DriverVersion } else { '-' })
    # Akku
    $bat = @(Get-CimInstance Win32_Battery -ErrorAction SilentlyContinue)
    $des = 0; $full = 0; $cyc = -1
    try { $des = [double](@(Get-CimInstance -Namespace root\wmi -ClassName BatteryStaticData -ErrorAction Stop)[0].DesignedCapacity) } catch { }
    try { $full = [double](@(Get-CimInstance -Namespace root\wmi -ClassName BatteryFullChargedCapacity -ErrorAction Stop)[0].FullChargedCapacity) } catch { }
    try { $cyc = [int](@(Get-CimInstance -Namespace root\wmi -ClassName BatteryCycleCount -ErrorAction Stop)[0].CycleCount) } catch { }
    if ($bat.Count) {
        $hp = if ($des -gt 0 -and $full -gt 0) { [math]::Min(100, [math]::Round(100 * $full / $des)) } else { -1 }
        $ui.SfS0.Text = $(if ($hp -ge 0) { '{0} %' -f $hp } else { '?' })
        $st = switch ([int]$bat[0].BatteryStatus) { 1 { 'entlädt' } 2 { 'am Netzteil' } 3 { 'voll' } 6 { 'lädt' } 7 { 'lädt schnell' } 9 { 'lädt' } default { 'Status ' + $bat[0].BatteryStatus } }
        $ui.SfBat.Text = '{0} % geladen, {1}; Zustand {2}' -f $bat[0].EstimatedChargeRemaining, $st, $ui.SfS0.Text
        $ui.SfBatText.Text = ('Ladung: {0} % ({1})' -f $bat[0].EstimatedChargeRemaining, $st) + "`n" + ('Kapazität: {0:N0} mWh von ursprünglich {1:N0} mWh = {2}{3}' -f $full, $des, $ui.SfS0.Text, $(if ($hp -ge 0 -and $hp -lt 70) { ' - Akku deutlich verschlissen, Tausch überlegen' } elseif ($hp -ge 0 -and $hp -lt 85) { ' - normaler Verschleiß' } else { '' })) + "`n" + ('Ladezyklen: {0}' -f $(if ($cyc -ge 0) { $cyc } else { 'nicht verfügbar' }))
        if ([int]$bat[0].BatteryStatus -eq 2 -and [int]$bat[0].EstimatedChargeRemaining -le 55 -and [int]$bat[0].EstimatedChargeRemaining -ge 45) { $ui.SfBatText.Text += "`n" + 'Am Netzteil bei ca. 50 %: vermutlich ist die Akkubegrenzung im UEFI eingeschaltet.' }
    } else { $ui.SfS0.Text = '-'; $ui.SfBat.Text = 'kein Akku (Studio) oder nicht erkannt'; $ui.SfBatText.Text = 'Kein Akku erkannt.' }
    # Zubehör / Eingabe
    $inp = @(Get-PnpDevice -PresentOnly -ErrorAction SilentlyContinue | Where-Object { $_.FriendlyName -match '(?i)Surface|Type Cover|Pen|Stift|Touch|Digitizer|Kamera|Camera|IR|Dock|Keyboard|Tastatur|Precision' -and $_.Class -in 'HIDClass', 'Keyboard', 'Mouse', 'Camera', 'Image', 'Bluetooth', 'System', 'USB', 'Net', 'Battery', 'Monitor', 'SoftwareDevice', 'Firmware' })
    $rows = @($inp | Where-Object { $_.Class -in 'HIDClass', 'Keyboard', 'Mouse', 'Camera', 'Image', 'Bluetooth' -or $_.FriendlyName -match 'Dock' } | Sort-Object Class, FriendlyName | ForEach-Object { [pscustomobject]@{ Name = $_.FriendlyName; Class = $_.Class; State = $(if ($_.Status -eq 'OK') { 'OK' } else { [string]$_.Status }); Version = ''; Id = $_.InstanceId } })
    Set-GridItems $ui.SfInGrid $rows
    $acc = @(); if (@($inp | Where-Object FriendlyName -match 'Type Cover').Count) { $acc += 'Type Cover' }; if (@($inp | Where-Object FriendlyName -match '(?i)\bPen\b|Stift').Count) { $acc += 'Stift' }; if (@($inp | Where-Object FriendlyName -match 'Dock').Count) { $acc += 'Dock' }
    $ui.SfAcc.Text = $(if ($acc.Count) { ($acc -join ', ') + ' erkannt' } else { 'kein Type Cover, Stift oder Dock erkannt' })
    # Tastenkombinationen
    $m = $si.Model
    $old = $m -match 'Surface (Pro [1-4]\b|3$|Book$)'
    $lap = $m -match 'Laptop|Studio'
    $ui.SfKeys.Text = (@(
        $(if ($lap) { 'UEFI öffnen: Windows-Einstellungen > System > Wiederherstellung > Erweiterter Start > Problembehandlung > Erweiterte Optionen > UEFI-Firmwareeinstellungen (oder den Button unten).' } else { 'UEFI öffnen: Surface ausschalten, Lauter-Taste gedrückt halten, Ein/Aus kurz drücken, Lauter-Taste halten bis das Surface-Logo erscheint (oder den Button unten).' }),
        $(if ($lap) { 'Vom USB-Stick starten: im UEFI unter "Boot configuration" USB nach oben ziehen - oder "Erweiterter Start" > "Gerät verwenden".' } else { 'Vom USB-Stick starten: Stick einstecken, ausschalten, Leiser-Taste gedrückt halten, Ein/Aus kurz drücken, Leiser-Taste halten bis die Punkte kreisen.' }),
        $(if ($old) { 'Erzwungener Neustart (dieses Modell): Ein/Aus 30 Sekunden halten, loslassen; dann Lauter + Ein/Aus gleichzeitig 15 Sekunden halten, loslassen, 10 Sekunden warten, Surface normal einschalten.' } else { 'Erzwungener Neustart: Ein/Aus 20 Sekunden gedrückt halten, bis das Windows-Logo erscheint (bei Surface Pro 5 und neuer, Laptop, Book 2 und neuer, Go, Studio).' }),
        'Bild weg, Surface läuft: Windows-Taste + Strg + Umschalt + B startet den Grafiktreiber neu.',
        'Zurücksetzen ohne Windows: vom Wiederherstellungsstick (Surface-Wiederherstellungsabbild von Microsoft, mit Seriennummer) starten.'
    ) -join "`n")
    # Modellauswahl
    if ($si.Entry -and $ui.SfModelCombo.SelectedIndex -lt 0) { for ($i = 0; $i -lt $SurfaceModels.Count; $i++) { if ($SurfaceModels[$i].N -eq $si.Entry.N) { $ui.SfModelCombo.SelectedIndex = $i } } }
    if ($si.IsSurface -and [int]$os.BuildNumber -lt 22000) { $ui.SfWin.SelectedIndex = 1 }
    $null = Update-SfLocal
    Start-SfDrvScan
}
function Start-SfDrvScan {
    $ui.StatusText.Text = 'Surface-Treiber und Firmware werden gelesen ...'
    Invoke-Bg -Script {
        $err = @{}; foreach ($p in @(Get-CimInstance Win32_PnPEntity -ErrorAction SilentlyContinue)) { $err[[string]$p.DeviceID] = [int]$p.ConfigManagerErrorCode }
        @(Get-CimInstance Win32_PnPSignedDriver -ErrorAction SilentlyContinue | Where-Object { $_.DeviceName } | ForEach-Object {
            $c = if ($err.ContainsKey([string]$_.DeviceID)) { $err[[string]$_.DeviceID] } else { 0 }
            $dt = ''; try { if ($_.DriverDate) { $dt = ([datetime]$_.DriverDate).ToString('dd.MM.yyyy') } } catch { }
            [pscustomobject]@{ Name = [string]$_.DeviceName; Class = [string]$_.DeviceClass; Version = [string]$_.DriverVersion; Date = $dt; Provider = [string]$_.DriverProviderName; State = $(if ($c) { 'Fehler Code ' + $c } else { 'OK' }); Bad = [bool]$c; Id = [string]$_.DeviceID
                Surf = [bool]([string]$_.DeviceName -match '(?i)Surface|Marvell|AVASTAR|Type Cover|Precision|Digitizer' -or [string]$_.DeviceClass -in 'FIRMWARE', 'NET' -or ([string]$_.DriverProviderName -match 'Microsoft' -and [string]$_.InfName -match '(?i)surface')) }
        } | Sort-Object @{ e = { -not $_.Bad } }, Class, Name)
    } -Done {
        param($r, $err)
        $script:SfDrv = @($r | Where-Object { $_ -and $_.Name })
        $ui.SfS1.Text = [string]@($script:SfDrv | Where-Object Surf).Count; $ui.SfS2.Text = [string]@($script:SfDrv | Where-Object Bad).Count
        Show-SfDrv; $ui.StatusText.Text = 'Surface-Seite aktualisiert.'
    }
}
function Show-SfDrv {
    if (-not $script:SfDrv) { return }
    $q = $ui.SfDrvSearch.Text
    $rows = @(switch ($ui.SfDrvFilter.SelectedIndex) { 1 { $script:SfDrv | Where-Object Bad } 2 { $script:SfDrv } default { $script:SfDrv | Where-Object { $_.Surf -or $_.Bad } } })
    if ($q) { $rows = @($rows | Where-Object { Test-Match $_ $q @('Name', 'Class', 'Provider', 'Version') }) }
    Set-GridItems $ui.SfDrvGrid $rows
}
