$ui.BtnSfFind.Add_Click({
    $m = Get-SfSelModel; if (-not $m) { return }
    if (-not $m.Id) { $ui.SfPackInfo.Text = $m.N + ': Microsoft bietet kein MSI-Paket an - Treiber und Firmware kommen nur über Windows Update.'; return }
    $win = if ($ui.SfWin.SelectedIndex -eq 1) { 10 } else { 11 }
    $ui.SfPackInfo.Text = 'Suche das neueste Paket bei Microsoft ...'; $ui.BtnSfFind.IsEnabled = $false
    $script:SfOsBuild = $(if ($script:SfInfo -and $script:SfInfo.IsSurface) { [Environment]::OSVersion.Version.Build } else { 0 })
    Invoke-Bg -Script {
        param($i, $w, $b)
        $l = @(Get-SurfaceMsiList $i $w $b)
        foreach ($p in $l) {
            $len = [int64]-1
            try { $rq = [Net.HttpWebRequest]::Create($p.Url); $rq.Method = 'HEAD'; $rq.Timeout = 8000; $rs = $rq.GetResponse(); $len = [int64]$rs.ContentLength; $rs.Close() } catch { }
            $p | Add-Member -NotePropertyName Size -NotePropertyValue $len -Force
        }
        , $l
    } -Arguments @($m.Id, $win, $script:SfOsBuild) -Functions @('Get-SurfaceMsiList', 'Get-WebHtml') -Done {
        param($r, $err)
        $ui.BtnSfFind.IsEnabled = $true
        if ($err) { $ui.SfPackInfo.Text = 'Nicht gefunden: ' + $err.Message + ' (ohne Internet? Dann auf einem anderen PC laden.)'; return }
        $l = @($r | ForEach-Object { $_ } | Where-Object { $_ -and $_.Url }); if (-not $l.Count) { $ui.SfPackInfo.Text = 'Keine Pakete gefunden.'; return }
        $script:SfPack = $l[0]
        $wantWin = if ($ui.SfWin.SelectedIndex -eq 1) { 10 } else { 11 }
        $rows = for ($k = 0; $k -lt $l.Count; $k++) {
            $p = $l[$k]
            $fit = if ($k -eq 0) { 'empfohlen' } elseif ($p.Kind -ne 'MSI') { 'ZIP - nur manuell' } elseif ($p.Win -and $p.Win -ne $wantWin) { 'für Windows ' + $p.Win } elseif ($script:SfOsBuild -and $p.Build -gt $script:SfOsBuild) { 'für neueres Windows (Build ' + $p.Build + ')' } elseif ($script:SfOsBuild -and $p.Build) { 'passt (älterer Build)' } else { 'Alternative' }
            [pscustomobject]@{ File = $p.File; Url = $p.Url; Win = $p.Win; WinText = $(if ($p.Win) { 'Windows ' + $p.Win } else { '-' }); Build = $p.Build; Version = $p.Version; Kind = $p.Kind
                Size = [int64]$p.Size; SizeText = $(if ([int64]$p.Size -gt 0) { '{0:N0} MB' -f ([double]$p.Size / 1MB) } else { '?' }); Fit = $fit; Level = $(if ($k -eq 0) { 'Good' } elseif ($p.Kind -ne 'MSI') { 'Off' } else { '' }) }
        }
        Set-GridItems $ui.SfPackGrid @($rows)
        $ui.SfPackBox.Visibility = 'Visible'; $ui.SfPackHint.Visibility = 'Visible'
        try { $ui.SfPackGrid.SelectedIndex = 0 } catch { }
        $ui.SfPackInfo.Text = 'Empfohlen: {0}  (Windows {1}, Build {2}, Version {3}) - {4} Variante(n) gefunden, Auswahl in der Liste' -f $l[0].File, $l[0].Win, $l[0].Build, $l[0].Version, $l.Count
    }
})
$ui.BtnSfOneClick.Add_Click({
    if (-not ($script:SfInfo -and $script:SfInfo.IsSurface)) { Show-UiError 'Dieser PC ist kein Surface. Auf einem Surface wird das Modell automatisch erkannt - sonst bitte unten das Modell wählen und "Herunterladen und installieren" nutzen.'; return }
    $m = $null
    if ($script:SfInfo.Entry) { $m = $script:SfInfo.Entry; for ($i = 0; $i -lt $SurfaceModels.Count; $i++) { if ($SurfaceModels[$i].N -eq $m.N) { $ui.SfModelCombo.SelectedIndex = $i } } }
    else { $m = Get-SfSelModel }
    if (-not $m) { return }
    if (-not $m.Id) { Show-UiError ($m.N + ': Microsoft bietet kein MSI-Paket an - Treiber und Firmware kommen nur über Windows Update.'); return }
    if (-not (Confirm-Ui ("Neueste Treiber und Firmware für {0} suchen, herunterladen (0,5-1,5 GB) und installieren?`n`nNetzteil anschließen. BitLocker wird von Windows für das Firmware-Update automatisch ausgesetzt. Nach dem Neustart spielt das Surface die Firmware ein - dabei NICHT ausschalten." -f $m.N))) { return }
    $win = if ($ui.SfWin.SelectedIndex -eq 1) { 10 } else { 11 }
    $ui.SfPackInfo.Text = 'Suche das neueste Paket bei Microsoft ...'; $ui.BtnSfOneClick.IsEnabled = $false; $ui.BtnSfFind.IsEnabled = $false
    $script:SfOsBuild = [Environment]::OSVersion.Version.Build
    Invoke-Bg -Script {
        param($i, $w, $b)
        $l = @(Get-SurfaceMsiList $i $w $b)
        foreach ($p in $l) { $len = [int64]-1; try { $rq = [Net.HttpWebRequest]::Create($p.Url); $rq.Method = 'HEAD'; $rq.Timeout = 8000; $rs = $rq.GetResponse(); $len = [int64]$rs.ContentLength; $rs.Close() } catch { }; $p | Add-Member -NotePropertyName Size -NotePropertyValue $len -Force }
        , $l
    } -Arguments @($m.Id, $win, $script:SfOsBuild) -Functions @('Get-SurfaceMsiList', 'Get-WebHtml') -Done {
        param($r, $err)
        $ui.BtnSfOneClick.IsEnabled = $true; $ui.BtnSfFind.IsEnabled = $true
        if ($err) { $ui.SfPackInfo.Text = 'Nicht gefunden: ' + $err.Message + ' (ohne Internet? Dann auf einem anderen PC laden.)'; return }
        $l = @($r | ForEach-Object { $_ } | Where-Object { $_ -and $_.Url })
        if (-not @($l | Where-Object { $_.Kind -eq 'MSI' }).Count) { $ui.SfPackInfo.Text = 'Kein installierbares MSI-Paket gefunden - bitte Microsoft-Downloadseite nutzen.'; return }
        $script:SfPack = $l[0]
        $rows = for ($k = 0; $k -lt $l.Count; $k++) {
            $p = $l[$k]
            [pscustomobject]@{ File = $p.File; Url = $p.Url; Win = $p.Win; WinText = $(if ($p.Win) { 'Windows ' + $p.Win } else { '-' }); Build = $p.Build; Version = $p.Version; Kind = $p.Kind
                Size = [int64]$p.Size; SizeText = $(if ([int64]$p.Size -gt 0) { '{0:N0} MB' -f ([double]$p.Size / 1MB) } else { '?' }); Fit = $(if ($k -eq 0) { 'empfohlen' } elseif ($p.Kind -ne 'MSI') { 'ZIP - nur manuell' } else { 'Alternative' }); Level = $(if ($k -eq 0) { 'Good' } elseif ($p.Kind -ne 'MSI') { 'Off' } else { '' }) }
        }
        Set-GridItems $ui.SfPackGrid @($rows)
        $ui.SfPackBox.Visibility = 'Visible'; $ui.SfPackHint.Visibility = 'Visible'
        $idx = 0; for ($k = 0; $k -lt $rows.Count; $k++) { if ($rows[$k].Kind -eq 'MSI') { $idx = $k; break } }
        try { $ui.SfPackGrid.SelectedIndex = $idx } catch { }
        $ui.SfPackInfo.Text = 'Lade und installiere: {0} (Windows {1}, Build {2}, Version {3})' -f $rows[$idx].File, $rows[$idx].Win, $rows[$idx].Build, $rows[$idx].Version
        Start-SfPack 'Install'
    }
})
function Start-SfPack([string]$Mode, [string]$Dest = '', [string]$File = '') {
    $m = if ($File) { $null } else { Get-SfSelModel }; if (-not $File -and -not $m) { return }
    if ($m -and -not $m.Id) { Show-UiError 'Für dieses Modell gibt es kein MSI-Paket - bitte Windows Update nutzen.'; return }
    $job = @{ SurfMode = $Mode; SurfWin = $(if ($ui.SfWin.SelectedIndex -eq 1) { 10 } else { 11 }) }
    if ($m) { $job.SurfId = $m.Id; $job.SurfName = $m.N } else { $job.SurfName = [IO.Path]::GetFileName($File) }
    if ($Dest) { $job.SurfDest = $Dest }; if ($File) { $job.SurfFile = $File }
    $sel = $null; try { $sel = $ui.SfPackGrid.SelectedItem } catch { }
    if (-not $File -and $sel -and $sel.Url -and $Mode -ne 'Net') {
        if ($sel.Kind -ne 'MSI' -and $Mode -eq 'Install') { Show-UiError 'Die gewählte Variante ist ein ZIP-Paket ohne Installer - bitte eine MSI-Variante wählen oder "Auf USB-Stick / in Ordner laden" nutzen.'; return }
        $job.SurfUrl = [string]$sel.Url; $job.SurfPkgFile = [string]$sel.File
    }
    Start-Run -Parts @('SurfacePack') -Job $job
}
$ui.BtnSfInstall.Add_Click({
    $m = Get-SfSelModel; if (-not $m) { return }
    if ($script:SfInfo -and $script:SfInfo.IsSurface -and $script:SfInfo.Entry -and $script:SfInfo.Entry.N -ne $m.N -and -not (Confirm-Ui ('Gewählt ist "{0}", erkannt wurde aber "{1}". Trotzdem fortfahren? (Das Paket prüft das Modell selbst.)' -f $m.N, $script:SfInfo.Entry.N) 'Warning')) { return }
    if (-not $script:SfInfo.IsSurface) { Show-UiError 'Dieser PC ist kein Surface - bitte "Auf USB-Stick / in Ordner laden" verwenden.'; return }
    if (Confirm-Ui ("Surface-Treiber- und Firmwarepaket für {0} laden (0,5-1,5 GB) und installieren?`n`nNetzteil anschließen. BitLocker wird von Windows für das Firmware-Update automatisch ausgesetzt. Nach dem Neustart spielt das Surface die Firmware ein - dabei NICHT ausschalten." -f $m.N)) { Start-SfPack 'Install' }
})
$ui.BtnSfSave.Add_Click({
    $m = Get-SfSelModel; if (-not $m) { return }
    $p = Select-NdFolder ('Ziel für das Surface-Paket ({0}) - z.B. der USB-Stick. Es wird ein Ordner "Surface" angelegt.' -f $m.N); if (-not $p) { return }
    $dest = if ((Split-Path $p -Leaf) -eq 'Surface') { $p } else { Join-Path $p 'Surface' }
    $portable = $false
    if (-not (Test-Path (Join-Path (Split-Path $dest) 'PCPflege.ps1')) -and -not (Test-Path (Join-Path (Split-Path $dest) 'PCPflege\PCPflege.ps1'))) { $portable = Confirm-Ui 'Soll die portablen PC-Tools (mit Netzwerk-Notfall) gleich mit auf den Stick? Dann kann das Surface das Paket direkt vom Stick installieren.' }
    if ($portable) { try { Copy-PortablePflege (Join-Path (Split-Path $dest) 'PCPflege') $false; $dest = Join-Path (Join-Path (Split-Path $dest) 'PCPflege') 'Surface' } catch { Show-UiError $_.Exception.Message } }
    Start-SfPack 'Save' $dest
})
$ui.BtnSfAllModels.Add_Click({
    $cnt = @($SurfaceModels | Where-Object { $_.Id }).Count
    $p = Select-NdFolder ('Zielordner für die neuesten Pakete ALLER {0} Surface-Modelle - z.B. ein NAS-Ordner. Pro Modell wird ein Unterordner angelegt.' -f $cnt); if (-not $p) { return }
    if (-not (Confirm-Ui ("Die neuesten Treiber-/Firmwarepakete für ALLE {0} Surface-Modelle nach`n{1}`nladen?`n`nDas sind je Modell 0,5-1,5 GB - insgesamt viele GB und kann länger dauern. Bereits vorhandene Pakete werden übersprungen." -f $cnt, $p) 'Warning')) { return }
    $win = if ($ui.SfWin.SelectedIndex -eq 1) { 10 } else { 11 }
    Start-Run -Parts @('SurfaceAll') -Job @{ SurfAllDest = $p; SurfWin = $win }
})
function Select-SfLocalMsi {
    $l = @(Update-SfLocal)
    if ($l.Count -and (Confirm-Ui ('Gefundenes Paket verwenden?{0}{0}{1}{0}({2:N0} MB, {3})' -f "`n", $l[0].Name, ($l[0].Length / 1MB), $l[0].DirectoryName))) { return $l[0].FullName }
    Add-Type -AssemblyName System.Windows.Forms
    $d = New-Object System.Windows.Forms.OpenFileDialog; $d.Filter = 'Surface-Paket (*.msi)|*.msi'; $d.Title = 'Surface-Treiberpaket wählen'
    if ($d.ShowDialog() -eq 'OK') { return $d.FileName }; return ''
}
