function Restart-SfDevice($r) {
    if (-not $r) { return }
    try { Disable-PnpDevice -InstanceId $r.Id -Confirm:$false -ErrorAction Stop; Start-Sleep -Seconds 2; Enable-PnpDevice -InstanceId $r.Id -Confirm:$false -ErrorAction Stop; $ui.StatusText.Text = $r.Name + ' neu gestartet.' } catch { Show-UiError ('{0}: {1}' -f $r.Name, $_.Exception.Message) }
}
