$ui.BtnPwrReset.Add_Click({ if (Confirm-Ui 'Aktuellen Energiesparplan auf die Windows-Standardwerte zurücksetzen?') { $null = & powercfg.exe /restoredefaultschemes 2>&1; Load-Custom; $ui.StatusText.Text = 'Energiesparpläne auf Standard gesetzt.' } })
$ui.BtnPlanUltimate.Add_Click({ $o = & powercfg.exe -duplicatescheme e9a42b02-d5df-448d-aa00-03f14749eb61 2>&1; Load-Custom; $ui.StatusText.Text = 'Plan "Ultimative Leistung" hinzugefügt - oben auswählen und übernehmen.' })
$ui.BtnBatReport.Add_Click({ $f = Join-Path $env:TEMP 'Akku-Bericht.html'; $null = & powercfg.exe /batteryreport /output $f 2>&1; if (Test-Path $f) { Start-Process $f } else { Show-UiError 'Kein Akku gefunden.' } })
$ui.BtnBatVantage.Add_Click({ try { Start-Process 'shell:AppsFolder\E046963F.LenovoCompanion_k1h2ywk1493x8!App' -ErrorAction Stop } catch { Start-Process 'ms-settings:batterysaver' } })
$ui.CuBright.Add_ValueChanged({ $ui.CuBrightVal.Text = '{0} %' -f [int]$ui.CuBright.Value })
$ui.CuBright.Add_PreviewMouseUp({ try { $m = Get-CimInstance -Namespace root\wmi -ClassName WmiMonitorBrightnessMethods -ErrorAction Stop | Select-Object -First 1; $null = Invoke-CimMethod -InputObject $m -MethodName WmiSetBrightness -Arguments @{ Timeout = [uint32]1; Brightness = [byte][int]$ui.CuBright.Value } } catch { } })
$ui.CuMouseSpeed.Add_ValueChanged({ $ui.CuMouseSpeedVal.Text = '{0} von 20 (Standard 10)' -f [int]$ui.CuMouseSpeed.Value })
$ui.CuKeyDelay.Add_ValueChanged({ $ui.CuKeyDelayVal.Text = @('kurz', 'mittel', 'lang', 'sehr lang')[[int]$ui.CuKeyDelay.Value] })
$ui.CuKeyRate.Add_ValueChanged({ $ui.CuKeyRateVal.Text = '{0} von 31 (Standard 31 = schnell)' -f [int]$ui.CuKeyRate.Value })
$ui.BtnCuMouseApply.Add_Click({ try { Save-MouseSettings } catch { Show-UiError $_.Exception.Message } })
$ui.BtnCuKeyApply.Add_Click({ try { Save-KeySettings } catch { Show-UiError $_.Exception.Message } })
$ui.BtnCuLookApply.Add_Click({ try { Save-LookSettings } catch { Show-UiError $_.Exception.Message } })
foreach ($p in @(@('BtnCuNight', 'ms-settings:nightlight'), @('BtnCuDisplay', 'ms-settings:display'), @('BtnCuHdr', 'ms-settings:display-advanced'), @('BtnCuGfx', 'ms-settings:display-advancedgraphics'), @('BtnCuPointer', 'ms-settings:easeofaccess-mousepointer'),
                 @('BtnCuWall', 'ms-settings:personalization-background'), @('BtnCuColors', 'ms-settings:colors'), @('BtnCuLock', 'ms-settings:lockscreen'), @('BtnCuThemes', 'ms-settings:themes'), @('BtnCuFonts', 'ms-settings:fonts'))) {
    $ui[$p[0]].Tag = $p[1]; $ui[$p[0]].Add_Click({ param($s, $e) Start-Process ([string]$s.Tag) })
}
$ui.BtnCuSounds.Add_Click({ Start-Process 'control.exe' 'mmsys.cpl,,2' })
$ui.BtnCuRename.Add_Click({
    $n = $ui.CuPcName.Text.Trim(); $d = $ui.CuPcDesc.Text.Trim()
    try {
        $os = Get-CimInstance Win32_OperatingSystem; if ([string]$os.Description -ne $d) { Set-CimInstance -InputObject $os -Property @{ Description = $d } }
        if ($n -and $n -ne $env:COMPUTERNAME) {
            if ($n -notmatch '^[A-Za-z0-9\-]{1,15}$' -or $n -match '^\d+$') { Show-UiError 'Name ungültig: nur Buchstaben, Ziffern und Bindestrich, höchstens 15 Zeichen, nicht nur Ziffern.'; return }
            if (-not (Confirm-Ui ('PC von "{0}" in "{1}" umbenennen? Wirkt nach Neustart (Netzlaufwerke/Freigaben auf anderen PCs ggf. anpassen).' -f $env:COMPUTERNAME, $n))) { return }
            Rename-Computer -NewName $n -Force -ErrorAction Stop; $ui.StatusText.Text = 'PC wird beim nächsten Neustart zu ' + $n
        } else { $ui.StatusText.Text = 'Beschreibung gespeichert.' }
    } catch { Show-UiError $_.Exception.Message }
})
$ui.BtnBiosRead.Add_Click({ Update-CuBios })
$ui.CuBiosAll.Add_Click({ if ($script:CuBios) { Show-CuBios } })
$ui.BtnBiosApply.Add_Click({ Save-CuBios })

# Fehlersuche und Reparatur
$ui.BtnRepScan.Add_Click({ Start-RepScan })
$ui.BtnRepPick.Add_Click({ Select-RepRecommended })
if ($ui.AppxFixOut) {
    $script:AppxFns = @('Get-AppxIssues', 'Get-AppxIssueText', 'Repair-AppxIssues', 'Invoke-NdCmd')
    $ui.BtnAppxCheck.Add_Click({
        if ($script:Job) { Show-UiError 'Es läuft bereits eine Aufgabe - bitte warten.'; return }
        $ui.AppxFixState.Text = 'Store-Apps werden geprüft ... (dauert nur wenige Sekunden)'; $ui.AppxFixOut.Text = ''
        Invoke-Bg -Script { Get-AppxIssueText } -Functions $script:AppxFns -Done {
            param($r, $e)
            if ($e) { $ui.AppxFixOut.Text = 'Fehler: ' + $e.Message } else { $ui.AppxFixOut.Text = [string]@($r | Where-Object { $null -ne $_ })[-1] }
            $ui.AppxFixState.Text = 'Prüfung fertig (' + (Get-Date -Format 'HH:mm:ss') + ')'
        }
    })
    $ui.BtnAppxFix.Add_Click({
        if ($script:Job) { Show-UiError 'Es läuft bereits eine Aufgabe - bitte warten.'; return }
        if (-not (Confirm-Ui "Defekte Store-Apps entfernen (ihre Store-Seite öffnet sich danach zum Neuinstallieren) und beschädigte Laufzeiten bzw. WebView2 neu installieren?`n`nHinweis: Beim neuen Outlook liegen Exchange-, Microsoft-365- und Outlook.com-Mails auf dem Server. Nur reine POP-Konten speichern lokal - die vorher sichern.")) { return }
        $ui.AppxFixState.Text = 'Store-Apps werden repariert ... (Neuinstallationen können einige Minuten dauern)'; $ui.AppxFixOut.Text = ''
        Invoke-Bg -Script { Repair-AppxIssues } -Functions $script:AppxFns -Done {
            param($r, $e)
            if ($e) { $ui.AppxFixOut.Text = 'Fehler: ' + $e.Message }
            else {
                $x = @($r | Where-Object { $null -ne $_ })[-1]
                $ui.AppxFixOut.Text = [string]$x.Text
                foreach ($f in @($x.Open | Select-Object -First 5)) { try { Start-Process ('ms-windows-store://pdp/?PFN=' + $f) } catch { } }
            }
            $ui.AppxFixState.Text = 'Reparatur fertig (' + (Get-Date -Format 'HH:mm:ss') + ') - in der geöffneten Store-Seite auf "Installieren" klicken.'
        }
    })
    $ui.BtnAppxCopy.Add_Click({ $t = [string]$ui.AppxFixOut.Text; if (-not $t.Trim()) { $ui.AppxFixState.Text = 'Noch nichts zum Kopieren - bitte erst "Store-Apps prüfen".'; return }; try { [Windows.Clipboard]::SetText($t); $ui.AppxFixState.Text = 'Protokoll in die Zwischenablage kopiert.' } catch { $ui.AppxFixState.Text = 'Kopieren fehlgeschlagen.' } })
}
# ---------------------------------------------------------------- WLAN optimieren
if ($ui.WlOut) {
    $script:WlFns = @('Get-WlanAdapter', 'Get-WlanIfInfo', 'Get-WlanDriverCaps', 'Get-WlanAdvPlan', 'Get-WlanPowerIdx', 'Get-WlanPowerText', 'Get-WlanDevPower', 'Test-WlanPing', 'Get-WlanReport', 'Invoke-WlanOptimize', 'Undo-WlanOptimize', 'Test-WlanStability', 'New-WlanWinReport', 'Reset-WlanConnection', 'ConvertFrom-NtWlanText', 'Get-NtChannelAdvice', 'Format-NtMac', 'Invoke-NdCmd', 'Get-SysExe')
    $script:WlRun = {
        param([string]$State, [scriptblock]$Script, $ArgList, [scriptblock]$After)
        if ($script:Job) { Show-UiError 'Es läuft bereits eine Aufgabe - bitte warten.'; return }
        $ui.WlState.Text = $State; $ui.WlOut.Text = ''
        $script:WlAfter = $After
        Invoke-Bg -Script $Script -Arguments $ArgList -Functions $script:WlFns -Done {
            param($r, $e)
            $x = @($r | Where-Object { $null -ne $_ }); $x = if ($x.Count) { $x[-1] } else { $null }
            if ($e) { $ui.WlOut.Text = 'Fehler: ' + $e.Message; $ui.WlState.Text = 'Fehlgeschlagen.' }
            else { try { & $script:WlAfter $x } catch { $ui.WlOut.Text = [string]$x } }
        }
    }
    $ui.BtnWlScan.Add_Click({
        & $script:WlRun 'WLAN wird analysiert ... (ca. 10 Sekunden)' { Get-WlanReport } @() {
            param($x)
            $ui.WlOut.Text = [string]$x.Text
            $ui.WlState.Text = 'Analyse fertig (' + (Get-Date -Format 'HH:mm:ss') + ')' + $(if ($x.NeedLocation) { ' - für die WLAN-Liste bitte "Standortdienste" einschalten.' } else { '' })
        }
    })
    $ui.BtnWlStab.Add_Click({ & $script:WlRun 'Stabilitätstest läuft 60 Sekunden - bitte das WLAN normal weiter benutzen ...' { Test-WlanStability 60 } @() { param($x) $ui.WlOut.Text = [string]$x; $ui.WlState.Text = 'Stabilitätstest fertig (' + (Get-Date -Format 'HH:mm:ss') + ')' } })
    $ui.BtnWlOpt.Add_Click({
        if (-not (Confirm-Ui "WLAN optimieren?`n`n- WLAN-Energiesparen im Netzbetrieb aus`n- `"Computer kann das Gerät ausschalten`" aus`n- Treiber-Einstellungen auf die Empfehlung (5/6 GHz bevorzugen, volle Sendeleistung, MIMO-Energiesparen aus, ...)`n- kein automatisches Verbinden mit vorgeschlagenen Hotspots`n`nAlles wird gesichert (Rückgängig). Das WLAN ist dabei ca. 10 Sekunden weg.")) { return }
        & $script:WlRun 'WLAN wird optimiert ...' { param($dd, $bat) Invoke-WlanOptimize $dd $bat } @($DataDir, [bool]$ui.WlBattery.IsChecked) { param($x) $ui.WlOut.Text = [string]$x; $ui.WlState.Text = 'Optimierung fertig (' + (Get-Date -Format 'HH:mm:ss') + ')' }
    })
    $ui.BtnWlUndo.Add_Click({
        if (-not (Confirm-Ui 'Alle WLAN-Optimierungen von PC-Tools zurücknehmen?')) { return }
        & $script:WlRun 'Wird zurückgesetzt ...' { param($dd) Undo-WlanOptimize $dd } @($DataDir) { param($x) $ui.WlOut.Text = [string]$x; $ui.WlState.Text = 'Fertig.' }
    })
    $ui.BtnWlReset.Add_Click({ & $script:WlRun 'WLAN-Adapter wird neu gestartet ...' { Reset-WlanConnection } @() { param($x) $ui.WlOut.Text = [string]$x; $ui.WlState.Text = 'Fertig.' } })
    $ui.BtnWlReport.Add_Click({ & $script:WlRun 'Windows erstellt den WLAN-Bericht (bis zu 1 Minute) ...' { New-WlanWinReport } @() { param($x) if ($x) { $ui.WlState.Text = 'WLAN-Bericht geöffnet: ' + $x; try { Start-Process ([string]$x) } catch { } } else { $ui.WlState.Text = 'Der WLAN-Bericht konnte nicht erstellt werden.' } } })
    $ui.BtnWlLoc.Add_Click({ Start-Process 'ms-settings:privacy-location' })
    $ui.BtnWlSettings.Add_Click({ Start-Process 'ms-settings:network-wifi' })
    $ui.BtnWlChannels.Add_Click({ Show-NtSection 'NtSecWlan' })
    $ui.BtnWlNetDiag.Add_Click({ $ui.Tabs.SelectedItem = $ui.TabNetDiag })
    $ui.BtnWlCopy.Add_Click({ $t = [string]$ui.WlOut.Text; if (-not $t.Trim()) { $ui.WlState.Text = 'Noch nichts zum Kopieren.'; return }; try { [Windows.Clipboard]::SetText($t); $ui.WlState.Text = 'In die Zwischenablage kopiert.' } catch { } })
}
# ---------------------------------------------------------------- WLAN-Rundgang
if ($ui.WlRoomGrid) {
    $script:WlRoomsLoad = { Set-GridItems $ui.WlRoomGrid @(Read-NdocJson 'wlan-raeume.json' @() | ForEach-Object { $_ } | Where-Object { $_ }) }
    try { & $script:WlRoomsLoad } catch { }
    $ui.BtnWlRoomMeasure.Add_Click({
        $room = $ui.WlRoom.Text.Trim(); if (-not $room) { $ui.WlRoomState.Text = 'Bitte zuerst den Raumnamen eingeben (z.B. "Küche", "Büro OG").'; return }
        $ui.BtnWlRoomMeasure.IsEnabled = $false; $ui.WlRoomState.Text = ('Messe in "{0}" ... (10 Sekunden, bitte stehen bleiben)' -f $room)
        Invoke-Bg -Script { param($r) Measure-WlanRoom $r 10 } -Arguments @($room) -Functions @('Measure-WlanRoom', 'Get-WlanAdapter', 'Get-WlanIfInfo', 'Format-NtMac') -Done {
            param($r, $e)
            $ui.BtnWlRoomMeasure.IsEnabled = $true
            $x = @($r | Where-Object { $_ -and $_.PSObject.Properties['Room'] })[0]
            if ($e -or -not $x) { $ui.WlRoomState.Text = 'Messung fehlgeschlagen: ' + $(if ($e) { $e.Message } else { 'keine Werte' }); return }
            $all = @(Read-NdocJson 'wlan-raeume.json' @() | ForEach-Object { $_ } | Where-Object { $_ -and $_.Room -ne $x.Room }) + @($x)
            Save-NdocJson 'wlan-raeume.json' @($all)
            & $script:WlRoomsLoad
            $ui.WlRoomState.Text = ('{0}: {1} % ({2} dBm) - {3}. Nächster Raum?' -f $x.Room, $x.Signal, $x.Dbm, $x.Rating); $ui.WlRoom.Text = ''; $ui.WlRoom.Focus() | Out-Null
        }
    })
    $ui.BtnWlRoomDel.Add_Click({ $sel = $ui.WlRoomGrid.SelectedItem; if (-not $sel) { return }; Save-NdocJson 'wlan-raeume.json' @(Read-NdocJson 'wlan-raeume.json' @() | ForEach-Object { $_ } | Where-Object { $_ -and $_.Room -ne $sel.Room }); & $script:WlRoomsLoad })
    $ui.BtnWlRoomClear.Add_Click({ if (Confirm-Ui 'Alle Raum-Messungen löschen?') { Save-NdocJson 'wlan-raeume.json' @(); & $script:WlRoomsLoad } })
}
# ---------------------------------------------------------------- Netzwerk dokumentieren
if ($ui.NdocDevGrid) {
    $script:NdocDir = Join-Path ([Environment]::GetFolderPath('MyDocuments')) 'PC-Tools Berichte'
    $ui.BtnNdocPdf.IsEnabled = $false; $ui.BtnNdocAi.IsEnabled = $false
    $script:NdocKnxMon = $null
    try {
        $set = Read-NdocJson 'einstellungen.json' $null
        if ($set) { $ui.NdocTitle.Text = [string]$set.Title; $ui.NdocSite.Text = [string]$set.Site; $ui.NdocAuthor.Text = [string]$set.Author; $ui.NdocLogo.Text = [string]$set.LogoPath; $ui.NdocHaUrl.Text = [string]$set.HaUrl; $ui.NdocFbUser.Text = [string]$set.FbUser
            if ($set.HaToken) { try { $ss = ConvertTo-SecureString ([string]$set.HaToken) -ErrorAction Stop; $ui.NdocHaToken.Password = [Runtime.InteropServices.Marshal]::PtrToStringBSTR([Runtime.InteropServices.Marshal]::SecureStringToBSTR($ss)); $ui.NdocHaSave.IsChecked = $true } catch { } } }
        $ui.NdocAuto.IsChecked = [bool](Get-ScheduledTask -TaskName 'PC-Tools Netzwerk-Dokumentation' -ErrorAction SilentlyContinue)
        if ($ui.NdocAuto.IsChecked) { $ui.NdocAutoState.Text = 'aktiv' }
    } catch { }
    $script:NdocSaveSet = {
        $tok = ''
        if ($ui.NdocHaSave.IsChecked -and $ui.NdocHaToken.Password) { try { $tok = ConvertFrom-SecureString (ConvertTo-SecureString $ui.NdocHaToken.Password -AsPlainText -Force) } catch { } }
        Save-NdocJson 'einstellungen.json' ([pscustomobject]@{ Title = $ui.NdocTitle.Text.Trim(); Site = $ui.NdocSite.Text.Trim(); Author = $ui.NdocAuthor.Text.Trim(); LogoPath = $ui.NdocLogo.Text.Trim(); HaUrl = $ui.NdocHaUrl.Text.Trim(); FbUser = $ui.NdocFbUser.Text.Trim(); HaToken = $tok })
    }
    $script:NdocShow = {
        $res = $script:Ndoc; $rows = @($res.Rows); $find = @($res.Find)
        Set-GridItems $ui.NdocDevGrid $rows
        Set-GridItems $ui.NdocFindGrid $find
        Set-GridItems $ui.NdocExpGrid @($res.Exposure)
        $x = $res.Data
        if ($x.Smart) { Set-GridItems $ui.NdocSmartGrid @(@($x.Smart.Knx | ForEach-Object { [pscustomobject]@{ System = 'KNX IP'; Ip = $_.Ip; Model = ('{0} ({1})' -f $_.Name, $_.Address); Firmware = ''; Auth = $(if ($_.Secure) { 'KNX Secure' } else { 'ungesichert' }); Risk = $(if ($_.Secure) { 'Info' } else { 'Mittel' }) } }) + @($x.Smart.Items | Where-Object { $_.System -ne 'KNX IP' }) + @($(if ($x.Ha) { [pscustomobject]@{ System = 'Home Assistant (API)'; Ip = $x.Ha.Url; Model = $x.Ha.Name; Firmware = $x.Ha.Version; Auth = 'Token'; Risk = $(if (@($x.Ha.Updates).Count) { 'Updates: ' + @($x.Ha.Updates).Count } else { 'OK' }) } }))) } else { Set-GridItems $ui.NdocSmartGrid @() }
        $sc = Get-NdocScore $find
        $hi = @($find | Where-Object { $_.SevNo -le 2 }).Count; $mid = @($find | Where-Object { $_.SevNo -eq 3 }).Count
        $ui.NdocSummary.Text = ('{0} Geräte in {1}/{2} · Bewertung {3} ({4}/100, {5}) · {6} kritische/hohe, {7} mittlere Befunde · von außen erreichbar: {8}{9}{10}' -f @($rows | Where-Object { -not $_.Offline }).Count, $x.Net.Ip, $x.Net.Prefix, $sc.Grade, $sc.Score, $sc.Text, $hi, $mid, @($res.Exposure | Where-Object { $_.Way -like 'Portfreigabe*' -or $_.Way -like 'Fernzugang*' -or $_.Way -like 'Laut Shodan aus*' }).Count, $(if ($x.Smart) { ' · Smart Home: {0} KNX, {1} Systeme' -f @($x.Smart.Knx).Count, @($x.Smart.Items).Count } else { '' }), $(if ($x.Fritz) { ' · FRITZ!Box: {0} bekannte Geräte' -f @($x.Fritz.Hosts).Count } elseif ($x.FritzErr) { ' · FRITZ!Box: ' + $x.FritzErr } else { '' }))
        $d = $res.Diff
        $ui.NdocDiff.Text = if (-not $d) { 'Erste Erfassung - ab der nächsten wird verglichen.' } else { 'Seit {0}: {1} neue Geräte, {2} nicht mehr da, {3} mit neuen Diensten, {4} neue und {5} behobene Befunde.' -f $(try { ([datetime]$d.PrevTime).ToString('dd.MM.yyyy HH:mm') } catch { $d.PrevTime }), @($d.NewDev).Count, @($d.GoneDev).Count, @($d.PortsOpened).Count, @($d.NewFind).Count, @($d.FixedFind).Count }
    }
    $ui.BtnNdocScan.Add_Click({
        if ($script:Job) { Show-UiError 'Es läuft bereits eine Aufgabe - bitte warten.'; return }
        try { & $script:NdocSaveSet } catch { }
        $ui.BtnNdocScan.IsEnabled = $false; $ui.BtnNdocPdf.IsEnabled = $false; $ui.BtnNdocAi.IsEnabled = $false
        $sync = Start-NtProgress $ui.NdocProg $ui.NdocState 'Starte ...'
        $opt = @{ Ext = [bool]$ui.NdocExt.IsChecked }
        if ($ui.NdocFbPass.Password) { $opt.FbUser = $ui.NdocFbUser.Text.Trim(); $opt.FbPass = (ConvertTo-SecureString $ui.NdocFbPass.Password -AsPlainText -Force) }
        if ($ui.NdocHaUrl.Text.Trim() -and $ui.NdocHaToken.Password) { $opt.HaUrl = $ui.NdocHaUrl.Text.Trim(); $opt.HaToken = $ui.NdocHaToken.Password }
        $fns = @('Invoke-NdocCollect', 'Get-NdocPcInfo', 'Get-NdocWebTitles', 'Get-NdocWlanInfo', 'Invoke-NtSweep', 'Get-NtSubnetHosts', 'Get-NtIpSort', 'Get-NtRouterData', 'Get-NtHttpInfo', 'ConvertFrom-NtBoxInfo', 'Get-UpnpInfo', 'Get-WlanAdapter', 'Get-WlanIfInfo', 'Get-WlanDriverCaps', 'ConvertFrom-NtWlanText', 'Get-NdocSmartHome', 'Invoke-NdocMdns', 'Invoke-NdocSsdp', 'Invoke-NdocKnx', 'ConvertFrom-NdocKnxSearch', 'New-NdocUdp', 'Read-NdocDnsName', 'ConvertFrom-NdocMdns', 'Get-NdocHttp', 'Test-NdocMqttAnon', 'Get-FbServices', 'Invoke-FbSoap', 'Get-FbData', 'Get-NdocShodan', 'Get-NdocHomeAssistant', 'Get-NdocInfra', 'Invoke-NdocSnmpScan', 'New-NdocSnmpGet', 'ConvertFrom-NdocSnmp', 'Get-NdocTraceHops') + $script:NtNetFns
        Invoke-Bg -Script { param($p, $w, $s, $pl, $code, $sy, $o) Invoke-NdocCollect $p $w $s $pl $code $sy $o } -Arguments @([bool]$ui.NdocPorts.IsChecked, [bool]$ui.NdocWeb.IsChecked, [bool]$ui.NdocSmart.IsChecked, $NdocPorts, $NtTlsCode, $sync, $opt) -Functions $fns -Done {
            param($r, $err)
            $ui.BtnNdocScan.IsEnabled = $true
            $x = @($r | Where-Object { $_ -and $_.PSObject.Properties['Devices'] })[0]
            if ($err -or -not $x) { Stop-NtProgress $ui.NdocProg $ui.NdocState ('Erfassung fehlgeschlagen: ' + $(if ($err) { $err.Message } else { 'kein Ergebnis' })); return }
            try {
                $script:Ndoc = Complete-NdocResult $x $script:NtDevFile
                & $script:NdocShow
                $ui.BtnNdocPdf.IsEnabled = $true; $ui.BtnNdocAi.IsEnabled = $true
                Stop-NtProgress $ui.NdocProg $ui.NdocState ('Erfasst um ' + (Get-Date -Format 'HH:mm') + ' - jetzt "PDF-Bericht erstellen".')
            } catch { Stop-NtProgress $ui.NdocProg $ui.NdocState ('Auswertung fehlgeschlagen: ' + $_.Exception.Message) }
        }
    })
    $ui.BtnNdocPdf.Add_Click({
        if (-not $script:Ndoc) { return }
        try { & $script:NdocSaveSet } catch { }
        $pdf = $null
        try { $pdf = New-NdocPdf $script:Ndoc (Get-NdocMeta $ui.NdocTitle.Text.Trim() $ui.NdocSite.Text.Trim() $ui.NdocAuthor.Text.Trim()) $script:NdocDir $script:NdocKnxMon } catch { Show-UiError ('Bericht konnte nicht erstellt werden: ' + $_.Exception.Message); return }
        $ui.BtnNdocPdf.IsEnabled = $false
        $null = Start-NtProgress $ui.NdocProg $ui.NdocState 'PDF wird erstellt ...' -Indeterminate
        Invoke-Bg -Script { param($h, $o) Convert-HtmlToPdf $h $o } -Arguments @($pdf.Html, $pdf.Out) -Functions @('Convert-HtmlToPdf', 'Get-EdgePath') -Done {
            param($r, $err)
            $ui.BtnNdocPdf.IsEnabled = $true
            $f = [string]@($r | Where-Object { $_ })[-1]
            if ($err -or -not $f) { Stop-NtProgress $ui.NdocProg $ui.NdocState ('PDF fehlgeschlagen: ' + $(if ($err) { $err.Message } else { 'kein Ergebnis' })); return }
            Stop-NtProgress $ui.NdocProg $ui.NdocState ('Bericht gespeichert: ' + $f + $(if ($f -notmatch '\.pdf$') { ' (Edge fehlt - als HTML gespeichert, im Browser als PDF drucken)' } else { '' }))
            try { Start-Process $f } catch { }
        }
    })
    $ui.BtnNdocAi.Add_Click({
        if (-not $script:Ndoc) { return }
        $t = Get-AiNetReportText $script:Ndoc
        Open-AiAssistant
        $script:AiAttach.Add([pscustomobject]@{ Label = 'Netzwerk-Bericht'; Text = (Limit-AiText $t 12000) }); Update-AiAttachUi
        Send-AiQuestion 'Fasse diesen Netzwerk-Bericht in einfachen Worten zusammen (3-4 Sätze: Wie sicher ist das Netzwerk insgesamt?) und gib mir danach eine nummerierte Maßnahmenliste nach Wichtigkeit (Kritisch zuerst), jeweils mit dem konkreten Schritt und dem betroffenen Gerät.'
    })
    $ui.BtnNdocKnxMon.Add_Click({
        $net = $null; try { $net = Get-NtActiveNet } catch { }
        if (-not $net -or -not $net.Ip) { Show-UiError 'Kein aktiver Netzwerkadapter.'; return }
        $ui.BtnNdocKnxMon.IsEnabled = $false
        $null = Start-NtProgress $ui.NdocProg $ui.NdocState 'KNX-Busmonitor lauscht 60 Sekunden mit (sendet nichts) ...' -Indeterminate
        Invoke-Bg -Script { param($ip) Invoke-NdocKnxMonitor $ip 60 } -Arguments @($net.Ip) -Functions @('Invoke-NdocKnxMonitor') -Done {
            param($r, $err)
            $ui.BtnNdocKnxMon.IsEnabled = $true
            $m = @($r | Where-Object { $_ -and $_.PSObject.Properties['Frames'] })[0]
            if ($err -or -not $m) { Stop-NtProgress $ui.NdocProg $ui.NdocState ('KNX-Busmonitor fehlgeschlagen: ' + $(if ($err) { $err.Message } else { 'kein Ergebnis' })); return }
            $script:NdocKnxMon = $m
            Stop-NtProgress $ui.NdocProg $ui.NdocState $(if ($m.Frames) { 'KNX: {0} Telegramme, {1} Gruppenadressen, {2} sendende Geräte - kommt mit in den PDF-Bericht.' -f $m.Frames, @($m.Groups).Count, @($m.Devices).Count } else { 'KNX: keine Telegramme empfangen - nur mit KNX-IP-Router (Routing) möglich, Tunneling-Schnittstellen geben nichts ins Netz.' })
        }
    })
    $ui.BtnNdocLogo.Add_Click({
        Add-Type -AssemblyName System.Windows.Forms
        $d = New-Object System.Windows.Forms.OpenFileDialog; $d.Filter = 'Bilder (*.png;*.jpg;*.jpeg;*.svg;*.gif)|*.png;*.jpg;*.jpeg;*.svg;*.gif'
        if ($d.ShowDialog() -eq 'OK') { $ui.NdocLogo.Text = $d.FileName; try { & $script:NdocSaveSet } catch { } }
    })
    $ui.BtnNdocLogoClear.Add_Click({ $ui.NdocLogo.Text = ''; try { & $script:NdocSaveSet } catch { } })
    $ui.NdocAuto.Add_Click({
        try { $ui.NdocAutoState.Text = Register-NdocTask ([bool]$ui.NdocAuto.IsChecked); try { Copy-Item -LiteralPath $PSCommandPath -Destination (Join-Path $DataDir 'PCPflege.ps1') -Force -ErrorAction SilentlyContinue } catch { } }
        catch { $ui.NdocAutoState.Text = 'Fehler: ' + $_.Exception.Message; $ui.NdocAuto.IsChecked = -not $ui.NdocAuto.IsChecked }
    })
    $ui.BtnNdocEdit.Add_Click({
        $row = $ui.NdocDevGrid.SelectedItem; if (-not $row) { Show-UiError 'Bitte ein Gerät in der Liste auswählen.'; return }
        $res = Show-InputDialog 'Gerät beschreiben' ('{0} - {1}, {2}{3}' -f $row.Name, $row.Ip, $row.Mac, $(if ($row.Vendor) { ', ' + $row.Vendor } else { '' })) @(
            @{ Key = 'Name'; Label = 'Name (leer = automatisch)'; Type = 'Text'; Value = $(if ([string]$row.Name -notmatch '^\(') { ([string]$row.Name -replace '\s+\[.*$', '') } else { '' }) },
            @{ Key = 'Room'; Label = 'Raum / Standort'; Type = 'Text'; Value = $row.Room },
            @{ Key = 'Purpose'; Label = 'Zweck'; Type = 'Text'; Value = $row.Purpose },
            @{ Key = 'Owner'; Label = 'Verantwortlich'; Type = 'Text'; Value = $row.Owner },
            @{ Key = 'Note'; Label = 'Notiz'; Type = 'Text'; Value = $row.Note })
        if ($null -eq $res) { return }
        try {
            $inv = Get-NdocInventory; $inv[[string]$row.Key] = [pscustomobject]@{ Room = [string]$res.Room; Purpose = [string]$res.Purpose; Owner = [string]$res.Owner; Note = [string]$res.Note }
            Save-NdocJson 'inventar.json' ([pscustomobject]$inv)
            $st = Read-NtDevStore $script:NtDevFile
            if ($res.Name) { $st.Names | Add-Member -NotePropertyName $row.Key -NotePropertyValue $res.Name -Force } elseif ($st.Names.PSObject.Properties[$row.Key]) { $st.Names.PSObject.Properties.Remove($row.Key) }
            $st | ConvertTo-Json -Depth 5 | Set-Content -LiteralPath $script:NtDevFile -Encoding UTF8
            foreach ($k in 'Room', 'Purpose', 'Owner', 'Note') { $row.$k = [string]$res.$k }
            if ($res.Name) { $row.Name = $res.Name + $(if ($row.Gateway) { '  [Router]' } elseif ($row.Self) { '  [dieser PC]' } else { '' }) }
            $ui.NdocDevGrid.Items.Refresh()
        } catch { Show-UiError ('Speichern fehlgeschlagen: ' + $_.Exception.Message) }
    })
    $ui.BtnNdocCsv.Add_Click({
        if (-not $script:Ndoc) { $ui.NdocState.Text = 'Noch nichts erfasst.'; return }
        Add-Type -AssemblyName System.Windows.Forms
        $d = New-Object System.Windows.Forms.SaveFileDialog; $d.Filter = 'CSV für Excel (*.csv)|*.csv'; $d.FileName = 'Netzwerk-Inventar_{0:yyyy-MM-dd}.csv' -f (Get-Date)
        if ($d.ShowDialog() -ne 'OK') { return }
        try {
            @($script:Ndoc.Rows | ForEach-Object { [pscustomobject][ordered]@{ Name = ($_.Name -replace '\s+\[.*$', ''); Art = $_.Type; System = $_.System; IP = $_.Ip; MAC = $_.Mac; Hersteller = $_.Vendor; Anschluss = $_.Conn; Raum = $_.Room; Zweck = $_.Purpose; Verantwortlich = $_.Owner; Notiz = $_.Note; 'Offene Dienste' = $_.Ports; Status = $_.NewText; Hostname = $_.Host } }) | Export-Csv -LiteralPath $d.FileName -Delimiter ';' -NoTypeInformation -Encoding UTF8
            $ui.NdocState.Text = 'Gespeichert: ' + $d.FileName; try { Start-Process $d.FileName } catch { }
        } catch { Show-UiError ('CSV konnte nicht gespeichert werden: ' + $_.Exception.Message) }
    })
    $ui.BtnNdocFolder.Add_Click({ New-Item -Path $script:NdocDir -ItemType Directory -Force | Out-Null; Start-Process explorer.exe ('"{0}"' -f $script:NdocDir) })
    $ui.BtnNdocCopy.Add_Click({
        if (-not $script:Ndoc) { $ui.NdocState.Text = 'Noch nichts erfasst.'; return }
        $t = (@("Name`tArt`tIP`tMAC`tHersteller`tAnschluss`tRaum`tDienste`tStatus") + @($script:Ndoc.Rows | ForEach-Object { "{0}`t{1}`t{2}`t{3}`t{4}`t{5}`t{6}`t{7}`t{8}" -f $_.Name, $_.Type, $_.Ip, $_.Mac, $_.Vendor, $_.Conn, $_.Room, $_.Ports, $_.NewText })) -join "`r`n"
        try { [Windows.Clipboard]::SetText($t); $ui.NdocState.Text = 'Inventar kopiert (für Excel einfügen).' } catch { }
    })
}
if ($ui.DevFixOut) {
    $script:DevFns = @('Get-DevIssues', 'Get-DevIssueText', 'Get-DevBtSvcName', 'Get-DevProblemText', 'Disable-DevBtService', 'Remove-DevNode', 'Repair-DevIssues', 'Invoke-NdCmd', 'Get-SysExe')
    $ui.BtnDevCheck.Add_Click({
        if ($script:Job) { Show-UiError 'Es läuft bereits eine Aufgabe - bitte warten.'; return }
        $ui.DevFixState.Text = 'Geräte werden geprüft ...'; $ui.DevFixOut.Text = ''
        Invoke-Bg -Script { Get-DevIssueText } -Functions $script:DevFns -Done {
            param($r, $e)
            if ($e) { $ui.DevFixOut.Text = 'Fehler: ' + $e.Message } else { $ui.DevFixOut.Text = [string]@($r | Where-Object { $null -ne $_ })[-1] }
            $ui.DevFixState.Text = 'Prüfung fertig (' + (Get-Date -Format 'HH:mm:ss') + ')'
        }
    })
    $ui.BtnDevFix.Add_Click({
        if ($script:Job) { Show-UiError 'Es läuft bereits eine Aufgabe - bitte warten.'; return }
        if (-not (Confirm-Ui "Verwaiste Geräte-Einträge entfernen und Bluetooth-Dienste ohne Treiber für ihr Gerät ausschalten?`n`nEchte Geräte und ihre Treiber werden nicht angefasst. Ein ausgeschalteter Bluetooth-Dienst lässt sich jederzeit wieder einschalten: Systemsteuerung > Geräte und Drucker > Gerät > Eigenschaften > Dienste.")) { return }
        $ui.DevFixState.Text = 'Geräte werden repariert ...'; $ui.DevFixOut.Text = ''
        Invoke-Bg -Script { Repair-DevIssues } -Functions $script:DevFns -Done {
            param($r, $e)
            if ($e) { $ui.DevFixOut.Text = 'Fehler: ' + $e.Message }
            else {
                $x = @($r | Where-Object { $null -ne $_ })[-1]
                $ui.DevFixOut.Text = [string]$x.Text
                if ($x.OpenCpl) { try { Start-Process (Join-Path $env:windir 'System32\control.exe') 'printers' } catch { } }
            }
            $ui.DevFixState.Text = 'Reparatur fertig (' + (Get-Date -Format 'HH:mm:ss') + ')'
        }
    })
    $ui.BtnDevCopy.Add_Click({ $t = [string]$ui.DevFixOut.Text; if (-not $t.Trim()) { $ui.DevFixState.Text = 'Noch nichts zum Kopieren - bitte erst "Geräte prüfen".'; return }; try { [Windows.Clipboard]::SetText($t); $ui.DevFixState.Text = 'Protokoll in die Zwischenablage kopiert.' } catch { $ui.DevFixState.Text = 'Kopieren fehlgeschlagen.' } })
}
if ($ui.SvcFixOut) {
    $ui.BtnSvcCheck.Add_Click({
        if ($script:Job) { Show-UiError 'Es läuft bereits eine Aufgabe - bitte warten.'; return }
        $ui.SvcFixState.Text = 'Dienste werden geprüft ... (dauert nur wenige Sekunden)'; $ui.SvcFixOut.Text = ''
        Invoke-Bg -Script { Get-StuckSvcText } -Functions @('Get-StuckSvcText', 'Get-SvcTriggerMap', 'Get-SvcHostGroupMap', 'Get-SvcHostGroupsFor', 'Get-SvcHostGroupOf', 'Get-SvcHostGroupFix') -Done {
            param($r, $e)
            if ($e) { $ui.SvcFixOut.Text = 'Fehler: ' + $e.Message } else { $ui.SvcFixOut.Text = [string]@($r | Where-Object { $null -ne $_ })[-1] }
            $ui.SvcFixState.Text = 'Prüfung fertig (' + (Get-Date -Format 'HH:mm:ss') + ')'
        }
    })
    $ui.BtnSvcFix.Add_Click({
        if ($script:Job) { Show-UiError 'Es läuft bereits eine Aufgabe - bitte warten.'; return }
        if (-not (Confirm-Ui 'Nicht startende Kerndienste auf die Windows-Vorgabe setzen und in der richtigen Reihenfolge starten? (Bei Problemen hilft danach der Wiederherstellungspunkt der letzten Pflege.)')) { return }
        $ui.SvcFixState.Text = 'Dienste werden repariert ... (dauert i.d.R. unter einer Minute)'; $ui.SvcFixOut.Text = ''
        Invoke-Bg -Script { param($c) Repair-StuckSvcText $c } -Arguments @(, @($WrCoreSvcDefaults)) -Functions @('Repair-StuckSvcText', 'Get-SvcTriggerMap', 'Start-SvcNonBlocking', 'Get-SvcHostGroupMap', 'Get-SvcHostGroupsFor', 'Get-SvcHostGroupOf', 'Get-SvcHostGroupFix') -Done {
            param($r, $e)
            if ($e) { $ui.SvcFixOut.Text = 'Fehler: ' + $e.Message } else { $ui.SvcFixOut.Text = [string]@($r | Where-Object { $null -ne $_ })[-1] }
            $ui.SvcFixState.Text = 'Reparatur fertig (' + (Get-Date -Format 'HH:mm:ss') + ')'
        }
    })
    $ui.BtnSvcCopy.Add_Click({ $t = [string]$ui.SvcFixOut.Text; if (-not $t.Trim()) { $ui.SvcFixState.Text = 'Noch nichts zum Kopieren - bitte erst "Dienste prüfen".'; return }; try { [Windows.Clipboard]::SetText($t); $ui.SvcFixState.Text = 'Protokoll in die Zwischenablage kopiert.' } catch { $ui.SvcFixState.Text = 'Kopieren fehlgeschlagen.' } })
}
foreach ($k in $RepPresets.Keys) { $ui['BtnRep' + $k].Tag = $k; $ui['BtnRep' + $k].Add_Click({ param($s, $e) Set-RepSelection $RepPresets[[string]$s.Tag] }) }
$ui.BtnRepNone.Add_Click({ Set-RepSelection @() })
$ui.BtnRepRun.Add_Click({ Start-Repair })
$ui.BtnRepSource.Add_Click({ Add-Type -AssemblyName System.Windows.Forms; $d = New-Object System.Windows.Forms.OpenFileDialog; $d.Filter = 'Windows-ISO oder Abbild (*.iso;*.wim;*.esd)|*.iso;*.wim;*.esd'; if ($d.ShowDialog() -eq 'OK') { $ui.RepSource.Text = $d.FileName } })
$ui.BtnRpRefresh.Add_Click({ Update-RestorePoints })
$ui.BtnRpRstrui.Add_Click({ Start-Tool 'rstrui.exe' })
$ui.BtnRpCreate.Add_Click({
    $ui.StatusText.Text = 'Wiederherstellungspunkt wird erstellt ...'
    Invoke-Bg -Script {
        New-ItemProperty -Path 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\SystemRestore' -Name 'SystemRestorePointCreationFrequency' -Value 0 -PropertyType DWord -Force | Out-Null
        try { Enable-ComputerRestore -Drive ($env:SystemDrive + '\') -ErrorAction SilentlyContinue } catch { }
        Checkpoint-Computer -Description ('PC-Tools manuell {0:dd.MM.yyyy HH:mm}' -f (Get-Date)) -RestorePointType MODIFY_SETTINGS -ErrorAction Stop
    } -Done { param($r, $err) if ($err) { Show-UiError ('Nicht möglich: ' + $err.Message) } else { $ui.StatusText.Text = 'Wiederherstellungspunkt erstellt.' }; Update-RestorePoints }
})
$ui.BtnRpRestore.Add_Click({
    $r = $ui.RepPoints.SelectedItem
    if (-not $r) { Show-UiError 'Bitte einen Wiederherstellungspunkt auswählen.'; return }
    if (-not (Confirm-Ui ("Windows auf den Stand vom {0} zurücksetzen?`n`"{1}`"`n`nDer PC startet dafür SOFORT neu. Eigene Dateien bleiben, danach installierte Programme und Treiber sind weg. Alles speichern!" -f $r.Date, $r.Desc) 'Warning')) { return }
    try { Restore-Computer -RestorePoint $r.Seq -Confirm:$false -ErrorAction Stop } catch { Show-UiError $_.Exception.Message }
})
$script:RepLoaded = $false
$ui.Tabs.Add_SelectionChanged({
    param($s, $e)
    if ($e.OriginalSource -ne $s -or $s.SelectedItem -ne $ui.TabRepair -or $script:RepLoaded) { return }
    $script:RepLoaded = $true; Build-RepGroups; Build-RepTools; try { Update-RestorePoints } catch { }
})

