$script:PwrLoaded = $false
$ui.BtnPwrAbort.Add_Click({ $o = & shutdown.exe /a 2>&1; $ui.StatusText.Text = $(if ($LASTEXITCODE -eq 0) { 'Geplanter Neustart/Herunterfahren abgebrochen.' } else { 'Es war nichts geplant.' }) })
$ui.BtnPwrSafeOff.Add_Click({
    $null = & $BcdExe /deletevalue '{current}' safeboot 2>&1; $null = & $BcdExe /deletevalue '{current}' safebootalternateshell 2>&1
    Remove-ItemProperty -Path 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\RunOnce' -Name '*PCPflegeSafeModeOff' -ErrorAction SilentlyContinue
    $ui.StatusText.Text = 'Abgesicherter Modus ist aus - der nächste Start ist wieder normal.'; Update-PowerInfo
})
