$ui.BtnBkAddFolder.Add_Click({ Add-Type -AssemblyName System.Windows.Forms; $d = New-Object System.Windows.Forms.FolderBrowserDialog; if ($d.ShowDialog() -eq 'OK') { Add-BkSource $d.SelectedPath } })
$ui.BtnBkRemove.Add_Click({ $s = $ui.BkSourceList.SelectedItem; if ($s) { $ui.BkSourceList.Items.Remove($s); Sync-BkSources } })
