    if (-not $u) { Remove-Item -LiteralPath $BackupCredFile -Force -ErrorAction SilentlyContinue; Update-BkInfo; return }
    try { Save-BackupCred $u $p; $ui.BkNasPwd.Password = ''; Save-PflegeConfig (Get-ConfigFromUi); Update-BkInfo } catch { Show-UiError $_.Exception.Message }
})
$ui.BtnBkTest.Add_Click({
    $t = $ui.Backup_Target.Text.Trim(); if (-not $t) { return }
    $window.Cursor = 'Wait'
    try {
        Connect-BackupTarget $t
        if (-not (Test-Path -LiteralPath $t)) { New-Item $t -ItemType Directory -Force -ErrorAction Stop | Out-Null }
        $f = Join-Path $t ('pcpflege_test_{0}.tmp' -f $PID); Set-Content -LiteralPath $f -Value 'Test' -ErrorAction Stop; Remove-Item -LiteralPath $f -Force
        $ui.BkTargetInfo.Text = 'Ziel erreichbar und beschreibbar.'; $ui.BkTargetInfo.Foreground = $Brush.Green
    } catch { $ui.BkTargetInfo.Text = 'Ziel nicht nutzbar: ' + $_.Exception.Message; $ui.BkTargetInfo.Foreground = $Brush.Red }
    finally { $window.Cursor = $null }
})
$ui.BtnBkRun.Add_Click({ Sync-BkSources; if (-not $ui.Backup_Sources.Text) { Show-UiError 'Bitte zuerst Ordner zum Sichern hinzufügen.'; return }; if (-not $ui.Backup_Target.Text.Trim()) { Show-UiError 'Bitte ein Sicherungsziel angeben.'; return }; $null = Save-All -Quiet; Start-Run -Parts @('Backup') })
