})
$ui.BtnBkOpen.Add_Click({ $t = Join-Path $ui.Backup_Target.Text.Trim() $env:COMPUTERNAME; if (Test-Path -LiteralPath $t) { Start-Process explorer.exe ('"{0}"' -f $t) } else { Show-UiError 'Noch keine Sicherung am Ziel vorhanden.' } })
$ui.BtnBkImageList.Add_Click({
