$ui.BtnMigPwWipe.Add_Click({
    if (-not $script:MigPwDir) { return }
    if (-not (Confirm-Ui ("Alle Kennwort-Dateien (CSV) in`n{0}`nüberschreiben und löschen? Vorher in allen Browsern importieren!" -f $script:MigPwDir) 'Warning')) { return }
    foreach ($f in @(Get-ChildItem -LiteralPath $script:MigPwDir -Filter *.csv -File -ErrorAction SilentlyContinue)) { Remove-FileSecure $f.FullName }
    if (-not @(Get-ChildItem -LiteralPath $script:MigPwDir -Force -ErrorAction SilentlyContinue).Count) { Remove-Item -LiteralPath $script:MigPwDir -Force -ErrorAction SilentlyContinue }
    $ui.StatusText.Text = 'Kennwort-Dateien gelöscht.'; Update-MigPwImport $ui.MigPackage.Text.Trim()
})
