$ui.Tabs.Add_SelectionChanged({
    param($s, $e)
    if ($e.OriginalSource -ne $s) { return }
    if ($s.SelectedItem -eq $ui.TabBackup) { Load-BkSources; if (-not $ui.BkSourceList.Items.Count) { foreach ($f in (Get-KnownFolders)) { if ($f.Path -notlike '\\*') { Add-BkSource $f.Path } } }; Update-BkInfo }
    elseif ($s.SelectedItem -eq $ui.TabMigrate) { if (-not $ui.MigFolders.Children.Count) { Build-MigFolders; Build-MigPwButtons } else { Update-MigPwInfo } }
})

