# Vorhandene Verknüpfungen einmalig auf "ohne PowerShell-Fenster" umstellen
$lnkMarker = Join-Path $DataDir 'shortcuts.v52'
if (-not $Script:IsPortable -and -not (Test-Path -LiteralPath $lnkMarker)) {
    foreach ($w in 'Desktop', 'Public', 'StartMenu') { if (Test-Path -LiteralPath (Get-ShortcutPath $w)) { try { $null = New-PflegeShortcut $w } catch { } } }
    try {
        $sh = New-Object -ComObject WScript.Shell
        foreach ($dir in @([Environment]::GetFolderPath('Desktop'), [Environment]::GetFolderPath('CommonDesktopDirectory'))) {
            foreach ($f in @(Get-ChildItem -LiteralPath $dir -Filter '*.lnk' -ErrorAction SilentlyContinue)) {
                $sc = $sh.CreateShortcut($f.FullName)
                if ($sc.TargetPath -match 'powershell\.exe$' -and $sc.Arguments -match 'PCPflege\.ps1"\s+(-Monitor|-DeskArrange|-Topology)(.*)$') {
                    Set-HiddenShortcut $sc (Join-Path $DataDir 'PCPflege.ps1') ($Matches[1] + $Matches[2]); $sc.Save()
                }
            }
        }
        [void][Runtime.InteropServices.Marshal]::ReleaseComObject($sh)
    } catch { }
    try { Set-Content -LiteralPath $lnkMarker -Value (Get-Date).ToString('o') } catch { }
}
